import React, { useState, useEffect } from "react";
import {
  ClockIcon,
  UserIcon,
  BriefcaseIcon,
  XMarkIcon,
  ArrowPathIcon,
  ArrowTopRightOnSquareIcon,
} from "@heroicons/react/24/outline";
import { useNavigate } from "react-router-dom";
import { useTheme } from "../hooks/useTheme";
import tokenManager from "../utils/tokenManager";
import { buildApiUrl } from "../utils/urlHelper";

const ActiveUsersMonitor = ({ isOpen, onClose }) => {
  const navigate = useNavigate();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const [activeUsers, setActiveUsers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [stoppingTimer, setStoppingTimer] = useState(null);
  const getAccessToken = () => tokenManager.getAccessToken();

  const themeColors = {
    bg: isDark ? "bg-slate-800" : "bg-white",
    border: isDark ? "border-slate-700" : "border-gray-200",
    text: isDark ? "text-white" : "text-gray-900",
    subText: isDark ? "text-gray-400" : "text-gray-600",
    mutedBg: isDark ? "bg-slate-700/50" : "bg-gray-50",
    hoverBg: isDark ? "hover:bg-slate-700" : "hover:bg-gray-50",
  };

  // Combined effect with Page Visibility API for better performance
  useEffect(() => {
    if (!isOpen) return;

    // Fetch immediately when opened
    fetchActiveUsers();

    // Handle visibility changes - pause updates when tab is hidden
    const handleVisibilityChange = () => {
      if (!document.hidden && isOpen) {
        fetchActiveUsers();
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);

    // Update current time every second (only when visible)
    const timerInterval = setInterval(() => {
      if (!document.hidden) {
        setCurrentTime(new Date());
      }
    }, 1000);

    // Refresh data every 30 seconds (only when visible)
    const refreshInterval = setInterval(() => {
      if (!document.hidden && isOpen) {
        fetchActiveUsers();
      }
    }, 30000);

    // Cleanup function
    return () => {
      clearInterval(timerInterval);
      clearInterval(refreshInterval);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [isOpen]); // Only re-run when isOpen changes

  const fetchActiveUsers = async () => {
    try {
      setLoading(true);
      setError(null);
      const token = getAccessToken();

      if (!token) {
        setLoading(false);
        return;
      }

      const response = await fetch(buildApiUrl("admin/active-users"), {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) {
        // Silently fail on 401 - user not authenticated yet
        if (response.status === 401) {
          setActiveUsers([]);
          setLoading(false);
          return;
        }
        throw new Error("فشل في جلب البيانات");
      }

      const result = await response.json();
      setActiveUsers(result.data?.activeUsers || []);
    } catch (err) {
      // Only show error if it's not a network/auth issue
      if (err.message !== "فشل في جلب البيانات") {
        setError(err.message);
      }
      setActiveUsers([]);
    } finally {
      setLoading(false);
    }
  };

  const calculateLiveDuration = (startTime) => {
    const start = new Date(startTime);
    const duration = Math.floor((currentTime - start) / 1000);
    const hours = Math.floor(duration / 3600);
    const minutes = Math.floor((duration % 3600) / 60);
    const seconds = duration % 60;
    return `${hours.toString().padStart(2, "0")}:${minutes.toString().padStart(2, "0")}:${seconds.toString().padStart(2, "0")}`;
  };

  const getPriorityColor = (priority) => {
    const colors = {
      URGENT: "text-red-600 bg-red-100",
      HIGH: "text-orange-600 bg-orange-100",
      MEDIUM: "text-yellow-600 bg-yellow-100",
      LOW: "text-blue-600 bg-blue-100",
    };
    return colors[priority] || "text-gray-600 bg-gray-100";
  };

  const getStatusColor = (status) => {
    const colors = {
      TODO: "text-gray-600 bg-gray-100",
      IN_PROGRESS: "text-blue-600 bg-blue-100",
      IN_REVIEW: "text-purple-600 bg-purple-100",
      DONE: "text-green-600 bg-green-100",
      BLOCKED: "text-red-600 bg-red-100",
    };
    return colors[status] || "text-gray-600 bg-gray-100";
  };

  const handleTaskClick = async (taskId, entryId) => {
    try {
      setStoppingTimer(entryId);
      const token = getAccessToken();

      if (!token) {
        console.error("No token found");
        return;
      }

      const response = await fetch(
        buildApiUrl(`super-admin/dev/tasks/${taskId}/timer/stop`),
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ timerId: entryId }),
        },
      );

      if (response.ok) {
        onClose();
        navigate(`/super-admin/dev-tasks/${taskId}`);
      } else {
        console.error("Failed to stop timer");
      }
    } catch (err) {
      console.error("Error stopping timer:", err);
    } finally {
      setStoppingTimer(null);
    }
  };

  const handleStopTimerOnly = async (taskId, entryId) => {
    try {
      setStoppingTimer(entryId);
      const token = getAccessToken();

      if (!token) return;

      const response = await fetch(
        buildApiUrl(`super-admin/dev/tasks/${taskId}/timer/stop`),
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ timerId: entryId, description: "" }),
        },
      );

      if (response.ok) {
        // Refresh list instead of navigating
        fetchActiveUsers();
      } else {
        console.error("Failed to stop timer");
      }
    } catch (err) {
      console.error("Error stopping timer:", err);
    } finally {
      setStoppingTimer(null);
    }
  };

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-start justify-center pt-20"
      onClick={onClose}
    >
      <div
        className={`${themeColors.bg} rounded-2xl shadow-2xl border ${themeColors.border} w-full max-w-4xl mx-4 max-h-[80vh] overflow-hidden`}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div
          className={`flex items-center justify-between p-6 border-b ${themeColors.border}`}
        >
          <div className="flex items-center gap-3">
            <div className="p-2 bg-green-500/10 rounded-lg">
              <ClockIcon className="h-6 w-6 text-green-600" />
            </div>
            <div>
              <h2 className={`text-xl font-bold ${themeColors.text}`}>
                المستخدمون النشطون
              </h2>
              <p className={`text-sm ${themeColors.subText}`}>
                {activeUsers.length} مستخدم يعمل الآن
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={fetchActiveUsers}
              disabled={loading}
              className={`p-2 ${themeColors.hoverBg} rounded-lg transition-colors ${loading ? "opacity-50 cursor-not-allowed" : ""}`}
              title="تحديث"
            >
              <ArrowPathIcon
                className={`h-5 w-5 ${themeColors.text} ${loading ? "animate-spin" : ""}`}
              />
            </button>
            <button
              onClick={onClose}
              className={`p-2 ${themeColors.hoverBg} rounded-lg transition-colors`}
            >
              <XMarkIcon className={`h-5 w-5 ${themeColors.text}`} />
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="overflow-y-auto max-h-[calc(80vh-100px)] p-6">
          {loading && activeUsers.length === 0 ? (
            <div className="flex justify-center items-center py-12">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-green-500"></div>
            </div>
          ) : error ? (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-center">
              <p className="text-red-600">{error}</p>
            </div>
          ) : activeUsers.length === 0 ? (
            <div
              className={`${themeColors.mutedBg} rounded-lg p-12 text-center`}
            >
              <ClockIcon
                className={`h-16 w-16 mx-auto mb-4 ${themeColors.subText} opacity-50`}
              />
              <p className={`text-lg ${themeColors.text}`}>
                لا يوجد مستخدمون نشطون حالياً
              </p>
              <p className={`text-sm ${themeColors.subText} mt-2`}>
                سيظهر هنا المستخدمون الذين يشغلون التيمر
              </p>
            </div>
          ) : (
            <div className="space-y-4">
              {activeUsers.map((entry) => (
                <div
                  key={entry.id}
                  className={`${themeColors.mutedBg} rounded-xl p-5 border ${themeColors.border} transition-all relative group`}
                >
                  <div className="flex items-start justify-between gap-4">
                    {/* User Info */}
                    <div className="flex items-start gap-3 flex-1">
                      <div className="relative">
                        {entry.user.avatar ? (
                          <img
                            src={entry.user.avatar}
                            alt={entry.user.name}
                            className="h-12 w-12 rounded-full object-cover"
                          />
                        ) : (
                          <div className="h-12 w-12 rounded-full bg-gradient-to-br from-green-400 to-blue-500 flex items-center justify-center">
                            <UserIcon className="h-6 w-6 text-white" />
                          </div>
                        )}
                        <div className="absolute -bottom-1 -right-1 h-4 w-4 bg-green-500 rounded-full border-2 border-white animate-pulse"></div>
                      </div>

                      <div className="flex-1 min-w-0">
                        <h3
                          className={`font-semibold ${themeColors.text} truncate`}
                        >
                          {entry.user.name}
                        </h3>
                        <p
                          className={`text-sm ${themeColors.subText} truncate`}
                        >
                          {entry.user.email}
                        </p>
                        <div className="flex items-center gap-2 mt-1">
                          <BriefcaseIcon
                            className={`h-4 w-4 ${themeColors.subText}`}
                          />
                          <span
                            className={`text-xs ${themeColors.subText} capitalize`}
                          >
                            {entry.user.role}
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Timer */}
                    <div className="text-left">
                      <div className="flex items-center gap-2 bg-green-500/10 px-4 py-2 rounded-lg">
                        <ClockIcon className="h-5 w-5 text-green-600" />
                        <span className="text-xl font-mono font-bold text-green-600 tabular-nums">
                          {calculateLiveDuration(entry.startTime)}
                        </span>
                      </div>
                      <p
                        className={`text-xs ${themeColors.subText} mt-1 text-center`}
                      >
                        منذ{" "}
                        {new Date(entry.startTime).toLocaleTimeString("ar-EG", {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </p>
                    </div>
                  </div>

                  {/* Task Info */}
                  <div className={`mt-4 pt-4 border-t ${themeColors.border}`}>
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1 min-w-0">
                        <p
                          className={`text-sm font-medium ${themeColors.text} mb-2`}
                        >
                          {entry.task.title}
                        </p>
                        {entry.description && (
                          <p
                            className={`text-xs ${themeColors.subText} line-clamp-2`}
                          >
                            {entry.description}
                          </p>
                        )}
                      </div>
                      <div className="flex gap-2">
                        <span
                          className={`text-xs px-2 py-1 rounded-full ${getPriorityColor(entry.task.priority)}`}
                        >
                          {entry.task.priority}
                        </span>
                        <span
                          className={`text-xs px-2 py-1 rounded-full ${getStatusColor(entry.task.status)}`}
                        >
                          {entry.task.status}
                        </span>
                      </div>
                    </div>

                    {/* Action Buttons */}
                    <div className="mt-3 flex justify-end gap-2">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleStopTimerOnly(entry.task.id, entry.id);
                        }}
                        disabled={stoppingTimer === entry.id}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all ${stoppingTimer === entry.id
                            ? "bg-gray-200 text-gray-400 cursor-not-allowed"
                            : "bg-red-50 text-red-600 hover:bg-red-100 hover:shadow-sm border border-red-200"
                          }`}
                      >
                        {stoppingTimer === entry.id ? (
                          <>
                            <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-red-600"></div>
                            <span>جاري الإيقاف...</span>
                          </>
                        ) : (
                          <>
                            <XMarkIcon className="h-4 w-4" />
                            <span>إيقاف التايمر</span>
                          </>
                        )}
                      </button>

                      <button
                        onClick={() => {
                          onClose();
                          navigate(`/super-admin/dev-tasks/${entry.task.id}`);
                        }}
                        className="flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all bg-blue-500 hover:bg-blue-600 text-white shadow-md hover:shadow-lg"
                      >
                        <ArrowTopRightOnSquareIcon className="h-4 w-4" />
                        <span>فتح المهمة</span>
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ActiveUsersMonitor;

import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Switch,
  FormControlLabel,
  Alert,
  CircularProgress,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
} from "@mui/material";
import Grid from "@mui/material/GridLegacy";
import {
  Add,
  Edit,
  Delete,
  ArrowUpward,
  ArrowDownward,
  ThumbUp,
  ThumbDown,
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";

interface FAQ {
  id: string;
  question: string;
  answer: string;
  category: string;
  tags: string[];
  order: number;
  helpful: number;
  notHelpful: number;
  isActive: boolean;
  version: number;
  createdAt: string;
  updatedAt: string;
}

const FAQManagement: React.FC = () => {
  const [faqs, setFaqs] = useState<FAQ[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingFaq, setEditingFaq] = useState<FAQ | null>(null);
  const [formData, setFormData] = useState({
    question: "",
    answer: "",
    category: "general",
    tags: "",
    isActive: true,
  });

  useEffect(() => {
    loadFAQs();
  }, []);

  const loadFAQs = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await apiClient.get("/faqs");
      setFaqs(response.data);
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحميل الأسئلة الشائعة");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      const data = {
        ...formData,
        tags: formData.tags
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean),
      };

      if (editingFaq) {
        await apiClient.put(`/faqs/${editingFaq.id}`, data);
        setSuccess("تم تحديث السؤال بنجاح");
      } else {
        await apiClient.post("/faqs", data);
        setSuccess("تم إضافة السؤال بنجاح");
      }

      setDialogOpen(false);
      resetForm();
      loadFAQs();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل حفظ السؤال");
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا السؤال؟")) return;

    try {
      await apiClient.delete(`/faqs/${id}`);
      setSuccess("تم حذف السؤال بنجاح");
      loadFAQs();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل حذف السؤال");
    }
  };

  const handleToggleActive = async (faq: FAQ) => {
    try {
      await apiClient.put(`/faqs/${faq.id}`, { isActive: !faq.isActive });
      setSuccess(`تم ${!faq.isActive ? "تفعيل" : "تعطيل"} السؤال بنجاح`);
      loadFAQs();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحديث حالة السؤال");
    }
  };

  const handleReorder = async (faq: FAQ, direction: "up" | "down") => {
    try {
      const newOrder = direction === "up" ? faq.order - 1 : faq.order + 1;
      await apiClient.put(`/faqs/${faq.id}`, { order: newOrder });
      loadFAQs();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل إعادة الترتيب");
    }
  };

  const openEditDialog = (faq: FAQ) => {
    setEditingFaq(faq);
    setFormData({
      question: faq.question,
      answer: faq.answer,
      category: faq.category,
      tags: faq.tags.join(", "),
      isActive: faq.isActive,
    });
    setDialogOpen(true);
  };

  const resetForm = () => {
    setEditingFaq(null);
    setFormData({
      question: "",
      answer: "",
      category: "general",
      tags: "",
      isActive: true,
    });
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h4">إدارة الأسئلة الشائعة</Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => {
            resetForm();
            setDialogOpen(true);
          }}
        >
          إضافة سؤال جديد
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}
      {success && (
        <Alert
          severity="success"
          sx={{ mb: 2 }}
          onClose={() => setSuccess(null)}
        >
          {success}
        </Alert>
      )}

      {loading ? (
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      ) : (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>الترتيب</TableCell>
                <TableCell>السؤال</TableCell>
                <TableCell>الفئة</TableCell>
                <TableCell>التقييم</TableCell>
                <TableCell>الحالة</TableCell>
                <TableCell>الإصدار</TableCell>
                <TableCell>الإجراءات</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {faqs.map((faq) => (
                <TableRow key={faq.id}>
                  <TableCell>
                    <Box display="flex" alignItems="center">
                      <IconButton
                        size="small"
                        onClick={() => handleReorder(faq, "up")}
                        disabled={faq.order === 0}
                      >
                        <ArrowUpward fontSize="small" />
                      </IconButton>
                      <Typography sx={{ mx: 1 }}>{faq.order}</Typography>
                      <IconButton
                        size="small"
                        onClick={() => handleReorder(faq, "down")}
                      >
                        <ArrowDownward fontSize="small" />
                      </IconButton>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" fontWeight="bold">
                      {faq.question}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {faq.answer.substring(0, 100)}...
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip label={faq.category} size="small" />
                  </TableCell>
                  <TableCell>
                    <Box display="flex" alignItems="center" gap={1}>
                      <Box display="flex" alignItems="center">
                        <ThumbUp fontSize="small" color="success" />
                        <Typography variant="caption" ml={0.5}>
                          {faq.helpful}
                        </Typography>
                      </Box>
                      <Box display="flex" alignItems="center">
                        <ThumbDown fontSize="small" color="error" />
                        <Typography variant="caption" ml={0.5}>
                          {faq.notHelpful}
                        </Typography>
                      </Box>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Switch
                      checked={faq.isActive}
                      onChange={() => handleToggleActive(faq)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={`v${faq.version}`}
                      size="small"
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>
                    <IconButton
                      size="small"
                      onClick={() => openEditDialog(faq)}
                    >
                      <Edit fontSize="small" />
                    </IconButton>
                    <IconButton
                      size="small"
                      color="error"
                      onClick={() => handleDelete(faq.id)}
                    >
                      <Delete fontSize="small" />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <Dialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {editingFaq ? "تعديل السؤال" : "إضافة سؤال جديد"}
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12}>
              <TextField
                label="السؤال"
                fullWidth
                multiline
                rows={2}
                value={formData.question}
                onChange={(e) =>
                  setFormData({ ...formData, question: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="الإجابة"
                fullWidth
                multiline
                rows={4}
                value={formData.answer}
                onChange={(e) =>
                  setFormData({ ...formData, answer: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>الفئة</InputLabel>
                <Select
                  value={formData.category}
                  label="الفئة"
                  onChange={(e) =>
                    setFormData({ ...formData, category: e.target.value })
                  }
                >
                  <MenuItem value="general">عام</MenuItem>
                  <MenuItem value="shipping">الشحن</MenuItem>
                  <MenuItem value="payment">الدفع</MenuItem>
                  <MenuItem value="returns">الإرجاع</MenuItem>
                  <MenuItem value="products">المنتجات</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                label="الوسوم (مفصولة بفواصل)"
                fullWidth
                value={formData.tags}
                onChange={(e) =>
                  setFormData({ ...formData, tags: e.target.value })
                }
                placeholder="شحن, توصيل, سريع"
              />
            </Grid>
            <Grid item xs={12}>
              <FormControlLabel
                control={
                  <Switch
                    checked={formData.isActive}
                    onChange={(e) =>
                      setFormData({ ...formData, isActive: e.target.checked })
                    }
                  />
                }
                label="نشط"
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>إلغاء</Button>
          <Button
            variant="contained"
            onClick={handleSave}
            disabled={!formData.question || !formData.answer}
          >
            حفظ
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default FAQManagement;

import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Switch,
  FormControlLabel,
  Alert,
  CircularProgress,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
} from "@mui/material";
import Grid from "@mui/material/GridLegacy";
import { Add, Edit, Delete, Visibility, Schedule } from "@mui/icons-material";
import { DateTimePicker } from "@mui/x-date-pickers/DateTimePicker";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { apiClient } from "../../services/apiClient";

interface Policy {
  id: string;
  title: string;
  content: string;
  category: string;
  tags: string[];
  order: number;
  isActive: boolean;
  version: number;
  effectiveAt: string;
  expiresAt: string | null;
  createdAt: string;
  updatedAt: string;
}

const PolicyManagement: React.FC = () => {
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [editingPolicy, setEditingPolicy] = useState<Policy | null>(null);
  const [viewingPolicy, setViewingPolicy] = useState<Policy | null>(null);
  const [formData, setFormData] = useState({
    title: "",
    content: "",
    category: "general",
    tags: "",
    isActive: true,
    effectiveAt: new Date(),
    expiresAt: null as Date | null,
  });

  useEffect(() => {
    loadPolicies();
  }, []);

  const loadPolicies = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await apiClient.get("/policies");
      setPolicies(response.data);
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحميل السياسات");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      const data = {
        ...formData,
        tags: formData.tags
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean),
        effectiveAt: formData.effectiveAt.toISOString(),
        expiresAt: formData.expiresAt ? formData.expiresAt.toISOString() : null,
      };

      if (editingPolicy) {
        await apiClient.put(`/policies/${editingPolicy.id}`, data);
        setSuccess("تم تحديث السياسة بنجاح");
      } else {
        await apiClient.post("/policies", data);
        setSuccess("تم إضافة السياسة بنجاح");
      }

      setDialogOpen(false);
      resetForm();
      loadPolicies();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل حفظ السياسة");
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذه السياسة؟")) return;

    try {
      await apiClient.delete(`/policies/${id}`);
      setSuccess("تم حذف السياسة بنجاح");
      loadPolicies();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل حذف السياسة");
    }
  };

  const handleToggleActive = async (policy: Policy) => {
    try {
      await apiClient.put(`/policies/${policy.id}`, {
        isActive: !policy.isActive,
      });
      setSuccess(`تم ${!policy.isActive ? "تفعيل" : "تعطيل"} السياسة بنجاح`);
      loadPolicies();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحديث حالة السياسة");
    }
  };

  const openEditDialog = (policy: Policy) => {
    setEditingPolicy(policy);
    setFormData({
      title: policy.title,
      content: policy.content,
      category: policy.category,
      tags: policy.tags.join(", "),
      isActive: policy.isActive,
      effectiveAt: new Date(policy.effectiveAt),
      expiresAt: policy.expiresAt ? new Date(policy.expiresAt) : null,
    });
    setDialogOpen(true);
  };

  const resetForm = () => {
    setEditingPolicy(null);
    setFormData({
      title: "",
      content: "",
      category: "general",
      tags: "",
      isActive: true,
      effectiveAt: new Date(),
      expiresAt: null,
    });
  };

  const getCategoryColor = (category: string) => {
    const colors: Record<string, any> = {
      shipping: "primary",
      return: "secondary",
      refund: "warning",
      privacy: "info",
      terms: "default",
    };
    return colors[category] || "default";
  };

  const isExpired = (policy: Policy) => {
    return policy.expiresAt && new Date(policy.expiresAt) < new Date();
  };

  const isNotYetEffective = (policy: Policy) => {
    return new Date(policy.effectiveAt) > new Date();
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h4">إدارة السياسات</Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => {
            resetForm();
            setDialogOpen(true);
          }}
        >
          إضافة سياسة جديدة
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}
      {success && (
        <Alert
          severity="success"
          sx={{ mb: 2 }}
          onClose={() => setSuccess(null)}
        >
          {success}
        </Alert>
      )}

      {loading ? (
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      ) : (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>العنوان</TableCell>
                <TableCell>الفئة</TableCell>
                <TableCell>تاريخ السريان</TableCell>
                <TableCell>تاريخ الانتهاء</TableCell>
                <TableCell>الحالة</TableCell>
                <TableCell>الإصدار</TableCell>
                <TableCell>الإجراءات</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {policies.map((policy) => (
                <TableRow
                  key={policy.id}
                  sx={{
                    bgcolor: isExpired(policy)
                      ? "error.lighter"
                      : isNotYetEffective(policy)
                        ? "warning.lighter"
                        : "inherit",
                  }}
                >
                  <TableCell>
                    <Typography variant="body2" fontWeight="bold">
                      {policy.title}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {policy.content.substring(0, 80)}...
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={policy.category}
                      size="small"
                      color={getCategoryColor(policy.category)}
                    />
                  </TableCell>
                  <TableCell>
                    <Box display="flex" alignItems="center" gap={0.5}>
                      <Schedule fontSize="small" />
                      <Typography variant="caption">
                        {new Date(policy.effectiveAt).toLocaleDateString(
                          "ar-EG",
                        )}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    {policy.expiresAt ? (
                      <Typography
                        variant="caption"
                        color={isExpired(policy) ? "error" : "text.secondary"}
                      >
                        {new Date(policy.expiresAt).toLocaleDateString("ar-EG")}
                      </Typography>
                    ) : (
                      <Typography variant="caption" color="text.secondary">
                        بدون انتهاء
                      </Typography>
                    )}
                  </TableCell>
                  <TableCell>
                    <Box display="flex" alignItems="center" gap={1}>
                      <Switch
                        checked={policy.isActive}
                        onChange={() => handleToggleActive(policy)}
                        size="small"
                      />
                      {isExpired(policy) && (
                        <Chip label="منتهية" size="small" color="error" />
                      )}
                      {isNotYetEffective(policy) && (
                        <Chip label="قادمة" size="small" color="warning" />
                      )}
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={`v${policy.version}`}
                      size="small"
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>
                    <IconButton
                      size="small"
                      onClick={() => {
                        setViewingPolicy(policy);
                        setViewDialogOpen(true);
                      }}
                    >
                      <Visibility fontSize="small" />
                    </IconButton>
                    <IconButton
                      size="small"
                      onClick={() => openEditDialog(policy)}
                    >
                      <Edit fontSize="small" />
                    </IconButton>
                    <IconButton
                      size="small"
                      color="error"
                      onClick={() => handleDelete(policy.id)}
                    >
                      <Delete fontSize="small" />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <Dialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {editingPolicy ? "تعديل السياسة" : "إضافة سياسة جديدة"}
        </DialogTitle>
        <DialogContent>
          <LocalizationProvider dateAdapter={AdapterDateFns}>
            <Grid container spacing={2} sx={{ mt: 1 }}>
              <Grid item xs={12}>
                <TextField
                  label="العنوان"
                  fullWidth
                  value={formData.title}
                  onChange={(e) =>
                    setFormData({ ...formData, title: e.target.value })
                  }
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="المحتوى"
                  fullWidth
                  multiline
                  rows={6}
                  value={formData.content}
                  onChange={(e) =>
                    setFormData({ ...formData, content: e.target.value })
                  }
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <FormControl fullWidth>
                  <InputLabel>الفئة</InputLabel>
                  <Select
                    value={formData.category}
                    label="الفئة"
                    onChange={(e) =>
                      setFormData({ ...formData, category: e.target.value })
                    }
                  >
                    <MenuItem value="general">عام</MenuItem>
                    <MenuItem value="shipping">الشحن</MenuItem>
                    <MenuItem value="return">الإرجاع</MenuItem>
                    <MenuItem value="refund">الاسترداد</MenuItem>
                    <MenuItem value="privacy">الخصوصية</MenuItem>
                    <MenuItem value="terms">الشروط والأحكام</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="الوسوم (مفصولة بفواصل)"
                  fullWidth
                  value={formData.tags}
                  onChange={(e) =>
                    setFormData({ ...formData, tags: e.target.value })
                  }
                  placeholder="شحن, إرجاع, ضمان"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <DateTimePicker
                  label="تاريخ السريان"
                  value={formData.effectiveAt}
                  onChange={(date) =>
                    setFormData({
                      ...formData,
                      effectiveAt: date || new Date(),
                    })
                  }
                  slotProps={{ textField: { fullWidth: true } }}
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <DateTimePicker
                  label="تاريخ الانتهاء (اختياري)"
                  value={formData.expiresAt}
                  onChange={(date) =>
                    setFormData({ ...formData, expiresAt: date })
                  }
                  slotProps={{ textField: { fullWidth: true } }}
                />
              </Grid>
              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formData.isActive}
                      onChange={(e) =>
                        setFormData({ ...formData, isActive: e.target.checked })
                      }
                    />
                  }
                  label="نشط"
                />
              </Grid>
            </Grid>
          </LocalizationProvider>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>إلغاء</Button>
          <Button
            variant="contained"
            onClick={handleSave}
            disabled={!formData.title || !formData.content}
          >
            حفظ
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={viewDialogOpen}
        onClose={() => setViewDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>{viewingPolicy?.title}</DialogTitle>
        <DialogContent>
          {viewingPolicy && (
            <Box>
              <Grid container spacing={2} sx={{ mb: 2 }}>
                <Grid item xs={6}>
                  <Typography variant="caption" color="text.secondary">
                    الفئة
                  </Typography>
                  <Typography variant="body2">
                    {viewingPolicy.category}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="caption" color="text.secondary">
                    الإصدار
                  </Typography>
                  <Typography variant="body2">
                    v{viewingPolicy.version}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="caption" color="text.secondary">
                    تاريخ السريان
                  </Typography>
                  <Typography variant="body2">
                    {new Date(viewingPolicy.effectiveAt).toLocaleString(
                      "ar-EG",
                    )}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="caption" color="text.secondary">
                    تاريخ الانتهاء
                  </Typography>
                  <Typography variant="body2">
                    {viewingPolicy.expiresAt
                      ? new Date(viewingPolicy.expiresAt).toLocaleString(
                          "ar-EG",
                        )
                      : "بدون انتهاء"}
                  </Typography>
                </Grid>
              </Grid>
              <Typography variant="body1" sx={{ whiteSpace: "pre-wrap" }}>
                {viewingPolicy.content}
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setViewDialogOpen(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default PolicyManagement;

import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  CircularProgress,
  Button,
} from "@mui/material";
import { Visibility, Schedule } from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface TraceStep {
  id: string;
  stepType: string;
  latencyMs: number;
  input: string;
  output: string;
  metadata: string;
  order: number;
  createdAt: string;
}

interface Trace {
  id: string;
  query: string;
  timestamp: string;
  latencyMs: number;
  metadata: string;
  createdAt: string;
  steps: TraceStep[];
}

const RAGInspector: React.FC = () => {
  const [traces, setTraces] = useState<Trace[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedTraceId, setSelectedTraceId] = useState<string | null>(null);
  const [traceDetails, setTraceDetails] = useState<Trace | null>(null);
  const [loadingDetails, setLoadingDetails] = useState(false);

  const fetchTraces = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get("/rag-analytics/traces");
      if (response.data.success) {
        setTraces(response.data.data);
      }
    } catch (error) {
      console.error("Failed to fetch traces:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchTraceDetails = async (id: string) => {
    setLoadingDetails(true);
    try {
      const response = await apiClient.get(`/rag-analytics/traces/${id}`);
      if (response.data.success) {
        setTraceDetails(response.data.data);
      }
    } catch (error) {
      console.error("Failed to fetch trace details:", error);
    } finally {
      setLoadingDetails(false);
    }
  };

  useEffect(() => {
    fetchTraces();
  }, []);

  const handleOpenTrace = (id: string) => {
    setSelectedTraceId(id);
    fetchTraceDetails(id);
  };

  const handleCloseTrace = () => {
    setSelectedTraceId(null);
    setTraceDetails(null);
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case "EXPANSION":
        return "info";
      case "RETRIEVAL":
        return "warning";
      case "RERANK":
        return "success";
      case "GENERATION":
        return "primary";
      default:
        return "default";
    }
  };

  const formatJSON = (str: string) => {
    try {
      return JSON.stringify(JSON.parse(str), null, 2);
    } catch (e) {
      return str;
    }
  };

  return (
    <Box>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h5">سجل التتبعات (Traces)</Typography>
        <Button variant="outlined" onClick={fetchTraces}>
          تحديث
        </Button>
      </Box>

      <TableContainer component={Card}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>التوقيت</TableCell>
              <TableCell>الاستعلام (Query)</TableCell>
              <TableCell>الخطوات</TableCell>
              <TableCell>السرعة</TableCell>
              <TableCell>إجراءات</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={5} align="center">
                  <CircularProgress size={24} />
                </TableCell>
              </TableRow>
            ) : (
              traces.map((trace) => (
                <TableRow key={trace.id} hover>
                  <TableCell>
                    {format(new Date(trace.createdAt), "pp P", { locale: ar })}
                  </TableCell>
                  <TableCell
                    sx={{
                      maxWidth: 300,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {trace.query}
                  </TableCell>
                  <TableCell>
                    {trace.steps?.map((s) => (
                      <Chip
                        key={s.stepType + Math.random()}
                        label={s.stepType[0]}
                        size="small"
                        color={getTypeColor(s.stepType) as any}
                        sx={{
                          mr: 0.5,
                          fontSize: "0.6rem",
                          height: 20,
                          width: 20,
                          "& .MuiChip-label": { px: 0 },
                        }}
                      />
                    ))}
                  </TableCell>
                  <TableCell>
                    {trace.steps?.reduce(
                      (acc, curr) => acc + (curr.latencyMs || 0),
                      0,
                    )}{" "}
                    ms
                  </TableCell>
                  <TableCell>
                    <IconButton onClick={() => handleOpenTrace(trace.id)}>
                      <Visibility />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog
        open={!!selectedTraceId}
        onClose={handleCloseTrace}
        maxWidth="md"
        fullWidth
        dir="ltr" // Show technical details LTR
      >
        <DialogTitle>
          Trace Details
          <Typography variant="caption" display="block" color="text.secondary">
            {selectedTraceId}
          </Typography>
        </DialogTitle>
        <DialogContent dividers>
          {loadingDetails || !traceDetails ? (
            <Box display="flex" justifyContent="center" p={3}>
              <CircularProgress />
            </Box>
          ) : (
            <Box>
              <Box mb={3} p={2} bgcolor="grey.50" borderRadius={1}>
                <Typography variant="subtitle2" gutterBottom>
                  Original Query:
                </Typography>
                <Typography variant="h6">{traceDetails.query}</Typography>
              </Box>

              <Typography variant="h6" gutterBottom>
                Execution Steps
              </Typography>
              {traceDetails.steps?.map((step, index) => (
                <Card key={step.id || index} variant="outlined" sx={{ mb: 2 }}>
                  <CardContent sx={{ pb: "16px !important" }}>
                    <Box
                      display="flex"
                      alignItems="center"
                      justifyContent="space-between"
                      mb={1}
                    >
                      <Box display="flex" alignItems="center" gap={1}>
                        <Chip
                          label={step.stepType}
                          color={getTypeColor(step.stepType) as any}
                          size="small"
                        />
                        <Typography
                          variant="caption"
                          display="flex"
                          alignItems="center"
                        >
                          <Schedule fontSize="inherit" sx={{ mr: 0.5 }} />
                          {step.latencyMs}ms
                        </Typography>
                      </Box>
                      {/* <Typography variant="caption" color="text.secondary">Step {index + 1}</Typography> */}
                    </Box>

                    {/* Input/Output Expanders could go here, for now just basic info */}
                    {step.stepType === "EXPANSION" && (
                      <Box mt={1}>
                        <Typography variant="subtitle2" fontSize="0.75rem">
                          Expanded Queries:
                        </Typography>
                        <pre
                          style={{
                            margin: 0,
                            fontSize: "0.75rem",
                            background: "#f5f5f5",
                            padding: 4,
                          }}
                        >
                          {formatJSON(step.output)}
                        </pre>
                      </Box>
                    )}

                    {step.stepType === "RETRIEVAL" && (
                      <Box mt={1}>
                        <Typography variant="subtitle2" fontSize="0.75rem">
                          Retrieved Docs:
                        </Typography>
                        <Typography variant="caption">
                          Input: {formatJSON(step.input)}
                        </Typography>
                        {/* <pre style={{ margin: 0, fontSize: '0.75rem', maxHeight: 100, overflow: 'auto' }}>
                            {formatJSON(step.output)}
                          </pre> */}
                      </Box>
                    )}

                    <Box mt={2}>
                      <details>
                        <summary
                          style={{
                            cursor: "pointer",
                            fontSize: "0.8rem",
                            color: "gray",
                          }}
                        >
                          View Full Input/Output
                        </summary>
                        <Box
                          mt={1}
                          display="grid"
                          gridTemplateColumns="1fr 1fr"
                          gap={2}
                        >
                          <Box>
                            <Typography variant="caption" fontWeight="bold">
                              Input
                            </Typography>
                            <pre
                              style={{
                                fontSize: "0.7rem",
                                maxHeight: 200,
                                overflow: "auto",
                                background: "#f8f9fa",
                                padding: 8,
                                borderRadius: 4,
                              }}
                            >
                              {formatJSON(step.input)}
                            </pre>
                          </Box>
                          <Box>
                            <Typography variant="caption" fontWeight="bold">
                              Output
                            </Typography>
                            <pre
                              style={{
                                fontSize: "0.7rem",
                                maxHeight: 200,
                                overflow: "auto",
                                background: "#f8f9fa",
                                padding: 8,
                                borderRadius: 4,
                              }}
                            >
                              {formatJSON(step.output)}
                            </pre>
                          </Box>
                        </Box>
                      </details>
                    </Box>
                  </CardContent>
                </Card>
              ))}
            </Box>
          )}
        </DialogContent>
      </Dialog>
    </Box>
  );
};

export default RAGInspector;

import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Tabs,
  Tab,
  CircularProgress,
  Alert,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import Grid from "@mui/material/GridLegacy";
import {
  Refresh,
  Delete,
  Speed,
  Storage,
  Analytics,
  Security,
  CheckCircle,
  Error as ErrorIcon,
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";
import RAGInspector from "./RAGInspector";
import RAGPlayground from "./RAGPlayground";

interface CacheStats {
  faqs: { size: number; hits: number; misses: number };
  policies: { size: number; hits: number; misses: number };
  products: { size: number; hits: number; misses: number };
  search: { size: number; hits: number; misses: number };
}

interface SystemHealth {
  status: string;
  cache: { enabled: boolean; stats: CacheStats };
  analytics: { enabled: boolean; recordsCount: number };
  rateLimiter: { enabled: boolean; activeCompanies: number };
  dataLoader: { enabled: boolean; lastReload: string };
}

const RAGManagement: React.FC = () => {
  const [tabValue, setTabValue] = useState(0);
  const [loading, setLoading] = useState(false);
  const [cacheStats, setCacheStats] = useState<CacheStats | null>(null);
  const [systemHealth, setSystemHealth] = useState<SystemHealth | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean;
    action: string;
    title: string;
  }>({ open: false, action: "", title: "" });
  const [settings, setSettings] = useState<any>(null);
  const [analyticsData, setAnalyticsData] = useState<any>(null);
  const [performanceData, setPerformanceData] = useState<any>(null);

  useEffect(() => {
    loadData();
  }, [tabValue]);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      if (tabValue === 0) {
        const [healthRes, cacheRes] = await Promise.all([
          apiClient.get("/rag-admin/health"),
          apiClient.get("/rag-admin/cache/stats"),
        ]);
        setSystemHealth(healthRes.data);
        setCacheStats(cacheRes.data);
      } else if (tabValue === 3) {
        const analyticsRes = await apiClient.get("/rag-admin/analytics/search");
        setAnalyticsData(analyticsRes.data.data);
      } else if (tabValue === 4) {
        const performanceRes = await apiClient.get(
          "/rag-admin/analytics/performance",
        );
        setPerformanceData(performanceRes.data.data);
      } else if (tabValue === 5) {
        const settingsRes = await apiClient.get("/rag-admin/settings");
        setSettings(settingsRes.data.data);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحميل البيانات");
    } finally {
      setLoading(false);
    }
  };

  const handleInvalidateCache = async (type?: string) => {
    try {
      await apiClient.post("/rag-admin/cache/invalidate", { type });
      setSuccess(
        `تم إلغاء الذاكرة المؤقتة ${type ? `(${type})` : "بالكامل"} بنجاح`,
      );
      loadData();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل إلغاء الذاكرة المؤقتة");
    }
    setConfirmDialog({ open: false, action: "", title: "" });
  };

  const handleReloadData = async (type: "faqs" | "policies") => {
    try {
      await apiClient.post(`/rag-admin/reload/${type}`);
      setSuccess(
        `تم إعادة تحميل ${type === "faqs" ? "الأسئلة الشائعة" : "السياسات"} بنجاح`,
      );
      loadData();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل إعادة التحميل");
    }
    setConfirmDialog({ open: false, action: "", title: "" });
  };

  const handleUpdateSettings = async (newSettings: any) => {
    try {
      await apiClient.post("/rag-admin/settings/update", newSettings);
      setSuccess("تم تحديث الإعدادات بنجاح");
      loadData();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحديث الإعدادات");
    }
  };

  const renderCacheCard = (title: string, stats: any, type: string) => {
    // Add null checks for stats
    if (!stats) {
      stats = { size: 0, hits: 0, misses: 0 };
    }

    const hits = stats.hits || 0;
    const misses = stats.misses || 0;
    const size = stats.size || 0;

    const hitRate =
      hits + misses > 0 ? ((hits / (hits + misses)) * 100).toFixed(1) : "0";

    return (
      <Card sx={{ height: "100%" }}>
        <CardContent>
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            mb={2}
          >
            <Typography variant="h6">{title}</Typography>
            <IconButton
              size="small"
              onClick={() =>
                setConfirmDialog({
                  open: true,
                  action: `invalidate-${type}`,
                  title: `إلغاء ذاكرة ${title}`,
                })
              }
            >
              <Delete />
            </IconButton>
          </Box>
          <Grid container spacing={2}>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                الحجم
              </Typography>
              <Typography variant="h6">{size}</Typography>
            </Grid>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                معدل النجاح
              </Typography>
              <Typography variant="h6" color="primary">
                {hitRate}%
              </Typography>
            </Grid>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                Hits
              </Typography>
              <Typography variant="body1">{hits}</Typography>
            </Grid>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                Misses
              </Typography>
              <Typography variant="body1">{misses}</Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    );
  };

  // Helper to safely access limits
  const limits = settings?.limits || {};
  const cacheConfig = settings?.cache || {};

  const renderSettingsTab = () => (
    <Box>
      <Typography variant="h5" mb={3}>
        إعدادات النظام
      </Typography>
      {settings && (
        <Grid container spacing={3}>
          {/* Rate Limits Section */}
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  حدود الطلبات (Rate Limits)
                </Typography>
                <Box mb={3}>
                  <Typography variant="subtitle2" color="text.secondary">
                    لكل شركة (في الدقيقة)
                  </Typography>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={8}>
                      <Typography variant="body1">
                        الحد الأقصى: {limits.perCompany?.maxRequests}
                      </Typography>
                    </Grid>
                    <Grid item xs={4}>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => {
                          const val = prompt(
                            "أدخل الحد الجديد لكل شركة:",
                            limits.perCompany?.maxRequests?.toString(),
                          );
                          if (val)
                            handleUpdateSettings({
                              limits: {
                                ...limits,
                                perCompany: {
                                  ...limits.perCompany,
                                  maxRequests: parseInt(val),
                                },
                              },
                            });
                        }}
                      >
                        تعديل
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
                <Box>
                  <Typography variant="subtitle2" color="text.secondary">
                    لكل عنوان IP (في الدقيقة)
                  </Typography>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={8}>
                      <Typography variant="body1">
                        الحد الأقصى: {limits.perIP?.maxRequests}
                      </Typography>
                    </Grid>
                    <Grid item xs={4}>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => {
                          const val = prompt(
                            "أدخل الحد الجديد لكل IP:",
                            limits.perIP?.maxRequests?.toString(),
                          );
                          if (val)
                            handleUpdateSettings({
                              limits: {
                                ...limits,
                                perIP: {
                                  ...limits.perIP,
                                  maxRequests: parseInt(val),
                                },
                              },
                            });
                        }}
                      >
                        تعديل
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          {/* Token Budget Section */}
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  ميزانية الـ Tokens اليومية
                </Typography>
                <Box mb={3}>
                  <Typography variant="subtitle2" color="text.secondary">
                    الحد الأقصى للشركة يومياً
                  </Typography>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={8}>
                      <Typography variant="body1">
                        {limits.dailyTokens?.maxTokens?.toLocaleString()} Token
                      </Typography>
                    </Grid>
                    <Grid item xs={4}>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => {
                          const val = prompt(
                            "أدخل حد الـ Tokens الجديد:",
                            limits.dailyTokens?.maxTokens?.toString(),
                          );
                          if (val)
                            handleUpdateSettings({
                              limits: {
                                ...limits,
                                dailyTokens: { maxTokens: parseInt(val) },
                              },
                            });
                        }}
                      >
                        تعديل
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          {/* Cache Configuration Section */}
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  إعدادات الذاكرة المؤقتة (Smart Cache)
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  التحكم في مدة بقاء البيانات في الذاكرة (بالدقائق). زيادة المدة
                  تحسن الأداء ولكن قد تؤخر التحديثات.
                </Typography>

                <Grid container spacing={3}>
                  {/* Search Cache TTL */}
                  <Grid item xs={12} md={4}>
                    <Box mb={1}>
                      <Typography variant="subtitle2">
                        ذاكرة البحث (Search TTL)
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        المقترحات والنتائج المكررة
                      </Typography>
                    </Box>
                    <Grid container spacing={2} alignItems="center">
                      <Grid item xs={6}>
                        <Typography variant="h6">
                          {(cacheConfig.ttl?.search / 60000).toFixed(0)} دقيقة
                        </Typography>
                      </Grid>
                      <Grid item xs={6}>
                        <Button
                          size="small"
                          variant="outlined"
                          fullWidth
                          onClick={() => {
                            const val = prompt(
                              "أدخل مدة الحفظ بالدقائق:",
                              (cacheConfig.ttl?.search / 60000).toString(),
                            );
                            if (val)
                              handleUpdateSettings({
                                cache: {
                                  ...cacheConfig,
                                  ttl: {
                                    ...cacheConfig.ttl,
                                    search: parseInt(val) * 60000,
                                  },
                                },
                              });
                          }}
                        >
                          تعديل
                        </Button>
                      </Grid>
                    </Grid>
                  </Grid>

                  {/* Product Cache TTL */}
                  <Grid item xs={12} md={4}>
                    <Box mb={1}>
                      <Typography variant="subtitle2">
                        ذاكرة المنتجات (Product TTL)
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        تفاصيل المنتجات والأسعار
                      </Typography>
                    </Box>
                    <Grid container spacing={2} alignItems="center">
                      <Grid item xs={6}>
                        <Typography variant="h6">
                          {(cacheConfig.ttl?.product / 60000).toFixed(0)} دقيقة
                        </Typography>
                      </Grid>
                      <Grid item xs={6}>
                        <Button
                          size="small"
                          variant="outlined"
                          fullWidth
                          onClick={() => {
                            const val = prompt(
                              "أدخل مدة الحفظ بالدقائق:",
                              (cacheConfig.ttl?.product / 60000).toString(),
                            );
                            if (val)
                              handleUpdateSettings({
                                cache: {
                                  ...cacheConfig,
                                  ttl: {
                                    ...cacheConfig.ttl,
                                    product: parseInt(val) * 60000,
                                  },
                                },
                              });
                          }}
                        >
                          تعديل
                        </Button>
                      </Grid>
                    </Grid>
                  </Grid>

                  {/* FAQ/Policy Cache TTL */}
                  <Grid item xs={12} md={4}>
                    <Box mb={1}>
                      <Typography variant="subtitle2">
                        الأسئلة والسياسات
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        المعلومات الثابتة
                      </Typography>
                    </Box>
                    <Grid container spacing={2} alignItems="center">
                      <Grid item xs={6}>
                        <Typography variant="h6">
                          {(cacheConfig.ttl?.faq / 60000).toFixed(0)} دقيقة
                        </Typography>
                      </Grid>
                      <Grid item xs={6}>
                        <Button
                          size="small"
                          variant="outlined"
                          fullWidth
                          onClick={() => {
                            const val = prompt(
                              "أدخل مدة الحفظ بالدقائق:",
                              (cacheConfig.ttl?.faq / 60000).toString(),
                            );
                            if (val)
                              handleUpdateSettings({
                                cache: {
                                  ...cacheConfig,
                                  ttl: {
                                    ...cacheConfig.ttl,
                                    faq: parseInt(val) * 60000,
                                    policy: parseInt(val) * 60000,
                                  },
                                },
                              });
                          }}
                        >
                          تعديل
                        </Button>
                      </Grid>
                    </Grid>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}
    </Box>
  );

  const renderAnalyticsTab = () => (
    <Box>
      <Typography variant="h5" mb={3}>
        تحليلات البحث
      </Typography>
      {analyticsData && (
        <Grid container spacing={3}>
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  إحصائيات النتائج
                </Typography>
                <TableContainer>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell align="right">النية (Intent)</TableCell>
                        <TableCell align="center">العدد</TableCell>
                        <TableCell align="center">الحالة</TableCell>
                        <TableCell align="center">متوسط السرعة</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {analyticsData.stats.map((stat: any, idx: number) => (
                        <TableRow key={idx}>
                          <TableCell align="right">{stat.intent}</TableCell>
                          <TableCell align="center">{stat._count}</TableCell>
                          <TableCell align="center">
                            {stat.wasSuccessful ? "✅" : "❌"}
                          </TableCell>
                          <TableCell align="center">
                            {stat._avg.responseTime.toFixed(0)} ms
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2} color="error">
                  أبحاث فاشلة حديثاً
                </Typography>
                {analyticsData.failedSearches.map((item: any, idx: number) => (
                  <Box
                    key={idx}
                    mb={1}
                    p={1}
                    bgcolor="error.light"
                    borderRadius={1}
                  >
                    <Typography variant="body2" color="white">
                      {item.query}
                    </Typography>
                    <Typography
                      variant="caption"
                      color="white"
                      sx={{ opacity: 0.8 }}
                    >
                      {new Date(item.createdAt).toLocaleTimeString()}
                    </Typography>
                  </Box>
                ))}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}
    </Box>
  );

  const renderPerformanceTab = () => (
    <Box>
      <Typography variant="h5" mb={3}>
        أداء النظام وتكاليف الـ AI
      </Typography>
      {performanceData && (
        <Grid container spacing={3}>
          {performanceData.stats.map((op: any, idx: number) => (
            <Grid item xs={12} md={4} key={idx}>
              <Card>
                <CardContent>
                  <Typography variant="h6" color="primary">
                    {op.operation}
                  </Typography>
                  <Box mt={2}>
                    <Typography variant="body2" color="text.secondary">
                      عدد العمليات: {op._count}
                    </Typography>
                    <Typography variant="body1">
                      متوسط الـ Tokens: {op._avg.tokensUsed?.toFixed(0) || 0}
                    </Typography>
                    <Typography variant="body1">
                      إجمالي الـ Tokens:{" "}
                      {op._sum.tokensUsed?.toLocaleString() || 0}
                    </Typography>
                    <Typography variant="body2" mt={1}>
                      متوسط الاستجابة: {op._avg.responseTime.toFixed(0)} ms
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}
    </Box>
  );

  const renderOverviewTab = () => (
    <Box>
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}
      {success && (
        <Alert
          severity="success"
          sx={{ mb: 2 }}
          onClose={() => setSuccess(null)}
        >
          {success}
        </Alert>
      )}

      {systemHealth && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Box display="flex" alignItems="center" mb={2}>
              <Typography variant="h5" sx={{ flexGrow: 1 }}>
                حالة النظام
              </Typography>
              <Chip
                icon={
                  systemHealth.status === "healthy" ? (
                    <CheckCircle />
                  ) : (
                    <ErrorIcon />
                  )
                }
                label={
                  systemHealth.status === "healthy"
                    ? "يعمل بشكل جيد"
                    : "يوجد مشاكل"
                }
                color={systemHealth.status === "healthy" ? "success" : "error"}
              />
            </Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Storage sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Cache
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.cache?.enabled ? "مفعّل" : "معطّل"}
                    </Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Analytics sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Analytics
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.analytics?.recordsCount || 0} سجل
                    </Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Security sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Rate Limiter
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.rateLimiter?.activeCompanies || 0} شركة
                    </Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Speed sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      آخر تحديث
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.dataLoader?.lastReload
                        ? new Date(
                            systemHealth.dataLoader.lastReload,
                          ).toLocaleTimeString("ar-EG")
                        : "N/A"}
                    </Typography>
                  </Box>
                </Box>
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      )}

      {cacheStats && (
        <>
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            mb={2}
          >
            <Typography variant="h5">إحصائيات الذاكرة المؤقتة</Typography>
            <Box>
              <Button
                variant="outlined"
                startIcon={<Refresh />}
                onClick={loadData}
                sx={{ mr: 1 }}
              >
                تحديث
              </Button>
              <Button
                variant="contained"
                color="error"
                startIcon={<Delete />}
                onClick={() =>
                  setConfirmDialog({
                    open: true,
                    action: "invalidate-all",
                    title: "إلغاء جميع الذاكرة المؤقتة",
                  })
                }
              >
                إلغاء الكل
              </Button>
            </Box>
          </Box>

          <Grid container spacing={3}>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("الأسئلة الشائعة", cacheStats.faqs, "faqs")}
            </Grid>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("السياسات", cacheStats.policies, "policies")}
            </Grid>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("المنتجات", cacheStats.products, "products")}
            </Grid>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("البحث", cacheStats.search, "search")}
            </Grid>
          </Grid>

          <Box mt={4}>
            <Typography variant="h5" mb={2}>
              إعادة تحميل البيانات
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" mb={2}>
                      الأسئلة الشائعة
                    </Typography>
                    <Button
                      variant="contained"
                      startIcon={<Refresh />}
                      onClick={() =>
                        setConfirmDialog({
                          open: true,
                          action: "reload-faqs",
                          title: "إعادة تحميل الأسئلة الشائعة",
                        })
                      }
                      fullWidth
                    >
                      إعادة تحميل من قاعدة البيانات
                    </Button>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" mb={2}>
                      السياسات
                    </Typography>
                    <Button
                      variant="contained"
                      startIcon={<Refresh />}
                      onClick={() =>
                        setConfirmDialog({
                          open: true,
                          action: "reload-policies",
                          title: "إعادة تحميل السياسات",
                        })
                      }
                      fullWidth
                    >
                      إعادة تحميل من قاعدة البيانات
                    </Button>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          </Box>
        </>
      )}
    </Box>
  );

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" mb={3}>
        إدارة نظام RAG
      </Typography>

      <Tabs value={tabValue} onChange={(_, v) => setTabValue(v)} sx={{ mb: 3 }}>
        <Tab label="نظرة عامة" />
        <Tab label="سجل التتبعات" />
        <Tab label="تجربة البحث" />
        <Tab label="التحليلات" />
        <Tab label="الأداء" />
        <Tab label="الإعدادات" />
      </Tabs>

      {loading ? (
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          {tabValue === 0 && renderOverviewTab()}
          {tabValue === 1 && <RAGInspector />}
          {tabValue === 2 && <RAGPlayground />}
          {tabValue === 3 && renderAnalyticsTab()}
          {tabValue === 4 && renderPerformanceTab()}
          {tabValue === 5 && renderSettingsTab()}
        </>
      )}

      <Dialog
        open={confirmDialog.open}
        onClose={() => setConfirmDialog({ open: false, action: "", title: "" })}
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>
        <DialogContent>
          <Typography>هل أنت متأكد من هذا الإجراء؟</Typography>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() =>
              setConfirmDialog({ open: false, action: "", title: "" })
            }
          >
            إلغاء
          </Button>
          <Button
            variant="contained"
            color="primary"
            onClick={() => {
              if (confirmDialog.action === "invalidate-all") {
                handleInvalidateCache();
              } else if (confirmDialog.action.startsWith("invalidate-")) {
                const type = confirmDialog.action.replace("invalidate-", "");
                handleInvalidateCache(type);
              } else if (confirmDialog.action === "reload-faqs") {
                handleReloadData("faqs");
              } else if (confirmDialog.action === "reload-policies") {
                handleReloadData("policies");
              }
            }}
          >
            تأكيد
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default RAGManagement;

import React, { useState } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  CircularProgress,
  Chip,
} from "@mui/material";
import Grid from "@mui/material/GridLegacy";
import { Search, Image as ImageIcon } from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";

const RAGPlayground: React.FC = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [executionTime, setExecutionTime] = useState<number | null>(null);

  const handleSearch = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setExecutionTime(null);
    const startTime = Date.now();

    try {
      const response = await apiClient.get("/products/search", {
        params: { q: query },
      });

      if (response.data.success) {
        setResults(response.data.data);
      }
    } catch (error) {
      console.error("Search failed:", error);
    } finally {
      setExecutionTime(Date.now() - startTime);
      setLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      handleSearch();
    }
  };

  return (
    <Box>
      <Card sx={{ mb: 4 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            تجربة البحث (Playground)
          </Typography>
          <Typography variant="body2" color="text.secondary" mb={3}>
            اختبر محرك البحث RAG وتأكد من دقة النتائج وترتيبها.
          </Typography>

          <Box display="flex" gap={2}>
            <TextField
              fullWidth
              label="بحث عن منتج..."
              variant="outlined"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder="مثال: حذاء رياضي نايك أسود مقاس 42"
            />
            <Button
              variant="contained"
              size="large"
              startIcon={
                loading ? (
                  <CircularProgress size={20} color="inherit" />
                ) : (
                  <Search />
                )
              }
              onClick={handleSearch}
              disabled={loading || !query.trim()}
              sx={{ minWidth: 120 }}
            >
              بحث
            </Button>
          </Box>

          {executionTime !== null && (
            <Box mt={2} display="flex" alignItems="center" gap={1}>
              <Typography variant="caption" color="text.secondary">
                تم التنفيذ في {executionTime}ms
              </Typography>
              <Typography variant="caption" color="text.secondary">
                • عدد النتائج: {results.length}
              </Typography>
            </Box>
          )}
        </CardContent>
      </Card>

      <Grid container spacing={3}>
        {results.map((product) => (
          <Grid item xs={12} md={6} key={product.id}>
            <Card variant="outlined" sx={{ display: "flex", height: "100%" }}>
              {product.images && JSON.parse(product.images)[0] && (
                <Box
                  component="img"
                  sx={{ width: 100, objectFit: "cover" }}
                  src={JSON.parse(product.images)[0]}
                  alt={product.name}
                />
              )}
              {!product.images ||
                (!JSON.parse(product.images)[0] && (
                  <Box
                    sx={{
                      width: 100,
                      bgcolor: "grey.100",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <ImageIcon color="disabled" />
                  </Box>
                ))}
              <Box
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  flexGrow: 1,
                  p: 2,
                }}
              >
                <Box
                  display="flex"
                  justifyContent="space-between"
                  alignItems="start"
                >
                  <Typography
                    variant="subtitle1"
                    component="div"
                    fontWeight="bold"
                  >
                    {product.name}
                  </Typography>
                  {product.score && (
                    <Chip
                      label={`Score: ${(product.score * 100).toFixed(0)}%`}
                      size="small"
                      color={
                        product.score > 0.7
                          ? "success"
                          : product.score > 0.5
                            ? "warning"
                            : "default"
                      }
                      variant="outlined"
                    />
                  )}
                </Box>

                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{
                    mb: 1,
                    maxHeight: 40,
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {product.description?.substring(0, 100)}...
                </Typography>

                <Box mt="auto" display="flex" justifyContent="space-between">
                  <Typography variant="subtitle2" color="primary">
                    {product.price} EGP
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    ID: {product.id.substring(0, 8)}...
                  </Typography>
                </Box>
              </Box>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

export default RAGPlayground;

import React, { useState } from "react";
import {
  XMarkIcon,
  BuildingOffice2Icon,
  EnvelopeIcon,
  PhoneIcon,
  GlobeAltIcon,
  MapPinIcon,
  CurrencyDollarIcon,
  ClockIcon,
} from "@heroicons/react/24/outline";
import { toast } from "react-hot-toast";
import { apiClient } from "../services/apiClient";

interface CreateCompanyModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

interface FormData {
  name: string;
  email: string;
  phone: string;
  website: string;
  address: string;
  plan: string;
  currency: string;
  timezone: string;
}

const CreateCompanyModal: React.FC<CreateCompanyModalProps> = ({
  isOpen,
  onClose,
  onSuccess,
}) => {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState<FormData>({
    name: "",
    email: "",
    phone: "",
    website: "",
    address: "",
    plan: "BASIC",
    currency: "EGP",
    timezone: "Africa/Cairo",
  });

  const [errors, setErrors] = useState<Partial<FormData>>({});

  const plans = [
    { value: "BASIC", label: "أساسية - Basic" },
    { value: "PROFESSIONAL", label: "احترافية - Professional" },
    { value: "ENTERPRISE", label: "مؤسسية - Enterprise" },
  ];

  const currencies = [
    { value: "EGP", label: "جنيه مصري - EGP", symbol: "ج.م" },
    { value: "USD", label: "دولار أمريكي - USD", symbol: "$" },
    { value: "SAR", label: "ريال سعودي - SAR", symbol: "ر.س" },
    { value: "AED", label: "درهم إماراتي - AED", symbol: "د.إ" },
    { value: "EUR", label: "يورو - EUR", symbol: "€" },
  ];

  const timezones = [
    { value: "Africa/Cairo", label: "القاهرة (GMT+2)" },
    { value: "Asia/Riyadh", label: "الرياض (GMT+3)" },
    { value: "Asia/Dubai", label: "دبي (GMT+4)" },
    { value: "Europe/London", label: "لندن (GMT+0)" },
    { value: "America/New_York", label: "نيويورك (GMT-5)" },
  ];

  const validateForm = (): boolean => {
    const newErrors: Partial<FormData> = {};

    if (!formData.name.trim()) {
      newErrors.name = "اسم الشركة مطلوب";
    }

    if (!formData.email.trim()) {
      newErrors.email = "البريد الإلكتروني مطلوب";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = "البريد الإلكتروني غير صحيح";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);

    try {
      const response = await apiClient.post("/owner/companies", {
        name: formData.name.trim(),
        email: formData.email.trim(),
        phone: formData.phone.trim() || undefined,
        website: formData.website.trim() || undefined,
        address: formData.address.trim() || undefined,
        plan: formData.plan,
        currency: formData.currency,
        timezone: formData.timezone,
      });

      if (response.data.success) {
        toast.success("تم إنشاء الشركة بنجاح! 🎉");
        onSuccess();
        handleClose();
      } else {
        toast.error(response.data.message || "فشل في إنشاء الشركة");
      }
    } catch (error: any) {
      console.error("Error creating company:", error);
      const errorMessage =
        error.response?.data?.message || "حدث خطأ أثناء إنشاء الشركة";
      toast.error(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    setFormData({
      name: "",
      email: "",
      phone: "",
      website: "",
      address: "",
      plan: "BASIC",
      currency: "EGP",
      timezone: "Africa/Cairo",
    });
    setErrors({});
    onClose();
  };

  const handleChange = (field: keyof FormData, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" dir="rtl">
      <div className="flex items-center justify-center min-h-screen px-4 pt-4 pb-20 text-center sm:block sm:p-0">
        {/* Overlay */}
        <div
          className="fixed inset-0 transition-opacity bg-gray-500 bg-opacity-75 dark:bg-gray-900 dark:bg-opacity-80"
          onClick={handleClose}
        />

        {/* Modal */}
        <div className="inline-block w-full max-w-2xl my-8 overflow-hidden text-right align-middle transition-all transform bg-white dark:bg-gray-800 rounded-2xl shadow-xl">
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg">
                <BuildingOffice2Icon className="w-6 h-6 text-blue-600 dark:text-blue-400" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                  إضافة شركة جديدة
                </h2>
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  أدخل بيانات الشركة الجديدة
                </p>
              </div>
            </div>
            <button
              onClick={handleClose}
              className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
            >
              <XMarkIcon className="w-5 h-5" />
            </button>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="p-6 space-y-5">
            {/* Company Name */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                اسم الشركة <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                  <BuildingOffice2Icon className="w-5 h-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => handleChange("name", e.target.value)}
                  className={`block w-full pr-10 border rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                    errors.name
                      ? "border-red-500"
                      : "border-gray-300 dark:border-gray-600"
                  }`}
                  placeholder="مثال: شركة التقنية المتقدمة"
                />
              </div>
              {errors.name && (
                <p className="mt-1 text-sm text-red-500">{errors.name}</p>
              )}
            </div>

            {/* Email */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                البريد الإلكتروني <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                  <EnvelopeIcon className="w-5 h-5 text-gray-400" />
                </div>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleChange("email", e.target.value)}
                  className={`block w-full pr-10 border rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                    errors.email
                      ? "border-red-500"
                      : "border-gray-300 dark:border-gray-600"
                  }`}
                  placeholder="company@example.com"
                />
              </div>
              {errors.email && (
                <p className="mt-1 text-sm text-red-500">{errors.email}</p>
              )}
            </div>

            {/* Phone & Website */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  رقم الهاتف
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                    <PhoneIcon className="w-5 h-5 text-gray-400" />
                  </div>
                  <input
                    type="tel"
                    value={formData.phone}
                    onChange={(e) => handleChange("phone", e.target.value)}
                    className="block w-full pr-10 border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="+20 123 456 7890"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الموقع الإلكتروني
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                    <GlobeAltIcon className="w-5 h-5 text-gray-400" />
                  </div>
                  <input
                    type="url"
                    value={formData.website}
                    onChange={(e) => handleChange("website", e.target.value)}
                    className="block w-full pr-10 border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="https://example.com"
                  />
                </div>
              </div>
            </div>

            {/* Address */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                العنوان
              </label>
              <div className="relative">
                <div className="absolute top-3 right-0 flex items-center pr-3 pointer-events-none">
                  <MapPinIcon className="w-5 h-5 text-gray-400" />
                </div>
                <textarea
                  value={formData.address}
                  onChange={(e) => handleChange("address", e.target.value)}
                  rows={2}
                  className="block w-full pr-10 border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="العنوان الكامل للشركة"
                />
              </div>
            </div>

            {/* Plan, Currency, Timezone */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الخطة
                </label>
                <select
                  value={formData.plan}
                  onChange={(e) => handleChange("plan", e.target.value)}
                  className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  {plans.map((plan) => (
                    <option key={plan.value} value={plan.value}>
                      {plan.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  العملة
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                    <CurrencyDollarIcon className="w-5 h-5 text-gray-400" />
                  </div>
                  <select
                    value={formData.currency}
                    onChange={(e) => handleChange("currency", e.target.value)}
                    className="block w-full pr-10 border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    {currencies.map((currency) => (
                      <option key={currency.value} value={currency.value}>
                        {currency.label}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  المنطقة الزمنية
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                    <ClockIcon className="w-5 h-5 text-gray-400" />
                  </div>
                  <select
                    value={formData.timezone}
                    onChange={(e) => handleChange("timezone", e.target.value)}
                    className="block w-full pr-10 border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    {timezones.map((tz) => (
                      <option key={tz.value} value={tz.value}>
                        {tz.label}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* Footer Actions */}
            <div className="flex gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <button
                type="button"
                onClick={handleClose}
                className="flex-1 px-4 py-2.5 text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg font-medium transition-colors"
              >
                إلغاء
              </button>
              <button
                type="submit"
                disabled={isSubmitting}
                className="flex-1 px-4 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {isSubmitting ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    <span>جاري الإنشاء...</span>
                  </>
                ) : (
                  <>
                    <BuildingOffice2Icon className="w-5 h-5" />
                    <span>إنشاء الشركة</span>
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

