import React, { Component, ErrorInfo, ReactNode } from "react";
import { ExclamationTriangleIcon } from "@heroicons/react/24/outline";
import errorTracking from "../services/errorTracking";

/**
 * Error Boundary Component
 *
 * Catches JavaScript errors anywhere in the child component tree,
 * logs those errors, and displays a fallback UI.
 */

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
  errorInfo?: ErrorInfo;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI
    return { hasError: true, error };
  }

  override componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    // Log error to console in development
    if (import.meta.env.DEV) {
      console.error("Error Boundary caught an error:", error, errorInfo);
    }

    // Log error to monitoring service in production
    if (import.meta.env.PROD) {
      this.logErrorToService(error, errorInfo);
    }

    this.setState({ error, errorInfo });
  }

  private logErrorToService = (error: Error, errorInfo: React.ErrorInfo): void => {
    try {
      // Import dynamic to avoid circular dependency if possible, or just use global
      // Note: errorTracking is already imported in many files, here we just use it
      errorTracking.logError("ErrorBoundary caught error", error, {
        componentStack: errorInfo.componentStack,
        digest: (error as any).digest, // minified React error group ID
        timestamp: new Date().toISOString(),
        userAgent: navigator.userAgent,
        url: window.location.href,
        pathname: window.location.pathname,
      });
    } catch (loggingError) {
      console.error("Failed to log error to monitoring service:", loggingError);
    }
  };

  private handleReload = (): void => {
    window.location.reload();
  };

  private handleReset = (): void => {
    this.setState({ hasError: false, error: undefined, errorInfo: undefined });
  };

  override render(): ReactNode {
    if (this.state.hasError) {
      // Custom fallback UI
      if (this.props.fallback) {
        return this.props.fallback;
      }

      // Default fallback UI
      return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900 px-4">
          <div className="max-w-md w-full">
            <div className="text-center">
              <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-red-100 dark:bg-red-900/20 mb-6">
                <ExclamationTriangleIcon className="h-8 w-8 text-red-600 dark:text-red-400" />
              </div>

              <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
                حدث خطأ غير متوقع
              </h1>

              <p className="text-gray-600 dark:text-gray-400 mb-8">
                نعتذر، حدث خطأ في التطبيق. يرجى المحاولة مرة أخرى أو إعادة تحميل
                الصفحة.
              </p>

              {import.meta.env.DEV && this.state.error && (
                <div className="mb-8 p-4 bg-red-50 dark:bg-red-900/20 rounded-lg text-left">
                  <h3 className="text-sm font-medium text-red-800 dark:text-red-400 mb-2">
                    Error Details (Development Only):
                  </h3>
                  <pre className="text-xs text-red-700 dark:text-red-300 overflow-auto">
                    {this.state.error.message}
                    {this.state.error.stack && (
                      <>
                        {"\n\n"}
                        {this.state.error.stack}
                      </>
                    )}
                  </pre>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-3 justify-center">
                <button
                  onClick={this.handleReset}
                  className="btn btn-primary btn-md"
                >
                  المحاولة مرة أخرى
                </button>

                <button
                  onClick={this.handleReload}
                  className="btn btn-outline btn-md"
                >
                  إعادة تحميل الصفحة
                </button>
              </div>

              <div className="mt-8 text-sm text-gray-500 dark:text-gray-400">
                <p>
                  إذا استمر هذا الخطأ، يرجى{" "}
                  <a
                    href="mailto:support@example.com"
                    className="text-primary-600 hover:text-primary-500 dark:text-primary-400"
                  >
                    التواصل مع الدعم الفني
                  </a>
                </p>
              </div>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect } from "react";
import {
  ExclamationTriangleIcon,
  XMarkIcon,
  ArrowDownTrayIcon,
  TrashIcon,
  MagnifyingGlassIcon,
} from "@heroicons/react/24/outline";
import errorTracking, { ErrorLog } from "../services/errorTracking";

/**
 * Error Dashboard Component
 * لوحة تحكم لعرض وإدارة الأخطاء المسجلة
 */
const ErrorDashboard: React.FC = () => {
  const [errors, setErrors] = useState<ErrorLog[]>([]);
  const [filteredErrors, setFilteredErrors] = useState<ErrorLog[]>([]);
  const [filterCategory, setFilterCategory] = useState<string>("all");
  const [filterSeverity, setFilterSeverity] = useState<string>("all");
  const [searchTerm, setSearchTerm] = useState("");
  const [showDashboard, setShowDashboard] = useState(false);

  useEffect(() => {
    loadErrors();

    // Auto refresh every 5 seconds
    const interval = setInterval(loadErrors, 5000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    applyFilters();
  }, [errors, filterCategory, filterSeverity, searchTerm]);

  const loadErrors = () => {
    const storedErrors = errorTracking.getStoredErrors();
    setErrors(storedErrors);
  };

  const applyFilters = () => {
    let filtered = [...errors];

    // Filter by category
    if (filterCategory !== "all") {
      filtered = filtered.filter((err) => err.category === filterCategory);
    }

    // Filter by severity
    if (filterSeverity !== "all") {
      filtered = filtered.filter((err) => err.severity === filterSeverity);
    }

    // Search
    if (searchTerm) {
      filtered = filtered.filter((err) =>
        err.message.toLowerCase().includes(searchTerm.toLowerCase()),
      );
    }

    setFilteredErrors(filtered);
  };

  const handleClearErrors = () => {
    if (confirm("هل أنت متأكد من حذف جميع الأخطاء المسجلة؟")) {
      errorTracking.clearStoredErrors();
      setErrors([]);
    }
  };

  const handleExportJSON = () => {
    const json = errorTracking.exportErrors();
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `errors-${new Date().toISOString()}.json`;
    a.click();
  };

  const handleExportCSV = () => {
    const csv = errorTracking.exportErrorsAsCSV();
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `errors-${new Date().toISOString()}.csv`;
    a.click();
  };

  const getSeverityColor = (severity: ErrorLog["severity"]) => {
    switch (severity) {
      case "critical":
        return "bg-red-100 text-red-800 border-red-200";
      case "high":
        return "bg-orange-100 text-orange-800 border-orange-200";
      case "medium":
        return "bg-yellow-100 text-yellow-800 border-yellow-200";
      case "low":
        return "bg-blue-100 text-blue-800 border-blue-200";
      default:
        return "bg-gray-100 text-gray-800 border-gray-200";
    }
  };

  const getCategoryColor = (category: ErrorLog["category"]) => {
    switch (category) {
      case "api":
        return "bg-purple-100 text-purple-800";
      case "network":
        return "bg-blue-100 text-blue-800";
      case "auth":
        return "bg-red-100 text-red-800";
      case "validation":
        return "bg-yellow-100 text-yellow-800";
      case "ui":
        return "bg-green-100 text-green-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  // Only show in development or when explicitly enabled
  if (!import.meta.env.DEV && !showDashboard) {
    return (
      <button
        onClick={() => setShowDashboard(true)}
        className="fixed bottom-4 right-4 bg-red-600 text-white p-3 rounded-full shadow-lg hover:bg-red-700 transition-colors z-50"
        title="عرض لوحة الأخطاء"
      >
        <ExclamationTriangleIcon className="w-6 h-6" />
        {errors.length > 0 && (
          <span className="absolute -top-1 -right-1 bg-yellow-400 text-black text-xs font-bold rounded-full w-5 h-5 flex items-center justify-center">
            {errors.length}
          </span>
        )}
      </button>
    );
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-2xl w-full max-w-6xl max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="bg-gradient-to-r from-red-600 to-red-700 text-white p-6 flex items-center justify-between">
          <div className="flex items-center">
            <ExclamationTriangleIcon className="w-8 h-8 ml-3" />
            <div>
              <h2 className="text-2xl font-bold">لوحة تتبع الأخطاء</h2>
              <p className="text-red-100 text-sm">
                {errors.length} خطأ مسجل | {filteredErrors.length} ظاهر
              </p>
            </div>
          </div>
          <button
            onClick={() => setShowDashboard(false)}
            className="text-white hover:bg-red-800 p-2 rounded transition-colors"
          >
            <XMarkIcon className="w-6 h-6" />
          </button>
        </div>

        {/* Filters & Actions */}
        <div className="bg-gray-50 border-b border-gray-200 p-4">
          <div className="flex flex-wrap items-center gap-3">
            {/* Search */}
            <div className="flex-1 min-w-64">
              <div className="relative">
                <MagnifyingGlassIcon className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  placeholder="بحث في الأخطاء..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pr-10 pl-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent"
                />
              </div>
            </div>

            {/* Category Filter */}
            <select
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent"
            >
              <option value="all">كل الأنواع</option>
              <option value="api">API</option>
              <option value="network">شبكة</option>
              <option value="auth">مصادقة</option>
              <option value="validation">تحقق</option>
              <option value="ui">واجهة</option>
              <option value="unknown">غير معروف</option>
            </select>

            {/* Severity Filter */}
            <select
              value={filterSeverity}
              onChange={(e) => setFilterSeverity(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent"
            >
              <option value="all">كل الخطورات</option>
              <option value="critical">حرجة</option>
              <option value="high">عالية</option>
              <option value="medium">متوسطة</option>
              <option value="low">منخفضة</option>
            </select>

            {/* Actions */}
            <div className="flex gap-2">
              <button
                onClick={handleExportJSON}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2"
                title="تصدير JSON"
              >
                <ArrowDownTrayIcon className="w-4 h-4" />
                JSON
              </button>
              <button
                onClick={handleExportCSV}
                className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors flex items-center gap-2"
                title="تصدير CSV"
              >
                <ArrowDownTrayIcon className="w-4 h-4" />
                CSV
              </button>
              <button
                onClick={handleClearErrors}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors flex items-center gap-2"
                title="مسح الكل"
              >
                <TrashIcon className="w-4 h-4" />
                مسح
              </button>
            </div>
          </div>
        </div>

        {/* Errors List */}
        <div className="flex-1 overflow-y-auto p-4">
          {filteredErrors.length === 0 ? (
            <div className="text-center py-12 text-gray-500">
              <ExclamationTriangleIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
              <p className="text-lg font-medium">لا توجد أخطاء مسجلة</p>
              <p className="text-sm">هذا رائع! النظام يعمل بشكل صحيح</p>
            </div>
          ) : (
            <div className="space-y-3">
              {filteredErrors.map((error) => (
                <div
                  key={error.id}
                  className={`border rounded-lg p-4 ${getSeverityColor(
                    error.severity,
                  )}`}
                >
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span
                          className={`px-2 py-1 rounded text-xs font-medium ${getCategoryColor(
                            error.category,
                          )}`}
                        >
                          {error.category}
                        </span>
                        <span className="text-xs text-gray-500">
                          {new Date(error.timestamp).toLocaleString("ar-EG")}
                        </span>
                      </div>
                      <p className="font-medium mb-1">{error.message}</p>
                      {error.context && (
                        <details className="text-sm opacity-80">
                          <summary className="cursor-pointer hover:underline">
                            عرض التفاصيل
                          </summary>
                          <pre className="mt-2 p-2 bg-black bg-opacity-10 rounded text-xs overflow-auto max-h-40">
                            {JSON.stringify(error.context, null, 2)}
                          </pre>
                        </details>
                      )}
                      {error.stack && (
                        <details className="text-sm opacity-80 mt-2">
                          <summary className="cursor-pointer hover:underline">
                            Stack Trace
                          </summary>
                          <pre
                            className="mt-2 p-2 bg-black bg-opacity-10 rounded text-xs overflow-auto max-h-40 text-left"
                            dir="ltr"
                          >
                            {error.stack}
                          </pre>
                        </details>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ErrorDashboard;

import React, { useState, useEffect } from "react";
import { ShoppingCartIcon, PlusIcon } from "@heroicons/react/24/outline";
import { apiClient } from "../services/apiClient";

interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  salePrice?: number | undefined;
  images: string[];
  stock: number;
}

interface FrequentlyBoughtTogetherProps {
  productId: string;
  companyId: string;
  currentProduct: Product;
  onAddToCart: (productIds: string[]) => void;
}

const FrequentlyBoughtTogether: React.FC<FrequentlyBoughtTogetherProps> = ({
  productId,
  companyId,
  currentProduct,
  onAddToCart,
}) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedProducts, setSelectedProducts] = useState<Set<string>>(
    new Set([productId]),
  );

  const parseImages = (images: string | string[] | undefined): string[] => {
    if (!images) return [];
    if (Array.isArray(images)) return images;
    if (typeof images === "string") {
      try {
        const parsed = JSON.parse(images);
        return Array.isArray(parsed) ? parsed : [images];
      } catch {
        return [images];
      }
    }
    return [];
  };

  useEffect(() => {
    fetchFrequentlyBought();
  }, [productId, companyId]);

  const fetchFrequentlyBought = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(
        `/public/products/${productId}/frequently-bought-together`,
        {
          params: { companyId, limit: 3 },
        },
      );

      if (response.data.success) {
        const productsWithParsedImages = response.data.data.map(
          (product: any) => ({
            ...product,
            images: parseImages(product.images),
            salePrice: product.salePrice || product.comparePrice || undefined,
          }),
        );
        setProducts(productsWithParsedImages);
      }
    } catch (error) {
      console.error("❌ [FREQUENTLY-BOUGHT] Error:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleToggleProduct = (id: string) => {
    const newSelected = new Set(selectedProducts);
    if (newSelected.has(id)) {
      if (id !== productId) { // Prevent unselecting current product for logical consistency
        newSelected.delete(id);
      }
    } else {
      newSelected.add(id);
    }
    setSelectedProducts(newSelected);
  };

  const calculateTotal = () => {
    let total = 0;
    if (selectedProducts.has(productId)) {
      total += Number(currentProduct.salePrice || currentProduct.price || 0);
    }
    products.forEach((product) => {
      if (selectedProducts.has(product.id)) {
        total += Number(product.salePrice || product.price || 0);
      }
    });
    return total;
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
      minimumFractionDigits: 0,
    }).format(price);
  };

  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#1a1a2e]"></div>
      </div>
    );
  }

  if (products.length === 0) return null;

  const allProducts = [currentProduct, ...products];

  return (
    <div className="mt-12 p-6 md:p-8 bg-[#fcfbf7] border border-[#c9a96e]/20 rounded-2xl shadow-sm">
      <h3 className="text-xl font-black text-[#1a1a2e] mb-6 flex items-center gap-2">
        <ShoppingCartIcon className="h-6 w-6 text-[#c9a96e]" />
        <span>يُشترى معاً عادة</span>
      </h3>

      <div className="flex flex-col md:flex-row items-center gap-6 mb-8">
        {allProducts.map((product, index) => {
          const isCurrentProduct = product.id === productId;
          const displayPrice = product.salePrice || product.price;
          const isSelected = selectedProducts.has(product.id);
          const productImages = parseImages(product.images);
          const productImage = productImages.length > 0 ? productImages[0] : "";

          return (
            <React.Fragment key={product.id}>
              {index > 0 && (
                <div className="flex items-center justify-center">
                  <PlusIcon className="h-6 w-6 text-gray-300" />
                </div>
              )}

              <div
                className={`relative group cursor-pointer transition-all duration-300 ${isSelected ? "opacity-100" : "opacity-60 grayscale hover:grayscale-0 hover:opacity-80"
                  }`}
                onClick={() => handleToggleProduct(product.id)}
              >
                <div className={`w-32 h-40 md:w-40 md:h-48 rounded-xl overflow-hidden border-2 transition-colors ${isSelected ? "border-[#c9a96e]" : "border-transparent"
                  }`}>
                  <img
                    src={productImage}
                    alt={product.name}
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                  />
                  {isCurrentProduct && (
                    <div className="absolute top-2 right-2 bg-[#1a1a2e] text-white text-[9px] px-2 py-0.5 rounded-full uppercase tracking-tighter">
                      الحالي
                    </div>
                  )}
                </div>
                <div className="mt-3 text-center">
                  <p className="text-xs font-bold text-[#1a1a2e] truncate w-32 md:w-40">{product.name}</p>
                  <p className="text-sm font-black text-[#c9a96e] mt-0.5">{formatPrice(displayPrice)}</p>
                </div>

                {/* Custom Checkbox overlay */}
                {!isCurrentProduct && (
                  <div className={`absolute -top-2 -left-2 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors ${isSelected ? "bg-[#c9a96e] border-[#c9a96e]" : "bg-white border-gray-300"
                    }`}>
                    {isSelected && (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-white" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                      </svg>
                    )}
                  </div>
                )}
              </div>
            </React.Fragment>
          );
        })}
      </div>

      <div className="border-t border-[#c9a96e]/10 pt-6 flex flex-col sm:flex-row justify-between items-center gap-6">
        <div>
          <p className="text-xs text-gray-500 mb-1">
            الإجمالي للمنتجات المحددة ({selectedProducts.size})
          </p>
          <p className="text-2xl font-black text-[#1a1a2e]">
            {formatPrice(calculateTotal())}
          </p>
        </div>

        <button
          onClick={() => onAddToCart(Array.from(selectedProducts))}
          disabled={selectedProducts.size === 0}
          className="w-full sm:w-auto px-10 py-4 bg-[#1a1a2e] text-white rounded-xl font-bold hover:bg-[#c9a96e] transition-all duration-300 flex items-center justify-center gap-3 shadow-lg shadow-[#1a1a2e]/20 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <ShoppingCartIcon className="h-5 w-5" />
          <span>أضف المحدد للسلة</span>
        </button>
      </div>
    </div>
  );
};

export default FrequentlyBoughtTogether;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Search, RefreshCw, MessageSquare, TrendingUp } from 'lucide-react';

const PostsManagement = () => {
  const { t } = useTranslation();
  const [searchTerm, setSearchTerm] = useState('');
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);

  // Mock data for demonstration - replace with actual API calls
  const mockPosts = [
    {
      id: '123456789',
      content: 'Sample post content about AI tracking...',
      engagement: 45,
      comments: 12,
      shares: 8,
      createdAt: '2026-02-18T10:30:00Z'
    }
  ];

  useEffect(() => {
    loadPosts();
  }, []);

  const loadPosts = async () => {
    setLoading(true);
    try {
      // Simulate API call
      setTimeout(() => {
        setPosts(mockPosts);
        setLoading(false);
      }, 1000);
    } catch (error) {
      console.error('Error loading posts:', error);
      setLoading(false);
    }
  };

  const handleUpdate = async () => {
    setIsUpdating(true);
    try {
      // Simulate update API call
      setTimeout(() => {
        loadPosts();
        setIsUpdating(false);
      }, 1500);
    } catch (error) {
      console.error('Error updating posts:', error);
      setIsUpdating(false);
    }
  };

  const filteredPosts = posts.filter(post =>
    post.id.includes(searchTerm) || 
    post.content.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="posts-management">
      {/* Header */}
      <div className="header-section">
        <div className="title-section">
          <MessageSquare className="header-icon" size={32} />
          <div>
            <h1 className="main-title">{t('posts.management.title')}</h1>
            <p className="subtitle">{t('posts.management.subtitle')}</p>
          </div>
        </div>
        
        <button 
          onClick={handleUpdate}
          disabled={isUpdating}
          className="update-button"
        >
          <RefreshCw className={`icon ${isUpdating ? 'spinning' : ''}`} size={16} />
          {t('posts.update.button')}
        </button>
      </div>

      {/* Search Section */}
      <div className="search-section">
        <div className="search-container">
          <Search className="search-icon" size={20} />
          <input
            type="text"
            placeholder={t('posts.search.placeholder')}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
      </div>

      {/* Posts Content */}
      <div className="posts-content">
        {loading ? (
          <div className="loading-state">
            <div className="loading-spinner"></div>
            <p>{t('common.loading')}</p>
          </div>
        ) : filteredPosts.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">
              <MessageSquare size={64} />
            </div>
            <p className="empty-message">{t('posts.empty.message')}</p>
          </div>
        ) : (
          <div className="posts-grid">
            {filteredPosts.map(post => (
              <div key={post.id} className="post-card">
                <div className="post-header">
                  <span className="post-id">ID: {post.id}</span>
                  <div className="post-engagement">
                    <TrendingUp size={16} />
                    <span>{post.engagement}</span>
                  </div>
                </div>
                <div className="post-content">
                  <p>{post.content}</p>
                </div>
                <div className="post-stats">
                  <div className="stat">
                    <MessageSquare size={14} />
                    <span>{post.comments}</span>
                  </div>
                  <div className="stat">
                    <span>{post.shares} shares</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default PostsManagement;

import React, { useState, useEffect, useCallback } from "react";
import { apiClient } from "../services/apiClient";
import ProductCard, { type ProductCardSettings } from "./storefront/ProductCard";
import { storefrontSettingsService } from "../services/storefrontSettingsService";

interface Product {
  id: string;
  name: string;
  slug?: string;
  description: string;
  price: number;
  salePrice?: number;
  comparePrice?: number;
  images: string[];
  stock: number;
  category?: {
    id: string;
    name: string;
  };
}

interface RelatedProductsProps {
  productId: string;
  companyId: string;
  limit?: number;
  showHeading?: boolean;
  headingText?: string;
}

interface RelatedProductsResponseItem {
  id: string;
  name: string;
  slug?: string;
  description?: string;
  price?: number | string;
  salePrice?: number | string;
  comparePrice?: number | string;
  images?: string[] | string;
  stock?: number;
  category?: {
    id: string;
    name: string;
  };
}

const RelatedProducts: React.FC<RelatedProductsProps> = ({
  productId,
  companyId,
  limit = 6,
  showHeading = true,
  headingText = "🔍 منتجات قد تعجبك",
}) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [globalSettings, setGlobalSettings] = useState<
    ProductCardSettings | null
  >(null);

  const loadGlobalSettings = useCallback(async () => {
    try {
      if (companyId) {
        const data = await storefrontSettingsService.getPublicSettings(companyId);
        if (data.success && data.data) {
          setGlobalSettings({
            productCardStyle: data.data.productCardStyle as any,
            gridAddToCartIcon: data.data.gridAddToCartIcon as any,
            gridDiscountBanner: data.data.gridDiscountBanner as any,
            currency: (data.data as any).currency || "جنيه",
          } as any);
        }
      }
    } catch (error) {
      console.warn("[RelatedProducts] Error loading global settings");
    }
  }, [companyId]);

  const parseImages = (images: string | string[] | undefined): string[] => {
    if (!images) return [];
    if (Array.isArray(images)) return images;
    if (typeof images === "string") {
      try {
        const parsed = JSON.parse(images);
        return Array.isArray(parsed) ? parsed : [images];
      } catch {
        return [images];
      }
    }
    return [];
  };

  const fetchRelatedProducts = useCallback(async () => {
    if (!companyId || !productId) {
      return;
    }
    
    try {
      setLoading(true);
      const response = await apiClient.get(
        `/public/products/${productId}/related`,
        {
          params: { companyId, limit },
        },
      );

      if (response.data.success) {
        const productsWithParsedData = (response.data.data as RelatedProductsResponseItem[]).map(
          (product) => ({
            ...product,
            images: parseImages(product.images),
            price: Number(product.price) || 0,
            salePrice: product.salePrice
              ? Number(product.salePrice)
              : undefined,
            comparePrice: product.comparePrice
              ? Number(product.comparePrice)
              : undefined,
          }),
        );
        setProducts(productsWithParsedData as Product[]);
      }
    } catch (error) {
      console.error("❌ [RELATED-PRODUCTS] Error:", error);
    } finally {
      setLoading(false);
    }
  }, [companyId, limit, productId]);

  useEffect(() => {
    void fetchRelatedProducts();
    void loadGlobalSettings();
  }, [fetchRelatedProducts, loadGlobalSettings]);

  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
      </div>
    );
  }

  if (products.length === 0) return null;

  return (
    <div className="mt-12">
      {showHeading && (
        <h3 className="text-2xl font-black text-[#1a1a2e] mb-8 relative inline-block">
          {headingText}
          <span className="absolute -bottom-2 right-0 w-12 h-1 bg-[#c9a96e]"></span>
        </h3>
      )}

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-6">
        {products.map((product) => (
          <ProductCard
            key={product.id}
            product={{
              id: product.id,
              name: product.name,
              slug: product.slug,
              price: product.price,
              comparePrice: product.comparePrice,
              salePrice: product.salePrice,
              images: product.images,
            }}
            settings={{
              productCardStyle: globalSettings?.productCardStyle,
              gridAddToCartIcon: globalSettings?.gridAddToCartIcon,
              gridDiscountBanner: globalSettings?.gridDiscountBanner,
            }}
            companyId={companyId}
            onAddToCart={() => {
              window.dispatchEvent(new Event("cartUpdated"));
            }}
            currencyLabel={(globalSettings as any)?.currency || "جنيه"}
          />
        ))}
      </div>
    </div>
  );
};

export default RelatedProducts;

import React, { useEffect, useState } from "react";
import { TagIcon } from "@heroicons/react/24/outline";

interface VolumeDiscount {
  id: string;
  minQuantity: number;
  maxQuantity: number | null;
  discountType: "percentage" | "fixed";
  discountValue: number;
}

interface Props {
  productId: string;
  quantity: number;
}

const VolumeDiscountBadge: React.FC<Props> = ({ productId, quantity }) => {
  const [discounts, setDiscounts] = useState<VolumeDiscount[]>([]);
  const [applicableDiscount, setApplicableDiscount] =
    useState<VolumeDiscount | null>(null);

  useEffect(() => {
    let isCancelled = false;

    const loadDiscounts = async () => {
      try {
        const {
          getMarketplacePreviewProduct,
          resolveMarketplacePreviewThemeId,
        } = await import("../storefront/preview/marketplaceSampleData");
        const { getProductVolumeDiscounts } = await import(
          "../storefront/utils/volumeDiscounts"
        );

        const previewThemeId = resolveMarketplacePreviewThemeId();
        if (previewThemeId) {
          const previewProduct = getMarketplacePreviewProduct(
            productId,
            previewThemeId,
          );
          if (!isCancelled && previewProduct) {
            setDiscounts(getProductVolumeDiscounts(previewProduct));
          }
          return;
        }

        // Use storefrontFetch for public storefront routes outside preview mode.
        const { storefrontFetch } = await import("../utils/storefrontApi");
        const response = await storefrontFetch(
          `/products/${productId}/volume-discounts`,
        );

        if (!isCancelled) {
          if (response && response.success && response.data) {
            setDiscounts(Array.isArray(response.data) ? response.data : []);
          } else {
            setDiscounts([]);
          }
        }
      } catch (error: any) {
        // Silently handle errors - endpoint might not exist or product has no discounts
        if (error?.response?.status !== 404) {
          // Only log non-404 errors
          console.error("Error fetching volume discounts:", error);
        }

        if (!isCancelled) {
          setDiscounts([]);
        }
      }
    };

    void loadDiscounts();

    return () => {
      isCancelled = true;
    };
  }, [productId]);

  useEffect(() => {
    findApplicableDiscount();
  }, [quantity, discounts]);

  const findApplicableDiscount = () => {
    if (!discounts.length) {
      setApplicableDiscount(null);
      return;
    }

    const applicable = [...discounts]
      .filter((discount) => {
        const maxQty = discount.maxQuantity || 999999;
        return quantity >= discount.minQuantity && quantity <= maxQty;
      })
      .sort((left, right) => right.minQuantity - left.minQuantity)[0];

    setApplicableDiscount(applicable || null);
  };

  if (!discounts.length) {
    return null;
  }

  return (
    <div className="mt-4 space-y-3">
      {/* Current Discount Badge */}
      {applicableDiscount && (
        <div className="flex items-center gap-2 p-3 bg-green-50 border border-green-200 rounded-lg">
          <TagIcon className="h-5 w-5 text-green-600" />
          <div>
            <div className="text-sm font-bold text-green-800">
              خصم{" "}
              {applicableDiscount.discountType === "percentage"
                ? `${applicableDiscount.discountValue}%`
                : `${applicableDiscount.discountValue} جنيه`}{" "}
              مطبق!
            </div>
            <div className="text-xs text-green-600">على الكمية {quantity}</div>
          </div>
        </div>
      )}

      {/* All Available Discounts */}
      <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
        <div className="flex items-center gap-2 mb-3">
          <TagIcon className="h-5 w-5 text-blue-600" />
          <h3 className="text-sm font-bold text-blue-900">
            خصومات الكميات المتاحة:
          </h3>
        </div>

        <div className="space-y-2">
          {discounts.map((discount) => {
            const isActive = applicableDiscount?.id === discount.id;
            const maxQty = discount.maxQuantity || "∞";

            return (
              <div
                key={discount.id}
                className={`flex items-center justify-between p-2 rounded ${
                  isActive
                    ? "bg-green-100 border border-green-300"
                    : "bg-white border border-blue-200"
                }`}
              >
                <div className="text-sm">
                  <span className="font-medium text-gray-900">
                    {discount.minQuantity} - {maxQty} قطعة
                  </span>
                </div>
                <div
                  className={`text-sm font-bold ${
                    isActive ? "text-green-700" : "text-blue-700"
                  }`}
                >
                  {discount.discountType === "percentage"
                    ? `خصم ${discount.discountValue}%`
                    : `خصم ${discount.discountValue} جنيه`}
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-3 text-xs text-blue-600">
          💡 اشتري كميات أكبر واحصل على خصم أفضل!
        </div>
      </div>
    </div>
  );
};

export default VolumeDiscountBadge;

import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Alert,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Switch,
  FormControlLabel,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Percent as PercentIcon,
  AttachMoney as MoneyIcon,
} from "@mui/icons-material";
import { apiClient } from "../services/apiClient";

interface VolumeDiscount {
  id: string;
  minQuantity: number;
  maxQuantity: number | null;
  discountType: "percentage" | "fixed";
  discountValue: number;
  isActive: boolean;
}

interface VolumeDiscountsProps {
  productId: string;
}

const VolumeDiscounts: React.FC<VolumeDiscountsProps> = ({ productId }) => {
  const [discounts, setDiscounts] = useState<VolumeDiscount[]>([]);
  const [loading, setLoading] = useState(true);
  const [openDialog, setOpenDialog] = useState(false);
  const [editingDiscount, setEditingDiscount] = useState<VolumeDiscount | null>(
    null,
  );
  const [message, setMessage] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  const [formData, setFormData] = useState({
    minQuantity: 2,
    maxQuantity: null as number | null,
    discountType: "percentage" as "percentage" | "fixed",
    discountValue: 10,
    isActive: true,
  });

  useEffect(() => {
    if (productId) {
      fetchDiscounts();
    }
  }, [productId]);

  const fetchDiscounts = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(
        `/products/${productId}/volume-discounts`,
      );

      if (response.data.success) {
        setDiscounts(response.data.data);
      }
    } catch (error: any) {
      console.error("Error fetching volume discounts:", error);
      setMessage({
        type: "error",
        text: "فشل في جلب خصومات الكميات",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (discount?: VolumeDiscount) => {
    if (discount) {
      setEditingDiscount(discount);
      setFormData({
        minQuantity: discount.minQuantity,
        maxQuantity: discount.maxQuantity,
        discountType: discount.discountType,
        discountValue: discount.discountValue,
        isActive: discount.isActive,
      });
    } else {
      setEditingDiscount(null);
      setFormData({
        minQuantity: 2,
        maxQuantity: null,
        discountType: "percentage",
        discountValue: 10,
        isActive: true,
      });
    }
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setEditingDiscount(null);
  };

  const handleSave = async () => {
    try {
      if (editingDiscount) {
        // Update
        await apiClient.put(
          `/products/${productId}/volume-discounts/${editingDiscount.id}`,
          formData,
        );
        setMessage({ type: "success", text: "تم تحديث الخصم بنجاح" });
      } else {
        // Create
        await apiClient.post(
          `/products/${productId}/volume-discounts`,
          formData,
        );
        setMessage({ type: "success", text: "تم إضافة الخصم بنجاح" });
      }

      handleCloseDialog();
      fetchDiscounts();
    } catch (error: any) {
      console.error("Error saving volume discount:", error);
      setMessage({
        type: "error",
        text: error.response?.data?.message || "فشل في حفظ الخصم",
      });
    }
  };

  const handleDelete = async (discountId: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا الخصم؟")) {
      return;
    }

    try {
      await apiClient.delete(
        `/products/${productId}/volume-discounts/${discountId}`,
      );
      setMessage({ type: "success", text: "تم حذف الخصم بنجاح" });
      fetchDiscounts();
    } catch (error: any) {
      console.error("Error deleting volume discount:", error);
      setMessage({
        type: "error",
        text: "فشل في حذف الخصم",
      });
    }
  };

  const formatDiscount = (discount: VolumeDiscount) => {
    if (discount.discountType === "percentage") {
      return `${discount.discountValue}%`;
    } else {
      return `${discount.discountValue} جنيه`;
    }
  };

  const formatQuantityRange = (discount: VolumeDiscount) => {
    if (discount.maxQuantity) {
      return `${discount.minQuantity} - ${discount.maxQuantity}`;
    } else {
      return `${discount.minQuantity}+`;
    }
  };

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 2,
        }}
      >
        <Box>
          <Typography variant="h6" gutterBottom>
            💰 خصومات الكميات
          </Typography>
          <Typography variant="body2" color="text.secondary">
            قم بإضافة خصومات تلقائية عند شراء كميات معينة من المنتج
          </Typography>
        </Box>
        <Button
          variant="contained"
          size="small"
          startIcon={<AddIcon />}
          onClick={() => handleOpenDialog()}
        >
          إضافة خصم
        </Button>
      </Box>

      {message && (
        <Alert
          severity={message.type}
          sx={{ mb: 2 }}
          onClose={() => setMessage(null)}
        >
          {message.text}
        </Alert>
      )}

      <Card variant="outlined">
        <CardContent>
          <TableContainer component={Paper} variant="outlined">
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>نطاق الكمية</TableCell>
                  <TableCell>نوع الخصم</TableCell>
                  <TableCell>قيمة الخصم</TableCell>
                  <TableCell>الحالة</TableCell>
                  <TableCell align="center">الإجراءات</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {discounts.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={5} align="center">
                      <Box py={3}>
                        <PercentIcon
                          sx={{ fontSize: 48, color: "text.secondary", mb: 1 }}
                        />
                        <Typography variant="body2" color="text.secondary">
                          لا توجد خصومات كميات. قم بإضافة خصم لتحفيز العملاء على
                          الشراء بكميات أكبر
                        </Typography>
                      </Box>
                    </TableCell>
                  </TableRow>
                ) : (
                  discounts.map((discount) => (
                    <TableRow key={discount.id}>
                      <TableCell>
                        {formatQuantityRange(discount)} قطعة
                      </TableCell>
                      <TableCell>
                        <Chip
                          icon={
                            discount.discountType === "percentage" ? (
                              <PercentIcon />
                            ) : (
                              <MoneyIcon />
                            )
                          }
                          label={
                            discount.discountType === "percentage"
                              ? "نسبة مئوية"
                              : "مبلغ ثابت"
                          }
                          size="small"
                          color="primary"
                          variant="outlined"
                        />
                      </TableCell>
                      <TableCell>
                        <Typography
                          variant="body2"
                          fontWeight="bold"
                          color="success.main"
                        >
                          {formatDiscount(discount)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={discount.isActive ? "نشط" : "معطل"}
                          color={discount.isActive ? "success" : "default"}
                          size="small"
                        />
                      </TableCell>
                      <TableCell align="center">
                        <IconButton
                          size="small"
                          onClick={() => handleOpenDialog(discount)}
                          color="primary"
                        >
                          <EditIcon fontSize="small" />
                        </IconButton>
                        <IconButton
                          size="small"
                          onClick={() => handleDelete(discount.id)}
                          color="error"
                        >
                          <DeleteIcon fontSize="small" />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {discounts.length > 0 && (
            <Box sx={{ mt: 2, p: 2, bgcolor: "info.light", borderRadius: 1 }}>
              <Typography
                variant="caption"
                color="text.secondary"
                gutterBottom
                display="block"
              >
                💡 نصيحة:
              </Typography>
              <Typography variant="body2">
                تأكد من عدم تداخل نطاقات الكميات. سيتم تطبيق الخصم تلقائياً عند
                إضافة المنتج للسلة.
              </Typography>
            </Box>
          )}
        </CardContent>
      </Card>

      {/* Add/Edit Dialog */}
      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          {editingDiscount ? "تعديل خصم الكمية" : "إضافة خصم كمية جديد"}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 2 }}>
            <TextField
              label="الحد الأدنى للكمية"
              type="number"
              fullWidth
              required
              value={formData.minQuantity}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  minQuantity: parseInt(e.target.value) || 1,
                })
              }
              InputProps={{ inputProps: { min: 1 } }}
              helperText="الكمية التي يبدأ عندها الخصم"
            />

            <TextField
              label="الحد الأقصى للكمية (اختياري)"
              type="number"
              fullWidth
              value={formData.maxQuantity || ""}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  maxQuantity: e.target.value ? parseInt(e.target.value) : null,
                })
              }
              InputProps={{ inputProps: { min: formData.minQuantity } }}
              helperText="اتركه فارغاً لعدم وجود حد أقصى"
            />

            <FormControl fullWidth required>
              <InputLabel>نوع الخصم</InputLabel>
              <Select
                value={formData.discountType}
                label="نوع الخصم"
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    discountType: e.target.value as "percentage" | "fixed",
                  })
                }
              >
                <MenuItem value="percentage">
                  <Box display="flex" alignItems="center" gap={1}>
                    <PercentIcon fontSize="small" />
                    نسبة مئوية
                  </Box>
                </MenuItem>
                <MenuItem value="fixed">
                  <Box display="flex" alignItems="center" gap={1}>
                    <MoneyIcon fontSize="small" />
                    مبلغ ثابت
                  </Box>
                </MenuItem>
              </Select>
            </FormControl>

            <TextField
              label={
                formData.discountType === "percentage"
                  ? "نسبة الخصم (%)"
                  : "مبلغ الخصم (جنيه)"
              }
              type="number"
              fullWidth
              required
              value={formData.discountValue}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  discountValue: parseFloat(e.target.value) || 0,
                })
              }
              InputProps={{
                inputProps: {
                  min: 0,
                  max: formData.discountType === "percentage" ? 100 : undefined,
                  step: formData.discountType === "percentage" ? 1 : 5,
                },
              }}
              helperText={
                formData.discountType === "percentage"
                  ? "النسبة المئوية للخصم (0-100)"
                  : "المبلغ الذي سيتم خصمه من السعر"
              }
            />

            <FormControlLabel
              control={
                <Switch
                  checked={formData.isActive}
                  onChange={(e) =>
                    setFormData({ ...formData, isActive: e.target.checked })
                  }
                />
              }
              label="تفعيل الخصم"
            />

            {/* Preview */}
            <Box sx={{ p: 2, bgcolor: "success.light", borderRadius: 1 }}>
              <Typography
                variant="caption"
                color="text.secondary"
                gutterBottom
                display="block"
              >
                معاينة:
              </Typography>
              <Typography variant="body2" fontWeight="medium">
                عند شراء {formData.minQuantity}
                {formData.maxQuantity ? ` - ${formData.maxQuantity}` : "+"}{" "}
                قطعة، سيحصل العميل على خصم {formData.discountValue}
                {formData.discountType === "percentage" ? "%" : " جنيه"}
              </Typography>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>إلغاء</Button>
          <Button onClick={handleSave} variant="contained">
            {editingDiscount ? "تحديث" : "إضافة"}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

