  String(value || "")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();

const formatCount = (value: number) =>
  new Intl.NumberFormat("ar-EG").format(value);

const buildDefaultState = (): Record<PolicyPageType, StorePolicyPage> => ({
  SHIPPING_POLICY: {
    id: null,
    pageType: "SHIPPING_POLICY",
    title: POLICY_CONFIG.SHIPPING_POLICY.title,
    slug: POLICY_CONFIG.SHIPPING_POLICY.slug,
    content: "",
    isActive: true,
    showInFooter: false,
    showInMenu: false,
    order: POLICY_CONFIG.SHIPPING_POLICY.order,
  },
  RETURN_POLICY: {
    id: null,
    pageType: "RETURN_POLICY",
    title: POLICY_CONFIG.RETURN_POLICY.title,
    slug: POLICY_CONFIG.RETURN_POLICY.slug,
    content: "",
    isActive: true,
    showInFooter: false,
    showInMenu: false,
    order: POLICY_CONFIG.RETURN_POLICY.order,
  },
  REFUND_POLICY: {
    id: null,
    pageType: "REFUND_POLICY",
    title: POLICY_CONFIG.REFUND_POLICY.title,
    slug: POLICY_CONFIG.REFUND_POLICY.slug,
    content: "",
    isActive: true,
    showInFooter: false,
    showInMenu: false,
    order: POLICY_CONFIG.REFUND_POLICY.order,
  },
});

const KnowledgeBasePoliciesSettings: React.FC = () => {
  const [policies, setPolicies] = useState<Record<PolicyPageType, StorePolicyPage>>(
    buildDefaultState(),
  );
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const stats = useMemo(() => {
    const values = POLICY_ORDER.map((type) => policies[type]);
    const configured = values.filter((item) => stripHtml(item.content).length > 0)
      .length;
    const active = values.filter(
      (item) => item.isActive && stripHtml(item.content).length > 0,
    ).length;
    const visible = values.filter(
      (item) => item.showInFooter && stripHtml(item.content).length > 0,
    ).length;

    return { configured, active, visible };
  }, [policies]);

  const fetchPolicies = async () => {
    setLoading(true);
    setErrorMessage(null);

    try {
      const response = await companyAwareApi.post<StorePagesResponse>(
        "/store-pages/list?includeInactive=true",
        {},
      );

      const nextState = buildDefaultState();
      (response.data?.data || [])
        .filter((page) => POLICY_ORDER.includes(page.pageType))
        .forEach((page) => {
          nextState[page.pageType] = {
            id: page.id,
            pageType: page.pageType,
            title: page.title || POLICY_CONFIG[page.pageType].title,
            slug: page.slug || POLICY_CONFIG[page.pageType].slug,
            content: page.content || "",
            isActive: page.isActive,
            showInFooter: page.showInFooter,
            showInMenu: page.showInMenu,
            order: page.order ?? POLICY_CONFIG[page.pageType].order,
          };
        });

      setPolicies(nextState);
    } catch (error: any) {
      console.error("Error loading knowledge base policies:", error);
      setErrorMessage(
        error?.response?.data?.error ||
          "فشل تحميل سياسات الشحن والإرجاع من قاعدة البيانات.",
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPolicies();
  }, []);

  const updatePolicy = (
    pageType: PolicyPageType,
    updates: Partial<StorePolicyPage>,
  ) => {
    setPolicies((current) => ({
      ...current,
      [pageType]: {
        ...current[pageType],
        ...updates,
      },
    }));
  };

  const savePolicies = async () => {
    setSaving(true);
    setErrorMessage(null);

    try {
      for (const pageType of POLICY_ORDER) {
        const policy = policies[pageType];
        const trimmedContent = stripHtml(policy.content);
        const payload = {
          title: policy.title.trim() || POLICY_CONFIG[pageType].title,
          slug: policy.slug.trim() || POLICY_CONFIG[pageType].slug,
          content: policy.content || "",
          pageType,
          isActive: trimmedContent.length > 0 ? policy.isActive : false,
          showInFooter: policy.showInFooter,
          showInMenu: false,
          order: policy.order,
        };

        if (!policy.id && trimmedContent.length === 0) {
          continue;
        }

        if (policy.id) {
          await companyAwareApi.put(`/store-pages/page/${policy.id}`, payload);
        } else {
          await companyAwareApi.post("/store-pages", payload);
        }
      }

      await fetchPolicies();
      toast.success("تم حفظ سياسات المعرفة وتحديث RAG الخاص بالشركة بنجاح.");
    } catch (error: any) {
      console.error("Error saving knowledge base policies:", error);
      const message =
        error?.response?.data?.error ||
        "فشل حفظ السياسات. راجع الحقول ثم حاول مرة أخرى.";
      setErrorMessage(message);
      toast.error(message);
    } finally {
      setSaving(false);
    }
  };

  const refreshKnowledgeBase = async () => {
    setRefreshing(true);
    setErrorMessage(null);

    try {
      await companyAwareApi.post("/ai/knowledge-base/update", {});
      toast.success("تمت إعادة تحميل قاعدة المعرفة للشركة بنجاح.");
    } catch (error: any) {
      console.error("Error refreshing knowledge base:", error);
      const message =
        error?.response?.data?.error ||
        "فشل تحديث قاعدة المعرفة يدويًا. حاول مرة أخرى.";
      setErrorMessage(message);
      toast.error(message);
    } finally {
      setRefreshing(false);
    }
  };

  if (loading) {
    return (
      <Card className="border-dashed" dir="rtl">
        <CardContent className="flex flex-col items-center justify-center gap-4 py-16">
          <div className="flex size-14 items-center justify-center rounded-full bg-primary/10 text-primary">
            <Loader2 className="size-6 animate-spin" />
          </div>
          <div className="space-y-1 text-center">
            <p className="text-sm font-medium text-foreground">
              جاري تحميل سياسات قاعدة المعرفة
            </p>
            <p className="text-sm text-muted-foreground">
              نجهز سياسات الشحن والإرجاع والاسترجاع المالي الخاصة بالشركة.
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      <Card className="overflow-hidden border-none bg-gradient-to-br from-slate-950 via-slate-900 to-slate-800 text-white shadow-xl">
        <CardHeader className="gap-5">
          <div className="flex flex-col gap-6 xl:flex-row xl:items-start xl:justify-between">
            <div className="space-y-4">
              <Badge className="w-fit rounded-full border-white/15 bg-white/10 px-3 py-1 text-white hover:bg-white/10">
                <Brain className="size-3.5" />
                معرفة RAG الخاصة بالشركة
              </Badge>

              <div className="space-y-2">
                <CardTitle className="text-2xl font-semibold text-white">
                  سياسات يقرأها الذكاء قبل أن يرد
                </CardTitle>
                <CardDescription className="max-w-3xl text-sm leading-7 text-slate-200">
                  اكتب هنا المرجع الرسمي لسياسات الشحن، والإرجاع، والاسترجاع
                  المالي. هذا المحتوى يُحمّل داخل معرفة الشركة نفسها، ويُستخدم
                  مباشرة أثناء ردود الـ AI بدل الاعتماد على اجتهاد عام أو ذاكرة
                  غير مكتملة.
                </CardDescription>
              </div>
            </div>

            <div className="flex flex-wrap gap-2">
              <Button
                variant="outline"
                className="border-white/15 bg-white/5 text-white hover:bg-white/10 hover:text-white"
                onClick={refreshKnowledgeBase}
                disabled={refreshing || saving}
              >
                <RefreshCcw
                  className={cn("size-4", refreshing && "animate-spin")}
                />
                <span>{refreshing ? "جاري التحديث..." : "تحديث RAG الآن"}</span>
              </Button>

              <Button
                className="bg-white text-slate-950 hover:bg-slate-100"
                onClick={savePolicies}
                disabled={saving || refreshing}
              >
                <Save className={cn("size-4", saving && "animate-pulse")} />
                <span>{saving ? "جاري الحفظ..." : "حفظ السياسات"}</span>
              </Button>
            </div>
          </div>

          <div className="grid gap-4 md:grid-cols-3">
            <Card className="border-white/10 bg-white/7 text-white shadow-none backdrop-blur-sm">
              <CardContent className="flex items-center justify-between py-1">
                <div className="space-y-1">
                  <p className="text-sm text-slate-300">سياسات مكتملة</p>
                  <p className="text-3xl font-semibold">
                    {formatCount(stats.configured)}/3
                  </p>
                </div>
                <div className="rounded-2xl bg-white/10 p-3">
                  <CheckCircle2 className="size-5 text-emerald-300" />
                </div>
              </CardContent>
            </Card>

            <Card className="border-white/10 bg-white/7 text-white shadow-none backdrop-blur-sm">
              <CardContent className="flex items-center justify-between py-1">
                <div className="space-y-1">
                  <p className="text-sm text-slate-300">مفعلة داخل الردود</p>
                  <p className="text-3xl font-semibold">
                    {formatCount(stats.active)}/3
                  </p>
                </div>
                <div className="rounded-2xl bg-white/10 p-3">
                  <Brain className="size-5 text-sky-300" />
                </div>
              </CardContent>
            </Card>

            <Card className="border-white/10 bg-white/7 text-white shadow-none backdrop-blur-sm">
              <CardContent className="flex items-center justify-between py-1">
                <div className="space-y-1">
                  <p className="text-sm text-slate-300">ظاهرة في المتجر</p>
                  <p className="text-3xl font-semibold">
                    {formatCount(stats.visible)}
                  </p>
                </div>
                <div className="rounded-2xl bg-white/10 p-3">
                  <Eye className="size-5 text-amber-300" />
                </div>
              </CardContent>
            </Card>
          </div>
        </CardHeader>
      </Card>

      {errorMessage && (
        <Alert variant="destructive" className="border-destructive/20 bg-destructive/5">
          <AlertCircle className="size-4" />
          <AlertTitle>تعذر إكمال آخر عملية</AlertTitle>
          <AlertDescription>{errorMessage}</AlertDescription>
          <AlertAction>
            <Button
              variant="outline"
              size="sm"
              className="border-destructive/20"
              onClick={fetchPolicies}
            >
              إعادة المحاولة
            </Button>
          </AlertAction>
        </Alert>
      )}

      <div className="space-y-5">
        {POLICY_ORDER.map((pageType) => {
          const policy = policies[pageType];
          const config = POLICY_CONFIG[pageType];
          const Icon = config.icon;
          const plainTextLength = stripHtml(policy.content).length;
          const hasContent = plainTextLength > 0;

          return (
            <Card
              key={pageType}
              className={cn("shadow-sm", config.panelClassName)}
            >
              <CardHeader className="gap-5">
                <div className="flex flex-col gap-5 xl:flex-row xl:items-start xl:justify-between">
                  <div className="flex items-start gap-4">
                    <div
                      className={cn(
                        "flex size-12 shrink-0 items-center justify-center rounded-2xl ring-1",
                        config.iconWrapClassName,
                      )}
                    >
                      <Icon className="size-5" />
                    </div>

                    <div className="space-y-2">
                      <Badge
                        variant="outline"
                        className={cn("rounded-full px-3 py-1", config.badgeClassName)}
                      >
                        {config.title}
                      </Badge>
                      <CardTitle className="text-xl text-foreground">
                        {policy.title || config.title}
                      </CardTitle>
                      <CardDescription className="max-w-3xl text-sm leading-7">
                        {config.description}
                      </CardDescription>
                    </div>
                  </div>

                  <div className="grid min-w-full gap-3 sm:min-w-[320px] xl:max-w-[360px]">
                    <div className="flex items-center justify-between rounded-2xl border bg-background/80 px-4 py-3 shadow-sm">
                      <div className="space-y-1">
                        <p className="text-sm font-medium text-foreground">
                          تفعيل داخل الردود
                        </p>
                        <p className="text-xs text-muted-foreground">
                          لن تُفعّل السياسة في RAG إلا بعد كتابة محتوى واضح.
                        </p>
                      </div>
                      <Switch
                        checked={hasContent ? policy.isActive : false}
                        onCheckedChange={(checked) =>
                          updatePolicy(pageType, { isActive: Boolean(checked) })
                        }
                        disabled={!hasContent}
                      />
                    </div>

                    <div className="flex items-center justify-between rounded-2xl border bg-background/80 px-4 py-3 shadow-sm">
                      <div className="space-y-1">
                        <p className="text-sm font-medium text-foreground">
                          إظهارها في واجهة المتجر
