                  <div className="space-y-2">
                    <Label htmlFor={`slug-${pageType}`}>الرابط الداخلي</Label>
                    <Input
                      id={`slug-${pageType}`}
                      value={policy.slug}
                      onChange={(event) =>
                        updatePolicy(pageType, { slug: event.target.value })
                      }
                      placeholder={config.slug}
                      dir="ltr"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label>محتوى السياسة</Label>
                  <div className="rounded-2xl bg-background/70 p-3 ring-1 ring-border/70 shadow-inner">
                    <RichTextEditor
                      value={policy.content}
                      onChange={(value) =>
                        updatePolicy(pageType, { content: value })
                      }
                      placeholder={config.placeholder}
                      minHeight="220px"
                    />
                  </div>
                </div>

                <div className="flex flex-col gap-3 rounded-2xl border bg-background/70 px-4 py-3 lg:flex-row lg:items-center lg:justify-between">
                  <div className="flex flex-wrap items-center gap-2">
                    <Badge
                      variant={hasContent ? "secondary" : "outline"}
                      className="rounded-full px-3 py-1"
