                      {hasContent
                        ? `${formatCount(plainTextLength)} حرف مفهوم للذكاء`
                        : "لم تتم كتابة محتوى بعد"}
                    </Badge>
                    <Badge
                      variant={
                        hasContent && policy.isActive ? "secondary" : "outline"
                      }
                      className="rounded-full px-3 py-1"
                    >
                      {hasContent && policy.isActive
                        ? "مفعلة في ردود الـ AI"
                        : "غير مفعلة داخل الردود"}
                    </Badge>
                    <Badge
                      variant={
                        hasContent && policy.showInFooter ? "secondary" : "outline"
                      }
                      className="rounded-full px-3 py-1"
                    >
                      {hasContent && policy.showInFooter
                        ? "ظاهرة في واجهة المتجر"
                        : "مخفية عن واجهة المتجر"}
