                    {hasContent
                      ? "سيتم استخدام هذه السياسة في الاسترجاع الدلالي الخاص بالشركة عند أسئلة العملاء ذات الصلة."
                      : "السياسة الفارغة لن تُنشأ تلقائيًا، ولن تدخل في RAG حتى تضيف محتوى فعليًا."}
                  </p>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
};

export default KnowledgeBasePoliciesSettings;

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "../ui/card";
import {
  AlertTriangle,
  CheckCircle,
  Info,
  X,
  Bell,
  BellOff,
  Clock,
} from "lucide-react";

interface Alert {
  id: string;
  type: "success" | "warning" | "error" | "info";
  title: string;
  message: string;
  timestamp: string;
  priority: "high" | "medium" | "low";
  category: "performance" | "quality" | "system" | "user";
  actionable: boolean;
  action?: {
    label: string;
    url?: string;
    callback?: () => void;
  };
}

interface SmartAlertsProps {
  qualityStats?: any;
  performanceData?: any;
  className?: string;
}

const SmartAlerts: React.FC<SmartAlertsProps> = ({
  qualityStats,
  performanceData,
  className = "",
}) => {
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [dismissed, setDismissed] = useState<Set<string>>(new Set());
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);

  // Generate smart alerts based on data
  useEffect(() => {
    const newAlerts: Alert[] = [];

    if (qualityStats) {
      // Low satisfaction alert
      if (
        qualityStats.ratings.satisfaction < 70 &&
        qualityStats.ratings.total >= 5
      ) {
        newAlerts.push({
          id: "low-satisfaction",
          type: "warning",
          title: "معدل رضا منخفض",
          message: `معدل الرضا الحالي ${qualityStats.ratings.satisfaction}% أقل من المستوى المطلوب (70%)`,
          timestamp: new Date().toISOString(),
          priority: "high",
          category: "quality",
          actionable: false,
          // ❌ REMOVED: quality-advanced route - Advanced Quality Dashboard removed
        });
      }

      // High negative rate alert
      if (
        qualityStats.analysis.negativeRate > 30 &&
        qualityStats.ratings.total >= 3
      ) {
        newAlerts.push({
          id: "high-negative-rate",
          type: "error",
          title: "نسبة عالية من التقييمات السلبية",
          message: `${qualityStats.analysis.negativeRate}% من التقييمات سلبية، مما يتطلب مراجعة فورية`,
          timestamp: new Date().toISOString(),
          priority: "high",
          category: "quality",
          actionable: true,
          action: {
            label: "مراجعة التقييمات السلبية",
            url: "/quality?filter=negative",
          },
        });
      }

      // No ratings alert
      if (
        qualityStats.responses.totalResponses > 10 &&
        qualityStats.ratings.total === 0
      ) {
        newAlerts.push({
          id: "no-ratings",
          type: "info",
          title: "لا توجد تقييمات",
          message: `تم إرسال ${qualityStats.responses.totalResponses} رد ولكن لم يتم تقييم أي منها بعد`,
          timestamp: new Date().toISOString(),
          priority: "medium",
          category: "user",
          actionable: false,
        });
      }
    }

    if (performanceData) {
      // Slow response time alert
      if (
        performanceData.responseTime.average > 5000 &&
        performanceData.totalResponses >= 3
      ) {
        newAlerts.push({
          id: "slow-response",
          type: "warning",
          title: "أوقات استجابة بطيئة",
          message: `متوسط وقت الاستجابة ${(performanceData.responseTime.average / 1000).toFixed(1)}s أعلى من المستوى المطلوب`,
          timestamp: new Date().toISOString(),
          priority: "high",
          category: "performance",
          actionable: false,
          // ❌ REMOVED: quality-advanced route - Advanced Quality Dashboard removed
        });
      }

      // Low confidence alert
      if (
        performanceData.aiMetrics.averageConfidence < 70 &&
        performanceData.totalResponses >= 3
      ) {
        newAlerts.push({
          id: "low-confidence",
          type: "warning",
          title: "مستوى ثقة منخفض",
          message: `متوسط ثقة الذكاء الاصطناعي ${performanceData.aiMetrics.averageConfidence}% أقل من المستوى المطلوب`,
          timestamp: new Date().toISOString(),
          priority: "medium",
          category: "performance",
          actionable: true,
          action: {
            label: "مراجعة الإعدادات",
            url: "/settings?section=ai",
          },
        });
      }

      // Low RAG usage alert
      if (
        performanceData.aiMetrics.ragUsageRate < 30 &&
        performanceData.totalResponses >= 5
      ) {
        newAlerts.push({
          id: "low-rag-usage",
          type: "info",
          title: "استخدام منخفض لقاعدة المعرفة",
          message: `${performanceData.aiMetrics.ragUsageRate}% فقط من الردود تستخدم قاعدة المعرفة`,
          timestamp: new Date().toISOString(),
          priority: "low",
          category: "system",
          actionable: true,
          action: {
            label: "تحسين قاعدة المعرفة",
            url: "/knowledge-base",
          },
        });
      }

      // Excellent performance alert
      if (
        performanceData.responseTime.average < 2000 &&
        performanceData.aiMetrics.averageConfidence > 90 &&
        performanceData.totalResponses >= 5
      ) {
        newAlerts.push({
          id: "excellent-performance",
          type: "success",
          title: "أداء ممتاز",
          message:
            "النظام يعمل بكفاءة عالية مع أوقات استجابة سريعة ومستوى ثقة عالي",
          timestamp: new Date().toISOString(),
          priority: "low",
          category: "performance",
          actionable: false,
        });
      }
    }

    // Filter out dismissed alerts
    const filteredAlerts = newAlerts.filter(
      (alert) => !dismissed.has(alert.id),
    );
    setAlerts(filteredAlerts);
  }, [qualityStats, performanceData, dismissed]);

  const getAlertIcon = (type: string) => {
    switch (type) {
      case "success":
        return <CheckCircle className="w-5 h-5 text-green-600" />;
      case "warning":
        return <AlertTriangle className="w-5 h-5 text-yellow-600" />;
      case "error":
        return <AlertTriangle className="w-5 h-5 text-red-600" />;
      default:
        return <Info className="w-5 h-5 text-blue-600" />;
    }
  };

  const getAlertBg = (type: string) => {
    switch (type) {
      case "success":
        return "bg-green-50 border-green-200";
      case "warning":
        return "bg-yellow-50 border-yellow-200";
      case "error":
        return "bg-red-50 border-red-200";
      default:
        return "bg-blue-50 border-blue-200";
    }
  };

  const getPriorityBadge = (priority: string) => {
    switch (priority) {
      case "high":
        return "bg-red-100 text-red-800";
      case "medium":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const dismissAlert = (alertId: string) => {
    setDismissed((prev) => new Set([...prev, alertId]));
  };

  const handleAction = (action: Alert["action"]) => {
    if (action?.url) {
      window.location.href = action.url;
    } else if (action?.callback) {
      action.callback();
    }
  };

  const formatTimestamp = (timestamp: string) => {
    return new Date(timestamp).toLocaleString("ar-EG", {
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  if (alerts.length === 0) {
    return (
      <Card className={className}>
        <CardContent className="flex items-center justify-center py-8">
          <div className="text-center">
            <CheckCircle className="w-12 h-12 text-green-500 mx-auto mb-2" />
            <h3 className="text-lg font-semibold text-gray-600 mb-1">
              لا توجد تنبيهات
            </h3>
            <p className="text-sm text-gray-500">النظام يعمل بشكل طبيعي</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={className}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center space-x-2 space-x-reverse">
            <Bell className="w-5 h-5 text-orange-600" />
            <span>التنبيهات الذكية</span>
            <span className="bg-orange-100 text-orange-800 text-xs px-2 py-1 rounded-full">
              {alerts.length}
            </span>
          </CardTitle>
          <button
            onClick={() => setNotificationsEnabled(!notificationsEnabled)}
            className={`p-2 rounded-lg transition-colors ${
              notificationsEnabled
                ? "text-orange-600 hover:bg-orange-50"
                : "text-gray-400 hover:bg-gray-50"
            }`}
            title={notificationsEnabled ? "إيقاف التنبيهات" : "تفعيل التنبيهات"}
          >
            {notificationsEnabled ? (
              <Bell className="w-4 h-4" />
            ) : (
              <BellOff className="w-4 h-4" />
            )}
          </button>
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-3 max-h-96 overflow-y-auto">
          {alerts.map((alert) => (
            <div
              key={alert.id}
              className={`p-4 rounded-lg border ${getAlertBg(alert.type)}`}
            >
              <div className="flex items-start justify-between">
                <div className="flex items-start space-x-3 space-x-reverse flex-1">
                  {getAlertIcon(alert.type)}
                  <div className="flex-1">
                    <div className="flex items-center justify-between mb-1">
                      <h4 className="text-sm font-medium text-gray-900">
                        {alert.title}
                      </h4>
                      <div className="flex items-center space-x-2 space-x-reverse">
                        <span
                          className={`px-2 py-1 text-xs rounded-full ${getPriorityBadge(alert.priority)}`}
                        >
                          {alert.priority === "high"
                            ? "عالي"
                            : alert.priority === "medium"
                              ? "متوسط"
                              : "منخفض"}
                        </span>
                        <span className="text-xs text-gray-500 flex items-center">
                          <Clock className="w-3 h-3 mr-1" />
                          {formatTimestamp(alert.timestamp)}
                        </span>
                      </div>
                    </div>
                    <p className="text-sm text-gray-700 mb-2">
                      {alert.message}
                    </p>
                    {alert.actionable && alert.action && (
                      <button
                        onClick={() => handleAction(alert.action)}
                        className="text-sm text-blue-600 hover:text-blue-800 font-medium"
                      >
                        {alert.action.label} ←
                      </button>
                    )}
                  </div>
                </div>
                <button
                  onClick={() => dismissAlert(alert.id)}
                  className="p-1 hover:bg-white hover:bg-opacity-50 rounded"
                >
                  <X className="w-4 h-4 text-gray-400" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
};

export default SmartAlerts;

import React, { useEffect, useState } from "react";
import {
  XMarkIcon,
  CheckCircleIcon,
  XCircleIcon,
} from "@heroicons/react/24/outline";
import { socketService } from "../../services/socketService";

interface CampaignProgressModalProps {
  campaignId: string;
  campaignName: string;
  isOpen: boolean;
  onClose: () => void;
}

interface ProgressData {
  campaignId: string;
  status: "started" | "sending" | "completed" | "failed";
  total: number;
  sent: number;
  failed: number;
  progress: number;
  currentRecipient?: string;
}

const CampaignProgressModal: React.FC<CampaignProgressModalProps> = ({
  campaignId,
  campaignName,
  isOpen,
  onClose,
}) => {
  const [progressData, setProgressData] = useState<ProgressData>({
    campaignId,
    status: "started",
    total: 0,
    sent: 0,
    failed: 0,
    progress: 0,
  });

  useEffect(() => {
    if (!isOpen) return;

    console.log(
      "🔌 [CAMPAIGN-MODAL] Listening for campaign progress, campaignId:",
      campaignId,
    );

    // Listen for progress updates
    const handleProgress = (data: ProgressData) => {
      console.log("📡 [CAMPAIGN-MODAL] Received progress event:", data);

      if (data.campaignId === campaignId) {
        console.log(
          "✅ [CAMPAIGN-MODAL] Campaign ID matches, updating progress",
        );
        setProgressData(data);

        // Auto-close after completion (with delay)
        if (false && data.status === "completed") {
          setTimeout(() => {
            onClose();
          }, 3000);
        }
      } else {
        console.log(
          "⚠️ [CAMPAIGN-MODAL] Campaign ID mismatch:",
          data.campaignId,
          "vs",
          campaignId,
        );
      }
    };

    socketService.onCampaignProgress(handleProgress);

    return () => {
      socketService.off("campaign:progress", handleProgress);
    };
  }, [isOpen, campaignId, onClose]);

  if (!isOpen) return null;

  const isCompleted = progressData.status === "completed";
  const isFailed = progressData.status === "failed";

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex min-h-screen items-center justify-center p-4">
        {/* Backdrop */}
        <div className="fixed inset-0 bg-black bg-opacity-50 transition-opacity" />

        {/* Modal */}
        <div className="relative bg-white rounded-lg shadow-xl max-w-md w-full p-6">
          {/* Header */}
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900">
              {isCompleted ? "✅ اكتمل الإرسال" : "📤 جاري إرسال الحملة"}
            </h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 transition-colors"
            >
              <XMarkIcon className="w-5 h-5" />
            </button>
          </div>

          {/* Campaign Name */}
          <div className="mb-4">
            <p className="text-sm text-gray-600">اسم الحملة</p>
            <p className="font-medium text-gray-900">{campaignName}</p>
          </div>

          {/* Progress Bar */}
          <div className="mb-4">
            <div className="flex justify-between text-sm text-gray-600 mb-2">
              <span>التقدم</span>
              <span className="font-semibold">{progressData.progress}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
              <div
                className={`h-full transition-all duration-300 rounded-full ${
                  isCompleted
                    ? "bg-green-500"
                    : isFailed
                      ? "bg-red-500"
                      : "bg-blue-500"
                }`}
                style={{ width: `${progressData.progress}%` }}
              />
            </div>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-3 gap-4 mb-4">
            <div className="text-center p-3 bg-gray-50 rounded-lg">
              <div className="text-2xl font-bold text-gray-900">
                {progressData.total}
              </div>
              <div className="text-xs text-gray-600">إجمالي</div>
            </div>
            <div className="text-center p-3 bg-green-50 rounded-lg">
              <div className="text-2xl font-bold text-green-600">
                {progressData.sent}
              </div>
              <div className="text-xs text-gray-600">نجح</div>
            </div>
            <div className="text-center p-3 bg-red-50 rounded-lg">
              <div className="text-2xl font-bold text-red-600">
                {progressData.failed}
              </div>
              <div className="text-xs text-gray-600">فشل</div>
            </div>
          </div>

          {/* Current Recipient */}
          {progressData.currentRecipient && !isCompleted && (
            <div className="mb-4 p-3 bg-blue-50 rounded-lg">
              <p className="text-xs text-gray-600 mb-1">جاري الإرسال إلى</p>
              <p className="text-sm font-medium text-blue-900">
                {progressData.currentRecipient}
              </p>
            </div>
          )}

          {/* Status Message */}
          {isCompleted && (
            <div className="flex items-center gap-2 p-3 bg-green-50 rounded-lg">
              <CheckCircleIcon className="w-5 h-5 text-green-600" />
              <p className="text-sm text-green-900">
                تم إرسال الحملة بنجاح! تم إرسال {progressData.sent} رسالة من أصل{" "}
                {progressData.total}
              </p>
            </div>
          )}

          {isFailed && (
            <div className="flex items-center gap-2 p-3 bg-red-50 rounded-lg">
              <XCircleIcon className="w-5 h-5 text-red-600" />
              <p className="text-sm text-red-900">فشل إرسال الحملة</p>
            </div>
          )}

          {/* Loading Animation */}
          {!isCompleted && !isFailed && (
            <div className="flex items-center justify-center gap-2 text-sm text-gray-600">
              <div className="animate-spin rounded-full h-4 w-4 border-2 border-blue-500 border-t-transparent" />
              <span>جاري الإرسال...</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CampaignProgressModal;

import React, { useState } from "react";
import { XMarkIcon } from "@heroicons/react/24/outline";
import { broadcastService } from "../../services/broadcastService";

interface CreateListModalProps {
  onClose: () => void;
  onSuccess: () => void;
}

const CreateListModal: React.FC<CreateListModalProps> = ({
  onClose,
  onSuccess,
}) => {
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    criteriaType: "active",
    lastActivity: "24",
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.name.trim()) {
      setError("يرجى إدخال اسم القائمة");
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const criteria = {
        type: formData.criteriaType,
        lastActivity: formData.lastActivity,
      };

      await broadcastService.createCustomerList({
        name: formData.name,
        description: formData.description,
        criteria,
      });

      onSuccess();
      onClose();
    } catch (err: any) {
      console.error("Error creating list:", err);
      setError(err.message || "فشل في إنشاء القائمة");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50 flex items-center justify-center">
      <div className="relative bg-white rounded-lg shadow-xl max-w-md w-full mx-4">
        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-gray-200">
          <h3 className="text-lg font-medium text-gray-900">
            إنشاء قائمة جديدة
          </h3>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 transition-colors"
          >
            <XMarkIcon className="h-6 w-6" />
          </button>
        </div>

        {/* Body */}
        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-3">
              <p className="text-sm text-red-800">{error}</p>
            </div>
          )}

          {/* Name */}
          <div>
            <label
              htmlFor="name"
              className="block text-sm font-medium text-gray-700 mb-1"
            >
              اسم القائمة <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              id="name"
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
              className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              placeholder="مثال: عملاء VIP"
              required
            />
          </div>

          {/* Description */}
          <div>
            <label
              htmlFor="description"
              className="block text-sm font-medium text-gray-700 mb-1"
            >
              الوصف
            </label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) =>
                setFormData({ ...formData, description: e.target.value })
              }
              rows={3}
              className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              placeholder="وصف مختصر للقائمة..."
            />
          </div>

          {/* Criteria Type */}
          <div>
            <label
              htmlFor="criteriaType"
              className="block text-sm font-medium text-gray-700 mb-1"
            >
              نوع المعايير
            </label>
            <select
              id="criteriaType"
              value={formData.criteriaType}
              onChange={(e) =>
                setFormData({ ...formData, criteriaType: e.target.value })
              }
              className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
            >
              <option value="all">جميع العملاء</option>
              <option value="active">نشطين في فترة محددة</option>
              <option value="inactive">غير نشطين لفترة محددة</option>
            </select>
          </div>

          {/* Last Activity (only for active/inactive) */}
          {(formData.criteriaType === "active" ||
            formData.criteriaType === "inactive") && (
            <div>
              <label
                htmlFor="lastActivity"
                className="block text-sm font-medium text-gray-700 mb-1"
              >
                {formData.criteriaType === "active"
                  ? "نشطين خلال (ساعات)"
                  : "غير نشطين لأكثر من (أيام)"}
              </label>
              <input
                type="number"
                id="lastActivity"
                value={formData.lastActivity}
                onChange={(e) =>
                  setFormData({ ...formData, lastActivity: e.target.value })
                }
                className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                min="1"
                placeholder={formData.criteriaType === "active" ? "24" : "30"}
              />
              <p className="mt-1 text-xs text-gray-500">
                {formData.criteriaType === "active"
                  ? "العملاء الذين تواصلوا معك في آخر X ساعة"
                  : "العملاء الذين لم يتواصلوا معك منذ X يوم"}
              </p>
            </div>
          )}

          {/* Actions */}
          <div className="flex items-center justify-end space-x-3 space-x-reverse pt-4 border-t border-gray-200">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
              disabled={loading}
            >
              إلغاء
            </button>
            <button
              type="submit"
              className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed"
              disabled={loading}
            >
              {loading ? (
                <span className="flex items-center">
                  <svg
                    className="animate-spin -ml-1 mr-2 h-4 w-4 text-white"
                    xmlns="http://www.w3.org/2000/svg"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    ></circle>
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                    ></path>
                  </svg>
                  جاري الإنشاء...
                </span>
              ) : (
                "إنشاء القائمة"
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreateListModal;

import React from 'react';
import {
    BarChart as RechartsBarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Legend,
    ResponsiveContainer,
} from 'recharts';

interface BarChartProps {
    data: any[];
    xKey: string;
    bars: {
        key: string;
        name: string;
        color: string;
    }[];
    height?: number;
    showLegend?: boolean;
    showGrid?: boolean;
    layout?: 'horizontal' | 'vertical';
}

const BarChart: React.FC<BarChartProps> = ({
    data,
    xKey,
    bars,
    height = 300,
    showLegend = true,
    showGrid = true,
    layout = 'horizontal',
}) => {
    return (
        <ResponsiveContainer width="100%" height={height}>
            <RechartsBarChart
                data={data}
                layout={layout}
                margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
            >
                {showGrid && <CartesianGrid strokeDasharray="3 3" />}
                {layout === 'horizontal' ? (
                    <>
                        <XAxis dataKey={xKey} />
                        <YAxis />
                    </>
                ) : (
                    <>
                        <XAxis type="number" />
                        <YAxis dataKey={xKey} type="category" />
                    </>
                )}
                <Tooltip />
                {showLegend && <Legend />}
                {bars.map((bar) => (
                    <Bar
                        key={bar.key}
                        dataKey={bar.key}
                        fill={bar.color}
                        name={bar.name}
                    />
                ))}
            </RechartsBarChart>
        </ResponsiveContainer>
    );
};

