import React from "react";

interface ResponsiveGridProps {
  children: React.ReactNode;
  cols?: {
    default?: number;
    sm?: number;
    md?: number;
    lg?: number;
    xl?: number;
  };
  gap?: number;
  className?: string;
}

const ResponsiveGrid: React.FC<ResponsiveGridProps> = ({
  children,
  cols = { default: 1, sm: 2, md: 3, lg: 4, xl: 5 },
  gap = 4,
  className = "",
}) => {
  const getGridClasses = () => {
    const classes = ["grid"];

    // Default columns
    if (cols.default) {
      classes.push(`grid-cols-${cols.default}`);
    }

    // Responsive columns
    if (cols.sm) {
      classes.push(`sm:grid-cols-${cols.sm}`);
    }
    if (cols.md) {
      classes.push(`md:grid-cols-${cols.md}`);
    }
    if (cols.lg) {
      classes.push(`lg:grid-cols-${cols.lg}`);
    }
    if (cols.xl) {
      classes.push(`xl:grid-cols-${cols.xl}`);
    }

    // Gap
    classes.push(`gap-${gap}`);

    return classes.join(" ");
  };

  return <div className={`${getGridClasses()} ${className}`}>{children}</div>;
};

interface ResponsiveCardProps {
  children: React.ReactNode;
  className?: string;
  padding?: "sm" | "md" | "lg";
  shadow?: "sm" | "md" | "lg" | "xl";
  rounded?: "sm" | "md" | "lg" | "xl";
  hover?: boolean;
}

const ResponsiveCard: React.FC<ResponsiveCardProps> = ({
  children,
  className = "",
  padding = "md",
  shadow = "md",
  rounded = "lg",
  hover = false,
}) => {
  const getPaddingClass = () => {
    switch (padding) {
      case "sm":
        return "p-3 sm:p-4";
      case "md":
        return "p-4 sm:p-6";
      case "lg":
        return "p-6 sm:p-8";
      default:
        return "p-4 sm:p-6";
    }
  };

  const getShadowClass = () => {
    switch (shadow) {
      case "sm":
        return "shadow-sm";
      case "md":
        return "shadow-md";
      case "lg":
        return "shadow-lg";
      case "xl":
        return "shadow-xl";
      default:
        return "shadow-md";
    }
  };

  const getRoundedClass = () => {
    switch (rounded) {
      case "sm":
        return "rounded-sm";
      case "md":
        return "rounded-md";
      case "lg":
        return "rounded-lg";
      case "xl":
        return "rounded-xl";
      default:
        return "rounded-lg";
    }
  };

  const hoverClass = hover
    ? "hover:shadow-lg transition-shadow duration-200"
    : "";

  return (
    <div
      className={`bg-white ${getPaddingClass()} ${getShadowClass()} ${getRoundedClass()} ${hoverClass} ${className}`}
