  ExternalLink,
} from "lucide-react";
import { NoSymbolIcon, CheckCircleIcon } from "@heroicons/react/24/outline";
import { format } from "date-fns";
import { arSA } from "date-fns/locale";
import { useCustomerProfile } from "../../../hooks/inbox/useCustomerProfile";
import {
  ConversationStatus,
  InboxConversation,
} from "../../../types/inbox.types";
import TagInput from "../TagInput/TagInput";
import { apiClient } from "../../../services/apiClient";
import { extractCoreAiConversationSummary } from "../../../utils/inboxConversationMetadata";

import StatusDropdown from "../StatusDropdown/StatusDropdown";
import AssignmentDropdown from "../AssignmentDropdown/AssignmentDropdown";

interface CustomerProfileProps {
  conversation: InboxConversation;
  className?: string;
  onTagsChange: (tags: string[]) => void;
  updatingTags: boolean;
  currentStatus?: string;
  onStatusChange?: (status: string) => void;
  currentAssignee?: string | null;
  currentAssigneeName?: string | null;
  onAssign?: (userId: string | null) => void;
  disabled?: boolean;
  // 🆕 Open Conversation Callback
  onOpenConversation?: (conversationId: string) => void;
  // 🆕 Block Customer Props
  isBlocked?: boolean;
  checkingBlockStatus?: boolean;
  blocking?: boolean;
  showBlockModal?: boolean;
  blockReason?: string;
  onBlockClick?: () => void;
  onUnblockClick?: () => void;
  onBlockReasonChange?: (reason: string) => void;
  onBlockConfirm?: () => void;
  onBlockCancel?: () => void;
  // 🆕 Sound & Notifications Props
  soundEnabled?: boolean;
  notificationsEnabled?: boolean;
  onSoundToggle?: () => void;
  onNotificationsToggle?: () => void;
  // 🆕 Copy Conversation Link
  onCopyConversationLink?: (conversationId: string) => void;
  // 🆕 Quick Order
  onCreateOrder?: () => void;
}

type Tab = "info" | "orders" | "timeline";

const CustomerProfile: React.FC<CustomerProfileProps> = ({
  conversation,
  className,
  onTagsChange,
  updatingTags,
  currentStatus,
  onStatusChange,
  currentAssignee,
  currentAssigneeName,
  onAssign,
  disabled = false,
  // 🆕 Block Customer
  isBlocked = false,
  checkingBlockStatus = false,
  blocking = false,
  showBlockModal = false,
  blockReason = "",
  onBlockClick,
  onUnblockClick,
  onBlockReasonChange,
  onBlockConfirm,
  onBlockCancel,
  // 🆕 Sound & Notifications
  soundEnabled = true,
  notificationsEnabled = true,
  onSoundToggle,
  onNotificationsToggle,
  // 🆕 Copy Conversation Link
  // 🆕 Quick Order
  onCreateOrder,
}) => {
  const [activeTab, setActiveTab] = useState<Tab>("timeline");
  const [syncingMessages, setSyncingMessages] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);
  const {
    orders,
    activities,
    loading,
    loadCustomerData,
    calculateLTV,

    customer, // Add customer to destructured object
  } = useCustomerProfile();

  useEffect(() => {
    if (conversation?.customerId) {
      loadCustomerData(conversation.customerId);
    }
  }, [conversation?.customerId, loadCustomerData]);

  const handleSyncMessages = async () => {
    if (!conversation?.id || conversation.platform !== "facebook") {
      return;
    }

    setSyncingMessages(true);
    setSyncMessage(null);

    try {
      // Increase timeout for sync operation (can take longer due to Facebook API calls)
      const response = await apiClient.post(
        `/conversations/${conversation.id}/sync-messages`,
        {},
        {
          timeout: 90000, // 90 seconds timeout for sync operation
        },
      );

      if (response.data.success) {
        setSyncMessage(`✅ ${response.data.message || "تم جلب الرسائل بنجاح"}`);
        // Reload customer data to refresh activities
        if (conversation.customerId) {
          loadCustomerData(conversation.customerId);
        }
      } else {
        setSyncMessage(`❌ ${response.data.message || "فشل في جلب الرسائل"}`);
      }
    } catch (error: any) {
      console.error("Error syncing messages:", error);
      const errorMessage =
        error.response?.data?.message ||
        error.response?.data?.error ||
        error.message ||
        "حدث خطأ أثناء جلب الرسائل";
      const errorInfo = error.response?.data?.info
        ? ` (${error.response.data.info})`
        : "";
      setSyncMessage(`❌ ${errorMessage}${errorInfo}`);
    } finally {
      setSyncingMessages(false);
      // Clear message after 5 seconds
      setTimeout(() => {
        setSyncMessage(null);
      }, 5000);
    }
  };

  const ltv = calculateLTV();
  const effectiveStatus: ConversationStatus =
    currentStatus === "open" ||
    currentStatus === "pending" ||
    currentStatus === "resolved" ||
    currentStatus === "done"
      ? currentStatus
