  const conversationSummaryUpdatedAt = conversationSummary?.updatedAt
    ? new Date(conversationSummary.updatedAt)
    : null;
  const hasValidConversationSummaryUpdatedAt =
    !!conversationSummaryUpdatedAt &&
    !Number.isNaN(conversationSummaryUpdatedAt.getTime());

