        {/* Quick Stats */}
        <div className="flex justify-center gap-4 mt-4 text-sm">
          <div className="text-center">
            <p className="text-xs" style={mutedHeadingStyle}>
              الطلبات
            </p>
            <p
              className="font-semibold"
              style={{ color: "var(--color-foreground)" }}
            >
              {orders.length}
            </p>
          </div>
          <div className="text-center">
