              style={{
                color: "var(--business-warning)",
                background:
                  "color-mix(in srgb, var(--business-warning) 10%, white)",
                borderColor:
                  "color-mix(in srgb, var(--business-warning) 20%, transparent)",
              }}
              title="إنشاء طلب سريع لهذا العميل"
