                disabled={blocking}
                className="business-chip-button w-full flex items-center justify-center gap-2 px-4 py-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                style={{
                  color: "var(--business-success)",
                  background:
                    "color-mix(in srgb, var(--business-success) 10%, white)",
                  borderColor:
                    "color-mix(in srgb, var(--business-success) 20%, transparent)",
                }}
                title="إلغاء حظر العميل على الصفحة"
              >
                <CheckCircleIcon className="w-5 h-5" />
                <span className="text-sm font-medium">إلغاء الحظر</span>
              </button>
            ) : (
              <button
                onClick={onBlockClick}
                className="business-chip-button w-full flex items-center justify-center gap-2 px-4 py-2 rounded-lg transition-colors"
                style={{
                  color: "var(--business-danger)",
                  background:
                    "color-mix(in srgb, var(--business-danger) 10%, white)",
                  borderColor:
                    "color-mix(in srgb, var(--business-danger) 20%, transparent)",
                }}
                title="حظر العميل على الصفحة"
              >
                <NoSymbolIcon className="w-5 h-5" />
                <span className="text-sm font-medium">حظر العميل</span>
              </button>
            )}
          </div>
        )}
      </div>

      {/* Tabs */}
      <div className="business-inbox-tabs m-3 mt-0">
        <button
          onClick={() => setActiveTab("timeline")}
          className="business-inbox-tab"
          data-active={activeTab === "timeline" ? "true" : "false"}
        >
          <span className="flex items-center justify-center gap-1">
            <Activity size={16} /> نشاط
          </span>
        </button>
        <button
          onClick={() => setActiveTab("orders")}
          className="business-inbox-tab"
          data-active={activeTab === "orders" ? "true" : "false"}
        >
          <span className="flex items-center justify-center gap-1">
            <ShoppingBag size={16} /> طلبات
            {orders.length > 0 && (
              <span className="business-inbox-tab-count">{orders.length}</span>
            )}
          </span>
        </button>
        <button
          onClick={() => setActiveTab("info")}
          className="business-inbox-tab"
          data-active={activeTab === "info" ? "true" : "false"}
        >
          <span className="flex items-center justify-center gap-1">
            <User size={16} /> معلومات
          </span>
        </button>
      </div>

      {/* Content area */}
      <div className="business-chat-stage flex-1 overflow-y-auto p-4">
        {loading ? (
          <div className="flex justify-center p-8">
            <div
              className="animate-spin rounded-full h-8 w-8 border-b-2"
              style={{ borderColor: "var(--color-primary)" }}
            ></div>
          </div>
        ) : (
          <>
            <div className="mb-6 p-4 rounded-lg" style={sectionSurfaceStyle}>
              <div className="flex items-start justify-between gap-3 mb-3">
                <div>
                  <h4
                    className="text-xs font-semibold uppercase"
                    style={mutedHeadingStyle}
                  >
                    AI JSON Summary
                  </h4>
                  <p
                    className="text-sm mt-1"
                    style={{ color: "var(--color-foreground)" }}
                  >
                    ملخص الطلب اللي الـ AI استخرجه من المحادثة
                  </p>
                </div>
                {hasValidConversationSummaryUpdatedAt && (
                  <span
                    className="text-[11px] whitespace-nowrap"
                    style={{ color: "var(--color-muted-foreground)" }}
                  >
                    {format(conversationSummaryUpdatedAt, "dd MMM, HH:mm", {
                      locale: arSA,
                    })}
                  </span>
                )}
              </div>

              {conversationSummary && conversationSummaryFields.length > 0 ? (
                <>
                  <div className="space-y-2 mb-3">
                    {conversationSummaryFields.map((field) => (
                      <div
                        key={field.label}
                        className="flex items-start justify-between gap-3 text-sm"
                      >
                        <span
                          className="shrink-0"
                          style={{ color: "var(--color-muted-foreground)" }}
                        >
                          {field.label}
                        </span>
                        <span
                          className="text-left break-words"
                          style={{ color: "var(--color-foreground)" }}
                          dir={field.label === "الموبايل" ? "ltr" : undefined}
                        >
                          {field.value}
                        </span>
                      </div>
                    ))}
                  </div>

                  <div
                    className="rounded-lg overflow-hidden"
                    style={{
                      border: "1px solid var(--business-card-border)",
                      background: "var(--color-background)",
                    }}
                  >
                    <div
                      className="px-3 py-2 text-[11px] font-semibold uppercase"
                      style={{
                        color: "var(--color-muted-foreground)",
                        borderBottom: "1px solid var(--business-card-border)",
                      }}
                    >
                      Raw JSON
                    </div>
                    <pre
                      className="text-[11px] leading-5 whitespace-pre-wrap break-words p-3 overflow-x-auto"
                      style={{ color: "var(--color-foreground)" }}
                      dir="ltr"
                    >
                      {conversationSummaryJson}
                    </pre>
                  </div>
                </>
              ) : (
                <p
                  className="text-sm"
                  style={{ color: "var(--color-muted-foreground)" }}
                >
                  لا يوجد ملخص JSON متسجل من الـ AI في المحادثة دي حتى الآن.
                </p>
              )}
            </div>

            {/* INFO TAB */}
            {activeTab === "info" && (
              <div className="space-y-6">
                {/* Contact Info */}
                <div className="p-4 rounded-lg" style={sectionSurfaceStyle}>
                  <h4
                    className="text-xs font-semibold uppercase mb-3"
                    style={mutedHeadingStyle}
                  >
                    التواصل
                  </h4>
                  <div className="space-y-3">
                    <div className="flex items-center gap-3 text-sm">
                      <Phone
                        size={16}
                        style={{ color: "var(--color-muted-foreground)" }}
                      />
                      <span
                        className="font-medium font-mono"
                        style={{ color: "var(--color-foreground)" }}
                        dir="ltr"
                      >
                        {customer?.phone || "غير متوفر"}
                      </span>
                    </div>
                    {customer?.email &&
                      !customer.email.endsWith("@example.com") && (
                        <div className="flex items-center gap-3 text-sm">
                          <Mail
                            size={16}
                            style={{ color: "var(--color-muted-foreground)" }}
                          />
                          <span
                            className="truncate"
                            style={{ color: "var(--color-foreground)" }}
                          >
                            {customer.email}
                          </span>
                        </div>
                      )}
                  </div>
                </div>

                {/* Tags */}
                <div className="p-4 rounded-lg" style={sectionSurfaceStyle}>
                  <h4
                    className="text-xs font-semibold uppercase mb-3"
                    style={mutedHeadingStyle}
                  >
                    التصنيفات
                  </h4>
                  <TagInput
                    conversationId={conversation.id}
                    currentTags={conversation.tags}
                    onTagsChange={onTagsChange}
                    disabled={updatingTags}
                  />
                </div>

                {/* Metadata / Custom Fields */}
                <div className="p-4 rounded-lg" style={sectionSurfaceStyle}>
                  <h4
                    className="text-xs font-semibold uppercase mb-3"
                    style={mutedHeadingStyle}
                  >
                    بيانات أخرى
                  </h4>
                  <div className="text-sm space-y-2">
                    <div className="flex justify-between">
                      <span style={{ color: "var(--color-muted-foreground)" }}>
                        آخر ظهور:
                      </span>
                      <span
                        className="font-medium"
                        style={{ color: "var(--color-foreground)" }}
                      >
                        {format(
                          new Date(conversation.lastMessageTime),
                          "MMM d, HH:mm",
                          { locale: arSA },
                        )}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* ORDERS TAB */}
            {activeTab === "orders" && (
              <div className="space-y-4">
                {/* Orders Summary Header */}
                {orders.length > 0 && (
                  <div
                    className="p-3 rounded-lg"
                    style={{
                      background:
                        "linear-gradient(135deg, color-mix(in srgb, var(--color-primary) 10%, white) 0%, color-mix(in srgb, var(--color-secondary) 8%, white) 100%)",
                      border:
                        "1px solid color-mix(in srgb, var(--color-primary) 18%, transparent)",
                    }}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <ShoppingBag
                          size={20}
                          style={{ color: "var(--color-primary)" }}
                        />
                        <span
                          className="font-semibold"
                          style={{ color: "var(--color-primary)" }}
                        >
                          سجل الطلبات
                        </span>
                      </div>
                      <span
                        className="text-white text-xs font-bold px-2 py-1 rounded-full"
                        style={{ background: "var(--color-primary)" }}
                      >
                        {orders.length} طلب
                      </span>
                    </div>
                  </div>
                )}

                {orders.length === 0 ? (
                  <div
                    className="text-center py-8"
                    style={{ color: "var(--color-muted-foreground)" }}
                  >
                    <ShoppingBag
                      size={48}
                      className="mx-auto mb-2 opacity-20"
                    />
                    <p>لا توجد طلبات سابقة</p>
                  </div>
                ) : (
                  orders.map((order) => (
                    <div
                      key={order.id}
                      className="p-3 rounded-lg transition-colors"
                      style={sectionSurfaceStyle}
                    >
                      <div className="flex justify-between items-start mb-2">
                        <div>
                          <p
                            className="font-bold"
                            style={{ color: "var(--color-foreground)" }}
                          >
                            #{order.orderNumber}
                          </p>
                          <p
                            className="text-xs"
                            style={{ color: "var(--color-muted-foreground)" }}
                          >
                            {format(new Date(order.createdAt), "dd MMM yyyy", {
                              locale: arSA,
                            })}
                          </p>
                        </div>
                        <span
                          className="px-2 py-1 text-xs rounded-full"
                          style={getOrderStatusTheme(order.status)}
                        >
                          {order.status === "PENDING"
                            ? "جديد"
                            : order.status === "CONFIRMED"
                              ? "مؤكد"
                              : order.status === "PROCESSING"
                                ? "جاري التجهيز"
                                : order.status === "SHIPPED"
                                  ? "تم الشحن"
                                  : order.status === "DELIVERED" ||
                                      order.status === "COMPLETED" ||
                                      order.status === "completed"
                                    ? "تم التسليم"
                                    : order.status === "CANCELLED" ||
                                        order.status === "cancelled"
                                      ? "ملغي"
                                      : order.status}
                        </span>
                      </div>
                      <div
                        className="flex justify-between items-center pt-2 mt-2"
                        style={{
                          borderTop: "1px solid var(--business-muted-line)",
                        }}
                      >
                        <span
                          className="text-xs"
                          style={{ color: "var(--color-muted-foreground)" }}
                        >
                          {order.items?.length || 0} منتجات
                        </span>
                        <span
                          className="font-bold"
                          style={{ color: "var(--color-primary)" }}
                        >
                          {order.total?.toLocaleString() || 0} ج.م
                        </span>
                      </div>
                      {/* View Order Button */}
                      <button
                        onClick={() =>
                          window.open(`/orders/${encodeURIComponent(String(order.id))}`, "_blank")
                        }
                        className="business-chip-button w-full mt-2 flex items-center justify-center gap-2 px-3 py-2 rounded-lg transition-colors text-sm font-medium"
                        style={{
                          color: "var(--color-primary)",
                          background:
                            "color-mix(in srgb, var(--color-primary) 8%, white)",
                        }}
                      >
                        <ExternalLink size={14} />
                        عرض الطلب
                      </button>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* TIMELINE TAB */}
            {activeTab === "timeline" && (
              <div
                className="relative pl-4 space-y-6 mr-2"
                style={{ borderRight: "2px solid var(--business-muted-line)" }}
              >
                {/* Using marginRight and borderRight for RTL timeline effect */}

                {/* Sync Facebook Messages Button - Only for Facebook conversations */}
                {conversation.platform === "facebook" && (
                  <div className="relative pr-6 mb-4">
                    <div
                      className="absolute -right-[29px] top-1 w-3 h-3 rounded-full border-2"
                      style={{
                        background: "var(--business-success)",
                        borderColor:
                          "color-mix(in srgb, white 76%, var(--color-background) 24%)",
                        boxShadow:
                          "0 0 0 4px color-mix(in srgb, var(--business-success) 10%, white)",
                      }}
                    ></div>
                    <div
                      className="rounded-lg p-3"
                      style={{
                        background:
                          "color-mix(in srgb, var(--business-success) 8%, white)",
                        border:
                          "1px solid color-mix(in srgb, var(--business-success) 18%, transparent)",
                      }}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex-1">
                          <p
                            className="text-sm font-semibold mb-1"
                            style={{ color: "var(--business-success)" }}
                          >
                            جلب الرسائل من Facebook
                          </p>
                          <p
                            className="text-xs"
                            style={{ color: "var(--business-success)" }}
                          >
                            احضر جميع الرسائل القديمة للمحادثة من Facebook
                          </p>
                          {syncMessage && (
                            <p
                              className="text-xs mt-2"
                              style={{
                                color: syncMessage.includes("✅")
                                  ? "var(--business-success)"
                                  : "var(--business-danger)",
                              }}
                            >
                              {syncMessage}
                            </p>
                          )}
                        </div>
                        <button
                          onClick={handleSyncMessages}
                          disabled={syncingMessages}
                          className="business-chip-button flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm transition-colors"
                          style={
                            syncingMessages
                              ? {
                                  background:
                                    "color-mix(in srgb, var(--business-success) 16%, white)",
                                  color: "var(--business-success)",
                                }
                              : {
                                  background: "var(--business-success)",
                                  borderColor: "transparent",
                                  color: "white",
                                }
                          }
                        >
                          <RefreshCw
                            size={16}
                            className={syncingMessages ? "animate-spin" : ""}
                          />
                          {syncingMessages ? "جاري الجلب..." : "جلب الرسائل"}
                        </button>
                      </div>
                    </div>
                  </div>
                )}

                {/* Post Details Section - Show if postId exists */}
                {conversation.postId && (
                  <div className="relative pr-6 mb-4">
                    <div
                      className="absolute -right-[29px] top-1 w-3 h-3 rounded-full border-2"
                      style={{
                        background: "var(--color-secondary)",
                        borderColor:
                          "color-mix(in srgb, white 76%, var(--color-background) 24%)",
                        boxShadow:
                          "0 0 0 4px color-mix(in srgb, var(--color-secondary) 10%, white)",
                      }}
                    ></div>
                    <div
                      className="rounded-lg p-3"
                      style={{
                        background:
                          "color-mix(in srgb, var(--color-secondary) 8%, white)",
                        border:
                          "1px solid color-mix(in srgb, var(--color-secondary) 18%, transparent)",
                      }}
                    >
                      <div className="flex items-start space-x-2 space-x-reverse mb-2">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center space-x-2 text-sm mb-1">
                            <span
                              className="font-semibold"
                              style={{ color: "var(--color-secondary)" }}
                            >
                              📌 جاء من منشور
                            </span>
                            {!conversation.postDetails && (
                              <span
                                className="text-xs"
                                style={{ color: "var(--color-secondary)" }}
                              >
                                جاري تحميل التفاصيل...
                              </span>
                            )}
                            {conversation.postDetails?.permalinkUrl && (
                              <a
                                href={conversation.postDetails.permalinkUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-xs underline flex items-center space-x-1"
                                style={{ color: "var(--color-secondary)" }}
                              >
                                <span>عرض المنشور</span>
                                <svg
                                  className="w-3 h-3"
                                  fill="none"
                                  stroke="currentColor"
                                  viewBox="0 0 24 24"
                                >
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
                                  />
                                </svg>
                              </a>
                            )}
                          </div>
                          {conversation.postDetails?.message && (
                            <p
                              className="text-xs mb-2 line-clamp-3"
                              style={{ color: "var(--color-secondary)" }}
                            >
                              {conversation.postDetails.message}
                            </p>
                          )}
                          {conversation.postDetails?.hasImages &&
                            conversation.postDetails?.imageUrls &&
                            conversation.postDetails.imageUrls.length > 0 && (
                              <div className="flex space-x-1 space-x-reverse mb-2">
                                {conversation.postDetails.imageUrls
                                  .slice(0, 3)
                                  .map((imageUrl: string, idx: number) => (
                                    <img
                                      key={idx}
                                      src={imageUrl}
                                      alt={`Post image ${idx + 1}`}
                                      className="w-12 h-12 object-cover rounded border"
                                      style={{
                                        borderColor:
                                          "color-mix(in srgb, var(--color-secondary) 18%, transparent)",
                                      }}
                                      onError={(e) => {
                                        (
                                          e.target as HTMLImageElement
                                        ).style.display = "none";
                                      }}
                                    />
                                  ))}
                                {conversation.postDetails.imageUrls.length >
                                  3 && (
                                  <div
                                    className="w-12 h-12 rounded flex items-center justify-center text-xs font-medium"
                                    style={{
                                      background:
                                        "color-mix(in srgb, var(--color-secondary) 10%, white)",
                                      border:
                                        "1px solid color-mix(in srgb, var(--color-secondary) 18%, transparent)",
                                      color: "var(--color-secondary)",
                                    }}
                                  >
                                    +
                                    {conversation.postDetails.imageUrls.length -
                                      3}
                                  </div>
                                )}
                              </div>
                            )}
                          <p
                            className="text-xs mt-1"
                            style={{ color: "var(--color-secondary)" }}
                          >
                            Post ID: {conversation.postId.substring(0, 20)}...
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                {activities.length === 0 && !conversation.postId ? (
                  <div
                    className="text-center py-8 pr-4"
                    style={{ color: "var(--color-muted-foreground)" }}
                  >
                    <Clock size={48} className="mx-auto mb-2 opacity-20" />
                    <p>لا يوجد نشاط مسجل</p>
                  </div>
                ) : (
                  activities.map((activity) => {
                    return (
                      <div key={activity.id} className="relative pr-6">
                        <div
                          className="absolute -right-[29px] top-1 w-3 h-3 rounded-full border-2"
                          style={{
                            background: "var(--color-primary)",
                            borderColor:
                              "color-mix(in srgb, white 76%, var(--color-background) 24%)",
                            boxShadow:
                              "0 0 0 4px color-mix(in srgb, var(--color-primary) 10%, white)",
                          }}
                        ></div>
                        <div>
                          <p
                            className="text-sm font-medium"
                            style={{ color: "var(--color-foreground)" }}
                          >
                            {activity.description}
                          </p>
                          <p
                            className="text-xs mt-1"
                            style={{ color: "var(--color-muted-foreground)" }}
                          >
                            {format(
                              new Date(activity.createdAt),
                              "dd MMM, HH:mm",
                              { locale: arSA },
                            )}
                          </p>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* 🆕 Block Customer Modal */}
      {showBlockModal && onBlockConfirm && onBlockCancel && (
        <div className="fixed inset-0 bg-black bg-opacity-50 dark:bg-opacity-70 flex items-center justify-center z-50">
          <div className="business-modal-surface rounded-lg p-6 w-full max-w-md mx-4">
            <h3
              className="text-lg font-semibold mb-4"
              style={{ color: "var(--color-foreground)" }}
            >
              حظر العميل على صفحة الفيس بوك
            </h3>
            <p
              className="text-sm mb-4"
              style={{ color: "var(--color-muted-foreground)" }}
            >
              سيتم حظر هذا العميل على صفحة الفيس بوك المحددة ولن يتم استقبال
              رسائله.
            </p>

            <div className="mb-4">
              <label
                className="block text-sm font-medium mb-2"
                style={{ color: "var(--color-foreground)" }}
              >
                سبب الحظر (اختياري)
              </label>
              <textarea
                value={blockReason}
                onChange={(e) => onBlockReasonChange?.(e.target.value)}
                className="business-chat-input"
                rows={3}
                placeholder="أدخل سبب الحظر..."
              />
            </div>

            <div className="flex justify-end space-x-2">
              <button
                onClick={onBlockCancel}
                className="business-chip-button px-4 py-2 rounded-lg"
              >
                إلغاء
              </button>
              <button
                onClick={onBlockConfirm}
                disabled={blocking}
                className="business-chip-button px-4 py-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                style={{
                  background: "var(--business-danger)",
                  borderColor: "transparent",
                  color: "white",
                }}
              >
                {blocking ? "جاري الحظر..." : "تأكيد الحظر"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerProfile;

import React from "react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import { XMarkIcon, FunnelIcon } from "@heroicons/react/24/outline";
import { useAuth } from "../../../hooks/useAuthSimple";

export interface FilterState {
  unreadOnly: boolean;
  assignedTo: "all" | "me" | "unassigned";
  startDate: Date | null;
  endDate: Date | null;
}

interface FilterPanelProps {
  isOpen: boolean;
  filters: FilterState;
  onFilterChange: (filters: FilterState) => void;
  onClose: () => void;
  onReset: () => void;
}

const FilterPanel: React.FC<FilterPanelProps> = ({
  isOpen,
  filters,
  onFilterChange,
  onClose,
  onReset,
}) => {
  const { user } = useAuth();

  if (!isOpen) return null;

  const handleChange = (key: keyof FilterState, value: any) => {
    onFilterChange({
      ...filters,
      [key]: value,
    });
  };

  return (
    <div
      className="business-modal-surface border-b p-4 transition-all duration-300 ease-in-out"
      style={{ borderColor: "var(--business-muted-line)" }}
    >
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <FunnelIcon
            className="w-5 h-5"
            style={{ color: "var(--color-primary)" }}
          />
          <h3
            className="font-medium"
            style={{ color: "var(--color-foreground)" }}
          >
            تصفية المحادثات
          </h3>
        </div>
        <button onClick={onClose} className="business-chip-button">
          <XMarkIcon className="w-5 h-5" />
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {/* Unread Only */}
        <div className="flex items-center gap-2 mt-6">
          <input
            type="checkbox"
            id="unreadOnly"
            checked={filters.unreadOnly}
            onChange={(e) => handleChange("unreadOnly", e.target.checked)}
            className="rounded"
            style={{ accentColor: "var(--color-primary)" }}
          />
          <label
            htmlFor="unreadOnly"
            className="text-sm cursor-pointer select-none"
            style={{ color: "var(--color-foreground)" }}
          >
            غير مقروءة فقط
          </label>
        </div>

        {/* Assignment */}
        <div>
          <label
            className="block text-xs font-medium mb-1"
            style={{ color: "var(--color-muted-foreground)" }}
          >
            تعيين لـ
          </label>
          <select
            value={filters.assignedTo}
            onChange={(e) => handleChange("assignedTo", e.target.value)}
            className="business-control-input"
          >
            <option value="all">الكل</option>
            <option value="me">محادثاتي ({user?.firstName})</option>
            <option value="unassigned">غير معين</option>
          </select>
        </div>

        {/* Date Range - Start */}
        <div>
          <label
            className="block text-xs font-medium mb-1"
            style={{ color: "var(--color-muted-foreground)" }}
          >
            من تاريخ
          </label>
          <DatePicker
            selected={filters.startDate}
            onChange={(date: Date | null) => handleChange("startDate", date)}
            className="business-control-input"
            placeholderText="اختر تاريخ البداية"
            dateFormat="dd/MM/yyyy"
            isClearable
          />
        </div>

        {/* Date Range - End */}
        <div>
          <label
            className="block text-xs font-medium mb-1"
            style={{ color: "var(--color-muted-foreground)" }}
          >
            إلى تاريخ
          </label>
          <DatePicker
            selected={filters.endDate}
            onChange={(date: Date | null) => handleChange("endDate", date)}
            className="business-control-input"
            placeholderText="اختر تاريخ النهاية"
            dateFormat="dd/MM/yyyy"
            minDate={filters.startDate || undefined}
            isClearable
          />
        </div>
      </div>

      {/* Actions */}
      <div
        className="flex justify-end mt-4 pt-3 border-t"
        style={{ borderColor: "var(--business-muted-line)" }}
      >
        <button
          onClick={onReset}
          className="text-xs font-medium px-3 py-1"
          style={{ color: "var(--business-danger)" }}
        >
          إعادة تعيين الفلاتر
        </button>
      </div>
    </div>
  );
};

export default FilterPanel;

import React, { useState, memo } from "react";
import { Trash2, Reply, Forward, Star, Smile } from "lucide-react";
import ReactionSelector from "../Generic/ReactionSelector";

interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type:
    | "text"
    | "image"
    | "file"
    | "video"
    | "audio"
    | "template"
    | "IMAGE"
    | "FILE"
    | "VIDEO"
    | "AUDIO"
    | "TEMPLATE";
  isFromCustomer: boolean;
  status: "sending" | "sent" | "delivered" | "read" | "error";
  conversationId: string;
  fileUrl?: string;
  fileName?: string;
  fileSize?: number;
  isAiGenerated?: boolean;
  metadata?: any;
  attachments?: any[];
  isStarred?: boolean; // We will map this from metadata in parent or handle it here
}

interface MessageBubbleProps {
  message: Message;
  onDelete?: (messageId: string) => void;
  onForward?: (message: Message) => void;
  onStar?: (messageId: string, isStarred: boolean) => void;
  onReaction?: (messageId: string, reaction: string) => void;
  onReply?: (message: Message) => void;
  currentUserId?: string;
  hasBeenReplied?: boolean; // جديد: هل تم الرد على هذه الرسالة
}

const MessageBubble: React.FC<MessageBubbleProps> = memo(
  ({
    message,
    onDelete,
    onForward,
    onStar,
    onReaction,
    onReply,
    hasBeenReplied,
  }) => {
    const isCustomer = !!message.isFromCustomer;
    const isAI = message.isAiGenerated;
    const [showActions, setShowActions] = useState(false);
    const [showReactionSelector, setShowReactionSelector] = useState(false);

    // Parse metadata safely
    let metadata: any = {};
    try {
      if (typeof message.metadata === "string") {
        metadata = JSON.parse(message.metadata);
      } else if (typeof message.metadata === "object") {
        metadata = message.metadata;
      }
    } catch (e) {
      // ignore
    }

    const isStarred = metadata?.isStarred || message.isStarred;
    const replyTo = metadata?.replyTo;
    const myReaction = metadata?.myReaction;
    const reactionCounts = Object.entries(metadata?.reactions ?? {}).reduce<
      Record<string, number>
    >((acc, [reaction, count]) => {
      if (typeof count === "number") {
        acc[reaction] = count;
      }
      return acc;
    }, {});

    const formatTime = (date: Date) => {
      const now = new Date();
      const messageDate = new Date(date);
      const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      const msgDay = new Date(
        messageDate.getFullYear(),
        messageDate.getMonth(),
        messageDate.getDate(),
      );
      const yesterday = new Date(today);
      yesterday.setDate(yesterday.getDate() - 1);

      const diffDays = Math.floor(
        (today.getTime() - msgDay.getTime()) / (1000 * 60 * 60 * 24),
      );

      const timeStr = messageDate.toLocaleTimeString("ar-EG", {
        hour: "2-digit",
        minute: "2-digit",
        calendar: "gregory",
      });

      if (diffDays === 0) {
        // Today
        return timeStr;
      } else if (diffDays === 1) {
        // Yesterday
        return `أمس ${timeStr}`;
      } else if (diffDays < 7) {
        // Within this week
        return messageDate.toLocaleDateString("ar-EG", {
          weekday: "short",
          hour: "2-digit",
          minute: "2-digit",
          calendar: "gregory",
        });
      } else {
        // Older
        return messageDate.toLocaleDateString("ar-EG", {
          day: "numeric",
          month: "short",
          hour: "2-digit",
          minute: "2-digit",
          calendar: "gregory",
        });
      }
    };

    const formatFileSize = (bytes?: number) => {
      if (!bytes) return "";
      if (bytes < 1024) return bytes + " B";
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
      return (bytes / (1024 * 1024)).toFixed(1) + " MB";
    };

    const bubbleStyle = isCustomer
      ? hasBeenReplied === false
        ? {
            background: "var(--business-message-incoming-bg)",
            color: "var(--color-foreground)",
            borderRadius: "1rem",
            borderBottomRightRadius: "0.35rem",
            border: "2px solid var(--business-message-unreplied-border)",
          }
        : {
            background: "var(--business-message-incoming-bg)",
            color: "var(--color-foreground)",
            borderRadius: "1rem",
            borderBottomRightRadius: "0.35rem",
            border: "1px solid var(--business-message-incoming-border)",
          }
      : isAI
        ? {
            background:
              "linear-gradient(135deg, var(--business-success) 0%, color-mix(in srgb, var(--business-success) 68%, var(--color-secondary)) 100%)",
            color: "white",
            borderRadius: "1rem",
            borderBottomLeftRadius: "0.35rem",
          }
        : {
            background:
              "linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%)",
            color: "white",
            borderRadius: "1rem",
            borderBottomLeftRadius: "0.35rem",
          };

    const bubbleSubtleText = isCustomer
      ? "var(--color-muted-foreground)"
      : "rgba(255,255,255,0.72)";

    return (
      <div
        className={`flex w-full mb-4 group relative`}
        onMouseEnter={() => setShowActions(true)}
        onMouseLeave={() => setShowActions(false)}
      >
        <div
          className={`relative max-w-[85%] sm:max-w-xs lg:max-w-md ${isCustomer ? "ml-auto" : "mr-auto"}`}
        >
          {/* Action Buttons */}
          {showActions && (
            <div
              className={`absolute z-20 flex items-center gap-1 rounded-full p-1 shadow-sm ${
                isCustomer ? "right-2 top-2" : "left-2 top-2"
              }`}
              style={{
                background: "var(--business-floating-surface)",
                border: "1px solid var(--business-card-border)",
                backdropFilter: "blur(12px)",
              }}
            >
              {onReaction && (
                <div className="relative">
                  <button
                    onClick={() => setShowReactionSelector(!showReactionSelector)}
                    className="business-chip-button p-1.5 rounded-full transition-colors"
                    style={
                      myReaction
                        ? {
                            color: "var(--business-warning)",
                            background:
                              "color-mix(in srgb, var(--business-warning) 12%, var(--color-background))",
                          }
                        : undefined
                    }
                    title="إضافة تفاعل"
                  >
                    <Smile size={14} />
                  </button>
                  {showReactionSelector && (
                    <ReactionSelector
                      onSelect={(r) => {
                        if (onReaction) onReaction(message.id, r);
                        setShowReactionSelector(false);
                      }}
                      currentReaction={myReaction}
                    />
                  )}
                </div>
              )}
              {onReply && (
                <button
                  onClick={() => onReply(message)}
                  className="business-chip-button p-1.5 rounded-full transition-colors"
                  title="رد"
                >
                  <Reply size={14} />
                </button>
              )}
              {onStar && (
                <button
                  onClick={() => onStar(message.id, !!isStarred)}
                  className="business-chip-button p-1.5 rounded-full transition-colors"
                  style={
                    isStarred
                      ? {
                          color: "var(--business-warning)",
                          background:
                            "color-mix(in srgb, var(--business-warning) 12%, var(--color-background))",
                        }
                      : undefined
                  }
                  title={isStarred ? "إلغاء التمييز" : "تمييز الرسالة"}
                >
                  <Star size={14} fill={isStarred ? "currentColor" : "none"} />
                </button>
              )}
              {onForward && (
                <button
                  onClick={() => onForward(message)}
                  className="business-chip-button p-1.5 rounded-full transition-colors"
                  title="إعادة توجيه"
                >
                  <Forward size={14} />
                </button>
              )}
              {!isCustomer && onDelete && (
                <button
                  onClick={() => onDelete(message.id)}
                  className="business-chip-button p-1.5 rounded-full transition-colors"
                  style={{ color: "var(--business-danger)" }}
                  title="حذف الرسالة"
                >
                  <Trash2 size={14} />
                </button>
              )}
            </div>
          )}

          {/* Sender name (for employee/AI messages) */}
          {!isCustomer && (
            <div
              className="text-xs mb-1 text-left"
              style={{ color: "var(--color-muted-foreground)" }}
            >
              {message.senderName}
              {isAI && " 🤖"}
            </div>
          )}

          {/* Unreplied indicator for customer messages */}
          {isCustomer && hasBeenReplied === false && (
            <div
              className="flex items-center gap-1 mb-1 text-xs font-medium"
              style={{ color: "var(--business-danger)" }}
            >
              <span
                className="w-2 h-2 rounded-full animate-pulse"
                style={{ background: "var(--business-danger)" }}
              ></span>
              <span>غير مردود عليها</span>
            </div>
          )}

          <div className="px-4 py-2 rounded-2xl" style={bubbleStyle}>
            {/* Reply Context */}
            {replyTo && (
              <div
                className="mb-2 text-xs border-l-2 pl-2"
                style={{
                  borderColor: isCustomer
                    ? "var(--business-message-reply-accent)"
                    : "rgba(255,255,255,0.5)",
                  color: isCustomer
                    ? "var(--color-muted-foreground)"
                    : "rgba(255,255,255,0.8)",
                }}
              >
                <div className="font-semibold">{replyTo.senderName}</div>
                <div className="truncate opacity-80">
                  {replyTo.type === "text" ? replyTo.content : "مرفق/صورة"}
                </div>
              </div>
            )}

            {/* Image message */}
            {(message.type === "image" || message.type === "IMAGE") &&
              (message.fileUrl ||
                (typeof message.content === "string" &&
                  message.content.startsWith("http"))) && (
                <div className="mb-2">
                  <img
                    src={message.fileUrl || message.content}
                    alt="صورة"
                    loading="lazy"
                    className="rounded-lg max-w-full h-auto"
                    style={{ maxHeight: "300px" }}
                  />
                </div>
              )}

            {/* Video message */}
            {(message.type === "video" || message.type === "VIDEO") &&
              (message.fileUrl ||
                (typeof message.content === "string" &&
                  message.content.startsWith("http"))) && (
                <div className="mb-2">
                  <video
                    src={message.fileUrl || message.content}
                    controls
                    className="rounded-lg max-w-full h-auto"
                    style={{ maxHeight: "300px" }}
                  />
                </div>
              )}

            {/* Audio message */}
            {(message.type === "audio" || message.type === "AUDIO") &&
              (message.fileUrl ||
                (typeof message.content === "string" &&
                  message.content.startsWith("http"))) && (
                <div className="mb-2">
                  <audio
                    src={message.fileUrl || message.content}
                    controls
                    className="w-full min-w-[200px]"
                  />
                </div>
              )}

            {/* Template/Check for buttons in metadata or attachments */}
            {(message.type === "template" ||
              message.type === "TEMPLATE" ||
              (message.attachments && message.attachments.length > 0)) && (
              <div className="mb-2 flex flex-col gap-2">
                {message.attachments?.map((att: any, i: number) => {
                  // Skip standard media as they might be handled above, unless we want to show everything from attachments
                  if (att.type === "image" || att.type === "IMAGE") return null;
                  if (att.type === "video" || att.type === "VIDEO") return null;
                  if (att.type === "audio" || att.type === "AUDIO") return null;

                  // Handle template
                  if (att.payload && att.payload.template_type === "generic") {
                    return (
                      <div
                        key={i}
                        className="flex flex-col gap-2 overflow-hidden rounded-lg border"
                        style={{
                          borderColor: isCustomer
                            ? "var(--business-card-border)"
                            : "rgba(255,255,255,0.2)",
                        }}
                      >
                        {att.payload.elements?.map((el: any, j: number) => (
                          <div
                            key={j}
                            className="p-2"
                            style={{
                              background: isCustomer
                                ? "color-mix(in srgb, white 72%, var(--color-background) 28%)"
                                : "rgba(0,0,0,0.12)",
                            }}
                          >
                            {el.image_url && (
                              <img
                                src={el.image_url}
                                alt=""
                                className="w-full h-32 object-cover rounded mb-2"
                              />
                            )}
                            {el.title && (
                              <div className="font-bold text-sm mb-1">
                                {el.title}
                              </div>
                            )}
                            {el.subtitle && (
                              <div className="text-xs opacity-80 mb-2">
                                {el.subtitle}
                              </div>
                            )}
                            <div className="flex flex-col gap-1">
                              {el.buttons &&
                                el.buttons.map((btn: any, k: number) => (
                                  <a
                                    key={k}
                                    href={btn.url}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="block text-center py-1.5 px-3 rounded text-xs transition-colors truncate"
                                    style={{
                                      background: isCustomer
                                        ? "color-mix(in srgb, var(--color-primary) 10%, white)"
                                        : "rgba(255,255,255,0.2)",
                                      color: isCustomer
                                        ? "var(--color-primary)"
                                        : "white",
                                    }}
                                  >
                                    {btn.title}{" "}
                                    {btn.type === "web_url" ? "🔗" : ""}
                                  </a>
                                ))}
                            </div>
                          </div>
                        ))}
                      </div>
                    );
                  }

                  // Handle button template
                  if (att.payload && att.payload.template_type === "button") {
                    return (
                      <div key={i} className="flex flex-col gap-2">
                        <div className="text-sm opacity-90 mb-1">
                          {att.payload.text}
                        </div>
                        <div className="flex flex-col gap-1">
                          {att.payload.buttons &&
                            att.payload.buttons.map((btn: any, k: number) => (
                              <a
                                key={k}
                                href={btn.url}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="block text-center py-1.5 px-3 rounded text-xs transition-colors truncate"
                                style={{
                                  background: isCustomer
                                    ? "color-mix(in srgb, var(--color-primary) 10%, white)"
                                    : "rgba(255,255,255,0.2)",
                                  color: isCustomer
                                    ? "var(--color-primary)"
                                    : "white",
                                }}
                              >
                                {btn.title}
                              </a>
                            ))}
                        </div>
                      </div>
                    );
                  }

                  return null;
                })}
              </div>
            )}

            {/* File message */}
            {(message.type === "file" || message.type === "FILE") &&
              (message.fileUrl ||
                (typeof message.content === "string" &&
                  message.content.startsWith("http"))) && (
                <a
                  href={message.fileUrl || message.content}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center gap-2 p-2 rounded-lg mb-2"
                  style={{
                    background: isCustomer
                      ? "color-mix(in srgb, var(--color-border) 34%, white)"
                      : "rgba(255,255,255,0.2)",
                  }}
                >
                  <div
                    className="flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center"
                    style={{
                      background: isCustomer
                        ? "rgba(255,255,255,0.55)"
                        : "rgba(255,255,255,0.3)",
                    }}
                  >
                    📎
                  </div>
                  <div className="flex-1 min-w-0">
                    <p
                      className="text-sm font-medium truncate"
                      style={{
                        color: isCustomer ? "var(--color-foreground)" : "white",
                      }}
                    >
                      {message.fileName || message.content}
                    </p>
                    <p className="text-xs" style={{ color: bubbleSubtleText }}>
                      {formatFileSize(message.fileSize)}
                    </p>
                  </div>
                  <div className="text-xs">⬇️</div>
                </a>
              )}

            {/* Text content */}
            {message.content &&
              (() => {
                // Check if content has embedded URL (format: "text |TYPE_URL|url")
                if (
                  message.content.includes("|IMAGE_URL|") ||
                  message.content.includes("|FILE_URL|") ||
                  message.content.includes("|VIDEO_URL|") ||
                  message.content.includes("|AUDIO_URL|")
                ) {
                  const textPart =
                    message.content.split(
                      /(\|(IMAGE|FILE|VIDEO|AUDIO)_URL\|)/,
                    )[0] ?? "";
                  const trimmedTextPart = textPart.trim();
                  return trimmedTextPart ? (
                    <p className="text-sm whitespace-pre-wrap break-words mb-2">
                      {trimmedTextPart}
                    </p>
                  ) : null;
                }
                // Regular text content (not a URL)
                // Don't show content as text if it's a URL and the message type is media
                const isMediaType = [
                  "IMAGE",
                  "VIDEO",
                  "AUDIO",
                  "FILE",
                  "image",
                  "video",
                  "audio",
                  "file",
                ].includes(message.type);
                const contentIsUrl =
                  typeof message.content === "string" &&
                  message.content.startsWith("http");
                if (
                  message.content !== message.fileUrl &&
                  !(isMediaType && contentIsUrl)
                ) {
                  return (
                    <p className="text-sm whitespace-pre-wrap break-words">
                      {message.content}
                    </p>
                  );
                }
                return null;
              })()}

            {/* Reactions Display */}
            {Object.keys(reactionCounts).length > 0 && (
              <div
                className={`absolute -bottom-3 ${isCustomer ? "right-2" : "left-2"} rounded-full shadow-md border flex items-center px-1.5 py-0.5 gap-1`}
                style={{
                  background:
                    "linear-gradient(180deg, color-mix(in srgb, white 90%, var(--color-background) 10%) 0%, color-mix(in srgb, white 78%, var(--color-background) 22%) 100%)",
                  borderColor: "var(--business-card-border)",
                }}
              >
                {Object.entries(reactionCounts).map(([reaction, count]) => (
                  <span
                    key={reaction}
                    className="text-xs leading-none flex items-center"
                  >
                    <span className="text-sm">{reaction}</span>
                    {count > 1 && (
                      <span
                        className="text-[10px] ml-0.5 font-medium"
                        style={{ color: "var(--color-muted-foreground)" }}
                      >
                        {count}
                      </span>
                    )}
                  </span>
                ))}
              </div>
            )}

            {/* Timestamp and status */}
            <div className="flex items-center justify-end mt-1 gap-2">
              {isStarred && (
                <Star
                  size={10}
                  className="fill-current"
                  style={{ color: "var(--business-warning)" }}
                />
              )}
              <span className="text-xs opacity-75">
                {formatTime(message.timestamp)}
              </span>
              {!isCustomer && (
                <span className="text-xs flex items-center gap-0.5">
                  {message.status === "sending" && (
                    <span className="flex items-center gap-1 text-white/70">
                      <span className="animate-spin inline-block w-3 h-3 border border-white/50 border-t-white rounded-full"></span>
                    </span>
                  )}
                  {message.status === "sent" && (
                    <span className="text-white/90">✓</span>
                  )}
                  {message.status === "delivered" && (
                    <span className="text-white">✓✓</span>
                  )}
                  {message.status === "read" && (
                    <span style={{ color: "rgba(200, 235, 255, 0.92)" }}>
                      ✓✓
                    </span>
                  )}
                  {message.status === "error" && (
                    <span style={{ color: "rgba(255, 206, 206, 0.92)" }}>
                      ❌
                    </span>
                  )}
                </span>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  },
  (prevProps, nextProps) => {
    // Custom comparison function for better performance
    return (
      prevProps.message.id === nextProps.message.id &&
      prevProps.message.content === nextProps.message.content &&
      prevProps.message.timestamp.getTime() ===
        nextProps.message.timestamp.getTime() &&
      prevProps.message.status === nextProps.message.status &&
      prevProps.message.metadata === nextProps.message.metadata &&
      prevProps.hasBeenReplied === nextProps.hasBeenReplied &&
      prevProps.currentUserId === nextProps.currentUserId
    );
  },
);

MessageBubble.displayName = "MessageBubble";

export default MessageBubble;

import React, { useState, useRef } from "react";
import {
  PaperAirplaneIcon,
  PaperClipIcon,
  FaceSmileIcon,
  XMarkIcon,
} from "@heroicons/react/24/outline";
import EmojiPicker from "emoji-picker-react";
import QuickReplyDropdown, {
  QuickReply,
} from "../QuickReplyDropdown/QuickReplyDropdown";
import {
  replaceVariables,
  getContextVariables,
} from "../../../utils/quickReplyUtils";

interface MessageInputProps {
  onSendMessage: (content: string) => void;
  onSendFile: (file: File) => void;
  sending: boolean;
  uploadingFile: boolean;
  conversation?: any;
  user?: any;
  replyTo?: any;
  onCancelReply?: () => void;
  onOpenTextGallery?: () => void;
  onOpenImageGallery?: () => void;
}

const MessageInput: React.FC<MessageInputProps> = ({
  onSendMessage,
  onSendFile,
  sending,
  uploadingFile,
  conversation,
  user,
  replyTo,
  onCancelReply,
  onOpenTextGallery,
  onOpenImageGallery,
}) => {
  const [message, setMessage] = useState("");
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showQuickReplies, setShowQuickReplies] = useState(false);
  const [isCompactMobile, setIsCompactMobile] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const messageInputRef = useRef<HTMLTextAreaElement>(null);

  // Focus input on mount and after sending message
  React.useEffect(() => {
    // Focus input when component mounts
    if (messageInputRef.current && !sending && !uploadingFile) {
      messageInputRef.current.focus();
    }
  }, []);

  // Keep input focused after sending message
  React.useEffect(() => {
    if (!sending && messageInputRef.current) {
      // Small delay to ensure DOM is updated
      setTimeout(() => {
        messageInputRef.current?.focus();
      }, 50);
    }
  }, [sending]);

  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;

    const updateViewportMode = () => {
      setIsCompactMobile(window.innerWidth < 480);
    };

    updateViewportMode();
    window.addEventListener("resize", updateViewportMode);

    return () => {
      window.removeEventListener("resize", updateViewportMode);
    };
  }, []);

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (message.trim() && !sending) {
      onSendMessage(message);
      setMessage("");
      setShowQuickReplies(false);
      // Focus input after sending to allow immediate typing
      setTimeout(() => {
        messageInputRef.current?.focus();
      }, 100);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    // Don't send on Enter if quick replies dropdown is open
    if (e.key === "Enter" && !e.shiftKey && !showQuickReplies) {
      e.preventDefault();
      handleSend(e);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setMessage(value);

    // Show quick replies if starts with /
    if (value.startsWith("/")) {
      setShowQuickReplies(true);
    } else {
      setShowQuickReplies(false);
    }

    // Auto-resize textarea
    const textarea = e.target;
    textarea.style.height = "auto";
    textarea.style.height = Math.min(textarea.scrollHeight, 150) + "px";
  };

  const handleSelectQuickReply = (reply: QuickReply) => {
    // Replace variables in content
    const contextVars = getContextVariables(conversation, user);
    const processedContent = replaceVariables(reply.content, contextVars);

    setMessage(processedContent);
    setShowQuickReplies(false);
  };

  const handleEmojiClick = (emojiData: any) => {
    setMessage((prev) => prev + emojiData.emoji);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && !uploadingFile) {
      onSendFile(file);
    }
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  return (
    <div className="business-chat-composer business-chat-composer--facebook relative">
      {/* Quick Replies Dropdown */}
