};

const mutedStyle: React.CSSProperties = {
  color: "var(--color-muted-foreground)",
};

const primaryStyle: React.CSSProperties = {
  color: "var(--color-primary)",
};

const successStyle: React.CSSProperties = {
  color: "color-mix(in srgb, var(--business-success) 74%, black)",
};

const warningStyle: React.CSSProperties = {
  color: "color-mix(in srgb, var(--business-warning) 74%, black)",
};

const dangerStyle: React.CSSProperties = {
  color: "color-mix(in srgb, var(--business-danger) 74%, black)",
};

const selectedToneStyle: React.CSSProperties = {
  background: "color-mix(in srgb, var(--color-primary) 10%, white)",
  borderColor: "color-mix(in srgb, var(--color-primary) 20%, transparent)",
  color: "var(--color-primary)",
};

interface SavedText {
  id: string;
  title: string;
  content: string;
  imageUrls?: string[];
  isPinned?: boolean;
  createdAt: Date;
}

interface TextGalleryModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectText: (text: { content: string; imageUrls?: string[] }) => void;
}

const TextGalleryModal: React.FC<TextGalleryModalProps> = ({
  isOpen,
  onClose,
  onSelectText,
}) => {
  // States
  const [savedTexts, setSavedTexts] = useState<SavedText[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [updating, setUpdating] = useState(false);
  const [pinning, setPinning] = useState<string | null>(null);

  // New text form
  const [newTitle, setNewTitle] = useState("");
  const [newContent, setNewContent] = useState("");
  const [newImages, setNewImages] = useState<File[]>([]);
  const [newImagePreviews, setNewImagePreviews] = useState<string[]>([]);

  // Edit form
  const [editImages, setEditImages] = useState<File[]>([]);
  const [editImagePreviews, setEditImagePreviews] = useState<string[]>([]);
  const [editExistingImages, setEditExistingImages] = useState<string[]>([]);

  // Load texts
  const loadTexts = useCallback(async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/user/text-gallery");
      if (response.data?.texts) {
        // ترتيب النصوص: المثبتة أولاً، ثم الباقي حسب التاريخ (الأحدث أولاً)
        const sortedTexts = [...response.data.texts].sort((a, b) => {
          // إذا كان كلاهما مثبت أو غير مثبت، رتب حسب التاريخ (الأحدث أولاً)
          if (!!a.isPinned === !!b.isPinned) {
            return (
              new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
            );
          }
          // النصوص المثبتة تظهر أولاً
          return a.isPinned ? -1 : 1;
        });
        setSavedTexts(sortedTexts);
      }
    } catch (error) {
      console.error("Error loading text gallery:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (isOpen) {
      loadTexts();
    }
  }, [isOpen, loadTexts]);

  // Save new text
  const saveText = async () => {
    if (!newContent.trim() && newImages.length === 0) {
      alert("يرجى إدخال محتوى النص أو إرفاق صورة على الأقل");
      return;
    }

    try {
      setSaving(true);
      let imageUrls: string[] = [];

      // Upload images first
      if (newImages.length > 0) {
        for (const file of newImages) {
          if (!file.type.startsWith("image/")) continue;

          const formData = new FormData();
          formData.append("image", file);

          const uploadResponse = await apiClient.post(
            "/user/image-gallery/upload",
            formData,
            {
              headers: { "Content-Type": "multipart/form-data" },
            },
          );

          const imageUrl =
            uploadResponse.data?.image?.url ||
            uploadResponse.data?.image?.fileUrl;
          if (imageUrl) {
            imageUrls.push(imageUrl);
          }
        }
      }

      // Save text
      await apiClient.post("/user/text-gallery", {
        title: newTitle.trim() || null,
        content: newContent.trim() || null,
        imageUrls: imageUrls.length > 0 ? imageUrls : undefined,
      });

      // Reload and clear form
      await loadTexts();
      setNewTitle("");
      setNewContent("");
      setNewImages([]);
      setNewImagePreviews([]);
      alert("✅ تم حفظ النص بنجاح!");
    } catch (error) {
      console.error("Error saving text:", error);
      alert("فشل حفظ النص. حاول مرة أخرى.");
    } finally {
      setSaving(false);
    }
  };

  // Update text
  const updateText = async (textId: string, title: string, content: string) => {
    if (
      !content.trim() &&
      editExistingImages.length === 0 &&
      editImages.length === 0
    ) {
      alert("يرجى إدخال محتوى النص أو إرفاق صورة على الأقل");
      return;
    }

    try {
      setUpdating(true);
      let imageUrls: string[] = [...editExistingImages];

      // Upload new images
      if (editImages.length > 0) {
        for (const file of editImages) {
          if (!file.type.startsWith("image/")) continue;

          const formData = new FormData();
          formData.append("image", file);

          const uploadResponse = await apiClient.post(
            "/user/image-gallery/upload",
            formData,
            {
              headers: { "Content-Type": "multipart/form-data" },
            },
          );

          const imageUrl =
            uploadResponse.data?.image?.url ||
            uploadResponse.data?.image?.fileUrl;
          if (imageUrl) {
            imageUrls.push(imageUrl);
          }
        }
      }

      // Update text
      await apiClient.put(`/user/text-gallery/${textId}`, {
        title: title.trim() || null,
        content: content.trim() || null,
        imageUrls: imageUrls.length > 0 ? imageUrls : undefined,
      });

      // Reload and clear edit state
      await loadTexts();
      setEditingId(null);
      setEditImages([]);
      setEditImagePreviews([]);
      setEditExistingImages([]);
      alert("✅ تم تحديث النص بنجاح!");
    } catch (error) {
      console.error("Error updating text:", error);
      alert("فشل تحديث النص. حاول مرة أخرى.");
    } finally {
      setUpdating(false);
    }
  };

  // Delete text
  const deleteText = async (textId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذا النص من الحافظة؟")) return;

    try {
      setDeleting(textId);
      await apiClient.delete(`/user/text-gallery/${textId}`);
      setSavedTexts((prev) => prev.filter((t) => t.id !== textId));
    } catch (error) {
      console.error("Error deleting text:", error);
      alert("فشل حذف النص. حاول مرة أخرى.");
    } finally {
      setDeleting(null);
    }
  };

  // Toggle pin
  const togglePin = async (textId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      setPinning(textId);
      const text = savedTexts.find((t) => t.id === textId);
      // استخدام endpoint الصحيح للتثبيت
      await apiClient.patch(`/user/text-gallery/${textId}/pin`, {
        isPinned: !text?.isPinned,
      });
      await loadTexts();
    } catch (error) {
      console.error("Error toggling pin:", error);
      alert("فشل تحديث حالة التثبيت. حاول مرة أخرى.");
    } finally {
      setPinning(null);
    }
  };

  // Handle image selection for new text
  const handleNewImageSelect = async (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const files = e.target.files;
    if (!files) return;

    const validFiles: File[] = [];
    const previews: string[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files.item(i);
      if (!file) continue;
      if (file.size > 10 * 1024 * 1024) {
        alert(`حجم الملف ${file.name} كبير جداً. الحد الأقصى 10 ميجابايت.`);
        continue;
      }
      if (!file.type.startsWith("image/")) {
        alert(`الملف ${file.name} ليس صورة.`);
        continue;
      }

      validFiles.push(file);
      previews.push(URL.createObjectURL(file));
    }

    setNewImages((prev) => [...prev, ...validFiles]);
    setNewImagePreviews((prev) => [...prev, ...previews]);
    e.target.value = "";
  };

  // Handle image selection for edit
  const handleEditImageSelect = async (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const files = e.target.files;
    if (!files) return;

    const validFiles: File[] = [];
    const previews: string[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files.item(i);
      if (!file) continue;
      if (file.size > 10 * 1024 * 1024) continue;
      if (!file.type.startsWith("image/")) continue;

      validFiles.push(file);
      previews.push(URL.createObjectURL(file));
    }

    setEditImages((prev) => [...prev, ...validFiles]);
    setEditImagePreviews((prev) => [...prev, ...previews]);
    e.target.value = "";
  };

  // Remove image from new text
  const removeNewImage = (index: number) => {
    setNewImages((prev) => prev.filter((_, i) => i !== index));
    setNewImagePreviews((prev) => prev.filter((_, i) => i !== index));
  };

  // Remove existing image from edit
  const removeEditExistingImage = (index: number) => {
    setEditExistingImages((prev) => prev.filter((_, i) => i !== index));
  };

  // Remove new image from edit
  const removeEditNewImage = (index: number) => {
    setEditImages((prev) => prev.filter((_, i) => i !== index));
    setEditImagePreviews((prev) => prev.filter((_, i) => i !== index));
  };

  // Start editing
  const startEditing = (text: SavedText, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingId(text.id);
    setEditExistingImages(text.imageUrls || []);
    setEditImages([]);
    setEditImagePreviews([]);
  };

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={overlayStyle}
    >
      <div className="business-modal-surface flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden">
        {/* Header */}
        <div className="business-gallery-toolbar flex items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <svg
              className="h-6 w-6"
              style={successStyle}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
              />
            </svg>
            <h3 className="text-xl font-bold" style={headingStyle}>
              حافظة النصوص المحفوظة
            </h3>
            <span className="text-sm" style={mutedStyle}>
              ({savedTexts.length} نص)
            </span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="business-icon-button"
            style={mutedStyle}
          >
            <svg
              className="w-6 h-6"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-3 sm:p-4">
          {/* Add new text form */}
          <div className="business-page-panel mb-6 p-4">
            <h4 className="mb-3 text-sm font-semibold" style={headingStyle}>
              إضافة نص جديد
            </h4>
            <div className="space-y-3">
              <input
                type="text"
                placeholder="عنوان النص (اختياري)"
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                className="business-control-input w-full px-3 py-2"
              />
              <textarea
                placeholder="محتوى النص..."
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                rows={4}
                className="business-chat-input w-full resize-none px-3 py-2"
              />

              {/* Image upload */}
              <div className="space-y-2">
                <label
                  className="block text-sm font-medium"
                  style={headingStyle}
                >
                  إرفاق صور (اختياري)
                </label>
                <input
                  type="file"
                  accept="image/*"
                  multiple
                  onChange={handleNewImageSelect}
                  className="hidden"
                  id="text-gallery-new-image"
                />
                <label
                  htmlFor="text-gallery-new-image"
                  className="business-upload-dropzone cursor-pointer px-4 py-2"
                  data-tone="success"
                >
                  <svg
                    className="mr-2 h-5 w-5"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 4v16m8-8H4"
                    />
                  </svg>
                  <span className="text-sm">اختر صور لإرفاقها</span>
                </label>

                {newImagePreviews.length > 0 && (
                  <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4">
                    {newImagePreviews.map((preview, index) => (
                      <div key={index} className="relative group">
                        <img
                          src={preview}
                          alt=""
                          className="h-24 w-full rounded-lg border object-cover"
                          style={{ borderColor: "var(--business-card-border)" }}
                        />
                        <button
                          type="button"
                          onClick={() => removeNewImage(index)}
                          className="business-icon-button business-icon-button--sm absolute right-1 top-1 opacity-0 transition-opacity group-hover:opacity-100"
                          style={{
                            background: "var(--business-danger)",
                            borderColor: "transparent",
                            color: "white",
                          }}
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M6 18L18 6M6 6l12 12"
                            />
                          </svg>
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <button
                type="button"
                onClick={saveText}
                disabled={
                  saving || (!newContent.trim() && newImages.length === 0)
                }
                className="business-chip-button w-full px-4 py-2 disabled:cursor-not-allowed"
                style={{
                  background:
                    "linear-gradient(135deg, var(--business-success) 0%, color-mix(in srgb, var(--color-secondary) 82%, white) 100%)",
                  borderColor: "transparent",
                  color: "white",
                }}
              >
                {saving ? (
                  <div className="flex items-center justify-center">
                    <div
                      className="mr-2 h-4 w-4 animate-spin rounded-full border-b-2"
                      style={{ borderColor: "currentColor" }}
                    />
                    <span>جاري الحفظ...</span>
                  </div>
                ) : (
                  "حفظ النص"
                )}
              </button>
            </div>
          </div>

          {/* Texts list */}
          {loading ? (
            <div className="flex items-center justify-center h-64">
              <div className="text-center">
                <div
                  className="mx-auto mb-4 h-12 w-12 animate-spin rounded-full border-b-2"
                  style={{ borderColor: "var(--business-success)" }}
                />
                <p style={mutedStyle}>جاري تحميل النصوص...</p>
              </div>
            </div>
          ) : savedTexts.length === 0 ? (
            <div className="flex items-center justify-center h-64 text-center">
              <div>
                <svg
                  className="mx-auto mb-4 h-24 w-24"
                  style={mutedStyle}
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                  />
                </svg>
                <p className="mb-2 text-lg" style={headingStyle}>
                  لا توجد نصوص محفوظة
                </p>
                <p className="text-sm" style={mutedStyle}>
                  احفظ النصوص الشائعة هنا للإرسال السريع
                </p>
              </div>
            </div>
          ) : (
            <div className="space-y-3">
              {savedTexts.map((text) => (
                <div
                  key={text.id}
                  className={`business-page-panel group p-4 transition-all ${
                    editingId === text.id ? "" : "cursor-pointer"
                  }`}
                  style={editingId === text.id ? selectedToneStyle : undefined}
                  onClick={() => {
                    if (editingId !== text.id) {
                      onSelectText({
                        content: text.content,
                        ...(text.imageUrls && { imageUrls: text.imageUrls }),
                      });
                    }
                  }}
                >
                  {editingId === text.id ? (
                    // Edit mode
                    <div
                      className="space-y-3"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="text"
                        placeholder="عنوان النص (اختياري)"
                        defaultValue={text.title || ""}
                        id={`edit-title-${text.id}`}
                        className="business-control-input w-full px-3 py-2"
                      />
                      <textarea
                        placeholder="محتوى النص..."
                        defaultValue={text.content}
                        id={`edit-content-${text.id}`}
                        rows={4}
                        className="business-chat-input w-full resize-none px-3 py-2"
                      />

                      {/* Existing images */}
                      {editExistingImages.length > 0 && (
                        <div className="space-y-2">
                          <label
                            className="block text-sm font-medium"
                            style={headingStyle}
                          >
                            الصور الحالية
                          </label>
                          <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4">
                            {editExistingImages.map((url, index) => (
                              <div key={index} className="relative group">
                                <img
                                  src={url}
                                  alt=""
                                  className="h-24 w-full rounded-lg border object-cover"
                                  style={{
                                    borderColor: "var(--business-card-border)",
                                  }}
                                />
                                <button
                                  type="button"
                                  onClick={() => removeEditExistingImage(index)}
                                  className="business-icon-button business-icon-button--sm absolute right-1 top-1 opacity-0 transition-opacity group-hover:opacity-100"
                                  style={{
                                    background: "var(--business-danger)",
                                    borderColor: "transparent",
                                    color: "white",
                                  }}
                                >
                                  <svg
                                    className="w-4 h-4"
                                    fill="none"
                                    stroke="currentColor"
                                    viewBox="0 0 24 24"
                                  >
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2}
                                      d="M6 18L18 6M6 6l12 12"
                                    />
                                  </svg>
                                </button>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Add new images */}
                      <div className="space-y-2">
                        <input
                          type="file"
                          accept="image/*"
                          multiple
                          onChange={handleEditImageSelect}
                          className="hidden"
                          id={`edit-image-${text.id}`}
                        />
                        <label
                          htmlFor={`edit-image-${text.id}`}
                          className="business-upload-dropzone cursor-pointer px-4 py-2"
                          data-tone="primary"
                        >
                          <svg
                            className="mr-2 h-5 w-5"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M12 4v16m8-8H4"
                            />
                          </svg>
                          <span className="text-sm">إضافة صور جديدة</span>
                        </label>

                        {editImagePreviews.length > 0 && (
                          <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4">
                            {editImagePreviews.map((preview, index) => (
                              <div key={index} className="relative group">
                                <img
                                  src={preview}
                                  alt=""
                                  className="h-24 w-full rounded-lg border object-cover"
                                  style={{
                                    borderColor: "var(--business-card-border)",
                                  }}
                                />
                                <button
                                  type="button"
                                  onClick={() => removeEditNewImage(index)}
                                  className="business-icon-button business-icon-button--sm absolute right-1 top-1 opacity-0 transition-opacity group-hover:opacity-100"
                                  style={{
                                    background: "var(--business-danger)",
                                    borderColor: "transparent",
                                    color: "white",
                                  }}
                                >
                                  <svg
                                    className="w-4 h-4"
                                    fill="none"
                                    stroke="currentColor"
                                    viewBox="0 0 24 24"
                                  >
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2}
                                      d="M6 18L18 6M6 6l12 12"
                                    />
                                  </svg>
                                </button>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>

                      <div className="flex flex-wrap items-center justify-end gap-2">
                        <button
                          type="button"
                          onClick={() => {
                            setEditingId(null);
                            setEditImages([]);
                            setEditImagePreviews([]);
                            setEditExistingImages([]);
                          }}
                          className="business-chip-button px-4 py-2"
                        >
                          إلغاء
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            const titleEl = document.getElementById(
                              `edit-title-${text.id}`,
                            ) as HTMLInputElement;
                            const contentEl = document.getElementById(
                              `edit-content-${text.id}`,
                            ) as HTMLTextAreaElement;
                            if (titleEl && contentEl) {
                              updateText(
                                text.id,
                                titleEl.value,
                                contentEl.value,
                              );
                            }
                          }}
                          disabled={updating}
                          className="business-chip-button px-4 py-2"
                          data-active="true"
                        >
                          {updating ? "جاري التحديث..." : "حفظ التعديلات"}
                        </button>
                      </div>
                    </div>
                  ) : (
                    // View mode
                    <div className="flex items-start justify-between gap-3">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-2">
                          {text.isPinned && (
                            <svg
                              className="h-4 w-4"
                              style={warningStyle}
                              fill="currentColor"
                              viewBox="0 0 20 20"
                            >
                              <path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" />
                            </svg>
                          )}
                          <h5 className="font-semibold" style={headingStyle}>
                            {text.title || "بدون عنوان"}
                          </h5>
                        </div>
                        {text.content && (
                          <p
                            className="line-clamp-3 whitespace-pre-wrap text-sm"
                            style={mutedStyle}
                          >
                            {text.content}
                          </p>
                        )}
                        {text.imageUrls && text.imageUrls.length > 0 && (
                          <div className="flex gap-2 mt-2">
                            {text.imageUrls.slice(0, 4).map((url, i) => (
                              <img
                                key={i}
                                src={url}
                                alt=""
                                className="h-12 w-12 rounded border object-cover"
                                style={{
                                  borderColor: "var(--business-card-border)",
                                }}
                              />
                            ))}
                            {text.imageUrls.length > 4 && (
                              <div
                                className="flex h-12 w-12 items-center justify-center rounded border text-xs"
                                style={{
                                  background:
                                    "color-mix(in srgb, var(--color-border) 18%, white)",
                                  borderColor: "var(--business-card-border)",
                                  color: "var(--color-muted-foreground)",
                                }}
                              >
                                +{text.imageUrls.length - 4}
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                      <div className="mr-2 flex items-center gap-1 opacity-100 transition-opacity sm:opacity-0 sm:group-hover:opacity-100">
                        <button
                          type="button"
                          onClick={(e) => togglePin(text.id, e)}
                          disabled={pinning === text.id}
                          className="business-icon-button business-icon-button--sm"
                          style={text.isPinned ? warningStyle : mutedStyle}
                          title={text.isPinned ? "إلغاء التثبيت" : "تثبيت"}
                        >
                          <svg
                            className="w-4 h-4"
                            fill={text.isPinned ? "currentColor" : "none"}
                            stroke="currentColor"
                            viewBox="0 0 20 20"
                          >
                            <path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" />
                          </svg>
                        </button>
                        <button
                          type="button"
                          onClick={(e) => startEditing(text, e)}
                          className="business-icon-button business-icon-button--sm"
                          style={primaryStyle}
                          title="تعديل"
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                            />
                          </svg>
                        </button>
                        <button
                          type="button"
                          onClick={(e) => deleteText(text.id, e)}
                          disabled={deleting === text.id}
                          className="business-icon-button business-icon-button--sm"
                          style={dangerStyle}
                          title="حذف"
                        >
                          {deleting === text.id ? (
                            <div
                              className="h-4 w-4 animate-spin rounded-full border-b-2"
                              style={{ borderColor: "var(--business-danger)" }}
                            />
                          ) : (
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                              />
                            </svg>
                          )}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TextGalleryModal;

import React, { useState, useEffect, useMemo } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../../components/ui/dialog';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Label } from '../../components/ui/label';
import { Avatar, AvatarFallback, AvatarImage } from '../../components/ui/avatar';
import { Checkbox } from '../../components/ui/checkbox';
import { Search, Users, AlertTriangle, Check } from 'lucide-react';
import api from '../../services/api';
import { toast } from 'sonner';
import { getDateRange } from '../../utils/shiftHelpers';
import { cn } from '../../lib/utils';

interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  avatar?: string;
  employeeNumber?: string;
  department?: { name: string };
  position?: { title: string };
  userId?: string;
}

interface Assignment {
  id: string;
  date: string;
  user: { id: string; firstName: string; lastName: string };
}

interface AssignShiftDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  shiftId: string;
  shiftName: string;
  onSuccess?: () => void;
}

const AssignShiftDialog: React.FC<AssignShiftDialogProps> = ({
  open,
  onOpenChange,
  shiftId,
  shiftName,
  onSuccess
}) => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [existingAssignments, setExistingAssignments] = useState<Assignment[]>([]);
  const [selectedEmployeeIds, setSelectedEmployeeIds] = useState<string[]>([]);
  const [assignmentDate, setAssignmentDate] = useState<string>(
    new Date().toISOString().split('T')[0] ?? ''
  );
  const [endDate, setEndDate] = useState<string>('');
  const [dateRangeMode, setDateRangeMode] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const instanceId = useMemo(() => Math.random().toString(36).substring(7), []);

  console.log(`[AssignShiftDialog-${instanceId}] Render - open:`, open, 'employees:', employees.length, 'loading:', loading);

  useEffect(() => {
    if (!open) {
      // Reset on close
      console.log(`[AssignShiftDialog-${instanceId}] 🧹 Resetting state on close`);
      setSelectedEmployeeIds([]);
      setSearchTerm('');
      setDateRangeMode(false);
      setEndDate('');
      // We don't reset employees here anymore to prevent ghosting during re-renders
    } else {
      console.log(`[AssignShiftDialog-${instanceId}] 🔓 Dialog opened`);
    }
  }, [open, instanceId]);

  // Track state changes for debugging
  useEffect(() => {
    console.log(`[AssignShiftDialog-${instanceId}] 📊 STATE UPDATE:`, {
      employees: employees.length,
      existingAssignments: existingAssignments.length,
      loading,
      open
    });
  }, [employees.length, existingAssignments.length, loading, open, instanceId]);

  // Combine all data fetching into a single unified effect to prevent race conditions
  useEffect(() => {
    if (!open || !shiftId) return;

    const loadAllData = async () => {
      try {
        setLoading(true);
        console.log(`[AssignShiftDialog-${instanceId}] 🔄 Loading all data for shift:`, shiftId, 'date:', assignmentDate);

        // Single call to get shift and its current assignments
        const [shiftRes, employeesRes] = await Promise.all([
          api.get(`/hr/shifts/${shiftId}`),
          api.get('/hr/employees?limit=1000&status=ACTIVE')
        ]);

        const rawEmployees: Employee[] = employeesRes.data.employees || [];
        const allAssignments = shiftRes.data.shift?.assignments || [];

        console.log(`[AssignShiftDialog-${instanceId}] 📥 API Data Received:`, {
          employeesCount: rawEmployees.length,
          assignmentsCount: allAssignments.length,
          shiftFound: !!shiftRes.data.shift,
          employees: rawEmployees.map(e => ({ id: e.id, name: `${e.firstName} ${e.lastName}` }))
        });

        // Filter assignments by date locally for the "existingAssignments" state
        console.log(`[AssignShiftDialog-${instanceId}] 📅 Filtering assignments by date:`, assignmentDate);
        console.log(`[AssignShiftDialog-${instanceId}] 📅 All assignments:`, allAssignments.map((a: Assignment) => ({ id: a.id, date: a.date, userId: a.user?.id })));

        const currentAssignments = allAssignments.filter(
          (a: Assignment) => {
            const assignmentDateStr = a.date.split('T')[0];
            const matches = assignmentDateStr === assignmentDate;
            console.log(`[AssignShiftDialog-${instanceId}] 📅 Comparing: assignment date "${assignmentDateStr}" vs selected "${assignmentDate}" = ${matches}`);
            return matches;
          }
        );

        console.log(`[AssignShiftDialog-${instanceId}] 📅 Filtered assignments for ${assignmentDate}:`, currentAssignments.length);

        // Update states only if we actually got data (prevent accidental wipes)
        if (rawEmployees.length > 0) {
          setEmployees(rawEmployees);
        } else if (employees.length === 0) {
          console.warn(`[AssignShiftDialog-${instanceId}] ⚠️ Received 0 employees from API`);
          setEmployees([]);
        }

        setExistingAssignments(currentAssignments);
      } catch (error) {
        console.error(`[AssignShiftDialog-${instanceId}] ❌ Error in loadAllData:`, error);
        toast.error('فشل في جلب البيانات');
      } finally {
        setLoading(false);
      }
    };

    loadAllData();
  }, [open, shiftId, assignmentDate, instanceId]); // instanceId ensures fresh fetch on mount

  const handleAssign = async () => {
    if (selectedEmployeeIds.length === 0 || !assignmentDate) {
      toast.error('يرجى اختيار موظف واحد على الأقل والتاريخ');
      return;
    }

    if (dateRangeMode && !endDate) {
      toast.error('يرجى تحديد تاريخ الانتهاء');
      return;
    }

    try {
      setSubmitting(true);

      // Prepare dates array
      const dates = dateRangeMode && endDate
        ? getDateRange(assignmentDate, endDate)
        : [assignmentDate];

      // Use bulk assignment API
      const response = await api.post('/hr/shifts/bulk-assign', {
        shiftId,
        employeeIds: selectedEmployeeIds,
        dates
      });

      const { results, message } = response.data;

      // Show detailed results
      if (results.failed.length > 0) {
        // Show warning with details
        const failedDetails = results.failed.slice(0, 3).map((f: any) =>
          `${f.employeeName || 'موظف'}: ${f.error}`
        ).join('\n');

        toast.warning(
          `${message}\n\nالأخطاء:\n${failedDetails}${results.failed.length > 3 ? `\n...و ${results.failed.length - 3} أخطاء أخرى` : ''}`,
          { duration: 5000 }
        );
      } else {
        toast.success(message);
      }

      onSuccess?.();
      onOpenChange(false);
    } catch (error: any) {
      console.error('Error assigning shift:', error);
      const errorMessage = error.response?.data?.error || 'فشل في تعيين المناوبة';
      toast.error(errorMessage);
    } finally {
      setSubmitting(false);
    }
  };

  const filteredEmployees = useMemo(() => {
    console.log(`[AssignShiftDialog-${instanceId}] 🧩 Computing filteredEmployees:`, {
      totalEmployees: employees.length,
      existingAssignments: existingAssignments.length,
      assignmentDate
    });

    if (employees.length === 0) {
      console.log(`[AssignShiftDialog-${instanceId}] 🧩 No employees to filter`);
      return [];
    }

    const filtered = employees.filter(emp => {
      const matchesSearch = `${emp.firstName} ${emp.lastName} ${emp.employeeNumber || ''}`
        .toLowerCase()
        .includes(searchTerm.toLowerCase());

      // Check if employee is already assigned - with null check for user
      const isAlreadyAssigned = existingAssignments.some(
        a => a.user && (a.user.id === emp.id || (emp.userId && a.user.id === emp.userId)) && a.date.split('T')[0] === assignmentDate
      );

      return matchesSearch && !isAlreadyAssigned;
    });

    console.log(`[AssignShiftDialog-${instanceId}] 🧩 Filtering result: ${filtered.length} / ${employees.length}`);
    return filtered;
  }, [employees, searchTerm, existingAssignments, assignmentDate, instanceId]);

  const toggleEmployeeSelection = (empId: string) => {
    setSelectedEmployeeIds(prev =>
      prev.includes(empId) ? prev.filter(id => id !== empId) : [...prev, empId]
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-hidden flex flex-col p-0 border-none shadow-2xl bg-white/95 backdrop-blur-md rounded-3xl" dir="rtl">
        <DialogHeader className="p-6 pb-2">
          <DialogTitle className="text-2xl font-black text-gray-800">
            تعيين موظفين - {shiftName}
          </DialogTitle>
          <p className="text-sm text-gray-500 font-medium">أضف الموظفين إلى هذه المناوبة لفترة زمنية محددة</p>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 py-2 space-y-6">
          {/* Date Selection */}
          <div className="space-y-3 bg-gray-50/50 p-4 rounded-2xl border border-gray-100">
            <div className="flex items-center justify-between">
              <Label className="text-[10px] font-black uppercase tracking-wider text-gray-400">فترة التعيين</Label>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setDateRangeMode(!dateRangeMode)}
                className="text-xs font-bold text-purple-600 hover:bg-purple-50 rounded-lg h-7"
              >
                {dateRangeMode ? 'تبديل لتاريخ واحد' : 'تبديل لنطاق تاريخ'}
              </Button>
            </div>
            <div className={dateRangeMode ? 'grid grid-cols-2 gap-4' : ''}>
              <div className="space-y-1.5">
                {dateRangeMode && <Label className="text-[10px] font-bold text-gray-400 mr-1">تاريخ البدء</Label>}
                <Input
                  type="date"
                  value={assignmentDate}
                  onChange={(e) => {
                    setAssignmentDate(e.target.value);
                    setExistingAssignments([]);
                  }}
                  className="rounded-xl border-gray-200 focus:ring-purple-500 font-medium"
                />
              </div>
              {dateRangeMode && (
                <div className="space-y-1.5">
                  <Label className="text-[10px] font-bold text-gray-400 mr-1">تاريخ الانتهاء</Label>
                  <Input
                    type="date"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    min={assignmentDate}
                    className="rounded-xl border-gray-200 focus:ring-purple-500 font-medium"
                  />
                </div>
              )}
            </div>
          </div>

          {/* Existing Assignments Warning */}
          {existingAssignments.length > 0 && (
            <div className="bg-amber-50/50 border border-amber-100 rounded-2xl p-4 animate-in fade-in zoom-in-95">
              <div className="flex items-start gap-3">
                <div className="p-2 bg-amber-100 rounded-xl text-amber-600">
                  <AlertTriangle className="h-5 w-5" />
                </div>
                <div className="pt-0.5">
                  <p className="font-black text-amber-900 text-sm">
                    تنبيه: يوجد {existingAssignments.length} موظفاً معينين بالفعل
                  </p>
                  <p className="text-xs text-amber-700 font-medium mt-0.5">
                    المرتبطون بهذه المناوبة في تاريخ {assignmentDate} تم إخفاؤهم تلقائياً.
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Employee Search */}
          <div className="space-y-2">
            <Label className="text-[10px] font-black uppercase tracking-wider text-gray-400 ml-1">
              اختيار الموظفين {selectedEmployeeIds.length > 0 && (
                <span className="text-purple-600">({selectedEmployeeIds.length} محدد)</span>
              )}
            </Label>
            <div className="relative">
              <Search className="absolute right-3 top-3 h-4 w-4 text-gray-400" />
              <Input
                placeholder="ابحث بالاسم أو الرقم الوظيفي..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pr-10 rounded-xl border-gray-200 focus:ring-purple-500 h-11 shadow-sm"
              />
            </div>
          </div>

          {/* Employee List */}
          <div className="border border-gray-100 rounded-2xl shadow-sm bg-white overflow-hidden min-h-[300px]">
            {loading ? (
              <div className="py-20 flex flex-col items-center justify-center gap-4">
                <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-purple-600"></div>
                <p className="text-sm font-bold text-purple-600 animate-pulse">جاري تحميل الموظفين...</p>
              </div>
            ) : filteredEmployees.length > 0 ? (
              <div className="divide-y divide-gray-50">
                {filteredEmployees.map((emp) => {
                  const isSelected = selectedEmployeeIds.includes(emp.id);
                  return (
                    <div
                      key={emp.id}
                      onClick={() => toggleEmployeeSelection(emp.id)}
                      className={cn(
                        "flex items-center justify-between p-4 cursor-pointer transition-all hover:bg-gray-50/80",
                        isSelected ? "bg-purple-50/50" : ""
                      )}
                    >
                      <div className="flex items-center gap-4">
                        <Checkbox
                          checked={isSelected}
                          className="rounded-md border-gray-300 data-[state=checked]:bg-purple-600 data-[state=checked]:border-purple-600"
                        />
                        <div className="relative">
                          <Avatar className="h-11 w-11 border-2 border-white shadow-sm ring-1 ring-gray-100">
                            <AvatarImage src={emp.avatar} />
                            <AvatarFallback className="bg-gradient-to-br from-purple-100 to-indigo-100 text-purple-700 font-black text-sm">
                              {emp.firstName[0]}{emp.lastName[0]}
                            </AvatarFallback>
                          </Avatar>
                          {isSelected && (
                            <div className="absolute -top-1 -right-1 bg-purple-600 text-white rounded-full p-0.5 shadow-sm">
                              <Check className="h-2.5 w-2.5" />
                            </div>
                          )}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <p className="font-black text-gray-800">
                              {emp.firstName} {emp.lastName}
                            </p>
                            {emp.employeeNumber && (
                              <span className="text-[10px] font-black bg-gray-100 text-gray-500 px-1.5 py-0.5 rounded uppercase">
                                #{emp.employeeNumber}
                              </span>
                            )}
                          </div>
                          <p className="text-xs font-bold text-gray-400 mt-0.5">
                            {emp.department?.name || 'بدون قسم'}
                            {emp.position?.title && ` • ${emp.position.title}`}
                          </p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="py-20 text-center flex flex-col items-center gap-4">
                <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center text-gray-300">
                  <Search className="h-8 w-8" />
                </div>
                <div className="space-y-1">
                  <p className="font-bold text-gray-800">{searchTerm ? 'لا توجد نتائج مطابقة' : 'لا يوجد موظفين متاحين'}</p>
                  <p className="text-xs text-gray-500">حاول البحث بكلمات أخرى أو تغيير التاريخ</p>
                </div>
              </div>
            )}
          </div>

          {/* Summary */}
          {selectedEmployeeIds.length > 0 && (
            <div className="bg-gradient-to-r from-purple-600 to-indigo-600 rounded-2xl p-5 text-white shadow-lg shadow-purple-200 animate-in slide-in-from-bottom-2">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm">
                  <Users className="h-6 w-6" />
                </div>
                <div>
                  <p className="font-black text-lg">ملخص التعيين</p>
                  <p className="text-purple-100 font-bold text-sm">
                    {selectedEmployeeIds.length} موظف
                    {dateRangeMode && endDate
                      ? ` × ${getDateRange(assignmentDate, endDate).length} أيام عمل`
                      : ' • تعيين ليوم واحد'}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>

        <DialogFooter className="p-6 pt-2 bg-gray-50/50 flex flex-row items-center justify-between">
          <Button
            variant="ghost"
            onClick={() => onOpenChange(false)}
            className="font-bold text-gray-500 hover:text-gray-700"
          >
            إلغاء النافذة
          </Button>
          <Button
            onClick={handleAssign}
            disabled={submitting || selectedEmployeeIds.length === 0 || (dateRangeMode && !endDate)}
            className="bg-purple-600 hover:bg-purple-700 text-white font-black px-8 h-12 rounded-2xl shadow-xl shadow-purple-200 transition-all hover:scale-105 active:scale-95"
          >
            {submitting ? (
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                <span>جاري الحفظ...</span>
              </div>
            ) : (
              `تأكيد تعيين ${selectedEmployeeIds.length} موظف`
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default AssignShiftDialog;

import React from 'react';
import { Clock, TrendingUp, Bell, Calculator, Info, Trash2, Plus } from 'lucide-react';
import { Input } from '../../components/ui/input';
import { Button } from '../../components/ui/button';
import { Label } from '../../components/ui/label';
import { Switch } from '../../components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../../components/ui/select';

interface SubSettingProps {
  settings: any;
  setSettings: (settings: any) => void;
}

export const Tooltip: React.FC<{ content: string; children: React.ReactNode }> = ({ content, children }) => {
  const [show, setShow] = React.useState(false);
  return (
    <div className="relative inline-block">
      <div onMouseEnter={() => setShow(true)} onMouseLeave={() => setShow(false)} className="cursor-help">
        {children}
      </div>
      {show && (
        <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2 px-3 py-2 bg-gray-900 dark:bg-gray-700 text-white text-xs rounded-lg shadow-lg z-50 whitespace-nowrap max-w-xs">
          {content}
          <div className="absolute top-full left-1/2 transform -translate-x-1/2 -mt-1 border-4 border-transparent border-t-gray-900 dark:border-t-gray-700"></div>
        </div>
      )}
    </div>
  );
};

// --- 1. Grace Period & Daily Limit ---
export const PunctualityRules: React.FC<SubSettingProps> = ({ settings, setSettings }) => (
  <div className="space-y-4 p-5 border border-gray-200 dark:border-gray-700 rounded-xl bg-gray-50/50 dark:bg-gray-900/50">
    <div className="flex items-center justify-between">
      <div className="flex items-center gap-2">
        <Clock className="h-5 w-5 text-blue-500" />
        <h4 className="font-bold text-gray-900 dark:text-white">قواعد الحضور ورصيد التسامح</h4>
      </div>
      <div className="px-2 py-0.5 rounded-full text-[10px] bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 font-bold border border-green-200 dark:border-green-800">
        نظام نشط دائماً
      </div>
    </div>

    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <div className="space-y-2">
        <div className="flex items-center gap-2">
          <Label htmlFor="lateThresholdMinutes">حد التأخير اليومي المسموح</Label>
          <Tooltip content="الوقت المسموح به يومياً قبل اعتبار الموظف 'متأخر'. مثلاً 10 دقائق.">
            <Info className="h-4 w-4 text-gray-400" />
          </Tooltip>
        </div>
        <Input
          id="lateThresholdMinutes"
          name="lateThresholdMinutes"
          type="number"
          min={0}
          max={60}
          step={1}
          value={settings.lateThresholdMinutes}
          onChange={(e) => {
            const value = parseInt(e.target.value);
            const finalValue = isNaN(value) ? 10 : Math.max(0, Math.min(60, value));
            setSettings({ ...settings, lateThresholdMinutes: finalValue, lateThreshold: finalValue });
          }}
        />
        <p className="text-xs text-gray-500">دقيقة (افتراضي: 10)</p>
      </div>

      <div className="space-y-2">
        <div className="flex items-center gap-2">
          <Label htmlFor="gracePeriodMinutes">رصيد التسامح الشهري</Label>
          <Tooltip content="إجمالي الدقائق المسموح للموظف بتجاوزها شهرياً قبل بدء الخصم المالي">
            <Info className="h-4 w-4 text-gray-400" />
          </Tooltip>
        </div>
        <Input
          id="gracePeriodMinutes"
          name="gracePeriodMinutes"
          type="number"
          min={0}
          max={60}
          step={1}
          value={settings.gracePeriodMinutes}
          onChange={(e) => {
            const value = parseInt(e.target.value);
            setSettings({ ...settings, gracePeriodMinutes: isNaN(value) ? 60 : Math.max(0, Math.min(60, value)) });
          }}
        />
        <p className="text-xs text-gray-500">دقيقة (افتراضي: 60)</p>
      </div>
    </div>
  </div>
);

// --- 2. Financial Penalties (Escalation) ---
export const FinancialPenalties: React.FC<SubSettingProps> = ({ settings, setSettings }) => {
  // delayPenaltyTiers is already an array from the backend, no need to parse
  const penaltyTiers = Array.isArray(settings.delayPenaltyTiers) ? settings.delayPenaltyTiers : [];
  const isTieredActive = settings.autoDeductionEnabled && penaltyTiers.length > 0;

  return (
    <div className="space-y-6">
      <div className={`flex items-center justify-between p-4 border rounded-xl transition-all duration-300 ${settings.autoDeductionEnabled
        ? 'border-orange-200 dark:border-orange-800 bg-orange-50/50 dark:bg-orange-950/20 ring-1 ring-orange-500/20'
        : 'border-gray-200 dark:border-gray-800 bg-gray-50/30'
        }`}>
        <div className="flex-1">
          <div className="flex items-center gap-2">
            <Label className={`font-bold text-lg ${settings.autoDeductionEnabled ? 'text-orange-900 dark:text-orange-100' : 'text-gray-500'}`}>
              تفعيل الجزاءات المالية الآلية
            </Label>
            {settings.autoDeductionEnabled ? (
              <span className="px-2 py-0.5 bg-orange-500 text-white text-[10px] rounded-full font-bold animate-pulse">نشط حالياً ✅</span>
            ) : (
              <span className="px-2 py-0.5 bg-gray-200 text-gray-500 text-[10px] rounded-full font-bold">معطل ⚠️</span>
            )}
          </div>
          <p className={`text-sm ${settings.autoDeductionEnabled ? 'text-orange-700 dark:text-orange-300' : 'text-gray-400'}`}>
            خصم قيمة وقت التأخير من الراتب تلقائياً بعد نفاد رصيد التسامح
          </p>
        </div>
        <Switch
          checked={settings.autoDeductionEnabled}
          onCheckedChange={(checked) => setSettings({ ...settings, autoDeductionEnabled: checked })}
        />
      </div>

      {settings.autoDeductionEnabled && (
        <div className="space-y-4 animate-in slide-in-from-top-4 duration-500">
          <div className="flex items-center justify-between p-4 border border-blue-200 dark:border-blue-800 rounded-xl bg-blue-50/50 dark:bg-blue-950/20">
            <div>
              <Label className="text-blue-900 dark:text-blue-100 font-semibold">مراجعة الـ HR قبل الخصم</Label>
              <p className="text-sm text-blue-700 dark:text-blue-300">تحويل الخصومات لحالة "معلق" حتى يتم اعتمادها يدوياً</p>
            </div>
            <Switch
              checked={settings.requireDeductionReview}
              onCheckedChange={(checked) => setSettings({ ...settings, requireDeductionReview: checked })}
            />
          </div>

          {!isTieredActive && (
            <div className="space-y-4 p-5 border border-gray-200 dark:border-gray-700 rounded-xl bg-gray-50/50 dark:bg-gray-900/50 relative overflow-hidden group">
              <div className="flex items-center gap-2">
                <TrendingUp className="h-5 w-5 text-red-500" />
                <h4 className="font-bold text-gray-900 dark:text-white">مضاعفات الخصم للتكرار</h4>
                <span className="text-[10px] text-gray-500 font-normal">(يعمل الآن بالدقيقة)</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="firstViolationMultiplier">المخالفة الأولى</Label>
                  <Input
                    id="firstViolationMultiplier"
                    name="firstViolationMultiplier"
                    type="number"
                    step="0.1"
                    value={settings.firstViolationMultiplier}
                    onChange={(e) => setSettings({ ...settings, firstViolationMultiplier: parseFloat(e.target.value) || 1.0 })}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="secondViolationMultiplier">المخالفة الثانية</Label>
                  <Input
                    id="secondViolationMultiplier"
                    name="secondViolationMultiplier"
                    type="number"
                    step="0.1"
                    value={settings.secondViolationMultiplier}
                    onChange={(e) => setSettings({ ...settings, secondViolationMultiplier: parseFloat(e.target.value) || 2.0 })}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="thirdViolationMultiplier">المخالفة الثالثة+</Label>
                  <Input
                    id="thirdViolationMultiplier"
                    name="thirdViolationMultiplier"
                    type="number"
                    step="0.1"
                    value={settings.thirdViolationMultiplier}
                    onChange={(e) => setSettings({ ...settings, thirdViolationMultiplier: parseFloat(e.target.value) || 3.0 })}
                  />
                </div>
              </div>
            </div>
          )}

          <div className={`space-y-4 p-5 border rounded-xl transition-all ${isTieredActive
            ? 'border-purple-200 dark:border-purple-900 bg-purple-50/30 dark:bg-purple-950/20 ring-1 ring-purple-500/10'
            : 'border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50'
            }`}>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Clock className="h-5 w-5 text-purple-500" />
                <h4 className="font-bold text-gray-900 dark:text-white">جدول شرائح الخصم الثابت</h4>
                {isTieredActive && (
                  <span className="px-2 py-0.5 bg-purple-100 text-purple-700 text-[10px] rounded-full font-bold border border-purple-200">
                    مفعّل (يلغي الخصم بالدقيقة)
                  </span>
                )}
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  const handleAddTier = () => {
                    const currentTiers = penaltyTiers;
                    const newTiers = [...currentTiers, { minMinutes: 15, deductionDays: 0.25 }].sort((a, b) => a.minMinutes - b.minMinutes);
                    setSettings({ ...settings, delayPenaltyTiers: JSON.stringify(newTiers) });
                  };
                  handleAddTier();
                }}
              >
                <Plus className="h-4 w-4 ml-1" />
                إضافة شريحة
              </Button>
            </div>

            <p className="text-sm text-gray-500 dark:text-gray-400">
              إذا تم تحديد شرائح، سيتم تطبيق خصم الشريحة بدلاً من الخصم بالدقيقة. يتم اختيار الشريحة الأعلى التي تنطبق على مدة التأخير.
            </p>

            <div className="space-y-2">
              {(() => {
                try {
                  const tiers = penaltyTiers; // Use penaltyTiers directly
                  if (tiers.length === 0) return <p className="text-center py-4 text-gray-400 italic">لا توجد شرائح مضافة حالياً (يتم استخدام الخصم بالدقيقة)</p>;

                  return penaltyTiers.map((tier: any, index: number) => (
                    <div key={index} className="flex items-center gap-3 p-3 bg-white dark:bg-gray-800 rounded-lg border">
                      <div className="flex-1">
                        <Label htmlFor={`tier-min-${index}`} className="text-[10px]">تأخير يبدأ من (دقيقة)</Label>
                        <Input
                          id={`tier-min-${index}`}
                          name={`tier-min-${index}`}
                          type="number"
                          value={tier.minMinutes}
                          onChange={(e) => {
                            const newTiers = [...tiers];
                            newTiers[index].minMinutes = parseInt(e.target.value) || 0;
                            setSettings({ ...settings, delayPenaltyTiers: JSON.stringify(newTiers) });
                          }}
                        />
                      </div>
                      <div className="flex-1">
                        <Label htmlFor={`tier-days-${index}`} className="text-[10px]">الخصم المطبق (أيام)</Label>
                        <Input
                          id={`tier-days-${index}`}
                          name={`tier-days-${index}`}
                          type="number"
                          step="0.1"
                          value={tier.deductionDays}
                          onChange={(e) => {
                            const newTiers = [...tiers];
                            newTiers[index].deductionDays = parseFloat(e.target.value) || 0;
                            setSettings({ ...settings, delayPenaltyTiers: JSON.stringify(newTiers) });
                          }}
                        />
                      </div>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="mt-4 text-red-500"
                        onClick={() => {
                          const newTiers = tiers.filter((_: any, i: number) => i !== index);
                          setSettings({ ...settings, delayPenaltyTiers: JSON.stringify(newTiers) });
                        }}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  ));
                } catch (e) {
                  return null;
                }
              })()}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- 3. Calculation Engine Settings ---
export const CalculationEngine: React.FC<SubSettingProps> = ({ settings, setSettings }) => {
  const minuteRate = settings.workingDaysPerMonth && settings.workingHoursPerDay
    ? (1 / settings.workingDaysPerMonth / settings.workingHoursPerDay / 60).toFixed(4)
    : '0.0000';

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="workingDaysPerMonth">أيام العمل في الشهر</Label>
          <Input
            id="workingDaysPerMonth"
            name="workingDaysPerMonth"
            type="number"
            value={settings.workingDaysPerMonth}
