const SuperAdminSidebar: React.FC<SuperAdminSidebarProps> = ({
  mobileOpen,
  setMobileOpen,
  isCollapsed,
  setIsCollapsed,
  user,
  isDark,
  handleProfileMenuOpen,
}) => {
  const location = useLocation();
  const [openGroups, setOpenGroups] = useState<{ [key: string]: boolean }>({
    الرئيسية: true,
  });

  const handleDrawerToggle = () => setMobileOpen(!mobileOpen);

  const handleGroupToggle = (groupTitle: string) => {
    if (isCollapsed) setIsCollapsed(false);
    setOpenGroups((prev) => ({
      ...prev,
      [groupTitle]: !prev[groupTitle],
    }));
  };

  const sidebarColors = {
    bg: isDark ? "#0f172a" : "#ffffff",
    text: isDark ? "#f1f5f9" : "#1e293b",
    border: isDark ? alpha("#eceef2", 0.1) : "#e2e8f0",
    groupBgActive: isDark ? alpha("#3b82f6", 0.1) : alpha("#3b82f6", 0.05),
    groupTextActive: "#3b82f6",
    itemText: isDark ? "#94a3b8" : "#64748b",
    itemHoverBg: isDark ? alpha("#3b82f6", 0.08) : alpha("#3b82f6", 0.04),
    footerBg: isDark ? alpha("#1e293b", 0.5) : "#f8fafc",
  };

  const drawerContent = (
    <Box
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        bgcolor: sidebarColors.bg,
        color: sidebarColors.text,
        overflowX: "hidden",
        direction: "rtl",
        transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
        borderLeft: isDark ? "none" : "1px solid",
        borderColor: sidebarColors.border,
      }}
    >
      {/* Brand Section */}
      <Box
        sx={{
          p: 3,
          display: "flex",
          alignItems: "center",
          gap: 2,
          borderBottom: "1px solid",
          borderColor: sidebarColors.border,
          mb: 2,
        }}
      >
        <Avatar
          sx={{
            width: 40,
            height: 40,
            background: "linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)",
            boxShadow: "0 4px 12px rgba(37, 99, 235, 0.3)",
          }}
        >
          <AdminIcon sx={{ fontSize: 24 }} />
        </Avatar>
        {!isCollapsed && (
          <Box>
            <Typography
              variant="subtitle1"
              sx={{
                fontWeight: 800,
                lineHeight: 1.2,
                letterSpacing: "-0.02em",
                color: isDark ? "#f8fafc" : "#1e293b",
              }}
            >
              التحكم الذكي
            </Typography>
            <Typography
              variant="caption"
              sx={{ color: isDark ? "#64748b" : "#94a3b8", fontWeight: 500 }}
            >
              السوبر أدمن
            </Typography>
          </Box>
        )}
      </Box>

      {/* Navigation List */}
      <List
        sx={{
          flexGrow: 1,
          px: 1.5,
          "& .MuiListItem-root": { py: 0.5 },
          overflowY: "auto",
          "&::-webkit-scrollbar": { width: "4px" },
          "&::-webkit-scrollbar-thumb": {
            bgcolor: alpha(isDark ? "#fff" : "#000", 0.1),
            borderRadius: "4px",
          },
        }}
      >
        {menuGroups.map((group) => {
          const isOpen = openGroups[group.title];
          const hasActiveItem = group.items.some(
            (item) => matchesPath(location.pathname, item.path),
          );

          return (
            <React.Fragment key={group.title}>
              <ListItem disablePadding>
                <ListItemButton
                  onClick={() => handleGroupToggle(group.title)}
                  sx={{
                    py: 1.2,
                    px: isCollapsed ? 2 : 2,
                    mb: 0.5,
                    borderRadius: "12px",
                    justifyContent: isCollapsed ? "center" : "initial",
                    bgcolor:
                      hasActiveItem && !isOpen
                        ? sidebarColors.groupBgActive
                        : "transparent",
                    color: hasActiveItem
                      ? sidebarColors.groupTextActive
                      : sidebarColors.itemText,
                    "&:hover": {
                      bgcolor: sidebarColors.itemHoverBg,
                      color: isDark ? "#f8fafc" : "#1e293b",
                    },
                    transition: "all 0.2s ease-in-out",
                  }}
                >
                  <ListItemIcon
                    sx={{
                      minWidth: isCollapsed ? 0 : 36,
                      color: hasActiveItem
                        ? sidebarColors.groupTextActive
                        : "inherit",
                    }}
                  >
                    {group.icon}
                  </ListItemIcon>
                  {!isCollapsed && (
                    <>
                      <ListItemText
                        primary={group.title}
                        primaryTypographyProps={{
                          variant: "body2",
                          sx: {
                            fontWeight: hasActiveItem ? 700 : 500,
                            fontSize: "0.875rem",
                          },
                        }}
                      />
                      {isOpen ? (
                        <ExpandLess sx={{ fontSize: 18 }} />
                      ) : (
                        <ExpandMore sx={{ fontSize: 18 }} />
                      )}
                    </>
                  )}
                </ListItemButton>
              </ListItem>

              <Collapse
                in={!!isOpen && !isCollapsed}
                timeout="auto"
                unmountOnExit
              >
                <List component="div" disablePadding sx={{ mt: 0.5, mb: 1 }}>
                  {group.items.map((item) => {
                    const isSelected = matchesPath(location.pathname, item.path);
                    return (
                      <ListItem key={item.text} disablePadding sx={{ px: 1 }}>
                        <ListItemButton
                          component={Link}
                          to={item.path}
                          onClick={() => mobileOpen && setMobileOpen(false)}
                          selected={isSelected}
                          sx={{
                            borderRadius: "10px",
                            py: 0.8,
                            pl: 4.5,
                            pr: 2,
                            mb: 0.25,
                            color: isSelected ? "#fff" : sidebarColors.itemText,
                            bgcolor: isSelected
                              ? "#3b82f6 !important"
                              : "transparent",
                            boxShadow: isSelected
                              ? "0 4px 12px rgba(59, 130, 246, 0.4)"
                              : "none",
                            "&:hover": {
                              bgcolor: isSelected
                                ? "#2563eb !important"
                                : sidebarColors.itemHoverBg,
                              color: isSelected ? "#fff" : isDark ? "#f8fafc" : "#1e293b",
                              transform: "translateX(-4px)",
                            },
                            transition: "all 0.2s",
                          }}
                        >
                          <ListItemText
                            primary={item.text}
                            primaryTypographyProps={{
                              variant: "body2",
                              sx: {
                                fontSize: "0.8125rem",
                                fontWeight: isSelected ? 600 : 400,
                              },
                            }}
                          />
                        </ListItemButton>
                      </ListItem>
                    );
                  })}
                </List>
              </Collapse>
            </React.Fragment>
          );
        })}
      </List>

      {/* Footer Profile */}
      <Box
        sx={{
          p: 2,
          mt: "auto",
          borderTop: "1px solid",
          borderColor: sidebarColors.border,
          bgcolor: sidebarColors.footerBg,
        }}
      >
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 1.5,
            cursor: "pointer",
            p: 1,
            borderRadius: "12px",
            "&:hover": { bgcolor: alpha(isDark ? "#fff" : "#000", 0.05) },
          }}
          onClick={handleProfileMenuOpen}
        >
          <Avatar
            sx={{
              width: 36,
              height: 36,
              bgcolor: "#3b82f6",
              fontSize: "0.875rem",
              fontWeight: 700,
            }}
          >
            {user?.firstName?.charAt(0)}
          </Avatar>
          {!isCollapsed && (
            <Box sx={{ minWidth: 0, flexGrow: 1 }}>
              <Typography
                variant="body2"
                noWrap
                sx={{ fontWeight: 600, color: isDark ? "#f8fafc" : "#1e293b" }}
              >
                {user?.firstName} {user?.lastName}
              </Typography>
              <Typography
                variant="caption"
                noWrap
                sx={{ color: sidebarColors.itemText, display: "block" }}
              >
                {user?.email}
              </Typography>
            </Box>
          )}
          {!isCollapsed && (
            <SettingsIcon
              sx={{ fontSize: 16, color: isDark ? "#475569" : "#94a3b8" }}
            />
          )}
        </Box>
      </Box>
    </Box>
  );

  const currentDrawerWidth = isCollapsed ? collapsedDrawerWidth : drawerWidth;

    return (
      <Box
        component="nav"
        sx={{
        width: { xs: 0, sm: currentDrawerWidth },
          flexShrink: { sm: 0 },
          overflow: "hidden",
          transition: "width 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
        }}
      >
      <Drawer
        variant="temporary"
        anchor="right"
        open={mobileOpen}
        onClose={handleDrawerToggle}
        ModalProps={{ keepMounted: true }}
        sx={{
          display: { xs: "block", sm: "none" },
          "& .MuiDrawer-paper": {
            boxSizing: "border-box",
            width: drawerWidth,
            border: "none",
          },
        }}
      >
        {drawerContent}
      </Drawer>
      <Drawer
        variant="permanent"
        anchor="right"
        sx={{
          display: { xs: "none", sm: "block" },
          "& .MuiDrawer-paper": {
            boxSizing: "border-box",
            width: currentDrawerWidth,
            border: "none",
            transition: "width 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
            overflowX: "hidden",
          },
        }}
        open
      >
        {drawerContent}
      </Drawer>
    </Box>
  );
};

export default SuperAdminSidebar;

import React, { useState, useEffect } from "react";
import { buildApiUrl } from "../../utils/urlHelper";
import { tokenManager } from "../../utils/tokenManager";
import { Card, CardContent, CardHeader, CardTitle } from "../ui/card";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import {
  AlertTriangle,
  CheckCircle,
  XCircle,
  Clock,
  RefreshCw,
  X,
} from "lucide-react";

interface Alert {
  id: string;
  type: string;
  severity: "critical" | "warning" | "info";
  message: string;
  icon: string;
  color: string;
  timestamp: string;
  data: {
    currentValue: any;
    threshold: any;
    details: string;
  };
  resolved: boolean;
  resolvedAt?: string;
  resolvedBy?: string;
}

interface AlertsData {
  alerts: Alert[];
  stats: {
    active: number;
    total: number;
    byType: Record<string, number>;
    bySeverity: {
      critical: number;
      warning: number;
      info: number;
    };
    lastCheck: string;
    thresholds: Record<string, number>;
  };
  summary: {
    hasAlerts: boolean;
    totalActive: number;
    critical: number;
    warnings: number;
    lastCheck: string;
    mostRecentAlert: Alert | null;
  };
}

interface AlertsPanelProps {
  className?: string;
}

const AlertsPanel: React.FC<AlertsPanelProps> = ({ className = "" }) => {
  const [alertsData, setAlertsData] = useState<AlertsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [resolving, setResolving] = useState<Set<string>>(new Set());

  const fetchAlerts = async () => {
    try {
      setError(null);
      const token = tokenManager.getAccessToken();
      const response = await fetch(buildApiUrl("monitor/alerts"), {
        headers: {
          Authorization: token ? `Bearer ${token}` : "",
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (data.success) {
        setAlertsData(data.data);
      } else {
        throw new Error(data.error || "Failed to fetch alerts");
      }
    } catch (err) {
      console.error("Error fetching alerts:", err);
      setError(err instanceof Error ? err.message : "Unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const resolveAlert = async (alertId: string) => {
    try {
      setResolving((prev) => new Set(prev).add(alertId));

      const token = tokenManager.getAccessToken();
      const response = await fetch(
        buildApiUrl(`monitor/alerts/${alertId}/resolve`),
        {
          method: "POST",
          headers: {
            Authorization: token ? `Bearer ${token}` : "",
            "Content-Type": "application/json",
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (data.success) {
        // إعادة تحميل التنبيهات
        await fetchAlerts();
      } else {
        throw new Error(data.error || "Failed to resolve alert");
      }
    } catch (err) {
      console.error("Error resolving alert:", err);
      setError(err instanceof Error ? err.message : "Failed to resolve alert");
    } finally {
      setResolving((prev) => {
        const newSet = new Set(prev);
        newSet.delete(alertId);
        return newSet;
      });
    }
  };

  const triggerCheck = async () => {
    try {
      setLoading(true);
      const token = tokenManager.getAccessToken();
      const response = await fetch(buildApiUrl("monitor/alerts/check"), {
        method: "POST",
        headers: {
          Authorization: token ? `Bearer ${token}` : "",
          "Content-Type": "application/json",
        },
      });

      if (response.ok) {
        await fetchAlerts();
      }
    } catch (err) {
      console.error("Error triggering alert check:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAlerts();

    // تحديث تلقائي كل 10 دقائق (reduced from 1 minute)
    const interval = setInterval(fetchAlerts, 10 * 60 * 1000);

    return () => clearInterval(interval);
  }, []);

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case "critical":
        return "text-red-600 bg-red-100 border-red-200";
      case "warning":
        return "text-yellow-600 bg-yellow-100 border-yellow-200";
      case "info":
        return "text-blue-600 bg-blue-100 border-blue-200";
      default:
        return "text-gray-600 bg-gray-100 border-gray-200";
    }
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case "critical":
        return <XCircle className="w-5 h-5 text-red-600" />;
      case "warning":
        return <AlertTriangle className="w-5 h-5 text-yellow-600" />;
      case "info":
        return <CheckCircle className="w-5 h-5 text-blue-600" />;
      default:
        return <Clock className="w-5 h-5 text-gray-600" />;
    }
  };

  const formatTimestamp = (timestamp: string) => {
    return new Date(timestamp).toLocaleString("ar-EG", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
  };

  const formatValue = (value: any) => {
    if (typeof value === "number") {
      if (value < 100) {
        return `${value.toFixed(2)}%`;
      } else {
        return `${Math.round(value)}ms`;
      }
    }
    return String(value);
  };

  if (loading && !alertsData) {
    return (
      <Card className={className}>
        <CardContent className="flex items-center justify-center p-6">
          <div className="flex items-center space-x-2 space-x-reverse">
            <RefreshCw className="w-5 h-5 animate-spin" />
            <span>جاري تحميل التنبيهات...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card className={className}>
        <CardContent className="p-6">
          <div className="text-center">
            <XCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-red-600 mb-2">
              خطأ في تحميل التنبيهات
            </h3>
            <p className="text-gray-600 mb-4">{error}</p>
            <Button onClick={fetchAlerts} variant="outline">
              <RefreshCw className="w-4 h-4 mr-2" />
              إعادة المحاولة
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!alertsData) {
    return null;
  }

  return (
    <Card className={className}>
      <CardHeader>
        <div className="flex justify-between items-center">
          <CardTitle className="flex items-center space-x-2 space-x-reverse">
            {alertsData.summary.hasAlerts ? (
              getSeverityIcon(
                alertsData.summary.mostRecentAlert?.severity || "info",
              )
            ) : (
              <CheckCircle className="w-5 h-5 text-green-600" />
            )}
            <span>التنبيهات النشطة</span>
            {alertsData.summary.totalActive > 0 && (
              <Badge variant="destructive">
                {alertsData.summary.totalActive}
              </Badge>
            )}
          </CardTitle>
          <div className="flex space-x-2 space-x-reverse">
            <Button
              onClick={triggerCheck}
              variant="outline"
              size="sm"
              disabled={loading}
            >
              <RefreshCw
                className={`w-4 h-4 mr-2 ${loading ? "animate-spin" : ""}`}
              />
              فحص
            </Button>
            <Button onClick={fetchAlerts} variant="ghost" size="sm">
              <RefreshCw className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {!alertsData.summary.hasAlerts ? (
          <div className="text-center py-8">
            <CheckCircle className="w-16 h-16 text-green-500 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-green-600 mb-2">
              لا توجد تنبيهات
            </h3>
            <p className="text-gray-600">النظام يعمل بشكل طبيعي</p>
            <p className="text-sm text-gray-500 mt-2">
              آخر فحص: {formatTimestamp(alertsData.summary.lastCheck)}
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {/* ملخص سريع */}
            <div className="grid grid-cols-3 gap-4 p-4 bg-gray-50 rounded-lg">
              <div className="text-center">
                <div className="text-2xl font-bold text-red-600">
                  {alertsData.summary.critical}
                </div>
                <div className="text-sm text-gray-600">حرجة</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-yellow-600">
                  {alertsData.summary.warnings}
                </div>
                <div className="text-sm text-gray-600">تحذيرات</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-600">
                  {alertsData.stats.total}
                </div>
                <div className="text-sm text-gray-600">إجمالي</div>
              </div>
            </div>

            {/* قائمة التنبيهات */}
            <div className="space-y-3">
              {alertsData.alerts.map((alert) => (
                <div
                  key={alert.id}
                  className={`border rounded-lg p-4 ${getSeverityColor(alert.severity)}`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="flex items-center space-x-2 space-x-reverse mb-2">
                        <span className="text-2xl">{alert.icon}</span>
                        <h4 className="font-semibold">{alert.message}</h4>
                        <Badge variant="outline" className="text-xs">
                          {alert.severity === "critical" && "حرج"}
                          {alert.severity === "warning" && "تحذير"}
                          {alert.severity === "info" && "معلومات"}
                        </Badge>
                      </div>

                      <p className="text-sm mb-2">{alert.data.details}</p>

                      <div className="flex items-center space-x-4 space-x-reverse text-xs text-gray-600">
                        <span>
                          القيمة: {formatValue(alert.data.currentValue)}
                        </span>
                        <span>العتبة: {formatValue(alert.data.threshold)}</span>
                        <span>{formatTimestamp(alert.timestamp)}</span>
                      </div>
                    </div>

                    <Button
                      onClick={() => resolveAlert(alert.id)}
                      disabled={resolving.has(alert.id)}
                      variant="outline"
                      size="sm"
                      className="mr-2"
                    >
                      {resolving.has(alert.id) ? (
                        <RefreshCw className="w-4 h-4 animate-spin" />
                      ) : (
                        <X className="w-4 h-4" />
                      )}
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default AlertsPanel;

import React, { useState, useEffect, useRef } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from "chart.js";
import { Line } from "react-chartjs-2";
import { Card, CardContent, CardHeader, CardTitle } from "../ui/card";
import { Button } from "../ui/button";
import { RefreshCw, TrendingUp, Clock, AlertTriangle } from "lucide-react";
import { buildApiUrl } from "../../utils/urlHelper";
import { tokenManager } from "../../utils/tokenManager";

// تسجيل مكونات Chart.js
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
);

interface ChartDataPoint {
  timestamp: string;
  totalResponses: number;
  errorRate: number;
  averageResponseTime: number;
  successRate: number;
  slowRate: number;
  emptyRate: number;
  activeErrors: number;
}

interface ChartData {
  period: string;
  limit: number;
  points: ChartDataPoint[];
  stats: any;
  meta: {
    totalPoints: number;
    oldestPoint: string | null;
    newestPoint: string | null;
    dataRange: string;
  };
}

interface PerformanceChartProps {
  className?: string;
}

const PerformanceChart: React.FC<PerformanceChartProps> = ({
  className = "",
}) => {
  const [chartData, setChartData] = useState<ChartData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedMetric, setSelectedMetric] = useState<string>(
    "averageResponseTime",
  );
  const [period] = useState<string>("hourly");
  const chartRef = useRef<ChartJS<"line">>(null);

  const fetchChartData = async () => {
    try {
      setError(null);
      const token = tokenManager.getAccessToken();
      const response = await fetch(
        buildApiUrl(`monitor/charts?period=${period}&limit=20`),
        {
          headers: {
            Authorization: token ? `Bearer ${token}` : "",
            "Content-Type": "application/json",
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (data.success) {
        setChartData(data.data);
      } else {
        throw new Error(data.error || "Failed to fetch chart data");
      }
    } catch (err) {
      console.error("Error fetching chart data:", err);
      setError(err instanceof Error ? err.message : "Unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchChartData();

    // تحديث تلقائي كل 10 دقائق (reduced from 1 minute)
    const interval = setInterval(fetchChartData, 10 * 60 * 1000);

    return () => clearInterval(interval);
  }, [period]);

  const formatTimestamp = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString("ar-EG", {
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const getChartConfig = () => {
    if (!chartData || chartData.points.length === 0) {
      return null;
    }

    const labels = chartData.points.map((point) =>
      formatTimestamp(point.timestamp),
    );

    const datasets = [];

    // إعداد البيانات حسب المقياس المختار
    switch (selectedMetric) {
      case "averageResponseTime":
        datasets.push({
          label: "متوسط وقت الاستجابة (ms)",
          data: chartData.points.map((point) => point.averageResponseTime),
          borderColor: "rgb(59, 130, 246)",
          backgroundColor: "rgba(59, 130, 246, 0.1)",
          fill: true,
          tension: 0.4,
        });
        break;

      case "rates":
        datasets.push(
          {
            label: "معدل النجاح (%)",
            data: chartData.points.map((point) => point.successRate),
            borderColor: "rgb(34, 197, 94)",
            backgroundColor: "rgba(34, 197, 94, 0.1)",
            fill: false,
            tension: 0.4,
          },
          {
            label: "معدل الأخطاء (%)",
            data: chartData.points.map((point) => point.errorRate),
            borderColor: "rgb(239, 68, 68)",
            backgroundColor: "rgba(239, 68, 68, 0.1)",
            fill: false,
            tension: 0.4,
          },
          {
            label: "معدل الردود البطيئة (%)",
            data: chartData.points.map((point) => point.slowRate),
            borderColor: "rgb(245, 158, 11)",
            backgroundColor: "rgba(245, 158, 11, 0.1)",
            fill: false,
            tension: 0.4,
          },
        );
        break;

      case "totalResponses":
        datasets.push({
          label: "إجمالي الردود",
          data: chartData.points.map((point) => point.totalResponses),
          borderColor: "rgb(168, 85, 247)",
          backgroundColor: "rgba(168, 85, 247, 0.1)",
          fill: true,
          tension: 0.4,
        });
        break;
    }

    return {
      labels,
      datasets,
    };
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: "top" as const,
        rtl: true,
        labels: {
          font: {
            family: "Arial, sans-serif",
          },
        },
      },
      title: {
        display: true,
        text: getMetricTitle(),
        font: {
          size: 16,
          family: "Arial, sans-serif",
        },
      },
      tooltip: {
        mode: "index" as const,
        intersect: false,
        rtl: true,
        titleFont: {
          family: "Arial, sans-serif",
        },
        bodyFont: {
          family: "Arial, sans-serif",
        },
      },
    },
    scales: {
      x: {
        display: true,
        title: {
          display: true,
          text: "الوقت",
          font: {
            family: "Arial, sans-serif",
          },
        },
        ticks: {
          font: {
            family: "Arial, sans-serif",
          },
        },
      },
      y: {
        display: true,
        title: {
          display: true,
          text: getYAxisLabel(),
          font: {
            family: "Arial, sans-serif",
          },
        },
        ticks: {
          font: {
            family: "Arial, sans-serif",
          },
        },
      },
    },
    interaction: {
      mode: "nearest" as const,
      axis: "x" as const,
      intersect: false,
    },
  };

  function getMetricTitle() {
    switch (selectedMetric) {
      case "averageResponseTime":
        return "متوسط وقت الاستجابة عبر الزمن";
      case "rates":
        return "معدلات الأداء عبر الزمن";
      case "totalResponses":
        return "إجمالي الردود عبر الزمن";
      default:
        return "أداء النظام";
    }
  }

  function getYAxisLabel() {
    switch (selectedMetric) {
      case "averageResponseTime":
        return "الوقت (ميلي ثانية)";
      case "rates":
        return "النسبة المئوية (%)";
      case "totalResponses":
        return "عدد الردود";
      default:
        return "القيمة";
    }
  }

  const chartConfig = getChartConfig();

  if (loading) {
    return (
      <Card className={className}>
        <CardContent className="flex items-center justify-center p-6 h-96">
          <div className="flex items-center space-x-2 space-x-reverse">
            <RefreshCw className="w-6 h-6 animate-spin" />
            <span>جاري تحميل الرسوم البيانية...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card className={className}>
        <CardContent className="p-6">
          <div className="text-center">
            <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-red-600 mb-2">
              خطأ في تحميل الرسوم البيانية
            </h3>
            <p className="text-gray-600 mb-4">{error}</p>
            <Button onClick={fetchChartData} variant="outline">
              <RefreshCw className="w-4 h-4 mr-2" />
              إعادة المحاولة
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!chartData || chartData.points.length === 0) {
    return (
      <Card className={className}>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2 space-x-reverse">
            <TrendingUp className="w-5 h-5" />
            <span>الرسوم البيانية</span>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-6">
          <div className="text-center py-8">
            <Clock className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-gray-600 mb-2">
              لا توجد بيانات كافية
            </h3>
            <p className="text-gray-500">
              سيتم عرض الرسوم البيانية عند توفر بيانات كافية
            </p>
            <Button onClick={fetchChartData} variant="outline" className="mt-4">
              <RefreshCw className="w-4 h-4 mr-2" />
              تحديث
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={className}>
      <CardHeader>
        <div className="flex justify-between items-center">
          <CardTitle className="flex items-center space-x-2 space-x-reverse">
            <TrendingUp className="w-5 h-5 text-blue-600" />
            <span>الرسوم البيانية</span>
          </CardTitle>
          <div className="flex space-x-2 space-x-reverse">
            <Button onClick={fetchChartData} variant="ghost" size="sm">
              <RefreshCw className="w-4 h-4" />
            </Button>
          </div>
        </div>

        {/* أزرار التحكم */}
        <div className="flex flex-wrap gap-2 mt-4">
          <div className="flex space-x-2 space-x-reverse">
            <span className="text-sm font-medium text-gray-700">المقياس:</span>
            <button
              onClick={() => setSelectedMetric("averageResponseTime")}
              className={`px-3 py-1 text-xs rounded-full ${
                selectedMetric === "averageResponseTime"
                  ? "bg-blue-100 text-blue-800"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              وقت الاستجابة
            </button>
            <button
              onClick={() => setSelectedMetric("rates")}
              className={`px-3 py-1 text-xs rounded-full ${
                selectedMetric === "rates"
                  ? "bg-blue-100 text-blue-800"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              المعدلات
            </button>
            <button
              onClick={() => setSelectedMetric("totalResponses")}
              className={`px-3 py-1 text-xs rounded-full ${
                selectedMetric === "totalResponses"
                  ? "bg-blue-100 text-blue-800"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              إجمالي الردود
            </button>
          </div>
        </div>

        {/* معلومات البيانات */}
        <div className="text-sm text-gray-600 mt-2">
          {chartData.meta.dataRange} • آخر تحديث:{" "}
          {formatTimestamp(
            chartData.meta.newestPoint || new Date().toISOString(),
          )}
        </div>
      </CardHeader>

      <CardContent>
        <div className="h-96">
          {chartConfig && (
            <Line ref={chartRef} data={chartConfig} options={chartOptions} />
          )}
        </div>
      </CardContent>
    </Card>
  );
};

export default PerformanceChart;

import React, { useState, useEffect, useRef } from "react";
import {
  XMarkIcon,
  ChatBubbleLeftRightIcon,
  StarIcon,
  ExclamationTriangleIcon,
  InformationCircleIcon,
  PrinterIcon,
  ShoppingBagIcon,
} from "@heroicons/react/24/outline";
import { useCurrency } from "../../hooks/useCurrency";
import { useTranslation } from "react-i18next";
import { apiClient } from "../../services/apiClient";
import { Link } from "react-router-dom";

interface EnhancedOrderModalProps {
  order: any;
  isOpen: boolean;
  onClose: () => void;
  onOrderUpdate?: (updatedOrder: any) => void;
}

const EnhancedOrderModal: React.FC<EnhancedOrderModalProps> = ({
  order,
  isOpen,
  onClose,
  onOrderUpdate,
}) => {
  const { formatPrice } = useCurrency();
  const { t } = useTranslation();
  const [isUpdating, setIsUpdating] = useState(false);
  const [isPrinting, setIsPrinting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const modalRef = useRef<HTMLDivElement>(null);

  const normalizeItems = (rawItems: any): any[] => {
    if (!rawItems) return [];
    let items = rawItems;
    if (typeof items === "string") {
      try {
        items = JSON.parse(items);
      } catch (e) {
        return [];
      }
    }
    if (!Array.isArray(items)) return [];

    return items.map((item: any) => {
      const price = parseFloat(item.price ?? item.unitPrice ?? 0);
      const quantity = parseInt(item.quantity ?? 1);
      const safePrice = Number.isFinite(price) ? price : 0;
      const safeQuantity =
        Number.isFinite(quantity) && quantity > 0 ? quantity : 1;
      return {
        ...item,
        productName:
          item.productName ||
          item.name ||
          item.product?.name ||
          "منتج غير محدد",
        name:
          item.name ||
          item.productName ||
          item.product?.name ||
          "منتج غير محدد",
        price: safePrice,
        quantity: safeQuantity,
        total:
          Number.isFinite(parseFloat(item.total))
            ? parseFloat(item.total)
            : safePrice * safeQuantity,
        productColor:
          item.productColor ||
          item.color ||
          item.metadata?.color ||
          item.metadata?.productColor,
        productSize:
          item.productSize ||
          item.size ||
          item.metadata?.size ||
          item.metadata?.productSize,
      };
    });
  };

  const resolvedItems =
    normalizeItems(order?.items) ||
    (Array.isArray(order?.items) ? order.items : []);
  const fallbackItems = normalizeItems(order?.orderItems);
  const displayItems =
    resolvedItems && resolvedItems.length > 0 ? resolvedItems : fallbackItems;
  const isGuestOrder = Boolean(order?.metadata?.isGuestOrder);
  const normalizedPaymentStatus = (
    order?.paymentStatus ||
    (isGuestOrder ? "unavailable" : "pending")
  ).toLowerCase();

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };

    if (isOpen) {
      document.addEventListener("keydown", handleEscape);
      document.body.style.overflow = "hidden";
      modalRef.current?.focus();
    }

    return () => {
      document.removeEventListener("keydown", handleEscape);
      document.body.style.overflow = "unset";
    };
  }, [isOpen, onClose]);

  const handleUpdateStatus = async (newStatus: string) => {
    try {
      setIsUpdating(true);
      setError(null);
      const response = await apiClient.post(
        `/orders-new/simple/${order.orderNumber}/status`,
        {
          status: newStatus,
        },
      );

      if (response.data.success) {
        const updatedOrder = { ...order, status: newStatus.toLowerCase() };
        if (onOrderUpdate) {
          onOrderUpdate(updatedOrder);
        }
      } else {
        setError(response.data.message || t("orders.statusUpdateFailed"));
      }
    } catch (err: any) {
      setError(err.response?.data?.message || t("orders.updateError"));
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdatePaymentStatus = async (newStatus: string) => {
    if (isGuestOrder) {
      return;
    }

    try {
      setIsUpdating(true);
      setError(null);
      const response = await apiClient.post(
        `/orders-new/simple/${order.orderNumber}/payment-status`,
        {
          paymentStatus: newStatus,
        },
      );

      if (response.data.success) {
        const updatedOrder = {
          ...order,
          paymentStatus: newStatus.toLowerCase(),
        };
        if (onOrderUpdate) {
          onOrderUpdate(updatedOrder);
        }
      } else {
        setError(
          response.data.message || t("orders.paymentStatusUpdateFailed"),
        );
      }
    } catch (err: any) {
      setError(err.response?.data?.message || t("orders.paymentUpdateError"));
    } finally {
      setIsUpdating(false);
    }
  };

  const handlePrintInvoice = async () => {
    try {
      setIsPrinting(true);
      setError(null);
      const response = await apiClient.post("/order-invoices/bulk-generate", {
        orderIds: [order.orderNumber],
      });

      if (response.data.success && response.data.data.invoices?.length > 0) {
        const invoice = response.data.data.invoices[0];
        window.open(
          `/orders/invoices/print-multiple?ids=${invoice.id}`,
          "_blank",
        );
      } else {
        setError(
          t("orders.invoiceGenerationFailed") || "Failed to generate invoice",
        );
      }
    } catch (err: any) {
      setError(
        err.response?.data?.message ||
          t("orders.invoiceError") ||
          "Error generating invoice",
      );
    } finally {
      setIsPrinting(false);
    }
  };

  const getCustomerDisplayName = () => {
    if (order.customer) {
      const fullName =
        `${order.customer.firstName} ${order.customer.lastName}`.trim();
      if (
        fullName !== "New Customer" &&
        fullName !== "Customer Not Specified" &&
        fullName !== "Customer"
      ) {
        return fullName;
      }
    }

    if (order.customerName && !order.customerName.match(/^\d+/)) {
      return order.customerName;
    }

    if (order.customerName && order.customerName.match(/^\d+/)) {
      return `${t("orders.facebookCustomer")} (${order.customerName.substring(0, 8)}...)`;
    }

    return t("orders.notSpecifiedCustomer");
  };

  const getConfidenceColor = (confidence?: number) => {
    if (!confidence) return "text-gray-500";

    if (confidence >= 0.8) return "text-green-600";
    if (confidence >= 0.6) return "text-yellow-600";
    return "text-red-600";
  };

  const [governments, setGovernments] = useState<any[]>([]);

  useEffect(() => {
    const fetchGovernments = async () => {
      try {
        const response = await apiClient.get("/turbo/governments");
        if (response.data.success && response.data.data?.governments) {
          setGovernments(response.data.data.governments);
        }
      } catch (error) {
        console.error("Failed to fetch governments in modal:", error);
      }
    };
    if (isOpen) {
      fetchGovernments();
    }
  }, [isOpen]);

  if (!isOpen || !order) return null;

  const getConfidenceIcon = (confidence?: number) => {
    if (!confidence) return <InformationCircleIcon className="h-4 w-4" />;

    if (confidence >= 0.8) return <StarIcon className="h-4 w-4" />;
    return <ExclamationTriangleIcon className="h-4 w-4" />;
  };

  const getLocationDisplayName = (val: any) => {
    if (!val) return null;

    // Check if it's a numeric ID for governorates
    const numId = parseInt(String(val));
    if (!isNaN(numId) && governments.length > 0) {
      const found = governments.find((g) => g.id === numId);
      if (found) return found.name;
    }

    // Clean numeric prefix (e.g., "2339:Cairo")
    return String(val).replace(/^\d+:/, "").trim();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-slate-950/55 backdrop-blur-md dark:bg-slate-950/75 sm:items-center sm:p-4 overscroll-contain"
      onClick={(e) => e.target === e.currentTarget && onClose()}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
    >
      <div
        ref={modalRef}
        tabIndex={-1}
        className="relative flex max-h-[calc(100vh-0.5rem)] w-full flex-col overflow-y-auto rounded-t-[30px] border border-slate-200/70 bg-white/96 shadow-2xl dark:border-slate-700/70 dark:bg-slate-900/96 sm:max-h-[calc(100vh-2rem)] sm:w-11/12 sm:rounded-[28px] md:w-3/5 lg:w-1/2 xl:w-2/5 max-w-3xl"
      >
        <div className="px-4 pb-5 pt-3 sm:px-5">
          <div className="mx-auto mb-4 h-1.5 w-14 rounded-full bg-slate-300 dark:bg-slate-600 sm:hidden" />
          <div className="space-y-6">
          {/* Header */}
          <div className="flex items-center justify-between pb-4 border-b border-gray-200 dark:border-gray-700">
            <div className="flex items-center gap-3">
              <ShoppingBagIcon className="h-6 w-6 text-blue-600 dark:text-blue-400" />
              <h3
                id="modal-title"
                className="text-xl font-semibold text-gray-900 dark:text-gray-100"
              >
                {t("orders.orderDetails")} #{order.orderNumber}
              </h3>
            </div>
            <button
              onClick={onClose}
              className="text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300 transition-colors p-1 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700"
              aria-label={String(t("orders.close"))}
            >
              <XMarkIcon className="h-6 w-6" />
            </button>
          </div>

          {/* Error Message */}
          {error && (
            <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4 flex items-start gap-3">
              <ExclamationTriangleIcon className="h-5 w-5 text-red-600 dark:text-red-400 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-sm text-red-800 dark:text-red-200">
                  {error}
                </p>
              </div>
              <button
                onClick={() => setError(null)}
                className="text-red-400 hover:text-red-600 dark:hover:text-red-300"
              >
                <XMarkIcon className="h-4 w-4" />
              </button>
            </div>
          )}

          {/* Customer Info */}
          <div>
            <h4 className="font-semibold text-gray-900 dark:text-gray-100 mb-3 flex items-center gap-2">
              <span className="text-blue-600 dark:text-blue-400">●</span>
              {t("orders.customerInfo")}
            </h4>
            <div className="bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 p-3 rounded-lg border border-gray-200 dark:border-gray-700">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <div>
                  <span className="text-sm text-gray-500 dark:text-gray-400 block mb-1">
                    {t("orders.name")}
                  </span>
                  <span className="text-gray-900 dark:text-gray-100 font-medium">
