                  <th className="text-center py-2 font-bold w-20">الكمية</th>
                  <th className="text-right py-2 font-bold w-24">السعر</th>
                  <th className="text-right py-2 font-bold w-28">الإجمالي</th>
                </tr>
              </thead>
              <tbody>
                {invoice.order?.orderItems?.map((item: any, idx: number) => (
                  <tr
                    key={idx}
                    className="border-b border-slate-200 dark:border-slate-700 print:border-slate-200"
                  >
                    <td className="text-right py-3">
                      <div className="font-medium text-slate-900 dark:text-slate-100 print:text-black">
                        {item.productName}
                      </div>
                      {(item.productColor || item.productSize) && (
                        <div className="mt-1 text-xs text-slate-500 dark:text-slate-400 print:text-slate-600">
                          {item.productColor && (
                            <span>اللون: {item.productColor}</span>
                          )}
                          {item.productColor && item.productSize && (
                            <span> | </span>
                          )}
                          {item.productSize && (
                            <span>المقاس: {item.productSize}</span>
                          )}
                        </div>
                      )}
                    </td>
                    <td className="text-center py-3">{item.quantity}</td>
                    <td className="text-right py-3">
                      {formatCurrency(item.price, invoice.currency)}
                    </td>
                    <td className="text-right py-3 font-semibold">
                      {formatCurrency(item.total, invoice.currency)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* المجاميع */}
          <div className="flex justify-end mb-6">
            <div className="w-64 space-y-2 text-sm">
              <div className="flex justify-between py-1">
                <span className="text-slate-500 dark:text-slate-400 print:text-slate-600">
                  المجموع الفرعي:
                </span>
                <span className="font-semibold">
                  {formatCurrency(invoice.subtotal, invoice.currency)}
                </span>
              </div>
              {invoice.shipping > 0 && (
                <div className="flex justify-between py-1">
                  <span className="text-slate-500 dark:text-slate-400 print:text-slate-600">
                    الشحن:
                  </span>
                  <span className="font-semibold">
                    {formatCurrency(invoice.shipping, invoice.currency)}
                  </span>
                </div>
              )}
              {invoice.tax > 0 && (
                <div className="flex justify-between py-1">
                  <span className="text-slate-500 dark:text-slate-400 print:text-slate-600">
                    الضريبة:
                  </span>
                  <span className="font-semibold">
                    {formatCurrency(invoice.tax, invoice.currency)}
                  </span>
                </div>
              )}
              {invoice.discount > 0 && (
                <div className="flex justify-between py-1">
                  <span className="text-slate-500 dark:text-slate-400 print:text-slate-600">
                    الخصم:
                  </span>
                  <span className="font-semibold text-red-600">
                    -{formatCurrency(invoice.discount, invoice.currency)}
                  </span>
                </div>
              )}
              <div className="flex justify-between py-3 bg-blue-600 text-white px-4 rounded-lg font-bold text-base">
                <span>الإجمالي:</span>
                <span>
                  {formatCurrency(invoice.totalAmount, invoice.currency)}
                </span>
              </div>
            </div>
          </div>

          {/* حالة الدفع */}
          <div className="mb-4 rounded-[24px] border border-slate-200/80 bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800/70 print:border-slate-200 print:bg-slate-50">
            <div className="flex justify-between items-center text-sm">
              <div>
                <span className="font-semibold">حالة الدفع: </span>
                <span
                  className={`px-3 py-1 rounded-full text-xs font-semibold ${
                    invoice.paymentStatus === "PAID"
                      ? "bg-green-100 text-green-800 dark:bg-green-500/10 dark:text-green-300"
                      : invoice.paymentStatus === "PENDING"
                        ? "bg-yellow-100 text-yellow-800 dark:bg-yellow-500/10 dark:text-yellow-300"
                        : "bg-red-100 text-red-800 dark:bg-red-500/10 dark:text-red-300"
                  }`}
                >
                  {getPaymentStatusText(invoice.paymentStatus)}
                </span>
              </div>
              {invoice.paymentMethod && (
                <div>
                  <span className="font-semibold">طريقة الدفع: </span>
                  <span>{invoice.paymentMethod}</span>
                </div>
              )}
            </div>
          </div>

          {/* ملاحظات */}
          {invoice.notes && (
            <div className="rounded-[22px] border-r-4 border-yellow-400 bg-yellow-50 p-4 text-sm dark:border-yellow-500/70 dark:bg-yellow-500/10">
              <p className="font-semibold mb-1">ملاحظات:</p>
              <p className="text-slate-700 dark:text-slate-200 print:text-slate-700">
                {invoice.notes}
              </p>
            </div>
          )}

          {/* Footer */}
          <div className="mt-6 border-t border-slate-200 pt-4 text-center text-xs text-slate-500 dark:border-slate-700 dark:text-slate-400 print:border-slate-200 print:text-slate-500">
            <p>شكراً لتعاملكم معنا</p>
          </div>
        </div>
      </div>

      <style>{`
        @media print {
          body * {
            visibility: hidden;
          }
          .print\\:max-w-none, .print\\:max-w-none * {
            visibility: visible;
          }
          .print\\:max-w-none {
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
          }
        }
      `}</style>
    </div>
  );
};

export default InvoiceModal;

import React, { useEffect, useState } from 'react';
import {
    CheckCircleIcon,
    XMarkIcon,
    ClipboardDocumentIcon,
    ClockIcon,
    UserIcon,
    PhoneIcon,
    MapPinIcon,
    ShoppingBagIcon,
    TruckIcon,
    QrCodeIcon,
    EnvelopeIcon,
    PrinterIcon,
    ArrowPathIcon,
    HeartIcon
} from '@heroicons/react/24/outline';
import { QRCodeSVG } from 'qrcode.react';
import { toast } from 'react-hot-toast';

interface OrderItem {
    productName: string;
    quantity: number;
    price: number;
    productColor?: string;
    productSize?: string;
    productImage?: string;
}

interface OrderConfirmationProps {
    isOpen: boolean;
    onClose: () => void;
    orderData: {
        id: string;
        orderNumber: string;
        customerName: string;
        customerPhone: string;
        customerAddress?: string;
        governorate?: string;
        items: OrderItem[];
        subtotal: number;
        shippingCost: number;
        discount: number;
        total: number;
        status: string;
        paymentMethod: string;
        createdAt: string;
    } | null;
    onViewDetails?: () => void;
    onPrint?: () => void;
    onNewOrder?: () => void;
}

const statusConfig: Record<string, { label: string; color: string; bgColor: string; icon: any }> = {
    'PENDING': { label: 'جديد - قيد الانتظار', color: 'text-amber-700', bgColor: 'bg-amber-100', icon: ClockIcon },
    'CONFIRMED': { label: 'تم التأكيد', color: 'text-blue-700', bgColor: 'bg-blue-100', icon: CheckCircleIcon },
    'PROCESSING': { label: 'جاري التجهيز', color: 'text-purple-700', bgColor: 'bg-purple-100', icon: ShoppingBagIcon },
    'SHIPPED': { label: 'تم الشحن', color: 'text-indigo-700', bgColor: 'bg-indigo-100', icon: TruckIcon },
    'OUT_FOR_DELIVERY': { label: 'في الطريق', color: 'text-orange-700', bgColor: 'bg-orange-100', icon: TruckIcon },
    'DELIVERED': { label: 'تم التوصيل', color: 'text-green-700', bgColor: 'bg-green-100', icon: CheckCircleIcon },
};

const paymentMethodLabels: Record<string, string> = {
    'CASH': 'الدفع عند الاستلام',
    'wallet': 'محفظة إلكترونية',
    'insta': 'Instapay',
    'CARD': 'بطاقة ائتمان',
};

export const OrderConfirmationModal: React.FC<OrderConfirmationProps> = ({
    isOpen,
    onClose,
    orderData,
    onViewDetails,
    onPrint,
    onNewOrder
}) => {
    const [copied, setCopied] = useState(false);
    const [showConfetti, setShowConfetti] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setShowConfetti(true);
            const timer = setTimeout(() => setShowConfetti(false), 3000);
            return () => clearTimeout(timer);
        }
        return undefined;
    }, [isOpen]);

    if (!isOpen || !orderData) return null;

    const statusInfo = statusConfig[orderData.status] || statusConfig['PENDING'];
    const StatusIcon = statusInfo?.icon || CheckCircleIcon;

    const formatDate = (dateString: string) => {
        const date = new Date(dateString);
        return new Intl.DateTimeFormat('ar-EG', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
        }).format(date);
    };

    const copyOrderNumber = () => {
        navigator.clipboard.writeText(orderData.orderNumber);
        setCopied(true);
        toast.success('تم نسخ رقم الطلب!');
        setTimeout(() => setCopied(false), 2000);
    };

    const trackingUrl = `${window.location.origin}/track-order/${orderData.orderNumber}`;

    return (
        <div className="fixed inset-0 z-50 overflow-y-auto">
            {/* Backdrop */}
            <div className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />

            {/* Modal Container */}
            <div className="relative min-h-screen flex items-center justify-center p-4">
                <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-300">

                    {/* Success Header with Gradient */}
                    <div className="relative bg-gradient-to-r from-green-500 to-emerald-600 p-6 text-white">
                        {/* Confetti Animation */}
                        {showConfetti && (
                            <div className="absolute inset-0 overflow-hidden pointer-events-none">
                                {[...Array(20)].map((_, i) => (
                                    <div
                                        key={i}
                                        className="absolute w-2 h-2 bg-white/30 rounded-full animate-ping"
                                        style={{
                                            left: `${Math.random() * 100}%`,
                                            top: `${Math.random() * 100}%`,
                                            animationDelay: `${Math.random() * 0.5}s`,
                                            animationDuration: `${1 + Math.random()}s`
                                        }}
                                    />
                                ))}
                            </div>
                        )}

                        <div className="relative flex items-start justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center">
                                    <CheckCircleIcon className="w-8 h-8 text-white" />
                                </div>
                                <div>
                                    <h2 className="text-2xl font-bold">تم إنشاء الطلب بنجاح!</h2>
                                    <p className="text-green-100 text-sm mt-1">شكراً لاختيارك متجرنا</p>
                                </div>
                            </div>
                            <button
                                onClick={onClose}
                                className="p-2 hover:bg-white/20 rounded-full transition-colors"
                            >
                                <XMarkIcon className="w-6 h-6 text-white" />
                            </button>
                        </div>

                        {/* Order Number Badge */}
                        <div className="mt-4 flex items-center gap-3">
                            <div className="bg-white/20 backdrop-blur-sm rounded-lg px-4 py-2 flex items-center gap-2">
                                <span className="text-green-100 text-sm">رقم الطلب:</span>
                                <span className="text-white font-bold text-lg" dir="ltr">
                                    #{orderData.orderNumber}
                                </span>
                                <button
                                    onClick={copyOrderNumber}
                                    className="p-1 hover:bg-white/20 rounded transition-colors"
                                    title="نسخ رقم الطلب"
                                >
                                    {copied ? (
                                        <CheckCircleIcon className="w-4 h-4 text-white" />
                                    ) : (
                                        <ClipboardDocumentIcon className="w-4 h-4 text-white" />
                                    )}
                                </button>
                            </div>
                            <div className={`${statusInfo?.bgColor} ${statusInfo?.color} px-3 py-1 rounded-full text-sm font-medium flex items-center gap-1`}>
                                <StatusIcon className="w-4 h-4" />
                                {statusInfo?.label}
                            </div>
                        </div>
                    </div>

                    {/* Content */}
                    <div className="p-6 space-y-6">

                        {/* Customer Info Card */}
                        <div className="bg-gray-50 rounded-xl p-4 space-y-3">
                            <h3 className="font-bold text-gray-800 flex items-center gap-2">
                                <UserIcon className="w-5 h-5 text-blue-600" />
                                بيانات العميل
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                                        <UserIcon className="w-5 h-5 text-blue-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-500">الاسم الكامل</p>
                                        <p className="font-semibold text-gray-800">{orderData.customerName}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center">
                                        <PhoneIcon className="w-5 h-5 text-green-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-500">رقم الهاتف</p>
                                        <p className="font-semibold text-gray-800" dir="ltr">{orderData.customerPhone}</p>
                                    </div>
                                </div>
                                {orderData.customerAddress && (
                                    <div className="flex items-center gap-3 md:col-span-2">
                                        <div className="w-10 h-10 bg-orange-100 rounded-full flex items-center justify-center">
                                            <MapPinIcon className="w-5 h-5 text-orange-600" />
                                        </div>
                                        <div>
                                            <p className="text-xs text-gray-500">عنوان التوصيل</p>
                                            <p className="font-semibold text-gray-800">
                                                {orderData.governorate} - {orderData.customerAddress}
                                            </p>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Order Date & Payment */}
                        <div className="flex flex-wrap gap-4 text-sm">
                            <div className="flex items-center gap-2 text-gray-600">
                                <ClockIcon className="w-4 h-4" />
                                <span>تاريخ الطلب: {formatDate(orderData.createdAt)}</span>
                            </div>
                            <div className="flex items-center gap-2 text-gray-600">
                                <ShoppingBagIcon className="w-4 h-4" />
                                <span>طريقة الدفع: {paymentMethodLabels[orderData.paymentMethod] || orderData.paymentMethod}</span>
                            </div>
                        </div>

                        {/* Order Items */}
                        <div className="border rounded-xl overflow-hidden">
                            <div className="bg-gray-50 px-4 py-3 border-b">
                                <h3 className="font-bold text-gray-800 flex items-center gap-2">
                                    <ShoppingBagIcon className="w-5 h-5 text-blue-600" />
                                    تفاصيل المنتجات ({orderData.items.length})
                                </h3>
                            </div>
                            <div className="divide-y">
                                {orderData.items.map((item, index) => (
                                    <div key={index} className="p-4 flex items-center gap-4">
                                        {item.productImage ? (
                                            <img
                                                src={item.productImage}
                                                alt={item.productName}
                                                className="w-16 h-16 object-cover rounded-lg"
                                            />
                                        ) : (
                                            <div className="w-16 h-16 bg-gray-200 rounded-lg flex items-center justify-center">
                                                <ShoppingBagIcon className="w-6 h-6 text-gray-400" />
                                            </div>
                                        )}
                                        <div className="flex-1">
                                            <h4 className="font-semibold text-gray-800">{item.productName}</h4>
                                            <div className="flex flex-wrap gap-2 mt-1 text-sm text-gray-600">
                                                {item.productColor && (
                                                    <span className="bg-pink-100 text-pink-700 px-2 py-0.5 rounded-full text-xs">
                                                        اللون: {item.productColor}
                                                    </span>
                                                )}
                                                {item.productSize && (
                                                    <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full text-xs">
                                                        المقاس: {item.productSize}
                                                    </span>
                                                )}
                                                <span className="bg-gray-100 text-gray-700 px-2 py-0.5 rounded-full text-xs">
                                                    الكمية: {item.quantity}
                                                </span>
                                            </div>
                                        </div>
                                        <div className="text-left">
                                            <p className="font-bold text-gray-800">
                                                {(item.price * item.quantity).toLocaleString()} ج.م
                                            </p>
                                            <p className="text-xs text-gray-500">
                                                {item.price.toLocaleString()} × {item.quantity}
                                            </p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Price Summary */}
                        <div className="bg-gray-50 rounded-xl p-4 space-y-2">
                            {orderData.shippingCost > 0 && (
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-600">تكلفة الشحن:</span>
                                    <span className="font-medium">+{orderData.shippingCost.toLocaleString()} ج.م</span>
                                </div>
                            )}
                            {orderData.discount > 0 && (
                                <div className="flex justify-between text-sm text-green-600">
                                    <span>الخصم:</span>
                                    <span className="font-medium">-{orderData.discount.toLocaleString()} ج.م</span>
                                </div>
