import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  TextField,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  MenuItem,
  Autocomplete,
  Divider,
  CircularProgress,
} from "@mui/material";
import Grid from "@mui/material/GridLegacy";
import {
  Delete as DeleteIcon,
  Add as AddIcon,
  ArrowBack as BackIcon,
  Save as SaveIcon,
  Print as PrintIcon,
} from "@mui/icons-material";
import { useNavigate, useParams } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import { useTheme } from "../../hooks/useTheme";
import toast from "react-hot-toast";
import "../../styles/dashboard-enhanced.css";

interface Supplier {
  id: string;
  name: string;
}

interface Product {
  id: string;
  name: string;
  sku: string;
  price: number;
  cost: number;
}

interface OrderItem {
  id?: string;
  productId: string | null;
  productName: string;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  discountRate: number;
  totalPrice: number;
  notes?: string;
}

const PurchaseOrderForm: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const isEdit = Boolean(id);
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const glassClass = isDark ? "glass-effect-dark" : "glass-effect";

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [productSearchLoading, setProductSearchLoading] = useState(false);

  const [formData, setFormData] = useState({
    supplierId: "",
    orderDate: new Date().toISOString().split("T")[0] ?? "",
    expectedDelivery: "",
    paymentTerms: "",
    notes: "",
    shippingCost: 0,
    discountAmount: 0,
  });

  const [items, setItems] = useState<OrderItem[]>([
    {
      productId: null,
      productName: "",
      description: "",
      quantity: 1,
      unitPrice: 0,
      taxRate: 0,
      discountRate: 0,
      totalPrice: 0,
    },
  ]);

  useEffect(() => {
    fetchInitialData();
    if (isEdit) {
      fetchOrder();
    }
  }, [id]);

  const fetchInitialData = async () => {
    try {
      setLoading(true);
      const [suppliersRes, productsRes] = await Promise.all([
        apiClient.get("/procurement/suppliers", { params: { limit: 100 } }),
        apiClient.get("/products", { params: { limit: 100 } }), // Initial product list
      ]);
      setSuppliers(suppliersRes.data.suppliers || []);
      setProducts(productsRes.data.data || []);
    } catch (error) {
      console.error("Error fetching initial data:", error);
      toast.error("فشل في تحميل البيانات الأولية");
    } finally {
      setLoading(false);
    }
  };

  const fetchOrder = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(
        `/procurement/purchase-orders/${id}`,
      );
      const order = response.data;

      setFormData({
        supplierId: order.supplierId,
        orderDate: new Date(order.orderDate).toISOString().split("T")[0] ?? "",
        expectedDelivery: order.expectedDelivery
          ? (new Date(order.expectedDelivery).toISOString().split("T")[0] ?? "")
          : "",
        paymentTerms: order.paymentTerms || "",
        notes: order.notes || "",
        shippingCost: Number(order.shippingCost),
        discountAmount: Number(order.discountAmount),
      });

      setItems(
        order.items.map((item: any) => ({
          id: item.id,
          productId: item.productId ?? null,
          productName: item.productName,
          description: item.description || "",
          quantity: Number(item.quantity),
          unitPrice: Number(item.unitPrice),
          taxRate: Number(item.taxRate),
          discountRate: Number(item.discountRate),
          totalPrice: Number(item.totalPrice),
        })),
      );
    } catch (error) {
      console.error("Error fetching order:", error);
      toast.error("فشل في تحميل بيانات أمر الشراء");
    } finally {
      setLoading(false);
    }
  };

  const handleProductSearch = async (query: string) => {
    // We allow searching even with empty string to restore initial state if needed
    // but server-side search is triggered for 1+ characters
    try {
      setProductSearchLoading(true);
      const response = await apiClient.get("/products", {
        params: {
          search: query || undefined,
          limit: query ? 20 : 100,
        },
      });
      setProducts(response.data.data || []);
    } catch (error) {
      console.error("Error searching products:", error);
    } finally {
      setProductSearchLoading(false);
    }
  };

  const updateItemDetails = (index: number, updates: Partial<OrderItem>) => {
    setItems((prevItems) => {
      const newItems = [...prevItems];
      const currentItem = newItems[index];
      if (!currentItem) {
        return prevItems;
      }
      const item: OrderItem = { ...currentItem, ...updates };

      // Recalculate item total based on current or new values
      const quantity =
        parseFloat(
          "quantity" in updates ? (updates.quantity as any) : item.quantity,
        ) || 0;
      const unitPrice =
        parseFloat(
          "unitPrice" in updates ? (updates.unitPrice as any) : item.unitPrice,
        ) || 0;
      const taxRate =
        parseFloat(
          "taxRate" in updates ? (updates.taxRate as any) : item.taxRate,
        ) || 0;
      const discountRate =
        parseFloat(
          "discountRate" in updates
            ? (updates.discountRate as any)
            : item.discountRate,
        ) || 0;

      const subtotal = quantity * unitPrice;
      const discount = subtotal * (discountRate / 100);
      const tax = (subtotal - discount) * (taxRate / 100);

      item.totalPrice = subtotal - discount + tax;
      newItems[index] = item;
      return newItems;
    });
  };

  // Keep updateItem for single field calls to avoid massive refactor downstream
  const updateItem = (index: number, field: keyof OrderItem, value: any) => {
    updateItemDetails(index, { [field]: value });
  };

  const addItem = () => {
    setItems([
      ...items,
      {
        productId: null,
        productName: "",
        description: "",
        quantity: 1,
        unitPrice: 0,
        taxRate: 0,
        discountRate: 0,
        totalPrice: 0,
      },
    ]);
  };

  const removeItem = (index: number) => {
    if (items.length === 1) {
      setItems([
        {
          productId: null,
          productName: "",
          description: "",
          quantity: 1,
          unitPrice: 0,
          taxRate: 0,
          discountRate: 0,
          totalPrice: 0,
        },
      ]);
    } else {
      setItems(items.filter((_, i) => i !== index));
    }
  };

  const calculateTotals = () => {
    const subtotal = items.reduce(
      (sum, item) => sum + item.quantity * item.unitPrice,
      0,
    );
    const totalTax = items.reduce((sum, item) => {
      const itemSubtotal = item.quantity * item.unitPrice;
      const itemDiscount = itemSubtotal * (item.discountRate / 100);
      return sum + (itemSubtotal - itemDiscount) * (item.taxRate / 100);
    }, 0);
    const itemDiscounts = items.reduce(
      (sum, item) =>
        sum + item.quantity * item.unitPrice * (item.discountRate / 100),
      0,
    );

    const grandTotal =
      subtotal -
      itemDiscounts +
      totalTax +
      Number(formData.shippingCost) -
      Number(formData.discountAmount);

    return {
      subtotal,
      totalTax,
      itemDiscounts,
      grandTotal,
    };
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.supplierId) {
      toast.error("يرجى اختيار المورد");
      return;
    }

    const invalidItems = items.filter(
      (item) => !item.productName || item.quantity <= 0,
    );
    if (invalidItems.length > 0) {
      toast.error("يرجى التأكد من اختيار المنتج وإدخال كمية صحيحة لكل البنود");
      return;
    }

    try {
      setSaving(true);
      const payload = {
        ...formData,
        items,
      };

      if (isEdit) {
        await apiClient.put(`/procurement/purchase-orders/${id}`, payload);
        toast.success("تم تحديث أمر الشراء بنجاح");
      } else {
        await apiClient.post("/procurement/purchase-orders", payload);
        toast.success("تم إنشاء أمر الشراء بنجاح");
      }
      navigate("/procurement/purchase-orders");
    } catch (error: any) {
      console.error("Error saving order:", error);
      toast.error(
        error.response?.data?.message || "حدث خطأ أثناء حفظ أمر الشراء",
      );
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: "flex", justifyContent: "center", p: 5 }}>
        <CircularProgress />
      </Box>
    );
  }

  const handlePrint = () => {
    window.print();
  };

  const totals = calculateTotals();

  return (
    <Box sx={{ p: 3 }} className="no-print">
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          mb: 3,
          gap: 2,
          justifyContent: "space-between",
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <IconButton
            onClick={() => navigate("/procurement/purchase-orders")}
            className="micro-bounce"
          >
            <BackIcon />
          </IconButton>
          <Typography
            variant="h4"
            className="gradient-text"
            sx={{ fontWeight: "bold" }}
          >
            {isEdit ? "تعديل أمر شراء" : "إنشاء أمر شراء جديد"}
          </Typography>
        </Box>
        {isEdit && (
          <Button
            variant="outlined"
            startIcon={<PrintIcon />}
            onClick={handlePrint}
            className="micro-bounce"
          >
            طباعة
          </Button>
        )}
      </Box>

      <form onSubmit={handleSubmit}>
        <Grid container spacing={3}>
          {/* Header Info */}
          <Grid item xs={12}>
            <Card
              className={`${glassClass} card-hover-lift`}
              sx={{ borderRadius: 4 }}
            >
              <CardContent>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={4}>
                    <TextField
                      select
                      fullWidth
                      label="المورد *"
                      value={formData.supplierId}
                      onChange={(e) =>
                        setFormData({ ...formData, supplierId: e.target.value })
                      }
                      required
                      variant="standard"
                    >
                      {suppliers.map((s) => (
                        <MenuItem key={s.id} value={s.id}>
                          {s.name}
                        </MenuItem>
                      ))}
                    </TextField>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <TextField
                      fullWidth
                      label="تاريخ الأمر"
                      type="date"
                      InputLabelProps={{ shrink: true }}
                      value={formData.orderDate}
                      onChange={(e) =>
                        setFormData({ ...formData, orderDate: e.target.value })
                      }
                      variant="standard"
                    />
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <TextField
                      fullWidth
                      label="التسليم المتوقع"
                      type="date"
                      InputLabelProps={{ shrink: true }}
                      value={formData.expectedDelivery}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          expectedDelivery: e.target.value,
                        })
                      }
                      variant="standard"
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>

          {/* Line Items */}
          <Grid item xs={12}>
            <Card
              className={`${glassClass} card-hover-lift`}
              sx={{ borderRadius: 4 }}
            >
              <CardContent>
                <Typography
                  variant="h6"
                  sx={{ mb: 2 }}
                  className="gradient-text"
                >
                  الأصناف
                </Typography>
                <TableContainer
                  component={Paper}
                  elevation={0}
                  sx={{ background: "transparent" }}
                >
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell sx={{ minWidth: 250, fontWeight: "bold" }}>
                          الصنف
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{ width: 100, fontWeight: "bold" }}
                        >
                          الكمية
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{ width: 120, fontWeight: "bold" }}
                        >
                          سعر الوحدة
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{ width: 100, fontWeight: "bold" }}
                        >
                          الضريبة %
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{ width: 100, fontWeight: "bold" }}
                        >
                          الخصم %
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{ width: 120, fontWeight: "bold" }}
                        >
                          الإجمالي
                        </TableCell>
                        <TableCell
                          align="center"
                          sx={{ width: 50 }}
                        ></TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {items.map((item, index) => (
                        <TableRow key={index} className="micro-rotate-active">
                          <TableCell>
                            <Autocomplete
                              freeSolo
                              openOnFocus
                              options={products}
                              getOptionLabel={(option) =>
                                typeof option === "string"
                                  ? option
                                  : `${option.name} (${option.sku || "N/A"})`
                              }
                              onInputChange={(_, value, reason) => {
                                // Only trigger backend search on actual typing
                                // reason 'reset' or 'clear' shouldn't trigger expensive search
                                if (reason === "input") {
                                  handleProductSearch(value);
                                }
                              }}
                              loading={productSearchLoading}
                              onChange={(_, value) => {
                                if (
                                  typeof value === "object" &&
                                  value !== null
                                ) {
                                  updateItemDetails(index, {
                                    productId: value.id,
                                    productName: value.name,
                                    unitPrice: value.cost || 0,
                                  });
                                } else if (typeof value === "string") {
                                  updateItemDetails(index, {
                                    productName: value,
                                  });
                                } else if (value === null) {
                                  updateItemDetails(index, {
                                    productId: null,
                                    productName: "",
                                  });
                                }
                              }}
                              renderInput={(params) => (
                                <TextField
                                  {...params}
                                  size="small"
                                  placeholder="اختر صنفاً أو ابحث باسمه"
                                  variant="standard"
                                  InputProps={{
                                    ...params.InputProps,
                                    endAdornment: (
                                      <React.Fragment>
                                        {productSearchLoading ? (
                                          <CircularProgress
                                            color="inherit"
                                            size={20}
                                          />
                                        ) : null}
                                        {params.InputProps.endAdornment}
                                      </React.Fragment>
                                    ),
                                  }}
                                />
                              )}
                            />
                          </TableCell>
                          <TableCell>
                            <TextField
                              type="number"
                              size="small"
                              variant="standard"
                              value={item.quantity}
                              onChange={(e) =>
                                updateItem(index, "quantity", e.target.value)
                              }
                            />
                          </TableCell>
                          <TableCell>
                            <TextField
                              type="number"
                              size="small"
                              variant="standard"
                              value={item.unitPrice}
                              onChange={(e) =>
                                updateItem(index, "unitPrice", e.target.value)
                              }
                            />
                          </TableCell>
                          <TableCell>
                            <TextField
                              type="number"
                              size="small"
                              variant="standard"
                              value={item.taxRate}
                              onChange={(e) =>
                                updateItem(index, "taxRate", e.target.value)
                              }
                            />
                          </TableCell>
                          <TableCell>
                            <TextField
                              type="number"
                              size="small"
                              variant="standard"
                              value={item.discountRate}
                              onChange={(e) =>
                                updateItem(
                                  index,
                                  "discountRate",
                                  e.target.value,
                                )
                              }
                            />
                          </TableCell>
                          <TableCell align="right" sx={{ fontWeight: "bold" }}>
                            {item.totalPrice.toFixed(2)}
                          </TableCell>
                          <TableCell align="center">
                            <IconButton
                              size="small"
                              color="error"
                              onClick={() => removeItem(index)}
                              className="micro-bounce"
                            >
                              <DeleteIcon fontSize="small" />
                            </IconButton>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
                <Button
                  startIcon={<AddIcon />}
                  onClick={addItem}
                  sx={{ mt: 2 }}
                  className="micro-bounce"
                >
                  إضافة صنف جديد
                </Button>
              </CardContent>
            </Card>
          </Grid>

          {/* Footer Info & Totals */}
          <Grid item xs={12} md={8}>
            <Card
              className={`${glassClass}`}
              sx={{ borderRadius: 4, height: "100%" }}
            >
              <CardContent>
                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="شروط الدفع"
                      multiline
                      rows={2}
                      variant="outlined"
                      value={formData.paymentTerms}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          paymentTerms: e.target.value,
                        })
                      }
                      sx={{ mt: 1 }}
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="ملاحظات إضافية"
                      multiline
                      rows={3}
                      variant="outlined"
                      value={formData.notes}
                      onChange={(e) =>
                        setFormData({ ...formData, notes: e.target.value })
                      }
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={4}>
            <Card
              className={`${glassClass} pulse-glow`}
              sx={{ borderRadius: 4 }}
            >
              <CardContent>
                <Typography variant="h6" gutterBottom className="gradient-text">
                  ملخص المبالغ
                </Typography>
                <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
                  <Box
                    sx={{ display: "flex", justifyContent: "space-between" }}
                  >
                    <Typography color="textSecondary">
                      المجموع قبل الخصم:
                    </Typography>
                    <Typography fontWeight="bold">
                      {totals.subtotal.toFixed(2)} EGP
                    </Typography>
                  </Box>
                  <Box
                    sx={{ display: "flex", justifyContent: "space-between" }}
                  >
                    <Typography color="textSecondary">
                      إجمالي خصم البنود:
                    </Typography>
                    <Typography color="error.main">
                      -{totals.itemDiscounts.toFixed(2)} EGP
                    </Typography>
                  </Box>
                  <Box
                    sx={{ display: "flex", justifyContent: "space-between" }}
                  >
                    <Typography color="textSecondary">
                      إجمالي الضرائب:
                    </Typography>
                    <Typography color="success.main">
                      +{totals.totalTax.toFixed(2)} EGP
                    </Typography>
                  </Box>
                  <Divider sx={{ my: 1 }} />
                  <Grid container spacing={1} alignItems="center">
                    <Grid item xs={6}>
                      <Typography color="textSecondary">
                        مصاريف الشحن:
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <TextField
                        type="number"
                        size="small"
                        value={formData.shippingCost}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            shippingCost: Number(e.target.value),
                          })
                        }
                        fullWidth
                        variant="standard"
                      />
                    </Grid>
                  </Grid>
                  <Grid container spacing={1} alignItems="center">
                    <Grid item xs={6}>
                      <Typography color="textSecondary">
                        خصم إضافي عام:
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <TextField
                        type="number"
                        size="small"
                        value={formData.discountAmount}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            discountAmount: Number(e.target.value),
                          })
                        }
                        fullWidth
                        variant="standard"
                      />
                    </Grid>
                  </Grid>
                  <Divider sx={{ my: 1 }} />
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      mt: 1,
                    }}
                  >
                    <Typography variant="h6" sx={{ fontWeight: "bold" }}>
                      الإجمالي النهائي:
                    </Typography>
                    <Typography
                      variant="h5"
                      color="primary"
                      sx={{ fontWeight: "900" }}
                    >
                      {totals.grandTotal.toFixed(2)} EGP
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12}>
            <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 2 }}>
              <Button
                variant="outlined"
                onClick={() => navigate("/procurement/purchase-orders")}
                className="micro-bounce"
                sx={{ borderRadius: 2 }}
              >
                إلغاء
              </Button>
              <Button
                type="submit"
                variant="contained"
                disabled={saving}
                startIcon={
                  saving ? <CircularProgress size={20} /> : <SaveIcon />
                }
                className="micro-bounce"
                sx={{
                  borderRadius: 2,
                  px: 4,
                  background:
                    "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                  boxShadow: "0 4px 15px rgba(118, 75, 162, 0.4)",
                }}
              >
                {isEdit ? "تحديث البيانات" : "تأكيد وحفظ الأمر"}
              </Button>
            </Box>
          </Grid>
        </Grid>
      </form>
    </Box>
  );
};

export default PurchaseOrderForm;

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Typography,
  TextField,
  InputAdornment,
  Pagination,
  MenuItem,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Visibility as ViewIcon,
  CheckCircle as ApproveIcon,
  Cancel as CancelIcon,
  Search as SearchIcon,
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";

interface PurchaseOrder {
  id: string;
  orderNumber: string;
  orderDate: string;
  expectedDelivery?: string;
  status: string;
  totalAmount: number;
  supplier: {
    id: string;
    name: string;
    phone?: string;
  };
  _count: {
    items: number;
  };
}

const statusColors: Record<
  string,
  "default" | "primary" | "secondary" | "error" | "warning" | "info" | "success"
> = {
  DRAFT: "default",
  PENDING: "warning",
  APPROVED: "info",
  SENT: "primary",
  PARTIALLY_RECEIVED: "secondary",
  RECEIVED: "success",
  CANCELLED: "error",
  CLOSED: "default",
};

const statusLabels: Record<string, string> = {
  DRAFT: "مسودة",
  PENDING: "في انتظار الموافقة",
  APPROVED: "تمت الموافقة",
  SENT: "تم الإرسال",
  PARTIALLY_RECEIVED: "استلام جزئي",
  RECEIVED: "تم الاستلام",
  CANCELLED: "ملغي",
  CLOSED: "مغلق",
};

const PurchaseOrders: React.FC = () => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  useEffect(() => {
    fetchOrders();
  }, [page, searchTerm, statusFilter]);

  const fetchOrders = async () => {
    try {
      const response = await apiClient.get("/procurement/purchase-orders", {
        params: { page, limit: 20, search: searchTerm, status: statusFilter },
      });
      setOrders(response.data.orders);
      setTotalPages(response.data.pagination.totalPages);
    } catch (error) {
      console.error("Error fetching purchase orders:", error);
    }
  };

  const handleApprove = async (id: string) => {
    if (window.confirm("هل تريد الموافقة على هذا الأمر؟")) {
      try {
        await apiClient.post(`/procurement/purchase-orders/${id}/approve`);
        fetchOrders();
      } catch (error) {
        console.error("Error approving order:", error);
      }
    }
  };

  const handleCancel = async (id: string) => {
    if (window.confirm("هل تريد إلغاء هذا الأمر؟")) {
      try {
        await apiClient.post(`/procurement/purchase-orders/${id}/cancel`);
        fetchOrders();
      } catch (error) {
        console.error("Error cancelling order:", error);
      }
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: "flex", justifyContent: "space-between", mb: 3 }}>
        <Typography variant="h4">أوامر الشراء</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => navigate("/procurement/purchase-orders/new")}
        >
          إنشاء أمر شراء جديد
        </Button>
      </Box>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Box sx={{ display: "flex", gap: 2 }}>
            <TextField
              fullWidth
              placeholder="البحث عن أمر شراء..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
            />
            <TextField
              select
              label="الحالة"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              sx={{ minWidth: 200 }}
            >
              <MenuItem value="">الكل</MenuItem>
              {Object.entries(statusLabels).map(([key, label]) => (
                <MenuItem key={key} value={key}>
                  {label}
                </MenuItem>
              ))}
            </TextField>
          </Box>
        </CardContent>
      </Card>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>رقم الأمر</TableCell>
              <TableCell>المورد</TableCell>
              <TableCell>تاريخ الأمر</TableCell>
              <TableCell>التسليم المتوقع</TableCell>
              <TableCell>عدد الأصناف</TableCell>
              <TableCell>المبلغ الإجمالي</TableCell>
              <TableCell>الحالة</TableCell>
              <TableCell>الإجراءات</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {orders.map((order) => (
              <TableRow key={order.id}>
                <TableCell>{order.orderNumber}</TableCell>
                <TableCell>{order.supplier.name}</TableCell>
                <TableCell>
                  {new Date(order.orderDate).toLocaleDateString("ar-EG")}
                </TableCell>
                <TableCell>
                  {order.expectedDelivery
                    ? new Date(order.expectedDelivery).toLocaleDateString(
                        "ar-EG",
                      )
                    : "-"}
                </TableCell>
                <TableCell>{order._count.items}</TableCell>
                <TableCell>
                  {Number(order.totalAmount).toFixed(2)} EGP
                </TableCell>
                <TableCell>
                  <Chip
                    label={statusLabels[order.status]}
                    color={statusColors[order.status]}
                    size="small"
                  />
                </TableCell>
                <TableCell>
                  <IconButton
                    size="small"
                    onClick={() =>
                      navigate(`/procurement/purchase-orders/${order.id}`)
                    }
                    title="عرض التفاصيل"
                  >
                    <ViewIcon />
                  </IconButton>
                  {(order.status === "DRAFT" || order.status === "PENDING") && (
                    <>
                      <IconButton
                        size="small"
                        onClick={() =>
                          navigate(
                            `/procurement/purchase-orders/${order.id}/edit`,
                          )
                        }
                        title="تعديل"
                      >
                        <EditIcon />
                      </IconButton>
                      <IconButton
                        size="small"
                        onClick={() => handleApprove(order.id)}
                        title="الموافقة"
                        color="success"
                      >
                        <ApproveIcon />
                      </IconButton>
                    </>
                  )}
                  {order.status !== "RECEIVED" &&
                    order.status !== "CLOSED" &&
                    order.status !== "CANCELLED" && (
                      <IconButton
                        size="small"
                        onClick={() => handleCancel(order.id)}
                        title="إلغاء"
                        color="error"
                      >
                        <CancelIcon />
                      </IconButton>
                    )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Box sx={{ display: "flex", justifyContent: "center", mt: 3 }}>
        <Pagination
          count={totalPages}
          page={page}
          onChange={(_, value) => setPage(value)}
          color="primary"
        />
      </Box>
    </Box>
  );
};

export default PurchaseOrders;

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Typography,
  TextField,
  InputAdornment,
  Pagination,
  MenuItem,
} from "@mui/material";
import {
  Add as AddIcon,
  Visibility as ViewIcon,
  Search as SearchIcon,
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";

interface SupplierPayment {
  id: string;
  paymentNumber: string;
  paymentDate: string;
  amount: number;
  paymentMethod: string;
  supplier: {
    id: string;
    name: string;
  };
  purchaseInvoice?: {
    id: string;
    invoiceNumber: string;
  };
}

const paymentMethodLabels: Record<string, string> = {
  CASH: "نقدي",
  BANK_TRANSFER: "تحويل بنكي",
  CHECK: "شيك",
  CREDIT_CARD: "بطاقة ائتمان",
  OTHER: "أخرى",
};

const SupplierPayments: React.FC = () => {
  const navigate = useNavigate();
  const [payments, setPayments] = useState<SupplierPayment[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [methodFilter, setMethodFilter] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  useEffect(() => {
    fetchPayments();
  }, [page, searchTerm, methodFilter]);

  const fetchPayments = async () => {
    try {
      const response = await apiClient.get("/procurement/supplier-payments", {
        params: {
          page,
          limit: 20,
          search: searchTerm,
          paymentMethod: methodFilter,
        },
      });
      setPayments(response.data.payments);
      setTotalPages(response.data.pagination.totalPages);
    } catch (error) {
      console.error("Error fetching payments:", error);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: "flex", justifyContent: "space-between", mb: 3 }}>
        <Typography variant="h4">إدارة المدفوعات</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => navigate("/procurement/supplier-payments/new")}
        >
          تسجيل دفعة جديدة
        </Button>
      </Box>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Box sx={{ display: "flex", gap: 2 }}>
            <TextField
              fullWidth
              placeholder="البحث عن دفعة..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
            />
            <TextField
              select
              label="طريقة الدفع"
              value={methodFilter}
              onChange={(e) => setMethodFilter(e.target.value)}
              sx={{ minWidth: 200 }}
            >
              <MenuItem value="">الكل</MenuItem>
              {Object.entries(paymentMethodLabels).map(([key, label]) => (
                <MenuItem key={key} value={key}>
                  {label}
                </MenuItem>
              ))}
            </TextField>
          </Box>
        </CardContent>
      </Card>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>رقم الدفعة</TableCell>
              <TableCell>المورد</TableCell>
              <TableCell>رقم الفاتورة</TableCell>
              <TableCell>تاريخ الدفع</TableCell>
              <TableCell>المبلغ</TableCell>
              <TableCell>طريقة الدفع</TableCell>
              <TableCell>الإجراءات</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {payments.map((payment) => (
              <TableRow key={payment.id}>
                <TableCell>{payment.paymentNumber}</TableCell>
                <TableCell>{payment.supplier.name}</TableCell>
                <TableCell>
                  {payment.purchaseInvoice?.invoiceNumber || "دفعة مقدمة"}
                </TableCell>
                <TableCell>
                  {new Date(payment.paymentDate).toLocaleDateString("ar-EG")}
                </TableCell>
                <TableCell>{Number(payment.amount).toFixed(2)} EGP</TableCell>
                <TableCell>
                  <Chip
                    label={paymentMethodLabels[payment.paymentMethod]}
                    size="small"
                  />
                </TableCell>
                <TableCell>
                  <IconButton
                    size="small"
                    onClick={() =>
                      navigate(`/procurement/supplier-payments/${payment.id}`)
                    }
                    title="عرض التفاصيل"
                  >
                    <ViewIcon />
                  </IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Box sx={{ display: "flex", justifyContent: "center", mt: 3 }}>
        <Pagination
          count={totalPages}
          page={page}
          onChange={(_, value) => setPage(value)}
          color="primary"
        />
      </Box>
    </Box>
  );
};

export default SupplierPayments;

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Typography,
  MenuItem,
  InputAdornment,
  Pagination,
  Rating,
} from "@mui/material";
import Grid from "@mui/material/GridLegacy";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Search as SearchIcon,
  Visibility as ViewIcon,
} from "@mui/icons-material";
import { useTranslation } from "react-i18next";
import { apiClient } from "../../services/apiClient";

interface Supplier {
  id: string;
  name: string;
  contactPerson?: string;
  email?: string;
  phone?: string;
  mobile?: string;
  address?: string;
  city?: string;
  country?: string;
  taxNumber?: string;
  commercialRegister?: string;
  paymentTerms?: string;
  creditLimit?: number;
  currentBalance: number;
  rating?: number;
  notes?: string;
  isActive: boolean;
  createdAt: string;
  _count?: {
    purchaseOrders: number;
    purchaseInvoices: number;
  };
}

const Suppliers: React.FC = () => {
  const { t, i18n } = useTranslation();
  const tr = (key: string) => String(t(key));
  const isRtl = i18n.language === "ar";
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [openDialog, setOpenDialog] = useState(false);
  const [openViewDialog, setOpenViewDialog] = useState(false);
  const [selectedSupplier, setSelectedSupplier] = useState<Supplier | null>(
    null,
  );
  const [searchTerm, setSearchTerm] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [formData, setFormData] = useState({
    name: "",
    contactPerson: "",
    email: "",
    phone: "",
    mobile: "",
    address: "",
    city: "",
    country: "Egypt",
    taxNumber: "",
    commercialRegister: "",
    paymentTerms: "",
    creditLimit: "",
    rating: 0,
    notes: "",
    isActive: true,
  });

  useEffect(() => {
    fetchSuppliers();
  }, [page, searchTerm]);

  const fetchSuppliers = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/procurement/suppliers", {
        params: { page, limit: 20, search: searchTerm },
      });
      setSuppliers(response.data.suppliers);
      setTotalPages(response.data.pagination.totalPages);
    } catch (error) {
      console.error("Error fetching suppliers:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (supplier?: Supplier) => {
    if (supplier) {
      setSelectedSupplier(supplier);
      setFormData({
        name: supplier.name,
        contactPerson: supplier.contactPerson || "",
        email: supplier.email || "",
        phone: supplier.phone || "",
        mobile: supplier.mobile || "",
        address: supplier.address || "",
        city: supplier.city || "",
        country: supplier.country || "Egypt",
        taxNumber: supplier.taxNumber || "",
        commercialRegister: supplier.commercialRegister || "",
        paymentTerms: supplier.paymentTerms || "",
        creditLimit: supplier.creditLimit?.toString() || "",
        rating: supplier.rating || 0,
        notes: supplier.notes || "",
        isActive: supplier.isActive,
      });
    } else {
      setSelectedSupplier(null);
      setFormData({
        name: "",
        contactPerson: "",
        email: "",
        phone: "",
        mobile: "",
        address: "",
        city: "",
        country: "Egypt",
        taxNumber: "",
        commercialRegister: "",
        paymentTerms: "",
        creditLimit: "",
        rating: 0,
        notes: "",
        isActive: true,
      });
    }
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedSupplier(null);
  };

  const handleSubmit = async () => {
    try {
      if (selectedSupplier) {
        await apiClient.put(
          `/procurement/suppliers/${selectedSupplier.id}`,
          formData,
        );
      } else {
        await apiClient.post("/procurement/suppliers", formData);
      }
      fetchSuppliers();
      handleCloseDialog();
    } catch (error) {
      console.error("Error saving supplier:", error);
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm(tr("procurement.suppliers.deleteConfirm"))) {
      try {
        await apiClient.delete(`/procurement/suppliers/${id}`);
        fetchSuppliers();
      } catch (error) {
        console.error("Error deleting supplier:", error);
      }
    }
  };

  const handleViewDetails = async (supplier: Supplier) => {
    try {
      const response = await apiClient.get(
        `/procurement/suppliers/${supplier.id}`,
      );
      setSelectedSupplier(response.data);
      setOpenViewDialog(true);
    } catch (error) {
      console.error("Error fetching supplier details:", error);
    }
  };

  return (
    <Box sx={{ p: 3 }} dir={isRtl ? "rtl" : "ltr"}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          mb: 3,
          alignItems: "center",
        }}
      >
        <Typography variant="h4">{t("procurement.suppliers.title")}</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => handleOpenDialog()}
        >
          {t("procurement.suppliers.addNew")}
        </Button>
      </Box>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <TextField
            fullWidth
            placeholder={tr("procurement.suppliers.searchPlaceholder")}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
            }}
          />
        </CardContent>
      </Card>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnName")}
              </TableCell>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnContact")}
              </TableCell>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnPhone")}
              </TableCell>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnEmail")}
              </TableCell>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnBalance")}
              </TableCell>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnRating")}
              </TableCell>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnStatus")}
              </TableCell>
              <TableCell align={isRtl ? "right" : "left"}>
                {t("procurement.suppliers.columnActions")}
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={8} align="center">
                  {t("common.loading")}
                </TableCell>
              </TableRow>
            ) : suppliers.length === 0 ? (
              <TableRow>
                <TableCell colSpan={8} align="center">
                  {t("common.noData")}
                </TableCell>
              </TableRow>
            ) : (
              suppliers.map((supplier) => (
                <TableRow key={supplier.id}>
                  <TableCell align={isRtl ? "right" : "left"}>
                    {supplier.name}
                  </TableCell>
                  <TableCell align={isRtl ? "right" : "left"}>
                    {supplier.contactPerson || "-"}
                  </TableCell>
                  <TableCell align={isRtl ? "right" : "left"}>
                    {supplier.phone || supplier.mobile || "-"}
                  </TableCell>
                  <TableCell align={isRtl ? "right" : "left"}>
                    {supplier.email || "-"}
                  </TableCell>
                  <TableCell align={isRtl ? "right" : "left"}>
                    {Number(supplier.currentBalance).toFixed(2)} EGP
                  </TableCell>
                  <TableCell align={isRtl ? "right" : "left"}>
                    <Rating
                      value={supplier.rating || 0}
                      readOnly
                      size="small"
                    />
                  </TableCell>
                  <TableCell align={isRtl ? "right" : "left"}>
                    <Chip
                      label={
                        supplier.isActive
                          ? t("procurement.suppliers.statusActive")
                          : t("procurement.suppliers.statusInactive")
                      }
                      color={supplier.isActive ? "success" : "default"}
                      size="small"
                    />
                  </TableCell>
                  <TableCell align={isRtl ? "right" : "left"}>
                    <IconButton
                      size="small"
                      onClick={() => handleViewDetails(supplier)}
                      title={tr("procurement.suppliers.viewDetails")}
                    >
                      <ViewIcon />
                    </IconButton>
                    <IconButton
                      size="small"
                      onClick={() => handleOpenDialog(supplier)}
                      title={tr("common.edit")}
                    >
                      <EditIcon />
                    </IconButton>
                    <IconButton
                      size="small"
                      onClick={() => handleDelete(supplier.id)}
                      title={tr("common.delete")}
                    >
                      <DeleteIcon />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Box sx={{ display: "flex", justifyContent: "center", mt: 3 }}>
        <Pagination
          count={totalPages}
          page={page}
          onChange={(_, value) => setPage(value)}
          color="primary"
        />
      </Box>

      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="md"
        fullWidth
        dir={isRtl ? "rtl" : "ltr"}
      >
        <DialogTitle>
          {selectedSupplier
            ? t("procurement.suppliers.editTitle")
            : t("procurement.suppliers.addNew")}
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelName")}
                value={formData.name}
                onChange={(e) =>
                  setFormData({ ...formData, name: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelContact")}
                value={formData.contactPerson}
                onChange={(e) =>
                  setFormData({ ...formData, contactPerson: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelEmail")}
                type="email"
                value={formData.email}
                onChange={(e) =>
                  setFormData({ ...formData, email: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelPhone")}
                value={formData.phone}
                onChange={(e) =>
                  setFormData({ ...formData, phone: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelMobile")}
                value={formData.mobile}
                onChange={(e) =>
                  setFormData({ ...formData, mobile: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelCity")}
                value={formData.city}
                onChange={(e) =>
                  setFormData({ ...formData, city: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelCountry")}
                value={formData.country}
                onChange={(e) =>
                  setFormData({ ...formData, country: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelTaxNumber")}
                value={formData.taxNumber}
                onChange={(e) =>
                  setFormData({ ...formData, taxNumber: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelCommercialRegister")}
                value={formData.commercialRegister}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    commercialRegister: e.target.value,
                  })
                }
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelCreditLimit")}
                type="number"
                value={formData.creditLimit}
                onChange={(e) =>
                  setFormData({ ...formData, creditLimit: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelAddress")}
                multiline
                rows={2}
                value={formData.address}
                onChange={(e) =>
                  setFormData({ ...formData, address: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelPaymentTerms")}
                multiline
                rows={2}
                value={formData.paymentTerms}
                onChange={(e) =>
                  setFormData({ ...formData, paymentTerms: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label={t("procurement.suppliers.labelNotes")}
                multiline
                rows={3}
                value={formData.notes}
                onChange={(e) =>
                  setFormData({ ...formData, notes: e.target.value })
                }
              />
            </Grid>
            <Grid item xs={12}>
              <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                <Typography>
                  {t("procurement.suppliers.labelRating")}
                </Typography>
                <Rating
                  value={formData.rating}
                  onChange={(_, value) =>
                    setFormData({ ...formData, rating: value || 0 })
                  }
                />
              </Box>
            </Grid>
            <Grid item xs={12}>
              <TextField
                select
                fullWidth
                label={t("procurement.suppliers.labelStatus")}
                value={formData.isActive}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    isActive: e.target.value === "true",
                  })
                }
              >
                <MenuItem value="true">
                  {t("procurement.suppliers.statusActive")}
                </MenuItem>
                <MenuItem value="false">
                  {t("procurement.suppliers.statusInactive")}
                </MenuItem>
              </TextField>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>{t("common.cancel")}</Button>
          <Button onClick={handleSubmit} variant="contained">
            {t("common.save")}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={openViewDialog}
        onClose={() => setOpenViewDialog(false)}
        maxWidth="md"
        fullWidth
        dir={isRtl ? "rtl" : "ltr"}
      >
        <DialogTitle>{t("procurement.suppliers.viewTitle")}</DialogTitle>
        <DialogContent>
          {selectedSupplier && (
            <Grid container spacing={2} sx={{ mt: 1 }}>
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  {t("procurement.suppliers.columnName")}
                </Typography>
                <Typography variant="body1">{selectedSupplier.name}</Typography>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  {t("procurement.suppliers.columnContact")}
                </Typography>
                <Typography variant="body1">
                  {selectedSupplier.contactPerson || "-"}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  {t("procurement.suppliers.columnEmail")}
                </Typography>
                <Typography variant="body1">
                  {selectedSupplier.email || "-"}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  {t("procurement.suppliers.columnPhone")}
                </Typography>
                <Typography variant="body1">
                  {selectedSupplier.phone || "-"}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  {t("procurement.suppliers.columnBalance")}
                </Typography>
                <Typography variant="body1">
                  {Number(selectedSupplier.currentBalance).toFixed(2)} EGP
                </Typography>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  {t("procurement.suppliers.columnRating")}
                </Typography>
                <Rating value={selectedSupplier.rating || 0} readOnly />
              </Grid>
              <Grid item xs={12}>
                <Typography variant="subtitle2" color="textSecondary">
                  {t("procurement.suppliers.labelAddress")}
                </Typography>
                <Typography variant="body1">
                  {selectedSupplier.address || "-"}
                </Typography>
              </Grid>
              <Grid item xs={12}>
                <Typography variant="subtitle2" color="textSecondary">
