                    </label>
                )}
            </div>
            <div
                className={joinClasses(
                    "space-y-4",
                    isContentVisible ? "" : "pointer-events-none opacity-50",
                    contentClassName,
                )}
            >
                {children}
            </div>
        </div>
    );
};

