              </button>
              <button
                onClick={onSave}
                disabled={!isValid()}
                className={`px-6 py-2.5 rounded-md transition-colors font-medium shadow-lg ${isValid()
                  ? "bg-indigo-600 text-white hover:bg-indigo-700"
