  createdDateFrom: string;
  createdDateTo: string;
  hasAttachments: boolean | null;
  hasComments: boolean | null;
  isOverdue: boolean | null;
  progressMin: number;
  progressMax: number;
  tags: string[];
  searchIn: ("title" | "description" | "comments" | "attachments")[];
}

interface SavedSearch {
  id: string;
  name: string;
  filters: SearchFilters;
}

interface AdvancedSearchProps {
  onSearch: (filters: SearchFilters) => void;
  onClose: () => void;
}

const defaultFilters: SearchFilters = {
  query: "",
  status: [],
  priority: [],
  projectId: "",
  categoryId: "",
  assignedTo: "",
  createdBy: "",
  dueDateFrom: "",
  dueDateTo: "",
  createdDateFrom: "",
  createdDateTo: "",
  hasAttachments: null,
  hasComments: null,
  isOverdue: null,
  progressMin: 0,
  progressMax: 100,
  tags: [],
  searchIn: ["title", "description"],
};

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const AdvancedSearch: React.FC<AdvancedSearchProps> = ({
  onSearch,
  onClose,
}) => {
  const [filters, setFilters] = useState<SearchFilters>(defaultFilters);
  const [users, setUsers] = useState<
    { id: string; firstName: string; lastName: string }[]
  >([]);
  const [projects, setProjects] = useState<{ id: string; name: string }[]>([]);
  const [categories, setCategories] = useState<{ id: string; name: string }[]>(
    [],
  );
  const [savedSearches, setSavedSearches] = useState<SavedSearch[]>([]);
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [searchName, setSearchName] = useState("");
  const [tagInput, setTagInput] = useState("");

  useEffect(() => {
    fetchUsers();
    fetchProjects();
    fetchCategories();
    loadSavedSearches();
  }, []);

  const fetchUsers = async () => {
    try {
      const response = await fetch(buildApiUrl("tasks/company-users"), {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setUsers(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  const fetchProjects = async () => {
    try {
      const response = await fetch(buildApiUrl("projects"), {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setProjects(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching projects:", error);
    }
  };

  const fetchCategories = async () => {
    try {
      const response = await fetch(buildApiUrl("tasks/categories/list"), {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setCategories(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const loadSavedSearches = () => {
    const saved = localStorage.getItem("taskSavedSearches");
    if (saved) {
      setSavedSearches(JSON.parse(saved));
    }
  };

  const saveSearch = () => {
    if (!searchName.trim()) return;

    const newSearch: SavedSearch = {
      id: Date.now().toString(),
      name: searchName,
      filters: { ...filters },
    };

    const updated = [...savedSearches, newSearch];
    setSavedSearches(updated);
    localStorage.setItem("taskSavedSearches", JSON.stringify(updated));
    setShowSaveModal(false);
    setSearchName("");
  };

  const deleteSavedSearch = (id: string) => {
    const updated = savedSearches.filter((s) => s.id !== id);
    setSavedSearches(updated);
    localStorage.setItem("taskSavedSearches", JSON.stringify(updated));
  };

  const loadSavedSearch = (search: SavedSearch) => {
    setFilters(search.filters);
  };

  const handleSearch = () => {
    onSearch(filters);
  };

  const resetFilters = () => {
    setFilters(defaultFilters);
  };

  const toggleStatus = (status: string) => {
    setFilters((prev) => ({
      ...prev,
      status: prev.status.includes(status)
        ? prev.status.filter((s) => s !== status)
        : [...prev.status, status],
    }));
  };

  const togglePriority = (priority: string) => {
    setFilters((prev) => ({
      ...prev,
      priority: prev.priority.includes(priority)
        ? prev.priority.filter((p) => p !== priority)
        : [...prev.priority, priority],
    }));
  };

  const toggleSearchIn = (
    field: "title" | "description" | "comments" | "attachments",
  ) => {
    setFilters((prev) => ({
      ...prev,
      searchIn: prev.searchIn.includes(field)
        ? prev.searchIn.filter((f) => f !== field)
        : [...prev.searchIn, field],
    }));
  };

  const addTag = () => {
    if (tagInput.trim() && !filters.tags.includes(tagInput.trim())) {
      setFilters((prev) => ({
        ...prev,
        tags: [...prev.tags, tagInput.trim()],
      }));
      setTagInput("");
    }
  };

  const removeTag = (tag: string) => {
    setFilters((prev) => ({
      ...prev,
      tags: prev.tags.filter((t) => t !== tag),
    }));
  };

  const getActiveFiltersCount = () => {
    let count = 0;
    if (filters.query) count++;
    if (filters.status.length) count++;
    if (filters.priority.length) count++;
    if (filters.projectId) count++;
    if (filters.categoryId) count++;
    if (filters.assignedTo) count++;
    if (filters.createdBy) count++;
    if (filters.dueDateFrom || filters.dueDateTo) count++;
    if (filters.createdDateFrom || filters.createdDateTo) count++;
    if (filters.hasAttachments !== null) count++;
    if (filters.hasComments !== null) count++;
    if (filters.isOverdue !== null) count++;
    if (filters.progressMin > 0 || filters.progressMax < 100) count++;
    if (filters.tags.length) count++;
    return count;
  };

  return (
    <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
      <div className="relative top-5 mx-auto p-5 border w-full max-w-4xl shadow-lg rounded-md bg-white max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center">
            <AdjustmentsHorizontalIcon className="h-6 w-6 text-indigo-600 ml-2" />
            <h2 className="text-xl font-bold text-gray-900">البحث المتقدم</h2>
            {getActiveFiltersCount() > 0 && (
              <span className="mr-2 px-2 py-1 text-xs bg-indigo-100 text-indigo-700 rounded-full">
                {getActiveFiltersCount()} فلتر نشط
              </span>
            )}
          </div>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600"
          >
            <XMarkIcon className="h-6 w-6" />
          </button>
        </div>

        {/* Saved Searches */}
        {savedSearches.length > 0 && (
          <div className="mb-6">
            <h3 className="text-sm font-medium text-gray-700 mb-2 flex items-center">
              <BookmarkIcon className="h-4 w-4 ml-1" />
              عمليات البحث المحفوظة
            </h3>
            <div className="flex flex-wrap gap-2">
              {savedSearches.map((search) => (
                <div
                  key={search.id}
                  className="inline-flex items-center bg-gray-100 rounded-full"
                >
                  <button
                    onClick={() => loadSavedSearch(search)}
                    className="px-3 py-1 text-sm text-gray-700 hover:text-indigo-600"
                  >
                    {search.name}
                  </button>
                  <button
                    onClick={() => deleteSavedSearch(search.id)}
                    className="p-1 text-gray-400 hover:text-red-600"
                  >
                    <XMarkIcon className="h-3 w-3" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Search Query */}
        <div className="mb-6">
          <label className="block text-sm font-medium text-gray-700 mb-2">
            كلمة البحث
          </label>
          <div className="relative">
            <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
            <input
              type="text"
              value={filters.query}
              onChange={(e) =>
                setFilters({ ...filters, query: e.target.value })
              }
              placeholder="ابحث في المهام..."
              className="w-full pr-10 pl-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          {/* Search In Options */}
          <div className="mt-2 flex flex-wrap gap-2">
            <span className="text-sm text-gray-500">البحث في:</span>
            {[
              { id: "title", label: "العنوان" },
              { id: "description", label: "الوصف" },
              { id: "comments", label: "التعليقات" },
              { id: "attachments", label: "المرفقات" },
            ].map((option) => (
              <button
                key={option.id}
                onClick={() => toggleSearchIn(option.id as any)}
                className={`px-2 py-1 text-xs rounded ${
                  filters.searchIn.includes(option.id as any)
                    ? "bg-indigo-100 text-indigo-700"
                    : "bg-gray-100 text-gray-600"
                }`}
              >
                {option.label}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Status Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              الحالة
            </label>
            <div className="flex flex-wrap gap-2">
              {[
                {
                  id: "pending",
                  label: "في الانتظار",
                  color: "bg-yellow-100 text-yellow-800",
                },
                {
                  id: "in_progress",
                  label: "قيد التنفيذ",
                  color: "bg-blue-100 text-blue-800",
                },
                {
                  id: "completed",
                  label: "مكتمل",
                  color: "bg-green-100 text-green-800",
                },
                {
                  id: "cancelled",
                  label: "ملغي",
                  color: "bg-red-100 text-red-800",
                },
              ].map((status) => (
                <button
                  key={status.id}
                  onClick={() => toggleStatus(status.id)}
                  className={`px-3 py-1 text-sm rounded-full border-2 ${
                    filters.status.includes(status.id)
                      ? `${status.color} border-current`
                      : "bg-gray-50 text-gray-500 border-transparent"
                  }`}
                >
                  {status.label}
                </button>
              ))}
            </div>
          </div>

          {/* Priority Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              الأولوية
            </label>
            <div className="flex flex-wrap gap-2">
              {[
                {
                  id: "urgent",
                  label: "عاجل",
                  color: "bg-red-100 text-red-800",
                },
                {
                  id: "high",
                  label: "عالي",
                  color: "bg-orange-100 text-orange-800",
                },
                {
                  id: "medium",
                  label: "متوسط",
                  color: "bg-yellow-100 text-yellow-800",
                },
                {
                  id: "low",
                  label: "منخفض",
                  color: "bg-green-100 text-green-800",
                },
              ].map((priority) => (
                <button
                  key={priority.id}
                  onClick={() => togglePriority(priority.id)}
                  className={`px-3 py-1 text-sm rounded-full border-2 ${
                    filters.priority.includes(priority.id)
                      ? `${priority.color} border-current`
                      : "bg-gray-50 text-gray-500 border-transparent"
                  }`}
                >
                  {priority.label}
                </button>
              ))}
            </div>
          </div>

          {/* Project Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              المشروع
            </label>
            <select
              value={filters.projectId}
              onChange={(e) =>
                setFilters({ ...filters, projectId: e.target.value })
              }
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">جميع المشاريع</option>
              {projects.map((project) => (
                <option key={project.id} value={project.id}>
                  {project.name}
                </option>
              ))}
            </select>
          </div>

          {/* Category Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              القسم
            </label>
            <select
              value={filters.categoryId}
              onChange={(e) =>
                setFilters({ ...filters, categoryId: e.target.value })
              }
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">جميع الأقسام</option>
              {categories.map((category) => (
                <option key={category.id} value={category.id}>
                  {category.name}
                </option>
              ))}
            </select>
          </div>

          {/* Assigned To Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              المسؤول
            </label>
            <select
              value={filters.assignedTo}
              onChange={(e) =>
                setFilters({ ...filters, assignedTo: e.target.value })
              }
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">جميع المستخدمين</option>
              {users.map((user) => (
                <option key={user.id} value={user.id}>
                  {user.firstName} {user.lastName}
                </option>
              ))}
            </select>
          </div>

          {/* Created By Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              أنشأها
            </label>
            <select
              value={filters.createdBy}
              onChange={(e) =>
                setFilters({ ...filters, createdBy: e.target.value })
              }
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">جميع المستخدمين</option>
              {users.map((user) => (
                <option key={user.id} value={user.id}>
                  {user.firstName} {user.lastName}
                </option>
              ))}
            </select>
          </div>

          {/* Due Date Range */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              تاريخ الاستحقاق
            </label>
            <div className="flex space-x-2 space-x-reverse">
              <input
                type="date"
                value={filters.dueDateFrom}
                onChange={(e) =>
                  setFilters({ ...filters, dueDateFrom: e.target.value })
                }
                className="flex-1 px-2 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
              <input
                type="date"
                value={filters.dueDateTo}
                onChange={(e) =>
                  setFilters({ ...filters, dueDateTo: e.target.value })
                }
                className="flex-1 px-2 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          {/* Created Date Range */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              تاريخ الإنشاء
            </label>
            <div className="flex space-x-2 space-x-reverse">
              <input
                type="date"
                value={filters.createdDateFrom}
                onChange={(e) =>
                  setFilters({ ...filters, createdDateFrom: e.target.value })
                }
                className="flex-1 px-2 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
              <input
                type="date"
                value={filters.createdDateTo}
                onChange={(e) =>
                  setFilters({ ...filters, createdDateTo: e.target.value })
                }
                className="flex-1 px-2 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          {/* Progress Range */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              التقدم: {filters.progressMin}% - {filters.progressMax}%
            </label>
            <div className="flex items-center space-x-2 space-x-reverse">
              <input
                type="range"
                min="0"
                max="100"
                value={filters.progressMin}
                onChange={(e) =>
                  setFilters({
                    ...filters,
                    progressMin: parseInt(e.target.value),
                  })
                }
                className="flex-1"
              />
              <input
                type="range"
                min="0"
                max="100"
                value={filters.progressMax}
                onChange={(e) =>
                  setFilters({
                    ...filters,
                    progressMax: parseInt(e.target.value),
                  })
                }
                className="flex-1"
              />
            </div>
          </div>
        </div>

        {/* Additional Filters */}
        <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="flex items-center">
              <input
                type="checkbox"
                checked={filters.isOverdue === true}
                onChange={(e) =>
                  setFilters({
                    ...filters,
                    isOverdue: e.target.checked ? true : null,
                  })
                }
                className="ml-2"
              />
              <span className="text-sm text-gray-700">المهام المتأخرة فقط</span>
            </label>
          </div>
          <div>
            <label className="flex items-center">
              <input
                type="checkbox"
                checked={filters.hasAttachments === true}
                onChange={(e) =>
                  setFilters({
                    ...filters,
                    hasAttachments: e.target.checked ? true : null,
                  })
                }
                className="ml-2"
              />
              <span className="text-sm text-gray-700">تحتوي على مرفقات</span>
            </label>
          </div>
          <div>
            <label className="flex items-center">
              <input
                type="checkbox"
                checked={filters.hasComments === true}
                onChange={(e) =>
                  setFilters({
                    ...filters,
                    hasComments: e.target.checked ? true : null,
                  })
                }
                className="ml-2"
              />
              <span className="text-sm text-gray-700">تحتوي على تعليقات</span>
            </label>
          </div>
        </div>

        {/* Tags Filter */}
        <div className="mt-6">
          <label className="block text-sm font-medium text-gray-700 mb-2">
            الوسوم
          </label>
          <div className="flex items-center space-x-2 space-x-reverse">
            <input
              type="text"
              value={tagInput}
              onChange={(e) => setTagInput(e.target.value)}
              onKeyPress={(e) =>
                e.key === "Enter" && (e.preventDefault(), addTag())
              }
              placeholder="أضف وسم..."
              className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <button
              onClick={addTag}
              className="px-3 py-2 bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200"
            >
              إضافة
            </button>
          </div>
          {filters.tags &&
            Array.isArray(filters.tags) &&
            filters.tags.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {filters.tags.map((tag, index) => (
                  <span
                    key={index}
                    className="inline-flex items-center px-2 py-1 bg-indigo-100 text-indigo-700 rounded text-sm"
                  >
                    {tag}
                    <button
                      onClick={() => removeTag(tag)}
                      className="mr-1 text-indigo-500 hover:text-indigo-700"
                    >
                      ×
                    </button>
                  </span>
                ))}
              </div>
            )}
        </div>

        {/* Actions */}
        <div className="mt-8 flex items-center justify-between border-t pt-4">
          <div className="flex items-center space-x-2 space-x-reverse">
            <button
              onClick={resetFilters}
              className="px-4 py-2 text-gray-600 hover:text-gray-800"
            >
              إعادة تعيين
            </button>
            <button
              onClick={() => setShowSaveModal(true)}
              className="px-4 py-2 text-indigo-600 hover:text-indigo-800 flex items-center"
            >
              <BookmarkIcon className="h-4 w-4 ml-1" />
              حفظ البحث
            </button>
          </div>
          <div className="flex items-center space-x-2 space-x-reverse">
            <button
              onClick={onClose}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200"
            >
              إلغاء
            </button>
            <button
              onClick={handleSearch}
              className="px-6 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 flex items-center"
            >
              <MagnifyingGlassIcon className="h-5 w-5 ml-2" />
              بحث
            </button>
          </div>
        </div>

        {/* Save Search Modal */}
        {showSaveModal && (
          <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-60">
            <div className="bg-white rounded-lg p-6 w-full max-w-sm">
              <h3 className="text-lg font-medium text-gray-900 mb-4">
                حفظ البحث
              </h3>
              <input
                type="text"
                value={searchName}
                onChange={(e) => setSearchName(e.target.value)}
                placeholder="اسم البحث..."
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500 mb-4"
                autoFocus
              />
              <div className="flex justify-end space-x-2 space-x-reverse">
                <button
                  onClick={() => {
                    setShowSaveModal(false);
                    setSearchName("");
                  }}
                  className="px-4 py-2 text-gray-600 hover:text-gray-800"
                >
                  إلغاء
                </button>
                <button
                  onClick={saveSearch}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
                >
                  حفظ
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdvancedSearch;

import React from "react";
import { ArrowPathIcon, CalendarIcon } from "@heroicons/react/24/outline";

interface RecurringConfig {
  enabled: boolean;
  frequency: "daily" | "weekly" | "monthly" | "yearly";
  interval: number;
  daysOfWeek: number[];
  dayOfMonth: number;
  endType: "never" | "date" | "count";
  endDate: string;
  endCount: number;
}

interface RecurringTaskFormProps {
  value: RecurringConfig;
  onChange: (config: RecurringConfig) => void;
}

const RecurringTaskForm: React.FC<RecurringTaskFormProps> = ({
  value,
  onChange,
}) => {
  const dayNames = [
    "الأحد",
    "الإثنين",
    "الثلاثاء",
    "الأربعاء",
    "الخميس",
    "الجمعة",
    "السبت",
  ];

  const handleChange = (field: keyof RecurringConfig, newValue: any) => {
    onChange({ ...value, [field]: newValue });
  };

  const toggleDayOfWeek = (day: number) => {
    const newDays = value.daysOfWeek.includes(day)
      ? value.daysOfWeek.filter((d) => d !== day)
      : [...value.daysOfWeek, day];
    handleChange("daysOfWeek", newDays);
  };

  const getFrequencyText = () => {
    switch (value.frequency) {
      case "daily":
        return value.interval === 1 ? "كل يوم" : `كل ${value.interval} أيام`;
      case "weekly":
        return value.interval === 1
          ? "كل أسبوع"
          : `كل ${value.interval} أسابيع`;
      case "monthly":
        return value.interval === 1 ? "كل شهر" : `كل ${value.interval} أشهر`;
      case "yearly":
        return value.interval === 1 ? "كل سنة" : `كل ${value.interval} سنوات`;
      default:
        return "";
    }
  };

  const getEndText = () => {
    switch (value.endType) {
      case "never":
        return "بدون نهاية";
      case "date":
        return `حتى ${value.endDate}`;
      case "count":
        return `${value.endCount} مرات`;
      default:
        return "";
    }
  };

  return (
    <div className="bg-gray-50 rounded-lg border border-gray-200 p-4">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center">
          <ArrowPathIcon className="h-5 w-5 text-indigo-600 ml-2" />
          <h4 className="font-medium text-gray-900">مهمة متكررة</h4>
        </div>
        <label className="relative inline-flex items-center cursor-pointer">
          <input
            type="checkbox"
            checked={value.enabled}
            onChange={(e) => handleChange("enabled", e.target.checked)}
            className="sr-only peer"
          />
          <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
        </label>
      </div>

      {value.enabled && (
        <div className="space-y-4">
          {/* Frequency Selection */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              التكرار
            </label>
            <div className="grid grid-cols-4 gap-2">
              {[
                { value: "daily", label: "يومي" },
                { value: "weekly", label: "أسبوعي" },
                { value: "monthly", label: "شهري" },
                { value: "yearly", label: "سنوي" },
              ].map((option) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => handleChange("frequency", option.value)}
                  className={`px-3 py-2 text-sm font-medium rounded-md border ${
                    value.frequency === option.value
                      ? "bg-indigo-600 text-white border-indigo-600"
                      : "bg-white text-gray-700 border-gray-300 hover:bg-gray-50"
                  }`}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>

          {/* Interval */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              كل
            </label>
            <div className="flex items-center space-x-2 space-x-reverse">
              <input
                type="number"
                min="1"
                max="365"
                value={value.interval}
                onChange={(e) =>
                  handleChange("interval", parseInt(e.target.value) || 1)
                }
                className="w-20 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
              <span className="text-gray-600">
                {value.frequency === "daily" && "يوم"}
                {value.frequency === "weekly" && "أسبوع"}
                {value.frequency === "monthly" && "شهر"}
                {value.frequency === "yearly" && "سنة"}
              </span>
            </div>
          </div>

          {/* Days of Week (for weekly) */}
          {value.frequency === "weekly" && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                أيام الأسبوع
              </label>
              <div className="flex flex-wrap gap-2">
                {dayNames.map((day, index) => (
                  <button
                    key={index}
                    type="button"
                    onClick={() => toggleDayOfWeek(index)}
                    className={`px-3 py-1.5 text-sm font-medium rounded-full ${
                      value.daysOfWeek.includes(index)
                        ? "bg-indigo-600 text-white"
                        : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                    }`}
                  >
                    {day}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Day of Month (for monthly) */}
          {value.frequency === "monthly" && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                يوم الشهر
              </label>
              <select
                value={value.dayOfMonth}
                onChange={(e) =>
                  handleChange("dayOfMonth", parseInt(e.target.value))
                }
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
              >
                {Array.from({ length: 31 }, (_, i) => i + 1).map((day) => (
                  <option key={day} value={day}>
                    {day}
                  </option>
                ))}
                <option value={-1}>آخر يوم في الشهر</option>
              </select>
            </div>
          )}

          {/* End Options */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              ينتهي
            </label>
            <div className="space-y-2">
              <label className="flex items-center">
                <input
                  type="radio"
                  name="endType"
                  value="never"
                  checked={value.endType === "never"}
                  onChange={() => handleChange("endType", "never")}
                  className="ml-2"
                />
                <span className="text-sm text-gray-700">أبداً</span>
              </label>

              <label className="flex items-center">
                <input
                  type="radio"
                  name="endType"
                  value="date"
                  checked={value.endType === "date"}
                  onChange={() => handleChange("endType", "date")}
                  className="ml-2"
                />
                <span className="text-sm text-gray-700 ml-2">في تاريخ</span>
                {value.endType === "date" && (
                  <input
                    type="date"
                    value={value.endDate}
                    onChange={(e) => handleChange("endDate", e.target.value)}
                    className="mr-2 px-2 py-1 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  />
                )}
              </label>

              <label className="flex items-center">
                <input
                  type="radio"
                  name="endType"
                  value="count"
                  checked={value.endType === "count"}
                  onChange={() => handleChange("endType", "count")}
                  className="ml-2"
                />
                <span className="text-sm text-gray-700 ml-2">بعد</span>
                {value.endType === "count" && (
                  <>
                    <input
                      type="number"
                      min="1"
                      max="999"
                      value={value.endCount}
                      onChange={(e) =>
                        handleChange("endCount", parseInt(e.target.value) || 1)
                      }
                      className="mr-2 w-16 px-2 py-1 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                    <span className="text-sm text-gray-700">مرة</span>
                  </>
                )}
              </label>
            </div>
          </div>

          {/* Summary */}
          <div className="bg-indigo-50 rounded-lg p-3 border border-indigo-200">
            <div className="flex items-center text-indigo-800">
              <CalendarIcon className="h-5 w-5 ml-2" />
              <span className="text-sm font-medium">
                ستتكرر هذه المهمة {getFrequencyText()}
                {value.frequency === "weekly" &&
                  value.daysOfWeek.length > 0 && (
                    <>
                      {" "}
                      في أيام:{" "}
                      {value.daysOfWeek.map((d) => dayNames[d]).join("، ")}
                    </>
                  )}
                {value.frequency === "monthly" && (
                  <>
                    {" "}
                    في اليوم{" "}
                    {value.dayOfMonth === -1 ? "الأخير" : value.dayOfMonth} من
                    الشهر
                  </>
                )}
                {" - "}
                {getEndText()}
              </span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

