import React, { useState, useEffect } from "react";
import { buildApiUrl } from "../../utils/urlHelper";
import tokenManager from "../../utils/tokenManager";
import {
  CheckCircleIcon,
  PlusIcon,
  XMarkIcon,
  TrashIcon,
  PencilIcon,
  Bars3Icon,
} from "@heroicons/react/24/outline";
import { CheckCircleIcon as CheckCircleSolidIcon } from "@heroicons/react/24/solid";

interface ChecklistItem {
  id: string;
  content: string;
  isCompleted: boolean;
  order: number;
}

interface Checklist {
  id: string;
  title: string;
  items: ChecklistItem[];
  completedCount: number;
  totalCount: number;
}

interface TaskChecklistProps {
  taskId: string;
  onUpdate?: () => void;
}

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const TaskChecklist: React.FC<TaskChecklistProps> = ({ taskId, onUpdate }) => {
  const [checklists, setChecklists] = useState<Checklist[]>([]);
  const [loading, setLoading] = useState(true);
  const [showAddChecklist, setShowAddChecklist] = useState(false);
  const [newChecklistTitle, setNewChecklistTitle] = useState("");
  const [newItemContent, setNewItemContent] = useState<Record<string, string>>(
    {},
  );
  const [editingItem, setEditingItem] = useState<{
    checklistId: string;
    itemId: string;
  } | null>(null);
  const [editContent, setEditContent] = useState("");

  useEffect(() => {
    fetchChecklists();
  }, [taskId]);

  const fetchChecklists = async () => {
    try {
      setLoading(true);
      const response = await fetch(buildApiUrl(`tasks/${taskId}/checklists`), {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setChecklists(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching checklists:", error);
    } finally {
      setLoading(false);
    }
  };

  const createChecklist = async () => {
    if (!newChecklistTitle.trim()) return;

    try {
      const response = await fetch(buildApiUrl(`tasks/${taskId}/checklists`), {
        method: "POST",
        headers: getAuthHeaders({ "Content-Type": "application/json" }),
        body: JSON.stringify({ title: newChecklistTitle }),
      });

      const data = await response.json();
      if (data.success) {
        fetchChecklists();
        setNewChecklistTitle("");
        setShowAddChecklist(false);
        onUpdate?.();
      }
    } catch (error) {
      console.error("Error creating checklist:", error);
    }
  };

  const deleteChecklist = async (checklistId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذه القائمة؟")) return;

    try {
      const response = await fetch(
        buildApiUrl(`tasks/checklists/${checklistId}`),
        {
          method: "DELETE",
          headers: getAuthHeaders(),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchChecklists();
        onUpdate?.();
      }
    } catch (error) {
      console.error("Error deleting checklist:", error);
    }
  };

  const addItem = async (checklistId: string) => {
    const content = newItemContent[checklistId];
    if (!content?.trim()) return;

    try {
      const response = await fetch(
        buildApiUrl(`tasks/checklists/${checklistId}/items`),
        {
          method: "POST",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ content }),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchChecklists();
        setNewItemContent({ ...newItemContent, [checklistId]: "" });
        onUpdate?.();
      }
    } catch (error) {
      console.error("Error adding item:", error);
    }
  };

  const toggleItem = async (
    checklistId: string,
    itemId: string,
    isCompleted: boolean,
  ) => {
    try {
      const response = await fetch(
        buildApiUrl(`tasks/checklists/items/${itemId}`),
        {
          method: "PUT",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ isCompleted: !isCompleted }),
        },
      );

      const data = await response.json();
      if (data.success) {
        // Update local state immediately for better UX
        setChecklists((prev) =>
          prev.map((cl) => {
            if (cl.id === checklistId) {
              return {
                ...cl,
                items: cl.items.map((item) =>
                  item.id === itemId
                    ? { ...item, isCompleted: !isCompleted }
                    : item,
                ),
                completedCount: cl.completedCount + (isCompleted ? -1 : 1),
              };
            }
            return cl;
          }),
        );
        onUpdate?.();
      }
    } catch (error) {
      console.error("Error toggling item:", error);
    }
  };

  const updateItem = async (_checklistId: string, itemId: string) => {
    if (!editContent.trim()) return;

    try {
      const response = await fetch(
        buildApiUrl(`tasks/checklists/items/${itemId}`),
        {
          method: "PUT",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ content: editContent }),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchChecklists();
        setEditingItem(null);
        setEditContent("");
        onUpdate?.();
      }
    } catch (error) {
      console.error("Error updating item:", error);
    }
  };

  const deleteItem = async (_checklistId: string, itemId: string) => {
    try {
      const response = await fetch(
        buildApiUrl(`tasks/checklists/items/${itemId}`),
        {
          method: "DELETE",
          headers: getAuthHeaders(),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchChecklists();
        onUpdate?.();
      }
    } catch (error) {
      console.error("Error deleting item:", error);
    }
  };

  const getProgressPercentage = (checklist: Checklist) => {
    if (checklist.totalCount === 0) return 0;
    return Math.round((checklist.completedCount / checklist.totalCount) * 100);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-4">
        <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-medium text-gray-900 flex items-center">
          <CheckCircleIcon className="h-5 w-5 text-indigo-600 ml-2" />
          قوائم التحقق
        </h3>
        <button
          onClick={() => setShowAddChecklist(true)}
          className="inline-flex items-center px-3 py-1.5 text-sm bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
        >
          <PlusIcon className="h-4 w-4 ml-1" />
          إضافة قائمة
        </button>
      </div>

      {/* Add Checklist Form */}
      {showAddChecklist && (
        <div className="bg-gray-50 rounded-lg p-4 border border-gray-200">
          <input
            type="text"
            value={newChecklistTitle}
            onChange={(e) => setNewChecklistTitle(e.target.value)}
            placeholder="عنوان القائمة..."
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500 mb-3"
            autoFocus
            onKeyPress={(e) => e.key === "Enter" && createChecklist()}
          />
          <div className="flex justify-end space-x-2 space-x-reverse">
            <button
              onClick={() => {
                setShowAddChecklist(false);
                setNewChecklistTitle("");
              }}
              className="px-3 py-1.5 text-sm text-gray-600 hover:text-gray-800"
            >
              إلغاء
            </button>
            <button
              onClick={createChecklist}
              className="px-3 py-1.5 text-sm bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
            >
              إنشاء
            </button>
          </div>
        </div>
      )}

      {/* Checklists */}
      {checklists.length === 0 && !showAddChecklist ? (
        <div className="text-center py-8 text-gray-500">
          <CheckCircleIcon className="h-10 w-10 mx-auto mb-2 text-gray-300" />
          <p className="text-sm">لا توجد قوائم تحقق</p>
        </div>
      ) : (
        checklists.map((checklist) => (
          <div
            key={checklist.id}
            className="bg-white rounded-lg border border-gray-200 overflow-hidden"
          >
            {/* Checklist Header */}
            <div className="bg-gray-50 px-4 py-3 border-b border-gray-200">
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <Bars3Icon className="h-4 w-4 text-gray-400 ml-2" />
                  <h4 className="font-medium text-gray-900">
                    {checklist.title}
                  </h4>
                </div>
                <div className="flex items-center space-x-2 space-x-reverse">
                  <span className="text-sm text-gray-500">
                    {checklist.completedCount}/{checklist.totalCount}
                  </span>
                  <button
                    onClick={() => deleteChecklist(checklist.id)}
                    className="p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded"
                  >
                    <TrashIcon className="h-4 w-4" />
                  </button>
                </div>
              </div>

              {/* Progress Bar */}
              {checklist.totalCount > 0 && (
                <div className="mt-2">
                  <div className="w-full bg-gray-200 rounded-full h-1.5">
                    <div
                      className={`h-1.5 rounded-full transition-all ${
                        getProgressPercentage(checklist) === 100
                          ? "bg-green-500"
                          : "bg-indigo-600"
                      }`}
                      style={{ width: `${getProgressPercentage(checklist)}%` }}
                    ></div>
                  </div>
                </div>
              )}
            </div>

            {/* Checklist Items */}
            <div className="p-2">
              {checklist.items.map((item) => (
                <div
                  key={item.id}
                  className={`flex items-center p-2 rounded-lg hover:bg-gray-50 group ${
                    item.isCompleted ? "opacity-60" : ""
                  }`}
                >
                  <button
                    onClick={() =>
                      toggleItem(checklist.id, item.id, item.isCompleted)
                    }
                    className="flex-shrink-0 ml-3"
                  >
                    {item.isCompleted ? (
                      <CheckCircleSolidIcon className="h-5 w-5 text-green-500" />
                    ) : (
                      <div className="h-5 w-5 border-2 border-gray-300 rounded-full hover:border-indigo-500"></div>
                    )}
                  </button>

                  {editingItem?.checklistId === checklist.id &&
                  editingItem?.itemId === item.id ? (
                    <div className="flex-1 flex items-center space-x-2 space-x-reverse">
                      <input
                        type="text"
                        value={editContent}
                        onChange={(e) => setEditContent(e.target.value)}
                        className="flex-1 px-2 py-1 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-indigo-500"
                        autoFocus
                        onKeyPress={(e) =>
                          e.key === "Enter" && updateItem(checklist.id, item.id)
                        }
                      />
                      <button
                        onClick={() => updateItem(checklist.id, item.id)}
                        className="text-indigo-600 hover:text-indigo-800"
                      >
                        حفظ
                      </button>
                      <button
                        onClick={() => {
                          setEditingItem(null);
                          setEditContent("");
                        }}
                        className="text-gray-400 hover:text-gray-600"
                      >
                        إلغاء
                      </button>
                    </div>
                  ) : (
                    <>
                      <span
                        className={`flex-1 text-sm ${item.isCompleted ? "line-through text-gray-400" : "text-gray-700"}`}
                      >
                        {item.content}
                      </span>
                      <div className="opacity-0 group-hover:opacity-100 flex items-center space-x-1 space-x-reverse">
                        <button
                          onClick={() => {
                            setEditingItem({
                              checklistId: checklist.id,
                              itemId: item.id,
                            });
                            setEditContent(item.content);
                          }}
                          className="p-1 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded"
                        >
                          <PencilIcon className="h-3.5 w-3.5" />
                        </button>
                        <button
                          onClick={() => deleteItem(checklist.id, item.id)}
                          className="p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded"
                        >
                          <XMarkIcon className="h-3.5 w-3.5" />
                        </button>
                      </div>
                    </>
                  )}
                </div>
              ))}

              {/* Add Item */}
              <div className="flex items-center p-2 mt-1">
                <PlusIcon className="h-5 w-5 text-gray-400 ml-3" />
                <input
                  type="text"
                  value={newItemContent[checklist.id] || ""}
                  onChange={(e) =>
                    setNewItemContent({
                      ...newItemContent,
                      [checklist.id]: e.target.value,
                    })
                  }
                  placeholder="أضف عنصر..."
                  className="flex-1 px-2 py-1 text-sm border-0 focus:outline-none focus:ring-0 placeholder-gray-400"
                  onKeyPress={(e) => e.key === "Enter" && addItem(checklist.id)}
                />
                {newItemContent[checklist.id] && (
                  <button
                    onClick={() => addItem(checklist.id)}
                    className="text-sm text-indigo-600 hover:text-indigo-800"
                  >
                    إضافة
                  </button>
                )}
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
};

export default TaskChecklist;

import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { buildApiUrl } from "../../utils/urlHelper";
import tokenManager from "../../utils/tokenManager";
import {
  LinkIcon,
  PlusIcon,
  XMarkIcon,
  ArrowRightIcon,
  ArrowLeftIcon,
  ExclamationTriangleIcon,
  CheckCircleIcon,
  ClockIcon,
} from "@heroicons/react/24/outline";

interface Task {
  id: string;
  title: string;
  status: string;
  priority: string;
}

interface Dependency {
  id: string;
  dependsOnTaskId: string;
  dependsOnTask: Task;
  type: "blocks" | "blocked_by" | "related";
}

interface TaskDependenciesProps {
  taskId: string;
  dependencies?: string[];
  onUpdate?: () => void;
}

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const TaskDependencies: React.FC<TaskDependenciesProps> = ({
  taskId,
  onUpdate,
}) => {
  const [allTasks, setAllTasks] = useState<Task[]>([]);
  const [taskDependencies, setTaskDependencies] = useState<Dependency[]>([]);
  const [blockedByTasks, setBlockedByTasks] = useState<Dependency[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedTaskId, setSelectedTaskId] = useState("");
  const [dependencyType, setDependencyType] = useState<
    "blocks" | "blocked_by" | "related"
  >("blocked_by");
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => {
    fetchAllTasks();
    fetchDependencies();
  }, [taskId]);

  const fetchAllTasks = async () => {
    try {
      const response = await fetch(buildApiUrl("tasks"), {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        // Exclude current task from the list
        setAllTasks(data.data.filter((t: Task) => t.id !== taskId));
      }
    } catch (error) {
      console.error("Error fetching tasks:", error);
    }
  };

  const fetchDependencies = async () => {
    try {
      const response = await fetch(
        buildApiUrl(`tasks/${taskId}/dependencies`),
        {
          headers: getAuthHeaders(),
        },
      );
      const data = await response.json();
      if (data.success) {
        setTaskDependencies(data.data?.blocks || []);
        setBlockedByTasks(data.data?.blockedBy || []);
      }
    } catch (error) {
      console.error("Error fetching dependencies:", error);
    }
  };

  const addDependency = async () => {
    if (!selectedTaskId) return;

    try {
      setLoading(true);
      const response = await fetch(
        buildApiUrl(`tasks/${taskId}/dependencies`),
        {
          method: "POST",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({
            dependsOnId: selectedTaskId,
            type: dependencyType,
          }),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchDependencies();
        setShowAddModal(false);
        setSelectedTaskId("");
        onUpdate?.();
      } else {
        alert(data.error || "فشل في إضافة التبعية");
      }
    } catch (error) {
      console.error("Error adding dependency:", error);
      alert("فشل في إضافة التبعية");
    } finally {
      setLoading(false);
    }
  };

  const removeDependency = async (dependencyId: string) => {
    if (!confirm("هل أنت متأكد من إزالة هذه التبعية؟")) return;

    try {
      const response = await fetch(
        buildApiUrl(`tasks/dependencies/${dependencyId}`),
        {
          method: "DELETE",
          headers: getAuthHeaders(),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchDependencies();
        onUpdate?.();
      }
    } catch (error) {
      console.error("Error removing dependency:", error);
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status?.toLowerCase()) {
      case "completed":
        return <CheckCircleIcon className="h-4 w-4 text-green-500" />;
      case "in_progress":
        return <ClockIcon className="h-4 w-4 text-blue-500" />;
      case "pending":
        return <ClockIcon className="h-4 w-4 text-yellow-500" />;
      default:
        return <ExclamationTriangleIcon className="h-4 w-4 text-gray-500" />;
    }
  };

  const getStatusText = (status: string) => {
    switch (status?.toLowerCase()) {
      case "completed":
        return "مكتمل";
      case "in_progress":
        return "قيد التنفيذ";
      case "pending":
        return "في الانتظار";
      case "cancelled":
        return "ملغي";
      default:
        return status;
    }
  };

  const filteredTasks = allTasks.filter(
    (task) =>
      task.title.toLowerCase().includes(searchQuery.toLowerCase()) &&
      !taskDependencies.some((d) => d.dependsOnTaskId === task.id) &&
      !blockedByTasks.some((d) => d.dependsOnTaskId === task.id),
  );

  const hasBlockingIssues = blockedByTasks.some(
    (d) => d.dependsOnTask?.status?.toLowerCase() !== "completed",
  );

  return (
    <div className="bg-white rounded-lg border border-gray-200 p-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-medium text-gray-900 flex items-center">
          <LinkIcon className="h-5 w-5 text-indigo-600 ml-2" />
          تبعيات المهمة
        </h3>
        <button
          onClick={() => setShowAddModal(true)}
          className="inline-flex items-center px-3 py-1.5 text-sm bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
        >
          <PlusIcon className="h-4 w-4 ml-1" />
          إضافة تبعية
        </button>
      </div>

      {hasBlockingIssues && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3 mb-4">
          <div className="flex items-center text-yellow-800">
            <ExclamationTriangleIcon className="h-5 w-5 ml-2" />
            <span className="text-sm font-medium">
              هذه المهمة محظورة بمهام أخرى غير مكتملة
            </span>
          </div>
        </div>
      )}

      {/* Blocked By Section */}
      {blockedByTasks.length > 0 && (
        <div className="mb-4">
          <h4 className="text-sm font-medium text-gray-700 mb-2 flex items-center">
            <ArrowLeftIcon className="h-4 w-4 ml-1 text-red-500" />
            محظورة بـ (يجب إكمالها أولاً)
          </h4>
          <div className="space-y-2">
            {blockedByTasks.map((dep) => (
              <div
                key={dep.id}
                className={`flex items-center justify-between p-3 rounded-lg border ${
                  dep.dependsOnTask?.status?.toLowerCase() === "completed"
                    ? "bg-green-50 border-green-200"
                    : "bg-red-50 border-red-200"
                }`}
              >
                <div className="flex items-center">
                  {getStatusIcon(dep.dependsOnTask?.status)}
                  <Link
                    to={`/tasks/${dep.dependsOnTaskId}`}
                    className="mr-2 text-sm font-medium text-gray-900 hover:text-indigo-600"
                  >
                    {dep.dependsOnTask?.title}
                  </Link>
                  <span className="text-xs text-gray-500 mr-2">
                    ({getStatusText(dep.dependsOnTask?.status)})
                  </span>
                </div>
                <button
                  onClick={() => removeDependency(dep.id)}
                  className="p-1 text-gray-400 hover:text-red-600 hover:bg-red-100 rounded"
                >
                  <XMarkIcon className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Blocks Section */}
      {taskDependencies.length > 0 && (
        <div className="mb-4">
          <h4 className="text-sm font-medium text-gray-700 mb-2 flex items-center">
            <ArrowRightIcon className="h-4 w-4 ml-1 text-blue-500" />
            تحظر (تنتظر إكمال هذه المهمة)
          </h4>
          <div className="space-y-2">
            {taskDependencies.map((dep) => (
              <div
                key={dep.id}
                className="flex items-center justify-between p-3 rounded-lg border bg-blue-50 border-blue-200"
              >
                <div className="flex items-center">
                  {getStatusIcon(dep.dependsOnTask?.status)}
                  <Link
                    to={`/tasks/${dep.dependsOnTaskId}`}
                    className="mr-2 text-sm font-medium text-gray-900 hover:text-indigo-600"
                  >
                    {dep.dependsOnTask?.title}
                  </Link>
                  <span className="text-xs text-gray-500 mr-2">
                    ({getStatusText(dep.dependsOnTask?.status)})
                  </span>
                </div>
                <button
                  onClick={() => removeDependency(dep.id)}
                  className="p-1 text-gray-400 hover:text-red-600 hover:bg-red-100 rounded"
                >
                  <XMarkIcon className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {taskDependencies.length === 0 && blockedByTasks.length === 0 && (
        <div className="text-center py-6 text-gray-500">
          <LinkIcon className="h-8 w-8 mx-auto mb-2 text-gray-300" />
          <p className="text-sm">لا توجد تبعيات لهذه المهمة</p>
        </div>
      )}

      {/* Add Dependency Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-full max-w-md shadow-lg rounded-md bg-white">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-medium text-gray-900">إضافة تبعية</h3>
              <button
                onClick={() => setShowAddModal(false)}
                className="text-gray-400 hover:text-gray-600"
              >
                <XMarkIcon className="h-6 w-6" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  نوع التبعية
                </label>
                <select
                  value={dependencyType}
                  onChange={(e) => setDependencyType(e.target.value as any)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                >
                  <option value="blocked_by">
                    محظورة بـ (يجب إكمال المهمة المحددة أولاً)
                  </option>
                  <option value="blocks">
                    تحظر (المهمة المحددة تنتظر إكمال هذه المهمة)
                  </option>
                  <option value="related">مرتبطة بـ</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  البحث عن مهمة
                </label>
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="ابحث بعنوان المهمة..."
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  اختر المهمة
                </label>
                <div className="max-h-60 overflow-y-auto border border-gray-300 rounded-md">
                  {filteredTasks.length === 0 ? (
                    <div className="p-4 text-center text-gray-500 text-sm">
                      لا توجد مهام متاحة
                    </div>
                  ) : (
                    filteredTasks.map((task) => (
                      <button
                        key={task.id}
                        onClick={() => setSelectedTaskId(task.id)}
                        className={`w-full text-right p-3 border-b last:border-b-0 hover:bg-gray-50 ${
                          selectedTaskId === task.id
                            ? "bg-indigo-50 border-indigo-200"
                            : ""
                        }`}
                      >
                        <div className="flex items-center">
                          {getStatusIcon(task.status)}
                          <span className="mr-2 text-sm font-medium text-gray-900">
                            {task.title}
                          </span>
                        </div>
                        <span className="text-xs text-gray-500">
                          {getStatusText(task.status)}
                        </span>
                      </button>
                    ))
                  )}
                </div>
              </div>
            </div>

            <div className="mt-6 flex justify-end space-x-2 space-x-reverse">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-2 bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200"
              >
                إلغاء
              </button>
              <button
                onClick={addDependency}
                disabled={!selectedTaskId || loading}
                className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? "جاري الإضافة..." : "إضافة"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskDependencies;

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  ArrowRightIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  PlayIcon,
  StopIcon,
  PauseIcon,
  PencilIcon,
  TrashIcon,
  DocumentDuplicateIcon,
  ShareIcon,
  CheckIcon,
  CalendarIcon,
} from "@heroicons/react/24/outline";
import { Task } from "../../../types/tasks";

interface TaskHeaderProps {
  task: Task;
  isTimerRunning: boolean;
  isTimerPaused?: boolean;
  elapsedSeconds: number;
  handleStartTimer: () => void;
  handleStopTimer: () => void;
  handlePauseTimer?: () => void;
  handleResumeTimer?: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onDuplicate: () => void;
  isSmartTimeTrackingEnabled: boolean;
  canEdit: boolean;
  canDelete: boolean;
  settings?: any;
}

const TaskHeader: React.FC<TaskHeaderProps> = ({
  task,
  isTimerRunning,
  isTimerPaused = false,
  elapsedSeconds,
  handleStartTimer,
  handleStopTimer,
  handlePauseTimer,
  handleResumeTimer,
  onEdit,
  onDelete,
  onDuplicate,
  isSmartTimeTrackingEnabled,
  canEdit,
  canDelete,
  settings,
}) => {
  const navigate = useNavigate();
  const [copiedLink, setCopiedLink] = useState(false);

  // Format seconds to HH:MM:SS
  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  const copyLink = () => {
    const url = window.location.href;
    navigator.clipboard.writeText(url);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2000);
  };

  return (
    <div className="flex items-center justify-between mb-8">
      <div className="flex items-center gap-4">
        <button
          onClick={() => navigate("/super-admin/dev-tasks")}
          className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-xl transition-colors"
        >
          <ArrowRightIcon className="h-6 w-6 text-gray-600 dark:text-gray-400" />
        </button>

        {/* Navigation Buttons */}
        <div className="flex items-center bg-gray-100 dark:bg-gray-800 rounded-xl p-0.5 border border-gray-200 dark:border-gray-700">
          <button
            onClick={() =>
              task.nextTaskId &&
              navigate(`/super-admin/dev-tasks/${task.nextTaskId}`)
            }
            disabled={!task.nextTaskId}
            className="p-1.5 hover:bg-white dark:hover:bg-gray-700 rounded-lg transition-all disabled:opacity-30 disabled:cursor-not-allowed"
            title="المهمة التالية"
          >
            <ChevronLeftIcon className="h-5 w-5 text-gray-600 dark:text-gray-400" />
          </button>
          <div className="w-px h-4 bg-gray-300 dark:bg-gray-600 mx-0.5"></div>
          <button
            onClick={() =>
              task.previousTaskId &&
              navigate(`/super-admin/dev-tasks/${task.previousTaskId}`)
            }
            disabled={!task.previousTaskId}
            className="p-1.5 hover:bg-white dark:hover:bg-gray-700 rounded-lg transition-all disabled:opacity-30 disabled:cursor-not-allowed"
            title="المهمة السابقة"
          >
            <ChevronRightIcon className="h-5 w-5 text-gray-600 dark:text-gray-400" />
          </button>
        </div>

        <div>
          <div className="flex items-center gap-3 text-sm text-gray-500 dark:text-gray-400 mb-1">
            <span className="bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded text-xs font-mono">
              #{task.id.slice(0, 8)}
            </span>
            <span>/</span>
            <span>{task.projectName || "General"}</span>
            {(settings?.taskDetailsVisibility?.showCreatedAt ?? true) && (
              <div className="flex items-center gap-1.5 mr-2 pr-2 border-r border-gray-200 dark:border-gray-700">
                <CalendarIcon className="h-3.5 w-3.5" />
                <span>
                  {new Date(task.createdAt).toLocaleString("ar-EG", {
                    year: "numeric",
                    month: "long",
                    day: "numeric",
                    hour: "2-digit",
                    minute: "2-digit",
                  })}
                </span>
              </div>
            )}
          </div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white line-clamp-1 max-w-3xl">
            {task.title}
          </h1>
        </div>
      </div>

      <div className="flex items-center gap-3">
        {/* Smart Time Tracking Buttons */}
        {isSmartTimeTrackingEnabled && (
          <div className="flex items-center gap-2">
            {!isTimerRunning ? (
              <button
                onClick={handleStartTimer}
                className="flex items-center gap-3 px-5 py-3 rounded-xl font-bold shadow-md transition-all transform active:scale-95 bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-200 dark:shadow-none"
              >
                <PlayIcon className="h-5 w-5" />
                <span>ابدأ العمل</span>
              </button>
            ) : (
              <>
                <div className="flex items-center gap-3 px-4 py-3 bg-gray-100 dark:bg-gray-800 rounded-xl border-2 border-indigo-500 dark:border-indigo-400">
                  <span className="font-mono text-lg font-bold text-gray-900 dark:text-white">
                    {formatTime(elapsedSeconds)}
                  </span>
                  <span
                    className={`w-2 h-2 rounded-full ${isTimerPaused ? "bg-yellow-500" : "bg-green-500 animate-pulse"}`}
                  ></span>
                </div>
                {isTimerPaused ? (
                  <button
                    onClick={handleResumeTimer}
                    className="flex items-center gap-2 px-4 py-3 rounded-xl font-bold shadow-md transition-all transform active:scale-95 bg-green-600 text-white hover:bg-green-700"
                    title="استئناف"
                  >
                    <PlayIcon className="h-5 w-5" />
                    <span>استئناف</span>
                  </button>
                ) : (
                  <button
                    onClick={handlePauseTimer}
                    className="flex items-center gap-2 px-4 py-3 rounded-xl font-bold shadow-md transition-all transform active:scale-95 bg-yellow-600 text-white hover:bg-yellow-700"
                    title="إيقاف مؤقت"
                  >
                    <PauseIcon className="h-5 w-5" />
                    <span>إيقاف مؤقت</span>
                  </button>
                )}
                <button
                  onClick={handleStopTimer}
                  className="flex items-center gap-2 px-4 py-3 rounded-xl font-bold shadow-md transition-all transform active:scale-95 bg-red-600 text-white hover:bg-red-700"
                  title="إيقاف نهائي"
                >
                  <StopIcon className="h-5 w-5" />
                  <span>إيقاف</span>
                </button>
              </>
            )}
          </div>
        )}

        <div className="h-8 w-px bg-gray-200 dark:bg-gray-700"></div>

        <button
          onClick={copyLink}
          className="p-3 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-xl transition-colors relative group"
          title="نسخ الرابط"
        >
          {copiedLink ? (
            <CheckIcon className="h-5 w-5 text-green-500" />
          ) : (
            <ShareIcon className="h-5 w-5" />
          )}
        </button>

        <button
          onClick={onDuplicate}
          className="p-3 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-xl transition-colors"
          title="تكرار المهمة"
        >
          <DocumentDuplicateIcon className="h-5 w-5" />
        </button>

        {canEdit && (
          <button
            onClick={onEdit}
            className="p-3 text-blue-600 hover:bg-blue-50 dark:text-blue-400 dark:hover:bg-blue-900/20 rounded-xl transition-colors"
            title="تعديل"
          >
            <PencilIcon className="h-5 w-5" />
          </button>
        )}

        {canDelete && (
          <button
            onClick={onDelete}
            className="p-3 text-red-600 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-900/20 rounded-xl transition-colors"
            title="حذف"
          >
            <TrashIcon className="h-5 w-5" />
          </button>
        )}
      </div>
    </div>
  );
};

export default TaskHeader;

import React, { useState, useEffect } from "react";
import {
  DocumentDuplicateIcon,
  LightBulbIcon,
  CheckBadgeIcon,
  PhotoIcon,
  CheckCircleIcon,
  LinkIcon,
  PlusIcon,
} from "@heroicons/react/24/outline";
import { Task } from "../../../types/tasks";
import tokenManager from "../../../utils/tokenManager";

interface TaskOverviewProps {
  task: Task;
  handleToggleItem?: (itemId: string, currentStatus: boolean) => void;
  handleAddItem?: (checklistId: string) => void;
  newItemInputs?: Record<string, string>;
  setNewItemInputs?: React.Dispatch<
    React.SetStateAction<Record<string, string>>
  >;
  settings?: any;
}

const TaskOverview: React.FC<TaskOverviewProps> = ({
  task,
  handleToggleItem,
  handleAddItem,
  newItemInputs,
  setNewItemInputs,
  settings,
}) => {
  const visibility = settings?.taskDetailsVisibility || {
    showDescription: true,
    showRelatedLinks: true,
    showChecklists: true,
    showBusinessValue: true,
    showAcceptanceCriteria: true,
    showAttachments: true,
    showCreatedAt: true,
  };

  const [imageBlobUrls, setImageBlobUrls] = useState<Record<string, string>>(
    {},
  );

  const imageAttachments =
    task.attachments?.filter((file: any) =>
      file.fileType?.startsWith("image/"),
    ) || [];

  // Parse acceptance criteria into checklist items
  const parseAcceptanceCriteria = (
    criteria: string | null | undefined,
  ): string[] => {
    if (!criteria) return [];

    // Split by newlines and filter out empty lines
    const lines = criteria
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line.length > 0);

    // Remove common prefixes like "- ", "* ", "• ", numbers, etc.
    return lines
      .map((line) => {
        return line
          .replace(/^[-*•]\s*/, "") // Remove bullet points
          .replace(/^\d+\.\s*/, "") // Remove numbered lists
          .replace(/^✓\s*/, "") // Remove checkmarks
          .replace(/^☐\s*/, "") // Remove empty checkboxes
          .replace(/^☑\s*/, "") // Remove filled checkboxes
          .trim();
      })
      .filter((line) => line.length > 0);
  };

  const acceptanceCriteriaItems = parseAcceptanceCriteria(
    task.acceptanceCriteria,
  );

  useEffect(() => {
    const loadImages = async () => {
      const token = tokenManager.getAccessToken();
      if (!token) return;

      const urls: Record<string, string> = {};

      for (const file of imageAttachments) {
        try {
          // استخدام file.fileUrl مباشرة من الـ API
          const imageUrl =
            file.fileUrl || `/uploads/dev-tasks/${file.fileName}`;
          const response = await fetch(imageUrl, {
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "application/json",
            },
          });

          if (response.ok) {
            const blob = await response.blob();
            urls[file.id] = URL.createObjectURL(blob);
          }
        } catch (error) {
          console.error("Error loading image:", error);
        }
      }

      setImageBlobUrls(urls);
    };

    if (imageAttachments.length > 0) {
      loadImages();
    }

    return () => {
      Object.values(imageBlobUrls).forEach((url) => URL.revokeObjectURL(url));
    };
  }, [task.id]);

  return (
    <div className="space-y-6">
      {/* Description */}
      {visibility.showDescription && (
        <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm">
          <h3 className="text-lg font-bold text-gray-900 dark:text-gray-100 mb-4 flex items-center gap-2">
            <DocumentDuplicateIcon className="h-5 w-5 text-indigo-500" />
            الوصف
          </h3>
          <div className="prose max-w-none text-gray-700 dark:text-gray-300 whitespace-pre-wrap leading-relaxed">
            {task.description}
          </div>
        </div>
      )}

      {/* Related Links */}
      {visibility.showRelatedLinks &&
        task.relatedLinks &&
        task.relatedLinks.length > 0 && (
          <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm">
            <h3 className="text-lg font-bold text-gray-900 dark:text-gray-100 mb-4 flex items-center gap-2">
              <LinkIcon className="h-5 w-5 text-indigo-500" />
              الروابط المرتبطة (Related Links)
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {task.relatedLinks.map((link, idx) => (
                <a
                  key={idx}
                  href={
                    link.url.startsWith("http")
                      ? link.url
                      : `https://${link.url}`
