/**
 * Smart Environment Configuration System
 */

interface EnvironmentConfig {
  apiUrl: string;
  wsUrl: string;
  appUrl: string;
  backendUrl: string;
  isDevelopment: boolean;
  isProduction: boolean;
  environment: "development" | "production";
  googleMapsApiKey: string;
}

/**
 * كشف البيئة الحالية بناءً على hostname
 */
const detectEnvironment = (): "development" | "production" => {
  const hostname = window.location.hostname;

  if (
    hostname === "localhost" ||
    hostname === "127.0.0.1" ||
    hostname === "0.0.0.0" ||
    hostname === "lvh.me" ||
    hostname.startsWith("192.168.") ||
    hostname.startsWith("10.") ||
    hostname.startsWith("172.") ||
    hostname.endsWith(".local") ||
    hostname.endsWith(".localhost") ||
    hostname.endsWith(".lvh.me") ||
    hostname.endsWith(".test")
  ) {
    return "development";
  }
  return "production";
};

/**
 * إنشاء إعدادات البيئة
 */
const createEnvironmentConfig = (): EnvironmentConfig => {
  const environment = detectEnvironment();
  const isDevelopment = environment === "development";
  const isProduction = environment === "production";

  // الرابط الأساسي من متغيرات البيئة أو تلقائياً
  const envApiUrl = (import.meta.env as any)["VITE_API_URL"];
  const envWsUrl = (import.meta.env as any)["VITE_WS_URL"];
  const envBackendUrl = (import.meta.env as any)["VITE_BACKEND_URL"];

  let apiUrl: string;
  let wsUrl: string;
  let appUrl: string;
  let backendUrl: string;

  if (isDevelopment) {
    // Use relative URLs to hit Vite proxy (configured in vite.config.ts)
    // This avoids CORS and CSP issues during development
    // The proxy will forward /api/v1/* to backend (localhost:3007)
    apiUrl = envApiUrl || "/api/v1";
    // For Socket.IO in development, always use the current origin so the client
    // connects through the Vite proxy instead of a stale hard-coded backend port.
    wsUrl = window.location.origin;
    backendUrl = envBackendUrl || window.location.origin;
    appUrl = window.location.origin;
  } else {
    const currentOrigin = window.location.origin;
    const isSecure = window.location.protocol === "https:";

    // استخدام النطاق الحالي ديناميكياً لتجنب مشاكل CORS
    apiUrl = envApiUrl || `${currentOrigin}/api/v1`;
    backendUrl =
      envBackendUrl ||
      (envApiUrl && envApiUrl.startsWith("http")
        ? envApiUrl.replace(/\/api(?:\/v1)?\/?$/, "")
        : currentOrigin);
    appUrl = currentOrigin;

    if (envWsUrl) {
      wsUrl = envWsUrl;
    } else {
      const wsHost = window.location.host;
      wsUrl = isSecure ? `wss://${wsHost}` : `ws://${wsHost}`;
    }
  }

  return {
    apiUrl,
    wsUrl,
    appUrl,
    backendUrl,
    isDevelopment,
    isProduction,
    environment,
    googleMapsApiKey:
      ((import.meta.env as any)["VITE_GOOGLE_MAPS_API_KEY"] as string) || "",
  };
};

// إنشاء إعدادات البيئة
export const envConfig = createEnvironmentConfig();
if (import.meta.env.DEV || import.meta.env.MODE === "development") {
