export type ShippingClassOption = {
  key: string;
  label: string;
};

export const DEFAULT_SHIPPING_CLASS_FEES: Record<string, number> = {
  standard: 0,
  heavy: 20,
  fragile: 10,
  express: 30,
};

export const DEFAULT_SHIPPING_CLASSES: ShippingClassOption[] = [
  { key: "standard", label: "عادي" },
  { key: "heavy", label: "ثقيل" },
  { key: "fragile", label: "قابل للكسر" },
  { key: "express", label: "سريع" },
];

export const normalizeShippingClassKey = (value?: string | null): string => {
  if (value === null || value === undefined) return "";
  return String(value).trim().toLowerCase();
};

const normalizeShippingClassLabel = (value: any, fallback: string): string => {
  const label = value === null || value === undefined ? "" : String(value).trim();
  return label || fallback;
};

export const normalizeFeesMap = (
  fees?: Record<string, any>,
): Record<string, number> => {
  if (!fees || typeof fees !== "object") return {};
  return Object.entries(fees).reduce<Record<string, number>>(
    (acc, [key, value]) => {
      const normalizedKey = normalizeShippingClassKey(key);
      if (!normalizedKey) return acc;
      acc[normalizedKey] = Number(value) || 0;
      return acc;
    },
    {},
  );
};

export const mergeShippingClasses = (stored?: any): ShippingClassOption[] => {
  const map = new Map<string, ShippingClassOption>();

  DEFAULT_SHIPPING_CLASSES.forEach((option) => {
    const key = normalizeShippingClassKey(option.key);
    if (!key) return;
    map.set(key, { key, label: option.label });
  });

  const addClass = (rawKey: any, rawLabel: any) => {
    const key = normalizeShippingClassKey(rawKey);
    if (!key) return;
    const existing = map.get(key);
    const label = normalizeShippingClassLabel(rawLabel, existing?.label || key);
    map.set(key, { key, label });
  };

  if (Array.isArray(stored)) {
    stored.forEach((item) => {
      if (!item) return;
      if (typeof item === "string") {
        addClass(item, item);
        return;
      }
      if (typeof item === "object") {
        addClass(
          item.key ?? item.slug ?? item.value ?? item.id ?? item.name ?? item.label,
          item.label ?? item.name ?? item.key ?? item.value,
        );
      }
    });
  }

  return Array.from(map.values());
};

export const ensureShippingClassesForKeys = (
  classes: ShippingClassOption[],
  keys?: string[],
): ShippingClassOption[] => {
  if (!Array.isArray(keys) || keys.length === 0) return classes;
  const existing = new Set(
    classes.map((option) => normalizeShippingClassKey(option.key)),
  );

  let next = [...classes];
  keys.forEach((key) => {
    const normalized = normalizeShippingClassKey(key);
    if (!normalized || existing.has(normalized)) return;
    existing.add(normalized);
    next = [
      ...next,
      {
        key: normalized,
        label: normalizeShippingClassLabel(key, normalized),
      },
    ];
  });

  return next;
};

export const buildDefaultClassFees = (
  classes?: ShippingClassOption[],
): Record<string, number> => {
  const base = { ...DEFAULT_SHIPPING_CLASS_FEES };
  const list = classes && classes.length > 0 ? classes : DEFAULT_SHIPPING_CLASSES;
  list.forEach((option) => {
    const key = normalizeShippingClassKey(option.key);
    if (!key) return;
    if (!(key in base)) {
      base[key] = 0;
    }
  });
  return base;
};

import React, {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
  useCallback,
} from "react";
import { useAuth } from "../hooks/useAuthSimple";
import api from "../services/api";

interface Company {
  id: string;
  name: string;
  email: string;
  plan: string;
  currency: string;
  isActive: boolean;
  settings?: any;
}

interface CompanyContextType {
  company: Company | null;
  companyId: string | null;
  isCompanyLoading: boolean;
  companyError: string | null;
  refreshCompany: (bypassCache?: boolean) => Promise<void>;

  // Helper functions for company-specific operations
  isOwnCompany: (companyId: string) => boolean;
  canAccessCompany: (companyId: string) => boolean;
  getCompanyFilter: () => { companyId: string } | {};
}

const CompanyContext = createContext<CompanyContextType | undefined>(undefined);

export const CompanyProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user, isAuthenticated } = useAuth();
  const [company, setCompany] = useState<Company | null>(null);
  const [isCompanyLoading, setIsCompanyLoading] = useState(false);
  const [companyError, setCompanyError] = useState<string | null>(null);

  const companyId = user?.companyId || null;

  // Fetch company data
  const fetchCompany = useCallback(async (bypassCache = false) => {
    if (!isAuthenticated || !companyId) {
      setCompany(null);
      setCompanyError(null);
      return;
    }

    try {
      setIsCompanyLoading(true);
      setCompanyError(null);

      const requestConfig = bypassCache
        ? { params: { _ts: Date.now() }, _skipErrorToast: true }
        : { _skipErrorToast: true };

      const response = await api.get(
        "companies/current",
        requestConfig,
      );

      if (response.data && response.data.success) {
        setCompany(response.data.data);
      } else {
        throw new Error(response.data?.message || "فشل في تحميل بيانات الشركة");
      }
    } catch (error: any) {
      console.error("Error fetching company:", error);
      setCompanyError(error.message || "فشل في تحميل بيانات الشركة");
    } finally {
      setIsCompanyLoading(false);
    }
  }, [companyId, isAuthenticated]);

  // Load company data when user changes
  useEffect(() => {
    void fetchCompany();
  }, [fetchCompany]);

  // Listen for company switch events
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === "companySwitchTimestamp") {
        void fetchCompany(true);
      }
    };

    const handleCompanySwitched = () => {
      void fetchCompany(true);
    };

    window.addEventListener("storage", handleStorageChange);
    window.addEventListener("company:switched", handleCompanySwitched);
    return () => {
      window.removeEventListener("storage", handleStorageChange);
      window.removeEventListener("company:switched", handleCompanySwitched);
    };
  }, [fetchCompany]);

  // Helper functions
  const isOwnCompany = (targetCompanyId: string): boolean => {
    return companyId === targetCompanyId;
  };

  const canAccessCompany = (targetCompanyId: string): boolean => {
    // Super admin can access all companies
    if (user?.role === "SUPER_ADMIN") {
      return true;
    }

    // Regular users can only access their own company
    return isOwnCompany(targetCompanyId);
  };

  const getCompanyFilter = () => {
    // Super admin gets no filter (can see all)
    if (user?.role === "SUPER_ADMIN") {
      return {};
    }

    // Regular users get company filter
    return companyId ? { companyId } : {};
  };

  const refreshCompany = async (bypassCache = false) => {
    await fetchCompany(bypassCache);
  };

  const value: CompanyContextType = {
    company,
    companyId,
    isCompanyLoading,
    companyError,
    refreshCompany,
    isOwnCompany,
    canAccessCompany,
    getCompanyFilter,
  };

  return (
    <CompanyContext.Provider value={value}>{children}</CompanyContext.Provider>
  );
};

export const useCompany = (): CompanyContextType => {
  const context = useContext(CompanyContext);
  if (!context) {
    throw new Error("useCompany must be used within a CompanyProvider");
  }
  return context;
};

// HOC for company-protected components
export const withCompanyProtection = <P extends object>(
  Component: React.ComponentType<P>,
) => {
  return (props: P) => {
    const { company, isCompanyLoading, companyError } = useCompany();

    if (isCompanyLoading) {
      return (
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
            <p className="mt-4 text-gray-600">جاري تحميل بيانات الشركة...</p>
          </div>
        </div>
      );
    }

    if (companyError) {
      return (
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <div className="bg-red-50 border border-red-200 rounded-lg p-6 max-w-md">
              <h3 className="text-red-800 font-semibold mb-2">
                ❌ خطأ في تحميل الشركة
              </h3>
              <p className="text-red-700 mb-4">{companyError}</p>
              <button
                onClick={() => window.location.reload()}
                className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700"
              >
                إعادة المحاولة
              </button>
            </div>
          </div>
        </div>
      );
    }

    if (!company) {
      return (
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6 max-w-md">
              <h3 className="text-yellow-800 font-semibold mb-2">
                ⚠️ لا توجد شركة
              </h3>
              <p className="text-yellow-700 mb-4">
                لم يتم العثور على بيانات الشركة
              </p>
            </div>
          </div>
        </div>
      );
    }

    return <Component {...props} />;
  };
};

export default CompanyContext;

import React, { createContext, useContext, useEffect, useState, ReactNode } from "react";
import { detectUserGovernorate } from "../utils/geolocation";
import { Governorate } from "../constants/egyptGovernorates";
import { getCompanyId } from "../utils/storefrontApi";
import { checkoutFormSettingsService } from "../services/checkoutFormSettingsService";

interface GeolocationContextType {
  detectedGovernorate: Governorate | null;
  loading: boolean;
  refreshLocation: () => Promise<void>;
}

const GeolocationContext = createContext<GeolocationContextType | undefined>(undefined);

export const GeolocationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [detectedGovernorate, setDetectedGovernorate] = useState<Governorate | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchLocation = async () => {
    try {
      setLoading(true);

      // 1. Check if city detection is enabled in settings
      const companyId = getCompanyId();
      if (companyId) {
        const settingsResponse = await checkoutFormSettingsService.getPublicSettings(companyId);
        if (settingsResponse?.success && settingsResponse.data && !settingsResponse.data.showCity) {
          setDetectedGovernorate(null);
          return;
        }
      }

      // 2. Detect location
      const gov = await detectUserGovernorate();
      setDetectedGovernorate(gov);
    } catch (error) {
      console.error("Error in GeolocationProvider:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void fetchLocation();
  }, []);

  return (
    <GeolocationContext.Provider value={{ detectedGovernorate, loading, refreshLocation: fetchLocation }}>
      {children}
    </GeolocationContext.Provider>
  );
};

export const useGeolocation = () => {
  const context = useContext(GeolocationContext);
  if (context === undefined) {
    throw new Error("useGeolocation must be used within a GeolocationProvider");
  }
  return context;
};

