  });

  const [elapsedSeconds, setElapsedSeconds] = useState(0);

  const checkActiveTimer = useCallback(async () => {
    const token = getAccessToken();
    if (!token) return;
    if (!window.location.pathname.startsWith("/super-admin")) return;

    // Only Super Admins can access the dev timer
    try {
      const base64Url = token.split(".")[1];
      if (!base64Url) return;
      const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
      const payload = JSON.parse(atob(base64));
      if (payload.role !== "SUPER_ADMIN") return;
    } catch (e) {
      return;
    }

    try {
      const response = await fetch(
        buildApiUrl("super-admin/dev/timer/active"),
        {
          headers: { Authorization: `Bearer ${token}` },
        },
      );
      if (response.ok) {
        const data = await response.json();
        if (data.success && data.data) {
          const timerData = data.data;
          setActiveTimer({
            taskId: timerData.taskId,
            startTime: new Date(timerData.startTime).getTime(),
            isRunning: !timerData.isPaused,
            isPaused: timerData.isPaused,
            taskTitle: timerData.taskTitle,
            projectId: null,
            projectName: timerData.projectName,
          });
        } else {
          setActiveTimer({
            taskId: null,
            startTime: null,
            isRunning: false,
            isPaused: false,
            taskTitle: null,
            projectId: null,
            projectName: null,
          });
        }
      }
    } catch (err) {
      console.error("Failed to sync timer:", err);
    }
  }, []);

  // Check for active timer on mount (only once)
  useEffect(() => {
    checkActiveTimer();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Run only once on mount to avoid infinite loops

  // Sync with localStorage (backup)
  useEffect(() => {
    if (activeTimer.taskId) {
      localStorage.setItem("timer_taskId", activeTimer.taskId);
      localStorage.setItem(
        "timer_startTime",
        activeTimer.startTime?.toString() || "",
      );
      localStorage.setItem("timer_isRunning", String(activeTimer.isRunning));
      localStorage.setItem("timer_isPaused", String(activeTimer.isPaused));
      localStorage.setItem("timer_taskTitle", activeTimer.taskTitle || "");
      localStorage.setItem("timer_projectName", activeTimer.projectName || "");
    } else {
      localStorage.removeItem("timer_taskId");
      localStorage.removeItem("timer_startTime");
      localStorage.removeItem("timer_isRunning");
      localStorage.removeItem("timer_isPaused");
      localStorage.removeItem("timer_taskTitle");
      localStorage.removeItem("timer_projectName");
    }
  }, [activeTimer]);

  // Tick effect - optimized with Page Visibility API
  useEffect(() => {
    // Early return if timer is not running
    if (
      !activeTimer.isRunning ||
      activeTimer.isPaused ||
      !activeTimer.startTime
    ) {
      setElapsedSeconds(0);
      return;
    }

    const updateElapsed = () => {
      // Don't update when tab is hidden to save resources
      if (document.hidden) return;

      const now = Date.now();
      const diff = Math.floor((now - activeTimer.startTime!) / 1000);
      setElapsedSeconds(diff > 0 ? diff : 0);
    };

    // Immediate update
    updateElapsed();

    // Update every second
    const interval = setInterval(updateElapsed, 1000);

    // Update when tab becomes visible again
    const handleVisibilityChange = () => {
      if (!document.hidden) {
        updateElapsed();
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      clearInterval(interval);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [activeTimer.isRunning, activeTimer.isPaused, activeTimer.startTime]);

  const showToast = (message: string, type: "success" | "error") => {
    const event = new CustomEvent("show-toast", { detail: { message, type } });
    window.dispatchEvent(event);
    if (type === "error") console.error(message);
  };

  const startTimer = useCallback(
    async (taskId: string, taskTitle: string, projectName?: string) => {
      try {
        const token = getAccessToken();
        if (!token) return;

        // Role check
        try {
          const base64Url = token.split(".")[1];
          if (!base64Url) return;
          const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
          const payload = JSON.parse(atob(base64));
          if (payload.role !== "SUPER_ADMIN") {
            showToast("غير مسموح لهذه العملية إلا للمشرفين", "error");
            return;
          }
        } catch (e) {
          return;
        }

        const response = await fetch(
          buildApiUrl(`super-admin/dev/tasks/${taskId}/timer/start`),
          {
            method: "POST",
            headers: { Authorization: `Bearer ${token}` },
          },
        );

        if (response.ok) {
          setActiveTimer({
            taskId,
            startTime: Date.now(),
            isRunning: true,
            isPaused: false,
            taskTitle,
            projectId: null,
            projectName: projectName || null,
          });
        } else {
          const data = await response.json();
          showToast(data.message || "فشل بدء المؤقت", "error");
        }
      } catch (err) {
        showToast("حدث خطأ في الاتصال", "error");
      }
    },
    [],
  );

  const stopTimer = useCallback(
    async (taskId: string) => {
      try {
        const token = getAccessToken();
        if (!token) return;

        const response = await fetch(
          buildApiUrl(`super-admin/dev/tasks/${taskId}/timer/stop`),
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ description: "" }),
          },
        );

        if (response.ok) {
          // Determine if we should clear or fetch next
          // Optimistically clear first
          setActiveTimer({
            taskId: null,
            startTime: null,
            isRunning: false,
            isPaused: false,
            taskTitle: null,
            projectId: null,
            projectName: null,
          });
          setElapsedSeconds(0);

          // Then check if another timer exists (drain queue)
          await checkActiveTimer();
        } else {
          showToast("فشل إيقاف المؤقت", "error");
        }
      } catch (err) {
        showToast("حدث خطأ في الاتصال", "error");
      }
    },
    [checkActiveTimer],
  );

  const pauseTimer = useCallback(async (taskId: string) => {
    try {
      const token = getAccessToken();
      if (!token) return;

      const response = await fetch(
        buildApiUrl(`super-admin/dev/tasks/${taskId}/timer/pause`),
        {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
        },
      );

      if (response.ok) {
        setActiveTimer((prev) => ({ ...prev, isPaused: true }));
      }
    } catch (err) {
      showToast("حدث خطأ", "error");
    }
  }, []);

  const resumeTimer = useCallback(async (taskId: string) => {
    try {
      const token = getAccessToken();
      if (!token) return;

      const response = await fetch(
        buildApiUrl(`super-admin/dev/tasks/${taskId}/timer/resume`),
        {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
        },
      );

      if (response.ok) {
        // When resuming, we effectively reset the start time to now minus previously elapsed?
        // Actually, the simple backend logic starts a NEW log segment.
        // So for the UI to be consistent, we treat it as a new start time relative to this session.
        // However, this simple start time logic resets the counter to 0!
        // To accurately reflect TOTAL time for the task, we should probably fetch the total duration from backend.
        // For now, let's treat resume normally (starts counting from 0 for this session or continues?)
        // If we want "total elapsed", we need more complex logic.
        // Let's assume Resume starts a new segment, so user sees time for *current session*.

        setActiveTimer((prev) => ({
          ...prev,
          isPaused: false,
          startTime: Date.now(), // Reset start time for new segment display
        }));
      }
    } catch (err) {
      showToast("حدث خطأ", "error");
    }
  }, []);

  const syncTimerState = useCallback(async () => {
    // Optional: Fetch current status from backend to handle multi-tab/device
    // Implement if needed for robustness
  }, []);

  return (
    <TimerContext.Provider
      value={{
        activeTimer,
        elapsedSeconds,
        startTimer,
        stopTimer,
        pauseTimer,
        resumeTimer,
        syncTimerState,
      }}
    >
      {children}
    </TimerContext.Provider>
  );
};

export const useTimer = () => {
  const context = useContext(TimerContext);
  if (context === undefined) {
    throw new Error("useTimer must be used within a TimerProvider");
  }
  return context;
};

import React, {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import {
  BUSINESS_THEME_ID,
  themes,
  type VisualThemeOption,
} from "../config/themes";

type VisualThemeContextValue = {
  currentTheme: VisualThemeOption;
  setTheme: (theme: string) => void;
};

const STORAGE_KEY = "visual-theme";

const normalizeThemeId = (theme: string | null | undefined): string => {
  if (!theme) {
    return BUSINESS_THEME_ID;
  }

  return themes.some((option) => option.id === theme)
    ? theme
    : BUSINESS_THEME_ID;
};

const VisualThemeContext = createContext<VisualThemeContextValue>({
  currentTheme: themes[0],
  setTheme: () => {},
});

export const VisualThemeProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [currentTheme, setCurrentTheme] = useState<string>(() => {
    if (typeof window === "undefined") return BUSINESS_THEME_ID;
    return normalizeThemeId(window.localStorage.getItem(STORAGE_KEY));
  });

  useEffect(() => {
    if (typeof document === "undefined") return;
    const normalizedTheme = normalizeThemeId(currentTheme);
    document.documentElement.setAttribute("data-visual-theme", normalizedTheme);
    if (typeof window !== "undefined") {
      window.localStorage.setItem(STORAGE_KEY, normalizedTheme);
    }
  }, [currentTheme]);

  const value = useMemo(
    () => ({
      currentTheme:
        themes.find((theme) => theme.id === normalizeThemeId(currentTheme)) ||
        themes[0],
      setTheme: (theme: string) => setCurrentTheme(normalizeThemeId(theme)),
    }),
    [currentTheme],
  );

  return (
    <VisualThemeContext.Provider value={value}>
      {children}
    </VisualThemeContext.Provider>
  );
};

export const useVisualTheme = (): VisualThemeContextValue => {
  return useContext(VisualThemeContext);
};

export default VisualThemeContext;

import { useCallback, useState } from "react";
import { apiClient } from "../../services/apiClient";
import { ConversationStatus } from "../../types/inbox.types";

export const useConversationActions = () => {
  const [updating, setUpdating] = useState(false);

  // Update conversation status
  const updateStatus = useCallback(
    async (
      conversationId: string,
      status: ConversationStatus,
      companyId: string,
    ) => {
      try {
        setUpdating(true);

        await apiClient.put(`/conversations/${conversationId}`, {
          status,
          companyId,
        });

        return true;
      } catch (error: any) {
        console.error("❌ Error updating status:", error);
        throw new Error(error.message || "فشل في تحديث الحالة");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Assign conversation to user
  const assignConversation = useCallback(
    async (
      conversationId: string,
      userId: string | null,
      companyId: string,
    ) => {
      try {
        setUpdating(true);

        await apiClient.put(`/conversations/${conversationId}`, {
          assignedTo: userId,
          companyId,
        });

        return true;
      } catch (error: any) {
        console.error("❌ Error assigning conversation:", error);
        throw new Error(error.message || "فشل في تعيين المحادثة");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Mark conversation as done
  const markAsDone = useCallback(
    async (conversationId: string, companyId: string) => {
      try {
        setUpdating(true);

        await apiClient.put(`/conversations/${conversationId}`, {
          status: "done",
          tab: "done",
          companyId,
        });

        return true;
      } catch (error: any) {
        console.error("❌ Error marking as done:", error);
        throw new Error(error.message || "فشل في تحديث المحادثة");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Toggle priority/star
  const togglePriority = useCallback(
    async (conversationId: string, priority: boolean, companyId: string) => {
      try {
        setUpdating(true);

        await apiClient.put(`/conversations/${conversationId}`, {
          priority,
          companyId,
        });

        return true;
      } catch (error: any) {
        console.error("❌ Error toggling priority:", error);
        throw new Error(error.message || "فشل في تحديث الأولوية");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Bulk update
  const bulkUpdate = useCallback(
    async (
      conversationIds: string[],
      action: string,
      value: any,
      _companyId?: string,
    ) => {
      try {
        setUpdating(true);

        // Build updates object based on action
        const updates: Record<string, any> = {};
        updates[action] = value;

        const response = await apiClient.put("/conversations/bulk-update", {
          conversationIds,
          updates,
        });

        return response.data;
      } catch (error: any) {
        console.error("❌ Error in bulk update:", error);
        throw new Error(error.message || "فشل في تحديث المحادثات");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Delete message
  const deleteMessage = useCallback(
    async (conversationId: string, messageId: string) => {
      try {
        setUpdating(true);
        await apiClient.delete(
          `/conversations/${conversationId}/messages/${messageId}`,
        );
        return true;
      } catch (error: any) {
        console.error("❌ Error deleting message:", error);
        throw new Error(error.message || "فشل في حذف الرسالة");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Forward message
  const forwardMessage = useCallback(
    async (
      targetConversationId: string,
      message: {
        content: string;
        type: string;
        fileUrl?: string;
        fileName?: string;
      },
      companyId: string,
    ) => {
      try {
        setUpdating(true);

        if (
          (message.type === "image" || message.type === "IMAGE") &&
          message.fileUrl
        ) {
          // Forward image using send-existing-image
          await apiClient.post(
            `/conversations/${targetConversationId}/send-existing-image`,
            {
              imageUrl: message.fileUrl,
              filename: message.fileName || "forwarded_image.jpg",
              companyId,
            },
          );
        } else {
          // Forward text
          // Check if it has content, if not (e.g. file without specific handler), send placeholder
          const contentToSend =
            message.content ||
            (message.fileUrl
              ? `File: ${message.fileUrl}`
              : "Forwarded message");

          await apiClient.post(
            `/conversations/${targetConversationId}/messages`,
            {
              message: contentToSend,
              companyId,
            },
          );
        }
        return true;
      } catch (error: any) {
        console.error("❌ Error forwarding message:", error);
        throw new Error(error.message || "فشل في إعادة توجيه الرسالة");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Toggle message star
  const toggleMessageStar = useCallback(
    async (conversationId: string, messageId: string) => {
      try {
        // Note: Optimistic update should be handled in the UI
        const response = await apiClient.put(
          `/conversations/${conversationId}/messages/${messageId}/star`,
        );
        return response.data.data.isStarred;
      } catch (error: any) {
        console.error("❌ Error starring message:", error);
        throw new Error(error.message || "فشل في تمييز الرسالة");
      }
    },
    [],
  );

  // Toggle message reaction
  const toggleMessageReaction = useCallback(
    async (conversationId: string, messageId: string, reaction: string) => {
      try {
        const response = await apiClient.put(
          `/conversations/${conversationId}/messages/${messageId}/reaction`,
          { reaction },
        );
        return response.data;
      } catch (error: any) {
        console.error("❌ Error updating reaction:", error);
        throw new Error(error.message || "فشل في تحديث التفاعل");
      }
    },
    [],
  );

  const snoozeConversation = useCallback(
    async (conversationId: string, until: Date, companyId: string) => {
      setUpdating(true);
      try {
        await apiClient.post(`/conversations/${conversationId}/snooze`, {
          snoozeUntil: until.toISOString(),
        });
      } catch (error) {
        console.error("Error snoozing conversation:", error);
        throw error;
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  const toggleAI = useCallback(
    async (conversationId: string, aiEnabled: boolean) => {
      setUpdating(true);
      try {
        const response = await apiClient.patch(
          `/conversations/${conversationId}/ai-toggle`,
          {
            aiEnabled,
          },
        );
        return response.data;
      } catch (error) {
        console.error("Error toggling AI:", error);
        throw error;
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  return {
    updateStatus,
    assignConversation,
    markAsDone,
    togglePriority,
    bulkUpdate,
    deleteMessage,
    forwardMessage,
    toggleMessageStar,
    toggleMessageReaction,

    snoozeConversation,
    toggleAI,
    updating,
  };
};

import { useState, useCallback } from "react";
import { useCompany } from "../../contexts/CompanyContext";
import { apiClient } from "../../services/apiClient";

interface OrderItem {
  name: string;
  quantity: number;
  price: number;
  image: string | null;
}

interface Order {
  id: string;
  orderNumber: string;
  status: string;
  total: number;
  createdAt: string;
  items: OrderItem[];
}

interface Activity {
  id: string;
  action: string;
  description: string;
  createdAt: string;
  metadata?: string;
}

interface Customer {
  id: string;
  firstName: string;
  lastName: string;
  email: string | null;
  phone: string | null;
  avatar: string | null;
  city: string | null;
  country: string | null;
}

export const useCustomerProfile = () => {
  const { companyId } = useCompany();
  const [orders, setOrders] = useState<Order[]>([]);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadCustomerData = useCallback(
    async (customerId: string) => {
      if (!customerId || !companyId) return;

      setLoading(true);
      setError(null);

      try {
        // Concurrent fetching
        const [ordersRes, activityRes, customerRes] = await Promise.all([
          apiClient.get(
            `/customers/${customerId}/orders?companyId=${companyId}`,
          ),
          apiClient.get(
            `/customers/${customerId}/activity?companyId=${companyId}`,
          ),
          apiClient.get(`/customers/${customerId}?companyId=${companyId}`),
        ]);

        setOrders(ordersRes.data.data || []);
        if (customerRes.data.success) {
          setCustomer(customerRes.data.data);
        }

        // Map backend activity format to frontend interface
        const rawActivities = activityRes.data.data || [];
        const mappedActivities = rawActivities.map((act: any) => ({
          id: act.id,
          action: act.type,
          description:
            act.type === "order"
              ? `طلب جديد #${act.orderNumber} (${act.total} ر.س)`
              : `محادثة عبر ${act.platform === "WHATSAPP" ? "واتساب" : act.platform === "MESSENGER" ? "ماسنجر" : act.platform || "المنصة"}`,
          createdAt: act.timestamp || new Date().toISOString(),
          metadata: JSON.stringify(act.data),
        }));
        setActivities(mappedActivities);
      } catch (err: any) {
        console.error("Error fetching customer profile:", err);
        setError("فشل جلب بيانات العميل");
      } finally {
        setLoading(false);
      }
    },
    [companyId],
  );

  const calculateLTV = useCallback(() => {
    return orders
      .filter(
        (o) =>
          o.status === "completed" ||
          o.status === "delivered" ||
          o.status === "paid",
      )
      .reduce((sum, order) => sum + order.total, 0);
  }, [orders]);

  return {
    customer,
    orders,
    activities,
    loading,
    error,
    loadCustomerData,
    calculateLTV,
  };
};

import { useState, useEffect, useCallback, useRef } from "react";
import { useAuth } from "../useAuthSimple";
import { useCompany } from "../../contexts/CompanyContext";
import { apiClient } from "../../services/apiClient";
import { InboxConversation, InboxTab } from "../../types/inbox.types";
import { parseInboxConversationMetadata } from "../../utils/inboxConversationMetadata";

export interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type:
    | "text"
    | "image"
    | "file"
    | "video"
    | "audio"
    | "template"
    | "IMAGE"
    | "FILE"
    | "VIDEO"
    | "AUDIO"
    | "TEMPLATE";
  isFromCustomer: boolean;
  status: "sending" | "sent" | "delivered" | "read" | "error";
  conversationId: string;
  fileUrl?: string;
  fileName?: string;
  fileSize?: number;
  isAiGenerated?: boolean;
  metadata?: any;
  attachments?: any[];
}

// Helper to safely parse dates
const safeDate = (date: any): Date => {
  if (!date) return new Date();
  try {
    const parsed = new Date(date);
    if (isNaN(parsed.getTime())) {
      return new Date();
    }
    return parsed;
  } catch (e) {
    return new Date();
  }
};

const serializeConversationMetadata = (metadata: unknown): string => {
  try {
    return JSON.stringify(metadata ?? null);
  } catch (_error) {
    return "";
  }
};

// Helper to parse messages (unified logic)
const parseMessage = (msg: any): Message => {
  let isAiGenerated = false;
  let md: any = null;

  if (msg.metadata) {
    try {
      md =
        typeof msg.metadata === "string"
          ? JSON.parse(msg.metadata)
          : msg.metadata;
      isAiGenerated =
        md.isAIGenerated ||
        md.isAutoGenerated ||
        md.source === "ai_agent" ||
        false;
    } catch (e) {
      // Failed to parse metadata, continue with default values
    }
  }

  // Determine sender name
  let senderName = "العميل";
  if (!msg.isFromCustomer) {
    if (isAiGenerated) {
      senderName = "الذكاء الاصطناعي";
    } else if (md?.employeeName) {
      senderName = md.employeeName;
    } else if (msg.sender?.name && msg.sender.name !== "موظف") {
      senderName = msg.sender.name;
    } else {
      senderName = "موظف";
    }
  }

  // Parse attachments if string
  let attachments = msg.attachments;
  if (typeof attachments === "string") {
    try {
      attachments = JSON.parse(attachments);
    } catch (e) {
      attachments = [];
    }
  }

  const msgType = msg.type || "text";
  const isMedia = [
    "image",
    "file",
    "video",
    "audio",
    "IMAGE",
    "FILE",
    "VIDEO",
    "AUDIO",
  ].includes(msgType);

  return {
    id: msg.id,
    content: msg.content,
    senderId: msg.sender?.id || msg.senderId || "unknown",
    senderName,
    timestamp: safeDate(msg.timestamp || msg.createdAt),
    type: msgType,
    isFromCustomer: msg.isFromCustomer,
    status: "delivered", // Default to delivered for history
    conversationId: msg.conversationId,
    fileUrl: msg.fileUrl || (isMedia ? msg.content : undefined),
    fileName: msg.fileName,
    fileSize: msg.fileSize,
    isAiGenerated,
    metadata: md,
    attachments: attachments,
  };
};

export const useInboxConversations = () => {
  const { user: _user } = useAuth();
  const { companyId } = useCompany();

  const [conversations, setConversations] = useState<InboxConversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<InboxConversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMessages, setLoadingMessages] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [messagesPage, setMessagesPage] = useState(1);
  const [hasMoreMessages, setHasMoreMessages] = useState(false);

  // Conversations pagination & filtering
  const [conversationsPage, setConversationsPage] = useState(1);
  const [hasMoreConversations, setHasMoreConversations] = useState(false);

  // Track current tab for pagination to work correctly
  const currentTabRef = useRef<string>("all");

  const currentConversationIdRef = useRef<string | null>(null);

  // Store counts from API
  const [apiCounts, setApiCounts] = useState<{
    total: number;
    unreplied: number;
  }>({ total: 0, unreplied: 0 });

  // Load conversations
  const loadConversations = useCallback(
    async (
      pageNum = 1,
      append = false,
      tab: string = "all",
      search?: string,
    ) => {
      if (!companyId) return;

      try {
        if (pageNum === 1) {
          setLoading(true);
          currentTabRef.current = tab; // Update current tab
        }
        setError(null);

        const response = await apiClient.get(`conversations`, {
          params: {
            companyId,
            limit: tab === "unreplied" ? 1000 : 50, // Fetch all unreplied conversations, limit others for performance
            page: pageNum,
            tab: tab,
            ...(search && search.trim() ? { search: search.trim() } : {}), // 🆕 Add search parameter
          },
        });

        const result = response.data || {};
        const data = result.data || result || [];
        const pagination = result.pagination || {};
        const counts = result.counts || {};

        // Update API counts
        if (counts.total !== undefined || counts.unreplied !== undefined) {
          setApiCounts((prev) => ({
            total: counts.total ?? prev.total,
            unreplied: counts.unreplied ?? prev.unreplied,
          }));
        }

        // Check for more conversations
        setHasMoreConversations(
          pagination.hasNextPage || pagination.hasMore || false,
        );
        setConversationsPage(pageNum);

        const formattedConversations: InboxConversation[] = data.map(
          (conv: any) => {
            const metadata = parseInboxConversationMetadata(conv.metadata);
            // Determine tab logic moved to backend ideally, mapping here for safety
            // ... logic to determine tab ...
            let currentTab: InboxTab = "all";
            const status = (conv.status || "active").toLowerCase();

            if (status === "resolved" || status === "done") {
              currentTab = "done";
            } else if (
              status === "active" ||
              status === "open" ||
              status === "pending"
            ) {
              const metadataTab = metadata?.tab || metadata?.inboxTab;
              if (
                metadataTab &&
                ["main", "general", "requests", "spam"].includes(metadataTab)
              ) {
                currentTab = metadataTab as InboxTab;
              } else {
                currentTab = "main";
              }
            }

            return {
              id: conv.id,
              customerId: conv.customerId,
              customerName: conv.customer?.name || conv.customerName || "عميل",
              customerAvatar: conv.customer?.avatar || conv.customerAvatar,
              lastMessage: conv.lastMessage || "لا توجد رسائل",
              lastMessageTime: safeDate(conv.lastMessageTime || conv.updatedAt),
              unreadCount: conv.unreadCount || 0,
              platform: "facebook" as const,
              tab: currentTab,
              status:
                status === "resolved" || status === "done"
                  ? "done"
                  : status === "pending"
                    ? "pending"
                    : "open",
              assignedTo: conv.assignedTo || null,
              assignedToName: conv.assignedToName || null,
              tags: conv.tags || [],
              priority: conv.priority || false,
              snoozedUntil: conv.snoozedUntil
                ? safeDate(conv.snoozedUntil)
                : null,
              archived: conv.archived || false,
              muted: conv.muted || false,
              lastStatusChange: safeDate(
                conv.lastStatusChange || conv.updatedAt,
              ),
              firstResponseTime: conv.firstResponseTime || null,
              avgResponseTime: conv.avgResponseTime || null,
              pageName: conv.pageName,
              pageId: conv.pageId,
              metadata,
              aiEnabled: (() => {
                if (
                  conv.hasOwnProperty("aiEnabled") &&
                  conv.aiEnabled !== undefined
                )
                  return conv.aiEnabled;
                if (metadata) {
                  return metadata.aiEnabled !== false;
                }
                return true;
              })(),
              lastMessageIsFromCustomer: conv.lastMessageIsFromCustomer,
              hasUnreadMessages: conv.hasUnreadMessages,
              postId: (() => {
                if (conv.postId) return conv.postId;
                if (metadata?.postId) return metadata.postId;
                return null;
              })(),
              postDetails: null,
            };
          },
        );

        // Deduplicate
        const conversationsMap = new Map<string, InboxConversation>();
        formattedConversations.forEach((conv) => {
          conversationsMap.set(conv.id, conv);
        });
        const deduplicatedConversations = Array.from(conversationsMap.values());

        if (append && pageNum > 1) {
          setConversations((prev) => {
            const existingIds = new Set(prev.map((c) => c.id));
            const newConversations = deduplicatedConversations.filter(
              (c) => !existingIds.has(c.id),
            );
            return [...prev, ...newConversations];
          });
        } else {
          setConversations(deduplicatedConversations); // Replace entirely for new page or tab switch
        }
      } catch (err: any) {
        console.error("❌ Error loading conversations:", err);
        setError(err.message || "فشل في تحميل المحادثات");
      } finally {
        if (pageNum === 1) {
          setLoading(false);
        }
      }
    },
    [companyId],
  );

  // Load more conversations - now uses currentTabRef to ensure correct pagination
  const loadMoreConversations = useCallback(() => {
    if (hasMoreConversations && !loading) {
      loadConversations(conversationsPage + 1, true, currentTabRef.current);
    }
  }, [hasMoreConversations, loading, conversationsPage, loadConversations]);

  // Load messages for a conversation
  const loadMessages = useCallback(
    async (conversationId: string, pageNum = 1) => {
      if (!conversationId || !companyId) return;

      if (pageNum === 1) {
        currentConversationIdRef.current = conversationId;
        setMessages([]);
      } else if (currentConversationIdRef.current !== conversationId) {
        return;
      }

      try {
        setLoadingMessages(true);

        const response = await apiClient.get(
          `/conversations/${conversationId}/messages`,
          {
            params: {
              companyId,
              page: pageNum,
              limit: 50,
            },
          },
        );

        if (currentConversationIdRef.current !== conversationId) return;

        const result = response.data || {};
        const data = result.data || result || [];
        const pagination = result.pagination || {};

        setHasMoreMessages(
          pagination.hasNextPage || pagination.hasMore || false,
        );
        setMessagesPage(pageNum);

        const formattedMessages: Message[] = data.map(parseMessage);

        // Deduplicate
        const messagesMap = new Map<string, Message>();
        formattedMessages.forEach((msg) => messagesMap.set(msg.id, msg));
        const deduplicatedMessages = Array.from(messagesMap.values());

        if (pageNum === 1) {
          setMessages(deduplicatedMessages);
        } else {
          setMessages((prev) => {
            const existingIds = new Set(prev.map((m) => m.id));
            const newMessages = deduplicatedMessages.filter(
              (m) => !existingIds.has(m.id),
            );
            const result = [...newMessages, ...prev];
            return result;
          });
        }
      } catch (err: any) {
        console.error("❌ Error loading messages:", err);
        setError(err.message || "فشل في تحميل الرسائل");
      } finally {
        setLoadingMessages(false);
      }
    },
    [companyId],
  );

  const loadMoreMessages = useCallback(() => {
    if (selectedConversation && hasMoreMessages && !loadingMessages) {
      loadMessages(selectedConversation.id, messagesPage + 1);
    }
  }, [
    selectedConversation,
    hasMoreMessages,
    loadingMessages,
    messagesPage,
    loadMessages,
  ]);

  // Select conversation
  const selectConversation = useCallback(
    async (conversation: InboxConversation | null) => {
      setSelectedConversation(conversation);
      if (conversation) {
        // 🆕 Save selected conversation ID to localStorage for persistence after refresh
        localStorage.setItem("selectedConversationId", conversation.id);

        loadMessages(conversation.id);
        // 🔧 FIX: Always mark conversation as read when opened (even if unreadCount is 0, to sync with backend)
        // This ensures backend state is updated and unreadCount is recalculated
        try {
          const response = await apiClient.post(
            `/conversations/${conversation.id}/read`,
          );
          // Update local state with response data
          // 🔧 FIX: Use unreadCount from response (backend calculates it correctly)
          const newUnreadCount =
            response.data?.unreadCount ??
            response.data?.conversation?.unreadCount ??
            0;
          setSelectedConversation((prev) =>
            prev ? { ...prev, unreadCount: newUnreadCount } : null,
          );
          setConversations((prev) =>
            prev.map((conv) =>
              conv.id === conversation.id
                ? { ...conv, unreadCount: newUnreadCount }
                : conv,
            ),
          );
        } catch (error: any) {
          console.error("Failed to mark conversation as read:", error);
        }
      } else {
        // 🆕 Clear saved conversation ID when deselecting
        localStorage.removeItem("selectedConversationId");
        setMessages([]);
        currentConversationIdRef.current = null;
      }
    },
    [loadMessages, companyId, setConversations],
  );

  // Update selected conversation from list updates
  useEffect(() => {
    if (selectedConversation && conversations.length > 0) {
      const updatedConversation = conversations.find(
        (c) => c.id === selectedConversation.id,
      );
      const updatedMetadataSnapshot = serializeConversationMetadata(
        updatedConversation?.metadata,
      );
      const selectedMetadataSnapshot = serializeConversationMetadata(
        selectedConversation.metadata,
      );
      if (
        updatedConversation &&
        (updatedConversation.status !== selectedConversation.status ||
          updatedConversation.assignedTo !== selectedConversation.assignedTo ||
          updatedConversation.assignedToName !==
            selectedConversation.assignedToName ||
          updatedConversation.priority !== selectedConversation.priority ||
          updatedConversation.postId !== selectedConversation.postId ||
          updatedConversation.lastMessage !== selectedConversation.lastMessage ||
          updatedConversation.unreadCount !== selectedConversation.unreadCount ||
          updatedConversation.lastMessageTime.getTime() !==
            selectedConversation.lastMessageTime.getTime() ||
          updatedMetadataSnapshot !== selectedMetadataSnapshot)
      ) {
        const postDetails =
          selectedConversation.postDetails ||
          updatedConversation.postDetails ||
          null;
        setSelectedConversation({
          ...updatedConversation,
          postDetails: postDetails,
        });
      }
    }
  }, [conversations, selectedConversation]);

  // Initial load - load default 'all' tab if not called externally
  // But since component calls it, we might want to skip auto-load or default to something
  useEffect(() => {
    // We let the component trigger the first load to control the tab
  }, []);

  // 🆕 Restore selected conversation from localStorage after conversations are loaded
  const restoredRef = useRef(false);
  useEffect(() => {
    if (
      restoredRef.current ||
      conversations.length === 0 ||
      selectedConversation
    )
      return;

    const savedConversationId = localStorage.getItem("selectedConversationId");
    if (savedConversationId) {
      const savedConversation = conversations.find(
        (c) => c.id === savedConversationId,
      );
      if (savedConversation) {
        console.log("🔄 Restoring saved conversation:", savedConversationId);
        selectConversation(savedConversation);
        restoredRef.current = true;
      }
    }
  }, [conversations, selectedConversation, selectConversation]);

  // Selection state
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const toggleSelection = useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const selectAll = useCallback((ids: string[]) => {
    setSelectedIds(new Set(ids));
  }, []);

  const clearSelection = useCallback(() => {
    setSelectedIds(new Set());
  }, []);

  const addMessage = useCallback((newMessage: any) => {
    setMessages((prev) => {
      // Check if message already exists by ID
      if (prev.some((m) => m.id === newMessage.id)) return prev;

      const formatted = parseMessage(newMessage);

      // 🆕 Check for optimistic message with same content (temp_ ID)
      // If we find a temp message with same content, replace it with real message
      const tempIndex = prev.findIndex(
        (m) =>
          m.id.startsWith("temp_") &&
          m.content === formatted.content &&
          !m.isFromCustomer,
      );

      if (tempIndex !== -1) {
        // Replace temp message with real message
        const updated = [...prev];
        updated[tempIndex] = formatted;
        return updated;
      }

      // 🆕 Also check if same content was sent within last 5 seconds (duplicate prevention)
      const now = new Date().getTime();
      const isDuplicate = prev.some(
        (m) =>
          m.content === formatted.content &&
          !m.isFromCustomer &&
          now - new Date(m.timestamp).getTime() < 5000,
      );

      if (isDuplicate) return prev;

      return [...prev, formatted];
    });
  }, []);

  const updateSelectedConversation = useCallback(
    (updates: Partial<InboxConversation>) => {
      setSelectedConversation((prev) =>
        prev ? { ...prev, ...updates } : null,
      );
      setConversations((prev) =>
        prev.map((conv) =>
          conv.id === selectedConversation?.id ? { ...conv, ...updates } : conv,
        ),
      );
    },
    [selectedConversation?.id],
  );

  // 🆕 Add a single conversation to the list (for URL loading)
  const addConversationToList = useCallback(
    (conversation: InboxConversation) => {
      setConversations((prev) => {
        // Check if conversation already exists
        if (prev.some((c) => c.id === conversation.id)) {
          // Update existing conversation
          return prev.map((c) => (c.id === conversation.id ? conversation : c));
        }
        // Add to beginning of list
        return [conversation, ...prev];
      });
    },
    [],
  );

  // 🆕 Update messages status to 'read' (for read receipts)
  const markMessagesAsRead = useCallback((watermark: number) => {
    setMessages((prev) =>
      prev.map((msg) => {
        // Only update outgoing messages (not from customer) that are sent/delivered
        if (
          !msg.isFromCustomer &&
          (msg.status === "sent" || msg.status === "delivered") &&
          new Date(msg.timestamp).getTime() <= watermark
        ) {
          return { ...msg, status: "read" as const };
        }
        return msg;
      }),
    );
  }, []);

  return {
    conversations,
    selectedConversation,
    messages,
    loading,
    loadingMessages,
    error,
    selectConversation,
    loadConversations,
    loadMessages,
    loadMoreMessages,
    addMessage,
    hasMore: hasMoreMessages,
    hasMoreConversations,
    loadMoreConversations,
    updateSelectedConversation,
    selectedIds,
    toggleSelection,
    selectAll,
    clearSelection,
    apiCounts,
    // 🆕 Add conversation to list
    addConversationToList,
    // 🆕 Mark messages as read (for read receipts)
    markMessagesAsRead,
  };
};

import { useCallback, useState } from "react";
import { apiClient } from "../../services/apiClient";
import { Note } from "../../types/inbox.types";

export const useNotes = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch notes for a customer
  const fetchNotes = useCallback(
    async (customerId: string): Promise<Note[]> => {
      try {
        setLoading(true);
        setError(null);
        const response = await apiClient.get<{ data: any[] }>(
          `/customers/${customerId}/notes`,
        );

        // Transform backend response to match frontend Note interface
        // Backend returns: { id, customerId, authorId, content, createdAt, author: {firstName, lastName, avatar} }
        // Frontend expects: { id, conversationId, content, authorId, authorName, mentions, attachments, createdAt, updatedAt }

        return response.data.data.map((note: any) => ({
          id: note.id,
          conversationId: "", // Notes are per-customer now, but interface requires string
          content: note.content,
          authorId: note.authorId,
          authorName:
            `${note.author?.firstName || ""} ${note.author?.lastName || ""}`.trim() ||
            "Unknown",
          authorAvatar: note.author?.avatar, // We might need to extend Note interface or ignore this
          mentions: [],
          attachments: [],
          createdAt: new Date(note.createdAt),
          updatedAt: new Date(note.updatedAt || note.createdAt),
        }));
      } catch (err: any) {
        console.error("❌ Error fetching notes:", err);
        setError(err.message || "فشل في جلب الملاحظات");
        return [];
      } finally {
        setLoading(false);
      }
    },
    [],
  );

  // Add a new note
  const addNote = useCallback(
    async (customerId: string, content: string): Promise<Note | null> => {
      try {
        setLoading(true);
        setError(null);
        const response = await apiClient.post<{ data: any }>(
          `/customers/${customerId}/notes`,
          { content },
        );

        const note = response.data.data;

        return {
          id: note.id,
          conversationId: "",
          content: note.content,
          authorId: note.authorId,
          authorName:
            `${note.author?.firstName || ""} ${note.author?.lastName || ""}`.trim() ||
            "Unknown",
          mentions: [],
          attachments: [],
          createdAt: new Date(note.createdAt),
          updatedAt: new Date(note.updatedAt || note.createdAt),
        };
      } catch (err: any) {
        console.error("❌ Error adding note:", err);
        setError(err.message || "فشل في إضافة الملاحظة");
        return null;
      } finally {
        setLoading(false);
      }
    },
    [],
  );

  // Delete a note
  const deleteNote = useCallback(async (noteId: string): Promise<boolean> => {
    try {
      setLoading(true);
      setError(null);
      await apiClient.delete(`/customers/notes/${noteId}`);
      return true;
    } catch (err: any) {
      console.error("❌ Error deleting note:", err);
      setError(err.message || "فشل في حذف الملاحظة");
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  return {
    fetchNotes,
    addNote,
    deleteNote,
    loading,
    error,
  };
};

import { useState, useCallback, useRef } from "react";
import { apiClient } from "../../services/apiClient";
import { uploadService } from "../../services/uploadService";

interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type: "text" | "image" | "file" | "IMAGE" | "FILE";
  isFromCustomer: boolean;
  status: "sending" | "sent" | "delivered" | "read" | "error";
  conversationId: string;
  fileUrl?: string;
  fileName?: string;
  fileSize?: number;
  isAiGenerated?: boolean;
}

export const useSendMessage = () => {
  const [sending, setSending] = useState(false);
  const [uploadingFile, setUploadingFile] = useState(false);

  // 🆕 Track pending messages count for optimistic UI
  const pendingMessagesRef = useRef(0);

  // 🆕 Send text message with Optimistic UI support
  const sendTextMessage = useCallback(
    async (
      conversationId: string,
      content: string,
      companyId: string,
      replyTo?: any,
      onOptimisticMessage?: (message: Message) => void,
      onMessageSent?: (tempId: string, realMessage: Message) => void,
      onMessageError?: (tempId: string, error: string) => void,
    ): Promise<Message | null> => {
      if (!content.trim()) return null;

      // 🆕 Create optimistic message with temporary ID
      const tempId = `temp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      const optimisticMessage: Message = {
        id: tempId,
        content: content.trim(),
        senderId: "currentUser",
        senderName: "أنت",
        timestamp: new Date(),
        type: "text",
        isFromCustomer: false,
        status: "sending",
        conversationId,
      };

      // 🆕 Immediately show optimistic message
      if (onOptimisticMessage) {
        onOptimisticMessage(optimisticMessage);
      }

      pendingMessagesRef.current++;
      setSending(pendingMessagesRef.current > 0);

      try {
        const response = await apiClient.post(
          `/conversations/${conversationId}/messages`,
          {
            message: content.trim(),
            type: "text",
            companyId,
            replyTo,
          },
        );

        const data = response.data?.data || response.data;

        // Format response as Message
        const message: Message = {
          id: data.id,
          content: data.content,
          senderId: data.senderId,
          senderName: data.senderName || "أنت",
          timestamp: new Date(data.timestamp || data.createdAt),
          type: "text",
          isFromCustomer: false,
          status: "sent",
          conversationId: data.conversationId,
        };

        // 🆕 Update optimistic message with real data
        if (onMessageSent) {
          onMessageSent(tempId, message);
        }

        return message;
      } catch (error: any) {
        console.error("❌ Error sending message:", error);
        // 🆕 Mark optimistic message as error
        if (onMessageError) {
          onMessageError(tempId, error.message || "فشل في إرسال الرسالة");
        }
        throw new Error(error.message || "فشل في إرسال الرسالة");
      } finally {
        pendingMessagesRef.current--;
        setSending(pendingMessagesRef.current > 0);
      }
    },
    [],
  );

  // Send file/image message
  const sendFileMessage = useCallback(
    async (
      conversationId: string,
      file: File,
      _companyId: string,
    ): Promise<Message | null> => {
      try {
        setUploadingFile(true);

        // Validate file
        const validation = uploadService.validateFile(file);
        if (!validation.valid) {
          throw new Error(validation.error);
        }

        // Upload file
        const uploadResult = await uploadService.uploadConversationFile(
          conversationId,
          file,
        );

        if (
          !uploadResult.success ||
          !uploadResult.data ||
          !Array.isArray(uploadResult.data) ||
          uploadResult.data.length === 0
        ) {
          throw new Error("فشل في رفع الملف");
        }

        const uploadedFile = uploadResult.data[0];
        const isImage = file.type.startsWith("image/");

        // Return constructed message object from upload result
        // Backend already created the message and emitted socket event
        return {
          id: uploadedFile.messageId || Date.now().toString(),
          content: isImage ? "صورة" : file.name,
          senderId: "currentUser", // Placeholder
          senderName: "Me", // Placeholder
          timestamp: new Date(),
          type: isImage ? "image" : "file",
          isFromCustomer: false,
          status: "sent",
          conversationId,
          fileUrl: uploadedFile.fullUrl,
          fileName: uploadedFile.originalName,
          fileSize: uploadedFile.size,
        };
      } catch (error: any) {
        console.error("❌ Error sending file:", error);
        throw new Error(error.message || "فشل في إرسال الملف");
      } finally {
        setUploadingFile(false);
      }
    },
    [],
  );

  return {
    sendTextMessage,
    sendFileMessage,
    sending,
    uploadingFile,
  };
};

import { useCallback, useState } from "react";
import { apiClient } from "../../services/apiClient";

export const useTagManagement = () => {
  const [updating, setUpdating] = useState(false);

  // Add tags to conversation
  const addTags = useCallback(
    async (conversationId: string, tagIds: string[], companyId: string) => {
      try {
        setUpdating(true);

        await apiClient.put(`/conversations/${conversationId}`, {
          tags: tagIds,
          companyId,
        });

        return true;
      } catch (error: any) {
        console.error("❌ Error adding tags:", error);
        throw new Error(error.message || "فشل في إضافة التصنيفات");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  // Remove tag from conversation
  const removeTag = useCallback(
    async (
      conversationId: string,
      currentTags: string[],
      tagToRemove: string,
      companyId: string,
    ) => {
      try {
        setUpdating(true);

        const newTags = currentTags.filter((t) => t !== tagToRemove);

        await apiClient.put(`/conversations/${conversationId}`, {
          tags: newTags,
          companyId,
        });

        return true;
      } catch (error: any) {
        console.error("❌ Error removing tag:", error);
        throw new Error(error.message || "فشل في إزالة التصنيف");
      } finally {
        setUpdating(false);
      }
    },
    [],
  );

  return {
    addTags,
    removeTag,
    updating,
  };
};

import React, { useState, useEffect, createContext, useContext, ReactNode, useRef, useCallback } from 'react';
import { getApiUrl } from '../config/environment';
import { tokenManager } from '../utils/tokenManager';
import {
  refreshSessionTokens,
  shouldClearSessionOnRefreshFailure,
} from '../utils/sessionRefresh';
import socketService from '../services/socketService';
import type { CompanyOnboardingState } from '../utils/companyOnboarding';

interface Company {
  id: string;
  name: string;
  slug: string | null;
  phone?: string | null;
  customDomain?: string | null;
  logo?: string | null;
  plan: string;
  currency?: string;
  isActive?: boolean;
  role?: string;
  sidebarLayout?: string;
  signupCouponCode?: string | null;
  isDefault?: boolean;
  isCurrent?: boolean;
  onboarding?: CompanyOnboardingState | null;
}

interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  timezone?: string;
  companyId: string | null;
  company: Company | null;
  companies?: Company[];         // قائمة الشركات التي ينتمي إليها المستخدم
  hasMultipleCompanies?: boolean; // هل لديه أكثر من شركة؟
  devStats?: {
    xp: number;
    level: number;
  } | null;
}

interface LoginCredentials {
  email: string;
  password: string;
  rememberMe?: boolean;
}

interface RegisterData {
  email: string;
  password: string;
  firstName: string;
  lastName: string;
  companyName: string;
  phone?: string;
  timezone?: string;
  partnerCode?: string;
  promoCode?: string;
}

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (credentials: LoginCredentials | User, token?: string) => Promise<User | null>;
  register: (data: RegisterData) => Promise<User | null>;
  logout: () => void;
  switchCompany: (companyId: string) => Promise<boolean>; // التبديل بين الشركات
  setDefaultCompany: (companyId: string) => Promise<boolean>; // تعيين الشركة الافتراضية
  isSwitchingCompany: boolean; // هل يتم التبديل حالياً؟
}

type AuthContextWindow = typeof globalThis & {
  __MAXP_AUTH_CONTEXT__?: ReturnType<typeof createContext<AuthContextType | undefined>>;
};

// Keep the auth context stable across HMR updates because the app preserves a
// single React root in development. Without this, a hot-reloaded consumer can
// end up reading from a fresh context instance while the provider still holds
// the previous one, which crashes super-admin routes intermittently.
const authContextWindow = globalThis as AuthContextWindow;
const AuthContext =
  authContextWindow.__MAXP_AUTH_CONTEXT__ ??
  createContext<AuthContextType | undefined>(undefined);

authContextWindow.__MAXP_AUTH_CONTEXT__ = AuthContext;

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Initialize user from localStorage to prevent redirect "blips" on refresh
  const [user, setUser] = useState<User | null>(() => {
    try {
      const savedUser = localStorage.getItem('user');
      return savedUser ? JSON.parse(savedUser) : null;
    } catch (e) {
      console.warn('⚠️ [useAuthSimple] Failed to parse user from localStorage:', e);
      return null;
    }
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSwitchingCompany, setIsSwitchingCompany] = useState(false);
  const authStateVersionRef = useRef(0);
  const isDev = import.meta.env.DEV || import.meta.env.MODE === 'development';
  const debugLog = useCallback((...args: unknown[]) => {
    if (isDev) console.debug(...args);
  }, [isDev]);
  const warnLog = useCallback((...args: unknown[]) => {
    if (isDev) console.warn(...args);
  }, [isDev]);
  const errorLog = useCallback((...args: unknown[]) => {
    if (isDev) console.error(...args);
  }, [isDev]);
  const bumpAuthStateVersion = () => {
    authStateVersionRef.current += 1;
  };

  const AUTH_TRANSITION_GRACE_MS = 5000;

  const isAuthTransitioning = useCallback(() => {
    try {
      const raw = localStorage.getItem('authTransitionUntil');
      if (!raw) return false;

      const until = Number(raw);
      if (!Number.isFinite(until)) {
        localStorage.removeItem('authTransitionUntil');
        return false;
      }

      if (Date.now() < until) {
        return true;
      }

      localStorage.removeItem('authTransitionUntil');
      return false;
    } catch {
      return false;
    }
  }, []);

  const hasToken = !!tokenManager.getAccessToken();
  const isAuthenticated = !!user || hasToken;

  const clearStoredAuth = useCallback(() => {
    tokenManager.clearTokens();
    localStorage.removeItem('user');
  }, []);

  useEffect(() => {
    const checkAuth = async () => {
      const authStateVersion = authStateVersionRef.current;
      const isStale = () => authStateVersion !== authStateVersionRef.current;
      debugLog('🔍 [AuthProvider] Starting auth check...');

      // Keep track of the user we started with (from localStorage)
      let currentInitialUser: User | null = null;
      try {
        const savedUser = localStorage.getItem('user');
        currentInitialUser = savedUser ? JSON.parse(savedUser) : null;
      } catch {
        currentInitialUser = null;
      }

      let finalUser: User | null = currentInitialUser;

      try {
        let token = tokenManager.getAccessToken();
        debugLog('🔍 [AuthProvider] Token exists:', !!token);

        if (token) {
          let mePath = '/auth/me';

          const attemptSessionRecovery = async () => {
            const refreshResult = await refreshSessionTokens();

            if (refreshResult.ok) {
              debugLog('🔄 [AuthProvider] Session refresh succeeded during auth check');
              return refreshResult;
            }

            if (shouldClearSessionOnRefreshFailure(refreshResult)) {
              warnLog('⚠️ [AuthProvider] Session refresh failed with auth error, clearing tokens', refreshResult);
              clearStoredAuth();
              setUser(null);
              finalUser = null;
            } else {
              warnLog('⏳ [AuthProvider] Session refresh failed temporarily, preserving existing user state', refreshResult);
              finalUser = currentInitialUser;
              setUser(currentInitialUser);
            }

            return refreshResult;
          };

          const requestCurrentUser = async (activeToken: string) =>
            fetch(`${getApiUrl()}${mePath}?t=${Date.now()}`, {
              headers: {
                'Authorization': `Bearer ${activeToken}`,
                'Content-Type': 'application/json'
              },
              credentials: 'include',
            });

          try {
            const parts = token.split('.');
            const payloadBase64 = parts[1];
            if (payloadBase64) {
              const payloadJson = JSON.parse(atob(payloadBase64));

              if (payloadJson?.exp && payloadJson.exp < Date.now() / 1000) {
                debugLog('🔍 [AuthProvider] Token is expired locally, attempting session refresh');
                const refreshResult = await attemptSessionRecovery();
                if (!refreshResult.ok) {
                  setIsLoading(false);
                  return;
                }
                token = refreshResult.accessToken;
              }

              if (payloadJson?.role === 'CUSTOMER') {
                mePath = '/public/customers/me';
              }
            }
          } catch (decodeError) {
            debugLog('⚠️ [AuthProvider] Failed to decode access token payload during auth check', decodeError);
          }

          debugLog(`🔍 [AuthProvider] Making ${mePath} request...`);
          let response = await requestCurrentUser(token);

          debugLog('🔍 [AuthProvider] Response status:', response.status);

          if (response.status === 403 || response.status === 401) {
            if (isAuthTransitioning()) {
              warnLog('⏳ [AuthProvider] Ignoring transient 401/403 during auth/company switch transition');
              finalUser = currentInitialUser;
              setUser(currentInitialUser);
            } else {
              const refreshResult = await attemptSessionRecovery();
              if (!refreshResult.ok) {
                return;
              }

              response = await requestCurrentUser(refreshResult.accessToken);
              debugLog('🔍 [AuthProvider] Retried auth check after refresh, status:', response.status);
            }
          }

          if (response.ok || response.status === 304) {
            const data = await response.json();
            debugLog('🔍 [AuthProvider] Response received');

            if (data.success) {
              // debugLog('✅ [AuthProvider] Authenticated user loaded');
              // API might return user in data.data or data.data.user
              debugLog('🔍 [AuthProvider] Data received:', data);
              const userObj = data.data?.user || data.data;
              debugLog('🔍 [AuthProvider] Parsed userObj:', userObj);
              finalUser = userObj;
              setUser(userObj);
              localStorage.setItem('user', JSON.stringify(userObj));
            } else {
              warnLog('⚠️ [AuthProvider] API returned success:false, clearing tokens');
              clearStoredAuth();
              setUser(null);
              finalUser = null;
            }
          } else if (response.status === 403 || response.status === 401) {
            warnLog('⚠️ [AuthProvider] Token still unauthorized after refresh/auth check, clearing tokens');
            warnLog('⚠️ [AuthProvider] Response status:', response.status);
            clearStoredAuth();
            setUser(null);
            finalUser = null;
            debugLog('🔐 [AuthProvider] Token invalid, cleared');
          } else {
            warnLog('⚠️ [AuthProvider] Auth check failed with status:', response.status);

            if (response.status >= 400 && response.status < 500) {
              warnLog('⚠️ [AuthProvider] Client error (4xx), clearing tokens');
              clearStoredAuth();
              setUser(null);
              finalUser = null;
            } else {
              warnLog('⚠️ [AuthProvider] Server error (5xx), keeping existing session if any');
              finalUser = currentInitialUser;
            }
          }
        } else {
          debugLog('🔐 [AuthProvider] No token found');
          // If no token, we definitely shouldn't have a user
          if (currentInitialUser) {
            localStorage.removeItem('user');
            setUser(null);
            finalUser = null;
          }
        }
      } catch (error: unknown) {
        // Network errors or other issues - log
        const errorMessage =
          error instanceof Error ? error.message : String(error ?? '');
        errorLog('❌ [AuthProvider] Auth check failed:', errorMessage || error);

        // Don't clear tokens on network errors - might be temporary
        if (errorMessage.includes('401')) {
          warnLog('⚠️ [AuthProvider] 401 error detected, clearing tokens');
          clearStoredAuth();
          setUser(null);
          finalUser = null;
        } else {
          warnLog('⚠️ [AuthProvider] Network error - keeping existing session if any');
          finalUser = currentInitialUser;
        }
      } finally {
        if (isStale()) {
          debugLog('🔍 [AuthProvider] Check aborted - stale state');
        } else {
          const isNowAuthenticated = !!finalUser;
          debugLog('🔍 [AuthProvider] Auth check complete. Authenticated:', isNowAuthenticated);

          setUser(finalUser || null);
          setIsLoading(false);
        }
      }
    };

    checkAuth();
  }, [clearStoredAuth, debugLog, errorLog, isAuthTransitioning, warnLog]);

  useEffect(() => {
    const handleUnauthorized = () => {
      if (isAuthTransitioning()) {
        warnLog('⏳ [AuthProvider] Ignoring auth:unauthorized during auth/company switch transition');
        return;
      }

      bumpAuthStateVersion();
      clearStoredAuth();
      setUser(null);
      setIsLoading(false);
    };

    window.addEventListener('auth:unauthorized', handleUnauthorized);
    return () => window.removeEventListener('auth:unauthorized', handleUnauthorized);
  }, [clearStoredAuth, isAuthTransitioning, warnLog]);

  useEffect(() => {
    const handleUserUpdated = (event: Event) => {
      const detail = (event as CustomEvent<{ user?: User | null }>).detail;
      const nextUser = detail?.user;

      if (!nextUser) {
        return;
      }

      setUser(nextUser);
      localStorage.setItem('user', JSON.stringify(nextUser));
    };

    window.addEventListener('auth:user-updated', handleUserUpdated as EventListener);
    return () =>
      window.removeEventListener(
        'auth:user-updated',
        handleUserUpdated as EventListener,
      );
  }, []);

  const login = async (credentials: LoginCredentials | User, token?: string) => {
    debugLog('🔍 [AuthProvider] Starting login...');
    try {
      // If user and token are provided directly (for Super Admin)
      if (token && typeof credentials === 'object' && 'id' in credentials) {
        debugLog('🔍 [AuthProvider] Direct login with token');
        bumpAuthStateVersion();
        tokenManager.setAccessToken(token);
        const userData = credentials as User;
        setUser(userData);
        localStorage.setItem('user', JSON.stringify(userData));
        setIsLoading(false);
        return userData;
      }

      // Normal login flow
      const loginCredentials = credentials as LoginCredentials;
      debugLog('🔍 [AuthProvider] Normal login flow');

      const response = await fetch(`${getApiUrl()}/auth/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          email: loginCredentials.email,
          password: loginCredentials.password
        })
      });

      debugLog('🔍 [AuthProvider] Login response status:', response.status);

      // Handle network errors
      if (!response.ok) {
        let errorMessage = 'فشل في تسجيل الدخول';
        try {
          const errorData = await response.json();
          errorMessage = errorData.message || errorData.error || errorMessage;
        } catch (parseError) {
          // If response is not JSON, use status text
          errorMessage = response.statusText || `خطأ في الاتصال (${response.status})`;
        }
        throw new Error(errorMessage);
      }

      const data = await response.json();
      debugLog('🔍 [AuthProvider] Login response received');

      if (data.success) {
        // Store tokens
        debugLog('✅ [AuthProvider] Login successful, storing token');
        bumpAuthStateVersion();
        tokenManager.setAccessToken(data.data.token);
        if (data.data.refreshToken) {
          tokenManager.setRefreshToken(data.data.refreshToken);
        }

        // Set user data
        debugLog('✅ [AuthProvider] Setting user data');
        const userData = data.data.user;
        setUser(userData);

        // Store user data in localStorage for Socket.IO connection
        localStorage.setItem('user', JSON.stringify(userData));
        setIsLoading(false);

        // 🔌 Reconnect socket with new authentication token
        // socketService.disconnect();
        // socketService.connect();
        debugLog('🔌 [AUTH] Socket reconnected with new token');

        // Return user data for immediate use
        return userData;
      } else {
        throw new Error(data.message || 'فشل في تسجيل الدخول');
      }
    } catch (error: unknown) {
      const errorMessage =
        error instanceof Error ? error.message : String(error ?? '');
      errorLog('❌ [AuthProvider] Login error:', errorMessage || error);
      // Provide better error message for network errors
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error('فشل الاتصال بالخادم. يرجى التحقق من الاتصال بالإنترنت والمحاولة مرة أخرى.');
      }
      throw error;
    }
  };

  const register = async (data: RegisterData) => {
    try {
      const response = await fetch(`${getApiUrl()}/auth/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(data),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.message || 'فشل في إنشاء الحساب');
      }

      // Store token and user data
      bumpAuthStateVersion();
      tokenManager.setAccessToken(result.data.token);
      if (result.data.refreshToken) {
        tokenManager.setRefreshToken(result.data.refreshToken);
      }

      let userData = result.data.user;

      try {
        const token = tokenManager.getAccessToken();
        const meResponse = await fetch(`${getApiUrl()}/auth/me`, {
          method: 'GET',
          headers: token
            ? {
                Authorization: `Bearer ${token}`,
                'Content-Type': 'application/json',
              }
            : {
                'Content-Type': 'application/json',
              },
          credentials: 'include',
        });

        if (meResponse.ok) {
          const meResult = await meResponse.json();
          if (meResult?.success && meResult?.data?.user) {
            userData = meResult.data.user;
          }
        }
      } catch (meError) {
        console.warn('⚠️ [AuthProvider] Failed to hydrate register user from /auth/me:', meError);
      }

      setUser(userData);

      // Store user data in localStorage for Socket.IO connection
      localStorage.setItem('user', JSON.stringify(userData));

      return userData;
    } catch (error: unknown) {
      console.error('Registration error:', error);
      throw error;
    }
  };

  const logout = async () => {
    try {
      const token = tokenManager.getAccessToken();
      if (token) {
        // Call logout API
        await fetch(`${getApiUrl()}/auth/logout`, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          },
          credentials: 'include'
        });
      }
    } catch (error) {
      errorLog('Logout error:', error);
    } finally {
      // Always clear storage and user state
      bumpAuthStateVersion();
      tokenManager.clearTokens();
      localStorage.removeItem('user');
      setUser(null);

      // 🔌 Disconnect socket to force fresh connection on next login
      socketService.disconnect();
      debugLog('🔌 [AUTH] Socket disconnected on logout');
    }
  };

  // التبديل إلى شركة أخرى
  const switchCompany = async (companyId: string): Promise<boolean> => {
    debugLog('🔄 [AuthProvider] Switching to company:', companyId);

    try {
      bumpAuthStateVersion();
      setIsSwitchingCompany(true);
      const token = tokenManager.getAccessToken();

      if (!token) {
        errorLog('❌ [AuthProvider] No token for company switch');
        return false;
      }

      const response = await fetch(`${getApiUrl()}/auth/switch-company/${companyId}`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        credentials: 'include'
      });

      const data = await response.json();

      if (response.ok && data.success) {
        debugLog('✅ [AuthProvider] Company switch successful');

        localStorage.setItem('authTransitionUntil', String(Date.now() + AUTH_TRANSITION_GRACE_MS));

        // Store new tokens
        tokenManager.setAccessToken(data.data.token);
        if (data.data.refreshToken) {
          tokenManager.setRefreshToken(data.data.refreshToken);
        }

        let switchedUser: User | null = null;

        try {
          const switchedToken = tokenManager.getAccessToken();
          const meResponse = await fetch(`${getApiUrl()}/auth/me?t=${Date.now()}`, {
            headers: switchedToken
              ? {
                  Authorization: `Bearer ${switchedToken}`,
                  'Content-Type': 'application/json',
                }
              : {
                  'Content-Type': 'application/json',
                },
            credentials: 'include',
            cache: 'no-store',
          });

          if (meResponse.ok) {
            const meResult = await meResponse.json();
            const hydratedUser = meResult?.data?.user || meResult?.data || null;
            if (hydratedUser) {
              switchedUser = hydratedUser;
            }
          }
        } catch (meError) {
          warnLog('⚠️ [AuthProvider] Failed to hydrate switched company user from /auth/me:', meError);
        }

        if (!switchedUser && user) {
          const fallbackCompanies =
            data.data.companies ||
            user.companies?.map((company) => ({
              ...company,
              isCurrent: company.id === companyId,
            })) ||
            [];

          switchedUser = {
            ...user,
            companyId,
            role: data.data.role,
            company: data.data.company,
            companies: fallbackCompanies,
            hasMultipleCompanies:
              data.data.hasMultipleCompanies ??
              fallbackCompanies.length > 1,
          };
        }

        if (switchedUser) {
          setUser(switchedUser);
          localStorage.setItem('user', JSON.stringify(switchedUser));
        }
        setIsLoading(false);

        // Store company switch timestamp to force consumers to refresh scoped data
        localStorage.setItem('companySwitchTimestamp', Date.now().toString());

        // Let React/context consumers update first, then soft-refresh the route state
        setTimeout(() => {
          window.dispatchEvent(new CustomEvent('company:switched', {
            detail: {
              companyId,
              timestamp: Date.now(),
            },
          }));
        }, 50);

        return true;
      } else {
        errorLog('❌ [AuthProvider] Company switch failed:', data?.message);
        return false;
      }
    } catch (error) {
      errorLog('❌ [AuthProvider] Company switch error:', error);
      return false;
    } finally {
      setIsSwitchingCompany(false);
    }
  };

  const setDefaultCompany = async (companyId: string): Promise<boolean> => {
    try {
      const token = tokenManager.getAccessToken();
      const response = await fetch(`${getApiUrl()}/auth/set-default-company/${companyId}`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();

      if (data.success) {
        // تحديث حالة المستخدم محلياً لتعكس الشركة الافتراضية الجديدة
        if (user && user.companies) {
          const updatedCompanies = user.companies.map(c => ({
            ...c,
            isDefault: c.id === companyId
          }));
          
          const updatedUser = {
            ...user,
            companyId: companyId, // تحديث الشركة الأساسية أيضاً
            companies: updatedCompanies
          };

          setUser(updatedUser);
          localStorage.setItem('user', JSON.stringify(updatedUser));
        }
        return true;
      } else {
        errorLog('❌ [AuthProvider] Set default company failed:', data?.message);
        return false;
      }
    } catch (error) {
      errorLog('❌ [AuthProvider] Set default company error:', error);
      return false;
    }
  };

  const value: AuthContextType = {
    user,
    isLoading,
    isAuthenticated,
    login,
    register,
    logout,
    switchCompany,
    setDefaultCompany,
    isSwitchingCompany,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const useOptionalAuth = (): AuthContextType | undefined =>
  useContext(AuthContext);

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { storefrontApi } from "../utils/storefrontApi";

/**
 * 🛒 Custom hook for cart management using React Query.
 * Centralizes cart state, mutations, and business logic (free shipping).
 */
export const useCart = () => {
  const queryClient = useQueryClient();

  // 1. Fetch Cart Data
  const {
    data: cartResponse,
    isLoading: isCartLoading,
    isFetching: isCartFetching,
    refetch: refetchCart 
  } = useQuery({
    queryKey: ["cart"],
    queryFn: async () => {
      const response = await storefrontApi.getCart();
      const cartData = response?.data || response || { items: [], total: 0 };

      // Parse images for consistency across the app
      if (Array.isArray(cartData.items)) {
        cartData.items = cartData.items.map((item: any) => {
          let image = item.product?.images || item.images || item.image;
          if (typeof image === "string" && image.startsWith("[")) {
            try {
              const parsed = JSON.parse(image);
              image = Array.isArray(parsed) && parsed.length > 0 ? parsed[0] : (parsed || null);
            } catch {
              // fallback to original if parsing fails
            }
          }
          return { ...item, image };
        });
      }

      return cartData;
    },
    staleTime: 1000 * 30, // 30 seconds
    refetchOnWindowFocus: true,
  });

  // 2. Fetch Store Info (for Free Shipping & Currency settings)
  const { data: storeInfo } = useQuery({
    queryKey: ["storeInfo"],
    queryFn: async () => {
      const response = await storefrontApi.getStoreInfo();
      return response?.data || response;
    },
    staleTime: 1000 * 60 * 10, // 10 minutes
  });

  const cart = cartResponse || { items: [], total: 0 };
  const items = Array.isArray(cart.items) ? cart.items : [];
  const subtotal = Number(cart.total || 0);

  // 3. Business Logic: Free Shipping Progress
  const freeShippingSettings = storeInfo?.freeShippingSettings || { enabled: false, minAmount: 0 };
  const isFreeShippingAvailable = freeShippingSettings.enabled && subtotal >= freeShippingSettings.minAmount;

  const minAmount = Number(freeShippingSettings.minAmount || 0);
  const freeShippingProgress = minAmount > 0 
    ? Math.min((subtotal / minAmount) * 100, 100) 
    : 0;
  const amountToFreeShipping = Math.max(minAmount - subtotal, 0);

  // 4. Mutations
  const updateQuantityMutation = useMutation({
    mutationFn: async ({ productId, quantity, variantId }: { productId: string; quantity: number; variantId?: string | null }) => {
      return storefrontApi.updateCartItem(productId, { quantity, variantId });
    },
    onSuccess: (data) => {
      queryClient.setQueryData(["cart"], data?.data || data);
      queryClient.invalidateQueries({ queryKey: ["cart"] });
    }
  });

  const removeItemMutation = useMutation({
    mutationFn: async ({ productId, variantId }: { productId: string; variantId?: string | null }) => {
      return storefrontApi.removeCartItem(productId, variantId);
    },
    onSuccess: (data) => {
      queryClient.setQueryData(["cart"], data?.data || data);
      queryClient.invalidateQueries({ queryKey: ["cart"] });
    }
  });

  const clearCartMutation = useMutation({
    mutationFn: async () => {
      return storefrontApi.clearCart();
    },
    onSuccess: () => {
      queryClient.setQueryData(["cart"], { items: [], total: 0 });
      queryClient.invalidateQueries({ queryKey: ["cart"] });
    }
  });

  const addToCartMutation = useMutation({
    mutationFn: async ({ productId, quantity, variantId }: { productId: string; quantity: number; variantId?: string | null }) => {
      return storefrontApi.addToCart({ productId, quantity, variantId: variantId ?? undefined });
    },
    onSuccess: (data) => {
      queryClient.setQueryData(["cart"], data?.data || data);
      queryClient.invalidateQueries({ queryKey: ["cart"] });
      // Notify other parts of the app if needed
      window.dispatchEvent(new Event("cartUpdated"));
    }
  });

  // 5. Utility: Total Items Count
  const itemsCount = items.reduce((acc: number, item: any) => acc + (item.quantity || 0), 0);

  return {
    cart,
    items,
    itemsCount,
    subtotal,
    isCartLoading,
    isCartFetching,
    isAdding: addToCartMutation.isPending,
    isLoading: isCartLoading || updateQuantityMutation.isPending || removeItemMutation.isPending || addToCartMutation.isPending,
    freeShipping: {
      settings: freeShippingSettings,
      isAvailable: isFreeShippingAvailable,
      progress: freeShippingProgress,
      amountRemaining: amountToFreeShipping,
    },
    updateQuantity: (productId: string, quantity: number, variantId?: string | null) => 
      updateQuantityMutation.mutate({ productId, quantity, variantId }),
    updateQuantityAsync: (productId: string, quantity: number, variantId?: string | null) => 
      updateQuantityMutation.mutateAsync({ productId, quantity, variantId }),
    removeItem: (productId: string, variantId?: string | null) => 
      removeItemMutation.mutate({ productId, variantId }),
    removeItemAsync: (productId: string, variantId?: string | null) => 
      removeItemMutation.mutateAsync({ productId, variantId }),
    clearCart: () => clearCartMutation.mutate(),
    clearCartAsync: () => clearCartMutation.mutateAsync(),
    addToCart: (productId: string, quantity: number, variantId?: string | null) => 
      addToCartMutation.mutate({ productId, quantity, variantId }),
    addToCartAsync: (productId: string, quantity: number, variantId?: string | null) => 
      addToCartMutation.mutateAsync({ productId, quantity, variantId }),
    refresh: refetchCart,
  };
};

import { useEffect } from "react";

type ClaritySettings = {
  clarityProjectId?: string | null;
};

export const useClarityAnalytics = (settings?: ClaritySettings | null) => {
  useEffect(() => {
    if (!settings) return;

    const projectId = settings.clarityProjectId;
    const isProduction = import.meta.env.PROD || import.meta.env.MODE === "production";
    const idleWindow = window as Window & {
      requestIdleCallback?: (callback: () => void, options?: { timeout: number }) => number;
      cancelIdleCallback?: (id: number) => void;
    };

    if (!isProduction || !projectId || window.clarity) {
      return;
    }

    const injectClarity = () => {
      if (window.clarity) {
        return;
      }

      (function(c: any,l: any,a: any,r: any,i: any,t?: any,y?: any){
          c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
          t=l.createElement(r);t.async=1;t.defer=1;t.src="https://www.clarity.ms/tag/"+i;
          y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
      })(window, document, "clarity", "script", projectId);
    };

    // Strategy: Delay injection by 7s OR until user interacts (whichever comes first)
    const interactionEvents = ["pointermove", "scroll", "keydown", "click"];
    let injected = false;

    const handleInteraction = () => {
      if (injected) return;
      injected = true;
      injectClarity();
      
      // Cleanup listeners
      interactionEvents.forEach(event => {
        window.removeEventListener(event, handleInteraction);
      });
    };

    // Setup listeners for early interaction
    interactionEvents.forEach(event => {
      window.addEventListener(event, handleInteraction, { once: true, passive: true });
    });

    // Fallback timer (7 seconds)
    const fallbackId = window.setTimeout(() => {
      if (!injected) {
        handleInteraction();
      }
    }, 7000);

    return () => {
      window.clearTimeout(fallbackId);
      interactionEvents.forEach(event => {
        window.removeEventListener(event, handleInteraction);
      });
    };
  }, [settings?.clarityProjectId]);
};

