const scheduleIdleTask = (callback: () => void): (() => void) => {
  const idleWindow = window as Window & {
    requestIdleCallback?: (cb: () => void, options?: { timeout: number }) => number;
    cancelIdleCallback?: (id: number) => void;
  };

  if (typeof idleWindow.requestIdleCallback === "function") {
    const idleId = idleWindow.requestIdleCallback(callback, { timeout: 2500 });
    return () => idleWindow.cancelIdleCallback?.(idleId);
  }

  const timeoutId = window.setTimeout(callback, 1200);
  return () => window.clearTimeout(timeoutId);
};

export const useFacebookPixel = (
  storefrontSettings?: PublicStorefrontSettings | null,
) => {
  const location = useLocation();
  const [isLoaded, setIsLoaded] = useState(false);
  const [pixelId, setPixelId] = useState<string | null>(null);
  const [pageViewEnabled, setPageViewEnabled] = useState(false);
  const lastTrackedPathRef = useRef<string>("");

  useEffect(() => {
    setIsLoaded(false);
    setPixelId(null);
    setPageViewEnabled(false);

    if (!storefrontSettings) {
      return;
    }

    if (
      storefrontSettings.gtmEnabled &&
      storefrontSettings.gtmSuppressPixels
    ) {
      return;
    }

    if (
      !storefrontSettings.facebookPixelEnabled ||
      !storefrontSettings.facebookPixelId
    ) {
      return;
    }

    const cleanupIdleTask = scheduleIdleTask(() => {
      loadFacebookPixel(storefrontSettings.facebookPixelId!);
      setPixelId(storefrontSettings.facebookPixelId!);
      setIsLoaded(true);
      setPageViewEnabled(storefrontSettings.pixelTrackPageView !== false);
    });

    return cleanupIdleTask;
  }, [
    storefrontSettings?.facebookPixelEnabled,
    storefrontSettings?.facebookPixelId,
    storefrontSettings?.gtmEnabled,
    storefrontSettings?.gtmSuppressPixels,
    storefrontSettings?.pixelTrackPageView,
  ]);

  useEffect(() => {
    if (!isLoaded || !pageViewEnabled) {
      return;
    }

    let isCancelled = false;
    const timeoutIds: number[] = [];

    const currentPath = `${location.pathname}${location.search}`;
    if (lastTrackedPathRef.current === currentPath) {
      return;
    }

    const trackPageViewWithRetry = (attempt = 1) => {
      try {
        if (isCancelled) return;

        const eventId = trackPageView();
        if (eventId) {
          lastTrackedPathRef.current = currentPath;
        } else if (attempt < 3) {
          const timeoutId = window.setTimeout(
            () => trackPageViewWithRetry(attempt + 1),
            1000,
          );
          timeoutIds.push(timeoutId);
        }
      } catch (error) {
        console.error("❌ [Facebook Pixel] Error tracking PageView:", error);
      }
    };

    trackPageViewWithRetry();

    return () => {
      isCancelled = true;
      timeoutIds.forEach((id) => window.clearTimeout(id));
    };
  }, [isLoaded, pageViewEnabled, location.pathname, location.search]);

  return { isLoaded, pixelId };
};

import { useState, useCallback, useRef } from "react";
import useErrorHandler, { ErrorState } from "./useErrorHandler";

export interface LoadingState {
  conversations: boolean;
  messages: boolean;
  sending: boolean;
  retrying: boolean;
  initialLoad: boolean;
}

export interface RetryConfig {
  maxRetries: number;
  baseDelay: number;
  maxDelay: number;
  exponentialBackoff: boolean;
}

export interface UseLoadingWithRetryReturn {
  loading: LoadingState;
  error: ErrorState | null;
  retryCount: number;
  setLoading: (key: keyof LoadingState, value: boolean) => void;
  executeWithRetry: <T>(
    fn: () => Promise<T>,
    loadingKey?: keyof LoadingState,
    config?: Partial<RetryConfig>,
  ) => Promise<T>;
  retry: () => Promise<void>;
  clearError: () => void;
  isError: boolean;
}

const defaultRetryConfig: RetryConfig = {
  maxRetries: 3,
  baseDelay: 1000,
  maxDelay: 10000,
  exponentialBackoff: true,
};

const useLoadingWithRetry = (): UseLoadingWithRetryReturn => {
  const [loading, setLoadingState] = useState<LoadingState>({
    conversations: false,
    messages: false,
    sending: false,
    retrying: false,
    initialLoad: true,
  });

  const [retryCount, setRetryCount] = useState(0);
  const lastFailedFunction = useRef<(() => Promise<any>) | null>(null);
  const { error, handleError, clearError, isError } = useErrorHandler();

  const setLoading = useCallback((key: keyof LoadingState, value: boolean) => {
    setLoadingState((prev) => ({
      ...prev,
      [key]: value,
    }));
  }, []);

  const calculateDelay = (attempt: number, config: RetryConfig): number => {
    if (!config.exponentialBackoff) {
      return config.baseDelay;
    }

    const delay = config.baseDelay * Math.pow(2, attempt - 1);
    return Math.min(delay, config.maxDelay);
  };

  const sleep = (ms: number): Promise<void> => {
    return new Promise((resolve) => setTimeout(resolve, ms));
  };

  const executeWithRetry = useCallback(
    async <T>(
      fn: () => Promise<T>,
      loadingKey?: keyof LoadingState,
      config: Partial<RetryConfig> = {},
    ): Promise<T> => {
      const finalConfig = { ...defaultRetryConfig, ...config };
      let lastError: any;

      // حفظ الدالة للإعادة المحاولة لاحقاً
      lastFailedFunction.current = fn;

      // تعيين حالة التحميل
      if (loadingKey) {
        setLoading(loadingKey, true);
      }

      // مسح الأخطاء السابقة
      clearError();
      setRetryCount(0);

      for (let attempt = 1; attempt <= finalConfig.maxRetries + 1; attempt++) {
        try {
          // إظهار حالة إعادة المحاولة إذا لم تكن المحاولة الأولى
          if (attempt > 1) {
            setLoading("retrying", true);
            setRetryCount(attempt - 1);
          }

          const result = await fn();

          // نجحت العملية - مسح حالات التحميل
          if (loadingKey) {
            setLoading(loadingKey, false);
          }
          setLoading("retrying", false);
          setRetryCount(0);
          lastFailedFunction.current = null;

          return result;
        } catch (error) {
          lastError = error;
          console.warn(`Attempt ${attempt} failed:`, error);

          // إذا كانت هذه المحاولة الأخيرة، أو إذا كان الخطأ غير قابل للإعادة
          if (attempt > finalConfig.maxRetries) {
            break;
          }

          // التحقق من إمكانية إعادة المحاولة
          const errorType = error?.response?.status;
          if (errorType === 401 || errorType === 403 || errorType === 404) {
            // أخطاء غير قابلة للإعادة
            break;
          }

          // انتظار قبل المحاولة التالية
          const delay = calculateDelay(attempt, finalConfig);
          await sleep(delay);
        }
      }

      // فشلت جميع المحاولات
      if (loadingKey) {
        setLoading(loadingKey, false);
      }
      setLoading("retrying", false);

      handleError(lastError);
      throw lastError;
    },
    [setLoading, clearError, handleError],
  );

  const retry = useCallback(async (): Promise<void> => {
    if (lastFailedFunction.current) {
      try {
        await executeWithRetry(lastFailedFunction.current);
      } catch (error) {
        // الخطأ تم التعامل معه في executeWithRetry
      }
    }
  }, [executeWithRetry]);

  return {
    loading,
    error,
    retryCount,
    setLoading,
    executeWithRetry,
    retry,
    clearError,
    isError,
  };
};

export default useLoadingWithRetry;

import { useState, useEffect } from "react";
import { useParams, useSearchParams } from "react-router-dom";
import { storefrontApi, getCompanyId } from "../utils/storefrontApi";

export const useOrderConfirmation = () => {
  const { orderNumber } = useParams<{ orderNumber: string }>();
  const [searchParams] = useSearchParams();
  const companyId =
    searchParams.get("companyId") ||
    localStorage.getItem("currentCompanyId") ||
    getCompanyId();
  const phone = searchParams.get("phone")?.trim() || "";

  const [orderData, setOrderData] = useState<any>(null);
  const [loading, setLoading] = useState(Boolean(orderNumber && phone));
  const [fetchError, setFetchError] = useState<string | null>(null);

  useEffect(() => {
    if (!orderNumber) {
      setLoading(false);
      setOrderData(null);
      setFetchError("رقم الطلب غير متوفر");
      return;
    }

    if (!phone) {
      setLoading(false);
      setOrderData(null);
      setFetchError(null);
      return;
    }

    fetchOrderData(orderNumber, phone);
  }, [orderNumber, phone]);

  const fetchOrderData = async (orderId: string, phoneNumber: string) => {
    try {
      setLoading(true);
      setFetchError(null);
      const response = await storefrontApi.trackOrder(orderId, phoneNumber);
      if (response.success && response.data) {
        setOrderData(response.data);
        return;
      }
      setOrderData(null);
      setFetchError(response?.error || "تعذر جلب تفاصيل الطلب");
    } catch (error) {
      console.error("Error fetching order data:", error);
      setOrderData(null);
      setFetchError("حدث خطأ أثناء جلب تفاصيل الطلب");
    } finally {
      setLoading(false);
    }
  };

  return {
    orderNumber,
    phone,
    companyId,
    orderData,
    loading,
    fetchError,
  };
};

import { useState, useEffect, useCallback, useRef } from "react";
import useSocket from "./useSocket";
import { buildApiUrl } from "../utils/urlHelper";

export interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type: "text" | "image" | "file";
  isFromCustomer: boolean;
  status: "sending" | "sent" | "delivered" | "read";
  conversationId: string;
  fileUrl?: string;
  fileName?: string;
  fileSize?: number;
  voiceDuration?: number;
}

export interface Conversation {
  id: string;
  customerName: string;
  customerAvatar?: string;
  lastMessage: string;
  lastMessageTime: Date;
  unreadCount: number;
  isOnline: boolean;
  platform: "facebook" | "whatsapp" | "telegram";
  messages: Message[];
  pageName?: string; // اسم صفحة الفيسبوك
  pageId?: string; // معرف صفحة الفيسبوك
  aiEnabled?: boolean; // حالة الذكاء الاصطناعي
}

export interface TypingUser {
  userId: string;
  userName: string;
  conversationId: string;
  timestamp: Date;
}

export interface UseRealTimeMessagingReturn {
  conversations: Conversation[];
  selectedConversation: Conversation | null;
  typingUsers: TypingUser[];
  onlineUsers: string[];
  isConnected: boolean;
  isReconnecting: boolean;
  connectionError: string | null;

  // Actions
  selectConversation: (conversationId: string) => void;
  sendMessage: (
    conversationId: string,
    content: string,
    type?: Message["type"],
  ) => Promise<void>;
  markAsRead: (conversationId: string, messageId?: string) => void;
  startTyping: (conversationId: string) => void;
  stopTyping: (conversationId: string) => void;
  loadConversations: (searchQuery?: string) => Promise<void>;
  loadMessages: (conversationId: string) => Promise<void>;
}

// Helper to safely parse dates
const safeDate = (date: any): Date => {
  if (!date) return new Date();
  try {
    const parsed = new Date(date);
    // Check if date is valid
    if (isNaN(parsed.getTime())) {
      console.warn(
        "⚠️ [DATE-FIX] Invalid date detected, using current time:",
        date,
      );
      return new Date();
    }
    return parsed;
  } catch (e) {
    console.error("❌ [DATE-FIX] Error parsing date:", e);
    return new Date();
  }
};

const useRealTimeMessaging = (): UseRealTimeMessagingReturn => {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [typingUsers, setTypingUsers] = useState<TypingUser[]>([]);
  const [onlineUsers, setOnlineUsers] = useState<string[]>([]);

  const {
    socket,
    isConnected,
    isReconnecting,
    connectionError,
    emit,
    on,
    off,
  } = useSocket();
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // تحديث محادثة معينة
  const updateConversation = useCallback(
    (conversationId: string, updates: Partial<Conversation>) => {
      setConversations((prev) =>
        prev.map((conv) =>
          conv.id === conversationId ? { ...conv, ...updates } : conv,
        ),
      );

      if (selectedConversation?.id === conversationId) {
        setSelectedConversation((prev) =>
          prev ? { ...prev, ...updates } : null,
        );
      }
    },
    [selectedConversation],
  );

  // إضافة رسالة جديدة
  const addMessage = useCallback(
    (message: Message) => {
      const conversationId = message.conversationId;

      setConversations((prev) =>
        prev.map((conv) => {
          if (conv.id === conversationId) {
            const updatedMessages = [...conv.messages, message];
            return {
              ...conv,
              messages: updatedMessages,
              lastMessage: message.content,
              lastMessageTime: message.timestamp,
              unreadCount: message.isFromCustomer
                ? conv.unreadCount + 1
                : conv.unreadCount,
            };
          }
          return conv;
        }),
      );

      if (selectedConversation?.id === conversationId) {
        setSelectedConversation((prev) =>
          prev
            ? {
                ...prev,
                messages: [...prev.messages, message],
                lastMessage: message.content,
                lastMessageTime: message.timestamp,
              }
            : null,
        );
      }
    },
    [selectedConversation],
  );

  // تحديث حالة الرسالة
  const updateMessageStatus = useCallback(
    (messageId: string, status: Message["status"]) => {
      setConversations((prev) =>
        prev.map((conv) => ({
          ...conv,
          messages: conv.messages.map((msg) =>
            msg.id === messageId ? { ...msg, status } : msg,
          ),
        })),
      );

      if (selectedConversation) {
        setSelectedConversation((prev) =>
          prev
            ? {
                ...prev,
                messages: prev.messages.map((msg) =>
                  msg.id === messageId ? { ...msg, status } : msg,
                ),
              }
            : null,
        );
      }
    },
    [selectedConversation],
  );

  // تحميل المحادثات مع دعم البحث
  const loadConversations = useCallback(
    async (searchQuery?: string) => {
      try {
        const url = new URL(buildApiUrl("conversations"));
        if (searchQuery && searchQuery.trim()) {
          url.searchParams.append("search", searchQuery.trim());
        }

        const response = await fetch(url.toString());
        const result = await response.json();

        // التعامل مع الاستجابة الجديدة
        const data = result.success ? result.data : result;

        if (data && Array.isArray(data)) {
          console.log(
            "🔍 [CONVERSATIONS-DEBUG] Raw data from server:",
            data.slice(0, 2),
          ); // أول محادثتين فقط
          const formattedConversations = data.map((conv: any) => {
            console.log(
              "🔍 [CONVERSATION-DEBUG] Processing conversation:",
              conv.id,
              "aiEnabled:",
              conv.aiEnabled,
            );
            return {
              id: conv.id,
              customerId: conv.customerId,
              customerName:
                conv.customerName ||
                (conv.customer
                  ? `${conv.customer.firstName} ${conv.customer.lastName}`.trim() ||
                    conv.customer.email ||
                    "عميل غير معروف"
                  : "عميل غير معروف"),
              lastMessage:
                conv.lastMessage || conv.lastMessagePreview || "لا توجد رسائل",
              lastMessageTime: safeDate(
                conv.lastMessageTime || conv.lastMessageAt || Date.now(),
              ),
              unreadCount: conv.unreadCount || 0,
              platform:
                conv.platform || conv.channel?.toLowerCase() || "unknown",
              status: conv.status || "active",
              isOnline: onlineUsers.includes(conv.customerId),
              messages: [],
              aiEnabled: conv.aiEnabled !== undefined ? conv.aiEnabled : true, // إضافة حالة AI
              pageName: conv.pageName || null, // إضافة اسم الصفحة
              pageId: conv.pageId || null, // إضافة معرف الصفحة
            };
          });

          console.log(
            "✅ [CONVERSATIONS-DEBUG] Formatted conversations:",
            formattedConversations.slice(0, 2).map((c) => ({
              id: c.id,
              customerName: c.customerName,
              aiEnabled: c.aiEnabled,
            })),
          );
          setConversations(formattedConversations);
        }
      } catch (error) {
        console.error("Error loading conversations:", error);
      }
    },
    [onlineUsers],
  );

  // تحميل رسائل محادثة معينة
  const loadMessages = useCallback(
    async (conversationId: string) => {
      try {
        const response = await fetch(
          buildApiUrl(`conversations/${conversationId}/messages`),
        );
        const data = await response.json();

        if (data.success) {
          const formattedMessages = data.data.map((msg: any) => ({
            id: msg.id,
            content: msg.content,
            senderId: msg.senderId,
            senderName: msg.senderName || "مجهول",
            timestamp: safeDate(msg.createdAt),
            type:
              msg.type?.toLowerCase() === "image"
                ? "image"
                : msg.type?.toLowerCase() || "text",
            isFromCustomer: msg.isFromCustomer,
            status: msg.status || "sent",
            conversationId: conversationId,
            fileUrl:
              msg.fileUrl ||
              (msg.type?.toLowerCase() === "image" ? msg.content : undefined),
            fileName: msg.fileName,
            fileSize: msg.fileSize,
            voiceDuration: msg.voiceDuration,
          }));

          updateConversation(conversationId, { messages: formattedMessages });
        }
      } catch (error) {
        console.error("Error loading messages:", error);
      }
    },
    [updateConversation],
  );

  // اختيار محادثة
  const selectConversation = useCallback(
    (conversationId: string) => {
      const conversation = conversations.find(
        (conv) => conv.id === conversationId,
      );
      if (conversation) {
        setSelectedConversation(conversation);

        // تحميل الرسائل إذا لم تكن محملة
        if (conversation.messages.length === 0) {
          loadMessages(conversationId);
        }

        // تمييز الرسائل كمقروءة
        if (conversation.unreadCount > 0) {
          markAsRead(conversationId);
        }
      }
    },
    [conversations, loadMessages],
  );

  // إرسال رسالة
  const sendMessage = useCallback(
    async (
      conversationId: string,
      content: string,
      type: Message["type"] = "text",
    ) => {
      const tempId = `temp_${Date.now()}`;
      const tempMessage: Message = {
        id: tempId,
        content,
        senderId: "current_user",
        senderName: "أنت",
        timestamp: safeDate(new Date()),
        type,
        isFromCustomer: false,
        status: "sending",
        conversationId,
      };

      // إضافة الرسالة مؤقتاً
      addMessage(tempMessage);

      try {
        // إرسال عبر Socket.IO
        emit("send_message", {
          conversationId,
          content,
          type,
          tempId,
        });

        // إرسال عبر API كـ backup
        const response = await fetch(
          buildApiUrl(`conversations/${conversationId}/messages`),
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ content, type }),
          },
        );

        const data = await response.json();

        if (data.success) {
          // تحديث الرسالة المؤقتة بالبيانات الحقيقية
          updateMessageStatus(tempId, "sent");
        }
      } catch (error) {
        console.error("Error sending message:", error);
        updateMessageStatus(tempId, "sent"); // تمييز كمرسلة حتى لو فشل API
      }
    },
    [addMessage, emit, updateMessageStatus],
  );

  // تمييز كمقروء
  const markAsRead = useCallback(
    (conversationId: string, messageId?: string) => {
      emit("mark_as_read", { conversationId, messageId });
      updateConversation(conversationId, { unreadCount: 0 });
    },
    [emit, updateConversation],
  );

  // بدء الكتابة
  const startTyping = useCallback(
    (conversationId: string) => {
      emit("start_typing", { conversationId });
    },
    [emit],
  );

  // إيقاف الكتابة
  const stopTyping = useCallback(
    (conversationId: string) => {
      emit("stop_typing", { conversationId });

      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }
    },
    [emit],
  );

  // إعداد مستمعي الأحداث
  useEffect(() => {
    if (!socket || !isConnected) return;

    // رسالة جديدة
    const handleNewMessage = (message: any) => {
      console.log("🔔 [NEW-MESSAGE] Received message:", message);

      const formattedMessage: Message = {
        id: message.id,
        content: message.content,
        senderId: message.senderId,
        senderName: message.senderName,
        timestamp: safeDate(message.timestamp),
        type:
          message.type?.toLowerCase() === "image"
            ? "image"
            : message.type?.toLowerCase() || "text",
        isFromCustomer: message.isFromCustomer,
        status: "delivered",
        conversationId: message.conversationId,
        fileUrl:
          message.fileUrl ||
          (message.type?.toLowerCase() === "image"
            ? message.content
            : undefined),
        fileName: message.fileName,
        fileSize: message.fileSize,
        voiceDuration: message.voiceDuration,
      };

      console.log("🔄 [NEW-MESSAGE] Formatted message:", formattedMessage);
      addMessage(formattedMessage);
    };

    // تحديث حالة الرسالة
    const handleMessageDelivered = (data: any) => {
      updateMessageStatus(data.messageId, "delivered");
    };

    const handleMessageRead = (data: any) => {
      updateMessageStatus(data.messageId, "read");
    };

    // حالة الكتابة
    const handleUserTyping = (data: any) => {
      setTypingUsers((prev) => {
        const existing = prev.find(
          (user) =>
            user.userId === data.userId &&
            user.conversationId === data.conversationId,
        );

        if (existing) return prev;

        return [
          ...prev,
          {
            userId: data.userId,
            userName: data.userName,
            conversationId: data.conversationId,
            timestamp: safeDate(new Date()),
          },
        ];
      });
    };

    const handleUserStoppedTyping = (data: any) => {
      setTypingUsers((prev) =>
        prev.filter(
          (user) =>
            !(
              user.userId === data.userId &&
              user.conversationId === data.conversationId
            ),
        ),
      );
    };

    // حالة الاتصال
    const handleUserOnline = (data: any) => {
      setOnlineUsers((prev) => [...new Set([...prev, data.userId])]);
    };

    const handleUserOffline = (data: any) => {
      setOnlineUsers((prev) => prev.filter((id) => id !== data.userId));
    };

    // تسجيل المستمعين
    on("new_message", handleNewMessage);
    on("message_delivered", handleMessageDelivered);
    on("message_read", handleMessageRead);
    on("user_typing", handleUserTyping);
    on("user_stopped_typing", handleUserStoppedTyping);
    on("user_online", handleUserOnline);
    on("user_offline", handleUserOffline);

    return () => {
      off("new_message", handleNewMessage);
      off("message_delivered", handleMessageDelivered);
      off("message_read", handleMessageRead);
      off("user_typing", handleUserTyping);
      off("user_stopped_typing", handleUserStoppedTyping);
      off("user_online", handleUserOnline);
      off("user_offline", handleUserOffline);
    };
  }, [socket, isConnected, on, off, addMessage, updateMessageStatus]);

  // تنظيف مستخدمي الكتابة القدامى
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();
      setTypingUsers((prev) =>
        prev.filter(
          (user) => now.getTime() - user.timestamp.getTime() < 5000, // 5 ثوان
        ),
      );
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  return {
    conversations,
    selectedConversation,
    typingUsers,
    onlineUsers,
    isConnected,
    isReconnecting,
    connectionError,
    selectConversation,
    sendMessage,
    markAsRead,
    startTyping,
    stopTyping,
    loadConversations,
    loadMessages,
  };
};

export default useRealTimeMessaging;

import { useState, useEffect, useRef, useCallback } from "react";
import { io, Socket } from "socket.io-client";
import { buildWsUrl } from "../utils/urlHelper";
import { tokenManager } from "../utils/tokenManager";

export interface SocketEvents {
  // رسائل جديدة
  new_message: (message: any) => void;
  message_delivered: (data: { messageId: string; timestamp: Date }) => void;
  message_read: (data: { messageId: string; timestamp: Date }) => void;

  // حالة الكتابة
  user_typing: (data: {
    userId: string;
    userName: string;
    conversationId: string;
  }) => void;
  user_stopped_typing: (data: {
    userId: string;
    conversationId: string;
  }) => void;
  ai_typing: (data: {
    conversationId: string;
    isTyping: boolean;
    source?: string;
  }) => void;

  // حالة الاتصال
  user_online: (data: { userId: string; timestamp: Date }) => void;
  user_offline: (data: { userId: string; timestamp: Date }) => void;

  // تحديثات المحادثات
  conversation_updated: (conversation: any) => void;
  conversation_deleted: (conversationId: string) => void;
  "conversation:new": (conversation: any) => void;

  // إشعارات
  notification: (notification: any) => void;
}

export interface UseSocketReturn {
  socket: Socket | null;
  isConnected: boolean;
  isReconnecting: boolean;
  connectionError: string | null;
  emit: (event: string, data?: any) => void;
  on: <K extends keyof SocketEvents>(
    event: K,
    handler: SocketEvents[K],
  ) => void;
  off: <K extends keyof SocketEvents>(
    event: K,
    handler?: SocketEvents[K],
  ) => void;
  connect: () => void;
  disconnect: () => void;
}

const useSocket = (
  url: string = buildWsUrl(),
  options: any = {},
): UseSocketReturn => {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [isReconnecting, setIsReconnecting] = useState(false);
  const [connectionError, setConnectionError] = useState<string | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const reconnectAttempts = useRef(0);
  const maxReconnectAttempts = 5;

  const defaultOptions = {
    transports: ["websocket", "polling"],
    autoConnect: true,
    reconnection: true,
    reconnectionAttempts: maxReconnectAttempts,
    reconnectionDelay: 1000,
    reconnectionDelayMax: 5000,
    timeout: 20000,
    forceNew: false,
    ...options,
  };

  // إنشاء الاتصال
  const connect = useCallback(() => {
    if (socket?.connected) return;

    console.log("🔌 Connecting to Socket.IO server...");

    // Get fresh token for each connection attempt
    const token = tokenManager.getAccessToken();

    const connectionOptions = {
      ...defaultOptions,
      auth: {
        token: token,
      },
    };

    console.log(
      "🔑 [SOCKET-AUTH] Using token for connection:",
      token ? "Token present" : "No token",
    );

    const newSocket = io(url, connectionOptions);

    // معالجات الأحداث الأساسية
    newSocket.on("connect", () => {
      console.log("✅ Socket.IO connected successfully");
      setIsConnected(true);
      setIsReconnecting(false);
      setConnectionError(null);
      reconnectAttempts.current = 0;

      // إرسال معلومات المستخدم عند الاتصال مع دعم عزل الشركات
      const userData = localStorage.getItem("user");
      if (userData) {
        try {
          const user = JSON.parse(userData);
          if (!user) {
            console.warn("⚠️ [SOCKET-JOIN] User data is null after parsing");
            return;
          }

          const userJoinData = {
            userId: user.id || user._id,
            userName:
              `${user.firstName || ""} ${user.lastName || ""}`.trim() ||
              user.email ||
              "مستخدم",
            companyId: user.companyId,
          };

          console.log(
            "🔌 [SOCKET-JOIN] Sending user_join with company isolation:",
            userJoinData,
          );
          newSocket.emit("user_join", userJoinData);

          // Add main listener for new messages
          newSocket.on("new_message", (data) => {
            console.log("📨 [NEW-MESSAGE] Received new message:", data);
            console.log(
              "📨 [NEW-MESSAGE] Message conversation:",
              data.conversationId,
            );
            console.log("📨 [NEW-MESSAGE] Message type:", data.type);
            console.log(
              "📨 [NEW-MESSAGE] Is from customer:",
              data.isFromCustomer,
            );
            // This will be handled by the conversation components
          });
        } catch (error) {
          console.error("❌ [SOCKET-JOIN] Error parsing user data:", error);
        }
      } else {
        console.warn(
          "⚠️ [SOCKET-JOIN] No user data found for Socket.IO connection",
        );
      }
    });

    newSocket.on("disconnect", (reason) => {
      console.log("❌ Socket.IO disconnected:", reason);
      setIsConnected(false);

      if (reason === "io server disconnect") {
        // الخادم قطع الاتصال، إعادة الاتصال يدوياً
        newSocket.connect();
      }
    });

    newSocket.on("connect_error", (error) => {
      console.error("🔥 Socket.IO connection error:", error);
      setConnectionError(error.message);
      setIsConnected(false);

      reconnectAttempts.current++;
      if (reconnectAttempts.current < maxReconnectAttempts) {
        setIsReconnecting(true);
        const delay = Math.min(
          1000 * Math.pow(2, reconnectAttempts.current),
          10000,
        );

        reconnectTimeoutRef.current = setTimeout(() => {
          console.log(
            `🔄 Reconnection attempt ${reconnectAttempts.current + 1}/${maxReconnectAttempts}`,
          );
          newSocket.connect();
        }, delay);
      } else {
        setIsReconnecting(false);
        setConnectionError("فشل في الاتصال بالخادم بعد عدة محاولات");
      }
    });

    newSocket.on("reconnect", (attemptNumber) => {
      console.log(`🔄 Socket.IO reconnected after ${attemptNumber} attempts`);
      setIsReconnecting(false);
      reconnectAttempts.current = 0;
    });

    newSocket.on("reconnect_attempt", (attemptNumber) => {
      console.log(`🔄 Socket.IO reconnection attempt ${attemptNumber}`);
      setIsReconnecting(true);
    });

    newSocket.on("reconnect_failed", () => {
      console.error("💥 Socket.IO failed to reconnect");
      setIsReconnecting(false);
      setConnectionError("فشل في إعادة الاتصال بالخادم");
    });

    setSocket(newSocket);
  }, [url, defaultOptions]);

  // قطع الاتصال
  const disconnect = useCallback(() => {
    if (socket) {
      console.log("🔌 Disconnecting from Socket.IO server...");
      socket.disconnect();
      setSocket(null);
      setIsConnected(false);
      setIsReconnecting(false);
    }

    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }
  }, [socket]);

  // إرسال حدث
  const emit = useCallback(
    (event: string, data?: any) => {
      if (socket?.connected) {
        socket.emit(event, data);
      } else {
        console.warn("⚠️ Cannot emit event: Socket not connected");
      }
    },
    [socket],
  );

  // الاستماع لحدث
  const on = useCallback(
    <K extends keyof SocketEvents>(event: K, handler: SocketEvents[K]) => {
      if (socket) {
        socket.on(event as string, handler as any);
      }
    },
    [socket],
  );

  // إلغاء الاستماع لحدث
  const off = useCallback(
    <K extends keyof SocketEvents>(event: K, handler?: SocketEvents[K]) => {
      if (socket) {
        if (handler) {
          socket.off(event as string, handler as any);
        } else {
          socket.off(event as string);
        }
      }
    },
    [socket],
  );

  // تنظيف عند إلغاء المكون
  useEffect(() => {
    return () => {
      disconnect();
    };
  }, []); // إزالة disconnect من dependencies لتجنب الحلقة اللانهائية

  // الاتصال التلقائي
  useEffect(() => {
    if (defaultOptions.autoConnect) {
      connect();
    }
  }, []); // إزالة connect من dependencies لتجنب الحلقة اللانهائية

  return {
    socket,
    isConnected,
    isReconnecting,
    connectionError,
    emit,
    on,
    off,
    connect,
    disconnect,
  };
};

