import React, {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
} from "react";
import { io, Socket } from "socket.io-client";
import { useAuth } from "./useAuthSimple";
import { config } from "../config";
import { tokenManager } from "../utils/tokenManager";

/**
 * Socket.IO Hook and Context
 *
 * Provides real-time communication throughout the application
 */

interface SocketContextType {
  socket: Socket | null;
  isConnected: boolean;
  emit: (event: string, data?: any) => void;
  on: (event: string, callback: (data: any) => void) => void;
  off: (event: string, callback?: (data: any) => void) => void;
  joinRoom: (room: string) => void;
  leaveRoom: (room: string) => void;
}

const SocketContext = createContext<SocketContextType | undefined>(undefined);

interface SocketProviderProps {
  children: ReactNode;
}

export const SocketProvider: React.FC<SocketProviderProps> = ({ children }) => {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const { user, isAuthenticated } = useAuth();

  useEffect(() => {
    if (!isAuthenticated || !user) {
      // Disconnect socket if user is not authenticated
      if (socket) {
        socket.disconnect();
        setSocket(null);
        setIsConnected(false);
      }
      return;
    }

    // Create socket connection
    const newSocket = io(config.wsUrl, {
      auth: {
        token: tokenManager.getAccessToken(),
      },
      transports: ["websocket", "polling"],
      timeout: 20000,
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
    });

    // Connection event handlers
    newSocket.on("connect", () => {
      console.log("Socket connected:", newSocket.id);
      setIsConnected(true);

      // 🔐 Send user_join with company isolation support
      if (user) {
        const userJoinData = {
          userId: user.id,
          userName: `${user.firstName} ${user.lastName}`.trim() || user.email,
          companyId: user.companyId,
        };

        console.log(
          "🏢 [SOCKET-CONTEXT] Sending user_join with company isolation:",
          userJoinData,
        );
        newSocket.emit("user_join", userJoinData);
      }
    });

    newSocket.on("disconnect", (reason) => {
      console.log("Socket disconnected:", reason);
      setIsConnected(false);
    });

    newSocket.on("connect_error", (error) => {
      console.error("Socket connection error:", error);
      setIsConnected(false);
    });

    newSocket.on("reconnect", (attemptNumber) => {
      console.log("Socket reconnected after", attemptNumber, "attempts");
      setIsConnected(true);
    });

    newSocket.on("reconnect_error", (error) => {
      console.error("Socket reconnection error:", error);
    });

    newSocket.on("reconnect_failed", () => {
      console.error("Socket reconnection failed");
      setIsConnected(false);
    });

    // Authentication events
    newSocket.on("authenticated", (data) => {
      console.log("Socket authenticated:", data);
    });

    newSocket.on("unauthorized", (error) => {
      console.error("Socket authentication failed:", error);
      newSocket.disconnect();
    });

    // Global event handlers
    newSocket.on("notification", (notification) => {
      // Handle global notifications
      console.log("Received notification:", notification);

      // You can dispatch to a notification store or show toast
      // notificationStore.addNotification(notification);
    });

    newSocket.on("system_announcement", (announcement) => {
      // Handle system announcements
      console.log("System announcement:", announcement);
    });

    newSocket.on("user_status_changed", (data) => {
      // Handle user status changes
      console.log("User status changed:", data);
    });

    setSocket(newSocket);

    // Cleanup on unmount
    return () => {
      newSocket.disconnect();
      setSocket(null);
      setIsConnected(false);
    };
  }, [isAuthenticated, user]);

  // Helper functions
  const emit = (event: string, data?: any) => {
    if (socket && isConnected) {
      socket.emit(event, data);
    } else {
      console.warn("Socket not connected. Cannot emit event:", event);
    }
  };

  const on = (event: string, callback: (data: any) => void) => {
    if (socket) {
      socket.on(event, callback);
    }
  };

  const off = (event: string, callback?: (data: any) => void) => {
    if (socket) {
      if (callback) {
        socket.off(event, callback);
      } else {
        socket.off(event);
      }
    }
  };

  const joinRoom = (room: string) => {
    emit("join_room", room);
  };

  const leaveRoom = (room: string) => {
    emit("leave_room", room);
  };

  const contextValue: SocketContextType = {
    socket,
    isConnected,
    emit,
    on,
    off,
    joinRoom,
    leaveRoom,
  };

  return (
    <SocketContext.Provider value={contextValue}>
      {children}
    </SocketContext.Provider>
  );
};

export const useSocket = (): SocketContextType => {
  const context = useContext(SocketContext);
  if (context === undefined) {
    throw new Error("useSocket must be used within a SocketProvider");
  }
  return context;
};

import React, {
  createContext,
  useContext,
  useEffect,
  useLayoutEffect,
  useState,
  ReactNode,
} from "react";
import { useLocation } from "react-router-dom";

/**
 * Theme Hook and Context
 *
 * Provides theme management (light/dark mode) throughout the application
 */

type Theme = "light" | "dark" | "system";
type DarkStyle = "classic" | "midnight" | "oled" | "aurora" | "amethyst" | "royal";

interface ThemeContextType {
  theme: Theme;
  actualTheme: "light" | "dark";
  derivedTheme: "light" | "dark";
  darkStyle: DarkStyle;
  setTheme: (theme: Theme) => void;
  setDarkStyle: (style: DarkStyle) => void;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

interface ThemeProviderProps {
  children: ReactNode;
  defaultTheme?: Theme;
}

export const ThemeProvider: React.FC<ThemeProviderProps> = ({
  children,
  defaultTheme = "light",
}) => {
  const [theme, setThemeState] = useState<Theme>(() => {
    // Get theme from localStorage or use default
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem("theme") as Theme;
      return stored || defaultTheme;
    }
    return defaultTheme;
  });

  const [actualTheme, setActualTheme] = useState<"light" | "dark">("light");
  const [darkStyle, setDarkStyleState] = useState<DarkStyle>(() => {
    if (typeof window === "undefined") return "classic";
    const stored = localStorage.getItem("dark-style");
    if (
      stored === "classic" ||
      stored === "midnight" ||
      stored === "oled" ||
      stored === "aurora" ||
      stored === "amethyst" ||
      stored === "royal"
    ) {
      return stored;
    }
    return "classic";
  });
  const location = useLocation();

  // If user has no saved theme yet, default analytics to dark on first visit
  useEffect(() => {
    if (typeof window === "undefined") return;
    const stored = localStorage.getItem("theme");
    if (!stored && location.pathname.startsWith("/analytics")) {
      setThemeState("dark");
      localStorage.setItem("theme", "dark");
    }
  }, [location.pathname]);

  // Get system theme preference
  const getSystemTheme = (): "light" | "dark" => {
    if (typeof window !== "undefined") {
      return window.matchMedia("(prefers-color-scheme: dark)").matches
        ? "dark"
        : "light";
    }
    return "light";
  };

  // Update actual theme based on theme setting
  useEffect(() => {
    const updateActualTheme = () => {
      if (theme === "system") {
        setActualTheme(getSystemTheme());
      } else {
        setActualTheme(theme);
      }
    };

    updateActualTheme();

    // Listen for system theme changes
    if (theme === "system") {
      const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
      const handleChange = () => updateActualTheme();

      mediaQuery.addEventListener("change", handleChange);
      return () => mediaQuery.removeEventListener("change", handleChange);
    }

    return undefined;
  }, [theme]);

  // Calculate derived theme (effective theme) based on route
  const currentPath = location.pathname;
  // Check if we are in a storefront route including public pages
  const isStorefront =
    currentPath.startsWith("/shop") ||
    currentPath.startsWith("/home") ||
    currentPath.startsWith("/woodmart-replica") ||
    (currentPath.startsWith("/auth") &&
      !currentPath.startsWith("/auth/admin")) || // Assume auth pages are public/light? No, let's stick to known storefront
    currentPath === "/test-minimal" ||
    currentPath === "/test-public";

  // Routes that should be forced to dark mode
  const isDarkForced =
    currentPath.startsWith("/monitor-reports") ||
    currentPath.startsWith("/alert-settings") ||
    currentPath.startsWith("/support"); // Force dark mode for all support pages including FAQ

  // Analytics routes should NEVER be forced to dark mode - they respect user's theme choice
  const isAnalytics = currentPath.startsWith("/analytics");

  let derivedTheme = isStorefront ? "light" : actualTheme;

  // Only force dark mode if not in analytics section
  if (isDarkForced && !isAnalytics) {
    derivedTheme = "dark";
  }

  // Apply theme to document
  useLayoutEffect(() => {
    const root = document.documentElement;

    // Remove existing theme classes
    root.classList.remove("light", "dark");

    // Tailwind darkMode is class-based and expects only the 'dark' class
    if (derivedTheme === "dark") {
      root.classList.add("dark");
      root.setAttribute("data-dark-style", darkStyle);
    } else {
      root.removeAttribute("data-dark-style");
    }

    // Update meta theme-color
    const metaThemeColor = document.querySelector('meta[name="theme-color"]');
    if (metaThemeColor) {
      const darkThemeColor =
        darkStyle === "midnight"
          ? "#081223"
          : darkStyle === "oled"
            ? "#000000"
            : darkStyle === "aurora"
              ? "#061018"
              : darkStyle === "amethyst"
                ? "#120b1f"
                : darkStyle === "royal"
                  ? "#140b33"
                  : "#030712";
      metaThemeColor.setAttribute(
        "content",
        derivedTheme === "dark" ? darkThemeColor : "#ffffff",
      );
    }
  }, [derivedTheme, darkStyle]); // Depend on derivedTheme

  // Set theme and persist to localStorage
  const setTheme = (newTheme: Theme) => {
    setThemeState(newTheme);
    if (typeof window !== "undefined") {
      localStorage.setItem("theme", newTheme);
    }
  };

  const setDarkStyle = (style: DarkStyle) => {
    setDarkStyleState(style);
    if (typeof window !== "undefined") {
      localStorage.setItem("dark-style", style);
    }
  };

  // Toggle between light and dark (ignoring system)
  const toggleTheme = () => {
    if (theme === "system") {
      // If currently system, switch to opposite of current system theme
      const systemTheme = getSystemTheme();
      setTheme(systemTheme === "dark" ? "light" : "dark");
    } else {
      // Toggle between light and dark
      setTheme(theme === "light" ? "dark" : "light");
    }
  };

  const contextValue: ThemeContextType = {
    theme,
    actualTheme,
    derivedTheme, // Expose the effective theme
    darkStyle,
    setTheme,
    setDarkStyle,
    toggleTheme,
  };

  return (
    <ThemeContext.Provider value={contextValue}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = (): ThemeContextType => {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }
  return context;
};

import { useEffect, useRef, useState } from "react";
import { useLocation } from "react-router-dom";
import {
  loadTikTokPixel,
  trackTikTokPageView,
  configureTikTokPixel,
} from "../utils/tiktokPixel";
import { storefrontSettingsService } from "../services/storefrontSettingsService";

export const useTikTokPixel = (companyId: string | undefined) => {
  const location = useLocation();
  const [isLoaded, setIsLoaded] = useState(false);
  const [pixelId, setPixelId] = useState<string | null>(null);
  const [pageViewEnabled, setPageViewEnabled] = useState(false);
  const lastTrackedPathRef = useRef<string>("");

  useEffect(() => {
    if (!companyId) {
      return;
    }

    setIsLoaded(false);
    setPixelId(null);
    setPageViewEnabled(false);

    const loadPixelSettings = async () => {
      try {
        const response = await storefrontSettingsService.getPublicSettings(
          companyId,
          true,
        );

        if (response.success && response.data) {
          const settings = response.data;
          if (typeof window !== "undefined") {
            const win = window as any;
            win.__storefrontSettings = settings;
            try {
              const cacheKey = companyId
                ? `storefront_settings_cache_${companyId}`
                : null;
              if (cacheKey) {
                localStorage.setItem(cacheKey, JSON.stringify(settings));
              }
            } catch {
              // ignore storage failures
            }
          }
          if (settings.gtmEnabled && settings.gtmSuppressPixels) {
            return;
          }

          if (settings.tiktokPixelEnabled && settings.tiktokPixelId) {
            configureTikTokPixel({
              trackPageView: settings.tiktokTrackPageView !== false,
              trackViewContent: settings.tiktokTrackViewContent !== false,
              trackAddToCart: settings.tiktokTrackAddToCart !== false,
              trackInitiateCheckout:
                settings.tiktokTrackInitiateCheckout !== false,
              trackPurchase: settings.tiktokTrackPurchase !== false,
              trackSearch: settings.tiktokTrackSearch !== false,
              trackAddToWishlist: settings.tiktokTrackAddToWishlist === true,
            });

            loadTikTokPixel(settings.tiktokPixelId);
            setPixelId(settings.tiktokPixelId);
            setIsLoaded(true);
            setPageViewEnabled(settings.tiktokTrackPageView !== false);
          }
        }
      } catch (error) {
        console.error("[TikTok Pixel] Error loading settings:", error);
      }
    };

    loadPixelSettings();
  }, [companyId]);

  useEffect(() => {
    if (!isLoaded || !pageViewEnabled) {
      return;
    }

    const currentPath = `${location.pathname}${location.search}`;
    if (lastTrackedPathRef.current === currentPath) {
      return;
    }

    trackTikTokPageView();
    lastTrackedPathRef.current = currentPath;
  }, [isLoaded, pageViewEnabled, location.pathname, location.search]);

  return { isLoaded, pixelId };
};

