      return;
    }

    try {
      setLoading(true);
      setSearched(true);

      const data = await storefrontApi.trackOrder(orderNumber, phone);

      if (data.success) {
        setOrder(data.data);
      } else {
        setOrder(null);
        toast.error(data.error || "الطلب غير موجود");
      }
    } catch (error) {
      console.error("Error tracking order:", error);
      toast.error("حدث خطأ في تتبع الطلب");
      setOrder(null);
    } finally {
      setLoading(false);
    }
  };

  const getStatusText = (status: string) => {
    const statusMap: Record<string, string> = {
      PENDING: "قيد المعالجة",
      CONFIRMED: "تم التأكيد",
      PROCESSING: "جاري التجهيز",
      SHIPPED: "تم الشحن",
      DELIVERED: "تم التوصيل",
      CANCELLED: "ملغي",
    };
    return statusMap[status] || status;
  };

  const getStatusColor = (status: string) => {
    const colorMap: Record<string, string> = {
      PENDING: "bg-yellow-100 text-yellow-800",
      CONFIRMED: "bg-blue-100 text-blue-800",
      PROCESSING: "bg-purple-100 text-purple-800",
      SHIPPED: "bg-indigo-100 text-indigo-800",
      DELIVERED: "bg-green-100 text-green-800",
      CANCELLED: "bg-red-100 text-red-800",
    };
    return colorMap[status] || "bg-gray-100 text-gray-800";
  };

  return {
    orderNumber,
    setOrderNumber,
    phone,
    setPhone,
    order,
    loading,
    searched,
    handleSearch,
    getStatusText,
    getStatusColor,
  };
};

import {
  useMutation,
  useQueryClient,
  UseMutationOptions,
} from "@tanstack/react-query";
import { apiClient as api } from "../services/apiClient";
import { indexedDBStorage } from "../services/indexedDBStorage";
import { Message, Contact } from "./useWhatsAppQueries";

/**
 * WhatsApp Mutations Hooks
 *
 * Custom hooks for mutations (send, delete, update) with optimistic updates
 */

interface SendMessageParams {
  sessionId: string;
  to: string;
  text: string;
  quotedMessageId?: string;
  userId?: string;
}

interface SendMediaParams {
  sessionId: string;
  to: string;
  file: File;
  caption?: string;
  userId?: string;
}

interface MarkAsReadParams {
  sessionId: string;
  remoteJid: string;
}

interface DeleteConversationParams {
  conversationId: string;
  jid: string;
  sessionId: string;
}

interface ArchiveConversationParams {
  jid: string;
  sessionId: string;
  isArchived: boolean;
}

/**
 * Hook to send a text message with optimistic update
 */
export const useSendMessage = (
  options?: Omit<
    UseMutationOptions<any, Error, SendMessageParams>,
    "mutationFn"
  >,
) => {
  const queryClient = useQueryClient();

  return useMutation<any, Error, SendMessageParams>({
    mutationFn: async (params) => {
      const response = await api.post("/whatsapp/messages/send", params);
      return response.data;
    },
    onMutate: async (variables) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({
        queryKey: ["whatsapp", "messages", variables.to, variables.sessionId],
      });

      // Snapshot previous value
      const previousMessages = queryClient.getQueryData([
        "whatsapp",
        "messages",
        variables.to,
        variables.sessionId,
      ]);

      // Optimistically update messages
      const optimisticMessage: Message = {
        id: `temp-${Date.now()}`,
        messageId: `temp-${Date.now()}`,
        remoteJid: variables.to,
        fromMe: true,
        messageType: "TEXT",
        content: variables.text,
        mediaUrl: null,
        mediaType: null,
        mediaFileName: null,
        quotedMessageId: variables.quotedMessageId || null,
        quotedContent: null,
        status: "PENDING",
        timestamp: new Date().toISOString(),
        isAIResponse: false,
        aiConfidence: null,
      };

      queryClient.setQueryData(
        ["whatsapp", "messages", variables.to, variables.sessionId],
        (old: any) => {
          if (!old) return old;
          const newPages = old.pages.map((page: any, index: number) => {
            if (index === old.pages.length - 1) {
              return {
                ...page,
                messages: [...(page.messages || []), optimisticMessage],
              };
            }
            return page;
          });
          return { ...old, pages: newPages };
        },
      );

      // Update conversations list
      queryClient.setQueryData(
        ["whatsapp", "conversations", variables.sessionId, 30],
        (old: any) => {
          if (!old || !old.pages || old.pages.length === 0) return old;
          // Update first page (most recent conversations)
          const firstPage = old.pages[0];
          const updatedConversations = firstPage.conversations.map(
            (conv: Contact) => {
              if (conv.jid === variables.to) {
                return {
                  ...conv,
                  lastMessage: {
                    content: variables.text,
                    messageType: "TEXT",
                    fromMe: true,
                    timestamp: new Date().toISOString(),
                  },
                  lastMessageAt: new Date().toISOString(),
                };
              }
              return conv;
            },
          );
          return {
            ...old,
            pages: [
              {
                ...firstPage,
                conversations: updatedConversations,
              },
              ...old.pages.slice(1),
            ],
          };
        },
      );

      return { previousMessages };
    },
    onError: (err, variables, context) => {
      // Rollback on error
      if (context?.previousMessages) {
        queryClient.setQueryData(
          ["whatsapp", "messages", variables.to, variables.sessionId],
          context.previousMessages,
        );
      }
    },
    onSuccess: (data, variables) => {
      // Invalidate to refetch with real data
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "messages", variables.to, variables.sessionId],
      });
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "conversations", variables.sessionId],
      });

      // Invalidate IndexedDB cache
      const cacheKey = `whatsapp_messages_${variables.to}_${variables.sessionId}`;
      indexedDBStorage.removeItem(cacheKey).catch(console.error);
    },
    ...options,
  });
};

/**
 * Hook to send media with optimistic update
 */
export const useSendMedia = (
  options?: Omit<UseMutationOptions<any, Error, SendMediaParams>, "mutationFn">,
) => {
  const queryClient = useQueryClient();

  return useMutation<any, Error, SendMediaParams>({
    mutationFn: async (params) => {
      const formData = new FormData();
      formData.append("sessionId", params.sessionId);
      formData.append("to", params.to);
      formData.append("file", params.file);
      if (params.caption) formData.append("caption", params.caption);
      if (params.userId) formData.append("userId", params.userId);

      const response = await api.post(
        "/whatsapp/messages/send-media",
        formData,
        {
          headers: { "Content-Type": "multipart/form-data" },
        },
      );
      return response.data;
    },
    onSuccess: (data, variables) => {
      // Invalidate queries to refetch
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "messages", variables.to, variables.sessionId],
      });
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "conversations", variables.sessionId],
      });

      // Invalidate IndexedDB cache
      const cacheKey = `whatsapp_messages_${variables.to}_${variables.sessionId}`;
      indexedDBStorage.removeItem(cacheKey).catch(console.error);
    },
    ...options,
  });
};

/**
 * Hook to mark conversation as read
 */
export const useMarkAsRead = (
  options?: Omit<
    UseMutationOptions<any, Error, MarkAsReadParams>,
    "mutationFn"
  >,
) => {
  const queryClient = useQueryClient();

  return useMutation<any, Error, MarkAsReadParams>({
    mutationFn: async (params) => {
      // Use shorter timeout for mark as read (10 seconds instead of 30)
      const response = await api.post("/whatsapp/messages/read", params, {
        timeout: 10000,
      });
      return response.data;
    },
    retry: false, // ✅ منع المحاولات المتكررة عند فشل الاتصال
    onMutate: async (variables) => {
      // Optimistically update unread count
      queryClient.setQueryData(
        ["whatsapp", "conversations", variables.sessionId, 30],
        (old: any) => {
          if (!old || !old.pages || old.pages.length === 0) return old;
          const firstPage = old.pages[0];
          const updatedConversations = firstPage.conversations.map(
            (conv: Contact) => {
              if (conv.jid === variables.remoteJid) {
                return { ...conv, unreadCount: 0 };
              }
              return conv;
            },
          );
          return {
            ...old,
            pages: [
              {
                ...firstPage,
                conversations: updatedConversations,
              },
              ...old.pages.slice(1),
            ],
          };
        },
      );
    },
    onSuccess: (data, variables) => {
      // Invalidate to ensure consistency
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "conversations", variables.sessionId],
      });
    },
    ...options,
  });
};

/**
 * Hook to delete a conversation
 */
export const useDeleteConversation = (
  options?: Omit<
    UseMutationOptions<any, Error, DeleteConversationParams>,
    "mutationFn"
  >,
) => {
  const queryClient = useQueryClient();

  return useMutation<any, Error, DeleteConversationParams>({
    mutationFn: async (params) => {
      const response = await api.delete(
        `/whatsapp/conversations/${params.conversationId}`,
      );
      return response.data;
    },
    onMutate: async (variables) => {
      // Optimistically remove from list
      queryClient.setQueryData(
        ["whatsapp", "conversations", variables.sessionId, 30],
        (old: any) => {
          if (!old || !old.pages || old.pages.length === 0) return old;
          const firstPage = old.pages[0];
          return {
            ...old,
            pages: [
              {
                ...firstPage,
                conversations: firstPage.conversations.filter(
                  (conv: Contact) => conv.id !== variables.conversationId,
                ),
              },
              ...old.pages.slice(1),
            ],
          };
        },
      );
    },
    onSuccess: (data, variables) => {
      // Invalidate queries
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "conversations", variables.sessionId],
      });
      queryClient.removeQueries({
        queryKey: ["whatsapp", "messages", variables.jid, variables.sessionId],
      });

      // Remove from IndexedDB cache
      const cacheKey = `whatsapp_messages_${variables.jid}_${variables.sessionId}`;
      indexedDBStorage.removeItem(cacheKey).catch(console.error);
    },
    onError: (err, variables) => {
      // Rollback on error
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "conversations", variables.sessionId],
      });
    },
    ...options,
  });
};

/**
 * Hook to archive/unarchive a conversation
 */
export const useArchiveConversation = (
  options?: Omit<
    UseMutationOptions<any, Error, ArchiveConversationParams>,
    "mutationFn"
  >,
) => {
  const queryClient = useQueryClient();

  return useMutation<any, Error, ArchiveConversationParams>({
    mutationFn: async (params) => {
      const response = await api.put(
        `/whatsapp/conversations/${params.jid}/archive`,
        {
          sessionId: params.sessionId,
          isArchived: params.isArchived,
        },
      );
      return response.data;
    },
    onMutate: async (variables) => {
      // Optimistically update archive status
      queryClient.setQueryData(
        ["whatsapp", "conversations", variables.sessionId, 30],
        (old: any) => {
          if (!old || !old.pages || old.pages.length === 0) return old;
          const firstPage = old.pages[0];
          const updatedConversations = firstPage.conversations.map(
            (conv: Contact) => {
              if (conv.jid === variables.jid) {
                return { ...conv, isArchived: variables.isArchived };
              }
              return conv;
            },
          );
          return {
            ...old,
            pages: [
              {
                ...firstPage,
                conversations: updatedConversations,
              },
              ...old.pages.slice(1),
            ],
          };
        },
      );
    },
    onSuccess: (data, variables) => {
      // Invalidate to ensure consistency
      queryClient.invalidateQueries({
        queryKey: ["whatsapp", "conversations", variables.sessionId],
      });
    },
    ...options,
  });
};

import { useState, useEffect } from "react";
import { toast } from "react-hot-toast";
import { wishlistApi } from "../utils/wishlistApi";
import { storefrontApi, getCompanyId } from "../utils/storefrontApi";
import { storefrontSettingsService } from "../services/storefrontSettingsService";

export interface WishlistItem {
  id: string;
  productId: string;
  variantId?: string;
  product: {
    id: string;
    name: string;
    slug?: string;
    price: number;
    comparePrice?: number;
    images: string | string[];
    stock: number;
    category?: {
      id: string;
      name: string;
    };
  };
  createdAt: string;
}

export const useWishlistPage = () => {
  const [items, setItems] = useState<WishlistItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [storefrontSettings, setStorefrontSettings] = useState<any>(null);

  useEffect(() => {
    fetchWishlist();
    fetchStorefrontSettings();
  }, []);

  const fetchStorefrontSettings = async () => {
    try {
      const companyId = getCompanyId();
      if (companyId) {
        const data = await storefrontSettingsService.getPublicSettings(companyId);
        if (data.success) {
          setStorefrontSettings(data.data);
        }
      }
    } catch (error) {
      console.error("Error fetching storefront settings:", error);
    }
  };

  const fetchWishlist = async () => {
    try {
      setLoading(true);
      const data = await wishlistApi.getWishlist();
      if (data.success) {
        setItems(data.data.items || []);
      }
    } catch (error) {
      console.error("Error fetching wishlist:", error);
      toast.error("حدث خطأ في جلب قائمة الرغبات");
    } finally {
      setLoading(false);
    }
  };

  const handleRemove = async (itemId: string, productId: string, variantId?: string) => {
    try {
      await wishlistApi.removeFromWishlist(productId, variantId);
      setItems((prev) => prev.filter((item) => item.id !== itemId));
      toast.success("تم حذف المنتج من المفضلة");
      window.dispatchEvent(new Event("wishlistUpdated"));
    } catch (error) {
      console.error("Error removing from wishlist:", error);
      toast.error("حدث خطأ في حذف المنتج");
    }
  };

  const handleAddToCart = async (productId: string, variantId?: string) => {
    try {
      await storefrontApi.addToCart({
        productId,
        quantity: 1,
        ...(variantId && { variantId }),
      });
      toast.success("تمت إضافة المنتج للسلة");
      window.dispatchEvent(new Event("cartUpdated"));
    } catch (error) {
      console.error("Error adding to cart:", error);
      toast.error("حدث خطأ في إضافة المنتج");
    }
  };

  const handleClearAll = async () => {
    if (!confirm("هل أنت متأكد من مسح جميع المنتجات من المفضلة؟")) return;

    try {
      await wishlistApi.clearWishlist();
      setItems([]);
      toast.success("تم مسح قائمة الرغبات");
      window.dispatchEvent(new Event("wishlistUpdated"));
    } catch (error) {
      console.error("Error clearing wishlist:", error);
      toast.error("حدث خطأ في مسح القائمة");
    }
  };

  const parseImages = (images: string | string[]): string[] => {
    if (Array.isArray(images)) return images;
    if (typeof images === "string") {
      try {
        return JSON.parse(images);
      } catch {
        return [images];
      }
    }
    return [];
  };

  return {
    items,
    loading,
    storefrontSettings,
    handleRemove,
    handleAddToCart,
    handleClearAll,
    parseImages,
    fetchWishlist,
  };
};

