export default ConversionRateAnalytics;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  TicketIcon,
  XCircleIcon,
  ExclamationTriangleIcon,
} from "@heroicons/react/24/outline";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip } from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";
import { useCurrency } from "../../../hooks/useCurrency";

interface CouponStats {
  coupons: Array<{
    code: string;
    usageCount: number;
    discountAmount: number;
    revenue: number;
  }>;
  totalDiscounts: number;
  totalCouponOrders: number;
}

const CouponsAnalytics: React.FC = () => {
  const { t } = useTranslation();
  const { formatPrice } = useCurrency();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<CouponStats | null>(null);

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await analyticsService.getCouponsAnalytics(period);
      if (response.success) {
        const data = response.data || {};
        setStats({
          coupons: data.coupons || [],
          totalDiscounts: data.totalDiscounts || 0,
          totalCouponOrders: data.totalCouponOrders || 0,
        });
      }
    } catch (err: any) {
      setError(err.message || t("couponsAnalytics.fetchError"));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          {t("couponsAnalytics.retry")}
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {t("couponsAnalytics.title")}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("couponsAnalytics.subtitle")}
          </p>
        </div>
        <select
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="7">{t("couponsAnalytics.last7Days")}</option>
          <option value="30">{t("couponsAnalytics.last30Days")}</option>
          <option value="90">{t("couponsAnalytics.last90Days")}</option>
          <option value="365">{t("couponsAnalytics.lastYear")}</option>
        </select>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-purple-500">
              <TicketIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("couponsAnalytics.ordersWithCoupons")}
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.totalCouponOrders}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-red-500">
              <ExclamationTriangleIcon className="h-6 w-6 text-white" />
            </div>
          </div>
          <div>
            <p className="text-sm text-gray-500">
              {t("couponsAnalytics.totalDiscounts")}
            </p>
            <p className="text-2xl font-bold text-red-600">
              {formatPrice(stats?.totalDiscounts || 0)}
            </p>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-blue-500">
              <TicketIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("couponsAnalytics.couponsUsedCount")}
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.coupons?.length || 0}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Coupon Usage Chart */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          {t("couponsAnalytics.usageChartTitle")}
        </h3>
        <div className="min-w-0 h-[350px]">
          <ResponsiveContainer width="100%" height="100%" minWidth={0}>
            <BarChart
              data={stats?.coupons?.slice(0, 10) || []}
              layout="vertical"
            >
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="#374151"
                opacity={0.1}
              />
              <XAxis type="number" stroke="#9CA3AF" fontSize={12} />
              <YAxis
                dataKey="code"
                type="category"
                stroke="#9CA3AF"
                fontSize={12}
                width={120}
              />
              <Tooltip />
              <Bar
                dataKey="usageCount"
                fill="#8B5CF6"
                name={t("couponsAnalytics.usageCount")}
                radius={[0, 4, 4, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Coupons Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          {t("couponsAnalytics.detailsTitle")}
        </h3>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-200 dark:border-gray-700">
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("couponsAnalytics.coupon")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("couponsAnalytics.usageCount")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("couponsAnalytics.discountAmount")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("couponsAnalytics.revenueGenerated")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("couponsAnalytics.status")}
                </th>
              </tr>
            </thead>
            <tbody>
              {stats?.coupons?.map((coupon, index) => {
                const profitWarning =
                  coupon.discountAmount > coupon.revenue * 0.3;
                return (
                  <tr
                    key={index}
                    className="border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50"
                  >
                    <td className="py-3 px-4 text-sm text-gray-900 dark:text-white font-mono font-medium">
                      {coupon.code}
                    </td>
                    <td className="py-3 px-4 text-sm text-gray-900 dark:text-white">
                      {coupon.usageCount}
                    </td>
                    <td className="py-3 px-4 text-sm text-red-600">
                      {formatPrice(coupon.discountAmount)}
                    </td>
                    <td className="py-3 px-4 text-sm text-green-600">
                      {formatPrice(coupon.revenue)}
                    </td>
                    <td className="py-3 px-4">
                      {profitWarning ? (
                        <span className="inline-flex items-center gap-1 px-2 py-1 bg-yellow-100 text-yellow-800 rounded-full text-xs">
                          <ExclamationTriangleIcon className="h-3 w-3" />
                          {t("couponsAnalytics.highDiscount")}
                        </span>
                      ) : (
                        <span className="px-2 py-1 bg-green-100 text-green-800 rounded-full text-xs">
                          {t("couponsAnalytics.good")}
                        </span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CouponsAnalytics;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  UsersIcon,
  ArrowPathIcon,
  XCircleIcon,
  StarIcon,
  CurrencyDollarIcon,
  ShoppingBagIcon,
} from "@heroicons/react/24/outline";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
} from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";
import { useCurrency } from "../../../hooks/useCurrency";

interface CustomerStats {
  totalCustomers: number;
  repeatCustomers: number;
  newCustomers: number;
  repeatRate: number;
  averageOrderValue: number;
  customerLifetimeValue: number;
  topCustomers: Array<{
    id: string;
    name: string;
    email: string;
    orders: number;
    totalSpent: number;
    lastOrderDate: string;
  }>;
  customerSegments: Array<{
    segment: string;
    count: number;
    revenue: number;
  }>;
}

const COLORS = ["#3B82F6", "#10B981", "#F59E0B", "#EF4444"];

const CustomerAnalytics: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { formatPrice } = useCurrency();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<CustomerStats | null>(null);

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const qualityData =
        await analyticsService.getCustomerQualityAnalytics(period);

      if (qualityData.success) {
        const data = qualityData.data || {};
        setStats({
          totalCustomers: data.totalCustomers || 0,
          repeatCustomers: data.repeatCustomers || 0,
          newCustomers: data.newCustomers || 0,
          repeatRate: data.repeatRate || 0,
          averageOrderValue: data.averageOrderValue || 0,
          customerLifetimeValue: data.customerLifetimeValue || 0,
          topCustomers: data.topCustomers || [],
          customerSegments: data.segments || [
            { segment: t("customerAnalytics.vip"), count: 0, revenue: 0 },
            { segment: t("customerAnalytics.active"), count: 0, revenue: 0 },
            { segment: t("customerAnalytics.atRisk"), count: 0, revenue: 0 },
            { segment: t("customerAnalytics.lost"), count: 0, revenue: 0 },
          ],
        });
      }
    } catch (err: any) {
      console.error("CustomerAnalytics error:", err);
      setError(err.message || t("customerAnalytics.fetchError"));
    } finally {
      setLoading(false);
    }
  };

  const customerData = stats
    ? [
        {
          name: t("customerAnalytics.repeatCustomers"),
          value: stats.repeatCustomers,
        },
        {
          name: t("customerAnalytics.newCustomers"),
          value: stats.newCustomers,
        },
      ]
    : [];

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          {t("customerAnalytics.retry")}
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {t("customerAnalytics.title")}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("customerAnalytics.subtitle")}
          </p>
        </div>
        <select
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="7">{t("customerAnalytics.last7Days")}</option>
          <option value="30">{t("customerAnalytics.last30Days")}</option>
          <option value="90">{t("customerAnalytics.last90Days")}</option>
          <option value="365">{t("customerAnalytics.lastYear")}</option>
        </select>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-blue-500">
              <UsersIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("customerAnalytics.totalCustomers")}
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.totalCustomers?.toLocaleString()}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-green-500">
              <ArrowPathIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("customerAnalytics.repeatCustomers")}
              </p>
              <p className="text-2xl font-bold text-green-600">
                {stats?.repeatCustomers?.toLocaleString()}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-purple-500">
              <UsersIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("customerAnalytics.newCustomers")}
              </p>
              <p className="text-2xl font-bold text-purple-600">
                {stats?.newCustomers?.toLocaleString()}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-orange-500">
              <ArrowPathIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("customerAnalytics.repeatRate")}
              </p>
              <p className="text-2xl font-bold text-orange-600">
                {stats?.repeatRate?.toFixed(1)}%
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Additional Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-indigo-500">
              <ShoppingBagIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("customerAnalytics.averageOrderValue")}
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {formatPrice(stats?.averageOrderValue || 0)}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-yellow-500">
              <CurrencyDollarIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("customerAnalytics.customerLifetimeValue")}
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {formatPrice(stats?.customerLifetimeValue || 0)}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Customer Distribution Chart */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            {t("customerAnalytics.customerDistribution")}
          </h3>
          <div className="min-w-0 h-[300px]">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <PieChart>
                <Pie
                  data={customerData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={5}
                  dataKey="value"
                  nameKey="name"
                  label={({ name, value }) => `${name}: ${value}`}
                >
                  {customerData.map((_, index) => (
                    <Cell
                      key={`cell-${index}`}
                      fill={COLORS[index % COLORS.length]}
                    />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Customer Segments */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            {t("customerAnalytics.customerSegments")}
          </h3>
          <div className="min-w-0 h-[300px]">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <BarChart data={stats?.customerSegments || []}>
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="#374151"
                  opacity={0.1}
                />
                <XAxis dataKey="segment" stroke="#9CA3AF" fontSize={12} />
                <YAxis stroke="#9CA3AF" fontSize={12} />
                <Tooltip
                  formatter={(value) => (value ? value.toLocaleString() : "0")}
                />
                <Bar
                  dataKey="count"
                  fill="#3B82F6"
                  name={t("customerAnalytics.count")}
                  radius={[4, 4, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Top Customers Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
          <StarIcon className="h-5 w-5 text-yellow-500" />
          {t("customerAnalytics.topCustomers")}
        </h3>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-200 dark:border-gray-700">
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  #
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("customerAnalytics.customer")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("customerAnalytics.email")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("customerAnalytics.ordersCount")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("customerAnalytics.totalSpent")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("customerAnalytics.lastOrder")}
                </th>
              </tr>
            </thead>
            <tbody>
              {stats?.topCustomers?.map((customer, index) => (
                <tr
                  key={customer.id}
                  className="border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50"
                >
                  <td className="py-3 px-4 text-sm text-gray-900 dark:text-white">
                    {index + 1}
                  </td>
                  <td className="py-3 px-4 text-sm text-gray-900 dark:text-white">
                    {customer.name}
                  </td>
                  <td className="py-3 px-4 text-sm text-gray-500">
                    {customer.email}
                  </td>
                  <td className="py-3 px-4 text-sm text-blue-600 font-medium">
                    {customer.orders}
                  </td>
                  <td className="py-3 px-4 text-sm text-green-600 font-medium">
                    {formatPrice(customer.totalSpent)}
                  </td>
                  <td className="py-3 px-4 text-sm text-gray-500">
                    {new Date(customer.lastOrderDate).toLocaleDateString(
                      i18n.language === "ar" ? "ar-EG" : "en-US",
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CustomerAnalytics;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  TruckIcon,
  XCircleIcon,
  CheckCircleIcon,
  ClockIcon,
} from "@heroicons/react/24/outline";
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
} from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";

interface DeliveryStats {
  totalDeliveries: number;
  successfulDeliveries: number;
  failedDeliveries: number;
  deliveryRate: number;
  averageDeliveryTime: number;
  dailyTrends: Array<{
    date: string;
    successful: number;
    failed: number;
    rate: number;
  }>;
  regionPerformance: Array<{
    region: string;
    deliveryRate: number;
    avgTime: number;
  }>;
  shippingCompanies: Array<{
    company: string;
    deliveryRate: number;
    orders: number;
  }>;
}

const DeliveryRateAnalytics: React.FC = () => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<DeliveryStats | null>(null);

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await analyticsService.getDeliveryRateAnalytics(period);

      if (response.success && response.data) {
        setStats(response.data);
      } else {
        setStats({
          totalDeliveries: 0,
          successfulDeliveries: 0,
          failedDeliveries: 0,
          deliveryRate: 0,
          averageDeliveryTime: 0,
          dailyTrends: [],
          regionPerformance: [],
          shippingCompanies: [],
        });
      }
    } catch (err: any) {
      console.error("DeliveryRateAnalytics error:", err);
      setError(err.message || t("deliveryRateAnalytics.fetchError"));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          {t("deliveryRateAnalytics.retry")}
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {t("deliveryRateAnalytics.title")}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("deliveryRateAnalytics.subtitle")}
          </p>
        </div>
        <select
          id="delivery-rate-period"
          name="deliveryRatePeriod"
          aria-label={t("deliveryRateAnalytics.title")}
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="7">{t("deliveryRateAnalytics.last7Days")}</option>
          <option value="30">{t("deliveryRateAnalytics.last30Days")}</option>
          <option value="90">{t("deliveryRateAnalytics.last90Days")}</option>
          <option value="365">{t("deliveryRateAnalytics.lastYear")}</option>
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-blue-500">
              <TruckIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("deliveryRateAnalytics.totalDeliveries")}
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.totalDeliveries?.toLocaleString()}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-green-500">
              <CheckCircleIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("deliveryRateAnalytics.successRate")}
              </p>
              <p className="text-2xl font-bold text-green-600">
                {stats?.deliveryRate?.toFixed(1)}%
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-orange-500">
              <ClockIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("deliveryRateAnalytics.avgDeliveryTime")}
              </p>
              <p className="text-2xl font-bold text-orange-600">
                {stats?.averageDeliveryTime?.toFixed(1)}{" "}
                {t("deliveryRateAnalytics.day")}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-red-500">
              <XCircleIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("deliveryRateAnalytics.failedDeliveries")}
              </p>
              <p className="text-2xl font-bold text-red-600">
                {stats?.failedDeliveries?.toLocaleString()}
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          {t("deliveryRateAnalytics.deliveryRateOverTime")}
        </h3>
        <div className="min-w-0 h-[350px]">
          <ResponsiveContainer width="100%" height="100%" minWidth={0}>
            <LineChart data={stats?.dailyTrends || []}>
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="#374151"
                opacity={0.1}
              />
              <XAxis dataKey="date" stroke="#9CA3AF" fontSize={12} />
              <YAxis stroke="#9CA3AF" fontSize={12} />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="rate"
                stroke="#10B981"
                strokeWidth={2}
                name={t("deliveryRateAnalytics.deliveryRatePercentage")}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            {t("deliveryRateAnalytics.performanceByRegion")}
          </h3>
          <div className="min-w-0 h-[300px]">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <BarChart data={stats?.regionPerformance || []} layout="vertical">
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="#374151"
                  opacity={0.1}
                />
                <XAxis type="number" stroke="#9CA3AF" fontSize={12} />
                <YAxis
                  dataKey="region"
                  type="category"
                  stroke="#9CA3AF"
                  fontSize={12}
                  width={100}
                />
                <Tooltip />
                <Bar
                  dataKey="deliveryRate"
                  fill="#10B981"
                  name={t("deliveryRateAnalytics.deliveryRatePercentage")}
                  radius={[0, 4, 4, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            {t("deliveryRateAnalytics.shippingCompanyPerformance")}
          </h3>
          <div className="min-w-0 h-[300px]">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <BarChart data={stats?.shippingCompanies || []} layout="vertical">
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="#374151"
                  opacity={0.1}
                />
                <XAxis type="number" stroke="#9CA3AF" fontSize={12} />
                <YAxis
                  dataKey="company"
                  type="category"
                  stroke="#9CA3AF"
                  fontSize={12}
                  width={100}
                />
                <Tooltip />
                <Bar
                  dataKey="deliveryRate"
                  fill="#3B82F6"
                  name={t("deliveryRateAnalytics.deliveryRatePercentage")}
                  radius={[0, 4, 4, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DeliveryRateAnalytics;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  ShoppingCartIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  TruckIcon,
  ArrowPathIcon,
  BanknotesIcon,
  CreditCardIcon,
} from "@heroicons/react/24/outline";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  LineChart,
  Line,
  Legend,
} from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";

interface OrdersStats {
  totalOrders: number;
  byStatus: Record<string, number>;
  dailyTrend: Array<{ date: string; orders: number }>;
  weeklyTrend: Array<{ week: string; orders: number }>;
  monthlyTrend: Array<{ month: string; orders: number }>;
  codVsPrepaid: { cod: number; prepaid: number };
  cancelledOrders: number;
  rejectedOrders: number;
}

const OrdersAnalytics: React.FC = () => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<OrdersStats | null>(null);
  const [trendView, setTrendView] = useState<"daily" | "weekly" | "monthly">(
    "daily",
  );

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const [storeData, dailyData] = await Promise.all([
        analyticsService.getStoreAnalytics(period),
        analyticsService.getDailyAnalytics(period),
      ]);

      if (storeData.success) {
        const data = storeData.data;
        setStats({
          totalOrders: data.totalOrders || 0,
          byStatus: data.ordersByStatus || {},
          dailyTrend: dailyData.data || [],
          weeklyTrend: [],
          monthlyTrend: [],
          codVsPrepaid: {
            cod: data.codOrders || 0,
            prepaid: data.prepaidOrders || 0,
          },
          cancelledOrders: data.cancelledOrders || 0,
          rejectedOrders: data.rejectedOrders || 0,
        });
      }
    } catch (err: any) {
      setError(err.message || "حدث خطأ في جلب البيانات");
    } finally {
      setLoading(false);
    }
  };

  const statusColors: Record<string, string> = {
    completed: "bg-green-500",
    processing: "bg-blue-500",
    pending: "bg-yellow-500",
    cancelled: "bg-red-500",
    refunded: "bg-purple-500",
    "on-hold": "bg-orange-500",
    failed: "bg-gray-500",
  };

  const statusLabels: Record<string, string> = {
    completed: "مكتمل",
    processing: "قيد المعالجة",
    pending: "قيد الانتظار",
    cancelled: "ملغي",
    refunded: "مسترد",
    "on-hold": "معلق",
    failed: "فاشل",
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          إعادة المحاولة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            تحليلات الطلبات
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            تتبع وتحليل حالات الطلبات
          </p>
        </div>
        <select
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="7">آخر 7 أيام</option>
          <option value="30">آخر 30 يوم</option>
          <option value="90">آخر 90 يوم</option>
          <option value="365">آخر سنة</option>
        </select>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">إجمالي الطلبات</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.totalOrders?.toLocaleString()}
              </p>
            </div>
            <div className="p-3 rounded-full bg-blue-500">
              <ShoppingCartIcon className="h-6 w-6 text-white" />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">الدفع عند الاستلام (COD)</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.codVsPrepaid.cod?.toLocaleString()}
              </p>
            </div>
            <div className="p-3 rounded-full bg-orange-500">
              <BanknotesIcon className="h-6 w-6 text-white" />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">الدفع المسبق</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.codVsPrepaid.prepaid?.toLocaleString()}
              </p>
            </div>
            <div className="p-3 rounded-full bg-green-500">
              <CreditCardIcon className="h-6 w-6 text-white" />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">الطلبات الملغاة</p>
              <p className="text-2xl font-bold text-red-600">
                {stats?.cancelledOrders?.toLocaleString()}
              </p>
            </div>
            <div className="p-3 rounded-full bg-red-500">
              <XCircleIcon className="h-6 w-6 text-white" />
            </div>
          </div>
        </div>
      </div>

      {/* Orders by Status */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          الطلبات حسب الحالة
        </h3>
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-4">
          {Object.entries(stats?.byStatus || {}).map(([status, count]) => (
            <div
              key={status}
              className="text-center p-4 bg-gray-50 dark:bg-gray-700 rounded-lg"
            >
              <div
                className={`w-4 h-4 rounded-full ${statusColors[status] || "bg-gray-400"} mx-auto mb-2`}
              ></div>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                {statusLabels[status] || status}
              </p>
              <p className="text-xl font-bold text-gray-900 dark:text-white">
                {count}
              </p>
            </div>
          ))}
        </div>
      </div>

      {/* Trend Chart */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            اتجاه الطلبات
          </h3>
          <div className="flex gap-2">
            {(["daily", "weekly", "monthly"] as const).map((view) => (
              <button
                key={view}
                onClick={() => setTrendView(view)}
                className={`px-3 py-1 rounded-lg text-sm ${
                  trendView === view
                    ? "bg-blue-600 text-white"
                    : "bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300"
                }`}
              >
                {view === "daily"
                  ? "يومي"
                  : view === "weekly"
                    ? "أسبوعي"
                    : "شهري"}
              </button>
            ))}
          </div>
        </div>
        <div className="min-w-0 h-[350px]">
          <ResponsiveContainer width="100%" height="100%" minWidth={0}>
            <LineChart data={stats?.dailyTrend || []}>
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="currentColor"
                className="stroke-gray-300 dark:stroke-gray-600"
              />
              <XAxis
                dataKey="date"
                stroke="currentColor"
                className="stroke-gray-600 dark:stroke-gray-400"
                fontSize={12}
              />
              <YAxis
                stroke="currentColor"
                className="stroke-gray-600 dark:stroke-gray-400"
                fontSize={12}
              />
              <Tooltip
                contentStyle={{
                  borderRadius: "8px",
                }}
                wrapperClassName="[&_.recharts-tooltip-wrapper]:!bg-white dark:[&_.recharts-tooltip-wrapper]:!bg-gray-800 [&_.recharts-tooltip-wrapper]:!border-gray-200 dark:[&_.recharts-tooltip-wrapper]:!border-gray-700 [&_.recharts-tooltip-wrapper]:!text-gray-900 dark:[&_.recharts-tooltip-wrapper]:!text-gray-100"
              />
              <Legend />
              <Line
                type="monotone"
                dataKey="orders"
                stroke="#3B82F6"
                strokeWidth={2}
                name="الطلبات"
                dot={false}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* COD vs Prepaid Chart */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          الدفع عند الاستلام مقابل الدفع المسبق
        </h3>
        <div className="min-w-0 h-[300px]">
          <ResponsiveContainer width="100%" height="100%" minWidth={0}>
            <BarChart
              data={[
                {
                  name: "الدفع عند الاستلام",
                  value: stats?.codVsPrepaid.cod || 0,
                },
                {
                  name: "الدفع المسبق",
                  value: stats?.codVsPrepaid.prepaid || 0,
                },
              ]}
              layout="vertical"
            >
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="currentColor"
                className="stroke-gray-300 dark:stroke-gray-600"
              />
              <XAxis
                type="number"
                stroke="currentColor"
                className="stroke-gray-600 dark:stroke-gray-400"
              />
              <YAxis
                dataKey="name"
                type="category"
                stroke="currentColor"
                className="stroke-gray-600 dark:stroke-gray-400"
                width={120}
              />
              <Tooltip
                contentStyle={{
                  borderRadius: "8px",
                }}
                wrapperClassName="[&_.recharts-tooltip-wrapper]:!bg-white dark:[&_.recharts-tooltip-wrapper]:!bg-gray-800 [&_.recharts-tooltip-wrapper]:!border-gray-200 dark:[&_.recharts-tooltip-wrapper]:!border-gray-700 [&_.recharts-tooltip-wrapper]:!text-gray-900 dark:[&_.recharts-tooltip-wrapper]:!text-gray-100"
              />
              <Bar dataKey="value" fill="#3B82F6" radius={[0, 4, 4, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default OrdersAnalytics;

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import {
  ChartBarIcon,
  ShoppingCartIcon,
  CurrencyDollarIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowTrendingUpIcon,
  ArrowTrendingDownIcon,
  ClockIcon,
  TruckIcon,
  UsersIcon,
} from "@heroicons/react/24/outline";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  PieChart,
  Pie,
  Cell,
} from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";
import { useAuth } from "../../../hooks/useAuthSimple";
import { useCurrency } from "../../../hooks/useCurrency";
import {
  createStorageKey,
  getWithExpiry,
  setWithExpiry,
} from "../../../utils/storage";

interface DashboardStats {
  totalOrders: number;
  completedOrders: number;
  cancelledOrders: number;
  returnedOrders: number;
  pendingOrders: number;
  totalRevenue: number;
  averageOrderValue: number;
  conversionRate: number;
  dailyTrend: Array<{ date: string; orders: number; revenue: number }>;
}

const OverviewDashboard: React.FC = () => {
  const { t } = useTranslation();
  const { user } = useAuth();
  const { formatPrice } = useCurrency();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const CACHE_TTL_MS = 60_000;

  const cacheKey = useMemo(() => {
    let companyId = "unknown";

    const storefrontCompanyId = localStorage.getItem("storefront_companyId");
    if (storefrontCompanyId) {
      companyId = storefrontCompanyId;
    } else if (user?.companyId || user?.company?.id) {
      companyId = user?.companyId || user?.company?.id || companyId;
    } else {
      try {
        const storedCompany = localStorage.getItem("company");
        if (storedCompany) {
          const parsedCompany = JSON.parse(storedCompany);
          companyId = parsedCompany?.id || companyId;
        }
      } catch {
        companyId = companyId;
      }

      if (companyId === "unknown") {
        try {
          const rawUser = localStorage.getItem("user");
          const parsedUser = rawUser ? JSON.parse(rawUser) : null;
          companyId =
            parsedUser?.companyId || parsedUser?.company?.id || companyId;
        } catch {
          companyId = companyId;
        }
      }
    }

    return createStorageKey(
      "orders-overview-dashboard",
      `${companyId}:${period}`,
    );
  }, [period, user?.company?.id, user?.companyId]);

  const fetchDashboardData = useCallback(
    async ({ signal, background = false } = {}) => {
      try {
        if (!background) {
          setLoading(true);
          setError(null);
        }

        const [storeData, dailyData] = await Promise.all([
          analyticsService.getStoreAnalytics(
            period,
            undefined,
            undefined,
            signal,
          ),
          analyticsService.getDailyAnalytics(
            period,
            undefined,
            undefined,
            signal,
          ),
        ]);

        if (storeData.success && dailyData.success) {
          const storeStats = storeData.data;
          const nextStats = {
            totalOrders: storeStats.totalOrders || 0,
            completedOrders: storeStats.completedOrders || 0,
            cancelledOrders: storeStats.cancelledOrders || 0,
            returnedOrders: storeStats.returnedOrders || 0,
            pendingOrders: storeStats.pendingOrders || 0,
            totalRevenue: storeStats.totalRevenue || 0,
            averageOrderValue: storeStats.averageOrderValue || 0,
            conversionRate: storeStats.conversionRate || 0,
            dailyTrend: dailyData.data || [],
          };
          setStats(nextStats);
          setWithExpiry(cacheKey, nextStats, CACHE_TTL_MS);
        }
      } catch (err: any) {
        if (!background) {
          setError(err.message || "حدث خطأ في جلب البيانات");
        }
      } finally {
        if (!background) {
          setLoading(false);
        }
      }
    },
    [cacheKey, period],
  );

  useEffect(() => {
    const controller = new AbortController();
    const cached = getWithExpiry<DashboardStats>(cacheKey);

    if (cached) {
      setStats(cached);
      setLoading(false);
      fetchDashboardData({ signal: controller.signal, background: true });
    } else {
      fetchDashboardData({ signal: controller.signal });
    }

    return () => controller.abort();
  }, [cacheKey, fetchDashboardData]);

  const StatCard: React.FC<{
    title: string;
    value: string | number;
    icon: React.ElementType;
    color: string;
    trend?: number;
    link?: string;
  }> = ({ title, value, icon: Icon, color, trend, link }) => {
    const content = (
      <div
        className={`bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 hover:shadow-md transition-shadow`}
      >
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-gray-500 dark:text-gray-400">{title}</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
              {value}
            </p>
            {trend !== undefined && (
              <div
                className={`flex items-center mt-2 text-sm ${trend >= 0 ? "text-green-600" : "text-red-600"}`}
              >
                {trend >= 0 ? (
                  <ArrowTrendingUpIcon className="h-4 w-4 mr-1" />
                ) : (
                  <ArrowTrendingDownIcon className="h-4 w-4 mr-1" />
                )}
                <span>{Math.abs(trend)}% عن الفترة السابقة</span>
              </div>
            )}
          </div>
          <div className={`p-3 rounded-full ${color}`}>
            <Icon className="h-6 w-6 text-white" />
          </div>
        </div>
      </div>
    );

    return link ? <Link to={link}>{content}</Link> : content;
  };

  const COLORS = ["#10B981", "#EF4444", "#F59E0B", "#6366F1"];

  const orderStatusData = stats
    ? [
        { name: "مكتمل", value: stats.completedOrders, color: "#10B981" },
        { name: "ملغي", value: stats.cancelledOrders, color: "#EF4444" },
        { name: "مرتجع", value: stats.returnedOrders, color: "#F59E0B" },
        { name: "قيد الانتظار", value: stats.pendingOrders, color: "#6366F1" },
      ]
    : [];

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchDashboardData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          إعادة المحاولة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            نظرة عامة على الأداء
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            ملخص شامل لأداء المتجر
          </p>
        </div>
        <select
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
        >
          <option value="7">آخر 7 أيام</option>
          <option value="30">آخر 30 يوم</option>
          <option value="90">آخر 90 يوم</option>
          <option value="365">آخر سنة</option>
        </select>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard
          title="إجمالي الطلبات"
          value={stats?.totalOrders?.toLocaleString() || 0}
          icon={ShoppingCartIcon}
          color="bg-blue-500"
          link="/analytics/orders/orders"
        />
        <StatCard
          title="الطلبات المكتملة"
          value={stats?.completedOrders?.toLocaleString() || 0}
          icon={CheckCircleIcon}
          color="bg-green-500"
        />
        <StatCard
          title="إجمالي الإيرادات"
          value={formatPrice(stats?.totalRevenue || 0)}
          icon={CurrencyDollarIcon}
          color="bg-purple-500"
          link="/analytics/orders/revenue"
        />
        <StatCard
          title="متوسط قيمة الطلب"
          value={formatPrice(stats?.averageOrderValue || 0)}
          icon={ArrowTrendingUpIcon}
          color="bg-orange-500"
        />
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Daily Trend Chart */}
        <div className="lg:col-span-2 bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            اتجاه الطلبات اليومي
          </h3>
          <div className="min-w-0 h-[300px]">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <AreaChart data={stats?.dailyTrend || []}>
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="currentColor"
                  className="stroke-gray-300 dark:stroke-gray-600"
                />
                <XAxis
                  dataKey="date"
                  stroke="currentColor"
                  className="stroke-gray-600 dark:stroke-gray-400"
                  fontSize={12}
                />
                <YAxis
                  stroke="currentColor"
                  className="stroke-gray-600 dark:stroke-gray-400"
                  fontSize={12}
                />
                <Tooltip
                  contentStyle={{
                    borderRadius: "8px",
                  }}
                  wrapperClassName="[&_.recharts-tooltip-wrapper]:!bg-white dark:[&_.recharts-tooltip-wrapper]:!bg-gray-800 [&_.recharts-tooltip-wrapper]:!border-gray-200 dark:[&_.recharts-tooltip-wrapper]:!border-gray-700 [&_.recharts-tooltip-wrapper]:!text-gray-900 dark:[&_.recharts-tooltip-wrapper]:!text-gray-100"
                />
                <Area
                  type="monotone"
                  dataKey="orders"
                  stroke="#3B82F6"
                  fill="#3B82F6"
                  fillOpacity={0.3}
                  name="الطلبات"
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Order Status Pie Chart */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            توزيع حالات الطلبات
          </h3>
          <div style={{ width: "100%", height: 250 }}>
            <ResponsiveContainer width="100%" height={250} minHeight={250}>
              <PieChart>
                <Pie
                  data={orderStatusData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {orderStatusData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex flex-wrap justify-center gap-4 mt-4">
            {orderStatusData.map((item, index) => (
              <div key={index} className="flex items-center gap-2">
                <div
                  className="w-3 h-3 rounded-full"
                  style={{ backgroundColor: item.color }}
                ></div>
                <span className="text-sm text-gray-600 dark:text-gray-400">
                  {item.name}: {item.value}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Quick Links */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          الوصول السريع للتحليلات
        </h3>
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
          {[
            {
              to: "/analytics/orders/orders",
              icon: ShoppingCartIcon,
              label: "الطلبات",
              color:
                "bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400",
            },
            {
              to: "/analytics/orders/revenue",
              icon: CurrencyDollarIcon,
              label: "الإيرادات",
              color:
                "bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400",
            },
            {
              to: "/analytics/orders/products",
              icon: ChartBarIcon,
              label: "المنتجات",
              color:
                "bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400",
            },
            {
              to: "/analytics/orders/categories",
              icon: ClockIcon,
              label: "الأقسام",
              color:
                "bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400",
            },
            {
              to: "/analytics/orders/coupons",
              icon: TruckIcon,
              label: "الكوبونات",
              color:
                "bg-pink-100 dark:bg-pink-900/30 text-pink-600 dark:text-pink-400",
            },
            {
              to: "/analytics/orders/stock",
              icon: UsersIcon,
              label: "المخزون",
              color:
                "bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400",
            },
          ].map((item, index) => (
            <Link
              key={index}
              to={item.to}
              className={`flex flex-col items-center p-4 rounded-xl ${item.color} hover:opacity-80 transition-all duration-200`}
            >
              <item.icon className="h-8 w-8 mb-2" />
              <span className="text-sm font-medium">{item.label}</span>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
};

export default OverviewDashboard;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  CreditCardIcon,
  BanknotesIcon,
  XCircleIcon,
  InformationCircleIcon,
  TruckIcon,
  CheckCircleIcon,
} from "@heroicons/react/24/outline";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  LineChart,
  Line,
} from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";
import { useCurrency } from "../../../hooks/useCurrency";

interface PaymentStats {
  methods: Array<{
    name: string;
    count: number;
    revenue: number;
    percentage: number;
    averageOrderValue: number;
  }>;
  totalOrders: number;
  codVsOnline: {
    cod: { count: number; revenue: number; percentage: number };
    online: { count: number; revenue: number; percentage: number };
  };
  successRate: number;
  dailyTrends: Array<{ date: string; cod: number; online: number }>;
}

const COLORS = [
  "#3B82F6",
  "#10B981",
  "#F59E0B",
  "#EF4444",
  "#8B5CF6",
  "#EC4899",
];

const PaymentMethodAnalytics: React.FC = () => {
  const { t } = useTranslation();
  const { formatPrice } = useCurrency();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<PaymentStats | null>(null);

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);
      const response =
        await analyticsService.getPaymentMethodsAnalytics(period);
      if (response.success && response.data) {
        const data = response.data || {};
        const methodsData = Array.isArray(data) ? data : data.methods || [];

        // Calculate COD vs Online
        const codData = methodsData.filter((m: any) => {
          const name = m.name || "";
          return (
            name.toLowerCase().includes("cod") ||
            name.toLowerCase().includes("نقد")
          );
        });
        const onlineData = methodsData.filter((m: any) => {
          const name = m.name || "";
          return (
            !name.toLowerCase().includes("cod") &&
            !name.toLowerCase().includes("نقد")
          );
        });

        const codTotal = codData.reduce(
          (sum: number, m: any) => sum + (m.count || 0),
          0,
        );
        const codRevenue = codData.reduce(
          (sum: number, m: any) => sum + (m.revenue || 0),
          0,
        );
        const onlineTotal = onlineData.reduce(
          (sum: number, m: any) => sum + (m.count || 0),
          0,
        );
        const onlineRevenue = onlineData.reduce(
          (sum: number, m: any) => sum + (m.revenue || 0),
          0,
        );
        const totalCount = codTotal + onlineTotal;

        setStats({
          methods: methodsData,
          totalOrders: data.totalOrders || totalCount || 0,
          codVsOnline: {
            cod: {
              count: codTotal,
              revenue: codRevenue,
              percentage: totalCount > 0 ? (codTotal / totalCount) * 100 : 0,
            },
            online: {
              count: onlineTotal,
              revenue: onlineRevenue,
              percentage: totalCount > 0 ? (onlineTotal / totalCount) * 100 : 0,
            },
          },
          successRate: data.successRate || 95,
          dailyTrends: data.dailyTrends || [],
        });
      }
    } catch (err: any) {
      console.error("PaymentMethodAnalytics error:", err);
      setError(err.message || t("paymentAnalytics.fetchError"));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          {t("paymentAnalytics.retry")}
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {t("paymentAnalytics.title")}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("paymentAnalytics.subtitle")}
          </p>
        </div>
        <select
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="7">{t("paymentAnalytics.last7Days")}</option>
          <option value="30">{t("paymentAnalytics.last30Days")}</option>
          <option value="90">{t("paymentAnalytics.last90Days")}</option>
          <option value="365">{t("paymentAnalytics.lastYear")}</option>
        </select>
      </div>

      {/* Basic Analytics Notice */}
      <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl p-4">
        <div className="flex items-center gap-3">
          <InformationCircleIcon className="h-5 w-5 text-blue-500" />
          <p className="text-blue-700 dark:text-blue-300 text-sm">
            {t("paymentAnalytics.basicAnalyticsNotice")}
          </p>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-blue-500">
              <CreditCardIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("paymentAnalytics.totalOrders")}
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats?.totalOrders?.toLocaleString()}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-orange-500">
              <TruckIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("paymentAnalytics.codPercentage")}
              </p>
              <p className="text-2xl font-bold text-orange-600">
                {typeof stats?.codVsOnline?.cod?.percentage === "number"
                  ? stats.codVsOnline.cod.percentage.toFixed(1)
                  : "0.0"}
                %
              </p>
              <p className="text-xs text-gray-400 mt-1">
                {stats?.codVsOnline?.cod?.count?.toLocaleString()}{" "}
                {t("paymentAnalytics.orders")}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-green-500">
              <BanknotesIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("paymentAnalytics.onlinePercentage")}
              </p>
              <p className="text-2xl font-bold text-green-600">
                {typeof stats?.codVsOnline?.online?.percentage === "number"
                  ? stats.codVsOnline.online.percentage.toFixed(1)
                  : "0.0"}
                %
              </p>
              <p className="text-xs text-gray-400 mt-1">
                {stats?.codVsOnline?.online?.count?.toLocaleString()}{" "}
                {t("paymentAnalytics.orders")}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-purple-500">
              <CheckCircleIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("paymentAnalytics.successRate")}
              </p>
              <p className="text-2xl font-bold text-purple-600">
                {typeof stats?.successRate === "number"
                  ? stats.successRate.toFixed(1)
                  : "0.0"}
                %
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Payment Methods Pie Chart */}
        {stats?.methods && stats.methods.length > 0 && (
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
              {t("paymentAnalytics.paymentMethodsDistribution")}
            </h3>
            <div style={{ width: "100%", height: 300 }}>
              <ResponsiveContainer width="100%" height={300} minHeight={300}>
                <PieChart>
                  <Pie
                    data={stats.methods}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={100}
                    paddingAngle={5}
                    dataKey="count"
                    nameKey="name"
                    label={({ name, percent }) =>
                      `${name || t("paymentAnalytics.undefined")} (${percent ? (percent * 100).toFixed(1) : 0}%)`
                    }
                  >
                    {stats.methods.map((_, index) => (
                      <Cell
                        key={`cell-${index}`}
                        fill={COLORS[index % COLORS.length]}
                      />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {/* Revenue by Payment Method */}
        {stats?.methods && stats.methods.length > 0 && (
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
              {t("paymentAnalytics.revenueByPaymentMethod")}
            </h3>
            <div style={{ width: "100%", height: 300 }}>
              <ResponsiveContainer width="100%" height={300} minHeight={300}>
                <BarChart data={stats.methods} layout="vertical">
                  <CartesianGrid
                    strokeDasharray="3 3"
                    stroke="#374151"
                    opacity={0.1}
                  />
                  <XAxis type="number" stroke="#9CA3AF" fontSize={12} />
                  <YAxis
                    dataKey="name"
                    type="category"
                    stroke="#9CA3AF"
                    fontSize={12}
                    width={100}
                  />
                  <Tooltip
                    formatter={(value) =>
                      value ? formatPrice(value as number) : "0"
                    }
                  />
                  <Bar
                    dataKey="revenue"
                    fill="#10B981"
                    name={t("paymentAnalytics.revenue")}
                    radius={[0, 4, 4, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </div>

      {/* COD vs Online Trends */}
      {stats?.dailyTrends && stats.dailyTrends.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            {t("paymentAnalytics.paymentTrends")}
          </h3>
          <div style={{ width: "100%", height: 300 }}>
            <ResponsiveContainer width="100%" height={300} minHeight={300}>
              <LineChart data={stats.dailyTrends}>
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="#374151"
                  opacity={0.1}
                />
                <XAxis dataKey="date" stroke="#9CA3AF" fontSize={12} />
                <YAxis stroke="#9CA3AF" fontSize={12} />
                <Tooltip />
                <Line
                  type="monotone"
                  dataKey="cod"
                  stroke="#F59E0B"
                  strokeWidth={2}
                  name="COD"
                />
                <Line
                  type="monotone"
                  dataKey="online"
                  stroke="#10B981"
                  strokeWidth={2}
                  name={t("paymentAnalytics.electronicPayment")}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* Payment Methods Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          {t("paymentAnalytics.paymentMethodsDetails")}
        </h3>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-200 dark:border-gray-700">
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("paymentAnalytics.paymentMethod")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("paymentAnalytics.ordersCount")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("paymentAnalytics.revenue")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("paymentAnalytics.averageOrderValue")}
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  {t("paymentAnalytics.percentage")}
                </th>
              </tr>
            </thead>
            <tbody>
              {stats?.methods?.map((method, index) => {
                const methodName =
                  method.name || t("paymentAnalytics.undefined");
                const isCOD =
                  methodName.toLowerCase().includes("cod") ||
                  methodName.toLowerCase().includes("نقد") ||
                  methodName.includes("استلام");
                return (
                  <tr
                    key={index}
                    className="border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50"
                  >
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-2">
                        {isCOD ? (
                          <BanknotesIcon className="h-5 w-5 text-orange-500" />
                        ) : (
                          <CreditCardIcon className="h-5 w-5 text-blue-500" />
                        )}
                        <span className="text-sm text-gray-900 dark:text-white">
                          {methodName}
                        </span>
                      </div>
                    </td>
                    <td className="py-3 px-4 text-sm text-blue-600 font-medium">
                      {method.count || 0}
                    </td>
                    <td className="py-3 px-4 text-sm text-green-600 font-medium">
                      {formatPrice(method.revenue || 0)}
                    </td>
                    <td className="py-3 px-4 text-sm text-purple-600 font-medium">
                      {formatPrice(
                        method.averageOrderValue ||
                          (method.count > 0
                            ? method.revenue / method.count
                            : 0),
                      )}
                    </td>
                    <td className="py-3 px-4 text-sm text-gray-500">
                      {typeof method.percentage === "number"
                        ? method.percentage.toFixed(1)
                        : method.percentage || "0.0"}
                      %
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default PaymentMethodAnalytics;

import React, { useState, useEffect } from "react";
import {
  ShoppingBagIcon,
  ArrowTrendingUpIcon,
  ArrowTrendingDownIcon,
  XCircleIcon,
  StarIcon,
} from "@heroicons/react/24/outline";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip } from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";
import { useCurrency } from "../../../hooks/useCurrency";

interface ProductStats {
  topProducts: Array<{
    id: string;
    name: string;
    sales: number;
    revenue: number;
    image?: string;
  }>;
  lowPerformingProducts: Array<{
    id: string;
    name: string;
    sales: number;
    revenue: number;
  }>;
  totalProducts: number;
}

const ProductsAnalytics: React.FC = () => {
  const { formatPrice } = useCurrency();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<ProductStats | null>(null);

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const [topProductsData, productAnalyticsData] = await Promise.all([
        analyticsService.getTopProducts(period, 10),
        analyticsService.getProductAnalytics(period),
      ]);

      setStats({
        topProducts: topProductsData.success ? topProductsData.data : [],
        lowPerformingProducts: productAnalyticsData.success
          ? productAnalyticsData.data?.lowPerforming || []
          : [],
        totalProducts: productAnalyticsData.success
          ? productAnalyticsData.data?.totalProducts || 0
          : 0,
      });
    } catch (err: any) {
      setError(err.message || "حدث خطأ في جلب البيانات");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          إعادة المحاولة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            تحليلات المنتجات
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            أداء المنتجات والمبيعات
          </p>
        </div>
        <select
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="7">آخر 7 أيام</option>
          <option value="30">آخر 30 يوم</option>
          <option value="90">آخر 90 يوم</option>
          <option value="365">آخر سنة</option>
        </select>
      </div>

      {/* Summary */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="flex items-center gap-4">
          <div className="p-3 rounded-full bg-purple-500">
            <ShoppingBagIcon className="h-6 w-6 text-white" />
          </div>
          <div>
            <p className="text-sm text-gray-500">إجمالي المنتجات</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">
              {stats?.totalProducts?.toLocaleString()}
            </p>
          </div>
        </div>
      </div>

      {/* Top Products Chart */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
          <ArrowTrendingUpIcon className="h-5 w-5 text-green-500" />
          أفضل المنتجات مبيعاً
        </h3>
        <div className="min-w-0 h-[400px]">
          <ResponsiveContainer width="100%" height="100%" minWidth={0}>
            <BarChart data={stats?.topProducts || []} layout="vertical">
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="currentColor"
                className="stroke-gray-300 dark:stroke-gray-600"
              />
              <XAxis
                type="number"
                stroke="currentColor"
                className="stroke-gray-600 dark:stroke-gray-400"
                fontSize={12}
              />
              <YAxis
                dataKey="name"
                type="category"
                stroke="currentColor"
                className="stroke-gray-600 dark:stroke-gray-400"
                fontSize={12}
                width={150}
              />
              <Tooltip
                contentStyle={{
                  borderRadius: "8px",
                }}
                wrapperClassName="[&_.recharts-tooltip-wrapper]:!bg-white dark:[&_.recharts-tooltip-wrapper]:!bg-gray-800 [&_.recharts-tooltip-wrapper]:!border-gray-200 dark:[&_.recharts-tooltip-wrapper]:!border-gray-700 [&_.recharts-tooltip-wrapper]:!text-gray-900 dark:[&_.recharts-tooltip-wrapper]:!text-gray-100"
                formatter={(value, name) => {
                  if (!value) return ["0", name];
                  if (name === "revenue")
                    return [formatPrice(value as number), "الإيرادات"];
                  return [value, "المبيعات"];
                }}
              />
              <Bar
                dataKey="sales"
                fill="#3B82F6"
                name="المبيعات"
                radius={[0, 4, 4, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Top Products Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
          <StarIcon className="h-5 w-5 text-yellow-500" />
          تفاصيل أفضل المنتجات
        </h3>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-200 dark:border-gray-700">
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  #
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  المنتج
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  المبيعات
                </th>
                <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                  الإيرادات
                </th>
              </tr>
            </thead>
            <tbody>
              {stats?.topProducts?.map((product, index) => (
                <tr
                  key={product.id}
                  className="border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50"
                >
                  <td className="py-3 px-4 text-sm text-gray-900 dark:text-white">
                    {index + 1}
                  </td>
                  <td className="py-3 px-4">
                    <div className="flex items-center gap-3">
                      {product.image && (
                        <img
                          src={product.image}
                          alt={product.name}
                          className="w-10 h-10 rounded-lg object-cover"
                        />
                      )}
                      <span className="text-sm text-gray-900 dark:text-white">
                        {product.name}
                      </span>
                    </div>
                  </td>
                  <td className="py-3 px-4 text-sm text-gray-900 dark:text-white">
                    {product.sales}
                  </td>
                  <td className="py-3 px-4 text-sm text-green-600 font-medium">
                    {formatPrice(product.revenue)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Low Performing Products */}
      {stats?.lowPerformingProducts &&
        stats.lowPerformingProducts.length > 0 && (
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
              <ArrowTrendingDownIcon className="h-5 w-5 text-red-500" />
              المنتجات الأقل أداءً
            </h3>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-gray-200 dark:border-gray-700">
                    <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                      المنتج
                    </th>
                    <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                      المبيعات
                    </th>
                    <th className="text-right py-3 px-4 text-sm font-medium text-gray-500">
                      الإيرادات
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {stats.lowPerformingProducts.map((product) => (
                    <tr
                      key={product.id}
                      className="border-b border-gray-100 dark:border-gray-700"
                    >
                      <td className="py-3 px-4 text-sm text-gray-900 dark:text-white">
                        {product.name}
                      </td>
                      <td className="py-3 px-4 text-sm text-red-600">
                        {product.sales}
                      </td>
                      <td className="py-3 px-4 text-sm text-gray-500">
                        {formatPrice(product.revenue)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
    </div>
  );
};

export default ProductsAnalytics;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  CurrencyDollarIcon,
  XCircleIcon,
  ArrowTrendingUpIcon,
  ArrowTrendingDownIcon,
  ChartBarIcon,
} from "@heroicons/react/24/outline";
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  PieChart,
  Pie,
  Cell,
} from "recharts";
import ResponsiveContainer from "../../../components/ui/DeferredResponsiveContainer";
import analyticsService from "../../../services/analyticsService";
import { useCurrency } from "../../../hooks/useCurrency";

interface ProfitStats {
  grossProfit: number;
  netProfit: number;
  profitMargin: number;
  cogs: number;
  operatingExpenses: number;
  adsCost: number;
  dailyProfit: Array<{
    date: string;
    profit: number;
    revenue: number;
    costs: number;
  }>;
  profitByCategory: Array<{ name: string; profit: number; margin: number }>;
}

const COLORS = ["#10B981", "#3B82F6", "#F59E0B", "#EF4444", "#8B5CF6"];

const ProfitAnalytics: React.FC = () => {
  const { t } = useTranslation();
  const { formatPrice } = useCurrency();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState("30");
  const [stats, setStats] = useState<ProfitStats | null>(null);

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await analyticsService.getProfitAnalytics(period);

      if (response.success && response.data) {
        setStats(response.data);
      } else {
        setStats({
          grossProfit: 0,
          netProfit: 0,
          profitMargin: 0,
          cogs: 0,
          operatingExpenses: 0,
          adsCost: 0,
          dailyProfit: [],
          profitByCategory: [],
        });
      }
    } catch (err: any) {
      console.error("ProfitAnalytics error:", err);
      setError(err.message || t("profitAnalytics.fetchError"));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl text-center">
        <XCircleIcon className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchData}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
        >
          {t("profitAnalytics.retry")}
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {t("profitAnalytics.title")}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("profitAnalytics.subtitle")}
          </p>
        </div>
        <select
          value={period}
          onChange={(e) => setPeriod(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="7">{t("profitAnalytics.last7Days")}</option>
          <option value="30">{t("profitAnalytics.last30Days")}</option>
          <option value="90">{t("profitAnalytics.last90Days")}</option>
          <option value="365">{t("profitAnalytics.lastYear")}</option>
        </select>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-green-500">
              <CurrencyDollarIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("profitAnalytics.grossProfit")}
              </p>
              <p className="text-2xl font-bold text-green-600">
                {formatPrice(stats?.grossProfit || 0)}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-blue-500">
              <ArrowTrendingUpIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("profitAnalytics.netProfit")}
              </p>
              <p className="text-2xl font-bold text-blue-600">
                {formatPrice(stats?.netProfit || 0)}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-purple-500">
              <ChartBarIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("profitAnalytics.profitMargin")}
              </p>
              <p className="text-2xl font-bold text-purple-600">
                {stats?.profitMargin?.toFixed(1)}%
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-red-500">
              <ArrowTrendingDownIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500">
                {t("profitAnalytics.totalCosts")}
              </p>
              <p className="text-2xl font-bold text-red-600">
                {formatPrice(
                  (stats?.cogs || 0) +
                    (stats?.operatingExpenses || 0) +
                    (stats?.adsCost || 0),
                )}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Cost Breakdown */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm text-gray-500 mb-2">
            {t("profitAnalytics.cogs")}
