                      <WarningIcon />
                    </Avatar>
                  </ListItemAvatar>
                  <ListItemText
                    primary={activity.description}
                    secondary={
                      <Box sx={{ textAlign: isRtl ? "right" : "left" }}>
                        <Typography component="span" variant="body2">
                          {activity.userId?.name} -{" "}
                          {format(new Date(activity.createdAt), "PPp", {
                            locale: isRtl ? ar : enUS,
                          })}
