export default LandingPage;

import React, { useState, useEffect } from "react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../components/ui/card";
import { Badge } from "../components/ui/badge";
import { Button } from "../components/ui/button";
import {
  RefreshCw,
  Activity,
  AlertTriangle,
  CheckCircle,
  XCircle,
  MessageSquare,
  Clock,
  TrendingUp,
  Target,
} from "lucide-react";
import StatsCard from "../components/monitoring/StatsCard";
import AlertsPanel from "../components/monitoring/AlertsPanel";
import PerformanceChart from "../components/monitoring/PerformanceChart";
import { tokenManager } from "../utils/tokenManager";
import { buildApiUrl } from "../utils/urlHelper";

interface MonitoringStats {
  summary: {
    totalResponses: number;
    errorRate: number;
    emptyRate: number;
    slowRate: number;
    successRate: number;
    averageResponseTime: number;
    uptime: number;
    lastActivity: string;
    healthStatus: "healthy" | "warning" | "critical" | "unknown";
  };
  responses: {
    total: number;
    empty: number;
    slow: number;
    successful: number;
    failed: number;
  };
  performance: {
    responseTimes: number[];
    averageResponseTime: number;
    maxResponseTime: number;
    minResponseTime: number | null;
  };
  errors: {
    total: number;
    recent: Array<{
      id: string;
      message: string;
      type: string;
      timestamp: string;
      context?: any;
    }>;
    byType: Record<string, number>;
  };
  system: {
    startTime: string;
    uptime: number;
    lastActivity: string;
  };
}

const MonitoringDashboard: React.FC = () => {
  const [stats, setStats] = useState<MonitoringStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const fetchStats = async () => {
    try {
      setError(null);

      const token = tokenManager.getAccessToken();

      const response = await fetch(buildApiUrl("monitor/stats"), {
        headers: {
          Authorization: token ? `Bearer ${token}` : "",
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) {
        if (response.status === 401) {
          throw new Error("يجب تسجيل الدخول لعرض إحصائيات المراقبة");
        }
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (data.success) {
        setStats(data.data);
        setLastUpdated(new Date());
      } else {
        throw new Error(data.error || "Failed to fetch stats");
      }
    } catch (err) {
      console.error("Error fetching monitoring stats:", err);
      setError(err instanceof Error ? err.message : "Unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStats();

    // Auto-refresh every 5 minutes (reduced from 30 seconds)
    const interval = setInterval(fetchStats, 5 * 60 * 1000);

    return () => clearInterval(interval);
  }, []);

  const getHealthStatusColor = (status: string) => {
    switch (status) {
      case "healthy":
        return "text-green-600 bg-green-100";
      case "warning":
        return "text-yellow-600 bg-yellow-100";
      case "critical":
        return "text-red-600 bg-red-100";
      default:
        return "text-gray-600 bg-gray-100";
    }
  };

  const getHealthStatusIcon = (status: string) => {
    switch (status) {
      case "healthy":
        return <CheckCircle className="w-5 h-5 text-green-600" />;
      case "warning":
        return <AlertTriangle className="w-5 h-5 text-yellow-600" />;
      case "critical":
        return <XCircle className="w-5 h-5 text-red-600" />;
      default:
        return <Activity className="w-5 h-5 text-gray-600" />;
    }
  };

  const formatUptime = (uptime: number) => {
    const seconds = Math.floor(uptime / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days}d ${hours % 24}h ${minutes % 60}m`;
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const formatTimestamp = (timestamp: string) => {
    return new Date(timestamp).toLocaleString("ar-EG", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="flex items-center space-x-2">
          <RefreshCw className="w-6 h-6 animate-spin" />
          <span>جاري تحميل بيانات المراقبة...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen space-y-4">
        <XCircle className="w-12 h-12 text-red-500" />
        <h2 className="text-xl font-semibold text-red-600">
          خطأ في تحميل البيانات
        </h2>
        <p className="text-gray-600 text-center max-w-md">{error}</p>
        <Button onClick={fetchStats} variant="outline">
          <RefreshCw className="w-4 h-4 mr-2" />
          إعادة المحاولة
        </Button>
      </div>
    );
  }

  if (!stats) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <p className="text-gray-500">لا توجد بيانات متاحة</p>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            لوحة مراقبة النظام
          </h1>
          <p className="text-gray-600 mt-1">
            آخر تحديث:{" "}
            {lastUpdated
              ? formatTimestamp(lastUpdated.toISOString())
              : "غير محدد"}
          </p>
        </div>
        <Button onClick={fetchStats} variant="outline" size="sm">
          <RefreshCw className="w-4 h-4 mr-2" />
          تحديث
        </Button>
      </div>

      {/* Health Status */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2 space-x-reverse">
            {getHealthStatusIcon(stats.summary.healthStatus)}
            <span>حالة النظام</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center space-x-4 space-x-reverse">
            <Badge className={getHealthStatusColor(stats.summary.healthStatus)}>
              {stats.summary.healthStatus === "healthy" && "صحي"}
              {stats.summary.healthStatus === "warning" && "تحذير"}
              {stats.summary.healthStatus === "critical" && "حرج"}
              {stats.summary.healthStatus === "unknown" && "غير معروف"}
            </Badge>
            <span className="text-sm text-gray-600">
              وقت التشغيل: {formatUptime(stats.summary.uptime)}
            </span>
          </div>
        </CardContent>
      </Card>

      {/* Alerts Panel */}
      <AlertsPanel />

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatsCard
          title="إجمالي الردود"
          value={stats.summary.totalResponses}
          subtitle={`ناجح: ${stats.responses.successful} | فاشل: ${stats.responses.failed}`}
          icon={<MessageSquare className="w-4 h-4" />}
          color="blue"
        />

        <StatsCard
          title="معدل الأخطاء"
          value={`${stats.summary.errorRate.toFixed(2)}%`}
          subtitle={`${stats.errors.total} خطأ إجمالي`}
          icon={<AlertTriangle className="w-4 h-4" />}
          color={
            stats.summary.errorRate > 10
              ? "red"
              : stats.summary.errorRate > 5
                ? "yellow"
                : "green"
          }
        />

        <StatsCard
          title="متوسط وقت الاستجابة"
          value={`${stats.summary.averageResponseTime.toLocaleString()}ms`}
          subtitle={`بطيء: ${stats.responses.slow} ردود`}
          icon={<Clock className="w-4 h-4" />}
          color={
            stats.summary.averageResponseTime > 10000
              ? "red"
              : stats.summary.averageResponseTime > 5000
                ? "yellow"
                : "green"
          }
        />

        <StatsCard
          title="معدل النجاح"
          value={`${stats.summary.successRate.toFixed(2)}%`}
          subtitle={`فارغ: ${stats.responses.empty} ردود`}
          icon={<Target className="w-4 h-4" />}
          color={
            stats.summary.successRate < 90
              ? "red"
              : stats.summary.successRate < 95
                ? "yellow"
                : "green"
          }
        />
      </div>

      {/* Performance Chart */}
      <PerformanceChart />

      {/* Recent Errors Section */}
      {stats.errors.recent.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2 space-x-reverse">
              <XCircle className="w-5 h-5 text-red-500" />
              <span>الأخطاء الأخيرة</span>
              <Badge variant="destructive" className="mr-2">
                {stats.errors.total}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {stats.errors.recent.slice(0, 5).map((error) => (
                <div
                  key={error.id}
                  className="border-r-4 border-red-400 bg-red-50 p-3 rounded"
                >
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="flex items-center space-x-2 space-x-reverse mb-1">
                        <Badge variant="outline" className="text-xs">
                          {error.type}
                        </Badge>
                        <span className="text-xs text-gray-500">
                          {formatTimestamp(error.timestamp)}
                        </span>
                      </div>
                      <p className="text-sm text-red-800 font-medium">
                        {error.message}
                      </p>
                      {error.context && error.context.customerId && (
                        <p className="text-xs text-red-600 mt-1">
                          العميل: {error.context.customerId}
                        </p>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {stats.errors.recent.length > 5 && (
              <div className="mt-4 text-center">
                <Button variant="outline" size="sm">
                  عرض جميع الأخطاء ({stats.errors.total})
                </Button>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Performance Summary */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2 space-x-reverse">
              <TrendingUp className="w-5 h-5 text-blue-500" />
              <span>ملخص الأداء</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              <div className="flex justify-between">
                <span className="text-sm text-gray-600">أسرع استجابة:</span>
                <span className="text-sm font-medium">
                  {stats.performance.minResponseTime !== null
                    ? `${stats.performance.minResponseTime}ms`
                    : "غير متاح"}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-sm text-gray-600">أبطأ استجابة:</span>
                <span className="text-sm font-medium">
                  {stats.performance.maxResponseTime}ms
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-sm text-gray-600">إجمالي البيانات:</span>
                <span className="text-sm font-medium">
                  {stats.performance.responseTimes.length} نقطة
                </span>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2 space-x-reverse">
              <Activity className="w-5 h-5 text-green-500" />
              <span>معلومات النظام</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              <div className="flex justify-between">
                <span className="text-sm text-gray-600">بدء التشغيل:</span>
                <span className="text-sm font-medium">
                  {formatTimestamp(stats.system.startTime)}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-sm text-gray-600">آخر نشاط:</span>
                <span className="text-sm font-medium">
                  {formatTimestamp(stats.system.lastActivity)}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-sm text-gray-600">حالة الاتصال:</span>
                <Badge className="bg-green-100 text-green-800">متصل</Badge>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default MonitoringDashboard;

import React, { useState, useEffect } from "react";
import {
  Box,
  Container,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  TextField,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  Grid,
  Card,
  CardContent,
  IconButton,
  Tooltip,
  Button,
  CircularProgress,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Stack,
} from "@mui/material";
import {
  Visibility as VisibilityIcon,
  FileDownload as FileDownloadIcon,
  FilterList as FilterListIcon,
  CheckCircle as CheckCircleIcon,
  Error as ErrorIcon,
  Info as InfoIcon,
  Warning as WarningIcon,
} from "@mui/icons-material";
import { format } from "date-fns";
import { ar } from "date-fns/locale";
import { apiClient } from "../services/apiClient";

const MyActivity = () => {
  const [activities, setActivities] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Pagination
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalActivities, setTotalActivities] = useState(0);

  // Filters
  const [filters, setFilters] = useState({
    category: "",
    action: "",
    severity: "",
    isSuccess: "",
    startDate: "",
    endDate: "",
    search: "",
  });

  // Dialog
  const [selectedActivity, setSelectedActivity] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  // Fetch activities
  const fetchActivities = async () => {
    try {
      setLoading(true);
      const params = {
        page: page + 1,
        limit: rowsPerPage,
        ...filters,
      };

      // Remove empty filters
      Object.keys(params).forEach((key) => {
        if (params[key] === "") delete params[key];
      });

      const response = await apiClient.get("/activity/my-activities", {
        params,
      });

      if (response.data.success) {
        setActivities(response.data.data.activities);
        setTotalActivities(response.data.data.pagination.total);
      }
    } catch (err) {
      setError(err.response?.data?.message || "حدث خطأ أثناء جلب النشاطات");
    } finally {
      setLoading(false);
    }
  };

  // Fetch stats
  const fetchStats = async () => {
    try {
      const response = await apiClient.get("/activity/my-stats");

      if (response.data.success) {
        setStats(response.data.data);
      }
    } catch (err) {
      console.error("Error fetching stats:", err);
    }
  };

  useEffect(() => {
    fetchActivities();
    fetchStats();
  }, [
    page,
    rowsPerPage,
    filters.category,
    filters.action,
    filters.severity,
    filters.isSuccess,
    filters.startDate,
    filters.endDate,
    filters.search,
  ]);

  // Export activities
  const handleExport = async () => {
    try {
      const response = await apiClient.get("/activity/export/csv", {
        params: filters,
        responseType: "blob",
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", `my-activities-${Date.now()}.csv`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (err) {
      setError("حدث خطأ أثناء تصدير النشاطات");
    }
  };

  // View activity details
  const handleViewDetails = (activity) => {
    setSelectedActivity(activity);
    setDialogOpen(true);
  };

  // Get severity color
  const getSeverityColor = (severity) => {
    switch (severity) {
      case "LOW":
        return "success";
      case "MEDIUM":
        return "info";
      case "HIGH":
        return "warning";
      case "CRITICAL":
        return "error";
      default:
        return "default";
    }
  };

  // Get severity icon
  const getSeverityIcon = (severity) => {
    switch (severity) {
      case "LOW":
        return <InfoIcon fontSize="small" />;
      case "MEDIUM":
        return <InfoIcon fontSize="small" />;
      case "HIGH":
        return <WarningIcon fontSize="small" />;
      case "CRITICAL":
        return <ErrorIcon fontSize="small" />;
      default:
        return <InfoIcon fontSize="small" />;
    }
  };

  // Get category label in Arabic
  const getCategoryLabel = (category) => {
    const labels = {
      AUTH: "المصادقة",
      ADS: "الإعلانات",
      CONVERSATIONS: "المحادثات",
      BILLING: "الفواتير",
      SETTINGS: "الإعدادات",
      SUPPORT: "الدعم الفني",
      FILES: "الملفات",
      USERS: "المستخدمين",
      COMPANY: "الشركة",
      REPORTS: "التقارير",
    };
    return labels[category] || category;
  };

  // Get action label in Arabic
  const getActionLabel = (action) => {
    const labels = {
      CREATE: "إنشاء",
      UPDATE: "تعديل",
      DELETE: "حذف",
      LOGIN: "تسجيل دخول",
      LOGOUT: "تسجيل خروج",
      UPLOAD: "رفع",
      DOWNLOAD: "تحميل",
      VIEW: "عرض",
      SEND: "إرسال",
      RECEIVE: "استقبال",
      ACTIVATE: "تفعيل",
      DEACTIVATE: "إيقاف",
      APPROVE: "موافقة",
      REJECT: "رفض",
      EXPORT: "تصدير",
      IMPORT: "استيراد",
    };
    return labels[action] || action;
  };

  return (
    <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom sx={{ mb: 3, fontWeight: "bold" }}>
        📊 نشاطاتي
      </Typography>

      {/* Stats Cards */}
      {stats && (
        <Grid container spacing={3} sx={{ mb: 3 }}>
          <Grid item xs={12} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  إجمالي النشاطات
                </Typography>
                <Typography variant="h4">{stats.totalActivities}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  آخر نشاط
                </Typography>
                <Typography variant="body1">
                  {stats.lastActivity
                    ? format(new Date(stats.lastActivity.createdAt), "PPp", {
                        locale: ar,
                      })
                    : "لا يوجد"}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  التصنيفات الأكثر نشاطاً
                </Typography>
                <Stack direction="row" spacing={1} flexWrap="wrap">
                  {stats.categoryStats && stats.categoryStats.length > 0 ? (
                    stats.categoryStats
                      .slice(0, 5)
                      .map((cat) => (
                        <Chip
                          key={cat._id}
                          label={`${getCategoryLabel(cat._id)}: ${cat.count}`}
                          size="small"
                          color="primary"
                          variant="outlined"
                        />
                      ))
                  ) : (
                    <Typography variant="body2" color="textSecondary">
                      لا توجد تصنيفات
                    </Typography>
                  )}
                </Stack>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Filters */}
      <Paper sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>التصنيف</InputLabel>
              <Select
                value={filters.category}
                label="التصنيف"
                onChange={(e) =>
                  setFilters({ ...filters, category: e.target.value })
                }
              >
                <MenuItem value="">الكل</MenuItem>
                <MenuItem value="AUTH">المصادقة</MenuItem>
                <MenuItem value="ADS">الإعلانات</MenuItem>
                <MenuItem value="CONVERSATIONS">المحادثات</MenuItem>
                <MenuItem value="BILLING">الفواتير</MenuItem>
                <MenuItem value="SETTINGS">الإعدادات</MenuItem>
                <MenuItem value="SUPPORT">الدعم الفني</MenuItem>
                <MenuItem value="FILES">الملفات</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>الخطورة</InputLabel>
              <Select
                value={filters.severity}
                label="الخطورة"
                onChange={(e) =>
                  setFilters({ ...filters, severity: e.target.value })
                }
              >
                <MenuItem value="">الكل</MenuItem>
                <MenuItem value="LOW">منخفض</MenuItem>
                <MenuItem value="MEDIUM">متوسط</MenuItem>
                <MenuItem value="HIGH">عالي</MenuItem>
                <MenuItem value="CRITICAL">حرج</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>الحالة</InputLabel>
              <Select
                value={filters.isSuccess}
                label="الحالة"
                onChange={(e) =>
                  setFilters({ ...filters, isSuccess: e.target.value })
                }
              >
                <MenuItem value="">الكل</MenuItem>
                <MenuItem value="true">نجح</MenuItem>
                <MenuItem value="false">فشل</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={3}>
            <TextField
              fullWidth
              size="small"
              label="بحث"
              value={filters.search}
              onChange={(e) =>
                setFilters({ ...filters, search: e.target.value })
              }
              placeholder="ابحث في الوصف..."
            />
          </Grid>

          <Grid item xs={12} md={3}>
            <Button
              fullWidth
              variant="outlined"
              startIcon={<FileDownloadIcon />}
              onClick={handleExport}
            >
              تصدير CSV
            </Button>
          </Grid>
        </Grid>
      </Paper>

      {/* Error Alert */}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {/* Activities Table */}
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>التاريخ والوقت</TableCell>
              <TableCell>التصنيف</TableCell>
              <TableCell>الإجراء</TableCell>
              <TableCell>الوصف</TableCell>
              <TableCell>الخطورة</TableCell>
              <TableCell>الحالة</TableCell>
              <TableCell>تفاصيل</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  <CircularProgress />
                </TableCell>
              </TableRow>
            ) : activities.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  لا توجد نشاطات
                </TableCell>
              </TableRow>
            ) : (
              activities.map((activity) => (
                <TableRow key={activity._id} hover>
                  <TableCell>
                    {format(new Date(activity.createdAt), "PPp", {
                      locale: ar,
                    })}
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={getCategoryLabel(activity.category)}
                      size="small"
                      color="primary"
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>{getActionLabel(activity.action)}</TableCell>
                  <TableCell>{activity.description}</TableCell>
                  <TableCell>
                    <Chip
                      icon={getSeverityIcon(activity.severity)}
                      label={activity.severity}
                      size="small"
                      color={getSeverityColor(activity.severity)}
                    />
                  </TableCell>
                  <TableCell>
                    {activity.isSuccess ? (
                      <CheckCircleIcon color="success" />
                    ) : (
                      <ErrorIcon color="error" />
                    )}
                  </TableCell>
                  <TableCell>
                    <Tooltip title="عرض التفاصيل">
                      <IconButton
                        size="small"
                        onClick={() => handleViewDetails(activity)}
                      >
                        <VisibilityIcon />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
        <TablePagination
          component="div"
          count={totalActivities}
          page={page}
          onPageChange={(e, newPage) => setPage(newPage)}
          rowsPerPage={rowsPerPage}
          onRowsPerPageChange={(e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          }}
          labelRowsPerPage="عدد الصفوف:"
          labelDisplayedRows={({ from, to, count }) =>
            `${from}-${to} من ${count}`
          }
        />
      </TableContainer>

      {/* Activity Details Dialog */}
      <Dialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>تفاصيل النشاط</DialogTitle>
        <DialogContent>
          {selectedActivity && (
            <Box sx={{ mt: 2 }}>
              <Grid container spacing={2}>
                <Grid item xs={6}>
                  <Typography variant="subtitle2" color="textSecondary">
                    التصنيف
                  </Typography>
                  <Typography variant="body1">
                    {getCategoryLabel(selectedActivity.category)}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="subtitle2" color="textSecondary">
                    الإجراء
                  </Typography>
                  <Typography variant="body1">
                    {getActionLabel(selectedActivity.action)}
                  </Typography>
                </Grid>
                <Grid item xs={12}>
                  <Typography variant="subtitle2" color="textSecondary">
                    الوصف
                  </Typography>
                  <Typography variant="body1">
                    {selectedActivity.description}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="subtitle2" color="textSecondary">
                    التاريخ والوقت
                  </Typography>
                  <Typography variant="body1">
                    {format(new Date(selectedActivity.createdAt), "PPpp", {
                      locale: ar,
                    })}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="subtitle2" color="textSecondary">
                    الحالة
                  </Typography>
                  <Typography variant="body1">
                    {selectedActivity.isSuccess ? "نجح ✅" : "فشل ❌"}
                  </Typography>
                </Grid>
                {selectedActivity.metadata && (
                  <>
                    <Grid item xs={6}>
                      <Typography variant="subtitle2" color="textSecondary">
                        عنوان IP
                      </Typography>
                      <Typography variant="body1">
                        {selectedActivity.metadata.ipAddress || "غير متوفر"}
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="subtitle2" color="textSecondary">
                        المتصفح
                      </Typography>
                      <Typography variant="body1">
                        {selectedActivity.metadata.browser || "غير متوفر"}
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="subtitle2" color="textSecondary">
                        نظام التشغيل
                      </Typography>
                      <Typography variant="body1">
                        {selectedActivity.metadata.os || "غير متوفر"}
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="subtitle2" color="textSecondary">
                        نوع الجهاز
                      </Typography>
                      <Typography variant="body1">
                        {selectedActivity.metadata.deviceType || "غير متوفر"}
                      </Typography>
                    </Grid>
                  </>
                )}
              </Grid>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default MyActivity;

import React, { useState, useEffect } from "react";
import { apiClient } from "../services/apiClient";
import { useAuth } from "../hooks/useAuthSimple";
import useSocket from "../hooks/useSocket";
import {
  BellIcon,
  CheckIcon,
  EyeIcon,
  TrashIcon,
  ExclamationTriangleIcon,
  InformationCircleIcon,
  XCircleIcon,
  CheckCircleIcon,
} from "@heroicons/react/24/outline";
import { BellIcon as BellSolidIcon } from "@heroicons/react/24/solid";

interface NotificationItem {
  id: string;
  type: "error" | "warning" | "info" | "success" | "test" | "ai_error";
  title: string;
  message: string;
  timestamp: Date;
  isRead: boolean;
  silent?: boolean;
  customerId?: string;
  errorType?: string;
  metadata?: any;
  severity?: "low" | "medium" | "high" | "critical";
  source?: "system" | "ai"; // مصدر الإشعار
}

const Notifications: React.FC = () => {
  const { user, isAuthenticated } = useAuth();
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<"all" | "unread" | "read">("all");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [sourceFilter, setSourceFilter] = useState<"all" | "system" | "ai">(
    "all",
  );
  const { socket } = useSocket();

  useEffect(() => {
    fetchNotifications();
    fetchAINotifications();
  }, [user, isAuthenticated]);

  // الاستماع لإشعارات AI الجديدة عبر Socket.io
  useEffect(() => {
    if (!socket) return;

    const handleAINotification = (aiNotification: any) => {
      console.log(
        "📢 [Notifications] Received AI notification:",
        aiNotification,
      );

      // تحويل إشعار AI للصيغة الموحدة
      const notification: NotificationItem = {
        id: aiNotification.id,
        type: "ai_error",
        title: aiNotification.title,
        message: aiNotification.message,
        timestamp: new Date(aiNotification.createdAt || Date.now()),
        isRead: false,
        metadata: aiNotification.metadata,
        severity: aiNotification.severity,
        source: "ai",
      };

      setNotifications((prev: NotificationItem[]) => [notification, ...prev]);
    };

    // استخدام socket.on مباشرة بدون type checking
    (socket as any).on("ai_notification", handleAINotification);

    return () => {
      (socket as any).off("ai_notification", handleAINotification);
    };
  }, [socket]);

  const fetchNotifications = async () => {
    if (!user || !isAuthenticated) {
      setLoading(false);
      return;
    }

    try {
      const response = await apiClient.get("/v1/notifications/recent", {
        params: { limit: 50 },
      });

      if (response.data.success || response.status === 200) {
        const systemNotifications = (response.data.notifications || []).map(
          (n: any) => ({
            ...n,
            source: "system" as const,
          }),
        );

        setNotifications((prev: NotificationItem[]) => {
          // دمج الإشعارات الجديدة مع الموجودة (AI notifications)
          const aiNotifications = prev.filter(
            (n: NotificationItem) => n.source === "ai",
          );
          return [...systemNotifications, ...aiNotifications];
        });
      }
    } catch (error) {
      console.error(
        "❌ [NotificationsPage] Error fetching notifications:",
        error,
      );
    } finally {
      setLoading(false);
    }
  };

  const fetchAINotifications = async () => {
    if (!isAuthenticated) return;

    try {
      const response = await apiClient.get("/ai-notifications", {
        params: { limit: 50 },
      });

      if (response.data.success) {
        const aiNotifications = response.data.data.notifications.map(
          (n: any) => ({
            id: n.id,
            type: "ai_error" as const,
            title: n.title,
            message: n.message,
            timestamp: new Date(n.createdAt),
            isRead: n.isRead,
            metadata: n.metadata,
            severity: n.severity,
            source: "ai" as const,
          }),
        );

        setNotifications((prev: NotificationItem[]) => {
          // دمج إشعارات AI مع إشعارات النظام
          const systemNotifications = prev.filter(
            (n: NotificationItem) => n.source === "system",
          );
          return [...systemNotifications, ...aiNotifications];
        });
      }
    } catch (error) {
      console.error("❌ Error fetching AI notifications:", error);
    }
  };

  const markAsRead = async (
    notificationId: string,
    source: "system" | "ai" = "system",
  ) => {
    try {
      if (source === "ai") {
        await apiClient.patch(`/ai-notifications/${notificationId}/read`, {});
      } else {
        await apiClient.post(`/notifications/${notificationId}/read`, {});
      }

      setNotifications((prev: NotificationItem[]) =>
        prev.map((n: NotificationItem) =>
          n.id === notificationId ? { ...n, isRead: true } : n,
        ),
      );
    } catch (error) {
      console.error("Error marking notification as read:", error);
    }
  };

  const markAllAsRead = async () => {
    try {
      await apiClient.post("/notifications/mark-all-read", {});

      setNotifications((prev: NotificationItem[]) =>
        prev.map((n: NotificationItem) => ({ ...n, isRead: true })),
      );
    } catch (error) {
      console.error("Error marking all notifications as read:", error);
    }
  };

  const deleteNotification = async (notificationId: string) => {
    try {
      await apiClient.delete(`/notifications/${notificationId}`);
      setNotifications((prev) => prev.filter((n) => n.id !== notificationId));
    } catch (error) {
      console.error("Error deleting notification:", error);
    }
  };

  const getIcon = (type: string, severity?: string) => {
    // إشعارات AI حسب الخطورة
    if (type === "ai_error") {
      switch (severity) {
        case "critical":
          return <XCircleIcon className="h-6 w-6 text-red-600" />;
        case "high":
          return (
            <ExclamationTriangleIcon className="h-6 w-6 text-orange-500" />
          );
        case "medium":
          return (
            <ExclamationTriangleIcon className="h-6 w-6 text-yellow-500" />
          );
        default:
          return <InformationCircleIcon className="h-6 w-6 text-blue-500" />;
      }
    }

    // إشعارات النظام العادية
    switch (type) {
      case "error":
        return <XCircleIcon className="h-6 w-6 text-red-500" />;
      case "warning":
        return <ExclamationTriangleIcon className="h-6 w-6 text-yellow-500" />;
      case "success":
        return <CheckCircleIcon className="h-6 w-6 text-green-500" />;
      case "test":
        return <BellSolidIcon className="h-6 w-6 text-blue-500" />;
      default:
        return <InformationCircleIcon className="h-6 w-6 text-blue-500" />;
    }
  };

  const getTypeColor = (type: string, severity?: string) => {
    // إشعارات AI حسب الخطورة
    if (type === "ai_error") {
      switch (severity) {
        case "critical":
          return "bg-red-100 text-red-800 border-red-200";
        case "high":
          return "bg-orange-100 text-orange-800 border-orange-200";
        case "medium":
          return "bg-yellow-100 text-yellow-800 border-yellow-200";
        default:
          return "bg-blue-100 text-blue-800 border-blue-200";
      }
    }

    // إشعارات النظام العادية
    switch (type) {
      case "error":
        return "bg-red-100 text-red-800 border-red-200";
      case "warning":
        return "bg-yellow-100 text-yellow-800 border-yellow-200";
      case "success":
        return "bg-green-100 text-green-800 border-green-200";
      case "test":
        return "bg-blue-100 text-blue-800 border-blue-200";
      default:
        return "bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-200 border-gray-200 dark:border-gray-600";
    }
  };

  const filteredNotifications = notifications
    .filter((notification: NotificationItem) => {
      const matchesReadFilter =
        filter === "all" ||
        (filter === "read" && notification.isRead) ||
        (filter === "unread" && !notification.isRead);

      const matchesTypeFilter =
        typeFilter === "all" || notification.type === typeFilter;

      const matchesSourceFilter =
        sourceFilter === "all" || notification.source === sourceFilter;

      return matchesReadFilter && matchesTypeFilter && matchesSourceFilter;
    })
    .sort(
      (a: NotificationItem, b: NotificationItem) =>
        new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
    );

  const unreadCount = notifications.filter(
    (n: NotificationItem) => !n.isRead,
  ).length;

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3 space-x-reverse">
              <BellSolidIcon className="h-8 w-8 text-blue-600" />
              <div>
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
                  الإشعارات
                </h1>
                <p className="text-gray-600 dark:text-gray-400">
                  إجمالي الإشعارات: {notifications.length} | غير مقروءة:{" "}
                  {unreadCount}
                </p>
              </div>
            </div>

            {unreadCount > 0 && (
              <button
                onClick={markAllAsRead}
                className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors duration-200 flex items-center space-x-2 space-x-reverse"
              >
                <CheckIcon className="h-5 w-5" />
                <span>تحديد الكل كمقروء</span>
              </button>
            )}
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-6 mb-6">
          <div className="flex flex-wrap gap-4">
            {/* Read Status Filter */}
            <div className="flex items-center space-x-2 space-x-reverse">
              <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                الحالة:
              </label>
              <select
                value={filter}
                onChange={(e) => setFilter(e.target.value as any)}
                className="border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white px-3 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="all">الكل</option>
                <option value="unread">غير مقروءة</option>
                <option value="read">مقروءة</option>
              </select>
            </div>

            {/* Type Filter */}
            <div className="flex items-center space-x-2 space-x-reverse">
              <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                النوع:
              </label>
              <select
                value={typeFilter}
                onChange={(e) => setTypeFilter(e.target.value)}
                className="border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white px-3 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="all">الكل</option>
                <option value="info">معلومات</option>
                <option value="success">نجاح</option>
                <option value="warning">تحذير</option>
                <option value="error">خطأ</option>
                <option value="ai_error">أخطاء AI</option>
                <option value="test">تجريبي</option>
              </select>
            </div>

            {/* Source Filter */}
            <div className="flex items-center space-x-2 space-x-reverse">
              <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                المصدر:
              </label>
              <select
                value={sourceFilter}
                onChange={(e) => setSourceFilter(e.target.value as any)}
                className="border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white px-3 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="all">الكل</option>
                <option value="system">النظام</option>
                <option value="ai">الذكاء الاصطناعي</option>
              </select>
            </div>
          </div>
        </div>

        {/* Notifications List */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm">
          {filteredNotifications.length === 0 ? (
            <div className="p-12 text-center">
              <BellIcon className="h-16 w-16 text-gray-300 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                لا توجد إشعارات
              </h3>
              <p className="text-gray-500 dark:text-gray-400">
                {filter === "unread"
                  ? "لا توجد إشعارات غير مقروءة"
                  : "لا توجد إشعارات متاحة"}
              </p>
            </div>
          ) : (
            <div className="divide-y divide-gray-200 dark:divide-gray-700">
              {filteredNotifications.map((notification: NotificationItem) => (
                <div
                  key={notification.id}
                  className={`p-6 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors duration-200 ${
                    !notification.isRead
                      ? "bg-blue-50 dark:bg-blue-900/20 border-r-4 border-blue-500"
                      : ""
                  }`}
                >
                  <div className="flex items-start space-x-4 space-x-reverse">
                    <div className="flex-shrink-0 mt-1">
                      {getIcon(notification.type, notification.severity)}
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center space-x-2 space-x-reverse mb-2">
                            <h3
                              className={`text-lg font-medium ${!notification.isRead ? "text-gray-900 dark:text-white" : "text-gray-700 dark:text-gray-300"}`}
                            >
                              {notification.title}
                            </h3>
                            <span
                              className={`px-2 py-1 text-xs rounded-full border ${getTypeColor(notification.type, notification.severity)}`}
                            >
                              {notification.type === "ai_error"
                                ? notification.severity === "critical"
                                  ? "🚨 AI حرج"
                                  : notification.severity === "high"
                                    ? "⚠️ AI عالي"
                                    : notification.severity === "medium"
                                      ? "⚡ AI متوسط"
                                      : "ℹ️ AI"
                                : notification.type === "test"
                                  ? "تجريبي"
                                  : notification.type === "success"
                                    ? "نجاح"
                                    : notification.type === "error"
                                      ? "خطأ"
                                      : notification.type === "warning"
                                        ? "تحذير"
                                        : "معلومات"}
                            </span>
                          </div>

                          <p className="text-gray-600 dark:text-gray-400 mb-3 whitespace-pre-wrap">
                            {notification.message}
                          </p>

                          <div className="flex items-center space-x-4 space-x-reverse text-sm text-gray-500 dark:text-gray-400">
                            <span>
                              {new Date(notification.timestamp).toLocaleString(
                                "ar-EG",
                              )}
                            </span>
                            {notification.isRead && (
                              <span className="flex items-center space-x-1 space-x-reverse">
                                <CheckIcon className="h-4 w-4" />
                                <span>مقروء</span>
                              </span>
                            )}
                          </div>
                        </div>

                        <div className="flex items-center space-x-2 space-x-reverse mr-4">
                          {!notification.isRead && (
                            <button
                              onClick={() =>
                                markAsRead(notification.id, notification.source)
                              }
                              className="p-2 text-gray-400 hover:text-blue-600 transition-colors duration-200"
                              title="تحديد كمقروء"
                            >
                              <EyeIcon className="h-5 w-5" />
                            </button>
                          )}

                          <button
                            onClick={() => deleteNotification(notification.id)}
                            className="p-2 text-gray-400 hover:text-red-600 transition-colors duration-200"
                            title="حذف الإشعار"
                          >
                            <TrashIcon className="h-5 w-5" />
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Notifications;

import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Alert,
  CircularProgress,
  Grid,
  Chip,
  IconButton,
  Snackbar,
  Paper,
  Divider,
} from "@mui/material";
import {
  ContentCopy as CopyIcon,
  CloudUpload as UploadIcon,
  CheckCircle as CheckIcon,
  Error as ErrorIcon,
} from "@mui/icons-material";
import { apiClient } from "../services/apiClient";

const PaymentPage = () => {
  const { invoiceId } = useParams();
  const [invoice, setInvoice] = useState(null);
  const [walletNumbers, setWalletNumbers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "info",
  });

  useEffect(() => {
    fetchInvoiceData();
    fetchWalletNumbers();
  }, [invoiceId]);

  const fetchInvoiceData = async () => {
    try {
      const response = await apiClient.get(
        `/wallet-payment/invoice/${invoiceId}`,
      );
      if (response.data.success) {
        setInvoice(response.data.data);
      } else {
        setError(response.data.message);
      }
    } catch (error) {
      console.error("خطأ في جلب الفاتورة:", error);
      setError("خطأ في جلب بيانات الفاتورة");
    }
  };

  const fetchWalletNumbers = async () => {
    try {
      const response = await apiClient.get("/wallet-payment/wallet-numbers");
      if (response.data.success) {
        setWalletNumbers(response.data.data);
      }
    } catch (error) {
      console.error("خطأ في جلب أرقام المحافظ:", error);
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text, walletName) => {
    navigator.clipboard.writeText(text).then(() => {
      setSnackbar({
        open: true,
        message: `تم نسخ رقم ${walletName}`,
        severity: "success",
      });
    });
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        setSnackbar({
          open: true,
          message: "حجم الملف يجب أن يكون أقل من 5 ميجابايت",
          severity: "error",
        });
        return;
      }
      setSelectedFile(file);
    }
  };

  const submitReceipt = async (walletNumberId) => {
    if (!selectedFile) {
      setSnackbar({
        open: true,
        message: "يرجى اختيار صورة الإيصال أولاً",
        severity: "warning",
      });
      return;
    }

    setUploading(true);
    const formData = new FormData();
    formData.append("receipt", selectedFile);
    formData.append("invoiceId", invoiceId);
    formData.append("walletNumberId", walletNumberId);

    try {
      const response = await apiClient.post(
        "/wallet-payment/submit-receipt",
        formData,
      );

      if (response.data.success) {
        setSubmitted(true);
        setSnackbar({
          open: true,
          message: "تم إرسال الإيصال بنجاح! سيتم مراجعته قريباً",
          severity: "success",
        });
      } else {
        setSnackbar({
          open: true,
          message: response.data.message,
          severity: "error",
        });
      }
    } catch (error) {
      console.error("خطأ في إرسال الإيصال:", error);
      setSnackbar({
        open: true,
        message: "خطأ في إرسال الإيصال",
        severity: "error",
      });
    } finally {
      setUploading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="100vh"
        className="bg-gray-50 dark:bg-gray-900"
      >
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} className="min-h-screen bg-gray-50 dark:bg-gray-900">
        <Alert
          severity="error"
          sx={{ maxWidth: 600, mx: "auto" }}
          className="bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800 text-red-800 dark:text-red-200"
        >
          {error}
        </Alert>
      </Box>
    );
  }

  if (submitted) {
    return (
      <Box
        p={3}
        maxWidth={600}
        mx="auto"
        className="min-h-screen bg-gray-50 dark:bg-gray-900"
      >
        <Card className="bg-white dark:bg-gray-800 shadow-lg dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700">
          <CardContent sx={{ textAlign: "center", py: 4 }}>
            <CheckIcon
              sx={{ fontSize: 64, color: "success.main", mb: 2 }}
              className="text-green-600 dark:text-green-400"
            />
            <Typography
              variant="h5"
              gutterBottom
              className="text-gray-900 dark:text-white"
            >
              تم إرسال الإيصال بنجاح!
            </Typography>
            <Typography
              variant="body1"
              className="text-gray-600 dark:text-gray-400"
            >
              سيتم مراجعة إيصال الدفع وتأكيد الدفع خلال 24 ساعة
            </Typography>
          </CardContent>
        </Card>
      </Box>
    );
  }

  return (
    <Box
      p={3}
      maxWidth={800}
      mx="auto"
      className="min-h-screen bg-gray-50 dark:bg-gray-900"
    >
      <Typography
        variant="h4"
        gutterBottom
        textAlign="center"
        sx={{ mb: 4 }}
        className="text-gray-900 dark:text-white"
      >
        🧾 دفع الفاتورة
      </Typography>

      {/* تفاصيل الفاتورة */}
      <Card
        sx={{ mb: 3 }}
        className="bg-white dark:bg-gray-800 shadow-lg dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700"
      >
        <CardContent>
          <Typography
            variant="h6"
            gutterBottom
            className="text-gray-900 dark:text-white font-semibold"
          >
            تفاصيل الفاتورة
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <Typography
                variant="body2"
                className="text-gray-600 dark:text-gray-400"
              >
                رقم الفاتورة
              </Typography>
              <Typography
                variant="body1"
                className="font-bold text-gray-900 dark:text-white"
              >
                {invoice?.invoiceNumber}
              </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
              <Typography
                variant="body2"
                className="text-gray-600 dark:text-gray-400"
              >
                الشركة
              </Typography>
              <Typography
                variant="body1"
                className="font-bold text-gray-900 dark:text-white"
              >
                {invoice?.company?.name}
              </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
              <Typography
                variant="body2"
                className="text-gray-600 dark:text-gray-400"
              >
                المبلغ المطلوب
              </Typography>
              <Typography
                variant="h6"
                className="font-bold text-blue-600 dark:text-blue-400"
              >
                {formatCurrency(invoice?.totalAmount)}
              </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
              <Typography
                variant="body2"
                className="text-gray-600 dark:text-gray-400"
              >
                تاريخ الاستحقاق
              </Typography>
              <Typography
                variant="body1"
                className="font-bold text-gray-900 dark:text-white"
              >
                {formatDate(invoice?.dueDate)}
              </Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* أرقام المحافظ */}
      <Card
        sx={{ mb: 3 }}
        className="bg-white dark:bg-gray-800 shadow-lg dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700"
      >
        <CardContent>
          <Typography
            variant="h6"
            gutterBottom
            className="text-gray-900 dark:text-white font-semibold"
          >
            💳 أرقام المحافظ المتاحة
          </Typography>
          <Typography
            variant="body2"
            sx={{ mb: 2 }}
            className="text-gray-600 dark:text-gray-400"
          >
            اختر رقم المحفظة المناسب وانسخه لإجراء التحويل
          </Typography>

          <Grid container spacing={2}>
            {walletNumbers.map((wallet) => (
              <Grid item xs={12} sm={6} key={wallet.id}>
                <Paper
                  sx={{
                    p: 2,
                    border: 1,
                    borderColor: "divider",
                    "&:hover": { borderColor: "primary.main" },
                  }}
                  className="bg-white dark:bg-gray-700 border-gray-200 dark:border-gray-600 hover:border-blue-500 dark:hover:border-blue-400 transition-colors"
                >
                  <Box
                    display="flex"
                    alignItems="center"
                    justifyContent="space-between"
                  >
                    <Box>
                      <Typography
                        variant="subtitle1"
                        className="font-bold text-gray-900 dark:text-white"
                      >
                        {wallet.icon} {wallet.name}
                      </Typography>
                      <Typography
                        variant="h6"
                        sx={{ fontFamily: "monospace" }}
                        className="text-gray-700 dark:text-gray-300"
                      >
                        {wallet.number}
                      </Typography>
                    </Box>
                    <IconButton
                      onClick={() =>
                        copyToClipboard(wallet.number, wallet.name)
                      }
                      size="small"
                      className="text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                    >
                      <CopyIcon />
                    </IconButton>
                  </Box>
                </Paper>
              </Grid>
            ))}
          </Grid>
        </CardContent>
      </Card>

      {/* رفع الإيصال */}
      <Card className="bg-white dark:bg-gray-800 shadow-lg dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700">
        <CardContent>
          <Typography
            variant="h6"
            gutterBottom
            className="text-gray-900 dark:text-white font-semibold"
          >
            📸 رفع إيصال التحويل
          </Typography>

          <Box sx={{ mb: 3 }}>
            <Typography
              variant="body2"
              sx={{ mb: 2 }}
              className="text-gray-600 dark:text-gray-400"
            >
              📝 التعليمات:
            </Typography>
            <Box component="ol" sx={{ pl: 2 }}>
              <Typography
                component="li"
                variant="body2"
                sx={{ mb: 1 }}
                className="text-gray-700 dark:text-gray-300"
              >
                انسخ رقم المحفظة المناسب
              </Typography>
              <Typography
                component="li"
                variant="body2"
                sx={{ mb: 1 }}
                className="text-gray-700 dark:text-gray-300"
              >
                حول المبلغ {formatCurrency(invoice?.totalAmount)} من تليفونك
              </Typography>
              <Typography
                component="li"
                variant="body2"
                sx={{ mb: 1 }}
                className="text-gray-700 dark:text-gray-300"
              >
                التقط صورة واضحة لإيصال التحويل
              </Typography>
              <Typography
                component="li"
                variant="body2"
                className="text-gray-700 dark:text-gray-300"
              >
                ارفع الصورة هنا واضغط إرسال
              </Typography>
            </Box>
          </Box>

          <Divider
            sx={{ my: 2 }}
            className="border-gray-200 dark:border-gray-600"
          />

          <input
            accept="image/*"
            style={{ display: "none" }}
            id="receipt-upload"
            type="file"
            onChange={handleFileSelect}
          />
          <label htmlFor="receipt-upload">
            <Button
              variant="outlined"
              component="span"
              startIcon={<UploadIcon />}
              fullWidth
              sx={{ mb: 2 }}
              className="border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
            >
              اختر صورة الإيصال
            </Button>
          </label>

          {selectedFile && (
            <Alert
              severity="info"
              sx={{ mb: 2 }}
              className="bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-800 dark:text-blue-200"
            >
              تم اختيار الملف: {selectedFile.name}
            </Alert>
          )}

          <Grid container spacing={2}>
            {walletNumbers.map((wallet) => (
              <Grid item xs={12} sm={6} key={wallet.id}>
                <Button
                  variant="contained"
                  fullWidth
                  onClick={() => submitReceipt(wallet.id)}
                  disabled={!selectedFile || uploading}
                  sx={{
                    backgroundColor: wallet.color,
                    "&:hover": {
                      backgroundColor: wallet.color,
                      opacity: 0.8,
                    },
                  }}
                >
                  {uploading ? (
                    <CircularProgress size={20} color="inherit" />
                  ) : (
                    `إرسال إيصال ${wallet.name}`
                  )}
                </Button>
              </Grid>
            ))}
          </Grid>
        </CardContent>
      </Card>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert
          onClose={() => setSnackbar({ ...snackbar, open: false })}
          severity={snackbar.severity}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default PaymentPage;

import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import toast from "react-hot-toast";
import { buildApiUrl } from "../utils/urlHelper";

type PublicLink = {
  id: string;
  name: string;
  url: string;
  username?: string;
  openMode?: "new_tab" | "in_app";
  hasPassword?: boolean;
};

type PublicResponse = {
  success: boolean;
  data?: {
    company: { id: string; name: string };
    links: PublicLink[];
  };
  message?: string;
};

const ActionIcon = ({ type }: { type: "copy" | "open" }): React.ReactElement => {
  if (type === "copy") {
    return (
      <svg aria-hidden="true" viewBox="0 0 24 24" className="h-4 w-4">
        <path
          fill="currentColor"
          d="M9 9a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2h-7a2 2 0 0 1-2-2V9Zm-5 4V6a2 2 0 0 1 2-2h7v2H6v7H4Z"
        />
      </svg>
    );
  }

  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" className="h-4 w-4">
      <path
        fill="currentColor"
        d="M14 3h7v7h-2V6.41l-9.29 9.3-1.42-1.42 9.3-9.29H14V3Zm5 16v-6h2v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5c0-1.1.9-2 2-2h6v2H5v14h14Z"
      />
    </svg>
  );
};

const PublicCompanyLinks = () => {
  const { token } = useParams();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [companyName, setCompanyName] = useState<string>("");
  const [links, setLinks] = useState<PublicLink[]>([]);

  const copyText = async (text: string, successMessage: string) => {
    try {
      await navigator.clipboard.writeText(text || "");
      toast.success(successMessage);
    } catch (e) {
      toast.error("فشل النسخ");
    }
  };

  useEffect(() => {
    const run = async () => {
      try {
        setLoading(true);
        setError(null);

        const t = String(token || "").trim();
        if (!t) {
          setError("لينك غير صالح");
          return;
        }

        const res = await fetch(
          buildApiUrl(`public/company-links/${encodeURIComponent(t)}`),
        );
        const data = (await res.json()) as PublicResponse;

        if (!res.ok || !data?.success) {
          setError(data?.message || "لينك غير صالح");
          return;
        }

        setCompanyName(data.data?.company?.name || "");
        setLinks(data.data?.links || []);
      } catch (e: any) {
        setError(e?.message || "فشل في جلب الروابط");
      } finally {
        setLoading(false);
      }
    };

    run();
  }, [token]);

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <div className="flex flex-col items-center gap-4 text-slate-500">
          <div className="h-10 w-10 animate-spin rounded-full border-2 border-slate-200 border-t-slate-700" />
          <p className="text-sm font-medium">جاري تحميل الروابط...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-4xl px-4 py-8">
      <h1 className="text-2xl font-semibold text-slate-900">روابط الشركة</h1>

      {companyName ? (
        <p className="mt-2 text-sm text-slate-500">{companyName}</p>
      ) : null}

      {error ? (
        <div className="mt-6 rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {error}
        </div>
      ) : links.length === 0 ? (
        <div className="mt-6 rounded-2xl border border-sky-200 bg-sky-50 px-4 py-3 text-sm text-sky-700">
          لا توجد روابط
        </div>
      ) : (
        <div className="mt-6 overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-200 bg-slate-50 px-5 py-4 text-sm leading-6 text-slate-600">
            هذه صفحة عامة لفتح الروابط ونسخ اليوزر. كلمة المرور لا تظهر هنا حفاظًا على الأمان.
          </div>
          <div className="divide-y divide-slate-200">
            {links.map((link) => (
              <div
                key={link.id}
                className="flex flex-col gap-4 px-5 py-4 md:flex-row md:items-center md:justify-between"
              >
                <div className="min-w-0">
                  <div className="text-base font-medium text-slate-900">{link.name}</div>
                  <div className="mt-1 truncate text-sm text-slate-500">{link.url}</div>
                  {link.username ? (
                    <div className="mt-2 text-xs text-slate-400">Username: {link.username}</div>
                  ) : null}
                </div>
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    className="inline-flex items-center gap-2 rounded-xl border border-slate-200 px-3 py-2 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:bg-slate-50"
                    onClick={() => {
                      if (!link.url) return;
                      window.open(link.url, "_blank", "noopener,noreferrer");
                    }}
                  >
                    <ActionIcon type="open" />
                    فتح
                  </button>

                  {link.username ? (
                    <button
                      type="button"
                      className="inline-flex items-center gap-2 rounded-xl border border-slate-200 px-3 py-2 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:bg-slate-50"
                      onClick={() => copyText(link.username || "", "تم نسخ Username")}
                    >
                      <ActionIcon type="copy" />
                      نسخ Username
                    </button>
                  ) : null}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default PublicCompanyLinks;

import React, { useState, useEffect } from "react";
import { useDateFormat } from "../hooks/useDateFormat";
import api from "../services/api";
import {
  BellIcon,
  ClockIcon,
  CheckCircleIcon,
  XMarkIcon,
  PlusIcon,
  CalendarIcon,
  UserIcon,
  ExclamationTriangleIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";

interface Reminder {
  id: string;
  title: string;
  description: string;
  type: string;
  priority: "low" | "medium" | "high";
  status: "pending" | "triggered" | "completed" | "dismissed";
  companyId: string;
  userId: string;
  customerId?: string;
  scheduledTime: string;
  createdAt: string;
  snoozeCount: number;
  maxSnooze: number;
  canSnooze: boolean;
  metadata: any;
}

const Reminders: React.FC = () => {
  const { formatDate } = useDateFormat();
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<"active" | "completed" | "stats">(
    "active",
  );

  // Create reminder form
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [createForm, setCreateForm] = useState({
    title: "",
    description: "",
    type: "FOLLOW_UP",
    priority: "medium",
    customerId: "",
    scheduledTime: "",
  });

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);

      // Load reminders
      const remindersResponse = await api.get("/reminders?companyId=1");
      if (remindersResponse.data.success) {
        setReminders(remindersResponse.data.data.reminders);
      }

      // Load stats
      const statsResponse = await api.get("/reminders/stats?companyId=1");
      if (statsResponse.data.success) {
        setStats(statsResponse.data.data);
      }
    } catch (error) {
      console.error("Error loading data:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateReminder = async () => {
    if (!createForm.title.trim() || !createForm.scheduledTime) return;

    try {
      const response = await api.post("/reminders", {
        ...createForm,
        companyId: "1",
        userId: "1",
        relatedEntity: createForm.customerId
          ? {
              type: "customer",
              id: createForm.customerId,
            }
          : null,
      });

      if (response.data.success) {
        await loadData();
        setShowCreateForm(false);
        setCreateForm({
          title: "",
          description: "",
          type: "FOLLOW_UP",
          priority: "medium",
          customerId: "",
          scheduledTime: "",
        });
      }
    } catch (error) {
      console.error("Error creating reminder:", error);
    }
  };

  const handleUpdateStatus = async (
    reminderId: string,
    status: string,
    notes = "",
  ) => {
    try {
      await api.put(`/reminders/${reminderId}/status`, { status, notes });
      await loadData();
    } catch (error) {
      console.error("Error updating reminder status:", error);
    }
  };

  const handleSnoozeReminder = async (reminderId: string, minutes: number) => {
    try {
      await api.post(`/reminders/${reminderId}/snooze`, {
        snoozeMinutes: minutes,
      });
      await loadData();
    } catch (error) {
      console.error("Error snoozing reminder:", error);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "high":
        return "text-red-600 bg-red-100";
      case "medium":
        return "text-yellow-600 bg-yellow-100";
      case "low":
        return "text-green-600 bg-green-100";
      default:
        return "text-gray-600 bg-gray-100";
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "completed":
        return <CheckCircleIcon className="h-5 w-5 text-green-500" />;
      case "triggered":
        return <BellIcon className="h-5 w-5 text-blue-500" />;
      case "dismissed":
        return <XMarkIcon className="h-5 w-5 text-gray-500" />;
      default:
        return <ClockIcon className="h-5 w-5 text-yellow-500" />;
    }
  };

  const isOverdue = (scheduledTime: string) => {
    return new Date(scheduledTime) < new Date();
  };

  const formatTime = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = date.getTime() - now.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMs < 0) {
      const overdueMins = Math.abs(diffMins);
      if (overdueMins < 60) return `متأخر ${overdueMins} دقيقة`;
      if (overdueMins < 1440)
        return `متأخر ${Math.floor(overdueMins / 60)} ساعة`;
      return `متأخر ${Math.floor(overdueMins / 1440)} يوم`;
    }

    if (diffMins < 60) return `خلال ${diffMins} دقيقة`;
    if (diffHours < 24) return `خلال ${diffHours} ساعة`;
    return `خلال ${diffDays} يوم`;
  };

  const activeReminders = reminders.filter(
    (r) => r.status === "pending" || r.status === "triggered",
  );
  const completedReminders = reminders.filter(
    (r) => r.status === "completed" || r.status === "dismissed",
  );

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center">
            <BellIcon className="h-8 w-8 text-blue-600 dark:text-blue-400 ml-3" />
            التذكيرات
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            إدارة التذكيرات والمتابعة مع العملاء
          </p>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={() => setShowCreateForm(true)}
            className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center"
          >
            <PlusIcon className="h-4 w-4 ml-2" />
            تذكير جديد
          </button>
          <button
            onClick={loadData}
            disabled={loading}
            className="bg-gray-600 text-white px-4 py-2 rounded-lg hover:bg-gray-700 disabled:opacity-50 flex items-center"
          >
            <ArrowPathIcon
              className={`h-4 w-4 ml-2 ${loading ? "animate-spin" : ""}`}
            />
            تحديث
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <ClockIcon className="h-8 w-8 text-blue-600" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 dark:text-gray-400 truncate">
                    التذكيرات النشطة
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {stats.active.total}
                  </dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <ExclamationTriangleIcon className="h-8 w-8 text-red-600" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 dark:text-gray-400 truncate">
                    متأخرة
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {stats.active.overdue}
                  </dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <CheckCircleIcon className="h-8 w-8 text-green-600" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 dark:text-gray-400 truncate">
                    مكتملة هذا الأسبوع
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {stats.completed.thisWeek}
                  </dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <BellIcon className="h-8 w-8 text-purple-600" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 dark:text-gray-400 truncate">
                    معدل الإنجاز
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {Math.round(stats.performance.completionRate * 100)}%
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <nav className="-mb-px flex space-x-8">
          <button
            onClick={() => setActiveTab("active")}
            className={`py-2 px-1 border-b-2 font-medium text-sm ${
              activeTab === "active"
                ? "border-blue-500 text-blue-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            <ClockIcon className="h-5 w-5 inline ml-2" />
            التذكيرات النشطة ({activeReminders.length})
          </button>
          <button
            onClick={() => setActiveTab("completed")}
            className={`py-2 px-1 border-b-2 font-medium text-sm ${
              activeTab === "completed"
                ? "border-blue-500 text-blue-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            <CheckCircleIcon className="h-5 w-5 inline ml-2" />
            المكتملة ({completedReminders.length})
          </button>
          <button
            onClick={() => setActiveTab("stats")}
            className={`py-2 px-1 border-b-2 font-medium text-sm ${
              activeTab === "stats"
                ? "border-blue-500 text-blue-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            <CalendarIcon className="h-5 w-5 inline ml-2" />
            الإحصائيات
          </button>
        </nav>
      </div>

      {/* Create Reminder Modal */}
      {showCreateForm && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 dark:bg-gray-900 dark:bg-opacity-75 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border border-gray-200 dark:border-gray-700 w-96 shadow-lg rounded-md bg-white dark:bg-gray-800">
            <div className="mt-3">
              <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">
                إنشاء تذكير جديد
              </h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    العنوان
                  </label>
                  <input
                    type="text"
                    value={createForm.title}
                    onChange={(e) =>
                      setCreateForm({ ...createForm, title: e.target.value })
                    }
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="عنوان التذكير"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    الوصف
                  </label>
                  <textarea
                    value={createForm.description}
                    onChange={(e) =>
                      setCreateForm({
                        ...createForm,
                        description: e.target.value,
                      })
                    }
                    rows={3}
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="وصف التذكير"
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      النوع
                    </label>
                    <select
                      value={createForm.type}
                      onChange={(e) =>
                        setCreateForm({ ...createForm, type: e.target.value })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                      <option value="FOLLOW_UP">متابعة عميل</option>
                      <option value="QUOTE_FOLLOW_UP">متابعة عرض سعر</option>
                      <option value="PAYMENT_REMINDER">تذكير دفع</option>
                      <option value="TASK_REMINDER">تذكير مهمة</option>
                      <option value="APPOINTMENT_REMINDER">تذكير موعد</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      الأولوية
                    </label>
                    <select
                      value={createForm.priority}
                      onChange={(e) =>
                        setCreateForm({
                          ...createForm,
                          priority: e.target.value,
                        })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                      <option value="low">منخفضة</option>
                      <option value="medium">متوسطة</option>
                      <option value="high">عالية</option>
                    </select>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    وقت التذكير
                  </label>
                  <input
                    type="datetime-local"
                    value={createForm.scheduledTime}
                    onChange={(e) =>
                      setCreateForm({
                        ...createForm,
                        scheduledTime: e.target.value,
                      })
                    }
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>
              <div className="flex justify-end space-x-2 mt-6">
                <button
                  onClick={() => setShowCreateForm(false)}
                  className="px-4 py-2 bg-gray-300 dark:bg-gray-600 text-gray-700 dark:text-gray-200 rounded-md hover:bg-gray-400 dark:hover:bg-gray-500"
                >
                  إلغاء
                </button>
                <button
                  onClick={handleCreateReminder}
                  disabled={
                    !createForm.title.trim() || !createForm.scheduledTime
                  }
                  className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50"
                >
                  إنشاء
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Content */}
      {activeTab === "active" && (
        <div className="space-y-4">
          {activeReminders.length === 0 ? (
            <div className="text-center py-12">
              <BellIcon className="mx-auto h-12 w-12 text-gray-400" />
              <h3 className="mt-2 text-sm font-medium text-gray-900">
                لا توجد تذكيرات نشطة
              </h3>
              <p className="mt-1 text-sm text-gray-500">
                جميع التذكيرات مكتملة أو لا توجد تذكيرات
              </p>
            </div>
          ) : (
            activeReminders.map((reminder) => (
              <div
                key={reminder.id}
                className={`bg-white dark:bg-gray-800 rounded-lg shadow border dark:border-gray-700 hover:shadow-md transition-shadow ${
                  isOverdue(reminder.scheduledTime)
                    ? "border-red-200 bg-red-50 dark:border-red-900 dark:bg-red-900/20"
                    : ""
                }`}
              >
                <div className="p-6">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center space-x-3 mb-2">
                        {getStatusIcon(reminder.status)}
                        <h4 className="text-lg font-medium text-gray-900 dark:text-white">
                          {reminder.title}
                        </h4>
                        <span
                          className={`px-2 py-1 rounded-full text-xs font-medium ${getPriorityColor(reminder.priority)}`}
                        >
                          {reminder.priority === "high"
                            ? "عالية"
                            : reminder.priority === "medium"
                              ? "متوسطة"
                              : "منخفضة"}
                        </span>
                        {isOverdue(reminder.scheduledTime) && (
                          <span className="px-2 py-1 rounded-full text-xs font-medium bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-400">
                            متأخر
                          </span>
                        )}
                      </div>

                      <p className="text-gray-600 dark:text-gray-400 mb-3">
                        {reminder.description}
                      </p>

                      <div className="flex items-center text-sm text-gray-500 dark:text-gray-400 space-x-4">
                        <span className="flex items-center">
                          <ClockIcon className="h-4 w-4 ml-1" />
                          {formatTime(reminder.scheduledTime)}
                        </span>
                        {reminder.customerId && (
                          <span className="flex items-center">
                            <UserIcon className="h-4 w-4 ml-1" />
                            عميل #{reminder.customerId}
                          </span>
                        )}
                        {reminder.snoozeCount > 0 && (
                          <span className="text-yellow-600">
                            تم التأجيل {reminder.snoozeCount} مرة
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="mr-4 flex flex-col space-y-2">
                      <button
                        onClick={() =>
                          handleUpdateStatus(reminder.id, "completed")
                        }
                        className="text-green-600 hover:text-green-800 p-1 text-sm"
                        title="تم الإنجاز"
                      >
                        <CheckCircleIcon className="h-5 w-5" />
                      </button>

                      {reminder.canSnooze &&
                        reminder.snoozeCount < reminder.maxSnooze && (
                          <div className="relative group">
                            <button className="text-yellow-600 hover:text-yellow-800 p-1 text-sm">
                              <ClockIcon className="h-5 w-5" />
                            </button>
                            <div className="absolute left-0 mt-1 w-32 bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-md shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-10">
                              <button
                                onClick={() =>
                                  handleSnoozeReminder(reminder.id, 15)
                                }
                                className="block w-full text-right px-3 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-600"
                              >
                                15 دقيقة
                              </button>
                              <button
                                onClick={() =>
                                  handleSnoozeReminder(reminder.id, 60)
                                }
                                className="block w-full text-right px-3 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-600"
                              >
                                ساعة واحدة
                              </button>
                              <button
                                onClick={() =>
                                  handleSnoozeReminder(reminder.id, 240)
                                }
                                className="block w-full text-right px-3 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-600"
                              >
                                4 ساعات
                              </button>
                            </div>
                          </div>
                        )}

                      <button
                        onClick={() =>
                          handleUpdateStatus(reminder.id, "dismissed")
                        }
                        className="text-gray-600 hover:text-gray-800 p-1 text-sm"
                        title="تجاهل"
                      >
                        <XMarkIcon className="h-5 w-5" />
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === "completed" && (
        <div className="space-y-4">
          {completedReminders.length === 0 ? (
            <div className="text-center py-12">
              <CheckCircleIcon className="mx-auto h-12 w-12 text-gray-400" />
              <h3 className="mt-2 text-sm font-medium text-gray-900">
                لا توجد تذكيرات مكتملة
              </h3>
            </div>
          ) : (
            completedReminders.map((reminder) => (
              <div
                key={reminder.id}
                className="bg-white dark:bg-gray-800 rounded-lg shadow border dark:border-gray-700"
              >
                <div className="p-6">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center space-x-3 mb-2">
                        {getStatusIcon(reminder.status)}
                        <h4 className="text-lg font-medium text-gray-900">
                          {reminder.title}
                        </h4>
                        <span
                          className={`px-2 py-1 rounded-full text-xs font-medium ${
                            reminder.status === "completed"
                              ? "bg-green-100 text-green-800"
                              : "bg-gray-100 text-gray-800"
                          }`}
                        >
                          {reminder.status === "completed"
                            ? "مكتمل"
                            : "تم التجاهل"}
                        </span>
                      </div>

                      <p className="text-gray-600 mb-3">
                        {reminder.description}
                      </p>

                      <div className="flex items-center text-sm text-gray-500 space-x-4">
                        <span>
                          تم الإنشاء: {formatDate(reminder.createdAt)}
                        </span>
                        <span>
                          كان مجدولاً: {formatDate(reminder.scheduledTime)}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === "stats" && stats && (
        <div className="space-y-6">
          {/* Performance Metrics */}
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">
              مقاييس الأداء
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-600">
                  {Math.round(stats.performance.completionRate * 100)}%
                </div>
                <div className="text-sm text-gray-600">معدل الإنجاز</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-green-600">
                  {stats.performance.averageSnoozeCount.toFixed(1)}
                </div>
                <div className="text-sm text-gray-600">متوسط التأجيل</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-purple-600">
                  {Math.round(stats.performance.onTimeCompletion * 100)}%
                </div>
                <div className="text-sm text-gray-600">الإنجاز في الوقت</div>
              </div>
            </div>
          </div>

          {/* Trends */}
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">
              الاتجاهات
            </h3>
            <div className="space-y-3">
              {stats.trends.map((trend: any, index: number) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-700 rounded-lg"
                >
                  <span className="text-sm font-medium text-gray-900 dark:text-white">
                    {trend.period}
                  </span>
                  <div className="flex items-center space-x-4 text-sm text-gray-600 dark:text-gray-400">
                    <span>تم الإنشاء: {trend.created}</span>
                    <span>مكتمل: {trend.completed}</span>
                    <span>متأخر: {trend.overdue}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Reminders;

import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Alert,
  CircularProgress,
  Grid,
  Paper,
  IconButton,
  TextField,
  Stepper,
  Step,
  StepLabel,
  Divider,
} from "@mui/material";
import {
  ContentCopy as CopyIcon,
  CloudUpload as UploadIcon,
  CheckCircle as CheckIcon,
  ArrowBack as BackIcon,
} from "@mui/icons-material";
import { useAuth } from "../hooks/useAuthSimple";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../services/apiClient";

const SubscriptionRenewalPayment = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [walletNumbers, setWalletNumbers] = useState([]);
  const [selectedWallet, setSelectedWallet] = useState(null);
  const [receiptFile, setReceiptFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [uploadLoading, setUploadLoading] = useState(false);
  const [activeStep, setActiveStep] = useState(0);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success",
  });
  const [subscription, setSubscription] = useState(null);

  const steps = ["اختيار المحفظة", "رفع الإيصال", "تأكيد الإرسال"];

  useEffect(() => {
    fetchWalletNumbers();
    fetchSubscription();
  }, []);

  const fetchWalletNumbers = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/wallet-payment/wallet-numbers");
      if (response.data.success) {
        setWalletNumbers(response.data.data);
      }
    } catch (error) {
      console.error("خطأ في جلب أرقام المحافظ:", error);
      showSnackbar("خطأ في جلب أرقام المحافظ", "error");
    } finally {
      setLoading(false);
    }
  };

  const fetchSubscription = async () => {
    try {
      // بيانات وهمية للاشتراك
      const mockSubscription = {
        id: "mock-subscription",
        price: 7500,
        currency: "EGP",
      };
      setSubscription(mockSubscription);
    } catch (error) {
      console.error("خطأ في جلب الاشتراك:", error);
    }
  };

  const copyToClipboard = (text, walletName) => {
    navigator.clipboard.writeText(text).then(() => {
      showSnackbar(`تم نسخ رقم ${walletName}`, "success");
    });
  };

  const showSnackbar = (message, severity = "success") => {
    setSnackbar({ open: true, message, severity });
    setTimeout(() => setSnackbar({ ...snackbar, open: false }), 3000);
  };

  const handleWalletSelect = (wallet) => {
    setSelectedWallet(wallet);
    setActiveStep(1);
  };

  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        showSnackbar("حجم الملف كبير جداً. الحد الأقصى 5 ميجابايت", "error");
        return;
      }
      if (!file.type.startsWith("image/")) {
        showSnackbar("يرجى اختيار ملف صورة فقط", "error");
        return;
      }
      setReceiptFile(file);
      setActiveStep(2);
    }
  };

  const handleSubmitReceipt = async () => {
    if (!receiptFile || !selectedWallet) {
      showSnackbar("يرجى اختيار المحفظة ورفع الإيصال", "error");
      return;
    }

    try {
      setUploadLoading(true);

      const formData = new FormData();
      formData.append("receipt", receiptFile);
      formData.append("walletNumberId", selectedWallet.id);
      formData.append("subscriptionId", subscription?.id || "renewal");
      formData.append("amount", subscription?.price || 7500);
      formData.append("purpose", "subscription_renewal");

      const response = await apiClient.post(
        "/wallet-payment/submit-receipt",
        formData,
      );

      if (response.data.success) {
        showSnackbar("تم إرسال الإيصال بنجاح! سيتم مراجعته قريباً", "success");
        setTimeout(() => {
          navigate("/subscription");
        }, 2000);
      } else {
        showSnackbar(response.data.message || "خطأ في إرسال الإيصال", "error");
      }
    } catch (error) {
      console.error("خطأ في رفع الإيصال:", error);
      showSnackbar("خطأ في إرسال الإيصال", "error");
    } finally {
      setUploadLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="400px"
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box p={3} maxWidth={900} mx="auto">
      {/* Header */}
      <Box display="flex" alignItems="center" mb={3}>
        <IconButton onClick={() => navigate("/subscription")} sx={{ mr: 2 }}>
          <BackIcon />
        </IconButton>
        <Typography variant="h4">💳 دفع تجديد الاشتراك</Typography>
      </Box>

      {/* Stepper */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Stepper activeStep={activeStep} alternativeLabel>
            {steps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
        </CardContent>
      </Card>

      {/* معلومات المبلغ */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            💰 تفاصيل الدفع
          </Typography>
          <Typography variant="h5" color="primary" fontWeight="bold">
            المبلغ المطلوب: {formatCurrency(subscription?.price || 7500)}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            رسوم تجديد الاشتراك الشهري
          </Typography>
        </CardContent>
      </Card>

      {/* Step 1: اختيار المحفظة */}
      {activeStep >= 0 && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              1️⃣ اختر رقم المحفظة للتحويل
            </Typography>

            <Grid container spacing={2}>
              {walletNumbers.map((wallet) => (
                <Grid item xs={12} sm={6} key={wallet.id}>
                  <Paper
                    sx={{
                      p: 2,
                      border: selectedWallet?.id === wallet.id ? 2 : 1,
                      borderColor:
                        selectedWallet?.id === wallet.id
                          ? "primary.main"
                          : "divider",
                      cursor: "pointer",
                      "&:hover": { borderColor: "primary.main" },
                    }}
                    onClick={() => handleWalletSelect(wallet)}
                  >
                    <Box
                      display="flex"
                      alignItems="center"
                      justifyContent="space-between"
                    >
                      <Box>
                        <Typography variant="subtitle1" fontWeight="bold">
                          {wallet.icon} {wallet.name}
                        </Typography>
                        <Typography
                          variant="h6"
                          sx={{ fontFamily: "monospace" }}
                        >
                          {wallet.number}
                        </Typography>
                      </Box>
                      <Box>
                        <IconButton
                          onClick={(e) => {
                            e.stopPropagation();
                            copyToClipboard(wallet.number, wallet.name);
                          }}
                          color="primary"
                          size="small"
                        >
                          <CopyIcon />
                        </IconButton>
                        {selectedWallet?.id === wallet.id && (
                          <CheckIcon color="success" sx={{ ml: 1 }} />
                        )}
                      </Box>
                    </Box>
                  </Paper>
                </Grid>
              ))}
            </Grid>
          </CardContent>
        </Card>
      )}

      {/* Step 2: رفع الإيصال */}
      {activeStep >= 1 && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              2️⃣ ارفع صورة إيصال التحويل
            </Typography>

            {selectedWallet && (
              <Alert severity="info" sx={{ mb: 2 }}>
                تم اختيار: {selectedWallet.icon} {selectedWallet.name} -{" "}
                {selectedWallet.number}
              </Alert>
            )}

            <Box
              sx={{
                border: "2px dashed",
                borderColor: receiptFile ? "success.main" : "grey.300",
                borderRadius: 2,
                p: 3,
                textAlign: "center",
                backgroundColor: receiptFile ? "success.50" : "grey.50",
              }}
            >
              <input
                accept="image/*"
                style={{ display: "none" }}
                id="receipt-upload"
                type="file"
                onChange={handleFileChange}
              />
              <label htmlFor="receipt-upload">
                <Button
                  variant="outlined"
                  component="span"
                  startIcon={receiptFile ? <CheckIcon /> : <UploadIcon />}
                  size="large"
                  color={receiptFile ? "success" : "primary"}
                >
                  {receiptFile ? "تم رفع الإيصال" : "اختر صورة الإيصال"}
                </Button>
              </label>

              {receiptFile && (
                <Typography variant="body2" sx={{ mt: 1 }}>
                  {receiptFile.name}
                </Typography>
              )}

              <Typography variant="caption" display="block" sx={{ mt: 1 }}>
                الحد الأقصى: 5 ميجابايت | الصيغ المدعومة: JPG, PNG, GIF
              </Typography>
            </Box>
          </CardContent>
        </Card>
      )}

      {/* Step 3: تأكيد الإرسال */}
      {activeStep >= 2 && (
        <Card>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              3️⃣ تأكيد وإرسال
            </Typography>

            <Box sx={{ mb: 3 }}>
              <Typography variant="body1" gutterBottom>
                <strong>المحفظة المختارة:</strong> {selectedWallet?.name} -{" "}
                {selectedWallet?.number}
              </Typography>
              <Typography variant="body1" gutterBottom>
                <strong>المبلغ:</strong>{" "}
                {formatCurrency(subscription?.price || 7500)}
              </Typography>
              <Typography variant="body1" gutterBottom>
                <strong>الإيصال:</strong> {receiptFile?.name}
              </Typography>
            </Box>

            <Divider sx={{ my: 2 }} />

            <Box textAlign="center">
              <Button
                variant="contained"
                size="large"
                onClick={handleSubmitReceipt}
                disabled={uploadLoading || !receiptFile || !selectedWallet}
                sx={{ px: 4, py: 1.5 }}
              >
                {uploadLoading ? (
                  <>
                    <CircularProgress size={20} sx={{ mr: 1 }} />
                    جاري الإرسال...
                  </>
                ) : (
                  "إرسال الإيصال للمراجعة"
                )}
              </Button>
            </Box>
          </CardContent>
        </Card>
      )}

      {/* Snackbar */}
      {snackbar.open && (
        <Alert
          severity={snackbar.severity}
          sx={{
            position: "fixed",
            bottom: 20,
            right: 20,
            zIndex: 1000,
          }}
          onClose={() => setSnackbar({ ...snackbar, open: false })}
        >
          {snackbar.message}
        </Alert>
      )}
    </Box>
  );
};

export default SubscriptionRenewalPayment;

import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Button,
  Chip,
  Alert,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  MenuItem,
  Stack,
  FormControlLabel,
  Switch,
  Divider,
  Checkbox,
  Toolbar,
  InputAdornment,
} from "@mui/material";
import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  CheckCircle as CheckCircleIcon,
  Cancel as CancelIcon,
  Refresh as RefreshIcon,
  SmartToy as BotIcon,
  VpnKey as KeyIcon,
  Settings as SettingsIcon,
  Bolt as BoltIcon,
  Psychology as BrainIcon,
  Face as FaceIcon,
  Search as SearchIcon,
  FilterList as FilterListIcon,
  PlayArrow as PlayArrowIcon,
  Stop as StopIcon,
} from "@mui/icons-material";
import { useTheme } from "../hooks/useTheme";

import tokenManager from "../utils/tokenManager";
import { buildApiUrl } from "../utils/urlHelper";

const PROVIDERS = [
  {
    value: "GOOGLE",
    label: "Google Gemini",
    icon: <BoltIcon color="warning" />,
  },
  {
    value: "DEEPSEEK",
    label: "DeepSeek (V3/R1)",
    icon: <BrainIcon color="primary" />,
  },
  { value: "OPENAI", label: "OpenAI (GPT)", icon: <BotIcon color="success" /> },
  {
    value: "ANTHROPIC",
    label: "Anthropic (Claude)",
    icon: <BotIcon color="error" />,
  },
  {
    value: "HUGGINGFACE",
    label: "Hugging Face (Hub)",
    icon: <FaceIcon color="warning" />,
  },
  { value: "OLLAMA", label: "Ollama (Local)", icon: <BotIcon color="info" /> },
  { value: "GROQ", label: "Groq (LPU)", icon: <BoltIcon color="secondary" /> },
];

const SuperAdminAIProviders = () => {
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);

  // Ollama Specific
  const [ollamaModels, setOllamaModels] = useState<string[]>([]);
  const [loadingModels, setLoadingModels] = useState(false);

  // Data States
  const [globalConfig, setGlobalConfig] = useState({
    defaultProvider: "GOOGLE",
    enableFailover: true,
  });
  const [keys, setKeys] = useState([]);
  const [filteredKeys, setFilteredKeys] = useState([]);
  const [selectedKeys, setSelectedKeys] = useState<string[]>([]);

  // Filter States
  const [filters, setFilters] = useState({
    search: "",
    provider: "",
    status: "",
  });

  // Dialog States
  const [openDialog, setOpenDialog] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    provider: "GOOGLE",
    apiKey: "",
    baseUrl: "",
    defaultModel: "",
  });

  const applyFilters = (keysToFilter: any[], currentFilters: any) => {
    let filtered = [...keysToFilter];

    // Search filter
    if (currentFilters.search) {
      const searchLower = currentFilters.search.toLowerCase();
      filtered = filtered.filter(
        (key: any) =>
          key.name.toLowerCase().includes(searchLower) ||
          key.provider.toLowerCase().includes(searchLower) ||
          key.apiKey.substring(0, 8).toLowerCase().includes(searchLower),
      );
    }

    // Provider filter
    if (currentFilters.provider) {
      filtered = filtered.filter(
        (key: any) => key.provider === currentFilters.provider,
      );
    }

    // Status filter
    if (currentFilters.status !== "") {
      const isActive = currentFilters.status === "active";
      filtered = filtered.filter((key: any) => key.isActive === isActive);
    }

    setFilteredKeys(filtered);
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    if (keys.length > 0) {
      applyFilters(keys, filters);
    }
  }, [filters, keys]);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const headers = getAuthHeaders();

      const [configRes, keysRes] = await Promise.all([
        fetch(buildApiUrl("super-admin/ai/config"), { headers }),
        fetch(buildApiUrl("super-admin/ai/keys"), { headers }),
      ]);

      const configData = await configRes.json();
      const keysData = await keysRes.json();

      if (configData.success) setGlobalConfig(configData.data);
      if (keysData.success) {
        setKeys(keysData.data);
      }
    } catch (err) {
      console.error("Failed to fetch AI data:", err);
      // Mock data for UI development if backend fails (remove later)
      // setError('Failed to load data.');
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (field: string) => (event: any) => {
    setFilters({ ...filters, [field]: event.target.value });
  };

  const handleSaveConfig = async (newProvider) => {
    try {
      const response = await fetch(buildApiUrl("super-admin/ai/config"), {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          defaultProvider:
            newProvider !== undefined
              ? newProvider
              : globalConfig.defaultProvider,
          enableFailover:
            newProvider === undefined &&
            globalConfig.enableFailover !== undefined
              ? !globalConfig.enableFailover
              : globalConfig.enableFailover,
        }),
      });
      const data = await response.json();
      if (data.success) {
        setGlobalConfig(data.data);
        setSuccess(
          newProvider
            ? `System now using ${newProvider} exclusively.`
            : `Failover setting updated.`,
        );
      } else {
        setError(data.message);
      }
    } catch (err) {
      setError("Failed to update configuration.");
    }
  };

  const handleAddKey = async () => {
    try {
      const response = await fetch(buildApiUrl("super-admin/ai/keys"), {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          ...formData,
          modelName: formData.defaultModel, // Map to backend expected field
        }),
      });
      const data = await response.json();
      if (data.success) {
        setSuccess("Key added successfully");
        setOpenDialog(false);
        fetchData(); // Reload
      } else {
        setError(data.message);
      }
    } catch (err) {
      setError("Failed to add key.");
    }
  };

  const fetchOllamaModels = async () => {
    if (!formData.baseUrl) {
      setError("Please enter Base URL first (e.g. http://localhost:11434)");
      return;
    }
    try {
      setLoadingModels(true);
      setError(null);

      // Call our new backend proxy
      const response = await fetch(
        buildApiUrl(
          `super-admin/ai/ollama/models?baseUrl=${encodeURIComponent(formData.baseUrl)}`,
        ),
        {
          headers: getAuthHeaders(),
        },
      );
      const data = await response.json();

      if (data.success) {
        setOllamaModels(data.models);
        setSuccess(`Found ${data.models.length} models!`);
      } else {
        setError(data.message);
        setOllamaModels([]);
      }
    } catch (err: any) {
      console.error(err);
      setError(`Failed to fetch models: ${err.message || "Unknown error"}`);
    } finally {
      setLoadingModels(false);
    }
  };

  const handleDeleteKey = async (id) => {
    if (!window.confirm("Are you sure you want to delete this key?")) return;
    try {
      const response = await fetch(buildApiUrl(`super-admin/ai/keys/${id}`), {
        method: "DELETE",
        headers: getAuthHeaders(),
      });
      if (response.ok) {
        setSuccess("Key deleted.");
        setSelectedKeys([]);
        fetchData();
      }
    } catch (err) {
      setError("Failed delete.");
    }
  };

  const handleToggleKeyStatus = async (id: string, currentStatus: boolean) => {
    try {
      const response = await fetch(
        buildApiUrl(`super-admin/ai/keys/${id}/active-status`),
        {
          method: "PATCH",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
          body: JSON.stringify({ isActive: !currentStatus }),
        },
      );
      if (response.ok) {
        setSuccess(`Key ${!currentStatus ? "activated" : "deactivated"}.`);
        fetchData();
      }
    } catch (err) {
      setError("Failed to update key status.");
    }
  };

  const handleBulkDelete = async () => {
    if (selectedKeys.length === 0) return;
    if (
      !window.confirm(
        `Are you sure you want to delete ${selectedKeys.length} key(s)?`,
      )
    )
      return;

    try {
      const response = await fetch(
        buildApiUrl("super-admin/ai/keys/bulk-delete"),
        {
          method: "POST",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
          body: JSON.stringify({ ids: selectedKeys }),
        },
      );
      const data = await response.json();
      if (data.success) {
        setSuccess(`${data.count} key(s) deleted successfully.`);
        setSelectedKeys([]);
        fetchData();
      } else {
        setError(data.message || "Failed to delete keys.");
      }
    } catch (err) {
      setError("Failed to delete keys.");
    }
  };

  const handleBulkUpdateStatus = async (isActive: boolean) => {
    if (selectedKeys.length === 0) return;

    try {
      const response = await fetch(
        buildApiUrl("super-admin/ai/keys/bulk-update-status"),
        {
          method: "POST",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
          body: JSON.stringify({ ids: selectedKeys, isActive }),
        },
      );
      const data = await response.json();
      if (data.success) {
        setSuccess(
          `${data.count} key(s) ${isActive ? "activated" : "deactivated"} successfully.`,
        );
        setSelectedKeys([]);
        fetchData();
      } else {
        setError(data.message || "Failed to update keys status.");
      }
    } catch (err) {
      setError("Failed to update keys status.");
    }
  };

  const handleSelectAll = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.checked) {
      setSelectedKeys(filteredKeys.map((key: any) => key.id));
    } else {
      setSelectedKeys([]);
    }
  };

  const handleSelectKey = (id: string) => {
    setSelectedKeys((prev) =>
      prev.includes(id) ? prev.filter((keyId) => keyId !== id) : [...prev, id],
    );
  };

  const handleUpdateActiveModel = async (keyId: string, modelName: string) => {
    try {
      const response = await fetch(
        buildApiUrl(`super-admin/ai/keys/${keyId}/active-model`),
        {
          method: "POST",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
          body: JSON.stringify({ modelName }),
        },
      );

      if (response.ok) {
        setSuccess(`Active model updated to ${modelName}`);
        fetchData(); // Refresh UI to reflect changes
      } else {
        setError("Failed to update active model");
      }
    } catch (err) {
      setError("Error updating model");
      console.error(err);
    }
  };

  const activeProviderInfo = PROVIDERS.find(
    (p) => p.value === globalConfig.defaultProvider,
  );

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ display: "flex", justifyContent: "space-between", mb: 4 }}>
        <Typography variant="h4" fontWeight="bold">
          🤖 AI Provider Management
        </Typography>
        <Button startIcon={<RefreshIcon />} onClick={fetchData}>
          Refresh
        </Button>
      </Box>

      {/* Global Switcher */}
      <Card
        sx={{
          mb: 4,
          borderLeft: "6px solid",
          borderColor: "primary.main",
          bgcolor: isDark ? "rgba(0, 150, 255, 0.05)" : "#f8fdff",
        }}
      >
        <CardContent>
          <Grid container alignItems="center" spacing={2}>
            <Grid size={{ xs: 12, md: 8 }}>
              <Typography variant="h6" gutterBottom>
                System Active Provider
              </Typography>
              <Typography variant="body2" color="text.secondary">
                The selected provider will handle ALL AI requests across the
                entire system. Ensure you have active keys for the selected
                provider.
              </Typography>
            </Grid>
            <Grid size={{ xs: 12, md: 4 }} textAlign="right">
              <Stack spacing={2} alignItems="flex-end">
                <Stack
                  direction="row"
                  spacing={1}
                  justifyContent="flex-end"
                  alignItems="center"
                >
                  {activeProviderInfo?.icon}
                  <TextField
                    select
                    label="Active Provider"
                    value={globalConfig.defaultProvider}
                    onChange={(e) => handleSaveConfig(e.target.value)}
                    sx={{ minWidth: 200 }}
                    size="small"
                  >
                    {PROVIDERS.map((p) => (
                      <MenuItem key={p.value} value={p.value}>
                        <Box sx={{ display: "flex", gap: 1 }}>
                          {p.icon} {p.label}
                        </Box>
                      </MenuItem>
                    ))}
                  </TextField>
                </Stack>
                <FormControlLabel
                  control={
                    <Switch
                      checked={globalConfig.enableFailover !== false}
                      onChange={() => handleSaveConfig(undefined)}
                      color="primary"
                    />
                  }
                  label={
                    <Box>
                      <Typography variant="body2" fontWeight="bold">
                        Smart Failover (Central)
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        Automatically switch to backup providers on failure
                      </Typography>
                    </Box>
                  }
                  sx={{ ml: 0 }}
                />
              </Stack>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Errors/Success */}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}
      {success && (
        <Alert
          severity="success"
          sx={{ mb: 2 }}
          onClose={() => setSuccess(null)}
        >
          {success}
        </Alert>
      )}

      {/* Keys List */}
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          mb: 2,
          alignItems: "center",
        }}
      >
        <Typography variant="h5">API Keys</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setOpenDialog(true)}
        >
          Add New Key
        </Button>
      </Box>

      {/* Filters */}
      <Card sx={{ mb: 2 }}>
        <CardContent>
          <Grid container spacing={2} alignItems="center">
            <Grid size={{ xs: 12, md: 4 }}>
              <TextField
                fullWidth
                size="small"
                placeholder="Search by name, provider, or key..."
                value={filters.search}
                onChange={handleFilterChange("search")}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon />
                    </InputAdornment>
                  ),
                }}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 3 }}>
              <TextField
                fullWidth
                select
                size="small"
                label="Provider"
                value={filters.provider}
                onChange={handleFilterChange("provider")}
              >
                <MenuItem value="">All Providers</MenuItem>
                {PROVIDERS.map((p) => (
                  <MenuItem key={p.value} value={p.value}>
                    {p.label}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid size={{ xs: 12, md: 3 }}>
              <TextField
                fullWidth
                select
                size="small"
                label="Status"
                value={filters.status}
                onChange={handleFilterChange("status")}
              >
                <MenuItem value="">All Status</MenuItem>
                <MenuItem value="active">Active</MenuItem>
                <MenuItem value="inactive">Inactive</MenuItem>
              </TextField>
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <Button
                fullWidth
                variant="outlined"
                startIcon={<FilterListIcon />}
                onClick={() => {
                  setFilters({ search: "", provider: "", status: "" });
                }}
              >
                Clear
              </Button>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Bulk Actions Toolbar */}
      {selectedKeys.length > 0 && (
        <Paper
          sx={{
            mb: 2,
            p: 1,
            bgcolor: isDark
              ? "rgba(25, 118, 210, 0.1)"
              : "rgba(25, 118, 210, 0.05)",
          }}
        >
          <Toolbar sx={{ minHeight: "48px !important", px: "16px !important" }}>
            <Typography sx={{ flex: "1 1 100%" }}>
              {selectedKeys.length} key(s) selected
            </Typography>
            <Stack direction="row" spacing={1}>
              <Button
                size="small"
                variant="outlined"
                color="success"
                startIcon={<PlayArrowIcon />}
                onClick={() => handleBulkUpdateStatus(true)}
              >
                Activate
              </Button>
              <Button
                size="small"
                variant="outlined"
                color="warning"
                startIcon={<StopIcon />}
                onClick={() => handleBulkUpdateStatus(false)}
              >
                Deactivate
              </Button>
              <Button
                size="small"
                variant="outlined"
                color="error"
                startIcon={<DeleteIcon />}
                onClick={handleBulkDelete}
              >
                Delete
              </Button>
            </Stack>
          </Toolbar>
        </Paper>
      )}

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell padding="checkbox">
                <Checkbox
                  indeterminate={
                    selectedKeys.length > 0 &&
                    selectedKeys.length < filteredKeys.length
                  }
                  checked={
                    filteredKeys.length > 0 &&
                    selectedKeys.length === filteredKeys.length
                  }
                  onChange={handleSelectAll}
                />
              </TableCell>
              <TableCell>Name</TableCell>
              <TableCell>Provider</TableCell>
              <TableCell>Active Model</TableCell>
              <TableCell>Key (Masked)</TableCell>
              <TableCell>Base URL</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {filteredKeys.length === 0 ? (
              <TableRow>
                <TableCell colSpan={8} align="center">
                  No keys found.
                </TableCell>
              </TableRow>
            ) : (
              filteredKeys.map((key: any) => {
                // Logic to find active model (Priority 1)
                // Default to empty string if not found, to match standard Select behavior
                let activeModel =
                  key.aiModelConfigs?.find(
                    (m: any) => m.priority === 1 && m.isEnabled,
                  )?.modelName || "";

                // If provider has models list (like we synced for Groq), use it.
                const availableModels =
                  key.aiModelConfigs?.map((m: any) => m.modelName) || [];

                // Verify activeModel is actually in the list. if not (e.g. "Default" was saved but not in synced list), reset to empty to avoid warning
                if (
                  availableModels.length > 0 &&
                  activeModel &&
                  !availableModels.includes(activeModel)
                ) {
                  activeModel = "";
                }

                return (
                  <TableRow
                    key={key.id}
                    selected={selectedKeys.includes(key.id)}
                  >
                    <TableCell padding="checkbox">
                      <Checkbox
                        checked={selectedKeys.includes(key.id)}
                        onChange={() => handleSelectKey(key.id)}
                      />
                    </TableCell>
                    <TableCell>{key.name}</TableCell>
                    <TableCell>
                      <Chip
                        icon={
                          PROVIDERS.find((p) => p.value === key.provider)?.icon
                        }
                        label={key.provider}
                        size="small"
                        variant="outlined"
                      />
                    </TableCell>
                    <TableCell>
                      {/* Model Selector */}
                      {availableModels.length > 0 ? (
                        <TextField
                          select
                          size="small"
                          variant="standard"
                          value={activeModel}
                          onChange={(e) =>
                            handleUpdateActiveModel(key.id, e.target.value)
                          }
                          sx={{ minWidth: 150 }}
                          InputProps={{ disableUnderline: true }}
                        >
                          <MenuItem value="">
                            <Typography
                              variant="caption"
                              color="text.secondary"
                            >
                              Select Model
                            </Typography>
                          </MenuItem>
                          {availableModels.map((m: string) => (
                            <MenuItem key={m} value={m}>
                              {m}
                            </MenuItem>
                          ))}
                        </TextField>
                      ) : (
                        <Typography variant="body2">{activeModel}</Typography>
                      )}
                    </TableCell>
                    <TableCell>{key.apiKey.substring(0, 8)}...</TableCell>
                    <TableCell>
                      {key.baseUrl || (
                        <Typography color="text.secondary" variant="caption">
                          Default
                        </Typography>
                      )}
                    </TableCell>
                    <TableCell>
                      {key.isActive ? (
                        <Chip label="Active" color="success" size="small" />
                      ) : (
                        <Chip label="Inactive" size="small" />
                      )}
                    </TableCell>
                    <TableCell>
                      <Stack direction="row" spacing={0.5}>
                        <IconButton
                          onClick={() =>
                            handleToggleKeyStatus(key.id, key.isActive)
                          }
                          color={key.isActive ? "warning" : "success"}
                          size="small"
                          title={key.isActive ? "Deactivate" : "Activate"}
                        >
                          {key.isActive ? (
                            <StopIcon fontSize="small" />
                          ) : (
                            <PlayArrowIcon fontSize="small" />
                          )}
                        </IconButton>
                        <IconButton
                          onClick={() => handleDeleteKey(key.id)}
                          color="error"
                          size="small"
                        >
                          <DeleteIcon fontSize="small" />
                        </IconButton>
                      </Stack>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Add Key Dialog */}
      <Dialog
        open={openDialog}
        onClose={() => setOpenDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Add AI Provider Key</DialogTitle>
        <DialogContent>
          <Stack spacing={3} sx={{ mt: 1 }}>
            <TextField
              label="Key Name (e.g. My DeepSeek Key)"
              fullWidth
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
            />
            <TextField
              select
              label="Provider"
              fullWidth
              value={formData.provider}
              onChange={(e) => {
                const newProvider = e.target.value;
                setFormData({
                  ...formData,
                  provider: newProvider,
                  // Pre-fill known working URL for Ollama if empty
                  baseUrl:
                    newProvider === "OLLAMA" && !formData.baseUrl
                      ? "https://ollama.maxp.online"
                      : formData.baseUrl,
                });
              }}
            >
              {PROVIDERS.map((p) => (
                <MenuItem key={p.value} value={p.value}>
                  {p.label}
                </MenuItem>
              ))}
            </TextField>
            <TextField
              label="API Key"
              fullWidth
              value={formData.apiKey}
              onChange={(e) =>
                setFormData({ ...formData, apiKey: e.target.value })
              }
              type="password"
            />
            {(formData.provider === "DEEPSEEK" ||
              formData.provider === "OLLAMA") && (
              <TextField
                label="Base URL (Optional)"
                placeholder="https://api.deepseek.com"
                fullWidth
                value={formData.baseUrl}
                onChange={(e) =>
                  setFormData({ ...formData, baseUrl: e.target.value })
                }
                helperText={
                  formData.provider === "OLLAMA"
                    ? "e.g. http://localhost:11434"
                    : "Keep empty for standard cloud API"
                }
              />
            )}

            {formData.provider === "OLLAMA" && (
              <Box>
                <Stack direction="row" spacing={1} mb={2} alignItems="center">
                  <Button
                    variant="outlined"
                    size="small"
                    onClick={fetchOllamaModels}
                    disabled={loadingModels || !formData.baseUrl}
                  >
                    {loadingModels ? (
                      <CircularProgress size={20} />
                    ) : (
                      "Fetch Models"
                    )}
                  </Button>
                  <Typography variant="caption" color="text.secondary">
                    Click to load available models from your server
                  </Typography>
                </Stack>

                {ollamaModels.length > 0 ? (
                  <TextField
                    select
                    label="Select Model"
                    fullWidth
                    value={formData.defaultModel}
                    onChange={(e) =>
                      setFormData({ ...formData, defaultModel: e.target.value })
                    }
                    helperText="Select the model to use"
                  >
                    {ollamaModels.map((model) => (
                      <MenuItem key={model} value={model}>
                        {model}
                      </MenuItem>
                    ))}
                  </TextField>
                ) : (
                  <TextField
                    label="Default Model (Manual Entry)"
                    placeholder="e.g. llama3"
                    fullWidth
                    value={formData.defaultModel}
                    onChange={(e) =>
                      setFormData({ ...formData, defaultModel: e.target.value })
                    }
                    helperText="Fetch models to select from list, or type manually"
                  />
                )}
              </Box>
            )}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleAddKey}>
            Add Key
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

