                variant="outlined"
                size="small"
                value={filters.search}
                onChange={handleFilterChange("search")}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <TextField
                fullWidth
                label="اسم الشركة / ID"
                variant="outlined"
                size="small"
                value={filters.companyId}
                onChange={handleFilterChange("companyId")}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <TextField
                fullWidth
                label="اسم المفتاح"
                variant="outlined"
                size="small"
                value={filters.keyName}
                onChange={handleFilterChange("keyName")}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <TextField
                fullWidth
                type="date"
                label="من تاريخ"
                InputLabelProps={{ shrink: true }}
                size="small"
                value={filters.startDate}
                onChange={handleFilterChange("startDate")}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <TextField
                fullWidth
                type="date"
                label="إلى تاريخ"
                InputLabelProps={{ shrink: true }}
                size="small"
                value={filters.endDate}
                onChange={handleFilterChange("endDate")}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 1 }}>
              <Button
                fullWidth
                variant="contained"
                startIcon={<SearchIcon />}
                onClick={handleSearch}
                sx={{ height: 40 }}
              >
                بحث
              </Button>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      <TableContainer component={Paper}>
        <Table aria-label="collapsible table">
          <TableHead>
            <TableRow>
              <TableCell />
              <TableCell>التوقيت</TableCell>
              <TableCell>الشركة</TableCell>
              <TableCell>المفتاح</TableCell>
              <TableCell>الموديل</TableCell>
              <TableCell>Tokens</TableCell>
              <TableCell>وقت الرد</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  جاري التحميل...
                </TableCell>
              </TableRow>
            ) : logs.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  لا توجد سجلات
                </TableCell>
              </TableRow>
            ) : (
              logs.map((log) => <Row key={log.id} row={log} />)
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Box sx={{ mt: 2, display: "flex", justifyContent: "center" }}>
        <Pagination
          count={totalPages}
          page={page}
          onChange={(_, value) => setPage(value)}
