import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Grid,
  CircularProgress,
  Alert,
  TextField,
  InputAdornment,
  TablePagination,
  TableSortLabel,
  Stack,
  alpha,
  useTheme as useMuiTheme,
  Tooltip,
  IconButton,
  Button,
  Menu,
  MenuItem,
} from "@mui/material";
import {
  Search as SearchIcon,
  Image as ImageIcon,
  Storage as StorageIcon,
  Business as BusinessIcon,
  Refresh as RefreshIcon,
  InfoOutlined as InfoIcon,
  AutoFixHigh as AutoFixHighIcon,
  DeleteSweep as DeleteSweepIcon,
  Delete as DeleteIcon,
  CleaningServices as CleaningServicesIcon,
  Settings as SettingsIcon,
} from "@mui/icons-material";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  Cell,
} from "recharts";
import { apiClient } from "../services/apiClient";

const formatSize = (bytes: number) => {
  if (bytes === 0) return "0 Bytes";
  const k = 1024;
  const sizes = ["Bytes", "KB", "MB", "GB", "TB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
};

interface CompanyStats {
  companyId: string;
  companyName: string;
  galleryCount: number;
  gallerySize: number;
  productCount: number;
  productSize: number;
  chatImageCount: number;
  chatImageSize: number;
  whatsappImageCount: number;
  whatsappImageSize: number;
  totalCount: number;
  totalSize: number;
}

const SuperAdminImageStats = () => {
  const muiTheme = useMuiTheme();
  const isDark = muiTheme.palette.mode === "dark";

  const [stats, setStats] = useState<CompanyStats[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [compressing, setCompressing] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [orderBy, setOrderBy] = useState<keyof CompanyStats>("totalSize");
  const [order, setOrder] = useState<"asc" | "desc">("desc");
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [selectedCompany, setSelectedCompany] = useState<{
    id: string;
    name: string;
  } | null>(null);
  const [orphanedStats, setOrphanedStats] = useState<{
    count: number;
    size: number;
  } | null>(null);
  const [scanning, setScanning] = useState(false);
  const [cleaning, setCleaning] = useState(false);

  const handleMenuOpen = (
    event: React.MouseEvent<HTMLButtonElement>,
    companyId: string,
    companyName: string,
  ) => {
    setAnchorEl(event.currentTarget);
    setSelectedCompany({ id: companyId, name: companyName });
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedCompany(null);
  };

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await apiClient.get("/super-admin/image-statistics");

      if (response.status === 200 && response.data.success) {
        setStats(response.data.data);
      } else {
        setError(response.data.message || "فشل في جلب الإحصائيات");
      }
    } catch (err: any) {
      console.error("Error fetching image stats:", err);
      setError("حدث خطأ أثناء الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  const handleCompressImages = async () => {
    if (
      !window.confirm(
        "هل أنت متأكد من بدء عملية ضغط الصور؟ سيتم ضغط جميع الصور غير المضغوطة في النظام. قد تستغرق العملية وقتاً طويلاً.",
      )
    )
      return;

    try {
      setCompressing(true);
      const response = await apiClient.post(
        "/super-admin/image-stats/compress",
      );

      if (response.status === 200 && response.data.success) {
        setMessage(response.data.message);
        setTimeout(() => setMessage(null), 5000);
      } else {
        setError(response.data.message || "فشل في بدء العملية");
      }
    } catch (err: any) {
      setError(err.response?.data?.message || "فشل في الاتصال بالخادم");
    } finally {
      setCompressing(false);
    }
  };

  const handleDeleteOldChatImages = async (months: number) => {
    if (
      !window.confirm(
        `هل أنت متأكد من حذف صور الدردشة التي مضى عليها أكثر من ${months} أشهر؟ هذه العملية لا يمكن التراجع عنها.`,
      )
    )
      return;

    try {
      setLoading(true);
      const response = await apiClient.post(
        "/super-admin/image-stats/delete-old-chat-images",
        { months },
      );

      if (response.status === 200 && response.data.success) {
        setMessage(
          `تم حذف ${response.data.details.chatDeleted + response.data.details.whatsappDeleted} صورة بنجاح`,
        );
        fetchStats();
        setTimeout(() => setMessage(null), 5000);
      } else {
        setError(response.data.message || "فشل في عملية الحذف");
      }
    } catch (err: any) {
      setError(err.response?.data?.message || "فشل في الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteCompanyImages = async (
    companyId: string,
    companyName: string,
    target: "CHAT" | "GALLERY" | "PRODUCTS" | "ALL" = "ALL",
  ) => {
    const targetNames: any = {
      CHAT: "صور الدردشات (النظام وواتساب)",
      GALLERY: "صور المعرض",
      PRODUCTS: "صور المنتجات",
      ALL: "كافة الصور والبيانات",
    };

    const targetName = targetNames[target];

    if (
      !window.confirm(
        `⚠️ تحذير: سيتم حذف ${targetName} الخاصة بشركة "${companyName}". هل أنت متأكد؟`,
      )
    )
      return;
    if (
      target === "ALL" &&
      !window.confirm(`تأكيد أخير: حذف كافة بيانات الصور لـ "${companyName}"؟`)
    )
      return;

    try {
      setLoading(true);
      const response = await apiClient.post(
        "/super-admin/image-stats/delete-company-images",
        { companyId, target },
      );

      if (response.status === 200 && response.data.success) {
        setMessage(`تم تنظيف ${targetName} لشركة ${companyName} بنجاح`);
        fetchStats();
        setTimeout(() => setMessage(null), 5000);
      } else {
        setError(response.data.message || "فشل في عملية الحذف");
      }
    } catch (err: any) {
      setError(err.response?.data?.message || "فشل في الاتصال بالخادم");
    } finally {
      setLoading(false);
      handleMenuClose();
    }
  };

  const handleRequestSort = (property: keyof CompanyStats) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
  };

  const handleScanOrphaned = async () => {
    try {
      setScanning(true);
      const response = await apiClient.get(
        "/super-admin/image-stats/orphaned-stats",
      );
      if (response.status === 200 && response.data.success) {
        setOrphanedStats(response.data.stats);
        setMessage(
          `تم العثور على ${response.data.stats.count} ملف يتيم يشغل مساحة ${formatSize(response.data.stats.size)}`,
        );
      } else {
        setError(response.data.message || "فشل في فحص الملفات");
      }
    } catch (err: any) {
      setError("حدث خطأ أثناء فحص الملفات");
    } finally {
      setScanning(false);
    }
  };

  const handleCleanupOrphaned = async () => {
    if (
      !window.confirm(
        "هل أنت متأكد من حذف الملفات اليتيمة؟ هذه العملية ستحذف كافة الصور والملفات غير المرتبطة بقاعدة البيانات نهائياً.",
      )
    )
      return;

    try {
      setCleaning(true);
      const response = await apiClient.post(
        "/super-admin/image-stats/cleanup-orphaned",
      );
      if (response.status === 200 && response.data.success) {
        const { deletedCount, deletedSize } = response.data.result;
        setMessage(
          `تم بنجاح حذف ${deletedCount} ملف يتيم وتوفير ${formatSize(deletedSize)}`,
        );
        setOrphanedStats(null);
        fetchStats();
      } else {
        setError(response.data.message || "فشل في عملية التنظيف");
      }
    } catch (err: any) {
      setError("حدث خطأ أثناء عملية التنظيف");
    } finally {
      setCleaning(false);
    }
  };

  const handleChangePage = (event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const filteredStats = React.useMemo(
    () =>
      stats.filter((item) =>
        item.companyName.toLowerCase().includes(searchTerm.toLowerCase()),
      ),
    [stats, searchTerm],
  );

  const sortedStats = React.useMemo(() => {
    return [...filteredStats].sort((a, b) => {
      const aValue = a[orderBy];
      const bValue = b[orderBy];

      if (bValue < aValue) return order === "asc" ? 1 : -1;
      if (bValue > aValue) return order === "asc" ? -1 : 1;
      return 0;
    });
  }, [filteredStats, orderBy, order]);

  const paginatedStats = React.useMemo(
    () =>
      sortedStats.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage),
    [sortedStats, page, rowsPerPage],
  );

  const systemTotals = React.useMemo(() => {
    const totalSize = stats.reduce((acc, curr) => acc + curr.totalSize, 0);
    const galleryCount = stats.reduce(
      (acc, curr) => acc + curr.galleryCount,
      0,
    );
    const productCount = stats.reduce(
      (acc, curr) => acc + curr.productCount,
      0,
    );
    const chatCount = stats.reduce(
      (acc, curr) =>
        acc + (curr.chatImageCount || 0) + (curr.whatsappImageCount || 0),
      0,
    );
    return {
      totalSize,
      galleryCount,
      productCount,
      chatCount,
      totalImages: galleryCount + productCount + chatCount,
    };
  }, [stats]);

  const chartData = React.useMemo(() => {
    return [...stats]
      .sort((a, b) => b.totalSize - a.totalSize)
      .slice(0, 5)
      .map((item) => ({
        name:
          item.companyName.length > 15
            ? item.companyName.substring(0, 12) + "..."
            : item.companyName,
        size: parseFloat((item.totalSize / (1024 * 1024)).toFixed(2)), // In MB
        fullName: item.companyName,
      }));
  }, [stats]);

  if (loading && stats.length === 0) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="60vh"
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 2, md: 3 }, direction: "rtl" }}>
      <Stack
        direction="row"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography
          variant="h4"
          sx={{ fontWeight: 800, color: isDark ? "#f8fafc" : "#1e293b" }}
        >
          إحصائيات استهلاك الصور
        </Typography>
        <Box>
          <IconButton
            onClick={fetchStats}
            color="primary"
            sx={{ bgcolor: alpha(muiTheme.palette.primary.main, 0.1) }}
          >
            <RefreshIcon />
          </IconButton>
        </Box>
      </Stack>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      )}
      {message && (
        <Alert severity="success" sx={{ mb: 3 }}>
          {message}
        </Alert>
      )}

      {/* Summary Cards */}
      <Grid container spacing={3} mb={4}>
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <Card
            sx={{
              borderRadius: 4,
              boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
              background: isDark
                ? "linear-gradient(135deg, #1e293b 0%, #0f172a 100%)"
                : "#fff",
              border: "1px solid",
              borderColor: isDark ? alpha("#fff", 0.05) : alpha("#000", 0.05),
            }}
          >
            <CardContent sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Box
                sx={{
                  p: 1.5,
                  borderRadius: 3,
                  bgcolor: alpha("#3b82f6", 0.1),
                  color: "#3b82f6",
                }}
              >
                <ImageIcon fontSize="large" />
              </Box>
              <Box>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ fontWeight: 600 }}
                >
                  إجمالي الصور
                </Typography>
                <Typography variant="h5" sx={{ fontWeight: 800 }}>
                  {systemTotals.totalImages.toLocaleString()}
                </Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <Card
            sx={{
              borderRadius: 4,
              boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
              background: isDark
                ? "linear-gradient(135deg, #1e293b 0%, #0f172a 100%)"
                : "#fff",
              border: "1px solid",
              borderColor: isDark ? alpha("#fff", 0.05) : alpha("#000", 0.05),
            }}
          >
            <CardContent sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Box
                sx={{
                  p: 1.5,
                  borderRadius: 3,
                  bgcolor: alpha("#10b981", 0.1),
                  color: "#10b981",
                }}
              >
                <StorageIcon fontSize="large" />
              </Box>
              <Box>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ fontWeight: 600 }}
                >
                  المساحة الإجمالية
                </Typography>
                <Typography variant="h5" sx={{ fontWeight: 800 }}>
                  {formatSize(systemTotals.totalSize)}
                </Typography>
