        </Grid>

        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <Card
            sx={{
              borderRadius: 4,
              boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
              background: isDark
                ? "linear-gradient(135deg, #1e293b 0%, #0f172a 100%)"
                : "#fff",
              border: "1px solid",
              borderColor: isDark ? alpha("#fff", 0.05) : alpha("#000", 0.05),
            }}
          >
            <CardContent sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Box
                sx={{
                  p: 1.5,
                  borderRadius: 3,
                  bgcolor: alpha("#8b5cf6", 0.1),
                  color: "#8b5cf6",
                }}
              >
                <InfoIcon fontSize="large" />
              </Box>
              <Box>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ fontWeight: 600 }}
                >
                  صور المحادثات
                </Typography>
                <Typography variant="h5" sx={{ fontWeight: 800 }}>
                  {systemTotals.chatCount.toLocaleString()}
                </Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <Card
            sx={{
              borderRadius: 4,
              boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
              background: isDark
                ? "linear-gradient(135deg, #1e293b 0%, #0f172a 100%)"
                : "#fff",
              border: "1px solid",
              borderColor: isDark ? alpha("#fff", 0.05) : alpha("#000", 0.05),
            }}
          >
            <CardContent sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Box
                sx={{
                  p: 1.5,
                  borderRadius: 3,
                  bgcolor: alpha("#f59e0b", 0.1),
                  color: "#f59e0b",
                }}
              >
                <ImageIcon fontSize="large" />
              </Box>
              <Box>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ fontWeight: 600 }}
                >
                  صور المنتجات
                </Typography>
                <Typography variant="h5" sx={{ fontWeight: 800 }}>
                  {systemTotals.productCount.toLocaleString()}
                </Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Maintenance Actions */}
      <Card
        sx={{
          mb: 4,
          borderRadius: 4,
          boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
          border: "1px solid",
          borderColor: alpha(muiTheme.palette.primary.main, 0.1),
          overflow: "hidden",
        }}
      >
        <Box
          sx={{
            p: 2,
            display: "flex",
            alignItems: "center",
            gap: 1.5,
            bgcolor: alpha(muiTheme.palette.primary.main, 0.05),
            borderBottom: "1px solid",
            borderColor: alpha(muiTheme.palette.primary.main, 0.1),
          }}
        >
          <CleaningServicesIcon color="primary" />
          <Typography variant="h6" sx={{ fontWeight: 700 }}>
            إجراءات الصيانة وتوفير المساحة
          </Typography>
        </Box>
        <CardContent>
          <Grid container spacing={2}>
            <Grid size={{ xs: 12, md: 4 }}>
              <Box
                sx={{
                  p: 2,
                  border: "1px dashed",
                  borderColor: "divider",
                  borderRadius: 2,
                }}
              >
                <Typography
                  variant="subtitle2"
                  gutterBottom
                  sx={{ fontWeight: 600 }}
                >
                  تنظيف صور الدردشات القديمة
                </Typography>
                <Typography
                  variant="caption"
                  display="block"
                  color="text.secondary"
                  mb={2}
                >
                  حذف صور المحادثات (النظام وواتساب) لتوفير المساحة.
                </Typography>
                <Stack direction="row" spacing={1}>
                  <Button
                    size="small"
                    variant="outlined"
                    color="warning"
                    startIcon={<DeleteSweepIcon />}
                    onClick={() => handleDeleteOldChatImages(3)}
                  >
                    أقدم من 3 أشهر
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    color="error"
                    startIcon={<DeleteSweepIcon />}
                    onClick={() => handleDeleteOldChatImages(6)}
                  >
                    أقدم من 6 أشهر
                  </Button>
                </Stack>
              </Box>
            </Grid>
            <Grid size={{ xs: 12, md: 4 }}>
              <Box
                sx={{
                  p: 2,
                  border: "1px dashed",
                  borderColor: "divider",
                  borderRadius: 2,
                  height: "100%",
                }}
              >
                <Typography
                  variant="subtitle2"
                  gutterBottom
                  sx={{ fontWeight: 600 }}
                >
                  تنظيف الملفات اليتيمة (Orphaned Files)
                </Typography>
                <Typography
                  variant="caption"
                  display="block"
                  color="text.secondary"
                  mb={2}
                >
                  البحث عن الملفات الموجودة على السيرفر وغير مرتبطة بقاعدة
                  البيانات ومسحها.
                </Typography>
                {orphanedStats ? (
                  <Box mb={2}>
                    <Typography
                      variant="body2"
                      sx={{ fontWeight: 700, color: "error.main" }}
                    >
                      وجدنا: {orphanedStats.count} ملف (
                      {formatSize(orphanedStats.size)})
                    </Typography>
                  </Box>
                ) : null}
                <Stack direction="row" spacing={1}>
                  <Button
                    size="small"
                    variant="outlined"
                    color="primary"
                    startIcon={
                      scanning ? (
                        <CircularProgress size={16} color="inherit" />
                      ) : (
                        <SearchIcon />
                      )
                    }
                    onClick={handleScanOrphaned}
                    disabled={scanning || cleaning}
                  >
                    {orphanedStats ? "إعادة الفحص" : "فحص الملفات"}
                  </Button>
                  {orphanedStats && orphanedStats.count > 0 && (
                    <Button
                      size="small"
                      variant="contained"
                      color="error"
                      startIcon={
                        cleaning ? (
                          <CircularProgress size={16} color="inherit" />
                        ) : (
                          <DeleteIcon />
                        )
                      }
                      onClick={handleCleanupOrphaned}
                      disabled={scanning || cleaning}
                    >
                      تنظيف الآن
                    </Button>
                  )}
                </Stack>
              </Box>
            </Grid>
            <Grid size={{ xs: 12, md: 4 }}>
              <Box
                sx={{
                  p: 2,
                  border: "1px dashed",
                  borderColor: "divider",
                  borderRadius: 2,
                  height: "100%",
                }}
              >
                <Typography
                  variant="subtitle2"
                  gutterBottom
                  sx={{ fontWeight: 600 }}
                >
                  ضغط الصور
                </Typography>
                <Typography
                  variant="caption"
                  display="block"
                  color="text.secondary"
                  mb={2}
                >
                  تقليل حجم الصور المخزنة دون التأثير الملحوظ على الجودة.
                </Typography>
                <Button
                  size="small"
                  variant="contained"
                  color="secondary"
                  startIcon={
                    compressing ? (
                      <CircularProgress size={16} color="inherit" />
                    ) : (
                      <AutoFixHighIcon />
                    )
                  }
                  onClick={handleCompressImages}
                  disabled={compressing}
                >
                  بدء عملية الضغط
                </Button>
              </Box>
            </Grid>
            <Grid size={{ xs: 12, md: 4 }}>
              <Box
                sx={{
                  p: 2,
                  border: "1px dashed",
                  borderColor: "divider",
                  borderRadius: 2,
                  height: "100%",
                }}
              >
                <Typography
                  variant="subtitle2"
                  gutterBottom
                  sx={{ fontWeight: 600 }}
                >
                  ملاحظة هامة
                </Typography>
                <Typography
                  variant="caption"
                  display="block"
                  color="text.secondary"
                >
                  • عمليات الحذف نهائية ولا يمكن التراجع عنها.
                  <br />
                  • حذف صور الدردشات سيجعل الصور غير متاحة للمستخدمين.
                  <br />• تنظيف الملفات اليتيمة هو أضمن وسيلة لتوفير المساحة
                  الضائعة.
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Visual Analytics */}
      <Grid container spacing={3} mb={4}>
        <Grid size={12}>
          <Card
            sx={{
              borderRadius: 4,
              boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
              p: 3,
            }}
          >
            <Typography
              variant="h6"
              gutterBottom
              sx={{ fontWeight: 700, mb: 3 }}
            >
              أكثر الشركات استهلاكاً للمساحة (MB)
            </Typography>
            <Box
              sx={{ height: 300, width: "100%", minHeight: 300, minWidth: 0 }}
            >
              <ResponsiveContainer
                width="100%"
                height={300}
                minHeight={300}
                minWidth={0}
              >
                <BarChart
                  data={chartData}
                  margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
                >
                  <CartesianGrid
                    strokeDasharray="3 3"
                    vertical={false}
                    stroke={isDark ? alpha("#fff", 0.1) : alpha("#000", 0.1)}
                  />
                  <XAxis
                    dataKey="name"
                    axisLine={false}
                    tickLine={false}
                    tick={{
                      fill: isDark ? "#94a3b8" : "#64748b",
                      fontSize: 12,
                    }}
                  />
                  <YAxis
                    axisLine={false}
                    tickLine={false}
                    tick={{
                      fill: isDark ? "#94a3b8" : "#64748b",
                      fontSize: 12,
                    }}
                  />
                  <RechartsTooltip
                    contentStyle={{
                      backgroundColor: isDark ? "#1e293b" : "#fff",
                      borderRadius: "8px",
                      border: "none",
                      boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
                    }}
                    itemStyle={{ color: "#3b82f6" }}
                    formatter={(value: any) => [`${value} MB`, "المساحة"]}
                  />
                  <Bar dataKey="size" radius={[4, 4, 0, 0]} barSize={40}>
                    {chartData.map((entry, index) => (
                      <Cell
                        key={`cell-${index}`}
                        fill={muiTheme.palette.primary.main}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </Box>
          </Card>
        </Grid>
      </Grid>

      {/* Data Table */}
      <Card
        sx={{
          borderRadius: 4,
          boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
          overflow: "hidden",
        }}
      >
        <Box
          sx={{
            p: 2,
            display: "flex",
            gap: 2,
            alignItems: "center",
            bgcolor: isDark ? alpha("#fff", 0.02) : alpha("#000", 0.02),
          }}
        >
          <TextField
            placeholder="البحث عن شركة..."
            variant="outlined"
            size="small"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            sx={{ width: 300 }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon fontSize="small" />
                </InputAdornment>
              ),
            }}
          />
          <Tooltip title="المساحة تشمل صور الحافظة وصور المنتجات المخزنة محلياً">
            <InfoIcon color="action" fontSize="small" />
          </Tooltip>
        </Box>

        <TableContainer
          component={Paper}
          elevation={0}
          sx={{ maxHeight: "unset" }}
        >
          <Table stickyHeader aria-label="image usage statistics">
            <TableHead>
              <TableRow>
                <TableCell>
                  <TableSortLabel
                    active={orderBy === "companyName"}
                    direction={orderBy === "companyName" ? order : "asc"}
                    onClick={() => handleRequestSort("companyName")}
                  >
                    الشركة
                  </TableSortLabel>
                </TableCell>
                <TableCell align="center">
                  <TableSortLabel
                    active={orderBy === "galleryCount"}
                    direction={orderBy === "galleryCount" ? order : "asc"}
                    onClick={() => handleRequestSort("galleryCount")}
                  >
                    صور الحافظة
                  </TableSortLabel>
                </TableCell>
                <TableCell align="center">
                  <TableSortLabel
                    active={orderBy === "productCount"}
                    direction={orderBy === "productCount" ? order : "asc"}
                    onClick={() => handleRequestSort("productCount")}
                  >
                    صور المنتجات
                  </TableSortLabel>
                </TableCell>
                <TableCell align="center">
                  <TableSortLabel
                    active={orderBy === "chatImageCount"}
                    direction={orderBy === "chatImageCount" ? order : "asc"}
                    onClick={() => handleRequestSort("chatImageCount")}
                  >
                    الدردشات
                  </TableSortLabel>
                </TableCell>
                <TableCell align="center">
                  <TableSortLabel
                    active={orderBy === "whatsappImageCount"}
                    direction={orderBy === "whatsappImageCount" ? order : "asc"}
                    onClick={() => handleRequestSort("whatsappImageCount")}
                  >
                    واتساب
                  </TableSortLabel>
                </TableCell>
                <TableCell align="center">
                  <TableSortLabel
                    active={orderBy === "totalCount"}
                    direction={orderBy === "totalCount" ? order : "asc"}
                    onClick={() => handleRequestSort("totalCount")}
                  >
                    إجمالي الصور
                  </TableSortLabel>
                </TableCell>
                <TableCell align="center">
                  <TableSortLabel
                    active={orderBy === "totalSize"}
                    direction={orderBy === "totalSize" ? order : "asc"}
                    onClick={() => handleRequestSort("totalSize")}
                  >
                    إجمالي الحجم
                  </TableSortLabel>
                </TableCell>
                <TableCell align="center">إجراءات</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedStats.map((row) => (
                <TableRow
                  key={row.companyId}
                  hover
                  sx={{ "&:last-child td, &:last-child th": { border: 0 } }}
                >
                  <TableCell component="th" scope="row">
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>
                      {row.companyName}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {row.companyId}
                    </Typography>
                  </TableCell>
                  <TableCell align="center">
                    {row.galleryCount.toLocaleString()}
                  </TableCell>
                  <TableCell align="center">
                    <Typography variant="body2">
                      {row.productCount.toLocaleString()}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {formatSize(row.productSize)}
                    </Typography>
                  </TableCell>
                  <TableCell align="center">
                    <Typography variant="body2">
                      {(row.chatImageCount || 0).toLocaleString()}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {formatSize(row.chatImageSize || 0)}
                    </Typography>
                  </TableCell>
                  <TableCell align="center">
                    <Typography variant="body2">
                      {(row.whatsappImageCount || 0).toLocaleString()}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {formatSize(row.whatsappImageSize || 0)}
                    </Typography>
                  </TableCell>
                  <TableCell align="center">
                    <Typography
                      variant="body2"
                      sx={{ fontWeight: 700, color: "#3b82f6" }}
                    >
                      {row.totalCount.toLocaleString()}
                    </Typography>
                  </TableCell>
                  <TableCell align="center">
                    <Typography
                      variant="body2"
                      sx={{ fontWeight: 700, color: "#10b981" }}
                    >
                      {formatSize(row.totalSize)}
                    </Typography>
                  </TableCell>
                  <TableCell align="center">
                    <Tooltip title="خيارات الحذف">
                      <IconButton
                        size="small"
                        color="error"
                        onClick={(e) =>
                          handleMenuOpen(e, row.companyId, row.companyName)
                        }
                        sx={{
                          bgcolor: alpha(muiTheme.palette.error.main, 0.1),
                        }}
                      >
                        <SettingsIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))}
              {paginatedStats.length === 0 && (
                <TableRow>
                  <TableCell colSpan={7} align="center" sx={{ py: 3 }}>
                    لا توجد بيانات للعرض
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
        <TablePagination
          rowsPerPageOptions={[10, 25, 50]}
          component="div"
          count={filteredStats.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          labelRowsPerPage="عدد الصفوف:"
          labelDisplayedRows={({ from, to, count }) =>
            `${from}-${to} من ${count}`
          }
        />
      </Card>

      {/* Deletion Menu for Companies */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: {
            borderRadius: 3,
            boxShadow: "0 10px 40px rgba(0,0,0,0.1)",
            border: "1px solid",
            borderColor: "divider",
            minWidth: 180,
          },
        }}
        transformOrigin={{ horizontal: "right", vertical: "top" }}
        anchorOrigin={{ horizontal: "right", vertical: "bottom" }}
      >
        <Box
          sx={{
            px: 2,
            py: 1.5,
            borderBottom: "1px solid",
            borderColor: "divider",
            mb: 1,
          }}
        >
          <Typography variant="caption" color="text.secondary" display="block">
            خيارات الحذف لـ
          </Typography>
          <Typography variant="body2" sx={{ fontWeight: 700 }}>
            {selectedCompany?.name}
          </Typography>
        </Box>

        <MenuItem
          onClick={() =>
            handleDeleteCompanyImages(
              selectedCompany!.id,
              selectedCompany!.name,
              "CHAT",
            )
          }
          sx={{ py: 1.5 }}
        >
          <Stack direction="row" spacing={1.5} alignItems="center">
            <CleaningServicesIcon fontSize="small" color="primary" />
            <Typography variant="body2">حذف صور الدردشات</Typography>
          </Stack>
        </MenuItem>

        <MenuItem
          onClick={() =>
            handleDeleteCompanyImages(
              selectedCompany!.id,
              selectedCompany!.name,
              "GALLERY",
            )
          }
          sx={{ py: 1.5 }}
        >
          <Stack direction="row" spacing={1.5} alignItems="center">
            <ImageIcon fontSize="small" color="info" />
            <Typography variant="body2">حذف صور المعرض</Typography>
          </Stack>
        </MenuItem>

        <MenuItem
          onClick={() =>
            handleDeleteCompanyImages(
              selectedCompany!.id,
              selectedCompany!.name,
              "PRODUCTS",
            )
          }
          sx={{ py: 1.5 }}
        >
          <Stack direction="row" spacing={1.5} alignItems="center">
            <BusinessIcon fontSize="small" color="warning" />
            <Typography variant="body2">حذف صور المنتجات</Typography>
          </Stack>
        </MenuItem>

        <Box sx={{ borderTop: "1px solid", borderColor: "divider", mt: 1 }}>
          <MenuItem
            onClick={() =>
              handleDeleteCompanyImages(
                selectedCompany!.id,
                selectedCompany!.name,
                "ALL",
              )
            }
            sx={{ py: 1.5, color: "error.main" }}
          >
            <Stack direction="row" spacing={1.5} alignItems="center">
              <DeleteSweepIcon fontSize="small" color="error" />
              <Typography variant="body2" sx={{ fontWeight: 700 }}>
                حذف كافة البيانات
              </Typography>
            </Stack>
          </MenuItem>
        </Box>
      </Menu>
    </Box>
  );
};

export default SuperAdminImageStats;

import React, { useState, useEffect } from "react";
import {
  Typography,
  Button,
  TextField,
  Switch,
  FormControlLabel,
  Alert,
  CircularProgress,
  Grid,
  Paper,
  Box,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  Tabs,
  Tab,
  Chip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import {
  Settings as SettingsIcon,
  Image as ImageIcon,
  TrendingUp as TrendingUpIcon,
  CheckCircle as CheckCircleIcon,
  Cancel as XCircleIcon,
  VpnKey as KeyIcon,
} from "@mui/icons-material";
import { apiClient } from "../services/apiClient";

const SuperAdminImageStudio: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<any>(null);
  const [stats, setStats] = useState<any>(null);
  const [keys, setKeys] = useState<any[]>([]);
  const [currentTab, setCurrentTab] = useState(0);
  const [message, setMessage] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  useEffect(() => {
    loadSettings();
    loadStats();
    loadKeys();
  }, []);

  const loadSettings = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/image-studio/admin/settings");
      if (response.data.success) {
        setSettings(response.data.settings);
      }
    } catch (error: any) {
      console.error("Error loading settings:", error);
      setMessage({
        type: "error",
        text: error.response?.data?.error || "فشل تحميل الإعدادات",
      });
    } finally {
      setLoading(false);
    }
  };

  const loadStats = async () => {
    try {
      const response = await apiClient.get("/image-studio/admin/stats");
      if (response.data.success) {
        setStats(response.data.stats);
      }
    } catch (error) {
      console.error("Error loading stats:", error);
    }
  };

  const loadKeys = async () => {
    try {
      const response = await apiClient.get("/image-studio/admin/keys");
      if (response.data.success) {
        setKeys(response.data.keys);
      }
    } catch (error) {
      console.error("Error loading keys:", error);
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);
      setMessage(null);

      const response = await apiClient.put(
        "/image-studio/admin/settings",
        settings,
      );

      if (response.data.success) {
        setMessage({ type: "success", text: "تم حفظ الإعدادات بنجاح" });
        loadSettings();
      }
    } catch (error: any) {
      console.error("Error saving settings:", error);
      setMessage({
        type: "error",
        text: error.response?.data?.error || "فشل حفظ الإعدادات",
      });
    } finally {
      setSaving(false);
    }
  };

  const updateSetting = (key: string, value: any) => {
    setSettings((prev: any) => ({ ...prev, [key]: value }));
  };

  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="400px"
      >
        <Box textAlign="center">
          <CircularProgress size={60} sx={{ mb: 2 }} />
          <Typography color="text.secondary">جاري التحميل...</Typography>
        </Box>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3, maxWidth: 1400, mx: "auto" }} dir="rtl">
      <Box sx={{ mb: 4 }}>
        <Box display="flex" alignItems="center" gap={1} mb={1}>
          <ImageIcon sx={{ fontSize: 32 }} />
          <Typography variant="h4" component="h1" fontWeight="bold">
            استديو توليد الصور (Nano Banana)
          </Typography>
        </Box>
        <Typography color="text.secondary">
          إدارة إعدادات نظام توليد الصور باستخدام Google AI Image Models
        </Typography>
      </Box>

      {message && (
        <Alert
          severity={message.type === "success" ? "success" : "error"}
          sx={{ mb: 3 }}
        >
          {message.text}
        </Alert>
      )}

      {/* Statistics Cards */}
      {stats && (
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid size={{ xs: 12, sm: 6, md: 3 }}>
            <Paper sx={{ p: 2 }}>
              <Box
                display="flex"
                justifyContent="space-between"
                alignItems="center"
              >
                <Box>
                  <Typography variant="body2" color="text.secondary">
                    إجمالي الصور
                  </Typography>
                  <Typography variant="h4" fontWeight="bold">
                    {stats.totalImages}
                  </Typography>
                </Box>
                <ImageIcon sx={{ fontSize: 40, color: "primary.main" }} />
              </Box>
            </Paper>
          </Grid>

          <Grid size={{ xs: 12, sm: 6, md: 3 }}>
            <Paper sx={{ p: 2 }}>
              <Box
                display="flex"
                justifyContent="space-between"
                alignItems="center"
              >
                <Box>
                  <Typography variant="body2" color="text.secondary">
                    نجحت
                  </Typography>
                  <Typography
                    variant="h4"
                    fontWeight="bold"
                    color="success.main"
                  >
                    {stats.completedImages}
                  </Typography>
                </Box>
                <CheckCircleIcon sx={{ fontSize: 40, color: "success.main" }} />
              </Box>
            </Paper>
          </Grid>

          <Grid size={{ xs: 12, sm: 6, md: 3 }}>
            <Paper sx={{ p: 2 }}>
              <Box
                display="flex"
                justifyContent="space-between"
                alignItems="center"
              >
                <Box>
                  <Typography variant="body2" color="text.secondary">
                    فشلت
                  </Typography>
                  <Typography variant="h4" fontWeight="bold" color="error.main">
                    {stats.failedImages}
                  </Typography>
                </Box>
                <XCircleIcon sx={{ fontSize: 40, color: "error.main" }} />
              </Box>
            </Paper>
          </Grid>

          <Grid size={{ xs: 12, sm: 6, md: 3 }}>
            <Paper sx={{ p: 2 }}>
              <Box
                display="flex"
                justifyContent="space-between"
                alignItems="center"
              >
                <Box>
                  <Typography variant="body2" color="text.secondary">
                    نسبة النجاح
                  </Typography>
                  <Typography
                    variant="h4"
                    fontWeight="bold"
                    color="primary.main"
                  >
                    {stats.successRate}%
                  </Typography>
                </Box>
                <TrendingUpIcon sx={{ fontSize: 40, color: "primary.main" }} />
              </Box>
            </Paper>
          </Grid>
        </Grid>
      )}

      {/* Tabs */}
      <Box sx={{ borderBottom: 1, borderColor: "divider", mb: 3 }}>
        <Tabs
          value={currentTab}
          onChange={(_e, newValue) => setCurrentTab(newValue)}
        >
          <Tab icon={<SettingsIcon />} label="الإعدادات" iconPosition="start" />
          <Tab icon={<KeyIcon />} label="المفاتيح" iconPosition="start" />
        </Tabs>
      </Box>

      {/* Tab 0: Settings */}
      {currentTab === 0 && settings && (
        <Grid container spacing={3}>
          <Grid size={{ xs: 12, lg: 6 }}>
            <Paper sx={{ p: 3 }}>
              <Box display="flex" alignItems="center" gap={1} mb={2}>
                <SettingsIcon />
                <Typography variant="h6">الإعدادات العامة</Typography>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={settings.enabled}
                      onChange={(e) =>
                        updateSetting("enabled", e.target.checked)
                      }
                    />
                  }
                  label="تفعيل الاستديو"
                />

                <FormControl fullWidth>
                  <InputLabel>اختر مفتاح Google AI</InputLabel>
                  <Select
                    value={settings.selectedKeyId || ""}
                    label="اختر مفتاح Google AI"
                    onChange={(e) =>
                      updateSetting("selectedKeyId", e.target.value || null)
                    }
                  >
                    <MenuItem value="">استخدام المفاتيح التلقائية</MenuItem>
                    {keys.map((key) => (
                      <MenuItem key={key.id} value={key.id}>
                        {key.name} ({key.keyType}) - {key.maskedKey}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>

                <FormControl fullWidth>
                  <InputLabel>النموذج الافتراضي</InputLabel>
                  <Select
                    value={settings.defaultModel}
                    label="النموذج الافتراضي"
                    onChange={(e) =>
                      updateSetting("defaultModel", e.target.value)
                    }
                  >
                    <MenuItem value="basic">Basic (سريع)</MenuItem>
                    <MenuItem value="pro">Pro (احترافي)</MenuItem>
                  </Select>
                </FormControl>

                <TextField
                  label="الحد الأقصى للصور في الطلب الواحد"
                  type="number"
                  inputProps={{ min: 1, max: 10 }}
                  value={settings.maxImagesPerRequest}
                  onChange={(e) =>
                    updateSetting(
                      "maxImagesPerRequest",
                      parseInt(e.target.value),
                    )
                  }
                  fullWidth
                />

                <TextField
                  label="الحد الأقصى للطلبات اليومية (لكل شركة)"
                  type="number"
                  inputProps={{ min: 1, max: 1000 }}
                  value={settings.maxRequestsPerDay}
                  onChange={(e) =>
                    updateSetting("maxRequestsPerDay", parseInt(e.target.value))
                  }
                  fullWidth
                />
              </Box>
            </Paper>
          </Grid>

          <Grid size={{ xs: 12, lg: 6 }}>
            <Paper sx={{ p: 3 }}>
              <Box display="flex" alignItems="center" gap={1} mb={2}>
                <ImageIcon />
                <Typography variant="h6">إعدادات النماذج</Typography>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
                <Box>
                  <FormControl fullWidth>
                    <InputLabel>نموذج Basic</InputLabel>
                    <Select
                      value={settings.basicModelName}
                      label="نموذج Basic"
                      onChange={(e) =>
                        updateSetting("basicModelName", e.target.value)
                      }
                    >
                      <MenuItem value="gemini-2.5-flash-image">
                        Nano Banana (gemini-2.5-flash-image)
                      </MenuItem>
                      <MenuItem value="imagen-3.0-generate-002">
                        Imagen 3 (imagen-3.0-generate-002)
                      </MenuItem>
                    </Select>
                  </FormControl>
                  <Typography
                    variant="caption"
                    color="text.secondary"
                    sx={{ mt: 0.5, display: "block" }}
                  >
                    النموذج السريع والفعال - مناسب للاستخدام اليومي
                  </Typography>
                </Box>

                <Box>
                  <FormControl fullWidth>
                    <InputLabel>نموذج Pro</InputLabel>
                    <Select
                      value={settings.proModelName}
                      label="نموذج Pro"
                      onChange={(e) =>
                        updateSetting("proModelName", e.target.value)
                      }
                    >
                      <MenuItem value="gemini-3-pro-image-preview">
                        Nano Banana Pro (gemini-3-pro-image-preview)
                      </MenuItem>
                      <MenuItem value="imagen-4.0-generate-002">
                        Imagen 4 (imagen-4.0-generate-002)
                      </MenuItem>
                    </Select>
                  </FormControl>
                  <Typography
                    variant="caption"
                    color="text.secondary"
                    sx={{ mt: 0.5, display: "block" }}
                  >
                    النموذج الاحترافي - جودة عالية ونصوص واضحة
                  </Typography>
                </Box>
              </Box>
            </Paper>
          </Grid>
        </Grid>
      )}

      {/* Tab 1: Keys */}
      {currentTab === 1 && (
        <Paper sx={{ p: 3 }}>
          <Box display="flex" alignItems="center" gap={1} mb={3}>
            <KeyIcon />
            <Typography variant="h6">مفاتيح Google AI المتاحة</Typography>
          </Box>

          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>الاسم</TableCell>
                  <TableCell>النوع</TableCell>
                  <TableCell>المفتاح</TableCell>
                  <TableCell>الأولوية</TableCell>
                  <TableCell>الحالة</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {keys.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={5} align="center">
                      <Typography color="text.secondary">
                        لا توجد مفاتيح نشطة
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  keys.map((key) => (
                    <TableRow key={key.id}>
                      <TableCell>{key.name}</TableCell>
                      <TableCell>
                        <Chip
                          label={key.keyType}
                          size="small"
                          color={key.keyType === "PRO" ? "primary" : "default"}
                        />
                      </TableCell>
                      <TableCell
                        sx={{ fontFamily: "monospace", fontSize: "0.875rem" }}
                      >
                        {key.maskedKey}
                      </TableCell>
                      <TableCell>{key.priority}</TableCell>
                      <TableCell>
                        <Chip
                          label={key.isActive ? "نشط" : "غير نشط"}
                          size="small"
                          color={key.isActive ? "success" : "default"}
                        />
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <Alert severity="info" sx={{ mt: 3 }}>
            <Typography variant="body2">
              <strong>ملاحظة:</strong> يمكنك اختيار مفتاح محدد من تبويب
              الإعدادات، أو ترك الخيار فارغاً لاستخدام نظام التبديل التلقائي.
            </Typography>
          </Alert>
        </Paper>
      )}

      {/* Save Button */}
      {currentTab === 0 && (
        <Box sx={{ mt: 3, display: "flex", justifyContent: "flex-end" }}>
          <Button
            variant="contained"
            onClick={handleSave}
            disabled={saving}
            size="large"
          >
            {saving ? "جاري الحفظ..." : "حفظ الإعدادات"}
          </Button>
        </Box>
      )}
    </Box>
  );
};

export default SuperAdminImageStudio;

import React, { useState, useEffect } from "react";
import tokenManager from "../utils/tokenManager";
import { buildApiUrl } from "../utils/urlHelper";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Button,
  TextField,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Tooltip,
  Alert,
  CircularProgress,
  Pagination,
  Tabs,
  Tab,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Send as SendIcon,
  GetApp as DownloadIcon,
  Visibility as ViewIcon,
  Search as SearchIcon,
  FilterList as FilterIcon,
  Receipt as ReceiptIcon,
  Payment as PaymentIcon,
  TrendingUp as TrendingUpIcon,
  AttachMoney as MoneyIcon,
} from "@mui/icons-material";
import { useNavigate, useSearchParams } from "react-router-dom";

const SuperAdminInvoices = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const getAccessToken = () => tokenManager.getAccessToken();
  const getAuthHeaders = (additionalHeaders = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);
  const [invoices, setInvoices] = useState([]);
  const [stats, setStats] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [activeTab, setActiveTab] = useState(0);

  const [filters, setFilters] = useState({
    search: "",
    status: "",
    type: "",
    dateFrom: "",
    dateTo: "",
    sortBy: "createdAt",
    sortOrder: "desc",
  });

  // Dialog states
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [selectedInvoice, setSelectedInvoice] = useState(null);

  // Form data for creating invoice
  const [formData, setFormData] = useState({
    companyId: "",
    subscriptionId: "",
    type: "SUBSCRIPTION",
    dueDate: "",
    items: [{ description: "", quantity: 1, unitPrice: 0 }],
    taxRate: 14,
    discountAmount: 0,
    notes: "",
    paymentTerms: "Net 30",
  });

  useEffect(() => {
    // Check if there's a subscription filter from URL
    const subscriptionId = searchParams.get("subscription");
    const invoiceId = searchParams.get("invoice");
    if (subscriptionId && !filters.subscriptionId) {
      setFilters((prev) => ({ ...prev, subscriptionId }));
      return; // Exit early to prevent double fetch
    }
    if (invoiceId && !filters.invoiceId) {
      setFilters((prev) => ({ ...prev, invoiceId }));
      return; // Exit early to prevent double fetch
    }
    fetchInvoices();
  }, [page, filters]);

  // Separate effect for URL params to avoid infinite loop
  useEffect(() => {
    const subscriptionId = searchParams.get("subscription");
    const invoiceId = searchParams.get("invoice");
    if (subscriptionId && !filters.subscriptionId) {
      setFilters((prev) => ({ ...prev, subscriptionId }));
    }
    if (invoiceId && !filters.invoiceId) {
      setFilters((prev) => ({ ...prev, invoiceId }));
    }
  }, [searchParams]);

  const fetchInvoices = async () => {
    try {
      setLoading(true);
      const token = getAccessToken();

      const queryParams = new URLSearchParams({
        page: page.toString(),
        limit: "10",
        ...filters,
      });

      const response = await fetch(
        buildApiUrl(`admin/invoices?${queryParams}`),
        {
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
        },
      );

      const data = await response.json();

      if (data.success) {
        setInvoices(data.data.invoices);
        setStats(data.data.stats);
        setTotalPages(data.data.pagination.pages);
      } else {
        setError(data.message || "خطأ في جلب البيانات");
      }
    } catch (error) {
      console.error("Error fetching invoices:", error);
      setError("خطأ في الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  const fetchInvoiceStats = async () => {
    try {
      const token = getAccessToken();

      const response = await fetch(
        buildApiUrl("admin/invoices/stats/overview"),
        {
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
        },
      );

      const data = await response.json();

      if (data.success) {
        setStats(data.data);
      }
    } catch (error) {
      console.error("Error fetching invoice stats:", error);
    }
  };

  useEffect(() => {
    if (activeTab === 1) {
      fetchInvoiceStats();
    }
  }, [activeTab]);

  const handleFilterChange = (field, value) => {
    setFilters((prev) => ({
      ...prev,
      [field]: value,
    }));
    setPage(1);
  };

  const getStatusColor = (status) => {
    const colors = {
      DRAFT: "default",
      SENT: "info",
      PAID: "success",
      OVERDUE: "error",
      CANCELLED: "error",
      REFUNDED: "warning",
    };
    return colors[status] || "default";
  };

  const getStatusText = (status) => {
    const texts = {
      DRAFT: "مسودة",
      SENT: "مرسلة",
      PAID: "مدفوعة",
      OVERDUE: "متأخرة",
      CANCELLED: "ملغية",
      REFUNDED: "مستردة",
    };
    return texts[status] || status;
  };

  const getTypeText = (type) => {
    const texts = {
      SUBSCRIPTION: "اشتراك",
      ONE_TIME: "مرة واحدة",
      UPGRADE: "ترقية",
      DOWNGRADE: "تخفيض",
      REFUND: "استرداد",
    };
    return texts[type] || type;
  };

  const formatPrice = (price, currency = "EGP") => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: currency,
    }).format(price);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("ar-EG");
  };

  const handleSendInvoice = async (invoiceId) => {
    try {
      const token = getAccessToken();

      const response = await fetch(
        buildApiUrl(`admin/invoices/${invoiceId}/send`),
        {
          method: "POST",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
        },
      );

      const data = await response.json();

      if (data.success) {
        fetchInvoices();
      } else {
        setError(data.message || "خطأ في إرسال الفاتورة");
      }
    } catch (error) {
      console.error("Error sending invoice:", error);
      setError("خطأ في الاتصال بالخادم");
    }
  };

  const handleUpdateStatus = async (invoiceId, status) => {
    try {
      const token = getAccessToken();

      const response = await fetch(
        buildApiUrl(`admin/invoices/${invoiceId}/status`),
        {
          method: "PUT",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
          body: JSON.stringify({ status }),
        },
      );

      const data = await response.json();

      if (data.success) {
        fetchInvoices();
      } else {
        setError(data.message || "خطأ في تحديث حالة الفاتورة");
      }
    } catch (error) {
      console.error("Error updating invoice status:", error);
      setError("خطأ في الاتصال بالخادم");
    }
  };

  const addInvoiceItem = () => {
    setFormData((prev) => ({
      ...prev,
      items: [...prev.items, { description: "", quantity: 1, unitPrice: 0 }],
    }));
  };

  const removeInvoiceItem = (index) => {
    setFormData((prev) => ({
      ...prev,
      items: prev.items.filter((_, i) => i !== index),
    }));
  };

  const updateInvoiceItem = (index, field, value) => {
    setFormData((prev) => ({
      ...prev,
      items: prev.items.map((item, i) =>
        i === index ? { ...item, [field]: value } : item,
      ),
    }));
  };

  const calculateSubtotal = () => {
    return formData.items.reduce(
      (sum, item) => sum + item.quantity * item.unitPrice,
      0,
    );
  };

  const calculateTotal = () => {
    const subtotal = calculateSubtotal();
    const tax = (subtotal * formData.taxRate) / 100;
    return subtotal + tax - formData.discountAmount;
  };

  if (loading && invoices.length === 0) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="400px"
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h4" component="h1">
          إدارة الفواتير
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setCreateDialogOpen(true)}
        >
          فاتورة جديدة
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError("")}>
          {error}
        </Alert>
      )}

      <Box sx={{ borderBottom: 1, borderColor: "divider", mb: 3 }}>
        <Tabs
          value={activeTab}
          onChange={(e, newValue) => setActiveTab(newValue)}
        >
          <Tab label="الفواتير" />
          <Tab label="الإحصائيات" />
        </Tabs>
      </Box>

      {activeTab === 0 && (
        <>
          {/* Statistics Cards */}
          <Grid container spacing={3} sx={{ mb: 3 }}>
            <Grid item xs={12} md={3}>
              <Card>
                <CardContent>
                  <Typography color="textSecondary" gutterBottom>
                    إجمالي الفواتير
                  </Typography>
                  <Typography variant="h4">{stats.total || 0}</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card>
                <CardContent>
                  <Typography color="textSecondary" gutterBottom>
                    الفواتير المدفوعة
                  </Typography>
                  <Typography variant="h4" color="success.main">
                    {stats.byStatus?.PAID?.count || 0}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card>
                <CardContent>
                  <Typography color="textSecondary" gutterBottom>
                    الفواتير المتأخرة
                  </Typography>
                  <Typography variant="h4" color="error.main">
                    {stats.byStatus?.OVERDUE?.count || 0}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card>
                <CardContent>
                  <Typography color="textSecondary" gutterBottom>
                    إجمالي الإيرادات
                  </Typography>
                  <Typography variant="h4" color="primary.main">
                    {formatPrice(stats.totalRevenue || 0)}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          {/* Filters */}
          <Card sx={{ mb: 3 }}>
            <CardContent>
              <Grid container spacing={2} alignItems="center">
                <Grid item xs={12} md={3}>
                  <TextField
                    fullWidth
                    label="البحث"
                    value={filters.search}
                    onChange={(e) =>
                      handleFilterChange("search", e.target.value)
                    }
                    InputProps={{
                      startAdornment: (
                        <SearchIcon sx={{ mr: 1, color: "text.secondary" }} />
                      ),
                    }}
                  />
                </Grid>
                <Grid item xs={12} md={2}>
                  <FormControl fullWidth>
                    <InputLabel>الحالة</InputLabel>
                    <Select
                      value={filters.status}
                      onChange={(e) =>
                        handleFilterChange("status", e.target.value)
                      }
                      label="الحالة"
                    >
                      <MenuItem value="">الكل</MenuItem>
                      <MenuItem value="DRAFT">مسودة</MenuItem>
                      <MenuItem value="SENT">مرسلة</MenuItem>
                      <MenuItem value="PAID">مدفوعة</MenuItem>
                      <MenuItem value="OVERDUE">متأخرة</MenuItem>
                      <MenuItem value="CANCELLED">ملغية</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} md={2}>
                  <FormControl fullWidth>
                    <InputLabel>النوع</InputLabel>
                    <Select
                      value={filters.type}
                      onChange={(e) =>
                        handleFilterChange("type", e.target.value)
                      }
                      label="النوع"
                    >
                      <MenuItem value="">الكل</MenuItem>
                      <MenuItem value="SUBSCRIPTION">اشتراك</MenuItem>
                      <MenuItem value="ONE_TIME">مرة واحدة</MenuItem>
                      <MenuItem value="UPGRADE">ترقية</MenuItem>
                      <MenuItem value="DOWNGRADE">تخفيض</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} md={2}>
                  <TextField
                    fullWidth
                    label="من تاريخ"
                    type="date"
                    value={filters.dateFrom}
                    onChange={(e) =>
                      handleFilterChange("dateFrom", e.target.value)
                    }
                    InputLabelProps={{ shrink: true }}
                  />
                </Grid>
                <Grid item xs={12} md={2}>
                  <TextField
                    fullWidth
                    label="إلى تاريخ"
                    type="date"
                    value={filters.dateTo}
                    onChange={(e) =>
                      handleFilterChange("dateTo", e.target.value)
                    }
                    InputLabelProps={{ shrink: true }}
                  />
                </Grid>
              </Grid>
            </CardContent>
          </Card>

          {/* Invoices Table */}
          <Card>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>رقم الفاتورة</TableCell>
                    <TableCell>الشركة</TableCell>
                    <TableCell>النوع</TableCell>
                    <TableCell>الحالة</TableCell>
                    <TableCell>المبلغ</TableCell>
                    <TableCell>تاريخ الإصدار</TableCell>
                    <TableCell>تاريخ الاستحقاق</TableCell>
                    <TableCell>الإجراءات</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {invoices.map((invoice) => (
                    <TableRow key={invoice.id}>
                      <TableCell>
                        <Typography variant="subtitle2">
                          {invoice.invoiceNumber}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Box>
                          <Typography variant="subtitle2">
                            {invoice.company.name}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            {invoice.company.email}
                          </Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={getTypeText(invoice.type)}
                          variant="outlined"
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={getStatusText(invoice.status)}
                          color={getStatusColor(invoice.status)}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        {formatPrice(invoice.totalAmount, invoice.currency)}
                      </TableCell>
                      <TableCell>{formatDate(invoice.issueDate)}</TableCell>
                      <TableCell>{formatDate(invoice.dueDate)}</TableCell>
                      <TableCell>
                        <Box display="flex" gap={1}>
                          <Tooltip title="عرض التفاصيل">
                            <IconButton
                              size="small"
                              onClick={() => {
                                setSelectedInvoice(invoice);
                                setViewDialogOpen(true);
                              }}
                            >
                              <ViewIcon />
                            </IconButton>
                          </Tooltip>
                          {invoice.status === "DRAFT" && (
                            <Tooltip title="إرسال">
                              <IconButton
                                size="small"
                                color="primary"
                                onClick={() => handleSendInvoice(invoice.id)}
                              >
                                <SendIcon />
                              </IconButton>
                            </Tooltip>
                          )}
                          {invoice.status === "SENT" && (
                            <Tooltip title="تحديد كمدفوعة">
                              <IconButton
                                size="small"
                                color="success"
                                onClick={() =>
                                  handleUpdateStatus(invoice.id, "PAID")
                                }
                              >
                                <PaymentIcon />
                              </IconButton>
                            </Tooltip>
                          )}
                          <Tooltip title="عرض المدفوعات">
                            <IconButton
                              size="small"
                              onClick={() =>
                                navigate(
                                  `/super-admin/payments?invoice=${invoice.id}`,
                                )
                              }
                            >
                              <MoneyIcon />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            {totalPages > 1 && (
              <Box display="flex" justifyContent="center" p={2}>
                <Pagination
                  count={totalPages}
                  page={page}
                  onChange={(e, newPage) => setPage(newPage)}
                  color="primary"
                />
              </Box>
            )}
          </Card>
        </>
      )}

      {activeTab === 1 && (
        <Grid container spacing={3}>
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  نظرة عامة على الفواتير
                </Typography>
                {stats.overview && (
                  <Grid container spacing={2}>
                    <Grid item xs={6}>
                      <Typography variant="body2" color="text.secondary">
                        إجمالي الفواتير
                      </Typography>
                      <Typography variant="h6">
                        {stats.overview.totalInvoices}
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2" color="text.secondary">
                        الفواتير المدفوعة
                      </Typography>
                      <Typography variant="h6" color="success.main">
                        {stats.overview.paidInvoices}
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2" color="text.secondary">
                        الفواتير المتأخرة
                      </Typography>
                      <Typography variant="h6" color="error.main">
                        {stats.overview.overdueInvoices}
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2" color="text.secondary">
                        الفواتير المعلقة
                      </Typography>
                      <Typography variant="h6" color="warning.main">
                        {stats.overview.pendingInvoices}
                      </Typography>
                    </Grid>
                    <Grid item xs={12}>
                      <Typography variant="body2" color="text.secondary">
                        إجمالي الإيرادات
                      </Typography>
                      <Typography variant="h5" color="primary.main">
                        {formatPrice(stats.overview.totalRevenue)}
                      </Typography>
                    </Grid>
                    <Grid item xs={12}>
                      <Typography variant="body2" color="text.secondary">
                        متوسط قيمة الفاتورة
                      </Typography>
                      <Typography variant="h6">
                        {formatPrice(stats.overview.averageInvoiceValue)}
                      </Typography>
                    </Grid>
                  </Grid>
                )}
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  الفواتير الحديثة
                </Typography>
                {stats.recentInvoices && stats.recentInvoices.length > 0 ? (
                  <Box>
                    {stats.recentInvoices.slice(0, 5).map((invoice) => (
                      <Box
                        key={invoice.id}
                        display="flex"
                        justifyContent="space-between"
                        alignItems="center"
                        py={1}
                      >
                        <Box>
                          <Typography variant="body2">
                            {invoice.invoiceNumber}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            {invoice.company.name}
                          </Typography>
                        </Box>
                        <Box textAlign="right">
                          <Typography variant="body2">
                            {formatPrice(invoice.totalAmount, invoice.currency)}
                          </Typography>
                          <Chip
                            label={getStatusText(invoice.status)}
                            color={getStatusColor(invoice.status)}
                            size="small"
                          />
                        </Box>
                      </Box>
                    ))}
                  </Box>
                ) : (
                  <Typography variant="body2" color="text.secondary">
                    لا توجد فواتير حديثة
                  </Typography>
                )}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Create Invoice Dialog */}
      <Dialog
        open={createDialogOpen}
        onClose={() => setCreateDialogOpen(false)}
        maxWidth="lg"
        fullWidth
      >
        <DialogTitle>إنشاء فاتورة جديدة</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="معرف الشركة"
                value={formData.companyId}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    companyId: e.target.value,
                  }))
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="معرف الاشتراك (اختياري)"
                value={formData.subscriptionId}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    subscriptionId: e.target.value,
                  }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>نوع الفاتورة</InputLabel>
                <Select
                  value={formData.type}
                  onChange={(e) =>
                    setFormData((prev) => ({ ...prev, type: e.target.value }))
                  }
                  label="نوع الفاتورة"
                >
                  <MenuItem value="SUBSCRIPTION">اشتراك</MenuItem>
                  <MenuItem value="ONE_TIME">مرة واحدة</MenuItem>
                  <MenuItem value="UPGRADE">ترقية</MenuItem>
                  <MenuItem value="DOWNGRADE">تخفيض</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="تاريخ الاستحقاق"
                type="date"
                value={formData.dueDate}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, dueDate: e.target.value }))
                }
                InputLabelProps={{ shrink: true }}
                required
              />
            </Grid>

            {/* Invoice Items */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                عناصر الفاتورة
              </Typography>
              {formData.items.map((item, index) => (
                <Grid container spacing={2} key={index} sx={{ mb: 2 }}>
                  <Grid item xs={12} md={4}>
                    <TextField
                      fullWidth
                      label="الوصف"
                      value={item.description}
                      onChange={(e) =>
                        updateInvoiceItem(index, "description", e.target.value)
                      }
                      required
                    />
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <TextField
                      fullWidth
                      label="الكمية"
                      type="number"
                      value={item.quantity}
                      onChange={(e) =>
                        updateInvoiceItem(
                          index,
                          "quantity",
                          parseFloat(e.target.value),
                        )
                      }
                      required
                    />
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <TextField
                      fullWidth
                      label="سعر الوحدة"
                      type="number"
                      value={item.unitPrice}
                      onChange={(e) =>
                        updateInvoiceItem(
                          index,
                          "unitPrice",
                          parseFloat(e.target.value),
                        )
                      }
                      required
                    />
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <TextField
                      fullWidth
                      label="الإجمالي"
                      value={item.quantity * item.unitPrice}
                      disabled
                    />
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <Button
                      variant="outlined"
                      color="error"
                      onClick={() => removeInvoiceItem(index)}
                      disabled={formData.items.length === 1}
                      fullWidth
                    >
                      حذف
                    </Button>
                  </Grid>
                </Grid>
              ))}
              <Button
                variant="outlined"
                onClick={addInvoiceItem}
                sx={{ mb: 2 }}
              >
                إضافة عنصر
              </Button>
            </Grid>

            {/* Totals */}
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="معدل الضريبة (%)"
                type="number"
                value={formData.taxRate}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    taxRate: parseFloat(e.target.value),
                  }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="مبلغ الخصم"
                type="number"
                value={formData.discountAmount}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    discountAmount: parseFloat(e.target.value),
                  }))
                }
              />
            </Grid>

            <Grid item xs={12}>
              <Box sx={{ p: 2, bgcolor: "grey.100", borderRadius: 1 }}>
                <Typography variant="body1">
                  المجموع الفرعي: {formatPrice(calculateSubtotal())}
                </Typography>
                <Typography variant="body1">
                  الضريبة ({formData.taxRate}%):{" "}
                  {formatPrice((calculateSubtotal() * formData.taxRate) / 100)}
                </Typography>
                <Typography variant="body1">
                  الخصم: {formatPrice(formData.discountAmount)}
                </Typography>
                <Typography variant="h6" color="primary">
                  الإجمالي: {formatPrice(calculateTotal())}
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="ملاحظات"
                multiline
                rows={3}
                value={formData.notes}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, notes: e.target.value }))
                }
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialogOpen(false)}>إلغاء</Button>
          <Button
            onClick={() => {
              /* handleCreateInvoice */
            }}
            variant="contained"
          >
            إنشاء
          </Button>
        </DialogActions>
      </Dialog>

      {/* View Invoice Dialog */}
      <Dialog
        open={viewDialogOpen}
        onClose={() => setViewDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>تفاصيل الفاتورة</DialogTitle>
        <DialogContent>
          {selectedInvoice && (
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">رقم الفاتورة</Typography>
                <Typography variant="body1">
                  {selectedInvoice.invoiceNumber}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">الشركة</Typography>
                <Typography variant="body1">
                  {selectedInvoice.company.name}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">الحالة</Typography>
                <Chip
                  label={getStatusText(selectedInvoice.status)}
                  color={getStatusColor(selectedInvoice.status)}
                  size="small"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">المبلغ الإجمالي</Typography>
                <Typography variant="h6" color="primary">
                  {formatPrice(
                    selectedInvoice.totalAmount,
                    selectedInvoice.currency,
                  )}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">تاريخ الإصدار</Typography>
                <Typography variant="body1">
                  {formatDate(selectedInvoice.issueDate)}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">تاريخ الاستحقاق</Typography>
                <Typography variant="body1">
                  {formatDate(selectedInvoice.dueDate)}
                </Typography>
              </Grid>
              {selectedInvoice.notes && (
                <Grid item xs={12}>
                  <Typography variant="subtitle2">ملاحظات</Typography>
                  <Typography variant="body1">
                    {selectedInvoice.notes}
                  </Typography>
                </Grid>
              )}

              {/* Invoice Items */}
              <Grid item xs={12}>
                <Typography variant="h6" gutterBottom>
                  عناصر الفاتورة
                </Typography>
                <TableContainer component={Paper}>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell>الوصف</TableCell>
                        <TableCell>الكمية</TableCell>
                        <TableCell>سعر الوحدة</TableCell>
                        <TableCell>الإجمالي</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {selectedInvoice.items?.map((item, index) => (
                        <TableRow key={index}>
                          <TableCell>{item.description}</TableCell>
                          <TableCell>{item.quantity}</TableCell>
                          <TableCell>
                            {formatPrice(
                              item.unitPrice,
                              selectedInvoice.currency,
                            )}
                          </TableCell>
                          <TableCell>
                            {formatPrice(
                              item.totalPrice,
                              selectedInvoice.currency,
                            )}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </Grid>

              {/* Payments */}
              {selectedInvoice.payments &&
                selectedInvoice.payments.length > 0 && (
                  <Grid item xs={12}>
                    <Typography variant="h6" gutterBottom>
                      المدفوعات
                    </Typography>
                    {selectedInvoice.payments.map((payment, index) => (
                      <Box
                        key={index}
                        sx={{
                          p: 1,
                          border: 1,
                          borderColor: "grey.300",
                          borderRadius: 1,
                          mb: 1,
                        }}
                      >
                        <Typography variant="body2">
                          المبلغ:{" "}
                          {formatPrice(
                            payment.amount,
                            selectedInvoice.currency,
                          )}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          الطريقة: {payment.method} | التاريخ:{" "}
                          {payment.paidAt
                            ? formatDate(payment.paidAt)
                            : "غير محدد"}
                        </Typography>
                      </Box>
                    ))}
                  </Grid>
                )}
            </Grid>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setViewDialogOpen(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default SuperAdminInvoices;

import React, { useState, useEffect } from "react";
import tokenManager from "../utils/tokenManager";
import { buildApiUrl } from "../utils/urlHelper";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Button,
  TextField,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Tooltip,
  Alert,
  CircularProgress,
  Pagination,
} from "@mui/material";
import {
  Add as AddIcon,
  Visibility as ViewIcon,
  Search as SearchIcon,
  FilterList as FilterIcon,
  Receipt as ReceiptIcon,
  Business as BusinessIcon,
  TrendingUp as TrendingUpIcon,
  AttachMoney as MoneyIcon,
  CreditCard as CreditCardIcon,
  AccountBalance as BankIcon,
} from "@mui/icons-material";
import { useNavigate, useSearchParams } from "react-router-dom";

const SuperAdminPayments = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const getAccessToken = () => tokenManager.getAccessToken();
  const getAuthHeaders = (additionalHeaders = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);
  const [payments, setPayments] = useState([]);
  const [stats, setStats] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  const [filters, setFilters] = useState({
    search: "",
    status: "",
    method: "",
    dateFrom: "",
    dateTo: "",
    sortBy: "createdAt",
    sortOrder: "desc",
  });

  // Dialog states
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [selectedPayment, setSelectedPayment] = useState(null);

  // Form data for recording payment
  const [formData, setFormData] = useState({
    companyId: "",
    invoiceId: "",
    subscriptionId: "",
    amount: "",
    currency: "EGP",
    method: "BANK_TRANSFER",
    gateway: "",
    transactionId: "",
    notes: "",
  });

  useEffect(() => {
    fetchPayments();
  }, [page, filters]);

  // Separate effect for URL params to avoid infinite loop
  useEffect(() => {
    const invoiceId = searchParams.get("invoice");
    const subscriptionId = searchParams.get("subscription");
    if (invoiceId && !filters.invoiceId) {
      setFilters((prev) => ({ ...prev, invoiceId }));
    }
    if (subscriptionId && !filters.subscriptionId) {
      setFilters((prev) => ({ ...prev, subscriptionId }));
    }
  }, [searchParams]);

  const fetchPayments = async () => {
    try {
      setLoading(true);
      const token = getAccessToken();

      // Check if token exists
      if (!token) {
        // Redirect to login if no token
        navigate("/auth/login");
        return;
      }

      const queryParams = new URLSearchParams({
        page: page.toString(),
        limit: "10",
        ...filters,
      });

      const response = await fetch(
        buildApiUrl(`admin/payments?${queryParams}`),
        {
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
        },
      );

      // Handle authentication errors
      if (response.status === 401 || response.status === 403) {
        // Clear local storage and redirect to login
        tokenManager.clearTokens();
        navigate("/auth/login");
        return;
      }

      const data = await response.json();

      if (data.success) {
        setPayments(data.data.payments);
        setStats(data.data.stats);
        setTotalPages(data.data.pagination.pages);
      } else {
        setError(data.message || "خطأ في جلب البيانات");
      }
    } catch (error) {
      console.error("Error fetching payments:", error);
      setError("خطأ في الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (field, value) => {
    setFilters((prev) => ({
      ...prev,
      [field]: value,
    }));
    setPage(1);
  };

  const getStatusColor = (status) => {
    const colors = {
      PENDING: "warning",
      COMPLETED: "success",
      FAILED: "error",
      CANCELLED: "error",
      REFUNDED: "info",
    };
    return colors[status] || "default";
  };

  const getStatusText = (status) => {
    const texts = {
      PENDING: "معلق",
      COMPLETED: "مكتمل",
      FAILED: "فاشل",
      CANCELLED: "ملغي",
      REFUNDED: "مسترد",
    };
    return texts[status] || status;
  };

  const getMethodText = (method) => {
    const texts = {
      CREDIT_CARD: "بطاقة ائتمان",
      DEBIT_CARD: "بطاقة خصم",
      BANK_TRANSFER: "تحويل بنكي",
      PAYPAL: "باي بال",
      STRIPE: "سترايب",
      CASH: "نقدي",
      CHECK: "شيك",
    };
    return texts[method] || method;
  };

  const getMethodIcon = (method) => {
    const icons = {
      CREDIT_CARD: <CreditCardIcon />,
      DEBIT_CARD: <CreditCardIcon />,
      BANK_TRANSFER: <BankIcon />,
      PAYPAL: <MoneyIcon />,
      STRIPE: <CreditCardIcon />,
      CASH: <MoneyIcon />,
      CHECK: <ReceiptIcon />,
    };
    return icons[method] || <MoneyIcon />;
  };

  const formatPrice = (price, currency = "EGP") => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: currency,
    }).format(price);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("ar-EG");
  };

  const formatDateTime = (dateString) => {
    return new Date(dateString).toLocaleString("ar-EG");
  };

  const handleCreatePayment = async () => {
    try {
      const token = getAccessToken();

      // Check if token exists
      if (!token) {
        // Redirect to login if no token
        navigate("/auth/login");
        return;
      }

      const response = await fetch(buildApiUrl("admin/payments"), {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          ...formData,
          amount: parseFloat(formData.amount),
        }),
      });

      // Handle authentication errors
      if (response.status === 401 || response.status === 403) {
        // Clear local storage and redirect to login
        tokenManager.clearTokens();
        navigate("/auth/login");
        return;
      }

      const data = await response.json();

      if (data.success) {
        setCreateDialogOpen(false);
        fetchPayments();
        setFormData({
          companyId: "",
          invoiceId: "",
          subscriptionId: "",
          amount: "",
          currency: "EGP",
          method: "BANK_TRANSFER",
          gateway: "",
          transactionId: "",
          notes: "",
        });
      } else {
        setError(data.message || "خطأ في تسجيل المدفوعة");
      }
    } catch (error) {
      console.error("Error creating payment:", error);
      setError("خطأ في الاتصال بالخادم");
    }
  };

  if (loading && payments.length === 0) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="400px"
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h4" component="h1">
          إدارة المدفوعات
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setCreateDialogOpen(true)}
        >
          تسجيل مدفوعة
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError("")}>
          {error}
        </Alert>
      )}

      {/* Statistics Cards */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                إجمالي المدفوعات
              </Typography>
              <Typography variant="h4">{stats.total || 0}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                المدفوعات المكتملة
              </Typography>
              <Typography variant="h4" color="success.main">
                {stats.byStatus?.COMPLETED?.count || 0}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                المدفوعات المعلقة
              </Typography>
              <Typography variant="h4" color="warning.main">
                {stats.byStatus?.PENDING?.count || 0}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                إجمالي المبالغ
              </Typography>
              <Typography variant="h4" color="primary.main">
                {formatPrice(stats.byStatus?.COMPLETED?.amount || 0)}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Filters */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2} alignItems="center">
            <Grid item xs={12} md={3}>
              <TextField
                fullWidth
                label="البحث"
                value={filters.search}
                onChange={(e) => handleFilterChange("search", e.target.value)}
                InputProps={{
                  startAdornment: (
                    <SearchIcon sx={{ mr: 1, color: "text.secondary" }} />
                  ),
                }}
              />
            </Grid>
            <Grid item xs={12} md={2}>
              <FormControl fullWidth>
                <InputLabel>الحالة</InputLabel>
                <Select
                  value={filters.status}
                  onChange={(e) => handleFilterChange("status", e.target.value)}
                  label="الحالة"
                >
                  <MenuItem value="">الكل</MenuItem>
                  <MenuItem value="PENDING">معلق</MenuItem>
                  <MenuItem value="COMPLETED">مكتمل</MenuItem>
                  <MenuItem value="FAILED">فاشل</MenuItem>
                  <MenuItem value="CANCELLED">ملغي</MenuItem>
                  <MenuItem value="REFUNDED">مسترد</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={2}>
              <FormControl fullWidth>
                <InputLabel>طريقة الدفع</InputLabel>
                <Select
                  value={filters.method}
                  onChange={(e) => handleFilterChange("method", e.target.value)}
                  label="طريقة الدفع"
                >
                  <MenuItem value="">الكل</MenuItem>
                  <MenuItem value="CREDIT_CARD">بطاقة ائتمان</MenuItem>
                  <MenuItem value="BANK_TRANSFER">تحويل بنكي</MenuItem>
                  <MenuItem value="PAYPAL">باي بال</MenuItem>
                  <MenuItem value="CASH">نقدي</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={2}>
              <TextField
                fullWidth
                label="من تاريخ"
                type="date"
                value={filters.dateFrom}
                onChange={(e) => handleFilterChange("dateFrom", e.target.value)}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} md={2}>
              <TextField
                fullWidth
                label="إلى تاريخ"
                type="date"
                value={filters.dateTo}
                onChange={(e) => handleFilterChange("dateTo", e.target.value)}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Payments Table */}
      <Card>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>رقم المدفوعة</TableCell>
                <TableCell>الشركة</TableCell>
                <TableCell>المبلغ</TableCell>
                <TableCell>طريقة الدفع</TableCell>
                <TableCell>الحالة</TableCell>
                <TableCell>تاريخ الدفع</TableCell>
                <TableCell>الإجراءات</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {payments.map((payment) => (
                <TableRow key={payment.id}>
                  <TableCell>
                    <Typography variant="subtitle2">
                      {payment.paymentNumber}
                    </Typography>
                    {payment.transactionId && (
                      <Typography variant="caption" color="text.secondary">
                        {payment.transactionId}
                      </Typography>
                    )}
                  </TableCell>
                  <TableCell>
                    <Box>
                      <Typography variant="subtitle2">
                        {payment.company.name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {payment.company.email}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Typography variant="subtitle1" color="primary">
                      {formatPrice(payment.amount, payment.currency)}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Box display="flex" alignItems="center" gap={1}>
                      {getMethodIcon(payment.method)}
                      <Typography variant="body2">
                        {getMethodText(payment.method)}
                      </Typography>
                    </Box>
                    {payment.gateway && (
                      <Typography
                        variant="caption"
                        color="text.secondary"
                        display="block"
                      >
                        {payment.gateway}
                      </Typography>
                    )}
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={getStatusText(payment.status)}
                      color={getStatusColor(payment.status)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    {payment.paidAt
                      ? formatDateTime(payment.paidAt)
                      : formatDateTime(payment.createdAt)}
                  </TableCell>
                  <TableCell>
                    <Box display="flex" gap={1}>
                      <Tooltip title="عرض التفاصيل">
                        <IconButton
                          size="small"
                          onClick={() => {
                            setSelectedPayment(payment);
                            setViewDialogOpen(true);
                          }}
                        >
                          <ViewIcon />
                        </IconButton>
                      </Tooltip>
                      {payment.invoice && (
                        <Tooltip title="عرض الفاتورة">
                          <IconButton
                            size="small"
                            onClick={() =>
                              navigate(
                                `/super-admin/invoices?invoice=${payment.invoice.id}`,
                              )
                            }
                          >
                            <ReceiptIcon />
                          </IconButton>
                        </Tooltip>
                      )}
                      {payment.subscription && (
                        <Tooltip title="عرض الاشتراك">
                          <IconButton
                            size="small"
                            onClick={() =>
                              navigate(
                                `/super-admin/subscriptions?subscription=${payment.subscription.id}`,
                              )
                            }
                          >
                            <BusinessIcon />
                          </IconButton>
                        </Tooltip>
                      )}
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {totalPages > 1 && (
          <Box display="flex" justifyContent="center" p={2}>
            <Pagination
              count={totalPages}
              page={page}
              onChange={(e, newPage) => setPage(newPage)}
              color="primary"
            />
          </Box>
        )}
      </Card>

      {/* Create Payment Dialog */}
      <Dialog
        open={createDialogOpen}
        onClose={() => setCreateDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>تسجيل مدفوعة جديدة</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="معرف الشركة"
                value={formData.companyId}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    companyId: e.target.value,
                  }))
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="معرف الفاتورة (اختياري)"
                value={formData.invoiceId}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    invoiceId: e.target.value,
                  }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="معرف الاشتراك (اختياري)"
                value={formData.subscriptionId}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    subscriptionId: e.target.value,
                  }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="المبلغ"
                type="number"
                value={formData.amount}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, amount: e.target.value }))
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>العملة</InputLabel>
                <Select
                  value={formData.currency}
                  onChange={(e) =>
                    setFormData((prev) => ({
                      ...prev,
                      currency: e.target.value,
                    }))
                  }
                  label="العملة"
                >
                  <MenuItem value="EGP">جنيه مصري</MenuItem>
                  <MenuItem value="USD">دولار أمريكي</MenuItem>
                  <MenuItem value="SAR">ريال سعودي</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>طريقة الدفع</InputLabel>
                <Select
                  value={formData.method}
                  onChange={(e) =>
                    setFormData((prev) => ({ ...prev, method: e.target.value }))
                  }
                  label="طريقة الدفع"
                >
                  <MenuItem value="BANK_TRANSFER">تحويل بنكي</MenuItem>
                  <MenuItem value="CREDIT_CARD">بطاقة ائتمان</MenuItem>
                  <MenuItem value="DEBIT_CARD">بطاقة خصم</MenuItem>
                  <MenuItem value="PAYPAL">باي بال</MenuItem>
                  <MenuItem value="CASH">نقدي</MenuItem>
                  <MenuItem value="CHECK">شيك</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="بوابة الدفع (اختياري)"
                value={formData.gateway}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, gateway: e.target.value }))
                }
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="معرف المعاملة"
                value={formData.transactionId}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    transactionId: e.target.value,
                  }))
                }
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="ملاحظات"
                multiline
                rows={3}
                value={formData.notes}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, notes: e.target.value }))
                }
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialogOpen(false)}>إلغاء</Button>
          <Button onClick={handleCreatePayment} variant="contained">
            تسجيل
          </Button>
        </DialogActions>
      </Dialog>

      {/* View Payment Dialog */}
      <Dialog
        open={viewDialogOpen}
        onClose={() => setViewDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>تفاصيل المدفوعة</DialogTitle>
        <DialogContent>
          {selectedPayment && (
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">رقم المدفوعة</Typography>
                <Typography variant="body1">
                  {selectedPayment.paymentNumber}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">الشركة</Typography>
                <Typography variant="body1">
                  {selectedPayment.company.name}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">المبلغ</Typography>
                <Typography variant="h6" color="primary">
                  {formatPrice(
                    selectedPayment.amount,
                    selectedPayment.currency,
                  )}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">طريقة الدفع</Typography>
                <Box display="flex" alignItems="center" gap={1}>
                  {getMethodIcon(selectedPayment.method)}
                  <Typography variant="body1">
                    {getMethodText(selectedPayment.method)}
                  </Typography>
                </Box>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">الحالة</Typography>
                <Chip
                  label={getStatusText(selectedPayment.status)}
                  color={getStatusColor(selectedPayment.status)}
                  size="small"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="subtitle2">تاريخ الدفع</Typography>
                <Typography variant="body1">
                  {selectedPayment.paidAt
                    ? formatDateTime(selectedPayment.paidAt)
                    : "غير محدد"}
                </Typography>
              </Grid>
              {selectedPayment.gateway && (
                <Grid item xs={12} md={6}>
                  <Typography variant="subtitle2">بوابة الدفع</Typography>
                  <Typography variant="body1">
                    {selectedPayment.gateway}
                  </Typography>
                </Grid>
              )}
              {selectedPayment.transactionId && (
                <Grid item xs={12} md={6}>
                  <Typography variant="subtitle2">معرف المعاملة</Typography>
                  <Typography variant="body1">
                    {selectedPayment.transactionId}
                  </Typography>
                </Grid>
              )}
              {selectedPayment.invoice && (
                <Grid item xs={12}>
                  <Typography variant="subtitle2">الفاتورة المرتبطة</Typography>
                  <Box
                    sx={{
                      p: 1,
                      border: 1,
                      borderColor: "grey.300",
                      borderRadius: 1,
                    }}
                  >
                    <Typography variant="body2">
                      رقم الفاتورة: {selectedPayment.invoice.invoiceNumber}
                    </Typography>
                    <Typography variant="body2">
                      مبلغ الفاتورة:{" "}
                      {formatPrice(
                        selectedPayment.invoice.totalAmount,
                        selectedPayment.currency,
                      )}
                    </Typography>
                  </Box>
                </Grid>
              )}
              {selectedPayment.metadata?.notes && (
                <Grid item xs={12}>
                  <Typography variant="subtitle2">ملاحظات</Typography>
                  <Typography variant="body1">
                    {selectedPayment.metadata.notes}
                  </Typography>
                </Grid>
              )}
            </Grid>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setViewDialogOpen(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default SuperAdminPayments;

import React, { useState, useEffect } from "react";
import tokenManager from "../utils/tokenManager";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Button,
  TextField,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Tooltip,
  Alert,
  CircularProgress,
  Pagination,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Cancel as CancelIcon,
  Refresh as RefreshIcon,
  Search as SearchIcon,
  FilterList as FilterIcon,
  Receipt as ReceiptIcon,
  Payment as PaymentIcon,
  Autorenew as RenewIcon,
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

import { buildApiUrl } from "../utils/urlHelper";

const SuperAdminSubscriptions = () => {
  const navigate = useNavigate();
  const getAccessToken = () => tokenManager.getAccessToken();
  const getAuthHeaders = (additionalHeaders = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);
  const [subscriptions, setSubscriptions] = useState([]);
  const [stats, setStats] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [filters, setFilters] = useState({
    search: "",
    status: "",
    planType: "",
    sortBy: "createdAt",
    sortOrder: "desc",
  });

  // Dialog states
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [cancelDialogOpen, setCancelDialogOpen] = useState(false);
  const [renewDialogOpen, setRenewDialogOpen] = useState(false);
  const [selectedSubscription, setSelectedSubscription] = useState(null);

  // Form data
  const [formData, setFormData] = useState({
    companyId: "",
    planType: "BASIC",
    billingCycle: "monthly",
    price: "",
    currency: "EGP",
    startDate: "",
    trialDays: 0,
    autoRenew: true,
  });

  const [cancelData, setCancelData] = useState({
    reason: "",
    immediate: false,
  });

  const [renewData, setRenewData] = useState({
    planType: "",
    price: "",
    billingCycle: "",
    immediate: false,
  });

  useEffect(() => {
    fetchSubscriptions();
  }, [page, filters]);

  const fetchSubscriptions = async () => {
    try {
      setLoading(true);
      const token = getAccessToken();

      const queryParams = new URLSearchParams({
        page: page.toString(),
        limit: "10",
        ...filters,
      });

      const response = await fetch(
        buildApiUrl(`admin/subscriptions?${queryParams}`),
        {
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
        },
      );

      const data = await response.json();

      if (data.success) {
        setSubscriptions(data.data.subscriptions);
        setStats(data.data.stats);
        setTotalPages(data.data.pagination.pages);
      } else {
        setError(data.message || "خطأ في جلب البيانات");
      }
    } catch (error) {
      console.error("Error fetching subscriptions:", error);
      setError("خطأ في الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (field, value) => {
    setFilters((prev) => ({
      ...prev,
      [field]: value,
    }));
    setPage(1);
  };

  const getStatusColor = (status) => {
    const colors = {
      ACTIVE: "success",
      TRIAL: "info",
      INACTIVE: "warning",
      CANCELLED: "error",
      EXPIRED: "error",
      SUSPENDED: "warning",
    };
    return colors[status] || "default";
  };

  const getStatusText = (status) => {
    const texts = {
      ACTIVE: "نشط",
      TRIAL: "تجريبي",
      INACTIVE: "غير نشط",
      CANCELLED: "ملغي",
      EXPIRED: "منتهي",
      SUSPENDED: "معلق",
    };
    return texts[status] || status;
  };

  const getPlanText = (planType) => {
    const texts = {
      BASIC: "أساسية",
      PRO: "احترافية",
      ENTERPRISE: "مؤسسية",
    };
    return texts[planType] || planType;
  };

  const formatPrice = (price, currency = "EGP") => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: currency,
    }).format(price);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("ar-EG");
  };

  const handleCreateSubscription = async () => {
    try {
      const token = getAccessToken();

      const response = await fetch(buildApiUrl("admin/subscriptions"), {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (data.success) {
        setCreateDialogOpen(false);
        fetchSubscriptions();
        setFormData({
          companyId: "",
          planType: "BASIC",
          billingCycle: "monthly",
          price: "",
          currency: "EGP",
          startDate: "",
          trialDays: 0,
          autoRenew: true,
        });
      } else {
        setError(data.message || "خطأ في إنشاء الاشتراك");
      }
    } catch (error) {
      console.error("Error creating subscription:", error);
      setError("خطأ في الاتصال بالخادم");
    }
  };

  const handleCancelSubscription = async () => {
    try {
      const token = getAccessToken();

      const response = await fetch(
        buildApiUrl(`admin/subscriptions/${selectedSubscription.id}/cancel`),
        {
          method: "POST",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
          body: JSON.stringify(cancelData),
        },
      );

      const data = await response.json();

      if (data.success) {
        setCancelDialogOpen(false);
        fetchSubscriptions();
        setCancelData({ reason: "", immediate: false });
      } else {
        setError(data.message || "خطأ في إلغاء الاشتراك");
      }
    } catch (error) {
      console.error("Error cancelling subscription:", error);
      setError("خطأ في الاتصال بالخادم");
    }
  };

  const handleRenewSubscription = async () => {
    try {
      const token = getAccessToken();

      const response = await fetch(
        buildApiUrl(`admin/subscriptions/${selectedSubscription.id}/renew`),
        {
          method: "POST",
          headers: getAuthHeaders({
            "Content-Type": "application/json",
          }),
          body: JSON.stringify({
            planType: renewData.planType || selectedSubscription.planType,
            price: renewData.price
              ? parseFloat(renewData.price)
              : selectedSubscription.price,
            billingCycle:
              renewData.billingCycle || selectedSubscription.billingCycle,
            immediate: renewData.immediate,
          }),
        },
      );

      const data = await response.json();

      if (data.success) {
        setRenewDialogOpen(false);
        fetchSubscriptions();
        setRenewData({
          planType: "",
          price: "",
          billingCycle: "",
          immediate: false,
        });
      } else {
        setError(data.message || "خطأ في تجديد الاشتراك");
      }
    } catch (error) {
      console.error("Error renewing subscription:", error);
      setError("خطأ في الاتصال بالخادم");
    }
  };

  if (loading && subscriptions.length === 0) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="400px"
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h4" component="h1">
          إدارة الاشتراكات
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setCreateDialogOpen(true)}
        >
          اشتراك جديد
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError("")}>
          {error}
        </Alert>
      )}

      {/* Statistics Cards */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid size={{ xs: 12, md: 3 }}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                إجمالي الاشتراكات
              </Typography>
              <Typography variant="h4">{stats.total || 0}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid size={{ xs: 12, md: 3 }}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                الاشتراكات النشطة
              </Typography>
              <Typography variant="h4" color="success.main">
                {stats.byStatus?.ACTIVE || 0}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid size={{ xs: 12, md: 3 }}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                الاشتراكات التجريبية
              </Typography>
              <Typography variant="h4" color="info.main">
                {stats.byStatus?.TRIAL || 0}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid size={{ xs: 12, md: 3 }}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                الإيرادات الشهرية
              </Typography>
              <Typography variant="h4" color="primary.main">
                {formatPrice(stats.monthlyRevenue || 0)}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Filters */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2} alignItems="center">
            <Grid size={{ xs: 12, md: 3 }}>
              <TextField
                fullWidth
                label="البحث"
                value={filters.search}
                onChange={(e) => handleFilterChange("search", e.target.value)}
                InputProps={{
                  startAdornment: (
                    <SearchIcon sx={{ mr: 1, color: "text.secondary" }} />
                  ),
                }}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <FormControl fullWidth>
                <InputLabel>الحالة</InputLabel>
                <Select
                  value={filters.status}
                  onChange={(e) => handleFilterChange("status", e.target.value)}
                  label="الحالة"
                >
                  <MenuItem value="">الكل</MenuItem>
                  <MenuItem value="ACTIVE">نشط</MenuItem>
                  <MenuItem value="TRIAL">تجريبي</MenuItem>
                  <MenuItem value="INACTIVE">غير نشط</MenuItem>
                  <MenuItem value="CANCELLED">ملغي</MenuItem>
                  <MenuItem value="EXPIRED">منتهي</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <FormControl fullWidth>
                <InputLabel>نوع الخطة</InputLabel>
                <Select
                  value={filters.planType}
                  onChange={(e) =>
                    handleFilterChange("planType", e.target.value)
                  }
                  label="نوع الخطة"
                >
                  <MenuItem value="">الكل</MenuItem>
                  <MenuItem value="BASIC">أساسية</MenuItem>
                  <MenuItem value="PRO">احترافية</MenuItem>
                  <MenuItem value="ENTERPRISE">مؤسسية</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 2 }}>
              <Button
                variant="outlined"
                startIcon={<RefreshIcon />}
                onClick={fetchSubscriptions}
                fullWidth
              >
                تحديث
              </Button>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Subscriptions Table */}
      <Card>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>الشركة</TableCell>
                <TableCell>نوع الخطة</TableCell>
                <TableCell>الحالة</TableCell>
                <TableCell>السعر</TableCell>
                <TableCell>تاريخ البداية</TableCell>
                <TableCell>التجديد التالي</TableCell>
                <TableCell>الإجراءات</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {subscriptions.map((subscription) => (
                <TableRow key={subscription.id}>
                  <TableCell>
                    <Box>
                      <Typography variant="subtitle2">
                        {subscription.company.name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {subscription.company.email}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={getPlanText(subscription.planType)}
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={getStatusText(subscription.status)}
                      color={getStatusColor(subscription.status)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    {formatPrice(subscription.price, subscription.currency)}
                    <Typography variant="caption" display="block">
                      {subscription.billingCycle === "monthly"
                        ? "شهري"
                        : "سنوي"}
                    </Typography>
                  </TableCell>
                  <TableCell>{formatDate(subscription.startDate)}</TableCell>
                  <TableCell>
                    {subscription.nextBillingDate
                      ? formatDate(subscription.nextBillingDate)
                      : "-"}
                  </TableCell>
                  <TableCell>
                    <Box display="flex" gap={1}>
                      <Tooltip title="عرض الفواتير">
                        <IconButton
                          size="small"
                          onClick={() =>
                            navigate(
                              `/super-admin/invoices?subscription=${subscription.id}`,
                            )
                          }
                        >
                          <ReceiptIcon />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="عرض المدفوعات">
                        <IconButton
                          size="small"
                          onClick={() =>
                            navigate(
                              `/super-admin/payments?subscription=${subscription.id}`,
                            )
                          }
                        >
                          <PaymentIcon />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="تعديل">
                        <IconButton
                          size="small"
                          onClick={() => {
                            setSelectedSubscription(subscription);
                            setEditDialogOpen(true);
                          }}
                        >
                          <EditIcon />
                        </IconButton>
                      </Tooltip>
                      {(subscription.status === "ACTIVE" ||
                        subscription.status === "EXPIRED") && (
                        <Tooltip title="تجديد">
                          <IconButton
                            size="small"
                            color="primary"
                            onClick={() => {
                              setSelectedSubscription(subscription);
                              setRenewData({
                                planType: subscription.planType,
                                price: subscription.price.toString(),
                                billingCycle: subscription.billingCycle,
                                immediate: false,
                              });
                              setRenewDialogOpen(true);
                            }}
                          >
                            <RenewIcon />
                          </IconButton>
                        </Tooltip>
                      )}
                      {subscription.status !== "CANCELLED" && (
                        <Tooltip title="إلغاء">
                          <IconButton
                            size="small"
                            color="error"
                            onClick={() => {
                              setSelectedSubscription(subscription);
                              setCancelDialogOpen(true);
                            }}
                          >
                            <CancelIcon />
                          </IconButton>
                        </Tooltip>
                      )}
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {totalPages > 1 && (
          <Box display="flex" justifyContent="center" p={2}>
            <Pagination
              count={totalPages}
              page={page}
              onChange={(e, newPage) => setPage(newPage)}
              color="primary"
            />
          </Box>
        )}
      </Card>

      {/* Create Subscription Dialog */}
      <Dialog
        open={createDialogOpen}
        onClose={() => setCreateDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>إنشاء اشتراك جديد</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid size={12}>
              <TextField
                fullWidth
                label="معرف الشركة"
                value={formData.companyId}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    companyId: e.target.value,
                  }))
                }
                required
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl fullWidth>
                <InputLabel>نوع الخطة</InputLabel>
                <Select
                  value={formData.planType}
                  onChange={(e) =>
                    setFormData((prev) => ({
                      ...prev,
                      planType: e.target.value,
                    }))
                  }
                  label="نوع الخطة"
                >
                  <MenuItem value="BASIC">أساسية</MenuItem>
                  <MenuItem value="PRO">احترافية</MenuItem>
                  <MenuItem value="ENTERPRISE">مؤسسية</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl fullWidth>
                <InputLabel>دورة الفوترة</InputLabel>
                <Select
                  value={formData.billingCycle}
                  onChange={(e) =>
                    setFormData((prev) => ({
                      ...prev,
                      billingCycle: e.target.value,
                    }))
                  }
                  label="دورة الفوترة"
                >
                  <MenuItem value="monthly">شهري</MenuItem>
                  <MenuItem value="yearly">سنوي</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="السعر"
                type="number"
                value={formData.price}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    price: parseFloat(e.target.value),
                  }))
                }
                required
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl fullWidth>
                <InputLabel>العملة</InputLabel>
                <Select
                  value={formData.currency}
                  onChange={(e) =>
                    setFormData((prev) => ({
                      ...prev,
                      currency: e.target.value,
                    }))
                  }
                  label="العملة"
                >
                  <MenuItem value="EGP">جنيه مصري</MenuItem>
                  <MenuItem value="USD">دولار أمريكي</MenuItem>
                  <MenuItem value="SAR">ريال سعودي</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="تاريخ البداية"
                type="date"
                value={formData.startDate}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    startDate: e.target.value,
                  }))
                }
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="أيام التجربة"
                type="number"
                value={formData.trialDays}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    trialDays: parseInt(e.target.value),
                  }))
                }
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialogOpen(false)}>إلغاء</Button>
          <Button onClick={handleCreateSubscription} variant="contained">
            إنشاء
          </Button>
        </DialogActions>
      </Dialog>

      {/* Renew Subscription Dialog */}
      <Dialog
        open={renewDialogOpen}
        onClose={() => setRenewDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>تجديد الاشتراك</DialogTitle>
        <DialogContent>
          <Typography variant="body1" sx={{ mb: 3 }}>
            تجديد اشتراك {selectedSubscription?.company?.name}
          </Typography>
          <Grid container spacing={2}>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl fullWidth>
                <InputLabel>نوع الخطة</InputLabel>
                <Select
                  value={renewData.planType}
                  onChange={(e) =>
                    setRenewData((prev) => ({
                      ...prev,
                      planType: e.target.value,
                    }))
                  }
                  label="نوع الخطة"
                >
                  <MenuItem value="BASIC">أساسية (2,500 ج.م)</MenuItem>
                  <MenuItem value="PRO">احترافية (7,500 ج.م)</MenuItem>
                  <MenuItem value="ENTERPRISE">مؤسسية (15,000 ج.م)</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl fullWidth>
                <InputLabel>دورة الفوترة</InputLabel>
                <Select
                  value={renewData.billingCycle}
                  onChange={(e) =>
                    setRenewData((prev) => ({
                      ...prev,
                      billingCycle: e.target.value,
                    }))
                  }
                  label="دورة الفوترة"
                >
                  <MenuItem value="monthly">شهري</MenuItem>
                  <MenuItem value="yearly">سنوي (خصم 10%)</MenuItem>
                  <MenuItem value="quarterly">ربع سنوي</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="السعر المخصص (اختياري)"
                type="number"
                value={renewData.price}
                onChange={(e) =>
                  setRenewData((prev) => ({ ...prev, price: e.target.value }))
                }
                helperText="اتركه فارغاً لاستخدام السعر الافتراضي"
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl component="fieldset" sx={{ mt: 2 }}>
                <label>
                  <input
                    type="checkbox"
                    checked={renewData.immediate}
                    onChange={(e) =>
                      setRenewData((prev) => ({
                        ...prev,
                        immediate: e.target.checked,
                      }))
                    }
                  />
                  تجديد فوري (بدلاً من انتظار تاريخ التجديد)
                </label>
              </FormControl>
            </Grid>
            <Grid size={12}>
              <Box sx={{ p: 2, bgcolor: "info.light", borderRadius: 1 }}>
                <Typography variant="body2" color="info.contrastText">
                  <strong>ملاحظة:</strong> سيتم إنشاء فاتورة جديدة وتحديث تاريخ
                  التجديد التالي تلقائياً
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setRenewDialogOpen(false)}>إلغاء</Button>
          <Button
            onClick={handleRenewSubscription}
            variant="contained"
            color="primary"
          >
            تجديد الاشتراك
          </Button>
        </DialogActions>
      </Dialog>

      {/* Cancel Subscription Dialog */}
      <Dialog
        open={cancelDialogOpen}
        onClose={() => setCancelDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>إلغاء الاشتراك</DialogTitle>
        <DialogContent>
          <Typography variant="body1" sx={{ mb: 2 }}>
            هل أنت متأكد من إلغاء اشتراك {selectedSubscription?.company?.name}؟
          </Typography>
          <TextField
            fullWidth
            label="سبب الإلغاء"
            multiline
            rows={3}
            value={cancelData.reason}
            onChange={(e) =>
              setCancelData((prev) => ({ ...prev, reason: e.target.value }))
            }
            sx={{ mb: 2 }}
          />
          <FormControl component="fieldset">
            <label>
              <input
                type="checkbox"
                checked={cancelData.immediate}
                onChange={(e) =>
                  setCancelData((prev) => ({
                    ...prev,
                    immediate: e.target.checked,
                  }))
                }
              />
              إلغاء فوري (بدلاً من انتظار نهاية الفترة)
            </label>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCancelDialogOpen(false)}>إلغاء</Button>
          <Button
            onClick={handleCancelSubscription}
            variant="contained"
            color="error"
          >
            تأكيد الإلغاء
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default SuperAdminSubscriptions;

import React, { useState } from "react";
import { buildApiUrl } from "../utils/urlHelper";

const TestFacebookPage: React.FC = () => {
  const [recipientId, setRecipientId] = useState("");
  const [message, setMessage] = useState("");
  const [pageId, setPageId] = useState("");
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const testSendMessage = async () => {
    setLoading(true);
    setResult(null);

    try {
      const response = await fetch(buildApiUrl("/test-facebook/test-send"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          recipientId,
          message,
          pageId: pageId || null,
        }),
      });

      const data = await response.json();
      setResult(data);
    } catch (error) {
      setResult({
        success: false,
        error: error.message,
      });
    } finally {
      setLoading(false);
    }
  };

  const testWebhook = async () => {
    setLoading(true);
    setResult(null);

    try {
      const webhookData = {
        sender: { id: recipientId },
        recipient: { id: pageId || "test-page" },
        message: { text: message },
      };

      const response = await fetch(buildApiUrl("/test-facebook/test-webhook"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(webhookData),
      });

      const data = await response.json();
      setResult(data);
    } catch (error) {
      setResult({
        success: false,
        error: error.message,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 w-full">
      <h1 className="text-3xl font-bold mb-6">🧪 Facebook Test Page</h1>

      <div className="bg-white rounded-lg shadow-md p-6 mb-6">
        <h2 className="text-xl font-semibold mb-4">
          Test Facebook Message Sending
        </h2>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Recipient ID (Facebook User ID)
            </label>
            <input
              type="text"
              value={recipientId}
              onChange={(e) => setRecipientId(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="Enter Facebook User ID"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Message
            </label>
            <textarea
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              rows={3}
              placeholder="Enter message to send"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Page ID (Optional)
            </label>
            <input
              type="text"
              value={pageId}
              onChange={(e) => setPageId(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="Enter Facebook Page ID (optional)"
            />
          </div>

          <div className="flex space-x-4">
            <button
              onClick={testSendMessage}
              disabled={loading || !recipientId || !message}
              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {loading ? "Testing..." : "Test Send Message"}
            </button>

            <button
              onClick={testWebhook}
              disabled={loading || !recipientId || !message}
              className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {loading ? "Testing..." : "Test Webhook Processing"}
            </button>
          </div>
        </div>
      </div>

      {result && (
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">Test Results</h2>

          <div
            className={`p-4 rounded-md ${result.success ? "bg-green-50 border border-green-200" : "bg-red-50 border border-red-200"}`}
          >
            <h3
              className={`font-semibold ${result.success ? "text-green-800" : "text-red-800"}`}
            >
              {result.success ? "✅ Success" : "❌ Failed"}
            </h3>
            <pre className="mt-2 text-sm overflow-auto max-h-96 bg-gray-100 p-3 rounded">
              {JSON.stringify(result, null, 2)}
            </pre>
          </div>
        </div>
      )}

      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mt-6">
        <h3 className="font-semibold text-yellow-800 mb-2">📋 Instructions:</h3>
        <ul className="text-sm text-yellow-700 space-y-1">
          <li>
            • <strong>Test Send Message:</strong> Tests direct Facebook API
            sending
          </li>
          <li>
            • <strong>Test Webhook Processing:</strong> Tests full webhook
            processing with AI
          </li>
          <li>
            • Check the browser console and backend logs for detailed
            diagnostics
          </li>
          <li>• Use real Facebook User IDs for actual testing</li>
        </ul>
      </div>
    </div>
  );
};

export default TestFacebookPage;

import React, { useState, useEffect } from "react";
import { buildApiUrl } from "../utils/urlHelper";

const TestMinimal: React.FC = () => {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    console.log("🧪 [TestMinimal] Component mounted");

    // Get company identifier from URL or auth cache
    const params = new URLSearchParams(window.location.search);
    const companyIdFromQuery = params.get("companyId")?.trim();

    let companyId =
      companyIdFromQuery || localStorage.getItem("storefront_companyId") || "";

    if (!companyId) {
      try {
        const rawUser = localStorage.getItem("user");
        if (rawUser) {
          const parsed = JSON.parse(rawUser) as {
            companyId?: string;
            company?: { id?: string; slug?: string } | null;
          };

          companyId =
            parsed.company?.slug?.trim() ||
            parsed.companyId?.trim() ||
            parsed.company?.id?.trim() ||
            "";
        }
      } catch {
        companyId = "";
      }
    }

    console.log("🧪 [TestMinimal] Company ID:", companyId);

    if (!companyId) {
      setData({
        success: false,
        message: "No company identifier available",
      });
      setLoading(false);
      return;
    }

    // Fetch storefront public settings using the current company identifier.
    const url = buildApiUrl(
      `public/storefront/settings?companyId=${encodeURIComponent(companyId)}`,
    );

    console.log("🧪 [TestMinimal] Fetching:", url);

    fetch(url)
      .then(async (response) => {
        console.log("🧪 [TestMinimal] Response status:", response.status);
        const contentType = response.headers.get("content-type") || "";

        if (!response.ok) {
          const fallbackText = await response.text().catch(() => "");
          throw new Error(
            `HTTP ${response.status}: ${fallbackText.slice(0, 120) || "Request failed"}`,
          );
        }

        if (!contentType.includes("application/json")) {
          const fallbackText = await response.text().catch(() => "");
          throw new Error(
            `Expected JSON but received ${contentType || "unknown"}: ${fallbackText.slice(0, 120)}`,
          );
        }

        return response.json();
      })
      .then((result) => {
        console.log("🧪 [TestMinimal] Data received:", result);
        setData(result);
        setLoading(false);
      })
      .catch((error) => {
        setData({
          success: false,
          message: error instanceof Error ? error.message : String(error),
        });
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div
        style={{
          minHeight: "100vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: "#f3f4f6",
        }}
      >
        <div style={{ textAlign: "center" }}>
          <h1 style={{ fontSize: "24px", marginBottom: "16px" }}>
            ⏳ جاري التحميل...
          </h1>
        </div>
      </div>
    );
  }

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: "#f3f4f6",
        padding: "40px 20px",
      }}
    >
      <div
        style={{
          maxWidth: "800px",
          margin: "0 auto",
          backgroundColor: "white",
          borderRadius: "12px",
          padding: "40px",
          boxShadow: "0 4px 6px rgba(0,0,0,0.1)",
        }}
      >
        <div
          style={{
            backgroundColor: "#10b981",
            color: "white",
            padding: "20px",
            borderRadius: "8px",
            marginBottom: "30px",
            textAlign: "center",
          }}
        >
          <h1 style={{ fontSize: "32px", margin: "0 0 10px 0" }}>✅ نجح!</h1>
          <p style={{ margin: 0, fontSize: "18px" }}>
            الصفحة تعمل بدون تحويل لتسجيل الدخول
          </p>
        </div>

        <div
          style={{
            backgroundColor: "#eff6ff",
            padding: "20px",
            borderRadius: "8px",
            marginBottom: "20px",
          }}
        >
          <h2
            style={{ fontSize: "20px", marginBottom: "10px", color: "#1e40af" }}
          >
            📊 البيانات المستلمة:
          </h2>
          <pre
            style={{
              backgroundColor: "#1e293b",
              color: "#e2e8f0",
              padding: "16px",
              borderRadius: "6px",
              overflow: "auto",
              fontSize: "14px",
            }}
          >
            {JSON.stringify(data, null, 2)}
          </pre>
        </div>

        <div
          style={{
            backgroundColor: "#fef3c7",
            padding: "20px",
            borderRadius: "8px",
            border: "2px solid #fbbf24",
          }}
        >
          <h3
            style={{ fontSize: "18px", marginBottom: "10px", color: "#92400e" }}
          >
            💡 ملاحظة مهمة:
          </h3>
          <p style={{ margin: 0, color: "#78350f", lineHeight: "1.6" }}>
            هذه الصفحة لا تستخدم أي imports من services أو hooks معقدة. فقط
            React + fetch API البسيط.
          </p>
        </div>
      </div>
    </div>
  );
};

export default TestMinimal;

import React, { useState, useEffect } from "react";
import errorLogger, { ErrorLog } from "../../utils/errorLogger";
import {
  ArrowDownTrayIcon,
  TrashIcon,
  ArrowPathIcon,
  ExclamationTriangleIcon,
  FunnelIcon,
} from "@heroicons/react/24/outline";

const ErrorLogsPage: React.FC = () => {
  const [logs, setLogs] = useState<ErrorLog[]>([]);
  const [filter, setFilter] = useState<string>("all");
  const [stats, setStats] = useState<any>(null);
  const [selectedLog, setSelectedLog] = useState<ErrorLog | null>(null);

  const loadLogs = () => {
    const allLogs = errorLogger.getLogs();
    setLogs(allLogs);
    setStats(errorLogger.getStats());
  };

  useEffect(() => {
    loadLogs();
    // تحديث تلقائي كل 30 ثانية
    const interval = setInterval(loadLogs, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleClearLogs = () => {
    if (window.confirm("هل أنت متأكد من مسح جميع سجلات الأخطاء؟")) {
      errorLogger.clearLogs();
      loadLogs();
      setSelectedLog(null);
    }
  };

  const handleExportCSV = () => {
    const csv = errorLogger.exportLogsAsCSV();
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.setAttribute("download", `error_logs_${new Date().toISOString()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportJSON = () => {
    const json = errorLogger.exportLogs();
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.setAttribute(
      "download",
      `error_logs_${new Date().toISOString()}.json`,
    );
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const filteredLogs = logs.filter((log) => {
    if (filter === "all") return true;
    return log.errorState.errorType === filter;
  });

  const getStatusColor = (status?: number) => {
    if (!status) return "bg-gray-100 text-gray-800";
    if (status >= 500) return "bg-red-100 text-red-800";
    if (status >= 400) return "bg-yellow-100 text-yellow-800";
    return "bg-green-100 text-green-800";
  };

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <ExclamationTriangleIcon className="w-8 h-8 text-red-600" />
            سجل الأخطاء والنظام
          </h1>
          <p className="text-gray-500 mt-1">
            عرض وتحليل أخطاء التطبيق للمساعدة في الصيانة
          </p>
        </div>

        <div className="flex gap-2">
          <button
            onClick={loadLogs}
            className="p-2 text-gray-600 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
            title="تحديث"
          >
            <ArrowPathIcon className="w-6 h-6" />
          </button>

          <div className="relative group">
            <button className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 text-gray-700">
              <ArrowDownTrayIcon className="w-5 h-5" />
              تصدير
            </button>
            <div className="absolute left-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-gray-100 hidden group-hover:block z-10">
              <button
                onClick={handleExportCSV}
                className="block w-full text-right px-4 py-2 hover:bg-gray-50 text-sm"
              >
                تصدير كـ CSV
              </button>
              <button
                onClick={handleExportJSON}
                className="block w-full text-right px-4 py-2 hover:bg-gray-50 text-sm"
              >
                تصدير كـ JSON
              </button>
            </div>
          </div>

          <button
            onClick={handleClearLogs}
            className="flex items-center gap-2 px-4 py-2 bg-red-50 text-red-600 border border-red-200 rounded-lg hover:bg-red-100"
          >
            <TrashIcon className="w-5 h-5" />
            مسح السجل
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div className="text-gray-500 text-sm mb-1">إجمالي الأخطاء</div>
            <div className="text-2xl font-bold text-gray-900">
              {stats.total}
            </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div className="text-gray-500 text-sm mb-1">أخطاء آخر 24 ساعة</div>
            <div className="text-2xl font-bold text-blue-600">
              {stats.last24Hours}
            </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div className="text-gray-500 text-sm mb-1">
              أكثر مسار فيه أخطاء
            </div>
            <div
              className="text-lg font-medium text-red-600 truncate"
              title={stats.mostCommonEndpoint || "لا يوجد"}
            >
              {stats.mostCommonEndpoint || "-"}
            </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div className="text-gray-500 text-sm mb-1">
              نوع الخطأ الأكثر شيوعاً
            </div>
            <div className="text-lg font-medium text-orange-600">
              {Object.entries(stats.byType).sort(
                (a: any, b: any) => b[1] - a[1],
              )[0]?.[0] || "-"}
            </div>
          </div>
        </div>
      )}

      {/* Main Content */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[600px]">
        {/* Logs List */}
        <div className="lg:col-span-1 bg-white rounded-xl shadow-sm border border-gray-200 flex flex-col overflow-hidden">
          <div className="p-4 border-b border-gray-200 flex justify-between items-center">
            <h2 className="font-semibold text-gray-900">سجل العمليات</h2>
            <div className="flex items-center gap-2">
              <FunnelIcon className="w-4 h-4 text-gray-500" />
              <select
                value={filter}
                onChange={(e) => setFilter(e.target.value)}
                className="text-sm border-none bg-transparent focus:ring-0 text-gray-600 font-medium cursor-pointer"
              >
                <option value="all">الكل</option>
                <option value="server">Server</option>
                <option value="network">Network</option>
                <option value="auth">Auth</option>
                <option value="validation">Validation</option>
              </select>
            </div>
          </div>

          <div className="overflow-y-auto flex-1 p-2 space-y-2">
            {filteredLogs.length === 0 ? (
              <div className="text-center py-10 text-gray-500">
                لا توجد سجلات
              </div>
            ) : (
              filteredLogs.map((log, index) => (
                <div
                  key={index}
                  onClick={() => setSelectedLog(log)}
                  className={`p-3 rounded-lg border cursor-pointer transition-all ${
                    selectedLog === log
                      ? "bg-blue-50 border-blue-200 shadow-sm"
                      : "bg-white border-gray-100 hover:bg-gray-50"
                  }`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <span
                      className={`px-2 py-0.5 rounded text-xs font-medium ${
                        log.errorState.errorType === "server"
                          ? "bg-red-100 text-red-700"
                          : log.errorState.errorType === "network"
                            ? "bg-gray-100 text-gray-700"
                            : log.errorState.errorType === "auth"
                              ? "bg-yellow-100 text-yellow-700"
                              : "bg-orange-100 text-orange-700"
                      }`}
                    >
                      {log.errorState.errorType}
                    </span>
                    <span className="text-xs text-gray-400">
                      {new Date(log.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                  <div className="text-sm text-gray-900 font-medium truncate mb-1">
                    {log.errorState.errorMessage}
                  </div>
                  {log.errorState.details?.endpoint && (
                    <div className="text-xs text-gray-500 truncate font-mono">
                      {log.errorState.details.method}{" "}
                      {log.errorState.details.endpoint}
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>

        {/* Log Details */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
          {selectedLog ? (
            <div className="flex-1 flex flex-col h-full overflow-hidden">
              <div className="p-4 border-b border-gray-200 bg-gray-50">
                <div className="flex items-center gap-2 mb-2">
                  <span
                    className={`px-2.5 py-0.5 rounded-full text-xs font-medium border ${
                      selectedLog.errorState.errorType === "server"
                        ? "bg-red-100 text-red-700 border-red-200"
                        : "bg-gray-100 text-gray-700 border-gray-200"
                    }`}
                  >
                    {selectedLog.errorState.errorType.toUpperCase()}
                  </span>
                  <span className="text-sm text-gray-500">
                    {new Date(selectedLog.timestamp).toLocaleString()}
                  </span>
                </div>
                <h2 className="text-lg font-bold text-gray-900 leading-snug">
                  {selectedLog.errorState.errorMessage}
                </h2>
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {/* Basic Info */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 bg-gray-50 rounded-lg border border-gray-100">
                    <div className="text-xs text-gray-500 uppercase tracking-wider mb-1">
                      Session ID
                    </div>
                    <div className="text-sm font-mono text-gray-700">
                      {selectedLog.sessionId || "-"}
                    </div>
                  </div>
                  <div className="p-3 bg-gray-50 rounded-lg border border-gray-100">
                    <div className="text-xs text-gray-500 uppercase tracking-wider mb-1">
                      User Agent
                    </div>
                    <div
                      className="text-sm text-gray-700 truncate"
                      title={selectedLog.userAgent}
                    >
                      {selectedLog.userAgent}
                    </div>
                  </div>
                </div>

                {/* Technical Details */}
                {selectedLog.errorState.details && (
                  <div className="space-y-4">
                    <h3 className="text-sm font-bold text-gray-900 flex items-center gap-2 pb-2 border-b">
                      تفاصيل الطلب (Request Details)
                    </h3>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div className="p-3 rounded-lg bg-gray-900 text-gray-300 font-mono text-sm">
                        <div className="text-xs text-gray-500 mb-1">Method</div>
                        <span className="text-yellow-400">
                          {selectedLog.errorState.details.method}
                        </span>
                      </div>
                      <div className="p-3 rounded-lg bg-gray-900 text-gray-300 font-mono text-sm">
                        <div className="text-xs text-gray-500 mb-1">
                          Status Code
                        </div>
                        <span
                          className={
                            selectedLog.errorState.details.statusCode &&
                            selectedLog.errorState.details.statusCode >= 400
                              ? "text-red-400"
                              : "text-green-400"
                          }
                        >
                          {selectedLog.errorState.details.statusCode || "-"}
                        </span>
                      </div>
                      <div className="p-3 rounded-lg bg-gray-900 text-gray-300 font-mono text-sm">
                        <div className="text-xs text-gray-500 mb-1">
                          Endpoint
                        </div>
                        <span className="text-blue-300 break-all">
                          {selectedLog.errorState.details.endpoint}
                        </span>
                      </div>
                    </div>

                    {selectedLog.errorState.details.requestData && (
                      <div>
                        <div className="text-xs font-medium text-gray-500 mb-2">
                          Request Body
                        </div>
                        <pre className="bg-gray-900 text-gray-300 p-4 rounded-lg text-xs font-mono overflow-auto max-h-40">
                          {JSON.stringify(
                            selectedLog.errorState.details.requestData,
                            null,
                            2,
                          )}
                        </pre>
                      </div>
                    )}

                    {selectedLog.errorState.details.responseData && (
                      <div>
                        <div className="text-xs font-medium text-gray-500 mb-2">
                          Response Body
                        </div>
                        <pre className="bg-gray-900 text-gray-300 p-4 rounded-lg text-xs font-mono overflow-auto max-h-60 border-l-4 border-red-500">
                          {typeof selectedLog.errorState.details
                            .responseData === "object"
                            ? JSON.stringify(
                                selectedLog.errorState.details.responseData,
                                null,
                                2,
                              )
                            : selectedLog.errorState.details.responseData}
                        </pre>
                      </div>
                    )}

                    {selectedLog.errorState.details.stackTrace &&
                      import.meta.env.DEV && (
                        <div>
                          <div className="text-xs font-medium text-gray-500 mb-2">
                            Stack Trace
                          </div>
                          <pre className="bg-gray-50 text-red-800 p-4 rounded-lg text-[10px] font-mono overflow-auto whitespace-pre max-h-60 border border-gray-200">
                            {selectedLog.errorState.details.stackTrace}
                          </pre>
                        </div>
                      )}
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col justify-center items-center text-gray-400 p-8 text-center">
              <ExclamationTriangleIcon className="w-16 h-16 mb-4 opacity-50" />
              <h3 className="text-lg font-medium text-gray-900">
                لم يتم تحديد خطأ
              </h3>
              <p className="mt-1">
                اختر سجلاً من القائمة لعرض التفاصيل الكاملة
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ErrorLogsPage;

import { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import ProductSearchColumn from "./components/ProductSearchColumn";
import CartColumn from "./components/CartColumn";
import CheckoutColumn from "./components/CheckoutColumn";
import { toast } from "react-hot-toast";
import { CartItem } from "./types";
import { InformationCircleIcon } from "@heroicons/react/24/outline";
import { extractVariantDisplayDetails } from "./utils/variantAttributes";

const ManualOrderPage = () => {
  const { t } = useTranslation();
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [showShortcuts, setShowShortcuts] = useState(false);

  // منع scroll من main
  useEffect(() => {
    const mainElement = document.querySelector("main");
    if (mainElement) {
      mainElement.style.overflow = "hidden";
      mainElement.style.padding = "0";
    }

    return () => {
      if (mainElement) {
        mainElement.style.overflow = "";
        mainElement.style.padding = "";
      }
    };
  }, []);

  // Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      const isTyping =
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.tagName === "SELECT";

      // F1 - Show shortcuts
      if (e.key === "F1") {
        e.preventDefault();
        setShowShortcuts((prev) => !prev);
      }

      // F2 - Focus product search
      if (e.key === "F2") {
        e.preventDefault();
        const input = document.getElementById(
          "manual-order-product-search",
        ) as HTMLInputElement;
        if (input) input.focus();
      }

      // Escape
      if (e.key === "Escape") {
        (document.activeElement as HTMLElement)?.blur();
        setShowShortcuts(false);
      }

      // Ctrl + Delete (when not typing)
      if (!isTyping && e.ctrlKey && e.key === "Delete") {
        e.preventDefault();
        if (cartItems.length > 0) {
          setCartItems([]);
          toast.success(t("manualOrder.cartCleared"));
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [cartItems, t]);

  const handleAddToCart = (product: any, variant?: any) => {
    const itemId = variant
      ? `${product.id}-${variant.id}`
      : product.id;

    const existing = cartItems.find((item) => {
      if (variant) {
        return (
          item.productId === product.id &&
          item.variantId === variant.id
        );
      }
      return item.productId === product.id && !item.variantId;
    });

    if (existing) {
      toast.success(t("manualOrder.quantityIncreased"));
      setCartItems((prev) =>
        prev.map((item) => {
          const currentItemId = item.variantId
            ? `${item.productId}-${item.variantId}`
            : item.productId;

          return currentItemId === itemId
            ? { ...item, quantity: item.quantity + 1 }
            : item;
        }),
      );
    } else {
      toast.success(t("manualOrder.addedToCart"));

      const productPrice =
        typeof product.price === "string"
          ? parseFloat(product.price)
          : product.price || 0;

      const price = variant
        ? parseFloat(variant.price)
        : productPrice;

      const image =
        variant && variant.image ? variant.image : product.image;

      const stock = variant ? variant.stock : product.stock;
      const sku = variant ? variant.sku : product.sku;

      const variantDetails = extractVariantDisplayDetails(variant);

      const baseMarkup = product.baseMarkup || 0;

      setCartItems((prev) => [
        ...prev,
        {
          productId: product.id,
          variantId: variant?.id,
          name: product.name,
          price: price + baseMarkup,
          originalPrice: price,
          markup: baseMarkup,
          quantity: 1,
          image,
          stock,
          variantName: variantDetails.summary,
          color: variantDetails.color,
          size: variantDetails.size,
          sku,
        },
      ]);
    }
  };

  const handleUpdateItem = (
    productId: string,
    updates: Partial<CartItem>,
    variantId?: string,
  ) => {
    setCartItems((prev) =>
      prev.map((item) => {
        const isMatch = variantId
          ? item.productId === productId &&
            item.variantId === variantId
          : item.productId === productId && !item.variantId;

        return isMatch ? { ...item, ...updates } : item;
      }),
    );
  };

  const handleRemoveItem = (
    productId: string,
    variantId?: string,
  ) => {
    setCartItems((prev) =>
      prev.filter((item) => {
        const isMatch = variantId
          ? item.productId === productId &&
            item.variantId === variantId
          : item.productId === productId && !item.variantId;

        return !isMatch;
      }),
    );

    toast.success(t("manualOrder.productRemoved"));
  };

  return (
    <div
      className="bg-gray-50/50 dark:bg-gray-900 flex flex-col p-4"
      style={{
        height: "calc(100vh - 64px)",
        overflow: "hidden",
      }}
    >
      {/* Help Button */}
      <button
        onClick={() => setShowShortcuts((prev) => !prev)}
        className="absolute top-2 left-2 z-10 p-2 text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
        title={`${t("manualOrder.keyboardShortcuts")} (F1)`}
      >
        <InformationCircleIcon className="w-5 h-5" />
      </button>

      {/* Shortcuts Modal */}
      {showShortcuts && (
        <div
          className="fixed inset-0 z-50 bg-black/50 dark:bg-gray-900/80 backdrop-blur-sm flex items-center justify-center p-4"
          onClick={() => setShowShortcuts(false)}
        >
          <div
            className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl max-w-sm w-full overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="p-4 border-b bg-gray-50 dark:bg-gray-900">
              <h3 className="font-bold">
                {t("manualOrder.keyboardShortcuts")}
              </h3>
            </div>

            <div className="p-4 space-y-3 text-sm">
              <div className="flex justify-between">
                <span>{t("manualOrder.showShortcuts")}</span>
                <kbd>F1</kbd>
              </div>
              <div className="flex justify-between">
                <span>{t("manualOrder.searchProduct")}</span>
                <kbd>F2</kbd>
              </div>
              <div className="flex justify-between">
                <span>{t("manualOrder.clearCart")}</span>
                <span>Ctrl + Delete</span>
              </div>
              <div className="flex justify-between">
                <span>{t("manualOrder.closeCancel")}</span>
                <kbd>Esc</kbd>
              </div>
            </div>

            <div className="p-4 border-t bg-gray-50 dark:bg-gray-900">
              <button
                onClick={() => setShowShortcuts(false)}
                className="w-full py-2 bg-blue-600 text-white rounded-lg"
              >
                {t("manualOrder.ok")}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Layout */}
      <div className="grid grid-cols-12 gap-4 flex-1 min-h-0">
        <div className="col-span-12 lg:col-span-5 overflow-hidden">
          <ProductSearchColumn onAddToCart={handleAddToCart} />
        </div>

        <div className="col-span-12 lg:col-span-3 overflow-hidden">
          <CartColumn
            items={cartItems}
            onUpdateItem={handleUpdateItem}
            onRemoveItem={handleRemoveItem}
          />
        </div>

        <div className="col-span-12 lg:col-span-4 overflow-hidden">
          <CheckoutColumn
            cartItems={cartItems}
            onClearCart={() => setCartItems([])}
          />
        </div>
      </div>
    </div>
  );
};

