                  className="w-full py-3 px-4 bg-blue-600 dark:bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-700 dark:hover:bg-blue-600 transition-colors flex items-center justify-center gap-2"
                >
                  عرض تفاصيل الطلب
                </button>
                <button
                  onClick={() => {
                    if (createdOrderId) {
                      window.open(
                        `/orders/${encodeURIComponent(String(createdOrderId))}?print=true`,
                        "_blank",
                      );
                    }
                  }}
                  className="w-full py-3 px-4 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg font-medium hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors flex items-center justify-center gap-2"
                >
                  <PrinterIcon className="w-5 h-5" />
                  طباعة الفاتورة
                </button>
                <button
                  onClick={() => {
                    setShowSuccessModal(false);
                    setCreatedOrderId(null);
                    resetForm();
                  }}
                  className="w-full py-3 px-4 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 font-medium hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                >
                  إنشاء طلب جديد
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CheckoutColumn;

import React, { useState, useEffect, useCallback, useMemo } from "react";
import {
  MagnifyingGlassIcon,
  PlusIcon,
  ArchiveBoxIcon,
  XMarkIcon,
  ChevronRightIcon,
} from "@heroicons/react/24/outline";
import { authService } from "../../../../services/authService";
import { config } from "../../../../config";
import { toast } from "react-hot-toast";
import { getPrimaryImageUrl } from "../../../../utils/imageUrl";
import { parseVariantAttributes } from "../utils/variantAttributes";

interface ProductVariant {
  id: string;
  sku: string;
  price: number | string;
  stock: number;
  name: string;
  type?: string;
  color?: string;
  size?: string;
  image?: string;
  metadata?: string;
  attributeValues?: Record<string, string>;
  trackInventory?: boolean;
}

interface Product {
  id: string;
  name: string;
  price: number;
  image: string;
  stock: number;
  sku: string;
  trackInventory?: boolean;
  variants: ProductVariant[];
}

/** Returns true if the item is considered in-stock (either tracking is off, or stock > 0) */
const isInStock = (item: { stock: number; trackInventory?: boolean }): boolean => {
  if (item.trackInventory === false) return true;
  return item.stock > 0;
};

interface ProductSearchColumnProps {
  onAddToCart: (product: Product, variant?: ProductVariant) => void;
}

// Helper function to extract unique attributes from variants
const extractAttributes = (
  variants: ProductVariant[],
): { name: string; values: string[] }[] => {
  const attributeMap: Record<string, Set<string>> = {};

  variants.forEach((variant) => {
    const attrs = parseVariantAttributes(variant);
    Object.entries(attrs).forEach(([key, value]) => {
      if (!attributeMap[key]) attributeMap[key] = new Set();
      if (value) attributeMap[key].add(value);
    });
  });

  // Sort attributes to ensure consistent order
  return Object.entries(attributeMap)
    .filter(([_, values]) => values.size > 0)
    .map(([name, values]) => ({
      name,
      values: Array.from(values).sort(),
    }));
};

const ProductSearchColumn: React.FC<ProductSearchColumnProps> = ({
  onAddToCart,
}) => {
  const [searchQuery, setSearchQuery] = useState("");
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);

  // Variant Selection State
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Multi-level selection state
  const [selectedAttributes, setSelectedAttributes] = useState<
    Record<string, string>
  >({});

  // Debounce search could be better, but let's keep it simple for now
  const fetchProducts = useCallback(async (query: string = "") => {
    try {
      setLoading(true);
      const token = authService.getAccessToken();
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...(token && { Authorization: `Bearer ${token}` }),
      };

      const params = new URLSearchParams({
        page: "1",
        limit: "50", // Increase limit for better search experience
        manualOrder: "true", // ✅ Request all products for manual order
        // search: query // If backend supports it
      });

      const response = await fetch(
        `${config.apiUrl}/products?${params.toString()}`,
        { headers },
      );
      const data = await response.json();

      if (data.success && data.data) {
        const mappedProducts: Product[] = data.data.map((p: any) => {
          return {
            id: p.id,
            name: p.name,
            price: p.price,
            stock: p.stock,
            trackInventory: p.trackInventory,
            sku: p.sku,
            image: getPrimaryImageUrl(p.mainImage, p.image, p.images),
            variants: (p.variants || p.productVariants || []).map((v: any) => ({
              ...v,
              image: getPrimaryImageUrl(v.image, v.images),
              trackInventory: v.trackInventory,
            })),
          };
        });

        const filtered = query
          ? mappedProducts.filter(
              (p) =>
                String(p.name || "")
                  .toLowerCase()
                  .includes(query.toLowerCase()) ||
                String(p.sku || "")
                  .toLowerCase()
                  .includes(query.toLowerCase()),
            )
          : mappedProducts;

        setProducts(filtered);
      }
    } catch (error) {
      console.error("Error fetching products:", error);
      toast.error("فشل في جلب المنتجات");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchProducts();
  }, [fetchProducts]);

  const handleProductClick = (product: Product) => {
    if (product.variants && product.variants.length > 0) {
      setSelectedProduct(product);
      setSelectedAttributes({});
      setIsModalOpen(true);
    } else {
      onAddToCart(product);
    }
  };

  const handleVariantSelect = (variant: ProductVariant) => {
    if (selectedProduct) {
      onAddToCart(selectedProduct, variant);
      setIsModalOpen(false);
      setSelectedProduct(null);
      setSelectedAttributes({});
    }
  };

  const handleAttributeSelect = (attrName: string, value: string) => {
    setSelectedAttributes((prev) => ({
      ...prev,
      [attrName]: value,
    }));
  };

  // Extract attributes from selected product
  const productAttributes = useMemo(() => {
    if (!selectedProduct) return [];
    return extractAttributes(selectedProduct.variants);
  }, [selectedProduct]);

  // Filter variants based on selected attributes
  const filteredVariants = useMemo(() => {
    if (!selectedProduct) return [];

    return selectedProduct.variants.filter((variant) => {
      const variantAttrs = parseVariantAttributes(variant);
      return Object.entries(selectedAttributes).every(([key, value]) => {
        return variantAttrs[key] === value;
      });
    });
  }, [selectedProduct, selectedAttributes]);

  // Get available values for each attribute based on current selection
  const getAvailableValues = (attrName: string): string[] => {
    if (!selectedProduct) return [];

    // Filter variants based on all OTHER selected attributes (not this one)
    const otherSelections = { ...selectedAttributes };
    delete otherSelections[attrName];

    const availableVariants = selectedProduct.variants.filter((variant) => {
      const variantAttrs = parseVariantAttributes(variant);
      return Object.entries(otherSelections).every(([key, value]) => {
        return variantAttrs[key] === value;
      });
    });

    const values = new Set<string>();
    availableVariants.forEach((variant) => {
      const variantAttrs = parseVariantAttributes(variant);
      if (variantAttrs[attrName]) {
        values.add(variantAttrs[attrName]);
      }
    });

    return Array.from(values);
  };

  // Check if all attributes are selected
  const allAttributesSelected =
    productAttributes.length > 0 &&
    productAttributes.every((attr) => selectedAttributes[attr.name]);

  // Get the matching variant when all attributes are selected
  const matchedVariant = useMemo(() => {
    if (!allAttributesSelected || filteredVariants.length !== 1) return null;
    return filteredVariants[0];
  }, [allAttributesSelected, filteredVariants]);

  return (
    <div
      className="flex flex-col bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden relative"
      style={{ height: "100%", maxHeight: "100%" }}
    >
      {/* Search Header */}
      <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
        <h2 className="font-semibold text-gray-800 dark:text-gray-100 mb-3">
          المنتجات
        </h2>
        <div className="relative">
          <input
            id="manual-order-product-search"
            type="text"
            placeholder="بحث باسم المنتج أو SKU..."
            className="w-full pl-4 pr-10 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:text-gray-100 dark:placeholder-gray-400"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") fetchProducts(searchQuery);
            }}
          />
          <MagnifyingGlassIcon className="w-5 h-5 text-gray-400 dark:text-gray-500 absolute right-3 top-2.5" />
        </div>
      </div>

      {/* Product List */}
      <div className="flex-1 overflow-y-auto min-h-0 p-2 manual-order-scroll manual-order-column">
        {loading ? (
          <div className="grid grid-cols-2 xl:grid-cols-3 gap-3 p-3">
            {[...Array(6)].map((_, i) => (
              <div
                key={i}
                className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-lg overflow-hidden animate-pulse"
              >
                <div className="aspect-square bg-gray-200 dark:bg-gray-700" />
                <div className="p-3 space-y-2">
                  <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-3/4" />
                  <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/2" />
                  <div className="flex justify-between items-center mt-2">
                    <div className="h-5 bg-gray-200 dark:bg-gray-700 rounded w-16" />
                    <div className="h-8 w-8 bg-gray-200 dark:bg-gray-700 rounded-full" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : products.length === 0 ? (
          <div className="text-center py-10 text-gray-400 dark:text-gray-500">
            <ArchiveBoxIcon className="w-12 h-12 mx-auto mb-2 opacity-50" />
            <p>لا توجد منتجات</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 xl:grid-cols-3 gap-3 p-3">
            {products.map((product) => (
              <div
                key={product.id}
                className="flex flex-col bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-lg hover:border-blue-300 dark:hover:border-blue-600 hover:shadow-md transition-all group cursor-pointer overflow-hidden relative"
                onClick={() => handleProductClick(product)}
              >
                {/* Image - Now larger and on top */}
                <div className="aspect-square bg-gray-100 dark:bg-gray-700 relative">
                  {product.image ? (
                    <img
                      src={product.image}
                      alt={product.name}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-gray-300 dark:text-gray-600">
                      <ArchiveBoxIcon className="w-12 h-12" />
                    </div>
                  )}

                  <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 dark:group-hover:bg-black/10 transition-colors" />

                  {/* Stock Badge */}
                  {product.trackInventory !== false && product.stock <= 5 && (
                    <div className="absolute top-2 left-2 bg-white/90 dark:bg-gray-800/90 backdrop-blur text-red-600 dark:text-red-400 text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm border border-red-100 dark:border-red-900">
                      متبقي {product.stock}
                    </div>
                  )}

                  {/* Variant Badge */}
                  {product.variants.length > 0 && (
                    <div className="absolute bottom-2 right-2 bg-blue-600 dark:bg-blue-500 text-white text-[10px] px-1.5 py-0.5 rounded shadow-sm">
                      خيارات متعددة
                    </div>
                  )}
                </div>

                {/* Info */}
                <div className="p-3">
                  <h3
                    className="text-sm font-medium text-gray-900 dark:text-gray-100 line-clamp-2 h-10 leading-snug mb-1"
                    title={product.name}
                  >
                    {product.name}
                  </h3>

                  <div className="flex items-center justify-between mt-2">
                    <span className="text-base font-bold text-blue-600 dark:text-blue-400">
                      {product.price} ج.م
                    </span>

                    <button
                      className="p-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-full hover:bg-blue-600 dark:hover:bg-blue-500 hover:text-white transition-colors"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleProductClick(product);
                      }}
                    >
                      <PlusIcon className="w-4 h-4" />
                    </button>
                  </div>

                  <div className="text-[10px] text-gray-400 dark:text-gray-500 mt-1 truncate">
                    SKU: {product.sku || "N/A"}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Variant Selection Modal */}
      {isModalOpen && selectedProduct && (
        <div className="absolute inset-0 z-50 bg-black/50 dark:bg-gray-900/80 backdrop-blur-sm flex items-end sm:items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 w-full max-w-md rounded-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900">
              <h3 className="font-bold text-gray-900 dark:text-gray-100 truncate pr-4">
                {selectedProduct.name}
              </h3>
              <button
                onClick={() => {
                  setIsModalOpen(false);
                  setSelectedAttributes({});
                }}
                className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full text-gray-500 dark:text-gray-400"
              >
                <XMarkIcon className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 max-h-[60vh] overflow-y-auto">
              {/* Multi-level attribute selection */}
              {productAttributes.length > 0 ? (
                <div className="space-y-4">
                  {productAttributes.map((attr) => {
                    const availableValues = getAvailableValues(attr.name);
                    const isSelected = selectedAttributes[attr.name];

                    return (
                      <div key={attr.name} className="space-y-2">
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300">
                          {attr.name}
                          {isSelected && (
                            <span className="text-blue-600 dark:text-blue-400 mr-2">
                              : {isSelected}
                            </span>
                          )}
                        </label>
                        <div className="flex flex-wrap gap-2">
                          {attr.values.map((value) => {
                            const isAvailable = availableValues.includes(value);
                            const isActive =
                              selectedAttributes[attr.name] === value;

                            return (
                              <button
                                key={value}
                                onClick={() =>
                                  handleAttributeSelect(attr.name, value)
                                }
                                disabled={!isAvailable}
                                className={`px-3 py-2 rounded-lg text-sm font-medium transition-all
                                    ${
                                      isActive
                                        ? "bg-blue-600 dark:bg-blue-500 text-white border-2 border-blue-600 dark:border-blue-500"
                                        : isAvailable
                                          ? "bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 border-2 border-gray-200 dark:border-gray-600 hover:border-blue-400 dark:hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                                          : "bg-gray-100 dark:bg-gray-900 text-gray-400 dark:text-gray-500 border-2 border-gray-100 dark:border-gray-800 cursor-not-allowed line-through"
                                    }
                                `}
                              >
                                {value}
                              </button>
                            );
                          })}
                        </div>
                      </div>
                    );
                  })}

                  {/* Selected variant info & add button */}
                  {matchedVariant && (
                    <div className="mt-4 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-700">
                      <div className="flex justify-between items-center mb-3">
                        <div>
                          <div className="text-lg font-bold text-blue-600 dark:text-blue-400">
                            {matchedVariant.price} ج.م
                          </div>
                          <div
                            className={`text-sm ${isInStock(matchedVariant) ? "text-green-600 dark:text-green-400" : "text-red-500 dark:text-red-400"}`}
                          >
                            {isInStock(matchedVariant)
                              ? matchedVariant.trackInventory === false
                                ? "متاح"
                                : `${matchedVariant.stock} متاح`
                              : "نفذت الكمية"}
                          </div>
                        </div>
                        <div className="text-xs text-gray-500 dark:text-gray-400">
                          SKU: {matchedVariant.sku}
                        </div>
                      </div>
                      <button
                        onClick={() => handleVariantSelect(matchedVariant)}
                        disabled={!isInStock(matchedVariant)}
                        className={`w-full py-2.5 rounded-lg font-semibold transition-all flex items-center justify-center gap-2
                                                    ${
                                                      isInStock(matchedVariant)
                                                        ? "bg-blue-600 dark:bg-blue-500 text-white hover:bg-blue-700 dark:hover:bg-blue-600"
                                                        : "bg-gray-300 dark:bg-gray-700 text-gray-500 dark:text-gray-400 cursor-not-allowed"
                                                    }
                                                `}
                      >
                        <PlusIcon className="w-5 h-5" />
                        إضافة للسلة
                      </button>
                    </div>
                  )}

                  {/* Prompt to select remaining attributes */}
                  {!allAttributesSelected && (
                    <div className="mt-4 p-3 bg-gray-50 dark:bg-gray-700 rounded-lg text-center text-sm text-gray-500 dark:text-gray-400">
                      <ChevronRightIcon className="w-4 h-4 inline ml-1" />
                      اختر{" "}
                      {productAttributes
                        .filter((a) => !selectedAttributes[a.name])
                        .map((a) => a.name)
                        .join(" و ")}
                    </div>
                  )}
                </div>
              ) : (
                /* Fallback: Simple variant list if no attributes found */
                <div className="space-y-2">
                  {selectedProduct.variants.map((variant) => (
                    <button
                      key={variant.id}
                      onClick={() => handleVariantSelect(variant)}
                      disabled={!isInStock(variant)}
                      className={`w-full flex items-center justify-between p-3 rounded-lg border text-right transition-all
                                                ${
                                                  isInStock(variant)
                                                    ? "border-gray-200 dark:border-gray-700 hover:border-blue-500 dark:hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer bg-white dark:bg-gray-700"
                                                    : "border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 opacity-60 cursor-not-allowed"
                                                }
                                            `}
                    >
                      <div className="flex flex-col items-start">
                        <div className="font-medium text-gray-900 dark:text-gray-100 text-sm">
                          {variant.name || "غير محدد"}
                        </div>
                        <div className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                          SKU: {variant.sku}
                        </div>
                      </div>
                      <div className="text-left">
                        <div className="font-bold text-blue-600 dark:text-blue-400 text-sm">
                          {variant.price} ج.م
                        </div>
                        <div
                          className={`text-xs mt-0.5 ${isInStock(variant) ? "text-green-600 dark:text-green-400" : "text-red-500 dark:text-red-400"}`}
                        >
                          {isInStock(variant)
                            ? variant.trackInventory === false
                              ? "متاح"
                              : `${variant.stock} متاح`
                            : "نفذت الكمية"}
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductSearchColumn;

export interface VariantAttributeSource {
  name?: string;
  type?: string;
  color?: string;
  size?: string;
  metadata?: string | Record<string, any> | null;
  attributeValues?: Record<string, string> | null;
}

const COLOR_KEYS = ["اللون", "color", "pa_color", "لون"];
const SIZE_KEYS = ["المقاس", "size", "pa_size", "مقاس"];

const normalizeAttributeKey = (key: string) => key.trim().toLowerCase();

const hasValues = (
  value?: Record<string, string> | null,
): value is Record<string, string> => Boolean(value && Object.keys(value).length > 0);

const getMatchingAttributeValue = (
  attributes: Record<string, string>,
  candidates: string[],
) => {
  const candidateSet = new Set(candidates.map(normalizeAttributeKey));

  return Object.entries(attributes).find(([key]) =>
    candidateSet.has(normalizeAttributeKey(key)),
  )?.[1];
};

export const parseVariantAttributes = (
  variant: VariantAttributeSource,
): Record<string, string> => {
  if (hasValues(variant.attributeValues)) {
    return variant.attributeValues;
  }

  if (variant.metadata) {
    try {
      const metadata =
        typeof variant.metadata === "string"
          ? JSON.parse(variant.metadata)
          : variant.metadata;

      if (metadata.attributes && Array.isArray(metadata.attributes)) {
        const attrs: Record<string, string> = {};

        metadata.attributes.forEach((attr: any) => {
          if (attr.type === "color") {
            attrs["اللون"] = attr.option;
          } else if (attr.type === "size") {
            attrs["المقاس"] = attr.option;
          } else if (attr.type === "material") {
            attrs["المادة"] = attr.option;
          } else if (attr.type === "style") {
            attrs["النمط"] = attr.option;
          } else if (attr.option) {
            attrs[attr.name || "خاصية"] = attr.option;
          }
        });

        if (hasValues(attrs)) {
          return attrs;
        }
      }

      if (hasValues(metadata.attributeValues)) {
        return metadata.attributeValues;
      }
    } catch {
      // Ignore malformed metadata and continue with the fallback chain.
    }
  }

  if (variant.color || variant.size) {
    const attrs: Record<string, string> = {};

    if (variant.color) attrs["اللون"] = variant.color;
    if (variant.size) attrs["المقاس"] = variant.size;

    return attrs;
  }

  if (variant.name) {
    const pipePattern = /([^:]+):\s*([^|]+)/g;
    const attrs: Record<string, string> = {};
    let match: RegExpExecArray | null;

    while ((match = pipePattern.exec(variant.name)) !== null) {
      const key = match[1].trim();
      const value = match[2].trim();
      attrs[key] = value;
    }

    if (hasValues(attrs)) {
      return attrs;
    }

    const parts = variant.name.split(/\s*[-–]\s*/);
    if (parts.length >= 2) {
      return {
        اللون: parts[0].trim(),
        المقاس: parts[1].trim(),
      };
    }

    if (parts.length === 1 && variant.type) {
      const typeName =
        variant.type === "color"
          ? "اللون"
          : variant.type === "size"
            ? "المقاس"
            : variant.type;

      return { [typeName]: parts[0].trim() };
    }
  }

  return {};
};

export const extractVariantDisplayDetails = (
  variant?: VariantAttributeSource | null,
) => {
  if (!variant) {
    return {
      color: "",
      size: "",
      summary: "",
    };
  }

  const attributes = parseVariantAttributes(variant);
  const color =
    variant.color || getMatchingAttributeValue(attributes, COLOR_KEYS) || "";
  const size =
    variant.size || getMatchingAttributeValue(attributes, SIZE_KEYS) || "";
  const consumedKeys = new Set(
    [...COLOR_KEYS, ...SIZE_KEYS].map(normalizeAttributeKey),
  );

  const extras = Object.entries(attributes)
    .filter(
      ([key, value]) =>
        Boolean(value) && !consumedKeys.has(normalizeAttributeKey(key)),
    )
    .map(([key, value]) => `${key}: ${value}`);

  const baseSummary = [color, size].filter(Boolean).join(" / ");
  const summaryParts = [baseSummary, ...extras].filter(Boolean);

  return {
    color,
    size,
    summary:
      summaryParts.join(" | ") || String(variant.name || "").trim(),
  };
};

import React, { useState, useEffect } from 'react';
import {
    CheckCircleIcon,
    XCircleIcon,
    ClockIcon,
    ChatBubbleBottomCenterTextIcon,
    UserIcon,
    ShoppingBagIcon
} from '@heroicons/react/24/outline';
import orderWorkflowService from '../../../services/orderWorkflowService';

const ApprovalRules: React.FC<{ onUpdate: () => void }> = ({ onUpdate }) => {
    const [requests, setRequests] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [reviewing, setReviewing] = useState<any | null>(null);
    const [reason, setReason] = useState('');

    useEffect(() => {
        fetchRequests();
    }, []);

    const fetchRequests = async () => {
        try {
            setLoading(true);
            const res = await orderWorkflowService.getPendingApprovals();
            setRequests(res.data);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleReview = async (action: 'approve' | 'reject') => {
        if (!reviewing) return;
        try {
            await orderWorkflowService.reviewApproval(reviewing.id, action, reason);
            setReviewing(null);
            setReason('');
            fetchRequests();
            onUpdate();
        } catch (error) {
            alert(error.message);
        }
    };

    return (
        <div className="animate-in fade-in duration-500">
            <div className="mb-8">
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">طلبات الموافقة المعلقة</h2>
                <p className="text-slate-500 text-sm">راجع طلبات تغيير حالة الطلبات التي تتطلب موافقة المدير</p>
            </div>

            {loading ? (
                <div className="p-10 text-center">جاري التحميل...</div>
            ) : requests.length === 0 ? (
                <div className="p-20 text-center bg-slate-50 dark:bg-slate-900/30 rounded-3xl border border-slate-100 dark:border-slate-800">
                    <CheckCircleIcon className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                    <p className="text-slate-400">لا يوجد طلبات موافقة معلقة حالياً</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {requests.map((req) => (
                        <div
                            key={req.id}
                            className="p-5 rounded-3xl bg-white dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700 hover:border-indigo-200 transition-colors"
                        >
                            <div className="flex flex-col md:flex-row justify-between gap-4">
                                <div className="space-y-3">
                                    <div className="flex items-center gap-2">
                                        <ShoppingBagIcon className="w-5 h-5 text-indigo-500" />
                                        <span className="font-bold text-slate-900 dark:text-white">طلب رقم: {req.order?.orderNumber}</span>
                                    </div>
                                    <div className="flex items-center gap-4 text-sm text-slate-500">
                                        <div className="flex items-center gap-1">
                                            <UserIcon className="w-4 h-4" />
                                            بواسطة: {req.requestor?.firstName} {req.requestor?.lastName}
                                        </div>
                                        <div className="flex items-center gap-1">
                                            <ClockIcon className="w-4 h-4" />
                                            منذ: {new Date(req.createdAt).toLocaleString('ar-EG')}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 py-2 px-4 bg-slate-50 dark:bg-slate-900/50 rounded-2xl w-fit">
                                        <span className="text-sm font-medium">{req.fromStatus?.name || 'بداية'}</span>
                                        <span className="text-indigo-400">←</span>
                                        <span className="text-sm font-bold text-indigo-600">{req.toStatus?.name}</span>
                                    </div>
                                    {req.reason && (
                                        <div className="flex items-start gap-2 bg-amber-50 dark:bg-amber-900/10 p-3 rounded-xl border border-amber-100 dark:border-amber-900/30">
                                            <ChatBubbleBottomCenterTextIcon className="w-4 h-4 text-amber-500 mt-1" />
                                            <p className="text-xs text-amber-700 dark:text-amber-400">السبب: {req.reason}</p>
                                        </div>
                                    )}
                                </div>

                                <div className="flex items-center gap-3 self-end md:self-center">
                                    <button
                                        onClick={() => setReviewing(req)}
                                        className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition"
                                    >
                                        مراجعة الطلب
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Review Modal */}
            {reviewing && (
                <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
                    <div className="w-full max-w-lg bg-white dark:bg-slate-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
                        <h2 className="text-2xl font-bold mb-6">مراجعة طلب تغيير الحالة</h2>

                        <div className="mb-6 p-4 rounded-2xl bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800">
                            <p className="text-sm text-indigo-700 dark:text-indigo-300">
                                أنت بصدد مراجعة تغيير حالة الطلب <strong>{reviewing.order?.orderNumber}</strong> إلى <strong>{reviewing.toStatus?.name}</strong>.
                            </p>
                        </div>

                        <div className="mb-6">
                            <label className="block text-sm font-medium mb-2 text-slate-700 dark:text-slate-300">ملاحظات المراجعة (اختياري):</label>
                            <textarea
                                value={reason}
                                onChange={(e) => setReason(e.target.value)}
                                className="w-full p-4 rounded-2xl border border-slate-200 dark:border-slate-700 bg-transparent"
                                placeholder="اكتب ملاحظاتك للموظف هنا..."
                                rows={3}
                            />
                        </div>

                        <div className="flex gap-4">
                            <button
                                onClick={() => handleReview('approve')}
                                className="flex-1 flex items-center justify-center gap-2 py-4 bg-green-600 text-white rounded-2xl font-bold hover:bg-green-700 transition"
                            >
                                <CheckCircleIcon className="w-6 h-6" />
                                موافقة
                            </button>
                            <button
                                onClick={() => handleReview('reject')}
                                className="flex-1 flex items-center justify-center gap-2 py-4 bg-red-600 text-white rounded-2xl font-bold hover:bg-red-700 transition"
                            >
                                <XCircleIcon className="w-6 h-6" />
                                رفض
                            </button>
                        </div>

                        <button
                            onClick={() => { setReviewing(null); setReason(''); }}
                            className="w-full mt-4 py-3 text-slate-400 hover:text-slate-600 font-medium"
                        >
                            إغلاق
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ApprovalRules;

import React, { useState } from 'react';
import {
    MagnifyingGlassIcon,
    ClockIcon,
    UserIcon,
    ArrowRightIcon,
    ShieldExclamationIcon,
    CheckBadgeIcon
} from '@heroicons/react/24/outline';
import orderWorkflowService from '../../../services/orderWorkflowService';

const AuditLogViewer: React.FC = () => {
    const [orderNumber, setOrderNumber] = useState('');
    const [logs, setLogs] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [searched, setSearched] = useState(false);

    React.useEffect(() => {
        fetchInitialLogs();
    }, []);

    const fetchInitialLogs = async () => {
        try {
            setLoading(true);
            const res = await orderWorkflowService.getGlobalAuditLogs(20);
            setLogs(res.data);
            setSearched(false);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!orderNumber) return;
        try {
            setLoading(true);
            // In a real app, you'd find order by number first or the API would handle it
            // For now, let's assume we pass the ID or the API searches by number
            const res = await orderWorkflowService.getAuditLogs(orderNumber);
            setLogs(res.data);
            setSearched(true);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const getTypeBadge = (type: string) => {
        switch (type) {
            case 'override':
                return <span className="flex items-center gap-1 text-[10px] bg-red-50 text-red-600 px-2 py-0.5 rounded-full border border-red-100 font-bold"><ShieldExclamationIcon className="w-3 h-3" /> تجـاوز</span>;
            case 'approval':
                return <span className="flex items-center gap-1 text-[10px] bg-green-50 text-green-600 px-2 py-0.5 rounded-full border border-green-100 font-bold"><CheckBadgeIcon className="w-3 h-3" /> بموافقة</span>;
            default:
                return <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded-full border border-slate-200">اعتيادي</span>;
        }
    };

    return (
        <div className="animate-in fade-in duration-500">
            <div className="mb-8">
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">سجل الرقابة على المسار</h2>
                <p className="text-slate-500 text-sm">تتبع جميع التغييرات التي طرأت على حالات الطلبات والمسؤولين عنها</p>
            </div>

            {/* Search Bar */}
            <form onSubmit={handleSearch} className="mb-8 p-6 rounded-3xl bg-slate-50 dark:bg-slate-900/50 border border-slate-100 dark:border-slate-800 flex gap-4">
                <div className="flex-1 relative">
                    <MagnifyingGlassIcon className="w-5 h-5 text-slate-400 absolute left-4 top-1/2 -translate-y-1/2" />
                    <input
                        type="text"
                        value={orderNumber}
                        onChange={(e) => setOrderNumber(e.target.value)}
                        placeholder="أدخل معرف الطلب (Order ID) للبحث في سجله..."
                        className="w-full pl-12 pr-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                    />
                </div>
                <button
                    type="submit"
                    disabled={loading}
                    className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 transition disabled:opacity-50"
                >
                    {loading ? 'جاري البحث...' : 'عـرض السجل'}
                </button>
            </form>

            {/* Timeline */}
            <div className="relative">
                {logs.length > 0 && (
                    <div className="absolute top-0 bottom-0 left-[21px] w-0.5 bg-slate-100 dark:bg-slate-800" />
                )}

                {searched && logs.length === 0 && (
                    <div className="p-20 text-center text-slate-400">لا يوجد سجل عمليات لهذا الطلب</div>
                )}

                <div className="space-y-8">
                    {logs.map((log) => (
                        <div key={log.id} className="relative flex gap-6 animate-in slide-in-from-left-4 duration-300">
                            <div className="relative z-10 w-[44px] h-[44px] rounded-full bg-white dark:bg-slate-800 border-4 border-slate-50 dark:border-slate-900 flex items-center justify-center shadow-sm">
                                <ClockIcon className="w-5 h-5 text-indigo-500" />
                            </div>

                            <div className="flex-1 p-6 rounded-3xl bg-white dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700 shadow-sm">
                                <div className="flex flex-wrap items-center justify-between gap-4 mb-4">
                                    <div className="flex items-center gap-3">
                                        {log.order?.orderNumber && (
                                            <div className="bg-slate-100 dark:bg-slate-700 px-2 py-1 rounded text-[10px] font-bold text-slate-600">
                                                #{log.order.orderNumber}
                                            </div>
                                        )}
                                        <span className="text-sm font-bold text-slate-700 dark:text-slate-300">{log.fromStatus?.name || 'بداية'}</span>
                                        <ArrowRightIcon className="w-4 h-4 text-slate-300" />
                                        <span className="text-sm font-bold text-indigo-600">{log.toStatus?.name}</span>
                                        {getTypeBadge(log.changeType)}
                                    </div>
                                    <span className="text-xs text-slate-400">{new Date(log.createdAt).toLocaleString('ar-EG')}</span>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="flex items-center gap-2 text-sm">
                                        <UserIcon className="w-4 h-4 text-slate-400" />
                                        <span className="text-slate-500">المنفذ:</span>
                                        <span className="font-medium text-slate-700 dark:text-slate-300">{log.user?.firstName} {log.user?.lastName}</span>
                                    </div>
                                    {log.approver && (
                                        <div className="flex items-center gap-2 text-sm">
                                            <CheckBadgeIcon className="w-4 h-4 text-green-500" />
                                            <span className="text-slate-500">الموافق:</span>
                                            <span className="font-medium text-green-600">{log.approver?.firstName} {log.approver?.lastName}</span>
                                        </div>
                                    )}
                                </div>

                                {log.reason && (
                                    <div className="mt-4 p-3 rounded-xl bg-slate-50 dark:bg-slate-900/50 border border-slate-100 dark:border-slate-700 text-xs text-slate-600 dark:text-slate-400 italic">
                                        " {log.reason} "
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default AuditLogViewer;

import React, { useState, useEffect } from 'react';
import {
    PlusIcon,
    TrashIcon,
    ArrowsRightLeftIcon,
    UserGroupIcon,
    ShieldCheckIcon,
    ExclamationCircleIcon
} from '@heroicons/react/24/outline';
import orderWorkflowService, {
    OrderStatusDefinition,
    OrderWorkflowTransition
} from '../../../services/orderWorkflowService';

interface Props {
    statuses: OrderStatusDefinition[];
    onUpdate: () => void;
}

const TransitionRules: React.FC<Props> = ({ statuses, onUpdate }) => {
    const [transitions, setTransitions] = useState<OrderWorkflowTransition[]>([]);
    const [isAdding, setIsAdding] = useState(false);
    const [newRule, setNewRule] = useState<Partial<OrderWorkflowTransition>>({
        fromStatusId: '',
        toStatusId: '',
        allowedRoles: '["OWNER", "SUPER_ADMIN"]',
        requiresApproval: false,
        restrictBackward: false
    });

    const availableRoles = [
        { value: 'OWNER', label: 'مالك الشركة' },
        { value: 'SUPER_ADMIN', label: 'مدير النظام' },
        { value: 'COMPANY_ADMIN', label: 'مدير شركة' },
        { value: 'MANAGER', label: 'مدير' },
        { value: 'AGENT', label: 'موظف / عميل' },
    ];

    useEffect(() => {
        fetchTransitions();
    }, []);

    const fetchTransitions = async () => {
        try {
            const res = await orderWorkflowService.getTransitions();
            setTransitions(res.data);
        } catch (error) {
            console.error('Failed to fetch transitions', error);
        }
    };

    const handleSave = async () => {
        if (!newRule.toStatusId) return;
        try {
            await orderWorkflowService.upsertTransition(newRule);
            setIsAdding(false);
            fetchTransitions();
            onUpdate();
        } catch (error) {
            console.error('Failed to save transition', error);
        }
    };

    const handleDelete = async (id: string) => {
        if (!window.confirm('هل أنت متأكد من حذف قاعدة الانتقال هذه؟')) return;
        try {
            await orderWorkflowService.deleteTransition(id);
            fetchTransitions();
            onUpdate();
        } catch (error) {
            console.error('Failed to delete', error);
        }
    };

    const getStatusName = (id: string | null) => {
        if (!id) return 'بداية (New Order)';
        return statuses.find(s => s.id === id)?.name || 'غير معروف';
    };

    return (
        <div className="animate-in fade-in duration-500">
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white">مصفوفة قواعد الانتقال</h2>
                    <p className="text-slate-500 text-sm">حدد التحولات المسموح بها بين الحالات والأدوار المخولة لكل تحول</p>
                </div>
                <button
                    onClick={() => setIsAdding(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-colors"
                >
                    <PlusIcon className="w-5 h-5" />
                    إضافة قاعدة انتقال
                </button>
            </div>

            <div className="space-y-4">
                {transitions.length === 0 && !isAdding && (
                    <div className="p-20 text-center bg-slate-50 dark:bg-slate-900/40 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700">
                        <ArrowsRightLeftIcon className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                        <p className="text-slate-400">لا يوجد قواعد انتقال معرفة حالياً</p>
                    </div>
                )}

                {isAdding && (
                    <div className="p-6 rounded-3xl border-2 border-indigo-200 dark:border-indigo-900 bg-indigo-50/30 dark:bg-indigo-900/10 animate-in slide-in-from-top-4 duration-300">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                            <div>
                                <label className="block text-sm font-medium mb-1">من حالة:</label>
                                <select
                                    value={newRule.fromStatusId}
                                    onChange={(e) => setNewRule({ ...newRule, fromStatusId: e.target.value })}
                                    className="w-full p-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                                >
                                    <option value="">بداية (New Order)</option>
                                    {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium mb-1">إلى حالة:</label>
                                <select
                                    value={newRule.toStatusId}
                                    onChange={(e) => setNewRule({ ...newRule, toStatusId: e.target.value })}
                                    className="w-full p-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                                >
                                    <option value="">اختر الحالة المستهدفة</option>
                                    {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                                </select>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                            <div>
                                <label className="block text-sm font-medium mb-1">الأدوار المسموح لها:</label>
                                <div className="grid grid-cols-2 gap-2">
                                    {availableRoles.map(role => (
                                        <label key={role.value} className="flex items-center gap-2 text-xs p-2 rounded-lg bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 cursor-pointer">
                                            <input
                                                type="checkbox"
                                                checked={JSON.parse(newRule.allowedRoles || '[]').includes(role.value)}
                                                onChange={(e) => {
                                                    const roles = JSON.parse(newRule.allowedRoles || '[]');
                                                    const updated = e.target.checked
                                                        ? [...roles, role.value]
                                                        : roles.filter((r: string) => r !== role.value);
                                                    setNewRule({ ...newRule, allowedRoles: JSON.stringify(updated) });
                                                }}
                                            />
                                            {role.label}
                                        </label>
                                    ))}
                                </div>
                            </div>
                            <div className="space-y-4">
                                <label className="flex items-center gap-3 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={newRule.requiresApproval}
                                        onChange={(e) => setNewRule({ ...newRule, requiresApproval: e.target.checked })}
                                        className="w-5 h-5 rounded border-slate-300"
                                    />
                                    <div className="text-sm">
                                        <p className="font-bold">يتطلب موافقة المدير</p>
                                        <p className="text-slate-500 text-xs">سيتم تعليق الطلب حتى يوافق المسؤول.</p>
                                    </div>
                                </label>
                                <label className="flex items-center gap-3 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={newRule.restrictBackward}
                                        onChange={(e) => setNewRule({ ...newRule, restrictBackward: e.target.checked })}
                                        className="w-5 h-5 rounded border-slate-300"
                                    />
                                    <div className="text-sm">
                                        <p className="font-bold">منع العودة للخلف (Restrict Backward)</p>
                                        <p className="text-slate-500 text-xs">يمنع الرجوع من الحالة "المستهدفة" إلى "الحالية".</p>
                                    </div>
                                </label>
                            </div>
                        </div>

                        <div className="flex gap-4">
                            <button onClick={handleSave} className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold">حفظ القاعدة</button>
                            <button onClick={() => setIsAdding(false)} className="px-6 py-2 bg-slate-200 text-slate-700 rounded-xl font-bold">إلغاء</button>
                        </div>
                    </div>
                )}

                {transitions.map((t) => (
                    <div
                        key={t.id}
                        className="flex flex-col md:flex-row items-center justify-between p-5 rounded-3xl bg-white dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700 hover:shadow-md transition-shadow gap-4"
                    >
                        <div className="flex items-center gap-4 flex-1">
                            <div className="flex items-center gap-3">
                                <span className="font-bold text-slate-700 dark:text-slate-300">{getStatusName(t.fromStatusId)}</span>
                                <ArrowsRightLeftIcon className="w-5 h-5 text-indigo-400" />
                                <span className="font-bold text-indigo-600">{getStatusName(t.toStatusId)}</span>
                            </div>

                            <div className="hidden md:flex flex-wrap items-center gap-2 px-6 border-x border-slate-100 dark:border-slate-700">
                                {JSON.parse(t.allowedRoles || '[]').map((role: string) => (
                                    <span key={role} className="text-[10px] bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 px-2 py-0.5 rounded-full border border-indigo-100 dark:border-indigo-800">
                                        {availableRoles.find(r => r.value === role)?.label || role}
                                    </span>
                                ))}
                                {t.requiresApproval && <ShieldCheckIcon className="w-5 h-5 text-amber-500" title="يتطلب موافقة" />}
                                {t.restrictBackward && <ExclamationCircleIcon className="w-5 h-5 text-red-400" title="ممنوع العودة" />}
                            </div>
                        </div>

                        <button
                            onClick={() => handleDelete(t.id)}
                            className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                        >
                            <TrashIcon className="w-5 h-5" />
                        </button>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default TransitionRules;

import React, { useState, useEffect } from "react";
import { Link, Navigate } from "react-router-dom";
import {
  Search,
  Filter,
  Clock,
  CheckCircle,
  AlertCircle,
  MessageSquare,
  Calendar,
  Tag,
  User,
  BarChart3,
  Plus,
  Eye,
  Edit,
  Trash2,
  Settings,
} from "lucide-react";
import supportService, {
  Ticket,
  FAQ,
  TicketStats,
} from "../../services/supportService";
import ThemeToggle from "../../components/ui/theme-toggle";
import { useAuth } from "../../hooks/useAuthSimple";

const SupportAdmin: React.FC = () => {
  const { user } = useAuth();

  // فحص الصلاحيات - فقط Super Admin يمكنه الوصول
  if (!user || user.role !== "SUPER_ADMIN") {
    return <Navigate to="/support" replace />;
  }

  const [activeTab, setActiveTab] = useState<"tickets" | "faq" | "stats">(
    "tickets",
  );

  // Tickets State
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [ticketStats, setTicketStats] = useState<TicketStats[]>([]);
  const [ticketsLoading, setTicketsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);

  // FAQ State
  const [faqs, setFaqs] = useState<FAQ[]>([]);
  const [faqsLoading, setFaqsLoading] = useState(false);
  const [showFAQForm, setShowFAQForm] = useState(false);
  const [editingFAQ, setEditingFAQ] = useState<FAQ | null>(null);
  const [faqFormData, setFaqFormData] = useState({
    question: "",
    answer: "",
    category: "general",
    tags: "",
    order: 0,
  });

  const statusOptions = [
    { value: "", label: "جميع الحالات" },
    { value: "open", label: "مفتوح" },
    { value: "in_progress", label: "قيد المعالجة" },
    { value: "closed", label: "مغلق" },
  ];

  const categoryOptions = [
    { value: "", label: "جميع الأنواع" },
    { value: "technical", label: "تقني" },
    { value: "billing", label: "فواتير" },
    { value: "inquiry", label: "استفسار" },
    { value: "suggestion", label: "اقتراح" },
    { value: "complaint", label: "شكوى" },
  ];

  const faqCategoryOptions = [
    { value: "general", label: "عام" },
    { value: "technical", label: "تقني" },
    { value: "billing", label: "فواتير" },
    { value: "woocommerce", label: "WooCommerce" },
    { value: "whatsapp", label: "WhatsApp" },
    { value: "facebook_ads", label: "إعلانات فيسبوك" },
  ];

  useEffect(() => {
    if (activeTab === "tickets") {
      fetchTickets();
    } else if (activeTab === "faq") {
      fetchFAQs();
    }
  }, [activeTab, currentPage, statusFilter, categoryFilter]);

  const fetchTickets = async () => {
    try {
      setTicketsLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: "10",
      });

      if (statusFilter) params.append("status", statusFilter);
      if (categoryFilter) params.append("category", categoryFilter);
      if (searchTerm) params.append("search", searchTerm);

      const data = await supportService.getAllTickets(params);

      if (data.success) {
        setTickets(data.tickets);
        setTicketStats(data.stats || []);
        setTotalPages(data.pagination.pages);
        setTotal(data.pagination.total);
      }
    } catch (error) {
      console.error("Error fetching tickets:", error);
    } finally {
      setTicketsLoading(false);
    }
  };

  const fetchFAQs = async () => {
    try {
      setFaqsLoading(true);
      const data = await supportService.getAdminFAQs();

      if (data.success) {
        setFaqs(data.faqs);
      }
    } catch (error) {
      console.error("Error fetching FAQs:", error);
    } finally {
      setFaqsLoading(false);
    }
  };

  const updateTicketStatus = async (ticketId: string, status: string) => {
    try {
      const data = await supportService.updateTicketStatus(ticketId, status);

      if (data.success) {
        fetchTickets(); // Refresh tickets
      }
    } catch (error) {
      console.error("Error updating ticket status:", error);
    }
  };

  const handleFAQSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const data = {
        ...faqFormData,
        tags: faqFormData.tags
          .split(",")
          .map((tag) => tag.trim())
          .filter((tag) => tag),
      };

      let responseData;
      if (editingFAQ) {
        responseData = await supportService.updateFAQ(editingFAQ._id, data);
      } else {
        responseData = await supportService.createFAQ(data);
      }

      if (responseData.success) {
        setShowFAQForm(false);
        setEditingFAQ(null);
        setFaqFormData({
          question: "",
          answer: "",
          category: "general",
          tags: "",
          order: 0,
        });
        fetchFAQs();
      }
    } catch (error) {
      console.error("Error saving FAQ:", error);
    }
  };

  const deleteFAQ = async (faqId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا السؤال؟")) return;

    try {
      const data = await supportService.deleteFAQ(faqId);

      if (data.success) {
        fetchFAQs();
      }
    } catch (error) {
      console.error("Error deleting FAQ:", error);
    }
  };

  const editFAQ = (faq: FAQ) => {
    setEditingFAQ(faq);
    setFaqFormData({
      question: faq.question,
      answer: faq.answer,
      category: faq.category,
      tags: faq.tags?.join(", ") || "",
      order: 0,
    });
    setShowFAQForm(true);
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "open":
        return <Clock className="w-4 h-4 text-orange-500" />;
      case "in_progress":
        return <AlertCircle className="w-4 h-4 text-blue-500" />;
      case "closed":
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      default:
        return <Clock className="w-4 h-4 text-gray-500" />;
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case "open":
        return "مفتوح";
      case "in_progress":
        return "قيد المعالجة";
      case "closed":
        return "مغلق";
      default:
        return status;
    }
  };

  const getCategoryText = (category: string) => {
    const categories: { [key: string]: string } = {
      technical: "تقني",
      billing: "فواتير",
      inquiry: "استفسار",
      suggestion: "اقتراح",
      complaint: "شكوى",
      general: "عام",
      woocommerce: "WooCommerce",
      whatsapp: "WhatsApp",
      facebook_ads: "إعلانات فيسبوك",
    };
    return categories[category] || category;
  };

  const getStatsCount = (status: string) => {
    const stat = ticketStats.find((s) => s._id === status);
    return stat ? stat.count : 0;
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex justify-between items-center mb-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
                إدارة الدعم الفني
              </h1>
              <p className="text-gray-600 dark:text-gray-300">
                إدارة تذاكر الدعم والأسئلة الشائعة
              </p>
            </div>
            <ThemeToggle />
          </div>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
            <div className="flex items-center">
              <div className="bg-orange-100 dark:bg-orange-900/30 p-3 rounded-full">
                <Clock className="w-6 h-6 text-orange-600 dark:text-orange-400" />
              </div>
              <div className="mr-4">
                <p className="text-sm font-medium text-gray-600 dark:text-gray-300">
                  مفتوح
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {getStatsCount("open")}
                </p>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
            <div className="flex items-center">
              <div className="bg-blue-100 dark:bg-blue-900/30 p-3 rounded-full">
                <AlertCircle className="w-6 h-6 text-blue-600 dark:text-blue-400" />
              </div>
              <div className="mr-4">
                <p className="text-sm font-medium text-gray-600 dark:text-gray-300">
                  قيد المعالجة
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {getStatsCount("in_progress")}
                </p>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
            <div className="flex items-center">
              <div className="bg-green-100 dark:bg-green-900/30 p-3 rounded-full">
                <CheckCircle className="w-6 h-6 text-green-600 dark:text-green-400" />
              </div>
              <div className="mr-4">
                <p className="text-sm font-medium text-gray-600 dark:text-gray-300">
                  مغلق
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {getStatsCount("closed")}
                </p>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
            <div className="flex items-center">
              <div className="bg-purple-100 dark:bg-purple-900/30 p-3 rounded-full">
                <BarChart3 className="w-6 h-6 text-purple-600 dark:text-purple-400" />
              </div>
              <div className="mr-4">
                <p className="text-sm font-medium text-gray-600 dark:text-gray-300">
                  الإجمالي
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {total}
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md mb-6">
          <div className="border-b border-gray-200 dark:border-gray-700">
            <nav className="-mb-px flex space-x-8 space-x-reverse px-6">
              <button
                onClick={() => setActiveTab("tickets")}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === "tickets"
                    ? "border-blue-500 text-blue-600 dark:text-blue-400"
                    : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300 dark:hover:border-gray-600"
                }`}
              >
                <MessageSquare className="w-5 h-5 inline ml-2" />
                التذاكر
              </button>
              <button
                onClick={() => setActiveTab("faq")}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === "faq"
                    ? "border-blue-500 text-blue-600 dark:text-blue-400"
                    : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300 dark:hover:border-gray-600"
                }`}
              >
                <Settings className="w-5 h-5 inline ml-2" />
                الأسئلة الشائعة
              </button>
            </nav>
          </div>

          {/* Tickets Tab */}
          {activeTab === "tickets" && (
            <div className="p-6">
              {/* Filters */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                <div className="md:col-span-2">
                  <div className="relative">
                    <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500 w-4 h-4" />
                    <input
                      type="text"
                      placeholder="البحث في التذاكر..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      onKeyPress={(e) => e.key === "Enter" && fetchTickets()}
                      className="w-full pr-10 pl-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-transparent"
                    />
                  </div>
                </div>

                <select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  className="px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-transparent"
                >
                  {statusOptions.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>

                <select
                  value={categoryFilter}
                  onChange={(e) => setCategoryFilter(e.target.value)}
                  className="px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-transparent"
                >
                  {categoryOptions.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Tickets List */}
              {ticketsLoading ? (
                <div className="flex justify-center py-8">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 dark:border-blue-400"></div>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                    <thead className="bg-gray-50 dark:bg-gray-700">
                      <tr>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                          التذكرة
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                          العميل
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                          الحالة
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                          النوع
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                          التاريخ
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                          الإجراءات
                        </th>
                      </tr>
                    </thead>
                    <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                      {tickets.map((ticket) => (
                        <tr
                          key={ticket.ticketId || ticket._id}
                          className="hover:bg-gray-50 dark:hover:bg-gray-700"
                        >
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div>
                              <div className="text-sm font-medium text-gray-900 dark:text-white">
                                {ticket.subject}
                              </div>
                              <div className="text-sm text-gray-500 dark:text-gray-400">
                                #{ticket.ticketId}
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center">
                              <User className="w-4 h-4 text-gray-400 dark:text-gray-500 ml-2" />
                              <div>
                                <div className="text-sm font-medium text-gray-900 dark:text-white">
                                  {ticket.userId.name}
                                </div>
                                <div className="text-sm text-gray-500 dark:text-gray-400">
                                  {ticket.userId.email}
                                </div>
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center">
                              {getStatusIcon(ticket.status)}
                              <select
                                value={ticket.status}
                                onChange={(e) =>
                                  updateTicketStatus(
                                    ticket.ticketId,
                                    e.target.value,
                                  )
                                }
                                className="mr-2 text-sm border-none bg-transparent dark:bg-gray-800 dark:text-white focus:ring-0"
                              >
                                <option value="open">مفتوح</option>
                                <option value="in_progress">
                                  قيد المعالجة
                                </option>
                                <option value="closed">مغلق</option>
                              </select>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className="px-2 py-1 text-xs font-medium bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-300 rounded-full">
                              {getCategoryText(ticket.category)}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                            {new Date(ticket.createdAt).toLocaleDateString(
                              "ar-EG",
                            )}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                            <Link
                              to={`/support/tickets/${ticket.ticketId}`}
                              className="text-blue-600 dark:text-blue-400 hover:text-blue-900 dark:hover:text-blue-300 inline-flex items-center"
                            >
                              <Eye className="w-4 h-4 ml-1" />
                              عرض
                            </Link>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-center space-x-2 space-x-reverse mt-6">
                  <button
                    onClick={() =>
                      setCurrentPage((prev) => Math.max(prev - 1, 1))
                    }
                    disabled={currentPage === 1}
                    className="px-3 py-2 border border-gray-300 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                  >
                    السابق
                  </button>

                  {Array.from({ length: totalPages }, (_, i) => i + 1).map(
                    (page) => (
                      <button
                        key={page}
                        onClick={() => setCurrentPage(page)}
                        className={`px-3 py-2 rounded-lg ${
                          currentPage === page
                            ? "bg-blue-600 text-white"
                            : "border border-gray-300 hover:bg-gray-50"
                        }`}
                      >
                        {page}
                      </button>
                    ),
                  )}

                  <button
                    onClick={() =>
                      setCurrentPage((prev) => Math.min(prev + 1, totalPages))
                    }
                    disabled={currentPage === totalPages}
                    className="px-3 py-2 border border-gray-300 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                  >
                    التالي
                  </button>
                </div>
              )}
            </div>
          )}

          {/* FAQ Tab */}
          {activeTab === "faq" && (
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-lg font-semibold text-gray-900">
                  إدارة الأسئلة الشائعة
                </h2>
                <button
                  onClick={() => setShowFAQForm(true)}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 inline-flex items-center"
                >
                  <Plus className="w-4 h-4 ml-2" />
                  إضافة سؤال
                </button>
              </div>

              {/* FAQ Form */}
              {showFAQForm && (
                <div className="bg-gray-50 rounded-lg p-6 mb-6">
                  <h3 className="text-lg font-medium text-gray-900 mb-4">
                    {editingFAQ ? "تعديل السؤال" : "إضافة سؤال جديد"}
                  </h3>
                  <form onSubmit={handleFAQSubmit} className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        السؤال *
                      </label>
                      <input
                        type="text"
                        value={faqFormData.question}
                        onChange={(e) =>
                          setFaqFormData((prev) => ({
                            ...prev,
                            question: e.target.value,
                          }))
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        required
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        الإجابة *
                      </label>
                      <textarea
                        value={faqFormData.answer}
                        onChange={(e) =>
                          setFaqFormData((prev) => ({
                            ...prev,
                            answer: e.target.value,
                          }))
                        }
                        rows={4}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        required
                      />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          الفئة *
                        </label>
                        <select
                          value={faqFormData.category}
                          onChange={(e) =>
                            setFaqFormData((prev) => ({
                              ...prev,
                              category: e.target.value,
                            }))
                          }
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                          required
                        >
                          {faqCategoryOptions.map((option) => (
                            <option key={option.value} value={option.value}>
                              {option.label}
                            </option>
                          ))}
                        </select>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          الكلمات المفتاحية (مفصولة بفاصلة)
                        </label>
                        <input
                          type="text"
                          value={faqFormData.tags}
                          onChange={(e) =>
                            setFaqFormData((prev) => ({
                              ...prev,
                              tags: e.target.value,
                            }))
                          }
                          placeholder="مثال: واتساب، رسائل، تكامل"
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        />
                      </div>
                    </div>

                    <div className="flex justify-end space-x-4 space-x-reverse">
                      <button
                        type="button"
                        onClick={() => {
                          setShowFAQForm(false);
                          setEditingFAQ(null);
                          setFaqFormData({
                            question: "",
                            answer: "",
                            category: "general",
                            tags: "",
                            order: 0,
                          });
                        }}
                        className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                      >
                        إلغاء
                      </button>
                      <button
                        type="submit"
                        className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                      >
                        {editingFAQ ? "تحديث" : "إضافة"}
                      </button>
                    </div>
                  </form>
                </div>
              )}

              {/* FAQ List */}
              {faqsLoading ? (
                <div className="flex justify-center py-8">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 dark:border-blue-400"></div>
                </div>
              ) : (
                <div className="space-y-4">
                  {faqs.map((faq, index) => (
                    <div
                      key={faq._id || `faq-${index}`}
                      className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg p-6"
                    >
                      <div className="flex justify-between items-start mb-4">
                        <div className="flex-1">
                          <h4 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                            {faq.question}
                          </h4>
                          <p className="text-gray-600 dark:text-gray-300 mb-3 leading-relaxed">
                            {faq.answer}
                          </p>
                          <div className="flex items-center space-x-4 space-x-reverse text-sm text-gray-500 dark:text-gray-400">
                            <span className="bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-300 px-2 py-1 rounded">
                              {getCategoryText(faq.category)}
                            </span>
                            <span>👍 {faq.helpful}</span>
                            <span>👎 {faq.notHelpful}</span>
                            <span
                              className={`px-2 py-1 rounded text-xs ${
                                faq.isActive
                                  ? "bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300"
                                  : "bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300"
                              }`}
                            >
                              {faq.isActive ? "نشط" : "غير نشط"}
                            </span>
                          </div>
                        </div>
                        <div className="flex space-x-2 space-x-reverse mr-4">
                          <button
                            onClick={() => editFAQ(faq)}
                            className="p-2 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded"
                          >
                            <Edit className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => deleteFAQ(faq._id)}
                            className="p-2 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SupportAdmin;

/**
 * A/B Test Details Page
 *
 * صفحة تفاصيل اختبار A/B مع النتائج والتحليل
 */

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  PlayIcon,
  PauseIcon,
  ChartBarIcon,
  BeakerIcon,
  StarIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookAdTest,
  FacebookAdTestVariant,
} from "../../services/facebookAdsService";

const ABTestDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [test, setTest] = useState<FacebookAdTest | null>(null);
  const [loading, setLoading] = useState(true);
  const [analysis, setAnalysis] = useState<any>(null);
  const [analyzing, setAnalyzing] = useState(false);

  useEffect(() => {
    if (id) {
      loadTest();
    }
  }, [id]);

  const loadTest = async () => {
    try {
      setLoading(true);
      const data = await facebookAdsService.getAdTest(id!);
      setTest(data);
    } catch (error: any) {
      console.error("Error loading test:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل الاختبار");
    } finally {
      setLoading(false);
    }
  };

  const handleStartTest = async () => {
    if (!id) return;
    try {
      await facebookAdsService.startAdTest(id);
      toast.success("تم بدء الاختبار بنجاح");
      loadTest();
    } catch (error: any) {
      console.error("Error starting test:", error);
      toast.error(error?.response?.data?.error || "فشل في بدء الاختبار");
    }
  };

  const handlePauseTest = async () => {
    if (!id) return;
    try {
      await facebookAdsService.pauseAdTest(id);
      toast.success("تم إيقاف الاختبار بنجاح");
      loadTest();
    } catch (error: any) {
      console.error("Error pausing test:", error);
      toast.error(error?.response?.data?.error || "فشل في إيقاف الاختبار");
    }
  };

  const handleAnalyze = async () => {
    if (!id) return;
    try {
      setAnalyzing(true);
      const result = await facebookAdsService.analyzeAdTest(id);
      setAnalysis(result.analysis);
      setTest(result.test);
      toast.success("تم تحليل النتائج بنجاح");
    } catch (error: any) {
      console.error("Error analyzing test:", error);
      toast.error(error?.response?.data?.error || "فشل في تحليل النتائج");
    } finally {
      setAnalyzing(false);
    }
  };

  const handlePromoteWinner = async () => {
    if (!id) return;
    if (
      !window.confirm(
        "هل أنت متأكد من تعزيز الفائز؟ سيتم إيقاف المتغيرات الأخرى.",
      )
    )
      return;

    try {
      await facebookAdsService.promoteWinner(id);
      toast.success("تم تعزيز الفائز بنجاح");
      loadTest();
    } catch (error: any) {
      console.error("Error promoting winner:", error);
      toast.error(error?.response?.data?.error || "فشل في تعزيز الفائز");
    }
  };

  const getStatusBadge = (status: string) => {
    const badges = {
      DRAFT: "bg-gray-100 text-gray-800",
      RUNNING: "bg-green-100 text-green-800",
      PAUSED: "bg-yellow-100 text-yellow-800",
      COMPLETED: "bg-blue-100 text-blue-800",
      ARCHIVED: "bg-gray-100 text-gray-600",
    };
    return badges[status as keyof typeof badges] || "bg-gray-100 text-gray-800";
  };

  const getStatusLabel = (status: string) => {
    const labels = {
      DRAFT: "مسودة",
      RUNNING: "قيد التشغيل",
      PAUSED: "متوقف",
      COMPLETED: "مكتمل",
      ARCHIVED: "مؤرشف",
    };
    return labels[status as keyof typeof labels] || status;
  };

  if (loading) {
    return (
      <div className="text-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 mx-auto"></div>
        <p className="mt-4 text-gray-600">جاري التحميل...</p>
      </div>
    );
  }

  if (!test) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-600">الاختبار غير موجود</p>
      </div>
    );
  }

  const variants = test.variantsList || [];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <button
          onClick={() => navigate("/advertising/facebook-ads/tests")}
          className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          رجوع
        </button>
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">{test.name}</h1>
            {test.description && (
              <p className="mt-2 text-sm text-gray-600">{test.description}</p>
            )}
          </div>
          <div className="flex items-center gap-3">
            <span
              className={`px-3 py-1 text-sm font-medium rounded-full ${getStatusBadge(test.status)}`}
            >
              {getStatusLabel(test.status)}
            </span>
            {test.status === "DRAFT" && (
              <button
                onClick={handleStartTest}
                className="flex items-center gap-2 px-4 py-2 text-white bg-green-600 rounded-lg hover:bg-green-700"
              >
                <PlayIcon className="w-5 h-5" />
                بدء الاختبار
              </button>
            )}
            {test.status === "RUNNING" && (
              <>
                <button
                  onClick={handleAnalyze}
                  disabled={analyzing}
                  className="flex items-center gap-2 px-4 py-2 text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100 disabled:opacity-50"
                >
                  <ChartBarIcon className="w-5 h-5" />
                  {analyzing ? "جارٍ التحليل..." : "تحليل النتائج"}
                </button>
                <button
                  onClick={handlePauseTest}
                  className="flex items-center gap-2 px-4 py-2 text-yellow-600 bg-yellow-50 rounded-lg hover:bg-yellow-100"
                >
                  <PauseIcon className="w-5 h-5" />
                  إيقاف
                </button>
              </>
            )}
            {test.status === "PAUSED" && (
              <button
                onClick={handleStartTest}
                className="flex items-center gap-2 px-4 py-2 text-white bg-green-600 rounded-lg hover:bg-green-700"
              >
                <PlayIcon className="w-5 h-5" />
                استئناف
              </button>
            )}
            {test.winnerVariantId && test.status === "RUNNING" && (
              <button
                onClick={handlePromoteWinner}
                className="flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
              >
                <StarIcon className="w-5 h-5" />
                تعزيز الفائز
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Test Info */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-lg shadow">
          <div className="text-sm text-gray-500">نوع الاختبار</div>
          <div className="mt-1 text-lg font-semibold text-gray-900">
            {test.testType}
          </div>
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <div className="text-sm text-gray-500">عدد المتغيرات</div>
          <div className="mt-1 text-lg font-semibold text-gray-900">
            {variants.length}
          </div>
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <div className="text-sm text-gray-500">توزيع حركة المرور</div>
          <div className="mt-1 text-lg font-semibold text-gray-900">
            {test.trafficSplit}% / {100 - test.trafficSplit}%
          </div>
        </div>
      </div>

      {/* Statistics */}
      {test.totalImpressions > 0 && (
        <div className="bg-white p-6 rounded-lg shadow">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">
            الإحصائيات الإجمالية
          </h2>
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
            <div>
              <div className="text-sm text-gray-500">المشاهدات</div>
              <div className="mt-1 text-xl font-semibold text-gray-900">
                {test.totalImpressions.toLocaleString()}
              </div>
            </div>
            <div>
              <div className="text-sm text-gray-500">النقرات</div>
              <div className="mt-1 text-xl font-semibold text-gray-900">
                {test.totalClicks.toLocaleString()}
              </div>
            </div>
            <div>
              <div className="text-sm text-gray-500">التحويلات</div>
              <div className="mt-1 text-xl font-semibold text-gray-900">
                {test.totalConversions.toLocaleString()}
              </div>
            </div>
            <div>
              <div className="text-sm text-gray-500">الإنفاق</div>
              <div className="mt-1 text-xl font-semibold text-gray-900">
                {test.totalSpend.toFixed(2)} EGP
              </div>
            </div>
            {test.confidenceLevel && (
              <div>
                <div className="text-sm text-gray-500">مستوى الثقة</div>
                <div className="mt-1 text-xl font-semibold text-indigo-600">
                  {test.confidenceLevel.toFixed(1)}%
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Analysis Results */}
      {analysis && (
        <div className="bg-white p-6 rounded-lg shadow">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">
            نتائج التحليل الإحصائي
          </h2>
          <div className="space-y-4">
            {analysis.pValue !== null && (
              <div className="p-4 bg-indigo-50 rounded-lg">
                <div className="flex items-center justify-between">
                  <div>
                    <div className="font-medium text-gray-900">P-value</div>
                    <div className="text-sm text-gray-600">
                      القيمة الإحصائية
                    </div>
                  </div>
                  <div className="text-2xl font-bold text-indigo-600">
                    {analysis.pValue.toFixed(4)}
                  </div>
                </div>
                {analysis.isSignificant && (
                  <div className="mt-2 text-sm text-green-600 font-medium">
                    ✓ النتيجة إحصائياً معنوية (95% ثقة)
                  </div>
                )}
              </div>
            )}
            {analysis.winner && (
              <div className="p-4 bg-green-50 rounded-lg border-2 border-green-500">
                <div className="flex items-center gap-2 mb-2">
                  <StarIcon className="w-6 h-6 text-green-600" />
                  <div className="font-semibold text-green-900">الفائز</div>
                </div>
                <div className="text-lg font-medium text-green-800">
                  {analysis.winner.winner === "VARIANT_A"
                    ? "Variant A"
                    : "Variant B"}
                </div>
                <div className="text-sm text-green-700 mt-1">
                  تحسن بنسبة {analysis.winner.improvement}%
                </div>
              </div>
            )}
            {analysis.recommendation && (
              <div className="p-4 bg-blue-50 rounded-lg">
                <div className="text-sm font-medium text-blue-900">
                  التوصية:
                </div>
                <div className="text-sm text-blue-800 mt-1">
                  {analysis.recommendation}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Variants */}
      <div className="bg-white rounded-lg shadow">
        <div className="p-6 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-gray-900">
            المتغيرات (Variants)
          </h2>
        </div>
        <div className="divide-y divide-gray-200">
          {variants.map((variant) => (
            <div
              key={variant.id}
              className={`p-6 ${
                variant.isWinner
                  ? "bg-green-50 border-l-4 border-green-500"
                  : ""
              }`}
            >
              <div className="flex items-center justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-3">
                    <h3 className="font-semibold text-gray-900">
                      {variant.name}
                    </h3>
                    <span className="px-2 py-1 text-xs font-medium rounded-full bg-gray-100 text-gray-800">
                      {variant.variantType}
                    </span>
                    {variant.isWinner && (
                      <span className="flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-full bg-green-100 text-green-800">
                        <StarIcon className="w-4 h-4" />
                        الفائز
                      </span>
                    )}
                  </div>
                  <div className="mt-4 grid grid-cols-2 md:grid-cols-5 gap-4">
                    <div>
                      <div className="text-sm text-gray-500">المشاهدات</div>
                      <div className="mt-1 text-lg font-semibold text-gray-900">
                        {variant.impressions.toLocaleString()}
                      </div>
                    </div>
                    <div>
                      <div className="text-sm text-gray-500">النقرات</div>
                      <div className="mt-1 text-lg font-semibold text-gray-900">
                        {variant.clicks.toLocaleString()}
                      </div>
                    </div>
                    <div>
                      <div className="text-sm text-gray-500">CTR</div>
                      <div className="mt-1 text-lg font-semibold text-gray-900">
                        {(variant.ctr || 0).toFixed(2)}%
                      </div>
                    </div>
                    <div>
                      <div className="text-sm text-gray-500">CPC</div>
                      <div className="mt-1 text-lg font-semibold text-gray-900">
                        {(variant.cpc || 0).toFixed(2)} EGP
                      </div>
                    </div>
                    <div>
                      <div className="text-sm text-gray-500">الإنفاق</div>
                      <div className="mt-1 text-lg font-semibold text-gray-900">
                        {(variant.spend || 0).toFixed(2)} EGP
                      </div>
                    </div>
                  </div>
                  {variant.pValue !== null && variant.pValue !== undefined && (
                    <div className="mt-4 text-sm text-gray-600">
                      P-value: {variant.pValue.toFixed(4)} | Confidence:{" "}
                      {variant.confidenceLevel?.toFixed(1)}%
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ABTestDetails;

/**
 * A/B Tests Management Page
 *
 * صفحة إدارة اختبارات A/B للإعلانات
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  PlusIcon,
  PlayIcon,
  PauseIcon,
  TrashIcon,
  EyeIcon,
  ChartBarIcon,
  BeakerIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookAdTest,
} from "../../services/facebookAdsService";
import { useTheme } from "../../hooks/useTheme";

const ABTestsManagement: React.FC = () => {
  const navigate = useNavigate();
  const { derivedTheme } = useTheme();
  const [tests, setTests] = useState<FacebookAdTest[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<
    "all" | "DRAFT" | "RUNNING" | "PAUSED" | "COMPLETED"
  >("all");

  useEffect(() => {
    loadTests();
  }, [filter]);

  const loadTests = async () => {
    try {
      setLoading(true);
      const data = await facebookAdsService.getAdTests(
        filter === "all" ? undefined : filter,
      );
      setTests(data);
    } catch (error: any) {
      console.error("Error loading tests:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل الاختبارات");
    } finally {
      setLoading(false);
    }
  };

  const handleStartTest = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await facebookAdsService.startAdTest(id);
      toast.success("تم بدء الاختبار بنجاح");
      loadTests();
    } catch (error: any) {
      console.error("Error starting test:", error);
      toast.error(error?.response?.data?.error || "فشل في بدء الاختبار");
    }
  };

  const handlePauseTest = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await facebookAdsService.pauseAdTest(id);
      toast.success("تم إيقاف الاختبار بنجاح");
      loadTests();
    } catch (error: any) {
      console.error("Error pausing test:", error);
      toast.error(error?.response?.data?.error || "فشل في إيقاف الاختبار");
    }
  };

  const handleDeleteTest = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!window.confirm("هل أنت متأكد من حذف هذا الاختبار؟")) return;

    try {
      await facebookAdsService.deleteAdTest(id);
      toast.success("تم حذف الاختبار بنجاح");
      loadTests();
    } catch (error: any) {
      console.error("Error deleting test:", error);
      toast.error(error?.response?.data?.error || "فشل في حذف الاختبار");
    }
  };

  const getStatusBadge = (status: string) => {
    const badges = {
      DRAFT:
        derivedTheme === "dark"
          ? "bg-gray-700 text-gray-300"
          : "bg-gray-100 text-gray-800",
      RUNNING:
        derivedTheme === "dark"
          ? "bg-green-900 text-green-300"
          : "bg-green-100 text-green-800",
      PAUSED:
        derivedTheme === "dark"
          ? "bg-yellow-900 text-yellow-300"
          : "bg-yellow-100 text-yellow-800",
      COMPLETED:
        derivedTheme === "dark"
          ? "bg-blue-900 text-blue-300"
          : "bg-blue-100 text-blue-800",
      ARCHIVED:
        derivedTheme === "dark"
          ? "bg-gray-700 text-gray-400"
          : "bg-gray-100 text-gray-600",
    };
    return (
      badges[status as keyof typeof badges] ||
      (derivedTheme === "dark"
        ? "bg-gray-700 text-gray-300"
        : "bg-gray-100 text-gray-800")
    );
  };

  const getStatusLabel = (status: string) => {
    const labels = {
      DRAFT: "مسودة",
      RUNNING: "قيد التشغيل",
      PAUSED: "متوقف",
      COMPLETED: "مكتمل",
      ARCHIVED: "مؤرشف",
    };
    return labels[status as keyof typeof labels] || status;
  };

  const getTestTypeLabel = (type: string) => {
    const labels = {
      CREATIVE: "Creative",
      TARGETING: "Targeting",
      BUDGET: "Budget",
      PLACEMENT: "Placement",
    };
    return labels[type as keyof typeof labels] || type;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1
            className={`text-3xl font-bold ${derivedTheme === "dark" ? "text-white" : "text-gray-900"}`}
          >
            اختبارات A/B
          </h1>
          <p
            className={`mt-2 text-sm ${derivedTheme === "dark" ? "text-gray-400" : "text-gray-600"}`}
          >
            إدارة اختبارات A/B لتحسين أداء الإعلانات
          </p>
        </div>
        <button
          onClick={() => navigate("/advertising/facebook-ads/tests/create")}
          className="flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
        >
          <PlusIcon className="w-5 h-5" />
          إنشاء اختبار جديد
        </button>
      </div>

      {/* Filters */}
      <div
        className={`${derivedTheme === "dark" ? "bg-gray-800 border-gray-700" : "bg-white"} p-4 rounded-lg shadow`}
      >
        <div className="flex items-center gap-2">
          <span
            className={`text-sm font-medium ${derivedTheme === "dark" ? "text-gray-300" : "text-gray-700"}`}
          >
            التصفية:
          </span>
          {["all", "DRAFT", "RUNNING", "PAUSED", "COMPLETED"].map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status as any)}
              className={`px-3 py-1 text-sm rounded-lg ${
                filter === status
                  ? "bg-indigo-600 text-white"
                  : derivedTheme === "dark"
                    ? "bg-gray-700 text-gray-300 hover:bg-gray-600"
                    : "bg-gray-100 text-gray-700 hover:bg-gray-200"
              }`}
            >
              {status === "all" ? "الكل" : getStatusLabel(status)}
            </button>
          ))}
        </div>
      </div>

      {/* Tests List */}
      <div
        className={`${derivedTheme === "dark" ? "bg-gray-800 border-gray-700" : "bg-white"} rounded-lg shadow`}
      >
        {loading ? (
          <div className="text-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 mx-auto"></div>
            <p
              className={`mt-4 ${derivedTheme === "dark" ? "text-gray-400" : "text-gray-600"}`}
            >
              جاري التحميل...
            </p>
          </div>
        ) : tests.length === 0 ? (
          <div className="text-center py-12">
            <BeakerIcon
              className={`w-16 h-16 ${derivedTheme === "dark" ? "text-gray-500" : "text-gray-400"} mx-auto mb-4`}
            />
            <p
              className={`mb-4 ${derivedTheme === "dark" ? "text-gray-400" : "text-gray-600"}`}
            >
              لا توجد اختبارات
            </p>
            <button
              onClick={() => navigate("/advertising/facebook-ads/tests/create")}
              className="inline-flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
            >
              <PlusIcon className="w-5 h-5" />
              إنشاء اختبار جديد
            </button>
          </div>
        ) : (
          <div
            className={`divide-y ${derivedTheme === "dark" ? "divide-gray-700" : "divide-gray-200"}`}
          >
            {tests.map((test) => (
              <div
                key={test.id}
                onClick={() =>
                  navigate(`/advertising/facebook-ads/tests/${test.id}`)
                }
                className={`p-6 ${derivedTheme === "dark" ? "hover:bg-gray-700" : "hover:bg-gray-50"} cursor-pointer`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-3">
                      <h3
                        className={`font-semibold ${derivedTheme === "dark" ? "text-white" : "text-gray-900"}`}
                      >
                        {test.name}
                      </h3>
                      <span
                        className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusBadge(test.status)}`}
                      >
                        {getStatusLabel(test.status)}
                      </span>
                      <span
                        className={`px-2 py-1 text-xs font-medium rounded-full ${derivedTheme === "dark" ? "bg-indigo-900 text-indigo-300" : "bg-indigo-100 text-indigo-800"}`}
                      >
                        {getTestTypeLabel(test.testType)}
                      </span>
                    </div>
                    {test.description && (
                      <p
                        className={`mt-1 text-sm ${derivedTheme === "dark" ? "text-gray-400" : "text-gray-600"}`}
                      >
                        {test.description}
                      </p>
                    )}
                    <div
                      className={`mt-3 flex items-center gap-6 text-sm ${derivedTheme === "dark" ? "text-gray-400" : "text-gray-600"}`}
                    >
                      {test.variantsList && (
                        <span>{test.variantsList.length} متغير</span>
                      )}
                      {test.totalImpressions > 0 && (
                        <>
                          <span>
                            {test.totalImpressions.toLocaleString()} مشاهدة
                          </span>
                          <span>{test.totalClicks.toLocaleString()} نقرة</span>
                          {test.confidenceLevel && (
                            <span
                              className={`font-medium ${derivedTheme === "dark" ? "text-indigo-400" : "text-indigo-600"}`}
                            >
                              {test.confidenceLevel.toFixed(1)}% ثقة
                            </span>
                          )}
                        </>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {test.status === "DRAFT" && (
                      <button
                        onClick={(e) => handleStartTest(test.id, e)}
                        className={`p-2 ${derivedTheme === "dark" ? "text-green-400 hover:bg-green-900" : "text-green-600 hover:bg-green-50"} rounded-lg`}
                        title="بدء الاختبار"
                      >
                        <PlayIcon className="w-5 h-5" />
                      </button>
                    )}
                    {test.status === "RUNNING" && (
                      <button
                        onClick={(e) => handlePauseTest(test.id, e)}
                        className={`p-2 ${derivedTheme === "dark" ? "text-yellow-400 hover:bg-yellow-900" : "text-yellow-600 hover:bg-yellow-50"} rounded-lg`}
                        title="إيقاف الاختبار"
                      >
                        <PauseIcon className="w-5 h-5" />
                      </button>
                    )}
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate(`/advertising/facebook-ads/tests/${test.id}`);
                      }}
                      className={`p-2 ${derivedTheme === "dark" ? "text-indigo-400 hover:bg-indigo-900" : "text-indigo-600 hover:bg-indigo-50"} rounded-lg`}
                      title="عرض التفاصيل"
                    >
                      <EyeIcon className="w-5 h-5" />
                    </button>
                    {test.status !== "RUNNING" && (
                      <button
                        onClick={(e) => handleDeleteTest(test.id, e)}
                        className={`p-2 ${derivedTheme === "dark" ? "text-red-400 hover:bg-red-900" : "text-red-600 hover:bg-red-50"} rounded-lg`}
                        title="حذف"
                      >
                        <TrashIcon className="w-5 h-5" />
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default ABTestsManagement;

/**
 * 👁️ Ad Preview
 *
 * معاينة الإعلانات قبل النشر
 */

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  Eye,
  Smartphone,
  Monitor,
  RefreshCw,
  Loader2,
  ArrowLeft,
  Facebook,
  Instagram,
  MessageCircle,
  Layout,
  Image,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

type PreviewFormat =
  | "DESKTOP_FEED_STANDARD"
  | "MOBILE_FEED_STANDARD"
  | "INSTAGRAM_STANDARD"
  | "INSTAGRAM_STORY"
  | "MESSENGER_MOBILE_INBOX_MEDIA"
  | "RIGHT_COLUMN_STANDARD";

const AdPreview: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [previewData, setPreviewData] = useState<any>(null);
  const [selectedFormat, setSelectedFormat] = useState<PreviewFormat>(
    "MOBILE_FEED_STANDARD",
  );

  const [formData, setFormData] = useState({
    creativeId: "",
  });

  const previewFormats = [
    {
      id: "MOBILE_FEED_STANDARD" as const,
      label: "موبايل - Feed",
      icon: Smartphone,
      platform: "facebook",
    },
    {
      id: "DESKTOP_FEED_STANDARD" as const,
      label: "سطح المكتب - Feed",
      icon: Monitor,
      platform: "facebook",
    },
    {
      id: "INSTAGRAM_STANDARD" as const,
      label: "Instagram Feed",
      icon: Instagram,
      platform: "instagram",
    },
    {
      id: "INSTAGRAM_STORY" as const,
      label: "Instagram Story",
      icon: Smartphone,
      platform: "instagram",
    },
    {
      id: "MESSENGER_MOBILE_INBOX_MEDIA" as const,
      label: "Messenger",
      icon: MessageCircle,
      platform: "messenger",
    },
    {
      id: "RIGHT_COLUMN_STANDARD" as const,
      label: "العمود الأيمن",
      icon: Layout,
      platform: "facebook",
    },
  ];

  const handlePreview = async () => {
    if (!formData.creativeId.trim()) {
      toast.error("يرجى إدخال معرف الإعلان الإبداعي");
      return;
    }

    try {
      setLoading(true);
      const result = await facebookAdsService.getAdPreview(
        formData.creativeId,
        selectedFormat,
      );
      setPreviewData(result);
      toast.success("تم تحميل المعاينة بنجاح");
    } catch (error: any) {
      console.error("Error loading preview:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل المعاينة");
    } finally {
      setLoading(false);
    }
  };

  const getPlatformColor = (platform: string) => {
    switch (platform) {
      case "facebook":
        return "blue";
      case "instagram":
        return "pink";
      case "messenger":
        return "purple";
      default:
        return "gray";
    }
  };

  return (
    <div className="p-6 space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button
          onClick={() => navigate("/advertising/facebook-ads")}
          className="p-2 hover:bg-gray-100 rounded-lg"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Eye className="w-7 h-7 text-indigo-600" />
            معاينة الإعلان
          </h1>
          <p className="text-gray-600 mt-1">
            شاهد كيف سيظهر إعلانك على مختلف المنصات
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Settings Panel */}
        <div className="lg:col-span-1 space-y-6">
          {/* Creative ID Input */}
          <div className="bg-white rounded-xl shadow-sm border p-6">
            <h2 className="text-lg font-semibold text-gray-900 mb-4">
              إعدادات المعاينة
            </h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  معرف الإعلان الإبداعي (Creative ID) *
                </label>
                <input
                  type="text"
                  value={formData.creativeId}
                  onChange={(e) => setFormData({ creativeId: e.target.value })}
                  placeholder="أدخل معرف Creative"
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <button
                onClick={handlePreview}
                disabled={loading || !formData.creativeId.trim()}
                className="w-full py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {loading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    جاري التحميل...
                  </>
                ) : (
                  <>
                    <Eye className="w-4 h-4" />
                    عرض المعاينة
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Format Selection */}
          <div className="bg-white rounded-xl shadow-sm border p-6">
            <h2 className="text-lg font-semibold text-gray-900 mb-4">
              تنسيق العرض
            </h2>

            <div className="space-y-2">
              {previewFormats.map((format) => {
                const Icon = format.icon;
                const isSelected = selectedFormat === format.id;
                const color = getPlatformColor(format.platform);

                return (
                  <button
                    key={format.id}
                    onClick={() => {
                      setSelectedFormat(format.id);
                      if (previewData) handlePreview();
                    }}
                    className={`w-full p-3 rounded-lg border-2 transition-all flex items-center gap-3 ${
                      isSelected
                        ? `border-${color}-500 bg-${color}-50`
                        : "border-gray-200 hover:border-gray-300"
                    }`}
                  >
                    <Icon
                      className={`w-5 h-5 ${isSelected ? `text-${color}-600` : "text-gray-400"}`}
                    />
                    <span
                      className={`text-sm font-medium ${isSelected ? `text-${color}-700` : "text-gray-700"}`}
                    >
                      {format.label}
                    </span>
                    {format.platform === "instagram" && (
                      <Instagram className="w-4 h-4 text-pink-500 mr-auto" />
                    )}
                    {format.platform === "facebook" && (
                      <Facebook className="w-4 h-4 text-blue-500 mr-auto" />
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Preview Panel */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
            <div className="p-4 border-b bg-gray-50 flex items-center justify-between">
              <h2 className="font-semibold text-gray-900">المعاينة</h2>
              {previewData && (
                <button
                  onClick={handlePreview}
                  className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-lg"
                >
                  <RefreshCw className="w-4 h-4" />
                </button>
              )}
            </div>

            <div className="p-6 min-h-[500px] flex items-center justify-center bg-gray-100">
              {loading ? (
                <div className="text-center">
                  <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mx-auto mb-4" />
                  <p className="text-gray-600">جاري تحميل المعاينة...</p>
                </div>
              ) : previewData ? (
                <div className="w-full max-w-md">
                  {/* Device Frame */}
                  <div
                    className={`mx-auto ${
                      selectedFormat.includes("MOBILE") ||
                      selectedFormat.includes("STORY")
                        ? "max-w-[375px]"
                        : "max-w-full"
                    }`}
                  >
                    {selectedFormat.includes("STORY") ? (
                      // Story Format
                      <div className="bg-black rounded-3xl p-2 shadow-2xl">
                        <div className="bg-gray-900 rounded-2xl overflow-hidden aspect-[9/16]">
                          {previewData.body ? (
                            <div
                              dangerouslySetInnerHTML={{
                                __html: previewData.body,
                              }}
                            />
                          ) : (
                            <div className="h-full flex items-center justify-center text-white">
                              <Image className="w-16 h-16 opacity-50" />
                            </div>
                          )}
                        </div>
                      </div>
                    ) : selectedFormat.includes("MOBILE") ? (
                      // Mobile Format
                      <div className="bg-gray-800 rounded-3xl p-3 shadow-2xl">
                        <div className="bg-white rounded-2xl overflow-hidden">
                          {previewData.body ? (
                            <div
                              dangerouslySetInnerHTML={{
                                __html: previewData.body,
                              }}
                            />
                          ) : (
                            <div className="aspect-square flex items-center justify-center bg-gray-100">
                              <Image className="w-16 h-16 text-gray-300" />
                            </div>
                          )}
                        </div>
                      </div>
                    ) : (
                      // Desktop Format
                      <div className="bg-white rounded-lg shadow-lg overflow-hidden">
                        {previewData.body ? (
                          <div
                            dangerouslySetInnerHTML={{
                              __html: previewData.body,
                            }}
                          />
                        ) : (
                          <div className="aspect-video flex items-center justify-center bg-gray-100">
                            <Image className="w-16 h-16 text-gray-300" />
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ) : (
                <div className="text-center">
                  <Eye className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                  <p className="text-gray-500 mb-2">
                    أدخل معرف الإعلان الإبداعي لعرض المعاينة
                  </p>
                  <p className="text-sm text-gray-400">
                    يمكنك الحصول على المعرف من صفحة إدارة الإعلانات
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* Tips */}
          <div className="mt-4 bg-indigo-50 border border-indigo-200 rounded-lg p-4">
            <h3 className="font-medium text-indigo-900 mb-2">
              💡 نصائح للمعاينة
            </h3>
            <ul className="text-sm text-indigo-700 space-y-1">
              <li>• تأكد من أن الإعلان يظهر بشكل جيد على جميع الأجهزة</li>
              <li>• راجع النصوص والصور قبل النشر</li>
              <li>• اختبر الروابط للتأكد من عملها بشكل صحيح</li>
              <li>• تحقق من ظهور زر الإجراء بوضوح</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdPreview;

/**
 * 🛒 Advantage+ Shopping Campaign
 *
 * صفحة إنشاء حملات التسوق الذكية من Facebook
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  ShoppingBag,
  Sparkles,
  Globe,
  DollarSign,
  Target,
  Zap,
  CheckCircle,
  Loader2,
  ArrowLeft,
  TrendingUp,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

const AdvantagePlusShopping: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [catalogs, setCatalogs] = useState<any[]>([]);
  const [loadingCatalogs, setLoadingCatalogs] = useState(true);

  const [formData, setFormData] = useState({
    name: "",
    status: "PAUSED" as "ACTIVE" | "PAUSED",
    budgetType: "DAILY" as "DAILY" | "LIFETIME",
    budgetAmount: 50,
    catalogId: "",
    pixelId: "",
    countryTargeting: ["SA", "AE", "EG"],
  });

  const countries = [
    { code: "SA", name: "السعودية", flag: "🇸🇦" },
    { code: "AE", name: "الإمارات", flag: "🇦🇪" },
    { code: "EG", name: "مصر", flag: "🇪🇬" },
    { code: "KW", name: "الكويت", flag: "🇰🇼" },
    { code: "QA", name: "قطر", flag: "🇶🇦" },
    { code: "BH", name: "البحرين", flag: "🇧🇭" },
    { code: "OM", name: "عمان", flag: "🇴🇲" },
    { code: "JO", name: "الأردن", flag: "🇯🇴" },
    { code: "LB", name: "لبنان", flag: "🇱🇧" },
    { code: "MA", name: "المغرب", flag: "🇲🇦" },
  ];

  useEffect(() => {
    loadCatalogs();
  }, []);

  const loadCatalogs = async () => {
    try {
      setLoadingCatalogs(true);
      const data = await facebookAdsService.getCatalogs();
      setCatalogs(data);
    } catch (error) {
      console.error("Error loading catalogs:", error);
    } finally {
      setLoadingCatalogs(false);
    }
  };

  const toggleCountry = (code: string) => {
    setFormData((prev) => ({
      ...prev,
      countryTargeting: prev.countryTargeting.includes(code)
        ? prev.countryTargeting.filter((c) => c !== code)
        : [...prev.countryTargeting, code],
    }));
  };

  const handleSubmit = async () => {
    if (!formData.name.trim()) {
      toast.error("يرجى إدخال اسم الحملة");
      return;
    }

    if (!formData.pixelId.trim()) {
      toast.error("يرجى إدخال معرف Facebook Pixel");
      return;
    }

    if (formData.budgetAmount < 1) {
      toast.error("يرجى إدخال ميزانية صحيحة");
      return;
    }

    if (formData.countryTargeting.length === 0) {
      toast.error("يرجى اختيار دولة واحدة على الأقل");
      return;
    }

    try {
      setLoading(true);
      const campaignPayload: any = {
        name: formData.name,
        status: formData.status,
        budgetType: formData.budgetType,
        budgetAmount: formData.budgetAmount,
        pixelId: formData.pixelId,
        countryTargeting: formData.countryTargeting,
      };
      if (formData.catalogId) campaignPayload.catalogId = formData.catalogId;
      await facebookAdsService.createAdvantagePlusShoppingCampaign(
        campaignPayload,
      );

      toast.success("تم إنشاء حملة Advantage+ Shopping بنجاح! 🛒");
      navigate("/advertising/facebook-ads");
    } catch (error: any) {
      console.error("Error creating campaign:", error);
      toast.error(error?.response?.data?.error || "فشل في إنشاء الحملة");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="p-6 space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900"
      dir="rtl"
