                </button>
              </div>
            </div>

            <div>
              <label
                htmlFor="advantage-plus-budget-amount"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
              >
                المبلغ ({formData.budgetType === "DAILY" ? "يومياً" : "إجمالي"})
