              </label>
              <div className="relative">
                <DollarSign className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500" />
                <input
                  id="advantage-plus-budget-amount"
                  name="budgetAmount"
                  type="number"
                  autoComplete="off"
