                      ...prev,
                      budgetAmount: Number(e.target.value),
                    }))
                  }
                  min={1}
                  className="w-full pr-10 pl-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-green-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Country Targeting */}
        <div className="p-6 border-b border-gray-200 dark:border-gray-600">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <Globe className="w-5 h-5 text-green-600 dark:text-green-400" />
            الدول المستهدفة
          </h2>
          <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
            {countries.map((country) => {
              const isSelected = formData.countryTargeting.includes(
                country.code,
              );
              return (
                <button
                  key={country.code}
                  onClick={() => toggleCountry(country.code)}
                  className={`p-3 rounded-lg border-2 transition-all ${
                    isSelected
                      ? "border-green-500 dark:border-green-400 bg-green-50 dark:bg-green-900/20"
                      : "border-gray-200 dark:border-gray-600 hover:border-gray-300 dark:hover:border-gray-500 bg-white dark:bg-gray-700"
                  }`}
                >
                  <div className="text-2xl mb-1">{country.flag}</div>
                  <div
                    className={`text-sm font-medium ${isSelected ? "text-green-700 dark:text-green-300" : "text-gray-700 dark:text-gray-300"}`}
                  >
                    {country.name}
                  </div>
                  {isSelected && (
                    <CheckCircle className="w-4 h-4 text-green-600 dark:text-green-400 mx-auto mt-1" />
                  )}
                </button>
              );
            })}
          </div>
        </div>

        {/* Status */}
        <div className="p-6 border-b border-gray-200 dark:border-gray-600">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            حالة الحملة
          </h2>
          <div className="flex gap-3">
            <button
              onClick={() =>
                setFormData((prev) => ({ ...prev, status: "PAUSED" }))
              }
              className={`flex-1 p-4 rounded-lg border-2 transition-all ${
                formData.status === "PAUSED"
                  ? "border-yellow-500 dark:border-yellow-400 bg-yellow-50 dark:bg-yellow-900/20"
                  : "border-gray-200 dark:border-gray-600 hover:border-gray-300 dark:hover:border-gray-500 bg-white dark:bg-gray-700"
              }`}
            >
              <div className="font-medium text-gray-900 dark:text-white">
                متوقفة
              </div>
              <div className="text-sm text-gray-500 dark:text-gray-400">
                ستبدأ عند التفعيل يدوياً
              </div>
            </button>
            <button
              onClick={() =>
                setFormData((prev) => ({ ...prev, status: "ACTIVE" }))
              }
              className={`flex-1 p-4 rounded-lg border-2 transition-all ${
                formData.status === "ACTIVE"
                  ? "border-green-500 dark:border-green-400 bg-green-50 dark:bg-green-900/20"
                  : "border-gray-200 dark:border-gray-600 hover:border-gray-300 dark:hover:border-gray-500 bg-white dark:bg-gray-700"
              }`}
            >
              <div className="font-medium text-gray-900 dark:text-white">
                نشطة
              </div>
              <div className="text-sm text-gray-500 dark:text-gray-400">
                ستبدأ فوراً بعد الإنشاء
              </div>
            </button>
          </div>
        </div>

        {/* Actions */}
        <div className="p-6 bg-gray-50 dark:bg-gray-700 flex gap-3 justify-end">
          <button
            onClick={() => navigate("/advertising/facebook-ads")}
            className="px-6 py-2 text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            إلغاء
          </button>
          <button
            onClick={handleSubmit}
            disabled={loading}
            className="px-6 py-2 text-white bg-green-600 dark:bg-green-500 rounded-lg hover:bg-green-700 dark:hover:bg-green-600 disabled:opacity-50 flex items-center gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                جاري الإنشاء...
              </>
            ) : (
              <>
                <ShoppingBag className="w-4 h-4" />
                إنشاء الحملة
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AdvantagePlusShopping;

/**
 * 📊 Async Reports Management
 *
 * صفحة إدارة التقارير المتقدمة (Async Reports)
 * v22.0 Feature
 */

import React, { useState, useEffect } from "react";
import { toast } from "react-hot-toast";
import {
  FileText,
  Plus,
  Download,
  RefreshCw,
  Clock,
  CheckCircle,
  XCircle,
  Loader2,
  Calendar,
  BarChart3,
  TrendingUp,
  Filter,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

// ============================================
// Types
// ============================================

interface AsyncReport {
  id: string;
  name: string;
  status: "PENDING" | "RUNNING" | "COMPLETED" | "FAILED";
  level: string;
  dateRange: { start: string; end: string };
  metrics: string[];
  createdAt: string;
  completedAt?: string;
  downloadUrl?: string;
}

interface CreateReportForm {
  name: string;
  level: "campaign" | "adset" | "ad";
  datePreset: string;
  startDate: string;
  endDate: string;
  metrics: string[];
  breakdowns: string[];
}

// ============================================
// Constants
// ============================================

const REPORT_LEVELS = [
  { value: "campaign", label: "الحملات" },
  { value: "adset", label: "المجموعات الإعلانية" },
  { value: "ad", label: "الإعلانات" },
];

const DATE_PRESETS = [
  { value: "today", label: "اليوم" },
  { value: "yesterday", label: "أمس" },
  { value: "last_7d", label: "آخر 7 أيام" },
  { value: "last_14d", label: "آخر 14 يوم" },
  { value: "last_30d", label: "آخر 30 يوم" },
  { value: "this_month", label: "هذا الشهر" },
  { value: "last_month", label: "الشهر الماضي" },
  { value: "custom", label: "تاريخ مخصص" },
];

const AVAILABLE_METRICS = [
  { value: "impressions", label: "مرات الظهور", category: "الأداء" },
  { value: "reach", label: "الوصول", category: "الأداء" },
  { value: "frequency", label: "التكرار", category: "الأداء" },
  { value: "clicks", label: "النقرات", category: "الأداء" },
  { value: "ctr", label: "معدل النقر (CTR)", category: "الأداء" },
  { value: "spend", label: "الإنفاق", category: "التكلفة" },
  { value: "cpc", label: "تكلفة النقرة (CPC)", category: "التكلفة" },
  { value: "cpm", label: "تكلفة الألف ظهور (CPM)", category: "التكلفة" },
  { value: "conversions", label: "التحويلات", category: "التحويلات" },
  {
    value: "cost_per_conversion",
    label: "تكلفة التحويل",
    category: "التحويلات",
  },
  { value: "conversion_rate", label: "معدل التحويل", category: "التحويلات" },
  {
    value: "purchase_roas",
    label: "العائد على الإنفاق (ROAS)",
    category: "التحويلات",
  },
  { value: "video_views", label: "مشاهدات الفيديو", category: "الفيديو" },
  { value: "video_p25_watched", label: "مشاهدة 25%", category: "الفيديو" },
  { value: "video_p50_watched", label: "مشاهدة 50%", category: "الفيديو" },
  { value: "video_p75_watched", label: "مشاهدة 75%", category: "الفيديو" },
  { value: "video_p100_watched", label: "مشاهدة كاملة", category: "الفيديو" },
];

const AVAILABLE_BREAKDOWNS = [
  { value: "age", label: "العمر" },
  { value: "gender", label: "الجنس" },
  { value: "country", label: "الدولة" },
  { value: "region", label: "المنطقة" },
  { value: "device_platform", label: "الجهاز" },
  { value: "publisher_platform", label: "المنصة" },
  { value: "placement", label: "الموضع" },
];

// ============================================
// Component
// ============================================

const AsyncReports: React.FC = () => {
  const [reports, setReports] = useState<AsyncReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [creating, setCreating] = useState(false);
  const [refreshingReport, setRefreshingReport] = useState<string | null>(null);

  const [formData, setFormData] = useState<CreateReportForm>({
    name: "",
    level: "campaign",
    datePreset: "last_7d",
    startDate: "",
    endDate: "",
    metrics: ["impressions", "clicks", "spend", "ctr", "cpc"],
    breakdowns: [],
  });

  // Load reports
  useEffect(() => {
    loadReports();
  }, []);

  const loadReports = async () => {
    try {
      setLoading(true);
      // Simulated data - replace with actual API call
      setReports([]);
    } catch (error) {
      toast.error("فشل في تحميل التقارير");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateReport = async () => {
    if (!formData.name.trim()) {
      toast.error("اسم التقرير مطلوب");
      return;
    }
    if (formData.metrics.length === 0) {
      toast.error("يجب اختيار مقياس واحد على الأقل");
      return;
    }

    try {
      setCreating(true);

      const reportData = {
        name: formData.name,
        level: formData.level,
        datePreset:
          formData.datePreset !== "custom" ? formData.datePreset : undefined,
        timeRange:
          formData.datePreset === "custom"
            ? {
                since: formData.startDate,
                until: formData.endDate,
              }
            : undefined,
        fields: formData.metrics,
        breakdowns:
          formData.breakdowns.length > 0 ? formData.breakdowns : undefined,
      };

      await facebookAdsService.createAsyncReport(reportData);

      toast.success("تم إنشاء التقرير بنجاح");
      setShowCreateModal(false);
      resetForm();
      await loadReports();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في إنشاء التقرير");
    } finally {
      setCreating(false);
    }
  };

  const handleRefreshStatus = async (reportId: string) => {
    try {
      setRefreshingReport(reportId);
      const status = await facebookAdsService.getAsyncReportStatus(reportId);

      setReports((prev) =>
        prev.map((r) =>
          r.id === reportId ? { ...r, status: status.status } : r,
        ),
      );

      if (status.status === "COMPLETED") {
        toast.success("التقرير جاهز للتحميل");
      }
    } catch (error) {
      toast.error("فشل في تحديث حالة التقرير");
    } finally {
      setRefreshingReport(null);
    }
  };

  const handleDownloadReport = async (reportId: string) => {
    try {
      const results = await facebookAdsService.getAsyncReportResults(reportId);

      // Convert to CSV and download
      const csv = convertToCSV(results);
      downloadCSV(csv, `report_${reportId}.csv`);

      toast.success("تم تحميل التقرير");
    } catch (error) {
      toast.error("فشل في تحميل التقرير");
    }
  };

  const convertToCSV = (data: any[]) => {
    if (!data || data.length === 0) return "";
    const headers = Object.keys(data[0]);
    const rows = data.map((row) => headers.map((h) => row[h]).join(","));
    return [headers.join(","), ...rows].join("\n");
  };

  const downloadCSV = (csv: string, filename: string) => {
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    link.click();
  };

  const resetForm = () => {
    setFormData({
      name: "",
      level: "campaign",
      datePreset: "last_7d",
      startDate: "",
      endDate: "",
      metrics: ["impressions", "clicks", "spend", "ctr", "cpc"],
      breakdowns: [],
    });
  };

  const toggleMetric = (metric: string) => {
    setFormData((prev) => ({
      ...prev,
      metrics: prev.metrics.includes(metric)
        ? prev.metrics.filter((m) => m !== metric)
        : [...prev.metrics, metric],
    }));
  };

  const toggleBreakdown = (breakdown: string) => {
    setFormData((prev) => ({
      ...prev,
      breakdowns: prev.breakdowns.includes(breakdown)
        ? prev.breakdowns.filter((b) => b !== breakdown)
        : [...prev.breakdowns, breakdown],
    }));
  };

  const getStatusBadge = (status: string) => {
    const badges = {
      PENDING: {
        bg: "bg-yellow-100",
        text: "text-yellow-700",
        icon: <Clock className="w-3 h-3" />,
        label: "قيد الانتظار",
      },
      RUNNING: {
        bg: "bg-blue-100",
        text: "text-blue-700",
        icon: <Loader2 className="w-3 h-3 animate-spin" />,
        label: "جاري التنفيذ",
      },
      COMPLETED: {
        bg: "bg-green-100",
        text: "text-green-700",
        icon: <CheckCircle className="w-3 h-3" />,
        label: "مكتمل",
      },
      FAILED: {
        bg: "bg-red-100",
        text: "text-red-700",
        icon: <XCircle className="w-3 h-3" />,
        label: "فشل",
      },
    };
    return badges[status as keyof typeof badges] || badges.PENDING;
  };

  // Group metrics by category
  const metricsByCategory = AVAILABLE_METRICS.reduce(
    (acc, metric) => {
      if (!acc[metric.category]) acc[metric.category] = [];
      acc[metric.category].push(metric);
      return acc;
    },
    {} as Record<string, typeof AVAILABLE_METRICS>,
  );

  // ============================================
  // Render
  // ============================================

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="w-12 h-12 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
            <BarChart3 className="w-8 h-8 text-blue-500" />
            التقارير المتقدمة
          </h1>
          <p className="text-gray-600 mt-1">
            أنشئ تقارير مفصلة عن أداء حملاتك الإعلانية
          </p>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
        >
          <Plus className="w-5 h-5" />
          تقرير جديد
        </button>
      </div>

      {/* Reports List */}
      {reports.length === 0 ? (
        <div className="bg-white rounded-xl shadow p-12 text-center">
          <FileText className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-xl font-medium text-gray-900 mb-2">
            لا توجد تقارير
          </h3>
          <p className="text-gray-500 mb-6">
            أنشئ تقريراً جديداً لتحليل أداء حملاتك
          </p>
          <button
            onClick={() => setShowCreateModal(true)}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            إنشاء تقرير
          </button>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow overflow-hidden">
          <table className="w-full">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-right text-sm font-medium text-gray-500">
                  اسم التقرير
                </th>
                <th className="px-6 py-3 text-right text-sm font-medium text-gray-500">
                  المستوى
                </th>
                <th className="px-6 py-3 text-right text-sm font-medium text-gray-500">
                  الفترة
                </th>
                <th className="px-6 py-3 text-right text-sm font-medium text-gray-500">
                  الحالة
                </th>
                <th className="px-6 py-3 text-right text-sm font-medium text-gray-500">
                  الإجراءات
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {reports.map((report) => {
                const statusBadge = getStatusBadge(report.status);
                return (
                  <tr key={report.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <div className="font-medium text-gray-900">
                        {report.name}
                      </div>
                      <div className="text-sm text-gray-500">
                        {report.metrics.length} مقاييس
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-600">
                      {
                        REPORT_LEVELS.find((l) => l.value === report.level)
                          ?.label
                      }
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-600">
                      {report.dateRange.start} - {report.dateRange.end}
                    </td>
                    <td className="px-6 py-4">
                      <span
                        className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${statusBadge.bg} ${statusBadge.text}`}
                      >
                        {statusBadge.icon}
                        {statusBadge.label}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        {report.status !== "COMPLETED" && (
                          <button
                            onClick={() => handleRefreshStatus(report.id)}
                            disabled={refreshingReport === report.id}
                            className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg disabled:opacity-50"
                          >
                            <RefreshCw
                              className={`w-4 h-4 ${refreshingReport === report.id ? "animate-spin" : ""}`}
                            />
                          </button>
                        )}
                        {report.status === "COMPLETED" && (
                          <button
                            onClick={() => handleDownloadReport(report.id)}
                            className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"
                          >
                            <Download className="w-4 h-4" />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Create Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b">
              <h2 className="text-xl font-bold text-gray-900">
                إنشاء تقرير جديد
              </h2>
            </div>

            <div className="p-6 space-y-6">
              {/* Report Name */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  اسم التقرير
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData((prev) => ({ ...prev, name: e.target.value }))
                  }
                  placeholder="مثال: تقرير أداء الحملات الأسبوعي"
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {/* Level & Date */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    المستوى
                  </label>
                  <select
                    value={formData.level}
                    onChange={(e) =>
                      setFormData((prev) => ({
                        ...prev,
                        level: e.target.value as any,
                      }))
                    }
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    {REPORT_LEVELS.map((level) => (
                      <option key={level.value} value={level.value}>
                        {level.label}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    الفترة الزمنية
                  </label>
                  <select
                    value={formData.datePreset}
                    onChange={(e) =>
                      setFormData((prev) => ({
                        ...prev,
                        datePreset: e.target.value,
                      }))
                    }
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    {DATE_PRESETS.map((preset) => (
                      <option key={preset.value} value={preset.value}>
                        {preset.label}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              {/* Custom Date Range */}
              {formData.datePreset === "custom" && (
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      من تاريخ
                    </label>
                    <input
                      type="date"
                      value={formData.startDate}
                      onChange={(e) =>
                        setFormData((prev) => ({
                          ...prev,
                          startDate: e.target.value,
                        }))
                      }
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      إلى تاريخ
                    </label>
                    <input
                      type="date"
                      value={formData.endDate}
                      onChange={(e) =>
                        setFormData((prev) => ({
                          ...prev,
                          endDate: e.target.value,
                        }))
                      }
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>
              )}

              {/* Metrics */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                  المقاييس
                </label>
                <div className="space-y-4">
                  {Object.entries(metricsByCategory).map(
                    ([category, metrics]) => (
                      <div key={category}>
                        <h4 className="text-sm font-medium text-gray-500 mb-2">
                          {category}
                        </h4>
                        <div className="flex flex-wrap gap-2">
                          {metrics.map((metric) => (
                            <button
                              key={metric.value}
                              type="button"
                              onClick={() => toggleMetric(metric.value)}
                              className={`px-3 py-1.5 text-sm rounded-lg border transition-all ${
                                formData.metrics.includes(metric.value)
                                  ? "bg-blue-50 border-blue-500 text-blue-700"
                                  : "border-gray-200 hover:border-gray-300"
                              }`}
                            >
                              {metric.label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ),
                  )}
                </div>
              </div>

              {/* Breakdowns */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                  التقسيمات (اختياري)
                </label>
                <div className="flex flex-wrap gap-2">
                  {AVAILABLE_BREAKDOWNS.map((breakdown) => (
                    <button
                      key={breakdown.value}
                      type="button"
                      onClick={() => toggleBreakdown(breakdown.value)}
                      className={`px-3 py-1.5 text-sm rounded-lg border transition-all ${
                        formData.breakdowns.includes(breakdown.value)
                          ? "bg-purple-50 border-purple-500 text-purple-700"
                          : "border-gray-200 hover:border-gray-300"
                      }`}
                    >
                      {breakdown.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-6 border-t flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowCreateModal(false);
                  resetForm();
                }}
                className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200"
              >
                إلغاء
              </button>
              <button
                onClick={handleCreateReport}
                disabled={creating}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
              >
                {creating ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    جاري الإنشاء...
                  </>
                ) : (
                  <>
                    <CheckCircle className="w-4 h-4" />
                    إنشاء التقرير
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AsyncReports;

/**
 * 📊 Attribution Settings
 *
 * إعدادات إحالة التحويلات
 */

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  Settings,
  ArrowLeft,
  Clock,
  MousePointer,
  Eye,
  Loader2,
  CheckCircle,
  Info,
  BarChart3,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

const AttributionSettings: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  const [settings, setSettings] = useState({
    adSetId: "",
    clickWindow: "7d" as "1d" | "7d" | "28d",
    viewWindow: "1d" as "1d" | "7d",
    useAccountDefault: false,
  });

  const clickWindowOptions = [
    {
      value: "1d",
      label: "يوم واحد",
      description: "تحويلات خلال 24 ساعة من النقر",
    },
    {
      value: "7d",
      label: "7 أيام",
      description: "تحويلات خلال أسبوع من النقر (موصى به)",
    },
    { value: "28d", label: "28 يوم", description: "تحويلات خلال شهر من النقر" },
  ];

  const viewWindowOptions = [
    {
      value: "1d",
      label: "يوم واحد",
      description: "تحويلات خلال 24 ساعة من المشاهدة",
    },
    {
      value: "7d",
      label: "7 أيام",
      description: "تحويلات خلال أسبوع من المشاهدة",
    },
  ];

  const handleSave = async () => {
    if (!settings.adSetId.trim()) {
      toast.error("يرجى إدخال معرف مجموعة الإعلانات");
      return;
    }

    try {
      setLoading(true);
      const attributionPayload: any = {
        clickWindow: settings.clickWindow,
        viewWindow: settings.viewWindow,
        useAccountDefault: settings.useAccountDefault,
      };
      await facebookAdsService.updateAttributionSettings(
        settings.adSetId,
        attributionPayload,
      );
      toast.success("تم حفظ إعدادات الإحالة بنجاح! ✅");
    } catch (error: any) {
      console.error("Error saving settings:", error);
      toast.error(error?.response?.data?.error || "فشل في حفظ الإعدادات");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button
          onClick={() => navigate("/advertising/facebook-ads")}
          className="p-2 hover:bg-gray-100 rounded-lg"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Settings className="w-7 h-7 text-gray-600" />
            إعدادات الإحالة (Attribution)
          </h1>
          <p className="text-gray-600 mt-1">
            تحديد كيفية احتساب التحويلات للإعلانات
          </p>
        </div>
      </div>

      {/* Info Card */}
      <div className="bg-blue-50 border border-blue-200 rounded-xl p-4">
        <div className="flex items-start gap-3">
          <Info className="w-5 h-5 text-blue-600 mt-0.5" />
          <div>
            <h3 className="font-medium text-blue-900">ما هي نافذة الإحالة؟</h3>
            <p className="text-sm text-blue-700 mt-1">
              نافذة الإحالة تحدد الفترة الزمنية التي يتم فيها احتساب التحويل
              للإعلان. مثلاً، إذا اخترت 7 أيام للنقر، فإن أي عملية شراء تحدث
              خلال 7 أيام من النقر على الإعلان ستُحتسب كتحويل.
            </p>
          </div>
        </div>
      </div>

      {/* Main Form */}
      <div className="bg-white rounded-xl shadow-sm border">
        <div className="p-6 border-b">
          <h2 className="text-lg font-semibold text-gray-900">
            تحديد مجموعة الإعلانات
          </h2>
          <div className="mt-4">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              معرف مجموعة الإعلانات (Ad Set ID) *
            </label>
            <input
              type="text"
              value={settings.adSetId}
              onChange={(e) =>
                setSettings((prev) => ({ ...prev, adSetId: e.target.value }))
              }
              placeholder="أدخل معرف Ad Set"
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        {/* Click Attribution */}
        <div className="p-6 border-b">
          <div className="flex items-center gap-2 mb-4">
            <MousePointer className="w-5 h-5 text-blue-600" />
            <h2 className="text-lg font-semibold text-gray-900">
              نافذة النقر (Click-Through)
            </h2>
          </div>
          <p className="text-sm text-gray-600 mb-4">
            الفترة الزمنية بعد النقر على الإعلان التي يتم فيها احتساب التحويلات
          </p>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {clickWindowOptions.map((option) => (
              <button
                key={option.value}
                onClick={() =>
                  setSettings((prev) => ({
                    ...prev,
                    clickWindow: option.value as any,
                  }))
                }
                className={`p-4 rounded-xl border-2 text-right transition-all ${
                  settings.clickWindow === option.value
                    ? "border-blue-500 bg-blue-50"
                    : "border-gray-200 hover:border-gray-300"
                }`}
              >
                <div className="flex items-center justify-between mb-2">
                  <Clock
                    className={`w-5 h-5 ${settings.clickWindow === option.value ? "text-blue-600" : "text-gray-400"}`}
                  />
                  {settings.clickWindow === option.value && (
                    <CheckCircle className="w-5 h-5 text-blue-600" />
                  )}
                </div>
                <h3
                  className={`font-semibold ${settings.clickWindow === option.value ? "text-blue-900" : "text-gray-900"}`}
                >
                  {option.label}
                </h3>
                <p className="text-xs text-gray-500 mt-1">
                  {option.description}
                </p>
              </button>
            ))}
          </div>
        </div>

        {/* View Attribution */}
        <div className="p-6 border-b">
          <div className="flex items-center gap-2 mb-4">
            <Eye className="w-5 h-5 text-purple-600" />
            <h2 className="text-lg font-semibold text-gray-900">
              نافذة المشاهدة (View-Through)
            </h2>
          </div>
          <p className="text-sm text-gray-600 mb-4">
            الفترة الزمنية بعد مشاهدة الإعلان (بدون نقر) التي يتم فيها احتساب
            التحويلات
          </p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {viewWindowOptions.map((option) => (
              <button
                key={option.value}
                onClick={() =>
                  setSettings((prev) => ({
                    ...prev,
                    viewWindow: option.value as any,
                  }))
                }
                className={`p-4 rounded-xl border-2 text-right transition-all ${
                  settings.viewWindow === option.value
                    ? "border-purple-500 bg-purple-50"
                    : "border-gray-200 hover:border-gray-300"
                }`}
              >
                <div className="flex items-center justify-between mb-2">
                  <Clock
                    className={`w-5 h-5 ${settings.viewWindow === option.value ? "text-purple-600" : "text-gray-400"}`}
                  />
                  {settings.viewWindow === option.value && (
                    <CheckCircle className="w-5 h-5 text-purple-600" />
                  )}
                </div>
                <h3
                  className={`font-semibold ${settings.viewWindow === option.value ? "text-purple-900" : "text-gray-900"}`}
                >
                  {option.label}
                </h3>
                <p className="text-xs text-gray-500 mt-1">
                  {option.description}
                </p>
              </button>
            ))}
          </div>
        </div>

        {/* Account Default */}
        <div className="p-6 border-b">
          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="checkbox"
              checked={settings.useAccountDefault}
              onChange={(e) =>
                setSettings((prev) => ({
                  ...prev,
                  useAccountDefault: e.target.checked,
                }))
              }
              className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
            />
            <div>
              <span className="font-medium text-gray-900">
                استخدام الإعدادات الافتراضية للحساب
              </span>
              <p className="text-sm text-gray-500">
                تجاهل الإعدادات أعلاه واستخدام إعدادات الحساب
              </p>
            </div>
          </label>
        </div>

        {/* Summary */}
        <div className="p-6 border-b bg-gray-50">
          <div className="flex items-center gap-2 mb-3">
            <BarChart3 className="w-5 h-5 text-gray-600" />
            <h3 className="font-medium text-gray-900">ملخص الإعدادات</h3>
          </div>
          <div className="bg-white rounded-lg p-4 border">
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <span className="text-gray-500">نافذة النقر:</span>
                <span className="font-medium text-gray-900 mr-2">
                  {
                    clickWindowOptions.find(
                      (o) => o.value === settings.clickWindow,
                    )?.label
                  }
                </span>
              </div>
              <div>
                <span className="text-gray-500">نافذة المشاهدة:</span>
                <span className="font-medium text-gray-900 mr-2">
                  {
                    viewWindowOptions.find(
                      (o) => o.value === settings.viewWindow,
                    )?.label
                  }
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Actions */}
        <div className="p-6 flex gap-3 justify-end">
          <button
            onClick={() => navigate("/advertising/facebook-ads")}
            className="px-6 py-2 text-gray-700 bg-white border rounded-lg hover:bg-gray-50"
          >
            إلغاء
          </button>
          <button
            onClick={handleSave}
            disabled={loading || !settings.adSetId.trim()}
            className="px-6 py-2 text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                جاري الحفظ...
              </>
            ) : (
              <>
                <CheckCircle className="w-4 h-4" />
                حفظ الإعدادات
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AttributionSettings;

/**
 * Audiences Management Page
 *
 * صفحة إدارة الجماهير (Custom & Lookalike Audiences)
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  PlusIcon,
  TrashIcon,
  EyeIcon,
  UserGroupIcon,
  SparklesIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookCustomAudience,
  FacebookLookalikeAudience,
} from "../../services/facebookAdsService";

const AudiencesManagement: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<"custom" | "lookalike">("custom");
  const [customAudiences, setCustomAudiences] = useState<
    FacebookCustomAudience[]
  >([]);
  const [lookalikeAudiences, setLookalikeAudiences] = useState<
    FacebookLookalikeAudience[]
  >([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    loadAudiences();
  }, [activeTab]);

  const loadAudiences = async () => {
    try {
      setLoading(true);
      if (activeTab === "custom") {
        const data = await facebookAdsService.getCustomAudiences();
        setCustomAudiences(data);
      } else {
        const data = await facebookAdsService.getLookalikeAudiences();
        setLookalikeAudiences(data);
      }
    } catch (error: any) {
      console.error("Error loading audiences:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل الجماهير");
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await loadAudiences();
    setRefreshing(false);
    toast.success("تم تحديث البيانات");
  };

  const handleCreateCustomAudience = () => {
    navigate("/advertising/facebook-ads/audiences/custom/create");
  };

  const handleCreateLookalikeAudience = () => {
    navigate("/advertising/facebook-ads/audiences/lookalike/create");
  };

  const handleDeleteCustomAudience = async (
    id: string,
    e: React.MouseEvent,
  ) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذا الجمهور؟")) return;

    try {
      await facebookAdsService.deleteCustomAudience(id);
      toast.success("تم حذف الجمهور بنجاح");
      await loadAudiences();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في حذف الجمهور");
    }
  };

  const handleViewAudience = (id: string) => {
    if (activeTab === "custom") {
      navigate(`/advertising/facebook-ads/audiences/custom/${id}`);
    }
  };

  const getAudienceTypeLabel = (type: string) => {
    const types: Record<string, string> = {
      CUSTOMER_LIST: "قائمة عملاء",
      WEBSITE: "زوار الموقع",
      ENGAGEMENT: "المتفاعلين",
      APP_ACTIVITY: "نشاط التطبيق",
      VIDEO_VIEW: "مشاهدي الفيديو",
    };
    return types[type] || type;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <ArrowPathIcon className="w-8 h-8 animate-spin mx-auto text-indigo-600" />
          <p className="mt-2 text-gray-600">جاري التحميل...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6 min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            إدارة الجماهير
          </h1>
          <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
            أدر الجماهير المخصصة والجماهير المشابهة لحملاتك الإعلانية
          </p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleRefresh}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2 text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50"
          >
            <ArrowPathIcon
              className={`w-5 h-5 ${refreshing ? "animate-spin" : ""}`}
            />
            تحديث
          </button>
          <button
            onClick={
              activeTab === "custom"
                ? handleCreateCustomAudience
                : handleCreateLookalikeAudience
            }
            className="flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 dark:bg-indigo-500 rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
          >
            <PlusIcon className="w-5 h-5" />
            {activeTab === "custom" ? "جمهور مخصص جديد" : "جمهور مشابه جديد"}
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <nav className="-mb-px flex space-x-8">
          <button
            onClick={() => setActiveTab("custom")}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${
              activeTab === "custom"
                ? "border-indigo-500 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            <div className="flex items-center gap-2">
              <UserGroupIcon className="w-5 h-5" />
              الجماهير المخصصة ({customAudiences.length})
            </div>
          </button>
          <button
            onClick={() => setActiveTab("lookalike")}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${
              activeTab === "lookalike"
                ? "border-indigo-500 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            <div className="flex items-center gap-2">
              <SparklesIcon className="w-5 h-5" />
              الجماهير المشابهة ({lookalikeAudiences.length})
            </div>
          </button>
        </nav>
      </div>

      {/* Custom Audiences Tab */}
      {activeTab === "custom" && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow dark:shadow-gray-900/20 overflow-hidden border-0 dark:border dark:border-gray-700">
          {customAudiences.length === 0 ? (
            <div className="text-center py-12">
              <UserGroupIcon className="w-16 h-16 mx-auto text-gray-400 dark:text-gray-500" />
              <h3 className="mt-4 text-lg font-medium text-gray-900 dark:text-white">
                لا توجد جماهير مخصصة
              </h3>
              <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                ابدأ بإنشاء جمهور مخصص جديد لحملاتك الإعلانية
              </p>
              <button
                onClick={handleCreateCustomAudience}
                className="mt-6 inline-flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
              >
                <PlusIcon className="w-5 h-5" />
                إنشاء جمهور مخصص جديد
              </button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      الاسم
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      النوع
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      الحجم
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      الحالة
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      تاريخ الإنشاء
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      الإجراءات
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-600">
                  {customAudiences.map((audience) => (
                    <tr
                      key={audience.id}
                      className="hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer"
                      onClick={() => handleViewAudience(audience.id)}
                    >
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">
                          {audience.name}
                        </div>
                        {audience.description && (
                          <div className="text-sm text-gray-500">
                            {audience.description}
                          </div>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800">
                          {getAudienceTypeLabel(audience.audienceType)}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {audience.audienceSize
                          ? audience.audienceSize.toLocaleString()
                          : "-"}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                            audience.status === "ACTIVE"
                              ? "bg-green-100 text-green-800"
                              : "bg-gray-100 text-gray-800"
                          }`}
                        >
                          {audience.status === "ACTIVE" ? "نشط" : "محذوف"}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {new Date(audience.createdAt).toLocaleDateString(
                          "ar-EG",
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                        <div className="flex items-center justify-end gap-2">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              handleViewAudience(audience.id);
                            }}
                            className="text-indigo-600 hover:text-indigo-900"
                          >
                            <EyeIcon className="w-5 h-5" />
                          </button>
                          <button
                            onClick={(e) =>
                              handleDeleteCustomAudience(audience.id, e)
                            }
                            className="text-red-600 hover:text-red-900"
                          >
                            <TrashIcon className="w-5 h-5" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Lookalike Audiences Tab */}
      {activeTab === "lookalike" && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow dark:shadow-gray-900/20 overflow-hidden border-0 dark:border dark:border-gray-700">
          {lookalikeAudiences.length === 0 ? (
            <div className="text-center py-12">
              <SparklesIcon className="w-16 h-16 mx-auto text-gray-400 dark:text-gray-500" />
              <h3 className="mt-4 text-lg font-medium text-gray-900 dark:text-white">
                لا توجد جماهير مشابهة
              </h3>
              <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                ابدأ بإنشاء جمهور مشابه جديد بناءً على جمهورك المخصص
              </p>
              <button
                onClick={handleCreateLookalikeAudience}
                className="mt-6 inline-flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 dark:bg-indigo-500 rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
              >
                <PlusIcon className="w-5 h-5" />
                إنشاء جمهور مشابه جديد
              </button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-600">
                <thead className="bg-gray-50 dark:bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      الاسم
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      المصدر
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      نسبة الشبه
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      الحجم
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      الحالة
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      تاريخ الإنشاء
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-600">
                  {lookalikeAudiences.map((audience) => (
                    <tr
                      key={audience.id}
                      className="hover:bg-gray-50 dark:hover:bg-gray-700/50"
                    >
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900 dark:text-white">
                          {audience.name}
                        </div>
                        {audience.description && (
                          <div className="text-sm text-gray-500 dark:text-gray-400">
                            {audience.description}
                          </div>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                        {audience.sourceAudience?.name || "-"}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-purple-100 dark:bg-purple-900/30 text-purple-800 dark:text-purple-300">
                          {audience.ratio}%
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                        {audience.audienceSize
                          ? audience.audienceSize.toLocaleString()
                          : "-"}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                            audience.status === "ACTIVE"
                              ? "bg-green-100 text-green-800"
                              : "bg-gray-100 text-gray-800"
                          }`}
                        >
                          {audience.status === "ACTIVE" ? "نشط" : "محذوف"}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {new Date(audience.createdAt).toLocaleDateString(
                          "ar-EG",
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AudiencesManagement;

/**
 * 🤖 Automation Rules Management
 *
 * صفحة إدارة قواعد الأتمتة للإعلانات
 * v22.0 Feature
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  Zap,
  Plus,
  Trash2,
  Edit,
  Play,
  Pause,
  AlertCircle,
  CheckCircle,
  Clock,
  TrendingUp,
  TrendingDown,
  DollarSign,
  Target,
  Loader2,
  ChevronDown,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

// ============================================
// Types
// ============================================

interface AutomationRule {
  id: string;
  name: string;
  status: "ACTIVE" | "PAUSED";
  entityType: "CAMPAIGN" | "ADSET" | "AD";
  actionType: string;
  conditions: RuleCondition[];
  schedule: string;
  createdAt: string;
  lastTriggered?: string;
}

interface RuleCondition {
  field: string;
  operator: string;
  value: number;
}

interface CreateRuleForm {
  name: string;
  entityType: "CAMPAIGN" | "ADSET" | "AD";
  actionType: string;
  conditions: RuleCondition[];
  schedule: string;
}

// ============================================
// Constants
// ============================================

const ENTITY_TYPES = [
  { value: "CAMPAIGN", label: "الحملات" },
  { value: "ADSET", label: "المجموعات الإعلانية" },
  { value: "AD", label: "الإعلانات" },
];

const ACTION_TYPES = [
  { value: "PAUSE", label: "إيقاف مؤقت", icon: <Pause className="w-4 h-4" /> },
  { value: "UNPAUSE", label: "استئناف", icon: <Play className="w-4 h-4" /> },
  {
    value: "INCREASE_BUDGET",
    label: "زيادة الميزانية",
    icon: <TrendingUp className="w-4 h-4" />,
  },
  {
    value: "DECREASE_BUDGET",
    label: "تقليل الميزانية",
    icon: <TrendingDown className="w-4 h-4" />,
  },
  {
    value: "SEND_NOTIFICATION",
    label: "إرسال إشعار",
    icon: <AlertCircle className="w-4 h-4" />,
  },
];

const CONDITION_FIELDS = [
  { value: "cost_per_result", label: "تكلفة النتيجة" },
  { value: "ctr", label: "معدل النقر (CTR)" },
  { value: "cpc", label: "تكلفة النقرة (CPC)" },
  { value: "cpm", label: "تكلفة الألف ظهور (CPM)" },
  { value: "spend", label: "الإنفاق" },
  { value: "impressions", label: "مرات الظهور" },
  { value: "clicks", label: "النقرات" },
  { value: "conversions", label: "التحويلات" },
  { value: "frequency", label: "التكرار" },
  { value: "roas", label: "العائد على الإنفاق (ROAS)" },
];

const OPERATORS = [
  { value: "GREATER_THAN", label: "أكبر من" },
  { value: "LESS_THAN", label: "أقل من" },
  { value: "EQUAL", label: "يساوي" },
  { value: "IN_RANGE", label: "في النطاق" },
];

const SCHEDULES = [
  { value: "SEMI_HOURLY", label: "كل 30 دقيقة" },
  { value: "HOURLY", label: "كل ساعة" },
  { value: "DAILY", label: "يومياً" },
  { value: "WEEKLY", label: "أسبوعياً" },
];

// ============================================
// Component
// ============================================

const AutomationRules: React.FC = () => {
  const navigate = useNavigate();
  const [rules, setRules] = useState<AutomationRule[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [creating, setCreating] = useState(false);

  const [formData, setFormData] = useState<CreateRuleForm>({
    name: "",
    entityType: "CAMPAIGN",
    actionType: "PAUSE",
    conditions: [
      { field: "cost_per_result", operator: "GREATER_THAN", value: 0 },
    ],
    schedule: "DAILY",
  });

  // Load rules
  useEffect(() => {
    loadRules();
  }, []);

  const loadRules = async () => {
    try {
      setLoading(true);
      const data = await facebookAdsService.getAutomatedRules();
      setRules(data);
    } catch (error: any) {
      console.error("Error loading rules:", error);
      toast.error("فشل في تحميل القواعد");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRule = async () => {
    if (!formData.name.trim()) {
      toast.error("اسم القاعدة مطلوب");
      return;
    }

    try {
      setCreating(true);
      await facebookAdsService.createAutomatedRule({
        name: formData.name,
        entityType: formData.entityType,
        actionType: formData.actionType,
        evaluationSpec: {
          evaluationType: formData.schedule,
          filters: formData.conditions.map((c) => ({
            field: c.field,
            operator: c.operator,
            value: c.value,
          })),
        },
        executionSpec: {
          executionType: formData.actionType,
        },
      });

      toast.success("تم إنشاء القاعدة بنجاح");
      setShowCreateModal(false);
      resetForm();
      await loadRules();
    } catch (error: any) {
      console.error("Error creating rule:", error);
      toast.error(error?.response?.data?.error || "فشل في إنشاء القاعدة");
    } finally {
      setCreating(false);
    }
  };

  const handleDeleteRule = async (ruleId: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذه القاعدة؟")) return;

    try {
      await facebookAdsService.deleteAutomatedRule(ruleId);
      toast.success("تم حذف القاعدة");
      await loadRules();
    } catch (error: any) {
      toast.error("فشل في حذف القاعدة");
    }
  };

  const resetForm = () => {
    setFormData({
      name: "",
      entityType: "CAMPAIGN",
      actionType: "PAUSE",
      conditions: [
        { field: "cost_per_result", operator: "GREATER_THAN", value: 0 },
      ],
      schedule: "DAILY",
    });
  };

  const addCondition = () => {
    setFormData((prev) => ({
      ...prev,
      conditions: [
        ...prev.conditions,
        { field: "ctr", operator: "LESS_THAN", value: 0 },
      ],
    }));
  };

  const removeCondition = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      conditions: prev.conditions.filter((_, i) => i !== index),
    }));
  };

  const updateCondition = (
    index: number,
    field: keyof RuleCondition,
    value: any,
  ) => {
    setFormData((prev) => ({
      ...prev,
      conditions: prev.conditions.map((c, i) =>
        i === index ? { ...c, [field]: value } : c,
      ),
    }));
  };

  // ============================================
  // Render
  // ============================================

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="w-12 h-12 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
            <Zap className="w-8 h-8 text-yellow-500" />
            قواعد الأتمتة
          </h1>
          <p className="text-gray-600 mt-1">
            أنشئ قواعد لأتمتة إدارة حملاتك الإعلانية تلقائياً
          </p>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
        >
          <Plus className="w-5 h-5" />
          قاعدة جديدة
        </button>
      </div>

      {/* Rules List */}
      {rules.length === 0 ? (
        <div className="bg-white rounded-xl shadow p-12 text-center">
          <Zap className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-xl font-medium text-gray-900 mb-2">
            لا توجد قواعد أتمتة
          </h3>
          <p className="text-gray-500 mb-6">
            أنشئ قاعدة جديدة لأتمتة إدارة حملاتك
          </p>
          <button
            onClick={() => setShowCreateModal(true)}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            إنشاء قاعدة
          </button>
        </div>
      ) : (
        <div className="grid gap-4">
          {rules.map((rule) => (
            <div key={rule.id} className="bg-white rounded-xl shadow p-6">
              <div className="flex items-start justify-between">
                <div className="flex items-start gap-4">
                  <div
                    className={`p-3 rounded-lg ${rule.status === "ACTIVE" ? "bg-green-100" : "bg-gray-100"}`}
                  >
                    <Zap
                      className={`w-6 h-6 ${rule.status === "ACTIVE" ? "text-green-600" : "text-gray-400"}`}
                    />
                  </div>
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900">
                      {rule.name}
                    </h3>
                    <div className="flex items-center gap-4 mt-2 text-sm text-gray-500">
                      <span className="flex items-center gap-1">
                        <Target className="w-4 h-4" />
                        {
                          ENTITY_TYPES.find((e) => e.value === rule.entityType)
                            ?.label
                        }
                      </span>
                      <span className="flex items-center gap-1">
                        <Clock className="w-4 h-4" />
                        {
                          SCHEDULES.find((s) => s.value === rule.schedule)
                            ?.label
                        }
                      </span>
                    </div>
                    <div className="mt-3">
                      <span
                        className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${
                          rule.status === "ACTIVE"
                            ? "bg-green-100 text-green-700"
                            : "bg-gray-100 text-gray-600"
                        }`}
                      >
                        {rule.status === "ACTIVE" ? (
                          <CheckCircle className="w-3 h-3" />
                        ) : (
                          <Pause className="w-3 h-3" />
                        )}
                        {rule.status === "ACTIVE" ? "نشط" : "متوقف"}
                      </span>
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => handleDeleteRule(rule.id)}
                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg"
                  >
                    <Trash2 className="w-5 h-5" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b">
              <h2 className="text-xl font-bold text-gray-900">
                إنشاء قاعدة أتمتة جديدة
              </h2>
            </div>

            <div className="p-6 space-y-6">
              {/* Rule Name */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  اسم القاعدة
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData((prev) => ({ ...prev, name: e.target.value }))
                  }
                  placeholder="مثال: إيقاف الإعلانات منخفضة الأداء"
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {/* Entity Type */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  تطبيق على
                </label>
                <select
                  value={formData.entityType}
                  onChange={(e) =>
                    setFormData((prev) => ({
                      ...prev,
                      entityType: e.target.value as any,
                    }))
                  }
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  {ENTITY_TYPES.map((type) => (
                    <option key={type.value} value={type.value}>
                      {type.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Action Type */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  الإجراء
                </label>
                <div className="grid grid-cols-2 gap-3">
                  {ACTION_TYPES.map((action) => (
                    <button
                      key={action.value}
                      type="button"
                      onClick={() =>
                        setFormData((prev) => ({
                          ...prev,
                          actionType: action.value,
                        }))
                      }
                      className={`flex items-center gap-2 p-3 border-2 rounded-lg transition-all ${
                        formData.actionType === action.value
                          ? "border-blue-500 bg-blue-50"
                          : "border-gray-200 hover:border-gray-300"
                      }`}
                    >
                      {action.icon}
                      <span>{action.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Conditions */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  الشروط
                </label>
                <div className="space-y-3">
                  {formData.conditions.map((condition, index) => (
                    <div
                      key={index}
                      className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg"
                    >
                      <select
                        value={condition.field}
                        onChange={(e) =>
                          updateCondition(index, "field", e.target.value)
                        }
                        className="flex-1 px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        {CONDITION_FIELDS.map((field) => (
                          <option key={field.value} value={field.value}>
                            {field.label}
                          </option>
                        ))}
                      </select>
                      <select
                        value={condition.operator}
                        onChange={(e) =>
                          updateCondition(index, "operator", e.target.value)
                        }
                        className="px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        {OPERATORS.map((op) => (
                          <option key={op.value} value={op.value}>
                            {op.label}
                          </option>
                        ))}
                      </select>
                      <input
                        type="number"
                        value={condition.value}
                        onChange={(e) =>
                          updateCondition(
                            index,
                            "value",
                            parseFloat(e.target.value),
                          )
                        }
                        className="w-24 px-3 py-2 border border-gray-300 rounded-lg"
                      />
                      {formData.conditions.length > 1 && (
                        <button
                          onClick={() => removeCondition(index)}
                          className="p-2 text-red-500 hover:bg-red-50 rounded-lg"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      )}
                    </div>
                  ))}
                  <button
                    onClick={addCondition}
                    className="flex items-center gap-2 text-blue-600 hover:text-blue-700"
                  >
                    <Plus className="w-4 h-4" />
                    إضافة شرط
                  </button>
                </div>
              </div>

              {/* Schedule */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  التكرار
                </label>
                <select
                  value={formData.schedule}
                  onChange={(e) =>
                    setFormData((prev) => ({
                      ...prev,
                      schedule: e.target.value,
                    }))
                  }
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  {SCHEDULES.map((schedule) => (
                    <option key={schedule.value} value={schedule.value}>
                      {schedule.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="p-6 border-t flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowCreateModal(false);
                  resetForm();
                }}
                className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200"
              >
                إلغاء
              </button>
              <button
                onClick={handleCreateRule}
                disabled={creating}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
              >
                {creating ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    جاري الإنشاء...
                  </>
                ) : (
                  <>
                    <CheckCircle className="w-4 h-4" />
                    إنشاء القاعدة
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AutomationRules;

/**
 * Campaign Details Page
 *
 * صفحة تفاصيل الحملة الإعلانية
 */

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  PauseIcon,
  PlayIcon,
  TrashIcon,
  ArrowPathIcon,
  PlusIcon,
  ShoppingBagIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookCampaign,
  CAMPAIGN_OBJECTIVES,
} from "../../services/facebookAdsService";

const CampaignDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [campaign, setCampaign] = useState<FacebookCampaign | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    if (id) {
      loadCampaign();
    }
  }, [id]);

  const loadCampaign = async () => {
    if (!id) return;

    try {
      setLoading(true);
      const data = await facebookAdsService.getCampaign(id);
      setCampaign(data);
    } catch (error: any) {
      console.error("Error loading campaign:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل الحملة");
      navigate("/advertising/facebook-ads");
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await loadCampaign();
    setRefreshing(false);
    toast.success("تم تحديث البيانات");
  };

  const handlePause = async () => {
    if (!id) return;
    try {
      await facebookAdsService.pauseCampaign(id);
      toast.success("تم إيقاف الحملة");
      await loadCampaign();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في إيقاف الحملة");
    }
  };

  const handleResume = async () => {
    if (!id) return;
    try {
      await facebookAdsService.resumeCampaign(id);
      toast.success("تم استئناف الحملة");
      await loadCampaign();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في استئناف الحملة");
    }
  };

  const handleDelete = async () => {
    if (!id) return;
    if (!window.confirm("هل أنت متأكد من حذف هذه الحملة؟")) {
      return;
    }

    try {
      await facebookAdsService.deleteCampaign(id);
      toast.success("تم حذف الحملة");
      navigate("/advertising/facebook-ads");
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في حذف الحملة");
    }
  };

  const getObjectiveLabel = (objective: string) => {
    const obj = CAMPAIGN_OBJECTIVES.find((o) => o.value === objective);
    return obj?.label || objective;
  };

  const getStatusBadge = (status: string) => {
    const badges = {
      ACTIVE: "bg-green-100 text-green-800",
      PAUSED: "bg-yellow-100 text-yellow-800",
      ARCHIVED: "bg-gray-100 text-gray-800",
      DELETED: "bg-red-100 text-red-800",
    };
    return badges[status as keyof typeof badges] || "bg-gray-100 text-gray-800";
  };

  const getStatusLabel = (status: string) => {
    const labels = {
      ACTIVE: "نشط",
      PAUSED: "متوقف",
      ARCHIVED: "مؤرشف",
      DELETED: "محذوف",
    };
    return labels[status as keyof typeof labels] || status;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  if (!campaign) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-600">الحملة غير موجودة</p>
        <button
          onClick={() => navigate("/advertising/facebook-ads")}
          className="mt-4 text-indigo-600 hover:text-indigo-700"
        >
          العودة للقائمة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate("/advertising/facebook-ads")}
            className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg"
          >
            <ArrowLeftIcon className="w-5 h-5" />
          </button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-3xl font-bold text-gray-900">
                {campaign.name}
              </h1>
              <span
                className={`px-3 py-1 text-sm font-medium rounded-full ${getStatusBadge(campaign.status)}`}
              >
                {getStatusLabel(campaign.status)}
              </span>
            </div>
            <p className="mt-1 text-sm text-gray-600">
              تم الإنشاء:{" "}
              {new Date(campaign.createdAt).toLocaleDateString("ar-EG")}
            </p>
          </div>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleRefresh}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50"
          >
            <ArrowPathIcon
              className={`w-5 h-5 ${refreshing ? "animate-spin" : ""}`}
            />
            تحديث
          </button>
          {campaign.status === "ACTIVE" ? (
            <button
              onClick={handlePause}
              className="flex items-center gap-2 px-4 py-2 text-yellow-700 bg-white border border-yellow-300 rounded-lg hover:bg-yellow-50"
            >
              <PauseIcon className="w-5 h-5" />
              إيقاف
            </button>
          ) : campaign.status === "PAUSED" ? (
            <button
              onClick={handleResume}
              className="flex items-center gap-2 px-4 py-2 text-green-700 bg-white border border-green-300 rounded-lg hover:bg-green-50"
            >
              <PlayIcon className="w-5 h-5" />
              استئناف
            </button>
          ) : null}
          <button
            onClick={handleDelete}
            className="flex items-center gap-2 px-4 py-2 text-red-700 bg-white border border-red-300 rounded-lg hover:bg-red-50"
          >
            <TrashIcon className="w-5 h-5" />
            حذف
          </button>
        </div>
      </div>

      {/* Campaign Info */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Basic Info */}
        <div className="bg-white p-6 rounded-lg shadow">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">
            معلومات الحملة
          </h2>
          <div className="space-y-4">
            <div>
              <p className="text-sm text-gray-600">اسم الحملة</p>
              <p className="font-medium text-gray-900">{campaign.name}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">الهدف</p>
              <p className="font-medium text-gray-900">
                {getObjectiveLabel(campaign.objective)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">الحالة</p>
              <span
                className={`inline-block px-3 py-1 text-sm font-medium rounded-full ${getStatusBadge(campaign.status)}`}
              >
                {getStatusLabel(campaign.status)}
              </span>
            </div>
            {campaign.facebookCampaignId && (
              <div>
                <p className="text-sm text-gray-600">Facebook Campaign ID</p>
                <p className="font-medium text-gray-900 font-mono text-sm">
                  {campaign.facebookCampaignId}
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Budget Info */}
        <div className="bg-white p-6 rounded-lg shadow">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">
            الميزانية
          </h2>
          <div className="space-y-4">
            <div>
              <p className="text-sm text-gray-600">نوع الميزانية</p>
              <p className="font-medium text-gray-900">
                {campaign.budgetType === "DAILY" ? "يومية" : "إجمالية"}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">مبلغ الميزانية</p>
              <p className="font-medium text-gray-900 text-xl">
                {campaign.budgetAmount.toLocaleString()} EGP
                {campaign.budgetType === "DAILY" && (
                  <span className="text-sm text-gray-600"> / يوم</span>
                )}
              </p>
            </div>
            {campaign.startDate && (
              <div>
                <p className="text-sm text-gray-600">تاريخ البدء</p>
                <p className="font-medium text-gray-900">
                  {new Date(campaign.startDate).toLocaleDateString("ar-EG")}
                </p>
              </div>
            )}
            {campaign.endDate && (
              <div>
                <p className="text-sm text-gray-600">تاريخ الانتهاء</p>
                <p className="font-medium text-gray-900">
                  {new Date(campaign.endDate).toLocaleDateString("ar-EG")}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* AdSets */}
      <div className="bg-white rounded-lg shadow">
        <div className="p-6 border-b border-gray-200 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-900">
            مجموعات الإعلانات
          </h2>
          <button
            onClick={() =>
              navigate(
                `/advertising/facebook-ads/campaigns/${id}/adsets/create`,
              )
            }
            className="flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
          >
            <PlusIcon className="w-5 h-5" />
            إضافة مجموعة إعلانات
          </button>
        </div>

        {!campaign.adSets || campaign.adSets.length === 0 ? (
          <div className="p-12 text-center">
            <p className="text-gray-600 mb-4">لا توجد مجموعات إعلانات</p>
            <button
              onClick={() =>
                navigate(
                  `/advertising/facebook-ads/campaigns/${id}/adsets/create`,
                )
              }
              className="inline-flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
            >
              <PlusIcon className="w-5 h-5" />
              إضافة مجموعة إعلانات
            </button>
          </div>
        ) : (
          <div className="divide-y divide-gray-200">
            {campaign.adSets.map((adSet) => (
              <div key={adSet.id} className="p-6 hover:bg-gray-50">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <h3 className="font-semibold text-gray-900">
                      {adSet.name}
                    </h3>
                    <div className="mt-2 text-sm text-gray-600">
                      <span className="font-medium">الميزانية:</span>{" "}
                      {adSet.budgetAmount.toLocaleString()} EGP
                      {adSet.budgetType === "DAILY" && " / يوم"}
                    </div>
                    {adSet.ads && adSet.ads.length > 0 && (
                      <div className="mt-1 text-sm text-gray-500">
                        {adSet.ads.length} إعلان
                      </div>
                    )}
                  </div>
                  <div className="flex items-center gap-3">
                    <button
                      onClick={() =>
                        navigate(
                          `/advertising/facebook-ads/adsets/${adSet.id}/ads/create`,
                        )
                      }
                      className="flex items-center gap-2 px-3 py-1.5 text-sm text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
                      title="إنشاء إعلان جديد"
                    >
                      <PlusIcon className="w-4 h-4" />
                      إعلان جديد
                    </button>
                    <button
                      onClick={() =>
                        navigate(
                          `/advertising/facebook-ads/adsets/${adSet.id}/dynamic-ads/create`,
                        )
                      }
                      className="flex items-center gap-2 px-3 py-1.5 text-sm text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100"
                      title="إنشاء Dynamic Ad"
                    >
                      <ShoppingBagIcon className="w-4 h-4" />
                      Dynamic Ad
                    </button>
                    <span
                      className={`px-3 py-1 text-sm font-medium rounded-full ${getStatusBadge(adSet.status)}`}
                    >
                      {getStatusLabel(adSet.status)}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default CampaignDetails;

/**
 * Catalog Details Page
 *
 * صفحة تفاصيل Product Catalog مع Sync Products
 */

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  TrashIcon,
  ArrowPathIcon,
  ShoppingBagIcon,
  PlusIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookProductCatalog,
  FacebookCatalogProduct,
} from "../../services/facebookAdsService";

const CatalogDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [catalog, setCatalog] = useState<FacebookProductCatalog | null>(null);
  const [products, setProducts] = useState<FacebookCatalogProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [syncAll, setSyncAll] = useState(true);
  const [selectedProducts, setSelectedProducts] = useState<string[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);

  useEffect(() => {
    if (id) {
      loadCatalog();
      loadCatalogProducts();
    }
  }, [id]);

  const loadCatalog = async () => {
    if (!id) return;

    try {
      setLoading(true);
      const data = await facebookAdsService.getCatalog(id);
      setCatalog(data);
    } catch (error: any) {
      console.error("Error loading catalog:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل Catalog");
      navigate("/advertising/facebook-ads/catalogs");
    } finally {
      setLoading(false);
    }
  };

  const loadCatalogProducts = async (page: number = 1) => {
    if (!id) return;

    try {
      setLoadingProducts(true);
      const result = await facebookAdsService.getCatalogProducts(id, page, 50);
      setProducts(result.data);
    } catch (error: any) {
      console.error("Error loading catalog products:", error);
      toast.error("فشل في تحميل المنتجات");
    } finally {
      setLoadingProducts(false);
    }
  };

  const handleSync = async () => {
    if (!id) return;

    try {
      setSyncing(true);
      const result = await facebookAdsService.syncProducts(id, {
        syncAll,
        productIds: syncAll ? undefined : selectedProducts,
      });

      toast.success(`تم مزامنة ${result.successful} منتج بنجاح`);

      // تحديث البيانات
      await loadCatalog();
      await loadCatalogProducts();

      if (result.failed > 0) {
        toast.error(`فشل في مزامنة ${result.failed} منتج`);
      }
    } catch (error: any) {
      console.error("Error syncing products:", error);
      toast.error(error?.response?.data?.error || "فشل في مزامنة المنتجات");
    } finally {
      setSyncing(false);
    }
  };

  const handleDelete = async () => {
    if (!id) return;
    if (!confirm("هل أنت متأكد من حذف هذا Catalog؟")) return;

    try {
      await facebookAdsService.deleteCatalog(id);
      toast.success("تم حذف Catalog بنجاح");
      navigate("/advertising/facebook-ads/catalogs");
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في حذف Catalog");
    }
  };

  const toggleProductSelection = (productId: string) => {
    if (selectedProducts.includes(productId)) {
      setSelectedProducts(selectedProducts.filter((id) => id !== productId));
    } else {
      setSelectedProducts([...selectedProducts, productId]);
    }
  };

  const getSyncStatusIcon = (status?: string) => {
    switch (status) {
      case "SUCCESS":
        return <CheckCircleIcon className="w-5 h-5 text-green-500" />;
      case "FAILED":
        return <XCircleIcon className="w-5 h-5 text-red-500" />;
      case "IN_PROGRESS":
        return <ClockIcon className="w-5 h-5 text-yellow-500 animate-spin" />;
      default:
        return null;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <ArrowPathIcon className="w-8 h-8 animate-spin mx-auto text-indigo-600" />
          <p className="mt-2 text-gray-600">جاري التحميل...</p>
        </div>
      </div>
    );
  }

  if (!catalog) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-600">لم يتم العثور على Catalog</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <button
            onClick={() => navigate("/advertising/facebook-ads/catalogs")}
            className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
          >
            <ArrowLeftIcon className="w-5 h-5" />
            رجوع
          </button>
          <div className="flex items-center gap-3">
            <ShoppingBagIcon className="w-8 h-8 text-indigo-600" />
            <div>
              <h1 className="text-3xl font-bold text-gray-900">
                {catalog.name}
              </h1>
              {catalog.description && (
                <p className="mt-1 text-sm text-gray-600">
                  {catalog.description}
                </p>
              )}
            </div>
          </div>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleSync}
            disabled={syncing || (!syncAll && selectedProducts.length === 0)}
            className="flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 disabled:opacity-50"
          >
            <ArrowPathIcon
              className={`w-5 h-5 ${syncing ? "animate-spin" : ""}`}
            />
            {syncing ? "جاري المزامنة..." : "مزامنة المنتجات"}
          </button>
          <button
            onClick={handleDelete}
            className="flex items-center gap-2 px-4 py-2 text-red-600 bg-white border border-red-300 rounded-lg hover:bg-red-50"
          >
            <TrashIcon className="w-5 h-5" />
            حذف
          </button>
        </div>
      </div>

      {/* Info Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-sm text-gray-600">إجمالي المنتجات</p>
          <p className="mt-1 text-2xl font-bold text-gray-900">
            {catalog.totalProducts || 0}
          </p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-sm text-gray-600">المنتجات المتزامنة</p>
          <p className="mt-1 text-2xl font-bold text-green-600">
            {catalog.syncedProducts || 0}
          </p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-sm text-gray-600">حالة المزامنة</p>
          <div className="mt-1 flex items-center gap-2">
            {getSyncStatusIcon(catalog.lastSyncStatus)}
            <span className="text-sm font-medium text-gray-900">
              {catalog.lastSyncStatus === "SUCCESS"
                ? "مكتمل"
                : catalog.lastSyncStatus === "FAILED"
                  ? "فشل"
                  : catalog.lastSyncStatus === "IN_PROGRESS"
                    ? "جاري"
                    : "غير متزامن"}
            </span>
          </div>
          {catalog.lastSyncAt && (
            <p className="mt-1 text-xs text-gray-500">
              {new Date(catalog.lastSyncAt).toLocaleString("ar-EG")}
            </p>
          )}
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-sm text-gray-600">الحالة</p>
          <p className="mt-1">
            <span
              className={`inline-block px-3 py-1 text-sm font-medium rounded-full ${
                catalog.status === "ACTIVE"
                  ? "bg-green-100 text-green-800"
                  : "bg-gray-100 text-gray-800"
              }`}
            >
              {catalog.status === "ACTIVE"
                ? "نشط"
                : catalog.status === "PAUSED"
                  ? "متوقف"
                  : "محذوف"}
            </span>
          </p>
        </div>
      </div>

      {/* Sync Options */}
      <div className="bg-white rounded-lg shadow p-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">
          خيارات المزامنة
        </h2>
        <div className="space-y-4">
          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="radio"
              checked={syncAll}
              onChange={() => {
                setSyncAll(true);
                setSelectedProducts([]);
              }}
              className="w-4 h-4 text-indigo-600 border-gray-300 focus:ring-indigo-500"
            />
            <div>
              <p className="font-medium text-gray-900">مزامنة جميع المنتجات</p>
              <p className="text-sm text-gray-500">
                سيتم مزامنة جميع المنتجات النشطة
              </p>
            </div>
          </label>
          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="radio"
              checked={!syncAll}
              onChange={() => setSyncAll(false)}
              className="w-4 h-4 text-indigo-600 border-gray-300 focus:ring-indigo-500"
            />
            <div>
              <p className="font-medium text-gray-900">مزامنة منتجات محددة</p>
              <p className="text-sm text-gray-500">
                اختر المنتجات التي تريد مزامنتها
              </p>
            </div>
          </label>
        </div>
      </div>

      {/* Products List */}
      <div className="bg-white rounded-lg shadow">
        <div className="p-6 border-b border-gray-200 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-900">
            المنتجات في Catalog
          </h2>
          <div className="flex items-center gap-3">
            {!syncAll && selectedProducts.length > 0 && (
              <span className="text-sm text-gray-600">
                {selectedProducts.length} منتج محدد
              </span>
            )}
          </div>
        </div>

        {loadingProducts ? (
          <div className="p-12 text-center">
            <ArrowPathIcon className="w-8 h-8 animate-spin mx-auto text-indigo-600" />
            <p className="mt-2 text-gray-600">جاري تحميل المنتجات...</p>
          </div>
        ) : products.length === 0 ? (
          <div className="p-12 text-center">
            <ShoppingBagIcon className="w-16 h-16 mx-auto text-gray-400" />
            <h3 className="mt-4 text-lg font-medium text-gray-900">
              لا توجد منتجات
            </h3>
            <p className="mt-2 text-sm text-gray-500">
              ابدأ بمزامنة المنتجات مع Catalog
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  {!syncAll && (
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                      <input
                        type="checkbox"
                        checked={
                          selectedProducts.length === products.length &&
                          products.length > 0
                        }
                        onChange={(e) => {
                          if (e.target.checked) {
                            setSelectedProducts(products.map((p) => p.id));
                          } else {
                            setSelectedProducts([]);
                          }
                        }}
                        className="w-4 h-4 text-indigo-600 border-gray-300 rounded"
                      />
                    </th>
                  )}
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    المنتج
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    السعر
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    الحالة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    حالة المزامنة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    آخر مزامنة
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {products.map((product) => (
                  <tr key={product.id} className="hover:bg-gray-50">
                    {!syncAll && (
                      <td className="px-6 py-4 whitespace-nowrap">
                        <input
                          type="checkbox"
                          checked={selectedProducts.includes(product.id)}
                          onChange={() => toggleProductSelection(product.id)}
                          className="w-4 h-4 text-indigo-600 border-gray-300 rounded"
                        />
                      </td>
                    )}
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        {product.imageUrl && (
                          <img
                            src={product.imageUrl}
                            alt={product.name}
                            className="w-10 h-10 rounded object-cover mr-3"
                          />
                        )}
                        <div>
                          <div className="text-sm font-medium text-gray-900">
                            {product.name}
                          </div>
                          {product.sku && (
                            <div className="text-sm text-gray-500">
                              SKU: {product.sku}
                            </div>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {product.price
                        ? `${product.price} ${product.currency || "EGP"}`
                        : "-"}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          product.availability === "in stock"
                            ? "bg-green-100 text-green-800"
                            : "bg-gray-100 text-gray-800"
                        }`}
                      >
                        {product.availability === "in stock"
                          ? "متوفر"
                          : "غير متوفر"}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          product.syncStatus === "SYNCED"
                            ? "bg-green-100 text-green-800"
                            : product.syncStatus === "FAILED"
                              ? "bg-red-100 text-red-800"
                              : "bg-yellow-100 text-yellow-800"
                        }`}
                      >
                        {product.syncStatus === "SYNCED"
                          ? "متزامن"
                          : product.syncStatus === "FAILED"
                            ? "فشل"
                            : product.syncStatus === "UPDATED"
                              ? "محدث"
                              : "في الانتظار"}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {product.lastSyncedAt
                        ? new Date(product.lastSyncedAt).toLocaleDateString(
                            "ar-EG",
                          )
                        : "-"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default CatalogDetails;

/**
 * Catalogs Management Page
 *
 * صفحة إدارة Product Catalogs
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  PlusIcon,
  TrashIcon,
  EyeIcon,
  ArrowPathIcon,
  FolderIcon,
  ShoppingBagIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookProductCatalog,
} from "../../services/facebookAdsService";

const CatalogsManagement: React.FC = () => {
  const navigate = useNavigate();
  const [catalogs, setCatalogs] = useState<FacebookProductCatalog[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [businessId, setBusinessId] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    loadCatalogs();
  }, []);

  const loadCatalogs = async () => {
    try {
      setLoading(true);
      setErrors({});

      if (!businessId) {
        setErrors({ businessId: "Business ID is required" });
        setLoading(false);
        return;
      }

      const data = await facebookAdsService.getCatalogs(businessId);
      setCatalogs(data);
    } catch (error: any) {
      console.error("Error loading catalogs:", error);
      const errorMsg = error?.response?.data?.error || "فشل في تحميل Catalogs";
      toast.error(errorMsg);
      if (errorMsg.includes("Business ID")) {
        setErrors({ businessId: errorMsg });
      }
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await loadCatalogs();
    setRefreshing(false);
    toast.success("تم تحديث البيانات");
  };

  const handleCreateCatalog = () => {
    navigate("/advertising/facebook-ads/catalogs/create");
  };

  const handleViewCatalog = (id: string) => {
    navigate(`/advertising/facebook-ads/catalogs/${id}`);
  };

  const handleDeleteCatalog = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (
      !confirm(
        "هل أنت متأكد من حذف هذا Catalog؟ سيتم حذف جميع المنتجات المرتبطة به.",
      )
    )
      return;

    try {
      await facebookAdsService.deleteCatalog(id);
      toast.success("تم حذف Catalog بنجاح");
      await loadCatalogs();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في حذف Catalog");
    }
  };

  const getSyncStatusBadge = (status?: string) => {
    if (!status) return "bg-gray-100 text-gray-800";

    switch (status) {
      case "SUCCESS":
        return "bg-green-100 text-green-800";
      case "FAILED":
        return "bg-red-100 text-red-800";
      case "IN_PROGRESS":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const getSyncStatusLabel = (status?: string) => {
    if (!status) return "غير متزامن";

    switch (status) {
      case "SUCCESS":
        return "مكتمل";
      case "FAILED":
        return "فشل";
      case "IN_PROGRESS":
        return "جاري المزامنة";
      default:
        return "غير متزامن";
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <ArrowPathIcon className="w-8 h-8 animate-spin mx-auto text-indigo-600" />
          <p className="mt-2 text-gray-600">جاري التحميل...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            إدارة Product Catalogs
          </h1>
          <p className="mt-2 text-sm text-gray-600">
            أدر Product Catalogs لحملات Dynamic Ads
          </p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleRefresh}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50"
          >
            <ArrowPathIcon
              className={`w-5 h-5 ${refreshing ? "animate-spin" : ""}`}
            />
            تحديث
          </button>
          <button
            onClick={handleCreateCatalog}
            className="flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
          >
            <PlusIcon className="w-5 h-5" />
            Catalog جديد
          </button>
        </div>
      </div>

      {/* Business ID Input */}
      <div className="bg-white p-4 rounded-lg shadow">
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Business ID (اختياري)
        </label>
        <div className="flex gap-3">
          <input
            type="text"
            value={businessId}
            onChange={(e) => {
              setBusinessId(e.target.value);
              if (errors["businessId"])
                setErrors({ ...errors, businessId: "" });
            }}
            placeholder="أدخل Facebook Business ID"
            className={`flex-1 px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 ${
              errors["businessId"] ? "border-red-500" : "border-gray-300"
            }`}
          />
          <button
            onClick={loadCatalogs}
            className="px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
          >
            تحميل
          </button>
        </div>
        {errors["businessId"] && (
          <p className="mt-2 text-sm text-red-600 flex items-center gap-1">
            <span className="inline-block w-1 h-1 bg-red-600 rounded-full"></span>
            {errors["businessId"]}
          </p>
        )}
        <p className="mt-2 text-xs text-gray-500">
          يمكنك العثور على Business ID من Facebook Business Manager
        </p>
      </div>

      {/* Catalogs List */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        {catalogs.length === 0 ? (
          <div className="text-center py-12">
            <FolderIcon className="w-16 h-16 mx-auto text-gray-400" />
            <h3 className="mt-4 text-lg font-medium text-gray-900">
              لا توجد Catalogs
            </h3>
            <p className="mt-2 text-sm text-gray-500">
              ابدأ بإنشاء Catalog جديد لحملات Dynamic Ads
            </p>
            <button
              onClick={handleCreateCatalog}
              className="mt-6 inline-flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
            >
              <PlusIcon className="w-5 h-5" />
              إنشاء Catalog جديد
            </button>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                    الاسم
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                    المنتجات
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                    آخر مزامنة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                    الحالة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                    تاريخ الإنشاء
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                    الإجراءات
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {catalogs.map((catalog) => (
                  <tr
                    key={catalog.id}
                    className="hover:bg-gray-50 cursor-pointer"
                    onClick={() => handleViewCatalog(catalog.id)}
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <ShoppingBagIcon className="w-5 h-5 text-gray-400 mr-3" />
                        <div>
                          <div className="text-sm font-medium text-gray-900">
                            {catalog.name}
                          </div>
                          {catalog.description && (
                            <div className="text-sm text-gray-500">
                              {catalog.description}
                            </div>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-gray-900">
                        {catalog.syncedProducts || 0} /{" "}
                        {catalog.totalProducts || 0}
                      </div>
                      <div className="text-xs text-gray-500">منتج متزامن</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {catalog.lastSyncAt ? (
                        <div>
                          <div className="text-sm text-gray-900">
                            {new Date(catalog.lastSyncAt).toLocaleDateString(
                              "ar-EG",
                            )}
                          </div>
                          <span
                            className={`inline-block px-2 py-1 text-xs font-medium rounded-full ${getSyncStatusBadge(catalog.lastSyncStatus)}`}
                          >
                            {getSyncStatusLabel(catalog.lastSyncStatus)}
                          </span>
                        </div>
                      ) : (
                        <span className="text-sm text-gray-500">
                          لم يتم المزامنة
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          catalog.status === "ACTIVE"
                            ? "bg-green-100 text-green-800"
                            : "bg-gray-100 text-gray-800"
                        }`}
                      >
                        {catalog.status === "ACTIVE"
                          ? "نشط"
                          : catalog.status === "PAUSED"
                            ? "متوقف"
                            : "محذوف"}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {new Date(catalog.createdAt).toLocaleDateString("ar-EG")}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      <div className="flex items-center justify-end gap-2">
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleViewCatalog(catalog.id);
                          }}
                          className="text-indigo-600 hover:text-indigo-900"
                        >
                          <EyeIcon className="w-5 h-5" />
                        </button>
                        <button
                          onClick={(e) => handleDeleteCatalog(catalog.id, e)}
                          className="text-red-600 hover:text-red-900"
                        >
                          <TrashIcon className="w-5 h-5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default CatalogsManagement;

/**
 * 📊 Conversion API (CAPI) Dashboard
 *
 * لوحة تحكم لإدارة وإرسال أحداث التحويل عبر Facebook Conversion API
 */

import React, { useState } from "react";
import { toast } from "react-hot-toast";
import {
  Activity,
  Send,
  ShoppingCart,
  UserPlus,
  Eye,
  CreditCard,
  Phone,
  Mail,
  CheckCircle,
  Loader2,
  History,
  TrendingUp,
  AlertTriangle,
  Settings,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

interface ConversionEvent {
  id: string;
  eventName: string;
  timestamp: string;
  status: "success" | "failed" | "pending";
  value?: number;
  currency?: string;
}

const ConversionApiDashboard: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<"send" | "history" | "settings">(
    "send",
  );
  const [recentEvents, setRecentEvents] = useState<ConversionEvent[]>([]);

  const [eventData, setEventData] = useState({
    pixelId: "",
    eventName: "Purchase",
    eventSourceUrl: "",
    // User Data
    email: "",
    phone: "",
    firstName: "",
    lastName: "",
    city: "",
    country: "SA",
    // Custom Data
    value: 0,
    currency: "SAR",
    contentIds: "",
    contentType: "product",
    contentName: "",
    numItems: 1,
    orderId: "",
    // Action Source
    actionSource: "website" as const,
  });

  const eventTypes = [
    { value: "Purchase", label: "شراء", icon: CreditCard, color: "green" },
    { value: "Lead", label: "عميل محتمل", icon: UserPlus, color: "blue" },
    {
      value: "AddToCart",
      label: "إضافة للسلة",
      icon: ShoppingCart,
      color: "orange",
    },
    { value: "ViewContent", label: "مشاهدة محتوى", icon: Eye, color: "purple" },
    {
      value: "InitiateCheckout",
      label: "بدء الدفع",
      icon: CreditCard,
      color: "indigo",
    },
    {
      value: "CompleteRegistration",
      label: "إكمال التسجيل",
      icon: CheckCircle,
      color: "teal",
    },
    { value: "Contact", label: "تواصل", icon: Phone, color: "pink" },
    { value: "Subscribe", label: "اشتراك", icon: Mail, color: "cyan" },
  ];

  const currencies = [
    { code: "SAR", name: "ريال سعودي" },
    { code: "AED", name: "درهم إماراتي" },
    { code: "EGP", name: "جنيه مصري" },
    { code: "USD", name: "دولار أمريكي" },
    { code: "EUR", name: "يورو" },
  ];

  const actionSources = [
    { value: "website", label: "موقع ويب" },
    { value: "app", label: "تطبيق" },
    { value: "phone_call", label: "مكالمة هاتفية" },
    { value: "chat", label: "محادثة" },
    { value: "email", label: "بريد إلكتروني" },
    { value: "physical_store", label: "متجر فعلي" },
  ];

  const handleSendEvent = async () => {
    if (!eventData.pixelId) {
      toast.error("يرجى إدخال معرف Facebook Pixel");
      return;
    }

    try {
      setLoading(true);

      const payload: any = {
        pixelId: eventData.pixelId,
        eventName: eventData.eventName,
        actionSource: eventData.actionSource,
      };

      // Add event source URL if provided
      if (eventData.eventSourceUrl) {
        payload.eventSourceUrl = eventData.eventSourceUrl;
      }

      // Add user data
      const userData: any = {};
      if (eventData.email) userData.email = eventData.email;
      if (eventData.phone) userData.phone = eventData.phone;
      if (eventData.firstName) userData.firstName = eventData.firstName;
      if (eventData.lastName) userData.lastName = eventData.lastName;
      if (eventData.city) userData.city = eventData.city;
      if (eventData.country) userData.country = eventData.country;

      if (Object.keys(userData).length > 0) {
        payload.userData = userData;
      }

      // Add custom data for purchase events
      if (eventData.eventName === "Purchase" || eventData.value > 0) {
        const customData: any = {};
        if (eventData.value > 0) {
          customData.value = eventData.value;
          customData.currency = eventData.currency;
        }
        if (eventData.contentIds) {
          customData.contentIds = eventData.contentIds
            .split(",")
            .map((id) => id.trim());
        }
        if (eventData.contentType)
          customData.contentType = eventData.contentType;
        if (eventData.contentName)
          customData.contentName = eventData.contentName;
        if (eventData.numItems > 0) customData.numItems = eventData.numItems;
        if (eventData.orderId) customData.orderId = eventData.orderId;

        if (Object.keys(customData).length > 0) {
          payload.customData = customData;
        }
      }

      await facebookAdsService.sendConversionEvent(payload);

      // Add to recent events
      const newEvent: ConversionEvent = {
        id: Date.now().toString(),
        eventName: eventData.eventName,
        timestamp: new Date().toISOString(),
        status: "success",
        value: eventData.value,
        currency: eventData.currency,
      };
      setRecentEvents((prev) => [newEvent, ...prev.slice(0, 9)]);

      toast.success("تم إرسال الحدث بنجاح! ✅");
    } catch (error: any) {
      console.error("Error sending event:", error);

      // Add failed event
      const failedEvent: ConversionEvent = {
        id: Date.now().toString(),
        eventName: eventData.eventName,
        timestamp: new Date().toISOString(),
        status: "failed",
      };
      setRecentEvents((prev) => [failedEvent, ...prev.slice(0, 9)]);

      toast.error(error?.response?.data?.error || "فشل في إرسال الحدث");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="p-6 space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <Activity className="w-7 h-7 text-blue-600 dark:text-blue-400" />
            Conversion API (CAPI)
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            إرسال أحداث التحويل مباشرة إلى Facebook لتحسين تتبع الإعلانات
          </p>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-200 dark:border-gray-700 shadow-sm dark:shadow-gray-900/20">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg">
              <CheckCircle className="w-6 h-6 text-green-600 dark:text-green-400" />
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                نجح اليوم
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                24
              </p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-200 dark:border-gray-700 shadow-sm dark:shadow-gray-900/20">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-red-100 dark:bg-red-900/30 rounded-lg">
              <AlertTriangle className="w-6 h-6 text-red-600 dark:text-red-400" />
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                فشل اليوم
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                2
              </p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-200 dark:border-gray-700 shadow-sm dark:shadow-gray-900/20">
          <div className="flex items-center gap-3">
