                      }
                      placeholder="0"
                      min={0}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">
                      العملة
                    </label>
                    <select
                      value={eventData.currency}
                      onChange={(e) =>
                        setEventData((prev) => ({
                          ...prev,
                          currency: e.target.value,
                        }))
                      }
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                    >
                      {currencies.map((c) => (
                        <option key={c.code} value={c.code}>
                          {c.name}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">
                      رقم الطلب
                    </label>
                    <input
                      type="text"
                      value={eventData.orderId}
                      onChange={(e) =>
                        setEventData((prev) => ({
                          ...prev,
                          orderId: e.target.value,
                        }))
                      }
                      placeholder="ORD-123"
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Action Source */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                مصدر الحدث
              </label>
              <select
                value={eventData.actionSource}
                onChange={(e) =>
                  setEventData((prev) => ({
                    ...prev,
                    actionSource: e.target.value as any,
                  }))
                }
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
              >
                {actionSources.map((source) => (
                  <option key={source.value} value={source.value}>
                    {source.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Submit */}
            <button
              onClick={handleSendEvent}
              disabled={loading || !eventData.pixelId}
              className="w-full py-3 text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  جاري الإرسال...
                </>
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  إرسال الحدث
                </>
              )}
            </button>
          </div>
        )}

        {/* History Tab */}
        {activeTab === "history" && (
          <div className="p-6">
            {recentEvents.length === 0 ? (
              <div className="text-center py-12">
                <History className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                <p className="text-gray-500">لا توجد أحداث مسجلة</p>
              </div>
            ) : (
              <div className="space-y-3">
                {recentEvents.map((event) => (
                  <div
                    key={event.id}
                    className="flex items-center justify-between p-4 bg-gray-50 rounded-lg"
                  >
                    <div className="flex items-center gap-3">
                      <div
                        className={`p-2 rounded-lg ${
                          event.status === "success"
                            ? "bg-green-100"
                            : "bg-red-100"
                        }`}
                      >
                        {event.status === "success" ? (
                          <CheckCircle className="w-5 h-5 text-green-600" />
                        ) : (
                          <AlertTriangle className="w-5 h-5 text-red-600" />
                        )}
                      </div>
                      <div>
                        <p className="font-medium text-gray-900">
                          {event.eventName}
                        </p>
                        <p className="text-sm text-gray-500">
                          {new Date(event.timestamp).toLocaleString("ar-EG")}
                        </p>
                      </div>
                    </div>
                    {event.value && (
                      <div className="text-left">
                        <p className="font-semibold text-gray-900">
                          {event.value.toLocaleString()} {event.currency}
                        </p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Settings Tab */}
        {activeTab === "settings" && (
          <div className="p-6">
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
              <h3 className="font-medium text-blue-900 mb-2">
                نصائح لتحسين CAPI
              </h3>
              <ul className="text-sm text-blue-700 space-y-1">
                <li>• أرسل أكبر قدر ممكن من بيانات المستخدم لتحسين المطابقة</li>
                <li>• استخدم نفس Pixel ID المستخدم في موقعك</li>
                <li>• أرسل الأحداث في الوقت الفعلي للحصول على أفضل النتائج</li>
                <li>• تأكد من تشفير البيانات الحساسة قبل الإرسال</li>
              </ul>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ConversionApiDashboard;

/**
 * Create A/B Test Page
 *
 * صفحة إنشاء اختبار A/B جديد
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeftIcon, CheckCircleIcon } from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  CreateAdTestData,
  FacebookCampaign,
} from "../../services/facebookAdsService";

const CreateABTest: React.FC = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [campaigns, setCampaigns] = useState<FacebookCampaign[]>([]);
  const [loadingCampaigns, setLoadingCampaigns] = useState(true);

  const [formData, setFormData] = useState<CreateAdTestData>({
    name: "",
    description: "",
    testType: "CREATIVE",
    campaignId: "",
    variants: [{ name: "Variant A" }, { name: "Variant B" }],
    trafficSplit: 50,
    minimumResults: 100,
    autoPromote: false,
  });

  const totalSteps = 3;

  useEffect(() => {
    loadCampaigns();
  }, []);

  const loadCampaigns = async () => {
    try {
      setLoadingCampaigns(true);
      const data = await facebookAdsService.getCampaigns();
      setCampaigns(
        data.filter((c) => c.status === "ACTIVE" || c.status === "PAUSED"),
      );
    } catch (error: any) {
      console.error("Error loading campaigns:", error);
      toast.error("فشل في تحميل الحملات");
    } finally {
      setLoadingCampaigns(false);
    }
  };

  const handleInputChange = (field: keyof CreateAdTestData, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const handleVariantChange = (index: number, field: string, value: any) => {
    const updatedVariants = [...formData.variants];
    updatedVariants[index] = { ...updatedVariants[index], [field]: value };
    setFormData((prev) => ({ ...prev, variants: updatedVariants }));
  };

  const validateStep = (step: number): boolean => {
    switch (step) {
      case 1:
        if (!formData.name.trim()) {
          toast.error("يرجى إدخال اسم الاختبار");
          return false;
        }
        if (!formData.testType) {
          toast.error("يرجى اختيار نوع الاختبار");
          return false;
        }
        return true;
      case 2:
        if (!formData.campaignId) {
          toast.error("يرجى اختيار الحملة");
          return false;
        }
        if (formData.variants.length < 2) {
          toast.error("يرجى إضافة متغيرين على الأقل");
          return false;
        }
        return true;
      case 3:
        return true; // Review step
      default:
        return true;
    }
  };

  const handleNext = () => {
    if (validateStep(currentStep)) {
      if (currentStep < totalSteps) {
        setCurrentStep(currentStep + 1);
      }
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = async () => {
    if (!validateStep(currentStep)) return;

    try {
      setLoading(true);
      await facebookAdsService.createAdTest(formData);
      toast.success("تم إنشاء الاختبار بنجاح");
      navigate("/advertising/facebook-ads/tests");
    } catch (error: any) {
      console.error("Error creating test:", error);
      toast.error(error?.response?.data?.error || "فشل في إنشاء الاختبار");
    } finally {
      setLoading(false);
    }
  };

  const testTypes = [
    {
      value: "CREATIVE",
      label: "Creative",
      description: "اختبار صور أو نصوص مختلفة",
    },
    {
      value: "TARGETING",
      label: "Targeting",
      description: "اختبار جماهير مستهدفة مختلفة",
    },
    { value: "BUDGET", label: "Budget", description: "اختبار ميزانيات مختلفة" },
    {
      value: "PLACEMENT",
      label: "Placement",
      description: "اختبار مواقع عرض مختلفة",
    },
  ];

  return (
    <div className="w-full space-y-6">
      {/* Header */}
      <div>
        <button
          onClick={() => navigate("/advertising/facebook-ads/tests")}
          className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          رجوع
        </button>
        <h1 className="text-3xl font-bold text-gray-900">إنشاء اختبار A/B</h1>
        <p className="mt-2 text-sm text-gray-600">
          أنشئ اختبار A/B لتحسين أداء الإعلانات
        </p>
      </div>

      {/* Progress Steps */}
      <div className="bg-white p-6 rounded-lg shadow">
        <div className="flex items-center justify-between">
          {[1, 2, 3].map((step) => (
            <React.Fragment key={step}>
              <div className="flex flex-col items-center flex-1">
                <div
                  className={`w-10 h-10 rounded-full flex items-center justify-center ${
                    step < currentStep
                      ? "bg-green-500 text-white"
                      : step === currentStep
                        ? "bg-indigo-600 text-white"
                        : "bg-gray-200 text-gray-600"
                  }`}
                >
                  {step < currentStep ? (
                    <CheckCircleIcon className="w-6 h-6" />
                  ) : (
                    <span>{step}</span>
                  )}
                </div>
                <p
                  className={`mt-2 text-sm font-medium ${
                    step <= currentStep ? "text-gray-900" : "text-gray-500"
                  }`}
                >
                  {step === 1 && "معلومات الاختبار"}
                  {step === 2 && "المتغيرات"}
                  {step === 3 && "المراجعة"}
                </p>
              </div>
              {step < 3 && (
                <div
                  className={`flex-1 h-1 mx-4 ${
                    step < currentStep ? "bg-green-500" : "bg-gray-200"
                  }`}
                />
              )}
            </React.Fragment>
          ))}
        </div>
      </div>

      {/* Form Content */}
      <div className="bg-white rounded-lg shadow p-6">
        {/* Step 1: Test Info */}
        {currentStep === 1 && (
          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                اسم الاختبار *
              </label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => handleInputChange("name", e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                placeholder="مثال: اختبار Creative - صيف 2025"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                الوصف
              </label>
              <textarea
                value={formData.description}
                onChange={(e) =>
                  handleInputChange("description", e.target.value)
                }
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                rows={3}
                placeholder="وصف الاختبار..."
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                نوع الاختبار *
              </label>
              <div className="grid grid-cols-2 gap-4">
                {testTypes.map((type) => (
                  <button
                    key={type.value}
                    onClick={() => handleInputChange("testType", type.value)}
                    className={`p-4 border-2 rounded-lg text-left ${
                      formData.testType === type.value
                        ? "border-indigo-600 bg-indigo-50"
                        : "border-gray-200 hover:border-gray-300"
                    }`}
                  >
                    <div className="font-medium text-gray-900">
                      {type.label}
                    </div>
                    <div className="text-sm text-gray-600 mt-1">
                      {type.description}
                    </div>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                توزيع حركة المرور (Traffic Split)
              </label>
              <input
                type="number"
                value={formData.trafficSplit}
                onChange={(e) =>
                  handleInputChange("trafficSplit", parseInt(e.target.value))
                }
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                min={10}
                max={90}
                step={10}
              />
              <p className="mt-1 text-sm text-gray-500">
                {formData.trafficSplit}% / {100 - formData.trafficSplit}%
              </p>
            </div>
          </div>
        )}

        {/* Step 2: Variants */}
        {currentStep === 2 && (
          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                الحملة *
              </label>
              {loadingCampaigns ? (
                <div className="text-center py-4">
                  <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-indigo-600 mx-auto"></div>
                </div>
              ) : campaigns.length === 0 ? (
                <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                  <p className="text-sm text-yellow-800">
                    لا توجد حملات متاحة. يرجى إنشاء حملة أولاً.
                  </p>
                </div>
              ) : (
                <select
                  value={formData.campaignId}
                  onChange={(e) =>
                    handleInputChange("campaignId", e.target.value)
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                  required
                >
                  <option value="">اختر الحملة</option>
                  {campaigns.map((campaign) => (
                    <option key={campaign.id} value={campaign.id}>
                      {campaign.name}
                    </option>
                  ))}
                </select>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                المتغيرات (Variants)
              </label>
              {formData.variants.map((variant, index) => (
                <div
                  key={index}
                  className="mb-4 p-4 border border-gray-200 rounded-lg"
                >
                  <div className="font-medium text-gray-900 mb-2">
                    {variant.name ||
                      `Variant ${String.fromCharCode(65 + index)}`}
                  </div>
                  <input
                    type="text"
                    value={variant.name}
                    onChange={(e) =>
                      handleVariantChange(index, "name", e.target.value)
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                    placeholder={`اسم Variant ${String.fromCharCode(65 + index)}`}
                  />
                  <p className="mt-2 text-sm text-gray-500">
                    سيتم إضافة المزيد من الحقول حسب نوع الاختبار في المرحلة
                    القادمة
                  </p>
                </div>
              ))}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                الحد الأدنى للنتائج (Minimum Results)
              </label>
              <input
                type="number"
                value={formData.minimumResults}
                onChange={(e) =>
                  handleInputChange("minimumResults", parseInt(e.target.value))
                }
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                min={50}
                step={50}
              />
              <p className="mt-1 text-sm text-gray-500">
                عدد التحويلات المطلوبة لتحديد الفائز
              </p>
            </div>

            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="autoPromote"
                checked={formData.autoPromote}
                onChange={(e) =>
                  handleInputChange("autoPromote", e.target.checked)
                }
                className="w-4 h-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500"
              />
              <label htmlFor="autoPromote" className="text-sm text-gray-700">
                تعزيز الفائز تلقائياً عند الوصول لثقة إحصائية 95%
              </label>
            </div>
          </div>
        )}

        {/* Step 3: Review */}
        {currentStep === 3 && (
          <div className="space-y-6">
            <div className="bg-gray-50 rounded-lg p-6 space-y-4">
              <h3 className="font-medium text-gray-900">مراجعة المعلومات</h3>

              <div>
                <span className="text-sm text-gray-500">اسم الاختبار:</span>
                <p className="font-medium">{formData.name}</p>
              </div>

              {formData.description && (
                <div>
                  <span className="text-sm text-gray-500">الوصف:</span>
                  <p className="font-medium">{formData.description}</p>
                </div>
              )}

              <div>
                <span className="text-sm text-gray-500">نوع الاختبار:</span>
                <p className="font-medium">
                  {testTypes.find((t) => t.value === formData.testType)?.label}
                </p>
              </div>

              <div>
                <span className="text-sm text-gray-500">الحملة:</span>
                <p className="font-medium">
                  {campaigns.find((c) => c.id === formData.campaignId)?.name ||
                    "-"}
                </p>
              </div>

              <div>
                <span className="text-sm text-gray-500">عدد المتغيرات:</span>
                <p className="font-medium">{formData.variants.length}</p>
              </div>

              <div>
                <span className="text-sm text-gray-500">
                  توزيع حركة المرور:
                </span>
                <p className="font-medium">
                  {formData.trafficSplit}% / {100 - formData.trafficSplit}%
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Navigation Buttons */}
        <div className="flex items-center justify-between mt-8 pt-6 border-t border-gray-200">
          <button
            onClick={handlePrevious}
            disabled={currentStep === 1}
            className="px-6 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            السابق
          </button>

          {currentStep < totalSteps ? (
            <button
              onClick={handleNext}
              className="px-6 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
            >
              التالي
            </button>
          ) : (
            <button
              onClick={handleSubmit}
              disabled={loading}
              className="px-6 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 disabled:opacity-50"
            >
              {loading ? "جاري الإنشاء..." : "إنشاء الاختبار"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default CreateABTest;

/**
 * Create Ad Page
 *
 * صفحة إنشاء إعلان جديد (Creative)
 */

import React, { useState, useEffect, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  CheckCircleIcon,
  PhotoIcon,
  VideoCameraIcon,
  RectangleStackIcon,
  XMarkIcon,
  PlusIcon,
  EyeIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  CreateAdData,
  CALL_TO_ACTION_TYPES,
} from "../../services/facebookAdsService";
import { useAuth } from "../../hooks/useAuthSimple";
import { apiClient } from "../../services/apiClient";

interface FacebookPage {
  id: string;
  pageId: string;
  pageName: string;
  status: string;
}

const CreateAd: React.FC = () => {
  const { adSetId } = useParams<{ adSetId: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [currentStep, setCurrentStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [facebookPages, setFacebookPages] = useState<FacebookPage[]>([]);
  const [loadingPages, setLoadingPages] = useState(true);
  const [previewMode, setPreviewMode] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  // Form data
  const [formData, setFormData] = useState<
    CreateAdData & {
      pageId?: string;
      imageFile?: File | null;
      videoFile?: File | null;
      uploadedImageHash?: string;
      uploadedVideoId?: string;
      imagePreview?: string;
      videoPreview?: string;
    }
  >({
    adSetId: adSetId || "",
    name: "",
    status: "PAUSED",
    creativeType: "SINGLE_IMAGE",
    primaryText: "",
    headline: "",
    description: "",
    callToAction: "LEARN_MORE",
    linkUrl: "",
    pageId: "",
    imageFile: null,
    videoFile: null,
  });

  const totalSteps = 4;

  useEffect(() => {
    loadFacebookPages();
  }, []);

  const loadFacebookPages = async () => {
    if (!user?.companyId) return;

    try {
      setLoadingPages(true);
      const response = await apiClient.get(
        "/facebook-integration/connected-pages",
      );
      if (response.data.success && response.data.pages) {
        setFacebookPages(
          response.data.pages.filter(
            (p: FacebookPage) => p.status === "connected",
          ),
        );
        if (response.data.pages.length === 1 && !formData.pageId) {
          setFormData((prev) => ({
            ...prev,
            pageId: response.data.pages[0].pageId,
          }));
        }
      }
    } catch (error: any) {
      console.error("Error loading Facebook Pages:", error);
      // لا نعرض خطأ لأن Page اختياري في بعض الحالات
    } finally {
      setLoadingPages(false);
    }
  };

  const handleInputChange = (field: string, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate image
    if (!file.type.startsWith("image/")) {
      toast.error("الملف المحدد ليس صورة");
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      // 10MB
      toast.error("حجم الصورة كبير جداً. الحد الأقصى 10MB");
      return;
    }

    setFormData((prev) => ({
      ...prev,
      imageFile: file,
      imagePreview: URL.createObjectURL(file),
    }));
  };

  const handleVideoSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate video
    if (!file.type.startsWith("video/")) {
      toast.error("الملف المحدد ليس فيديو");
      return;
    }

    if (file.size > 500 * 1024 * 1024) {
      // 500MB
      toast.error("حجم الفيديو كبير جداً. الحد الأقصى 500MB");
      return;
    }

    setFormData((prev) => ({
      ...prev,
      videoFile: file,
      videoPreview: URL.createObjectURL(file),
    }));
  };

  const removeImage = () => {
    if (formData.imagePreview) {
      URL.revokeObjectURL(formData.imagePreview);
    }
    setFormData((prev) => ({
      ...prev,
      imageFile: null,
      imagePreview: undefined,
      uploadedImageHash: undefined,
    }));
  };

  const removeVideo = () => {
    if (formData.videoPreview) {
      URL.revokeObjectURL(formData.videoPreview);
    }
    setFormData((prev) => ({
      ...prev,
      videoFile: null,
      videoPreview: undefined,
      uploadedVideoId: undefined,
    }));
  };

  const uploadImage = async (): Promise<string | null> => {
    if (!formData.imageFile) return null;

    try {
      setUploading(true);
      toast.loading("جاري رفع الصورة...", { id: "upload-image" });

      // Create FormData
      const uploadFormData = new FormData();
      uploadFormData.append("image", formData.imageFile);
      uploadFormData.append("adSetId", formData.adSetId);

      // Upload to backend
      const response = await apiClient.post(
        "/facebook-ads/upload-image",
        uploadFormData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        },
      );

      if (response.data.success && response.data.hash) {
        toast.success("تم رفع الصورة بنجاح", { id: "upload-image" });
        return response.data.hash;
      } else {
        throw new Error(response.data.error || "فشل في رفع الصورة");
      }
    } catch (error: any) {
      console.error("Error uploading image:", error);
      toast.error(error?.response?.data?.error || "فشل في رفع الصورة", {
        id: "upload-image",
      });
      return null;
    } finally {
      setUploading(false);
    }
  };

  const uploadVideo = async (): Promise<string | null> => {
    if (!formData.videoFile) return null;

    try {
      setUploading(true);
      toast.loading("جاري رفع الفيديو...", { id: "upload-video" });

      // Create FormData
      const uploadFormData = new FormData();
      uploadFormData.append("video", formData.videoFile);
      uploadFormData.append("adSetId", formData.adSetId);
      uploadFormData.append("name", formData.name || "Video Ad");

      // Upload to backend
      const response = await apiClient.post(
        "/facebook-ads/upload-video",
        uploadFormData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
          timeout: 300000, // 5 minutes for video upload
        },
      );

      if (response.data.success && response.data.videoId) {
        toast.success("تم رفع الفيديو بنجاح", { id: "upload-video" });
        return response.data.videoId;
      } else {
        throw new Error(response.data.error || "فشل في رفع الفيديو");
      }
    } catch (error: any) {
      console.error("Error uploading video:", error);
      toast.error(error?.response?.data?.error || "فشل في رفع الفيديو", {
        id: "upload-video",
      });
      return null;
    } finally {
      setUploading(false);
    }
  };

  const validateStep = (step: number): boolean => {
    switch (step) {
      case 1:
        if (!formData.name.trim()) {
          toast.error("يرجى إدخال اسم الإعلان");
          return false;
        }
        if (!formData.creativeType) {
          toast.error("يرجى اختيار نوع الإعلان");
          return false;
        }
        return true;
      case 2:
        if (
          formData.creativeType === "SINGLE_IMAGE" &&
          !formData.imageFile &&
          !formData.imageUrl
        ) {
          toast.error("يرجى إضافة صورة للإعلان");
          return false;
        }
        if (
          formData.creativeType === "SINGLE_VIDEO" &&
          !formData.videoFile &&
          !formData.videoUrl
        ) {
          toast.error("يرجى إضافة فيديو للإعلان");
          return false;
        }
        return true;
      case 3:
        if (!formData.primaryText.trim()) {
          toast.error("يرجى إدخال نص الإعلان");
          return false;
        }
        if (!formData.linkUrl.trim()) {
          toast.error("يرجى إدخال رابط الإعلان");
          return false;
        }
        return true;
      case 4:
        return true; // Review step
      default:
        return true;
    }
  };

  const handleNext = async () => {
    if (!validateStep(currentStep)) {
      return;
    }

    // Upload media before moving to next step
    if (currentStep === 2) {
      if (
        formData.creativeType === "SINGLE_IMAGE" &&
        formData.imageFile &&
        !formData.uploadedImageHash
      ) {
        const hash = await uploadImage();
        if (hash) {
          setFormData((prev) => ({ ...prev, uploadedImageHash: hash }));
        } else {
          return; // Don't proceed if upload failed
        }
      } else if (
        formData.creativeType === "SINGLE_VIDEO" &&
        formData.videoFile &&
        !formData.uploadedVideoId
      ) {
        const videoId = await uploadVideo();
        if (videoId) {
          setFormData((prev) => ({ ...prev, uploadedVideoId: videoId }));
        } else {
          return; // Don't proceed if upload failed
        }
      }
    }

    if (currentStep < totalSteps) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = async () => {
    if (!validateStep(4)) {
      return;
    }

    // Upload media if not already uploaded
    let imageHash = formData.uploadedImageHash;
    let videoId = formData.uploadedVideoId;

    if (
      formData.creativeType === "SINGLE_IMAGE" &&
      formData.imageFile &&
      !imageHash
    ) {
      imageHash = await uploadImage();
      if (!imageHash) return;
    } else if (
      formData.creativeType === "SINGLE_VIDEO" &&
      formData.videoFile &&
      !videoId
    ) {
      videoId = await uploadVideo();
      if (!videoId) return;
    }

    try {
      setLoading(true);

      const adData: CreateAdData = {
        adSetId: formData.adSetId,
        name: formData.name,
        status: formData.status || "PAUSED",
        creativeType: formData.creativeType,
        primaryText: formData.primaryText,
        headline: formData.headline,
        description: formData.description,
        callToAction: formData.callToAction,
        linkUrl: formData.linkUrl,
        imageUrl: formData.imageUrl,
        videoUrl: formData.videoUrl,
        ...(imageHash && { imageHash }),
        ...(videoId && { videoId }),
        ...(formData.pageId && { pageId: formData.pageId }),
      };

      await facebookAdsService.createAd(adData);
      toast.success("تم إنشاء الإعلان بنجاح!");
      navigate(`/advertising/facebook-ads/campaigns/${adSetId}/adset`);
    } catch (error: any) {
      console.error("Error creating ad:", error);
      toast.error(error?.response?.data?.error || "فشل في إنشاء الإعلان");
    } finally {
      setLoading(false);
    }
  };

  const creativeTypes = [
    {
      value: "SINGLE_IMAGE",
      label: "صورة واحدة",
      icon: PhotoIcon,
      description: "إعلان بصورة واحدة ونص",
    },
    {
      value: "SINGLE_VIDEO",
      label: "فيديو واحد",
      icon: VideoCameraIcon,
      description: "إعلان بفيديو واحد ونص",
    },
    {
      value: "CAROUSEL",
      label: "Carousel",
      icon: RectangleStackIcon,
      description: "إعلان متعدد الصور (قريباً)",
    },
  ];

  return (
    <div className="w-full space-y-6">
      {/* Header */}
      <div>
        <button
          onClick={() => navigate(-1)}
          className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          رجوع
        </button>
        <h1 className="text-3xl font-bold text-gray-900">إنشاء إعلان جديد</h1>
        <p className="mt-2 text-sm text-gray-600">
          أنشئ إعلاناً جديداً مع Creative كامل
        </p>
      </div>

      {/* Progress Steps */}
      <div className="bg-white p-6 rounded-lg shadow">
        <div className="flex items-center justify-between">
          {[1, 2, 3, 4].map((step) => (
            <React.Fragment key={step}>
              <div className="flex flex-col items-center flex-1">
                <div
                  className={`w-10 h-10 rounded-full flex items-center justify-center ${
                    step < currentStep
                      ? "bg-green-500 text-white"
                      : step === currentStep
                        ? "bg-indigo-600 text-white"
                        : "bg-gray-200 text-gray-600"
                  }`}
                >
                  {step < currentStep ? (
                    <CheckCircleIcon className="w-6 h-6" />
                  ) : (
                    <span>{step}</span>
                  )}
                </div>
                <p
                  className={`mt-2 text-sm font-medium ${
                    step <= currentStep ? "text-gray-900" : "text-gray-500"
                  }`}
                >
                  {step === 1 && "معلومات الإعلان"}
                  {step === 2 && "الوسائط"}
                  {step === 3 && "النص والمحتوى"}
                  {step === 4 && "المراجعة"}
                </p>
              </div>
              {step < 4 && (
                <div
                  className={`flex-1 h-1 mx-4 ${
                    step < currentStep ? "bg-green-500" : "bg-gray-200"
                  }`}
                />
              )}
            </React.Fragment>
          ))}
        </div>
      </div>

      {/* Form Content */}
      <div className="bg-white p-8 rounded-lg shadow">
        {/* Step 1: Ad Info */}
        {currentStep === 1 && (
          <div className="space-y-6">
            <h2 className="text-xl font-semibold text-gray-900">
              معلومات الإعلان
            </h2>

            {/* Ad Name */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                اسم الإعلان *
              </label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => handleInputChange("name", e.target.value)}
                placeholder="مثال: إعلان صيف 2025"
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>

            {/* Creative Type */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-3">
                نوع الإعلان *
              </label>
              <div className="grid grid-cols-3 gap-4">
                {creativeTypes.map((type) => {
                  const Icon = type.icon;
                  const isSelected = formData.creativeType === type.value;
                  return (
                    <button
                      key={type.value}
                      onClick={() =>
                        handleInputChange("creativeType", type.value)
                      }
                      className={`p-6 border-2 rounded-lg text-left transition-all ${
                        isSelected
                          ? "border-indigo-600 bg-indigo-50"
                          : "border-gray-200 hover:border-gray-300"
                      } ${type.value === "CAROUSEL" ? "opacity-50 cursor-not-allowed" : ""}`}
                      disabled={type.value === "CAROUSEL"}
                    >
                      <Icon
                        className={`w-8 h-8 mb-2 ${isSelected ? "text-indigo-600" : "text-gray-400"}`}
                      />
                      <div className="font-medium text-gray-900">
                        {type.label}
                      </div>
                      <div className="text-sm text-gray-600 mt-1">
                        {type.description}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Facebook Page */}
            {loadingPages ? (
              <div className="text-center py-4">
                <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-indigo-600 mx-auto"></div>
              </div>
            ) : facebookPages.length > 0 ? (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  صفحة Facebook (لربط الإعلان)
                </label>
                <select
                  value={formData.pageId}
                  onChange={(e) => handleInputChange("pageId", e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                >
                  <option value="">اختر صفحة Facebook</option>
                  {facebookPages.map((page) => (
                    <option key={page.pageId} value={page.pageId}>
                      {page.pageName}
                    </option>
                  ))}
                </select>
                <p className="mt-1 text-sm text-gray-500">
                  الإعلان سيُنشر من هذه الصفحة
                </p>
              </div>
            ) : null}

            {/* Ad Status */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                حالة الإعلان
              </label>
              <select
                value={formData.status}
                onChange={(e) =>
                  handleInputChange(
                    "status",
                    e.target.value as "ACTIVE" | "PAUSED",
                  )
                }
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              >
                <option value="PAUSED">متوقف (سأفعله لاحقاً)</option>
                <option value="ACTIVE">نشط (يبدأ فوراً)</option>
              </select>
            </div>
          </div>
        )}

        {/* Step 2: Media */}
        {currentStep === 2 && (
          <div className="space-y-6">
            <h2 className="text-xl font-semibold text-gray-900">الوسائط</h2>

            {/* Image Upload */}
            {formData.creativeType === "SINGLE_IMAGE" && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  صورة الإعلان *
                </label>

                {formData.imagePreview ? (
                  <div className="relative">
                    <img
                      src={formData.imagePreview}
                      alt="Preview"
                      className="w-full max-w-md h-auto rounded-lg border border-gray-300"
                    />
                    <button
                      onClick={removeImage}
                      className="absolute top-2 right-2 p-2 bg-red-500 text-white rounded-full hover:bg-red-600"
                    >
                      <XMarkIcon className="w-5 h-5" />
                    </button>
                    {formData.uploadedImageHash && (
                      <div className="mt-2 text-sm text-green-600">
                        ✓ تم رفع الصورة بنجاح
                      </div>
                    )}
                  </div>
                ) : (
                  <div
                    onClick={() => fileInputRef.current?.click()}
                    className="border-2 border-dashed border-gray-300 rounded-lg p-12 text-center cursor-pointer hover:border-indigo-500 transition-colors"
                  >
                    <PhotoIcon className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                    <p className="text-gray-600">اضغط لاختيار صورة</p>
                    <p className="text-sm text-gray-500 mt-1">
                      JPG, PNG - الحد الأقصى 10MB
                    </p>
                    <p className="text-sm text-gray-500">
                      الحد الأدنى: 600x315 بكسل
                    </p>
                  </div>
                )}

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageSelect}
                  className="hidden"
                />

                {/* Alternative: Image URL */}
                {!formData.imagePreview && (
                  <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      أو رابط الصورة
                    </label>
                    <input
                      type="url"
                      value={formData.imageUrl || ""}
                      onChange={(e) =>
                        handleInputChange("imageUrl", e.target.value)
                      }
                      placeholder="https://example.com/image.jpg"
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                    />
                  </div>
                )}
              </div>
            )}

            {/* Video Upload */}
            {formData.creativeType === "SINGLE_VIDEO" && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  فيديو الإعلان *
                </label>

                {formData.videoPreview ? (
                  <div className="relative">
                    <video
                      src={formData.videoPreview}
                      controls
                      className="w-full max-w-md h-auto rounded-lg border border-gray-300"
                    />
                    <button
                      onClick={removeVideo}
                      className="absolute top-2 right-2 p-2 bg-red-500 text-white rounded-full hover:bg-red-600"
                    >
                      <XMarkIcon className="w-5 h-5" />
                    </button>
                    {formData.uploadedVideoId && (
                      <div className="mt-2 text-sm text-green-600">
                        ✓ تم رفع الفيديو بنجاح
                      </div>
                    )}
                  </div>
                ) : (
                  <div
                    onClick={() => videoInputRef.current?.click()}
                    className="border-2 border-dashed border-gray-300 rounded-lg p-12 text-center cursor-pointer hover:border-indigo-500 transition-colors"
                  >
                    <VideoCameraIcon className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                    <p className="text-gray-600">اضغط لاختيار فيديو</p>
                    <p className="text-sm text-gray-500 mt-1">
                      MP4, MOV - الحد الأقصى 500MB
                    </p>
                    <p className="text-sm text-gray-500">
                      المدة الموصى بها: 15-60 ثانية
                    </p>
                  </div>
                )}

                <input
                  ref={videoInputRef}
                  type="file"
                  accept="video/*"
                  onChange={handleVideoSelect}
                  className="hidden"
                />

                {/* Alternative: Video URL */}
                {!formData.videoPreview && (
                  <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      أو رابط الفيديو
                    </label>
                    <input
                      type="url"
                      value={formData.videoUrl || ""}
                      onChange={(e) =>
                        handleInputChange("videoUrl", e.target.value)
                      }
                      placeholder="https://example.com/video.mp4"
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                    />
                  </div>
                )}
              </div>
            )}

            {uploading && (
              <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
                <p className="text-sm text-blue-800">
                  جاري الرفع... الرجاء الانتظار
                </p>
              </div>
            )}
          </div>
        )}

        {/* Step 3: Copy & Content */}
        {currentStep === 3 && (
          <div className="space-y-6">
            <h2 className="text-xl font-semibold text-gray-900">
              النص والمحتوى
            </h2>

            {/* Primary Text */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                النص الأساسي (Primary Text) *
              </label>
              <textarea
                value={formData.primaryText}
                onChange={(e) =>
                  handleInputChange("primaryText", e.target.value)
                }
                placeholder="اكتب النص الرئيسي للإعلان هنا..."
                rows={4}
                maxLength={500}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
              <p className="mt-1 text-sm text-gray-500">
                {formData.primaryText.length}/500 حرف
              </p>
            </div>

            {/* Headline */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                العنوان (Headline)
              </label>
              <input
                type="text"
                value={formData.headline || ""}
                onChange={(e) => handleInputChange("headline", e.target.value)}
                placeholder="عنوان جذاب للإعلان"
                maxLength={40}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
              <p className="mt-1 text-sm text-gray-500">
                {formData.headline?.length || 0}/40 حرف
              </p>
            </div>

            {/* Description */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                الوصف (Description)
              </label>
              <textarea
                value={formData.description || ""}
                onChange={(e) =>
                  handleInputChange("description", e.target.value)
                }
                placeholder="وصف مختصر للإعلان"
                rows={3}
                maxLength={125}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
              <p className="mt-1 text-sm text-gray-500">
                {formData.description?.length || 0}/125 حرف
              </p>
            </div>

            {/* Call to Action */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Call to Action
              </label>
              <select
                value={formData.callToAction}
                onChange={(e) =>
                  handleInputChange("callToAction", e.target.value)
                }
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              >
                {CALL_TO_ACTION_TYPES.map((cta) => (
                  <option key={cta.value} value={cta.value}>
                    {cta.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Link URL */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                رابط الإعلان (Destination URL) *
              </label>
              <input
                type="url"
                value={formData.linkUrl || ""}
                onChange={(e) => handleInputChange("linkUrl", e.target.value)}
                placeholder="https://example.com/page"
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
              <p className="mt-1 text-sm text-gray-500">
                الرابط الذي سيتم توجيه المستخدمين إليه عند النقر على الإعلان
              </p>
            </div>
          </div>
        )}

        {/* Step 4: Review */}
        {currentStep === 4 && (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-semibold text-gray-900">
                المراجعة والمعاينة
              </h2>
              <button
                onClick={() => setPreviewMode(!previewMode)}
                className="flex items-center gap-2 px-4 py-2 text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100"
              >
                <EyeIcon className="w-5 h-5" />
                {previewMode ? "إخفاء المعاينة" : "معاينة الإعلان"}
              </button>
            </div>

            {/* Preview */}
            {previewMode && (
              <div className="border border-gray-300 rounded-lg p-6 bg-gray-50">
                <div className="max-w-md mx-auto bg-white rounded-lg shadow-lg overflow-hidden">
                  {/* Media */}
                  {formData.creativeType === "SINGLE_IMAGE" &&
                    formData.imagePreview && (
                      <img
                        src={formData.imagePreview}
                        alt="Ad Preview"
                        className="w-full h-auto"
                      />
                    )}
                  {formData.creativeType === "SINGLE_VIDEO" &&
                    formData.videoPreview && (
                      <video
                        src={formData.videoPreview}
                        controls
                        className="w-full h-auto"
                      />
                    )}

                  {/* Content */}
                  <div className="p-4 space-y-2">
                    {formData.headline && (
                      <h3 className="font-semibold text-gray-900">
                        {formData.headline}
                      </h3>
                    )}
                    <p className="text-gray-700 text-sm">
                      {formData.primaryText}
                    </p>
                    {formData.description && (
                      <p className="text-gray-600 text-xs">
                        {formData.description}
                      </p>
                    )}
                    <button className="mt-2 px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm">
                      {CALL_TO_ACTION_TYPES.find(
                        (cta) => cta.value === formData.callToAction,
                      )?.label || "افعل المزيد"}
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* Summary */}
            <div className="space-y-4">
              <div className="p-6 bg-gray-50 rounded-lg space-y-4">
                <h3 className="font-medium text-gray-900">ملخص الإعلان</h3>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-600">اسم الإعلان</p>
                    <p className="font-semibold text-gray-900">
                      {formData.name}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">نوع الإعلان</p>
                    <p className="font-semibold text-gray-900">
                      {
                        creativeTypes.find(
                          (t) => t.value === formData.creativeType,
                        )?.label
                      }
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Call to Action</p>
                    <p className="font-semibold text-gray-900">
                      {
                        CALL_TO_ACTION_TYPES.find(
                          (cta) => cta.value === formData.callToAction,
                        )?.label
                      }
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">الحالة</p>
                    <p className="font-semibold text-gray-900">
                      {formData.status === "ACTIVE" ? "نشط" : "متوقف"}
                    </p>
                  </div>
                  {formData.linkUrl && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600">رابط الإعلان</p>
                      <p className="font-semibold text-gray-900 text-sm break-all">
                        {formData.linkUrl}
                      </p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Navigation Buttons */}
        <div className="flex items-center justify-between mt-8 pt-6 border-t border-gray-200">
          <button
            onClick={() => navigate(-1)}
            className="px-4 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            إلغاء
          </button>

          <div className="flex gap-3">
            {currentStep > 1 && (
              <button
                onClick={handlePrevious}
                disabled={uploading}
                className="flex items-center gap-2 px-4 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50"
              >
                <ArrowLeftIcon className="w-5 h-5" />
                السابق
              </button>
            )}
            {currentStep < totalSteps ? (
              <button
                onClick={handleNext}
                disabled={uploading}
                className="flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 disabled:opacity-50"
              >
                {uploading ? "جاري الرفع..." : "التالي"}
              </button>
            ) : (
              <button
                onClick={handleSubmit}
                disabled={loading || uploading}
                className="flex items-center gap-2 px-6 py-2 text-white bg-green-600 rounded-lg hover:bg-green-700 disabled:opacity-50"
              >
                {loading ? (
                  <>
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                    جاري الإنشاء...
                  </>
                ) : (
                  <>
                    <CheckCircleIcon className="w-5 h-5" />
                    إنشاء الإعلان
                  </>
                )}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreateAd;

/**
 * Create AdSet Page - Enhanced with Full Targeting Options
 *
 * صفحة إنشاء مجموعة إعلانات جديدة مع كل خيارات الاستهداف المتقدمة
 *
 * الخيارات المدعومة:
 * ═══════════════════════════════════════════════════
 * ✅ Demographics (العمر، الجنس، الحالة الاجتماعية)
 * ✅ Locations (الدول، المدن)
 * ✅ Interests (الاهتمامات مع البحث)
 * ✅ Behaviors (السلوكيات)
 * ✅ Languages (اللغات)
 * ✅ Devices (الأجهزة ونظام التشغيل)
 * ✅ Custom & Lookalike Audiences
 * ✅ Advantage+ Audience
 * ✅ Reach Estimate
 * ═══════════════════════════════════════════════════
 */

import React, { useState, useEffect, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  CheckCircleIcon,
  MagnifyingGlassIcon,
  XMarkIcon,
  UserGroupIcon,
  MapPinIcon,
  HeartIcon,
  DevicePhoneMobileIcon,
  GlobeAltIcon,
  SparklesIcon,
  ChartBarIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  CreateAdSetData,
  FacebookCustomAudience,
  FacebookLookalikeAudience,
} from "../../services/facebookAdsService";

interface TargetingOption {
  id: string;
  name: string;
  audience_size?: number;
}

interface ReachEstimate {
  users: number;
  usersLowerBound: number;
  usersUpperBound: number;
}

const CreateAdSet: React.FC = () => {
  const { campaignId } = useParams<{ campaignId: string }>();
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [customAudiences, setCustomAudiences] = useState<
    FacebookCustomAudience[]
  >([]);
  const [lookalikeAudiences, setLookalikeAudiences] = useState<
    FacebookLookalikeAudience[]
  >([]);
  const [loadingAudiences, setLoadingAudiences] = useState(true);

  // Search & Reach
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<TargetingOption[]>([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const [reachEstimate, setReachEstimate] = useState<ReachEstimate | null>(
    null,
  );
  const [reachLoading, setReachLoading] = useState(false);

  // Active targeting tab
  const [activeTargetingTab, setActiveTargetingTab] = useState<
    "demographics" | "locations" | "interests" | "audiences" | "advanced"
  >("demographics");

  // Extended targeting state
  const [extendedTargeting, setExtendedTargeting] = useState({
    relationshipStatuses: [] as number[],
    locales: [] as number[],
    devicePlatforms: [] as string[],
    interests: [] as TargetingOption[],
    behaviors: [] as TargetingOption[],
    advantageAudience: false,
    targetingExpansion: false,
  });

  const [formData, setFormData] = useState<CreateAdSetData>({
    name: "",
    status: "PAUSED",
    budgetType: "DAILY",
    budgetAmount: 50,
    optimizationGoal: "LINK_CLICKS",
    billingEvent: "IMPRESSIONS",
    targeting: {
      ageMin: 18,
      ageMax: 65,
      genders: [],
      locations: ["EG"],
      interests: [],
      behaviors: [],
      customAudiences: [],
      lookalikeAudiences: [],
    },
  });

  // Static Data
  const countries = [
    { code: "EG", name: "مصر", flag: "🇪🇬" },
    { code: "SA", name: "السعودية", flag: "🇸🇦" },
    { code: "AE", name: "الإمارات", flag: "🇦🇪" },
    { code: "KW", name: "الكويت", flag: "🇰🇼" },
    { code: "QA", name: "قطر", flag: "🇶🇦" },
    { code: "BH", name: "البحرين", flag: "🇧🇭" },
    { code: "OM", name: "عمان", flag: "🇴🇲" },
    { code: "JO", name: "الأردن", flag: "🇯🇴" },
    { code: "LB", name: "لبنان", flag: "🇱🇧" },
    { code: "MA", name: "المغرب", flag: "🇲🇦" },
    { code: "DZ", name: "الجزائر", flag: "🇩🇿" },
    { code: "TN", name: "تونس", flag: "🇹🇳" },
    { code: "IQ", name: "العراق", flag: "🇮🇶" },
    { code: "PS", name: "فلسطين", flag: "🇵🇸" },
    { code: "SY", name: "سوريا", flag: "🇸🇾" },
    { code: "YE", name: "اليمن", flag: "🇾🇪" },
    { code: "SD", name: "السودان", flag: "🇸🇩" },
    { code: "LY", name: "ليبيا", flag: "🇱🇾" },
  ];

  const relationshipOptions = [
    { value: 1, label: "أعزب/عزباء" },
    { value: 2, label: "في علاقة" },
    { value: 3, label: "مخطوب/ة" },
    { value: 4, label: "متزوج/ة" },
    { value: 6, label: "غير محدد" },
  ];

  const languages = [
    { id: 6, name: "العربية" },
    { id: 24, name: "الإنجليزية" },
    { id: 10, name: "الفرنسية" },
    { id: 25, name: "التركية" },
  ];

  const devicePlatforms = [
    { value: "iOS", label: "iOS" },
    { value: "Android", label: "Android" },
  ];

  const interestCategories = [
    { name: "التسوق", query: "shopping" },
    { name: "الموضة", query: "fashion" },
    { name: "التكنولوجيا", query: "technology" },
    { name: "الرياضة", query: "sports" },
    { name: "السفر", query: "travel" },
    { name: "الطعام", query: "food" },
    { name: "الصحة", query: "health" },
    { name: "الأعمال", query: "business" },
  ];

  const totalSteps = 3;

  useEffect(() => {
    if (campaignId) {
      loadAudiences();
    }
  }, [campaignId]);

  const loadAudiences = async () => {
    try {
      setLoadingAudiences(true);
      const [custom, lookalike] = await Promise.all([
        facebookAdsService.getCustomAudiences(),
        facebookAdsService.getLookalikeAudiences(),
      ]);

      setCustomAudiences(custom.filter((a) => a.status === "ACTIVE"));
      setLookalikeAudiences(lookalike.filter((a) => a.status === "ACTIVE"));
    } catch (error: any) {
      console.error("Error loading audiences:", error);
      toast.error("فشل في تحميل الجماهير");
    } finally {
      setLoadingAudiences(false);
    }
  };

  const handleInputChange = (field: keyof CreateAdSetData, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const handleTargetingChange = (field: string, value: any) => {
    setFormData((prev) => ({
      ...prev,
      targeting: {
        ...prev.targeting!,
        [field]: value,
      },
    }));
  };

  const toggleCustomAudience = (audienceId: string) => {
    const current = formData.targeting?.customAudiences || [];
    const updated = current.includes(audienceId)
      ? current.filter((id) => id !== audienceId)
      : [...current, audienceId];
    handleTargetingChange("customAudiences", updated);
  };

  const toggleLookalikeAudience = (audienceId: string) => {
    const current = formData.targeting?.lookalikeAudiences || [];
    const updated = current.includes(audienceId)
      ? current.filter((id) => id !== audienceId)
      : [...current, audienceId];
    handleTargetingChange("lookalikeAudiences", updated);
  };

  // Search for interests
  const handleSearchInterests = useCallback(async (query: string) => {
    if (!query.trim() || query.length < 2) {
      setSearchResults([]);
      return;
    }

    try {
      setSearchLoading(true);
      const results = await facebookAdsService.searchTargetingOptions(
        query,
        "adinterest",
      );
      setSearchResults(results || []);
    } catch (error) {
      console.error("Search error:", error);
      setSearchResults([]);
    } finally {
      setSearchLoading(false);
    }
  }, []);

  // Add interest
  const addInterest = (interest: TargetingOption) => {
    if (!extendedTargeting.interests.find((i) => i.id === interest.id)) {
      setExtendedTargeting((prev) => ({
        ...prev,
        interests: [...prev.interests, interest],
      }));
    }
    setSearchQuery("");
    setSearchResults([]);
  };

  // Remove interest
  const removeInterest = (id: string) => {
    setExtendedTargeting((prev) => ({
      ...prev,
      interests: prev.interests.filter((i) => i.id !== id),
    }));
  };

  // Fetch reach estimate
  const fetchReachEstimate = async () => {
    try {
      setReachLoading(true);
      const result = await facebookAdsService.getReachEstimate(
        formData.targeting || {},
      );
      if (result) {
        setReachEstimate(result);
      }
    } catch (error) {
      console.error("Reach estimate error:", error);
    } finally {
      setReachLoading(false);
    }
  };

  const validateStep = (step: number): boolean => {
    switch (step) {
      case 1:
        if (!formData.name.trim()) {
          toast.error("يرجى إدخال اسم مجموعة الإعلانات");
          return false;
        }
        return true;
      case 2:
        if (!formData.budgetAmount || formData.budgetAmount <= 0) {
          toast.error("يرجى إدخال ميزانية صحيحة");
          return false;
        }
        return true;
      case 3:
        return true; // Review step
      default:
        return true;
    }
  };

  const handleNext = () => {
    if (validateStep(currentStep)) {
      if (currentStep < totalSteps) {
        setCurrentStep(currentStep + 1);
      }
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = async () => {
    if (!validateStep(currentStep) || !campaignId) return;

    try {
      setLoading(true);
      await facebookAdsService.createAdSet(campaignId, formData);
      toast.success("تم إنشاء مجموعة الإعلانات بنجاح");
      navigate(`/advertising/facebook-ads/campaigns/${campaignId}`);
    } catch (error: any) {
      console.error("Error creating ad set:", error);
      toast.error(
        error?.response?.data?.error || "فشل في إنشاء مجموعة الإعلانات",
      );
    } finally {
      setLoading(false);
    }
  };

  if (!campaignId) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-600">معرف الحملة غير موجود</p>
      </div>
    );
  }

  return (
    <div className="w-full space-y-6">
      {/* Header */}
      <div>
        <button
          onClick={() =>
            navigate(`/advertising/facebook-ads/campaigns/${campaignId}`)
          }
          className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          رجوع
        </button>
        <h1 className="text-3xl font-bold text-gray-900">
          إنشاء مجموعة إعلانات جديدة
        </h1>
        <p className="mt-2 text-sm text-gray-600">
          اتبع الخطوات لإنشاء مجموعة إعلانات جديدة
        </p>
      </div>

      {/* Progress Steps */}
      <div className="bg-white p-6 rounded-lg shadow">
        <div className="flex items-center justify-between">
          {[1, 2, 3].map((step) => (
            <React.Fragment key={step}>
              <div className="flex flex-col items-center flex-1">
                <div
                  className={`w-10 h-10 rounded-full flex items-center justify-center ${
                    step < currentStep
                      ? "bg-green-500 text-white"
                      : step === currentStep
                        ? "bg-indigo-600 text-white"
                        : "bg-gray-200 text-gray-600"
                  }`}
                >
                  {step < currentStep ? (
                    <CheckCircleIcon className="w-6 h-6" />
                  ) : (
                    <span>{step}</span>
                  )}
                </div>
                <p
                  className={`mt-2 text-sm font-medium ${
                    step <= currentStep ? "text-gray-900" : "text-gray-500"
                  }`}
                >
                  {step === 1 && "المعلومات الأساسية"}
                  {step === 2 && "الاستهداف"}
                  {step === 3 && "المراجعة"}
                </p>
              </div>
              {step < 3 && (
                <div
                  className={`flex-1 h-1 mx-4 ${
                    step < currentStep ? "bg-green-500" : "bg-gray-200"
                  }`}
                />
              )}
            </React.Fragment>
          ))}
        </div>
      </div>

      {/* Form Content */}
      <div className="bg-white rounded-lg shadow p-6">
        {/* Step 1: Basic Info */}
        {currentStep === 1 && (
          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                اسم مجموعة الإعلانات *
              </label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => handleInputChange("name", e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                placeholder="مثال: مجموعة إعلانات - رجال 25-45"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  نوع الميزانية *
                </label>
                <select
                  value={formData.budgetType}
                  onChange={(e) =>
                    handleInputChange("budgetType", e.target.value)
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                >
                  <option value="DAILY">يومية</option>
                  <option value="LIFETIME">إجمالية</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  مبلغ الميزانية *
                </label>
                <input
                  type="number"
                  value={formData.budgetAmount}
                  onChange={(e) =>
                    handleInputChange(
                      "budgetAmount",
                      parseFloat(e.target.value),
                    )
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                  min={1}
                  step={0.01}
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  هدف التحسين
                </label>
                <select
                  value={formData.optimizationGoal}
                  onChange={(e) =>
                    handleInputChange("optimizationGoal", e.target.value)
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                >
                  <option value="LINK_CLICKS">نقرات الروابط</option>
                  <option value="OFFSITE_CONVERSIONS">التحويلات</option>
                  <option value="IMPRESSIONS">المشاهدات</option>
                  <option value="REACH">الوصول</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  حدث الفوترة
                </label>
                <select
                  value={formData.billingEvent}
                  onChange={(e) =>
                    handleInputChange("billingEvent", e.target.value)
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                >
                  <option value="IMPRESSIONS">المشاهدات</option>
                  <option value="LINK_CLICKS">النقرات</option>
                </select>
              </div>
            </div>
          </div>
        )}

        {/* Step 2: Targeting - Enhanced */}
        {currentStep === 2 && (
          <div className="space-y-6">
            {/* Targeting Tabs */}
            <div className="flex flex-wrap gap-2 border-b pb-4">
              {[
                {
                  id: "demographics",
                  label: "الديموغرافيا",
                  icon: UserGroupIcon,
                },
                { id: "locations", label: "المواقع", icon: MapPinIcon },
                { id: "interests", label: "الاهتمامات", icon: HeartIcon },
                { id: "audiences", label: "الجماهير", icon: ChartBarIcon },
                { id: "advanced", label: "متقدم", icon: SparklesIcon },
              ].map((tab) => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTargetingTab(tab.id as any)}
                    className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                      activeTargetingTab === tab.id
                        ? "bg-indigo-100 text-indigo-700"
                        : "text-gray-600 hover:bg-gray-100"
                    }`}
                  >
                    <Icon className="w-4 h-4" />
                    {tab.label}
                  </button>
                );
              })}
            </div>

            {/* Reach Estimate Card */}
            <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-lg p-4 border border-indigo-100">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">حجم الجمهور المقدر</p>
                  <p className="text-2xl font-bold text-indigo-600">
                    {reachLoading
                      ? "..."
                      : reachEstimate
                        ? `${(reachEstimate.users / 1000000).toFixed(1)}M`
                        : "---"}
                  </p>
                  {reachEstimate && (
                    <p className="text-xs text-gray-500">
                      {(reachEstimate.usersLowerBound / 1000).toFixed(0)}K -{" "}
                      {(reachEstimate.usersUpperBound / 1000000).toFixed(1)}M
                    </p>
                  )}
                </div>
                <button
                  onClick={fetchReachEstimate}
                  disabled={reachLoading}
                  className="p-2 text-indigo-600 hover:bg-indigo-100 rounded-lg"
                >
                  <ChartBarIcon
                    className={`w-5 h-5 ${reachLoading ? "animate-pulse" : ""}`}
                  />
                </button>
              </div>
            </div>

            {/* Demographics Tab */}
            {activeTargetingTab === "demographics" && (
              <div className="space-y-6">
                {/* Age Range */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    الفئة العمرية
                  </label>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs text-gray-600 mb-1">
                        من
                      </label>
                      <input
                        type="number"
                        value={formData.targeting?.ageMin || 18}
                        onChange={(e) =>
                          handleTargetingChange(
                            "ageMin",
                            parseInt(e.target.value),
                          )
                        }
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                        min={13}
                        max={65}
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-gray-600 mb-1">
                        إلى
                      </label>
                      <input
                        type="number"
                        value={formData.targeting?.ageMax || 65}
                        onChange={(e) =>
                          handleTargetingChange(
                            "ageMax",
                            parseInt(e.target.value),
                          )
                        }
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                        min={13}
                        max={65}
                      />
                    </div>
                  </div>
                </div>

                {/* Gender */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    الجنس
                  </label>
                  <div className="flex gap-3">
                    {[
                      { value: "male", label: "ذكور 👨" },
                      { value: "female", label: "إناث 👩" },
                    ].map((gender) => (
                      <button
                        key={gender.value}
                        type="button"
                        onClick={() => {
                          const current = formData.targeting?.genders || [];
                          const updated = current.includes(gender.value)
                            ? current.filter((g) => g !== gender.value)
                            : [...current, gender.value];
                          handleTargetingChange("genders", updated);
                        }}
                        className={`flex-1 py-3 px-4 rounded-lg border-2 transition-colors ${
                          formData.targeting?.genders?.includes(gender.value)
                            ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                            : "border-gray-200 hover:border-gray-300"
                        }`}
                      >
                        {gender.label}
                      </button>
                    ))}
                  </div>
                  <p className="mt-2 text-sm text-gray-500">
                    {!formData.targeting?.genders?.length
                      ? "الكل (افتراضي)"
                      : `محدد: ${formData.targeting.genders.length}`}
                  </p>
                </div>

                {/* Relationship Status */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    الحالة الاجتماعية
                  </label>
                  <div className="flex flex-wrap gap-2">
                    {relationshipOptions.map((status) => (
                      <button
                        key={status.value}
                        type="button"
                        onClick={() => {
                          const current =
                            extendedTargeting.relationshipStatuses;
                          const updated = current.includes(status.value)
                            ? current.filter((s) => s !== status.value)
                            : [...current, status.value];
                          setExtendedTargeting((prev) => ({
                            ...prev,
                            relationshipStatuses: updated,
                          }));
                        }}
                        className={`px-4 py-2 rounded-full border text-sm transition-colors ${
                          extendedTargeting.relationshipStatuses.includes(
                            status.value,
                          )
                            ? "border-indigo-500 bg-indigo-500 text-white"
                            : "border-gray-200 hover:border-gray-300"
                        }`}
                      >
                        {status.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Locations Tab */}
            {activeTargetingTab === "locations" && (
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    الدول *
                  </label>
                  <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-2">
                    {countries.map((country) => (
                      <button
                        key={country.code}
                        type="button"
                        onClick={() => {
                          const current = formData.targeting?.locations || [];
                          const updated = current.includes(country.code)
                            ? current.filter((c) => c !== country.code)
                            : [...current, country.code];
                          handleTargetingChange("locations", updated);
                        }}
                        className={`py-2 px-3 rounded-lg border text-sm transition-colors ${
                          formData.targeting?.locations?.includes(country.code)
                            ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                            : "border-gray-200 hover:border-gray-300"
                        }`}
                      >
                        <span className="ml-1">{country.flag}</span>
                        {country.name}
                      </button>
                    ))}
                  </div>
                  <p className="mt-2 text-sm text-gray-500">
                    محدد: {formData.targeting?.locations?.length || 0} دولة
                  </p>
                </div>
              </div>
            )}

            {/* Interests Tab */}
            {activeTargetingTab === "interests" && (
              <div className="space-y-6">
                {/* Search */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    البحث عن اهتمامات
                  </label>
                  <div className="relative">
                    <MagnifyingGlassIcon className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                    <input
                      type="text"
                      value={searchQuery}
                      onChange={(e) => {
                        setSearchQuery(e.target.value);
                        handleSearchInterests(e.target.value);
                      }}
                      placeholder="ابحث عن اهتمام (مثال: تسوق، موضة، تقنية...)"
                      className="w-full pr-10 pl-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500"
                    />
                    {searchLoading && (
                      <div className="absolute left-3 top-1/2 -translate-y-1/2">
                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-indigo-600"></div>
                      </div>
                    )}
                  </div>

                  {/* Search Results */}
                  {searchResults.length > 0 && (
                    <div className="mt-2 border rounded-lg max-h-48 overflow-y-auto">
                      {searchResults.map((result) => (
                        <button
                          key={result.id}
                          type="button"
                          onClick={() => addInterest(result)}
                          className="w-full px-4 py-2 text-right hover:bg-gray-50 border-b last:border-b-0 flex items-center justify-between"
                        >
                          <span className="text-sm">{result.name}</span>
                          {result.audience_size && (
                            <span className="text-xs text-gray-500">
                              {(result.audience_size / 1000000).toFixed(1)}M
                            </span>
                          )}
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                {/* Selected Interests */}
                {extendedTargeting.interests.length > 0 && (
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      الاهتمامات المحددة ({extendedTargeting.interests.length})
                    </label>
                    <div className="flex flex-wrap gap-2">
                      {extendedTargeting.interests.map((interest) => (
                        <span
                          key={interest.id}
                          className="inline-flex items-center gap-1 px-3 py-1.5 bg-indigo-100 text-indigo-700 rounded-full text-sm"
                        >
                          {interest.name}
                          <button
                            type="button"
                            onClick={() => removeInterest(interest.id)}
                            className="p-0.5 hover:bg-indigo-200 rounded-full"
                          >
                            <XMarkIcon className="w-3 h-3" />
                          </button>
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {/* Quick Categories */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    فئات سريعة
                  </label>
                  <div className="flex flex-wrap gap-2">
                    {interestCategories.map((cat) => (
                      <button
                        key={cat.query}
                        type="button"
                        onClick={() => {
                          setSearchQuery(cat.query);
                          handleSearchInterests(cat.query);
                        }}
                        className="px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm"
                      >
                        {cat.name}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Audiences Tab */}
            {activeTargetingTab === "audiences" && (
              <div className="space-y-6">
                {loadingAudiences ? (
                  <div className="text-center py-8">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 mx-auto"></div>
                    <p className="mt-2 text-sm text-gray-500">
                      جاري تحميل الجماهير...
                    </p>
                  </div>
                ) : (
                  <>
                    {/* Custom Audiences */}
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-3">
                        الجماهير المخصصة
                      </label>
                      {customAudiences.length === 0 ? (
                        <p className="text-sm text-gray-500 bg-gray-50 p-4 rounded-lg">
                          لا توجد جماهير مخصصة متاحة
                        </p>
                      ) : (
                        <div className="space-y-2 max-h-48 overflow-y-auto border border-gray-200 rounded-lg p-3">
                          {customAudiences.map((audience) => (
                            <label
                              key={audience.id}
                              className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded cursor-pointer"
                            >
                              <input
                                type="checkbox"
                                checked={
                                  formData.targeting?.customAudiences?.includes(
                                    audience.id,
                                  ) || false
                                }
                                onChange={() =>
                                  toggleCustomAudience(audience.id)
                                }
                                className="w-4 h-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500"
                              />
                              <div className="flex-1">
                                <p className="text-sm font-medium text-gray-900">
                                  {audience.name}
                                </p>
                                <p className="text-xs text-gray-500">
                                  {audience.audienceSize?.toLocaleString() || 0}{" "}
                                  شخص
                                </p>
                              </div>
                            </label>
                          ))}
                        </div>
                      )}
                    </div>

                    {/* Lookalike Audiences */}
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-3">
                        الجماهير المشابهة
                      </label>
                      {lookalikeAudiences.length === 0 ? (
                        <p className="text-sm text-gray-500 bg-gray-50 p-4 rounded-lg">
                          لا توجد جماهير مشابهة متاحة
                        </p>
                      ) : (
                        <div className="space-y-2 max-h-48 overflow-y-auto border border-gray-200 rounded-lg p-3">
                          {lookalikeAudiences.map((audience) => (
                            <label
                              key={audience.id}
                              className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded cursor-pointer"
                            >
                              <input
                                type="checkbox"
                                checked={
                                  formData.targeting?.lookalikeAudiences?.includes(
                                    audience.id,
                                  ) || false
                                }
                                onChange={() =>
                                  toggleLookalikeAudience(audience.id)
                                }
                                className="w-4 h-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500"
                              />
                              <div className="flex-1">
                                <p className="text-sm font-medium text-gray-900">
                                  {audience.name}
                                </p>
                                <p className="text-xs text-gray-500">
                                  {audience.audienceSize?.toLocaleString() || 0}{" "}
                                  شخص | {audience.ratio}% شبه
                                </p>
                              </div>
                            </label>
                          ))}
                        </div>
                      )}
                    </div>
                  </>
                )}
              </div>
            )}

            {/* Advanced Tab */}
            {activeTargetingTab === "advanced" && (
              <div className="space-y-6">
                {/* Languages */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    <GlobeAltIcon className="w-4 h-4 inline ml-1" />
                    اللغات
                  </label>
                  <div className="flex flex-wrap gap-2">
                    {languages.map((lang) => (
                      <button
                        key={lang.id}
                        type="button"
                        onClick={() => {
                          const current = extendedTargeting.locales;
                          const updated = current.includes(lang.id)
                            ? current.filter((l) => l !== lang.id)
                            : [...current, lang.id];
                          setExtendedTargeting((prev) => ({
                            ...prev,
                            locales: updated,
                          }));
                        }}
                        className={`px-4 py-2 rounded-lg border transition-colors ${
                          extendedTargeting.locales.includes(lang.id)
                            ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                            : "border-gray-200 hover:border-gray-300"
                        }`}
                      >
                        {lang.name}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Devices */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    <DevicePhoneMobileIcon className="w-4 h-4 inline ml-1" />
                    نظام التشغيل
                  </label>
                  <div className="flex gap-3">
                    {devicePlatforms.map((platform) => (
                      <button
                        key={platform.value}
                        type="button"
                        onClick={() => {
                          const current = extendedTargeting.devicePlatforms;
                          const updated = current.includes(platform.value)
                            ? current.filter((p) => p !== platform.value)
                            : [...current, platform.value];
                          setExtendedTargeting((prev) => ({
                            ...prev,
                            devicePlatforms: updated,
                          }));
                        }}
                        className={`flex-1 py-3 px-4 rounded-lg border-2 transition-colors ${
                          extendedTargeting.devicePlatforms.includes(
                            platform.value,
                          )
                            ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                            : "border-gray-200 hover:border-gray-300"
                        }`}
                      >
                        {platform.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Advantage+ Audience */}
                <div className="p-4 bg-gradient-to-r from-purple-50 to-indigo-50 rounded-xl border border-purple-200">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={extendedTargeting.advantageAudience}
                      onChange={(e) =>
                        setExtendedTargeting((prev) => ({
                          ...prev,
                          advantageAudience: e.target.checked,
                        }))
                      }
                      className="w-5 h-5 text-purple-600 rounded focus:ring-purple-500"
                    />
                    <div>
                      <span className="font-medium text-gray-900 flex items-center gap-2">
                        <SparklesIcon className="w-4 h-4 text-purple-600" />
                        Advantage+ Audience
                      </span>
                      <p className="text-sm text-gray-600 mt-1">
                        السماح لـ Facebook بتوسيع الجمهور تلقائياً للوصول لأشخاص
                        أكثر احتمالاً للتحويل
                      </p>
                    </div>
                  </label>
                </div>

                {/* Targeting Expansion */}
                <div className="p-4 bg-blue-50 rounded-xl border border-blue-200">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={extendedTargeting.targetingExpansion}
                      onChange={(e) =>
                        setExtendedTargeting((prev) => ({
                          ...prev,
                          targetingExpansion: e.target.checked,
                        }))
                      }
                      className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
                    />
                    <div>
                      <span className="font-medium text-gray-900">
                        توسيع الاستهداف التفصيلي
                      </span>
                      <p className="text-sm text-gray-600 mt-1">
                        الوصول لأشخاص إضافيين خارج الاستهداف المحدد عندما يكون
                        ذلك مفيداً
                      </p>
                    </div>
                  </label>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Step 3: Review */}
        {currentStep === 3 && (
          <div className="space-y-6">
            <div className="bg-gray-50 rounded-lg p-6 space-y-4">
              <h3 className="font-medium text-gray-900">مراجعة المعلومات</h3>

              <div>
                <span className="text-sm text-gray-500">الاسم:</span>
                <p className="font-medium">{formData.name}</p>
              </div>

              <div>
                <span className="text-sm text-gray-500">الميزانية:</span>
                <p className="font-medium">
                  {formData.budgetAmount.toLocaleString()} EGP (
                  {formData.budgetType === "DAILY" ? "يومية" : "إجمالية"})
                </p>
              </div>

              <div>
                <span className="text-sm text-gray-500">الفئة العمرية:</span>
                <p className="font-medium">
                  {formData.targeting?.ageMin || 18} -{" "}
                  {formData.targeting?.ageMax || 65}
                </p>
              </div>

              {formData.targeting?.customAudiences &&
                formData.targeting.customAudiences.length > 0 && (
                  <div>
                    <span className="text-sm text-gray-500">
                      الجماهير المخصصة:
                    </span>
                    <p className="font-medium">
                      {formData.targeting.customAudiences.length} جمهور
                    </p>
                  </div>
                )}

              {formData.targeting?.lookalikeAudiences &&
                formData.targeting.lookalikeAudiences.length > 0 && (
                  <div>
                    <span className="text-sm text-gray-500">
                      الجماهير المشابهة:
                    </span>
                    <p className="font-medium">
                      {formData.targeting.lookalikeAudiences.length} جمهور
                    </p>
                  </div>
                )}
            </div>
          </div>
        )}

        {/* Navigation Buttons */}
        <div className="flex items-center justify-between mt-8 pt-6 border-t border-gray-200">
          <button
            onClick={handlePrevious}
            disabled={currentStep === 1}
            className="px-6 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            السابق
          </button>

          {currentStep < totalSteps ? (
            <button
              onClick={handleNext}
              className="px-6 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700"
            >
              التالي
            </button>
          ) : (
            <button
              onClick={handleSubmit}
              disabled={loading}
              className="px-6 py-2 text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 disabled:opacity-50"
            >
              {loading ? "جاري الإنشاء..." : "إنشاء مجموعة الإعلانات"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

