/**
 * Custom Audience Details Page
 *
 * صفحة تفاصيل الجمهور المخصص
 */

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  TrashIcon,
  UserGroupIcon,
  CalendarIcon,
  TagIcon,
  EyeIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookCustomAudience,
} from "../../services/facebookAdsService";

const CustomAudienceDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [audience, setAudience] = useState<FacebookCustomAudience | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (id) {
      loadAudience();
    }
  }, [id]);

  const loadAudience = async () => {
    if (!id) return;

    try {
      setLoading(true);
      const data = await facebookAdsService.getCustomAudience(id);
      setAudience(data);
    } catch (error: any) {
      console.error("Error loading audience:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل الجمهور");
      navigate("/advertising/facebook-ads/audiences");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!id) return;
    if (
      !confirm(
        "هل أنت متأكد من حذف هذا الجمهور؟ لا يمكن التراجع عن هذا الإجراء.",
      )
    )
      return;

    try {
      await facebookAdsService.deleteCustomAudience(id);
      toast.success("تم حذف الجمهور بنجاح");
      navigate("/advertising/facebook-ads/audiences");
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في حذف الجمهور");
    }
  };

  const getAudienceTypeLabel = (type: string) => {
    const types: Record<string, string> = {
      CUSTOMER_LIST: "قائمة عملاء",
      WEBSITE: "زوار الموقع",
      ENGAGEMENT: "المتفاعلين",
      APP_ACTIVITY: "نشاط التطبيق",
      VIDEO_VIEW: "مشاهدي الفيديو",
    };
    return types[type] || type;
  };

  const getEventTypeLabel = (eventType?: string) => {
    if (!eventType) return "-";
    const types: Record<string, string> = {
      ALL_VISITORS: "جميع الزوار",
      PURCHASE: "المشترون",
      ADD_TO_CART: "أضافوا للعربة",
      VIEW_CONTENT: "شاهدوا المحتوى",
    };
    return types[eventType] || eventType;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 mx-auto"></div>
          <p className="mt-2 text-gray-600">جاري التحميل...</p>
        </div>
      </div>
    );
  }

  if (!audience) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-600">لم يتم العثور على الجمهور</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <button
            onClick={() => navigate("/advertising/facebook-ads/audiences")}
            className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
          >
            <ArrowLeftIcon className="w-5 h-5" />
            رجوع
          </button>
          <h1 className="text-3xl font-bold text-gray-900">{audience.name}</h1>
          {audience.description && (
            <p className="mt-2 text-sm text-gray-600">{audience.description}</p>
          )}
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleDelete}
            className="flex items-center gap-2 px-4 py-2 text-red-600 bg-white border border-red-300 rounded-lg hover:bg-red-50"
          >
            <TrashIcon className="w-5 h-5" />
            حذف
          </button>
        </div>
      </div>

      {/* Info Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Status Card */}
        <div className="bg-white p-6 rounded-lg shadow">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600">الحالة</p>
              <p className="mt-1">
                <span
                  className={`inline-block px-3 py-1 text-sm font-medium rounded-full ${
                    audience.status === "ACTIVE"
                      ? "bg-green-100 text-green-800"
                      : "bg-gray-100 text-gray-800"
                  }`}
                >
                  {audience.status === "ACTIVE" ? "نشط" : "محذوف"}
                </span>
              </p>
            </div>
            <UserGroupIcon className="w-8 h-8 text-gray-400" />
          </div>
        </div>

        {/* Audience Size Card */}
        <div className="bg-white p-6 rounded-lg shadow">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600">حجم الجمهور</p>
              <p className="mt-1 text-2xl font-bold text-gray-900">
                {audience.audienceSize
                  ? audience.audienceSize.toLocaleString()
                  : "-"}
              </p>
            </div>
            <EyeIcon className="w-8 h-8 text-gray-400" />
          </div>
        </div>

        {/* Type Card */}
        <div className="bg-white p-6 rounded-lg shadow">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600">نوع الجمهور</p>
              <p className="mt-1 font-medium text-gray-900">
                {getAudienceTypeLabel(audience.audienceType)}
              </p>
            </div>
            <TagIcon className="w-8 h-8 text-gray-400" />
          </div>
        </div>
      </div>

      {/* Details */}
      <div className="bg-white rounded-lg shadow p-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-6">التفاصيل</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <p className="text-sm text-gray-600">معرف الجمهور على Facebook</p>
            <p className="mt-1 font-mono text-sm text-gray-900">
              {audience.facebookAudienceId || "-"}
            </p>
          </div>

          <div>
            <p className="text-sm text-gray-600">تاريخ الإنشاء</p>
            <p className="mt-1 text-gray-900">
              {new Date(audience.createdAt).toLocaleDateString("ar-EG", {
                year: "numeric",
                month: "long",
                day: "numeric",
              })}
            </p>
          </div>

          {audience.audienceType === "WEBSITE" && (
            <>
              <div>
                <p className="text-sm text-gray-600">Pixel ID</p>
                <p className="mt-1 font-mono text-sm text-gray-900">
                  {audience.pixelId || "-"}
                </p>
              </div>

              <div>
                <p className="text-sm text-gray-600">نوع الحدث</p>
                <p className="mt-1 text-gray-900">
                  {getEventTypeLabel(audience.eventType)}
                </p>
              </div>

              {audience.retentionDays && (
                <div>
                  <p className="text-sm text-gray-600">مدة الاحتفاظ</p>
                  <p className="mt-1 text-gray-900">
                    {audience.retentionDays} يوم
                  </p>
                </div>
              )}
            </>
          )}

          {audience.audienceType === "CUSTOMER_LIST" &&
            audience.customerListId && (
              <div>
                <p className="text-sm text-gray-600">قائمة العملاء</p>
                <p className="mt-1 text-gray-900">
                  ID: {audience.customerListId}
                </p>
              </div>
            )}

          {audience.matchRate && (
            <div>
              <p className="text-sm text-gray-600">نسبة المطابقة</p>
              <p className="mt-1 text-gray-900">
                {audience.matchRate.toFixed(1)}%
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Lookalike Audiences */}
      {audience.lookalikeAudiences &&
        audience.lookalikeAudiences.length > 0 && (
          <div className="bg-white rounded-lg shadow p-6">
            <h2 className="text-lg font-semibold text-gray-900 mb-4">
              الجماهير المشابهة
            </h2>
            <div className="space-y-3">
              {audience.lookalikeAudiences.map((lookalike) => (
                <div
                  key={lookalike.id}
                  className="p-4 border border-gray-200 rounded-lg hover:bg-gray-50"
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-medium text-gray-900">
                        {lookalike.name}
                      </p>
                      <p className="text-sm text-gray-500 mt-1">
                        نسبة الشبه: {lookalike.ratio}% | الدولة:{" "}
                        {lookalike.country}
                      </p>
                    </div>
                    <span
                      className={`px-3 py-1 text-xs font-medium rounded-full ${
                        lookalike.status === "ACTIVE"
                          ? "bg-green-100 text-green-800"
                          : "bg-gray-100 text-gray-800"
                      }`}
                    >
                      {lookalike.status === "ACTIVE" ? "نشط" : "محذوف"}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
    </div>
  );
};

export default CustomAudienceDetails;

/**
 * 🎨 Dynamic Creative Optimization (DCO)
 *
 * صفحة تحسين الإعلانات الديناميكية - تجمع عناصر إبداعية متعددة وتختبرها تلقائياً
 */

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  Sparkles,
  Image,
  Video,
  Type,
  Link,
  Plus,
  Trash2,
  Loader2,
  CheckCircle,
  Zap,
  BarChart3,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

const DynamicCreativeOptimization: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<
    "images" | "videos" | "titles" | "bodies" | "ctas"
  >("images");

  const [formData, setFormData] = useState({
    pageId: "",
    name: "",
    images: [""],
    videos: [""],
    titles: [""],
    bodies: [""],
    descriptions: [""],
    callToActions: ["LEARN_MORE"],
    linkUrls: [""],
  });

  const ctaOptions = [
    { value: "LEARN_MORE", label: "اعرف المزيد" },
    { value: "SHOP_NOW", label: "تسوق الآن" },
    { value: "SIGN_UP", label: "سجل الآن" },
    { value: "SUBSCRIBE", label: "اشترك" },
    { value: "CONTACT_US", label: "تواصل معنا" },
    { value: "GET_OFFER", label: "احصل على العرض" },
    { value: "GET_QUOTE", label: "احصل على عرض سعر" },
    { value: "BOOK_NOW", label: "احجز الآن" },
    { value: "DOWNLOAD", label: "تحميل" },
    { value: "WATCH_MORE", label: "شاهد المزيد" },
  ];

  const addItem = (field: keyof typeof formData) => {
    if (Array.isArray(formData[field])) {
      const arr = formData[field] as string[];
      if (arr.length < 10) {
        setFormData((prev) => ({
          ...prev,
          [field]: [...arr, ""],
        }));
      }
    }
  };

  const removeItem = (field: keyof typeof formData, index: number) => {
    if (Array.isArray(formData[field])) {
      const arr = formData[field] as string[];
      if (arr.length > 1) {
        setFormData((prev) => ({
          ...prev,
          [field]: arr.filter((_, i) => i !== index),
        }));
      }
    }
  };

  const updateItem = (
    field: keyof typeof formData,
    index: number,
    value: string,
  ) => {
    if (Array.isArray(formData[field])) {
      const arr = [...(formData[field] as string[])];
      arr[index] = value;
      setFormData((prev) => ({
        ...prev,
        [field]: arr,
      }));
    }
  };

  const handleSubmit = async () => {
    if (!formData.pageId) {
      toast.error("يرجى إدخال معرف الصفحة");
      return;
    }

    const filledImages = formData.images.filter((i) => i.trim());
    const filledVideos = formData.videos.filter((v) => v.trim());
    const filledTitles = formData.titles.filter((t) => t.trim());
    const filledBodies = formData.bodies.filter((b) => b.trim());

    if (filledImages.length === 0 && filledVideos.length === 0) {
      toast.error("يرجى إضافة صورة أو فيديو واحد على الأقل");
      return;
    }

    if (filledTitles.length === 0) {
      toast.error("يرجى إضافة عنوان واحد على الأقل");
      return;
    }

    if (filledBodies.length === 0) {
      toast.error("يرجى إضافة نص واحد على الأقل");
      return;
    }

    try {
      setLoading(true);
      const dcoPayload: any = {
        pageId: formData.pageId,
        name:
          formData.name || `DCO - ${new Date().toLocaleDateString("ar-EG")}`,
        titles: filledTitles,
        bodies: filledBodies,
        descriptions: formData.descriptions.filter((d) => d.trim()),
        callToActions: formData.callToActions,
        linkUrls: formData.linkUrls.filter((l) => l.trim()),
      };
      if (filledImages.length > 0) dcoPayload.images = filledImages;
      if (filledVideos.length > 0) dcoPayload.videos = filledVideos;
      await facebookAdsService.createDynamicCreative(dcoPayload);

      toast.success("تم إنشاء الإعلان الديناميكي بنجاح! 🎉");
      navigate("/advertising/facebook-ads");
    } catch (error: any) {
      console.error("Error creating DCO:", error);
      toast.error(error?.response?.data?.error || "فشل في إنشاء الإعلان");
    } finally {
      setLoading(false);
    }
  };

  const getTotalCombinations = () => {
    const images = formData.images.filter((i) => i.trim()).length || 1;
    const videos = formData.videos.filter((v) => v.trim()).length || 0;
    const titles = formData.titles.filter((t) => t.trim()).length || 1;
    const bodies = formData.bodies.filter((b) => b.trim()).length || 1;
    const ctas = formData.callToActions.length || 1;

    return (images + videos) * titles * bodies * ctas;
  };

  const tabs = [
    {
      id: "images",
      label: "الصور",
      icon: Image,
      count: formData.images.filter((i) => i.trim()).length,
    },
    {
      id: "videos",
      label: "الفيديوهات",
      icon: Video,
      count: formData.videos.filter((v) => v.trim()).length,
    },
    {
      id: "titles",
      label: "العناوين",
      icon: Type,
      count: formData.titles.filter((t) => t.trim()).length,
    },
    {
      id: "bodies",
      label: "النصوص",
      icon: Type,
      count: formData.bodies.filter((b) => b.trim()).length,
    },
    {
      id: "ctas",
      label: "أزرار الإجراء",
      icon: Zap,
      count: formData.callToActions.length,
    },
  ];

  return (
    <div
      className="p-6 space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <Sparkles className="w-7 h-7 text-indigo-600 dark:text-indigo-400" />
            Dynamic Creative Optimization
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            تحسين الإعلانات الديناميكية - اختبار عناصر متعددة تلقائياً
          </p>
        </div>
      </div>

      {/* Stats Card */}
      <div className="bg-gradient-to-r from-purple-500 to-indigo-600 rounded-xl p-6 text-white">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-purple-100">إجمالي التركيبات الممكنة</p>
            <p className="text-4xl font-bold mt-1">{getTotalCombinations()}</p>
            <p className="text-purple-200 text-sm mt-2">
              سيتم اختبارها تلقائياً لتحقيق أفضل أداء
            </p>
          </div>
          <BarChart3 className="w-16 h-16 text-purple-200" />
        </div>
      </div>

      {/* Main Form */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm dark:shadow-gray-900/20 border border-gray-200 dark:border-gray-700 overflow-hidden">
        {/* Basic Info */}
        <div className="p-6 border-b border-gray-200 dark:border-gray-600">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            معلومات أساسية
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                معرف الصفحة *
              </label>
              <input
                type="text"
                value={formData.pageId}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, pageId: e.target.value }))
                }
                placeholder="أدخل معرف صفحة Facebook"
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                اسم الإعلان
              </label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, name: e.target.value }))
                }
                placeholder="اختياري"
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
              />
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="border-b border-gray-200 dark:border-gray-600">
          <div className="flex overflow-x-auto">
            {tabs.map((tab) => {
              const Icon = tab.icon;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex items-center gap-2 px-6 py-4 font-medium whitespace-nowrap transition-colors ${
                    activeTab === tab.id
                      ? "text-indigo-600 dark:text-indigo-400 border-b-2 border-indigo-600 dark:border-indigo-400 bg-indigo-50 dark:bg-indigo-900/20"
                      : "text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white"
                  }`}
                >
                  <Icon className="w-5 h-5" />
                  {tab.label}
                  <span
                    className={`text-xs px-2 py-1 rounded-full ${
                      activeTab === tab.id
                        ? "bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400"
                        : "bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400"
                    }`}
                  >
                    {tab.count}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Tab Content */}
        <div className="p-6">
          {/* Images Tab */}
          {activeTab === "images" && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <p className="text-gray-600">أضف حتى 10 صور مختلفة للاختبار</p>
                <button
                  onClick={() => addItem("images")}
                  disabled={formData.images.length >= 10}
                  className="flex items-center gap-1 text-purple-600 hover:text-purple-700 disabled:opacity-50"
                >
                  <Plus className="w-4 h-4" />
                  إضافة صورة
                </button>
              </div>
              {formData.images.map((url, index) => (
                <div key={index} className="flex gap-2">
                  <input
                    type="url"
                    value={url}
                    onChange={(e) =>
                      updateItem("images", index, e.target.value)
                    }
                    placeholder="رابط الصورة"
                    className="flex-1 px-4 py-2 border rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                  {formData.images.length > 1 && (
                    <button
                      onClick={() => removeItem("images", index)}
                      className="p-2 text-red-500 hover:bg-red-50 rounded-lg"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  )}
                </div>
              ))}
            </div>
          )}

          {/* Videos Tab */}
          {activeTab === "videos" && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <p className="text-gray-600">
                  أضف حتى 10 فيديوهات مختلفة للاختبار
                </p>
                <button
                  onClick={() => addItem("videos")}
                  disabled={formData.videos.length >= 10}
                  className="flex items-center gap-1 text-purple-600 hover:text-purple-700 disabled:opacity-50"
                >
                  <Plus className="w-4 h-4" />
                  إضافة فيديو
                </button>
              </div>
              {formData.videos.map((url, index) => (
                <div key={index} className="flex gap-2">
                  <input
                    type="url"
                    value={url}
                    onChange={(e) =>
                      updateItem("videos", index, e.target.value)
                    }
                    placeholder="رابط الفيديو"
                    className="flex-1 px-4 py-2 border rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                  {formData.videos.length > 1 && (
                    <button
                      onClick={() => removeItem("videos", index)}
                      className="p-2 text-red-500 hover:bg-red-50 rounded-lg"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  )}
                </div>
              ))}
            </div>
          )}

          {/* Titles Tab */}
          {activeTab === "titles" && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <p className="text-gray-600">
                  أضف حتى 5 عناوين مختلفة للاختبار
                </p>
                <button
                  onClick={() => addItem("titles")}
                  disabled={formData.titles.length >= 5}
                  className="flex items-center gap-1 text-purple-600 hover:text-purple-700 disabled:opacity-50"
                >
                  <Plus className="w-4 h-4" />
                  إضافة عنوان
                </button>
              </div>
              {formData.titles.map((title, index) => (
                <div key={index} className="flex gap-2">
                  <input
                    type="text"
                    value={title}
                    onChange={(e) =>
                      updateItem("titles", index, e.target.value)
                    }
                    placeholder={`العنوان ${index + 1}`}
                    maxLength={40}
                    className="flex-1 px-4 py-2 border rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                  <span className="text-xs text-gray-400 self-center">
                    {title.length}/40
                  </span>
                  {formData.titles.length > 1 && (
                    <button
                      onClick={() => removeItem("titles", index)}
                      className="p-2 text-red-500 hover:bg-red-50 rounded-lg"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  )}
                </div>
              ))}
            </div>
          )}

          {/* Bodies Tab */}
          {activeTab === "bodies" && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <p className="text-gray-600">أضف حتى 5 نصوص مختلفة للاختبار</p>
                <button
                  onClick={() => addItem("bodies")}
                  disabled={formData.bodies.length >= 5}
                  className="flex items-center gap-1 text-purple-600 hover:text-purple-700 disabled:opacity-50"
                >
                  <Plus className="w-4 h-4" />
                  إضافة نص
                </button>
              </div>
              {formData.bodies.map((body, index) => (
                <div key={index} className="flex gap-2">
                  <textarea
                    value={body}
                    onChange={(e) =>
                      updateItem("bodies", index, e.target.value)
                    }
                    placeholder={`النص الأساسي ${index + 1}`}
                    rows={3}
                    maxLength={125}
                    className="flex-1 px-4 py-2 border rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                  <div className="flex flex-col justify-between">
                    <span className="text-xs text-gray-400">
                      {body.length}/125
                    </span>
                    {formData.bodies.length > 1 && (
                      <button
                        onClick={() => removeItem("bodies", index)}
                        className="p-2 text-red-500 hover:bg-red-50 rounded-lg"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* CTAs Tab */}
          {activeTab === "ctas" && (
            <div className="space-y-4">
              <p className="text-gray-600">اختر أزرار الإجراء للاختبار</p>
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3">
                {ctaOptions.map((cta) => {
                  const isSelected = formData.callToActions.includes(cta.value);
                  return (
                    <button
                      key={cta.value}
                      onClick={() => {
                        if (isSelected) {
                          if (formData.callToActions.length > 1) {
                            setFormData((prev) => ({
                              ...prev,
                              callToActions: prev.callToActions.filter(
                                (c) => c !== cta.value,
                              ),
                            }));
                          }
                        } else {
                          setFormData((prev) => ({
                            ...prev,
                            callToActions: [...prev.callToActions, cta.value],
                          }));
                        }
                      }}
                      className={`p-3 rounded-lg border-2 transition-all ${
                        isSelected
                          ? "border-purple-500 bg-purple-50 text-purple-700"
                          : "border-gray-200 hover:border-gray-300"
                      }`}
                    >
                      <div className="flex items-center justify-center gap-2">
                        {isSelected && <CheckCircle className="w-4 h-4" />}
                        <span className="text-sm font-medium">{cta.label}</span>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Link URL */}
        <div className="p-6 border-t">
          <label className="block text-sm font-medium text-gray-700 mb-2">
            رابط الوجهة
          </label>
          {formData.linkUrls.map((url, index) => (
            <div key={index} className="flex gap-2 mb-2">
              <div className="flex-1 relative">
                <Link className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="url"
                  value={url}
                  onChange={(e) =>
                    updateItem("linkUrls", index, e.target.value)
                  }
                  placeholder="https://example.com"
                  className="w-full pr-10 pl-4 py-2 border rounded-lg focus:ring-2 focus:ring-purple-500"
                />
              </div>
            </div>
          ))}
        </div>

        {/* Actions */}
        <div className="p-6 border-t bg-gray-50 flex gap-3 justify-end">
          <button
            onClick={() => navigate("/advertising/facebook-ads")}
            className="px-6 py-2 text-gray-700 bg-white border rounded-lg hover:bg-gray-50"
          >
            إلغاء
          </button>
          <button
            onClick={handleSubmit}
            disabled={loading}
            className="px-6 py-2 text-white bg-purple-600 rounded-lg hover:bg-purple-700 disabled:opacity-50 flex items-center gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                جاري الإنشاء...
              </>
            ) : (
              <>
                <Sparkles className="w-4 h-4" />
                إنشاء الإعلان الديناميكي
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default DynamicCreativeOptimization;

/**
 * Facebook Ads Dashboard
 *
 * لوحة تحكم لإدارة إعلانات Facebook
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  ChartBarIcon,
  PlusIcon,
  PlayIcon,
  PauseIcon,
  ArrowPathIcon,
  TrashIcon,
  EyeIcon,
  CurrencyDollarIcon,
  UserGroupIcon,
  ShoppingCartIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import {
  facebookAdsService,
  FacebookCampaign,
  CAMPAIGN_OBJECTIVES,
} from "../../services/facebookAdsService";

const FacebookAdsDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [campaigns, setCampaigns] = useState<FacebookCampaign[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  // Load campaigns on mount
  useEffect(() => {
    loadCampaigns();
  }, []);

  const loadCampaigns = async () => {
    try {
      setLoading(true);
      const data = await facebookAdsService.getCampaigns();
      setCampaigns(data);
    } catch (error: any) {
      console.error("Error loading campaigns:", error);
      toast.error(error?.response?.data?.error || "فشل في تحميل الحملات");
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await loadCampaigns();
    setRefreshing(false);
    toast.success("تم تحديث البيانات");
  };

  const handleCreateCampaign = () => {
    navigate("/advertising/facebook-ads/campaigns/create");
  };

  const handleCreateFullAd = () => {
    navigate("/advertising/facebook-ads/create-ad");
  };

  const handleViewCampaign = (id: string) => {
    navigate(`/advertising/facebook-ads/campaigns/${id}`);
  };

  const handlePauseCampaign = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await facebookAdsService.pauseCampaign(id);
      toast.success("تم إيقاف الحملة");
      await loadCampaigns();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في إيقاف الحملة");
    }
  };

  const handleResumeCampaign = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await facebookAdsService.resumeCampaign(id);
      toast.success("تم استئناف الحملة");
      await loadCampaigns();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في استئناف الحملة");
    }
  };

  const handleDeleteCampaign = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!window.confirm("هل أنت متأكد من حذف هذه الحملة؟")) {
      return;
    }

    try {
      await facebookAdsService.deleteCampaign(id);
      toast.success("تم حذف الحملة");
      await loadCampaigns();
    } catch (error: any) {
      toast.error(error?.response?.data?.error || "فشل في حذف الحملة");
    }
  };

  // Calculate statistics
  const stats = {
    total: campaigns.length,
    active: campaigns.filter((c) => c.status === "ACTIVE").length,
    paused: campaigns.filter((c) => c.status === "PAUSED").length,
    totalBudget: campaigns.reduce((sum, c) => sum + c.budgetAmount, 0),
  };

  const getObjectiveLabel = (objective: string) => {
    const obj = CAMPAIGN_OBJECTIVES.find((o) => o.value === objective);
    return obj?.label || objective;
  };

  const getStatusBadge = (status: string) => {
    const badges = {
      ACTIVE: "bg-green-100 text-green-800",
      PAUSED: "bg-yellow-100 text-yellow-800",
      ARCHIVED: "bg-gray-100 text-gray-800",
      DELETED: "bg-red-100 text-red-800",
    };
    return badges[status as keyof typeof badges] || "bg-gray-100 text-gray-800";
  };

  const getStatusLabel = (status: string) => {
    const labels = {
      ACTIVE: "نشط",
      PAUSED: "متوقف",
      ARCHIVED: "مؤرشف",
      DELETED: "محذوف",
    };
    return labels[status as keyof typeof labels] || status;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96 bg-gray-50 dark:bg-gray-900">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 dark:border-indigo-400"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900 p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            إدارة إعلانات Facebook
          </h1>
          <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
            أنشئ وأدر حملاتك الإعلانية على Facebook مباشرة من هنا
          </p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleRefresh}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2 text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50"
          >
            <ArrowPathIcon
              className={`w-5 h-5 ${refreshing ? "animate-spin" : ""}`}
            />
            تحديث
          </button>
          <button
            onClick={handleCreateCampaign}
            className="flex items-center gap-2 px-4 py-2 text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            <PlusIcon className="w-5 h-5" />
            حملة فقط
          </button>
          <button
            onClick={handleCreateFullAd}
            className="flex items-center gap-2 px-4 py-2 text-white bg-gradient-to-r from-blue-600 to-indigo-600 dark:from-blue-500 dark:to-indigo-500 rounded-lg hover:from-blue-700 hover:to-indigo-700 dark:hover:from-blue-600 dark:hover:to-indigo-600 shadow-lg"
          >
            <PlusIcon className="w-5 h-5" />
            🚀 إنشاء إعلان كامل
          </button>
        </div>
      </div>

      {/* Quick Actions - Row 1 */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <button
          onClick={() => navigate("/advertising/facebook-ads/audiences")}
          className="p-4 bg-white dark:bg-gray-800 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border-0 dark:border dark:border-gray-700"
        >
          <UserGroupIcon className="w-8 h-8 text-purple-500 dark:text-purple-400 mb-2" />
          <h3 className="font-medium text-gray-900 dark:text-white">
            الجماهير
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            إدارة الجماهير المستهدفة
          </p>
        </button>
        <button
          onClick={() => navigate("/advertising/facebook-ads/automation-rules")}
          className="p-4 bg-white dark:bg-gray-800 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border-0 dark:border dark:border-gray-700"
        >
          <ChartBarIcon className="w-8 h-8 text-yellow-500 dark:text-yellow-400 mb-2" />
          <h3 className="font-medium text-gray-900 dark:text-white">
            قواعد الأتمتة
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            أتمتة إدارة الحملات
          </p>
        </button>
        <button
          onClick={() => navigate("/advertising/facebook-ads/reports")}
          className="p-4 bg-white dark:bg-gray-800 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border-0 dark:border dark:border-gray-700"
        >
          <EyeIcon className="w-8 h-8 text-blue-500 dark:text-blue-400 mb-2" />
          <h3 className="font-medium text-gray-900 dark:text-white">
            التقارير
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            تقارير الأداء المتقدمة
          </p>
        </button>
        <button
          onClick={() => navigate("/advertising/facebook-ads/catalogs")}
          className="p-4 bg-white dark:bg-gray-800 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border-0 dark:border dark:border-gray-700"
        >
          <ShoppingCartIcon className="w-8 h-8 text-green-500 dark:text-green-400 mb-2" />
          <h3 className="font-medium text-gray-900 dark:text-white">
            الكتالوجات
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            إدارة كتالوجات المنتجات
          </p>
        </button>
      </div>

      {/* Quick Actions - Row 2 (v22.0 Features) */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        <button
          onClick={() => navigate("/advertising/facebook-ads/lead-forms")}
          className="p-4 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border border-blue-100 dark:border-blue-800"
        >
          <span className="text-2xl mb-2 block">📋</span>
          <h3 className="font-medium text-gray-900 dark:text-white">
            نماذج Lead
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            جمع بيانات العملاء
          </p>
        </button>
        <button
          onClick={() => navigate("/advertising/facebook-ads/dco")}
          className="p-4 bg-gradient-to-br from-purple-50 to-pink-50 dark:from-purple-900/20 dark:to-pink-900/20 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border border-purple-100 dark:border-purple-800"
        >
          <span className="text-2xl mb-2 block">✨</span>
          <h3 className="font-medium text-gray-900 dark:text-white">DCO</h3>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            تحسين ديناميكي
          </p>
        </button>
        <button
          onClick={() => navigate("/advertising/facebook-ads/advantage-plus")}
          className="p-4 bg-gradient-to-br from-green-50 to-emerald-50 dark:from-green-900/20 dark:to-emerald-900/20 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border border-green-100 dark:border-green-800"
        >
          <span className="text-2xl mb-2 block">🛒</span>
          <h3 className="font-medium text-gray-900 dark:text-white">
            Advantage+
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            حملات تسوق ذكية
          </p>
        </button>
        <button
          onClick={() => navigate("/advertising/facebook-ads/conversions")}
          className="p-4 bg-gradient-to-br from-orange-50 to-amber-50 dark:from-orange-900/20 dark:to-amber-900/20 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border border-orange-100 dark:border-orange-800"
        >
          <span className="text-2xl mb-2 block">📊</span>
          <h3 className="font-medium text-gray-900 dark:text-white">CAPI</h3>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            تتبع التحويلات
          </p>
        </button>
        <button
          onClick={() => navigate("/advertising/facebook-ads/creative-formats")}
          className="p-4 bg-gradient-to-br from-pink-50 to-rose-50 dark:from-pink-900/20 dark:to-rose-900/20 rounded-xl shadow dark:shadow-gray-900/20 hover:shadow-md transition-all text-right border border-pink-100 dark:border-pink-800"
        >
          <span className="text-2xl mb-2 block">🎬</span>
          <h3 className="font-medium text-gray-900 dark:text-white">تنسيقات</h3>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            Stories & Reels
          </p>
        </button>
      </div>

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                إجمالي الحملات
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
                {stats.total}
              </p>
            </div>
            <div className="p-3 bg-indigo-100 dark:bg-indigo-900/30 rounded-lg">
              <ChartBarIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                حملات نشطة
              </p>
              <p className="text-2xl font-bold text-green-600 dark:text-green-400 mt-1">
                {stats.active}
              </p>
            </div>
            <div className="p-3 bg-green-100 dark:bg-green-900/30 rounded-lg">
              <PlayIcon className="w-6 h-6 text-green-600 dark:text-green-400" />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                حملات متوقفة
              </p>
              <p className="text-2xl font-bold text-yellow-600 dark:text-yellow-400 mt-1">
                {stats.paused}
              </p>
            </div>
            <div className="p-3 bg-yellow-100 dark:bg-yellow-900/30 rounded-lg">
              <PauseIcon className="w-6 h-6 text-yellow-600 dark:text-yellow-400" />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                إجمالي الميزانية
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
                {stats.totalBudget.toLocaleString()}{" "}
                {campaigns[0]?.adAccountId ? "EGP" : ""}
              </p>
            </div>
            <div className="p-3 bg-purple-100 dark:bg-purple-900/30 rounded-lg">
              <CurrencyDollarIcon className="w-6 h-6 text-purple-600 dark:text-purple-400" />
            </div>
          </div>
        </div>
      </div>

      {/* Campaigns List */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow dark:shadow-gray-900/20 border-0 dark:border dark:border-gray-700">
        <div className="p-6 border-b border-gray-200 dark:border-gray-600">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
            الحملات الإعلانية
          </h2>
        </div>

        {campaigns.length === 0 ? (
          <div className="p-12 text-center">
            <ChartBarIcon className="w-12 h-12 text-gray-400 dark:text-gray-500 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
              لا توجد حملات إعلانية
            </h3>
            <p className="text-gray-600 dark:text-gray-400 mb-6">
              ابدأ بإنشاء حملة إعلانية جديدة
            </p>
            <button
              onClick={handleCreateCampaign}
              className="inline-flex items-center gap-2 px-4 py-2 text-white bg-indigo-600 dark:bg-indigo-500 rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
            >
              <PlusIcon className="w-5 h-5" />
              إنشاء حملة جديدة
            </button>
          </div>
        ) : (
          <div className="divide-y divide-gray-200 dark:divide-gray-600">
            {campaigns.map((campaign) => (
              <div
                key={campaign.id}
                onClick={() => handleViewCampaign(campaign.id)}
                className="p-6 hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer transition-colors"
              >
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                        {campaign.name}
                      </h3>
                      <span
                        className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusBadge(campaign.status)} dark:bg-opacity-20`}
                      >
                        {getStatusLabel(campaign.status)}
                      </span>
                    </div>
                    <div className="flex items-center gap-6 text-sm text-gray-600 dark:text-gray-400">
                      <span>
                        <span className="font-medium">الهدف:</span>{" "}
                        {getObjectiveLabel(campaign.objective)}
                      </span>
                      <span>
                        <span className="font-medium">الميزانية:</span>{" "}
                        {campaign.budgetAmount.toLocaleString()}{" "}
                        {campaign.budgetType === "DAILY" ? "EGP/يوم" : "EGP"}
                      </span>
                      {campaign.startDate && (
                        <span>
                          <span className="font-medium">تاريخ البدء:</span>{" "}
                          {new Date(campaign.startDate).toLocaleDateString(
                            "ar-EG",
                          )}
                        </span>
                      )}
                    </div>
                    {campaign.adSets && campaign.adSets.length > 0 && (
                      <div className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                        {campaign.adSets.length} مجموعة إعلانات
                      </div>
                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    {campaign.status === "ACTIVE" ? (
                      <button
                        onClick={(e) => handlePauseCampaign(campaign.id, e)}
                        className="p-2 text-yellow-600 dark:text-yellow-400 hover:bg-yellow-50 dark:hover:bg-yellow-900/20 rounded-lg"
                        title="إيقاف"
                      >
                        <PauseIcon className="w-5 h-5" />
                      </button>
                    ) : campaign.status === "PAUSED" ? (
                      <button
                        onClick={(e) => handleResumeCampaign(campaign.id, e)}
                        className="p-2 text-green-600 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20 rounded-lg"
                        title="استئناف"
                      >
                        <PlayIcon className="w-5 h-5" />
                      </button>
                    ) : null}
                    <button
                      onClick={(e) => handleDeleteCampaign(campaign.id, e)}
                      className="p-2 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg"
                      title="حذف"
                    >
                      <TrashIcon className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default FacebookAdsDashboard;

/**
 * 📋 Lead Forms Management
 *
 * صفحة إدارة نماذج جمع البيانات (Lead Generation)
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  FileText,
  Plus,
  Trash2,
  Eye,
  Download,
  RefreshCw,
  Users,
  Mail,
  Phone,
  User,
  MapPin,
  Calendar,
  X,
  Loader2,
  Search,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

interface LeadForm {
  id: string;
  name: string;
  status: string;
  leads_count?: number;
  created_time?: string;
  questions?: any[];
}

interface Lead {
  id: string;
  created_time: string;
  field_data: Array<{ name: string; values: string[] }>;
}

type QuestionType =
  | "EMAIL"
  | "PHONE"
  | "FULL_NAME"
  | "FIRST_NAME"
  | "LAST_NAME"
  | "CITY"
  | "STATE"
  | "ZIP"
  | "COUNTRY"
  | "CUSTOM";

const LeadFormsManagement: React.FC = () => {
  useNavigate(); // Keep for future navigation needs
  const [forms, setForms] = useState<LeadForm[]>([]);
  const [selectedForm, setSelectedForm] = useState<LeadForm | null>(null);
  const [leads, setLeads] = useState<Lead[]>([]);
  const [loading, setLoading] = useState(true);
  const [leadsLoading, setLeadsLoading] = useState(false);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showLeadsModal, setShowLeadsModal] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  // Form creation state
  const [newForm, setNewForm] = useState({
    pageId: "",
    name: "",
    privacyPolicyUrl: "",
    questions: [
      { type: "EMAIL", key: "email", label: "البريد الإلكتروني" },
      { type: "PHONE", key: "phone", label: "رقم الهاتف" },
    ],
    thankYouPage: {
      title: "شكراً لك!",
      body: "سنتواصل معك قريباً",
      buttonText: "زيارة الموقع",
      buttonType: "VIEW_WEBSITE",
      websiteUrl: "",
    },
  });

  const questionTypes = [
    { type: "EMAIL", label: "البريد الإلكتروني", icon: Mail },
    { type: "PHONE", label: "رقم الهاتف", icon: Phone },
    { type: "FULL_NAME", label: "الاسم الكامل", icon: User },
    { type: "FIRST_NAME", label: "الاسم الأول", icon: User },
    { type: "LAST_NAME", label: "اسم العائلة", icon: User },
    { type: "CITY", label: "المدينة", icon: MapPin },
    { type: "STATE", label: "المنطقة", icon: MapPin },
    { type: "ZIP", label: "الرمز البريدي", icon: MapPin },
    { type: "COUNTRY", label: "الدولة", icon: MapPin },
    { type: "DOB", label: "تاريخ الميلاد", icon: Calendar },
  ];

  useEffect(() => {
    loadForms();
  }, []);

  const loadForms = async () => {
    try {
      setLoading(true);
      // Note: This would need a backend endpoint to list forms
      // For now, we'll show empty state
      setForms([]);
    } catch (error) {
      console.error("Error loading forms:", error);
      toast.error("فشل في تحميل النماذج");
    } finally {
      setLoading(false);
    }
  };

  const loadLeads = async (formId: string) => {
    try {
      setLeadsLoading(true);
      const data = await facebookAdsService.getLeads(formId);
      setLeads(data);
    } catch (error) {
      console.error("Error loading leads:", error);
      toast.error("فشل في تحميل البيانات");
    } finally {
      setLeadsLoading(false);
    }
  };

  const handleCreateForm = async () => {
    if (!newForm.pageId || !newForm.name || !newForm.privacyPolicyUrl) {
      toast.error("يرجى ملء جميع الحقول المطلوبة");
      return;
    }

    try {
      setLoading(true);
      const formPayload: any = {
        pageId: newForm.pageId,
        name: newForm.name,
        questions: newForm.questions,
        privacyPolicyUrl: newForm.privacyPolicyUrl,
        thankYouPage: newForm.thankYouPage,
      };
      await facebookAdsService.createLeadForm(formPayload);
      toast.success("تم إنشاء النموذج بنجاح!");
      setShowCreateModal(false);
      loadForms();
    } catch (error: any) {
      console.error("Error creating form:", error);
      toast.error(error?.response?.data?.error || "فشل في إنشاء النموذج");
    } finally {
      setLoading(false);
    }
  };

  const handleViewLeads = (form: LeadForm) => {
    setSelectedForm(form);
    setShowLeadsModal(true);
    loadLeads(form.id);
  };

  const addQuestion = (type: string) => {
    const questionType = questionTypes.find((q) => q.type === type);
    if (questionType) {
      setNewForm((prev) => ({
        ...prev,
        questions: [
          ...prev.questions,
          { type, key: type.toLowerCase(), label: questionType.label },
        ],
      }));
    }
  };

  const removeQuestion = (index: number) => {
    setNewForm((prev) => ({
      ...prev,
      questions: prev.questions.filter((_, i) => i !== index),
    }));
  };

  const exportLeadsToCSV = () => {
    if (leads.length === 0) return;

    const headers = leads[0]?.field_data?.map((f) => f.name) || [];
    const rows = leads.map(
      (lead) =>
        lead.field_data?.map((f) => f.values?.join(", ") || "").join(",") || "",
    );

    const csv = [headers.join(","), ...rows].join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `leads_${selectedForm?.name || "export"}_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
    URL.revokeObjectURL(url);
    toast.success("تم تصدير البيانات بنجاح!");
  };

  const filteredForms = forms.filter((form) =>
    form.name.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  return (
    <div
      className="p-6 space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <FileText className="w-7 h-7 text-blue-600 dark:text-blue-400" />
            نماذج جمع البيانات
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            إدارة نماذج Lead Generation وجمع بيانات العملاء المحتملين
          </p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={loadForms}
            className="flex items-center gap-2 px-4 py-2 text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            <RefreshCw className="w-4 h-4" />
            تحديث
          </button>
          <button
            onClick={() => setShowCreateModal(true)}
            className="flex items-center gap-2 px-4 py-2 text-white bg-blue-600 dark:bg-blue-500 rounded-lg hover:bg-blue-700 dark:hover:bg-blue-600"
          >
            <Plus className="w-4 h-4" />
            إنشاء نموذج جديد
          </button>
        </div>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
        <input
          type="text"
          placeholder="البحث في النماذج..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full pr-10 pl-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
        />
      </div>

      {/* Forms List */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
        </div>
      ) : filteredForms.length === 0 ? (
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm dark:shadow-gray-900/20 border border-gray-200 dark:border-gray-700 p-12 text-center">
          <FileText className="w-16 h-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
            لا توجد نماذج
          </h3>
          <p className="text-gray-500 dark:text-gray-400 mb-4">
            ابدأ بإنشاء نموذج جديد لجمع بيانات العملاء المحتملين
          </p>
          <button
            onClick={() => setShowCreateModal(true)}
            className="inline-flex items-center gap-2 px-4 py-2 text-white bg-blue-600 dark:bg-blue-500 rounded-lg hover:bg-blue-700 dark:hover:bg-blue-600"
          >
            <Plus className="w-4 h-4" />
            إنشاء نموذج جديد
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredForms.map((form) => (
            <div
              key={form.id}
              className="bg-white dark:bg-gray-800 rounded-xl shadow-sm dark:shadow-gray-900/20 border border-gray-200 dark:border-gray-700 p-5 hover:shadow-md transition-shadow"
            >
              <div className="flex items-start justify-between mb-4">
                <div>
                  <h3 className="font-semibold text-gray-900 dark:text-white">
                    {form.name}
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                    {form.created_time
                      ? new Date(form.created_time).toLocaleDateString("ar-EG")
                      : ""}
                  </p>
                </div>
                <span
                  className={`px-2 py-1 text-xs rounded-full ${
                    form.status === "ACTIVE"
                      ? "bg-green-100 text-green-700"
                      : "bg-gray-100 text-gray-700"
                  }`}
                >
                  {form.status === "ACTIVE" ? "نشط" : form.status}
                </span>
              </div>

              <div className="flex items-center gap-4 text-sm text-gray-600 dark:text-gray-400 mb-4">
                <div className="flex items-center gap-1">
                  <Users className="w-4 h-4" />
                  <span>{form.leads_count || 0} عميل محتمل</span>
                </div>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={() => handleViewLeads(form)}
                  className="flex-1 flex items-center justify-center gap-1 px-3 py-2 text-blue-600 bg-blue-50 rounded-lg hover:bg-blue-100"
                >
                  <Eye className="w-4 h-4" />
                  عرض البيانات
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Form Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto border-0 dark:border dark:border-gray-700">
            <div className="p-6 border-b border-gray-200 dark:border-gray-600 sticky top-0 bg-white dark:bg-gray-800">
              <div className="flex items-center justify-between">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                  إنشاء نموذج جديد
                </h2>
                <button
                  onClick={() => setShowCreateModal(false)}
                  className="text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>
            </div>

            <div className="p-6 space-y-6">
              {/* Basic Info */}
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    معرف الصفحة *
                  </label>
                  <input
                    type="text"
                    value={newForm.pageId}
                    onChange={(e) =>
                      setNewForm((prev) => ({
                        ...prev,
                        pageId: e.target.value,
                      }))
                    }
                    placeholder="أدخل معرف صفحة Facebook"
                    className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    اسم النموذج *
                  </label>
                  <input
                    type="text"
                    value={newForm.name}
                    onChange={(e) =>
                      setNewForm((prev) => ({ ...prev, name: e.target.value }))
                    }
                    placeholder="مثال: نموذج التسجيل"
                    className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    رابط سياسة الخصوصية *
                  </label>
                  <input
                    type="url"
                    value={newForm.privacyPolicyUrl}
                    onChange={(e) =>
                      setNewForm((prev) => ({
                        ...prev,
                        privacyPolicyUrl: e.target.value,
                      }))
                    }
                    placeholder="https://example.com/privacy"
                    className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                  />
                </div>
              </div>

              {/* Questions */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الأسئلة
                </label>
                <div className="space-y-2 mb-3">
                  {newForm.questions.map((q, index) => (
                    <div
                      key={index}
                      className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-700 rounded-lg"
                    >
                      <span className="text-gray-700 dark:text-gray-300">
                        {q.label}
                      </span>
                      <button
                        onClick={() => removeQuestion(index)}
                        className="text-red-500 dark:text-red-400 hover:text-red-700 dark:hover:text-red-300"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>

                <div className="flex flex-wrap gap-2">
                  {questionTypes.map((qt) => {
                    const Icon = qt.icon;
                    const isAdded = newForm.questions.some(
                      (q) => q.type === qt.type,
                    );
                    return (
                      <button
                        key={qt.type}
                        onClick={() => !isAdded && addQuestion(qt.type)}
                        disabled={isAdded}
                        className={`flex items-center gap-1 px-3 py-1.5 text-sm rounded-lg border ${
                          isAdded
                            ? "bg-gray-100 dark:bg-gray-600 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-300 dark:border-gray-500"
                            : "bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-600 border-gray-300 dark:border-gray-600"
                        }`}
                      >
                        <Icon className="w-4 h-4" />
                        {qt.label}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Thank You Page */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  صفحة الشكر
                </label>
                <div className="space-y-3 p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                  <input
                    type="text"
                    value={newForm.thankYouPage.title}
                    onChange={(e) =>
                      setNewForm((prev) => ({
                        ...prev,
                        thankYouPage: {
                          ...prev.thankYouPage,
                          title: e.target.value,
                        },
                      }))
                    }
                    placeholder="العنوان"
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                  />
                  <textarea
                    value={newForm.thankYouPage.body}
                    onChange={(e) =>
                      setNewForm((prev) => ({
                        ...prev,
                        thankYouPage: {
                          ...prev.thankYouPage,
                          body: e.target.value,
                        },
                      }))
                    }
                    placeholder="الرسالة"
                    rows={2}
                    className="w-full px-3 py-2 border rounded-lg"
                  />
                  <input
                    type="url"
                    value={newForm.thankYouPage.websiteUrl}
                    onChange={(e) =>
                      setNewForm((prev) => ({
                        ...prev,
                        thankYouPage: {
                          ...prev.thankYouPage,
                          websiteUrl: e.target.value,
                        },
                      }))
                    }
                    placeholder="رابط الموقع (اختياري)"
                    className="w-full px-3 py-2 border rounded-lg"
                  />
                </div>
              </div>
            </div>

            <div className="p-6 border-t bg-gray-50 flex gap-3 justify-end">
              <button
                onClick={() => setShowCreateModal(false)}
                className="px-4 py-2 text-gray-700 bg-white border rounded-lg hover:bg-gray-50"
              >
                إلغاء
              </button>
              <button
                onClick={handleCreateForm}
                disabled={loading}
                className="px-4 py-2 text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
              >
                {loading && <Loader2 className="w-4 h-4 animate-spin" />}
                إنشاء النموذج
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Leads Modal */}
      {showLeadsModal && selectedForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-6 border-b flex items-center justify-between">
              <div>
                <h2 className="text-xl font-bold text-gray-900">
                  بيانات العملاء المحتملين
                </h2>
                <p className="text-gray-500">{selectedForm.name}</p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={exportLeadsToCSV}
                  disabled={leads.length === 0}
                  className="flex items-center gap-2 px-3 py-2 text-green-600 bg-green-50 rounded-lg hover:bg-green-100 disabled:opacity-50"
                >
                  <Download className="w-4 h-4" />
                  تصدير CSV
                </button>
                <button
                  onClick={() => setShowLeadsModal(false)}
                  className="text-gray-500 hover:text-gray-700"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-auto p-6">
              {leadsLoading ? (
                <div className="flex items-center justify-center py-12">
                  <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
                </div>
              ) : leads.length === 0 ? (
                <div className="text-center py-12">
                  <Users className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                  <p className="text-gray-500">لا توجد بيانات بعد</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="bg-gray-50">
                        <th className="px-4 py-3 text-right text-sm font-medium text-gray-700">
                          التاريخ
                        </th>
                        {leads[0]?.field_data?.map((field, i) => (
                          <th
                            key={i}
                            className="px-4 py-3 text-right text-sm font-medium text-gray-700"
                          >
                            {field.name}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {leads.map((lead) => (
                        <tr key={lead.id} className="hover:bg-gray-50">
                          <td className="px-4 py-3 text-sm text-gray-600">
                            {new Date(lead.created_time).toLocaleDateString(
                              "ar-EG",
                            )}
                          </td>
                          {lead.field_data?.map((field, i) => (
                            <td
                              key={i}
                              className="px-4 py-3 text-sm text-gray-900"
                            >
                              {field.values?.join(", ") || "-"}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default LeadFormsManagement;

/**
 * 👥 Saved Audiences
 *
 * إدارة الجماهير المحفوظة
 */

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  Users,
  Plus,
  Search,
  Trash2,
  Eye,
  Loader2,
  ArrowLeft,
  Target,
  Calendar,
  MoreVertical,
  CheckCircle,
} from "lucide-react";
import { facebookAdsService } from "../../services/facebookAdsService";

interface SavedAudience {
  id: string;
  name: string;
  description?: string;
  targeting: any;
  approximateCount?: number;
  createdAt: string;
}

const SavedAudiences: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [audiences, setAudiences] = useState<SavedAudience[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [creating, setCreating] = useState(false);
  const [selectedAudience, setSelectedAudience] =
    useState<SavedAudience | null>(null);

  const [newAudience, setNewAudience] = useState({
    name: "",
    description: "",
    ageMin: 18,
    ageMax: 65,
    genders: [] as number[],
    countries: ["SA"],
    interests: "",
  });

  const countries = [
    { code: "SA", name: "السعودية" },
    { code: "AE", name: "الإمارات" },
    { code: "EG", name: "مصر" },
    { code: "KW", name: "الكويت" },
    { code: "QA", name: "قطر" },
    { code: "BH", name: "البحرين" },
    { code: "OM", name: "عمان" },
    { code: "JO", name: "الأردن" },
  ];

  useEffect(() => {
    loadAudiences();
  }, []);

  const loadAudiences = async () => {
    try {
      setLoading(true);
      const data = await facebookAdsService.getSavedAudiences();
      setAudiences(data || []);
    } catch (error) {
      console.error("Error loading audiences:", error);
      toast.error("فشل في تحميل الجماهير");
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async () => {
    if (!newAudience.name.trim()) {
      toast.error("يرجى إدخال اسم الجمهور");
      return;
    }

    try {
      setCreating(true);

      const targeting: any = {
        age_min: newAudience.ageMin,
        age_max: newAudience.ageMax,
        geo_locations: {
          countries: newAudience.countries,
        },
      };

      if (newAudience.genders.length > 0) {
        targeting.genders = newAudience.genders;
      }

      if (newAudience.interests.trim()) {
        targeting.flexible_spec = [
          {
            interests: newAudience.interests
              .split(",")
              .map((i) => ({ name: i.trim() })),
          },
        ];
      }

      const audiencePayload: any = {
        name: newAudience.name,
        targeting,
      };
      if (newAudience.description) {
        audiencePayload.description = newAudience.description;
      }
      await facebookAdsService.createSavedAudience(audiencePayload);

      toast.success("تم إنشاء الجمهور بنجاح! ✅");
      setShowCreateModal(false);
      setNewAudience({
        name: "",
        description: "",
        ageMin: 18,
        ageMax: 65,
        genders: [],
        countries: ["SA"],
        interests: "",
      });
      loadAudiences();
    } catch (error: any) {
      console.error("Error creating audience:", error);
      toast.error(error?.response?.data?.error || "فشل في إنشاء الجمهور");
    } finally {
      setCreating(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا الجمهور؟")) return;

    try {
      await facebookAdsService.deleteSavedAudience(id);
      toast.success("تم حذف الجمهور");
      setAudiences((prev) => prev.filter((a) => a.id !== id));
    } catch (error: any) {
      console.error("Error deleting audience:", error);
      toast.error(error?.response?.data?.error || "فشل في حذف الجمهور");
    }
  };

  const filteredAudiences = audiences.filter((a) =>
    a.name.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  const toggleGender = (gender: number) => {
    setNewAudience((prev) => ({
      ...prev,
      genders: prev.genders.includes(gender)
        ? prev.genders.filter((g) => g !== gender)
        : [...prev.genders, gender],
    }));
  };

  const toggleCountry = (code: string) => {
    setNewAudience((prev) => ({
      ...prev,
      countries: prev.countries.includes(code)
        ? prev.countries.filter((c) => c !== code)
        : [...prev.countries, code],
    }));
  };

  return (
    <div
      className="p-6 space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate("/advertising/facebook-ads/audiences")}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg"
          >
            <ArrowLeft className="w-5 h-5 text-gray-600 dark:text-gray-400" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
              <Users className="w-7 h-7 text-blue-600 dark:text-blue-400" />
              الجماهير المحفوظة
            </h1>
            <p className="text-gray-600 dark:text-gray-400 mt-1">
              إنشاء وإدارة الجماهير المستهدفة القابلة لإعادة الاستخدام
            </p>
          </div>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 px-4 py-2 text-white bg-blue-600 dark:bg-blue-500 rounded-lg hover:bg-blue-700 dark:hover:bg-blue-600"
        >
          <Plus className="w-5 h-5" />
          جمهور جديد
        </button>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="البحث في الجماهير..."
          className="w-full pr-10 pl-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
        />
      </div>

      {/* Audiences List */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
        </div>
      ) : filteredAudiences.length === 0 ? (
        <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700">
          <Users className="w-16 h-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
            لا توجد جماهير محفوظة
          </h3>
          <p className="text-gray-500 dark:text-gray-400 mb-4">
            أنشئ جمهوراً جديداً لاستخدامه في حملاتك
          </p>
          <button
            onClick={() => setShowCreateModal(true)}
            className="px-4 py-2 text-white bg-blue-600 dark:bg-blue-500 rounded-lg hover:bg-blue-700 dark:hover:bg-blue-600"
          >
            إنشاء جمهور
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredAudiences.map((audience) => (
            <div
              key={audience.id}
              className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm hover:shadow-md transition-shadow"
            >
              <div className="p-4">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg">
                      <Target className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-gray-900 dark:text-white">
                        {audience.name}
                      </h3>
                      {audience.description && (
                        <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
                          {audience.description}
                        </p>
                      )}
                    </div>
                  </div>
                  <button className="p-1 text-gray-400 hover:text-gray-600">
                    <MoreVertical className="w-5 h-5" />
                  </button>
                </div>

                {audience.approximateCount && (
                  <div className="mt-4 flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                    <Users className="w-4 h-4" />
                    <span>
                      ~{audience.approximateCount.toLocaleString()} شخص
                    </span>
                  </div>
                )}

                <div className="mt-4 flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
                  <Calendar className="w-3 h-3" />
                  <span>
                    {new Date(audience.createdAt).toLocaleDateString("ar-EG")}
                  </span>
                </div>
              </div>

              <div className="px-4 py-3 border-t border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-700/50 flex gap-2">
                <button
                  onClick={() => setSelectedAudience(audience)}
                  className="flex-1 py-1.5 text-sm text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-600 rounded-lg flex items-center justify-center gap-1"
                >
                  <Eye className="w-4 h-4" />
                  عرض
                </button>
                <button
                  onClick={() => handleDelete(audience.id)}
                  className="flex-1 py-1.5 text-sm text-red-600 hover:text-red-700 hover:bg-red-50 rounded-lg flex items-center justify-center gap-1"
                >
                  <Trash2 className="w-4 h-4" />
                  حذف
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-xl w-full max-w-lg max-h-[90vh] overflow-y-auto border-0 dark:border dark:border-gray-700">
            <div className="p-6 border-b border-gray-200 dark:border-gray-600">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                إنشاء جمهور جديد
              </h2>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  اسم الجمهور *
                </label>
                <input
                  type="text"
                  value={newAudience.name}
                  onChange={(e) =>
                    setNewAudience((prev) => ({
                      ...prev,
                      name: e.target.value,
                    }))
                  }
                  placeholder="مثال: عملاء السعودية 25-45"
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  الوصف
                </label>
                <textarea
                  value={newAudience.description}
                  onChange={(e) =>
                    setNewAudience((prev) => ({
                      ...prev,
                      description: e.target.value,
                    }))
                  }
                  placeholder="وصف اختياري للجمهور"
                  rows={2}
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الفئة العمرية
                </label>
                <div className="flex items-center gap-4">
                  <div className="flex-1">
                    <label className="text-xs text-gray-500 dark:text-gray-400">
                      من
                    </label>
                    <input
                      type="number"
                      value={newAudience.ageMin}
                      onChange={(e) =>
                        setNewAudience((prev) => ({
                          ...prev,
                          ageMin: Number(e.target.value),
                        }))
                      }
                      min={13}
                      max={65}
                      className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    />
                  </div>
                  <div className="flex-1">
                    <label className="text-xs text-gray-500">إلى</label>
                    <input
                      type="number"
                      value={newAudience.ageMax}
                      onChange={(e) =>
                        setNewAudience((prev) => ({
                          ...prev,
                          ageMax: Number(e.target.value),
                        }))
                      }
                      min={13}
                      max={65}
                      className="w-full px-3 py-2 border rounded-lg"
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  الجنس
                </label>
                <div className="flex gap-3">
                  <button
                    onClick={() => toggleGender(1)}
                    className={`flex-1 p-2 rounded-lg border-2 transition-all ${
                      newAudience.genders.includes(1)
                        ? "border-blue-500 bg-blue-50 text-blue-700"
                        : "border-gray-200"
                    }`}
                  >
                    ذكور
                  </button>
                  <button
                    onClick={() => toggleGender(2)}
                    className={`flex-1 p-2 rounded-lg border-2 transition-all ${
                      newAudience.genders.includes(2)
                        ? "border-pink-500 bg-pink-50 text-pink-700"
                        : "border-gray-200"
                    }`}
                  >
                    إناث
                  </button>
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  اترك فارغاً لاستهداف الجميع
                </p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  الدول
                </label>
                <div className="flex flex-wrap gap-2">
                  {countries.map((country) => (
                    <button
                      key={country.code}
                      onClick={() => toggleCountry(country.code)}
                      className={`px-3 py-1.5 rounded-lg border-2 text-sm transition-all ${
                        newAudience.countries.includes(country.code)
                          ? "border-green-500 bg-green-50 text-green-700"
                          : "border-gray-200"
                      }`}
                    >
                      {country.name}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  الاهتمامات
                </label>
                <input
                  type="text"
                  value={newAudience.interests}
                  onChange={(e) =>
                    setNewAudience((prev) => ({
                      ...prev,
                      interests: e.target.value,
                    }))
                  }
                  placeholder="مثال: تسوق, موضة, تقنية (افصل بفاصلة)"
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <div className="p-6 border-t bg-gray-50 flex gap-3 justify-end">
              <button
                onClick={() => setShowCreateModal(false)}
                className="px-4 py-2 text-gray-700 bg-white border rounded-lg hover:bg-gray-50"
              >
                إلغاء
              </button>
              <button
                onClick={handleCreate}
                disabled={creating}
                className="px-4 py-2 text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
              >
                {creating ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    جاري الإنشاء...
                  </>
                ) : (
                  <>
                    <CheckCircle className="w-4 h-4" />
                    إنشاء الجمهور
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* View Audience Modal */}
      {selectedAudience && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-md">
            <div className="p-6 border-b flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-900">
                {selectedAudience.name}
              </h2>
              <button
                onClick={() => setSelectedAudience(null)}
                className="p-1 text-gray-400 hover:text-gray-600"
              >
                ✕
              </button>
            </div>
            <div className="p-6">
              {selectedAudience.description && (
                <p className="text-gray-600 mb-4">
                  {selectedAudience.description}
                </p>
              )}
              <div className="bg-gray-50 rounded-lg p-4">
                <h3 className="font-medium text-gray-900 mb-2">
                  إعدادات الاستهداف
                </h3>
                <pre className="text-xs text-gray-600 overflow-auto max-h-60">
                  {JSON.stringify(selectedAudience.targeting, null, 2)}
                </pre>
              </div>
            </div>
            <div className="p-6 border-t bg-gray-50">
              <button
                onClick={() => setSelectedAudience(null)}
                className="w-full py-2 text-gray-700 bg-white border rounded-lg hover:bg-gray-50"
              >
                إغلاق
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SavedAudiences;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import toast from "react-hot-toast";
import { useTheme } from "../../hooks/useTheme";
import {
  BanknotesIcon,
  CreditCardIcon,
  ClockIcon,
  CheckCircleIcon,
  ArrowTrendingUpIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";

const AffiliateCommission: React.FC = () => {
  const { formatPrice } = useCurrency();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";

  const [loading, setLoading] = useState(true);
  const [affiliate, setAffiliate] = useState<any>(null);
  const [payouts, setPayouts] = useState<any[]>([]);
  const [commissions, setCommissions] = useState<any[]>([]);
  const [expectedCommission, setExpectedCommission] = useState(0);

  // Payout Modal State
  const [showPayoutModal, setShowPayoutModal] = useState(false);
  const [payoutAmount, setPayoutAmount] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("");
  const [paymentDetails, setPaymentDetails] = useState("");
  const [submittingPayout, setSubmittingPayout] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [affiliateRes, payoutsRes, commissionsRes] = await Promise.all([
        apiClient.get("/affiliates/me"),
        apiClient.get("/affiliates/payouts"),
        apiClient.get("/affiliates/commissions?limit=20"), // Get recent commissions
      ]);

      if (affiliateRes.data.success) {
        setAffiliate(affiliateRes.data.data);
      }

      if (payoutsRes.data.success) {
        setPayouts(payoutsRes.data.data);
      }

      if (commissionsRes.data.success) {
        const commissionsData = commissionsRes.data.data?.commissions || [];
        setCommissions(commissionsData);

        // حساب العمولة المتوقعة من الطلبات غير المستلمة
        const expectedAmount = commissionsData
          .filter((comm: any) => {
            const status = comm.order?.status || comm.status;
            // الطلبات التي لم تُستلم بعد: PENDING, CONFIRMED, PROCESSING, SHIPPED
            return ["PENDING", "CONFIRMED", "PROCESSING", "SHIPPED"].includes(
              status,
            );
          })
          .reduce(
            (sum: number, comm: any) => sum + (parseFloat(comm.amount) || 0),
            0,
          );

        setExpectedCommission(expectedAmount);
      }
    } catch (error) {
      console.error("Error loading commission data:", error);
      toast.error("حدث خطأ أثناء تحميل البيانات");
    } finally {
      setLoading(false);
    }
  };

  const handleRequestPayout = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!payoutAmount || Number(payoutAmount) <= 0) {
      toast.error("الرجاء إدخال مبلغ صالح");
      return;
    }

    if (Number(payoutAmount) > Number(affiliate?.pendingEarnings || 0)) {
      toast.error("المبلغ المطلوب أكبر من الرصيد المتاح");
      return;
    }

    try {
      setSubmittingPayout(true);
      const response = await apiClient.post("/affiliates/payout/request", {
        amount: Number(payoutAmount),
        paymentMethod,
        paymentDetails: { note: paymentDetails },
      });

      if (response.data.success) {
        toast.success("تم إرسال طلب السحب بنجاح");
        setShowPayoutModal(false);
        setPayoutAmount("");
        setPaymentDetails("");
        loadData(); // Reload data to update balance
      }
    } catch (error: any) {
      console.error("Error requesting payout:", error);
      toast.error(error.response?.data?.message || "فشل طلب السحب");
    } finally {
      setSubmittingPayout(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "CONFIRMED":
        return "text-green-600 bg-green-100 dark:bg-green-900/30 dark:text-green-400";
      case "PENDING":
        return "text-yellow-600 bg-yellow-100 dark:bg-yellow-900/30 dark:text-yellow-400";
      case "PAID":
        return "text-blue-600 bg-blue-100 dark:bg-blue-900/30 dark:text-blue-400";
      case "CANCELLED":
        return "text-red-600 bg-red-100 dark:bg-red-900/30 dark:text-red-400";
      default:
        return "text-gray-600 bg-gray-100 dark:bg-gray-800 dark:text-gray-400";
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case "CONFIRMED":
        return "مؤكدة";
      case "PENDING":
        return "قيد الانتظار"; // For payouts
      case "PAID":
        return "تم الدفع";
      case "PAID_EXTERNAL":
        return "تم الدفع";
      case "PROCESSING":
        return "قيد المعالجة";
      case "CANCELLED":
        return "ملغية";
      case "FAILED":
        return "فشل";
      default:
        return status;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="p-6 w-full space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            العمولات والأرباح
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            متابعة الأرباح وطلبات السحب
          </p>
        </div>
        <button
          onClick={() => setShowPayoutModal(true)}
          disabled={affiliate?.pendingEarnings <= 0}
          className={`px-4 py-2 rounded-lg flex items-center gap-2 ${
            affiliate?.pendingEarnings > 0
              ? "bg-green-600 hover:bg-green-700 text-white"
              : "bg-gray-300 cursor-not-allowed text-gray-500 dark:bg-gray-700 dark:text-gray-400"
          }`}
        >
          <BanknotesIcon className="w-5 h-5" />
          طلب سحب الرصيد
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Withdrawable Balance */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
                الرصيد القابل للسحب
              </p>
              <h3 className="text-3xl font-bold text-green-600 mt-2">
                {formatPrice(affiliate?.pendingEarnings || 0)}
              </h3>
            </div>
            <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-lg">
              <BanknotesIcon className="w-6 h-6 text-green-600 dark:text-green-400" />
            </div>
          </div>
          <p className="text-xs text-gray-400 mt-4">
            الحد الأدنى للسحب: {formatPrice(affiliate?.minPayout || 100)}
          </p>
        </div>

        {/* Expected Commission */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
                العمولة المتوقعة
              </p>
              <h3 className="text-3xl font-bold text-orange-600 mt-2">
                {formatPrice(expectedCommission)}
              </h3>
            </div>
            <div className="p-3 bg-orange-50 dark:bg-orange-900/20 rounded-lg">
              <ClockIcon className="w-6 h-6 text-orange-600 dark:text-orange-400" />
            </div>
          </div>
          <p className="text-xs text-gray-400 mt-4">
            من الطلبات التي لم تُستلم بعد
          </p>
        </div>

        {/* Total Earnings */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
                إجمالي الأرباح
              </p>
              <h3 className="text-3xl font-bold text-blue-600 mt-2">
                {formatPrice(affiliate?.totalEarnings || 0)}
              </h3>
            </div>
            <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
              <ArrowTrendingUpIcon className="w-6 h-6 text-blue-600 dark:text-blue-400" />
            </div>
          </div>
          <p className="text-xs text-gray-400 mt-4">منذ بداية العمل</p>
        </div>

        {/* Paid Earnings */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
                تم صرفه
              </p>
              <h3 className="text-3xl font-bold text-purple-600 mt-2">
                {formatPrice(affiliate?.paidEarnings || 0)}
              </h3>
            </div>
            <div className="p-3 bg-purple-50 dark:bg-purple-900/20 rounded-lg">
              <CreditCardIcon className="w-6 h-6 text-purple-600 dark:text-purple-400" />
            </div>
          </div>
          <p className="text-xs text-gray-400 mt-4">إجمالي المبالغ المحولة</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Recent Payouts */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
            <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
              <ClockIcon className="w-5 h-5 text-gray-500" />
              سجل طلبات السحب
            </h3>
          </div>
          <div className="p-0 overflow-x-auto">
            {payouts.length > 0 ? (
              <table className="w-full text-sm text-right">
                <thead className="bg-gray-50 dark:bg-gray-900/50 text-gray-500 dark:text-gray-400">
                  <tr>
                    <th className="p-3">التاريخ</th>
                    <th className="p-3">المبلغ</th>
                    <th className="p-3">طريقة الدفع</th>
                    <th className="p-3">الحالة</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {payouts.map((payout) => (
                    <tr
                      key={payout.id}
                      className="hover:bg-gray-50 dark:hover:bg-gray-700/50"
                    >
                      <td className="p-3 text-gray-600 dark:text-gray-300">
                        {new Date(payout.createdAt).toLocaleDateString("ar-EG")}
                      </td>
                      <td className="p-3 font-bold text-gray-900 dark:text-white">
                        {formatPrice(payout.amount)}
                      </td>
                      <td className="p-3 text-gray-600 dark:text-gray-300">
                        {payout.paymentMethod}
                      </td>
                      <td className="p-3">
                        <span
                          className={`px-2 py-1 rounded-full text-xs ${getStatusColor(payout.status)}`}
                        >
                          {getStatusText(payout.status)}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <div className="p-8 text-center text-gray-500 dark:text-gray-400">
                لا توجد عمليات سحب سابقة
              </div>
            )}
          </div>
        </div>

        {/* Recent Commissions */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
            <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
              <CheckCircleIcon className="w-5 h-5 text-gray-500" />
              أحدث العمولات
            </h3>
          </div>
          <div className="p-0 overflow-x-auto">
            {commissions.length > 0 ? (
              <table className="w-full text-sm text-right">
                <thead className="bg-gray-50 dark:bg-gray-900/50 text-gray-500 dark:text-gray-400">
                  <tr>
                    <th className="p-3">رقم الطلب</th>
                    <th className="p-3">قيمة الطلب</th>
                    <th className="p-3">العمولة</th>
                    <th className="p-3">التاريخ</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {commissions.map((comm) => (
                    <tr
                      key={comm.id}
                      className="hover:bg-gray-50 dark:hover:bg-gray-700/50"
                    >
                      <td className="p-3 text-blue-600 dark:text-blue-400 font-mono">
                        {comm.order?.orderNumber || "غير متوفر"}
                      </td>
                      <td className="p-3 text-gray-600 dark:text-gray-300">
                        {formatPrice(comm.orderTotal)}
                      </td>
                      <td className="p-3 font-bold text-green-600 dark:text-green-400">
                        +{formatPrice(comm.amount)}
                      </td>
                      <td className="p-3 text-gray-500 text-xs">
                        {new Date(comm.createdAt).toLocaleDateString("ar-EG")}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <div className="p-8 text-center text-gray-500 dark:text-gray-400">
                لا توجد عمولات مسجلة
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Payout Request Modal */}
      {showPayoutModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl max-w-md w-full overflow-hidden">
            <div className="p-6 border-b border-gray-100 dark:border-gray-700">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                طلب سحب جديد
              </h3>
            </div>

            <form onSubmit={handleRequestPayout} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  المبلغ المطلوب (الحد الأقصى:{" "}
                  {formatPrice(affiliate?.pendingEarnings)})
                </label>
                <input
                  type="number"
                  value={payoutAmount}
                  onChange={(e) => setPayoutAmount(e.target.value)}
                  max={affiliate?.pendingEarnings}
                  className="w-full px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                  placeholder="0.00"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  طريقة الدفع
                </label>
                <select
                  value={paymentMethod}
                  onChange={(e) => setPaymentMethod(e.target.value)}
                  className="w-full px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                  required
                >
                  <option value="">اختر طريقة الدفع</option>
                  <option value="VODAFONE_CASH">فودافون كاش</option>
                  <option value="INSTAPAY">إنستاباي</option>
                  <option value="BANK_TRANSFER">تحويل بنكي</option>
                  <option value="OTHER">أخرى</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  بيانات التحويل (رقم المحفظة / الحساب)
                </label>
                <textarea
                  value={paymentDetails}
                  onChange={(e) => setPaymentDetails(e.target.value)}
                  className="w-full px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                  rows={3}
                  required
                  placeholder="مثال: 010xxxxxx"
                />
              </div>

              <div className="flex gap-3 mt-6">
                <button
                  type="button"
                  onClick={() => setShowPayoutModal(false)}
                  className="flex-1 px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600"
                >
                  إلغاء
                </button>
                <button
                  type="submit"
                  disabled={submittingPayout}
                  className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex justify-center items-center gap-2"
                >
                  {submittingPayout ? (
                    <ArrowPathIcon className="w-5 h-5 animate-spin" />
                  ) : (
                    "تأكيد الطلب"
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AffiliateCommission;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import { useTheme } from "../../hooks/useTheme";
import {
  UserGroupIcon,
  ShoppingBagIcon,
  CurrencyDollarIcon,
  PlusIcon,
} from "@heroicons/react/24/outline";
import { useNavigate } from "react-router-dom";

interface Customer {
  id: string;
  firstName: string;
  lastName: string;
  phone: string;
  email: string;
  totalOrders: number;
  totalSpent: number;
}

const AffiliateCustomers: React.FC = () => {
  const { formatPrice } = useCurrency();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const navigate = useNavigate();
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCustomers();
  }, []);

  const loadCustomers = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/affiliates/customers");
      if (response.data.success) {
        setCustomers(response.data.data);
      }
    } catch (error: any) {
      console.error("Error loading customers:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div
        className={`flex items-center justify-center min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"}`}
      >
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div className="w-full">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1
              className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"}`}
            >
              عملائي
            </h1>
            <p className={`${isDark ? "text-gray-300" : "text-gray-600"} mt-2`}>
              جميع العملاء المرتبطين بك
            </p>
          </div>
