                </p>
              </div>
              <CurrencyDollarIcon className="h-8 w-8 text-green-600" />
            </div>
          </div>

          <div
            className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow p-6`}
          >
