import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import { useTheme } from "../../hooks/useTheme";
import {
  ShoppingBagIcon,
  MagnifyingGlassIcon,
  PlusCircleIcon,
  ArrowRightIcon,
} from "@heroicons/react/24/outline";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";

interface Product {
  id: string;
  name: string;
  price: number;
  images: string;
}

const normalizeProductImages = (
  images: string | string[] | null | undefined,
): string[] => {
  if (!images) {
    return [];
  }

  if (Array.isArray(images)) {
    return images.filter(
      (image): image is string =>
        typeof image === "string" && image.trim().length > 0,
    );
  }

  const trimmedImages = images.trim();

  if (!trimmedImages) {
    return [];
  }

  if (trimmedImages.startsWith("[")) {
    try {
      const parsedImages = JSON.parse(trimmedImages);
      if (Array.isArray(parsedImages)) {
        return parsedImages.filter(
          (image): image is string =>
            typeof image === "string" && image.trim().length > 0,
        );
      }

      if (typeof parsedImages === "string" && parsedImages.trim().length > 0) {
        return [parsedImages.trim()];
      }

      return [];
    } catch {
      return [trimmedImages];
    }
  }

  return [trimmedImages];
};

const AffiliateMarketplace: React.FC = () => {
  const { formatPrice } = useCurrency();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const navigate = useNavigate();
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [importing, setImporting] = useState<string | null>(null);
  const [markup, setMarkup] = useState<{ [key: string]: number }>({});

  useEffect(() => {
    fetchMarketplace();
  }, []);

  const fetchMarketplace = async () => {
    try {
      setLoading(true);
      // For now, we use the general products API but with a marketplace flag or just unfiltered
      // In a real scenario, we might have a specific /marketplace endpoint
      const response = await apiClient.get(
        "/products?limit=50&marketplace=true",
      );
      if (response.data.success) {
        setProducts(response.data.data);
      }
    } catch (error) {
      toast.error("فشل جلب منتجات السوق");
    } finally {
      setLoading(false);
    }
  };

  const handleImport = async (productId: string) => {
    try {
      setImporting(productId);
      const profit = markup[productId] || 0;
      const response = await apiClient.post("/affiliates/products", {
        productId,
        markup: profit,
      });

      if (response.data.success) {
        toast.success("تم استيراد المنتج لكتالوجك بنجاح");
        // Optional: Remove from marketplace list or show imported status
      }
    } catch (error: any) {
      toast.error(
        error.response?.data?.message || "هذا المنتج موجود بالفعل في كتالوجك",
      );
    } finally {
      setImporting(null);
    }
  };

  const filteredProducts = products.filter((p) =>
    p.name.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  if (loading) {
    return (
      <div
        className={`flex items-center justify-center min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"}`}
      >
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div className="w-full">
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate("/affiliates/products")}
              className={`p-2 rounded-lg ${isDark ? "bg-gray-800 hover:bg-gray-700" : "bg-white hover:bg-gray-100"} transition-all`}
            >
              <ArrowRightIcon
                className={`h-5 w-5 ${isDark ? "text-white" : "text-gray-900"}`}
              />
            </button>
            <div>
              <h1
                className={`text-2xl font-bold ${isDark ? "text-white" : "text-gray-900"}`}
              >
                سوق المنتجات (Marketplace)
              </h1>
              <p
                className={`text-sm ${isDark ? "text-gray-400" : "text-gray-500"} mt-1`}
              >
                اكتشف منتجات الشركة وأضفها لكتالوجك الشخصي للبدء في التسويق.
              </p>
            </div>
          </div>

          <div className="relative w-full md:w-96">
            <MagnifyingGlassIcon className="absolute right-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
            <input
              type="text"
              placeholder="ابحث عن منتج لاستيراده..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className={`w-full pr-10 pl-4 py-3 rounded-xl border ${isDark ? "bg-gray-800 border-gray-700 text-white" : "bg-white border-gray-100 text-gray-900"} outline-none focus:ring-2 focus:ring-blue-500`}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {filteredProducts.map((product) => {
            const images = normalizeProductImages(product.images);
            const mainImage = images[0] || "/placeholder-product.png";

            return (
              <div
                key={product.id}
                className={`${isDark ? "bg-gray-800 border-gray-700" : "bg-white border-gray-100"} border rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-all group`}
              >
                <div className="h-40 overflow-hidden">
                  <img
                    src={mainImage}
                    alt={product.name}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                  />
                </div>
                <div className="p-4">
                  <h3
                    className={`font-bold mb-2 truncate ${isDark ? "text-white" : "text-gray-900"}`}
                  >
                    {product.name}
                  </h3>
                  <div className="flex justify-between items-center mb-4">
                    <span className="text-xs text-gray-500">سعر الجملة:</span>
                    <span
                      className={`text-sm font-bold ${isDark ? "text-blue-400" : "text-blue-600"}`}
                    >
                      {formatPrice(product.price)}
                    </span>
                  </div>

                  <div className="space-y-3">
                    <div className="flex flex-col gap-1">
                      <label className="text-[10px] text-gray-400">
                        حدد ربحك (جنيه):
                      </label>
                      <input
                        type="number"
                        placeholder="0.00"
                        onChange={(e) =>
                          setMarkup({
                            ...markup,
                            [product.id]: parseFloat(e.target.value),
                          })
                        }
                        className={`w-full px-3 py-2 rounded-lg border text-sm ${isDark ? "bg-gray-900 border-gray-700 text-white" : "bg-gray-50 border-gray-200"} outline-none focus:ring-2 focus:ring-blue-500`}
                      />
                    </div>

                    <button
                      onClick={() => handleImport(product.id)}
                      disabled={importing === product.id}
                      className={`w-full flex items-center justify-center gap-2 py-2 rounded-xl font-bold text-xs transition-all ${
                        importing === product.id
                          ? "bg-gray-700 text-gray-400"
                          : "bg-blue-600 text-white hover:bg-blue-700 shadow-md shadow-blue-500/20"
                      }`}
                    >
                      {importing === product.id ? (
                        <div className="h-4 w-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                      ) : (
                        <PlusCircleIcon className="h-4 w-4" />
                      )}
                      استيراد لكتالوجي
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {filteredProducts.length === 0 && (
          <div className="text-center py-20">
            <ShoppingBagIcon className="h-16 w-16 mx-auto mb-4 opacity-10" />
            <p className="text-gray-500">لا توجد منتجات مطابقة للبحث</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default AffiliateMarketplace;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import { useTheme } from "../../hooks/useTheme";
import {
  PlusIcon,
  EyeIcon,
  ShoppingBagIcon,
  FunnelIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";

interface Order {
  id: string;
  orderNumber: string;
  total: number;
  status: string;
  orderSource: string;
  createdAt: string;
  customer: {
    firstName: string;
    lastName: string;
    phone: string;
  };
  commissions: Array<{
    id: string;
    amount: number;
    status: string;
  }>;
}

const AffiliateOrders: React.FC = () => {
  const { formatPrice } = useCurrency();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    status: "",
    orderSource: "",
  });

  useEffect(() => {
    loadOrders();
  }, [filters]);

  const loadOrders = async () => {
    try {
      setLoading(true);
      const params: any = {};
      if (filters.status) params.status = filters.status;
      if (filters.orderSource) params.orderSource = filters.orderSource;

      const response = await apiClient.get("/affiliates/orders", { params });
      if (response.data.success) {
        setOrders(response.data.data);
      }
    } catch (error: any) {
      toast.error("حدث خطأ أثناء جلب الطلبات");
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const statusMap: Record<
      string,
      { label: string; lightClass: string; darkClass: string }
    > = {
      PENDING: {
        label: "معلق",
        lightClass: "bg-yellow-100 text-yellow-800",
        darkClass: "bg-yellow-900/50 text-yellow-300",
      },
      CONFIRMED: {
        label: "مؤكد",
        lightClass: "bg-blue-100 text-blue-800",
        darkClass: "bg-blue-900/50 text-blue-300",
      },
      DELIVERED: {
        label: "تم التسليم",
        lightClass: "bg-green-100 text-green-800",
        darkClass: "bg-green-900/50 text-green-300",
      },
      CANCELLED: {
        label: "ملغي",
        lightClass: "bg-red-100 text-red-800",
        darkClass: "bg-red-900/50 text-red-300",
      },
    };
    const statusInfo = statusMap[status] || {
      label: status,
      lightClass: "bg-gray-100 text-gray-800",
      darkClass: "bg-gray-700 text-gray-300",
    };
    return (
      <span
        className={`px-2 py-1 text-xs rounded-full ${isDark ? statusInfo.darkClass : statusInfo.lightClass}`}
      >
        {statusInfo.label}
      </span>
    );
  };

  const getSourceBadge = (source: string) => {
    const sourceMap: Record<
      string,
      { label: string; lightClass: string; darkClass: string }
    > = {
      AFFILIATE_REFERRAL: {
        label: "إحالة",
        lightClass: "bg-purple-100 text-purple-800",
        darkClass: "bg-purple-900/50 text-purple-300",
      },
      AFFILIATE_DIRECT: {
        label: "مباشر",
        lightClass: "bg-indigo-100 text-indigo-800",
        darkClass: "bg-indigo-900/50 text-indigo-300",
      },
      REGULAR: {
        label: "عادي",
        lightClass: "bg-gray-100 text-gray-800",
        darkClass: "bg-gray-700 text-gray-300",
      },
    };
    const sourceInfo = sourceMap[source] || {
      label: source,
      lightClass: "bg-gray-100 text-gray-800",
      darkClass: "bg-gray-700 text-gray-300",
    };
    return (
      <span
        className={`px-2 py-1 text-xs rounded-full ${isDark ? sourceInfo.darkClass : sourceInfo.lightClass}`}
      >
        {sourceInfo.label}
      </span>
    );
  };

  if (loading) {
    return (
      <div
        className={`flex items-center justify-center min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"}`}
      >
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div className="w-full">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1
              className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"}`}
            >
              طلباتي
            </h1>
            <p className={`${isDark ? "text-gray-300" : "text-gray-600"} mt-2`}>
              جميع الطلبات المرتبطة بك
            </p>
          </div>
          <button
            onClick={() => navigate("/affiliates/orders/create")}
            className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition"
          >
            <PlusIcon className="h-5 w-5" />
            إنشاء طلب جديد
          </button>
        </div>

        {/* Filters */}
        <div
          className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow p-4 mb-6`}
        >
          <div className="flex items-center gap-4">
            <FunnelIcon
              className={`h-5 w-5 ${isDark ? "text-gray-400" : "text-gray-500"}`}
            />
            <select
              value={filters.status}
              onChange={(e) =>
                setFilters({ ...filters, status: e.target.value })
              }
              className={`px-4 py-2 border rounded-lg ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
            >
              <option value="">جميع الحالات</option>
              <option value="PENDING">معلق</option>
              <option value="CONFIRMED">مؤكد</option>
              <option value="DELIVERED">تم التسليم</option>
              <option value="CANCELLED">ملغي</option>
            </select>

            <select
              value={filters.orderSource}
              onChange={(e) =>
                setFilters({ ...filters, orderSource: e.target.value })
              }
              className={`px-4 py-2 border rounded-lg ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
            >
              <option value="">جميع المصادر</option>
              <option value="AFFILIATE_REFERRAL">إحالة</option>
              <option value="AFFILIATE_DIRECT">مباشر</option>
            </select>
          </div>
        </div>

        {/* Orders Table */}
        <div
          className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow overflow-hidden`}
        >
          {orders.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className={isDark ? "bg-gray-700" : "bg-gray-50"}>
                  <tr>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      رقم الطلب
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      العميل
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      المبلغ
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      الحالة
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      المصدر
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      العمولة
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      التاريخ
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      إجراءات
                    </th>
                  </tr>
                </thead>
                <tbody
                  className={`${isDark ? "bg-gray-800 divide-gray-700" : "bg-white divide-gray-200"} divide-y`}
                >
                  {orders.map((order) => (
                    <tr
                      key={order.id}
                      className={
                        isDark ? "hover:bg-gray-700" : "hover:bg-gray-50"
                      }
                    >
                      <td
                        className={`px-6 py-4 whitespace-nowrap text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-900"}`}
                      >
                        {order.orderNumber}
                      </td>
                      <td
                        className={`px-6 py-4 whitespace-nowrap text-sm ${isDark ? "text-gray-300" : "text-gray-900"}`}
                      >
                        {order.customer?.firstName} {order.customer?.lastName}
                        <br />
                        <span
                          className={isDark ? "text-gray-500" : "text-gray-500"}
                        >
                          {order.customer?.phone}
                        </span>
                      </td>
                      <td
                        className={`px-6 py-4 whitespace-nowrap text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-900"}`}
                      >
                        {formatPrice(order.total)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        {getStatusBadge(order.status)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        {getSourceBadge(order.orderSource)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-green-600 font-medium">
                        {order.commissions && order.commissions.length > 0
                          ? formatPrice(order.commissions[0].amount)
                          : "-"}
                      </td>
                      <td
                        className={`px-6 py-4 whitespace-nowrap text-sm ${isDark ? "text-gray-400" : "text-gray-500"}`}
                      >
                        {new Date(order.createdAt).toLocaleDateString("ar-EG")}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <button
                          onClick={() => navigate(`/orders/${encodeURIComponent(String(order.id))}`)}
                          className="text-blue-600 hover:text-blue-800 flex items-center gap-1 transition"
                        >
                          <EyeIcon className="h-4 w-4" />
                          عرض
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="text-center py-12">
              <ShoppingBagIcon
                className={`h-12 w-12 mx-auto mb-4 ${isDark ? "text-gray-600" : "text-gray-400"}`}
              />
              <p className={isDark ? "text-gray-400" : "text-gray-500"}>
                لا توجد طلبات بعد
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AffiliateOrders;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import { useTheme } from "../../hooks/useTheme";
import { useNavigate } from "react-router-dom";
import { LinkIcon, ShoppingBagIcon } from "@heroicons/react/24/outline";
import toast from "react-hot-toast";

interface AffiliateProduct {
  id: string;
  productId: string;
  basePrice: number;
  markup: number;
  finalPrice: number;
  isActive: boolean;
  product: {
    id: string;
    name: string;
    images: string;
  };
}

const AffiliateProducts: React.FC = () => {
  const { formatPrice } = useCurrency();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const navigate = useNavigate();
  const [products, setProducts] = useState<AffiliateProduct[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadProducts();
  }, []);

  const loadProducts = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/affiliates/products");
      if (response.data.success) {
        setProducts(response.data.data);
      }
    } catch (error: any) {
      toast.error("حدث خطأ أثناء جلب المنتجات");
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateMarkup = async (productId: string, markup: number) => {
    try {
      const product = products.find((p) => p.productId === productId);
      if (!product) return;

      const response = await apiClient.put(
        `/affiliates/products/${product.id}`,
        { markup },
      );
      if (response.data.success) {
        toast.success("تم تحديث الهامش بنجاح");
        loadProducts();
      }
    } catch (error: any) {
      toast.error("حدث خطأ أثناء التحديث");
    }
  };

  const generateAffiliateLink = async (productId: string) => {
    try {
      // الحصول على كود المسوق من API
      const response = await apiClient.get("/affiliates/me");
      if (response.data.success && response.data.data) {
        const affiliateCode = response.data.data.affiliateCode;
        const baseUrl = window.location.origin;
        return `${baseUrl}/shop/products/${productId}?ref=${affiliateCode}`;
      }
    } catch (error) {
      console.error("Error getting affiliate code:", error);
    }
    const baseUrl = window.location.origin;
    return `${baseUrl}/shop/products/${productId}`;
  };

  if (loading) {
    return (
      <div
        className={`flex items-center justify-center min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"}`}
      >
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div className="w-full">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1
              className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"}`}
            >
              منتجاتي
            </h1>
            <p className={`${isDark ? "text-gray-300" : "text-gray-600"} mt-2`}>
              إدارة منتجاتك مع هامش الربح
            </p>
          </div>
          <button
            onClick={() => navigate("/affiliates/marketplace")}
            className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition font-bold shadow-lg shadow-blue-500/20"
          >
            <ShoppingBagIcon className="h-5 w-5" />
            تصفح السوق
          </button>
        </div>

        {/* Product Grid / Empty State */}
        {products.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {products.map((affiliateProduct) => {
              const images = affiliateProduct.product.images
                ? JSON.parse(affiliateProduct.product.images)
                : [];
              const mainImage = images[0] || "/placeholder-product.png";

              return (
                <div
                  key={affiliateProduct.id}
                  className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-xl shadow-sm border ${isDark ? "border-gray-700" : "border-gray-100"} overflow-hidden hover:shadow-md transition-all group`}
                >
                  <div className="relative h-48 overflow-hidden">
                    <img
                      src={mainImage}
                      alt={affiliateProduct.product.name}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                    />
                    <div className="absolute top-2 left-2">
                      <span className="px-2 py-1 bg-blue-600 text-white text-[10px] font-bold rounded-lg shadow-lg">
                        منتجي
                      </span>
                    </div>
                  </div>
                  <div className="p-4">
                    <h3
                      className={`font-bold mb-2 truncate ${isDark ? "text-white" : "text-gray-900"}`}
                    >
                      {affiliateProduct.product.name}
                    </h3>

                    <div className="space-y-2 mb-4">
                      <div className="flex justify-between text-xs">
                        <span className="text-gray-500">سعر المنصة:</span>
                        <span
                          className={`font-medium ${isDark ? "text-gray-300" : "text-gray-700"}`}
                        >
                          {formatPrice(affiliateProduct.basePrice)}
                        </span>
                      </div>
                      <div className="flex justify-between text-xs">
                        <span className="text-gray-500">هامش ربحك:</span>
                        <span className="font-bold text-green-500">
                          +{formatPrice(affiliateProduct.markup)}
                        </span>
                      </div>
                      <div
                        className={`flex justify-between text-sm font-bold border-t pt-2 ${isDark ? "border-gray-700" : "border-gray-100"}`}
                      >
                        <span
                          className={isDark ? "text-white" : "text-gray-900"}
                        >
                          السعر للعميل:
                        </span>
                        <span className="text-blue-500">
                          {formatPrice(affiliateProduct.finalPrice)}
                        </span>
                      </div>
                    </div>

                    <div className="flex gap-2 mb-4">
                      <input
                        type="number"
                        step="0.01"
                        min="0"
                        defaultValue={affiliateProduct.markup}
                        onBlur={(e) => {
                          const newMarkup = parseFloat(e.target.value);
                          if (newMarkup !== affiliateProduct.markup) {
                            handleUpdateMarkup(
                              affiliateProduct.productId,
                              newMarkup,
                            );
                          }
                        }}
                        className={`flex-1 px-3 py-2 border rounded-lg text-sm ${
                          isDark
                            ? "bg-gray-900 border-gray-700 text-white"
                            : "bg-gray-50 border-gray-200 text-gray-900"
                        } outline-none focus:ring-2 focus:ring-blue-500`}
                        placeholder="تعديل الربح"
                      />
                    </div>

                    <div className="flex gap-2">
                      <button
                        onClick={async () => {
                          const link = await generateAffiliateLink(
                            affiliateProduct.productId,
                          );
                          navigator.clipboard.writeText(link);
                          toast.success("تم نسخ الرابط!");
                        }}
                        className="flex-1 flex items-center justify-center gap-2 bg-blue-600 text-white px-3 py-2 rounded-lg hover:bg-blue-700 text-xs font-bold transition shadow-sm shadow-blue-500/20"
                      >
                        <LinkIcon className="h-4 w-4" />
                        نسخ الرابط
                      </button>
                      <button
                        onClick={() =>
                          navigate(
                            `/shop/products/${affiliateProduct.productId}`,
                          )
                        }
                        className={`px-3 py-2 border rounded-lg text-xs font-bold transition ${
                          isDark
                            ? "border-gray-700 text-gray-400 hover:bg-gray-700"
                            : "border-gray-200 text-gray-600 hover:bg-gray-50"
                        }`}
                      >
                        عرض
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div
            className={`text-center py-20 rounded-2xl border ${isDark ? "bg-gray-800 border-gray-700" : "bg-white border-gray-100"} shadow-sm`}
          >
            <ShoppingBagIcon
              className={`h-16 w-16 mx-auto mb-4 opacity-20 ${isDark ? "text-gray-400" : "text-gray-500"}`}
            />
            <p
              className={`mb-6 text-lg font-medium ${isDark ? "text-gray-400" : "text-gray-500"}`}
            >
              كتالوجك الشخصي فارغ تماماً
            </p>
            <button
              onClick={() => navigate("/affiliates/marketplace")}
              className="bg-blue-600 text-white px-8 py-3 rounded-xl hover:bg-blue-700 transition font-bold shadow-lg shadow-blue-500/30"
            >
              اكتشف المنتجات في السوق الآن
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default AffiliateProducts;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { useTheme } from "../../hooks/useTheme";
import { useTranslation } from "react-i18next";
import { useCurrency } from "../../hooks/useCurrency";
import { getCurrencyByCode } from "../../utils/currency";
import toast from "react-hot-toast";
import {
  CurrencyDollarIcon,
  MagnifyingGlassIcon,
  ArrowPathIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon,
  BoltIcon,
} from "@heroicons/react/24/outline";

interface Product {
  id: string;
  name: string;
  sku: string;
  price: string | number;
  cost: string | number;
  basePrice: string | number;
  affiliateCommission: string | number | null;
  commissionType: string | null;
  platformMarginType: "FIXED" | "PERCENTAGE";
  platformMarginValue: number;
  category?: { name: string };
}

const AffiliateQuickActions: React.FC = () => {
  const { actualTheme } = useTheme();
  const { t } = useTranslation();
  const { currency } = useCurrency();
  const isDark = actualTheme === "dark";

  const currencyInfo = getCurrencyByCode(currency || "EGP");
  const displayCurrency = currencyInfo?.symbol || "ج.م";

  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [pendingChanges, setPendingChanges] = useState<{
    [key: string]: Partial<Product>;
  }>({});

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/products");
      if (response.data.success) {
        setProducts(response.data.data);
      }
    } catch (error) {
      toast.error("حدث خطأ أثناء تحميل المنتجات");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (
    productId: string,
    field: keyof Product,
    value: any,
  ) => {
    setPendingChanges((prev) => {
      const currentProduct = products.find((p) => p.id === productId);
      if (!currentProduct) return prev;

      const updatedChanges = {
        ...(prev[productId] || {}),
        [field]: value,
      };

      // أتمتة حساب السعر الأساسي للمسوق عند تغيير سعر التاجر (cost)
      if (field === "cost") {
        const cost = Number(value);
        let platMargin = 0;
        if (currentProduct.platformMarginType === "FIXED") {
          platMargin = currentProduct.platformMarginValue;
        } else {
          platMargin = (cost * currentProduct.platformMarginValue) / 100;
        }
        const newBasePrice = cost + platMargin;
        updatedChanges.basePrice = Number(newBasePrice.toFixed(2));
      }

      return {
        ...prev,
        [productId]: updatedChanges,
      };
    });
  };

  const handleBulkSave = async () => {
    const changesCount = Object.keys(pendingChanges).length;
    if (changesCount === 0) return;

    try {
      setSaving(true);
      const updatePromises = Object.entries(pendingChanges).map(
        ([id, changes]) => apiClient.patch(`/products/${id}`, changes),
      );

      await Promise.all(updatePromises);
      toast.success(`تم تحديث ${changesCount} منتج بنجاح!`);
      setPendingChanges({});
      fetchProducts();
    } catch (error) {
      toast.error("حدث خطأ أثناء حفظ التعديلات");
    } finally {
      setSaving(false);
    }
  };

  const filteredProducts = products.filter(
    (p) =>
      p.name.toLowerCase().includes(search.toLowerCase()) ||
      (p.sku && p.sku.toLowerCase().includes(search.toLowerCase())),
  );

  return (
    <div
      className={`p-6 min-h-screen ${isDark ? "bg-gray-900 text-white" : "bg-gray-50 text-gray-900"}`}
    >
      <div className="w-full">
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2 text-indigo-500">
              <BoltIcon className="h-8 w-8" />
              الأكشن السريع: إدارة التسعير الثلاثي 🇪🇬
            </h1>
            <p className={`mt-1 ${isDark ? "text-gray-400" : "text-gray-600"}`}>
              إدارة أسعار التجار (التكلفة)، ربح المنصة، وعمولات المسوقين في مكان
              واحد.
            </p>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={fetchProducts}
              className={`p-2 rounded-lg border ${isDark ? "border-gray-700 hover:bg-gray-800" : "border-gray-300 hover:bg-gray-100"}`}
              title="تحديث البيانات"
            >
              <ArrowPathIcon
                className={`h-5 w-5 ${loading ? "animate-spin" : ""}`}
              />
            </button>
            <button
              onClick={handleBulkSave}
              disabled={Object.keys(pendingChanges).length === 0 || saving}
              className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 font-semibold shadow-lg shadow-indigo-500/20"
            >
              {saving
                ? "جاري الحفظ..."
                : `حفظ التغييرات (${Object.keys(pendingChanges).length})`}
              {!saving && <CheckCircleIcon className="h-5 w-5" />}
            </button>
          </div>
        </div>

        {/* Search Bar */}
        <div className={`mb-6 relative`}>
          <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
          <input
            type="text"
            placeholder="ابحث باسم المنتج أو الـ SKU..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className={`w-full pl-10 pr-4 py-3 rounded-xl border ${
              isDark
                ? "bg-gray-800 border-gray-700 focus:border-indigo-500"
                : "bg-white border-gray-300 focus:border-indigo-500"
            } outline-none transition-all shadow-sm`}
          />
        </div>

        {/* Triple Profit Table */}
        <div
          className={`overflow-x-auto rounded-xl border ${isDark ? "border-gray-700" : "border-gray-200"} shadow-sm`}
        >
          <table className="w-full text-right border-collapse">
            <thead
              className={`${isDark ? "bg-gray-800 text-gray-400" : "bg-gray-100 text-gray-600"}`}
            >
              <tr>
                <th className="px-4 py-4 font-semibold text-sm">المنتج</th>
                <th className="px-4 py-4 font-semibold text-sm">
                  سعر التاجر 🏗️
                </th>
                <th className="px-4 py-4 font-semibold text-sm">
                  ربح المنصة 🏢
                </th>
                <th className="px-4 py-4 font-semibold text-sm">
                  تكلفة المسوق 👤
                </th>
                <th className="px-4 py-4 font-semibold text-sm">
                  السعر النهائي 🏷️
                </th>
                <th className="px-4 py-4 font-semibold text-sm">ربح المسوق</th>
                <th className="px-4 py-4 font-semibold text-sm">
                  إجمالي التوزيع
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
              {filteredProducts.map((product) => {
                const changes = pendingChanges[product.id] || {};
                const currentCost =
                  changes.cost !== undefined ? changes.cost : product.cost;
                const currentBasePrice =
                  changes.basePrice !== undefined
                    ? changes.basePrice
                    : product.basePrice || product.price;
                const currentFinalPrice =
                  changes.price !== undefined ? changes.price : product.price;

                // حساب ربح المنصة الفعلي المعروض
                const platformProfit =
                  Number(currentBasePrice) - Number(currentCost);
                // حساب ربح المسوق الفعلي
                const affiliateProfit =
                  Number(currentFinalPrice) - Number(currentBasePrice);

                const isInvalid = platformProfit < 0 || affiliateProfit < 0;

                return (
                  <tr
                    key={product.id}
                    className={`${isDark ? "hover:bg-gray-800/50" : "hover:bg-gray-50"} transition-colors ${isInvalid ? "bg-red-50 dark:bg-red-900/10" : ""}`}
                  >
                    <td className="px-4 py-4">
                      <div className="font-medium text-sm">{product.name}</div>
                      <div className="text-xs text-gray-500 font-mono mt-0.5">
                        {product.sku || "N/A"}
                      </div>
                    </td>

                    {/* سعر التاجر - قابل للتعديل */}
                    <td className="px-4 py-4">
                      <div className="flex items-center gap-1">
                        <input
                          type="number"
                          value={currentCost || ""}
                          onChange={(e) =>
                            handleInputChange(
                              product.id,
                              "cost",
                              parseFloat(e.target.value),
                            )
                          }
                          className={`w-24 px-2 py-1.5 rounded-lg border text-sm font-mono ${
                            isDark
                              ? "bg-gray-800 border-gray-700"
                              : "bg-white border-gray-300"
                          }`}
                        />
                        <span className="text-[10px] text-gray-500">
                          {displayCurrency}
                        </span>
                      </div>
                    </td>

                    {/* ربح المنصة - عرض فقط (يتأثر بسعر التاجر تلقائياً) */}
                    <td className="px-4 py-4">
                      <div
                        className={`text-sm font-medium ${platformProfit < 0 ? "text-red-500" : "text-blue-500"}`}
                      >
                        +{platformProfit.toFixed(2)}
                        <span className="mr-1 text-[10px] text-gray-500">
                          {displayCurrency}
                        </span>
                      </div>
                      <div className="text-[9px] text-gray-400">
                        {product.platformMarginType === "FIXED"
                          ? "ثابت"
                          : `${product.platformMarginValue}%`}
                      </div>
                    </td>

                    {/* تكلفة المسوق (Base Price) - قابل للتعديل كاستثناء */}
                    <td className="px-4 py-4">
                      <div className="flex items-center gap-1">
                        <input
                          type="number"
                          value={currentBasePrice || ""}
                          onChange={(e) =>
                            handleInputChange(
                              product.id,
                              "basePrice",
                              parseFloat(e.target.value),
                            )
                          }
                          className={`w-24 px-2 py-1.5 rounded-lg border text-sm font-mono font-bold ${
                            isDark
                              ? "bg-blue-900/20 border-blue-700"
                              : "bg-blue-50 border-blue-200 text-blue-800"
                          }`}
                        />
                        <span className="text-[10px] text-gray-500">
                          {displayCurrency}
                        </span>
                      </div>
                    </td>

                    {/* السعر النهائي للجمهور - قابل للتعديل */}
                    <td className="px-4 py-4">
                      <div className="flex items-center gap-1">
                        <input
                          type="number"
                          value={currentFinalPrice || ""}
                          onChange={(e) =>
                            handleInputChange(
                              product.id,
                              "price",
                              parseFloat(e.target.value),
                            )
                          }
                          className={`w-24 px-2 py-1.5 rounded-lg border text-sm font-mono ${
                            isDark
                              ? "bg-gray-800 border-gray-700 text-indigo-400"
                              : "bg-white border-gray-300 text-indigo-600 font-bold"
                          }`}
                        />
                        <span className="text-[10px] text-gray-500">
                          {displayCurrency}
                        </span>
                      </div>
                    </td>

                    {/* ربح المسوق - عرض فقط */}
                    <td className="px-4 py-4">
                      <div
                        className={`text-sm font-bold ${affiliateProfit < 0 ? "text-red-500" : "text-green-500"}`}
                      >
                        {affiliateProfit.toFixed(2)}
                        <span className="mr-1 text-[10px] text-gray-500">
                          {displayCurrency}
                        </span>
                      </div>
                      {affiliateProfit < 0 && (
                        <div className="text-[9px] text-red-400 flex items-center gap-1">
                          <ExclamationTriangleIcon className="h-2 w-2" />
                          خسارة مسوق
                        </div>
                      )}
                    </td>

                    {/* الإجمالي */}
                    <td className="px-4 py-4">
                      <div className="flex flex-col text-[10px] text-gray-500">
                        <span className="flex justify-between">
                          التاجر: <span>{currentCost}</span>
                        </span>
                        <span className="flex justify-between">
                          المنصة: <span>{platformProfit.toFixed(2)}</span>
                        </span>
                        <span className="flex justify-between border-t border-gray-700/20 mt-1 pt-1 font-bold">
                          المنتج: <span>{currentBasePrice}</span>
                        </span>
                        <span className="flex justify-between text-green-500">
                          المسوق: <span>{affiliateProfit.toFixed(2)}</span>
                        </span>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {filteredProducts.length === 0 && !loading && (
          <div className="text-center py-20">
            <MagnifyingGlassIcon className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-500 font-medium">
              لم يتم العثور على منتجات تطابق بحثك.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default AffiliateQuickActions;

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import { useTheme } from "../../hooks/useTheme";
import toast from "react-hot-toast";

const AffiliateRegister: React.FC = () => {
  const navigate = useNavigate();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    commissionType: "PERCENTAGE" as "PERCENTAGE" | "MARKUP",
    commissionRate: 5.0,
    paymentMethod: "",
    paymentDetails: {
      bankAccount: "",
      phoneNumber: "",
      bankName: "",
    },
    minPayout: 100.0,
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      const response = await apiClient.post("/affiliates/register", formData);

      if (response.data.success) {
        toast.success("تم تسجيلك كمسوق بنجاح!");
        navigate("/affiliates/dashboard");
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "حدث خطأ أثناء التسجيل");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div
        className={`max-w-2xl mx-auto ${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow-lg p-8`}
      >
        <h1
          className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"} mb-2`}
        >
          تسجيل كمسوق
        </h1>
        <p className={`${isDark ? "text-gray-300" : "text-gray-600"} mb-6`}>
          انضم إلى برنامج المسوقين وابدأ في كسب العمولات من كل عملية بيع
        </p>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Commission Type */}
          <div>
            <label
              className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
            >
              نوع العمولة
            </label>
            <div className="grid grid-cols-2 gap-4">
              <label
                className={`border-2 rounded-lg p-4 cursor-pointer transition ${
                  formData.commissionType === "PERCENTAGE"
                    ? isDark
                      ? "border-blue-500 bg-blue-900/30"
                      : "border-blue-600 bg-blue-50"
                    : isDark
                      ? "border-gray-600 bg-gray-700"
                      : "border-gray-200"
                }`}
              >
                <input
                  type="radio"
                  name="commissionType"
                  value="PERCENTAGE"
                  checked={formData.commissionType === "PERCENTAGE"}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      commissionType: e.target.value as "PERCENTAGE",
                    })
                  }
                  className="mr-2"
                />
                <div>
                  <div
                    className={`font-semibold ${isDark ? "text-white" : "text-gray-900"}`}
                  >
                    نسبة مئوية
                  </div>
                  <div
                    className={`text-sm ${isDark ? "text-gray-400" : "text-gray-600"}`}
                  >
                    نسبة من السعر النهائي
                  </div>
                </div>
              </label>

              <label
                className={`border-2 rounded-lg p-4 cursor-pointer transition ${
                  formData.commissionType === "MARKUP"
                    ? isDark
                      ? "border-blue-500 bg-blue-900/30"
                      : "border-blue-600 bg-blue-50"
                    : isDark
                      ? "border-gray-600 bg-gray-700"
                      : "border-gray-200"
                }`}
              >
                <input
                  type="radio"
                  name="commissionType"
                  value="MARKUP"
                  checked={formData.commissionType === "MARKUP"}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      commissionType: e.target.value as "MARKUP",
                    })
                  }
                  className="mr-2"
                />
                <div>
                  <div
                    className={`font-semibold ${isDark ? "text-white" : "text-gray-900"}`}
                  >
                    هامش ربح
                  </div>
                  <div
                    className={`text-sm ${isDark ? "text-gray-400" : "text-gray-600"}`}
                  >
                    إضافة هامش على السعر الثابت
                  </div>
                </div>
              </label>
            </div>
          </div>

          {/* Commission Rate (for PERCENTAGE) */}
          {formData.commissionType === "PERCENTAGE" && (
            <div>
              <label
                className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
              >
                نسبة العمولة (%)
              </label>
              <input
                type="number"
                step="0.1"
                min="0"
                max="100"
                value={formData.commissionRate}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    commissionRate: parseFloat(e.target.value),
                  })
                }
                className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                  isDark
                    ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                    : "bg-white border-gray-300 text-gray-900"
                }`}
                required
              />
            </div>
          )}

          {/* Payment Method */}
          <div>
            <label
              className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
            >
              طريقة الدفع المفضلة
            </label>
            <select
              value={formData.paymentMethod}
              onChange={(e) =>
                setFormData({ ...formData, paymentMethod: e.target.value })
              }
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
            >
              <option value="">اختر طريقة الدفع</option>
              <option value="BANK_TRANSFER">تحويل بنكي</option>
              <option value="VODAFONE_CASH">فودافون كاش</option>
              <option value="ORANGE_CASH">أورنج كاش</option>
              <option value="INSTAPAY">إنستاباي</option>
            </select>
          </div>

          {/* Payment Details */}
          {formData.paymentMethod && (
            <div
              className={`space-y-4 p-4 rounded-lg ${isDark ? "bg-gray-700" : "bg-gray-50"}`}
            >
              <h3
                className={`font-semibold ${isDark ? "text-white" : "text-gray-900"}`}
              >
                تفاصيل الدفع
              </h3>

              {formData.paymentMethod === "BANK_TRANSFER" && (
                <>
                  <div>
                    <label
                      className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
                    >
                      اسم البنك
                    </label>
                    <input
                      type="text"
                      value={formData.paymentDetails.bankName}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          paymentDetails: {
                            ...formData.paymentDetails,
                            bankName: e.target.value,
                          },
                        })
                      }
                      className={`w-full px-4 py-2 border rounded-lg ${
                        isDark
                          ? "bg-gray-600 border-gray-500 text-white placeholder-gray-400"
                          : "bg-white border-gray-300 text-gray-900"
                      }`}
                    />
                  </div>
                  <div>
                    <label
                      className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
                    >
                      رقم الحساب
                    </label>
                    <input
                      type="text"
                      value={formData.paymentDetails.bankAccount}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          paymentDetails: {
                            ...formData.paymentDetails,
                            bankAccount: e.target.value,
                          },
                        })
                      }
                      className={`w-full px-4 py-2 border rounded-lg ${
                        isDark
                          ? "bg-gray-600 border-gray-500 text-white placeholder-gray-400"
                          : "bg-white border-gray-300 text-gray-900"
                      }`}
                    />
                  </div>
                </>
              )}

              {(formData.paymentMethod === "VODAFONE_CASH" ||
                formData.paymentMethod === "ORANGE_CASH") && (
                <div>
                  <label
                    className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
                  >
                    رقم المحفظة
                  </label>
                  <input
                    type="text"
                    value={formData.paymentDetails.phoneNumber}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        paymentDetails: {
                          ...formData.paymentDetails,
                          phoneNumber: e.target.value,
                        },
                      })
                    }
                    className={`w-full px-4 py-2 border rounded-lg ${
                      isDark
                        ? "bg-gray-600 border-gray-500 text-white placeholder-gray-400"
                        : "bg-white border-gray-300 text-gray-900"
                    }`}
                  />
                </div>
              )}
            </div>
          )}

          {/* Min Payout */}
          <div>
            <label
              className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
            >
              الحد الأدنى للسحب (جنيه)
            </label>
            <input
              type="number"
              step="0.01"
              min="0"
              value={formData.minPayout}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  minPayout: parseFloat(e.target.value),
                })
              }
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
              required
            />
          </div>

          {/* Terms */}
          <div
            className={`${isDark ? "bg-blue-900/30 border-blue-700" : "bg-blue-50 border-blue-200"} border rounded-lg p-4`}
          >
            <h3
              className={`font-semibold ${isDark ? "text-blue-300" : "text-blue-900"} mb-2`}
            >
              شروط وأحكام البرنامج
            </h3>
            <ul
              className={`text-sm space-y-1 list-disc list-inside ${isDark ? "text-blue-200" : "text-blue-800"}`}
            >
              <li>العمولات تُحسب فوراً عند استكمال الطلب</li>
              <li>يمكنك سحب الأرباح عند الوصول للحد الأدنى</li>
              <li>الدفع يتم خارج المنصة ويتم تسجيله بعد الدفع الفعلي</li>
              <li>يمكنك إنشاء طلبات لنفسك أو لعملاء آخرين</li>
            </ul>
          </div>

          {/* Submit Button */}
          <div className="flex gap-4">
            <button
              type="submit"
              disabled={loading}
              className="flex-1 bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? "جاري التسجيل..." : "تسجيل كمسوق"}
            </button>
            <button
              type="button"
              onClick={() => navigate(-1)}
              className={`px-6 py-3 border rounded-lg transition ${
                isDark
                  ? "border-gray-600 text-gray-300 hover:bg-gray-700"
                  : "border-gray-300 text-gray-700 hover:bg-gray-50"
              }`}
            >
              إلغاء
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AffiliateRegister;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import { useTheme } from "../../hooks/useTheme";
import { useAuth } from "../../hooks/useAuthSimple";
import { getBaseDomain } from "../../utils/storeUrl";
import toast from "react-hot-toast";
import {
  LinkIcon,
  ClipboardDocumentIcon,
  Cog6ToothIcon,
} from "@heroicons/react/24/outline";

const AffiliateSystemSettings: React.FC = () => {
  const navigate = useNavigate();
  const { actualTheme } = useTheme();
  const { user } = useAuth();
  const isDark = actualTheme === "dark";
  const [loading, setLoading] = useState(false);

  // Settings State
  const [settings, setSettings] = useState({
    commissionType: "PERCENTAGE",
    commissionRate: 5.0,
    cookieDuration: 30,
    termsAndConditions: "",
    isActive: true,
  });

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    try {
      const response = await apiClient.get("/affiliate-settings");
      if (response.data.success) {
        setSettings(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching affiliate settings:", error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      const response = await apiClient.put("/affiliate-settings", settings);

      if (response.data.success) {
        toast.success("تم تحديث إعدادات نظام المسوقين بنجاح!");
        setSettings(response.data.data);
      }
    } catch (error: any) {
      toast.error(
        error.response?.data?.message || "حدث خطأ أثناء حفظ الإعدادات",
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div
        className={`w-full ${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow-lg p-8`}
      >
        <div className="flex items-center mb-6">
          <div className="p-3 rounded-full bg-blue-100 dark:bg-blue-900/30 mr-4">
            <Cog6ToothIcon className="h-8 w-8 text-blue-600 dark:text-blue-400" />
          </div>
          <div>
            <h1
              className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"}`}
            >
              إعدادات نظام المسوقين
            </h1>
            <p className={`${isDark ? "text-gray-300" : "text-gray-600"} mt-1`}>
              تحكم في عمولات المسوقين، الشروط والأحكام، وروابط التسجيل
            </p>
          </div>
        </div>

        {/* Invitation Link Section */}
        {user?.company && (
          <div
            className={`mb-8 p-6 rounded-lg border ${isDark ? "bg-blue-900/20 border-blue-800" : "bg-blue-50 border-blue-200"}`}
          >
            <h3
              className={`text-lg font-semibold mb-3 flex items-center ${isDark ? "text-blue-300" : "text-blue-900"}`}
            >
              <LinkIcon className="h-6 w-6 mr-2" />
              رابط دعوة المسوقين
            </h3>

            {!user.company.slug ? (
              <div
                className={`text-sm p-3 rounded bg-amber-100 text-amber-800 border border-amber-200`}
              >
                ⚠️ برجاء إعداد "رابط الشركة" (Slug) في إعدادات الشركة لتمكين
                رابط الدعوة.
              </div>
            ) : (
              <>
                <p
                  className={`text-sm mb-4 ${isDark ? "text-gray-300" : "text-gray-600"}`}
                >
                  شارك هذا الرابط مع المسوقين ليقوموا بالتسجيل في برنامجك. عند
                  التسجيل، سيتم ربطهم بشركتك تلقائياً.
                </p>
                <div className="flex gap-2">
                  <input
                    type="text"
                    readOnly
                    value={(() => {
                      const baseDomain = getBaseDomain();
                      const protocol = window.location.protocol;
                      const slug = user.company!.slug;
                      if (!baseDomain.includes("localhost")) {
                        return `${protocol}//${slug}.${baseDomain}/affiliate-register`;
                      }
                      return `${protocol}//${baseDomain}/affiliate-register/${slug}`;
                    })()}
                    className={`flex-1 px-4 py-3 border rounded-lg text-sm font-mono ${
                      isDark
                        ? "bg-gray-800 border-gray-600 text-gray-300"
                        : "bg-white border-gray-300 text-gray-600"
                    }`}
                  />
                  <button
                    type="button"
                    onClick={() => {
                      const baseDomain = getBaseDomain();
                      const protocol = window.location.protocol;
                      const slug = user!.company!.slug;
                      const link = !baseDomain.includes("localhost")
                        ? `${protocol}//${slug}.${baseDomain}/affiliate-register`
                        : `${protocol}//${baseDomain}/affiliate-register/${slug}`;

                      navigator.clipboard.writeText(link);
                      toast.success("تم نسخ الرابط بنجاح");
                    }}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition flex items-center font-semibold"
                  >
                    <ClipboardDocumentIcon className="h-5 w-5 mr-2" />
                    نسخ
                  </button>
                </div>
              </>
            )}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Program Status */}
          <div
            className={`p-4 rounded-lg border ${isDark ? "border-gray-700 bg-gray-800/50" : "border-gray-200 bg-gray-50"}`}
          >
            <div className="flex items-center justify-between">
              <div>
                <h3
                  className={`font-semibold ${isDark ? "text-white" : "text-gray-900"}`}
                >
                  حالة النظام
                </h3>
                <p
                  className={`text-sm ${isDark ? "text-gray-400" : "text-gray-500"}`}
                >
                  تفعيل أو تعطيل تسجيل مسوقين جدد
                </p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  className="sr-only peer"
                  checked={settings.isActive}
                  onChange={(e) =>
                    setSettings({ ...settings, isActive: e.target.checked })
                  }
                />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 dark:peer-focus:ring-blue-800 rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-blue-600"></div>
              </label>
            </div>
          </div>

          {/* Commission Settings */}
          <div className="space-y-4">
            <h2
              className={`text-xl font-semibold border-b pb-2 ${isDark ? "text-white border-gray-700" : "text-gray-900 border-gray-200"}`}
            >
              إعدادات العمولة الافتراضية
            </h2>
            <p
              className={`text-sm ${isDark ? "text-gray-400" : "text-gray-500"}`}
            >
              هذه الإعدادات ستطبق تلقائياً على أي مسوق جديد يقوم بالتسجيل. يمكنك
              تعديل عمولة كل مسوق لاحقاً بشكل فردي.
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label
                  className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
                >
                  نوع العمولة للمسوق
                </label>
                <select
                  value={settings.commissionType}
                  onChange={(e) =>
                    setSettings({ ...settings, commissionType: e.target.value })
                  }
                  className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                    isDark
                      ? "bg-gray-700 border-gray-600 text-white"
                      : "bg-white border-gray-300 text-gray-900"
                  }`}
                >
                  <option value="PERCENTAGE">نسبة مئوية (%)</option>
                  <option value="MARKUP">هامش ربح ثابت</option>
                </select>
              </div>

              <div>
                <label
                  className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
                >
                  {settings.commissionType === "PERCENTAGE"
                    ? "النسبة للافتراضية للمسوق (%)"
                    : "المبلغ الثابت الافتراضي للمسوق"}
                </label>
                <input
                  type="number"
                  step="0.1"
                  min="0"
                  value={settings.commissionRate}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      commissionRate: parseFloat(e.target.value),
                    })
                  }
                  className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                    isDark
                      ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                      : "bg-white border-gray-300 text-gray-900"
                  }`}
                />
              </div>
            </div>

            <h2
              className={`text-xl font-semibold border-b pb-2 pt-6 ${isDark ? "text-white border-gray-700" : "text-gray-900 border-gray-200"}`}
            >
              هامش ربح المنصة (بين التاجر والمسوق)
            </h2>
            <p
              className={`text-sm ${isDark ? "text-gray-400" : "text-gray-500"}`}
            >
              هذا الهامش سيتم إضافته تلقائياً على سعر التاجر ليكون هو "سعر
              التكلفة" الذي يراه المسوق.
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label
                  className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
                >
                  نوع ربح المنصة
                </label>
                <select
                  value={(settings as any).platformMarginType || "FIXED"}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      platformMarginType: e.target.value,
                    } as any)
                  }
                  className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                    isDark
                      ? "bg-gray-700 border-gray-600 text-white"
                      : "bg-white border-gray-300 text-gray-900"
                  }`}
                >
                  <option value="FIXED">مبلغ ثابت لكل قطعة</option>
                  <option value="PERCENTAGE">
                    نسبة مئوية من سعر التاجر (%)
                  </option>
                </select>
              </div>

              <div>
                <label
                  className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
                >
                  قيمة ربح المنصة
                </label>
                <input
                  type="number"
                  step="0.1"
                  min="0"
                  value={(settings as any).platformMarginValue || 0}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      platformMarginValue: parseFloat(e.target.value),
                    } as any)
                  }
                  className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                    isDark
                      ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                      : "bg-white border-gray-300 text-gray-900"
                  }`}
                />
              </div>
            </div>

            <div>
              <label
                className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
              >
                مدة الكوكيز (أيام)
              </label>
              <input
                type="number"
                min="1"
                max="365"
                value={settings.cookieDuration}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    cookieDuration: parseInt(e.target.value),
                  })
                }
                className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                  isDark
                    ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                    : "bg-white border-gray-300 text-gray-900"
                }`}
              />
              <p
                className={`text-xs mt-1 ${isDark ? "text-gray-500" : "text-gray-500"}`}
              >
                الفترة التي يتم فيها احتساب العمولة للمسوق بعد زيارة العميل
                للرابط (الافتراضي 30 يوم).
              </p>
            </div>
          </div>

          {/* Terms and Conditions */}
          <div className="space-y-4">
            <h2
              className={`text-xl font-semibold border-b pb-2 ${isDark ? "text-white border-gray-700" : "text-gray-900 border-gray-200"}`}
            >
              الشروط والأحكام
            </h2>

            <div>
              <label
                className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
              >
                نص الشروط والأحكام
              </label>
              <textarea
                rows={6}
                value={settings.termsAndConditions}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    termsAndConditions: e.target.value,
                  })
                }
                placeholder="اكتب هنا الشروط التي يجب أن يوافق عليها المسوق عند التسجيل..."
                className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                  isDark
                    ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                    : "bg-white border-gray-300 text-gray-900"
                }`}
              />
              <p
                className={`text-xs mt-1 ${isDark ? "text-gray-500" : "text-gray-500"}`}
              >
                سيظهر هذا النص في صفحة تسجيل المسوقين.
              </p>
            </div>
          </div>

          {/* Submit Button */}
          <div className="flex gap-4 border-t pt-6">
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-bold"
            >
              {loading ? "جاري الحفظ..." : "حفظ الإعدادات"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AffiliateSystemSettings;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { useTheme } from "../../hooks/useTheme";
import toast from "react-hot-toast";
import {
  UserGroupIcon,
  CheckCircleIcon,
  XCircleIcon,
  PencilIcon,
  MagnifyingGlassIcon,
} from "@heroicons/react/24/outline";

interface Affiliate {
  id: string;
  userId: string;
  user: {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
  };
  status: "PENDING" | "ACTIVE" | "SUSPENDED";
  isActive: boolean;
  commissionType: "PERCENTAGE" | "MARKUP";
  commissionRate: number;
  totalEarnings: number;
  paidEarnings: number;
  pendingEarnings: number;
  totalSales: number;
  totalClicks: number;
  createdAt: string;
}

const AffiliatesManagement: React.FC = () => {
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const [affiliates, setAffiliates] = useState<Affiliate[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState<string>("ALL");
  const [editingCommission, setEditingCommission] = useState<string | null>(
    null,
  );
  const [newCommission, setNewCommission] = useState<number>(0);

  useEffect(() => {
    fetchAffiliates();
  }, []);

  const fetchAffiliates = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/affiliates/list");
      if (response.data.success) {
        setAffiliates(response.data.data);
      }
    } catch (error: any) {
      toast.error("فشل تحميل قائمة المسوقين");
    } finally {
      setLoading(false);
    }
  };

  const handleStatusUpdate = async (affiliateId: string, newStatus: string) => {
    try {
      const isActive = newStatus === "ACTIVE";
      const response = await apiClient.put(
        `/affiliates/${affiliateId}/status`,
        {
          isActive,
        },
      );
      if (response.data.success) {
        toast.success("تم تحديث حالة المسوق بنجاح");
        fetchAffiliates();
      }
    } catch (error: any) {
      toast.error("فشل تحديث حالة المسوق");
    }
  };

  const updateCommission = async (affiliateId: string) => {
    try {
      const response = await apiClient.put(
        `/affiliates/${affiliateId}/commission`,
        {
          commissionRate: newCommission,
        },
      );
      if (response.data.success) {
        toast.success("تم تحديث العمولة بنجاح");
        setEditingCommission(null);
        fetchAffiliates();
      }
    } catch (error: any) {
      toast.error("فشل تحديث العمولة");
    }
  };

  const getStatusStyle = (status: string) => {
    switch (status) {
      case "ACTIVE":
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400";
      case "PENDING":
        return "bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400";
      case "SUSPENDED":
        return "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400";
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300";
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case "ACTIVE":
        return "نشط";
      case "PENDING":
        return "قيد المراجعة";
      case "SUSPENDED":
        return "موقوف";
      default:
        return status;
    }
  };

  const filteredAffiliates = affiliates.filter((affiliate) => {
    const matchesSearch =
      affiliate.user.firstName
        .toLowerCase()
        .includes(searchTerm.toLowerCase()) ||
      affiliate.user.lastName
        .toLowerCase()
        .includes(searchTerm.toLowerCase()) ||
      affiliate.user.email.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesFilter =
      filterStatus === "ALL" || affiliate.status === filterStatus;

    return matchesSearch && matchesFilter;
  });

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div
      className={`p-6 ${isDark ? "bg-gray-900" : "bg-gray-50"} min-h-screen`}
    >
      <div className="w-full">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
          <div>
            <h1
              className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"} flex items-center`}
            >
              <UserGroupIcon className="h-9 w-9 ml-3 text-indigo-500" />
              إدارة شبكة المسوقين (Premium)
            </h1>
            <p className={`mt-2 ${isDark ? "text-gray-400" : "text-gray-600"}`}>
              تحكم كامل في المسوقين والعمولات والبيانات المالية.
            </p>
          </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div
            className={`p-6 rounded-2xl ${isDark ? "bg-gray-800" : "bg-white"} shadow-sm border ${isDark ? "border-gray-700" : "border-gray-100"}`}
          >
            <div className="text-sm text-gray-400 mb-1">الجمهور المستهدف</div>
            <div className="text-3xl font-bold text-indigo-500">
              {affiliates.length}
            </div>
            <div className="text-xs text-gray-500 mt-2">
              إجمالي المسوقين المسجلين
            </div>
          </div>
          <div
            className={`p-6 rounded-2xl ${isDark ? "bg-gray-800" : "bg-white"} shadow-sm border ${isDark ? "border-gray-700" : "border-gray-100"}`}
          >
            <div className="text-sm text-gray-400 mb-1">ينتظرون التفعيل</div>
            <div className="text-3xl font-bold text-orange-500">
              {affiliates.filter((a) => a.status === "PENDING").length}
            </div>
            <div className="text-xs text-gray-500 mt-2">
              طلبات تسجيل جديدة لم تراجع
            </div>
          </div>
          <div
            className={`p-6 rounded-2xl ${isDark ? "bg-gray-800" : "bg-white"} shadow-sm border ${isDark ? "border-gray-700" : "border-gray-100"}`}
          >
            <div className="text-sm text-gray-400 mb-1">إجمالي المبيعات</div>
            <div className="text-3xl font-bold text-green-500">
              {affiliates.reduce(
                (acc, curr) => acc + (curr.totalSales || 0),
                0,
              )}
            </div>
            <div className="text-xs text-gray-500 mt-2">
              إجمالي الطلبات المحققة
            </div>
          </div>
          <div
            className={`p-6 rounded-2xl ${isDark ? "bg-gray-800" : "bg-white"} shadow-sm border ${isDark ? "border-gray-700" : "border-gray-100"}`}
          >
            <div className="text-sm text-gray-400 mb-1">إجمالي العمولات</div>
            <div className="text-3xl font-bold text-blue-500">
              {affiliates
                .reduce(
                  (acc, curr) => acc + (Number(curr.totalEarnings) || 0),
                  0,
                )
                .toFixed(2)}
            </div>
            <div className="text-xs text-gray-500 mt-2">
              جنيه مصري مستحقة للمسوقين
            </div>
          </div>
        </div>

        {/* Filters Row */}
        <div className="flex flex-col md:flex-row gap-4 mb-6">
          <div className="flex-1 relative">
            <MagnifyingGlassIcon
              className={`absolute right-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400`}
            />
            <input
              type="text"
              placeholder="بحث بالاسم، البريد، أو الهاتف..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className={`w-full pr-10 pl-4 py-3 rounded-xl border ${
                isDark
                  ? "bg-gray-800 border-gray-700 text-white placeholder-gray-500"
                  : "bg-white border-gray-200 text-gray-900 shadow-sm"
              } outline-none focus:ring-2 focus:ring-indigo-500 transition-all`}
            />
          </div>
          <div className="flex gap-2">
            {["ALL", "PENDING", "ACTIVE", "SUSPENDED"].map((status) => (
              <button
                key={status}
                onClick={() => setFilterStatus(status)}
                className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                  filterStatus === status
                    ? "bg-indigo-600 text-white shadow-lg shadow-indigo-500/20"
                    : `${isDark ? "bg-gray-800 text-gray-400 border-gray-700" : "bg-white text-gray-600 border-gray-200"} border`
                }`}
              >
                {status === "ALL" ? "الكل" : getStatusLabel(status)}
              </button>
            ))}
          </div>
        </div>

        {/* Main Table */}
        <div
          className={`rounded-2xl border ${isDark ? "border-gray-700 bg-gray-800" : "border-gray-200 bg-white"} overflow-hidden shadow-sm`}
        >
          <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
            <thead className={isDark ? "bg-gray-900/50" : "bg-gray-50"}>
              <tr>
                <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">
                  المسوق
                </th>
                <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">
                  البيانات المالية
                </th>
                <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">
                  الأداء
                </th>
                <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">
                  العمولة اليدوية
                </th>
                <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">
                  الحالة
                </th>
                <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">
                  الإجراء
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
              {filteredAffiliates.map((affiliate) => (
                <tr
                  key={affiliate.id}
                  className={`${isDark ? "hover:bg-gray-700/30" : "hover:bg-gray-50/50"} transition-colors`}
                >
                  {/* المسوق */}
                  <td className="px-6 py-5">
                    <div className="flex flex-col">
                      <span
                        className={`font-bold ${isDark ? "text-white" : "text-gray-900"}`}
                      >
                        {affiliate.user.firstName} {affiliate.user.lastName}
                      </span>
                      <span className="text-xs text-gray-500 mt-1">
                        {affiliate.user.email}
                      </span>
                      <span className="text-[10px] text-indigo-500 mt-0.5">
                        {affiliate.user.phone || "بدون هاتف"}
                      </span>
                    </div>
                  </td>

                  {/* البيانات المالية */}
                  <td className="px-6 py-5">
                    <div className="flex flex-col gap-1">
                      <div className="flex justify-between text-xs max-w-[120px]">
                        <span className="text-gray-500">الإجمالي:</span>
                        <span
                          className={`font-bold ${isDark ? "text-gray-300" : "text-gray-700"}`}
                        >
                          {Number(affiliate.totalEarnings).toFixed(2)}
                        </span>
                      </div>
                      <div className="flex justify-between text-xs max-w-[120px]">
                        <span className="text-gray-500">المدفوع:</span>
                        <span className="text-green-500 font-bold">
                          {Number(affiliate.paidEarnings).toFixed(2)}
                        </span>
                      </div>
                      <div className="flex justify-between text-xs max-w-[120px]">
                        <span className="text-gray-500">المعلق:</span>
                        <span className="text-orange-500 font-bold">
                          {Number(affiliate.pendingEarnings).toFixed(2)}
                        </span>
                      </div>
                    </div>
                  </td>

                  {/* الأداء */}
                  <td className="px-6 py-5">
                    <div className="flex items-center gap-4">
                      <div className="flex flex-col text-center">
                        <span className="text-[10px] text-gray-400">
                          مبيعات
                        </span>
                        <span
                          className={`font-bold ${isDark ? "text-white" : "text-gray-900"}`}
                        >
                          {affiliate.totalSales}
                        </span>
                      </div>
                      <div className="w-[1px] h-6 bg-gray-700/20"></div>
                      <div className="flex flex-col text-center">
                        <span className="text-[10px] text-gray-400">نقرات</span>
                        <span
                          className={`font-bold ${isDark ? "text-white" : "text-gray-900"}`}
                        >
                          {affiliate.totalClicks}
                        </span>
                      </div>
                    </div>
                  </td>

                  {/* العمولة */}
                  <td className="px-6 py-5">
                    {editingCommission === affiliate.id ? (
                      <div className="flex items-center gap-1">
                        <input
                          type="number"
                          value={newCommission}
                          onChange={(e) =>
                            setNewCommission(parseFloat(e.target.value))
                          }
                          className={`w-16 px-2 py-1 rounded border text-xs ${isDark ? "bg-gray-700 border-gray-600" : "bg-white"}`}
                        />
                        <button
                          onClick={() => updateCommission(affiliate.id)}
                          className="p-1 text-green-500 hover:bg-green-500/10 rounded"
                        >
                          ✓
                        </button>
                        <button
                          onClick={() => setEditingCommission(null)}
                          className="p-1 text-red-500 hover:bg-red-500/10 rounded"
                        >
                          ✗
                        </button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2">
                        <span
                          className={`text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"}`}
                        >
                          {affiliate.commissionRate}%
                        </span>
                        <button
                          onClick={() => {
                            setEditingCommission(affiliate.id);
                            setNewCommission(affiliate.commissionRate);
                          }}
                          className="p-1 text-gray-400 hover:text-indigo-500 rounded-lg hover:bg-indigo-500/5 transition-all"
                        >
                          <PencilIcon className="h-3.5 w-3.5" />
                        </button>
                      </div>
                    )}
                  </td>

                  {/* الحالة */}
                  <td className="px-6 py-5">
                    <span
                      className={`px-3 py-1 text-[10px] font-bold rounded-full border ${getStatusStyle(affiliate.status)}`}
                    >
                      {getStatusLabel(affiliate.status)}
                    </span>
                  </td>

                  {/* الإجراءات */}
                  <td className="px-6 py-5">
                    <select
                      value={affiliate.status}
                      onChange={(e) =>
                        handleStatusUpdate(affiliate.id, e.target.value)
                      }
                      className={`text-xs px-2 py-1.5 rounded-lg border outline-none focus:ring-2 focus:ring-indigo-500 ${isDark ? "bg-gray-900 border-gray-700 text-gray-300" : "bg-white border-gray-200"}`}
                    >
                      <option value="PENDING">مراجعة الطلب</option>
                      <option value="ACTIVE">تفعيل المسوق</option>
                      <option value="SUSPENDED">إيقاف (Suspend)</option>
                    </select>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {filteredAffiliates.length === 0 && (
            <div
              className={`p-20 text-center flex flex-col items-center ${isDark ? "text-gray-500" : "text-gray-400"}`}
            >
              <UserGroupIcon className="h-12 w-12 mb-4 opacity-20" />
              <p className="font-medium">
                لم يتم العثور على أي مسوقين يطابقون خيارات البحث.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AffiliatesManagement;

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Typography,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Chip,
  Grid,
  Switch,
  FormControlLabel,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Alert,
  Snackbar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Tooltip,
  Tabs,
  Tab,
  CircularProgress,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Settings as SettingsIcon,
  PlayArrow as TestIcon,
  TrendingUp as StatsIcon,
  School as LearnIcon,
} from "@mui/icons-material";
import { companyAwareApi } from "../../services/companyAwareApi";

interface FewShotExample {
  id: string;
  customerMessage: string;
  aiResponse: string;
  category?: string;
  tags?: string[];
  priority: number;
  isActive: boolean;
  usageCount: number;
  lastUsedAt?: string;
  notes?: string;
  createdAt: string;
  updatedAt: string;
}

interface FewShotSettings {
  enabled: boolean;
  maxExamplesPerPrompt: number;
  selectionStrategy: "priority" | "random" | "category_match" | "smart";
  autoLearnFromGood: boolean;
  minQualityScore: number;
}

interface FewShotStats {
  totalExamples: number;
  activeExamples: number;
  inactiveExamples: number;
  enabled: boolean;
  maxExamplesPerPrompt: number;
  selectionStrategy: string;
  autoLearnEnabled: boolean;
  examplesByCategory: Array<{ category: string; count: number }>;
  mostUsedExamples: Array<{
    id: string;
    customerMessage: string;
    category: string;
    usageCount: number;
    priority: number;
  }>;
}

const FewShotManagement: React.FC = () => {
  const [activeTab, setActiveTab] = useState(0);
  const [examples, setExamples] = useState<FewShotExample[]>([]);
  const [settings, setSettings] = useState<FewShotSettings>({
    enabled: false,
    maxExamplesPerPrompt: 3,
    selectionStrategy: "priority",
    autoLearnFromGood: false,
    minQualityScore: 80,
  });
  const [stats, setStats] = useState<FewShotStats | null>(null);
  const [loading, setLoading] = useState(false);
  const [openDialog, setOpenDialog] = useState(false);
  const [openSettingsDialog, setOpenSettingsDialog] = useState(false);
  const [openTestDialog, setOpenTestDialog] = useState(false);
  const [editingExample, setEditingExample] = useState<FewShotExample | null>(
    null,
  );
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success" as "success" | "error",
  });

  const [formData, setFormData] = useState({
    customerMessage: "",
    aiResponse: "",
    category: "",
    tags: "",
    priority: 5,
    notes: "",
    isActive: true,
  });

  const [testData, setTestData] = useState({
    customerMessage: "",
    category: "",
  });

  const [testResult, setTestResult] = useState<any>(null);

  useEffect(() => {
    loadExamples();
    loadSettings();
    loadStats();
  }, []);

  const loadExamples = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/few-shot/examples");
      setExamples(response.data.data);
    } catch (error) {
      showSnackbar("فشل في تحميل الأمثلة", "error");
    } finally {
      setLoading(false);
    }
  };

  const loadSettings = async () => {
    try {
      const response = await companyAwareApi.get("/few-shot/settings");
      setSettings(response.data.data);
    } catch (error) {
      showSnackbar("فشل في تحميل الإعدادات", "error");
    }
  };

  const loadStats = async () => {
    try {
      const response = await companyAwareApi.get("/few-shot/stats");
      setStats(response.data.data);
    } catch (error) {
      console.error("Failed to load stats:", error);
    }
  };

  const handleSaveExample = async () => {
    try {
      const data = {
        ...formData,
        tags: formData.tags
          ? formData.tags.split(",").map((t) => t.trim())
          : [],
      };

      if (editingExample) {
        await companyAwareApi.put(
          `/few-shot/examples/${editingExample.id}`,
          data,
        );
        showSnackbar("تم تحديث المثال بنجاح", "success");
      } else {
        await companyAwareApi.post("/few-shot/examples", data);
        showSnackbar("تم إضافة المثال بنجاح", "success");
      }

      loadExamples();
      loadStats();
      handleCloseDialog();
    } catch (error) {
      showSnackbar("فشل في حفظ المثال", "error");
    }
  };

  const handleDeleteExample = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا المثال؟")) return;

    try {
      await companyAwareApi.delete(`/few-shot/examples/${id}`);
      showSnackbar("تم حذف المثال بنجاح", "success");
      loadExamples();
      loadStats();
    } catch (error) {
      showSnackbar("فشل في حذف المثال", "error");
    }
  };

  const handleSaveSettings = async () => {
    try {
      await companyAwareApi.put("/few-shot/settings", settings);
      showSnackbar("تم حفظ الإعدادات بنجاح", "success");
      setOpenSettingsDialog(false);
      loadStats();
    } catch (error) {
      showSnackbar("فشل في حفظ الإعدادات", "error");
    }
  };

  const handleTestPrompt = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.post("/few-shot/test", {
        customerMessage: testData.customerMessage,
        messageContext: { category: testData.category },
      });
      setTestResult(response.data.data);
    } catch (error) {
      showSnackbar("فشل في اختبار البرومبت", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (example?: FewShotExample) => {
    if (example) {
      setEditingExample(example);
      setFormData({
        customerMessage: example.customerMessage,
        aiResponse: example.aiResponse,
        category: example.category || "",
        tags: example.tags?.join(", ") || "",
        priority: example.priority,
        notes: example.notes || "",
        isActive: example.isActive,
      });
    } else {
      setEditingExample(null);
      setFormData({
        customerMessage: "",
        aiResponse: "",
        category: "",
        tags: "",
        priority: 5,
        notes: "",
        isActive: true,
      });
    }
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setEditingExample(null);
  };

  const showSnackbar = (message: string, severity: "success" | "error") => {
    setSnackbar({ open: true, message, severity });
  };

  const getCategoryColor = (category?: string) => {
    const colors: Record<string, string> = {
      pricing: "primary",
      shipping: "secondary",
      complaint: "error",
      product_info: "info",
      general: "default",
    };
    return colors[category || "general"] || "default";
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Typography variant="h4">🎓 نظام التعلم بالأمثلة</Typography>
        <Box>
          <Button
            variant="outlined"
            startIcon={<SettingsIcon />}
            onClick={() => setOpenSettingsDialog(true)}
            sx={{ mr: 1 }}
          >
            الإعدادات
          </Button>
          <Button
            variant="outlined"
            startIcon={<TestIcon />}
            onClick={() => setOpenTestDialog(true)}
            sx={{ mr: 1 }}
          >
            اختبار
          </Button>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => handleOpenDialog()}
          >
            إضافة مثال
          </Button>
        </Box>
      </Box>

      {stats && (
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  إجمالي الأمثلة
                </Typography>
                <Typography variant="h4">{stats.totalExamples}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  الأمثلة النشطة
                </Typography>
                <Typography variant="h4" color="success.main">
                  {stats.activeExamples}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  الحد الأقصى للأمثلة
                </Typography>
                <Typography variant="h4">
                  {stats.maxExamplesPerPrompt}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  الحالة
                </Typography>
                <Chip
                  label={stats.enabled ? "مفعّل" : "معطّل"}
                  color={stats.enabled ? "success" : "default"}
                  size="small"
                />
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      <Tabs
        value={activeTab}
        onChange={(e, v) => setActiveTab(v)}
        sx={{ mb: 2 }}
      >
        <Tab label="📚 الأمثلة" />
        <Tab label="📊 الإحصائيات" />
      </Tabs>

      {activeTab === 0 && (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>سؤال العميل</TableCell>
                <TableCell>رد الذكاء الاصطناعي</TableCell>
                <TableCell>التصنيف</TableCell>
                <TableCell>الأولوية</TableCell>
                <TableCell>الاستخدام</TableCell>
                <TableCell>الحالة</TableCell>
                <TableCell>الإجراءات</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={7} align="center">
                    <CircularProgress />
                  </TableCell>
                </TableRow>
              ) : examples.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} align="center">
                    <Typography color="textSecondary">لا توجد أمثلة</Typography>
                  </TableCell>
                </TableRow>
              ) : (
                examples.map((example) => (
                  <TableRow key={example.id}>
                    <TableCell>
                      <Tooltip title={example.customerMessage}>
                        <Typography noWrap sx={{ maxWidth: 200 }}>
                          {example.customerMessage}
                        </Typography>
                      </Tooltip>
                    </TableCell>
                    <TableCell>
                      <Tooltip title={example.aiResponse}>
                        <Typography noWrap sx={{ maxWidth: 250 }}>
                          {example.aiResponse}
                        </Typography>
                      </Tooltip>
                    </TableCell>
                    <TableCell>
                      {example.category && (
                        <Chip
                          label={example.category}
                          size="small"
                          color={getCategoryColor(example.category) as any}
                        />
                      )}
                    </TableCell>
                    <TableCell>
                      <Chip label={example.priority} size="small" />
                    </TableCell>
                    <TableCell>{example.usageCount}</TableCell>
                    <TableCell>
                      <Chip
                        label={example.isActive ? "نشط" : "معطل"}
                        size="small"
                        color={example.isActive ? "success" : "default"}
                      />
                    </TableCell>
                    <TableCell>
                      <IconButton
                        size="small"
                        onClick={() => handleOpenDialog(example)}
                      >
                        <EditIcon />
                      </IconButton>
                      <IconButton
                        size="small"
                        onClick={() => handleDeleteExample(example.id)}
                        color="error"
                      >
                        <DeleteIcon />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {activeTab === 1 && stats && (
        <Grid container spacing={3}>
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  الأمثلة حسب التصنيف
                </Typography>
                {stats.examplesByCategory.map((cat) => (
                  <Box key={cat.category} sx={{ mb: 1 }}>
                    <Typography variant="body2">
                      {cat.category}: {cat.count}
                    </Typography>
                  </Box>
                ))}
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  الأمثلة الأكثر استخداماً
                </Typography>
                {stats.mostUsedExamples.map((ex, idx) => (
                  <Box key={ex.id} sx={{ mb: 1 }}>
                    <Typography variant="body2">
                      {idx + 1}. {ex.customerMessage.substring(0, 50)}... (
                      {ex.usageCount} مرة)
                    </Typography>
                  </Box>
                ))}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {editingExample ? "✏️ تعديل المثال" : "➕ إضافة مثال جديد"}
        </DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="سؤال العميل"
            multiline
            rows={3}
            value={formData.customerMessage}
            onChange={(e) =>
              setFormData({ ...formData, customerMessage: e.target.value })
            }
            sx={{ mt: 2, mb: 2 }}
            required
          />
          <TextField
            fullWidth
            label="رد الذكاء الاصطناعي"
            multiline
            rows={4}
            value={formData.aiResponse}
            onChange={(e) =>
              setFormData({ ...formData, aiResponse: e.target.value })
            }
            sx={{ mb: 2 }}
            required
          />
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="التصنيف"
                value={formData.category}
                onChange={(e) =>
                  setFormData({ ...formData, category: e.target.value })
                }
                placeholder="pricing, shipping, complaint, etc."
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="الأولوية (0-10)"
                type="number"
                value={formData.priority}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    priority: parseInt(e.target.value),
                  })
                }
                inputProps={{ min: 0, max: 10 }}
              />
            </Grid>
          </Grid>
          <TextField
            fullWidth
            label="الوسوم (مفصولة بفاصلة)"
            value={formData.tags}
            onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
            sx={{ mt: 2, mb: 2 }}
            placeholder="tag1, tag2, tag3"
          />
          <TextField
            fullWidth
            label="ملاحظات"
            multiline
            rows={2}
            value={formData.notes}
            onChange={(e) =>
              setFormData({ ...formData, notes: e.target.value })
            }
            sx={{ mb: 2 }}
          />
          <FormControlLabel
            control={
              <Switch
                checked={formData.isActive}
                onChange={(e) =>
                  setFormData({ ...formData, isActive: e.target.checked })
                }
              />
            }
            label="نشط"
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>إلغاء</Button>
          <Button
            onClick={handleSaveExample}
            variant="contained"
            disabled={!formData.customerMessage || !formData.aiResponse}
          >
            حفظ
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={openSettingsDialog}
        onClose={() => setOpenSettingsDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>⚙️ إعدادات نظام التعلم بالأمثلة</DialogTitle>
        <DialogContent>
          <FormControlLabel
            control={
              <Switch
                checked={settings.enabled}
                onChange={(e) =>
                  setSettings({ ...settings, enabled: e.target.checked })
                }
              />
            }
            label="تفعيل نظام التعلم بالأمثلة"
            sx={{ mt: 2, mb: 2 }}
          />
          <TextField
            fullWidth
            label="الحد الأقصى للأمثلة في كل برومبت"
            type="number"
            value={settings.maxExamplesPerPrompt}
            onChange={(e) =>
              setSettings({
                ...settings,
                maxExamplesPerPrompt: parseInt(e.target.value),
              })
            }
            sx={{ mb: 2 }}
            inputProps={{ min: 1, max: 10 }}
          />
          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>استراتيجية الاختيار</InputLabel>
            <Select
              value={settings.selectionStrategy}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  selectionStrategy: e.target.value as any,
                })
              }
            >
              <MenuItem value="priority">حسب الأولوية</MenuItem>
              <MenuItem value="random">عشوائي</MenuItem>
              <MenuItem value="category_match">حسب التصنيف</MenuItem>
              <MenuItem value="smart">ذكي</MenuItem>
            </Select>
          </FormControl>
          <FormControlLabel
            control={
              <Switch
                checked={settings.autoLearnFromGood}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    autoLearnFromGood: e.target.checked,
                  })
                }
              />
            }
            label="التعلم التلقائي من الردود الجيدة"
            sx={{ mb: 2 }}
          />
          {settings.autoLearnFromGood && (
            <TextField
              fullWidth
              label="الحد الأدنى لجودة الرد (%)"
              type="number"
              value={settings.minQualityScore}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  minQualityScore: parseFloat(e.target.value),
                })
              }
              inputProps={{ min: 0, max: 100 }}
            />
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSettingsDialog(false)}>إلغاء</Button>
          <Button onClick={handleSaveSettings} variant="contained">
            حفظ
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={openTestDialog}
        onClose={() => setOpenTestDialog(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>🧪 اختبار نظام التعلم بالأمثلة</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="رسالة العميل"
            multiline
            rows={3}
            value={testData.customerMessage}
            onChange={(e) =>
              setTestData({ ...testData, customerMessage: e.target.value })
            }
            sx={{ mt: 2, mb: 2 }}
          />
          <TextField
            fullWidth
            label="التصنيف (اختياري)"
            value={testData.category}
            onChange={(e) =>
              setTestData({ ...testData, category: e.target.value })
            }
            sx={{ mb: 2 }}
          />
          <Button
            variant="contained"
            onClick={handleTestPrompt}
            disabled={!testData.customerMessage || loading}
            fullWidth
          >
            {loading ? <CircularProgress size={24} /> : "اختبار"}
          </Button>
          {testResult && (
            <Box sx={{ mt: 3 }}>
              <Alert severity="info" sx={{ mb: 2 }}>
                ✅ تم اختيار {testResult.examplesCount} أمثلة بنجاح
              </Alert>
              <Typography variant="subtitle2" gutterBottom>
                الأمثلة المختارة:
              </Typography>
              {testResult.selectedExamples.map((ex: any, idx: number) => (
                <Card key={idx} sx={{ mb: 1, p: 1 }}>
                  <Typography variant="caption" color="textSecondary">
                    العميل: {ex.customerMessage}
                  </Typography>
                  <Typography variant="caption" display="block">
                    الرد: {ex.aiResponse}
                  </Typography>
                </Card>
              ))}
              <Typography variant="subtitle2" gutterBottom sx={{ mt: 2 }}>
                البرومبت الكامل:
              </Typography>
              <Paper sx={{ p: 2, bgcolor: "grey.100" }}>
                <Typography
                  variant="body2"
                  sx={{ whiteSpace: "pre-wrap", fontFamily: "monospace" }}
                >
                  {testResult.prompt}
                </Typography>
              </Paper>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenTestDialog(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert
          severity={snackbar.severity}
          onClose={() => setSnackbar({ ...snackbar, open: false })}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default FewShotManagement;

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  Typography,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Chip,
  Grid,
  Switch,
  FormControlLabel,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Alert,
  Snackbar,
  CircularProgress,
  Avatar,
  Divider,
  Stack,
  Paper,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Settings as SettingsIcon,
  PlayArrow as TestIcon,
  Person as PersonIcon,
  SmartToy as BotIcon,
  TrendingUp as StatsIcon,
} from "@mui/icons-material";
import { companyAwareApi } from "../../services/companyAwareApi";

interface FewShotExample {
  id: string;
  customerMessage: string;
  aiResponse: string;
  category?: string;
  tags?: string[];
  priority: number;
  isActive: boolean;
  usageCount: number;
  lastUsedAt?: string;
  notes?: string;
  createdAt: string;
  updatedAt: string;
}

interface FewShotSettings {
  enabled: boolean;
  maxExamplesPerPrompt: number;
  selectionStrategy: "priority" | "random" | "category_match" | "smart";
  autoLearnFromGood: boolean;
  minQualityScore: number;
}

interface FewShotStats {
  totalExamples: number;
  activeExamples: number;
  inactiveExamples: number;
  enabled: boolean;
  maxExamplesPerPrompt: number;
  selectionStrategy: string;
  autoLearnEnabled: boolean;
  examplesByCategory: Array<{ category: string; count: number }>;
  mostUsedExamples: Array<{
    id: string;
    customerMessage: string;
    category: string;
    usageCount: number;
    priority: number;
  }>;
}

const FewShotManagementChat: React.FC = () => {
  const [examples, setExamples] = useState<FewShotExample[]>([]);
  const [settings, setSettings] = useState<FewShotSettings>({
    enabled: false,
    maxExamplesPerPrompt: 3,
    selectionStrategy: "priority",
    autoLearnFromGood: false,
    minQualityScore: 80,
  });
  const [stats, setStats] = useState<FewShotStats | null>(null);
  const [loading, setLoading] = useState(false);
  const [openDialog, setOpenDialog] = useState(false);
  const [openSettingsDialog, setOpenSettingsDialog] = useState(false);
  const [editingExample, setEditingExample] = useState<FewShotExample | null>(
    null,
  );
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success" as "success" | "error",
  });
  const [selectedExample, setSelectedExample] = useState<FewShotExample | null>(
    null,
  );

  const [formData, setFormData] = useState({
    customerMessage: "",
    aiResponse: "",
    category: "",
    tags: "",
    priority: 5,
    notes: "",
    isActive: true,
  });

  useEffect(() => {
    loadExamples();
    loadSettings();
    loadStats();
  }, []);

  const loadExamples = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/few-shot/examples");
      setExamples(response.data.data);
    } catch (error) {
      showSnackbar("فشل في تحميل الأمثلة", "error");
    } finally {
      setLoading(false);
    }
  };

  const loadSettings = async () => {
    try {
      const response = await companyAwareApi.get("/few-shot/settings");
      setSettings(response.data.data);
    } catch (error) {
      showSnackbar("فشل في تحميل الإعدادات", "error");
    }
  };

  const loadStats = async () => {
    try {
      const response = await companyAwareApi.get("/few-shot/stats");
      setStats(response.data.data);
    } catch (error) {
      console.error("Failed to load stats:", error);
    }
  };

  const handleSaveExample = async () => {
    try {
      const data = {
        ...formData,
        tags: formData.tags
          ? formData.tags.split(",").map((t) => t.trim())
          : [],
      };

      if (editingExample) {
        await companyAwareApi.put(
          `/few-shot/examples/${editingExample.id}`,
          data,
        );
        showSnackbar("تم تحديث المثال بنجاح", "success");
      } else {
        await companyAwareApi.post("/few-shot/examples", data);
        showSnackbar("تم إضافة المثال بنجاح", "success");
      }

      loadExamples();
      loadStats();
      handleCloseDialog();
    } catch (error) {
      showSnackbar("فشل في حفظ المثال", "error");
    }
  };

  const handleDeleteExample = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا المثال؟")) return;

    try {
      await companyAwareApi.delete(`/few-shot/examples/${id}`);
      showSnackbar("تم حذف المثال بنجاح", "success");
      loadExamples();
      loadStats();
      setSelectedExample(null);
    } catch (error) {
      showSnackbar("فشل في حذف المثال", "error");
    }
  };

  const handleSaveSettings = async () => {
    try {
      await companyAwareApi.put("/few-shot/settings", settings);
      showSnackbar("تم حفظ الإعدادات بنجاح", "success");
      setOpenSettingsDialog(false);
      loadStats();
    } catch (error) {
      showSnackbar("فشل في حفظ الإعدادات", "error");
    }
  };

  const handleOpenDialog = (example?: FewShotExample) => {
    if (example) {
      setEditingExample(example);
      setFormData({
        customerMessage: example.customerMessage,
        aiResponse: example.aiResponse,
        category: example.category || "",
        tags: example.tags?.join(", ") || "",
        priority: example.priority,
        notes: example.notes || "",
        isActive: example.isActive,
      });
    } else {
      setEditingExample(null);
      setFormData({
        customerMessage: "",
        aiResponse: "",
        category: "",
        tags: "",
        priority: 5,
        notes: "",
        isActive: true,
      });
    }
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setEditingExample(null);
  };

  const showSnackbar = (message: string, severity: "success" | "error") => {
    setSnackbar({ open: true, message, severity });
  };

  const getCategoryColor = (category?: string) => {
    const colors: Record<string, string> = {
      pricing: "#3b82f6",
      shipping: "#8b5cf6",
      complaint: "#ef4444",
      product_info: "#10b981",
      general: "#6b7280",
    };
    return colors[category || "general"] || "#6b7280";
  };

  const getCategoryLabel = (category?: string) => {
    const labels: Record<string, string> = {
      pricing: "الأسعار",
      shipping: "الشحن",
      complaint: "شكوى",
      product_info: "معلومات المنتج",
      general: "عام",
    };
    return labels[category || "general"] || "عام";
  };

  return (
    <Box sx={{ height: "100%", display: "flex", flexDirection: "column" }}>
      {/* Header */}
      <Box sx={{ p: 3, borderBottom: "1px solid #e5e7eb" }}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            mb: 2,
          }}
        >
          <Typography variant="h5" sx={{ fontWeight: 600 }}>
            🎓 نظام التعلم بالأمثلة
          </Typography>
          <Box>
            <Button
              variant="outlined"
              startIcon={<SettingsIcon />}
              onClick={() => setOpenSettingsDialog(true)}
              sx={{ mr: 1 }}
              size="small"
            >
              الإعدادات
            </Button>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => handleOpenDialog()}
              size="small"
            >
              إضافة مثال
            </Button>
          </Box>
        </Box>

        {/* Stats Cards */}
        {stats && (
          <Grid container spacing={2}>
            <Grid item xs={6} md={3}>
              <Paper sx={{ p: 2, textAlign: "center", bgcolor: "#f0f9ff" }}>
                <Typography
                  variant="h4"
                  sx={{ color: "#3b82f6", fontWeight: 700 }}
                >
                  {stats.totalExamples}
                </Typography>
                <Typography variant="caption" color="textSecondary">
                  إجمالي الأمثلة
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={6} md={3}>
              <Paper sx={{ p: 2, textAlign: "center", bgcolor: "#f0fdf4" }}>
                <Typography
                  variant="h4"
                  sx={{ color: "#10b981", fontWeight: 700 }}
                >
                  {stats.activeExamples}
                </Typography>
                <Typography variant="caption" color="textSecondary">
                  الأمثلة النشطة
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={6} md={3}>
              <Paper sx={{ p: 2, textAlign: "center", bgcolor: "#fef3c7" }}>
                <Typography
                  variant="h4"
                  sx={{ color: "#f59e0b", fontWeight: 700 }}
                >
                  {stats.maxExamplesPerPrompt}
                </Typography>
                <Typography variant="caption" color="textSecondary">
                  الحد الأقصى
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={6} md={3}>
              <Paper
                sx={{
                  p: 2,
                  textAlign: "center",
                  bgcolor: stats.enabled ? "#f0fdf4" : "#f3f4f6",
                }}
              >
                <Chip
                  label={stats.enabled ? "مفعّل" : "معطّل"}
                  color={stats.enabled ? "success" : "default"}
                  size="small"
                />
                <Typography
                  variant="caption"
                  color="textSecondary"
                  display="block"
                  sx={{ mt: 1 }}
                >
                  حالة النظام
                </Typography>
              </Paper>
            </Grid>
          </Grid>
        )}
      </Box>

      {/* Chat-like Examples List */}
      <Box sx={{ flex: 1, overflow: "auto", p: 3, bgcolor: "#f9fafb" }}>
        {loading ? (
          <Box sx={{ display: "flex", justifyContent: "center", py: 8 }}>
            <CircularProgress />
          </Box>
        ) : examples.length === 0 ? (
          <Box sx={{ textAlign: "center", py: 8 }}>
            <Typography color="textSecondary" gutterBottom>
              لا توجد أمثلة حتى الآن
            </Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => handleOpenDialog()}
              sx={{ mt: 2 }}
            >
              إضافة أول مثال
            </Button>
          </Box>
        ) : (
          <Stack spacing={3}>
            {examples.map((example) => (
              <Card
                key={example.id}
                sx={{
                  cursor: "pointer",
                  transition: "all 0.2s",
                  border:
                    selectedExample?.id === example.id
                      ? "2px solid #3b82f6"
                      : "1px solid #e5e7eb",
                  "&:hover": {
                    boxShadow: 3,
                    transform: "translateY(-2px)",
                  },
                }}
                onClick={() => setSelectedExample(example)}
              >
                <Box sx={{ p: 2 }}>
                  {/* Header with Category and Priority */}
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      mb: 2,
                    }}
                  >
                    <Box sx={{ display: "flex", gap: 1, alignItems: "center" }}>
                      {example.category && (
                        <Chip
                          label={getCategoryLabel(example.category)}
                          size="small"
                          sx={{
                            bgcolor: getCategoryColor(example.category),
                            color: "white",
                            fontWeight: 600,
                          }}
                        />
                      )}
                      <Chip
                        label={`أولوية: ${example.priority}`}
                        size="small"
                        variant="outlined"
                      />
                      <Chip
                        label={example.isActive ? "نشط" : "معطل"}
                        size="small"
                        color={example.isActive ? "success" : "default"}
                      />
                    </Box>
                    <Box>
                      <IconButton
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleOpenDialog(example);
                        }}
                      >
                        <EditIcon fontSize="small" />
                      </IconButton>
                      <IconButton
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDeleteExample(example.id);
                        }}
                        color="error"
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Box>
                  </Box>

                  {/* Customer Message */}
                  <Box sx={{ display: "flex", gap: 2, mb: 2 }}>
                    <Avatar sx={{ bgcolor: "#3b82f6", width: 36, height: 36 }}>
                      <PersonIcon />
                    </Avatar>
                    <Box sx={{ flex: 1 }}>
                      <Typography
                        variant="caption"
                        color="textSecondary"
                        sx={{ fontWeight: 600 }}
                      >
                        سؤال العميل
                      </Typography>
                      <Paper
                        sx={{
                          p: 2,
                          mt: 0.5,
                          bgcolor: "#eff6ff",
                          borderRadius: 2,
                        }}
                      >
                        <Typography variant="body2">
                          {example.customerMessage}
                        </Typography>
                      </Paper>
                    </Box>
                  </Box>

                  {/* AI Response */}
                  <Box sx={{ display: "flex", gap: 2 }}>
                    <Avatar sx={{ bgcolor: "#10b981", width: 36, height: 36 }}>
                      <BotIcon />
                    </Avatar>
                    <Box sx={{ flex: 1 }}>
                      <Typography
                        variant="caption"
                        color="textSecondary"
                        sx={{ fontWeight: 600 }}
                      >
                        رد الذكاء الاصطناعي
                      </Typography>
                      <Paper
                        sx={{
                          p: 2,
                          mt: 0.5,
                          bgcolor: "#f0fdf4",
                          borderRadius: 2,
                        }}
                      >
                        <Typography variant="body2">
