        fullWidth
      >
        <DialogTitle>
          {editingExample ? "✏️ تعديل المثال" : "➕ إضافة مثال جديد"}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ mt: 2 }}>
            <Typography
              variant="subtitle2"
              gutterBottom
              sx={{ display: "flex", alignItems: "center", gap: 1 }}
            >
              <PersonIcon fontSize="small" color="primary" />
              سؤال العميل
            </Typography>
            <TextField
              fullWidth
              multiline
              rows={3}
              value={formData.customerMessage}
              onChange={(e) =>
                setFormData({ ...formData, customerMessage: e.target.value })
              }
              placeholder="مثال: كم سعر المنتج؟"
              sx={{ mb: 3 }}
              required
            />

            <Typography
              variant="subtitle2"
              gutterBottom
              sx={{ display: "flex", alignItems: "center", gap: 1 }}
            >
              <BotIcon fontSize="small" color="success" />
              رد الذكاء الاصطناعي المثالي
            </Typography>
            <TextField
              fullWidth
              multiline
              rows={4}
              value={formData.aiResponse}
              onChange={(e) =>
                setFormData({ ...formData, aiResponse: e.target.value })
              }
              placeholder="مثال: سعر المنتج 299 جنيه، ويشمل الشحن المجاني 🎁"
              sx={{ mb: 3 }}
              required
            />

            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <FormControl fullWidth>
                  <InputLabel>التصنيف</InputLabel>
                  <Select
                    value={formData.category}
                    onChange={(e) =>
                      setFormData({ ...formData, category: e.target.value })
                    }
                    label="التصنيف"
                  >
                    <MenuItem value="">بدون تصنيف</MenuItem>
                    <MenuItem value="pricing">الأسعار</MenuItem>
                    <MenuItem value="shipping">الشحن</MenuItem>
                    <MenuItem value="complaint">شكوى</MenuItem>
                    <MenuItem value="product_info">معلومات المنتج</MenuItem>
                    <MenuItem value="general">عام</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label="الأولوية (0-10)"
                  type="number"
                  value={formData.priority}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      priority: parseInt(e.target.value),
                    })
                  }
                  inputProps={{ min: 0, max: 10 }}
                />
              </Grid>
            </Grid>

            <TextField
              fullWidth
              label="الوسوم (مفصولة بفاصلة)"
              value={formData.tags}
              onChange={(e) =>
                setFormData({ ...formData, tags: e.target.value })
              }
              sx={{ mt: 2, mb: 2 }}
              placeholder="سعر, خصم, عرض"
            />

            <TextField
              fullWidth
              label="ملاحظات"
              multiline
              rows={2}
              value={formData.notes}
              onChange={(e) =>
                setFormData({ ...formData, notes: e.target.value })
              }
              sx={{ mb: 2 }}
            />

            <FormControlLabel
              control={
                <Switch
                  checked={formData.isActive}
                  onChange={(e) =>
                    setFormData({ ...formData, isActive: e.target.checked })
                  }
                />
              }
              label="نشط"
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>إلغاء</Button>
          <Button
            onClick={handleSaveExample}
            variant="contained"
            disabled={!formData.customerMessage || !formData.aiResponse}
          >
            حفظ
          </Button>
        </DialogActions>
      </Dialog>

      {/* Settings Dialog */}
      <Dialog
        open={openSettingsDialog}
        onClose={() => setOpenSettingsDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>⚙️ إعدادات نظام التعلم بالأمثلة</DialogTitle>
        <DialogContent>
          <FormControlLabel
            control={
              <Switch
                checked={settings.enabled}
                onChange={(e) =>
                  setSettings({ ...settings, enabled: e.target.checked })
                }
              />
            }
            label="تفعيل نظام التعلم بالأمثلة"
            sx={{ mt: 2, mb: 2 }}
          />
          <TextField
            fullWidth
            label="الحد الأقصى للأمثلة في كل برومبت"
            type="number"
            value={settings.maxExamplesPerPrompt}
            onChange={(e) =>
              setSettings({
                ...settings,
                maxExamplesPerPrompt: parseInt(e.target.value),
              })
            }
            sx={{ mb: 2 }}
            inputProps={{ min: 1, max: 10 }}
          />
          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>استراتيجية الاختيار</InputLabel>
            <Select
              value={settings.selectionStrategy}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  selectionStrategy: e.target.value as any,
                })
              }
              label="استراتيجية الاختيار"
            >
              <MenuItem value="priority">حسب الأولوية</MenuItem>
              <MenuItem value="random">عشوائي</MenuItem>
              <MenuItem value="category_match">حسب التصنيف</MenuItem>
              <MenuItem value="smart">ذكي</MenuItem>
            </Select>
          </FormControl>
          <FormControlLabel
            control={
              <Switch
                checked={settings.autoLearnFromGood}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    autoLearnFromGood: e.target.checked,
                  })
                }
              />
            }
            label="التعلم التلقائي من الردود الجيدة"
            sx={{ mb: 2 }}
          />
          {settings.autoLearnFromGood && (
            <TextField
              fullWidth
              label="الحد الأدنى لجودة الرد (%)"
              type="number"
              value={settings.minQualityScore}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  minQualityScore: parseFloat(e.target.value),
                })
              }
              inputProps={{ min: 0, max: 100 }}
            />
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSettingsDialog(false)}>إلغاء</Button>
          <Button onClick={handleSaveSettings} variant="contained">
            حفظ
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert
          severity={snackbar.severity}
          onClose={() => setSnackbar({ ...snackbar, open: false })}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default FewShotManagementChat;

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  TextField,
  IconButton,
  Avatar,
  Paper,
  Typography,
  CircularProgress,
  Snackbar,
  Alert,
  Chip,
  Switch,
  FormControlLabel,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from "@mui/material";
import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Person as PersonIcon,
  SmartToy as BotIcon,
  Settings as SettingsIcon,
} from "@mui/icons-material";
import { companyAwareApi } from "../../services/companyAwareApi";

interface FewShotExample {
  id: string;
  customerMessage: string;
  aiResponse: string;
  isActive: boolean;
  usageCount: number;
  createdAt: string;
}

const FewShotSimple: React.FC = () => {
  const [examples, setExamples] = useState<FewShotExample[]>([]);
  const [loading, setLoading] = useState(false);
  const [customerMessage, setCustomerMessage] = useState("");
  const [aiResponse, setAiResponse] = useState("");
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success" as "success" | "error",
  });
  const [systemEnabled, setSystemEnabled] = useState(false);
  const [openSettings, setOpenSettings] = useState(false);

  useEffect(() => {
    loadExamples();
    loadSettings();
  }, []);

  const loadExamples = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/few-shot/examples");
      setExamples(response.data.data);
    } catch (error) {
      showSnackbar("فشل في تحميل الأمثلة", "error");
    } finally {
      setLoading(false);
    }
  };

  const loadSettings = async () => {
    try {
      const response = await companyAwareApi.get("/few-shot/settings");
      setSystemEnabled(response.data.data.enabled);
    } catch (error) {
      console.error("Failed to load settings:", error);
    }
  };

  const handleAdd = async () => {
    if (!customerMessage.trim() || !aiResponse.trim()) {
      showSnackbar("يرجى كتابة السؤال والرد", "error");
      return;
    }

    try {
      await companyAwareApi.post("/few-shot/examples", {
        customerMessage: customerMessage.trim(),
        aiResponse: aiResponse.trim(),
        priority: 5,
        isActive: true,
      });

      showSnackbar("تم إضافة المثال بنجاح ✅", "success");
      setCustomerMessage("");
      setAiResponse("");
      loadExamples();
    } catch (error) {
      showSnackbar("فشل في إضافة المثال", "error");
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل تريد حذف هذا المثال؟")) return;

    try {
      await companyAwareApi.delete(`/few-shot/examples/${id}`);
      showSnackbar("تم الحذف بنجاح", "success");
      loadExamples();
    } catch (error) {
      showSnackbar("فشل في الحذف", "error");
    }
  };

  const handleToggleSystem = async () => {
    try {
      await companyAwareApi.put("/few-shot/settings", {
        enabled: !systemEnabled,
        maxExamplesPerPrompt: 3,
        selectionStrategy: "priority",
        autoLearnFromGood: false,
        minQualityScore: 80,
      });
      setSystemEnabled(!systemEnabled);
      showSnackbar(
        systemEnabled ? "تم تعطيل النظام" : "تم تفعيل النظام ✅",
        "success",
      );
      setOpenSettings(false);
    } catch (error) {
      showSnackbar("فشل في تحديث الإعدادات", "error");
    }
  };

  const showSnackbar = (message: string, severity: "success" | "error") => {
    setSnackbar({ open: true, message, severity });
  };

  return (
    <Box
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        bgcolor: "#f9fafb",
      }}
    >
      {/* Header */}
      <Box sx={{ p: 3, bgcolor: "white", borderBottom: "2px solid #e5e7eb" }}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            mb: 2,
          }}
        >
          <Typography variant="h5" sx={{ fontWeight: 700, color: "#1f2937" }}>
            🎓 التعلم بالأمثلة
          </Typography>
          <Button
            variant="outlined"
            size="small"
            startIcon={<SettingsIcon />}
            onClick={() => setOpenSettings(true)}
          >
            الإعدادات
          </Button>
        </Box>

        <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 2 }}>
          <Chip
            label={systemEnabled ? "✅ مفعّل" : "⭕ معطّل"}
            color={systemEnabled ? "success" : "default"}
            size="small"
          />
          <Typography variant="caption" color="textSecondary">
            {examples.length} مثال
          </Typography>
        </Box>

        {/* Add New Example Form */}
        <Paper sx={{ p: 3, bgcolor: "#f0f9ff", border: "2px dashed #3b82f6" }}>
          <Box sx={{ display: "flex", gap: 2, mb: 2 }}>
            <Avatar sx={{ bgcolor: "#3b82f6", width: 40, height: 40 }}>
              <PersonIcon />
            </Avatar>
            <TextField
              fullWidth
              placeholder="اكتب سؤال العميل هنا..."
              value={customerMessage}
              onChange={(e) => setCustomerMessage(e.target.value)}
              multiline
              rows={2}
              variant="outlined"
              sx={{ bgcolor: "white" }}
            />
          </Box>

          <Box sx={{ display: "flex", gap: 2, mb: 2 }}>
            <Avatar sx={{ bgcolor: "#10b981", width: 40, height: 40 }}>
              <BotIcon />
            </Avatar>
            <TextField
              fullWidth
              placeholder="اكتب رد البوت المثالي هنا..."
              value={aiResponse}
              onChange={(e) => setAiResponse(e.target.value)}
              multiline
              rows={3}
              variant="outlined"
              sx={{ bgcolor: "white" }}
            />
          </Box>

          <Box sx={{ display: "flex", justifyContent: "flex-end" }}>
            <Button
              variant="contained"
              size="large"
              startIcon={<AddIcon />}
              onClick={handleAdd}
              disabled={!customerMessage.trim() || !aiResponse.trim()}
              sx={{
                bgcolor: "#3b82f6",
                "&:hover": { bgcolor: "#2563eb" },
                px: 4,
                py: 1.5,
                fontSize: "1rem",
                fontWeight: 600,
              }}
            >
              إضافة المثال
            </Button>
          </Box>
        </Paper>
      </Box>

      {/* Examples List */}
      <Box sx={{ flex: 1, overflow: "auto", p: 3 }}>
        {loading ? (
          <Box sx={{ display: "flex", justifyContent: "center", py: 8 }}>
            <CircularProgress />
          </Box>
        ) : examples.length === 0 ? (
          <Box sx={{ textAlign: "center", py: 8 }}>
            <Typography variant="h6" color="textSecondary" gutterBottom>
              لا توجد أمثلة بعد
            </Typography>
            <Typography variant="body2" color="textSecondary">
              ابدأ بإضافة أول مثال في الأعلى ⬆️
            </Typography>
          </Box>
        ) : (
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
            {examples.map((example, index) => (
              <Paper
                key={example.id}
                sx={{
                  p: 3,
                  position: "relative",
                  border: "1px solid #e5e7eb",
                  "&:hover": {
                    boxShadow: 3,
                    borderColor: "#3b82f6",
                  },
                }}
              >
                {/* Delete Button */}
                <IconButton
                  size="small"
                  onClick={() => handleDelete(example.id)}
                  sx={{
                    position: "absolute",
                    top: 8,
                    right: 8,
                    color: "#ef4444",
                  }}
                >
                  <DeleteIcon />
                </IconButton>

                {/* Example Number */}
                <Chip
                  label={`مثال ${index + 1}`}
                  size="small"
                  sx={{ mb: 2, bgcolor: "#f3f4f6", fontWeight: 600 }}
                />

                {/* Customer Message */}
                <Box sx={{ display: "flex", gap: 2, mb: 2 }}>
                  <Avatar sx={{ bgcolor: "#3b82f6", width: 36, height: 36 }}>
                    <PersonIcon fontSize="small" />
                  </Avatar>
                  <Box sx={{ flex: 1 }}>
                    <Typography
                      variant="caption"
                      sx={{
                        color: "#6b7280",
                        fontWeight: 600,
                        display: "block",
                        mb: 0.5,
                      }}
                    >
                      سؤال العميل
                    </Typography>
                    <Paper
                      sx={{
                        p: 2,
                        bgcolor: "#eff6ff",
                        border: "1px solid #bfdbfe",
                      }}
                    >
                      <Typography variant="body2" sx={{ color: "#1e40af" }}>
                        {example.customerMessage}
                      </Typography>
                    </Paper>
                  </Box>
                </Box>

                {/* AI Response */}
                <Box sx={{ display: "flex", gap: 2 }}>
                  <Avatar sx={{ bgcolor: "#10b981", width: 36, height: 36 }}>
                    <BotIcon fontSize="small" />
                  </Avatar>
                  <Box sx={{ flex: 1 }}>
                    <Typography
                      variant="caption"
                      sx={{
                        color: "#6b7280",
                        fontWeight: 600,
                        display: "block",
                        mb: 0.5,
                      }}
                    >
                      رد البوت
                    </Typography>
                    <Paper
                      sx={{
                        p: 2,
                        bgcolor: "#f0fdf4",
                        border: "1px solid #bbf7d0",
                      }}
                    >
                      <Typography variant="body2" sx={{ color: "#065f46" }}>
                        {example.aiResponse}
                      </Typography>
                    </Paper>
                  </Box>
                </Box>

                {/* Stats */}
                <Box
                  sx={{
                    display: "flex",
                    gap: 2,
                    mt: 2,
                    pt: 2,
                    borderTop: "1px solid #e5e7eb",
                  }}
                >
                  <Typography variant="caption" color="textSecondary">
                    📊 استُخدم {example.usageCount} مرة
                  </Typography>
                  <Typography variant="caption" color="textSecondary">
                    📅 {new Date(example.createdAt).toLocaleDateString("ar-EG")}
                  </Typography>
                </Box>
              </Paper>
            ))}
          </Box>
        )}
      </Box>

      {/* Settings Dialog */}
      <Dialog
        open={openSettings}
        onClose={() => setOpenSettings(false)}
        maxWidth="xs"
        fullWidth
      >
        <DialogTitle>⚙️ إعدادات النظام</DialogTitle>
        <DialogContent>
          <FormControlLabel
            control={
              <Switch
                checked={systemEnabled}
                onChange={handleToggleSystem}
                color="success"
              />
            }
            label={
              <Box>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  {systemEnabled ? "تعطيل النظام" : "تفعيل النظام"}
                </Typography>
                <Typography variant="caption" color="textSecondary">
                  {systemEnabled
                    ? "النظام مفعّل حالياً ويستخدم الأمثلة في الردود"
                    : "النظام معطّل حالياً"}
                </Typography>
              </Box>
            }
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSettings(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert
          severity={snackbar.severity}
          onClose={() => setSnackbar({ ...snackbar, open: false })}
          sx={{ width: "100%" }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

