import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  TextField,
  IconButton,
  Avatar,
  Paper,
  Typography,
  CircularProgress,
  Snackbar,
  Alert,
  Chip,
  Switch,
  FormControlLabel,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Collapse,
} from "@mui/material";
import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Person as PersonIcon,
  SmartToy as BotIcon,
  Settings as SettingsIcon,
  Info as InfoIcon,
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
} from "@mui/icons-material";
import { companyAwareApi } from "../../services/companyAwareApi";

interface FewShotExample {
  id: string;
  customerMessage: string;
  aiResponse: string;
  isActive: boolean;
  usageCount: number;
  createdAt: string;
}

const FewShotSimpleEnhanced: React.FC = () => {
  const [examples, setExamples] = useState<FewShotExample[]>([]);
  const [loading, setLoading] = useState(false);
  const [customerMessages, setCustomerMessages] = useState<string[]>([""]);
  const [aiResponses, setAiResponses] = useState<string[]>([""]);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success" as "success" | "error",
  });
  const [systemEnabled, setSystemEnabled] = useState(false);
  const [openSettings, setOpenSettings] = useState(false);
  const [showInstructions, setShowInstructions] = useState(true);

  useEffect(() => {
    loadExamples();
    loadSettings();
  }, []);

  const loadExamples = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/few-shot/examples");
      setExamples(response.data.data);
    } catch (error) {
      showSnackbar("فشل في تحميل الأمثلة", "error");
    } finally {
      setLoading(false);
    }
  };

  const loadSettings = async () => {
    try {
      const response = await companyAwareApi.get("/few-shot/settings");
      setSystemEnabled(response.data.data.enabled);
    } catch (error) {
      console.error("Failed to load settings:", error);
    }
  };

  const handleAddCustomerMessage = () => {
    setCustomerMessages([...customerMessages, ""]);
  };

  const handleAddAiResponse = () => {
    setAiResponses([...aiResponses, ""]);
  };

  const handleRemoveCustomerMessage = (index: number) => {
    if (customerMessages.length > 1) {
      setCustomerMessages(customerMessages.filter((_, i) => i !== index));
    }
  };

  const handleRemoveAiResponse = (index: number) => {
    if (aiResponses.length > 1) {
      setAiResponses(aiResponses.filter((_, i) => i !== index));
    }
  };

  const handleAdd = async () => {
    const validCustomerMessages = customerMessages.filter((msg) => msg.trim());
    const validAiResponses = aiResponses.filter((resp) => resp.trim());

    if (validCustomerMessages.length === 0 || validAiResponses.length === 0) {
      showSnackbar(
        "يرجى كتابة سؤال واحد على الأقل ورد واحد على الأقل",
        "error",
      );
      return;
    }

    try {
      // إضافة كل تركيبة ممكنة من الأسئلة والردود
      const promises = [];
      for (const customerMsg of validCustomerMessages) {
        for (const aiResp of validAiResponses) {
          promises.push(
            companyAwareApi.post("/few-shot/examples", {
              customerMessage: customerMsg.trim(),
              aiResponse: aiResp.trim(),
              priority: 5,
              isActive: true,
            }),
          );
        }
      }

      await Promise.all(promises);

      const totalAdded = validCustomerMessages.length * validAiResponses.length;
      showSnackbar(`تم إضافة ${totalAdded} مثال بنجاح ✅`, "success");

      // إعادة تعيين النماذج
      setCustomerMessages([""]);
      setAiResponses([""]);
      loadExamples();
    } catch (error) {
      showSnackbar("فشل في إضافة الأمثلة", "error");
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل تريد حذف هذا المثال؟")) return;

    try {
      await companyAwareApi.delete(`/few-shot/examples/${id}`);
      showSnackbar("تم الحذف بنجاح", "success");
      loadExamples();
    } catch (error) {
      showSnackbar("فشل في الحذف", "error");
    }
  };

  const handleToggleSystem = async () => {
    try {
      await companyAwareApi.put("/few-shot/settings", {
        enabled: !systemEnabled,
        maxExamplesPerPrompt: 3,
        selectionStrategy: "priority",
        autoLearnFromGood: false,
        minQualityScore: 80,
      });
      setSystemEnabled(!systemEnabled);
      showSnackbar(
        systemEnabled ? "تم تعطيل النظام" : "تم تفعيل النظام ✅",
        "success",
      );
      setOpenSettings(false);
    } catch (error) {
      showSnackbar("فشل في تحديث الإعدادات", "error");
    }
  };

  const showSnackbar = (message: string, severity: "success" | "error") => {
    setSnackbar({ open: true, message, severity });
  };

  return (
    <Box
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "row",
        gap: 2,
        bgcolor: "#f9fafb",
        p: 2,
      }}
    >
      {/* Left Side - Add Form */}
      <Box
        sx={{ width: "45%", display: "flex", flexDirection: "column", gap: 2 }}
      >
        {/* Header */}
        <Box sx={{ p: 2, bgcolor: "white", borderRadius: 2, boxShadow: 1 }}>
          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              mb: 2,
            }}
          >
            <Typography variant="h5" sx={{ fontWeight: 700, color: "#1f2937" }}>
              🎓 التعلم بالأمثلة
            </Typography>
            <Button
              variant="outlined"
              size="small"
              startIcon={<SettingsIcon />}
              onClick={() => setOpenSettings(true)}
            >
              الإعدادات
            </Button>
          </Box>

          <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 2 }}>
            <Chip
              label={systemEnabled ? "✅ مفعّل" : "⭕ معطّل"}
              color={systemEnabled ? "success" : "default"}
              size="small"
            />
            <Typography variant="caption" color="textSecondary">
              {examples.length} مثال
            </Typography>
          </Box>
        </Box>

        {/* Instructions */}
        <Paper
          sx={{
            p: 2,
            mb: 2,
            bgcolor: "#fef3c7",
            border: "2px solid #fbbf24",
            cursor: "pointer",
          }}
          onClick={() => setShowInstructions(!showInstructions)}
        >
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
              <InfoIcon sx={{ color: "#f59e0b" }} />
              <Typography
                variant="subtitle2"
                sx={{ fontWeight: 600, color: "#92400e" }}
              >
                📚 تعليمات مهمة - اقرأ قبل الإضافة
              </Typography>
            </Box>
            {showInstructions ? <ExpandLessIcon /> : <ExpandMoreIcon />}
          </Box>

          <Collapse in={showInstructions}>
            <Box sx={{ mt: 2, pl: 4 }}>
              <Typography
                variant="body2"
                sx={{ color: "#92400e", mb: 1, fontWeight: 600 }}
              >
                ⚠️ مهم جداً:
              </Typography>
              <Typography variant="body2" sx={{ color: "#92400e", mb: 0.5 }}>
                • <strong>الأمثلة تُعلم الأسلوب فقط</strong> - البوت يتعلم كيف
                يرد، لكن المعلومات الفعلية تأتي من قاعدة البيانات
              </Typography>
              <Typography variant="body2" sx={{ color: "#92400e", mb: 0.5 }}>
                • <strong>لا تكتب أسعار محددة</strong> - البوت يجلب السعر
                الحقيقي من المنتجات تلقائياً
              </Typography>
              <Typography variant="body2" sx={{ color: "#92400e", mb: 2 }}>
                • <strong>ركز على الأسلوب والطريقة</strong> - كيف يرد البوت بشكل
                احترافي وودود
              </Typography>

              <Typography
                variant="body2"
                sx={{ color: "#92400e", mb: 1, fontWeight: 600 }}
              >
                ✅ أمثلة صحيحة:
              </Typography>
              <Paper
                sx={{
                  p: 1.5,
                  mb: 1,
                  bgcolor: "#d1fae5",
                  border: "1px solid #10b981",
                }}
              >
                <Typography
                  variant="caption"
                  sx={{ color: "#065f46", display: "block", mb: 0.5 }}
                >
                  <strong>سؤال:</strong> كم سعر المنتج؟
                </Typography>
                <Typography variant="caption" sx={{ color: "#065f46" }}>
                  <strong>رد:</strong> سعر المنتج [السعر] جنيه، ويشمل الشحن
                  المجاني 🎁
                </Typography>
              </Paper>
              <Paper
                sx={{
                  p: 1.5,
                  mb: 2,
                  bgcolor: "#d1fae5",
                  border: "1px solid #10b981",
                }}
              >
                <Typography
                  variant="caption"
                  sx={{ color: "#065f46", display: "block", mb: 0.5 }}
                >
                  <strong>سؤال:</strong> متى يوصل الطلب؟
                </Typography>
                <Typography variant="caption" sx={{ color: "#065f46" }}>
                  <strong>رد:</strong> التوصيل خلال 2-3 أيام عمل، وسنبلغك
                  بالتفاصيل 📦
                </Typography>
              </Paper>

              <Typography
                variant="body2"
                sx={{ color: "#92400e", mb: 1, fontWeight: 600 }}
              >
                ❌ أمثلة خاطئة:
              </Typography>
              <Paper
                sx={{ p: 1.5, bgcolor: "#fee2e2", border: "1px solid #ef4444" }}
              >
                <Typography
                  variant="caption"
                  sx={{ color: "#991b1b", display: "block", mb: 0.5 }}
                >
                  <strong>سؤال:</strong> كم سعر تيشيرت أديداس؟
                </Typography>
                <Typography variant="caption" sx={{ color: "#991b1b" }}>
                  <strong>رد:</strong> سعر تيشيرت أديداس 299 جنيه ❌ (لا تكتب
                  أسعار محددة!)
                </Typography>
              </Paper>
            </Box>
          </Collapse>
        </Paper>

        {/* Add New Example Form */}
        <Paper sx={{ p: 3, bgcolor: "#f0f9ff", border: "2px dashed #3b82f6" }}>
