            startIcon={<AddIcon />}
            onClick={handleAddCustomerMessage}
            sx={{ mb: 3, color: "#3b82f6" }}
          >
            إضافة سؤال آخر
          </Button>

          {/* AI Responses */}
          <Typography
            variant="subtitle2"
            sx={{ mb: 1, fontWeight: 600, color: "#065f46" }}
          >
            🤖 ردود البوت (يمكنك إضافة أكثر من رد)
