                onChange={(e) => {
                  const newResponses = [...aiResponses];
                  newResponses[index] = e.target.value;
                  setAiResponses(newResponses);
                }}
                multiline
                rows={3}
                variant="outlined"
                sx={{ bgcolor: "white" }}
              />
              {aiResponses.length > 1 && (
                <IconButton
                  onClick={() => handleRemoveAiResponse(index)}
                  color="error"
                  size="small"
                >
                  <DeleteIcon />
                </IconButton>
              )}
            </Box>
          ))}
          <Button
            size="small"
            startIcon={<AddIcon />}
            onClick={handleAddAiResponse}
            sx={{ mb: 2, color: "#10b981" }}
          >
            إضافة رد آخر
          </Button>

          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              mt: 2,
            }}
          >
            <Typography variant="caption" color="textSecondary">
              💡 سيتم إنشاء{" "}
              {customerMessages.filter((m) => m.trim()).length *
                aiResponses.filter((r) => r.trim()).length}{" "}
              مثال
            </Typography>
            <Button
              variant="contained"
              size="large"
              startIcon={<AddIcon />}
              onClick={handleAdd}
              disabled={
                customerMessages.filter((m) => m.trim()).length === 0 ||
                aiResponses.filter((r) => r.trim()).length === 0
              }
              sx={{
                bgcolor: "#3b82f6",
                "&:hover": { bgcolor: "#2563eb" },
                px: 4,
                py: 1.5,
                fontSize: "1rem",
                fontWeight: 600,
              }}
            >
              إضافة الأمثلة
            </Button>
          </Box>
        </Paper>
      </Box>

      {/* Examples List */}
      <Box sx={{ flex: 1, overflow: "auto", p: 3 }}>
        {loading ? (
          <Box sx={{ display: "flex", justifyContent: "center", py: 8 }}>
            <CircularProgress />
          </Box>
        ) : examples.length === 0 ? (
          <Box sx={{ textAlign: "center", py: 8 }}>
