              ابدأ بإضافة أول مثال في الأعلى ⬆️
            </Typography>
          </Box>
        ) : (
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
            {examples.map((example, index) => (
              <Paper
                key={example.id}
                sx={{
                  p: 3,
                  position: "relative",
                  border: "1px solid #e5e7eb",
                  "&:hover": {
                    boxShadow: 3,
                    borderColor: "#3b82f6",
                  },
                }}
              >
                <IconButton
                  size="small"
                  onClick={() => handleDelete(example.id)}
                  sx={{
                    position: "absolute",
                    top: 8,
                    right: 8,
                    color: "#ef4444",
                  }}
                >
                  <DeleteIcon />
                </IconButton>

                <Chip
                  label={`مثال ${index + 1}`}
                  size="small"
                  sx={{ mb: 2, bgcolor: "#f3f4f6", fontWeight: 600 }}
                />

                <Box sx={{ display: "flex", gap: 2, mb: 2 }}>
                  <Avatar sx={{ bgcolor: "#3b82f6", width: 36, height: 36 }}>
                    <PersonIcon fontSize="small" />
                  </Avatar>
                  <Box sx={{ flex: 1 }}>
                    <Typography
                      variant="caption"
                      sx={{
                        color: "#6b7280",
                        fontWeight: 600,
                        display: "block",
                        mb: 0.5,
                      }}
                    >
                      سؤال العميل
                    </Typography>
                    <Paper
                      sx={{
                        p: 2,
                        bgcolor: "#eff6ff",
                        border: "1px solid #bfdbfe",
                      }}
                    >
                      <Typography variant="body2" sx={{ color: "#1e40af" }}>
                        {example.customerMessage}
                      </Typography>
                    </Paper>
                  </Box>
                </Box>

                <Box sx={{ display: "flex", gap: 2 }}>
                  <Avatar sx={{ bgcolor: "#10b981", width: 36, height: 36 }}>
                    <BotIcon fontSize="small" />
                  </Avatar>
                  <Box sx={{ flex: 1 }}>
                    <Typography
                      variant="caption"
                      sx={{
                        color: "#6b7280",
                        fontWeight: 600,
                        display: "block",
                        mb: 0.5,
                      }}
                    >
                      رد البوت
                    </Typography>
                    <Paper
                      sx={{
                        p: 2,
                        bgcolor: "#f0fdf4",
                        border: "1px solid #bbf7d0",
                      }}
                    >
                      <Typography variant="body2" sx={{ color: "#065f46" }}>
                        {example.aiResponse}
                      </Typography>
                    </Paper>
                  </Box>
                </Box>

                <Box
                  sx={{
                    display: "flex",
                    gap: 2,
                    mt: 2,
                    pt: 2,
                    borderTop: "1px solid #e5e7eb",
                  }}
                >
                  <Typography variant="caption" color="textSecondary">
                    📊 استُخدم {example.usageCount} مرة
                  </Typography>
                  <Typography variant="caption" color="textSecondary">
                    📅 {new Date(example.createdAt).toLocaleDateString("ar-EG")}
                  </Typography>
                </Box>
              </Paper>
            ))}
          </Box>
        )}
      </Box>

      {/* Settings Dialog */}
      <Dialog
        open={openSettings}
        onClose={() => setOpenSettings(false)}
        maxWidth="xs"
        fullWidth
      >
        <DialogTitle>⚙️ إعدادات النظام</DialogTitle>
        <DialogContent>
          <FormControlLabel
            control={
              <Switch
                checked={systemEnabled}
                onChange={handleToggleSystem}
                color="success"
              />
            }
            label={
              <Box>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  {systemEnabled ? "تعطيل النظام" : "تفعيل النظام"}
                </Typography>
                <Typography variant="caption" color="textSecondary">
                  {systemEnabled
                    ? "النظام مفعّل حالياً ويستخدم الأمثلة في الردود"
                    : "النظام معطّل حالياً"}
                </Typography>
              </Box>
            }
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSettings(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert
          severity={snackbar.severity}
          onClose={() => setSnackbar({ ...snackbar, open: false })}
          sx={{ width: "100%" }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

