  children,
  footer,
  maxWidthClassName = "max-w-3xl",
}) => {
  if (!open) return null;

  return (
    <div className={modalOverlayClassName} dir="rtl">
      <div
        className={`flex max-h-[90vh] w-full flex-col overflow-hidden rounded-xl bg-white shadow-2xl dark:bg-gray-800 ${maxWidthClassName}`}
      >
        <div className="flex items-start justify-between gap-4 border-b border-gray-200 px-6 py-4 dark:border-gray-700">
          <div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              {title}
            </h3>
            {description && (
              <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
                {description}
              </p>
            )}
          </div>
          <button
            onClick={onClose}
            className="rounded-lg p-2 text-gray-500 transition hover:bg-gray-100 hover:text-gray-900 dark:text-gray-400 dark:hover:bg-gray-700 dark:hover:text-white"
          >
            <XMarkIcon className="h-5 w-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-5">{children}</div>

        {footer && (
          <div className="border-t border-gray-200 px-6 py-4 dark:border-gray-700">
            {footer}
          </div>
        )}
      </div>
    </div>
  );
};

const formatDate = (value: string) =>
  new Date(value).toLocaleDateString("ar-EG", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });

const countFilled = (items: string[]) => items.filter((item) => item.trim()).length;

const updateArrayValue = (items: string[], index: number, value: string) =>
  items.map((item, currentIndex) => (currentIndex === index ? value : item));

const removeArrayValue = (items: string[], index: number) =>
  items.filter((_, currentIndex) => currentIndex !== index);

const FewShotTwoColumns: React.FC = () => {
  const [examples, setExamples] = useState<FewShotExample[]>([]);
  const [loading, setLoading] = useState(false);
  const [busyAction, setBusyAction] = useState<string | null>(null);
  const [customerMessages, setCustomerMessages] = useState<string[]>([""]);
  const [aiResponses, setAiResponses] = useState<string[]>([""]);
  const [notification, setNotification] = useState<NotificationState>({
    show: false,
    message: "",
    type: "success",
  });
  const [systemEnabled, setSystemEnabled] = useState(false);
  const [openSettings, setOpenSettings] = useState(false);
  const [showInstructions, setShowInstructions] = useState(true);
  const [editingExample, setEditingExample] = useState<FewShotExample | null>(
    null,
  );
  const [openEditDialog, setOpenEditDialog] = useState(false);
  const [openAddVariationDialog, setOpenAddVariationDialog] = useState(false);
  const [baseExample, setBaseExample] = useState<FewShotExample | null>(null);
  const [newVariations, setNewVariations] = useState<VariationState>(
    emptyVariationState(),
  );
  const [openTemplatesDialog, setOpenTemplatesDialog] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    loadExamples();
    loadSettings();
  }, []);

  useEffect(() => {
    if (!notification.show) return undefined;

    const timer = window.setTimeout(() => {
      setNotification((current) => ({ ...current, show: false }));
    }, 4000);

    return () => window.clearTimeout(timer);
  }, [notification.show]);

  const showNotification = (
    message: string,
    type: NotificationState["type"],
  ) => {
    setNotification({ show: true, message, type });
  };

  const loadExamples = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/few-shot/examples");
      setExamples(response.data.data || []);
    } catch (error) {
      showNotification("فشل في تحميل الأمثلة", "error");
    } finally {
      setLoading(false);
    }
  };

  const loadSettings = async () => {
    try {
      const response = await companyAwareApi.get("/few-shot/settings");
      setSystemEnabled(Boolean(response.data.data.enabled));
    } catch (error) {
      console.error("Failed to load few-shot settings:", error);
    }
  };

  const validCustomerCount = useMemo(
    () => countFilled(customerMessages),
    [customerMessages],
  );

  const validResponseCount = useMemo(
    () => countFilled(aiResponses),
    [aiResponses],
  );

  const totalCombinations = validCustomerCount * validResponseCount;

  const activeExamplesCount = useMemo(
    () => examples.filter((example) => example.isActive).length,
    [examples],
  );

  const filteredExamples = useMemo(() => {
    const normalizedQuery = searchTerm.trim().toLowerCase();
    if (!normalizedQuery) return examples;

    return examples.filter((example) => {
      return (
        example.customerMessage.toLowerCase().includes(normalizedQuery) ||
        example.aiResponse.toLowerCase().includes(normalizedQuery)
      );
    });
  }, [examples, searchTerm]);

  const handleAddCustomerMessage = () => {
    setCustomerMessages((current) => [...current, ""]);
  };

  const handleAddAiResponse = () => {
    setAiResponses((current) => [...current, ""]);
  };

  const handleRemoveCustomerMessage = (index: number) => {
    setCustomerMessages((current) =>
      current.length > 1 ? removeArrayValue(current, index) : current,
    );
  };

  const handleRemoveAiResponse = (index: number) => {
    setAiResponses((current) =>
      current.length > 1 ? removeArrayValue(current, index) : current,
    );
  };

  const handleAdd = async () => {
    const validCustomerMessages = customerMessages
      .map((message) => message.trim())
      .filter(Boolean);
    const validAiResponses = aiResponses
      .map((response) => response.trim())
      .filter(Boolean);

    if (validCustomerMessages.length === 0 || validAiResponses.length === 0) {
      showNotification(
        "يرجى كتابة سؤال واحد على الأقل ورد واحد على الأقل",
        "error",
      );
      return;
    }

    try {
      setBusyAction("add");

      const promises = [];
      for (const customerMessage of validCustomerMessages) {
        for (const aiResponse of validAiResponses) {
          promises.push(
            companyAwareApi.post("/few-shot/examples", {
              customerMessage,
              aiResponse,
              priority: 5,
              isActive: true,
            }),
          );
        }
      }

      await Promise.all(promises);

      showNotification(
        `تم إضافة ${validCustomerMessages.length * validAiResponses.length} مثال بنجاح`,
        "success",
      );
      setCustomerMessages([""]);
      setAiResponses([""]);
      await loadExamples();
    } catch (error) {
      showNotification("فشل في إضافة الأمثلة", "error");
    } finally {
      setBusyAction(null);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل تريد حذف هذا المثال؟")) return;

    try {
      setBusyAction(`delete-${id}`);
      await companyAwareApi.delete(`/few-shot/examples/${id}`);
      showNotification("تم حذف المثال بنجاح", "success");
      await loadExamples();
    } catch (error) {
      showNotification("فشل في حذف المثال", "error");
    } finally {
      setBusyAction(null);
    }
  };

  const handleEditExample = (example: FewShotExample) => {
    setEditingExample(example);
    setOpenEditDialog(true);
  };

  const handleSaveEdit = async () => {
    if (!editingExample) return;

    try {
      setBusyAction("edit");
      await companyAwareApi.put(`/few-shot/examples/${editingExample.id}`, {
        customerMessage: editingExample.customerMessage,
        aiResponse: editingExample.aiResponse,
        priority: 5,
        isActive: true,
      });
      showNotification("تم تحديث المثال بنجاح", "success");
      setOpenEditDialog(false);
      setEditingExample(null);
      await loadExamples();
    } catch (error) {
      showNotification("فشل في تحديث المثال", "error");
    } finally {
      setBusyAction(null);
    }
  };

  const handleAddVariation = (example: FewShotExample) => {
    setBaseExample(example);
    setNewVariations(emptyVariationState());
    setOpenAddVariationDialog(true);
  };

  const handleSaveVariations = async () => {
    if (!baseExample) return;

    const validQuestions = newVariations.questions
      .map((question) => question.trim())
      .filter(Boolean);
    const validAnswers = newVariations.answers
      .map((answer) => answer.trim())
      .filter(Boolean);

    if (validQuestions.length === 0 && validAnswers.length === 0) {
      showNotification("يرجى إضافة سؤال أو رد على الأقل", "error");
      return;
    }

    try {
      setBusyAction("variation");
      const promises = [];

      for (const question of validQuestions) {
        promises.push(
          companyAwareApi.post("/few-shot/examples", {
            customerMessage: question,
            aiResponse: baseExample.aiResponse,
            priority: 5,
            isActive: true,
          }),
        );
      }

      for (const answer of validAnswers) {
        promises.push(
          companyAwareApi.post("/few-shot/examples", {
            customerMessage: baseExample.customerMessage,
            aiResponse: answer,
            priority: 5,
            isActive: true,
          }),
        );
      }

      await Promise.all(promises);

      showNotification(
        `تم إضافة ${validQuestions.length + validAnswers.length} تنويع جديد`,
        "success",
      );
      setOpenAddVariationDialog(false);
      setBaseExample(null);
      setNewVariations(emptyVariationState());
      await loadExamples();
    } catch (error) {
      showNotification("فشل في إضافة التنويعات", "error");
    } finally {
      setBusyAction(null);
    }
  };

  const handleAddTemplate = async (templateId: string) => {
    const template = templates.find((entry) => entry.id === templateId);
    if (!template) return;

    try {
      setBusyAction(`template-${templateId}`);
      await Promise.all(
        template.examples.map((example) =>
          companyAwareApi.post("/few-shot/examples", {
            customerMessage: example.q,
            aiResponse: example.a,
            priority: 5,
            isActive: true,
          }),
        ),
      );

      showNotification(
        `تمت إضافة ${template.examples.length} مثال من قالب "${template.name}"`,
        "success",
      );
      setOpenTemplatesDialog(false);
      await loadExamples();
    } catch (error) {
      showNotification("فشل في إضافة القالب", "error");
    } finally {
      setBusyAction(null);
    }
  };

  const handleToggleSystem = async () => {
    try {
      setBusyAction("settings");
      await companyAwareApi.put("/few-shot/settings", {
        enabled: !systemEnabled,
        maxExamplesPerPrompt: 3,
        selectionStrategy: "priority",
        autoLearnFromGood: false,
        minQualityScore: 80,
      });

      setSystemEnabled((current) => !current);
      showNotification(
        systemEnabled ? "تم تعطيل النظام" : "تم تفعيل النظام بنجاح",
        "success",
      );
      setOpenSettings(false);
    } catch (error) {
      showNotification("فشل في تحديث إعدادات النظام", "error");
    } finally {
      setBusyAction(null);
    }
  };

  return (
    <div className="flex h-full flex-col bg-gray-50 dark:bg-gray-900" dir="rtl">
      {notification.show && (
        <div
          className={`fixed right-4 top-4 z-50 max-w-md rounded-lg px-4 py-3 text-sm text-white shadow-lg ${
            notification.type === "success" ? "bg-green-600" : "bg-red-600"
          }`}
        >
          <div className="flex items-start gap-3">
            <div className="mt-0.5">
              {notification.type === "success" ? (
                <SparklesIcon className="h-5 w-5" />
              ) : (
                <InformationCircleIcon className="h-5 w-5" />
              )}
            </div>
            <div className="flex-1">{notification.message}</div>
            <button
              onClick={() =>
                setNotification((current) => ({ ...current, show: false }))
              }
              className="rounded p-0.5 text-white/80 transition hover:bg-white/10 hover:text-white"
            >
              <XMarkIcon className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}

      <div className="border-b border-gray-200 bg-white px-4 py-4 dark:border-gray-700 dark:bg-gray-800">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
          <div className="max-w-3xl">
            <div className="mb-2 inline-flex items-center gap-2 rounded-full bg-blue-50 px-3 py-1 text-xs font-semibold text-blue-700 dark:bg-blue-900/20 dark:text-blue-300">
              <BoltIcon className="h-4 w-4" />
              Few-Shot Learning
            </div>
            <h2 className="text-xl font-bold text-gray-900 dark:text-white">
              علّم الذكاء أسلوب الرد الذي يناسب شغلك
            </h2>
            <p className="mt-2 text-sm leading-6 text-gray-600 dark:text-gray-300">
              أضف أمثلة حقيقية لأسئلة العملاء مع الردود المطلوبة، وسيستخدمها
              النظام لتوجيه أسلوب الإجابة بدون تثبيت معلومات خاطئة أو أسعار
              جامدة.
            </p>
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setOpenTemplatesDialog(true)}
              className="inline-flex items-center gap-2 rounded-md border border-emerald-300 px-3 py-2 text-sm font-medium text-emerald-700 transition hover:bg-emerald-50 dark:border-emerald-700 dark:text-emerald-300 dark:hover:bg-emerald-900/20"
            >
              <ClipboardDocumentListIcon className="h-4 w-4" />
              قوالب جاهزة
            </button>
            <button
              onClick={() => setOpenSettings(true)}
              className="inline-flex items-center gap-2 rounded-md border border-gray-300 px-3 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50 dark:border-gray-600 dark:text-gray-200 dark:hover:bg-gray-700"
            >
              <Cog6ToothIcon className="h-4 w-4" />
              الإعدادات
            </button>
          </div>
        </div>

        <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <div className="rounded-lg border border-gray-200 bg-gray-50 px-4 py-3 dark:border-gray-700 dark:bg-gray-900/40">
            <div className="text-sm text-gray-500 dark:text-gray-400">
              حالة النظام
            </div>
            <div className="mt-2 flex items-center gap-2 text-sm font-semibold">
              <span
                className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs ${
                  systemEnabled
                    ? "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300"
                    : "bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-gray-200"
                }`}
              >
                {systemEnabled ? "مفعّل" : "معطّل"}
              </span>
            </div>
          </div>

          <div className="rounded-lg border border-gray-200 bg-gray-50 px-4 py-3 dark:border-gray-700 dark:bg-gray-900/40">
            <div className="text-sm text-gray-500 dark:text-gray-400">
              الأمثلة المحفوظة
            </div>
            <div className="mt-2 text-2xl font-bold text-gray-900 dark:text-white">
              {examples.length}
            </div>
          </div>

          <div className="rounded-lg border border-gray-200 bg-gray-50 px-4 py-3 dark:border-gray-700 dark:bg-gray-900/40">
            <div className="text-sm text-gray-500 dark:text-gray-400">
              أمثلة نشطة
            </div>
            <div className="mt-2 text-2xl font-bold text-gray-900 dark:text-white">
              {activeExamplesCount}
            </div>
          </div>

          <div className="rounded-lg border border-gray-200 bg-gray-50 px-4 py-3 dark:border-gray-700 dark:bg-gray-900/40">
            <div className="text-sm text-gray-500 dark:text-gray-400">
              التركيبات الجاهزة الآن
            </div>
            <div className="mt-2 text-2xl font-bold text-gray-900 dark:text-white">
              {totalCombinations}
            </div>
          </div>
        </div>
      </div>

      <div className="grid flex-1 min-h-0 grid-cols-1 gap-4 overflow-hidden p-4 xl:grid-cols-[minmax(0,1.05fr)_minmax(0,0.95fr)]">
        <div className="min-h-0 space-y-4 overflow-y-auto pr-1">
          <div className="rounded-lg border border-amber-300 bg-amber-50 p-4 dark:border-amber-700 dark:bg-amber-900/10">
            <button
              onClick={() => setShowInstructions((current) => !current)}
              className="flex w-full items-center justify-between gap-3 text-right"
            >
              <div className="flex items-center gap-3">
                <div className="rounded-full bg-amber-100 p-2 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300">
                  <InformationCircleIcon className="h-5 w-5" />
                </div>
                <div>
                  <h3 className="text-sm font-semibold text-amber-900 dark:text-amber-200">
                    تعليمات مهمة قبل إضافة الأمثلة
                  </h3>
                  <p className="mt-1 text-xs text-amber-800/80 dark:text-amber-300/80">
                    أمثلة الـ Few-Shot تعلّم الأسلوب، لا تستبدل بيانات المنتجات.
                  </p>
                </div>
              </div>
              {showInstructions ? (
                <ChevronUpIcon className="h-5 w-5 text-amber-700 dark:text-amber-300" />
              ) : (
                <ChevronDownIcon className="h-5 w-5 text-amber-700 dark:text-amber-300" />
              )}
            </button>

            {showInstructions && (
              <div className="mt-4 space-y-3 border-t border-amber-200 pt-4 dark:border-amber-800">
                <div className="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800 dark:border-emerald-800 dark:bg-emerald-900/20 dark:text-emerald-300">
                  <div className="font-semibold">افعل هذا</div>
                  <ul className="mt-2 space-y-1 leading-6">
                    <li>اكتب ردودًا مرنة مثل: "سعر المنتج [السعر] جنيه".</li>
                    <li>علّم النبرة، أسلوب العرض، وطريقة التطمين.</li>
                    <li>استخدم أكثر من سؤال لنفس الرد إذا كانت النية واحدة.</li>
                  </ul>
                </div>
                <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
                  <div className="font-semibold">تجنب هذا</div>
                  <ul className="mt-2 space-y-1 leading-6">
                    <li>لا تكتب أسعارًا ثابتة أو معلومات منتج حرفية قد تتغير.</li>
                    <li>لا تحوّل المثال إلى قاعدة بيانات بديلة للكتالوج.</li>
                    <li>لا تكرر نفس المثال بصياغة متطابقة بلا داعٍ.</li>
                  </ul>
                </div>
              </div>
            )}
          </div>

          <div className="rounded-lg border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-700 dark:bg-gray-800">
            <div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
              <div>
                <h3 className="flex items-center gap-2 text-lg font-semibold text-gray-900 dark:text-white">
                  <ChatBubbleLeftRightIcon className="h-5 w-5 text-blue-600 dark:text-blue-400" />
                  إضافة أمثلة جديدة
                </h3>
                <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
                  يمكنك إدخال أكثر من سؤال وأكثر من رد، وسيتم توليد كل التركيبات
                  الممكنة بينهما.
                </p>
              </div>
              <div className="rounded-full bg-blue-50 px-3 py-1 text-xs font-semibold text-blue-700 dark:bg-blue-900/20 dark:text-blue-300">
                {totalCombinations} تركيبة جاهزة
              </div>
            </div>

            <div className="space-y-5">
              <div>
                <div className="mb-3 flex items-center justify-between">
                  <label className="text-sm font-medium text-gray-900 dark:text-white">
                    أسئلة العميل
                  </label>
                  <button
                    onClick={handleAddCustomerMessage}
                    className="inline-flex items-center gap-1 rounded-md bg-blue-50 px-2.5 py-1.5 text-xs font-medium text-blue-700 transition hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:hover:bg-blue-900/30"
                  >
                    <PlusIcon className="h-4 w-4" />
                    إضافة سؤال
                  </button>
                </div>

                <div className="space-y-3">
                  {customerMessages.map((message, index) => (
                    <div key={`customer-${index}`} className="flex gap-2">
                      <div className="hidden rounded-lg bg-blue-50 px-3 py-3 text-blue-700 dark:bg-blue-900/20 dark:text-blue-300 sm:flex">
                        <UserCircleIcon className="h-5 w-5" />
                      </div>
                      <textarea
                        value={message}
                        onChange={(event) =>
                          setCustomerMessages((current) =>
                            updateArrayValue(
                              current,
                              index,
                              event.target.value,
                            ),
                          )
                        }
                        rows={2}
                        placeholder={`سؤال ${index + 1}`}
                        className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 shadow-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 dark:border-gray-600 dark:bg-gray-900 dark:text-white dark:focus:ring-blue-900/40"
                      />
                      {customerMessages.length > 1 && (
                        <button
                          onClick={() => handleRemoveCustomerMessage(index)}
                          className="self-start rounded-lg border border-red-200 p-2 text-red-600 transition hover:bg-red-50 dark:border-red-900/50 dark:text-red-400 dark:hover:bg-red-900/20"
                        >
                          <TrashIcon className="h-4 w-4" />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              <div>
                <div className="mb-3 flex items-center justify-between">
                  <label className="text-sm font-medium text-gray-900 dark:text-white">
                    ردود البوت
                  </label>
                  <button
                    onClick={handleAddAiResponse}
                    className="inline-flex items-center gap-1 rounded-md bg-emerald-50 px-2.5 py-1.5 text-xs font-medium text-emerald-700 transition hover:bg-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-300 dark:hover:bg-emerald-900/30"
                  >
                    <PlusIcon className="h-4 w-4" />
                    إضافة رد
                  </button>
                </div>

                <div className="space-y-3">
                  {aiResponses.map((response, index) => (
                    <div key={`response-${index}`} className="flex gap-2">
                      <div className="hidden rounded-lg bg-emerald-50 px-3 py-3 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-300 sm:flex">
                        <CpuChipIcon className="h-5 w-5" />
                      </div>
                      <textarea
                        value={response}
                        onChange={(event) =>
                          setAiResponses((current) =>
                            updateArrayValue(
                              current,
                              index,
                              event.target.value,
                            ),
                          )
                        }
                        rows={3}
                        placeholder={`رد ${index + 1}`}
                        className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 shadow-sm outline-none transition focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 dark:border-gray-600 dark:bg-gray-900 dark:text-white dark:focus:ring-emerald-900/40"
                      />
                      {aiResponses.length > 1 && (
                        <button
                          onClick={() => handleRemoveAiResponse(index)}
                          className="self-start rounded-lg border border-red-200 p-2 text-red-600 transition hover:bg-red-50 dark:border-red-900/50 dark:text-red-400 dark:hover:bg-red-900/20"
                        >
                          <TrashIcon className="h-4 w-4" />
                        </button>
                      )}
                    </div>
