                />
              </div>
            </div>
          </div>

          {loading ? (
            <div className="flex h-64 items-center justify-center rounded-lg border border-dashed border-gray-300 bg-white dark:border-gray-700 dark:bg-gray-800">
              <div className="text-center">
                <div className="mx-auto h-10 w-10 animate-spin rounded-full border-2 border-gray-200 border-t-blue-600 dark:border-gray-700 dark:border-t-blue-400" />
                <p className="mt-3 text-sm text-gray-600 dark:text-gray-400">
