                        title="حذف المثال"
                      >
                        <TrashIcon className="h-4 w-4" />
                      </button>
                    </div>
                  </div>

                  <div className="space-y-3">
                    <div className="rounded-lg border border-blue-200 bg-blue-50/70 p-3 dark:border-blue-900/60 dark:bg-blue-900/20">
                      <div className="mb-2 flex items-center gap-2 text-xs font-semibold text-blue-700 dark:text-blue-300">
                        <UserCircleIcon className="h-4 w-4" />
                        سؤال العميل
                      </div>
                      <p className="text-sm leading-6 text-blue-900 dark:text-blue-100">
                        {example.customerMessage}
                      </p>
                    </div>

                    <div className="rounded-lg border border-emerald-200 bg-emerald-50/70 p-3 dark:border-emerald-900/60 dark:bg-emerald-900/20">
                      <div className="mb-2 flex items-center gap-2 text-xs font-semibold text-emerald-700 dark:text-emerald-300">
                        <CpuChipIcon className="h-4 w-4" />
                        رد البوت
                      </div>
                      <p className="text-sm leading-6 text-emerald-900 dark:text-emerald-100">
                        {example.aiResponse}
                      </p>
                    </div>
                  </div>

                  <div className="mt-4 flex flex-wrap gap-3 border-t border-gray-200 pt-3 text-xs text-gray-500 dark:border-gray-700 dark:text-gray-400">
                    <span>الاستخدام: {example.usageCount} مرة</span>
                    <span>تاريخ الإضافة: {formatDate(example.createdAt)}</span>
                  </div>
