        maxWidthClassName="max-w-5xl"
        footer={
          <div className="flex justify-end">
            <button
              onClick={() => setOpenTemplatesDialog(false)}
              className="rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50 dark:border-gray-600 dark:text-gray-200 dark:hover:bg-gray-700"
            >
              إغلاق
            </button>
          </div>
        }
      >
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {templates.map((template) => (
            <button
              key={template.id}
              onClick={() => handleAddTemplate(template.id)}
              disabled={busyAction === `template-${template.id}`}
              className="rounded-lg border border-gray-200 bg-white p-4 text-right shadow-sm transition hover:-translate-y-0.5 hover:border-blue-300 hover:shadow-md disabled:cursor-not-allowed disabled:opacity-60 dark:border-gray-700 dark:bg-gray-900 dark:hover:border-blue-700"
            >
              <div
                className={`inline-flex rounded-full border px-3 py-1 text-xs font-semibold ${template.accentClassName}`}
              >
                {template.name}
              </div>
              <h4 className="mt-3 text-base font-semibold text-gray-900 dark:text-white">
                {template.name}
              </h4>
              <p className="mt-1 text-sm leading-6 text-gray-600 dark:text-gray-400">
                {template.description}
              </p>

              <div className="mt-3 rounded-md bg-gray-50 px-3 py-2 text-xs text-gray-600 dark:bg-gray-800 dark:text-gray-300">
                {template.examples.length} أمثلة جاهزة
              </div>

              <div className="mt-4 space-y-2">
                {template.examples.slice(0, 2).map((example, index) => (
                  <div
                    key={`${template.id}-${index}`}
                    className="rounded-md border border-gray-200 bg-gray-50 p-3 dark:border-gray-700 dark:bg-gray-800"
                  >
                    <div className="text-xs font-medium text-blue-700 dark:text-blue-300">
                      العميل: {example.q}
                    </div>
                    <div className="mt-1 text-xs leading-5 text-emerald-700 dark:text-emerald-300">
                      الرد: {example.a}
                    </div>
                  </div>
                ))}
              </div>

              <div className="mt-4 inline-flex items-center gap-2 text-sm font-medium text-blue-700 dark:text-blue-300">
                {busyAction === `template-${template.id}`
                  ? "جاري الإضافة..."
                  : "استخدم هذا القالب"}
                <PlusIcon className="h-4 w-4" />
              </div>
            </button>
          ))}
        </div>
      </ModalShell>

      <ModalShell
        open={openAddVariationDialog}
        onClose={() => setOpenAddVariationDialog(false)}
        title="إضافة تنويعات على المثال"
        description="أضف أسئلة جديدة تستخدم نفس الرد، أو ردودًا جديدة تستخدم نفس السؤال."
        maxWidthClassName="max-w-4xl"
        footer={
          <div className="flex justify-end gap-3">
            <button
              onClick={() => setOpenAddVariationDialog(false)}
              className="rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50 dark:border-gray-600 dark:text-gray-200 dark:hover:bg-gray-700"
            >
              إلغاء
            </button>
            <button
              onClick={handleSaveVariations}
              disabled={busyAction === "variation"}
              className="rounded-md bg-emerald-600 px-4 py-2 text-sm font-medium text-white transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {busyAction === "variation"
                ? "جاري الحفظ..."
                : "حفظ التنويعات"}
            </button>
          </div>
        }
      >
        {baseExample && (
          <div className="space-y-5">
            <div className="rounded-lg border border-blue-200 bg-blue-50 p-4 dark:border-blue-900/60 dark:bg-blue-900/20">
              <div className="text-sm font-semibold text-blue-800 dark:text-blue-300">
                المثال الأساسي
              </div>
              <div className="mt-3 space-y-2 text-sm leading-6">
                <div className="rounded-md bg-white/70 p-3 text-blue-900 dark:bg-gray-900/40 dark:text-blue-100">
                  <span className="font-semibold">السؤال:</span>{" "}
                  {baseExample.customerMessage}
                </div>
                <div className="rounded-md bg-white/70 p-3 text-emerald-900 dark:bg-gray-900/40 dark:text-emerald-100">
                  <span className="font-semibold">الرد:</span>{" "}
                  {baseExample.aiResponse}
                </div>
              </div>
            </div>

            <div className="grid gap-5 lg:grid-cols-2">
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h4 className="text-sm font-semibold text-gray-900 dark:text-white">
                    أسئلة إضافية بنفس الرد
                  </h4>
                  <button
                    onClick={() =>
                      setNewVariations((current) => ({
                        ...current,
                        questions: [...current.questions, ""],
                      }))
                    }
                    className="inline-flex items-center gap-1 rounded-md bg-blue-50 px-2.5 py-1.5 text-xs font-medium text-blue-700 transition hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300"
                  >
                    <PlusIcon className="h-4 w-4" />
                    إضافة
                  </button>
                </div>

                {newVariations.questions.map((question, index) => (
                  <div key={`variation-question-${index}`} className="flex gap-2">
                    <textarea
                      value={question}
                      onChange={(event) =>
                        setNewVariations((current) => ({
                          ...current,
                          questions: updateArrayValue(
                            current.questions,
                            index,
                            event.target.value,
                          ),
                        }))
                      }
                      rows={3}
                      placeholder={`سؤال إضافي ${index + 1}`}
                      className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 dark:border-gray-600 dark:bg-gray-900 dark:text-white dark:focus:ring-blue-900/40"
                    />
                    {newVariations.questions.length > 1 && (
                      <button
                        onClick={() =>
                          setNewVariations((current) => ({
                            ...current,
                            questions: removeArrayValue(current.questions, index),
                          }))
                        }
                        className="self-start rounded-lg border border-red-200 p-2 text-red-600 transition hover:bg-red-50 dark:border-red-900/50 dark:text-red-400 dark:hover:bg-red-900/20"
                      >
                        <TrashIcon className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                ))}
              </div>

              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h4 className="text-sm font-semibold text-gray-900 dark:text-white">
                    ردود إضافية بنفس السؤال
                  </h4>
                  <button
                    onClick={() =>
                      setNewVariations((current) => ({
                        ...current,
                        answers: [...current.answers, ""],
                      }))
                    }
                    className="inline-flex items-center gap-1 rounded-md bg-emerald-50 px-2.5 py-1.5 text-xs font-medium text-emerald-700 transition hover:bg-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-300"
                  >
                    <PlusIcon className="h-4 w-4" />
                    إضافة
                  </button>
                </div>

                {newVariations.answers.map((answer, index) => (
                  <div key={`variation-answer-${index}`} className="flex gap-2">
                    <textarea
                      value={answer}
                      onChange={(event) =>
                        setNewVariations((current) => ({
                          ...current,
                          answers: updateArrayValue(
                            current.answers,
                            index,
                            event.target.value,
                          ),
                        }))
                      }
                      rows={3}
                      placeholder={`رد إضافي ${index + 1}`}
                      className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 outline-none transition focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 dark:border-gray-600 dark:bg-gray-900 dark:text-white dark:focus:ring-emerald-900/40"
                    />
                    {newVariations.answers.length > 1 && (
                      <button
                        onClick={() =>
                          setNewVariations((current) => ({
                            ...current,
                            answers: removeArrayValue(current.answers, index),
                          }))
                        }
                        className="self-start rounded-lg border border-red-200 p-2 text-red-600 transition hover:bg-red-50 dark:border-red-900/50 dark:text-red-400 dark:hover:bg-red-900/20"
                      >
                        <TrashIcon className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </ModalShell>

      <ModalShell
        open={openEditDialog}
        onClose={() => setOpenEditDialog(false)}
        title="تعديل المثال"
        description="حدّث السؤال أو الرد دون الحاجة لإعادة إنشاء المثال من البداية."
        maxWidthClassName="max-w-3xl"
        footer={
          <div className="flex justify-end gap-3">
            <button
              onClick={() => setOpenEditDialog(false)}
              className="rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50 dark:border-gray-600 dark:text-gray-200 dark:hover:bg-gray-700"
            >
              إلغاء
            </button>
            <button
              onClick={handleSaveEdit}
              disabled={busyAction === "edit" || !editingExample}
              className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {busyAction === "edit" ? "جاري الحفظ..." : "حفظ التعديلات"}
            </button>
          </div>
        }
      >
        {editingExample && (
          <div className="space-y-4">
            <div>
              <label className="mb-2 block text-sm font-medium text-gray-900 dark:text-white">
                سؤال العميل
              </label>
              <textarea
                rows={4}
                value={editingExample.customerMessage}
                onChange={(event) =>
                  setEditingExample({
                    ...editingExample,
                    customerMessage: event.target.value,
                  })
                }
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 dark:border-gray-600 dark:bg-gray-900 dark:text-white dark:focus:ring-blue-900/40"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-gray-900 dark:text-white">
                رد البوت
              </label>
              <textarea
                rows={5}
                value={editingExample.aiResponse}
                onChange={(event) =>
                  setEditingExample({
                    ...editingExample,
                    aiResponse: event.target.value,
                  })
                }
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 outline-none transition focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 dark:border-gray-600 dark:bg-gray-900 dark:text-white dark:focus:ring-emerald-900/40"
              />
            </div>
          </div>
        )}
      </ModalShell>

      <ModalShell
        open={openSettings}
        onClose={() => setOpenSettings(false)}
        title="إعدادات النظام"
        description="تحكم في تفعيل أو إيقاف نظام الـ Few-Shot على مستوى الشركة."
        maxWidthClassName="max-w-lg"
        footer={
          <div className="flex justify-end">
            <button
              onClick={() => setOpenSettings(false)}
              className="rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50 dark:border-gray-600 dark:text-gray-200 dark:hover:bg-gray-700"
            >
              إغلاق
            </button>
          </div>
        }
      >
        <div className="rounded-lg border border-gray-200 bg-gray-50 p-4 dark:border-gray-700 dark:bg-gray-900/40">
          <div className="flex items-center justify-between gap-4">
            <div>
              <h4 className="text-sm font-semibold text-gray-900 dark:text-white">
                {systemEnabled ? "النظام مفعّل حاليًا" : "النظام متوقف حاليًا"}
              </h4>
              <p className="mt-1 text-sm leading-6 text-gray-600 dark:text-gray-400">
                عند التفعيل سيستخدم النظام الأمثلة المحفوظة لتوجيه أسلوب الردود،
                وعند الإيقاف سيتجاهلها تمامًا.
              </p>
            </div>

            <button
              onClick={handleToggleSystem}
              disabled={busyAction === "settings"}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                systemEnabled ? "bg-blue-600" : "bg-gray-300 dark:bg-gray-600"
              } ${busyAction === "settings" ? "cursor-not-allowed opacity-60" : ""}`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  systemEnabled ? "translate-x-6" : "translate-x-1"
                }`}
              />
            </button>
          </div>

          <div className="mt-4 rounded-md bg-white px-3 py-2 text-xs text-gray-600 dark:bg-gray-800 dark:text-gray-300">
            {busyAction === "settings"
              ? "جاري تحديث الحالة..."
              : systemEnabled
                ? "النظام يستفيد الآن من الأمثلة الموجودة أثناء بناء الرد."
                : "الأمثلة محفوظة، لكن النظام لا يستخدمها حتى يتم تفعيله."}
          </div>
        </div>
      </ModalShell>
    </div>
  );
};

export default FewShotTwoColumns;

