  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [invitation, setInvitation] = useState<InvitationData | null>(null);
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    if (!token) {
      setError("رابط الدعوة غير صحيح");
      setLoading(false);
      return;
    }

    const verifyInvitation = async () => {
      try {
        const response = await apiClient.get(`/invitations/verify/${token}`);
        if (response.data.success) {
          setInvitation(response.data.data.invitation);
        } else {
          setError(response.data.message || "فشل في التحقق من الدعوة");
        }
      } catch (err: any) {
        setError(err.response?.data?.message || "فشل في التحقق من الدعوة");
      } finally {
        setLoading(false);
      }
    };

    void verifyInvitation();
  }, [token]);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError("");

    if (!password) {
      setError("كلمة المرور مطلوبة");
      return;
    }

    if (password.length < 6) {
      setError("كلمة المرور يجب أن تكون 6 أحرف على الأقل");
      return;
    }

    if (password !== confirmPassword) {
      setError("كلمتا المرور غير متطابقتين");
      return;
    }

    try {
      setSubmitting(true);
      const response = await apiClient.post(`/invitations/accept/${token}`, {
        password,
      });

      if (response.data.success) {
        setSuccess(true);
        tokenManager.setAccessToken(response.data.data.token);
        if (response.data.data.refreshToken) {
          tokenManager.setRefreshToken(response.data.data.refreshToken);
        }
        localStorage.setItem("user", JSON.stringify(response.data.data.user));
        setTimeout(() => navigate("/conversations"), 1500);
      } else {
        setError(response.data.message || "فشل في قبول الدعوة");
      }
    } catch (err: any) {
      setError(err.response?.data?.message || "فشل في قبول الدعوة");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <AuthSurface
        title="جاري التحقق من الدعوة"
        description="نراجع بيانات الفريق والصلاحية قبل إتمام إنشاء الحساب."
        eyebrow="Invitation Check"
      >
        <div className="business-auth-loader-block">
          <div className="business-auth-loader" />
          <p>يتم التحقق من الرابط وتأمين الوصول لفريقك.</p>
        </div>
      </AuthSurface>
    );
  }

  if (error && !invitation) {
    return (
      <AuthSurface
        title="تعذر فتح الدعوة"
        description="الرابط غير صالح أو انتهت صلاحيته. يمكنك العودة لصفحة تسجيل الدخول وطلب دعوة جديدة."
        eyebrow="Invitation Error"
        icon={<ExclamationTriangleIcon className="h-7 w-7" />}
      >
        <AuthNotice variant="error" title="خطأ في الدعوة">
          {error}
        </AuthNotice>

        <div className="business-auth-actions">
          <button
            type="button"
            className="business-primary-button"
            onClick={() => navigate("/auth/login")}
          >
            العودة إلى تسجيل الدخول
          </button>
        </div>
      </AuthSurface>
    );
  }

  if (success) {
    return (
      <AuthSurface
        title="تم إنشاء الحساب بنجاح"
        description="تم تفعيل حسابك داخل الفريق، وسيتم تحويلك إلى لوحة التحكم خلال لحظات."
        eyebrow="Team Access Ready"
        icon={<CheckCircleIcon className="h-7 w-7" />}
      >
        <div className="business-auth-loader-block">
          <div className="business-auth-loader" />
          <p>يتم تجهيز مساحة العمل الخاصة بك الآن.</p>
        </div>
      </AuthSurface>
    );
  }

  return (
    <AuthSurface
      title="قبول الدعوة والانضمام للفريق"
      description="أكمل إنشاء كلمة المرور لتفعيل حسابك داخل الشركة والانطلاق بنفس الثيم المؤسسي الجديد."
      eyebrow="Join The Team"
      icon={<LockClosedIcon className="h-7 w-7" />}
      footer={
        <div className="business-auth-link-row">
          <button
            type="button"
            className="business-auth-inline-link"
            onClick={() => navigate("/auth/login")}
          >
            تسجيل الدخول إذا كان لديك حساب بالفعل
          </button>
        </div>
      }
    >
      {invitation ? (
        <div className="business-auth-summary">
          <div className="business-auth-summary-item">
            <UserIcon className="h-5 w-5" />
            <div>
              <span>الاسم</span>
              <strong>
                {invitation.firstName} {invitation.lastName}
              </strong>
            </div>
          </div>
          <div className="business-auth-summary-item">
            <EnvelopeIcon className="h-5 w-5" />
            <div>
              <span>البريد الإلكتروني</span>
              <strong>{invitation.email}</strong>
            </div>
          </div>
          <div className="business-auth-summary-item">
            <BuildingOffice2Icon className="h-5 w-5" />
            <div>
              <span>الشركة</span>
              <strong>{invitation.companyName}</strong>
            </div>
          </div>
          <div className="business-auth-summary-item">
            <CheckCircleIcon className="h-5 w-5" />
            <div>
              <span>الدور</span>
              <strong>{roleLabels[invitation.role] || invitation.role}</strong>
            </div>
          </div>
        </div>
      ) : null}

      {error ? (
        <AuthNotice variant="error" title="تعذر قبول الدعوة">
          {error}
        </AuthNotice>
      ) : null}

      <form onSubmit={handleSubmit} className="business-auth-form">
        <div className="business-auth-field">
          <label htmlFor="password" className="business-auth-label">
            كلمة المرور
          </label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(event) => setPassword(event.target.value)}
            className="business-auth-input"
            placeholder="أدخل كلمة المرور (6 أحرف على الأقل)"
            disabled={submitting}
          />
        </div>

        <div className="business-auth-field">
          <label htmlFor="confirmPassword" className="business-auth-label">
            تأكيد كلمة المرور
          </label>
          <input
            id="confirmPassword"
            type="password"
            value={confirmPassword}
            onChange={(event) => setConfirmPassword(event.target.value)}
            className="business-auth-input"
            placeholder="أعد إدخال كلمة المرور"
            disabled={submitting}
          />
        </div>

        <button
          type="submit"
          disabled={submitting}
          className="business-primary-button"
        >
          {submitting ? "جاري إنشاء الحساب..." : "قبول الدعوة وإنشاء الحساب"}
        </button>
      </form>
    </AuthSurface>
  );
};

export default AcceptInvitation;

import React, { useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import LoadingSpinner from "../../components/LoadingSpinner";
import { tokenManager } from "../../utils/tokenManager";
import { AuthNotice, AuthSurface } from "../../components/auth/AuthSurface";

const CustomerRegister: React.FC = () => {
  const navigate = useNavigate();
  const params = useParams();
  const [phone, setPhone] = useState("");
  const [code, setCode] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [step, setStep] = useState<"PHONE" | "OTP">("PHONE");

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();

    try {
      setIsLoading(true);
      setError("");
      setSuccessMessage("");

      const searchParams = new URLSearchParams(window.location.search);
      const companyIdFromQuery = searchParams.get("companyId");
      const companyIdFromPath =
        typeof params.companyId === "string" ? params.companyId : null;
      const companyIdFromStorage = localStorage.getItem("storefront_companyId");
      const companyId = (
        companyIdFromQuery ||
        companyIdFromPath ||
        companyIdFromStorage ||
        ""
      ).trim();

      if (companyIdFromQuery) {
        localStorage.setItem("storefront_companyId", companyIdFromQuery);
      }

      if (!companyIdFromQuery && companyIdFromPath) {
        localStorage.setItem("storefront_companyId", companyIdFromPath);
      }

      const normalizedPhone = phone.trim();
      if (!normalizedPhone) {
        throw new Error("رقم الهاتف مطلوب");
      }

      if (!companyId) {
        throw new Error(
          "لا يمكن تحديد الشركة. افتح الرابط من داخل متجر الشركة أو أضف companyId إلى الرابط.",
        );
      }

      if (step === "PHONE") {
        const response = await apiClient.post(
          `/public/customers/request-otp?companyId=${encodeURIComponent(companyId)}`,
          { phone: normalizedPhone },
        );

        if (response.data?.success) {
          setSuccessMessage("تم إرسال كود التحقق على واتساب");
          setStep("OTP");
          return;
        }

        setError(response.data?.message || "تعذر إرسال كود التحقق");
        return;
      }

      const normalizedCode = code.trim();
      if (!normalizedCode || normalizedCode.length !== 4) {
        throw new Error("يرجى إدخال كود مكوّن من 4 أرقام");
      }

      const response = await apiClient.post(
        `/public/customers/verify-otp?companyId=${encodeURIComponent(companyId)}`,
        {
          phone: normalizedPhone,
          code: normalizedCode,
        },
      );

      if (response.data?.success && response.data?.data?.token) {
        tokenManager.setAccessToken(response.data.data.token);
        setSuccessMessage("تم تسجيل الدخول بنجاح");
        navigate("/account/whatsapp");
        return;
      }

      setError(response.data?.message || "تعذر تسجيل الدخول");
    } catch (err: any) {
      setError(
        err.response?.data?.message || err.message || "حدث خطأ أثناء التسجيل",
      );
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthSurface
      title="دخول العملاء"
      description="سجّل دخولك برقم واتساب المرتبط بالحساب للوصول السريع والآمن إلى تفاعلاتك وخدماتك."
      eyebrow="Customer Access"
      footer={
        <div className="business-auth-footer-stack">
          <div className="business-auth-link-row">
            <span>لديك حساب شركة للوحة التحكم؟</span>
            <Link to="/auth/login">تسجيل الدخول للمنصة</Link>
          </div>
          <p className="business-auth-legal">
            تسجيل دخول العملاء يعتمد على أرقام واتساب الموثقة داخل النظام.
          </p>
        </div>
      }
    >
      {error ? (
        <AuthNotice variant="error" title="تعذر إكمال العملية">
          {error}
        </AuthNotice>
      ) : null}

      {successMessage ? (
        <AuthNotice variant="success" title="تم التنفيذ">
          {successMessage}
        </AuthNotice>
      ) : null}

      <form onSubmit={handleSubmit} className="business-auth-form">
        <div className="business-auth-field">
          <label htmlFor="phone" className="business-auth-label">
            رقم الهاتف المرتبط بواتساب
          </label>
          <input
            id="phone"
            name="phone"
            type="tel"
            value={phone}
            onChange={(event) => {
              setPhone(event.target.value);
              if (error) setError("");
            }}
            required
            className="business-auth-input business-auth-input--ltr"
            placeholder="01xxxxxxxxx"
            disabled={isLoading || step === "OTP"}
          />
        </div>

        {step === "OTP" ? (
          <div className="business-auth-field">
            <label htmlFor="code" className="business-auth-label">
              كود التحقق
            </label>
            <input
              id="code"
              name="code"
              type="text"
              inputMode="numeric"
              value={code}
              onChange={(event) => {
                setCode(event.target.value);
                if (error) setError("");
              }}
              required
              className="business-auth-input business-auth-code-input"
              placeholder="1234"
              maxLength={4}
              disabled={isLoading}
            />
          </div>
        ) : null}

        <button
          type="submit"
          disabled={isLoading}
          className="business-primary-button"
        >
          {isLoading ? (
            <span className="business-inline-loader">
              <LoadingSpinner size="sm" color="white" />
              <span>جاري التحقق...</span>
            </span>
          ) : step === "PHONE" ? (
            "إرسال كود واتساب"
          ) : (
            "تأكيد الدخول"
          )}
        </button>
      </form>
    </AuthSurface>
  );
};

export default CustomerRegister;

import React, { useState } from "react";
import { Link } from "react-router-dom";
import { useForm } from "react-hook-form";
import { ArrowRightIcon, KeyIcon } from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import { apiClient } from "../../services/apiClient";
import LoadingSpinner from "../../components/ui/LoadingSpinner";
import { AuthNotice, AuthSurface } from "../../components/auth/AuthSurface";

interface ForgotPasswordFormData {
  email: string;
}

const ForgotPassword: React.FC = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
    setError,
    getValues,
  } = useForm<ForgotPasswordFormData>({
    defaultValues: {
      email: "",
    },
  });

  const onSubmit = async (data: ForgotPasswordFormData) => {
    try {
      setIsLoading(true);
      await apiClient.post("/auth/forgot-password", data);
      setIsSubmitted(true);
      toast.success("تم إرسال رابط إعادة تعيين كلمة المرور");
    } catch (error: any) {
      const message =
        error.response?.data?.error?.message ||
        "فشل في إرسال رابط إعادة التعيين";
      setError("root", { message });
    } finally {
      setIsLoading(false);
    }
  };

  const handleResend = async () => {
    const email = getValues("email");
    if (email) {
      await onSubmit({ email });
    }
  };

  if (isSubmitted) {
    return (
      <AuthSurface
        title="تم إرسال الرابط"
        description="أرسلنا رابط إعادة تعيين كلمة المرور إلى بريدك الإلكتروني المسجل."
        eyebrow="Recovery Sent"
        icon={<KeyIcon className="h-7 w-7" />}
      >
        <AuthNotice variant="info" title="قبل المتابعة">
          <div className="business-auth-list">
            <span>تحقق من صندوق البريد الوارد.</span>
            <span>راجع مجلد الرسائل المزعجة إذا لم تصلك الرسالة.</span>
            <span>الرابط صالح لمدة ساعة واحدة فقط.</span>
          </div>
        </AuthNotice>

        <div className="business-auth-actions">
          <button
            type="button"
            onClick={handleResend}
            disabled={isLoading}
            className="business-secondary-button"
          >
            {isLoading ? <LoadingSpinner size="sm" /> : "إعادة إرسال الرابط"}
          </button>

          <Link to="/auth/login" className="business-secondary-button">
            <ArrowRightIcon className="h-4 w-4" />
            <span>العودة إلى تسجيل الدخول</span>
          </Link>
        </div>
      </AuthSurface>
    );
  }

  return (
    <AuthSurface
      title="استعادة الوصول"
      description="أدخل بريدك الإلكتروني وسنرسل لك رابطًا آمنًا لإعادة تعيين كلمة المرور."
      eyebrow="Password Recovery"
      icon={<KeyIcon className="h-7 w-7" />}
      footer={
        <div className="business-auth-link-row">
          <Link to="/auth/login" className="business-auth-inline-link">
            <ArrowRightIcon className="h-4 w-4" />
            <span>العودة إلى تسجيل الدخول</span>
          </Link>
        </div>
      }
    >
      {errors.root ? (
        <AuthNotice variant="error" title="تعذر إرسال الرابط">
          {errors.root.message}
        </AuthNotice>
      ) : null}

      <form className="business-auth-form" onSubmit={handleSubmit(onSubmit)}>
        <div className="business-auth-field">
          <label htmlFor="email" className="business-auth-label">
            البريد الإلكتروني
          </label>
          <input
            {...register("email", {
              required: "البريد الإلكتروني مطلوب",
              pattern: {
                value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
                message: "يرجى إدخال بريد إلكتروني صحيح",
              },
            })}
            id="email"
            type="email"
            autoComplete="email"
            className="business-auth-input"
            placeholder="name@company.com"
          />
          {errors.email ? (
            <p className="business-auth-error">{errors.email.message}</p>
          ) : null}
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="business-primary-button"
        >
          {isLoading ? (
            <span className="business-inline-loader">
              <LoadingSpinner size="sm" color="white" />
              <span>جاري الإرسال...</span>
            </span>
          ) : (
            "إرسال رابط إعادة التعيين"
          )}
        </button>
      </form>
    </AuthSurface>
  );
};

