import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../../hooks/useAuthSimple";
import { AuthNotice, AuthSurface } from "../../components/auth/AuthSurface";
import { trackPlatformSiteLogin } from "../../utils/platformSiteMetaPixel";
import { companyNeedsOnboarding, getPostAuthDestination } from "../../utils/companyOnboarding";

interface LoginFormData {
  email: string;
  password: string;
  rememberMe: boolean;
}

const ModernLogin: React.FC = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [formData, setFormData] = useState<LoginFormData>({
    email: "",
    password: "",
    rememberMe: false,
  });

  const { login, isAuthenticated, isLoading: isAuthLoading, user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from?.pathname || "/company-dashboard";

  useEffect(() => {
    if (!isAuthLoading && isAuthenticated && user) {
      navigate(getPostAuthDestination(user), {
        replace: true,
      });
    }
  }, [isAuthenticated, isAuthLoading, navigate, user]);

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value, type, checked } = event.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));

    if (error) setError("");
    if (success) setSuccess("");
  };

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();

    if (!formData.email || !formData.password) {
      setError("يرجى ملء جميع الحقول المطلوبة");
      return;
    }

    if (!formData.email.includes("@")) {
      setError("يرجى إدخال بريد إلكتروني صحيح");
      return;
    }

    try {
      setIsLoading(true);
      setError("");
      setSuccess("جاري تأكيد بيانات الدخول…");

      const userData = await login(formData);
      const postAuthDestination = getPostAuthDestination(userData);
      const redirectPath =
        postAuthDestination === "/company-dashboard" &&
        from &&
        from !== "/company-dashboard" &&
        !companyNeedsOnboarding(userData?.company)
          ? from
          : postAuthDestination;

      setSuccess("تم تسجيل الدخول بنجاح، يتم تحويلك الآن…");
      trackPlatformSiteLogin({
        destination: redirectPath,
        role: userData?.role || "UNKNOWN",
      });
      setTimeout(() => navigate(redirectPath, { replace: true }), 800);
    } catch (err: any) {
      setError(
        err.message ||
          "فشل في تسجيل الدخول. يرجى التحقق من البيانات والمحاولة مرة أخرى",
      );
      setSuccess("");
    } finally {
      setIsLoading(false);
    }
  };

  if (isAuthLoading || (isAuthenticated && user)) {
    return (
      <AuthSurface
        title="جاري التحقق من الجلسة"
        description="نراجع حالة الحساب ونجهّز مساحة العمل المناسبة لك."
        eyebrow="Session Check"
      >
        <div className="business-auth-loader-block">
          <div className="business-auth-loader" />
          <p>ثوانٍ قليلة ويتم توجيهك تلقائيًا.</p>
        </div>
      </AuthSurface>
    );
  }

  return (
    <AuthSurface
      title="الدخول إلى مساحة العمل"
      description="أدخل بريدك وكلمة المرور للوصول إلى لوحة التشغيل الخاصة بك."
      eyebrow="Secure Sign In"
      className="business-auth-panel--login"
      footer={
        <div className="business-auth-footer-stack">
          <div className="business-auth-link-row">
            <span>ليس لديك حساب؟</span>
            <Link to="/auth/register">إنشاء حساب جديد</Link>
          </div>
          <p className="business-auth-legal">
            بتسجيل الدخول، أنت توافق على شروط الخدمة وسياسة الخصوصية.
          </p>
        </div>
      }
    >
      {success ? (
        <AuthNotice variant="success" title="تم التحقق">
          {success}
        </AuthNotice>
      ) : null}

      {error ? (
        <AuthNotice variant="error" title="تعذر تسجيل الدخول">
          {error}
        </AuthNotice>
      ) : null}

      <form onSubmit={handleSubmit} className="business-auth-form">
        <div className="business-auth-field">
          <label htmlFor="email" className="business-auth-label">
            البريد الإلكتروني
          </label>
          <input
            id="email"
            name="email"
            type="email"
            value={formData.email}
            onChange={handleChange}
            autoComplete="email"
            spellCheck={false}
            required
            className="business-auth-input"
            placeholder="name@company.com"
            dir="ltr"
          />
        </div>

        <div className="business-auth-field">
          <label htmlFor="password" className="business-auth-label">
            كلمة المرور
          </label>
          <input
            id="password"
            name="password"
            type="password"
            value={formData.password}
            onChange={handleChange}
            autoComplete="current-password"
            required
            className="business-auth-input"
            placeholder="••••••••"
          />
        </div>

        <div className="business-auth-inline-row">
          <Link
            to="/auth/forgot-password"
            className="business-auth-inline-link"
          >
            نسيت كلمة المرور؟
          </Link>

          <label htmlFor="remember-me" className="business-auth-checkbox">
            <input
              id="remember-me"
              name="rememberMe"
              type="checkbox"
              checked={formData.rememberMe}
              onChange={handleChange}
            />
            <span>تذكرني</span>
          </label>
        </div>

        <button
          type="submit"
          disabled={isLoading || !formData.email || !formData.password}
          className="business-primary-button"
        >
          {isLoading ? "جاري تسجيل الدخول..." : "دخول إلى النظام"}
        </button>
      </form>
    </AuthSurface>
  );
};

export default ModernLogin;

import React, { useEffect, useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { useForm } from "react-hook-form";
import {
  CheckIcon,
  EyeIcon,
  EyeSlashIcon,
  LockClosedIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import { apiClient } from "../../services/apiClient";
import LoadingSpinner from "../../components/ui/LoadingSpinner";
import { AuthNotice, AuthSurface } from "../../components/auth/AuthSurface";

interface ResetPasswordFormData {
  password: string;
  confirmPassword: string;
}

const passwordRules = [
  {
    id: "length",
    label: "8 أحرف على الأقل",
    test: (password: string) => password.length >= 8,
  },
  {
    id: "upper",
    label: "حرف كبير واحد على الأقل",
    test: (password: string) => /[A-Z]/.test(password),
  },
  {
    id: "lower",
    label: "حرف صغير واحد على الأقل",
    test: (password: string) => /[a-z]/.test(password),
  },
  {
    id: "number",
    label: "رقم واحد على الأقل",
    test: (password: string) => /\d/.test(password),
  },
  {
    id: "symbol",
    label: "رمز خاص واحد على الأقل",
    test: (password: string) => /[@$!%*?&]/.test(password),
  },
];

const ResetPassword: React.FC = () => {
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const token = searchParams.get("token");

  const {
    register,
    handleSubmit,
    formState: { errors },
    setError,
    watch,
  } = useForm<ResetPasswordFormData>({
    defaultValues: {
      password: "",
      confirmPassword: "",
    },
  });

  const password = watch("password");

  useEffect(() => {
    if (!token) {
      toast.error("رمز إعادة التعيين غير صحيح");
      navigate("/auth/forgot-password");
    }
  }, [navigate, token]);

  const onSubmit = async (data: ResetPasswordFormData) => {
    try {
      setIsLoading(true);

      await apiClient.post("/auth/reset-password", {
        token,
        password: data.password,
      });

      setIsSuccess(true);
      toast.success("تم إعادة تعيين كلمة المرور بنجاح");
      setTimeout(() => navigate("/auth/login"), 2000);
    } catch (error: any) {
      const message =
        error.response?.data?.error?.message ||
        "فشل في إعادة تعيين كلمة المرور";
      setError("root", { message });
    } finally {
      setIsLoading(false);
    }
  };

  if (!token) {
    return null;
  }

  if (isSuccess) {
    return (
      <AuthSurface
        title="تم تحديث كلمة المرور"
        description="أصبح بإمكانك الآن تسجيل الدخول باستخدام كلمة المرور الجديدة."
        eyebrow="Password Updated"
        icon={<CheckIcon className="h-7 w-7" />}
      >
        <div className="business-auth-actions">
          <Link to="/auth/login" className="business-primary-button">
            الذهاب إلى تسجيل الدخول
          </Link>
        </div>
      </AuthSurface>
    );
  }

  return (
    <AuthSurface
      title="إعادة تعيين كلمة المرور"
      description="اختر كلمة مرور قوية لتأمين الوصول إلى مساحة العمل الجديدة."
      eyebrow="Set New Password"
      icon={<LockClosedIcon className="h-7 w-7" />}
      footer={
        <div className="business-auth-link-row">
          <Link to="/auth/login">العودة إلى تسجيل الدخول</Link>
        </div>
      }
    >
      {errors.root ? (
        <AuthNotice variant="error" title="تعذر تحديث كلمة المرور">
          {errors.root.message}
        </AuthNotice>
      ) : null}

      <form className="business-auth-form" onSubmit={handleSubmit(onSubmit)}>
        <div className="business-auth-field">
          <label htmlFor="password" className="business-auth-label">
            كلمة المرور الجديدة
          </label>
          <div className="business-auth-password-wrap">
            <input
              {...register("password", {
                required: "كلمة المرور مطلوبة",
                minLength: {
                  value: 8,
                  message: "كلمة المرور يجب أن تكون 8 أحرف على الأقل",
                },
                pattern: {
                  value:
                    /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/,
                  message:
                    "كلمة المرور يجب أن تحتوي على حروف كبيرة وصغيرة وأرقام ورموز",
                },
              })}
              id="password"
              type={showPassword ? "text" : "password"}
              autoComplete="new-password"
              className="business-auth-input"
              placeholder="أدخل كلمة مرور قوية"
            />
            <button
              type="button"
              className="business-auth-password-toggle"
              onClick={() => setShowPassword((prev) => !prev)}
            >
              {showPassword ? (
                <EyeSlashIcon className="h-5 w-5" />
              ) : (
                <EyeIcon className="h-5 w-5" />
              )}
            </button>
          </div>
          {errors.password ? (
            <p className="business-auth-error">{errors.password.message}</p>
          ) : null}
        </div>

        <div className="business-auth-field">
          <label htmlFor="confirmPassword" className="business-auth-label">
            تأكيد كلمة المرور
          </label>
          <div className="business-auth-password-wrap">
            <input
              {...register("confirmPassword", {
                required: "تأكيد كلمة المرور مطلوب",
                validate: (value) =>
                  value === password || "كلمتا المرور غير متطابقتين",
              })}
              id="confirmPassword"
              type={showConfirmPassword ? "text" : "password"}
              autoComplete="new-password"
              className="business-auth-input"
              placeholder="أعد إدخال كلمة المرور"
            />
            <button
              type="button"
              className="business-auth-password-toggle"
              onClick={() => setShowConfirmPassword((prev) => !prev)}
            >
              {showConfirmPassword ? (
                <EyeSlashIcon className="h-5 w-5" />
              ) : (
                <EyeIcon className="h-5 w-5" />
              )}
            </button>
          </div>
          {errors.confirmPassword ? (
            <p className="business-auth-error">
              {errors.confirmPassword.message}
            </p>
          ) : null}
        </div>

        <div className="business-auth-requirements">
          <h4>متطلبات كلمة المرور</h4>
          <div className="business-auth-requirement-list">
            {passwordRules.map((rule) => (
              <div
                key={rule.id}
                className="business-auth-requirement"
                data-met={rule.test(password)}
              >
                <span className="business-auth-requirement-dot" />
                <span>{rule.label}</span>
              </div>
            ))}
          </div>
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="business-primary-button"
        >
          {isLoading ? (
            <span className="business-inline-loader">
              <LoadingSpinner size="sm" color="white" />
              <span>جاري إعادة التعيين...</span>
            </span>
          ) : (
            "إعادة تعيين كلمة المرور"
          )}
        </button>
      </form>
    </AuthSurface>
  );
};

export default ResetPassword;

import React, { useState } from "react";
import { useAuth } from "../../hooks/useAuthSimple";

const SimpleLogin: React.FC = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { login } = useAuth();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const userData = await login({ email, password });

      // Determine redirect path based on user role
      let redirectPath = "/conversations-improved";

      if (userData) {
        // Check user role and redirect accordingly
        if (userData.role === "SUPER_ADMIN") {
          redirectPath = "/super-admin/dashboard";
        } else {
          // Company members go to company dashboard
          redirectPath = "/company-dashboard";
        }
      }

      // إعادة توجيه حسب دور المستخدم
      window.location.href = redirectPath;
    } catch (error: any) {
      setError(error.message || "فشل في تسجيل الدخول");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8">
