                  </div>
                </div>

                <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <ClockIcon className="h-6 w-6 text-blue-400 dark:text-blue-500" />
                      </div>
                      <div className="mr-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-semibold text-gray-700 dark:text-gray-400 truncate">
                            الحملات النشطة
                          </dt>
                          <dd className="text-2xl font-black text-gray-900 dark:text-white">
                            {stats.activeCampaigns}
                          </dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <UserGroupIcon className="h-6 w-6 text-green-400 dark:text-green-500" />
                      </div>
                      <div className="mr-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-semibold text-gray-700 dark:text-gray-400 truncate">
                            إجمالي المستلمين
                          </dt>
                          <dd className="text-2xl font-black text-gray-900 dark:text-white">
                            {stats.totalRecipients.toLocaleString()}
                          </dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <EyeIcon className="h-6 w-6 text-indigo-400 dark:text-indigo-500" />
                      </div>
                      <div className="mr-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-semibold text-gray-700 dark:text-gray-400 truncate">
                            متوسط معدل الفتح
                          </dt>
                          <dd className="text-2xl font-black text-gray-900 dark:text-white">
                            {stats.averageOpenRate}%
                          </dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <ChatBubbleLeftRightIcon className="h-6 w-6 text-purple-400 dark:text-purple-500" />
                      </div>
                      <div className="mr-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-semibold text-gray-700 dark:text-gray-400 truncate">
                            متوسط معدل النقر
                          </dt>
                          <dd className="text-2xl font-black text-gray-900 dark:text-white">
                            {stats.averageClickRate}%
                          </dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <ArrowTrendingUpIcon className="h-6 w-6 text-orange-400 dark:text-orange-500" />
                      </div>
                      <div className="mr-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-semibold text-gray-700 dark:text-gray-400 truncate">
                            حملات هذا الشهر
                          </dt>
                          <dd className="text-2xl font-black text-gray-900 dark:text-white">
                            {stats.campaignsThisMonth}
                          </dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Recent Campaigns */}
            <div className="bg-white dark:bg-gray-800 shadow overflow-hidden sm:rounded-md">
              <div className="px-4 py-5 sm:px-6">
                <h3 className="text-xl font-black text-gray-900 dark:text-white">
                  الحملات الأخيرة
                </h3>
                <p className="text-lg font-bold text-gray-700 dark:text-gray-200">
                  آخر الحملات التي تم إنشاؤها أو تنفيذها
                </p>
              </div>
              <ul className="divide-y divide-gray-200 dark:divide-gray-700">
                {campaigns.slice(0, 5).map((campaign) => (
                  <li key={campaign.id}>
                    <div className="px-4 py-4 sm:px-6">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center">
                          <div className="flex-shrink-0">
                            <MegaphoneIcon className="h-6 w-6 text-gray-400 dark:text-gray-500" />
                          </div>
                          <div className="mr-4">
                            <p className="text-base font-semibold text-gray-900 dark:text-white">
                              {campaign.name}
                            </p>
                            <p className="text-base font-medium text-gray-700 dark:text-gray-200">
                              {campaign.recipientCount} مستلم •{" "}
                              {formatDate(campaign.createdAt)}
                            </p>
                          </div>
                        </div>
                        <div className="flex items-center space-x-2 space-x-reverse">
                          <span
                            className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(campaign.status)}`}
                          >
                            {getStatusText(campaign.status)}
                          </span>
                          {campaign.openRate && (
                            <span className="text-base font-semibold text-gray-500 dark:text-gray-400">
                              {campaign.openRate}% فتح
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {activeTab === "create" && <CreateCampaign />}

        {activeTab === "scheduled" && <ScheduledCampaigns />}

        {activeTab === "analytics" && <CampaignAnalytics />}

        {activeTab === "lists" && <CustomerListsManager />}

        {activeTab === "settings" && <BroadcastSettings />}
      </div>
    </div>
  );
};

export default BroadcastDashboard;

import React, { useState, useEffect } from "react";
import {
  Cog6ToothIcon,
  ClockIcon,
  BellIcon,
  ShieldCheckIcon,
  EnvelopeIcon,
  ChartBarIcon,
  ExclamationTriangleIcon,
  CheckCircleIcon,
} from "@heroicons/react/24/outline";
import { broadcastService } from "../../services/broadcastService";

interface BroadcastSettings {
  // General Settings
  defaultSendTime: string;
  timezone: string;
  maxRecipientsPerCampaign: number;
  maxCampaignsPerDay: number;

  // Delivery Settings
  enableDeliveryReports: boolean;
  enableOpenTracking: boolean;
  enableClickTracking: boolean;
  enableUnsubscribeTracking: boolean;

  // Notification Settings
  notifyOnCampaignSent: boolean;
  notifyOnHighUnsubscribeRate: boolean;
  notifyOnLowDeliveryRate: boolean;
  adminEmail: string;

  // Security Settings
  requireApprovalForHighVolume: boolean;
  highVolumeThreshold: number;
  enableContentFiltering: boolean;
  blockedWords: string[];

  // Rate Limiting
  messagesPerMinute: number;
  messagesPerHour: number;
  messagesPerDay: number;

  // Templates
  defaultFooter: string;
  unsubscribeText: string;
  companyName: string;
  companyAddress: string;
}

const BroadcastSettings: React.FC = () => {
  const [settings, setSettings] = useState<BroadcastSettings>({
    // General Settings
    defaultSendTime: "10:00",
    timezone: "Asia/Riyadh",
    maxRecipientsPerCampaign: 5000,
    maxCampaignsPerDay: 10,

    // Delivery Settings
    enableDeliveryReports: true,
    enableOpenTracking: true,
    enableClickTracking: true,
    enableUnsubscribeTracking: true,

    // Notification Settings
    notifyOnCampaignSent: true,
    notifyOnHighUnsubscribeRate: true,
    notifyOnLowDeliveryRate: true,
    adminEmail: "admin@company.com",

    // Security Settings
    requireApprovalForHighVolume: true,
    highVolumeThreshold: 1000,
    enableContentFiltering: true,
    blockedWords: ["spam", "fake", "scam"],

    // Rate Limiting
    messagesPerMinute: 100,
    messagesPerHour: 1000,
    messagesPerDay: 10000,

    // Templates
    defaultFooter: "شكراً لك على اشتراكك في خدماتنا",
    unsubscribeText: "لإلغاء الاشتراك، اضغط هنا",
    companyName: "شركة التواصل",
    companyAddress: "الرياض، المملكة العربية السعودية",
  });

  const [activeSection, setActiveSection] = useState<
    "general" | "delivery" | "notifications" | "security" | "templates"
  >("general");
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newBlockedWord, setNewBlockedWord] = useState("");

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      console.log("⚙️ Loading broadcast settings...");
      const response = await broadcastService.getSettings();
      console.log("⚙️ Settings response:", response);

      // Handle different response formats
      let settingsData = null;
      if (response && typeof response === "object") {
        if ("data" in response) {
          settingsData = (response as any).data;
        } else if ("success" in response && "data" in response) {
          settingsData = (response as any).data;
        } else {
          settingsData = response;
        }
      }

      if (settingsData) {
        setSettings(settingsData);
      }
    } catch (error) {
      console.error("Error loading settings:", error);
      // Keep default settings if loading fails
    }
  };

  const handleInputChange = (
    e: React.ChangeEvent<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >,
  ) => {
    const { name, value, type } = e.target;

    if (type === "checkbox") {
      const checked = (e.target as HTMLInputElement).checked;
      setSettings((prev) => ({ ...prev, [name]: checked }));
    } else if (type === "number") {
      setSettings((prev) => ({ ...prev, [name]: parseInt(value) || 0 }));
    } else {
      setSettings((prev) => ({ ...prev, [name]: value }));
    }
  };

  const addBlockedWord = () => {
    if (
      newBlockedWord.trim() &&
      !settings.blockedWords.includes(newBlockedWord.trim())
    ) {
      setSettings((prev) => ({
        ...prev,
        blockedWords: [...prev.blockedWords, newBlockedWord.trim()],
      }));
      setNewBlockedWord("");
    }
  };

  const removeBlockedWord = (word: string) => {
    setSettings((prev) => ({
      ...prev,
      blockedWords: prev.blockedWords.filter((w) => w !== word),
    }));
  };

  const handleSave = async () => {
    try {
      setLoading(true);
      setError(null);

      console.log("💾 Saving broadcast settings:", settings);
      const updatedSettings = await broadcastService.updateSettings(settings);
      console.log("✅ Settings saved successfully:", updatedSettings);

      // Update local state with server response
      if (updatedSettings) {
        setSettings(updatedSettings);
      }

      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
    } catch (err: any) {
      console.error("❌ Error saving settings:", err);
      setError(err.message || "فشل في حفظ الإعدادات. يرجى المحاولة مرة أخرى.");
    } finally {
      setLoading(false);
    }
  };

  const sections = [
    { id: "general", name: "الإعدادات العامة", icon: Cog6ToothIcon },
    { id: "delivery", name: "إعدادات التسليم", icon: EnvelopeIcon },
    { id: "notifications", name: "التنبيهات", icon: BellIcon },
    { id: "security", name: "الأمان", icon: ShieldCheckIcon },
    { id: "templates", name: "القوالب", icon: ChartBarIcon },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">
            إعدادات البرودكاست
          </h3>
          <p className="mt-1 text-sm text-gray-500">
            إدارة إعدادات نظام الإرسال الجماعي والتحكم في سلوك النظام
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={loading}
          className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? (
            <>
              <ClockIcon className="h-4 w-4 ml-2 animate-spin" />
              جاري الحفظ...
            </>
          ) : (
            <>
              <CheckCircleIcon className="h-4 w-4 ml-2" />
              حفظ الإعدادات
            </>
          )}
        </button>
      </div>

      {/* Success/Error Messages */}
      {success && (
        <div className="bg-green-50 border border-green-200 rounded-md p-4">
          <div className="flex">
            <CheckCircleIcon className="h-5 w-5 text-green-400" />
            <div className="mr-3">
              <p className="text-sm text-green-800">تم حفظ الإعدادات بنجاح!</p>
            </div>
          </div>
        </div>
      )}

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-md p-4">
          <div className="flex">
            <ExclamationTriangleIcon className="h-5 w-5 text-red-400" />
            <div className="mr-3">
              <p className="text-sm text-red-800">{error}</p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 shadow sm:rounded-lg">
        <div className="flex">
          {/* Sidebar */}
          <div className="w-64 bg-gray-50 dark:bg-gray-700 rounded-r-lg">
            <nav className="p-4 space-y-2">
              {sections.map((section) => {
                const Icon = section.icon;
                return (
                  <button
                    key={section.id}
                    onClick={() => setActiveSection(section.id as any)}
                    className={`w-full flex items-center px-3 py-2 text-sm font-medium rounded-md ${
                      activeSection === section.id
                        ? "bg-indigo-100 text-indigo-700 dark:bg-indigo-900 dark:text-indigo-200"
                        : "text-gray-600 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-600"
                    }`}
                  >
                    <Icon className="h-5 w-5 ml-3" />
                    {section.name}
                  </button>
                );
              })}
            </nav>
          </div>

          {/* Content */}
          <div className="flex-1 p-6">
            {activeSection === "general" && (
              <div className="space-y-6">
                <h4 className="text-lg font-medium text-gray-900 dark:text-white">
                  الإعدادات العامة
                </h4>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      وقت الإرسال الافتراضي
                    </label>
                    <input
                      type="time"
                      name="defaultSendTime"
                      value={settings.defaultSendTime}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      المنطقة الزمنية
                    </label>
                    <select
                      name="timezone"
                      value={settings.timezone}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    >
                      <option value="Asia/Riyadh">الرياض (GMT+3)</option>
                      <option value="Asia/Dubai">دبي (GMT+4)</option>
                      <option value="Africa/Cairo">القاهرة (GMT+2)</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      الحد الأقصى للمستلمين لكل حملة
                    </label>
                    <input
                      type="number"
                      name="maxRecipientsPerCampaign"
                      value={settings.maxRecipientsPerCampaign}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      الحد الأقصى للحملات يومياً
                    </label>
                    <input
                      type="number"
                      name="maxCampaignsPerDay"
                      value={settings.maxCampaignsPerDay}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>
                </div>
              </div>
            )}

            {activeSection === "delivery" && (
              <div className="space-y-6">
                <h4 className="text-lg font-medium text-gray-900 dark:text-white">
                  إعدادات التسليم
                </h4>

                <div className="space-y-4">
                  <div className="flex items-center">
                    <input
                      id="enableDeliveryReports"
                      name="enableDeliveryReports"
                      type="checkbox"
                      checked={settings.enableDeliveryReports}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="enableDeliveryReports"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      تفعيل تقارير التسليم
                    </label>
                  </div>

                  <div className="flex items-center">
                    <input
                      id="enableOpenTracking"
                      name="enableOpenTracking"
                      type="checkbox"
                      checked={settings.enableOpenTracking}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="enableOpenTracking"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      تتبع فتح الرسائل
                    </label>
                  </div>

                  <div className="flex items-center">
                    <input
                      id="enableClickTracking"
                      name="enableClickTracking"
                      type="checkbox"
                      checked={settings.enableClickTracking}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="enableClickTracking"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      تتبع النقرات
                    </label>
                  </div>

                  <div className="flex items-center">
                    <input
                      id="enableUnsubscribeTracking"
                      name="enableUnsubscribeTracking"
                      type="checkbox"
                      checked={settings.enableUnsubscribeTracking}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="enableUnsubscribeTracking"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      تتبع إلغاء الاشتراك
                    </label>
                  </div>
                </div>

                <div className="border-t pt-6">
                  <h5 className="text-md font-medium text-gray-900 dark:text-white mb-4">
                    حدود معدل الإرسال
                  </h5>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                        رسائل في الدقيقة
                      </label>
                      <input
                        type="number"
                        name="messagesPerMinute"
                        value={settings.messagesPerMinute}
                        onChange={handleInputChange}
                        className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                        رسائل في الساعة
                      </label>
                      <input
                        type="number"
                        name="messagesPerHour"
                        value={settings.messagesPerHour}
                        onChange={handleInputChange}
                        className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                        رسائل في اليوم
                      </label>
                      <input
                        type="number"
                        name="messagesPerDay"
                        value={settings.messagesPerDay}
                        onChange={handleInputChange}
                        className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                      />
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeSection === "notifications" && (
              <div className="space-y-6">
                <h4 className="text-lg font-medium text-gray-900 dark:text-white">
                  إعدادات التنبيهات
                </h4>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    البريد الإلكتروني للمدير
                  </label>
                  <input
                    type="email"
                    name="adminEmail"
                    value={settings.adminEmail}
                    onChange={handleInputChange}
                    className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                  />
                </div>

                <div className="space-y-4">
                  <div className="flex items-center">
                    <input
                      id="notifyOnCampaignSent"
                      name="notifyOnCampaignSent"
                      type="checkbox"
                      checked={settings.notifyOnCampaignSent}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="notifyOnCampaignSent"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      إشعار عند إرسال الحملة
                    </label>
                  </div>

                  <div className="flex items-center">
                    <input
                      id="notifyOnHighUnsubscribeRate"
                      name="notifyOnHighUnsubscribeRate"
                      type="checkbox"
                      checked={settings.notifyOnHighUnsubscribeRate}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="notifyOnHighUnsubscribeRate"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      إشعار عند ارتفاع معدل إلغاء الاشتراك
                    </label>
                  </div>

                  <div className="flex items-center">
                    <input
                      id="notifyOnLowDeliveryRate"
                      name="notifyOnLowDeliveryRate"
                      type="checkbox"
                      checked={settings.notifyOnLowDeliveryRate}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="notifyOnLowDeliveryRate"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      إشعار عند انخفاض معدل التسليم
                    </label>
                  </div>
                </div>
              </div>
            )}

            {activeSection === "security" && (
              <div className="space-y-6">
                <h4 className="text-lg font-medium text-gray-900 dark:text-white">
                  إعدادات الأمان
                </h4>

                <div className="space-y-4">
                  <div className="flex items-center">
                    <input
                      id="requireApprovalForHighVolume"
                      name="requireApprovalForHighVolume"
                      type="checkbox"
                      checked={settings.requireApprovalForHighVolume}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="requireApprovalForHighVolume"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      طلب موافقة للحملات عالية الحجم
                    </label>
