                    </label>
                    <input
                      type="number"
                      name="highVolumeThreshold"
                      value={settings.highVolumeThreshold}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>

                  <div className="flex items-center">
                    <input
                      id="enableContentFiltering"
                      name="enableContentFiltering"
                      type="checkbox"
                      checked={settings.enableContentFiltering}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                    <label
                      htmlFor="enableContentFiltering"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      تفعيل تصفية المحتوى
                    </label>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      الكلمات المحظورة
                    </label>
                    <div className="mt-1 flex items-center space-x-2 space-x-reverse">
                      <input
                        type="text"
                        value={newBlockedWord}
                        onChange={(e) => setNewBlockedWord(e.target.value)}
                        onKeyPress={(e) =>
                          e.key === "Enter" &&
                          (e.preventDefault(), addBlockedWord())
                        }
                        className="flex-1 border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                        placeholder="أضف كلمة محظورة"
                      />
                      <button
                        type="button"
                        onClick={addBlockedWord}
                        className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700"
                      >
                        إضافة
                      </button>
                    </div>
                    {settings.blockedWords.length > 0 && (
                      <div className="mt-2 flex flex-wrap gap-2">
                        {settings.blockedWords.map((word, index) => (
                          <span
                            key={index}
                            className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800"
                          >
                            {word}
                            <button
                              type="button"
                              onClick={() => removeBlockedWord(word)}
                              className="mr-1 h-3 w-3 text-red-600 hover:text-red-800"
                            >
                              ×
                            </button>
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}

            {activeSection === "templates" && (
              <div className="space-y-6">
                <h4 className="text-lg font-medium text-gray-900 dark:text-white">
                  قوالب الرسائل
                </h4>

                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      اسم الشركة
                    </label>
                    <input
                      type="text"
                      name="companyName"
                      value={settings.companyName}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      عنوان الشركة
                    </label>
                    <input
                      type="text"
                      name="companyAddress"
                      value={settings.companyAddress}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      التذييل الافتراضي
                    </label>
                    <textarea
                      name="defaultFooter"
                      rows={3}
                      value={settings.defaultFooter}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                      نص إلغاء الاشتراك
                    </label>
                    <input
                      type="text"
                      name="unsubscribeText"
                      value={settings.unsubscribeText}
                      onChange={handleInputChange}
                      className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    />
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default BroadcastSettings;

import React, { useState, useEffect } from "react";
import { useDateFormat } from "../../hooks/useDateFormat";
import {
  ChartBarIcon,
  ArrowTrendingUpIcon,
  EyeIcon,
  UserGroupIcon,
} from "@heroicons/react/24/outline";
import { broadcastService } from "../../services/broadcastService";

interface CampaignMetrics {
  campaignId: string;
  campaignName: string;
  sentAt: string;
  recipientCount: number;
  deliveredCount: number;
  openedCount: number;
  clickedCount: number;
  repliedCount: number;
  unsubscribedCount: number;
  deliveryRate: number;
  openRate: number;
  clickRate: number;
  replyRate: number;
  unsubscribeRate: number;
  revenue?: number;
  conversions?: number;
}

interface AnalyticsData {
  totalCampaigns: number;
  totalRecipients: number;
  averageOpenRate: number;
  averageClickRate: number;
  totalRevenue: number;
  bestPerformingTime: string;
  campaignMetrics: CampaignMetrics[];
  timeSeriesData: {
    date: string;
    campaigns: number;
    opens: number;
    clicks: number;
    revenue: number;
  }[];
}

const CampaignAnalytics: React.FC = () => {
  const [analyticsData, setAnalyticsData] = useState<AnalyticsData | null>(
    null,
  );
  const [selectedPeriod, setSelectedPeriod] = useState<"7d" | "30d" | "90d">(
    "30d",
  );
  const [loading, setLoading] = useState(true);
  const { formatDate } = useDateFormat();

  useEffect(() => {
    loadAnalyticsData();
  }, [selectedPeriod]);

  const loadAnalyticsData = async () => {
    try {
      setLoading(true);

      console.log("📊 Loading analytics data for period:", selectedPeriod);
      const response = await broadcastService.getAnalytics(selectedPeriod);
      console.log("📊 Analytics response:", response);

      // Handle different response formats
      let analyticsData = null;
      if (response && typeof response === "object") {
        if ("data" in response) {
          analyticsData = (response as any).data;
        } else if ("success" in response && "data" in response) {
          analyticsData = (response as any).data;
        } else {
          analyticsData = response;
        }
      }

      if (analyticsData) {
        setAnalyticsData(analyticsData);
      } else {
        // Fallback to mock data if no data available
        const mockData: AnalyticsData = {
          totalCampaigns: 0,
          totalRecipients: 0,
          averageOpenRate: 0,
          averageClickRate: 0,
          totalRevenue: 0,
          bestPerformingTime: "10:00 صباحاً",
          campaignMetrics: [],
          timeSeriesData: [],
        };
        setAnalyticsData(mockData);
      }
    } catch (error) {
      console.error("Error loading analytics data:", error);
      // Fallback to empty data on error
      const emptyData: AnalyticsData = {
        totalCampaigns: 0,
        totalRecipients: 0,
        averageOpenRate: 0,
        averageClickRate: 0,
        totalRevenue: 0,
        bestPerformingTime: "10:00 صباحاً",
        campaignMetrics: [],
        timeSeriesData: [],
      };
      setAnalyticsData(emptyData);
    } finally {
      setLoading(false);
    }
  };

  const getPerformanceColor = (
    rate: number,
    type: "open" | "click" | "reply",
  ) => {
    const thresholds = {
      open: { good: 50, excellent: 70 },
      click: { good: 8, excellent: 15 },
      reply: { good: 1, excellent: 3 },
    };

    const threshold = thresholds[type];
    if (rate >= threshold.excellent) return "text-green-600 bg-green-100";
    if (rate >= threshold.good) return "text-yellow-600 bg-yellow-100";
    return "text-red-600 bg-red-100";
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("ar-SA", {
      style: "currency",
      currency: "SAR",
    }).format(amount);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  if (!analyticsData) {
    return (
      <div className="text-center py-12">
        <ChartBarIcon className="mx-auto h-12 w-12 text-gray-400" />
        <h3 className="mt-2 text-sm font-medium text-gray-900">
          لا توجد بيانات
        </h3>
        <p className="mt-1 text-sm text-gray-500">
          لم يتم العثور على بيانات إحصائية
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Period Selector */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">
          إحصائيات الحملات
        </h3>
        <div className="flex items-center space-x-2 space-x-reverse">
          <label className="text-sm text-gray-500">الفترة:</label>
          <select
            value={selectedPeriod}
            onChange={(e) =>
              setSelectedPeriod(e.target.value as "7d" | "30d" | "90d")
            }
            className="border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 text-sm"
          >
            <option value="7d">آخر 7 أيام</option>
            <option value="30d">آخر 30 يوم</option>
            <option value="90d">آخر 90 يوم</option>
          </select>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
          <div className="p-5">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <ChartBarIcon className="h-6 w-6 text-indigo-400" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">
                    إجمالي الحملات
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {analyticsData.totalCampaigns}
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
          <div className="p-5">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <UserGroupIcon className="h-6 w-6 text-blue-400" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">
                    إجمالي المستلمين
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {analyticsData.totalRecipients.toLocaleString()}
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
          <div className="p-5">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <EyeIcon className="h-6 w-6 text-green-400" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">
                    متوسط معدل الفتح
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {analyticsData.averageOpenRate}%
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 overflow-hidden shadow rounded-lg">
          <div className="p-5">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <ArrowTrendingUpIcon className="h-6 w-6 text-purple-400" />
              </div>
              <div className="mr-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">
                    إجمالي الإيرادات
                  </dt>
                  <dd className="text-lg font-medium text-gray-900 dark:text-white">
                    {formatCurrency(analyticsData.totalRevenue)}
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Performance Insights */}
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg">
        <div className="px-4 py-5 sm:p-6">
          <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white mb-4">
            رؤى الأداء
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="text-center">
              <div className="text-2xl font-bold text-indigo-600">
                {analyticsData.bestPerformingTime}
              </div>
              <div className="text-sm text-gray-500">أفضل وقت للإرسال</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-green-600">
                {analyticsData.averageClickRate}%
              </div>
              <div className="text-sm text-gray-500">متوسط معدل النقر</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-purple-600">
                {analyticsData.campaignMetrics.reduce(
                  (sum, c) => sum + (c.conversions || 0),
                  0,
                )}
              </div>
              <div className="text-sm text-gray-500">إجمالي التحويلات</div>
            </div>
          </div>
        </div>
      </div>

      {/* Campaign Performance Table */}
      <div className="bg-white dark:bg-gray-800 shadow overflow-hidden sm:rounded-md">
        <div className="px-4 py-5 sm:px-6">
          <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">
            أداء الحملات
          </h3>
          <p className="mt-1 max-w-2xl text-sm text-gray-500">
            تفاصيل أداء كل حملة على حدة
          </p>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
            <thead className="bg-gray-50 dark:bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  الحملة
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  المستلمون
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  معدل التسليم
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  معدل الفتح
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  معدل النقر
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  الإيرادات
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  التحويلات
                </th>
              </tr>
            </thead>
            <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
              {analyticsData.campaignMetrics.map((campaign) => (
                <tr
                  key={campaign.campaignId}
                  className="hover:bg-gray-50 dark:hover:bg-gray-700"
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div>
                      <div className="text-sm font-medium text-gray-900 dark:text-white">
                        {campaign.campaignName}
                      </div>
                      <div className="text-sm text-gray-500">
                        {formatDate(campaign.sentAt)}
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-white">
                    {campaign.recipientCount.toLocaleString()}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span
                      className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                        campaign.deliveryRate >= 98
                          ? "text-green-800 bg-green-100"
                          : campaign.deliveryRate >= 95
                            ? "text-yellow-800 bg-yellow-100"
                            : "text-red-800 bg-red-100"
                      }`}
                    >
                      {campaign.deliveryRate}%
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span
                      className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getPerformanceColor(campaign.openRate, "open")}`}
                    >
                      {campaign.openRate}%
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span
                      className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getPerformanceColor(campaign.clickRate, "click")}`}
                    >
                      {campaign.clickRate}%
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-white">
                    {campaign.revenue ? formatCurrency(campaign.revenue) : "-"}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-white">
                    {campaign.conversions || "-"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Time Series Chart Placeholder */}
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg">
        <div className="px-4 py-5 sm:p-6">
          <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white mb-4">
            اتجاهات الأداء
          </h3>
          <div className="text-center py-12">
            <ChartBarIcon className="mx-auto h-12 w-12 text-gray-400" />
            <h3 className="mt-2 text-sm font-medium text-gray-900 dark:text-white">
              الرسوم البيانية قيد التطوير
            </h3>
            <p className="mt-1 text-sm text-gray-500">
              ستتوفر الرسوم البيانية التفاعلية قريباً
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CampaignAnalytics;

import React, { useState, useEffect } from "react";
import {
  PlusIcon,
  CalendarIcon,
  EyeIcon,
  ClockIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon,
  XMarkIcon,
  PhotoIcon,
  PaperAirplaneIcon,
} from "@heroicons/react/24/outline";
import { broadcastService } from "../../services/broadcastService";
import CampaignProgressModal from "../../components/broadcast/CampaignProgressModal";

interface CampaignFormData {
  name: string;
  message: string;
  targetAudience: string;
  scheduledAt: string;
  scheduledTime: string;
  recipientCount: number;
  tags: string[];
  priority: "low" | "medium" | "high";
  includeImages: boolean;
  trackClicks: boolean;
  autoResend: boolean;
  sendNow: boolean;
  images: File[];
}

interface CustomerList {
  id: string;
  name: string;
  description: string;
  count: number;
  criteria: string;
}

const CreateCampaign: React.FC = () => {
  const [formData, setFormData] = useState<CampaignFormData>({
    name: "",
    message: "",
    targetAudience: "",
    scheduledAt: "",
    scheduledTime: "",
    recipientCount: 0,
    tags: [],
    priority: "medium",
    includeImages: false,
    trackClicks: true,
    autoResend: false,
    sendNow: false,
    images: [],
  });

  const [customerLists, setCustomerLists] = useState<CustomerList[]>([]);
  const [newTag, setNewTag] = useState("");
  const [previewMode, setPreviewMode] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [currentCampaignId, setCurrentCampaignId] = useState<string>("");
  const [currentCampaignName, setCurrentCampaignName] = useState<string>("");
  const [success, setSuccess] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");
  const [messageTextareaRef, setMessageTextareaRef] =
    useState<HTMLTextAreaElement | null>(null);

  useEffect(() => {
    loadCustomerLists();
  }, []);

  const loadCustomerLists = async () => {
    try {
      setLoading(true);
      setError(null);

      console.log("📋 Loading customer lists using broadcastService...");
      const response = await broadcastService.getCustomerLists();
      console.log("📋 Customer lists response:", response);

      // Handle different response formats
      let listsArray: CustomerList[] = [];
      if (Array.isArray(response)) {
        listsArray = response;
      } else if (response && typeof response === "object") {
        if ("data" in response && Array.isArray((response as any).data)) {
          listsArray = (response as any).data;
        } else if (
          "success" in response &&
          "data" in response &&
          Array.isArray((response as any).data)
        ) {
          listsArray = (response as any).data;
        }
      }

      console.log("✅ Parsed customer lists:", listsArray);
      setCustomerLists(listsArray);
    } catch (err: any) {
      console.error("❌ Error loading customer lists:", err);
      setError(
        err.message || "فشل في تحميل قوائم العملاء. يرجى المحاولة مرة أخرى.",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (
    e: React.ChangeEvent<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >,
  ) => {
    const { name, value, type } = e.target;

    console.log("📝 Input Change:", { name, value, type });

    if (type === "checkbox") {
      const checked = (e.target as HTMLInputElement).checked;
      setFormData((prev) => ({ ...prev, [name]: checked }));
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));

      // Update recipient count when target audience changes
      if (name === "targetAudience") {
        console.log("🎯 Looking for list with ID:", value);
        console.log("📚 Available lists:", customerLists);

        const selectedList = customerLists.find((list) => list.id === value);
        console.log("✨ Selected list:", selectedList);

        if (selectedList) {
          setFormData((prev) => ({
            ...prev,
            recipientCount: selectedList.count || 0,
          }));
        } else {
          console.warn("⚠️ No list found with ID:", value);
          setFormData((prev) => ({
            ...prev,
            recipientCount: 0,
          }));
        }
      }
    }
  };

  const addTag = () => {
    if (newTag.trim() && !formData.tags.includes(newTag.trim())) {
      setFormData((prev) => ({ ...prev, tags: [...prev.tags, newTag.trim()] }));
      setNewTag("");
    }
  };

  const removeTag = (tagToRemove: string) => {
    setFormData((prev) => ({
      ...prev,
      tags: prev.tags.filter((tag) => tag !== tagToRemove),
    }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newImages = Array.from(e.target.files);
      setFormData((prev) => ({
        ...prev,
        images: [...prev.images, ...newImages],
      }));
    }
  };

  const removeImage = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index),
    }));
  };

  const handleSendNowChange = (checked: boolean) => {
    setFormData((prev) => ({
      ...prev,
      sendNow: checked,
      scheduledAt: checked ? "" : prev.scheduledAt,
      scheduledTime: checked ? "" : prev.scheduledTime,
    }));
  };

  const validateForm = (): string | null => {
    if (!formData.name.trim()) return "اسم الحملة مطلوب";
    if (!formData.message.trim()) return "نص الرسالة مطلوب";
    if (!formData.targetAudience) return "يجب اختيار الجمهور المستهدف";

    if (!formData.sendNow) {
      if (!formData.scheduledAt) return "تاريخ الإرسال مطلوب";
      if (!formData.scheduledTime) return "وقت الإرسال مطلوب";

      const scheduledDateTime = new Date(
        `${formData.scheduledAt}T${formData.scheduledTime}`,
      );
      const now = new Date();
      const maxDate = new Date(now.getTime() + 24 * 60 * 60 * 1000);

      if (scheduledDateTime <= now) {
        return "يجب أن يكون موعد الإرسال في المستقبل";
      }

      if (scheduledDateTime > maxDate) {
        return "لا يمكن جدولة الحملة لأكثر من 24 ساعة مقدماً";
      }
    }

    return null;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);

    try {
      console.log("🚀 Submitting campaign:", formData);

      // إعداد FormData لإرسال البيانات والملفات
      const formDataToSend = new FormData();
      formDataToSend.append("name", formData.name);
      formDataToSend.append("message", formData.message);
      formDataToSend.append("targetAudience", formData.targetAudience);
      if (!formData.sendNow) {
        // تحويل التوقيت المحلي إلى UTC بشكل صحيح
        const localDateTime = new Date(
          `${formData.scheduledAt}T${formData.scheduledTime}`,
        );
        const utcDateTime = localDateTime.toISOString();
        formDataToSend.append("scheduledAt", utcDateTime);
      }
      formDataToSend.append("priority", formData.priority);
      formDataToSend.append("includeImages", String(formData.includeImages));
      formDataToSend.append("trackClicks", String(formData.trackClicks));
      formDataToSend.append("autoResend", String(formData.autoResend));
      formDataToSend.append("sendNow", String(formData.sendNow));
      formData.tags.forEach((tag) => formDataToSend.append("tags[]", tag));
      formData.images.forEach((file) => formDataToSend.append("images", file));

      console.log("📤 Sending campaign data (FormData):", formDataToSend);

      // Create campaign using broadcastService
      const createdCampaign =
        await broadcastService.createCampaign(formDataToSend);
      console.log("✅ Campaign created successfully:", createdCampaign);

      // If sendNow is true, also send the campaign
      if (createdCampaign.data.status === "sending") {
        console.log("📨 Sending campaign immediately...");

        // Show progress modal
        setCurrentCampaignId(createdCampaign.data.id);
        setCurrentCampaignName(formData.name);
        setShowProgressModal(true);

        try {
          const sendResult = await broadcastService.sendCampaign(
            createdCampaign.data.id,
          );
          console.log("✅ Campaign sent successfully:", sendResult);

          // Check if the send was actually successful
          if (!sendResult.success) {
            throw new Error(sendResult.message || "فشل في إرسال الحملة");
          }
        } catch (sendError: any) {
          console.error("❌ Error sending campaign:", sendError);
          throw new Error(
            `فشل في إرسال الحملة: ${sendError.message || sendError.toString()}`,
          );
        }
      }

      if (!formData.sendNow) {
        setSuccess(true);
        setSuccessMessage("تم إنشاء الحملة وجدولتها بنجاح!");

        setTimeout(() => {
          setSuccess(false);
          setSuccessMessage("");
          setFormData({
            name: "",
            message: "",
            targetAudience: "",
            scheduledAt: "",
            scheduledTime: "",
            recipientCount: 0,
            tags: [],
            priority: "medium",
            includeImages: false,
            trackClicks: true,
            autoResend: false,
            sendNow: false,
            images: [],
          });
        }, 3000);
      }
    } catch (err: any) {
      console.error("❌ Error creating campaign:", err);
      setError(err.message || "فشل في إنشاء الحملة. يرجى المحاولة مرة أخرى.");
    } finally {
      setLoading(false);
    }
  };

  // Function to insert variable at cursor position
  const insertVariable = (variable: string) => {
    if (!messageTextareaRef) return;

    const textarea = messageTextareaRef;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const text = formData.message;
    const before = text.substring(0, start);
    const after = text.substring(end, text.length);

    const newMessage = before + variable + after;
    setFormData((prev) => ({ ...prev, message: newMessage }));

    // Set cursor position after inserted variable
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(
        start + variable.length,
        start + variable.length,
      );
    }, 0);
  };

  // Function to replace variables with actual values for preview
  const getPreviewMessage = () => {
    if (!formData.message) return "اكتب رسالتك لرؤية المعاينة...";

    let preview = formData.message;
    preview = preview.replace(/{customerName}/g, "محمد أحمد");
    preview = preview.replace(/{firstName}/g, "محمد");
    preview = preview.replace(/{lastName}/g, "أحمد");

    return preview;
  };

  const selectedList = customerLists.find(
    (list) => list.id === formData.targetAudience,
  );

  if (success) {
    return (
      <div className="max-w-2xl mx-auto p-6">
        <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg p-6 text-center">
          <CheckCircleIcon className="mx-auto h-12 w-12 text-green-500 dark:text-green-400 mb-4" />
          <h3 className="text-lg font-medium text-green-800 dark:text-green-200 mb-2">
            تم إنشاء الحملة بنجاح!
          </h3>
          <p className="text-green-600 dark:text-green-300">{successMessage}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full p-6">
      <div className="bg-white dark:bg-gray-800 shadow sm:rounded-lg">
        <div className="px-4 py-5 sm:p-6">
          <div className="flex items-center justify-between mb-6">
            <div>
              <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">
                إنشاء حملة برودكاست جديدة
              </h3>
              <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                قم بإنشاء حملة إرسال جماعي لتصل لعملائك خلال 24 ساعة
              </p>
            </div>
            <button
              type="button"
              onClick={() => setPreviewMode(!previewMode)}
              className="inline-flex items-center px-3 py-2 border border-gray-300 dark:border-gray-600 shadow-sm text-sm leading-4 font-medium rounded-md text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
            >
              <EyeIcon className="h-4 w-4 ml-2" />
              {previewMode ? "إخفاء المعاينة" : "معاينة"}
            </button>
          </div>

          {error && (
            <div className="mb-6 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-md p-4">
              <div className="flex">
                <ExclamationTriangleIcon className="h-5 w-5 text-red-400" />
                <div className="mr-3">
                  <p className="text-sm text-red-800 dark:text-red-200">
                    {error}
                  </p>
                </div>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Left Column - Form */}
              <div className="space-y-6">
                {/* Campaign Name */}
                <div>
                  <label
                    htmlFor="name"
                    className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                  >
                    اسم الحملة *
                  </label>
                  <input
                    type="text"
                    name="name"
                    id="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    className="mt-1 block w-full border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    placeholder="مثال: عرض الجمعة البيضاء"
                    required
                  />
                </div>

                {/* Target Audience */}
                <div>
                  <label
                    htmlFor="targetAudience"
                    className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                  >
                    الجمهور المستهدف *
                  </label>
                  <select
                    name="targetAudience"
                    id="targetAudience"
                    value={formData.targetAudience}
                    onChange={handleInputChange}
                    className="mt-1 block w-full border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    required
                    disabled={loading}
                  >
                    <option value="">
                      {loading ? "جاري التحميل..." : "اختر قائمة العملاء"}
                    </option>
                    {customerLists.map((list) => (
                      <option key={list.id} value={list.id}>
                        {list.name} ({list.count.toLocaleString()} عميل)
                      </option>
                    ))}
                  </select>
                  {selectedList && (
                    <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                      {selectedList.description}
                    </p>
                  )}
                  {formData.targetAudience && formData.recipientCount > 0 && (
                    <p className="mt-1 text-sm font-medium text-indigo-600 dark:text-indigo-400">
                      ✓ سيتم الإرسال إلى{" "}
                      {formData.recipientCount.toLocaleString()} عميل
                    </p>
                  )}
                </div>

                {/* Message */}
                <div>
                  <label
                    htmlFor="message"
                    className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                  >
                    نص الرسالة *
                  </label>
                  <textarea
                    ref={(ref) => setMessageTextareaRef(ref)}
                    name="message"
                    id="message"
                    rows={4}
                    value={formData.message}
                    onChange={handleInputChange}
                    className="mt-1 block w-full border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    placeholder="اكتب رسالتك هنا... يمكنك استخدام المتغيرات لتخصيص الرسالة"
                    required
                  />

                  {/* Variables Buttons */}
                  <div className="mt-2 p-3 bg-indigo-50 dark:bg-indigo-900/30 rounded-md border border-indigo-200 dark:border-indigo-700">
                    <p className="text-xs font-medium text-indigo-900 dark:text-indigo-100 mb-2">
                      إدراج متغيرات:
                    </p>
                    <div className="flex flex-wrap gap-2">
                      <button
                        type="button"
                        onClick={() => insertVariable("{customerName}")}
                        className="inline-flex items-center px-2.5 py-1 border border-indigo-300 dark:border-indigo-600 text-xs font-medium rounded text-indigo-700 dark:text-indigo-300 bg-white dark:bg-gray-700 hover:bg-indigo-100 dark:hover:bg-indigo-800 transition-colors"
                        title="إدراج اسم العميل الكامل"
                      >
                        <span className="ml-1">👤</span>
                        اسم العميل
                      </button>
                      <button
                        type="button"
                        onClick={() => insertVariable("{firstName}")}
                        className="inline-flex items-center px-2.5 py-1 border border-indigo-300 dark:border-indigo-600 text-xs font-medium rounded text-indigo-700 dark:text-indigo-300 bg-white dark:bg-gray-700 hover:bg-indigo-100 dark:hover:bg-indigo-800 transition-colors"
                        title="إدراج الاسم الأول"
                      >
                        <span className="ml-1">✨</span>
                        الاسم الأول
                      </button>
                      <button
                        type="button"
                        onClick={() => insertVariable("{lastName}")}
                        className="inline-flex items-center px-2.5 py-1 border border-indigo-300 dark:border-indigo-600 text-xs font-medium rounded text-indigo-700 dark:text-indigo-300 bg-white dark:bg-gray-700 hover:bg-indigo-100 dark:hover:bg-indigo-800 transition-colors"
                        title="إدراج الاسم الأخير"
                      >
                        <span className="ml-1">✨</span>
                        الاسم الأخير
                      </button>
                    </div>
                    <p className="text-xs text-indigo-600 dark:text-indigo-300 mt-2">
                      💡 مثال: "مرحباً {"{customerName}"}, نذكرك بالعرض الخاص!"
                    </p>
                  </div>

                  <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                    عدد الأحرف: {formData.message.length} / 1000
                  </p>
                </div>

                {/* Send Now Option */}
                <div className="flex items-center">
                  <input
                    type="checkbox"
                    id="sendNow"
                    checked={formData.sendNow}
                    onChange={(e) => handleSendNowChange(e.target.checked)}
                    className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 dark:border-gray-600 rounded"
                  />
                  <label
                    htmlFor="sendNow"
                    className="mr-2 block text-sm font-medium text-gray-700 dark:text-gray-300"
                  >
                    <PaperAirplaneIcon className="h-5 w-5 inline ml-1" />
                    إرسال فوري (الآن)
                  </label>
                </div>

                {/* Scheduling */}
                {!formData.sendNow && (
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label
                        htmlFor="scheduledAt"
                        className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                      >
                        تاريخ الإرسال *
                      </label>
                      <input
                        type="date"
                        name="scheduledAt"
                        id="scheduledAt"
                        value={formData.scheduledAt}
                        onChange={handleInputChange}
                        min={new Date().toISOString().split("T")[0]}
                        max={
                          new Date(Date.now() + 24 * 60 * 60 * 1000)
                            .toISOString()
                            .split("T")[0]
                        }
                        className="mt-1 block w-full border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                        required={!formData.sendNow}
                      />
                    </div>
                    <div>
                      <label
                        htmlFor="scheduledTime"
                        className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                      >
                        وقت الإرسال *
                      </label>
                      <input
                        type="time"
                        name="scheduledTime"
                        id="scheduledTime"
                        value={formData.scheduledTime}
                        onChange={handleInputChange}
                        className="mt-1 block w-full border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                        required={!formData.sendNow}
                      />
                    </div>
                  </div>
                )}

                {/* Image Upload */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    <PhotoIcon className="h-5 w-5 inline ml-1" />
                    إرفاق صور (اختياري)
                  </label>
                  <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md hover:border-gray-400 dark:hover:border-gray-500 transition-colors">
                    <div className="space-y-1 text-center">
                      <PhotoIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-500" />
                      <div className="flex text-sm text-gray-600 dark:text-gray-400">
                        <label
                          htmlFor="images"
                          className="relative cursor-pointer bg-white dark:bg-gray-700 rounded-md font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-500 dark:hover:text-indigo-300"
                        >
                          <span>اختر الصور</span>
                          <input
                            id="images"
                            name="images"
                            type="file"
                            multiple
                            accept="image/*"
                            onChange={handleImageChange}
                            className="sr-only"
                          />
                        </label>
                        <p className="pr-1">أو اسحب الصور هنا</p>
                      </div>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        PNG, JPG, GIF حتى 10MB
                      </p>
                    </div>
                  </div>

                  {formData.images.length > 0 && (
                    <div className="mt-4">
                      <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                        الصور المرفقة ({formData.images.length})
                      </h4>
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {formData.images.map((image, index) => (
                          <div key={index} className="relative">
                            <img
                              src={URL.createObjectURL(image)}
                              alt={`صورة ${index + 1}`}
                              className="h-20 w-full object-cover rounded-lg"
                            />
                            <button
                              type="button"
                              onClick={() => removeImage(index)}
                              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 hover:bg-red-600"
                            >
                              <XMarkIcon className="h-4 w-4" />
                            </button>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {/* Priority */}
                <div>
                  <label
                    htmlFor="priority"
                    className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                  >
                    أولوية الحملة
                  </label>
                  <select
                    name="priority"
                    id="priority"
                    value={formData.priority}
                    onChange={handleInputChange}
                    className="mt-1 block w-full border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                  >
                    <option value="low">منخفضة</option>
                    <option value="medium">متوسطة</option>
                    <option value="high">عالية</option>
                  </select>
                </div>

                {/* Tags */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    العلامات (Tags)
                  </label>
                  <div className="mt-1 flex items-center space-x-2 space-x-reverse">
                    <input
                      type="text"
                      value={newTag}
                      onChange={(e) => setNewTag(e.target.value)}
                      onKeyPress={(e) =>
                        e.key === "Enter" && (e.preventDefault(), addTag())
                      }
                      className="flex-1 border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                      placeholder="أضف علامة جديدة"
                    />
                    <button
                      type="button"
                      onClick={addTag}
                      className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700"
                    >
                      <PlusIcon className="h-4 w-4" />
                    </button>
                  </div>
                  {formData.tags &&
                    Array.isArray(formData.tags) &&
                    formData.tags.length > 0 && (
                      <div className="mt-2 flex flex-wrap gap-2">
                        {formData.tags.map((tag, index) => (
                          <span
                            key={index}
                            className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-100 text-indigo-800"
                          >
                            {tag}
                            <button
                              type="button"
                              onClick={() => removeTag(tag)}
                              className="mr-1 h-3 w-3 text-indigo-600 hover:text-indigo-800"
                            >
                              <XMarkIcon className="h-3 w-3" />
                            </button>
                          </span>
                        ))}
                      </div>
                    )}
                </div>

                {/* Options */}
                <div className="space-y-3">
                  <div className="flex items-center">
                    <input
                      id="trackClicks"
                      name="trackClicks"
                      type="checkbox"
                      checked={formData.trackClicks}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 dark:border-gray-600 rounded"
                    />
                    <label
                      htmlFor="trackClicks"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      تتبع النقرات والتفاعل
                    </label>
                  </div>
                  <div className="flex items-center">
                    <input
                      id="includeImages"
                      name="includeImages"
                      type="checkbox"
                      checked={formData.includeImages}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 dark:border-gray-600 rounded"
                    />
                    <label
                      htmlFor="includeImages"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      تضمين صور في الرسالة
                    </label>
                  </div>
                  <div className="flex items-center">
                    <input
                      id="autoResend"
                      name="autoResend"
                      type="checkbox"
                      checked={formData.autoResend}
                      onChange={handleInputChange}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 dark:border-gray-600 rounded"
                    />
                    <label
                      htmlFor="autoResend"
                      className="mr-2 block text-sm text-gray-900 dark:text-gray-300"
                    >
                      إعادة الإرسال للذين لم يقرؤوا (بعد 6 ساعات)
                    </label>
                  </div>
                </div>
              </div>

              {/* Right Column - Preview */}
              {previewMode && (
                <div className="lg:sticky lg:top-6">
                  <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-4">
                    <h4 className="text-sm font-medium text-gray-900 dark:text-white mb-3">
                      معاينة الرسالة
                    </h4>
                    <div className="bg-white dark:bg-gray-800 rounded-lg p-4 shadow-sm border dark:border-gray-600">
                      <div className="flex items-center mb-3">
                        <div className="h-8 w-8 bg-indigo-600 rounded-full flex items-center justify-center">
                          <span className="text-xs font-medium text-white">
                            ش
                          </span>
                        </div>
                        <div className="mr-3">
                          <p className="text-sm font-medium text-gray-900 dark:text-white">
                            شركتك
                          </p>
                          <p className="text-xs text-gray-500 dark:text-gray-400">
                            {formData.sendNow
                              ? "سيتم الإرسال فوراً"
                              : formData.scheduledAt &&
                                formData.scheduledTime &&
                                new Date(
                                  `${formData.scheduledAt}T${formData.scheduledTime}`,
                                ).toLocaleString("ar-EG", {
                                  calendar: "gregory",
                                  year: "numeric",
                                  month: "2-digit",
                                  day: "2-digit",
                                  hour: "2-digit",
                                  minute: "2-digit",
                                  hour12: true,
                                })}
                          </p>
                        </div>
                      </div>
                      <div className="text-sm text-gray-900 dark:text-white whitespace-pre-wrap">
                        {getPreviewMessage()}
                      </div>
                      {formData.message &&
                        (formData.message.includes("{customerName}") ||
                          formData.message.includes("{firstName}") ||
                          formData.message.includes("{lastName}")) && (
                          <div className="mt-2 p-2 bg-indigo-50 dark:bg-indigo-900/30 rounded text-xs text-indigo-700 dark:text-indigo-300">
                            ℹ️ المعاينة تعرض مثال مع بيانات وهمية. سيتم استبدال
                            المتغيرات بالبيانات الحقيقية عند الإرسال.
                          </div>
                        )}
                      {formData.tags &&
                        Array.isArray(formData.tags) &&
                        formData.tags.length > 0 && (
                          <div className="mt-3 pt-3 border-t border-gray-200 dark:border-gray-600">
                            <div className="flex flex-wrap gap-1">
                              {formData.tags.map((tag, index) => (
                                <span
                                  key={index}
                                  className="inline-block px-2 py-1 text-xs bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded"
                                >
                                  #{tag}
                                </span>
                              ))}
                            </div>
                          </div>
                        )}
                    </div>

                    <div className="mt-4 space-y-2 text-sm">
                      <div className="flex justify-between">
                        <span className="text-gray-500 dark:text-gray-400">
                          المستلمون:
                        </span>
                        <span className="font-medium text-gray-900 dark:text-white">
                          {formData.recipientCount.toLocaleString()}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-500">الأولوية:</span>
                        <span
                          className={`font-medium ${
                            formData.priority === "high"
                              ? "text-red-600 dark:text-red-400"
                              : formData.priority === "medium"
                                ? "text-yellow-600 dark:text-yellow-400"
                                : "text-green-600 dark:text-green-400"
                          }`}
                        >
                          {formData.priority === "high"
                            ? "عالية"
                            : formData.priority === "medium"
                              ? "متوسطة"
                              : "منخفضة"}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Submit Buttons */}
            <div className="flex justify-end space-x-3 space-x-reverse pt-5 border-t border-gray-200 dark:border-gray-600">
              <button
                type="button"
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
              >
                حفظ كمسودة
              </button>
              <button
                type="submit"
                disabled={loading}
                className={`inline-flex justify-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed ${
                  formData.sendNow
                    ? "bg-green-600 hover:bg-green-700"
                    : "bg-indigo-600 hover:bg-indigo-700"
                }`}
              >
                {loading ? (
                  <>
                    <ClockIcon className="h-4 w-4 ml-2 animate-spin" />
                    {formData.sendNow ? "جاري الإرسال..." : "جاري الجدولة..."}
                  </>
                ) : (
                  <>
                    {formData.sendNow ? (
                      <PaperAirplaneIcon className="h-4 w-4 ml-2" />
                    ) : (
                      <CalendarIcon className="h-4 w-4 ml-2" />
                    )}
                    {formData.sendNow ? "إرسال فوري" : "جدولة الحملة"}
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>

      {/* Progress Modal */}
      <CampaignProgressModal
        campaignId={currentCampaignId}
        campaignName={currentCampaignName}
        isOpen={showProgressModal}
        onClose={() => setShowProgressModal(false)}
      />
    </div>
  );
};

export default CreateCampaign;

import React, { useState, useEffect } from "react";
import {
  PlusIcon,
  UserGroupIcon,
  PencilIcon,
  TrashIcon,
  FunnelIcon,
  MagnifyingGlassIcon,
  EyeIcon,
  ArrowDownTrayIcon,
} from "@heroicons/react/24/outline";
import { broadcastService } from "../../services/broadcastService";
import CreateListModal from "../../components/broadcast/CreateListModal";

interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  lastActivity: string;
  totalSpent: number;
  location: string;
  status: "active" | "inactive";
}

interface CustomerList {
  id: string;
  name: string;
  description: string;
  count: number;
  criteria: any;
  createdAt?: string;
  updatedAt?: string;
  isDefault?: boolean;
}

const CustomerListsManager: React.FC = () => {
  const [customerLists, setCustomerLists] = useState<CustomerList[]>([]);
  const [selectedList, setSelectedList] = useState<CustomerList | null>(null);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadCustomerLists();
  }, []);

  const loadCustomerLists = async () => {
    try {
      setLoading(true);
      setError(null);

      console.log("📋 Loading customer lists using broadcastService...");
      const response = await broadcastService.getCustomerLists();
      console.log("📋 Customer lists response:", response);

      // Handle different response formats
      let listsArray: CustomerList[] = [];
      if (Array.isArray(response)) {
        listsArray = response;
      } else if (response && typeof response === "object") {
        if ("data" in response && Array.isArray((response as any).data)) {
          listsArray = (response as any).data;
        } else if (
          "success" in response &&
          "data" in response &&
          Array.isArray((response as any).data)
        ) {
          listsArray = (response as any).data;
        }
      }

      console.log("✅ Parsed customer lists:", listsArray);
      setCustomerLists(listsArray);
    } catch (error: any) {
      console.error("Error loading customer lists:", error);
      setError(error.message || "فشل في تحميل قوائم العملاء");
    } finally {
      setLoading(false);
    }
  };

  const loadCustomersInList = async (listId: string) => {
    try {
      setLoading(true);
      setError(null);

      console.log("👥 Loading customers for list:", listId);
      const response = await broadcastService.getCustomersInList(listId);
      console.log("👥 Customers response:", response);

      // Handle different response formats
      let customersArray: Customer[] = [];
      if (Array.isArray(response)) {
        customersArray = response;
      } else if (response && typeof response === "object") {
        if ("data" in response && Array.isArray((response as any).data)) {
          customersArray = (response as any).data;
        } else if (
          "success" in response &&
          "data" in response &&
          Array.isArray((response as any).data)
        ) {
          customersArray = (response as any).data;
        }
      }

      console.log("✅ Parsed customers:", customersArray);
      setCustomers(customersArray);
    } catch (error: any) {
      console.error("Error loading customers:", error);
      setError(error.message || "فشل في تحميل العملاء");
      setCustomers([]);
    } finally {
      setLoading(false);
    }
  };

  const handleViewList = (list: CustomerList) => {
    setSelectedList(list);
    loadCustomersInList(list.id);
  };

  const handleDeleteList = async (listId: string) => {
    if (window.confirm("هل أنت متأكد من حذف هذه القائمة؟")) {
      try {
        setCustomerLists((prev) => prev.filter((list) => list.id !== listId));
      } catch (error) {
        console.error("Error deleting list:", error);
      }
    }
  };

  const getCriteriaText = (criteria: any) => {
    if (!criteria || typeof criteria !== "object") return "غير محدد";

    switch (criteria.type) {
      case "all":
        return "جميع العملاء المسجلين";
      case "active":
        return `آخر نشاط خلال ${criteria.lastActivity || "30 يوم"}`;
      case "inactive":
        return `غير نشط لأكثر من ${criteria.lastActivity || "30 يوم"}`;
      case "high_value":
        return `إجمالي المشتريات > ${criteria.totalSpent?.min || 0} ريال`;
      case "cart_abandoners":
        return `عربة متروكة > ${criteria.lastActivity || "7 أيام"}`;
      case "custom":
        return criteria.location
          ? `الموقع: ${criteria.location.join(", ")}`
          : "شروط مخصصة";
      default:
        return "غير محدد";
    }
  };

  const formatDate = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleDateString("ar-EG", {
        year: "numeric",
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
        calendar: "gregory",
      });
    } catch {
      return "غير محدد";
    }
  };

  const formatPrice = (amount: number) => {
    return new Intl.NumberFormat("ar-SA", {
      style: "currency",
      currency: "SAR",
    }).format(amount);
  };

  const filteredLists = Array.isArray(customerLists)
    ? customerLists.filter(
        (list) =>
          list.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          list.description.toLowerCase().includes(searchTerm.toLowerCase()),
      )
    : [];

  if (loading && !selectedList) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
      </div>
