  }

  return (
    <div className="space-y-6 p-6">
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <p className="text-sm text-red-800">{error}</p>
        </div>
      )}

      {!selectedList ? (
        <>
          {/* Header */}
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-lg leading-6 font-medium text-gray-900">
                إدارة قوائم العملاء
              </h3>
              <p className="mt-1 text-sm text-gray-500">
                إنشاء وإدارة قوائم العملاء للحملات المستهدفة
              </p>
            </div>
            <button
              onClick={() => setShowCreateModal(true)}
              className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700"
            >
              <PlusIcon className="h-4 w-4 ml-2" />
              قائمة جديدة
            </button>
          </div>

          {/* Search */}
          <div className="relative">
            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
              <MagnifyingGlassIcon className="h-5 w-5 text-gray-400" />
            </div>
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="block w-full pr-10 border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              placeholder="البحث في القوائم..."
            />
          </div>

          {/* Lists Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredLists.map((list) => (
              <div
                key={list.id}
                className="bg-white overflow-hidden shadow rounded-lg hover:shadow-md transition-shadow"
              >
                <div className="p-5">
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center">
                      <UserGroupIcon className="h-6 w-6 text-indigo-500 ml-2" />
                      <h3 className="text-lg font-medium text-gray-900">
                        {list.name}
                      </h3>
                    </div>
                    {list.isDefault && (
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                        افتراضية
                      </span>
                    )}
                  </div>

                  <p className="text-sm text-gray-500 mb-3">
                    {list.description}
                  </p>

                  <div className="flex items-center justify-between text-sm text-gray-500 mb-4">
                    <span>{list.count.toLocaleString()} عميل</span>
                    <span>
                      {list.updatedAt ? formatDate(list.updatedAt) : "غير محدد"}
                    </span>
                  </div>

                  <div className="text-xs text-gray-400 mb-4">
                    المعايير: {getCriteriaText(list.criteria)}
                  </div>

                  <div className="flex items-center justify-between">
                    <button
                      onClick={() => handleViewList(list)}
                      className="inline-flex items-center px-3 py-1.5 border border-gray-300 shadow-sm text-xs font-medium rounded text-gray-700 bg-white hover:bg-gray-50"
                    >
                      <EyeIcon className="h-4 w-4 ml-1" />
                      عرض
                    </button>

                    <div className="flex items-center space-x-2 space-x-reverse">
                      <button
                        onClick={() => {
                          setSelectedList(list);
                          setShowEditModal(true);
                        }}
                        className="text-indigo-600 hover:text-indigo-900"
                      >
                        <PencilIcon className="h-4 w-4" />
                      </button>
                      {!list.isDefault && (
                        <button
                          onClick={() => handleDeleteList(list.id)}
                          className="text-red-600 hover:text-red-900"
                        >
                          <TrashIcon className="h-4 w-4" />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {filteredLists.length === 0 && !loading && (
            <div className="text-center py-12">
              <UserGroupIcon className="mx-auto h-12 w-12 text-gray-400" />
              <h3 className="mt-2 text-sm font-medium text-gray-900">
                لا توجد قوائم
              </h3>
              <p className="mt-1 text-sm text-gray-500">
                {searchTerm
                  ? "لم يتم العثور على قوائم تطابق البحث"
                  : "ابدأ بإنشاء قائمة عملاء جديدة"}
              </p>
            </div>
          )}
        </>
      ) : (
        /* Customer List Details */
        <div className="space-y-6">
          {/* Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <button
                onClick={() => {
                  setSelectedList(null);
                  setCustomers([]);
                }}
                className="ml-4 text-gray-400 hover:text-gray-600"
              >
                ←
              </button>
              <div>
                <h3 className="text-lg leading-6 font-medium text-gray-900">
                  {selectedList.name}
                </h3>
                <p className="mt-1 text-sm text-gray-500">
                  {selectedList.count.toLocaleString()} عميل •{" "}
                  {getCriteriaText(selectedList.criteria)}
                </p>
              </div>
            </div>
            <div className="flex items-center space-x-2 space-x-reverse">
              <button className="inline-flex items-center px-3 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded text-gray-700 bg-white hover:bg-gray-50">
                <ArrowDownTrayIcon className="h-4 w-4 ml-2" />
                تصدير
              </button>
              <button className="inline-flex items-center px-3 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded text-gray-700 bg-white hover:bg-gray-50">
                <FunnelIcon className="h-4 w-4 ml-2" />
                تصفية
              </button>
            </div>
          </div>

          {/* Loading state for customers */}
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
            </div>
          ) : customers.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-lg shadow">
              <UserGroupIcon className="mx-auto h-12 w-12 text-gray-400" />
              <h3 className="mt-2 text-sm font-medium text-gray-900">
                لا يوجد عملاء في هذه القائمة
              </h3>
            </div>
          ) : (
            /* Customers Table */
            <div className="bg-white shadow overflow-hidden sm:rounded-md">
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        العميل
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        البريد الإلكتروني
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        الهاتف
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        آخر نشاط
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        إجمالي المشتريات
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        الموقع
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        الحالة
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {customers.map((customer) => (
                      <tr key={customer.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center">
                            <div className="h-8 w-8 bg-indigo-600 rounded-full flex items-center justify-center">
                              <span className="text-xs font-medium text-white">
                                {customer.name.charAt(0)}
                              </span>
                            </div>
                            <div className="mr-3">
                              <div className="text-sm font-medium text-gray-900">
                                {customer.name}
                              </div>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {customer.email}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {customer.phone || "غير متوفر"}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {formatDate(customer.lastActivity)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {formatPrice(customer.totalSpent)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {customer.location}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span
                            className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                              customer.status === "active"
                                ? "text-green-800 bg-green-100"
                                : "text-gray-800 bg-gray-100"
                            }`}
                          >
                            {customer.status === "active" ? "نشط" : "غير نشط"}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Create Modal */}
      {showCreateModal && (
        <CreateListModal
          onClose={() => setShowCreateModal(false)}
          onSuccess={loadCustomerLists}
        />
      )}

      {/* Edit Modal */}
      {showEditModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50 flex items-center justify-center">
          <div className="relative p-5 border w-96 shadow-lg rounded-md bg-white">
            <div className="mt-3 text-center">
              <h3 className="text-lg font-medium text-gray-900">
                تعديل القائمة
              </h3>
              <p className="text-sm text-gray-500 mt-2">
                هذه الميزة قيد التطوير
              </p>
              <div className="mt-4">
                <button
                  onClick={() => {
                    setShowEditModal(false);
                    setSelectedList(null);
                  }}
                  className="px-4 py-2 bg-gray-500 text-white text-base font-medium rounded-md shadow-sm hover:bg-gray-600"
                >
                  إغلاق
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerListsManager;

import React, { useState, useEffect } from "react";
import {
  CalendarIcon,
  ClockIcon,
  PencilIcon,
  TrashIcon,
  EyeIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  ExclamationTriangleIcon,
  XMarkIcon,
  PlayIcon,
  PauseIcon,
} from "@heroicons/react/24/outline";
import { broadcastService } from "../../services/broadcastService";

interface ScheduledCampaign {
  id: string;
  name: string;
  message: string;
  targetAudience: string;
  scheduledAt: string;
  status: "scheduled" | "paused" | "cancelled";
  recipientCount: number;
  priority: "low" | "medium" | "high";
  tags: string[];
  createdAt: string;
  estimatedDeliveryTime: string;
  canEdit: boolean;
  canCancel: boolean;
}

const ScheduledCampaigns: React.FC = () => {
  const [campaigns, setCampaigns] = useState<ScheduledCampaign[]>([]);
  const [filteredCampaigns, setFilteredCampaigns] = useState<
    ScheduledCampaign[]
  >([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<
    "all" | "scheduled" | "paused"
  >("all");
  const [priorityFilter, setPriorityFilter] = useState<
    "all" | "low" | "medium" | "high"
  >("all");
  const [selectedCampaign, setSelectedCampaign] =
    useState<ScheduledCampaign | null>(null);
  const [showPreview, setShowPreview] = useState(false);

  const [showCancelModal, setShowCancelModal] = useState(false);

  const loadScheduledCampaigns = async () => {
    try {
      setLoading(true);

      // Load scheduled campaigns from API
      const campaignsData = await broadcastService.getCampaigns();

      const allCampaigns = Array.isArray(campaignsData)
        ? campaignsData
        : Array.isArray(campaignsData?.campaigns)
          ? campaignsData.campaigns
          : [];
      const scheduledCampaigns = allCampaigns.filter(
        (campaign: any) => campaign.scheduledAt !== null,
      );

      setCampaigns(scheduledCampaigns);
    } catch (error) {
      console.error("Error loading scheduled campaigns:", error);
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    loadScheduledCampaigns();
  }, []);

  useEffect(() => {
    filterCampaigns();
  }, [campaigns, searchTerm, statusFilter, priorityFilter]);

  const filterCampaigns = () => {
    let filtered = campaigns;

    if (searchTerm) {
      filtered = filtered.filter(
        (campaign) =>
          campaign.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          campaign.message.toLowerCase().includes(searchTerm.toLowerCase()) ||
          campaign.targetAudience
            .toLowerCase()
            .includes(searchTerm.toLowerCase()),
      );
    }

    if (statusFilter !== "all") {
      filtered = filtered.filter(
        (campaign) => campaign.status === statusFilter,
      );
    }

    if (priorityFilter !== "all") {
      filtered = filtered.filter(
        (campaign) => campaign.priority === priorityFilter,
      );
    }

    setFilteredCampaigns(filtered);
  };

  const handleEdit = (campaign: ScheduledCampaign) => {
    setSelectedCampaign(campaign);
    // TODO: Implement edit functionality
    console.log("Edit campaign:", campaign);
  };

  const handleCancel = (campaign: ScheduledCampaign) => {
    setSelectedCampaign(campaign);
    setShowCancelModal(true);
  };

  const handlePreview = (campaign: ScheduledCampaign) => {
    setSelectedCampaign(campaign);
    setShowPreview(true);
  };

  const confirmCancel = async () => {
    if (!selectedCampaign) return;

    try {
      // Mock API call - replace with actual implementation
      setCampaigns((prev) =>
        prev.map((c) =>
          c.id === selectedCampaign.id
            ? { ...c, status: "cancelled" as const }
            : c,
        ),
      );

      setShowCancelModal(false);
      setSelectedCampaign(null);
    } catch (error) {
      console.error("Error cancelling campaign:", error);
    }
  };

  const togglePause = async (campaign: ScheduledCampaign) => {
    try {
      const newStatus =
        campaign.status === "scheduled" ? "paused" : "scheduled";

      setCampaigns((prev) =>
        prev.map((c) =>
          c.id === campaign.id
            ? { ...c, status: newStatus as "scheduled" | "paused" }
            : c,
        ),
      );
    } catch (error) {
      console.error("Error toggling campaign status:", error);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "high":
        return "text-red-600 bg-red-100";
      case "medium":
        return "text-yellow-600 bg-yellow-100";
      case "low":
        return "text-green-600 bg-green-100";
      default:
        return "text-gray-600 bg-gray-100";
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "scheduled":
        return "text-blue-600 bg-blue-100";
      case "paused":
        return "text-yellow-600 bg-yellow-100";
      case "cancelled":
        return "text-red-600 bg-red-100";
      default:
        return "text-gray-600 bg-gray-100";
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case "scheduled":
        return "مجدولة";
      case "paused":
        return "متوقفة";
      case "cancelled":
        return "ملغية";
      default:
        return status;
    }
  };

  const getPriorityText = (priority: string) => {
    switch (priority) {
      case "high":
        return "عالية";
      case "medium":
        return "متوسطة";
      case "low":
        return "منخفضة";
      default:
        return priority;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">
          الحملات المجدولة ({filteredCampaigns.length})
        </h3>
      </div>

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {/* Search */}
          <div className="relative">
            <MagnifyingGlassIcon className="h-5 w-5 absolute right-3 top-3 text-gray-400" />
            <input
              type="text"
              placeholder="البحث في الحملات..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pr-10 pl-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:bg-gray-700 dark:text-white"
            />
          </div>

          {/* Status Filter */}
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as any)}
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:bg-gray-700 dark:text-white"
          >
            <option value="all">جميع الحالات</option>
            <option value="scheduled">مجدولة</option>
            <option value="paused">متوقفة</option>
          </select>

          {/* Priority Filter */}
          <select
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value as any)}
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:bg-gray-700 dark:text-white"
          >
            <option value="all">جميع الأولويات</option>
            <option value="high">عالية</option>
            <option value="medium">متوسطة</option>
            <option value="low">منخفضة</option>
          </select>

          {/* Refresh Button */}
          <button
            onClick={loadScheduledCampaigns}
            className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 flex items-center justify-center"
          >
            <FunnelIcon className="h-4 w-4 ml-2" />
            تحديث
          </button>
        </div>
      </div>

      {/* Campaigns List */}
      {filteredCampaigns.length === 0 ? (
        <div className="text-center py-12">
          <CalendarIcon className="mx-auto h-12 w-12 text-gray-400" />
          <h3 className="mt-2 text-sm font-medium text-gray-900 dark:text-white">
            لا توجد حملات مجدولة
          </h3>
          <p className="mt-1 text-sm text-gray-500">ابدأ بإنشاء حملة جديدة</p>
        </div>
      ) : (
        <div className="bg-white dark:bg-gray-800 shadow-sm rounded-lg border border-gray-200 dark:border-gray-700">
          <ul className="divide-y divide-gray-200 dark:divide-gray-700">
            {filteredCampaigns.map((campaign) => (
              <li key={campaign.id} className="p-6">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <div className="flex items-center space-x-3 space-x-reverse">
                      <h4 className="text-lg font-medium text-gray-900 dark:text-white">
                        {campaign.name}
                      </h4>
                      <span
                        className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(campaign.status)}`}
                      >
                        {getStatusText(campaign.status)}
                      </span>
                      <span
                        className={`px-2 py-1 text-xs font-medium rounded-full ${getPriorityColor(campaign.priority)}`}
                      >
                        {getPriorityText(campaign.priority)}
                      </span>
                    </div>

                    <p className="mt-2 text-sm text-gray-600 dark:text-gray-300 line-clamp-2">
                      {campaign.message}
                    </p>

                    <div className="mt-3 flex items-center space-x-6 space-x-reverse text-sm text-gray-500">
                      <div className="flex items-center">
                        <CalendarIcon className="h-4 w-4 ml-1" />
                        {new Date(campaign.scheduledAt).toLocaleString(
                          "ar-EG",
                          {
                            calendar: "gregory",
                            year: "numeric",
                            month: "2-digit",
                            day: "2-digit",
                            hour: "2-digit",
                            minute: "2-digit",
                            hour12: true,
                          },
                        )}
                      </div>
                      <div className="flex items-center">
                        <ClockIcon className="h-4 w-4 ml-1" />
                        {campaign.estimatedDeliveryTime}
                      </div>
                      <div>
                        {campaign.recipientCount.toLocaleString()} مستلم
                      </div>
                      <div>{campaign.targetAudience}</div>
                    </div>

                    {campaign.tags &&
                      Array.isArray(campaign.tags) &&
                      campaign.tags.length > 0 && (
                        <div className="mt-2 flex flex-wrap gap-1">
                          {campaign.tags.map((tag, index) => (
                            <span
                              key={index}
                              className="px-2 py-1 text-xs bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded"
                            >
                              {tag}
                            </span>
                          ))}
                        </div>
                      )}
                  </div>

                  <div className="flex items-center space-x-2 space-x-reverse">
                    <button
                      onClick={() => handlePreview(campaign)}
                      className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                      title="معاينة"
                    >
                      <EyeIcon className="h-5 w-5" />
                    </button>

                    {campaign.canEdit && (
                      <button
                        onClick={() => handleEdit(campaign)}
                        className="p-2 text-indigo-400 hover:text-indigo-600"
                        title="تعديل"
                      >
                        <PencilIcon className="h-5 w-5" />
                      </button>
                    )}

                    <button
                      onClick={() => togglePause(campaign)}
                      className="p-2 text-yellow-400 hover:text-yellow-600"
                      title={
                        campaign.status === "scheduled"
                          ? "إيقاف مؤقت"
                          : "استئناف"
                      }
                    >
                      {campaign.status === "scheduled" ? (
                        <PauseIcon className="h-5 w-5" />
                      ) : (
                        <PlayIcon className="h-5 w-5" />
                      )}
                    </button>

                    {campaign.canCancel && (
                      <button
                        onClick={() => handleCancel(campaign)}
                        className="p-2 text-red-400 hover:text-red-600"
                        title="إلغاء"
                      >
                        <TrashIcon className="h-5 w-5" />
                      </button>
                    )}
                  </div>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Preview Modal */}
      {showPreview && selectedCampaign && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-11/12 md:w-3/4 lg:w-1/2 shadow-lg rounded-md bg-white dark:bg-gray-800">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                معاينة الحملة: {selectedCampaign.name}
              </h3>
              <button
                onClick={() => setShowPreview(false)}
                className="text-gray-400 hover:text-gray-600"
              >
                <XMarkIcon className="h-6 w-6" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                  الرسالة:
                </label>
                <div className="mt-1 p-3 border border-gray-300 dark:border-gray-600 rounded-md bg-gray-50 dark:bg-gray-700">
                  <p className="text-sm text-gray-900 dark:text-white whitespace-pre-wrap">
                    {selectedCampaign.message}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    الجمهور المستهدف:
                  </label>
                  <p className="mt-1 text-sm text-gray-900 dark:text-white">
                    {selectedCampaign.targetAudience}
                  </p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    عدد المستلمين:
                  </label>
                  <p className="mt-1 text-sm text-gray-900 dark:text-white">
                    {selectedCampaign.recipientCount.toLocaleString()}
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Cancel Confirmation Modal */}
      {showCancelModal && selectedCampaign && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-96 shadow-lg rounded-md bg-white dark:bg-gray-800">
            <div className="mt-3 text-center">
              <ExclamationTriangleIcon className="mx-auto h-12 w-12 text-red-600" />
              <h3 className="text-lg font-medium text-gray-900 dark:text-white mt-2">
                تأكيد إلغاء الحملة
              </h3>
              <p className="text-sm text-gray-500 mt-2">
                هل أنت متأكد من إلغاء حملة "{selectedCampaign.name}"؟ لا يمكن
                التراجع عن هذا الإجراء.
              </p>
              <div className="flex justify-center space-x-4 space-x-reverse mt-4">
                <button
                  onClick={() => setShowCancelModal(false)}
                  className="px-4 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  إلغاء
                </button>
                <button
                  onClick={confirmCancel}
                  className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
                >
                  تأكيد الإلغاء
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScheduledCampaigns;

import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import {
  bulkSearchService,
  Order,
  BulkSearchStats,
} from "../../services/bulkSearchService";
import toast from "react-hot-toast";
import {
  Search,
  FileText,
  Download,
  AlertCircle,
  CheckCircle,
  Loader2,
  Phone,
  Package,
  Copy,
} from "lucide-react";

const BulkSearchPage: React.FC = () => {
  const { t } = useTranslation();
  const [searchType, setSearchType] = useState<"orderNumber" | "phone">(
    "orderNumber",
  );
  const [inputText, setInputText] = useState("");
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<Order[]>([]);
  const [notFoundValues, setNotFoundValues] = useState<string[]>([]);
  const [stats, setStats] = useState<BulkSearchStats | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const handleSearch = async () => {
    if (!inputText.trim()) {
      toast.error(t("bulkSearch.errorEnterValues"));
      return;
    }

    setLoading(true);
    setHasSearched(false);

    try {
      const values = bulkSearchService.parseInput(inputText);

      if (values.length === 0) {
        toast.error(t("bulkSearch.errorNoValidValues"));
        setLoading(false);
        return;
      }

      if (values.length > 100) {
        toast.error(t("bulkSearch.errorMaxValues"));
        setLoading(false);
        return;
      }

      // Phone validation for phone search type
      if (searchType === "phone") {
        const invalidPhones = values.filter(
          (v) => !bulkSearchService.validatePhone(v),
        );
        if (invalidPhones.length > 0) {
          toast.error(
            t("bulkSearch.errorInvalidPhones", { count: invalidPhones.length }),
            { duration: 4000 },
          );
        }
      }

      const response = await bulkSearchService.bulkSearch(searchType, values);

      if (response.success) {
        setResults(response.data.orders);
        setNotFoundValues(response.data.notFoundValues);
        setStats(response.data.stats);
        setHasSearched(true);

        if (response.data.orders.length === 0) {
          toast.error(t("bulkSearch.errorNoResults"));
        } else {
          const message =
            searchType === "phone"
              ? t("bulkSearch.successFoundCustomers", {
                  customers: response.data.stats.found,
                  orders: response.data.orders.length,
                })
              : t("bulkSearch.successFoundOrders", {
                  count: response.data.orders.length,
                });
          toast.success(message);
        }
      }
    } catch (error: any) {
      console.error("Bulk search error:", error);
      const errorMessage =
        error.response?.data?.error ||
        error.message ||
        t("bulkSearch.errorSearch");
      const statusCode = error.response?.status;

      if (statusCode === 403) {
        toast.error(t("bulkSearch.errorUnauthorized"));
      } else if (statusCode === 400) {
        toast.error(t("bulkSearch.errorBadRequest", { message: errorMessage }));
      } else if (statusCode === 500) {
        toast.error(t("bulkSearch.errorServer"));
      } else {
        toast.error(errorMessage);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    if (results.length === 0) {
      toast.error(t("bulkSearch.errorNoExport"));
      return;
    }

    try {
      bulkSearchService.exportToCSV(results, searchType);
      toast.success(t("bulkSearch.successExport"));
    } catch (error) {
      toast.error(t("bulkSearch.errorExport"));
    }
  };

  const handleCopy = async () => {
    if (results.length === 0) {
      toast.error(t("bulkSearch.errorNoCopy"));
      return;
    }

    const success = await bulkSearchService.copyToClipboard(results);
    if (success) {
      toast.success(t("bulkSearch.successCopy"));
    } else {
      toast.error(t("bulkSearch.errorCopy"));
    }
  };

  const handleClear = () => {
    setInputText("");
    setResults([]);
    setNotFoundValues([]);
    setStats(null);
    setHasSearched(false);
  };

  const getStatusBadge = (status: string) => {
    const statusMap: Record<string, { label: string; color: string }> = {
      pending: {
        label: t("orders.status.pending"),
        color:
          "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400",
      },
      processing: {
        label: t("orders.status.processing"),
        color:
          "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
      },
      shipped: {
        label: t("orders.status.shipped"),
        color:
          "bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400",
      },
      delivered: {
        label: t("orders.status.delivered"),
        color:
          "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400",
      },
      cancelled: {
        label: t("orders.status.cancelled"),
        color: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400",
      },
      completed: {
        label: t("orders.status.completed"),
        color:
          "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400",
      },
    };

    const statusInfo = statusMap[status.toLowerCase()] || {
      label: status,
      color: "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300",
    };

    return (
      <span
        className={`px-2 py-1 rounded-full text-xs font-medium ${statusInfo.color}`}
      >
        {statusInfo.label}
      </span>
    );
  };

  return (
    <div className="p-6 w-full" dir="rtl">
      {/* Header */}
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
          <Search className="text-blue-600 dark:text-blue-400" size={32} />
          {t("bulkSearch.title")}
        </h1>
        <p className="text-gray-600 dark:text-gray-400 mt-2">
          {t("bulkSearch.description")}
        </p>
      </div>

      {/* Search Section */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6 mb-6">
        <div className="mb-4">
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            {t("bulkSearch.searchType")}
          </label>
          <div className="flex gap-4">
            <button
              onClick={() => setSearchType("orderNumber")}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg border-2 transition-all ${
                searchType === "orderNumber"
                  ? "border-blue-600 bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400"
                  : "border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:border-gray-300 dark:hover:border-gray-500"
              }`}
            >
              <Package size={20} />
              <span className="font-medium">{t("bulkSearch.orderCodes")}</span>
            </button>
            <button
              onClick={() => setSearchType("phone")}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg border-2 transition-all ${
                searchType === "phone"
                  ? "border-blue-600 bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400"
                  : "border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:border-gray-300 dark:hover:border-gray-500"
              }`}
            >
              <Phone size={20} />
              <span className="font-medium">
                {t("bulkSearch.phoneNumbers")}
              </span>
            </button>
          </div>
        </div>

        <div className="mb-4">
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            {searchType === "orderNumber"
              ? t("bulkSearch.orderCodes")
              : t("bulkSearch.phoneNumbers")}
            <span className="text-gray-500 dark:text-gray-400 text-xs mr-2">
              ({t("bulkSearch.inputLabel")})
            </span>
          </label>
          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            placeholder={
              searchType === "orderNumber"
                ? t("bulkSearch.orderCodesPlaceholder")
                : t("bulkSearch.phonesPlaceholder")
            }
            className="w-full h-48 p-4 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none font-mono text-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500"
            disabled={loading}
          />
          <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            {t("bulkSearch.valueCount", {
              count: bulkSearchService.parseInput(inputText).length,
            })}
          </div>
        </div>

        <div className="flex gap-3">
          <button
            onClick={handleSearch}
            disabled={loading || !inputText.trim()}
            className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-300 dark:disabled:bg-gray-600 disabled:cursor-not-allowed transition-colors font-medium"
          >
            {loading ? (
              <>
                <Loader2 size={20} className="animate-spin" />
                {t("bulkSearch.searching")}
              </>
            ) : (
              <>
                <Search size={20} />
                {t("bulkSearch.search")}
              </>
            )}
          </button>
          <button
            onClick={handleClear}
            disabled={loading}
            className="px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-600 disabled:bg-gray-100 dark:disabled:bg-gray-800 disabled:cursor-not-allowed transition-colors font-medium"
          >
            {t("bulkSearch.clear")}
          </button>
        </div>
      </div>

      {/* Statistics */}
      {hasSearched && stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("bulkSearch.total")}
                </p>
                <p className="text-2xl font-bold text-gray-800 dark:text-white">
                  {stats.total}
                </p>
              </div>
              <FileText
                className="text-gray-400 dark:text-gray-500"
                size={32}
              />
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("orders.found")}
                </p>
                <p className="text-2xl font-bold text-green-600 dark:text-green-400">
                  {stats.found}
                </p>
              </div>
              <CheckCircle
                className="text-green-400 dark:text-green-500"
                size={32}
              />
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("orders.notFound")}
                </p>
                <p className="text-2xl font-bold text-red-600 dark:text-red-400">
                  {stats.notFound}
                </p>
              </div>
              <AlertCircle
                className="text-red-400 dark:text-red-500"
                size={32}
              />
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("orders.ordersCount")}
                </p>
                <p className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                  {stats.ordersCount}
                </p>
              </div>
              <Package className="text-blue-400 dark:text-blue-500" size={32} />
            </div>
          </div>
        </div>
      )}

      {/* Not Found Values */}
      {hasSearched && notFoundValues.length > 0 && (
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4 mb-6">
          <div className="flex items-start gap-2">
            <AlertCircle
              className="text-red-600 dark:text-red-400 mt-1"
              size={20}
            />
            <div className="flex-1">
              <h3 className="font-bold text-red-800 dark:text-red-300 mb-2">
                {t("orders.notFoundValues", { count: notFoundValues.length })}
              </h3>
              <div className="flex flex-wrap gap-2">
                {notFoundValues.map((value, index) => (
                  <span
                    key={index}
                    className="bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300 px-2 py-1 rounded text-sm font-mono"
                  >
                    {value}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Results Table */}
      {hasSearched && results.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md overflow-hidden">
          <div className="p-4 bg-gray-50 dark:bg-gray-700 border-b border-gray-200 dark:border-gray-600 flex justify-between items-center">
            <h2 className="text-lg font-bold text-gray-800 dark:text-white">
              {t("bulkSearch.results")} ({results.length})
            </h2>
            <button
              onClick={handleExport}
              className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
            >
              <Download size={18} />
              {t("bulkSearch.export")}
            </button>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-50 dark:bg-gray-700">
                <tr>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    {t("bulkSearch.orderNumber")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    {t("bulkSearch.customer")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    {t("bulkSearch.phone")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    {t("bulkSearch.status")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    {t("bulkSearch.total")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    {t("bulkSearch.date")}
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                {results.map((order) => (
                  <tr
                    key={order.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="font-mono text-sm font-medium text-blue-600 dark:text-blue-400">
                        {order.orderNumber}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm font-medium text-gray-900 dark:text-gray-100">
                        {order.customer
                          ? `${order.customer.firstName} ${order.customer.lastName}`
                          : "-"}
                      </div>
                      <div className="text-xs text-gray-500 dark:text-gray-400">
                        {order.customer?.email || "-"}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className="text-sm text-gray-900 dark:text-gray-100 font-mono"
                        dir="ltr"
                      >
                        {order.customer?.phone || "-"}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getStatusBadge(order.status)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm font-medium text-gray-900 dark:text-gray-100">
                        {order.total.toFixed(2)} {order.currency || "ج.م"}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                      {new Date(order.createdAt).toLocaleDateString("ar-EG")}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Empty State */}
      {hasSearched && results.length === 0 && notFoundValues.length === 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-12 text-center">
          <Search
            className="mx-auto text-gray-400 dark:text-gray-500 mb-4"
            size={64}
          />
          <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
            {t("bulkSearch.noResults")}
          </h3>
          <p className="text-gray-600 dark:text-gray-400">
            {t("bulkSearch.searchFirst")}
          </p>
        </div>
      )}
    </div>
  );
};

export default BulkSearchPage;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import CommentService from "../../services/commentService";

const CommentDetails = () => {
  const { t } = useTranslation();
  const { id } = useParams();
  const navigate = useNavigate();
  const [comment, setComment] = useState(null);
  const [loading, setLoading] = useState(true);
  const [responseText, setResponseText] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState("");

  // Fetch comment details
  const fetchComment = async () => {
    try {
      const response = await CommentService.getFacebookCommentById(id);
      if (response.success) {
        setComment(response.data);
        setResponseText(response.data.response || "");
      }
    } catch (error) {
      console.error("Error fetching comment:", error);
    } finally {
      setLoading(false);
    }
  };

  // Handle response update
  const handleUpdateResponse = async () => {
    if (!responseText.trim()) {
      setSaveMessage("Please enter a response before saving.");
      setTimeout(() => setSaveMessage(""), 3000);
      return;
    }

    setIsSaving(true);
    setSaveMessage("");
    try {
      const result = await CommentService.sendManualResponseToFacebook(
        id,
        responseText,
      );
      if (result.success) {
        setSaveMessage("Response saved and sent to Facebook successfully!");
        fetchComment(); // Refresh the comment data
        // Clear message after 3 seconds
        setTimeout(() => setSaveMessage(""), 3000);
      }
    } catch (error) {
      setSaveMessage("Error saving response: " + error.message);
      setTimeout(() => setSaveMessage(""), 3000);
    } finally {
      setIsSaving(false);
    }
  };

  // Handle comment deletion
  const handleDeleteComment = async () => {
    if (window.confirm("Are you sure you want to delete this comment?")) {
      try {
        const result = await CommentService.deleteFacebookComment(id);
        if (result.success) {
          alert("Comment deleted successfully");
          navigate("/comments");
        }
      } catch (error) {
        alert("Error deleting comment: " + error.message);
      }
    }
  };

  useEffect(() => {
    fetchComment();
  }, [id]);

  if (loading) {
    return (
      <div className="p-6">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-600"></div>
          <p className="mt-2 text-gray-600">
            {t("commentDetails.loadingDetails")}
          </p>
        </div>
      </div>
    );
  }

  if (!comment) {
    return (
      <div className="p-6">
        <div className="bg-white rounded-lg shadow p-6 text-center">
          <h2 className="text-xl font-bold text-gray-800 mb-2">
            {t("commentDetails.notFoundTitle")}
          </h2>
          <p className="text-gray-600 mb-4">
            {t("commentDetails.notFoundDesc")}
          </p>
          <button
            onClick={() => navigate("/comments")}
            className="bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition"
          >
            {t("commentDetails.backToComments")}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="mb-6">
        <button
          onClick={() => navigate("/comments")}
          className="flex items-center text-blue-600 hover:text-blue-800 mb-4"
        >
          <svg
            className="w-5 h-5 mr-2"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M15 19l-7-7 7-7"
            />
          </svg>
          {t("commentDetails.backToComments")}
        </button>
        <h1 className="text-2xl font-bold text-gray-800">
          {t("commentDetails.pageTitle")}
        </h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Comment Details */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h2 className="text-xl font-bold text-gray-800 mb-4">
              {t("commentDetails.infoTitle")}
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("commentDetails.commentId")}
                </label>
                <div className="text-sm text-gray-900">{comment.commentId}</div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("commentDetails.postId")}
                </label>
                <div className="text-sm text-gray-900">{comment.postId}</div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("commentDetails.senderName")}
                </label>
                <div className="text-sm text-gray-900">
                  {comment.senderName}
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("commentDetails.senderId")}
                </label>
                <div className="text-sm text-gray-900">{comment.senderId}</div>
              </div>
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {t("commentDetails.commentDate")}
              </label>
              <div className="text-sm text-gray-900">
                {new Date(comment.createdTime).toLocaleString()}
              </div>
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {t("commentDetails.commentText")}
              </label>
              <div className="bg-gray-50 p-4 rounded-md">
                <p className="text-gray-900">{comment.message}</p>
              </div>
            </div>

            {comment.respondedAt && (
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("commentDetails.repliedAt")}
                </label>
                <div className="text-sm text-gray-900">
                  {new Date(comment.respondedAt).toLocaleString()}
                </div>
              </div>
            )}

            {comment.response && (
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("commentDetails.previousReply")}
                </label>
                <div className="bg-blue-50 p-4 rounded-md">
                  <p className="text-gray-900">{comment.response}</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Response Section */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-lg shadow p-6">
            <h2 className="text-xl font-bold text-gray-800 mb-4">
              {t("commentDetails.replySectionTitle")}
            </h2>

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {t("commentDetails.yourReply")}
              </label>
              <textarea
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                rows="6"
                value={responseText}
                onChange={(e) => setResponseText(e.target.value)}
                placeholder={t("commentDetails.replyPlaceholder")}
              />
            </div>

            {saveMessage && (
              <div
                className={`mb-4 p-2 rounded text-center text-sm ${
                  saveMessage.includes("Error") || saveMessage.includes("خطأ")
                    ? "bg-red-100 text-red-700"
                    : "bg-green-100 text-green-700"
                }`}
              >
                {saveMessage}
              </div>
            )}

            <div className="flex flex-col space-y-2">
              <button
                onClick={handleUpdateResponse}
                disabled={isSaving}
                className="bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition disabled:opacity-50"
              >
                {isSaving
                  ? t("commentDetails.sending")
                  : t("commentDetails.sendReplyToFacebook")}
              </button>

              <button
                onClick={handleDeleteComment}
                className="bg-red-600 text-white py-2 px-4 rounded-md hover:bg-red-700 transition"
              >
                {t("commentDetails.deleteComment")}
              </button>
            </div>

            <div className="mt-4 text-xs text-gray-500">
              <p>{t("commentDetails.note")}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CommentDetails;

import React, { useState, useEffect } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import CommentService from "../../services/commentService";
import {
  MessageSquare,
  CheckCircle,
  Clock,
  Search,
  RefreshCw,
  Trash2,
  Edit3,
} from "lucide-react";

const CommentsManagement = () => {
  const { t } = useTranslation();
  const [comments, setComments] = useState([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({
    currentPage: 1,
    totalPages: 1,
    totalCount: 0,
    responded: 0,
    pending: 0,
    recent: 0,
    responseRate: 0,
  });
  const [filters, setFilters] = useState({
    page: 1,
    limit: 20,
    search: "",
    status: "all",
  });
  const [pagination, setPagination] = useState({
    currentPage: 1,
    totalPages: 1,
    totalCount: 0,
  });
  const navigate = useNavigate();

  const fetchStats = async () => {
    try {
      const response = await CommentService.getCommentStats();
      if (response.success) {
        setStats((prev) => ({
          ...prev,
          totalCount: response.data?.total || 0,
          responded: response.data?.responded || 0,
          pending: response.data?.pending || 0,
          recent: response.data?.recent || 0,
          responseRate: response.data?.responseRate || 0,
        }));
      }
    } catch (error) {
      console.error("Error fetching comment statistics:", error);
    }
  };

  const fetchComments = async () => {
    setLoading(true);
    try {
      const response = await CommentService.getFacebookComments(filters);
      if (response.success) {
        setComments(response.data);
        setPagination(response.pagination);
        setStats((prev) => ({
          ...prev,
          currentPage: response.pagination?.currentPage || 1,
          totalPages: response.pagination?.totalPages || 1,
          totalCount: response.pagination?.totalCount || prev.totalCount || 0,
        }));
      }
    } catch (error) {
      console.error("Error fetching comments:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (key, value) => {
    setFilters((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const handlePageChange = (newPage) => {
    setFilters((prev) => ({
      ...prev,
      page: newPage,
    }));
  };

  const handleUpdateResponse = async (commentId, response) => {
    if (!response || !response.trim()) {
      alert(t("unifiedComments.enterReply"));
      return;
    }

    try {
      const result = await CommentService.sendManualResponseToFacebook(
        commentId,
        response,
      );
      if (result.success) {
        fetchComments();
        fetchStats();
        alert(t("unifiedComments.replySaved"));
      }
    } catch (error) {
      alert(t("unifiedComments.replyError") + ": " + error.message);
    }
  };

  const handleDeleteComment = async (commentId) => {
    if (window.confirm(t("unifiedComments.confirmDeleteComment"))) {
      try {
        const result = await CommentService.deleteFacebookComment(commentId);
        if (result.success) {
          fetchComments();
          fetchStats();
        }
      } catch (error) {
        console.error("Error deleting comment:", error);
      }
    }
  };

  const handleBulkDelete = async (commentIds) => {
    if (
      window.confirm(
        `${t("unifiedComments.confirmDelete")} ${commentIds.length} ${t("unifiedComments.comment")}؟`,
      )
    ) {
      try {
        const result =
          await CommentService.bulkDeleteFacebookComments(commentIds);
        if (result.success) {
          fetchComments();
          fetchStats();
        }
      } catch (error) {
        console.error("Error deleting comments:", error);
      }
    }
  };

  useEffect(() => {
    fetchStats();
    fetchComments();
  }, [filters]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 p-4 md:p-8">
      <div className="w-full">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-3 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-xl shadow-lg">
              <MessageSquare className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-3xl font-bold text-slate-800">
                {t("commentsManagement.pageTitle")}
              </h1>
              <p className="text-slate-600 mt-1">
                {t("commentsManagement.pageSubtitle")}
              </p>
            </div>
          </div>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
          <div className="group relative overflow-hidden rounded-2xl bg-gradient-to-br from-blue-500 to-blue-600 p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:-translate-y-1">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-10 rounded-full -mr-16 -mt-16 group-hover:scale-150 transition-transform duration-500"></div>
            <div className="relative">
              <div className="flex items-center justify-between mb-4">
                <div className="p-3 bg-white bg-opacity-20 rounded-xl backdrop-blur-sm">
                  <MessageSquare className="w-6 h-6 text-white" />
                </div>
                <div className="text-right">
                  <div className="text-5xl font-black text-white">
                    {stats.currentPage || 0}
                  </div>
                </div>
              </div>
              <div className="text-blue-100 text-sm font-medium">
                {t("commentsManagement.currentPage")}
              </div>
            </div>
          </div>

          <div className="group relative overflow-hidden rounded-2xl bg-gradient-to-br from-emerald-500 to-teal-600 p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:-translate-y-1">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-10 rounded-full -mr-16 -mt-16 group-hover:scale-150 transition-transform duration-500"></div>
            <div className="relative">
              <div className="flex items-center justify-between mb-4">
                <div className="p-3 bg-white bg-opacity-20 rounded-xl backdrop-blur-sm">
                  <CheckCircle className="w-6 h-6 text-white" />
                </div>
                <div className="text-right">
                  <div className="text-5xl font-black text-white">
                    {stats.totalPages || 0}
                  </div>
                </div>
              </div>
              <div className="text-emerald-100 text-sm font-medium">
                {t("commentsManagement.totalPages")}
              </div>
            </div>
          </div>

          <div className="group relative overflow-hidden rounded-2xl bg-gradient-to-br from-amber-500 to-orange-600 p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:-translate-y-1">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-10 rounded-full -mr-16 -mt-16 group-hover:scale-150 transition-transform duration-500"></div>
            <div className="relative">
              <div className="flex items-center justify-between mb-4">
                <div className="p-3 bg-white bg-opacity-20 rounded-xl backdrop-blur-sm">
                  <Clock className="w-6 h-6 text-white" />
                </div>
                <div className="text-right">
                  <div className="text-5xl font-black text-white">
                    {stats.totalCount || 0}
                  </div>
                </div>
              </div>
              <div className="text-amber-100 text-sm font-medium">
                {t("commentsManagement.totalCommentsAll")}
              </div>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white/80 backdrop-blur-xl rounded-2xl shadow-xl p-6 mb-8 border border-white/20">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">
                {t("commentsManagement.search")}
              </label>
              <div className="relative">
                <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input
                  type="text"
                  className="w-full pr-10 pl-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 focus:bg-white transition-all text-right"
                  placeholder={t("commentsManagement.searchPlaceholder")}
                  value={filters.search}
                  onChange={(e) => handleFilterChange("search", e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">
                {t("commentsManagement.status")}
              </label>
              <select
                className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 focus:bg-white transition-all text-right"
                value={filters.status}
                onChange={(e) => handleFilterChange("status", e.target.value)}
              >
                <option value="all">
                  {t("commentsManagement.allComments")}
                </option>
                <option value="responded">
                  {t("commentsManagement.responded")}
                </option>
                <option value="pending">
                  {t("commentsManagement.pending")}
                </option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">
                {t("commentsManagement.itemsCount")}
              </label>
              <select
                className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 focus:bg-white transition-all text-right"
                value={filters.limit}
                onChange={(e) =>
                  handleFilterChange("limit", parseInt(e.target.value))
                }
              >
                <option value="10">10</option>
                <option value="20">20</option>
                <option value="50">50</option>
                <option value="100">100</option>
              </select>
            </div>

            <div className="flex items-end">
              <button
                className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-3 px-6 rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all shadow-lg hover:shadow-xl flex items-center justify-center gap-2 font-semibold"
                onClick={() => fetchComments()}
              >
                <RefreshCw className="w-5 h-5" />
                {t("commentsManagement.refresh")}
              </button>
            </div>
          </div>
        </div>

        {/* Comments Table */}
        <div className="bg-white/80 backdrop-blur-xl rounded-2xl shadow-xl overflow-hidden border border-white/20">
          {loading ? (
            <div className="p-12 text-center">
              <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent"></div>
              <p className="mt-4 text-slate-600 font-medium">
                {t("commentsManagement.loadingComments")}
              </p>
            </div>
          ) : (
            <>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-slate-200">
                  <thead className="bg-gradient-to-r from-slate-50 to-slate-100">
                    <tr>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        {t("commentsManagement.table_comment")}
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        {t("commentsManagement.table_sender")}
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        {t("commentsManagement.table_postId")}
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        {t("commentsManagement.table_date")}
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        {t("commentsManagement.table_status")}
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        {t("commentsManagement.table_actions")}
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-slate-100">
                    {comments.length === 0 ? (
                      <tr>
                        <td colSpan="6" className="px-6 py-12 text-center">
                          <div className="flex flex-col items-center justify-center">
                            <MessageSquare className="w-16 h-16 text-slate-300 mb-4" />
                            <p className="text-slate-500 text-lg font-medium">
                              {t("commentsManagement.noComments")}
                            </p>
                          </div>
                        </td>
                      </tr>
                    ) : (
                      comments.map((comment) => (
                        <tr
                          key={comment.id}
                          className="hover:bg-blue-50/50 transition-colors"
                        >
                          <td className="px-6 py-4">
                            <Link
                              to={`/comments/${comment.id}`}
                              className="text-sm text-blue-600 hover:text-blue-800 font-medium max-w-xs truncate block transition-colors"
                              title={comment.message}
                            >
                              {comment.message}
                            </Link>
                          </td>
                          <td className="px-6 py-4">
                            <div className="text-sm font-semibold text-slate-900">
                              {comment.senderName}
                            </div>
                            <div className="text-xs text-slate-500 mt-1">
                              {comment.senderId}
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <div
                              className="text-sm text-slate-700 font-mono max-w-xs truncate"
                              title={comment.postId}
                            >
                              {comment.postId}
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <div className="text-sm font-medium text-slate-900">
                              {new Date(comment.createdTime).toLocaleDateString(
                                "ar-EG",
                              )}
                            </div>
                            <div className="text-xs text-slate-500 mt-1">
                              {new Date(comment.createdTime).toLocaleTimeString(
                                "ar-EG",
                              )}
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            {comment.respondedAt ? (
                              <span className="px-3 py-1.5 inline-flex items-center gap-1 text-xs leading-5 font-bold rounded-full bg-gradient-to-r from-emerald-100 to-teal-100 text-emerald-700 border border-emerald-200">
                                <CheckCircle className="w-3.5 h-3.5" />
                                {t("commentsManagement.respondedLabel")}
                              </span>
                            ) : (
                              <span className="px-3 py-1.5 inline-flex items-center gap-1 text-xs leading-5 font-bold rounded-full bg-gradient-to-r from-amber-100 to-orange-100 text-amber-700 border border-amber-200">
                                <Clock className="w-3.5 h-3.5" />
                                {t("commentsManagement.pendingLabel")}
                              </span>
                            )}
                          </td>
                          <td className="px-6 py-4">
                            <div className="flex gap-2 justify-end">
                              <button
                                onClick={() => {
                                  const response = prompt(
                                    t("unifiedComments.replyPrompt"),
                                    comment.response || "",
                                  );
                                  if (response !== null) {
                                    handleUpdateResponse(comment.id, response);
                                  }
                                }}
                                className="p-2 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors"
                                title={
                                  comment.respondedAt
                                    ? t("commentsManagement.edit")
                                    : t("commentsManagement.reply")
                                }
                              >
                                <Edit3 className="w-4 h-4" />
                              </button>
                              <button
                                onClick={() => handleDeleteComment(comment.id)}
                                className="p-2 text-red-600 hover:bg-red-100 rounded-lg transition-colors"
                                title={t("commentsManagement.delete")}
                              >
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              {pagination.totalPages > 1 && (
                <div className="bg-gradient-to-r from-slate-50 to-slate-100 px-6 py-4 flex items-center justify-between border-t border-slate-200">
                  <div className="flex-1 flex justify-between sm:hidden">
                    <button
                      onClick={() =>
                        handlePageChange(pagination.currentPage - 1)
                      }
                      disabled={pagination.currentPage === 1}
                      className="relative inline-flex items-center px-4 py-2 border-2 border-slate-300 text-sm font-semibold rounded-xl text-slate-700 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                      {t("commentsManagement.previous")}
                    </button>
                    <button
                      onClick={() =>
                        handlePageChange(pagination.currentPage + 1)
                      }
                      disabled={
                        pagination.currentPage === pagination.totalPages
                      }
                      className="mr-3 relative inline-flex items-center px-4 py-2 border-2 border-slate-300 text-sm font-semibold rounded-xl text-slate-700 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                      {t("commentsManagement.next")}
                    </button>
                  </div>
                  <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
                    <div>
                      <p className="text-sm text-slate-700 font-medium">
                        {t("commentsManagement.showing")}{" "}
                        <span className="font-bold text-blue-600">
                          {(pagination.currentPage - 1) * filters.limit + 1}
                        </span>{" "}
                        {t("commentsManagement.to")}{" "}
                        <span className="font-bold text-blue-600">
                          {Math.min(
                            pagination.currentPage * filters.limit,
                            pagination.totalCount,
                          )}
                        </span>{" "}
                        {t("commentsManagement.of")}{" "}
                        <span className="font-bold text-blue-600">
                          {pagination.totalCount}
                        </span>{" "}
                        {t("commentsManagement.result")}
                      </p>
                    </div>
                    <div>
                      <nav
                        className="relative z-0 inline-flex rounded-xl shadow-sm gap-1"
                        aria-label="Pagination"
                      >
                        <button
                          onClick={() =>
                            handlePageChange(pagination.currentPage - 1)
                          }
                          disabled={pagination.currentPage === 1}
                          className="relative inline-flex items-center px-3 py-2 rounded-lg bg-white border-2 border-slate-300 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                        >
                          {t("commentsManagement.previous")}
                        </button>
                        {[...Array(Math.min(pagination.totalPages, 7))].map(
                          (_, i) => {
                            let page;
                            if (pagination.totalPages <= 7) {
                              page = i + 1;
                            } else if (pagination.currentPage <= 4) {
                              page = i + 1;
                            } else if (
                              pagination.currentPage >=
                              pagination.totalPages - 3
                            ) {
                              page = pagination.totalPages - 6 + i;
                            } else {
                              page = pagination.currentPage - 3 + i;
                            }

                            return (
                              <button
                                key={page}
                                onClick={() => handlePageChange(page)}
                                className={`relative inline-flex items-center px-4 py-2 text-sm font-bold rounded-lg transition-all ${
                                  page === pagination.currentPage
                                    ? "bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg scale-105"
                                    : "bg-white border-2 border-slate-300 text-slate-700 hover:bg-slate-50"
                                }`}
                              >
                                {page}
                              </button>
                            );
                          },
                        )}
                        <button
                          onClick={() =>
                            handlePageChange(pagination.currentPage + 1)
                          }
                          disabled={
                            pagination.currentPage === pagination.totalPages
                          }
                          className="relative inline-flex items-center px-3 py-2 rounded-lg bg-white border-2 border-slate-300 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                        >
                          {t("commentsManagement.next")}
                        </button>
                      </nav>
                    </div>
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default CommentsManagement;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import CommentService from "../../services/commentService";
import { MessageSquare, CheckCircle, Clock, Edit3, Trash2, Sparkles } from "lucide-react";

const PostComments = () => {
  const { t } = useTranslation();
  const { postId } = useParams();
  const navigate = useNavigate();
  const [comments, setComments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedComments, setSelectedComments] = useState([]);
  const [filters, setFilters] = useState({
    status: "all",
  });

  const fetchComments = async () => {
    try {
      const response = await CommentService.getCommentsByPostId(
        postId,
        filters,
      );
      if (response.success) {
        setComments(response.data);
      }
    } catch (error) {
      console.error("Error fetching comments:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (key, value) => {
    setFilters((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const handleUpdateResponse = async (commentId, response) => {
    if (!response || !response.trim()) {
      alert(t("unifiedComments.enterReply"));
      return;
    }

    try {
      const result = await CommentService.sendManualResponseToFacebook(
        commentId,
        response,
      );
      if (result.success) {
        fetchComments();
        alert(t("unifiedComments.replySaved"));
      }
    } catch (error) {
      alert(t("unifiedComments.replyError") + ": " + error.message);
    }
  };

  const handleFilterCommentAI = async (commentId) => {
    setLoading(true);
    try {
      const result = await CommentService.filterCommentAI(commentId);
      if (result.success) {
        alert(result.message || "تم تحليل التعليق وإخفائه لأنه سلبي.");
        fetchComments();
      } else {
        alert(result.message || "لم يتم العثور على محتوى سلبي في التعليق.");
      }
    } catch (error) {
      console.error("Error filtering comment:", error);
      alert("حدث خطأ أثناء محاولة فلترة التعليق.");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteComment = async (commentId) => {
    if (window.confirm(t("unifiedComments.confirmDeleteComment"))) {
      try {
        const result = await CommentService.deleteFacebookComment(commentId);
        if (result.success) {
          fetchComments();
          alert(t("unifiedComments.deletedSuccessfully"));
        }
      } catch (error) {
        console.error("Error deleting comment:", error);
        alert(t("unifiedComments.deleteError") + ": " + error.message);
      }
    }
  };

  const handleBulkDelete = async () => {
    if (selectedComments.length === 0) {
      alert(t("unifiedComments.selectComments"));
      return;
    }

    if (
      window.confirm(
        `${t("unifiedComments.confirmDelete")} ${selectedComments.length} ${t("unifiedComments.comment")}؟`,
      )
    ) {
      try {
        const result =
          await CommentService.bulkDeleteFacebookComments(selectedComments);
        if (result.success) {
          setSelectedComments([]);
          fetchComments();
          alert(t("unifiedComments.deletedSuccessfully"));
        }
      } catch (error) {
        console.error("Error bulk deleting comments:", error);
        alert(t("unifiedComments.deleteError") + ": " + error.message);
      }
    }
  };

  const toggleCommentSelection = (commentId) => {
    setSelectedComments((prev) =>
      prev.includes(commentId)
        ? prev.filter((id) => id !== commentId)
        : [...prev, commentId],
    );
  };

  const toggleSelectAll = () => {
    if (selectedComments.length === comments.length) {
      setSelectedComments([]);
    } else {
      setSelectedComments(comments.map((c) => c.id));
    }
  };

  useEffect(() => {
    fetchComments();
  }, [postId, filters]);

  return (
    <div className="p-6">
      <div className="mb-6">
        <button
          onClick={() => navigate("/posts")}
          className="flex items-center text-blue-600 hover:text-blue-800 mb-4"
        >
          <svg
            className="w-5 h-5 mr-2"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M15 19l-7-7 7-7"
            />
          </svg>
          {t("postComments.backToPosts")}
        </button>
        <h1 className="text-2xl font-bold text-gray-800">
          {t("postComments.pageTitle")}
        </h1>
        <p className="text-gray-600">
          {t("postComments.postIdLabel")}: {postId}
        </p>
      </div>

      {/* Filters */}
      <div className="bg-white rounded-lg shadow p-4 mb-6">
        <div className="flex flex-wrap gap-4">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-1">
              {t("postComments.status")}
            </label>
            <select
              className="px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:border-blue-500 focus:bg-white transition-all text-right"
              value={filters.status}
              onChange={(e) => handleFilterChange("status", e.target.value)}
            >
              <option value="all">{t("postComments.allComments")}</option>
              <option value="responded">{t("postComments.responded")}</option>
              <option value="pending">{t("postComments.pending")}</option>
            </select>
          </div>

          <div className="flex items-end">
            <button
              className="bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition flex items-center gap-2"
              onClick={() => fetchComments()}
            >
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                />
              </svg>
              {t("postComments.refresh")}
            </button>
          </div>

          <div className="flex items-end">
            <button
              className="bg-indigo-600 text-white py-2 px-4 rounded-lg hover:bg-indigo-700 transition"
              onClick={() => navigate(`/posts/${postId}/settings`)}
            >
              {t("postComments.autoResponseSettings")}
            </button>
          </div>

          {selectedComments.length > 0 && (
            <div className="flex items-end">
              <button
                className="bg-red-600 text-white py-2 px-4 rounded-lg hover:bg-red-700 transition flex items-center gap-2"
                onClick={handleBulkDelete}
              >
                <Trash2 className="w-4 h-4" />
                {t("postComments.deleteSelected")} ({selectedComments.length})
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Comments List */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        {loading ? (
          <div className="p-12 text-center">
            <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-600"></div>
            <p className="mt-2 text-gray-600">
              {t("postComments.loadingComments")}
            </p>
          </div>
        ) : comments.length === 0 ? (
          <div className="p-12 text-center">
            <MessageSquare className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-1">
              {t("postComments.noComments")}
            </h3>
            <p className="text-gray-500">{t("postComments.noCommentsDesc")}</p>
          </div>
        ) : (
          <>
            {/* Select All */}
            <div className="p-4 bg-slate-50 border-b border-slate-200">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={
                    selectedComments.length === comments.length &&
                    comments.length > 0
                  }
                  onChange={toggleSelectAll}
                  className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                />
                <span className="text-sm font-medium text-slate-700">
                  {t("postComments.selectAll")} ({comments.length})
                </span>
              </label>
            </div>

            <div className="divide-y divide-gray-200">
              {comments.map((comment) => (
                <div
                  key={comment.id}
                  className="p-6 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex justify-between">
                    <div className="flex items-start gap-3">
                      <input
                        type="checkbox"
                        checked={selectedComments.includes(comment.id)}
                        onChange={() => toggleCommentSelection(comment.id)}
                        className="mt-1 w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                      />
                      <div className="bg-gray-200 border-2 border-dashed rounded-xl w-10 h-10" />
                      <div>
                        <div className="flex items-center gap-2">
                          <h4 className="text-sm font-semibold text-gray-900">
                            {comment.senderName}
                          </h4>
                          <span className="text-xs text-gray-500">
                            {comment.senderId}
                          </span>
                        </div>
                        <p className="text-sm text-gray-500 mt-1">
                          {new Date(comment.createdTime).toLocaleString(
                            "ar-EG",
                          )}
                        </p>
                      </div>
                    </div>
                    <div>
                      {comment.respondedAt ? (
                        <span className="inline-flex items-center gap-1 px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">
                          <CheckCircle className="w-3 h-3" />
                          {t("postComments.respondedLabel")}
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 px-2 py-1 text-xs font-semibold rounded-full bg-amber-100 text-amber-800">
                          <Clock className="w-3 h-3" />
                          {t("postComments.pendingLabel")}
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="mt-4 ml-13">
                    <div className="bg-gray-50 p-4 rounded-lg">
                      <p className="text-gray-800">{comment.message}</p>
                    </div>

                    {comment.response && (
                      <div className="mt-3 bg-blue-50 p-4 rounded-lg border border-blue-100">
                        <p className="text-gray-800">{comment.response}</p>
                        <p className="text-xs text-gray-500 mt-2">
                          {t("postComments.repliedAt")}:{" "}
                          {new Date(comment.respondedAt).toLocaleString(
                            "ar-EG",
                          )}
                        </p>
                      </div>
                    )}

                    <div className="mt-4 flex flex-wrap gap-2">
                      {!comment.respondedAt && (
                        <button
                          onClick={() => {
                            const response = prompt(
                              t("postComments.replyPrompt"),
                            );
                            if (response !== null) {
                              handleUpdateResponse(comment.id, response);
                            }
                          }}
                          className="inline-flex items-center gap-1 px-3 py-1.5 text-sm bg-blue-600 text-white rounded-md hover:bg-blue-700 transition"
                        >
                          <Edit3 className="w-4 h-4" />
                          {t("postComments.reply")}
                        </button>
                      )}
                      <button
                        onClick={() => handleFilterCommentAI(comment.id)}
                        disabled={loading}
                        title="فلترة ذكية للكشف عن التعليقات السلبية"
                        className="inline-flex items-center gap-1 px-3 py-1.5 text-sm bg-purple-600 text-white rounded-md hover:bg-purple-700 transition disabled:opacity-50"
                      >
                        <Sparkles className="w-4 h-4" />
                        فلترة ذكية (AI)
                      </button>
                      <button
                        onClick={() => handleDeleteComment(comment.id)}
                        className="inline-flex items-center gap-1 px-3 py-1.5 text-sm bg-red-600 text-white rounded-md hover:bg-red-700 transition"
                      >
                        <Trash2 className="w-4 h-4" />
                        {t("postComments.delete")}
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default PostComments;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import CommentService from "../../services/commentService";
import { Bot, MessageSquare, Settings } from "lucide-react";

const PostSettings = () => {
  const { t } = useTranslation();
  const { postId } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [postSettings, setPostSettings] = useState({
    responseMethod: "manual", // 'ai', 'fixed', 'manual'
    commentMessages: [""], // Variations for comment responses
    fixedMessengerMessage: "",
    aiPrompt: "",
  });
  const [message, setMessage] = useState("");
  const [isFallbackMode, setIsFallbackMode] = useState(false);

  const fetchPostSettings = async () => {
    try {
      const response = await CommentService.getPostResponseMethod(postId);
      if (response.success && response.data) {
        setPostSettings({
          responseMethod: response.data.responseMethod || "manual",
          commentMessages: response.data.commentMessages
            ? JSON.parse(response.data.commentMessages)
            : [""],
          fixedMessengerMessage: response.data.fixedMessengerMessage || "",
          aiPrompt: response.data.aiPrompt || "",
        });

        // Check if we're in fallback mode
        if (response.data.updatedAt && !response.data.id) {
          setIsFallbackMode(true);
        }
      }
    } catch (error) {
      console.error("Error fetching post settings:", error);
      setMessage(t("pageComments.saveError"));
    } finally {
      setLoading(false);
    }
  };

  const savePostSettings = async () => {
    if (
      postSettings.responseMethod === "fixed" &&
      (!postSettings.commentMessages ||
        postSettings.commentMessages.length === 0 ||
        !postSettings.commentMessages[0].trim())
    ) {
      setMessage(t("postsManagement.note"));
      return;
    }

    setSaving(true);
    setMessage("");
    try {
      const response = await CommentService.setPostResponseMethod(
        postId,
        postSettings,
      );
      if (response.success) {
        setMessage(response.message || t("pageComments.savedSuccessfully"));

        // Check if we're in fallback mode
        if (response.message && response.message.includes("fallback")) {
          setIsFallbackMode(true);
        }

        setTimeout(() => setMessage(""), 3000);
      }
    } catch (error) {
      console.error("Error saving post settings:", error);
      setMessage(t("pageComments.saveError") + ": " + error.message);
    } finally {
      setSaving(false);
    }
  };

  const applyResponseMethod = async () => {
    if (isFallbackMode) {
      setMessage(t("postSettings.applyResponseDisabled"));
      return;
    }

    if (
      window.confirm(
        "هل أنت متأكد من تطبيق طريقة الرد على جميع التعليقات المعلقة في هذا المنشور؟",
      )
    ) {
      try {
        const response = await CommentService.applyPostResponseMethod(postId);
        if (response.success) {
          setMessage(`تم معالجة ${response.data.processedComments} تعليق`);
          setTimeout(() => setMessage(""), 3000);
        }
      } catch (error) {
        console.error("Error applying response method:", error);
        setMessage("حدث خطأ أثناء تطبيق طريقة الرد: " + error.message);
      }
    }
  };

  useEffect(() => {
    fetchPostSettings();
  }, [postId]);

  if (loading) {
    return (
      <div className="p-6">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-600"></div>
          <p className="mt-2 text-gray-600">
            {t("postSettings.loadingPostSettings")}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="mb-6">
        <button
          onClick={() => navigate("/posts")}
          className="flex items-center text-blue-600 hover:text-blue-800 mb-4"
        >
          <svg
            className="w-5 h-5 mr-2"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M15 19l-7-7 7-7"
            />
          </svg>
          {t("postSettings.backToPosts")}
        </button>
        <h1 className="text-2xl font-bold text-gray-800">
          {t("postSettings.pageTitle")}
        </h1>
        <p className="text-gray-600">
          {t("postSettings.postIdLabel")}: {postId}
        </p>
        {isFallbackMode && (
          <div className="mt-2 p-2 bg-yellow-100 border border-yellow-400 text-yellow-700 rounded">
            {t("postSettings.fallbackWarning")}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Settings Form */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
              <Settings className="w-5 h-5" />
              {t("postSettings.autoResponseMethodTitle")}
            </h2>

            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                  {t("postSettings.chooseResponseMethod")}
                </label>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div
                    className={`border-2 rounded-lg p-4 cursor-pointer transition-all ${
                      postSettings.responseMethod === "ai"
                        ? "border-blue-500 bg-blue-50"
                        : "border-gray-200 hover:border-gray-300"
                    }`}
                    onClick={() =>
                      setPostSettings((prev) => ({
                        ...prev,
                        responseMethod: "ai",
                      }))
                    }
                  >
                    <div className="flex items-center gap-2 mb-2">
                      <Bot className="w-5 h-5 text-blue-600" />
                      <span className="font-medium">
                        {t("postSettings.ai")}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600">
                      {t("postSettings.aiDesc")}
                    </p>
                  </div>

                  <div
                    className={`border-2 rounded-lg p-4 cursor-pointer transition-all ${
                      postSettings.responseMethod === "fixed"
                        ? "border-green-500 bg-green-50"
                        : "border-gray-200 hover:border-gray-300"
                    }`}
                    onClick={() =>
                      setPostSettings((prev) => ({
                        ...prev,
                        responseMethod: "fixed",
                      }))
                    }
                  >
                    <div className="flex items-center gap-2 mb-2">
                      <MessageSquare className="w-5 h-5 text-green-600" />
                      <span className="font-medium">
                        {t("postSettings.fixed")}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600">
                      {t("postSettings.fixedDesc")}
                    </p>
                  </div>

                  <div
                    className={`border-2 rounded-lg p-4 cursor-pointer transition-all ${
                      postSettings.responseMethod === "manual"
                        ? "border-yellow-500 bg-yellow-50"
                        : "border-gray-200 hover:border-gray-300"
                    }`}
                    onClick={() =>
                      setPostSettings((prev) => ({
                        ...prev,
                        responseMethod: "manual",
                      }))
                    }
                  >
                    <div className="flex items-center gap-2 mb-2">
                      <svg
                        className="w-5 h-5 text-yellow-600"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M15 19l-7-7 7-7"
                        />
                      </svg>
                      <span className="font-medium">
                        {t("postSettings.manual")}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600">
                      {t("postSettings.manualDesc")}
                    </p>
                  </div>
                </div>
              </div>

              {postSettings.responseMethod === "ai" && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    {t("postSettings.aiPromptOptional")}
                  </label>
                  <textarea
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    rows="6"
                    value={postSettings.aiPrompt}
                    onChange={(e) =>
                      setPostSettings((prev) => ({
                        ...prev,
                        aiPrompt: e.target.value,
                      }))
                    }
                    placeholder={t("postSettings.enterAIPrompt")}
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    {t("postSettings.aiPromptHint")}
                  </p>
                </div>
              )}

              {postSettings.responseMethod === "fixed" && (
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      {t("postSettings.fixedCommentVariations")}
                    </label>
                    {postSettings.commentMessages.map((msg, index) => (
                      <div key={index} className="mb-2 flex gap-2">
                        <textarea
                          className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                          rows="2"
                          value={msg}
                          onChange={(e) => {
                            const newMessages = [
                              ...postSettings.commentMessages,
                            ];
                            newMessages[index] = e.target.value;
                            setPostSettings((prev) => ({
                              ...prev,
                              commentMessages: newMessages,
                            }));
                          }}
                          placeholder={`${t("unifiedComments.reply")} ${index + 1}...`}
                        />
                        {postSettings.commentMessages.length > 1 && (
                          <button
                            onClick={() => {
                              const newMessages =
                                postSettings.commentMessages.filter(
                                  (_, i) => i !== index,
                                );
                              setPostSettings((prev) => ({
                                ...prev,
                                commentMessages: newMessages,
                              }));
                            }}
                            className="px-3 py-2 bg-red-500 text-white rounded-md hover:bg-red-600 transition"
                          >
                            {t("pageComments.delete")}
                          </button>
                        )}
                      </div>
                    ))}
                    <button
                      onClick={() => {
                        setPostSettings((prev) => ({
                          ...prev,
                          commentMessages: [...prev.commentMessages, ""],
                        }));
                      }}
                      className="mt-2 px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 transition text-sm"
                    >
                      {t("postsManagement.addReply")}
                    </button>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      {t("postSettings.fixedMessengerMessage")}
                    </label>
                    <textarea
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                      rows="3"
                      value={postSettings.fixedMessengerMessage}
                      onChange={(e) =>
                        setPostSettings((prev) => ({
                          ...prev,
                          fixedMessengerMessage: e.target.value,
                        }))
                      }
                      placeholder={t("postSettings.fixedMessengerPlaceholder")}
                    />
                  </div>
                </div>
              )}
            </div>

            <div className="flex flex-wrap gap-3 mt-6">
              <button
                onClick={savePostSettings}
                disabled={saving}
                className="bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition disabled:opacity-50"
              >
                {saving
                  ? t("postSettings.saving")
                  : t("postSettings.saveSettings")}
              </button>

              {postSettings.responseMethod !== "manual" && !isFallbackMode && (
                <button
                  onClick={applyResponseMethod}
                  className="bg-green-600 text-white py-2 px-4 rounded-md hover:bg-green-700 transition"
                >
                  {t("postSettings.applyResponse")}
                </button>
              )}

              {isFallbackMode && postSettings.responseMethod !== "manual" && (
                <button
                  disabled
                  className="bg-gray-400 text-white py-2 px-4 rounded-md cursor-not-allowed"
                >
                  {t("postSettings.applyResponseDisabled")}
                </button>
              )}

              <button
                onClick={() => navigate(`/posts/${postId}/comments`)}
                className="bg-gray-600 text-white py-2 px-4 rounded-md hover:bg-gray-700 transition"
              >
                {t("postSettings.viewPostComments")}
              </button>
            </div>

            {message && (
              <div
                className={`mt-4 p-3 rounded text-center text-sm ${
                  message.includes("خطأ") || message.includes("Error")
                    ? "bg-red-100 text-red-700"
                    : "bg-green-100 text-green-700"
                }`}
              >
                {message}
              </div>
            )}
          </div>
        </div>

        {/* Instructions */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-lg shadow p-6">
            <h2 className="text-xl font-bold text-gray-800 mb-4">
              {t("postSettings.howToUse")}
            </h2>
            <div className="space-y-4">
              <div className="border-r-4 border-blue-500 pr-3">
                <h3 className="font-medium text-gray-800">
                  {t("postSettings.aiTitle")}
                </h3>
                <p className="text-sm text-gray-600 mt-1">
                  {t("postSettings.aiHow")}
                </p>
              </div>

              <div className="border-r-4 border-green-500 pr-3">
                <h3 className="font-medium text-gray-800">
                  {t("postSettings.fixedTitle")}
                </h3>
                <p className="text-sm text-gray-600 mt-1">
                  {t("postSettings.fixedHow")}
                </p>
              </div>

              <div className="border-r-4 border-yellow-500 pr-3">
                <h3 className="font-medium text-gray-800">
                  {t("postSettings.manualTitle")}
                </h3>
                <p className="text-sm text-gray-600 mt-1">
                  {t("postSettings.manualHow")}
                </p>
              </div>

              <div className="pt-4 border-t border-gray-200">
                <h3 className="font-medium text-gray-800 mb-2">
                  {t("postSettings.tipsTitle")}
                </h3>
                <ul className="text-sm text-gray-600 space-y-1 list-disc pr-5">
                  <li>{t("postSettings.tipChangeAnyTime")}</li>
                  <li>{t("postSettings.tipAffectsPendingOnly")}</li>
                  <li>{t("postSettings.tipAlreadyRepliedUnaffected")}</li>
                  {isFallbackMode && (
                    <li className="text-yellow-600 font-medium">
                      {t("postSettings.tipFallbackCached")}
                    </li>
                  )}
                </ul>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostSettings;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import CommentService from "../../services/commentService";
import {
  MessageSquare,
  CheckCircle,
  Clock,
  Search,
  RefreshCw,
  Settings,
  X,
  Save,
  TrendingUp,
  Users,
  BarChart3,
  Zap,
  Filter,
  Grid3x3,
  List,
} from "lucide-react";

const PostsManagement = () => {
  const { t } = useTranslation();
  const [posts, setPosts] = useState([]);
  const [pages, setPages] = useState([]);
  const [selectedPage, setSelectedPage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [loadingPages, setLoadingPages] = useState(true);
  const [showPageSettings, setShowPageSettings] = useState(false);
  const [pageSettings, setPageSettings] = useState({
    responseMethod: "manual",
    commentMessages: [""],
    fixedMessengerMessage: "",
    aiPrompt: "",
  });
  const [savingPageSettings, setSavingPageSettings] = useState(false);
  const [pageSettingsMessage, setPageSettingsMessage] = useState("");
  const [filters, setFilters] = useState({
    page: 1,
    limit: 20,
    search: "",
    status: "all",
  });
  const [pagination, setPagination] = useState({
    currentPage: 1,
    totalPages: 1,
    totalCount: 0,
  });
  const navigate = useNavigate();

  const fetchPages = async () => {
    setLoadingPages(true);
    try {
      const response = await CommentService.getFacebookPages();
      if (response.success && response.data) {
        setPages(response.data);
        // Auto-select first page if available
        if (response.data.length > 0 && !selectedPage) {
          setSelectedPage(response.data[0].pageId);
        }
      }
    } catch (error) {
      console.error("Error fetching pages:", error);
    } finally {
      setLoadingPages(false);
    }
  };

  const fetchPosts = async () => {
    if (!selectedPage) return;

    setLoading(true);
    try {
      const response = await CommentService.getPostsByPageId(selectedPage);
      if (response.success) {
        console.log(response.data);
        setPosts(response.data);
      }
    } catch (error) {
      console.error("Error fetching posts:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (key, value) => {
    setFilters((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const handlePageChange = (newPage) => {
    setFilters((prev) => ({
      ...prev,
      page: newPage,
    }));
  };

  useEffect(() => {
    fetchPages();
  }, []);

  useEffect(() => {
    if (selectedPage) {
      fetchPosts();
      fetchPageSettings();
    }
  }, [selectedPage]);

  const fetchPageSettings = async () => {
    if (!selectedPage) return;
    try {
      const response = await CommentService.getPageResponseMethod(selectedPage);
      if (response.success && response.data) {
        setPageSettings({
          responseMethod: response.data.responseMethod || "manual",
          commentMessages: response.data.commentMessages
            ? JSON.parse(response.data.commentMessages)
            : [""],
          fixedMessengerMessage: response.data.fixedMessengerMessage || "",
          aiPrompt: response.data.aiPrompt || "",
        });
      }
    } catch (error) {
      console.error("Error fetching page settings:", error);
    }
  };

  const savePageSettings = async () => {
    if (
      pageSettings.responseMethod === "fixed" &&
      (!pageSettings.commentMessages ||
        pageSettings.commentMessages.length === 0 ||
        !pageSettings.commentMessages[0].trim())
    ) {
      setPageSettingsMessage(t("postsManagement.note"));
      return;
    }

    setSavingPageSettings(true);
    setPageSettingsMessage("");
    try {
      const response = await CommentService.setPageResponseMethod(
        selectedPage,
        pageSettings,
      );
      if (response.success) {
        setPageSettingsMessage(t("pageComments.savedSuccessfully") + " ✅");
        setTimeout(() => {
          setShowPageSettings(false);
          setPageSettingsMessage("");
        }, 2000);
      }
    } catch (error) {
      setPageSettingsMessage(
        t("pageComments.saveError") + ": " + error.message,
      );
    } finally {
      setSavingPageSettings(false);
    }
  };

  const getResponseMethodLabel = (method) => {
    switch (method) {
      case "ai":
        return t("unifiedComments.aiResponse");
      case "fixed":
        return t("unifiedComments.fixedResponse");
      case "manual":
        return t("unifiedComments.manualResponse");
      default:
        return t("unifiedComments.notSpecified");
    }
  };

  const getResponseMethodColor = (method) => {
    switch (method) {
      case "ai":
        return "bg-blue-100 text-blue-800";
      case "fixed":
        return "bg-green-100 text-green-800";
      case "manual":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  // Calculate stats
  const totalPosts = posts.length;
  const totalComments = posts.reduce(
    (sum, post) => sum + (post.totalComments || 0),
    0,
  );
  const respondedComments = posts.reduce(
    (sum, post) => sum + (post.respondedComments || 0),
    0,
  );
  const avgResponseRate =
    posts.length > 0
      ? Math.round(
          posts.reduce((sum, post) => sum + (post.responseRate || 0), 0) /
            posts.length,
        )
      : 0;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 p-4 md:p-8">
      <div className="w-full">
        {/* Header with Stats */}
        <div className="mb-8 animate-fade-in">
          {/* Title Section */}
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-6 mb-6">
            <div className="flex items-center gap-4">
              <div className="relative">
                <div className="absolute inset-0 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-2xl blur-lg opacity-50 animate-pulse"></div>
                <div className="relative p-4 bg-gradient-to-br from-blue-600 via-indigo-600 to-purple-600 rounded-2xl shadow-2xl">
                  <MessageSquare className="w-8 h-8 text-white" />
                </div>
              </div>
              <div>
                <h1 className="text-4xl font-black bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">
                  {t("postsManagement.pageTitle")}
                </h1>
                <p className="text-slate-600 dark:text-gray-300 mt-2 text-lg font-medium">
                  {t("postsManagement.pageSubtitle")}
                </p>
              </div>
            </div>
          </div>

          {/* Stats Cards */}
          {selectedPage && posts.length > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-fade-in">
              {/* Total Posts */}
              <div className="bg-gradient-to-br from-blue-500 to-blue-600 rounded-2xl p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105 border border-blue-400/20">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-blue-100 text-sm font-semibold mb-1">
                      إجمالي المنشورات
                    </p>
                    <h3 className="text-4xl font-black text-white">
                      {totalPosts}
                    </h3>
                  </div>
                  <div className="p-4 bg-white/20 rounded-xl backdrop-blur-sm">
                    <Grid3x3 className="w-8 h-8 text-white" />
                  </div>
                </div>
              </div>

              {/* Total Comments */}
              <div className="bg-gradient-to-br from-indigo-500 to-indigo-600 rounded-2xl p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105 border border-indigo-400/20">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-indigo-100 text-sm font-semibold mb-1">
                      إجمالي التعليقات
                    </p>
                    <h3 className="text-4xl font-black text-white">
                      {totalComments}
                    </h3>
                  </div>
                  <div className="p-4 bg-white/20 rounded-xl backdrop-blur-sm">
                    <MessageSquare className="w-8 h-8 text-white" />
                  </div>
                </div>
              </div>

              {/* Responded Comments */}
              <div className="bg-gradient-to-br from-green-500 to-green-600 rounded-2xl p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105 border border-green-400/20">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-green-100 text-sm font-semibold mb-1">
                      تم الرد عليها
                    </p>
                    <h3 className="text-4xl font-black text-white">
                      {respondedComments}
                    </h3>
                  </div>
                  <div className="p-4 bg-white/20 rounded-xl backdrop-blur-sm">
                    <CheckCircle className="w-8 h-8 text-white" />
                  </div>
                </div>
              </div>

              {/* Average Response Rate */}
              <div className="bg-gradient-to-br from-purple-500 to-purple-600 rounded-2xl p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105 border border-purple-400/20">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-purple-100 text-sm font-semibold mb-1">
                      معدل الاستجابة
                    </p>
                    <h3 className="text-4xl font-black text-white">
                      {avgResponseRate}%
                    </h3>
                  </div>
                  <div className="p-4 bg-white/20 rounded-xl backdrop-blur-sm">
                    <TrendingUp className="w-8 h-8 text-white" />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Page Selector */}
        <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl p-6 mb-8 border border-white/30 dark:border-gray-700/30">
          <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-4 flex items-center gap-2">
            <MessageSquare className="w-5 h-5 text-blue-600" />
            {t("postsManagement.selectPage")}
          </label>
          {loadingPages ? (
            <div className="text-center py-4">
              <div className="inline-block animate-spin rounded-full h-8 w-8 border-4 border-blue-500 border-t-transparent"></div>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {pages.map((page) => (
                <div
                  key={page.pageId}
                  className={`p-5 rounded-2xl border-2 transition-all duration-300 ${
                    selectedPage === page.pageId
                      ? "border-blue-500 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 shadow-xl scale-105"
                      : "border-slate-200 dark:border-gray-600 bg-white dark:bg-gray-700 hover:border-blue-300 hover:shadow-lg hover:scale-102"
                  }`}
                >
                  <div className="flex items-start justify-between gap-2 mb-3">
                    <div className="flex-1 text-right">
                      <div className="font-bold text-slate-800">
                        {page.pageName}
                      </div>
                      <div className="text-sm text-slate-600 mt-2 flex gap-3">
                        <span>📝 {page.totalPosts} منشور</span>
                        <span>💬 {page.totalComments} تعليق</span>
                      </div>
                    </div>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setSelectedPage(page.pageId);
                        setShowPageSettings(true);
                      }}
                      className="group p-2.5 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl hover:from-indigo-700 hover:to-purple-700 transition-all duration-300 shadow-md hover:shadow-xl hover:scale-110 flex-shrink-0"
                      title={t("postsManagement.pageSettings")}
                    >
                      <Settings className="w-5 h-5 group-hover:rotate-90 transition-transform duration-300" />
                    </button>
                  </div>
                  <button
                    onClick={() => setSelectedPage(page.pageId)}
                    className="w-full px-4 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white text-sm font-bold rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105"
                  >
                    {t("postsManagement.viewPosts")}
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Filters */}
        {selectedPage && (
          <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl p-6 mb-8 border border-white/30 dark:border-gray-700/30">
            <div className="flex items-center gap-2 mb-5">
              <div className="p-2 bg-gradient-to-br from-blue-500 to-indigo-500 rounded-lg">
                <Filter className="w-5 h-5 text-white" />
              </div>
              <h2 className="text-xl font-bold text-slate-800 dark:text-white">
                فلاتر البحث
              </h2>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
              <div>
                <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                  <Search className="w-4 h-4 text-blue-600" />
                  {t("postsManagement.search")}
                </label>
                <div className="relative">
                  <Search className="absolute right-4 top-1/2 transform -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input
                    type="text"
                    className="w-full pr-12 pl-4 py-3.5 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 border-2 border-slate-200 dark:border-gray-600 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400 transition-all text-right font-medium shadow-sm"
                    placeholder={t("postsManagement.searchPlaceholder")}
                    value={filters.search}
                    onChange={(e) =>
                      handleFilterChange("search", e.target.value)
                    }
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                  <Clock className="w-4 h-4 text-blue-600" />
                  {t("postsManagement.status")}
                </label>
                <select
                  className="w-full px-4 py-3.5 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 border-2 border-slate-200 dark:border-gray-600 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200 text-gray-900 dark:text-white transition-all text-right font-semibold shadow-sm"
                  value={filters.status}
                  onChange={(e) => handleFilterChange("status", e.target.value)}
                >
                  <option value="all">
                    📊 {t("postsManagement.allPosts")}
                  </option>
                  <option value="responded">
                    ✅ {t("postsManagement.responded")}
                  </option>
                  <option value="pending">
                    ⏳ {t("postsManagement.pending")}
                  </option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                  <List className="w-4 h-4 text-blue-600" />
                  {t("postsManagement.itemsCount")}
                </label>
                <select
                  className="w-full px-4 py-3.5 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 border-2 border-slate-200 dark:border-gray-600 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200 text-gray-900 dark:text-white transition-all text-right font-semibold shadow-sm"
                  value={filters.limit}
                  onChange={(e) =>
                    handleFilterChange("limit", parseInt(e.target.value))
                  }
                >
                  <option value="10">10 منشورات</option>
                  <option value="20">20 منشور</option>
                  <option value="50">50 منشور</option>
                  <option value="100">100 منشور</option>
                </select>
              </div>

              <div className="flex items-end">
                <button
                  className="group w-full max-w-xs bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-3.5 px-6 rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all duration-300 shadow-lg hover:shadow-xl hover:scale-105 flex items-center justify-center gap-2 font-bold"
                  onClick={() => fetchPosts()}
                  disabled={loading}
                >
                  <RefreshCw
                    className={`w-5 h-5 ${loading ? "animate-spin" : "group-hover:rotate-180 transition-transform duration-500"}`}
                  />
                  {t("postsManagement.refresh")}
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Posts Grid - Facebook Style */}
        {selectedPage && (
          <div>
            {loading ? (
              <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl p-16 text-center border border-white/30 dark:border-gray-700/30">
                <div className="relative inline-block">
                  <div className="absolute inset-0 bg-blue-500 rounded-full blur-xl opacity-30 animate-pulse"></div>
                  <div className="relative inline-block animate-spin rounded-full h-16 w-16 border-4 border-blue-500 border-t-transparent"></div>
                </div>
                <p className="mt-6 text-slate-600 dark:text-gray-300 font-bold text-lg">
                  {t("postsManagement.loadingPosts")}
                </p>
                <p className="mt-2 text-slate-500 dark:text-gray-400 text-sm">
                  الرجاء الانتظار...
                </p>
              </div>
            ) : (
              <>
                {posts.length === 0 ? (
                  <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl p-16 text-center border border-white/30 dark:border-gray-700/30">
                    <div className="relative inline-block mb-6">
                      <div className="absolute inset-0 bg-blue-200 rounded-full blur-2xl opacity-20"></div>
                      <div className="relative bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 p-8 rounded-3xl border-2 border-dashed border-blue-200 dark:border-blue-700">
                        <MessageSquare className="w-24 h-24 text-blue-400" />
                      </div>
                    </div>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
                      {t("postsManagement.noPosts")}
                    </h3>
                    <p className="text-slate-500 dark:text-gray-400 text-lg">
                      لم يتم العثور على أي منشورات
                    </p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {posts.map((post, index) => (
                      <div
                        key={post.postId}
                        className="bg-white dark:bg-gray-800 rounded-3xl shadow-xl hover:shadow-2xl transition-all duration-300 border-2 border-slate-200 dark:border-gray-700 overflow-hidden hover:scale-105 hover:border-blue-400 animate-fade-in"
                        style={{ animationDelay: `${index * 0.1}s` }}
                      >
                        {/* Post Image */}
                        {post.pictureUrl && (
                          <div className="relative h-48 bg-slate-100 overflow-hidden">
                            <img
                              src={post.pictureUrl}
                              alt="Post"
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                e.target.style.display = "none";
                              }}
                            />
                          </div>
                        )}

                        {/* Post Header */}
                        <div className="p-4 border-b border-slate-100">
                          <div className="flex items-start gap-3">
                            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center flex-shrink-0">
                              <MessageSquare className="w-5 h-5 text-white" />
                            </div>
                            <div className="flex-1 min-w-0">
                              <div
                                className="text-sm font-bold text-slate-900 truncate"
                                title={post.postId}
                              >
                                {t("postsManagement.postLabel")} #
                                {post.postId.substring(post.postId.length - 8)}
                              </div>
                              <div className="text-xs text-slate-500">
                                {post.firstCommentTime || post.lastCommentTime
                                  ? new Date(
                                      post.firstCommentTime ||
                                        post.lastCommentTime,
                                    ).toLocaleDateString("ar-EG", {
                                      year: "numeric",
                                      month: "short",
                                      day: "numeric",
                                      hour: "2-digit",
                                      minute: "2-digit",
                                    })
                                  : "No date"}
                              </div>
                            </div>
                            <span
                              className={`px-2 py-1 text-xs font-bold rounded-full ${getResponseMethodColor(post.responseMethod)}`}
                            >
                              {post.responseMethod === "ai"
                                ? "🤖"
                                : post.responseMethod === "fixed"
                                  ? "📝"
                                  : "✋"}
                            </span>
                          </div>

                          {/* Post Description */}
                          {post.message && (
                            <div
                              className="mt-3 text-xs text-slate-600 line-clamp-3"
                              title={post.message}
                            >
                              {post.message}
                            </div>
                          )}
                        </div>

                        {/* Latest Comment Preview */}
                        {post.latestComment && (
                          <div className="p-4 bg-slate-50 border-b border-slate-100">
                            <div className="flex items-start gap-2">
                              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-purple-400 to-pink-500 flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                                {(post.latestComment.senderName || "?").charAt(
                                  0,
                                )}
                              </div>
                              <div className="flex-1 min-w-0">
                                <div className="text-xs font-semibold text-slate-700">
                                  {post.latestComment.senderName ||
                                    t("postsManagement.unknownCustomer")}
                                </div>
                                <div
                                  className="text-xs text-slate-600 mt-1 line-clamp-2"
                                  title={post.latestComment.message}
                                >
                                  {post.latestComment.message ||
                                    t("postsManagement.image")}
                                </div>
                              </div>
                            </div>
                          </div>
                        )}

                        {/* Stats */}
                        <div className="p-4 space-y-3">
                          {/* Comments Count */}
                          <div className="flex items-center justify-between">
                            <span className="text-xs text-slate-600 font-medium">
                              {t("postsManagement.comments")}
                            </span>
                            <div className="flex items-center gap-2">
                              <span className="px-2 py-1 bg-blue-100 text-blue-800 text-xs font-bold rounded-full">
                                {post.totalComments}
                              </span>
                              <span className="px-2 py-1 bg-green-100 text-green-800 text-xs font-bold rounded-full flex items-center gap-1">
                                <CheckCircle className="w-3 h-3" />
                                {post.respondedComments}
                              </span>
                              <span className="px-2 py-1 bg-amber-100 text-amber-800 text-xs font-bold rounded-full flex items-center gap-1">
                                <Clock className="w-3 h-3" />
                                {post.pendingComments}
                              </span>
                            </div>
                          </div>

                          {/* Response Rate */}
                          <div>
                            <div className="flex items-center justify-between mb-1">
                              <span className="text-xs text-slate-600 font-medium">
                                {t("postsManagement.responseRate")}
                              </span>
                              <span className="text-xs font-bold text-slate-700">
                                {post.responseRate}%
                              </span>
                            </div>
                            <div className="w-full bg-slate-200 rounded-full h-2">
                              <div
                                className="bg-gradient-to-r from-blue-500 to-indigo-600 h-2 rounded-full transition-all"
                                style={{ width: `${post.responseRate}%` }}
                              ></div>
                            </div>
                          </div>

                          {/* Response Method */}
                          <div className="pt-2 border-t border-slate-100">
                            <span
                              className={`px-3 py-1.5 inline-flex items-center gap-1 text-xs font-bold rounded-full w-full justify-center ${getResponseMethodColor(post.responseMethod)}`}
                            >
                              {getResponseMethodLabel(post.responseMethod)}
                            </span>
                          </div>
                        </div>

                        {/* Actions */}
                        <div className="p-4 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 flex gap-3">
                          <button
                            onClick={() =>
                              navigate(`/posts/${post.postId}/comments`)
                            }
                            className="group flex-1 px-4 py-2.5 bg-gradient-to-r from-blue-600 to-blue-700 text-white text-sm font-bold rounded-xl hover:from-blue-700 hover:to-blue-800 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105 flex items-center justify-center gap-2"
                          >
                            <MessageSquare className="w-4 h-4 group-hover:scale-110 transition-transform" />
                            {t("postsManagement.viewComments")}
                          </button>
                          <button
                            onClick={() =>
                              navigate(`/posts/${post.postId}/settings`)
                            }
                            className="group flex-1 px-4 py-2.5 bg-gradient-to-r from-indigo-600 to-purple-600 text-white text-sm font-bold rounded-xl hover:from-indigo-700 hover:to-purple-700 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105 flex items-center justify-center gap-2"
                          >
                            <Settings className="w-4 h-4 group-hover:rotate-90 transition-transform duration-300" />
                            {t("postsManagement.settings")}
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Pagination */}
                {pagination.totalPages > 1 && (
                  <div className="mt-6 bg-white/80 backdrop-blur-xl rounded-2xl shadow-xl p-6 border border-white/20">
                    <div className="flex-1 flex justify-between sm:hidden">
                      <button
                        onClick={() =>
                          handlePageChange(pagination.currentPage - 1)
                        }
                        disabled={pagination.currentPage === 1}
                        className="relative inline-flex items-center px-4 py-2 border-2 border-slate-300 text-sm font-semibold rounded-xl text-slate-700 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                      >
                        {t("postsManagement.previous")}
                      </button>
                      <button
                        onClick={() =>
                          handlePageChange(pagination.currentPage + 1)
                        }
                        disabled={
                          pagination.currentPage === pagination.totalPages
                        }
                        className="mr-3 relative inline-flex items-center px-4 py-2 border-2 border-slate-300 text-sm font-semibold rounded-xl text-slate-700 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                      >
                        {t("postsManagement.next")}
                      </button>
                    </div>
                    <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
                      <div>
                        <p className="text-sm text-slate-700 font-medium">
                          {t("postsManagement.showing")}{" "}
                          <span className="font-bold text-blue-600">
                            {(pagination.currentPage - 1) * filters.limit + 1}
                          </span>{" "}
                          {t("postsManagement.to")}{" "}
                          <span className="font-bold text-blue-600">
                            {Math.min(
                              pagination.currentPage * filters.limit,
                              pagination.totalCount,
                            )}
                          </span>{" "}
                          {t("postsManagement.of")}{" "}
                          <span className="font-bold text-blue-600">
                            {pagination.totalCount}
                          </span>{" "}
                          {t("postsManagement.result")}
                        </p>
                      </div>
                      <div>
                        <nav
                          className="relative z-0 inline-flex rounded-xl shadow-sm gap-1"
                          aria-label="Pagination"
                        >
                          <button
                            onClick={() =>
                              handlePageChange(pagination.currentPage - 1)
                            }
                            disabled={pagination.currentPage === 1}
                            className="relative inline-flex items-center px-3 py-2 rounded-lg bg-white border-2 border-slate-300 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                          >
                            {t("postsManagement.previous")}
                          </button>
                          {[...Array(Math.min(pagination.totalPages, 7))].map(
                            (_, i) => {
                              let page;
                              if (pagination.totalPages <= 7) {
                                page = i + 1;
                              } else if (pagination.currentPage <= 4) {
                                page = i + 1;
                              } else if (
                                pagination.currentPage >=
                                pagination.totalPages - 3
                              ) {
                                page = pagination.totalPages - 6 + i;
                              } else {
                                page = pagination.currentPage - 3 + i;
                              }

                              return (
                                <button
                                  key={page}
                                  onClick={() => handlePageChange(page)}
                                  className={`relative inline-flex items-center px-4 py-2 text-sm font-bold rounded-lg transition-all ${
                                    page === pagination.currentPage
                                      ? "bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg scale-105"
                                      : "bg-white border-2 border-slate-300 text-slate-700 hover:bg-slate-50"
                                  }`}
                                >
                                  {page}
                                </button>
                              );
                            },
                          )}
                          <button
                            onClick={() =>
                              handlePageChange(pagination.currentPage + 1)
                            }
                            disabled={
                              pagination.currentPage === pagination.totalPages
                            }
                            className="relative inline-flex items-center px-3 py-2 rounded-lg bg-white border-2 border-slate-300 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                          >
                            {t("postsManagement.next")}
                          </button>
                        </nav>
                      </div>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* Page Settings Modal */}
        {showPageSettings && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-y-auto">
              {/* Modal Header */}
              <div className="sticky top-0 bg-gradient-to-r from-indigo-600 to-purple-600 text-white p-6 rounded-t-2xl flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Settings className="w-6 h-6" />
                  <div>
                    <h2 className="text-2xl font-bold">
                      {t("postsManagement.pageSettings")}
                    </h2>
                    <p className="text-sm text-white/80 mt-1">
                      {pages.find((p) => p.pageId === selectedPage)?.pageName ||
                        t("postsManagement.selectPage")}
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => setShowPageSettings(false)}
                  className="p-2 hover:bg-white/20 rounded-lg transition"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>

              {/* Modal Content */}
              <div className="p-6 space-y-6">
                <div className="bg-blue-50 border-r-4 border-blue-500 p-4 rounded-lg">
                  <p className="text-sm text-blue-800 font-medium">
                    ℹ️ <strong>{t("postsManagement.note")}:</strong>{" "}
                    {t("postsManagement.noteFallback")}
                  </p>
                  <p className="text-xs text-blue-700 mt-2">
                    • {t("postsManagement.noteFallback")}
                  </p>
                </div>

                {/* Response Method Selection */}
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-3">
                    {t("postsManagement.responseMethodLabel")}
                  </label>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                    <button
                      onClick={() =>
                        setPageSettings((prev) => ({
                          ...prev,
                          responseMethod: "ai",
                        }))
                      }
                      className={`p-4 rounded-xl border-2 transition-all ${
                        pageSettings.responseMethod === "ai"
                          ? "border-blue-500 bg-blue-50 shadow-lg"
                          : "border-slate-200 hover:border-blue-300"
                      }`}
                    >
                      <div className="text-center">
                        <div className="text-2xl mb-2">🤖</div>
                        <div className="font-bold text-slate-800">
                          {t("postsManagement.ai")}
                        </div>
                      </div>
                    </button>
                    <button
                      onClick={() =>
                        setPageSettings((prev) => ({
                          ...prev,
                          responseMethod: "fixed",
                        }))
                      }
                      className={`p-4 rounded-xl border-2 transition-all ${
                        pageSettings.responseMethod === "fixed"
                          ? "border-green-500 bg-green-50 shadow-lg"
                          : "border-slate-200 hover:border-green-300"
                      }`}
                    >
                      <div className="text-center">
                        <div className="text-2xl mb-2">📝</div>
                        <div className="font-bold text-slate-800">
                          {t("postsManagement.fixed")}
                        </div>
                      </div>
                    </button>
                    <button
                      onClick={() =>
                        setPageSettings((prev) => ({
                          ...prev,
                          responseMethod: "manual",
                        }))
                      }
                      className={`p-4 rounded-xl border-2 transition-all ${
                        pageSettings.responseMethod === "manual"
                          ? "border-yellow-500 bg-yellow-50 shadow-lg"
                          : "border-slate-200 hover:border-yellow-300"
                      }`}
                    >
                      <div className="text-center">
                        <div className="text-2xl mb-2">✋</div>
                        <div className="font-bold text-slate-800">
                          {t("postsManagement.manual")}
                        </div>
                      </div>
                    </button>
                  </div>
                </div>

                {/* AI Settings */}
                {pageSettings.responseMethod === "ai" && (
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">
                      {t("postsManagement.aiPromptOptional")}
                    </label>
                    <textarea
                      className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 transition-all"
                      rows="4"
                      value={pageSettings.aiPrompt}
                      onChange={(e) =>
                        setPageSettings((prev) => ({
                          ...prev,
                          aiPrompt: e.target.value,
                        }))
                      }
                      placeholder={t("postsManagement.enterAIPrompt")}
                    />
                  </div>
                )}

                {/* Fixed Response Settings */}
                {pageSettings.responseMethod === "fixed" && (
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-2">
                        {t("postsManagement.fixedCommentVariations")}
                      </label>
                      {pageSettings.commentMessages.map((msg, index) => (
                        <div key={index} className="mb-2 flex gap-2">
                          <textarea
                            className="flex-1 px-3 py-2 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 transition-all"
                            rows="2"
                            value={msg}
                            onChange={(e) => {
                              const newMessages = [
                                ...pageSettings.commentMessages,
                              ];
                              newMessages[index] = e.target.value;
                              setPageSettings((prev) => ({
                                ...prev,
                                commentMessages: newMessages,
                              }));
                            }}
                            placeholder={`${t("unifiedComments.reply")} ${index + 1}...`}
                          />
                          {pageSettings.commentMessages.length > 1 && (
                            <button
                              onClick={() => {
                                const newMessages =
                                  pageSettings.commentMessages.filter(
                                    (_, i) => i !== index,
                                  );
                                setPageSettings((prev) => ({
                                  ...prev,
                                  commentMessages: newMessages,
                                }));
                              }}
                              className="px-3 py-2 bg-red-500 text-white rounded-xl hover:bg-red-600 transition"
                            >
                              {t("postsManagement.cancel")}
                            </button>
                          )}
                        </div>
                      ))}
                      <button
                        onClick={() => {
                          setPageSettings((prev) => ({
                            ...prev,
                            commentMessages: [...prev.commentMessages, ""],
                          }));
                        }}
                        className="mt-2 px-4 py-2 bg-green-500 text-white rounded-xl hover:bg-green-600 transition text-sm"
                      >
                        {t("postsManagement.addReply")}
                      </button>
                    </div>

                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-2">
                        {t("postsManagement.fixedMessengerMessage")}
                      </label>
                      <textarea
                        className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 transition-all"
                        rows="3"
                        value={pageSettings.fixedMessengerMessage}
                        onChange={(e) =>
                          setPageSettings((prev) => ({
                            ...prev,
                            fixedMessengerMessage: e.target.value,
                          }))
                        }
                        placeholder={t("postsManagement.enterMessengerMessage")}
                      />
                    </div>
                  </div>
                )}

                {/* Message */}
                {pageSettingsMessage && (
                  <div
                    className={`p-4 rounded-xl text-center font-medium ${
                      pageSettingsMessage.includes("خطأ") ||
                      pageSettingsMessage.includes("Error")
                        ? "bg-red-100 text-red-700"
                        : "bg-green-100 text-green-700"
                    }`}
                  >
                    {pageSettingsMessage}
                  </div>
                )}

                {/* Actions */}
                <div className="flex gap-3 pt-4 border-t border-slate-200">
                  <button
                    onClick={savePageSettings}
                    disabled={savingPageSettings}
                    className="flex-1 flex items-center justify-center gap-2 px-6 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl hover:from-indigo-700 hover:to-purple-700 transition-all shadow-lg hover:shadow-xl disabled:opacity-50"
                  >
                    <Save className="w-5 h-5" />
                    {savingPageSettings
                      ? t("postsManagement.saving")
                      : t("postsManagement.saveSettings")}
                  </button>
                  <button
                    onClick={() => setShowPageSettings(false)}
                    className="px-6 py-3 bg-slate-200 text-slate-700 rounded-xl hover:bg-slate-300 transition-all"
                  >
                    {t("postsManagement.cancel")}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Add custom CSS animations
const style = document.createElement("style");
style.textContent = `
  @keyframes fade-in {
    from {
      opacity: 0;
      transform: translateY(-10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-fade-in {
    animation: fade-in 0.5s ease-out;
  }
`;
if (!document.head.querySelector("style[data-posts-management]")) {
  style.setAttribute("data-posts-management", "true");
  document.head.appendChild(style);
}

export default PostsManagement;

import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import CommentService from "../../services/commentService";
import {
  MessageSquare,
  CheckCircle,
  Clock,
  Search,
  RefreshCw,
  Edit3,
  Trash2,
  Settings,
  ArrowLeft,
  TrendingUp,
  Users,
  BarChart3,
  Sparkles,
} from "lucide-react";

const UnifiedCommentsManagement = () => {
  const { postId: urlPostId } = useParams();
  const navigate = useNavigate();
  const [posts, setPosts] = useState([]);
  const [comments, setComments] = useState([]);
  const [loading, setLoading] = useState(false);
  const [activePostId, setActivePostId] = useState(urlPostId || null);
  const [selectedComments, setSelectedComments] = useState([]); // For bulk operations
  const [postSettings, setPostSettings] = useState(null); // To store post response settings
  const [filters, setFilters] = useState({
    page: 1,
    limit: 20,
    search: "",
    status: "all",
  });
  const [pagination, setPagination] = useState({
    currentPage: 1,
    totalPages: 1,
    totalCount: 0,
  });

  // Fetch posts
  const fetchPosts = async () => {
    setLoading(true);
    try {
      const response = await CommentService.getFacebookPosts(filters);
      if (response.success) {
        setPosts(response.data);
        setPagination(response.pagination);
      }
    } catch (error) {
      console.error("Error fetching posts:", error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch comments for a specific post
  const fetchComments = async (postId) => {
    setLoading(true);
    try {
      const response = await CommentService.getCommentsByPostId(postId, {
        status: filters.status,
      });
      if (response.success) {
        setComments(response.data);
      }
    } catch (error) {
      console.error("Error fetching comments:", error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch post response settings
  const fetchPostSettings = async (postId) => {
    try {
      const response = await CommentService.getPostResponseMethod(postId);
      if (response.success) {
        setPostSettings(response.data);
      }
    } catch (error) {
      console.error("Error fetching post settings:", error);
    }
  };

  const handleFilterChange = (key, value) => {
    setFilters((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const handlePageChange = (newPage) => {
    setFilters((prev) => ({
      ...prev,
      page: newPage,
    }));
  };

  const handleUpdateResponse = async (commentId, response) => {
    if (!response || !response.trim()) {
      alert("الرجاء إدخال رد قبل الحفظ.");
      return;
    }

    try {
      const result = await CommentService.sendManualResponseToFacebook(
        commentId,
        response,
      );
      if (result.success) {
        // Refresh comments
        if (activePostId) {
          fetchComments(activePostId);
        }
        alert("تم حفظ الرد وإرساله إلى فيسبوك بنجاح!");
      }
    } catch (error) {
      alert("خطأ في تحديث رد التعليق: " + error.message);
    }
  };

  const handleDeleteComment = async (commentId) => {
    if (window.confirm("هل أنت متأكد من حذف هذا التعليق؟")) {
      try {
        const result = await CommentService.deleteFacebookComment(commentId);
        if (result.success) {
          // Refresh comments
          if (activePostId) {
            fetchComments(activePostId);
          }
        }
      } catch (error) {
        console.error("Error deleting comment:", error);
      }
    }
  };

  const handleFilterCommentAI = async (commentId) => {
    try {
      setLoading(true);
      const result = await CommentService.filterCommentAI(commentId);
      if (result.success) {
        const { sentiment, actionTaken, isNegative } = result.data;
        let message = `تحليل المشاعر: ${sentiment}.`;

        if (isNegative) {
          message += ` تم اكتشاف تعليق سلبي واتخاذ إجراء: ${actionTaken === 'hide' ? 'إخفاء' : 'حذف'}.`;
        } else {
          message += ` التعليق آمن.`;
        }

        alert(message);
        // Refresh comments to show updated status/removal
        if (activePostId) {
          fetchComments(activePostId);
        }
      }
    } catch (error) {
      alert("خطأ في فلترة التعليق: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleViewComments = (postId) => {
    setActivePostId(postId);
    fetchComments(postId);
    fetchPostSettings(postId); // Fetch post settings when viewing comments
    // Update URL without page reload
    window.history.pushState({}, "", `/unified-comments/${postId}`);
  };

  const handleBackToPosts = () => {
    setActivePostId(null);
    // Update URL without page reload
    window.history.pushState({}, "", "/unified-comments");
  };

  // Handle bulk delete
  const handleBulkDelete = async () => {
    if (selectedComments.length === 0) {
      alert("الرجاء اختيار تعليقات لحذفها");
      return;
    }

    if (
      window.confirm(`هل أنت متأكد من حذف ${selectedComments.length} تعليق؟`)
    ) {
      try {
        const result =
          await CommentService.bulkDeleteFacebookComments(selectedComments);
        if (result.success) {
          // Refresh comments
          if (activePostId) {
            fetchComments(activePostId);
          }
          // Clear selection
          setSelectedComments([]);
          alert("تم حذف التعليقات بنجاح");
        }
      } catch (error) {
        console.error("Error deleting comments:", error);
        alert("حدث خطأ أثناء حذف التعليقات: " + error.message);
      }
    }
  };

  // Handle select/deselect comment
  const toggleCommentSelection = (commentId) => {
    setSelectedComments((prev) => {
      if (prev.includes(commentId)) {
        return prev.filter((id) => id !== commentId);
      } else {
        return [...prev, commentId];
      }
    });
  };

  // Handle select all comments
  const toggleSelectAll = () => {
    if (selectedComments.length === comments.length) {
      // Deselect all
      setSelectedComments([]);
    } else {
      // Select all
      setSelectedComments(comments.map((comment) => comment.id));
    }
  };

  const getResponseMethodLabel = (method) => {
    switch (method) {
      case "ai":
        return "رد تلقائي بالذكاء الاصطناعي";
      case "fixed":
        return "رد محدد مسبقًا";
      case "manual":
        return "رد يدوي";
      default:
        return "غير محدد";
    }
  };

  const getResponseMethodColor = (method) => {
    switch (method) {
      case "ai":
        return "bg-blue-100 text-blue-800";
      case "fixed":
        return "bg-green-100 text-green-800";
      case "manual":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  useEffect(() => {
    if (activePostId) {
      fetchComments(activePostId);
    } else {
      fetchPosts();
    }
  }, [filters, activePostId]);

  // If we're viewing comments for a specific post
  if (activePostId) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 p-4 md:p-8">
        <div className="w-full">
          {/* Header */}
          <div className="mb-8 animate-fade-in">
            <div className="flex items-center gap-4 mb-2">
              <div className="relative">
                <div className="absolute inset-0 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-2xl blur-lg opacity-50 animate-pulse"></div>
                <div className="relative p-4 bg-gradient-to-br from-blue-600 via-indigo-600 to-purple-600 rounded-2xl shadow-2xl">
                  <MessageSquare className="w-8 h-8 text-white" />
                </div>
              </div>
              <div>
                <h1 className="text-4xl font-black bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">
                  تعليقات المنشور
                </h1>
                <p className="text-slate-600 dark:text-gray-300 mt-2 text-lg font-medium">
                  إدارة والرد على تعليقات المنشور بكل سهولة
                </p>
              </div>
            </div>
          </div>

          {/* Back Button and Post Info */}
          <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl p-6 mb-8 border border-white/30 dark:border-gray-700/30 hover:shadow-blue-200/50 dark:hover:shadow-blue-900/50 transition-all duration-300">
            <div className="flex flex-wrap items-center justify-between gap-4">
              <button
                onClick={handleBackToPosts}
                className="group flex items-center gap-2 px-5 py-3 bg-gradient-to-r from-slate-100 to-slate-200 dark:from-gray-700 dark:to-gray-600 rounded-xl hover:from-blue-50 hover:to-indigo-50 dark:hover:from-blue-900/30 dark:hover:to-indigo-900/30 transition-all duration-300 shadow-md hover:shadow-lg font-semibold text-slate-700 dark:text-gray-200"
              >
                <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform duration-300" />
                العودة إلى المنشورات
              </button>

              <div className="flex-1 min-w-0">
                <h2 className="text-lg font-semibold text-slate-800 dark:text-white truncate">
                  معرف المنشور: {activePostId}
                </h2>
                {postSettings && (
                  <div className="mt-1">
                    <span
                      className={`px-2 py-1 text-xs font-bold rounded-full ${getResponseMethodColor(postSettings.responseMethod)}`}
                    >
                      طريقة الرد:{" "}
                      {getResponseMethodLabel(postSettings.responseMethod)}
                    </span>
                  </div>
                )}
              </div>

              <div className="flex gap-3">
                <button
                  onClick={() => navigate(`/posts/${activePostId}/settings`)}
                  className="group flex items-center gap-2 px-5 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl hover:from-indigo-700 hover:to-purple-700 transition-all duration-300 shadow-lg hover:shadow-xl hover:scale-105 font-semibold"
                >
                  <Settings className="w-5 h-5 group-hover:rotate-90 transition-transform duration-300" />
                  إعدادات الرد
                </button>
                {selectedComments.length > 0 && (
                  <button
                    onClick={handleBulkDelete}
                    className="group flex items-center gap-2 px-5 py-3 bg-gradient-to-r from-red-600 to-rose-600 text-white rounded-xl hover:from-red-700 hover:to-rose-700 transition-all duration-300 shadow-lg hover:shadow-xl hover:scale-105 font-semibold animate-bounce-subtle"
                  >
                    <Trash2 className="w-5 h-5 group-hover:scale-110 transition-transform duration-300" />
                    حذف ({selectedComments.length})
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* Filters */}
          <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl p-6 mb-8 border border-white/30 dark:border-gray-700/30">
            <div className="flex flex-wrap gap-4 items-end">
              <div className="flex-1 min-w-[200px]">
                <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                  <Clock className="w-4 h-4 text-blue-600" />
                  فلتر حسب الحالة
                </label>
                <select
                  className="w-full px-4 py-3 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 border-2 border-slate-200 dark:border-gray-600 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200 text-gray-900 dark:text-white transition-all text-right font-semibold shadow-sm"
                  value={filters.status}
                  onChange={(e) => handleFilterChange("status", e.target.value)}
                >
                  <option value="all">📊 كل التعليقات</option>
                  <option value="responded">✅ تم الرد عليها</option>
                  <option value="pending">⏳ قيد الانتظار</option>
                </select>
              </div>

              <div>
                <button
                  className="group px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all duration-300 shadow-lg hover:shadow-xl hover:scale-105 flex items-center gap-2 font-semibold"
                  onClick={() => fetchComments(activePostId)}
                  disabled={loading}
                >
                  <RefreshCw
                    className={`w-5 h-5 ${loading ? "animate-spin" : "group-hover:rotate-180 transition-transform duration-500"}`}
                  />
                  تحديث
                </button>
              </div>
            </div>
          </div>

          {/* Comments List */}
          <div className="bg-white/80 dark:bg-gray-800/80 backdrop-blur-xl rounded-2xl shadow-xl overflow-hidden border border-white/20 dark:border-gray-700/20">
            {loading ? (
              <div className="p-16 text-center">
                <div className="relative inline-block">
                  <div className="absolute inset-0 bg-blue-500 rounded-full blur-xl opacity-30 animate-pulse"></div>
                  <div className="relative inline-block animate-spin rounded-full h-16 w-16 border-4 border-blue-500 border-t-transparent"></div>
                </div>
                <p className="mt-6 text-slate-600 dark:text-gray-300 font-bold text-lg">
                  جاري تحميل التعليقات...
                </p>
                <p className="mt-2 text-slate-500 dark:text-gray-400 text-sm">
                  الرجاء الانتظار
                </p>
              </div>
            ) : comments.length === 0 ? (
              <div className="p-16 text-center">
                <div className="relative inline-block mb-6">
                  <div className="absolute inset-0 bg-blue-200 rounded-full blur-2xl opacity-20"></div>
                  <div className="relative bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 p-6 rounded-3xl border-2 border-dashed border-blue-200 dark:border-blue-700">
                    <MessageSquare className="w-20 h-20 text-blue-400 mx-auto" />
                  </div>
                </div>
                <h3 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
                  لا توجد تعليقات
                </h3>
                <p className="text-slate-500 dark:text-gray-400 text-lg">
                  لا توجد تعليقات لهذا المنشور حتى الآن.
                </p>
              </div>
            ) : (
              <>
                {/* Bulk Actions Bar */}
                {selectedComments.length > 0 && (
                  <div className="bg-blue-50 border-b border-blue-100 px-6 py-3 flex items-center justify-between">
                    <div className="text-sm text-blue-800">
                      تم اختيار {selectedComments.length} تعليق
                    </div>
                    <div className="flex gap-2">
                      <button
                        onClick={handleBulkDelete}
                        className="flex items-center gap-1 px-3 py-1.5 text-sm bg-red-600 text-white rounded-md hover:bg-red-700 transition"
                      >
                        <Trash2 className="w-4 h-4" />
                        حذف الكل
                      </button>
                      <button
                        onClick={() => setSelectedComments([])}
                        className="px-3 py-1.5 text-sm bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition"
                      >
                        إلغاء الاختيار
                      </button>
                    </div>
                  </div>
                )}

                <div className="divide-y divide-slate-200 dark:divide-gray-700">
                  {comments.map((comment, index) => (
                    <div
                      key={comment.id}
                      className="p-6 hover:bg-gradient-to-r hover:from-blue-50/30 hover:to-indigo-50/30 dark:hover:bg-gray-700/50 transition-all duration-300 border-r-4 border-transparent hover:border-blue-500 animate-fade-in"
                      style={{ animationDelay: `${index * 0.05}s` }}
                    >
                      <div className="flex justify-between">
                        <div className="flex items-start gap-3">
                          <div className="pt-1">
                            <input
                              type="checkbox"
                              checked={selectedComments.includes(comment.id)}
                              onChange={() =>
                                toggleCommentSelection(comment.id)
                              }
                              className="h-5 w-5 text-blue-600 rounded focus:ring-blue-500"
                            />
                          </div>
                          <div className="bg-gray-200 border-2 border-dashed rounded-xl w-10 h-10" />
                          <div>
                            <div className="flex items-center gap-2">
                              <h4 className="text-sm font-semibold text-slate-900 dark:text-white">
                                {comment.senderName}
                              </h4>
                              <span className="text-xs text-slate-500">
                                {comment.senderId}
                              </span>
                            </div>
                            <p className="text-sm text-slate-500 mt-1">
                              {new Date(comment.createdTime).toLocaleString(
                                "ar-EG",
                              )}
                            </p>
                          </div>
                        </div>
                        <div>
                          {comment.respondedAt ? (
                            <span className="inline-flex items-center gap-1 px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">
                              <CheckCircle className="w-3 h-3" />
                              تم الرد
                            </span>
                          ) : (
                            <span className="inline-flex items-center gap-1 px-2 py-1 text-xs font-semibold rounded-full bg-amber-100 text-amber-800">
                              <Clock className="w-3 h-3" />
                              قيد الانتظار
                            </span>
                          )}
                        </div>
                      </div>

                      <div className="mt-4 ml-13">
                        <div className="bg-gradient-to-br from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-gray-600">
                          <p className="text-slate-800 dark:text-gray-100 leading-relaxed">
                            {comment.message}
                          </p>
                        </div>

                        {comment.response && (
                          <div className="mt-4 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 p-5 rounded-2xl border-2 border-blue-200 dark:border-blue-700 shadow-md">
                            <div className="flex items-start gap-2 mb-2">
                              <Sparkles className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
                              <div className="flex-1">
                                <p className="text-slate-800 dark:text-gray-100 leading-relaxed font-medium">
                                  {comment.response}
                                </p>
                                <p className="text-xs text-blue-600 dark:text-blue-400 mt-3 font-semibold">
                                  ✓ تم الرد في:{" "}
                                  {new Date(comment.respondedAt).toLocaleString(
                                    "ar-EG",
                                  )}
                                </p>
                              </div>
                            </div>
                          </div>
                        )}

                        <div className="mt-4 flex flex-wrap gap-3">
                          {!comment.respondedAt && (
                            <button
                              onClick={() => {
                                const response = prompt("اكتب ردك هنا:");
                                if (response !== null) {
                                  handleUpdateResponse(comment.id, response);
                                }
                              }}
                              className="group inline-flex items-center gap-2 px-4 py-2 text-sm bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105 font-semibold"
                            >
                              <Edit3 className="w-4 h-4 group-hover:scale-110 transition-transform" />
                              رد على التعليق
                            </button>
                          )}
                          <button
                            onClick={() => handleFilterCommentAI(comment.id)}
                            disabled={loading}
                            title="فلترة ذكية للكشف عن التعليقات السلبية"
                            className="group inline-flex items-center gap-2 px-4 py-2 text-sm bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl hover:from-purple-700 hover:to-indigo-700 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105 font-semibold disabled:opacity-50"
                          >
                            <Sparkles className="w-4 h-4 group-hover:scale-110 transition-transform" />
                            فلترة ذكية (AI)
                          </button>
                          <button
                            onClick={() => handleDeleteComment(comment.id)}
                            className="group inline-flex items-center gap-2 px-4 py-2 text-sm bg-gradient-to-r from-red-600 to-rose-600 text-white rounded-xl hover:from-red-700 hover:to-rose-700 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105 font-semibold"
                          >
                            <Trash2 className="w-4 h-4 group-hover:scale-110 transition-transform" />
                            حذف
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    );
  }

  // Default view: Show posts list
  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 p-4 md:p-8">
      <div className="w-full">
        {/* Header */}
        <div className="mb-8 animate-fade-in">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-6 mb-6">
            <div className="flex items-center gap-4">
              <div className="relative">
                <div className="absolute inset-0 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-2xl blur-lg opacity-50 animate-pulse"></div>
                <div className="relative p-4 bg-gradient-to-br from-blue-600 via-indigo-600 to-purple-600 rounded-2xl shadow-2xl">
                  <MessageSquare className="w-8 h-8 text-white" />
                </div>
              </div>
              <div>
                <h1 className="text-4xl font-black bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">
                  إدارة منشورات فيسبوك
                </h1>
                <p className="text-slate-600 dark:text-gray-300 mt-2 text-lg font-medium">
                  إدارة ومتابعة التعليقات بكل احترافية
                </p>
              </div>
            </div>

            {/* Quick Stats */}
            <div className="flex gap-4">
              <div className="bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 rounded-2xl p-4 border border-blue-100 dark:border-blue-800 shadow-lg">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-blue-600 rounded-lg">
                    <BarChart3 className="w-5 h-5 text-white" />
                  </div>
                  <div>
                    <p className="text-xs text-slate-600 dark:text-gray-400 font-medium">
                      إجمالي المنشورات
                    </p>
                    <p className="text-2xl font-black text-blue-600">
                      {pagination.totalCount || 0}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl p-6 mb-8 border border-white/30 dark:border-gray-700/30">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
            <div>
              <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                <Search className="w-4 h-4 text-blue-600" />
                بحث في المنشورات
              </label>
              <div className="relative">
                <Search className="absolute right-4 top-1/2 transform -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input
                  type="text"
                  className="w-full pr-12 pl-4 py-3.5 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 border-2 border-slate-200 dark:border-gray-600 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400 transition-all text-right font-medium shadow-sm"
                  placeholder="ابحث هنا..."
                  value={filters.search}
                  onChange={(e) => handleFilterChange("search", e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                <Clock className="w-4 h-4 text-blue-600" />
                فلتر الحالة
              </label>
              <select
                className="w-full px-4 py-3.5 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 border-2 border-slate-200 dark:border-gray-600 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200 text-gray-900 dark:text-white transition-all text-right font-semibold shadow-sm"
                value={filters.status}
                onChange={(e) => handleFilterChange("status", e.target.value)}
              >
                <option value="all">📊 كل المنشورات</option>
                <option value="responded">✅ تم الرد عليها</option>
                <option value="pending">⏳ قيد الانتظار</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                <BarChart3 className="w-4 h-4 text-blue-600" />
                عدد النتائج
              </label>
              <select
                className="w-full px-4 py-3.5 bg-gradient-to-r from-slate-50 to-slate-100 dark:from-gray-700 dark:to-gray-600 border-2 border-slate-200 dark:border-gray-600 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200 text-gray-900 dark:text-white transition-all text-right font-semibold shadow-sm"
                value={filters.limit}
                onChange={(e) =>
                  handleFilterChange("limit", parseInt(e.target.value))
                }
              >
                <option value="10">10 منشورات</option>
                <option value="20">20 منشور</option>
                <option value="50">50 منشور</option>
                <option value="100">100 منشور</option>
              </select>
            </div>

            <div className="flex items-end">
              <button
                className="group w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-3.5 px-6 rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all duration-300 shadow-lg hover:shadow-xl hover:scale-105 flex items-center justify-center gap-2 font-bold"
                onClick={() => fetchPosts()}
                disabled={loading}
              >
                <RefreshCw
                  className={`w-5 h-5 ${loading ? "animate-spin" : "group-hover:rotate-180 transition-transform duration-500"}`}
                />
                تحديث البيانات
              </button>
            </div>
          </div>
        </div>

        {/* Posts Table */}
        <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-2xl rounded-3xl shadow-2xl overflow-hidden border border-white/30 dark:border-gray-700/30 hover:shadow-blue-200/50 dark:hover:shadow-blue-900/50 transition-all duration-300">
          {loading ? (
            <div className="p-16 text-center">
              <div className="relative inline-block">
                <div className="absolute inset-0 bg-blue-500 rounded-full blur-xl opacity-30 animate-pulse"></div>
                <div className="relative inline-block animate-spin rounded-full h-16 w-16 border-4 border-blue-500 border-t-transparent"></div>
              </div>
              <p className="mt-6 text-slate-600 dark:text-gray-300 font-bold text-lg">
                جاري تحميل المنشورات...
              </p>
              <p className="mt-2 text-slate-500 dark:text-gray-400 text-sm">
                الرجاء الانتظار
              </p>
            </div>
          ) : (
            <>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-slate-200">
                  <thead className="bg-gradient-to-r from-slate-50 to-slate-100">
                    <tr>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        معرف المنشور
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        آخر تعليق
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        التعليقات
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        الردود
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        طريقة الرد
                      </th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-slate-600 uppercase tracking-wider">
                        الإجراءات
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white dark:bg-gray-800 divide-y divide-slate-100 dark:divide-gray-700">
                    {posts.length === 0 ? (
                      <tr>
                        <td colSpan="6" className="px-6 py-16 text-center">
                          <div className="flex flex-col items-center justify-center">
                            <div className="relative inline-block mb-6">
                              <div className="absolute inset-0 bg-blue-200 rounded-full blur-2xl opacity-20"></div>
                              <div className="relative bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 p-8 rounded-3xl border-2 border-dashed border-blue-200 dark:border-blue-700">
                                <MessageSquare className="w-24 h-24 text-blue-400" />
                              </div>
                            </div>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
                              لا يوجد منشورات
                            </h3>
                            <p className="text-slate-500 dark:text-gray-400 text-lg">
                              لم يتم العثور على أي منشورات حتى الآن
                            </p>
                          </div>
                        </td>
                      </tr>
                    ) : (
                      posts.map((post) => (
                        <tr
                          key={post.postId}
                          className="hover:bg-gradient-to-r hover:from-blue-50/50 hover:to-indigo-50/50 dark:hover:bg-gray-700/50 transition-all duration-300 border-l-4 border-transparent hover:border-blue-500"
                        >
                          <td className="px-6 py-4">
                            <div className="text-sm font-semibold text-slate-900 font-mono">
                              {post.postId.substring(0, 10)}...
                            </div>
                            <div className="text-xs text-slate-500 mt-1">
                              {new Date(
                                post.firstCommentTime,
                              ).toLocaleDateString("ar-EG")}
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            {post.latestComment ? (
                              <div>
                                <div className="text-sm font-medium text-slate-900">
                                  {post.latestComment.senderName}
                                </div>
                                <div
                                  className="text-xs text-slate-500 mt-1 max-w-xs truncate"
                                  title={post.latestComment.message}
                                >
                                  {post.latestComment.message}
                                </div>
                              </div>
                            ) : (
                              <div className="text-sm text-slate-500">
                                لا توجد تعليقات
                              </div>
                            )}
                          </td>
                          <td className="px-6 py-4">
                            <div className="flex items-center gap-2">
                              <span className="px-2 py-1 bg-blue-100 text-blue-800 text-xs font-bold rounded-full">
                                {post.totalComments}
                              </span>
                              <div className="flex gap-1">
                                <span className="px-2 py-1 bg-green-100 text-green-800 text-xs font-bold rounded-full flex items-center gap-1">
                                  <CheckCircle className="w-3 h-3" />
                                  {post.respondedComments}
                                </span>
                                <span className="px-2 py-1 bg-amber-100 text-amber-800 text-xs font-bold rounded-full flex items-center gap-1">
                                  <Clock className="w-3 h-3" />
                                  {post.pendingComments}
                                </span>
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <div className="w-full bg-gray-200 rounded-full h-2">
                              <div
                                className="bg-blue-600 h-2 rounded-full"
                                style={{ width: `${post.responseRate}%` }}
                              ></div>
                            </div>
                            <div className="text-xs text-slate-500 mt-1">
                              {post.responseRate}%
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <span
                              className={`px-3 py-1.5 inline-flex items-center gap-1 text-xs leading-5 font-bold rounded-full ${getResponseMethodColor(post.responseMethod)}`}
                            >
                              {getResponseMethodLabel(post.responseMethod)}
                            </span>
                          </td>
                          <td className="px-6 py-4">
                            <div className="flex gap-2 justify-end">
                              <button
                                onClick={() => handleViewComments(post.postId)}
                                className="group px-4 py-2 bg-gradient-to-r from-blue-600 to-blue-700 text-white text-sm font-semibold rounded-xl hover:from-blue-700 hover:to-blue-800 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105 flex items-center gap-2"
                              >
                                <MessageSquare className="w-4 h-4 group-hover:scale-110 transition-transform" />
                                عرض التعليقات
                              </button>
                              <button
                                onClick={() =>
                                  navigate(`/posts/${post.postId}/settings`)
                                }
                                className="group px-4 py-2 bg-gradient-to-r from-indigo-600 to-purple-600 text-white text-sm font-semibold rounded-xl hover:from-indigo-700 hover:to-purple-700 transition-all duration-300 shadow-md hover:shadow-lg hover:scale-105 flex items-center gap-2"
                              >
                                <Settings className="w-4 h-4 group-hover:rotate-90 transition-transform duration-300" />
                                إعدادات
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              {pagination.totalPages > 1 && (
                <div className="bg-gradient-to-r from-slate-50 to-slate-100 px-6 py-4 flex items-center justify-between border-t border-slate-200">
                  <div className="flex-1 flex justify-between sm:hidden">
                    <button
                      onClick={() =>
                        handlePageChange(pagination.currentPage - 1)
                      }
                      disabled={pagination.currentPage === 1}
                      className="relative inline-flex items-center px-4 py-2 border-2 border-slate-300 text-sm font-semibold rounded-xl text-slate-700 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                      السابق
                    </button>
                    <button
                      onClick={() =>
                        handlePageChange(pagination.currentPage + 1)
                      }
                      disabled={
                        pagination.currentPage === pagination.totalPages
                      }
                      className="mr-3 relative inline-flex items-center px-4 py-2 border-2 border-slate-300 text-sm font-semibold rounded-xl text-slate-700 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                      التالي
                    </button>
                  </div>
                  <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
                    <div>
                      <p className="text-sm text-slate-700 font-medium">
                        عرض{" "}
                        <span className="font-bold text-blue-600">
                          {(pagination.currentPage - 1) * filters.limit + 1}
                        </span>{" "}
                        إلى{" "}
                        <span className="font-bold text-blue-600">
                          {Math.min(
                            pagination.currentPage * filters.limit,
                            pagination.totalCount,
                          )}
                        </span>{" "}
                        من{" "}
                        <span className="font-bold text-blue-600">
                          {pagination.totalCount}
                        </span>{" "}
                        نتيجة
                      </p>
                    </div>
                    <div>
                      <nav
                        className="relative z-0 inline-flex rounded-xl shadow-sm gap-1"
                        aria-label="Pagination"
                      >
                        <button
                          onClick={() =>
                            handlePageChange(pagination.currentPage - 1)
                          }
                          disabled={pagination.currentPage === 1}
                          className="relative inline-flex items-center px-3 py-2 rounded-lg bg-white border-2 border-slate-300 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                        >
                          السابق
                        </button>
                        {[...Array(Math.min(pagination.totalPages, 7))].map(
                          (_, i) => {
                            let page;
                            if (pagination.totalPages <= 7) {
                              page = i + 1;
                            } else if (pagination.currentPage <= 4) {
                              page = i + 1;
                            } else if (
                              pagination.currentPage >=
                              pagination.totalPages - 3
                            ) {
                              page = pagination.totalPages - 6 + i;
                            } else {
                              page = pagination.currentPage - 3 + i;
                            }

                            return (
                              <button
                                key={page}
                                onClick={() => handlePageChange(page)}
                                className={`relative inline-flex items-center px-4 py-2 text-sm font-bold rounded-lg transition-all ${page === pagination.currentPage
                                    ? "bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg scale-105"
                                    : "bg-white border-2 border-slate-300 text-slate-700 hover:bg-slate-50"
                                  }`}
                              >
                                {page}
                              </button>
                            );
                          },
                        )}
                        <button
                          onClick={() =>
                            handlePageChange(pagination.currentPage + 1)
                          }
                          disabled={
                            pagination.currentPage === pagination.totalPages
                          }
                          className="relative inline-flex items-center px-3 py-2 rounded-lg bg-white border-2 border-slate-300 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                        >
                          التالي
                        </button>
                      </nav>
                    </div>
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default UnifiedCommentsManagement;

// Add custom CSS animations
const style = document.createElement("style");
style.textContent = `
  @keyframes fade-in {
    from {
      opacity: 0;
      transform: translateY(-10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes bounce-subtle {
    0%, 100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-2px);
    }
  }

  .animate-fade-in {
    animation: fade-in 0.5s ease-out;
  }

  .animate-bounce-subtle {
    animation: bounce-subtle 2s ease-in-out infinite;
  }
`;
document.head.appendChild(style);

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import CommentService from "../../services/commentService";
import {
  MessageSquare,
  CheckCircle,
  Clock,
  Search,
  RefreshCw,
  Settings,
  X,
  Save,
  TrendingUp,
  Filter,
  Grid3x3,
  List,
  ChevronRight,
  Layout,
} from "lucide-react";

const UnifiedCommentsSplit = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();

  // State
  const [pages, setPages] = useState([]);
  const [posts, setPosts] = useState([]);
  const [selectedPage, setSelectedPage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [loadingPages, setLoadingPages] = useState(true);

  // Filters
  const [filters, setFilters] = useState({
    search: "",
    status: "all",
  });

  // Fetch Pages on Mount
  useEffect(() => {
    fetchPages();
  }, []);

  // Fetch Posts when Page Selected
  useEffect(() => {
    if (selectedPage) {
      fetchPosts(selectedPage);
    } else {
      setPosts([]);
    }
  }, [selectedPage]);

  const fetchPages = async () => {
    setLoadingPages(true);
    try {
      const response = await CommentService.getFacebookPages();
      if (response.success && response.data) {
        setPages(response.data);
        // Auto-select first page if available
        if (response.data.length > 0 && !selectedPage) {
          setSelectedPage(response.data[0].pageId);
        }
      }
    } catch (error) {
      console.error("Error fetching pages:", error);
    } finally {
      setLoadingPages(false);
    }
  };

  const fetchPosts = async (pageId) => {
    setLoading(true);
    try {
      const response = await CommentService.getPostsByPageId(pageId);
      if (response.success) {
        setPosts(response.data);
      }
    } catch (error) {
      console.error("Error fetching posts:", error);
    } finally {
      setLoading(false);
    }
  };

  const getResponseMethodLabel = (method) => {
    switch (method) {
      case "ai":
        return t("unifiedComments.aiResponse");
      case "fixed":
        return t("unifiedComments.fixedResponse");
      case "manual":
        return t("unifiedComments.manualResponse");
      default:
        return t("unifiedComments.notSpecified");
    }
  };

  const getResponseMethodColor = (method) => {
    switch (method) {
      case "ai":
        return "bg-blue-100 text-blue-800";
      case "fixed":
        return "bg-green-100 text-green-800";
      case "manual":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  // Filter posts locally for now (since API might not support all filters on this endpoint yet, or to be snappy)
  const filteredPosts = posts.filter((post) => {
    const matchesSearch =
      filters.search === "" ||
      post.postId.includes(filters.search) ||
      (post.message && post.message.includes(filters.search));
    const matchesStatus =
      filters.status === "all" ||
      (filters.status === "responded" && post.pendingComments === 0) ||
      (filters.status === "pending" && post.pendingComments > 0);
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="h-[calc(100vh-64px)] overflow-hidden bg-gray-50 dark:bg-gray-900 flex flex-col">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 p-4 flex-shrink-0">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg text-white shadow-lg">
              <Layout className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-gray-900 dark:text-white">
                إدارة المنشورات الموحدة
              </h1>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                عرض مقسم للصفحات والمنشورات
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {/* Global Filters could go here */}
          </div>
        </div>
      </div>

      {/* Main Split View */}
      <div className="flex-1 flex overflow-hidden">
        {/* Left Column: Pages List */}
        <div className="w-1/4 min-w-[300px] border-l border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 overflow-y-auto flex flex-col">
          <div className="p-4 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/50 flex-shrink-0">
            <h2 className="font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
              <List className="w-5 h-5" />
              الصفحات ({pages.length})
            </h2>
          </div>

          <div className="flex-1 overflow-y-auto p-3 space-y-3">
            {loadingPages ? (
              <div className="text-center py-10">
                <div className="inline-block animate-spin rounded-full h-8 w-8 border-4 border-blue-500 border-t-transparent"></div>
              </div>
            ) : (
              pages.map((page) => (
                <div
                  key={page.pageId}
                  onClick={() => setSelectedPage(page.pageId)}
                  className={`p-4 rounded-xl cursor-pointer transition-all duration-200 border border-transparent ${
                    selectedPage === page.pageId
                      ? "bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 shadow-sm"
                      : "hover:bg-gray-50 dark:hover:bg-gray-700/50"
                  }`}
                >
                  <div className="flex items-center justify-between mb-2">
                    <span
                      className="font-bold text-gray-900 dark:text-white truncate"
                      title={page.pageName}
                    >
                      {page.pageName}
                    </span>
                    {selectedPage === page.pageId && (
                      <ChevronRight className="w-5 h-5 text-blue-500" />
                    )}
                  </div>
                  <div className="flex gap-2 text-xs text-gray-500 dark:text-gray-400">
                    <span className="flex items-center gap-1">
                      <Grid3x3 className="w-3 h-3" /> {page.totalPosts}
                    </span>
                    <span className="flex items-center gap-1">
                      <MessageSquare className="w-3 h-3" /> {page.totalComments}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Right Column: Posts List */}
        <div className="flex-1 bg-gray-50 dark:bg-gray-900 flex flex-col min-w-0">
          {/* Posts Toolbar */}
          <div className="p-4 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 flex flex-wrap items-center gap-4 flex-shrink-0 shadow-sm z-10">
            <div className="flex-1 relative min-w-[200px]">
              <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="بحث في المنشورات..."
                className="w-full pr-9 pl-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-gray-50 dark:bg-gray-700 dark:text-white transition-all"
                value={filters.search}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, search: e.target.value }))
                }
              />
            </div>

            <select
              className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm bg-gray-50 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-blue-500"
              value={filters.status}
              onChange={(e) =>
                setFilters((prev) => ({ ...prev, status: e.target.value }))
              }
            >
              <option value="all">كل الحالات</option>
              <option value="pending">⏳ قيد الانتظار</option>
              <option value="responded">✅ تم الرد</option>
            </select>

            <button
              onClick={() => selectedPage && fetchPosts(selectedPage)}
              className="p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="تحديث"
            >
              <RefreshCw
                className={`w-5 h-5 ${loading ? "animate-spin" : ""}`}
              />
            </button>
          </div>

          {/* Posts Grid/List */}
          <div className="flex-1 overflow-y-auto p-4 md:p-6">
            {loading ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-500">
                <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent mb-4"></div>
                <p>جاري تحميل المنشورات...</p>
              </div>
            ) : filteredPosts.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-500">
                <div className="p-6 bg-gray-100 dark:bg-gray-800 rounded-full mb-4">
                  <MessageSquare className="w-12 h-12 text-gray-400" />
                </div>
                {selectedPage ? (
                  <p className="text-lg font-medium">لا توجد منشورات مطابقة</p>
                ) : (
                  <p className="text-lg font-medium">
                    الرجاء اختيار صفحة لعرض المنشورات
                  </p>
                )}
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                {filteredPosts.map((post, index) => (
                  <div
                    key={post.postId}
                    className="bg-white dark:bg-gray-800 rounded-xl shadow-sm hover:shadow-md border border-gray-200 dark:border-gray-700 overflow-hidden flex flex-col md:flex-row transition-all duration-200 hover:border-blue-400 group animate-fade-in"
                    style={{ animationDelay: `${index * 0.05}s` }}
                  >
                    {/* Post Image (Left side in list view) */}
                    <div className="md:w-32 md:h-32 relative bg-gray-100 dark:bg-gray-700 flex-shrink-0">
                      {post.pictureUrl ? (
                        <img
                          src={post.pictureUrl}
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <MessageSquare className="w-6 h-6 text-gray-400" />
                        </div>
                      )}
                      <div className="absolute top-1 right-1 md:left-1 md:right-auto">
                        <span
                          className={`px-1.5 py-0.5 text-[10px] font-bold rounded shadow-sm ${getResponseMethodColor(post.responseMethod)}`}
                        >
                          {getResponseMethodLabel(post.responseMethod)}
                        </span>
                      </div>
                    </div>

                    {/* Content (Middle) */}
                    <div className="p-3 flex-1 flex flex-col min-w-0 justify-between">
                      <div>
                        <div className="flex items-start justify-between mb-1">
                          <span
                            className="text-[10px] text-gray-500 font-mono"
                            title={post.postId}
                          >
                            #{post.postId.substring(post.postId.length - 8)}
                          </span>
                          <span className="text-[10px] text-gray-500">
                            {new Date(post.firstCommentTime).toLocaleDateString(
                              "ar-EG",
                            )}
                          </span>
                        </div>

                        <p
                          className="text-xs font-medium text-gray-800 dark:text-gray-200 line-clamp-2 mb-2"
                          title={post.message}
                        >
                          {post.message || "لا يوجد نص"}
                        </p>
                      </div>

                      {/* Stats Bar - Compact */}
                      <div className="flex items-center gap-3 text-xs text-gray-500 dark:text-gray-400">
                        <div className="flex items-center gap-1">
                          <MessageSquare className="w-3 h-3 text-blue-500" />
                          <span className="font-bold text-gray-700 dark:text-gray-300">
                            {post.totalComments}
                          </span>
                        </div>
                        <div className="flex items-center gap-1">
                          <span className="w-1.5 h-1.5 rounded-full bg-amber-500"></span>
                          <span>
                            منتظر:{" "}
                            <span className="font-bold text-gray-700 dark:text-gray-300">
                              {post.pendingComments}
                            </span>
                          </span>
                        </div>
                        <div className="flex items-center gap-1">
                          <span className="w-1.5 h-1.5 rounded-full bg-purple-500"></span>
                          <span>
                            الرد:{" "}
                            <span className="font-bold text-gray-700 dark:text-gray-300">
                              {post.responseRate}%
                            </span>
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Actions (Right side or Bottom) */}
                    <div className="p-2 bg-gray-50 dark:bg-gray-900/50 border-t md:border-t-0 md:border-r border-gray-100 dark:border-gray-700 flex md:flex-col justify-center gap-2 md:w-32 flex-shrink-0">
                      <button
                        onClick={() =>
                          navigate(`/posts/${post.postId}/comments`)
                        }
                        className="flex-1 md:flex-none bg-blue-600 hover:bg-blue-700 text-white text-xs py-1.5 px-3 rounded-lg font-medium transition-colors flex items-center justify-center gap-1"
                      >
                        <MessageSquare className="w-3 h-3" />
                        التعليقات
                      </button>
                      <button
                        onClick={() =>
                          navigate(`/posts/${post.postId}/settings`)
                        }
                        className="flex-1 md:flex-none py-1.5 px-3 text-gray-600 hover:text-blue-600 hover:bg-white rounded-lg transition-colors border border-gray-200 hover:border-blue-200 flex items-center justify-center gap-1 text-xs"
                      >
                        <Settings className="w-3 h-3" />
                        الإعدادات
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default UnifiedCommentsSplit;

import React, { useState, useEffect, useMemo } from 'react';
import {
  CalculatorIcon,
  ArrowTrendingUpIcon,
  ArrowTrendingDownIcon,
  UsersIcon,
  ClockIcon
} from '@heroicons/react/24/outline';
import {
  DollarSign as DollarSignIcon,
  Target as TargetIcon,
  BarChart3 as BarChart3Icon,
  RefreshCw as RefreshCwIcon,
  Download as DownloadIcon,
  AlertTriangle as AlertTriangleIcon
} from 'lucide-react';
import { useAuth } from '../../hooks/useAuthSimple';
import LineChart from '../../components/charts/LineChart';
import BarChart from '../../components/charts/BarChart';
import PieChart from '../../components/charts/PieChart';
import { buildApiUrl } from '../../utils/urlHelper';

interface PredictionParams {
  messagesCount: number;
  savedRate: number;
  conversionRate: number;
  avgRevenuePerConversation: number;
  campaignCost: number;
  peakHour: number;
  bestDay: number;
}

interface PredictionResult {
  predictedSaved: number;
  predictedIgnored: number;
  predictedConversations: number;
  predictedRevenue: number;
  predictedOrders: number;
  roi: number;
  breakEven: number;
  profit: number;
  costPerMessage: number;
  costPerConversion: number;
  scenarios: ScenarioResult[];
}

interface ScenarioResult {
  name: string;
  description: string;
  savedRate: number;
  conversionRate: number;
  revenue: number;
  roi: number;
  profit: number;
}

interface HistoricalStats {
  averageSavedRate: number;
  averageConversionRate: number;
  averageRevenuePerConversation: number;
  peakHour: number;
  bestDay: number;
  dailyTrend: Array<{
    date: string;
    savedRate: number;
    conversionRate: number;
    revenue: number;
  }>;
  hourlyPattern: Array<{
    hour: number;
    savedRate: number;
    conversionRate: number;
  }>;
}

const CampaignResultsPredictor: React.FC = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [historicalStats, setHistoricalStats] = useState<HistoricalStats | null>(null);
  const [prediction, setPrediction] = useState<PredictionResult | null>(null);
  const [params, setParams] = useState<PredictionParams>({
    messagesCount: 1000,
    savedRate: 35,
    conversionRate: 12,
    avgRevenuePerConversation: 85,
    campaignCost: 500,
    peakHour: 20,
    bestDay: 5
  });

  const fetchHistoricalStats = async () => {
    setLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem('accessToken');
      const headers: HeadersInit = {
        'Content-Type': 'application/json',
      };
      if (token) {
        headers['Authorization'] = `Bearer ${token}`;
      }

      const response = await fetch(
        buildApiUrl('conversations/stats/historical-prediction-data'),
        { headers }
      );

      if (!response.ok) {
        throw new Error('فشل في جلب البيانات التاريخية');
      }

      const data = await response.json();
      if (data.success) {
        setHistoricalStats(data.data);
        // Initialize parameters with historical averages
        setParams(prev => ({
          ...prev,
          savedRate: data.data.averageSavedRate,
          conversionRate: data.data.averageConversionRate,
          avgRevenuePerConversation: data.data.averageRevenuePerConversation,
          peakHour: data.data.peakHour,
          bestDay: data.data.bestDay
        }));
      } else {
        throw new Error(data.error || 'فشل في جلب البيانات');
      }
    } catch (err: any) {
      console.error('Error fetching historical stats:', err);
      setError(err.message || 'حدث خطأ أثناء جلب البيانات التاريخية');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHistoricalStats();
  }, []);

  const calculatePrediction = () => {
    // Calculate basic predictions
    const predictedSaved = Math.round(params.messagesCount * (params.savedRate / 100));
    const predictedIgnored = params.messagesCount - predictedSaved;
    const predictedConversations = Math.round(predictedSaved * (params.conversionRate / 100));
    const predictedRevenue = predictedConversations * params.avgRevenuePerConversation;
    const predictedOrders = Math.round(predictedConversations * 0.8); // Assumed 80% conversion to order

    // Calculate financial metrics
    const roi = ((predictedRevenue - params.campaignCost) / params.campaignCost) * 100;
    const breakEven = Math.ceil((params.campaignCost / (params.avgRevenuePerConversation * (params.savedRate / 100) * (params.conversionRate / 100))));
    const profit = predictedRevenue - params.campaignCost;
    const costPerMessage = params.campaignCost / params.messagesCount;
    const costPerConversion = params.campaignCost / predictedConversations;

    // Generate scenarios
    const scenarios: ScenarioResult[] = [
      {
        name: 'سيناريو متشائم',
        description: 'نموذج أسوأ الحالات (نسبة محفظة thấp)',
        savedRate: Math.max(0, params.savedRate - 10),
        conversionRate: Math.max(0, params.conversionRate - 5),
        revenue: 0,
        roi: 0,
        profit: 0
      },
      {
        name: 'سيناريو متوقع',
        description: 'المتوقع بناءً على البيانات التاريخية',
        savedRate: params.savedRate,
        conversionRate: params.conversionRate,
        revenue: 0,
        roi: 0,
        profit: 0
      },
      {
        name: 'سيناريو مثالي',
        description: 'أفضل الحالات (زيادة 20% في معدل التحويل)',
        savedRate: Math.min(100, params.savedRate + 10),
        conversionRate: Math.min(100, params.conversionRate + 5),
        revenue: 0,
        roi: 0,
        profit: 0
      }
    ];

    // Calculate scenario details
    scenarios.forEach(scenario => {
      const scenarioSaved = Math.round(params.messagesCount * (scenario.savedRate / 100));
      const scenarioConversations = Math.round(scenarioSaved * (scenario.conversionRate / 100));
      scenario.revenue = scenarioConversations * params.avgRevenuePerConversation;
      scenario.roi = ((scenario.revenue - params.campaignCost) / params.campaignCost) * 100;
      scenario.profit = scenario.revenue - params.campaignCost;
    });

    setPrediction({
      predictedSaved,
      predictedIgnored,
      predictedConversations,
      predictedRevenue,
      predictedOrders,
      roi,
      breakEven,
      profit,
      costPerMessage,
      costPerConversion,
      scenarios
    });
  };

  useEffect(() => {
    if (historicalStats) {
      calculatePrediction();
    }
  }, [params]);

  const handleParamChange = (key: keyof PredictionParams, value: number) => {
    setParams(prev => ({
      ...prev,
      [key]: value
    }));
  };

  const handleResetToHistorical = () => {
    if (historicalStats) {
      setParams(prev => ({
        ...prev,
        savedRate: historicalStats.averageSavedRate,
        conversionRate: historicalStats.averageConversionRate,
        avgRevenuePerConversation: historicalStats.averageRevenuePerConversation,
        peakHour: historicalStats.peakHour,
        bestDay: historicalStats.bestDay
      }));
    }
  };

  const exportReport = () => {
    if (!prediction) return;

    const report = {
      prediction,
      parameters: params,
      generatedAt: new Date().toLocaleString('ar-EG')
    };

    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `campaign-prediction-report-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const days = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 p-4 md:p-6 lg:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-2 flex items-center gap-3">
                <CalculatorIcon className="w-10 h-10 text-blue-600" />
                حاسبة توقعات نتائج حملات الرسائل
              </h1>
              <p className="text-gray-600 dark:text-gray-400">
                أداة متقدمة لتوقعات أداء حملات الرسائل بناءً على البيانات التاريخية والتجارب السابقة
              </p>
            </div>
            <div className="flex gap-3">
              <button
                onClick={handleResetToHistorical}
                disabled={!historicalStats}
                className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
              >
                <RefreshCwIcon className="w-5 h-5" />
                إعادة تعيين إلى المتوسط التاريخي
              </button>
              {prediction && (
                <button
                  onClick={exportReport}
                  className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors flex items-center gap-2"
                >
                  <DownloadIcon className="w-5 h-5" />
                  تصدير التقرير
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Loading State */}
        {loading && (
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-12 text-center">
            <RefreshCwIcon className="h-12 w-12 animate-spin text-blue-600 mx-auto mb-4" />
            <p className="text-gray-600 dark:text-gray-400 text-lg">جاري تحميل البيانات التاريخية...</p>
          </div>
        )}

        {/* Error State */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-4 mb-6 flex items-center gap-3">
            <AlertTriangleIcon className="h-6 w-6 text-red-600 dark:text-red-400" />
            <div>
              <p className="text-red-800 dark:text-red-200 font-medium">{error}</p>
              <button
                onClick={fetchHistoricalStats}
                className="text-sm text-red-600 dark:text-red-400 underline mt-1"
              >
                إعادة المحاولة
              </button>
            </div>
          </div>
        )}

        {/* Main Content */}
        {!loading && historicalStats && (
          <div className="space-y-6">
            {/* Parameters Section */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6">
              <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
                <TargetIcon className="w-6 h-6 text-blue-600" />
                المتغيرات الأساسية
              </h2>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Basic Parameters */}
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      عدد الرسائل المرسلة
                    </label>
                    <input
                      type="number"
                      value={params.messagesCount}
                      onChange={(e) => handleParamChange('messagesCount', parseInt(e.target.value) || 0)}
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                      min="0"
                      step="100"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      تكلفة الحملة (ج.م)
                    </label>
                    <input
                      type="number"
                      value={params.campaignCost}
                      onChange={(e) => handleParamChange('campaignCost', parseInt(e.target.value) || 0)}
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                      min="0"
                      step="100"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      متوسط الإيراد لكل محادثة (ج.م)
                    </label>
                    <input
                      type="number"
                      value={params.avgRevenuePerConversation}
                      onChange={(e) => handleParamChange('avgRevenuePerConversation', parseFloat(e.target.value) || 0)}
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                      min="0"
                      step="10"
                    />
                  </div>
                </div>

                {/* Performance Parameters */}
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      نسبة الحفظ (%) - المتوسط التاريخي: {historicalStats.averageSavedRate}%
                    </label>
                    <input
                      type="range"
                      value={params.savedRate}
                      onChange={(e) => handleParamChange('savedRate', parseInt(e.target.value) || 0)}
                      className="w-full"
                      min="0"
                      max="100"
                      step="1"
                    />
                    <div className="flex justify-between text-sm text-gray-500 mt-1">
                      <span>0%</span>
                      <span>{params.savedRate}%</span>
                      <span>100%</span>
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      معدل التحويل (%) - المتوسط التاريخي: {historicalStats.averageConversionRate}%
                    </label>
                    <input
                      type="range"
                      value={params.conversionRate}
                      onChange={(e) => handleParamChange('conversionRate', parseInt(e.target.value) || 0)}
                      className="w-full"
                      min="0"
                      max="100"
                      step="1"
                    />
                    <div className="flex justify-between text-sm text-gray-500 mt-1">
                      <span>0%</span>
                      <span>{params.conversionRate}%</span>
                      <span>100%</span>
                    </div>
                  </div>

                  {/* Optimal Timing */}
                  <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-4 border border-blue-200 dark:border-blue-800">
                    <h3 className="text-sm font-medium text-blue-800 dark:text-blue-200 mb-3">الوقت الأمثل للإرسال</h3>
                    <div className="space-y-2">
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-700 dark:text-gray-300">أفضل ساعة:</span>
                        <span className="text-sm font-semibold text-blue-600 dark:text-blue-400">{params.peakHour}:00</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-700 dark:text-gray-300">أفضل يوم:</span>
                        <span className="text-sm font-semibold text-blue-600 dark:text-blue-400">{days[params.bestDay]}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Results Section */}
            {prediction && (
              <>
                {/* Key Metrics */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
                  <div className="bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl shadow-lg p-6 text-white transform hover:scale-105 transition-transform">
                    <div className="flex items-center justify-between mb-4">
                      <UsersIcon className="h-12 w-12 opacity-80" />
                      <div className="bg-white/20 rounded-full p-2">
                        <ArrowTrendingUpIcon className="h-6 w-6" />
                      </div>
                    </div>
                    <p className="text-sm opacity-90 mb-1">الرسائل المحفوظة المتوقعة</p>
                    <p className="text-4xl font-bold">
                      {prediction.predictedSaved.toLocaleString('ar-EG')}
                    </p>
                    <p className="text-sm opacity-90 mt-1">
                      {params.savedRate}% من إجمالي الرسائل
                    </p>
                  </div>

