interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type: "text" | "image" | "file";
  isFromCustomer: boolean;
  status: "sent" | "delivered" | "read";
  isAutoGenerated?: boolean;
  provider?: string;
  metadata?: any;
}

interface Conversation {
  id: string;
  customerName: string;
  customerAvatar?: string;
  lastMessage: string;
  lastMessageTime: Date;
  unreadCount: number;
  isOnline: boolean;
  platform: "facebook" | "whatsapp" | "telegram";
  messages: Message[];
  pageName?: string; // اسم صفحة الفيسبوك
  pageId?: string; // معرف صفحة الفيسبوك
}

const Conversations: React.FC = () => {
  const { formatDate } = useDateFormat();
  // const { user } = useAuth(); // 'user' is declared but its value is never read.
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [newMessage, setNewMessage] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [isAutoUpdating, setIsAutoUpdating] = useState(false);
  const [isUserTyping, setIsUserTyping] = useState(false);
  const [lastUpdateTime, setLastUpdateTime] = useState(0);
  const [hasNewMessages, setHasNewMessages] = useState(false);
  const [showScrollButton, setShowScrollButton] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const isConnected = false;

  // تحميل المحادثات من API
  const loadConversations = async (showAutoUpdateIndicator = false) => {
    try {
      // تجنب التحديث المتكرر - على الأقل ثانيتين بين التحديثات
      const now = Date.now();
      if (showAutoUpdateIndicator && now - lastUpdateTime < 2000) {
        return;
      }

      if (showAutoUpdateIndicator) {
        setIsAutoUpdating(true);
        setLastUpdateTime(now);
      } else {
        setLoading(true);
      }

      const response = await fetch(buildApiUrl("conversations"));
      const data = await response.json();

      if (data.success) {
        console.log("✅ Conversations loaded successfully:", data.data.length);

        // تحويل البيانات للتنسيق المطلوب
        const formattedConversations = data.data.map((conv: any) => ({
          id: conv.id,
          customerName: conv.customerName || "عميل غير معروف", // Fix: Use customerName instead of customerId
          lastMessage: conv.lastMessage || "لا توجد رسائل",
          lastMessageTime: new Date(conv.lastMessageTime || Date.now()),
          unreadCount: conv.unreadCount || 0,
          platform: conv.platform || "unknown",
          isOnline: false,
          messages: [],
          pageName: conv.pageName || null, // إضافة اسم الصفحة
          pageId: conv.pageId || null, // إضافة معرف الصفحة
        }));

        setConversations(formattedConversations);
      }
    } catch (error) {
      console.error("Error loading conversations:", error);
    } finally {
      setLoading(false);
      setIsAutoUpdating(false);
    }
  };

  // تحميل رسائل محادثة معينة
  const loadMessages = async (conversationId: string, silent = false) => {
    try {
      const response = await fetch(
        buildApiUrl(`conversations/${conversationId}/messages`),
      );
      const data = await response.json();

      if (data.success) {
        // تحديث ذكي للرسائل - فقط عند وجود تغييرات
        const currentMessages = selectedConversation?.messages || [];
        const hasNewMessages =
          currentMessages.length !== data.data.length ||
          data.data.some(
            (msg: any, index: number) =>
              !currentMessages[index] || currentMessages[index].id !== msg.id,
          );

        if (hasNewMessages) {
          console.log("📨 Updating messages - new messages detected");

          // تحديث المحادثة المحددة بالرسائل
          setConversations((prev: Conversation[]) =>
            prev.map((conv: Conversation) =>
              conv.id === conversationId
                ? { ...conv, messages: data.data }
                : conv,
            ),
          );

          // تحديث المحادثة المختارة
          if (selectedConversation?.id === conversationId) {
            setSelectedConversation((prev: Conversation | null) =>
              prev ? { ...prev, messages: data.data } : null,
            );

            // إزالة التمرير التلقائي المزعج
            // if (!silent) {
            //   setTimeout(scrollToBottom, 100);
            // }
          }

          // إشعار صوتي ومرئي للرسائل الجديدة (فقط إذا كانت من العميل)
          if (silent && data.data.length > currentMessages.length) {
            const newMessage = data.data[data.data.length - 1];
            if (newMessage?.isFromCustomer) {
              console.log(
                "🔔 New customer message - playing notification sound",
              );

              // تحديث مؤشر الرسائل الجديدة
              setHasNewMessages(true);

              // تحديث عنوان الصفحة
              document.title = "🔔 رسالة جديدة - منصة التواصل";

              // تشغيل صوت إشعار بسيط
              try {
                const audio = new Audio(
                  "data:audio/wav;base64,UklGRnoGAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQoGAACBhYqFbF1fdJivrJBhNjVgodDbq2EcBj+a2/LDciUFLIHO8tiJNwgZaLvt559NEAxQp+PwtmMcBjiR1/LMeSwFJHfH8N2QQAoUXrTp66hVFApGn+DyvmwhBSuBzvLZiTYIG2m98OScTgwOUarm7blmGgU7k9n1unEiBC13yO/eizEIHWq+8+OWT",
                );
                audio.volume = 0.3;
                audio
                  .play()
                  .catch((e) =>
                    console.log("Could not play notification sound:", e),
                  );
              } catch (e) {
                console.log("Notification sound not available");
              }
            }
          }
        } else if (!silent) {
          console.log("✅ No new messages - skipping update");
        }
      }
    } catch (error) {
      console.error("Error loading messages:", error);
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  // مراقبة التمرير لإظهار/إخفاء زر التمرير
  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const container = e.currentTarget;
    const isNearBottom =
      container.scrollHeight - container.scrollTop - container.clientHeight <
      100;
    setShowScrollButton(!isNearBottom);
  };

  // تتبع حالة الكتابة المحسن
  const handleTypingStart = () => {
    if (!isUserTyping) {
      console.log("🖊️ User started typing - pausing auto-update");
      setIsUserTyping(true);
    }

    // إلغاء المؤقت السابق
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }

    // إعداد مؤقت جديد لإيقاف حالة الكتابة بعد ثانيتين من عدم الكتابة
    typingTimeoutRef.current = setTimeout(() => {
      console.log("✅ User stopped typing - resuming auto-update");
      setIsUserTyping(false);
    }, 2000); // تقليل الوقت إلى ثانيتين
  };

  useEffect(() => {
    loadConversations();
  }, []);

  // Socket.IO event listeners للتحديث الفوري
  useEffect(() => {
    // Connect to socket if not already connected
    if (!socketService.isConnected()) {
      socketService.connect();
    }

    // Listen for new messages
    const handleNewMessage = (message: any) => {
      console.log("🔌 [SOCKET] New message received:", message);

      // Update messages in selected conversation
      if (selectedConversation?.id === message.conversationId) {
        setSelectedConversation((prev: Conversation | null) => {
          if (!prev) return null;
          return {
            ...prev,
            messages: [...prev.messages, message],
          };
        });
      }

      // Update conversation list with latest message
      setConversations((prev: Conversation[]) => {
        return prev.map((conv: Conversation) => {
          if (conv.id === message.conversationId) {
            return {
              ...conv,
              lastMessage: message.content,
              lastMessageTime: new Date(message.timestamp),
              unreadCount: conv.unreadCount + (message.isFromCustomer ? 1 : 0),
            };
          }
          return conv;
        });
      });
    };

    // Listen for new conversations
    const handleNewConversation = (conversation: any) => {
      console.log("🔌 [SOCKET] New conversation received:", conversation);

      // Add new conversation to the top of the list
      setConversations((prev: Conversation[]) => {
        // Check if conversation already exists
        const exists = prev.some(
          (conv: Conversation) => conv.id === conversation.id,
        );
        if (exists) {
          // Update existing conversation
          return prev.map((conv: Conversation) =>
            conv.id === conversation.id ? { ...conv, ...conversation } : conv,
          );
        } else {
          // Add new conversation to the beginning of the list
          return [conversation, ...prev];
        }
      });
    };

    // Listen for conversation updates
    const handleConversationUpdated = (conversation: any) => {
      console.log("🔌 [SOCKET] Conversation updated:", conversation);

      // Update conversation in the list
      setConversations((prev: Conversation[]) => {
        return prev.map((conv: Conversation) =>
          conv.id === conversation.id ? { ...conv, ...conversation } : conv,
        );
      });
    };

    // Register event listeners
    socketService.onMessage(handleNewMessage);
    socketService.onConversationUpdated(handleConversationUpdated);
    socketService.onNewConversation(handleNewConversation); // Add this line

    // Cleanup function
    return () => {
      socketService.off("message:new", handleNewMessage);
      socketService.off("conversation:updated", handleConversationUpdated);
      socketService.off("conversation:new", handleNewConversation);
    };
  }, [selectedConversation]);

  // useEffect للتحديث التلقائي الذكي والسريع
  useEffect(() => {
    console.log("🔄 Setting up smart real-time update system");

    // تحديث أبطأ كل 10 ثوان للمحادثات
    const conversationsInterval = setInterval(() => {
      if (!isUserTyping) {
        console.log("🔄 Smart auto-updating conversations...");
        loadConversations(true);
      } else {
        console.log("⏸️ Skipping conversations auto-update: user is typing");
      }
    }, 10000); // كل 10 ثوان للمحادثات

    return () => {
      clearInterval(conversationsInterval);
    };
  }, [isUserTyping]); // مع dependency صحيحة

  // تحديث منفصل للرسائل
  useEffect(() => {
    if (!selectedConversation) return;

    console.log(
      "🔄 Setting up messages auto-update for conversation:",
      selectedConversation.id,
    );

    // تحديث سريع كل 5 ثوان للرسائل الجديدة
    const messagesInterval = setInterval(() => {
      if (!isUserTyping) {
        console.log("🔄 Smart auto-updating messages...");
        loadMessages(selectedConversation.id, true);
      } else {
        console.log("⏸️ Skipping messages auto-update: user is typing");
      }
    }, 5000); // كل 5 ثوان للرسائل

    return () => {
      clearInterval(messagesInterval);
    };
  }, [selectedConversation?.id, isUserTyping]); // مع dependencies صحيحة

  // تنظيف timeout الكتابة
  useEffect(() => {
    return () => {
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (
      selectedConversation &&
      (!selectedConversation.messages ||
        selectedConversation.messages.length === 0)
    ) {
      loadMessages(selectedConversation.id);
    }
  }, [selectedConversation]);

  // إزالة التمرير التلقائي المزعج - دع المستخدم يتحكم في التمرير
  // useEffect(() => {
  //   scrollToBottom();
  // }, [selectedConversation?.messages]);

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;

    const messageContent = newMessage;
    setNewMessage(""); // مسح الرسالة فوراً

    console.log("📤 Attempting to send message:", messageContent);
    console.log("📤 To conversation:", selectedConversation.id);

    try {
      // 🔧 FIX: استخدم endpoint الصحيح
      const url = buildApiUrl(
        `conversations/${selectedConversation.id}/messages`,
      );
      console.log("📤 Sending POST to:", url);

      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          message: messageContent,
        }),
      });

      console.log("📤 Response status:", response.status);
      console.log("📤 Response ok:", response.ok);

      const data = await response.json();
      console.log("📤 Response data:", data);

      if (data.success) {
        console.log("✅ Message sent successfully");

        // إرسال إشعار عبر Socket.IO للتحديث الفوري (معطل مؤقتاً)
        // Socket.IO معطل للاختبار
        console.log("📡 Socket.IO disabled - message sent via HTTP only");

        // إعادة تحميل الرسائل لإظهار الرسالة الجديدة
        console.log("🔄 Reloading messages to show new message...");
        await loadMessages(selectedConversation.id, true);

        // التمرير لأسفل فقط عند إرسال رسالة جديدة
        setTimeout(scrollToBottom, 300);

        // تحديث آخر رسالة في قائمة المحادثات
        setConversations((prev: Conversation[]) =>
          prev.map((conv: Conversation) =>
            conv.id === selectedConversation.id
              ? {
                  ...conv,
                  lastMessage: messageContent,
                  lastMessageTime: new Date(),
                }
              : conv,
          ),
        );

        console.log("✅ Message handling completed");
      } else {
        console.error("❌ Server returned error:", data.message);
        alert("فشل في إرسال الرسالة: " + data.message);
        setNewMessage(messageContent); // إرجاع الرسالة في حالة الفشل
      }
    } catch (error) {
      console.error("❌ Error sending message:", error);
      alert("حدث خطأ أثناء إرسال الرسالة");
      setNewMessage(messageContent); // إرجاع الرسالة في حالة الفشل
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const formatTime = (date: Date | string) => {
    const now = new Date();
    const dateObj = typeof date === "string" ? new Date(date) : date;

    // التحقق من صحة التاريخ
    if (isNaN(dateObj.getTime())) {
      return "غير محدد";
    }

    const diff = now.getTime() - dateObj.getTime();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (minutes < 1) return "الآن";
    if (minutes < 60) return `منذ ${minutes} دقيقة`;
    if (hours < 24) return `منذ ${hours} ساعة`;
    if (days < 7) return `منذ ${days} يوم`;
    return formatDate(dateObj);
  };

  const getPlatformIcon = (platform: string) => {
    switch (platform) {
      case "facebook":
        return (
          <div className="w-6 h-6 bg-blue-600 rounded-full flex items-center justify-center shadow-lg">
            <span className="text-white text-xs font-bold">f</span>
          </div>
        );
      case "whatsapp":
        return (
          <div className="w-6 h-6 bg-green-500 rounded-full flex items-center justify-center shadow-lg">
            <span className="text-white text-xs">💬</span>
          </div>
        );
      case "telegram":
        return (
          <div className="w-6 h-6 bg-blue-500 rounded-full flex items-center justify-center shadow-lg">
            <span className="text-white text-xs">✈️</span>
          </div>
        );
      default:
        return (
          <div className="w-6 h-6 bg-gray-500 rounded-full flex items-center justify-center shadow-lg">
            <span className="text-white text-xs">💬</span>
          </div>
        );
    }
  };

  // تحديد المحادثة كمقروءة
  const markAsRead = async (conversationId: string) => {
    try {
      const response = await fetch(
        buildApiUrl(`conversations/${conversationId}/read`),
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
        },
      );

      const data = await response.json();

      if (data.success) {
        // تحديث عداد الرسائل غير المقروءة
        setConversations((prev) =>
          prev.map((conv) =>
            conv.id === conversationId ? { ...conv, unreadCount: 0 } : conv,
          ),
        );
      }
    } catch (error) {
      console.error("Error marking conversation as read:", error);
    }
  };

  // معالجة اختيار محادثة
  const handleSelectConversation = (conversation: Conversation) => {
    // تجنب إعادة التحديد للمحادثة نفسها
    if (selectedConversation?.id === conversation.id) {
      return;
    }

    console.log("📱 Selecting conversation:", conversation.id);
    setSelectedConversation(conversation);

    // إزالة مؤشر الرسائل الجديدة
    setHasNewMessages(false);
    document.title = "منصة التواصل";

    // تحميل رسائل المحادثة الجديدة
    loadMessages(conversation.id);

    if (conversation.unreadCount > 0) {
      markAsRead(conversation.id);
    }
  };

  // التحديث اليدوي
  const handleManualRefresh = () => {
    console.log("🔄 Manual refresh triggered");
    loadConversations(true);
    if (selectedConversation) {
      loadMessages(selectedConversation.id);
    }
  };

  const filteredConversations = conversations.filter(
    (conv) =>
      conv.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      conv.lastMessage.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-gradient-to-br from-indigo-50 via-white to-purple-50">
        <div className="text-center">
          <div className="relative">
            <div className="animate-spin rounded-full h-16 w-16 border-4 border-transparent bg-gradient-to-r from-indigo-500 to-purple-500 mx-auto"></div>
            <div className="absolute inset-0 animate-spin rounded-full h-16 w-16 border-4 border-transparent border-t-white mx-auto"></div>
          </div>
          <div className="mt-6 space-y-2">
            <p className="text-lg font-semibold bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">
              جاري تحميل المحادثات
            </p>
            <p className="text-sm text-gray-500">يرجى الانتظار قليلاً...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 min-h-full">
      {/* Conversations Sidebar */}
      <div className="w-1/3 bg-white/80 backdrop-blur-sm border-r border-gray-200/50 flex flex-col shadow-xl">
        {/* Header */}
        <div className="flex-shrink-0 p-6 border-b border-gray-200/50 bg-gradient-to-r from-indigo-500 to-purple-600">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-3 space-x-reverse">
              <div className="p-2 bg-white/20 rounded-lg backdrop-blur-sm">
                <ChatBubbleLeftRightIcon className="h-6 w-6 text-white" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">المحادثات</h2>
                <p className="text-indigo-100 text-sm">
                  إدارة محادثات العملاء ({filteredConversations.length})
                </p>
              </div>
              {hasNewMessages && (
                <div className="flex items-center space-x-2 space-x-reverse bg-red-500/20 px-3 py-1 rounded-full backdrop-blur-sm">
                  <div className="w-2 h-2 bg-red-400 rounded-full animate-pulse"></div>
                  <span className="text-xs text-red-100 font-medium animate-pulse">
                    رسائل جديدة
                  </span>
                </div>
              )}
            </div>
            {isAutoUpdating && !isUserTyping && (
              <div className="flex items-center text-sm bg-white/20 px-3 py-1 rounded-full backdrop-blur-sm">
                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white/30 border-t-white ml-2"></div>
                <span className="text-white font-medium">تحديث تلقائي</span>
              </div>
            )}
            {isUserTyping && (
              <div className="flex items-center text-sm bg-orange-500/20 px-3 py-1 rounded-full backdrop-blur-sm">
                <div className="flex space-x-1 ml-2">
                  <div className="w-2 h-2 bg-orange-300 rounded-full animate-bounce"></div>
                  <div
                    className="w-2 h-2 bg-orange-300 rounded-full animate-bounce"
                    style={{ animationDelay: "0.1s" }}
                  ></div>
                  <div
                    className="w-2 h-2 bg-orange-300 rounded-full animate-bounce"
                    style={{ animationDelay: "0.2s" }}
                  ></div>
                </div>
                <span className="text-orange-100 font-medium">
                  جاري الكتابة
                </span>
              </div>
            )}
          </div>
          <div className="flex space-x-3 space-x-reverse mt-4">
            <div className="relative flex-1">
              <label htmlFor="conversations-search" className="sr-only">
                البحث في المحادثات
              </label>
              <MagnifyingGlassIcon className="h-5 w-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-white/60" />
              <input
                id="conversations-search"
                name="searchQuery"
                type="text"
                autoComplete="off"
                placeholder="البحث في المحادثات..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-3 bg-white/20 border border-white/30 rounded-xl text-white placeholder-white/60 focus:ring-2 focus:ring-white/50 focus:border-white/50 backdrop-blur-sm transition-all duration-200"
              />
            </div>
            <div className="flex items-center space-x-2 space-x-reverse">
              <button
                onClick={handleManualRefresh}
                disabled={loading || isAutoUpdating}
                className="p-3 text-white/80 hover:text-white hover:bg-white/20 rounded-xl transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed backdrop-blur-sm"
                title="تحديث المحادثات"
              >
                <ArrowPathIcon
                  className={`h-5 w-5 ${loading || isAutoUpdating ? "animate-spin" : ""}`}
                />
              </button>

              {/* مؤشر حالة التحديث التلقائي */}
              <div className="flex items-center space-x-2 space-x-reverse text-xs bg-white/20 px-3 py-2 rounded-xl backdrop-blur-sm">
                <div
                  className={`w-2 h-2 rounded-full ${!isUserTyping ? "bg-green-400 animate-pulse" : "bg-yellow-400"}`}
                ></div>
                <span className="text-white/80 font-medium">
                  {!isUserTyping ? "متصل" : "متوقف"}
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Conversations List */}
        <div className="flex-1 min-h-0 overflow-y-auto p-3 space-y-3 conversations-scroll scroll-indicator">
          {filteredConversations.length === 0 ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center p-8">
                <div className="w-16 h-16 bg-gradient-to-br from-gray-100 to-gray-200 rounded-3xl flex items-center justify-center mx-auto mb-4 shadow-lg">
                  <ChatBubbleLeftRightIcon className="h-8 w-8 text-gray-400" />
                </div>
                <h3 className="text-lg font-semibold text-gray-600 mb-2">
                  لا توجد محادثات
                </h3>
                <p className="text-gray-500 text-sm">
                  في انتظار رسائل العملاء...
                </p>
              </div>
            </div>
          ) : (
            filteredConversations.map((conversation, index) => (
              <div
                key={conversation.id}
                onClick={() => handleSelectConversation(conversation)}
                className={`conversation-item group relative p-4 mb-2 rounded-2xl cursor-pointer animate-slide-in ${
                  selectedConversation?.id === conversation.id
                    ? "bg-gradient-to-r from-indigo-500 to-purple-600 text-white shadow-lg shadow-indigo-500/25"
                    : "bg-white/60 hover:bg-white/80 backdrop-blur-sm border border-gray-200/50 hover:shadow-lg hover:shadow-gray-500/10"
                }`}
                style={{
                  animationDelay: `${index * 0.1}s`,
                }}
              >
                <div className="flex items-center space-x-4 space-x-reverse">
                  <div className="relative">
                    <div
                      className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-300 ${
                        selectedConversation?.id === conversation.id
                          ? "bg-white/20 backdrop-blur-sm"
                          : "bg-gradient-to-br from-indigo-100 to-purple-100"
                      }`}
                    >
                      <UserCircleIcon
                        className={`h-8 w-8 ${
                          selectedConversation?.id === conversation.id
                            ? "text-white"
                            : "text-indigo-600"
                        }`}
                      />
                    </div>
                    {conversation.isOnline && (
                      <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-white shadow-lg animate-pulse"></div>
                    )}
                    <div className="absolute -bottom-1 -left-1 text-sm">
                      {getPlatformIcon(conversation.platform)}
                    </div>
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-2">
                      <h3
                        className={`text-base font-semibold truncate transition-colors duration-300 ${
                          selectedConversation?.id === conversation.id
                            ? "text-white"
                            : "text-gray-900"
                        }`}
                      >
                        {conversation.customerName}
                        {conversation.pageName && (
                          <span className="text-xs text-blue-600 font-medium bg-blue-50 px-1.5 py-0.5 rounded mr-2">
                            {conversation.pageName}
                          </span>
                        )}
                      </h3>
                      <div className="flex items-center space-x-2 space-x-reverse">
                        <span
                          className={`text-xs font-medium ${
                            selectedConversation?.id === conversation.id
                              ? "text-white/80"
                              : "text-gray-500"
                          }`}
                        >
                          {formatTime(conversation.lastMessageTime)}
                        </span>
                        {conversation.unreadCount > 0 && (
                          <span className="inline-flex items-center justify-center min-w-[20px] h-5 px-2 text-xs font-bold text-white bg-red-500 rounded-full shadow-lg animate-pulse">
                            {conversation.unreadCount}
                          </span>
                        )}
                      </div>
                    </div>
                    <p
                      className={`text-sm truncate transition-colors duration-300 ${
                        selectedConversation?.id === conversation.id
                          ? "text-white/90"
                          : "text-gray-600"
                      }`}
                    >
                      {conversation.lastMessage}
                    </p>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Chat Area */}
      {selectedConversation ? (
        <div className="flex-1 h-full max-h-full flex flex-col bg-white/50 backdrop-blur-sm overflow-hidden">
          {/* Chat Header */}
          <div className="flex-shrink-0 bg-white/80 backdrop-blur-sm border-b border-gray-200/50 p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-4 space-x-reverse">
                <div className="relative">
                  <div className="w-12 h-12 bg-gradient-to-br from-indigo-100 to-purple-100 rounded-2xl flex items-center justify-center shadow-lg">
                    <UserCircleIcon className="h-8 w-8 text-indigo-600" />
                  </div>
                  {selectedConversation.isOnline && (
                    <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-white shadow-lg animate-pulse"></div>
                  )}
                </div>
                <div>
                  <h3 className="text-lg font-bold text-gray-900">
                    {selectedConversation.customerName}
                  </h3>
                  <div className="flex items-center space-x-3 space-x-reverse mt-1">
                    <span
                      className={`text-sm font-medium ${selectedConversation.isOnline ? "text-green-600" : "text-gray-500"}`}
                    >
                      {selectedConversation.isOnline ? "متصل الآن" : "غير متصل"}
                    </span>
                    <div className="flex items-center space-x-1 space-x-reverse">
                      <div
                        className={`w-2 h-2 rounded-full ${isConnected ? "bg-green-500 animate-pulse" : "bg-red-500"}`}
                      ></div>
                      <span className="text-xs text-gray-500">
                        {isConnected ? "مباشر" : "غير مباشر"}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
              <div className="flex items-center space-x-2 space-x-reverse">
                <button className="p-3 text-gray-400 hover:text-indigo-600 rounded-xl hover:bg-indigo-50 transition-all duration-200 group">
                  <PhoneIcon className="h-5 w-5 group-hover:scale-110 transition-transform duration-200" />
                </button>
                <button className="p-3 text-gray-400 hover:text-purple-600 rounded-xl hover:bg-purple-50 transition-all duration-200 group">
                  <VideoCameraIcon className="h-5 w-5 group-hover:scale-110 transition-transform duration-200" />
                </button>
                <button className="p-3 text-gray-400 hover:text-blue-600 rounded-xl hover:bg-blue-50 transition-all duration-200 group">
                  <InformationCircleIcon className="h-5 w-5 group-hover:scale-110 transition-transform duration-200" />
                </button>
                <button className="p-3 text-gray-400 hover:text-gray-600 rounded-xl hover:bg-gray-50 transition-all duration-200 group">
                  <EllipsisVerticalIcon className="h-5 w-5 group-hover:scale-110 transition-transform duration-200" />
                </button>
              </div>
            </div>
          </div>

          {/* Messages */}
          <div className="relative flex-1 min-h-0 overflow-hidden">
            <div
              ref={messagesContainerRef}
              onScroll={handleScroll}
              className="h-full max-h-full overflow-y-auto p-6 space-y-4 bg-gradient-to-b from-transparent to-gray-50/50 messages-scroll scroll-indicator"
            >
              {selectedConversation?.messages?.length > 0 ? (
                selectedConversation.messages.map((message, index) => (
                  <div
                    key={message.id}
                    className={`flex ${message.isFromCustomer ? "justify-start" : "justify-end"} animate-fade-in`}
                    style={{
                      animationDelay: `${index * 0.1}s`,
                    }}
                  >
                    <div
                      className={`message-bubble relative max-w-xs lg:max-w-md px-5 py-3 rounded-2xl shadow-lg backdrop-blur-sm ${
                        message.isFromCustomer
                          ? "bg-white/90 text-gray-900 border border-gray-200/50"
                          : message.isAutoGenerated
                            ? "bg-gradient-to-r from-emerald-500 to-teal-600 text-white shadow-emerald-500/25"
                            : "bg-gradient-to-r from-indigo-500 to-purple-600 text-white shadow-indigo-500/25"
                      }`}
                    >
                      {/* مؤشر الرسالة التلقائية */}
                      {message.isAutoGenerated && !message.isFromCustomer && (
                        <div className="absolute -top-2 -right-2 w-6 h-6 bg-yellow-400 rounded-full flex items-center justify-center shadow-lg">
                          <span className="text-xs">🤖</span>
                        </div>
                      )}

                      <div className="text-sm leading-relaxed">
                        {message.content}
                      </div>
                      <div className="flex items-center justify-between mt-2">
                        <div
                          className={`text-xs font-medium ${
                            message.isFromCustomer
                              ? "text-gray-500"
                              : "text-white/80"
                          }`}
                        >
                          {formatTime(message.timestamp)}
                        </div>

                        {/* مؤشر نوع الرسالة */}
                        {message.isAutoGenerated && !message.isFromCustomer && (
                          <div className="text-xs px-2 py-1 rounded-full bg-white/20 text-white/80">
                            {message.provider === "system" ? "نظام" : "ذكي"}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex items-center justify-center h-full">
                  <div className="text-center p-8">
                    <div className="w-20 h-20 bg-gradient-to-br from-indigo-100 to-purple-100 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-lg">
                      <ChatBubbleLeftRightIcon className="h-10 w-10 text-indigo-500" />
                    </div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2">
                      لا توجد رسائل بعد
                    </h3>
                    <p className="text-gray-500 mb-4">
                      ابدأ محادثة جديدة مع العميل
                    </p>
                    <div className="inline-flex items-center px-4 py-2 bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-xl text-sm font-medium shadow-lg">
                      <span>في انتظار الرسائل...</span>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* زر التمرير لأسفل */}
            {showScrollButton && (
              <button
                onClick={scrollToBottom}
                className="absolute bottom-4 right-4 p-3 bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-full shadow-lg hover:shadow-xl transition-all duration-300 hover:scale-110 group animate-fade-in"
                title="التمرير لأسفل"
              >
                <svg
                  className="w-5 h-5 group-hover:translate-y-1 transition-transform duration-200"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 14l-7 7m0 0l-7-7m7 7V3"
                  />
                </svg>
              </button>
            )}
          </div>

          {/* Message Input */}
          <div className="flex-shrink-0 bg-white/80 backdrop-blur-sm border-t border-gray-200/50 p-6 shadow-lg">
            <div className="flex items-end space-x-3 space-x-reverse">
              <button className="p-3 text-gray-400 hover:text-indigo-600 rounded-xl hover:bg-indigo-50 transition-all duration-200 group">
                <PaperClipIcon className="h-5 w-5 group-hover:scale-110 transition-transform duration-200" />
              </button>
              <div className="flex-1 relative">
                <label htmlFor="conversation-message-input" className="sr-only">
                  اكتب رسالتك هنا
                </label>
                <textarea
                  id="conversation-message-input"
                  name="message"
                  autoComplete="off"
                  value={newMessage}
                  onChange={(e) => {
                    setNewMessage(e.target.value);
                    handleTypingStart(); // تتبع الكتابة
                  }}
                  onKeyPress={handleKeyPress}
                  placeholder="اكتب رسالتك هنا..."
                  className="w-full px-5 py-4 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 resize-none bg-white/90 backdrop-blur-sm shadow-sm transition-all duration-200 hover:shadow-md"
                  rows={1}
                />
              </div>
              <button className="p-3 text-gray-400 hover:text-purple-600 rounded-xl hover:bg-purple-50 transition-all duration-200 group">
                <FaceSmileIcon className="h-5 w-5 group-hover:scale-110 transition-transform duration-200" />
              </button>
              <button
                onClick={handleSendMessage}
                disabled={!newMessage.trim()}
                className="p-4 bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-2xl hover:from-indigo-600 hover:to-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 shadow-lg hover:shadow-xl hover:scale-105 group"
              >
                <PaperAirplaneIcon className="h-5 w-5 group-hover:translate-x-1 transition-transform duration-200" />
              </button>
            </div>
          </div>
        </div>
      ) : (
        <div className="flex-1 h-full max-h-full flex items-center justify-center bg-gradient-to-br from-gray-50 to-indigo-50 overflow-hidden">
          <div className="text-center p-12">
            <div className="w-24 h-24 bg-gradient-to-br from-indigo-100 to-purple-100 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-xl">
              <ChatBubbleLeftRightIcon className="h-12 w-12 text-indigo-500" />
            </div>
            <h3 className="text-2xl font-bold text-gray-900 mb-4">
              اختر محادثة للبدء
            </h3>
            <p className="text-gray-500 text-lg mb-6">
              اختر محادثة من القائمة لبدء المراسلة مع العملاء
            </p>
            <div className="inline-flex items-center px-6 py-3 bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-2xl text-sm font-medium shadow-lg hover:shadow-xl transition-all duration-200 cursor-pointer">
              <span>جاهز للمحادثة</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Conversations;

import React, { useState, useEffect } from "react";
import {
  ChatBubbleLeftRightIcon,
  MagnifyingGlassIcon,
  ChartBarIcon,
  Cog6ToothIcon,
  BellIcon,
  UserGroupIcon,
} from "@heroicons/react/24/outline";

// Import all the enhanced components
import ConversationsImproved from "./ConversationsImproved";
import ConversationAnalytics from "../../components/conversations/ConversationAnalytics";
import AdvancedSearch from "../../components/conversations/AdvancedSearch";
import NotificationSystem, {
  useNotifications,
} from "../../components/common/NotificationSystem";
import ErrorBoundary from "../../components/common/ErrorBoundary";

type DashboardView = "conversations" | "analytics" | "search" | "settings";

interface DashboardTab {
  id: DashboardView;
  label: string;
  icon: React.ReactNode;
  component: React.ReactNode;
}

const ConversationsDashboard: React.FC = () => {
  const [activeView, setActiveView] = useState<DashboardView>("conversations");
  const [showSearch, setShowSearch] = useState(false);
  const [searchFilters, setSearchFilters] = useState<any>(null);
  const [dashboardStats, setDashboardStats] = useState({
    totalConversations: 0,
    unreadMessages: 0,
    activeUsers: 0,
    responseTime: 0,
  });

  const { showSuccess, showInfo, showWarning } = useNotifications();

  // تحميل إحصائيات سريعة للوحة التحكم
  useEffect(() => {
    const loadDashboardStats = async () => {
      try {
        // محاكاة تحميل الإحصائيات
        const stats = {
          totalConversations: 127,
          unreadMessages: 23,
          activeUsers: 15,
          responseTime: 2.5,
        };
        setDashboardStats(stats);
      } catch (error) {
        console.error("Error loading dashboard stats:", error);
      }
    };

    loadDashboardStats();
  }, []);

  // معالجة البحث المتقدم
  const handleAdvancedSearch = (filters: any) => {
    setSearchFilters(filters);
    setShowSearch(false);
    setActiveView("conversations");
    showInfo("تم تطبيق البحث", `تم البحث عن: "${filters.query}"`);
  };

  // معالجة اختيار نتيجة البحث
  const handleSearchResultSelect = (result: any) => {
    setShowSearch(false);
    setActiveView("conversations");
    showSuccess("تم العثور على الرسالة", "سيتم الانتقال إلى المحادثة المحددة");
  };

  // تبويبات لوحة التحكم
  const dashboardTabs: DashboardTab[] = [
    {
      id: "conversations",
      label: "المحادثات",
      icon: <ChatBubbleLeftRightIcon className="w-5 h-5" />,
      component: <ConversationsImproved />,
    },
    {
      id: "analytics",
      label: "الإحصائيات",
      icon: <ChartBarIcon className="w-5 h-5" />,
      component: <ConversationAnalytics />,
    },
    {
      id: "search",
      label: "البحث المتقدم",
      icon: <MagnifyingGlassIcon className="w-5 h-5" />,
      component: null, // يتم التعامل معه بشكل منفصل
    },
    {
      id: "settings",
      label: "الإعدادات",
      icon: <Cog6ToothIcon className="w-5 h-5" />,
      component: <ConversationSettings />,
    },
  ];

  const activeTab = dashboardTabs.find((tab) => tab.id === activeView);

  return (
    <ErrorBoundary>
      <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50">
        {/* Header */}
        <div className="bg-white shadow-sm border-b border-gray-200">
          <div className="w-full px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              {/* Logo and Title */}
              <div className="flex items-center space-x-4 space-x-reverse">
                <div className="flex items-center space-x-3 space-x-reverse">
                  <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center">
                    <ChatBubbleLeftRightIcon className="w-6 h-6 text-white" />
                  </div>
                  <div>
                    <h1 className="text-xl font-bold text-gray-900">
                      لوحة المحادثات
                    </h1>
                    <p className="text-sm text-gray-500">
                      إدارة شاملة للمحادثات والرسائل
                    </p>
                  </div>
                </div>
              </div>

              {/* Quick Stats */}
              <div className="hidden md:flex items-center space-x-6 space-x-reverse">
                <div className="text-center">
                  <div className="text-2xl font-bold text-indigo-600">
                    {dashboardStats.totalConversations}
                  </div>
                  <div className="text-xs text-gray-500">محادثة</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-red-600">
                    {dashboardStats.unreadMessages}
                  </div>
                  <div className="text-xs text-gray-500">غير مقروء</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-green-600">
                    {dashboardStats.activeUsers}
                  </div>
                  <div className="text-xs text-gray-500">متصل</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-yellow-600">
                    {dashboardStats.responseTime}د
                  </div>
                  <div className="text-xs text-gray-500">متوسط الرد</div>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex items-center space-x-3 space-x-reverse">
                <button
                  onClick={() => setShowSearch(true)}
                  className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200"
                  title="البحث المتقدم"
                >
                  <MagnifyingGlassIcon className="w-5 h-5" />
                </button>
                <button
                  className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200 relative"
                  title="الإشعارات"
                >
                  <BellIcon className="w-5 h-5" />
                  {dashboardStats.unreadMessages > 0 && (
                    <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                      {dashboardStats.unreadMessages > 9
                        ? "9+"
                        : dashboardStats.unreadMessages}
                    </span>
                  )}
                </button>
                <button
                  className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200"
                  title="المستخدمون المتصلون"
                >
                  <UserGroupIcon className="w-5 h-5" />
                </button>
              </div>
            </div>

            {/* Navigation Tabs */}
            <div className="flex space-x-8 space-x-reverse">
              {dashboardTabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => {
                    if (tab.id === "search") {
                      setShowSearch(true);
                    } else {
                      setActiveView(tab.id);
                    }
                  }}
                  className={`
                    flex items-center space-x-2 space-x-reverse py-4 px-1 border-b-2 font-medium text-sm transition-colors duration-200
                    ${
                      activeView === tab.id
                        ? "border-indigo-500 text-indigo-600"
                        : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
                    }
                  `}
                >
                  {tab.icon}
                  <span>{tab.label}</span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Main Content */}
        <div className="w-full px-4 sm:px-6 lg:px-8 py-6">
          {/* Welcome Message */}
          {activeView === "conversations" && !searchFilters && (
            <div className="mb-6 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-lg p-6 text-white">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-bold mb-2">
                    مرحباً بك في نظام المحادثات المحسن
                  </h2>
                  <p className="text-indigo-100">
                    استمتع بتجربة محادثات متطورة مع رسائل فورية، تمرير ذكي،
                    ومعالجة أخطاء محسنة
                  </p>
                </div>
                <div className="hidden md:block">
                  <div className="w-16 h-16 bg-white bg-opacity-20 rounded-full flex items-center justify-center">
                    <ChatBubbleLeftRightIcon className="w-8 h-8" />
                  </div>
                </div>
              </div>

              {/* Quick Actions */}
              <div className="mt-4 flex space-x-4 space-x-reverse">
                <button
                  onClick={() => setShowSearch(true)}
                  className="px-4 py-2 bg-white bg-opacity-20 text-white rounded-lg hover:bg-opacity-30 transition-colors duration-200 flex items-center space-x-2 space-x-reverse"
                >
                  <MagnifyingGlassIcon className="w-4 h-4" />
                  <span>بحث متقدم</span>
                </button>
                <button
                  onClick={() => setActiveView("analytics")}
                  className="px-4 py-2 bg-white bg-opacity-20 text-white rounded-lg hover:bg-opacity-30 transition-colors duration-200 flex items-center space-x-2 space-x-reverse"
                >
                  <ChartBarIcon className="w-4 h-4" />
                  <span>عرض الإحصائيات</span>
                </button>
              </div>
            </div>
          )}

          {/* Search Results Banner */}
          {searchFilters && activeView === "conversations" && (
            <div className="mb-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-3 space-x-reverse">
                  <MagnifyingGlassIcon className="w-5 h-5 text-blue-600" />
                  <div>
                    <p className="text-sm font-medium text-blue-900">
                      نتائج البحث عن: "{searchFilters.query}"
                    </p>
                    <p className="text-xs text-blue-700">
                      تم تطبيق{" "}
                      {
                        Object.keys(searchFilters).filter(
                          (key) =>
                            searchFilters[key] &&
                            searchFilters[key] !== "" &&
                            (Array.isArray(searchFilters[key])
                              ? searchFilters[key].length > 0
                              : true),
                        ).length
                      }{" "}
                      فلتر
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => setSearchFilters(null)}
                  className="text-blue-600 hover:text-blue-800 text-sm font-medium"
                >
                  مسح البحث
                </button>
              </div>
            </div>
          )}

          {/* Active Tab Content */}
          <div className="min-h-[600px]">{activeTab?.component}</div>
        </div>

        {/* Advanced Search Modal */}
        <AdvancedSearch
          isVisible={showSearch}
          onClose={() => setShowSearch(false)}
          onSearch={handleAdvancedSearch}
          onResultSelect={handleSearchResultSelect}
        />

        {/* Notification System */}
        <NotificationSystem position="top-right" maxNotifications={5} />
      </div>
    </ErrorBoundary>
  );
};

// مكون إعدادات المحادثات
const ConversationSettings: React.FC = () => {
  const [settings, setSettings] = useState({
    autoRefresh: true,
    refreshInterval: 30,
    soundNotifications: true,
    desktopNotifications: false,
    showTypingIndicators: true,
    autoScroll: true,
    compactView: false,
    darkMode: false,
  });

  const { showSuccess } = useNotifications();

  const handleSaveSettings = () => {
    localStorage.setItem("conversationSettings", JSON.stringify(settings));
    showSuccess("تم الحفظ", "تم حفظ الإعدادات بنجاح");
  };

  useEffect(() => {
    const saved = localStorage.getItem("conversationSettings");
    if (saved) {
      setSettings(JSON.parse(saved));
    }
  }, []);

  return (
    <div className="bg-white rounded-lg shadow-md p-6">
      <h3 className="text-lg font-semibold text-gray-900 mb-6">
        إعدادات المحادثات
      </h3>

      <div className="space-y-6">
        {/* General Settings */}
        <div>
          <h4 className="text-md font-medium text-gray-800 mb-4">
            الإعدادات العامة
          </h4>
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">
                  التحديث التلقائي
                </label>
                <p className="text-xs text-gray-500">
                  تحديث المحادثات تلقائياً
                </p>
              </div>
              <input
                type="checkbox"
                checked={settings.autoRefresh}
                onChange={(e) =>
                  setSettings((prev) => ({
                    ...prev,
                    autoRefresh: e.target.checked,
                  }))
                }
                className="text-indigo-600 focus:ring-indigo-500"
              />
            </div>

            {settings.autoRefresh && (
              <div className="flex items-center justify-between">
                <div>
                  <label className="text-sm font-medium text-gray-700">
                    فترة التحديث (ثانية)
                  </label>
                  <p className="text-xs text-gray-500">كم ثانية بين كل تحديث</p>
                </div>
                <select
                  value={settings.refreshInterval}
                  onChange={(e) =>
                    setSettings((prev) => ({
                      ...prev,
                      refreshInterval: parseInt(e.target.value),
                    }))
                  }
                  className="px-3 py-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                >
                  <option value={10}>10 ثوانٍ</option>
                  <option value={30}>30 ثانية</option>
                  <option value={60}>دقيقة</option>
                  <option value={300}>5 دقائق</option>
                </select>
              </div>
            )}
          </div>
        </div>

        {/* Notification Settings */}
        <div>
          <h4 className="text-md font-medium text-gray-800 mb-4">
            إعدادات الإشعارات
          </h4>
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">
                  الإشعارات الصوتية
                </label>
                <p className="text-xs text-gray-500">
                  تشغيل صوت عند وصول رسالة جديدة
                </p>
              </div>
              <input
                type="checkbox"
                checked={settings.soundNotifications}
                onChange={(e) =>
                  setSettings((prev) => ({
                    ...prev,
                    soundNotifications: e.target.checked,
                  }))
                }
                className="text-indigo-600 focus:ring-indigo-500"
              />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">
                  إشعارات سطح المكتب
                </label>
                <p className="text-xs text-gray-500">
                  إظهار إشعارات في نظام التشغيل
                </p>
              </div>
              <input
                type="checkbox"
                checked={settings.desktopNotifications}
                onChange={(e) =>
                  setSettings((prev) => ({
                    ...prev,
                    desktopNotifications: e.target.checked,
                  }))
                }
                className="text-indigo-600 focus:ring-indigo-500"
              />
            </div>
          </div>
        </div>

        {/* UI Settings */}
        <div>
          <h4 className="text-md font-medium text-gray-800 mb-4">
            إعدادات الواجهة
          </h4>
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">
                  مؤشرات الكتابة
                </label>
                <p className="text-xs text-gray-500">إظهار عندما يكتب شخص ما</p>
              </div>
              <input
                type="checkbox"
                checked={settings.showTypingIndicators}
                onChange={(e) =>
                  setSettings((prev) => ({
                    ...prev,
                    showTypingIndicators: e.target.checked,
                  }))
                }
                className="text-indigo-600 focus:ring-indigo-500"
              />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">
                  التمرير التلقائي
                </label>
                <p className="text-xs text-gray-500">
                  التمرير تلقائياً للرسائل الجديدة
                </p>
              </div>
              <input
                type="checkbox"
                checked={settings.autoScroll}
                onChange={(e) =>
                  setSettings((prev) => ({
                    ...prev,
                    autoScroll: e.target.checked,
                  }))
                }
                className="text-indigo-600 focus:ring-indigo-500"
              />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">
                  العرض المضغوط
                </label>
                <p className="text-xs text-gray-500">
                  عرض أكثر محادثات في مساحة أقل
                </p>
              </div>
              <input
                type="checkbox"
                checked={settings.compactView}
                onChange={(e) =>
                  setSettings((prev) => ({
                    ...prev,
                    compactView: e.target.checked,
                  }))
                }
                className="text-indigo-600 focus:ring-indigo-500"
              />
            </div>
          </div>
        </div>

        {/* Save Button */}
        <div className="pt-4 border-t border-gray-200">
          <button
            onClick={handleSaveSettings}
            className="w-full px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors duration-200"
          >
            حفظ الإعدادات
          </button>
        </div>
      </div>
    </div>
  );
};

export default ConversationsDashboard;

import React, {
  useState,
  useEffect,
  useMemo,
  useCallback,
  useRef,
} from "react";
import {
  PaperAirplaneIcon,
  FaceSmileIcon,
  PaperClipIcon,
  MagnifyingGlassIcon,
  EllipsisVerticalIcon,
  PhoneIcon,
  VideoCameraIcon,
  InformationCircleIcon,
  ChatBubbleLeftRightIcon,
  TrashIcon,
  SpeakerWaveIcon,
  SpeakerXMarkIcon,
  CpuChipIcon,
} from "@heroicons/react/24/outline";

// Import new hooks and components
import useLoadingWithRetry from "../../hooks/useLoadingWithRetry";
import useSmartScroll from "../../hooks/useSmartScroll";
import useRealTimeMessaging from "../../hooks/useRealTimeMessaging";
import ErrorBoundary from "../../components/common/ErrorBoundary";
import ErrorDisplay from "../../components/common/ErrorDisplay";
import {
  ConversationSkeleton,
  MessagesSkeleton,
  RetryIndicator,
  SendingIndicator,
  InitialLoading,
  EmptyState,
} from "../../components/common/LoadingStates";
import {
  ScrollToBottomButton,
  NewMessageAlert,
  MessagesContainer,
  TypingIndicator,
  ConnectionStatus,
} from "../../components/common/ScrollComponents";

// استيراد التحسينات الإضافية
import "../../styles/conversations-improved.css";

// استيراد خدمة التحكم في الذكاء الاصطناعي
import { useConversationAI } from "../../services/conversationAIService";
import { getImageUrl } from "../../utils/urlConverter";

const ConversationsImproved: React.FC = () => {
  const [newMessage, setNewMessage] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [deletingConversation, setDeletingConversation] = useState<
    string | null
  >(null);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [togglingAI, setTogglingAI] = useState<string | null>(null);
  const [uploadingFile, setUploadingFile] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // استخدام الـ hooks الجديدة
  const {
    loading,
    error,
    retryCount,
    executeWithRetry,
    retry,
    clearError,
    isError,
  } = useLoadingWithRetry();

  const {
    conversations,
    selectedConversation,
    typingUsers,
    isConnected,
    isReconnecting,
    selectConversation,
    sendMessage,
    startTyping,
    loadConversations,
  } = useRealTimeMessaging();

  const {
    messagesEndRef,
    messagesContainerRef,
    showScrollButton,
    showNewMessageAlert,
    unreadCount,
    scrollToBottom,
    handleScroll,
    markAsRead: markScrollAsRead,
  } = useSmartScroll();

  // خدمة التحكم في الذكاء الاصطناعي
  const { toggleAI, getAIStatus } = useConversationAI();

  // خدمة رفع الملفات
  const uploadService = require("../../services/uploadService").default;

  // دالة تشغيل الصوت للرسائل الجديدة
  const playNotificationSound = useCallback(() => {
    if (soundEnabled) {
      try {
        // استخدام Web Audio API لإنشاء صوت بسيط
        const audioContext = new (
          window.AudioContext || (window as any).webkitAudioContext
        )();
        const oscillator = audioContext.createOscillator();
        const gainNode = audioContext.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(audioContext.destination);

        oscillator.frequency.setValueAtTime(800, audioContext.currentTime);
        oscillator.frequency.setValueAtTime(
          600,
          audioContext.currentTime + 0.1,
        );

        gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
        gainNode.gain.exponentialRampToValueAtTime(
          0.01,
          audioContext.currentTime + 0.3,
        );

        oscillator.start(audioContext.currentTime);
        oscillator.stop(audioContext.currentTime + 0.3);
      } catch (error) {
        console.error("Failed to play notification sound:", error);
      }
    }
  }, [soundEnabled]);

  // تحميل المحادثات عند بدء التشغيل
  useEffect(() => {
    executeWithRetry(() => loadConversations(), "conversations");
  }, [executeWithRetry, loadConversations]);

  // اختصارات لوحة المفاتيح
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl/Cmd + K للبحث
      if ((e.ctrlKey || e.metaKey) && e.key === "k") {
        e.preventDefault();
        const searchInput = document.querySelector(
          'input[placeholder*="البحث"]',
        ) as HTMLInputElement;
        searchInput?.focus();
      }

      // Escape لإلغاء البحث
      if (e.key === "Escape" && searchQuery) {
        setSearchQuery("");
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [searchQuery]);

  // معالجة إرسال الرسالة
  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim() || !selectedConversation) return;

    const messageContent = newMessage.trim();
    setNewMessage("");

    try {
      await executeWithRetry(
        () => sendMessage(selectedConversation.id, messageContent),
        "sending",
      );
    } catch (error) {
      console.error("Failed to send message:", error);
    }
  };

  // معالجة الكتابة
  const handleTyping = (e: React.ChangeEvent<HTMLInputElement>) => {
    setNewMessage(e.target.value);

    if (selectedConversation) {
      startTyping(selectedConversation.id);
    }
  };

  // معالجة رفع الملفات
  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0 || !selectedConversation) return;

    // التحقق من نوع الملفات
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (!file.type.startsWith("image/")) {
        alert("يُسمح برفع الصور فقط");
        return;
      }

      // التحقق من حجم الملف (10MB)
      if (file.size > 10 * 1024 * 1024) {
        alert("حجم الملف كبير جداً. الحد الأقصى 10MB");
        return;
      }
    }

    setUploadingFile(true);

    try {
      // رفع الملفات
      const formData = new FormData();
      for (let i = 0; i < files.length; i++) {
        formData.append("files", files[i]);
      }

      const response = await fetch(
        `https://www.mokhtarelhenawy.online/api/v1/conversations/${selectedConversation.id}/upload`,
        {
          method: "POST",
          body: formData,
        },
      );

      const data = await response.json();

      if (data.success) {
        // معالجة كل ملف مرفوع
        for (let i = 0; i < data.data.length; i++) {
          const uploadedFile = data.data[i];

          // إرسال رسالة الصورة
          const imageMessage = {
            content: uploadedFile.originalName,
            conversationId: selectedConversation.id,
            type: "image" as const,
            isFromCustomer: false,
            status: "sending" as const,
            fileUrl: uploadedFile.fullUrl,
            fileName: uploadedFile.originalName,
            fileSize: uploadedFile.size,
          };

          // إضافة الرسالة محلياً
          const newMsg = {
            id: Date.now().toString() + i, // إضافة معرف فريد
            ...imageMessage,
            senderId: "current-user",
            senderName: "أنت",
            timestamp: new Date(),
            status: "sent" as const,
          };

          // تحديث المحادثة محلياً
          const updatedConversation = {
            ...selectedConversation,
            messages: [...selectedConversation.messages, newMsg],
            lastMessage: `📷 ${uploadedFile.originalName}`,
            lastMessageTime: new Date(),
          };

          // إرسال عبر Socket.IO (سيتم إرسالها للعميل على الفيسبوك)
          emit("send_message", {
            conversationId: selectedConversation.id,
            content: uploadedFile.fullUrl,
            type: "image",
            fileUrl: uploadedFile.fullUrl,
            fileName: uploadedFile.originalName,
            fileSize: uploadedFile.size,
          });
        }

        console.log(`✅ تم رفع وإرسال ${files.length} صورة بنجاح`);
      } else {
        alert(data.error || "فشل في رفع الصور");
      }
    } catch (error) {
      console.error("❌ خطأ في رفع الصور:", error);
      alert("حدث خطأ أثناء رفع الصور");
    } finally {
      setUploadingFile(false);
      // مسح input
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    }
  };

  // معالجة اختيار المحادثة مع تحسين الأداء
  const handleSelectConversation = useCallback(
    (conversationId: string) => {
      selectConversation(conversationId);
      markScrollAsRead();
    },
    [selectConversation, markScrollAsRead],
  );

  // معالجة حذف المحادثة
  const handleDeleteConversation = async (
    conversationId: string,
    customerName: string,
  ) => {
    // تأكيد الحذف
    const confirmDelete = window.confirm(
      `هل أنت متأكد من حذف محادثة "${customerName}"؟\n\nسيتم حذف جميع الرسائل المرتبطة بهذه المحادثة نهائياً.`,
    );

    if (!confirmDelete) return;

    try {
      setDeletingConversation(conversationId);

      const response = await fetch(
        `https://www.mokhtarelhenawy.online/api/v1/conversations/${conversationId}`,
        {
          method: "DELETE",
          headers: {
            "Content-Type": "application/json",
          },
        },
      );

      const data = await response.json();

      if (data.success) {
        // إعادة تحميل المحادثات
        await loadConversations();

        // إذا كانت المحادثة المحذوفة هي المحادثة المختارة، قم بإلغاء الاختيار
        if (selectedConversation?.id === conversationId) {
          selectConversation("");
        }

        console.log("✅ تم حذف المحادثة بنجاح");
      } else {
        throw new Error(data.message || "فشل في حذف المحادثة");
      }
    } catch (error) {
      console.error("❌ خطأ في حذف المحادثة:", error);
      alert("حدث خطأ أثناء حذف المحادثة. يرجى المحاولة مرة أخرى.");
    } finally {
      setDeletingConversation(null);
    }
  };

  // دالة تشغيل/إيقاف الذكاء الاصطناعي للمحادثة
  const handleToggleAI = async (
    conversationId: string,
    currentAIStatus: boolean,
  ) => {
    console.log("🤖 [HANDLE-TOGGLE-AI] Function called with:", {
      conversationId,
      currentAIStatus,
      togglingAI,
    });

    if (togglingAI) {
      console.log("🤖 [HANDLE-TOGGLE-AI] Already toggling, returning");
      return; // منع التشغيل المتعدد
    }

    setTogglingAI(conversationId);
    try {
      const newAIStatus = !currentAIStatus;
      console.log(
        `🤖 [HANDLE-TOGGLE-AI] Toggling AI for conversation ${conversationId} from ${currentAIStatus} to ${newAIStatus}`,
      );

      const result = await toggleAI(conversationId, newAIStatus);
      console.log("🤖 [HANDLE-TOGGLE-AI] API result:", result);

      if (result.success) {
        // تحديث المحادثة محلياً
        await loadConversations();

        // إظهار رسالة نجاح
        const statusText = newAIStatus ? "تم تفعيل" : "تم إيقاف";
        console.log(`✅ ${statusText} الذكاء الاصطناعي للمحادثة`);

        // يمكن إضافة toast notification هنا
        if (soundEnabled) {
          playNotificationSound();
        }
      } else {
        throw new Error(
          result.message || "فشل في تحديث إعدادات الذكاء الاصطناعي",
        );
      }
    } catch (error) {
      console.error("❌ خطأ في تحديث الذكاء الاصطناعي:", error);
      alert(
        "حدث خطأ أثناء تحديث إعدادات الذكاء الاصطناعي. يرجى المحاولة مرة أخرى.",
      );
    } finally {
      setTogglingAI(null);
    }
  };

  // Helper to safely format time
  const formatTime = (date: any) => {
    try {
      if (!date) return "";
      const d = new Date(date);
      if (isNaN(d.getTime())) return "";

      return d.toLocaleTimeString("ar-SA", {
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch (e) {
      console.error("Error formatting time:", e);
      return "";
    }
  };

  // البحث في الخادم بدلاً من التصفية المحلية
  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<any[]>([]);

  // دالة البحث في الخادم
  const handleSearch = useCallback(
    async (query: string) => {
      if (!query.trim()) {
        setSearchResults([]);
        await loadConversations(); // تحميل جميع المحادثات
        return;
      }

      setIsSearching(true);
      try {
        await loadConversations(query.trim());
      } catch (error) {
        console.error("خطأ في البحث:", error);
      } finally {
        setIsSearching(false);
      }
    },
    [loadConversations],
  );

  // المحادثات المعروضة (إما نتائج البحث أو جميع المحادثات)
  const displayedConversations = searchQuery.trim()
    ? conversations
    : conversations;

  // الحصول على مستخدمي الكتابة للمحادثة الحالية
  const currentTypingUsers = typingUsers.filter(
    (user) => user.conversationId === selectedConversation?.id,
  );

  if (loading.initialLoad) {
    return <InitialLoading message="جاري تحميل المحادثات..." />;
  }

  return (
    <ErrorBoundary>
      <div className="flex bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 min-h-full relative">
        {/* Connection Status */}
        <ConnectionStatus
          isConnected={isConnected}
          isReconnecting={isReconnecting}
        />

        {/* Conversations Sidebar - محسن للموبايل */}
        <div className="w-full md:w-1/3 lg:w-1/4 xl:w-1/3 bg-white/80 backdrop-blur-sm border-r border-gray-200/50 flex flex-col shadow-xl">
          {/* Header */}
          <div className="flex-shrink-0 p-6 border-b border-gray-200/50 bg-gradient-to-r from-indigo-500 to-purple-600">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-3 space-x-reverse">
                <ChatBubbleLeftRightIcon className="w-8 h-8 text-white" />
                <h1 className="text-xl font-bold text-white">المحادثات</h1>
              </div>
              <div className="flex items-center space-x-3 space-x-reverse">
                <button
                  onClick={() => setSoundEnabled(!soundEnabled)}
                  className="p-1 text-white/80 hover:text-white hover:bg-white/20 rounded-full transition-colors duration-200"
                  title={soundEnabled ? "إيقاف الصوت" : "تشغيل الصوت"}
                >
                  {soundEnabled ? (
                    <SpeakerWaveIcon className="w-5 h-5" />
                  ) : (
                    <SpeakerXMarkIcon className="w-5 h-5" />
                  )}
                </button>
                <span
                  className={`w-3 h-3 rounded-full ${isConnected ? "bg-green-400" : "bg-red-400"}`}
                ></span>
                <span className="text-white text-sm">
                  {isConnected ? "متصل" : "غير متصل"}
                </span>
              </div>
            </div>

            {/* إحصائيات سريعة */}
            <div className="flex items-center justify-between text-white/80 text-sm mb-4">
              <span>المحادثات: {conversations.length}</span>
              <span>
                غير مقروءة:{" "}
                {conversations.reduce(
                  (sum, conv) => sum + (conv.unreadCount || 0),
                  0,
                )}
              </span>
            </div>

            {/* Search */}
            <div className="relative">
              <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-white/70" />
              <input
                type="text"
                placeholder="البحث في المحادثات (اسم، رقم، محتوى)..."
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  // البحث التلقائي بعد توقف الكتابة
                  const timeoutId = setTimeout(() => {
                    handleSearch(e.target.value);
                  }, 500);

                  // إلغاء البحث السابق
                  return () => clearTimeout(timeoutId);
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    handleSearch(searchQuery);
                  }
                }}
                className="w-full bg-white/20 border border-white/30 rounded-lg px-10 py-2 text-white placeholder-white/70 focus:outline-none focus:ring-2 focus:ring-white/50 focus:border-transparent"
              />
              {isSearching && (
                <div className="absolute left-3 top-1/2 transform -translate-y-1/2">
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                </div>
              )}
            </div>
          </div>

          {/* Error Display */}
          {isError && (
            <div className="p-4">
              <ErrorDisplay
                error={error!}
                onRetry={retry}
                onDismiss={clearError}
                compact
              />
            </div>
          )}

          {/* Retry Indicator */}
          {loading.retrying && (
            <div className="p-4">
              <RetryIndicator
                retryCount={retryCount}
                maxRetries={3}
                isRetrying={loading.retrying}
              />
            </div>
          )}

          {/* Conversations List */}
          <div className="flex-1 overflow-y-auto conversations-scroll">
            {loading.conversations ? (
              <ConversationSkeleton />
            ) : displayedConversations.length === 0 ? (
              <EmptyState
                title={searchQuery.trim() ? "لا توجد نتائج" : "لا توجد محادثات"}
                description={
                  searchQuery.trim()
                    ? `لم يتم العثور على محادثات مطابقة لـ "${searchQuery}"`
                    : "لم يتم العثور على أي محادثات"
                }
                icon={
                  <ChatBubbleLeftRightIcon className="w-12 h-12 text-gray-400" />
                }
              />
            ) : (
              displayedConversations.map((conversation) => (
                <div
                  key={conversation.id}
                  className={`p-4 border-b border-gray-200/50 transition-all duration-200 hover:bg-white/60 ${
                    selectedConversation?.id === conversation.id
                      ? "bg-white/80 border-r-4 border-r-indigo-500"
                      : ""
                  }`}
                >
                  <div className="flex items-center space-x-3 space-x-reverse">
                    <div className="relative flex-shrink-0">
                      <div className="w-12 h-12 bg-gradient-to-br from-indigo-400 to-purple-500 rounded-full flex items-center justify-center text-white font-semibold">
                        {conversation.customerName.charAt(0)}
                      </div>
                      {conversation.isOnline && (
                        <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-400 border-2 border-white rounded-full"></div>
                      )}
                    </div>
                    <div
                      className="flex-1 min-w-0 cursor-pointer"
                      onClick={() => handleSelectConversation(conversation.id)}
                    >
                      <div className="flex items-center justify-between">
                        <h3 className="text-sm font-semibold text-gray-900 truncate">
                          {conversation.customerName}
                          {conversation.pageName && (
                            <span className="text-xs text-blue-600 font-medium bg-blue-50 px-1.5 py-0.5 rounded mr-2">
                              {conversation.pageName}
                            </span>
                          )}
                        </h3>
                        <span className="text-xs text-gray-500">
                          {formatTime(conversation.lastMessageTime)}
                        </span>
                      </div>
                      <p className="text-sm text-gray-600 truncate mt-1">
                        {conversation.lastMessage}
                      </p>
                    </div>

                    {/* Conversation Actions */}
                    <div className="flex items-center space-x-2 space-x-reverse">
                      {conversation.unreadCount > 0 && (
                        <div className="bg-red-500 text-white text-xs rounded-full w-6 h-6 flex items-center justify-center font-medium">
                          {conversation.unreadCount > 99
                            ? "99+"
                            : conversation.unreadCount}
                        </div>
                      )}

                      {/* Delete Button */}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDeleteConversation(
                            conversation.id,
                            conversation.customerName,
                          );
                        }}
                        disabled={deletingConversation === conversation.id}
                        className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-full transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                        title="حذف المحادثة"
                      >
                        {deletingConversation === conversation.id ? (
                          <div className="w-4 h-4 border-2 border-red-600 border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                          <TrashIcon className="w-4 h-4" />
                        )}
                      </button>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Chat Area */}
        <div className="flex-1 flex flex-col bg-white/50 backdrop-blur-sm">
          {selectedConversation ? (
            <>
              {/* Chat Header */}
              <div className="flex-shrink-0 bg-white/80 border-b border-gray-200/50 p-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3 space-x-reverse">
                    <div className="relative">
                      <div className="w-10 h-10 bg-gradient-to-br from-indigo-400 to-purple-500 rounded-full flex items-center justify-center text-white font-semibold">
                        {selectedConversation.customerName.charAt(0)}
                      </div>
                      {selectedConversation.isOnline && (
                        <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-green-400 border-2 border-white rounded-full"></div>
                      )}
                    </div>
                    <div>
                      <h2 className="text-lg font-semibold text-gray-900">
                        {selectedConversation.customerName}
                      </h2>
                      <p className="text-sm text-gray-500">
                        {selectedConversation.isOnline
                          ? "متصل الآن"
                          : "غير متصل"}
                        {/* Debug info */}
                        <span className="ml-2 text-xs text-blue-500">
                          AI:{" "}
                          {selectedConversation.aiEnabled !== undefined
                            ? selectedConversation.aiEnabled
                              ? "ON"
                              : "OFF"
                            : "UNDEFINED"}
                        </span>
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2 space-x-reverse">
                    {/* زر التحكم في الذكاء الاصطناعي - مؤقت للاختبار */}
                    <button
                      onClick={() => {
                        console.log(
                          "🤖 [AI-BUTTON] Clicked! Conversation:",
                          selectedConversation?.id,
                          "AI Status:",
                          selectedConversation?.aiEnabled,
                        );
                        if (selectedConversation) {
                          handleToggleAI(
                            selectedConversation.id,
                            selectedConversation.aiEnabled ?? true,
                          );
                        }
                      }}
                      disabled={
                        !selectedConversation ||
                        togglingAI === selectedConversation?.id
                      }
                      className={`p-2 rounded-full transition-all duration-200 ${
                        (selectedConversation?.aiEnabled ?? true)
                          ? "text-green-600 bg-green-50 hover:bg-green-100"
                          : "text-red-600 bg-red-50 hover:bg-red-100"
                      } disabled:opacity-50 disabled:cursor-not-allowed border-2 border-blue-300`}
                      title={`${(selectedConversation?.aiEnabled ?? true) ? "إيقاف" : "تفعيل"} الذكاء الاصطناعي`}
                    >
                      {togglingAI === selectedConversation?.id ? (
                        <div className="w-5 h-5 border-2 border-current border-t-transparent rounded-full animate-spin"></div>
                      ) : (
                        <CpuChipIcon className="w-5 h-5" />
                      )}
                    </button>

                    <button className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200">
                      <PhoneIcon className="w-5 h-5" />
                    </button>
                    <button className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200">
                      <VideoCameraIcon className="w-5 h-5" />
                    </button>
                    <button className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200">
                      <InformationCircleIcon className="w-5 h-5" />
                    </button>
                    <button className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200">
                      <EllipsisVerticalIcon className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>

              {/* Messages Area */}
              <div className="flex-1 relative">
                <MessagesContainer
                  onScroll={handleScroll}
                  containerRef={messagesContainerRef}
                  className="p-4 space-y-4"
                >
                  {loading.messages ? (
                    <MessagesSkeleton />
                  ) : selectedConversation.messages.length === 0 ? (
                    <EmptyState
                      title="لا توجد رسائل"
                      description="ابدأ محادثة جديدة مع هذا العميل"
                      icon={
                        <ChatBubbleLeftRightIcon className="w-12 h-12 text-gray-400" />
                      }
                    />
                  ) : (
                    selectedConversation.messages.map((message) => (
                      <div
                        key={message.id}
                        className={`flex ${message.isFromCustomer ? "justify-start" : "justify-end"}`}
                      >
                        <div className="max-w-xs lg:max-w-md">
                          <div
                            className={`px-4 py-2 rounded-lg ${
                              message.isFromCustomer
                                ? "bg-gray-200 text-gray-900 rounded-bl-none"
                                : "bg-indigo-600 text-white rounded-br-none"
                            }`}
                          >
                            {/* عرض المحتوى حسب نوع الرسالة */}
                            {(message.type === "image" ||
                              message.type === "IMAGE") &&
                            (message.fileUrl ||
                              (message.content &&
                                message.content.startsWith("http"))) ? (
                              <div className="space-y-2">
                                <img
                                  src={getImageUrl(message)}
                                  alt={message.fileName || "صورة"}
                                  className="max-w-full h-auto rounded-lg cursor-pointer hover:opacity-90 transition-opacity"
                                  style={{
                                    maxHeight: "300px",
                                    maxWidth: "250px",
                                  }}
                                  onClick={() =>
                                    window.open(getImageUrl(message), "_blank")
                                  }
                                  onError={(e) => {
                                    console.error(
                                      "❌ Failed to load image:",
                                      getImageUrl(message),
                                    );
                                    console.log("🔍 Message debug:", {
                                      id: message.id,
                                      type: message.type,
                                      fileUrl: message.fileUrl,
                                      content: message.content,
                                    });
                                    const target =
                                      e.currentTarget as HTMLImageElement;
                                    target.src =
                                      "data:image/svg+xml;base64,";
                                    target.alt = "فشل في تحميل الصورة";
                                  }}
                                />
                                {message.fileName && (
                                  <p className="text-xs text-gray-500 mt-1">
                                    {message.fileName}
                                  </p>
                                )}
                              </div>
                            ) : message.type === "file" && message.fileUrl ? (
                              <div className="space-y-2">
                                <div className="flex items-center space-x-2 bg-gray-100 p-2 rounded-lg">
                                  <PaperClipIcon className="w-4 h-4 text-gray-500" />
                                  <div className="flex-1">
                                    <p className="text-sm font-medium">
                                      {message.fileName || "ملف"}
                                    </p>
                                    {message.fileSize && (
                                      <p className="text-xs text-gray-500">
                                        {(message.fileSize / 1024).toFixed(1)}{" "}
                                        KB
                                      </p>
                                    )}
                                  </div>
                                  <a
                                    href={message.fileUrl}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="text-blue-500 hover:text-blue-700 text-sm"
                                  >
                                    تحميل
                                  </a>
                                </div>
                              </div>
                            ) : (
                              <p className="text-sm">{message.content}</p>
                            )}
                          </div>
                          <div className="flex items-center justify-between mt-1">
                            <span className="text-xs text-gray-500">
                              {formatTime(message.timestamp)}
                            </span>
                            {!message.isFromCustomer && (
                              <span className="text-xs text-gray-500">
                                {message.status === "sending" && "⏳"}
                                {message.status === "sent" && "✓"}
                                {message.status === "delivered" && "✓✓"}
                                {message.status === "read" && "✓✓"}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    ))
                  )}

                  {/* Typing Indicator */}
                  {currentTypingUsers.map((user) => (
                    <TypingIndicator
                      key={user.userId}
                      show={true}
                      userName={user.userName}
                    />
                  ))}

                  <div ref={messagesEndRef} />
                </MessagesContainer>

                {/* Scroll Controls */}
                <ScrollToBottomButton
                  show={showScrollButton}
                  onClick={() => scrollToBottom()}
                  unreadCount={unreadCount}
                />

                <NewMessageAlert
                  show={showNewMessageAlert}
                  count={unreadCount}
                  onClick={() => {
                    scrollToBottom();
                    markScrollAsRead();
                  }}
                />
              </div>

              {/* Message Input */}
              <div className="flex-shrink-0 bg-white/80 border-t border-gray-200/50 p-4">
                <SendingIndicator isSending={loading.sending} />

                <form
                  onSubmit={handleSendMessage}
                  className="flex items-center space-x-3 space-x-reverse"
                >
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleFileSelect}
                    className="hidden"
                    multiple
                  />
                  <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    disabled={uploadingFile}
                    className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                    title="رفع صورة"
                  >
                    {uploadingFile ? (
                      <div className="w-5 h-5 border-2 border-gray-500 border-t-transparent rounded-full animate-spin"></div>
                    ) : (
                      <PaperClipIcon className="w-5 h-5" />
                    )}
                  </button>
                  <button
                    type="button"
                    className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-full transition-colors duration-200"
                  >
                    <FaceSmileIcon className="w-5 h-5" />
                  </button>
                  <div className="flex-1 relative">
                    <input
                      type="text"
                      value={newMessage}
                      onChange={handleTyping}
                      placeholder="اكتب رسالتك هنا..."
                      className="w-full bg-gray-100 border border-gray-300 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                      disabled={loading.sending}
                    />
                  </div>
                  <button
                    type="submit"
                    disabled={!newMessage.trim() || loading.sending}
                    className="p-2 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-200"
                  >
                    <PaperAirplaneIcon className="w-5 h-5" />
                  </button>
                </form>
              </div>
            </>
          ) : (
            <EmptyState
              title="اختر محادثة"
              description="اختر محادثة من القائمة الجانبية لبدء المراسلة"
              icon={
                <ChatBubbleLeftRightIcon className="w-16 h-16 text-gray-400" />
              }
            />
          )}
        </div>
      </div>
    </ErrorBoundary>
  );
};

export default ConversationsImproved;

import React, { useState, useEffect } from "react";

interface Conversation {
  id: string;
  customerName: string;
  lastMessage: string;
  lastMessageTime: Date;
  unreadCount: number;
  pageName?: string; // اسم صفحة الفيسبوك
  pageId?: string; // معرف صفحة الفيسبوك
}

const ConversationsImprovedSimple: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // تحميل المحادثات من API
  const loadConversations = async () => {
    try {
      setLoading(true);
      setError(null);

      console.log("🔄 Loading conversations from API...");
      const response = await fetch(
        "https://www.mokhtarelhenawy.online/api/v1/conversations",
      );
      const data = await response.json();

      if (data.success) {
        console.log("✅ Conversations loaded successfully:", data.data.length);

        // تحويل البيانات للتنسيق المطلوب
        const formattedConversations = data.data.map((conv: any) => ({
          id: conv.id,
          customerName: conv.customerName || "عميل غير معروف",
          lastMessage: conv.lastMessage || "لا توجد رسائل",
          lastMessageTime: new Date(conv.lastMessageTime || Date.now()),
          unreadCount: conv.unreadCount || 0,
          pageName: conv.pageName || null, // إضافة اسم الصفحة
          pageId: conv.pageId || null, // إضافة معرف الصفحة
        }));

        setConversations(formattedConversations);
      } else {
        throw new Error(data.message || "فشل في تحميل المحادثات");
      }
    } catch (error) {
      console.error("❌ Error loading conversations:", error);
      setError("فشل في تحميل المحادثات. يرجى المحاولة مرة أخرى.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadConversations();
  }, []);

  if (loading) {
    return (
      <div className="p-6">
        <div className="bg-white rounded-lg shadow-md p-6">
          <div className="flex items-center justify-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
            <span className="ml-3 text-gray-600">جاري تحميل المحادثات...</span>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6">
        <div className="bg-white rounded-lg shadow-md p-6">
          <div className="bg-red-50 border border-red-200 rounded-lg p-4">
            <h3 className="text-red-800 font-semibold mb-2">
              ❌ خطأ في التحميل
            </h3>
            <p className="text-red-700">{error}</p>
            <button
              onClick={loadConversations}
              className="mt-3 px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700"
            >
              إعادة المحاولة
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="bg-white rounded-lg shadow-md">
        <div className="p-6 border-b border-gray-200">
          <h1 className="text-2xl font-bold text-gray-900">
            🚀 المحادثات المحسنة (نسخة مبسطة)
          </h1>
          <p className="text-gray-600 mt-2">
            تم تحميل {conversations.length} محادثة بنجاح
          </p>
        </div>

        <div className="divide-y divide-gray-200">
          {conversations.length === 0 ? (
            <div className="p-6 text-center text-gray-500">
              لا توجد محادثات متاحة
            </div>
          ) : (
            conversations.map((conversation) => (
              <div key={conversation.id} className="p-4 hover:bg-gray-50">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <h3 className="font-semibold text-gray-900">
                      {conversation.customerName}
                      {conversation.pageName && (
                        <span className="text-xs text-blue-600 font-medium bg-blue-50 px-1.5 py-0.5 rounded mr-2">
                          {conversation.pageName}
                        </span>
                      )}
                    </h3>
                    <p className="text-gray-600 text-sm mt-1">
                      {conversation.lastMessage}
                    </p>
                  </div>
                  <div className="text-right">
                    <div className="text-xs text-gray-500">
                      {conversation.lastMessageTime.toLocaleTimeString("ar-SA")}
                    </div>
                    {conversation.unreadCount > 0 && (
                      <div className="bg-blue-600 text-white text-xs rounded-full px-2 py-1 mt-1">
                        {conversation.unreadCount}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default ConversationsImprovedSimple;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";

interface Conversation {
  id: string;
  customerId: string;
  platform: string;
  status: string;
  lastMessage: string;
  lastMessageAt: string;
  messageCount: number;
  unreadCount: number;
  metadata: any;
  customerName?: string; // اسم العميل
  pageName?: string; // اسم صفحة الفيسبوك
  pageId?: string; // معرف صفحة الفيسبوك
}

interface Message {
  id: string;
  conversationId: string;
  content: string;
  type: string;
  direction: string;
  isFromCustomer: boolean;
  timestamp: string;
  status: string;
  metadata: any;
  isFacebookReply?: boolean; // إضافة معلومة الردود من فيسبوك
  facebookMessageId?: string; // إضافة معرف رسالة فيسبوك
}

const ConversationsSimple: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // تحميل المحادثات
  const loadConversations = async () => {
    try {
      console.log("🔄 Loading conversations...");
      const response = await apiClient.get("/conversations");

      const data = response.data;
      console.log("📊 API Response:", data);

      // Check if data is an array (direct response) or has success property
      if (Array.isArray(data)) {
        console.log("✅ Conversations loaded:", data.length, "conversations");
        setConversations(data);
        setError(null);
      } else if (data.success && data.data) {
        console.log("✅ Conversations loaded:", data.data);
        setConversations(data.data);
        setError(null);
      } else {
        console.error("❌ API returned unexpected format:", data);
        setError("تنسيق غير متوقع من الخادم");
      }
    } catch (error) {
      console.error("❌ Error loading conversations:", error);
      setError("خطأ في الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  // تحميل الرسائل
  const loadMessages = async (conversationId: string) => {
    try {
      console.log("🔄 Loading messages for conversation:", conversationId);
      const response = await apiClient.get(
        `/conversations/${conversationId}/messages`,
      );

      const data = response.data;
      console.log("📊 Messages Response:", data);

      // Check if data is an array (direct response) or has success property
      if (Array.isArray(data)) {
        console.log("✅ Messages loaded:", data.length, "messages");
        // تحويل الرسائل الحقيقية إلى تنسيق الواجهة مع إضافة خصائص فيسبوك
        const formattedMessages: Message[] = data.map((msg: any) => ({
          ...msg,
          isFacebookReply:
            msg.isFacebookReply || msg.metadata?.isFacebookReply || false, // Include Facebook reply flag
          facebookMessageId:
            msg.facebookMessageId || msg.metadata?.facebookMessageId || null, // Include Facebook message ID
        }));
        setMessages(formattedMessages);
      } else if (data.success && data.data) {
        console.log("✅ Messages loaded:", data.data);
        // تحويل الرسائل الحقيقية إلى تنسيق الواجهة مع إضافة خصائص فيسبوك
        const formattedMessages: Message[] = data.data.map((msg: any) => ({
          ...msg,
          isFacebookReply:
            msg.isFacebookReply || msg.metadata?.isFacebookReply || false, // Include Facebook reply flag
          facebookMessageId:
            msg.facebookMessageId || msg.metadata?.facebookMessageId || null, // Include Facebook message ID
        }));
        setMessages(formattedMessages);
      } else {
        console.error("❌ Failed to load messages:", data);
      }
    } catch (error) {
      console.error("❌ Error loading messages:", error);
    }
  };

  // إرسال رسالة
  const sendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;

    try {
      console.log("📤 Sending message:", newMessage);
      const response = await apiClient.post(
        `/conversations/${selectedConversation.id}/messages`,
        {
          message: newMessage,
        },
      );

      const data = response.data;
      console.log("📤 Send response:", data);

      setNewMessage("");
      // إعادة تحميل الرسائل
      loadMessages(selectedConversation.id);
    } catch (error) {
      console.error("❌ Error sending message:", error);
    }
  };

  // تحميل المحادثات عند بدء التطبيق
  useEffect(() => {
    loadConversations();
  }, []);

  // تحميل الرسائل عند اختيار محادثة
  useEffect(() => {
    if (selectedConversation) {
      loadMessages(selectedConversation.id);
    }
  }, [selectedConversation]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-600">جاري تحميل المحادثات...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="text-red-500 text-xl mb-4">❌</div>
          <p className="text-red-600 mb-4">{error}</p>
          <button
            onClick={loadConversations}
            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
          >
            إعادة المحاولة
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-gray-100">
      {/* قائمة المحادثات */}
      <div className="w-1/3 bg-white border-r border-gray-200">
        <div className="p-4 border-b border-gray-200">
          <h2 className="text-xl font-bold text-gray-800">
            المحادثات ({conversations.length})
          </h2>
        </div>

        <div className="overflow-y-auto h-full">
          {conversations.length === 0 ? (
            <div className="p-4 text-center text-gray-500">لا توجد محادثات</div>
          ) : (
            conversations.map((conversation) => (
              <div
                key={conversation.id}
                onClick={() => setSelectedConversation(conversation)}
                className={`p-4 border-b border-gray-100 cursor-pointer hover:bg-gray-50 ${
                  selectedConversation?.id === conversation.id
                    ? "bg-blue-50 border-blue-200"
                    : ""
                }`}
              >
                <div className="flex justify-between items-start mb-2">
                  <h3 className="font-medium text-gray-900">
                    {conversation.customerName || conversation.customerId}
                    {conversation.pageName && (
                      <span className="text-xs text-blue-600 font-medium bg-blue-50 px-1.5 py-0.5 rounded mr-2">
                        {conversation.pageName}
                      </span>
                    )}
                  </h3>
                  <span className="text-xs text-gray-500">
                    {conversation.platform}
                  </span>
                </div>
                <p className="text-sm text-gray-600 truncate">
                  {conversation.lastMessage || "لا توجد رسائل"}
                </p>
                <div className="flex justify-between items-center mt-2">
                  <span className="text-xs text-gray-400">
                    {new Date(conversation.lastMessageAt).toLocaleString(
                      "ar-EG",
                    )}
                  </span>
                  <span className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">
                    {conversation.messageCount} رسالة
                  </span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* منطقة الرسائل */}
      <div className="flex-1 flex flex-col">
        {selectedConversation ? (
          <>
            {/* رأس المحادثة */}
            <div className="bg-white border-b border-gray-200 p-4">
              <h3 className="font-bold text-lg text-gray-800">
                محادثة مع{" "}
                {selectedConversation.customerName ||
                  selectedConversation.customerId}
                {selectedConversation.pageName && (
                  <span className="text-sm text-blue-600 font-medium bg-blue-50 px-2 py-1 rounded mr-2">
                    {selectedConversation.pageName}
                  </span>
                )}
              </h3>
              <p className="text-sm text-gray-500">
                منصة: {selectedConversation.platform} | الحالة:{" "}
                {selectedConversation.status}
              </p>
            </div>

            {/* قائمة الرسائل */}
            <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
              {messages.length === 0 ? (
                <div className="text-center text-gray-500 mt-8">
                  لا توجد رسائل في هذه المحادثة
                </div>
              ) : (
                <div className="space-y-4">
                  {messages.map((message) => (
                    <div
                      key={message.id}
                      className={`flex ${
                        message.isFromCustomer ? "justify-start" : "justify-end"
                      }`}
                    >
                      <div
                        className={`max-w-xs lg:max-w-md px-4 py-2 rounded-lg ${
                          message.isFromCustomer
                            ? "bg-white border border-gray-200 text-gray-800"
                            : message.isFacebookReply
                              ? "bg-purple-100 border border-purple-200 text-purple-800" // نمط خاص للردود من فيسبوك
                              : "bg-blue-500 text-white"
                        }`}
                      >
                        {/* عرض أيقونة خاصة للردود من فيسبوك */}
                        {message.isFacebookReply && (
                          <div className="flex items-center mb-1">
                            <span className="text-xs font-bold text-purple-600">
                              رد من صفحتك على فيسبوك
                            </span>
                          </div>
                        )}
                        <p className="text-sm">{message.content}</p>
                        <p className="text-xs mt-1 opacity-70">
                          {new Date(message.timestamp).toLocaleString("ar-EG")}
                        </p>
                        {/* عرض معرف رسالة فيسبوك إذا كان متوفرًا */}
                        {message.facebookMessageId && (
                          <p className="text-xs mt-1 opacity-50">
                            معرف فيسبوك:{" "}
                            {message.facebookMessageId.substring(0, 10)}...
                          </p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* منطقة إرسال الرسائل */}
            <div className="bg-white border-t border-gray-200 p-4">
              <div className="flex">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyPress={(e) => e.key === "Enter" && sendMessage()}
                  placeholder="اكتب رسالتك هنا..."
                  className="flex-1 border border-gray-300 rounded-l-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  disabled={loading}
                />
                <button
                  onClick={sendMessage}
                  disabled={!newMessage.trim() || loading}
                  className="bg-blue-500 text-white px-6 py-2 rounded-r-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  إرسال
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center bg-gray-50">
            <div className="text-center">
              <div className="text-5xl mb-4">💬</div>
              <p className="text-gray-500">
                اختر محادثة من القائمة لعرض الرسائل
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ConversationsSimple;

import React, { useState, useEffect, useRef } from "react";
import {
  PaperAirplaneIcon,
  PaperClipIcon,
  ChatBubbleLeftRightIcon,
  InformationCircleIcon,
  MagnifyingGlassIcon,
  TrashIcon,
  CheckIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";
import apiService, {
  Message,
  Conversation,
  SavedReply,
  CustomerProfile as CustomerProfileType,
} from "../../services/apiService";
import { config } from "../../config";
import { tokenManager } from "../../utils/tokenManager";

const MOCK_CONVERSATIONS: Conversation[] = [
  {
    id: "mock-conversation-1",
    customerId: "mock-customer-1",
    customerName: "أحمد محمد",
    lastMessage: "مرحبا، أحتاج مساعدة",
    lastMessageTime: new Date(),
    status: "active",
    unreadCount: 2,
    platform: "facebook",
    messages: [],
  },
  {
    id: "mock-conversation-2",
    customerId: "mock-customer-2",
    customerName: "فاطمة علي",
    lastMessage: "شكرا لكم",
    lastMessageTime: new Date(),
    status: "active",
    unreadCount: 0,
    platform: "facebook",
    messages: [],
  },
];

const MOCK_SAVED_REPLIES: SavedReply[] = [
  {
    id: "1",
    title: "ترحيب",
    content: "مرحباً بك! كيف يمكنني مساعدتك اليوم؟",
    category: "welcome",
    createdAt: new Date(),
  },
  {
    id: "2",
    title: "شكر",
    content: "شكراً لتواصلك معنا. نقدر ثقتك بنا.",
    category: "thanks",
    createdAt: new Date(),
  },
  {
    id: "3",
    title: "اعتذار",
    content: "نعتذر عن أي إزعاج. سنعمل على حل المشكلة فوراً.",
    category: "apology",
    createdAt: new Date(),
  },
];

const buildMockMessages = (conversation: Conversation): Message[] => [
  {
    id: `${conversation.id}-incoming`,
    content: conversation.lastMessage,
    senderId: "customer",
    senderName: conversation.customerName,
    timestamp: new Date(),
    type: "text",
    isFromCustomer: true,
    status: "read",
    conversationId: conversation.id,
  },
];

const buildMockCustomerProfile = (
  customerId: string,
  customerName: string,
): CustomerProfileType => ({
  id: customerId,
  name: customerName || "عميل",
  email: "customer@example.com",
  phone: "+201234567890",
  avatar: undefined,
  totalOrders: 0,
  lastOrder: undefined,
  customerSince: new Date(),
  notes: "ملف تجريبي لعرض الصفحة عند عدم توفر بيانات حقيقية.",
  rating: "B",
});

const isMockConversation = (conversation: Conversation | null): boolean =>
  Boolean(
    conversation &&
    (conversation.id.startsWith("mock-") ||
      conversation.customerId.startsWith("mock-")),
  );

const MessengerChat: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [newMessage, setNewMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [sending, setSending] = useState(false);
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showSavedReplies, setShowSavedReplies] = useState(false);
  const [showCustomerProfile, setShowCustomerProfile] = useState(false);
  const [customerProfile, setCustomerProfile] =
    useState<CustomerProfileType | null>(null);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [conversationToDelete, setConversationToDelete] =
    useState<Conversation | null>(null);
  const [conversationFilter, setConversationFilter] = useState<
    "all" | "new" | "active" | "archived" | "important"
  >("all");
  const [savedReplies, setSavedReplies] = useState<SavedReply[]>([]);
  const [expandedMessages, setExpandedMessages] = useState<Set<string>>(
    new Set(),
  );
  const [usingMockConversations, setUsingMockConversations] = useState(false);

  useEffect(() => {
    loadConversations();
    loadSavedReplies();
  }, []);

  // Load messages when conversation changes
  useEffect(() => {
    if (selectedConversation) {
      if (usingMockConversations || isMockConversation(selectedConversation)) {
        setMessages(buildMockMessages(selectedConversation));
        setCustomerProfile(
          buildMockCustomerProfile(
            selectedConversation.customerId,
            selectedConversation.customerName,
          ),
        );
        return;
      }

      loadMessages(selectedConversation.id);
      if (selectedConversation.customerId) {
        loadCustomerProfile(selectedConversation.customerId);
      }
    }
  }, [selectedConversation, usingMockConversations]);

  // Auto-refresh messages every 5 seconds for the selected conversation
  useEffect(() => {
    if (selectedConversation && !usingMockConversations) {
      const interval = setInterval(() => {
        loadMessages(selectedConversation.id);
      }, 5000);

      return () => clearInterval(interval);
    }
  }, [selectedConversation, usingMockConversations]);

  const loadConversations = async () => {
    try {
      setLoading(true);
      const fetchedConversations = await apiService.getConversations();
      if (Array.isArray(fetchedConversations)) {
        setConversations(fetchedConversations);
        setUsingMockConversations(false);
        if (fetchedConversations.length > 0) {
          setSelectedConversation(fetchedConversations[0]);
        }
      } else {
        setUsingMockConversations(true);
        setConversations(MOCK_CONVERSATIONS);
        setSelectedConversation(MOCK_CONVERSATIONS[0]);
      }
    } catch (error) {
      setUsingMockConversations(true);
      setConversations(MOCK_CONVERSATIONS);
      setSelectedConversation(MOCK_CONVERSATIONS[0]);
    } finally {
      setLoading(false);
    }
  };

  const loadMessages = async (conversationId: string) => {
    try {
      const realMessages = await apiService.getMessages(conversationId);

      // تحويل الرسائل الحقيقية إلى تنسيق الواجهة
      const formattedMessages: Message[] = realMessages.map((msg: any) => ({
        id: msg.id,
        content: msg.content,
        senderId: msg.sender?.id || (msg.isFromCustomer ? "customer" : "agent"),
        senderName:
          msg.sender?.name || (msg.isFromCustomer ? "العميل" : "المندوب"),
        timestamp: new Date(msg.timestamp),
        status: "read",
        type: msg.type || "text",
        conversationId: conversationId,
        isFromCustomer: msg.isFromCustomer,
        repliedBy: msg.isFromCustomer
          ? undefined
          : msg.sender?.name || "المندوب",
        attachments: msg.attachments || [],
        isFacebookReply: msg.isFacebookReply || false, // Include Facebook reply flag
        facebookMessageId: msg.facebookMessageId || null, // Include Facebook message ID
      }));

      setMessages(formattedMessages);
    } catch (error) {
      setMessages([]);
    }
  };

  const loadSavedReplies = async () => {
    try {
      const fetchedReplies = await apiService.getSavedReplies();
      if (Array.isArray(fetchedReplies) && fetchedReplies.length > 0) {
        setSavedReplies(fetchedReplies);
      } else {
        setSavedReplies(MOCK_SAVED_REPLIES);
      }
    } catch (error) {
      setSavedReplies(MOCK_SAVED_REPLIES);
    }
  };

  const loadCustomerProfile = async (customerId: string) => {
    try {
      const profile = await apiService.getCustomerProfile(customerId);
      setCustomerProfile(
        profile ||
          buildMockCustomerProfile(
            customerId,
            selectedConversation?.customerName || "عميل",
          ),
      );
    } catch (error) {
      setCustomerProfile(
        buildMockCustomerProfile(
          customerId,
          selectedConversation?.customerName || "عميل",
        ),
      );
    }
  };

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;

    // إنشاء معرف مؤقت للرسالة خارج try-catch
    const tempMessageId = Date.now().toString();
    const messageContent = newMessage.trim();

    try {
      if (!selectedConversation) return;

      setSending(true);

      const messageToSend: Omit<Message, "id" | "timestamp" | "status"> = {
        content: messageContent,
        senderId: "agent1",
        senderName: "أنت",
        type: "text",
        isFromCustomer: false,
        conversationId: selectedConversation.id,
      };

      // إضافة الرسالة محلياً
      const tempMessage: Message = {
        ...messageToSend,
        id: tempMessageId,
        timestamp: new Date(),
        status: "sending",
      };

      setMessages((prev) => [...prev, tempMessage]);
      setNewMessage("");

      if (usingMockConversations) {
        const mockSavedMessage: Message = {
          ...tempMessage,
          status: "sent",
        };

        setMessages((prev) =>
          prev.map((msg) =>
            msg.id === tempMessageId ? mockSavedMessage : msg,
          ),
        );
        return;
      }

      // إرسال الرسالة للخادم
      const token = tokenManager.getAccessToken();
      const response = await fetch(
        `${config.apiUrl}/conversations/${selectedConversation.id}/messages`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ message: messageContent }),
        },
      );

      if (response.ok) {
        const payload = await response.json().catch(() => null);
        const savedMessage = payload?.data ?? payload;
        setMessages((prev) =>
          prev.map((msg) =>
            msg.id === tempMessageId
              ? {
                  ...msg,
                  ...savedMessage,
                  content: savedMessage?.content ?? messageContent,
                  status: "sent",
                }
              : msg,
          ),
        );
      } else {
        throw new Error("فشل في إرسال الرسالة");
      }
    } catch (error) {
      console.error("خطأ في إرسال الرسالة:", error);
      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === tempMessageId ? { ...msg, status: "error" } : msg,
        ),
      );
    } finally {
      setSending(false);
    }
  };

  const handleDeleteConversation = async (conversation: Conversation) => {
    try {
      await apiService.deleteConversation(conversation.id);
      setConversations((prev) =>
        prev.filter((conv) => conv.id !== conversation.id),
      );
      if (selectedConversation?.id === conversation.id) {
        setSelectedConversation(null);
        setMessages([]);
      }
      setShowDeleteModal(false);
    } catch (error) {
      console.error("Error deleting conversation:", error);
    }
  };

  const handleSelectConversation = (conversation: Conversation) => {
    setSelectedConversation(conversation);
  };

  const useSavedReply = (reply: SavedReply) => {
    setNewMessage(reply.content);
    setShowSavedReplies(false);
  };

  const handleFileUpload = async (file: File) => {
    if (!selectedConversation) return;

    try {
      // محاكاة رفع الملف
      const fileUrl = URL.createObjectURL(file);
      const messageToSend: Partial<Message> = {
        content: file.name,
        senderId: "currentUserId", // يجب استبدال هذا بمعرف المستخدم الفعلي
        senderName: "أنت",
        timestamp: new Date(),
        status: "sent",
        type: "image", // نوع الرسالة سيكون صورة
        conversationId: selectedConversation.id,
        isFromCustomer: false,
        repliedBy: "أنت",
        fileUrl: fileUrl,
        fileName: file.name,
        fileSize: file.size,
      };

      // تحديث الواجهة فوراً
      setMessages((prev) => [...prev, messageToSend as Message]);
      // سيتم إرسال الرسالة عبر WebSocket عند تنفيذ التكامل الحقيقي

      // إغلاق مربع اختيار الملف
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    } catch (error) {
      console.error("Error uploading file:", error);
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const toggleMessageExpansion = (messageId: string) => {
    setExpandedMessages((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(messageId)) {
        newSet.delete(messageId);
      } else {
        newSet.add(messageId);
      }
      return newSet;
    });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const filteredConversations = Array.isArray(conversations)
    ? conversations.filter((conv: Conversation) => {
        const matchesSearch =
          conv.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
          conv.lastMessage.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesFilter =
          conversationFilter === "all" || conv.status === conversationFilter;
        return matchesSearch && matchesFilter;
      })
    : [];

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      {/* قائمة المحادثات */}
      <div className="w-80 bg-white border-l border-gray-200 flex flex-col">
        <div className="p-4 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-gray-900">المحادثات</h2>

          <div className="mt-3 relative">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
            <input
              type="text"
              placeholder="ابحث عن محادثة..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>

          <div className="mt-3 flex gap-1">
            {(["all", "new", "active", "archived", "important"] as const).map(
              (filter) => (
                <button
                  key={filter}
                  onClick={() => setConversationFilter(filter)}
                  className={`px-3 py-1 text-xs rounded-full ${
                    conversationFilter === filter
                      ? "bg-blue-500 text-white"
                      : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                  }`}
                >
                  {filter === "all"
                    ? "الكل"
                    : filter === "new"
                      ? "جديد"
                      : filter === "active"
                        ? "نشط"
                        : filter === "archived"
                          ? "مؤرشف"
                          : "مهم"}
                </button>
              ),
            )}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="p-4 text-center text-gray-500">جاري التحميل...</div>
          ) : (
            filteredConversations.map((conversation) => (
              <div
                key={conversation.id}
                onClick={() => handleSelectConversation(conversation)}
                className={`p-4 border-b border-gray-100 cursor-pointer hover:bg-gray-50 ${
                  selectedConversation?.id === conversation.id
                    ? "bg-blue-50"
                    : ""
                }`}
              >
                <div className="flex items-center">
                  {conversation.customerAvatar ? (
                    <img
                      src={conversation.customerAvatar}
                      alt={conversation.customerName}
                      className="w-10 h-10 rounded-full"
                    />
                  ) : (
                    <div className="w-10 h-10 rounded-full bg-gray-300 flex items-center justify-center">
                      <span className="text-gray-600 text-sm font-medium">
                        {conversation.customerName.charAt(0)}
                      </span>
                    </div>
                  )}
                  <div className="ml-3 flex-1 min-w-0">
                    <div className="flex justify-between items-baseline">
                      <h3 className="text-sm font-medium text-gray-900 truncate">
                        {conversation.customerName}
                        {conversation.pageName && (
                          <span className="text-xs text-blue-600 font-medium bg-blue-50 px-1.5 py-0.5 rounded mr-2">
                            {conversation.pageName}
                          </span>
                        )}
                      </h3>
                      <span className="text-xs text-gray-500">
                        {conversation.lastMessageTime
                          ? new Date(
                              conversation.lastMessageTime,
                            ).toLocaleTimeString([], {
                              hour: "2-digit",
                              minute: "2-digit",
                            })
                          : "الآن"}
                      </span>
                    </div>
                    <p className="text-sm text-gray-500 truncate">
                      {conversation.lastMessage}
                    </p>
                    <div className="flex justify-between items-center mt-1">
                      <span
                        className={`text-xs px-2 py-1 rounded-full ${
                          conversation.status === "new"
                            ? "bg-green-100 text-green-800"
                            : conversation.status === "active"
                              ? "bg-blue-100 text-blue-800"
                              : conversation.status === "archived"
                                ? "bg-gray-100 text-gray-800"
                                : "bg-yellow-100 text-yellow-800"
                        }`}
                      >
                        {conversation.status === "new"
                          ? "جديد"
                          : conversation.status === "active"
                            ? "نشط"
                            : conversation.status === "archived"
                              ? "مؤرشف"
                              : "مهم"}
                      </span>
                      {conversation.isOnline && (
                        <span className="ml-2 w-2 h-2 bg-green-500 rounded-full"></span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* منطقة المحادثة */}
      <div className="flex-1 flex flex-col min-h-0">
        {selectedConversation ? (
          <>
            <div className="bg-white border-b border-gray-200 p-4 flex justify-between items-center">
              <div className="flex items-center">
                {selectedConversation.customerAvatar ? (
                  <img
                    src={selectedConversation.customerAvatar}
                    alt={selectedConversation.customerName}
                    className="w-10 h-10 rounded-full"
                  />
                ) : (
                  <div className="w-10 h-10 rounded-full bg-gray-300 flex items-center justify-center">
                    <span className="text-gray-600 text-sm font-medium">
                      {selectedConversation.customerName.charAt(0)}
                    </span>
                  </div>
                )}
                <div className="ml-3">
                  <h3 className="text-sm font-medium text-gray-900">
                    {selectedConversation.customerName}
                  </h3>
                  <p className="text-sm text-gray-500">
                    {selectedConversation.isOnline ? "نشط الآن" : "غير متصل"}
                  </p>
                </div>
              </div>
              <div className="flex items-center space-x-2 space-x-reverse">
                <button
                  onClick={() => setShowCustomerProfile(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <InformationCircleIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => setShowSavedReplies(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <ChatBubbleLeftRightIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <PaperClipIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => {
                    setConversationToDelete(selectedConversation);
                    setShowDeleteModal(true);
                  }}
                  className="p-2 text-gray-400 hover:text-red-600"
                >
                  <TrashIcon className="h-5 w-5" />
                </button>
              </div>
            </div>

            <div
              ref={messagesContainerRef}
              className="flex-1 overflow-y-auto overflow-x-hidden p-4 bg-gray-50"
              style={{ minHeight: 0, height: "auto" }}
              onScroll={() => {
                // يمكن إضافة تحميل الرسائل القديمة عند التمرير لأعلى
              }}
            >
              <div className="space-y-4 w-full">
                {messages.map((message) => (
                  <div
                    key={message.id}
                    className={`flex w-full ${message.isFromCustomer ? "justify-start" : "justify-end"}`}
                  >
                    <div
                      className={`max-w-xs sm:max-w-sm md:max-w-md lg:max-w-lg xl:max-w-2xl 2xl:max-w-4xl px-4 py-2 rounded-lg min-h-fit ${
                        message.isFromCustomer
                          ? "bg-white border border-gray-200"
                          : "bg-blue-500 text-white"
                      }`}
                      style={{
                        maxHeight: "none",
                        height: "auto",
                        overflow: "visible",
                      }}
                    >
                      {message.type === "image" && message.fileUrl && (
                        <div className="mb-2">
                          <img
                            src={getImageUrl(message)}
                            alt={message.fileName}
                            className="rounded-lg max-h-48 object-cover"
                          />
                        </div>
                      )}
                      {message.type === "voice" && message.fileUrl && (
                        <div className="mb-2">
                          <audio controls className="w-full">
                            <source src={message.fileUrl} type="audio/mpeg" />
                            متصفحك لا يدعم عنصر الصوت.
                          </audio>
                        </div>
                      )}
                      <div
                        className="text-sm whitespace-pre-wrap break-words leading-relaxed overflow-visible w-full"
                        style={{
                          wordBreak: "break-word",
                          overflowWrap: "break-word",
                          hyphens: "auto",
                          maxHeight: "none",
                          height: "auto",
                          textOverflow: "clip",
                          overflow: "visible",
                          display: "block",
                        }}
                      >
                        {message.content.length > 500 &&
                        !expandedMessages.has(message.id)
                          ? message.content.substring(0, 500) + "..."
                          : message.content}
                        {message.content.length > 500 && (
                          <button
                            onClick={() => toggleMessageExpansion(message.id)}
                            className="text-xs text-blue-400 hover:text-blue-600 mt-1 block"
                          >
                            {expandedMessages.has(message.id)
                              ? "إخفاء"
                              : "عرض المزيد"}
                          </button>
                        )}
                      </div>
                      <div className="flex justify-between items-center mt-1">
                        <span className="text-xs opacity-70">
                          {message.timestamp.toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </span>
                        {!message.isFromCustomer && (
                          <span className="text-xs opacity-70 mr-1">
                            {message.status === "sent"
                              ? "✓"
                              : message.status === "delivered"
                                ? "✓✓"
                                : "👁"}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
                {typingUsers.length > 0 && (
                  <div className="flex justify-start">
                    <div className="bg-white border border-gray-200 px-4 py-2 rounded-lg">
                      <div className="flex space-x-1">
                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                        <div
                          className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"
                          style={{ animationDelay: "0.2s" }}
                        ></div>
                        <div
                          className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"
                          style={{ animationDelay: "0.4s" }}
                        ></div>
                      </div>
                    </div>
                  </div>
                )}
                <div ref={messagesEndRef} />
              </div>
            </div>

            <div className="bg-white border-t border-gray-200 p-4">
              <div className="flex items-center">
                <button
                  onClick={() => setShowSavedReplies(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <ChatBubbleLeftRightIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <PaperClipIcon className="h-5 w-5" />
                </button>
                <input
                  type="file"
                  ref={fileInputRef}
                  className="hidden"
                  accept="image/*,audio/*,video/*"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      handleFileUpload(file);
                    }
                  }}
                />
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyPress={(e) =>
                    e.key === "Enter" && !e.shiftKey && handleSendMessage()
                  }
                  placeholder="اكتب رسالتك..."
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                <button
                  onClick={() => handleSendMessage()}
                  disabled={!newMessage.trim() || sending}
                  className="p-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <PaperAirplaneIcon className="h-5 w-5" />
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center bg-gray-50">
            <div className="text-center">
              <ChatBubbleLeftRightIcon className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-500">اختر محادثة للبدء</p>
            </div>
          </div>
        )}
      </div>

      {/* مكون الردود المحفوظة */}
      {showSavedReplies && (
        <SavedReplies
          replies={savedReplies}
          onClose={() => setShowSavedReplies(false)}
          onUseReply={(reply: SavedReply) => {
            setNewMessage(reply.content);
            setShowSavedReplies(false);
          }}
        />
      )}

      {/* مكون ملف العميل */}
      {showCustomerProfile && customerProfile && selectedConversation && (
        <CustomerProfile
          customerId={selectedConversation.customerId}
          isOpen={showCustomerProfile}
          onClose={() => setShowCustomerProfile(false)}
        />
      )}

      {/* مودال حذف المحادثة */}
      {showDeleteModal && conversationToDelete && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-sm mx-4">
            <h3 className="text-lg font-medium text-gray-900 mb-4">
              تأكيد الحذف
            </h3>
            <p className="text-gray-600 mb-6">
              هل أنت متأكد من حذف محادثة {conversationToDelete.customerName}؟
            </p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setShowDeleteModal(false)}
                className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200"
              >
                إلغاء
              </button>
              <button
                onClick={() => handleDeleteConversation(conversationToDelete)}
                className="px-4 py-2 text-white bg-red-500 rounded-lg hover:bg-red-600"
              >
                حذف
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MessengerChat;

import React, { useState, useEffect, useRef } from "react";
import {
  MagnifyingGlassIcon,
  PaperAirplaneIcon,
  XMarkIcon,
  ChatBubbleLeftRightIcon,
  ArchiveBoxIcon,
  TrashIcon,
  EyeIcon,
  InformationCircleIcon,
  ShoppingCartIcon,
  PaperClipIcon,
  FaceSmileIcon,
} from "@heroicons/react/24/outline";
import { CheckIcon } from "@heroicons/react/24/solid";
import SavedReplies from "../../components/conversations/SavedReplies";
import CustomerProfile from "../../components/conversations/CustomerProfile";
import { socketService } from "../../services/socketService";

// Types
interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type: "text" | "image" | "file" | "voice";
  isFromCustomer: boolean;
  status: "sending" | "sent" | "delivered" | "read" | "error";
  conversationId: string;
  fileUrl?: string;
  fileName?: string;
  fileSize?: number;
  voiceDuration?: number;
  repliedBy?: string;
}

interface Conversation {
  id: string;
  customerId: string;
  customerName: string;
  customerAvatar?: string;
  customerEmail?: string;
  customerPhone?: string;
  lastMessage: string;
  lastMessageTime: Date;
  unreadCount: number;
  isOnline?: boolean;
  platform: "facebook" | "whatsapp" | "telegram" | "unknown";
  status: "new" | "active" | "archived" | "important";
  messages: Message[];
  customerOrders?: any[];
  lastRepliedBy?: string;
  pageName?: string; // اسم صفحة الفيسبوك
  pageId?: string; // معرف صفحة الفيسبوك
}

interface SavedReply {
  id: string;
  title: string;
  content: string;
  category:
    | "welcome"
    | "thanks"
    | "apology"
    | "followup"
    | "closing"
    | "custom";
  createdAt: Date;
}

interface CustomerProfile {
  id: string;
  name: string;
  avatar?: string;
  email?: string;
  phone?: string;
  totalOrders: number;
  lastOrder?: any;
  customerSince: Date;
  notes?: string;
}

const MessengerChat: React.FC = () => {
  // الحالات الأساسية
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(true);
  const [newMessage, setNewMessage] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [sending, setSending] = useState(false);

  // المراجع
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // حالات إضافية
  const [showSavedReplies, setShowSavedReplies] = useState(false);
  const [savedReplies, setSavedReplies] = useState<SavedReply[]>([]);
  const [showCustomerProfile, setShowCustomerProfile] = useState(false);
  const [customerProfile, setCustomerProfile] =
    useState<CustomerProfile | null>(null);
  const [searchResults, setSearchResults] = useState<string[]>([]);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [conversationToDelete, setConversationToDelete] =
    useState<Conversation | null>(null);

  // تصنيف المحادثات
  const [conversationFilter, setConversationFilter] = useState<
    "all" | "new" | "active" | "archived" | "important"
  >("all");

  // تحميل المحادثات
  const loadConversations = async () => {
    try {
      setLoading(true);
      // محاكاة تحميل البيانات
      const mockConversations: Conversation[] = [
        {
          id: "1",
          customerId: "customer1",
          customerName: "أحمد محمد",
          lastMessage: "شكراً لك على المساعدة!",
          lastMessageTime: new Date(),
          unreadCount: 2,
          status: "active",
          platform: "facebook",
          messages: [],
          customerOrders: [],
        },
        {
          id: "2",
          customerId: "customer2",
          customerName: "سارة أحمد",
          lastMessage: "هل يمكنني معرفة حالة طلبي؟",
          lastMessageTime: new Date(Date.now() - 3600000),
          unreadCount: 0,
          status: "new",
          platform: "facebook",
          messages: [],
          customerOrders: [],
        },
      ];
      setConversations(mockConversations);
    } catch (error) {
      console.error("Error loading conversations:", error);
    } finally {
      setLoading(false);
    }
  };

  // تحميل الرسائل
  const loadMessages = async (conversationId: string) => {
    try {
      // محاكاة تحميل الرسائل
      const mockMessages: Message[] = [
        {
          id: "1",
          content: "مرحباً، كيف يمكنني مساعدتك؟",
          senderId: "user1",
          senderName: "أنت",
          timestamp: new Date(Date.now() - 7200000),
          status: "read",
          type: "text",
          conversationId: conversationId,
          isFromCustomer: false,
          repliedBy: "أنت",
        },
        {
          id: "2",
          content: "أريد الاستفسار عن منتج معين",
          senderId: "customer1",
          senderName: "أحمد محمد",
          timestamp: new Date(Date.now() - 3600000),
          status: "read",
          type: "text",
          conversationId: conversationId,
          isFromCustomer: true,
        },
        {
          id: "3",
          content: "بالطبع، أي منتج تريد؟",
          senderId: "user1",
          senderName: "أنت",
          timestamp: new Date(Date.now() - 1800000),
          status: "delivered",
          type: "text",
          conversationId: conversationId,
          isFromCustomer: false,
          repliedBy: "أنت",
        },
      ];
      setMessages(mockMessages);
    } catch (error) {
      console.error("Error loading messages:", error);
    }
  };

  // إرسال رسالة
  const handleSendMessage = async (
    content: string,
    type: "text" | "image" | "voice" = "text",
  ) => {
    if (!content.trim() || !selectedConversation) return;

    setSending(true);
    try {
      const message: Message = {
        id: Date.now().toString(),
        content: content,
        senderId: "user1",
        senderName: "أنت",
        timestamp: new Date(),
        type: type,
        status: "sent",
        conversationId: selectedConversation.id,
        isFromCustomer: false,
        repliedBy: "أنت",
      };

      setMessages((prev) => [...prev, message]);
      setNewMessage("");

      // إرسال عبر WebSocket
      socketService.sendMessage({
        conversationId: selectedConversation.id,
        text: content,
        type: type,
      });

      // تحديث حالة المحادثة
      setConversations((prev) =>
        prev.map((conv) =>
          conv.id === selectedConversation.id
            ? { ...conv, lastMessage: content, lastMessageTime: new Date() }
            : conv,
        ),
      );
    } catch (error) {
      console.error("Error sending message:", error);
    } finally {
      setSending(false);
    }
  };

  // حذف محادثة
  const handleDeleteConversation = async (conversation: Conversation) => {
    try {
      setConversations((prev) => prev.filter((c) => c.id !== conversation.id));
      if (selectedConversation?.id === conversation.id) {
        setSelectedConversation(null);
        setMessages([]);
      }
      setShowDeleteModal(false);
    } catch (error) {
      console.error("Error deleting conversation:", error);
    }
  };

  // تحميل الردود المحفوظة
  const loadSavedReplies = async () => {
    try {
      const mockReplies: SavedReply[] = [
        {
          id: "1",
          title: "ترحيب",
          content: "مرحباً بك! كيف يمكنني مساعدتك اليوم؟",
          category: "welcome",
          createdAt: new Date(),
        },
        {
          id: "2",
          title: "شكر",
          content: "شكراً لتواصلك معنا!",
          category: "thanks",
          createdAt: new Date(),
        },
        {
          id: "3",
          title: "اعتذار",
          content: "نأسف للإزعاج، سنعمل على حل المشكلة فوراً",
          category: "apology",
          createdAt: new Date(),
        },
      ];
      setSavedReplies(mockReplies);
    } catch (error) {
      console.error("Error loading saved replies:", error);
    }
  };

  // استخدام الرد المحفوظ
  const useSavedReply = (reply: SavedReply) => {
    handleSendMessage(reply.content, "text");
    setShowSavedReplies(false);
  };

  // البحث في المحادثات
  const searchInChat = (query: string) => {
    if (query.trim()) {
      const results = messages
        .filter((msg) =>
          msg.content.toLowerCase().includes(query.toLowerCase()),
        )
        .map((msg) => msg.content);
      setSearchResults(results);
    } else {
      setSearchResults([]);
    }
  };

  // تصفية المحادثات
  const filteredConversations = conversations.filter((conv) => {
    const matchesSearch = conv.customerName
      .toLowerCase()
      .includes(searchQuery.toLowerCase());
    const matchesFilter =
      conversationFilter === "all" || conv.status === conversationFilter;
    return matchesSearch && matchesFilter;
  });

  // تمرير إلى آخر رسالة
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // تحميل البيانات عند التحميل
  useEffect(() => {
    loadConversations();
    loadSavedReplies();

    // إعداد WebSocket
    socketService.onMessage((message: any) => {
      setMessages((prev) => [...prev, message]);
    });

    return () => {
      socketService.disconnect();
    };
  }, []);

  // تحميل الرسائل عند تغيير المحادثة
  useEffect(() => {
    if (selectedConversation) {
      loadMessages(selectedConversation.id);
      const mockCustomerProfile: CustomerProfile = {
        id: selectedConversation.customerId,
        name: selectedConversation.customerName,
        totalOrders: 5,
        customerSince: new Date("2023-01-01"),
        email: "customer@example.com",
        phone: "+1234567890",
      };
      setCustomerProfile(mockCustomerProfile);
    }
  }, [selectedConversation]);

  return (
    <div className="flex h-screen bg-gray-50">
      {/* قائمة المحادثات */}
      <div className="w-80 bg-white border-l border-gray-200 flex flex-col">
        {/* رأس القائمة */}
        <div className="p-4 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-gray-900">المحادثات</h2>

          {/* البحث */}
          <div className="mt-3 relative">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
            <input
              type="text"
              placeholder="ابحث عن محادثة..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>

          {/* تصفية المحادثات */}
          <div className="mt-3 flex gap-2">
            {(["all", "new", "active", "important"] as const).map((filter) => (
              <button
                key={filter}
                onClick={() => setConversationFilter(filter)}
                className={`px-3 py-1 text-sm rounded-full ${
                  conversationFilter === filter
                    ? "bg-blue-500 text-white"
                    : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                }`}
              >
                {filter === "all"
                  ? "الكل"
                  : filter === "new"
                    ? "جديد"
                    : filter === "active"
                      ? "نشط"
                      : "مهم"}
              </button>
            ))}
          </div>
        </div>

        {/* قائمة المحادثات */}
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="p-4 text-center text-gray-500">جاري التحميل...</div>
          ) : (
            filteredConversations.map((conversation) => (
              <div
                key={conversation.id}
                onClick={() => setSelectedConversation(conversation)}
                className={`p-4 border-b border-gray-100 cursor-pointer hover:bg-gray-50 ${
                  selectedConversation?.id === conversation.id
                    ? "bg-blue-50"
                    : ""
                }`}
              >
                <div className="flex items-center">
                  <img
                    src={
                      conversation.customerAvatar || "/api/placeholder/40/40"
                    }
                    alt={conversation.customerName}
                    className="w-10 h-10 rounded-full"
                  />
                  <div className="mr-3 flex-1">
                    <div className="flex justify-between items-center">
                      <h3 className="font-medium text-gray-900">
                        {conversation.customerName}
                        {conversation.pageName && (
                          <span className="text-xs text-blue-600 font-medium bg-blue-50 px-1.5 py-0.5 rounded mr-2">
                            {conversation.pageName}
                          </span>
                        )}
                      </h3>
                      <span className="text-xs text-gray-500">
                        {new Date(
                          conversation.lastMessageTime,
                        ).toLocaleTimeString("ar-SA")}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 truncate">
                      {conversation.lastMessage}
                    </p>
                    <div className="flex items-center mt-1">
                      {conversation.unreadCount > 0 && (
                        <span className="bg-blue-500 text-white text-xs rounded-full px-2 py-1">
                          {conversation.unreadCount}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* منطقة المحادثة */}
      <div className="flex-1 flex flex-col">
        {selectedConversation ? (
          <>
            {/* رأس المحادثة */}
            <div className="bg-white border-b border-gray-200 p-4 flex justify-between items-center">
              <div className="flex items-center">
                <img
                  src={
                    selectedConversation.customerAvatar ||
                    "/api/placeholder/40/40"
                  }
                  alt={selectedConversation.customerName}
                  className="w-10 h-10 rounded-full"
                />
                <div className="mr-3">
                  <h3 className="font-medium text-gray-900">
                    {selectedConversation.customerName}
                  </h3>
                  <p className="text-sm text-gray-500">نشط الآن</p>
                </div>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => setShowCustomerProfile(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <InformationCircleIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => setShowOrderModal(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <ShoppingCartIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => {
                    setConversationToDelete(selectedConversation);
                    setShowDeleteModal(true);
                  }}
                  className="p-2 text-gray-400 hover:text-red-600"
                >
                  <TrashIcon className="h-5 w-5" />
                </button>
              </div>
            </div>

            {/* منطقة الرسائل */}
            <div
              className="flex-1 overflow-y-auto p-4 space-y-4"
              ref={messagesContainerRef}
            >
              {messages.map((message) => (
                <div
                  key={message.id}
                  className={`flex ${message.isFromCustomer ? "justify-start" : "justify-end"}`}
                >
                  <div
                    className={`max-w-xs lg:max-w-md px-4 py-2 rounded-lg ${
                      message.isFromCustomer
                        ? "bg-gray-100 text-gray-900"
                        : "bg-blue-500 text-white"
                    }`}
                  >
                    {message.type === "image" && message.fileUrl && (
                      <img
                        src={message.fileUrl}
                        alt="صورة"
                        className="rounded-lg max-w-full"
                      />
                    )}
                    {message.type === "text" && <p>{message.content}</p>}

                    <div className="flex items-center mt-1">
                      <span className="text-xs opacity-75">
                        {new Date(message.timestamp).toLocaleTimeString(
                          "ar-SA",
                        )}
                      </span>
                      {!message.isFromCustomer && (
                        <div className="mr-1">
                          {message.status === "sent" && (
                            <CheckIcon className="h-3 w-3" />
                          )}
                          {message.status === "delivered" && (
                            <div className="flex">
                              <CheckIcon className="h-3 w-3" />
                              <CheckIcon className="h-3 w-3 -mr-1" />
                            </div>
                          )}
                          {message.status === "read" && (
                            <div className="flex text-blue-300">
                              <CheckIcon className="h-3 w-3" />
                              <CheckIcon className="h-3 w-3 -mr-1" />
                            </div>
                          )}
                        </div>
                      )}
                    </div>

                    {message.repliedBy && message.isFromCustomer && (
                      <p className="text-xs mt-1 opacity-75">
                        تم الرد بواسطة: {message.repliedBy}
                      </p>
                    )}
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            {/* منطقة الإدخال */}
            <div className="bg-white border-t border-gray-200 p-4">
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setShowSavedReplies(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <ChatBubbleLeftRightIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <PaperClipIcon className="h-5 w-5" />
                </button>
                <input
                  type="file"
                  ref={fileInputRef}
                  className="hidden"
                  accept="image/*"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      // معالجة رفع الملف
                      console.log("Uploading file:", file.name);
                    }
                  }}
                />
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyPress={(e) =>
                    e.key === "Enter" &&
                    !e.shiftKey &&
                    handleSendMessage(newMessage)
                  }
                  placeholder="اكتب رسالتك..."
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                <button
                  onClick={() => handleSendMessage(newMessage)}
                  disabled={!newMessage.trim() || sending}
                  className="p-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <PaperAirplaneIcon className="h-5 w-5" />
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center bg-gray-50">
            <div className="text-center">
              <ChatBubbleLeftRightIcon className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-500">اختر محادثة للبدء</p>
            </div>
          </div>
        )}
      </div>

      {/* مكون الردود المحفوظة */}
      {showSavedReplies && (
        <SavedReplies
          replies={savedReplies}
          onClose={() => setShowSavedReplies(false)}
          onUseReply={useSavedReply}
        />
      )}

      {/* مكون ملف العميل */}
      {showCustomerProfile && customerProfile && (
        <CustomerProfile
          customer={customerProfile}
          onClose={() => setShowCustomerProfile(false)}
        />
      )}

      {/* مودال حذف المحادثة */}
      {showDeleteModal && conversationToDelete && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-sm mx-4">
            <h3 className="text-lg font-medium text-gray-900 mb-4">
              تأكيد الحذف
            </h3>
            <p className="text-gray-600 mb-6">
              هل أنت متأكد من حذف محادثة {conversationToDelete.customerName}؟
            </p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setShowDeleteModal(false)}
                className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200"
              >
                إلغاء
              </button>
              <button
                onClick={() => handleDeleteConversation(conversationToDelete)}
                className="px-4 py-2 text-white bg-red-500 rounded-lg hover:bg-red-600"
              >
                حذف
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MessengerChat;

import React, { useState, useEffect, useRef } from "react";
import {
  MagnifyingGlassIcon,
  PaperAirplaneIcon,
  XMarkIcon,
  ChatBubbleLeftRightIcon,
  ArchiveBoxIcon,
  TrashIcon,
  EyeIcon,
  InformationCircleIcon,
  ShoppingCartIcon,
  PaperClipIcon,
  FaceSmileIcon,
} from "@heroicons/react/24/outline";
import { CheckIcon } from "@heroicons/react/24/solid";
import SavedReplies from "../../components/conversations/SavedReplies";
import CustomerProfile from "../../components/conversations/CustomerProfile";
import { socketService } from "../../services/socketService";
import { uploadService } from "../../services/uploadService";

// Types
interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type: "text" | "image" | "file" | "voice";
  isFromCustomer: boolean;
  status: "sending" | "sent" | "delivered" | "read" | "error";
  conversationId: string;
  fileUrl?: string;
  fileName?: string;
  fileSize?: number;
  voiceDuration?: number;
  repliedBy?: string;
}

interface Conversation {
  id: string;
  customerId: string;
  customerName: string;
  customerAvatar?: string;
  customerEmail?: string;
  customerPhone?: string;
  lastMessage: string;
  lastMessageTime: Date;
  unreadCount: number;
  isOnline?: boolean;
  platform: "facebook" | "whatsapp" | "telegram" | "unknown";
  status: "new" | "active" | "archived" | "important";
  messages: Message[];
  customerOrders?: any[];
  lastRepliedBy?: string;
  pageName?: string; // اسم صفحة الفيسبوك
  pageId?: string; // معرف صفحة الفيسبوك
}

interface SavedReply {
  id: string;
  title: string;
  content: string;
  category:
    | "welcome"
    | "thanks"
    | "apology"
    | "followup"
    | "closing"
    | "custom";
  createdAt: Date;
}

interface CustomerProfile {
  id: string;
  name: string;
  avatar?: string;
  email?: string;
  phone?: string;
  totalOrders: number;
  lastOrder?: any;
  customerSince: Date;
  notes?: string;
}

const MessengerChat: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(true);
  const [newMessage, setNewMessage] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [sending, setSending] = useState(false);
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showOrderModal, setShowOrderModal] = useState(false);
  const [uploadingFile, setUploadingFile] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [showSavedReplies, setShowSavedReplies] = useState(false);
  const [savedReplies, setSavedReplies] = useState<SavedReply[]>([]);
  const [showCustomerProfile, setShowCustomerProfile] = useState(false);
  const [customerProfile, setCustomerProfile] =
    useState<CustomerProfile | null>(null);
  const [searchResults, setSearchResults] = useState<string[]>([]);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [conversationToDelete, setConversationToDelete] =
    useState<Conversation | null>(null);

  const [conversationFilter, setConversationFilter] = useState<
    "all" | "new" | "active" | "archived" | "important"
  >("all");

  // إعداد الإشعارات

  // تحميل المحادثات
  const loadConversations = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        "https://www.mokhtarelhenawy.online/api/v1/conversations",
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      // Check if data is an array (direct response) or has success property
      if (Array.isArray(data)) {
        setConversations(data);
      } else if (data.success && data.data) {
        setConversations(data.data);
      } else {
        console.error("❌ API returned unexpected format:", data);
        setError("تنسيق غير متوقع من الخادم");
      }
    } catch (error) {
      console.error("Error loading conversations:", error);
      setError("فشل تحميل المحادثات");
    } finally {
      setLoading(false);
    }
  };

  // تحميل الرسائل
  const loadMessages = async (conversationId: string) => {
    try {
      const response = await fetch(
        `https://www.mokhtarelhenawy.online/api/v1/conversations/${conversationId}/messages`,
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      // Check if data is an array (direct response) or has success property
      if (Array.isArray(data)) {
        setMessages(data);
        scrollToBottom();
      } else if (data.success && data.data) {
        setMessages(data.data);
        scrollToBottom();
      } else {
        console.error("❌ Failed to load messages:", data);
      }
    } catch (error) {
      console.error("Error loading messages:", error);
    }
  };

  // التمرير إلى أسفل
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  // اختيار محادثة
  const selectConversation = (conversation: Conversation) => {
    setSelectedConversation(conversation);
    loadMessages(conversation.id);
    loadCustomerProfile(conversation.customerId);

    // تعليم الرسائل كمقروءة
    if (conversation.unreadCount > 0) {
      messages.forEach((message) => {
        if (message.isFromCustomer && message.status !== "read") {
          socketService.markAsRead(message.id, conversation.id);
        }
      });
    }
  };

  // تحميل بروفايل العميل
  const loadCustomerProfile = async (customerId: string) => {
    try {
      const response = await fetch(`/api/customers/${customerId}`);
      const data = await response.json();

      if (data.success) {
        setCustomerProfile(data.data);
      }
    } catch (error) {
      console.error("Error loading customer profile:", error);
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !selectedConversation) return;

    // Validate file
    const validation = uploadService.validateFile(file);
    if (!validation.valid) {
      alert(validation.error);
      return;
    }

    setUploadingFile(true);

    try {
      // Upload file
      const uploadResult = await uploadService.uploadConversationImage(file);

      if (!uploadResult.success) {
        alert(uploadResult.error || "Failed to upload image");
        return;
      }

      // Send message with image
      const imageMessage = {
        content: file.name,
        conversationId: selectedConversation.id,
        type: "image" as const,
        isFromCustomer: false,
        status: "sending" as const,
        fileUrl: uploadResult.data?.fullUrl,
        fileName: file.name,
        fileSize: file.size,
      };

      // Send via Socket.IO
      socketService.sendMessage({
        ...imageMessage,
        senderId: "current-user",
        senderName: "المستخدم",
      });

      // Update local state
      const newMsg = {
        id: Date.now().toString(),
        ...imageMessage,
        senderId: "current-user",
        senderName: "المستخدم",
        timestamp: new Date(),
        status: "sent" as const,
      };

      setMessages((prev) => [...prev, newMsg]);

      // Clear file input
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    } catch (error) {
      console.error("Error uploading file:", error);
      alert("Failed to upload image");
    } finally {
      setUploadingFile(false);
    }
  };

  // إرسال رسالة
  const handleSendMessage = async (
    content: string,
    type: "text" | "image" | "voice" = "text",
  ) => {
    if (!selectedConversation || !content.trim()) return;

    setSending(true);

    try {
      const message = {
        content: content.trim(),
        conversationId: selectedConversation.id,
        type,
        isFromCustomer: false,
        status: "sending" as const,
      };

      // إرسال عبر Socket.IO
      socketService.sendMessage({
        content: content.trim(),
        conversationId: selectedConversation.id,
        senderId: "current-user", // يجب استبداله بالمستخدم الفعلي
        senderName: "المستخدم",
        type,
        isFromCustomer: false,
        status: "sending",
      });

      // تحديث المحلي
      const newMsg = {
        id: Date.now().toString(),
        content: content.trim(),
        senderId: "current-user",
        senderName: "المستخدم",
        timestamp: new Date(),
        type: type as "text" | "image" | "voice",
        isFromCustomer: false,
        status: "sent" as const,
        conversationId: selectedConversation.id,
      };

      setMessages((prev) => [...prev, newMsg]);
      setNewMessage("");

      // تحديث آخر رسالة في المحادثة
      setConversations((prev) =>
        prev.map((conv) =>
          conv.id === selectedConversation.id
            ? {
                ...conv,
                lastMessage: content.trim(),
                lastMessageTime: new Date(),
              }
            : conv,
        ),
      );
    } catch (error) {
      console.error("Error sending message:", error);
    } finally {
      setSending(false);
    }
  };

  // حذف محادثة
  const handleDeleteConversation = async (conversationId: string) => {
    try {
      const response = await fetch(
        `https://www.mokhtarelhenawy.online/api/v1/conversations/${conversationId}`,
        {
          method: "DELETE",
        },
      );

      if (response.ok) {
        setConversations((prev) => prev.filter((c) => c.id !== conversationId));
        if (selectedConversation?.id === conversationId) {
          setSelectedConversation(null);
          setMessages([]);
        }
        setConversationToDelete(null);
      }
    } catch (error) {
      console.error("Error deleting conversation:", error);
    }
  };

  // تصفية المحادثات
  const filteredConversations = conversations.filter((conversation) => {
    const matchesSearch =
      conversation.customerName
        .toLowerCase()
        .includes(searchQuery.toLowerCase()) ||
      conversation.lastMessage
        .toLowerCase()
        .includes(searchQuery.toLowerCase());

    const matchesFilter =
      conversationFilter === "all" ||
      conversation.status === conversationFilter;

    return matchesSearch && matchesFilter;
  });

  // تحميل الردود المحفوظة
  const loadSavedReplies = async () => {
    try {
      const response = await fetch(
        "https://www.mokhtarelhenawy.online/api/v1/saved-replies",
      );
      const data = await response.json();

      if (data.success) {
        setSavedReplies(data.data);
      }
    } catch (error) {
      console.error("Error loading saved replies:", error);
    }
  };

  // استخدام الرد المحفوظ
  const useSavedReply = (reply: SavedReply) => {
    handleSendMessage(reply.content);
    setShowSavedReplies(false);
  };

  // البحث داخل المحادثة
  const searchInChat = (query: string) => {
    if (!query.trim()) {
      setSearchResults([]);
      return;
    }

    const results = messages.filter((message) =>
      message.content.toLowerCase().includes(query.toLowerCase()),
    );
    setSearchResults(results);
  };

  // إعداد التأثيرات
  useEffect(() => {
    loadConversations();
    loadSavedReplies();

    // توصيل Socket.IO
    const socket = socketService.connect();

    // الاستماع للأحداث
    socketService.onMessage((message) => {
      if (
        selectedConversation &&
        message.conversationId === selectedConversation.id
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socketService.onMessageDelivered((data) => {
      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === data.messageId ? { ...msg, status: "delivered" } : msg,
        ),
      );
    });

    socketService.onMessageRead((data) => {
      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === data.messageId ? { ...msg, status: "read" } : msg,
        ),
      );
    });

    socketService.onTypingStart((data) => {
      if (data.conversationId === selectedConversation?.id) {
        setTypingUsers((prev) => [...prev, data.userName]);
      }
    });

    socketService.onTypingStop((data) => {
      if (data.conversationId === selectedConversation?.id) {
        setTypingUsers((prev) => prev.filter((name) => name !== data.userName));
      }
    });

    socketService.onConversationUpdated((conversation) => {
      setConversations((prev) =>
        prev.map((conv) => (conv.id === conversation.id ? conversation : conv)),
      );
    });

    return () => {
      socketService.disconnect();
    };
  }, []);

  useEffect(() => {
    if (selectedConversation) {
      socketService.joinConversation(selectedConversation.id);

      return () => {
        socketService.leaveConversation(selectedConversation.id);
      };
    }
  }, [selectedConversation]);

  useEffect(() => {
    if (chatSearchQuery) {
      searchInChat(chatSearchQuery);
    }
  }, [chatSearchQuery, messages]);

  return (
    <div className="flex h-screen bg-gray-50">
      {/* Sidebar - قائمة المحادثات */}
      <div className="w-80 bg-white border-l border-gray-200 flex flex-col">
        {/* Header */}
        <div className="p-4 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-gray-900 mb-3">
            المحادثات
          </h2>

          {/* Search */}
          <div className="relative mb-3">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="البحث في المحادثات..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>

          {/* Filter Tabs */}
          <div className="flex space-x-1 bg-gray-100 rounded-lg p-1">
            {["all", "new", "active", "important", "archived"].map((filter) => (
              <button
                key={filter}
                onClick={() => setConversationFilter(filter as any)}
                className={`flex-1 px-2 py-1 text-sm rounded-md transition-colors ${
                  conversationFilter === filter
                    ? "bg-blue-600 text-white"
                    : "text-gray-600 hover:bg-gray-200"
                }`}
              >
                {filter === "all"
                  ? "الكل"
                  : filter === "new"
                    ? "جديد"
                    : filter === "active"
                      ? "نشط"
                      : filter === "important"
                        ? "مهم"
                        : "مؤرشف"}
              </button>
            ))}
          </div>
        </div>

        {/* Conversations List */}
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="flex items-center justify-center h-full">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
            </div>
          ) : (
            filteredConversations.map((conversation) => (
              <div
                key={conversation.id}
                onClick={() => selectConversation(conversation)}
                className={`p-4 border-b border-gray-100 cursor-pointer hover:bg-gray-50 transition-colors ${
                  selectedConversation?.id === conversation.id
                    ? "bg-blue-50 border-l-4 border-l-blue-600"
                    : ""
                }`}
              >
                <div className="flex items-center">
                  <img
                    src={
                      conversation.customerAvatar ||
                      `https://ui-avatars.com/api/?name=${conversation.customerName}&background=random`
                    }
                    alt={conversation.customerName}
                    className="w-12 h-12 rounded-full"
                  />
                  <div className="mr-3 flex-1">
                    <div className="flex justify-between items-center">
                      <h3 className="font-semibold text-gray-900">
                        {conversation.customerName}
                        {conversation.pageName && (
                          <span className="text-xs text-blue-600 font-medium bg-blue-50 px-1.5 py-0.5 rounded mr-2">
                            {conversation.pageName}
                          </span>
                        )}
                      </h3>
                      <span className="text-xs text-gray-500">
                        {new Date(
                          conversation.lastMessageTime,
                        ).toLocaleTimeString("ar-EG", {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 truncate">
                      {conversation.lastMessage}
                    </p>
                    <div className="flex justify-between items-center mt-1">
                      <span
                        className={`text-xs px-2 py-1 rounded-full ${
                          conversation.status === "new"
                            ? "bg-green-100 text-green-800"
                            : conversation.status === "active"
                              ? "bg-blue-100 text-blue-800"
                              : conversation.status === "important"
                                ? "bg-red-100 text-red-800"
                                : conversation.status === "archived"
                                  ? "bg-gray-100 text-gray-800"
                                  : ""
                        }`}
                      >
                        {conversation.status === "new"
                          ? "جديد"
                          : conversation.status === "active"
                            ? "نشط"
                            : conversation.status === "important"
                              ? "مهم"
                              : "مؤرشف"}
                      </span>
                      {conversation.unreadCount > 0 && (
                        <span className="bg-red-500 text-white text-xs rounded-full px-2 py-1">
                          {conversation.unreadCount}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 flex flex-col bg-white">
        {selectedConversation ? (
          <>
            {/* Chat Header */}
            <div className="p-4 border-b border-gray-200 flex justify-between items-center">
              <div className="flex items-center">
                <img
                  src={
                    selectedConversation.customerAvatar ||
                    `https://ui-avatars.com/api/?name=${selectedConversation.customerName}&background=random`
                  }
                  alt={selectedConversation.customerName}
                  className="w-10 h-10 rounded-full"
                />
                <div className="mr-3">
                  <h3 className="font-semibold text-gray-900">
                    {selectedConversation.customerName}
                  </h3>
                  <p className="text-sm text-gray-500">
                    {selectedConversation.isOnline ? "متصل الآن" : "غير متصل"}
                  </p>
                </div>
              </div>

              <div className="flex space-x-2">
                <button
                  onClick={() => setShowCustomerProfile(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <InformationCircleIcon className="w-5 h-5" />
                </button>
                <button
                  onClick={() => setShowOrderModal(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <ShoppingCartIcon className="w-5 h-5" />
                </button>
                <button
                  onClick={() => {
                    setConversationToDelete(selectedConversation);
                    setShowDeleteModal(true);
                  }}
                  className="p-2 text-gray-400 hover:text-red-600"
                >
                  <TrashIcon className="w-5 h-5" />
                </button>
              </div>
            </div>

            {/* Messages Area */}
            <div
              className="flex-1 overflow-y-auto p-4"
              ref={messagesContainerRef}
            >
              <div className="space-y-4">
                {messages.map((message) => (
                  <div
                    key={message.id}
                    className={`flex ${message.isFromCustomer ? "justify-start" : "justify-end"}`}
                  >
                    <div
                      className={`max-w-xs lg:max-w-md xl:max-w-lg ${
                        message.isFromCustomer
                          ? "bg-gray-100"
                          : "bg-blue-600 text-white"
                      } rounded-lg p-3`}
                    >
                      {message.type === "image" && (
                        <img
                          src={message.fileUrl}
                          alt={message.fileName}
                          className="rounded-lg max-w-full"
                        />
                      )}
                      {message.type === "text" && (
                        <p className="text-sm">{message.content}</p>
                      )}
                      <div
                        className={`flex items-center mt-1 text-xs ${
                          message.isFromCustomer
                            ? "text-gray-500"
                            : "text-blue-100"
                        }`}
                      >
                        <span>
                          {new Date(message.timestamp).toLocaleTimeString(
                            "ar-EG",
                            { hour: "2-digit", minute: "2-digit" },
                          )}
                        </span>
                        {!message.isFromCustomer && (
                          <span className="mr-1">
                            {message.status === "sent" && (
                              <CheckIcon className="w-4 h-4" />
                            )}
                            {message.status === "delivered" && (
                              <CheckCheckIcon className="w-4 h-4" />
                            )}
                            {message.status === "read" && (
                              <EyeIcon className="w-4 h-4" />
                            )}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
                <div ref={messagesEndRef} />
              </div>
            </div>

            {/* Message Input */}
            <div className="p-4 border-t border-gray-200">
              <div className="flex items-center space-x-2">
                <button
                  onClick={() => setShowSavedReplies(true)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <ArchiveBoxIcon className="w-5 h-5" />
                </button>
                <button
                  onClick={() => fileInputRef.current?.click()}
                  disabled={uploadingFile}
                  className={`p-2 ${uploadingFile ? "text-gray-300" : "text-gray-400 hover:text-gray-600"}`}
                >
                  {uploadingFile ? (
                    <div className="w-5 h-5 border-2 border-gray-300 border-t-blue-500 rounded-full animate-spin"></div>
                  ) : (
                    <PaperClipIcon className="w-5 h-5" />
                  )}
                </button>
                <button
                  onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                  className="p-2 text-gray-400 hover:text-gray-600"
                >
                  <FaceSmileIcon className="w-5 h-5" />
                </button>
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={handleFileSelect}
                  className="hidden"
                  accept="image/*"
                />
                <div className="flex-1">
                  <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    onKeyPress={(e) => {
                      if (e.key === "Enter" && !e.shiftKey) {
                        e.preventDefault();
                        handleSendMessage(newMessage, "text");
                      }
                    }}
                    placeholder="اكتب رسالتك..."
                    className="w-full px-4 py-2 border border-gray-300 rounded-full focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>
                <button
                  onClick={() => handleSendMessage(newMessage, "text")}
                  disabled={!newMessage.trim() || sending}
                  className="p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <PaperAirplaneIcon className="w-5 h-5" />
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center">
            <div className="text-center text-gray-500">
              <ChatBubbleLeftRightIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
              <h3 className="text-lg font-semibold mb-2">اختر محادثة للبدء</h3>
              <p>اختر محادثة من القائمة لعرض الرسائل</p>
            </div>
          </div>
        )}
      </div>

      {/* Customer Profile Sidebar */}
      {showCustomerProfile && selectedConversation && (
        <div className="w-80 bg-white border-r border-gray-200 p-4">
          <div className="flex justify-between items-center mb-4">
            <h3 className="font-semibold">بروفايل العميل</h3>
            <button
              onClick={() => setShowCustomerProfile(false)}
              className="p-1 text-gray-400 hover:text-gray-600"
            >
              <XMarkIcon className="w-5 h-5" />
            </button>
          </div>

          {customerProfile && (
            <div className="space-y-4">
              <div className="text-center">
                <img
                  src={
                    customerProfile.avatar ||
                    `https://ui-avatars.com/api/?name=${customerProfile.name}&background=random`
                  }
                  alt={customerProfile.name}
                  className="w-20 h-20 rounded-full mx-auto mb-2"
                />
                <h4 className="font-semibold">{customerProfile.name}</h4>
                <p className="text-sm text-gray-600">{customerProfile.email}</p>
              </div>

              <div className="border-t pt-4">
                <h5 className="font-semibold mb-2">معلومات العميل</h5>
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <span className="text-gray-600">الطلبات الكلية:</span>
                    <span>{customerProfile.totalOrders}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">تاريخ التسجيل:</span>
                    <span>
                      {new Date(
                        customerProfile.customerSince,
                      ).toLocaleDateString("ar-EG")}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default MessengerChat;

import React, { useState, useEffect, useRef } from "react";
import { useAuth } from "../../hooks/useAuthSimple";
import { useTranslation } from "react-i18next";
import useSocket from "../../hooks/useSocket";
import { companyAwareApi } from "../../services/companyAwareApi";
import {
  Send,
  Paperclip,
  Smile,
  MoreVertical,
  Search,
  Phone,
  Check,
  CheckCheck,
  MessageCircle,
  Bot,
  Settings,
  User,
  MapPin,
  File,
  Image as ImageIcon,
  Reply,
  Forward,
  Trash2,
  Mic,
  X,
  Video,
  Music,
  Map,
  Contact,
  Edit,
  Download,
  Play,
  Pause,
  Volume2,
} from "lucide-react";

// --- Types ---
interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  type:
    | "text"
    | "image"
    | "video"
    | "audio"
    | "document"
    | "location"
    | "contact"
    | "voice";
  isFromCustomer: boolean;
  status: "sent" | "delivered" | "read" | "failed";
  conversationId: string;
  fileUrl?: string;
  fileName?: string;
  fileSize?: number;
  isAiGenerated?: boolean;
  replyToMessageId?: string;
  location?: { latitude: number; longitude: number };
  duration?: number; // for audio/voice messages
}

interface Conversation {
  id: string;
  customerId: string;
  customerName: string;
  customerAvatar?: string;
  lastMessage: string;
  lastMessageTime: Date;
  unreadCount: number;
  platform: "telegram";
  isOnline: boolean;
  messages: Message[];
  telegramBotId?: string;
}

const TelegramConversationsPro: React.FC = () => {
  const { user, isAuthenticated } = useAuth();
  const { i18n } = useTranslation();
  const { socket, isConnected } = useSocket();

  // Detect language direction
  const isRTL = i18n.language === "ar";
  const dir = isRTL ? "rtl" : "ltr";

  // State
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversationId, setSelectedConversationId] = useState<
    string | null
  >(null);
  const [loading, setLoading] = useState(true);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [chatSearchQuery, setChatSearchQuery] = useState("");
  const [isInfoOpen, setIsInfoOpen] = useState(true);
  const [isTyping, setIsTyping] = useState(false);
  const [showMediaGallery, setShowMediaGallery] = useState(false);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [editingMessage, setEditingMessage] = useState<Message | null>(null);
  const [showFileMenu, setShowFileMenu] = useState(false);

  // Refs
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);
  const documentInputRef = useRef<HTMLInputElement>(null);

  // Filtered Conversations
  const filteredConversations = conversations.filter(
    (c) =>
      c.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.lastMessage.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  // Filtered Messages (for chat search)
  const filteredMessages = chatSearchQuery
    ? messages.filter((m) =>
        m.content.toLowerCase().includes(chatSearchQuery.toLowerCase()),
      )
    : messages;

  const activeConversation = conversations.find(
    (c) => c.id === selectedConversationId,
  );

  // --- Effects ---

  // 1. Load Conversations
  useEffect(() => {
    if (!isAuthenticated || !user?.companyId) return;

    const fetchConversations = async () => {
      try {
        setLoading(true);
        const response = await companyAwareApi.getConversations({
          page: 1,
          limit: 50,
          platform: "telegram",
        });

        if (response.data && response.data.data) {
          const formatted = response.data.data.map((c: any) => ({
            id: c.id,
            customerId: c.customerId,
            customerName: c.customerName || "Telegram User",
            lastMessage: c.lastMessage || "",
            lastMessageTime: new Date(c.lastMessageTime || Date.now()),
            unreadCount: c.unreadCount || 0,
            platform: "telegram",
            isOnline: false,
            messages: [],
          }));
          setConversations(formatted);
        }
      } catch (error) {
        console.error("Failed to load Telegram conversations:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchConversations();
  }, [isAuthenticated, user?.companyId]);

  // 2. Load Messages
  useEffect(() => {
    if (!selectedConversationId) return;

    const fetchMessages = async () => {
      try {
        const response = await companyAwareApi.get(
          `/conversations/${selectedConversationId}/messages`,
        );
        const data = response.data.data || [];

        const loadedMessages: Message[] = data.map((msg: any) => ({
          id: msg.id,
          content: msg.content,
          senderId: msg.senderId || "unknown",
          senderName: msg.isFromCustomer ? "Customer" : "Agent",
          timestamp: new Date(msg.createdAt || Date.now()),
          type: (msg.type || "text").toLowerCase(),
          isFromCustomer: msg.isFromCustomer,
          status: "read",
          conversationId: selectedConversationId,
          fileUrl:
            msg.fileUrl ||
            (msg.metadata
              ? JSON.parse(msg.metadata || "{}").fileUrl
              : undefined),
          fileName:
            msg.fileName ||
            (msg.metadata
              ? JSON.parse(msg.metadata || "{}").fileName
              : undefined),
          fileSize:
            msg.fileSize ||
            (msg.metadata
              ? JSON.parse(msg.metadata || "{}").fileSize
              : undefined),
          location:
            msg.location ||
            (msg.metadata
              ? JSON.parse(msg.metadata || "{}").location
              : undefined),
          duration:
            msg.duration ||
            (msg.metadata
              ? JSON.parse(msg.metadata || "{}").duration
              : undefined),
        }));

        // ترتيب الرسائل من الأقدم للأحدث (الأقدم أولاً)
        const sortedMessages = loadedMessages.sort(
          (a, b) =>
            new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
        );

        setMessages(sortedMessages);
      } catch (error) {
        console.error("Failed to load messages:", error);
      }
    };

    fetchMessages();
  }, [selectedConversationId]);

  // 3. Socket
  useEffect(() => {
    if (!socket || !isConnected || !user?.companyId) {
      console.log("⚠️ [SOCKET] Socket not ready:", {
        socket: !!socket,
        isConnected,
        companyId: user?.companyId,
      });
      return;
    }

    // Join company room to receive messages
    socket.emit("join_company_room", { companyId: user.companyId });
    console.log("🔌 [SOCKET] Joined company room:", user.companyId);

    const handleNewMessage = (data: any) => {
      console.log("📨 [SOCKET] Received message:", {
        id: data.id,
        platform: data.platform,
        channel: data.channel,
        conversationId: data.conversationId,
        companyId: data.companyId,
        userCompanyId: user?.companyId,
        content: data.content?.substring(0, 50),
      });

      // Filter for Telegram messages
      const isTelegram =
        data.platform === "telegram" || data.channel === "TELEGRAM";
      if (!isTelegram) {
        console.log(
          "⚠️ [SOCKET] Not a Telegram message, skipping. Platform:",
          data.platform,
          "Channel:",
          data.channel,
        );
        return;
      }

      if (String(data.companyId) !== String(user?.companyId)) {
        console.log(
          "⚠️ [SOCKET] Different company, skipping. Data company:",
          data.companyId,
          "User company:",
          user?.companyId,
        );
        return;
      }

      console.log(
        "✅ [SOCKET] Processing Telegram message for conversation:",
        data.conversationId,
      );

      setConversations((prev) => {
        const exists = prev.find((c) => c.id === data.conversationId);
        if (exists) {
          return prev.map((c) =>
            c.id === data.conversationId
              ? {
                  ...c,
                  lastMessage: data.content,
                  lastMessageTime: new Date(),
                  unreadCount:
                    data.conversationId === selectedConversationId
                      ? 0
                      : c.unreadCount + 1,
                }
              : c,
          );
        }
        return prev;
      });

      if (selectedConversationId === data.conversationId) {
        const newMsg: Message = {
          id: data.id || Date.now().toString(),
          content: data.content,
          senderId: data.senderId,
          senderName: data.senderName,
          timestamp: new Date(data.timestamp || Date.now()),
          type: (data.type || "text").toLowerCase(),
          isFromCustomer: data.isFromCustomer,
          status: "delivered",
          conversationId: data.conversationId,
          fileUrl:
            data.fileUrl ||
            (data.metadata
              ? (typeof data.metadata === "string"
                  ? JSON.parse(data.metadata)
                  : data.metadata
                ).fileUrl
              : undefined),
          fileName:
            data.fileName ||
            (data.metadata
              ? (typeof data.metadata === "string"
                  ? JSON.parse(data.metadata)
                  : data.metadata
                ).fileName
              : undefined),
          location:
            data.location ||
            (data.metadata
              ? (typeof data.metadata === "string"
                  ? JSON.parse(data.metadata)
                  : data.metadata
                ).location
              : undefined),
          duration:
            data.duration ||
            (data.metadata
              ? (typeof data.metadata === "string"
                  ? JSON.parse(data.metadata)
                  : data.metadata
                ).duration
              : undefined),
        };

        // منع التكرار: التحقق من وجود الرسالة بالفعل
        setMessages((prev) => {
          // التحقق من وجود الرسالة بنفس ID
          const existsById = prev.some((msg) => msg.id === newMsg.id);
          if (existsById) {
            console.log(
              "⚠️ [SOCKET] Message already exists by ID, skipping:",
              newMsg.id,
            );
            return prev;
          }

          // التحقق من الرسائل المؤقتة (temp messages) - استبدالها بالرسالة الحقيقية
          const tempMessageIndex = prev.findIndex(
            (msg) =>
              msg.id.startsWith("temp_") &&
              msg.content === newMsg.content &&
              !msg.isFromCustomer === !newMsg.isFromCustomer &&
              Math.abs(
                new Date(msg.timestamp).getTime() -
                  new Date(newMsg.timestamp).getTime(),
              ) < 5000,
          );

          if (tempMessageIndex !== -1) {
            // استبدال الرسالة المؤقتة بالرسالة الحقيقية
            const updated = [...prev];
            updated[tempMessageIndex] = newMsg;
            // ترتيب الرسائل بعد الاستبدال
            return updated.sort(
              (a, b) =>
                new Date(a.timestamp).getTime() -
                new Date(b.timestamp).getTime(),
            );
          }

          // إضافة الرسالة الجديدة وترتيبها
          const updated = [...prev, newMsg];
          return updated.sort(
            (a, b) =>
              new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
          );
        });
        setTimeout(scrollToBottom, 100);
      }
    };

    const handleTyping = (data: any) => {
      if (
        data.conversationId === selectedConversationId &&
        data.isFromCustomer
      ) {
        setIsTyping(true);
        setTimeout(() => setIsTyping(false), 3000);
      }
    };

    socket.on("new_message", handleNewMessage);
    socket.on("typing", handleTyping);
    return () => {
      socket.off("new_message", handleNewMessage);
      socket.off("typing", handleTyping);
    };
  }, [socket, isConnected, selectedConversationId, user?.companyId]);

  // Handlers
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const handleSendMessage = async () => {
    if (!selectedConversationId || !inputText.trim()) return;

    const messageContent = inputText.trim();
    const tempId = `temp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const tempMsg: Message = {
      id: tempId,
      content: messageContent,
      senderId: user?.id || "me",
      senderName: "Me",
      timestamp: new Date(),
      type: "text",
      isFromCustomer: false,
      status: "sending",
      conversationId: selectedConversationId,
      replyToMessageId: replyingTo?.id,
    };

    // إضافة الرسالة المؤقتة
    setMessages((prev) => {
      const updated = [...prev, tempMsg];
      return updated.sort(
        (a, b) =>
          new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
      );
    });
    setInputText("");
    setReplyingTo(null);
    setTimeout(scrollToBottom, 100);

    try {
      const response = await companyAwareApi.post(
        `/conversations/${selectedConversationId}/messages`,
        {
          message: messageContent,
          type: "text",
          replyToMessageId: replyingTo?.id,
        },
      );

      // إذا كانت الرسالة تم حفظها بنجاح، سيتم استبدالها بالرسالة الحقيقية من Socket
      // لكن إذا لم تأت من Socket، نحدث حالة الرسالة المؤقتة
      if (response.data.success && response.data.data) {
        setMessages((prev) =>
          prev.map((msg) =>
            msg.id === tempId
              ? { ...msg, id: response.data.data.id, status: "sent" }
              : msg,
          ),
        );
      }
    } catch (error) {
      console.error("Failed to send:", error);
      // في حالة الفشل، إزالة الرسالة المؤقتة
      setMessages((prev) => prev.filter((msg) => msg.id !== tempId));
    }
  };

  const handleFileSelect = async (
    e: React.ChangeEvent<HTMLInputElement>,
    type: "image" | "video" | "audio" | "document",
  ) => {
    if (!e.target.files || !e.target.files[0] || !selectedConversationId)
      return;

    const file = e.target.files[0];
    const tempId = `temp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // إضافة رسالة مؤقتة
    const tempMsg: Message = {
      id: tempId,
      content: `[${type}]`,
      senderId: user?.id || "me",
      senderName: "Me",
      timestamp: new Date(),
      type: type,
      isFromCustomer: false,
      status: "sending",
      conversationId: selectedConversationId,
      fileName: file.name,
      fileSize: file.size,
    };

    setMessages((prev) => {
      const updated = [...prev, tempMsg];
      return updated.sort(
        (a, b) =>
          new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
      );
    });
    setTimeout(scrollToBottom, 100);

    const formData = new FormData();
    formData.append("file", file);
    formData.append("type", type);

    try {
      const response = await companyAwareApi.post(
        `/conversations/${selectedConversationId}/messages/media`,
        formData,
        {
          headers: { "Content-Type": "multipart/form-data" },
        },
      );

      if (response.data.success) {
        // تحديث الرسالة المؤقتة بالرسالة الحقيقية
        // سيتم استبدالها بالرسالة الكاملة من Socket لاحقاً
        setMessages((prev) =>
          prev.map((msg) =>
            msg.id === tempId
              ? { ...msg, id: response.data.data.id, status: "sent" }
              : msg,
          ),
        );
      }
    } catch (error) {
      console.error("Failed to upload file:", error);
      // إزالة الرسالة المؤقتة في حالة الفشل
      setMessages((prev) => prev.filter((msg) => msg.id !== tempId));
      alert(isRTL ? "فشل رفع الملف" : "Failed to upload file");
    }
  };

  const handleSendLocation = async () => {
    if (!selectedConversationId) return;

    if (!navigator.geolocation) {
      alert(
        isRTL ? "المتصفح لا يدعم تحديد الموقع" : "Geolocation not supported",
      );
      return;
    }

    navigator.geolocation.getCurrentPosition(async (position) => {
      try {
        const response = await companyAwareApi.post(
          `/conversations/${selectedConversationId}/messages`,
          {
            type: "location",
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          },
        );

        if (response.data.success) {
          const newMsg: Message = {
            id: response.data.data.id || Date.now().toString(),
            content: "",
            senderId: user?.id || "me",
            senderName: "Me",
            timestamp: new Date(),
            type: "location",
            isFromCustomer: false,
            status: "sent",
            conversationId: selectedConversationId,
            location: {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
            },
          };
          setMessages((prev) => [...prev, newMsg]);
          setTimeout(scrollToBottom, 100);
        }
      } catch (error) {
        console.error("Failed to send location:", error);
      }
    });
  };

  const handleEditMessage = async (message: Message) => {
    if (!inputText.trim()) return;

    try {
      await companyAwareApi.put(
        `/conversations/${selectedConversationId}/messages/${message.id}`,
        {
          content: inputText,
        },
      );

      setMessages((prev) =>
        prev.map((m) =>
          m.id === message.id ? { ...m, content: inputText } : m,
        ),
      );
      setEditingMessage(null);
      setInputText("");
    } catch (error) {
      console.error("Failed to edit message:", error);
    }
  };

  const handleDeleteMessage = async (messageId: string) => {
    if (!confirm(isRTL ? "هل تريد حذف هذه الرسالة؟" : "Delete this message?"))
      return;

    try {
      await companyAwareApi.delete(
        `/conversations/${selectedConversationId}/messages/${messageId}`,
      );
      setMessages((prev) => prev.filter((m) => m.id !== messageId));
    } catch (error) {
      console.error("Failed to delete message:", error);
    }
  };

  const handleForwardMessage = async (message: Message) => {
    // TODO: Implement forward to another conversation
    alert(isRTL ? "ميزة إعادة التوجيه قريباً" : "Forward feature coming soon");
  };

  // Get media messages for gallery
  const mediaMessages = messages.filter((m) =>
    ["image", "video", "document"].includes(m.type),
  );

  // --- Render ---
  return (
    <div
      className={`flex h-[calc(100vh-64px)] business-bg-messenger-app business-bg-soft overflow-hidden`}
      dir={dir}
    >
      {/* SIDEBAR: Conversations List - Position based on language */}
      <div
        className={`w-[350px] business-bg-panel border-r business-border flex flex-col shrink-0 z-20 ${isRTL ? "order-3" : "order-1"}`}
      >
        {/* Header */}
        <div className="p-4 business-bg-primary-solid business-text-on-accent flex justify-between items-center shadow-sm">
          <h2 className="font-bold text-lg flex items-center gap-2">
            <Bot size={20} />
            {isRTL ? "محادثات تيليجرام" : "Telegram Chats"}
          </h2>
          <div className="flex gap-2">
            <Settings
              size={18}
              className="cursor-pointer opacity-80 hover:opacity-100"
            />
          </div>
        </div>

        {/* Search */}
        <div className="p-3 border-b business-border">
          <div className="relative">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder={isRTL ? "بحث في المحادثات..." : "Search chats..."}
              className={`w-full ${isRTL ? "pr-10 pl-4" : "pl-10 pr-4"} py-2 business-bg-soft-strong border-none rounded-lg text-sm business-text-strong business-placeholder-muted focus:ring-2 business-focus-primary transition-all`}
            />
            <Search
              className={`absolute ${isRTL ? "right-3" : "left-3"} top-2.5 business-text-subtle`}
              size={16}
            />
          </div>
        </div>

        {/* List */}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {loading ? (
            <div className="p-10 text-center business-text-subtle flex flex-col items-center">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 business-border-primary-strong mb-2"></div>
              {isRTL ? "جاري التحميل..." : "Loading..."}
            </div>
          ) : filteredConversations.length === 0 ? (
            <div className="p-10 text-center business-text-subtle">
              {searchQuery
                ? isRTL
                  ? "لا توجد نتائج"
                  : "No results found"
                : isRTL
                  ? "لا توجد محادثات"
                  : "No conversations found"}
            </div>
          ) : (
            filteredConversations.map((conv) => (
              <div
                key={conv.id}
                onClick={() => setSelectedConversationId(conv.id)}
                className={`p-3 border-b business-border cursor-pointer business-hover-primary-soft business-hover-soft transition-colors
                                    ${selectedConversationId === conv.id ? `business-bg-primary-soft ${isRTL ? "border-r-4 business-border-r-primary" : "border-l-4 business-border-l-primary"}` : ""}
                                `}
              >
                <div
                  className={`flex justify-between items-start mb-1 ${isRTL ? "flex-row-reverse" : ""}`}
                >
                  <h3 className="font-semibold business-text-strong text-sm truncate">
                    {conv.customerName}
                  </h3>
                  <span
                    className={`text-[10px] business-text-subtle whitespace-nowrap ${isRTL ? "mr-2" : "ml-2"}`}
                  >
                    {conv.lastMessageTime.toLocaleTimeString([], {
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </span>
                </div>
                <div
                  className={`flex justify-between items-end ${isRTL ? "flex-row-reverse" : ""}`}
                >
                  <p
                    className={`text-xs business-text-muted truncate max-w-[200px] ${isRTL ? "text-right" : "text-left"}`}
                  >
                    {conv.lastMessage}
                  </p>
                  {conv.unreadCount > 0 && (
                    <span className="business-bg-primary-solid business-text-on-accent text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[18px] text-center shadow-sm">
                      {conv.unreadCount}
                    </span>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* MIDDLE: Chat Area */}
      <div className="flex-1 flex flex-col business-bg-messenger-thread business-bg-panel bg-opacity-10 relative order-2">
        {selectedConversationId && activeConversation ? (
          <>
            {/* Header */}
            <div
              className={`p-3 business-bg-panel border-b business-border flex justify-between items-center z-10 shadow-sm px-4 ${isRTL ? "flex-row-reverse" : ""}`}
            >
              <div
                className={`flex items-center gap-3 ${isRTL ? "flex-row-reverse" : ""}`}
              >
                <div className="w-10 h-10 rounded-full bg-gradient-to-br business-bg-brand-gradient business-text-on-accent flex items-center justify-center font-bold text-lg shadow-sm">
                  {activeConversation.customerName.charAt(0).toUpperCase()}
                </div>
                <div>
                  <h3 className="font-bold business-text-strong pointer-events-none">
                    {activeConversation.customerName}
                  </h3>
                  <div
                    className={`text-xs business-text-primary flex items-center gap-1 ${isRTL ? "flex-row-reverse" : ""}`}
                  >
                    <div className="w-1.5 h-1.5 rounded-full business-bg-success-solid"></div>
                    {isRTL ? "مشترك بوت" : "bot subscriber"}
                    {isTyping && (
                      <span className="business-text-muted ml-2">
                        {isRTL ? "يكتب..." : "typing..."}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <div
                className={`flex items-center gap-2 business-text-muted ${isRTL ? "flex-row-reverse" : ""}`}
              >
                <button
                  onClick={() => setChatSearchQuery(chatSearchQuery ? "" : " ")}
                  className="p-2 business-hover-soft rounded-full transition-colors"
                  title={isRTL ? "بحث في المحادثة" : "Search in chat"}
                >
                  <Search size={20} />
                </button>
                <button
                  onClick={() => setShowMediaGallery(!showMediaGallery)}
                  className="p-2 business-hover-soft rounded-full transition-colors"
                  title={isRTL ? "معرض الوسائط" : "Media gallery"}
                >
                  <ImageIcon size={20} />
                </button>
                <button
                  className="p-2 business-hover-soft rounded-full transition-colors"
                  title={isRTL ? "مكالمة (قريباً)" : "Call (Coming Soon)"}
                >
                  <Phone size={20} />
                </button>
                <button
                  className={`p-2 business-hover-soft rounded-full transition-colors ${isInfoOpen ? "business-text-primary business-bg-primary-soft" : ""}`}
                  onClick={() => setIsInfoOpen(!isInfoOpen)}
                  title={isRTL ? "تبديل المعلومات" : "Toggle Info"}
                >
                  <MoreVertical size={20} />
                </button>
              </div>
            </div>

            {/* Chat Search Bar */}
            {chatSearchQuery !== null && chatSearchQuery !== "" && (
              <div className="p-2 business-bg-primary-soft border-b business-border-primary-soft flex items-center gap-2">
                <input
                  type="text"
                  value={chatSearchQuery}
                  onChange={(e) => setChatSearchQuery(e.target.value)}
                  placeholder={
                    isRTL ? "بحث في الرسائل..." : "Search messages..."
                  }
                  className={`flex-1 ${isRTL ? "pr-10 pl-4" : "pl-10 pr-4"} py-2 business-bg-panel border business-border-primary-soft business-control-border rounded-lg text-sm business-text-strong focus:ring-2 business-focus-primary`}
                  autoFocus
                />
                <button
                  onClick={() => setChatSearchQuery("")}
                  className="p-2 business-hover-primary-soft business-hover-primary-solid rounded"
                >
                  <X size={16} />
                </button>
              </div>
            )}

            {/* Media Gallery */}
            {showMediaGallery && (
              <div className="p-4 business-bg-panel border-b business-border max-h-48 overflow-y-auto">
                <h4 className="font-semibold mb-3 business-text-strong">
                  {isRTL ? "الوسائط المشتركة" : "Shared Media"}
                </h4>
                <div className="grid grid-cols-6 gap-2">
                  {mediaMessages.slice(0, 12).map((msg, idx) => (
                    <div
                      key={idx}
                      className="aspect-square business-bg-soft-strong rounded-lg overflow-hidden cursor-pointer hover:opacity-80"
                    >
                      {msg.type === "image" && msg.fileUrl ? (
                        <img
                          src={msg.fileUrl}
                          alt=""
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          {msg.type === "video" && (
                            <Video size={20} className="business-text-subtle" />
                          )}
                          {msg.type === "document" && (
                            <File size={20} className="business-text-subtle" />
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-3 z-10 custom-scrollbar">
              {/* ترتيب الرسائل من الأقدم للأحدث للعرض */}
              {filteredMessages
                .sort(
                  (a, b) =>
                    new Date(a.timestamp).getTime() -
                    new Date(b.timestamp).getTime(),
                )
                .map((msg, idx) => {
                  const isMe = !msg.isFromCustomer;
                  const replyingToMsg = msg.replyToMessageId
                    ? messages.find((m) => m.id === msg.replyToMessageId)
                    : null;

                  return (
                    <div
                      key={idx}
                      className={`group flex ${isMe ? (isRTL ? "justify-start" : "justify-end") : isRTL ? "justify-end" : "justify-start"}`}
                    >
                      <div
                        className={`max-w-[70%] p-3 rounded-2xl shadow-sm relative group-hover:shadow-md transition-shadow
                                            ${isMe ? `business-bg-primary-soft ${isRTL ? "rounded-tl-none" : "rounded-tr-none"}` : `business-bg-panel ${isRTL ? "rounded-tr-none" : "rounded-tl-none"}`}
                                        `}
                      >
                        {/* Reply Preview */}
                        {replyingToMsg && (
                          <div
                            className={`mb-2 ${isRTL ? "border-r-2" : "border-l-2"} business-border-primary-strong pl-2 pr-2 py-1 business-bg-soft rounded text-xs`}
                          >
                            <p className="font-semibold business-text-primary">
                              {replyingToMsg.senderName}
                            </p>
                            <p className="business-text-muted truncate">
                              {replyingToMsg.content ||
                                (isRTL ? "وسائط" : "Media")}
                            </p>
                          </div>
                        )}

                        {!isMe && (
                          <p className="text-[10px] business-text-primary font-bold mb-1 opacity-80">
                            {msg.senderName}
                          </p>
                        )}

                        {/* Media Rendering */}
                        {msg.type === "image" && msg.fileUrl && (
                          <div className="mb-2 relative rounded-lg overflow-hidden border business-border">
                            <img
                              src={msg.fileUrl}
                              alt="attachment"
                              className="max-w-xs max-h-64 object-cover"
                            />
                          </div>
                        )}

                        {msg.type === "video" && msg.fileUrl && (
                          <div className="mb-2 relative rounded-lg overflow-hidden border business-border">
                            <video
                              src={msg.fileUrl}
                              controls
                              className="max-w-xs max-h-64"
                            />
                          </div>
                        )}

                        {msg.type === "audio" && (
                          <div className="mb-2 flex items-center gap-2 p-2 business-bg-soft rounded">
                            <Music
                              size={20}
                              className="business-text-primary"
                            />
                            <div className="flex-1">
                              <p className="text-xs font-semibold">
                                {msg.fileName ||
                                  (isRTL ? "ملف صوتي" : "Audio file")}
                              </p>
                              {msg.duration && (
                                <p className="text-[10px] business-text-muted">
                                  {msg.duration}s
                                </p>
                              )}
                            </div>
                            <button className="p-1 business-hover-soft rounded">
                              <Play size={16} />
                            </button>
                          </div>
                        )}

                        {msg.type === "voice" && (
                          <div className="mb-2 flex items-center gap-2 p-2 business-bg-soft rounded">
                            <Mic size={20} className="business-text-primary" />
                            <div className="flex-1 business-bg-soft-strong h-1 rounded-full">
                              <div
                                className="business-bg-primary-solid h-1 rounded-full"
                                style={{ width: "60%" }}
                              ></div>
                            </div>
                            {msg.duration && (
                              <span className="text-xs business-text-muted">
                                {msg.duration}s
                              </span>
                            )}
                          </div>
                        )}

                        {msg.type === "document" && (
                          <div className="mb-2 flex items-center gap-2 p-2 business-bg-soft rounded border business-border">
                            <File size={24} className="business-text-primary" />
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-semibold truncate">
                                {msg.fileName || (isRTL ? "مستند" : "Document")}
                              </p>
                              {msg.fileSize && (
                                <p className="text-xs business-text-muted">
                                  {(msg.fileSize / 1024).toFixed(1)} KB
                                </p>
                              )}
                            </div>
                            <button className="p-1 business-hover-soft rounded">
                              <Download size={16} />
                            </button>
                          </div>
                        )}

                        {msg.type === "location" && msg.location && (
                          <div className="mb-2 relative rounded-lg overflow-hidden border business-border">
                            <div className="w-64 h-32 business-bg-soft-strong flex items-center justify-center">
                              <Map
                                size={32}
                                className="business-text-primary"
                              />
                            </div>
                            <a
                              href={`https://www.google.com/maps?q=${msg.location.latitude},${msg.location.longitude}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="absolute bottom-2 left-2 right-2 business-bg-panel px-2 py-1 rounded text-xs business-text-primary business-hover-primary-soft"
                            >
                              {isRTL ? "فتح في الخرائط" : "Open in Maps"}
                            </a>
                          </div>
                        )}

                        {/* Text Content */}
                        {msg.content && (
                          <p
                            className={`text-sm business-text-strong whitespace-pre-wrap leading-relaxed min-w-[120px] ${isRTL ? "text-right" : "text-left"}`}
                          >
                            {msg.content}
                          </p>
                        )}

                        {/* Footer (Time + Status) */}
                        <div
                          className={`flex ${isRTL ? "justify-start" : "justify-end"} items-center gap-1 mt-1 select-none`}
                        >
                          <span className="text-[10px] business-text-subtle">
                            {msg.timestamp.toLocaleTimeString([], {
                              hour: "2-digit",
                              minute: "2-digit",
                            })}
                          </span>
                          {isMe &&
                            (msg.status === "read" ? (
                              <CheckCheck
                                size={14}
                                className="business-text-primary"
                              />
                            ) : (
                              <Check
                                size={14}
                                className="business-text-subtle"
                              />
                            ))}
                        </div>

                        {/* Message Actions (Hover) */}
                        <div
                          className={`absolute top-0 ${isMe ? (isRTL ? "-right-20" : "-left-20") : isRTL ? "-left-20" : "-right-20"} h-full flex items-center opacity-0 group-hover:opacity-100 transition-opacity gap-1 ${isRTL ? "flex-row-reverse" : ""}`}
                        >
                          <button
                            onClick={() => setReplyingTo(msg)}
                            className="p-1.5 business-bg-panel rounded-full shadow business-text-muted business-hover-primary-text"
                            title={isRTL ? "رد" : "Reply"}
                          >
                            <Reply size={14} />
                          </button>
                          <button
                            onClick={() => handleForwardMessage(msg)}
                            className="p-1.5 business-bg-panel rounded-full shadow business-text-muted business-hover-primary-text"
                            title={isRTL ? "إعادة توجيه" : "Forward"}
                          >
                            <Forward size={14} />
                          </button>
                          {isMe && (
                            <>
                              <button
                                onClick={() => {
                                  setEditingMessage(msg);
                                  setInputText(msg.content);
                                }}
                                className="p-1.5 business-bg-panel rounded-full shadow business-text-muted business-hover-primary-text"
                                title={isRTL ? "تعديل" : "Edit"}
                              >
                                <Edit size={14} />
                              </button>
                              <button
                                onClick={() => handleDeleteMessage(msg.id)}
                                className="p-1.5 business-bg-panel rounded-full shadow business-text-muted business-hover-danger-text"
                                title={isRTL ? "حذف" : "Delete"}
                              >
                                <Trash2 size={14} />
                              </button>
                            </>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-3 business-bg-panel border-t business-border z-10 px-4 py-4">
              {/* Reply Preview */}
              {replyingTo && (
                <div
                  className={`mb-2 p-2 business-bg-primary-soft rounded-lg flex items-center justify-between ${isRTL ? "flex-row-reverse" : ""}`}
                >
                  <div className="flex-1">
                    <p className="text-xs font-semibold business-text-primary">
                      {isRTL ? "رد على" : "Replying to"} {replyingTo.senderName}
                    </p>
                    <p className="text-xs business-text-body truncate">
                      {replyingTo.content || (isRTL ? "وسائط" : "Media")}
                    </p>
                  </div>
                  <button
                    onClick={() => setReplyingTo(null)}
                    className="p-1 business-hover-primary-soft business-hover-primary-solid rounded"
                  >
                    <X size={16} />
                  </button>
                </div>
              )}

              {/* Edit Preview */}
              {editingMessage && (
                <div
                  className={`mb-2 p-2 business-bg-warning-soft rounded-lg flex items-center justify-between ${isRTL ? "flex-row-reverse" : ""}`}
                >
                  <p className="text-xs font-semibold business-text-warning">
                    {isRTL ? "تعديل الرسالة" : "Editing message"}
                  </p>
                  <button
                    onClick={() => {
                      setEditingMessage(null);
                      setInputText("");
                    }}
                    className="p-1 business-hover-warning-soft rounded"
                  >
                    <X size={16} />
                  </button>
                </div>
              )}

              <div
                className={`flex items-end gap-2 w-full ${isRTL ? "flex-row-reverse" : ""}`}
              >
                {/* File Menu */}
                {showFileMenu && (
                  <div
                    className={`absolute bottom-16 ${isRTL ? "right-4" : "left-4"} business-bg-panel rounded-lg shadow-xl border business-border p-2 z-50`}
                  >
                    <div className="grid grid-cols-2 gap-2">
                      <button
                        onClick={() => {
                          fileInputRef.current?.click();
                          setShowFileMenu(false);
                        }}
                        className="p-3 business-hover-soft rounded-lg flex flex-col items-center gap-2"
                      >
                        <ImageIcon
                          size={24}
                          className="business-text-primary"
                        />
                        <span className="text-xs business-text-body">
                          {isRTL ? "صورة" : "Photo"}
                        </span>
                      </button>
                      <button
                        onClick={() => {
                          videoInputRef.current?.click();
                          setShowFileMenu(false);
                        }}
                        className="p-3 business-hover-soft rounded-lg flex flex-col items-center gap-2"
                      >
                        <Video size={24} className="business-text-primary" />
                        <span className="text-xs">
                          {isRTL ? "فيديو" : "Video"}
                        </span>
                      </button>
                      <button
                        onClick={() => {
                          audioInputRef.current?.click();
                          setShowFileMenu(false);
                        }}
                        className="p-3 business-hover-soft rounded-lg flex flex-col items-center gap-2"
                      >
                        <Music size={24} className="business-text-primary" />
                        <span className="text-xs">
                          {isRTL ? "صوت" : "Audio"}
                        </span>
                      </button>
                      <button
                        onClick={() => {
                          documentInputRef.current?.click();
                          setShowFileMenu(false);
                        }}
                        className="p-3 business-hover-soft rounded-lg flex flex-col items-center gap-2"
                      >
                        <File size={24} className="business-text-primary" />
                        <span className="text-xs">
                          {isRTL ? "ملف" : "File"}
                        </span>
                      </button>
                      <button
                        onClick={() => {
                          handleSendLocation();
                          setShowFileMenu(false);
                        }}
                        className="p-3 business-hover-soft rounded-lg flex flex-col items-center gap-2"
                      >
                        <Map size={24} className="business-text-primary" />
                        <span className="text-xs">
                          {isRTL ? "موقع" : "Location"}
                        </span>
                      </button>
                      <button
                        onClick={() => {
                          // TODO: Implement contact sharing
                          alert(
                            isRTL
                              ? "ميزة مشاركة جهة الاتصال قريباً"
                              : "Contact sharing coming soon",
                          );
                          setShowFileMenu(false);
                        }}
                        className="p-3 business-hover-soft rounded-lg flex flex-col items-center gap-2"
                      >
                        <Contact size={24} className="business-text-primary" />
                        <span className="text-xs">
                          {isRTL ? "جهة اتصال" : "Contact"}
                        </span>
                      </button>
                    </div>
                  </div>
                )}

                {/* Hidden File Inputs */}
                <input
                  type="file"
                  ref={fileInputRef}
                  className="hidden"
                  accept="image/*"
                  onChange={(e) => handleFileSelect(e, "image")}
                />
                <input
                  type="file"
                  ref={videoInputRef}
                  className="hidden"
                  accept="video/*"
                  onChange={(e) => handleFileSelect(e, "video")}
                />
                <input
                  type="file"
                  ref={audioInputRef}
                  className="hidden"
                  accept="audio/*"
                  onChange={(e) => handleFileSelect(e, "audio")}
                />
                <input
                  type="file"
                  ref={documentInputRef}
                  className="hidden"
                  onChange={(e) => handleFileSelect(e, "document")}
                />

                <button
                  onClick={() => setShowFileMenu(!showFileMenu)}
                  className="p-3 business-hover-soft rounded-full business-text-subtle business-hover-muted  transition-colors"
                  title={isRTL ? "إرفاق ملف" : "Attach File"}
                >
                  <Paperclip size={24} />
                </button>

                <div
                  className={`flex-1 business-bg-soft border business-border business-control-border rounded-2xl flex items-center ${isRTL ? "pr-4 pl-4" : "pl-4 pr-4"} py-2 business-focus-within-primary business-focus-within-panel transition-all`}
                >
                  <input
                    type="text"
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && !e.shiftKey) {
                        e.preventDefault();
                        if (editingMessage) {
                          handleEditMessage(editingMessage);
                        } else {
                          handleSendMessage();
                        }
                      }
                    }}
                    placeholder={isRTL ? "اكتب رسالة..." : "Write a message..."}
                    className="w-full business-bg-clear border-none focus:ring-0 business-text-strong business-placeholder-muted leading-relaxed"
                  />
                  <Smile
                    size={20}
                    className={`business-text-subtle cursor-pointer business-hover-muted ${isRTL ? "mr-2" : "ml-2"}`}
                  />
                </div>

                {inputText.trim() || editingMessage ? (
                  <button
                    onClick={() =>
                      editingMessage
                        ? handleEditMessage(editingMessage)
                        : handleSendMessage()
                    }
                    className="p-3 business-bg-primary-solid business-text-on-accent rounded-full shadow-lg business-hover-primary-soft0 active:scale-95 transition-all flex items-center justify-center transform"
                  >
                    <Send size={20} className={isRTL ? "mr-0.5" : "ml-0.5"} />
                  </button>
                ) : (
                  <button
                    className="p-3 business-bg-soft-strong business-text-muted rounded-full business-hover-soft transition-colors"
                    title={
                      isRTL
                        ? "رسالة صوتية (قريباً)"
                        : "Record Voice (Coming Soon)"
                    }
                  >
                    <Mic size={24} />
                  </button>
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center business-text-subtle select-none">
            <div className="w-24 h-24 business-bg-soft rounded-full flex items-center justify-center mb-6 shadow-sm">
              <MessageCircle size={48} className="business-text-subtle" />
            </div>
            <p className="text-lg font-medium business-text-subtle">
              {isRTL ? "اختر محادثة للبدء" : "Select a chat to start messaging"}
            </p>
            <p
              className={`text-sm mt-2 max-w-xs text-center ${isRTL ? "text-right" : "text-left"}`}
            >
              {isRTL
                ? "استخدم شريط البحث على اليمين للعثور على عملاء محددين."
                : "Use the search bar on the left to find specific customers."}
            </p>
          </div>
        )}
      </div>

      {/* RIGHT SIDEBAR: Info/CRM - Position based on language */}
      {selectedConversationId && activeConversation && isInfoOpen && (
        <div
          className={`w-[300px] business-bg-panel border-l business-border flex flex-col z-20 shadow-lg animate-in slide-in-from-right duration-300 ${isRTL ? "order-1 border-r border-l-0" : "order-3"}`}
        >
          {/* Header */}
          <div
            className={`p-4 border-b business-border flex justify-between items-center ${isRTL ? "flex-row-reverse" : ""}`}
          >
            <h3 className="font-bold business-text-body">
              {isRTL ? "معلومات المستخدم" : "UserInfo"}
            </h3>
            <button
              onClick={() => setIsInfoOpen(false)}
              className="business-text-subtle business-hover-muted"
            >
              <X size={20} />
            </button>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto p-6 flex flex-col gap-6">
            {/* Avatar */}
            <div className="flex flex-col items-center">
              <div className="w-24 h-24 rounded-full bg-gradient-to-br business-bg-brand-gradient business-text-on-accent flex items-center justify-center text-3xl font-bold shadow-lg mb-3">
                {activeConversation.customerName.charAt(0).toUpperCase()}
              </div>
              <h2 className="text-lg font-bold business-text-strong text-center">
                {activeConversation.customerName}
              </h2>
              <p className="text-sm business-text-muted">
                @
                {activeConversation.customerName
                  .replace(/\s/g, "")
                  .toLowerCase()}
              </p>
              <span className="mt-2 text-xs business-bg-primary-soft business-text-primary px-2 py-1 rounded-full font-medium">
                {isRTL ? "مستخدم تيليجرام" : "Telegram User"}
              </span>
            </div>

            {/* Info List */}
            <div className="space-y-4">
              <div
                className={`flex items-center gap-3 business-text-muted ${isRTL ? "flex-row-reverse" : ""}`}
              >
                <Phone size={18} className="business-text-subtle" />
                <span className="text-sm">+20 10XXXX XXXX</span>
              </div>
              <div
                className={`flex items-center gap-3 business-text-muted ${isRTL ? "flex-row-reverse" : ""}`}
              >
                <Bot size={18} className="business-text-subtle" />
                <span className="text-sm text-wrap break-all">
                  {activeConversation.customerId}
                </span>
              </div>
              <div
                className={`flex items-center gap-3 business-text-muted ${isRTL ? "flex-row-reverse" : ""}`}
              >
                <MapPin size={18} className="business-text-subtle" />
                <span className="text-sm">
                  {isRTL ? "مصر (تقريبي)" : "Egypt (Approx.)"}
                </span>
              </div>
            </div>

            {/* Shared Media Section */}
            <div className="pt-4 border-t business-border">
              <h4
                className={`text-xs font-bold business-text-subtle uppercase tracking-wider mb-3 ${isRTL ? "text-right" : "text-left"}`}
              >
                {isRTL ? "الوسائط المشتركة" : "Shared Media"}
              </h4>
              <div className="grid grid-cols-3 gap-2">
                {mediaMessages.slice(0, 9).map((msg, idx) => (
                  <div
                    key={idx}
                    className="aspect-square business-bg-soft-strong rounded-lg overflow-hidden cursor-pointer hover:opacity-80"
                  >
                    {msg.type === "image" && msg.fileUrl ? (
                      <img
                        src={msg.fileUrl}
                        alt=""
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        {msg.type === "video" && (
                          <Video size={20} className="business-text-subtle" />
                        )}
                        {msg.type === "document" && (
                          <File className="business-text-subtle" size={20} />
                        )}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* Actions */}
            <div className="pt-4 border-t business-border space-y-2">
              <button
                className={`w-full py-2 flex items-center justify-center gap-2 business-text-danger business-bg-danger-soft business-hover-danger-soft rounded-lg transition-colors text-sm font-medium ${isRTL ? "flex-row-reverse" : ""}`}
              >
                <Trash2 size={16} />
                {isRTL ? "حذف المحادثة" : "Delete Conversation"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TelegramConversationsPro;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import {
  Save,
  DollarSign,
  AlertCircle,
  CheckCircle,
  Crown,
  Shield,
  Info,
} from "lucide-react";
import toast from "react-hot-toast";

interface CustomerLoyaltyTier {
  id: string;
  name: string;
  nameAr?: string;
  color: string;
  icon: string;
}

interface CashbackSettings {
  id: string;
  status: "ACTIVE" | "INACTIVE" | "DRAFT" | "SUSPENDED";
  rules: {
    cashbackPercent: number;
    base: "total" | "subtotal";
    trigger: string;
    maxPerOrder?: number;
    tierOverrides?: Record<string, number>;
  };
}

const CashbackSettingsPage: React.FC = () => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [tiers, setTiers] = useState<CustomerLoyaltyTier[]>([]);
  const [settings, setSettings] = useState<{
    cashbackPercent: number;
    base: "total" | "subtotal";
    status: CashbackSettings["status"];
    maxPerOrder: number;
    tierOverrides: Record<string, number>;
  } | null>(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setIsLoading(true);
      const [tiersRes, settingsRes] = await Promise.all([
        apiClient.get("/hr/customer-loyalty/tiers"),
        apiClient.get("/hr/customer-loyalty/cashback/settings"),
      ]);

      setTiers(tiersRes.data.data || []);

      const cs: CashbackSettings | null = settingsRes?.data?.data || null;
      if (cs) {
        setSettings({
          cashbackPercent: cs.rules.cashbackPercent,
          base: cs.rules.base,
          status: cs.status,
          maxPerOrder: cs.rules.maxPerOrder || 0,
          tierOverrides: cs.rules.tierOverrides || {},
        });
      } else {
        // Default state if no settings exist
        setSettings({
          cashbackPercent: 0,
          base: "subtotal",
          status: "INACTIVE",
          maxPerOrder: 0,
          tierOverrides: {},
        });
      }
    } catch (error) {
      console.error("Error fetching cashback data:", error);
      toast.error("حدث خطأ أثناء تحميل الإعدادات");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!settings) return;

    // Validation
    if (settings.cashbackPercent < 0 || settings.cashbackPercent > 100) {
      toast.error("نسبة الكاش باك يجب أن تكون بين 0 و 100");
      return;
    }

    if (settings.maxPerOrder < 0) {
      toast.error("الحد الأقصى للطلب يجب أن يكون رقم إيجابي (أو 0 بدون حد)");
      return;
    }

    // Validate tier overrides
    const invalidOverrides = Object.values(settings.tierOverrides).some(val => val < 0 || val > 100);
    if (invalidOverrides) {
      toast.error("يجب أن تكون نسب المستويات الخاصة بين 0 و 100");
      return;
    }

    try {
      setIsSaving(true);
      await apiClient.put("/hr/customer-loyalty/cashback/settings", settings);
      toast.success("تم حفظ إعدادات الكاش باك بنجاح");
    } catch (error: any) {
      console.error("Error saving cashback settings:", error);
      toast.error(error?.response?.data?.error || "حدث خطأ أثناء حفظ الإعدادات");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  if (!settings) return <div>Failed to load settings</div>;

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            إعدادات الكاش باك
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            تكوين نظام المكافآت المالية للعملاء
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={isSaving}
          className="flex items-center gap-2 px-6 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50"
        >
          {isSaving ? (
            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
          ) : (
            <Save className="w-4 h-4" />
          )}
          حفظ التغييرات
        </button>
      </div>

      {/* Main Settings Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-purple-100 dark:bg-purple-900/30 rounded-lg text-purple-600 dark:text-purple-400">
              <DollarSign className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                الإعدادات الأساسية
              </h2>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                التحكم في نسبة وآلية احتساب الكاش باك
              </p>
            </div>
          </div>
        </div>

        <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Status */}
          <div className="col-span-1">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              حالة النظام
            </label>
            <div className="relative">
              <select
                value={settings.status}
                onChange={(e) =>
                  setSettings({ ...settings, status: e.target.value as any })
                }
                className="w-full pl-4 pr-10 py-2.5 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500"
              >
                <option value="ACTIVE">نشط (Active)</option>
                <option value="INACTIVE">متوقف (Inactive)</option>
                <option value="DRAFT">مسودة (Draft)</option>
              </select>
              <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                {settings.status === "ACTIVE" ? (
                  <CheckCircle className="w-4 h-4 text-green-500" />
                ) : (
                  <AlertCircle className="w-4 h-4" />
                )}
              </div>
            </div>
          </div>

          {/* Calculation Base */}
          <div className="col-span-1">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              طريقة الحساب
            </label>
            <select
              value={settings.base}
              onChange={(e) =>
                setSettings({ ...settings, base: e.target.value as any })
              }
              className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500"
            >
              <option value="subtotal">
                المجموع الفرعي (Subtotal) - قبل الضرائب والشحن
              </option>
              <option value="total">الإجمالي الكلي (Grand Total)</option>
            </select>
          </div>

          {/* Percentage */}
          <div className="col-span-1">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              نسبة الكاش باك (%)
            </label>
            <div className="relative">
              <input
                type="number"
                min="0"
                max="100"
                step="0.1"
                value={settings.cashbackPercent}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    cashbackPercent: Number(e.target.value),
                  })
                }
                className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500"
              />
              <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">
                %
              </div>
            </div>
            <p className="mt-1.5 text-xs text-gray-500">
              النسبة الافتراضية لجميع العملاء.
            </p>
          </div>

          {/* Max Limit */}
          <div className="col-span-1">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              الحد الأقصى للطلب الواحد
            </label>
            <div className="relative">
              <input
                type="number"
                min="0"
                value={settings.maxPerOrder}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    maxPerOrder: Number(e.target.value),
                  })
                }
                className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500"
                placeholder="0 = بدون حد"
              />
              <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 text-xs">
                عملة المتجر
              </div>
            </div>
            <p className="mt-1.5 text-xs text-gray-500">
              اتركه 0 إذا كنت لا تريد وضع حد أقصى.
            </p>
          </div>
        </div>
      </div>

      {/* Tiers Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-yellow-100 dark:bg-yellow-900/30 rounded-lg text-yellow-600 dark:text-yellow-400">
                <Crown className="w-5 h-5" />
              </div>
              <div>
                <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                  تخصيص المستويات (Advanced)
                </h2>
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  تجاوز النسبة الافتراضية لعملاء محددين
                </p>
              </div>
            </div>
          </div>
        </div>

        <div className="p-6">
          {tiers.length === 0 ? (
            <div className="text-center py-8 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-dashed border-gray-200 dark:border-gray-700">
              <Info className="w-8 h-8 text-gray-400 mx-auto mb-2" />
              <p className="text-gray-500 dark:text-gray-400">
                لا توجد مستويات عملاء معرفة حالياً.
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {tiers.map((tier) => (
                <div
                  key={tier.id}
                  className="relative group bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4 hover:border-purple-500/50 transition-colors"
                >
                  <div className="flex items-start justify-between mb-3">
                    <span className="font-medium text-gray-900 dark:text-white flex items-center gap-2">
                      <span
                        className="w-2 h-2 rounded-full"
                        style={{ backgroundColor: tier.color }}
                      ></span>
                      {tier.nameAr || tier.name}
                    </span>
                  </div>

                  <div className="relative">
                    <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">
                      نسبة خاصة
                    </label>
                    <input
                      type="number"
                      min="0"
                      max="100"
                      placeholder={`${settings.cashbackPercent}% (Default)`}
                      value={settings.tierOverrides?.[tier.id] ?? ""}
                      onChange={(e) => {
                        const val = e.target.value;
                        const newOverrides = { ...settings.tierOverrides };
                        if (val === "") {
                           delete newOverrides[tier.id];
                        } else {
                           const numVal = Number(val);
                           if (!isNaN(numVal)) {
                             newOverrides[tier.id] = numVal;
                           }
                        }
                        setSettings({
                          ...settings,
                          tierOverrides: newOverrides,
                        });
                      }}
                      className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-600 rounded-lg text-sm text-gray-900 dark:text-white"
                    />
                    <div className="absolute left-3 top-[26px] text-gray-400 text-xs">
                      %
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          <div className="mt-4 flex items-start gap-3 p-4 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 rounded-lg text-sm">
            <Shield className="w-5 h-5 flex-shrink-0 mt-0.5" />
            <p>
              <strong>ملاحظة:</strong> إذا قمت بتعيين نسبة خاصة لمستوى معين،
              سيتم تجاهل "النسبة الافتراضية" لهذا المستوى واستخدام النسبة
              المحددة هنا.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CashbackSettingsPage;

import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  ArrowRightIcon,
  UserIcon,
  PhoneIcon,
  EnvelopeIcon,
  MapPinIcon,
  CheckIcon,
  PlusIcon,
} from "@heroicons/react/24/outline";
import { apiClient } from "../../services/apiClient";

interface CustomerFormData {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  country: string;
  status: string;
  notes: string;
  birthday: string;
}

const CustomerCreate: React.FC = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();

  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  const [formData, setFormData] = useState<CustomerFormData>({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    address: "",
    city: "",
    country: "",
    status: "LEAD",
    notes: "",
    birthday: "",
  });

  const handleChange = (
    e: React.ChangeEvent<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >,
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.firstName.trim()) {
      setError("الاسم الأول مطلوب");
      return;
    }
    setIsSaving(true);
    setError("");
    setSuccessMessage("");

    try {
      const payload: any = {
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email || undefined,
        phone: formData.phone || undefined,
        address: formData.address || undefined,
        city: formData.city || undefined,
        country: formData.country || undefined,
        status: formData.status,
        notes: formData.notes || undefined,
      };

      // إضافة تاريخ الميلاد في metadata
      if (formData.birthday) {
        payload.metadata = JSON.stringify({ birthday: formData.birthday });
      }

      const response = await apiClient.post("/customers", payload);
      const newId = response.data?.data?.id || response.data?.id;
      setSuccessMessage("تم إضافة العميل بنجاح");
      setTimeout(() => {
        if (newId) {
          navigate(`/customers/${newId}`);
        } else {
          navigate("/customers");
        }
      }, 1200);
    } catch (err: any) {
      console.error("Error creating customer:", err);
      setError(err.response?.data?.message || "فشل في إضافة العميل");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          to="/customers"
          className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
        >
          <ArrowRightIcon className="h-5 w-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <PlusIcon className="h-6 w-6 text-indigo-500" />
            إضافة عميل جديد
          </h1>
          <p className="text-sm text-gray-500 mt-1">
            أدخل بيانات العميل الجديد
          </p>
        </div>
      </div>

      {/* Error */}
      {error && (
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-700 text-red-700 dark:text-red-300 px-4 py-3 rounded-lg">
          {error}
        </div>
      )}

      {/* Success */}
      {successMessage && (
        <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-700 text-green-700 dark:text-green-300 px-4 py-3 rounded-lg flex items-center gap-2">
          <CheckIcon className="h-5 w-5" />
          {successMessage}
        </div>
      )}

      {/* Form */}
      <form
        onSubmit={handleSubmit}
        className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 space-y-6"
      >
        {/* Basic Info */}
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <UserIcon className="h-5 w-5 text-indigo-500" />
            المعلومات الأساسية
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                الاسم الأول <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                required
                autoFocus
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
                placeholder="مثال: محمد"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                اسم العائلة
              </label>
              <input
                type="text"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
                placeholder="مثال: أحمد"
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                تاريخ الميلاد
                <span className="text-xs text-gray-400 mr-2">(لإشعارات أعياد الميلاد)</span>
              </label>
              <input
                type="date"
                name="birthday"
                value={formData.birthday}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
              />
            </div>
          </div>
        </div>

        {/* Contact Info */}
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <PhoneIcon className="h-5 w-5 text-green-500" />
            معلومات الاتصال
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                رقم الهاتف
              </label>
              <input
                type="tel"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
                placeholder="01xxxxxxxxx"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                البريد الإلكتروني
              </label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
                placeholder="example@email.com"
              />
            </div>
          </div>
        </div>

        {/* Address */}
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <MapPinIcon className="h-5 w-5 text-red-500" />
            العنوان والحالة
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="md:col-span-3">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                العنوان
              </label>
              <input
                type="text"
                name="address"
                value={formData.address}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
                placeholder="الشارع، المنطقة"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                المدينة
              </label>
              <input
                type="text"
                name="city"
                value={formData.city}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                الدولة
              </label>
              <input
                type="text"
                name="country"
                value={formData.country}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                الحالة
              </label>
              <select
                name="status"
                value={formData.status}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
              >
                <option value="LEAD">عميل محتمل</option>
                <option value="ACTIVE">نشط</option>
                <option value="INACTIVE">غير نشط</option>
                <option value="BLOCKED">محظور</option>
              </select>
            </div>
          </div>
        </div>

        {/* Notes */}
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            ملاحظات
          </label>
          <textarea
            name="notes"
            value={formData.notes}
            onChange={handleChange}
            rows={3}
            className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white"
            placeholder="ملاحظات إضافية عن العميل..."
          />
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
          <Link
            to="/customers"
            className="px-6 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            إلغاء
          </Link>
          <button
            type="submit"
            disabled={isSaving}
            className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 inline-flex items-center gap-2"
          >
            {isSaving ? (
              <>
                <span className="animate-spin inline-block h-4 w-4 border-2 border-white border-t-transparent rounded-full" />
                جاري الحفظ...
              </>
            ) : (
              <>
                <CheckIcon className="h-4 w-4" />
                إضافة العميل
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

export default CustomerCreate;

import React, { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  ArrowRightIcon,
  PencilIcon,
  TrashIcon,
  ChatBubbleLeftRightIcon,
  ShoppingBagIcon,
  ClockIcon,
  DocumentTextIcon,
  UserIcon,
  PhoneIcon,
  EnvelopeIcon,
  MapPinIcon,
  TagIcon,
  PlusIcon,
  XMarkIcon,
  ArrowDownTrayIcon,
  ExclamationTriangleIcon,
  CalendarIcon,
} from "@heroicons/react/24/outline";
import { apiClient } from "../../services/apiClient";
import LoadingSpinner from "../../components/LoadingSpinner";
import { useDateFormat } from "../../hooks/useDateFormat";
import { formatCurrency } from "../../utils/currency";

interface CustomerDetailsData {
  customer: {
    id: string;
    firstName: string;
    lastName: string;
    email?: string;
    phone?: string;
    address?: string;
    city?: string;
    country?: string;
    tags: string[];
    notes?: string;
    birthday?: string;
    status: string;
    customerRating?: string;
    createdAt: string;
    updatedAt: string;
  };
  stats: {
    ordersCount: number;
    conversationsCount: number;
    totalSpent: number;
    averageOrderValue: number;
  };
  recentOrders: Array<{
    id: string;
    orderNumber: string;
    status: string;
    total: number;
    createdAt: string;
  }>;
  recentConversations: Array<{
    id: string;
    channel: string;
    status: string;
    lastMessageAt: string;
    createdAt: string;
  }>;
  notes: Array<{
    id: string;
    content: string;
    createdAt: string;
    author?: {
      firstName: string;
      lastName: string;
    };
  }>;
  activities: Array<{
    type: string;
    id: string;
    title: string;
    status?: string;
    value?: number;
    content?: string;
    author?: string;
    timestamp: string;
  }>;
}

const CustomerDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { t } = useTranslation();
  const { formatDate } = useDateFormat();
  const navigate = useNavigate();

  const [data, setData] = useState<CustomerDetailsData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [activeTab, setActiveTab] = useState<
    "info" | "orders" | "conversations" | "notes" | "activity"
  >("info");
  const [newNote, setNewNote] = useState("");
  const [isAddingNote, setIsAddingNote] = useState(false);

  // New state for additional features
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [newTag, setNewTag] = useState("");
  const [customerTags, setCustomerTags] = useState<string[]>([]);
  const [deletingNoteId, setDeletingNoteId] = useState<string | null>(null);
  
  // Birthday state
  const [editingBirthday, setEditingBirthday] = useState(false);
  const [tempBirthday, setTempBirthday] = useState("");

  useEffect(() => {
    loadCustomerDetails();
  }, [id]);

  // Initialize tags when data loads
  useEffect(() => {
    if (data?.customer?.tags) {
      try {
        const parsedTags =
          typeof data.customer.tags === "string"
            ? JSON.parse(data.customer.tags)
            : data.customer.tags;
        setCustomerTags(Array.isArray(parsedTags) ? parsedTags : []);
      } catch {
        setCustomerTags([]);
      }
    }
  }, [data?.customer?.tags]);

  const loadCustomerDetails = async () => {
    try {
      setIsLoading(true);
      setError("");
      const response = await apiClient.get(`/customers/${id}`);
      console.log(
        "Customer API Response:",
        JSON.stringify(response.data, null, 2),
      );

      // Normalize the response data structure
      let customerData = response.data?.data || response.data;

      // If the response is { customer: {...} } use it directly
      // If the response IS the customer object (has firstName), wrap it
      if (customerData && !customerData.customer && customerData.firstName) {
        customerData = {
          customer: customerData,
          stats: {
            ordersCount: 0,
            conversationsCount: 0,
            totalSpent: 0,
            averageOrderValue: 0,
          },
          recentOrders: [],
          recentConversations: [],
          notes: [],
          activities: [],
        };
      }

      if (customerData?.customer?.metadata) {
        try {
          const parsedMeta = typeof customerData.customer.metadata === 'string' 
            ? JSON.parse(customerData.customer.metadata) 
            : customerData.customer.metadata;
          
          if (parsedMeta) {
            customerData.customer.address = customerData.customer.address || parsedMeta.address;
            customerData.customer.city = customerData.customer.city || parsedMeta.city;
            customerData.customer.country = customerData.customer.country || parsedMeta.country;
            if (parsedMeta.birthday) {
              customerData.customer.birthday = parsedMeta.birthday;
            }
          }
        } catch (e) {
          console.error("Error parsing customer metadata:", e);
        }
      }

      console.log(
        "Normalized customer data:",
        JSON.stringify(customerData, null, 2),
      );
      setData(customerData);
    } catch (err: any) {
      console.error("Error loading customer:", err);
      setError(
        err.response?.data?.message ||
        err.message ||
        t("customers.loadError"),
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddNote = async () => {
    if (!newNote.trim()) return;
    setIsAddingNote(true);
    try {
      await apiClient.post(`/customers/${id}/notes`, { content: newNote });
      setNewNote("");
      loadCustomerDetails(); // Reload to get fresh notes
    } catch (err: any) {
      console.error("Error adding note:", err);
    } finally {
      setIsAddingNote(false);
    }
  };

  // 🗑️ Delete customer handler
  const handleDeleteCustomer = async () => {
    setIsDeleting(true);
    try {
      await apiClient.delete(`/customers/${id}`);
      navigate("/customers", { replace: true });
    } catch (err: any) {
      console.error("Error deleting customer:", err);
      alert(err.response?.data?.message || t("customers.deleteError"));
    } finally {
      setIsDeleting(false);
      setShowDeleteModal(false);
    }
  };

  // 🗑️ Delete note handler
  const handleDeleteNote = async (noteId: string) => {
    setDeletingNoteId(noteId);
    try {
      await apiClient.delete(`/customers/notes/${noteId}`);
      loadCustomerDetails(); // Reload to refresh notes
    } catch (err: any) {
      console.error("Error deleting note:", err);
      alert(err.response?.data?.message || t("customers.deleteNoteError"));
    } finally {
      setDeletingNoteId(null);
    }
  };

  // 🏷️ Add tag handler
  const handleAddTag = async () => {
    if (!newTag.trim()) return;
    const updatedTags = [...customerTags, newTag.trim()];
    try {
      await apiClient.put(`/customers/${id}/tags`, { tags: updatedTags });
      setCustomerTags(updatedTags);
      setNewTag("");
    } catch (err: any) {
      console.error("Error adding tag:", err);
      alert(err.response?.data?.message || t("customers.addTagError"));
    }
  };

  // 🏷️ Remove tag handler
  const handleRemoveTag = async (tagToRemove: string) => {
    const updatedTags = customerTags.filter((tag) => tag !== tagToRemove);
    try {
      await apiClient.put(`/customers/${id}/tags`, { tags: updatedTags });
      setCustomerTags(updatedTags);
    } catch (err: any) {
      console.error("Error removing tag:", err);
      alert(err.response?.data?.message || t("customers.removeTagError"));
    }
  };

  // 🎂 Save birthday inline
  const handleSaveBirthday = async () => {
    if (!customer) return;
    try {
      await apiClient.put(`/customers/${id}`, {
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        phone: customer.phone,
        address: customer.address,
        city: customer.city,
        country: customer.country,
        status: customer.status,
        notes: customer.notes,
        birthday: tempBirthday
      });
      setEditingBirthday(false);
      loadCustomerDetails();
    } catch (err: any) {
      console.error("Error saving birthday:", err);
      alert(err.response?.data?.message || "حدث خطأ أثناء حفظ تاريخ الميلاد");
    }
  };

  // 📤 Export customer data
  const handleExportCustomer = () => {
    if (!data) return;
    const exportData = {
      customer: data.customer,
      stats: data.stats,
      orders: data.recentOrders,
      conversations: data.recentConversations,
      notes: data.notes,
      activities: data.activities,
      exportedAt: new Date().toISOString(),
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `customer_${data.customer.firstName}_${data.customer.lastName}_${new Date().toISOString().split("T")[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // 💬 Start WhatsApp conversation
  const handleStartWhatsApp = () => {
    const phone = data?.customer?.phone;
    if (phone) {
      // Remove any non-digit characters and ensure it starts with country code
      const cleanPhone = phone.replace(/\D/g, "");
      window.open(`https://wa.me/${cleanPhone}`, "_blank");
    }
  };

  const getStatusBadge = (status: string) => {
    const colors: Record<string, string> = {
      LEAD: "bg-yellow-100 text-yellow-800",
      ACTIVE: "bg-green-100 text-green-800",
      INACTIVE: "bg-gray-100 text-gray-800",
      VIP: "bg-purple-100 text-purple-800",
      BLOCKED: "bg-red-100 text-red-800",
    };
    return colors[status] || "bg-gray-100 text-gray-800";
  };

  const getRatingBadge = (rating?: string) => {
    if (!rating) return null;
    const r = rating.toUpperCase();

    // Define styles mapping
    const styles: Record<string, string> = {
      EXCELLENT: "bg-purple-100 text-purple-700",
      GOOD: "bg-blue-100 text-blue-700",
      AVERAGE: "bg-gray-100 text-gray-700",
      BAD: "bg-red-100 text-red-700",
    };

    // Define translation key mapping
    const translationKeys: Record<string, string> = {
      EXCELLENT: "customers.rating.excellent",
      GOOD: "customers.rating.good",
      AVERAGE: "customers.rating.average",
      BAD: "customers.rating.bad",
    };

    const style = styles[r] || "bg-gray-100 text-gray-700";
    const key = translationKeys[r];

    if (!key) return null;

    return (
      <span className={`px-2 py-1 rounded-full text-xs font-medium ${style}`}>
        {t(key)}
      </span>
    );
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  if (error || !data || !data.customer) {
    return (
      <div className="text-center py-12">
        <p className="text-red-500">{error || t("customers.notFound")}</p>
        <Link
          to="/customers"
          className="text-indigo-600 hover:underline mt-4 inline-block"
        >
          {t("common.backToList")}
        </Link>
      </div>
    );
  }

  const customer = data.customer || {};
  const stats = data.stats || {
    ordersCount: 0,
    conversationsCount: 0,
    totalSpent: 0,
    averageOrderValue: 0,
  };
  const recentOrders = data.recentOrders || [];
  const recentConversations = data.recentConversations || [];
  const notes = data.notes || [];
  const activities = data.activities || [];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link to="/customers" className="text-gray-500 hover:text-gray-700">
            <ArrowRightIcon className="h-5 w-5" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
              {customer.firstName} {customer.lastName}
            </h1>
            <div className="flex gap-2 mt-1">
              <span
                className={`px-2 py-1 rounded-full text-xs ${getStatusBadge(customer.status)}`}
              >
                {customer.status}
              </span>
              {getRatingBadge(customer.customerRating)}
            </div>
          </div>
        </div>
        <div className="flex gap-2 flex-wrap">
          {/* WhatsApp Button */}
          {customer.phone && (
            <button
              onClick={handleStartWhatsApp}
              className="inline-flex items-center px-4 py-2 border border-green-300 rounded-md text-sm font-medium text-green-700 bg-white hover:bg-green-50"
            >
              <ChatBubbleLeftRightIcon className="h-4 w-4 ml-2" />
              WhatsApp
            </button>
          )}
          {/* Export Button */}
          <button
            onClick={handleExportCustomer}
            className="inline-flex items-center px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 bg-white hover:bg-gray-50"
          >
            <ArrowDownTrayIcon className="h-4 w-4 ml-2" />
            {t("common.export")}
          </button>
          {/* Edit Button */}
          <button
            onClick={() => navigate(`/customers/${id}/edit`)}
            className="inline-flex items-center px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 bg-white hover:bg-gray-50"
          >
            <PencilIcon className="h-4 w-4 ml-2" />
            {t("common.edit")}
          </button>
          {/* Delete Button */}
          <button
            onClick={() => setShowDeleteModal(true)}
            className="inline-flex items-center px-4 py-2 border border-red-300 rounded-md text-sm font-medium text-red-700 bg-white hover:bg-red-50"
          >
            <TrashIcon className="h-4 w-4 ml-2" />
            {t("common.delete")}
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <div className="flex items-center gap-3">
            <ShoppingBagIcon className="h-8 w-8 text-indigo-500" />
            <div>
              <p className="text-sm text-gray-500">{t("sidebar.orders")}</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats.ordersCount}
              </p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <div className="flex items-center gap-3">
            <ChatBubbleLeftRightIcon className="h-8 w-8 text-green-500" />
            <div>
              <p className="text-sm text-gray-500">{t("sidebar.conversations")}</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {stats.conversationsCount}
              </p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <div className="flex items-center gap-3">
            <div className="h-8 w-8 rounded-full bg-yellow-100 flex items-center justify-center text-yellow-600">
              $
            </div>
            <div>
              <p className="text-sm text-gray-500">{t("customers.totalSpent")}</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {formatCurrency(stats.totalSpent)}
              </p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <div className="flex items-center gap-3">
            <div className="h-8 w-8 rounded-full bg-purple-100 flex items-center justify-center text-purple-600">
              ~
            </div>
            <div>
              <p className="text-sm text-gray-500">{t("customers.averageOrder")}</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {formatCurrency(stats.averageOrderValue)}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow">
        <div className="border-b border-gray-200 dark:border-gray-700">
          <nav className="flex -mb-px">
            {[
              { key: "info", label: t("customers.tabs.info"), icon: UserIcon },
              { key: "orders", label: t("orders.title"), icon: ShoppingBagIcon },
              {
                key: "conversations",
                label: t("sidebar.conversations"),
                icon: ChatBubbleLeftRightIcon,
              },
              { key: "notes", label: t("customers.tabs.notes"), icon: DocumentTextIcon },
              { key: "activity", label: t("customers.tabs.activity"), icon: ClockIcon },
            ].map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key as any)}
                className={`flex items-center gap-2 px-6 py-4 text-sm font-medium border-b-2 ${activeTab === tab.key
                  ? "border-indigo-500 text-indigo-600"
                  : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
                  }`}
              >
                <tab.icon className="h-4 w-4" />
                {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="p-6">
          {/* Info Tab */}
          {activeTab === "info" && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-4">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                  {t("customers.contactInfo")}
                </h3>
                <div className="space-y-3">
                  {customer.phone && (
                    <div className="flex items-center gap-3 text-gray-600 dark:text-gray-300">
                      <PhoneIcon className="h-5 w-5" />
                      <span>{customer.phone}</span>
                    </div>
                  )}
                  {customer.email && (
                    <div className="flex items-center gap-3 text-gray-600 dark:text-gray-300">
                      <EnvelopeIcon className="h-5 w-5" />
                      <span>{customer.email}</span>
                    </div>
                  )}
                  {(customer.address || customer.city || customer.country) && (
                    <div className="flex items-center gap-3 text-gray-600 dark:text-gray-300">
                      <MapPinIcon className="h-5 w-5" />
                      <span>
                        {[customer.address, customer.city, customer.country]
                          .filter(Boolean)
                          .join(", ")}
                      </span>
                    </div>
                  )}
                  {/* Birthday Inline Editor */}
                  <div className="flex items-center gap-3 text-gray-600 dark:text-gray-300">
                    <CalendarIcon className="h-5 w-5" />
                    {editingBirthday ? (
                      <div className="flex gap-2 w-full max-w-xs items-center">
                        <input
                          type="date"
                          value={tempBirthday}
                          onChange={(e) => setTempBirthday(e.target.value)}
                          className="flex-1 px-3 py-1 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 focus:ring-indigo-500 focus:border-indigo-500"
                        />
                        <button
                          onClick={handleSaveBirthday}
                          className="px-3 py-1 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm"
                        >
                          حفظ
                        </button>
                        <button
                          onClick={() => setEditingBirthday(false)}
                          className="px-3 py-1 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 text-sm"
                        >
                          إلغاء
                        </button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2 group">
                        <span className="text-sm">
                          {customer.birthday
                            ? new Date(customer.birthday).toLocaleDateString("ar-EG")
                            : "تاريخ الميلاد غير مسجل"}
                        </span>
                        <button
                          onClick={() => {
                            setTempBirthday(customer.birthday || "");
                            setEditingBirthday(true);
                          }}
                          className="text-gray-400 hover:text-indigo-600 opacity-0 group-hover:opacity-100 transition-opacity"
                          title="إضافة / تعديل تاريخ الميلاد"
                        >
                          <PencilIcon className="h-4 w-4" />
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
              <div className="space-y-4">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                  {t("customers.tagsLabel")}
                </h3>
                <div className="flex flex-wrap gap-2 mb-3">
                  {customerTags.length > 0 ? (
                    customerTags.map((tag, i) => (
                      <span
                        key={i}
                        className="inline-flex items-center gap-1 px-3 py-1 bg-gray-100 text-gray-800 rounded-full text-sm group"
                      >
                        <TagIcon className="h-3 w-3" />
                        {tag}
                        <button
                          onClick={() => handleRemoveTag(tag)}
                          className="ml-1 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          <XMarkIcon className="h-3 w-3" />
                        </button>
                      </span>
                    ))
                  ) : (
                    <p className="text-gray-500">{t("customers.noTags")}</p>
                  )}
                </div>
                {/* Add new tag */}
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={newTag}
                    onChange={(e) => setNewTag(e.target.value)}
                    onKeyPress={(e) => e.key === "Enter" && handleAddTag()}
                    placeholder={t("customers.addTagPlaceholder")}
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600"
                  />
                  <button
                    onClick={handleAddTag}
                    disabled={!newTag.trim()}
                    className="inline-flex items-center px-3 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 text-sm"
                  >
                    <PlusIcon className="h-4 w-4" />
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Orders Tab */}
          {activeTab === "orders" && (
            <div>
              {recentOrders.length > 0 ? (
                <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                  <thead>
                    <tr>
                      <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                        {t("orders.orderNumber")}
                      </th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                        {t("common.status")}
                      </th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                        {t("orders.amount")}
                      </th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                        {t("common.date")}
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                    {recentOrders.map((order) => (
                      <tr
                        key={order.id}
                        className="hover:bg-gray-50 dark:hover:bg-gray-700"
                      >
                        <td className="px-4 py-3">
                          <Link
                            to={`/orders/${encodeURIComponent(String(order.id))}`}
                            className="text-indigo-600 hover:underline"
                          >
                            #{order.orderNumber}
                          </Link>
                        </td>
                        <td className="px-4 py-3">
                          <span className="px-2 py-1 rounded text-xs bg-gray-100">
                            {order.status}
                          </span>
                        </td>
                        <td className="px-4 py-3">
                          {formatCurrency(order.total)}
                        </td>
                        <td className="px-4 py-3 text-gray-500">
                          {formatDate(order.createdAt)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p className="text-center text-gray-500 py-8">{t("customers.noOrders")}</p>
              )}
            </div>
          )}

          {/* Conversations Tab */}
          {activeTab === "conversations" && (
            <div>
              {recentConversations.length > 0 ? (
                <div className="space-y-3">
                  {recentConversations.map((conv) => (
                    <div
                      key={conv.id}
                      className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-lg"
                    >
                      <div className="flex items-center gap-3">
                        <ChatBubbleLeftRightIcon className="h-5 w-5 text-gray-400" />
                        <div>
                          <p className="font-medium text-gray-900 dark:text-white">
                            {conv.channel}
                          </p>
                          <p className="text-sm text-gray-500">{conv.status}</p>
                        </div>
                      </div>
                      <p className="text-sm text-gray-500">
                        {formatDate(conv.lastMessageAt || conv.createdAt)}
                      </p>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-center text-gray-500 py-8">
                  {t("customers.noConversations")}
                </p>
              )}
            </div>
          )}

          {/* Notes Tab */}
          {activeTab === "notes" && (
            <div className="space-y-4">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newNote}
                  onChange={(e) => setNewNote(e.target.value)}
                  placeholder={t("customers.notesPlaceholder")}
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600"
                />
                <button
                  onClick={handleAddNote}
                  disabled={isAddingNote || !newNote.trim()}
                  className="inline-flex items-center px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50"
                >
                  <PlusIcon className="h-4 w-4 ml-2" />
                  {t("common.add")}
                </button>
              </div>
              {notes.length > 0 ? (
                <div className="space-y-3">
                  {notes.map((note) => (
                    <div
                      key={note.id}
                      className="p-4 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg border-r-4 border-yellow-400 relative group"
                    >
                      <button
                        onClick={() => handleDeleteNote(note.id)}
                        disabled={deletingNoteId === note.id}
                        className="absolute top-2 left-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity disabled:opacity-50"
                      >
                        {deletingNoteId === note.id ? (
                          <span className="animate-spin">⏳</span>
                        ) : (
                          <TrashIcon className="h-4 w-4" />
                        )}
                      </button>
                      <p className="text-gray-800 dark:text-gray-200">
                        {note.content}
                      </p>
                      <div className="mt-2 text-sm text-gray-500">
                        {note.author &&
                          `${note.author.firstName} ${note.author.lastName} • `}
                        {formatDate(note.createdAt)}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-center text-gray-500 py-8">
                  {t("customers.noNotes")}
                </p>
              )}
            </div>
          )}

          {/* Activity Tab */}
          {activeTab === "activity" && (
            <div>
              {activities.length > 0 ? (
                <div className="relative">
                  <div className="absolute right-4 top-0 bottom-0 w-0.5 bg-gray-200 dark:bg-gray-700" />
                  <div className="space-y-4">
                    {activities.map((activity, i) => (
                      <div key={i} className="relative pr-10">
                        <div
                          className={`absolute right-2 w-4 h-4 rounded-full ${activity.type === "order"
                            ? "bg-indigo-500"
                            : activity.type === "conversation"
                              ? "bg-green-500"
                              : "bg-yellow-500"
                            }`}
                        />
                        <div className="bg-gray-50 dark:bg-gray-700 p-4 rounded-lg">
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-medium text-gray-900 dark:text-white">
                                {activity.title}
                              </p>
                              {activity.status && (
                                <span className="text-sm text-gray-500">
                                  {activity.status}
                                </span>
                              )}
                              {activity.content && (
                                <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">
                                  {activity.content}
                                </p>
                              )}
                            </div>
                            <p className="text-xs text-gray-500">
                              {formatDate(activity.timestamp)}
                            </p>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <p className="text-center text-gray-500 py-8">{t("customers.noActivities")}</p>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-gray-800 rounded-lg p-6 max-w-md w-full mx-4 shadow-xl">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-2 bg-red-100 rounded-full">
                <ExclamationTriangleIcon className="h-6 w-6 text-red-600" />
              </div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                {t("customers.deleteConfirmTitle")}
              </h3>
            </div>
            <p className="text-gray-600 dark:text-gray-300 mb-6">
              {t("customers.deleteConfirmMessage", { name: `${customer.firstName} ${customer.lastName}` })}
              <br />
              <span className="text-red-500 text-sm">
                {t("customers.deleteWarning")}
              </span>
            </p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setShowDeleteModal(false)}
                disabled={isDeleting}
                className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 dark:text-gray-300 dark:border-gray-600 dark:hover:bg-gray-700"
              >
                إلغاء
              </button>
              <button
                onClick={handleDeleteCustomer}
                disabled={isDeleting}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50 inline-flex items-center gap-2"
              >
                {isDeleting ? (
                  <>
                    <span className="animate-spin">⏳</span>
                    جاري الحذف...
                  </>
                ) : (
                  <>
                    <TrashIcon className="h-4 w-4" />
                    حذف العميل
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerDetails;

import React, { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  ArrowRightIcon,
  UserIcon,
  PhoneIcon,
  EnvelopeIcon,
  MapPinIcon,
  CheckIcon,
} from "@heroicons/react/24/outline";
import { apiClient } from "../../services/apiClient";
import LoadingSpinner from "../../components/LoadingSpinner";

interface CustomerFormData {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  country: string;
  status: string;
  notes: string;
  birthday: string;
}

const CustomerEdit: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { t } = useTranslation();
  const navigate = useNavigate();

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  const [formData, setFormData] = useState<CustomerFormData>({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    address: "",
    city: "",
    country: "",
    status: "LEAD",
    notes: "",
    birthday: "",
  });

  useEffect(() => {
    loadCustomer();
  }, [id]);

  const loadCustomer = async () => {
    try {
      setIsLoading(true);
      setError("");
      const response = await apiClient.get(`/customers/${id}`);
      const customerData =
        response.data?.data?.customer || response.data?.data || response.data;

      let birthdayVal = "";
      let addressVal = "";
      let cityVal = "";
      let countryVal = "";

      try {
        if (customerData.metadata) {
          const parsedMeta = typeof customerData.metadata === 'string' ? JSON.parse(customerData.metadata) : customerData.metadata;
          if (parsedMeta) {
            if (parsedMeta.birthday) birthdayVal = parsedMeta.birthday;
            if (parsedMeta.address) addressVal = parsedMeta.address;
            if (parsedMeta.city) cityVal = parsedMeta.city;
            if (parsedMeta.country) countryVal = parsedMeta.country;
          }
        }
      } catch (e) {
        // ignore
      }

      setFormData({
        firstName: customerData.firstName || "",
        lastName: customerData.lastName || "",
        email: customerData.email || "",
        phone: customerData.phone || "",
        address: customerData.address || addressVal || "",
        city: customerData.city || cityVal || "",
        country: customerData.country || countryVal || "",
        status: customerData.status || "LEAD",
        notes: customerData.notes || "",
        birthday: birthdayVal,
      });
    } catch (err: any) {
      console.error("Error loading customer:", err);
      setError(err.response?.data?.message || "فشل في تحميل بيانات العميل");
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (
    e: React.ChangeEvent<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >,
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    setError("");
    setSuccessMessage("");

    try {
      await apiClient.put(`/customers/${id}`, formData);
      setSuccessMessage("تم حفظ التغييرات بنجاح");
      setTimeout(() => {
        navigate(`/customers/${id}`);
      }, 1500);
    } catch (err: any) {
      console.error("Error saving customer:", err);
      setError(err.response?.data?.message || "فشل في حفظ التغييرات");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          to={`/customers/${id}`}
          className="text-gray-500 hover:text-gray-700"
        >
          <ArrowRightIcon className="h-5 w-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            تعديل بيانات العميل
          </h1>
          <p className="text-sm text-gray-500 mt-1">
            {formData.firstName} {formData.lastName}
          </p>
        </div>
      </div>

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
          {error}
        </div>
      )}

      {/* Success Message */}
      {successMessage && (
        <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-lg flex items-center gap-2">
          <CheckIcon className="h-5 w-5" />
          {successMessage}
        </div>
      )}

      {/* Form */}
      <form
        onSubmit={handleSubmit}
        className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 space-y-6"
      >
        {/* Basic Info */}
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <UserIcon className="h-5 w-5 text-indigo-500" />
            المعلومات الأساسية
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                الاسم الأول *
              </label>
              <input
                type="text"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                required
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                اسم العائلة *
              </label>
              <input
                type="text"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                required
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                تاريخ الميلاد (لإشعارات أعياد الميلاد)
              </label>
              <input
                type="date"
                name="birthday"
                value={formData.birthday}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
              />
            </div>
          </div>
        </div>

        {/* Contact Info */}
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <PhoneIcon className="h-5 w-5 text-green-500" />
            معلومات الاتصال
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                رقم الهاتف
              </label>
              <input
                type="tel"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
                placeholder="01xxxxxxxxx"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                البريد الإلكتروني
              </label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
                placeholder="example@email.com"
              />
            </div>
          </div>
        </div>

        {/* Address Info */}
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <MapPinIcon className="h-5 w-5 text-red-500" />
            العنوان
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="md:col-span-3">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                العنوان
              </label>
              <input
                type="text"
                name="address"
                value={formData.address}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
                placeholder="الشارع، المنطقة"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                المدينة
              </label>
              <input
                type="text"
                name="city"
                value={formData.city}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                الدولة
              </label>
              <input
                type="text"
                name="country"
                value={formData.country}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                الحالة
              </label>
              <select
                name="status"
                value={formData.status}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
              >
                <option value="LEAD">عميل محتمل</option>
                <option value="ACTIVE">نشط</option>
                <option value="INACTIVE">غير نشط</option>
                <option value="BLOCKED">محظور</option>
              </select>
            </div>
          </div>
        </div>

        {/* Notes */}
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            ملاحظات
          </label>
          <textarea
            name="notes"
            value={formData.notes}
            onChange={handleChange}
            rows={4}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            placeholder="ملاحظات إضافية عن العميل..."
          />
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
          <Link
            to={`/customers/${id}`}
            className="px-6 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 dark:text-gray-300 dark:border-gray-600 dark:hover:bg-gray-700"
          >
            إلغاء
          </Link>
          <button
            type="submit"
            disabled={isSaving}
            className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 inline-flex items-center gap-2"
          >
            {isSaving ? (
              <>
                <span className="animate-spin">⏳</span>
                جاري الحفظ...
              </>
            ) : (
              <>
                <CheckIcon className="h-4 w-4" />
                حفظ التغييرات
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

export default CustomerEdit;

import React, { useState, useRef } from "react";
import {
  XMarkIcon,
  ArrowUpTrayIcon,
  DocumentArrowUpIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon,
} from "@heroicons/react/24/outline";
import { useTranslation } from "react-i18next";
import { apiClient } from "../../services/apiClient";

interface CustomerImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

interface ParsedCustomer {
  firstName: string;
  lastName: string;
  email?: string;
  phone?: string;
  address?: string;
  city?: string;
  country?: string;
  status?: string;
}

const CustomerImportModal: React.FC<CustomerImportModalProps> = ({
  isOpen,
  onClose,
  onSuccess,
}) => {
  const { t } = useTranslation();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [file, setFile] = useState<File | null>(null);
  const [parsedData, setParsedData] = useState<ParsedCustomer[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<{
    success: boolean;
    count: number;
  } | null>(null);

  const parseCSV = (text: string): ParsedCustomer[] => {
    const lines = text.trim().split("\n");
    if (lines.length < 2) return [];

    const headers = lines[0]
      .split(",")
      .map((h) => h.trim().toLowerCase().replace(/['"]/g, ""));
    const customers: ParsedCustomer[] = [];

    for (let i = 1; i < lines.length; i++) {
      const values = lines[i]
        .split(",")
        .map((v) => v.trim().replace(/['"]/g, ""));
      const customer: any = {};

      headers.forEach((header, index) => {
        const value = values[index] || "";
        // Map common header names
        if (header.includes("first") || header === "الاسم الأول")
          customer.firstName = value;
        else if (header.includes("last") || header === "الاسم الأخير")
          customer.lastName = value;
        else if (header.includes("name") || header === "الاسم") {
          const parts = value.split(" ");
          customer.firstName = parts[0];
          customer.lastName = parts.slice(1).join(" ");
        } else if (header.includes("email") || header === "البريد")
          customer.email = value;
        else if (
          header.includes("phone") ||
          header.includes("mobile") ||
          header === "الهاتف"
        )
          customer.phone = value;
        else if (header.includes("address") || header === "العنوان")
          customer.address = value;
        else if (header.includes("city") || header === "المدينة")
          customer.city = value;
        else if (header.includes("country") || header === "البلد")
          customer.country = value;
        else if (header.includes("status") || header === "الحالة")
          customer.status = value.toUpperCase();
      });

      if (customer.firstName || customer.phone || customer.email) {
        customers.push(customer);
      }
    }

    return customers;
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    setFile(selectedFile);
    setError("");
    setResult(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const parsed = parseCSV(text);
        setParsedData(parsed);
        if (parsed.length === 0) {
          setError(t("customers.import.noValidData"));
        }
      } catch (err) {
        setError(t("customers.import.readError"));
      }
    };
    reader.readAsText(selectedFile);
  };

  const handleImport = async () => {
    if (parsedData.length === 0) return;

    setIsLoading(true);
    setError("");

    try {
      const response = await apiClient.post("/customers/import", {
        customers: parsedData,
      });
      setResult({
        success: true,
        count: response.data.importedCount || parsedData.length,
      });
      onSuccess();
    } catch (err: any) {
      setError(err.response?.data?.message || t("customers.deleteError")); // fallback to generic error if needed or use a specific one
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    setFile(null);
    setParsedData([]);
    setError("");
    setResult(null);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto">
      <div className="fixed inset-0 bg-black/50" onClick={handleClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-2xl w-full mx-4 max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
            <ArrowUpTrayIcon className="h-5 w-5" />
            {t("customers.import.title")}
          </h2>
          <button
            onClick={handleClose}
            className="text-gray-400 hover:text-gray-500"
          >
            <XMarkIcon className="h-6 w-6" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-4 overflow-y-auto max-h-[60vh]">
          {/* Upload Area */}
          {!result && (
            <div
              onClick={() => fileInputRef.current?.click()}
              className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-8 text-center cursor-pointer hover:border-indigo-500 transition-colors"
            >
              <input
                ref={fileInputRef}
                type="file"
                accept=".csv"
                onChange={handleFileChange}
                className="hidden"
              />
              <DocumentArrowUpIcon className="h-12 w-12 mx-auto text-gray-400" />
              <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                {file ? file.name : t("customers.import.clickOrDrag")}
              </p>
              <p className="text-xs text-gray-400 mt-1">
                {t("customers.import.requiredColumns")}
              </p>
            </div>
          )}

          {/* Preview */}
          {parsedData.length > 0 && !result && (
            <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-4">
              <p className="text-sm font-medium text-gray-700 dark:text-gray-200 mb-2">
                {t("customers.import.foundCount", { count: parsedData.length })}
              </p>
              <div className="max-h-40 overflow-y-auto">
                <table className="min-w-full text-sm">
                  <thead>
                    <tr className="text-gray-500 dark:text-gray-400">
                      <th className="text-right py-1 px-2">الاسم</th>
                      <th className="text-right py-1 px-2">{t("common.phone")}</th>
                      <th className="text-right py-1 px-2">{t("common.email")}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {parsedData.slice(0, 5).map((c, i) => (
                      <tr key={i} className="text-gray-800 dark:text-gray-200">
                        <td className="py-1 px-2">
                          {c.firstName} {c.lastName}
                        </td>
                        <td className="py-1 px-2">{c.phone || "-"}</td>
                        <td className="py-1 px-2">{c.email || "-"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {parsedData.length > 5 && (
                  <p className="text-xs text-gray-500 mt-2">
                    ... {t("common.and")} {parsedData.length - 5} {t("common.otherItems")}
                  </p>
                )}
              </div>
            </div>
          )}

          {/* Success Result */}
          {result?.success && (
            <div className="text-center py-8">
              <CheckCircleIcon className="h-16 w-16 mx-auto text-green-500" />
              <p className="mt-4 text-lg font-medium text-gray-900 dark:text-white">
                {t("customers.import.success", { count: result.count })}
              </p>
            </div>
          )}

          {/* Error */}
          {error && (
            <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 rounded-lg">
              <ExclamationTriangleIcon className="h-5 w-5" />
              {error}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex justify-end gap-3 p-4 border-t dark:border-gray-700">
          <button
            onClick={handleClose}
            className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md hover:bg-gray-50 dark:hover:bg-gray-600"
          >
            {result ? t("common.close") : t("common.cancel")}
          </button>
          {!result && (
            <button
              onClick={handleImport}
              disabled={parsedData.length === 0 || isLoading}
              className="inline-flex items-center px-4 py-2 text-sm font-medium text-white bg-indigo-600 border border-transparent rounded-md hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isLoading ? (
                <>
                  <svg
                    className="animate-spin -ml-1 mr-2 h-4 w-4 text-white"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    />
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                    />
                  </svg>
                  {t("customers.import.importing")}
                </>
              ) : (
                <>
                  <ArrowUpTrayIcon className="h-4 w-4 ml-2" />
                  {t("customers.import.importButton", { count: parsedData.length })}
                </>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default CustomerImportModal;

import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  PlusIcon,
  MagnifyingGlassIcon,
  ArrowDownTrayIcon,
  ArrowUpTrayIcon,
  EyeIcon,
  PencilIcon,
  TrashIcon,
  UsersIcon,
  ShoppingBagIcon,
} from "@heroicons/react/24/outline";
import {
  customerService,
  Customer,
  CustomerFilters,
} from "../../services/customerService";
import LoadingSpinner from "../../components/LoadingSpinner";
import { useDateFormat } from "../../hooks/useDateFormat";
import CustomerImportModal from "./CustomerImportModal";
import { useAuth } from "../../hooks/useAuthSimple";

const CustomerList: React.FC = () => {
  const { t } = useTranslation();
  const { formatDate } = useDateFormat();
  const navigate = useNavigate();
  const { user } = useAuth();
  const isAdmin = ["OWNER", "COMPANY_ADMIN", "SUPER_ADMIN", "MANAGER"].includes(
    user?.role || "",
  );

  const [customers, setCustomers] = useState<Customer[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [showOnlyWithOrders, setShowOnlyWithOrders] = useState(false);
  const [filters, setFilters] = useState<CustomerFilters>({
    page: 1,
    limit: 10,
    sortBy: "updatedAt",
    sortOrder: "desc",
    hasOrders: false,
  });

  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0,
    totalPages: 0,
    hasNext: false,
    hasPrev: false,
  });

  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkDeleting, setIsBulkDeleting] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const statusOptions = customerService.getStatusOptions();

  // Toggle hasOrders filter
  const handleToggleWithOrders = () => {
    const newVal = !showOnlyWithOrders;
    setShowOnlyWithOrders(newVal);
    setFilters((prev) => ({ ...prev, page: 1, hasOrders: newVal }));
  };

  // Selection handlers
  const toggleSelectAll = () => {
    if (selectedIds.size === customers.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(customers.map((c) => c.id)));
    }
  };

  const toggleSelect = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleBulkDelete = async () => {
    if (selectedIds.size === 0) return;
    if (!confirm(t("customers.bulkDeleteConfirm", { count: selectedIds.size }))) return;

    setIsBulkDeleting(true);
    try {
      await Promise.all(
        Array.from(selectedIds).map((id) => customerService.deleteCustomer(id)),
      );
      setSelectedIds(new Set());
      loadCustomers();
    } catch (err: any) {
      setError(err.message || t("customers.deleteError"));
    } finally {
      setIsBulkDeleting(false);
    }
  };

  // Single delete handler
  const handleDeleteCustomer = async (customer: Customer) => {
    setError("");
    if (!confirm(t("customers.deleteCustomerConfirm"))) return;
    setDeletingId(customer.id);
    try {
      await customerService.deleteCustomer(customer.id);
      loadCustomers();
    } catch (err: any) {
      setError(err.response?.data?.message || err.message || t("customers.deleteError"));
    } finally {
      setDeletingId(null);
    }
  };

  const loadCustomers = async () => {
    try {
      setIsLoading(true);
      const response = await customerService.getCustomers(filters);
      setCustomers(response.data);
      setPagination(response.pagination);
    } catch (err: any) {
      setError(err.message || t("customers.loadingError"));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadCustomers();
  }, [filters]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setFilters((prev) => ({
      ...prev,
      search: searchQuery,
      page: 1,
    }));
  };

  const handleStatusFilter = (status: string) => {
    setFilters((prev) => {
      const newFilters: CustomerFilters = { ...prev, page: 1 };
      if (status === "all") {
        delete newFilters.status;
      } else {
        newFilters.status = status;
      }
      return newFilters;
    });
  };

  // Parse tags safely — DB stores them as a JSON string or real array
  const parseTags = (tags: any): string[] => {
    if (!tags) return [];
    if (Array.isArray(tags)) return tags;
    if (typeof tags === "string") {
      try {
        const parsed = JSON.parse(tags);
        return Array.isArray(parsed) ? parsed : [];
      } catch {
        return [];
      }
    }
    return [];
  };

  const handlePageChange = (page: number) => {
    setFilters((prev) => ({ ...prev, page }));
  };

  const handleExport = async (format: "csv" | "json") => {
    try {
      await customerService.exportCustomers(format, filters);
    } catch (err: any) {
      setError(err.message || t("customers.exportError"));
    }
  };

  const getStatusBadge = (status: string) => {
    const statusOption = statusOptions.find(
      (option) => option.value === status,
    );
    if (!statusOption) return null;

    const colorClasses = {
      yellow: "bg-yellow-100 text-yellow-800",
      green: "bg-green-100 text-green-800",
      gray: "bg-gray-100 text-gray-800",
      purple: "bg-purple-100 text-purple-800",
      red: "bg-red-100 text-red-800",
    };

    return (
      <span
        className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${colorClasses[statusOption.color as keyof typeof colorClasses]}`}
      >
        {statusOption.label}
      </span>
    );
  };

  const getRatingBadge = (rating: string | undefined) => {
    if (!rating) return null;
    const r = rating.toLowerCase();
    switch (r) {
      case "excellent":
        return (
          <span className="ml-2 text-xs bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full ring-1 ring-purple-600/20">
            {t("customers.rating.excellent")}
          </span>
        );
      case "good":
        return (
          <span className="ml-2 text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full ring-1 ring-blue-600/20">
            {t("customers.rating.good")}
          </span>
        );
      case "average":
        return (
          <span className="ml-2 text-xs bg-gray-100 text-gray-700 px-2 py-0.5 rounded-full ring-1 ring-gray-600/20">
            {t("customers.rating.average")}
          </span>
        );
      case "bad":
        return (
          <span className="ml-2 text-xs bg-red-100 text-red-700 px-2 py-0.5 rounded-full ring-1 ring-red-600/20">
            {t("customers.rating.bad")}
          </span>
        );
      default:
        return null;
    }
  };

  if (isLoading && customers.length === 0) {
    return (
      <div className="flex items-center justify-center h-64">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  return (
    <>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
              {t("customers.pageTitle")}
            </h1>
            <p className="text-gray-600 dark:text-gray-400">
              {t("customers.pageSubtitle")}
            </p>
          </div>
          {isAdmin && (
            <div className="flex space-x-3 space-x-reverse">
              <button
                onClick={() => setIsImportModalOpen(true)}
                className="inline-flex items-center px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
              >
                <ArrowUpTrayIcon className="h-4 w-4 ml-2" />
                {t("customers.importCSV")}
              </button>
              <button
                onClick={() => handleExport("csv")}
                className="inline-flex items-center px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
              >
                <ArrowDownTrayIcon className="h-4 w-4 ml-2" />
                {t("customers.exportCSV")}
              </button>

              <Link
                to="/customers/new"
                className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600"
              >
                <PlusIcon className="h-4 w-4 ml-2" />
                {t("customers.addCustomer")}
              </Link>
            </div>
          )}
        </div>

        {/* Filters */}
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow dark:shadow-md">
          <div className="flex flex-col sm:flex-row gap-4">
            {/* Search */}
            <form onSubmit={handleSearch} className="flex-1">
              <div className="relative">
                <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400 dark:text-gray-500" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t("customers.searchPlaceholder")}
                  className="block w-full pr-10 pl-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md leading-5 bg-white dark:bg-gray-700 placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 dark:text-gray-100"
                />
              </div>
            </form>

            {/* Toggle: with orders only */}
            <button
              onClick={handleToggleWithOrders}
              className={`inline-flex items-center gap-2 px-4 py-2 rounded-md border text-sm font-medium transition-colors ${
                showOnlyWithOrders
                  ? "bg-indigo-600 border-indigo-600 text-white hover:bg-indigo-700"
                  : "border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
              }`}
            >
              {showOnlyWithOrders ? (
                <ShoppingBagIcon className="h-4 w-4" />
              ) : (
                <UsersIcon className="h-4 w-4" />
              )}
              {showOnlyWithOrders
                ? t("customers.withOrdersOnly")
                : t("customers.showAllCustomers")}
            </button>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-700 text-red-700 dark:text-red-300 px-4 py-3 rounded-md">
            {error}
          </div>
        )}

        {/* Bulk Action Toolbar */}
        {selectedIds.size > 0 && (
          <div className="bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-700 px-4 py-3 rounded-md flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="text-indigo-700 dark:text-indigo-300 font-medium">
                {t("customers.selectedCount", { count: selectedIds.size })}
              </span>
              <button
                onClick={() => setSelectedIds(new Set())}
                className="text-sm text-indigo-600 hover:text-indigo-800 dark:text-indigo-400"
              >
                {t("customers.cancelSelection")}
              </button>
            </div>
            <div className="flex items-center gap-2">
              {/* Delete function removed as requested */}
            </div>
          </div>
        )}

        {/* Customers Table */}
        <div className="bg-white dark:bg-gray-800 shadow dark:shadow-md overflow-hidden sm:rounded-md">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-50 dark:bg-gray-900">
                <tr>
                  <th className="px-4 py-3 text-center">
                    <input
                      type="checkbox"
                      checked={
                        selectedIds.size === customers.length &&
                        customers.length > 0
                      }
                      onChange={toggleSelectAll}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    {t("customers.tableCustomer")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    {t("customers.tableContactInfo")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    {t("customers.tableStatus")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    {t("customers.tableStats")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    {t("customers.tableUpdatedAt")}
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    {t("customers.tableActions")}
