                                    className="border border-gray-100 dark:border-slate-800 rounded-xl p-3 hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors"
                                >
                                    <div className="flex items-start justify-between gap-2">
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-2 flex-wrap">
                                                <span className="text-sm font-bold text-gray-800 dark:text-slate-100 truncate">
                                                    {camp.name}
                                                </span>
                                                <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold ${getHistoryStatusStyle(camp.status)}`}>
                                                    {getHistoryStatusLabel(camp.status)}
                                                </span>
                                                <span className="text-[10px] text-gray-400 dark:text-slate-500 bg-gray-100 dark:bg-slate-800 px-2 py-0.5 rounded-full">
                                                    {AUDIENCE_LABELS[camp.targetAudience] || camp.targetAudience}
                                                </span>
                                            </div>
                                            <p className="text-[11px] text-gray-400 dark:text-slate-500 mt-0.5">
                                                {formatRelativeTime(camp.createdAt)}
                                            </p>
                                        </div>
                                        <div className="text-right flex-shrink-0">
                                            <div className="flex items-center gap-2 text-[11px]">
                                                <span className="text-emerald-600 dark:text-emerald-400 font-bold">✓ {camp.sentCount}</span>
                                                {camp.failedCount > 0 && (
                                                    <span className="text-rose-500 dark:text-rose-400 font-bold">✗ {camp.failedCount}</span>
                                                )}
                                                <span className="text-gray-400 dark:text-slate-600">/ {camp.recipientCount}</span>
                                            </div>
                                            {camp.recipientCount > 0 && (
                                                <div className="mt-1 h-1.5 w-20 bg-gray-100 dark:bg-slate-800 rounded-full overflow-hidden">
                                                    <div
                                                        className="h-full bg-emerald-500 dark:bg-emerald-400 rounded-full"
                                                        style={{ width: `${(camp.sentCount / camp.recipientCount) * 100}%` }}
                                                    />
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

            </div>
        </div>
    );
};

export default CustomerOccasionsWhatsAppNotify;

import React, { useEffect, useMemo, useState } from "react";
import { apiClient } from "../../services/apiClient";
import {
  Star,
  RefreshCw,
  Search,
  Users,
  TrendingUp,
  AlertTriangle,
  Gift,
  Target,
  Sparkles,
  ArrowUpCircle,
  ArrowDownCircle,
  Wrench,
  UserPlus,
  History,
  Filter,
  ChevronLeft,
  ChevronRight,
  MessageCircle,
  X
} from "lucide-react";

interface CustomerLoyaltyProgram {
  id: string;
  name: string;
  nameAr?: string;
  pointsPerPurchase?: number | string;
  pointsPerAmount?: number | string;
  pointsPerReferral?: number | string;
  minimumPoints?: number | string;
  expiryMonths?: number;
}

interface CustomerLoyaltyTier {
  id: string;
  programId: string;
  name: string;
  nameAr?: string;
  minPoints: number | string;
  maxPoints?: number | string | null;
  priority?: number;
  color?: string;
}

interface CustomerLoyaltyRecord {
  id: string;
  customer: {
    id: string;
    firstName: string;
    lastName: string;
    email?: string;
    phone?: string;
  };
  program: CustomerLoyaltyProgram;
  tier?: {
    id: string;
    name: string;
    nameAr?: string;
  } | null;
  currentPoints: number | string;
  totalEarned: number | string;
  totalRedeemed: number | string;
  lastActivity: string;
  metadata?: any;
  status: "ACTIVE" | "INACTIVE" | "SUSPENDED";
}

type PointsActionType = "ADD" | "REDEEM" | "ADJUST";
type FilterMode = "ALL" | "VIP" | "AT_RISK";

const toNumber = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const formatPoints = (value: number): string =>
  Math.round(value).toLocaleString("ar-EG");

const getMonthsSince = (dateString: string): number => {
  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) return 0;

  const now = new Date();
  let months =
    (now.getFullYear() - date.getFullYear()) * 12 +
    (now.getMonth() - date.getMonth());

  if (now.getDate() < date.getDate()) {
    months -= 1;
  }

  return Math.max(0, months);
};

const getEarningRuleText = (program: CustomerLoyaltyProgram | null): string => {
  if (!program) return "حدد برنامج نقاط واضح وسهل الفهم للعملاء.";

  const pointsPerAmount = toNumber(program.pointsPerAmount);
  const pointsPerPurchase = toNumber(program.pointsPerPurchase);
  const pointsPerReferral = toNumber(program.pointsPerReferral);

  if (pointsPerAmount > 0) {
    return `اكسب ${pointsPerAmount} نقطة لكل 1 وحدة عملة من قيمة الطلب.`;
  }

  if (pointsPerPurchase > 0) {
    return `اكسب ${pointsPerPurchase} نقطة لكل عملية شراء مكتملة.`;
  }

  if (pointsPerReferral > 0) {
    return `برنامج الإحالة يضيف ${pointsPerReferral} نقطة لكل إحالة ناجحة.`;
  }

  return "فعّل معدل كسب واضح (لكل طلب أو لكل قيمة شراء) لرفع وضوح البرنامج.";
};

const CustomerPointsCenter: React.FC = () => {
  const [records, setRecords] = useState<CustomerLoyaltyRecord[]>([]);
  const [programs, setPrograms] = useState<CustomerLoyaltyProgram[]>([]);
  const [tiers, setTiers] = useState<CustomerLoyaltyTier[]>([]);
  const [allSystemCustomers, setAllSystemCustomers] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  // Search and Filters
  const [searchQuery, setSearchQuery] = useState("");
  const [filterMode, setFilterMode] = useState<FilterMode>("ALL");
  
  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 8;
  
  // Selected Customer Management
  const [selectedRecordId, setSelectedRecordId] = useState<string>("");
  const [actionType, setActionType] = useState<PointsActionType>("ADD");
  const [pointsValue, setPointsValue] = useState<string>("");
  const [reason, setReason] = useState("");
  
  // Modals
  const [isEnrollModalOpen, setIsEnrollModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [enrollData, setEnrollData] = useState({
    customerId: "",
    programId: "",
    initialPoints: "0"
  });

  // Messages
  const [errorMessage, setErrorMessage] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  const fetchData = async () => {
    try {
      setIsLoading(true);
      setErrorMessage("");

      const [customersRes, programsRes, tiersRes] = await Promise.all([
        apiClient.get("/hr/customer-loyalty/customers"),
        apiClient.get("/hr/customer-loyalty/programs"),
        apiClient.get("/hr/customer-loyalty/tiers"),
      ]);

      const nextRecords: CustomerLoyaltyRecord[] = customersRes.data.data || [];
      const nextPrograms: CustomerLoyaltyProgram[] = programsRes.data.data || [];
      const nextTiers: CustomerLoyaltyTier[] = tiersRes.data.data || [];

      setRecords(nextRecords);
      setPrograms(nextPrograms);
      setTiers(nextTiers);

      if (!selectedRecordId && nextRecords.length > 0) {
        setSelectedRecordId(nextRecords[0].id);
      }

      if (
        selectedRecordId &&
        !nextRecords.some((record) => record.id === selectedRecordId)
      ) {
        setSelectedRecordId(nextRecords[0]?.id || "");
      }
    } catch (error) {
      console.error("Error fetching points center data:", error);
      setErrorMessage("فشل تحميل بيانات النقاط. حاول مرة أخرى.");
    } finally {
      setIsLoading(false);
    }
  };

  const fetchAllCustomers = async () => {
    try {
      // جلب جميع العملاء بما فيهم الذين ليس لديهم طلبات بعد
      const res = await apiClient.get("/customers?limit=200&hasOrders=false");
      // API يرجع: { success: true, data: [...] } وليس { data: { customers: [...] } }
      const list = Array.isArray(res.data.data) ? res.data.data : [];
      setAllSystemCustomers(list);
    } catch (error) {
      console.error("Error fetching system customers", error);
    }
  };


  useEffect(() => {
    fetchData();
    fetchAllCustomers();
  }, []);

  // Filter and Sort logic
  const filteredRecords = useMemo(() => {
    let result = records;

    if (filterMode === "AT_RISK") {
      result = result.filter((record) => {
        const expiryMonths = Math.max(1, Number(record.program.expiryMonths || 12));
        const monthsSinceActivity = getMonthsSince(record.lastActivity);
        return (
          record.status === "ACTIVE" &&
          toNumber(record.currentPoints) > 0 &&
          monthsSinceActivity >= expiryMonths - 1
        );
      });
    } else if (filterMode === "VIP") {
      // Top 20% by points or simply top 20
      result = [...result]
        .sort((a, b) => toNumber(b.currentPoints) - toNumber(a.currentPoints))
        .slice(0, 20);
    }

    const normalizedQuery = searchQuery.trim().toLowerCase();
    
    result = result.filter((record) => {
      if (!normalizedQuery) return true;
      const fullName =
        `${record.customer.firstName} ${record.customer.lastName}`.toLowerCase();
      return (
        fullName.includes(normalizedQuery) ||
        (record.customer.email || "").toLowerCase().includes(normalizedQuery) ||
        (record.customer.phone || "").includes(normalizedQuery)
      );
    });

    return result.sort((a, b) => toNumber(b.currentPoints) - toNumber(a.currentPoints));
  }, [records, searchQuery, filterMode]);

  // Reset page when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, filterMode]);

  const totalPages = Math.ceil(filteredRecords.length / itemsPerPage);
  const paginatedRecords = filteredRecords.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const selectedRecord =
    records.find((record) => record.id === selectedRecordId) || null;

  const selectedProgram = selectedRecord
    ? programs.find((program) => program.id === selectedRecord.program.id) ||
      selectedRecord.program
    : null;
    
  const earningRuleText = getEarningRuleText(selectedProgram);

  const selectedProgramTiers = useMemo(() => {
    if (!selectedProgram) return [];
    return tiers
      .filter((tier) => tier.programId === selectedProgram.id)
      .sort((a, b) => toNumber(a.minPoints) - toNumber(b.minPoints));
  }, [tiers, selectedProgram]);

  const selectedCurrentPoints = toNumber(selectedRecord?.currentPoints || 0);

  const nextTier = selectedProgramTiers.find(
    (tier) => toNumber(tier.minPoints) > selectedCurrentPoints,
  );

  const reachedTiers = selectedProgramTiers.filter(
    (tier) => toNumber(tier.minPoints) <= selectedCurrentPoints,
  );
  const currentTierMin =
    reachedTiers.length > 0 ? reachedTiers[reachedTiers.length - 1].minPoints : 0;

  const progressDenominator = Math.max(
    1,
    toNumber(nextTier?.minPoints || selectedCurrentPoints || 1) -
      toNumber(currentTierMin),
  );
  const progressNumerator = selectedCurrentPoints - toNumber(currentTierMin);
  const progressToNextTier = nextTier
    ? Math.max(
        0,
        Math.min(100, Math.round((progressNumerator / progressDenominator) * 100)),
      )
    : 100;

  const pointsToNextTier = nextTier
    ? Math.max(0, toNumber(nextTier.minPoints) - selectedCurrentPoints)
    : 0;

  // Global Stats calculations (from original records)
  const activeMembers = records.filter((record) => record.status === "ACTIVE").length;
  const totalPointsBalance = records.reduce(
    (sum, record) => sum + toNumber(record.currentPoints),
    0,
  );
  const totalEarnedPoints = records.reduce(
    (sum, record) => sum + toNumber(record.totalEarned),
    0,
  );
  const totalRedeemedPoints = records.reduce(
    (sum, record) => sum + toNumber(record.totalRedeemed),
    0,
  );

  const redemptionRate =
    totalEarnedPoints > 0
      ? Math.round((totalRedeemedPoints / totalEarnedPoints) * 100)
      : 0;

  const atRiskCustomers = records.filter((record) => {
    const expiryMonths = Math.max(1, Number(record.program.expiryMonths || 12));
    const monthsSinceActivity = getMonthsSince(record.lastActivity);
    return (
      record.status === "ACTIVE" &&
      toNumber(record.currentPoints) > 0 &&
      monthsSinceActivity >= expiryMonths - 1
    );
  });

  const handleSubmitAction = async () => {
    if (!selectedRecord) return;

    const points = Number(pointsValue);
    if (!Number.isFinite(points) || points === 0) {
      setErrorMessage("ادخل عدد نقاط صالح.");
      return;
    }

    if ((actionType === "ADD" || actionType === "REDEEM") && points <= 0) {
      setErrorMessage("قيمة النقاط يجب أن تكون أكبر من صفر.");
      return;
    }

    if (actionType === "REDEEM" && points > toNumber(selectedRecord.currentPoints)) {
      setErrorMessage("لا يمكن استبدال نقاط أكبر من رصيد العميل الحالي.");
      return;
    }
    
    if (actionType === "ADJUST" && (!reason || reason.trim().length < 3)) {
      setErrorMessage("بسبب حساسيات التعديل اليدوي، يرجى تقديم سبب واضح للعملية.");
      return;
    }

    const endpointMap: Record<PointsActionType, string> = {
      ADD: "/hr/customer-loyalty/add-points",
      REDEEM: "/hr/customer-loyalty/redeem-points",
      ADJUST: "/hr/customer-loyalty/adjust-points",
    };

    try {
      setIsSubmitting(true);
      setErrorMessage("");
      setSuccessMessage("");

      await apiClient.post(endpointMap[actionType], {
        customerId: selectedRecord.customer.id,
        programId: selectedRecord.program.id,
        points,
        reason: reason.trim() || undefined,
      });

      setSuccessMessage("تم تنفيذ العملية بنجاح.");
      setPointsValue("");
      setReason("");
      await fetchData();
    } catch (error) {
      console.error("Error submitting points action:", error);
      setErrorMessage("تعذر تنفيذ العملية. راجع البيانات وحاول مرة أخرى.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEnrollCustomer = async () => {
    if (!enrollData.customerId || !enrollData.programId) {
      setErrorMessage("يرجى اختيار العميل وبرنامج الولاء");
      return;
    }
    
    try {
      setIsSubmitting(true);
      setErrorMessage("");
      
      await apiClient.post("/hr/customer-loyalty/enroll", {
        customerId: enrollData.customerId,
        programId: enrollData.programId,
        initialPoints: Number(enrollData.initialPoints) || 0
      });
      
      setSuccessMessage("تم تسجيل العميل بنجاح في برنامج الولاء");
      setIsEnrollModalOpen(false);
      setEnrollData({ customerId: "", programId: "", initialPoints: "0" });
      await fetchData();
    } catch (error) {
      console.error("Error enrolling customer", error);
      setErrorMessage("حدث خطأ أثناء التسجيل. قد يكون العميل مسجلاً بالفعل.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading && records.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-[420px]">
        <div className="h-10 w-10 animate-spin rounded-full border-2 border-purple-600 border-t-transparent" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            مركز نقاط العملاء
          </h1>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
            لوحة شاملة لنقاط العملاء ومستوياتهم وحملات حفظ الولاء.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setIsEnrollModalOpen(true)}
            className="flex items-center gap-2 rounded-lg bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-700 transition"
          >
            <UserPlus className="h-4 w-4" />
            إضافة عميل
          </button>
          <button
            onClick={fetchData}
            className="flex items-center gap-2 rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200 dark:hover:bg-gray-700"
          >
            <RefreshCw className="h-4 w-4" />
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          <div className="mb-2 flex items-center justify-between">
            <Users className="h-5 w-5 text-blue-600" />
            <span className="text-xs text-gray-500">نشط</span>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400">أعضاء الولاء الإجمالي</p>
          <p className="mt-1 text-2xl font-bold text-gray-900 dark:text-white">
            {activeMembers.toLocaleString("ar-EG")}
          </p>
        </div>

        <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          <div className="mb-2 flex items-center justify-between">
            <Star className="h-5 w-5 text-yellow-500" />
            <span className="text-xs text-gray-500">الرصيد</span>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400">إجمالي النقاط المتبقية</p>
          <p className="mt-1 text-2xl font-bold text-gray-900 dark:text-white">
            {formatPoints(totalPointsBalance)}
          </p>
        </div>

        <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          <div className="mb-2 flex items-center justify-between">
            <TrendingUp className="h-5 w-5 text-emerald-600" />
            <span className="text-xs text-gray-500">استبدال</span>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            معدل استبدال النقاط
          </p>
          <p className="mt-1 text-2xl font-bold text-gray-900 dark:text-white">
            {redemptionRate}%
          </p>
        </div>

        <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          <div className="mb-2 flex items-center justify-between">
            <AlertTriangle className="h-5 w-5 text-amber-600" />
            <span className="text-xs text-gray-500">انتهاء صلاحية</span>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400">عملاء مهددون بانتهاء رصيد</p>
          <p className="mt-1 text-2xl font-bold text-gray-900 dark:text-white">
            {atRiskCustomers.length.toLocaleString("ar-EG")}
          </p>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        <div className="space-y-4 lg:col-span-2">
          {/* Controls Bar */}
          <div className="flex flex-col sm:flex-row gap-3">
            <div className="relative flex-1">
              <Search className="absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(event) => setSearchQuery(event.target.value)}
                placeholder="ابحث باسم العميل، إيميل، رقم الهاتف..."
                className="w-full rounded-lg border border-gray-300 bg-white py-2.5 pl-4 pr-10 text-right text-sm text-gray-900 outline-none focus:border-purple-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              />
            </div>
            <div className="flex items-center gap-2 overflow-x-auto pb-2 sm:pb-0 scrollbar-hide">
               <button
                 onClick={() => setFilterMode("ALL")}
                 className={`flex whitespace-nowrap items-center gap-2 rounded-lg px-3 py-2.5 text-sm font-medium transition ${
                   filterMode === "ALL" ? "bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300 border border-purple-200 dark:border-purple-800" : "bg-white border border-gray-300 text-gray-600 dark:bg-gray-800 dark:text-gray-300 hover:bg-gray-50 dark:border-gray-600"
                 }`}
               >
                 <Filter className="h-4 w-4" />
                 الكل
               </button>
               <button
                 onClick={() => setFilterMode("VIP")}
                 className={`flex whitespace-nowrap items-center gap-2 rounded-lg px-3 py-2.5 text-sm font-medium transition ${
                   filterMode === "VIP" ? "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300 border border-amber-200 dark:border-amber-800" : "bg-white border border-gray-300 text-gray-600 dark:bg-gray-800 dark:text-gray-300 hover:bg-gray-50 dark:border-gray-600"
                 }`}
               >
                 <Star className="h-4 w-4" />
                 VIP
               </button>
               <button
                 onClick={() => setFilterMode("AT_RISK")}
                 className={`flex whitespace-nowrap items-center gap-2 rounded-lg px-3 py-2.5 text-sm font-medium transition ${
                   filterMode === "AT_RISK" ? "bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300 border border-red-200 dark:border-red-800" : "bg-white border border-gray-300 text-gray-600 dark:bg-gray-800 dark:text-gray-300 hover:bg-gray-50 dark:border-gray-600"
                 }`}
               >
                 <AlertTriangle className="h-4 w-4" />
                 مهدد
               </button>
            </div>
          </div>

          <div className="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm dark:border-gray-700 dark:bg-gray-800 flex flex-col min-h-[400px]">
             {/* Table */}
            <div className="overflow-x-auto flex-1">
              <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                <thead className="bg-gray-50 dark:bg-gray-700/40 sticky top-0">
                  <tr>
                    <th className="px-4 py-3 text-right text-xs font-semibold text-gray-500">العميل</th>
                    <th className="px-4 py-3 text-right text-xs font-semibold text-gray-500">البرنامج</th>
                    <th className="px-4 py-3 text-right text-xs font-semibold text-gray-500">الرصيد</th>
                    <th className="px-4 py-3 text-right text-xs font-semibold text-gray-500">المستوى</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                  {paginatedRecords.map((record) => (
                    <tr
                      key={record.id}
                      onClick={() => setSelectedRecordId(record.id)}
                      className={`cursor-pointer transition-colors ${
                        selectedRecord?.id === record.id
                          ? "bg-purple-50 dark:bg-purple-900/20"
                          : "hover:bg-gray-50 dark:hover:bg-gray-700/30"
                      }`}
                    >
                      <td className="px-4 py-3 text-right">
                        <p className="font-medium text-gray-900 dark:text-white">
                          {record.customer.firstName} {record.customer.lastName}
                        </p>
                        <p className="text-xs text-gray-500">{record.customer.phone || "-"}</p>
                      </td>
                      <td className="px-4 py-3 text-right text-sm text-gray-700 dark:text-gray-200">
                        {record.program.nameAr || record.program.name}
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-white">
                        {formatPoints(toNumber(record.currentPoints))}
                      </td>
                      <td className="px-4 py-3 text-right text-sm text-gray-700 dark:text-gray-200">
                        <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300`}>
                          {record.tier?.nameAr || record.tier?.name || "بدون مستوى"}
                        </span>
                      </td>
                    </tr>
                  ))}
                  {paginatedRecords.length === 0 && (
                    <tr>
                      <td colSpan={4}>
                        <div className="p-10 text-center text-sm text-gray-500">
                          لا يوجد عملاء مطابقون للبحث والتصفية.
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
            
             {/* Pagination */}
             {totalPages > 1 && (
               <div className="flex items-center justify-between border-t border-gray-200 px-4 py-3 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                   <p className="text-sm text-gray-500 dark:text-gray-400">
                     صفحة <span className="font-medium">{currentPage}</span> من <span className="font-medium">{totalPages}</span>
                   </p>
                   <div className="flex gap-2">
                     <button
                       onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                       disabled={currentPage === 1}
                       className="p-1 rounded bg-white border border-gray-300 dark:bg-gray-700 dark:border-gray-600 disabled:opacity-50 text-gray-700 dark:text-gray-200 hover:bg-gray-50"
                     >
                       <ChevronRight className="h-5 w-5" />
                     </button>
                     <button
                       onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                       disabled={currentPage === totalPages}
                       className="p-1 rounded bg-white border border-gray-300 dark:bg-gray-700 dark:border-gray-600 disabled:opacity-50 text-gray-700 dark:text-gray-200 hover:bg-gray-50"
                     >
                       <ChevronLeft className="h-5 w-5" />
                     </button>
                   </div>
               </div>
             )}
          </div>
        </div>

        <div className="space-y-4">
          <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-700 dark:bg-gray-800">
            <h3 className="mb-4 text-lg font-bold text-gray-900 dark:text-white flex justify-between items-center">
              ملف العميل المختار
              {selectedRecord && (
                 <button 
                  onClick={() => setIsHistoryModalOpen(true)}
                  className="text-xs flex items-center gap-1 font-normal text-purple-600 bg-purple-50 dark:bg-purple-900/30 px-2 py-1.5 rounded hover:bg-purple-100 transition"
                 >
                   <History className="h-3.5 w-3.5" /> سجل الحركات
                 </button>
              )}
            </h3>
            {selectedRecord ? (
              <div className="space-y-3 text-right">
                <p className="font-semibold text-gray-900 dark:text-white text-lg">
                  {selectedRecord.customer.firstName} {selectedRecord.customer.lastName}
                </p>
                <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-3">
                    <div>
                        <p className="text-sm text-gray-500 dark:text-gray-400">البرنامج:</p>
                        <p className="font-medium text-gray-800 dark:text-gray-200">{selectedProgram?.nameAr || selectedProgram?.name || "-"}</p>
                    </div>
                    <div className="text-left">
                        <p className="text-sm text-gray-500 dark:text-gray-400">الرصيد:</p>
                        <span className="font-bold text-emerald-600 dark:text-emerald-400 text-2xl">
                            {formatPoints(selectedCurrentPoints)}
                        </span>
                    </div>
                </div>
                
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  آخر نشاط مسجل:{" "}
                  {new Date(selectedRecord.lastActivity).toLocaleDateString("ar-EG")}
                </p>

                <div className="pt-3 bg-gray-50 dark:bg-gray-900/50 p-3 rounded-lg border border-gray-100 dark:border-gray-700 mt-2">
                  <div className="mb-2 flex items-center justify-between text-xs text-gray-600 dark:text-gray-400">
                    <span className="font-bold">{progressToNextTier}%</span>
                    <span>التقدم للمستوى التالي</span>
                  </div>
                  <div className="h-2 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden">
                    <div
                      className="h-2 rounded-full bg-gradient-to-r from-amber-500 to-purple-600"
                      style={{ width: `${progressToNextTier}%` }}
                    />
                  </div>
                  <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                    {nextTier
                      ? `يحتاج ${formatPoints(pointsToNextTier)} نقطة للوصول لـ ${nextTier.nameAr || nextTier.name}`
                      : "العميل في أعلى مستوى متاح حاليًا 🌟"}
                  </p>
                </div>
              </div>
            ) : (
              <div className="text-right text-sm text-gray-400 py-12 flex flex-col items-center justify-center border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-lg bg-gray-50 dark:bg-gray-800/50">
                 <Search className="h-8 w-8 text-gray-300 mb-2" />
                 اختَر عميلًا من الجدول العرض
              </div>
            )}
          </div>

          <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-700 dark:bg-gray-800">
            <h3 className="mb-4 text-lg font-bold text-gray-900 dark:text-white">
              إجراء عملية على النقاط
            </h3>
            <div className="space-y-3 text-right relative">
              <select
                value={actionType}
                onChange={(event) => setActionType(event.target.value as PointsActionType)}
                className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm dark:border-gray-600 dark:bg-gray-900 dark:text-white"
                disabled={!selectedRecord}
              >
                <option value="ADD">إضافة نقاط (+)</option>
                <option value="REDEEM">استبدال نقاط (-)</option>
                <option value="ADJUST">تعديل يدوي (يتطلب السبب)</option>
              </select>

              <input
                type="number"
                value={pointsValue}
                onChange={(event) => setPointsValue(event.target.value)}
                placeholder={actionType === "ADJUST" ? "مثال: 100 للقيمة الموجبة و -40 للخصم" : "أدخل عدد النقاط المُنفذة"}
                className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-right text-sm dark:border-gray-600 dark:bg-gray-900 dark:text-white disabled:bg-gray-50 dark:disabled:bg-gray-800"
                disabled={!selectedRecord}
              />

              <div className="relative">
                <textarea
                    value={reason}
                    onChange={(event) => setReason(event.target.value)}
                    placeholder={actionType === 'ADJUST' ? "سبب التعديل اليدوي (إلزامي)" : "تفاصيل العملية (اختياري)"}
                    className={`min-h-[80px] w-full rounded-lg border bg-white px-3 py-2.5 text-right text-sm dark:bg-gray-900 dark:text-white disabled:bg-gray-50 dark:disabled:bg-gray-800 ${actionType === 'ADJUST' && !reason.trim() ? "border-amber-400 focus:border-amber-500 outline-none ring-1 ring-amber-400" : "border-gray-300 dark:border-gray-600"}`}
                    disabled={!selectedRecord}
                />
                {actionType === 'ADJUST' && (
                  <AlertTriangle className={`absolute bottom-3 left-3 h-4 w-4 ${reason.trim() ? 'text-emerald-500' : 'text-amber-500'}`} />
                )}
              </div>

              {errorMessage && (
                <p className="rounded-md bg-red-50 px-3 py-2 text-sm text-red-700 dark:bg-red-900/20 dark:text-red-300 border border-red-100 dark:border-red-800">
                  {errorMessage}
                </p>
              )}
              {successMessage && (
                <p className="rounded-md bg-emerald-50 px-3 py-2 text-sm text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-300 border border-emerald-100 dark:border-emerald-800">
                  {successMessage}
                </p>
              )}

              <button
                onClick={handleSubmitAction}
                disabled={!selectedRecord || isSubmitting}
                className={`flex w-full items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-sm font-medium text-white transition disabled:cursor-not-allowed disabled:opacity-50 ${actionType === 'REDEEM' ? 'bg-amber-600 hover:bg-amber-700' : actionType === 'ADJUST' ? 'bg-gray-800 hover:bg-gray-900 dark:bg-gray-700 dark:hover:bg-gray-600' : 'bg-emerald-600 hover:bg-emerald-700'}`}
              >
                {actionType === "ADD" && <ArrowUpCircle className="h-4 w-4" />}
                {actionType === "REDEEM" && <ArrowDownCircle className="h-4 w-4" />}
                {actionType === "ADJUST" && <Wrench className="h-4 w-4" />}
                {isSubmitting ? "جاري التنفيذ..." : "تأكيد العملية"}
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        <div className="rounded-xl border border-amber-200 bg-gradient-to-br from-white to-amber-50 p-5 shadow-sm dark:border-amber-900/30 dark:from-gray-800 dark:to-amber-900/10">
          <div className="mb-3 flex items-center gap-2 text-amber-600 dark:text-amber-500">
            <Target className="h-5 w-5" />
            <h4 className="font-semibold text-gray-900 dark:text-white">
              برامج ولاء كبار المتاجر
            </h4>
          </div>
          <p className="text-sm text-gray-600 dark:text-gray-300 mb-4 h-16">
            فعّل إرسال رسائل آلية عند وصول العميل لمستوى VIP لمكافأته بتوصيل مجاني لتعزيز شعوره بالولاية.
          </p>
          <button onClick={() => setFilterMode("VIP")} className="w-full text-sm py-2 px-3 bg-white border border-amber-200 text-amber-700 rounded-lg hover:bg-amber-50 shadow-sm transition dark:bg-gray-800 dark:border-gray-600 dark:text-amber-400">
             عرض عملاء VIP الآن
          </button>
        </div>

        <div className="rounded-xl border border-purple-200 bg-gradient-to-br from-white to-purple-50 p-5 shadow-sm dark:border-purple-900/30 dark:from-gray-800 dark:to-purple-900/10">
          <div className="mb-3 flex items-center gap-2 text-purple-600 dark:text-purple-400">
            <Sparkles className="h-5 w-5" />
            <h4 className="font-semibold text-gray-900 dark:text-white">
              أيام المضاعفات الترويجية
            </h4>
          </div>
          <p className="text-sm text-gray-600 dark:text-gray-300 mb-2 h-10">
            أبلغ العملاء عن أيام ترويجية لكسب مضاعف عبر الواتساب.
          </p>
           <p className="text-xs text-purple-700 dark:text-purple-300 mb-4 font-medium flex items-center line-clamp-1 w-full truncate">
            المعدل الحالي: {earningRuleText}
          </p>
          <button className="w-full flex items-center justify-center gap-2 text-sm py-2 px-3 bg-purple-600 text-white rounded-lg hover:bg-purple-700 shadow-sm transition">
             <MessageCircle className="h-4 w-4" />
             إرسال تنبيه بالبرنامج (قريباً)
          </button>
        </div>

        <div className="rounded-xl border border-red-200 bg-gradient-to-br from-white to-red-50 p-5 shadow-sm dark:border-red-900/30 dark:from-gray-800 dark:to-red-900/10">
          <div className="mb-3 flex items-center gap-2 text-red-600 dark:text-red-500">
            <Gift className="h-5 w-5" />
            <h4 className="font-semibold text-gray-900 dark:text-white">
              حملات إنقاذ النقاط (Expiry)
            </h4>
          </div>
          <p className="text-sm text-gray-600 dark:text-gray-300 mb-4 h-16">
            العملاء المهددون بخسارة رصيدهم. ارسل لهم عروض استبدال سريعة قبل خصم النقاط نهائياً.
          </p>
          <button onClick={() => setFilterMode("AT_RISK")} className="w-full text-sm py-2 px-3 bg-red-50 border border-red-200 text-red-700 font-medium rounded-lg shadow-sm hover:bg-red-100 transition dark:bg-red-900/30 dark:border-red-900 dark:text-red-400">
             استهداف ({atRiskCustomers.length}) عميل
          </button>
        </div>
      </div>

      {/* Enroll Modal */}
      {isEnrollModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 text-right" dir="rtl">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl dark:bg-gray-800">
             <div className="flex justify-between items-center mb-5 border-b border-gray-100 dark:border-gray-700 pb-3">
                <h3 className="text-xl font-bold text-gray-900 dark:text-white">إضافة عميل لبرنامج ولاء</h3>
                <button onClick={() => setIsEnrollModalOpen(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                   <X className="h-5 w-5" />
                </button>
             </div>
             
             <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">العميل</label>
                  <select 
                    value={enrollData.customerId}
                    onChange={e => setEnrollData({...enrollData, customerId: e.target.value})}
                    className="w-full rounded-lg border border-gray-300 p-2.5 text-sm dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-white"
                  >
                    <option value="">-- اختر عميل من النظام --</option>
                    {allSystemCustomers.map(c => (
                        <option key={c.id} value={c.id}>{c.firstName} {c.lastName} {c.phone ? `(${c.phone})` : ''}</option>
                    ))}
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">برنامج الولاء المستهدف</label>
                  <select 
                    value={enrollData.programId}
                    onChange={e => setEnrollData({...enrollData, programId: e.target.value})}
                    className="w-full rounded-lg border border-gray-300 p-2.5 text-sm dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-white"
                  >
                    <option value="">-- اختر برنامج --</option>
                    {programs.filter(p => p.status === 'ACTIVE').map(p => (
                        <option key={p.id} value={p.id}>{p.nameAr || p.name}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">نقاط ترحيبية مبدئية</label>
                  <input 
                    type="number"
                    value={enrollData.initialPoints}
                    onChange={e => setEnrollData({...enrollData, initialPoints: e.target.value})}
                    className="w-full rounded-lg border border-gray-300 p-2.5 text-sm dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-white text-right"
                  />
                  <p className="text-xs text-gray-500 mt-1">يُضاف الرصيد فور التسجيل في البرنامج.</p>
                </div>

                {errorMessage && (
                  <p className="bg-red-50 text-red-600 p-3 rounded-md text-sm border border-red-100 dark:bg-red-900/20 dark:border-red-900/50">{errorMessage}</p>
                )}

                <div className="flex gap-3 pt-4 border-t border-gray-100 dark:border-gray-700 mt-6">
                   <button 
                     onClick={() => setIsEnrollModalOpen(false)}
                     className="flex-1 rounded-lg border border-gray-300 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700"
                   >
                     إلغاء
                   </button>
                   <button 
                     onClick={handleEnrollCustomer}
                     disabled={isSubmitting || !enrollData.customerId || !enrollData.programId}
                     className="flex-1 rounded-lg bg-emerald-600 py-2.5 text-sm font-medium text-white hover:bg-emerald-700 disabled:opacity-50 flex items-center justify-center gap-2 transition"
                   >
                     <UserPlus className="h-4 w-4" /> 
                     {isSubmitting ? "جاري التسجيل..." : "تسجيل وتفعيل"}
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* History Modal (Simplified for local metadata logic) */}
      {isHistoryModalOpen && selectedRecord && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 text-right" dir="rtl">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl dark:bg-gray-800">
             <div className="flex justify-between items-center border-b border-gray-100 dark:border-gray-700 pb-3 mb-4">
                <h3 className="text-lg font-bold text-gray-900 dark:text-white flex items-center gap-2">
                   <History className="h-5 w-5 text-purple-600" />
                   سجل حركات: {selectedRecord.customer.firstName}
                </h3>
                <button onClick={() => setIsHistoryModalOpen(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                   <X className="h-5 w-5" />
                </button>
             </div>
             
             <div className="space-y-4 max-h-[400px] overflow-y-auto">
                 <div className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4 border border-gray-200 dark:border-gray-700 shadow-inner">
                    <p className="text-sm font-medium text-gray-800 dark:text-gray-200 mb-3">ملخص الحركات والأرصدة:</p>
                    <ul className="text-sm text-gray-600 dark:text-gray-400 space-y-3">
                       <li className="flex justify-between border-b pb-2 dark:border-gray-700">
                          <span>إجمالي المكتسب تاريخياً:</span>
                          <span className="text-emerald-600 font-bold">{formatPoints(toNumber(selectedRecord.totalEarned))} نقطة</span>
                       </li>
                       <li className="flex justify-between border-b pb-2 dark:border-gray-700">
                          <span>إجمالي المستبدل تاريخياً:</span>
                          <span className="text-red-500 font-bold">{formatPoints(toNumber(selectedRecord.totalRedeemed))} نقطة</span>
                       </li>
                       <li className="flex justify-between pt-1">
                          <span>آخر عملية مسجلة:</span>
                          <span className="text-gray-900 dark:text-white font-medium text-xs">{new Date(selectedRecord.lastActivity).toLocaleString("ar-EG")}</span>
                       </li>
                    </ul>
                 </div>
                 
                 {selectedRecord.metadata && selectedRecord.metadata.lastReason && (
                   <div className="bg-amber-50 dark:bg-amber-900/10 p-4 rounded-lg border border-amber-200 dark:border-amber-800/30">
                      <p className="text-xs text-amber-800 dark:text-amber-400 font-medium mb-1">سبب التعديل اليدوي الأخير:</p>
                      <p className="text-sm text-amber-900 dark:text-amber-200">{selectedRecord.metadata.lastReason}</p>
                   </div>
                 )}
                 
                 <p className="text-xs text-center text-gray-400 bg-gray-50 dark:bg-gray-900 p-2 rounded">
                     ملاحظة: سجل الحركات المفصل سيُتاح في التحديث القادم للنظام المعماري.
                 </p>
             </div>
             
             <button 
                  onClick={() => setIsHistoryModalOpen(false)}
                  className="mt-6 w-full rounded-lg border border-gray-300 py-2.5 text-sm font-medium bg-white text-gray-700 hover:bg-gray-50 shadow-sm transition dark:border-gray-600 dark:text-gray-300 dark:bg-gray-800 dark:hover:bg-gray-700"
              >
                  إغلاق السجل
              </button>
          </div>
        </div>
      )}

    </div>
  );
};

export default CustomerPointsCenter;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
    MegaphoneIcon,
    PaperAirplaneIcon,
    PhotoIcon,
    UserGroupIcon,
    ShoppingBagIcon,
    ArrowPathIcon,
    CheckCircleIcon as CheckCircleOutline,
    ExclamationCircleIcon,
    BoltIcon,
    ClockIcon,
    ChartBarIcon,
    XMarkIcon,
    InformationCircleIcon,
    SparklesIcon,
    CalendarDaysIcon,
} from '@heroicons/react/24/outline';
import { CheckCircleIcon as CheckCircleSolid } from '@heroicons/react/24/solid';
import { apiClient } from '../../services/apiClient';
import { useTranslation } from 'react-i18next';
import { formatCurrency } from '../../utils/currency';


// ─────────────────────────────────────────
// Types
// ─────────────────────────────────────────
type Audience = 'all' | 'withOrders' | 'newCustomers' | 'activeCustomers';
type NotifyMode = 'general' | 'birthday';

interface CustomerWhatsAppNotifyProps {
    mode?: NotifyMode;
}

interface Session {
    sessionId: string;
    phoneNumber: string;
    isConnected: boolean;
    status: string;
}

interface Product {
    id: string;
    name: string;
    price: number | string;
    images: string[];
    description?: string;
}

interface CampaignStatus {
    status: 'running' | 'completed' | 'cancelled';
    sent: number;
    failed: number;
    total: number;
    progress: number;
    startedAt: string;
    completedAt?: string;
    errors: {
        customerId: string;
        phone?: string;
        formattedPhone?: string;
        name?: string;
        error: string;
        timestamp?: string;
    }[];
}

// ─────────────────────────────────────────
// Audience Options
// ─────────────────────────────────────────
const getAudienceOptions = (t: any) => [
    {
        value: 'all',
        label: t('whatsappNotify.audienceOptions.all'),
        desc: t('whatsappNotify.audienceOptions.allDesc'),
        icon: '👥',
        color: 'from-violet-500 to-purple-600',
    },
    {
        value: 'withOrders',
        label: t('whatsappNotify.audienceOptions.withOrders'),
        desc: t('whatsappNotify.audienceOptions.withOrdersDesc'),
        icon: '🛒',
        color: 'from-blue-500 to-cyan-600',
    },
    {
        value: 'newCustomers',
        label: t('whatsappNotify.audienceOptions.newCustomers'),
        desc: t('whatsappNotify.audienceOptions.newCustomersDesc'),
        icon: '✨',
        color: 'from-emerald-500 to-green-600',
    },
    {
        value: 'activeCustomers',
        label: t('whatsappNotify.audienceOptions.activeCustomers'),
        desc: t('whatsappNotify.audienceOptions.activeCustomersDesc'),
        icon: '⚡',
        color: 'from-amber-500 to-orange-600',
    },
];

const getTemplates = (t: any) => [
    {
        label: t('whatsappNotify.templates.newProduct'),
        text: t('whatsappNotify.templates.newProductText'),
    },
    {
        label: t('whatsappNotify.templates.specialOffer'),
        text: t('whatsappNotify.templates.specialOfferText'),
    },
    {
        label: t('whatsappNotify.templates.generalContact'),
        text: t('whatsappNotify.templates.generalContactText'),
    },
];

const getBirthdayTemplates = () => [
    {
        label: 'تهنئة رسمية',
        text: 'عزيزي {اسم العميل} ✨\n\nكل عام وأنتم بخير بمناسبة عيد ميلادكم 🎉!\nنتمنى لكم عاماً سعيداً مليئاً بالنجاح والتوفيق.\n\nمع تحياتنا،\nفريق العمل',
    },
    {
        label: 'تهنئة ودية + خصم',
        text: 'كل سنة وأنت طيب يا {اسم العميل}! 🎂🥳\n\nعشان النهاردة يوم مش عادي، حبينا نحتفل معاك ونقدملك خصم 20% على أي طلب بمناسبة عيد ميلادك! 🎁\n\nاطلب دلوقتي واستمتع بالخصم ✨',
    },
    {
        label: 'رسالة قصيرة',
        text: 'عيد ميلاد سعيد {اسم العميل} 🎉🎂 نتمنى لك يوماً رائعاً وعاماً مليئاً بالسعادة!',
    },
];


// ─────────────────────────────────────────
// Component
// ─────────────────────────────────────────
const CustomerWhatsAppNotify: React.FC<CustomerWhatsAppNotifyProps> = ({ mode = 'general' }) => {
    const { t } = useTranslation();
    const isBirthdayPage = mode === 'birthday';

    const campaignStorageKey = isBirthdayPage ? 'active_birthday_campaign_id' : 'active_general_campaign_id';

    // Session
    const [sessions, setSessions] = useState<Session[]>([]);
    const [selectedSession, setSelectedSession] = useState('');
    const [sessionsLoading, setSessionsLoading] = useState(true);

    // Audience
    const [audience, setAudience] = useState<Audience>('withOrders');
    const [newDays, setNewDays] = useState(7);
    const [audienceCount, setAudienceCount] = useState<number | null>(null);
    const [audienceLoading, setAudienceLoading] = useState(false);

    // Message
    const [message, setMessage] = useState('');
    const [mediaUrl, setMediaUrl] = useState('');

    // Birthday campaign
    const [birthdayDate, setBirthdayDate] = useState(() => {
        const now = new Date();
        const y = now.getFullYear();
        const m = String(now.getMonth() + 1).padStart(2, '0');
        const d = String(now.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    });
    const [birthdayAudienceCount, setBirthdayAudienceCount] = useState<number | null>(null);
    const [birthdayAudienceLoading, setBirthdayAudienceLoading] = useState(false);
    const [birthdayMessage, setBirthdayMessage] = useState(
        t('whatsappNotify.birthdayMessageDefault')
    );

    const [birthdayMediaUrl, setBirthdayMediaUrl] = useState('');

    // Product picker
    const [showProducts, setShowProducts] = useState(false);
    const [productSearch, setProductSearch] = useState('');
    const [products, setProducts] = useState<Product[]>([]);
    const [productsLoading, setProductsLoading] = useState(false);
    const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

    // Campaign
    const [sending, setSending] = useState(false);
    const [campaignId, setCampaignId] = useState<string | null>(() => localStorage.getItem(campaignStorageKey));
    const [campaign, setCampaign] = useState<CampaignStatus | null>(null);
    const [sendError, setSendError] = useState('');

    // Delay Settings
    const [delayValue, setDelayValue] = useState(1.5);
    const [delayUnit, setDelayUnit] = useState<'seconds' | 'minutes'>('seconds');
    const [delayMode, setDelayMode] = useState<'perMessage' | 'perSession'>('perMessage');

    const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

    // ── Load Sessions ──
    const loadSessions = useCallback(async () => {
        setSessionsLoading(true);
        try {
            const res = await apiClient.get(`/customers/whatsapp-notify/sessions?t=${Date.now()}`);
            const list: Session[] = res.data?.sessions || [];
            setSessions(list);
            const active = list.find(s => s.isConnected);
            if (active) setSelectedSession(active.sessionId);
            else if (list.length > 0) setSelectedSession(list[0].sessionId);
        } catch { }
        finally { setSessionsLoading(false); }
    }, []);

    useEffect(() => { loadSessions(); }, [loadSessions]);

    // ── Preview Audience Count ──
    const previewAudience = useCallback(async (aud: Audience, days: number) => {
        setAudienceLoading(true);
        setAudienceCount(null);
        try {
            const params: Record<string, string> = { audience: aud };
            if (aud === 'newCustomers') params.newDays = String(days);
            const res = await apiClient.get('/customers/whatsapp-notify/preview-audience', { params });
            setAudienceCount(res.data?.count ?? 0);
        } catch {
            setAudienceCount(null);
        } finally {
            setAudienceLoading(false);
        }
    }, []);

    useEffect(() => {
        if (!isBirthdayPage) previewAudience(audience, newDays);
    }, [audience, newDays, previewAudience, isBirthdayPage]);

    const previewBirthdayAudience = useCallback(async (targetDate: string) => {
        if (!targetDate) return;
        setBirthdayAudienceLoading(true);
        setBirthdayAudienceCount(null);
        try {
            const res = await apiClient.get('/customers/whatsapp-notify/preview-birthday-audience', {
                params: { date: targetDate },
            });
            setBirthdayAudienceCount(res.data?.count ?? 0);
        } catch {
            setBirthdayAudienceCount(null);
        } finally {
            setBirthdayAudienceLoading(false);
        }
    }, []);

    useEffect(() => {
        if (isBirthdayPage) previewBirthdayAudience(birthdayDate);
    }, [birthdayDate, previewBirthdayAudience, isBirthdayPage]);
    useEffect(() => { setSendError(''); }, [mode]);

    // ── Load Products ──
    const loadProducts = useCallback(async () => {
        setProductsLoading(true);
        try {
            const res = await apiClient.get('/customers/whatsapp-notify/products?limit=60');
            setProducts(res.data?.data || []);
        } catch { } finally { setProductsLoading(false); }
    }, []);

    useEffect(() => {
        if (!isBirthdayPage && showProducts) loadProducts();
    }, [showProducts, loadProducts, isBirthdayPage]);

    // ── Poll Campaign Status ──
    useEffect(() => {
        if (!campaignId) return;

        pollRef.current = setInterval(async () => {
            try {
                const res = await apiClient.get(`/customers/whatsapp-notify/campaign/${campaignId}`);
                const data: CampaignStatus & { status: string } = res.data;
                setCampaign(data as CampaignStatus);

                if (data.status === 'completed' || data.status === 'cancelled') {
                    if (pollRef.current) clearInterval(pollRef.current);
                    setSending(false);
                    localStorage.removeItem(campaignStorageKey);
                }
            } catch (err: any) {
                if (err.response?.status === 404) {
                    if (pollRef.current) clearInterval(pollRef.current);
                    setSending(false);
                    setCampaign(null);
                    setCampaignId(null);
                    localStorage.removeItem(campaignStorageKey);
                }
            }
        }, 2000);

        return () => { if (pollRef.current) clearInterval(pollRef.current); };
    }, [campaignId, campaignStorageKey]);

    // ── Insert product info into message ──
    const insertProduct = (product: Product) => {
        const imgUrl = Array.isArray(product.images) && product.images.length > 0
            ? product.images[0]
            : '';
        setMessage(prev =>
            prev
                .replace(/{productName}/g, product.name)
                .replace(/{price}/g, String(product.price))
        );
        if (imgUrl && !mediaUrl) setMediaUrl(imgUrl);
        setSelectedProduct(product);
        setShowProducts(false);
    };

    // ── Send ──
    const handleSend = async () => {
        if (!message.trim()) { setSendError(t('whatsappNotify.writeMessageFirst')); return; }
        if (!Number.isFinite(delayValue) || delayValue <= 0) { setSendError(t('whatsappNotify.invalidDelay')); return; }

        const connectedSession = sessions.find(s => s.isConnected);
        if (!connectedSession) {
            setSendError(t('whatsappNotify.noConnectedSessionError'));
            return;
        }


        setSendError('');
        setSending(true);
        setCampaign(null);
        setCampaignId(null);
        localStorage.removeItem(campaignStorageKey);

        try {
            const payload: Record<string, unknown> = {
                audience,
                message: message.trim(),
                sessionId: selectedSession || connectedSession.sessionId,
                delayValue,
                delayUnit,
                delayMode,
            };
            if (audience === 'newCustomers') payload.newDays = newDays;
            if (mediaUrl.trim()) payload.mediaUrl = mediaUrl.trim();

            const res = await apiClient.post('/customers/whatsapp-notify/smart-send', payload);
            if (res.data?.success) {
                const newId = res.data.campaignId;
                setCampaignId(newId);
                localStorage.setItem(campaignStorageKey, newId);
                setCampaign({
                    status: 'running',
                    sent: 0,
                    failed: 0,
                    total: res.data.total,
                    progress: 0,
                    startedAt: new Date().toISOString(),
                    errors: [],
                });
            } else {
                setSendError(res.data?.message || t('whatsappNotify.errorGeneric'));
                setSending(false);
            }
        } catch (err: any) {
            setSendError(err?.response?.data?.message || t('whatsappNotify.failed'));
            setSending(false);
        }
    };

    const handleSendBirthday = async () => {
        if (!birthdayMessage.trim()) { setSendError(t('whatsappNotify.birthdayMessagePlaceholder')); return; }
        if (!Number.isFinite(delayValue) || delayValue <= 0) { setSendError(t('whatsappNotify.invalidDelay')); return; }

        const connectedSession = sessions.find(s => s.isConnected);
        if (!connectedSession) {
            setSendError(t('whatsappNotify.noConnectedSessionError'));
            return;
        }


        setSendError('');
        setSending(true);
        setCampaign(null);
        setCampaignId(null);
        localStorage.removeItem(campaignStorageKey);

        try {
            const payload: Record<string, unknown> = {
                date: birthdayDate,
                message: birthdayMessage.trim(),
                sessionId: selectedSession || connectedSession.sessionId,
                delayValue,
                delayUnit,
                delayMode,
            };
            if (birthdayMediaUrl.trim()) payload.mediaUrl = birthdayMediaUrl.trim();

            const res = await apiClient.post('/customers/whatsapp-notify/smart-send-birthday', payload);
            if (res.data?.success) {
                const newId = res.data.campaignId;
                setCampaignId(newId);
                localStorage.setItem(campaignStorageKey, newId);
                setCampaign({
                    status: 'running',
                    sent: 0,
                    failed: 0,
                    total: res.data.total,
                    progress: 0,
                    startedAt: new Date().toISOString(),
                    errors: [],
                });
            } else {
                setSendError(res.data?.message || t('whatsappNotify.errorGeneric'));
                setSending(false);
            }
        } catch (err: any) {
            setSendError(err?.response?.data?.message || t('whatsappNotify.failed'));
            setSending(false);
        }
    };

    // ── Stop ──
    const handleStop = async () => {
        if (!campaignId) return;
        try {
            await apiClient.delete(`/customers/whatsapp-notify/campaign/${campaignId}`);
            // Polling will detect 'cancelled' status or we can update UI locally
        } catch (err) {
            console.error('Stop failed:', err);
        }
    };

    // ── Connected session ──
    const connectedSession = sessions.find(s => s.isConnected);

    // ─────────────────────────────────────────
    // Render
    // ─────────────────────────────────────────
    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-950 text-gray-900 dark:text-white p-4 md:p-6 transition-colors duration-300" dir="rtl">

            {/* ── Header ── */}
            <div className="mb-6 flex items-start justify-between">
                <div>
                    <h1 className="text-2xl font-bold flex items-center gap-2 text-gray-900 dark:text-white">
                        <span className="text-3xl">{isBirthdayPage ? '🎂' : '📢'}</span>
                        {isBirthdayPage ? t('whatsappNotify.birthdayTitle') : t('whatsappNotify.title')}
                    </h1>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                        {!isBirthdayPage
                            ? t('whatsappNotify.subtitle')
                            : t('whatsappNotify.birthdaySubtitle')}
                    </p>
                </div>

                {/* Session badge */}
                <div className="flex items-center gap-2">
                    {sessionsLoading ? (
                        <div className="h-8 w-32 bg-gray-200 dark:bg-gray-800 rounded-full animate-pulse" />
                    ) : connectedSession ? (
                        <div className="flex items-center gap-1.5 bg-green-500/10 dark:bg-green-500/15 border border-green-500/20 dark:border-green-500/30 rounded-full px-3 py-1.5 text-xs text-green-600 dark:text-green-400 font-medium">
                            <span className="h-1.5 w-1.5 rounded-full bg-green-500 dark:bg-green-400 animate-pulse" />
                            🟢 {connectedSession.phoneNumber}
                        </div>
                    ) : (
                        <div className="flex items-center gap-1.5 bg-red-500/10 dark:bg-red-500/15 border border-red-500/20 dark:border-red-500/30 rounded-full px-3 py-1.5 text-xs text-red-600 dark:text-red-400 font-medium">
                            🔴 {t('whatsappNotify.sessionDisconnected')}
                        </div>
                    )}
                    <button
                        onClick={loadSessions}
                        className="p-1.5 rounded-full bg-white dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-400 dark:text-gray-400 hover:text-gray-600 dark:hover:text-white shadow-sm dark:shadow-none border border-gray-200 dark:border-transparent transition-all"
                        title={t('whatsappNotify.refreshSession')}
                    >
                        <ArrowPathIcon className="h-4 w-4" />
                    </button>
                </div>
            </div>

            {/* ── No session warning ── */}
            {!sessionsLoading && !connectedSession && (
                <div className="mb-4 flex items-start gap-3 bg-red-500/10 border border-red-500/30 rounded-xl p-4 text-sm text-red-300">
                    <ExclamationCircleIcon className="h-5 w-5 flex-shrink-0 mt-0.5" />
                    <div>
                        <p className="font-medium">{t('whatsappNotify.noSessionWarning')}</p>
                        <p className="text-xs text-red-400 mt-0.5">
                            {t('whatsappNotify.noSessionWarningDesc').split(' ').map((word, i, arr) => {
                                if (word === t('common.settings')) {
                                    return <a key={i} href="/whatsapp/settings" className="underline">{t('whatsappNotify.whatsappSettings')}</a>;
                                }
                                return word + (i === arr.length - 1 ? '' : ' ');
                            })}
                        </p>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
                {!isBirthdayPage ? (
                    <>
                    {/* ══════════════════════════════════════
                    LEFT: Audience & Progress
                ══════════════════════════════════════ */}
                    <div className="lg:col-span-12 xl:col-span-5 space-y-5">

                        {/* Audience Cards */}
                        <div className="bg-white dark:bg-gray-900/60 backdrop-blur-xl border border-gray-200 dark:border-white/10 rounded-3xl p-5 shadow-xl dark:shadow-2xl">
                            <h2 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2 mb-4">
                                <span className="p-1.5 rounded-lg bg-violet-500/10 dark:bg-violet-500/20 text-violet-600 dark:text-violet-400">
                                    <UserGroupIcon className="h-4 w-4" />
                                </span>
                                {t('whatsappNotify.audienceTarget')}
                            </h2>

                            <div className="grid grid-cols-2 gap-3 mb-4">
                                {getAudienceOptions(t).map(opt => (
                                    <button

                                        key={opt.value}
                                        onClick={() => setAudience(opt.value)}
                                        className={`relative p-3.5 rounded-2xl border text-right transition-all duration-300 group ${audience === opt.value
                                            ? 'border-violet-500/60 bg-violet-500/5 dark:bg-violet-500/10 shadow-[0_0_20px_rgba(139,92,246,0.1)] dark:shadow-[0_0_20px_rgba(139,92,246,0.15)]'
                                            : 'border-gray-100 dark:border-white/5 bg-gray-50 dark:bg-white/5 hover:border-gray-200 dark:hover:border-white/20 hover:bg-white dark:hover:bg-white/10'
                                            }`}
                                    >
                                        <div className="text-2xl mb-1.5 group-hover:scale-110 transition-transform">{opt.icon}</div>
                                        <div className="text-xs font-bold text-gray-900 dark:text-white mb-0.5">{opt.label}</div>
                                        <div className="text-[10px] text-gray-500 dark:text-gray-400 leading-snug">{opt.desc}</div>
                                        {audience === opt.value && (
                                            <span className="absolute top-2.5 left-2.5">
                                                <div className="h-2 w-2 rounded-full bg-violet-500 dark:bg-violet-400 shadow-[0_0_8px_#a78bfa]" />
                                            </span>
                                        )}
                                    </button>
                                ))}
                            </div>

                            {/* New days picker */}
                            {audience === 'newCustomers' && (
                                <div className="mt-4 flex items-center justify-center gap-2 bg-emerald-500/5 border border-emerald-500/10 rounded-2xl p-3 animate-in slide-in-from-top-2">
                                    <span className="text-xs text-emerald-600 dark:text-emerald-300 font-medium">{t('whatsappNotify.joinedInLast')}</span>
                                    <input
                                        type="number"
                                        min={1}
                                        max={365}
                                        value={newDays}
                                        onChange={e => setNewDays(Number(e.target.value))}
                                        className="w-20 text-center bg-white dark:bg-gray-950/50 border border-emerald-500/30 rounded-xl px-2 py-2 text-sm text-gray-900 dark:text-white focus:ring-2 focus:ring-emerald-500/40 outline-none"
                                    />
                                    <span className="text-xs text-emerald-600 dark:text-emerald-300">{t('whatsappNotify.days')}</span>
                                </div>
                            )}

                            {/* Audience Preview Box */}
                            <div className="bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 rounded-2xl p-4 flex items-center justify-between group">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 rounded-xl bg-violet-500/5 dark:bg-violet-500/10 text-violet-600 dark:text-violet-400 group-hover:scale-110 transition-transform">
                                        <ChartBarIcon className="h-4 w-4" />
                                    </div>
                                    <div>
                                        <div className="text-[10px] text-gray-400 dark:text-gray-500 font-bold uppercase tracking-wider">{t('whatsappNotify.willSendTo')}</div>
                                        <div className="text-[11px] text-gray-500 dark:text-gray-300 mt-0.5">{t('whatsappNotify.realCustomers')}</div>
                                    </div>
                                </div>
                                {audienceLoading ? (
                                    <div className="h-7 w-16 bg-gray-200 dark:bg-white/10 rounded-lg animate-pulse" />
                                ) : (
                                    <div className="text-right">
                                        <span className="text-2xl font-black text-gray-900 dark:text-white">{audienceCount?.toLocaleString() ?? 0}</span>
                                        <span className="text-[10px] text-gray-400 dark:text-gray-500 block font-bold">{t('whatsappNotify.customer')}</span>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Campaign Progress */}
                        {campaign && (
                            <div className="bg-white dark:bg-gray-900/60 backdrop-blur-xl border border-gray-200 dark:border-white/10 rounded-3xl p-5 shadow-xl dark:shadow-2xl animate-in fade-in zoom-in-95 duration-500">
                                <div className="flex items-center justify-between mb-4">
                                    <h2 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                        {campaign.status === 'running' ? (
                                            <><div className="h-2 w-2 rounded-full bg-blue-500 animate-ping" /> {t('whatsappNotify.sending')}</>
                                        ) : campaign.status === 'cancelled' ? (
                                            <><ExclamationCircleIcon className="h-4 w-4 text-amber-500" /> {t('whatsappNotify.paused')}</>
                                        ) : (
                                            <><CheckCircleSolid className="h-4 w-4 text-green-500" /> {t('whatsappNotify.completed')}</>
                                        )}
                                    </h2>
                                    {campaign.status === 'running' && (
                                        <button
                                            onClick={handleStop}
                                            className="text-[10px] px-2.5 py-1.5 bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 border border-red-500/20 dark:border-red-500/30 rounded-lg transition-colors flex items-center gap-1 font-bold"
                                        >
                                            <XMarkIcon className="h-3 w-3" />
                                            {t('whatsappNotify.pause')}
                                        </button>
                                    )}
                                </div>

                                {/* Progress bar */}
                                <div className="relative h-3 bg-gray-100 dark:bg-gray-950 rounded-full overflow-hidden mb-5 shadow-inner">
                                    <div
                                        className={`h-full rounded-full transition-all duration-1000 ease-out ${campaign.status === 'completed' ? 'bg-gradient-to-r from-green-500 to-emerald-400' : 'bg-gradient-to-r from-blue-500 to-violet-500'}`}
                                        style={{ width: `${(campaign.sent + campaign.failed) / campaign.total * 100}%` }}
                                    />
                                    {campaign.status === 'running' && (
                                        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-shimmer" style={{ backgroundSize: '200% 100%' }} />
                                    )}
                                </div>

                                <div className="grid grid-cols-3 gap-3">
                                    <div className="bg-gray-50 dark:bg-white/5 rounded-2xl p-3 border border-gray-100 dark:border-white/5 text-center">
                                        <div className="text-xl font-black text-gray-900 dark:text-white">{campaign.total}</div>
                                        <div className="text-[10px] text-gray-400 dark:text-gray-500 font-bold uppercase">{t('whatsappNotify.audience')}</div>
                                    </div>
                                    <div className="bg-green-500/5 rounded-2xl p-3 border border-green-500/10 text-center">
                                        <div className="text-xl font-black text-green-600 dark:text-green-400">{campaign.sent}</div>
                                        <div className="text-[10px] text-green-600/70 dark:text-gray-400 font-bold uppercase">{t('whatsappNotify.done')}</div>
                                    </div>
                                    <div className="bg-red-500/5 rounded-2xl p-3 border border-red-500/10 text-center">
                                        <div className="text-xl font-black text-red-600 dark:text-red-400">{campaign.failed}</div>
                                        <div className="text-[10px] text-red-600/70 dark:text-gray-400 font-bold uppercase">{t('whatsappNotify.failed')}</div>
                                    </div>
                                </div>

                                {/* Error Logs (Collapsible or visible if errors exist) */}
                                {campaign.errors && campaign.errors.length > 0 && (
                                    <div className="mt-4 pt-4 border-t border-gray-100 dark:border-white/5">
                                        <label className="text-[10px] text-red-500 font-black uppercase block mb-2">{t('whatsappNotify.errorLogs')} ({campaign.errors.length})</label>
                                        <div className="max-h-32 overflow-y-auto custom-scrollbar space-y-1.5">
                                            {campaign.errors.map((err, idx) => (
                                                <div key={idx} className="flex items-center justify-between text-[9px] bg-red-500/5 p-2 rounded-lg border border-red-500/10">
                                                    <span className="font-bold text-gray-700 dark:text-gray-300">{err.phone} {err.name ? `(${err.name})` : ''}</span>
                                                    <span className="text-red-500 font-medium">{err.error}</span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* ══════════════════════════════════════
                RIGHT: Message Composer & Preview
            ══════════════════════════════════════ */}
                    <div className="lg:col-span-12 xl:col-span-7 space-y-5">

                        {/* Editor Card */}
                        <div className="bg-white dark:bg-gray-900/60 backdrop-blur-xl border border-gray-200 dark:border-white/10 rounded-3xl p-5 shadow-xl dark:shadow-2xl">
                            <div className="flex items-center justify-between mb-4">
                                <h2 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                    <span className="p-1.5 rounded-lg bg-amber-500/10 dark:bg-amber-500/20 text-amber-600 dark:text-amber-400">
                                        <PaperAirplaneIcon className="h-4 w-4" />
                                    </span>
                                    {t('whatsappNotify.notificationContent')}
                                </h2>
                                <div className="flex flex-wrap gap-2">
                                    <button
                                        onClick={() => setShowProducts(!showProducts)}
                                        className="text-[10px] px-3 py-1.5 rounded-full bg-gray-50 dark:bg-white/5 hover:bg-gray-100 dark:hover:bg-white/10 border border-gray-200 dark:border-white/10 text-gray-600 dark:text-gray-300 transition-all flex items-center gap-1.5 font-bold"
                                    >
                                        <ShoppingBagIcon className="h-3 w-3" />
                                        {t('whatsappNotify.linkProduct')}
                                    </button>
                                    {getTemplates(t).map((t_temp, i) => (
                                        <button
                                            key={i}
                                            onClick={() => setMessage(t_temp.text)}
                                            className="text-[10px] px-3 py-1.5 rounded-full bg-gray-50 dark:bg-white/5 hover:bg-gray-100 dark:hover:bg-white/10 border border-gray-200 dark:border-white/10 text-gray-600 dark:text-gray-300 transition-all font-bold"
                                        >
                                            {t_temp.label}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Product Picker (Inline) */}
                            {showProducts && (
                                <div className="mb-4 bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl p-4 animate-in fade-in zoom-in-95">
                                    <div className="flex items-center gap-2 mb-3">
                                        <input
                                            type="text"
                                            placeholder={t('whatsappNotify.searchProduct')}
                                            value={productSearch}
                                            onChange={e => setProductSearch(e.target.value)}
                                            className="flex-1 bg-white dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl px-3 py-2 text-xs text-gray-900 dark:text-white focus:ring-1 focus:ring-violet-500 outline-none shadow-sm dark:shadow-none"
                                        />
                                        <button onClick={() => setShowProducts(false)} className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-white transition-colors">
                                            <XMarkIcon className="h-4 w-4" />
                                        </button>
                                    </div>
                                    {productsLoading ? (
                                        <div className="grid grid-cols-2 gap-2">
                                            {[1, 2, 3, 4].map(i => <div key={i} className="h-14 bg-gray-200 dark:bg-white/5 rounded-xl animate-pulse" />)}
                                        </div>
                                    ) : (
                                        <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto custom-scrollbar pr-1">
                                            {products
                                                .filter(p => !productSearch || p.name.toLowerCase().includes(productSearch.toLowerCase()))
                                                .map(p => (
                                                    <button
                                                        key={p.id}
                                                        onClick={() => insertProduct(p)}
                                                        className="flex items-center gap-2 p-2 rounded-xl bg-white dark:bg-black/20 hover:bg-gray-100 dark:hover:bg-white/5 border border-gray-100 dark:border-white/5 text-right text-[10px] transition-all shadow-sm dark:shadow-none"
                                                    >
                                                        {p.images?.[0] ? (
                                                            <img src={p.images[0]} alt="" className="h-10 w-10 rounded-lg object-cover flex-shrink-0 shadow-md" />
                                                        ) : (
                                                            <div className="h-10 w-10 rounded-lg bg-gray-100 dark:bg-gray-800 flex items-center justify-center flex-shrink-0 text-gray-400 dark:text-gray-600">
                                                                <ShoppingBagIcon className="h-5 w-5" />
                                                            </div>
                                                        )}
                                                        <div className="min-w-0 flex-1">
                                                            <div className="text-gray-900 dark:text-white truncate font-bold">{p.name}</div>
                                                            <div className="text-violet-600 dark:text-violet-400 font-black mt-0.5">{formatCurrency(typeof p.price === 'string' ? parseFloat(p.price) : p.price)}</div>
                                                        </div>
                                                    </button>
                                                ))}
                                        </div>
                                    )}
                                </div>
                            )}

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                {/* Editor */}
                                <div className="space-y-4">
                                    <div>
                                        <label className="text-[10px] text-gray-500 dark:text-gray-500 font-black uppercase mb-2 block">{t('whatsappNotify.messageText')}</label>
                                        <textarea
                                            value={message}
                                            onChange={e => setMessage(e.target.value)}
                                            rows={8}
                                            placeholder={t('whatsappNotify.messagePlaceholder')}
                                            className="w-full bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-2xl px-4 py-3 text-sm text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-600 resize-none focus:ring-2 focus:ring-violet-500/20 dark:focus:ring-violet-500/30 outline-none transition-all shadow-inner"
                                        />
                                        <div className="flex items-center justify-between mt-2 px-1">
                                            <div className="flex items-center gap-1.5">
                                                <span className="h-1.5 w-1.5 rounded-full bg-violet-500 dark:bg-violet-400" />
                                                <span className="text-[10px] text-gray-400 dark:text-gray-500 font-bold">{t('whatsappNotify.charCount', { count: message.length })}</span>
                                            </div>
                                            <button onClick={() => setMessage('')} className="text-[10px] text-gray-400 dark:text-gray-600 hover:text-red-500 dark:hover:text-red-400 font-bold transition-colors">{t('whatsappNotify.clearText')}</button>
                                        </div>
                                        <div className="mt-2 flex items-center gap-1.5 bg-violet-500/5 dark:bg-violet-500/10 border border-violet-500/10 rounded-lg p-2">
                                            <SparklesIcon className="h-3 w-3 text-violet-500 dark:text-violet-400" />
                                            <p className="text-[9px] text-violet-700 dark:text-violet-300">
                                                {t('whatsappNotify.aiTip')}
                                            </p>
                                        </div>
                                    </div>

                                    <div>
                                        <label className="text-[10px] text-gray-500 dark:text-gray-500 font-black uppercase mb-2 block">{t('whatsappNotify.imageUrl')}</label>
                                        <div className="relative group">
                                            <PhotoIcon className="absolute right-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400 dark:text-gray-500 group-focus-within:text-violet-500 dark:group-focus-within:text-violet-400 transition-colors" />
                                            <input
                                                value={mediaUrl}
                                                onChange={e => setMediaUrl(e.target.value)}
                                                placeholder="https://..."
                                                className="w-full bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl pr-10 pl-4 py-3 text-xs text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-700 outline-none focus:ring-2 focus:ring-violet-500/20 dark:focus:ring-violet-500/30 transition-all shadow-inner"
                                            />
                                        </div>
                                    </div>

                                    {/* Delay Settings */}
                                    <div className="pt-4 border-t border-gray-100 dark:border-white/5 space-y-3">
                                        <div className="flex items-center justify-between mb-1">
                                            <label className="text-[10px] text-violet-600 dark:text-violet-400 font-black uppercase flex items-center gap-1.5">
                                                <ClockIcon className="h-3 w-3" />
                                                {t('whatsappNotify.delaySettings')}
                                            </label>

                                            {/* Safety Badge */}
                                            {(() => {
                                                const totalSec = delayUnit === 'seconds' ? delayValue : delayValue * 60;
                                                if (totalSec < 5) return <span className="text-[8px] px-1.5 py-0.5 bg-red-500/10 text-red-500 border border-red-500/20 rounded-md font-bold">{t('whatsappNotify.safetyLow')}</span>;
                                                if (totalSec < 15) return <span className="text-[8px] px-1.5 py-0.5 bg-amber-500/10 text-amber-600 dark:text-amber-500 border border-amber-500/20 rounded-md font-bold">{t('whatsappNotify.safetyMedium')}</span>;
                                                return <span className="text-[8px] px-1.5 py-0.5 bg-green-500/10 text-green-600 dark:text-green-400 border border-green-500/20 rounded-md font-bold">{t('whatsappNotify.safetyHigh')}</span>;
                                            })()}
                                        </div>
                                        <div className="grid grid-cols-2 gap-3">
                                            <div className="flex items-center gap-2 bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl px-3 py-2 shadow-inner">
                                                <input
                                                    type="number"
                                                    value={delayValue}
                                                    onChange={e => setDelayValue(Number(e.target.value))}
                                                    min={0.5}
                                                    step={0.5}
                                                    className="w-12 bg-transparent text-xs text-gray-900 dark:text-white outline-none font-black"
                                                />
                                                <select
                                                    value={delayUnit}
                                                    onChange={e => setDelayUnit(e.target.value as any)}
                                                    className="bg-transparent text-[10px] text-gray-500 dark:text-gray-400 outline-none cursor-pointer font-bold"
                                                >
                                                    <option value="seconds">{t('whatsappNotify.seconds')}</option>
                                                    <option value="minutes">{t('whatsappNotify.minutes')}</option>
                                                </select>
                                            </div>
                                            <select
                                                value={delayMode}
                                                onChange={e => setDelayMode(e.target.value as any)}
                                                className="bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl px-3 py-2 text-[10px] text-gray-600 dark:text-gray-300 outline-none cursor-pointer font-bold shadow-inner"
                                            >
                                                <option value="perMessage">{t('whatsappNotify.perMessage')}</option>
                                                <option value="perSession">{t('whatsappNotify.perSession')}</option>
                                            </select>
                                        </div>
                                        <p className="text-[9px] text-gray-400 dark:text-gray-500 leading-relaxed px-1 font-medium">
                                            {t('whatsappNotify.delayDesc', {
                                                value: delayValue,
                                                unit: delayUnit === 'seconds' ? t('whatsappNotify.seconds') : t('whatsappNotify.minutes'),
                                                mode: delayMode === 'perMessage' ? t('whatsappNotify.perMessage') : t('whatsappNotify.perSession')
                                            })}
                                        </p>
                                    </div>
                                </div>

                                {/* Live Preview (WhatsApp Bubble) */}
                                <div className="hidden md:block">
                                    <label className="text-[10px] text-gray-500 dark:text-gray-500 font-black uppercase mb-2 block">{t('whatsappNotify.livePreview')}</label>
                                    <div className="bg-[#0b141a] rounded-3xl overflow-hidden border border-gray-200 dark:border-white/5 h-[340px] relative shadow-2xl">
                                        {/* Whatsapp Header */}
                                        <div className="bg-[#202c33] px-3 py-2 flex items-center gap-2">
                                            <div className="h-8 w-8 rounded-full bg-gray-600" />
                                            <div>
                                                <div className="text-[11px] font-bold text-[#e9edef]">{t('whatsappNotify.customerName')}</div>
                                                <div className="text-[9px] text-[#8696a0]">{t('whatsappNotify.onlineNow')}</div>
                                            </div>
                                        </div>
                                        {/* Chat Background */}
                                        <div className="absolute inset-x-0 top-12 bottom-0 bg-[#0b141a] opacity-50" style={{ backgroundImage: 'url("https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png")', backgroundSize: 'contain' }} />

                                        {/* Bubble */}
                                        <div className="relative p-4 flex flex-col items-start overflow-y-auto h-full custom-scrollbar">
                                            <div className="max-w-[90%] bg-[#005c4b] rounded-2xl rounded-tr-none p-1.5 shadow-md self-end mb-2 animate-in fade-in slide-in-from-right-2">
                                                {mediaUrl && (
                                                    <img src={mediaUrl} alt="" className="w-full rounded-xl mb-1.5 object-cover max-h-40 shadow-sm" onError={e => e.currentTarget.style.display = 'none'} />
                                                )}
                                                <div className="px-2 pb-1">
                                                    <div className="text-[12px] text-[#e9edef] leading-relaxed whitespace-pre-wrap">
                                                        {message || t('whatsappNotify.messagePlaceholder').split('\n')[0]}
                                                    </div>
                                                    <div className="text-[9px] text-[#8696a0] text-left mt-1 flex items-center gap-1 justify-end">
                                                        10:30 PM
                                                        <CheckCircleSolid className="h-3 w-3 text-[#53bdeb]" />
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Send Area */}
                            <div className="mt-8 pt-5 border-t border-gray-100 dark:border-white/5">
                                {sendError && (
                                    <div className="mb-4 bg-red-500/5 dark:bg-red-500/10 border border-red-500/20 dark:border-red-500/20 rounded-2xl p-4 flex items-start gap-3 text-red-600 dark:text-red-300 text-sm animate-in fade-in slide-in-from-bottom-2 font-medium">
                                        <ExclamationCircleIcon className="h-5 w-5 flex-shrink-0" />
                                        {sendError}
                                    </div>
                                )}

                                <button
                                    onClick={handleSend}
                                    disabled={sending || !message.trim() || !connectedSession || audienceCount === 0}
                                    className={`w-full py-5 rounded-2xl font-black text-base flex items-center justify-center gap-3 transition-all duration-500 group relative overflow-hidden ${sending || !message.trim() || !connectedSession || audienceCount === 0
                                        ? 'bg-gray-100 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border border-gray-200 dark:border-white/5'
                                        : 'bg-violet-600 hover:bg-violet-500 text-white shadow-[0_20px_40px_-15px_rgba(124,58,237,0.4)] dark:shadow-[0_20px_40px_-15px_rgba(124,58,237,0.5)] hover:scale-[1.01] active:scale-[0.98]'
                                        }`}
                                >
                                    {sending ? (
                                        <><ArrowPathIcon className="h-6 w-6 animate-spin" /> {t('common.loading')}</>
                                    ) : (
                                        <>
                                            <span className="relative z-10 flex items-center gap-3">
                                                {t('whatsappNotify.sendCampaign')} {audienceCount?.toLocaleString() ?? '...'} {t('whatsappNotify.customer')}
                                                <PaperAirplaneIcon className="h-5 w-5 -rotate-45 group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
                                            </span>
                                            <div className="absolute inset-0 bg-gradient-to-r from-violet-600 via-fuchsia-500 to-violet-600 opacity-0 group-hover:opacity-100 transition-opacity blur-2xl -z-0" />
                                        </>
                                    )}
                                </button>

                                <div className="mt-4 flex items-center gap-3 text-[10px] text-gray-500 dark:text-gray-500 bg-gray-50 dark:bg-black/20 rounded-xl p-3 border border-gray-100 dark:border-white/5 font-bold">
                                    <InformationCircleIcon className="h-4 w-4 text-violet-500 dark:text-violet-400 flex-shrink-0" />
                                    <span>{t('whatsappNotify.instructions')}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </>
            ) : (
                <>
                    <div className="lg:col-span-12 xl:col-span-5 space-y-5">
                        <div className="bg-white dark:bg-gray-900/60 backdrop-blur-xl border border-gray-200 dark:border-white/10 rounded-3xl p-5 shadow-xl dark:shadow-2xl">
                        <h2 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2 mb-4">
                            <span className="p-1.5 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400">
                                <CalendarDaysIcon className="h-4 w-4" />
                            </span>
                            {t('whatsappNotify.birthdayTitle')}
                        </h2>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className="text-[11px] text-gray-500 dark:text-gray-400 mb-2 block font-bold">{t('whatsappNotify.birthdayDateLabel')}</label>
                                <input
                                    type="date"
                                    value={birthdayDate}
                                    onChange={e => setBirthdayDate(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl px-3 py-2.5 text-sm text-gray-900 dark:text-white outline-none focus:ring-2 focus:ring-amber-400/30"
                                />
                            </div>
                            <div className="bg-amber-500/5 border border-amber-500/20 rounded-2xl p-4 flex items-center justify-between">
                                <div>
                                    <div className="text-[10px] text-amber-700 dark:text-amber-300 font-bold uppercase">{t('whatsappNotify.willSendTo')}</div>
                                    <div className="text-[11px] text-gray-500 dark:text-gray-300 mt-1">{t('whatsappNotify.birthdaySubtitle')}</div>
                                </div>
                                {birthdayAudienceLoading ? (
                                    <div className="h-7 w-16 bg-gray-200 dark:bg-white/10 rounded-lg animate-pulse" />
                                ) : (
                                    <div className="text-right">
                                        <span className="text-2xl font-black text-amber-600 dark:text-amber-400">{birthdayAudienceCount?.toLocaleString() ?? 0}</span>
                                        <span className="text-[10px] text-gray-400 dark:text-gray-500 block font-bold">{t('whatsappNotify.customer')}</span>
                                    </div>
                                )}
                            </div>
                        </div>

                        <p className="mb-4 text-[11px] text-gray-500 dark:text-gray-400">
                            {t('whatsappNotify.birthdayDataNote')}
                        </p>

                        {campaign && (
                            <div className="mb-4 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-2xl p-4">
                                <div className="flex items-center justify-between text-sm mb-2">
                                    <div className="flex items-center gap-2">
                                        <span className="font-bold text-gray-700 dark:text-gray-200">
                                            {campaign.status === 'running' ? t('whatsappNotify.sending') : campaign.status === 'completed' ? t('whatsappNotify.completed') : t('whatsappNotify.paused')}
                                        </span>
                                        {campaign.status === 'running' && (
                                            <button
                                                onClick={handleStop}
                                                className="text-[10px] px-2 py-1 bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 border border-red-500/20 dark:border-red-500/30 rounded-lg transition-colors flex items-center gap-1 font-bold"
                                            >
                                                <XMarkIcon className="h-3 w-3" />
                                                {t('whatsappNotify.pause')}
                                            </button>
                                        )}
                                    </div>
                                    <span className="font-bold text-amber-600 dark:text-amber-400">{campaign.sent + campaign.failed}/{campaign.total}</span>
                                </div>

                                <div className="h-2 rounded-full bg-gray-200 dark:bg-gray-800 overflow-hidden">
                                    <div
                                        className="h-full bg-gradient-to-r from-amber-500 to-orange-500 transition-all"
                                        style={{ width: `${campaign.total > 0 ? ((campaign.sent + campaign.failed) / campaign.total) * 100 : 0}%` }}
                                    />
                                </div>

                                {/* Error Logs */}
                                {campaign.errors && campaign.errors.length > 0 && (
                                    <div className="mt-4 pt-4 border-t border-gray-200 dark:border-white/5">
                                        <label className="text-[10px] text-red-500 font-black uppercase block mb-2">{t('whatsappNotify.errorLogs')} ({campaign.errors.length})</label>
                                        <div className="max-h-32 overflow-y-auto custom-scrollbar space-y-1.5">
                                            {campaign.errors.map((err, idx) => (
                                                <div key={idx} className="flex items-center justify-between text-[9px] bg-red-500/5 p-2 rounded-lg border border-red-500/10">
                                                    <span className="font-bold text-gray-700 dark:text-gray-300">{err.phone} {err.name ? `(${err.name})` : ''}</span>
                                                    <span className="text-red-500 font-medium">{err.error}</span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>

                <div className="lg:col-span-12 xl:col-span-7 space-y-5">
                    <div className="bg-white dark:bg-gray-900/60 backdrop-blur-xl border border-gray-200 dark:border-white/10 rounded-3xl p-5 shadow-xl dark:shadow-2xl">
                        <h2 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2 mb-4">
                            <span className="p-1.5 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400">
                                <SparklesIcon className="h-4 w-4" />
                            </span>
                            أرشيف ونماذج الرسائل
                        </h2>
                        <div className="flex flex-wrap gap-2 mb-6">
                            {getBirthdayTemplates().map((t_temp, i) => (
                                <button
                                    key={i}
                                    onClick={() => setBirthdayMessage(t_temp.text)}
                                    className="text-[10px] px-3 py-1.5 rounded-full bg-gray-50 dark:bg-white/5 hover:bg-gray-100 dark:hover:bg-white/10 border border-gray-200 dark:border-white/10 text-gray-600 dark:text-gray-300 transition-all font-bold"
                                >
                                    {t_temp.label}
                                </button>
                            ))}
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            <div className="space-y-4">
                                <div>
                                <label className="text-[11px] text-gray-500 dark:text-gray-400 mb-2 block font-bold">{t('whatsappNotify.birthdayMessageLabel')}</label>
                                <textarea
                                    value={birthdayMessage}
                                    onChange={e => setBirthdayMessage(e.target.value)}
                                    rows={7}
                                    placeholder={t('whatsappNotify.messagePlaceholder')}
                                    className="w-full bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-2xl px-4 py-3 text-sm text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-600 resize-none outline-none focus:ring-2 focus:ring-amber-400/30"
                                />

                                <p className="mt-2 text-[11px] text-gray-500 dark:text-gray-400">
                                    {t('whatsappNotify.availableVariables')} <span className="font-mono">{t('whatsappNotify.customerNameVar')}</span> {t('common.and')} <span className="font-mono">{t('whatsappNotify.ageVar')}</span>
                                </p>
                            </div>

                            <div>
                                <label className="text-[11px] text-gray-500 dark:text-gray-400 mb-2 block font-bold">{t('whatsappNotify.imageUrl')}</label>
                                <input
                                    value={birthdayMediaUrl}
                                    onChange={e => setBirthdayMediaUrl(e.target.value)}
                                    placeholder="https://..."
                                    className="w-full bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl px-3 py-2.5 text-sm text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-700 outline-none focus:ring-2 focus:ring-amber-400/30"
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                <div className="flex items-center gap-2 bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl px-3 py-2">
                                    <input
                                        type="number"
                                        value={delayValue}
                                        onChange={e => setDelayValue(Number(e.target.value))}
                                        min={0.5}
                                        step={0.5}
                                        className="w-12 bg-transparent text-xs text-gray-900 dark:text-white outline-none font-black"
                                    />
                                    <select
                                        value={delayUnit}
                                        onChange={e => setDelayUnit(e.target.value as any)}
                                        className="bg-transparent text-[10px] text-gray-500 dark:text-gray-400 outline-none cursor-pointer font-bold"
                                    >
                                        <option value="seconds">{t('whatsappNotify.seconds')}</option>
                                        <option value="minutes">{t('whatsappNotify.minutes')}</option>
                                    </select>
                                </div>
                                <select
                                    value={delayMode}
                                    onChange={e => setDelayMode(e.target.value as any)}
                                    className="bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 rounded-xl px-3 py-2 text-[10px] text-gray-600 dark:text-gray-300 outline-none cursor-pointer font-bold"
                                >
                                    <option value="perMessage">{t('whatsappNotify.perMessage')}</option>
                                    <option value="perSession">{t('whatsappNotify.perSession')}</option>
                                </select>
                            </div>
                        </div>

                        {/* Live Preview (WhatsApp Bubble) */}
                        <div className="hidden md:block">
                            <label className="text-[10px] text-gray-500 dark:text-gray-500 font-black uppercase mb-2 block">{t('whatsappNotify.livePreview')}</label>
                            <div className="bg-[#0b141a] rounded-3xl overflow-hidden border border-gray-200 dark:border-white/5 h-[340px] relative shadow-2xl">
                                <div className="bg-[#202c33] px-3 py-2 flex items-center gap-2">
                                    <div className="h-8 w-8 rounded-full bg-gray-600" />
                                    <div>
                                        <div className="text-[11px] font-bold text-[#e9edef]">{t('whatsappNotify.customerName')}</div>
                                        <div className="text-[9px] text-[#8696a0]">{t('whatsappNotify.onlineNow')}</div>
                                    </div>
                                </div>
                                <div className="absolute inset-x-0 top-12 bottom-0 bg-[#0b141a] opacity-50" style={{ backgroundImage: 'url("https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png")', backgroundSize: 'contain' }} />

                                <div className="relative p-4 flex flex-col items-start overflow-y-auto h-full custom-scrollbar">
                                    <div className="max-w-[90%] bg-[#005c4b] rounded-2xl rounded-tr-none p-1.5 shadow-md self-end mb-2 animate-in fade-in slide-in-from-right-2">
                                        {birthdayMediaUrl && (
                                            <img src={birthdayMediaUrl} alt="" className="w-full rounded-xl mb-1.5 object-cover max-h-40 shadow-sm" onError={e => e.currentTarget.style.display = 'none'} />
                                        )}
                                        <div className="px-2 pb-1">
                                            <div className="text-[12px] text-[#e9edef] leading-relaxed whitespace-pre-wrap">
                                                {birthdayMessage || t('whatsappNotify.messagePlaceholder').split('\n')[0]}
                                            </div>
                                            <div className="text-[9px] text-[#8696a0] text-left mt-1 flex items-center gap-1 justify-end">
                                                10:30 PM
                                                <CheckCircleSolid className="h-3 w-3 text-[#53bdeb]" />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-8 pt-5 border-t border-gray-100 dark:border-white/5">
                        {sendError && (
                                <div className="bg-red-500/5 dark:bg-red-500/10 border border-red-500/20 rounded-2xl p-3 text-red-600 dark:text-red-300 text-sm">
                                    {sendError}
                                </div>
                            )}

                            <button
                                onClick={handleSendBirthday}
                                disabled={sending || !birthdayMessage.trim() || !connectedSession || birthdayAudienceCount === 0}
                                className={`w-full py-4 rounded-2xl font-black text-base flex items-center justify-center gap-2 transition-all ${sending || !birthdayMessage.trim() || !connectedSession || birthdayAudienceCount === 0
                                    ? 'bg-gray-100 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border border-gray-200 dark:border-white/5'
                                    : 'bg-amber-500 hover:bg-amber-400 text-white shadow-[0_20px_40px_-15px_rgba(245,158,11,0.45)]'
                                    }`}
                            >
                                {sending
                                    ? <><ArrowPathIcon className="h-5 w-5 animate-spin" /> {t('common.loading')}</>
                                    : <>{t('whatsappNotify.sendCampaign')} {birthdayAudienceCount?.toLocaleString() ?? 0} {t('whatsappNotify.customer')} <PaperAirplaneIcon className="h-4 w-4 -rotate-45" /></>
                                }
                            </button>
                        </div>
                    </div>
                </div>
                </>
            )}
            </div>

            {/* Global Styles */}
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { 
                    background: rgba(0,0,0,0.1); 
                    border-radius: 10px; 
                }
                .dark .custom-scrollbar::-webkit-scrollbar-thumb {
                    background: rgba(255,255,255,0.1);
                }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(0,0,0,0.2); }
                .dark .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }
                @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
                .animate-shimmer { animation: shimmer 2.5s infinite linear; }
            `}</style>
        </div >
    );
};

export default CustomerWhatsAppNotify;

import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  PlusIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  ArrowDownTrayIcon,
  ArrowUpTrayIcon,
  EyeIcon,
  PencilIcon,
  TrashIcon,
  UserGroupIcon,
} from "@heroicons/react/24/outline";
import {
  customerService,
  Customer,
  CustomerFilters,
} from "../../services/customerService";
import LoadingSpinner from "../../components/LoadingSpinner";
import { useDateFormat } from "../../hooks/useDateFormat";
import CustomerImportModal from "./CustomerImportModal";
import { useAuth } from "../../hooks/useAuthSimple";

const LeadsList: React.FC = () => {
  const { t } = useTranslation();
  const { formatDate } = useDateFormat();
  const { user } = useAuth();
  const isAdmin = ["OWNER", "COMPANY_ADMIN", "SUPER_ADMIN", "MANAGER"].includes(
    user?.role || "",
  );
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [filters, setFilters] = useState<CustomerFilters>({
    page: 1,
    limit: 10,
    sortBy: "updatedAt",
    sortOrder: "desc",
    status: "LEAD", // Default to LEAD
    hasOrders: false,
  });
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0,
    totalPages: 0,
    hasNext: false,
    hasPrev: false,
  });

  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkDeleting, setIsBulkDeleting] = useState(false);

  const statusOptions = customerService.getStatusOptions();

  // Selection handlers
  const toggleSelectAll = () => {
    if (selectedIds.size === customers.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(customers.map((c) => c.id)));
    }
  };

  const toggleSelect = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleBulkDelete = async () => {
    if (selectedIds.size === 0) return;
    if (!confirm(`هل أنت متأكد من حذف ${selectedIds.size} عميل محتمل؟`)) return;

    setIsBulkDeleting(true);
    try {
      await Promise.all(
        Array.from(selectedIds).map((id) => customerService.deleteCustomer(id)),
      );
      setSelectedIds(new Set());
      loadCustomers();
    } catch (err: any) {
      setError(err.message || "فشل في حذف العملاء");
    } finally {
      setIsBulkDeleting(false);
    }
  };

  const loadCustomers = async () => {
    try {
      setIsLoading(true);
      const response = await customerService.getCustomers(filters);
      setCustomers(response.data);
      setPagination(response.pagination);
    } catch (err: any) {
      setError(err.message || t("customers.loadingError"));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadCustomers();
  }, [filters]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setFilters((prev) => ({
      ...prev,
      search: searchQuery,
      page: 1,
    }));
  };

  const handlePageChange = (page: number) => {
    setFilters((prev) => ({ ...prev, page }));
  };

  const handleExport = async (format: "csv" | "json") => {
    try {
      await customerService.exportCustomers(format, filters);
    } catch (err: any) {
      setError(err.message || t("customers.exportError"));
    }
  };

  const getStatusBadge = (status: string) => {
    const statusOption = statusOptions.find(
      (option) => option.value === status,
    );
    if (!statusOption) return null;

    const colorClasses = {
      yellow: "bg-yellow-100 text-yellow-800",
      green: "bg-green-100 text-green-800",
      gray: "bg-gray-100 text-gray-800",
      purple: "bg-purple-100 text-purple-800",
      red: "bg-red-100 text-red-800",
    };

    return (
      <span
        className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${colorClasses[statusOption.color as keyof typeof colorClasses]}`}
      >
        {statusOption.label}
      </span>
    );
  };

  const getRatingBadge = (rating: string | undefined) => {
    if (!rating) return null;
    switch (rating) {
      case "EXCELLENT":
        return (
          <span className="ml-2 text-xs bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full ring-1 ring-purple-600/20">
            💎 Excellent
          </span>
        );
      case "GOOD":
        return (
          <span className="ml-2 text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full ring-1 ring-blue-600/20">
            ✅ Good
          </span>
        );
      case "AVERAGE":
        return (
          <span className="ml-2 text-xs bg-gray-100 text-gray-700 px-2 py-0.5 rounded-full ring-1 ring-gray-600/20">
            Average
          </span>
        );
      case "BAD":
        return (
          <span className="ml-2 text-xs bg-red-100 text-red-700 px-2 py-0.5 rounded-full ring-1 ring-red-600/20">
            ⛔ Bad
          </span>
        );
      default:
        return null;
    }
  };

  if (isLoading && customers.length === 0) {
    return (
      <div className="flex items-center justify-center h-64">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  return (
    <>
      <div className="space-y-6" dir="rtl">
        {/* Header */}
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
              العملاء المحتملين (Leads)
            </h1>
            <p className="text-gray-600 dark:text-gray-400">
              إدارة ومتابعة العملاء الذين لم يكملوا عمليات الشراء بعد
            </p>
          </div>
          {isAdmin && (
            <div className="flex space-x-3 space-x-reverse">
              <button
                onClick={() => setIsImportModalOpen(true)}
                className="inline-flex items-center px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
              >
                <ArrowUpTrayIcon className="h-4 w-4 ml-2" />
                استيراد
              </button>
              <button
                onClick={() => handleExport("csv")}
                className="inline-flex items-center px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
              >
                <ArrowDownTrayIcon className="h-4 w-4 ml-2" />
                تصدير CSV
              </button>
              <Link
                to="/customers/new"
                className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600"
              >
                <PlusIcon className="h-4 w-4 ml-2" />
                إضافة عميل محتمل
              </Link>
            </div>
          )}
        </div>

        {/* Filters */}
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow dark:shadow-md">
          <div className="flex flex-col sm:flex-row gap-4">
            {/* Search */}
            <form onSubmit={handleSearch} className="flex-1">
              <div className="relative">
                <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400 dark:text-gray-500" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="البحث بالاسم، الهاتف أو البريد..."
                  className="block w-full pr-10 pl-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md leading-5 bg-white dark:bg-gray-700 placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 dark:text-gray-100"
                />
              </div>
            </form>

            <div className="flex items-center text-sm text-gray-500 bg-indigo-50 dark:bg-indigo-900/20 px-4 py-2 rounded-md border border-indigo-100 dark:border-indigo-800">
              <UserGroupIcon className="h-5 w-5 ml-2 text-indigo-500" />
              عرض العملاء بحالة:{" "}
              <span className="mr-1 font-bold text-indigo-700 dark:text-indigo-400">
                عميل محتمل (LEAD)
              </span>
            </div>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-700 text-red-700 dark:text-red-300 px-4 py-3 rounded-md">
            {error}
          </div>
        )}

        {/* Leads Table */}
        <div className="bg-white dark:bg-gray-800 shadow dark:shadow-md overflow-hidden sm:rounded-md">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-50 dark:bg-gray-900">
                <tr>
                  <th className="px-4 py-3 text-center">
                    <input
                      type="checkbox"
                      checked={
                        selectedIds.size === customers.length &&
                        customers.length > 0
                      }
                      onChange={toggleSelectAll}
                      className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                    />
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    العميل المحتمل
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    معلومات التواصل
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    الحالة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    الإحصائيات
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    آخر نشاط
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    إجراءات
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                {customers.map((customer) => (
                  <tr
                    key={customer.id}
                    className={`hover:bg-gray-50 dark:hover:bg-gray-700 ${selectedIds.has(customer.id) ? "bg-indigo-50 dark:bg-indigo-900/10" : ""}`}
                  >
                    <td className="px-4 py-4 text-center">
                      <input
                        type="checkbox"
                        checked={selectedIds.has(customer.id)}
                        onChange={() => toggleSelect(customer.id)}
                        className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                      />
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div className="flex-shrink-0 h-10 w-10">
                          <div className="h-10 w-10 rounded-full bg-indigo-100 dark:bg-indigo-900/20 flex items-center justify-center">
                            <span className="text-sm font-medium text-indigo-700 dark:text-indigo-400">
                              {customer.firstName &&
                                customer.firstName.charAt(0)}
                              {customer.lastName && customer.lastName.charAt(0)}
                            </span>
                          </div>
                        </div>
                        <div className="mr-4">
                          <div className="text-sm font-medium text-gray-900 dark:text-gray-100 flex items-center">
                            {customer.firstName || ""} {customer.lastName || ""}
                            {getRatingBadge(customer.customerRating)}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-gray-900 dark:text-gray-100">
                        {customer.email}
                      </div>
                      <div className="text-sm text-gray-500 dark:text-gray-400">
                        {customer.phone}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getStatusBadge(customer.status)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                      <div>
                        المحادثات: {customer._count?.conversations || 0}
                      </div>
                      <div>الطلبات: {customer._count?.orders || 0}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                      {formatDate(customer.updatedAt)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <div className="flex space-x-2 space-x-reverse">
                        <Link
                          to={`/customers/${customer.id}`}
                          className="text-indigo-600 dark:text-indigo-400 hover:text-indigo-900 dark:hover:text-indigo-300"
                        >
                          <EyeIcon className="h-4 w-4" />
                        </Link>
                        <Link
                          to={`/customers/${customer.id}/edit`}
                          className="text-green-600 dark:text-green-400 hover:text-green-900 dark:hover:text-green-300"
                        >
                          <PencilIcon className="h-4 w-4" />
                        </Link>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {pagination && pagination.total > 0 && (
            <div className="bg-white dark:bg-gray-800 px-4 py-3 flex items-center justify-between border-t border-gray-200 dark:border-gray-700 sm:px-6">
              <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
                <div>
                  <p className="text-sm text-gray-700 dark:text-gray-300">
                    عرض{" "}
                    <span className="font-medium">
                      {(pagination.page - 1) * pagination.limit + 1}
                    </span>{" "}
                    إلى{" "}
                    <span className="font-medium">
                      {Math.min(
                        pagination.page * pagination.limit,
                        pagination.total,
                      )}
                    </span>{" "}
                    من أصل{" "}
                    <span className="font-medium">{pagination.total}</span>{" "}
                    نتيجة
                  </p>
                </div>
                <div>
                  <nav
                    className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px"
                    aria-label="Pagination"
                  >
                    <button
                      onClick={() => handlePageChange(pagination.page - 1)}
                      disabled={!pagination.hasPrev}
                      className="relative inline-flex items-center px-2 py-2 rounded-r-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm font-medium text-gray-500 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-600 disabled:opacity-50"
                    >
                      السابق
                    </button>
                    <button
                      onClick={() => handlePageChange(pagination.page + 1)}
                      disabled={!pagination.hasNext}
                      className="relative inline-flex items-center px-2 py-2 rounded-l-md border border-gray-300 bg-white text-sm font-medium text-gray-500 hover:bg-gray-50 disabled:opacity-50"
                    >
                      التالي
                    </button>
                  </nav>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Empty State */}
        {!isLoading && customers.length === 0 && (
          <div className="text-center py-12">
            <UserGroupIcon className="mx-auto h-12 w-12 text-gray-400" />
            <h3 className="mt-2 text-sm font-medium text-gray-900">
              لا يوجد عملاء محتملين
            </h3>
            <p className="mt-1 text-sm text-gray-500">
              ابدأ بإضافة أول عميل محتمل لمتابعته
            </p>
          </div>
        )}
      </div>

      <CustomerImportModal
        isOpen={isImportModalOpen}
        onClose={() => setIsImportModalOpen(false)}
        onSuccess={() => {
          setIsImportModalOpen(false);
          loadCustomers();
        }}
      />
    </>
  );
};

export default LeadsList;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import {
  TrendingUp,
  Star,
  Target,
  Award,
  DollarSign,
  Gift,
  RefreshCw,
  Users,
} from "lucide-react";

interface CustomerLoyaltyProgram {
  id: string;
  name: string;
  nameAr?: string;
  type: string;
  customersCount: number;
  totalPointsIssued: number;
  totalPointsRedeemed: number;
}

const LoyaltyAnalytics: React.FC = () => {
  const [stats, setStats] = useState<{ totalCashback: number } | null>(null);
  const [programs, setPrograms] = useState<CustomerLoyaltyProgram[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setIsLoading(true);
      const [programsRes, statsRes] = await Promise.all([
        apiClient.get("/hr/customer-loyalty/programs"),
        apiClient.get("/wallet/stats"),
      ]);

      setPrograms(programsRes.data.data || []);
      setStats(statsRes.data.data || null);
    } catch (error) {
      console.error("Error fetching analytics:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const IconWrapper = ({
    color,
    children,
  }: {
    color: string;
    children: React.ReactNode;
  }) => <div className={`p-3 rounded-lg ${color}`}>{children}</div>;

  const getProgramIcon = (type: string) => {
    switch (type) {
      case "POINTS":
        return <Star className="w-5 h-5" />;
      case "TIER":
        return <Award className="w-5 h-5" />;
      case "CASHBACK":
        return <DollarSign className="w-5 h-5" />;
      case "REFERRAL":
        return <Users className="w-5 h-5" />;
      default:
        return <Gift className="w-5 h-5" />;
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  const totalIssued = programs.reduce((sum, p) => sum + Number(p.totalPointsIssued || 0), 0);
  const totalRedeemed = programs.reduce((sum, p) => sum + Number(p.totalPointsRedeemed || 0), 0);
  const totalCustomers = programs.reduce((sum, p) => sum + Number(p.customersCount || 0), 0);

  const avgPoints = totalCustomers > 0 ? Math.round((totalIssued - totalRedeemed) / totalCustomers) : 0;
  const redemptionRate = totalIssued > 0 ? Math.round((totalRedeemed / totalIssued) * 100) : 0;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            تحليلات الولاء
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            متابعة أداء برامج الولاء والنقاط والكاش باك
          </p>
        </div>
        <button
          onClick={fetchData}
          className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700"
        >
          <RefreshCw className="w-4 h-4" />
          تحديث
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <IconWrapper color="bg-green-100 text-green-600 dark:bg-green-900/30">
              <Users className="w-6 h-6" />
            </IconWrapper>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">
            العملاء المشتركين
          </p>
          <p className="text-3xl font-bold text-gray-900 dark:text-white">
            {totalCustomers.toLocaleString()}
          </p>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <IconWrapper color="bg-yellow-100 text-yellow-600 dark:bg-yellow-900/30">
              <Star className="w-6 h-6" />
            </IconWrapper>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">
            متوسط النقاط للعميل
          </p>
          <p className="text-3xl font-bold text-gray-900 dark:text-white">
            {avgPoints.toLocaleString()}
          </p>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <IconWrapper color="bg-blue-100 text-blue-600 dark:bg-blue-900/30">
              <Target className="w-6 h-6" />
            </IconWrapper>
            <span className="text-xs font-medium text-blue-600 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded">
              {redemptionRate}%
            </span>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">
            نسبة الاستبدال
          </p>
          <p className="text-3xl font-bold text-gray-900 dark:text-white">
            {redemptionRate}%
          </p>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <IconWrapper color="bg-pink-100 text-pink-600 dark:bg-pink-900/30">
              <DollarSign className="w-6 h-6" />
            </IconWrapper>
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">
            إجمالي الكاش باك
          </p>
          <p className="text-2xl font-bold text-gray-900 dark:text-white dir-rtl">
            {stats?.totalCashback ? stats.totalCashback.toLocaleString() : "0"}{" "}
            ج.م
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Program Performance */}
        <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-6">
            أداء البرامج التفصيلي
          </h3>
          <div className="space-y-4">
            {programs.map((program) => (
              <div
                key={program.id}
                className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
              >
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-white dark:bg-gray-800 rounded-md shadow-sm text-purple-600 dark:text-purple-400">
                    {getProgramIcon(program.type)}
                  </div>
                  <div>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {program.nameAr || program.name}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      {program.customersCount} عميل مشترك
                    </p>
                  </div>
                </div>
                <div className="text-left rtl:text-right">
                  <p className="font-bold text-gray-900 dark:text-white">
                    {program.totalPointsIssued.toLocaleString()}{" "}
                    <span className="text-xs font-normal text-gray-500">
                      نقطة
                    </span>
                  </p>
                  <div className="w-full bg-gray-200 dark:bg-gray-600 rounded-full h-1.5 mt-2 w-24">
                    <div
                      className="bg-purple-600 h-1.5 rounded-full"
                      style={{
                        width: `${Math.min(100, (program.totalPointsRedeemed / (program.totalPointsIssued || 1)) * 100)}%`,
                      }}
                    ></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Insight Card */}
        <div className="bg-gradient-to-br from-purple-900 to-indigo-900 rounded-xl p-8 text-white flex flex-col justify-center relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-5 rounded-full -mr-16 -mt-16 pointer-events-none"></div>
          <div className="absolute bottom-0 left-0 w-32 h-32 bg-white opacity-5 rounded-full -ml-8 -mb-8 pointer-events-none"></div>

          <Award className="w-12 h-12 text-yellow-400 mb-6" />
          <h3 className="text-2xl font-bold mb-2">رؤى وتوصيات</h3>
          <p className="text-purple-100 mb-6 leading-relaxed">
            معدل استبدال النقاط لديك {redemptionRate >= 50 ? 'جيد جداً' : 'يحتاج للتحسين'} ({redemptionRate}%)، {redemptionRate >= 50 ? 'مما يدل على اهتمام العملاء بالمكافآت' : 'نقترح مراجعة مكافآت برامج الولاء لزيادة التفاعل'}. 
            نقترح أيضاً إنشاء مستوى "بلاتيني" جديد للعملاء الذين تجاوزوا 5000 نقطة لزيادة ولائهم.
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoyaltyAnalytics;

import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import {
  Users,
  Search,
  Filter,
  Star,
  Crown,
  Medal,
  Gem,
  Trophy,
  Award,
  Eye,
  Edit,
  RefreshCw,
  Gift,
  DollarSign,
  Plus,
} from "lucide-react";
import { customerService, Customer } from "../../services/customerService";

interface CustomerLoyaltyProgram {
  id: string;
  name: string;
  nameAr?: string;
  type: "POINTS" | "TIER" | "CASHBACK" | "REFERRAL";
}

interface CustomerLoyaltyTier {
  id: string;
  name: string;
  nameAr?: string;
  color: string;
  icon: string;
}

interface CustomerLoyaltyRecord {
  id: string;
  customer: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
  };
  program: CustomerLoyaltyProgram;
  currentPoints: number;
  totalEarned: number;
  totalRedeemed: number;
  tier?: CustomerLoyaltyTier;
  joinDate: string;
  lastActivity: string;
  status: "ACTIVE" | "INACTIVE" | "SUSPENDED";
}

const LoyaltyMembers: React.FC = () => {
  const [customers, setCustomers] = useState<CustomerLoyaltyRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");

  // Modal state
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState(false);
  const [selectedRecord, setSelectedRecord] =
    useState<CustomerLoyaltyRecord | null>(null);
  const [adjustmentPoints, setAdjustmentPoints] = useState<number>(0);
  const [adjustmentReason, setAdjustmentReason] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Enroll Modal state
  const [isEnrollModalOpen, setIsEnrollModalOpen] = useState(false);
  const [availablePrograms, setAvailablePrograms] = useState<CustomerLoyaltyProgram[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState("");
  const [selectedProgramId, setSelectedProgramId] = useState("");
  const [initialPoints, setInitialPoints] = useState<number>(0);
  const [customerSearch, setCustomerSearch] = useState("");
  const [searchResults, setSearchResults] = useState<Customer[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isEnrolling, setIsEnrolling] = useState(false);

  useEffect(() => {
    fetchCustomers();
    fetchPrograms();
  }, []);

  const fetchPrograms = async () => {
    try {
      const res = await apiClient.get("/hr/customer-loyalty/programs");
      // filter only active points/tier programs
      const activePrograms = (res.data.data || []).filter((p: any) => p.status === 'ACTIVE' && (p.type === 'POINTS' || p.type === 'TIER'));
      setAvailablePrograms(activePrograms);
    } catch (error) {
      console.error("Error fetching programs:", error);
    }
  };

  const fetchCustomers = async () => {
    try {
      setIsLoading(true);
      const res = await apiClient.get("/hr/customer-loyalty/customers");
      setCustomers(res.data.data || []);
    } catch (error) {
      console.error("Error fetching customers:", error);
    } finally {
      setIsLoading(false);
    }
  };

  // Search customers for enrollment
  useEffect(() => {
    const searchTimer = setTimeout(async () => {
      if (customerSearch.trim().length >= 2) {
        setIsSearching(true);
        try {
          // You could use searchCustomers if supported, or getCustomers with search filter
          const res = await customerService.getCustomers({ search: customerSearch, limit: 10 });
          setSearchResults(res.data || []);
        } catch (error) {
          console.error("Error searching customers:", error);
        } finally {
          setIsSearching(false);
        }
      } else {
        setSearchResults([]);
      }
    }, 500);

    return () => clearTimeout(searchTimer);
  }, [customerSearch]);

  const handleEnrollCustomer = async () => {
    if (!selectedCustomerId || !selectedProgramId) return;

    try {
      setIsEnrolling(true);
      await apiClient.post("/hr/customer-loyalty/enroll", {
        customerId: selectedCustomerId,
        programId: selectedProgramId,
        initialPoints: initialPoints || 0
      });

      // Cleanup & Refresh
      setIsEnrollModalOpen(false);
      setSelectedCustomerId("");
      setSelectedProgramId("");
      setInitialPoints(0);
      setCustomerSearch("");
      setSearchResults([]);
      fetchCustomers();
    } catch (error: any) {
      console.error("Error enrolling customer:", error);
      alert(error?.response?.data?.error || "فشل تسجيل العميل. يرجى المحاولة مرة أخرى.");
    } finally {
      setIsEnrolling(false);
    }
  };

  const handleAdjustPoints = async () => {
    if (!selectedRecord || adjustmentPoints === 0) return;

    try {
      setIsSubmitting(true);
      await apiClient.post("/hr/customer-loyalty/adjust-points", {
        customerId: selectedRecord.customer.id,
        programId: selectedRecord.program.id,
        points: adjustmentPoints,
        reason: adjustmentReason,
      });

      // Success
      setIsAdjustModalOpen(false);
      setAdjustmentPoints(0);
      setAdjustmentReason("");
      fetchCustomers(); // Refresh list
    } catch (error: any) {
      console.error("Error adjusting points:", error);
      alert(error?.response?.data?.error || "فشل تعديل النقاط. يرجى المحاولة مرة أخرى.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const getProgramIcon = (type: string) => {
    switch (type) {
      case "POINTS":
        return <Star className="w-4 h-4" />;
      case "TIER":
        return <Crown className="w-4 h-4" />;
      case "CASHBACK":
        return <DollarSign className="w-4 h-4" />;
      case "REFERRAL":
        return <Users className="w-4 h-4" />;
      default:
        return <Gift className="w-4 h-4" />;
    }
  };

  const getTierIcon = (iconName: string) => {
    switch (iconName) {
      case "crown":
        return <Crown className="w-4 h-4" />;
      case "medal":
        return <Medal className="w-4 h-4" />;
      case "gem":
        return <Gem className="w-4 h-4" />;
      case "trophy":
        return <Trophy className="w-4 h-4" />;
      default:
        return <Award className="w-4 h-4" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "ACTIVE":
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400";
      case "INACTIVE":
        return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400";
      case "SUSPENDED":
        return "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  // Filter customers based on search
  const safeSearch = searchQuery.toLowerCase();
  const filteredCustomers = customers.filter(
    (c) =>
      c.customer?.firstName?.toLowerCase()?.includes(safeSearch) ||
      c.customer?.lastName?.toLowerCase()?.includes(safeSearch) ||
      c.customer?.email?.toLowerCase()?.includes(safeSearch) ||
      c.customer?.phone?.includes(safeSearch),
  );

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            أعضاء الولاء
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            قائمة العملاء المشتركين في برامج النقاط والمكافآت
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setIsEnrollModalOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition-colors shadow-sm"
          >
            <Plus className="w-4 h-4" />
            إضافة عضو
          </button>
          <button
            onClick={fetchCustomers}
            className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            <RefreshCw className="w-4 h-4" />
            تحديث
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="flex-1 relative">
          <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="البحث باسم العميل، البريد، أو الهاتف..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pr-10 pl-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 text-right"
          />
        </div>
        <button className="flex items-center gap-2 px-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 bg-white dark:bg-gray-800 shadow-sm">
          <Filter className="w-4 h-4" />
          فلترة متقدمة
        </button>
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden shadow-sm">
        {filteredCustomers.length === 0 ? (
          <div className="text-center py-12">
            <Users className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
              لا يوجد عملاء
            </h3>
            <p className="text-gray-500 dark:text-gray-400">
              لا توجد نتائج تطابق بحثك
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-50 dark:bg-gray-800/50">
                <tr>
                  <th className="px-6 py-4 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    العميل
                  </th>
                  <th className="px-6 py-4 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    البرنامج
                  </th>
                  <th className="px-6 py-4 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    النقاط
                  </th>
                  <th className="px-6 py-4 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    المستوى
                  </th>
                  <th className="px-6 py-4 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    الحالة
                  </th>
                  <th className="px-6 py-4 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    آخر نشاط
                  </th>
                  <th className="px-6 py-4 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    إجراءات
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                {filteredCustomers.map((record) => (
                  <tr
                    key={record.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                  >
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <div>
                        <div className="font-medium text-gray-900 dark:text-white">
                          {record.customer.firstName} {record.customer.lastName}
                        </div>
                        <div className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                          {record.customer.email}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <div className="flex items-center gap-2 justify-end">
                        <span className="text-sm text-gray-700 dark:text-gray-300">
                          {record.program.nameAr || record.program.name}
                        </span>
                        <span className="p-1 rounded bg-gray-100 dark:bg-gray-700">
                          {getProgramIcon(record.program.type)}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <div className="flex items-center gap-1.5 justify-end">
                        <span className="font-bold text-gray-900 dark:text-white">
                          {record.currentPoints.toLocaleString()}
                        </span>
                        <Star className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      {record.tier ? (
                        <div className="flex items-center gap-2 justify-end">
                          <span className="text-sm font-medium text-gray-900 dark:text-white">
                            {record.tier.nameAr || record.tier.name}
                          </span>
                          <span style={{ color: record.tier.color }}>
                            {getTierIcon(record.tier.icon)}
                          </span>
                        </div>
                      ) : (
                        <span className="text-sm text-gray-400">-</span>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <span
                        className={`text-xs px-2.5 py-1 rounded-full font-medium ${getStatusColor(record.status)}`}
                      >
                        {record.status === "ACTIVE"
                          ? "نشط"
                          : record.status === "INACTIVE"
                            ? "غير نشط"
                            : "معلق"}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm text-gray-500 dark:text-gray-400">
                      {new Date(record.lastActivity).toLocaleDateString(
                        "ar-EG",
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm">
                      <div className="flex gap-3 justify-end">
                        <Link
                          to={`/customers/${record.customer.id}`}
                          className="text-gray-400 hover:text-purple-600 transition-colors"
                          title="عرض التفاصيل"
                        >
                          <Eye className="w-4 h-4" />
                        </Link>
                        <button
                          onClick={() => {
                            setSelectedRecord(record);
                            setIsAdjustModalOpen(true);
                          }}
                          className="text-gray-400 hover:text-blue-600 transition-colors"
                          title="تعديل الرصيد"
                        >
                          <Edit className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Adjustment Modal */}
      {isAdjustModalOpen && selectedRecord && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md border border-gray-200 dark:border-gray-700 overflow-hidden">
            <div className="p-6 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white text-right">
                تعديل نقاط العميل
              </h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 text-right mt-1">
                العميل: <span className="font-semibold text-gray-700 dark:text-gray-300">{selectedRecord.customer.firstName} {selectedRecord.customer.lastName}</span>
              </p>
              <p className="text-sm text-gray-500 dark:text-gray-400 text-right mt-1">
                البرنامج: <span className="font-semibold text-gray-700 dark:text-gray-300">{selectedRecord.program.nameAr || selectedRecord.program.name}</span>
              </p>
              <div className="mt-4 flex items-center justify-between p-3 bg-white dark:bg-gray-900 rounded-lg border border-gray-200 dark:border-gray-700">
                <span className="text-sm font-medium text-gray-600 dark:text-gray-400">الرصيد الحالي:</span>
                <div className="flex items-center gap-1.5">
                  <span className="text-lg font-bold text-gray-900 dark:text-white">
                    {selectedRecord.currentPoints.toLocaleString()}
                  </span>
                  <Star className="w-5 h-5 text-yellow-500 fill-yellow-500" />
                </div>
              </div>
            </div>

            <div className="p-6 space-y-5">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 text-right mb-2">
                  مقدار النقاط للتعديل
                </label>
                <div className="flex items-center gap-3">
                  <button
                    onClick={() => setAdjustmentPoints(prev => Math.abs(prev) * -1)}
                    className={`flex-1 flex justify-center items-center py-2.5 rounded-lg border transition-all ${adjustmentPoints < 0 
                      ? 'bg-red-50 border-red-500 text-red-700 dark:bg-red-900/30' 
                      : 'border-gray-300 text-gray-600 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-800'}`}
                  >
                    خصم نقاط
                  </button>
                  <button
                    onClick={() => setAdjustmentPoints(prev => Math.abs(prev))}
                    className={`flex-1 flex justify-center items-center py-2.5 rounded-lg border transition-all ${adjustmentPoints >= 0 
                      ? 'bg-green-50 border-green-500 text-green-700 dark:bg-green-900/30' 
                      : 'border-gray-300 text-gray-600 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-800'}`}
                  >
                    إضافة نقاط
                  </button>
                </div>
                
                <div className="mt-3">
                  <input
                    type="number"
                    min="0"
                    placeholder="أدخل عدد النقاط..."
                    value={Math.abs(adjustmentPoints) || ''}
                    onChange={(e) => {
                      const val = Math.abs(Number(e.target.value));
                      setAdjustmentPoints(adjustmentPoints < 0 ? -val : val);
                    }}
                    className="w-full px-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white text-right focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none font-medium"
                  />
                  {adjustmentPoints < 0 && Math.abs(adjustmentPoints) > selectedRecord.currentPoints && (
                    <p className="mt-1.5 text-xs text-red-500 text-right">
                      تنبيه: لا يمكن خصم نقاط أكثر من الرصيد الحالي للعميل!
                    </p>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 text-right mb-1">
                  سبب التعديل (إلزامي)
                </label>
                <textarea
                  value={adjustmentReason}
                  onChange={(e) => setAdjustmentReason(e.target.value)}
                  className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white text-right focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none resize-none min-h-[100px]"
                  placeholder="الرجاء كتابة سبب التعديل بوضوح..."
                />
              </div>
            </div>

            <div className="p-6 bg-gray-50 dark:bg-gray-800/50 flex justify-between items-center rounded-b-xl border-t border-gray-200 dark:border-gray-700">
              <div className="text-sm font-medium">
                 صافي الرصيد بعد العملية: 
                 <span className={`mr-2 font-bold ${(selectedRecord.currentPoints + adjustmentPoints) < 0 ? 'text-red-500' : 'text-indigo-600 dark:text-indigo-400'}`}>
                   {(selectedRecord.currentPoints + (adjustmentPoints || 0)).toLocaleString()}
                 </span>
              </div>
              <div className="flex gap-3">
                <button
                  onClick={() => {
                    setIsAdjustModalOpen(false);
                    setAdjustmentPoints(0);
                    setAdjustmentReason("");
                  }}
                  className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-lg transition-colors border border-gray-300 dark:border-gray-600"
                >
                  إلغاء
                </button>
                <button
                  onClick={handleAdjustPoints}
                  disabled={isSubmitting || adjustmentPoints === 0 || !adjustmentReason.trim() || (adjustmentPoints < 0 && Math.abs(adjustmentPoints) > selectedRecord.currentPoints)}
                  className="px-5 py-2 bg-purple-600 hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-medium rounded-lg transition-all shadow-sm"
                >
                  {isSubmitting ? "جاري الحفظ..." : "تأكيد التعديل"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
      {/* Enroll Modal */}
      {isEnrollModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md border border-gray-200 dark:border-gray-700 overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white text-right">
                إضافة عضو جديد للولاء
              </h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 text-right mt-1">
                ابحث عن العميل وسجله في أحد برامج النقاط أو المستويات النشطة
              </p>
            </div>

            <div className="p-6 space-y-5 overflow-y-auto">
              {/* Customer Search */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 text-right mb-2">
                  العميل
                </label>
                <div className="relative">
                  <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                  <input
                    type="text"
                    value={customerSearch}
                    onChange={(e) => {
                      setCustomerSearch(e.target.value);
                      setSelectedCustomerId("");
                    }}
                    placeholder="ابحث بالاسم أو الهاتف..."
                    className="w-full pr-10 pl-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 text-right"
                  />
                  {/* Search Results Dropdown */}
                  {customerSearch.trim().length >= 2 && !selectedCustomerId && (
                    <div className="absolute z-10 w-full mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-lg max-h-48 overflow-y-auto">
                      {isSearching ? (
                        <div className="p-4 text-center text-sm text-gray-500">جاري البحث...</div>
                      ) : searchResults.length > 0 ? (
                        searchResults.map((c) => (
                          <div
                            key={c.id}
                            onClick={() => {
                              setSelectedCustomerId(c.id);
                              setCustomerSearch(`${c.firstName} ${c.lastName}`);
                              setSearchResults([]);
                            }}
                            className="p-3 hover:bg-gray-50 dark:hover:bg-gray-700 cursor-pointer border-b border-gray-100 dark:border-gray-700/50 last:border-0 text-right"
                          >
                            <div className="font-medium text-gray-900 dark:text-white">{c.firstName} {c.lastName}</div>
                            <div className="text-xs text-gray-500">{c.phone || c.email}</div>
                          </div>
                        ))
                      ) : (
                        <div className="p-4 text-center text-sm text-gray-500">لا يوجد نتائج</div>
                      )}
                    </div>
                  )}
                </div>
              </div>

              {/* Program Selection */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 text-right mb-2">
                  برنامج الولاء
                </label>
                <select
                  value={selectedProgramId}
                  onChange={(e) => setSelectedProgramId(e.target.value)}
                  className="w-full px-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 text-right"
                  dir="rtl"
                >
                  <option value="">-- اختر البرنامج --</option>
                  {availablePrograms.map(p => (
                    <option key={p.id} value={p.id}>{p.nameAr || p.name}</option>
                  ))}
                </select>
              </div>

              {/* Initial Points */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 text-right mb-2">
                  رصيد افتتاحي (اختياري)
                </label>
                <div className="relative">
                  <input
                    type="number"
                    min="0"
                    placeholder="0"
                    value={initialPoints || ''}
                    onChange={(e) => setInitialPoints(Number(e.target.value))}
                    className="w-full pr-4 pl-10 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 text-right font-medium"
                  />
                  <div className="absolute left-3 top-1/2 -translate-y-1/2">
                    <Star className="w-5 h-5 text-yellow-500 fill-yellow-500 opacity-50" />
                  </div>
                </div>
              </div>
            </div>

            <div className="p-6 bg-gray-50 dark:bg-gray-800/50 flex justify-end items-center rounded-b-xl border-t border-gray-200 dark:border-gray-700 gap-3">
              <button
                onClick={() => {
                  setIsEnrollModalOpen(false);
                  setSelectedCustomerId("");
                  setSelectedProgramId("");
                  setInitialPoints(0);
                  setCustomerSearch("");
                }}
                className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-lg transition-colors border border-gray-300 dark:border-gray-600"
              >
                إلغاء
              </button>
              <button
                onClick={handleEnrollCustomer}
                disabled={isEnrolling || !selectedCustomerId || !selectedProgramId}
                className="px-5 py-2 bg-purple-600 hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-medium rounded-lg transition-all shadow-sm"
              >
                {isEnrolling ? "جاري التسجيل..." : "تأكيد التسجيل"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default LoyaltyMembers;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import {
  Gift,
  Star,
  Crown,
  DollarSign,
  Users,
  Plus,
  RefreshCw,
  Edit,
  Trash2,
  Truck,
  Tag,
  Percent,
  AlertCircle,
} from "lucide-react";

interface CustomerLoyaltyProgram {
  id: string;
  name: string;
  nameAr?: string;
  description: string;
  type: "POINTS" | "TIER" | "CASHBACK" | "REFERRAL";
  status: "ACTIVE" | "INACTIVE" | "DRAFT";
  pointsPerPurchase: number;
  pointsPerReferral: number;
  redemptionRate: number;
  minimumPoints: number;
  maxPointsPerTransaction: number;
  pointsPerAmount?: number;
  expiryMonths: number;
  rules?: string | any;
  createdAt: string;
  updatedAt: string;
  customersCount: number;
  totalPointsIssued: number;
  totalPointsRedeemed: number;
}

const DEFAULT_RULES = {
  rewards: {
    points: true,
    freeShipping: false,
    discount: false,
  },
  freeShippingThreshold: 0,
  discountPercent: 0,
};

const LoyaltyPrograms: React.FC = () => {
  const [programs, setPrograms] = useState<CustomerLoyaltyProgram[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProgram, setEditingProgram] =
    useState<Partial<CustomerLoyaltyProgram> | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    fetchPrograms();
  }, []);

  // Lock body scroll when modal is open
  useEffect(() => {
    if (isModalOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isModalOpen]);

  const fetchPrograms = async () => {
    try {
      setIsLoading(true);
      const res = await apiClient.get("/hr/customer-loyalty/programs");
      setPrograms(res.data.data || []);
    } catch (error) {
      console.error("Error fetching programs:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenModal = (program: CustomerLoyaltyProgram | null = null) => {
    if (program) {
      let parsedRules = DEFAULT_RULES;
      try {
        if (typeof program.rules === "string") {
          parsedRules = JSON.parse(program.rules);
        } else if (program.rules) {
          parsedRules = program.rules;
        }
      } catch (e) {
        console.error("Error parsing rules:", e);
      }
      setEditingProgram({ ...program, rules: parsedRules });
    } else {
      setEditingProgram({
        name: "",
        nameAr: "",
        description: "",
        type: "POINTS",
        status: "DRAFT",
        pointsPerPurchase: 1,
        pointsPerAmount: 1,
        pointsPerReferral: 10,
        redemptionRate: 100,
        minimumPoints: 100,
        maxPointsPerTransaction: 0,
        expiryMonths: 12,
        rules: DEFAULT_RULES,
      });
    }
    setIsModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProgram) return;

    try {
      setIsSaving(true);
      if (editingProgram.id) {
        await apiClient.put(
          `/hr/customer-loyalty/programs/${editingProgram.id}`,
          editingProgram,
        );
      } else {
        await apiClient.post("/hr/customer-loyalty/programs", editingProgram);
      }
      setIsModalOpen(false);
      fetchPrograms();
    } catch (error) {
      console.error("Error saving program:", error);
      alert("حدث خطأ أثناء حفظ البرنامج");
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا البرنامج؟")) return;
    try {
      await apiClient.delete(`/hr/customer-loyalty/programs/${id}`);
      fetchPrograms();
    } catch (error) {
      console.error("Error deleting program:", error);
      alert("حدث خطأ أثناء الحذف");
    }
  };

  const getProgramIcon = (type: string) => {
    switch (type) {
      case "POINTS":
        return <Star className="w-5 h-5" />;
      case "TIER":
        return <Crown className="w-5 h-5" />;
      case "CASHBACK":
        return <DollarSign className="w-5 h-5" />;
      case "REFERRAL":
        return <Users className="w-5 h-5" />;
      default:
        return <Gift className="w-5 h-5" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "ACTIVE":
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400";
      case "INACTIVE":
        return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400";
      case "DRAFT":
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            برامج النقاط
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            إدارة أنظمة النقاط والمكافآت (Loyalty Programs)
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={fetchPrograms}
            className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            <RefreshCw className="w-4 h-4" />
            تحديث
          </button>
          <button
            onClick={() => handleOpenModal()}
            className="flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-medium"
          >
            <Plus className="w-4 h-4" />
            برنامج جديد
          </button>
        </div>
      </div>

      {programs.length === 0 ? (
        <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700">
          <Gift className="w-12 h-12 text-gray-400 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
            لا توجد برامج ولاء
          </h3>
          <p className="text-gray-500 dark:text-gray-400 mb-4">
            أنشئ برنامج نقاط لتشجيع العملاء على الشراء
          </p>
          <button
            onClick={() => handleOpenModal()}
            className="px-4 py-2 bg-purple-600 text-white rounded-lg font-medium hover:bg-purple-700"
          >
            إنشاء برنامج جديد
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {programs.map((program) => (
            <div
              key={program.id}
              className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 hover:border-purple-500/50 transition-colors"
            >
              <div className="flex items-start justify-between mb-4">
                <div
                  className={`p-2 ${program.status === "ACTIVE" ? "bg-purple-100 text-purple-600 dark:bg-purple-900/30" : "bg-gray-100 text-gray-600 dark:bg-gray-800"} rounded-lg`}
                >
                  {getProgramIcon(program.type)}
                </div>
                <span
                  className={`text-xs px-2 py-1 rounded-full font-medium ${getStatusColor(program.status)}`}
                >
                  {program.status === "ACTIVE"
                    ? "نشط"
                    : program.status === "INACTIVE"
                      ? "غير نشط"
                      : "مسودة"}
                </span>
              </div>

              <h3 className="font-bold text-lg text-gray-900 dark:text-white mb-2">
                {program.nameAr || program.name}
              </h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-4 line-clamp-2">
                {program.description}
              </p>

              {/* Active Rewards Badges */}
              <div className="flex flex-wrap gap-2 mb-4">
                {(() => {
                  let rules = DEFAULT_RULES;
                  try {
                    if (typeof program.rules === "string")
                      rules = JSON.parse(program.rules);
                    else if (program.rules) rules = program.rules;
                  } catch (e) {}

                  return (
                    <>
                      {rules.rewards?.points && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-yellow-50 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-500 text-xs font-medium">
                          <Star className="w-3 h-3" /> نقاط
                        </span>
                      )}
                      {rules.rewards?.freeShipping && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-500 text-xs font-medium">
                          <Truck className="w-3 h-3" /> شحن مجاني
                        </span>
                      )}
                      {rules.rewards?.discount && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-500 text-xs font-medium">
                          <Tag className="w-3 h-3" /> خصم %
                          {rules.discountPercent}
                        </span>
                      )}
                    </>
                  );
                })()}
              </div>

              <div className="space-y-3 pt-4 border-t border-gray-100 dark:border-gray-700">
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500 dark:text-gray-400">
                    معدل اكتساب النقاط:
                  </span>
                  <span className="font-medium text-gray-900 dark:text-white">
                    {program.pointsPerPurchase} نقطة / {program.pointsPerAmount || 1} عملة
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500 dark:text-gray-400">
                    عدد المشتركين:
                  </span>
                  <span className="font-medium text-gray-900 dark:text-white">
                    {program.customersCount}
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500 dark:text-gray-400">
                    صلاحية النقاط (شهر):
                  </span>
                  <span className="font-medium text-gray-900 dark:text-white">
                    {program.expiryMonths}
                  </span>
                </div>
              </div>

              <div className="flex gap-2 mt-6">
                <button
                  onClick={() => handleOpenModal(program)}
                  className="flex-1 px-3 py-2 bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400 rounded-lg text-sm font-medium hover:bg-purple-100 dark:hover:bg-purple-900/30 transition-colors flex items-center justify-center gap-2"
                >
                  <Edit className="w-4 h-4" />
                  تعديل
                </button>
                <button
                  onClick={() => handleDelete(program.id)}
                  className="px-3 py-2 text-gray-400 hover:text-red-500 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create/Edit Modal */}
      {isModalOpen && editingProgram && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto overflow-x-hidden shadow-2xl">
            <div className="sticky top-0 bg-white dark:bg-gray-800 px-6 py-4 border-b border-gray-100 dark:border-gray-700 flex items-center justify-between z-10">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                {editingProgram.id
                  ? "تعديل برنامج الولاء"
                  : "إنشاء برنامج ولاء جديد"}
              </h2>
              <button
                onClick={() => setIsModalOpen(false)}
                className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
              >
                <Trash2 className="w-6 h-6 rotate-45" />
              </button>
            </div>

            <form onSubmit={handleSave} className="p-6 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                    اسم البرنامج (بالأجنبية)
                  </label>
                  <input
                    type="text"
                    required
                    value={editingProgram.name || ""}
                    onChange={(e) =>
                      setEditingProgram({
                        ...editingProgram,
                        name: e.target.value,
                      })
                    }
                    className="w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900"
                    placeholder="e.g. Platinum Points"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                    اسم البرنامج (بالعربية)
                  </label>
                  <input
                    type="text"
                    required
                    value={editingProgram.nameAr || ""}
                    onChange={(e) =>
                      setEditingProgram({
                        ...editingProgram,
                        nameAr: e.target.value,
                      })
                    }
                    className="w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-right"
                    placeholder="مثلاً: البرنامج البلاتيني"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  وصف البرنامج
                </label>
                <textarea
                  value={editingProgram.description || ""}
                  onChange={(e) =>
                    setEditingProgram({
                      ...editingProgram,
                      description: e.target.value,
                    })
                  }
                  className="w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 h-24"
                  placeholder="اشرح كيف يمكن للعملاء كسب النقاط..."
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                    نوع البرنامج
                  </label>
                  <select
                    value={editingProgram.type || "POINTS"}
                    onChange={(e) =>
                      setEditingProgram({
                        ...editingProgram,
                        type: e.target.value as any,
                      })
                    }
                    className="w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900"
                  >
                    <option value="POINTS">نقاط (Points)</option>
                    <option value="TIERS">مستويات (Tiers)</option>
                    <option value="CASHBACK">كاش باك (Cashback)</option>
                    <option value="REFERRAL">إحالات (Referral)</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                    الحالة
                  </label>
                  <select
                    value={editingProgram.status || "DRAFT"}
                    onChange={(e) =>
                      setEditingProgram({
                        ...editingProgram,
                        status: e.target.value as any,
                      })
                    }
                    className="w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900"
                  >
                    <option value="ACTIVE">نشط</option>
                    <option value="INACTIVE">غير نشط</option>
                    <option value="DRAFT">مسودة</option>
                  </select>
                </div>
              </div>

              <div className="bg-purple-50 dark:bg-purple-900/20 p-4 rounded-xl space-y-4 border border-purple-100 dark:border-purple-900/30">
                <h4 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                  <Gift className="w-4 h-4 text-purple-600" />
                  تكوين المكافآت (Rewards Config)
                </h4>
                <div className="space-y-4">
                  {/* Points Reward Toggle */}
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-white dark:bg-gray-800 rounded-lg text-yellow-500">
                        <Star className="w-4 h-4" />
                      </div>
                      <div>
                        <p className="text-sm font-medium text-gray-900 dark:text-white">
