                      <input
                        type="number"
                        value={editingProgram.rules?.freeShippingThreshold || 0}
                        onChange={(e) =>
                          setEditingProgram({
                            ...editingProgram,
                            rules: {
                              ...(editingProgram.rules || {}),
                              freeShippingThreshold: Number(e.target.value),
                            },
