    <path d="M16 3.13a4 4 0 0 1 0 7.75" />
  </svg>
);

export default LoyaltyTiers;

import React, { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import {
    Wallet,
    Plus,
    History,
    Clock,
    CheckCircle2,
    XCircle,
    AlertCircle,
    Info,
    Loader2,
    Banknote,
    Calendar,
    ArrowRight,
    TrendingDown,
    User,
    ShieldCheck,
    X,
    CreditCard,
    BarChart3,
} from "lucide-react";
import api from "../../services/api";
import { useAuth } from "../../hooks/useAuthSimple";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Label } from "../../components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "../../components/ui/card";
import { Badge } from "../../components/ui/badge";
import { Progress } from "../../components/ui/progress";
import { motion, AnimatePresence } from "framer-motion";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "../../components/ui/select";

type AdvanceFormData = {
    amount: string;
    reason: string;
    repaymentType: "ONE_TIME" | "INSTALLMENTS";
    installmentsCount: string;
};

const StatusBadge = ({ status }: { status: string }) => {
    const config: Record<string, { label: string; icon: React.ReactNode; className: string }> = {
        PENDING: {
            label: "قيد المراجعة",
            icon: <Clock className="w-3.5 h-3.5" />,
            className: "bg-amber-50 text-amber-700 border border-amber-200 dark:bg-amber-900/20 dark:text-amber-300",
        },
        APPROVED: {
            label: "تمت الموافقة",
            icon: <CheckCircle2 className="w-3.5 h-3.5" />,
            className: "bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-300",
        },
        REJECTED: {
            label: "مرفوض",
            icon: <XCircle className="w-3.5 h-3.5" />,
            className: "bg-rose-50 text-rose-700 border border-rose-200 dark:bg-rose-900/20 dark:text-rose-300",
        },
    };

    const c = config[status] || { label: status, icon: null, className: "bg-gray-100 text-gray-600" };
    return (
        <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold ${c.className}`}>
            {c.icon}
            {c.label}
        </span>
    );
};

const MyAdvances = () => {
    const { user } = useAuth();
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(true);
    const [history, setHistory] = useState<any[]>([]);
    const [settings, setSettings] = useState<any>(null);
    const [showForm, setShowForm] = useState(false);
    const [expandedId, setExpandedId] = useState<string | null>(null);

    const {
        register,
        handleSubmit,
        setValue,
        watch,
        reset,
        formState: { errors },
    } = useForm<AdvanceFormData>({
        defaultValues: {
            amount: "",
            reason: "",
            repaymentType: "INSTALLMENTS",
            installmentsCount: "3",
        },
    });

    const repaymentType = watch("repaymentType");
    const amount = watch("amount");
    const installmentsCount = watch("installmentsCount");

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            setFetching(true);
            const [historyResult, settingsResult] = await Promise.allSettled([
                api.get("/hr/advances/my"),
                api.get("/hr/advances/my-config", { _skipErrorToast: true }),
            ]);

            if (historyResult.status === "fulfilled") {
                setHistory(historyResult.value.data.data || []);
            } else {
                console.error("Error fetching advances history:", historyResult.reason);
                toast.error("حدث خطأ أثناء جلب سجل السلف");
            }

            if (settingsResult.status === "fulfilled") {
                setSettings(settingsResult.value.data.settings || {});
            } else {
                console.error("Error fetching advance settings:", settingsResult.reason);
                setSettings(null);
            }
        } catch (error) {
            console.error("Error fetching advances data:", error);
        } finally {
            setFetching(false);
        }
    };

    const onSubmit = async (data: AdvanceFormData) => {
        try {
            setLoading(true);
            const requestedAmount = parseFloat(data.amount);

            if (settings && user?.baseSalary) {
                const maxAllowed = (parseFloat(user.baseSalary) * settings.maxAdvancePercentage) / 100;
                if (requestedAmount > maxAllowed && maxAllowed > 0) {
                    toast.error(`المبلغ يتجاوز الحد المسموح: ${maxAllowed.toFixed(0)} جم`);
                    return;
                }
            }

            await api.post("/hr/advances", {
                ...data,
                amount: requestedAmount,
                installmentsCount: data.repaymentType === "INSTALLMENTS" ? parseInt(data.installmentsCount) : 1,
            });

            toast.success("✅ تم تقديم طلب السلفة بنجاح، سيتم مراجعته قريباً");
            setShowForm(false);
            reset();
            fetchData();
        } catch (error: any) {
            toast.error(error.response?.data?.error || "فشل في تقديم الطلب");
        } finally {
            setLoading(false);
        }
    };

    // Calculate stats
    const totalActive = history
        .filter((r) => r.status === "APPROVED" && !r.isPaidOff)
        .reduce((sum, r) => sum + parseFloat(r.remainingBalance || 0), 0);
    const totalPending = history.filter((r) => r.status === "PENDING").length;
    const totalAmount = history.reduce((sum, r) => sum + parseFloat(r.amount || 0), 0);

    // Try to get baseSalary from advances history (employeeSalary field) or user object
    const baseSalary =
        parseFloat(user?.baseSalary || "0") ||
        history.find((r) => r.employeeSalary && parseFloat(r.employeeSalary) > 0)?.employeeSalary ||
        0;

    const maxAllowed =
        settings && baseSalary > 0
            ? (parseFloat(String(baseSalary)) * settings.maxAdvancePercentage) / 100
            : settings?.maxAdvanceAmount || 0;

    const hasPending = totalPending > 0;
    const hasActiveApproved = history.some((r) => r.status === "APPROVED" && !r.isPaidOff);

    if (fetching) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4" dir="rtl">
                <div className="relative">
                    <Wallet className="w-16 h-16 text-emerald-200 dark:text-emerald-900" />
                    <Loader2 className="w-8 h-8 text-emerald-500 animate-spin absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
                </div>
                <p className="text-gray-400 font-medium text-lg">جارٍ تحميل سجل السلف...</p>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-950 p-4 sm:p-8" dir="rtl">
            <div className="max-w-5xl mx-auto space-y-8">

                {/* ─── Header ─── */}
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-3xl font-black text-gray-900 dark:text-white flex items-center gap-3">
                            <div className="bg-gradient-to-br from-emerald-500 to-teal-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-500/20">
                                <Wallet className="w-7 h-7 text-white" />
                            </div>
                            السلف والمستحقات
                        </h1>
                        <p className="text-gray-500 dark:text-gray-400 mt-1.5 text-base">
                            إدارة طلبات السلف الشخصية ومتابعة حالة السداد
                        </p>
                    </div>

                    {!showForm && !hasPending && (
                        <Button
                            onClick={() => setShowForm(true)}
                            className="bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 text-white shadow-lg shadow-emerald-500/25 rounded-xl h-12 px-6 gap-2 transition-all hover:scale-[1.02]"
                        >
                            <Plus className="w-5 h-5" />
                            طلب سلفة جديدة
                        </Button>
                    )}
                    {hasPending && (
                        <div className="flex items-center gap-2 text-amber-600 bg-amber-50 dark:bg-amber-900/20 px-4 py-2.5 rounded-xl border border-amber-200 dark:border-amber-800 text-sm font-bold">
                            <Clock className="w-4 h-4" />
                            لديك طلب قيد المراجعة
                        </div>
                    )}
                </div>

                {/* ─── Stats Row ─── */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {[
                        {
                            label: "إجمالي طلباتك",
                            value: history.length,
                            suffix: "طلب",
                            icon: <BarChart3 className="w-5 h-5" />,
                            color: "from-blue-500 to-indigo-600",
                            bg: "bg-blue-50 dark:bg-blue-900/20",
                            text: "text-blue-600 dark:text-blue-400",
                        },
                        {
                            label: "قيد الانتظار",
                            value: totalPending,
                            suffix: "طلب",
                            icon: <Clock className="w-5 h-5" />,
                            color: "from-amber-500 to-orange-600",
                            bg: "bg-amber-50 dark:bg-amber-900/20",
                            text: "text-amber-600 dark:text-amber-400",
                        },
                        {
                            label: "المتبقي للسداد",
                            value: totalActive.toFixed(0),
                            suffix: "جم",
                            icon: <TrendingDown className="w-5 h-5" />,
                            color: "from-rose-500 to-pink-600",
                            bg: "bg-rose-50 dark:bg-rose-900/20",
                            text: "text-rose-600 dark:text-rose-400",
                        },
                        {
                            label: "الحد المسموح",
                            value: maxAllowed > 0 ? maxAllowed.toFixed(0) : "---",
                            suffix: maxAllowed > 0 ? "جم" : "",
                            icon: <ShieldCheck className="w-5 h-5" />,
                            color: "from-emerald-500 to-teal-600",
                            bg: "bg-emerald-50 dark:bg-emerald-900/20",
                            text: "text-emerald-600 dark:text-emerald-400",
                        },
                    ].map((stat, i) => (
                        <motion.div
                            key={i}
                            initial={{ opacity: 0, y: 16 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: i * 0.07 }}
                        >
                            <Card className={`border-0 shadow-sm ${stat.bg} overflow-hidden`}>
                                <CardContent className="p-5">
                                    <div className={`${stat.text} mb-3`}>{stat.icon}</div>
                                    <p className="text-gray-500 dark:text-gray-400 text-xs font-semibold mb-1">{stat.label}</p>
                                    <p className={`text-2xl font-black ${stat.text}`}>
                                        {stat.value} <span className="text-sm font-semibold opacity-70">{stat.suffix}</span>
                                    </p>
                                </CardContent>
                            </Card>
                        </motion.div>
                    ))}
                </div>

                {/* ─── New Request Form ─── */}
                <AnimatePresence>
                    {showForm && (
                        <motion.div
                            initial={{ opacity: 0, y: -20, scale: 0.98 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            exit={{ opacity: 0, y: -20, scale: 0.98 }}
                            transition={{ type: "spring", damping: 20 }}
                        >
                            <Card className="border border-emerald-100 dark:border-emerald-900/40 shadow-2xl shadow-emerald-500/5 rounded-3xl overflow-hidden bg-white dark:bg-gray-900">
                                {/* Form header */}
                                <div className="bg-gradient-to-l from-emerald-50 to-teal-50 dark:from-emerald-900/20 dark:to-teal-900/20 px-8 py-6 border-b border-emerald-100 dark:border-emerald-900/30 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="bg-white dark:bg-gray-800 p-2.5 rounded-xl shadow-sm border border-emerald-100 dark:border-emerald-900">
                                            <CreditCard className="w-6 h-6 text-emerald-600" />
                                        </div>
                                        <div>
                                            <h2 className="font-black text-gray-900 dark:text-white text-xl">طلب سلفة جديدة</h2>
                                            <p className="text-gray-500 dark:text-gray-400 text-sm">سيتم مراجعة طلبك من قبل الإدارة</p>
                                        </div>
                                    </div>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => { setShowForm(false); reset(); }}
                                        className="rounded-xl text-gray-400 hover:text-gray-600 hover:bg-white dark:hover:bg-gray-800"
                                    >
                                        <X className="w-5 h-5" />
                                    </Button>
                                </div>

                                <CardContent className="p-8">
                                    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            {/* Amount */}
                                            <div className="space-y-2">
                                                <Label className="font-bold text-gray-700 dark:text-gray-300 flex items-center gap-2">
                                                    <Banknote className="w-4 h-4 text-emerald-500" />
                                                    المبلغ المطلوب (جم)
                                                </Label>
                                                <div className="relative">
                                                    <Input
                                                        type="number"
                                                        placeholder="مثال: 2000"
                                                        className="h-14 text-xl font-bold pr-4 pl-14 border-2 border-gray-100 dark:border-gray-700 focus:border-emerald-400 focus:ring-emerald-200 rounded-xl bg-gray-50/50 dark:bg-gray-800/50 transition-all"
                                                        {...register("amount", {
                                                            required: "يرجى إدخال المبلغ",
                                                            min: { value: 100, message: "الحد الأدنى 100 جم" },
                                                        })}
                                                    />
                                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold text-sm">جم</span>
                                                </div>
                                                {errors.amount && (
                                                    <p className="text-rose-500 text-sm flex items-center gap-1 font-medium">
                                                        <AlertCircle className="w-4 h-4" /> {errors.amount.message}
                                                    </p>
                                                )}
                                                {maxAllowed > 0 && (
                                                    <p className="text-gray-400 text-xs font-medium flex items-center gap-1">
                                                        <Info className="w-3.5 h-3.5" />
                                                        الحد الأقصى المسموح: <span className="text-emerald-600 font-bold">{maxAllowed.toFixed(0)} جم</span>
                                                    </p>
                                                )}
                                            </div>

                                            {/* Repayment Type */}
                                            <div className="space-y-2">
                                                <Label className="font-bold text-gray-700 dark:text-gray-300 flex items-center gap-2">
                                                    <Calendar className="w-4 h-4 text-blue-500" />
                                                    طريقة السداد
                                                </Label>
                                                <Select
                                                    onValueChange={(val) => setValue("repaymentType", val as any)}
                                                    defaultValue="INSTALLMENTS"
                                                >
                                                    <SelectTrigger className="h-14 text-base font-semibold border-2 border-gray-100 dark:border-gray-700 rounded-xl bg-gray-50/50 dark:bg-gray-800/50 focus:border-blue-400">
                                                        <SelectValue placeholder="اختر طريقة السداد" />
                                                    </SelectTrigger>
                                                    <SelectContent className="rounded-xl border-2 shadow-xl">
                                                        <SelectItem value="INSTALLMENTS" className="text-base h-11 rounded-lg font-medium">📅 تقسيط شهري على دفعات</SelectItem>
                                                        <SelectItem value="ONE_TIME" className="text-base h-11 rounded-lg font-medium">💸 خصم كامل من الراتب القادم</SelectItem>
                                                    </SelectContent>
                                                </Select>
                                            </div>

                                            {/* Installments Count */}
                                            {repaymentType === "INSTALLMENTS" && (
                                                <motion.div
                                                    initial={{ opacity: 0, x: -16 }}
                                                    animate={{ opacity: 1, x: 0 }}
                                                    className="space-y-2"
                                                >
                                                    <Label className="font-bold text-gray-700 dark:text-gray-300 flex items-center gap-2">
                                                        <Clock className="w-4 h-4 text-amber-500" />
                                                        عدد الأقساط (أشهر)
                                                    </Label>
                                                    <Input
                                                        type="number"
                                                        className="h-14 text-xl font-bold border-2 border-gray-100 dark:border-gray-700 focus:border-amber-400 focus:ring-amber-200 rounded-xl bg-gray-50/50 dark:bg-gray-800/50 transition-all"
                                                        {...register("installmentsCount", {
                                                            required: "أدخل عدد الأقساط",
                                                            min: { value: 1, message: "الحد الأدنى شهر واحد" },
                                                            max: { value: settings?.advanceRepaymentMonths || 12, message: `الحد الأقصى ${settings?.advanceRepaymentMonths || 12} أشهر` },
                                                        })}
                                                    />
                                                    {errors.installmentsCount && (
                                                        <p className="text-rose-500 text-sm font-medium">{errors.installmentsCount.message}</p>
                                                    )}
                                                </motion.div>
                                            )}

                                            {/* Live Summary */}
                                            {amount && parseFloat(amount) > 0 && (
                                                <motion.div
                                                    initial={{ opacity: 0 }}
                                                    animate={{ opacity: 1 }}
                                                    className={`${repaymentType === "INSTALLMENTS" ? "" : "md:col-span-2"} bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 border-2 border-blue-100 dark:border-blue-900/30 rounded-2xl p-5`}
                                                >
                                                    <p className="text-blue-700 dark:text-blue-300 font-black text-sm mb-2 flex items-center gap-2">
                                                        <Info className="w-4 h-4" /> ملخص السلفة
                                                    </p>
                                                    <div className="flex flex-wrap gap-4">
                                                        <div>
                                                            <p className="text-xs text-blue-500 font-semibold">المبلغ الإجمالي</p>
                                                            <p className="text-2xl font-black text-blue-800 dark:text-blue-200">{parseFloat(amount).toFixed(0)} <span className="text-sm">جم</span></p>
                                                        </div>
                                                        {repaymentType === "INSTALLMENTS" && installmentsCount && (
                                                            <div>
                                                                <p className="text-xs text-blue-500 font-semibold">القسط الشهري</p>
                                                                <p className="text-2xl font-black text-emerald-700 dark:text-emerald-300">
                                                                    {(parseFloat(amount) / parseInt(installmentsCount || "1")).toFixed(0)} <span className="text-sm">جم</span>
                                                                </p>
                                                            </div>
                                                        )}
                                                    </div>
                                                </motion.div>
                                            )}
                                        </div>

                                        {/* Reason */}
                                        <div className="space-y-2">
                                            <Label className="font-bold text-gray-700 dark:text-gray-300">سبب الطلب</Label>
                                            <Textarea
                                                placeholder="يرجى توضيح سبب الاحتياج للسلفة مثل: ظروف طارئة، مصروفات طبية..."
                                                className="min-h-[110px] text-base border-2 border-gray-100 dark:border-gray-700 focus:border-emerald-400 transition-all bg-gray-50/50 dark:bg-gray-800/50 p-4 rounded-xl resize-none"
                                                {...register("reason", { required: "يرجى إدخال سبب الطلب" })}
                                            />
                                            {errors.reason && (
                                                <p className="text-rose-500 text-sm font-medium flex items-center gap-1">
                                                    <AlertCircle className="w-4 h-4" /> {errors.reason.message}
                                                </p>
                                            )}
                                        </div>

                                        <div className="flex gap-3 pt-2">
                                            <Button
                                                type="button"
                                                variant="outline"
                                                onClick={() => { setShowForm(false); reset(); }}
                                                className="flex-1 h-12 rounded-xl font-bold border-2"
                                            >
                                                إلغاء
                                            </Button>
                                            <Button
                                                type="submit"
                                                disabled={loading}
                                                className="flex-[2] h-12 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 text-white rounded-xl font-bold shadow-lg shadow-emerald-500/20 text-base gap-2"
                                            >
                                                {loading ? (
                                                    <><Loader2 className="w-5 h-5 animate-spin" /> جارٍ الإرسال...</>
                                                ) : (
                                                    <><CheckCircle2 className="w-5 h-5" /> تأكيد وإرسال الطلب</>
                                                )}
                                            </Button>
                                        </div>
                                    </form>
                                </CardContent>
                            </Card>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* ─── History List ─── */}
                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <h2 className="text-xl font-black text-gray-800 dark:text-white flex items-center gap-2.5">
                            <History className="w-6 h-6 text-gray-400" />
                            سجل السلف
                            {history.length > 0 && (
                                <span className="bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 text-sm px-2.5 py-0.5 rounded-full font-bold">
                                    {history.length}
                                </span>
                            )}
                        </h2>
                    </div>

                    {history.length === 0 ? (
                        <motion.div
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="bg-white dark:bg-gray-900 border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-3xl p-16 text-center space-y-4"
                        >
                            <div className="bg-emerald-50 dark:bg-emerald-900/20 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto border border-emerald-100 dark:border-emerald-900">
                                <Banknote className="w-10 h-10 text-emerald-300" />
                            </div>
                            <h3 className="text-2xl font-black text-gray-700 dark:text-gray-300">لا توجد سلف بعد</h3>
                            <p className="text-gray-400 max-w-sm mx-auto">لم يتم تقديم أو إنشاء أي طلبات سلف لحسابك حتى الآن.</p>
                            <Button
                                onClick={() => setShowForm(true)}
                                className="mt-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl h-11 px-8 font-bold"
                            >
                                <Plus className="w-4 h-4 ml-1" />
                                اطلب أول سلفة
                            </Button>
                        </motion.div>
                    ) : (
                        <div className="space-y-3">
                            {history.map((req, idx) => {
                                const isExpanded = expandedId === req.id;
                                const paidAmount = parseFloat(req.amount || 0) - parseFloat(req.remainingBalance || req.amount || 0);
                                const progressPct = parseFloat(req.amount) > 0
                                    ? (paidAmount / parseFloat(req.amount)) * 100
                                    : 0;
                                const isManagerCreated = req.approver || req.approvedBy;
                                const isOneTime = req.repaymentType === "ONE_TIME" || req.repaymentType === "MONTHLY";

                                return (
                                    <motion.div
                                        key={req.id}
                                        initial={{ opacity: 0, y: 12 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: idx * 0.05 }}
                                    >
                                        <Card
                                            className={`border border-gray-100 dark:border-gray-800 shadow-sm hover:shadow-md transition-all rounded-2xl overflow-hidden bg-white dark:bg-gray-900 cursor-pointer
                                                ${req.status === "PENDING" ? "border-l-4 border-l-amber-400" :
                                                    req.status === "APPROVED" ? "border-l-4 border-l-emerald-400" :
                                                        req.status === "REJECTED" ? "border-l-4 border-l-rose-400" : ""}`}
                                            onClick={() => setExpandedId(isExpanded ? null : req.id)}
                                        >
                                            <CardContent className="p-0">
                                                {/* Main Row */}
                                                <div className="flex items-center gap-4 p-5">
                                                    {/* Amount Badge */}
                                                    <div className={`w-16 h-16 rounded-2xl flex flex-col items-center justify-center shrink-0 font-black text-sm
                                                        ${req.status === "APPROVED" ? "bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300" :
                                                            req.status === "REJECTED" ? "bg-rose-50 dark:bg-rose-900/20 text-rose-700 dark:text-rose-300" :
                                                                "bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-300"}`}>
                                                        <span className="text-lg font-black leading-none">{parseFloat(req.amount).toFixed(0)}</span>
                                                        <span className="text-xs opacity-70">جم</span>
                                                    </div>

                                                    {/* Info */}
                                                    <div className="flex-1 min-w-0">
                                                        <div className="flex items-center gap-2 flex-wrap mb-1">
                                                            <StatusBadge status={req.status} />
                                                            <span className="text-xs text-gray-400 font-medium">
                                                                {isOneTime ? "دفعة واحدة" : `${req.installmentsCount} أقساط`}
                                                            </span>
                                                            {/* Tag if created by manager */}
                                                            {req.approvedBy && req.status === "APPROVED" && (
                                                                <span className="inline-flex items-center gap-1 text-xs text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-900/40 px-2 py-0.5 rounded-full font-bold">
                                                                    <User className="w-3 h-3" /> معتمدة من الإدارة
                                                                </span>
                                                            )}
                                                        </div>
                                                        <p className="text-gray-500 dark:text-gray-400 text-xs font-medium truncate">
                                                            {req.reason}
                                                        </p>
                                                        <p className="text-gray-400 text-xs mt-0.5">
                                                            {new Date(req.createdAt).toLocaleDateString("ar-EG", {
                                                                year: "numeric", month: "long", day: "numeric"
                                                            })}
                                                        </p>
                                                    </div>

                                                    {/* Right side */}
                                                    <div className="flex items-center gap-3 shrink-0">
                                                        {req.status === "APPROVED" && !req.isPaidOff && (
                                                            <div className="text-left hidden sm:block">
                                                                <p className="text-xs text-gray-400 font-semibold">المتبقي</p>
                                                                <p className="text-lg font-black text-rose-600 dark:text-rose-400">
                                                                    {parseFloat(req.remainingBalance || 0).toFixed(0)} جم
                                                                </p>
                                                            </div>
                                                        )}
                                                        {req.isPaidOff && (
                                                            <span className="text-emerald-600 text-xs font-black bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-900 px-3 py-1.5 rounded-full flex items-center gap-1">
                                                                <CheckCircle2 className="w-3.5 h-3.5" /> مسدّدة
                                                            </span>
                                                        )}
                                                        <ArrowRight className={`w-4 h-4 text-gray-300 transition-transform ${isExpanded ? "rotate-90" : ""}`} />
                                                    </div>
                                                </div>

                                                {/* Progress bar for approved */}
                                                {req.status === "APPROVED" && !isOneTime && !req.isPaidOff && (
                                                    <div className="px-5 pb-3">
                                                        <div className="flex justify-between text-xs text-gray-400 mb-1.5 font-medium">
                                                            <span>تم سداد {paidAmount.toFixed(0)} جم</span>
                                                            <span>{progressPct.toFixed(0)}%</span>
                                                        </div>
                                                        <Progress value={progressPct} className="h-1.5 bg-gray-100 dark:bg-gray-800" />
                                                    </div>
                                                )}

                                                {/* Expanded Details */}
                                                <AnimatePresence>
                                                    {isExpanded && (
                                                        <motion.div
                                                            initial={{ height: 0, opacity: 0 }}
                                                            animate={{ height: "auto", opacity: 1 }}
                                                            exit={{ height: 0, opacity: 0 }}
                                                            transition={{ duration: 0.2 }}
                                                            className="overflow-hidden"
                                                        >
                                                            <div className="border-t border-gray-100 dark:border-gray-800 p-5 bg-gray-50/50 dark:bg-gray-800/30 space-y-4">
                                                                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                                                                    <div>
                                                                        <p className="text-gray-400 font-semibold text-xs uppercase mb-1">المبلغ الكلي</p>
                                                                        <p className="font-black text-gray-800 dark:text-white text-base">{parseFloat(req.amount).toFixed(0)} جم</p>
                                                                    </div>
                                                                    <div>
                                                                        <p className="text-gray-400 font-semibold text-xs uppercase mb-1">طريقة السداد</p>
                                                                        <p className="font-bold text-gray-700 dark:text-gray-300">
                                                                            {isOneTime ? "دفعة واحدة" : `${req.installmentsCount} أقساط`}
                                                                        </p>
                                                                    </div>
                                                                    {!isOneTime && (
                                                                        <div>
                                                                            <p className="text-gray-400 font-semibold text-xs uppercase mb-1">القسط الشهري</p>
                                                                            <p className="font-bold text-gray-700 dark:text-gray-300">{parseFloat(req.monthlyAmount || req.installmentAmount || 0).toFixed(0)} جم</p>
                                                                        </div>
                                                                    )}
                                                                    <div>
                                                                        <p className="text-gray-400 font-semibold text-xs uppercase mb-1">تاريخ الطلب</p>
                                                                        <p className="font-bold text-gray-700 dark:text-gray-300">
                                                                            {new Date(req.createdAt).toLocaleDateString("ar-EG")}
                                                                        </p>
                                                                    </div>
                                                                </div>

                                                                {/* Reason box */}
                                                                <div className="bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 rounded-xl p-4">
                                                                    <p className="text-xs text-gray-400 font-bold uppercase mb-1.5">سبب الطلب</p>
                                                                    <p className="text-gray-700 dark:text-gray-300 font-medium leading-relaxed">{req.reason}</p>
                                                                </div>

                                                                {/* Approval info */}
                                                                {req.status === "APPROVED" && req.approver && (
                                                                    <div className="flex items-center gap-2 text-emerald-700 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-900/30 px-4 py-2.5 rounded-xl text-sm font-bold">
                                                                        <ShieldCheck className="w-4 h-4" />
                                                                        تمت الموافقة من قبل: {req.approver.firstName} {req.approver.lastName}
                                                                        {req.approvedAt && (
                                                                            <span className="text-emerald-500 font-normal mr-auto">
                                                                                {new Date(req.approvedAt).toLocaleDateString("ar-EG")}
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                )}

                                                                {/* Rejection reason */}
                                                                {req.status === "REJECTED" && req.rejectedReason && (
                                                                    <div className="flex items-start gap-2.5 text-rose-700 dark:text-rose-400 bg-rose-50 dark:bg-rose-900/20 border border-rose-100 dark:border-rose-900/30 px-4 py-3 rounded-xl text-sm">
                                                                        <XCircle className="w-4 h-4 shrink-0 mt-0.5" />
                                                                        <div>
                                                                            <p className="font-black text-xs uppercase mb-0.5">سبب الرفض</p>
                                                                            <p className="font-medium">{req.rejectedReason}</p>
                                                                        </div>
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </motion.div>
                                                    )}
                                                </AnimatePresence>
                                            </CardContent>
                                        </Card>
                                    </motion.div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default MyAdvances;

/**
 * 🏠 My Dashboard - Employee Dashboard
 * لوحة التحكم الشخصية للموظف
 */

import React, { useState, useEffect, useCallback, useMemo } from "react";
import {
  Clock,
  Calendar,
  DollarSign,
  FileText,
  TrendingUp,
  AlertCircle,
  CheckCircle,
  Users,
  Award,
  Target,
  CreditCard,
  Briefcase,
  AlertTriangle,
  ChevronRight,
  Plus,
  ArrowRight,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Progress } from "../../components/ui/progress";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../components/ui/tabs";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../../hooks/useAuthSimple";
import api from "../../services/api";
import { createStorageKey, getWithExpiry, setWithExpiry } from "../../utils/storage";
import { toast } from "sonner";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface EmployeeInfo {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  avatar: string;
  employeeNumber: string;
  department: { name: string; color: string } | null;
  position: { title: string } | null;
  hireDate: string;
  annualLeaveBalance: number;
  sickLeaveBalance: number;
}

interface TodayAttendance {
  checkIn: string | null;
  checkOut: string | null;
  status: string;
}

interface RecentLeave {
  id: string;
  type: string;
  startDate: string;
  endDate: string;
  totalDays: number;
  status: string;
}

interface PermissionRequest {
  id: string;
  type: string;
  date: string;
  startTime: string;
  endTime: string;
  status: string;
  reason: string;
}

interface Warning {
  id: string;
  type?: string;
  severity?: string;
  title?: string;
  description?: string;
  status?: string;
  incidentDate?: string;
  createdAt?: string;
}

interface AdvanceRequest {
  id: string;
  amount: number;
  reason?: string;
  status: "PENDING" | "APPROVED" | "REJECTED";
  createdAt: string;
  repaymentType: string;
  installmentsCount: number;
  remainingBalance: number;
}

interface Reward {
  id: string;
  rewardName: string;
  calculatedValue: number;
  rewardCategory: string;
  status: string;
  appliedAt: string;
  createdAt: string;
}

interface LastPayroll {
  id: string;
  month: number;
  year: number;
  netSalary: number;
  status: string;
  totalAllowances: number;
  totalDeductions: number;
}

interface DashboardCachePayload {
  employee: EmployeeInfo | null;
  todayAttendance: TodayAttendance | null;
  recentLeaves: RecentLeave[];
  permissions: PermissionRequest[];
  advances: AdvanceRequest[];
  warnings: Warning[];
  rewards: Reward[];
  lastPayroll: LastPayroll | null;
}



const DASHBOARD_CACHE_TTL_MS = 60 * 1000;

const MyDashboard: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("overview");

  const [employee, setEmployee] = useState<EmployeeInfo | null>(null);
  const [todayAttendance, setTodayAttendance] = useState<TodayAttendance | null>(null);
  const [recentLeaves, setRecentLeaves] = useState<RecentLeave[]>([]);
  const [permissions, setPermissions] = useState<PermissionRequest[]>([]);
  const [advances, setAdvances] = useState<AdvanceRequest[]>([]);
  const [warnings, setWarnings] = useState<Warning[]>([]);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [lastPayroll, setLastPayroll] = useState<LastPayroll | null>(null);

  const cacheKey = useMemo(
    () => createStorageKey("dashboard", `employee:${user?.id || "anon"}`),
    [user?.id],
  );

  const applyDashboardPayload = useCallback((payload: DashboardCachePayload) => {
    if (!payload) return;
    setEmployee(payload.employee ?? null);
    setTodayAttendance(payload.todayAttendance ?? null);
    setRecentLeaves(payload.recentLeaves ?? []);
    setPermissions(payload.permissions ?? []);
    setAdvances(payload.advances ?? []);
    setWarnings(payload.warnings ?? []);
    setRewards(payload.rewards ?? []);
    setLastPayroll(payload.lastPayroll ?? null);
  }, []);

  const fetchDashboardData = useCallback(
    async ({ signal, background = false } = {}) => {
      if (!background) {
        setLoading(true);
      }

      try {
        const [empRes, attRes, leavesRes, permissionsRes, advancesRes, warningsRes, rewardsRes, payrollRes] = await Promise.all([
          api.get("/hr/employees/me", { signal }),
          api.get("/hr/attendance/my-today", { signal }),
          api.get("/hr/leaves/my-recent", { params: { limit: 5 }, signal }),
          api.get("/hr/permissions", { params: { mine: true, limit: 5 }, signal }),
          api.get("/hr/advances/my", { params: { limit: 5 }, signal }),
          api.get("/hr/warnings/my-history", { params: { limit: 5 }, signal }),
          api.get("/hr/rewards/my-rewards", { params: { limit: 5 }, signal }),
          api.get("/hr/payroll/my-last", { signal }),
        ]);

        const payload: DashboardCachePayload = {
          employee: empRes.data.employee,
          todayAttendance: attRes.data.attendance,
          recentLeaves: leavesRes.data.leaves || [],
          permissions: permissionsRes.data.requests || [],
          advances: advancesRes.data.data || [],
          warnings: warningsRes.data.warnings || [],
          rewards: rewardsRes.data.data || [],
          lastPayroll: payrollRes.data.payroll,
        };

        applyDashboardPayload(payload);
        setWithExpiry(cacheKey, payload, DASHBOARD_CACHE_TTL_MS);
      } catch (error: any) {
        if (error?.name === "CanceledError" || error?.code === "ERR_CANCELED") {
          return;
        }
        console.error("Error fetching dashboard data:", error);
        if (!background) {
          toast.error("حدث خطأ أثناء جلب البيانات");
        }
      } finally {
        if (!background) {
          setLoading(false);
        }
      }
    },
    [applyDashboardPayload, cacheKey],
  );

  useEffect(() => {
    const controller = new AbortController();
    const cached = getWithExpiry<DashboardCachePayload>(cacheKey);

    if (cached) {
      applyDashboardPayload(cached);
      setLoading(false);
      fetchDashboardData({ signal: controller.signal, background: true });
    } else {
      fetchDashboardData({ signal: controller.signal });
    }

    return () => controller.abort();
  }, [cacheKey, fetchDashboardData, applyDashboardPayload]);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-screen space-y-4 bg-gray-50/50 dark:bg-gray-900/50">
        <div className="relative">
          <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-primary"></div>
          <div className="absolute top-0 left-0 animate-pulse rounded-full h-16 w-16 bg-primary/10"></div>
        </div>
        <p className="text-lg font-medium text-gray-600 dark:text-gray-300 animate-pulse">جاري تحميل بياناتك...</p>
      </div>
    );
  }

  if (!employee) {
    return (
      <div className="flex flex-col items-center justify-center h-screen space-y-6">
        <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-2xl text-center">
          <AlertCircle className="h-16 w-16 text-red-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">عذراً، لم يتم العثور على بيانات الموظف</h2>
          <p className="text-gray-500 dark:text-gray-400">يرجى الاتصال بإدارة الموارد البشرية للتأكد من ربط حسابك.</p>
        </div>
        <Button onClick={() => window.location.reload()} variant="outline">إعادة المحاولة</Button>
      </div>
    );
  }

  const canCheckIn = !todayAttendance?.checkIn;
  const canCheckOut = todayAttendance?.checkIn && !todayAttendance?.checkOut;

  const pendingRequestsCount = [
    ...recentLeaves.filter(l => l.status === "PENDING"),
    ...permissions.filter(p => p.status === "PENDING"),
    ...advances.filter(a => a.status === "PENDING")
  ].length;

  return (
    <div className="p-4 md:p-8 space-y-8 bg-[#f8faff] dark:bg-gray-950 min-h-screen font-inter" dir="rtl">
      {/* Header with Welcome & Quick Info */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <div className="relative">
            <Avatar className="h-20 w-20 ring-4 ring-white dark:ring-gray-800 shadow-xl border-2 border-primary/20">
              <AvatarImage src={employee.avatar} className="object-cover" />
              <AvatarFallback className="bg-primary/5 text-primary text-2xl font-bold">
                {employee.firstName?.[0]}
                {employee.lastName?.[0]}
              </AvatarFallback>
            </Avatar>
            <div className="absolute -bottom-1 -right-1 h-6 w-6 bg-green-500 border-4 border-[#f8faff] dark:border-gray-950 rounded-full shadow-lg"></div>
          </div>
          <div>
            <div className="flex items-center gap-2 mb-1">
              <h1 className="text-3xl font-extrabold text-gray-900 dark:text-white tracking-tight">
                مرحباً، {employee.firstName}
              </h1>
              <span className="text-3xl animate-bounce">👋</span>
            </div>
            <p className="text-gray-500 dark:text-gray-400 font-medium flex items-center gap-2">
              <span className="bg-primary/10 text-primary px-3 py-0.5 rounded-full text-sm">
                {employee.position?.title || "موظف"}
              </span>
              <span>•</span>
              <span className="text-gray-400 dark:text-gray-500">
                {employee.department?.name || "بدون قسم"}
              </span>
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-gray-900 px-5 py-3 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 flex flex-col items-center min-w-[120px]">
            <span className="text-xs text-gray-400 font-bold uppercase tracking-wider mb-1">رقم الموظف</span>
            <span className="text-lg font-black text-primary">{employee.employeeNumber}</span>
          </div>
          <Button
            variant="outline"
            className="rounded-2xl h-14 px-6 border-gray-200 hover:border-primary hover:text-primary transition-all duration-300"
            onClick={() => navigate("/profile")}
          >
            <Users className="ml-2 h-5 w-5" />
            الملف الشخصي
          </Button>
        </div>
      </div>

      {/* Stats Summary Cards */}
      <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-4">
        {/* Attendance Card */}
        <Card className="border-none shadow-sm bg-blue-600 text-white overflow-hidden relative group cursor-pointer" onClick={() => navigate("/my-attendance")}>
          <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform duration-500">
            <Clock className="h-24 w-24" />
          </div>
          <CardContent className="p-6 relative">
            <p className="text-blue-100 text-sm font-bold mb-4 flex items-center gap-2">
              <Clock className="h-4 w-4" /> الحضور اليوم
            </p>
            <div className="flex flex-col">
              {todayAttendance?.checkIn ? (
                <>
                  <span className="text-3xl font-black mb-1">
                    {new Date(todayAttendance.checkIn).toLocaleTimeString("ar-EG", { hour: "2-digit", minute: "2-digit" })}
                  </span>
                  <span className="text-xs text-blue-100 font-medium">سجلت الحضور بنجاح</span>
                </>
              ) : (
                <>
                  <span className="text-3xl font-black mb-1 text-blue-200 opacity-60">--:--</span>
                  <span className="text-xs text-blue-100 font-medium">لم يتم تسجيل الحضور اليوم</span>
                </>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Leave Balance Card */}
        <Card className="border-none shadow-sm bg-white dark:bg-gray-900 overflow-hidden relative group cursor-pointer" onClick={() => navigate("/my-leaves")}>
          <CardContent className="p-6">
            <div className="flex justify-between items-start mb-4">
              <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-2xl text-green-600 dark:text-green-400 group-hover:scale-110 transition-transform duration-300">
                <Calendar className="h-6 w-6" />
              </div>
              <Badge variant="outline" className="rounded-lg text-[10px] font-bold text-gray-400 border-gray-100">رصيد سنوي</Badge>
            </div>
            <p className="text-sm text-gray-500 font-medium mb-1">رصيد الإجازات</p>
            <div className="flex items-baseline gap-1">
              <span className="text-3xl font-black text-gray-900 dark:text-white">{employee.annualLeaveBalance}</span>
              <span className="text-sm text-gray-400 font-bold">يوم</span>
            </div>
          </CardContent>
        </Card>

        {/* Financial Info Card */}
        <Card className="border-none shadow-sm bg-white dark:bg-gray-900 overflow-hidden relative group cursor-pointer" onClick={() => navigate("/my-payroll")}>
          <CardContent className="p-6">
            <div className="flex justify-between items-start mb-4">
              <div className="p-3 bg-purple-50 dark:bg-purple-900/20 rounded-2xl text-purple-600 dark:text-purple-400 group-hover:scale-110 transition-transform duration-300">
                <CreditCard className="h-6 w-6" />
              </div>
              <Badge variant="outline" className="rounded-lg text-[10px] font-bold text-gray-400 border-gray-100">{lastPayroll ? months[lastPayroll.month - 1] : "--"}</Badge>
            </div>
            <p className="text-sm text-gray-500 font-medium mb-1">آخر مرتب صافي</p>
            <div className="flex items-baseline gap-1">
              <span className="text-3xl font-black text-gray-900 dark:text-white">
                {lastPayroll ? lastPayroll.netSalary.toLocaleString() : "0"}
              </span>
              <span className="text-sm text-gray-400 font-bold">ج.م</span>
            </div>
          </CardContent>
        </Card>

        {/* Tenure Card */}
        <Card className="border-none shadow-sm bg-white dark:bg-gray-900 overflow-hidden relative group cursor-pointer">
          <CardContent className="p-6">
            <div className="flex justify-between items-start mb-4">
              <div className="p-3 bg-orange-50 dark:bg-orange-900/20 rounded-2xl text-orange-600 dark:text-orange-400 group-hover:scale-110 transition-transform duration-300">
                <Briefcase className="h-6 w-6" />
              </div>
              <Badge variant="outline" className="rounded-lg text-[10px] font-bold text-gray-400 border-gray-100">مسيرة العمل</Badge>
            </div>
            <p className="text-sm text-gray-500 font-medium mb-1">مدة الخدمة</p>
            <div className="flex items-baseline gap-1">
              <span className="text-3xl font-black text-gray-900 dark:text-white">
                {Math.max(0, Math.floor((new Date().getTime() - new Date(employee.hireDate).getTime()) / (1000 * 60 * 60 * 24 * 365)))}
              </span>
              <span className="text-sm text-gray-400 font-bold">سنة</span>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Main Content Layout */}
      <div className="grid gap-8 lg:grid-cols-3">

        {/* Left Column: Quick Actions & Pending Requests */}
        <div className="space-y-6 lg:col-span-1">

          {/* Action Center */}
          <Card className="border-none shadow-md bg-gradient-to-br from-white to-gray-50 dark:from-gray-900 dark:to-gray-950 overflow-hidden">
            <CardHeader className="pb-4">
              <CardTitle className="text-lg font-bold flex items-center gap-2">
                <Target className="h-5 w-5 text-primary" />
                الإجراءات السريعة
              </CardTitle>
              <CardDescription>اطلب ما تحتاجه بضغطة واحدة</CardDescription>
            </CardHeader>
            <CardContent className="grid gap-3">
              <Button
                variant="outline"
                className="w-full justify-start h-14 rounded-2xl bg-white dark:bg-gray-900 border-gray-100 hover:border-primary/50 hover:bg-primary/5 shadow-sm transition-all group"
                onClick={() => navigate("/my-attendance")}
              >
                <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-xl ml-3 group-hover:bg-blue-100 group-hover:scale-110 transition-all">
                  <Clock className="h-5 w-5 text-blue-600" />
                </div>
                <div className="flex-1 text-right">
                  <p className="font-bold text-gray-900 dark:text-gray-100">{canCheckIn ? "تسجيل حضور" : "تسجيل انصراف"}</p>
                  <p className="text-[10px] text-gray-400">تحقق من الدوام اليومي</p>
                </div>
                <ArrowRight className="h-4 w-4 text-gray-300 opacity-0 group-hover:opacity-100 -mr-4 group-hover:mr-0 transition-all" />
              </Button>

              <Button
                variant="outline"
                className="w-full justify-start h-14 rounded-2xl bg-white dark:bg-gray-900 border-gray-100 hover:border-green-500/50 hover:bg-green-50/50 shadow-sm transition-all group"
                onClick={() => navigate("/my-leaves", { state: { createNew: true } })}
              >
                <div className="p-2 bg-green-50 dark:bg-green-900/20 rounded-xl ml-3 group-hover:bg-green-100 group-hover:scale-110 transition-all">
                  <Calendar className="h-5 w-5 text-green-600" />
                </div>
                <div className="flex-1 text-right">
                  <p className="font-bold text-gray-900 dark:text-gray-100">طلب إجازة</p>
                  <p className="text-[10px] text-gray-400">سنوية، مرضية، أو اضطرارية</p>
                </div>
                <ArrowRight className="h-4 w-4 text-gray-300 opacity-0 group-hover:opacity-100 -mr-4 group-hover:mr-0 transition-all" />
              </Button>

              <Button
                variant="outline"
                className="w-full justify-start h-14 rounded-2xl bg-white dark:bg-gray-900 border-gray-100 hover:border-yellow-500/50 hover:bg-yellow-50/50 shadow-sm transition-all group"
                onClick={() => navigate("/my-permissions", { state: { createNew: true } })}
              >
                <div className="p-2 bg-yellow-50 dark:bg-yellow-900/20 rounded-xl ml-3 group-hover:bg-yellow-100 group-hover:scale-110 transition-all">
                  <FileText className="h-5 w-5 text-yellow-600" />
                </div>
                <div className="flex-1 text-right">
                  <p className="font-bold text-gray-900 dark:text-gray-100">طلب إذن</p>
                  <p className="text-[10px] text-gray-400">خروج مبكر أو تأخير بعذر</p>
                </div>
                <ArrowRight className="h-4 w-4 text-gray-300 opacity-0 group-hover:opacity-100 -mr-4 group-hover:mr-0 transition-all" />
              </Button>

              <Button
                variant="outline"
                className="w-full justify-start h-14 rounded-2xl bg-white dark:bg-gray-900 border-gray-100 hover:border-purple-500/50 hover:bg-purple-50/50 shadow-sm transition-all group"
                onClick={() => navigate("/my-advances", { state: { createNew: true } })}
              >
                <div className="p-2 bg-purple-50 dark:bg-purple-900/20 rounded-xl ml-3 group-hover:bg-purple-100 group-hover:scale-110 transition-all">
                  <DollarSign className="h-5 w-5 text-purple-600" />
                </div>
                <div className="flex-1 text-right">
                  <p className="font-bold text-gray-900 dark:text-gray-100">طلب سلفة</p>
                  <p className="text-[10px] text-gray-400">تمويل شخصي ميسر</p>
                </div>
                <ArrowRight className="h-4 w-4 text-gray-300 opacity-0 group-hover:opacity-100 -mr-4 group-hover:mr-0 transition-all" />
              </Button>
            </CardContent>
          </Card>

          {/* Pending Requests Summary */}
          {pendingRequestsCount > 0 && (
            <Card className="border-none shadow-md bg-white dark:bg-gray-900 relative overflow-hidden">
              <div className="absolute top-0 right-0 h-1 w-full bg-yellow-400"></div>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-bold flex items-center justify-between">
                  <span>طلبات قيد المراجعة</span>
                  <Badge className="bg-yellow-100 text-yellow-700 hover:bg-yellow-100 border-none rounded-full">{pendingRequestsCount}</Badge>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <p className="text-xs text-gray-500">لديك {pendingRequestsCount} طلبات تنتظر الموافقة من المدير المباشر.</p>
                <div className="flex -space-x-reverse space-x-2">
                  {recentLeaves.filter(l => l.status === "PENDING").map(l => (
                    <div key={l.id} title="طلب إجازة" className="p-2 bg-green-50 dark:bg-green-900/20 rounded-lg text-green-600 border border-green-100 dark:border-green-800">
                      <Calendar className="h-4 w-4" />
                    </div>
                  ))}
                  {permissions.filter(p => p.status === "PENDING").map(p => (
                    <div key={p.id} title="طلب إذن" className="p-2 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg text-yellow-600 border border-yellow-100 dark:border-yellow-800">
                      <FileText className="h-4 w-4" />
                    </div>
                  ))}
                  {advances.filter(a => a.status === "PENDING").map(a => (
                    <div key={a.id} title="طلب سلفة" className="p-2 bg-purple-50 dark:bg-purple-900/20 rounded-lg text-purple-600 border border-purple-100 dark:border-purple-800">
                      <DollarSign className="h-4 w-4" />
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Warnings Alert */}
          {warnings.length > 0 && warnings.some(w => w.status === "ISSUED" || !w.status) && (
            <Card className="border-none shadow-md bg-red-50 dark:bg-red-900/10 border-r-4 border-r-red-500">
              <CardContent className="p-4 flex items-start gap-3">
                <AlertTriangle className="h-5 w-5 text-red-500 shrink-0 mt-1" />
                <div className="flex-1">
                  <p className="font-bold text-red-900 dark:text-red-400 text-sm">تنبيه إداري</p>
                  <p className="text-xs text-red-700 dark:text-red-500/80 mb-2">لديك سجل إنذارات يحتاج إلى مراجعة وتوقيع.</p>
                  <Button variant="link" size="sm" className="p-0 h-auto text-red-600 font-bold" onClick={() => navigate("/my-warnings")}>عرض الإنذارات</Button>
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Right Column: Detailed Tabs Activity */}
        <div className="lg:col-span-2">
          <Tabs defaultValue="activity" className="w-full" onValueChange={setActiveTab}>
            <div className="flex items-center justify-between mb-6 bg-white dark:bg-gray-900 p-2 rounded-2xl shadow-sm">
              <TabsList className="bg-transparent gap-2 h-auto p-0">
                <TabsTrigger
                  value="activity"
                  className="rounded-xl px-5 py-2.5 data-[state=active]:bg-primary data-[state=active]:text-white transition-all font-bold"
                >
                  النشاط الأخير
                </TabsTrigger>
                <TabsTrigger
                  value="requests"
                  className="rounded-xl px-5 py-2.5 data-[state=active]:bg-primary data-[state=active]:text-white transition-all font-bold"
                >
                  الطلبات
                </TabsTrigger>
                <TabsTrigger
                  value="financial"
                  className="rounded-xl px-5 py-2.5 data-[state=active]:bg-primary data-[state=active]:text-white transition-all font-bold"
                >
                  المالية والحوافز
                </TabsTrigger>
              </TabsList>
            </div>

            {/* Recent Activity Tab */}
            <TabsContent value="activity" className="mt-0">
              <Card className="border-none shadow-sm dark:bg-gray-900/50">
                <CardContent className="p-6">
                  <div className="space-y-6">
                    {/* Combine important movements */}
                    {[
                      ...recentLeaves.slice(0, 2).map(l => ({ ...l, category: 'LEAVE', icon: Calendar, color: 'green', title: `طلب إجازة ${l.type}`, date: l.createdAt || l.startDate })),
                      ...permissions.slice(0, 2).map(p => ({ ...p, category: 'PERMISSION', icon: FileText, color: 'yellow', title: `طلب إذن ${p.type === 'OUT' ? 'خروج' : 'تأخير'}`, date: p.createdAt || p.date })),
                      ...advances.slice(0, 2).map(a => ({ ...a, category: 'ADVANCE', icon: DollarSign, color: 'blue', title: 'طلب سلفة', date: a.createdAt })),
                      ...rewards.slice(0, 2).map(r => ({ ...r, category: 'REWARD', icon: Award, color: 'purple', title: r.rewardName || 'مكافأة إضافية', date: r.appliedAt || r.createdAt })),
                    ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
                      .slice(0, 5)
                      .map((item, idx) => (
                        <div key={idx} className="flex gap-4 relative">
                          {idx !== 4 && <div className="absolute top-10 bottom-0 right-[22px] w-[2px] bg-gray-100 dark:bg-gray-800"></div>}
                          <div className={`h-11 w-11 rounded-full bg-${item.color}-50 dark:bg-${item.color}-900/20 flex items-center justify-center shrink-0 border border-${item.color}-100 dark:border-${item.color}-800`}>
                            <item.icon className={`h-5 w-5 text-${item.color}-600 dark:text-${item.color}-400`} />
                          </div>
                          <div className="flex-1 pb-6">
                            <div className="flex justify-between items-start mb-1">
                              <h4 className="font-bold text-gray-900 dark:text-gray-100">
                                {item.title}
                              </h4>
                              <span className="text-[10px] font-bold text-gray-400">
                                {format(new Date(item.date), "d MMMM yyyy", { locale: ar })}
                              </span>
                            </div>
                            <div className="flex items-center gap-3">
                              <Badge className={
                                item.status === "APPROVED" || item.status === "COMPLETED" ? "bg-green-100/50 text-green-700 border-none" :
                                  item.status === "PENDING" ? "bg-yellow-100/50 text-yellow-700 border-none" :
                                    item.status === "REJECTED" ? "bg-red-100/50 text-red-700 border-none" :
                                      "bg-blue-100/50 text-blue-700 border-none"
                              }>
                                {(item.status === "APPROVED" || item.status === "COMPLETED") ? "مكتمل" : item.status === "PENDING" ? "تحت المراجعة" : item.status === "REJECTED" ? "مرفوض" : "نشط"}
                              </Badge>
                              <span className="text-xs text-gray-400">
                                {item.category === 'LEAVE' ? `${item.totalDays} أيام` :
                                  item.category === 'REWARD' ? `القيمة: ${item.calculatedValue} ج.م` :
                                    item.category === 'ADVANCE' ? `القيمة: ${item.amount} ج.م` :
                                      `${item.startTime} - ${item.endTime}`}
                              </span>
                            </div>
                          </div>
                        </div>
                      ))}

                    {recentLeaves.length === 0 && permissions.length === 0 && rewards.length === 0 && (
                      <div className="text-center py-12">
                        <div className="bg-gray-50 dark:bg-gray-800/10 h-16 w-16 rounded-full flex items-center justify-center mx-auto mb-4">
                          <Users className="h-8 w-8 text-gray-300" />
                        </div>
                        <p className="text-gray-400 font-medium">لا يوجد نشاط مسجل مؤخراً</p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </TabsContent>

            {/* Requests Tab */}
            <TabsContent value="requests" className="mt-0">
              <div className="grid gap-6">
                {/* Permissions List */}
                <Card className="border-none shadow-sm">
                  <CardHeader className="flex flex-row items-center justify-between pb-2">
                    <CardTitle className="text-md font-bold">الأذونات (آخر 5)</CardTitle>
                    <Button variant="link" size="sm" onClick={() => navigate("/my-permissions")}>عرض الكل</Button>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      {permissions.map(p => (
                        <div key={p.id} className="flex items-center justify-between p-4 bg-gray-50/50 dark:bg-gray-800/20 rounded-2xl border border-gray-100 dark:border-gray-800">
                          <div className="flex items-center gap-4">
                            <div className="h-10 w-10 bg-yellow-100 dark:bg-yellow-900/20 rounded-xl flex items-center justify-center">
                              <FileText className="h-5 w-5 text-yellow-600" />
                            </div>
                            <div>
                              <p className="font-bold text-gray-900 dark:text-gray-100">{p.type === 'OUT' ? 'إذن خروج' : 'إذن تأخير'}</p>
                              <p className="text-xs text-gray-400">{format(new Date(p.date), "dd/MM/yyyy")} • {p.startTime} - {p.endTime}</p>
                            </div>
                          </div>
                          <Badge className={p.status === 'APPROVED' ? 'bg-green-500' : p.status === 'PENDING' ? 'bg-yellow-500' : 'bg-red-500'}>
                            {p.status === 'APPROVED' ? 'مقبول' : p.status === 'PENDING' ? 'انتظار' : 'مرفوض'}
                          </Badge>
                        </div>
