                        <div key={l.id} className="flex items-center gap-4 p-3 bg-white dark:bg-gray-900 border border-gray-50 dark:border-gray-800 shadow-sm rounded-xl">
                          <div className="h-10 w-10 bg-green-50 dark:bg-green-900/20 text-green-600 rounded-lg flex items-center justify-center shrink-0">
                            <Calendar className="h-5 w-5" />
                          </div>
                          <div className="flex-1">
                            <div className="flex justify-between items-center mb-0.5">
                              <p className="font-bold text-sm">{l.type}</p>
                              <span className="text-[10px] text-gray-400">{l.totalDays} يوم</span>
                            </div>
                            <p className="text-[10px] text-gray-400">{format(new Date(l.startDate), "dd/MM")} - {format(new Date(l.endDate), "dd/MM")}</p>
                          </div>
                          <Badge variant="outline" className={l.status === 'APPROVED' ? 'text-green-600 border-green-200' : 'text-yellow-600 border-yellow-200'}>
                            {l.status === 'APPROVED' ? 'مقبول' : 'انتظار'}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              </div>
            </TabsContent>

            {/* Financial Tab */}
            <TabsContent value="financial" className="mt-0">
              <div className="grid gap-6">
                {/* Latest Rewards */}
                <Card className="border-none shadow-sm bg-gradient-to-br from-white to-purple-50/30 dark:from-gray-900 dark:to-purple-900/5">
                  <CardHeader>
                    <CardTitle className="text-md font-bold flex items-center gap-2">
                      <Award className="h-5 w-5 text-purple-600" />
                      الحوافز والمكافآت
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      {rewards.slice(0, 3).map(r => (
                        <div key={r.id} className="flex items-center justify-between p-4 bg-white/80 dark:bg-gray-900/40 rounded-2xl shadow-sm border border-purple-100 dark:border-purple-900/20">
                          <div>
                            <p className="font-bold text-gray-900 dark:text-gray-100">{r.rewardName}</p>
                            <p className="text-xs text-gray-400">{format(new Date(r.appliedAt || r.createdAt), "dd MMMM yyyy", { locale: ar })}</p>
                          </div>
                          <div className="text-left">
                            <p className="text-lg font-black text-purple-600">+{r.calculatedValue} <span className="text-xs">ج.م</span></p>
                            <Badge className="bg-purple-100 text-purple-700 border-none rounded-full text-[10px]">{r.rewardCategory || "مكافأة أداء"}</Badge>
                          </div>
                        </div>
                      ))}
                      {rewards.length === 0 && (
                        <div className="text-center py-6 text-gray-400">
                          <Award className="h-10 w-10 mx-auto opacity-20 mb-2" />
                          <p className="text-sm">اجتهد لتحصل على مكافأتك الأولى!</p>
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>

                {/* Active Advances */}
                <Card className="border-none shadow-sm">
                  <CardHeader>
                    <CardTitle className="text-md font-bold flex items-center gap-2">
                      <DollarSign className="h-5 w-5 text-green-600" />
                      السلف النشطة
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      {advances.filter(a => a.status === 'APPROVED' && a.remainingBalance > 0).map(a => (
                        <div key={a.id} className="p-4 bg-gray-50 dark:bg-gray-800/20 rounded-2xl">
                          <div className="flex justify-between items-start mb-4">
                            <div>
                              <p className="text-xs text-gray-400 font-bold mb-1 uppercase tracking-tight">إجمالي السلفة</p>
                              <p className="text-xl font-black text-gray-900 dark:text-gray-100">{a.amount.toLocaleString()} ج.م</p>
                            </div>
                            <Badge className="bg-green-100 text-green-700 border-none">نشط</Badge>
                          </div>
                          <div className="space-y-2">
                            <div className="flex justify-between text-xs font-bold mb-1">
                              <span className="text-gray-400">المبلغ المتبقي</span>
                              <span className="text-primary">{a.remainingBalance.toLocaleString()} ج.م</span>
                            </div>
                            <Progress value={((a.amount - a.remainingBalance) / a.amount) * 100} className="h-2 bg-gray-200" />
                            <p className="text-[10px] text-gray-400 text-left mt-2">نظام التقسيط: {a.installmentsCount} أشهر</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>

                {/* Advances History (Brief) */}
                <Card className="border-none shadow-sm">
                  <CardHeader className="flex flex-row items-center justify-between pb-2">
                    <CardTitle className="text-md font-bold text-gray-900 dark:text-gray-100">آخر طلبات السلف</CardTitle>
                    <Button variant="link" size="sm" onClick={() => navigate("/my-advances")}>عرض الكل</Button>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      {advances.slice(0, 3).map(a => (
                        <div key={a.id} className="flex items-center justify-between p-4 bg-gray-50/50 dark:bg-gray-800/20 rounded-2xl border border-gray-100 dark:border-gray-800">
                          <div className="flex items-center gap-4">
                            <div className="h-10 w-10 bg-blue-100 dark:bg-blue-900/20 rounded-xl flex items-center justify-center">
                              <DollarSign className="h-5 w-5 text-blue-600" />
                            </div>
                            <div>
                              <p className="font-bold text-gray-900 dark:text-gray-100">{a.amount.toLocaleString()} ج.م</p>
                              <p className="text-xs text-gray-400">{format(new Date(a.createdAt), "dd/MM/yyyy")}</p>
                            </div>
                          </div>
                          <Badge className={a.status === 'APPROVED' ? 'bg-green-500' : a.status === 'PENDING' ? 'bg-yellow-500' : 'bg-red-500'}>
                            {a.status === 'APPROVED' ? 'مقبول' : a.status === 'PENDING' ? 'انتظار' : 'مرفوض'}
                          </Badge>
                        </div>
                      ))}
                      {advances.length === 0 && <p className="text-center text-gray-400 py-4 text-sm">لا توجد طلبات سلف</p>}
                    </div>
                  </CardContent>
                </Card>
              </div>
            </TabsContent>
          </Tabs>
        </div>
      </div>

      {/* Corporate Culture Section (Placeholder for "WOW" - e.g. Goals or Values) */}
      <Card className="border-none shadow-md bg-white dark:bg-gray-900 border-t-4 border-primary">
        <CardHeader>
          <CardTitle className="text-lg font-bold flex items-center gap-2">
            <TrendingUp className="h-5 w-5 text-primary" />
            أهدافك وتطورك
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid md:grid-cols-3 gap-6">
            <div className="p-4 bg-blue-50/50 dark:bg-blue-900/10 rounded-2xl border border-blue-100/50 dark:border-blue-900/20">
              <div className="flex items-center gap-3 mb-3">
                <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg text-blue-600">
                  <Target className="h-5 w-5" />
                </div>
                <h5 className="font-bold text-gray-900 dark:text-gray-100">تحسين الأداء</h5>
              </div>
              <p className="text-xs text-gray-500 mb-4 line-clamp-2">التركيز على سرعة إنجاز المهام المسندة ورفع الجودة بنسبة 15% خلال هذا الربع.</p>
              <div className="flex items-center justify-between text-[10px] font-bold text-blue-600 mb-1">
                <span>معدل الإنجاز</span>
                <span>75%</span>
              </div>
              <Progress value={75} className="h-1.5 bg-blue-100 dark:bg-blue-900/30" />
            </div>

            <div className="p-4 bg-purple-50/50 dark:bg-purple-900/10 rounded-2xl border border-purple-100/50 dark:border-purple-900/20">
              <div className="flex items-center gap-3 mb-3">
                <div className="p-2 bg-purple-100 dark:bg-purple-900/30 rounded-lg text-purple-600">
                  <Award className="h-5 w-5" />
                </div>
                <h5 className="font-bold text-gray-900 dark:text-gray-100">التدريب المهني</h5>
              </div>
              <p className="text-xs text-gray-500 mb-4 line-clamp-2">إكمال دورة "الإدارة الفعالة للوقت" المتاحة في منصة التعليم الداخلية.</p>
              <div className="flex items-center justify-between text-[10px] font-bold text-purple-600 mb-1">
                <span>معدل الإنجاز</span>
                <span>40%</span>
              </div>
              <Progress value={40} className="h-1.5 bg-purple-100 dark:bg-purple-900/30" />
            </div>

            <div className="p-4 bg-gray-50/50 dark:bg-gray-800/40 rounded-2xl border border-gray-100 dark:border-gray-800 flex flex-col items-center justify-center text-center">
              <Plus className="h-8 w-8 text-gray-300 mb-2 cursor-pointer hover:text-primary transition-colors" />
              <p className="text-xs text-gray-400 font-medium">أضف هدفاً شخصياً جديداً</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Support & Footer */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 py-8 border-t border-gray-100 dark:border-gray-900">
        <p className="text-sm text-gray-400">نظام MaxP لإدارة الموارد البشرية © 2026</p>
        <div className="flex items-center gap-6">
          <Button variant="link" className="text-sm text-gray-400 hover:text-primary p-0 h-auto">مركز المساعدة</Button>
          <Button variant="link" className="text-sm text-gray-400 hover:text-primary p-0 h-auto">سياسة الشركة</Button>
          <Button variant="link" className="text-sm text-gray-400 hover:text-primary p-0 h-auto">الإبلاغ عن مشكلة</Button>
        </div>
      </div>
    </div>
  );
};

export default MyDashboard;

import React, { useState, useEffect } from "react";
import {
  DollarSign,
  Calendar,
  FileText,
  AlertCircle,
  TrendingDown,
  Clock,
  CheckCircle,
  XCircle,
  Info,
  Loader2,
} from "lucide-react";
import api from "../../services/api";

interface Deduction {
  id: string;
  type: string;
  category?: string;
  amount: number;
  reason: string;
  description?: string;
  date: string;
  effectiveMonth: number;
  effectiveYear: number;
  status: string;
  approvedAt?: string;
  rejectedAt?: string;
  rejectionReason?: string;
  appliedToPayroll: boolean;
  notes?: string;
  createdAt: string;
}

const DEDUCTION_TYPES = {
  PENALTY: "غرامة",
  VIOLATION: "مخالفة",
  DAMAGE: "تعويض عن ضرر",
  INSURANCE: "تأمين",
  LOAN_REPAYMENT: "سداد قرض",
  ADVANCE_REPAYMENT: "سداد سلفة",
  TAX: "ضريبة",
  SOCIAL_INSURANCE: "تأمينات اجتماعية",
  ABSENCE: "غياب",
  LATE: "تأخير",
  EARLY_LEAVE: "خروج مبكر",
  OTHER: "أخرى",
};

const DEDUCTION_STATUS = {
  PENDING: {
    label: "في الانتظار",
    color:
      "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400",
    icon: Clock,
  },
  APPROVED: {
    label: "موافق عليه",
    color:
      "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400",
    icon: CheckCircle,
  },
  REJECTED: {
    label: "مرفوض",
    color: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400",
    icon: XCircle,
  },
  APPLIED: {
    label: "تم التطبيق",
    color: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    icon: CheckCircle,
  },
  CANCELLED: {
    label: "ملغي",
    color: "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300",
    icon: XCircle,
  },
};

const MyDeductions: React.FC = () => {
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [filteredDeductions, setFilteredDeductions] = useState<Deduction[]>([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<any>(null);
  const [selectedDeduction, setSelectedDeduction] = useState<Deduction | null>(
    null,
  );
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [filterStatus, setFilterStatus] = useState("");
  const [filterMonth, setFilterMonth] = useState("");
  const [filterYear, setFilterYear] = useState("");

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    filterDeductions();
  }, [deductions, filterStatus, filterMonth, filterYear]);

  const loadData = async () => {
    try {
      setLoading(true);
      const [deductionsRes, statsRes] = await Promise.all([
        api.get("/employee/my-deductions"),
        api.get("/employee/my-deductions/stats"),
      ]);

      if (deductionsRes.data.success) {
        setDeductions(deductionsRes.data.deductions);
      }

      if (statsRes.data.success) {
        setStats(statsRes.data.stats);
      }
    } catch (error) {
      console.error("Error loading deductions:", error);
    } finally {
      setLoading(false);
    }
  };

  const filterDeductions = () => {
    let filtered = [...deductions];

    if (filterStatus) {
      filtered = filtered.filter((d) => d.status === filterStatus);
    }

    if (filterMonth && filterYear) {
      filtered = filtered.filter(
        (d) =>
          d.effectiveMonth === parseInt(filterMonth) &&
          d.effectiveYear === parseInt(filterYear),
      );
    }

    setFilteredDeductions(filtered);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
    }).format(amount);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("ar-EG");
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center">
          <DollarSign className="h-8 w-8 text-blue-600 dark:text-blue-400 ml-3" />
          خصوماتي
        </h1>
        <p className="text-gray-600 dark:text-gray-400 mt-1">
          عرض وتتبع الخصومات المطبقة على راتبك
        </p>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  إجمالي الخصومات
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {stats.total}
                </p>
              </div>
              <TrendingDown className="h-8 w-8 text-blue-600" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  إجمالي المبلغ
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {formatCurrency(parseFloat(stats.totalAmount))}
                </p>
              </div>
              <DollarSign className="h-8 w-8 text-red-600" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  في الانتظار
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {stats.byStatus.find((s: any) => s.status === "PENDING")
                    ?._count || 0}
                </p>
              </div>
              <Clock className="h-8 w-8 text-yellow-600" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  تم التطبيق
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {stats.byStatus.find((s: any) => s.status === "APPLIED")
                    ?._count || 0}
                </p>
              </div>
              <CheckCircle className="h-8 w-8 text-green-600" />
            </div>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              الحالة
            </label>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">الكل</option>
              <option value="PENDING">في الانتظار</option>
              <option value="APPROVED">موافق عليه</option>
              <option value="REJECTED">مرفوض</option>
              <option value="APPLIED">تم التطبيق</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              الشهر
            </label>
            <select
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">الكل</option>
              {Array.from({ length: 12 }, (_, i) => i + 1).map((month) => (
                <option key={month} value={month}>
                  {month}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              السنة
            </label>
            <select
              value={filterYear}
              onChange={(e) => setFilterYear(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">الكل</option>
              {Array.from(
                { length: 5 },
                (_, i) => new Date().getFullYear() - i,
              ).map((year) => (
                <option key={year} value={year}>
                  {year}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Deductions List */}
      <div className="space-y-4">
        {filteredDeductions.length === 0 ? (
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-12 text-center">
            <AlertCircle className="mx-auto h-12 w-12 text-gray-400 mb-4" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
              لا توجد خصومات
            </h3>
            <p className="text-gray-600 dark:text-gray-400">
              لم يتم تسجيل أي خصومات حتى الآن
            </p>
          </div>
        ) : (
          filteredDeductions.map((deduction) => {
            const StatusIcon =
              DEDUCTION_STATUS[
                deduction.status as keyof typeof DEDUCTION_STATUS
              ]?.icon || Info;

            return (
              <div
                key={deduction.id}
                className="bg-white dark:bg-gray-800 rounded-lg shadow hover:shadow-md transition-shadow border dark:border-gray-700"
              >
                <div className="p-6">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center space-x-3 space-x-reverse mb-2">
                        <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                          {
                            DEDUCTION_TYPES[
                              deduction.type as keyof typeof DEDUCTION_TYPES
                            ]
                          }
                        </h3>
                        <span
                          className={`px-2 py-1 rounded-full text-xs font-medium ${DEDUCTION_STATUS[deduction.status as keyof typeof DEDUCTION_STATUS]?.color}`}
                        >
                          <StatusIcon className="h-3 w-3 inline ml-1" />
                          {
                            DEDUCTION_STATUS[
                              deduction.status as keyof typeof DEDUCTION_STATUS
                            ]?.label
                          }
                        </span>
                        {deduction.category && (
                          <span className="px-2 py-1 rounded-full text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300">
                            {deduction.category}
                          </span>
                        )}
                      </div>

                      <p className="text-gray-600 dark:text-gray-400 mb-3">
                        {deduction.reason}
                      </p>

                      <div className="flex items-center space-x-6 space-x-reverse text-sm text-gray-500 dark:text-gray-400">
                        <div className="flex items-center">
                          <DollarSign className="h-4 w-4 ml-1" />
                          <span className="font-medium text-red-600 dark:text-red-400">
                            {formatCurrency(deduction.amount)}
                          </span>
                        </div>
                        <div className="flex items-center">
                          <Calendar className="h-4 w-4 ml-1" />
                          <span>
                            {deduction.effectiveMonth}/{deduction.effectiveYear}
                          </span>
                        </div>
                        <div className="flex items-center">
                          <FileText className="h-4 w-4 ml-1" />
                          <span>{formatDate(deduction.date)}</span>
                        </div>
                      </div>

                      {deduction.rejectionReason && (
                        <div className="mt-3 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-md">
                          <p className="text-sm text-red-800 dark:text-red-400">
                            <strong>سبب الرفض:</strong>{" "}
                            {deduction.rejectionReason}
                          </p>
                        </div>
                      )}

                      {deduction.appliedToPayroll && (
                        <div className="mt-3 p-3 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-md">
                          <p className="text-sm text-blue-800 dark:text-blue-400">
                            <CheckCircle className="h-4 w-4 inline ml-1" />
                            تم تطبيق هذا الخصم على الراتب
                          </p>
                        </div>
                      )}
                    </div>

                    <button
                      onClick={() => {
                        setSelectedDeduction(deduction);
                        setShowDetailsModal(true);
                      }}
                      className="text-blue-600 hover:text-blue-800 dark:text-blue-400 text-sm font-medium"
                    >
                      عرض التفاصيل
                    </button>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Details Modal */}
      {showDetailsModal && selectedDeduction && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 dark:bg-gray-900 dark:bg-opacity-75 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border border-gray-200 dark:border-gray-700 w-full max-w-2xl shadow-lg rounded-md bg-white dark:bg-gray-800">
            <div className="mt-3">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                  تفاصيل الخصم
                </h3>
                <button
                  onClick={() => setShowDetailsModal(false)}
                  className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                >
                  <XCircle className="h-6 w-6" />
                </button>
              </div>

              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      النوع
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {
                        DEDUCTION_TYPES[
                          selectedDeduction.type as keyof typeof DEDUCTION_TYPES
                        ]
                      }
                    </p>
                  </div>

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      المبلغ
                    </p>
                    <p className="text-base font-medium text-red-600 dark:text-red-400">
                      {formatCurrency(selectedDeduction.amount)}
                    </p>
                  </div>

                  {selectedDeduction.category && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        التصنيف
                      </p>
                      <p className="text-base font-medium text-gray-900 dark:text-white">
                        {selectedDeduction.category}
                      </p>
                    </div>
                  )}

                  <div className="col-span-2">
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      السبب
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {selectedDeduction.reason}
                    </p>
                  </div>

                  {selectedDeduction.description && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        الوصف
                      </p>
                      <p className="text-base text-gray-900 dark:text-white">
                        {selectedDeduction.description}
                      </p>
                    </div>
                  )}

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      التاريخ
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {formatDate(selectedDeduction.date)}
                    </p>
                  </div>

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      التاريخ الفعلي
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {selectedDeduction.effectiveMonth}/
                      {selectedDeduction.effectiveYear}
                    </p>
                  </div>

                  <div className="col-span-2">
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      الحالة
                    </p>
                    <span
                      className={`inline-block px-3 py-1 rounded-full text-sm font-medium ${DEDUCTION_STATUS[selectedDeduction.status as keyof typeof DEDUCTION_STATUS]?.color}`}
                    >
                      {
                        DEDUCTION_STATUS[
                          selectedDeduction.status as keyof typeof DEDUCTION_STATUS
                        ]?.label
                      }
                    </span>
                  </div>

                  {selectedDeduction.approvedAt && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        تاريخ الموافقة
                      </p>
                      <p className="text-base text-green-600 dark:text-green-400">
                        {formatDate(selectedDeduction.approvedAt)}
                      </p>
                    </div>
                  )}

                  {selectedDeduction.rejectionReason && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        سبب الرفض
                      </p>
                      <p className="text-base text-red-600 dark:text-red-400">
                        {selectedDeduction.rejectionReason}
                      </p>
                    </div>
                  )}

                  {selectedDeduction.appliedToPayroll && (
                    <div className="col-span-2">
                      <div className="p-3 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-md">
                        <p className="text-sm text-blue-800 dark:text-blue-400">
                          <CheckCircle className="h-4 w-4 inline ml-1" />
                          تم تطبيق هذا الخصم على الراتب
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              <div className="mt-6 flex justify-end">
                <button
                  onClick={() => setShowDetailsModal(false)}
                  className="px-4 py-2 bg-gray-300 dark:bg-gray-600 text-gray-700 dark:text-gray-200 rounded-md hover:bg-gray-400 dark:hover:bg-gray-500"
                >
                  إغلاق
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MyDeductions;

import React, { useState, useEffect } from "react";
import {
    TrendingUp,
    Calendar,
    FileText,
    Clock,
    CheckCircle,
    XCircle,
    Info,
    Loader2,
    Award,
    ArrowRight,
    DollarSign,
    Briefcase
} from "lucide-react";
import api from "../../services/api";
import { useTranslation } from "react-i18next";

interface Promotion {
    id: string;
    fromPositionId?: string;
    toPositionId: string;
    fromPositionName?: string;
    toPositionName: string;
    fromSalary?: number;
    toSalary?: number;
    promotionDate: string;
    effectiveDate: string;
    reason: string;
    status: string;
    notes?: string;
    createdAt: string;
    fromPosition?: { title: string };
    toPosition?: { title: string };
}

const PROMOTION_STATUS = {
    PENDING: {
        label: "في الانتظار",
        color: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400",
        icon: Clock,
    },
    APPROVED: {
        label: "معتمد",
        color: "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400",
        icon: CheckCircle,
    },
    REJECTED: {
        label: "مرفوض",
        color: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400",
        icon: XCircle,
    }
};

const MyPromotions: React.FC = () => {
    const { t } = useTranslation();
    const [promotions, setPromotions] = useState<Promotion[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedPromotion, setSelectedPromotion] = useState<Promotion | null>(null);
    const [showDetailsModal, setShowDetailsModal] = useState(false);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        try {
            setLoading(true);
            const res = await api.get("/hr/my-promotions");
            if (res.data.success) {
                setPromotions(res.data.promotions);
            }
        } catch (error) {
            console.error("Error loading promotions:", error);
        } finally {
            setLoading(false);
        }
    };

    const formatCurrency = (amount?: number) => {
        if (amount === undefined || amount === null) return "—";
        return new Intl.NumberFormat("ar-EG", {
            style: "currency",
            currency: "EGP",
        }).format(amount);
    };

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString("ar-EG");
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
            </div>
        );
    }

    return (
        <div className="space-y-6 p-6">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center">
                        <Award className="h-8 w-8 text-indigo-600 dark:text-indigo-400 ml-3" />
                        ترقياتي ومساري الوظيفي
                    </h1>
                    <p className="text-gray-600 dark:text-gray-400 mt-1">
                        سجل الترقيات والتغييرات في المنصب والمستوى الوظيفي
                    </p>
                </div>
            </div>

            {/* Promotions List */}
            <div className="space-y-4">
                {promotions.length === 0 ? (
                    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-12 text-center">
                        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 mb-4">
                            <TrendingUp className="h-8 w-8" />
                        </div>
                        <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                            لا يوجد سجل ترقيات حتى الآن
                        </h3>
                        <p className="text-gray-600 dark:text-gray-400 max-w-sm mx-auto">
                            سيظهر هنا تاريخك الوظيفي وأي ترقيات تحصل عليها في المستقبل.
                        </p>
                    </div>
                ) : (
                    promotions.map((promotion) => {
                        const status = (PROMOTION_STATUS as any)[promotion.status] || PROMOTION_STATUS.PENDING;
                        const StatusIcon = status.icon;

                        return (
                            <div
                                key={promotion.id}
                                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden hover:shadow-md transition-shadow"
                            >
                                <div className="p-6">
                                    <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                                        <div className="flex-1 space-y-4">
                                            <div className="flex flex-wrap items-center gap-2">
                                                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${status.color}`}>
                                                    <StatusIcon className="h-3 w-3 ml-1" />
                                                    {status.label}
                                                </span>
                                                <span className="text-sm text-gray-500 dark:text-gray-400 flex items-center">
                                                    <Clock className="h-4 w-4 ml-1" />
                                                    تم في {formatDate(promotion.promotionDate)}
                                                </span>
                                            </div>

                                            <div className="flex flex-col md:flex-row md:items-center gap-4 py-2">
                                                <div className="flex-1 min-w-0">
                                                    <p className="text-xs text-gray-500 dark:text-gray-400 mb-1 uppercase tracking-wider">المنصب السابق</p>
                                                    <div className="flex items-center">
                                                        <div className="w-8 h-8 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center ml-2">
                                                            <Briefcase className="h-4 w-4 text-gray-500" />
                                                        </div>
                                                        <span className="text-lg font-semibold text-gray-500 dark:text-gray-400 line-through">
                                                            {promotion.fromPositionName || promotion.fromPosition?.title || "لا يوجد منصب سابق"}
                                                        </span>
                                                    </div>
                                                </div>

                                                <div className="flex justify-center md:rotate-0 rotate-90 my-2 md:my-0">
                                                    <ArrowRight className="h-6 w-6 text-indigo-500" />
                                                </div>

                                                <div className="flex-1 min-w-0">
                                                    <p className="text-xs text-indigo-500 dark:text-indigo-400 mb-1 uppercase tracking-wider">المنصب الجديد</p>
                                                    <div className="flex items-center">
                                                        <div className="w-8 h-8 rounded-lg bg-indigo-50 dark:bg-indigo-900/30 flex items-center justify-center ml-2 font-bold text-indigo-600">
                                                            <Award className="h-4 w-4" />
                                                        </div>
                                                        <span className="text-lg font-bold text-gray-900 dark:text-white">
                                                            {promotion.toPositionName || promotion.toPosition?.title}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex flex-wrap items-center gap-6 text-sm">
                                                <div className="flex items-center text-gray-600 dark:text-gray-400">
                                                    <DollarSign className="h-4 w-4 ml-1 text-green-600" />
                                                    <span>الراتب الجديد: </span>
                                                    <span className="font-bold text-gray-900 dark:text-white mr-1">
                                                        {formatCurrency(promotion.toSalary)}
                                                    </span>
                                                </div>
                                                <div className="flex items-center text-gray-600 dark:text-gray-400">
                                                    <Calendar className="h-4 w-4 ml-1 text-blue-500" />
                                                    <span>تاريخ السريان: </span>
                                                    <span className="font-medium mr-1">{formatDate(promotion.effectiveDate)}</span>
                                                </div>
                                            </div>

                                            <div className="bg-gray-50 dark:bg-gray-900/50 rounded-lg p-3">
                                                <p className="text-sm text-gray-600 dark:text-gray-300">
                                                    <span className="font-semibold ml-1">السبب:</span>
                                                    {promotion.reason}
                                                </p>
                                            </div>
                                        </div>

                                        <div className="lg:border-r lg:pr-6 border-gray-100 dark:border-gray-700 flex flex-col items-stretch">
                                            <button
                                                onClick={() => {
                                                    setSelectedPromotion(promotion);
                                                    setShowDetailsModal(true);
                                                }}
                                                className="px-4 py-2 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-lg text-sm font-medium transition-colors"
                                            >
                                                عرض التفاصيل
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>

            {/* Details Modal */}
            {showDetailsModal && selectedPromotion && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
                        <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex items-center justify-between">
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center">
                                <Info className="h-6 w-6 text-indigo-500 ml-2" />
                                تفاصيل الترقية
                            </h2>
                            <button
                                onClick={() => setShowDetailsModal(false)}
                                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors"
                            >
                                <XCircle className="h-6 w-6 text-gray-400" />
                            </button>
                        </div>

                        <div className="p-6 max-h-[70vh] overflow-y-auto space-y-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">المنصب الجديد</p>
                                    <p className="text-lg font-bold text-gray-900 dark:text-white">
                                        {selectedPromotion.toPositionName || selectedPromotion.toPosition?.title}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">المنصب السابق</p>
                                    <p className="text-lg font-medium text-gray-500 dark:text-gray-400 line-through">
                                        {selectedPromotion.fromPositionName || selectedPromotion.fromPosition?.title || "—"}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">الراتب الجديد</p>
                                    <p className="text-lg font-bold text-green-600 dark:text-green-400">
                                        {formatCurrency(selectedPromotion.toSalary)}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">الراتب السابق</p>
                                    <p className="text-lg font-medium text-gray-500 dark:text-gray-400">
                                        {formatCurrency(selectedPromotion.fromSalary)}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">تاريخ الترقية</p>
                                    <p className="font-medium">{formatDate(selectedPromotion.promotionDate)}</p>
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">تاريخ السريان الفعلي</p>
                                    <p className="font-medium text-indigo-600 dark:text-indigo-400">
                                        {formatDate(selectedPromotion.effectiveDate)}
                                    </p>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <div className="p-4 bg-gray-50 dark:bg-gray-900/50 rounded-xl">
                                    <p className="text-xs text-gray-500 uppercase tracking-widest mb-2 font-bold">السبب</p>
                                    <p className="text-gray-900 dark:text-white leading-relaxed">
                                        {selectedPromotion.reason}
                                    </p>
                                </div>

                                {selectedPromotion.notes && (
                                    <div className="p-4 bg-blue-50/50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-900/30 rounded-xl">
                                        <p className="text-xs text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-2 font-bold">ملاحظات إضافية</p>
                                        <p className="text-gray-900 dark:text-white leading-relaxed italic">
                                            {selectedPromotion.notes}
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="p-6 bg-gray-50 dark:bg-gray-900/50 border-t border-gray-100 dark:border-gray-700 flex justify-end">
