                                        </div>
                                        {selectedTraining.endDate && (
                                            <div className="space-y-1">
                                                <p className="text-xs font-bold text-gray-400 uppercase">تاريخ الانتهاء</p>
                                                <p className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                                    <Calendar className="w-4 h-4 text-purple-400" />
                                                    {new Date(selectedTraining.endDate).toLocaleDateString("ar-EG", {
                                                        day: "numeric", month: "long", year: "numeric"
                                                    })}
                                                </p>
                                            </div>
                                        )}
                                    </div>

                                    <div className="grid grid-cols-2 mt-4 gap-4 p-4 rounded-xl bg-white shadow-sm ring-1 ring-gray-100">
                                        {selectedTraining.duration && (
                                            <div className="space-y-1">
                                                <p className="text-xs font-bold text-gray-400 uppercase">المدة</p>
                                                <p className="text-xl font-black text-gray-700 flex items-center gap-2">
                                                    <Clock className="w-5 h-5 text-indigo-400" />
                                                    {selectedTraining.duration} ساعة
                                                </p>
                                            </div>
                                        )}
                                        {selectedTraining.cost ? (
                                            <div className="space-y-1">
                                                <p className="text-xs font-bold text-gray-400 uppercase">التكلفة</p>
                                                <p className="text-xl font-black text-emerald-600 flex items-center gap-2">
                                                    <DollarSign className="w-5 h-5" />
                                                    {selectedTraining.cost.toLocaleString()}
                                                    <span className="text-xs">EGP</span>
                                                </p>
                                            </div>
                                        ) : (
                                            <div />
                                        )}
                                    </div>

                                    <div className="grid grid-cols-2 mt-4 gap-4 p-4 rounded-xl bg-white shadow-sm ring-1 ring-gray-100">
                                        <div className="space-y-1">
                                            <p className="text-xs font-bold text-gray-400 uppercase">التقييم (النتيجة)</p>
                                            {selectedTraining.score ? (
                                                <p className="text-xl font-black text-amber-500 flex items-center gap-2">
                                                    <Award className="w-5 h-5" />
                                                    %{selectedTraining.score}
                                                </p>
                                            ) : (
                                                <p className="text-sm font-medium text-gray-400">لم يتم التقييم</p>
                                            )}
                                        </div>
                                        <div className="space-y-1">
                                            <p className="text-xs font-bold text-gray-400 uppercase">حالة التدريب</p>
                                            <div className="mt-1">
                                                <span className={`px-3 py-1.5 rounded-lg text-xs font-black border flex items-center gap-2 w-fit ${statusConfig[selectedTraining.status]?.color || "bg-gray-100 text-gray-700"}`}>
                                                    {statusConfig[selectedTraining.status]?.icon}
                                                    {statusConfig[selectedTraining.status]?.label || selectedTraining.status}
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                    {selectedTraining.description && (
                                        <div className="p-4 rounded-xl bg-purple-50/50 border border-purple-100">
                                            <p className="text-xs font-bold text-purple-400 mb-2 flex items-center gap-2 uppercase">
                                                <FileText className="w-4 h-4" /> التفاصيل الإضافية والوصف
                                            </p>
                                            <p className="text-sm text-gray-700 leading-relaxed font-medium">
                                                {selectedTraining.description}
                                            </p>
                                        </div>
                                    )}

                                    <div className="pt-4 flex justify-end">
                                        <Button
                                            onClick={() => setSelectedTraining(null)}
                                            className="bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold px-8 rounded-xl"
                                        >
                                            إغلاق
                                        </Button>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default MyTraining;

import React, { useState, useEffect } from "react";
import {
    AlertTriangle,
    ClipboardList,
    Calendar,
    Clock,
    CheckCircle2,
    AlertCircle,
    FileText,
    Loader2,
    Info,
    ShieldAlert,
    Eye,
} from "lucide-react";
import api from "../../services/api";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "../../components/ui/dialog";
import { Badge } from "../../components/ui/badge";
import { Button } from "../../components/ui/button";
import { toast } from "react-hot-toast";
import { motion, AnimatePresence } from "framer-motion";
import { useDateFormat } from "../../hooks/useDateFormat";

interface Warning {
    id: string;
    title: string;
    description: string;
    severity: "low" | "medium" | "major" | "critical";
    type: string;
    incidentDate: string;
    actionTaken?: string;
    acknowledgedAt?: string;
    createdAt: string;
}

const severityConfig: Record<string, { label: string; color: string; icon: any }> = {
    low: {
        label: "تنبيه بسيط",
        color: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300 border-blue-200 dark:border-blue-800",
        icon: Info,
    },
    medium: {
        label: "تنبيه متوسط",
        color: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300 border-yellow-200 dark:border-yellow-800",
        icon: AlertCircle,
    },
    major: {
        label: "إنذار جسيم",
        color: "bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300 border-orange-200 dark:border-orange-800",
        icon: AlertTriangle,
    },
    critical: {
        label: "إنذار خطير جداً",
        color: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300 border-red-200 dark:border-red-800",
        icon: ShieldAlert,
    },
};

const MyWarnings: React.FC = () => {
    const { formatDate } = useDateFormat();
    const [warnings, setWarnings] = useState<Warning[]>([]);
    const [loading, setLoading] = useState(true);
    const [acknowledgingId, setAcknowledgingId] = useState<string | null>(null);
    const [selectedWarning, setSelectedWarning] = useState<Warning | null>(null);

    const fetchWarnings = async () => {
        try {
            setLoading(true);
            const response = await api.get("/hr/warnings/my-history");
            setWarnings(response.data.warnings || []);
        } catch (error) {
            console.error("Error fetching warnings:", error);
            toast.error("فشل في تحميل سجل الإنذارات");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchWarnings();
    }, []);

    const handleAcknowledge = async (id: string) => {
        try {
            setAcknowledgingId(id);
            const response = await api.post(`/hr/warnings/${id}/acknowledge`);
            if (response.data.success) {
                toast.success("تم تأكيد الاستلام بنجاح");
                setWarnings((prev) =>
                    prev.map((w) =>
                        w.id === id ? { ...w, acknowledgedAt: new Date().toISOString() } : w
                    )
                );
            }
        } catch (error) {
            console.error("Error acknowledging warning:", error);
            toast.error("فشل في تأكيد الاستلام");
        } finally {
            setAcknowledgingId(null);
        }
    };

    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.1,
            },
        },
    };

    const cardVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: { opacity: 1, y: 0 },
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px]">
                <Loader2 className="h-12 w-12 animate-spin text-blue-600 mb-4" />
                <p className="text-gray-500 font-medium animate-pulse">جاري تحميل سجل الإنذارات...</p>
            </div>
        );
    }

    return (
        <div className="max-w-5xl mx-auto space-y-8 p-4 sm:p-6 lg:p-8" dir="rtl">
            {/* Header Section */}
            <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-red-600 to-rose-700 p-8 text-white shadow-xl shadow-red-200/50 dark:shadow-none">
                <div className="relative z-10 flex flex-col md:flex-row md:items-center md:justify-between gap-6">
                    <div className="space-y-2">
                        <h1 className="text-3xl font-extrabold flex items-center gap-3">
                            <ShieldAlert className="h-10 w-10 text-white/90" />
