      console.error("فشل في تحديث المحادثة:", error);
    }
  }, [
    selectedConversation,
    companyId,
    markAsDone,
    activeTab,
    debouncedLoadConversations,
  ]);

  const handleTogglePriority = useCallback(async () => {
    if (!selectedConversation || !companyId) return;
    try {
      await togglePriority(
        selectedConversation.id,
        !selectedConversation.priority,
        companyId,
      );
      debouncedLoadConversations(activeTab);
    } catch (error) {
      console.error("فشل في تحديث الأولوية:", error);
    }
  }, [
    selectedConversation,
    companyId,
    togglePriority,
    activeTab,
    debouncedLoadConversations,
  ]);

  // Tags handler
  const handleTagsChange = useCallback(
    async (tags: string[]) => {
      if (!selectedConversation || !companyId) return;
      try {
        await addTags(selectedConversation.id, tags, companyId);
        debouncedLoadConversations(activeTab);
      } catch (error) {
        console.error("فشل في تحديث التصنيفات:", error);
      }
    },
    [
      selectedConversation,
      companyId,
      addTags,
      activeTab,
      debouncedLoadConversations,
    ],
  );

  // Delete message handler
  const handleDeleteMessage = useCallback(
    async (messageId: string) => {
      if (!selectedConversation) return;
      if (!window.confirm("هل أنت متأكد من حذف هذه الرسالة؟")) return;

      try {
        await deleteMessage(selectedConversation.id, messageId);
        loadMessages(selectedConversation.id); // Reload to reflect deletion
      } catch (error) {
        alert("فشل في حذف الرسالة");
      }
    },
    [selectedConversation, deleteMessage, loadMessages],
  );

  // Forward message request handler
  const handleForwardRequest = useCallback((message: any) => {
    setMessageToForward(message);
    setForwardModalOpen(true);
  }, []);

  // Execute forward handler
  const handleForward = useCallback(
    async (targetConversationId: string) => {
      if (!messageToForward || !companyId) return;

      try {
        await forwardMessage(targetConversationId, messageToForward, companyId);
        alert("✅ تم إعادة توجيه الرسالة بنجاح");
        // Optional: Move to the target conversation
        // selectConversation(conversations.find(c => c.id === targetConversationId));
      } catch (error) {
        alert("فشل في إعادة توجيه الرسالة");
      }
    },
    [messageToForward, companyId, forwardMessage],
  );

  // Star message handler
  const handleStarMessage = useCallback(
    async (messageId: string) => {
      if (!selectedConversation) return;
      try {
        await toggleMessageStar(selectedConversation.id, messageId);
        // Optimistic update or reload
        loadMessages(selectedConversation.id);
      } catch (error) {
        console.error("Failed to star message", error);
      }
    },
    [selectedConversation, toggleMessageStar, loadMessages],
  );

  // Reaction handler
  const handleMessageReaction = useCallback(
    async (messageId: string, reaction: string) => {
      if (!selectedConversation) return;
      try {
        await toggleMessageReaction(
          selectedConversation.id,
          messageId,
          reaction,
        );
        loadMessages(selectedConversation.id);
      } catch (error) {
        console.error("Failed to update reaction", error);
      }
    },
    [selectedConversation, toggleMessageReaction, loadMessages],
  );

  // Reply handler
  const handleReplyToMessage = useCallback((message: any) => {
    setReplyToMessage(message);
    // Focus input?
  }, []);

  const handleCancelReply = useCallback(() => {
    setReplyToMessage(null);
  }, []);

  // Snooze handler
  const handleSnoozeConfirm = useCallback(
    async (until: Date) => {
      if (!selectedConversation || !companyId) return;
      try {
        await snoozeConversation(selectedConversation.id, until, companyId);
        setSnoozeModalOpen(false);
        debouncedLoadConversations(activeTab);
        alert("✅ تم تأجيل المحادثة بنجاح");
      } catch (error) {
        alert("فشل في تأجيل المحادثة");
      }
    },
    [
      selectedConversation,
      companyId,
      snoozeConversation,
      activeTab,
      debouncedLoadConversations,
    ],
  );

  // AI Toggle Handler
  const handleToggleAI = useCallback(
    async (enabled: boolean) => {
      if (!selectedConversation || !companyId) {
        return;
      }
      try {
        await toggleAI(selectedConversation.id, enabled);
        // Optimistic update or reload
        debouncedLoadConversations(activeTab); // Reload to get fresh state including metadata
      } catch (error: any) {
        alert("فشل في تحديث حالة الذكاء الاصطناعي");
      }
    },
    [
      selectedConversation,
      companyId,
      toggleAI,
      activeTab,
      debouncedLoadConversations,
    ],
  );

  // AI Typing State
  const [isAITyping, setIsAITyping] = useState(false);
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // 🆕 Sound & Notifications Functions (defined before Socket.IO useEffect)
  const playNotificationSound = useCallback(() => {
    if (!soundEnabled) return;
    socketService.playNotificationSound();
  }, [soundEnabled]);

  const showBrowserNotification = useCallback(
    (title: string, body: string, icon?: string) => {
      if (!notificationsEnabled) return;
      if (isBrowserPushActive()) return;

      if ("Notification" in window && Notification.permission === "granted") {
        new Notification(title, {
          body,
          icon: icon || "/favicon.ico",
          tag: "new-message",
          requireInteraction: false,
          silent: false,
        });
      } else if (
        "Notification" in window &&
        Notification.permission !== "denied"
      ) {
        Notification.requestPermission().then((permission) => {
          if (permission === "granted") {
            new Notification(title, {
              body,
              icon: icon || "/favicon.ico",
              tag: "new-message",
            });
          }
        });
      }
    },
    [notificationsEnabled],
  );

  // Socket.IO
  // 🔧 FIX: Use ref to track activeTab for socket handler to avoid stale closure
  const activeTabRef = useRef<InboxTab>(activeTab);
  useEffect(() => {
    activeTabRef.current = activeTab;
  }, [activeTab]);

  useEffect(() => {
    if (!socket || !isConnected) return;

    const handleNewMessage = (data: any) => {
      if (
        selectedConversation &&
        data.conversationId === selectedConversation.id
      ) {
        addMessage(data);
        // Stop typing indicator when message arrives
        setIsAITyping(false);
        if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      }

      // 🆕 Play sound and show notification for customer messages
      if (data.isFromCustomer) {
        playNotificationSound();
        if (
          selectedConversation &&
          data.conversationId === selectedConversation.id
        ) {
          // Don't show notification if conversation is already open
        } else {
          showBrowserNotification(
            `رسالة جديدة من ${data.customerName || "عميل"}`,
            data.content?.substring(0, 50) || "رسالة جديدة",
          );
        }
      }

      // 🔧 OPTIMIZED: Use debounced loadConversations to prevent excessive API calls
      debouncedLoadConversations(activeTabRef.current);
    };

    const handleAITyping = (data: {
      conversationId: string;
      isTyping: boolean;
    }) => {
      if (
        selectedConversation &&
        data.conversationId === selectedConversation.id
      ) {
        setIsAITyping(data.isTyping);

        // Auto-hide after 15 seconds if no "stop" event received (safety net)
        if (data.isTyping) {
          if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
          typingTimeoutRef.current = setTimeout(() => {
            setIsAITyping(false);
          }, 15000);
        }
      }
    };

    socket.on("new_message", handleNewMessage);
    socket.on("ai_typing", handleAITyping);

    // 🆕 Handle read receipts - update message status to 'read'
    const handleMessagesRead = (data: {
      conversationId: string;
      watermark: number;
    }) => {
      if (selectedConversation?.id === data.conversationId) {
        // Update all messages sent before watermark to 'read' status
        markMessagesAsRead(data.watermark);
        console.log(
          "👁️ [READ-RECEIPT] Messages marked as read up to:",
          new Date(data.watermark),
        );
      }
    };

    socket.on("messages_read", handleMessagesRead);

    return () => {
      socket.off("new_message", handleNewMessage);
      socket.off("ai_typing", handleAITyping);
      socket.off("messages_read", handleMessagesRead);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      if (loadConversationsTimeoutRef.current)
        clearTimeout(loadConversationsTimeoutRef.current);
    };
  }, [
    socket,
    isConnected,
    selectedConversation,
    addMessage,
    debouncedLoadConversations,
    playNotificationSound,
    showBrowserNotification,
    markMessagesAsRead,
  ]);

  // Fetch post details when conversation is selected
  const fetchPostDetails = useCallback(
    async (conversationId: string) => {
      try {
        const response = await apiClient.get(
          `/conversations/${conversationId}/post-details`,
        );

        if (response.data?.success && response.data?.data) {
          const postDetails = response.data.data;

          // Update selectedConversation with post details
          updateSelectedConversation({ postDetails });
        }
      } catch (error: any) {
        // Silently fail if 404 (post details not found) - it's optional
        if (error.response?.status !== 404) {
          console.error("Error fetching post details:", error);
        }
      }
    },
    [updateSelectedConversation],
  );

  // Fetch post details when conversation with postId is selected
  useEffect(() => {
    if (selectedConversation?.postId && !selectedConversation?.postDetails) {
      fetchPostDetails(selectedConversation.id);
    }
  }, [
    selectedConversation?.id,
    selectedConversation?.postId,
    selectedConversation?.postDetails,
    fetchPostDetails,
  ]);

  // 🆕 Load messages for search when search query changes
  useEffect(() => {
    if (!debouncedSearchQuery || debouncedSearchQuery.trim() === "") {
      return;
    }

    const searchLower = debouncedSearchQuery.toLowerCase().trim();

    // Find conversations that match search in name or last message
    const matchingConversations = conversations.filter((conv) => {
      const matchesName = conv.customerName.toLowerCase().includes(searchLower);
      const matchesMessage = conv.lastMessage
        .toLowerCase()
        .includes(searchLower);
      return matchesName || matchesMessage;
    });

    // Load messages for matching conversations that don't have messages loaded yet
    matchingConversations.forEach((conv) => {
      // Check if messages are already loaded
      if (!conversationMessages.has(conv.id)) {
        // Also check if it's the selected conversation with messages
        if (selectedConversation?.id === conv.id && messages.length > 0) {
          // Store current messages (convert to InboxMessage format)
          const inboxMessages: InboxMessage[] = messages.map((msg) => ({
            id: msg.id,
            content: msg.content,
            senderId: msg.senderId,
            senderName: msg.senderName,
            timestamp: msg.timestamp,
            type: msg.type as InboxMessage["type"],
            isFromCustomer: msg.isFromCustomer,
            status: msg.status as InboxMessage["status"],
            conversationId: msg.conversationId,
            fileUrl: msg.fileUrl,
            fileName: msg.fileName,
            fileSize: msg.fileSize,
            isAiGenerated: msg.isAiGenerated,
            metadata: msg.metadata,
            attachments: msg.attachments,
          }));
          setConversationMessages((prev) => {
            const newMap = new Map(prev);
            newMap.set(conv.id, inboxMessages);
            return newMap;
          });
        } else {
          // Load messages for this conversation
          loadAllMessagesForConversation(conv.id);
        }
      }
    });
  }, [
    debouncedSearchQuery,
    conversations,
    conversationMessages,
    selectedConversation,
    messages,
    loadAllMessagesForConversation,
  ]);

  // 🆕 Block Customer Functions
  const checkBlockStatus = useCallback(async () => {
    if (!selectedConversation?.pageId || !selectedConversation?.customerId) {
      setIsBlocked(false);
      return;
    }

    try {
      setCheckingBlockStatus(true);
      const status = await apiService.checkCustomerBlockStatus(
        selectedConversation.customerId,
        selectedConversation.pageId,
      );
      setIsBlocked(status.isBlocked);
    } catch (error) {
      console.error("Error checking block status:", error);
      setIsBlocked(false);
    } finally {
      setCheckingBlockStatus(false);
    }
  }, [selectedConversation?.pageId, selectedConversation?.customerId]);

  const handleBlockCustomer = useCallback(async () => {
    if (!selectedConversation?.pageId || !selectedConversation?.customerId) {
      alert("معرف الصفحة أو العميل غير متوفر");
      return;
    }

    try {
      setBlocking(true);
      await apiService.blockCustomerOnPage(
        selectedConversation.customerId,
        selectedConversation.pageId,
        blockReason || undefined,
      );
      setIsBlocked(true);
      setShowBlockModal(false);
      setBlockReason("");
      alert("تم حظر العميل على الصفحة بنجاح");
    } catch (error: any) {
      alert(error.message || "فشل حظر العميل");
    } finally {
      setBlocking(false);
    }
  }, [
    selectedConversation?.pageId,
    selectedConversation?.customerId,
    blockReason,
  ]);

  const handleUnblockCustomer = useCallback(async () => {
    if (!selectedConversation?.pageId || !selectedConversation?.customerId) {
      alert("معرف الصفحة أو العميل غير متوفر");
      return;
    }

    if (!window.confirm("هل أنت متأكد من إلغاء حظر هذا العميل على الصفحة؟")) {
      return;
    }

    try {
      setBlocking(true);
      await apiService.unblockCustomerOnPage(
        selectedConversation.customerId,
        selectedConversation.pageId,
      );
      setIsBlocked(false);
      alert("تم إلغاء حظر العميل بنجاح");
    } catch (error: any) {
      alert(error.message || "فشل إلغاء حظر العميل");
    } finally {
      setBlocking(false);
    }
  }, [selectedConversation?.pageId, selectedConversation?.customerId]);

  // Check block status when conversation changes
  useEffect(() => {
    if (selectedConversation?.pageId && selectedConversation?.customerId) {
      checkBlockStatus();
    } else {
      setIsBlocked(false);
    }
  }, [
    selectedConversation?.id,
    selectedConversation?.pageId,
    selectedConversation?.customerId,
    checkBlockStatus,
  ]);

  // Calculate which customer messages have been replied to - OPTIMIZED VERSION
  const repliedMessages = useMemo((): Set<string> => {
    const repliedSet = new Set<string>();
    if (messages.length === 0) return repliedSet;

    // 🔧 OPTIMIZED: Single pass algorithm - more efficient than nested loops
    // Sort messages by timestamp once
    const sortedMessages = [...messages].sort((a, b) => {
      const timeA = new Date(a.timestamp).getTime();
      const timeB = new Date(b.timestamp).getTime();
      return timeA - timeB;
    });

    // Track the last reply timestamp
    let lastReplyTime = 0;

    // Single pass: iterate backwards to mark all customer messages before a reply
    for (let i = sortedMessages.length - 1; i >= 0; i--) {
      const msg = sortedMessages[i];
      if (!msg) continue; // Safety check

      const msgTime = new Date(msg.timestamp).getTime();

      if (!msg.isFromCustomer) {
        // Found a reply - update last reply time
        lastReplyTime = Math.max(lastReplyTime, msgTime);
      } else if (lastReplyTime > 0 && msgTime < lastReplyTime) {
        // This customer message is before the last reply, so it's been replied to
        repliedSet.add(msg.id);
      }
    }

    return repliedSet;
  }, [messages]);

  // إزالة padding و overflow من parent main element في Layout
  useEffect(() => {
    const mainElement = document.querySelector("main");
    if (mainElement) {
      // حفظ الـ classes الأصلية
      const originalClasses = mainElement.className;
      // إزالة padding و overflow وإضافة overflow-hidden و h-full
      mainElement.classList.remove("p-6", "overflow-y-auto");
      mainElement.classList.add("p-0", "overflow-hidden", "flex-1", "h-full");

      return () => {
        // استعادة الـ classes الأصلية عند إغلاق الصفحة
        mainElement.className = originalClasses;
      };
    }
    return undefined;
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return undefined;

    const updateViewportMode = () => {
      setIsMobileViewport(window.innerWidth < 768);
      setIsWideDesktop(window.innerWidth >= 1280);
    };

    updateViewportMode();
    window.addEventListener("resize", updateViewportMode);

    return () => {
      window.removeEventListener("resize", updateViewportMode);
    };
  }, []);

  useEffect(() => {
    if (selectedConversation && window.innerWidth < 768) {
      setShowSidebar(false);
    }

    if (!selectedConversation) {
      setShowProfilePanel(false);
      setShowNotes(false);
    }
  }, [selectedConversation]);

  useEffect(() => {
    if (!selectedConversation || !isMobileViewport) {
      setShowMobileActionMenu(false);
    }
  }, [isMobileViewport, selectedConversation]);

  const showPinnedContextPanel = Boolean(selectedConversation && isWideDesktop);
  const showProfileOverlay = Boolean(
    selectedConversation && showProfilePanel && !showPinnedContextPanel,
  );
  const showNotesOverlay = Boolean(
    selectedConversation && showNotes && !showPinnedContextPanel,
  );
  const isProfilePanelActive = showPinnedContextPanel
    ? !showNotes
    : showProfilePanel;

  const handleBackToConversationList = useCallback(() => {
    setShowSidebar(true);
    setShowProfilePanel(false);
    setShowNotes(false);
    setShowMobileActionMenu(false);
    selectConversation(null);
  }, [selectConversation]);

  const handleCopyConversationLink = useCallback(
    (conversationId: string) => {
      const conversationLink = `${window.location.origin}/facebook-inbox?conversation=${conversationId}`;

      navigator.clipboard
        .writeText(conversationLink)
        .then(() => {
          setCopiedLink(true);
          setTimeout(() => setCopiedLink(false), 2000);
        })
        .catch((err) => {
          console.error("Failed to copy link:", err);
          alert(`${t("inbox.conversationLink")}:\n${conversationLink}`);
        });
    },
    [t],
  );

  const handleOpenProfilePanel = useCallback(() => {
    setShowMobileActionMenu(false);

    if (isWideDesktop) {
      setShowNotes(false);
      setShowProfilePanel(true);
      return;
    }

    setShowProfilePanel((current) => {
      const next = !current;
      if (next) {
        setShowNotes(false);
      }
      return next;
    });
  }, [isWideDesktop]);

  const handleToggleNotesPanel = useCallback(() => {
    setShowMobileActionMenu(false);

    if (isWideDesktop) {
      setShowNotes((current) => !current);
      setShowProfilePanel(true);
      return;
    }

    setShowNotes((current) => {
      const next = !current;
      if (next) {
        setShowProfilePanel(false);
      }
      return next;
    });
  }, [isWideDesktop]);

  return (
    <div
      className={`business-inbox-shell${selectedConversation ? " business-inbox-shell--conversation-active" : ""}`}
    >
      <div className={selectedConversation ? "hidden md:block" : ""}>
        <InboxTabs
          activeTab={activeTab}
          onTabChange={(newTab) => {
            setActiveTab(newTab);
          }}
          counts={tabCounts}
          onSearch={setSearchQuery}
          onToggleFilters={() => setShowFilters(!showFilters)}
          onShowStats={() => setShowStats(true)}
        />
      </div>

      <StatsDashboard
        isOpen={showStats}
        onClose={() => setShowStats(false)}
        conversations={conversations}
      />

      <ForwardModal
        isOpen={forwardModalOpen}
        onClose={() => setForwardModalOpen(false)}
        onForward={handleForward}
        conversations={conversations}
      />

      <SnoozeModal
        isOpen={snoozeModalOpen}
        onClose={() => setSnoozeModalOpen(false)}
        onSnooze={handleSnoozeConfirm}
      />

      <div className="business-inbox-stage relative">
        {/* Notes Panel Overlay */}
        {showNotesOverlay && (
          <>
            <div
              className="absolute inset-0 z-20 bg-black/10 backdrop-blur-[1px]"
              onClick={() => setShowNotes(false)}
            />
            <div className="absolute inset-y-0 right-0 z-30 w-full sm:max-w-[20rem]">
              <NotesPanel
                className="h-full w-full shadow-2xl"
                customerId={selectedConversation!.customerId}
                isOpen={showNotes}
                onClose={() => setShowNotes(false)}
              />
            </div>
          </>
        )}

        {/* Mobile Sidebar Overlay */}
        {showSidebar && (
          <div
            className="md:hidden fixed inset-0 bg-black bg-opacity-50 z-20"
            onClick={() => setShowSidebar(false)}
          />
        )}

        {/* Left: Conversations */}
        <div
          className={`
                    ${showSidebar ? "translate-x-0" : "-translate-x-full"}
                    md:translate-x-0
                    fixed md:relative
                    inset-y-0 left-0
                    w-full sm:w-80 md:w-72 lg:w-80
                    z-30
                    business-inbox-column business-inbox-column--list flex flex-col
                    transition-transform duration-300 ease-in-out
                `}
        >
          {/* Bulk Actions Bar Overlay */}
          <BulkActionsBar
            selectedCount={selectedIds.size}
            onClearSelection={clearSelection}
            onMarkAsDone={handleBulkMarkDone}
            onAssign={handleBulkAssign}
            onAddTags={handleBulkTags}
          />

          <FilterPanel
            isOpen={showFilters}
            filters={filters}
            onFilterChange={setFilters}
            onClose={() => setShowFilters(false)}
            onReset={() =>
              setFilters({
                unreadOnly: false,
                assignedTo: "all",
                startDate: null,
                endDate: null,
              })
            }
          />

          <div
            className="flex-1 overflow-y-auto"
            onScroll={(e) => {
              const target = e.currentTarget;
              const { scrollTop, scrollHeight, clientHeight } = target;
              // Load more when near bottom (within 200px)
              if (
                scrollHeight - scrollTop - clientHeight < 200 &&
                hasMoreConversations &&
                !loading
              ) {
                loadMoreConversations();
              }
            }}
          >
            {loading && conversations.length === 0 ? (
              <div className="business-inbox-empty h-full">
                <div
                  className="animate-spin rounded-full h-12 w-12 border-b-2"
                  style={{ borderColor: "var(--color-primary)" }}
                ></div>
              </div>
            ) : error ? (
              <div
                className="text-center p-8"
                style={{ color: "var(--business-danger)" }}
              >
                {error}
              </div>
            ) : filteredConversations.length === 0 ? (
              <div className="business-inbox-empty p-8">
                <div className="text-6xl mb-4">💬</div>
                <p>لا توجد محادثات</p>
              </div>
            ) : (
              <div>
                {/* Deduplicate conversations by ID to prevent duplicate key warnings */}
                {Array.from(
                  new Map(
                    filteredConversations.map((conv) => [conv.id, conv]),
                  ).values(),
                ).map((conv) => (
                  <ConversationItem
                    key={conv.id}
                    conversation={conv}
                    isSelected={selectedConversation?.id === conv.id}
                    isMultiSelected={selectedIds.has(conv.id)}
                    onToggleSelection={(e) => {
                      e.stopPropagation();
                      toggleSelection(conv.id);
                    }}
                    onClick={() => {
                      selectConversation(conv);
                      if (window.innerWidth < 768) {
                        setShowSidebar(false);
                      }
                    }}
                  />
                ))}
                {/* Loading more conversations indicator */}
                {loading && conversations.length > 0 && (
                  <div className="flex justify-center p-4">
                    <div
                      className="animate-spin rounded-full h-6 w-6 border-b-2"
                      style={{ borderColor: "var(--color-muted-foreground)" }}
                    ></div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Center: Chat */}
        <div className="business-inbox-column flex-1 relative">
          {selectedConversation ? (
            <>
              {/* Chat Header - simplified, Status & Assignment moved to sidebar */}
              <div className="business-inbox-header business-inbox-chat-header p-2 sm:p-3">
                <div className="business-inbox-header-row business-inbox-chat-header-row">
                  {/* زر الرجوع للموبايل */}
                  <button
                    onClick={handleBackToConversationList}
                    className="md:hidden business-chip-button p-2 rounded-lg transition-colors"
                    title="رجوع للمحادثات"
                  >
                    <ArrowRight size={20} />
                  </button>

                  <div className="business-inbox-chat-identity flex min-w-0 items-center gap-3">
                    {selectedConversation.customerAvatar ? (
                      <img
                        src={selectedConversation.customerAvatar}
                        alt={selectedConversation.customerName}
                        className="business-conversation-avatar !w-10 !h-10"
                      />
                    ) : (
                      <div className="business-conversation-fallback !w-10 !h-10">
                        {selectedConversation.customerName.charAt(0)}
                      </div>
                    )}

                    <div className="min-w-0">
                      <h2
                        className="truncate text-lg font-semibold"
                        style={{ color: "var(--color-foreground)" }}
                      >
                        {selectedConversation.customerName}
                      </h2>
                      {selectedConversation.pageName && (
                        <p
                          className="truncate text-xs"
                          style={{ color: "var(--color-muted-foreground)" }}
                        >
                          {selectedConversation.pageName}
                        </p>
                      )}
                    </div>
                  </div>

                  <div className="business-inbox-chat-actions">
                    {isMobileViewport ? (
                      <>
                        <button
                          onClick={handleOpenProfilePanel}
                          className="business-icon-button rounded-xl transition-colors"
                          data-tone={
                            isProfilePanelActive ? "primary" : undefined
                          }
                          title="بيانات العميل"
                        >
                          <UserCircleIcon className="h-5 w-5" />
                        </button>

                        <button
                          onClick={() =>
                            setShowMobileActionMenu((current) => !current)
                          }
                          className="business-icon-button rounded-xl transition-colors"
                          data-tone={showMobileActionMenu ? "primary" : undefined}
                          title="المزيد"
                          aria-expanded={showMobileActionMenu}
                        >
                          <MoreHorizontal size={18} />
                        </button>
                      </>
                    ) : (
                      <>
                        <button
                          onClick={() =>
                            handleCopyConversationLink(selectedConversation.id)
                          }
                          className="business-icon-button rounded-xl transition-colors"
                          data-tone={copiedLink ? "success" : "primary"}
                          style={
                            copiedLink
                              ? {
                                  color: "var(--business-success)",
                                }
                              : {
                                  color: "var(--color-primary)",
                                }
                          }
                          title={String(
                            copiedLink
                              ? t("sidebar.linkCopied")
                              : t("sidebar.copyLink"),
                          )}
                        >
                          {copiedLink ? <Check size={16} /> : <Copy size={16} />}
                        </button>

                        <button
                          onClick={() => setShowQuickOrderModal(true)}
                          className="business-icon-button rounded-xl transition-colors"
                          data-tone="warning"
                          title="إنشاء طلب سريع"
                        >
                          <ShoppingCartIcon className="h-5 w-5" />
                        </button>

                        <button
                          onClick={handleOpenProfilePanel}
                          className="business-icon-button rounded-xl transition-colors"
                          data-tone={
                            isProfilePanelActive ? "primary" : undefined
                          }
                          title="بيانات العميل"
                        >
                          <UserCircleIcon className="h-5 w-5" />
                        </button>

                        <div
                          className="business-inbox-chat-separator h-6 w-px mx-1"
                          style={{ background: "var(--business-muted-line)" }}
                        ></div>

                        <AIToggle
                          enabled={selectedConversation.aiEnabled !== false}
                          onToggle={handleToggleAI}
                          loading={updating}
                        />

                        <div
                          className="business-inbox-chat-separator h-6 w-px mx-1"
                          style={{ background: "var(--business-muted-line)" }}
                        ></div>

                        <button
                          onClick={handleToggleNotesPanel}
                          className="business-chip-button p-2 rounded-full transition-colors"
                          style={
                            showNotes
                              ? {
                                  color: "var(--business-warning)",
                                  background:
                                    "color-mix(in srgb, var(--business-warning) 10%, white)",
                                }
                              : undefined
                          }
                          title={String(t("inbox.notes"))}
                        >
                          <StickyNote size={20} />
                        </button>
                        <ConversationActionsBar
                          isPriority={selectedConversation.priority}
                          onTogglePriority={handleTogglePriority}
                          onMarkDone={handleMarkDone}
                          onSnooze={() => setSnoozeModalOpen(true)}
                          disabled={updating}
                        />
                      </>
                    )}
                  </div>
                </div>

                {isMobileViewport && showMobileActionMenu && (
                  <>
                    <button
                      type="button"
                      className="fixed inset-0 z-20 bg-black/10 md:hidden"
                      onClick={() => setShowMobileActionMenu(false)}
                      aria-label="إغلاق قائمة الإجراءات"
                    />
                    <div className="business-inbox-mobile-action-menu business-dropdown-surface absolute inset-x-3 top-full z-30 mt-2 p-2 md:hidden">
                      <div
                        className="mb-2 flex items-center justify-between gap-3 rounded-2xl px-3 py-2"
                        style={{
                          background: "var(--business-surface-subtle)",
                        }}
                      >
                        <div>
                          <div
                            className="text-sm font-semibold"
                            style={{ color: "var(--color-foreground)" }}
                          >
                            الرد الذكي
                          </div>
                          <div
                            className="text-xs"
                            style={{
                              color: "var(--color-muted-foreground)",
                            }}
                          >
                            تشغيل أو إيقاف المساعد داخل المحادثة
                          </div>
                        </div>
                        <AIToggle
                          enabled={selectedConversation.aiEnabled !== false}
                          onToggle={handleToggleAI}
                          loading={updating}
                        />
                      </div>

                      <button
                        type="button"
                        className="business-dropdown-option"
                        onClick={() => {
                          setShowMobileActionMenu(false);
                          setShowQuickOrderModal(true);
                        }}
                      >
                        <ShoppingCartIcon className="h-5 w-5" />
                        <span>إنشاء طلب سريع</span>
                      </button>

                      <button
                        type="button"
                        className="business-dropdown-option"
                        onClick={() => {
                          handleCopyConversationLink(selectedConversation.id);
                          setShowMobileActionMenu(false);
                        }}
                      >
                        {copiedLink ? (
                          <Check className="h-5 w-5" />
                        ) : (
                          <Copy className="h-5 w-5" />
                        )}
                        <span>
                          {copiedLink
                            ? String(t("sidebar.linkCopied"))
                            : String(t("sidebar.copyLink"))}
                        </span>
                      </button>

                      <button
                        type="button"
                        className="business-dropdown-option"
                        onClick={handleToggleNotesPanel}
                      >
                        <StickyNote size={18} />
                        <span>{showNotes ? "إخفاء الملاحظات" : "عرض الملاحظات"}</span>
                      </button>

                      <button
                        type="button"
                        className="business-dropdown-option"
                        onClick={() => {
                          setShowMobileActionMenu(false);
                          handleMarkDone();
                        }}
                      >
                        <CheckCircleIcon className="h-5 w-5" />
                        <span>تحديد كمنتهي</span>
                      </button>

                      <button
                        type="button"
                        className="business-dropdown-option"
                        onClick={() => {
                          setShowMobileActionMenu(false);
                          handleTogglePriority();
                        }}
                      >
                        <StarIcon className="h-5 w-5" />
                        <span>
                          {selectedConversation.priority
                            ? "إلغاء الأولوية"
                            : "تحديد كأولوية"}
                        </span>
                      </button>

                      <button
                        type="button"
                        className="business-dropdown-option"
                        onClick={() => {
                          setShowMobileActionMenu(false);
                          setSnoozeModalOpen(true);
                        }}
                      >
                        <ClockIcon className="h-5 w-5" />
                        <span>غفوة المحادثة</span>
                      </button>
                    </div>
                  </>
                )}
              </div>

              {/* Messages Container - scrollable area, messages directly above input */}
              <div
                className="business-chat-stage flex-1 overflow-y-auto p-2 sm:p-4 pb-4"
                ref={messagesContainerRef}
                onScroll={handleScroll}
              >
                {loadingMessages && !hasMore ? (
                  <div className="business-inbox-empty h-full">
                    <div
                      className="animate-spin rounded-full h-8 w-8 border-b-2"
                      style={{ borderColor: "var(--color-primary)" }}
                    ></div>
                  </div>
                ) : messages.length === 0 && !loadingMessages ? (
                  <div className="business-inbox-empty h-full py-10">
                    <p>{t("inbox.noMessages")}</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {/* Loading more indicator at top when loading older messages */}
                    {loadingMessages && hasMore && (
                      <div className="flex justify-center p-2">
                        <div
                          className="animate-spin rounded-full h-5 w-5 border-b-2"
                          style={{
                            borderColor: "var(--color-muted-foreground)",
                          }}
                        ></div>
                      </div>
                    )}

                    {/* Messages in normal order (oldest first, newest last) */}
                    {Array.from(
                      new Map(messages.map((msg) => [msg.id, msg])).values(),
                    ).map((msg) => {
                      // hasBeenReplied: true if replied, false if not replied, undefined if not a customer message
                      const hasBeenReplied = msg.isFromCustomer
                        ? repliedMessages.has(msg.id)
                        : undefined;
                      return (
                        <MessageBubble
                          key={msg.id}
                          message={msg}
                          {...(hasBeenReplied !== undefined && {
                            hasBeenReplied,
                          })}
                          onDelete={handleDeleteMessage}
                          onForward={handleForwardRequest}
                          onStar={handleStarMessage}
                          onReaction={handleMessageReaction}
                          onReply={handleReplyToMessage}
                          currentUserId={user?.id || ""}
                        />
                      );
                    })}

                    {/* AI Typing Indicator at bottom */}
                    {isAITyping && (
                      <div className="mt-2">
                        <TypingIndicator />
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Sticky bottom composer */}
              <div className="sticky bottom-0 z-10 mt-auto">
                <MessageInput
                  onSendMessage={handleSendMessage}
                  onSendFile={handleSendFile}
                  sending={sending}
                  uploadingFile={uploadingFile}
                  conversation={selectedConversation}
                  user={user}
                  replyTo={replyToMessage}
                  onCancelReply={handleCancelReply}
                  onOpenTextGallery={() => setShowTextGallery(true)}
                  onOpenImageGallery={() => setShowImageGallery(true)}
                />
              </div>
            </>
          ) : (
            <div className="business-chat-stage flex items-center justify-center h-full">
              <div className="text-center">
                {/* زر فتح القائمة على الموبايل */}
                <button
                  onClick={() => setShowSidebar(true)}
                  className="md:hidden mb-4 business-icon-button !w-14 !h-14 rounded-full shadow-lg"
                  style={{
                    background:
                      "linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%)",
                    color: "white",
                    borderColor: "transparent",
                  }}
                  title="عرض المحادثات"
                >
                  <Menu size={24} />
                </button>
                <div className="text-6xl mb-4">💬</div>
                <h3
                  className="text-lg font-medium mb-2"
                  style={{ color: "var(--color-foreground)" }}
                >
                  اختر محادثة
                </h3>
                <p
                  className="text-sm"
                  style={{ color: "var(--color-muted-foreground)" }}
                >
                  اختر محادثة من القائمة
                </p>
              </div>
            </div>
          )}
        </div>

        {showPinnedContextPanel &&
          (showNotes ? (
            <NotesPanel
              className="business-inbox-column--profile business-inbox-column--context h-full shadow-none"
              customerId={selectedConversation!.customerId}
              isOpen
              onClose={() => setShowNotes(false)}
            />
          ) : (
            <CustomerProfile
              className="business-inbox-column--context h-full shadow-none"
              conversation={selectedConversation!}
              onTagsChange={handleTagsChange}
              updatingTags={updatingTags}
              currentStatus={selectedConversation!.status}
              onStatusChange={(status) =>
                handleStatusChange(status as ConversationStatus)
              }
              currentAssignee={selectedConversation!.assignedTo}
              currentAssigneeName={selectedConversation!.assignedToName ?? null}
              onAssign={handleAssignment}
              disabled={updating}
              onCopyConversationLink={(conversationId) => {
                const conversationLink = `${window.location.origin}/facebook-inbox?conversation=${conversationId}`;

                navigator.clipboard
                  .writeText(conversationLink)
                  .catch((err) => {
                    console.error("❌ Failed to copy link:", err);
                    alert(`رابط المحادثة:\n${conversationLink}`);
                  });
              }}
              isBlocked={isBlocked}
              checkingBlockStatus={checkingBlockStatus}
              blocking={blocking}
              showBlockModal={showBlockModal}
              blockReason={blockReason}
              onBlockClick={() => setShowBlockModal(true)}
              onUnblockClick={handleUnblockCustomer}
              onBlockReasonChange={setBlockReason}
              onBlockConfirm={handleBlockCustomer}
              onBlockCancel={() => {
                setShowBlockModal(false);
                setBlockReason("");
              }}
              soundEnabled={soundEnabled}
              notificationsEnabled={notificationsEnabled}
              onSoundToggle={() => setSoundEnabled(!soundEnabled)}
              onNotificationsToggle={() =>
                setNotificationsEnabled(!notificationsEnabled)
              }
              onCreateOrder={() => setShowQuickOrderModal(true)}
            />
          ))}

        {showProfileOverlay && (
          <>
            <div
              className="absolute inset-0 z-20 bg-black/15 backdrop-blur-[1px]"
              onClick={() => setShowProfilePanel(false)}
            />
            <div className="absolute inset-y-0 right-0 z-30 w-full sm:max-w-[22rem] xl:max-w-[23rem]">
              <button
                type="button"
                onClick={() => setShowProfilePanel(false)}
                className="business-icon-button absolute left-3 top-3 z-40 rounded-full"
                title="إغلاق بيانات العميل"
              >
                <XMarkIcon className="h-5 w-5" />
              </button>
              <CustomerProfile
                className="w-full shadow-2xl"
                conversation={selectedConversation!}
                onTagsChange={handleTagsChange}
                updatingTags={updatingTags}
                currentStatus={selectedConversation!.status}
                onStatusChange={(status) =>
                  handleStatusChange(status as ConversationStatus)
                }
                currentAssignee={selectedConversation!.assignedTo}
                currentAssigneeName={selectedConversation!.assignedToName ?? null}
                onAssign={handleAssignment}
                disabled={updating}
                // 🆕 Copy Conversation Link
                onCopyConversationLink={(conversationId) => {
                  const conversationLink = `${window.location.origin}/facebook-inbox?conversation=${conversationId}`;

                  navigator.clipboard
                    .writeText(conversationLink)
                    .then(() => {
                      console.log(
                        "✅ Conversation link copied:",
                        conversationLink,
                      );
                    })
                    .catch((err) => {
                      console.error("❌ Failed to copy link:", err);
                      alert(`رابط المحادثة:\n${conversationLink}`);
                    });
                }}
                // 🆕 Block Customer Props
                isBlocked={isBlocked}
                checkingBlockStatus={checkingBlockStatus}
                blocking={blocking}
                showBlockModal={showBlockModal}
                blockReason={blockReason}
                onBlockClick={() => setShowBlockModal(true)}
                onUnblockClick={handleUnblockCustomer}
                onBlockReasonChange={setBlockReason}
                onBlockConfirm={handleBlockCustomer}
                onBlockCancel={() => {
                  setShowBlockModal(false);
                  setBlockReason("");
                }}
                // 🆕 Sound & Notifications Props
                soundEnabled={soundEnabled}
                notificationsEnabled={notificationsEnabled}
                onSoundToggle={() => setSoundEnabled(!soundEnabled)}
                onNotificationsToggle={() =>
                  setNotificationsEnabled(!notificationsEnabled)
                }
                // 🆕 Quick Order
                onCreateOrder={() => setShowQuickOrderModal(true)}
              />
            </div>
          </>
        )}
      </div>

      {!isConnected && (
        <div
          className="fixed bottom-4 right-4 px-4 py-2 rounded-lg shadow-lg business-page-panel"
          style={{
            background:
              "color-mix(in srgb, var(--business-warning) 12%, white)",
            borderColor:
              "color-mix(in srgb, var(--business-warning) 24%, transparent)",
            color: "color-mix(in srgb, var(--business-warning) 78%, black)",
          }}
        >
          ⚠️ غير متصل
        </div>
      )}

      {/* Text Gallery Modal */}
      <TextGalleryModal
        isOpen={showTextGallery}
        onClose={() => setShowTextGallery(false)}
        onSelectText={handleSelectTextFromGallery}
      />

      {/* Image Gallery Modal */}
      <ImageGalleryModal
        isOpen={showImageGallery}
        onClose={() => setShowImageGallery(false)}
        onSelectImage={handleSelectImageFromGallery}
        onSelectMultipleImages={handleSelectMultipleImagesFromGallery}
      />

      {/* 🆕 Block Customer Modal */}
      {showBlockModal && selectedConversation && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="business-modal-surface p-6 w-full max-w-md">
            <h3
              className="text-lg font-semibold mb-4"
              style={{ color: "var(--color-foreground)" }}
            >
              حظر العميل على صفحة الفيس بوك
            </h3>
            <p
              className="text-sm mb-4"
              style={{ color: "var(--color-muted-foreground)" }}
            >
              سيتم حظر هذا العميل على صفحة الفيس بوك المحددة ولن يتم استقبال
              رسائله.
            </p>

            <div className="mb-4">
              <label
                className="block text-sm font-medium mb-2"
                style={{ color: "var(--color-foreground)" }}
              >
                سبب الحظر (اختياري)
              </label>
              <textarea
                value={blockReason}
                onChange={(e) => setBlockReason(e.target.value)}
                className="business-chat-input"
                rows={3}
                placeholder="أدخل سبب الحظر..."
              />
            </div>

            <div className="flex justify-end space-x-2">
              <button
                onClick={() => {
                  setShowBlockModal(false);
                  setBlockReason("");
                }}
                className="business-chip-button px-4 py-2 rounded-lg"
              >
                إلغاء
              </button>
              <button
                onClick={handleBlockCustomer}
                disabled={blocking}
                className="business-chip-button px-4 py-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                style={{
                  background: "var(--business-danger)",
                  borderColor: "transparent",
                  color: "white",
                }}
              >
                {blocking ? "جاري الحظر..." : "تأكيد الحظر"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 🆕 Blocked Customer Alert */}
      {isBlocked && selectedConversation && (
        <div
          className="fixed top-4 left-1/2 transform -translate-x-1/2 z-50 rounded-lg p-4 shadow-lg max-w-md business-page-panel"
          style={{
            background: "color-mix(in srgb, var(--business-danger) 8%, white)",
            borderColor:
              "color-mix(in srgb, var(--business-danger) 22%, transparent)",
          }}
        >
          <div className="flex items-center space-x-2">
            <NoSymbolIcon
              className="w-6 h-6"
              style={{ color: "var(--business-danger)" }}
            />
            <p className="text-sm" style={{ color: "var(--business-danger)" }}>
              ⚠️ هذا العميل محظور على صفحة الفيس بوك - لن يتم استقبال رسائله
            </p>
          </div>
        </div>
      )}

      {/* 🆕 Quick Order Modal */}
      {selectedConversation && (
        <QuickOrderModal
          isOpen={showQuickOrderModal}
          onClose={() => setShowQuickOrderModal(false)}
          conversation={selectedConversation}
          customerName={selectedConversation.customerName}
          onOrderCreated={(orderId) => {
            console.log("✅ Order created:", orderId);
            // يمكن إضافة رسالة تلقائية للعميل هنا
          }}
        />
      )}
    </div>
  );
};

export default FacebookInbox;

import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { companyAwareApi } from "../../services/companyAwareApi";
import { uploadService } from "../../services/uploadService";
import {
  PhotoIcon,
  VideoCameraIcon,
  LinkIcon,
  CalendarIcon,
  XMarkIcon,
  CheckCircleIcon,
  PaperAirplaneIcon,
  ClockIcon,
  DocumentTextIcon,
} from "@heroicons/react/24/outline";

interface FacebookPage {
  id: string;
  pageId: string;
  pageName: string;
  status: string;
}

type TabType = "STATUS" | "MEDIA" | "LINK";
type PostType = "FEED" | "STORY";

const headingStyle: React.CSSProperties = {
  color: "var(--color-foreground)",
};

const mutedStyle: React.CSSProperties = {
  color: "var(--color-muted-foreground)",
};

const panelStyle: React.CSSProperties = {
  border: "1px solid var(--business-card-border)",
};

const selectedSurfaceStyle: React.CSSProperties = {
  borderColor: "color-mix(in srgb, var(--color-primary) 28%, transparent)",
  background: "color-mix(in srgb, var(--color-primary) 8%, transparent)",
  boxShadow:
    "0 0 0 1px color-mix(in srgb, var(--color-primary) 18%, transparent)",
};

const idleSurfaceStyle: React.CSSProperties = {
  borderColor: "var(--business-card-border)",
  background:
    "color-mix(in srgb, var(--color-background) 88%, var(--shell-control-bg) 12%)",
};

const activeTabStyle: React.CSSProperties = {
  color: "var(--color-primary)",
  borderColor: "var(--color-primary)",
};

const accentTabStyle: React.CSSProperties = {
  color: "var(--color-secondary)",
  borderColor: "var(--color-secondary)",
};

const inactiveTabStyle: React.CSSProperties = {
  color: "var(--color-muted-foreground)",
  borderColor: "transparent",
};

const pillActiveStyle: React.CSSProperties = {
  color: "var(--color-foreground)",
  background:
    "color-mix(in srgb, var(--color-background) 80%, var(--shell-control-bg) 20%)",
};

const pillIdleStyle: React.CSSProperties = {
  color: "var(--color-muted-foreground)",
};

const controlInputStyle: React.CSSProperties = {
  borderColor: "var(--business-card-border)",
  background:
    "color-mix(in srgb, var(--color-background) 90%, var(--shell-control-bg) 10%)",
  color: "var(--color-foreground)",
};

const dropzoneStyle: React.CSSProperties = {
  borderColor: "var(--business-card-border)",
  background:
    "color-mix(in srgb, var(--color-background) 84%, var(--shell-control-bg) 16%)",
};

const primaryActionStyle: React.CSSProperties = {
  background:
    "linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%)",
  color: "color-mix(in srgb, var(--color-background) 96%, transparent)",
};

const disabledActionStyle: React.CSSProperties = {
  background:
    "color-mix(in srgb, var(--color-muted-foreground) 24%, var(--shell-control-bg))",
  color: "color-mix(in srgb, var(--color-background) 82%, transparent)",
};

const successBannerStyle: React.CSSProperties = {
  background:
    "color-mix(in srgb, var(--business-success) 10%, var(--color-background))",
  borderColor: "color-mix(in srgb, var(--business-success) 18%, transparent)",
};

const errorBannerStyle: React.CSSProperties = {
  background:
    "color-mix(in srgb, var(--business-danger) 10%, var(--color-background))",
  borderColor: "color-mix(in srgb, var(--business-danger) 18%, transparent)",
};

const FacebookPostCreator: React.FC = () => {
  const navigate = useNavigate();
  const [pages, setPages] = useState<FacebookPage[]>([]);
  const [selectedPages, setSelectedPages] = useState<string[]>([]);

  // UI State
  const [activeTab, setActiveTab] = useState<TabType>("STATUS");
  const [postType, setPostType] = useState<PostType>("FEED");
  const [isScheduled, setIsScheduled] = useState(false);
  const [scheduledDate, setScheduledDate] = useState("");

  // Content State
  const [message, setMessage] = useState("");
  const [linkUrl, setLinkUrl] = useState("");
  const [mediaFiles, setMediaFiles] = useState<File[]>([]);
  const [mediaPreviews, setMediaPreviews] = useState<
    { url: string; type: "image" | "video" }[]
  >([]);

  // Processing State
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState<any>(null);
  const hasFetchedPages = useRef(false);

  useEffect(() => {
    if (!hasFetchedPages.current) {
      hasFetchedPages.current = true;
      fetchPages();
    }
  }, []);

  const fetchPages = async () => {
    // Prevent multiple simultaneous calls
    if (loading) {
      return;
    }

    setLoading(true);
    try {
      const response = await companyAwareApi.get(
        "/integrations/facebook/connected",
      );
      if (response.data.success) {
        setPages(response.data.pages || []);
      }
    } catch (error) {
      console.error("Error fetching pages:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleMediaChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    // For Stories, only allow one media
    if (postType === "STORY" && mediaFiles.length + files.length > 1) {
      alert("القصص (Stories) تدعم ملف وسائط واحد فقط.");
      return;
    }

    const newPreviews = files.map((file) => ({
      url: URL.createObjectURL(file),
      type: file.type.startsWith("video/")
        ? "video"
        : ("image" as "image" | "video"),
    }));

    setMediaFiles((prev) => [...prev, ...files]);
    setMediaPreviews((prev) => [...prev, ...newPreviews]);
  };

  const removeMedia = (index: number) => {
    setMediaFiles((prev) => prev.filter((_, i) => i !== index));
    setMediaPreviews((prev) => {
      // Revoke URL to avoid memory leaks
      URL.revokeObjectURL(prev[index].url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const togglePageSelection = (pageId: string) => {
    setSelectedPages((prev) =>
      prev.includes(pageId)
        ? prev.filter((id) => id !== pageId)
        : [...prev, pageId],
    );
  };

  const handleSelectAll = () => {
    if (selectedPages.length === pages.length) {
      setSelectedPages([]);
    } else {
      setSelectedPages(pages.map((p) => p.pageId));
    }
  };

  const handleSubmit = async () => {
    if (selectedPages.length === 0) {
      alert("يرجى اختيار صفحة واحدة على الأقل");
      return;
    }

    // Validation
    if (postType === "STORY" && mediaFiles.length === 0) {
      alert("يجب إضافة صورة أو فيديو لنشر القصة");
      return;
    }
    if (activeTab === "LINK" && !linkUrl) {
      alert("يرجى إدخال الرابط");
      return;
    }
    if (activeTab === "STATUS" && !message && mediaFiles.length === 0) {
      alert("يرجى كتابة نص أو إضافة وسائط");
      return;
    }
    if (isScheduled && !scheduledDate) {
      alert("يرجى تحديد موعد النشر");
      return;
    }

    setSubmitting(true);
    setResult(null);

    try {
      // 1. Upload Media if any
      const uploadedMediaUrls: string[] = [];
      if (mediaFiles.length > 0) {
        for (const file of mediaFiles) {
          const uploadRes = await uploadService.uploadMedia(file);
          if (uploadRes.success && uploadRes.data) {
            let finalUrl = uploadRes.data.fullUrl || uploadRes.data.url;
            if (finalUrl && !finalUrl.startsWith("http")) {
              finalUrl = window.location.origin + finalUrl;
            }
            uploadedMediaUrls.push(finalUrl);
          } else {
            throw new Error(`فشل رفع الملف: ${file.name}`);
          }
        }
      }

      // 2. Determine Media Type
      let mediaType = "NONE";
      if (mediaFiles.length > 0) {
        // Check if video
        const hasVideo = mediaFiles.some((f) => f.type.startsWith("video/"));
        if (hasVideo) mediaType = "VIDEO";
        else if (mediaFiles.length > 1)
          mediaType = "CAROUSEL"; // Or just multiple images
        else mediaType = "IMAGE";
      }

      // 3. Prepare Payload
      const payload = {
        pageIds: selectedPages,
        message: message,
        mediaUrls: uploadedMediaUrls,
        mediaType: mediaType,
        linkUrl: activeTab === "LINK" ? linkUrl : undefined,
        postType: postType,
        scheduledTime: isScheduled ? scheduledDate : undefined,
      };

      const response = await companyAwareApi.post(
        "/integrations/facebook/publish",
        payload,
      );

      if (response.data.success) {
        setResult(response.data);
        // Reset form partially
        setMessage("");
        setMediaFiles([]);
        setMediaPreviews([]);
        setLinkUrl("");
      } else {
        alert("حدث خطأ أثناء النشر");
      }
    } catch (error: any) {
      console.error("Publishing error:", error);
      alert("فشل في عملية النشر: " + (error.message || "خطأ غير معروف"));
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      className="w-full min-h-screen space-y-6 p-6"
      style={{
        background:
          "linear-gradient(180deg, color-mix(in srgb, var(--color-background) 92%, var(--shell-control-bg) 8%) 0%, color-mix(in srgb, var(--shell-control-bg) 84%, var(--color-background) 16%) 100%)",
      }}
    >
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold" style={headingStyle}>
            إنشاء ومجدولة المنشورات
          </h1>
          <p className="mt-1 text-sm" style={mutedStyle}>
            انشر أو جدول محتواك على فيسبوك بكل سهولة
          </p>
        </div>
        <button
          onClick={() => navigate("/facebook-inbox")}
          className="business-chip-button flex items-center gap-1 px-4 py-2"
        >
          <XMarkIcon className="h-5 w-5" />
          إلغاء
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Creator */}
        <div className="lg:col-span-2 space-y-6">
          {/* 1. Page Selector */}
          <div className="business-page-panel p-5" style={panelStyle}>
            <div className="flex justify-between items-center mb-4">
              <h2 className="flex items-center font-bold" style={headingStyle}>
                <span
                  className="ml-2 flex h-6 w-6 items-center justify-center rounded-full text-xs"
                  style={{
                    background:
                      "color-mix(in srgb, var(--color-primary) 12%, transparent)",
                    color: "var(--color-primary)",
                  }}
                >
                  1
                </span>
                اختر الصفحات
              </h2>
              <button
                onClick={handleSelectAll}
                className="text-sm font-medium"
                style={{ color: "var(--color-primary)" }}
              >
                {selectedPages.length === pages.length
                  ? "إلغاء التحديد"
                  : "تحديد الكل"}
              </button>
            </div>

            {loading ? (
              <div className="animate-pulse space-y-2">
                <div
                  className="h-10 rounded"
                  style={{
                    background:
                      "color-mix(in srgb, var(--shell-control-bg) 82%, var(--color-background) 18%)",
                  }}
                ></div>
                <div
                  className="h-10 rounded"
                  style={{
                    background:
                      "color-mix(in srgb, var(--shell-control-bg) 82%, var(--color-background) 18%)",
                  }}
                ></div>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
                {pages.map((page) => (
                  <div
                    key={page.id}
                    onClick={() => togglePageSelection(page.pageId)}
                    className="flex cursor-pointer items-center rounded-lg border p-3 transition-all"
                    style={
                      selectedPages.includes(page.pageId)
                        ? selectedSurfaceStyle
                        : idleSurfaceStyle
                    }
                  >
                    <div
                      className="mr-3 flex h-5 w-5 flex-shrink-0 items-center justify-center rounded transition-colors"
                      style={
                        selectedPages.includes(page.pageId)
                          ? {
                              background: "var(--color-primary)",
                              color:
                                "color-mix(in srgb, var(--color-background) 96%, transparent)",
                            }
                          : controlInputStyle
                      }
                    >
                      {selectedPages.includes(page.pageId) && (
                        <CheckCircleIcon className="w-4 h-4" />
                      )}
                    </div>
                    <span className="truncate font-medium" style={headingStyle}>
                      {page.pageName}
                    </span>
                  </div>
                ))}
              </div>
            )}
            <p className="mt-2 text-xs" style={mutedStyle}>
              تم تحديد {selectedPages.length} صفحة
            </p>
          </div>

          {/* 2. Content Creator */}
          <div className="business-page-panel p-5" style={panelStyle}>
            <div
              className="mb-4 flex items-center justify-between pb-4"
              style={{ borderBottom: "1px solid var(--business-card-border)" }}
            >
              <div className="flex space-x-4 space-x-reverse">
                <button
                  onClick={() => setPostType("FEED")}
                  className="border-b-2 px-1 pb-2 text-sm font-semibold transition-colors"
                  style={
                    postType === "FEED" ? activeTabStyle : inactiveTabStyle
                  }
                >
                  منشور (Feed)
                </button>
                <button
                  onClick={() => {
                    setPostType("STORY");
                    setActiveTab("MEDIA");
                  }}
                  className="border-b-2 px-1 pb-2 text-sm font-semibold transition-colors"
                  style={
                    postType === "STORY" ? accentTabStyle : inactiveTabStyle
                  }
                >
                  قصة (Story)
                </button>
              </div>
            </div>

            {/* Tabs for Feed */}
            {postType === "FEED" && (
              <div className="flex space-x-2 space-x-reverse mb-4">
                <button
                  onClick={() => setActiveTab("STATUS")}
                  className="flex items-center rounded-full px-3 py-1.5 text-sm"
                  style={
                    activeTab === "STATUS" ? pillActiveStyle : pillIdleStyle
                  }
                >
                  <DocumentTextIcon className="w-4 h-4 ml-1" /> حالة
                </button>
                <button
                  onClick={() => setActiveTab("MEDIA")}
                  className="flex items-center rounded-full px-3 py-1.5 text-sm"
                  style={
                    activeTab === "MEDIA" ? pillActiveStyle : pillIdleStyle
                  }
                >
                  <PhotoIcon className="w-4 h-4 ml-1" /> صور/فيديو
                </button>
                <button
                  onClick={() => setActiveTab("LINK")}
                  className="flex items-center rounded-full px-3 py-1.5 text-sm"
                  style={activeTab === "LINK" ? pillActiveStyle : pillIdleStyle}
                >
                  <LinkIcon className="w-4 h-4 ml-1" /> رابط
                </button>
              </div>
            )}

            {/* Input Area */}
            <div className="space-y-4">
              {/* Text Input */}
              {(activeTab !== "LINK" || postType === "FEED") && (
                <textarea
                  className="h-32 w-full resize-none rounded-lg p-3 text-base"
                  style={controlInputStyle}
                  placeholder={
                    postType === "STORY"
                      ? "ملاحظة: القصص لا تدعم النص المرفق بشكل كامل في API."
                      : "اكتب شيئاً مميزاً..."
                  }
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                />
              )}

              {/* Link Input */}
              {activeTab === "LINK" && postType === "FEED" && (
                <div>
                  <label
                    className="mb-1 block text-sm font-medium"
                    style={headingStyle}
                  >
                    رابط المقال أو الصفحة
                  </label>
                  <div className="flex">
                    <span
                      className="inline-flex items-center rounded-r-md border border-l-0 px-3 text-sm"
                      style={controlInputStyle}
                    >
                      https://
                    </span>
                    <input
                      type="text"
                      className="block w-full min-w-0 flex-1 rounded-l-md px-3 py-2 text-sm"
                      style={controlInputStyle}
                      placeholder="www.example.com"
                      value={linkUrl}
                      onChange={(e) => setLinkUrl(e.target.value)}
                    />
                  </div>
                </div>
              )}

              {/* Media Uploader */}
              {(activeTab === "MEDIA" || postType === "STORY") && (
                <div
                  className="rounded-lg border-2 border-dashed p-6 text-center transition-colors"
                  style={dropzoneStyle}
                >
                  <input
                    type="file"
                    id="mediaUpload"
                    multiple={postType === "FEED"} // Stories take 1 file
                    accept="image/*,video/*"
                    className="hidden"
                    onChange={handleMediaChange}
                  />
                  <label
                    htmlFor="mediaUpload"
                    className="cursor-pointer flex flex-col items-center"
                  >
                    <div
                      className="mb-3 rounded-full p-3"
                      style={{
                        background:
                          "color-mix(in srgb, var(--color-primary) 12%, transparent)",
                      }}
                    >
                      <VideoCameraIcon
                        className="h-8 w-8"
                        style={{ color: "var(--color-primary)" }}
                      />
                    </div>
                    <span className="font-medium" style={headingStyle}>
                      اضغط لإضافة صور أو فيديو
                    </span>
                    <span className="mt-1 text-xs" style={mutedStyle}>
                      يدعم JPG, PNG, MP4
                    </span>
                  </label>
                </div>
              )}

              {/* Previews */}
              {mediaPreviews.length > 0 && (
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  {mediaPreviews.map((preview, idx) => (
                    <div
                      key={idx}
                      className="group relative aspect-square overflow-hidden rounded-lg border"
                      style={panelStyle}
                    >
                      {preview.type === "video" ? (
                        <video
                          src={preview.url}
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <img
                          src={preview.url}
                          alt="preview"
                          className="w-full h-full object-cover"
                        />
                      )}
                      <button
                        onClick={() => removeMedia(idx)}
                        className="absolute right-1 top-1 rounded-full p-1 opacity-0 transition-opacity transform group-hover:opacity-100 hover:scale-110"
                        style={errorBannerStyle}
                      >
                        <XMarkIcon className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* 3. Scheduling & Publish Action */}
          <div className="business-page-panel p-5" style={panelStyle}>
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
              <div>
                <div className="flex items-center space-x-2 space-x-reverse mb-2">
                  <input
                    type="checkbox"
                    id="schedule"
                    checked={isScheduled}
                    onChange={(e) => setIsScheduled(e.target.checked)}
                    className="h-4 w-4 rounded"
                    style={{ accentColor: "var(--color-primary)" }}
                  />
                  <label
                    htmlFor="schedule"
                    className="cursor-pointer select-none font-medium"
                    style={headingStyle}
                  >
                    جدولة المنشور لوقت لاحق
                  </label>
                </div>
                {isScheduled && (
                  <div className="mt-2">
                    <input
                      type="datetime-local"
                      value={scheduledDate}
                      onChange={(e) => setScheduledDate(e.target.value)}
                      className="block w-full rounded-md px-3 py-2 text-sm"
                      style={controlInputStyle}
                    />
                    <p
                      className="mt-1 text-xs"
                      style={{ color: "var(--business-warning)" }}
                    >
                      يجب أن يكون الوقت بين 10 دقائق و 6 أشهر من الآن
                    </p>
                  </div>
                )}
              </div>

              <button
                onClick={handleSubmit}
                disabled={submitting || selectedPages.length === 0}
                className={`flex w-full items-center justify-center rounded-lg px-8 py-3 font-bold transition-all transform hover:-translate-y-0.5 sm:w-auto ${
                  submitting || selectedPages.length === 0
                    ? "cursor-not-allowed"
                    : ""
                }`}
                style={
                  submitting || selectedPages.length === 0
                    ? disabledActionStyle
                    : primaryActionStyle
                }
              >
                {submitting ? (
                  "جاري النشر..."
                ) : (
                  <>
                    <PaperAirplaneIcon
                      className={`w-5 h-5 ml-2 ${isScheduled ? "hidden" : ""}`}
                    />
                    <CalendarIcon
                      className={`w-5 h-5 ml-2 ${!isScheduled ? "hidden" : ""}`}
                    />
                    {isScheduled ? "جدولة المنشور" : "نشر الآن"}
                  </>
                )}
              </button>
            </div>
          </div>
        </div>

        {/* Right Column: Preview & Results */}
        <div className="space-y-6">
          {/* Live Preview Card */}
          <div
            className="business-page-panel sticky top-6 overflow-hidden"
            style={panelStyle}
          >
            <div
              className="flex items-center justify-between p-4"
              style={{
                borderBottom: "1px solid var(--business-card-border)",
                background:
                  "color-mix(in srgb, var(--color-background) 80%, var(--shell-control-bg) 20%)",
              }}
            >
              <h3 className="font-bold" style={headingStyle}>
                معاينة البوست
              </h3>
              <span className="text-xs font-mono" style={mutedStyle}>
                Desktop Preview
              </span>
            </div>
            <div className="p-4">
              <div
                className="rounded-lg border p-4"
                style={{
                  ...panelStyle,
                  background:
                    "color-mix(in srgb, var(--color-background) 88%, var(--shell-control-bg) 12%)",
                }}
              >
                {/* Fake Header */}
                <div className="flex items-center mb-3">
                  <div
                    className="mr-3 h-10 w-10 rounded-full"
                    style={{
                      background:
                        "color-mix(in srgb, var(--shell-control-bg) 78%, var(--color-background) 22%)",
                    }}
                  ></div>
                  <div className="flex-1">
                    <div
                      className="mb-2 h-4 w-24 rounded"
                      style={{
                        background:
                          "color-mix(in srgb, var(--shell-control-bg) 78%, var(--color-background) 22%)",
                      }}
                    ></div>
                    <div
                      className="h-3 w-16 rounded"
                      style={{
                        background:
                          "color-mix(in srgb, var(--shell-control-bg) 84%, var(--color-background) 16%)",
                      }}
                    ></div>
                  </div>
                </div>

                {/* Content */}
                <div className="space-y-3">
                  <p
                    className="dir-auto whitespace-pre-line text-sm"
                    style={headingStyle}
                  >
                    {message || "سيظهر نص منشورك هنا..."}
                  </p>

                  {linkUrl && activeTab === "LINK" && (
                    <div
                      className="rounded-lg border p-3"
                      style={{
                        ...panelStyle,
                        background:
                          "color-mix(in srgb, var(--shell-control-bg) 82%, var(--color-background) 18%)",
                      }}
                    >
                      <div
                        className="truncate text-sm"
                        style={{ color: "var(--color-primary)" }}
                      >
                        {linkUrl}
                      </div>
                      <div
                        className="mt-2 h-20 rounded"
                        style={{
                          background:
                            "color-mix(in srgb, var(--shell-control-bg) 78%, var(--color-background) 22%)",
                        }}
                      ></div>
                    </div>
                  )}

                  {/* Media Grid Preview */}
                  {mediaPreviews.length > 0 && (
                    <div
                      className={`grid gap-1 overflow-hidden rounded-lg border ${mediaPreviews.length === 1 ? "grid-cols-1" : "grid-cols-2"}`}
                      style={panelStyle}
                    >
                      {mediaPreviews.slice(0, 4).map((p, i) => (
                        <div
                          key={i}
                          className={`relative h-40 ${mediaPreviews.length === 3 && i === 0 ? "col-span-2" : ""}`}
                          style={{
                            background:
                              "color-mix(in srgb, var(--color-foreground) 82%, transparent)",
                          }}
                        >
                          {p.type === "video" ? (
                            <div
                              className="flex h-full w-full items-center justify-center"
                              style={{
                                background:
                                  "color-mix(in srgb, var(--color-foreground) 70%, transparent)",
                                color:
                                  "color-mix(in srgb, var(--color-background) 96%, transparent)",
                              }}
                            >
                              <VideoCameraIcon className="w-8 h-8" />
                            </div>
                          ) : (
                            <img
                              src={p.url}
                              className="w-full h-full object-cover"
                            />
                          )}
                        </div>
                      ))}
                      {mediaPreviews.length > 4 && (
                        <div
                          className="absolute inset-0 flex items-center justify-center text-xl font-bold"
                          style={{
                            background:
                              "color-mix(in srgb, var(--color-foreground) 42%, transparent)",
                            color:
                              "color-mix(in srgb, var(--color-background) 96%, transparent)",
                          }}
                        >
                          +{mediaPreviews.length - 4}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Results Area */}
          {result && (
            <div
              className="animate-fade-in overflow-hidden rounded-xl"
              style={{ ...panelStyle, ...successBannerStyle }}
            >
              <div
                className="p-4"
                style={{
                  ...successBannerStyle,
                  borderBottom:
                    "1px solid color-mix(in srgb, var(--business-success) 18%, transparent)",
                }}
              >
                <h3
                  className="flex items-center font-bold"
                  style={{ color: "var(--business-success)" }}
                >
                  <CheckCircleIcon className="w-5 h-5 ml-2" />
                  تمت العملية بنجاح!
                </h3>
              </div>
              <div className="p-4">
                <p className="mb-3 text-sm" style={headingStyle}>
                  {result.message}
                </p>
                <div className="space-y-2 max-h-60 overflow-y-auto">
                  {result.results.map((res: any, idx: number) => (
                    <div
                      key={idx}
                      className="rounded border p-2 text-xs"
                      style={
                        res.success ? successBannerStyle : errorBannerStyle
                      }
                    >
                      <div className="flex justify-between">
                        <span className="font-bold">{res.pageName}</span>
                        <span>
                          {res.success
                            ? isScheduled
                              ? "تمت الجدولة"
                              : "تم النشر"
                            : "فشل"}
                        </span>
                      </div>
                      {!res.success && (
                        <div
                          className="mt-1"
                          style={{ color: "var(--business-danger)" }}
                        >
                          {res.error}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default FacebookPostCreator;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  DollarSign,
  Plus,
  Check,
  X,
  Calendar,
  ChevronLeft,
  ChevronRight,
  TrendingUp,
  Search,
  Eye,
  Edit2,
  Trash,
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Card, CardContent } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import { Progress } from "../../components/ui/progress";
import api from "../../services/api";
import { toast } from "sonner";

interface AdvanceRequest {
  id: string;
  amount: number;
  reason: string;
  requestDate: string;
  createdAt: string;
  status: string;
  repaymentType: string;
  installmentsCount: number;
  monthlyAmount: number;
  approvedAt: string | null;
  remainingBalance?: number;
  isPaidOff?: boolean;
  employee: {
    id: string;
    firstName: string;
    lastName: string;
    employeeNumber: string;
    avatar: string;
    department: { name: string } | null;
    position: { title: string } | null;
  };
  installments: Array<{
    id: string;
    amount: number;
    dueDate: string;
    status: string;
    paidAt: string | null;
  }>;
}

const statusConfig: Record<string, { label: string; color: string }> = {
  PENDING: {
    label: "بانتظار الموافقة",
    color: "bg-yellow-100 text-yellow-800",
  },
  APPROVED: { label: "معتمد", color: "bg-blue-100 text-blue-800" },
  REJECTED: { label: "مرفوض", color: "bg-red-100 text-red-800" },
  COMPLETED: { label: "مكتمل", color: "bg-green-100 text-green-800" },
};

const Advances: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [requests, setRequests] = useState<AdvanceRequest[]>([]);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0,
  });
  const [statusFilter, setStatusFilter] = useState("all");
  const [payStatusFilter, setPayStatusFilter] = useState<"all" | "paid" | "unpaid">("all");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedRequest, setSelectedRequest] = useState<AdvanceRequest | null>(
    null,
  );
  const [isRejectDialogOpen, setIsRejectDialogOpen] = useState(false);
  const [rejectionReason, setRejectionReason] = useState("");
  const [isDetailsOpen, setIsDetailsOpen] = useState(false);
  const [isUpdateStatusDialogOpen, setIsUpdateStatusDialogOpen] =
    useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchAdvances();
    }, 500);
    return () => clearTimeout(timer);
  }, [pagination.page, statusFilter, searchTerm]);

  const fetchAdvances = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
      });

      if (statusFilter && statusFilter !== "all")
        params.append("status", statusFilter);
      if (searchTerm) params.append("search", searchTerm);

      const response = await api.get(`/hr/advances?${params}`);

      // التأكد من وجود البيانات
      const advancesData = response.data.data || [];
      setRequests(Array.isArray(advancesData) ? advancesData : []);

      if (response.data.pagination) {
        setPagination((prev) => ({
          ...prev,
          total: response.data.pagination.total,
          totalPages: response.data.pagination.totalPages,
        }));
      }
    } catch (error) {
      console.error("Error fetching advances:", error);
      toast.error("حدث خطأ أثناء جلب البيانات");
      setRequests([]); // تعيين array فاضي في حالة الخطأ
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id: string) => {
    try {
      await api.post(`/hr/advances/${id}/approve`);
      toast.success("تم الموافقة على الطلب");
      fetchAdvances();
    } catch (error: any) {
      toast.error(error.response?.data?.error || "حدث خطأ");
    }
  };

  const confirmReject = async () => {
    if (!selectedRequest) return;
    try {
      await api.post(`/hr/advances/${selectedRequest.id}/reject`, {
        rejectedReason: rejectionReason || "تم الرفض من قبل الإدارة",
      });
      toast.success("تم رفض الطلب");
      setIsRejectDialogOpen(false);
      setRejectionReason("");
      fetchAdvances();
    } catch (error: any) {
      toast.error(error.response?.data?.error || "حدث خطأ");
    }
  };

  const openRejectDialog = (request: AdvanceRequest) => {
    setSelectedRequest(request);
    setRejectionReason("");
    setIsRejectDialogOpen(true);
  };

  const openDetailsDialog = (request: AdvanceRequest) => {
    setSelectedRequest(request);
    setIsDetailsOpen(true);
  };

  const openUpdateStatusDialog = (request: AdvanceRequest) => {
    setSelectedRequest(request);
    setIsUpdateStatusDialogOpen(true);
  };

  const handleUpdateStatus = (status: "APPROVED" | "REJECTED") => {
    if (!selectedRequest) return;

    setIsUpdateStatusDialogOpen(false);

    if (status === "APPROVED") {
      handleApprove(selectedRequest.id);
    } else {
      openRejectDialog(selectedRequest);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا الطلب؟")) return;

    try {
      await api.delete(`/hr/advances/${id}`);
      toast.success("تم حذف الطلب بنجاح");
      fetchAdvances();
    } catch (error) {
      console.error("Error deleting advance:", error);
      toast.error("حدث خطأ أثناء حذف الطلب");
    }
  };


  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  const calculatePaidAmount = (installments: any[]) => {
    if (!installments || !Array.isArray(installments)) return 0;
    return installments
      .filter((i) => i.status === "PAID")
      .reduce((sum, i) => sum + parseFloat(i.amount), 0);
  };

  const calculateProgress = (request: AdvanceRequest) => {
    if (!request.installments || !Array.isArray(request.installments)) return 0;
    const paid = calculatePaidAmount(request.installments);
    return (paid / parseFloat(request.amount.toString())) * 100;
  };

  const calculateRemaining = (request: AdvanceRequest) => {
    const total = parseFloat(request.amount.toString());
    const paid = calculatePaidAmount(request.installments || []);
    const remaining = request.remainingBalance ?? total - paid;
    return remaining;
  };

  const isRequestPaid = (request: AdvanceRequest) => {
    return request.isPaidOff || calculateRemaining(request) <= 0;
  };

  const markAsPaid = async (id: string) => {
    try {
      await api.post(`/hr/advances/${id}/mark-paid`);
      toast.success("تم تعليم السلفة كمسددة");
      fetchAdvances();
    } catch (error: any) {
      toast.error(error.response?.data?.error || "فشل في تحديث حالة السلفة");
    }
  };

  // حساب الإحصائيات
  const stats = {
    total: requests?.length || 0,
    pending: requests?.filter((r) => r.status === "PENDING").length || 0,
    approved: requests?.filter((r) => r.status === "APPROVED").length || 0,
    totalAmount:
      requests?.reduce((sum, r) => sum + parseFloat(r.amount.toString()), 0) ||
      0,
  };

  return (
    <div
      className="p-6 space-y-6 min-h-screen bg-gradient-to-br from-[#f9fbff] via-[#f2f6ff] to-[#fff7fc] text-slate-900 dark:bg-gradient-to-br dark:from-slate-950 dark:via-slate-950 dark:to-slate-900 dark:text-white"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            إدارة السلف
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            متابعة طلبات السلف والأقساط
          </p>
        </div>
        <Button
          onClick={() => navigate("/hr/advances/new")}
          className="bg-white text-slate-900 dark:bg-slate-100 dark:text-slate-900 font-semibold shadow-md shadow-slate-300/40 hover:shadow-slate-400/50 border border-slate-200 hover:-translate-y-0.5 transition duration-150 rounded-full px-5"
        >
          <Plus className="h-4 w-4 ml-2" />
          طلب سلفة جديد
        </Button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          {
            title: "إجمالي الطلبات",
            value: stats.total,
            icon: <DollarSign className="h-8 w-8" />,
            tint: "from-sky-100 via-sky-50 to-white dark:from-slate-900 dark:via-slate-800 dark:to-slate-900",
            accent: "bg-sky-500",
            text: "text-slate-900",
          },
          {
            title: "بانتظار الموافقة",
            value: stats.pending,
            icon: <Calendar className="h-8 w-8" />,
            tint: "from-amber-100 via-amber-50 to-white dark:from-slate-900 dark:via-slate-800 dark:to-slate-900",
            accent: "bg-amber-500",
            text: "text-slate-900",
          },
          {
            title: "معتمد",
            value: stats.approved,
            icon: <Check className="h-8 w-8" />,
            tint: "from-emerald-100 via-emerald-50 to-white dark:from-slate-900 dark:via-slate-800 dark:to-slate-900",
            accent: "bg-emerald-500",
            text: "text-slate-900",
          },
          {
            title: "إجمالي المبالغ",
            value: formatCurrency(stats.totalAmount),
            icon: <TrendingUp className="h-8 w-8" />,
            tint: "from-indigo-100 via-indigo-50 to-white dark:from-slate-900 dark:via-slate-800 dark:to-slate-900",
            accent: "bg-indigo-500",
            text: "text-slate-900",
          },
        ].map((card) => (
          <Card
            key={card.title}
            className="relative overflow-hidden border border-slate-200 dark:border-white/10 bg-white/90 dark:bg-white/5 backdrop-blur shadow-lg shadow-slate-200 dark:shadow-slate-900/30 rounded-2xl transition-colors duration-200"
          >
            <div
              className={`absolute inset-0 bg-gradient-to-br ${card.tint}`}
            />
            <div className="absolute inset-0 bg-white/30 pointer-events-none" />
            <CardContent className="relative p-6 flex items-center justify-between">
              <div className="space-y-1">
                <p className="text-xs text-slate-600 dark:text-slate-200 uppercase tracking-[0.15em]">
                  {card.title}
                </p>
                <h3 className={`text-3xl font-black tracking-tight ${card.text} dark:text-white`}>
                  {card.value}
                </h3>
              </div>
              <div className={`h-12 w-12 rounded-xl ${card.accent} bg-opacity-90 text-white shadow-md shadow-slate-300/40 dark:shadow-black/30 flex items-center justify-center`}>
                {card.icon}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Filters & Search */}
      <Card className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-lg shadow-slate-200/60 dark:shadow-slate-900/40 rounded-2xl">
        <CardContent className="p-5 space-y-4">
          <div className="flex items-start justify-between gap-3">
            <div>
              <p className="text-xs uppercase tracking-[0.2em] text-slate-500 dark:text-slate-300">تصفية سريعة</p>
              <h3 className="text-xl font-bold mt-1 text-slate-900 dark:text-white">ابحث وفرّز طلبات السلف</h3>
            </div>
          </div>

          <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
            <div className="relative w-full md:w-1/2">
              <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 dark:text-slate-300 h-4 w-4" />
              <Input
                placeholder="بحث باسم الموظف..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pr-10 bg-white border border-slate-200 text-slate-900 placeholder:text-slate-400 focus:border-sky-300 focus:ring-2 focus:ring-sky-100 dark:bg-slate-800 dark:border-slate-700 dark:text-white dark:placeholder:text-slate-400 dark:focus:border-sky-500 dark:focus:ring-sky-900/40"
              />
            </div>

            <div className="flex flex-wrap items-center gap-2 justify-end w-full md:w-auto">
              {[
                { key: "all", label: "الكل" },
                { key: "PENDING", label: statusConfig.PENDING.label },
                { key: "APPROVED", label: statusConfig.APPROVED.label },
                { key: "COMPLETED", label: statusConfig.COMPLETED.label },
                { key: "REJECTED", label: statusConfig.REJECTED.label },
              ].map((item) => (
                <Button
                  key={item.key}
                  size="sm"
                  variant={statusFilter === item.key ? "default" : "outline"}
                  className={
                    statusFilter === item.key
                      ? "bg-slate-900 text-white hover:bg-slate-800"
                      : "bg-white border-slate-200 text-slate-700 hover:border-slate-300 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-100"
                  }
                  onClick={() => setStatusFilter(item.key)}
                >
                  {item.label}
                </Button>
              ))}
            </div>
          </div>

            <div className="flex flex-wrap gap-2 items-center">
              <span className="text-sm text-slate-600 dark:text-slate-300">حالة السداد:</span>
              {([
                { key: "all", label: "كل حالات السداد" },
                { key: "paid", label: "مسدد" },
                { key: "unpaid", label: "غير مسدد" },
              ] as const).map((item) => (
                <Button
                  key={item.key}
                  size="sm"
                  variant={payStatusFilter === item.key ? "default" : "outline"}
                  className={
                    payStatusFilter === item.key
                    ? "bg-emerald-500 text-white hover:bg-emerald-600 border-emerald-500"
                    : "bg-white border-slate-200 text-slate-700 hover:border-slate-300 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-100"
                  }
                  onClick={() => setPayStatusFilter(item.key as any)}
                >
                  {item.label}
                </Button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Requests Table */}
      <Card>
        <CardContent className="p-0">
          {loading ? (
            <div className="flex items-center justify-center h-64">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
            </div>
          ) : requests.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-gray-500">
              <DollarSign className="h-12 w-12 mb-4 opacity-50" />
              <p>لا توجد طلبات سلف</p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-right">الموظف</TableHead>
                  <TableHead className="text-right">التاريخ والوقت</TableHead>
                  <TableHead className="text-right">المبلغ</TableHead>
                  <TableHead className="text-right">المتبقي</TableHead>
                  <TableHead className="text-right">نوع السداد</TableHead>
                  <TableHead className="text-right">التقدم</TableHead>
                  <TableHead className="text-right">الحالة</TableHead>
                  <TableHead className="text-right">الإجراءات</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {requests
                  .filter((request) => {
                    const paid = isRequestPaid(request);
                    if (payStatusFilter === "paid") return paid;
                    if (payStatusFilter === "unpaid") return !paid;
                    return true;
                  })
                  .map((request) => (
                  <TableRow key={request.id}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar>
                          <AvatarImage src={request.employee?.avatar} />
                          <AvatarFallback>
                            {request.employee?.firstName?.[0]}
                            {request.employee?.lastName?.[0]}
                          </AvatarFallback>
                        </Avatar>
                        <div>
                          <p className="font-medium">
                            {request.employee?.firstName}{" "}
                            {request.employee?.lastName}
                          </p>
                          <p className="text-sm text-gray-500">
                            {request.employee?.position?.title}
                          </p>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span className="font-medium">
                          {new Date(
                            request.createdAt || request.requestDate,
                          ).toLocaleDateString("ar-EG")}
                        </span>
                        <span className="text-xs text-gray-500">
                          {new Date(
                            request.createdAt || request.requestDate,
                          ).toLocaleTimeString("ar-EG", {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className="font-bold">
                      {formatCurrency(request.amount)}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <span>{formatCurrency(Math.max(calculateRemaining(request), 0))}</span>
                        {isRequestPaid(request) ? (
                          <Badge className="bg-green-100 text-green-700 border-green-200">
                            مسدد
                          </Badge>
                        ) : (
                          <Badge variant="outline" className="text-amber-700 border-amber-200 bg-amber-50">
                            غير مسدد
                          </Badge>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      {request.repaymentType === "ONE_TIME"
                        ? "دفعة واحدة"
                        : `${request.installmentsCount} أقساط`}
                    </TableCell>
                    <TableCell>
                      {request.status === "APPROVED" && (
                        <div className="space-y-1">
                          <Progress
                            value={calculateProgress(request)}
                            className="h-2"
                          />
                          <p className="text-xs text-gray-500">
                            {formatCurrency(
                              calculatePaidAmount(request.installments),
                            )}{" "}
                            / {formatCurrency(request.amount)}
                          </p>
                        </div>
                      )}
                    </TableCell>
                    <TableCell>
                      <Badge
                        className={statusConfig[request.status]?.color || ""}
                      >
                        {statusConfig[request.status]?.label || request.status}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => openDetailsDialog(request)}
                          title="التفاصيل"
                        >
                          <Eye className="h-4 w-4 text-blue-600" />
                        </Button>
                        {request.status === "PENDING" ? (
                          <>
                            <Button
                              size="sm"
                              variant="outline"
                              className="text-green-600 hover:text-green-700 hover:bg-green-50 border-green-200"
                              onClick={() => handleApprove(request.id)}
                              title="موافقة"
                            >
                              <Check className="h-4 w-4" />
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              className="text-red-600 hover:text-red-700 hover:bg-red-50 border-red-200"
                              onClick={() => openRejectDialog(request)}
                              title="رفض"
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </>
                        ) : (
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => openUpdateStatusDialog(request)}
                            title="تعديل القرار"
                          >
                            <Edit2 className="h-4 w-4 text-gray-600 dark:text-gray-400" />
                          </Button>
                        )}
                        {!isRequestPaid(request) && request.status === "APPROVED" && (
                          <Button
                            size="sm"
                            variant="outline"
                            className="text-green-700 border-green-200 hover:bg-green-50"
                            onClick={() => markAsPaid(request.id)}
                            title="تعليم السلفة كمسددة"
                          >
                            <Check className="h-4 w-4 mr-1" />
                            تسوية
                          </Button>
                        )}
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => handleDelete(request.id)}
                          title="حذف"
                          className="text-red-600 hover:text-red-700 hover:bg-red-50"
                        >
                          <Trash className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>

        {/* Pagination */}
        {pagination.totalPages > 1 && (
          <div className="flex items-center justify-between p-4 border-t">
            <p className="text-sm text-gray-500">
              عرض {(pagination.page - 1) * pagination.limit + 1} -{" "}
              {Math.min(pagination.page * pagination.limit, pagination.total)}{" "}
              من {pagination.total}
            </p>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={pagination.page === 1}
                onClick={() =>
                  setPagination((prev) => ({ ...prev, page: prev.page - 1 }))
                }
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={pagination.page === pagination.totalPages}
                onClick={() =>
                  setPagination((prev) => ({ ...prev, page: prev.page + 1 }))
                }
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>
            </div>
          </div>
        )}
      </Card>

      {/* Reject Dialog */}
      <Dialog open={isRejectDialogOpen} onOpenChange={setIsRejectDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>رفض طلب السلفة</DialogTitle>
            <DialogDescription>
              الرجاء إدخال سبب الرفض للموظف.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <Textarea
              placeholder="سبب الرفض..."
              value={rejectionReason}
              onChange={(e) => setRejectionReason(e.target.value)}
            />
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsRejectDialogOpen(false)}
            >
              إلغاء
            </Button>
            <Button variant="destructive" onClick={confirmReject}>
              تأكيد الرفض
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Details Dialog */}
      <Dialog open={isDetailsOpen} onOpenChange={setIsDetailsOpen}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>تفاصيل السلفة</DialogTitle>
            <DialogDescription>تفاصيل الطلب وجدول الأقساط</DialogDescription>
          </DialogHeader>
          {selectedRequest && (
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-4 bg-gray-50 dark:bg-gray-800/50 p-4 rounded-lg border dark:border-gray-700">
                <div>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    المبلغ
                  </p>
                  <p className="font-bold text-lg text-gray-900 dark:text-white">
                    {formatCurrency(selectedRequest.amount)}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    نظام السداد
                  </p>
                  <p className="font-bold text-gray-900 dark:text-white">
                    {selectedRequest.repaymentType === "ONE_TIME"
                      ? "دفعة واحدة"
                      : "أقساط"}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    سبب الطلب
                  </p>
                  <p className="text-gray-900 dark:text-gray-100">
                    {selectedRequest.reason}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    تاريخ ووقت الطلب
                  </p>
                  <p className="text-gray-900 dark:text-gray-100">
                    {new Date(
                      selectedRequest.createdAt || selectedRequest.requestDate,
                    ).toLocaleString("ar-EG", {
                      dateStyle: "long",
                      timeStyle: "short",
                    })}
                  </p>
                </div>
              </div>

              {selectedRequest.repaymentType === "INSTALLMENTS" &&
                selectedRequest.installments?.length > 0 && (
                  <div>
                    <h4 className="font-bold mb-2 text-gray-900 dark:text-white">
                      جدول الأقساط
                    </h4>
                    <div className="border dark:border-gray-700 rounded-md overflow-hidden">
                      <Table>
                        <TableHeader>
                          <TableRow className="bg-gray-100 dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-800">
                            <TableHead className="text-right text-gray-700 dark:text-gray-300">
                              القسط
                            </TableHead>
                            <TableHead className="text-right text-gray-700 dark:text-gray-300">
                              تاريخ الاستحقاق
                            </TableHead>
                            <TableHead className="text-right text-gray-700 dark:text-gray-300">
                              المبلغ
                            </TableHead>
                            <TableHead className="text-right text-gray-700 dark:text-gray-300">
                              الحالة
                            </TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {selectedRequest.installments.map((inst, idx) => (
                            <TableRow
                              key={inst.id}
                              className="dark:border-gray-700"
                            >
                              <TableCell className="dark:text-gray-200">
                                {idx + 1}
                              </TableCell>
                              <TableCell className="dark:text-gray-200">
                                {new Date(inst.dueDate).toLocaleDateString(
                                  "ar-EG",
                                )}
                              </TableCell>
                              <TableCell className="dark:text-gray-200">
                                {formatCurrency(inst.amount)}
                              </TableCell>
                              <TableCell>
                                <Badge
                                  variant={
                                    inst.status === "PAID"
                                      ? "default"
                                      : "outline"
                                  }
                                >
                                  {inst.status === "PAID"
                                    ? "تم الدفع"
                                    : "مستحق"}
                                </Badge>
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  </div>
                )}
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Update Status Dialog */}
      <Dialog
        open={isUpdateStatusDialogOpen}
        onOpenChange={setIsUpdateStatusDialogOpen}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>تعديل حالة السلفة</DialogTitle>
            <DialogDescription>
              يمكنك تغيير الحالة الحالية للسلفة. يرجى توخي الحذر عند تغيير
              الحالات المعتمدة مسبقاً.
            </DialogDescription>
          </DialogHeader>
          <div className="flex gap-4 justify-center py-6">
            <Button
              className="w-full bg-green-600 hover:bg-green-700 text-white"
              onClick={() => handleUpdateStatus("APPROVED")}
            >
              <Check className="h-4 w-4 ml-2" />
              اعتماد السلفة
            </Button>
            <Button
              className="w-full bg-red-600 hover:bg-red-700 text-white"
              onClick={() => handleUpdateStatus("REJECTED")}
            >
              <X className="h-4 w-4 ml-2" />
              رفض السلفة
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Advances;

import React, { useState, useEffect, useMemo } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Clock,
  Calendar,
  ArrowRight,
  UserPlus,
  Check,
  AlertCircle,
  Search,
  ShieldCheck,
  Briefcase,
  X,
  CalendarRange,
  AlertTriangle,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Badge } from "../../components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import api from "../../services/api";
import { toast } from "sonner";

interface Shift {
  id: string;
  name: string;
  startTime: string;
  endTime: string;
  color: string;
}

interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  avatar?: string;
  employeeNumber?: string;
  isActive?: boolean;
  department?: {
    id: string;
    name: string;
  };
  position?: {
    id: string;
    title: string;
  };
}

interface Assignment {
  id: string;
  date: string;
  user: {
    id: string;
    firstName: string;
    lastName: string;
    employeeNumber?: string;
  };
}

const AssignShift: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [shift, setShift] = useState<Shift | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [existingAssignments, setExistingAssignments] = useState<Assignment[]>(
    [],
  );
  const [selectedEmployeeIds, setSelectedEmployeeIds] = useState<string[]>([]);
  const [assignmentDate, setAssignmentDate] = useState<string>(
    () => new Date().toISOString().split("T")[0],
  );
  const [endDate, setEndDate] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [departmentFilter, setDepartmentFilter] = useState<string>("all");
  const [positionFilter, setPositionFilter] = useState<string>("all");
  const [dateRangeMode, setDateRangeMode] = useState(false);

  useEffect(() => {
    if (id) {
      fetchData();
    }
  }, [id]);

  const fetchData = async () => {
    if (!id) return;

    try {
      setLoading(true);
      const [shiftRes, employeesRes] = await Promise.all([
        api.get(`/hr/shifts/${id}`),
        api.get("/hr/employees?limit=1000&status=ACTIVE"),
      ]);

      setShift(shiftRes.data.shift);
      setEmployees(employeesRes.data.employees || []);

      // Fetch existing assignments for the selected date
      if (assignmentDate) {
        fetchExistingAssignments(assignmentDate);
      }
    } catch (error) {
      console.error("Error fetching data:", error);
      toast.error("فشل في جلب البيانات المطلوبة");
    } finally {
      setLoading(false);
    }
  };

  const fetchExistingAssignments = async (date: string) => {
    try {
      const response = await api.get(`/hr/shifts/${id}`);
      const assignments =
        response.data.shift?.assignments?.filter(
          (a: Assignment) => a.date.split("T")[0] === date,
        ) || [];
      setExistingAssignments(assignments);
    } catch (error) {
      console.error("Error fetching assignments:", error);
    }
  };

  useEffect(() => {
    if (assignmentDate && id) {
      fetchExistingAssignments(assignmentDate);
    }
  }, [assignmentDate, id]);

  const handleAssign = async () => {
    if (selectedEmployeeIds.length === 0 || !assignmentDate) {
      toast.error("يرجى اختيار موظف واحد على الأقل والتاريخ");
      return;
    }

    // Check for duplicate assignments
    const alreadyAssigned = selectedEmployeeIds.filter((empId) =>
      existingAssignments.some((a) => a.user?.id === empId),
    );

    if (alreadyAssigned.length > 0 && !dateRangeMode) {
      const employee = employees.find((e) => e.id === alreadyAssigned[0]);
      toast.error(
        `الموظف ${employee?.firstName} ${employee?.lastName} معيّن بالفعل في هذا التاريخ`,
      );
      return;
    }

    try {
      setSubmitting(true);

      if (dateRangeMode && endDate) {
        // Assign for date range
        const dates = getDateRange(assignmentDate, endDate);
        const promises = selectedEmployeeIds.flatMap((userId) =>
          dates.map((date) =>
            api.post("/hr/shifts/assign", {
              shiftId: id,
              userId,
              date,
            }),
          ),
        );
        await Promise.all(promises);
        toast.success(
          `تم تعيين ${selectedEmployeeIds.length} موظف لـ ${dates.length} يوم`,
        );
      } else {
        // Single or bulk assignment for one date
        const promises = selectedEmployeeIds.map((userId) =>
          api.post("/hr/shifts/assign", {
            shiftId: id,
            userId,
            date: assignmentDate,
          }),
        );
        await Promise.all(promises);
        toast.success(`تم تعيين ${selectedEmployeeIds.length} موظف بنجاح`);
      }

      navigate(`/hr/shifts/${id}`);
    } catch (error: any) {
      console.error("Error assigning shift:", error);
      toast.error(error.response?.data?.error || "فشل في تعيين المناوبة");
    } finally {
      setSubmitting(false);
    }
  };

  const getDateRange = (start: string, end: string): string[] => {
    const dates: string[] = [];
    const startDate = new Date(start);
    const endDate = new Date(end);

    for (
      let d = new Date(startDate);
      d <= endDate;
      d.setDate(d.getDate() + 1)
    ) {
      dates.push(new Date(d).toISOString().split("T")[0]);
    }

    return dates;
  };

  const toggleEmployeeSelection = (empId: string) => {
    setSelectedEmployeeIds((prev) =>
      prev.includes(empId)
        ? prev.filter((id) => id !== empId)
        : [...prev, empId],
    );
  };

  const departments = useMemo(() => {
    const depts = new Set(
      employees.map((e) => e.department?.name).filter(Boolean),
    );
    return Array.from(depts);
  }, [employees]);

  const positions = useMemo(() => {
    const pos = new Set(
      employees.map((e) => e.position?.title).filter(Boolean),
    );
    return Array.from(pos);
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    return employees.filter((emp) => {
      const matchesSearch =
        `${emp.firstName} ${emp.lastName} ${emp.employeeNumber || ""}`
          .toLowerCase()
          .includes(searchTerm.toLowerCase());

      const matchesDepartment =
        departmentFilter === "all" || emp.department?.name === departmentFilter;
      const matchesPosition =
        positionFilter === "all" || emp.position?.title === positionFilter;

      // Filter out already assigned employees - with null check for user
      const isAlreadyAssigned = existingAssignments.some(
        (a) => a.user && a.user.id === emp.id,
      );

      return (
        matchesSearch &&
        matchesDepartment &&
        matchesPosition &&
        !isAlreadyAssigned
      );
    });
  }, [
    employees,
    searchTerm,
    departmentFilter,
    positionFilter,
    existingAssignments,
  ]);

  const assignedEmployeeNames = useMemo(() => {
    return existingAssignments
      .filter((a) => a.user)
      .map((a) => `${a.user.firstName} ${a.user.lastName}`)
      .join("، ");
  }, [existingAssignments]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!shift) {
    return (
      <div className="p-6 text-center">
        <AlertCircle className="h-12 w-12 mx-auto text-red-500 mb-4" />
        <h2 className="text-xl font-bold">المناوبة غير موجودة</h2>
        <Button onClick={() => navigate("/hr/shifts")} className="mt-4">
          العودة للمناوبات
        </Button>
      </div>
    );
  }

  return (
    <div className="w-full p-4 md:p-6 space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate(`/hr/shifts/${id}`)}
            className="rounded-full hover:bg-gray-100 dark:hover:bg-gray-800"
          >
            <ArrowRight className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold">تعيين مناوبة</h1>
            <p className="text-muted-foreground text-sm">
              اختر موظف أو عدة موظفين لتعيينهم في المناوبة
            </p>
          </div>
        </div>
        <Button
          variant={dateRangeMode ? "default" : "outline"}
          size="sm"
          onClick={() => setDateRangeMode(!dateRangeMode)}
        >
          <CalendarRange className="h-4 w-4 ml-2" />
          {dateRangeMode ? "إلغاء نطاق التاريخ" : "نطاق تاريخ"}
        </Button>
      </div>

      {/* Existing Assignments Alert */}
      {existingAssignments.length > 0 && (
        <Card className="border-orange-200 bg-orange-50 dark:bg-orange-900/20">
          <CardContent className="pt-4">
            <div className="flex items-start gap-3">
              <AlertTriangle className="h-5 w-5 text-orange-600 mt-0.5" />
              <div className="flex-1">
                <p className="font-semibold text-orange-900 dark:text-orange-200">
                  موظفين معينين بالفعل في {assignmentDate}
                </p>
                <p className="text-sm text-orange-700 dark:text-orange-300 mt-1">
                  {assignedEmployeeNames}
                </p>
                <p className="text-xs text-orange-600 dark:text-orange-400 mt-2">
                  هؤلاء الموظفين مخفيون من القائمة لتجنب التعيين المكرر
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Shift Details Card */}
        <Card className="md:col-span-1 border-primary/20 bg-primary/5">
          <CardHeader className="pb-3">
            <CardTitle className="text-lg flex items-center gap-2">
              <Clock className="h-5 w-5 text-primary" />
              تفاصيل المناوبة
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between p-3 bg-white dark:bg-gray-900 rounded-lg border border-primary/10 shadow-sm">
              <span className="text-sm font-medium">{shift.name}</span>
              <div
                className="w-3 h-3 rounded-full shadow-sm"
                style={{ backgroundColor: shift.color }}
              />
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between text-sm px-1">
                <span className="text-muted-foreground">وقت البدء</span>
                <span className="font-bold text-primary">
                  {shift.startTime}
                </span>
              </div>
              <div className="flex items-center justify-between text-sm px-1">
                <span className="text-muted-foreground">وقت الانتهاء</span>
                <span className="font-bold text-primary">{shift.endTime}</span>
              </div>
            </div>

            <div className="pt-4 border-t border-primary/10">
              <div className="flex items-center gap-2 text-xs text-muted-foreground bg-primary/10 p-2 rounded">
                <ShieldCheck className="h-3 w-3" />
                <span>سيتم تسجيل هذا التعيين في ملف الموظف</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Assignment Form Card */}
        <Card className="md:col-span-2 shadow-lg border-none ring-1 ring-gray-200 dark:ring-gray-800">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <UserPlus className="h-5 w-5 text-green-500" />
              بيانات التعيين
            </CardTitle>
            <CardDescription>
              اختر الموظف والتاريخ لإتمام العملية
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Filters */}
            <div className="flex items-center gap-3">
              <div className="flex-1">
                <Label className="text-xs text-muted-foreground">القسم</Label>
                <Select
                  value={departmentFilter}
                  onValueChange={setDepartmentFilter}
                >
                  <SelectTrigger className="h-9">
                    <SelectValue placeholder="كل الأقسام" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">كل الأقسام</SelectItem>
                    {departments.map((dept) => (
                      <SelectItem key={dept || ""} value={dept || ""}>
                        {dept || ""}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex-1">
                <Label className="text-xs text-muted-foreground">المنصب</Label>
                <Select
                  value={positionFilter}
                  onValueChange={setPositionFilter}
                >
                  <SelectTrigger className="h-9">
                    <SelectValue placeholder="كل المناصب" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">كل المناصب</SelectItem>
                    {positions.map((pos) => (
                      <SelectItem key={pos || ""} value={pos || ""}>
                        {pos || ""}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              {(departmentFilter !== "all" || positionFilter !== "all") && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => {
                    setDepartmentFilter("all");
                    setPositionFilter("all");
                  }}
                  className="mt-5"
                >
                  <X className="h-4 w-4" />
                </Button>
              )}
            </div>

            {/* Employee Selection */}
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-semibold">
                  الموظفين{" "}
                  {selectedEmployeeIds.length > 0 &&
                    `(${selectedEmployeeIds.length} محدد)`}
                </Label>
                <Badge variant="secondary">
                  {filteredEmployees.length} متاح
                </Badge>
              </div>
              <div className="relative">
                <Search className="absolute right-3 top-3 h-4 w-4 text-muted-foreground pointer-events-none" />
                <Input
                  placeholder="ابحث عن الموظف باسمه أو رقمه..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pr-10 bg-gray-50/50 focus:bg-white dark:bg-gray-800/50"
                />
              </div>

              <div className="border rounded-xl overflow-hidden bg-gray-50/30 dark:bg-gray-900/30 max-h-[350px] overflow-y-auto">
                {filteredEmployees.length > 0 ? (
                  <div className="divide-y divide-gray-100 dark:divide-gray-800">
                    {filteredEmployees.map((emp) => {
                      const isSelected = selectedEmployeeIds.includes(emp.id);
                      return (
                        <div
                          key={emp.id}
                          onClick={() => toggleEmployeeSelection(emp.id)}
                          className={`flex items-center justify-between p-3 cursor-pointer transition-all hover:bg-primary/5 ${
                            isSelected
                              ? "bg-primary/10 border-r-4 border-primary"
                              : ""
                          }`}
                        >
                          <div className="flex items-center gap-3">
                            <Avatar className="h-10 w-10 border-2 border-white dark:border-gray-800 shadow-sm">
                              <AvatarImage src={emp.avatar} />
                              <AvatarFallback className="bg-primary/10 text-primary">
                                {emp.firstName[0]}
                                {emp.lastName[0]}
                              </AvatarFallback>
                            </Avatar>
                            <div className="text-right">
                              <div className="flex items-center gap-2">
                                <p className="text-sm font-bold">
                                  {emp.firstName} {emp.lastName}
                                </p>
                                {emp.employeeNumber && (
                                  <Badge
                                    variant="outline"
                                    className="text-[10px] px-1 py-0"
                                  >
                                    #{emp.employeeNumber}
                                  </Badge>
                                )}
                              </div>
                              <div className="flex items-center gap-2 text-[10px] text-muted-foreground mt-1">
                                <span className="flex items-center gap-1">
                                  <Briefcase className="h-3 w-3" />
                                  {emp.department?.name || "بدون قسم"}
                                </span>
                                {emp.position?.title && (
                                  <>
                                    <span>•</span>
                                    <span>{emp.position.title}</span>
                                  </>
                                )}
                              </div>
                            </div>
                          </div>
                          {isSelected && (
                            <div className="bg-primary text-white p-1 rounded-full">
                              <Check className="h-3 w-3" />
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="p-8 text-center text-muted-foreground italic text-sm">
                    لا يوجد موظفين يطابقون البحث
                  </div>
                )}
              </div>
            </div>

            {/* Date Selection */}
            <div className="space-y-3">
              <Label className="text-sm font-semibold flex items-center gap-2">
                <Calendar className="h-4 w-4 text-orange-500" />
                {dateRangeMode ? "نطاق التاريخ" : "تاريخ العمل"}
              </Label>
              <div className={dateRangeMode ? "grid grid-cols-2 gap-3" : ""}>
                <div>
                  {dateRangeMode && (
                    <Label className="text-xs text-muted-foreground mb-1">
                      من
                    </Label>
                  )}
                  <Input
                    type="date"
                    value={assignmentDate}
                    onChange={(e) => {
                      setAssignmentDate(e.target.value);
                      // Reset existing assignments when date changes to prevent stale data from filtering
                      setExistingAssignments([]);
                    }}
                    className="bg-gray-50/50 dark:bg-gray-800/50"
                  />
                </div>
                {dateRangeMode && (
                  <div>
                    <Label className="text-xs text-muted-foreground mb-1">
                      إلى
                    </Label>
                    <Input
                      type="date"
                      value={endDate}
                      onChange={(e) => setEndDate(e.target.value)}
                      min={assignmentDate}
                      className="bg-gray-50/50 dark:bg-gray-800/50"
                    />
                  </div>
                )}
              </div>
              <p className="text-[10px] text-muted-foreground px-1">
                {dateRangeMode
                  ? "* سيتم تعيين الموظفين المحددين لجميع الأيام في النطاق المحدد"
                  : "* يمكنك تعيين المناوبة للموظفين في هذا اليوم"}
              </p>
            </div>

            {/* Summary */}
            {selectedEmployeeIds.length > 0 && (
              <Card className="bg-blue-50 dark:bg-blue-900/20 border-blue-200">
                <CardContent className="pt-4">
                  <div className="flex items-start gap-3">
                    <Check className="h-5 w-5 text-blue-600 mt-0.5" />
                    <div className="flex-1 text-sm">
                      <p className="font-semibold text-blue-900 dark:text-blue-200">
                        ملخص التعيين
                      </p>
                      <p className="text-blue-700 dark:text-blue-300 mt-1">
                        {selectedEmployeeIds.length} موظف
                        {dateRangeMode && endDate
                          ? ` × ${getDateRange(assignmentDate, endDate).length} يوم = ${selectedEmployeeIds.length * getDateRange(assignmentDate, endDate).length} تعيين`
                          : " × 1 يوم = " +
                            selectedEmployeeIds.length +
                            " تعيين"}
                      </p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}

            {/* Action Buttons */}
            <div className="pt-4 flex gap-3">
              <Button
                onClick={handleAssign}
                disabled={
                  submitting ||
                  selectedEmployeeIds.length === 0 ||
                  (dateRangeMode && !endDate)
                }
                className="flex-1 h-12 text-lg font-bold shadow-lg shadow-primary/20 transition-all hover:scale-[1.02]"
              >
                {submitting
                  ? "جاري الحفظ..."
                  : `تأكيد التعيين (${selectedEmployeeIds.length})`}
              </Button>
              <Button
                variant="outline"
                onClick={() => navigate(`/hr/shifts/${id}`)}
                className="h-12 border-gray-200 dark:border-gray-800"
              >
