              month: "long",
              day: "numeric",
            }, "-", attendanceTimezone)}
          </p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={() => { resetManualForm(); setShowManualDialog(true); }} className="bg-blue-600 text-white hover:bg-blue-700">
            <Clock className="h-4 w-4 ml-2" /> تسجيل يدوي
          </Button>
          <Button variant="outline" onClick={handleExport}>
            <Download className="h-4 w-4 ml-2" /> تصدير
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: "إجمالي الموظفين", value: todayStats?.totalEmployees, icon: UserCheck, color: "text-gray-600", bg: "bg-gray-100" },
          { label: "حاضر", value: todayStats?.present, icon: CheckCircle, color: "text-green-600", bg: "bg-green-100" },
          { label: "متأخر", value: todayStats?.late, icon: AlertCircle, color: "text-yellow-600", bg: "bg-yellow-100" },
          { label: "غائب", value: todayStats?.absent, icon: XCircle, color: "text-red-600", bg: "bg-red-100" },
        ].map((stat, i) => (
          <Card key={i}>
            <CardContent className="p-6 flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">{stat.label}</p>
                <h3 className={`text-3xl font-bold ${stat.color}`}>{stat.value || 0}</h3>
              </div>
              <div className={`p-3 ${stat.bg} rounded-full`}><stat.icon className={`h-6 w-6 ${stat.color}`} /></div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card className="border-amber-100 bg-gradient-to-l from-amber-50 via-white to-white">
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <AlertCircle className="h-4 w-4 text-amber-600" />
            مراجعة الإغلاق التلقائي
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
            {[
              { label: "إجمالي مغلق تلقائيًا", value: autoCloseSummary.total, accent: "text-amber-700 bg-amber-100" },
              { label: "بانتظار المراجعة", value: autoCloseSummary.pending, accent: "text-amber-700 bg-amber-100" },
              { label: "تمت المراجعة", value: autoCloseSummary.reviewed, accent: "text-sky-700 bg-sky-100" },
              { label: "تم التعديل", value: autoCloseSummary.adjusted, accent: "text-emerald-700 bg-emerald-100" },
              { label: "اعتماد كما هو", value: autoCloseSummary.dismissed, accent: "text-slate-700 bg-slate-100" },
            ].map((item) => (
              <div key={item.label} className="rounded-xl border border-gray-100 bg-white p-4 shadow-sm">
                <div className={`inline-flex rounded-full px-2.5 py-1 text-xs font-bold ${item.accent}`}>
                  {item.label}
                </div>
                <div className="mt-3 text-3xl font-black text-gray-900">{item.value || 0}</div>
              </div>
            ))}
          </div>
          <div className="flex flex-wrap gap-3">
            <Button
              variant={autoClosedOnly ? "default" : "outline"}
              onClick={() => {
                setAutoClosedOnly(true);
                setPagination((p) => ({ ...p, page: 1 }));
              }}
              className={autoClosedOnly ? "bg-amber-600 hover:bg-amber-700" : ""}
            >
              السجلات المغلقة تلقائيًا
            </Button>
            <Button
              variant="outline"
              onClick={() => {
                setAutoClosedOnly(true);
                setAutoCloseReviewStatus("PENDING");
                setPagination((p) => ({ ...p, page: 1 }));
              }}
            >
              السجلات المنتظرة
            </Button>
            <Button
              variant="outline"
              onClick={() => {
                setAutoClosedOnly(false);
                setAutoCloseReviewStatus("ALL");
                setPagination((p) => ({ ...p, page: 1 }));
              }}
            >
              عرض كل السجلات
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardContent className="p-6 flex flex-col md:flex-row gap-4 justify-between items-center">
          <div className="flex flex-wrap gap-4 items-center">
            <Input type="date" value={selectedDate} onChange={(e) => { setSelectedDate(e.target.value); setPagination((p) => ({ ...p, page: 1 })); }} className="w-[160px]" />
            <div className="flex items-center gap-2">
              <input type="checkbox" id="useRange" checked={useDateRange} onChange={(e) => { setUseDateRange(e.target.checked); setPagination((p) => ({ ...p, page: 1 })); }} className="rounded" />
              <label htmlFor="useRange" className="text-sm cursor-pointer">فترة زمنية</label>
            </div>
            {useDateRange && <Input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value); setPagination((p) => ({ ...p, page: 1 })); }} className="w-[160px]" min={selectedDate} />}
          </div>
          <div className="flex flex-wrap gap-4">
            <Select
              value={statusFilter}
              onValueChange={(value) => { setStatusFilter(value ?? "ALL"); setPagination((p) => ({ ...p, page: 1 })); }}
            >
              <SelectTrigger className="w-[150px]"><SelectValue placeholder="الحالة" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="ALL">الكل</SelectItem>
                <SelectItem value="PRESENT">حاضر</SelectItem>
                <SelectItem value="LATE">متأخر</SelectItem>
                <SelectItem value="ABSENT">غائب</SelectItem>
                <SelectItem value="HALF_DAY">نصف يوم</SelectItem>
                <SelectItem value="ON_LEAVE">إجازة</SelectItem>
                <SelectItem value="HOLIDAY">عطلة</SelectItem>
                <SelectItem value="REMOTE">عن بُعد</SelectItem>
              </SelectContent>
            </Select>
            <select
              value={employeeId || "all"}
              onChange={(e) => { 
                const v = e.target.value; 
                setEmployeeId(v && v !== "all" ? v : ""); 
                setPagination((p) => ({ ...p, page: 1 })); 
              }}
              className="flex h-10 w-[200px] items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-blue-600 focus:border-blue-600"
            >
              <option value="all">الكل</option>
              {employees.map(emp => <option key={emp.id} value={emp.id}>{emp.firstName} {emp.lastName}</option>)}
            </select>
            <div className="flex items-center gap-2 rounded-md border border-input bg-background px-3 py-2">
              <input
                type="checkbox"
                id="autoClosedOnly"
                checked={autoClosedOnly}
                onChange={(e) => {
                  setAutoClosedOnly(e.target.checked);
                  setPagination((p) => ({ ...p, page: 1 }));
                }}
                className="rounded"
              />
              <label htmlFor="autoClosedOnly" className="text-sm cursor-pointer">
                الإغلاق التلقائي فقط
              </label>
            </div>
            <Select
              value={autoCloseReviewStatus}
              onValueChange={(value) => {
                setAutoCloseReviewStatus((value as "ALL" | AutoCloseReviewStatus) || "ALL");
                setPagination((p) => ({ ...p, page: 1 }));
              }}
            >
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="حالة المراجعة" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="ALL">كل المراجعات</SelectItem>
                <SelectItem value="PENDING">بانتظار المراجعة</SelectItem>
                <SelectItem value="REVIEWED">تمت المراجعة</SelectItem>
                <SelectItem value="ADJUSTED">تم التعديل</SelectItem>
                <SelectItem value="DISMISSED">اعتماد كما هو</SelectItem>
              </SelectContent>
            </Select>
            <Button
              variant="outline"
              onClick={() => {
                setSelectedDate(getLocalDateString());
                setEndDate(getLocalDateString());
                setUseDateRange(false);
                setStatusFilter("ALL");
                setEmployeeId("");
                setAutoClosedOnly(false);
                setAutoCloseReviewStatus("ALL");
                setPagination((p) => ({ ...p, page: 1 }));
              }}
            >
              <XCircle className="h-4 w-4" />
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle>سجل الحضور</CardTitle></CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div></div>
          ) : records.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-gray-500"><Clock className="h-12 w-12 mb-4 opacity-50" /><p>لا توجد سجلات</p></div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-right">الموظف</TableHead>
                  <TableHead className="text-right">اليوم والتاريخ</TableHead>
                  <TableHead className="text-right">القسم</TableHead>
                  <TableHead className="text-right">الحضور</TableHead>
                  <TableHead className="text-right">الانصراف</TableHead>
                  <TableHead className="text-right">الموقع</TableHead>
                  <TableHead className="text-right">ساعات العمل</TableHead>
                  <TableHead className="text-right">ساعات إضافية</TableHead>
                  <TableHead className="text-right">التأخير</TableHead>
                  <TableHead className="text-right">الحالة</TableHead>
                  <TableHead className="text-right w-[120px]">التحكم</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {records.map(record => (
                  <TableRow key={record.id} className="hover:bg-gray-50/50">
                    <TableCell>
                      <div className="flex items-center gap-3 font-arabic">
                        <Avatar className="h-9 w-9 border border-gray-200">
                          <AvatarImage src={record.employee?.avatar} />
                          <AvatarFallback className="bg-blue-50 text-blue-700">
                            {record.employee?.firstName?.[0]}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex flex-col">
                          <p className="font-bold text-gray-900 text-sm">{record.employee?.firstName} {record.employee?.lastName}</p>
                          <p className="text-[10px] text-gray-500 font-mono tracking-wider">{record.employee?.employeeNumber}</p>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col gap-0.5">
                        <span className="font-bold text-gray-800 text-xs">
                          {formatAttendanceDate(record.date, { weekday: "long" }, "-", attendanceTimezone)}
                        </span>
                        <span className="text-[10px] text-gray-500">
                          {formatAttendanceDate(record.date, {
                            year: "numeric",
                            month: "2-digit",
                            day: "2-digit",
                          }, "-", attendanceTimezone)}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className="font-medium bg-gray-50 text-gray-600 border-gray-200">
                        {record.employee?.department?.name || "بدون قسم"}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {record.checkIn ? (
                        <div className="flex flex-col">
                          <span className="text-green-600 font-bold text-sm">
                            {formatAttendanceTime(record.checkIn)}
                          </span>
                        </div>
                      ) : (
                        <span className="text-gray-300">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {record.checkOut ? (
                        <div className="flex flex-col">
                          <span className="text-blue-600 font-bold text-sm">
                            {formatAttendanceTime(record.checkOut)}
                          </span>
                        </div>
                      ) : (
                        <span className="text-gray-300">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {renderLocationInfo(record.checkInLocation, record.checkOutLocation, record.workMode)}
                    </TableCell>
                    <TableCell>
                      {record.workHours ? (
                        <span className="font-bold text-gray-700">{Number(record.workHours).toFixed(1)} س</span>
                      ) : (
                        <span className="text-gray-300">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {record.overtimeHours && Number(record.overtimeHours) > 0 ? (
                        <span className="text-indigo-600 font-black">{Number(record.overtimeHours).toFixed(1)} س</span>
                      ) : (
                        <span className="text-gray-300">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {record.lateMinutes && record.lateMinutes > 0 ? (
                        <div className="flex flex-col leading-none">
                          <span className="text-red-600 font-black text-sm">
                            {Math.floor(record.lateMinutes / 60) > 0 && `${Math.floor(record.lateMinutes / 60)}س `}
                            {record.lateMinutes % 60}د
                          </span>
                        </div>
                      ) : (
                        <span className="text-green-500 font-bold opacity-30">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col gap-2">
                        <Badge className={`${statusConfig[record.status]?.color} font-bold px-3 w-fit`}>
                          {statusConfig[record.status]?.label}
                        </Badge>
                        {record.isAutoClosed && record.autoCloseAudit && record.autoCloseAudit.isAutoClosed && (
                          <>
                            <Badge className="bg-amber-100 text-amber-800 font-bold px-3 w-fit">
                              مغلق تلقائيًا
                            </Badge>
                            <Badge
                              className={`${autoCloseReviewConfig[record.autoCloseAudit.reviewStatus]?.color} font-bold px-3 w-fit`}
                            >
                              {autoCloseReviewConfig[record.autoCloseAudit.reviewStatus]?.label}
                            </Badge>
                            <div className="text-[10px] leading-4 text-gray-500">
                              <div>
                                السبب: {getAutoCloseReasonLabel(record.autoCloseAudit.autoCloseReason)}
                              </div>
                              <div>
                                وقت الإغلاق: {formatAttendanceTime(record.autoCloseAudit.scheduledCheckOut)}
                              </div>
                            </div>
                          </>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        {record.checkIn && !record.checkOut && !record.id.startsWith("temp-") && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="h-8 gap-1.5 bg-orange-50 text-orange-600 border-orange-100 hover:bg-orange-600 hover:text-white"
                            onClick={() => handleCheckOut(record.employee.id)}
                          >
                            <Clock className="h-3.5 w-3.5" />
                            <span>انصراف</span>
                          </Button>
                        )}
                        {!record.checkIn && record.id.startsWith("temp-") && (
                          <button
                            type="button"
                            className="p-2 rounded-lg bg-green-50 text-green-600 hover:bg-green-600 hover:text-white transition-all border border-green-100"
                            onClick={() => handleCheckIn(record.employee.id)}
                            title="تسجيل حضور الآن"
                          >
                            <UserCheck className="h-4 w-4" />
                          </button>
                        )}
                        {record.notes && (
                          <button
                            type="button"
                            className="p-2 rounded-lg bg-gray-50 text-gray-600 hover:bg-gray-600 hover:text-white transition-all border border-gray-100"
                            onClick={() => {
                              setSelectedNotes(record.notes || "");
                              setShowNotesDialog(true);
                            }}
                            title="عرض الملاحظات"
                          >
                            <Eye className="h-4 w-4" />
                          </button>
                        )}
                        {record.isAutoClosed && record.autoCloseAudit && record.autoCloseAudit.isAutoClosed && (
                          <button
                            type="button"
                            className="p-2 rounded-lg bg-amber-50 text-amber-700 hover:bg-amber-600 hover:text-white transition-all border border-amber-100"
                            onClick={() => openAutoCloseReview(record)}
                            title="مراجعة الإغلاق التلقائي"
                          >
                            <AlertCircle className="h-4 w-4" />
                          </button>
                        )}
                        <button
                          type="button"
                          className="p-2 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white transition-all border border-blue-100"
                          onClick={() => handleEditClick(record)}
                          title="تعديل"
                        >
                          <Pencil className="h-4 w-4" />
                        </button>
                        <button
                          type="button"
                          className="p-2 rounded-lg bg-red-50 text-red-600 hover:bg-red-600 hover:text-white transition-all border border-red-100"
                          onClick={() => confirmDelete(record.id)}
                          title="حذف"
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
          {pagination.totalPages > 1 && records.length > 0 && (
            <div className="p-4 border-t flex items-center justify-between" dir="rtl">
              <span className="text-sm text-gray-500 font-medium">
                صفحة {pagination.page} من {pagination.totalPages} ({pagination.total} سجل)
              </span>
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  className="gap-1"
                  onClick={() => setPagination((p) => ({ ...p, page: Math.max(1, p.page - 1) }))}
                  disabled={pagination.page === 1}
                >
                  <ChevronRight className="h-4 w-4" /> السابق
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="gap-1"
                  onClick={() => setPagination((p) => ({ ...p, page: Math.min(p.totalPages, p.page + 1) }))}
                  disabled={pagination.page === pagination.totalPages}
                >
                  التالي <ChevronLeft className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={showManualDialog} onOpenChange={(open) => { if (!open) resetManualForm(); setShowManualDialog(open); }}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader><DialogTitle>{isEditMode ? "تعديل سجل حضور" : "تسجيل حضور يدوي"}</DialogTitle></DialogHeader>
          <div className="space-y-4 py-4" dir="rtl">
            <div className="space-y-2">
              <Label>الموظف <span className="text-red-500">*</span></Label>
              <select
                value={manualForm.employeeId}
                onChange={(e) => setManualForm({ ...manualForm, employeeId: e.target.value })}
                className="flex h-10 w-full items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-blue-600 focus:border-blue-600"
              >
                <option value="" disabled>اختر موظف</option>
                {employees.map(emp => <option key={emp.id} value={emp.id}>{emp.firstName} {emp.lastName} - {emp.employeeNumber}</option>)}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2"><Label>التاريخ</Label><Input type="date" value={manualForm.date} onChange={(e) => setManualForm({ ...manualForm, date: e.target.value })} /></div>
              <div className="space-y-2">
                <div className="flex items-center justify-between mb-2">
                  <Label>الحالة</Label>
                  <label className="flex items-center gap-1.5 cursor-pointer">
                    <input 
                      type="checkbox" 
                      className="rounded border-gray-300 text-blue-600 shadow-sm w-3 h-3 focus:ring-blue-500"
                      checked={manualOverrides.status}
                      onChange={(e) => setManualOverrides(prev => ({ ...prev, status: e.target.checked }))}
                    />
                    <span className="text-[10px] text-gray-500">تثبيت يدوي</span>
                  </label>
                </div>
                <Select
                  value={manualForm.status}
                  disabled={!manualOverrides.status}
                  onValueChange={(v) => {
                    setManualForm({ ...manualForm, status: v ?? "PRESENT" });
                  }}
                >
                  <SelectTrigger className={!manualOverrides.status ? "opacity-50" : ""}><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="PRESENT">حاضر</SelectItem>
                    <SelectItem value="LATE">متأخر</SelectItem>
                    <SelectItem value="ABSENT">غائب</SelectItem>
                    <SelectItem value="HALF_DAY">نصف يوم</SelectItem>
                    <SelectItem value="ON_LEAVE">إجازة</SelectItem>
                    <SelectItem value="HOLIDAY">عطلة</SelectItem>
                    <SelectItem value="REMOTE">عن بُعد</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>وقت الحضور</Label>
                <div className="flex gap-1">
                  <Input
                    type="time"
                    value={manualForm.checkIn}
                    onChange={(e) => setManualForm({ ...manualForm, checkIn: e.target.value })}
                  />
                  <Button
                    variant="outline"
                    size="icon"
                    type="button"
                    onClick={() => {
                      setManualForm({
                        ...manualForm,
                        checkIn: getLocalTimeString(new Date(), attendanceTimezone),
                      });
                    }}
                    title="الآن"
                  >
                    <Clock className="h-4 w-4" />
                  </Button>
                </div>
              </div>
              <div className="space-y-2">
                <Label>وقت الانصراف</Label>
                <div className="flex gap-1">
                  <Input
                    type="time"
                    value={manualForm.checkOut}
                    onChange={(e) => setManualForm({ ...manualForm, checkOut: e.target.value })}
                  />
                  <Button
                    variant="outline"
                    size="icon"
                    type="button"
                    onClick={() => {
                      setManualForm({
                        ...manualForm,
                        checkOut: getLocalTimeString(new Date(), attendanceTimezone),
                      });
                    }}
                    title="الآن"
                  >
                    <Clock className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4 border-t pt-4">
              <div className="space-y-2">
                <div className="flex items-center justify-between mb-1">
                  <Label className="text-red-600 font-bold">التأخير المعتمد</Label>
                  <label className="flex items-center gap-1.5 cursor-pointer">
                    <input 
                      type="checkbox" 
                      className="rounded border-gray-300 text-red-600 shadow-sm w-3 h-3 focus:ring-red-500"
                      checked={manualOverrides.late}
                      onChange={(e) => setManualOverrides(prev => ({ ...prev, late: e.target.checked }))}
                    />
                    <span className="text-[10px] text-gray-500">تخطي الحساب</span>
                  </label>
                </div>
                <div className={`flex items-center gap-2 ${!manualOverrides.late ? 'opacity-50 pointer-events-none' : ''}`}>
                  <div className="flex flex-col gap-1 items-center">
                    <span className="text-[10px] text-gray-500">ساعة</span>
                    <Input type="number" min="0" value={manualForm.lateHours} onChange={(e) => setManualForm({ ...manualForm, lateHours: parseInt(e.target.value) || 0 })} className="w-16 h-8 text-center" />
                  </div>
                  <div className="flex flex-col gap-1 items-center">
                    <span className="text-[10px] text-gray-500">دقيقة</span>
                    <Input type="number" min="0" max="59" value={manualForm.lateMins} onChange={(e) => setManualForm({ ...manualForm, lateMins: parseInt(e.target.value) || 0 })} className="w-16 h-8 text-center" />
                  </div>
                </div>
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between mb-1">
                  <Label className="text-orange-600 font-bold">انصراف مبكر</Label>
                  <label className="flex items-center gap-1.5 cursor-pointer">
                    <input 
                      type="checkbox" 
                      className="rounded border-gray-300 text-orange-600 shadow-sm w-3 h-3 focus:ring-orange-500"
                      checked={manualOverrides.early}
                      onChange={(e) => setManualOverrides(prev => ({ ...prev, early: e.target.checked }))}
                    />
                    <span className="text-[10px] text-gray-500">تخطي الحساب</span>
                  </label>
                </div>
                <div className={`flex items-center gap-2 ${!manualOverrides.early ? 'opacity-50 pointer-events-none' : ''}`}>
                  <div className="flex flex-col gap-1 items-center">
                    <span className="text-[10px] text-gray-500">ساعة</span>
                    <Input type="number" min="0" value={manualForm.earlyHours} onChange={(e) => setManualForm({ ...manualForm, earlyHours: parseInt(e.target.value) || 0 })} className="w-16 h-8 text-center" />
                  </div>
                  <div className="flex flex-col gap-1 items-center">
                    <span className="text-[10px] text-gray-500">دقيقة</span>
                    <Input type="number" min="0" max="59" value={manualForm.earlyMins} onChange={(e) => setManualForm({ ...manualForm, earlyMins: parseInt(e.target.value) || 0 })} className="w-16 h-8 text-center" />
                  </div>
                </div>
              </div>
            </div>

            <div className="space-y-2"><Label>ملاحظات</Label><Input value={manualForm.notes} onChange={(e) => setManualForm({ ...manualForm, notes: e.target.value })} placeholder="ملاحظات إضافية..." /></div>
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            {isEditMode && editingRecordId && !editingRecordId.startsWith("temp-") && manualForm.checkIn && !manualForm.checkOut && (
              <Button
                type="button"
                variant="outline"
                className="bg-orange-50 text-orange-600 border-orange-100 hover:bg-orange-600 hover:text-white"
                onClick={async () => {
                  try {
                    await api.post("/hr/attendance/check-out", {
                      employeeId: manualForm.employeeId,
                      method: "manual"
                    });
                    toast.success("تم تسجيل الانصراف بنجاح");
                    setShowManualDialog(false);
                    fetchAttendance();
                  } catch (err: any) {
                    toast.error(err.response?.data?.error || "حدث خطأ");
                  }
                }}
              >
                تسجيل انصراف الآن
              </Button>
            )}
            <div className="flex-1" />
            <Button variant="outline" onClick={() => setShowManualDialog(false)}>إلغاء</Button>
            <Button onClick={handleManualAttendance} className="bg-blue-600 hover:bg-blue-700">
              {isEditMode ? "حفظ التعديلات" : "تسجيل الحضور"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={showAutoCloseReviewDialog}
        onOpenChange={(open) => {
          setShowAutoCloseReviewDialog(open);
          if (!open) {
            setSelectedAutoCloseRecord(null);
          }
        }}
      >
        <DialogContent className="sm:max-w-[560px]">
          <DialogHeader>
            <DialogTitle className="text-right">مراجعة الإغلاق التلقائي</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2" dir="rtl">
            {selectedAutoCloseRecord && (
              <div className="rounded-xl border border-amber-100 bg-amber-50/60 p-4 space-y-2">
                <div className="font-bold text-gray-900">
                  {selectedAutoCloseRecord.employee?.firstName} {selectedAutoCloseRecord.employee?.lastName}
                </div>
                <div className="text-sm text-gray-600">
                  تاريخ السجل: {formatAttendanceDate(
                    selectedAutoCloseRecord.date,
                    { year: "numeric", month: "long", day: "numeric" },
                    "-",
                    attendanceTimezone,
                  )}
                </div>
                <div className="text-sm text-gray-600">
                  وقت الإغلاق المعتمد: {formatAttendanceTime(selectedAutoCloseRecord.autoCloseAudit?.scheduledCheckOut || null)}
                </div>
                <div className="text-sm text-gray-600">
                  السبب: {getAutoCloseReasonLabel(selectedAutoCloseRecord.autoCloseAudit?.autoCloseReason)}
                </div>
              </div>
            )}
            <div className="space-y-2">
              <Label>حالة المراجعة</Label>
              <Select
                value={autoCloseReviewForm.reviewStatus}
                onValueChange={(value) =>
                  setAutoCloseReviewForm((prev) => ({
                    ...prev,
                    reviewStatus: (value as AutoCloseReviewStatus) || "REVIEWED",
                  }))
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="اختر حالة المراجعة" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="PENDING">بانتظار المراجعة</SelectItem>
                  <SelectItem value="REVIEWED">تمت المراجعة</SelectItem>
                  <SelectItem value="ADJUSTED">تم التعديل</SelectItem>
                  <SelectItem value="DISMISSED">اعتماد كما هو</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>ملاحظات المراجعة</Label>
              <Textarea
                value={autoCloseReviewForm.reviewNotes}
                onChange={(e) =>
                  setAutoCloseReviewForm((prev) => ({
                    ...prev,
                    reviewNotes: e.target.value,
                  }))
                }
                placeholder="اكتب ملخص قرار المراجعة أو أي ملاحظات للإدارة/الموظف..."
                className="min-h-[120px]"
              />
            </div>
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            {selectedAutoCloseRecord && (
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  setShowAutoCloseReviewDialog(false);
                  handleEditClick(selectedAutoCloseRecord);
                }}
              >
                فتح السجل للتعديل
              </Button>
            )}
            <div className="flex-1" />
            <Button variant="outline" onClick={() => setShowAutoCloseReviewDialog(false)}>
              إلغاء
            </Button>
            <Button onClick={submitAutoCloseReview} className="bg-amber-600 hover:bg-amber-700">
              حفظ المراجعة
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* New Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={(isOpen) => {
        setDeleteDialogOpen(isOpen);
        if (!isOpen) setIdToDelete(null);
      }}>
        <DialogContent className="sm:max-w-[400px]">
          <DialogHeader>
            <DialogTitle className="text-right">حذف سجل حضور</DialogTitle>
          </DialogHeader>
          <div className="py-6 text-right text-gray-600">
            هل أنت متأكد من حذف هذا السجل بشكل نهائي؟ لا يمكن التراجع عن هذا الإجراء.
          </div>
          <DialogFooter className="flex gap-3 justify-start rtl:flex-row-reverse">
            <Button variant="outline" onClick={() => setDeleteDialogOpen(false)}>
              إلغاء
            </Button>
            <Button variant="destructive" onClick={executeDelete}>
              تأكيد الحذف
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <Dialog open={showNotesDialog} onOpenChange={setShowNotesDialog}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Eye className="h-5 w-5 text-blue-500" />
              ملاحظات الحضور
            </DialogTitle>
          </DialogHeader>
          <div className="py-6 px-4 bg-gray-50 rounded-lg border border-gray-100 min-h-[100px] flex items-center justify-center text-center">
            <p className="text-gray-700 font-medium whitespace-pre-wrap">{selectedNotes}</p>
          </div>
          <DialogFooter>
            <Button onClick={() => setShowNotesDialog(false)} className="w-full bg-blue-600 hover:bg-blue-700">إغلاق</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      
      <Dialog open={showMapModal} onOpenChange={setShowMapModal}>
        <DialogContent className="sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <MapPin className="h-5 w-5 text-blue-500" />
              موقع تسجيل الـ {selectedLocation?.type || "حضور/انصراف"}
            </DialogTitle>
          </DialogHeader>
          <div className="w-full h-[400px] bg-gray-100 rounded-md overflow-hidden relative">
            {selectedLocation && (
              <iframe
                title="Google Maps Location"
                width="100%"
                height="100%"
                frameBorder="0"
                src={`https://maps.google.com/maps?q=${selectedLocation.latitude},${selectedLocation.longitude}&z=15&output=embed`}
                allowFullScreen
              ></iframe>
            )}
          </div>
          <DialogFooter>
            <Button onClick={() => setShowMapModal(false)} className="w-full bg-blue-600 hover:bg-blue-700">إغلاق الخريطة</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Attendance;

import { useState, useEffect } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { Badge } from "../../components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "../../components/ui/dialog";
import {
  FileText,
  Filter,
  CheckCircle,
  XCircle,
  Edit,
  Search,
  Download,
  Eye,
  Clock,
  Shield,
  Globe,
  User,
  Calendar,
  ArrowRight,
  Loader2,
  Box,
  ListChecks,
  Terminal,
} from "lucide-react";
import { format } from "date-fns";
import { ar } from "date-fns/locale";
import api from "../../services/api";

interface AuditLog {
  id: string;
  action: "APPROVE" | "REJECT" | "UPDATE" | "CREATE" | "DELETE" | string;
  entityType:
  | "LEAVE"
  | "ADVANCE"
  | "RESIGNATION"
  | "EMPLOYEE"
  | "DEPARTMENT"
  | string;
  entityId: string;
  actorId: string;
  actorName: string;
  details: any;
  ipAddress?: string;
  createdAt: string;
  actor?: {
    avatar?: string;
    email?: string;
    firstName?: string;
    lastName?: string;
  };
}

interface AuditStats {
  totalLogs: number;
  actionStats: { action: string; count: number }[];
  entityStats: { entityType: string; count: number }[];
}

const AuditLogs = () => {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [stats, setStats] = useState<AuditStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0,
    totalPages: 0,
  });
  const [filters, setFilters] = useState({
    entityType: "",
    action: "",
    startDate: "",
    endDate: "",
    search: "",
  });
  const [selectedLog, setSelectedLog] = useState<AuditLog | null>(null);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => {
      fetchAuditLogs();
    }, 500);
    return () => clearTimeout(timer);
  }, [pagination.page, filters, pagination.limit]);

  // Fetch stats separately
  useEffect(() => {
    fetchStats();
  }, [filters.startDate, filters.endDate]);

  const fetchStats = async () => {
    try {
      const params = {
        startDate: filters.startDate,
        endDate: filters.endDate,
      };
      const response = await api.get("/hr/audit-logs/stats", { params });
      if (response.data.success) {
        setStats(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching audit stats:", error);
    }
  };

  const fetchAuditLogs = async () => {
    try {
      setLoading(true);
      const params = {
        page: pagination.page,
        limit: pagination.limit,
        entityType: filters.entityType === "all" ? "" : filters.entityType,
        action: filters.action === "all" ? "" : filters.action,
        startDate: filters.startDate,
        endDate: filters.endDate,
        search: filters.search,
      };

      const response = await api.get("/hr/audit-logs", { params });

      if (response.data.success) {
        setLogs(response.data.logs || []);
        setPagination(
          response.data.pagination || {
            page: 1,
            limit: 10,
            total: 0,
            totalPages: 0,
          },
        );
      } else {
        setLogs([]);
      }
    } catch (error) {
      console.error("Error fetching audit logs:", error);
      setLogs([]);
    } finally {
      setLoading(false);
    }
  };

  const formatFieldName = (field: string) => {
    const translations: Record<string, string> = {
      amount: "المبلغ",
      totalSalary: "إجمالي الراتب",
      monthlyAmount: "القسط الشهري",
      reason: "السبب",
      status: "الحالة",
      note: "ملاحظات",
      startDate: "تاريخ البدء",
      endDate: "تاريخ الانتهااء",
      type: "النوع",
      name: "الاسم",
      description: "الوصف",
      hours: "عدد الساعات",
      day: "اليوم",
      isPaid: "مدفوع",
    };
    return translations[field] || field;
  };

  const getEntityName = (type: string) => {
    const names: Record<string, string> = {
      EMPLOYEE: "موظف",
      DEPARTMENT: "قسم",
      POSITION: "مسمى وظيفي",
      LEAVE: "إجازة",
      ADVANCE: "سلفة",
      ADVANCE_REQUEST: "طلب سلفة",
      RESIGNATION: "استقالة",
      ATTENDANCE: "حضور وانصراف",
      SHIFT: "مناوبة",
      PERMISSION_REQUEST: "إذن خروج",
      DEDUCTION: "خصم",
      PAYROLL: "مسير رواتب",
      POLICY: "سياسة",
      GOAL: "هدف",
      FEEDBACK: "تقييم",
      SETTINGS: "إعدادات",
      USER: "مستخدم",
    };
    return names[type] || type;
  };

  const getActionIcon = (action: string) => {
    switch (action) {
      case "APPROVE":
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      case "REJECT":
        return <XCircle className="h-4 w-4 text-destructive" />;
      case "UPDATE":
        return <Edit className="h-4 w-4 text-blue-500" />;
      case "CREATE":
        return <CheckCircle className="h-4 w-4 text-purple-500" />;
      case "DELETE":
        return <XCircle className="h-4 w-4 text-destructive" />;
      case "SETTLEMENT":
        return <Shield className="h-4 w-4 text-emerald-500" />;
      case "LOGIN":
        return <User className="h-4 w-4 text-indigo-500" />;
      case "LOGOUT":
        return <User className="h-4 w-4 text-gray-500" />;
      default:
        return <FileText className="h-4 w-4 text-muted-foreground" />;
    }
  };

  const getActionBadge = (action: string) => {
    const styles: Record<string, string> = {
      APPROVE:
        "bg-green-100 text-green-800 border-green-200 dark:bg-green-900/30 dark:text-green-400",
      REJECT:
        "bg-red-100 text-red-800 border-red-200 dark:bg-red-900/30 dark:text-red-400",
      UPDATE:
        "bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-400",
      CREATE:
        "bg-purple-100 text-purple-800 border-purple-200 dark:bg-purple-900/30 dark:text-purple-400",
      DELETE:
        "bg-red-50 text-red-900 border-red-200 dark:bg-red-950/30 dark:text-red-300",
      SETTLEMENT:
        "bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400",
      LOGIN:
        "bg-indigo-100 text-indigo-800 border-indigo-200 dark:bg-indigo-900/30 dark:text-indigo-400",
      LOGOUT:
        "bg-gray-100 text-gray-800 border-gray-200 dark:bg-gray-900/30 dark:text-gray-400",
    };

    const labels: Record<string, string> = {
      APPROVE: "موافقة",
      REJECT: "رفض",
      UPDATE: "تحديث",
      CREATE: "إنشاء",
      DELETE: "حذف",
      SETTLEMENT: "تصفية",
      LOGIN: "تسجيل دخول",
      LOGOUT: "تسجيل خروج",
      EXPORT: "تصدير",
      IMPORT: "استيراد",
      ASSIGN: "تعيين",
      ACTIVATE: "تفعيل",
      DEACTIVATE: "تعطيل",
    };

    return (
      <Badge
        variant="outline"
        className={styles[action] || "bg-muted text-muted-foreground"}
      >
        {labels[action] || action}
      </Badge>
    );
  };

  const parseDetails = (details: any) => {
    try {
      return typeof details === "string" ? JSON.parse(details) : details;
    } catch {
      return {};
    }
  };

  const handleExport = () => {
    if (!logs.length) return;

    const headers = [
      "Date",
      "Time",
      "Actor Name",
      "Actor Email",
      "Action",
      "Entity Type",
      "Entity ID",
      "IP Address",
    ];
    const csvContent = [
      headers.join(","),
      ...logs.map((log) =>
        [
          format(new Date(log.createdAt), "yyyy-MM-dd"),
          format(new Date(log.createdAt), "HH:mm:ss"),
          `"${log.actorName}"`,
          `"${log.actor?.email || ""}"`,
          log.action,
          log.entityType,
          log.entityId,
          log.ipAddress || "",
        ].join(","),
      ),
    ].join("\n");

    const blob = new Blob(["\ufeff" + csvContent], {
      type: "text/csv;charset=utf-8;",
    });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute(
      "download",
      `audit_logs_${format(new Date(), "yyyyMMdd_HHmmss")}.csv`,
    );
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="container mx-auto p-6 space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-3">
            <Shield className="h-8 w-8 text-primary" />
            سجلات التدقيق
          </h1>
          <p className="text-muted-foreground mt-1">
            سجل التغييرات ومراقبة النظام
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            variant="outline"
            className="gap-2"
            onClick={handleExport}
            disabled={logs.length === 0}
          >
            <Download className="h-4 w-4" />
            تصدير CSV
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card>
            <CardContent className="p-4 flex items-center gap-4">
              <div className="bg-primary/10 p-3 rounded-full">
                <FileText className="h-6 w-6 text-primary" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">إجمالي السجلات</p>
                <h3 className="text-2xl font-bold">{stats.totalLogs}</h3>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4 flex items-center gap-4">
              <div className="bg-green-100 dark:bg-green-900/20 p-3 rounded-full">
                <CheckCircle className="h-6 w-6 text-green-600" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">عمليات الإنشاء</p>
                <h3 className="text-2xl font-bold">
                  {stats.actionStats.find(s => s.action === 'CREATE')?.count || 0}
                </h3>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4 flex items-center gap-4">
              <div className="bg-blue-100 dark:bg-blue-900/20 p-3 rounded-full">
                <Edit className="h-6 w-6 text-blue-600" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">علمايت التحديث</p>
                <h3 className="text-2xl font-bold">
                  {stats.actionStats.find(s => s.action === 'UPDATE')?.count || 0}
                </h3>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4 flex items-center gap-4">
              <div className="bg-red-100 dark:bg-red-900/20 p-3 rounded-full">
                <XCircle className="h-6 w-6 text-red-600" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">عمليات الحذف</p>
                <h3 className="text-2xl font-bold">
                  {stats.actionStats.find(s => s.action === 'DELETE')?.count || 0}
                </h3>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Filters Bar */}
      <Card>
        <CardContent className="p-4">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 relative">
              <Search className="absolute right-3 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="بحث في السجلات..."
                value={filters.search}
                onChange={(e) =>
                  setFilters({ ...filters, search: e.target.value })
                }
                className="pr-9"
              />
            </div>
            <Select
              value={filters.entityType || "all"}
              onValueChange={(value) =>
                setFilters({
                  ...filters,
                  entityType: value === "all" ? "" : value,
                })
              }
            >
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="نوع الكيان" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">الكل</SelectItem>
                <SelectItem value="EMPLOYEE">الموظفين</SelectItem>
                <SelectItem value="DEPARTMENT">الأقسام</SelectItem>
                <SelectItem value="POSITION">الوظائف</SelectItem>
                <SelectItem value="LEAVE">الإجازات</SelectItem>
                <SelectItem value="ADVANCE">السلف</SelectItem>
                <SelectItem value="ADVANCE_REQUEST">طلبات السلف</SelectItem>
                <SelectItem value="RESIGNATION">الاستقالات</SelectItem>
                <SelectItem value="ATTENDANCE">الحضور</SelectItem>
                <SelectItem value="SHIFT">المناوبات</SelectItem>
                <SelectItem value="PERMISSION_REQUEST">الإذونات</SelectItem>
                <SelectItem value="DEDUCTION">الخصومات</SelectItem>
                <SelectItem value="PAYROLL">الرواتب</SelectItem>
                <SelectItem value="POLICY">السياسات</SelectItem>
                <SelectItem value="GOAL">الأهداف</SelectItem>
                <SelectItem value="FEEDBACK">التغذية الراجعة</SelectItem>
                <SelectItem value="SETTINGS">الإعدادات</SelectItem>
                <SelectItem value="USER">المستخدمين</SelectItem>
              </SelectContent>
            </Select>

            <Select
              value={filters.action || "all"}
              onValueChange={(value) =>
                setFilters({ ...filters, action: value === "all" ? "" : value })
              }
            >
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="نوع العملية" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">الكل</SelectItem>
                <SelectItem value="CREATE">إنشاء</SelectItem>
                <SelectItem value="UPDATE">تحديث</SelectItem>
                <SelectItem value="DELETE">حذف</SelectItem>
                <SelectItem value="APPROVE">موافقة</SelectItem>
                <SelectItem value="REJECT">رفض</SelectItem>
                <SelectItem value="LOGIN">تسجيل دخول</SelectItem>
                <SelectItem value="LOGOUT">تسجيل خروج</SelectItem>
                <SelectItem value="EXPORT">تصدير</SelectItem>
                <SelectItem value="IMPORT">استيراد</SelectItem>
                <SelectItem value="SETTLEMENT">تصفية</SelectItem>
                <SelectItem value="ASSIGN">تعيين</SelectItem>
                <SelectItem value="ACTIVATE">تفعيل</SelectItem>
                <SelectItem value="DEACTIVATE">تعطيل</SelectItem>
              </SelectContent>
            </Select>

            <Input
              type="date"
              className="w-[160px]"
              value={filters.startDate}
              onChange={(e) =>
                setFilters({ ...filters, startDate: e.target.value })
              }
            />
            <Input
              type="date"
              className="w-[160px]"
              value={filters.endDate}
              onChange={(e) =>
                setFilters({ ...filters, endDate: e.target.value })
              }
            />
          </div>
        </CardContent>
      </Card>

      {/* Data Table */}
      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="text-right">المستخدم</TableHead>
              <TableHead className="text-right">العملية</TableHead>
              <TableHead className="text-right">الكيان</TableHead>
              <TableHead className="text-right">التاريخ</TableHead>
              <TableHead className="text-left w-[100px]">التفاصيل</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={5} className="h-24 text-center">
                  <div className="flex justify-center items-center gap-2">
                    <Loader2 className="h-5 w-5 animate-spin text-primary" />
                    <span>جاري التحميل...</span>
                  </div>
                </TableCell>
              </TableRow>
            ) : logs.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={5}
                  className="h-64 text-center text-muted-foreground"
                >
                  <div className="flex flex-col items-center justify-center">
                    <FileText className="h-12 w-12 mb-4 opacity-20" />
                    <p>لا توجد سجلات مطابقة للبحث</p>
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              logs.map((log) => (
                <TableRow
                  key={log.id}
                  className="group hover:bg-muted/50 transition-colors"
                >
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <Avatar className="h-8 w-8">
                        <AvatarImage src={log.actor?.avatar} />
                        <AvatarFallback>
                          {log.actorName?.charAt(0) || "U"}
                        </AvatarFallback>
                      </Avatar>
                      <div className="flex flex-col">
                        <span className="font-medium text-sm">
                          {log.actorName}
                        </span>
                        <span className="text-xs text-muted-foreground hidden group-hover:block transition-all">
                          {log.actor?.email}
                        </span>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      {getActionIcon(log.action)}
                      {getActionBadge(log.action)}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-col">
                      <span className="font-semibold text-sm text-primary/80">
                        {getEntityName(log.entityType)}
                      </span>
                      {log.entityType !== "SETTINGS" && (
                        <span className="text-[10px] text-muted-foreground font-mono bg-muted px-1 rounded w-fit mt-1">
                          #{log.entityId?.substring(0, 8)}
                        </span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-col text-sm">
                      <span className="font-medium">
                        {format(new Date(log.createdAt), "dd MMM yyyy", {
                          locale: ar,
                        })}
                      </span>
                      <span className="text-xs text-muted-foreground">
                        {format(new Date(log.createdAt), "HH:mm:ss", {
                          locale: ar,
                        })}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="text-left">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setSelectedLog(log)}
                    >
                      <Eye className="h-4 w-4 text-muted-foreground" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>

        {/* Pagination */}
        <div className="flex items-center justify-between p-4 border-t bg-muted/20">
          <div className="text-sm text-muted-foreground">
            صفحة {pagination.page} من {pagination.totalPages || 1}
          </div>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                setPagination({
                  ...pagination,
                  page: Math.max(1, pagination.page - 1),
                })
              }
              disabled={pagination.page <= 1}
            >
              السابق
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                setPagination({ ...pagination, page: pagination.page + 1 })
              }
              disabled={pagination.page >= pagination.totalPages}
            >
              التالي
            </Button>
          </div>
        </div>
      </Card>

      {/* Details Dialog */}
      <Dialog
        open={!!selectedLog}
        onOpenChange={(open) => !open && setSelectedLog(null)}
      >
        <DialogContent className="max-w-2xl" dir="rtl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shield className="h-5 w-5 text-primary" />
              تفاصيل العملية
            </DialogTitle>
            <DialogDescription>
              المعلومات الكاملة عن هذا الإجراء
            </DialogDescription>
          </DialogHeader>

          {selectedLog && (
            <div className="mt-4 space-y-6">
              {/* Actor Info */}
              <div className="flex items-center gap-4 p-4 bg-muted rounded-lg border">
                <Avatar className="h-12 w-12">
                  <AvatarImage src={selectedLog.actor?.avatar} />
                  <AvatarFallback>
                    {selectedLog.actorName?.charAt(0)}
                  </AvatarFallback>
                </Avatar>
                <div>
                  <h3 className="font-bold text-lg">{selectedLog.actorName}</h3>
                  <p className="text-sm text-muted-foreground">
                    {selectedLog.actor?.email || "System User"}
                  </p>
                </div>
                <div className="mr-auto">
                  {getActionBadge(selectedLog.action)}
                </div>
              </div>

              {/* Meta Info grid */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1 p-3 bg-muted/30 rounded border">
                  <span className="text-xs text-muted-foreground block mb-1">
                    التاريخ
                  </span>
                  <div className="font-medium flex items-center gap-2 text-sm">
                    <Calendar className="h-4 w-4 text-primary" />
                    {format(new Date(selectedLog.createdAt), "dd MMMM yyyy", {
                      locale: ar,
                    })}
                  </div>
                </div>
                <div className="space-y-1 p-3 bg-muted/30 rounded border">
                  <span className="text-xs text-muted-foreground block mb-1">
                    الوقت
                  </span>
                  <div className="font-medium flex items-center gap-2 text-sm">
                    <Clock className="h-4 w-4 text-primary" />
                    {format(new Date(selectedLog.createdAt), "HH:mm:ss a")}
                  </div>
                </div>
                <div className="space-y-1 p-3 bg-muted/30 rounded border">
                  <span className="text-xs text-muted-foreground block mb-1">
                    IP Address
                  </span>
                  <div className="font-medium flex items-center gap-2 font-mono text-sm">
                    <Globe className="h-4 w-4 text-primary" />
                    {selectedLog.ipAddress || "غير متوفر"}
                  </div>
                </div>
                <div className="space-y-1 p-3 bg-muted/30 rounded border">
                  <span className="text-xs text-muted-foreground block mb-1">
                    الكيان
                  </span>
                  <div className="font-medium flex items-center gap-2 text-sm text-primary">
                    <Box className="h-4 w-4" />
                    {getEntityName(selectedLog.entityType)}
                    {selectedLog.entityType !== "SETTINGS" && (
                      <span className="text-[10px] text-muted-foreground bg-muted px-1 rounded">
                        #{selectedLog.entityId?.substring(0, 8)}
                      </span>
                    )}
                  </div>
                </div>
              </div>

              {/* Human Readable Details */}
              <div className="space-y-3">
                <h4 className="font-semibold text-sm border-b pb-2 flex items-center gap-2">
                  <ListChecks className="h-4 w-4 text-primary" />
                  بيانات العملية التفصيلية
                </h4>
                <div className="grid grid-cols-1 gap-2">
                  {Object.entries(parseDetails(selectedLog.details)).map(
                    ([key, value]) => (
                      <div
                        key={key}
                        className="flex justify-between items-center p-2 bg-muted/20 rounded-md border border-transparent hover:border-muted-foreground/10 transition-all"
                      >
                        <span className="text-sm text-muted-foreground">
                          {formatFieldName(key)}
                        </span>
                        <span className="text-sm font-semibold">
                          {typeof value === "object"
                            ? JSON.stringify(value)
                            : String(value)}
                        </span>
                      </div>
                    ),
                  )}
                  {Object.keys(parseDetails(selectedLog.details)).length ===
                    0 && (
                      <div className="text-center p-4 text-muted-foreground text-sm italic">
                        لا توجد بيانات إضافية لهذه العملية
                      </div>
                    )}
                </div>
              </div>

              <div className="flex justify-end pt-2">
                <Button onClick={() => setSelectedLog(null)} variant="outline">
                  إغلاق
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AuditLogs;

import React, { useState, useEffect } from "react";
import {
  Gift,
  Plus,
  Users,
  DollarSign,
  CheckCircle,
  Trash2,
  HeartPulse,
  Shield,
  PiggyBank,
  Save,
  Pencil,
  Search,
  Filter,
  ChevronLeft,
  ChevronRight,
  X,
  Car,
  Home,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "../../components/ui/dialog";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Textarea } from "../../components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../components/ui/tabs";
import { ScrollArea } from "../../components/ui/scroll-area";
import { useNavigate, useLocation, useParams } from "react-router-dom";
import api from "../../services/api";
import { toast } from "sonner";

interface Enrollment {
  id: string;
  startDate: string;
  endDate?: string;
  status: string;
  notes?: string;
  employee: {
    id: string;
    firstName: string;
    lastName: string;
    employeeNumber: string;
  };
}

interface Benefit {
  id: string;
  name: string;
  description?: string;
  type: string;
  cost?: number;
  currency: string;
  isActive: boolean;
  activeEnrollments?: number;
  enrollments?: Enrollment[];
}

interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  employeeNumber: string;
}

const Benefits: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [benefits, setBenefits] = useState<Benefit[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [selectedBenefit, setSelectedBenefit] = useState<Benefit | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [enrollLoading, setEnrollLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: "",
    description: "",
    type: "health_insurance",
    cost: 0,
    currency: "EGP",
    isActive: true,
  });

  const [enrollmentFormData, setEnrollmentFormData] = useState({
    employeeId: "",
    startDate: new Date().toISOString().split("T")[0],
    notes: "",
  });

  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [page, setPage] = useState(1);
  const [pagination, setPagination] = useState({
    total: 0,
    page: 1,
    limit: 10,
    totalPages: 0,
  });

  const { id } = useParams();

  useEffect(() => {
    setPage(1);
  }, [search, typeFilter]);

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchBenefits();
    }, 500);
    return () => clearTimeout(timer);
  }, [search, typeFilter, page]);

  useEffect(() => {
    fetchEmployees();
  }, []);

  useEffect(() => {
    if (id && id !== "new") {
      fetchBenefitDetails(id);
    } else if (location.pathname.endsWith("/new")) {
      setDialogOpen(true);
    }
  }, [id, location.pathname]);

  const fetchEmployees = async () => {
    try {
      const response = await api.get("/hr/employees?limit=1000");
      setEmployees(response.data.employees || []);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  };

  const fetchBenefitDetails = async (benefitId: string) => {
    try {
      setLoading(true);
      const response = await api.get(`/hr/benefits/${benefitId}`);
      setSelectedBenefit(response.data.benefit);
      setDetailsOpen(true);
    } catch (error) {
      console.error("Error fetching benefit details:", error);
      toast.error("فشل في جلب تفاصيل الميزة");
      navigate("/hr/benefits");
    } finally {
      setLoading(false);
    }
  };

  const fetchBenefits = async () => {
    try {
      setLoading(true);
      console.log("💎 Fetching benefits with params:", {
        search,
        type: typeFilter,
        page,
        limit: 9,
      });
      const response = await api.get("/hr/benefits", {
        params: {
          search,
          type: typeFilter,
          page,
          limit: 9,
        },
      });
      setBenefits(response.data?.benefits || []);
      setPagination(
        response.data?.pagination || {
          total: 0,
          page: 1,
          limit: 10,
          totalPages: 0,
        },
      );
    } catch (error) {
      console.error("Error fetching benefits:", error);
      toast.error("فشل في جلب المزايا");
    } finally {
      setLoading(false);
    }
  };

  const handleEnroll = async () => {
    if (!enrollmentFormData.employeeId) {
      toast.error("يرجى اختيار موظف");
      return;
    }

    try {
      setEnrollLoading(true);
      await api.post("/hr/benefits/enroll", {
        benefitId: selectedBenefit?.id,
        ...enrollmentFormData,
      });
      toast.success("تم تسجيل الموظف في الميزة بنجاح");
      setEnrollmentFormData({
        employeeId: "",
        startDate: new Date().toISOString().split("T")[0],
        notes: "",
      });
      if (selectedBenefit) {
        fetchBenefitDetails(selectedBenefit.id);
      }
      fetchBenefits();
    } catch (error: any) {
      console.error("Error enrolling employee:", error);
      toast.error(error.response?.data?.error || "فشل في تسجيل الموظف");
    } finally {
      setEnrollLoading(false);
    }
  };

  const handleSubmit = async () => {
    if (!formData.name) {
      toast.error("اسم الميزة مطلوب");
      return;
    }

    try {
      setSubmitting(true);
      if (editingId) {
        await api.put(`/hr/benefits/${editingId}`, formData);
        toast.success("تم تحديث الميزة بنجاح");
      } else {
        await api.post("/hr/benefits", formData);
        toast.success("تم إنشاء الميزة بنجاح");
      }
      setDialogOpen(false);
      resetForm();
      fetchBenefits();
      if (!editingId && location.pathname.endsWith("/new")) {
        navigate("/hr/benefits");
      }
    } catch (error: any) {
      console.error("Error saving benefit:", error);
      toast.error(
        error.response?.data?.error ||
        (editingId ? "فشل في تحديث الميزة" : "فشل في إنشاء الميزة"),
      );
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذه الميزة؟")) return;

    try {
      await api.delete(`/hr/benefits/${id}`);
      toast.success("تم حذف الميزة بنجاح");
      fetchBenefits();
    } catch (error) {
      console.error("Error deleting benefit:", error);
      toast.error("فشل في حذف الميزة");
    }
  };

  const resetForm = () => {
    setFormData({
      name: "",
      description: "",
      type: "health_insurance",
      cost: 0,
      currency: "EGP",
      isActive: true,
    });
    setEditingId(null);
  };

  const openCreateDialog = () => {
    resetForm();
    setDialogOpen(true);
    navigate("/hr/benefits/new");
  };

  const openEditDialog = (benefit: Benefit) => {
    setFormData({
      name: benefit.name || "",
      description: benefit.description || "",
      type: benefit.type || "health_insurance",
      cost: benefit.cost || 0,
      currency: benefit.currency || "EGP",
      isActive: benefit.isActive,
    });
    setEditingId(benefit.id);
    setDialogOpen(true);
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case "health_insurance":
        return <HeartPulse className="h-5 w-5 text-red-500" />;
      case "life_insurance":
        return <Shield className="h-5 w-5 text-blue-500" />;
      case "retirement":
        return <PiggyBank className="h-5 w-5 text-green-500" />;
      case "transportation":
        return <Car className="h-5 w-5 text-gray-500" />;
      case "housing":
        return <Home className="h-5 w-5 text-orange-500" />;
      default:
        return <Gift className="h-5 w-5 text-purple-500" />;
    }
  };

  const getTypeLabel = (type: string) => {
    const typeMap: Record<string, string> = {
      health_insurance: "تأمين صحي",
      life_insurance: "تأمين على الحياة",
      retirement: "تقاعد",
      transportation: "بدل انتقال",
      housing: "بدل سكن",
      other: "أخرى",
    };
    return typeMap[type] || type;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-50/30 dark:bg-gray-900/30">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          <p className="text-sm text-muted-foreground animate-pulse">
            جاري تحميل المزايا...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 md:p-8 space-y-8 bg-gray-50/20 min-h-screen" dir="rtl">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="space-y-1">
          <h1 className="text-3xl font-black tracking-tight flex items-center gap-3">
            <Gift className="h-8 w-8 text-primary" />
            المزايا والتعويضات
          </h1>
          <p className="text-muted-foreground flex items-center gap-2">
            إدارة المزايا الإضافية وبرامج الرعاية الخاصة بالموظفين
          </p>
        </div>
        <Button
          onClick={openCreateDialog}
          className="h-12 px-6 rounded-xl shadow-lg shadow-primary/20 transition-all active:scale-95"
        >
          <Plus className="h-5 w-5 ml-2" />
          إضافة ميزة جديدة
        </Button>
      </div>

      {/* Filters Section */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
        <div className="md:col-span-8 relative group">
          <div className="absolute inset-y-0 right-0 pr-4 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-gray-400 group-focus-within:text-primary transition-colors" />
          </div>
          <Input
            placeholder="ابحث عن ميزة بالاسم أو الوصف..."
            className="w-full pr-12 h-14 rounded-2xl border-none bg-white dark:bg-gray-900 shadow-sm shadow-gray-200/50 dark:shadow-none focus:ring-2 focus:ring-primary/20 text-lg transition-all"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <div className="md:col-span-4 h-14">
          <Select value={typeFilter} onValueChange={setTypeFilter}>
            <SelectTrigger className="h-full rounded-2xl border-none bg-white dark:bg-gray-900 shadow-sm shadow-gray-200/50 dark:shadow-none focus:ring-2 focus:ring-primary/20 font-bold transition-all">
              <div className="flex items-center gap-2">
                <Filter className="h-4 w-4 text-primary" />
                <SelectValue placeholder="تصفية حسب النوع" />
              </div>
            </SelectTrigger>
            <SelectContent className="rounded-2xl border-none shadow-2xl">
              <SelectItem value="all" className="rounded-xl m-1">كل الأنواع</SelectItem>
              <SelectItem value="health_insurance" className="rounded-xl m-1">تأمين صحي</SelectItem>
              <SelectItem value="life_insurance" className="rounded-xl m-1">تأمين على الحياة</SelectItem>
              <SelectItem value="retirement" className="rounded-xl m-1">تقاعد</SelectItem>
              <SelectItem value="transportation" className="rounded-xl m-1">بدل انتقال</SelectItem>
              <SelectItem value="housing" className="rounded-xl m-1">بدل سكن</SelectItem>
              <SelectItem value="other" className="rounded-xl m-1">أخرى</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {benefits.length === 0 && !loading ? (
        <Card className="border-dashed border-2 bg-transparent">
          <CardContent className="p-20 text-center flex flex-col items-center">
            <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mb-6">
              <Gift className="h-10 w-10 text-primary" />
            </div>
            <h3 className="text-xl font-bold mb-2">لا توجد مزايا مسجلة</h3>
            <p className="text-muted-foreground mb-8 max-w-sm">
              لم تقم بإضافة أي مزايا موظفين حتى الآن. ابدأ بإضافة التأمين الصحي
              أو برامج التقاعد.
            </p>
            <Button
              variant="outline"
              onClick={() => setDialogOpen(true)}
              className="h-11 rounded-full px-8"
            >
              <Plus className="h-4 w-4 ml-2" />
              أضف أول ميزة
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {benefits.map((benefit: Benefit) => (
            <div
              key={benefit.id}
              className="group relative"
              onClick={() => navigate(`/hr/benefits/${benefit.id}`)}
            >
              <Card className="relative overflow-hidden border-none shadow-xl hover:shadow-2xl transition-all duration-500 cursor-pointer group bg-white/80 dark:bg-gray-900/60 backdrop-blur-xl ring-1 ring-gray-100 dark:ring-white/5 h-full rounded-3xl">
                {/* Visual Gradient Bottom */}
                <div className="absolute bottom-0 inset-x-0 h-1 bg-gradient-to-l from-primary via-blue-500 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

                <CardHeader className="pb-4">
                  <div className="flex items-start justify-between">
                    <div className="p-4 bg-white dark:bg-gray-800 rounded-2xl shadow-sm dark:shadow-none group-hover:scale-110 transition-transform duration-500">
                      {getTypeIcon(benefit.type)}
                    </div>
                    <div className="flex gap-1">
                      {benefit.isActive ? (
                        <Badge className="bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-400 border-none font-bold">
                          نشط
                        </Badge>
                      ) : (
                        <Badge variant="secondary" className="bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400">
                          متوقف
                        </Badge>
                      )}

                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-9 w-9 rounded-xl text-gray-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-500/10"
                        onClick={(e) => {
                          e.stopPropagation();
                          openEditDialog(benefit);
                        }}
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-9 w-9 rounded-xl text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10"
                        onClick={(e) => handleDelete(e, benefit.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                  <CardTitle className="text-2xl font-black mt-6 text-gray-900 dark:text-gray-100 group-hover:text-primary transition-colors">
                    {benefit.name}
                  </CardTitle>
                  <CardDescription className="line-clamp-2 min-h-[48px] mt-2 text-gray-500 dark:text-gray-400 text-sm leading-relaxed">
                    {benefit.description || "لا يوجد وصف متاح لهذه الميزة"}
                  </CardDescription>
                </CardHeader>

                <CardContent className="space-y-6 pt-0">
                  <div className="flex flex-wrap gap-2">
                    <Badge
                      variant="outline"
                      className="rounded-lg font-bold px-3 py-1 border-primary/10 bg-primary/5 text-primary"
                    >
                      {getTypeLabel(benefit.type)}
                    </Badge>
                  </div>

                  <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800/40 rounded-2xl border border-gray-100 dark:border-gray-700/50">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary shadow-inner">
                        <DollarSign className="h-5 w-5" />
                      </div>
                      <div>
                        <p className="text-[10px] text-gray-400 dark:text-gray-500 uppercase font-black tracking-widest leading-none mb-1">
                          التكلفة
                        </p>
                        <p className="font-black text-gray-900 dark:text-gray-100">
                          {benefit.cost?.toLocaleString() || 0}{" "}
                          <span className="text-xs font-bold text-gray-400">
                            {benefit.currency}
                          </span>
                        </p>
                      </div>
                    </div>
                    <div className="text-left flex items-center gap-3">
                      <div className="text-right">
                        <p className="text-[10px] text-gray-400 dark:text-gray-500 uppercase font-black tracking-widest leading-none mb-1">
                          المشتركون
                        </p>
                        <p className="font-black text-orange-600 dark:text-orange-400 leading-none">
                          {benefit.activeEnrollments || 0}
                        </p>
                      </div>
                      <div className="w-10 h-10 rounded-xl bg-orange-50 dark:bg-orange-500/10 flex items-center justify-center text-orange-500 shadow-inner">
                        <Users className="h-5 w-5" />
                      </div>
                    </div>
                  </div>
                </CardContent>

                <div className="px-6 py-4 bg-gray-50/50 dark:bg-black/20 border-t border-gray-100 dark:border-gray-800 flex justify-between items-center group-hover:bg-primary/5 transition-colors">
                  <div className="flex -space-x-2 rtl:space-x-reverse">
                    {[...Array(Math.min(3, benefit.activeEnrollments || 0))].map((_, i) => (
                      <div key={i} className="w-7 h-7 rounded-full border-2 border-white dark:border-gray-900 bg-primary/20 flex items-center justify-center text-[10px] font-black text-primary uppercase">
                        {String.fromCharCode(65 + i)}
                      </div>
                    ))}
                  </div>
                  <span className="text-xs font-black text-primary flex items-center gap-2">
                    عرض التفاصيل
                    <ChevronLeft className="h-4 w-4" />
                  </span>
                </div>
              </Card>
            </div>
          ))}
          {/* Pagination Section */}
          {pagination?.totalPages > 1 && (
            <div className="flex items-center justify-between pt-4 border-t border-gray-100">
              <p className="text-sm text-muted-foreground">
                عرض {benefits.length} من {pagination?.total || 0} ميزة
              </p>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page === 1}
                  className="h-9 w-9 p-0"
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
                <div className="flex items-center gap-1 mx-2">
                  {[...Array(pagination?.totalPages || 0)].map((_, i) => (
                    <Button
                      key={i}
                      variant={page === i + 1 ? "default" : "ghost"}
                      size="sm"
                      onClick={() => setPage(i + 1)}
                      className="h-9 w-9 p-0"
                    >
                      {i + 1}
                    </Button>
                  ))}
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() =>
                    setPage((p) => Math.min(pagination?.totalPages || 1, p + 1))
                  }
                  disabled={page === pagination?.totalPages}
                  className="h-9 w-9 p-0"
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Create Dialog */}
      <Dialog
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open);
          if (!open && location.pathname.endsWith("/new")) {
            navigate("/hr/benefits");
          }
          if (!open) {
            setEditingId(null);
          }
        }}
      >
        <DialogContent className="sm:max-w-xl rounded-[2.5rem] p-0 overflow-hidden border-none shadow-2xl bg-white/95 dark:bg-gray-900/95 backdrop-blur-md" dir="rtl">
          <div className="p-8 bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border-b border-gray-100 dark:border-gray-800">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-white dark:bg-gray-800 rounded-3xl flex items-center justify-center mb-6 shadow-xl shadow-primary/10">
                <Gift className="h-10 w-10 text-primary" />
              </div>
              <DialogTitle className="text-3xl font-black text-gray-900 dark:text-gray-100">
                {editingId ? "تعديل ميزة قائمة" : "إضافة ميزة جديدة"}
              </DialogTitle>
              <DialogDescription className="mt-2 text-gray-500 dark:text-gray-400 max-w-sm">
                {editingId
                  ? "قم بتحديث بيانات الميزة الحالية لتنسجم مع سياسات الشركة المتغيرة."
                  : "ابدأ بتعريف ميزة جديدة تساهم في رفع مستوى رفاهية موظفيك."}
              </DialogDescription>
            </div>
          </div>

          <ScrollArea className="max-h-[60vh]">
            <div className="p-8 space-y-8">
              <div className="space-y-3 px-1">
                <Label className="text-sm font-black text-gray-700 dark:text-gray-300 flex items-center gap-2">
                  <Pencil className="h-4 w-4 text-primary" />
                  اسم الميزة الفريد
                </Label>
                <Input
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  placeholder="مثال: تأمين طبي VIP، بدل سكن كبار المدراء..."
                  className="h-14 rounded-2xl bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm focus:ring-2 focus:ring-primary/20 transition-all text-lg font-bold"
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 px-1">
                <div className="space-y-3">
                  <Label className="text-sm font-black text-gray-700 dark:text-gray-300 flex items-center gap-2">
                    <Filter className="h-4 w-4 text-primary" />
                    نوع الميزة
                  </Label>
                  <Select
                    value={formData.type}
                    onValueChange={(val) => setFormData({ ...formData, type: val })}
                  >
                    <SelectTrigger className="h-14 rounded-2xl bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm font-bold">
                      <SelectValue placeholder="اختر النوع" />
                    </SelectTrigger>
                    <SelectContent className="rounded-2xl border-none shadow-2xl">
                      <SelectItem value="health_insurance" className="rounded-xl m-1">تأمين صحي</SelectItem>
                      <SelectItem value="life_insurance" className="rounded-xl m-1">تأمين على الحياة</SelectItem>
                      <SelectItem value="retirement" className="rounded-xl m-1">تقاعد ومساهمات</SelectItem>
                      <SelectItem value="transportation" className="rounded-xl m-1">بدل انتقال</SelectItem>
                      <SelectItem value="housing" className="rounded-xl m-1">بدل سكن</SelectItem>
                      <SelectItem value="other" className="rounded-xl m-1">أخرى</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-3">
                  <Label className="text-sm font-black text-gray-700 dark:text-gray-300 flex items-center gap-2">
                    <DollarSign className="h-4 w-4 text-primary" />
                    التكلفة الشهرية
                  </Label>
                  <div className="relative">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold text-sm">EGP</span>
                    <Input
                      type="number"
                      value={formData.cost}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          cost: parseFloat(e.target.value) || 0,
                        })
                      }
                      className="h-14 rounded-2xl bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm pl-16 text-lg font-black"
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-3 px-1">
                <Label className="text-sm font-black text-gray-700 dark:text-gray-300 flex items-center gap-2">
                  <HeartPulse className="h-4 w-4 text-primary" />
                  وصف الميزة وشروط الاستحقاق
                </Label>
                <Textarea
                  value={formData.description}
                  onChange={(e) =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  placeholder="اشرح هنا تفاصيل الميزة، من يستحقها، وكيفية تفعيلها..."
                  className="min-h-[120px] rounded-2xl bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm p-4 text-gray-600 dark:text-gray-400 resize-none leading-relaxed"
                />
              </div>
            </div>
          </ScrollArea>

          <DialogFooter className="p-8 pt-4 border-t border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-black/20 gap-3">
            <Button
              onClick={handleSubmit}
              disabled={submitting}
              className="flex-1 h-14 rounded-2xl font-black text-lg shadow-xl shadow-primary/20 hover:shadow-primary/30 transition-all active:scale-95"
            >
              {submitting ? (
                <div className="flex items-center gap-3">
                  <div className="h-5 w-5 border-3 border-white/30 border-t-white animate-spin rounded-full" />
                  جاري الحفظ...
                </div>
              ) : (
                <div className="flex items-center gap-2">
                  <Save className="h-5 w-5" />
                  {editingId ? "حفظ التعديلات" : "تأكيد إضافة الميزة"}
                </div>
              )}
            </Button>
            <Button
              variant="ghost"
              onClick={() => {
                setDialogOpen(false);
                if (location.pathname.endsWith("/new"))
                  navigate("/hr/benefits");
              }}
              className="h-14 px-8 rounded-2xl text-gray-500 font-bold hover:bg-gray-100 dark:hover:bg-gray-800"
            >
              إلغاء
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      {/* Benefit Details Dialog */}
      <Dialog
        open={detailsOpen}
        onOpenChange={(open) => {
          setDetailsOpen(open);
          if (!open) {
            setSelectedBenefit(null);
            navigate("/hr/benefits");
          }
        }}
      >
        <DialogContent
          className="sm:max-w-4xl rounded-3xl p-0 overflow-hidden border-none shadow-2xl bg-white/95 dark:bg-gray-900/95 backdrop-blur-md"
          dir="rtl"
        >
          {selectedBenefit && (
            <div className="flex flex-col max-h-[90vh]">
              <div className="p-8 bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border-b border-gray-100 dark:border-gray-800">
                <div className="flex flex-col md:flex-row items-start justify-between gap-6">
                  <div className="space-y-3 flex-1">
                    <div className="flex items-center gap-3">
                      <div className="p-3 bg-white dark:bg-gray-800 rounded-2xl shadow-sm">
                        {getTypeIcon(selectedBenefit.type)}
                      </div>
                      <div className="flex flex-col">
                        <Badge variant="outline" className="w-fit bg-white/50 dark:bg-white/5 border-primary/20 text-primary font-bold">
                          {getTypeLabel(selectedBenefit.type)}
                        </Badge>
                        <DialogTitle className="text-3xl font-black mt-1 text-gray-900 dark:text-gray-100">
                          {selectedBenefit.name}
                        </DialogTitle>
                      </div>
                    </div>
                    <DialogDescription className="text-gray-600 dark:text-gray-400 leading-relaxed max-w-2xl">
                      {selectedBenefit.description || "لا يوجد وصف متاح لهذه الميزة"}
                    </DialogDescription>
                  </div>
                  <div className="flex items-center gap-4 bg-white dark:bg-gray-800/50 p-5 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700/50 min-w-[200px]">
                    <div className="w-12 h-12 bg-orange-100 dark:bg-orange-500/20 rounded-2xl flex items-center justify-center text-orange-600 dark:text-orange-400 shadow-inner">
                      <Users className="h-6 w-6" />
                    </div>
                    <div>
                      <p className="text-[10px] text-gray-400 dark:text-gray-500 font-black uppercase tracking-widest mb-0.5">
                        المشتركون حالياً
                      </p>
                      <p className="text-3xl font-black text-gray-900 dark:text-gray-100 leading-none">
                        {selectedBenefit.activeEnrollments || 0}
                      </p>
                    </div>
                  </div>
                </div>
              </div>

              <Tabs defaultValue="enrollments" className="flex-1 flex flex-col min-h-0">
                <div className="px-8 border-b border-gray-100 dark:border-gray-800 bg-white/50 dark:bg-gray-900/50">
                  <TabsList className="bg-transparent gap-8 h-16">
                    <TabsTrigger
                      value="enrollments"
                      className="data-[state=active]:bg-transparent data-[state=active]:border-b-2 data-[state=active]:border-primary data-[state=active]:text-primary data-[state=active]:shadow-none rounded-none h-16 px-2 font-bold transition-all text-gray-500 dark:text-gray-400"
                    >
                      قائمة المشتركين
                    </TabsTrigger>
                    <TabsTrigger
                      value="add_enrollment"
                      className="data-[state=active]:bg-transparent data-[state=active]:border-b-2 data-[state=active]:border-primary data-[state=active]:text-primary data-[state=active]:shadow-none rounded-none h-16 px-2 font-bold transition-all text-gray-500 dark:text-gray-400"
                    >
                      إضافة مشترك جديد
                    </TabsTrigger>
                  </TabsList>
                </div>

                <div className="p-8 flex-1 overflow-y-auto custom-scrollbar bg-gray-50/30 dark:bg-black/20">
                  <TabsContent
                    value="enrollments"
                    className="m-0 focus-visible:outline-none data-[state=active]:flex data-[state=active]:flex-col"
                  >
                    {!selectedBenefit.enrollments ||
                      selectedBenefit.enrollments.length === 0 ? (
                      <div className="flex flex-col items-center justify-center py-20 text-center">
                        <div className="w-20 h-20 bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4">
                          <Users className="h-10 w-10 text-gray-400" />
                        </div>
                        <p className="font-bold text-gray-900 dark:text-gray-100">لا يوجد مشتركون حالياً</p>
                        <p className="text-sm text-gray-500">
                          ابدأ بإضافة موظفين للاستفادة من هذه الميزة
                        </p>
                      </div>
                    ) : (
                      <div className="overflow-hidden rounded-2xl border border-gray-100 dark:border-gray-800 bg-white dark:bg-gray-900 shadow-sm">
                        <Table>
                          <TableHeader>
                            <TableRow className="hover:bg-transparent border-b bg-gray-50/50 dark:bg-gray-800/50">
                              <TableHead className="text-right text-gray-900 dark:text-gray-100 font-bold py-4">
                                الموظف
                              </TableHead>
                              <TableHead className="text-right text-gray-900 dark:text-gray-100 font-bold">
                                تاريخ البدء
                              </TableHead>
                              <TableHead className="text-right text-gray-900 dark:text-gray-100 font-bold">
                                الحالة
                              </TableHead>
                              <TableHead className="text-left text-gray-900 dark:text-gray-100 font-bold">
                                ملاحظات
                              </TableHead>
                            </TableRow>
                          </TableHeader>
                          <TableBody>
                            {selectedBenefit.enrollments.map((en) => (
                              <TableRow
                                key={en.id}
                                className="group hover:bg-primary/5 dark:hover:bg-primary/10 border-b border-gray-50 dark:border-gray-800 transition-colors"
                              >
                                <TableCell className="py-4">
                                  <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-black uppercase">
                                      {en.employee.firstName[0]}
                                    </div>
                                    <div>
                                      <p className="font-bold text-gray-900 dark:text-gray-100">
                                        {en.employee.firstName}{" "}
                                        {en.employee.lastName}
                                      </p>
                                      <p className="text-xs text-gray-500">
                                        #{en.employee.employeeNumber}
                                      </p>
                                    </div>
                                  </div>
                                </TableCell>
                                <TableCell className="text-gray-600 dark:text-gray-400 font-medium">
                                  {new Date(en.startDate).toLocaleDateString(
                                    "ar-EG",
                                  )}
                                </TableCell>
                                <TableCell>
                                  <Badge
                                    className={
                                      en.status === "ACTIVE"
                                        ? "bg-emerald-100 text-emerald-700 hover:bg-emerald-100 border-none"
                                        : "bg-gray-100 text-gray-700 hover:bg-gray-100 border-none"
                                    }
                                  >
                                    {en.status === "ACTIVE" ? "نشط" : "ملغى"}
                                  </Badge>
                                </TableCell>
                                <TableCell className="text-xs text-gray-500 dark:text-gray-500 max-w-[200px] truncate italic">
                                  {en.notes || "-"}
                                </TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      </div>
                    )}
                  </TabsContent>

                  <TabsContent
                    value="add_enrollment"
                    className="m-0 focus-visible:outline-none data-[state=active]:flex data-[state=active]:flex-col"
                  >
                    <div className="max-w-2xl mx-auto space-y-8 pt-2 pb-12 w-full">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-3">
                          <Label className="text-sm font-black text-gray-700 dark:text-gray-300 flex items-center gap-2">
                            <Users className="h-4 w-4 text-primary" />
                            اختر الموظف المستفيد
                          </Label>
                          <Select
                            value={enrollmentFormData.employeeId}
                            onValueChange={(val) =>
                              setEnrollmentFormData({
                                ...enrollmentFormData,
                                employeeId: val,
                              })
                            }
                          >
                            <SelectTrigger className="h-14 rounded-2xl bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm focus:ring-2 focus:ring-primary/20 transition-all text-gray-900 dark:text-gray-100">
                              <SelectValue placeholder="ابحث عن الموظف..." />
                            </SelectTrigger>
                            <SelectContent className="rounded-2xl border-gray-100 dark:border-gray-800 shadow-2xl">
                              <div className="p-3 border-b border-gray-100 dark:border-gray-800 sticky top-0 bg-white dark:bg-gray-800 z-10">
                                <div className="relative">
                                  <Search className="absolute right-3 top-3 h-4 w-4 text-gray-400" />
                                  <Input
                                    placeholder="ابحث بالاسم أو الرقم الوظيفي..."
                                    className="h-10 pr-10 text-sm rounded-xl border-gray-100 dark:border-gray-700"
                                    onChange={(e) => {
                                      // Filter logic can be added here if needed
                                    }}
                                  />
                                </div>
                              </div>
                              <ScrollArea className="h-64">
                                {employees.length === 0 ? (
                                  <div className="p-8 text-center text-sm text-gray-400 italic">
                                    لا يوجد موظفون متاحون
                                  </div>
                                ) : (
                                  employees.map((emp) => (
                                    <SelectItem
                                      key={emp.id}
                                      value={emp.id}
                                      className="rounded-xl m-1 cursor-pointer focus:bg-primary/10"
                                    >
                                      <div className="flex flex-col text-right">
                                        <span className="font-bold">{emp.firstName} {emp.lastName}</span>
                                        <span className="text-[10px] text-gray-400">#{emp.employeeNumber}</span>
                                      </div>
                                    </SelectItem>
                                  ))
                                )}
                              </ScrollArea>
                            </SelectContent>
                          </Select>
                        </div>

                        <div className="space-y-3">
                          <Label className="text-sm font-black text-gray-700 dark:text-gray-300 flex items-center gap-2">
                            <CheckCircle className="h-4 w-4 text-primary" />
                            تاريخ بدء الاستحقاق
                          </Label>
                          <Input
                            type="date"
                            value={enrollmentFormData.startDate}
                            onChange={(e) =>
                              setEnrollmentFormData({
                                ...enrollmentFormData,
                                startDate: e.target.value,
                              })
                            }
                            className="h-14 rounded-2xl bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm focus:ring-2 focus:ring-primary/20 transition-all text-gray-900 dark:text-gray-100"
                          />
                        </div>
                      </div>

                      <div className="space-y-3">
                        <Label className="text-sm font-black text-gray-700 dark:text-gray-300 flex items-center gap-2">
                          <Pencil className="h-4 w-4 text-primary" />
                          ملاحظات إضافية
                        </Label>
                        <Textarea
                          value={enrollmentFormData.notes}
                          onChange={(e) =>
                            setEnrollmentFormData({
                              ...enrollmentFormData,
                              notes: e.target.value,
                            })
                          }
                          placeholder="أي تفاصيل خاصة باشتراك هذا الموظف (مثلاً: الفئة التأمينية، المرافقون...)"
                          className="min-h-[120px] rounded-2xl bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm focus:ring-2 focus:ring-primary/20 transition-all text-gray-900 dark:text-gray-100 resize-none p-4"
                        />
                      </div>

                      <Button
                        className="w-full h-14 rounded-2xl font-black text-lg shadow-xl shadow-primary/20 hover:shadow-primary/30 transition-all active:scale-[0.98]"
                        onClick={handleEnroll}
                        disabled={enrollLoading}
                      >
                        {enrollLoading ? (
                          <div className="flex items-center gap-3">
                            <div className="h-5 w-5 border-3 border-white/30 border-t-white animate-spin rounded-full" />
                            جاري الحفظ...
                          </div>
                        ) : (
                          <div className="flex items-center gap-2">
                            <Save className="h-5 w-5" />
                            تأكيد التسجيل في الميزة
                          </div>
                        )}
                      </Button>
                    </div>
                  </TabsContent>
                </div>
              </Tabs>
            </div>
          )
          }
        </DialogContent >
      </Dialog >
    </div >
  );
};

export default Benefits;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  CheckSquare,
  ArrowRight,
  Save,
  Circle,
  CheckCircle2,
} from "lucide-react";
import { toast } from "sonner";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Checkbox } from "../../components/ui/checkbox";
import { Badge } from "../../components/ui/badge";
import { Textarea } from "../../components/ui/textarea";

interface ClearanceItem {
  id: string;
  itemName: string;
  description: string;
  isCompleted: boolean;
  completedAt: string | null;
  completedBy: string | null;
  notes: string | null;
}

const ClearanceChecklist = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState<ClearanceItem[]>([]);
  const [resignation, setResignation] = useState<any>(null);

  useEffect(() => {
    fetchData();
  }, [id]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [resRes, checklistRes] = await Promise.all([
        api.get(`/hr/resignations/${id}`),
        api.get(`/hr/resignations/${id}/clearance`),
      ]);
      setResignation(resRes.data.resignation);
      setItems(checklistRes.data.items || []);
    } catch (error) {
      console.error("Error fetching clearance data:", error);
      toast.error("فشل في تحميل بيانات إخلاء الطرف");
    } finally {
      setLoading(false);
    }
  };

  const handleToggleItem = async (itemId: string, currentStatus: boolean) => {
    try {
      await api.patch(`/hr/resignations/clearance/${itemId}`, {
        isCompleted: !currentStatus,
      });

      // Update local state
      setItems(
        items.map((item) =>
          item.id === itemId
            ? {
                ...item,
                isCompleted: !currentStatus,
                completedAt: !currentStatus ? new Date().toISOString() : null,
              }
            : item,
        ),
      );

      toast.success(
        currentStatus ? "تم إلغاء الاكتمال" : "تم تحديد البند كمكتمل",
      );
    } catch (error) {
      console.error("Error updating item:", error);
      toast.error("فشل في تحديث الحالة");
    }
  };

  if (loading) return <div className="p-8 text-center">جاري التحميل...</div>;
  if (!resignation)
    return (
      <div className="p-8 text-center text-red-500">الاستقالة غير موجودة</div>
    );

  const completedCount = items.filter((i) => i.isCompleted).length;
  const progress = items.length > 0 ? (completedCount / items.length) * 100 : 0;

  return (
    <div className="p-6 w-full space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate("/hr/resignations")}
          >
            <ArrowRight className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <CheckSquare className="h-8 w-8 text-green-600" />
              قائمة إخلاء الطرف
            </h1>
            <p className="text-gray-500 mt-1">
              {resignation.employee?.firstName} {resignation.employee?.lastName}{" "}
              - {resignation.employee?.position?.title}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Badge variant={progress === 100 ? "default" : "secondary"}>
            {progress === 100 ? "مكتمل" : "قيد التنفيذ"}
          </Badge>
        </div>
      </div>

      {/* Progress */}
      <Card>
        <CardContent className="p-6">
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span>نسبة الإنجاز</span>
              <span>{Math.round(progress)}%</span>
            </div>
            <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
              <div
                className={`h-full transition-all duration-500 ${progress === 100 ? "bg-green-500" : "bg-blue-500"}`}
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Checklist Items */}
      <div className="space-y-4">
        {items.map((item) => (
          <Card
            key={item.id}
            className={`transition-colors ${item.isCompleted ? "bg-green-50 border-green-200" : ""}`}
          >
            <CardContent className="p-4 flex items-start gap-4">
              <Checkbox
                checked={item.isCompleted}
                onCheckedChange={() =>
                  handleToggleItem(item.id, item.isCompleted)
                }
                className="mt-1 h-5 w-5"
              />
              <div className="flex-1">
                <h3
                  className={`font-semibold ${item.isCompleted ? "text-green-800 line-through decoration-green-500" : "text-gray-800"}`}
                >
                  {item.itemName}
                </h3>
                <p className="text-sm text-gray-500 mt-1">{item.description}</p>
                {item.isCompleted && item.completedAt && (
                  <p className="text-xs text-green-600 mt-2 flex items-center gap-1">
                    <CheckCircle2 className="h-3 w-3" />
                    تم الإكمال في{" "}
                    {new Date(item.completedAt).toLocaleDateString()}
                  </p>
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {items.length === 0 && (
        <div className="text-center py-12 text-gray-500 bg-gray-50 rounded-lg border border-dashed">
          لا توجد بنود في قائمة إخلاء الطرف
        </div>
      )}
    </div>
  );
};

export default ClearanceChecklist;

import React, { useState, useEffect } from "react";
import {
  FileText,
  Plus,
  Edit,
  Trash2,
  Save,
  ChevronDown,
  ChevronRight,
  BookOpen,
  Clock,
  Search,
  Filter,
  AlertCircle,
  CheckCircle,
  XCircle,
  Eye,
} from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "../../components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { Badge } from "../../components/ui/badge";
import { toast } from "sonner";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import api from "../../services/api";

interface Policy {
  id: string;
  title: string;
  content: string;
  category: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
  version: number;
}

const categories = [
  { value: "attendance", label: "الحضور والانصراف" },
  { value: "leaves", label: "الإجازات" },
  { value: "conduct", label: "السلوك المهني" },
  { value: "compensation", label: "التعويضات والمزايا" },
  { value: "safety", label: "الصحة والسلامة" },
  { value: "it", label: "تكنولوجيا المعلومات" },
  { value: "general", label: "سياسات عامة" },
];

const CompanyPolicy: React.FC = () => {
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  // Dialog states
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [editingPolicy, setEditingPolicy] = useState<Policy | null>(null);
  const [viewingPolicy, setViewingPolicy] = useState<Policy | null>(null);

  // Form states
  const [formData, setFormData] = useState({
    title: "",
    content: "",
    category: "general",
    isActive: true,
  });

  // Fetch policies
  const fetchPolicies = async () => {
    setLoading(true);
    try {
      const { data } = await api.get("/hr/policies", {
        params: {
          category: selectedCategory !== "all" ? selectedCategory : undefined,
          search: searchQuery,
        },
      });
      if (data.success) {
        setPolicies(data.policies);
      }
    } catch (error) {
      console.error("Failed to fetch policies:", error);
      // Fallback to empty or mock if needed, but for now show error
      // toast.error('فشل في تحميل السياسات');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchPolicies();
    }, 500);
    return () => clearTimeout(timer);
  }, [searchQuery, selectedCategory]);

  const handleCreate = async () => {
    if (!formData.title || !formData.content) {
      toast.error("يرجى ملء جميع الحقول المطلوبة");
      return;
    }

    try {
      const { data } = await api.post("/hr/policies", formData);
      if (data.success) {
        toast.success("تم إنشاء السياسة بنجاح");
        setPolicies([data.policy, ...policies]);
        setIsAddDialogOpen(false);
        setFormData({
          title: "",
          content: "",
          category: "general",
          isActive: true,
        });
      }
    } catch (error) {
      toast.error("فشل في إنشاء السياسة");
    }
  };

  const handleUpdate = async () => {
    if (!editingPolicy) return;

    try {
      const { data } = await api.put(`/hr/policies/${editingPolicy.id}`, {
        title: editingPolicy.title,
        content: editingPolicy.content,
        category: editingPolicy.category,
        isActive: editingPolicy.isActive,
      });

      if (data.success) {
        toast.success("تم تحديث السياسة بنجاح");
        setPolicies(
          policies.map((p) => (p.id === editingPolicy.id ? data.policy : p)),
        );
        setEditingPolicy(null);
      }
    } catch (error) {
      toast.error("فشل في تحديث السياسة");
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذه السياسة؟")) return;

    try {
      await api.delete(`/hr/policies/${id}`);
      setPolicies(policies.filter((p) => p.id !== id));
      toast.success("تم حذف السياسة");
    } catch (error) {
      toast.error("فشل في حذف السياسة");
    }
  };

  const getCategoryLabel = (value: string) => {
    return categories.find((c) => c.value === value)?.label || value;
  };

  return (
    <div className="p-6 space-y-6" dir="rtl">
      {/* Header & Stats */}
      <div className="flex flex-col gap-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
              سياسات الشركة
            </h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">
              الدليل الشامل للوائح والقوانين التنظيمية
            </p>
          </div>
          <Button
            onClick={() => setIsAddDialogOpen(true)}
            className="bg-blue-600 hover:bg-blue-700"
          >
            <Plus className="h-4 w-4 ml-2" />
            إضافة سياسة جديدة
          </Button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white border-none shadow-md">
            <CardContent className="p-4 flex items-center justify-between">
              <div>
                <p className="text-blue-100 text-sm mb-1">إجمالي السياسات</p>
                <h3 className="text-2xl font-bold">{policies.length}</h3>
              </div>
              <div className="bg-white/20 p-2 rounded-lg">
                <FileText className="h-6 w-6 text-white" />
              </div>
            </CardContent>
          </Card>

          <Card className="bg-gradient-to-br from-emerald-500 to-emerald-600 text-white border-none shadow-md">
            <CardContent className="p-4 flex items-center justify-between">
              <div>
                <p className="text-emerald-100 text-sm mb-1">
                  السياسات الفعالة
                </p>
                <h3 className="text-2xl font-bold">
                  {policies.filter((p) => p.isActive).length}
                </h3>
              </div>
              <div className="bg-white/20 p-2 rounded-lg">
                <CheckCircle className="h-6 w-6 text-white" />
              </div>
            </CardContent>
          </Card>

          <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white border-none shadow-md">
            <CardContent className="p-4 flex items-center justify-between">
              <div>
                <p className="text-purple-100 text-sm mb-1">
                  التحديثات الأخيرة
                </p>
                <h3 className="text-2xl font-bold">
                  {
                    policies.filter((p) => {
                      const date = new Date(p.updatedAt);
                      const now = new Date();
                      const diffTime = Math.abs(now.getTime() - date.getTime());
                      const diffDays = Math.ceil(
                        diffTime / (1000 * 60 * 60 * 24),
                      );
                      return diffDays <= 30;
                    }).length
                  }
                </h3>
              </div>
              <div className="bg-white/20 p-2 rounded-lg">
                <Clock className="h-6 w-6 text-white" />
              </div>
            </CardContent>
          </Card>

          <Card className="bg-gradient-to-br from-orange-500 to-orange-600 text-white border-none shadow-md">
            <CardContent className="p-4 flex items-center justify-between">
              <div>
                <p className="text-orange-100 text-sm mb-1">فئات السياسات</p>
                <h3 className="text-2xl font-bold">
                  {new Set(policies.map((p) => p.category)).size}
                </h3>
              </div>
              <div className="bg-white/20 p-2 rounded-lg">
                <BookOpen className="h-6 w-6 text-white" />
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Filters & Search */}
      <Card className="border-none shadow-sm bg-white dark:bg-gray-900">
        <CardContent className="p-4">
          <div className="flex flex-col md:flex-row gap-4 items-center">
            <div className="relative flex-1 w-full">
              <Search className="absolute right-3 top-2.5 h-5 w-5 text-gray-400" />
              <Input
                placeholder="بحث في السياسات..."
                className="pr-10 w-full"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            <div className="w-full md:w-64">
              <Select
                value={selectedCategory}
                onValueChange={setSelectedCategory}
              >
                <SelectTrigger>
                  <SelectValue placeholder="تصفية حسب الفئة" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">جميع الفئات</SelectItem>
                  {categories.map((cat) => (
                    <SelectItem key={cat.value} value={cat.value}>
                      {cat.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Policies Table */}
      <Card className="border-none shadow-sm overflow-hidden">
        <CardContent className="p-0">
          {loading ? (
            <div className="p-8 flex justify-center">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
            </div>
          ) : policies.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-gray-500">
              <FileText className="h-16 w-16 mb-4 opacity-20" />
              <h3 className="text-lg font-semibold">لا توجد سياسات مطابقة</h3>
              <p>جرب تغيير معايير البحث أو أضف سياسة جديدة</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader className="bg-gray-50 dark:bg-gray-800">
                  <TableRow>
                    <TableHead className="text-right font-bold w-[300px]">عنوان السياسة</TableHead>
                    <TableHead className="text-right font-bold">الفئة</TableHead>
                    <TableHead className="text-right font-bold">الحالة</TableHead>
                    <TableHead className="text-right font-bold">الإصدار</TableHead>
                    <TableHead className="text-right font-bold">آخر تحديث</TableHead>
                    <TableHead className="text-left font-bold">الإجراءات</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {policies.map((policy) => (
                    <TableRow
                      key={policy.id}
                      className="hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors cursor-pointer group"
                      onClick={() => setViewingPolicy(policy)}
                    >
                      <TableCell className="font-medium">
                        <div className="flex items-center gap-3">
                          <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg group-hover:bg-blue-100 transition-colors">
                            <FileText className="h-4 w-4 text-blue-600" />
                          </div>
                          <span className="line-clamp-1">{policy.title}</span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge variant="secondary" className="font-normal">
                          {getCategoryLabel(policy.category)}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {policy.isActive ? (
                          <div className="flex items-center text-green-600 gap-1.5 text-xs font-semibold">
                            <CheckCircle className="h-3 w-3" />
                            نشط
                          </div>
                        ) : (
                          <div className="flex items-center text-red-600 gap-1.5 text-xs font-semibold">
                            <XCircle className="h-3 w-3" />
                            غير نشط
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        <span className="text-xs text-gray-500 font-mono">V{policy.version}.0</span>
                      </TableCell>
                      <TableCell className="text-xs text-gray-500">
                        {new Date(policy.updatedAt).toLocaleDateString("ar-EG")}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1 justify-end" onClick={(e) => e.stopPropagation()}>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-blue-600 hover:bg-blue-50"
                            onClick={() => setViewingPolicy(policy)}
                            title="عرض"
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-emerald-600 hover:bg-emerald-50"
                            onClick={() => setEditingPolicy(policy)}
                            title="تعديل"
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-red-600 hover:bg-red-50"
                            onClick={() => handleDelete(policy.id)}
                            title="حذف"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* View Policy Dialog */}
      <Dialog
        open={!!viewingPolicy}
        onOpenChange={() => setViewingPolicy(null)}
      >
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <div className="flex items-center gap-2 mb-2">
              <Badge variant="outline">
                {viewingPolicy && getCategoryLabel(viewingPolicy.category)}
              </Badge>
              <span className="text-sm text-gray-500">
                النسخة {viewingPolicy?.version}.0
              </span>
            </div>
            <DialogTitle className="text-2xl">
              {viewingPolicy?.title}
            </DialogTitle>
            <DialogDescription>
              تم التحديث في{" "}
              {viewingPolicy &&
                new Date(viewingPolicy.updatedAt).toLocaleDateString("ar-EG", {
                  dateStyle: "full",
                })}
            </DialogDescription>
          </DialogHeader>

          <div className="mt-6 prose prose-lg dark:prose-invert max-w-none">
            <div
              dangerouslySetInnerHTML={{ __html: viewingPolicy?.content || "" }}
            />
          </div>

          <DialogFooter className="mt-8 border-t pt-4">
            <Button onClick={() => setViewingPolicy(null)}>إغلاق</Button>
            <Button
              variant="outline"
              onClick={() => {
                setEditingPolicy(viewingPolicy);
                setViewingPolicy(null);
              }}
            >
              <Edit className="h-4 w-4 ml-2" />
              تعديل السياسة
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Add Policy Dialog */}
      <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>إضافة سياسة جديدة</DialogTitle>
