                <div className="space-y-2">
                  <Label>الفئة</Label>
                  <Select
                    value={editingPolicy.category}
                    onValueChange={(val) =>
                      setEditingPolicy({ ...editingPolicy, category: val })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {categories.map((cat) => (
                        <SelectItem key={cat.value} value={cat.value}>
                          {cat.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2">
                <Label>محتوى السياسة</Label>
                <div className="h-96 mb-12">
                  <ReactQuill
                    theme="snow"
                    value={editingPolicy.content}
                    onChange={(val) =>
                      setEditingPolicy({ ...editingPolicy, content: val })
                    }
                    className="h-80"
                    modules={{
                      toolbar: [
                        [{ header: [1, 2, 3, false] }],
                        ["bold", "italic", "underline", "strike"],
                        [{ list: "ordered" }, { list: "bullet" }],
                        ["link", "clean"],
                        [{ color: [] }, { background: [] }],
                        [{ align: [] }],
                      ],
                    }}
                  />
                </div>
              </div>

              <div className="flex items-center gap-2 mt-4">
                <input
                  type="checkbox"
                  id="edit-active"
                  checked={editingPolicy.isActive}
                  onChange={(e) =>
                    setEditingPolicy({
                      ...editingPolicy,
                      isActive: e.target.checked,
                    })
                  }
                  className="h-4 w-4 text-blue-600 rounded"
                />
                <Label htmlFor="edit-active">تفعيل السياسة</Label>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setEditingPolicy(null)}>
              إلغاء
            </Button>
            <Button onClick={handleUpdate}>حفظ التغييرات</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default CompanyPolicy;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useForm } from "react-hook-form";
import { ArrowRight, DollarSign } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Textarea } from "../../components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import api from "../../services/api";
import { toast } from "sonner";

interface AdvanceFormData {
  employeeId: string;
  amount: string;
  reason: string;
  repaymentType: string;
  installmentsCount: number;
}

interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  employeeNumber: string;
  position: { title: string } | null;
  hasEmployeeRecord: boolean;
}

const CreateAdvance: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [settings, setSettings] = useState<any>(null); // Store settings
  const {
    register,
    handleSubmit,
    watch,
    setValue,
    formState: { errors },
  } = useForm<AdvanceFormData>({
    defaultValues: {
      repaymentType: "ONE_TIME",
      installmentsCount: 1,
    },
  });

  const repaymentType = watch("repaymentType");

  useEffect(() => {
    register("employeeId", { required: true });
  }, [register]);

  useEffect(() => {
    const loadData = async () => {
      try {
        // Fetch Employees
        const empResponse = await api.get("/hr/employees?limit=1000");
        setEmployees(empResponse.data.employees || []);

        // Fetch Settings
        const settingsResponse = await api.get("/hr/settings");
        setSettings(settingsResponse.data.settings);
      } catch (error) {
        console.error("Error fetching data:", error);
        toast.error("حدث خطأ أثناء جلب البيانات");
      }
    };
    loadData();
  }, []);

  const onSubmit = async (data: AdvanceFormData) => {
    try {
      setLoading(true);
      await api.post("/hr/advances", {
        ...data,
        amount: parseFloat(data.amount),
        installmentsCount:
          data.repaymentType === "INSTALLMENTS" ? data.installmentsCount : 1,
      });

      toast.success("تم إنشاء طلب السلفة بنجاح");
      navigate("/hr/advances");
    } catch (error: any) {
      console.error("Error creating advance:", error);
      // Show detailed error message from backend
      toast.error(error.response?.data?.error || "حدث خطأ أثناء إنشاء الطلب");
    } finally {
      setLoading(false);
    }
  };

  const maxMonths = settings?.advanceRepaymentMonths || 12;

  return (
    <div className="p-6 w-full" dir="rtl">
      {/* Header */}
      <div className="mb-6">
        <Button
          variant="ghost"
          onClick={() => navigate("/hr/advances")}
          className="mb-4"
        >
          <ArrowRight className="h-4 w-4 ml-2" />
          العودة للقائمة
        </Button>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
          طلب سلفة جديد
        </h1>
        <p className="text-gray-500 dark:text-gray-400 mt-1">
          إنشاء طلب سلفة لموظف
        </p>
      </div>

      {/* Form */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <DollarSign className="h-5 w-5" />
            بيانات السلفة
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {/* Employee Selection */}
            <div className="space-y-2">
              <Label htmlFor="employeeId">الموظف *</Label>
              <Select onValueChange={(value) => setValue("employeeId", value)}>
                <SelectTrigger>
                  <SelectValue placeholder="اختر الموظف" />
                </SelectTrigger>
                <SelectContent>
                  {employees
                    .filter((emp) => emp.hasEmployeeRecord)
                    .map((employee) => (
                      <SelectItem key={employee.id} value={employee.id}>
                        {employee.firstName} {employee.lastName} -{" "}
                        {employee.position?.title || "لا يوجد منصب"}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
              {errors.employeeId && (
                <p className="text-sm text-red-500">هذا الحقل مطلوب</p>
              )}
            </div>

            {/* Amount */}
            <div className="space-y-2">
              <Label htmlFor="amount">المبلغ (جنيه) *</Label>
              <Input
                id="amount"
                type="number"
                step="0.01"
                placeholder="مثال: 5000"
                {...register("amount", { required: true, min: 1 })}
              />
              {settings && (
                <p className="text-xs text-gray-500">
                  الحد الأقصى: {settings.maxAdvancePercentage}% من الراتب
                </p>
              )}
              {errors.amount && (
                <p className="text-sm text-red-500">يرجى إدخال مبلغ صحيح</p>
              )}
            </div>

            {/* Repayment Type */}
            <div className="space-y-2">
              <Label htmlFor="repaymentType">نوع السداد *</Label>
              <Select
                defaultValue="ONE_TIME"
                onValueChange={(value) => setValue("repaymentType", value)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ONE_TIME">
                    دفعة واحدة (الشهر القادم)
                  </SelectItem>
                  <SelectItem value="INSTALLMENTS">
                    تقسيط على عدة أشهر
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Installments Count (if INSTALLMENTS) */}
            {repaymentType === "INSTALLMENTS" && (
              <div className="space-y-2">
                <Label htmlFor="installmentsCount">عدد الأقساط *</Label>
                <Input
                  id="installmentsCount"
                  type="number"
                  min="2"
                  max={maxMonths}
                  placeholder={`بحد أقصى ${maxMonths} أشهر`}
                  {...register("installmentsCount", {
                    required: repaymentType === "INSTALLMENTS",
                    min: 2,
                    max: maxMonths,
                  })}
                />
                {errors.installmentsCount && (
                  <p className="text-sm text-red-500">
                    يرجى إدخال عدد أقساط بين 2 و {maxMonths}
                  </p>
                )}
              </div>
            )}

            {/* Reason */}
            <div className="space-y-2">
              <Label htmlFor="reason">السبب (اختياري)</Label>
              <Textarea
                id="reason"
                placeholder="سبب طلب السلفة..."
                rows={4}
                {...register("reason")}
              />
            </div>

            {/* Submit Button */}
            <div className="flex gap-3 justify-end">
              <Button
                type="button"
                variant="outline"
                onClick={() => navigate("/hr/advances")}
              >
                إلغاء
              </Button>
              <Button type="submit" disabled={loading}>
                {loading ? "جاري الإنشاء..." : "إنشاء الطلب"}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
};

export default CreateAdvance;

import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useForm, Controller } from "react-hook-form";
import { toast } from "sonner";
import { Save, ArrowRight, Star, User, Info, AlertCircle } from "lucide-react";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Label } from "../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Checkbox } from "../../components/ui/checkbox";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Badge } from "../../components/ui/badge";

// Types
type FeedbackFormData = {
  toEmployeeId: string;
  type: string;
  category: string;
  content: string;
  rating: number;
  isAnonymous: boolean;
};

const CreateFeedback = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const isEdit = !!id;
  const isPersonal = window.location.pathname.startsWith("/my-feedback");
  const isHR = window.location.pathname.startsWith("/hr");
  const [employees, setEmployees] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [fetchingData, setFetchingData] = useState(isEdit);
  const [hoverRating, setHoverRating] = useState(0);

  const {
    register,
    handleSubmit,
    control,
    watch,
    setValue,
    formState: { errors },
  } = useForm<FeedbackFormData>({
    defaultValues: {
      toEmployeeId: isPersonal ? "management" : "",
      type: isPersonal ? "SUGGESTION" : "PEER",
      category: "",
      content: "",
      rating: 0,
      isAnonymous: false,
    },
  });

  const currentRating = watch("rating");
  const selectedEmployeeId = watch("toEmployeeId");
  const selectedEmployee = employees.find((e) => e.id === selectedEmployeeId);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const empRes = await api.get("/hr/employees");
        setEmployees(empRes.data.employees || []);

        if (isEdit) {
          const fbRes = await api.get(`/hr/feedback/${id}`);
          const currentFB = fbRes.data.feedback;

          if (currentFB) {
            setValue("toEmployeeId", currentFB.toUserId || "management");
            setValue("type", currentFB.type);
            setValue("category", currentFB.category || "");
            setValue("content", currentFB.content);
            setValue("rating", currentFB.rating || 0);
            setValue("isAnonymous", currentFB.isAnonymous);
          } else {
            toast.error("لم يتم العثور على التغذية الراجعة");
            navigate("/my-feedback");
          }
        }
      } catch (error) {
        console.error("Error fetching data:", error);
        toast.error("فشل في تحميل البيانات");
      } finally {
        setFetchingData(false);
      }
    };
    fetchData();
  }, [id, isEdit, setValue, navigate]);

  const onSubmit = async (data: FeedbackFormData) => {
    try {
      const isReviewType = ["PEER", "MANAGER", "SUBORDINATE"].includes(data.type);
      if (isReviewType && data.rating === 0) {
        toast.error("يرجى اختيار تقييم");
        return;
      }
      setLoading(true);
      const payload = {
        ...data,
        toUserId: data.toEmployeeId === "management" ? null : data.toEmployeeId,
        rating: isReviewType ? Number(data.rating) : null,
      };

      if (isEdit) {
        await api.put(`/hr/feedback/${id}`, payload);
        toast.success("تم تحديث الرسالة بنجاح");
      } else {
        await api.post("/hr/feedback", payload);
        toast.success("تم الإرسال بنجاح");
      }
      navigate("/my-feedback");
    } catch (error) {
      console.error("Error saving feedback:", error);
      toast.error(
        isEdit
          ? "فشل في تحديث البيانات"
          : "فشل في عملية الإرسال",
      );
    } finally {
      setLoading(false);
    }
  };

  if (fetchingData) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div
      className="p-6 max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 min-h-screen"
      dir="rtl"
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate(isPersonal ? "/my-feedback" : "/hr/feedback")}
            className="rounded-full shadow-sm hover:bg-muted"
          >
            <ArrowRight className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-extrabold tracking-tight text-foreground">
              {isEdit ? "تعديل الرسالة" : "إرسال شكوى أو اقتراح"}
            </h1>
            <p className="text-muted-foreground mt-1 text-lg">
              {isEdit
                ? "قم بتحديث تفاصيل رسالتك المرسلة"
                : isPersonal
                  ? "تعبيرك عن رأيك يساعدنا على تحسين بيئة العمل"
                  : "تواصل مع الإدارة أو شارك تقييمك لزملائك بكل شفافية"}
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Form */}
        <div className="lg:col-span-2 space-y-6">
          <Card className="border-none shadow-xl bg-card/60 backdrop-blur-sm border-t border-white/5">
            <CardHeader className="bg-muted/50 border-b dark:border-white/5">
              <CardTitle className="text-xl flex items-center gap-2">
                <Info className="h-5 w-5 text-primary" />
                تفاصيل الرسالة
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <div className="space-y-4">
                  {/* To Employee - Hide for personal mode as it defaults to management */}
                  {!isPersonal ? (
                    <div className="space-y-2">
                      <Label className="text-base font-semibold">
                        الموظف المستهدف
                      </Label>
                      <Controller
                        name="toEmployeeId"
                        control={control}
                        rules={{ required: "يجب اختيار الموظف" }}
                        render={({ field }) => (
                          <Select
                            onValueChange={field.onChange}
                            defaultValue={field.value}
                          >
                            <SelectTrigger className="h-12 bg-gray-50/30">
                              <SelectValue placeholder="اختر الموظف" />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="management">
                                <div className="flex items-center gap-2">
                                  <Avatar className="h-6 w-6">
                                    <AvatarFallback className="bg-primary/10 text-primary text-[10px]">
                                      HQ
                                    </AvatarFallback>
                                  </Avatar>
                                  <span className="font-bold">الإدارة (الشركة)</span>
                                </div>
                              </SelectItem>
                              {employees.map((emp) => (
                                <SelectItem key={emp.id} value={emp.id}>
                                  <div className="flex items-center gap-2">
                                    <Avatar className="h-6 w-6">
                                      <AvatarFallback className="text-[10px]">
                                        {emp.firstName?.[0] || ""}
                                        {emp.lastName?.[0] || ""}
                                      </AvatarFallback>
                                    </Avatar>
                                    <span>
                                      {emp.firstName} {emp.lastName}
                                    </span>
                                  </div>
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        )}
                      />
                      {errors.toEmployeeId && (
                        <p className="text-sm text-red-500 flex items-center gap-1">
                          <AlertCircle className="h-3 w-3" />{" "}
                          {errors.toEmployeeId.message}
                        </p>
                      )}
                    </div>
                  ) : (
                    <div className="bg-primary/5 p-4 rounded-xl border border-primary/10 flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold">HQ</div>
                        <div>
                          <p className="text-sm font-bold">جهة الإرسال</p>
                          <p className="text-xs text-muted-foreground">الإدارة العامة للشركة</p>
                        </div>
                      </div>
                      <Badge variant="outline" className="bg-white">رسالة رسمية</Badge>
                    </div>
                  )}

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Type */}
                    <div className="space-y-2">
                      <Label className="text-base font-semibold">
                        نوع الرسالة
                      </Label>
                      <Controller
                        name="type"
                        control={control}
                        render={({ field }) => (
                          <Select
                            onValueChange={field.onChange}
                            defaultValue={field.value}
                            value={field.value}
                          >
                            <SelectTrigger className="h-12 bg-muted/30 border-muted-foreground/20">
                              <SelectValue placeholder="اختر النوع" />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="SUGGESTION">اقتراح</SelectItem>
                              <SelectItem value="COMPLAINT">شكوى</SelectItem>
                              <SelectItem value="INQUIRY">استفسار</SelectItem>
                              {!isPersonal && (
                                <>
                                  <SelectItem value="PEER">تقييم زميل</SelectItem>
                                  <SelectItem value="MANAGER">تقييم مدير</SelectItem>
                                  <SelectItem value="SUBORDINATE">تقييم مرؤوس</SelectItem>
                                </>
                              )}
                              <SelectItem value="OTHER">آخر</SelectItem>
                            </SelectContent>
                          </Select>
                        )}
                      />
                    </div>

                    {/* Category */}
                    <div className="space-y-2">
                      <Label
                        htmlFor="category"
                        className="text-base font-semibold"
                      >
                        التصنيف (اختياري)
                      </Label>
                      <Input
                        id="category"
                        placeholder="مثال: أداء، سلوك، تعاون..."
                        className="h-12 bg-muted/30 border-muted-foreground/20 focus:bg-background transition-colors"
                        {...register("category")}
                      />
                    </div>
                  </div>

                  {/* Rating - Only show for HR mode and specific types */}
                  {!isPersonal && ["PEER", "MANAGER", "SUBORDINATE"].includes(watch("type")) && (
                    <div className="space-y-3 pt-2">
                      <Label className="text-base font-semibold">
                        التقييم
                      </Label>
                      <div className="flex items-center gap-2 bg-muted/20 p-4 rounded-xl border border-dashed border-muted-foreground/30">
                        {[1, 2, 3, 4, 5].map((star) => (
                          <button
                            key={star}
                            type="button"
                            className="transition-transform active:scale-90"
                            onMouseEnter={() => setHoverRating(star)}
                            onMouseLeave={() => setHoverRating(0)}
                            onClick={() => setValue("rating", star)}
                          >
                            <Star
                              className={`h-10 w-10 transition-colors ${(hoverRating || currentRating) >= star
                                ? "fill-yellow-500 text-yellow-500 shadow-[0_0_15px_rgba(234,179,8,0.3)]"
                                : "text-muted-foreground/30"
                                }`}
                            />
                          </button>
                        ))}
                        <span className="mr-4 font-bold text-xl text-yellow-600 dark:text-yellow-400">
                          {currentRating > 0
                            ? currentRating
                            : ""}
                        </span>
                      </div>
                    </div>
                  )}

                  {/* Content */}
                  <div className="space-y-2">
                    <Label
                      htmlFor="content"
                      className="text-base font-semibold"
                    >
                      رسالتك
                    </Label>
                    <Textarea
                      id="content"
                      placeholder="اكتب ملاحظاتك بشكل بناء ومفيد..."
                      className="min-h-[150px] bg-muted/30 border-muted-foreground/20 focus:bg-background resize-none transition-colors"
                      {...register("content", { required: "المحتوى مطلوب" })}
                    />
                    {errors.content && (
                      <p className="text-sm text-red-500 flex items-center gap-1">
                        <AlertCircle className="h-3 w-3" />{" "}
                        {errors.content.message}
                      </p>
                    )}
                  </div>

                  {/* Anonymous */}
                  <div className="flex items-center space-x-3 space-x-reverse p-4 bg-primary/5 rounded-xl border border-primary/10">
                    <Controller
                      name="isAnonymous"
                      control={control}
                      render={({ field }) => (
                        <Checkbox
                          id="isAnonymous"
                          checked={field.value}
                          onCheckedChange={field.onChange}
