          </form>
        </div>
      </div>
    </div>
  );
};

export default CreatePromotion;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useForm, Controller } from "react-hook-form";
import { toast } from "sonner";
import { Save, ArrowRight, FileX, Calculator, AlertCircle } from "lucide-react";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Label } from "../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { Card, CardContent } from "../../components/ui/card";

// Types
type ResignationFormData = {
  employeeId: string;
  resignationDate: string;
  lastWorkingDay: string;
  reason: string;
  exitInterview: string;
};

const CreateResignation = () => {
  const navigate = useNavigate();
  const [employees, setEmployees] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [noticePeriod, setNoticePeriod] = useState(30);
  const [expectedDate, setExpectedDate] = useState<string>("");

  const {
    register,
    handleSubmit,
    control,
    formState: { errors },
  } = useForm<ResignationFormData>({
    defaultValues: {
      employeeId: "",
      resignationDate: new Date().toISOString().split("T")[0],
      lastWorkingDay: "",
      reason: "",
      exitInterview: "",
    },
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [empRes, settingsRes] = await Promise.all([
          api.get("/hr/employees"),
          api.get("/hr/settings"),
        ]);

        // الآن جميع الموظفين المرجعين من Employee table صحيحين
        setEmployees(empRes.data.employees || []);
        console.log("Employees fetched:", empRes.data.employees?.length);

        if (settingsRes.data.settings?.noticePeriodDays) {
          setNoticePeriod(settingsRes.data.settings.noticePeriodDays);
        }
      } catch (error) {
        console.error("Error fetching data:", error);
        toast.error("فشل في تحميل البيانات");
      }
    };
    fetchData();
  }, []);

  // Watch resignation date to calculate expected last day
  const resignationDate = control._formValues.resignationDate; // Or use useWatch
  useEffect(() => {
    const subscription = control.register("resignationDate").onChange; // This isn't quite right for react-hook-form v7
    // We'll trust the re-render or useWatch if needed, but for simplicity let's stick to standard flow
    // Ideally useWatch
  }, []);

  // Better: useWatch for real-time updates
  // const watchedResignationDate = useWatch({ control, name: 'resignationDate' });
  // But since I can't easily add useWatch import without messing lines, I'll calculate on render if I can access form values
  // actually, I'll just calculate inside the render based on getValues or similar if I could.
  // Let's simplified: add onChange handler to Input directly or use a derived state.

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const date = new Date(e.target.value);
    if (!isNaN(date.getTime())) {
      const expected = new Date(date);
      expected.setDate(date.getDate() + noticePeriod);
      setExpectedDate(expected.toISOString().split("T")[0]);
    }
  };

  const onSubmit = async (data: ResignationFormData) => {
    try {
      setLoading(true);

      // Validate employeeId before submitting
      if (!data.employeeId || data.employeeId.trim() === "") {
        toast.error("يجب اختيار الموظف");
        return;
      }

      console.log("Submitting resignation data:", data);
      await api.post("/hr/resignations", data);
      toast.success("تم تسجيل الاستقالة بنجاح");
      navigate("/hr/resignations");
    } catch (error: any) {
      console.error("Error creating resignation:", error);
      toast.error(error.response?.data?.error || "فشل في تسجيل الاستقالة");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 w-full space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate("/hr/resignations")}
          >
            <ArrowRight className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <FileX className="h-8 w-8 text-red-500" />
              تسجيل استقالة جديدة
            </h1>
            <p className="text-gray-500 mt-1">
              إنهاء خدمة موظف وتسجيل تفاصيل الاستقالة
            </p>
          </div>
        </div>
      </div>

      <Card>
        <CardContent className="p-6">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Employee */}
              <div className="space-y-2">
                <Label>
                  الموظف <span className="text-red-500">*</span>
                </Label>
                <Controller
                  name="employeeId"
                  control={control}
                  rules={{ required: "يجب اختيار الموظف" }}
                  render={({ field }) => (
                    <Select onValueChange={field.onChange} value={field.value}>
                      <SelectTrigger>
                        <SelectValue placeholder="اختر الموظف" />
                      </SelectTrigger>
                      <SelectContent>
                        {employees.length === 0 ? (
                          <SelectItem value="no-employees" disabled>
                            لا يوجد موظفين متاحين
                          </SelectItem>
                        ) : (
                          employees.map((emp) => (
                            <SelectItem key={emp.id} value={emp.id}>
                              {emp.firstName} {emp.lastName} -{" "}
                              {emp.employeeNumber}
                            </SelectItem>
                          ))
                        )}
                      </SelectContent>
                    </Select>
                  )}
                />
                {errors.employeeId && (
                  <p className="text-sm text-red-500">
                    {errors.employeeId.message}
                  </p>
                )}
                {employees.length === 0 && (
                  <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3 mt-2 flex items-start gap-3">
                    <AlertCircle className="h-5 w-5 text-yellow-600 mt-0.5" />
                    <p className="text-sm text-yellow-700">
                      لا يوجد موظفين مسجلين في النظام. يجب إضافة موظفين أولاً من
                      قسم الموظفين.
                    </p>
                  </div>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="resignationDate">
                  تاريخ تقديم الاستقالة <span className="text-red-500">*</span>
                </Label>
                <Input
                  id="resignationDate"
                  type="date"
                  {...register("resignationDate", {
                    required: "التاريخ مطلوب",
                  })}
                  onChange={(e) => {
                    register("resignationDate").onChange(e);
                    handleDateChange(e);
                  }}
                />
                {errors.resignationDate && (
                  <p className="text-sm text-red-500">
                    {errors.resignationDate.message}
                  </p>
                )}

                {expectedDate && (
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 mt-2 flex items-start gap-3">
                    <Calculator className="h-5 w-5 text-blue-500 mt-0.5" />
                    <div>
                      <h4 className="text-sm font-semibold text-blue-700">
                        فترة الإشعار: {noticePeriod} يوم
                      </h4>
                      <p className="text-xs text-blue-600 mt-1">
                        تاريخ آخر عمل متوقع: <strong>{expectedDate}</strong>
                      </p>
                    </div>
                  </div>
                )}
              </div>

              {/* Last Working Day */}
              <div className="space-y-2">
                <Label htmlFor="lastWorkingDay">
                  آخر يوم عمل <span className="text-red-500">*</span>
                </Label>
                <Input
                  id="lastWorkingDay"
                  type="date"
                  {...register("lastWorkingDay", {
                    required: "تاريخ آخر يوم عمل مطلوب",
                  })}
                />
                {errors.lastWorkingDay && (
                  <p className="text-sm text-red-500">
                    {errors.lastWorkingDay.message}
                  </p>
                )}
              </div>
            </div>

            {/* Reason */}
            <div className="space-y-2">
              <Label htmlFor="reason">سبب الاستقالة</Label>
              <Textarea
                id="reason"
                placeholder="اذكر سبب الاستقالة..."
                className="min-h-[100px]"
                {...register("reason")}
              />
            </div>

            {/* Exit Interview Note */}
            <div className="space-y-2">
              <Label htmlFor="exitInterview">
                ملاحظات مقابلة الخروج (Exit Interview)
              </Label>
              <Textarea
                id="exitInterview"
                placeholder="تفاصيل المقابلة، ملاحظات إضافية..."
                className="min-h-[100px]"
                {...register("exitInterview")}
              />
            </div>

            <div className="flex justify-end pt-4 gap-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => navigate("/hr/resignations")}
              >
                إلغاء
              </Button>
              <Button
                type="submit"
                disabled={loading}
                size="lg"
                variant="destructive"
              >
                {loading ? (
                  "جاري الحفظ..."
                ) : (
                  <>
                    <Save className="h-4 w-4 ml-2" />
                    حفظ الاستقالة
                  </>
                )}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
};

export default CreateResignation;

import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useForm, Controller } from "react-hook-form";
import { toast } from "sonner";
import {
  Save,
  ArrowRight,
  AlertCircle,
  BookOpen,
  User,
  Calendar,
  Lightbulb,
  DollarSign,
  Clock,
  Award,
  FileText,
  CheckCircle2,
  Layout as LayoutIcon,
  Trash2,
} from "lucide-react";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Label } from "../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";

// Types
type TrainingFormData = {
  employeeId: string;
  trainingName: string;
  provider: string;
  type: string;
  startDate: string;
  endDate: string;
  status: "PLANNED" | "ONGOING" | "COMPLETED" | "CANCELLED";
  cost: string;
  duration: string;
  score: string;
  description: string;
};

const CreateTraining = () => {
  const { id } = useParams<{ id?: string }>();
  const isEdit = !!id;
  const navigate = useNavigate();
  const [employees, setEmployees] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(isEdit);

  const {
    register,
    handleSubmit,
    control,
    setValue,
    reset,
    formState: { errors },
  } = useForm<TrainingFormData>({
    defaultValues: {
      employeeId: "",
      trainingName: "",
      provider: "",
      type: "technical",
      cost: "",
      duration: "",
      score: "",
      status: "PLANNED",
      description: "",
    },
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch employees for the dropdown
        const empRes = await api.get("/hr/employees");
        setEmployees(empRes.data.employees || []);

        // If editing, fetch the training record
        if (isEdit) {
          setFetching(true);
          const trainingRes = await api.get(`/hr/trainings/${id}`);
          const training = trainingRes.data.training;

          if (training) {
            reset({
              employeeId: training.userId || training.employeeId,
              trainingName: training.trainingName,
              provider: training.provider || "",
              type: training.type || "technical",
              startDate: training.startDate
                ? new Date(training.startDate).toISOString().split("T")[0]
                : "",
              endDate: training.endDate
                ? new Date(training.endDate).toISOString().split("T")[0]
                : "",
              status: training.status,
              cost: training.cost?.toString() || "",
              duration: training.duration?.toString() || "",
              score: training.score?.toString() || "",
              description: training.description || "",
            });
          }
        }
      } catch (error) {
        console.error("Error fetching data:", error);
        toast.error("فشل في تحميل البيانات");
      } finally {
        setFetching(false);
      }
    };
    fetchData();
  }, [id, isEdit, reset]);

  const onSubmit = async (data: TrainingFormData) => {
    try {
      setLoading(true);

      if (!data.employeeId || data.employeeId.trim() === "") {
        toast.error("يجب اختيار الموظف");
        return;
      }

      const payload = {
        ...data,
        employeeId: data.employeeId, // Backend expects employeeId (which is userId in service)
        cost: data.cost ? Number(data.cost) : 0,
        duration: data.duration ? Number(data.duration) : 0,
        score: data.score ? Number(data.score) : null,
      };

      if (isEdit) {
        await api.put(`/hr/trainings/${id}`, payload);
        toast.success("تم تحديث البرنامج التدريبي بنجاح");
      } else {
        await api.post("/hr/trainings", payload);
        toast.success("تم إضافة البرنامج التدريبي بنجاح");
      }

      navigate("/hr/training");
    } catch (error: any) {
      console.error("Error saving training:", error);
      toast.error(error.response?.data?.error || "فشل في حفظ بيانات التدريب");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm("هل أنت متأكد من حذف هذا السجل التدريبي؟")) return;

    try {
      setLoading(true);
      await api.delete(`/hr/trainings/${id}`);
      toast.success("تم حذف السجل التدريبي بنجاح");
      navigate("/hr/training");
    } catch (error: any) {
      console.error("Error deleting training:", error);
      toast.error(error.response?.data?.error || "فشل في حذف سجل التدريب");
    } finally {
      setLoading(false);
    }
  };

  const trainingTypes = [
    { value: "technical", label: "تقني / فني" },
    { value: "soft-skills", label: "مهارات ناعمة / تواصل" },
    { value: "management", label: "إداري / قيادي" },
    { value: "safety", label: "صحة وسلامة مهنية" },
    { value: "language", label: "لغات" },
    { value: "onboarding", label: "تأهيل موظف جديد" },
    { value: "compliance", label: "امتثال وقوانين" },
    { value: "other", label: "أخرى" },
  ];

  const statusOptions = [
    {
      value: "PLANNED",
      label: "مخطط",
      color: "bg-blue-100 text-blue-700 border-blue-200",
    },
    {
      value: "ONGOING",
      label: "قيد التنفيذ",
      color: "bg-amber-100 text-amber-700 border-amber-200",
    },
    {
      value: "COMPLETED",
      label: "مكتمل",
      color: "bg-emerald-100 text-emerald-700 border-emerald-200",
    },
    {
      value: "CANCELLED",
      label: "ملغي",
      color: "bg-rose-100 text-rose-700 border-rose-200",
    },
  ];

  return (
    <div
      className="hr-theme min-h-screen p-4 md:p-8 w-full space-y-8"
      dir="rtl"
    >
      {/* Elegant Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 animate-in fade-in slide-in-from-top-4 duration-500">
        <div className="flex items-center gap-4">
          <Button
            variant="outline"
            size="icon"
            onClick={() => navigate("/hr/training")}
            className="rounded-full bg-white/80 backdrop-blur-sm border-purple-200 hover:bg-purple-50 hover:border-purple-300 transition-all shadow-sm"
          >
            <ArrowRight className="h-5 w-5 text-purple-600" />
          </Button>
          <div>
            <h1 className="text-3xl font-black tracking-tight text-transparent bg-clip-text bg-gradient-to-r from-purple-700 via-pink-600 to-indigo-600">
              إضافة سجل تدريبي
            </h1>
            <p className="text-gray-500 font-medium flex items-center gap-2 mt-1">
              <BookOpen className="h-4 w-4 text-purple-400" />
              توثيق الدورات التدريبية والتطويرية للموظفين
            </p>
          </div>
        </div>

      </div>

      <form
        onSubmit={handleSubmit(onSubmit)}
        className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-100"
      >
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Sidebar: Main Info */}
          <div className="lg:col-span-1 space-y-6">
            <Card className="overflow-hidden border-none shadow-xl ring-1 ring-purple-100/50">
              <div className="h-2 bg-gradient-to-r from-purple-500 to-indigo-500" />
              <CardContent className="p-6 space-y-6">
                <h3 className="text-lg font-bold flex items-center gap-2 text-purple-800">
                  <User className="h-5 w-5" />
                  الموظف والبرنامج
                </h3>

                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label className="font-bold flex items-center gap-2">
                      الموظف <span className="text-rose-500">*</span>
                    </Label>
                    <Controller
                      name="employeeId"
                      control={control}
                      rules={{ required: "يجب اختيار الموظف" }}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          value={field.value}
                        >
                          <SelectTrigger className="h-12 border-purple-100 focus:ring-purple-200 rounded-xl bg-gray-50/30">
                            <SelectValue placeholder="اختر الموظف المستهدف" />
                          </SelectTrigger>
                          <SelectContent className="max-h-72">
                            {employees.length === 0 ? (
                              <SelectItem value="no-employees" disabled>
                                لا يوجد موظفين حالياً
                              </SelectItem>
                            ) : (
                              employees.map((emp) => (
                                <SelectItem
                                  key={emp.id}
                                  value={emp.id}
                                  className="py-3"
                                >
                                  <div className="flex flex-col gap-0.5">
                                    <span className="font-bold text-gray-900">
                                      {emp.firstName} {emp.lastName}
                                    </span>
                                    <span className="text-[10px] text-gray-500">
                                      #{emp.employeeNumber} |{" "}
                                      {emp.position?.title || "موظف"}
                                    </span>
                                  </div>
                                </SelectItem>
                              ))
                            )}
                          </SelectContent>
                        </Select>
                      )}
                    />
                    {errors.employeeId && (
                      <p className="text-xs font-bold text-rose-500 flex items-center gap-1 mt-1">
                        <AlertCircle className="h-3 w-3" />{" "}
                        {errors.employeeId.message}
                      </p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <Label className="font-bold flex items-center gap-2">
                      اسم البرنامج <span className="text-rose-500">*</span>
                    </Label>
                    <Input
                      placeholder="مثال: تحليل البيانات باستخدام Excel"
                      className="h-12 border-purple-100 focus:ring-purple-200 rounded-xl"
                      {...register("trainingName", {
                        required: "اسم البرنامج مطلوب",
                      })}
                    />
                    {errors.trainingName && (
                      <p className="text-xs font-bold text-rose-500 mt-1">
                        {errors.trainingName.message}
                      </p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <Label className="font-bold">نوع التدريب</Label>
                    <Controller
                      name="type"
                      control={control}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          value={field.value}
                        >
                          <SelectTrigger className="h-12 border-purple-100 rounded-xl bg-gray-50/30">
                            <SelectValue placeholder="اختر تصنيف البرنامج" />
                          </SelectTrigger>
                          <SelectContent>
                            {trainingTypes.map((t) => (
                              <SelectItem key={t.value} value={t.value}>
                                {t.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="bg-gradient-to-br from-indigo-600 to-purple-700 text-white border-none shadow-xl overflow-hidden relative">
              <div className="absolute -right-4 -bottom-4 opacity-10">
                <Award className="w-32 h-32" />
              </div>
              <CardContent className="p-6 space-y-4">
                <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center">
                  <Lightbulb className="h-6 w-6 text-yellow-300" />
                </div>
                <h3 className="text-xl font-black">نصيحة التدريب</h3>
                <p className="text-indigo-100 text-sm leading-relaxed font-medium">
                  احرص على رفع شهادة التدريب في قسم المستندات بعد انتهاء
                  البرنامج لتوثيق السجل المهني للموظف.
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Main Section: Schedule & Details */}
          <div className="lg:col-span-2 space-y-8">
            <Card className="border-none shadow-xl ring-1 ring-purple-100/50">
              <CardHeader className="border-b border-gray-50 bg-gray-50/30">
                <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-800">
                  <Clock className="h-5 w-5" />
                  التوقيت والحالة
                </h3>
              </CardHeader>
              <CardContent className="p-6 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-2">
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label className="font-bold flex items-center gap-2">
                        تاريخ البدء <span className="text-rose-500">*</span>
                      </Label>
                      <div className="relative">
                        <Calendar className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                        <Input
                          type="date"
                          className="h-12 pr-10 border-purple-50 focus:ring-purple-200 rounded-xl"
                          {...register("startDate", {
                            required: "تاريخ البدء مطلوب",
                          })}
                        />
                      </div>
                      {errors.startDate && (
                        <p className="text-xs font-bold text-rose-500 mt-1">
                          {errors.startDate.message}
                        </p>
                      )}
                    </div>

                    <div className="space-y-2">
                      <Label className="font-bold">
                        تاريخ الانتهاء المتوقع
                      </Label>
                      <div className="relative">
                        <Calendar className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                        <Input
                          type="date"
                          className="h-12 pr-10 border-purple-50 focus:ring-purple-200 rounded-xl"
                          {...register("endDate")}
                        />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label className="font-bold">حالة التدريب</Label>
                      <Controller
                        name="status"
                        control={control}
                        render={({ field }) => (
                          <div className="grid grid-cols-2 gap-2">
                            {statusOptions.map((opt) => (
                              <button
                                key={opt.value}
                                type="button"
                                onClick={() => field.onChange(opt.value)}
                                className={`px-3 py-3 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${field.value === opt.value
                                  ? `${opt.color} shadow-sm ring-2 ring-offset-1 ring-purple-100`
                                  : "bg-white text-gray-500 border-gray-100 hover:border-purple-200"
                                  }`}
                              >
                                {field.value === opt.value && (
                                  <CheckCircle2 className="h-3 w-3" />
                                )}
                                {opt.label}
                              </button>
                            ))}
                          </div>
                        )}
                      />
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-2">
                      <div className="space-y-2">
                        <Label className="font-bold flex items-center gap-2">
                          <Clock className="h-4 w-4 text-indigo-400" />
                          المدة (ساعة)
                        </Label>
                        <Input
                          type="number"
                          placeholder="0"
                          className="h-12 border-purple-50 focus:ring-purple-200 rounded-xl"
                          {...register("duration")}
                        />
                      </div>
                      <div className="space-y-2">
                        <Label className="font-bold flex items-center gap-2">
                          <Save className="h-4 w-4 text-purple-400" />
                          الجهة المنظمة
                        </Label>
                        <Input
                          placeholder="مركز التدريب..."
                          className="h-12 border-purple-50 focus:ring-purple-200 rounded-xl"
                          {...register("provider")}
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="border-none shadow-xl ring-1 ring-purple-100/50">
              <CardHeader className="border-b border-gray-50 bg-gray-50/30">
                <h3 className="text-lg font-bold flex items-center gap-2 text-purple-800">
                  <DollarSign className="h-5 w-5" />
                  الاستثمار والنتائج
                </h3>
              </CardHeader>
              <CardContent className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <Label className="font-bold flex items-center gap-2">
                      تكلفة البرنامج التدريبي
                    </Label>
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 font-bold text-gray-400 text-sm">
                        EGP
                      </span>
                      <Input
                        id="cost"
                        type="number"
                        placeholder="0.00"
                        className="h-14 pl-12 text-lg font-bold border-purple-50 focus:ring-purple-200 rounded-xl bg-gray-50/20"
                        {...register("cost")}
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label className="font-bold flex items-center gap-2">
                      الدرجة أو النتيجة النهائية
                    </Label>
                    <div className="relative">
                      <Award className="absolute right-4 top-1/2 -translate-y-1/2 h-5 w-5 text-amber-500" />
                      <Input
                        id="score"
                        type="number"
                        max="100"
                        placeholder="الدرجة من 100"
                        className="h-14 pr-12 text-lg font-bold border-purple-50 focus:ring-purple-200 rounded-xl bg-gray-50/20"
                        {...register("score")}
                      />
                    </div>
                  </div>

                  <div className="col-span-full space-y-2">
                    <Label className="font-bold flex items-center gap-2">
                      <FileText className="h-4 w-4 text-gray-400" />
                      وصف البرنامج وملاحظات إضافية
                    </Label>
                    <Textarea
                      placeholder="اكتب هنا تفاصيل المنهج التدريبي أو أي تقييم إضافي لأداء الموظف خلال التدريب..."
                      className="min-h-[120px] border-purple-50 focus:ring-purple-200 rounded-xl resize-none p-4"
                      {...register("description")}
                    />
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Desktop & Mobile Actions at the bottom */}
            <div className="flex flex-col md:flex-row items-center justify-end gap-4 py-8 mt-4 border-t border-purple-100/50">
              <Button
                type="button"
                variant="ghost"
                onClick={() => navigate("/hr/training")}
                className="w-full md:w-auto font-bold text-gray-500 hover:bg-gray-100 rounded-xl px-8 h-12"
              >
                إلغاء التغييرات
              </Button>

              {isEdit && (
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleDelete}
                  disabled={loading}
                  className="w-full md:w-auto font-bold text-rose-600 border-rose-100 hover:bg-rose-50 rounded-xl px-8 h-12"
                >
                  <Trash2 className="h-4 w-4 ml-2" />
                  حذف السجل نهائياً
                </Button>
              )}

              <Button
                type="submit"
                disabled={loading}
                className="w-full md:w-auto h-14 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white font-black px-12 rounded-xl shadow-xl shadow-purple-200 transition-all hover:scale-[1.02] active:scale-[0.98] text-lg"
              >
                {loading ? (
                  <div className="flex items-center gap-2">
                    <div className="h-5 w-5 border-2 border-white/30 border-t-white animate-spin rounded-full" />
                    جاري الحفظ...
                  </div>
                ) : (
                  <>
                    <Save className="h-5 w-5 ml-2" />
                    حفظ السجل التدريبي
                  </>
                )}
              </Button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

export default CreateTraining;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useForm, Controller } from "react-hook-form";
import { toast } from "sonner";
import {
  Save,
  ArrowRight,
  AlertTriangle,
  AlertCircle,
  Calendar,
  FileText,
  User,
  ShieldAlert,
  Gavel,
  Eye,
} from "lucide-react";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Label } from "../../components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Badge } from "../../components/ui/badge";

// Types
type WarningFormData = {
  employeeId: string;
  type: "VERBAL" | "WRITTEN" | "FINAL" | "TERMINATION";
  severity: "minor" | "medium" | "major" | "critical";
  title: string;
  description: string;
  incidentDate: string;
  actionTaken: string;
};

const CreateWarning = () => {
  const navigate = useNavigate();
  const [employees, setEmployees] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);
  const [showPreview, setShowPreview] = useState(false);

  const {
    register,
    handleSubmit,
    control,
    watch,
    formState: { errors },
  } = useForm<WarningFormData>({
    defaultValues: {
      employeeId: "",
      type: "VERBAL",
      severity: "minor",
      title: "",
      description: "",
      incidentDate: new Date().toISOString().split("T")[0],
      actionTaken: "",
    },
  });

  const selectedEmployeeId = watch("employeeId");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const empRes = await api.get("/hr/employees");
        setEmployees(empRes.data.employees || []);
      } catch (error) {
        console.error("Error fetching data:", error);
        toast.error("فشل في تحميل بيانات الموظفين");
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (selectedEmployeeId) {
      const employee = employees.find((e) => e.id === selectedEmployeeId);
      setSelectedEmployee(employee);
    }
  }, [selectedEmployeeId, employees]);

  const onSubmit = async (data: WarningFormData) => {
    try {
      setLoading(true);

      if (!data.employeeId || data.employeeId.trim() === "") {
        toast.error("يجب اختيار الموظف");
        return;
      }

      await api.post("/hr/warnings", data);
      toast.success("تم إصدار الإنذار بنجاح");
      navigate("/hr/warnings");
    } catch (error: any) {
      console.error("Error creating warning:", error);
      toast.error(error.response?.data?.error || "فشل في إصدار الإنذار");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="p-6 max-w-5xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate("/hr/warnings")}
            className="rounded-full hover:bg-muted"
          >
            <ArrowRight className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2 text-foreground">
              <ShieldAlert className="h-8 w-8 text-red-500" />
              إصدار مخالفة إدارية
            </h1>
            <p className="text-muted-foreground mt-1 text-lg">
              توثيق إجراء تأديبي أو مخالفة وفقاً للوائح الشركة
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Form */}
        <div className="lg:col-span-2 space-y-6">
          <Card className="border-none shadow-xl bg-card/50 backdrop-blur-sm">
            <CardHeader className="border-b bg-muted/30">
              <CardTitle className="text-xl flex items-center gap-2">
                <FileText className="h-5 w-5 text-primary" />
                تفاصيل المخالفة
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                {/* Employee Selection */}
                <div className="space-y-2">
                  <Label className="text-base font-semibold">
                    الموظف المعني <span className="text-red-500">*</span>
                  </Label>
                  <Controller
                    name="employeeId"
                    control={control}
                    rules={{ required: "يجب اختيار الموظف" }}
                    render={({ field }) => (
                      <Select
                        onValueChange={field.onChange}
                        value={field.value}
                      >
                        <SelectTrigger className="h-12 bg-background/50">
                          <SelectValue placeholder="بحث عن موظف..." />
                        </SelectTrigger>
                        <SelectContent>
                          {employees.length === 0 ? (
                            <SelectItem value="no-employees" disabled>
                              لا يوجد موظفين متاحين
                            </SelectItem>
                          ) : (
                            employees.map((emp) => (
                              <SelectItem key={emp.id} value={emp.id}>
                                <div className="flex items-center gap-2">
                                  <Avatar className="h-6 w-6">
                                    <AvatarFallback>
                                      {emp.firstName?.[0]}
                                    </AvatarFallback>
                                  </Avatar>
                                  <span>
                                    {emp.firstName} {emp.lastName}
                                  </span>
                                  <span className="text-muted-foreground text-xs">
                                    ({emp.employeeNumber})
                                  </span>
                                </div>
                              </SelectItem>
                            ))
                          )}
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {errors.employeeId && (
                    <p className="text-sm text-red-500 flex items-center gap-1">
                      <AlertCircle className="h-3 w-3" />{" "}
                      {errors.employeeId.message}
                    </p>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {/* Incident Date */}
                  <div className="space-y-2">
                    <Label className="text-base font-semibold">
                      تاريخ الواقعة <span className="text-red-500">*</span>
                    </Label>
                    <div className="relative">
                      <Calendar className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                      <Input
                        type="date"
                        className="h-12 pr-10 bg-background/50"
                        {...register("incidentDate", {
                          required: "التاريخ مطلوب",
                        })}
                      />
                    </div>
                    {errors.incidentDate && (
                      <p className="text-sm text-red-500">
                        {errors.incidentDate.message}
                      </p>
                    )}
                  </div>

                  {/* Type */}
                  <div className="space-y-2">
                    <Label className="text-base font-semibold">
                      نوع الإجراء <span className="text-red-500">*</span>
                    </Label>
                    <Controller
                      name="type"
                      control={control}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          defaultValue={field.value}
                        >
                          <SelectTrigger className="h-12 bg-background/50">
                            <SelectValue placeholder="اختر النوع" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="VERBAL">تنبيه شفهي</SelectItem>
                            <SelectItem value="WRITTEN">إنذار كتابي</SelectItem>
                            <SelectItem value="FINAL">إنذار نهائي</SelectItem>
                            <SelectItem value="TERMINATION">
                              قرار فصل / إنهاء خدمات
                            </SelectItem>
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>
                </div>

                {/* Severity & Title */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-2">
                    <Label className="text-base font-semibold">
                      درجة الخطورة
                    </Label>
                    <Controller
                      name="severity"
                      control={control}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          defaultValue={field.value}
                        >
                          <SelectTrigger className="h-12 bg-background/50">
                            <SelectValue placeholder="اختر الشدة" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="minor">بسيطة (Low)</SelectItem>
                            <SelectItem value="medium">
                              متوسطة (Medium)
                            </SelectItem>
                            <SelectItem value="major">جسيمة (High)</SelectItem>
                            <SelectItem value="critical">
                              حرجة (Critical)
                            </SelectItem>
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>
                  <div className="md:col-span-2 space-y-2">
                    <Label className="text-base font-semibold">
                      عنوان المخالفة <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      placeholder="مثال: الغياب المتكرر بدون عذر..."
                      className="h-12 bg-background/50"
                      {...register("title", { required: "العنوان مطلوب" })}
                    />
                    {errors.title && (
                      <p className="text-sm text-red-500">
                        {errors.title.message}
                      </p>
                    )}
                  </div>
                </div>

                {/* Description */}
                <div className="space-y-2">
                  <Label className="text-base font-semibold">
                    تفاصيل الواقعة <span className="text-red-500">*</span>
                  </Label>
                  <Textarea
                    placeholder="اشرح بوضوح ما حدث، متى، وأين..."
                    className="min-h-[120px] bg-background/50 resize-none leading-relaxed"
                    {...register("description", {
                      required: "التفاصيل مطلوبة",
                    })}
                  />
                  {errors.description && (
                    <p className="text-sm text-red-500">
                      {errors.description.message}
                    </p>
                  )}
                </div>

                {/* Action Taken */}
                <div className="space-y-2">
                  <Label className="text-base font-semibold flex items-center gap-2">
                    <Gavel className="h-4 w-4" />
                    القرارات المتخذة (الجزاءات)
                  </Label>
                  <Textarea
                    placeholder="مثال: خصم يومين من الراتب، الحرمان من العلاوة..."
                    className="min-h-[80px] bg-background/50 resize-none"
                    {...register("actionTaken")}
                  />
                </div>

                <div className="flex flex-col sm:flex-row justify-end pt-6 border-t gap-4">
                  <Button
                    type="button"
                    variant="outline"
                    size="lg"
                    onClick={() => setShowPreview(true)}
                    className="gap-2"
                  >
                    <Eye className="h-4 w-4" />
                    معاينة قبل الحفظ
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    size="lg"
                    onClick={() => navigate("/hr/warnings")}
                  >
                    إلغاء
                  </Button>
                  <Button
                    type="submit"
                    disabled={loading}
                    size="lg"
                    className="bg-red-600 hover:bg-red-700 text-white min-w-[150px]"
                  >
                    {loading ? (
                      "جاري الحفظ..."
                    ) : (
                      <>
                        <Save className="h-4 w-4 ml-2" />
                        اعتماد المخالفة
                      </>
                    )}
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar Info */}
        <div className="space-y-6">
          {/* Selected Employee Card */}
          {selectedEmployee ? (
            <Card className="border-none shadow-lg bg-gradient-to-br from-muted to-background animate-in fade-in zoom-in duration-300">
              <CardHeader className="pb-2 border-b">
                <CardTitle className="text-sm uppercase tracking-wider text-muted-foreground">
                  ملف الموظف
                </CardTitle>
              </CardHeader>
              <CardContent className="flex flex-col items-center text-center p-6 space-y-4">
                <Avatar className="h-24 w-24 border-4 border-background shadow-xl">
                  <AvatarFallback className="text-2xl">
                    {selectedEmployee.firstName?.[0]}
                  </AvatarFallback>
                </Avatar>
                <div>
                  <h3 className="text-xl font-bold">
                    {selectedEmployee.firstName} {selectedEmployee.lastName}
                  </h3>
                  <p className="text-sm text-muted-foreground">
                    {selectedEmployee.position?.title || "موظف"}
                  </p>
                  {selectedEmployee.department?.name && (
                    <Badge variant="secondary" className="mt-2">
                      {selectedEmployee.department.name}
                    </Badge>
                  )}
                </div>
                <div className="w-full pt-4 border-t grid grid-cols-2 gap-2 text-sm">
                  <div className="bg-background/50 p-2 rounded">
                    <p className="text-xs text-muted-foreground">
                      الرقم الوظيفي
                    </p>
                    <p className="font-semibold">
                      {selectedEmployee.employeeNumber || "-"}
                    </p>
                  </div>
                  <div className="bg-background/50 p-2 rounded">
                    <p className="text-xs text-muted-foreground">
                      تاريخ التعيين
                    </p>
                    <p className="font-semibold">
                      {selectedEmployee.hireDate
                        ? new Date(
                          selectedEmployee.hireDate,
                        ).toLocaleDateString("ar-EG")
                        : "-"}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          ) : (
            <Card className="border-none shadow-sm bg-muted/30 border-dashed border-2">
              <CardContent className="flex flex-col items-center justify-center py-12 text-muted-foreground text-center">
                <User className="h-12 w-12 mb-3 opacity-20" />
                <p>اختر موظفاً لعرض ملفه المختصر هنا</p>
              </CardContent>
            </Card>
          )}

          {/* Guidelines Card */}
          <Card className="border-none shadow-md bg-blue-50/50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-900/20">
            <CardHeader>
              <CardTitle className="text-base text-blue-800 dark:text-blue-300 flex items-center gap-2">
                <AlertCircle className="h-4 w-4" />
                سياسة التدرج في العقوبات
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3 text-sm text-blue-700/80 dark:text-blue-400/80">
              <div className="flex gap-2 items-start">
                <div className="h-5 w-5 rounded-full bg-blue-200 dark:bg-blue-800 flex flex-shrink-0 items-center justify-center text-[10px] font-bold mt-0.5">
                  1
                </div>
                <p>
                  <span className="font-semibold">تنبيه شفهي:</span> للمخالفات
                  البسيطة الأولى (مثل التأخير البسيط).
                </p>
              </div>
              <div className="flex gap-2 items-start">
                <div className="h-5 w-5 rounded-full bg-blue-200 dark:bg-blue-800 flex flex-shrink-0 items-center justify-center text-[10px] font-bold mt-0.5">
                  2
                </div>
                <p>
                  <span className="font-semibold">إنذار كتابي:</span> عند تكرار
                  المخالفة أو للمخالفات المتوسطة.
                </p>
              </div>
              <div className="flex gap-2 items-start">
                <div className="h-5 w-5 rounded-full bg-blue-200 dark:bg-blue-800 flex flex-shrink-0 items-center justify-center text-[10px] font-bold mt-0.5">
                  3
                </div>
                <p>
                  <span className="font-semibold">فصل / إنهاء:</span> للمخالفات
                  الجسيمة جداً أو استنفاد رصيد الإنذارات.
                </p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Preview Modal */}
      <Dialog open={showPreview} onOpenChange={setShowPreview}>
        <DialogContent className="max-w-2xl bg-white dark:bg-gray-950 border-none shadow-2xl rounded-[2rem] p-0 overflow-hidden" dir="rtl">
          {/* Header with Background Pattern */}
          <div className="relative h-32 bg-gradient-to-r from-red-600 to-rose-700 flex items-center px-8 overflow-hidden">
            <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#fff_1px,transparent_1px)] [background-size:20px_20px]" />
            <div className="absolute -right-10 -top-10 w-40 h-40 bg-white/10 rounded-full blur-3xl" />

            <div className="flex items-center gap-5 relative z-10 w-full">
              <div className="p-4 bg-white/20 rounded-[1.5rem] backdrop-blur-md shadow-inner ring-1 ring-white/30">
                <ShieldAlert className="h-8 w-8 text-white" />
              </div>
              <div className="space-y-1 flex-1 min-w-0">
                <DialogTitle className="text-2xl font-black text-white break-words pr-2">
                  {watch("title") || "عنوان الإنذار"}
                </DialogTitle>
                <div className="flex items-center gap-2 text-white/70 text-xs font-bold uppercase tracking-widest">
                  <span className="bg-white/10 px-2 py-0.5 rounded-md backdrop-blur-sm">مسودة معاينة</span>
                  <span className="h-1 w-1 rounded-full bg-white/30" />
                  <span>{watch("type")}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="p-8 space-y-8 max-h-[60vh] overflow-y-auto custom-scrollbar relative">
            {selectedEmployee && (
              <div className="flex items-center gap-4 p-5 bg-muted/30 rounded-[1.5rem] border border-muted ring-4 ring-muted/20">
                <Avatar className="h-12 w-12 border-2 border-white dark:border-gray-800 shadow-md">
                  <AvatarFallback className="bg-primary text-white font-black">{selectedEmployee.firstName?.[0]}</AvatarFallback>
                </Avatar>
                <div>
                  <p className="text-sm font-black text-gray-900 dark:text-white leading-none mb-1">
                    {selectedEmployee.firstName} {selectedEmployee.lastName}
                  </p>
                  <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest leading-none">
                    {selectedEmployee.position?.title || "موظف"} • {selectedEmployee.employeeNumber}
                  </p>
                </div>
              </div>
            )}

            <div className="space-y-3">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 px-1">
                <FileText className="h-3.5 w-3.5" />
                وصف المخالفة المقترح
              </h4>
              <div className="relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-red-500/10 to-transparent rounded-3xl blur opacity-25" />
                <div className="relative bg-white dark:bg-gray-900/50 p-7 rounded-[1.5rem] border border-gray-100 dark:border-gray-800 shadow-sm leading-relaxed whitespace-pre-wrap break-words text-gray-700 dark:text-gray-200 text-lg font-medium">
                  {watch("description") || "سيتم عرض وصف المخالفة هنا..."}
                </div>
              </div>
            </div>

            {watch("actionTaken") && (
              <div className="space-y-3">
                <h4 className="text-[10px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-widest flex items-center gap-2 px-1">
                  <Gavel className="h-3.5 w-3.5" />
                  الإجراء الإداري المتخذ
                </h4>
                <div className="bg-amber-500/5 dark:bg-amber-500/10 p-6 rounded-[1.5rem] border border-amber-500/10 shadow-sm border-dashed">
                  <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap break-words text-md leading-relaxed">
                    {watch("actionTaken")}
                  </p>
                </div>
              </div>
            )}

            <div className="flex flex-wrap items-center gap-4 pt-6 border-t border-dashed border-muted font-bold text-xs text-muted-foreground">
              <div className="flex items-center gap-2 px-3 py-1.5 bg-muted/40 rounded-full">
                <Calendar className="h-3.5 w-3.5 text-primary" />
                <span>تاريخ الواقعة: {watch("incidentDate")}</span>
              </div>
              <div className="flex items-center gap-2 px-3 py-1.5 bg-primary/5 text-primary rounded-full ring-1 ring-primary/10">
                <AlertCircle className="h-3.5 w-3.5" />
                <span>درجة الشدة: {watch("severity")}</span>
              </div>
            </div>
          </div>

          <div className="p-6 bg-muted/20 border-t border-muted/30 flex justify-end">
            <Button
              onClick={() => setShowPreview(false)}
              className="rounded-xl px-10 h-12 font-black text-xs uppercase tracking-widest shadow-lg shadow-primary/20"
            >
              فهمت، العودة للتعديل
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default CreateWarning;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import {
  Users,
  Star,
  Gift,
  Trophy,
  Target,
  TrendingUp,
  Award,
  Plus,
  Search,
  Filter,
  RefreshCw,
  Eye,
  Edit,
  Crown,
  Medal,
  Gem,
  Heart,
  Zap,
  DollarSign,
} from "lucide-react";

interface CustomerLoyaltyProgram {
  id: string;
  name: string;
  nameAr?: string;
  description: string;
  type: "POINTS" | "TIER" | "CASHBACK" | "REFERRAL";
  status: "ACTIVE" | "INACTIVE" | "DRAFT";
  pointsPerPurchase: number;
  pointsPerReferral: number;
  redemptionRate: number;
  minimumPoints: number;
  maxPointsPerTransaction: number;
  expiryMonths: number;
  createdAt: string;
  updatedAt: string;
  customersCount: number;
  totalPointsIssued: number;
  totalPointsRedeemed: number;
}

interface CustomerLoyaltyTier {
  id: string;
  name: string;
  nameAr?: string;
  minPoints: number;
  maxPoints?: number;
  benefits: string[];
  color: string;
  icon: string;
  customersCount: number;
}

interface CustomerLoyaltyRecord {
  id: string;
  customer: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
  };
  program: CustomerLoyaltyProgram;
  currentPoints: number;
  totalEarned: number;
  totalRedeemed: number;
  tier?: CustomerLoyaltyTier;
  joinDate: string;
  lastActivity: string;
  status: "ACTIVE" | "INACTIVE" | "SUSPENDED";
}

interface CashbackSettings {
  id: string;
  status: "ACTIVE" | "INACTIVE" | "DRAFT" | "SUSPENDED";
  rules: {
    cashbackPercent: number;
    base: "total" | "subtotal";
    trigger: string;
    maxPerOrder?: number;
    tierOverrides?: Record<string, number>;
  };
}

const CustomerLoyalty: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<
    "programs" | "customers" | "tiers" | "analytics" | "cashback"
  >("programs");
  const [programs, setPrograms] = useState<CustomerLoyaltyProgram[]>([]);
  const [customers, setCustomers] = useState<CustomerLoyaltyRecord[]>([]);
  const [tiers, setTiers] = useState<CustomerLoyaltyTier[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [cashbackSettings, setCashbackSettings] =
    useState<CashbackSettings | null>(null);
  const [cashbackDraft, setCashbackDraft] = useState<{
    cashbackPercent: number;
    base: "total" | "subtotal";
    status: CashbackSettings["status"];
    maxPerOrder: number;
    tierOverrides: Record<string, number>;
  } | null>(null);
  const [isSavingCashback, setIsSavingCashback] = useState(false);

  const [walletStats, setWalletStats] = useState<{
    totalCashback: number;
  } | null>(null);

  useEffect(() => {
    fetchLoyaltyData();
  }, []);

  const fetchLoyaltyData = async () => {
    try {
      setIsLoading(true);
      const [programsRes, customersRes, tiersRes, cashbackRes, statsRes] =
        await Promise.all([
          apiClient.get("/hr/customer-loyalty/programs"),
          apiClient.get("/hr/customer-loyalty/customers"),
          apiClient.get("/hr/customer-loyalty/tiers"),
          apiClient.get("/hr/customer-loyalty/cashback/settings"),
          apiClient.get("/wallet/stats"),
        ]);

      setPrograms(programsRes.data.data || []);
      setCustomers(customersRes.data.data || []);
      setTiers(tiersRes.data.data || []);
      setWalletStats(statsRes.data.data || null);

      const cs: CashbackSettings | null = cashbackRes?.data?.data || null;
      setCashbackSettings(cs);
      if (cs) {
        setCashbackDraft({
          cashbackPercent: cs.rules.cashbackPercent,
          base: cs.rules.base,
          status: cs.status,
          maxPerOrder: cs.rules.maxPerOrder || 0,
          tierOverrides: cs.rules.tierOverrides || {},
        });
      } else {
        setCashbackDraft(null);
      }
    } catch (error) {
      console.error("Error fetching loyalty data:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const saveCashbackSettings = async () => {
    if (!cashbackDraft) return;

    try {
      setIsSavingCashback(true);
      const res = await apiClient.put(
        "/hr/customer-loyalty/cashback/settings",
        {
          cashbackPercent: cashbackDraft.cashbackPercent,
          base: cashbackDraft.base,
          status: cashbackDraft.status,
          maxPerOrder: cashbackDraft.maxPerOrder,
          tierOverrides: cashbackDraft.tierOverrides,
        },
      );

      const cs: CashbackSettings | null = res?.data?.data || null;
      setCashbackSettings(cs);
      if (cs) {
        setCashbackDraft({
          cashbackPercent: cs.rules.cashbackPercent,
          base: cs.rules.base,
          status: cs.status,
          maxPerOrder: cs.rules.maxPerOrder || 0,
          tierOverrides: cs.rules.tierOverrides || {},
        });
      }
    } catch (error) {
      console.error("Error saving cashback settings:", error);
    } finally {
      setIsSavingCashback(false);
    }
  };

  const getProgramIcon = (type: string) => {
    switch (type) {
      case "POINTS":
        return <Star className="w-5 h-5" />;
      case "TIER":
        return <Crown className="w-5 h-5" />;
      case "CASHBACK":
        return <DollarSign className="w-5 h-5" />;
      case "REFERRAL":
        return <Users className="w-5 h-5" />;
      default:
        return <Gift className="w-5 h-5" />;
    }
  };

  const getTierIcon = (iconName: string) => {
    switch (iconName) {
      case "crown":
        return <Crown className="w-6 h-6" />;
      case "medal":
        return <Medal className="w-6 h-6" />;
      case "gem":
        return <Gem className="w-6 h-6" />;
      case "trophy":
        return <Trophy className="w-6 h-6" />;
      default:
        return <Award className="w-6 h-6" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "ACTIVE":
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400";
      case "INACTIVE":
        return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400";
      case "DRAFT":
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400";
      case "SUSPENDED":
        return "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6 text-gray-900 dark:text-gray-100">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-pink-500 rounded-xl flex items-center justify-center">
            <Heart className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
              ولاء العملاء
            </h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              إدارة برامج ولاء العملاء ومكافآتهم
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <button
            onClick={fetchLoyaltyData}
            className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            <RefreshCw className="w-4 h-4" />
            تحديث
          </button>
          <button
            onClick={() => setShowCreateForm(true)}
            className="flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-medium"
          >
            <Plus className="w-4 h-4" />
            برنامج جديد
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-gradient-to-r from-purple-500 to-purple-600 p-4 rounded-xl text-white">
          <div className="flex items-center gap-2 text-sm opacity-80">
            <Gift className="w-4 h-4" />
            البرامج النشطة
          </div>
          <p className="text-2xl font-bold mt-1">
            {programs.filter((p) => p.status === "ACTIVE").length}
          </p>
        </div>
        <div className="bg-gradient-to-r from-blue-500 to-blue-600 p-4 rounded-xl text-white">
          <div className="flex items-center gap-2 text-sm opacity-80">
            <Users className="w-4 h-4" />
            العملاء المشتركين
          </div>
          <p className="text-2xl font-bold mt-1">
            {customers.filter((c) => c.status === "ACTIVE").length}
          </p>
        </div>
        <div className="bg-gradient-to-r from-green-500 to-green-600 p-4 rounded-xl text-white">
          <div className="flex items-center gap-2 text-sm opacity-80">
            <Star className="w-4 h-4" />
            إجمالي النقاط
          </div>
          <p className="text-2xl font-bold mt-1">
            {customers
              .reduce((sum, c) => sum + c.currentPoints, 0)
              .toLocaleString()}
          </p>
        </div>
        <div className="bg-gradient-to-r from-orange-500 to-orange-600 p-4 rounded-xl text-white">
          <div className="flex items-center gap-2 text-sm opacity-80">
            <Trophy className="w-4 h-4" />
            المستويات
          </div>
          <p className="text-2xl font-bold mt-1">{tiers.length}</p>
        </div>
      </div>

      {/* Tabs */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700">
        <div className="flex gap-2 p-2 border-b border-gray-200 dark:border-gray-700">
          {[
            { id: "programs", label: "البرامج", icon: Gift },
            { id: "customers", label: "العملاء", icon: Users },
            { id: "tiers", label: "المستويات", icon: Crown },
            { id: "analytics", label: "التحليلات", icon: TrendingUp },
            { id: "cashback", label: "الكاش باك", icon: DollarSign },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${
                activeTab === tab.id
                  ? "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400"
                  : "text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-gray-200"
              }`}
            >
              <tab.icon className="w-4 h-4" />
              {tab.label}
            </button>
          ))}
        </div>

        <div className="p-6">
          {/* Programs Tab */}
          {activeTab === "programs" && (
            <div className="space-y-4">
              {programs.length === 0 ? (
                <div className="text-center py-12">
                  <Gift className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                    لا توجد برامج ولاء
                  </h3>
                  <p className="text-gray-500 dark:text-gray-400 mb-4">
                    ابدأ بإنشاء برنامج ولاء للعملاء
                  </p>
                  <button
                    onClick={() => setShowCreateForm(true)}
                    className="px-4 py-2 bg-purple-600 text-white rounded-lg font-medium hover:bg-purple-700"
                  >
                    إنشاء برنامج جديد
                  </button>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {programs.map((program) => (
                    <div
                      key={program.id}
                      className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6 border border-gray-200 dark:border-gray-600"
                    >
                      <div className="flex items-start justify-between mb-4">
                        <div
                          className={`p-2 ${program.status === "ACTIVE" ? "bg-purple-100 text-purple-600 dark:bg-purple-900/30" : "bg-gray-100 text-gray-600 dark:bg-gray-800"} rounded-lg`}
                        >
                          {getProgramIcon(program.type)}
                        </div>
                        <span
                          className={`text-xs px-2 py-1 rounded-full font-medium ${getStatusColor(program.status)}`}
                        >
                          {program.status === "ACTIVE"
                            ? "نشط"
                            : program.status === "INACTIVE"
                              ? "غير نشط"
                              : program.status === "DRAFT"
                                ? "مسودة"
                                : "معلق"}
                        </span>
                      </div>
                      <h3 className="font-bold text-lg text-gray-900 dark:text-white mb-2">
                        {program.nameAr || program.name}
                      </h3>
                      <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
                        {program.description}
                      </p>
                      <div className="space-y-2 text-sm">
                        <div className="flex justify-between">
                          <span className="text-gray-500 dark:text-gray-400">
                            نقاط لكل عملية:
                          </span>
                          <span className="font-medium text-gray-900 dark:text-white">
                            {program.pointsPerPurchase}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gray-500 dark:text-gray-400">
                            العملاء:
                          </span>
                          <span className="font-medium text-gray-900 dark:text-white">
                            {program.customersCount}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gray-500 dark:text-gray-400">
                            معدل الاستبدال:
                          </span>
                          <span className="font-medium text-gray-900 dark:text-white">
                            {program.redemptionRate}
                          </span>
                        </div>
                      </div>
                      <div className="flex gap-2 mt-4">
                        <button className="flex-1 px-3 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700">
                          تعديل
                        </button>
                        <button className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700">
                          عرض
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Customers Tab */}
          {activeTab === "customers" && (
            <div className="space-y-4">
              <div className="flex items-center gap-4 mb-4">
                <div className="flex-1 relative">
                  <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <input
                    type="text"
                    placeholder="البحث عن عميل..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pr-10 pl-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>
                <button className="flex items-center gap-2 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700">
                  <Filter className="w-4 h-4" />
                  فلترة
                </button>
              </div>

              {customers.length === 0 ? (
                <div className="text-center py-12">
                  <Users className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                    لا يوجد عملاء مشتركون
                  </h3>
                  <p className="text-gray-500 dark:text-gray-400">
                    سيظهر هنا العملاء المشتركون في برامج الولاء
                  </p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                    <thead className="bg-gray-50 dark:bg-gray-800">
                      <tr>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                          العميل
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                          البرنامج
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                          النقاط الحالية
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                          المستوى
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                          الحالة
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                          آخر نشاط
                        </th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                          إجراءات
                        </th>
                      </tr>
                    </thead>
                    <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                      {customers.map((customer) => (
                        <tr
                          key={customer.id}
                          className="hover:bg-gray-50 dark:hover:bg-gray-700"
                        >
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div>
                              <div className="font-medium text-gray-900 dark:text-white">
                                {customer.customer.firstName}{" "}
                                {customer.customer.lastName}
                              </div>
                              <div className="text-sm text-gray-500 dark:text-gray-400">
                                {customer.customer.email}
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center gap-2">
                              {getProgramIcon(customer.program.type)}
                              <span className="text-sm text-gray-900 dark:text-white">
                                {customer.program.nameAr ||
                                  customer.program.name}
                              </span>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center gap-1">
                              <Star className="w-4 h-4 text-yellow-500" />
                              <span className="font-medium text-gray-900 dark:text-white">
                                {customer.currentPoints.toLocaleString()}
                              </span>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            {customer.tier && (
                              <div className="flex items-center gap-2">
                                {getTierIcon(customer.tier.icon)}
                                <span className="text-sm font-medium text-gray-900 dark:text-white">
                                  {customer.tier.nameAr || customer.tier.name}
                                </span>
                              </div>
                            )}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span
                              className={`text-xs px-2 py-1 rounded-full font-medium ${getStatusColor(customer.status)}`}
                            >
                              {customer.status === "ACTIVE"
                                ? "نشط"
                                : customer.status === "INACTIVE"
                                  ? "غير نشط"
                                  : "معلق"}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                            {new Date(customer.lastActivity).toLocaleDateString(
                              "ar-EG",
                            )}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm">
                            <div className="flex gap-2">
                              <button className="text-purple-600 hover:text-purple-800 dark:text-purple-400 dark:hover:text-purple-300">
                                <Eye className="w-4 h-4" />
                              </button>
                              <button className="text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300">
                                <Edit className="w-4 h-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {/* Tiers Tab */}
          {activeTab === "tiers" && (
            <div className="space-y-4">
              {tiers.length === 0 ? (
                <div className="text-center py-12">
                  <Crown className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                    لا توجد مستويات
                  </h3>
                  <p className="text-gray-500 dark:text-gray-400 mb-4">
                    أنشئ مستويات لبرامج الولاء
                  </p>
                  <button className="px-4 py-2 bg-purple-600 text-white rounded-lg font-medium hover:bg-purple-700">
                    إنشاء مستوى جديد
                  </button>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {tiers.map((tier) => (
                    <div
                      key={tier.id}
                      className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6 border border-gray-200 dark:border-gray-600"
                    >
                      <div className="flex items-center gap-3 mb-4">
                        <div
                          className={`p-3 rounded-lg`}
                          style={{
                            backgroundColor: tier.color + "20",
                            color: tier.color,
                          }}
                        >
                          {getTierIcon(tier.icon)}
                        </div>
                        <div>
                          <h3 className="font-bold text-lg text-gray-900 dark:text-white">
                            {tier.nameAr || tier.name}
                          </h3>
                          <p className="text-sm text-gray-500 dark:text-gray-400">
                            {tier.customersCount} عميل
                          </p>
                        </div>
                      </div>
                      <div className="space-y-2 mb-4">
                        <div className="flex justify-between text-sm">
                          <span className="text-gray-500 dark:text-gray-400">
                            النقاط الدنيا:
                          </span>
                          <span className="font-medium text-gray-900 dark:text-white">
                            {tier.minPoints.toLocaleString()}
                          </span>
                        </div>
                        {tier.maxPoints && (
                          <div className="flex justify-between text-sm">
                            <span className="text-gray-500 dark:text-gray-400">
                              النقاط القصوى:
                            </span>
                            <span className="font-medium text-gray-900 dark:text-white">
                              {tier.maxPoints.toLocaleString()}
                            </span>
                          </div>
                        )}
                      </div>
                      <div className="space-y-1">
                        <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                          المزايا:
                        </p>
                        {tier.benefits.map((benefit, index) => (
                          <div
                            key={index}
                            className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400"
                          >
                            <Zap className="w-3 h-3 text-yellow-500" />
                            {benefit}
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Analytics Tab */}
          {activeTab === "analytics" && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6">
                  <div className="flex items-center gap-2 mb-2">
                    <TrendingUp className="w-5 h-5 text-green-600" />
                    <span className="text-sm text-gray-500 dark:text-gray-400">
                      معدل النمو
                    </span>
                  </div>
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    +24%
                  </p>
                  <p className="text-xs text-green-600 mt-1">من الشهر الماضي</p>
                </div>
                <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6">
                  <div className="flex items-center gap-2 mb-2">
                    <Star className="w-5 h-5 text-yellow-500" />
                    <span className="text-sm text-gray-500 dark:text-gray-400">
                      متوسط النقاط
                    </span>
                  </div>
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    1,250
                  </p>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    لكل عميل
                  </p>
                </div>
                <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6">
                  <div className="flex items-center gap-2 mb-2">
                    <Target className="w-5 h-5 text-blue-600" />
                    <span className="text-sm text-gray-500 dark:text-gray-400">
                      معدل الاستبدال
                    </span>
                  </div>
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    68%
                  </p>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    من النقاط المكتسبة
                  </p>
                </div>
                <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6">
                  <div className="flex items-center gap-2 mb-2">
                    <Award className="w-5 h-5 text-purple-600" />
                    <span className="text-sm text-gray-500 dark:text-gray-400">
                      قيمة المكافآت
                    </span>
                  </div>
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    ₪45,200
                  </p>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    هذا الشهر
                  </p>
                </div>

                <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6">
                  <div className="flex items-center gap-2 mb-2">
                    <DollarSign className="w-5 h-5 text-pink-600" />
                    <span className="text-sm text-gray-500 dark:text-gray-400">
                      إجمالي الكاش باك
                    </span>
                  </div>
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    {walletStats?.totalCashback
                      ? walletStats.totalCashback.toLocaleString()
                      : "0"}{" "}
                    ج.م
                  </p>
                  <p className="text-xs text-pink-600 mt-1">مدفوعات فعلية</p>
                </div>
              </div>

              <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6">
                <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
                  أداء البرامج
                </h3>
                <div className="space-y-4">
                  {programs.map((program) => (
                    <div
                      key={program.id}
                      className="flex items-center justify-between p-4 bg-white dark:bg-gray-800 rounded-lg"
                    >
                      <div className="flex items-center gap-3">
                        {getProgramIcon(program.type)}
                        <div>
                          <p className="font-medium text-gray-900 dark:text-white">
                            {program.nameAr || program.name}
                          </p>
                          <p className="text-sm text-gray-500 dark:text-gray-400">
                            {program.customersCount} عميل
                          </p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-medium text-gray-900 dark:text-white">
                          {program.totalPointsIssued.toLocaleString()} نقطة
                        </p>
                        <p className="text-sm text-gray-500 dark:text-gray-400">
                          {program.totalPointsRedeemed.toLocaleString()} مستبدلة
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === "cashback" && (
            <div className="space-y-4">
              <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-6 border border-gray-200 dark:border-gray-600">
                <div className="flex items-center justify-between gap-4 mb-4">
                  <div>
                    <h3 className="text-lg font-bold text-gray-900 dark:text-white">
                      إعدادات الكاش باك
                    </h3>
                    <p className="text-sm text-gray-500 dark:text-gray-400">
                      تحديد نسبة الكاش باك وطريقة الحساب
                    </p>
                  </div>
                  <button
                    onClick={saveCashbackSettings}
                    disabled={!cashbackDraft || isSavingCashback}
                    className={`px-4 py-2 rounded-lg font-medium ${
                      !cashbackDraft || isSavingCashback
                        ? "bg-gray-300 text-gray-600 dark:bg-gray-600 dark:text-gray-300"
                        : "bg-purple-600 hover:bg-purple-700 text-white"
                    }`}
                  >
                    {isSavingCashback ? "جارٍ الحفظ..." : "حفظ"}
                  </button>
                </div>

                {!cashbackDraft ? (
                  <div className="text-sm text-gray-600 dark:text-gray-300">
                    تعذر تحميل إعدادات الكاش باك.
                  </div>
                ) : (
                  <div className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          نسبة الكاش باك (%)
                        </label>
                        <input
                          type="number"
                          min={0}
                          max={100}
                          step={0.01}
                          value={cashbackDraft.cashbackPercent}
                          onChange={(e) =>
                            setCashbackDraft({
                              ...cashbackDraft,
                              cashbackPercent: Number(e.target.value),
                            })
                          }
                          className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          الحد الأقصى للطلب (0 = بدون حد)
                        </label>
                        <input
                          type="number"
                          min={0}
                          step={1}
                          value={cashbackDraft.maxPerOrder}
                          onChange={(e) =>
                            setCashbackDraft({
                              ...cashbackDraft,
                              maxPerOrder: Number(e.target.value),
                            })
                          }
                          className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                          placeholder="مثلاً: 250"
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          أساس الحساب
                        </label>
                        <select
                          value={cashbackDraft.base}
                          onChange={(e) =>
                            setCashbackDraft({
                              ...cashbackDraft,
                              base:
                                e.target.value === "subtotal"
                                  ? "subtotal"
                                  : "total",
                            })
                          }
                          className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        >
                          <option value="total">إجمالي الطلب (total)</option>
                          <option value="subtotal">
                            قبل الشحن والضريبة (subtotal)
                          </option>
                        </select>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          الحالة
                        </label>
                        <select
                          value={cashbackDraft.status}
                          onChange={(e) =>
                            setCashbackDraft({
                              ...cashbackDraft,
                              status: e.target
                                .value as CashbackSettings["status"],
                            })
                          }
                          className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        >
                          <option value="ACTIVE">نشط</option>
                          <option value="INACTIVE">غير نشط</option>
                          <option value="DRAFT">مسودة</option>
                          <option value="SUSPENDED">معلق</option>
                        </select>
                      </div>
                    </div>

                    <div className="border-t border-gray-200 dark:border-gray-600 pt-6">
                      <h4 className="text-base font-bold text-gray-900 dark:text-white mb-2">
                        تخصيص الشرائح (Override Tiers)
                      </h4>
                      <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                        يمكنك تحديد نسبة كاش باك مختلفة لكل مستوى عملاء. اترك
                        الحقل فارغاً لاستخدام النسبة الافتراضية.
                      </p>

                      {tiers.length === 0 ? (
                        <div className="text-gray-500 text-sm italic">
                          لا توجد مستويات معرفة.
                        </div>
                      ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {tiers.map((tier) => (
                            <div
                              key={tier.id}
                              className="flex items-center gap-3 p-3 bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700"
                            >
                              <div
                                className={`p-2 rounded-lg`}
                                style={{
                                  backgroundColor: tier.color + "20",
                                  color: tier.color,
                                }}
                              >
                                {getTierIcon(tier.icon)}
                              </div>
                              <div className="flex-1">
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                                  {tier.nameAr || tier.name}
                                </label>
                                <input
                                  type="number"
                                  min={0}
                                  max={100}
                                  step={0.01}
                                  placeholder={`الافتراضي (${cashbackDraft.cashbackPercent}%)`}
                                  value={
                                    cashbackDraft.tierOverrides?.[tier.id] ?? ""
                                  }
                                  onChange={(e) => {
                                    const val = e.target.value;
                                    const newOverrides = {
                                      ...cashbackDraft.tierOverrides,
                                    };
                                    if (val === "") {
                                      delete newOverrides[tier.id];
                                    } else {
                                      newOverrides[tier.id] = Number(val);
                                    }
                                    setCashbackDraft({
                                      ...cashbackDraft,
                                      tierOverrides: newOverrides,
                                    });
                                  }}
                                  className="mt-1 w-full px-2 py-1 text-sm border border-gray-300 dark:border-gray-600 rounded-md bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white"
                                />
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {cashbackSettings && (
                  <div className="mt-4 text-xs text-gray-500 dark:text-gray-400">
                    Program ID: {cashbackSettings.id}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CustomerLoyalty;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import {
  FileText,
  ArrowRight,
  CheckCircle,
  XCircle,
  Calendar,
  User,
  AlertCircle,
} from "lucide-react";
import { toast } from "sonner";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Textarea } from "../../components/ui/textarea";
import { Label } from "../../components/ui/label";
import { Badge } from "../../components/ui/badge";
import { Separator } from "../../components/ui/separator";

const DecisionResignation = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const isApprove = location.pathname.endsWith("/approve");

  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [resignation, setResignation] = useState<any>(null);
  const [notes, setNotes] = useState("");

  useEffect(() => {
    fetchResignation();
  }, [id]);

  const fetchResignation = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/hr/resignations/${id}`);
      setResignation(response.data.resignation);
    } catch (error) {
      console.error("Error fetching resignation:", error);
      toast.error("فشل في تحميل بيانات الاستقالة");
      navigate("/hr/resignations");
    } finally {
      setLoading(false);
    }
  };

  const handleDecision = async (status: "APPROVED" | "REJECTED") => {
    try {
      setSubmitting(true);
      await api.put(`/hr/resignations/${id}`, {
        status,
        reason: status === "REJECTED" ? notes : resignation.reason,
        exitInterview: isApprove ? notes : resignation.exitInterview,
      });

      toast.success(
        status === "APPROVED"
          ? "تمت الموافقة على الاستقالة بنجاح"
          : "تم رفض الاستقالة",
      );
      navigate("/hr/resignations");
    } catch (error: any) {
      console.error("Error updating resignation:", error);
      toast.error(error.response?.data?.error || "حدث خطأ أثناء معالجة الطلب");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading)
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );

  if (!resignation)
    return (
      <div className="p-8 text-center text-destructive">
        الاستقالة غير موجودة
      </div>
    );

  return (
    <div className="p-6 w-full max-w-4xl mx-auto space-y-6" dir="rtl">
      <div className="flex items-center gap-4">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => navigate("/hr/resignations")}
        >
          <ArrowRight className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2">
            {isApprove ? (
              <CheckCircle className="h-8 w-8 text-green-600 dark:text-green-500" />
            ) : (
              <XCircle className="h-8 w-8 text-red-600 dark:text-red-500" />
            )}
            {isApprove ? "الموافقة على الاستقالة" : "رفض الاستقالة"}
          </h1>
          <p className="text-muted-foreground mt-1">
            مراجعة تفاصيل طلب الاستقالة المقدم من الموظف
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Employee Info */}
        <Card className="md:col-span-1">
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <User className="h-5 w-5 text-muted-foreground" />
              بيانات الموظف
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex flex-col items-center py-4 bg-muted rounded-lg">
              <div className="h-20 w-20 bg-primary/10 rounded-full flex items-center justify-center mb-3">
                <User className="h-10 w-10 text-primary" />
              </div>
              <h3 className="font-bold text-lg">
                {resignation.employee?.firstName}{" "}
                {resignation.employee?.lastName}
              </h3>
              <p className="text-sm text-muted-foreground">
                {resignation.employee?.employeeNumber}
              </p>
            </div>

            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-muted-foreground">القسم:</span>
                <span className="font-medium">
                  {resignation.employee?.department?.name || "غير محدد"}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">المسمى الوظيفي:</span>
                <span className="font-medium">
                  {resignation.employee?.position?.title || "غير محدد"}
                </span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Resignation Details */}
        <Card className="md:col-span-2">
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <FileText className="h-5 w-5 text-muted-foreground" />
              تفاصيل الاستقالة
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <Label className="text-muted-foreground">
                  تاريخ تقديم الاستقالة
                </Label>
                <div className="flex items-center gap-2 font-medium">
                  <Calendar className="h-4 w-4 text-primary" />
                  {new Date(resignation.resignationDate).toLocaleDateString(
                    "ar-EG",
                  )}
                </div>
              </div>
              <div className="space-y-1">
                <Label className="text-muted-foreground">آخر يوم عمل</Label>
                <div className="flex items-center gap-2 font-medium">
                  <Calendar className="h-4 w-4 text-destructive" />
                  {new Date(resignation.lastWorkingDay).toLocaleDateString(
                    "ar-EG",
                  )}
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <Label className="text-muted-foreground">فترة الإشعار</Label>
              <div className="flex items-center gap-2">
                <Badge variant="outline" className="text-sm">
                  {resignation.noticePeriodDays} يوم
                </Badge>
                <p className="text-xs text-muted-foreground">
                  التاريخ المتوقع:{" "}
                  {new Date(resignation.expectedLastDay).toLocaleDateString(
                    "ar-EG",
                  )}
                </p>
              </div>
            </div>

            <Separator />

            <div className="space-y-2">
              <Label className="text-muted-foreground">سبب الاستقالة</Label>
              <div className="p-3 bg-muted rounded-lg text-sm italic">
                "{resignation.reason || "لا يوجد سبب مذكور"}"
              </div>
            </div>

            {/* Admin Decision Note */}
            <div className="space-y-4 pt-4 border-t">
              <div className="space-y-2">
                <Label htmlFor="notes">
                  {isApprove
                    ? "ملاحظات الموافقة (Exit Interview Notes)"
                    : "سبب الرفض"}
                </Label>
                <Textarea
                  id="notes"
                  placeholder={
                    isApprove
                      ? "أضف ملاحظات مقابلة الخروج هنا..."
                      : "يرجى ذكر سبب الرفض..."
                  }
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="min-h-[120px]"
                />
                {isApprove && (
                  <p className="text-xs text-blue-600 dark:text-blue-400 flex items-center gap-1">
                    <AlertCircle className="h-3 w-3" />
                    سيتم تفعيل قائمة إخلاء الطرف تلقائياً بعد الموافقة.
                  </p>
                )}
              </div>

              <div className="flex gap-4">
                {isApprove ? (
                  <Button
                    className="flex-1 bg-green-600 hover:bg-green-700 dark:bg-green-700 dark:hover:bg-green-800"
                    onClick={() => handleDecision("APPROVED")}
                    disabled={submitting}
                  >
                    <CheckCircle className="h-4 w-4 ml-2" />
                    تأكيد الموافقة
                  </Button>
                ) : (
                  <Button
                    className="flex-1 bg-red-600 hover:bg-red-700 dark:bg-red-700 dark:hover:bg-red-800"
                    onClick={() => handleDecision("REJECTED")}
                    disabled={submitting || !notes.trim()}
                  >
                    <XCircle className="h-4 w-4 ml-2" />
                    تأكيد الرفض
                  </Button>
                )}
                <Button
                  variant="outline"
                  className="flex-1"
                  onClick={() => navigate("/hr/resignations")}
                  disabled={submitting}
                >
                  إلغاء الرجوع
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default DecisionResignation;

import React, { useState, useEffect } from "react";
import {
  DollarSign,
  Plus,
  Search,
  Eye,
  Trash2,
  Check,
  X,
  Clock,
  AlertCircle,
  TrendingDown,
  CheckCircle,
  Loader2,
  Edit2,
} from "lucide-react";
import api from "../../services/api";

interface Deduction {
  id: string;
  employeeId: string;
  type: string;
  category?: string;
  amount: number;
  reason: string;
  description?: string;
  date: string;
  effectiveMonth: number;
  effectiveYear: number;
  status: string;
  approvedBy?: string;
  approvedAt?: string;
  rejectedBy?: string;
  rejectedAt?: string;
  rejectionReason?: string;
  appliedToPayroll: boolean;
  payrollId?: string;
  notes?: string;
  createdAt: string;
  employee?: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
    employeeNumber?: string;
  };
}

const DEDUCTION_TYPES = {
  PENALTY: "غرامة",
  VIOLATION: "مخالفة",
  DAMAGE: "تعويض عن ضرر",
  INSURANCE: "تأمين",
  LOAN_REPAYMENT: "سداد قرض",
  ADVANCE_REPAYMENT: "سداد سلفة",
  TAX: "ضريبة",
  SOCIAL_INSURANCE: "تأمينات اجتماعية",
  ABSENCE: "غياب",
  LATE: "تأخير",
  EARLY_LEAVE: "خروج مبكر",
  OTHER: "أخرى",
};

const DEDUCTION_STATUS = {
  PENDING: {
    label: "في الانتظار",
    color:
      "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400",
  },
  APPROVED: {
    label: "موافق عليه",
    color:
      "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400",
  },
  REJECTED: {
    label: "مرفوض",
    color: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400",
  },
  APPLIED: {
    label: "تم التطبيق",
    color: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
  },
  CANCELLED: {
    label: "ملغي",
    color: "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300",
  },
};

const Deductions: React.FC = () => {
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [filteredDeductions, setFilteredDeductions] = useState<Deduction[]>([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<any>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [selectedDeduction, setSelectedDeduction] = useState<Deduction | null>(
    null,
  );
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState("");
  const [filterType, setFilterType] = useState("");
  const [filterMonth, setFilterMonth] = useState("");
  const [filterYear, setFilterYear] = useState("");
  const [employees, setEmployees] = useState<any[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [createForm, setCreateForm] = useState({
    employeeId: "",
    type: "OTHER",
    category: "",
    amount: "",
    reason: "",
    description: "",
    date: new Date().toISOString().split("T")[0],
    effectiveMonth: new Date().getMonth() + 1,
    effectiveYear: new Date().getFullYear(),
    notes: "",
  });

  useEffect(() => {
    loadData();
    loadEmployees();
  }, []);

  useEffect(() => {
    filterDeductions();
  }, [
    deductions,
    searchTerm,
    filterStatus,
    filterType,
    filterMonth,
    filterYear,
  ]);

  const loadData = async () => {
    try {
      setLoading(true);
      const [deductionsRes, statsRes] = await Promise.all([
        api.get("/hr/deductions"),
        api.get("/hr/deductions/stats"),
      ]);

      if (deductionsRes.data.success) {
        setDeductions(deductionsRes.data.deductions);
      }

      if (statsRes.data.success) {
        setStats(statsRes.data.stats);
      }
    } catch (error: any) {
      console.error("❌ Error loading deductions:", error);
      const errorMsg =
        error.response?.data?.error ||
        error.message ||
        "حدث خطأ أثناء جلب الخصومات";
      const details = error.response?.data?.details || "";
      alert(`${errorMsg}\n${details ? `التفاصيل: ${details}` : ""}`);
    } finally {
      setLoading(false);
    }
  };

  const loadEmployees = async () => {
    try {
      const response = await api.get("/hr/employees");
      if (response.data.success) {
        setEmployees(response.data.employees || []);
      }
    } catch (error) {
      console.error("Error loading employees:", error);
    }
  };

  const filterDeductions = () => {
    let filtered = [...deductions];

    if (searchTerm) {
      filtered = filtered.filter(
        (d) =>
          d.employee?.firstName
            ?.toLowerCase()
            .includes(searchTerm.toLowerCase()) ||
          d.employee?.lastName
            ?.toLowerCase()
            .includes(searchTerm.toLowerCase()) ||
          d.employee?.employeeNumber
            ?.toLowerCase()
            .includes(searchTerm.toLowerCase()) ||
          d.reason.toLowerCase().includes(searchTerm.toLowerCase()),
      );
    }

    if (filterStatus) {
      filtered = filtered.filter((d) => d.status === filterStatus);
    }

    if (filterType) {
      filtered = filtered.filter((d) => d.type === filterType);
    }

    if (filterMonth && filterYear) {
      filtered = filtered.filter(
        (d) =>
          d.effectiveMonth === parseInt(filterMonth) &&
          d.effectiveYear === parseInt(filterYear),
      );
    }

    setFilteredDeductions(filtered);
  };

  const handleCreateDeduction = async () => {
    try {
      // Client-side validation
      if (!createForm.employeeId) {
        alert("يرجى اختيار موظف");
        return;
      }

      if (!createForm.amount || parseFloat(createForm.amount) <= 0) {
        alert("يرجى إدخال مبلغ صحيح أكبر من صفر");
        return;
      }

      if (!createForm.reason || createForm.reason.trim().length < 5) {
        alert("يرجى إدخال سبب الخصم (5 أحرف على الأقل)");
        return;
      }

      console.log("📤 Sending deduction data:", createForm);

      let response;
      if (isEditing && editingId) {
        response = await api.put(`/hr/deductions/${editingId}`, createForm);
      } else {
        response = await api.post("/hr/deductions", createForm);
      }

      if (response.data.success) {
        alert(isEditing ? "تم تحديث الخصم بنجاح" : "تم إنشاء الخصم بنجاح");
        setShowCreateModal(false);
        resetCreateForm();
        loadData();
      }
    } catch (error: any) {
      console.error("Error saving deduction:", error);
      console.error("Error response:", error.response?.data);

      let errorMessage =
        error.response?.data?.error || `حدث خطأ أثناء ${isEditing ? "تحديث" : "إنشاء"} الخصم`;

      if (
        error.response?.data?.errors &&
        Array.isArray(error.response.data.errors)
      ) {
        const validationErrors = error.response.data.errors
          .map((err: any) => `${err.field}: ${err.message}`)
          .join("\n");
        errorMessage += "\n\nأخطاء التحقق:\n" + validationErrors;
      }

      alert(errorMessage);
    }
  };

  const handleEdit = (deduction: Deduction) => {
    setEditingId(deduction.id);
    setIsEditing(true);
    setCreateForm({
      employeeId: deduction.employeeId,
      type: deduction.type,
      category: deduction.category || "",
      amount: deduction.amount.toString(),
      reason: deduction.reason,
      description: deduction.description || "",
      date: deduction.date.split("T")[0],
      effectiveMonth: deduction.effectiveMonth,
      effectiveYear: deduction.effectiveYear,
      notes: deduction.notes || "",
    });
    setShowCreateModal(true);
  };

  const handleApprove = async (id: string) => {
    if (!confirm("هل أنت متأكد من الموافقة على هذا الخصم؟")) return;

    try {
      const response = await api.post(`/hr/deductions/${id}/approve`);
      if (response.data.success) {
        alert("تمت الموافقة على الخصم بنجاح");
        loadData();
      }
    } catch (error: any) {
      console.error("Error approving deduction:", error);
      alert(error.response?.data?.error || "حدث خطأ أثناء الموافقة");
    }
  };

  const handleReject = async (id: string) => {
    const reason = prompt("أدخل سبب الرفض:");
    if (!reason) return;

    try {
      const response = await api.post(`/hr/deductions/${id}/reject`, {
        reason,
      });
      if (response.data.success) {
        alert("تم رفض الخصم بنجاح");
        loadData();
      }
    } catch (error: any) {
      console.error("Error rejecting deduction:", error);
      alert(error.response?.data?.error || "حدث خطأ أثناء الرفض");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا الخصم؟")) return;

    try {
      const response = await api.delete(`/hr/deductions/${id}`);
      if (response.data.success) {
        alert("تم حذف الخصم بنجاح");
        loadData();
      }
    } catch (error: any) {
      console.error("Error deleting deduction:", error);
      alert(error.response?.data?.error || "حدث خطأ أثناء الحذف");
    }
  };

  const resetCreateForm = () => {
    setCreateForm({
      employeeId: "",
      type: "OTHER",
      category: "",
      amount: "",
      reason: "",
      description: "",
      date: new Date().toISOString().split("T")[0],
      effectiveMonth: new Date().getMonth() + 1,
      effectiveYear: new Date().getFullYear(),
      notes: "",
    });
    setIsEditing(false);
    setEditingId(null);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
    }).format(amount);
  };

  const formatDateWithDay = (dateString?: string) => {
    if (!dateString) return "-";

    const parsedDate = new Date(dateString);
    if (Number.isNaN(parsedDate.getTime())) return dateString;

    const datePart = parsedDate.toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    const dayPart = parsedDate.toLocaleDateString("ar-EG", {
      weekday: "long",
    });

    return `${datePart} - ${dayPart}`;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center">
            <DollarSign className="h-8 w-8 text-blue-600 dark:text-blue-400 ml-3" />
            إدارة الخصومات
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            إدارة الخصومات اليدوية للموظفين
          </p>
        </div>
        <button
          onClick={() => {
            setIsEditing(false);
            setEditingId(null);
            resetCreateForm();
            setShowCreateModal(true);
          }}
          className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 flex items-center"
        >
          <Plus className="h-5 w-5 ml-2" />
          إضافة خصم جديد
        </button>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  إجمالي الخصومات
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {stats.total}
                </p>
              </div>
              <TrendingDown className="h-8 w-8 text-blue-600" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  إجمالي المبلغ
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {formatCurrency(parseFloat(stats.totalAmount))}
                </p>
              </div>
              <DollarSign className="h-8 w-8 text-green-600" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  في الانتظار
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {stats.byStatus.find((s: any) => s.status === "PENDING")
                    ?._count || 0}
                </p>
              </div>
              <Clock className="h-8 w-8 text-yellow-600" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  موافق عليها
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {stats.byStatus.find((s: any) => s.status === "APPROVED")
                    ?._count || 0}
                </p>
              </div>
              <CheckCircle className="h-8 w-8 text-green-600" />
            </div>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              بحث
            </label>
            <div className="relative">
              <Search className="absolute right-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="ابحث عن موظف أو سبب..."
                className="w-full pr-10 border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              الحالة
            </label>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">الكل</option>
              <option value="PENDING">في الانتظار</option>
              <option value="APPROVED">موافق عليه</option>
              <option value="REJECTED">مرفوض</option>
              <option value="APPLIED">تم التطبيق</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              النوع
            </label>
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">الكل</option>
              {Object.entries(DEDUCTION_TYPES).map(([key, value]) => (
                <option key={key} value={key}>
                  {value}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              الشهر
            </label>
            <select
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">الكل</option>
              {Array.from({ length: 12 }, (_, i) => i + 1).map((month) => (
                <option key={month} value={month}>
                  {month}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              السنة
            </label>
            <select
              value={filterYear}
              onChange={(e) => setFilterYear(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">الكل</option>
              {Array.from(
                { length: 5 },
                (_, i) => new Date().getFullYear() - i,
              ).map((year) => (
                <option key={year} value={year}>
                  {year}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Deductions Table */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
            <thead className="bg-gray-50 dark:bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                  الموظف
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                  النوع
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                  المبلغ
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                  السبب
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                  التاريخ الفعلي
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                  الحالة
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                  إجراءات
                </th>
              </tr>
            </thead>
            <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
              {filteredDeductions.length === 0 ? (
                <tr>
                  <td
                    colSpan={7}
                    className="px-6 py-12 text-center text-gray-500 dark:text-gray-400"
                  >
                    <AlertCircle className="mx-auto h-12 w-12 mb-4" />
                    <p>لا توجد خصومات</p>
                  </td>
                </tr>
              ) : (
                filteredDeductions.map((deduction) => (
                  <tr
                    key={deduction.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-700"
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div>
                        <div className="text-sm font-medium text-gray-900 dark:text-white">
                          {deduction.employee?.firstName}{" "}
                          {deduction.employee?.lastName}
                        </div>
                        <div className="text-sm text-gray-500 dark:text-gray-400">
                          {deduction.employee?.employeeNumber}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm text-gray-900 dark:text-white">
                        {
                          DEDUCTION_TYPES[
                          deduction.type as keyof typeof DEDUCTION_TYPES
                          ]
                        }
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm font-medium text-gray-900 dark:text-white">
                        {formatCurrency(deduction.amount)}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-sm text-gray-900 dark:text-white line-clamp-2">
                        {deduction.reason}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm text-gray-900 dark:text-white">
                        {formatDateWithDay(deduction.date)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-medium ${DEDUCTION_STATUS[deduction.status as keyof typeof DEDUCTION_STATUS]?.color}`}
                      >
                        {
                          DEDUCTION_STATUS[
                            deduction.status as keyof typeof DEDUCTION_STATUS
                          ]?.label
                        }
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">
                      <div className="flex items-center space-x-2 space-x-reverse">
                        <button
                          onClick={() => {
                            setSelectedDeduction(deduction);
                            setShowDetailsModal(true);
                          }}
                          className="text-blue-600 hover:text-blue-800 dark:text-blue-400"
                          title="عرض التفاصيل"
                        >
                          <Eye className="h-5 w-5" />
                        </button>

                        {deduction.status === "PENDING" && (
                          <button
                            onClick={() => handleEdit(deduction)}
                            className="text-yellow-600 hover:text-yellow-800 dark:text-yellow-400"
                            title="تعديل"
                          >
                            <Edit2 className="h-5 w-5" />
                          </button>
                        )}

                        {!deduction.appliedToPayroll && (
                          <button
                            onClick={() => handleDelete(deduction.id)}
                            className="text-red-600 hover:text-red-800 dark:text-red-400"
                            title="حذف"
                          >
                            <Trash2 className="h-5 w-5" />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Create Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 dark:bg-gray-900 dark:bg-opacity-75 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border border-gray-200 dark:border-gray-700 w-full max-w-2xl shadow-lg rounded-md bg-white dark:bg-gray-800">
            <div className="mt-3">
              <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">
                {isEditing ? "تعديل الخصم" : "إضافة خصم جديد"}
              </h3>

              <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      الموظف *
                    </label>
                    <select
                      value={createForm.employeeId}
                      onChange={(e) =>
                        setCreateForm({
                          ...createForm,
                          employeeId: e.target.value,
                        })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      required
                    >
                      <option value="">اختر موظف</option>
                      {employees.map((emp) => (
                        <option key={emp.id} value={emp.id}>
                          {emp.firstName} {emp.lastName} - {emp.employeeNumber}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      النوع *
                    </label>
                    <select
                      value={createForm.type}
                      onChange={(e) =>
                        setCreateForm({ ...createForm, type: e.target.value })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    >
                      {Object.entries(DEDUCTION_TYPES).map(([key, value]) => (
                        <option key={key} value={key}>
                          {value}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      المبلغ *
                    </label>
                    <input
                      type="number"
                      value={createForm.amount}
                      onChange={(e) =>
                        setCreateForm({ ...createForm, amount: e.target.value })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      placeholder="0.00"
                      required
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      التصنيف الفرعي
                    </label>
                    <input
                      type="text"
                      value={createForm.category}
                      onChange={(e) =>
                        setCreateForm({
                          ...createForm,
                          category: e.target.value,
                        })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      placeholder="مثال: مخالفة مرورية"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      التاريخ
                    </label>
                    <input
                      type="date"
                      value={createForm.date}
                      onChange={(e) =>
                        setCreateForm({ ...createForm, date: e.target.value })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      الشهر الفعلي *
                    </label>
                    <select
                      value={createForm.effectiveMonth}
                      onChange={(e) =>
                        setCreateForm({
                          ...createForm,
                          effectiveMonth: parseInt(e.target.value),
                        })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    >
                      {Array.from({ length: 12 }, (_, i) => i + 1).map(
                        (month) => (
                          <option key={month} value={month}>
                            {month}
                          </option>
                        ),
                      )}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      السنة الفعلية *
                    </label>
                    <select
                      value={createForm.effectiveYear}
                      onChange={(e) =>
                        setCreateForm({
                          ...createForm,
                          effectiveYear: parseInt(e.target.value),
                        })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    >
                      {Array.from(
                        { length: 3 },
                        (_, i) => new Date().getFullYear() + i,
                      ).map((year) => (
                        <option key={year} value={year}>
                          {year}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      السبب *
                    </label>
                    <input
                      type="text"
                      value={createForm.reason}
                      onChange={(e) =>
                        setCreateForm({ ...createForm, reason: e.target.value })
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      placeholder="سبب الخصم"
                      required
                    />
                  </div>

                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      الوصف
                    </label>
                    <textarea
                      value={createForm.description}
                      onChange={(e) =>
                        setCreateForm({
                          ...createForm,
                          description: e.target.value,
                        })
                      }
                      rows={3}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      placeholder="تفاصيل إضافية..."
                    />
                  </div>

                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      ملاحظات
                    </label>
                    <textarea
                      value={createForm.notes}
                      onChange={(e) =>
                        setCreateForm({ ...createForm, notes: e.target.value })
                      }
                      rows={2}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      placeholder="ملاحظات داخلية..."
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end space-x-2 space-x-reverse mt-6">
                <button
                  onClick={() => {
                    setShowCreateModal(false);
                    resetCreateForm();
                  }}
                  className="px-4 py-2 bg-gray-300 dark:bg-gray-600 text-gray-700 dark:text-gray-200 rounded-md hover:bg-gray-400 dark:hover:bg-gray-500"
                >
                  إلغاء
                </button>
                <button
                  onClick={handleCreateDeduction}
                  disabled={
                    !createForm.employeeId ||
                    !createForm.amount ||
                    !createForm.reason
                  }
                  className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50"
                >
                  {isEditing ? "تحديث" : "إنشاء"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Details Modal */}
      {showDetailsModal && selectedDeduction && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 dark:bg-gray-900 dark:bg-opacity-75 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border border-gray-200 dark:border-gray-700 w-full max-w-2xl shadow-lg rounded-md bg-white dark:bg-gray-800 max-h-[80vh] overflow-y-auto">
            <div className="mt-3">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                  تفاصيل الخصم
                </h3>
                <button
                  onClick={() => setShowDetailsModal(false)}
                  className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                >
                  <X className="h-6 w-6" />
                </button>
              </div>

              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      الموظف
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {selectedDeduction.employee?.firstName}{" "}
                      {selectedDeduction.employee?.lastName}
                    </p>
                  </div>

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      رقم الموظف
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {selectedDeduction.employee?.employeeNumber}
                    </p>
                  </div>

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      النوع
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {
                        DEDUCTION_TYPES[
                        selectedDeduction.type as keyof typeof DEDUCTION_TYPES
                        ]
                      }
                    </p>
                  </div>

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      المبلغ
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {formatCurrency(selectedDeduction.amount)}
                    </p>
                  </div>

                  {selectedDeduction.category && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        التصنيف
                      </p>
                      <p className="text-base font-medium text-gray-900 dark:text-white">
                        {selectedDeduction.category}
                      </p>
                    </div>
                  )}

                  <div className="col-span-2">
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      السبب
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {selectedDeduction.reason}
                    </p>
                  </div>

                  {selectedDeduction.description && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        الوصف
                      </p>
                      <p className="text-base text-gray-900 dark:text-white">
                        {selectedDeduction.description}
                      </p>
                    </div>
                  )}

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      التاريخ الفعلي
                    </p>
                    <p className="text-base font-medium text-gray-900 dark:text-white">
                      {formatDateWithDay(selectedDeduction.date)}
                    </p>
                  </div>

                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      الحالة
                    </p>
                    <span
                      className={`inline-block px-2 py-1 rounded-full text-xs font-medium ${DEDUCTION_STATUS[selectedDeduction.status as keyof typeof DEDUCTION_STATUS]?.color}`}
                    >
                      {
                        DEDUCTION_STATUS[
                          selectedDeduction.status as keyof typeof DEDUCTION_STATUS
                        ]?.label
                      }
                    </span>
                  </div>

                  {selectedDeduction.rejectionReason && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        سبب الرفض
                      </p>
                      <p className="text-base text-red-600 dark:text-red-400">
                        {selectedDeduction.rejectionReason}
                      </p>
                    </div>
                  )}

                  {selectedDeduction.notes && (
                    <div className="col-span-2">
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        ملاحظات
                      </p>
                      <p className="text-base text-gray-900 dark:text-white">
                        {selectedDeduction.notes}
                      </p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Deductions;

import React, { useState, useEffect } from "react";
import {
  Building2,
  Plus,
  Trash2,
  Users,
  MoreVertical,
  ChevronRight,
  UserCircle,
  X,
  UserPlus,
  Pencil,
  Activity,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Badge } from "../../components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../../components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "../../components/ui/dialog";
import { Label } from "../../components/ui/label";
import { Textarea } from "../../components/ui/textarea";
import { Switch } from "../../components/ui/switch";
import api from "../../services/api";
import { toast } from "sonner";
import { useAuth } from "../../hooks/useAuthSimple";
import { motion, AnimatePresence } from "framer-motion";
import DepartmentCard from "./components/DepartmentCard";
import DepartmentSkeleton from "./components/DepartmentSkeleton";
import HierarchyView from "./components/HierarchyView";
import { LayoutGrid, Network as HierarchyIcon } from "lucide-react";

interface Department {
  id: string;
  name: string;
  nameEn: string | null;
  description: string | null;
  color: string;
  isActive: boolean;
  sortOrder: number;
  createdAt: string;
  parentId: string | null;
  managerId: string | null;
  manager: {
    id: string;
    firstName: string;
    lastName: string;
    avatar: string;
  } | null;
  parent: {
    id: string;
    name: string;
  } | null;
  _count: {
    users: number; // ✅ Changed from employees to users (employees are in User table)
    positions: number;
    children: number;
  };
}

interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  email?: string;
  avatar?: string;
  hasEmployeeRecord?: boolean;
  department?: {
    id: string;
    name: string;
  } | null;
  departmentId?: string | null;
  position?: {
    title: string;
  } | null;
}

const colorOptions = [
  { value: "#3B82F6", label: "أزرق" },
  { value: "#10B981", label: "أخضر" },
  { value: "#F59E0B", label: "برتقالي" },
  { value: "#EF4444", label: "أحمر" },
  { value: "#8B5CF6", label: "بنفسجي" },
  { value: "#EC4899", label: "وردي" },
  { value: "#06B6D4", label: "سماوي" },
  { value: "#84CC16", label: "ليموني" },
  { value: "#F97316", label: "برتقالي غامق" },
  { value: "#6366F1", label: "نيلي" },
  { value: "#14B8A6", label: "تركوازي" },
  { value: "#FACC15", label: "أصفر" },
  { value: "#475569", label: "رمادي" },
];

const Departments: React.FC = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [departments, setDepartments] = useState<Department[]>([]);

  // Check if user has permission to manage departments
  const canManage =
    user &&
    ["SUPER_ADMIN", "COMPANY_ADMIN", "HR_MANAGER", "OWNER"].includes(user.role);
  const [employees, setEmployees] = useState<Employee[]>([]);

  // Dialog states
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [showDetailsDialog, setShowDetailsDialog] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [showRemoveConfirm, setShowRemoveConfirm] = useState(false);
  const [employeeToRemove, setEmployeeToRemove] = useState<string | null>(null);
  const [selectedDepartment, setSelectedDepartment] =
    useState<Department | null>(null);
  const [isEditingDetails, setIsEditingDetails] = useState(false);
  const [isAddingEmployees, setIsAddingEmployees] = useState(false);

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    nameEn: "",
    description: "",
    color: "#3B82F6",
    parentId: "none",
    managerId: "none",
    isActive: true,
    sortOrder: 0,
  });

  const [viewMode, setViewMode] = useState<"grid" | "hierarchy">("grid");

  // Bulk import state
  const [selectedEmployees, setSelectedEmployees] = useState<string[]>([]);
  const [assignEmployeesSelection, setAssignEmployeesSelection] = useState<
    string[]
  >([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAssigningEmployees, setIsAssigningEmployees] = useState(false);

  // Search and Filter states
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState<
    "all" | "active" | "inactive"
  >("all");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 9;
  const [employeeSearchQuery, setEmployeeSearchQuery] = useState("");

  useEffect(() => {
    fetchDepartments();
    fetchEmployees();
  }, []);

  const fetchDepartments = async () => {
    try {
      setLoading(true);
      const response = await api.get("/hr/departments?includeInactive=true");
      setDepartments(response.data.departments);
    } catch (error: any) {
      console.error("Error fetching departments:", error);
      const errorMessage =
        error.response?.data?.error ||
        error.message ||
        "حدث خطأ أثناء جلب الأقسام";
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    try {
      const response = await api.get("/hr/employees?limit=1000");
      setEmployees(response.data.employees);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  };

  // Validation function
  const validateDepartmentData = (data: typeof formData): string[] => {
    const errors: string[] = [];

    if (!data.name || data.name.trim().length === 0) {
      errors.push("اسم القسم مطلوب");
    }

    if (data.name && data.name.length > 100) {
      errors.push("اسم القسم يجب ألا يتجاوز 100 حرف");
    }

    if (data.nameEn && data.nameEn.length > 100) {
      errors.push("الاسم الإنجليزي يجب ألا يتجاوز 100 حرف");
    }

    if (data.nameEn && !/^[a-zA-Z0-9\s]*$/.test(data.nameEn)) {
      errors.push("الاسم الإنجليزي يجب أن يحتوي على أحرف إنجليزية وأرقام فقط");
    }

    if (data.description && data.description.length > 500) {
      errors.push("الوصف يجب ألا يتجاوز 500 حرف");
    }

    return errors;
  };

  // Filter and search logic
  const filteredDepartments = departments.filter((dept) => {
    // Search filter
    const matchesSearch =
      searchQuery.trim() === "" ||
      dept.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      dept.nameEn?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      dept.description?.toLowerCase().includes(searchQuery.toLowerCase());

    // Status filter
    const matchesStatus =
      filterStatus === "all" ||
      (filterStatus === "active" && dept.isActive) ||
      (filterStatus === "inactive" && !dept.isActive);

    return matchesSearch && matchesStatus;
  }).sort((a, b) => {
    if (a.sortOrder !== b.sortOrder) return (a.sortOrder || 0) - (b.sortOrder || 0);
    return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
  });

  // Pagination logic
  const totalPages = Math.ceil(filteredDepartments.length / itemsPerPage);
  const paginatedDepartments = filteredDepartments.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );

  // Reset to page 1 when search or filter changes
  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, filterStatus]);

  // Filter employees for search
  const filteredEmployees = employees.filter((emp) => {
    if (!employeeSearchQuery.trim()) return true;
    const query = employeeSearchQuery.toLowerCase();
    return (
      emp.firstName.toLowerCase().includes(query) ||
      emp.lastName.toLowerCase().includes(query) ||
      emp.email?.toLowerCase().includes(query)
    );
  });

  // Toggle employee selection
  const toggleEmployeeSelection = (employeeId: string) => {
    setSelectedEmployees((prev) =>
      prev.includes(employeeId)
        ? prev.filter((id) => id !== employeeId)
        : [...prev, employeeId],
    );
  };

  // Reset employee selection
  const resetEmployeeSelection = () => {
    setSelectedEmployees([]);
  };

  const fillFormFromDepartment = (dept: Department) => {
    setFormData({
      name: dept.name,
      nameEn: dept.nameEn || "",
      description: dept.description || "",
      color: dept.color || "#3B82F6",
      parentId: dept.parentId || "none",
      managerId: dept.managerId || "none",
      isActive: dept.isActive,
      sortOrder: dept.sortOrder || 0,
    });
  };

  const toggleAssignEmployeeSelection = (employeeId: string) => {
    setAssignEmployeesSelection((prev) =>
      prev.includes(employeeId)
        ? prev.filter((id) => id !== employeeId)
        : [...prev, employeeId],
    );
  };

  const resetAssignEmployeeSelection = () => {
    setAssignEmployeesSelection([]);
  };

  const handleAddDepartment = async () => {
    if (!canManage) {
      toast.error("غير مصرح لك بإضافة أقسام");
      return;
    }

    // Validate data first
    const validationErrors = validateDepartmentData(formData);
    if (validationErrors.length > 0) {
      validationErrors.forEach((error) => toast.error(error));
      return;
    }

    // If no employees selected, use regular department creation
    if (selectedEmployees.length === 0) {
      try {
        const submitData = {
          ...formData,
          parentId:
            formData.parentId === "none" ? null : formData.parentId || null,
          managerId:
            formData.managerId === "none" ? null : formData.managerId || null,
        };
        await api.post("/hr/departments", submitData);
        toast.success("تم إضافة القسم بنجاح");
        setShowAddDialog(false);
        resetForm();
        fetchDepartments();
      } catch (error: any) {
        const errorMessage =
          error.response?.data?.error ||
          error.message ||
          "حدث خطأ أثناء إضافة القسم";
        toast.error(errorMessage);
      }
      return;
    }

    // If there are selected employees, create department and assign employees
    setIsProcessing(true);
    try {
      // First create the department
      const deptData = {
        ...formData,
        parentId:
          formData.parentId === "none" ? null : formData.parentId || null,
        managerId:
          formData.managerId === "none" ? null : formData.managerId || null,
      };

      const deptResponse = await api.post("/hr/departments", deptData);
      const newDepartmentId = deptResponse.data.department.id;

      // Then assign selected employees to the new department
      const assignPromises = selectedEmployees.map((empId) =>
        api.put(`/hr/employees/${empId}`, { departmentId: newDepartmentId }),
      );

      await Promise.all(assignPromises);

      toast.success(
        `تم إنشاء القسم وإضافة ${selectedEmployees.length} موظف بنجاح`,
      );

      setShowAddDialog(false);
      resetForm();
      resetEmployeeSelection();
      fetchDepartments();
      fetchEmployees();
    } catch (error: any) {
      toast.error(
        error.response?.data?.error ||
        "حدث خطأ أثناء إنشاء القسم وإضافة الموظفين",
      );
    } finally {
      setIsProcessing(false);
    }
  };

  const handleEditDepartment = async () => {
    if (!selectedDepartment) return;

    if (!canManage) {
      toast.error("غير مصرح لك بتعديل الأقسام");
      return;
    }

    // Validate data first
    const validationErrors = validateDepartmentData(formData);
    if (validationErrors.length > 0) {
      validationErrors.forEach((error) => toast.error(error));
      return;
    }

    try {
      const submitData = {
        ...formData,
        parentId:
          formData.parentId === "none" ? null : formData.parentId || null,
        managerId:
          formData.managerId === "none" ? null : formData.managerId || null,
      };
      await api.put(`/hr/departments/${selectedDepartment.id}`, submitData);
      toast.success("تم تحديث القسم بنجاح");
      const manager = submitData.managerId
        ? employees.find((e) => e.id === submitData.managerId)
        : null;
      const parent = submitData.parentId
        ? departments.find((d) => d.id === submitData.parentId)
        : null;
      setSelectedDepartment((prev) =>
        prev
          ? {
            ...prev,
            name: submitData.name,
            nameEn: submitData.nameEn || null,
            description: submitData.description || null,
            color: submitData.color,
            parentId: submitData.parentId,
            managerId: submitData.managerId,
            isActive: submitData.isActive,
            sortOrder: submitData.sortOrder || 0,
            parent: parent ? { id: parent.id, name: parent.name } : null,
            manager: manager
              ? {
                id: manager.id,
                firstName: manager.firstName,
                lastName: manager.lastName,
                avatar: manager.avatar || "",
              }
              : null,
          }
          : prev,
      );
      setIsEditingDetails(false);
      fetchDepartments();
      fetchEmployees();
    } catch (error: any) {
      toast.error(error.response?.data?.error || "حدث خطأ أثناء تحديث القسم");
    }
  };

  const handleDeleteDepartment = async () => {
    if (!selectedDepartment) return;

    if (!canManage) {
      toast.error("غير مصرح لك بحذف الأقسام");
      return;
    }

    try {
      await api.delete(`/hr/departments/${selectedDepartment.id}`);
      toast.success("تم حذف القسم بنجاح");
      setShowDeleteDialog(false);
      setSelectedDepartment(null);
      fetchDepartments();
      fetchEmployees();
    } catch (error: any) {
      toast.error(error.response?.data?.error || "حدث خطأ أثناء حذف القسم");
    }
  };

  const openEditDialog = (dept: Department) => {
    setSelectedDepartment(dept);
    fillFormFromDepartment(dept);
    setShowDetailsDialog(true);
    setIsEditingDetails(true);
    setIsAddingEmployees(false);
    resetAssignEmployeeSelection();
  };

  const handleAssignEmployees = async () => {
    if (!selectedDepartment) return;

    if (!canManage) {
      toast.error("غير مصرح لك بتعيين موظفين");
      return;
    }

    if (assignEmployeesSelection.length === 0) {
      toast.error("اختر موظف واحد على الأقل");
      return;
    }

    setIsAssigningEmployees(true);
    try {
      const assignPromises = assignEmployeesSelection.map((empId) =>
        api.put(`/hr/employees/${empId}`, {
          departmentId: selectedDepartment.id,
        }),
      );
      await Promise.all(assignPromises);
      toast.success(`تم إضافة ${assignEmployeesSelection.length} موظف للقسم`);
      setIsAddingEmployees(false);
      resetAssignEmployeeSelection();
      fetchDepartments();
      fetchEmployees();
    } catch (error: any) {
      toast.error(
        error.response?.data?.error || "حدث خطأ أثناء إضافة الموظفين للقسم",
      );
    } finally {
      setIsAssigningEmployees(false);
    }
  };

  const handleRemoveFromDepartment = async (employeeId: string) => {
    if (!canManage) {
      toast.error("غير مصرح لك بتغيير قسم الموظفين");
      return;
    }

    setEmployeeToRemove(employeeId);
    setShowRemoveConfirm(true);
  };

  const confirmRemoveFromDepartment = async () => {
    if (!employeeToRemove) return;

    try {
      await api.put(`/hr/employees/${employeeToRemove}`, {
        departmentId: null,
      });
      toast.success("تم إزالة الموظف من القسم");
      setShowRemoveConfirm(false);
      setEmployeeToRemove(null);
      fetchDepartments();
      fetchEmployees();
    } catch (error: any) {
      toast.error(error.response?.data?.error || "حدث خطأ أثناء إزالة الموظف");
    }
  };

  const openDetailsDialog = (dept: Department) => {
    setSelectedDepartment(dept);
    fillFormFromDepartment(dept);
    setShowDetailsDialog(true);
    setIsEditingDetails(false);
    setIsAddingEmployees(false);
    resetAssignEmployeeSelection();
  };

  const resetForm = () => {
    setFormData({
      name: "",
      nameEn: "",
      description: "",
      color: "#3B82F6",
      parentId: "none",
      managerId: "none",
      isActive: true,
      sortOrder: 0,
    });
  };

  const totalEmployees = departments.reduce(
    (sum, d) => sum + d._count.users,
    0,
  );

  return (
    <div className="p-6 space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            إدارة الأقسام
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {departments.length} قسم • {totalEmployees} موظف
          </p>
        </div>
        <div className="flex items-center gap-2">
          {canManage && (
            <Button onClick={() => setShowAddDialog(true)}>
              <Plus className="h-4 w-4 ml-2" />
              إضافة قسم
            </Button>
          )}
        </div>
      </div>

      {/* Search and Filter Bar */}
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="bg-white dark:bg-gray-900 p-4 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-xl shadow-gray-200/20 dark:shadow-none"
      >
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative group">
            <Input
              placeholder="ابحث عن قسم بالاسم أو الوصف..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 h-12 bg-gray-50/50 dark:bg-gray-800/50 border-none rounded-2xl focus-visible:ring-2 focus-visible:ring-primary/20 transition-all font-medium"
            />
            <Activity className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400 group-hover:text-primary transition-colors" />
          </div>
          <div className="flex gap-2">
            <Select
              value={filterStatus}
              onValueChange={(value: any) => setFilterStatus(value)}
            >
              <SelectTrigger className="w-full md:w-56 h-12 bg-gray-50/50 dark:bg-gray-800/50 border-none rounded-2xl focus:ring-2 focus:ring-primary/20">
                <SelectValue placeholder="حالة الأقسام" />
              </SelectTrigger>
              <SelectContent className="rounded-2xl border-gray-100 dark:border-gray-800">
                <SelectItem value="all">جميع الأقسام</SelectItem>
                <SelectItem value="active">النشطة والفعالة</SelectItem>
                <SelectItem value="inactive">المؤرشفة (غير نشطة)</SelectItem>
              </SelectContent>
            </Select>
            {(searchQuery || filterStatus !== "all") && (
              <Button
                variant="ghost"
                onClick={() => {
                  setSearchQuery("");
                  setFilterStatus("all");
                }}
                className="h-12 px-6 rounded-2xl text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-950/20"
              >
                <X className="h-4 w-4 ml-2" />
                تصفير
              </Button>
            )}
          </div>
        </div>
      </motion.div>

      {/* Stats */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="grid grid-cols-1 md:grid-cols-3 gap-6"
      >
        <Card className="border-none shadow-md bg-gradient-to-br from-blue-50 to-white dark:from-blue-950/20 dark:to-gray-900 overflow-hidden relative group">
          <div className="absolute right-0 top-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
            <Building2 className="h-16 w-16 text-blue-600" />
          </div>
          <CardContent className="p-6 relative">
            <p className="text-gray-500 dark:text-gray-400 text-sm font-bold uppercase tracking-wider">
              إجمالي الأقسام
            </p>
            <h3 className="text-4xl font-black mt-2 text-blue-600 dark:text-blue-400">
              {departments.length}
            </h3>
          </CardContent>
        </Card>

        <Card className="border-none shadow-md bg-gradient-to-br from-emerald-50 to-white dark:from-emerald-950/20 dark:to-gray-900 overflow-hidden relative group">
          <div className="absolute right-0 top-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
            <Activity className="h-16 w-16 text-emerald-600" />
          </div>
          <CardContent className="p-6 relative">
            <p className="text-gray-500 dark:text-gray-400 text-sm font-bold uppercase tracking-wider">
              الأقسام النشطة
            </p>
            <h3 className="text-4xl font-black mt-2 text-emerald-600 dark:text-emerald-400">
              {departments.filter((d) => d.isActive).length}
            </h3>
          </CardContent>
        </Card>

        <Card className="border-none shadow-md bg-gradient-to-br from-purple-50 to-white dark:from-purple-950/20 dark:to-gray-900 overflow-hidden relative group">
          <div className="absolute right-0 top-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
            <Users className="h-16 w-16 text-purple-600" />
          </div>
          <CardContent className="p-6 relative">
            <p className="text-gray-500 dark:text-gray-400 text-sm font-bold uppercase tracking-wider">
              إجمالي الموظفين
            </p>
            <h3 className="text-4xl font-black mt-2 text-purple-600 dark:text-purple-400">
              {totalEmployees}
            </h3>
          </CardContent>
        </Card>
      </motion.div>

      {/* View Toggle and Controls */}
      <div className="flex items-center justify-between bg-white dark:bg-gray-900 p-2 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-sm">
        <div className="flex gap-1 p-1 bg-gray-100 dark:bg-gray-800 rounded-xl">
          <Button
            variant={viewMode === "grid" ? "default" : "ghost"}
            size="sm"
            onClick={() => setViewMode("grid")}
            className="rounded-lg gap-2"
          >
            <LayoutGrid className="h-4 w-4" />
            عرض الشبكة
          </Button>
          <Button
            variant={viewMode === "hierarchy" ? "default" : "ghost"}
            size="sm"
            onClick={() => setViewMode("hierarchy")}
            className="rounded-lg gap-2"
          >
            <HierarchyIcon className="h-4 w-4" />
            الهيكل التنظيمي
          </Button>
        </div>
      </div>

      {/* Main Content Area */}
      <AnimatePresence mode="wait">
        {loading ? (
          <motion.div
            key="loading"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <DepartmentSkeleton />
          </motion.div>
        ) : viewMode === "hierarchy" ? (
          <motion.div
            key="hierarchy"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
          >
            <HierarchyView departments={departments} />
          </motion.div>
        ) : departments.length === 0 ? (
          <motion.div
            key="empty"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
          >
            <Card className="border-dashed border-2">
              <CardContent className="flex flex-col items-center justify-center h-64 text-gray-400">
                <Building2 className="h-16 w-16 mb-4 opacity-20" />
                <p className="text-lg font-medium">لا توجد أقسام مضافة بعد</p>
                {canManage && (
                  <Button
                    variant="link"
                    className="mt-2 text-primary hover:underline"
                    onClick={() => setShowAddDialog(true)}
                  >
                    ابدأ بإضافة أول قسم الآن
                  </Button>
                )}
              </CardContent>
            </Card>
          </motion.div>
        ) : (
          <motion.div
            key="grid"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="space-y-6"
          >
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {paginatedDepartments.map((dept) => (
                <DepartmentCard
                  key={dept.id}
                  department={dept}
                  onViewDetails={openDetailsDialog}
                  onDelete={(d) => {
                    setSelectedDepartment(d);
                    setShowDeleteDialog(true);
                  }}
                  canManage={canManage || false}
                />
              ))}
            </div>

            {/* Pagination moved here for consistency */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between px-2 py-4">
                <div className="text-sm font-medium text-gray-500">
                  عرض {paginatedDepartments.length} من{" "}
                  {filteredDepartments.length} قسم
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() =>
                      setCurrentPage((prev) => Math.max(1, prev - 1))
                    }
                    disabled={currentPage === 1}
                    className="rounded-xl"
                  >
                    السابق
                  </Button>
                  <div className="flex gap-1">
                    {Array.from({ length: totalPages }, (_, i) => i + 1)
                      .filter(
                        (page) =>
                          page === 1 ||
                          page === totalPages ||
                          Math.abs(page - currentPage) <= 1,
                      )
                      .map((page, idx, arr) => (
                        <React.Fragment key={page}>
                          {idx > 0 && arr[idx - 1] !== page - 1 && (
                            <span className="flex items-center text-gray-300">
                              ...
                            </span>
                          )}
                          <Button
                            variant={
                              currentPage === page ? "default" : "outline"
                            }
                            size="sm"
                            onClick={() => setCurrentPage(page)}
                            className={`min-w-[40px] rounded-xl font-bold ${currentPage === page ? "shadow-lg shadow-primary/20" : ""}`}
                          >
                            {page}
                          </Button>
                        </React.Fragment>
                      ))}
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() =>
                      setCurrentPage((prev) => Math.min(totalPages, prev + 1))
                    }
                    disabled={currentPage === totalPages}
                    className="rounded-xl"
                  >
                    التالي
                  </Button>
                </div>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Add Department Dialog */}
      <Dialog
        open={showAddDialog}
        onOpenChange={(open) => {
          setShowAddDialog(open);
          if (!open) {
            resetForm();
            resetEmployeeSelection();
            setEmployeeSearchQuery("");
          }
        }}
      >
        <DialogContent className="max-w-2xl max-h-[95vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="text-gray-900 dark:text-white">
              إضافة قسم جديد
            </DialogTitle>
            <DialogDescription className="text-gray-600 dark:text-gray-400">
              أدخل بيانات القسم ويمكنك اختيار المدير وإضافة الموظفين إن رغبت.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-6 py-4">
            {/* Department Info Section */}
            <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-lg space-y-4">
              <h3 className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                <Building2 className="h-4 w-4" />
                معلومات القسم
              </h3>
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label className="text-gray-700 dark:text-gray-300">
                    اسم القسم *
                  </Label>
                  <Input
                    value={formData.name}
                    onChange={(e) =>
                      setFormData({ ...formData, name: e.target.value })
                    }
                    placeholder="مثال: قسم المبيعات"
                  />
                </div>

                <div className="space-y-2">
                  <Label className="text-gray-700 dark:text-gray-300">
                    الاسم بالإنجليزية
                  </Label>
                  <Input
                    value={formData.nameEn}
                    onChange={(e) =>
                      setFormData({ ...formData, nameEn: e.target.value })
                    }
                    placeholder="e.g. Sales Department"
                    dir="ltr"
                  />
                </div>

                <div className="space-y-2">
                  <Label className="text-gray-700 dark:text-gray-300">
                    الوصف
                  </Label>
                  <Textarea
                    value={formData.description}
                    onChange={(e) =>
                      setFormData({ ...formData, description: e.target.value })
                    }
                    placeholder="وصف مختصر للقسم..."
                    rows={2}
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-gray-700 dark:text-gray-300">
                      اللون
                    </Label>
                    <div className="flex gap-2 flex-wrap">
                      {colorOptions.map((color) => (
                        <button
                          key={color.value}
                          type="button"
                          className={`w-8 h-8 rounded-full border-2 transition-all ${formData.color === color.value
                            ? "border-gray-900 dark:border-gray-100 scale-110"
                            : "border-transparent"
                            }`}
                          style={{ backgroundColor: color.value }}
                          onClick={() =>
                            setFormData({ ...formData, color: color.value })
                          }
                          title={color.label}
                        />
                      ))}
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label className="text-gray-700 dark:text-gray-300">
                      القسم الأب
                    </Label>
                    <Select
                      value={formData.parentId}
                      onValueChange={(value) =>
                        setFormData({ ...formData, parentId: value })
                      }
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="اختر القسم الأب" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="none">بدون</SelectItem>
                        {departments.map((dept) => (
                          <SelectItem key={dept.id} value={dept.id}>
                            {dept.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label className="text-gray-700 dark:text-gray-300">
                      ترتيب العرض
                    </Label>
                    <Input
                      type="number"
                      value={formData.sortOrder}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          sortOrder: parseInt(e.target.value) || 0,
                        })
                      }
                      placeholder="0"
                    />
                    <p className="text-[10px] text-gray-400">
                      أرقام أصغر تظهر أولاً
                    </p>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label className="text-gray-700 dark:text-gray-300">
                    مدير القسم (اختياري)
                  </Label>
                  <Select
                    value={formData.managerId}
                    onValueChange={(value) =>
                      setFormData({ ...formData, managerId: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="اختر المدير" />
                    </SelectTrigger>
                    <SelectContent className="max-h-60">
                      <SelectItem value="none">بدون</SelectItem>
                      {employees.map((emp) => (
                        <SelectItem key={emp.id} value={emp.id}>
                          <div className="flex items-center gap-2">
                            <span className="font-medium">
                              {emp.firstName} {emp.lastName}
                            </span>
                            <span className="text-gray-400 text-sm">•</span>
                            <span className="text-gray-500 text-sm">
                              {emp.email || "لا يوجد بريد"}
                            </span>
                          </div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex items-center justify-between gap-4 py-2">
                  <Label
                    htmlFor="isActive-add"
                    className="text-gray-700 dark:text-gray-300 cursor-pointer"
                  >
                    القسم نشط
                  </Label>
                  <Switch
                    id="isActive-add"
                    checked={formData.isActive}
                    onCheckedChange={(checked) =>
                      setFormData({ ...formData, isActive: checked })
                    }
                    className="data-[state=checked]:bg-green-600 data-[state=unchecked]:bg-gray-300 dark:data-[state=unchecked]:bg-gray-600"
                  />
                </div>

                <div className="space-y-2">
                  <Label className="text-gray-700 dark:text-gray-300">
                    ترتيب العرض (اختياري)
                  </Label>
                  <Input
                    type="number"
                    value={formData.sortOrder}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        sortOrder: parseInt(e.target.value) || 0,
                      })
                    }
                    placeholder="0"
                  />
                  <p className="text-[10px] text-gray-400">أرقام أصغر تظهر أولاً</p>
                </div>
              </div>
            </div>

            {/* Employees Selection Section */}
            <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-lg space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                  <Users className="h-4 w-4" />
                  إضافة موظفين (اختياري)
                </h3>
                {selectedEmployees.length > 0 && (
                  <Badge
                    variant="default"
                    className="bg-blue-100 text-blue-800"
                  >
                    {selectedEmployees.length} موظف محدد
                  </Badge>
                )}
              </div>

              {/* Employee Multi-Select Dropdown */}
              <div className="space-y-2">
                <Label className="text-gray-700 dark:text-gray-300 text-sm">
                  اختر الموظفين من القائمة
                </Label>
                {/* Search input for employees */}
                <Input
                  placeholder="ابحث عن موظف..."
                  value={employeeSearchQuery}
                  onChange={(e) => setEmployeeSearchQuery(e.target.value)}
                  className="mb-2"
                />
                <div className="max-h-60 overflow-y-auto border rounded-xl p-2 bg-white dark:bg-gray-900 space-y-1">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        className={`flex items-center justify-between p-2 rounded-lg cursor-pointer transition-colors ${selectedEmployees.includes(emp.id)
                          ? "bg-blue-50 dark:bg-blue-900/30"
                          : "hover:bg-gray-50 dark:hover:bg-gray-800"
                          }`}
                        onClick={() => toggleEmployeeSelection(emp.id)}
                      >
                        <div className="flex items-center gap-2">
                          <Avatar className="h-8 w-8">
                            <AvatarImage src={emp.avatar} />
                            <AvatarFallback>
                              {emp.firstName[0]}
                              {emp.lastName[0]}
                            </AvatarFallback>
                          </Avatar>
                          <div className="flex flex-col">
                            <span className="font-medium text-sm">
                              {emp.firstName} {emp.lastName}
                            </span>
                            <span className="text-xs text-gray-500">
                              {emp.email || "لا يوجد بريد"}
                            </span>
                          </div>
                        </div>
                        <div
                          className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${selectedEmployees.includes(emp.id)
                            ? "bg-blue-600 border-blue-600 text-white"
                            : "border-gray-300 dark:border-gray-600"
                            }`}
                        >
                          {selectedEmployees.includes(emp.id) && (
                            <Plus className="h-3 w-3" />
                          )}
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-4 text-gray-400 text-sm">
                      لا يوجد نتائج للبحث
                    </div>
                  )}
                </div>
              </div>

              {/* Selected Employees List */}
              {selectedEmployees.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-gray-700 dark:text-gray-300 text-sm">
                    الموظفون المحددون:
                  </Label>
                  <div className="border rounded-lg overflow-hidden max-h-40 overflow-y-auto">
                    <div className="divide-y dark:divide-gray-700">
                      {selectedEmployees.map((empId) => {
                        const emp = employees.find((e) => e.id === empId);
                        if (!emp) return null;
                        return (
                          <div
                            key={empId}
                            className="flex items-center justify-between p-2 bg-white dark:bg-gray-800"
                          >
                            <div className="flex items-center gap-2">
                              <Avatar className="h-8 w-8">
                                <AvatarImage src={emp.avatar} />
                                <AvatarFallback className="text-xs bg-primary text-white">
                                  {emp.firstName?.[0]}
                                  {emp.lastName?.[0]}
                                </AvatarFallback>
                              </Avatar>
                              <div>
                                <div className="font-medium text-sm">
                                  {emp.firstName} {emp.lastName}
                                </div>
                                <div className="text-xs text-gray-500">
                                  {emp.email}
                                </div>
                              </div>
                            </div>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 text-red-500 hover:text-red-700"
                              onClick={() => toggleEmployeeSelection(empId)}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          <DialogFooter className="flex-col sm:flex-row gap-2 pt-4">
            <Button
              variant="outline"
              onClick={() => {
                setShowAddDialog(false);
                resetEmployeeSelection();
                setEmployeeSearchQuery("");
              }}
              className="w-full sm:w-auto"
            >
              إلغاء
            </Button>
            <Button
              onClick={handleAddDepartment}
              className="w-full sm:w-auto gap-2"
              disabled={isProcessing || !formData.name}
            >
              {isProcessing ? (
                <>
                  <div className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full" />
                  جاري الإنشاء...
                </>
              ) : (
                <>
                  {selectedEmployees.length > 0 ? (
                    <>
                      <UserPlus className="h-4 w-4" />
                      إضافة القسم و {selectedEmployees.length} موظف
                    </>
                  ) : (
                    <>
                      <Plus className="h-4 w-4" />
                      إضافة القسم
                    </>
                  )}
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Department Details Dialog */}
      <Dialog
        open={showDetailsDialog}
        onOpenChange={(open) => {
          setShowDetailsDialog(open);
          if (!open) {
            setIsEditingDetails(false);
            setIsAddingEmployees(false);
            resetAssignEmployeeSelection();
            setEmployeeSearchQuery("");
          }
        }}
      >
        <DialogContent className="max-w-4xl max-h-[95vh] overflow-y-auto p-0 rounded-3xl border-none">
          <DialogHeader className="sr-only">
            <DialogTitle>
              {selectedDepartment
                ? `تفاصيل قسم ${selectedDepartment.name}`
                : "تفاصيل القسم"}
            </DialogTitle>
            <DialogDescription>
              عرض بيانات القسم وإدارة الموظفين والتعديلات.
            </DialogDescription>
          </DialogHeader>
          {selectedDepartment && (
            <div className="bg-gradient-to-br from-purple-100 via-pink-100 to-blue-100 dark:from-gray-900 dark:via-gray-900 dark:to-gray-800 p-6">
              <div className="flex flex-col gap-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div
                      className="w-4 h-4 rounded-full"
                      style={{
                        backgroundColor: selectedDepartment.color || "#3B82F6",
                      }}
                    />
                    <div>
                      <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
                        {selectedDepartment.name}
                      </h2>
                      {selectedDepartment.nameEn && (
                        <p className="text-gray-600 dark:text-gray-300">
                          {selectedDepartment.nameEn}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge
                      variant={
                        selectedDepartment.isActive ? "default" : "secondary"
                      }
                    >
                      {selectedDepartment.isActive ? "نشط" : "غير نشط"}
                    </Badge>
                    {canManage && (
                      <>
                        <Button
                          variant={isAddingEmployees ? "secondary" : "outline"}
                          className="gap-2"
                          onClick={() => {
                            setIsAddingEmployees((prev) => !prev);
                            setIsEditingDetails(false);
                          }}
                        >
                          <UserPlus className="h-4 w-4" />
                          {isAddingEmployees
                            ? "إغلاق إضافة الموظفين"
                            : "إضافة موظفين"}
                        </Button>
                        <Button
                          variant={isEditingDetails ? "secondary" : "outline"}
                          className="gap-2"
                          onClick={() => {
                            setIsEditingDetails((prev) => {
                              const next = !prev;
                              if (!next && selectedDepartment) {
                                fillFormFromDepartment(selectedDepartment);
                              }
                              return next;
                            });
                            setIsAddingEmployees(false);
                          }}
                        >
                          <Pencil className="h-4 w-4" />
                          {isEditingDetails ? "إلغاء التعديل" : "تعديل"}
                        </Button>
                      </>
                    )}
                    <Button
                      variant="outline"
                      onClick={() => setShowDetailsDialog(false)}
                    >
                      رجوع
                    </Button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <Card className="bg-white/70 dark:bg-gray-900/60">
                    <CardContent className="p-4 flex items-center justify-between">
                      <div>
                        <p className="text-sm text-gray-500 dark:text-gray-400">
                          عدد الموظفين
                        </p>
                        <p className="text-2xl font-bold text-gray-900 dark:text-white">
                          {selectedDepartment._count.users}
                        </p>
                      </div>
                      <Users className="h-8 w-8 text-blue-500" />
                    </CardContent>
                  </Card>
                  <Card className="bg-white/70 dark:bg-gray-900/60">
                    <CardContent className="p-4 flex items-center justify-between">
                      <div>
                        <p className="text-sm text-gray-500 dark:text-gray-400">
                          الأقسام الفرعية
                        </p>
                        <p className="text-2xl font-bold text-gray-900 dark:text-white">
                          {selectedDepartment._count.children}
                        </p>
                      </div>
                      <Building2 className="h-8 w-8 text-purple-500" />
                    </CardContent>
                  </Card>
                  <Card className="bg-white/70 dark:bg-gray-900/60">
                    <CardContent className="p-4 flex items-center justify-between">
                      <div>
                        <p className="text-sm text-gray-500 dark:text-gray-400">
                          الوظائف
                        </p>
                        <p className="text-2xl font-bold text-gray-900 dark:text-white">
                          {selectedDepartment._count.positions}
                        </p>
                      </div>
                      <Users className="h-8 w-8 text-green-500" />
                    </CardContent>
                  </Card>
                </div>

                <Card className="bg-white/80 dark:bg-gray-900/60">
                  <CardHeader className="pb-2">
                    <CardTitle className="text-lg">معلومات القسم</CardTitle>
                  </CardHeader>
                  <CardContent className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
                    <div className="space-y-1">
                      <p className="text-gray-500 dark:text-gray-400">المدير</p>
                      {selectedDepartment.manager ? (
                        <div className="flex items-center gap-2">
                          <Avatar className="h-7 w-7">
                            <AvatarImage
                              src={selectedDepartment.manager.avatar}
                            />
                            <AvatarFallback className="text-xs">
                              {selectedDepartment.manager.firstName?.[0]}
                              {selectedDepartment.manager.lastName?.[0]}
                            </AvatarFallback>
                          </Avatar>
                          <span className="text-gray-900 dark:text-gray-100">
                            {selectedDepartment.manager.firstName}{" "}
                            {selectedDepartment.manager.lastName}
                          </span>
                        </div>
                      ) : (
                        <span className="text-gray-500">غير محدد</span>
                      )}
                    </div>
                    <div className="space-y-1">
                      <p className="text-gray-500 dark:text-gray-400">
                        القسم الأب
                      </p>
                      <span className="text-gray-900 dark:text-gray-100">
                        {selectedDepartment.parent?.name || "بدون"}
                      </span>
                    </div>
                    <div className="space-y-1">
                      <p className="text-gray-500 dark:text-gray-400">اللون</p>
                      <div className="flex items-center gap-2">
                        <span className="text-gray-900 dark:text-gray-100">
                          {selectedDepartment.color}
                        </span>
                        <div
                          className="w-5 h-5 rounded border"
                          style={{
                            backgroundColor:
                              selectedDepartment.color || "#3B82F6",
                          }}
                        />
                      </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-gray-500 dark:text-gray-400">الترتيب</p>
                      <span className="text-gray-900 dark:text-gray-100 font-bold">
                        {selectedDepartment.sortOrder || 0}
                      </span>
                    </div>
                    {selectedDepartment.description && (
                      <div className="md:col-span-3 space-y-1">
                        <p className="text-gray-500 dark:text-gray-400">
                          الوصف
                        </p>
                        <p className="text-gray-800 dark:text-gray-200">
                          {selectedDepartment.description}
                        </p>
                      </div>
                    )}
                  </CardContent>
                </Card>

                {/* ✅ Added: Employees List in Department */}
                <Card className="bg-white/80 dark:bg-gray-900/60">
                  <CardHeader className="pb-2 flex flex-row items-center justify-between">
                    <CardTitle className="text-lg flex items-center gap-2">
                      <Users className="h-5 w-5 text-blue-500" />
                      موظفو القسم
                    </CardTitle>
                    <Badge
                      variant="outline"
                      className="bg-blue-50 text-blue-700 border-blue-200"
                    >
                      {
                        employees.filter(
                          (e) =>
                            e.department?.id === selectedDepartment.id ||
                            e.departmentId === selectedDepartment.id,
                        ).length
                      }{" "}
                      موظف
                    </Badge>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-3 max-h-60 overflow-y-auto pr-1">
                      {employees.filter(
                        (e) =>
                          e.department?.id === selectedDepartment.id ||
                          e.departmentId === selectedDepartment.id,
                      ).length > 0 ? (
                        employees
                          .filter(
                            (e) =>
                              e.department?.id === selectedDepartment.id ||
                              e.departmentId === selectedDepartment.id,
                          )
                          .map((emp) => (
                            <div
                              key={emp.id}
                              className="flex items-center justify-between p-2 rounded-lg hover:bg-white/50 dark:hover:bg-gray-800/50 border border-transparent hover:border-gray-100 dark:hover:border-gray-700 transition-colors"
                            >
                              <div className="flex items-center gap-3">
                                <Avatar className="h-9 w-9 border border-gray-100">
                                  <AvatarImage src={emp.avatar} />
                                  <AvatarFallback className="bg-blue-50 text-blue-600 font-bold">
                                    {emp.firstName?.[0]}
                                    {emp.lastName?.[0]}
                                  </AvatarFallback>
                                </Avatar>
                                <div>
                                  <p className="font-medium text-sm text-gray-900 dark:text-gray-100">
                                    {emp.firstName} {emp.lastName}
                                  </p>
                                  <div className="flex items-center gap-2 text-xs text-gray-500">
                                    <span>
                                      {emp.position?.title || "بدون مسمى وظيفي"}
                                    </span>
                                    {emp.email && <span>• {emp.email}</span>}
                                  </div>
                                </div>
                              </div>
                              {canManage && (
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-8 w-8 text-red-500 hover:text-red-700 hover:bg-red-50 rounded-full"
                                  onClick={() =>
                                    handleRemoveFromDepartment(emp.id)
                                  }
                                  title="إزالة من القسم"
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              )}
                            </div>
                          ))
                      ) : (
                        <div className="text-center py-6 text-gray-500 bg-gray-50/50 dark:bg-gray-800/50 rounded-lg border border-dashed text-sm">
                          لا يوجد موظفين في هذا القسم حالياً
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>

                {isEditingDetails && (
                  <Card className="bg-white/90 dark:bg-gray-900/70">
                    <CardHeader className="pb-2">
                      <CardTitle className="text-lg">تعديل القسم</CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label className="text-gray-700 dark:text-gray-300">
                            اسم القسم *
                          </Label>
                          <Input
                            value={formData.name}
                            onChange={(e) =>
                              setFormData({ ...formData, name: e.target.value })
                            }
                          />
                        </div>
                        <div className="space-y-2">
                          <Label>ترتيب العرض (اختياري)</Label>
                          <Input
                            type="number"
                            value={formData.sortOrder}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                sortOrder: parseInt(e.target.value) || 0,
                              })
                            }
                            placeholder="0"
                          />
                          <p className="text-[10px] text-gray-400">أرقام أصغر تظهر أولاً</p>
                        </div>
                        <div className="md:col-span-2 space-y-2">
                          <Label className="text-gray-700 dark:text-gray-300">
                            الاسم بالإنجليزية
                          </Label>
                          <Input
                            value={formData.nameEn}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                nameEn: e.target.value,
                              })
                            }
                            dir="ltr"
                          />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label className="text-gray-700 dark:text-gray-300">
                          الوصف
                        </Label>
                        <Textarea
                          value={formData.description}
                          onChange={(e) =>
                            setFormData({
                              ...formData,
                              description: e.target.value,
                            })
                          }
                          rows={2}
                        />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label className="text-gray-700 dark:text-gray-300">
                            اللون
                          </Label>
                          <div className="flex gap-2 flex-wrap">
                            {colorOptions.map((color) => (
                              <button
                                key={color.value}
                                type="button"
                                className={`w-8 h-8 rounded-full border-2 transition-all ${formData.color === color.value
                                  ? "border-gray-900 dark:border-gray-100 scale-110"
                                  : "border-transparent"
                                  }`}
                                style={{ backgroundColor: color.value }}
                                onClick={() =>
                                  setFormData({
                                    ...formData,
                                    color: color.value,
                                  })
                                }
                              />
                            ))}
                          </div>
                        </div>
                        <div className="space-y-2">
                          <Label className="text-gray-700 dark:text-gray-300">
                            القسم الأب
                          </Label>
                          <Select
                            value={formData.parentId}
                            onValueChange={(value) =>
                              setFormData({ ...formData, parentId: value })
                            }
                          >
                            <SelectTrigger>
                              <SelectValue placeholder="اختر القسم الأب" />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="none">بدون</SelectItem>
                              {departments
                                .filter((d) => d.id !== selectedDepartment?.id)
                                .map((dept) => (
                                  <SelectItem key={dept.id} value={dept.id}>
                                    {dept.name}
                                  </SelectItem>
                                ))}
                            </SelectContent>
                          </Select>
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label className="text-gray-700 dark:text-gray-300">
                          مدير القسم (اختياري)
                        </Label>
                        <Select
                          value={formData.managerId}
                          onValueChange={(value) =>
                            setFormData({ ...formData, managerId: value })
                          }
                        >
                          <SelectTrigger>
                            <SelectValue placeholder="اختر المدير" />
                          </SelectTrigger>
                          <SelectContent className="max-h-60">
                            <SelectItem value="none">بدون</SelectItem>
                            {employees.map((emp) => (
                              <SelectItem key={emp.id} value={emp.id}>
                                <div className="flex items-center gap-2">
                                  <span className="font-medium">
                                    {emp.firstName} {emp.lastName}
                                  </span>
                                  <span className="text-gray-400 text-sm">
                                    •
                                  </span>
                                  <span className="text-gray-500 text-sm">
                                    {emp.email || "لا يوجد بريد"}
                                  </span>
                                </div>
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>

                      <div className="flex items-center justify-between gap-4 py-2">
                        <Label
                          htmlFor="isActive-details"
                          className="text-gray-700 dark:text-gray-300 cursor-pointer"
                        >
                          القسم نشط
                        </Label>
                        <Switch
                          id="isActive-details"
                          checked={formData.isActive}
                          onCheckedChange={(checked) =>
                            setFormData({ ...formData, isActive: checked })
                          }
                          className="data-[state=checked]:bg-green-600 data-[state=unchecked]:bg-gray-300 dark:data-[state=unchecked]:bg-gray-600"
                        />
                      </div>

                      <div className="flex flex-col sm:flex-row gap-2 justify-end pt-2">
                        <Button
                          variant="outline"
                          onClick={() => {
                            if (selectedDepartment)
                              fillFormFromDepartment(selectedDepartment);
                            setIsEditingDetails(false);
                          }}
                        >
                          إلغاء
                        </Button>
                        <Button
                          onClick={handleEditDepartment}
                          disabled={!formData.name}
                        >
                          حفظ التغييرات
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                )}

                {isAddingEmployees && (
                  <Card className="bg-white/90 dark:bg-gray-900/70">
                    <CardHeader className="pb-2">
                      <CardTitle className="text-lg">
                        إضافة موظفين للقسم
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                      <div className="space-y-2">
                        <Label className="text-gray-700 dark:text-gray-300 text-sm">
                          اختر الموظفين من القائمة
                        </Label>
                        {/* Search input for employees */}
                        <Input
                          placeholder="ابحث عن موظف..."
                          value={employeeSearchQuery}
                          onChange={(e) =>
                            setEmployeeSearchQuery(e.target.value)
                          }
                          className="mb-2"
                        />
                        <div className="max-h-60 overflow-y-auto border rounded-xl p-2 bg-white dark:bg-gray-900 space-y-1">
                          {filteredEmployees.length > 0 ? (
                            filteredEmployees.map((emp) => (
                              <div
                                key={emp.id}
                                className={`flex items-center justify-between p-2 rounded-lg cursor-pointer transition-colors ${assignEmployeesSelection.includes(emp.id)
                                  ? "bg-blue-50 dark:bg-blue-900/30"
                                  : "hover:bg-gray-50 dark:hover:bg-gray-800"
                                  }`}
                                onClick={() =>
                                  toggleAssignEmployeeSelection(emp.id)
                                }
                              >
                                <div className="flex items-center gap-2">
                                  <Avatar className="h-8 w-8">
                                    <AvatarImage src={emp.avatar} />
                                    <AvatarFallback>
                                      {emp.firstName[0]}
                                      {emp.lastName[0]}
                                    </AvatarFallback>
                                  </Avatar>
                                  <div className="flex flex-col">
                                    <span className="font-medium text-sm">
                                      {emp.firstName} {emp.lastName}
                                    </span>
                                    <span className="text-xs text-gray-500">
                                      {emp.email || "لا يوجد بريد"}
                                    </span>
                                  </div>
                                </div>
                                <div
                                  className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${assignEmployeesSelection.includes(emp.id)
                                    ? "bg-blue-600 border-blue-600 text-white"
                                    : "border-gray-300 dark:border-gray-600"
                                    }`}
                                >
                                  {assignEmployeesSelection.includes(
                                    emp.id,
                                  ) && <Plus className="h-3 w-3" />}
                                </div>
                              </div>
                            ))
                          ) : (
                            <div className="text-center py-4 text-gray-400 text-sm">
                              لا يوجد نتائج للبحث
                            </div>
                          )}
                        </div>
                      </div>

                      {assignEmployeesSelection.length > 0 && (
                        <div className="space-y-2">
                          <Label className="text-gray-700 dark:text-gray-300 text-sm">
                            الموظفون المحددون:
                          </Label>
                          <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto">
                            <div className="divide-y dark:divide-gray-700">
                              {assignEmployeesSelection.map((empId) => {
                                const emp = employees.find(
                                  (e) => e.id === empId,
                                );
                                if (!emp) return null;
                                return (
                                  <div
                                    key={empId}
                                    className="flex items-center justify-between p-2 bg-white dark:bg-gray-800"
                                  >
                                    <div className="flex items-center gap-2">
                                      <Avatar className="h-8 w-8">
                                        <AvatarImage src={emp.avatar} />
                                        <AvatarFallback className="text-xs bg-primary text-white">
                                          {emp.firstName?.[0]}
                                          {emp.lastName?.[0]}
                                        </AvatarFallback>
                                      </Avatar>
                                      <div>
                                        <div className="font-medium text-sm">
                                          {emp.firstName} {emp.lastName}
                                        </div>
                                        <div className="text-xs text-gray-500">
                                          {emp.email}
                                        </div>
                                      </div>
                                    </div>
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      className="h-8 w-8 text-red-500 hover:text-red-700"
                                      onClick={() =>
                                        toggleAssignEmployeeSelection(empId)
                                      }
                                    >
                                      <X className="h-4 w-4" />
                                    </Button>
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        </div>
                      )}

                      <div className="flex flex-col sm:flex-row gap-2 justify-end pt-2">
                        <Button
                          variant="outline"
                          onClick={() => {
                            setIsAddingEmployees(false);
                            resetAssignEmployeeSelection();
                          }}
                        >
                          إلغاء
                        </Button>
                        <Button
                          onClick={handleAssignEmployees}
                          className="gap-2"
                          disabled={isAssigningEmployees}
                        >
                          {isAssigningEmployees ? (
                            <>
                              <div className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full" />
                              جاري الإضافة...
                            </>
                          ) : (
                            <>
                              <UserPlus className="h-4 w-4" />
                              إضافة الموظفين
                            </>
                          )}
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                )}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="text-gray-900 dark:text-white">
              تأكيد الحذف
            </DialogTitle>
          </DialogHeader>
          <DialogDescription className="py-4 text-gray-700 dark:text-gray-300">
            هل أنت متأكد من حذف قسم "{selectedDepartment?.name}"؟
            {selectedDepartment?._count.users &&
              selectedDepartment._count.users > 0 && (
                <span className="block text-red-500 text-sm mt-2">
                  ⚠️ هذا القسم يحتوي على {selectedDepartment._count.users} موظف
                </span>
              )}
          </DialogDescription>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowDeleteDialog(false)}
            >
              إلغاء
            </Button>
            <Button variant="destructive" onClick={handleDeleteDepartment}>
              حذف
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Remove Employee Confirmation */}
      <Dialog open={showRemoveConfirm} onOpenChange={setShowRemoveConfirm}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>تأكيد إزالة الموظف</DialogTitle>
            <DialogDescription>
              هل أنت متأكد من رغبتك في إزالة هذا الموظف من القسم؟ لن يتم حذف
              الموظف من النظام، بل سيصبح بدون قسم فقط.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="flex gap-2 sm:justify-start">
            <Button
              variant="destructive"
              onClick={confirmRemoveFromDepartment}
              className="px-6"
            >
              إزالة الآن
            </Button>
            <Button
              variant="outline"
              onClick={() => {
                setShowRemoveConfirm(false);
                setEmployeeToRemove(null);
              }}
            >
              إلغاء
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Departments;

import React, { useState, useEffect } from "react";
import {
  FileText,
  Upload,
  Download,
  Trash2,
  CheckCircle,
  XCircle,
  Calendar,
  AlertCircle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Badge } from "../../components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "../../components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { useParams, useNavigate } from "react-router-dom";
import api from "../../services/api";
import { toast } from "sonner";

interface Document {
  id: string;
  name: string;
  type: string;
  fileUrl: string;
  fileSize?: number;
  expiryDate?: string;
  isVerified: boolean;
  verifiedAt?: string;
  createdAt: string;
}

const Documents: React.FC = () => {
  const { employeeId } = useParams<{ employeeId?: string }>();
  const navigate = useNavigate();
  const [documents, setDocuments] = useState<Document[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploadDialog, setUploadDialog] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    type: "other",
    expiryDate: "",
    notes: "",
  });

  useEffect(() => {
    if (employeeId) {
      fetchDocuments();
    }
  }, [employeeId]);

  const fetchDocuments = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/hr/documents/employee/${employeeId}`);
      setDocuments(response.data.documents || []);
    } catch (error) {
      console.error("Error fetching documents:", error);
      toast.error("فشل في جلب المستندات");
    } finally {
      setLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setSelectedFile(e.target.files[0]);
      if (!formData.name) {
        setFormData({ ...formData, name: e.target.files[0].name });
      }
    }
  };

  const handleUpload = async () => {
    if (!selectedFile || !employeeId) {
      toast.error("الرجاء اختيار ملف");
      return;
    }

    try {
      const uploadFormData = new FormData();
      uploadFormData.append("file", selectedFile);
      uploadFormData.append("employeeId", employeeId);
      uploadFormData.append("name", formData.name);
      uploadFormData.append("type", formData.type);
      if (formData.expiryDate)
        uploadFormData.append("expiryDate", formData.expiryDate);
      if (formData.notes) uploadFormData.append("notes", formData.notes);

      await api.post("/hr/documents", uploadFormData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      toast.success("تم رفع المستند بنجاح");
      setUploadDialog(false);
      setSelectedFile(null);
      setFormData({ name: "", type: "other", expiryDate: "", notes: "" });
      fetchDocuments();
    } catch (error: any) {
      console.error("Error uploading document:", error);
      toast.error(error.response?.data?.error || "فشل في رفع المستند");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا المستند؟")) return;

    try {
      await api.delete(`/hr/documents/${id}`);
      toast.success("تم حذف المستند بنجاح");
      fetchDocuments();
    } catch (error) {
      console.error("Error deleting document:", error);
      toast.error("فشل في حذف المستند");
    }
  };

  const handleVerify = async (id: string) => {
    try {
      await api.post(`/hr/documents/${id}/verify`);
      toast.success("تم التحقق من المستند");
      fetchDocuments();
    } catch (error) {
      console.error("Error verifying document:", error);
      toast.error("فشل في التحقق من المستند");
    }
  };

  const formatFileSize = (bytes?: number) => {
    if (!bytes) return "-";
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + " KB";
    return (bytes / (1024 * 1024)).toFixed(2) + " MB";
  };

  const isExpired = (expiryDate?: string) => {
    if (!expiryDate) return false;
    return new Date(expiryDate) < new Date();
  };

  const isExpiringSoon = (expiryDate?: string) => {
    if (!expiryDate) return false;
    const daysUntilExpiry = Math.ceil(
      (new Date(expiryDate).getTime() - new Date().getTime()) /
        (1000 * 60 * 60 * 24),
    );
    return daysUntilExpiry <= 30 && daysUntilExpiry > 0;
  };

  if (!employeeId) {
    return (
      <div className="p-6" dir="rtl">
        <Card>
          <CardContent className="p-6 text-center">
            <p className="text-gray-500">الرجاء اختيار موظف لعرض مستنداته</p>
            <Button onClick={() => navigate("/hr/employees")} className="mt-4">
              العودة إلى الموظفين
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">مستندات الموظف</h1>
          <p className="text-gray-500 mt-1">إدارة مستندات الموظف</p>
        </div>
        <Button onClick={() => setUploadDialog(true)}>
          <Upload className="h-4 w-4 ml-2" />
          رفع مستند
        </Button>
      </div>

      {loading ? (
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
        </div>
      ) : documents.length === 0 ? (
        <Card>
          <CardContent className="p-12 text-center">
            <FileText className="h-16 w-16 mx-auto mb-4 text-gray-400" />
            <p className="text-gray-500 mb-4">لا توجد مستندات</p>
            <Button onClick={() => setUploadDialog(true)}>
              <Upload className="h-4 w-4 ml-2" />
              رفع أول مستند
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {documents.map((doc) => (
            <Card
              key={doc.id}
              className={isExpired(doc.expiryDate) ? "border-red-500" : ""}
            >
              <CardHeader>
                <div className="flex items-center justify-between">
                  <FileText className="h-8 w-8 text-blue-500" />
                  <div className="flex gap-2">
                    {doc.isVerified ? (
                      <CheckCircle className="h-5 w-5 text-green-500" />
                    ) : (
                      <XCircle className="h-5 w-5 text-gray-400" />
                    )}
                  </div>
                </div>
                <CardTitle className="text-lg">{doc.name}</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-sm">
                    <span className="text-gray-500">النوع:</span>
                    <Badge>{doc.type}</Badge>
                  </div>
                  <div className="flex items-center justify-between text-sm">
                    <span className="text-gray-500">الحجم:</span>
                    <span>{formatFileSize(doc.fileSize)}</span>
                  </div>
                  {doc.expiryDate && (
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-500">تاريخ الانتهاء:</span>
                      <div className="flex items-center gap-2">
                        {isExpired(doc.expiryDate) && (
                          <AlertCircle className="h-4 w-4 text-red-500" />
                        )}
                        {isExpiringSoon(doc.expiryDate) &&
                          !isExpired(doc.expiryDate) && (
                            <AlertCircle className="h-4 w-4 text-yellow-500" />
                          )}
                        <span
                          className={
                            isExpired(doc.expiryDate) ? "text-red-500" : ""
                          }
                        >
                          {new Date(doc.expiryDate).toLocaleDateString("ar-EG")}
                        </span>
                      </div>
                    </div>
                  )}
                  <div className="flex gap-2 mt-4">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => window.open(doc.fileUrl, "_blank")}
                      className="flex-1"
                    >
                      <Download className="h-4 w-4 ml-2" />
                      تحميل
                    </Button>
                    {!doc.isVerified && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleVerify(doc.id)}
                        className="flex-1"
                      >
                        <CheckCircle className="h-4 w-4 ml-2" />
                        تحقق
                      </Button>
                    )}
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleDelete(doc.id)}
                      className="text-red-500"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Upload Dialog */}
      <Dialog open={uploadDialog} onOpenChange={setUploadDialog}>
        <DialogContent className="sm:max-w-md" dir="rtl">
          <DialogHeader>
            <DialogTitle>رفع مستند جديد</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>الملف</Label>
              <Input
                type="file"
                onChange={handleFileChange}
                accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"
              />
            </div>
            <div>
              <Label>اسم المستند</Label>
              <Input
                value={formData.name}
                onChange={(e) =>
                  setFormData({ ...formData, name: e.target.value })
                }
                placeholder="اسم المستند"
              />
            </div>
            <div>
              <Label>نوع المستند</Label>
              <Select
                value={formData.type}
                onValueChange={(value) =>
                  setFormData({ ...formData, type: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="contract">عقد عمل</SelectItem>
                  <SelectItem value="id">هوية/جواز سفر</SelectItem>
                  <SelectItem value="certificate">شهادة</SelectItem>
                  <SelectItem value="medical">طبي</SelectItem>
                  <SelectItem value="other">أخرى</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>تاريخ الانتهاء (اختياري)</Label>
              <Input
                type="date"
                value={formData.expiryDate}
                onChange={(e) =>
                  setFormData({ ...formData, expiryDate: e.target.value })
                }
              />
            </div>
            <div>
              <Label>ملاحظات (اختياري)</Label>
              <Input
                value={formData.notes}
                onChange={(e) =>
                  setFormData({ ...formData, notes: e.target.value })
                }
                placeholder="ملاحظات"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setUploadDialog(false)}>
              إلغاء
            </Button>
            <Button onClick={handleUpload}>رفع</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Documents;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useForm, Controller } from "react-hook-form";
import { toast } from "sonner";
import {
  Save,
  ArrowRight,
  ArrowLeft,
  TrendingUp,
  Briefcase,
  Calendar,
  DollarSign,
  User as UserIcon,
  AlertCircle,
  CheckCircle2,
} from "lucide-react";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Label } from "../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Badge } from "../../components/ui/badge";
import { Separator } from "../../components/ui/separator";
import { Alert, AlertDescription, AlertTitle } from "../../components/ui/alert";

// Types
type PromotionFormData = {
  employeeId: string;
  fromPositionId?: string;
  fromPositionName?: string;
  toPositionId: string;
  toPositionName?: string;
  fromSalary?: number;
  toSalary?: number;
  promotionDate: string;
  effectiveDate: string;
  reason: string;
  notes?: string;
  status: string;
};

const EditPromotion: React.FC = () => {
  console.log("🚀 [DEBUG] EditPromotion component rendering");
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [employees, setEmployees] = useState<any[]>([]);
  const [positions, setPositions] = useState<any[]>([]); // We might want to pick from existing positions
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);
  const [promotion, setPromotion] = useState<any>(null);

  const {
    register,
    handleSubmit,
    control,
    watch,
    setValue,
    formState: { errors },
  } = useForm<PromotionFormData>({
    defaultValues: {
      employeeId: "",
      fromPositionId: "none",
      fromPositionName: "",
      toPositionId: "",
      toPositionName: "",
      fromSalary: undefined,
      toSalary: undefined,
      promotionDate: "",
      effectiveDate: "",
      reason: "",
      notes: "",
      status: "PENDING",
    },
  });

  const watchedEmployeeId = watch("employeeId");
  const watchedToSalary = watch("toSalary");
  const watchedFromSalary = watch("fromSalary");

  // Fetch initial data
  useEffect(() => {
    const fetchData = async () => {
      console.log("🚀 [DEBUG] EditPromotion fetchData starting for ID:", id);
      try {
        setLoading(true);

        // Fetch Employees
        const empRes = await api.get("/hr/employees");
        const employeesData =
          empRes.data.employees ||
          empRes.data.data ||
          (Array.isArray(empRes.data) ? empRes.data : []);
        setEmployees(employeesData);

        // Fetch Promotion
        const promoRes = await api.get(`/hr/promotions/${id}`);
        const promotionData = promoRes.data.promotion || promoRes.data;

        console.log("📊 [EDIT-PROMOTION] Data:", promotionData);

        if (!promotionData || typeof promotionData !== "object") {
          throw new Error("بيانات الترقية غير صالحة");
        }

        setPromotion(promotionData);

        // Initialize form values
        setValue(
          "employeeId",
          promotionData.userId || promotionData.employeeId || "",
        );
        setValue("fromPositionId", promotionData.fromPositionId || "none");
        setValue("toPositionId", promotionData.toPositionId || "");
        setValue("fromPositionName", promotionData.fromPositionName || "");
        setValue("toPositionName", promotionData.toPositionName || "");
        setValue(
          "fromSalary",
          promotionData.fromSalary != null
            ? Number(promotionData.fromSalary)
            : undefined,
        );
        setValue(
          "toSalary",
          promotionData.toSalary != null
            ? Number(promotionData.toSalary)
            : undefined,
        );
        setValue(
          "promotionDate",
          promotionData.promotionDate
            ? String(promotionData.promotionDate).split("T")[0]
            : "",
        );
        setValue(
          "effectiveDate",
          promotionData.effectiveDate
            ? String(promotionData.effectiveDate).split("T")[0]
            : "",
        );
        setValue("reason", promotionData.reason || "");
        setValue("notes", promotionData.notes || "");
        setValue("status", promotionData.status || "PENDING"); // Ensure status is set

        // Get initial position names if hidden
        if (promotionData.fromPositionId && employeesData.length > 0) {
          // Find employee to get their current position if needed
          const emp = employeesData.find(
            (e: any) =>
              e.id === (promotionData.userId || promotionData.employeeId),
          );
          if (emp) {
            setSelectedEmployee(emp);
          }
        }

        // Fetch Positions (Optional, for autocomplete)
        try {
          const posRes = await api.get("/hr/positions");
          setPositions(posRes.data.positions || []);
        } catch (e) {
          console.warn("Could not fetch positions", e);
        }
      } catch (error: any) {
        console.error("❌ [EDIT-PROMOTION] Error fetching:", error);
        const errorMessage =
          error.response?.data?.error ||
          error.response?.data?.message ||
          error.message ||
          "فشل في تحميل بيانات الترقية";
        toast.error(errorMessage);
        // navigate('/hr/promotions'); // Optional: redirect on error
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchData();
    }
  }, [id, setValue]);

  // Update selected employee details when employeeId changes
  useEffect(() => {
    if (watchedEmployeeId && employees.length > 0) {
      const emp = employees.find((e) => e.id === watchedEmployeeId);
      setSelectedEmployee(emp || null);

      // NOTE: We only auto-fill FROM details if it's a NEW selection or first load logic handled elsewhere.
      // But since this is EDIT, we should be careful not to overwrite what's in the DB unless the user explicitely changes the employee.
      // In this case, if the user changes the employee ID from the original one, we might want to update the "From" fields.
      // But usually, you don't change the employee on an edit page. You delete and create new.
      // However, we allow it.

      if (promotion && watchedEmployeeId !== promotion.userId) {
        // User changed the employee, so let's pre-fill from current data
        if (emp) {
          setValue("fromPositionName", emp.position?.title || "");
          setValue("fromPositionId", emp.position?.id || "none");
          setValue(
            "fromSalary",
            emp.baseSalary ? Number(emp.baseSalary) : undefined,
          );
        }
      }
    }
  }, [watchedEmployeeId, employees, promotion, setValue]);

  const calculateIncrease = () => {
    if (!watchedFromSalary || !watchedToSalary) return null;
    const diff = Number(watchedToSalary) - Number(watchedFromSalary);
    const percent = (diff / Number(watchedFromSalary)) * 100;
    return { diff, percent };
  };

  const increaseStats = calculateIncrease();

  const onSubmit = async (data: PromotionFormData) => {
    try {
      setSaving(true);

      if (!data.employeeId) {
        toast.error("يجب اختيار الموظف");
        return;
      }

      if (!data.toPositionName) {
        toast.error("يجب كتابة المنصب الجديد");
        return;
      }

      // Create payload
      const payload = {
        ...data,
        // Ensure numbers and handle 0 correctly
        fromSalary:
          data.fromSalary !== undefined && data.fromSalary !== null
            ? Number(data.fromSalary)
            : undefined,
        toSalary:
          data.toSalary !== undefined && data.toSalary !== null
            ? Number(data.toSalary)
            : undefined,
      };

      console.log(
        "🚀 [EDIT-PROMOTION] Submitting payload:",
        JSON.stringify(payload, null, 2),
      );
      const response = await api.put(`/hr/promotions/${id}`, payload);
      console.log("✅ [EDIT-PROMOTION] Success response:", response.data);
      toast.success("تم تحديث الترقية بنجاح");
      navigate("/hr/promotions");
    } catch (error: any) {
      console.error("❌ Error updating promotion:", error);
      const errorMessage =
        error.response?.data?.error ||
        error.response?.data?.message ||
        "فشل في تحديث الترقية";
      toast.error(errorMessage);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!promotion) {
    return (
      <div className="p-8 text-center">
        <h2 className="text-2xl font-bold text-gray-700">الترقية غير موجودة</h2>
        <Button onClick={() => navigate("/hr/promotions")} className="mt-4">
          العودة للقائمة
        </Button>
      </div>
    );
  }

  return (
    <div className="p-6 w-full max-w-7xl mx-auto space-y-8" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate("/hr/promotions")}
            className="rounded-full hover:bg-gray-100"
          >
            <ArrowRight className="h-6 w-6 text-gray-600" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
              <TrendingUp className="h-8 w-8 text-blue-600" />
              تعديل ترقية
            </h1>
            <p className="text-gray-500 mt-1">
              تحديث بيانات الترقية وتعديل الحالة
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <Badge
            variant={
              promotion.status === "APPROVED"
                ? "default"
                : promotion.status === "REJECTED"
                  ? "destructive"
                  : "secondary"
            }
            className="text-lg px-4 py-1"
          >
            {promotion.status === "APPROVED"
              ? "تمت الموافقة"
              : promotion.status === "REJECTED"
                ? "مرفوضة"
                : "قيد المراجعة"}
          </Badge>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Right Column: Employee Card & Summary */}
        <div className="space-y-6">
          <Card className="border-t-4 border-t-blue-500 shadow-md">
            <CardHeader className="pb-4">
              <CardTitle>الموظف المعني</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label>اختر الموظف</Label>
                  <Controller
                    name="employeeId"
                    control={control}
                    render={({ field }) => (
                      <Select
                        onValueChange={field.onChange}
                        value={field.value}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="اختر الموظف" />
                        </SelectTrigger>
                        <SelectContent>
                          {employees.map((emp) => (
                            <SelectItem key={emp.id} value={emp.id}>
                              {emp.firstName} {emp.lastName}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                </div>

                {selectedEmployee && (
                  <div className="bg-gray-50 p-4 rounded-xl flex items-center gap-4 mt-4 border border-gray-100">
                    <Avatar className="h-16 w-16 border-2 border-white shadow-sm">
                      <AvatarImage src={selectedEmployee.avatar} />
                      <AvatarFallback className="bg-blue-100 text-blue-600 text-xl font-bold">
                        {selectedEmployee.firstName?.[0]}
                        {selectedEmployee.lastName?.[0]}
                      </AvatarFallback>
                    </Avatar>
                    <div>
                      <h3 className="font-bold text-lg text-gray-900">
                        {selectedEmployee.firstName} {selectedEmployee.lastName}
                      </h3>
                      <p className="text-sm text-gray-500">
                        {selectedEmployee.employeeNumber}
                      </p>
                      <Badge variant="outline" className="mt-1 bg-white">
                        {selectedEmployee.position?.title || "بدون منصب"}
                      </Badge>
                    </div>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {increaseStats && (
            <Card className="bg-gradient-to-br from-green-50 to-emerald-50 border-green-200">
              <CardContent className="p-6">
                <h3 className="text-green-800 font-semibold mb-2 flex items-center gap-2">
                  <DollarSign className="h-5 w-5" />
                  تحليل الراتب
                </h3>
                <div className="space-y-1">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-600">الزيادة المقترحة:</span>
                    <span className="font-bold text-green-700 dir-ltr">
                      +{increaseStats.diff.toLocaleString()}
                    </span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-600">نسبة الزيادة:</span>
                    <span className="font-bold text-green-700 dir-ltr">
                      {increaseStats.percent.toFixed(2)}%
                    </span>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Left Column: Promotion Details */}
        <div className="lg:col-span-2 space-y-6">
          <form onSubmit={handleSubmit(onSubmit)}>
            <Card className="shadow-md overflow-hidden">
              <div className="bg-gray-50/50 p-6 border-b">
                <h2 className="text-xl font-semibold flex items-center gap-2 text-gray-800">
                  <Briefcase className="h-5 w-5 text-gray-500" />
                  تفاصيل الحركة الوظيفية
                </h2>
              </div>

              <CardContent className="p-6 space-y-8">
                {/* Movement Visualizer */}
                <div className="grid grid-cols-1 md:grid-cols-11 gap-4 items-center bg-slate-50 p-6 rounded-xl border border-slate-100">
                  {/* From */}
                  <div className="md:col-span-5 space-y-4">
                    <div className="space-y-2">
                      <Label className="text-gray-500 text-xs uppercase tracking-wide">
                        المنصب الحالي
                      </Label>
                      <Input
                        {...register("fromPositionName")}
                        placeholder="اسم المنصب الحالي"
                        className="bg-white border-slate-200 focus-visible:ring-slate-400 font-medium"
                      />
                    </div>
                    <div className="space-y-2 relative">
                      <Label className="text-gray-500 text-xs uppercase tracking-wide">
                        الراتب الحالي
                      </Label>
                      <div className="relative">
                        <DollarSign className="absolute right-3 top-2.5 h-4 w-4 text-gray-400" />
                        <Input
                          type="number"
                          {...register("fromSalary", { valueAsNumber: true })}
                          placeholder="0.00"
                          className="pr-9 bg-white border-slate-200"
                        />
                      </div>
                    </div>
                  </div>

                  {/* Arrow */}
                  <div className="md:col-span-1 flex justify-center py-4 md:py-0">
                    <div className="bg-blue-100 p-2 rounded-full text-blue-600">
                      <ArrowLeft className="h-6 w-6" />
                    </div>
                  </div>

                  {/* To */}
                  <div className="md:col-span-5 space-y-4">
                    <div className="space-y-2">
                      <Label className="text-blue-600 text-xs uppercase tracking-wide font-bold">
                        المنصب الجديد
                      </Label>
                      <Input
                        {...register("toPositionName", {
                          required: "المنصب الجديد مطلوب",
                        })}
                        placeholder="اسم المنصب الجديد"
                        className="bg-blue-50/50 border-blue-200 focus-visible:ring-blue-400 font-medium text-blue-900"
                      />
                      {errors.toPositionName && (
                        <p className="text-xs text-red-500">
                          {errors.toPositionName.message}
                        </p>
                      )}
                    </div>
                    <div className="space-y-2 relative">
                      <Label className="text-blue-600 text-xs uppercase tracking-wide font-bold">
                        الراتب الجديد
                      </Label>
                      <div className="relative">
                        <DollarSign className="absolute right-3 top-2.5 h-4 w-4 text-blue-500" />
                        <Input
                          type="number"
                          {...register("toSalary", { valueAsNumber: true })}
                          placeholder="0.00"
                          className="pr-9 bg-blue-50/50 border-blue-200 text-blue-900 font-bold"
                        />
                      </div>
                    </div>
                  </div>
                </div>

                <Separator />

                {/* Dates & Status */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <Label className="flex items-center gap-2">
                      <Calendar className="h-4 w-4 text-gray-500" />
                      تاريخ الترقية
                    </Label>
                    <Input
                      type="date"
                      {...register("promotionDate", { required: "مطلوب" })}
                    />
                    {errors.promotionDate && (
                      <p className="text-xs text-red-500">
                        {errors.promotionDate.message}
                      </p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <Label className="flex items-center gap-2">
                      <Calendar className="h-4 w-4 text-gray-500" />
                      تاريخ السريان
                    </Label>
                    <Input
                      type="date"
                      {...register("effectiveDate", { required: "مطلوب" })}
                    />
                    {errors.effectiveDate && (
                      <p className="text-xs text-red-500">
                        {errors.effectiveDate.message}
                      </p>
                    )}
                  </div>

                  <div className="space-y-2 md:col-span-2">
                    <Label>حالة الطلب</Label>
                    <Controller
                      name="status"
                      control={control}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          value={field.value}
                        >
                          <SelectTrigger>
                            <SelectValue placeholder="حالة الطلب" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="PENDING">
                              معلق (قيد المراجعة)
                            </SelectItem>
                            <SelectItem value="APPROVED">موافق عليه</SelectItem>
                            <SelectItem value="REJECTED">مرفوض</SelectItem>
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label>سبب الترقية / المبررات</Label>
                  <Textarea
                    {...register("reason", { required: "مطلوب" })}
                    className="min-h-[100px]"
                    placeholder="اشرح أسباب الترقية بالتفصيل..."
                  />
                  {errors.reason && (
                    <p className="text-xs text-red-500">
                      {errors.reason.message}
                    </p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label>ملاحظات إضافية</Label>
                  <Textarea
                    {...register("notes")}
                    className="min-h-[80px]"
                    placeholder="أي ملاحظات أخرى..."
                  />
                </div>
              </CardContent>
            </Card>

            <div className="flex justify-end gap-3 mt-6">
              <Button
                type="button"
                variant="outline"
                size="lg"
                onClick={() => navigate("/hr/promotions")}
              >
                إلغاء
              </Button>
              <Button
                type="submit"
                size="lg"
                className="min-w-[150px]"
                disabled={saving}
              >
                {saving ? (
                  "جاري الحفظ..."
                ) : (
                  <>
                    <Save className="ml-2 h-4 w-4" />
                    حفظ التعديلات
                  </>
                )}
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default EditPromotion;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { AlertTriangle, ArrowRight, Save, Eye, ShieldAlert, FileText, Calendar, Gavel } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Textarea } from "../../components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog";
import api from "../../services/api";
import { toast } from "sonner";

interface Warning {
  id: string;
  type: string;
  severity: string;
  title: string;
  description: string;
  incidentDate: string;
  actionTaken?: string;
  employeeResponse?: string;
  acknowledgedAt?: string;
  employee: {
    firstName: string;
    lastName: string;
  };
}

const EditWarning: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    type: "WRITTEN",
    severity: "moderate",
    incidentDate: "",
    actionTaken: "",
    employeeResponse: "",
  });
  const [showPreview, setShowPreview] = useState(false);
  const [warningData, setWarningData] = useState<any>(null);

  useEffect(() => {
    if (id) {
      fetchWarning();
    }
  }, [id]);

  const fetchWarning = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/hr/warnings/${id}`);
      const warning = response.data.warning;

      setFormData({
        title: warning.title || "",
        description: warning.description || "",
        type: warning.type || "WRITTEN",
        severity: warning.severity || "moderate",
        incidentDate: warning.incidentDate
          ? new Date(warning.incidentDate).toISOString().split("T")[0]
          : "",
        actionTaken: warning.actionTaken || "",
        employeeResponse: warning.employeeResponse || "",
      });
      setWarningData(warning);
    } catch (error: any) {
      console.error("Error fetching warning:", error);
      toast.error(error.response?.data?.error || "فشل في جلب بيانات الإنذار");
      navigate("/hr/warnings");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title.trim() || !formData.description.trim()) {
      toast.error("الرجاء ملء جميع الحقول المطلوبة");
      return;
    }

    try {
      setSaving(true);
      await api.put(`/hr/warnings/${id}`, formData);
      toast.success("تم تحديث الإنذار بنجاح");
      navigate(`/hr/warnings/${id}`);
    } catch (error: any) {
      console.error("Error updating warning:", error);
      toast.error(error.response?.data?.error || "فشل في تحديث الإنذار");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="outline"
            onClick={() => navigate(`/hr/warnings/${id}`)}
          >
            <ArrowRight className="h-4 w-4 ml-2" />
            العودة
          </Button>
          <div>
            <h1 className="text-3xl font-bold">تعديل الإنذار</h1>
            <p className="text-gray-500 mt-1">تحديث معلومات الإنذار</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-orange-500" />
              معلومات الإنذار
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label htmlFor="title">العنوان *</Label>
                <Input
                  id="title"
                  value={formData.title}
                  onChange={(e) =>
                    setFormData({ ...formData, title: e.target.value })
                  }
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="incidentDate">تاريخ الحادث *</Label>
                <Input
                  id="incidentDate"
                  type="date"
                  value={formData.incidentDate}
                  onChange={(e) =>
                    setFormData({ ...formData, incidentDate: e.target.value })
                  }
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="type">نوع الإنذار *</Label>
                <Select
                  value={formData.type}
                  onValueChange={(value) =>
                    setFormData({ ...formData, type: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="VERBAL">شفوي</SelectItem>
                    <SelectItem value="WRITTEN">كتابي</SelectItem>
                    <SelectItem value="FINAL">نهائي</SelectItem>
                    <SelectItem value="TERMINATION">إنهاء خدمة</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="severity">الشدة *</Label>
                <Select
                  value={formData.severity}
                  onValueChange={(value) =>
                    setFormData({ ...formData, severity: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="minor">خفيف</SelectItem>
                    <SelectItem value="moderate">متوسط</SelectItem>
                    <SelectItem value="severe">شديد</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">الوصف *</Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) =>
                  setFormData({ ...formData, description: e.target.value })
                }
                rows={5}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="actionTaken">الإجراء المتخذ</Label>
              <Textarea
                id="actionTaken"
                value={formData.actionTaken}
                onChange={(e) =>
                  setFormData({ ...formData, actionTaken: e.target.value })
                }
                rows={4}
                placeholder="وصف الإجراء الذي تم اتخاذه..."
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="employeeResponse">رد الموظف</Label>
              <Textarea
                id="employeeResponse"
                value={formData.employeeResponse}
                onChange={(e) =>
                  setFormData({ ...formData, employeeResponse: e.target.value })
                }
                rows={4}
                placeholder="رد الموظف على الإنذار..."
              />
            </div>

            <div className="flex flex-col sm:flex-row justify-end gap-4 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => setShowPreview(true)}
                className="gap-2"
              >
                <Eye className="h-4 w-4" />
                معاينة
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={() => navigate(`/hr/warnings/${id}`)}
              >
                إلغاء
              </Button>
              <Button type="submit" disabled={saving}>
                {saving ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white ml-2"></div>
                    جاري الحفظ...
                  </>
                ) : (
                  <>
                    <Save className="h-4 w-4 ml-2" />
                    حفظ التغييرات
                  </>
                )}
              </Button>
            </div>
          </CardContent>
        </Card>
      </form>

      {/* Preview Modal */}
      <Dialog open={showPreview} onOpenChange={setShowPreview}>
        <DialogContent className="max-w-2xl bg-white dark:bg-gray-950 border-none shadow-2xl rounded-[2rem] p-0 overflow-hidden" dir="rtl">
          {/* Header with Background Pattern */}
          <div className="relative h-32 bg-gradient-to-r from-orange-600 to-amber-700 flex items-center px-8 overflow-hidden">
            <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#fff_1px,transparent_1px)] [background-size:20px_20px]" />
            <div className="absolute -right-10 -top-10 w-40 h-40 bg-white/10 rounded-full blur-3xl" />

            <div className="flex items-center gap-5 relative z-10 w-full">
              <div className="p-4 bg-white/20 rounded-[1.5rem] backdrop-blur-md shadow-inner ring-1 ring-white/30">
                <ShieldAlert className="h-8 w-8 text-white" />
              </div>
              <div className="space-y-1 flex-1 min-w-0">
                <DialogTitle className="text-2xl font-black text-white break-words pr-2 max-w-[450px]">
                  {formData.title || "عنوان الإنذار"}
                </DialogTitle>
                <div className="flex items-center gap-2 text-white/70 text-[10px] font-black uppercase tracking-widest">
                  <span className="bg-white/10 px-2 py-0.5 rounded-md backdrop-blur-sm">تعديل مسودة</span>
                  <span className="h-1 w-1 rounded-full bg-white/30" />
                  <span>{formData.type}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="p-8 space-y-8 max-h-[60vh] overflow-y-auto custom-scrollbar relative">
            {warningData?.employee && (
              <div className="flex items-center gap-4 p-5 bg-muted/30 rounded-[1.5rem] border border-muted ring-4 ring-muted/20">
                <div className="h-12 w-12 bg-primary/10 rounded-full flex items-center justify-center text-primary font-black border-2 border-white shadow-sm">
                  {warningData.employee.firstName?.[0]}
                </div>
                <div>
                  <p className="text-sm font-black text-gray-900 dark:text-white leading-none mb-1">
                    {warningData.employee.firstName} {warningData.employee.lastName}
                  </p>
                  <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest leading-none">
                    موظف مسجل • تحديث بيانات قائمة
                  </p>
                </div>
              </div>
            )}

            <div className="space-y-3">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 px-1">
                <FileText className="h-3.5 w-3.5" />
                تفاصيل المخالفة المعدلة
              </h4>
              <div className="relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-orange-500/10 to-transparent rounded-3xl blur opacity-25" />
                <div className="relative bg-white dark:bg-gray-900/50 p-7 rounded-[1.5rem] border border-gray-100 dark:border-gray-800 shadow-sm leading-relaxed whitespace-pre-wrap break-words text-gray-700 dark:text-gray-200 text-lg font-medium">
                  {formData.description || "لا يوجد وصف مدخل..."}
                </div>
              </div>
            </div>

            {formData.actionTaken && (
              <div className="space-y-3">
                <h4 className="text-[10px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-widest flex items-center gap-2 px-1">
                  <Gavel className="h-3.5 w-3.5" />
                  الإجراء الإداري المحدث
                </h4>
                <div className="bg-amber-500/5 dark:bg-amber-500/10 p-6 rounded-[1.5rem] border border-amber-500/10 shadow-sm border-dashed">
                  <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap break-words text-md leading-relaxed">
                    {formData.actionTaken}
                  </p>
                </div>
              </div>
            )}

            <div className="flex flex-wrap items-center gap-4 pt-6 border-t border-dashed border-muted font-bold text-xs text-muted-foreground">
              <div className="flex items-center gap-2 px-3 py-1.5 bg-muted/40 rounded-full">
                <Calendar className="h-3.5 w-3.5 text-orange-500" />
                <span>تاريخ الحادثة: {formData.incidentDate}</span>
              </div>
              <Badge variant="secondary" className="px-4 py-1.5 rounded-full bg-orange-500/10 text-orange-600 border-none">
                {formData.severity}
              </Badge>
            </div>
          </div>

          <div className="p-6 bg-muted/20 border-t border-muted/30 flex justify-end">
            <Button
              onClick={() => setShowPreview(false)}
              className="rounded-xl px-10 h-12 font-black text-xs uppercase tracking-widest shadow-lg shadow-orange-500/20 bg-orange-600 hover:bg-orange-700"
            >
              العودة للتعديل
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default EditWarning;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  User,
  Mail,
  Phone,
  MapPin,
  Calendar,
  Briefcase,
  Building2,
  DollarSign,
  Clock,
  FileText,
  Award,
  AlertTriangle,
  GraduationCap,
  Edit,
  ArrowRight,
  UserCircle,
  CreditCard,
  Heart,
  ShieldHalf,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../components/ui/tabs";
import { Progress } from "../../components/ui/progress";
import api from "../../services/api";
import { toast } from "sonner";

interface Employee {
  id: string;
  employeeNumber: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  mobile: string;
  avatar: string;
  dateOfBirth: string;
  gender: string;
  maritalStatus: string;
  nationalId: string;
  address: string;
  city: string;
  country: string;
  hireDate: string;
  probationEndDate: string;
  contractType: string;
  contractEndDate: string;
  status: string;
  baseSalary: number;
  annualLeaveBalance: number;
  sickLeaveBalance: number;
  bankName: string;
  bankAccountNumber: string;
  bankIban: string;
  emergencyContactName: string;
  emergencyContactPhone: string;
  emergencyContactRelation: string;
  enableAutoDeduction: boolean;
  monthlyGraceMinutes: number;
  maxDailyLateMinutes: number;
  lateDeductionRate: number;
  department: { id: string; name: string; color: string } | null;
  position: { id: string; title: string; level: number } | null;
  manager: {
    id: string;
    firstName: string;
    lastName: string;
    avatar: string;
  } | null;
  subordinates: any[];
  employeeDocuments: any[];
  leaveRequests: any[];
  attendance: any[];
}

const statusLabels: Record<string, { label: string; color: string }> = {
  ACTIVE: { label: "نشط", color: "bg-green-100 text-green-800" },
  ON_LEAVE: { label: "في إجازة", color: "bg-yellow-100 text-yellow-800" },
  SUSPENDED: { label: "موقوف", color: "bg-red-100 text-red-800" },
  TERMINATED: { label: "منتهي", color: "bg-gray-100 text-gray-800" },
  RESIGNED: { label: "مستقيل", color: "bg-orange-100 text-orange-800" },
};

const contractLabels: Record<string, string> = {
  FULL_TIME: "دوام كامل",
  PART_TIME: "دوام جزئي",
  CONTRACT: "عقد",
  TEMPORARY: "مؤقت",
  INTERNSHIP: "تدريب",
  FREELANCE: "حر",
};

const genderLabels: Record<string, string> = {
  MALE: "ذكر",
  FEMALE: "أنثى",
};

const maritalLabels: Record<string, string> = {
  SINGLE: "أعزب",
  MARRIED: "متزوج",
  DIVORCED: "مطلق",
  WIDOWED: "أرمل",
};

const EmployeeDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [employee, setEmployee] = useState<Employee | null>(null);
  const [activeTab, setActiveTab] = useState("overview");

  useEffect(() => {
    if (id) {
      fetchEmployee();
    }
  }, [id]);

  const fetchEmployee = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/hr/employees/${id}`);
      setEmployee(response.data.employee);
    } catch (error) {
      console.error("Error fetching employee:", error);
      toast.error("حدث خطأ أثناء جلب بيانات الموظف");
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  const calculateAge = (dateOfBirth: string) => {
    const today = new Date();
    const birthDate = new Date(dateOfBirth);
    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();
    if (
      monthDiff < 0 ||
      (monthDiff === 0 && today.getDate() < birthDate.getDate())
    ) {
      age--;
    }
    return age;
  };

  const calculateTenure = (hireDate: string) => {
    const today = new Date();
    const hire = new Date(hireDate);
    const years = today.getFullYear() - hire.getFullYear();
    const months = today.getMonth() - hire.getMonth();

    if (years > 0) {
      return `${years} سنة${months > 0 ? ` و ${months} شهر` : ""}`;
    }
    return `${months} شهر`;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!employee) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-gray-500">
        <User className="h-16 w-16 mb-4 opacity-50" />
        <p className="text-xl">الموظف غير موجود</p>
        <Button variant="link" onClick={() => navigate("/hr/employees")}>
          العودة لقائمة الموظفين
        </Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" onClick={() => navigate("/hr/employees")}>
          <ArrowRight className="h-4 w-4" />
        </Button>
        <div className="flex-1">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            ملف الموظف
          </h1>
        </div>
        <Button
          variant="outline"
          onClick={() => navigate(`/hr/employees/${id}/edit`)}
        >
          <Edit className="h-4 w-4 ml-2" />
          تعديل
        </Button>
      </div>

      {/* Profile Card */}
      <Card>
        <CardContent className="p-6">
          <div className="flex flex-col md:flex-row gap-6">
            {/* Avatar & Basic Info */}
            <div className="flex flex-col items-center md:items-start gap-4">
              <Avatar className="h-32 w-32">
                <AvatarImage src={employee.avatar} />
                <AvatarFallback className="text-3xl">
                  {employee.firstName?.[0]}
                  {employee.lastName?.[0]}
                </AvatarFallback>
              </Avatar>
              <div className="text-center md:text-right">
                <h2 className="text-2xl font-bold">
                  {employee.firstName} {employee.lastName}
                </h2>
                <p className="text-gray-500">{employee.employeeNumber}</p>
                <Badge
                  className={`mt-2 ${statusLabels[employee.status]?.color || ""}`}
                >
                  {statusLabels[employee.status]?.label || employee.status}
                </Badge>
              </div>
            </div>

            {/* Quick Info */}
            <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <Building2 className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">القسم:</span>
                  <span className="font-medium">
                    {employee.department?.name || "-"}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <Briefcase className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">المنصب:</span>
                  <span className="font-medium">
                    {employee.position?.title || "-"}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <Calendar className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">تاريخ التعيين:</span>
                  <span className="font-medium">
                    {new Date(employee.hireDate).toLocaleDateString("ar-EG")}
                  </span>
                </div>
              </div>

              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <Mail className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">البريد:</span>
                  <span className="font-medium">{employee.email || "-"}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Phone className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">الهاتف:</span>
                  <span className="font-medium">
                    {employee.phone || employee.mobile || "-"}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <UserCircle className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">المدير:</span>
                  <span className="font-medium">
                    {employee.manager
                      ? `${employee.manager.firstName} ${employee.manager.lastName}`
                      : "-"}
                  </span>
                </div>
              </div>

              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">مدة الخدمة:</span>
                  <span className="font-medium">
                    {calculateTenure(employee.hireDate)}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <FileText className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">نوع العقد:</span>
                  <span className="font-medium">
                    {contractLabels[employee.contractType] ||
                      employee.contractType}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <DollarSign className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-600">الراتب:</span>
                  <span className="font-medium">
                    {formatCurrency(employee.baseSalary)}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid grid-cols-7 w-full max-w-3xl">
          <TabsTrigger value="overview">نظرة عامة</TabsTrigger>
          <TabsTrigger value="personal">البيانات الشخصية</TabsTrigger>
          <TabsTrigger value="attendance">الحضور</TabsTrigger>
          <TabsTrigger value="leaves">الإجازات</TabsTrigger>
          <TabsTrigger value="documents">المستندات</TabsTrigger>
          <TabsTrigger value="salary">سجل الرواتب</TabsTrigger>
          <TabsTrigger value="performance">الأداء</TabsTrigger>
        </TabsList>

        {/* Overview Tab */}
        <TabsContent value="overview" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Leave Balance */}
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500">
                  رصيد الإجازات السنوية
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-3xl font-bold text-blue-600">
                  {employee.annualLeaveBalance} يوم
                </div>
                <Progress
                  value={(employee.annualLeaveBalance / 21) * 100}
                  className="mt-2"
                />
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500">
                  رصيد الإجازات المرضية
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-3xl font-bold text-green-600">
                  {employee.sickLeaveBalance} يوم
                </div>
                <Progress
                  value={(employee.sickLeaveBalance / 15) * 100}
                  className="mt-2"
                />
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500">
                  أيام الحضور (هذا الشهر)
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-3xl font-bold text-purple-600">
                  {employee.attendance?.filter(
                    (a: any) => a.status === "PRESENT" || a.status === "LATE",
                  ).length || 0}
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500">
                  المرؤوسين
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-3xl font-bold text-orange-600">
                  {employee.subordinates?.length || 0}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Recent Activity */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Recent Attendance */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Clock className="h-5 w-5" />
                  آخر سجلات الحضور
                </CardTitle>
              </CardHeader>
              <CardContent>
                {employee.attendance?.length === 0 ? (
                  <p className="text-gray-500 text-center py-4">
                    لا توجد سجلات
                  </p>
                ) : (
                  <div className="space-y-3">
                    {employee.attendance
                      ?.slice(0, 5)
                      .map((att: any, index: number) => (
                        <div
                          key={index}
                          className="flex items-center justify-between p-2 bg-gray-50 rounded-lg"
                        >
                          <span className="text-sm">
                            {new Date(att.date).toLocaleDateString("ar-EG")}
                          </span>
                          <div className="flex items-center gap-2">
                            {att.checkIn && (
                              <span className="text-sm text-green-600">
                                {new Date(att.checkIn).toLocaleTimeString(
                                  "ar-EG",
                                  { hour: "2-digit", minute: "2-digit" },
                                )}
                              </span>
                            )}
                            {att.checkOut && (
                              <>
                                <span className="text-gray-400">-</span>
                                <span className="text-sm text-blue-600">
                                  {new Date(att.checkOut).toLocaleTimeString(
                                    "ar-EG",
                                    { hour: "2-digit", minute: "2-digit" },
                                  )}
                                </span>
                              </>
                            )}
                          </div>
                        </div>
                      ))}
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Recent Leave Requests */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Calendar className="h-5 w-5" />
                  آخر طلبات الإجازات
                </CardTitle>
              </CardHeader>
              <CardContent>
                {employee.leaveRequests?.length === 0 ? (
                  <p className="text-gray-500 text-center py-4">
                    لا توجد طلبات
                  </p>
                ) : (
                  <div className="space-y-3">
                    {employee.leaveRequests
                      ?.slice(0, 5)
                      .map((leave: any, index: number) => (
                        <div
                          key={index}
                          className="flex items-center justify-between p-2 bg-gray-50 rounded-lg"
                        >
                          <div>
                            <span className="text-sm font-medium">
                              {leave.type}
                            </span>
                            <span className="text-sm text-gray-500 mr-2">
                              ({leave.totalDays} يوم)
                            </span>
                          </div>
                          <Badge
                            variant={
                              leave.status === "APPROVED"
                                ? "default"
                                : "secondary"
                            }
                          >
                            {leave.status}
                          </Badge>
                        </div>
                      ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </div>

          {/* Subordinates */}
          {employee.subordinates && employee.subordinates.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <User className="h-5 w-5" />
                  المرؤوسين
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  {employee.subordinates.map((sub: any) => (
                    <div
                      key={sub.id}
                      className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg cursor-pointer hover:bg-gray-100"
                      onClick={() => navigate(`/hr/employees/${sub.id}`)}
                    >
                      <Avatar>
                        <AvatarImage src={sub.avatar} />
                        <AvatarFallback>
                          {sub.firstName?.[0]}
                          {sub.lastName?.[0]}
                        </AvatarFallback>
                      </Avatar>
                      <div>
                        <p className="font-medium text-sm">
                          {sub.firstName} {sub.lastName}
                        </p>
                        <p className="text-xs text-gray-500">
                          {sub.position?.title}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Deduction Settings Card */}
          <Card className="border-orange-100 bg-orange-50/20 dark:bg-orange-950/5">
            <CardHeader className="pb-3">
              <CardTitle className="text-xl flex items-center gap-2 text-orange-700 dark:text-orange-400">
                <ShieldHalf className="h-5 w-5" />
                سياسة الخصم والتأخير للموظف
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="space-y-1">
                  <p className="text-sm text-gray-500 font-medium">
                    حالة الخصم التلقائي
                  </p>
                  {employee.enableAutoDeduction !== false ? (
                    <Badge className="bg-green-100 text-green-800 border-green-200">
                      مفعل
                    </Badge>
                  ) : (
                    <Badge className="bg-red-100 text-red-800 border-red-200">
                      مستثنى (Whitelisted)
                    </Badge>
                  )}
                </div>
                <div className="space-y-1">
                  <p className="text-sm text-gray-500 font-medium">
                    رصيد المرونة الشهري
                  </p>
                  <p className="font-bold text-lg">
                    {employee.monthlyGraceMinutes ?? 60} دقيقة
                  </p>
                </div>
                <div className="space-y-1">
                  <p className="text-sm text-gray-500 font-medium">
                    حد التأخير اليومي
                  </p>
                  <p className="font-bold text-lg">
                    {employee.maxDailyLateMinutes ?? 10} دقائق
                  </p>
                </div>
                <div className="space-y-1">
                  <p className="text-sm text-gray-500 font-medium">
                    معدل الخصم للدقيقة
                  </p>
                  <p className="font-bold text-lg">
                    {employee.lateDeductionRate
                      ? `${employee.lateDeductionRate} جنيه`
                      : "حساب تلقائي"}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Personal Tab */}
        <TabsContent value="personal" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Personal Information */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <User className="h-5 w-5" />
                  المعلومات الشخصية
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-500">تاريخ الميلاد</p>
                    <p className="font-medium">
                      {employee.dateOfBirth
                        ? `${new Date(employee.dateOfBirth).toLocaleDateString("ar-EG")} (${calculateAge(employee.dateOfBirth)} سنة)`
                        : "-"}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">الجنس</p>
                    <p className="font-medium">
                      {genderLabels[employee.gender] || "-"}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">الحالة الاجتماعية</p>
                    <p className="font-medium">
                      {maritalLabels[employee.maritalStatus] || "-"}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">رقم الهوية</p>
                    <p className="font-medium">{employee.nationalId || "-"}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Contact Information */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Phone className="h-5 w-5" />
                  معلومات الاتصال
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-500">البريد الإلكتروني</p>
                    <p className="font-medium">{employee.email || "-"}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">الهاتف</p>
                    <p className="font-medium">{employee.phone || "-"}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">الجوال</p>
                    <p className="font-medium">{employee.mobile || "-"}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Address */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <MapPin className="h-5 w-5" />
                  العنوان
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <p className="text-sm text-gray-500">العنوان</p>
                    <p className="font-medium">{employee.address || "-"}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">المدينة</p>
                    <p className="font-medium">{employee.city || "-"}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">الدولة</p>
                    <p className="font-medium">{employee.country || "-"}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Emergency Contact */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Heart className="h-5 w-5" />
                  جهة اتصال الطوارئ
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-500">الاسم</p>
                    <p className="font-medium">
                      {employee.emergencyContactName || "-"}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">الهاتف</p>
                    <p className="font-medium">
                      {employee.emergencyContactPhone || "-"}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">صلة القرابة</p>
                    <p className="font-medium">
                      {employee.emergencyContactRelation || "-"}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Bank Information */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <CreditCard className="h-5 w-5" />
                  المعلومات البنكية
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-500">اسم البنك</p>
                    <p className="font-medium">{employee.bankName || "-"}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">رقم الحساب</p>
                    <p className="font-medium">
                      {employee.bankAccountNumber || "-"}
                    </p>
                  </div>
                  <div className="col-span-2">
                    <p className="text-sm text-gray-500">IBAN</p>
                    <p className="font-medium">{employee.bankIban || "-"}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        {/* Attendance Tab */}
        <TabsContent value="attendance">
          <Card>
            <CardHeader>
              <CardTitle>سجل الحضور</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-gray-500 text-center py-8">
                سيتم عرض سجل الحضور التفصيلي هنا
              </p>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Leaves Tab */}
        <TabsContent value="leaves">
          <Card>
            <CardHeader>
              <CardTitle>سجل الإجازات</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-gray-500 text-center py-8">
                سيتم عرض سجل الإجازات التفصيلي هنا
              </p>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Documents Tab */}
        <TabsContent value="documents">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>المستندات</CardTitle>
                <Button
                  onClick={() => navigate(`/hr/documents/${employee.id}`)}
                >
                  <FileText className="h-4 w-4 ml-2" />
                  إدارة المستندات
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              {employee.employeeDocuments?.length === 0 ? (
                <div className="text-center py-8">
                  <p className="text-gray-500 mb-4">لا توجد مستندات</p>
                  <Button
                    onClick={() => navigate(`/hr/documents/${employee.id}`)}
                  >
                    <FileText className="h-4 w-4 ml-2" />
                    إضافة مستند
                  </Button>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {employee.employeeDocuments?.map((doc: any) => (
                    <div
                      key={doc.id}
                      className="flex items-center gap-3 p-4 border rounded-lg"
                    >
                      <FileText className="h-8 w-8 text-blue-500" />
                      <div>
                        <p className="font-medium">{doc.title}</p>
                        <p className="text-sm text-gray-500">{doc.type}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Salary History Tab */}
        <TabsContent value="salary">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>سجل الرواتب</CardTitle>
                <Button
                  onClick={() => navigate(`/hr/salary-history/${employee.id}`)}
                >
                  <DollarSign className="h-4 w-4 ml-2" />
                  عرض السجل الكامل
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="text-center py-8">
                <p className="text-gray-500 mb-4">
                  عرض سجل التغييرات في الراتب
                </p>
                <Button
                  onClick={() => navigate(`/hr/salary-history/${employee.id}`)}
                >
                  <DollarSign className="h-4 w-4 ml-2" />
                  عرض سجل الرواتب
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Performance Tab */}
        <TabsContent value="performance">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>تقييمات الأداء</CardTitle>
                <Button
                  onClick={() =>
                    navigate(
                      `/hr/performance-reviews?employeeId=${employee.id}`,
                    )
                  }
                >
                  <Award className="h-4 w-4 ml-2" />
                  عرض جميع التقييمات
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="text-center py-8">
                <p className="text-gray-500 mb-4">عرض تقييمات الأداء للموظف</p>
                <Button
                  onClick={() =>
                    navigate(
                      `/hr/performance-reviews?employeeId=${employee.id}`,
                    )
                  }
                >
                  <Award className="h-4 w-4 ml-2" />
                  عرض التقييمات
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default EmployeeDetails;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useForm, Controller } from "react-hook-form";
import { toast } from "sonner";
import { Save, ArrowRight, User, Shield, DollarSign } from "lucide-react";
import api from "../../services/api";

import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";

type EmployeeFormData = {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  employeeNumber: string;
  departmentId: string;
  positionId: string;
  hireDate: string;
  contractType: string;
  baseSalary: number;
};

const EmployeeEdit: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [departments, setDepartments] = useState<any[]>([]);
  const [positions, setPositions] = useState<any[]>([]);

  const {
    register,
    handleSubmit,
    control,
    formState: { errors },
    reset,
  } = useForm<EmployeeFormData>({
    defaultValues: {
      firstName: "",
      lastName: "",
      email: "",
      phone: "",
      employeeNumber: "",
      departmentId: "",
      positionId: "",
      hireDate: "",
      contractType: "FULL_TIME",
      baseSalary: 0,
    },
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);

        // جلب بيانات الموظف
        const empRes = await api.get(`/hr/employees/${id}`);
        const employee = empRes.data.employee || empRes.data;

        // جلب الأقسام
        const deptRes = await api.get("/hr/departments");
        setDepartments(deptRes.data.departments || []);

        // جلب المناصب
        const posRes = await api.get("/hr/positions");
        setPositions(posRes.data.positions || posRes.data || []);

        // تعبئة النموذج
        reset({
          firstName: employee.firstName || "",
          lastName: employee.lastName || "",
          email: employee.email || "",
          phone: employee.phone || "",
          employeeNumber: employee.employeeNumber || "",
          departmentId: employee.departmentId || employee.department?.id || "",
          positionId: employee.positionId || employee.position?.id || "",
          hireDate: employee.hireDate
            ? new Date(employee.hireDate).toISOString().split("T")[0]
            : "",
          contractType: employee.contractType || "FULL_TIME",
          baseSalary: employee.baseSalary ? Number(employee.baseSalary) : 0,
        });
      } catch (error: any) {
        console.error("❌ Error fetching employee data:", error);
        toast.error("فشل في تحميل بيانات الموظف");
        navigate("/hr/employees");
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchData();
    }
  }, [id, navigate, reset]);

  const onSubmit = async (data: EmployeeFormData) => {
    try {
      setSaving(true);

      // تنظيف البيانات
      const payload = {
        ...data,
        baseSalary: Number(data.baseSalary),
      };

      console.log("🔍 [EMPLOYEE-UPDATE] Submitting employee update:", {
        employeeId: id,
        payload: payload,
        originalSalary: data.baseSalary,
        convertedSalary: Number(data.baseSalary),
      });

      const response = await api.put(`/hr/employees/${id}`, payload);

      console.log("✅ [EMPLOYEE-UPDATE] Update successful:", {
        status: response.status,
        data: response.data,
      });

      toast.success("تم تحديث بيانات الموظف بنجاح");
      navigate(`/hr/employees/${id}`);
    } catch (error: any) {
      console.error("❌ [EMPLOYEE-UPDATE] Error updating employee:", {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status,
        employeeId: id,
      });
      const errorMessage =
        error.response?.data?.error || "فشل في تحديث بيانات الموظف";
      toast.error(errorMessage);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="p-6 w-full space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => navigate(-1)}>
            <ArrowRight className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <User className="h-8 w-8 text-blue-500" />
              تعديل بيانات الموظف
            </h1>
            <p className="text-gray-500 mt-1">
              تحديث ملف الموظف والإعدادات الخاصة به
            </p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Basic Info */}
          <div className="lg:col-span-2 space-y-6">
            <Card>
              <CardHeader>
                <CardTitle className="text-xl flex items-center gap-2">
                  <User className="h-5 w-5 text-gray-400" />
                  المعلومات الأساسية
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>الاسم الأول *</Label>
                    <Input
                      {...register("firstName", {
                        required: "الاسم الأول مطلوب",
                      })}
                    />
                    {errors.firstName && (
                      <p className="text-sm text-red-500">
                        {errors.firstName.message}
                      </p>
                    )}
                  </div>
                  <div className="space-y-2">
                    <Label>الاسم الأخير *</Label>
                    <Input
                      {...register("lastName", {
                        required: "الاسم الأخير مطلوب",
                      })}
                    />
                    {errors.lastName && (
                      <p className="text-sm text-red-500">
                        {errors.lastName.message}
                      </p>
                    )}
                  </div>
                  <div className="space-y-2">
                    <Label>البريد الإلكتروني</Label>
                    <Input type="email" {...register("email")} />
                  </div>
                  <div className="space-y-2">
                    <Label>رقم الهاتف</Label>
                    <Input {...register("phone")} />
                  </div>
                  <div className="space-y-2">
                    <Label>رقم الموظف</Label>
                    <Input {...register("employeeNumber")} />
                  </div>
                  <div className="space-y-2">
                    <Label>تاريخ التعيين</Label>
                    <Input type="date" {...register("hireDate")} />
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="text-xl flex items-center gap-2">
                  <Shield className="h-5 w-5 text-gray-400" />
                  الوظيفة والراتب
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>القسم</Label>
                    <Controller
                      name="departmentId"
                      control={control}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          value={field.value}
                        >
                          <SelectTrigger>
                            <SelectValue placeholder="اختر القسم" />
                          </SelectTrigger>
                          <SelectContent>
                            {departments.map((dept) => (
                              <SelectItem key={dept.id} value={dept.id}>
                                {dept.name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>المنصب</Label>
                    <Controller
                      name="positionId"
                      control={control}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          value={field.value}
                        >
                          <SelectTrigger>
                            <SelectValue placeholder="اختر المنصب" />
                          </SelectTrigger>
                          <SelectContent>
                            {positions.map((pos) => (
                              <SelectItem key={pos.id} value={pos.id}>
                                {pos.title}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>نوع العقد</Label>
                    <Controller
                      name="contractType"
                      control={control}
                      render={({ field }) => (
                        <Select
                          onValueChange={field.onChange}
                          value={field.value}
                        >
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="FULL_TIME">دوام كامل</SelectItem>
                            <SelectItem value="PART_TIME">دوام جزئي</SelectItem>
                            <SelectItem value="CONTRACT">عقد</SelectItem>
                            <SelectItem value="TEMPORARY">مؤقت</SelectItem>
                            <SelectItem value="INTERNSHIP">تدريب</SelectItem>
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>الراتب الأساسي</Label>
                    <div className="relative">
                      <Input
                        type="number"
                        step="0.01"
                        {...register("baseSalary")}
                        className="pl-10"
                      />
                      <DollarSign className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Actions Sidebar */}
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle className="text-xl">إجراءات</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex flex-col gap-3">
                  <Button
                    type="submit"
                    disabled={saving}
                    size="lg"
                    className="w-full"
                  >
                    {saving ? (
                      "جاري الحفظ..."
                    ) : (
                      <>
                        <Save className="h-4 w-4 ml-2" />
                        حفظ جميع التغييرات
                      </>
                    )}
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => navigate(-1)}
                    className="w-full"
                  >
                    إلغاء
                  </Button>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </form>
    </div>
  );
};

export default EmployeeEdit;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  Users,
  Plus,
  Search,
  MoreVertical,
  Edit,
  Trash2,
  Eye,
  Download,
  Upload,
  Loader2,
  Clock,
  Shield,
} from "lucide-react";
import { Card, CardContent } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Badge } from "../../components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Switch } from "../../components/ui/switch";
import { Separator } from "../../components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../../components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "../../components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import { Label } from "../../components/ui/label";
import { Textarea } from "../../components/ui/textarea";
import { useNavigate } from "react-router-dom";
import api from "../../services/api";
import { toast } from "sonner";
import {
  validateEmployeeData,
  getErrorMessage,
  hasError,
  ValidationError,
} from "../../utils/hrValidation";
import { EmployeeTableSkeleton } from "../../components/hr/SkeletonLoader";
import { EmptyState } from "../../components/hr/EmptyState";
import { EnhancedPagination } from "../../components/hr/EnhancedPagination";
import { useDebounce } from "../../hooks/useDebounce";

interface Employee {
  id: string;
  userId?: string | null;
  employeeNumber: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  avatar: string;
  status: string;
  contractType: string;
  hireDate: string;
  department: { id: string; name: string; color: string } | null;
  position: { id: string; title: string; level: number } | null;
  manager: {
    id: string;
    firstName: string;
    lastName: string;
    avatar: string;
  } | null;
  // ✅ User (HR Integration) data
  user: {
    id: string;
    email: string;
    role: string;
    isActive: boolean;
    isEmailVerified: boolean;
    lastLoginAt: string | null;
    createdAt: string;
  } | null;
}

interface Department {
  id: string;
  name: string;
}

const statusColors: Record<string, string> = {
  ACTIVE: "bg-green-100 text-green-800",
  ON_LEAVE: "bg-yellow-100 text-yellow-800",
  SUSPENDED: "bg-red-100 text-red-800",
  TERMINATED: "bg-gray-100 text-gray-800",
  RESIGNED: "bg-orange-100 text-orange-800",
};

const contractKeys: Record<string, string> = {
  FULL_TIME: "contractFullTime",
  PART_TIME: "contractPartTime",
  CONTRACT: "contractContract",
  CONTRACTOR: "contractContract",
  TEMPORARY: "contractTemporary",
  INTERNSHIP: "contractInternship",
  INTERN: "contractInternship",
  FREELANCE: "contractFreelance",
};

const statusKeys: Record<string, string> = {
  ACTIVE: "statusActive",
  ON_LEAVE: "statusOnLeave",
  SUSPENDED: "statusSuspended",
  TERMINATED: "statusTerminated",
  RESIGNED: "statusResigned",
};

const Employees: React.FC = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0,
  });

  // Filters
  const [searchInput, setSearchInput] = useState("");
  const debouncedSearch = useDebounce(searchInput, 500);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [departmentFilter, setDepartmentFilter] = useState("");
  const [contractFilter, setContractFilter] = useState("");
  const [userStatusFilter, setUserStatusFilter] = useState(""); // ✅ Add User Status filter

  // Dialog states
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [errors, setErrors] = useState<ValidationError[]>([]);
  const [assetsDialog, setAssetsDialog] = useState<{
    open: boolean;
    employeeName: string;
    assets: any[];
    loading: boolean;
    error: string;
  }>({ open: false, employeeName: "", assets: [], loading: false, error: "" });

  // Form state
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    mobile: "",
    password: "", // User field
    role: "AGENT", // User field
    departmentId: "",
    positionId: "",
    hireDate: new Date().toISOString().split("T")[0],
    contractType: "FULL_TIME",
    baseSalary: "",
    nationalId: "",
    dateOfBirth: "",
    gender: "",
    address: "",
    city: "",
    country: "Egypt",
    // Deduction settings
    enableAutoDeduction: true,
    monthlyGraceMinutes: 60,
    maxDailyLateMinutes: 10,
    lateDeductionRate: "",
  });

  useEffect(() => {
    setSearch(debouncedSearch);
  }, [debouncedSearch]);

  useEffect(() => {
    fetchEmployees();
    fetchDepartments();
  }, [
    pagination.page,
    search,
    statusFilter,
    departmentFilter,
    contractFilter,
    userStatusFilter,
  ]);

  const fetchEmployees = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
      });

      if (search) params.append("search", search);
      if (statusFilter && statusFilter !== "all")
        params.append("status", statusFilter);
      if (departmentFilter && departmentFilter !== "all")
        params.append("departmentId", departmentFilter);
      if (contractFilter && contractFilter !== "all")
        params.append("contractType", contractFilter);
      if (userStatusFilter && userStatusFilter !== "all")
        params.append("userStatus", userStatusFilter); // ✅ Add User Status filter

      const response = await api.get(`/hr/employees?${params}`);
      setEmployees(response.data.employees);
      setPagination((prev) => ({
        ...prev,
        total: response.data.pagination.total,
        totalPages: response.data.pagination.totalPages,
      }));
    } catch (error) {
      console.error("Error fetching employees:", error);
      toast.error(t("employees.errorFetchEmployees"));
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartments = async () => {
    try {
      const response = await api.get("/hr/departments");
      setDepartments(response.data.departments);
    } catch (error) {
      console.error("Error fetching departments:", error);
    }
  };

  const openAssetsDialog = async (emp: Employee) => {
    setAssetsDialog({
      open: true,
      employeeName: `${emp.firstName} ${emp.lastName}`,
      assets: [],
      loading: true,
      error: "",
    });
    try {
      const res = await api.get("/hr/assets", {
        params: { assignedTo: emp.userId || emp.id },
      });
      if (res.data.success) {
        setAssetsDialog((prev) => ({
          ...prev,
          assets: res.data.data || [],
          loading: false,
        }));
      } else {
        setAssetsDialog((prev) => ({
          ...prev,
          error: res.data.message || "فشل في تحميل العهدة",
          loading: false,
        }));
      }
    } catch (err: any) {
      setAssetsDialog((prev) => ({
        ...prev,
        error: err.response?.data?.message || "فشل في تحميل العهدة",
        loading: false,
      }));
    }
  };

  const handleAddEmployee = async () => {
    // Frontend Validation
    const result = validateEmployeeData(formData);
    if (!result.isValid) {
      setErrors(result.errors);
      toast.error(t("employees.errorFormValidation"));
      return;
    }

    // Check if email is already being used in the current list
    const emailExists = employees.some(
      (emp) =>
        emp.email && emp.email.toLowerCase() === formData.email.toLowerCase(),
    );

    if (emailExists) {
      toast.error(t("employees.errorEmailExists"));
      return;
    }

    try {
      setSubmitting(true);
      setErrors([]);
      await api.post("/hr/employees", formData);
      toast.success(t("employees.successAdd"));
      setShowAddDialog(false);
      resetForm();
      fetchEmployees();
    } catch (error: any) {
      console.error("❌ Frontend error creating employee:", error);
      console.error("❌ Error response:", error.response);
      console.error(
        "❌ Error response data:",
        JSON.stringify(error.response?.data, null, 2),
      );

      let errorMsg =
        error.response?.data?.error ||
        error.response?.data?.message ||
        t("employees.errorAdd");

      // Handle specific error codes
      if (error.response?.status === 409) {
        errorMsg = error.response?.data?.error || t("employees.errorEmployeeExists");
      } else if (error.response?.status === 400) {
        errorMsg = error.response?.data?.error || t("employees.errorInvalidData");

        // Show validation errors if available
        if (
          error.response?.data?.errors &&
          Array.isArray(error.response.data.errors)
        ) {
          const errorMessages = error.response.data.errors
            .map((e: any) => e.message)
            .join(", ");
          errorMsg = errorMessages || errorMsg;
        }
      }

      toast.error(errorMsg);

      // Handle backend validation errors
      if (error.response?.data?.errors) {
        setErrors(error.response.data.errors);
      }
    } finally {
      setSubmitting(false);
    }
  };

  const handleDeleteEmployee = async (employeeToDelete: Employee) => {
    const confirmed = window.confirm(
      `سيتم حذف الموظف "${employeeToDelete.firstName} ${employeeToDelete.lastName}" من الشركة.\nاضغط موافق للمتابعة.`,
    );
    if (!confirmed) return;

    const previousEmployees = employees;
    const previousPagination = pagination;

    try {
      setDeleting(true);

      setEmployees((prev) =>
        prev.filter((emp) => emp.id !== employeeToDelete.id),
      );
      setPagination((prev) => ({
        ...prev,
        total: Math.max(0, prev.total - 1),
      }));

      await api.delete(`/hr/employees/${employeeToDelete.id}`, {
        data: {
          // الخلفية ما زالت تتطلب رمز التأكيد، نرسله تلقائياً.
          confirmationText: "DELETE",
        },
        headers: {
          // نرسل التأكيد أيضاً في الهيدر تحسباً لأي قيود بارسر على DELETE body
          "x-confirm-delete-employee": "DELETE",
        },
      });
      toast.success(t("employees.successDelete"));
      fetchEmployees();
    } catch (error: any) {
      setEmployees(previousEmployees);
      setPagination(previousPagination);
      toast.error(error.response?.data?.error || t("employees.errorDelete"));
    } finally {
      setDeleting(false);
    }
  };

  const resetForm = () => {
    setFormData({
      firstName: "",
      lastName: "",
      email: "",
      phone: "",
      mobile: "",
      password: "", // User field
      role: "AGENT", // User field
      departmentId: "",
      positionId: "",
      hireDate: new Date().toISOString().split("T")[0],
      contractType: "FULL_TIME",
      baseSalary: "",
      nationalId: "",
      dateOfBirth: "",
      gender: "",
      address: "",
      city: "",
      country: "Egypt",
      enableAutoDeduction: true,
      monthlyGraceMinutes: 60,
      maxDailyLateMinutes: 10,
      lateDeductionRate: "",
    });
    setErrors([]);
  };

  return (
    <div
      className="p-6 space-y-6 bg-gray-50 dark:bg-gray-900 min-h-screen"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            {t("employees.pageTitle")}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("employees.pageSubtitle")}
          </p>
        </div>
        <div className="flex gap-3">
          <Button
            onClick={() => setShowAddDialog(true)}
            className="bg-blue-600 dark:bg-blue-700 hover:bg-blue-700 dark:hover:bg-blue-800"
          >
            <Plus className="h-4 w-4 ml-2" />
            {t("employees.addEmployee")}
          </Button>
          <Button
            variant="outline"
            className="border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800"
          >
            <Upload className="h-4 w-4 ml-2" />
            {t("employees.import")}
          </Button>
          <Button
            variant="outline"
            className="border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800"
          >
            <Download className="h-4 w-4 ml-2" />
            {t("employees.export")}
          </Button>
        </div>
      </div>

      {/* Filters */}
      <Card className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700">
        <CardContent className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
            <div className="relative">
              <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500 h-4 w-4" />
              <Input
                placeholder={t("employees.searchPlaceholder")}
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                className="pr-10 bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
              />
            </div>
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white">
                <SelectValue placeholder={t("employees.statusFilter")} />
              </SelectTrigger>
              <SelectContent className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700">
                <SelectItem
                  value="all"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.allStatuses")}
                </SelectItem>
                <SelectItem
                  value="ACTIVE"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.active")}
                </SelectItem>
                <SelectItem
                  value="INACTIVE"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.inactive")}
                </SelectItem>
                <SelectItem
                  value="TERMINATED"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.terminated")}
                </SelectItem>
              </SelectContent>
            </Select>

            <Select
              value={departmentFilter}
              onValueChange={setDepartmentFilter}
            >
              <SelectTrigger className="bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white">
                <SelectValue placeholder={t("employees.departmentFilter")} />
              </SelectTrigger>
              <SelectContent className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700">
                <SelectItem
                  value="all"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.allDepartments")}
                </SelectItem>
                {departments.map((dept) => (
                  <SelectItem
                    key={dept.id}
                    value={dept.id}
                    className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                  >
                    {dept.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Select value={contractFilter} onValueChange={setContractFilter}>
              <SelectTrigger className="bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white">
                <SelectValue placeholder={t("employees.contractFilter")} />
              </SelectTrigger>
              <SelectContent className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700">
                <SelectItem
                  value="all"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.allContracts")}
                </SelectItem>
                <SelectItem
                  value="FULL_TIME"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.fullTime")}
                </SelectItem>
                <SelectItem
                  value="PART_TIME"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.partTime")}
                </SelectItem>
                <SelectItem
                  value="CONTRACTOR"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.contractor")}
                </SelectItem>
                <SelectItem
                  value="INTERN"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.intern")}
                </SelectItem>
              </SelectContent>
            </Select>

            {/* ✅ User Status Filter */}
            <Select
              value={userStatusFilter}
              onValueChange={setUserStatusFilter}
            >
              <SelectTrigger className="bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white">
                <SelectValue placeholder={t("employees.accountStatusFilter")} />
              </SelectTrigger>
              <SelectContent className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700">
                <SelectItem
                  value="all"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.allAccounts")}
                </SelectItem>
                <SelectItem
                  value="HAS_USER"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.hasAccount")}
                </SelectItem>
                <SelectItem
                  value="NO_USER"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.noAccount")}
                </SelectItem>
                <SelectItem
                  value="ACTIVE_USER"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.activeAccount")}
                </SelectItem>
                <SelectItem
                  value="INACTIVE_USER"
                  className="text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  {t("employees.inactiveAccount")}
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Employees Table */}
      <Card className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700">
        <CardContent className="p-0">
          {loading ? (
            <EmployeeTableSkeleton />
          ) : employees.length === 0 ? (
            <EmptyState
              icon={Users}
              title={t("employees.noEmployees")}
              description={t("employees.noEmployeesDesc")}
              actionLabel={t("employees.addFirstEmployee")}
              onAction={() => setShowAddDialog(true)}
              secondaryActionLabel={t("employees.importFromExcel")}
              secondaryIcon={Upload}
            />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-right">{t("employees.tableEmployee")}</TableHead>
                  <TableHead className="text-right">{t("employees.tableDepartment")}</TableHead>
                  <TableHead className="text-right">{t("employees.tablePosition")}</TableHead>
                  <TableHead className="text-right">{t("employees.tableUserAccount")}</TableHead>
                  <TableHead className="text-right">{t("employees.tableRole")}</TableHead>
                  <TableHead className="text-right">{t("employees.tableContractType")}</TableHead>
                  <TableHead className="text-right">{t("employees.tableHireDate")}</TableHead>
                  <TableHead className="text-right">{t("employees.tableStatus")}</TableHead>
                  <TableHead className="text-right">{t("employees.tableActions")}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {employees.map((employee) => (
                  <TableRow
                    key={employee.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-800"
                  >
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar>
                          {employee.avatar ? (
                            <AvatarImage
                              src={
                                employee.avatar.startsWith("http")
                                  ? employee.avatar
                                  : `https://mokhtarelhenawy.online${employee.avatar}`
                              }
                              onError={(e) => {
                                e.currentTarget.src = `https://ui-avatars.com/api/?name=${employee.firstName}+${employee.lastName}&background=random`;
                              }}
                            />
                          ) : (
                            <AvatarFallback>
                              {employee.firstName?.[0]}
                              {employee.lastName?.[0]}
                            </AvatarFallback>
                          )}
                        </Avatar>
                        <div>
                          <p className="font-medium">
                            {employee.firstName || t("employees.notSpecified")}{" "}
                            {employee.lastName || ""}
                          </p>
                          <p className="text-sm text-gray-500">
                            {employee.employeeNumber || t("employees.notSpecified")}
                          </p>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      {employee.department ? (
                        <div className="flex items-center gap-2">
                          <div
                            className="w-2 h-2 rounded-full"
                            style={{
                              backgroundColor:
                                employee.department.color || "#6B7280",
                            }}
                          />
                          {employee.department.name || t("employees.notSpecified")}
                        </div>
                      ) : (
                        <span className="text-gray-400">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {employee.position?.title || (
                        <span className="text-gray-400">-</span>
                      )}
                    </TableCell>
                    {/* ✅ User Account Status */}
                    <TableCell>
                      {employee.user ? (
                        <div className="flex flex-col gap-1">
                          <div className="flex items-center gap-2">
                            <Badge
                              className={
                                employee.user.isActive
                                  ? "bg-green-100 text-green-800"
                                  : "bg-gray-100 text-gray-800"
                              }
                            >
                              {employee.user.isActive ? t("employees.accountActive") : t("employees.accountInactive")}
                            </Badge>
                            {employee.user.isEmailVerified && (
                              <Badge className="bg-blue-100 text-blue-800 text-xs">
                                {t("employees.verified")}
                              </Badge>
                            )}
                          </div>
                          {employee.user.lastLoginAt && (
                            <span className="text-xs text-gray-500">
                              {t("employees.lastLogin")}{" "}
                              {new Date(
                                employee.user.lastLoginAt,
                              ).toLocaleDateString("ar-EG")}
