              ) : (
                t("employees.addEmployeeButton")
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Employees;

import React, { useState, useEffect } from "react";
import {
  TrendingUp,
  Plus,
  Calendar,
  Briefcase,
  Trash2,
  Edit,
  Search,
  CheckCircle2,
  XCircle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Input } from "../../components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "../../components/ui/alert-dialog";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { useNavigate } from "react-router-dom";
import api from "../../services/api";
import { toast } from "sonner";

interface Promotion {
  id: string;
  employeeId: string;
  fromPositionId?: string;
  toPositionId: string;
  fromPositionName?: string;
  toPositionName: string;
  fromSalary?: number | string;
  toSalary?: number | string;
  promotionDate: string;
  effectiveDate: string;
  reason: string;
  approvedBy?: string;
  status: "PENDING" | "APPROVED" | "REJECTED" | "COMPLETED";
  employee?: {
    firstName: string;
    lastName: string;
    employeeNumber: string;
    avatar?: string;
  };
  user?: {
    firstName: string;
    lastName: string;
    employeeNumber: string;
    avatar?: string;
  };
  fromPosition?: {
    id: string;
    title: string;
  } | null;
  toPosition: {
    id: string;
    title: string;
  };
}

const EmployeesPromotion: React.FC = () => {
  const navigate = useNavigate();
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [filteredPromotions, setFilteredPromotions] = useState<Promotion[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [sortBy, setSortBy] = useState<string>("promotionDate");

  useEffect(() => {
    fetchPromotions();
  }, []);

  useEffect(() => {
    // Filter promotions based on search term and status
    // Safe check: if promotions is not an array, don't try to filter/sort
    if (!Array.isArray(promotions)) {
      console.warn(
        "⚠️ [PROMOTIONS] promotions state is not an array:",
        promotions,
      );
      return;
    }

    let filtered = [...promotions]; // Use a copy to avoid mutation

    // Filter by search term
    if (searchTerm) {
      filtered = filtered.filter((promotion) => {
        const userObj = promotion?.user || promotion?.employee;
        const firstName = userObj?.firstName || "";
        const lastName = userObj?.lastName || "";
        const employeeName = `${firstName} ${lastName}`.trim().toLowerCase();
        const fromPos = promotion.fromPositionName?.toLowerCase() || "";
        const toPos = promotion.toPositionName?.toLowerCase() || "";
        const reason = promotion.reason?.toLowerCase() || "";

        return (
          employeeName.includes(searchTerm.toLowerCase()) ||
          fromPos.includes(searchTerm.toLowerCase()) ||
          toPos.includes(searchTerm.toLowerCase()) ||
          reason.includes(searchTerm.toLowerCase())
        );
      });
    }

    // Filter by status
    if (statusFilter !== "all") {
      filtered = filtered.filter(
        (promotion) => promotion.status === statusFilter,
      );
    }

    // Sort promotions
    filtered.sort((a, b) => {
      const userA = a?.user || a?.employee;
      const userB = b?.user || b?.employee;

      switch (sortBy) {
        case "promotionDate":
          return (
            new Date(b.promotionDate).getTime() -
            new Date(a.promotionDate).getTime()
          );
        case "employeeName":
          const nameA = `${userA?.firstName || ""} ${userA?.lastName || ""}`
            .trim()
            .toLowerCase();
          const nameB = `${userB?.firstName || ""} ${userB?.lastName || ""}`
            .trim()
            .toLowerCase();
          return nameA.localeCompare(nameB);
        case "toPosition":
          return (a.toPositionName || "").localeCompare(b.toPositionName || "");
        default:
          return 0;
      }
    });

    setFilteredPromotions(filtered);
  }, [promotions, searchTerm, statusFilter, sortBy]);

  const fetchPromotions = async () => {
    try {
      setLoading(true);
      const response = await api.get("/hr/promotions");
      console.log("📊 [PROMOTIONS] API Response:", response.data);

      // Safe extraction of promotions array
      let fetchedPromotions = [];
      if (
        response.data &&
        response.data.promotions &&
        Array.isArray(response.data.promotions)
      ) {
        fetchedPromotions = response.data.promotions;
      } else if (Array.isArray(response.data)) {
        fetchedPromotions = response.data;
      } else if (
        response.data &&
        response.data.data &&
        Array.isArray(response.data.data)
      ) {
        fetchedPromotions = response.data.data;
      }

      setPromotions(fetchedPromotions);
    } catch (error: any) {
      console.error("❌ [PROMOTIONS] Error fetching:", error);
      const errorMessage =
        error.response?.data?.error ||
        error.response?.data?.message ||
        error.message ||
        "فشل في جلب الترقيات";
      toast.error(errorMessage);
      setPromotions([]);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (
    promotionId: string,
    status: string,
    rejectionReason?: string,
  ) => {
    try {
      const response = await api.put(`/hr/promotions/${promotionId}`, {
        status,
        rejectionReason,
      });
      if (response.data.success) {
        toast.success(
          status === "APPROVED"
            ? "تم اعتماد الترقية بنجاح وتحديث ملف الموظف"
            : "تم رفض الترقية",
        );
        fetchPromotions();
      } else {
        toast.error(response.data.error || "فشل في تحديث حالة الترقية");
      }
    } catch (error: any) {
      console.error("❌ Error updating status:", error);
      toast.error(error.response?.data?.error || "حدث خطأ أثناء التحديث");
    }
  };

  const handleDeletePromotion = async (promotionId: string) => {
    try {
      const response = await api.delete(`/hr/promotions/${promotionId}`);
      if (response.data.success) {
        toast.success("تم حذف الترقية بنجاح");
        fetchPromotions(); // إعادة تحميل القائمة
      } else {
        toast.error(response.data.error || "فشل في حذف الترقية");
      }
    } catch (error: any) {
      console.error("❌ Error deleting promotion:", error);
      const errorMessage =
        error.response?.data?.error ||
        error.response?.data?.message ||
        error.message ||
        "فشل في حذف الترقية";
      toast.error(errorMessage);
    }
  };

  const getStatusLabel = (status: string) => {
    const statusMap: Record<string, { label: string; color: string }> = {
      PENDING: {
        label: "قيد المراجعة",
        color: "bg-yellow-100 text-yellow-800",
      },
      APPROVED: { label: "موافق عليها", color: "bg-green-100 text-green-800" },
      REJECTED: { label: "مرفوضة", color: "bg-red-100 text-red-800" },
      COMPLETED: { label: "مكتملة", color: "bg-blue-100 text-blue-800" },
    };
    return (
      statusMap[status] || { label: status, color: "bg-gray-100 text-gray-800" }
    );
  };

  // Calculate statistics
  const stats = {
    total: promotions.length,
    pending: promotions.filter((p) => p.status === "PENDING").length,
    approved: promotions.filter((p) => p.status === "APPROVED").length,
    rejected: promotions.filter((p) => p.status === "REJECTED").length,
    completed: promotions.filter((p) => p.status === "COMPLETED").length,
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">ترقيات الموظفين</h1>
          <p className="text-gray-500 mt-1">
            إدارة ترقيات الموظفين والترقي الوظيفي
          </p>
        </div>
        <Button onClick={() => navigate("/hr/promotions/new")}>
          <Plus className="h-4 w-4 ml-2" />
          ترقية جديدة
        </Button>
      </div>

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-gray-900">
              {stats.total}
            </div>
            <div className="text-sm text-gray-500">إجمالي الترقيات</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-yellow-600">
              {stats.pending}
            </div>
            <div className="text-sm text-gray-500">قيد المراجعة</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-green-600">
              {stats.approved}
            </div>
            <div className="text-sm text-gray-500">موافق عليها</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-red-600">
              {stats.rejected}
            </div>
            <div className="text-sm text-gray-500">مرفوضة</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-blue-600">
              {stats.completed}
            </div>
            <div className="text-sm text-gray-500">مكتملة</div>
          </CardContent>
        </Card>
      </div>

      {/* Search and Filter Controls */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="flex-1">
          <div className="relative">
            <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              placeholder="بحث بالاسم، المنصب، أو السبب..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pr-10"
            />
          </div>
        </div>
        <div className="w-full sm:w-48">
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger>
              <SelectValue placeholder="فلترة بالحالة" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">جميع الحالات</SelectItem>
              <SelectItem value="PENDING">قيد المراجعة</SelectItem>
              <SelectItem value="APPROVED">موافق عليها</SelectItem>
              <SelectItem value="REJECTED">مرفوضة</SelectItem>
              <SelectItem value="COMPLETED">مكتملة</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="w-full sm:w-48">
          <Select value={sortBy} onValueChange={setSortBy}>
            <SelectTrigger>
              <SelectValue placeholder="ترتيب حسب" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="promotionDate">تاريخ الترقية</SelectItem>
              <SelectItem value="employeeName">اسم الموظف</SelectItem>
              <SelectItem value="toPosition">المنصب الجديد</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {filteredPromotions.length === 0 ? (
        <Card>
          <CardContent className="p-12 text-center">
            <TrendingUp className="h-16 w-16 mx-auto mb-4 text-gray-400" />
            <p className="text-gray-500 mb-4">
              {promotions.length === 0
                ? "لا توجد ترقيات"
                : "لا توجد ترقيات تطابق البحث"}
            </p>
            <Button
              variant="outline"
              onClick={() => navigate("/hr/promotions/new")}
            >
              <Plus className="h-4 w-4 ml-2" />
              إضافة ترقية جديدة
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {filteredPromotions.map((promotion) => {
            const statusInfo = getStatusLabel(promotion.status);
            return (
              <Card
                key={promotion.id}
                className="border-l-4 border-l-green-500 hover:shadow-md transition-shadow"
              >
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      {/* Avatar */}
                      <Avatar className="h-10 w-10 border border-gray-200">
                        <AvatarImage
                          src={(promotion.user || promotion.employee)?.avatar}
                        />
                        <AvatarFallback className="bg-green-100 text-green-700 font-bold">
                          {
                            (promotion.user || promotion.employee)
                              ?.firstName?.[0]
                          }
                        </AvatarFallback>
                      </Avatar>
                      <div>
                        <CardTitle className="text-lg">
                          {(promotion?.user || promotion?.employee)
                            ?.firstName || ""}{" "}
                          {(promotion?.user || promotion?.employee)?.lastName ||
                            ""}
                        </CardTitle>
                        <div className="flex items-center gap-2 mt-1">
                          <Badge className={statusInfo?.color || "bg-gray-100"}>
                            {statusInfo?.label || promotion.status}
                          </Badge>
                          <Badge variant="outline">
                            {promotion.fromPositionName || "غير محدد"} →{" "}
                            {promotion.toPositionName}
                          </Badge>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {promotion.status === "PENDING" && (
                        <>
                          <Button
                            variant="default"
                            size="sm"
                            className="bg-green-600 hover:bg-green-700 text-white"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleUpdateStatus(promotion.id, "APPROVED");
                            }}
                          >
                            <CheckCircle2 className="h-4 w-4 ml-1" />
                            اعتماد
                          </Button>
                          <Button
                            variant="default"
                            size="sm"
                            className="bg-red-600 hover:bg-red-700 text-white"
                            onClick={(e) => {
                              e.stopPropagation();
                              const reason = prompt(
                                "الرجاء إدخال سبب الرفض (اختياري):",
                              );
                              handleUpdateStatus(
                                promotion.id,
                                "REJECTED",
                                reason || "",
                              );
                            }}
                          >
                            <XCircle className="h-4 w-4 ml-1" />
                            رفض
                          </Button>
                        </>
                      )}
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={(e) => {
                          e.stopPropagation();
                          navigate(`/hr/promotions/${promotion.id}/edit`);
                        }}
                      >
                        <Edit className="h-4 w-4 ml-1" />
                        تعديل
                      </Button>
                      <AlertDialog>
                        <AlertDialogTrigger asChild>
                          <Button
                            variant="outline"
                            size="sm"
                            className="text-red-600 hover:text-red-700 hover:bg-red-50"
                          >
                            <Trash2 className="h-4 w-4 ml-2" />
                            حذف
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>تأكيد الحذف</AlertDialogTitle>
                            <AlertDialogDescription>
                              هل أنت متأكد من حذف ترقية{" "}
                              {
                                (promotion.user || promotion.employee)
                                  ?.firstName
                              }{" "}
                              {(promotion.user || promotion.employee)?.lastName}
                              ؟ لا يمكن التراجع عن هذا الإجراء.
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>إلغاء</AlertDialogCancel>
                            <AlertDialogAction
                              onClick={() =>
                                handleDeletePromotion(promotion.id)
                              }
                              className="bg-red-600 hover:bg-red-700"
                            >
                              حذف
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="pt-0">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-muted/30 p-4 rounded-lg">
                    <div className="space-y-3">
                      <div className="flex items-center gap-3 text-sm">
                        <div className="p-2 bg-blue-100 rounded-full text-blue-600">
                          <Briefcase className="h-4 w-4" />
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">
                            المسار الوظيفي
                          </p>
                          <p className="font-medium">
                            {promotion.fromPositionName || "غير محدد"}{" "}
                            <span className="text-gray-400">←</span>{" "}
                            {promotion.toPositionName}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-3 text-sm">
                        <div className="p-2 bg-green-100 rounded-full text-green-600">
                          <TrendingUp className="h-4 w-4" />
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">تعديل الراتب</p>
                          <p className="font-medium">
                            {promotion.fromSalary != null
                              ? Number(promotion.fromSalary).toLocaleString()
                              : "-"}
                            <span className="text-gray-400 mx-2">→</span>
                            <span className="text-green-600 font-bold">
                              {promotion.toSalary != null
                                ? Number(promotion.toSalary).toLocaleString()
                                : "-"}
                            </span>
                          </p>
                        </div>
                      </div>
                    </div>

                    <div className="space-y-3">
                      <div className="flex items-center gap-3 text-sm">
                        <div className="p-2 bg-orange-100 rounded-full text-orange-600">
                          <Calendar className="h-4 w-4" />
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">التواريخ</p>
                          <p className="font-medium">
                            الترقية:{" "}
                            {new Date(
                              promotion.promotionDate,
                            ).toLocaleDateString("ar-EG")}
                          </p>
                          <p className="text-xs text-orange-600">
                            السريان:{" "}
                            {new Date(
                              promotion.effectiveDate,
                            ).toLocaleDateString("ar-EG")}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="mt-4 p-3 border-r-4 border-gray-200 bg-gray-50 rounded-l-md">
                    <p className="text-xs text-gray-500 mb-1 font-bold">
                      سبب الترقية:
                    </p>
                    <p className="text-sm text-gray-700 italic">
                      "{promotion.reason}"
                    </p>
                  </div>

                  {promotion.status === "REJECTED" &&
                    promotion.rejectionReason && (
                      <div className="mt-2 p-2 bg-red-50 border border-red-100 rounded text-xs text-red-700">
                        <strong>سبب الرفض:</strong> {promotion.rejectionReason}
                      </div>
                    )}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default EmployeesPromotion;

import React, { useState, useEffect } from "react";
import {
  MessageSquare,
  Plus,
  Star,
  User,
  ArrowRight,
  Filter,
  Search,
  TrendingUp,
  Inbox,
  Send as SendIcon,
  Award,
  Calendar,
  MoreVertical,
  Pencil,
  Trash2,
  Reply,
  CheckCircle2,
  Clock,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { useNavigate } from "react-router-dom";
import api from "../../services/api";
import { useAuth } from "../../hooks/useAuthSimple";
import { toast } from "sonner";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface Feedback {
  id: string;
  type: string;
  category?: string;
  content: string;
  rating?: number;
  isAnonymous: boolean;
  fromUserId: string;
  toUserId?: string;
  status: string;
  adminReply?: string;
  repliedAt?: string;
  repliedById?: string;
  fromEmployee: {
    id: string;
    firstName: string;
    lastName: string;
    email?: string;
    avatar?: string;
  };
  toEmployee?: {
    id: string;
    firstName: string;
    lastName: string;
    email?: string;
    avatar?: string;
  };
  createdAt: string;
}

interface Stats {
  total: number;
  averageRating: number;
  byType: Array<{ type: string; _count: number }>;
}

const Feedback: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [feedback, setFeedback] = useState<Feedback[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [ratingFilter, setRatingFilter] = useState<number | "all">("all");
  const isPrivileged = ["SUPER_ADMIN", "COMPANY_ADMIN", "OWNER", "MANAGER"].includes(
    user?.role || ""
  );

  // Reply state
  const [selectedFeedback, setSelectedFeedback] = useState<Feedback | null>(null);
  const [replyText, setReplyText] = useState("");
  const [replyLoading, setReplyLoading] = useState(false);
  const [isReplyDialogOpen, setIsReplyDialogOpen] = useState(false);

  useEffect(() => {
    if (user?.companyId) {
      fetchFeedback();
      fetchStats();
    }
  }, [user?.companyId]);

  const fetchFeedback = async () => {
    try {
      setLoading(true);
      const response = await api.get("/hr/feedback");
      if (response.data.success) {
        setFeedback(response.data.feedback || []);
      }
    } catch (error: any) {
      console.error("Error fetching feedback:", error);
      toast.error("فشل في جلب التغذية الراجعة");
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const response = await api.get("/hr/feedback/stats");
      if (response.data.success) {
        setStats(response.data.stats);
      }
    } catch (error) {
      console.error("Error fetching stats:", error);
    }
  };

  const getTypeLabel = (type: string) => {
    const typeMap: Record<string, string> = {
      PEER: "زميل",
      MANAGER: "مدير",
      SUBORDINATE: "مرؤوس",
      SELF: "ذاتي",
      GENERAL: "عام",
      OTHER: "آخر",
    };
    return typeMap[type] || type;
  };

  const getTypeColor = (type: string) => {
    const colorMap: Record<string, string> = {
      PEER: "bg-blue-100 text-blue-700 border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800",
      MANAGER:
        "bg-purple-100 text-purple-700 border-purple-200 dark:bg-purple-900/30 dark:text-purple-400 dark:border-purple-800",
      SUBORDINATE:
        "bg-green-100 text-green-700 border-green-200 dark:bg-green-900/30 dark:text-green-400 dark:border-green-800",
      SELF: "bg-orange-100 text-orange-700 border-orange-200 dark:bg-orange-900/30 dark:text-orange-400 dark:border-orange-800",
      GENERAL:
        "bg-gray-100 text-gray-700 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700",
    };
    return (
      colorMap[type] ||
      "bg-gray-100 text-gray-700 border-gray-200 dark:bg-gray-800"
    );
  };

  const filteredFeedback = feedback.filter((item) => {
    const currentUserId = user?.id;

    if (activeTab === "received" && item.toUserId !== currentUserId)
      return false;
    if (activeTab === "sent" && item.fromUserId !== currentUserId) return false;

    const safeStr = (val?: string) => (val ? val.toLowerCase() : "");
    const search = searchQuery.toLowerCase();
    const matchesSearch =
      safeStr(item.content).includes(search) ||
      safeStr(item.toEmployee?.firstName).includes(search) ||
      safeStr(item.toEmployee?.lastName).includes(search) ||
      safeStr(item.fromEmployee?.firstName).includes(search) ||
      safeStr(item.fromEmployee?.lastName).includes(search);

    const matchesRating =
      ratingFilter === "all" || item.rating === ratingFilter;

    return matchesSearch && matchesRating;
  });

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من رغبتك في حذف هذه التغذية الراجعة؟"))
      return;

    try {
      const response = await api.delete(`/hr/feedback/${id}`);
      if (response.data.success) {
        toast.success("تم حذف التغذية الراجعة بنجاح");
        setFeedback((prev) => prev.filter((item) => item.id !== id));
        fetchStats();
      }
    } catch (error) {
      console.error("Error deleting feedback:", error);
      toast.error("فشل في حذف التغذية الراجعة");
    }
  };

  const handleReply = async () => {
    if (!selectedFeedback || !replyText.trim()) {
      console.warn("⚠️ Cannot send reply: missing feedback or text");
      return;
    }

    try {
      setReplyLoading(true);
      console.log(`📤 Sending reply to feedback ${selectedFeedback.id}:`, replyText);
      const response = await api.post(`/hr/feedback/${selectedFeedback.id}/reply`, {
        reply: replyText,
      });

      if (response.data.success) {
        console.log("✅ Reply sent successfully:", response.data);
        toast.success("تم إرسال الرد بنجاح");
        setFeedback((prev) =>
          prev.map((f) =>
            f.id === selectedFeedback.id
              ? { ...f, adminReply: replyText, status: "RESOLVED", repliedAt: new Date().toISOString() }
              : f
          )
        );
        setIsReplyDialogOpen(false);
        setReplyText("");
      }
    } catch (error: any) {
      console.error("❌ Error replying to feedback:", error);
      toast.error(error.response?.data?.error || "فشل في إرسال الرد");
    } finally {
      setReplyLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "RESOLVED":
        return (
          <Badge className="bg-green-100 text-green-700 border-green-200 dark:bg-green-900/30 dark:text-green-400">
            <CheckCircle2 className="h-3 w-3 ml-1" />
            تم الرد
          </Badge>
        );
      default:
        return (
          <Badge className="bg-amber-100 text-amber-700 border-amber-200 dark:bg-amber-900/30 dark:text-amber-400">
            <Clock className="h-3 w-3 ml-1" />
            قيد الانتظار
          </Badge>
        );
    }
  };

  if (loading && feedback.length === 0) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div
      className="p-6 space-y-8 animate-in fade-in duration-500 min-h-screen transition-colors duration-300"
      dir="rtl"
    >
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-4xl font-extrabold tracking-tight text-foreground mb-2">
            التغذية الراجعة 360°
          </h1>
          <p className="text-lg text-muted-foreground">
            نظرة شاملة على الأداء والتفاعل في الشركة
          </p>
        </div>
        <Button
          onClick={() => navigate("/hr/feedback/new")}
          size="lg"
          className="shadow-lg hover:shadow-xl transition-all duration-300"
        >
          <Plus className="h-5 w-5 ml-2" />
          تغذية راجعة جديدة
        </Button>
      </div>

      {/* Stats Overview */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card className="border-none bg-gradient-to-br from-blue-50 to-white dark:from-blue-900/20 dark:to-slate-900 shadow-md hover:shadow-lg transition-all duration-300 border border-transparent dark:border-blue-900/20">
          <CardContent className="p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="p-2 bg-blue-500/10 rounded-xl">
                <MessageSquare className="h-6 w-6 text-blue-600 dark:text-blue-400" />
              </div>
              <span className="text-sm font-medium text-blue-600 bg-blue-50 dark:bg-blue-900/30 dark:text-blue-300 px-2 py-1 rounded-full">
                الإجمالي
              </span>
            </div>
            <div className="space-y-1">
              <h3 className="text-3xl font-bold">{stats?.total || 0}</h3>
              <p className="text-sm text-muted-foreground">تم تلقيها مؤخراً</p>
            </div>
          </CardContent>
        </Card>

        <Card className="border-none bg-gradient-to-br from-yellow-50 to-white dark:from-yellow-900/20 dark:to-slate-900 shadow-md hover:shadow-lg transition-all duration-300 border border-transparent dark:border-yellow-900/20">
          <CardContent className="p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="p-2 bg-yellow-500/10 rounded-xl">
                <Star className="h-6 w-6 text-yellow-600 dark:text-yellow-400 fill-yellow-600 dark:fill-yellow-400" />
              </div>
              <span className="text-sm font-medium text-yellow-600 bg-yellow-50 dark:bg-yellow-900/30 dark:text-yellow-300 px-2 py-1 rounded-full">
                التقييم
              </span>
            </div>
            <div className="space-y-1">
              <h3 className="text-3xl font-bold">
                {stats?.averageRating.toFixed(1) || "0.0"}
              </h3>
              <p className="text-sm text-muted-foreground">متوسط الرضا العام</p>
            </div>
          </CardContent>
        </Card>

        <Card className="border-none bg-gradient-to-br from-purple-50 to-white dark:from-purple-900/20 dark:to-slate-900 shadow-md hover:shadow-lg transition-all duration-300 border border-transparent dark:border-purple-900/20">
          <CardContent className="p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="p-2 bg-purple-500/10 rounded-xl">
                <TrendingUp className="h-6 w-6 text-purple-600 dark:text-purple-400" />
              </div>
              <span className="text-sm font-medium text-purple-600 bg-purple-50 dark:bg-purple-900/30 dark:text-purple-300 px-2 py-1 rounded-full">
                النشاط
              </span>
            </div>
            <div className="space-y-1">
              <h3 className="text-3xl font-bold">
                %{Math.round(((stats?.total || 0) / 50) * 100)}
              </h3>
              <p className="text-sm text-muted-foreground">
                معدل المشاركة الشهري
              </p>
            </div>
          </CardContent>
        </Card>

        <Card className="border-none bg-gradient-to-br from-green-50 to-white dark:from-green-900/20 dark:to-slate-900 shadow-md hover:shadow-lg transition-all duration-300 border border-transparent dark:border-green-900/20">
          <CardContent className="p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="p-2 bg-green-500/10 rounded-xl">
                <Award className="h-6 w-6 text-green-600 dark:text-green-400" />
              </div>
              <span className="text-sm font-medium text-green-600 bg-green-50 dark:bg-green-900/30 dark:text-green-300 px-2 py-1 rounded-full">
                التميز
              </span>
            </div>
            <div className="space-y-1">
              <h3 className="text-3xl font-bold">
                {feedback.filter((f) => (f.rating || 0) >= 4).length}
              </h3>
              <p className="text-sm text-muted-foreground">
                تقييمات إيجابية (4-5)
              </p>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card className="border-none shadow-xl overflow-hidden bg-card/50 backdrop-blur-sm border-t border-white/10">
        <CardHeader className="bg-muted/50 border-b dark:border-white/5">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <Tabs
              value={activeTab}
              onValueChange={setActiveTab}
              className="w-full lg:w-auto"
            >
              <TabsList className="bg-background/80 p-1 border dark:border-white/10">
                <TabsTrigger
                  value="all"
                  className="data-[state=active]:bg-primary data-[state=active]:text-white transition-all"
                >
                  الكل
                </TabsTrigger>
                <TabsTrigger
                  value="received"
                  className="data-[state=active]:bg-primary data-[state=active]:text-white transition-all"
                >
                  المستلمة
                </TabsTrigger>
                <TabsTrigger
                  value="sent"
                  className="data-[state=active]:bg-primary data-[state=active]:text-white transition-all"
                >
                  المرسلة
                </TabsTrigger>
              </TabsList>
            </Tabs>

            <div className="flex items-center gap-3 w-full lg:w-auto">
              <div className="relative flex-1 lg:w-72">
                <Search className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="ابحث في المحتوى أو الموظفين..."
                  className="pr-10 bg-background/50 border-muted-foreground/20"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
