              <Button
                variant="outline"
                onClick={() => {
                  setSearchQuery("");
                  setRatingFilter("all");
                }}
              >
                إعادة ضبط الفلاتر
              </Button>
            </div>
          ) : (
            <div className="divide-y divide-border">
              {filteredFeedback.map((item) => (
                <div
                  key={item.id}
                  className="p-6 hover:bg-muted/30 transition-colors group"
                >
                  <div className="flex flex-col sm:flex-row gap-6">
                    {/* User Avatars & Rating */}
                    <div className="flex sm:flex-col items-center sm:items-center gap-4 sm:w-32 lg:w-40">
                      <div className="flex -space-x-4 space-x-reverse items-center justify-center">
                        <Avatar className="h-12 w-12 border-2 border-background ring-2 ring-primary/10 shadow-sm">
                          <AvatarFallback className="bg-primary/10 text-primary font-bold">
                            {item.toEmployee?.firstName?.[0] || ""}
                            {item.toEmployee?.lastName?.[0] || ""}
                          </AvatarFallback>
                        </Avatar>
                        {!item.isAnonymous && (
                          <Avatar className="h-10 w-10 border-2 border-background ring-2 ring-purple-500/20 shadow-sm translate-y-1">
                            <AvatarFallback className="bg-purple-500/10 text-purple-600 dark:text-purple-400 text-xs font-bold">
                              {item.fromEmployee.firstName?.[0] || ""}
                              {item.fromEmployee.lastName?.[0] || ""}
                            </AvatarFallback>
                          </Avatar>
                        )}
                      </div>

                      <div className="flex flex-col items-center">
                        {item.rating && (
                          <div className="flex items-center gap-1.5 bg-yellow-500/10 px-2 py-0.5 rounded-full border border-yellow-500/20 mt-2">
                            <Star className="h-3.5 w-3.5 text-yellow-600 dark:text-yellow-400 fill-yellow-600 dark:fill-yellow-400" />
                            <span className="text-sm font-black text-yellow-700 dark:text-yellow-400">
                              {item.rating}
                            </span>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="flex-1 space-y-4">
                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                        <div className="space-y-1">
                          <div className="flex items-center gap-2">
                            <h4 className="text-lg font-bold text-foreground group-hover:text-primary transition-colors">
                              {item.toEmployee
                                ? `${item.toEmployee.firstName} ${item.toEmployee.lastName}`
                                : "تغذية راجعة عامة"}
                            </h4>
                            <Badge
                              variant="outline"
                              className={`font-medium ${getTypeColor(item.type)}`}
                            >
                              {getTypeLabel(item.type)}
                            </Badge>
                            {getStatusBadge(item.status)}
                          </div>

                          <div className="flex items-center gap-2 text-sm text-muted-foreground">
                            <Calendar className="h-3.5 w-3.5" />
                            <span>
                              {format(
                                new Date(item.createdAt),
                                "dd MMMM yyyy",
                                { locale: ar },
                              )}
                            </span>
                            {item.category && (
                              <>
                                <span className="h-1 w-1 rounded-full bg-muted-foreground/30"></span>
                                <span className="font-medium text-blue-600 dark:text-blue-400">
                                  {item.category}
                                </span>
                              </>
                            )}
                          </div>
                        </div>

                        {isPrivileged && (
                          <div className="flex items-center gap-2">
                            {(!item.toUserId || item.toUserId === "management") && !item.adminReply && (
                              <Button
                                size="sm"
                                variant="ghost"
                                className="text-primary hover:text-primary hover:bg-primary/5 gap-1.5 h-8 px-3"
                                onClick={() => {
                                  setSelectedFeedback(item);
                                  setIsReplyDialogOpen(true);
                                }}
                              >
                                <Reply className="h-4 w-4" />
                                <span className="text-xs font-bold">إضافة رد</span>
                              </Button>
                            )}
                            <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                              <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-8 w-8"
                                  >
                                    <MoreVertical className="h-4 w-4" />
                                  </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end" className="w-40">
                                  <DropdownMenuItem
                                    className="flex items-center gap-2 cursor-pointer"
                                    onClick={() =>
                                      navigate(`/hr/feedback/edit/${item.id}`)
                                    }
                                  >
                                    <Pencil className="h-4 w-4 text-blue-600 dark:text-blue-400" />
                                    <span>تعديل</span>
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    className="flex items-center gap-2 cursor-pointer text-red-600 focus:text-red-600"
                                    onClick={() => handleDelete(item.id)}
                                  >
                                    <Trash2 className="h-4 w-4" />
                                    <span>حذف</span>
                                  </DropdownMenuItem>
                                </DropdownMenuContent>
                              </DropdownMenu>
                            </div>
                          </div>
                        )}
                      </div>

                      <div className="bg-muted/50 p-4 rounded-2xl border border-border group-hover:border-blue-500/20 group-hover:bg-blue-500/5 transition-all">
                        <p className="text-foreground/90 leading-relaxed whitespace-pre-wrap">
                          {item.content}
                        </p>
                      </div>

                      <div className="flex items-center gap-4 text-xs font-medium uppercase tracking-wider text-muted-foreground pt-2">
                        <div className="flex items-center gap-1.5 ">
                          {item.isAnonymous ? (
                            <>
                              <User className="h-3 w-3" />
                              <span>مجهول المصدر</span>
                            </>
                          ) : (
                            <>
                              <SendIcon className="h-3 w-3" />
                              <span>
                                من: {item.fromEmployee.firstName}{" "}
                                {item.fromEmployee.lastName}
                              </span>
                            </>
                          )}
                        </div>
                      </div>

                      {/* Admin Reply Section */}
                      {item.adminReply && (
                        <div className="mr-8 mt-2 p-4 bg-primary/5 rounded-2xl border border-primary/10 relative">
                          <div className="absolute -right-4 top-4 bottom-4 w-1 bg-primary/30 rounded-full" />
                          <div className="flex items-center gap-2 mb-2">
                            <Badge className="bg-primary/20 text-primary border-none text-[10px] h-5">رد الإدارة</Badge>
                            {item.repliedAt && (
                              <span className="text-[10px] text-muted-foreground flex items-center gap-1">
                                <Clock className="h-3 w-3" />
                                {format(new Date(item.repliedAt), "dd MMMM yyyy HH:mm", { locale: ar })}
                              </span>
                            )}
                          </div>
                          <p className="text-sm text-foreground/80 leading-relaxed font-medium">
                            {item.adminReply}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
      <Dialog open={isReplyDialogOpen} onOpenChange={setIsReplyDialogOpen}>
        <DialogContent className="sm:max-w-[500px]" dir="rtl">
          <DialogHeader>
            <DialogTitle className="text-xl font-bold flex items-center gap-2">
              <Reply className="h-5 w-5 text-primary" />
              الرد على التغذية الراجعة
            </DialogTitle>
            <DialogDescription>
              سيتم إرسال هذا الرد إلى الموظف وسيصل له إشعار بذلك.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="p-4 bg-muted/50 rounded-xl border italic text-sm text-foreground/80">
              "{selectedFeedback?.content}"
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold">نص الرد</label>
              <Textarea
                placeholder="اكتب ردك هنا..."
                className="min-h-[150px] resize-none"
                value={replyText}
                onChange={(e) => setReplyText(e.target.value)}
              />
            </div>
          </div>

          <div className="flex flex-row-reverse gap-4 mt-8 pt-4 border-t w-full">
            <Button
              onClick={(e) => {
                e.preventDefault();
                console.log("🚀 SEND BUTTON CLICKED!");
                handleReply();
              }}
              disabled={replyLoading || !replyText.trim()}
              className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-bold h-12 text-lg"
            >
              {replyLoading ? "جاري الإرسال..." : "إرسال الرد"}
            </Button>
            <Button
              variant="outline"
              type="button"
              onClick={() => {
                console.log("❌ CANCEL BUTTON CLICKED");
                setIsReplyDialogOpen(false);
              }}
              disabled={replyLoading}
              className="px-6 h-12 font-bold"
            >
              إلغاء
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Feedback;

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { useTranslation } from "react-i18next";
import {
  Users,
  Building2,
  Clock,
  Calendar,
  DollarSign,
  TrendingUp,
  UserCheck,
  UserX,
  AlertCircle,
  ChevronRight,
  BarChart3,
  PieChart,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { Progress } from "../../components/ui/progress";
import { useNavigate } from "react-router-dom";
import api from "../../services/api";
import { toast } from "sonner";
import { useAuth } from "../../hooks/useAuthSimple";
import { createStorageKey, getWithExpiry, setWithExpiry } from "../../utils/storage";

interface DashboardData {
  employees: {
    totalEmployees: number;
    activeEmployees: number;
    byDepartment: any[];
    byContractType: any[];
    byStatus: any[];
    recentHires: any[];
    upcomingBirthdays: any[];
  };
  attendance: {
    date: string;
    totalEmployees: number;
    present: number;
    late: number;
    absent: number;
    records: any[];
  };
  pendingLeaves: any[];
  departments: {
    totalDepartments: number;
    departments: any[];
  };
  pendingPermissions: any[];
  pendingAdvances: any[];
  recruitment: {
    activeJobs: number;
    totalApplicants: number;
    scheduledInterviews: number;
    pendingReviews: number;
    hiredThisMonth: number;
  };
  warnings: {
    total: number;
    bySeverity: any[];
    acknowledged: number;
  };
}

const HRDashboard: React.FC = () => {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<DashboardData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const CACHE_TTL_MS = 60_000;

  const cacheKey = useMemo(() => {
    const authCompanyId = user?.companyId || user?.company?.id;
    if (authCompanyId) {
      return createStorageKey("hr-dashboard", authCompanyId);
    }

    try {
      const rawUser = localStorage.getItem("user");
      const parsedUser = rawUser ? JSON.parse(rawUser) : null;
      const companyId = parsedUser?.companyId || parsedUser?.company?.id || parsedUser?.id || "unknown";
      return createStorageKey("hr-dashboard", companyId);
    } catch {
      return createStorageKey("hr-dashboard", "unknown");
    }
  }, [user?.company?.id, user?.companyId]);

  const fetchDashboard = useCallback(async ({ signal, background = false } = {}) => {
    try {
      if (!background) {
        setLoading(true);
        setError(null);
      }
      const response = await api.get("/hr/dashboard", { signal });
      if (response.data?.dashboard) {
        setData(response.data.dashboard);
        setWithExpiry(cacheKey, response.data.dashboard, CACHE_TTL_MS);
      } else if (!background) {
        setError(t("hrDashboard.errors.fetchFailed") || "فشل تحميل لوحة التحكم");
      }
    } catch (error) {
      console.error("Error fetching HR dashboard:", error);
      if (!background) {
        setError(t("hrDashboard.errors.fetchFailed") || "فشل تحميل لوحة التحكم");
      }
    } finally {
      if (!background) {
        setLoading(false);
      }
    }
  }, [cacheKey, t]);

  useEffect(() => {
    const controller = new AbortController();
    const cached = getWithExpiry<DashboardData>(cacheKey);

    if (cached) {
      setData(cached);
      setLoading(false);
      fetchDashboard({ signal: controller.signal, background: true });
    } else {
      fetchDashboard({ signal: controller.signal });
    }

    return () => controller.abort();
  }, [cacheKey, fetchDashboard]);

  const handleLeaveAction = async (id: string, action: "approve" | "reject") => {
    try {
      const response = await api.post(`/hr/leaves/${id}/${action}`, {
        reason: action === "reject" ? "Action from dashboard" : undefined,
      });
      if (response.data.success) {
        toast.success(
          action === "approve" ? "تمت الموافقة بنجاح" : "تم الرفض بنجاح",
        );
        fetchDashboard({ background: true });
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "حدث خطأ");
    }
  };

  const handlePermissionAction = async (
    id: string,
    action: "approve" | "reject",
  ) => {
    try {
      const response = await api.post(`/hr/permissions/${id}/${action}`, {
        reason: action === "reject" ? "رفض من لوحة التحكم" : undefined,
      });
      if (response.data.success) {
        toast.success(
          action === "approve" ? "تمت الموافقة بنجاح" : "تم الرفض بنجاح",
        );
        fetchDashboard({ background: true });
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "حدث خطأ");
    }
  };

  const handleAdvanceAction = async (
    id: string,
    action: "approve" | "reject",
  ) => {
    try {
      const response = await api.post(`/hr/advances/${id}/${action}`, {
        rejectionReason: action === "reject" ? "Action from dashboard" : undefined,
      });
      if (response.data.success) {
        toast.success(
          action === "approve" ? "تمت الموافقة بنجاح" : "تم الرفض بنجاح",
        );
        fetchDashboard({ background: true });
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || "حدث خطأ");
    }
  };

  if (loading && !data) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (error && !data) {
    return (
      <div className="flex items-center justify-center h-96 text-gray-500">
        {error}
      </div>
    );
  }

  const attendanceRate = data?.attendance
    ? Math.round(
      (data.attendance.present / data.attendance.totalEmployees) * 100,
    )
    : 0;

  return (
    <div
      className="p-6 space-y-6 bg-gray-50 dark:bg-gray-900 min-h-screen"
      dir="rtl"
    >
      {/* Header */}
      <div className="relative overflow-hidden rounded-2xl bg-gradient-to-r from-blue-700 via-blue-600 to-indigo-700 p-8 shadow-lg mb-8">
        <div className="relative z-10 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="text-white">
            <h1 className="text-3xl md:text-4xl font-bold tracking-tight">
              {t("hrDashboard.pageTitle")}
            </h1>
            <p className="text-blue-100 mt-2 text-lg opacity-90 max-w-2xl">
              {t("hrDashboard.overview")}
            </p>
          </div>
          <div className="flex flex-wrap gap-3">
            <Button
              onClick={() => navigate("/hr/employees")}
              variant="secondary"
              className="bg-white/10 hover:bg-white/20 border-white/20 text-white backdrop-blur-md"
            >
              <Users className="h-5 w-5 ml-2" />
