          {
            label: t("hrDashboard.totalDepartments"),
            value: data?.departments.totalDepartments || 0,
            icon: Building2,
            color: "purple",
            gradient: "from-purple-500 to-purple-600",
            bg: "bg-purple-50 dark:bg-purple-900/10",
