                            : "bg-rose-50 text-rose-700 border-rose-100 dark:bg-rose-500/10 dark:text-rose-400 dark:border-rose-500/20"
                            }`}
                        >
                          {record.checkIn
                            ? new Date(record.checkIn).toLocaleTimeString(
                              "ar-EG",
                              {
                                hour: "2-digit",
                                minute: "2-digit",
                                hour12: true,
                              },
