            >
              {t("hrDashboard.viewAll")}
              <ChevronRight className="h-4 w-4" />
            </Button>
          </CardHeader>
          <CardContent className="p-6">
            {data?.pendingLeaves?.length === 0 ? (
              <div className="text-center py-12 flex flex-col items-center">
