                                          </SelectContent>
                                        </Select>
                                      </div>

                                      <div>
                                        <Label className="text-xs">رقم واتساب</Label>
                                        <Input
                                          value={recipient.phone}
                                          onChange={(e) => {
                                            const updated = [...settings.notificationRecipients];
                                            updated[index] = {
                                              ...updated[index],
                                              phone: e.target.value,
                                            };
                                            setSettings({
                                              ...settings,
                                              notificationRecipients: updated,
                                            });
