                  }`}
              >
                <div className="flex items-center gap-2">
                  {totalDaysCount === -1 ? (
                    <AlertTriangle className="h-5 w-5" />
                  ) : (
                    <Clock className="h-5 w-5" />
                  )}
                  <span className="font-medium">
                    {totalDaysCount === -1
                      ? "تاريخ النهاية يجب أن يكون بعد تاريخ البداية"
                      : totalDaysCount === 0
                        ? "الأيام المحددة هي أيام عطلة (جمعة/سبت)"
