              <div className="flex items-center justify-between flex-row-reverse">
                <div className="flex items-center gap-3 flex-row-reverse">
                  <div className="p-2 bg-white dark:bg-gray-900 rounded-md border border-gray-100 dark:border-gray-700">
                    <Clock className="h-4 w-4 text-primary" />
                  </div>
                  <div className="text-right">
                    <Label className="text-sm font-medium">نصف يوم</Label>
                    <p className="text-xs text-gray-500">
                      تقديم طلب لنصف يوم عمل فقط
                    </p>
                  </div>
                </div>
                <Checkbox
                  id="isHalfDay"
                  checked={formData.isHalfDay}
                  onCheckedChange={(checked: boolean) =>
                    setFormData({ ...formData, isHalfDay: checked })
                  }
                />
              </div>

              {formData.isHalfDay && (
                <div className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-700 space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
                  <Label className="text-xs text-gray-500 block text-right">
                    فترة نصف اليوم
                  </Label>
                  <Select
                    value={formData.halfDayPeriod}
                    onValueChange={(value) =>
                      setFormData({ ...formData, halfDayPeriod: value })
                    }
                  >
                    <SelectTrigger
                      className={`w-full bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-700 text-right ${fieldErrors["halfDayPeriod"] ? "border-red-500" : ""}`}
                    >
                      <SelectValue placeholder="اختر الفترة" />
                    </SelectTrigger>
                    <SelectContent className="bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800">
                      <SelectItem value="MORNING" className="justify-end">
                        الفترة الصباحية
                      </SelectItem>
                      <SelectItem value="AFTERNOON" className="justify-end">
                        الفترة المسائية
                      </SelectItem>
                    </SelectContent>
                  </Select>
                  {fieldErrors["halfDayPeriod"] && (
                    <p className="text-xs text-red-500 mt-1 mr-1">
                      {fieldErrors["halfDayPeriod"]}
                    </p>
                  )}
                </div>
              )}
            </div>

            <div className="space-y-2">
              <Label className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                <FileText className="h-4 w-4" />
                السبب
              </Label>
              <Textarea
                value={formData.reason}
                onChange={(e) =>
                  setFormData({ ...formData, reason: e.target.value })
                }
                placeholder="أدخل سبب طلب الإجازة..."
                rows={3}
                className={`bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-right ${fieldErrors["reason"] ? "border-red-500" : ""}`}
              />
              {fieldErrors["reason"] && (
                <p className="text-xs text-red-500 mt-1 mr-1">
                  {fieldErrors["reason"]}
                </p>
              )}
            </div>
          </div>

          <DialogFooter className="flex-row-reverse sm:justify-start gap-2">
            <Button
              onClick={handleAddRequest}
              disabled={
                totalDaysCount <= 0 ||
                !formData.startDate ||
                !formData.endDate ||
                (!isMyLeaves && !formData.employeeId)
              }
              className="bg-blue-600 hover:bg-blue-700 dark:bg-blue-500 dark:hover:bg-blue-600 text-white w-full sm:w-auto"
            >
              إرسال الطلب
            </Button>
            <Button
              variant="outline"
              onClick={() => setShowAddDialog(false)}
              className="w-full sm:w-auto"
            >
              إلغاء
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Details Dialog */}
      <Dialog open={showDetailsDialog} onOpenChange={setShowDetailsDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>تفاصيل طلب الإجازة</DialogTitle>
          </DialogHeader>

          {selectedRequest && (
            <div className="space-y-4 py-4">
              <div className="flex items-center gap-4">
                <Avatar className="h-16 w-16">
                  <AvatarImage src={selectedRequest.employee?.avatar} />
                  <AvatarFallback>
                    {selectedRequest.employee?.firstName?.[0]}
                    {selectedRequest.employee?.lastName?.[0]}
                  </AvatarFallback>
                </Avatar>
                <div>
                  <h3 className="font-semibold text-lg">
                    {selectedRequest.employee?.firstName}{" "}
                    {selectedRequest.employee?.lastName}
                  </h3>
                  <p className="text-gray-500">
                    {selectedRequest.employee?.department?.name}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-gray-500">نوع الإجازة</Label>
                  <p className="font-medium">
                    {leaveTypeConfig[selectedRequest.type]?.label}
                  </p>
                </div>
                <div>
                  <Label className="text-gray-500">حالة الأجر</Label>
                  <Badge
                    className={
                      selectedRequest.type !== "UNPAID"
                        ? "bg-green-100 text-green-800"
                        : "bg-red-100 text-red-800"
                    }
                  >
                    {selectedRequest.type !== "UNPAID"
                      ? "مدفوعة الأجر"
                      : "غير مدفوعة الأجر"}
                  </Badge>
                </div>
                <div>
                  <Label className="text-gray-500">الحالة</Label>
                  <Badge
                    className={
                      statusConfig[selectedRequest.status]?.color || ""
                    }
                  >
                    {statusConfig[selectedRequest.status]?.label ||
                      selectedRequest.status}
                  </Badge>
                </div>
                <div>
                  <Label className="text-gray-500">من</Label>
                  <p className="font-medium">
                    {new Date(selectedRequest.startDate).toLocaleDateString(
                      "ar-EG",
                    )}
                  </p>
                </div>
                <div>
                  <Label className="text-gray-500">إلى</Label>
                  <p className="font-medium">
                    {new Date(selectedRequest.endDate).toLocaleDateString(
                      "ar-EG",
                    )}
                  </p>
                </div>
                <div>
                  <Label className="text-gray-500">المدة</Label>
                  <p className="font-medium">{selectedRequest.totalDays} يوم</p>
                </div>
                <div>
                  <Label className="text-gray-500">تاريخ الطلب</Label>
                  <p className="font-medium">
                    {new Date(selectedRequest.createdAt).toLocaleDateString(
                      "ar-EG",
                    )}
                  </p>
                </div>
              </div>

              {selectedRequest.reason && (
                <div>
                  <Label className="text-gray-500">السبب</Label>
                  <p className="mt-1">{selectedRequest.reason}</p>
                </div>
              )}

              {selectedRequest.rejectionReason && (
                <div className="p-3 bg-red-50 rounded-lg">
                  <Label className="text-red-600">سبب الرفض</Label>
                  <p className="mt-1 text-red-700">
                    {selectedRequest.rejectionReason}
                  </p>
                </div>
              )}

              {selectedRequest.approver && (
                <div>
                  <Label className="text-gray-500">تمت المراجعة بواسطة</Label>
                  <p className="font-medium">
                    {selectedRequest.approver.firstName}{" "}
                    {selectedRequest.approver.lastName}
                  </p>
                </div>
              )}
            </div>
          )}

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowDetailsDialog(false)}
            >
              إغلاق
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Reject Dialog */}
      <Dialog open={showRejectDialog} onOpenChange={setShowRejectDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>رفض طلب الإجازة</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <p>هل أنت متأكد من رفض طلب الإجازة؟</p>
            <div className="space-y-2">
              <Label>سبب الرفض</Label>
              <Textarea
                value={rejectionReason}
                onChange={(e) => setRejectionReason(e.target.value)}
                placeholder="أدخل سبب الرفض..."
                rows={3}
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowRejectDialog(false)}
            >
              إلغاء
            </Button>
            <Button variant="destructive" onClick={handleReject}>
              رفض الطلب
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Reopen Dialog */}
      <Dialog open={showReopenDialog} onOpenChange={setShowReopenDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>إعادة فتح طلب الإجازة</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="p-4 bg-amber-50 rounded-lg border border-amber-200">
              <div className="flex items-center gap-2">
                <AlertTriangle className="h-5 w-5 text-amber-600" />
                <h3 className="font-medium text-amber-800">
                  إعادة فتح طلب مرفوض
                </h3>
              </div>
              <p className="mt-2 text-amber-700 text-sm">
                سيتم إعادة فتح طلب الإجازة المرفوض وتحويله إلى حالة قيد الانتظار
                مرة أخرى. هل أنت متأكد من المتابعة؟
              </p>
            </div>

            {selectedRequest && (
              <div className="space-y-3">
                <div className="flex justify-between items-center">
                  <span className="text-gray-500">الموظف:</span>
                  <span className="font-medium">
                    {selectedRequest.employee?.firstName}{" "}
                    {selectedRequest.employee?.lastName}
                  </span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-500">نوع الإجازة:</span>
                  <span>{leaveTypeConfig[selectedRequest.type]?.label}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-500">المدة:</span>
                  <span>{selectedRequest.totalDays} يوم</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-500">سبب الرفض:</span>
                  <span className="text-red-600">
                    {selectedRequest.rejectionReason}
                  </span>
                </div>
              </div>
            )}
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowReopenDialog(false)}
            >
              إلغاء
            </Button>
            <Button
              variant="default"
              onClick={handleReopenRequest}
              className="bg-amber-600 hover:bg-amber-700"
            >
              إعادة فتح الطلب
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Edit Dialog */}
      <Dialog open={showEditDialog} onOpenChange={setShowEditDialog}>
        <DialogContent className="sm:max-w-[500px] max-h-[90vh] overflow-y-auto bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800">
          <DialogHeader className="text-right">
            <DialogTitle className="text-2xl font-bold flex items-center justify-end gap-2">
              <ArrowRight className="h-6 w-6 text-amber-600" /> {/* AGAIN */}
              تعديل طلب الإجازة
            </DialogTitle>
            <DialogDescription className="text-right text-gray-500 dark:text-gray-400">
              قم بتعديل بيانات طلب الإجازة ثم اضغط على حفظ التعديلات.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-5 py-4">
            {selectedRequest && (
              <div className="p-4 bg-amber-50 rounded-lg border border-amber-200">
                <div className="flex items-center gap-2">
                  <AlertTriangle className="h-5 w-5 text-amber-600" />
                  <h3 className="font-medium text-amber-800">
                    تعديل طلب مرفوض
                  </h3>
                </div>
                <p className="mt-2 text-amber-700 text-sm">
                  سيتم إعادة فتح طلب الإجازة المرفوض وتحويله إلى حالة قيد
                  الانتظار مرة أخرى مع تطبيق التعديلات.
                </p>
              </div>
            )}

            <div className="space-y-2">
              <Label className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                <Palmtree className="h-4 w-4" />
                نوع الإجازة
              </Label>
              <Select
                value={editFormData.type}
                onValueChange={(value) =>
                  setEditFormData({
                    ...editFormData,
                    type: value,
                    isPaid: value === "UNPAID" ? false : editFormData.isPaid,
                  })
                }
              >
                <SelectTrigger className="w-full bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-right dir-rtl">
                  <SelectValue />
                </SelectTrigger>

            <div className="space-y-2">
              <Label className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                <Wallet className="h-4 w-4" />
                حالة الأجر
              </Label>
              <Select
                value={editFormData.isPaid ? "PAID" : "UNPAID"}
                onValueChange={(value) => {
                  const isPaid = value === "PAID";
                  setEditFormData({
                    ...editFormData,
                    isPaid,
                    type: !isPaid && editFormData.type !== "UNPAID" ? "UNPAID" : isPaid && editFormData.type === "UNPAID" ? "ANNUAL" : editFormData.type,
                  });
                }}
              >
                <SelectTrigger className="w-full bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-right dir-rtl">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800">
                  <SelectItem value="PAID">مدفوعة الأجر</SelectItem>
                  <SelectItem value="UNPAID">غير مدفوعة الأجر</SelectItem>
                </SelectContent>
              </Select>
            </div>



                <SelectContent className="max-h-[200px] bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800">
                  {Object.entries(leaveTypeConfig).map(([key, config]) => (
                    <SelectItem
                      key={key}
                      value={key}
                      className="justify-end cursor-pointer focus:bg-gray-100 dark:focus:bg-gray-800"
                    >
                      <div className="flex items-center gap-2 flex-row-reverse">
                        <config.icon
                          className={`h-4 w-4 ${config.color.split(" ")[1]}`}
                        />
                        <span>{config.label}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                  <Calendar className="h-4 w-4" />
                  من تاريخ
                </Label>
                <Input
                  type="date"
                  value={editFormData.startDate}
                  onChange={(e) =>
                    setEditFormData({
                      ...editFormData,
                      startDate: e.target.value,
                    })
                  }
                  className="bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700"
                />
              </div>
              <div className="space-y-2">
                <Label className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                  <Calendar className="h-4 w-4" />
                  إلى تاريخ
                </Label>
                <Input
                  type="date"
                  value={editFormData.endDate}
                  onChange={(e) =>
                    setEditFormData({
                      ...editFormData,
                      endDate: e.target.value,
                    })
                  }
                  className="bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700"
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                <FileText className="h-4 w-4" />
                سبب الإجازة
              </Label>
              <Textarea
                value={editFormData.reason}
                onChange={(e) =>
                  setEditFormData({ ...editFormData, reason: e.target.value })
                }
                placeholder="أدخل سبب الإجازة..."
                rows={3}
                className="bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-right dir-rtl"
              />
            </div>

            <div
              className={`p-3 rounded-lg border transition-colors ${editFormData.isHalfDay ? "bg-primary/5 border-primary/20" : "bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700"}`}
            >
              <div className="flex items-center justify-between flex-row-reverse">
                <div className="flex items-center gap-3 flex-row-reverse">
                  <div className="p-2 bg-white dark:bg-gray-900 rounded-md border border-gray-100 dark:border-gray-700">
                    <Clock className="h-4 w-4 text-primary" />
                  </div>
                  <div className="text-right">
                    <Label className="text-sm font-medium">نصف يوم</Label>
                    <p className="text-xs text-gray-500">
                      تقديم طلب لنصف يوم عمل فقط
                    </p>
                  </div>
                </div>
                <Checkbox
                  id="editIsHalfDay"
                  checked={editFormData.isHalfDay}
                  onCheckedChange={(checked: boolean) =>
                    setEditFormData({ ...editFormData, isHalfDay: checked })
                  }
                />
              </div>

              {editFormData.isHalfDay && (
                <div className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-700 space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
                  <Label className="text-xs text-gray-500 block text-right">
                    فترة نصف اليوم
                  </Label>
                  <Select
                    value={editFormData.halfDayPeriod}
                    onValueChange={(value) =>
                      setEditFormData({ ...editFormData, halfDayPeriod: value })
                    }
                  >
                    <SelectTrigger className="w-full bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-right dir-rtl">
                      <SelectValue placeholder="اختر الفترة" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem
                        value="MORNING"
                        className="justify-end cursor-pointer"
                      >
                        الفترة الصباحية
                      </SelectItem>
                      <SelectItem
                        value="AFTERNOON"
                        className="justify-end cursor-pointer"
                      >
                        الفترة المسائية
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowEditDialog(false)}>
              إلغاء
            </Button>
            <Button
              variant="default"
              onClick={handleSaveEdit}
              className="bg-amber-600 hover:bg-amber-700"
            >
              حفظ التعديلات
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Change Decision Dialog */}
      <Dialog
        open={showChangeDecisionDialog}
        onOpenChange={(open) => {
          setShowChangeDecisionDialog(open);
          if (!open) {
            setNewDecision("");
            setRejectionReason("");
          }
        }}
      >
        <DialogContent className="sm:max-w-[500px] bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800">
          <DialogHeader className="text-right">
            <DialogTitle className="text-2xl font-bold flex items-center justify-end gap-2">
              <RotateCcw className="h-6 w-6 text-blue-600" />
              تغيير القرار
            </DialogTitle>
            <DialogDescription className="text-right text-gray-500 dark:text-gray-400">
              قم بتغيير قرار الموافقة أو الرفض لطلب الإجازة.
            </DialogDescription>
          </DialogHeader>

          {selectedRequest && (
            <div className="space-y-4 py-4">
              {/* معلومات الطلب */}
              <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-900/30">
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <span className="text-gray-500">الموظف:</span>
                    <span className="font-medium">
                      {selectedRequest.employee?.firstName}{" "}
                      {selectedRequest.employee?.lastName}
                    </span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-gray-500">نوع الإجازة:</span>
                    <span>{leaveTypeConfig[selectedRequest.type]?.label}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-gray-500">المدة:</span>
                    <span>{selectedRequest.totalDays} يوم</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-gray-500">الحالة الحالية:</span>
                    <Badge
                      className={
                        statusConfig[selectedRequest.status]?.color || ""
                      }
                    >
                      {statusConfig[selectedRequest.status]?.label}
                    </Badge>
                  </div>
                </div>
              </div>

              {/* اختيار القرار الجديد */}
              <div className="space-y-3">
                <Label className="text-lg font-semibold">
                  اختر القرار الجديد:
                </Label>

                <div className="grid grid-cols-3 gap-2">
                  {/* زر الموافقة */}
                  <Button
                    variant="outline"
                    className={`h-20 flex flex-col gap-2 p-1 ${selectedRequest.status === "APPROVED"
                      ? "border-gray-300 opacity-50 cursor-not-allowed bg-gray-50"
                      : "border-green-500 hover:bg-green-50 hover:border-green-600"
                      }`}
                    onClick={() => {
                      if (selectedRequest.status !== "APPROVED") {
                        setNewDecision("APPROVE");
                        handleChangeDecision("APPROVE");
                      }
                    }}
                    disabled={selectedRequest.status === "APPROVED"}
                  >
                    <Check className="h-5 w-5 text-green-600" />
                    <span className="font-medium text-xs">موافقة</span>
                    {selectedRequest.status === "APPROVED" && (
                      <span className="text-[10px] text-gray-500">
                        (الحالة الحالية)
                      </span>
                    )}
                  </Button>

                  {/* زر الرفض */}
                  <Button
                    variant="outline"
                    className={`h-20 flex flex-col gap-2 p-1 ${selectedRequest.status === "REJECTED"
                      ? "border-gray-300 opacity-50 cursor-not-allowed bg-gray-50"
                      : "border-red-500 hover:bg-red-50 hover:border-red-600"
                      }`}
                    onClick={() => {
                      if (selectedRequest.status !== "REJECTED") {
                        // عند الضغط على زر الرفض، نظهر حقل سبب الرفض
                        setNewDecision("REJECT");
                      }
                    }}
                    disabled={selectedRequest.status === "REJECTED"}
                  >
                    <X className="h-5 w-5 text-red-600" />
                    <span className="font-medium text-xs">رفض</span>
                    {selectedRequest.status === "REJECTED" && (
                      <span className="text-[10px] text-gray-500">
                        (الحالة الحالية)
                      </span>
                    )}
                  </Button>

                  {/* زر الإلغاء */}
                  <Button
                    variant="outline"
                    className={`h-20 flex flex-col gap-2 p-1 ${selectedRequest.status === "CANCELLED"
                      ? "border-gray-300 opacity-50 cursor-not-allowed bg-gray-50"
                      : "border-orange-500 hover:bg-orange-50 hover:border-orange-600"
                      }`}
                    onClick={() => {
                      if (selectedRequest.status !== "CANCELLED") {
                        setNewDecision("CANCELLED");
                        handleChangeDecision("CANCELLED");
                      }
                    }}
                    disabled={selectedRequest.status === "CANCELLED"}
                  >
                    <RotateCcw className="h-5 w-5 text-orange-600" />
                    <span className="font-medium text-xs">إلغاء الطلب</span>
                    {selectedRequest.status === "CANCELLED" && (
                      <span className="text-[10px] text-gray-500">
                        (الحالة الحالية)
                      </span>
                    )}
                  </Button>
                </div>

                {/* حقل سبب الرفض - يظهر عندما يتم اختيار الرفض */}
                {newDecision === "REJECT" && (
                  <div className="space-y-2 pt-2 animate-in slide-in-from-top-4 duration-300">
                    <Label className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                      <FileText className="h-4 w-4" />
                      سبب الرفض *
                    </Label>
                    <Textarea
                      value={rejectionReason}
                      onChange={(e) => setRejectionReason(e.target.value)}
                      placeholder="أدخل سبب الرفض..."
                      rows={3}
                      className="bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-right"
                    />
                    <Button
                      variant="destructive"
                      className="w-full"
                      onClick={() => handleChangeDecision("REJECT")}
                    >
                      <X className="h-4 w-4 ml-2" />
                      تأكيد الرفض
                    </Button>
                  </div>
                )}
              </div>
            </div>
          )}

          <DialogFooter className="flex-row-reverse sm:justify-start">
            <Button
              variant="outline"
              onClick={() => {
                setShowChangeDecisionDialog(false);
                setRejectionReason("");
              }}
            >
              إغلاق
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Leaves;

import React, { useState, useEffect } from "react";
import {
  Clock,
  Save,
  X,
  ChevronLeft,
  ChevronRight,
  Edit2,
  AlertCircle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Badge } from "../../components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import api from "../../services/api";
import { toast } from "sonner";

interface AttendanceRecord {
  id: string;
  date: string;
  checkIn: string | null;
  checkOut: string | null;
  status: string;
  workHours: number | null;
  overtimeHours: number | null;
  lateMinutes: number | null;
  notes: string | null;
  employee: {
    id: string;
    firstName: string;
    lastName: string;
    avatar: string;
    employeeNumber: string;
    department: { name: string } | null;
  };
}

interface EditingRecord {
  id: string;
  checkIn: string;
  checkOut: string;
  status: string;
  notes: string;
  lateHours: number;
  lateMins: number;
  earlyHours: number;
  earlyMins: number;
}

const statusOptions = [
  { value: "PRESENT", label: "حاضر", color: "bg-green-100 text-green-800" },
  { value: "LATE", label: "متأخر", color: "bg-yellow-100 text-yellow-800" },
  { value: "ABSENT", label: "غائب", color: "bg-red-100 text-red-800" },
  { value: "HALF_DAY", label: "نصف يوم", color: "bg-blue-100 text-blue-800" },
  { value: "ON_LEAVE", label: "إجازة", color: "bg-purple-100 text-purple-800" },
  { value: "REMOTE", label: "عن بُعد", color: "bg-indigo-100 text-indigo-800" },
];

const ManualAttendanceEdit: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState<string | null>(null);
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [editingRecords, setEditingRecords] = useState<
    Map<string, EditingRecord>
  >(new Map());
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0,
  });

  const [selectedDate, setSelectedDate] = useState(
    new Date().toISOString().split("T")[0],
  );
  const [endDate, setEndDate] = useState(
    new Date().toISOString().split("T")[0],
  );
  const [useDateRange, setUseDateRange] = useState(false);
  const [statusFilter, setStatusFilter] = useState("");
  const [employeeId, setEmployeeId] = useState("");
  const [showAllEmployees, setShowAllEmployees] = useState(false);
  const [employees, setEmployees] = useState<
    Array<{
      id: string;
      firstName: string;
      lastName: string;
      employeeNumber: string;
    }>
  >([]);
  const [allEmployeesWithAttendance, setAllEmployeesWithAttendance] = useState<
    AttendanceRecord[]
  >([]);

  useEffect(() => {
    fetchEmployees();
  }, []);

  useEffect(() => {
    if (showAllEmployees) {
      fetchAllEmployeesWithAttendance();
    } else {
      fetchAttendance();
    }
  }, [
    selectedDate,
    endDate,
    useDateRange,
    statusFilter,
    employeeId,
    showAllEmployees,
  ]);

  useEffect(() => {
    if (pagination.page > 1) {
      fetchAttendance();
    }
  }, [pagination.page]);

  const fetchEmployees = async () => {
    try {
      const response = await api.get("/hr/employees?limit=1000&status=ACTIVE");
      console.log("📋 Employees API Response:", response.data);
      const employeesList = response.data.employees || [];
      console.log("📋 Employees List:", employeesList.length, "employees");
      setEmployees(employeesList);
    } catch (error) {
      console.error("❌ Error fetching employees:", error);
      toast.error("حدث خطأ أثناء جلب قائمة الموظفين");
    }
  };

  const fetchAttendance = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
        startDate: selectedDate || "",
        endDate: (useDateRange ? endDate : selectedDate) || "",
      } as Record<string, string>);

      if (statusFilter && statusFilter !== "ALL")
        params.append("status", statusFilter);
      if (employeeId) params.append("employeeId", employeeId);

      const response = await api.get(`/hr/attendance?${params}`);
      setRecords(response.data.records);
      setPagination((prev) => ({
        ...prev,
        total: response.data.pagination.total,
        totalPages: response.data.pagination.totalPages,
      }));
    } catch (error) {
      console.error("Error fetching attendance:", error);
      toast.error("حدث خطأ أثناء جلب سجل الحضور");
    } finally {
      setLoading(false);
    }
  };

  const fetchAllEmployeesWithAttendance = async () => {
    try {
      setLoading(true);
      const employeesResponse = await api.get(
        "/hr/employees?limit=1000&status=ACTIVE",
      );
      const employeesList = employeesResponse.data.employees || [];

      const targetDate = selectedDate;
      console.log("📅 Target date for search:", targetDate);

      // استخدام التاريخ المحدد مباشرة بدون إضافة أيام إضافية
      const searchStartDate = targetDate;
      const searchEndDate = targetDate;

      console.log("📅 Search date:", searchStartDate);

      const attendanceResponse = await api.get(
        `/hr/attendance?startDate=${searchStartDate}&endDate=${searchEndDate}&limit=1000`,
      );
      const attendanceRecords = attendanceResponse.data.records || [];

      console.log("📋 Fetched attendance records:", attendanceRecords.length);
      console.log("📋 Employees list:", employeesList.length);

      if (attendanceRecords.length > 0) {
        console.log("📋 Sample record date:", attendanceRecords[0].date);
      }

      const attendanceMap = new Map(
        attendanceRecords.map((r: AttendanceRecord) => [r.employee.id, r]),
      );

      const combinedRecords = employeesList.map((emp: any) => {
        const existingRecord = attendanceMap.get(emp.id);
        if (existingRecord) {
          console.log(`✅ Found existing record for employee ${emp.id}`);
          return existingRecord;
        }
        console.log(`➕ Creating placeholder for employee ${emp.id}`);
        return {
          id: `temp-${emp.id}`,
          date: targetDate,
          checkIn: null,
          checkOut: null,
          status: "ABSENT",
          workHours: null,
          overtimeHours: null,
          lateMinutes: null,
          notes: null,
          employee: {
            id: emp.id,
            firstName: emp.firstName,
            lastName: emp.lastName,
            avatar: emp.avatar,
            employeeNumber: emp.employeeNumber,
            department: emp.department,
          },
          isNew: true,
        };
      });

      console.log("📋 Combined records:", combinedRecords.length);
      setAllEmployeesWithAttendance(combinedRecords);
      setPagination((prev) => ({
        ...prev,
        total: combinedRecords.length,
        totalPages: Math.ceil(combinedRecords.length / prev.limit),
      }));
    } catch (error) {
      console.error("Error fetching all employees:", error);
      toast.error("حدث خطأ أثناء جلب الموظفين");
    } finally {
      setLoading(false);
    }
  };

  const startEditing = (record: AttendanceRecord) => {
    let checkInTime = "09:00";
    let checkOutTime = "";

    if (record.checkIn) {
      try {
        const date = new Date(record.checkIn);
        const hours = date.getHours().toString().padStart(2, "0");
        const minutes = date.getMinutes().toString().padStart(2, "0");
        checkInTime = `${hours}:${minutes}`;
      } catch (error) {
        console.error("Error parsing checkIn time:", error);
      }
    }

    if (record.checkOut) {
      try {
        const date = new Date(record.checkOut);
        const hours = date.getHours().toString().padStart(2, "0");
        const minutes = date.getMinutes().toString().padStart(2, "0");
        checkOutTime = `${hours}:${minutes}`;
      } catch (error) {
        console.error("Error parsing checkOut time:", error);
      }
    }

    setEditingRecords((prev) =>
      new Map(prev).set(record.id, {
        id: record.id,
        checkIn: checkInTime,
        checkOut: checkOutTime,
        status: record.status,
        notes: record.notes || "",
        lateHours: Math.floor((record.lateMinutes || 0) / 60),
        lateMins: (record.lateMinutes || 0) % 60,
        earlyHours: Math.floor((record.earlyLeaveMinutes || 0) / 60),
        earlyMins: (record.earlyLeaveMinutes || 0) % 60,
      }),
    );
  };

  const cancelEditing = (recordId: string) => {
    setEditingRecords((prev) => {
      const newMap = new Map(prev);
      newMap.delete(recordId);
      return newMap;
    });
  };

  const calculateWorkHours = (checkIn: string, checkOut: string): number => {
    if (!checkIn || !checkOut) return 0;
    try {
      const checkInTime = new Date(`2000-01-01T${checkIn}:00`);
      const checkOutTime = new Date(`2000-01-01T${checkOut}:00`);
      if (isNaN(checkInTime.getTime()) || isNaN(checkOutTime.getTime())) {
        return 0;
      }
      const diffMs = checkOutTime.getTime() - checkInTime.getTime();
      return Math.max(0, diffMs / (1000 * 60 * 60));
    } catch (error) {
      console.error("Error calculating work hours:", error);
      return 0;
    }
  };

  const validateTimes = (checkIn: string, checkOut: string): boolean => {
    if (!checkIn) {
      toast.error("يجب إدخال وقت الحضور");
      return false;
    }

    try {
      const checkInTime = new Date(`2000-01-01T${checkIn}:00`);
      if (isNaN(checkInTime.getTime())) {
        toast.error("تنسيق وقت الحضور غير صحيح");
        return false;
      }

      if (checkOut) {
        const checkOutTime = new Date(`2000-01-01T${checkOut}:00`);

        if (isNaN(checkOutTime.getTime())) {
          toast.error("تنسيق وقت الانصراف غير صحيح");
          return false;
        }

        if (checkOutTime <= checkInTime) {
          toast.error("وقت الانصراف يجب أن يكون بعد وقت الحضور");
          return false;
        }

        const workHours = calculateWorkHours(checkIn, checkOut);
        if (workHours > 24) {
          toast.error("ساعات العمل غير منطقية (أكثر من 24 ساعة)");
          return false;
        }
      }

      return true;
    } catch (error) {
      toast.error("خطأ في التحقق من الأوقات");
      return false;
    }
  };

  const saveRecord = async (recordId: string) => {
    const editingData = editingRecords.get(recordId);
    if (!editingData) return;

    if (saving === recordId) return;

    if (!validateTimes(editingData.checkIn, editingData.checkOut)) {
      return;
    }

    try {
      setSaving(recordId);
      const allRecords = showAllEmployees
        ? allEmployeesWithAttendance
        : records;
      const record = allRecords.find((r) => r.id === recordId);
      if (!record) {
        toast.error("السجل غير موجود");
        return;
      }

      const dateOnly = new Date(record.date).toISOString().split("T")[0];
      const checkInDateTime = `${dateOnly}T${editingData.checkIn}:00`;
      const checkOutDateTime = `${dateOnly}T${editingData.checkOut}:00`;

      const workHours = calculateWorkHours(
        editingData.checkIn,
        editingData.checkOut,
      );

      if ((record as any).isNew) {
        // للسجلات الجديدة، نستخدم API الذي يتعامل مع upsert
        try {
          await api.post("/hr/attendance/manual", {
            employeeId: record.employee.id,
            date: dateOnly,
            checkIn: editingData.checkIn,
            checkOut: editingData.checkOut,
            status: editingData.status,
            notes: editingData.notes || null,
            lateMinutes: editingData.lateHours * 60 + editingData.lateMins,
            earlyLeaveMinutes:
              editingData.earlyHours * 60 + editingData.earlyMins,
          });
          toast.success("تم حفظ سجل الحضور بنجاح");
        } catch (error: any) {
          // إذا فشل الإنشاء بسبب وجود السجل، نحاول التحديث
          if (
            error.response?.status === 400 ||
            error.response?.data?.error?.includes("موجود")
          ) {
            console.log("⚠️ Record exists, trying to update instead...");
            // نحاول جلب السجل الموجود وتحديثه
            const existingRecords = await api.get(
              `/hr/attendance?startDate=${dateOnly}&endDate=${dateOnly}&employeeId=${record.employee.id}`,
            );
            if (
              existingRecords.data.records &&
              existingRecords.data.records.length > 0
            ) {
              const existingRecordId = existingRecords.data.records[0].id;
              await api.put(`/hr/attendance/${existingRecordId}`, {
                date: dateOnly,
                checkIn: editingData.checkIn,
                checkOut: editingData.checkOut,
                status: editingData.status,
                notes: editingData.notes || null,
                workHours: workHours,
                lateMinutes: editingData.lateHours * 60 + editingData.lateMins,
                earlyLeaveMinutes:
                  editingData.earlyHours * 60 + editingData.earlyMins,
              });
              toast.success("تم تحديث سجل الحضور بنجاح");
            } else {
              throw error;
            }
          } else {
            throw error;
          }
        }
      } else {
        await api.put(`/hr/attendance/${recordId}`, {
          date: dateOnly,
          checkIn: editingData.checkIn,
          checkOut: editingData.checkOut,
          status: editingData.status,
          notes: editingData.notes || null,
          workHours: workHours,
          lateMinutes: editingData.lateHours * 60 + editingData.lateMins,
          earlyLeaveMinutes:
            editingData.earlyHours * 60 + editingData.earlyMins,
        });
        toast.success("تم حفظ التعديلات بنجاح");
      }

      cancelEditing(recordId);
      if (showAllEmployees) {
        await fetchAllEmployeesWithAttendance();
      } else {
        await fetchAttendance();
      }
    } catch (error: any) {
      console.error("Error saving attendance:", error);
      const errorMessage =
        error.response?.data?.error ||
        error.response?.data?.message ||
        "حدث خطأ أثناء حفظ التعديلات";
      toast.error(errorMessage);
    } finally {
      setSaving(null);
    }
  };

  const updateEditingField = (
    recordId: string,
    field: keyof EditingRecord,
    value: string | number,
  ) => {
    setEditingRecords((prev) => {
      const newMap = new Map(prev);
      const record = newMap.get(recordId);
      if (record) {
        newMap.set(recordId, { ...record, [field]: value });
      }
      return newMap;
    });
  };

  const setCurrentTimeForCheckIn = (recordId: string) => {
    const now = new Date();
    const hours = now.getHours().toString().padStart(2, "0");
    const minutes = now.getMinutes().toString().padStart(2, "0");
    const currentTime = `${hours}:${minutes}`;
    updateEditingField(recordId, "checkIn", currentTime);
    toast.success(`تم تعيين وقت الحضور: ${currentTime}`);
  };

  const setCurrentTimeForCheckOut = (recordId: string) => {
    const now = new Date();
    const hours = now.getHours().toString().padStart(2, "0");
    const minutes = now.getMinutes().toString().padStart(2, "0");
    const currentTime = `${hours}:${minutes}`;
    updateEditingField(recordId, "checkOut", currentTime);
    toast.success(`تم تعيين وقت الانصراف: ${currentTime}`);
  };

  const isEditing = (recordId: string): boolean => {
    return editingRecords.has(recordId);
  };

  const getStatusColor = (status: string): string => {
    return (
      statusOptions.find((s) => s.value === status)?.color ||
      "bg-gray-100 text-gray-800"
    );
  };

  const getStatusLabel = (status: string): string => {
    return statusOptions.find((s) => s.value === status)?.label || status;
  };

  return (
    <div
      className="p-6 space-y-6 bg-gray-50 dark:bg-gray-900 min-h-screen"
      dir="rtl"
    >
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            تعديل الحضور اليدوي
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            تعديل سجلات الحضور والانصراف للموظفين
          </p>
        </div>
        <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
          <AlertCircle className="h-4 w-4" />
          <span>التعديلات تُحفظ فوراً عند الضغط على حفظ</span>
        </div>
      </div>

      <Card>
        <CardContent className="p-6">
          <div className="flex flex-col gap-4">
            <div className="flex items-center gap-3 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
              <input
                type="checkbox"
                id="showAllEmployees"
                checked={showAllEmployees}
                onChange={(e) => setShowAllEmployees(e.target.checked)}
                className="rounded border-gray-300 w-4 h-4"
              />
              <label
                htmlFor="showAllEmployees"
                className="text-sm font-medium cursor-pointer select-none"
              >
                عرض جميع الموظفين (حتى بدون سجلات حضور)
              </label>
              {showAllEmployees && (
                <span className="text-xs text-blue-600 dark:text-blue-400 mr-auto">
                  يمكنك إنشاء سجلات حضور جديدة للموظفين
                </span>
              )}
            </div>
            <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center">
              <div className="flex flex-wrap gap-4 items-center">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">التاريخ:</span>
                  <Input
                    type="date"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    className="w-[160px]"
                  />
                </div>

                <div className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    id="useRange"
                    checked={useDateRange}
                    onChange={(e) => setUseDateRange(e.target.checked)}
                    className="rounded border-gray-300"
                  />
                  <label
                    htmlFor="useRange"
                    className="text-sm select-none cursor-pointer"
                  >
                    فترة زمنية
                  </label>
                </div>

                {useDateRange && (
                  <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4">
                    <span className="text-sm font-medium">إلى:</span>
                    <Input
                      type="date"
                      value={endDate}
                      onChange={(e) => setEndDate(e.target.value)}
                      className="w-[160px]"
                      min={selectedDate}
                    />
                  </div>
                )}
              </div>

              <div className="flex flex-wrap gap-4 w-full md:w-auto">
                <Select value={statusFilter} onValueChange={setStatusFilter}>
                  <SelectTrigger className="w-[150px]">
                    <SelectValue placeholder="الحالة" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ALL">الكل</SelectItem>
                    {statusOptions.map((status) => (
                      <SelectItem key={status.value} value={status.value}>
                        {status.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>

                <Select
                  value={employeeId || "all"}
                  onValueChange={(value) =>
                    setEmployeeId(value === "all" ? "" : value)
                  }
                >
                  <SelectTrigger className="w-[200px]">
                    <SelectValue
                      placeholder={
                        employees.length > 0 ? "اختر موظف" : "لا يوجد موظفين"
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">
                      الكل ({employees.length} موظف)
                    </SelectItem>
                    {employees.length > 0 ? (
                      employees.map((emp) => (
                        <SelectItem key={emp.id} value={emp.id}>
                          {emp.firstName} {emp.lastName}{" "}
                          {emp.employeeNumber ? `(${emp.employeeNumber})` : ""}
                        </SelectItem>
                      ))
                    ) : (
                      <SelectItem value="no-employees" disabled>
                        لا يوجد موظفين نشطين
                      </SelectItem>
                    )}
                  </SelectContent>
                </Select>

                <Button
                  variant="outline"
                  onClick={() => {
                    setSelectedDate(new Date().toISOString().split("T")[0]);
                    setEndDate(new Date().toISOString().split("T")[0]);
                    setUseDateRange(false);
                    setStatusFilter("");
                    setEmployeeId("");
                  }}
                  className="px-3"
                  title="إعادة تعيين الفلاتر"
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>سجلات الحضور</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="flex items-center justify-center h-64">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
            </div>
          ) : (showAllEmployees ? allEmployeesWithAttendance : records)
            .length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-gray-500">
              <Clock className="h-12 w-12 mb-4 opacity-50" />
              <p>لا توجد سجلات حضور</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="text-right">الموظف</TableHead>
                    <TableHead className="text-right">التاريخ</TableHead>
                    <TableHead className="text-right">الحضور</TableHead>
                    <TableHead className="text-right">الانصراف</TableHead>
                    <TableHead className="text-right">ساعات العمل</TableHead>
                    <TableHead className="text-right">تأخير/مبكر (د)</TableHead>
                    <TableHead className="text-right">الحالة</TableHead>
                    <TableHead className="text-right">ملاحظات</TableHead>
                    <TableHead className="text-right">الإجراءات</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {(showAllEmployees
                    ? allEmployeesWithAttendance
                    : records
                  ).map((record) => {
                    const editing = isEditing(record.id);
                    const editData = editingRecords.get(record.id);

                    return (
                      <TableRow
                        key={record.id}
                        className={
                          editing
                            ? "bg-blue-50 dark:bg-blue-900/10"
                            : (record as any).isNew
                              ? "bg-yellow-50 dark:bg-yellow-900/10"
                              : ""
                        }
                      >
                        <TableCell>
                          <div className="flex items-center gap-3">
                            <Avatar className="h-8 w-8">
                              <AvatarImage src={record.employee?.avatar} />
                              <AvatarFallback>
                                {record.employee?.firstName?.[0]}
                                {record.employee?.lastName?.[0]}
                              </AvatarFallback>
                            </Avatar>
                            <div>
                              <p className="font-medium text-sm">
                                {record.employee?.firstName}{" "}
                                {record.employee?.lastName}
                              </p>
                              <p className="text-xs text-gray-500">
                                {record.employee?.employeeNumber}
                              </p>
                            </div>
                          </div>
                        </TableCell>
                        <TableCell>
                          <span className="text-sm">
                            {new Date(record.date).toLocaleDateString("ar-EG")}
                          </span>
                        </TableCell>
                        <TableCell>
                          {editing ? (
                            <div className="flex items-center gap-2">
                              <Input
                                type="time"
                                value={editData?.checkIn || ""}
                                onChange={(e) =>
                                  updateEditingField(
                                    record.id,
                                    "checkIn",
                                    e.target.value,
                                  )
                                }
                                className="w-[120px]"
                              />
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() =>
                                  setCurrentTimeForCheckIn(record.id)
                                }
                                className="px-2 py-1 h-8"
                                title="تسجيل الوقت الحالي"
                              >
                                <Clock className="h-3 w-3" />
                              </Button>
                            </div>
                          ) : (
                            <span className="text-green-600 font-medium text-sm">
                              {record.checkIn
                                ? new Date(record.checkIn).toLocaleTimeString(
                                  "ar-EG",
                                  {
                                    hour: "2-digit",
                                    minute: "2-digit",
                                    hour12: true,
                                  },
                                )
                                : "-"}
                            </span>
                          )}
                        </TableCell>
                        <TableCell>
                          {editing ? (
                            <div className="flex items-center gap-2">
                              <Input
                                type="time"
                                value={editData?.checkOut || ""}
                                onChange={(e) =>
                                  updateEditingField(
                                    record.id,
                                    "checkOut",
                                    e.target.value,
                                  )
                                }
                                className="w-[120px]"
                              />
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() =>
                                  setCurrentTimeForCheckOut(record.id)
                                }
                                className="px-2 py-1 h-8"
                                title="تسجيل الوقت الحالي"
                              >
                                <Clock className="h-3 w-3" />
                              </Button>
                            </div>
                          ) : (
                            <span className="text-blue-600 font-medium text-sm">
                              {record.checkOut
                                ? new Date(record.checkOut).toLocaleTimeString(
                                  "ar-EG",
                                  {
                                    hour: "2-digit",
                                    minute: "2-digit",
                                    hour12: true,
                                  },
                                )
                                : "-"}
                            </span>
                          )}
                        </TableCell>
                        <TableCell>
                          {editing && editData ? (
                            <span className="text-sm font-medium">
                              {editData.checkIn && editData.checkOut
                                ? `${calculateWorkHours(editData.checkIn, editData.checkOut).toFixed(1)} ساعة`
                                : "-"}
                            </span>
                          ) : (
                            <span className="text-sm">
                              {record.workHours
                                ? `${Number(record.workHours).toFixed(1)} ساعة`
                                : "-"}
                            </span>
                          )}
                        </TableCell>
                        <TableCell>
                          {editing && editData ? (
                            <div className="flex flex-col gap-2 min-w-[140px]">
                              <div className="flex flex-col gap-1 border-b pb-1">
                                <span className="text-[10px] text-gray-500 font-bold">التأخير:</span>
                                <div className="flex items-center gap-1">
                                  <Input
                                    type="number"
                                    min="0"
                                    value={editData.lateHours}
                                    onChange={(e) => updateEditingField(record.id, "lateHours", parseInt(e.target.value) || 0)}
                                    className="w-12 h-7 text-xs px-1 text-center"
                                  />
                                  <span className="text-[10px]">س</span>
                                  <Input
                                    type="number"
                                    min="0"
                                    max="59"
                                    value={editData.lateMins}
                                    onChange={(e) => updateEditingField(record.id, "lateMins", parseInt(e.target.value) || 0)}
                                    className="w-12 h-7 text-xs px-1 text-center"
                                  />
                                  <span className="text-[10px]">د</span>
                                </div>
                              </div>
                              <div className="flex flex-col gap-1">
                                <span className="text-[10px] text-gray-500 font-bold">مبكر:</span>
                                <div className="flex items-center gap-1">
                                  <Input
                                    type="number"
                                    min="0"
                                    value={editData.earlyHours}
                                    onChange={(e) => updateEditingField(record.id, "earlyHours", parseInt(e.target.value) || 0)}
                                    className="w-12 h-7 text-xs px-1 text-center"
                                  />
                                  <span className="text-[10px]">س</span>
                                  <Input
                                    type="number"
                                    min="0"
                                    max="59"
                                    value={editData.earlyMins}
                                    onChange={(e) => updateEditingField(record.id, "earlyMins", parseInt(e.target.value) || 0)}
                                    className="w-12 h-7 text-xs px-1 text-center"
                                  />
                                  <span className="text-[10px]">د</span>
                                </div>
                              </div>
                            </div>
                          ) : (
                            <div className="text-xs space-y-1">
                              {Number(record.lateMinutes || 0) > 0 && (
                                <div className="flex items-center gap-1 text-red-600 bg-red-50 px-1.5 py-0.5 rounded border border-red-100 italic">
                                  <span>تأخير:</span>
                                  <span className="font-bold">
                                    {Math.floor(record.lateMinutes! / 60) > 0 && `${Math.floor(record.lateMinutes! / 60)}س `}
                                    {record.lateMinutes! % 60}د
                                  </span>
                                </div>
                              )}
                              {Number(record.earlyLeaveMinutes || 0) > 0 && (
                                <div className="flex items-center gap-1 text-orange-600 bg-orange-50 px-1.5 py-0.5 rounded border border-orange-100 italic">
                                  <span>مبكر:</span>
                                  <span className="font-bold">
                                    {Math.floor(record.earlyLeaveMinutes! / 60) > 0 && `${Math.floor(record.earlyLeaveMinutes! / 60)}س `}
                                    {record.earlyLeaveMinutes! % 60}د
                                  </span>
                                </div>
                              )}
                              {!record.lateMinutes && !record.earlyLeaveMinutes && <span className="text-gray-400">-</span>}
                            </div>
                          )}
                        </TableCell>
                        <TableCell>
                          {editing ? (
                            <Select
                              value={editData?.status || ""}
                              onValueChange={(value) =>
                                updateEditingField(record.id, "status", value)
                              }
                            >
                              <SelectTrigger className="w-[130px]">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                {statusOptions.map((status) => (
                                  <SelectItem
                                    key={status.value}
                                    value={status.value}
                                  >
                                    {status.label}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          ) : (
                            <Badge className={getStatusColor(record.status)}>
                              {getStatusLabel(record.status)}
                            </Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          {editing ? (
                            <Input
                              value={editData?.notes || ""}
                              onChange={(e) =>
                                updateEditingField(
                                  record.id,
                                  "notes",
                                  e.target.value,
                                )
                              }
                              placeholder="ملاحظات..."
                              className="w-[150px]"
                            />
                          ) : (
                            <span className="text-sm text-gray-600">
                              {record.notes || "-"}
                            </span>
                          )}
                        </TableCell>
                        <TableCell>
                          <div className="flex gap-2">
                            {editing ? (
                              <>
                                <Button
                                  size="sm"
                                  onClick={() => saveRecord(record.id)}
                                  disabled={saving === record.id}
                                  className="bg-green-600 hover:bg-green-700 disabled:opacity-50"
                                >
                                  {saving === record.id ? (
                                    <div className="animate-spin rounded-full h-3 w-3 border-b-2 border-white ml-1" />
                                  ) : (
                                    <Save className="h-3 w-3 ml-1" />
                                  )}
                                  {saving === record.id
                                    ? "جاري الحفظ..."
                                    : "حفظ"}
                                </Button>
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => cancelEditing(record.id)}
                                  disabled={saving === record.id}
                                >
                                  <X className="h-3 w-3 ml-1" />
                                  إلغاء
                                </Button>
                              </>
                            ) : (
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => startEditing(record)}
                              >
                                <Edit2 className="h-3 w-3 ml-1" />
                                تعديل
                              </Button>
                            )}
                          </div>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>

        {pagination.totalPages > 1 && (
          <div className="flex items-center justify-between p-4 border-t">
            <p className="text-sm text-gray-500">
              عرض {(pagination.page - 1) * pagination.limit + 1} -{" "}
              {Math.min(pagination.page * pagination.limit, pagination.total)}{" "}
              من {pagination.total}
            </p>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={pagination.page === 1}
                onClick={() =>
                  setPagination((prev) => ({ ...prev, page: prev.page - 1 }))
                }
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={pagination.page === pagination.totalPages}
                onClick={() =>
                  setPagination((prev) => ({ ...prev, page: prev.page + 1 }))
                }
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
};

export default ManualAttendanceEdit;

import React, { useState, useEffect } from "react";
import { useAuth } from "../../hooks/useAuthSimple";
import api from "../../services/api";
import { toast } from "sonner";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Badge } from "../../components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../../components/ui/dialog";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Textarea } from "../../components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import { Loader2, PlusIcon } from "lucide-react";
import { BanknotesIcon } from "@heroicons/react/24/outline";
import { useDateFormat } from "../../hooks/useDateFormat";

const MyAdvances: React.FC = () => {
  const { user } = useAuth();
  const { formatDate } = useDateFormat();
  const [advances, setAdvances] = useState<any[]>([]);
  const [loadingAdvances, setLoadingAdvances] = useState(false);
  const [isAdvanceDialogOpen, setIsAdvanceDialogOpen] = useState(false);
  const [advanceForm, setAdvanceForm] = useState({
    amount: "",
    reason: "",
    repaymentType: "ONE_TIME", // ✅ FIX: Backend expects ONE_TIME not FULL
    installmentsCount: "1",
  });
  const [submittingAdvance, setSubmittingAdvance] = useState(false);
  const [employeeId, setEmployeeId] = useState<string | null>(null);

  useEffect(() => {
    const fetchEmployeeId = async () => {
      try {
        // ✅ FIX: Use the user's own ID (userId) not the Employee table record ID
        // The backend advanceService stores advances by userId, not employeeRelId
        const response = await api.get("/hr/employees/me");
        if (response.data && response.data.employee) {
          // Use userId (user.id) for advance requests, not employee record id
          setEmployeeId(response.data.employee.userId || response.data.employee.id);
        }
      } catch (error) {
        console.error("Failed to fetch employee ID", error);
        // Fallback: the backend will use req.user.id from the token anyway
      }
    };
    fetchEmployeeId();
    fetchAdvances();
  }, []);

  const fetchAdvances = async () => {
    try {
      setLoadingAdvances(true);
      const response = await api.get("/hr/advances/my");
      if (response.data && response.data.success) {
        setAdvances(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching advances:", error);
      toast.error("فشل في جلب بيانات السلف");
    } finally {
      setLoadingAdvances(false);
    }
  };

  const handleAdvanceSubmit = async () => {
    if (!advanceForm.amount || !advanceForm.reason) {
      toast.error("يرجى تعبئة جميع الحقول المطلوبة");
      return;
    }

    try {
      setSubmittingAdvance(true);
      const payload = {
        employeeId: employeeId, // Use fetched employee ID
        amount: parseFloat(advanceForm.amount),
        reason: advanceForm.reason,
        repaymentType: advanceForm.repaymentType,
        installmentsCount: parseInt(advanceForm.installmentsCount),
      };

      const response = await api.post("/hr/advances", payload);

      if (response.data && response.data.success) {
        toast.success("تم إرسال طلب السلفة بنجاح");
        setIsAdvanceDialogOpen(false);
        setAdvanceForm({
          amount: "",
          reason: "",
          repaymentType: "ONE_TIME",
          installmentsCount: "1",
        });
        fetchAdvances();
      }
    } catch (error: any) {
      console.error("Error creating advance request:", error);
      toast.error(error.response?.data?.error || "فشل في إنشاء طلب السلفة");
    } finally {
      setSubmittingAdvance(false);
    }
  };

  return (
    <div className="container mx-auto p-6" dir="rtl">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <BanknotesIcon className="w-8 h-8 text-blue-600" />
            السلف المالية
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            إدارة وطلب السلف المالية الخاصة بك
          </p>
        </div>
        <Dialog
          open={isAdvanceDialogOpen}
          onOpenChange={setIsAdvanceDialogOpen}
        >
          <DialogTrigger asChild>
            <button className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition shadow-sm">
              <PlusIcon className="w-5 h-5 ml-2" />
              طلب سلفة جديدة
            </button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[425px]" dir="rtl">
            <DialogHeader>
              <DialogTitle className="text-right">طلب سلفة جديدة</DialogTitle>
              <DialogDescription className="text-right">
                قم بملء النموذج أدناه لطلب سلفة مالية. سيتم مراجعة الطلب من قبل
                الإدارة.
              </DialogDescription>
            </DialogHeader>
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label htmlFor="amount" className="text-right">
                  المبلغ المطلوب
                </Label>
                <Input
                  id="amount"
                  type="number"
                  placeholder="0.00"
                  className="text-right"
                  value={advanceForm.amount}
                  onChange={(e) =>
                    setAdvanceForm({ ...advanceForm, amount: e.target.value })
                  }
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="reason" className="text-right">
                  سبب السلفة
                </Label>
                <Textarea
                  id="reason"
                  placeholder="مثال: ظروف طارئة..."
                  className="text-right"
                  value={advanceForm.reason}
                  onChange={(e) =>
                    setAdvanceForm({ ...advanceForm, reason: e.target.value })
                  }
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="repaymentType" className="text-right">
                  طريقة السداد
                </Label>
                <Select
                  value={advanceForm.repaymentType}
                  onValueChange={(value) =>
                    setAdvanceForm({ ...advanceForm, repaymentType: value })
                  }
                >
                  <SelectTrigger className="w-full dir-rtl">
                    <SelectValue placeholder="اختر طريقة السداد" />
                  </SelectTrigger>
                  <SelectContent dir="rtl">
                    <SelectItem value="ONE_TIME">دفعة واحدة (الشهر القادم)</SelectItem>
                    <SelectItem value="INSTALLMENTS">
                      تقسيط على دفعات
                    </SelectItem>
                  </SelectContent>
                </Select>
              </div>
              {advanceForm.repaymentType === "INSTALLMENTS" && (
                <div className="grid gap-2">
                  <Label htmlFor="installments" className="text-right">
                    عدد الأقساط (أشهر)
                  </Label>
                  <Input
                    id="installments"
                    type="number"
                    min="1"
                    max="12"
                    className="text-right"
                    value={advanceForm.installmentsCount}
                    onChange={(e) =>
                      setAdvanceForm({
                        ...advanceForm,
                        installmentsCount: e.target.value,
                      })
                    }
                  />
                </div>
              )}
            </div>
            <DialogFooter>
              <button
                onClick={handleAdvanceSubmit}
                disabled={submittingAdvance}
                className={`flex items-center justify-center w-full px-4 py-2 rounded-lg text-white transition shadow-sm bg-green-600 hover:bg-green-700 disabled:opacity-50`}
              >
                {submittingAdvance ? (
                  <Loader2 className="w-4 h-4 animate-spin ml-2" />
                ) : null}
                إرسال الطلب
              </button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>سجل طلبات السلف</CardTitle>
        </CardHeader>
        <CardContent>
          {loadingAdvances ? (
            <div className="flex justify-center py-8">
              <Loader2 className="w-8 h-8 animate-spin text-blue-500" />
            </div>
          ) : advances.length === 0 ? (
            <div className="text-center py-12 bg-gray-50 dark:bg-black/20 rounded-lg dashed border-2 border-gray-200 dark:border-gray-800">
              <BanknotesIcon className="w-12 h-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
              <p className="text-gray-500 dark:text-gray-400">
                لا توجد طلبات سلف سابقة
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table dir="rtl">
                <TableHeader>
                  <TableRow>
                    <TableHead className="text-right">التاريخ</TableHead>
                    <TableHead className="text-right">المبلغ</TableHead>
                    <TableHead className="text-right">السبب</TableHead>
                    <TableHead className="text-right">الحالة</TableHead>
                    <TableHead className="text-right">السداد</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {advances.map((advance) => (
                    <TableRow key={advance.id}>
                      <TableCell>{formatDate(advance.createdAt)}</TableCell>
                      <TableCell className="font-bold">
                        {advance.amount.toLocaleString()} ج.م
                      </TableCell>
                      <TableCell
                        className="max-w-[200px] truncate"
                        title={advance.reason}
                      >
                        {advance.reason}
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant={
                            advance.status === "APPROVED"
                              ? "default"
                              : advance.status === "REJECTED"
                                ? "destructive"
                                : "secondary"
                          }
                        >
                          {advance.status === "APPROVED"
                            ? "تمت الموافقة"
                            : advance.status === "REJECTED"
                              ? "مرفوض"
                              : "قيد الانتظار"}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {advance.repaymentType === "INSTALLMENTS"
                          ? `${advance.installmentsCount} أقساط`
                          : "دفعة واحدة"}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default MyAdvances;

import React, { useState, useEffect, useCallback, useMemo } from "react";
import {
  BuildingOffice2Icon,
  UsersIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowDownTrayIcon,
  CalendarDaysIcon,
  ClockIcon,
  ShoppingCartIcon,
  CurrencyDollarIcon,
  ChatBubbleLeftRightIcon,
  ExclamationTriangleIcon,
  ArrowRightIcon,
  ChartBarIcon,
  PlusIcon,
} from "@heroicons/react/24/outline";
import { toast } from "react-hot-toast";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import CreateCompanyModal from "../../components/CreateCompanyModal";
import { useAuth } from "../../hooks/useAuthSimple";
import { createStorageKey, getWithExpiry, setWithExpiry } from "../../utils/storage";

// Types
interface CompanyStats {
  company: {
    id: string;
    name: string;
    logo: string | null;
    plan: string;
    isDefault?: boolean;
  };
  stats: {
    totalUsers: number;
    todayOrders: number;
    todayRevenue: number;
    unreadConversations: number;
    lowStockProducts: number;
    attendance: {
      present: number;
      late: number;
      absent: number;
    };
  };
}

interface DashboardOverview {
  totalCompanies: number;
  totalUsers: number;
  totalTodayOrders: number;
  totalTodayRevenue: number;
  totalUnreadConversations: number;
  totalLowStockProducts: number;
}

interface DashboardResponse {
  success: boolean;
  data: {
    overview: DashboardOverview;
    byCompany: CompanyStats[];
  };
}

const MyCompaniesDashboard: React.FC = () => {
  const navigate = useNavigate();
  const { switchCompany } = useAuth();
  const [activeTab, setActiveTab] = useState<
    "overview" | "reports" | "attendance"
  >("overview");
  const [isLoading, setIsLoading] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [dashboardData, setDashboardData] = useState<
    DashboardResponse["data"] | null
  >(null);
  const [error, setError] = useState<string | null>(null);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

  const CACHE_TTL_MS = 60_000;

  const cacheKey = useMemo(() => {
    try {
      const rawUser = localStorage.getItem("user");
      const parsedUser = rawUser ? JSON.parse(rawUser) : null;
      const userId = parsedUser?.id || parsedUser?.userId || "unknown";
      return createStorageKey("owner-dashboard", userId);
    } catch {
      return createStorageKey("owner-dashboard", "unknown");
    }
  }, []);

  // Filter States
  const [currentDate] = useState(new Date());
  const [selectedMonth, setSelectedMonth] = useState(
    currentDate.getMonth() + 1,
  );
  const [selectedYear, setSelectedYear] = useState(currentDate.getFullYear());

  // Helper to construct image URL
  const getImageUrl = (path: string | null) => {
    if (!path) return null;
    if (path.startsWith("http")) return path;
    const backendUrl =
      import.meta.env["VITE_API_URL"]?.replace("/api/v1", "") ||
      "http://localhost:3007";
    return `${backendUrl}/${path.replace(/^\/+/, "")}`;
  };

  const fetchDashboard = useCallback(async ({ signal, background = false } = {}) => {
    try {
      if (!background) {
        setIsLoading(true);
        setError(null);
      }

      const response = await apiClient.get("owner/dashboard", { signal });
      if (response.data.success) {
        setDashboardData(response.data.data);
        setWithExpiry(cacheKey, response.data.data, CACHE_TTL_MS);
      } else {
        const message = response.data.message || "فشل تحميل البيانات";
        if (!background) {
          setError(message);
          toast.error(message);
        }
      }
    } catch (error) {
      console.error("Failed to fetch dashboard", error);
      if (!background) {
        setError("فشل تحميل لوحة التحكم");
        toast.error("فشل تحميل لوحة التحكم");
      }
    } finally {
      if (!background) {
        setIsLoading(false);
      }
    }
  }, [cacheKey]);

  useEffect(() => {
    const controller = new AbortController();
    const cached = getWithExpiry<DashboardResponse["data"]>(cacheKey);

    if (cached) {
      setDashboardData(cached);
      setIsLoading(false);
      fetchDashboard({ signal: controller.signal, background: true });
    } else {
      fetchDashboard({ signal: controller.signal });
    }

    return () => controller.abort();
  }, [cacheKey, fetchDashboard]);

  const handleExport = async () => {
    try {
      setIsExporting(true);
      // TODO: Implement export
      toast.success("جاري التصدير...");
    } catch (error) {
      toast.error("فشل التصدير");
    } finally {
      setIsExporting(false);
    }
  };

  const switchToCompany = async (companyId: string) => {
    try {
      const switched = await switchCompany(companyId);
      if (switched) {
        navigate("/company-dashboard");
        return;
      }
      toast.error("فشل في تبديل الشركة. حاول مرة أخرى.");
    } catch (error) {
      console.error("Error switching company:", error);
      toast.error("فشل في تبديل الشركة. حاول مرة أخرى.");
    }
  };

  const handleSetDefaultCompany = async (companyId: string, companyName: string) => {
    try {
      const response = await apiClient.post(`/auth/set-default-company/${companyId}`);
      if (response.data.success) {
        toast.success(`تم تعيين ${companyName} كشركة افتراضية`);
        fetchDashboard({ background: true });
      } else {
        toast.error(response.data.message || "فشل تعيين الشركة كافتراضية");
      }
    } catch (error) {
      console.error("Error setting default company:", error);
      toast.error("فشل تعيين الشركة كافتراضية");
    }
  };

  if (isLoading && !dashboardData) {
    return <DashboardSkeleton />;
  }

  if (error && !dashboardData) {
    return (
      <div className="flex items-center justify-center h-64 text-gray-500">
        {error}
      </div>
    );
  }

  const overview = dashboardData?.overview;
  const companies = dashboardData?.byCompany || [];

  return (
    <div
      className="p-6 space-y-6 bg-gray-50 dark:bg-gray-900 min-h-screen"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-center bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 dark:text-white">
            لوحة تحكم شركاتي
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            متابعة شاملة لجميع فروعك وشركاتك من مكان واحد
          </p>
        </div>
        <div className="mt-4 md:mt-0 flex gap-3">
          <div className="flex bg-gray-100 dark:bg-gray-700 p-1 rounded-lg">
            <button
              onClick={() => setActiveTab("overview")}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === "overview" ? "bg-white dark:bg-gray-600 text-blue-600 dark:text-blue-400 shadow-sm" : "text-gray-500 dark:text-gray-400 hover:text-gray-700"}`}
            >
              نظرة عامة
            </button>
            <button
              onClick={() => setActiveTab("attendance")}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === "attendance" ? "bg-white dark:bg-gray-600 text-blue-600 dark:text-blue-400 shadow-sm" : "text-gray-500 dark:text-gray-400 hover:text-gray-700"}`}
            >
              الحضور
            </button>
            <button
              onClick={() => setActiveTab("reports")}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === "reports" ? "bg-white dark:bg-gray-600 text-blue-600 dark:text-blue-400 shadow-sm" : "text-gray-500 dark:text-gray-400 hover:text-gray-700"}`}
            >
              التقارير
            </button>
          </div>
          <button
            onClick={() => setIsCreateModalOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
          >
            <PlusIcon className="w-5 h-5" />
            <span>إضافة شركة</span>
          </button>
          <button
            onClick={handleExport}
            disabled={isExporting}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition-colors disabled:opacity-50"
          >
            {isExporting ? (
              <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              <ArrowDownTrayIcon className="w-5 h-5" />
            )}
            <span>تصدير</span>
          </button>
        </div>
      </div>

      {activeTab === "overview" && overview && (
        <div className="space-y-6 animate-fadeIn">
          {/* Overview Stats */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
            <StatCard
              title="الشركات"
              value={overview.totalCompanies}
              icon={<BuildingOffice2Icon className="w-6 h-6" />}
              color="bg-gradient-to-r from-blue-500 to-blue-600"
              textColor="text-white"
            />
            <StatCard
              title="الموظفين"
              value={overview.totalUsers}
              icon={<UsersIcon className="w-6 h-6" />}
              color="bg-white dark:bg-gray-800"
            />
            <StatCard
              title="طلبات اليوم"
              value={overview.totalTodayOrders}
              icon={<ShoppingCartIcon className="w-6 h-6" />}
              color="bg-white dark:bg-gray-800"
            />
            <StatCard
              title="إيرادات اليوم"
              value={`${overview.totalTodayRevenue.toLocaleString()} ج.م`}
              icon={<CurrencyDollarIcon className="w-6 h-6" />}
              color="bg-gradient-to-r from-green-500 to-green-600"
              textColor="text-white"
            />
            <StatCard
              title="رسائل جديدة"
              value={overview.totalUnreadConversations}
              icon={<ChatBubbleLeftRightIcon className="w-6 h-6" />}
              color="bg-white dark:bg-gray-800"
              alert={overview.totalUnreadConversations > 10}
            />
            <StatCard
              title="منتجات نفذت"
              value={overview.totalLowStockProducts}
              icon={<ExclamationTriangleIcon className="w-6 h-6" />}
              color="bg-white dark:bg-gray-800"
              alert={overview.totalLowStockProducts > 0}
            />
          </div>

          {/* Companies Grid */}
          <h2 className="text-lg font-bold text-gray-800 dark:text-white">
            الشركات
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {companies.map((item) => (
              <div
                key={item.company.id}
                className="bg-white dark:bg-gray-800 p-5 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 hover:shadow-md transition-all"
              >
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 bg-gray-100 dark:bg-gray-700 rounded-lg flex items-center justify-center overflow-hidden">
                      {item.company.logo ? (
                        <img
                          src={getImageUrl(item.company.logo) || ""}
                          alt={item.company.name}
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <BuildingOffice2Icon className="w-6 h-6 text-gray-400" />
                      )}
                    </div>
                    <div>
                      <h3 className="font-bold text-gray-800 dark:text-white flex items-center gap-2">
                        {item.company.name}
                        {item.company.isDefault && (
                          <span className="px-1.5 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 text-[10px] font-medium rounded-full border border-green-200 dark:border-green-800">
                            الافتراضية
                          </span>
                        )}
                      </h3>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {item.company.plan} • {item.stats.totalUsers} موظف
                      </p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <button
                      onClick={() => switchToCompany(item.company.id)}
                      className="flex items-center gap-1 text-blue-600 hover:text-blue-700 text-sm font-medium"
                    >
                      إدارة <ArrowRightIcon className="w-4 h-4" />
                    </button>
                    {!item.company.isDefault && (
                      <button
                        onClick={() => handleSetDefaultCompany(item.company.id, item.company.name)}
                        className="text-[10px] text-gray-400 hover:text-blue-500 transition-colors"
                      >
                        تعيين كافتراضية
                      </button>
                    )}
                  </div>
                </div>

                {/* Stats Grid */}
                <div className="grid grid-cols-3 gap-3 mt-4">
                  <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg text-center">
                    <ShoppingCartIcon className="w-5 h-5 mx-auto text-blue-600 mb-1" />
                    <p className="text-lg font-bold text-gray-800 dark:text-white">
                      {item.stats.todayOrders}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      طلب
                    </p>
                  </div>
                  <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-lg text-center">
                    <CurrencyDollarIcon className="w-5 h-5 mx-auto text-green-600 mb-1" />
                    <p className="text-lg font-bold text-gray-800 dark:text-white">
                      {item.stats.todayRevenue.toLocaleString()}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      ج.م
                    </p>
                  </div>
                  <div
                    className={`p-3 rounded-lg text-center ${item.stats.unreadConversations > 0 ? "bg-orange-50 dark:bg-orange-900/20" : "bg-gray-50 dark:bg-gray-700"}`}
                  >
                    <ChatBubbleLeftRightIcon
                      className={`w-5 h-5 mx-auto mb-1 ${item.stats.unreadConversations > 0 ? "text-orange-600" : "text-gray-400"}`}
                    />
                    <p className="text-lg font-bold text-gray-800 dark:text-white">
                      {item.stats.unreadConversations}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      رسالة
                    </p>
                  </div>
                </div>

                {/* Alerts */}
                {item.stats.lowStockProducts > 0 && (
                  <div className="mt-4 p-3 bg-red-50 dark:bg-red-900/20 rounded-lg flex items-center gap-2">
                    <ExclamationTriangleIcon className="w-5 h-5 text-red-600" />
                    <span className="text-sm text-red-700 dark:text-red-400">
                      {item.stats.lowStockProducts} منتج على وشك النفاد
                    </span>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === "attendance" && (
        <div className="space-y-6 animate-fadeIn">
          <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 flex gap-4 items-center">
            <div className="flex items-center gap-2">
              <CalendarDaysIcon className="w-5 h-5 text-gray-400" />
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="form-select rounded-md border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white shadow-sm focus:border-blue-500 focus:ring-blue-500"
              >
                {Array.from({ length: 12 }, (_, i) => i + 1).map((m) => (
                  <option key={m} value={m}>
                    {new Date(0, m - 1).toLocaleString("ar-EG", {
                      month: "long",
                    })}
                  </option>
                ))}
              </select>
            </div>
            <div className="flex items-center gap-2">
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(Number(e.target.value))}
                className="form-select rounded-md border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white shadow-sm focus:border-blue-500 focus:ring-blue-500"
              >
                {[2024, 2025, 2026].map((y) => (
                  <option key={y} value={y}>
                    {y}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Attendance by Company */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {companies.map((item) => (
              <div
                key={item.company.id}
                className="bg-white dark:bg-gray-800 p-5 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700"
              >
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-10 h-10 bg-gray-100 dark:bg-gray-700 rounded-lg flex items-center justify-center">
                    {item.company.logo ? (
                      <img
                        src={getImageUrl(item.company.logo) || ""}
                        alt=""
                        className="w-full h-full object-cover rounded-lg"
                      />
                    ) : (
                      <BuildingOffice2Icon className="w-5 h-5 text-gray-400" />
                    )}
                  </div>
                  <div>
                    <h3 className="font-bold text-gray-800 dark:text-white">
                      {item.company.name}
                    </h3>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      {item.stats.totalUsers} موظف
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-3">
                  <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-lg text-center">
                    <CheckCircleIcon className="w-5 h-5 mx-auto text-green-600 mb-1" />
                    <p className="text-xl font-bold text-gray-800 dark:text-white">
                      {item.stats.attendance.present}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      حاضر
                    </p>
                  </div>
                  <div className="p-3 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg text-center">
                    <ClockIcon className="w-5 h-5 mx-auto text-yellow-600 mb-1" />
                    <p className="text-xl font-bold text-gray-800 dark:text-white">
                      {item.stats.attendance.late}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      متأخر
                    </p>
                  </div>
                  <div className="p-3 bg-red-50 dark:bg-red-900/20 rounded-lg text-center">
                    <XCircleIcon className="w-5 h-5 mx-auto text-red-600 mb-1" />
                    <p className="text-xl font-bold text-gray-800 dark:text-white">
                      {item.stats.attendance.absent}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      غائب
                    </p>
                  </div>
                </div>

                {/* Attendance Bar */}
                <div className="mt-4 h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden flex">
                  <div
                    style={{
                      width: `${(item.stats.attendance.present / item.stats.totalUsers) * 100}%`,
                    }}
                    className="bg-green-500 h-full"
                  />
                  <div
                    style={{
                      width: `${(item.stats.attendance.late / item.stats.totalUsers) * 100}%`,
                    }}
                    className="bg-yellow-500 h-full"
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === "reports" && (
        <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 text-center">
          <ChartBarIcon className="w-16 h-16 mx-auto text-gray-300 dark:text-gray-600 mb-4" />
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-2">
            التقارير الموحدة
          </h3>
          <p className="text-gray-500 dark:text-gray-400 mb-4">
            قريباً... يمكنك الوصول للتقارير من صفحة التقارير الموحدة
          </p>
          <button
            onClick={() => navigate("/my-companies/reports")}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            الذهاب للتقارير
          </button>
        </div>
      )}

      {/* Create Company Modal */}
      <CreateCompanyModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onSuccess={() => {
          fetchDashboard({ background: true });
        }}
      />
    </div>
  );
};

// Reusable Components
const StatCard = ({
  title,
  value,
  icon,
  subValue,
  color,
  textColor = "text-gray-800 dark:text-white",
  alert = false,
}: any) => (
  <div
    className={`${color} p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-transform hover:-translate-y-1 ${alert ? "ring-2 ring-red-400" : ""}`}
  >
    <div className="flex justify-between items-start">
      <div>
        <p
          className={`text-xs font-medium ${textColor === "text-white" ? "text-white/70" : "text-gray-500 dark:text-gray-400"}`}
        >
          {title}
        </p>
        <h3 className={`text-xl font-bold mt-1 ${textColor}`}>{value}</h3>
        {subValue && (
          <p
            className={`text-xs mt-1 ${textColor === "text-white" ? "text-white/70" : "text-gray-500"}`}
          >
            {subValue}
          </p>
        )}
