interface Payroll {
  id: string;
  month: number;
  year: number;
  baseSalary: number;
  fullMonthBaseSalary?: number; // الراتب الشهري الكامل
  totalAllowances: number;
  totalDeductions: number;
  overtimeAmount: number;
  bonuses: number;
  socialInsurance: number;
  taxAmount: number;
  grossSalary: number;
  netSalary: number;
  attendanceDeduction: number;
  absentDays: number;
  latePenalty: number;
  status: string;
  paidAt: string | null;
  allowances: string | null; // JSON string
