import React, { useState, useEffect } from "react";
import {
  GraduationCap,
  Plus,
  Calendar,
  DollarSign,
  Award,
  Clock,
  User,
  Edit2,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { useNavigate, useParams } from "react-router-dom";
import api from "../../services/api";
import { toast } from "sonner";

interface Training {
  id: string;
  trainingName: string;
  provider?: string;
  type: string;
  startDate: string;
  endDate?: string;
  status: string;
  cost?: number;
  duration?: number;
  score?: number;
}

const Training: React.FC = () => {
  const { employeeId } = useParams<{ employeeId?: string }>();
  const navigate = useNavigate();
  const [trainings, setTrainings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchTrainings();
  }, [employeeId]);

  const fetchTrainings = async () => {
    try {
      setLoading(true);
      const url = employeeId
        ? `/hr/trainings/employee/${employeeId}`
        : "/hr/trainings";
      const response = await api.get(url);
      setTrainings(response.data.trainings || []);
    } catch (error) {
      console.error("Error fetching trainings:", error);
      toast.error("فشل في جلب سجلات التدريب");
    } finally {
      setLoading(false);
    }
  };

  const getStatusLabel = (status: string) => {
    const map: any = {
      PLANNED: {
        label: "مخطط",
        class: "bg-blue-100 text-blue-700 border-blue-200",
      },
      ONGOING: {
        label: "قيد التنفيذ",
        class: "bg-amber-100 text-amber-700 border-amber-200",
      },
      COMPLETED: {
        label: "مكتمل",
        class: "bg-emerald-100 text-emerald-700 border-emerald-200",
      },
      CANCELLED: {
        label: "ملغي",
        class: "bg-rose-100 text-rose-700 border-rose-200",
      },
    };
    return map[status] || { label: status, class: "bg-gray-100 text-gray-700" };
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-4 border-purple-600"></div>
          <p className="text-purple-600 font-bold animate-pulse">
            جاري تحميل السجلات...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="hr-theme min-h-screen p-6 md:p-8 space-y-8" dir="rtl">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div className="animate-in fade-in slide-in-from-right-4 duration-500">
          <h1 className="text-4xl font-black tracking-tight text-transparent bg-clip-text bg-gradient-to-r from-purple-700 via-pink-600 to-indigo-600">
            التدريب والتطوير
          </h1>
          <p className="text-gray-500 font-medium flex items-center gap-2 mt-1">
            <Award className="h-4 w-4 text-purple-400" />
            إدارة وقياس أثر البرامج التدريبية للموظفين
          </p>
        </div>
        <Button
          onClick={() => navigate("/hr/training/new")}
          className="bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white font-bold px-6 py-6 rounded-2xl shadow-xl shadow-purple-200 transition-all hover:scale-105 active:scale-95 animate-in fade-in slide-in-from-left-4 duration-500"
        >
          <Plus className="h-5 w-5 ml-2" />
          إضافة برنامج تدريب
        </Button>
      </div>

      {trainings.length === 0 ? (
        <Card className="border-none shadow-2xl bg-white/50 backdrop-blur-md p-16 animate-in zoom-in-95 duration-500">
          <CardContent className="flex flex-col items-center text-center space-y-6">
            <div className="w-24 h-24 bg-purple-50 rounded-full flex items-center justify-center text-purple-200">
              <GraduationCap className="h-12 w-12" />
            </div>
            <div className="space-y-2">
              <h3 className="text-2xl font-black text-gray-800">
                لا يوجد سجلات حالياً
              </h3>
              <p className="text-gray-500 max-w-sm mx-auto">
                لم يتم توثيق أي برامج تدريبية بعد. ابدأ بإضافة أول برنامج
                لموظفيك الآن.
              </p>
            </div>
            <Button
              variant="outline"
              onClick={() => navigate("/hr/training/new")}
              className="rounded-xl border-purple-200 text-purple-700 hover:bg-purple-50 px-8"
            >
              إضافة برنامجك الأول
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
          {trainings.map((training, index) => {
            const status = getStatusLabel(training.status);
            return (
              <Card
                key={training.id}
                className="group border-none shadow-lg hover:shadow-2xl transition-all duration-300 hover:-translate-y-2 overflow-hidden bg-white/70 backdrop-blur-sm cursor-pointer ring-1 ring-purple-100/50"
                onClick={() => navigate(`/hr/training/${training.id}`)}
              >
                <div className="h-1.5 w-full bg-gradient-to-r from-purple-500 via-indigo-500 to-pink-500 opacity-60 group-hover:opacity-100 transition-opacity" />
                <CardHeader className="pb-2">
                  <div className="flex items-start justify-between">
                    <div className="p-3 bg-purple-50 rounded-2xl text-purple-600 group-hover:scale-110 transition-transform">
                      <GraduationCap className="h-6 w-6" />
                    </div>
                    <span
                      className={`px-2 py-1 rounded-lg text-[10px] font-black border ${status.class}`}
                    >
                      {status.label}
                    </span>
                  </div>
                  <CardTitle className="text-xl font-black mt-4 leading-tight group-hover:text-purple-700 transition-colors">
                    {training.trainingName}
                  </CardTitle>
                  <div className="flex items-center gap-2 mt-2">
                    <div className="w-6 h-6 rounded-full bg-indigo-100 flex items-center justify-center">
                      <User className="w-3.5 h-3.5 text-indigo-600" />
                    </div>
                    <span className="text-sm font-bold text-gray-700">
                      {training.employee?.firstName}{" "}
                      {training.employee?.lastName}
                    </span>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4 pt-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider flex items-center gap-1">
                        <Calendar className="h-3 w-3" /> تاريخ البدء
                      </p>
                      <p className="text-xs font-bold text-gray-700">
                        {new Date(training.startDate).toLocaleDateString(
                          "ar-EG",
                          { day: "numeric", month: "long", year: "numeric" },
                        )}
                      </p>
                    </div>
                    {training.duration && (
                      <div className="space-y-1">
                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider flex items-center gap-1">
                          <Clock className="h-3 w-3" /> المدة
                        </p>
                        <p className="text-xs font-bold text-gray-700">
                          {training.duration} ساعة
                        </p>
                      </div>
                    )}
                  </div>

                  <div className="pt-4 border-t border-gray-50 flex items-center justify-between">
                    {training.cost ? (
                      <div className="flex flex-col">
                        <p className="text-[10px] font-bold text-gray-400 uppercase flex items-center gap-1">
                          <DollarSign className="h-3 w-3" /> الاستثمار
                        </p>
                        <p className="text-sm font-black text-purple-600">
                          {training.cost.toLocaleString()}{" "}
                          <span className="text-[10px] font-bold opacity-60">
                            EGP
                          </span>
                        </p>
                      </div>
                    ) : (
                      <div />
                    )}

                    {training.score ? (
                      <div className="flex flex-col items-end">
                        <p className="text-[10px] font-bold text-gray-400 uppercase flex items-center gap-1">
                          <Award className="h-3 w-3" /> التقييم
                        </p>
                        <p className="text-sm font-black text-amber-500">
                          %{training.score}
                        </p>
                      </div>
                    ) : null}
                  </div>

                  {/* Edit Button */}
                  <div className="pt-2">
                    <Button
                      variant="secondary"
                      className="w-full rounded-xl font-bold bg-purple-50 text-purple-700 hover:bg-purple-100 border-none shadow-sm transition-all flex items-center justify-center gap-2"
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate(`/hr/training/${training.id}`);
                      }}
                    >
                      <Edit2 className="h-3.5 w-3.5" />
                      تعديل بيانات التدريب
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default Training;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  AlertTriangle,
  Calendar,
  User,
  FileText,
  ArrowRight,
  Edit,
  Trash2,
  Clock,
  CheckCircle2,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription
} from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import api from "../../services/api";
import { toast } from "sonner";

interface Warning {
  id: string;
  type: string;
  severity: string;
  title: string;
  description: string;
  incidentDate: string;
  actionTaken?: string;
  employeeResponse?: string;
  acknowledgedAt?: string;
  attachments?: string[];
  createdAt: string;
  updatedAt: string;
  employee: {
    id: string;
    firstName: string;
    lastName: string;
    employeeNumber: string;
    position?: { title: string };
    department?: { name: string };
  };
}

const WarningDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [warning, setWarning] = useState<Warning | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (id) {
      fetchWarning();
    }
  }, [id]);

  const fetchWarning = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/hr/warnings/${id}`);
      setWarning(response.data.warning);
    } catch (error: any) {
      console.error("Error fetching warning:", error);
      toast.error(error.response?.data?.error || "فشل في جلب تفاصيل الإنذار");
      navigate("/hr/warnings");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm("هل أنت متأكد من حذف هذا الإنذار؟")) {
      return;
    }

    try {
      await api.delete(`/hr/warnings/${id}`);
      toast.success("تم حذف الإنذار بنجاح");
      navigate("/hr/warnings");
    } catch (error: any) {
      console.error("Error deleting warning:", error);
      toast.error(error.response?.data?.error || "فشل في حذف الإنذار");
    }
  };

  const getTypeLabel = (type: string) => {
    const typeMap: Record<string, string> = {
      VERBAL: "شفوي",
      WRITTEN: "كتابي",
      FINAL: "نهائي",
      TERMINATION: "إنهاء خدمة",
    };
    return typeMap[type] || type;
  };

  const getSeverityColor = (severity: string) => {
    const colorMap: Record<string, string> = {
      minor: "bg-yellow-100 text-yellow-800",
      moderate: "bg-orange-100 text-orange-800",
      severe: "bg-red-100 text-red-800",
    };
    return colorMap[severity] || "bg-gray-100 text-gray-800";
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!warning) {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="p-12 text-center">
            <AlertTriangle className="h-16 w-16 mx-auto mb-4 text-gray-400" />
            <p className="text-gray-500 mb-4">الإنذار غير موجود</p>
            <Button onClick={() => navigate("/hr/warnings")}>
              العودة للإنذارات
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 max-w-full lg:max-w-7xl mx-auto overflow-hidden" dir="rtl">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white dark:bg-gray-900 p-6 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-sm">
        <div className="flex items-center gap-5 min-w-0 flex-1">
          <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-2xl text-blue-600 dark:text-blue-400 flex-shrink-0">
            <AlertTriangle className="h-8 w-8" />
          </div>
          <div className="flex-1 min-w-0 overflow-hidden">
            <div className="flex items-center gap-3 flex-wrap">
              <h1
                className="text-xl sm:text-3xl font-black text-gray-900 dark:text-white leading-tight"
                style={{ wordBreak: 'break-all', overflowWrap: 'anywhere' }}
              >
                {warning.title}
              </h1>
              <div className="flex gap-2">
                <Badge className={`${getSeverityColor(warning.severity)} border-none py-1 px-4 rounded-full text-[10px] font-bold`}>
                  {warning.severity === 'minor' ? 'بسيط' : warning.severity === 'moderate' ? 'متوسط' : 'جسيم'}
                </Badge>
                <Badge variant="outline" className="border-blue-200 text-blue-700 bg-blue-50/50 py-1 px-4 rounded-full text-[10px] font-bold">
                  {getTypeLabel(warning.type)}
                </Badge>
              </div>
            </div>
            <p className="text-gray-500 mt-2 flex items-center gap-2">
              <User className="h-4 w-4" />
              إنذار خاص بالموظف: <span className="font-bold text-gray-700 dark:text-gray-300">{warning.employee.firstName} {warning.employee.lastName}</span>
            </p>
          </div>
        </div>
        <div className="flex gap-3">
          <Button
            variant="outline"
            onClick={() => navigate(`/hr/warnings/${id}/edit`)}
            className="rounded-xl px-6"
          >
            <Edit className="h-4 w-4 ml-2" />
            تعديل
          </Button>
          <Button
            variant="destructive"
            onClick={handleDelete}
            className="rounded-xl px-6 shadow-lg shadow-red-500/20"
          >
            <Trash2 className="h-4 w-4 ml-2" />
            حذف
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full">
        <div className="lg:col-span-2 space-y-6 min-w-0">
          {/* Description Card */}
          <Card className="border-none shadow-sm overflow-hidden rounded-3xl">
            <CardHeader className="bg-gray-50 dark:bg-white/5 border-b border-gray-100 dark:border-white/5 p-6">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-500 rounded-lg">
                  <FileText className="h-5 w-5 text-white" />
                </div>
                <div>
                  <CardTitle className="text-lg font-bold">وصف المخالفة</CardTitle>
                  <CardDescription>تفاصيل الواقعة كما تم تسجيلها</CardDescription>
                </div>
              </div>
            </CardHeader>
            <CardContent className="p-8">
              <div className="bg-blue-50/30 dark:bg-blue-900/5 p-6 rounded-2xl border border-blue-100/50 dark:border-blue-900/20 overflow-hidden">
                <p
                  className="text-gray-700 dark:text-gray-300 leading-relaxed whitespace-pre-wrap text-lg"
                  style={{ wordBreak: 'break-all', overflowWrap: 'anywhere' }}
                >
                  {warning.description}
                </p>
              </div>
            </CardContent>
          </Card>

          {/* Action Taken Card */}
          {warning.actionTaken && (
            <Card className="border-none shadow-sm overflow-hidden rounded-3xl">
              <CardHeader className="bg-amber-50 dark:bg-amber-900/10 border-b border-amber-100 dark:border-amber-900/20 p-6">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-amber-500 rounded-lg shadow-lg shadow-amber-500/20">
                    <AlertTriangle className="h-5 w-5 text-white" />
                  </div>
                  <div>
                    <CardTitle className="text-lg font-bold text-amber-900 dark:text-amber-100">الإجراء الإداري المتخذ</CardTitle>
                    <CardDescription>القرار الذي تم اتخاذه بناءً على المخالفة</CardDescription>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="p-8">
                <div className="bg-amber-50/50 dark:bg-amber-900/5 p-6 rounded-2xl border border-amber-100/50 dark:border-amber-900/20 overflow-hidden w-full">
                  <p
                    className="text-gray-700 dark:text-gray-300 leading-relaxed whitespace-pre-wrap text-lg font-bold italic"
                    style={{ wordBreak: 'break-all', overflowWrap: 'anywhere' }}
                  >
                    {warning.actionTaken}
                  </p>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Employee Response Card */}
          {warning.employeeResponse && (
            <Card className="border-none shadow-sm overflow-hidden rounded-3xl">
              <CardHeader className="bg-purple-50 dark:bg-purple-900/10 border-b border-purple-100 dark:border-purple-900/20 p-6">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-purple-500 rounded-lg shadow-lg shadow-purple-500/20">
                    <User className="h-5 w-5 text-white" />
                  </div>
                  <div>
                    <CardTitle className="text-lg font-bold">رد وتوضيح الموظف</CardTitle>
                    <CardDescription>الرد الرسمي المسجل من قبل الموظف</CardDescription>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="p-8">
                <div className="bg-purple-50/50 dark:bg-purple-900/5 p-6 rounded-2xl border border-purple-100/50 dark:border-purple-900/20 overflow-hidden">
                  <p className="text-gray-700 dark:text-gray-300 leading-relaxed whitespace-pre-wrap text-lg italic break-all">
                    {warning.employeeResponse}
                  </p>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Attachments Card */}
          {warning.attachments && warning.attachments.length > 0 && (
            <Card className="shadow-sm overflow-hidden">
              <CardHeader className="border-b bg-gray-50/50 dark:bg-gray-800/10">
                <CardTitle className="text-lg">المرفقات والمستندات</CardTitle>
              </CardHeader>
              <CardContent className="pt-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {warning.attachments.map((attachment, index) => (
                    <div
                      key={index}
                      className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-gray-100 dark:border-gray-800 hover:border-blue-200 transition-colors cursor-pointer group"
                    >
                      <div className="flex items-center gap-3">
                        <div className="p-2 bg-white dark:bg-gray-700 rounded-lg shadow-sm group-hover:bg-blue-50 transition-colors">
                          <FileText className="h-5 w-5 text-blue-500" />
                        </div>
                        <span className="text-sm font-medium truncate max-w-[150px]">{attachment}</span>
                      </div>
                      <Button variant="ghost" size="sm" className="text-blue-600">عرض</Button>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        <div className="space-y-6">
          <Card className="border-none shadow-sm overflow-hidden rounded-3xl">
            <CardHeader className="bg-gray-50 dark:bg-white/5 border-b border-gray-100 dark:border-white/5 p-5">
              <div className="flex items-center gap-3">
                <Calendar className="h-5 w-5 text-gray-400" />
                <CardTitle className="text-base font-bold">معلومات التاريخ</CardTitle>
              </div>
            </CardHeader>
            <CardContent className="p-6 space-y-4">
              <div className="flex items-start gap-3">
                <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                  <Clock className="h-4 w-4 text-blue-500" />
                </div>
                <div>
                  <p className="text-xs text-gray-500">تاريخ الواقعة</p>
                  <p className="text-sm font-bold">
                    {new Date(warning.incidentDate).toLocaleDateString(
                      "ar-EG",
                      {
                        year: "numeric",
                        month: "long",
                        day: "numeric",
                      },
                    )}
                  </p>
                </div>
              </div>

              {warning.acknowledgedAt && (
                <div className="flex items-start gap-3">
                  <div className="p-2 bg-green-50 dark:bg-green-900/20 rounded-lg">
                    <CheckCircle2 className="h-4 w-4 text-green-500" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500">تاريخ الاستلام</p>
                    <p className="text-sm font-bold text-green-600">
                      {new Date(warning.acknowledgedAt).toLocaleDateString("ar-EG")}
                    </p>
                  </div>
                </div>
              )}

              <div className="pt-4 border-t border-gray-100 dark:border-gray-800 space-y-3">
                <div className="flex justify-between text-xs">
                  <span className="text-gray-400">تاريخ الإصدار:</span>
                  <span className="font-medium text-gray-600">{new Date(warning.createdAt).toLocaleDateString("ar-EG")}</span>
                </div>
                <div className="flex justify-between text-xs">
                  <span className="text-gray-400">آخر تحديث:</span>
                  <span className="font-medium text-gray-600">{new Date(warning.updatedAt).toLocaleDateString("ar-EG")}</span>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card className="border-none shadow-sm overflow-hidden rounded-3xl">
            <CardHeader className="bg-gray-50 dark:bg-white/5 border-b border-gray-100 dark:border-white/5 p-5">
              <div className="flex items-center gap-3">
                <User className="h-5 w-5 text-gray-400" />
                <CardTitle className="text-base font-bold">ملف الموظف</CardTitle>
              </div>
            </CardHeader>
            <CardContent className="p-6">
              <div className="flex items-center gap-4 mb-6">
                <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-blue-500 to-blue-600 flex items-center justify-center text-white text-xl font-bold shadow-lg shadow-blue-500/20">
                  {warning.employee.firstName[0]}
                </div>
                <div>
                  <p className="font-bold text-gray-900 dark:text-white">
                    {warning.employee.firstName} {warning.employee.lastName}
                  </p>
                  <p className="text-xs text-blue-600 font-bold">#{warning.employee.employeeNumber}</p>
                </div>
              </div>

              <div className="space-y-4 mb-6">
                {warning.employee.position && (
                  <div className="flex justify-between items-center text-sm">
                    <span className="text-gray-400">المنصب:</span>
                    <span className="font-medium">{warning.employee.position.title}</span>
                  </div>
                )}
                {warning.employee.department && (
                  <div className="flex justify-between items-center text-sm">
                    <span className="text-gray-400">القسم:</span>
                    <span className="font-medium">{warning.employee.department.name}</span>
                  </div>
                )}
              </div>

              <Button
                variant="secondary"
                className="w-full rounded-xl hover:bg-blue-50 hover:text-blue-600 transition-all border-none"
                onClick={() => navigate(`/hr/employees/${warning.employee.id}`)}
              >
                عرض الملف الكامل
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default WarningDetails;

import React, { useState, useEffect, useMemo } from "react";
import {
  AlertTriangle,
  Plus,
  Calendar,
  User,
  FileText,
  Search,
  Filter,
  CheckCircle2,
  Clock,
  Trash2,
  Download,
  Eye,
  ArrowRight,
  Info,
  ShieldAlert,
  MoreVertical,
  Edit,
  Gavel,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
  CardFooter,
} from "../../components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Input } from "../../components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../../components/ui/dropdown-menu";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../components/ui/tabs";
import { Avatar, AvatarFallback, AvatarImage } from "../../components/ui/avatar";
import { useNavigate, useParams } from "react-router-dom";
import api from "../../services/api";
import { toast } from "sonner";

// Define Types
interface Warning {
  id: string;
  type: "VERBAL" | "WRITTEN" | "FINAL" | "TERMINATION";
  severity: "minor" | "moderate" | "severe";
  title: string;
  description: string;
  incidentDate: string;
  acknowledgedAt?: string;
  employee: {
    id: string;
    firstName: string;
    lastName: string;
    employeeNumber?: string;
    position?: { title: string };
    department?: { name: string };
    image?: string;
  };
}

interface WarningStats {
  total: number;
  byType: Array<{ type: string; _count: number }>;
  bySeverity: Array<{ severity: string; _count: number }>;
  acknowledged: number;
  acknowledgmentRate: number;
}

const Warnings: React.FC = () => {
  const { employeeId } = useParams<{ employeeId?: string }>();
  const navigate = useNavigate();

  // State
  const [warnings, setWarnings] = useState<Warning[]>([]);
  const [stats, setStats] = useState<WarningStats | null>(null);
  const [loading, setLoading] = useState(true);

  // Filters State
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState("all"); // all, pending, acknowledged
  const [severityFilter, setSeverityFilter] = useState("all");
  const [selectedWarning, setSelectedWarning] = useState<Warning | null>(null);

  useEffect(() => {
    fetchData();
  }, [employeeId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const url = employeeId
        ? `/hr/warnings/employee/${employeeId}`
        : "/hr/warnings";

      const statsUrl = `/hr/warnings/stats${employeeId ? `?employeeId=${employeeId}` : ""}`;

      console.log("🔍 [FETCH] Fetching warnings from:", url);
      const warningsRes = await api.get(url);
      setWarnings(warningsRes.data.warnings || []);

      console.log("🔍 [FETCH] Fetching stats from:", statsUrl);
      try {
        const statsRes = await api.get(statsUrl);
        setStats(statsRes.data.stats || null);
      } catch (statsErr: any) {
        console.error(
          "❌ [FETCH-STATS-ERROR]",
          statsErr.response?.data || statsErr.message,
        );
        // Don't fail the whole page if just stats fail
      }
    } catch (error) {
      console.error("Error fetching data:", error);
      toast.error("فشل في جلب البيانات");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا الإنذار؟")) return;
    try {
      await api.delete(`/hr/warnings/${id}`);
      toast.success("تم حذف الإنذار بنجاح");
      fetchData(); // Refresh data
    } catch (error) {
      toast.error("فشل في حذف الإنذار");
    }
  };

  const handleAdminAcknowledge = async (id: string) => {
    if (!window.confirm("هل تريد تسجيل إقرار إداري لهذا الإنذار؟ (يستخدم في حال توقيع الموظف ورقياً)")) return;
    try {
      await api.post(`/hr/warnings/${id}/admin-acknowledge`);
      toast.success("تم تسجيل الإقرار بنجاح");
      fetchData(); // Refresh data
    } catch (error) {
      toast.error("فشل في تسجيل الإقرار");
    }
  };

  // Helper Functions
  const getTypeLabel = (type: string) => {
    const typeMap: Record<string, string> = {
      VERBAL: "شفوي",
      WRITTEN: "كتابي",
      FINAL: "نهائي",
      TERMINATION: "إنهاء خدمة",
    };
    return typeMap[type] || type;
  };

  const getTypeColor = (type: string) => {
    const colorMap: Record<string, string> = {
      VERBAL:
        "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
      WRITTEN:
        "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400",
      FINAL:
        "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400",
      TERMINATION:
        "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    };
    return colorMap[type] || "bg-gray-100 text-gray-700";
  };

  const getSeverityBadge = (severity: string) => {
    const styles: Record<string, string> = {
      minor:
        "bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300",
      moderate:
        "bg-orange-100 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400",
      severe:
        "bg-red-100 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-400",
    };
    const labels: Record<string, string> = {
      minor: "مخالفة بسيطة",
      moderate: "مخالفة متوسطة",
      severe: "مخالفة جسيمة",
    };

    return (
      <Badge
        variant="outline"
        className={`${styles[severity] || ""} text-xs font-normal`}
      >
        {labels[severity] || severity}
      </Badge>
    );
  };

  // Filter Logic
  const filteredWarnings = useMemo(() => {
    return warnings.filter((item) => {
      // 1. Search Query
      const searchMatch =
        item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.employee.firstName
          .toLowerCase()
          .includes(searchQuery.toLowerCase()) ||
        item.employee.lastName
          .toLowerCase()
          .includes(searchQuery.toLowerCase());

      if (!searchMatch) return false;

      // 2. Tab Filter (Status)
      if (activeTab === "pending" && item.acknowledgedAt) return false;
      if (activeTab === "acknowledged" && !item.acknowledgedAt) return false;

      // 3. Severity Filter
      if (severityFilter !== "all" && item.severity !== severityFilter)
        return false;

      return true;
    });
  }, [warnings, searchQuery, activeTab, severityFilter]);

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center p-8 min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-foreground">
            الإنذارات والمخالفات
          </h1>
          <p className="text-muted-foreground mt-1">
            إدارة ومتابعة المخالفات الإدارية والإجراءات التأديبية
          </p>
        </div>
        <Button
          onClick={() => navigate("/hr/warnings/new")}
          className="shadow-lg hover:shadow-xl transition-all"
        >
          <Plus className="h-5 w-5 ml-2" />
          تسجيل مخالفة جديدة
        </Button>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <Card className="bg-gradient-to-br from-blue-50 to-white dark:from-blue-950/20 dark:to-card border-none shadow-sm hover:shadow-md transition-all">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium text-blue-700 dark:text-blue-400">
                إجمالي الإنذارات
              </CardTitle>
              <FileText className="h-4 w-4 text-blue-600" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-blue-900 dark:text-blue-100">
                {stats.total}
              </div>
              <p className="text-xs text-blue-600/80 mt-1">
                سجل كامل للمخالفات
              </p>
            </CardContent>
          </Card>

          <Card className="bg-gradient-to-br from-orange-50 to-white dark:from-orange-950/20 dark:to-card border-none shadow-sm hover:shadow-md transition-all">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium text-orange-700 dark:text-orange-400">
                قيد الانتظار
              </CardTitle>
              <Clock className="h-4 w-4 text-orange-600" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-orange-900 dark:text-orange-100">
                {stats.total - stats.acknowledged}
              </div>
              <p className="text-xs text-orange-600/80 mt-1">
                بانتظار توقيع الموظف
              </p>
            </CardContent>
          </Card>

          <Card className="bg-gradient-to-br from-green-50 to-white dark:from-green-950/20 dark:to-card border-none shadow-sm hover:shadow-md transition-all">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium text-green-700 dark:text-green-400">
                مكتملة الإجراءات
              </CardTitle>
              <CheckCircle2 className="h-4 w-4 text-green-600" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-green-900 dark:text-green-100">
                {stats.acknowledged}
              </div>
              <p className="text-xs text-green-600/80 mt-1">تم الاعتراف بها</p>
            </CardContent>
          </Card>

          <Card className="bg-gradient-to-br from-red-50 to-white dark:from-red-950/20 dark:to-card border-none shadow-sm hover:shadow-md transition-all">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium text-red-700 dark:text-red-400">
                مخالفات جسيمة
              </CardTitle>
              <ShieldAlert className="h-4 w-4 text-red-600" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-red-900 dark:text-red-100">
                {stats.bySeverity.find((s) => s.severity === "severe")
                  ?._count || 0}
              </div>
              <p className="text-xs text-red-600/80 mt-1">تتطلب انتباه فوري</p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Main Content Area */}
      <Card className="border-none shadow-md bg-card/50 backdrop-blur-sm">
        <CardHeader className="pb-4 border-b">
          <div className="flex flex-col md:flex-row justify-between gap-4">
            <Tabs
              defaultValue="all"
              className="w-full md:w-auto"
              onValueChange={setActiveTab}
            >
              <TabsList className="bg-muted/50 w-full md:w-auto p-1">
                <TabsTrigger value="all" className="flex-1 md:flex-none">
                  الكل
                </TabsTrigger>
                <TabsTrigger value="pending" className="flex-1 md:flex-none">
                  قيد الانتظار
                </TabsTrigger>
                <TabsTrigger
                  value="acknowledged"
                  className="flex-1 md:flex-none"
                >
                  مكتملة
                </TabsTrigger>
              </TabsList>
            </Tabs>

            <div className="flex items-center gap-2 w-full md:w-auto">
              <div className="relative flex-1 md:flex-none md:w-64">
                <Search className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="بحث باسم الموظف أو المخالفة..."
                  className="pr-9 bg-background/50 border-muted"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <Select value={severityFilter} onValueChange={setSeverityFilter}>
                <SelectTrigger className="w-[140px] bg-background/50 border-muted">
                  <div className="flex items-center gap-2">
                    <Filter className="h-4 w-4 text-muted-foreground" />
                    <SelectValue placeholder="الشدة" />
                  </div>
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">كل المستويات</SelectItem>
                  <SelectItem value="minor">بسيطة</SelectItem>
                  <SelectItem value="moderate">متوسطة</SelectItem>
                  <SelectItem value="severe">جسيمة</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-6">
          {loading ? (
            <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mb-2"></div>
              <p>جاري تحديث البيانات...</p>
            </div>
          ) : filteredWarnings.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-center text-muted-foreground">
              <div className="h-16 w-16 bg-muted/50 rounded-full flex items-center justify-center mb-4">
                <FileText className="h-8 w-8 opacity-50" />
              </div>
              <h3 className="text-lg font-medium text-foreground">
                لا توجد مخالفات مطابقة
              </h3>
              <p className="max-w-xs mx-auto mt-2">
                لم يتم العثور على أي سجلات تطابق معايير البحث الخاصة بك. حاول
                تغيير الفلاتر.
              </p>
              {Object.keys(filteredWarnings).length === 0 &&
                warnings.length === 0 && (
                  <Button
                    variant="outline"
                    className="mt-6"
                    onClick={() => navigate("/hr/warnings/new")}
                  >
                    <Plus className="h-4 w-4 ml-2" />
                    إضافة مخالفة جديدة
                  </Button>
                )}
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredWarnings.map((warning) => (
                <Card
                  key={warning.id}
                  className="group relative overflow-hidden border-muted hover:border-primary/50 transition-all duration-300 hover:shadow-lg bg-card"
                >
                  <div
                    className={`absolute top-0 right-0 w-1 h-full ${warning.severity === "severe"
                      ? "bg-red-500"
                      : warning.severity === "moderate"
                        ? "bg-orange-500"
                        : "bg-blue-400"
                      }`}
                  />

                  <CardHeader className="pb-3 pt-5 pr-6">
                    <div className="flex justify-between items-start mb-2">
                      <div className="flex items-center gap-3">
                        <Avatar className="h-10 w-10 border-2 border-white dark:border-gray-800 shadow-sm flex-shrink-0">
                          <AvatarFallback className="bg-gradient-to-br from-blue-500 to-blue-600 text-white font-bold">
                            {warning.employee.firstName[0]}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-bold text-gray-900 dark:text-gray-100 truncate">
                            {warning.employee.firstName}{" "}
                            {warning.employee.lastName}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {warning.employee.position?.title || "موظف"}
                          </p>
                        </div>
                      </div>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 -mt-1 -ml-2 text-muted-foreground"
                          >
                            <MoreVertical className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end" className="bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800 shadow-xl rounded-2xl p-2 min-w-[180px] z-50">
                          <DropdownMenuItem
                            className="rounded-xl flex items-center gap-3 py-2.5 cursor-pointer"
                            onClick={() =>
                              navigate(`/hr/warnings/${warning.id}`)
                            }
                          >
                            <div className="p-1.5 bg-blue-50 dark:bg-blue-900/20 rounded-lg text-blue-600 dark:text-blue-400">
                              <FileText className="h-4 w-4" />
                            </div>
                            <span className="font-medium text-sm">عـرض التفاصيل</span>
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            className="rounded-xl flex items-center gap-3 py-2.5 cursor-pointer"
                            onClick={() =>
                              navigate(`/hr/warnings/${warning.id}/edit`)
                            }
                          >
                            <div className="p-1.5 bg-amber-50 dark:bg-amber-900/20 rounded-lg text-amber-600 dark:text-amber-400">
                              <Edit className="h-4 w-4" />
                            </div>
                            <span className="font-medium text-sm">تعديل</span>
                          </DropdownMenuItem>
                          {!warning.acknowledgedAt && (
                            <DropdownMenuItem
                              className="rounded-xl flex items-center gap-3 py-2.5 cursor-pointer text-green-600 focus:text-green-600 focus:bg-green-50 dark:focus:bg-green-900/20"
                              onClick={() => handleAdminAcknowledge(warning.id)}
                            >
                              <div className="p-1.5 bg-green-50 dark:bg-green-900/20 rounded-lg">
                                <CheckCircle2 className="h-4 w-4" />
                              </div>
                              <span className="font-medium text-sm">إقرار إداري (يدوي)</span>
                            </DropdownMenuItem>
                          )}
                          <div className="my-1 border-t border-gray-100 dark:border-gray-800" />
                          <DropdownMenuItem
                            className="rounded-xl flex items-center gap-3 py-2.5 cursor-pointer text-red-600 focus:text-red-700 focus:bg-red-50 dark:focus:bg-red-900/20"
                            onClick={() => handleDelete(warning.id)}
                          >
                            <div className="p-1.5 bg-red-50 dark:bg-red-900/20 rounded-lg">
                              <Trash2 className="h-4 w-4" />
                            </div>
                            <span className="font-medium text-sm">حـذف</span>
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </div>
                    <div className="mt-2">
                      <div className="flex items-center justify-between mb-1">
                        <CardTitle
                          className="text-base break-all flex-1 pr-2 leading-tight font-bold text-gray-900 dark:text-gray-100"
                          title={warning.title}
                        >
                          {warning.title}
                        </CardTitle>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-muted-foreground hover:text-primary"
                          onClick={() => setSelectedWarning(warning)}
                          title="عرض سريع"
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Badge
                          variant="secondary"
                          className={`${getTypeColor(warning.type)} border-0`}
                        >
                          {getTypeLabel(warning.type)}
                        </Badge>
                      </div>
                    </div>
                  </CardHeader>

                  <CardContent className="p-6 pt-2 space-y-4">
                    <div className="space-y-3">
                      <div className="flex flex-col gap-2">
                        <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-widest">
                          <FileText className="h-3.5 w-3.5" />
                          <span>وصف المخالفة:</span>
                        </div>
                        <p
                          className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed whitespace-pre-wrap bg-gray-50/80 dark:bg-white/5 p-4 rounded-2xl border border-gray-100 dark:border-white/5"
                          style={{ wordBreak: 'break-all', overflowWrap: 'anywhere' }}
                        >
                          {warning.description}
                        </p>
                      </div>

                      {warning.actionTaken && (
                        <div className="flex flex-col gap-2">
                          <div className="flex items-center gap-2 text-[10px] font-black text-amber-500 uppercase tracking-widest">
                            <Gavel className="h-3.5 w-3.5" />
                            <span>الإجراء المتخذ:</span>
                          </div>
                          <p
                            className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed whitespace-pre-wrap bg-amber-50/50 dark:bg-amber-900/10 p-4 rounded-2xl border border-amber-100 dark:border-amber-900/20"
                            style={{ wordBreak: 'break-all', overflowWrap: 'anywhere' }}
                          >
                            {warning.actionTaken}
                          </p>
                        </div>
                      )}

                      <div className="flex items-center justify-between pt-2">
                        <div className="flex flex-col gap-1">
                          <span className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-widest">تاريخ الواقعة:</span>
                          <div className="flex items-center gap-2 text-xs font-bold text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 px-3 py-1.5 rounded-xl w-fit border border-blue-100 dark:border-blue-900/30">
                            <Calendar className="h-3.5 w-3.5" />
                            {new Date(warning.incidentDate).toLocaleDateString("ar-EG")}
                          </div>
                        </div>
                      </div>
                    </div>
                  </CardContent>

                  <CardFooter className="pt-0 pr-6 pb-4 flex items-center justify-between border-t bg-muted/10 h-14">
                    <div className="flex items-center gap-2">
                      {getSeverityBadge(warning.severity)}
                    </div>

                    {warning.acknowledgedAt ? (
                      <div className="flex items-center gap-1.5 text-xs font-medium text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/20 px-2.5 py-1 rounded-full">
                        <CheckCircle2 className="h-3.5 w-3.5" />
                        تم الإقرار
                      </div>
                    ) : (
                      <div className="flex items-center gap-1.5 text-xs font-medium text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 px-2.5 py-1 rounded-full">
                        <Clock className="h-3.5 w-3.5" />
                        بانتظار الإقرار
                      </div>
                    )}
                  </CardFooter>
                </Card>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Preview Modal */}
      <Dialog open={!!selectedWarning} onOpenChange={(open) => !open && setSelectedWarning(null)}>
        <DialogContent className="max-w-2xl bg-white dark:bg-gray-950 border-none shadow-2xl rounded-[2rem] p-0 overflow-hidden" dir="rtl">
          {selectedWarning && (
            <>
              {/* Status Header */}
              <div className="h-2 bg-primary/20 bg-gradient-to-r from-primary via-primary/50 to-primary/10" />

              <DialogHeader className="px-8 pt-8 pb-6 bg-gradient-to-br from-muted/50 via-background to-background relative overflow-hidden">
                <div className="absolute top-[-20%] left-[-10%] w-48 h-48 bg-primary/5 rounded-full blur-3xl" />

                <div className="flex items-start justify-between relative z-10">
                  <div className="flex items-center gap-5">
                    <div className="relative">
                      <Avatar className="h-16 w-16 border-4 border-white dark:border-gray-800 shadow-xl ring-2 ring-primary/10">
                        <AvatarFallback className="bg-gradient-to-br from-primary to-primary-foreground text-white text-xl font-black">
                          {selectedWarning.employee.firstName[0]}
                        </AvatarFallback>
                      </Avatar>
                      <div className="absolute -bottom-1 -right-1 bg-green-500 h-4 w-4 rounded-full border-2 border-white dark:border-gray-900" />
                    </div>
                    <div className="space-y-1">
                      <DialogTitle className="text-2xl font-black tracking-tight text-gray-900 dark:text-white break-words max-w-[400px]">
                        {selectedWarning.title}
                      </DialogTitle>
                      <div className="flex items-center gap-2 text-sm text-muted-foreground font-medium">
                        <User className="h-3.5 w-3.5" />
                        <span>{selectedWarning.employee.firstName} {selectedWarning.employee.lastName}</span>
                        <span className="h-1 w-1 rounded-full bg-muted-foreground/30" />
                        <span>{selectedWarning.employee.employeeNumber}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </DialogHeader>

              <div className="px-8 pb-8 space-y-8 max-h-[65vh] overflow-y-auto custom-scrollbar relative">
                {/* Meta Info Grid */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="group p-4 bg-muted/30 hover:bg-muted/50 transition-colors rounded-2xl border border-muted/50 space-y-2">
                    <p className="text-[10px] font-black text-primary uppercase tracking-widest flex items-center gap-1.5 opacity-60">
                      <AlertTriangle className="h-3 w-3" /> درجة الشدة
                    </p>
                    <div className="flex items-center gap-2">
                      {getSeverityBadge(selectedWarning.severity)}
                    </div>
                  </div>
                  <div className="group p-4 bg-muted/30 hover:bg-muted/50 transition-colors rounded-2xl border border-muted/50 space-y-2">
                    <p className="text-[10px] font-black text-primary uppercase tracking-widest flex items-center gap-1.5 opacity-60">
                      <FileText className="h-3 w-3" /> تصنيف المخالفة
                    </p>
                    <Badge variant="secondary" className={`${getTypeColor(selectedWarning.type)} border-0 text-xs px-3 py-1`}>
                      {getTypeLabel(selectedWarning.type)}
                    </Badge>
                  </div>
                </div>

                {/* Description Section */}
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                      <FileText className="h-3.5 w-3.5 text-primary" />
                      تفاصيل الواقعة
                    </h4>
                    <span className="text-[10px] text-muted-foreground font-mono">ID: #{selectedWarning.id.slice(-6)}</span>
                  </div>
                  <div className="relative group">
                    <div className="absolute -inset-0.5 bg-gradient-to-r from-primary/10 to-transparent rounded-[1.25rem] blur opacity-0 group-hover:opacity-100 transition duration-500" />
                    <div className="relative bg-white dark:bg-gray-900/50 p-6 rounded-[1.25rem] border border-gray-100 dark:border-gray-800 shadow-sm leading-relaxed whitespace-pre-wrap break-words text-gray-700 dark:text-gray-200 text-lg">
                      {selectedWarning.description}
                    </div>
                  </div>
                </div>

                {/* Footnote Stats */}
                <div className="flex flex-wrap items-center gap-6 pt-6 border-t border-dashed border-muted">
                  <div className="flex items-center gap-2 px-3 py-1.5 bg-muted/40 rounded-full text-xs font-semibold text-muted-foreground">
                    <Calendar className="h-3 w-3 text-primary" />
                    <span>حدثت في: {new Date(selectedWarning.incidentDate).toLocaleDateString('ar-EG', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
                  </div>
                  {selectedWarning.acknowledgedAt ? (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-green-500/10 text-green-600 rounded-full text-xs font-bold ring-1 ring-green-500/20">
                      <CheckCircle2 className="h-3 w-3" />
                      <span>تم الإقرار: {new Date(selectedWarning.acknowledgedAt).toLocaleDateString('ar-EG')}</span>
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-amber-500/10 text-amber-600 rounded-full text-xs font-bold ring-1 ring-amber-500/20">
                      <Info className="h-3 w-3" />
                      <span>في انتظار إقرار الموظف</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Action Footer */}
              <div className="p-6 bg-muted/20 border-t border-muted/30 flex items-center justify-between gap-4">
                <Button
                  variant="ghost"
                  onClick={() => setSelectedWarning(null)}
                  className="rounded-xl px-6 font-bold hover:bg-background"
                >
                  إغلاق النافذة
                </Button>
                <div className="flex items-center gap-3">
                  <Button
                    onClick={() => navigate(`/hr/warnings/${selectedWarning.id}`)}
                    className="rounded-xl shadow-lg shadow-primary/20 px-8 font-black gap-2 h-12"
                  >
                    فتح الملف الكامل
                    <ArrowRight className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Warnings;

import React, { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { XMarkIcon } from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../../services/companyAwareApi";

interface AssetAssignmentModalProps {
  asset: any;
  type: "assign" | "return";
  onClose: () => void;
  onSuccess: () => void;
  usePortal?: boolean;
}

const AssetAssignmentModal: React.FC<AssetAssignmentModalProps> = ({
  asset,
  type,
  onClose,
  onSuccess,
  usePortal = true,
}) => {
  const [formData, setFormData] = useState({
    employeeId: "",
    assignedAt: new Date().toISOString().split("T")[0],
    returnedAt: new Date().toISOString().split("T")[0],
    returnCondition: asset.condition || "GOOD",
    notes: "",
  });

  const [employees, setEmployees] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingEmployees, setLoadingEmployees] = useState(false);
  const [error, setError] = useState("");

  // قفل سكرول الصفحة أثناء فتح المودال
  useEffect(() => {
    const original = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = original;
    };
  }, []);

  useEffect(() => {
    if (type === "assign") {
      fetchEmployees();
    }
  }, [type]);

  const fetchEmployees = async () => {
    setLoadingEmployees(true);
    try {
      // Need an endpoint to fetch active employees
      // Using existing /hr/employees endpoint
      const response = await companyAwareApi.get("/hr/employees");
      if (response.data.success) {
        // Backend returns strictly { employees: [], pagination: {} }
        setEmployees(response.data.employees || response.data.data || []);
      }
    } catch (error) {
      console.error("Error fetching employees:", error);
    } finally {
      setLoadingEmployees(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      if (type === "assign") {
        await companyAwareApi.post("/hr/assets/assign", {
          assetId: asset.id,
          employeeId: formData.employeeId,
          assignedAt: formData.assignedAt,
          notes: formData.notes,
        });
      } else {
        await companyAwareApi.post("/hr/assets/return", {
          assetId: asset.id,
          returnedAt: formData.returnedAt,
          returnCondition: formData.returnCondition,
          notes: formData.notes,
        });
      }
      onSuccess();
    } catch (err: any) {
      setError(err.response?.data?.message || "حدث خطأ أثناء تنفيذ العملية");
    } finally {
      setLoading(false);
    }
  };

  const modal = (
    <div className="fixed inset-0 z-[1200] flex items-center justify-center px-4 py-8 sm:py-12 bg-black/60 backdrop-blur-sm">
      <div
        className="absolute inset-0"
        onClick={onClose}
        aria-hidden="true"
      />

      <div className="relative w-full max-w-2xl bg-white dark:bg-gray-800 text-right rounded-[2rem] shadow-2xl border border-gray-100 dark:border-gray-700 overflow-hidden transform transition-all">
        <div className="absolute left-0 top-0 h-full w-1.5 bg-gradient-to-b from-indigo-600 to-violet-500" />
        <div className="flex items-center justify-between px-8 py-6 border-b border-gray-100 dark:border-gray-700/50 bg-gray-50/50 dark:bg-gray-900/20 backdrop-blur-xl">
          <div>
            <p className="text-[10px] font-black text-indigo-500 dark:text-indigo-400 uppercase tracking-[0.2em] mb-1">
              {type === "assign" ? "نموذج تسليم عهدة" : "نموذج استرجاع عهدة"}
            </p>
            <h3 className="text-2xl font-black text-gray-900 dark:text-white">
              {asset?.name || "الأصل"}
            </h3>
          </div>
          <button
            onClick={onClose}
            className="rounded-2xl p-2.5 text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700 transition-all shadow-sm"
            aria-label="إغلاق النموذج"
          >
            <XMarkIcon className="h-6 w-6" />
          </button>
        </div>

        <div className="px-8 py-8 space-y-6">
          {error && (
            <motion.div 
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              className="rounded-2xl border border-red-100 dark:border-red-900/50 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 px-5 py-4 text-sm font-bold flex items-center gap-3"
            >
              <span className="text-lg">⚠️</span>
              {error}
            </motion.div>
          )}

          {type === "assign" && (
            <div className="rounded-2xl bg-amber-50 dark:bg-amber-900/20 border border-amber-100 dark:border-amber-900/50 text-amber-700 dark:text-amber-400 px-5 py-4 text-xs font-medium flex items-start gap-3">
              <span className="text-lg">💡</span>
              <span>
                لم يتم العثور على موظفين؟ تأكد من إضافة الموظفين في نظام الموارد البشرية أولاً.
              </span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="block text-sm font-black text-gray-700 dark:text-gray-300 mr-1">
                  الموظف {type === "assign" && <span className="text-red-500">*</span>}
                </label>
                {type === "assign" ? (
                  <select
                    required
                    value={formData.employeeId}
                    onChange={(e) =>
                      setFormData({ ...formData, employeeId: e.target.value })
                    }
                    className="w-full rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-white px-4 py-3 focus:outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 transition-all font-medium"
                    disabled={loadingEmployees}
                  >
                    <option value="">
                      {loadingEmployees ? "جاري التحميل..." : "اختر الموظف"}
                    </option>
                    {employees.map((emp) => (
                      <option key={emp.id} value={emp.id}>
                        {emp.firstName} {emp.lastName} ({emp.employeeNumber || "بدون رقم"})
                      </option>
                    ))}
                  </select>
                ) : (
                  <div className="rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50 text-gray-900 dark:text-white px-4 py-3 text-sm font-bold">
                    عهدة لدى: {asset?.currentHolder?.firstName}{" "}
                    {asset?.currentHolder?.lastName}
                  </div>
                )}
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-black text-gray-700 dark:text-gray-300 mr-1">
                  {type === "assign" ? "تاريخ التسليم" : "تاريخ الاسترجاع"}
                </label>
                <input
                  type="date"
                  required
                  className="block w-full border-2 border-gray-100 dark:border-gray-700 rounded-2xl shadow-sm py-3 px-4 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 transition-all font-medium"
                  value={type === "assign" ? formData.assignedAt : formData.returnedAt}
                  onChange={(e) =>
                    type === "assign"
                      ? setFormData({ ...formData, assignedAt: e.target.value })
                      : setFormData({ ...formData, returnedAt: e.target.value })
                  }
                />
              </div>
            </div>

            {type === "return" && (
              <div className="space-y-2">
                <label className="block text-sm font-black text-gray-700 dark:text-gray-300 mr-1">
                  حالة الأصل عند الاسترجاع
                </label>
                <select
                  className="w-full rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-white px-4 py-3 focus:outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 transition-all font-medium"
                  value={formData.returnCondition}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      returnCondition: e.target.value,
                    })
                  }
                >
                  <option value="NEW">جديد</option>
                  <option value="GOOD">جيد</option>
                  <option value="FAIR">مقبول</option>
                  <option value="POOR">سيء</option>
                  <option value="DAMAGED">تالف</option>
                </select>
              </div>
            )}

            <div className="space-y-2">
              <label className="block text-sm font-black text-gray-700 dark:text-gray-300 mr-1">
                ملاحظات
              </label>
              <textarea
                className="block w-full border-2 border-gray-100 dark:border-gray-700 rounded-2xl shadow-sm py-3 px-4 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 transition-all font-medium min-h-[110px] resize-none"
                placeholder="أضف ملاحظاتك هنا..."
                value={formData.notes}
                onChange={(e) =>
                  setFormData({ ...formData, notes: e.target.value })
                }
              />
            </div>

            <div className="flex flex-col sm:flex-row justify-end gap-3 pt-6 border-t border-gray-100 dark:border-gray-700/50">
              <button
                type="button"
                onClick={onClose}
                className="w-full sm:w-auto px-8 py-3.5 bg-gray-50 dark:bg-gray-800 text-gray-500 hover:text-gray-700 dark:hover:text-white rounded-2xl font-black text-sm border-2 border-gray-100 dark:border-gray-700 hover:bg-gray-100 dark:hover:bg-gray-700 transition-all shadow-sm"
              >
                إلغاء
              </button>
              <button
                type="submit"
                disabled={loading}
                className={`w-full sm:w-auto inline-flex justify-center items-center px-10 py-3.5 rounded-2xl text-white font-black text-sm transition-all shadow-lg active:scale-95 ${
                  type === "assign"
                    ? "bg-gradient-to-r from-indigo-600 to-violet-600 shadow-indigo-600/20 hover:shadow-indigo-600/40"
                    : "bg-gradient-to-r from-orange-500 to-amber-500 shadow-orange-500/20 hover:shadow-orange-500/40"
                } disabled:opacity-50`}
              >
                {loading ? (
                  <div className="flex items-center gap-2">
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white/30 border-t-white"></div>
                    جاري الحفظ...
                  </div>
                ) : type === "assign" ? (
                  "تأكيد التسليم"
                ) : (
                  "تأكيد الاسترجاع"
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );

  if (usePortal && typeof document !== "undefined") {
    return createPortal(modal, document.body);
  }

  return modal;
};

export default AssetAssignmentModal;

import React, { useState, useEffect } from "react";
import { PlusIcon, TrashIcon, TagIcon, ChatBubbleBottomCenterTextIcon } from "@heroicons/react/24/outline";
import { motion, AnimatePresence } from "framer-motion";
import { companyAwareApi } from "../../../services/companyAwareApi";
import toast from "react-hot-toast";

const AssetCategories: React.FC = () => {
  const [categories, setCategories] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [newCategory, setNewCategory] = useState({ name: "", description: "" });
  const [adding, setAdding] = useState(false);

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    setLoading(true);
    try {
      const response = await companyAwareApi.get("/hr/assets/categories");
      if (response.data.success) {
        setCategories(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCategory.name.trim()) return;

    setAdding(true);
    try {
      const response = await companyAwareApi.post(
        "/hr/assets/categories",
        newCategory,
      );
      if (response.data.success) {
        setNewCategory({ name: "", description: "" });
        fetchCategories();
      }
    } catch (error) {
      console.error("Error creating category:", error);
      alert("فشل في إضافة التصنيف");
    } finally {
      setAdding(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا التصنيف؟")) return;

    try {
      const response = await companyAwareApi.delete(`/hr/assets/categories/${id}`);
      if (response.data.success) {
        fetchCategories();
      }
    } catch (error) {
      alert("فشل في حذف التصنيف. قد يكون مرتبطاً بأصول.");
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* List */}
      <div className="lg:col-span-2 space-y-6">
        <div className="flex items-center justify-between">
          <h3 className="text-xl font-black text-gray-900 dark:text-white flex items-center gap-2">
            <TagIcon className="h-6 w-6 text-indigo-600" />
            التصنيفات الحالية
          </h3>
          <span className="px-3 py-1 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 text-xs font-black rounded-full">
            {categories.length} تصنيف
          </span>
        </div>

        {loading ? (
          <div className="flex justify-center py-20 bg-white/50 dark:bg-gray-800/50 rounded-3xl border border-dashed border-gray-200 dark:border-gray-700">
            <div className="flex flex-col items-center gap-3">
              <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600"></div>
              <p className="text-sm text-gray-400 animate-pulse">جاري تحميل التصنيفات...</p>
            </div>
          </div>
        ) : categories.length === 0 ? (
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="text-center py-20 bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-sm"
          >
            <div className="h-20 w-20 bg-gray-50 dark:bg-gray-700/50 rounded-full flex items-center justify-center mx-auto mb-4">
              <TagIcon className="h-10 w-10 text-gray-300 dark:text-gray-600" />
            </div>
            <h4 className="text-lg font-bold text-gray-400">لا توجد تصنيفات بعد</h4>
            <p className="text-sm text-gray-400 mt-2">ابدأ بإضافة أول تصنيف من القائمة الجانبية</p>
          </motion.div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <AnimatePresence mode="popLayout">
              {categories.map((cat, idx) => (
                <motion.div
                  key={cat.id}
                  layout
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.9 }}
                  transition={{ delay: idx * 0.05 }}
                  className="group bg-white dark:bg-gray-800 rounded-2xl p-5 border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-xl transition-all duration-300"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <div className="w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.5)]"></div>
                        <h4 className="font-black text-gray-900 dark:text-white group-hover:text-indigo-600 transition-colors">
                          {cat.name}
                        </h4>
                      </div>
                      {cat.description ? (
                        <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed mb-4">
                          {cat.description}
                        </p>
                      ) : (
                        <div className="h-4 mb-4"></div>
                      )}
                      
                      <div className="flex items-center justify-between pt-4 border-t border-gray-50 dark:border-gray-700/50">
                        <div className="flex items-center gap-1.5">
                          <PlusIcon className="h-3.5 w-3.5 text-indigo-400" />
                          <span className="text-xs font-bold text-gray-400">
                            الأصول: {cat._count?.assets || 0}
                          </span>
                        </div>
                        <button
                          onClick={() => handleDelete(cat.id)}
                          className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-all"
                          title="حذف"
                        >
                          <TrashIcon className="h-5 w-5" />
                        </button>
                      </div>
                    </div>
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        )}
      </div>

      {/* Add Form */}
      <div className="lg:sticky lg:top-6 self-start">
        <motion.div 
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="bg-gradient-to-br from-white to-gray-50/50 dark:from-gray-800 dark:to-gray-900 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-xl overflow-hidden relative"
        >
          {/* Decorative pattern */}
          <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
          
          <div className="p-6 relative">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-600/20">
                <PlusIcon className="h-6 w-6 text-white" />
              </div>
              <h3 className="text-xl font-black text-gray-900 dark:text-white">
                تصنيف جديد
              </h3>
            </div>

            <form onSubmit={handleAdd} className="space-y-5">
              <div className="space-y-2">
                <label className="text-sm font-black text-gray-700 dark:text-gray-300 mr-1 flex items-center gap-2">
                  <TagIcon className="h-4 w-4 text-indigo-400" />
                  اسم التصنيف
                </label>
                <input
                  type="text"
                  required
                  placeholder="مثل: أجهزة كمبيوتر، أثاث..."
                  className="block w-full border-2 border-gray-100 dark:border-gray-700 rounded-2xl py-3 px-4 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 transition-all font-medium"
                  value={newCategory.name}
                  onChange={(e) =>
                    setNewCategory({ ...newCategory, name: e.target.value })
                  }
                />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-black text-gray-700 dark:text-gray-300 mr-1 flex items-center gap-2">
                  <ChatBubbleBottomCenterTextIcon className="h-4 w-4 text-indigo-400" />
                  وصف التصنيف
                </label>
                <textarea
                  placeholder="أضف وصفاً مختصراً..."
                  className="block w-full border-2 border-gray-100 dark:border-gray-700 rounded-2xl py-3 px-4 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 transition-all font-medium min-h-[100px]"
                  rows={3}
                  value={newCategory.description}
                  onChange={(e) =>
                    setNewCategory({
                      ...newCategory,
                      description: e.target.value,
                    })
                  }
                />
              </div>

              <button
                type="submit"
                disabled={adding}
                className="w-full flex items-center justify-center gap-2 py-4 bg-gradient-to-r from-indigo-600 to-violet-600 text-white rounded-2xl font-black shadow-lg shadow-indigo-600/20 hover:shadow-indigo-600/40 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50"
              >
                {adding ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white/30 border-t-white"></div>
                    جاري الحفظ...
                  </>
                ) : (
                  <>
                    إضافة التصنيف
                    <PlusIcon className="h-5 w-5" />
                  </>
                )}
              </button>
            </form>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default AssetCategories;

import React, { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { XMarkIcon } from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../../services/companyAwareApi";

interface AssetFormProps {
  initialData?: any;
  onClose: () => void;
  onSuccess: () => void;
  usePortal?: boolean;
}

const AssetForm: React.FC<AssetFormProps> = ({
  initialData,
  onClose,
  onSuccess,
  usePortal = true,
}) => {
  const [formData, setFormData] = useState({
    name: "",
    categoryId: "",
    code: "",
    serialNumber: "",
    model: "",
    brand: "",
    status: "AVAILABLE",
    condition: "NEW",
    purchaseDate: "",
    purchaseValue: "",
    location: "",
    notes: "",
    warrantyStartDate: "",
    warrantyEndDate: "",
    warrantyMonths: "",
    warrantyProvider: "",
    supplierName: "",
    supplierMobile: "",
    supplierAddress: "",
    assignedToId: "",
  });

  const [categories, setCategories] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [employees, setEmployees] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingEmployees, setLoadingEmployees] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchCategories();
    fetchSuppliers();
    fetchEmployees();
    if (initialData) {
      setFormData({
        name: (initialData.name as string) || "",
        categoryId: (initialData.categoryId as string) || "",
        code: (initialData.code as string) || "",
        serialNumber: (initialData.serialNumber as string) || "",
        model: (initialData.model as string) || "",
        brand: (initialData.brand as string) || "",
        status: (initialData.status as string) || "AVAILABLE",
        condition: (initialData.condition as string) || "NEW",
        purchaseDate: (initialData as any).purchaseDate
          ? new Date((initialData as any).purchaseDate)
            .toISOString()
            .split("T")[0]
          : "",
        purchaseValue: (initialData as any).purchaseValue || "",
        location: (initialData as any).location || "",
        notes: (initialData as any).notes || "",
        warrantyStartDate: (initialData as any).warrantyStartDate
          ? new Date((initialData as any).warrantyStartDate)
            .toISOString()
            .split("T")[0]
          : "",
        warrantyEndDate: (initialData as any).warrantyEndDate
          ? new Date((initialData as any).warrantyEndDate)
            .toISOString()
            .split("T")[0]
          : "",
        warrantyMonths: (initialData.warrantyMonths as string) || "",
        warrantyProvider: (initialData.warrantyProvider as string) || "",
        supplierName: (initialData.supplierName as string) || "",
        supplierMobile: (initialData.supplierMobile as string) || "",
        supplierAddress: (initialData.supplierAddress as string) || "",
        assignedToId: (initialData.assignedToId as string) || "",
      });
    }
  }, [initialData]);

  const fetchCategories = async () => {
    try {
      const response = await companyAwareApi.get("/hr/assets/categories");
      if (response.data.success) {
        setCategories(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const fetchSuppliers = async () => {
    try {
      const response = await companyAwareApi.get("/procurement/suppliers");
      if (response.data.suppliers) {
        setSuppliers(response.data.suppliers);
      }
    } catch (error) {
      console.error("Error fetching suppliers:", error);
    }
  };

  const fetchEmployees = async () => {
    setLoadingEmployees(true);
    try {
      const response = await companyAwareApi.get("/hr/employees");
      if (response.data.success) {
        setEmployees(response.data.employees || response.data.data || []);
      }
    } catch (error) {
      console.error("Error fetching employees:", error);
    } finally {
      setLoadingEmployees(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const payload = {
        ...formData,
        purchaseValue: formData.purchaseValue
          ? Number(formData.purchaseValue)
          : null,
        warrantyMonths: formData.warrantyMonths
          ? parseInt(formData.warrantyMonths.toString(), 10)
          : null,
        purchaseDate: formData.purchaseDate || null,
        warrantyStartDate: formData.warrantyStartDate || null,
        warrantyEndDate: formData.warrantyEndDate || null,
        assignedToId: formData.assignedToId || null,
      };

      if (initialData) {
        await companyAwareApi.put(`/hr/assets/${initialData.id}`, payload);
      } else {
        await companyAwareApi.post("/hr/assets", payload);
      }
      onSuccess();
    } catch (err: any) {
      setError(err.response?.data?.message || "حدث خطأ أثناء حفظ البيانات");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!usePortal) return;
    if (typeof document === "undefined") return;
    // Prevent background scroll while the modal is open
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, [usePortal]);

  if (usePortal && typeof document === "undefined") return null;

  const modal = (
    <div
      className="fixed inset-0 z-[1100] flex items-center justify-center p-4 sm:p-6 bg-black/50 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
    >
      <div
        className="fixed inset-0 transition-opacity"
        onClick={onClose}
      />

      <div
        className="relative w-full max-w-4xl bg-white dark:bg-gray-800 rounded-xl shadow-2xl overflow-hidden border border-gray-200 dark:border-gray-700 transform transition-all flex flex-col max-h-[90vh]"
      >
        {/* Sticky Header */}
        <div className="bg-gray-50 dark:bg-gray-900/50 px-6 py-4 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center z-10 sticky top-0">
          <h3 className="text-xl font-bold text-gray-900 dark:text-white">
            {initialData ? "تعديل بيانات الأصل" : "إضافة أصل جديد"}
          </h3>
          <button
            onClick={onClose}
            type="button"
            className="p-2 rounded-full text-gray-400 hover:text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-700 transition"
            aria-label="إغلاق نموذج الأصل"
          >
            <XMarkIcon className="h-6 w-6" />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="p-6 overflow-y-auto flex-1">
          {error && (
            <div className="mb-6 bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-lg text-sm font-medium">
              {error}
            </div>
          )}

          <form id="asset-form" onSubmit={handleSubmit} className="space-y-8">
            {/* Section 1: Basic Info */}
            <div className="bg-white dark:bg-gray-800 rounded-lg">
              <h4 className="text-lg font-bold text-gray-900 dark:text-white mb-4 pb-2 border-b border-gray-100 dark:border-gray-700 flex items-center">
                <span className="bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 w-8 h-8 rounded-lg inline-flex items-center justify-center mr-2 ml-2">1</span>
                البيانات الأساسية للأصل
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">
                    اسم الأصل <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    required
