                    />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">
                      قيمة الشراء
                    </label>
                    <input
                      type="number"
                      step="0.01"
                      className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg shadow-sm py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition"
                      value={formData.purchaseValue}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          purchaseValue: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">
                    تاريخ انتهاء الضمان
                  </label>
                  <input
                    type="date"
                    className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg shadow-sm py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition"
                    value={formData.warrantyEndDate}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        warrantyEndDate: e.target.value,
                      })
                    }
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">
                    مدة الضمان (بالأشهر)
                  </label>
                  <input
                    type="number"
                    className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg shadow-sm py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition"
                    value={formData.warrantyMonths}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        warrantyMonths: e.target.value,
                      })
                    }
                    placeholder="مثال: 12"
                  />
                </div>
              </div>
            </div>

            {/* Section 4: Notes */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">
                ملاحظات إضافية
              </label>
              <textarea
                className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg shadow-sm py-3 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition resize-none"
                rows={3}
                value={formData.notes}
                onChange={(e) =>
                  setFormData({ ...formData, notes: e.target.value })
                }
                placeholder="أضف أي تفاصيل أو ملاحظات أخرى هنا..."
              />
            </div>

          </form>
        </div>

        {/* Fixed Footer */}
        <div className="bg-gray-50 dark:bg-gray-900/50 px-6 py-4 border-t border-gray-200 dark:border-gray-700 flex justify-end gap-3 flex-shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg shadow-sm text-sm font-semibold text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 transition-colors"
          >
            إلغاء
          </button>
          <button
            type="submit"
            form="asset-form"
            disabled={loading}
            className="px-5 py-2.5 border border-transparent rounded-lg shadow-sm text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50 transition-colors inline-flex items-center justify-center min-w-[120px]"
          >
            {loading ? (
              <>
                <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                جاري الحفظ...
              </>
            ) : (
              "حفظ الأصل"
            )}
          </button>
        </div>
      </div>
    </div>
  );

  if (usePortal) {
    return createPortal(modal, document.body);
  }

  return modal;
};

export default AssetForm;

import React, { useState, useEffect } from "react";
import {
  MagnifyingGlassIcon,
  FunnelIcon,
  PencilSquareIcon,
  TrashIcon,
  UserPlusIcon,
  ArrowUturnLeftIcon,
  DocumentDuplicateIcon,
  CheckIcon,
  XMarkIcon,
  ChevronDownIcon,
} from "@heroicons/react/24/outline";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, Transition } from "@headlessui/react";
import { companyAwareApi } from "../../../services/companyAwareApi";
import { useCurrency } from "../../../hooks/useCurrency";
import toast from "react-hot-toast";
import AssetForm from "./AssetForm";
import AssetAssignmentModal from "./AssetAssignmentModal";

interface AssetListProps {
  refreshTrigger: number;
}

const AssetList: React.FC<AssetListProps> = ({ refreshTrigger }) => {
  const [assets, setAssets] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [filters, setFilters] = useState({ status: "", categoryId: "" });
  const [categories, setCategories] = useState<any[]>([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const { formatPrice } = useCurrency();

  // Modals
  const [editingAsset, setEditingAsset] = useState<any>(null);
  const [assigningAsset, setAssigningAsset] = useState<any>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  useEffect(() => {
    fetchCategories();
  }, []);

  useEffect(() => {
    // reset pagination on filters/search/refresh change
    setPage(1);
    setHasMore(true);
    fetchAssets(1, true);
  }, [refreshTrigger, search, filters]);

  const fetchCategories = async () => {
    try {
      const response = await companyAwareApi.get("/hr/assets/categories");
      if (response.data.success) {
        setCategories(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const fetchAssets = async (targetPage = page, replace = false) => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.append("page", targetPage.toString());
      params.append("limit", "20");
      if (search) params.append("search", search);
      if (filters.status) params.append("status", filters.status);
      if (filters.categoryId) params.append("categoryId", filters.categoryId);

      const response = await companyAwareApi.get(
        `/hr/assets?${params.toString()}`,
      );
      if (response.data.success) {
        const newData = response.data.data || [];
        const pagination = response.data.pagination;
        setHasMore(
          pagination
            ? targetPage < pagination.totalPages
            : newData.length === 20
        );
        setAssets((prev) => {
          const combined = replace ? newData : [...prev, ...newData];
          // Ensure unique IDs to prevent key warnings
          const uniqueMap = new Map();
          combined.forEach((item: any) => uniqueMap.set(item.id, item));
          return Array.from(uniqueMap.values());
        });
        setPage(targetPage);
      }
    } catch (error) {
      console.error("Error fetching assets:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleClone = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من استنساخ هذا الأصل؟")) return;

    const toastId = toast.loading("جاري استنساخ الأصل...");
    try {
      const response = await companyAwareApi.post(`/hr/assets/${id}/clone`);
      if (response.data.success) {
        toast.success(response.data.message || "تم الاستنساخ بنجاح", { id: toastId });
        fetchAssets(1, true); // Refresh list
      } else {
        toast.error(response.data.message || "فشل في استنساخ الأصل", { id: toastId });
      }
    } catch (error: any) {
      console.error("Error cloning asset:", error);
      toast.error(error.response?.data?.message || "فشل في استنساخ الأصل", { id: toastId });
    }
  };

  const handleDelete = async (id: string | string[]) => {
    const ids = Array.isArray(id) ? id : [id];
    if (ids.length === 0) return;

    const msg = ids.length > 1
      ? `هل أنت متأكد من حذف ${ids.length} أصول مختارة؟`
      : "هل أنت متأكد من حذف هذا الأصل؟";
    if (!window.confirm(msg)) return;

    const toastId = toast.loading(ids.length > 1 ? "جاري حذف الأصول..." : "جاري حذف الأصل...");
    try {
      await Promise.all(ids.map((assetId) => 
        companyAwareApi.delete(`/hr/assets/${assetId}`).catch(err => {
          console.error(`Failed to delete asset ${assetId}:`, err);
          throw err;
        })
      ));
      
      toast.success(ids.length > 1 ? `تم حذف ${ids.length} أصول بنجاح` : "تم حذف الأصل بنجاح", { id: toastId });
      setSelectedIds((prev) => prev.filter((i) => !ids.includes(i)));
      fetchAssets(1, true);
    } catch (error: any) {
      console.error("Error deleting asset:", error);
      toast.error(error.response?.data?.message || "فشل في حذف الأصل", { id: toastId });
    }
  };

  const handleSelectAll = () => {
    if (selectedIds.length === assets.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(assets.map((a) => a.id));
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
    );
  };

  const getStatusBadge = (status: string) => {
    const styles: Record<string, string> = {
      AVAILABLE: "bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-300 border border-green-200 dark:border-green-800/50",
      IN_USE: "bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-300 border border-blue-200 dark:border-blue-800/50",
      MAINTENANCE: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-300 border border-yellow-200 dark:border-yellow-800/50",
      RETIRED: "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300 border border-gray-200 dark:border-gray-600",
      LOST: "bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300 border border-red-200 dark:border-red-800/50",
      RESERVED: "bg-purple-100 text-purple-800 dark:bg-purple-900/40 dark:text-purple-300 border border-purple-200 dark:border-purple-800/50",
    };

    const labels: Record<string, string> = {
      AVAILABLE: "متاح",
      IN_USE: "في الاستخدام",
      MAINTENANCE: "في الصيانة",
      RETIRED: "تالف/مكهن",
      LOST: "مفقود",
      RESERVED: "محجوز",
    };

    return (
      <span
        className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${styles[status] || "bg-gray-100"}`}
      >
        {labels[status] || status}
      </span>
    );
  };

  return (
    <div className="bg-white dark:bg-gray-800 shadow-lg rounded-2xl border border-gray-200 dark:border-gray-700 overflow-hidden">
      {/* Filters */}
      <div className="p-4 border-b border-gray-200 dark:border-gray-700">
        <div className="flex flex-col md:flex-row md:items-center space-y-4 md:space-y-0 md:space-x-4 md:space-x-reverse">
          <div className="flex-1 relative">
            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
              <MagnifyingGlassIcon className="h-5 w-5 text-gray-400" />
            </div>
            <input
              type="text"
              className="block w-full pr-10 pl-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md leading-5 bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 sm:text-sm"
              placeholder="بحث بالاسم، الكود، الرقم التسلسلي..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="flex space-x-2 space-x-reverse">
            <select
              value={filters.status}
              onChange={(e) =>
                setFilters({ ...filters, status: e.target.value })
              }
              className="block w-full pl-3 pr-10 py-2 text-base border-gray-300 dark:border-gray-600 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">جميع الحالات</option>
              <option value="AVAILABLE">متاح</option>
              <option value="IN_USE">في الاستخدام</option>
              <option value="MAINTENANCE">في الصيانة</option>
              <option value="RETIRED">تالف/مكهن</option>
              <option value="LOST">مفقود</option>
            </select>

            <select
              value={filters.categoryId}
              onChange={(e) =>
                setFilters({ ...filters, categoryId: e.target.value })
              }
              className="block w-full pl-3 pr-10 py-2 text-base border-gray-300 dark:border-gray-600 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="">جميع التصنيفات</option>
              {categories.map((cat) => (
                <option key={cat.id} value={cat.id}>
                  {cat.name}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
          <thead className="bg-gradient-to-l from-indigo-600 via-violet-600 to-purple-700">
            <tr>
              <th scope="col" className="px-4 py-3 text-right w-12">
                <input
                  type="checkbox"
                  checked={assets.length > 0 && selectedIds.length === assets.length}
                  onChange={handleSelectAll}
                  className="h-4 w-4 rounded border-white/30 text-violet-400 focus:ring-violet-400 focus:ring-offset-0 bg-white/10 cursor-pointer"
                />
              </th>
              <th
                scope="col"
                className="px-6 py-3 text-right text-xs font-bold text-white uppercase tracking-wider"
              >
                الأصل
              </th>
              <th
                scope="col"
                className="px-6 py-3 text-right text-xs font-bold text-white uppercase tracking-wider"
              >
                التصنيف
              </th>
              <th
                scope="col"
                className="px-6 py-3 text-right text-xs font-bold text-white uppercase tracking-wider"
              >
                الحالة
              </th>
              <th
                scope="col"
                className="px-6 py-3 text-right text-xs font-bold text-white uppercase tracking-wider"
              >
                العهدة الحالية
              </th>
              <th
                scope="col"
                className="px-6 py-3 text-right text-xs font-bold text-white uppercase tracking-wider"
              >
                القيمة
              </th>
              <th scope="col" className="relative px-6 py-3">
                <span className="sr-only">إجراءات</span>
              </th>
            </tr>
          </thead>
          <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
            {loading ? (
              <tr>
                <td colSpan={7} className="px-6 py-4 text-center">
                  <div className="flex justify-center">
                    <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-indigo-600"></div>
                  </div>
                </td>
              </tr>
            ) : assets.length === 0 ? (
              <tr>
                <td
                  colSpan={7}
                  className="px-6 py-12 text-center text-gray-500 dark:text-gray-400"
                >
                  {search || filters.status || filters.categoryId
                    ? "لا توجد نتائج مطابقة للبحث/الفلاتر"
                    : "لا توجد أصول مسجلة حالياً"}
                </td>
              </tr>
            ) : (
              assets.map((asset) => {
                const isSelected = selectedIds.includes(asset.id);
                return (
                <tr
                  key={asset.id}
                  className={`transition-all duration-150 cursor-pointer ${
                    isSelected
                      ? "bg-violet-50/70 dark:bg-violet-900/20 ring-1 ring-inset ring-violet-200 dark:ring-violet-700/30"
                      : "hover:bg-gray-50 dark:hover:bg-gray-700/50"
                  }`}
                  onClick={(e) => {
                    // Don't toggle on button/input clicks
                    if ((e.target as HTMLElement).closest('button, input, a')) return;
                    toggleSelect(asset.id);
                  }}
                >
                  <td className="px-4 py-4 whitespace-nowrap" onClick={(e) => e.stopPropagation()}>
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={() => toggleSelect(asset.id)}
                      className="h-4 w-4 rounded border-gray-300 text-violet-600 focus:ring-violet-500 cursor-pointer"
                    />
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex flex-wrap items-center gap-2 text-sm leading-tight">
                      <span className="font-medium text-gray-900 dark:text-white">
                        {asset.name}
                      </span>
                      {asset.code && (
                        <span className="bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded text-xs text-gray-700 dark:text-gray-200">
                          {asset.code}
                        </span>
                      )}
                      {asset.model && (
                        <span className="text-gray-500 dark:text-gray-400">
                          {asset.model}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                    {asset.category?.name || "-"}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {getStatusBadge(asset.status)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                    {asset.currentHolder ? (
                      <div className="flex items-center">
                        <div className="h-8 w-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold ml-2">
                          {asset.currentHolder.firstName.charAt(0)}
                        </div>
                        <div>
                          <div className="font-medium">
                            {asset.currentHolder.firstName}{" "}
                            {asset.currentHolder.lastName}
                          </div>
                          <div className="text-xs">
                            {asset.currentHolder.employeeNumber}
                          </div>
                        </div>
                      </div>
                    ) : (
                      <span className="text-gray-400">-</span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                    {asset.purchaseValue
                      ? formatPrice(asset.purchaseValue)
                      : "-"}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <div className="flex items-center justify-end space-x-2 space-x-reverse">
                      {asset.status === "AVAILABLE" ? (
                        <button
                          onClick={() =>
                            setAssigningAsset({ ...asset, type: "assign" })
                          }
                          className="text-indigo-600 dark:text-indigo-400 hover:text-indigo-900 bg-indigo-50 dark:bg-indigo-900/40 p-1.5 rounded-xl hover:bg-indigo-100 transition-all"
                          title="تسليم عهدة"
                        >
                          <UserPlusIcon className="h-5 w-5" />
                        </button>
                      ) : (
                        <button
                          onClick={() =>
                            setAssigningAsset({ ...asset, type: "return" })
                          }
                          className="text-orange-600 dark:text-orange-400 hover:text-orange-900 bg-orange-50 dark:bg-orange-900/40 p-1.5 rounded-xl hover:bg-orange-100 transition-all"
                          title="استرجاع عهدة"
                        >
                          <ArrowUturnLeftIcon className="h-5 w-5" />
                        </button>
                      )}

                      <button
                        onClick={() => handleClone(asset.id)}
                        className="text-amber-600 dark:text-amber-400 hover:text-amber-900 bg-amber-50 dark:bg-amber-900/40 p-1.5 rounded-xl hover:bg-amber-100 transition-all"
                        title="استنساخ"
                      >
                        <DocumentDuplicateIcon className="h-5 w-5" />
                      </button>

                      <button
                        onClick={() => setEditingAsset(asset)}
                        className="text-blue-600 dark:text-blue-400 hover:text-blue-900 bg-blue-50 dark:bg-blue-900/40 p-1.5 rounded-xl hover:bg-blue-100 transition-all"
                        title="تعديل"
                      >
                        <PencilSquareIcon className="h-5 w-5" />
                      </button>

                      <button
                        onClick={() => handleDelete(asset.id)}
                        className="text-red-600 dark:text-red-400 hover:text-red-900 bg-red-50 dark:bg-red-900/40 p-1.5 rounded-xl hover:bg-red-100 transition-all"
                        title="حذف"
                      >
                        <TrashIcon className="h-5 w-5" />
                      </button>
                    </div>
                  </td>
                </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Modals */}
      {editingAsset && (
        <AssetForm
          initialData={editingAsset}
          usePortal={false}
          onClose={() => setEditingAsset(null)}
          onSuccess={() => {
            setEditingAsset(null);
            fetchAssets(1, true);
          }}
        />
      )}

      {assigningAsset && (
        <AssetAssignmentModal
          asset={assigningAsset}
          type={assigningAsset.type}
          usePortal
          onClose={() => setAssigningAsset(null)}
          onSuccess={() => {
            setAssigningAsset(null);
            fetchAssets(1, true);
          }}
        />
      )}

      {/* Load more */}
      {hasMore && !loading && (
        <div className="p-4 text-center border-t border-gray-100 dark:border-gray-700">
          <button
            onClick={() => fetchAssets(page + 1)}
            className="px-6 py-2.5 bg-gradient-to-r from-indigo-600 to-violet-600 text-white rounded-xl hover:from-indigo-700 hover:to-violet-700 transition-all shadow-md hover:shadow-lg active:scale-95"
          >
            تحميل المزيد
          </button>
        </div>
      )}

      {/* Floating Bulk Actions Bar */}
      <AnimatePresence>
        {selectedIds.length > 0 && (
          <motion.div
            initial={{ y: 80, opacity: 0, scale: 0.95 }}
            animate={{ y: 0, opacity: 1, scale: 1 }}
            exit={{ y: 80, opacity: 0, scale: 0.95 }}
            transition={{ type: "spring", damping: 25, stiffness: 350 }}
            className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50"
          >
            <div className="bg-gradient-to-r from-[#1a1040] to-[#251858] text-white px-6 py-3.5 rounded-2xl shadow-2xl shadow-violet-900/40 border border-white/10 flex items-center gap-5 backdrop-blur-xl">
              {/* Counter */}
              <div className="flex items-center gap-3 border-l border-white/10 pl-5">
                <div className="p-2 bg-violet-500/30 rounded-lg">
                  <CheckIcon className="h-5 w-5 text-violet-300" />
                </div>
                <span className="font-bold text-sm whitespace-nowrap">
                  {selectedIds.length} عنصر محدد
                </span>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-2">
                {/* Delete */}
                <button
                  onClick={() => handleDelete(selectedIds)}
                  className="flex items-center gap-2 px-4 py-2 bg-red-500/10 hover:bg-red-500 text-red-300 hover:text-white border border-red-400/20 hover:border-red-500 rounded-xl transition-all duration-200 font-medium text-sm group"
                >
                  <TrashIcon className="h-4 w-4 group-hover:scale-110 transition-transform" />
                  <span className="hidden sm:inline">حذف</span>
                </button>

                {/* Status change */}
                <Menu as="div" className="relative">
                  <Menu.Button className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/15 border border-white/10 rounded-xl transition-all font-medium text-sm">
                    <span className="hidden sm:inline">تغيير الحالة</span>
                    <ChevronDownIcon className="h-4 w-4" />
                  </Menu.Button>
                  <Transition
                    as={React.Fragment}
                    enter="transition ease-out duration-150"
                    enterFrom="transform opacity-0 scale-95"
                    enterTo="transform opacity-100 scale-100"
                    leave="transition ease-in duration-75"
                    leaveFrom="transform opacity-100 scale-100"
                    leaveTo="transform opacity-0 scale-95"
                  >
                    <Menu.Items className="absolute bottom-full mb-2 left-0 w-44 origin-bottom-left bg-[#251854] rounded-xl shadow-2xl border border-white/10 p-1 z-50">
                      {[
                        { key: "AVAILABLE", label: "متاح", dot: "bg-green-400" },
                        { key: "MAINTENANCE", label: "صيانة", dot: "bg-yellow-400" },
                        { key: "RETIRED", label: "تكهين", dot: "bg-gray-400" },
                        { key: "LOST", label: "مفقود", dot: "bg-red-400" },
                      ].map((status) => (
                        <Menu.Item key={status.key}>
                          {({ active }) => (
                            <button
                              className={`${active ? "bg-white/10" : ""} flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-right transition-colors`}
                              onClick={async () => {
                                const toastId = toast.loading("جاري تحديث الحالة...");
                                try {
                                  await Promise.all(
                                    selectedIds.map((assetId) =>
                                      companyAwareApi.put(`/hr/assets/${assetId}`, { status: status.key })
                                    )
                                  );
                                  toast.success(`تم تغيير حالة ${selectedIds.length} أصول إلى ${status.label}`, { id: toastId });
                                  setSelectedIds([]);
                                  fetchAssets(1, true);
                                } catch {
                                  toast.error("فشل في تحديث الحالة", { id: toastId });
                                }
                              }}
                            >
                              <div className={`w-2 h-2 rounded-full ${status.dot}`}></div>
                              <span className="flex-1">{status.label}</span>
                            </button>
                          )}
                        </Menu.Item>
                      ))}
                    </Menu.Items>
                  </Transition>
                </Menu>

                {/* Clear selection */}
                <button
                  onClick={() => setSelectedIds([])}
                  className="p-2 hover:bg-white/10 rounded-xl transition-all"
                  title="إلغاء التحديد"
                >
                  <XMarkIcon className="h-5 w-5 text-gray-400 hover:text-white transition-colors" />
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AssetList;

import React, { useState, useEffect } from "react";
import {
  CubeIcon,
  CurrencyDollarIcon,
  ClipboardDocumentCheckIcon,
  WrenchScrewdriverIcon,
} from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../../services/companyAwareApi";
import { useCurrency } from "../../../hooks/useCurrency";

const AssetStats: React.FC<{ refreshTrigger: number }> = ({
  refreshTrigger,
}) => {
  const [stats, setStats] = useState({
    totalCount: 0,
    totalValue: 0,
    inUseCount: 0,
    maintenanceCount: 0,
  });
  const { formatPrice } = useCurrency();

  useEffect(() => {
    fetchStats();
  }, [refreshTrigger]);

  const fetchStats = async () => {
    try {
      // For now, we calculate stats from the assets list because we didn't make a specific stats endpoint
      // This is acceptable for MVP
      const response = await companyAwareApi.get("/hr/assets");
      if (response.data.success) {
        const assets = response.data.data;
        const totalCount = assets.length;
        const totalValue = assets.reduce(
          (sum: number, asset: any) => sum + (Number(asset.purchaseValue) || 0),
          0,
        );
        const inUseCount = assets.filter(
          (a: any) => a.status === "IN_USE",
        ).length;
        const maintenanceCount = assets.filter(
          (a: any) => a.status === "MAINTENANCE",
        ).length;

        setStats({ totalCount, totalValue, inUseCount, maintenanceCount });
      }
    } catch (error) {
      console.error("Error fetching asset stats:", error);
    }
  };

  const statCards = [
    {
      name: "إجمالي الأصول",
      value: stats.totalCount,
      icon: CubeIcon,
      color: "bg-indigo-50 text-indigo-700",
    },
    {
      name: "القيمة الإجمالية",
      value: formatPrice(stats.totalValue),
      icon: CurrencyDollarIcon,
      color: "bg-green-50 text-green-700",
    },
    {
      name: "أصول في الاستخدام",
      value: stats.inUseCount,
      icon: ClipboardDocumentCheckIcon,
      color: "bg-blue-50 text-blue-700",
    },
    {
      name: "في الصيانة",
      value: stats.maintenanceCount,
      icon: WrenchScrewdriverIcon,
      color: "bg-yellow-50 text-yellow-700",
    },
  ];

  return (
    <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-4">
      {statCards.map((card) => (
        <div
          key={card.name}
          className="relative overflow-hidden rounded-lg bg-white dark:bg-gray-800 px-4 pt-5 pb-12 shadow sm:px-6 sm:pt-6 border border-gray-200 dark:border-gray-700"
        >
          <dt>
            <div className={`absolute rounded-md p-3 ${card.color}`}>
              <card.icon className="h-6 w-6" aria-hidden="true" />
            </div>
            <p className="ml-16 truncate text-sm font-medium text-gray-500 dark:text-gray-400">
              {card.name}
            </p>
          </dt>
          <dd className="ml-16 flex items-baseline pb-1 sm:pb-2">
            <p className="text-2xl font-semibold text-gray-900 dark:text-white">
              {card.value}
            </p>
          </dd>
        </div>
      ))}
    </div>
  );
};

export default AssetStats;

import React, { useState, useEffect } from "react";
import {
  PlusIcon,
  TrashIcon,
  PhoneIcon,
  MapPinIcon,
} from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../../services/companyAwareApi";

const AssetSuppliers: React.FC = () => {
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [newSupplier, setNewSupplier] = useState({
    name: "",
    mobile: "",
    address: "",
  });
  const [adding, setAdding] = useState(false);

  useEffect(() => {
    fetchSuppliers();
  }, []);

  const fetchSuppliers = async () => {
    setLoading(true);
    try {
      const response = await companyAwareApi.get("/procurement/suppliers");
      if (response.data.suppliers) {
        setSuppliers(response.data.suppliers);
      }
    } catch (error) {
      console.error("Error fetching suppliers:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSupplier.name.trim()) return;

    setAdding(true);
    try {
      const response = await companyAwareApi.post(
        "/procurement/suppliers",
        newSupplier,
      );
      if (response.data.success) {
        setNewSupplier({ name: "", mobile: "", address: "" });
        fetchSuppliers();
      }
    } catch (error) {
      console.error("Error creating supplier:", error);
      alert("فشل في إضافة المورد");
    } finally {
      setAdding(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا المورد؟")) return;

    try {
      const response = await companyAwareApi.delete(
        `/procurement/suppliers/${id}`,
      );
      if (response.data.success) {
        fetchSuppliers();
      }
    } catch (error) {
      console.error("Error deleting supplier:", error);
      alert("فشل في حذف المورد. قد يكون مرتبطاً بطلبات شراء أو أصول.");
    }
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
      {/* List */}
      <div className="md:col-span-2 space-y-4">
        <h3 className="text-lg font-medium text-gray-900 dark:text-white">
          الموردون المسجلون
        </h3>

        {loading ? (
          <div className="flex justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
          </div>
        ) : suppliers.length === 0 ? (
          <div className="text-center py-8 text-gray-500 bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700">
            لا يوجد موردون مسجلون بعد
          </div>
        ) : (
          <div className="bg-white dark:bg-gray-800 shadow rounded-lg border border-gray-200 dark:border-gray-700 divide-y divide-gray-200 dark:divide-gray-700">
            {suppliers.map((s) => (
              <div key={s.id} className="p-4 flex items-center justify-between">
                <div className="space-y-1">
                  <h4 className="text-sm font-bold text-gray-900 dark:text-white">
                    {s.name}
                  </h4>
                  <div className="flex items-center text-xs text-gray-500 dark:text-gray-400">
                    <PhoneIcon className="h-3 w-3 mr-1" />
                    {s.mobile || "غير مسجل"}
                  </div>
                  <div className="flex items-center text-xs text-gray-500 dark:text-gray-400">
                    <MapPinIcon className="h-3 w-3 mr-1" />
                    {s.address || "لا يوجد عنوان"}
                  </div>
                </div>
                <button
                  onClick={() => handleDelete(s.id)}
                  className="text-red-600 hover:text-red-900 p-2 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-colors"
                  title="حذف"
                >
                  <TrashIcon className="h-5 w-5" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Add Form */}
      <div>
        <div className="bg-white dark:bg-gray-800 shadow rounded-lg border border-gray-200 dark:border-gray-700 p-4 sticky top-6">
          <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">
            إضافة مورد جديد
          </h3>
          <form onSubmit={handleAdd} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                اسم المورد *
              </label>
              <input
                type="text"
                required
                className="mt-1 block w-full border border-gray-300 dark:border-gray-600 rounded-md shadow-sm py-2 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                value={newSupplier.name}
                onChange={(e) =>
                  setNewSupplier({ ...newSupplier, name: e.target.value })
                }
                placeholder="مثال: شركة النصر للتكنولوجيا"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                رقم الموبايل
              </label>
              <input
                type="text"
                className="mt-1 block w-full border border-gray-300 dark:border-gray-600 rounded-md shadow-sm py-2 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                value={newSupplier.mobile}
                onChange={(e) =>
                  setNewSupplier({ ...newSupplier, mobile: e.target.value })
                }
                placeholder="01xxxxxxxxx"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                العنوان
              </label>
              <textarea
                className="mt-1 block w-full border border-gray-300 dark:border-gray-600 rounded-md shadow-sm py-2 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                rows={2}
                value={newSupplier.address}
                onChange={(e) =>
                  setNewSupplier({ ...newSupplier, address: e.target.value })
                }
                placeholder="العنوان بالتفصيل..."
              />
            </div>
            <button
              type="submit"
              disabled={adding}
              className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50 transition-all font-bold"
            >
              {adding ? "جاري الإضافة..." : "إضافة المورد"}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AssetSuppliers;

import React, { useState, useEffect } from "react";
import {
  ClipboardDocumentListIcon,
  UserIcon,
  ComputerDesktopIcon,
  MagnifyingGlassIcon,
  CalendarIcon,
  CheckCircleIcon,
  PencilSquareIcon,
  ArrowUturnLeftIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";
import { motion, AnimatePresence } from "framer-motion";
import { companyAwareApi } from "../../../services/companyAwareApi";
import { format } from "date-fns";
import { ar } from "date-fns/locale";
import toast from "react-hot-toast";
import AssetForm from "./AssetForm";
import AssetAssignmentModal from "./AssetAssignmentModal";

interface CustodyRecord {
  id: string;
  assetId: string;
  employeeId: string;
  assignedAt: string;
  returnedAt: string | null;
  condition: string;
  notes: string;
  asset: {
    id: string;
    name: string;
    code: string;
    category: { name: string };
    status: string;
  };
  employee: {
    firstName: string;
    lastName: string;
    employeeId: string;
  };
}

const CustodyHistory: React.FC = () => {
  const [records, setRecords] = useState<CustodyRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  // States for Modals
  const [editingAsset, setEditingAsset] = useState<any>(null);
  const [returningAsset, setReturningAsset] = useState<any>(null);

  useEffect(() => {
    fetchRecords();
  }, []);

  const fetchRecords = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/hr/assets/custody/active");
      if (
        response.data.success &&
        response.data.data &&
        response.data.data.length > 0
      ) {
        setRecords(response.data.data);
      } else {
        setRecords([]);
      }
    } catch (error) {
      console.error("Error fetching custody records:", error);
      setRecords([]);
    } finally {
      setLoading(false);
    }
  };

  const filteredRecords = records.filter(
    (record) =>
      record.asset.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      record.employee.firstName
        .toLowerCase()
        .includes(searchTerm.toLowerCase()) ||
      record.employee.lastName
        .toLowerCase()
        .includes(searchTerm.toLowerCase()) ||
      record.asset.code.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  if (loading) {
    return (
      <div className="flex flex-col justify-center items-center py-40 gap-4">
        <div className="relative">
          <div className="absolute inset-0 bg-indigo-500/20 rounded-full blur-xl animate-pulse"></div>
          <div className="animate-spin rounded-full h-16 w-16 border-[3px] border-indigo-100 border-t-indigo-600 relative"></div>
        </div>
        <p className="text-gray-400 font-bold animate-pulse">جاري تحميل البيانات...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <ClipboardDocumentListIcon className="h-7 w-7 text-amber-600" />
            العهد النشطة
          </h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            تتبع وإدارة جميع الأصول المسلمة للموظفين حالياً
          </p>
        </div>
        <div className="relative max-w-sm w-full">
          <MagnifyingGlassIcon className="h-5 w-5 absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-indigo-500 transition-colors" />
          <input
            type="text"
            placeholder="بحث عن موظف أو أصل..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pr-12 pl-4 py-3 border-2 border-gray-100 dark:border-gray-700 rounded-2xl bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 transition-all shadow-sm font-medium"
          />
        </div>
      </div>

      {filteredRecords.length === 0 ? (
        <motion.div 
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="text-center py-20 bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-sm"
        >
          <div className="h-24 w-24 bg-gray-50 dark:bg-gray-700/50 rounded-full flex items-center justify-center mx-auto mb-6">
            <ClipboardDocumentListIcon className="h-12 w-12 text-gray-300 dark:text-gray-600" />
          </div>
          <h3 className="text-xl font-bold text-gray-400">لا توجد عهد نشطة حالياً</h3>
          <p className="text-sm text-gray-400 mt-2">ابدأ بتعيين أصل لموظف من قائمة الأصول</p>
        </motion.div>
      ) : (
        <div className="grid grid-cols-1 gap-6">
          <AnimatePresence mode="popLayout">
            {filteredRecords.map((record, idx) => (
              <motion.div
                key={record.id}
                layout
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ delay: idx * 0.05 }}
                className="group relative bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-2xl transition-all duration-500 overflow-hidden"
              >
                {/* Decorative background circle */}
                <div className="absolute -left-10 -bottom-10 w-40 h-40 bg-indigo-500/5 rounded-full blur-3xl opacity-0 group-hover:opacity-100 transition-opacity"></div>
                
                <div className="flex flex-col lg:flex-row lg:items-center gap-8 relative z-10">
                  {/* Asset Info */}
                  <div className="flex items-center gap-5 flex-1 min-w-[300px]">
                    <div className="relative">
                      <div className="p-4 bg-gradient-to-br from-indigo-50 to-violet-50 dark:from-indigo-900/20 dark:to-violet-900/20 rounded-[2rem] group-hover:rotate-6 transition-transform duration-500">
                        <ComputerDesktopIcon className="h-10 w-10 text-indigo-600 dark:text-indigo-400" />
                      </div>
                      <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full flex items-center justify-center">
                        <CheckCircleIcon className="h-4 w-4 text-white" />
                      </div>
                    </div>
                    <div>
                      <h4 className="font-black text-xl text-gray-900 dark:text-white mb-2 decoration-indigo-500/30 group-hover:underline underline-offset-4 decoration-2">
                        {record.asset.name}
                      </h4>
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-black text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-900/30 px-3 py-1 rounded-full border border-indigo-100 dark:border-indigo-800">
                          {record.asset.code}
                        </span>
                        <span className="text-xs font-bold text-gray-400 flex items-center gap-1">
                          <TagIcon className="h-3 w-3" />
                          {record.asset.category.name}
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Divider line for mobile */}
                  <div className="lg:hidden h-px bg-gray-50 dark:bg-gray-700/50"></div>

                  {/* Employee Info */}
                  <div className="flex items-center gap-4 flex-1">
                    <div className="w-12 h-12 bg-gradient-to-tr from-violet-600 to-fuchsia-500 rounded-2xl flex items-center justify-center shadow-lg shadow-violet-500/20">
                      <UserIcon className="h-6 w-6 text-white" />
                    </div>
                    <div>
                      <p className="text-[10px] font-black text-violet-400 uppercase tracking-widest mb-0.5">الموظف الحالي</p>
                      <h5 className="font-black text-lg text-gray-900 dark:text-white">
                        {record.employee.firstName} {record.employee.lastName}
                      </h5>
                    </div>
                  </div>

                  {/* Assignment Info */}
                  <div className="flex flex-col sm:flex-row items-center gap-8 justify-end">
                    <div className="text-right">
                      <div className="flex items-center gap-1.5 text-[10px] font-black text-gray-400 uppercase tracking-wider mb-1 justify-end">
                        <CalendarIcon className="h-3.5 w-3.5 text-indigo-400" />
                        <span>منذ تاريخ</span>
                      </div>
                      <p className="text-sm font-black text-gray-700 dark:text-gray-300 bg-gray-50 dark:bg-gray-700/30 px-3 py-1.5 rounded-xl border border-gray-100 dark:border-gray-700/50">
                        {format(new Date(record.assignedAt), "PPP", { locale: ar })}
                      </p>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-3">
                      <button
                        onClick={() => setEditingAsset(record.asset)}
                        className="p-3 bg-white dark:bg-gray-800 text-gray-400 hover:text-indigo-600 border border-gray-100 dark:border-gray-700 rounded-2xl transition-all shadow-sm hover:shadow-lg hover:-translate-y-1"
                        title="تعديل"
                      >
                        <PencilSquareIcon className="h-5 w-5" />
                      </button>
                      <button
                        onClick={() => setReturningAsset({ ...record.asset, type: 'return' })}
                        className="flex items-center gap-2 px-5 py-3 bg-indigo-600 text-white rounded-2xl font-black shadow-lg shadow-indigo-600/20 hover:shadow-indigo-600/40 hover:-translate-y-1 active:translate-y-0 transition-all text-sm"
                      >
                        <ArrowPathIcon className="h-4 w-4" />
                        استرجاع
                      </button>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {/* Modals Integration */}
      {editingAsset && (
        <AssetForm
          initialData={editingAsset}
          onClose={() => setEditingAsset(null)}
          onSuccess={() => {
            setEditingAsset(null);
            fetchRecords();
          }}
        />
      )}

      {returningAsset && (
        <AssetAssignmentModal
          asset={returningAsset}
          type="return"
          onClose={() => setReturningAsset(null)}
          onSuccess={() => {
            setReturningAsset(null);
            fetchRecords();
          }}
        />
      )}
    </div>
  );
};

export default CustodyHistory;

import React, { useState, useEffect } from "react";
import {
  WrenchScrewdriverIcon,
  CalendarDaysIcon,
  BellAlertIcon,
  PlusIcon,
  ChartBarIcon,
  ShieldExclamationIcon,
  ClockIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";
import { format } from "date-fns";
import { companyAwareApi } from "../../../../services/companyAwareApi";
import { useCurrency } from "../../../../hooks/useCurrency";
import { toast } from "react-hot-toast";

interface MaintenanceRecord {
  id: string;
  assetId: string;
  type: string;
  description: string;
  cost: number;
  status: "SCHEDULED" | "IN_PROGRESS" | "COMPLETED" | "CANCELLED";
  startDate: string;
  completionDate?: string;
  performedBy?: string;
  notes?: string;
  asset?: {
    name: string;
    code: string;
  };
}

interface Alert {
  assetId?: string;
  maintenanceId?: string;
  name: string;
  code: string;
  endDate?: string;
  scheduledDate?: string;
  maintenanceType?: string;
  type: "WARRANTY" | "MAINTENANCE";
}

const AssetMaintenanceSection: React.FC = () => {
  const [alerts, setAlerts] = useState<{
    expiringWarranties: Alert[];
    upcomingMaintenance: Alert[];
  }>({
    expiringWarranties: [],
    upcomingMaintenance: [],
  });
  const [history, setHistory] = useState<MaintenanceRecord[]>([]);
  const [assets, setAssets] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const { formatPrice } = useCurrency();

  const [newRecord, setNewRecord] = useState({
    assetId: "",
    type: "صيانة دورية",
    description: "",
    cost: "",
    status: "COMPLETED",
    startDate: format(new Date(), "yyyy-MM-dd"),
    performedBy: "",
    notes: "",
  });

  const fetchData = async () => {
    setLoading(true);
    console.log("🔄 Fetching maintenance data...");
    try {
      // Fetch assets
      const assetsRes = await companyAwareApi.get("/hr/assets");
      if (assetsRes.data.success) {
        console.log("✅ Assets fetched:", assetsRes.data.data.length);
        setAssets(assetsRes.data.data);
      }

      // Fetch alerts
      try {
        const alertsRes = await companyAwareApi.get("/hr/assets/alerts");
        if (alertsRes.data.success) setAlerts(alertsRes.data.data);
      } catch (e) {
        console.error("Error fetching alerts:", e);
      }

      // Fetch history
      try {
        const historyRes = await companyAwareApi.get("/hr/assets/maintenance");
        if (historyRes.data.success) setHistory(historyRes.data.data);
      } catch (e) {
        console.error("Error fetching maintenance history:", e);
      }
    } catch (error) {
      console.error("Error in main maintenance fetch:", error);
      toast.error("حدث خطأ أثناء تحميل البيانات");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleAddMaintenance = async () => {
    if (!newRecord.assetId || !newRecord.description) {
      toast.error("يرجى اكمال البيانات المطلوبة");
      return;
    }

    try {
      const response = await companyAwareApi.post(
        `/hr/assets/${newRecord.assetId}/maintenance`,
        newRecord,
      );
      if (response.data.success) {
        toast.success("تم تسجيل سجل الصيانة بنجاح");
        setShowAddModal(false);
        fetchData();
      }
    } catch (error) {
      toast.error("فشل في حفظ سجل الصيانة");
    }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-900 dark:text-white flex items-center gap-3">
            <WrenchScrewdriverIcon className="h-8 w-8 text-indigo-600" />
            الصيانة والضمان
          </h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            إدارة سجلات الصيانة، جدولة المواعيد، ومتابعة تنبيهات الضمان
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setShowAddModal(true)}
            className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 dark:shadow-none"
          >
            <PlusIcon className="h-5 w-5" />
            تسجيل صيانة
          </button>
          <button
            onClick={fetchData}
            className="p-2.5 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl hover:bg-gray-50 transition-all"
          >
            <ArrowPathIcon
              className={`h-5 w-5 text-gray-500 ${loading ? "animate-spin" : ""}`}
            />
          </button>
        </div>
      </div>

      {/* Alerts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Due Warranties */}
        <div className="bg-white dark:bg-gray-800 rounded-3xl border border-red-100 dark:border-red-900/20 overflow-hidden shadow-sm">
          <div className="bg-red-50 dark:bg-red-900/10 px-6 py-4 border-b border-red-100 dark:border-red-900/20 flex items-center gap-3">
            <ShieldExclamationIcon className="h-5 w-5 text-red-600" />
            <h3 className="font-black text-red-900 dark:text-red-400">
              تنبيهات انتهاء الضمان (خلال 30 يوم)
            </h3>
          </div>
          <div className="p-4 space-y-3">
            {alerts.expiringWarranties.length === 0 ? (
              <p className="text-center py-8 text-gray-400 italic text-sm">
                لا توجد ضمانات قاربت على الانتهاء
              </p>
            ) : (
              alerts.expiringWarranties.map((alert, i) => (
                <div
                  key={i}
                  className="flex items-center justify-between p-3 bg-red-50/30 dark:bg-red-900/5 rounded-2xl border border-red-50 dark:border-red-900/10 transition-all hover:scale-[1.01]"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-red-100 dark:bg-red-900/30 flex items-center justify-center text-red-600">
                      <BellAlertIcon className="h-5 w-5" />
                    </div>
                    <div>
                      <h4 className="font-bold text-gray-900 dark:text-white text-sm">
                        {alert.name}
                      </h4>
                      <p className="text-[10px] text-gray-400 font-mono">
                        {alert.code}
                      </p>
                    </div>
                  </div>
                  <div className="text-left">
                    <span className="text-[10px] text-gray-400 block mb-1">
                      تاريخ الانتهاء
                    </span>
                    <span className="text-xs font-black text-red-600">
                      {alert.endDate
                        ? format(new Date(alert.endDate), "yyyy/MM/dd")
                        : "-"}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Upcoming Maintenance */}
        <div className="bg-white dark:bg-gray-800 rounded-3xl border border-amber-100 dark:border-amber-900/20 overflow-hidden shadow-sm">
          <div className="bg-amber-50 dark:bg-amber-900/10 px-6 py-4 border-b border-amber-100 dark:border-amber-900/20 flex items-center gap-3">
            <CalendarDaysIcon className="h-5 w-5 text-amber-600" />
            <h3 className="font-black text-amber-900 dark:text-amber-400">
              مواعيد الصيانة القادمة
            </h3>
          </div>
          <div className="p-4 space-y-3">
            {alerts.upcomingMaintenance.length === 0 ? (
              <p className="text-center py-8 text-gray-400 italic text-sm">
                لا توجد صيانات مجدولة حالياً
              </p>
            ) : (
              alerts.upcomingMaintenance.map((alert, i) => (
                <div
                  key={i}
                  className="flex items-center justify-between p-3 bg-amber-50/30 dark:bg-amber-900/5 rounded-2xl border border-amber-50 dark:border-amber-900/10 transition-all hover:scale-[1.01]"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-amber-100 dark:bg-amber-900/30 flex items-center justify-center text-amber-600">
                      <ClockIcon className="h-5 w-5" />
                    </div>
                    <div>
                      <h4 className="font-bold text-gray-900 dark:text-white text-sm">
                        {alert.name}
                      </h4>
                      <p className="text-[10px] text-gray-400 font-bold text-amber-600 uppercase">
                        {alert.maintenanceType}
                      </p>
                    </div>
                  </div>
                  <div className="text-left">
                    <span className="text-[10px] text-gray-400 block mb-1">
                      تاريخ الصيانة
                    </span>
                    <span className="text-xs font-black text-gray-900 dark:text-white">
                      {alert.scheduledDate
                        ? format(new Date(alert.scheduledDate), "yyyy/MM/dd")
                        : "-"}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      {/* Maintenance History Table */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-black text-gray-900 dark:text-white flex items-center gap-2">
            <ChartBarIcon className="h-6 w-6 text-indigo-600" />
            سجل العمليات الأخير
          </h3>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] border border-gray-100 dark:border-gray-700 shadow-xl overflow-hidden">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-gray-50 dark:bg-gray-900/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
                <th className="px-6 py-5">الأصل</th>
                <th className="px-6 py-5">النوع</th>
                <th className="px-6 py-5">التكلفة</th>
                <th className="px-6 py-5">التاريخ</th>
                <th className="px-6 py-5">الحالة</th>
                <th className="px-6 py-5">بواسطة</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-gray-700">
              {history.map((rec) => (
                <tr
                  key={rec.id}
                  className="hover:bg-gray-50/50 dark:hover:bg-gray-700/30 transition-colors group"
                >
                  <td className="px-6 py-5">
                    <div className="flex flex-col">
                      <span className="font-bold text-gray-900 dark:text-white text-sm">
                        {rec.asset?.name}
                      </span>
                      <span className="text-[10px] text-gray-400 font-mono">
                        {rec.asset?.code}
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-5">
                    <div className="flex flex-col">
                      <span className="font-medium text-gray-700 dark:text-gray-300 text-sm">
                        {rec.type}
                      </span>
                      <p className="text-[10px] text-gray-400 italic truncate max-w-[150px]">
                        {rec.description}
                      </p>
                    </div>
                  </td>
                  <td className="px-6 py-5">
                    <span className="font-black text-sm text-gray-900 dark:text-white">
                      {formatPrice(rec.cost)}
                    </span>
                  </td>
                  <td className="px-6 py-5">
                    <span className="text-xs font-bold text-gray-500">
                      {format(new Date(rec.startDate), "yyyy/MM/dd")}
                    </span>
                  </td>
                  <td className="px-6 py-5">
                    <span
                      className={`px-3 py-1 rounded-lg text-[10px] font-black border ${rec.status === "COMPLETED"
                          ? "bg-green-100 text-green-700 border-green-200"
                          : rec.status === "SCHEDULED"
                            ? "bg-blue-100 text-blue-700 border-blue-200"
                            : "bg-gray-100 text-gray-600 border-gray-200"
                        }`}
                    >
                      {rec.status === "COMPLETED" ? "مكتمل" : "مجدول"}
                    </span>
                  </td>
                  <td className="px-6 py-5 text-sm text-gray-500">
                    {rec.performedBy || "-"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Maintenance Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white dark:bg-gray-800 w-full max-w-2xl rounded-[2.5rem] p-10 shadow-2xl animate-scale-in">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black text-gray-900 dark:text-white">
                تسجيل عملية صيانة / جدولة
              </h3>
              <button
                onClick={() => setShowAddModal(false)}
                className="text-gray-400 hover:text-gray-600 text-3xl font-light transition-colors"
              >
                &times;
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="md:col-span-2">
                <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                  اختيار الأصل
                </label>
                <select
                  value={newRecord.assetId}
                  onChange={(e) =>
                    setNewRecord({ ...newRecord, assetId: e.target.value })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 rounded-2xl px-5 py-3 text-sm font-bold dark:text-white focus:border-indigo-500 outline-none transition-all"
                >
                  <option value="">-- اختر الأصل من القائمة --</option>
                  {assets.map((a) => (
                    <option key={a.id} value={a.id}>
                      {a.name} ({a.code})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                  نوع العملية
                </label>
                <select
                  value={newRecord.type}
                  onChange={(e) =>
                    setNewRecord({ ...newRecord, type: e.target.value })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 rounded-2xl px-5 py-3 text-sm font-bold dark:text-white focus:border-indigo-500 outline-none transition-all"
                >
                  <option>صيانة دورية</option>
                  <option>إصلاح عطل</option>
                  <option>تحديث (Upgrade)</option>
                  <option>فحص وقائي</option>
                </select>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                  الحالة
                </label>
                <select
                  value={newRecord.status}
                  onChange={(e) =>
                    setNewRecord({
                      ...newRecord,
                      status: e.target.value as any,
                    })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 rounded-2xl px-5 py-3 text-sm font-bold dark:text-white focus:border-indigo-500 outline-none transition-all"
                >
                  <option value="COMPLETED">تمت بنجاح (سجل تاريخي)</option>
                  <option value="SCHEDULED">مجدولة (تنبيه مستقبلي)</option>
                </select>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                  التكلفة المتوقعة/الفعلية
                </label>
                <input
                  type="number"
                  value={newRecord.cost}
                  onChange={(e) =>
                    setNewRecord({ ...newRecord, cost: e.target.value })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 rounded-2xl px-5 py-3 text-sm font-bold dark:text-white focus:border-indigo-500 outline-none transition-all"
                  placeholder="0.00"
                />
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                  التاريخ
                </label>
                <input
                  type="date"
                  value={newRecord.startDate}
                  onChange={(e) =>
                    setNewRecord({ ...newRecord, startDate: e.target.value })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 rounded-2xl px-5 py-3 text-sm font-bold dark:text-white focus:border-indigo-500 outline-none transition-all"
                />
              </div>

              <div className="md:col-span-2">
                <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                  وصف العملية / ملاحظات
                </label>
                <textarea
                  value={newRecord.description}
                  onChange={(e) =>
                    setNewRecord({ ...newRecord, description: e.target.value })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 rounded-2xl px-5 py-4 text-sm font-bold dark:text-white h-24 outline-none focus:border-indigo-500 transition-all"
                  placeholder="اكتب تفاصيل ما تم أو ما سيتم القيام به..."
                ></textarea>
              </div>
            </div>

            <div className="flex gap-4 mt-10">
              <button
                onClick={handleAddMaintenance}
                className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl shadow-indigo-100 dark:shadow-none transform hover:-translate-y-1 transition-all"
              >
                حفظ السجل / الجدولة
              </button>
              <button
                onClick={() => setShowAddModal(false)}
                className="flex-1 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-300 py-4 rounded-2xl font-black text-sm hover:bg-gray-200 transition-all"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AssetMaintenanceSection;

import React, { useState, useEffect } from "react";
import {
  PlusIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  CheckBadgeIcon,
  TagIcon,
  ChatBubbleLeftEllipsisIcon,
  UserIcon,
  ComputerDesktopIcon,
  ArrowRightCircleIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";
import { format } from "date-fns";
import { ar } from "date-fns/locale";
import { companyAwareApi } from "../../../../services/companyAwareApi";
import { toast } from "react-hot-toast";

interface AssetRequest {
  id: string;
  requestedBy: string;
  assetType: string;
  category?: string;
  reason: string;
  priority: string;
  status: "PENDING" | "APPROVED" | "REJECTED" | "FULFILLED" | "CANCELLED";
  createdAt: string;
  requester?: {
    firstName: string;
    lastName: string;
    employeeNumber: string;
  };
  requesterName?: string;
  rejectionReason?: string;
  assetId?: string;
}

const AssetRequestsSection: React.FC = () => {
  const [view, setView] = useState<"employee" | "hr">("employee");
  const [requests, setRequests] = useState<AssetRequest[]>([]);
  const [showRequestModal, setShowRequestModal] = useState(false);
  const [loading, setLoading] = useState(false);

  const [newRequest, setNewRequest] = useState({
    assetType: "حاسوب محمول (Laptop)",
    reason: "",
    priority: "NORMAL",
  });

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const endpoint =
        view === "hr" ? "/hr/assets/requests/all" : "/hr/assets/requests/my";
      const response = await companyAwareApi.get(endpoint);
      if (response.data.success) {
        const enriched: AssetRequest[] = (response.data.data || []).map(
          (req: AssetRequest) => ({
            ...req,
            requesterName:
              req.requester?.firstName || req.requester?.lastName
                ? `${req.requester?.firstName || ""} ${
                  req.requester?.lastName || ""
                }`.trim()
                : req.requester?.employeeNumber || req.requestedBy,
          }),
        );
        setRequests(enriched);
      }
    } catch (error) {
      console.error("Error fetching requests:", error);
      // Fallback to mock if API fails during testing
      if (requests.length === 0) {
        setRequests([
          {
            id: "REQ-MOCK",
            requestedBy: "me",
            assetType: "Laptop (Mock)",
            reason: "API Connection Error - Showing Mock",
            priority: "NORMAL",
            status: "PENDING",
            createdAt: new Date().toISOString(),
          },
        ]);
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [view]);

  const handleCreateRequest = async () => {
    if (!newRequest.reason) {
      toast.error("يرجى ذكر سبب الطلب");
      return;
    }
    try {
      console.log("🚀 Calling POST /hr/assets/requests");
      const response = await companyAwareApi.post(
        "/hr/assets/requests",
        newRequest,
      );
      if (response.data.success) {
        toast.success("تم إرسال الطلب بنجاح");
        setShowRequestModal(false);
        fetchRequests();
      }
    } catch (error) {
      toast.error("فشل في إرسال الطلب");
    }
  };

  const handleUpdateStatus = async (
    requestId: string,
    status: string,
    rejectionReason?: string,
  ) => {
    try {
      const response = await companyAwareApi.put(
        `/hr/assets/requests/${requestId}/status`,
        {
          status,
          rejectionReason,
        },
      );
      if (response.data.success) {
        toast.success(status === "APPROVED" ? "تمت الموافقة" : "تم الرفض");
        fetchRequests();
      }
    } catch (error) {
      toast.error("فشل في تحديث حالة الطلب");
    }
  };

  const getStatusColor = (status: AssetRequest["status"]) => {
    switch (status) {
      case "PENDING":
        return "bg-amber-100 text-amber-700 border-amber-200";
      case "APPROVED":
        return "bg-blue-100 text-blue-700 border-blue-200";
      case "REJECTED":
        return "bg-red-100 text-red-700 border-red-200";
      case "FULFILLED":
        return "bg-green-100 text-green-700 border-green-200";
      default:
        return "bg-gray-100 text-gray-700 border-gray-200";
    }
  };

  const getStatusText = (status: AssetRequest["status"]) => {
    switch (status) {
      case "PENDING":
        return "قيد الانتظار";
      case "APPROVED":
        return "تمت الموافقة";
      case "REJECTED":
        return "مرفوض";
      case "FULFILLED":
        return "تم التسليم";
      case "CANCELLED":
        return "ملغى";
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header & Toggle */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <ArrowRightCircleIcon className="h-7 w-7 text-indigo-600" />
            نظام طلبات العهدة والأصول
          </h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            تقديم طلبات عهدة جديدة ومتابعة حالات الموافقة والتخصيص (يدعم إشعارات
            WhatsApp)
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={fetchRequests}
            className="p-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl hover:bg-gray-50 transition-all"
          >
            <ArrowPathIcon
              className={`h-5 w-5 text-gray-500 ${loading ? "animate-spin" : ""}`}
            />
          </button>
          <div className="flex bg-white dark:bg-gray-800 p-1 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
            <button
              onClick={() => setView("employee")}
              className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                view === "employee"
                  ? "bg-indigo-600 text-white shadow-md"
                  : "text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
              }`}
            >
              طلباتي
            </button>
            <button
              onClick={() => setView("hr")}
              className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                view === "hr"
                  ? "bg-indigo-600 text-white shadow-md"
                  : "text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
              }`}
            >
              إدارة HR
            </button>
          </div>
        </div>
      </div>

      {view === "employee" ? (
        <div className="space-y-6">
          {/* Employee Stats */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm">
              <div className="flex items-center gap-3 text-amber-600 mb-2">
                <ClockIcon className="h-5 w-5" />
                <span className="text-sm font-bold">طلبات معلقة</span>
              </div>
              <p className="text-2xl font-black dark:text-white">
                {requests.filter((r) => r.status === "PENDING").length}
              </p>
            </div>
            <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm">
              <div className="flex items-center gap-3 text-blue-600 mb-2">
                <CheckBadgeIcon className="h-5 w-5" />
                <span className="text-sm font-bold">تمت الموافقة</span>
              </div>
              <p className="text-2xl font-black dark:text-white">
                {requests.filter((r) => r.status === "APPROVED").length}
              </p>
            </div>
            <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm">
              <button
                onClick={() => setShowRequestModal(true)}
                className="w-full h-full flex flex-col items-center justify-center gap-2 text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-xl transition-all border-2 border-dashed border-indigo-200 dark:border-indigo-800 py-2"
              >
                <PlusIcon className="h-6 w-6" />
                <span className="font-bold">طلب جديد</span>
              </button>
            </div>
          </div>

          {/* My Requests Table */}
          <div className="bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-xl overflow-x-auto">
            <table className="w-full text-right min-w-[600px]">
              <thead>
                <tr className="bg-gray-50 dark:bg-gray-900/50 text-gray-400 text-xs font-bold uppercase tracking-wider text-right">
                  <th className="px-6 py-4">التاريخ</th>
                  <th className="px-6 py-4">النوع</th>
                  <th className="px-6 py-4">الحالة</th>
                  <th className="px-6 py-4">السبب</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50 dark:divide-gray-700">
                {requests.length === 0 ? (
                  <tr>
                    <td
                      colSpan={4}
                      className="px-6 py-12 text-center text-gray-400 italic"
                    >
                      لا توجد طلبات حالياً
                    </td>
                  </tr>
                ) : (
                  requests.map((req) => (
                    <tr
                      key={req.id}
                      className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                    >
                      <td className="px-6 py-4">
                        <span className="text-sm font-medium dark:text-gray-300">
                          {format(new Date(req.createdAt), "yyyy/MM/dd")}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <div className="p-1.5 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg">
                            <ComputerDesktopIcon className="h-4 w-4 text-indigo-600" />
                          </div>
                          <span className="font-bold text-gray-900 dark:text-white">
                            {req.assetType}
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span
                          className={`px-3 py-1 rounded-full text-[10px] font-bold border ${getStatusColor(req.status)}`}
                        >
                          {getStatusText(req.status)}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <p className="text-xs text-gray-500 dark:text-gray-400 truncate max-w-xs">
                          {req.reason}
                        </p>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-gray-900 dark:text-white">
              إدارة طلبات الموظفين
            </h3>
            <span className="px-3 py-1 bg-amber-100 text-amber-700 rounded-full text-xs font-bold">
              {requests.filter((r) => r.status === "PENDING").length} طلب
              بانتظار القرار
            </span>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {requests
              .filter((r) => r.status === "PENDING")
              .map((req) => (
                <div
                  key={req.id}
                  className="bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700 p-6 shadow-sm"
                >
                  <div className="flex justify-between items-start mb-6">
                    <div className="flex gap-3">
                      <div className="w-12 h-12 rounded-2xl bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center text-indigo-600 border border-indigo-100 dark:border-indigo-800">
                        <UserIcon className="h-6 w-6" />
                      </div>
                      <div>
                        <h4 className="font-bold text-gray-900 dark:text-white">
                          {req.requesterName ||
                            `${req.requester?.firstName || ""} ${req.requester?.lastName || ""}`.trim() ||
                            "غير معروف"}
                        </h4>
                        <p className="text-xs text-gray-400 font-mono">
                          {req.requester?.employeeNumber}
                        </p>
                      </div>
                    </div>
                    <div className="text-left">
                      <span className="text-xs font-bold dark:text-gray-300">
                        {format(new Date(req.createdAt), "PPP", { locale: ar })}
                      </span>
                    </div>
                  </div>

                  <div className="space-y-4 mb-6">
                    <div className="flex items-center gap-2">
                      <TagIcon className="h-4 w-4 text-gray-400" />
                      <span className="text-sm font-bold dark:text-white">
                        المطلوب: {req.assetType}
                      </span>
                    </div>
                    <div className="bg-gray-50 dark:bg-gray-900/50 p-4 rounded-2xl">
                      <p className="text-xs text-gray-600 dark:text-gray-400 italic">
                        " {req.reason} "
                      </p>
                    </div>
                  </div>

                  <div className="flex gap-3">
                    <button
                      onClick={() => handleUpdateStatus(req.id, "APPROVED")}
                      className="flex-1 bg-indigo-600 text-white py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all flex items-center justify-center gap-2"
                    >
                      <CheckCircleIcon className="h-5 w-5" />
                      موافقة وارسال WhatsApp
                    </button>
                    <button
                      onClick={() => {
                        const res = prompt("سبب الرفض:");
                        if (res) handleUpdateStatus(req.id, "REJECTED", res);
                      }}
                      className="flex-1 bg-white dark:bg-gray-700 border border-red-200 text-red-600 py-3 rounded-xl text-sm font-bold hover:bg-red-50 transition-all flex items-center justify-center gap-2"
                    >
                      <XCircleIcon className="h-5 w-5" />
                      رفض
                    </button>
                  </div>
                </div>
              ))}

            {requests
              .filter((r) => r.status === "APPROVED")
              .map((req) => (
                <div
                  key={req.id}
                  className="bg-indigo-50/50 dark:bg-indigo-900/10 rounded-3xl border border-indigo-100 dark:border-indigo-800/30 p-6"
                >
                  <div className="flex justify-between items-center mb-4">
                    <span className="px-3 py-1 bg-blue-100 text-blue-700 text-[10px] font-bold rounded-full">
                      معتمد - بانتظار التسليم
                    </span>
                    <span className="text-[10px] text-gray-400">{req.id}</span>
                  </div>
                  <h4 className="font-bold text-gray-900 dark:text-white mb-2">
                    {req.requesterName ||
                      `${req.requester?.firstName || ""} ${req.requester?.lastName || ""}`.trim() ||
                      "غير معروف"}
                  </h4>
                  <p className="text-sm text-gray-600 dark:text-gray-400 mb-6 font-medium">
                    تمت الموافقة على {req.assetType}. يرجى تخصيص أصل فعلي لإتمام
                    العملية.
                  </p>
                  <button className="w-full bg-white dark:bg-indigo-800 text-indigo-700 dark:text-indigo-200 border border-indigo-200 dark:border-indigo-700 py-3 rounded-xl text-sm font-black hover:bg-indigo-600 hover:text-white transition-all">
                    تخصيص وتسليم الأصل
                  </button>
                </div>
              ))}
          </div>
        </div>
      )}

      {/* Request Modal */}
      {showRequestModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white dark:bg-gray-800 w-full max-w-md rounded-3xl p-8 shadow-2xl animate-scale-in">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                تقديم طلب عهدة
              </h3>
              <button
                onClick={() => setShowRequestModal(false)}
                className="text-gray-400 hover:text-gray-600"
              >
                &times;
              </button>
            </div>
            <div className="space-y-5">
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-2 uppercase">
                  نوع الأصل المطلوب
                </label>
                <select
                  value={newRequest.assetType}
                  onChange={(e) =>
                    setNewRequest({ ...newRequest, assetType: e.target.value })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border border-gray-100 dark:border-gray-600 rounded-xl px-4 py-3 text-sm dark:text-white"
                >
                  <option>حاسوب محمول (Laptop)</option>
                  <option>هاتف ذكي (Mobile)</option>
                  <option>شاشة (Monitor)</option>
                  <option>كرسي مكتبي</option>
                  <option>أدوات قرطاسية</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-2 uppercase">
                  الأولوية
                </label>
                <div className="flex gap-2">
                  {["NORMAL", "HIGH", "URGENT"].map((p) => (
                    <button
                      key={p}
                      onClick={() =>
                        setNewRequest({ ...newRequest, priority: p })
                      }
                      className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${
                        newRequest.priority === p
                          ? "bg-indigo-600 border-indigo-600 text-white"
                          : "bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-700 text-gray-400"
                      }`}
                    >
                      {p === "NORMAL"
                        ? "عادية"
                        : p === "HIGH"
                          ? "عالية"
                          : "عاجل"}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-2 uppercase">
                  سبب الطلب
                </label>
                <textarea
                  value={newRequest.reason}
                  onChange={(e) =>
                    setNewRequest({ ...newRequest, reason: e.target.value })
                  }
                  className="w-full bg-gray-50 dark:bg-gray-700 border border-gray-100 dark:border-gray-600 rounded-xl px-4 py-3 text-sm dark:text-white h-32"
                  placeholder="لماذا تحتاج هذه العهدة؟"
                ></textarea>
              </div>
            </div>
            <div className="flex gap-3 mt-8">
              <button
                onClick={handleCreateRequest}
                className="flex-1 bg-indigo-600 text-white py-3.5 rounded-xl font-bold hover:bg-indigo-700 shadow-xl shadow-indigo-100 dark:shadow-none transition-all"
              >
                إرسال الطلب
              </button>
              <button
                onClick={() => setShowRequestModal(false)}
                className="flex-1 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 py-3.5 rounded-xl font-bold hover:bg-gray-200 transition-all"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AssetRequestsSection;

import React, { useState, useEffect } from "react";
import {
  DocumentIcon,
  PhotoIcon,
  DocumentTextIcon,
  ShieldCheckIcon,
  BookOpenIcon,
  TrashIcon,
  ArrowDownTrayIcon,
  PlusIcon,
  XMarkIcon,
  EyeIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  ComputerDesktopIcon,
} from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../../../services/companyAwareApi";
import axios from "axios";
import { getApiUrl } from "../../../../config/environment";
import { tokenManager } from "../../../../utils/tokenManager";
import Lightbox from "react-image-lightbox";
import "react-image-lightbox/style.css";

interface Asset {
  id: string;
  name: string;
  code: string;
}

interface AssetDocument {
  id: string;
  assetId: string;
  documentType: string;
  fileName: string;
  fileUrl: string;
  fileSize?: number;
  mimeType?: string;
  uploadedBy: string;
  uploadedAt: string;
  description?: string;
  asset?: Asset;
}

interface DocumentType {
  value: string;
  label: string;
  labelEn: string;
  icon: string;
}

const DocumentsSection: React.FC = () => {
  const PAGE_SIZE = 12;
  const [documents, setDocuments] = useState<AssetDocument[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState("");
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [documentTypes] = useState<DocumentType[]>([
    {
      value: "image",
      label: "صور الأصل",
      labelEn: "Asset Images",
      icon: "photo",
    },
    {
      value: "invoice",
      label: "فاتورة الشراء",
      labelEn: "Purchase Invoice",
      icon: "document",
    },
    {
      value: "warranty",
      label: "شهادة الضمان",
      labelEn: "Warranty Certificate",
      icon: "shield",
    },
    {
      value: "manual",
      label: "دليل الاستخدام",
      labelEn: "User Manual",
      icon: "book",
    },
    {
      value: "other",
      label: "معاينة وتحميل المرفقات",
      labelEn: "Preview & Download",
      icon: "document",
    },
  ]);
  const [activeTab, setActiveTab] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [selectedAsset, setSelectedAsset] = useState("all");
  const [lightbox, setLightbox] = useState<{ open: boolean; src: string }>({
    open: false,
    src: "",
  });
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);

  // Upload form state
  const [uploadForm, setUploadForm] = useState({
    assetId: "",
    documentType: "image",
    fileName: "",
    fileUrl: "",
    description: "",
  });
  const [uploading, setUploading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [assetsLoading, setAssetsLoading] = useState(false);

  useEffect(() => {
    fetchAssets();
  }, []);

  useEffect(() => {
    setPage(1);
    fetchAllDocuments({ page: 1, append: false });
  }, [activeTab, selectedAsset, debouncedSearch]);

  // Debounce search
  useEffect(() => {
    const id = setTimeout(() => setDebouncedSearch(searchQuery), 400);
    return () => clearTimeout(id);
  }, [searchQuery]);

  // Reload assets when modal opens
  useEffect(() => {
    if (showUploadModal) {
      fetchAssets();
    }
  }, [showUploadModal]);

  const normalizeDoc = (doc: any): AssetDocument => ({
    ...doc,
    documentType: (doc as any).documentType || (doc as any).type,
    uploadedAt: (doc as any).uploadedAt || (doc as any).createdAt,
    asset: (doc as any).asset || (doc as any).assets,
  });

  const fetchAllDocuments = async ({
    page: requestedPage = 1,
    append = false,
  }: {
    page?: number;
    append?: boolean;
  } = {}) => {
    try {
      if (append) {
        setLoadingMore(true);
      } else {
        setLoading(true);
      }
      setError("");
      const response = await companyAwareApi.get("/hr/assets/documents/all", {
        params: {
          page: requestedPage,
          limit: PAGE_SIZE,
          type: activeTab !== "all" ? activeTab : undefined,
          assetId: selectedAsset !== "all" ? selectedAsset : undefined,
          search: debouncedSearch || undefined,
        },
      });
      if (response.data.success) {
        const docs = (response.data.data.documents || []).map((d: any) =>
          normalizeDoc(d),
        );
        setDocuments((prev) => (append ? [...prev, ...docs] : docs));
        const pagination = response.data.data.pagination || {};
        const totalPages =
          pagination.totalPages ||
          (docs.length < PAGE_SIZE ? requestedPage : requestedPage + 1);
        setPage(requestedPage);
        setHasMore(requestedPage < totalPages && docs.length > 0);
      }
    } catch (err: any) {
      // If endpoint doesn't exist, try fetching from each asset
      console.log("Fetching documents from all assets...");
      try {
        const assetsResponse = await companyAwareApi.get("/hr/assets");
        if (assetsResponse.data.success) {
          const allDocs: AssetDocument[] = [];
          const assetsData = assetsResponse.data.data || [];
          for (const asset of assetsData) {
            try {
              const docsResponse = await companyAwareApi.get(
                `/hr/assets/${asset.id}/documents`,
              );
              if (docsResponse.data.success) {
                const docs = docsResponse.data.data.documents || [];
                docs.forEach((doc: AssetDocument) => {
                  allDocs.push({ ...normalizeDoc(doc), asset });
                });
              }
            } catch (e) {
              // Skip if no documents
            }
          }
          setDocuments(allDocs);
          setHasMore(false);
          setPage(requestedPage);
        }
      } catch (e) {
        setError("فشل في تحميل المستندات");
      }
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  };

  const fetchAssets = async () => {
    try {
      setAssetsLoading(true);
      console.log("🔄 Fetching assets...");
      const response = await companyAwareApi.get("/hr/assets", {
        params: { limit: 200 },
      });
      console.log("📦 Assets API response:", response.data);

      if (response.data.success) {
        // API returns data directly as array (same as AssetList.tsx)
        const assetsData = response.data.data || [];
        console.log("✅ Assets loaded:", assetsData.length, assetsData);
        setAssets(assetsData);
      } else {
        console.error("❌ Assets API returned success: false", response.data);
      }
    } catch (err: any) {
      console.error("❌ Failed to fetch assets:", err);
      console.error("❌ Error details:", err.response?.data || err.message);
    } finally {
      setAssetsLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const allowedTypes = [
        "image/",
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "application/vnd.ms-excel",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      ];
      const maxSize = 20 * 1024 * 1024; // 20MB
      const isAllowed =
        allowedTypes.some((t) => file.type.startsWith(t.replace("/*", ""))) ||
        file.type === "";
      if (!isAllowed) {
        alert("نوع الملف غير مدعوم. يرجى رفع صور أو PDF أو Word/Excel.");
        return;
      }
      if (file.size > maxSize) {
        alert("حجم الملف يتجاوز 20 ميجابايت.");
        return;
      }
      setSelectedFile(file);
      setUploadForm((prev) => ({ ...prev, fileName: file.name }));
    }
  };

  const handleUpload = async () => {
    if (!uploadForm.assetId) {
      alert("يرجى اختيار الأصل");
      return;
    }
    if (!selectedFile && !uploadForm.fileUrl) {
      alert("يرجى اختيار ملف أو إدخال رابط الملف");
      return;
    }
    if (!uploadForm.fileName) {
      alert("يرجى إدخال اسم الملف");
      return;
    }

    setUploading(true);
    try {
      let fileUrl = uploadForm.fileUrl;
      const mimeType = selectedFile?.type;
      const fileSize = selectedFile?.size;

      // If file is selected, upload it first
      if (selectedFile) {
        const formData = new FormData();
        formData.append("file", selectedFile);
        // Get auth token
        const token = tokenManager.getAccessToken();
        const user = JSON.parse(localStorage.getItem("user") || "{}");

        const uploadResponse = await axios.post(
          `${getApiUrl()}/upload`,
          formData,
          {
            headers: {
              "Content-Type": "multipart/form-data",
              Authorization: `Bearer ${token}`,
            },
            params: {
              companyId: user.companyId,
            },
          },
        );

        if (uploadResponse.data?.success) {
          fileUrl =
            uploadResponse.data.filePath ||
            uploadResponse.data.url ||
            uploadResponse.data.data?.url ||
            uploadResponse.data.fileUrl;
        } else {
          throw new Error("فشل في رفع الملف");
        }
      }

      if (!fileUrl) {
        alert("يرجى اختيار ملف أو إدخال رابط الملف");
        setUploading(false);
        return;
      }

      console.log("📤 Sending document data:", {
        assetId: uploadForm.assetId,
        documentType: uploadForm.documentType,
        fileName: uploadForm.fileName,
        fileUrl: fileUrl,
        mimeType,
        fileSize,
      });

      const response = await companyAwareApi.post(
        `/hr/assets/${uploadForm.assetId}/documents`,
        {
          documentType: uploadForm.documentType,
          fileName: uploadForm.fileName,
          fileUrl: fileUrl,
          description: uploadForm.description,
          mimeType,
          fileSize,
        },
      );

      if (response.data.success) {
        const newDoc = normalizeDoc(response.data.data);
        const asset = assets.find((a) => a.id === uploadForm.assetId);
        setDocuments((prev) => [{ ...newDoc, asset }, ...prev]);
        setShowUploadModal(false);
        resetUploadForm();
        alert("تم رفع المستند بنجاح");
        // Refresh first page to keep pagination + filters in sync
        fetchAllDocuments({ page: 1, append: false });
      }
    } catch (err: any) {
      console.error("Document upload error:", err);
      alert(err.response?.data?.message || err.message || "فشل في رفع المستند");
    } finally {
      setUploading(false);
    }
  };

  const resetUploadForm = () => {
    setUploadForm({
      assetId: "",
      documentType: "image",
      fileName: "",
      fileUrl: "",
      description: "",
    });
    setSelectedFile(null);
  };

  const handleDelete = async (docId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا المستند؟")) return;

    try {
      await companyAwareApi.delete(`/hr/assets/documents/${docId}`);
      setDocuments(documents.filter((d) => d.id !== docId));
    } catch (err: any) {
      alert(err.response?.data?.message || "فشل في حذف المستند");
    }
  };

  const getDocumentIcon = (type: string) => {
    switch (type) {
      case "image":
        return <PhotoIcon className="h-10 w-10 text-blue-500" />;
      case "invoice":
        return <DocumentTextIcon className="h-10 w-10 text-green-500" />;
      case "warranty":
        return <ShieldCheckIcon className="h-10 w-10 text-purple-500" />;
      case "manual":
        return <BookOpenIcon className="h-10 w-10 text-orange-500" />;
      default:
        return <DocumentIcon className="h-10 w-10 text-gray-500" />;
    }
  };

  const getDocumentTypeLabel = (type: string) => {
    const docType = documentTypes.find((t) => t.value === type);
    return docType?.label || type;
  };

  const formatFileSize = (bytes?: number) => {
    if (!bytes) return "";
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const formatDate = (dateString: string) => {
    if (!dateString) return "-";
    const d = new Date(dateString);
    if (isNaN(d.getTime())) return "-";
    return d.toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const buildFileUrl = (url: string) => {
    if (!url) return "";
    if (url.startsWith("http")) return encodeURI(url);
    const base = getApiUrl().replace("/api/v1", "");
    const cleanPath = url.replace(/^\/+/, "");
    return encodeURI(`${base}/${cleanPath}`);
  };

  // Filter documents
  let filteredDocuments = documents;

  if (activeTab !== "all") {
    filteredDocuments = filteredDocuments.filter(
      (d) => d.documentType === activeTab,
    );
  }

  if (selectedAsset !== "all") {
    filteredDocuments = filteredDocuments.filter(
      (d) => d.assetId === selectedAsset,
    );
  }

  if (debouncedSearch) {
    const query = debouncedSearch.toLowerCase();
    filteredDocuments = filteredDocuments.filter(
      (d) =>
        d.fileName.toLowerCase().includes(query) ||
        d.description?.toLowerCase().includes(query) ||
        d.asset?.name.toLowerCase().includes(query),
    );
  }

  const tabs = [
    { id: "all", label: "الكل", count: documents.length, color: "gray" },
    {
      id: "image",
      label: "صور الأصول",
      count: documents.filter((d) => d.documentType === "image").length,
      color: "blue",
    },
    {
      id: "invoice",
      label: "فواتير الشراء",
      count: documents.filter((d) => d.documentType === "invoice").length,
      color: "green",
    },
    {
      id: "warranty",
      label: "شهادات الضمان",
      count: documents.filter((d) => d.documentType === "warranty").length,
      color: "purple",
    },
    {
      id: "manual",
      label: "أدلة الاستخدام",
      count: documents.filter((d) => d.documentType === "manual").length,
      color: "orange",
    },
    {
      id: "other",
      label: "أخرى",
      count: documents.filter((d) => d.documentType === "other").length,
      color: "gray",
    },
  ];

  const colorMap: Record<string, { bg: string; text: string; light: string }> =
  {
    gray: {
      bg: "bg-gray-600",
      text: "text-gray-600",
      light: "bg-gray-100 dark:bg-gray-700",
    },
    blue: {
      bg: "bg-blue-600",
      text: "text-blue-600",
      light: "bg-blue-100 dark:bg-blue-900/30",
    },
    green: {
      bg: "bg-green-600",
      text: "text-green-600",
      light: "bg-green-100 dark:bg-green-900/30",
    },
    purple: {
      bg: "bg-purple-600",
      text: "text-purple-600",
      light: "bg-purple-100 dark:bg-purple-900/30",
    },
    orange: {
      bg: "bg-orange-600",
      text: "text-orange-600",
      light: "bg-orange-100 dark:bg-orange-900/30",
    },
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <DocumentIcon className="h-7 w-7 text-indigo-600" />
            الوثائق والمرفقات
          </h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            إدارة جميع مستندات الأصول في مكان واحد
          </p>
        </div>
        <button
          onClick={() => setShowUploadModal(true)}
          className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-lg"
        >
          <PlusIcon className="h-5 w-5" />
          رفع مستند جديد
        </button>
      </div>

      {loading && (
        <div className="flex justify-center items-center py-12">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
        </div>
      )}

      {error && (
        <div className="p-4 bg-red-100 text-red-700 rounded-lg">
          {error || "فشل في تحميل المستندات"}
        </div>
      )}

      {/* Quick Upload Cards */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {documentTypes.map((type) => {
          const colorKey =
            type.value === "image"
              ? "blue"
              : type.value === "invoice"
                ? "green"
                : type.value === "warranty"
                  ? "purple"
                  : type.value === "manual"
                    ? "orange"
                    : "gray";
          const colors = colorMap[colorKey] ?? {
            bg: "bg-gray-600",
            text: "text-gray-600",
            light: "bg-gray-100 dark:bg-gray-700",
          };
          return (
            <button
              key={type.value}
              onClick={() => {
                setUploadForm((prev) => ({
                  ...prev,
                  documentType: type.value,
                }));
                setShowUploadModal(true);
              }}
                className={`${colors.light} p-4 rounded-xl text-center hover:shadow-md transition-all border-2 border-transparent`}
              >
                <div className="flex justify-center mb-2">
                  {type.value === "image" && (
                    <PhotoIcon className="h-8 w-8 text-blue-600" />
                )}
                {type.value === "invoice" && (
                  <DocumentTextIcon className="h-8 w-8 text-green-600" />
                )}
                {type.value === "warranty" && (
                  <ShieldCheckIcon className="h-8 w-8 text-purple-600" />
                )}
                {type.value === "manual" && (
                  <BookOpenIcon className="h-8 w-8 text-orange-600" />
                )}
                {type.value === "other" && (
                  <DocumentIcon className="h-8 w-8 text-gray-600" />
                )}
              </div>
              <p className={`font-medium ${colors.text} text-sm`}>
                {type.label}
              </p>
            </button>
          );
        })}
      </div>

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-200 dark:border-gray-700">
        <div className="flex flex-col md:flex-row gap-4">
          {/* Search */}
          <div className="flex-1 relative">
            <MagnifyingGlassIcon className="h-5 w-5 absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              placeholder="بحث في المستندات..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pr-10 pl-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          {/* Asset Filter */}
          <div className="flex items-center gap-2">
            <FunnelIcon className="h-5 w-5 text-gray-400" />
            <select
              value={selectedAsset}
              onChange={(e) => setSelectedAsset(e.target.value)}
              className="border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
            >
              <option value="all">جميع الأصول</option>
              {assets
                .filter((asset) => asset && asset.id && asset.name)
                .map((asset) => (
                  <option key={asset.id} value={asset.id}>
                    {asset.name} {asset.code ? `(${asset.code})` : ""}
                  </option>
                ))}
            </select>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 mt-4 overflow-x-auto pb-2">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${activeTab === tab.id
                ? "bg-indigo-600 text-white"
                : "bg-gray-100 text-gray-600 hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-300"
                }`}
            >
              {tab.label}
              {tab.count > 0 && (
                <span
                  className={`mr-2 px-2 py-0.5 rounded-full text-xs ${activeTab === tab.id
                    ? "bg-white/20"
                    : "bg-white dark:bg-gray-600"
                    }`}
                >
                  {tab.count}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Documents Grid */}
      {filteredDocuments.length === 0 && !loading ? (
        <div className="text-center py-16 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700">
          <DocumentIcon className="h-16 w-16 mx-auto mb-4 text-gray-300 dark:text-gray-600" />
          <p className="text-gray-500 dark:text-gray-400 text-lg">
            {searchQuery || activeTab !== "all" || selectedAsset !== "all"
              ? "لا توجد نتائج مطابقة"
              : "لا توجد مستندات"}
          </p>
          <p className="text-gray-400 dark:text-gray-500 text-sm mt-1">
            ابدأ برفع مستندات لأصولك
          </p>
          <button
            onClick={() => setShowUploadModal(true)}
            className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
          >
            رفع أول مستند
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {filteredDocuments.map((doc) => (
            <div
              key={doc.id}
              className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-4 hover:shadow-lg transition-all group"
            >
              <div className="flex items-start gap-3">
                <div className="p-2 bg-gray-50 dark:bg-gray-700 rounded-lg">
                  {getDocumentIcon(doc.documentType)}
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="font-medium text-gray-900 dark:text-white truncate">
                    {doc.fileName}
                  </h4>
                  <p className="text-sm text-indigo-600 dark:text-indigo-400">
                    {getDocumentTypeLabel(doc.documentType)}
                  </p>
                  {doc.asset && (
                    <div className="flex items-center gap-1 mt-1 text-xs text-gray-500 dark:text-gray-400">
                      <ComputerDesktopIcon className="h-3.5 w-3.5" />
                      {doc.asset.name}
                    </div>
                  )}
                </div>
              </div>

              {doc.description && (
                <p className="mt-3 text-sm text-gray-600 dark:text-gray-300 line-clamp-2">
                  {doc.description}
                </p>
              )}

              <div className="flex items-center justify-between mt-3 pt-3 border-t border-gray-100 dark:border-gray-700">
                <div className="text-xs text-gray-400">
                  {formatDate(doc.uploadedAt)}
                  {doc.fileSize && ` • ${formatFileSize(doc.fileSize)}`}
                </div>
              </div>

              <div className="flex gap-2 mt-3">
                <a
                  href={
                    doc.mimeType?.startsWith("image/")
                      ? undefined
                      : buildFileUrl(doc.fileUrl)
                  }
                  target={doc.mimeType === "application/pdf" ? "_blank" : undefined}
                  rel="noopener noreferrer"
                  onClick={(e) => {
                    if (doc.mimeType?.startsWith("image/")) {
                      e.preventDefault();
                      setLightbox({ open: true, src: buildFileUrl(doc.fileUrl) });
                    }
                  }}
                  className="flex-1 flex items-center justify-center gap-1 px-3 py-2 text-sm bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                >
                  <EyeIcon className="h-4 w-4" />
                  {doc.mimeType?.startsWith("image/")
                    ? "عرض الصورة"
                    : doc.mimeType === "application/pdf"
                      ? "فتح PDF"
                      : "معاينة"}
                </a>
                <a
                  href={buildFileUrl(doc.fileUrl)}
                  download={doc.fileName}
                  className="flex items-center justify-center gap-1 px-3 py-2 text-sm bg-indigo-100 dark:bg-indigo-900 text-indigo-700 dark:text-indigo-200 rounded-lg hover:bg-indigo-200 dark:hover:bg-indigo-800 transition-colors"
                >
                  <ArrowDownTrayIcon className="h-4 w-4" />
                </a>
                <button
                  onClick={() => handleDelete(doc.id)}
                  className="flex items-center justify-center gap-1 px-3 py-2 text-sm bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-200 rounded-lg hover:bg-red-200 dark:hover:bg-red-800 transition-colors"
                >
                  <TrashIcon className="h-4 w-4" />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {hasMore && filteredDocuments.length > 0 && (
        <div className="flex justify-center mt-4">
          <button
            onClick={() => fetchAllDocuments({ page: page + 1, append: true })}
            disabled={loadingMore}
            className="px-4 py-2 text-sm rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 disabled:opacity-50"
          >
            {loadingMore ? "جاري التحميل..." : "تحميل المزيد"}
          </button>
        </div>
      )}

      {/* Upload Modal */}
      {showUploadModal && (
        <div className="fixed inset-0 z-50 overflow-y-auto">
          <div className="flex items-center justify-center min-h-screen px-4">
            <div
              className="fixed inset-0 bg-black bg-opacity-50"
              onClick={() => setShowUploadModal(false)}
            />
            <div className="relative bg-white dark:bg-gray-800 rounded-xl p-6 max-w-lg w-full shadow-2xl">
              <div className="flex justify-between items-center mb-6">
                <h4 className="text-xl font-bold text-gray-900 dark:text-white">
                  رفع مستند جديد
                </h4>
                <button
                  onClick={() => {
                    setShowUploadModal(false);
                    resetUploadForm();
                  }}
                  className="text-gray-400 hover:text-gray-500"
                >
                  <XMarkIcon className="h-6 w-6" />
                </button>
              </div>

              <div className="space-y-4">
                {/* Asset Selection */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    اختر الأصل *
                  </label>
                  {assetsLoading ? (
                    <div className="p-3 bg-gray-50 dark:bg-gray-700 rounded-lg text-gray-500 dark:text-gray-400 text-sm flex items-center gap-2">
                      <div className="animate-spin h-4 w-4 border-2 border-indigo-500 border-t-transparent rounded-full"></div>
                      جاري تحميل الأصول...
                    </div>
                  ) : assets.length === 0 ? (
                    <div className="p-3 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg text-yellow-700 dark:text-yellow-300 text-sm">
                      لا توجد أصول متاحة. يرجى إضافة أصول أولاً من تبويب "إدارة
                      الأصول"
                    </div>
                  ) : (
                    <select
                      className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                      value={uploadForm.assetId}
                      onChange={(e) =>
                        setUploadForm({
                          ...uploadForm,
                          assetId: e.target.value,
                        })
                      }
                    >
                      <option value="">-- اختر الأصل --</option>
                      {assets.map((asset) => (
                        <option key={asset.id} value={asset.id}>
                          {asset.name} {asset.code ? `(${asset.code})` : ""}
                        </option>
                      ))}
                    </select>
                  )}
                </div>

                {/* Document Type */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    نوع المستند *
                  </label>
                  <select
                    className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                    value={uploadForm.documentType}
                    onChange={(e) =>
                      setUploadForm({
                        ...uploadForm,
                        documentType: e.target.value,
                      })
                    }
                  >
                    {documentTypes.map((type) => (
                      <option key={type.value} value={type.value}>
                        {type.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* File Upload */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    اختر ملف
                  </label>
                  <input
                    type="file"
                    onChange={handleFileChange}
                    accept="image/*,.pdf,.doc,.docx,.xls,.xlsx"
                    className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-medium file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100 dark:file:bg-indigo-900 dark:file:text-indigo-200"
                  />
                  {selectedFile && (
                    <p className="mt-1 text-sm text-green-600">
                      تم اختيار: {selectedFile.name}
                    </p>
                  )}
                </div>

                <div className="text-center text-gray-400 text-sm">أو</div>

                {/* File URL */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    رابط الملف
                  </label>
                  <input
                    type="url"
                    className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                    value={uploadForm.fileUrl}
                    onChange={(e) =>
                      setUploadForm({ ...uploadForm, fileUrl: e.target.value })
                    }
                    placeholder="https://..."
                    dir="ltr"
                    disabled={!!selectedFile}
                  />
                </div>

                {/* File Name */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    اسم الملف
                  </label>
                  <input
                    type="text"
                    className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                    value={uploadForm.fileName}
                    onChange={(e) =>
                      setUploadForm({ ...uploadForm, fileName: e.target.value })
                    }
                    placeholder="مثال: فاتورة_شراء_لابتوب.pdf"
                  />
                </div>

                {/* Description */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    الوصف (اختياري)
                  </label>
                  <textarea
                    className="block w-full border border-gray-300 dark:border-gray-600 rounded-lg py-2.5 px-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                    rows={2}
                    value={uploadForm.description}
                    onChange={(e) =>
                      setUploadForm({
                        ...uploadForm,
                        description: e.target.value,
                      })
                    }
                    placeholder="وصف اختياري للمستند"
                  />
                </div>

                <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
                  <button
                    type="button"
                    onClick={() => {
                      setShowUploadModal(false);
                      resetUploadForm();
                    }}
                    className="px-5 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600"
                  >
                    إلغاء
                  </button>
                  <button
                    type="button"
                    onClick={handleUpload}
                    disabled={uploading || !uploadForm.assetId}
                    className="px-5 py-2.5 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50"
                  >
                    {uploading ? "جاري الرفع..." : "رفع المستند"}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Lightbox for images */}
      {lightbox.open && (
        <Lightbox
          mainSrc={lightbox.src}
          onCloseRequest={() => setLightbox({ open: false, src: "" })}
        />
      )}
    </div>
  );
};

export default DocumentsSection;

import React, { useState, useEffect } from "react";
import {
  DocumentTextIcon,
  PrinterIcon,
  ArrowDownTrayIcon,
  CheckBadgeIcon,
  ComputerDesktopIcon,
  CameraIcon,
  ArrowPathIcon,
  CloudArrowUpIcon,
  PlusCircleIcon,
  UserGroupIcon,
  XMarkIcon,
} from "@heroicons/react/24/outline";
import { format } from "date-fns";
import { ar } from "date-fns/locale";
import { companyAwareApi } from "../../../../services/companyAwareApi";

interface ReceiptData {
  id: string;
  referenceNumber: string;
  date: string;
  employeeName: string;
  employeeId: string;
  jobTitle: string;
  department: string;
  assetName: string;
  assetCategory: string;
  assetCode: string;
  assetSerial: string;
  assetCondition: string;
  managerName: string;
  signatureUrl?: string;
  status: "pending" | "signed" | "archived";
}

const ReceiptFormSection: React.FC = () => {
  const [selectedReceipt, setSelectedReceipt] = useState<ReceiptData | null>(
    null,
  );
  const [isPrinting, setIsPrinting] = useState(false);
  const [showUploadSignature, setShowUploadSignature] = useState(false);
  const [showGenerateModal, setShowGenerateModal] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<string>("");
  const [selectedAsset, setSelectedAsset] = useState<string>("");
  const [employees, setEmployees] = useState<any[]>([]);
  const [assets, setAssets] = useState<any[]>([]);
  const [loadingData, setLoadingData] = useState(false);
  const [receipts, setReceipts] = useState<ReceiptData[]>([
    {
      id: "REC-001",
      referenceNumber: "AST-2024-001",
      date: new Date().toISOString(),
      employeeName: "أحمد محمد علي",
      employeeId: "EMP-1552",
      jobTitle: "مطور واجهات (Frontend Developer)",
      department: "تطوير البرمجيات",
      assetName: 'MacBook Pro M3 14"',
      assetCategory: "أجهزة حاسوب محمول",
      assetCode: "LP-8842",
      assetSerial: "SN-998822JH1",
      assetCondition: "جديد (Brand New)",
      managerName: "م. خالد ابراهيم",
      status: "pending",
    },
    {
      id: "REC-002",
      referenceNumber: "AST-2024-005",
      date: new Date(Date.now() - 86400000 * 2).toISOString(),
      employeeName: "سارة محمود حسن",
      employeeId: "EMP-2210",
      jobTitle: "أخصائي موارد بشرية (HR Specialist)",
      department: "الموارد البشرية",
      assetName: "iPhone 15 Pro Max",
      assetCategory: "هواتف ذكية",
      assetCode: "MB-1022",
      assetSerial: "SN-IPH15-XXL",
      assetCondition: "ممتازة",
      managerName: "م. خالد ابراهيم",
      signatureUrl:
        "https://upload.wikimedia.org/wikipedia/commons/3/3a/Jon_Foreman_Signature.png",
      status: "signed",
    },
  ]);

  const handlePrint = () => {
    setIsPrinting(true);
    setTimeout(() => {
      window.print();
      setIsPrinting(false);
    }, 500);
  };

  const handleGeneratePDF = () => {
    alert("جاري توليد ملف PDF وحفظه في سجلات الموظف...");
  };

  useEffect(() => {
    fetchEmployees();
    fetchAssets();
  }, []);

  const fetchEmployees = async () => {
    setLoadingData(true);
    try {
      const response = await companyAwareApi.get("/hr/employees");
      console.log("📋 Employees API Response:", response.data);
      if (response.data.success) {
        const employeesList =
          response.data.employees || response.data.data || [];
        console.log(
          "✅ Employees loaded:",
          employeesList.length,
          employeesList,
        );
        setEmployees(employeesList);
      }
    } catch (error) {
      console.error("❌ Error fetching employees:", error);
    } finally {
      setLoadingData(false);
    }
  };

  const fetchAssets = async () => {
    try {
      const response = await companyAwareApi.get("/hr/assets");
      console.log("🏢 Assets API Response:", response.data);
      if (response.data.success) {
        const assetsList = response.data.data || [];
        console.log("✅ Assets loaded:", assetsList.length, assetsList);
        setAssets(assetsList);
      }
    } catch (error) {
      console.error("❌ Error fetching assets:", error);
    }
  };

  const handleGenerateReceipt = () => {
    console.log("🔄 Generate Receipt Called");
    console.log("Selected Employee ID:", selectedEmployee);
    console.log("Selected Asset ID:", selectedAsset);
    console.log("Available Employees:", employees);
    console.log("Available Assets:", assets);

    if (!selectedEmployee || !selectedAsset) {
      alert("الرجاء اختيار الموظف والأصل");
      return;
    }

    const employee = employees.find((e) => e.id === selectedEmployee);
    const asset = assets.find((a) => a.id === selectedAsset);

    console.log("Found Employee:", employee);
    console.log("Found Asset:", asset);

    if (!employee) {
      alert("لم يتم العثور على الموظف المختار");
      return;
    }

    if (!asset) {
      alert("لم يتم العثور على الأصل المختار");
      return;
    }

    const newReceipt: ReceiptData = {
      id: `REC-${Math.floor(Math.random() * 1000)}`,
      referenceNumber: `AST-2024-${String(Math.floor(Math.random() * 1000)).padStart(3, "0")}`,
      date: new Date().toISOString(),
      employeeName:
        `${employee.firstName || ""} ${employee.lastName || ""}`.trim() ||
        employee.name ||
        "غير محدد",
      employeeId: employee.employeeId || employee.id || "غير محدد",
      jobTitle: employee.position || employee.jobTitle || "غير محدد",
      department:
        employee.department?.name || employee.department || "غير محدد",
      assetName: asset.name || "غير محدد",
      assetCategory: asset.category?.name || asset.assetCategory || "غير محدد",
      assetCode: asset.code || "غير محدد",
      assetSerial:
        asset.serialNumber ||
        `SN-${Math.random().toString(36).substring(2, 11).toUpperCase()}`,
      assetCondition:
        asset.condition === "NEW"
          ? "جديد (Brand New)"
          : asset.condition === "GOOD"
            ? "جيد"
            : asset.condition === "FAIR"
              ? "مقبول"
              : "جديد",
      managerName: "م. خالد ابراهيم",
      status: "pending",
    };

    console.log("✅ Generated Receipt:", newReceipt);

    // Add to receipts list
    setReceipts((prev) => [newReceipt, ...prev]);
    setSelectedReceipt(newReceipt);
    setShowGenerateModal(false);
    setSelectedEmployee("");
    setSelectedAsset("");
  };

  return (
    <div className="space-y-6 animate-fade-in print:p-0">
      {/* Header - Hidden on Print */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <DocumentTextIcon className="h-7 w-7 text-indigo-600" />
            نماذج التسليم والاستلام الرسمية
          </h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            توليد وطباعة أصول الاستلام الرسمية (العهدة) برقم مرجعي وتفاصيل كاملة
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setShowGenerateModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all font-bold shadow-lg shadow-indigo-200 dark:shadow-none"
          >
            <PlusCircleIcon className="h-5 w-5" />
            توليد نموذج جديد
          </button>
          <button className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-200 hover:bg-gray-50 transition-all font-medium">
            <ArrowPathIcon className="h-5 w-5" />
            تحديث القائمة
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* List Side - Hidden on Print */}
        <div className="lg:col-span-4 space-y-4 print:hidden">
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider">
            الطلبات الجاهزة للتوقيع
          </h3>
          {receipts.map((receipt) => (
            <button
              key={receipt.id}
              onClick={() => setSelectedReceipt(receipt)}
              className={`w-full text-right p-4 rounded-2xl border transition-all ${selectedReceipt?.id === receipt.id
                ? "bg-indigo-50 border-indigo-200 dark:bg-indigo-900/20 dark:border-indigo-800 ring-2 ring-indigo-500/20"
                : "bg-white border-gray-100 dark:bg-gray-800 dark:border-gray-700 hover:border-indigo-300"
                }`}
            >
              <div className="flex justify-between items-start mb-2">
                <span
                  className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${receipt.status === "signed"
                    ? "bg-green-100 text-green-700"
                    : "bg-amber-100 text-amber-700"
                    }`}
                >
                  {receipt.status === "signed" ? "مـوقع" : "بانتظار التوقيع"}
                </span>
                <span className="text-xs text-gray-400 font-mono">
                  {receipt.referenceNumber}
                </span>
              </div>
              <h4 className="font-bold text-gray-900 dark:text-white">
                {receipt.employeeName}
              </h4>
              <div className="flex items-center gap-1.5 mt-1 text-sm text-gray-500">
                <ComputerDesktopIcon className="h-4 w-4" />
                <span>{receipt.assetName}</span>
              </div>
            </button>
          ))}

          <div className="p-4 bg-indigo-600 rounded-2xl text-white shadow-lg shadow-indigo-200 dark:shadow-none">
            <h4 className="font-bold mb-2 flex items-center gap-2">
              <CheckBadgeIcon className="h-5 w-5" />
              لماذا نستخدم هذا النموذج؟
            </h4>
            <p className="text-xs opacity-90 leading-relaxed">
              هذا النموذج يعتبر وثيقة قانونية تثبت استلام الموظف للعهدة الموضحة،
              ويستخدم كمستند رسمي عند الجرد أو عند إخلاء الطرف.
            </p>
          </div>
        </div>

        {/* Content/Form Preview Side */}
        <div className="lg:col-span-8">
          {!selectedReceipt ? (
            <div className="h-full flex flex-col items-center justify-center p-12 bg-white dark:bg-gray-800 rounded-3xl border-2 border-dashed border-gray-200 dark:border-gray-700">
              <DocumentTextIcon className="h-20 w-20 text-gray-200 mb-4" />
              <h3 className="text-xl font-bold text-gray-400">
                اختر طلباً من القائمة لعرض النموذج
              </h3>
            </div>
          ) : (
            <div className="space-y-6">
              {/* Actions Bar - Hidden on Print */}
              <div className="flex flex-wrap items-center justify-between gap-4 bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700 print:hidden">
                <div className="flex gap-2">
                  <button
                    onClick={handlePrint}
                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all font-bold shadow-lg shadow-indigo-200 dark:shadow-none"
                  >
                    <PrinterIcon className="h-5 w-5" />
                    طباعة
                  </button>
                  <button
                    onClick={handleGeneratePDF}
                    className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-xl text-gray-700 dark:text-gray-200 hover:bg-gray-50 transition-all font-medium"
                  >
                    <ArrowDownTrayIcon className="h-5 w-5" />
                    حفظ كـ PDF
                  </button>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => setShowUploadSignature(!showUploadSignature)}
                    className="flex items-center gap-2 px-4 py-2 text-indigo-600 dark:text-indigo-400 font-bold hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-xl transition-all"
                  >
                    <CameraIcon className="h-5 w-5" />
                    إدراج توقيع
                  </button>
                </div>
              </div>

              {/* Signature Upload Placeholder - Hidden on Print */}
              {showUploadSignature && (
                <div className="p-6 bg-indigo-50 dark:bg-indigo-900/10 border-2 border-dashed border-indigo-200 dark:border-indigo-800 rounded-2xl animate-slide-down print:hidden">
                  <div className="flex flex-col items-center text-center">
                    <CloudArrowUpIcon className="h-10 w-10 text-indigo-500 mb-2" />
                    <h4 className="font-bold text-indigo-900 dark:text-indigo-100">
                      تحميل صورة التوقيع
                    </h4>
                    <p className="text-sm text-indigo-600/70 mb-4 italic">
                      يمكنك رفع صورة توقيع الموظف ليظهر في النموذج تلقائياً
                    </p>
                    <input type="file" className="hidden" id="sig-upload" />
                    <label
                      htmlFor="sig-upload"
                      className="cursor-pointer px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all font-bold"
                    >
                      اختر ملف
                    </label>
                  </div>
                </div>
              )}

              {/* THE FORM CONTAINER */}
              <div
                className={`bg-white text-gray-900 p-8 sm:p-12 shadow-2xl rounded-sm border border-gray-100 mx-auto max-w-[800px] font-sans relative ${isPrinting ? "print:shadow-none print:border-none print:p-0" : ""}`}
                id="printable-receipt"
              >
                {/* Form Header */}
                <div className="flex justify-between items-start border-b-4 border-indigo-600 pb-8 mb-8">
                  <div>
                    <h1 className="text-3xl font-black text-gray-900 mb-2">
                      نموذج استلام عهدة
                    </h1>
                    <p className="text-indigo-600 font-bold">
                      إدارة الموارد البشرية - قسم الأصول
                    </p>
                  </div>
                  <div className="text-left" dir="ltr">
                    <p className="text-sm font-bold text-gray-400">
                      Reference No.
                    </p>
                    <p className="text-xl font-mono font-bold text-gray-900">
                      {selectedReceipt.referenceNumber}
                    </p>
                  </div>
                </div>

                {/* Employee Info Section */}
                <div className="mb-8">
                  <h4 className="text-xs font-black text-white bg-gray-900 px-3 py-1.5 inline-block rounded mb-4">
                    أولاً: بيانات الموظف المستلم
                  </h4>
                  <div className="grid grid-cols-2 gap-y-4 gap-x-12">
