export default function PayrollSimulator() {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(
    null,
  );
  const [simulation, setSimulation] = useState<SimulationState>({
    baseSalary: 0,
    attendance: [],
    leaves: [],
    manualDeductions: [],
    allowances: {},
  });
  const [results, setResults] = useState<any>(null);
  const [calculating, setCalculating] = useState(false);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      setLoading(true);
      const response = await api.get("/hr/employees?limit=100");
      setEmployees(response.data.employees);
    } catch (error) {
      toast.error("فشل في جلب قائمة الموظفين");
    } finally {
      setLoading(false);
    }
  };

  const filteredEmployees = useMemo(() => {
    return employees.filter(
      (e) =>
        `${e.firstName} ${e.lastName}`
          .toLowerCase()
          .includes(search.toLowerCase()) || e.employeeNumber.includes(search),
    );
  }, [employees, search]);

  const selectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSimulation({
      baseSalary: emp.baseSalary,
      attendance: Array.from({ length: 22 }, (_, i) => ({
        id: `att-${i}`,
        date: new Date(2026, 1, i + 1),
        status: "PRESENT",
        lateMinutes: 0,
        overtimeHours: 0,
      })),
      leaves: [],
      manualDeductions: [],
      allowances: {},
    });
    setResults(null);
  };

  const runSimulation = async () => {
    if (!selectedEmployee) return;
    try {
      setCalculating(true);
      const response = await api.post(
        `/hr/payroll/calculate/${selectedEmployee.id}`,
        {
          month: 2,
          year: 2026,
          overrides: simulation,
        },
      );
      setResults(response.data.payroll);
      toast.success("تم الانتهاء من محاكاة الحسابات");
    } catch (error: any) {
      toast.error(error.response?.data?.error || "فشل في المحاكاة");
    } finally {
      setCalculating(false);
    }
  };

  const applyScenario = (scenarioId: string) => {
    if (!selectedEmployee) return;
    const scenario = SCENARIOS.find((s) => s.id === scenarioId);
    if (scenario) {
      setSimulation(scenario.apply(selectedEmployee.baseSalary));
      toast.info(`تم تطبيق سيناريو: ${scenario.name}`);
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
    }).format(val);
  };

  return (
    <div className="flex gap-6 h-[calc(100vh-180px)]" dir="rtl">
      {/* Search & Select Panel */}
      <Card className="w-80 flex flex-col shrink-0 border-none shadow-xl bg-slate-50/50 dark:bg-slate-950/20">
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <Users className="h-5 w-5 text-indigo-600" />
            اختيار موظف للتجربة
          </CardTitle>
          <div className="relative mt-2">
            <Search className="absolute right-3 top-2.5 h-4 w-4 text-slate-400" />
            <Input
              placeholder="بحث باسم أو رقم الموظف..."
              className="pr-9"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </CardHeader>
        <CardContent className="p-0 flex-1 overflow-hidden">
          <ScrollArea className="h-full">
            <div className="p-4 space-y-2">
              {filteredEmployees.map((emp) => (
                <button
                  key={emp.id}
                  onClick={() => selectEmployee(emp)}
                  className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all ${selectedEmployee?.id === emp.id ? "bg-indigo-600 text-white shadow-lg shadow-indigo-200" : "bg-white dark:bg-slate-900 hover:bg-indigo-50 dark:hover:bg-slate-800"}`}
                >
                  <Avatar className="h-10 w-10 border-2 border-white/20">
                    <AvatarImage src={emp.avatar} />
                    <AvatarFallback className="bg-indigo-200 text-indigo-700">
                      {emp.firstName[0]}
                    </AvatarFallback>
                  </Avatar>
                  <div className="text-right overflow-hidden">
                    <p className="font-bold text-sm truncate">
                      {emp.firstName} {emp.lastName}
                    </p>
                    <p
                      className={`text-xs ${selectedEmployee?.id === emp.id ? "text-indigo-100" : "text-slate-500"}`}
                    >
                      #{emp.employeeNumber} •{" "}
                      {emp.department?.name || "بدون قسم"}
                    </p>
                  </div>
                </button>
              ))}
            </div>
          </ScrollArea>
        </CardContent>
      </Card>

      {/* Workspace Area */}
      <div className="flex-1 overflow-hidden flex flex-col gap-6">
        {!selectedEmployee ? (
          <div className="flex-1 flex flex-col items-center justify-center bg-white dark:bg-slate-950/20 rounded-2xl border border-dashed border-slate-200">
            <motion.div
              animate={{ rotate: [0, 10, -10, 0] }}
              transition={{ repeat: Infinity, duration: 4 }}
              className="h-24 w-24 bg-indigo-50 dark:bg-slate-900 rounded-full flex items-center justify-center mb-4"
            >
              <Users className="h-12 w-12 text-indigo-400" />
            </motion.div>
            <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">
              ابدأ تجربة الحسابات الآن
            </h3>
            <p className="text-slate-500 text-center max-w-sm">
              قم باختيار موظف من القائمة الجانبية لبدء محاكاة عملية صرف الراتب
              وتجربة كافة السيناريوهات المالية.
            </p>
          </div>
        ) : (
          <>
            {/* Simulation Controls */}
            <Card className="flex-1 flex flex-col overflow-hidden border-none shadow-xl">
              <CardHeader className="bg-indigo-600 text-white py-4 px-6 flex-row items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className="h-12 w-12 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-md">
                    <Calculator className="h-6 w-6 text-white" />
                  </div>
                  <div>
                    <h2 className="text-xl font-bold">
                      محاكاة راتب: {selectedEmployee.firstName}
                    </h2>
                    <p className="text-indigo-100 text-xs opacity-90">
                      الراتب الأساسي الحالي:{" "}
                      {formatCurrency(selectedEmployee.baseSalary)}
                    </p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Button
                    onClick={runSimulation}
                    disabled={calculating}
                    className="bg-white text-indigo-700 hover:bg-indigo-50 font-bold h-10 px-6 rounded-lg"
                  >
                    {calculating ? (
                      <RefreshCw className="h-4 w-4 animate-spin ml-2" />
                    ) : (
                      <Zap className="h-4 w-4 ml-2" />
                    )}
                    بدء الحساب
                  </Button>
                </div>
              </CardHeader>

              <Tabs
                defaultValue="scenarios"
                className="flex-1 flex flex-col min-h-0"
              >
                <TabsList className="bg-slate-50 dark:bg-slate-900 p-1 flex justify-start rounded-none h-14 px-6 gap-2">
                  <TabsTrigger
                    value="scenarios"
                    className="data-[state=active]:bg-white dark:data-[state=active]:bg-slate-800 h-full rounded-none border-b-2 border-transparent data-[state=active]:border-indigo-600 px-6 font-bold"
                  >
                    سيناريوهات جاهزة
                  </TabsTrigger>
                  <TabsTrigger
                    value="attendance"
                    className="data-[state=active]:bg-white dark:data-[state=active]:bg-slate-800 h-full rounded-none border-b-2 border-transparent data-[state=active]:border-indigo-600 px-6 font-bold"
                  >
                    الحضور والإضافي
                  </TabsTrigger>
                  <TabsTrigger
                    value="deductions"
                    className="data-[state=active]:bg-white dark:data-[state=active]:bg-slate-800 h-full rounded-none border-b-2 border-transparent data-[state=active]:border-indigo-600 px-6 font-bold"
                  >
                    الخصومات
                  </TabsTrigger>
                  <TabsTrigger
                    value="allowances"
                    className="data-[state=active]:bg-white dark:data-[state=active]:bg-slate-800 h-full rounded-none border-b-2 border-transparent data-[state=active]:border-indigo-600 px-6 font-bold"
                  >
                    البدلات
                  </TabsTrigger>
                </TabsList>

                <div className="flex-1 overflow-hidden">
                  <ScrollArea className="h-full">
                    <div className="p-8">
                      {/* Scenarios Tab */}
                      <TabsContent value="scenarios" className="mt-0 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {SCENARIOS.map((scenario) => (
                            <button
                              key={scenario.id}
                              onClick={() => applyScenario(scenario.id)}
                              className="group text-right p-5 rounded-2xl bg-slate-50 dark:bg-slate-900/50 border border-slate-100 dark:border-slate-800 hover:border-indigo-300 hover:bg-white dark:hover:bg-slate-800 transition-all hover:shadow-lg"
                            >
                              <div className="h-10 w-10 rounded-xl bg-indigo-50 dark:bg-slate-800 flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                                <scenario.icon className="h-5 w-5 text-indigo-600" />
                              </div>
                              <h4 className="font-bold text-slate-900 dark:text-white mb-1">
                                {scenario.name}
                              </h4>
                              <p className="text-xs text-slate-500 leading-relaxed">
                                {scenario.description}
                              </p>
                            </button>
                          ))}
                        </div>
                      </TabsContent>

                      {/* Attendance Tab */}
                      <TabsContent
                        value="attendance"
                        className="mt-0 space-y-6"
                      >
                        <div className="bg-amber-50 dark:bg-amber-950/20 border border-amber-100 dark:border-amber-900/50 p-4 rounded-xl flex items-start gap-4 mb-6">
                          <AlertCircle className="h-5 w-5 text-amber-600 shrink-0 mt-0.5" />
                          <p className="text-sm text-amber-800 dark:text-amber-200">
                            يمكنك تعديل أيام الحضور، التأخيرات، وساعات العمل
                            الإضافي لكل يوم على حدة لاختبار كيفية تأثر الراتب.
                          </p>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                          {simulation.attendance.map((att, idx) => (
                            <div
                              key={idx}
                              className="p-4 rounded-xl border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900/50 flex gap-4"
                            >
                              <div className="shrink-0 text-center">
                                <div className="text-xs text-slate-500 font-bold uppercase">
                                  {att.date.getDate()} فبراير
                                </div>
                              </div>
                              <div className="flex-1 space-y-2">
                                <Select
                                  value={att.status}
                                  onValueChange={(v) => {
                                    const newAtt = [...simulation.attendance];
                                    newAtt[idx].status = v;
                                    setSimulation({
                                      ...simulation,
                                      attendance: newAtt,
                                    });
                                  }}
                                >
                                  <SelectTrigger className="h-8 text-xs font-bold">
                                    <SelectValue />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectItem value="PRESENT text-emerald-600">
                                      حاضر
                                    </SelectItem>
                                    <SelectItem value="ABSENT text-rose-600">
                                      غائب
                                    </SelectItem>
                                    <SelectItem value="LATE text-amber-600">
                                      متأخر
                                    </SelectItem>
                                  </SelectContent>
                                </Select>
                                <div className="flex gap-2">
                                  <div className="flex-1">
                                    <Label className="text-[10px] text-slate-400">
                                      تأخير (د)
                                    </Label>
                                    <Input
                                      type="number"
                                      value={att.lateMinutes}
                                      className="h-7 text-xs"
                                      onChange={(e) => {
                                        const newAtt = [
                                          ...simulation.attendance,
                                        ];
                                        newAtt[idx].lateMinutes =
                                          parseInt(e.target.value) || 0;
                                        setSimulation({
                                          ...simulation,
                                          attendance: newAtt,
                                        });
                                      }}
                                    />
                                  </div>
                                  <div className="flex-1">
                                    <Label className="text-[10px] text-slate-400">
                                      إضافي (س)
                                    </Label>
                                    <Input
                                      type="number"
                                      value={att.overtimeHours}
                                      className="h-7 text-xs"
                                      onChange={(e) => {
                                        const newAtt = [
                                          ...simulation.attendance,
                                        ];
                                        newAtt[idx].overtimeHours =
                                          parseInt(e.target.value) || 0;
                                        setSimulation({
                                          ...simulation,
                                          attendance: newAtt,
                                        });
                                      }}
                                    />
                                  </div>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </TabsContent>

                      {/* Deductions Tab */}
                      <TabsContent
                        value="deductions"
                        className="mt-0 space-y-6"
                      >
                        <div className="flex items-center justify-between mb-2">
                          <h4 className="font-bold text-slate-900 dark:text-white flex items-center gap-2 text-lg">
                            <MinusCircle className="h-5 w-5 text-rose-500" />
                            الخصومات والجزاءات المخصصة
                          </h4>
                          <Button
                            variant="outline"
                            size="sm"
                            className="rounded-full h-8"
                            onClick={() => {
                              setSimulation({
                                ...simulation,
                                manualDeductions: [
                                  ...simulation.manualDeductions,
                                  {
                                    id: Math.random().toString(),
                                    amount: 0,
                                    reason: "",
                                    type: "OTHER",
                                    date: new Date(),
                                  },
                                ],
                              });
                            }}
                          >
                            <Plus className="h-4 w-4 ml-1" /> إدخال خصم
                          </Button>
                        </div>
                        <div className="space-y-3">
                          {simulation.manualDeductions.length === 0 ? (
                            <div className="py-12 text-center text-slate-400 italic text-sm">
                              لا توجد خصومات مخصصة مضافة حالياً
                            </div>
                          ) : (
                            simulation.manualDeductions.map((d, i) => (
                              <div
                                key={d.id}
                                className="flex gap-4 p-4 rounded-2xl bg-slate-50 dark:bg-slate-900/50 items-end border border-slate-100 dark:border-slate-800"
                              >
                                <div className="space-y-1 flex-[2]">
                                  <Label className="text-xs">
                                    السبب / الوصف
                                  </Label>
                                  <Input
                                    placeholder="مثلاً: سلفة مرتب، مخالفة سياسة..."
                                    value={d.reason}
                                    onChange={(e) => {
                                      const newD = [
                                        ...simulation.manualDeductions,
                                      ];
                                      newD[i].reason = e.target.value;
                                      setSimulation({
                                        ...simulation,
                                        manualDeductions: newD,
                                      });
                                    }}
                                  />
                                </div>
                                <div className="space-y-1 flex-1">
                                  <Label className="text-xs">
                                    المبلغ (EGP)
                                  </Label>
                                  <Input
                                    type="number"
                                    value={d.amount}
                                    onChange={(e) => {
                                      const newD = [
                                        ...simulation.manualDeductions,
                                      ];
                                      newD[i].amount =
                                        parseFloat(e.target.value) || 0;
                                      setSimulation({
                                        ...simulation,
                                        manualDeductions: newD,
                                      });
                                    }}
                                  />
                                </div>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="text-rose-500 hover:bg-rose-50 rounded-xl"
                                  onClick={() => {
                                    setSimulation({
                                      ...simulation,
                                      manualDeductions:
                                        simulation.manualDeductions.filter(
                                          (item) => item.id !== d.id,
                                        ),
                                    });
                                  }}
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              </div>
                            ))
                          )}
                        </div>
                      </TabsContent>

                      {/* Allowances Tab */}
                      <TabsContent
                        value="allowances"
                        className="mt-0 space-y-6"
                      >
                        <div className="flex items-center justify-between mb-4">
                          <h4 className="font-bold text-slate-900 dark:text-white flex items-center gap-2 text-lg">
                            <Plus className="h-5 w-5 text-emerald-500" />
                            البدلات والمزايا الإضافية
                          </h4>
                          <Button
                            variant="outline"
                            size="sm"
                            className="rounded-full h-8"
                            onClick={() => {
                              const name = `بدل جديد ${Object.keys(simulation.allowances).length + 1}`;
                              setSimulation({
                                ...simulation,
                                allowances: {
                                  ...simulation.allowances,
                                  [name]: 0,
                                },
                              });
                            }}
                          >
                            <Plus className="h-4 w-4 ml-1" /> إضافة بدل
                          </Button>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          {Object.entries(simulation.allowances).map(
                            ([name, amount], idx) => (
                              <div
                                key={idx}
                                className="flex gap-4 p-4 rounded-2xl bg-slate-50 dark:bg-slate-900/50 items-end border border-slate-100 dark:border-slate-800"
                              >
                                <div className="space-y-1 flex-[2]">
                                  <Label className="text-xs">اسم البدل</Label>
                                  <Input
                                    value={name}
                                    onChange={(e) => {
                                      const newName = e.target.value;
                                      const { [name]: oldAmount, ...rest } =
                                        simulation.allowances;
                                      setSimulation({
                                        ...simulation,
                                        allowances: {
                                          ...rest,
                                          [newName]: oldAmount,
                                        },
                                      });
                                    }}
                                  />
                                </div>
                                <div className="space-y-1 flex-1">
                                  <Label className="text-xs">المبلغ</Label>
                                  <Input
                                    type="number"
                                    value={amount}
                                    onChange={(e) => {
                                      setSimulation({
                                        ...simulation,
                                        allowances: {
                                          ...simulation.allowances,
                                          [name]:
                                            parseFloat(e.target.value) || 0,
                                        },
                                      });
                                    }}
                                  />
                                </div>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="text-rose-500 hover:bg-rose-50"
                                  onClick={() => {
                                    const { [name]: _, ...rest } =
                                      simulation.allowances;
                                    setSimulation({
                                      ...simulation,
                                      allowances: rest,
                                    });
                                  }}
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              </div>
                            ),
                          )}
                        </div>
                      </TabsContent>
                    </div>
                  </ScrollArea>
                </div>
              </Tabs>
            </Card>
          </>
        )}
      </div>

      {/* Result Sidebar */}
      <Card className="w-96 flex flex-col shrink-0 border-none shadow-2xl bg-white dark:bg-slate-900">
        <CardHeader className="border-b dark:border-slate-800">
          <CardTitle className="text-lg flex items-center justify-between">
            نتائج الحساب المباشرة
            <Badge
              variant="outline"
              className="text-[10px] font-bold tracking-widest uppercase"
            >
              Live Breakdown
            </Badge>
          </CardTitle>
          <CardDescription>
            هذه البيانات تقديرية بناءً على المدخلات الحالية
          </CardDescription>
        </CardHeader>
        <CardContent className="p-0 flex-1 overflow-hidden flex flex-col">
          {!results ? (
            <div className="flex-1 flex flex-col items-center justify-center p-8 text-center text-slate-400">
              <Calculator className="h-16 w-16 mb-4 opacity-10" />
              <p className="text-sm italic">
                اضغط على "بدء الحساب" لرؤية تفاصيل الراتب والخصومات والضرائب
                المطبقة.
              </p>
            </div>
          ) : (
            <>
              <ScrollArea className="flex-1">
                <div className="p-6 space-y-6">
                  {/* Gross Section */}
                  <div className="space-y-3">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                      <Plus className="h-3 w-3 text-emerald-500" /> إجمالي
                      الاستحقاقات
                    </h5>
                    <div className="space-y-2">
                      <div className="flex justify-between text-sm">
                        <span className="text-slate-600 dark:text-slate-300">
                          الراتب الأساسي
                        </span>
                        <span className="font-bold">
                          {formatCurrency(results.baseSalary)}
                        </span>
                      </div>
                      <div className="flex justify-between text-sm">
                        <span className="text-slate-600 dark:text-slate-300">
                          إجمالي البدلات
                        </span>
                        <span className="font-bold text-emerald-600">
                          +{formatCurrency(results.totalAllowances)}
                        </span>
                      </div>
                      {results.overtimeAmount > 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-600 dark:text-slate-300">
                            العمل الإضافي ({results.overtimeHours} س)
                          </span>
                          <span className="font-bold text-emerald-600">
                            +{formatCurrency(results.overtimeAmount)}
                          </span>
                        </div>
                      )}
                      {results.bonuses > 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-600 dark:text-slate-300">
                            المكافآت
                          </span>
                          <span className="font-bold text-emerald-600">
                            +{formatCurrency(results.bonuses)}
                          </span>
                        </div>
                      )}
                      <Separator className="my-2 bg-slate-100 dark:bg-slate-800" />
                      <div className="flex justify-between font-bold text-slate-900 dark:text-white">
                        <span>إجمالي الدخل</span>
                        <span>{formatCurrency(results.grossSalary)}</span>
                      </div>
                    </div>
                  </div>

                  {/* Deductions Section */}
                  <div className="space-y-3">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                      <MinusCircle className="h-3 w-3 text-rose-500" /> إجمالي
                      الاستقطاعات
                    </h5>
                    <div className="space-y-2">
                      {results.absentDays > 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-600 dark:text-slate-300">
                            خصم الغياب ({results.absentDays} يوم)
                          </span>
                          <span className="font-bold text-rose-600">
                            -{formatCurrency(results.attendanceDeduction)}
                          </span>
                        </div>
                      )}
                      {results.latePenalty > 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-600 dark:text-slate-300">
                            خصم التأخير
                          </span>
                          <span className="font-bold text-rose-600">
                            -{formatCurrency(results.latePenalty)}
                          </span>
                        </div>
                      )}
                      <div className="flex justify-between text-sm">
                        <span className="text-slate-600 dark:text-slate-300">
                          تأمينات اجتماعية
                        </span>
                        <span className="font-bold text-rose-600">
                          -{formatCurrency(results.socialInsurance)}
                        </span>
                      </div>
                      <div className="flex justify-between text-sm">
                        <span className="text-slate-600 dark:text-slate-300">
                          ضريبة الدخل
                        </span>
                        <span className="font-bold text-rose-600">
                          -{formatCurrency(results.taxAmount)}
                        </span>
                      </div>
                      {results.totalDeductions >
                        results.attendanceDeduction + results.latePenalty && (
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-600 dark:text-slate-300">
                            خصومات أخرى
                          </span>
                          <span className="font-bold text-rose-600">
                            -
                            {formatCurrency(
                              results.totalDeductions -
                                results.attendanceDeduction -
                                results.latePenalty,
                            )}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Summary Box */}
                  <div className="bg-indigo-600 rounded-3xl p-6 text-white text-center shadow-xl shadow-indigo-200 dark:shadow-none relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-2 opacity-10">
                      <ShieldCheck className="h-20 w-20" />
                    </div>
                    <p className="text-indigo-100 text-sm font-medium mb-1">
                      صافي المبلغ المستحق
                    </p>
                    <h4 className="text-3xl font-black mb-1">
                      {formatCurrency(results.netSalary)}
                    </h4>
                    <p className="text-[10px] text-white/90 font-bold mb-1">
                      {numberToArabicWords(results.netSalary)}
                    </p>
                    <p className="text-[10px] text-white/60">
                      تم حساب الضرائب والتأمينات حسب القوانين المتبعة
                    </p>
                  </div>

                  {/* Verification Info */}
                  <div className="bg-slate-50 dark:bg-slate-800 p-4 rounded-xl space-y-2 border border-slate-100 dark:border-slate-700">
                    <div className="flex justify-between text-xs items-center">
                      <span className="text-slate-500">
                        أيام العمل المعتبرة:
                      </span>
                      <span className="font-bold">
                        {results.workingDays} يوم
                      </span>
                    </div>
                    <div className="flex justify-between text-xs items-center">
                      <span className="text-slate-500">معدل أجر اليوم:</span>
                      <span className="font-bold">
                        {formatCurrency(
                          results.baseSalary / results.workingDays,
                        )}
                      </span>
                    </div>
                  </div>
                </div>
              </ScrollArea>

              <div className="p-6 border-t dark:border-slate-800 space-y-3">
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    className="flex-1 rounded-xl gap-2 h-11 border-slate-200"
                    onClick={() => toast.info("جاري إعداد قالب الطباعة...")}
                  >
                    <Printer className="h-4 w-4" />
                    طباعة تجريبية
                  </Button>
                  <Button
                    className="flex-1 rounded-xl bg-slate-900 hover:bg-black gap-2 h-11"
                    onClick={() => toast.success("تم حفظ المحاكاة كمسودة")}
                  >
                    <Save className="h-4 w-4" />
                    حفظ كمسودة
                  </Button>
                </div>
                <Button
                  className="w-full bg-emerald-600 hover:bg-emerald-700 h-12 rounded-xl text-lg font-bold shadow-lg shadow-emerald-200 dark:shadow-none"
                  onClick={() =>
                    toast.warning(
                      "لا يمكن اعتماد بيانات المحاكاة مباشرة، يرجى إنشاء كشف راتب رسمي.",
                    )
                  }
                >
                  <ShieldCheck className="h-5 w-5 ml-2" />
                  اعتماد كراتب رسمي
                </Button>
              </div>
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import {
  BriefcaseIcon,
  UserGroupIcon,
  ClipboardDocumentCheckIcon,
  CalendarDaysIcon,
  ChartBarIcon,
  PlusIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  CheckCircleIcon,
  ClockIcon,
  XCircleIcon,
} from "@heroicons/react/24/outline";
import { motion } from "framer-motion";
import { companyAwareApi } from "../../../services/companyAwareApi";
import JobPostingsSection from "./sections/JobPostingsSection";
import ApplicantsSection from "./sections/ApplicantsSection";
import InterviewsSection from "./sections/InterviewsSection";
import HiringPipelineSection from "./sections/HiringPipelineSection";
import ApplicationFormsSection from "./sections/ApplicationFormsSection";

interface RecruitmentStats {
  activeJobs: number;
  totalApplicants: number;
  scheduledInterviews: number;
  pendingReviews: number;
  hiredThisMonth: number;
  averageTimeToHire: number;
}

const RecruitmentDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<
    "overview" | "jobs" | "applicants" | "interviews" | "pipeline" | "forms"
  >("overview");
  const [stats, setStats] = useState<RecruitmentStats>({
    activeJobs: 0,
    totalApplicants: 0,
    scheduledInterviews: 0,
    pendingReviews: 0,
    hiredThisMonth: 0,
    averageTimeToHire: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/hr/recruitment/stats");
      if (response.data.success) {
        setStats(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching recruitment stats:", error);
      setStats({
        activeJobs: 0,
        totalApplicants: 0,
        scheduledInterviews: 0,
        pendingReviews: 0,
        hiredThisMonth: 0,
        averageTimeToHire: 0,
      });
    } finally {
      setLoading(false);
    }
  };

  const tabs = [
    { id: "overview", name: "نظرة عامة", icon: ChartBarIcon },
    { id: "jobs", name: "الوظائف المتاحة", icon: BriefcaseIcon },
    { id: "applicants", name: "المتقدمين", icon: UserGroupIcon },
    { id: "interviews", name: "المقابلات", icon: CalendarDaysIcon },
    { id: "pipeline", name: "مسار التوظيف", icon: ClipboardDocumentCheckIcon },
    {
      id: "forms",
      name: "استبيانات التقديم",
      icon: ClipboardDocumentCheckIcon,
    },
  ];

  const statCards = [
    {
      title: "الوظائف النشطة",
      value: stats.activeJobs,
      icon: BriefcaseIcon,
      color: "blue",
      bgColor: "bg-blue-50",
      iconColor: "text-blue-600",
      borderColor: "border-blue-200",
    },
    {
      title: "إجمالي المتقدمين",
      value: stats.totalApplicants,
      icon: UserGroupIcon,
      color: "purple",
      bgColor: "bg-purple-50",
      iconColor: "text-purple-600",
      borderColor: "border-purple-200",
    },
    {
      title: "المقابلات المجدولة",
      value: stats.scheduledInterviews,
      icon: CalendarDaysIcon,
      color: "green",
      bgColor: "bg-green-50",
      iconColor: "text-green-600",
      borderColor: "border-green-200",
    },
    {
      title: "بانتظار المراجعة",
      value: stats.pendingReviews,
      icon: ClockIcon,
      color: "amber",
      bgColor: "bg-amber-50",
      iconColor: "text-amber-600",
      borderColor: "border-amber-200",
    },
    {
      title: "تم التوظيف هذا الشهر",
      value: stats.hiredThisMonth,
      icon: CheckCircleIcon,
      color: "emerald",
      bgColor: "bg-emerald-50",
      iconColor: "text-emerald-600",
      borderColor: "border-emerald-200",
    },
    {
      title: "متوسط وقت التوظيف",
      value: `${stats.averageTimeToHire} يوم`,
      icon: ChartBarIcon,
      color: "indigo",
      bgColor: "bg-indigo-50",
      iconColor: "text-indigo-600",
      borderColor: "border-indigo-200",
    },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50 to-purple-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 p-6">
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="mb-8"
      >
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent mb-2">
              إدارة التوظيف
            </h1>
            <p className="text-gray-600 dark:text-gray-400">
              إدارة الوظائف والمتقدمين ومراحل التوظيف
            </p>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 overflow-x-auto pb-2">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-all whitespace-nowrap ${
                  activeTab === tab.id
                    ? "bg-gradient-to-r from-blue-600 to-purple-600 text-white shadow-lg scale-105"
                    : "bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                }`}
              >
                <Icon className="w-5 h-5" />
                {tab.name}
              </button>
            );
          })}
        </div>
      </motion.div>

      {/* Content */}
      {activeTab === "overview" && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="space-y-6"
        >
          {/* Stats Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {statCards.map((card, index) => {
              const Icon = card.icon;
              return (
                <motion.div
                  key={card.title}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.1 }}
                  className={`${card.bgColor} border-2 ${card.borderColor} rounded-2xl p-6 hover:shadow-xl transition-all duration-300 hover:scale-105`}
                >
                  <div className="flex items-center justify-between mb-4">
                    <div
                      className={`p-3 rounded-xl ${card.bgColor} border ${card.borderColor}`}
                    >
                      <Icon className={`w-6 h-6 ${card.iconColor}`} />
                    </div>
                  </div>
                  <h3 className="text-gray-600 dark:text-gray-400 text-sm mb-2">
                    {card.title}
                  </h3>
                  <p className={`text-3xl font-bold ${card.iconColor}`}>
                    {card.value}
                  </p>
                </motion.div>
              );
            })}
          </div>

          {/* Quick Actions */}
          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-lg border-2 border-gray-200 dark:border-gray-700">
            <h2 className="text-xl font-bold text-gray-800 dark:text-white mb-4">
              إجراءات سريعة
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <button
                onClick={() => setActiveTab("jobs")}
                className="flex items-center gap-3 p-4 bg-gradient-to-r from-blue-50 to-blue-100 dark:from-blue-900/20 dark:to-blue-800/20 rounded-xl hover:shadow-md transition-all border-2 border-blue-200 dark:border-blue-700"
              >
                <PlusIcon className="w-6 h-6 text-blue-600" />
                <span className="font-medium text-gray-800 dark:text-white">
                  إضافة وظيفة جديدة
                </span>
              </button>
              <button
                onClick={() => setActiveTab("applicants")}
                className="flex items-center gap-3 p-4 bg-gradient-to-r from-purple-50 to-purple-100 dark:from-purple-900/20 dark:to-purple-800/20 rounded-xl hover:shadow-md transition-all border-2 border-purple-200 dark:border-purple-700"
              >
                <UserGroupIcon className="w-6 h-6 text-purple-600" />
                <span className="font-medium text-gray-800 dark:text-white">
                  عرض المتقدمين
                </span>
              </button>
              <button
                onClick={() => setActiveTab("interviews")}
                className="flex items-center gap-3 p-4 bg-gradient-to-r from-green-50 to-green-100 dark:from-green-900/20 dark:to-green-800/20 rounded-xl hover:shadow-md transition-all border-2 border-green-200 dark:border-green-700"
              >
                <CalendarDaysIcon className="w-6 h-6 text-green-600" />
                <span className="font-medium text-gray-800 dark:text-white">
                  جدولة مقابلة
                </span>
              </button>
              <button
                onClick={() => setActiveTab("pipeline")}
                className="flex items-center gap-3 p-4 bg-gradient-to-r from-amber-50 to-amber-100 dark:from-amber-900/20 dark:to-amber-800/20 rounded-xl hover:shadow-md transition-all border-2 border-amber-200 dark:border-amber-700"
              >
                <ClipboardDocumentCheckIcon className="w-6 h-6 text-amber-600" />
                <span className="font-medium text-gray-800 dark:text-white">
                  تتبع المراحل
                </span>
              </button>
            </div>
          </div>
        </motion.div>
      )}

      {activeTab === "jobs" && <JobPostingsSection />}
      {activeTab === "applicants" && <ApplicantsSection />}
      {activeTab === "interviews" && <InterviewsSection />}
      {activeTab === "pipeline" && <HiringPipelineSection />}
      {activeTab === "forms" && <ApplicationFormsSection />}
    </div>
  );
};

export default RecruitmentDashboard;

import React, { useState, useEffect } from "react";
import {
  UserGroupIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  EnvelopeIcon,
  PhoneIcon,
  DocumentTextIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  EyeIcon,
  StarIcon,
  PlusIcon,
} from "@heroicons/react/24/outline";
import { motion, AnimatePresence } from "framer-motion";
import { companyAwareApi } from "../../../../services/companyAwareApi";
import { toast } from "react-hot-toast";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface Applicant {
  id: string;
  name: string;
  email: string;
  phone: string;
  jobTitle: string;
  jobId: string;
  appliedDate: string;
  status:
    | "NEW"
    | "REVIEWING"
    | "INTERVIEW_SCHEDULED"
    | "INTERVIEWED"
    | "OFFERED"
    | "HIRED"
    | "REJECTED";
  resumeUrl?: string;
  coverLetter?: string;
  experience: number;
  education: string;
  skills: string[];
  rating?: number;
  notes?: string;
}

const ApplicantsSection: React.FC = () => {
  const [applicants, setApplicants] = useState<Applicant[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState<string>("all");
  const [selectedApplicant, setSelectedApplicant] = useState<Applicant | null>(
    null,
  );
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [jobs, setJobs] = useState<any[]>([]);
  const [newApplicant, setNewApplicant] = useState({
    name: "",
    email: "",
    phone: "",
    jobId: "",
    experience: 0,
    education: "",
    skills: "",
    coverLetter: "",
    resumeUrl: "",
  });

  useEffect(() => {
    fetchApplicants();
    fetchJobs();
  }, []);

  const fetchApplicants = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/hr/recruitment/applicants");
      if (response.data.success) {
        setApplicants(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching applicants:", error);
      setApplicants([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchJobs = async () => {
    try {
      const response = await companyAwareApi.get("/hr/recruitment/jobs");
      if (response.data.success) {
        setJobs(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching jobs:", error);
    }
  };

  const handleUpdateStatus = async (applicantId: string, status: string) => {
    try {
      await companyAwareApi.put(
        `/hr/recruitment/applicants/${applicantId}/status`,
        { status },
      );
      toast.success("تم تحديث حالة المتقدم");
      fetchApplicants();
    } catch (error) {
      toast.error("فشل في تحديث الحالة");
    }
  };

  const handleAddApplicant = async () => {
    try {
      if (!newApplicant.name || !newApplicant.email || !newApplicant.jobId) {
        toast.error("يرجى تعبئة الحقول المطلوبة");
        return;
      }

      const payload = {
        ...newApplicant,
        skills: newApplicant.skills
          .split(",")
          .map((s) => s.trim())
          .filter((s) => s),
      };

      const response = await companyAwareApi.post(
        "/hr/recruitment/applicants",
        payload,
      );
      if (response.data.success) {
        toast.success("تم إضافة المتقدم بنجاح 🎉");
        setShowAddModal(false);
        resetAddForm();
        fetchApplicants();
      }
    } catch (error: any) {
      console.error("Error adding applicant:", error);
      toast.error(error.response?.data?.message || "فشل في إضافة المتقدم");
    }
  };

  const resetAddForm = () => {
    setNewApplicant({
      name: "",
      email: "",
      phone: "",
      jobId: "",
      experience: 0,
      education: "",
      skills: "",
      coverLetter: "",
      resumeUrl: "",
    });
  };

  const filteredApplicants = applicants.filter((applicant) => {
    const matchesSearch =
      applicant.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      applicant.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      applicant.jobTitle.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter =
      filterStatus === "all" || applicant.status === filterStatus;
    return matchesSearch && matchesFilter;
  });

  const getStatusBadge = (status: Applicant["status"]) => {
    const badges = {
      NEW: { bg: "bg-blue-100 text-blue-700 border-blue-300", text: "🆕 جديد" },
      REVIEWING: {
        bg: "bg-amber-100 text-amber-700 border-amber-300",
        text: "👀 قيد المراجعة",
      },
      INTERVIEW_SCHEDULED: {
        bg: "bg-purple-100 text-purple-700 border-purple-300",
        text: "📅 مقابلة مجدولة",
      },
      INTERVIEWED: {
        bg: "bg-indigo-100 text-indigo-700 border-indigo-300",
        text: "✅ تمت المقابلة",
      },
      OFFERED: {
        bg: "bg-green-100 text-green-700 border-green-300",
        text: "🎉 تم العرض",
      },
      HIRED: {
        bg: "bg-emerald-100 text-emerald-700 border-emerald-300",
        text: "🎊 تم التوظيف",
      },
      REJECTED: {
        bg: "bg-red-100 text-red-700 border-red-300",
        text: "❌ مرفوض",
      },
    };
    return badges[status];
  };

  return (
    <div className="space-y-6">
      {/* Header with Add Button */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
            المتقدمين
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            إدارة المتقدمين على الوظائف
          </p>
        </div>
        <button
          onClick={() => setShowAddModal(true)}
          className="px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:shadow-lg transition-all flex items-center gap-2 font-semibold"
        >
          <PlusIcon className="w-5 h-5" />
          إضافة متقدم
        </button>
      </div>

      {/* Search and Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-lg border-2 border-gray-200 dark:border-gray-700">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="ابحث عن متقدم..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pr-10 pl-4 py-3 border-2 border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
            />
          </div>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-3 border-2 border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
          >
            <option value="all">جميع الحالات</option>
            <option value="NEW">جديد</option>
            <option value="REVIEWING">قيد المراجعة</option>
            <option value="INTERVIEW_SCHEDULED">مقابلة مجدولة</option>
            <option value="INTERVIEWED">تمت المقابلة</option>
            <option value="OFFERED">تم العرض</option>
            <option value="HIRED">تم التوظيف</option>
            <option value="REJECTED">مرفوض</option>
          </select>
        </div>
      </div>

      {/* Applicants Grid */}
      <div className="grid grid-cols-1 gap-6">
        <AnimatePresence>
          {filteredApplicants.map((applicant, index) => {
            const statusBadge = getStatusBadge(applicant.status);
            return (
              <motion.div
                key={applicant.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ delay: index * 0.1 }}
                className="bg-gradient-to-br from-white to-gray-50 dark:from-gray-800 dark:to-gray-900 rounded-2xl p-6 shadow-lg border-2 border-gray-200 dark:border-gray-700 hover:shadow-2xl hover:scale-[1.02] transition-all duration-300"
              >
                {/* Header */}
                <div className="flex items-start justify-between mb-5">
                  <div className="flex items-center gap-3 flex-1">
                    <div className="w-14 h-14 rounded-full bg-gradient-to-br from-purple-500 to-blue-600 flex items-center justify-center text-white font-bold text-xl shadow-lg">
                      {applicant.name.charAt(0).toUpperCase()}
                    </div>
                    <div className="flex-1">
                      <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-1">
                        {applicant.name}
                      </h3>
                      <p className="text-sm text-gray-600 dark:text-gray-400 font-medium flex items-center gap-1">
                        <DocumentTextIcon className="w-4 h-4" />
                        {applicant.jobTitle}
                      </p>
                    </div>
                  </div>
                  <span
                    className={`px-4 py-2 rounded-xl text-xs font-bold border-2 shadow-sm ${statusBadge.bg}`}
                  >
                    {statusBadge.text}
                  </span>
                </div>

                {/* Contact Info */}
                <div className="grid grid-cols-1 gap-3 mb-5">
                  <div className="flex items-center gap-3 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-100 dark:border-blue-800">
                    <div className="w-8 h-8 rounded-lg bg-blue-500 flex items-center justify-center">
                      <EnvelopeIcon className="w-4 h-4 text-white" />
                    </div>
                    <span className="text-sm text-gray-700 dark:text-gray-300 font-medium truncate">
                      {applicant.email}
                    </span>
                  </div>
                  <div className="flex items-center gap-3 p-3 bg-green-50 dark:bg-green-900/20 rounded-xl border border-green-100 dark:border-green-800">
                    <div className="w-8 h-8 rounded-lg bg-green-500 flex items-center justify-center">
                      <PhoneIcon className="w-4 h-4 text-white" />
                    </div>
                    <span className="text-sm text-gray-700 dark:text-gray-300 font-medium">
                      {applicant.phone}
                    </span>
                  </div>
                </div>

                {/* Details */}
                <div className="grid grid-cols-2 gap-3 mb-5">
                  <div className="p-4 bg-gradient-to-br from-purple-50 to-purple-100 dark:from-purple-900/30 dark:to-purple-800/20 rounded-xl border border-purple-200 dark:border-purple-700">
                    <div className="text-xs text-purple-600 dark:text-purple-400 font-semibold mb-1">
                      الخبرة
                    </div>
                    <div className="text-2xl font-bold text-purple-700 dark:text-purple-300">
                      {applicant.experience}
                    </div>
                    <div className="text-xs text-purple-600 dark:text-purple-400">
                      سنوات
                    </div>
                  </div>
                  <div className="p-4 bg-gradient-to-br from-indigo-50 to-indigo-100 dark:from-indigo-900/30 dark:to-indigo-800/20 rounded-xl border border-indigo-200 dark:border-indigo-700">
                    <div className="text-xs text-indigo-600 dark:text-indigo-400 font-semibold mb-1">
                      التعليم
                    </div>
                    <div className="text-sm font-bold text-indigo-700 dark:text-indigo-300 truncate">
                      {applicant.education || "غير محدد"}
                    </div>
                  </div>
                  {applicant.rating && (
                    <div className="col-span-2 p-3 bg-gradient-to-r from-yellow-50 to-orange-50 dark:from-yellow-900/20 dark:to-orange-900/20 rounded-xl border border-yellow-200 dark:border-yellow-700">
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-yellow-700 dark:text-yellow-400 font-semibold">
                          التقييم
                        </span>
                        <div className="flex items-center gap-1">
                          {[...Array(5)].map((_, i) => (
                            <StarIcon
                              key={i}
                              className={`w-5 h-5 ${i < applicant.rating! ? "text-yellow-500 fill-yellow-500" : "text-gray-300 dark:text-gray-600"}`}
                            />
                          ))}
                        </div>
                      </div>
                    </div>
                  )}
                </div>

                {/* Skills */}
                <div className="mb-5">
                  <div className="text-xs font-bold text-gray-600 dark:text-gray-400 mb-2 flex items-center gap-1">
                    <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
                    المهارات
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {(Array.isArray(applicant.skills)
                      ? applicant.skills
                      : typeof applicant.skills === "string"
                        ? (applicant.skills as string).split(",")
                        : []
                    )
                      .slice(0, 4)
                      .map((skill, idx) => (
                        <span
                          key={idx}
                          className="px-3 py-1.5 bg-gradient-to-r from-blue-500 to-purple-500 text-white text-xs font-semibold rounded-lg shadow-sm"
                        >
                          {skill.trim()}
                        </span>
                      ))}
                    {(Array.isArray(applicant.skills)
                      ? applicant.skills
                      : typeof applicant.skills === "string"
                        ? (applicant.skills as string).split(",")
                        : []
                    ).length > 4 && (
                      <span className="px-3 py-1.5 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 text-xs font-bold rounded-lg">
                        +
                        {(Array.isArray(applicant.skills)
                          ? applicant.skills
                          : typeof applicant.skills === "string"
                            ? (applicant.skills as string).split(",")
                            : []
                        ).length - 4}
                      </span>
                    )}
                  </div>
                </div>

                {/* Actions */}
                <div className="flex gap-3 pt-5 border-t-2 border-gray-200 dark:border-gray-700">
                  <button
                    onClick={() => {
                      setSelectedApplicant(applicant);
                      setShowDetailsModal(true);
                    }}
                    className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:shadow-lg hover:scale-105 transition-all font-semibold"
                  >
                    <EyeIcon className="w-5 h-5" />
                    عرض التفاصيل
                  </button>
                  {applicant.status === "NEW" && (
                    <button
                      onClick={() =>
                        handleUpdateStatus(applicant.id, "REVIEWING")
                      }
                      className="px-4 py-2 bg-amber-50 dark:bg-amber-900/20 text-amber-600 rounded-lg hover:bg-amber-100 transition-all"
                    >
                      <ClockIcon className="w-5 h-5" />
                    </button>
                  )}
                  {applicant.status === "REVIEWING" && (
                    <>
                      <button
                        onClick={() =>
                          handleUpdateStatus(
                            applicant.id,
                            "INTERVIEW_SCHEDULED",
                          )
                        }
                        className="px-4 py-2 bg-green-50 dark:bg-green-900/20 text-green-600 rounded-lg hover:bg-green-100 transition-all"
                      >
                        <CheckCircleIcon className="w-5 h-5" />
                      </button>
                      <button
                        onClick={() =>
                          handleUpdateStatus(applicant.id, "REJECTED")
