            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default ApplicationFormsSection;

import React, { useEffect, useState } from "react";
import {
  ArrowLeftIcon,
  BriefcaseIcon,
  CheckCircleIcon,
  ClipboardDocumentCheckIcon,
  UserGroupIcon,
  XCircleIcon,
} from "@heroicons/react/24/outline";
import { motion } from "framer-motion";
import { format } from "date-fns";
import { ar } from "date-fns/locale";
import { companyAwareApi } from "../../../../services/companyAwareApi";
import { toast } from "react-hot-toast";

interface PipelineStage {
  id: string;
  name: string;
  count: number;
  color: string;
}

interface StageApplicant {
  id: string;
  name: string;
  email: string;
  phone?: string;
  status: string;
  createdAt?: string;
  jobTitle?: string;
  job?: {
    title?: string;
  };
}

const DEFAULT_PIPELINE_STAGES: PipelineStage[] = [
  { id: "NEW", name: "جديد", count: 0, color: "blue" },
  { id: "REVIEWING", name: "قيد المراجعة", count: 0, color: "amber" },
  {
    id: "INTERVIEW_SCHEDULED",
    name: "مقابلة مجدولة",
    count: 0,
    color: "purple",
  },
  { id: "INTERVIEWED", name: "تمت المقابلة", count: 0, color: "indigo" },
  { id: "OFFERED", name: "تم العرض", count: 0, color: "green" },
  { id: "HIRED", name: "تم التوظيف", count: 0, color: "emerald" },
  { id: "REJECTED", name: "مرفوض", count: 0, color: "red" },
];

const HiringPipelineSection: React.FC = () => {
  const [stages, setStages] = useState<PipelineStage[]>(DEFAULT_PIPELINE_STAGES);
  const [selectedStageId, setSelectedStageId] = useState("NEW");
  const [stageApplicants, setStageApplicants] = useState<StageApplicant[]>([]);
  const [loading, setLoading] = useState(true);
  const [stageApplicantsLoading, setStageApplicantsLoading] = useState(false);

  useEffect(() => {
    fetchPipelineStats();
  }, []);

  useEffect(() => {
    if (selectedStageId) {
      fetchStageApplicants(selectedStageId);
    }
  }, [selectedStageId]);

  const fetchPipelineStats = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get(
        "/hr/recruitment/pipeline-stats",
      );

      if (response.data.success) {
        const incomingStages = Array.isArray(response.data.data)
          ? response.data.data
          : [];

        const normalizedStages = DEFAULT_PIPELINE_STAGES.map((defaultStage) => {
          const matchingStage = incomingStages.find(
            (stage: PipelineStage) => stage.id === defaultStage.id,
          );

          return matchingStage
            ? { ...defaultStage, ...matchingStage }
            : defaultStage;
        });

        setStages(normalizedStages);
        setSelectedStageId((currentStageId) => {
          if (normalizedStages.some((stage) => stage.id === currentStageId)) {
            return currentStageId;
          }

          return normalizedStages.find((stage) => stage.count > 0)?.id || "NEW";
        });
      }
    } catch (error) {
      console.error("Error fetching pipeline stats:", error);
      setStages(DEFAULT_PIPELINE_STAGES);
    } finally {
      setLoading(false);
    }
  };

  const fetchStageApplicants = async (status: string) => {
    try {
      setStageApplicantsLoading(true);
      const response = await companyAwareApi.get("/hr/recruitment/applicants", {
        params: { status, limit: 6 },
      });

      if (response.data.success) {
        setStageApplicants(response.data.data || []);
      } else {
        setStageApplicants([]);
      }
    } catch (error) {
      console.error("Error fetching stage applicants:", error);
      setStageApplicants([]);
    } finally {
      setStageApplicantsLoading(false);
    }
  };

  const handleUpdateStatus = async (applicantId: string, newStatus: string) => {
    try {
      setStageApplicantsLoading(true);
      const response = await companyAwareApi.put(
        `/hr/recruitment/applicants/${applicantId}/status`,
        { status: newStatus }
      );
      if (response.data.success) {
        toast.success("تم نقل المتقدم للمرحلة المحددة بنجاح");
        fetchPipelineStats();
        // Refresh applicants for the currently selected stage
        fetchStageApplicants(selectedStageId);
      } else {
        toast.error("فشل في نقل المتقدم");
        setStageApplicantsLoading(false);
      }
    } catch (error: any) {
      console.error("Error updating status:", error);
      toast.error(error.response?.data?.message || "حدث خطأ أثناء نقل المتقدم");
      setStageApplicantsLoading(false);
    }
  };

  const getColorClasses = (color: string) => {
    const colors: Record<string, string> = {
      blue: "bg-blue-100 border-blue-300 text-blue-700",
      amber: "bg-amber-100 border-amber-300 text-amber-700",
      purple: "bg-purple-100 border-purple-300 text-purple-700",
      indigo: "bg-indigo-100 border-indigo-300 text-indigo-700",
      green: "bg-green-100 border-green-300 text-green-700",
      emerald: "bg-emerald-100 border-emerald-300 text-emerald-700",
      red: "bg-red-100 border-red-300 text-red-700",
    };

    return colors[color] || colors.blue;
  };

  const totalApplicants = stages.reduce((sum, stage) => sum + stage.count, 0);
  const newApplicants = stages.find((stage) => stage.id === "NEW")?.count || 0;
  const hiredApplicants =
    stages.find((stage) => stage.id === "HIRED")?.count || 0;
  const inInterviewStages = stages
    .filter((stage) =>
      ["INTERVIEW_SCHEDULED", "INTERVIEWED"].includes(stage.id),
    )
    .reduce((sum, stage) => sum + stage.count, 0);
  const activePipelineApplicants = stages
    .filter((stage) => !["HIRED", "REJECTED"].includes(stage.id))
    .reduce((sum, stage) => sum + stage.count, 0);
  const conversionRate =
    newApplicants > 0 ? Math.round((hiredApplicants / newApplicants) * 100) : 0;
  const selectedStage =
    stages.find((stage) => stage.id === selectedStageId) || stages[0];

  return (
    <div className="space-y-6">
      <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-lg border-2 border-gray-200 dark:border-gray-700">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
          <ClipboardDocumentCheckIcon className="w-8 h-8 text-blue-600" />
          مسار التوظيف
        </h2>

        {loading ? (
          <div className="flex items-center justify-center py-16">
            <div className="w-12 h-12 rounded-full border-4 border-blue-200 border-t-blue-600 animate-spin" />
          </div>
        ) : totalApplicants === 0 ? (
          <div className="rounded-2xl border-2 border-dashed border-gray-300 dark:border-gray-600 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-gray-800 dark:to-gray-900 p-8 text-center">
            <ClipboardDocumentCheckIcon className="w-16 h-16 mx-auto text-blue-500 mb-4" />
            <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
              المسار جاهز لكن لا يوجد متقدمون بعد
            </h3>
            <p className="text-gray-600 dark:text-gray-400 max-w-2xl mx-auto leading-7">
              المتقدمون يظهرون هنا بعد إضافتهم من تبويب المتقدمين، أو تلقائيًا من
              ردود استبيانات التقديم إذا كان الاستبيان مربوطًا بوظيفة.
            </p>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-6 text-right">
              <div className="p-4 rounded-xl bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800">
                <p className="text-sm text-blue-700 dark:text-blue-300 font-semibold">
                  1. أنشئ وظيفة
                </p>
                <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                  اربطي الاستبيان بوظيفة واضحة.
                </p>
              </div>
              <div className="p-4 rounded-xl bg-purple-50 dark:bg-purple-900/20 border border-purple-200 dark:border-purple-800">
                <p className="text-sm text-purple-700 dark:text-purple-300 font-semibold">
                  2. اجمعي التقديمات
                </p>
                <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                  الردود المربوطة بوظيفة يمكن إدخالها للمسار.
                </p>
              </div>
              <div className="p-4 rounded-xl bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800">
                <p className="text-sm text-emerald-700 dark:text-emerald-300 font-semibold">
                  3. تابعي المراحل
                </p>
                <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                  بعدها ستظهر كل مرحلة وعدد المرشحين فيها.
                </p>
              </div>
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="overflow-x-auto pb-2">
              <div className="flex items-stretch gap-4 min-w-max">
                {stages.map((stage, index) => (
                  <React.Fragment key={stage.id}>
                    <motion.button
                      type="button"
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: index * 0.08 }}
                      onClick={() => setSelectedStageId(stage.id)}
                      className={`relative min-w-[220px] p-5 rounded-2xl border-2 text-right transition-all ${getColorClasses(
                        stage.color,
                      )} ${
                        selectedStageId === stage.id
                          ? "shadow-xl ring-2 ring-blue-500 ring-offset-2 scale-[1.02]"
                          : "hover:shadow-lg"
                      }`}
                    >
                      <div className="flex items-center justify-between gap-4 mb-4">
                        <div>
                          <p className="text-xs font-medium opacity-70 mb-1">
                            المرحلة
                          </p>
                          <h3 className="font-bold text-lg">{stage.name}</h3>
                        </div>
                        <div className="w-14 h-14 rounded-full bg-white dark:bg-gray-800 flex items-center justify-center font-bold text-xl shadow-sm">
                          {stage.count}
                        </div>
                      </div>
                      <div className="flex items-center justify-between text-sm">
                        <span className="flex items-center gap-2">
                          <UserGroupIcon className="w-4 h-4" />
                          {stage.count} متقدم
                        </span>
                        <span className="font-semibold">
                          {Math.round((stage.count / totalApplicants) * 100)}%
                        </span>
                      </div>
                    </motion.button>
                    {index < stages.length - 1 && (
                      <div className="hidden xl:flex items-center justify-center">
                        <ArrowLeftIcon className="w-6 h-6 text-gray-400" />
                      </div>
                    )}
                  </React.Fragment>
                ))}
              </div>
            </div>

            <div className="rounded-2xl border-2 border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/30 p-5">
              <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-5">
                <div>
                  <h3 className="text-xl font-bold text-gray-800 dark:text-white">
                    تفاصيل مرحلة: {selectedStage?.name}
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                    آخر المتقدمين الموجودين حاليًا داخل هذه المرحلة
                  </p>
                </div>
                <div
                  className={`px-4 py-2 rounded-xl border text-sm font-semibold w-fit ${getColorClasses(
                    selectedStage?.color || "blue",
                  )}`}
                >
                  {selectedStage?.count || 0} متقدم
                </div>
              </div>

              {stageApplicantsLoading ? (
                <div className="flex items-center justify-center py-10">
                  <div className="w-10 h-10 rounded-full border-4 border-blue-200 border-t-blue-600 animate-spin" />
                </div>
              ) : stageApplicants.length === 0 ? (
                <div className="rounded-xl bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 p-6 text-center">
                  <p className="text-gray-600 dark:text-gray-400">
                    لا يوجد متقدمون ظاهرون داخل مرحلة {selectedStage?.name} حاليًا.
                  </p>
                </div>
              ) : (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                  {stageApplicants.map((applicant) => (
                    <div
                      key={applicant.id}
                      className="rounded-xl bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 p-4 shadow-sm"
                    >
                      <div className="flex items-start justify-between gap-4">
                        <div>
                          <h4 className="font-bold text-gray-800 dark:text-white">
                            {applicant.name}
                          </h4>
                          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                            {applicant.email}
                          </p>
                          {applicant.phone && (
                            <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                              {applicant.phone}
                            </p>
                          )}
                        </div>
                        <select
                          value={applicant.status}
                          onChange={(e) => handleUpdateStatus(applicant.id, e.target.value)}
                          className={`text-xs font-semibold rounded-lg px-2 py-1.5 cursor-pointer outline-none border hover:shadow-md transition-all focus:ring-2 focus:ring-blue-500 ${getColorClasses(
                            selectedStage?.color || "blue",
                          )}`}
                          title="تغيير المرحلة"
                        >
                          {DEFAULT_PIPELINE_STAGES.map((t_stage) => (
                            <option
                              key={t_stage.id}
                              value={t_stage.id}
                              className="bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-200"
                            >
                              {t_stage.name}
                            </option>
                          ))}
                        </select>
                      </div>

                      <div className="flex flex-wrap items-center gap-3 mt-4 text-sm text-gray-600 dark:text-gray-400">
                        <span className="inline-flex items-center gap-1">
                          <BriefcaseIcon className="w-4 h-4" />
                          {applicant.jobTitle ||
                            applicant.job?.title ||
                            "بدون وظيفة"}
                        </span>
                        {applicant.createdAt && (
                          <span>
                            {format(new Date(applicant.createdAt), "dd MMM yyyy", {
                              locale: ar,
                            })}
                          </span>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-lg border-2 border-gray-200 dark:border-gray-700">
        <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-4">
          إحصائيات المسار
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-4">
          <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-xl border-2 border-blue-200">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              إجمالي المتقدمين
            </p>
            <p className="text-3xl font-bold text-blue-600">{totalApplicants}</p>
          </div>
          <div className="p-4 bg-slate-50 dark:bg-slate-900/20 rounded-xl border-2 border-slate-200">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              داخل المسار الآن
            </p>
            <p className="text-3xl font-bold text-slate-700 dark:text-slate-200">
              {activePipelineApplicants}
            </p>
          </div>
          <div className="p-4 bg-purple-50 dark:bg-purple-900/20 rounded-xl border-2 border-purple-200">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              في المقابلات
            </p>
            <p className="text-3xl font-bold text-purple-600">
              {inInterviewStages}
            </p>
          </div>
          <div className="p-4 bg-emerald-50 dark:bg-emerald-900/20 rounded-xl border-2 border-emerald-200">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              تم التوظيف
            </p>
            <p className="text-3xl font-bold text-emerald-600 flex items-center gap-2">
              <CheckCircleIcon className="w-7 h-7" />
              {hiredApplicants}
            </p>
          </div>
          <div className="p-4 bg-red-50 dark:bg-red-900/20 rounded-xl border-2 border-red-200">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              معدل التحويل من جديد إلى توظيف
            </p>
            <p className="text-3xl font-bold text-red-600 flex items-center gap-2">
              <XCircleIcon className="w-7 h-7" />
              {conversionRate}%
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HiringPipelineSection;

import React, { useState, useEffect } from "react";
import {
  CalendarDaysIcon,
  ClockIcon,
  UserIcon,
  VideoCameraIcon,
  MapPinIcon,
  PlusIcon,
  CheckCircleIcon,
  XCircleIcon,
  PhoneIcon,
  BuildingOfficeIcon,
  XMarkIcon,
  PencilIcon,
  TrashIcon,
} from "@heroicons/react/24/outline";
import { motion, AnimatePresence } from "framer-motion";
import { companyAwareApi } from "../../../../services/companyAwareApi";
import { toast } from "react-hot-toast";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface Interview {
  id: string;
  applicantName: string;
  applicantId: string;
  jobTitle: string;
  jobId: string;
  date: string;
  time: string;
  type: "IN_PERSON" | "VIDEO" | "PHONE";
  location?: string;
  interviewers: string[];
  status: "SCHEDULED" | "COMPLETED" | "CANCELLED" | "NO_SHOW";
  notes?: string;
}

interface Applicant {
  id: string;
  name: string;
  email: string;
  phone: string;
  jobId: string;
  jobTitle?: string;
}

interface Job {
  id: string;
  title: string;
  department: string;
}

const InterviewsSection: React.FC = () => {
  const [interviews, setInterviews] = useState<Interview[]>([]);
  const [applicants, setApplicants] = useState<Applicant[]>([]);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [loading, setLoading] = useState(true);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [editingInterview, setEditingInterview] = useState<Interview | null>(
    null,
  );

  const [newInterview, setNewInterview] = useState({
    applicantId: "",
    jobId: "",
    date: "",
    time: "",
    type: "VIDEO" as const,
    location: "",
    interviewers: [] as string[],
    notes: "",
  });

  const [interviewerInput, setInterviewerInput] = useState("");

  useEffect(() => {
    fetchInterviews();
    fetchApplicants();
    fetchJobs();
  }, []);

  const fetchInterviews = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/hr/recruitment/interviews");
      if (response.data.success) {
        setInterviews(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching interviews:", error);
      toast.error("فشل في جلب المقابلات");
    } finally {
      setLoading(false);
    }
  };

  const fetchApplicants = async () => {
    try {
      const response = await companyAwareApi.get("/hr/recruitment/applicants");
      if (response.data.success) {
        setApplicants(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching applicants:", error);
    }
  };

  const fetchJobs = async () => {
    try {
      const response = await companyAwareApi.get("/hr/recruitment/jobs");
      if (response.data.success) {
        setJobs(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching jobs:", error);
    }
  };

  const handleScheduleInterview = async () => {
    try {
      if (
        !newInterview.applicantId ||
        !newInterview.jobId ||
        !newInterview.date ||
        !newInterview.time
      ) {
        toast.error("يرجى تعبئة جميع الحقول المطلوبة");
        return;
      }

      const payload = {
        ...newInterview,
        interviewers: newInterview.interviewers, // Send as array, backend handles it
      };

      const response = await companyAwareApi.post(
        "/hr/recruitment/interviews",
        payload,
      );

      if (response.data.success) {
        toast.success("تم جدولة المقابلة بنجاح 🎉");
        setShowScheduleModal(false);
        resetForm();
        fetchInterviews();
      }
    } catch (error: any) {
      console.error("Error scheduling interview:", error);
      toast.error(error.response?.data?.message || "فشل في جدولة المقابلة");
    }
  };

  const handleUpdateStatus = async (id: string, status: string) => {
    try {
      const response = await companyAwareApi.put(
        `/hr/recruitment/interviews/${id}/status`,
        { status },
      );
      if (response.data.success) {
        toast.success("تم تحديث الحالة بنجاح");
        fetchInterviews();
      }
    } catch (error) {
      console.error("Error updating status:", error);
      toast.error("فشل تحديث الحالة");
    }
  };

  const resetForm = () => {
    setNewInterview({
      applicantId: "",
      jobId: "",
      date: "",
      time: "",
      type: "VIDEO",
      location: "",
      interviewers: [],
      notes: "",
    });
    setInterviewerInput("");
  };

  const addInterviewer = () => {
    if (interviewerInput.trim()) {
      setNewInterview({
        ...newInterview,
        interviewers: [...newInterview.interviewers, interviewerInput.trim()],
      });
      setInterviewerInput("");
    }
  };

  const removeInterviewer = (index: number) => {
    const updated = [...newInterview.interviewers];
    updated.splice(index, 1);
    setNewInterview({ ...newInterview, interviewers: updated });
  };

  const getApplicantsForJob = () => {
    if (!newInterview.jobId) return [];
    return applicants.filter((app) => app.jobId === newInterview.jobId);
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "SCHEDULED":
        return {
          text: "مجدولة",
          bg: "bg-blue-100 text-blue-700 border-blue-200",
        };
      case "COMPLETED":
        return {
          text: "مكتملة",
          bg: "bg-green-100 text-green-700 border-green-200",
        };
      case "CANCELLED":
        return { text: "ملغاة", bg: "bg-red-100 text-red-700 border-red-200" };
      case "NO_SHOW":
        return {
          text: "لم يحضر",
          bg: "bg-gray-100 text-gray-700 border-gray-200",
        };
      default:
        return { text: status, bg: "bg-gray-100 text-gray-700" };
    }
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case "VIDEO":
        return <VideoCameraIcon className="w-5 h-5 text-purple-500" />;
      case "PHONE":
        return <PhoneIcon className="w-5 h-5 text-green-500" />;
      case "IN_PERSON":
        return <BuildingOfficeIcon className="w-5 h-5 text-blue-500" />;
      default:
        return <ClockIcon className="w-5 h-5" />;
    }
  };

  const getTypeText = (type: string) => {
    switch (type) {
      case "VIDEO":
        return "مكالمة فيديو";
      case "PHONE":
        return "مكالمة هاتفية";
      case "IN_PERSON":
        return "في الشركة";
      default:
        return type;
    }
  };

  return (
    <div className="relative min-h-screen p-6 -m-6 overflow-hidden">
      {/* الخلفية المميزة - Decorative Background */}
      <div className="absolute inset-0 bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 -z-20" />
      <div className="absolute top-0 left-0 w-full h-96 bg-gradient-to-r from-violet-500/10 to-fuchsia-500/10 blur-3xl -z-10" />
      <div className="absolute bottom-0 right-0 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl -z-10" />

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4 relative z-10">
        <div>
          <h2 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-violet-600 to-fuchsia-600 dark:from-violet-400 dark:to-fuchsia-400">
            مساحة المقابلات
          </h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1 flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            إدارة جداول المقابلات والمواعيد بذكاء
          </p>
        </div>

        <button
          onClick={() => setShowScheduleModal(true)}
          className="group relative px-8 py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-2xl font-bold shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all duration-300 overflow-hidden"
        >
          <div className="absolute inset-0 bg-gradient-to-r from-violet-600 to-fuchsia-600 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
          <div className="relative flex items-center gap-2">
            <PlusIcon className="w-5 h-5 group-hover:rotate-90 transition-transform duration-300" />
            <span>جدولة مقابلة جديدة</span>
          </div>
        </button>
      </div>

      {/* Schedule Interview Modal */}
      <AnimatePresence>
        {showScheduleModal && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-md flex items-center justify-center z-50 p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.9, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-xl rounded-3xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-y-auto border border-white/20 scrollbar-hide"
            >
              <div className="sticky top-0 bg-white/80 dark:bg-gray-800/80 backdrop-blur-md p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center z-10">
                <div>
                  <h3 className="text-2xl font-bold text-gray-800 dark:text-white">
                    جدولة موعد
                  </h3>
                  <p className="text-sm text-gray-500">
                    قم بتنظيم مقابلة جديدة بسلاسة
                  </p>
                </div>
                <button
                  onClick={() => {
                    setShowScheduleModal(false);
                    resetForm();
                  }}
                  className="p-2 bg-gray-100 dark:bg-gray-700 rounded-full hover:bg-red-50 hover:text-red-500 transition-colors"
                >
                  <XMarkIcon className="w-6 h-6" />
                </button>
              </div>

              <div className="p-8 space-y-8">
                {/* Job & Applicant Selection */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-gray-700 dark:text-gray-300 ml-1">
                      الوظيفة المطلوبة
                    </label>
                    <select
                      value={newInterview.jobId}
                      onChange={(e) =>
                        setNewInterview({
                          ...newInterview,
                          jobId: e.target.value,
                          applicantId: "",
                        })
                      }
                      className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-700/50 border-2 border-transparent focus:border-violet-500 rounded-xl outline-none transition-all hover:bg-white dark:hover:bg-gray-700"
                    >
                      <option value="">اختر الوظيفة...</option>
                      {jobs.map((job) => (
                        <option key={job.id} value={job.id}>
                          {job.title}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-gray-700 dark:text-gray-300 ml-1">
                      المرشح للمقابلة
                    </label>
                    {!newInterview.jobId ? (
                      <div className="w-full px-4 py-3 bg-yellow-50 dark:bg-yellow-900/20 border-2 border-yellow-200 dark:border-yellow-700 rounded-xl">
                        <p className="text-sm text-yellow-700 dark:text-yellow-400">
                          ⚠️ اختر الوظيفة أولاً لعرض المتقدمين
                        </p>
                      </div>
                    ) : getApplicantsForJob().length === 0 ? (
                      <div className="w-full px-4 py-3 bg-orange-50 dark:bg-orange-900/20 border-2 border-orange-200 dark:border-orange-700 rounded-xl">
                        <p className="text-sm text-orange-700 dark:text-orange-400">
                          📋 لا توجد متقدمين لهذه الوظيفة
                        </p>
                      </div>
                    ) : (
                      <select
                        value={newInterview.applicantId}
                        onChange={(e) =>
                          setNewInterview({
                            ...newInterview,
                            applicantId: e.target.value,
                          })
                        }
                        className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-700/50 border-2 border-transparent focus:border-violet-500 rounded-xl outline-none transition-all hover:bg-white dark:hover:bg-gray-700"
                      >
                        <option value="">اختر المتقدم...</option>
                        {getApplicantsForJob().map((applicant) => (
                          <option key={applicant.id} value={applicant.id}>
                            {applicant.name}
                          </option>
                        ))}
                      </select>
                    )}
                  </div>
                </div>

                {/* Date & Type */}
                <div className="p-6 bg-gray-50 dark:bg-gray-700/30 rounded-2xl space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                        تاريخ ووقت المقابلة
                      </label>
                      <div className="flex gap-2">
                        <input
                          type="date"
                          value={newInterview.date}
                          onChange={(e) =>
                            setNewInterview({
                              ...newInterview,
                              date: e.target.value,
                            })
                          }
                          min={new Date().toISOString().split("T")[0]}
                          className="flex-1 px-4 py-3 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-600 focus:border-violet-500 outline-none"
                        />
                        <input
                          type="time"
                          value={newInterview.time}
                          onChange={(e) =>
                            setNewInterview({
                              ...newInterview,
                              time: e.target.value,
                            })
                          }
                          className="w-32 px-4 py-3 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-600 focus:border-violet-500 outline-none"
                        />
                      </div>
                    </div>

                    <div>
                      <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                        نوع المقابلة
                      </label>
                      <div className="flex gap-2">
                        {[
                          {
                            value: "VIDEO",
                            icon: VideoCameraIcon,
                            label: "فيديو",
                          },
                          {
                            value: "IN_PERSON",
                            icon: BuildingOfficeIcon,
                            label: "مقر الشركة",
                          },
                          { value: "PHONE", icon: PhoneIcon, label: "هاتف" },
                        ].map(({ value, icon: Icon, label }) => (
                          <button
                            key={value}
                            type="button"
                            onClick={() =>
                              setNewInterview({
                                ...newInterview,
                                type: value as any,
                              })
                            }
                            className={`flex-1 flex flex-col items-center justify-center gap-1 p-2 rounded-xl border-2 transition-all ${
                              newInterview.type === value
                                ? "border-violet-500 bg-violet-50 dark:bg-violet-900/20 text-violet-700"
                                : "border-transparent bg-white dark:bg-gray-800 text-gray-500 hover:bg-gray-100"
                            }`}
                          >
                            <Icon className="w-5 h-5" />
                            <span className="text-xs font-medium">{label}</span>
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>

                  {/* Dynamic Location/Link Input */}
                  <div className="relative">
                    <div className="absolute inset-y-0 right-0 flex items-center pr-4 pointer-events-none">
                      {newInterview.type === "VIDEO" ? (
                        <VideoCameraIcon className="h-5 w-5 text-gray-400" />
                      ) : newInterview.type === "PHONE" ? (
                        <PhoneIcon className="h-5 w-5 text-gray-400" />
                      ) : (
                        <MapPinIcon className="h-5 w-5 text-gray-400" />
                      )}
                    </div>
                    <input
                      type="text"
                      value={newInterview.location}
                      onChange={(e) =>
                        setNewInterview({
                          ...newInterview,
                          location: e.target.value,
                        })
                      }
                      placeholder={
                        newInterview.type === "VIDEO"
                          ? "ضع رابط الاجتماع (Zoom/Meet)..."
                          : newInterview.type === "PHONE"
                            ? "رقم الهاتف للتواصل..."
                            : "رقم القاعة / الطابق / الفرع..."
                      }
                      className="w-full pr-11 pl-4 py-3 bg-white dark:bg-gray-800 border-none rounded-xl shadow-sm ring-1 ring-gray-200 dark:ring-gray-700 focus:ring-2 focus:ring-violet-500 transition-all"
                    />
                  </div>
                </div>

                {/* Interviewers & Notes */}
                <div className="space-y-6">
                  <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700">
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                      لجنة المقابلة
                    </label>
                    <div className="flex gap-2 mb-3">
                      <input
                        type="text"
                        value={interviewerInput}
                        onChange={(e) => setInterviewerInput(e.target.value)}
                        onKeyPress={(e) =>
                          e.key === "Enter" &&
                          (e.preventDefault(), addInterviewer())
                        }
                        placeholder="اكتب الاسم واضغط إضافة..."
                        className="flex-1 bg-transparent border-b-2 border-gray-200 dark:border-gray-700 focus:border-violet-500 px-2 py-2 outline-none transition-colors"
                      />
                      <button
                        type="button"
                        onClick={addInterviewer}
                        className="px-4 py-2 bg-violet-100 text-violet-700 rounded-lg hover:bg-violet-200 transition-colors font-medium text-sm"
                      >
                        + إضافة
                      </button>
                    </div>
                    <div className="flex flex-wrap gap-2 min-h-[40px]">
                      {newInterview.interviewers.length === 0 && (
                        <p className="text-gray-400 text-sm italic py-2">
                          لم يتم إضافة أعضاء بعد...
                        </p>
                      )}
                      {newInterview.interviewers.map((interviewer, idx) => (
                        <motion.span
                          key={idx}
                          initial={{ scale: 0 }}
                          animate={{ scale: 1 }}
                          className="flex items-center gap-2 px-3 py-1.5 bg-gradient-to-r from-violet-50 to-fuchsia-50 dark:from-violet-900/30 dark:to-fuchsia-900/30 text-violet-700 dark:text-violet-300 rounded-full border border-violet-100 dark:border-violet-800 text-sm font-medium pr-3 pl-1"
                        >
                          {interviewer}
                          <button
                            type="button"
                            onClick={() => removeInterviewer(idx)}
                            className="p-0.5 hover:bg-white/50 rounded-full transition-colors text-violet-500"
                          >
                            <XMarkIcon className="w-4 h-4" />
                          </button>
                        </motion.span>
                      ))}
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      ملاحظات إضافية
                    </label>
                    <textarea
                      value={newInterview.notes}
                      onChange={(e) =>
                        setNewInterview({
                          ...newInterview,
                          notes: e.target.value,
                        })
                      }
                      rows={2}
                      className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-700/50 border-none rounded-xl focus:ring-2 focus:ring-violet-500 resize-none transition-all"
                      placeholder="تعليمات خاصة، متطلبات للمقابلة، إلخ..."
                    />
                  </div>
                </div>

                {/* Footer Actions */}
                <div className="flex gap-4 pt-6 border-t border-gray-100 dark:border-gray-700">
                  <button
                    onClick={handleScheduleInterview}
                    className="flex-1 py-4 bg-gradient-to-r from-gray-900 to-gray-800 dark:from-white dark:to-gray-200 text-white dark:text-gray-900 rounded-xl font-bold hover:shadow-lg hover:-translate-y-0.5 transition-all text-lg"
                  >
                    تأكيد الجدولة 📅
                  </button>
                  <button
                    onClick={() => {
                      setShowScheduleModal(false);
                      resetForm();
                    }}
                    className="px-8 py-4 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-semibold hover:bg-gray-200 transition-all"
                  >
                    إلغاء
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Interviews Grid - Modern Glass Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 relative z-10">
        {interviews.map((interview, index) => {
          const statusBadge = getStatusBadge(interview.status);
          return (
            <motion.div
              key={interview.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
              className="group relative bg-white/70 dark:bg-gray-800/60 backdrop-blur-xl rounded-[2rem] p-6 border border-white/40 dark:border-gray-700/50 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 dark:hover:bg-gray-800/80"
            >
              {/* Decorative Gradient Blob on Hover */}
              <div className="absolute inset-0 bg-gradient-to-br from-violet-500/5 to-fuchsia-500/5 rounded-[2rem] opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none" />

              <div className="relative">
                {/* Header */}
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-violet-100 to-white dark:from-violet-900/50 dark:to-gray-800 flex items-center justify-center shadow-inner border border-white/50 dark:border-gray-700">
                      <UserIcon className="w-6 h-6 text-violet-600 dark:text-violet-400" />
                    </div>
                    <div>
                      <h3 className="text-lg font-bold text-gray-800 dark:text-white leading-tight">
                        {interview.applicantName}
                      </h3>
                      <p className="text-xs text-gray-500 dark:text-gray-400 font-medium bg-gray-100/50 dark:bg-gray-700/50 px-2 py-0.5 rounded-full inline-block mt-1">
                        {interview.jobTitle}
                      </p>
                    </div>
                  </div>
                  <div
                    className={`px-3 py-1 rounded-full text-xs font-bold border ${statusBadge.bg} shadow-sm`}
                  >
                    {statusBadge.text}
                  </div>
                </div>

                {/* Date & Time Strip */}
                <div className="flex items-center gap-4 bg-gray-50/80 dark:bg-gray-700/30 rounded-xl p-3 mb-4 border border-gray-100 dark:border-gray-700/50">
                  <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                    <CalendarDaysIcon className="w-5 h-5 text-violet-500" />
                    <span className="text-sm font-semibold">
                      {format(new Date(interview.date), "dd MMM", {
                        locale: ar,
                      })}
                    </span>
                  </div>
                  <div className="w-px h-4 bg-gray-300 dark:bg-gray-600" />
                  <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                    <ClockIcon className="w-5 h-5 text-fuchsia-500" />
                    <span className="text-sm font-semibold">
                      {interview.time}
                    </span>
                  </div>
                </div>

                {/* Details Grid */}
                <div className="space-y-3">
                  <div className="flex items-start gap-3">
                    <div className="mt-1">{getTypeIcon(interview.type)}</div>
                    <div>
                      <p className="text-xs text-gray-500 uppercase tracking-wider font-bold">
                        طريقة المقابلة
                      </p>
                      <p className="text-sm font-medium text-gray-800 dark:text-gray-200">
                        {getTypeText(interview.type)}
                      </p>
                      {interview.location && (
                        <p className="text-xs text-violet-600 dark:text-violet-400 mt-0.5 truncate max-w-[200px]">
                          {interview.location}
                        </p>
                      )}
                    </div>
                  </div>

                  {interview.interviewers &&
                    interview.interviewers.length > 0 && (
                      <div className="flex items-center gap-2 pt-2 border-t border-gray-100 dark:border-gray-700/50">
                        <div className="flex -space-x-2 space-x-reverse overflow-hidden">
                          {(typeof interview.interviewers === "string"
                            ? interview.interviewers.split(",")
                            : interview.interviewers
                          )
                            .slice(0, 3)
                            .map((interviewer, idx) => (
                              <div
                                key={idx}
                                className="w-8 h-8 rounded-full bg-gradient-to-tr from-gray-200 to-white dark:from-gray-700 dark:to-gray-600 border-2 border-white dark:border-gray-800 flex items-center justify-center text-xs font-bold text-gray-600 dark:text-gray-300"
                                title={interviewer.trim()}
                              >
                                {interviewer.trim().charAt(0)}
                              </div>
                            ))}
                          {(typeof interview.interviewers === "string"
                            ? interview.interviewers.split(",").length
                            : interview.interviewers.length) > 3 && (
                            <div className="w-8 h-8 rounded-full bg-gray-100 dark:bg-gray-700 border-2 border-white dark:border-gray-800 flex items-center justify-center text-xs font-bold text-gray-500">
                              +
                              {(typeof interview.interviewers === "string"
                                ? interview.interviewers.split(",").length
                                : interview.interviewers.length) - 3}
                            </div>
                          )}
                        </div>
                        <span className="text-xs text-gray-400">
                          لجنة المقابلة
                        </span>
                      </div>
                    )}
                </div>

                {/* Actions - Only show for Scheduled */}
                {interview.status === "SCHEDULED" && (
                  <div className="grid grid-cols-2 gap-3 mt-6 pt-4 border-t border-gray-100 dark:border-gray-700/50">
                    <button
                      onClick={() =>
                        handleUpdateStatus(interview.id, "COMPLETED")
                      }
                      className="flex items-center justify-center gap-1 py-2 rounded-lg bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 hover:bg-green-100 dark:hover:bg-green-900/30 transition-colors text-sm font-bold"
                    >
                      <CheckCircleIcon className="w-4 h-4" />
                      تمت
                    </button>
                    <button
                      onClick={() =>
                        handleUpdateStatus(interview.id, "CANCELLED")
                      }
                      className="flex items-center justify-center gap-1 py-2 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors text-sm font-bold"
                    >
                      <XCircleIcon className="w-4 h-4" />
                      إلغاء
                    </button>
                  </div>
                )}
              </div>
            </motion.div>
          );
        })}
      </div>

      {interviews.length === 0 && !loading && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="flex flex-col items-center justify-center py-24 text-center relative z-10"
        >
          <div className="w-32 h-32 bg-gradient-to-br from-violet-100 to-fuchsia-50 dark:from-gray-800 dark:to-gray-700 rounded-full flex items-center justify-center mb-6 shadow-inner">
            <CalendarDaysIcon className="w-16 h-16 text-violet-300 dark:text-gray-600" />
          </div>
          <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">
            لا توجد مقابلات مجدولة
          </h3>
          <p className="text-gray-500 max-w-md mx-auto mb-8">
            ابدأ بتنظيم جدول أعمالك ومقابلات المرشحين بسهولة من هنا.
          </p>
          <button
            onClick={() => setShowScheduleModal(true)}
            className="px-8 py-3 bg-gradient-to-r from-violet-600 to-fuchsia-600 text-white rounded-xl shadow-lg hover:shadow-violet-500/30 hover:-translate-y-1 transition-all duration-300 font-bold"
          >
            جدولة أول مقابلة 🚀
          </button>
        </motion.div>
      )}

      {loading && (
        <div className="flex justify-center items-center py-32">
          <div className="relative">
            <div className="w-16 h-16 border-4 border-violet-200 border-t-violet-600 rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="w-8 h-8 bg-violet-100 rounded-full animate-pulse"></div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InterviewsSection;

import React, { useState, useEffect } from "react";
import {
  BriefcaseIcon,
  PlusIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  PencilIcon,
  TrashIcon,
  EyeIcon,
  MapPinIcon,
  CurrencyDollarIcon,
  ClockIcon,
  UserGroupIcon,
  CheckCircleIcon,
  XCircleIcon,
} from "@heroicons/react/24/outline";
import { motion, AnimatePresence } from "framer-motion";
import { companyAwareApi } from "../../../../services/companyAwareApi";
import { toast } from "react-hot-toast";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface JobPosting {
  id: string;
  title: string;
  department: string;
  location: string;
  type: "FULL_TIME" | "PART_TIME" | "CONTRACT" | "INTERNSHIP";
  experienceLevel: "ENTRY" | "JUNIOR" | "MID" | "SENIOR" | "LEAD";
  salaryMin?: number;
  salaryMax?: number;
  description: string;
  requirements: string[];
  responsibilities: string[];
  status: "DRAFT" | "ACTIVE" | "CLOSED" | "ON_HOLD";
  applicantsCount: number;
  postedDate: string;
  closingDate?: string;
}

const JobPostingsSection: React.FC = () => {
  const [jobs, setJobs] = useState<JobPosting[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState<string>("all");
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [selectedJob, setSelectedJob] = useState<JobPosting | null>(null);
  const [showDetailsModal, setShowDetailsModal] = useState(false);

  const [newJob, setNewJob] = useState({
    title: "",
    department: "",
    location: "",
    type: "FULL_TIME" as const,
    experienceLevel: "MID" as const,
    salaryMin: "",
    salaryMax: "",
    description: "",
    requirements: "",
    responsibilities: "",
    closingDate: "",
  });

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/hr/recruitment/jobs");
      if (response.data.success) {
        setJobs(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching jobs:", error);
      setJobs([]);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateJob = async () => {
    try {
      const jobData = {
        ...newJob,
        requirements: newJob.requirements.split("\n").filter((r) => r.trim()),
        responsibilities: newJob.responsibilities
          .split("\n")
          .filter((r) => r.trim()),
        salaryMin: newJob.salaryMin ? parseFloat(newJob.salaryMin) : undefined,
        salaryMax: newJob.salaryMax ? parseFloat(newJob.salaryMax) : undefined,
      };

      const response = await companyAwareApi.post(
        "/hr/recruitment/jobs",
        jobData,
      );
      if (response.data.success) {
        toast.success("تم إنشاء الوظيفة بنجاح");
        setShowCreateModal(false);
        fetchJobs();
        resetForm();
      }
    } catch (error) {
      toast.error("فشل في إنشاء الوظيفة");
    }
  };

  const handleDeleteJob = async (jobId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذه الوظيفة؟")) return;

    try {
      await companyAwareApi.delete(`/hr/recruitment/jobs/${jobId}`);
      toast.success("تم حذف الوظيفة بنجاح");
      fetchJobs();
    } catch (error) {
      toast.error("فشل في حذف الوظيفة");
    }
  };

  const handleUpdateStatus = async (jobId: string, status: string) => {
    try {
      await companyAwareApi.put(`/hr/recruitment/jobs/${jobId}/status`, {
        status,
      });
      toast.success("تم تحديث حالة الوظيفة");
      fetchJobs();
    } catch (error) {
      toast.error("فشل في تحديث الحالة");
    }
  };

  const resetForm = () => {
    setNewJob({
      title: "",
      department: "",
      location: "",
      type: "FULL_TIME",
      experienceLevel: "MID",
      salaryMin: "",
      salaryMax: "",
      description: "",
      requirements: "",
      responsibilities: "",
      closingDate: "",
    });
  };

  const filteredJobs = jobs.filter((job) => {
    const matchesSearch =
      job.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.department.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterStatus === "all" || job.status === filterStatus;
    return matchesSearch && matchesFilter;
  });

  const getStatusBadge = (status: JobPosting["status"]) => {
    const badges = {
      DRAFT: {
        bg: "bg-gray-100 text-gray-700 border-gray-300",
        text: "📝 مسودة",
      },
      ACTIVE: {
        bg: "bg-green-100 text-green-700 border-green-300",
        text: "✅ نشط",
      },
      CLOSED: { bg: "bg-red-100 text-red-700 border-red-300", text: "🔒 مغلق" },
      ON_HOLD: {
        bg: "bg-amber-100 text-amber-700 border-amber-300",
        text: "⏸️ معلق",
      },
    };
    return badges[status];
  };

  const getTypeBadge = (type: JobPosting["type"]) => {
    const badges = {
      FULL_TIME: "⏰ دوام كامل",
      PART_TIME: "🕐 دوام جزئي",
      CONTRACT: "📄 عقد",
      INTERNSHIP: "🎓 تدريب",
    };
    return badges[type];
  };

  const getExperienceBadge = (level: JobPosting["experienceLevel"]) => {
    const badges = {
      ENTRY: "🌱 مبتدئ",
      JUNIOR: "📚 Junior",
      MID: "💼 Mid-Level",
      SENIOR: "⭐ Senior",
      LEAD: "👑 Lead",
    };
    return badges[level];
  };

  return (
    <div className="space-y-6">
      {/* Search and Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-lg border-2 border-gray-200 dark:border-gray-700">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="ابحث عن وظيفة..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pr-10 pl-4 py-3 border-2 border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
            />
          </div>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-3 border-2 border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
          >
            <option value="all">جميع الحالات</option>
            <option value="ACTIVE">نشط</option>
            <option value="DRAFT">مسودة</option>
            <option value="CLOSED">مغلق</option>
            <option value="ON_HOLD">معلق</option>
          </select>
          <button
            onClick={() => setShowCreateModal(true)}
            className="flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:shadow-lg transition-all"
          >
            <PlusIcon className="w-5 h-5" />
            إضافة وظيفة
          </button>
        </div>
      </div>

      {/* Jobs Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <AnimatePresence>
          {filteredJobs.map((job, index) => {
            const statusBadge = getStatusBadge(job.status);
            return (
              <motion.div
                key={job.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ delay: index * 0.1 }}
                className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-lg border-2 border-gray-200 dark:border-gray-700 hover:shadow-xl transition-all"
              >
                {/* Header */}
                <div className="flex items-start justify-between mb-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2">
                      <BriefcaseIcon className="w-6 h-6 text-blue-600" />
                      <h3 className="text-xl font-bold text-gray-800 dark:text-white">
                        {job.title}
                      </h3>
                    </div>
                    <p className="text-gray-600 dark:text-gray-400">
                      {job.department}
                    </p>
                  </div>
                  <span
                    className={`px-3 py-1 rounded-full text-sm font-medium border-2 ${statusBadge.bg}`}
                  >
                    {statusBadge.text}
                  </span>
                </div>

                {/* Details */}
                <div className="space-y-3 mb-4">
                  <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
                    <MapPinIcon className="w-5 h-5" />
                    <span>{job.location}</span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
                    <ClockIcon className="w-5 h-5" />
                    <span>{getTypeBadge(job.type)}</span>
                    <span className="mx-2">•</span>
                    <span>{getExperienceBadge(job.experienceLevel)}</span>
                  </div>
                  {job.salaryMin && job.salaryMax && (
                    <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
                      <CurrencyDollarIcon className="w-5 h-5" />
                      <span>
                        {job.salaryMin.toLocaleString()} -{" "}
                        {job.salaryMax.toLocaleString()} جنيه
                      </span>
                    </div>
                  )}
                  <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
                    <UserGroupIcon className="w-5 h-5" />
                    <span>{job.applicantsCount} متقدم</span>
                  </div>
                </div>

                {/* Actions */}
                <div className="flex gap-2 pt-4 border-t-2 border-gray-200 dark:border-gray-700">
                  <button
                    onClick={() => {
                      setSelectedJob(job);
                      setShowDetailsModal(true);
                    }}
                    className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-lg hover:bg-blue-100 transition-all"
                  >
                    <EyeIcon className="w-5 h-5" />
                    عرض
                  </button>
                  <button
                    onClick={() =>
                      handleUpdateStatus(
                        job.id,
                        job.status === "ACTIVE" ? "CLOSED" : "ACTIVE",
                      )
                    }
                    className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-green-50 dark:bg-green-900/20 text-green-600 rounded-lg hover:bg-green-100 transition-all"
                  >
                    {job.status === "ACTIVE" ? (
                      <XCircleIcon className="w-5 h-5" />
                    ) : (
                      <CheckCircleIcon className="w-5 h-5" />
                    )}
                    {job.status === "ACTIVE" ? "إغلاق" : "تفعيل"}
                  </button>
                  <button
                    onClick={() => handleDeleteJob(job.id)}
                    className="px-4 py-2 bg-red-50 dark:bg-red-900/20 text-red-600 rounded-lg hover:bg-red-100 transition-all"
                  >
                    <TrashIcon className="w-5 h-5" />
                  </button>
                </div>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>

      {filteredJobs.length === 0 && !loading && (
        <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-2xl border-2 border-gray-200 dark:border-gray-700">
          <BriefcaseIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 dark:text-gray-400 text-lg">
            لا توجد وظائف متاحة
          </p>
        </div>
      )}

      {/* Create Job Modal */}
      <AnimatePresence>
        {showCreateModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4"
            onClick={() => setShowCreateModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-gray-800 rounded-2xl p-6 max-w-3xl w-full max-h-[90vh] overflow-y-auto"
            >
              <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">
                إضافة وظيفة جديدة
              </h2>

              <div className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      المسمى الوظيفي *
                    </label>
                    <input
                      type="text"
                      value={newJob.title}
                      onChange={(e) =>
                        setNewJob({ ...newJob, title: e.target.value })
                      }
                      className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                      placeholder="مثال: مطور Full Stack"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      القسم *
                    </label>
                    <input
                      type="text"
                      value={newJob.department}
                      onChange={(e) =>
                        setNewJob({ ...newJob, department: e.target.value })
                      }
                      className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                      placeholder="مثال: تطوير البرمجيات"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      الموقع *
                    </label>
                    <input
                      type="text"
                      value={newJob.location}
                      onChange={(e) =>
                        setNewJob({ ...newJob, location: e.target.value })
                      }
                      className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                      placeholder="مثال: القاهرة - مصر"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      نوع الوظيفة *
                    </label>
                    <select
                      value={newJob.type}
                      onChange={(e) =>
                        setNewJob({ ...newJob, type: e.target.value as any })
                      }
                      className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                    >
                      <option value="FULL_TIME">دوام كامل</option>
                      <option value="PART_TIME">دوام جزئي</option>
                      <option value="CONTRACT">عقد</option>
                      <option value="INTERNSHIP">تدريب</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      مستوى الخبرة *
                    </label>
                    <select
                      value={newJob.experienceLevel}
                      onChange={(e) =>
                        setNewJob({
                          ...newJob,
                          experienceLevel: e.target.value as any,
                        })
                      }
                      className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                    >
                      <option value="ENTRY">مبتدئ</option>
                      <option value="JUNIOR">Junior</option>
                      <option value="MID">Mid-Level</option>
                      <option value="SENIOR">Senior</option>
                      <option value="LEAD">Lead</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      الراتب من
                    </label>
                    <input
                      type="number"
                      value={newJob.salaryMin}
                      onChange={(e) =>
                        setNewJob({ ...newJob, salaryMin: e.target.value })
                      }
                      className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                      placeholder="15000"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      الراتب إلى
                    </label>
                    <input
                      type="number"
                      value={newJob.salaryMax}
                      onChange={(e) =>
                        setNewJob({ ...newJob, salaryMax: e.target.value })
                      }
                      className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                      placeholder="25000"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    الوصف الوظيفي *
                  </label>
                  <textarea
                    value={newJob.description}
                    onChange={(e) =>
                      setNewJob({ ...newJob, description: e.target.value })
                    }
                    rows={4}
                    className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                    placeholder="اكتب وصف تفصيلي للوظيفة..."
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    المتطلبات (سطر لكل متطلب) *
                  </label>
                  <textarea
                    value={newJob.requirements}
                    onChange={(e) =>
                      setNewJob({ ...newJob, requirements: e.target.value })
                    }
                    rows={4}
                    className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                    placeholder="خبرة 3+ سنوات&#10;React & Node.js&#10;TypeScript"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    المسؤوليات (سطر لكل مسؤولية) *
                  </label>
                  <textarea
                    value={newJob.responsibilities}
                    onChange={(e) =>
                      setNewJob({ ...newJob, responsibilities: e.target.value })
                    }
                    rows={4}
                    className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                    placeholder="تطوير الميزات الجديدة&#10;صيانة الكود&#10;مراجعة الكود"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    تاريخ الإغلاق
                  </label>
                  <input
                    type="date"
                    value={newJob.closingDate}
                    onChange={(e) =>
                      setNewJob({ ...newJob, closingDate: e.target.value })
                    }
                    className="w-full px-4 py-2 border-2 border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                  />
                </div>
              </div>

              <div className="flex gap-3 mt-6">
                <button
                  onClick={handleCreateJob}
                  className="flex-1 px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:shadow-lg transition-all"
                >
                  إنشاء الوظيفة
                </button>
                <button
                  onClick={() => {
                    setShowCreateModal(false);
                    resetForm();
                  }}
                  className="px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-white rounded-xl hover:bg-gray-300 transition-all"
                >
                  إلغاء
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Job Details Modal */}
      <AnimatePresence>
        {showDetailsModal && selectedJob && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4"
            onClick={() => setShowDetailsModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-gray-800 rounded-2xl p-6 max-w-3xl w-full max-h-[90vh] overflow-y-auto"
            >
              <div className="flex items-start justify-between mb-6">
                <div>
                  <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">
                    {selectedJob.title}
                  </h2>
                  <p className="text-gray-600 dark:text-gray-400">
                    {selectedJob.department}
                  </p>
                </div>
                <span
                  className={`px-3 py-1 rounded-full text-sm font-medium border-2 ${getStatusBadge(selectedJob.status).bg}`}
                >
                  {getStatusBadge(selectedJob.status).text}
                </span>
              </div>

              <div className="space-y-6">
                <div>
                  <h3 className="font-bold text-gray-800 dark:text-white mb-2">
                    الوصف الوظيفي
                  </h3>
                  <p className="text-gray-600 dark:text-gray-400">
                    {selectedJob.description}
                  </p>
                </div>

                <div>
                  <h3 className="font-bold text-gray-800 dark:text-white mb-2">
                    المتطلبات
                  </h3>
                  <ul className="list-disc list-inside space-y-1">
                    {(Array.isArray(selectedJob.requirements)
                      ? selectedJob.requirements
                      : typeof selectedJob.requirements === "string"
                        ? (selectedJob.requirements as string).split("\n")
                        : []
                    ).map((req, idx) => (
                      <li
                        key={idx}
                        className="text-gray-600 dark:text-gray-400"
                      >
                        {req}
                      </li>
                    ))}
                  </ul>
                </div>

                <div>
                  <h3 className="font-bold text-gray-800 dark:text-white mb-2">
                    المسؤوليات
                  </h3>
                  <ul className="list-disc list-inside space-y-1">
                    {(Array.isArray(selectedJob.responsibilities)
                      ? selectedJob.responsibilities
                      : typeof selectedJob.responsibilities === "string"
                        ? (selectedJob.responsibilities as string).split("\n")
                        : []
                    ).map((resp, idx) => (
                      <li
                        key={idx}
                        className="text-gray-600 dark:text-gray-400"
                      >
                        {resp}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              <button
                onClick={() => setShowDetailsModal(false)}
                className="w-full mt-6 px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-white rounded-xl hover:bg-gray-300 transition-all"
              >
                إغلاق
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default JobPostingsSection;

import React, { useState, useEffect } from "react";
import {
  Clock,
  Users,
  TrendingUp,
  TrendingDown,
  Download,
  RefreshCw,
  FileText,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../../components/ui/card";
import { Button } from "../../../components/ui/button";
import { Label } from "../../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../../components/ui/select";
import { Progress } from "../../../components/ui/progress";
import api from "../../../services/api";
import { toast } from "sonner";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../../components/ui/table";
import { Badge } from "../../../components/ui/badge";

interface AttendanceReport {
  totalEmployees: number;
  presentDays: number;
  absentDays: number;
  lateDays: number;
  averageWorkHours: number;
  attendanceRate: number;
  byDepartment: {
    department: string;
    rate: number;
    employees: number;
  }[];
  employees: {
    id: string;
    userId: string;
    name: string;
    employeeNumber: string;
    department: string;
    position: string;
    presentDays: number;
    lateDays: number;
    absentDays: number;
    totalWorkHours: number;
    totalLateMinutes: number;
    attendanceRate: number;
  }[];
}

const months = [
  "يناير",
  "فبراير",
  "مارس",
  "أبريل",
  "مايو",
  "يونيو",
  "يوليو",
  "أغسطس",
  "سبتمبر",
  "أكتوبر",
  "نوفمبر",
  "ديسمبر",
];

const AttendanceReport: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const currentDate = new Date();
  const [selectedMonth, setSelectedMonth] = useState(
    currentDate.getMonth() + 1,
  );
  const [selectedYear, setSelectedYear] = useState(currentDate.getFullYear());
  const [report, setReport] = useState<AttendanceReport | null>(null);

  useEffect(() => {
    fetchReport();
  }, [selectedMonth, selectedYear]);

  const fetchReport = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        month: selectedMonth.toString(),
        year: selectedYear.toString(),
      });

      const response = await api.get(`/hr/reports/attendance?${params}`);
      setReport(response.data?.report || null);
    } catch (error) {
      console.error("Error fetching report:", error);
      toast.error("فشل في جلب التقرير");
      setReport(null);
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async () => {
    toast.success("جاري تصدير التقرير...");
  };

  return (
    <div className="space-y-6 text-gray-900 dark:text-gray-100">
      {/* Filters */}
      <Card className="border-none shadow-sm dark:bg-gray-800/50 backdrop-blur-sm">
        <CardContent className="p-4">
          <div className="flex flex-wrap gap-4 items-end">
            <div className="space-y-2">
              <Label className="dark:text-gray-300">الشهر</Label>
              <Select
                value={selectedMonth.toString()}
                onValueChange={(v) => setSelectedMonth(parseInt(v))}
              >
                <SelectTrigger className="w-[150px] dark:bg-gray-800 dark:border-gray-700">
                  <SelectValue className="dark:text-white" />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-800 dark:border-gray-700">
                  {months.map((month, index) => (
                    <SelectItem
                      key={index}
                      value={(index + 1).toString()}
                      className="dark:text-gray-300 dark:focus:bg-gray-700"
                    >
                      {month}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label className="dark:text-gray-300">السنة</Label>
              <Select
                value={selectedYear.toString()}
                onValueChange={(v) => setSelectedYear(parseInt(v))}
              >
                <SelectTrigger className="w-[120px] dark:bg-gray-800 dark:border-gray-700">
                  <SelectValue className="dark:text-white" />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-800 dark:border-gray-700">
                  {[2023, 2024, 2025, 2026].map((year) => (
                    <SelectItem
                      key={year}
                      value={year.toString()}
                      className="dark:text-gray-300 dark:focus:bg-gray-700"
                    >
                      {year}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="flex gap-2 mr-auto">
              <Button
                variant="outline"
                onClick={fetchReport}
                className="dark:bg-gray-800 dark:border-gray-700 dark:text-gray-300 dark:hover:bg-gray-700"
              >
                <RefreshCw className="h-4 w-4 ml-2" />
                تحديث
              </Button>
              <Button
                variant="outline"
                onClick={handleExport}
                className="dark:bg-gray-800 dark:border-gray-700 dark:text-gray-300 dark:hover:bg-gray-700"
              >
                <Download className="h-4 w-4 ml-2" />
                تصدير
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {loading ? (
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
        </div>
      ) : (
        report && (
          <>
            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <Card className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white border-none shadow-lg transform transition-all hover:scale-[1.02]">
                <CardContent className="p-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-blue-100 text-sm font-medium">
                        نسبة الحضور
                      </p>
                      <h3 className="text-3xl font-bold mt-1">
                        {report.attendanceRate || 0}%
                      </h3>
                    </div>
                    <TrendingUp className="h-10 w-10 opacity-40" />
                  </div>
                  <div className="mt-4 bg-white/20 h-1.5 rounded-full overflow-hidden">
                    <div
                      className="bg-white h-full"
                      style={{ width: `${report.attendanceRate || 0}%` }}
                    ></div>
                  </div>
                </CardContent>
              </Card>

              <Card className="dark:bg-gray-800 dark:border-gray-700 shadow-sm border-none bg-white">
                <CardContent className="p-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-gray-500 dark:text-gray-400 text-sm font-medium">
                        أيام الحضور
                      </p>
                      <h3 className="text-3xl font-bold mt-1 text-emerald-600 dark:text-emerald-400">
                        {report.presentDays || 0}
                      </h3>
                    </div>
                    <Users className="h-10 w-10 text-emerald-500/20 dark:text-emerald-400/20" />
                  </div>
                </CardContent>
              </Card>

              <Card className="dark:bg-gray-800 dark:border-gray-700 shadow-sm border-none bg-white">
                <CardContent className="p-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-gray-500 dark:text-gray-400 text-sm font-medium">
                        أيام الغياب
                      </p>
                      <h3 className="text-3xl font-bold mt-1 text-rose-600 dark:text-rose-400">
                        {report.absentDays || 0}
                      </h3>
                    </div>
                    <TrendingDown className="h-10 w-10 text-rose-500/20 dark:text-rose-400/20" />
                  </div>
                </CardContent>
              </Card>

              <Card className="dark:bg-gray-800 dark:border-gray-700 shadow-sm border-none bg-white">
                <CardContent className="p-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-gray-500 dark:text-gray-400 text-sm font-medium">
                        متوسط ساعات العمل
                      </p>
                      <h3 className="text-3xl font-bold mt-1 text-amber-600 dark:text-amber-400">
                        {report.averageWorkHours || 0}
                      </h3>
                    </div>
                    <Clock className="h-10 w-10 text-amber-500/20 dark:text-amber-400/20" />
                  </div>
                </CardContent>
              </Card>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* By Department */}
              <Card className="lg:col-span-1 dark:bg-gray-800 dark:border-gray-700 shadow-sm border-none bg-white overflow-hidden">
                <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50 p-4">
                  <CardTitle className="text-lg font-semibold dark:text-white flex items-center gap-2">
                    <Users className="h-5 w-5 text-primary" />
                    الحضور حسب القسم
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-4">
                  <div className="space-y-4">
                    {report.byDepartment && report.byDepartment.length > 0 ? (
                      report.byDepartment.map((dept, index) => (
                        <div
                          key={index}
                          className="space-y-2 p-2 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                        >
                          <div className="flex items-center justify-between">
                            <span className="font-medium dark:text-gray-200">
                              {dept.department}
                            </span>
                            <span className="text-sm font-semibold text-primary">
                              {dept.rate}%
                            </span>
                          </div>
                          <div className="flex items-center justify-between text-xs text-gray-500 dark:text-gray-400 mb-1">
                            <span>{dept.employees} موظف</span>
                          </div>
                          <Progress
                            value={dept.rate}
                            className="h-1.5 dark:bg-gray-700"
                          />
                        </div>
                      ))
                    ) : (
                      <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                        لا توجد بيانات
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>

              {/* Comprehensive Employee Table */}
              <Card className="lg:col-span-2 dark:bg-gray-800 dark:border-gray-700 shadow-sm border-none bg-white">
                <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50 p-4">
                  <CardTitle className="text-lg font-semibold dark:text-white flex items-center gap-2">
                    <FileText className="h-5 w-5 text-primary" />
                    تقرير الحضور لكل موظف
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <Table>
                      <TableHeader className="bg-gray-50 dark:bg-gray-900/50">
                        <TableRow>
                          <TableHead className="text-right">الموظف</TableHead>
                          <TableHead className="text-right">القسم</TableHead>
                          <TableHead className="text-right">حضور</TableHead>
                          <TableHead className="text-right">غياب</TableHead>
                          <TableHead className="text-right">تأخير</TableHead>
                          <TableHead className="text-right">الساعات</TableHead>
                          <TableHead className="text-right">النسبة</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {report.employees && report.employees.length > 0 ? (
                          report.employees.map((emp) => (
                            <TableRow
                              key={emp.id}
                              className="hover:bg-gray-50 dark:hover:bg-gray-700/50"
                            >
                              <TableCell>
                                <div className="flex flex-col">
                                  <span className="font-medium dark:text-gray-200">
                                    {emp.name}
                                  </span>
                                  <span className="text-xs text-gray-500 dark:text-gray-400">
                                    #{emp.employeeNumber}
                                  </span>
                                </div>
                              </TableCell>
                              <TableCell className="dark:text-gray-300">
                                {emp.department}
                              </TableCell>
                              <TableCell>
                                <Badge
                                  variant="outline"
                                  className="text-emerald-600 border-emerald-200 bg-emerald-50 dark:bg-emerald-900/20 dark:border-emerald-800"
                                >
                                  {emp.presentDays}
                                </Badge>
                              </TableCell>
                              <TableCell>
                                <Badge
                                  variant="outline"
                                  className={`${emp.absentDays > 0 ? "text-rose-600 border-rose-200 bg-rose-50 dark:bg-rose-900/20 dark:border-rose-800" : "text-gray-400 border-gray-100"}`}
                                >
                                  {emp.absentDays}
                                </Badge>
                              </TableCell>
                              <TableCell>
                                <Badge
                                  variant="outline"
                                  className={`${emp.lateDays > 0 ? "text-amber-600 border-amber-200 bg-amber-50 dark:bg-amber-900/20 dark:border-amber-800" : "text-gray-400 border-gray-100"}`}
                                >
                                  {emp.lateDays}
                                </Badge>
                              </TableCell>
                              <TableCell className="dark:text-gray-300">
                                {emp.totalWorkHours.toFixed(1)}h
                              </TableCell>
                              <TableCell>
                                <div className="flex items-center gap-2">
                                  <span className="font-semibold text-sm">
                                    {emp.attendanceRate}%
                                  </span>
                                </div>
                              </TableCell>
                            </TableRow>
                          ))
                        ) : (
                          <TableRow>
                            <TableCell
                              colSpan={7}
                              className="text-center py-8 text-gray-500 dark:text-gray-400"
                            >
                              لا توجد بيانات للموظفين
                            </TableCell>
                          </TableRow>
                        )}
                      </TableBody>
                    </Table>
                  </div>
                </CardContent>
              </Card>
            </div>
          </>
        )
      )}
    </div>
  );
};

export default AttendanceReport;

import React, { useState, useEffect } from "react";
import {
  User,
  Download,
  RefreshCw,
  Calendar,
  Clock,
  DollarSign,
  FileText,
  AlertCircle,
  TrendingUp,
  Award,
  Target,
  CheckCircle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../../components/ui/card";
import { Button } from "../../../components/ui/button";
import { Label } from "../../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../../components/ui/select";
import { Badge } from "../../../components/ui/badge";
import { Progress } from "../../../components/ui/progress";
import api from "../../../services/api";
import { toast } from "sonner";

interface EmployeeReportData {
  employee: {
    id: string;
    name: string;
    employeeNumber: string;
    department: string;
    position: string;
  };
  attendance: {
    totalDays: number;
    presentDays: number;
    absentDays: number;
    lateDays: number;
    totalLateMinutes: number;
    totalWorkHours: number;
    overtimeHours: number;
    records: {
      date: string;
      checkIn: string | null;
      checkOut: string | null;
      status: string;
      workHours: number;
      lateMinutes: number;
    }[];
  };
  leaves: {
    totalRequests: number;
    approved: number;
    pending: number;
    rejected: number;
    totalDaysTaken: number;
    requests: {
      id: string;
      type: string;
      startDate: string;
      endDate: string;
      days: number;
      status: string;
      reason: string;
    }[];
  };
  advances: {
    totalRequests: number;
    totalAmount: number;
    pending: number;
    approved: number;
    requests: {
      id: string;
      amount: number;
      requestDate: string;
      status: string;
      reason: string;
    }[];
  };
  permissions: {
    totalRequests: number;
    approved: number;
    totalHours: number;
    requests: {
      id: string;
      date: string;
      startTime: string;
      endTime: string;
      totalHours: number;
      status: string;
      reason: string;
    }[];
  };
  payroll: {
    baseSalary: number;
    allowances: number;
    deductions: number;
    overtimePay: number;
    netSalary: number;
    lastPayment: string | null;
    manualDeductions: {
      id: string;
      amount: number;
      reason: string;
      date: string;
      status: string;
      type: string;
    }[];
  };
  performance: {
    lastReview: {
      date: string;
      score: number;
      reviewer: string;
    } | null;
    activeGoals: number;
    completedGoals: number;
  };
  warnings: {
    total: number;
    recent: {
      id: string;
      type: string;
      date: string;
      description: string;
    }[];
  };
}

const EmployeeReport: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [employees, setEmployees] = useState<any[]>([]);
  const [selectedEmployee, setSelectedEmployee] = useState<string>("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [report, setReport] = useState<EmployeeReportData | null>(null);

  useEffect(() => {
    fetchEmployees();

    // Set default dates (current month)
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);

    setStartDate(firstDay.toISOString().split("T")[0] || "");
    setEndDate(lastDay.toISOString().split("T")[0] || "");
  }, []);

  const fetchEmployees = async () => {
    try {
      const response = await api.get("/hr/employees");
      setEmployees(response.data?.employees || []);
    } catch (error) {
      console.error("Error fetching employees:", error);
      toast.error("فشل في جلب قائمة الموظفين");
    }
  };

  const fetchReport = async () => {
    if (!selectedEmployee) {
      toast.error("الرجاء اختيار موظف");
      return;
    }

    if (!startDate || !endDate) {
      toast.error("الرجاء تحديد الفترة الزمنية");
      return;
    }

    try {
      setLoading(true);
      if (new Date(startDate) > new Date(endDate)) {
        toast.error("تاريخ البداية يجب أن يكون قبل تاريخ النهاية");
        return;
      }

      const params = new URLSearchParams({
        employeeId: selectedEmployee,
        startDate,
        endDate,
      });

      const response = await api.get(`/hr/reports/employee?${params}`);
      console.log("Employee Report Response:", response.data);

      if (response.data?.success) {
        setReport(response.data.report);
      } else {
        toast.error(response.data?.error || "فشل في جلب التقرير");
        setReport(null);
      }
    } catch (error: any) {
      console.error("Error fetching report:", error);
      const errorMsg = error.response?.data?.error || "فشل في جلب التقرير";
      toast.error(errorMsg);
      setReport(null);
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    if (!report) return;

    // Create CSV content
    const headers = [
      "التاريخ",
      "الحالة",
      "وقت الدخول",
      "وقت الخروج",
      "ساعات العمل",
      "التأخير (دقيقة)",
    ];
    const rows = report.attendance.records.map((record) => [
      new Date(record.date).toLocaleDateString("ar-EG"),
      getStatusLabel(record.status),
      record.checkIn
        ? new Date(record.checkIn).toLocaleTimeString("ar-EG")
        : "-",
      record.checkOut
        ? new Date(record.checkOut).toLocaleTimeString("ar-EG")
        : "-",
      record.workHours?.toFixed(2) || "0",
      record.lateMinutes || "0",
    ]);

    const csvContent = [
      headers.join(","),
      ...rows.map((row) => row.join(",")),
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], {
      type: "text/csv;charset=utf-8;",
    });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `employee_report_${report.employee.name}_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();

    toast.success("تم تصدير التقرير بنجاح");
  };

  const handlePrint = () => {
    window.print();
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      PRESENT:
        "text-green-600 bg-green-50 dark:bg-green-900/20 dark:text-green-400",
      ABSENT: "text-red-600 bg-red-50 dark:bg-red-900/20 dark:text-red-400",
      LATE: "text-orange-600 bg-orange-50 dark:bg-orange-900/20 dark:text-orange-400",
      ON_LEAVE:
        "text-blue-600 bg-blue-50 dark:bg-blue-900/20 dark:text-blue-400",
      APPROVED:
        "text-green-600 bg-green-50 dark:bg-green-900/20 dark:text-green-400",
      PENDING:
        "text-yellow-600 bg-yellow-50 dark:bg-yellow-900/20 dark:text-yellow-400",
      REJECTED: "text-red-600 bg-red-50 dark:bg-red-900/20 dark:text-red-400",
    };
    return colors[status] || "text-gray-600 bg-gray-50";
  };

  const getStatusLabel = (status: string) => {
    const labels: Record<string, string> = {
      PRESENT: "حاضر",
      ABSENT: "غائب",
      LATE: "متأخر",
      ON_LEAVE: "إجازة",
      APPROVED: "موافق عليه",
      PENDING: "معلق",
      REJECTED: "مرفوض",
    };
    return labels[status] || status;
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("ar-EG", {
      style: "currency",
      currency: "EGP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  const getAttendanceRate = () => {
    if (!report?.attendance?.totalDays || report.attendance.totalDays === 0)
      return 0;
    return (
      (report.attendance.presentDays / report.attendance.totalDays) *
      100
    ).toFixed(1);
  };

  const getPerformanceColor = (score: number) => {
    if (score >= 4.5) return "text-green-600 dark:text-green-400";
    if (score >= 3.5) return "text-blue-600 dark:text-blue-400";
    if (score >= 2.5) return "text-yellow-600 dark:text-yellow-400";
    return "text-red-600 dark:text-red-400";
  };

  return (
    <div className="space-y-6 text-gray-900 dark:text-gray-100">
      {/* Filters */}
      <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
        <CardContent className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="space-y-2">
              <Label className="dark:text-gray-300">الموظف</Label>
              <Select
                value={selectedEmployee}
                onValueChange={setSelectedEmployee}
              >
                <SelectTrigger className="dark:bg-gray-800 dark:border-gray-700">
                  <SelectValue
                    placeholder="اختر موظف"
                    className="dark:text-gray-400"
                  />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-800 dark:border-gray-700">
                  {employees.map((emp) => (
                    <SelectItem
                      key={emp.id}
                      value={emp.id}
                      className="dark:text-gray-300 dark:focus:bg-gray-700"
                    >
                      {emp.firstName} {emp.lastName} - {emp.employeeNumber}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label className="dark:text-gray-300">من تاريخ</Label>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="w-full px-3 py-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-200 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <div className="space-y-2">
              <Label className="dark:text-gray-300">إلى تاريخ</Label>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="w-full px-3 py-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-200 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <div className="space-y-2">
              <Label className="invisible">Actions</Label>
              <div className="flex gap-2">
                <Button
                  onClick={fetchReport}
                  className="flex-1 bg-blue-600 hover:bg-blue-700 text-white"
                >
                  <RefreshCw className="h-4 w-4 ml-2" />
                  عرض
                </Button>
                {report && (
                  <>
                    <Button
                      variant="outline"
                      onClick={handleExport}
                      className="dark:bg-gray-800 dark:border-gray-700 dark:text-gray-300"
                    >
                      <Download className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="outline"
                      onClick={handlePrint}
                      className="dark:bg-gray-800 dark:border-gray-700 dark:text-gray-300 print:hidden"
                    >
                      <FileText className="h-4 w-4" />
                    </Button>
                  </>
                )}
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {loading ? (
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
        </div>
      ) : report ? (
        <>
          {/* Employee Info */}
          <Card className="border-none shadow-lg overflow-hidden">
            <CardHeader className="bg-gradient-to-r from-blue-600 to-indigo-700 text-white">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-white/10 rounded-xl backdrop-blur-sm">
                  <User className="h-10 w-10" />
                </div>
                <div>
                  <CardTitle className="text-2xl font-bold">
                    {report.employee?.name}
                  </CardTitle>
                  <p className="text-blue-100 text-sm mt-1 flex items-center gap-2">
                    <span>{report.employee?.employeeNumber}</span>
                    <span className="opacity-50">•</span>
                    <span>{report.employee?.department}</span>
                    <span className="opacity-50">•</span>
                    <span>{report.employee?.position}</span>
                  </p>
                </div>
              </div>
            </CardHeader>
          </Card>

          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <Card className="bg-gradient-to-br from-emerald-500 to-emerald-600 text-white border-none shadow-lg hover:shadow-xl transition-shadow">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-emerald-100 text-sm font-medium">
                      نسبة الحضور
                    </p>
                    <h3 className="text-3xl font-bold mt-1">
                      {getAttendanceRate()}%
                    </h3>
                  </div>
                  <Clock className="h-10 w-10 opacity-30" />
                </div>
                <Progress
                  value={parseFloat(getAttendanceRate())}
                  className="mt-3 h-2 bg-white/20"
                />
              </CardContent>
            </Card>

            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm hover:shadow-md transition-shadow">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-500 dark:text-gray-400 text-sm">
                      طلبات الإجازات
                    </p>
                    <h3 className="text-3xl font-bold mt-1 text-blue-600 dark:text-blue-400">
                      {report.leaves?.totalRequests || 0}
                    </h3>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                      {report.leaves?.approved || 0} موافق عليها
                    </p>
                  </div>
                  <Calendar className="h-10 w-10 text-blue-500/20 dark:text-blue-400/20" />
                </div>
              </CardContent>
            </Card>

            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm hover:shadow-md transition-shadow">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-500 dark:text-gray-400 text-sm">
                      صافي الراتب
                    </p>
                    <h3 className="text-2xl font-bold mt-1 text-purple-600 dark:text-purple-400">
                      {formatCurrency(report.payroll?.netSalary || 0)}
                    </h3>
                  </div>
                  <DollarSign className="h-10 w-10 text-purple-500/20 dark:text-purple-400/20" />
                </div>
              </CardContent>
            </Card>

            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm hover:shadow-md transition-shadow">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-500 dark:text-gray-400 text-sm">
                      تقييم الأداء
                    </p>
                    <h3
                      className={`text-3xl font-bold mt-1 ${getPerformanceColor(report.performance?.lastReview?.score || 0)}`}
                    >
                      {report.performance?.lastReview?.score || "N/A"}
                    </h3>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                      {report.performance?.activeGoals || 0} أهداف نشطة
                    </p>
                  </div>
                  <Award className="h-10 w-10 text-amber-500/20 dark:text-amber-400/20" />
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Detailed Sections */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Attendance Details */}
            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
              <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <Clock className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
                  تفاصيل الحضور
                </CardTitle>
              </CardHeader>
              <CardContent className="p-6">
                <div className="space-y-4">
                  <div className="flex justify-between items-center p-3 bg-emerald-50 dark:bg-emerald-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      أيام الحضور
                    </span>
                    <Badge className="bg-emerald-600 text-white">
                      {report.attendance?.presentDays || 0}
                    </Badge>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-red-50 dark:bg-red-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      أيام الغياب
                    </span>
                    <Badge className="bg-red-600 text-white">
                      {report.attendance?.absentDays || 0}
                    </Badge>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-orange-50 dark:bg-orange-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      أيام التأخير
                    </span>
                    <Badge className="bg-orange-600 text-white">
                      {report.attendance?.lateDays || 0}
                    </Badge>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-blue-50 dark:bg-blue-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      إجمالي ساعات العمل
                    </span>
                    <Badge className="bg-blue-600 text-white">
                      {report.attendance?.totalWorkHours?.toFixed(1) || 0}h
                    </Badge>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-purple-50 dark:bg-purple-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      ساعات إضافية
                    </span>
                    <Badge className="bg-purple-600 text-white">
                      {report.attendance?.overtimeHours?.toFixed(1) || 0}h
                    </Badge>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Payroll Details */}
            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
              <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <DollarSign className="h-5 w-5 text-purple-600 dark:text-purple-400" />
                  تفاصيل الراتب
                </CardTitle>
              </CardHeader>
              <CardContent className="p-6">
                <div className="space-y-4">
                  <div className="flex justify-between items-center p-3 bg-gray-50 dark:bg-gray-900/30 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      الراتب الأساسي
                    </span>
                    <span className="font-bold text-gray-900 dark:text-white">
                      {formatCurrency(report.payroll?.baseSalary || 0)}
                    </span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-emerald-50 dark:bg-emerald-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      البدلات
                    </span>
                    <span className="font-bold text-emerald-600 dark:text-emerald-400">
                      +{formatCurrency(report.payroll?.allowances || 0)}
                    </span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-blue-50 dark:bg-blue-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      مكافأة الوقت الإضافي
                    </span>
                    <span className="font-bold text-blue-600 dark:text-blue-400">
                      +{formatCurrency(report.payroll?.overtimePay || 0)}
                    </span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-red-50 dark:bg-red-900/10 rounded-lg">
                    <span className="text-sm font-medium dark:text-gray-300">
                      الخصومات
                    </span>
                    <span className="font-bold text-red-600 dark:text-red-400">
                      -{formatCurrency(report.payroll?.deductions || 0)}
                    </span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-gradient-to-r from-purple-100 to-purple-50 dark:from-purple-900/20 dark:to-purple-900/10 rounded-lg border-2 border-purple-200 dark:border-purple-800">
                    <span className="text-sm font-bold dark:text-gray-200">
                      صافي الراتب
                    </span>
                    <span className="font-bold text-xl text-purple-600 dark:text-purple-400">
                      {formatCurrency(report.payroll?.netSalary || 0)}
                    </span>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Performance & Goals */}
          {(report.performance?.lastReview ||
            (report.performance?.activeGoals || 0) > 0) && (
            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
              <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <Target className="h-5 w-5 text-amber-600 dark:text-amber-400" />
                  الأداء والأهداف
                </CardTitle>
              </CardHeader>
              <CardContent className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {report.performance?.lastReview && (
                    <div className="p-4 bg-gradient-to-br from-amber-50 to-orange-50 dark:from-amber-900/10 dark:to-orange-900/10 rounded-lg border border-amber-200 dark:border-amber-800">
                      <div className="flex items-center gap-2 mb-2">
                        <Award className="h-5 w-5 text-amber-600 dark:text-amber-400" />
                        <span className="text-sm font-medium dark:text-gray-300">
                          آخر تقييم
                        </span>
                      </div>
                      <p
                        className={`text-3xl font-bold ${getPerformanceColor(report.performance.lastReview.score)}`}
                      >
                        {report.performance.lastReview.score}/5
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                        {new Date(
                          report.performance.lastReview.date,
                        ).toLocaleDateString("ar-EG")}
                      </p>
                    </div>
                  )}
                  <div className="p-4 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/10 dark:to-indigo-900/10 rounded-lg border border-blue-200 dark:border-blue-800">
                    <div className="flex items-center gap-2 mb-2">
                      <Target className="h-5 w-5 text-blue-600 dark:text-blue-400" />
                      <span className="text-sm font-medium dark:text-gray-300">
                        أهداف نشطة
                      </span>
                    </div>
                    <p className="text-3xl font-bold text-blue-600 dark:text-blue-400">
                      {report.performance?.activeGoals || 0}
                    </p>
                  </div>
                  <div className="p-4 bg-gradient-to-br from-emerald-50 to-green-50 dark:from-emerald-900/10 dark:to-green-900/10 rounded-lg border border-emerald-200 dark:border-emerald-800">
                    <div className="flex items-center gap-2 mb-2">
                      <CheckCircle className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
                      <span className="text-sm font-medium dark:text-gray-300">
                        أهداف مكتملة
                      </span>
                    </div>
                    <p className="text-3xl font-bold text-emerald-600 dark:text-emerald-400">
                      {report.performance?.completedGoals || 0}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Leave Requests */}
          {report.leaves?.requests && report.leaves.requests.length > 0 && (
            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
              <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <Calendar className="h-5 w-5 text-blue-600 dark:text-blue-400" />
                  طلبات الإجازات ({report.leaves.totalDaysTaken} يوم)
                </CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <div className="divide-y dark:divide-gray-700">
                  {report.leaves.requests.map((leave) => (
                    <div
                      key={leave.id}
                      className="p-4 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                    >
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge className={getStatusColor(leave.status)}>
                              {getStatusLabel(leave.status)}
                            </Badge>
                            <span className="text-sm font-medium dark:text-gray-300">
                              {leave.type}
                            </span>
                          </div>
                          <p className="text-sm text-gray-600 dark:text-gray-400">
                            {new Date(leave.startDate).toLocaleDateString(
                              "ar-EG",
                            )}{" "}
                            -{" "}
                            {new Date(leave.endDate).toLocaleDateString(
                              "ar-EG",
                            )}
                          </p>
                          {leave.reason && (
                            <p className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                              {leave.reason}
                            </p>
                          )}
                        </div>
                        <Badge
                          variant="outline"
                          className="dark:border-gray-600"
                        >
                          {leave.days} يوم
                        </Badge>
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Advance Requests */}
          {report.advances?.requests && report.advances.requests.length > 0 && (
            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
              <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <DollarSign className="h-5 w-5 text-green-600 dark:text-green-400" />
                  طلبات السلف ({formatCurrency(report.advances.totalAmount)})
                </CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <div className="divide-y dark:divide-gray-700">
                  {report.advances.requests.map((advance) => (
                    <div
                      key={advance.id}
                      className="p-4 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                    >
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge className={getStatusColor(advance.status)}>
                              {getStatusLabel(advance.status)}
                            </Badge>
                            <span className="text-sm text-gray-500 dark:text-gray-400">
                              {new Date(advance.requestDate).toLocaleDateString(
                                "ar-EG",
                              )}
                            </span>
                          </div>
                          {advance.reason && (
                            <p className="text-xs text-gray-500 dark:text-gray-500">
                              {advance.reason}
                            </p>
                          )}
                        </div>
                        <span className="font-bold text-lg text-green-600 dark:text-green-400">
                          {formatCurrency(advance.amount)}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Permission Requests */}
          {report.permissions?.requests &&
            report.permissions.requests.length > 0 && (
              <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
                <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                  <CardTitle className="flex items-center gap-2 text-lg">
                    <Clock className="h-5 w-5 text-purple-600 dark:text-purple-400" />
                    طلبات الاستئذان ({report.permissions.totalHours} ساعة)
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y dark:divide-gray-700">
                    {report.permissions.requests.map((perm) => (
                      <div
                        key={perm.id}
                        className="p-4 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-2">
                              <Badge className={getStatusColor(perm.status)}>
                                {getStatusLabel(perm.status)}
                              </Badge>
                              <span className="text-sm font-medium dark:text-gray-300">
                                {new Date(perm.date).toLocaleDateString(
                                  "ar-EG",
                                )}
                              </span>
                            </div>
                            <p className="text-sm text-gray-600 dark:text-gray-400">
                              {perm.startTime} - {perm.endTime} (
                              {perm.totalHours} ساعة)
                            </p>
                            {perm.reason && (
                              <p className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                                {perm.reason}
                              </p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}

          {/* Manual Deductions */}
          {report.payroll?.manualDeductions &&
            report.payroll.manualDeductions.length > 0 && (
              <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
                <CardHeader className="border-b dark:border-gray-700 bg-red-50/50 dark:bg-red-950/10">
                  <CardTitle className="flex items-center gap-2 text-lg text-red-700 dark:text-red-400">
                    <DollarSign className="h-5 w-5" />
                    الخصومات المالية الإضافية
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y dark:divide-gray-700">
                    {report.payroll.manualDeductions.map((deduction) => (
                      <div
                        key={deduction.id}
                        className="p-4 hover:bg-red-50/30 dark:hover:bg-red-900/10 transition-colors"
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-2">
                              <Badge
                                className={getStatusColor(deduction.status)}
                              >
                                {getStatusLabel(deduction.status)}
                              </Badge>
                              <span className="text-sm font-medium dark:text-gray-300">
                                {new Date(deduction.date).toLocaleDateString(
                                  "ar-EG",
                                )}
                              </span>
                            </div>
                            <p className="text-sm text-gray-600 dark:text-gray-400">
                              {deduction.reason}
                            </p>
                          </div>
                          <span className="font-bold text-lg text-red-600 dark:text-red-400">
                            {formatCurrency(deduction.amount)}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}

          {/* Warnings */}
          {report.warnings?.total > 0 && (
            <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm overflow-hidden">
              <CardHeader className="border-b dark:border-gray-700 bg-red-50/50 dark:bg-red-950/20">
                <CardTitle className="text-red-700 dark:text-red-400 flex items-center gap-2">
                  <AlertCircle className="h-5 w-5" />
                  الإنذارات والتحذيرات التأديبية
                </CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <div className="divide-y dark:divide-gray-700">
                  {report.warnings?.recent?.map((warning) => (
                    <div
                      key={warning.id}
                      className="p-4 hover:bg-red-50/30 dark:hover:bg-red-900/10 transition-colors"
                    >
                      <div className="flex items-start justify-between gap-4">
                        <div>
                          <p className="font-bold text-red-600 dark:text-red-400">
                            {warning.type}
                          </p>
                          <p className="text-sm text-gray-600 dark:text-gray-400 mt-1 leading-relaxed">
                            {warning.description}
                          </p>
                        </div>
                        <span className="text-[10px] font-bold text-gray-500 bg-gray-100 dark:bg-gray-700 px-2 py-1 rounded whitespace-nowrap">
                          {new Date(warning.date).toLocaleDateString("ar-EG")}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Recent Attendance Records */}
          {report.attendance?.records &&
            report.attendance.records.length > 0 && (
              <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
                <CardHeader className="border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                  <CardTitle className="flex items-center gap-2 text-lg">
                    <Clock className="h-5 w-5 text-gray-600 dark:text-gray-400" />
                    سجل الحضور الأخير
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="overflow-x-auto max-h-[500px]">
                    <table className="w-full">
                      <thead className="bg-gray-50 dark:bg-gray-900/50">
                        <tr>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                            التاريخ
                          </th>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                            الحالة
                          </th>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                            الدخول
                          </th>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                            الخروج
                          </th>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                            ساعات العمل
                          </th>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                            التأخير
                          </th>
                        </tr>
                      </thead>
                      <tbody className="divide-y dark:divide-gray-700 max-h-96 overflow-y-auto">
                        {report.attendance.records.map((record, index) => (
                          <tr
                            key={index}
                            className="hover:bg-gray-50 dark:hover:bg-gray-700/50"
                          >
                            <td className="px-4 py-3 text-sm dark:text-gray-300">
                              {new Date(record.date).toLocaleDateString(
                                "ar-EG",
                              )}
                            </td>
                            <td className="px-4 py-3">
                              <Badge className={getStatusColor(record.status)}>
                                {getStatusLabel(record.status)}
                              </Badge>
                            </td>
                            <td className="px-4 py-3 text-sm dark:text-gray-300">
                              {record.checkIn
                                ? new Date(record.checkIn).toLocaleTimeString(
                                    "ar-EG",
                                    { hour: "2-digit", minute: "2-digit" },
                                  )
                                : "-"}
                            </td>
                            <td className="px-4 py-3 text-sm dark:text-gray-300">
                              {record.checkOut
                                ? new Date(record.checkOut).toLocaleTimeString(
                                    "ar-EG",
                                    { hour: "2-digit", minute: "2-digit" },
                                  )
                                : "-"}
                            </td>
                            <td className="px-4 py-3 text-sm dark:text-gray-300">
                              {record.workHours?.toFixed(1) || 0}h
                            </td>
                            <td className="px-4 py-3 text-sm dark:text-gray-300">
                              {record.lateMinutes > 0
                                ? `${record.lateMinutes} دقيقة`
                                : "-"}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </CardContent>
              </Card>
            )}
        </>
      ) : (
        <Card className="dark:bg-gray-800 dark:border-gray-700 border-none shadow-sm">
          <CardContent className="p-20">
            <div className="text-center text-gray-500 dark:text-gray-400">
              <FileText className="w-20 h-20 mx-auto mb-6 opacity-20" />
              <h3 className="text-xl font-bold dark:text-white">
                جاهز لعرض التقرير
              </h3>
              <p className="mt-2">
                اختر موظف وحدد الفترة الزمنية من القائمة أعلاه
              </p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default EmployeeReport;

import React, { useState, useEffect } from "react";
import {
  Settings,
  Clock,
  Calendar,
  DollarSign,
  TrendingUp,
  Users,
  Award,
  GraduationCap,
  AlertTriangle,
  FileText,
  BarChart3,
  ChevronLeft,
} from "lucide-react";
import { useNavigate, useSearchParams } from "react-router-dom";
import ErrorBoundary from "../../../components/ErrorBoundary";
import AttendanceReport from "./AttendanceReport";
import LeaveReport from "./LeaveReport";
import PayrollReport from "./PayrollReport";
import PerformanceReport from "./PerformanceReport";
import TurnoverReport from "./TurnoverReport";
import OvertimeReport from "./OvertimeReport";
import LateAbsenceReport from "./LateAbsenceReport";
import EmployeeReport from "./EmployeeReport";

type TabId =
  | "employee"
  | "attendance"
  | "leaves"
  | "payroll"
  | "performance"
  | "turnover"
  | "overtime"
  | "late-absence"
  | "training"
  | "warnings"
  | "kpis";

interface Tab {
  id: TabId;
  label: string;
  icon: React.ElementType;
  description: string;
}

const HRReportsHub: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const [activeTab, setActiveTab] = useState<TabId>(
    (searchParams.get("tab") as TabId) || "employee",
  );

  useEffect(() => {
    const tab = searchParams.get("tab") as TabId;
    if (tab && tab !== activeTab) {
      setActiveTab(tab);
    }
  }, [searchParams]);

  const handleTabChange = (tabId: TabId) => {
    setActiveTab(tabId);
    setSearchParams({ tab: tabId });
  };

  const tabs: Tab[] = [
    {
      id: "employee",
      label: "تقرير الموظف الشامل",
      icon: Users,
      description: "جميع أنشطة موظف معين",
    },
    {
      id: "attendance",
      label: "تقرير الحضور",
      icon: Clock,
      description: "الحضور والانصراف والتأخير",
    },
    {
      id: "leaves",
      label: "تقرير الإجازات",
      icon: Calendar,
      description: "طلبات الإجازات والرصيد",
    },
    {
      id: "payroll",
      label: "تقرير الرواتب",
      icon: DollarSign,
      description: "الرواتب والبدلات والخصومات",
    },
    {
      id: "performance",
      label: "تقرير الأداء",
      icon: Award,
      description: "تقييمات الأداء والأهداف",
    },
    {
      id: "turnover",
      label: "معدل دوران الموظفين",
      icon: Users,
      description: "التوظيف والاستقالات",
    },
    {
      id: "overtime",
      label: "تقرير العمل الإضافي",
      icon: TrendingUp,
      description: "ساعات العمل الإضافي",
    },
    {
      id: "late-absence",
      label: "التأخير والغياب",
      icon: AlertTriangle,
      description: "تحليل التأخير والغياب",
    },
    {
      id: "training",
      label: "تقرير التدريب",
      icon: GraduationCap,
      description: "البرامج التدريبية",
    },
    {
      id: "warnings",
      label: "تقرير الإنذارات",
      icon: FileText,
      description: "الإنذارات والجزاءات",
    },
    {
      id: "kpis",
      label: "مؤشرات الأداء",
      icon: BarChart3,
      description: "KPIs الموارد البشرية",
    },
  ];

