            <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <Info className="w-5 h-5 text-blue-600" />
              نوع المكافأة
            </h3>
            <div className="space-y-3">
              <div>
                <p className="text-sm text-gray-600">الاسم</p>
                <p className="text-base font-medium text-gray-900">
                  {rewardTypeName}
                </p>
              </div>
              {rewardTypeNameAr && (
                <div>
                  <p className="text-sm text-gray-600">الاسم بالعربية</p>
                  <p className="text-base font-medium text-gray-900">
                    {rewardTypeNameAr}
                  </p>
                </div>
              )}
              <div>
                <p className="text-sm text-gray-600">طريقة الحساب</p>
                <p className="text-base font-medium text-gray-900">
                  {rewardTypeCalculationMethod}
                </p>
              </div>
              <div>
                <p className="text-sm text-gray-600">التكرار</p>
                <p className="text-base font-medium text-gray-900">
                  {rewardTypeFrequency}
                </p>
              </div>
              {rewardTypeDescription && (
                <div>
                  <p className="text-sm text-gray-600">الوصف</p>
                  <p className="text-sm text-gray-700">
                    {rewardTypeDescription}
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* Timeline */}
          <div className="bg-white rounded-lg shadow p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">
              السجل الزمني
            </h3>
            <div className="space-y-4">
              <div className="flex items-start gap-3">
                <div className="w-2 h-2 bg-blue-500 rounded-full mt-2"></div>
                <div>
                  <p className="text-sm font-medium text-gray-900">
                    تم الإنشاء
                  </p>
                  <p className="text-xs text-gray-600">
                    {new Date(reward.createdAt).toLocaleString("ar-EG")}
                  </p>
                </div>
              </div>

              {reward.approvedAt && (
                <div className="flex items-start gap-3">
                  <div className="w-2 h-2 bg-green-500 rounded-full mt-2"></div>
                  <div>
                    <p className="text-sm font-medium text-gray-900">
                      تم الاعتماد
                    </p>
                    <p className="text-xs text-gray-600">
                      {new Date(reward.approvedAt).toLocaleString("ar-EG")}
                    </p>
                  </div>
                </div>
              )}

              {reward.appliedAt && (
                <div className="flex items-start gap-3">
                  <div className="w-2 h-2 bg-blue-500 rounded-full mt-2"></div>
                  <div>
                    <p className="text-sm font-medium text-gray-900">
                      تم التطبيق
                    </p>
                    <p className="text-xs text-gray-600">
                      {new Date(reward.appliedAt).toLocaleString("ar-EG")}
                    </p>
                  </div>
                </div>
              )}

              {reward.voidedAt && (
                <div className="flex items-start gap-3">
                  <div className="w-2 h-2 bg-red-500 rounded-full mt-2"></div>
                  <div>
                    <p className="text-sm font-medium text-gray-900">
                      تم الإلغاء
                    </p>
                    <p className="text-xs text-gray-600">
                      {new Date(reward.voidedAt).toLocaleString("ar-EG")}
                    </p>
                    {reward.voidReason && (
                      <p className="text-xs text-gray-600 mt-1">
                        السبب: {reward.voidReason}
                      </p>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RewardDetails;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../../components/ui/card";
import { Button } from "../../../components/ui/button";
import { Input } from "../../../components/ui/input";
import { Label } from "../../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../../components/ui/select";
import { Switch } from "../../../components/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from "../../../components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../../components/ui/table";
import { Plus, Edit, Trash2, Check, X, AlertCircle } from "lucide-react";
import { toast } from "react-hot-toast";
import api from "../../../services/api";

interface RewardType {
  id: string;
  name: string;
  category: string;
  calculationMethod: string;
  value: number;
  isActive: boolean;
  triggerType: string;
  eligibilityConditions: any;
}

const RewardTypes: React.FC = () => {
  const { t } = useTranslation();
  const [types, setTypes] = useState<RewardType[]>([]);
  const [loading, setLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingType, setEditingType] = useState<RewardType | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: "",
    category: "PERFORMANCE",
    calculationMethod: "FIXED_AMOUNT",
    value: 0,
    triggerType: "SEMI_AUTOMATIC",
    eligibilityConditions: {
      minTargetProgress: 0,
      maxLatenessCount: 0,
      maxAbsenceCount: 0,
      maxErrorRate: 0,
      minProjectScore: 0,
      minSalesAmount: 0,
      requiresManagerNomination: false,
      requiresHRApproval: false,
    },
  });

  useEffect(() => {
    fetchTypes();
  }, []);

  const fetchTypes = async () => {
    try {
      setLoading(true);
      const response = await api.get("/hr/rewards/types");
      if (response.data.success) {
        setTypes(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching types:", error);
      toast.error("فشل تحميل أنواع المكافآت");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async () => {
    try {
      if (!formData.name) return toast.error("يرجى إدخال اسم المكافأة");

      let response;
      if (editingType) {
        response = await api.put(
          `/hr/rewards/types/${editingType.id}`,
          formData,
        );
      } else {
        response = await api.post("/hr/rewards/types", formData);
      }

      if (response.data.success) {
        toast.success(editingType ? "تم التعديل بنجاح" : "تم الإنشاء بنجاح");
        setIsDialogOpen(false);
        fetchTypes();
        resetForm();
      }
    } catch (error) {
      console.error("Error saving type:", error);
      toast.error("حدث خطأ أثناء الحفظ");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من الحذف؟")) return;
    try {
      await api.delete(`/hr/rewards/types/${id}`);
      toast.success("تم الحذف بنجاح");
      fetchTypes();
    } catch (error) {
      toast.error("لا يمكن حذف هذا النوع لارتباطه بسجلات سابقة");
    }
  };

  const handleToggleStatus = async (id: string, currentStatus: boolean) => {
    try {
      await api.patch(`/hr/rewards/types/${id}/toggle`, {
        isActive: !currentStatus,
      });
      toast.success("تم تغيير الحالة");
      fetchTypes();
    } catch (error) {
      toast.error("فشل تغيير الحالة");
    }
  };

  const resetForm = () => {
    setEditingType(null);
    setFormData({
      name: "",
      category: "PERFORMANCE",
      calculationMethod: "FIXED_AMOUNT",
      value: 0,
      triggerType: "SEMI_AUTOMATIC",
      eligibilityConditions: {
        minTargetProgress: 0,
        maxLatenessCount: 0,
        maxAbsenceCount: 0,
        maxErrorRate: 0,
        minProjectScore: 0,
        minSalesAmount: 0,
        requiresManagerNomination: false,
        requiresHRApproval: false,
      },
    });
  };

  const openEdit = (type: any) => {
    setEditingType(type);
    setFormData({
      name: type.name,
      category: type.category,
      calculationMethod: type.calculationMethod,
      value: type.value,
      triggerType: type.triggerType,
      eligibilityConditions: type.eligibilityConditions || {
        minTargetProgress: 0,
        maxLatenessCount: 0,
        maxAbsenceCount: 0,
        maxErrorRate: 0,
        minProjectScore: 0,
        minSalesAmount: 0,
        requiresManagerNomination: false,
        requiresHRApproval: false,
      },
    });
    setIsDialogOpen(true);
  };

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle>أنواع المكافآت</CardTitle>
          <CardDescription>إدارة تعريفات المكافآت والحوافز</CardDescription>
        </div>
        <Button
          onClick={() => {
            resetForm();
            setIsDialogOpen(true);
          }}
        >
          <Plus className="h-4 w-4 ml-2" />
          إضافة جديد
        </Button>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>الاسم</TableHead>
              <TableHead>التصنيف</TableHead>
              <TableHead>القيمة</TableHead>
              <TableHead>الحالة</TableHead>
              <TableHead>الإجراءات</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {types.map((type) => (
              <TableRow key={type.id}>
                <TableCell className="font-medium">{type.name}</TableCell>
                <TableCell>
                  {t(`rewards.category.${type.category}`) || type.category}
                </TableCell>
                <TableCell>
                  {type.calculationMethod === "FIXED_AMOUNT"
                    ? `${type.value} جنية`
                    : `${type.value}%`}
                </TableCell>
                <TableCell>
                  <Switch
                    checked={type.isActive}
                    onCheckedChange={() =>
                      handleToggleStatus(type.id, type.isActive)
                    }
                  />
                </TableCell>
                <TableCell className="flex gap-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => openEdit(type)}
                  >
                    <Edit className="h-4 w-4 text-blue-500" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleDelete(type.id)}
                  >
                    <Trash2 className="h-4 w-4 text-red-500" />
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>

        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>
                {editingType ? "تعديل مكافأة" : "إضافة مكافأة جديدة"}
              </DialogTitle>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label>اسم المكافأة</Label>
                <Input
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  placeholder="مثال: مكافأة التميز"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>التصنيف</Label>
                  <Select
                    value={formData.category}
                    onValueChange={(v) =>
                      setFormData({ ...formData, category: v })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="PERFORMANCE">أداء عام</SelectItem>
                      <SelectItem value="TARGET_ACHIEVEMENT">
                        تحقيق التارجت
                      </SelectItem>
                      <SelectItem value="TARGET_EXCEED">
                        تجاوز التارجت
                      </SelectItem>
                      <SelectItem value="PUNCTUALITY">
                        التزام بالمواعيد
                      </SelectItem>
                      <SelectItem value="NO_ABSENCE">عدم غياب</SelectItem>
                      <SelectItem value="QUALITY">جودة العمل</SelectItem>
                      <SelectItem value="EMPLOYEE_OF_MONTH">
                        موظف الشهر
                      </SelectItem>
                      <SelectItem value="INITIATIVE">مبادرة مميزة</SelectItem>
                      <SelectItem value="PROJECT_SUCCESS">
                        مشروع ناجح
                      </SelectItem>
                      <SelectItem value="SALES">مبيعات</SelectItem>
                      <SelectItem value="ADMINISTRATIVE">
                        مكافأة إدارية
                      </SelectItem>
                      <SelectItem value="SEASONAL">موسمي</SelectItem>
                      <SelectItem value="ACHIEVEMENT">إنجاز آخر</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label>طريقة الحساب</Label>
                  <Select
                    value={formData.calculationMethod}
                    onValueChange={(v) =>
                      setFormData({ ...formData, calculationMethod: v })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="FIXED_AMOUNT">مبلغ ثابت</SelectItem>
                      <SelectItem value="PERCENTAGE_SALARY">
                        نسبة من الراتب
                      </SelectItem>
                      <SelectItem value="PERCENTAGE_SALES">
                        نسبة من المبيعات
                      </SelectItem>
                      <SelectItem value="PERCENTAGE_PROJECT_PROFIT">
                        نسبة من أرباح المشروع
                      </SelectItem>
                      <SelectItem value="POINTS">نقاط</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2">
                <Label>
                  القيمة{" "}
                  {[
                    "PERCENTAGE_SALARY",
                    "PERCENTAGE_SALES",
                    "PERCENTAGE_PROJECT_PROFIT",
                  ].includes(formData.calculationMethod)
                    ? "(%)"
                    : ""}
                </Label>
                <Input
                  type="number"
                  value={formData.value}
                  onChange={(e) =>
                    setFormData({ ...formData, value: Number(e.target.value) })
                  }
                />
              </div>

              {/* Eligibility Conditions Section */}
              <div className="p-4 bg-gray-50 rounded-lg space-y-4 border border-gray-200">
                <Label className="text-blue-600 font-bold block mb-2 border-b pb-2">
                  شروط الاستحقاق
                </Label>

                {["TARGET_ACHIEVEMENT", "TARGET_EXCEED"].includes(
                  formData.category,
                ) && (
                  <div className="space-y-2">
                    <Label>الحد الأدنى لتحقيق التارجت (%)</Label>
                    <Input
                      type="number"
                      value={formData.eligibilityConditions.minTargetProgress}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            minTargetProgress: Number(e.target.value),
                          },
                        })
                      }
                    />
                  </div>
                )}

                {formData.category === "PUNCTUALITY" && (
                  <div className="space-y-2">
                    <Label>أقصى عدد مرات تأخير مسموح</Label>
                    <Input
                      type="number"
                      value={formData.eligibilityConditions.maxLatenessCount}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            maxLatenessCount: Number(e.target.value),
                          },
                        })
                      }
                    />
                  </div>
                )}

                {formData.category === "NO_ABSENCE" && (
                  <div className="space-y-2">
                    <Label>أقصى عدد أيام غياب مسموح</Label>
                    <Input
                      type="number"
                      value={formData.eligibilityConditions.maxAbsenceCount}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            maxAbsenceCount: Number(e.target.value),
                          },
                        })
                      }
                    />
                  </div>
                )}

                {formData.category === "QUALITY" && (
                  <div className="space-y-2">
                    <Label>أقصى نسبة أخطاء مسموحة (%)</Label>
                    <Input
                      type="number"
                      value={formData.eligibilityConditions.maxErrorRate}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            maxErrorRate: Number(e.target.value),
                          },
                        })
                      }
                    />
                  </div>
                )}

                {formData.category === "PROJECT_SUCCESS" && (
                  <div className="space-y-2">
                    <Label>الحد الأدنى لتقييم المشروع</Label>
                    <Input
                      type="number"
                      value={formData.eligibilityConditions.minProjectScore}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            minProjectScore: Number(e.target.value),
                          },
                        })
                      }
                    />
                  </div>
                )}

                {formData.category === "SALES" && (
                  <div className="space-y-2">
                    <Label>الحد الأدنى لقيمة المبيعات</Label>
                    <Input
                      type="number"
                      value={formData.eligibilityConditions.minSalesAmount}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            minSalesAmount: Number(e.target.value),
                          },
                        })
                      }
                    />
                  </div>
                )}

                <div className="flex items-center justify-between gap-4 pt-2">
                  <div className="flex items-center space-x-2 space-x-reverse">
                    <Switch
                      checked={
                        formData.eligibilityConditions.requiresManagerNomination
                      }
                      onCheckedChange={(checked) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            requiresManagerNomination: checked,
                          },
                        })
                      }
                    />
                    <Label>ترشيح مدير</Label>
                  </div>
                  <div className="flex items-center space-x-2 space-x-reverse">
                    <Switch
                      checked={
                        formData.eligibilityConditions.requiresHRApproval
                      }
                      onCheckedChange={(checked) =>
                        setFormData({
                          ...formData,
                          eligibilityConditions: {
                            ...formData.eligibilityConditions,
                            requiresHRApproval: checked,
                          },
                        })
                      }
                    />
                    <Label>موافقة HR</Label>
                  </div>
                </div>
              </div>
            </div>
            <DialogFooter>
              <Button onClick={handleSubmit}>حفظ</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </CardContent>
    </Card>
  );
};

export default RewardTypes;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../../services/apiClient";
import {
  Award,
  Search,
  Filter,
  Plus,
  Eye,
  Edit,
  Trash2,
  RefreshCw,
  DollarSign,
  CheckCircle,
  XCircle,
  Clock,
  AlertCircle,
  Check,
  X,
} from "lucide-react";

const API_URL =
  (import.meta as any).env["VITE_API_URL"] || "http://localhost:3007/api/v1";

interface RewardRecord {
  id: string;
  rewardName: string;
  rewardCategory: string;
  calculatedValue: number;
  status: string;
  appliedMonth: number;
  appliedYear: number;
  periodStart: string;
  periodEnd: string;
  reason?: string;
  createdAt: string;
  user: {
    id: string;
    firstName: string;
    lastName: string;
    employeeNumber: string;
    departmentRelation?: { name: string };
  };
  rewardType: {
    name: string;
    nameAr?: string;
    category: string;
  };
}

interface Statistics {
  total: number;
  totalValue: number;
  byStatus: Array<{ status: string; count: number; value: number }>;
  byCategory: Array<{ category: string; count: number; value: number }>;
}

const RewardsList: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [records, setRecords] = useState<RewardRecord[]>([]);
  const [statistics, setStatistics] = useState<Statistics | null>(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0,
  });

  // Filters
  const [filters, setFilters] = useState({
    search: "",
    status: "",
    category: "",
    month: "",
    year: new Date().getFullYear().toString(),
    userId: "",
    rewardTypeId: "",
  });

  const [showFilters, setShowFilters] = useState(false);

  useEffect(() => {
    fetchRewards();
    fetchStatistics();
  }, [pagination.page, filters]);

  const fetchRewards = async () => {
    try {
      setLoading(true);
      setError(null);

      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
        ...Object.fromEntries(
          Object.entries(filters).filter(([_, v]) => v !== ""),
        ),
      });

      const response = await apiClient.get(`/hr/rewards/records?${params}`);

      if (response.data.success) {
        setRecords(response.data.records || []);
        setPagination((prev) => ({
          ...prev,
          ...response.data.pagination,
        }));
      }
    } catch (err: any) {
      console.error("Error fetching rewards:", err);
      setError(err.response?.data?.message || "فشل في تحميل المكافآت");
    } finally {
      setLoading(false);
    }
  };

  const fetchStatistics = async () => {
    try {
      const params = new URLSearchParams({
        month: filters.month,
        year: filters.year,
      });

      const response = await apiClient.get(`/hr/rewards/statistics?${params}`);

      if (response.data.success) {
        setStatistics(response.data.data);
      }
    } catch (err) {
      console.error("Error fetching statistics:", err);
    }
  };

  const handleStatusUpdate = async (
    id: string,
    action: "approve" | "reject",
  ) => {
    try {
      setLoading(true);
      await apiClient.patch(`/hr/rewards/${action}/${id}`);
      alert(action === "approve" ? "تم اعتماد المكافأة" : "تم رفض المكافأة");
      fetchRewards();
      fetchStatistics();
    } catch (err: any) {
      alert(err.response?.data?.message || "فشل تحديث الحالة");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذه المكافأة؟")) return;

    try {
      await apiClient.delete(`/hr/rewards/records/${id}`);

      fetchRewards();
      fetchStatistics();
    } catch (err: any) {
      alert(err.response?.data?.message || "فشل في حذف المكافأة");
    }
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: Record<
      string,
      { label: string; className: string; icon: any }
    > = {
      PENDING: {
        label: "قيد الانتظار",
        className: "bg-yellow-100 text-yellow-800",
        icon: Clock,
      },
      APPROVED: {
        label: "معتمد",
        className: "bg-green-100 text-green-800",
        icon: CheckCircle,
      },
      APPLIED: {
        label: "مطبق",
        className: "bg-blue-100 text-blue-800",
        icon: CheckCircle,
      },
      REJECTED: {
        label: "مرفوض",
        className: "bg-red-100 text-red-800",
        icon: XCircle,
      },
      VOIDED: {
        label: "ملغي",
        className: "bg-gray-100 text-gray-800",
        icon: XCircle,
      },
    };

    const config = statusConfig[status] || statusConfig["PENDING"];
    const Icon = config.icon;

    return (
      <span
        className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${config.className}`}
      >
        <Icon className="w-3 h-3" />
        {config.label}
      </span>
    );
  };

  const getCategoryBadge = (category: string) => {
    const categoryConfig: Record<string, { label: string; className: string }> =
      {
        ATTENDANCE: {
          label: "حضور وانضباط",
          className: "bg-blue-100 text-blue-800",
        },
        PERFORMANCE: {
          label: "أداء متميز",
          className: "bg-purple-100 text-purple-800",
        },
        ACHIEVEMENT: {
          label: "إنجاز",
          className: "bg-green-100 text-green-800",
        },
        SEASONAL: {
          label: "موسمية",
          className: "bg-orange-100 text-orange-800",
        },
        TEAM_BASED: {
          label: "فريق",
          className: "bg-indigo-100 text-indigo-800",
        },
        COMPANY_WIDE: { label: "عامة", className: "bg-pink-100 text-pink-800" },
        TARGET_ACHIEVEMENT: {
          label: "تحقيق تارجت",
          className: "bg-emerald-100 text-emerald-800",
        },
        TARGET_EXCEED: {
          label: "تجاوز تارجت",
          className: "bg-cyan-100 text-cyan-800",
        },
        PUNCTUALITY: {
          label: "التزام بالمواعيد",
          className: "bg-sky-100 text-sky-800",
        },
        NO_ABSENCE: {
          label: "عدم غياب",
          className: "bg-teal-100 text-teal-800",
        },
        QUALITY: {
          label: "جودة العمل",
          className: "bg-violet-100 text-violet-800",
        },
        EMPLOYEE_OF_MONTH: {
          label: "موظف الشهر",
          className: "bg-amber-100 text-amber-800",
        },
        INITIATIVE: {
          label: "مبادرة مميزة",
          className: "bg-rose-100 text-rose-800",
        },
        PROJECT_SUCCESS: {
          label: "مشروع ناجح",
          className: "bg-lime-100 text-lime-800",
        },
        SALES: { label: "مبيعات", className: "bg-blue-100 text-blue-800" },
        ADMINISTRATIVE: {
          label: "مكافأة إدارية",
          className: "bg-slate-100 text-slate-800",
        },
        OTHER: { label: "أخرى", className: "bg-gray-100 text-gray-800" },
      };

    const config = categoryConfig[category] || categoryConfig["OTHER"];

    return (
      <span
        className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${config.className}`}
      >
        {config.label}
      </span>
    );
  };

  if (loading && records.length === 0) {
    return (
      <div className="flex items-center justify-center h-64 min-h-screen bg-gray-50 dark:bg-gray-900">
        <div className="text-center">
          <RefreshCw className="w-8 h-8 animate-spin text-blue-500 mx-auto mb-2" />
          <p className="text-gray-600 dark:text-gray-400">
            جاري تحميل المكافآت...
          </p>
        </div>
      </div>
    );
  }

  if (error && records.length === 0) {
    return (
      <div className="flex items-center justify-center h-64 min-h-screen bg-gray-50 dark:bg-gray-900">
        <div className="text-center">
          <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
            حدث خطأ
          </h3>
          <p className="text-gray-600 dark:text-gray-400 mb-4">{error}</p>
          <button
            onClick={() => fetchRewards()}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            إعادة المحاولة
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <Award className="w-8 h-8 text-blue-600" />
            إدارة المكافآت
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            عرض وإدارة جميع مكافآت الموظفين
          </p>
        </div>
        <button
          onClick={() => navigate("/hr/rewards/create")}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <Plus className="w-5 h-5" />
          إضافة مكافأة
        </button>
      </div>

      {/* Statistics Cards */}
      {statistics && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  إجمالي المكافآت
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {statistics.total}
                </p>
              </div>
              <Award className="w-10 h-10 text-blue-500" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  القيمة الإجمالية
                </p>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">
                  {statistics.totalValue.toLocaleString()} ج.م
                </p>
              </div>
              <DollarSign className="w-10 h-10 text-green-500" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  معتمد
                </p>
                <p className="text-2xl font-bold text-green-600">
                  {statistics.byStatus.find((s) => s.status === "APPROVED")
                    ?.count || 0}
                </p>
              </div>
              <CheckCircle className="w-10 h-10 text-green-500" />
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  قيد الانتظار
                </p>
                <p className="text-2xl font-bold text-yellow-600">
                  {statistics.byStatus.find((s) => s.status === "PENDING")
                    ?.count || 0}
                </p>
              </div>
              <Clock className="w-10 h-10 text-yellow-500" />
            </div>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
        <div className="flex items-center justify-between mb-4">
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="flex items-center gap-2 text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white"
          >
            <Filter className="w-5 h-5" />
            الفلاتر
          </button>
          <button
            onClick={() => {
              setFilters({
                search: "",
                status: "",
                category: "",
                month: "",
                year: new Date().getFullYear().toString(),
                userId: "",
                rewardTypeId: "",
              });
              setPagination((prev) => ({ ...prev, page: 1 }));
            }}
            className="text-sm text-blue-600 hover:text-blue-700"
          >
            إعادة تعيين
          </button>
        </div>

        {showFilters && (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                بحث
              </label>
              <div className="relative">
                <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={filters.search}
                  onChange={(e) =>
                    setFilters((prev) => ({ ...prev, search: e.target.value }))
                  }
                  placeholder="ابحث..."
                  className="w-full pr-10 pl-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                الحالة
              </label>
              <select
                value={filters.status}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, status: e.target.value }))
                }
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500"
              >
                <option value="">الكل</option>
                <option value="PENDING">قيد الانتظار</option>
                <option value="APPROVED">معتمد</option>
                <option value="APPLIED">مطبق</option>
                <option value="REJECTED">مرفوض</option>
                <option value="VOIDED">ملغي</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                التصنيف
              </label>
              <select
                value={filters.category}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, category: e.target.value }))
                }
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500"
              >
                <option value="">الكل</option>
                <option value="ATTENDANCE">حضور</option>
                <option value="PERFORMANCE">أداء</option>
                <option value="ACHIEVEMENT">إنجاز</option>
                <option value="SEASONAL">موسمية</option>
                <option value="TEAM_BASED">فريق</option>
                <option value="COMPANY_WIDE">عامة</option>
                <option value="OTHER">أخرى</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                السنة
              </label>
              <select
                value={filters.year}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, year: e.target.value }))
                }
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500"
              >
                {[2024, 2025, 2026].map((year) => (
                  <option key={year} value={year}>
                    {year}
                  </option>
                ))}
              </select>
            </div>
          </div>
        )}
      </div>

      {/* Records Table */}
      {records.length === 0 ? (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-12 text-center">
          <Award className="w-16 h-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
            لا توجد مكافآت
          </h3>
          <p className="text-gray-600 dark:text-gray-400 mb-4">
            لم يتم العثور على أي مكافآت بالفلاتر المحددة
          </p>
          <button
            onClick={() => navigate("/hr/rewards/create")}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            إضافة مكافأة جديدة
          </button>
        </div>
      ) : (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow overflow-hidden">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-50 dark:bg-gray-900">
                <tr>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    الموظف
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    المكافأة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    التصنيف
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    القيمة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    الفترة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    الحالة
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                    إجراءات
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                {records.map((record) => (
                  <tr
                    key={record.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-700"
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div>
                        <div className="text-sm font-medium text-gray-900 dark:text-white">
                          {record.user.firstName} {record.user.lastName}
                        </div>
                        <div className="text-sm text-gray-500 dark:text-gray-400">
                          {record.user.employeeNumber}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm text-gray-900 dark:text-white">
                        {record.rewardType?.nameAr || record.rewardName}
                      </div>
                      {record.reason && (
                        <div className="text-sm text-gray-500 truncate max-w-xs">
                          {record.reason}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getCategoryBadge(record.rewardCategory)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm font-semibold text-green-600">
                        {record.calculatedValue.toLocaleString()} ج.م
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-gray-900 dark:text-white">
                        {record.appliedMonth}/{record.appliedYear}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getStatusBadge(record.status)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">
                      <div className="flex items-center gap-2">
                        <button
                          onClick={() => navigate(`/hr/rewards/${record.id}`)}
                          className="text-blue-600 hover:text-blue-700"
                          title="عرض التفاصيل"
                        >
                          <Eye className="w-5 h-5" />
                        </button>
                        {record.status === "PENDING" && (
                          <>
                            <button
                              onClick={() =>
                                handleStatusUpdate(record.id, "approve")
                              }
                              className="text-green-600 hover:text-green-700"
                              title="اعتماد"
                            >
                              <Check className="w-5 h-5" />
                            </button>
                            <button
                              onClick={() =>
                                handleStatusUpdate(record.id, "reject")
                              }
                              className="text-orange-600 hover:text-orange-700"
                              title="رفض"
                            >
                              <X className="w-5 h-5" />
                            </button>
                            <button
                              onClick={() =>
                                navigate(`/hr/rewards/edit/${record.id}`)
                              }
                              className="text-blue-600 hover:text-blue-700"
                              title="تعديل"
                            >
                              <Edit className="w-5 h-5" />
                            </button>
                            <button
                              onClick={() => handleDelete(record.id)}
                              className="text-red-600 hover:text-red-700"
                              title="حذف"
                            >
                              <Trash2 className="w-5 h-5" />
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {pagination.totalPages > 1 && (
            <div className="px-6 py-4 border-t border-gray-200 dark:border-gray-700 flex items-center justify-between">
              <div className="text-sm text-gray-700 dark:text-gray-300">
                عرض {(pagination.page - 1) * pagination.limit + 1} إلى{" "}
                {Math.min(pagination.page * pagination.limit, pagination.total)}{" "}
                من {pagination.total} نتيجة
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() =>
                    setPagination((prev) => ({ ...prev, page: prev.page - 1 }))
                  }
                  disabled={pagination.page === 1}
                  className="px-3 py-1 border border-gray-300 dark:border-gray-600 rounded hover:bg-gray-50 dark:hover:bg-gray-700 dark:text-gray-300 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  السابق
                </button>
                <button
                  onClick={() =>
                    setPagination((prev) => ({ ...prev, page: prev.page + 1 }))
                  }
                  disabled={pagination.page === pagination.totalPages}
                  className="px-3 py-1 border border-gray-300 dark:border-gray-600 rounded hover:bg-gray-50 dark:hover:bg-gray-700 dark:text-gray-300 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  التالي
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default RewardsList;

import React, { useEffect, useMemo, useState } from "react";
import { Link, useNavigate, useParams, useSearchParams } from "react-router-dom";
import {
  ArrowLeft,
  ChevronDown,
  ChevronUp,
  CopyPlus,
  Eye,
  GripVertical,
  Plus,
  Save,
  Sparkles,
  Trash2,
} from "lucide-react";
import { toast } from "react-hot-toast";
import { companyAwareApi } from "../../../services/companyAwareApi";
import {
  buildMessagingPreset,
  CADENCE_OPTIONS,
  DATA_TYPE_OPTIONS,
  FIELD_SOURCE_OPTIONS,
  SYSTEM_FIELD_OPTIONS,
} from "./catalog";
import { slugifyFieldKey } from "./utils";
import { WorkReportField, WorkReportFieldDataType, WorkReportTemplateDraft } from "./types";

const buildBlankField = (index: number): WorkReportField => ({
  key: `field_${index + 1}`,
  label: "",
  helpText: "",
  sourceType: "MANUAL",
  dataType: "TEXT",
  isRequired: false,
  isVisible: true,
  placeholder: "",
  orderIndex: index,
  systemKey: null,
  formula: null,
  options: [],
});

const cloneDraft = (draft: WorkReportTemplateDraft) => ({
  ...draft,
  fields: draft.fields.map((field, index) => ({
    ...field,
    options: [...field.options],
    orderIndex: index,
  })),
});

const BuilderBadge: React.FC<{ label: string; tone?: string }> = ({
  label,
  tone = "border-slate-200 bg-slate-50 text-slate-600 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-300",
}) => (
  <span className={`inline-flex items-center rounded-full border px-2.5 py-1 text-xs font-medium ${tone}`}>
    {label}
  </span>
);

const WorkReportFormBuilder: React.FC = () => {
  const navigate = useNavigate();
  const { formId } = useParams<{ formId: string }>();
  const [searchParams] = useSearchParams();
  const isEditing = Boolean(formId);
  const [loading, setLoading] = useState(isEditing);
  const [saving, setSaving] = useState(false);
  const [formState, setFormState] = useState<WorkReportTemplateDraft>({
    title: "",
    description: "",
    cadence: "DAILY",
    isActive: true,
    allowMultipleSubmissions: false,
    fields: [],
  });

  const applyDraft = (draft: WorkReportTemplateDraft) => {
    setFormState(cloneDraft(draft));
  };

  useEffect(() => {
    const loadExistingForm = async () => {
      if (!formId) return;

      try {
        setLoading(true);
        const response = await companyAwareApi.get<{ data: WorkReportTemplateDraft }>(
          `/hr/reporting/forms/${formId}`,
        );
        if (response.data?.data) {
          applyDraft(response.data.data);
        }
      } catch (error) {
        console.error("Error fetching reporting form:", error);
        toast.error("تعذر تحميل الفورم");
      } finally {
        setLoading(false);
      }
    };

    loadExistingForm();
  }, [formId]);

  useEffect(() => {
    if (isEditing) return;

    const presetName = searchParams.get("preset");
    const storedPreset = sessionStorage.getItem("work-report-form-preset");

    if (storedPreset) {
      try {
        const parsed = JSON.parse(storedPreset) as WorkReportTemplateDraft;
        applyDraft(parsed);
        sessionStorage.removeItem("work-report-form-preset");
        return;
      } catch (error) {
        sessionStorage.removeItem("work-report-form-preset");
      }
    }

    if (presetName === "messaging") {
      applyDraft(buildMessagingPreset());
    }
  }, [isEditing, searchParams]);

  const visibleCounts = useMemo(() => {
    const sourceCount = {
      SYSTEM: 0,
      MANUAL: 0,
      CALCULATED: 0,
    };
    formState.fields.forEach((field) => {
      sourceCount[field.sourceType] += 1;
    });
    return sourceCount;
  }, [formState.fields]);

  const updateField = (index: number, updater: (field: WorkReportField) => WorkReportField) => {
    setFormState((current) => ({
      ...current,
      fields: current.fields.map((field, fieldIndex) =>
        fieldIndex === index ? updater(field) : field,
      ),
    }));
  };

  const addField = (sourceType: WorkReportField["sourceType"] = "MANUAL") => {
    setFormState((current) => {
      const nextIndex = current.fields.length;
      const candidate = buildBlankField(nextIndex);
      candidate.sourceType = sourceType;

      if (sourceType === "SYSTEM") {
        candidate.systemKey = SYSTEM_FIELD_OPTIONS[0]?.key || null;
        candidate.dataType = SYSTEM_FIELD_OPTIONS[0]?.dataType || "TEXT";
      }

      if (sourceType === "CALCULATED") {
        candidate.dataType = "NUMBER";
        candidate.formula = "";
      }

      return {
        ...current,
        fields: [...current.fields, candidate],
      };
    });
  };

  const duplicateField = (index: number) => {
    setFormState((current) => {
      const target = current.fields[index];
      if (!target) return current;

      const clone = {
        ...target,
        key: `${target.key}_copy`,
      };

      const fields = [...current.fields];
      fields.splice(index + 1, 0, clone);

      return {
        ...current,
        fields: fields.map((field, fieldIndex) => ({
          ...field,
          orderIndex: fieldIndex,
        })),
      };
    });
  };

  const removeField = (index: number) => {
    setFormState((current) => ({
      ...current,
      fields: current.fields
        .filter((_, fieldIndex) => fieldIndex !== index)
        .map((field, fieldIndex) => ({
          ...field,
          orderIndex: fieldIndex,
        })),
    }));
  };

  const moveField = (index: number, direction: -1 | 1) => {
    setFormState((current) => {
      const nextIndex = index + direction;
      if (nextIndex < 0 || nextIndex >= current.fields.length) return current;

      const fields = [...current.fields];
      const [target] = fields.splice(index, 1);
      fields.splice(nextIndex, 0, target);

      return {
        ...current,
        fields: fields.map((field, fieldIndex) => ({
          ...field,
          orderIndex: fieldIndex,
        })),
      };
    });
  };

  const normalizeForSubmit = (): WorkReportTemplateDraft => ({
    ...formState,
    title: formState.title.trim(),
    description: formState.description.trim(),
    fields: formState.fields.map((field, index) => ({
      ...field,
      label: field.label.trim(),
      key: slugifyFieldKey(field.key || field.label) || `field_${index + 1}`,
      helpText: field.helpText?.trim() || "",
      placeholder: field.placeholder?.trim() || "",
      formula: field.formula?.trim() || "",
      orderIndex: index,
      options: field.options.map((option) => option.trim()).filter(Boolean),
    })),
  });

  const handleSave = async () => {
    const payload = normalizeForSubmit();

    if (!payload.title) {
      toast.error("اكتب اسم الفورم أولًا");
      return;
    }

    if (!payload.fields.length) {
      toast.error("أضف حقلًا واحدًا على الأقل");
      return;
    }

    try {
      setSaving(true);
      if (isEditing && formId) {
        await companyAwareApi.put(`/hr/reporting/forms/${formId}`, payload);
        toast.success("تم تحديث الفورم");
      } else {
        const response = await companyAwareApi.post<{ data: { id: string } }>(
          "/hr/reporting/forms",
          payload,
        );
        toast.success("تم إنشاء الفورم");
        const createdId = response.data?.data?.id;
        if (createdId) {
          navigate(`/hr/reporting/forms/${createdId}/preview`);
          return;
        }
      }

      navigate("/hr/reporting/forms");
    } catch (error: any) {
      console.error("Error saving reporting form:", error);
      toast.error(
        error?.response?.data?.message || "تعذر حفظ الفورم، راجع الحقول مرة أخرى",
      );
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div
        className="min-h-screen bg-slate-50 px-4 py-10 text-center text-slate-500 dark:bg-slate-950 dark:text-slate-400"
        dir="rtl"
      >
        جاري تحميل إعدادات الفورم...
      </div>
    );
  }

  return (
    <div
      className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900 dark:bg-slate-950 dark:text-slate-50 sm:px-6 lg:px-8"
      dir="rtl"
    >
      <div className="mx-auto max-w-7xl">
        <div className="mb-8 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
          <div className="space-y-3">
            <Link
              to="/hr/reporting/forms"
              className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-white px-3 py-1.5 text-sm text-slate-600 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300 dark:hover:border-slate-700 dark:hover:text-white"
            >
              <ArrowLeft className="h-4 w-4" />
              العودة لفورمات التقارير
            </Link>
            <div className="space-y-2">
              <p className="text-sm font-medium text-slate-500 dark:text-slate-400">
                {isEditing ? "تعديل فورم" : "إنشاء فورم جديد"}
              </p>
              <h1 className="text-3xl font-semibold tracking-tight">
                {isEditing ? formState.title || "تعديل الفورم" : "بناء فورم التقرير"}
              </h1>
              <p className="max-w-3xl text-sm leading-7 text-slate-600 dark:text-slate-300">
                حدّد بيانات تُسحب من النظام، وبيانات يكتبها الموظف، وأخرى تتحسب
                تلقائيًا. النتيجة النهائية ستظهر في شاشة التعبئة وسجلات التحليل.
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <button
              type="button"
              onClick={() => applyDraft(buildMessagingPreset())}
              className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200 dark:hover:border-slate-700"
            >
              <Sparkles className="h-4 w-4" />
              تحميل قالب فريق الرد
            </button>
            {isEditing && formId ? (
              <Link
                to={`/hr/reporting/forms/${formId}/preview`}
                className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200 dark:hover:border-slate-700"
              >
                <Eye className="h-4 w-4" />
                معاينة
              </Link>
            ) : null}
            <button
              type="button"
              onClick={handleSave}
              disabled={saving}
              className="inline-flex items-center gap-2 rounded-xl bg-slate-900 px-4 py-3 text-sm font-medium text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60 dark:bg-white dark:text-slate-950 dark:hover:bg-slate-200"
            >
              <Save className="h-4 w-4" />
              {saving ? "جاري الحفظ..." : "حفظ الفورم"}
            </button>
          </div>
        </div>

        <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]">
          <section className="space-y-4">
            <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
              <div className="mb-4 grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                    اسم الفورم
                  </label>
                  <input
                    value={formState.title}
                    onChange={(event) =>
                      setFormState((current) => ({ ...current, title: event.target.value }))
                    }
                    className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                    placeholder="مثال: تقرير يومي - فريق خدمة العملاء"
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                    دورة التقرير
                  </label>
                  <select
                    value={formState.cadence}
                    onChange={(event) =>
                      setFormState((current) => ({
                        ...current,
                        cadence: event.target.value as WorkReportTemplateDraft["cadence"],
                      }))
                    }
                    className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                  >
                    {CADENCE_OPTIONS.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                  وصف مختصر
                </label>
                <textarea
                  value={formState.description}
                  onChange={(event) =>
                    setFormState((current) => ({
                      ...current,
                      description: event.target.value,
                    }))
                  }
                  rows={3}
                  className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                  placeholder="اشرح الغرض من التقرير ومن الذي سيستخدمه."
                />
              </div>

              <div className="mt-4 flex flex-wrap gap-6">
                <label className="inline-flex items-center gap-2 text-sm text-slate-700 dark:text-slate-200">
                  <input
                    type="checkbox"
                    checked={formState.isActive}
                    onChange={(event) =>
                      setFormState((current) => ({
                        ...current,
                        isActive: event.target.checked,
                      }))
                    }
                    className="h-4 w-4 rounded border-slate-300"
                  />
                  الفورم مفعل
                </label>

                <label className="inline-flex items-center gap-2 text-sm text-slate-700 dark:text-slate-200">
                  <input
                    type="checkbox"
                    checked={formState.allowMultipleSubmissions}
                    onChange={(event) =>
                      setFormState((current) => ({
                        ...current,
                        allowMultipleSubmissions: event.target.checked,
                      }))
                    }
                    className="h-4 w-4 rounded border-slate-300"
                  />
                  السماح بأكثر من إرسال لنفس الفترة
                </label>
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-3">
              <button
                type="button"
                onClick={() => addField("MANUAL")}
                className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200 dark:hover:border-slate-700"
              >
                <Plus className="h-4 w-4" />
                إضافة حقل يدوي
              </button>
              <button
                type="button"
                onClick={() => addField("SYSTEM")}
                className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200 dark:hover:border-slate-700"
              >
                <Plus className="h-4 w-4" />
                إضافة حقل من النظام
              </button>
              <button
                type="button"
                onClick={() => addField("CALCULATED")}
                className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200 dark:hover:border-slate-700"
              >
                <Plus className="h-4 w-4" />
                إضافة حقل حسابي
              </button>
            </div>

            {formState.fields.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-slate-500 shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400">
                أضف أول حقل لبدء بناء الفورم.
              </div>
            ) : (
              <div className="space-y-4">
                {formState.fields.map((field, index) => {
                  const systemOption = SYSTEM_FIELD_OPTIONS.find(
                    (option) => option.key === field.systemKey,
                  );

                  return (
                    <div
                      key={`${field.key}-${index}`}
                      className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900"
                    >
                      <div className="mb-4 flex flex-wrap items-start justify-between gap-3">
                        <div className="flex items-center gap-3">
                          <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-300">
                            <GripVertical className="h-4 w-4" />
                          </span>
                          <div className="space-y-2">
                            <div className="flex flex-wrap items-center gap-2">
                              <h3 className="font-medium">
                                {field.label || `حقل ${index + 1}`}
                              </h3>
                              <BuilderBadge
                                label={
                                  FIELD_SOURCE_OPTIONS.find(
                                    (item) => item.value === field.sourceType,
                                  )?.label || field.sourceType
                                }
                              />
                              <BuilderBadge
                                label={
                                  DATA_TYPE_OPTIONS.find(
                                    (item) => item.value === field.dataType,
                                  )?.label || field.dataType
                                }
                              />
                              {!field.isVisible ? (
                                <BuilderBadge
                                  label="مخفي"
                                  tone="border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/60 dark:bg-amber-950/30 dark:text-amber-300"
                                />
                              ) : null}
                            </div>
                            <p className="text-xs text-slate-500 dark:text-slate-400">
                              المفتاح البرمجي: <span className="font-mono">{field.key || "—"}</span>
                            </p>
                          </div>
                        </div>

                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            type="button"
                            onClick={() => moveField(index, -1)}
                            className="rounded-xl border border-slate-200 p-2 text-slate-600 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-700 dark:text-slate-300 dark:hover:border-slate-600"
                            title="تحريك لأعلى"
                          >
                            <ChevronUp className="h-4 w-4" />
                          </button>
                          <button
                            type="button"
                            onClick={() => moveField(index, 1)}
                            className="rounded-xl border border-slate-200 p-2 text-slate-600 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-700 dark:text-slate-300 dark:hover:border-slate-600"
                            title="تحريك لأسفل"
                          >
                            <ChevronDown className="h-4 w-4" />
                          </button>
                          <button
                            type="button"
                            onClick={() => duplicateField(index)}
                            className="rounded-xl border border-slate-200 p-2 text-slate-600 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-700 dark:text-slate-300 dark:hover:border-slate-600"
                            title="نسخ الحقل"
                          >
                            <CopyPlus className="h-4 w-4" />
                          </button>
                          <button
                            type="button"
                            onClick={() => removeField(index)}
                            className="rounded-xl border border-rose-200 p-2 text-rose-700 transition hover:border-rose-300 hover:bg-rose-50 dark:border-rose-900/60 dark:text-rose-300 dark:hover:bg-rose-950/30"
                            title="حذف الحقل"
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </div>
                      </div>

                      <div className="grid gap-4 md:grid-cols-2">
                        <div className="space-y-2">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            اسم الحقل
                          </label>
                          <input
                            value={field.label}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                label: event.target.value,
                                key:
                                  !current.key || current.key.startsWith("field_")
                                    ? slugifyFieldKey(event.target.value) || current.key
                                    : current.key,
                              }))
                            }
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                            placeholder="مثال: عدد الرسائل"
                          />
                        </div>

                        <div className="space-y-2">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            المفتاح البرمجي
                          </label>
                          <input
                            value={field.key}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                key: slugifyFieldKey(event.target.value),
                              }))
                            }
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-mono outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                            placeholder="orders_count"
                          />
                        </div>

                        <div className="space-y-2">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            نوع المصدر
                          </label>
                          <select
                            value={field.sourceType}
                            onChange={(event) =>
                              updateField(index, (current) => {
                                const nextSource = event.target.value as WorkReportField["sourceType"];
                                const nextState: WorkReportField = {
                                  ...current,
                                  sourceType: nextSource,
                                };

                                if (nextSource === "SYSTEM") {
                                  const defaultSystem = SYSTEM_FIELD_OPTIONS[0];
                                  nextState.systemKey = defaultSystem?.key || null;
                                  nextState.dataType = defaultSystem?.dataType || "TEXT";
                                  nextState.formula = null;
                                } else if (nextSource === "CALCULATED") {
                                  nextState.systemKey = null;
                                  nextState.formula = current.formula || "";
                                  nextState.dataType =
                                    current.dataType === "TEXT" || current.dataType === "LONG_TEXT"
                                      ? "NUMBER"
                                      : current.dataType;
                                } else {
                                  nextState.systemKey = null;
                                  nextState.formula = null;
                                }

                                return nextState;
                              })
                            }
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                          >
                            {FIELD_SOURCE_OPTIONS.map((option) => (
                              <option key={option.value} value={option.value}>
                                {option.label}
                              </option>
                            ))}
                          </select>
                        </div>

                        <div className="space-y-2">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            نوع البيانات
                          </label>
                          <select
                            value={field.dataType}
                            disabled={field.sourceType === "SYSTEM"}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                dataType: event.target.value as WorkReportFieldDataType,
                                options:
                                  event.target.value === "SELECT" ? current.options : [],
                              }))
                            }
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white disabled:cursor-not-allowed disabled:opacity-60 dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                          >
                            {DATA_TYPE_OPTIONS.map((option) => (
                              <option key={option.value} value={option.value}>
                                {option.label}
                              </option>
                            ))}
                          </select>
                        </div>
                      </div>

                      <div className="mt-4 grid gap-4 md:grid-cols-2">
                        <div className="space-y-2">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            وصف أو ملاحظة مساعدة
                          </label>
                          <input
                            value={field.helpText || ""}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                helpText: event.target.value,
                              }))
                            }
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                            placeholder="نص مساعد يظهر للموظف أو المدير."
                          />
                        </div>

                        <div className="space-y-2">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            Placeholder
                          </label>
                          <input
                            value={field.placeholder || ""}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                placeholder: event.target.value,
                              }))
                            }
                            disabled={field.sourceType !== "MANUAL"}
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-slate-400 focus:bg-white disabled:cursor-not-allowed disabled:opacity-60 dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
                            placeholder="نص يظهر داخل الحقل للموظف."
                          />
                        </div>
                      </div>

                      {field.sourceType === "SYSTEM" ? (
                        <div className="mt-4 space-y-2 rounded-xl bg-slate-50 p-4 dark:bg-slate-950">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            مصدر البيانات من النظام
                          </label>
                          <select
                            value={field.systemKey || ""}
                            onChange={(event) =>
                              updateField(index, (current) => {
                                const option = SYSTEM_FIELD_OPTIONS.find(
                                  (item) => item.key === event.target.value,
                                );
                                return {
                                  ...current,
                                  systemKey: event.target.value,
                                  dataType: option?.dataType || current.dataType,
                                };
                              })
                            }
                            className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-slate-400 dark:border-slate-700 dark:bg-slate-900 dark:text-white"
                          >
                            {SYSTEM_FIELD_OPTIONS.map((option) => (
                              <option key={option.key} value={option.key}>
                                {option.label}
                              </option>
                            ))}
                          </select>
                          <p className="text-xs leading-6 text-slate-500 dark:text-slate-400">
                            {systemOption?.description}
                          </p>
                        </div>
                      ) : null}

                      {field.sourceType === "CALCULATED" ? (
                        <div className="mt-4 space-y-2 rounded-xl bg-slate-50 p-4 dark:bg-slate-950">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            المعادلة الحسابية
                          </label>
                          <input
                            value={field.formula || ""}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                formula: event.target.value,
                              }))
                            }
                            className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-mono outline-none transition focus:border-slate-400 dark:border-slate-700 dark:bg-slate-900 dark:text-white"
                            placeholder="(orders_count / replied_conversations_count) * 100"
                          />
                          <p className="text-xs leading-6 text-slate-500 dark:text-slate-400">
                            استخدم مفاتيح الحقول بالأحرف الإنجليزية مع العمليات
                            الحسابية الأساسية مثل + و - و * و /.
                          </p>
                        </div>
                      ) : null}

                      {field.dataType === "SELECT" && field.sourceType !== "SYSTEM" ? (
                        <div className="mt-4 space-y-2 rounded-xl bg-slate-50 p-4 dark:bg-slate-950">
                          <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                            خيارات القائمة
                          </label>
                          <textarea
                            value={field.options.join("\n")}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                options: event.target.value
                                  .split("\n")
                                  .map((option) => option.trim())
                                  .filter(Boolean),
                              }))
                            }
                            rows={4}
                            className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-slate-400 dark:border-slate-700 dark:bg-slate-900 dark:text-white"
                            placeholder="اكتب كل اختيار في سطر مستقل"
                          />
                        </div>
                      ) : null}

                      <div className="mt-4 flex flex-wrap gap-6">
                        <label className="inline-flex items-center gap-2 text-sm text-slate-700 dark:text-slate-200">
                          <input
                            type="checkbox"
                            checked={field.isRequired}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                isRequired: event.target.checked,
                              }))
                            }
                            className="h-4 w-4 rounded border-slate-300"
                          />
                          الحقل مطلوب
                        </label>
                        <label className="inline-flex items-center gap-2 text-sm text-slate-700 dark:text-slate-200">
                          <input
                            type="checkbox"
                            checked={field.isVisible}
                            onChange={(event) =>
                              updateField(index, (current) => ({
                                ...current,
                                isVisible: event.target.checked,
                              }))
                            }
                            className="h-4 w-4 rounded border-slate-300"
                          />
                          يظهر للموظف داخل الفورم
                        </label>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </section>

          <aside className="space-y-4">
            <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
              <h2 className="mb-4 text-lg font-semibold">ملخص سريع</h2>
              <div className="space-y-3 text-sm">
                <div className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 dark:bg-slate-950">
                  <span className="text-slate-500 dark:text-slate-400">إجمالي الحقول</span>
                  <strong>{formState.fields.length}</strong>
                </div>
                <div className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 dark:bg-slate-950">
                  <span className="text-slate-500 dark:text-slate-400">من النظام</span>
                  <strong>{visibleCounts.SYSTEM}</strong>
                </div>
                <div className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 dark:bg-slate-950">
                  <span className="text-slate-500 dark:text-slate-400">يدوي</span>
                  <strong>{visibleCounts.MANUAL}</strong>
                </div>
                <div className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 dark:bg-slate-950">
                  <span className="text-slate-500 dark:text-slate-400">حسابي</span>
                  <strong>{visibleCounts.CALCULATED}</strong>
                </div>
              </div>
            </div>

            <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
              <h2 className="mb-4 text-lg font-semibold">مصادر جاهزة من النظام</h2>
              <div className="space-y-3">
                {SYSTEM_FIELD_OPTIONS.map((option) => (
                  <div
                    key={option.key}
                    className="rounded-xl bg-slate-50 p-4 dark:bg-slate-950"
                  >
                    <div className="mb-1 flex items-center justify-between gap-2">
                      <strong className="text-sm">{option.label}</strong>
                      <BuilderBadge label={option.dataType} />
                    </div>
                    <p className="text-xs leading-6 text-slate-500 dark:text-slate-400">
                      {option.description}
                    </p>
                    <p className="mt-2 text-[11px] font-mono text-slate-400 dark:text-slate-500">
                      {option.key}
                    </p>
                  </div>
                ))}
              </div>
            </div>

            <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
              <h2 className="mb-3 text-lg font-semibold">ملاحظات مهمة</h2>
              <ul className="space-y-2 text-sm leading-7 text-slate-600 dark:text-slate-300">
                <li>الحقول المخفية يمكن استخدامها في التحليل حتى لو لم تظهر للموظف.</li>
                <li>المعادلات الحسابية تعتمد على مفاتيح الحقول وليس على العنوان.</li>
                <li>الحقول الرقمية أسهل بكثير في التحليل وعرض الرسوم لاحقًا.</li>
              </ul>
            </div>
          </aside>
        </div>
      </div>
    </div>
  );
};

export default WorkReportFormBuilder;

import React, { useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import {
  ArrowLeft,
  BarChart3,
  CalendarDays,
  Download,
  Filter,
  Table2,
  Users,
} from "lucide-react";
import { toast } from "react-hot-toast";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { companyAwareApi } from "../../../services/companyAwareApi";
import { WorkReportField, WorkReportRecordsResponse } from "./types";
import {
  formatArabicDate,
  formatArabicDateTime,
  formatMetricValue,
  getRelativeIsoDate,
  getTodayIsoDate,
  truncateText,
} from "./utils";

const StatCard: React.FC<{
  label: string;
  value: string | number;
  icon: React.ElementType;
  tone: string;
}> = ({ label, value, icon: Icon, tone }) => (
  <div className={`rounded-2xl border p-5 shadow-sm ${tone}`}>
    <div className="mb-2 flex items-center justify-between text-sm opacity-80">
      <span>{label}</span>
      <Icon className="h-4 w-4" />
    </div>
    <div className="text-3xl font-semibold">{value}</div>
  </div>
);

const WorkReportRecordsPage: React.FC = () => {
  const { formId } = useParams<{ formId: string }>();
  const [loading, setLoading] = useState(true);
  const [startDate, setStartDate] = useState(getRelativeIsoDate(-6));
  const [endDate, setEndDate] = useState(getTodayIsoDate());
  const [selectedUserId, setSelectedUserId] = useState("");
  const [payload, setPayload] = useState<WorkReportRecordsResponse | null>(null);

  const fetchRecords = async () => {
    if (!formId) return;

    try {
      setLoading(true);
      const response = await companyAwareApi.get<{ data: WorkReportRecordsResponse }>(
        `/hr/reporting/forms/${formId}/records`,
        {
          params: {
            startDate,
            endDate,
            ...(selectedUserId ? { userId: selectedUserId } : {}),
          },
        },
      );

      if (response.data?.data) {
        setPayload(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching work report records:", error);
      toast.error("تعذر تحميل السجلات");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRecords();
  }, [formId, startDate, endDate, selectedUserId]);

  const visibleFields = useMemo(
    () => (payload?.form.fields || []).filter((field) => field.isVisible),
    [payload],
  );

  const primaryMetric = payload?.analytics.metricCards[0];
  const secondaryMetric = payload?.analytics.metricCards[1];

  const chartData = useMemo(() => {
    if (!payload) return [];

    return payload.analytics.dailyTrend.map((row) => ({
      date: row.date,
      submissions: row.submissions,
      ...(primaryMetric
        ? {
            [primaryMetric.key]: Number(row.metrics[primaryMetric.key] || 0),
          }
        : {}),
      ...(secondaryMetric
        ? {
            [secondaryMetric.key]: Number(row.metrics[secondaryMetric.key] || 0),
          }
        : {}),
    }));
  }, [payload, primaryMetric, secondaryMetric]);

  const employeeChartData = useMemo(() => {
    if (!payload || !primaryMetric) return [];

    return payload.analytics.employeeBreakdown.map((row) => {
      const primarySnapshot = row.metrics.find(
        (metric) => metric.key === primaryMetric.key,
      );
      return {
        name: row.userDisplayName,
        submissions: row.submissionsCount,
        metric: primarySnapshot?.total || 0,
      };
    });
  }, [payload, primaryMetric]);

  const exportCsv = () => {
    if (!payload) return;

    const columns = [
      "الموظف",
      "تاريخ التقرير",
      "وقت الحفظ",
      ...visibleFields.slice(0, 6).map((field) => field.label),
    ];

    const rows = payload.records.map((record) => [
      record.userDisplayName,
      formatArabicDate(record.reportDate),
      formatArabicDateTime(record.submittedAt),
      ...visibleFields
        .slice(0, 6)
        .map((field) => record.valuesByFieldKey[field.key]?.displayValue || "—"),
    ]);

    const csvContent =
      "\uFEFF" + [columns, ...rows].map((row) => row.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `work-report-records-${formId}-${startDate}-${endDate}.csv`;
    link.click();
  };

  if (loading) {
    return (
      <div
        className="min-h-screen bg-slate-50 px-4 py-10 text-center text-slate-500 dark:bg-slate-950 dark:text-slate-400"
        dir="rtl"
      >
        جاري تحميل السجلات والتحليل...
      </div>
    );
  }

  if (!payload) {
    return (
      <div
        className="min-h-screen bg-slate-50 px-4 py-10 text-center text-slate-500 dark:bg-slate-950 dark:text-slate-400"
        dir="rtl"
      >
        لا توجد بيانات للعرض.
      </div>
    );
  }

  return (
    <div
      className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900 dark:bg-slate-950 dark:text-slate-50 sm:px-6 lg:px-8"
      dir="rtl"
    >
      <div className="mx-auto max-w-7xl">
        <div className="mb-8 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
          <div className="space-y-3">
            <Link
              to="/hr/reporting/forms"
              className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-white px-3 py-1.5 text-sm text-slate-600 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300 dark:hover:border-slate-700 dark:hover:text-white"
            >
              <ArrowLeft className="h-4 w-4" />
              العودة لفورمات التقارير
            </Link>
            <div className="space-y-2">
              <p className="text-sm font-medium text-slate-500 dark:text-slate-400">
                السجلات والتحليل
              </p>
              <h1 className="text-3xl font-semibold tracking-tight">
                {payload.form.title}
              </h1>
              <p className="max-w-3xl text-sm leading-7 text-slate-600 dark:text-slate-300">
                راقب السجلات المرسلة، قارن بين الموظفين، وراجع المؤشرات الرئيسية
                للفترة المحددة.
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <button
              type="button"
              onClick={exportCsv}
              className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200 dark:hover:border-slate-700"
            >
              <Download className="h-4 w-4" />
              تصدير CSV
            </button>
            <Link
              to={`/hr/reporting/forms/${payload.form.id}/preview`}
              className="inline-flex items-center gap-2 rounded-xl bg-slate-900 px-4 py-3 text-sm font-medium text-white transition hover:bg-slate-800 dark:bg-white dark:text-slate-950 dark:hover:bg-slate-200"
            >
              <BarChart3 className="h-4 w-4" />
              معاينة الفورم
            </Link>
          </div>
        </div>

        <div className="mb-6 grid gap-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900 md:grid-cols-2 xl:grid-cols-4">
          <label className="space-y-2 text-sm">
            <span className="inline-flex items-center gap-2 text-slate-500 dark:text-slate-400">
              <CalendarDays className="h-4 w-4" />
              من تاريخ
            </span>
            <input
              type="date"
              value={startDate}
              onChange={(event) => setStartDate(event.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
            />
          </label>
          <label className="space-y-2 text-sm">
            <span className="inline-flex items-center gap-2 text-slate-500 dark:text-slate-400">
              <CalendarDays className="h-4 w-4" />
              إلى تاريخ
            </span>
            <input
              type="date"
              value={endDate}
              onChange={(event) => setEndDate(event.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
            />
          </label>
          <label className="space-y-2 text-sm">
            <span className="inline-flex items-center gap-2 text-slate-500 dark:text-slate-400">
              <Users className="h-4 w-4" />
              الموظف
            </span>
            <select
              value={selectedUserId}
              onChange={(event) => setSelectedUserId(event.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none transition focus:border-slate-400 focus:bg-white dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:focus:border-slate-500"
            >
              <option value="">كل الموظفين</option>
              {payload.analytics.employeeBreakdown.map((row) => (
                <option key={row.userId} value={row.userId}>
                  {row.userDisplayName}
                </option>
              ))}
            </select>
          </label>
          <div className="flex items-end">
            <button
              type="button"
              onClick={fetchRecords}
              className="inline-flex w-full items-center justify-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-medium text-slate-700 transition hover:border-slate-300 hover:bg-white hover:text-slate-900 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-200 dark:hover:border-slate-600"
            >
              <Filter className="h-4 w-4" />
              تحديث النتائج
            </button>
          </div>
        </div>

        <div className="mb-6 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
          <StatCard
            label="إجمالي السجلات"
            value={payload.analytics.summary.totalSubmissions}
            icon={Table2}
            tone="border-slate-200 bg-white text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-50"
          />
          <StatCard
            label="عدد الموظفين"
            value={payload.analytics.summary.uniqueEmployees}
            icon={Users}
            tone="border-blue-200 bg-blue-50 text-blue-800 dark:border-blue-900/60 dark:bg-blue-950/30 dark:text-blue-200"
          />
          {payload.analytics.metricCards.slice(0, 2).map((metric) => (
            <StatCard
              key={metric.key}
              label={metric.label}
              value={
                metric.dataType === "PERCENT"
                  ? formatMetricValue(metric.average, metric.dataType)
                  : formatMetricValue(metric.total, metric.dataType)
              }
              icon={BarChart3}
              tone="border-emerald-200 bg-emerald-50 text-emerald-800 dark:border-emerald-900/60 dark:bg-emerald-950/30 dark:text-emerald-200"
            />
          ))}
        </div>

        <div className="mb-6 grid gap-6 xl:grid-cols-2">
          <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
            <div className="mb-4">
              <h2 className="text-lg font-semibold">اتجاه الأداء عبر الأيام</h2>
              <p className="text-sm text-slate-500 dark:text-slate-400">
                عدد السجلات ومعه المؤشرات الرقمية الأولى في الفورم.
              </p>
            </div>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="rgba(148,163,184,0.2)" />
                  <XAxis dataKey="date" />
                  <YAxis />
                  <Tooltip />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey="submissions"
                    name="عدد السجلات"
                    stroke="#0f172a"
                    strokeWidth={2.4}
                  />
                  {primaryMetric ? (
                    <Line
                      type="monotone"
                      dataKey={primaryMetric.key}
                      name={primaryMetric.label}
                      stroke="#2563eb"
                      strokeWidth={2}
                    />
                  ) : null}
                  {secondaryMetric ? (
                    <Line
                      type="monotone"
                      dataKey={secondaryMetric.key}
                      name={secondaryMetric.label}
                      stroke="#0f766e"
                      strokeWidth={2}
                    />
                  ) : null}
                </LineChart>
              </ResponsiveContainer>
            </div>
          </section>

          <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
            <div className="mb-4">
              <h2 className="text-lg font-semibold">مقارنة بين الموظفين</h2>
              <p className="text-sm text-slate-500 dark:text-slate-400">
                يعرض عدد السجلات مع أول مؤشر رقمي في الفورم لكل موظف.
              </p>
            </div>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={employeeChartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="rgba(148,163,184,0.2)" />
                  <XAxis dataKey="name" hide />
                  <YAxis />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="submissions" name="السجلات" fill="#334155" radius={[6, 6, 0, 0]} />
                  {primaryMetric ? (
                    <Bar
                      dataKey="metric"
                      name={primaryMetric.label}
                      fill="#2563eb"
                      radius={[6, 6, 0, 0]}
                    />
                  ) : null}
                </BarChart>
              </ResponsiveContainer>
            </div>
          </section>
        </div>

        <div className="mb-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-4">
            <h2 className="text-lg font-semibold">ملخص الموظفين</h2>
            <p className="text-sm text-slate-500 dark:text-slate-400">
              إجمالي كل موظف خلال الفترة المحددة مع متوسط المؤشرات.
            </p>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full text-right text-sm">
              <thead>
                <tr className="border-b border-slate-200 text-slate-500 dark:border-slate-800 dark:text-slate-400">
                  <th className="px-3 py-3 font-medium">الموظف</th>
                  <th className="px-3 py-3 font-medium">عدد السجلات</th>
                  {payload.analytics.metricCards.slice(0, 3).map((metric) => (
                    <th key={metric.key} className="px-3 py-3 font-medium">
                      {metric.label}
                    </th>
                  ))}
                  <th className="px-3 py-3 font-medium">آخر إرسال</th>
                </tr>
              </thead>
              <tbody>
                {payload.analytics.employeeBreakdown.map((row) => (
                  <tr
                    key={row.userId}
                    className="border-b border-slate-100 dark:border-slate-900"
                  >
                    <td className="px-3 py-3 font-medium">{row.userDisplayName}</td>
                    <td className="px-3 py-3">{row.submissionsCount}</td>
                    {payload.analytics.metricCards.slice(0, 3).map((metric) => {
                      const snapshot = row.metrics.find((item) => item.key === metric.key);
                      const value =
                        metric.dataType === "PERCENT"
                          ? snapshot?.average
                          : snapshot?.total;
                      return (
                        <td key={metric.key} className="px-3 py-3">
                          {formatMetricValue(value, metric.dataType)}
                        </td>
                      );
                    })}
                    <td className="px-3 py-3 text-slate-500 dark:text-slate-400">
                      {formatArabicDateTime(row.lastSubmittedAt)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-4">
            <h2 className="text-lg font-semibold">سجلات الفورم</h2>
            <p className="text-sm text-slate-500 dark:text-slate-400">
              عرض مباشر لكل إرسال مع أهم الحقول الظاهرة.
            </p>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full text-right text-sm">
              <thead>
                <tr className="border-b border-slate-200 text-slate-500 dark:border-slate-800 dark:text-slate-400">
                  <th className="px-3 py-3 font-medium">الموظف</th>
                  <th className="px-3 py-3 font-medium">تاريخ التقرير</th>
                  <th className="px-3 py-3 font-medium">وقت الحفظ</th>
                  {visibleFields.slice(0, 6).map((field: WorkReportField) => (
                    <th key={field.key} className="px-3 py-3 font-medium">
                      {field.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {payload.records.map((record) => (
                  <tr
                    key={record.id}
                    className="border-b border-slate-100 dark:border-slate-900"
                  >
                    <td className="px-3 py-3 font-medium">{record.userDisplayName}</td>
                    <td className="px-3 py-3">{formatArabicDate(record.reportDate)}</td>
                    <td className="px-3 py-3 text-slate-500 dark:text-slate-400">
                      {formatArabicDateTime(record.submittedAt)}
                    </td>
                    {visibleFields.slice(0, 6).map((field) => {
                      const value = record.valuesByFieldKey[field.key];
                      return (
                        <td key={field.key} className="px-3 py-3">
                          {field.dataType === "LONG_TEXT"
                            ? truncateText(value?.displayValue, 72)
                            : value?.displayValue || "—"}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default WorkReportRecordsPage;

import React, { useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import {
  ArrowLeft,
  CalendarDays,
  CheckCircle2,
  Lock,
  Save,
  Sigma,
  Sparkles,
} from "lucide-react";
import { toast } from "react-hot-toast";
import { companyAwareApi } from "../../../services/companyAwareApi";
import { WorkReportFillContext, WorkReportField, WorkReportFieldValue } from "./types";
import {
  buildLiveValuesByKey,
  formatArabicDateTime,
  getTodayIsoDate,
  valueFromRawInput,
} from "./utils";

const SectionBadge: React.FC<{
  label: string;
  tone?: string;
}> = ({
  label,
  tone = "border-slate-200 bg-slate-50 text-slate-600 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-300",
}) => (
  <span className={`inline-flex items-center rounded-full border px-2.5 py-1 text-xs font-medium ${tone}`}>
    {label}
  </span>
);

const WorkReportSubmissionPage: React.FC = () => {
  const { formId } = useParams<{ formId: string }>();
  const [reportDate, setReportDate] = useState(getTodayIsoDate());
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [context, setContext] = useState<WorkReportFillContext | null>(null);
  const [manualValues, setManualValues] = useState<Record<string, unknown>>({});

  const fetchContext = async () => {
    if (!formId) return;

    try {
      setLoading(true);
      const response = await companyAwareApi.get<{ data: WorkReportFillContext }>(
        `/hr/reporting/forms/${formId}/fill-context`,
        { params: { date: reportDate } },
      );

      if (response.data?.data) {
        const nextContext = response.data.data;
        setContext(nextContext);

        const nextManualValues: Record<string, unknown> = {};
        nextContext.form.fields.forEach((field) => {
          if (field.sourceType !== "MANUAL") return;
          const existingValue = nextContext.values.byFieldId[field.id || ""];
          if (field.dataType === "SELECT") {
            nextManualValues[field.id || field.key] = Array.isArray(existingValue?.valueJson)
              ? existingValue.valueJson
              : [];
            return;
          }

          nextManualValues[field.id || field.key] =
            existingValue?.valueText ?? existingValue?.valueNumber ?? "";
        });

        setManualValues(nextManualValues);
      }
    } catch (error: any) {
      console.error("Error fetching submission context:", error);
      toast.error(error?.response?.data?.message || "تعذر تحميل الفورم");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchContext();
  }, [formId, reportDate]);

  const liveValues = useMemo(() => {
    if (!context) return {};
    return buildLiveValuesByKey(context.form, context.values.byFieldKey, manualValues);
  }, [context, manualValues]);

  const visibleFields = useMemo(
    () => (context?.form.fields || []).filter((field) => field.isVisible),
    [context],
  );

  const highlightMetrics = useMemo(() => {
    if (!context) return [];
    return context.form.fields
      .filter(
        (field) =>
          field.isVisible &&
          (field.sourceType === "SYSTEM" || field.sourceType === "CALCULATED") &&
          (field.dataType === "NUMBER" || field.dataType === "PERCENT"),
      )
      .slice(0, 4);
  }, [context]);

  const updateManualValue = (field: WorkReportField, nextValue: unknown) => {
    setManualValues((current) => ({
      ...current,
      [field.id || field.key]: nextValue,
    }));
  };

  const buildSubmitPayload = () => {
    if (!context) return {};

    const values: Record<string, Record<string, unknown>> = {};

    context.form.fields.forEach((field) => {
      if (field.sourceType !== "MANUAL") return;

      const rawValue = manualValues[field.id || field.key];
      const normalized = valueFromRawInput(field, rawValue);

      if (field.dataType === "SELECT") {
        values[field.id || field.key] = {
          valueJson: normalized.valueJson,
          valueText: normalized.valueText,
        };
        return;
      }

      if (field.dataType === "NUMBER" || field.dataType === "PERCENT") {
        values[field.id || field.key] = {
          valueNumber: normalized.valueNumber,
          valueText: normalized.valueText,
        };
        return;
      }

      values[field.id || field.key] = {
        valueText: normalized.valueText,
      };
    });

    return values;
  };

  const handleSubmit = async () => {
    if (!formId || !context) return;

    try {
      setSaving(true);
      await companyAwareApi.post(`/hr/reporting/forms/${formId}/submit`, {
        reportDate,
        values: buildSubmitPayload(),
      });
      toast.success("تم حفظ التقرير");
      fetchContext();
    } catch (error: any) {
      console.error("Error submitting report:", error);
      toast.error(error?.response?.data?.message || "تعذر حفظ التقرير");
    } finally {
      setSaving(false);
    }
  };

  const renderFieldInput = (field: WorkReportField, value: WorkReportFieldValue | undefined) => {
    if (field.sourceType !== "MANUAL") {
      return (
        <div className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm dark:border-slate-700 dark:bg-slate-900">
          <div className="mb-2 flex items-center gap-2 text-xs text-slate-400">
            {field.sourceType === "SYSTEM" ? (
              <>
                <Sparkles className="h-4 w-4" />
                قيمة من النظام
              </>
            ) : (
              <>
                <Sigma className="h-4 w-4" />
                ناتج المعادلة
              </>
            )}
          </div>
          <div className="text-sm font-medium text-slate-900 dark:text-white">
            {value?.displayValue || "—"}
          </div>
          <div className="mt-2 text-[11px] font-mono text-slate-400">
            {field.sourceType === "SYSTEM" ? field.systemKey : field.formula}
          </div>
        </div>
      );
    }

    if (field.dataType === "LONG_TEXT") {
      return (
        <textarea
          rows={5}
          value={String(manualValues[field.id || field.key] || "")}
          onChange={(event) => updateManualValue(field, event.target.value)}
          className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-slate-400 dark:border-slate-700 dark:bg-slate-900 dark:text-white dark:focus:border-slate-500"
          placeholder={field.placeholder || ""}
        />
      );
    }

    if (field.dataType === "SELECT") {
      const selectedValues = Array.isArray(manualValues[field.id || field.key])
        ? (manualValues[field.id || field.key] as string[])
        : [];

      return (
        <div className="flex flex-wrap gap-2">
          {field.options.map((option) => {
            const isSelected = selectedValues.includes(option);
            return (
              <button
                key={option}
                type="button"
                onClick={() =>
                  updateManualValue(
                    field,
                    isSelected
                      ? selectedValues.filter((item) => item !== option)
                      : [...selectedValues, option],
                  )
                }
                className={`rounded-xl border px-3 py-2 text-sm transition ${
                  isSelected
                    ? "border-slate-900 bg-slate-900 text-white dark:border-white dark:bg-white dark:text-slate-950"
                    : "border-slate-200 bg-white text-slate-700 hover:border-slate-300 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200"
                }`}
              >
                {option}
              </button>
            );
          })}
        </div>
      );
    }

    return (
      <input
        type={field.dataType === "NUMBER" || field.dataType === "PERCENT" ? "number" : "text"}
        step={field.dataType === "PERCENT" ? "0.01" : field.dataType === "NUMBER" ? "1" : undefined}
        value={String(manualValues[field.id || field.key] ?? "")}
        onChange={(event) => updateManualValue(field, event.target.value)}
        className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-slate-400 dark:border-slate-700 dark:bg-slate-900 dark:text-white dark:focus:border-slate-500"
        placeholder={field.placeholder || ""}
      />
    );
  };

  if (loading) {
    return (
      <div
        className="min-h-screen bg-slate-50 px-4 py-10 text-center text-slate-500 dark:bg-slate-950 dark:text-slate-400"
        dir="rtl"
      >
        جاري تحميل شاشة التقرير...
      </div>
    );
  }

  if (!context) {
    return (
      <div
        className="min-h-screen bg-slate-50 px-4 py-10 text-center text-slate-500 dark:bg-slate-950 dark:text-slate-400"
        dir="rtl"
      >
        لم يتم العثور على الفورم المطلوب.
      </div>
    );
  }

  return (
    <div
      className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900 dark:bg-slate-950 dark:text-slate-50 sm:px-6 lg:px-8"
      dir="rtl"
    >
      <div className="mx-auto max-w-5xl">
        <div className="mb-8 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
          <div className="space-y-3">
            <Link
              to="/hr/reporting/forms"
              className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-white px-3 py-1.5 text-sm text-slate-600 transition hover:border-slate-300 hover:text-slate-900 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300 dark:hover:border-slate-700 dark:hover:text-white"
            >
              <ArrowLeft className="h-4 w-4" />
              العودة للفورمات
            </Link>
            <div className="space-y-2">
              <div className="flex flex-wrap items-center gap-2">
                <SectionBadge label={context.period.cadence} />
                {context.form.isActive ? (
                  <SectionBadge
                    label="مفعل"
                    tone="border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900/60 dark:bg-emerald-950/30 dark:text-emerald-300"
                  />
                ) : (
                  <SectionBadge
                    label="غير مفعل"
                    tone="border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/60 dark:bg-amber-950/30 dark:text-amber-300"
                  />
                )}
              </div>
              <h1 className="text-3xl font-semibold tracking-tight">
                {context.form.title}
              </h1>
              <p className="max-w-3xl text-sm leading-7 text-slate-600 dark:text-slate-300">
                {context.form.description || "أكمل التقرير ثم احفظه ليظهر في السجلات والتحليل."}
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <label className="flex items-center gap-3 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm dark:border-slate-800 dark:bg-slate-900">
              <CalendarDays className="h-4 w-4 text-slate-500" />
              <span className="text-slate-500 dark:text-slate-400">تاريخ التقرير</span>
              <input
                type="date"
                value={reportDate}
                onChange={(event) => setReportDate(event.target.value)}
                className="bg-transparent outline-none"
              />
            </label>
            <button
              type="button"
              onClick={handleSubmit}
              disabled={saving}
              className="inline-flex items-center gap-2 rounded-xl bg-slate-900 px-4 py-3 text-sm font-medium text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60 dark:bg-white dark:text-slate-950 dark:hover:bg-slate-200"
            >
              <Save className="h-4 w-4" />
              {saving ? "جاري الحفظ..." : "حفظ التقرير"}
            </button>
          </div>
        </div>

        {context.existingSubmission ? (
          <div className="mb-6 rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800 dark:border-emerald-900/60 dark:bg-emerald-950/30 dark:text-emerald-200">
            <div className="flex items-center gap-2 font-medium">
              <CheckCircle2 className="h-4 w-4" />
              يوجد إرسال محفوظ لهذه الفترة
            </div>
            <div className="mt-2 text-emerald-700 dark:text-emerald-300">
              آخر تحديث: {formatArabicDateTime(context.existingSubmission.submittedAt)}
            </div>
          </div>
        ) : null}

        {highlightMetrics.length ? (
          <div className="mb-6 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            {highlightMetrics.map((field) => {
              const value = liveValues[field.key];
              return (
                <div
                  key={field.key}
                  className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900"
                >
                  <div className="mb-2 flex items-center justify-between text-sm text-slate-500 dark:text-slate-400">
                    <span>{field.label}</span>
                    {field.sourceType === "SYSTEM" ? (
                      <Sparkles className="h-4 w-4" />
                    ) : (
                      <Sigma className="h-4 w-4" />
                    )}
                  </div>
                  <div className="text-3xl font-semibold">
                    {value?.displayValue || "—"}
                  </div>
                </div>
              );
            })}
          </div>
        ) : null}

        <div className="space-y-4">
          {visibleFields.map((field) => {
            const value = liveValues[field.key];

            return (
              <section
                key={field.key}
                className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900"
              >
                <div className="mb-4 flex flex-wrap items-start justify-between gap-3">
                  <div className="space-y-2">
                    <div className="flex flex-wrap items-center gap-2">
                      <h2 className="text-lg font-medium">{field.label}</h2>
                      <SectionBadge
                        label={
                          field.sourceType === "SYSTEM"
                            ? "من النظام"
                            : field.sourceType === "CALCULATED"
                              ? "حسابي"
                              : "يدوي"
                        }
                      />
                      {field.isRequired ? (
                        <SectionBadge
                          label="مطلوب"
                          tone="border-rose-200 bg-rose-50 text-rose-700 dark:border-rose-900/60 dark:bg-rose-950/30 dark:text-rose-300"
                        />
                      ) : null}
                    </div>
                    {field.helpText ? (
                      <p className="text-sm leading-7 text-slate-600 dark:text-slate-300">
                        {field.helpText}
                      </p>
                    ) : null}
                  </div>

                  {field.sourceType !== "MANUAL" ? (
                    <div className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-slate-50 px-3 py-1.5 text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-300">
                      <Lock className="h-3.5 w-3.5" />
                      للعرض فقط
                    </div>
                  ) : null}
                </div>

                {renderFieldInput(field, value)}
              </section>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default WorkReportSubmissionPage;

import React, { useState, useEffect } from "react";
import { useDateFormat } from "../../hooks/useDateFormat";
import { useCurrency } from "../../hooks/useCurrency";
import {
  CubeIcon,
  ExclamationTriangleIcon,
  PlusIcon,
  MinusIcon,
  ArrowPathIcon,
  EyeIcon,
} from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../services/companyAwareApi";

interface InventoryItem {
  id: string; // Internal inventory ID
  productId: string;
  productName: string;
  sku: string;
  price: number;
  warehouseId: string;
  warehouseName: string;
  quantity: number;
  available: number;
  reserved: number;
  reorderPoint?: number;
  batchNumber?: string | null;
  expiryDate?: string | null;
  updatedAt: string;
}

interface StockAlert {
  id: string;
  type: "low_stock" | "out_of_stock";
  priority: "critical" | "high" | "medium" | "low";
  productId: string;
  productName: string;
  warehouseId: string;
  warehouseName: string;
  message: string;
  currentStock: number;
  reorderPoint: number;
  reorderQuantity?: number;
  createdAt: string;
  isRead: boolean;
}

const Inventory: React.FC = () => {
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const { formatDate } = useDateFormat();
  const { formatPrice } = useCurrency();
  const [alerts, setAlerts] = useState<StockAlert[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [showItemModal, setShowItemModal] = useState(false);
  const [showStockUpdateModal, setShowStockUpdateModal] = useState(false);
  const [showTransferModal, setShowTransferModal] = useState(false);
  const [warehouses, setWarehouses] = useState<{ id: string; name: string }[]>(
    [],
  );
  const [filters, setFilters] = useState({
    warehouseId: "",
    lowStock: false,
    outOfStock: false,
  });

  const [stockUpdate, setStockUpdate] = useState({
    productId: "",
    warehouseId: "",
    quantity: 0,
    type: "IN" as any,
    reason: "PURCHASE" as any,
    reference: "",
    notes: "",
    batchNumber: "",
    expiryDate: "",
    isApproved: true,
  });

  const [transferData, setTransferData] = useState({
    productId: "",
    fromWarehouseId: "",
    toWarehouseId: "",
    quantity: 0,
    notes: "",
    batchNumber: "",
  });

  useEffect(() => {
    fetchInventory();
    fetchAlerts();
    fetchWarehouses();
  }, [filters]);

  const fetchWarehouses = async () => {
    try {
      const response = await companyAwareApi.get("/warehouses");
      if (response.data.success) {
        setWarehouses(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching warehouses:", error);
    }
  };

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const params: any = {};
      if (filters.warehouseId) params.warehouseId = filters.warehouseId;
      if (filters.lowStock) params.lowStock = "true";
      if (filters.outOfStock) params.outOfStock = "true";

      const response = await companyAwareApi.get("/inventory", { params });
      if (response.data.success) {
        const rawData = response.data.data;
        const items: InventoryItem[] = rawData.map((item: any) => ({
          id: item.id,
          productId: item.productId,
          productName: item.products.name,
          sku: item.products.sku,
          price: item.products.price,
          warehouseId: item.warehouseId,
          warehouseName: item.warehouses?.name || "---",
          quantity: item.quantity,
          available: item.available,
          reserved: item.reserved,
          reorderPoint: item.reorderPoint,
          batchNumber: item.batchNumber,
          expiryDate: item.expiryDate,
          updatedAt: item.updatedAt,
        }));
        setInventory(items);
      }
    } catch (error) {
      console.error("Error fetching inventory:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchAlerts = async () => {
    try {
      const response = await companyAwareApi.get("/inventory/alerts");
      if (response.data.success) {
        // Flatten alerts if needed, or handle based on backend structure
        const { lowStock, outOfStock } = response.data.data;
        const allAlerts = [
          ...lowStock.map((item: any) => ({
            ...item,
            type: "low_stock",
            priority: "high",
            message: "مخزون منخفض",
          })),
          ...outOfStock.map((item: any) => ({
            ...item,
            type: "out_of_stock",
            priority: "critical",
            message: "نفد المخزون",
          })),
        ];
        setAlerts(allAlerts);
      }
    } catch (error) {
      console.error("Error fetching alerts:", error);
    }
  };

  const updateStock = async () => {
    try {
      if (
        !stockUpdate.productId ||
        !stockUpdate.warehouseId ||
        stockUpdate.quantity <= 0
      ) {
        alert("يرجى ملء جميع الحقول المطلوبة");
        return;
      }
      const response = await companyAwareApi.post(
        "/inventory/update-stock",
        stockUpdate,
      );

      if (response.data.success) {
        fetchInventory();
        fetchAlerts();
        setShowStockUpdateModal(false);
        setStockUpdate({
          productId: "",
          warehouseId: "",
          quantity: 0,
          type: "IN",
          reason: "PURCHASE",
          reference: "",
          notes: "",
          batchNumber: "",
          expiryDate: "",
          isApproved: true,
        });
        alert(response.data.message || "تم تحديث المخزون بنجاح");
      } else {
        alert(response.data.message || "فشل في تحديث المخزون");
      }
    } catch (error: any) {
      console.error("Error updating stock:", error);
      alert(error.response?.data?.message || "فشل في تحديث المخزون");
    }
  };

  const downloadCSV = () => {
    const headers = [
      "Product",
      "SKU",
      "Warehouse",
      "Batch",
      "Quantity",
      "Available",
      "Cost",
      "Expiry",
    ];
    const rows = inventory.map((item) => [
      item.productName,
      item.sku,
      item.warehouseName,
      item.batchNumber || "",
      item.quantity,
      item.available,
      item.price,
      item.expiryDate || "",
    ]);

    const csvContent = [
      headers.join(","),
      ...rows.map((r) => r.join(",")),
    ].join("\n");

    const blob = new Blob([`\ufeff${csvContent}`], {
      type: "text/csv;charset=utf-8;",
    });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute(
      "download",
      `inventory_${new Date().toISOString().split("T")[0]}.csv`,
    );
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };
  const transferStock = async () => {
    try {
      if (
        !transferData.fromWarehouseId ||
        !transferData.toWarehouseId ||
        transferData.quantity <= 0
      ) {
        alert("يرجى ملء جميع الحقول المطلوبة");
        return;
      }
      const response = await companyAwareApi.post(
        "/inventory/transfer",
        transferData,
      );
      if (response.data.success) {
        fetchInventory();
        setShowTransferModal(false);
        setTransferData({
          productId: "",
          fromWarehouseId: "",
          toWarehouseId: "",
          quantity: 0,
          notes: "",
          batchNumber: "",
        });
        alert("تم نقل المخزون بنجاح");
      }
    } catch (error: any) {
      alert(error.response?.data?.message || "فشل في نقل المخزون");
    }
  };

  const getStockStatus = (item: InventoryItem) => {
    if (item.available === 0) {
      return { status: "نفد المخزون", color: "text-red-600 bg-red-100" };
    }

    if (item.available <= (item.reorderPoint || 0)) {
      return { status: "مخزون منخفض", color: "text-yellow-600 bg-yellow-100" };
    }

    return { status: "متوفر", color: "text-green-600 bg-green-100" };
  };

  const getAlertPriorityColor = (priority: string) => {
    switch (priority) {
      case "critical":
        return "bg-red-100 text-red-800 border-red-200";
      case "high":
        return "bg-orange-100 text-orange-800 border-orange-200";
      case "medium":
        return "bg-yellow-100 text-yellow-800 border-yellow-200";
      default:
        return "bg-blue-100 text-blue-800 border-blue-200";
    }
  };

  const getInventoryStats = () => {
    const totalItems = inventory.length;
    const totalValue = inventory.reduce(
      (acc, item) => acc + item.available * item.price,
      0,
    );
    const lowStockCount = inventory.filter(
      (item) =>
        item.available > 0 && item.available <= (item.reorderPoint || 0),
    ).length;
    const outOfStockCount = inventory.filter(
      (item) => item.available === 0,
    ).length;

    return { totalItems, totalValue, lowStockCount, outOfStockCount };
  };

  const stats = getInventoryStats();

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center">
              <CubeIcon className="h-8 w-8 text-indigo-600 dark:text-indigo-400 mr-3" />
              إدارة المخزون
            </h1>
            <p className="mt-2 text-gray-600 dark:text-gray-400">
              متابعة وإدارة مستويات المخزون والتنبيهات لجميع منتجات الشركة
            </p>
          </div>
          <div className="flex space-x-2 space-x-reverse">
            <button
              onClick={downloadCSV}
              className="flex items-center justify-center gap-2 px-4 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors shadow-sm"
            >
              تصدير CSV
            </button>
            <button
              onClick={() => setShowStockUpdateModal(true)}
              className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm transition-all"
            >
              <ArrowPathIcon className="h-5 w-5 mr-2" />
              تحديث المخزون
            </button>
          </div>
        </div>
      </div>

      {/* Stats Dashboard */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
            إجمالي المنتجات
          </p>
          <p className="mt-2 text-3xl font-bold text-gray-900 dark:text-white">
            {stats.totalItems}
          </p>
        </div>
        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
            إجمالي قيمة المخزون
          </p>
          <p className="mt-2 text-3xl font-bold text-indigo-600 dark:text-indigo-400">
            {formatPrice(stats.totalValue)}
          </p>
        </div>
        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
            فئات منخفضة المخزون
          </p>
          <p className="mt-2 text-3xl font-bold text-yellow-600 dark:text-yellow-400">
            {stats.lowStockCount}
          </p>
        </div>
        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
            نفد من المخزون
          </p>
          <p className="mt-2 text-3xl font-bold text-red-600 dark:text-red-400">
            {stats.outOfStockCount}
          </p>
        </div>
      </div>

      {/* Stock Alerts */}
      {alerts.length > 0 && (
        <div className="mb-8">
          <h2 className="text-lg font-medium text-gray-900 dark:text-white mb-4 flex items-center">
            <ExclamationTriangleIcon className="h-6 w-6 text-yellow-500 mr-2" />
            تنبيهات المخزون ({alerts.length})
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {alerts.slice(0, 6).map((alert) => (
              <div
                key={alert.id}
                className={`border rounded-lg p-4 ${getAlertPriorityColor(alert.priority)}`}
              >
                <div className="flex items-start justify-between">
                  <div>
                    <h3 className="font-medium dark:text-gray-100">
                      {alert.productName}
                    </h3>
                    <p className="text-sm mt-1 dark:text-gray-300">
                      {alert.message}
                    </p>
                    <p className="text-xs mt-2 dark:text-gray-400">
                      المخزون الحالي: {alert.currentStock} | نقطة الطلب:{" "}
                      {alert.reorderPoint}
                    </p>
                  </div>
                  <span className="text-xs font-medium px-2 py-1 rounded bg-white/50 dark:bg-black/20">
                    {alert.priority === "critical"
                      ? "حرج"
                      : alert.priority === "high"
                        ? "عالي"
                        : alert.priority === "medium"
                          ? "متوسط"
                          : "منخفض"}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-8 border border-transparent dark:border-gray-700">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              بحث عن منتج
            </label>
            <input
              type="text"
              placeholder="ابحث باسم المنتج أو الـ SKU..."
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
              // Add a search filter if needed in state, or just use frontend filter
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              المستودع
            </label>
            <select
              value={filters.warehouseId}
              onChange={(e) =>
                setFilters({ ...filters, warehouseId: e.target.value })
              }
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">جميع المستودعات</option>
              {warehouses.map((wh) => (
                <option key={wh.id} value={wh.id}>
                  {wh.name}
                </option>
              ))}
            </select>
          </div>

          <div className="flex items-end">
            <button
              onClick={() =>
                setFilters({
                  warehouseId: "",
                  lowStock: false,
                  outOfStock: false,
                })
              }
              className="w-full px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-gray-500 transition-colors"
            >
              إعادة تعيين
            </button>
          </div>
        </div>

        <div className="mt-4 flex gap-6">
          <label className="flex items-center cursor-pointer">
            <input
              type="checkbox"
              checked={filters.lowStock}
              onChange={(e) =>
                setFilters({ ...filters, lowStock: e.target.checked })
              }
              className="rounded border-gray-300 dark:border-gray-600 text-indigo-600 focus:ring-indigo-500 dark:bg-gray-700"
            />
            <span className="mr-2 text-sm text-gray-700 dark:text-gray-300">
              مخزون منخفض فقط
            </span>
          </label>

          <label className="flex items-center cursor-pointer">
            <input
              type="checkbox"
              checked={filters.outOfStock}
              onChange={(e) =>
                setFilters({ ...filters, outOfStock: e.target.checked })
              }
              className="rounded border-gray-300 dark:border-gray-600 text-indigo-600 focus:ring-indigo-500 dark:bg-gray-700"
            />
            <span className="mr-2 text-sm text-gray-700 dark:text-gray-300">
              نفد المخزون فقط
            </span>
          </label>
        </div>
      </div>

      {/* Inventory Table */}
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg overflow-hidden border border-transparent dark:border-gray-700">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
            <thead className="bg-gray-50 dark:bg-gray-900">
              <tr>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  المنتج / SKU
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  المستودع
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  الدفعة / الصلاحية
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  الكمية
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  المتاح
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  الحالة
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  التكلفة
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                  الإجراءات
                </th>
              </tr>
            </thead>
            <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
              {inventory.map((item) => {
                const stockStatus = getStockStatus(item);

                return (
                  <tr
                    key={item.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm font-medium text-gray-900 dark:text-white">
                        {item.productName}
                      </div>
                      <div className="text-xs text-gray-500 dark:text-gray-400">
                        {item.sku}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100">
                      {item.warehouseName}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                      <div>{item.batchNumber || "---"}</div>
                      {item.expiryDate && (
                        <div className="text-xs text-red-500">
                          {formatDate(item.expiryDate)}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100 font-bold">
                      {item.quantity}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100">
                      {item.available}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${stockStatus.color}`}
                      >
                        {stockStatus.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100">
                      {formatPrice(item.price)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <div className="flex space-x-2 space-x-reverse">
                        <button
                          onClick={() => {
                            setSelectedItem(item);
                            setShowItemModal(true);
                          }}
                          className="p-1 text-indigo-600 hover:text-indigo-900 transition-colors"
                          title="عرض التفاصيل"
                        >
                          <EyeIcon className="h-5 w-5" />
                        </button>
                        <button
                          onClick={() => {
                            setTransferData({
                              ...transferData,
                              productId: item.productId,
                              fromWarehouseId: item.warehouseId,
                              batchNumber: item.batchNumber || "",
                            });
                            setShowTransferModal(true);
                          }}
                          className="p-1 text-orange-600 hover:text-orange-900 transition-colors"
                          title="نقل مخزن"
                        >
                          <ArrowPathIcon className="h-5 w-5" />
                        </button>
                        <button
                          onClick={() => {
                            setStockUpdate({
                              ...stockUpdate,
                              productId: item.productId,
                              warehouseId: item.warehouseId,
                              batchNumber: item.batchNumber || "",
                              type: "IN",
                              reason: "PURCHASE",
                            });
                            setShowStockUpdateModal(true);
                          }}
                          className="p-1 text-green-600 hover:text-green-900 transition-colors"
                          title="توريد"
                        >
                          <PlusIcon className="h-5 w-5" />
                        </button>
                        <button
                          onClick={() => {
                            setStockUpdate({
                              ...stockUpdate,
                              productId: item.productId,
                              warehouseId: item.warehouseId,
                              batchNumber: item.batchNumber || "",
                              type: "OUT",
                              reason: "SALE",
                            });
                            setShowStockUpdateModal(true);
                          }}
                          className="p-1 text-red-600 hover:text-red-900 transition-colors"
                          title="صرف"
                        >
                          <MinusIcon className="h-5 w-5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {inventory.length === 0 && (
          <div className="text-center py-20">
            <CubeIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-500" />
            <h3 className="mt-2 text-lg font-medium text-gray-900 dark:text-white">
              لا توجد منتجات حالياً
            </h3>
            <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
              ابدأ بإضافة منتجاتك في قسم المنتجات أولاً.
            </p>
          </div>
        )}
      </div>

      {/* Item Details Modal */}
      {showItemModal && selectedItem && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-11/12 md:w-3/4 lg:w-1/2 shadow-lg rounded-md bg-white">
            <div className="mt-3">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-medium text-gray-900">
                  تفاصيل المخزون - {selectedItem.productName}
                </h3>
                <button
                  onClick={() => setShowItemModal(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  ✕
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <h4 className="font-medium text-gray-900 mb-2">
                    معلومات المنتج
                  </h4>
                  <div className="bg-gray-50 p-3 rounded">
                    <p>
                      <strong>اسم المنتج:</strong> {selectedItem.productName}
                    </p>
                    <p>
                      <strong>SKU:</strong> {selectedItem.sku}
                    </p>
                    <p>
                      <strong>السعر:</strong> {formatPrice(selectedItem.price)}
                    </p>
                  </div>
                </div>

                <div>
                  <h4 className="font-medium text-gray-900 mb-2">
                    حالة المخزون
                  </h4>
                  <div className="bg-gray-50 p-3 rounded">
                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <p>
                          <strong>المستودع:</strong>{" "}
                          {selectedItem.warehouseName}
                        </p>
                        <p>
                          <strong>رقم الدفعة:</strong>{" "}
                          {selectedItem.batchNumber || "بدون"}
                        </p>
                        <p>
                          <strong>تاريخ الصلاحية:</strong>{" "}
                          {selectedItem.expiryDate
                            ? formatDate(selectedItem.expiryDate)
                            : "---"}
                        </p>
                      </div>
                      <div>
                        <p>
                          <strong>الكمية الإجمالية:</strong>{" "}
                          {selectedItem.quantity}
                        </p>
                        <p>
                          <strong>المتاح للبيع:</strong>{" "}
                          {selectedItem.available}
                        </p>
                        <p>
                          <strong>المحجوز:</strong> {selectedItem.reserved}
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex justify-end mt-6">
                <button
                  onClick={() => setShowItemModal(false)}
                  className="px-4 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  إغلاق
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Stock Update Modal */}
      {showStockUpdateModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-11/12 md:w-1/2 shadow-lg rounded-md bg-white">
            <div className="mt-3">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-medium text-gray-900">
                  تحديث المخزون
                </h3>
                <button
                  onClick={() => setShowStockUpdateModal(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  ✕
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    المنتج
                  </label>
                  <select
                    value={stockUpdate.productId}
                    onChange={(e) =>
                      setStockUpdate({
                        ...stockUpdate,
                        productId: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  >
                    <option value="">اختر المنتج</option>
                    {inventory.map((item) => (
                      <option key={item.productId} value={item.productId}>
                        {item.productName}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      المستودع
                    </label>
                    <select
                      value={stockUpdate.warehouseId}
                      onChange={(e) =>
                        setStockUpdate({
                          ...stockUpdate,
                          warehouseId: e.target.value,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                      <option value="WH001">المستودع الرئيسي</option>
                      <option value="WH002">مستودع جدة</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      نوع الحركة
                    </label>
                    <select
                      value={stockUpdate.type}
                      onChange={(e) =>
                        setStockUpdate({
                          ...stockUpdate,
                          type: e.target.value as any,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                      <option value="IN">إدخال</option>
                      <option value="OUT">إخراج</option>
                      <option value="ADJUSTMENT_IN">تعديل إضافة</option>
                      <option value="ADJUSTMENT_OUT">تعديل سحب</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      الكمية
                    </label>
                    <input
                      type="number"
                      value={stockUpdate.quantity}
                      onChange={(e) =>
                        setStockUpdate({
                          ...stockUpdate,
                          quantity: parseInt(e.target.value) || 0,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                      min="0"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      السبب
                    </label>
                    <select
                      value={stockUpdate.reason}
                      onChange={(e) =>
                        setStockUpdate({
                          ...stockUpdate,
                          reason: e.target.value as any,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                      <option value="PURCHASE">شراء</option>
                      <option value="SALE">بيع</option>
                      <option value="ADJUSTMENT">تعديل</option>
                      <option value="DAMAGE">تلف</option>
                      <option value="RETURN">مرتجع</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      رقم الدفعة (Batch)
                    </label>
                    <input
                      type="text"
                      value={stockUpdate.batchNumber}
                      onChange={(e) =>
                        setStockUpdate({
                          ...stockUpdate,
                          batchNumber: e.target.value,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                      placeholder="رقم الدفعة أو Lot"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      تاريخ الصلاحية
                    </label>
                    <input
                      type="date"
                      value={stockUpdate.expiryDate}
                      onChange={(e) =>
                        setStockUpdate({
                          ...stockUpdate,
                          expiryDate: e.target.value,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                </div>

                <div>
                  <label className="flex items-center cursor-pointer bg-blue-50 p-2 rounded border border-blue-200">
                    <input
                      type="checkbox"
                      checked={!stockUpdate.isApproved}
                      onChange={(e) =>
                        setStockUpdate({
                          ...stockUpdate,
                          isApproved: !e.target.checked,
                        })
                      }
                      className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                    />
                    <span className="mr-2 text-sm font-medium text-blue-800">
                      يتطلب موافقة المدير (مسودة)
                    </span>
                  </label>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    المرجع
                  </label>
                  <input
                    type="text"
                    value={stockUpdate.reference}
                    onChange={(e) =>
                      setStockUpdate({
                        ...stockUpdate,
                        reference: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    placeholder="رقم الطلب أو المرجع"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    ملاحظات
                  </label>
                  <textarea
                    value={stockUpdate.notes}
                    onChange={(e) =>
                      setStockUpdate({ ...stockUpdate, notes: e.target.value })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    rows={3}
                    placeholder="ملاحظات إضافية..."
                  />
                </div>
              </div>

              <div className="flex justify-end space-x-2 space-x-reverse mt-6">
                <button
                  onClick={() => setShowStockUpdateModal(false)}
                  className="px-4 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  إلغاء
                </button>
                <button
                  onClick={updateStock}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
                >
                  تحديث المخزون
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Transfer Modal */}
      {showTransferModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-11/12 md:w-1/2 shadow-lg rounded-md bg-white">
            <div className="mt-3">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-medium text-gray-900">
                  نقل مخزون بين المستودعات
                </h3>
                <button
                  onClick={() => setShowTransferModal(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  ✕
                </button>
              </div>

              <div className="space-y-4">
                <div className="bg-blue-50 p-3 rounded text-sm text-blue-800">
                  سيتم نقل الكمية المحددة من مستودع المصدر إلى مستودع الوجهة
                  بشكل مباشر.
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      من مستودع
                    </label>
                    <input
                      type="text"
                      value={
                        inventory.find(
                          (i) => i.warehouseId === transferData.fromWarehouseId,
                        )?.warehouseName || ""
                      }
                      disabled
                      className="w-full px-3 py-2 border bg-gray-100 rounded-md"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      إلى مستودع
                    </label>
                    <select
                      value={transferData.toWarehouseId}
                      onChange={(e) =>
                        setTransferData({
                          ...transferData,
                          toWarehouseId: e.target.value,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    >
                      <option value="">اختر الوجهة</option>
                      {warehouses.map((wh) => (
                        <option key={wh.id} value={wh.id}>
                          {wh.name}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      الكمية
                    </label>
                    <input
                      type="number"
                      value={transferData.quantity}
                      onChange={(e) =>
                        setTransferData({
                          ...transferData,
                          quantity: parseInt(e.target.value) || 0,
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                      max={
                        inventory.find(
                          (i) =>
                            i.productId === transferData.productId &&
                            i.warehouseId === transferData.fromWarehouseId,
                        )?.available || 0
                      }
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      الدفعة (Batch)
                    </label>
                    <input
                      type="text"
                      value={transferData.batchNumber}
                      disabled
                      className="w-full px-3 py-2 border bg-gray-100 rounded-md"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    ملاحظات التحويل
                  </label>
                  <textarea
                    value={transferData.notes}
                    onChange={(e) =>
                      setTransferData({
                        ...transferData,
                        notes: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    rows={2}
                  />
                </div>
              </div>

              <div className="flex justify-end space-x-2 space-x-reverse mt-6">
                <button
                  onClick={() => setShowTransferModal(false)}
                  className="px-4 py-2 bg-gray-300 text-gray-700 rounded-md"
                >
                  إلغاء
                </button>
                <button
                  onClick={transferStock}
                  className="px-4 py-2 bg-orange-600 text-white rounded-md hover:bg-orange-700 shadow-sm transition-all"
                >
                  بدء النقل
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from "react";
import {
  CubeIcon,
  ArrowPathIcon,
  ExclamationTriangleIcon,
  CurrencyDollarIcon,
  ArrowTrendingUpIcon,
  TableCellsIcon,
} from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../services/companyAwareApi";
import { useCurrency } from "../../hooks/useCurrency";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";

interface InventoryStats {
  totalProducts: number;
  totalStock: number;
  totalValue: number;
  potentialRevenue: number;
  potentialProfit: number;
  lowStockCount: number;
  outOfStockCount: number;
  lowStockItems: any[];
  outOfStockItems: any[];
}

const InventoryAnalytics: React.FC = () => {
  const { formatPrice } = useCurrency();
  const [stats, setStats] = useState<InventoryStats | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/reports/inventory-detailed");
      if (response.data.success) {
        setStats(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching inventory stats:", error);
    } finally {
      setLoading(false);
    }
  };

  const metricCards = [
    {
      title: "قيمة المخزون (بالتكلفة)",
      value: formatPrice(stats?.totalValue || 0),
      icon: CurrencyDollarIcon,
      color: "text-blue-600 bg-blue-50 dark:bg-blue-900/20",
    },
    {
      title: "إيرادات محتملة",
      value: formatPrice(stats?.potentialRevenue || 0),
      icon: ArrowTrendingUpIcon,
      color: "text-green-600 bg-green-50 dark:bg-green-900/20",
    },
    {
      title: "أرباح محتملة للمخزون",
      value: formatPrice(stats?.potentialProfit || 0),
      icon: CurrencyDollarIcon,
      color: "text-purple-600 bg-purple-50 dark:bg-purple-900/20",
    },
    {
      title: "منتجات منخفضة المخزون",
      value: stats?.lowStockCount || 0,
      icon: ExclamationTriangleIcon,
      color: "text-yellow-600 bg-yellow-50 dark:bg-yellow-900/20",
    },
  ];

  return (
    <div className="p-6 bg-gray-50 dark:bg-gray-900 min-h-screen" dir="rtl">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-8 gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <CubeIcon className="h-8 w-8 text-blue-600" />
