import React, { useState, useEffect } from "react";
import {
  ChartBarIcon,
  ArrowPathIcon,
  ArrowTrendingUpIcon,
  ExclamationTriangleIcon,
  ArchiveBoxIcon,
  CurrencyDollarIcon,
} from "@heroicons/react/24/outline";
import { useTranslation } from "react-i18next";
import { companyAwareApi } from "../../services/companyAwareApi";
import { useCurrency } from "../../hooks/useCurrency";

interface InventoryStats {
  totalItems: number;
  totalValue: number;
  lowStockCount: number;
  outOfStockCount: number;
  topMovingItems: { productName: string; movementCount: number }[];
}

const InventoryReports: React.FC = () => {
  const { t } = useTranslation();
  const { formatPrice } = useCurrency();
  const [stats, setStats] = useState<InventoryStats | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/inventory");
      if (response.data.success) {
        const items = response.data.data;

        // Aggregate by product for stats
        const productStats: Record<
          string,
          { totalStock: number; price: number }
        > = {};
        items.forEach((item: any) => {
          const pid = item.productId;
          if (!productStats[pid]) {
            productStats[pid] = {
              totalStock: 0,
              price: item.products.price || 0,
            };
          }
          productStats[pid].totalStock += item.quantity;
        });

        const productList = Object.values(productStats);
        const totalItems = productList.length;
        const totalValue = productList.reduce(
          (acc, p) => acc + p.price * p.totalStock,
          0,
        );
        const lowStockCount = productList.filter(
          (p) => p.totalStock > 0 && p.totalStock <= 5,
        ).length;
        const outOfStockCount = productList.filter(
          (p) => p.totalStock === 0,
        ).length;

        setStats({
          totalItems,
          totalValue,
          lowStockCount,
          outOfStockCount,
          topMovingItems: [],
        });
      }
    } catch (error) {
      console.error("Error fetching inventory stats:", error);
    } finally {
      setLoading(false);
    }
  };

  const statCards = [
    {
      title: t("dashboard.totalProducts"),
      value: stats?.totalItems || 0,
      icon: ArchiveBoxIcon,
      color: "bg-blue-50 text-blue-600",
    },
    {
      title: t("common.totalValue", "إجمالي قيمة المخزون"),
      value: formatPrice(stats?.totalValue || 0),
      icon: CurrencyDollarIcon,
      color: "bg-green-50 text-green-600",
    },
    {
      title: t("dashboard.lowStock"),
      value: stats?.lowStockCount || 0,
      icon: ExclamationTriangleIcon,
      color: "bg-yellow-50 text-yellow-600",
    },
    {
      title: t("products.outOfStock"),
      value: stats?.outOfStockCount || 0,
      icon: ArrowTrendingUpIcon, // Closest relevant
      color: "bg-red-50 text-red-600",
    },
  ];

  return (
    <div className="p-4 sm:p-6 lg:p-8 bg-gray-50 dark:bg-gray-900 min-h-screen">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-8">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <ChartBarIcon className="h-8 w-8 text-blue-600" />
            {t("sidebar.inventoryReports")}
          </h1>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
            {t(
              "inventory.reportsDescription",
              "تحليلات وإحصائيات المخزون والنمو",
            )}
          </p>
        </div>

        <button
          onClick={fetchStats}
          className="mt-4 md:mt-0 flex items-center justify-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors shadow-sm"
        >
          <ArrowPathIcon
            className={`h-4 w-4 ${loading ? "animate-spin" : ""}`}
          />
          {t("common.updateData")}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        {statCards.map((card, index) => (
          <div
            key={index}
            className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4"
          >
            <div className={`p-3 rounded-lg ${card.color}`}>
              <card.icon className="h-6 w-6" />
            </div>
            <div>
              <p className="text-sm font-medium text-gray-500 dark:text-gray-400">
                {card.title}
              </p>
              <p className="text-xl font-bold text-gray-900 dark:text-white">
                {loading ? "..." : card.value}
              </p>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
            {t("inventory.stockDistribution", "توزيع المخزون")}
          </h2>
          <div className="h-64 flex items-center justify-center text-gray-400 dark:text-gray-500 italic">
            {t("common.comingSoon", "جاري العمل على الرسوم البيانية...")}
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
            {t("inventory.topMovingProducts", "أكثر المنتجات حركة")}
          </h3>
          <div className="h-64 flex items-center justify-center text-gray-400 dark:text-gray-500 italic">
            {t("common.noData")}
          </div>
        </div>
      </div>
    </div>
  );
};

export default InventoryReports;

import React, { useState, useEffect } from "react";
import {
  BuildingOfficeIcon,
  MapPinIcon,
  PlusIcon,
  PencilSquareIcon,
  TrashIcon,
  CheckCircleIcon,
  XCircleIcon,
  InboxStackIcon,
} from "@heroicons/react/24/outline";
import { companyAwareApi } from "../../services/companyAwareApi";
import { useTranslation } from "react-i18next";

interface Warehouse {
  id: string;
  name: string;
  location: string | null;
  type: string;
  capacity: number | null;
  isActive: boolean;
  createdAt: string;
}

const WarehouseManagement: React.FC = () => {
  const { t } = useTranslation();
  const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingWarehouse, setEditingWarehouse] = useState<Warehouse | null>(
    null,
  );
  const [formData, setFormData] = useState({
    name: "",
    location: "",
    type: "main",
    capacity: "",
  });

  const fetchWarehouses = async () => {
    try {
      setLoading(true);
      const response = await companyAwareApi.get("/warehouses");
      if (response.data.success) {
        setWarehouses(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching warehouses:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWarehouses();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const data = {
        ...formData,
        capacity: formData.capacity ? parseInt(formData.capacity) : null,
      };

      if (editingWarehouse) {
        await companyAwareApi.put(`/warehouses/${editingWarehouse.id}`, data);
      } else {
        await companyAwareApi.post("/warehouses", data);
      }

      setShowModal(false);
      setEditingWarehouse(null);
      setFormData({ name: "", location: "", type: "main", capacity: "" });
      fetchWarehouses();
    } catch (error: any) {
      alert(error.response?.data?.message || "فشل في حفظ المخزن");
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا المخزن؟")) return;
    try {
      const response = await companyAwareApi.delete(`/warehouses/${id}`);
      if (response.data.success) {
        fetchWarehouses();
      }
    } catch (error: any) {
      alert(error.response?.data?.message || "فشل في حذف المخزن");
    }
  };

  const handleEdit = (warehouse: Warehouse) => {
    setEditingWarehouse(warehouse);
    setFormData({
      name: warehouse.name,
      location: warehouse.location || "",
      type: warehouse.type,
      capacity: warehouse.capacity?.toString() || "",
    });
    setShowModal(true);
  };

  return (
    <div className="p-6 bg-gray-50 dark:bg-gray-900 min-h-screen">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
            <BuildingOfficeIcon className="h-8 w-8 text-blue-600" />
            إدارة المخازن
          </h1>
          <p className="text-gray-500 dark:text-gray-400">
            إدارة مواقع التخزين والمستودعات الخاصة بك
          </p>
        </div>
        <button
          onClick={() => {
            setEditingWarehouse(null);
            setFormData({ name: "", location: "", type: "main", capacity: "" });
            setShowModal(true);
          }}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition"
        >
          <PlusIcon className="h-5 w-5" />
          إضافة مخزن جديد
        </button>
      </div>

      {loading ? (
        <div className="flex justify-center p-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {warehouses.map((warehouse) => (
            <div
              key={warehouse.id}
              className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6 hover:shadow-md transition"
            >
              <div className="flex justify-between items-start mb-4">
                <div className="bg-blue-50 dark:bg-blue-900/30 p-3 rounded-lg">
                  <InboxStackIcon className="h-6 w-6 text-blue-600" />
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => handleEdit(warehouse)}
                    className="p-2 text-gray-400 dark:text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 transition"
                  >
                    <PencilSquareIcon className="h-5 w-5" />
                  </button>
                  <button
                    onClick={() => handleDelete(warehouse.id)}
                    className="p-2 text-gray-400 dark:text-gray-500 hover:text-red-600 dark:hover:text-red-400 transition"
                  >
                    <TrashIcon className="h-5 w-5" />
                  </button>
                </div>
              </div>

              <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-1">
                {warehouse.name}
              </h3>
              <div className="flex items-center text-gray-500 dark:text-gray-400 text-sm mb-4">
                <MapPinIcon className="h-4 w-4 mr-1 ml-1" />
                {warehouse.location || "لا يوجد موقع محدد"}
              </div>

              <div className="flex justify-between items-center pt-4 border-t border-gray-50 dark:border-gray-700">
                <span
                  className={`px-3 py-1 rounded-full text-xs font-medium ${
                    warehouse.isActive
                      ? "bg-green-100 text-green-700"
                      : "bg-red-100 text-red-700"
                  }`}
                >
                  {warehouse.isActive ? "نشط" : "غير نشط"}
                </span>
                <span className="text-xs text-gray-400 dark:text-gray-500">
                  السعة: {warehouse.capacity || "غير محدد"}
                </span>
              </div>
            </div>
          ))}

          {warehouses.length === 0 && (
            <div className="col-span-full py-12 text-center bg-gray-50 dark:bg-gray-800 rounded-xl border-2 border-dashed border-gray-200 dark:border-gray-700">
              <BuildingOfficeIcon className="h-12 w-12 text-gray-300 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-600 dark:text-gray-400">
                لا توجد مخازن حالياً
              </h3>
              <p className="text-gray-400 dark:text-gray-500">
                ابدأ بإضافة أول مخزن لشركتك
              </p>
            </div>
          )}
        </div>
      )}

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 dark:bg-black/70 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md overflow-hidden">
            <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
              <h3 className="text-xl font-bold text-gray-800 dark:text-white">
                {editingWarehouse ? "تعديل بيانات المخزن" : "إضافة مخزن جديد"}
              </h3>
              <button
                onClick={() => setShowModal(false)}
                className="text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <XCircleIcon className="h-6 w-6" />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  اسم المخزن *
                </label>
                <input
                  type="text"
                  required
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                  placeholder="مثال: المخزن الرئيسي"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  الموقع / العنوان
                </label>
                <input
                  type="text"
                  value={formData.location}
                  onChange={(e) =>
                    setFormData({ ...formData, location: e.target.value })
                  }
                  className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                  placeholder="مثال: مدينة نصر، القاهرة"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    النوع
                  </label>
                  <select
                    value={formData.type}
                    onChange={(e) =>
                      setFormData({ ...formData, type: e.target.value })
                    }
                    className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                  >
                    <option value="main">رئيسي</option>
                    <option value="cold">تبريد</option>
                    <option value="secondary">فرعي</option>
                    <option value="fulfillment">شحن</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    السعة القصوى
                  </label>
                  <input
                    type="number"
                    value={formData.capacity}
                    onChange={(e) =>
                      setFormData({ ...formData, capacity: e.target.value })
                    }
                    className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                    placeholder="1000"
                  />
                </div>
              </div>
              <div className="pt-4 flex gap-3">
                <button
                  type="submit"
                  className="flex-1 bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 transition"
                >
                  {editingWarehouse ? "حفظ التغييرات" : "إضافة المخزن"}
                </button>
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 py-2 rounded-lg font-bold hover:bg-gray-200 dark:hover:bg-gray-600 transition"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default WarehouseManagement;

import { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import {
  ArrowLeft,
  Star,
  Check,
  Download,
  Users,
  Calendar,
  Shield,
  Zap,
  AlertCircle,
  Sparkles,
} from "lucide-react";
import { toast } from "react-hot-toast";
import {
  getFeatureAccessBadgeClasses,
  getFeatureAccessKind,
  getFeatureAccessLabel,
  getMarketplaceFeatureItems,
} from "./featureCatalog";

interface MarketplaceApp {
  id: string;
  slug: string;
  name: string;
  nameEn?: string;
  category: string;
  description: string;
  descriptionEn?: string;
  icon?: string;
  coverImage?: string;
  screenshots?: any;
  pricingModel: string;
  monthlyPrice?: number;
  yearlyPrice?: number;
  setupFee?: number;
  trialDays: number;
  features: any;
  limitations?: any;
  requiredApps?: any;
  isActive: boolean;
  isFeatured: boolean;
  isPopular: boolean;
  installCount: number;
  unitPrice?: number;
  unitName?: string;
  isInstalled?: boolean;
  activePricingModel?: string;
  rating?: number;
  reviewCount: number;
  reviews?: any[];
  pricingRules?: any[];
  _count?: {
    installations: number;
    reviews: number;
  };
}

export default function AppDetails() {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const [app, setApp] = useState<MarketplaceApp | null>(null);
  const [loading, setLoading] = useState(true);
  const [installing, setInstalling] = useState(false);
  const [showPricingDialog, setShowPricingDialog] = useState(false);

  useEffect(() => {
    if (slug) {
      fetchAppDetails();
    }
  }, [slug]);

  const fetchAppDetails = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/marketplace/apps/${slug}`);
      setApp(response.data.data);
    } catch (error) {
      console.error("Error fetching app details:", error);
      toast.error("خطأ في جلب تفاصيل الأداة");
    } finally {
      setLoading(false);
    }
  };

  const handleInstall = async () => {
    if (!app) return;

    if (app.isInstalled && app.activePricingModel !== "PAY_PER_USE") {
      toast.error("هذه الأداة مفعلة بالفعل");
      return;
    }

    if (app.pricingModel === "FREE") {
      executeInstall("FREE");
    } else {
      setShowPricingDialog(true);
    }
  };

  const executeInstall = async (model: string) => {
    if (!app) return;
    try {
      setInstalling(true);

      const response = await apiClient.post(`/marketplace/apps/${app.slug}/install`, {
        pricingModel: model,
      });
      const autoInstalledRequiredApps =
        response.data?.data?.autoInstalledRequiredApps ?? [];
      const autoInstalledNames = autoInstalledRequiredApps.map(
        (requiredApp: { name?: string; slug: string }) =>
          requiredApp.name || requiredApp.slug,
      );

      toast.success(
        autoInstalledNames.length > 0
          ? `تم تفعيل ${app.name} مع المتطلبات: ${autoInstalledNames.join("، ")}`
          : `تم تفعيل ${app.name} بنجاح! 🎉`,
      );
      await fetchAppDetails();
      navigate("/marketplace");
    } catch (error: any) {
      if (error.response?.status === 401) {
        toast.error("يرجى تسجيل الدخول أولاً");
        navigate("/auth/login");
        return;
      }

      const errorMsg = error.response?.data?.message || "خطأ في تفعيل الأداة";
      toast.error(errorMsg);

      if (error.response?.data?.requiredApps) {
        toast.error(
          `يتطلب تفعيل: ${error.response.data.requiredApps.map((requiredApp: any) => requiredApp.name).join("، ")}`,
        );
      }
    } finally {
      setInstalling(false);
      setShowPricingDialog(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="text-gray-600 dark:text-gray-400 mt-4">
            جاري التحميل...
          </p>
        </div>
      </div>
    );
  }

  if (!app) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="text-center">
          <AlertCircle size={48} className="text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 dark:text-gray-400">الأداة غير موجودة</p>
          <button
            onClick={() => navigate("/marketplace")}
            className="mt-4 text-blue-600 hover:text-blue-700"
          >
            العودة إلى Growth Tools
          </button>
        </div>
      </div>
    );
  }

  const featureItems = getMarketplaceFeatureItems(app);
  const limitations = app.limitations
    ? typeof app.limitations === "string"
      ? JSON.parse(app.limitations)
      : app.limitations
    : null;
  const requiredApps = app.requiredApps
    ? typeof app.requiredApps === "string"
      ? JSON.parse(app.requiredApps)
      : app.requiredApps
    : null;

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <button
            onClick={() => navigate("/marketplace")}
            className="flex items-center gap-2 text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white mb-4"
          >
            <ArrowLeft size={20} />
            العودة إلى Growth Tools
          </button>

          <div className="flex items-start justify-between">
            <div className="flex items-start gap-6">
              <div className="w-20 h-20 bg-blue-100 dark:bg-blue-900/30 rounded-xl flex items-center justify-center text-4xl flex-shrink-0">
                {app.icon || "📦"}
              </div>
              <div>
                <div className="flex items-center gap-3 mb-2">
                  <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
                    {app.name}
                  </h1>
                  <span
                    className={`inline-flex items-center rounded-full px-3 py-1 text-xs font-bold ${getFeatureAccessBadgeClasses(getFeatureAccessKind(app.pricingModel))}`}
                  >
                    {getFeatureAccessLabel(getFeatureAccessKind(app.pricingModel))}
                  </span>
                  {app.isFeatured && (
                    <span className="bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-400 px-3 py-1 rounded-full text-sm font-semibold flex items-center gap-1">
                      <Sparkles size={14} />
                      مميز
                    </span>
                  )}
                </div>
                <p className="text-gray-600 dark:text-gray-300 text-lg mb-3">
                  {app.description}
                </p>
                <div className="flex items-center gap-6 text-sm text-gray-600 dark:text-gray-400">
                  {app.rating && (
                    <div className="flex items-center gap-1">
                      <Star
                        size={16}
                        className="text-yellow-400 fill-yellow-400"
                      />
                      <span className="font-semibold">
                        {app.rating.toFixed(1)}
                      </span>
                      <span>({app.reviewCount} تقييم)</span>
                    </div>
                  )}
                  <div className="flex items-center gap-1">
                    <Download size={16} />
                    <span>
                      {app.installCount.toLocaleString("ar-EG")} تثبيت
                    </span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Calendar size={16} />
                    <span>تجربة مجانية {app.trialDays} يوم</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-gray-50 dark:bg-gray-900 rounded-2xl p-6 min-w-[320px] shadow-sm border border-gray-100 dark:border-gray-800">
              <div className="space-y-4 mb-6">
                {/* Subscription Card Preview */}
                <div
                  className={`p-4 rounded-xl bg-white dark:bg-gray-800 border-2 relative overflow-hidden ${app.activePricingModel === "SUBSCRIPTION"
                    ? "border-blue-500 shadow-md"
                    : "border-blue-500/20"
                    }`}
                >
                  {app.activePricingModel === "SUBSCRIPTION" && (
                    <div className="absolute top-0 left-0 bg-blue-500 text-white text-[10px] px-2 py-0.5 rounded-br-lg font-bold">
                      نشط حالياً
                    </div>
                  )}
                  <div className="flex justify-between items-center mb-1">
                    <span className="text-sm font-semibold text-gray-900 dark:text-white">
                      اشتراك شهري
                    </span>
                    {app.monthlyPrice && (
                      <span className="text-blue-600 font-bold">
                        {app.monthlyPrice} ج/شهر
                      </span>
                    )}
                  </div>
                  <p className="text-[10px] text-gray-500">
                    وصول كامل لجميع المميزات
                  </p>
                </div>

                {/* PPU Card Preview */}
                {app.pricingModel === "PAY_PER_USE" && (
                  <div
                    className={`p-4 rounded-xl bg-white dark:bg-gray-800 border-2 relative overflow-hidden ${app.activePricingModel === "PAY_PER_USE"
                      ? "border-amber-500 shadow-md"
                      : "border-amber-500/20"
                      }`}
                  >
                    {app.activePricingModel === "PAY_PER_USE" && (
                      <div className="absolute top-0 left-0 bg-amber-500 text-white text-[10px] px-2 py-0.5 rounded-br-lg font-bold">
                        نشط حالياً
                      </div>
                    )}
                    <div className="flex justify-between items-center mb-1">
                      <span className="text-sm font-semibold text-gray-900 dark:text-white">
                        دفع بالاستخدام
                      </span>
                      <span className="text-amber-600 font-bold">
                        {app.unitPrice || 0} ج / {app.unitName || "وحدة"}
                      </span>
                    </div>
                    <p className="text-[10px] text-gray-500">
                      ادفع على قد استهلاكك بس
                    </p>
                  </div>
                )}
              </div>

              <button
                onClick={handleInstall}
                disabled={
                  installing ||
                  (app.isInstalled && app.activePricingModel === "SUBSCRIPTION")
                }
                className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white px-6 py-4 rounded-xl font-bold transition-all shadow-lg shadow-blue-500/20 hover:shadow-blue-500/30 flex items-center justify-center gap-2"
              >
                {installing ? (
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                ) : (
                  <>
                    <Zap size={20} className="fill-current" />
                    {app.isInstalled ? "تحديث الاشتراك" : "تفعيل الأداة الآن"}
                  </>
                )}
              </button>

              {app.setupFee && app.setupFee > 0 && (
                <p className="text-xs text-gray-500 dark:text-gray-400 text-center mt-3">
                  + رسوم إعداد لمرة واحدة: {app.setupFee} ج
                </p>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-8">
            {/* Tools & Features */}
            <div className="bg-white dark:bg-gray-800 rounded-2xl p-8 border border-gray-100 dark:border-gray-700 shadow-sm">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
                      <Check className="text-green-600" size={24} />
                    </div>
                    المزايا الظاهرة قبل التفعيل
                  </h2>
                  <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                    كل ميزة موضحة بوسم واضح: مجاني أو مدفوع أو حسب الاستخدام.
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {featureItems.length > 0 ? (
                  featureItems.map((feature) => (
                    <div
                      key={feature.key}
                      className="flex items-start justify-between gap-4 p-4 rounded-xl bg-gray-50 dark:bg-gray-900/50 border border-transparent hover:border-green-500/20 transition-all group"
                    >
                      <div className="flex items-start gap-4">
                        <div className="w-8 h-8 rounded-full bg-white dark:bg-gray-800 shadow-sm flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform">
                          <Sparkles size={16} className="text-green-500" />
                        </div>
                        <div>
                          <div className="text-gray-700 dark:text-gray-300 font-medium leading-relaxed">
                            {feature.name}
                          </div>
                          <div className="mt-1 text-sm leading-6 text-gray-500 dark:text-gray-400">
                            {feature.description}
                          </div>
                        </div>
                      </div>
                      <span
                        className={`shrink-0 rounded-full px-2.5 py-1 text-[11px] font-bold ${getFeatureAccessBadgeClasses(feature.access)}`}
                      >
                        {getFeatureAccessLabel(feature.access)}
                      </span>
                    </div>
                  ))
                ) : (
                  <div className="col-span-2 text-center py-8 text-gray-500">
                    لا يوجد تفاصيل إضافية للمميزات حالياً
                  </div>
                )}
              </div>
            </div>

            {/* Pricing Details */}
            {app.pricingRules && app.pricingRules.length > 0 && (
              <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
                  💰 تفاصيل التسعير
                </h2>
                <div className="space-y-3">
                  {app.pricingRules.map((rule: any) => (
                    <div
                      key={rule.id}
                      className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-900 rounded-lg"
                    >
                      <div>
                        <div className="font-semibold text-gray-900 dark:text-white">
                          {rule.name}
                        </div>
                        {rule.description && (
                          <div className="text-sm text-gray-600 dark:text-gray-400">
                            {rule.description}
                          </div>
                        )}
                      </div>
                      <div className="text-lg font-bold text-blue-600">
                        {rule.price} ج
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Reviews */}
            {app.reviews && app.reviews.length > 0 && (
              <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
                  ⭐ التقييمات
                </h2>
                <div className="space-y-4">
                  {app.reviews.map((review: any) => (
                    <div
                      key={review.id}
                      className="border-b border-gray-200 dark:border-gray-700 pb-4 last:border-0"
                    >
                      <div className="flex items-center gap-2 mb-2">
                        <div className="flex">
                          {[...Array(5)].map((_, i) => (
                            <Star
                              key={i}
                              size={16}
                              className={
                                i < review.rating
                                  ? "text-yellow-400 fill-yellow-400"
                                  : "text-gray-300"
                              }
                            />
                          ))}
                        </div>
                        {review.isVerified && (
                          <span className="text-xs bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-400 px-2 py-0.5 rounded">
                            موثق
                          </span>
                        )}
                      </div>
                      {review.title && (
                        <h4 className="font-semibold text-gray-900 dark:text-white mb-1">
                          {review.title}
                        </h4>
                      )}
                      {review.comment && (
                        <p className="text-gray-600 dark:text-gray-300 text-sm">
                          {review.comment}
                        </p>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Requirements */}
            {requiredApps && requiredApps.length > 0 && (
              <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-xl p-6">
                <h3 className="font-bold text-gray-900 dark:text-white mb-3 flex items-center gap-2">
                  <AlertCircle size={20} className="text-yellow-600" />
                  متطلبات التشغيل
                </h3>
                <p className="text-sm text-gray-700 dark:text-gray-300 mb-3">
                  هذه الأداة تتطلب تفعيل الأدوات التالية أولاً:
                </p>
                <ul className="space-y-2">
                  {requiredApps.map((reqApp: string, idx: number) => (
                    <li
                      key={idx}
                      className="text-sm text-gray-700 dark:text-gray-300 flex items-center gap-2"
                    >
                      <div className="w-2 h-2 bg-yellow-600 rounded-full"></div>
                      {reqApp}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Limitations */}
            {limitations && Object.keys(limitations).length > 0 && (
              <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
                <h3 className="font-bold text-gray-900 dark:text-white mb-3 flex items-center gap-2">
                  <Shield size={20} />
                  القيود
                </h3>
                <ul className="space-y-2">
                  {Object.entries(limitations).map(([key, value]) => (
                    <li
                      key={key}
                      className="text-sm text-gray-600 dark:text-gray-400"
                    >
                      <span className="font-medium">{key}:</span>{" "}
                      {String(value)}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Support */}
            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl p-6">
              <h3 className="font-bold text-gray-900 dark:text-white mb-3 flex items-center gap-2">
                <Users size={20} className="text-blue-600" />
                الدعم
              </h3>
              <p className="text-sm text-gray-700 dark:text-gray-300 mb-4">
                هل تحتاج مساعدة؟ فريق الدعم جاهز لمساعدتك
              </p>
              <button className="w-full bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors">
                تواصل مع الدعم
              </button>
            </div>
          </div>
        </div>
      </div>
      {/* Pricing Choice Dialog */}
      {showPricingDialog && app && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200"
          onClick={() => setShowPricingDialog(false)}
        >
          <div
            className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl max-w-md w-full overflow-hidden animate-in zoom-in-95 duration-200"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="p-6 text-right">
              <div className="flex items-center gap-4 mb-6 flex-row-reverse">
                <div className="w-12 h-12 rounded-xl bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 flex items-center justify-center text-2xl">
                  {app.icon || "🚀"}
                </div>
                <div className="text-right">
                  <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                    {app.name}
                  </h2>
                  <p className="text-sm text-gray-500">
                    اختر نظام الدفع المناسب لك
                  </p>
                </div>
              </div>

              <div className="space-y-4">
                {/* Subscription Option */}
                <button
                  onClick={() => executeInstall("SUBSCRIPTION")}
                  disabled={
                    app.isInstalled && app.activePricingModel === "SUBSCRIPTION"
                  }
                  className={`w-full p-4 rounded-xl border-2 transition-all text-right group relative overflow-hidden ${app.isInstalled && app.activePricingModel === "SUBSCRIPTION"
                    ? "border-blue-500 bg-blue-50/50 dark:bg-blue-900/20 cursor-default"
                    : "border-gray-100 dark:border-gray-700 hover:border-blue-500 hover:bg-blue-50/50 dark:hover:bg-blue-900/20"
                    }`}
                >
                  {app.isInstalled &&
                    app.activePricingModel === "SUBSCRIPTION" && (
                      <div className="absolute top-0 left-0 bg-blue-500 text-white text-[10px] px-2 py-0.5 rounded-br-lg font-bold">
                        نشط حالياً
                      </div>
                    )}
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-bold text-gray-900 dark:text-white">
                      {app.activePricingModel === "PAY_PER_USE"
                        ? "ترقية لاشتراك شهري"
                        : "اشتراك شهري كامل"}
                    </span>
                    <span className="text-blue-600 font-bold">
                      {(app.monthlyPrice ?? 0) > 0
                        ? `${app.monthlyPrice} ج/شهر`
                        : "مجاني"}
                    </span>
                  </div>
                  <p className="text-xs text-gray-500">
                    ادفع مبلغ ثابت شهرياً واستمتع بجميع مميزات الأداة بلا حدود.
                  </p>
                </button>

                {/* Pay Per Use Option */}
                {app.pricingModel === "PAY_PER_USE" && (
                  <button
                    onClick={() => executeInstall("PAY_PER_USE")}
                    disabled={
                      app.isInstalled &&
                      app.activePricingModel === "PAY_PER_USE"
                    }
                    className={`w-full p-4 rounded-xl border-2 transition-all text-right group relative overflow-hidden ${app.isInstalled &&
                      app.activePricingModel === "PAY_PER_USE"
                      ? "border-amber-500 bg-amber-50/50 dark:bg-amber-900/20 cursor-default"
                      : "border-gray-100 dark:border-gray-700 hover:border-amber-500 hover:bg-amber-50/50 dark:hover:bg-amber-900/20"
                      }`}
                  >
                    {app.isInstalled &&
                      app.activePricingModel === "PAY_PER_USE" && (
                        <div className="absolute top-0 left-0 bg-amber-500 text-white text-[10px] px-2 py-0.5 rounded-br-lg font-bold">
                          نشط حالياً
                        </div>
                      )}
                    <div className="flex items-center justify-between mb-1">
                      <span className="font-bold text-gray-900 dark:text-white flex items-center gap-1">
                        حسب الاستخدام
                        <Zap
                          size={14}
                          className="text-amber-500 fill-current"
                        />
                      </span>
                      <span className="text-amber-600 font-bold">
                        {app.unitPrice || 0} ج / {app.unitName || "وحدة"}
                      </span>
                    </div>
                    <p className="text-xs text-gray-500">
                      ادفع فقط مقابل ما تستهلكه فعلياً. مناسب للمشاريع المبتدئة.
                    </p>
                  </button>
                )}
              </div>

              <button
                onClick={() => setShowPricingDialog(false)}
                className="w-full mt-6 py-3 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 text-sm font-medium transition-colors border border-gray-100 dark:border-gray-700 rounded-xl"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import { toast } from "react-hot-toast";
import {
  Package,
  Check,
  Star,
  TrendingUp,
  Zap,
  Gift,
  DollarSign,
  ArrowRight,
  ShieldCheck,
  Clock,
} from "lucide-react";

interface Bundle {
  id: string;
  name: string;
  slug: string;
  description: string;
  price: number;
  discount: number;
  isActive: boolean;
  monthlyPrice: number;
  yearlyPrice?: number;
  apps: Array<{
    id: string;
    name: string;
    slug: string;
    description: string;
    monthlyPrice: number;
    logo?: string;
  }>;
}

export default function BundleDetails() {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const [bundle, setBundle] = useState<Bundle | null>(null);
  const [loading, setLoading] = useState(true);
  const [activating, setActivating] = useState(false);

  useEffect(() => {
    if (slug) {
      fetchBundleDetails();
    }
  }, [slug]);

  const fetchBundleDetails = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/marketplace/bundles/${slug}`);

      if (response.data.success) {
        setBundle(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching bundle:", error);
      toast.error("لم يتم العثور على الباقة");
      navigate("/marketplace/bundles");
    } finally {
      setLoading(false);
    }
  };

  const handleSubscribe = async () => {
    try {
      setActivating(true);
      const response = await apiClient.post(
        `/marketplace/bundles/${slug}/subscribe`,
        {},
      );

      if (response.data.success) {
        toast.success(response.data.message);
        setTimeout(() => {
          navigate("/marketplace/my-apps");
        }, 1500);
      }
    } catch (error: any) {
      console.error("Subscription error:", error);
      if (error.response?.status === 401) {
        navigate("/auth/login", {
          state: { from: `/marketplace/bundle/${slug}` },
        });
        return;
      }

      if (error.response?.data?.message) {
        toast.error(error.response.data.message);
      } else {
        toast.error("حدث خطأ أثناء الاشتراك");
      }
    } finally {
      setActivating(false);
    }
  };

  const calculateOriginalPrice = (b: Bundle) => {
    return b.apps.reduce(
      (sum, app) => sum + parseFloat(app.monthlyPrice.toString()),
      0,
    );
  };

  const calculateSavings = (b: Bundle) => {
    const original = calculateOriginalPrice(b);
    const bundlePrice =
      parseFloat(b.monthlyPrice.toString()) || parseFloat(b.price.toString());
    return original - bundlePrice;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  if (!bundle) return null;

  const originalPrice = calculateOriginalPrice(bundle);
  const bundlePrice = parseFloat(
    bundle.monthlyPrice?.toString() || bundle.price?.toString() || "0",
  );
  const savings = calculateSavings(bundle);

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-12">
      {/* Hero Section */}
      <div className="bg-gradient-to-br from-purple-700 via-indigo-600 to-blue-600 text-white pt-24 pb-32 rounded-b-[3rem] shadow-xl relative overflow-hidden">
        {/* Background Patterns */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10">
          <div className="absolute top-10 left-10 w-64 h-64 bg-white rounded-full mix-blend-overlay filter blur-3xl animate-pulse"></div>
          <div className="absolute bottom-10 right-10 w-96 h-96 bg-yellow-300 rounded-full mix-blend-overlay filter blur-3xl animate-pulse delay-700"></div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <div className="flex flex-col md:flex-row items-center justify-between gap-12">
            <div className="flex-1 text-center md:text-right">
              <div className="inline-flex items-center gap-2 bg-white/20 backdrop-blur-sm px-4 py-2 rounded-full text-sm font-medium mb-6 border border-white/10">
                <Gift className="w-4 h-4 text-yellow-300" />
                <span>عرض حصري لفترة محدودة</span>
              </div>
              <h1 className="text-4xl md:text-6xl font-bold mb-6 leading-tight">
                {bundle.name}
              </h1>
              <p className="text-xl text-indigo-100 mb-8 max-w-2xl leading-relaxed">
                {bundle.description}
              </p>

              <div className="flex flex-wrap items-center gap-4 justify-center md:justify-start">
                <div className="flex items-center gap-2 bg-black/20 px-6 py-3 rounded-2xl backdrop-blur-md">
                  <span className="text-gray-300 line-through text-lg">
                    {originalPrice.toFixed(0)} ج.م
                  </span>
                  <span className="text-3xl font-bold text-white">
                    {bundlePrice.toFixed(0)} ج.م
                  </span>
                  <span className="text-sm text-gray-300">/ شهرياً</span>
                </div>
                <div className="bg-green-500/20 text-green-300 px-4 py-3 rounded-2xl border border-green-500/30 flex items-center gap-2 font-bold">
                  <TrendingUp size={20} />
                  توفير {savings.toFixed(0)} ج.م
                </div>
              </div>
            </div>

            <div className="hidden md:block">
              {/* Abstract visual or Icon for bundle */}
              <div className="bg-white/10 p-8 rounded-3xl backdrop-blur-md border border-white/20 transform rotate-3 hover:rotate-0 transition-all duration-500">
                <Package size={120} className="text-white opacity-90" />
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-20 relative z-20">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content (Apps List) */}
          <div className="lg:col-span-2 space-y-8">
            <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-xl p-8">
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-3">
                <Zap className="text-yellow-500" />
                ماذا تتضمن الباقة؟
              </h2>
              <div className="space-y-4">
                {bundle.apps.map((app) => (
                  <div
                    key={app.id}
                    className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors border border-gray-100 dark:border-gray-700"
                  >
                    <div className="bg-indigo-100 dark:bg-indigo-900/50 p-3 rounded-xl">
                      <Package className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start">
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-1">
                          {app.name}
                        </h3>
                        <span className="text-sm font-medium text-gray-500 dark:text-gray-400 bg-white dark:bg-gray-800 px-2 py-1 rounded-lg border border-gray-200 dark:border-gray-600">
                          {app.monthlyPrice} ج.م
                        </span>
                      </div>
                      <p className="text-gray-600 dark:text-gray-300 text-sm leading-relaxed">
                        {app.description}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Features/Trust Section */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg text-center">
                <ShieldCheck className="w-10 h-10 text-green-500 mx-auto mb-3" />
                <h3 className="font-bold text-gray-900 dark:text-white mb-1">
                  دفع آمن
                </h3>
                <p className="text-sm text-gray-500">
                  عمليات دفع مشفرة وآمنة تماماً
                </p>
              </div>
              <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg text-center">
