  MARKETPLACE_POSITIONING_LABELS,
} from "./featureCatalog";

interface MarketplaceApp {
  id: string;
  slug: string;
  name: string;
  nameEn?: string;
  category: string;
  description: string;
  icon?: string;
  coverImage?: string;
