  name: string;
  nameEn?: string;
  description: string;
  monthlyPrice: number;
  yearlyPrice?: number;
  discount: number;
  isFeatured: boolean;
}

type ToolCollectionId = "ALL" | "CORE" | "ADD_ONS" | "FREE" | "PAID";

const categoryIcons: Record<string, any> = {
  ECOMMERCE: Store,
  HR: Users,
  AI: Brain,
