  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState<string>("");
  const [searchQuery, setSearchQuery] = useState("");
  const [sortBy, setSortBy] = useState("featured");
  const [selectedCollection, setSelectedCollection] =
    useState<ToolCollectionId>("ALL");
  const [installingApp, setInstallingApp] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<"APPS" | "BUNDLES">("APPS");
  const [isInstallingAll, setIsInstallingAll] = useState(false);
  const [showPricingDialog, setShowPricingDialog] =
    useState<MarketplaceApp | null>(null);

  const [searchParams] = useSearchParams();

  useEffect(() => {
    const categoryParam = searchParams.get("category");
    if (categoryParam) {
      setSelectedCategory(categoryParam);
    }
  }, [searchParams]);

  useEffect(() => {
    fetchData();
  }, [selectedCategory, searchQuery, sortBy]);

  const markAppsInstalled = (slugs: string[]) => {
    if (slugs.length === 0) return;

    const installedSlugs = new Set(slugs);
    setApps((prevApps) =>
      prevApps.map((app) =>
        installedSlugs.has(app.slug)
          ? {
            ...app,
            isInstalled: true,
            installCount: app.isInstalled ? app.installCount : app.installCount + 1,
          }
          : app,
      ),
    );
  };

  const getRequiredAppNames = (app: MarketplaceApp) =>
    normalizeRequiredApps(app.requiredApps).map(
      (requiredSlug) =>
        apps.find((candidate) => candidate.slug === requiredSlug)?.name || requiredSlug,
    );

  // Install all available apps
  const handleInstallAll = async () => {
    const visibleApps = apps.filter((app) =>
      matchesToolCollection(app, selectedCollection),
    );
    const uninstalledApps = sortAppsByDependencies(visibleApps).filter(
      (app) => !app.isInstalled,
    );

    if (uninstalledApps.length === 0) {
      toast.success("جميع الأدوات مثبتة بالفعل! 🎉");
      return;
    }

    if (
      !window.confirm(
        `هل أنت متأكد من تفعيل ${uninstalledApps.length} أداة دفعة واحدة؟`,
      )
    ) {
      return;
    }

    setIsInstallingAll(true);
    let successCount = 0;
    let failCount = 0;

    const toastId = toast.loading("جاري تفعيل الأدوات... 0%");

    try {
      // Install sequentially to avoid overloading the server
      for (let i = 0; i < uninstalledApps.length; i++) {
        const app = uninstalledApps[i];

        try {
          if (!app) continue;
          // Update toast process
          const progress = Math.round(((i + 1) / uninstalledApps.length) * 100);
          toast.loading(`جاري تفعيل ${app.name}... ${progress}%`, {
            id: toastId,
          });

          const response = await apiClient.post(
            `/marketplace/apps/${app.slug}/install`,
            { pricingModel: getDefaultPricingModel(app) },
          );
          const autoInstalledRequiredApps =
            response.data?.data?.autoInstalledRequiredApps ?? [];

          markAppsInstalled([
            app.slug,
            ...autoInstalledRequiredApps.map((requiredApp: { slug: string }) => requiredApp.slug),
          ]);

          successCount++;
        } catch (error) {
          console.error(`Failed to install ${app?.name || "app"}`, error);
          failCount++;
        }
      }

      if (failCount === 0) {
        toast.success(`تم تفعيل ${successCount} أداة بنجاح! 🚀`, {
          id: toastId,
        });
      } else {
        toast.success(`تم تفعيل ${successCount} أداة، وفشل ${failCount}`, {
          id: toastId,
        });
      }
    } catch (error) {
      toast.error("حدث خطأ أثناء عملية التفعيل الجماعي", { id: toastId });
    } finally {
      setIsInstallingAll(false);
    }
  };

  const fetchData = async () => {
    try {
      setLoading(true);

      const params: any = {};
      if (selectedCategory) params.category = selectedCategory;
      if (searchQuery) params.search = searchQuery;
      if (sortBy) params.sort = sortBy;

      const [appsRes, categoriesRes, bundlesRes] = await Promise.all([
        apiClient.get("/marketplace/apps", { params }),
        apiClient.get("/marketplace/categories"),
        apiClient.get("/marketplace/bundles"),
      ]);

      setApps(appsRes.data.data);
      setCategories(categoriesRes.data.data);
      setBundles(bundlesRes.data.data);
    } catch (error) {
      console.error("Error fetching marketplace data:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleInstallApp = (slug: string) => {
    navigate(`/marketplace/${slug}`);
  };

  const handleQuickInstall = async (
    e: React.MouseEvent,
    app: MarketplaceApp,
  ) => {
    e.stopPropagation(); // Prevent navigation to details
    if (app.isInstalled && app.pricingModel !== "PAY_PER_USE") return;

    if (
      app.pricingModel === "FREE" ||
      (app.pricingModel === "SUBSCRIPTION" && app.monthlyPrice === 0)
    ) {
      executeInstall(app, app.pricingModel);
    } else {
      setShowPricingDialog(app);
    }
  };

  const executeInstall = async (app: MarketplaceApp, pricingModel: string) => {
    try {
      setInstallingApp(app.slug);

      const response = await apiClient.post(`/marketplace/apps/${app.slug}/install`, {
        pricingModel,
      });
      const autoInstalledRequiredApps =
        response.data?.data?.autoInstalledRequiredApps ?? [];
      const autoInstalledNames = autoInstalledRequiredApps.map(
        (requiredApp: { name?: string; slug: string }) =>
          requiredApp.name || requiredApp.slug,
      );

      toast.success(
        autoInstalledNames.length > 0
          ? `تم تفعيل ${app.name} مع المتطلبات: ${autoInstalledNames.join("، ")}`
          : `تم تفعيل ${app.name} بنجاح! 🎉`,
      );

      markAppsInstalled([
        app.slug,
        ...autoInstalledRequiredApps.map((requiredApp: { slug: string }) => requiredApp.slug),
      ]);
    } catch (error: any) {
      if (error.response?.status === 401) {
        toast.error("يرجى تسجيل الدخول أولاً");
        navigate("/auth/login");
        return;
      }

      const errorMsg = error.response?.data?.message || "خطأ في تفعيل الأداة";
      toast.error(errorMsg);

      if (error.response?.data?.requiredApps) {
        const required = error.response.data.requiredApps;
        toast.error(
          `يتطلب تفعيل: ${required.map((a: any) => a.name).join("، ")}`,
        );
      } else {
        const requiredNames = getRequiredAppNames(app);
        if (requiredNames.length > 0) {
          toast(`هذا التطبيق يحتاج: ${requiredNames.join("، ")}`);
        }
      }
    } finally {
      setInstallingApp(null);
    }
  };

  const getPriceDisplay = (app: MarketplaceApp) => {
    if (app.pricingModel === "FREE") {
      return "مجاني";
    }
    if (app.pricingModel === "PAY_PER_USE") {
      return app.unitPrice
        ? `${app.unitPrice} ج / ${app.unitName || "وحدة"}`
        : "حسب الاستخدام";
    }
    if (app.monthlyPrice) {
      return `${app.monthlyPrice} ج/شهر`;
    }
    return "اتصل بنا";
  };

  const visibleApps = apps.filter((app) =>
    matchesToolCollection(app, selectedCollection),
  );
  const selectedCollectionMeta =
    toolCollections.find((collection) => collection.id === selectedCollection) ||
    toolCollections[0];
  const selectedCategoryMeta = categories.find(
    (category) => category.category === selectedCategory,
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Main Content with Sidebar */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
          {/* Sidebar */}
          <div className="md:col-span-3 space-y-6">
            {/* Install All Button */}
            <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-gray-700">
              <button
                onClick={handleInstallAll}
                disabled={
                  isInstallingAll ||
                  visibleApps.length === 0 ||
                  visibleApps.every((app) => app.isInstalled)
                }
                className="w-full bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-700 hover:to-emerald-700 text-white py-3 px-4 rounded-lg font-bold shadow-md hover:shadow-lg transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
              >
                {isInstallingAll ? (
                  <>
                    <Loader2 size={18} className="animate-spin" />
                    جاري التثبيت...
                  </>
                ) : (
                  <>
                    <Zap size={18} className="fill-current" />
                    تفعيل كل الأدوات
                  </>
                )}
              </button>
              <p className="text-xs text-gray-500 text-center mt-2">
                تفعيل الأدوات الظاهرة الآن مع مراعاة المتطلبات تلقائياً
              </p>
            </div>

            <div className="bg-gradient-to-br from-indigo-600 to-slate-900 rounded-2xl p-5 text-white shadow-lg">
              <div className="flex items-center justify-between gap-3">
                <div className="text-right">
                  <div className="text-sm font-black">قوالب المتجر</div>
                  <p className="mt-2 text-xs leading-6 text-indigo-100">
                    اشترِ قالب متجرك من المحفظة ثم طبّقه وكمّل تخصيصه من صفحة مستقلة داخل المتجر.
                  </p>
                </div>
                <Sparkles size={22} />
              </div>
              <button
                onClick={() => navigate("/marketplace/themes")}
                className="mt-4 w-full rounded-xl bg-white/15 px-4 py-3 text-sm font-bold backdrop-blur hover:bg-white/20"
              >
                فتح متجر القوالب
              </button>
            </div>

            {/* Main Menu (Marketplace Browser) */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
              <div className="p-4 border-b border-gray-100 dark:border-gray-700">
                <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                  <Store size={18} />
                  Growth Tools
                </h3>
              </div>

              <div className="p-2 space-y-1">
                {/* General/All Apps */}
                <button
                  onClick={() => {
                    setSelectedCategory("");
                    setSelectedCollection("ALL");
                    setActiveTab("APPS");
                  }}
                  className={`w-full text-right px-4 py-3 rounded-lg font-medium transition-colors flex items-center justify-between ${selectedCategory === "" && selectedCollection === "ALL" && activeTab !== "BUNDLES"
                    ? "bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400"
                    : "text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50"
                    }`}
                >
                  <span className="flex items-center gap-3">
                    <Store size={18} />
                    كل الأدوات
                  </span>
                  <span className="bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded text-xs">
                    {apps.length}
                  </span>
                </button>

                {/* Bundles Tab */}
                <button
                  onClick={() => {
                    setSelectedCategory("");
                    setActiveTab("BUNDLES");
                  }}
                  className={`w-full text-right px-4 py-3 rounded-lg font-medium transition-colors flex items-center justify-between ${activeTab === "BUNDLES"
                    ? "bg-yellow-50 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-400"
                    : "text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50"
                    }`}
                >
                  <span className="flex items-center gap-3">
                    <Package size={18} />
                    باقات التوفير
                  </span>
                  <span className="bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded text-xs">
                    جديد
                  </span>
                </button>
              </div>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
              <div className="p-4 border-b border-gray-100 dark:border-gray-700">
                <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                  <Sparkles size={18} />
                  تنظيم الأدوات
                </h3>
              </div>

              <div className="p-2 space-y-2">
                {toolCollections.map((collection) => {
                  const Icon = collection.icon;
                  const count = apps.filter((app) =>
                    matchesToolCollection(app, collection.id),
                  ).length;

                  return (
                    <button
                      key={collection.id}
                      onClick={() => {
                        setSelectedCollection(collection.id);
                        setActiveTab("APPS");
                      }}
                      className={`w-full rounded-xl border px-4 py-3 text-right transition-all ${
                        selectedCollection === collection.id
                          ? "border-slate-900 bg-slate-900 text-white dark:border-slate-200 dark:bg-slate-100 dark:text-slate-900"
                          : "border-gray-100 bg-gray-50 text-gray-700 hover:border-gray-200 hover:bg-white dark:border-gray-700 dark:bg-gray-900/40 dark:text-gray-200 dark:hover:bg-gray-800"
                      }`}
                    >
                      <div className="flex items-start justify-between gap-3">
                        <div>
                          <div className="flex items-center gap-2 font-bold">
                            <Icon size={15} />
                            <span>{collection.label}</span>
                          </div>
                          <div
                            className={`mt-1 text-xs leading-6 ${
                              selectedCollection === collection.id
                                ? "text-slate-200 dark:text-slate-700"
                                : "text-gray-500 dark:text-gray-400"
                            }`}
                          >
                            {collection.description}
                          </div>
                        </div>
                        <span
                          className={`rounded-full px-2 py-1 text-[10px] font-bold ${
                            selectedCollection === collection.id
                              ? "bg-white/15 text-white dark:bg-slate-300 dark:text-slate-900"
                              : "bg-white text-slate-700 border border-gray-200 dark:bg-gray-800 dark:text-slate-200 dark:border-gray-700"
                          }`}
                        >
                          {count}
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Categories */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
              <div className="p-4 border-b border-gray-100 dark:border-gray-700">
                <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                  <Filter size={18} />
                  الأقسام
                </h3>
              </div>

              <div className="p-2 space-y-1">
                {categories.map((cat) => {
                  const Icon = categoryIcons[cat.category] || Package;
                  return (
                    <button
                      key={cat.category}
                      onClick={() => {
                        setSelectedCategory(cat.category);
                        setActiveTab("APPS");
                      }}
                      className={`w-full text-right px-4 py-3 rounded-lg font-medium transition-colors flex items-center justify-between ${selectedCategory === cat.category
                        ? "bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400"
                        : "text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50"
                        }`}
                    >
                      <span className="flex items-center gap-3">
                        <Icon size={18} />
                        {cat.name}
                      </span>
                      <span className="bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded text-xs">
                        {cat.count}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Main Content Area */}
          <div className="md:col-span-9">
            {/* Unlimited Access Hero Section */}
            {user?.role !== "SUPER_ADMIN" &&
              user?.company?.plan !== "ENTERPRISE" && (
                <div className="mb-8 relative overflow-hidden rounded-2xl bg-gradient-to-br from-indigo-900 via-blue-900 to-indigo-950 text-white shadow-xl border border-blue-500/30">
                  {/* Background Patterns */}
                  <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/10 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl"></div>
                  <div className="absolute bottom-0 left-0 w-48 h-48 bg-indigo-500/10 rounded-full translate-y-1/2 -translate-x-1/2 blur-3xl"></div>

                  <div className="relative p-8 md:p-10 flex flex-col md:flex-row items-center gap-8">
                    <div className="flex-1 text-right">
                      <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-200 text-xs font-bold mb-4">
                        <Zap size={14} className="fill-current" />
                        عرض خاص لفترة محدودة
                      </div>
                      <h2 className="text-3xl md:text-4xl font-extrabold mb-4 leading-tight">
                        امتلك{" "}
                        <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-300 to-cyan-200">
                          أدوات النمو بالكامل
                        </span>{" "}
                        بضغطة واحدة!
                      </h2>
                      <p className="text-blue-100/80 text-lg mb-6 max-w-2xl leading-relaxed">
                        بدلاً من شراء كل أداة على حدة، افتح جميع أدوات النمو
                        الحالية والمستقبلية فوراً مع وضوح كامل لما هو مجاني وما
                        هو مدفوع داخل كل أداة.
                      </p>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-8">
                        {[
                          "وصول لجميع الأدوات (HR, AI, CRM, إلخ)",
                          "تفعيل تلقائي لأي أداة جديدة مستقبلاً",
                          "دعم فني مخصص للأعمال الكبيرة",
                          "توفير أكثر من 70% من قيمة الاشتراكات المنفصلة",
                        ].map((item, i) => (
                          <div
                            key={i}
                            className="flex items-center gap-2 text-sm text-blue-100/90"
                          >
                            <CheckCircle2 size={16} className="text-blue-400" />
                            <span>{item}</span>
                          </div>
                        ))}
                      </div>

                      <div className="flex flex-wrap items-center gap-6">
                        <button
                          onClick={async () => {
                            if (
                              !window.confirm(
                                'هل أنت متأكد من رغبتك في الترقية لـ "الوصول الشامل"؟ سيتم خصم 999 ج من محفظتك.',
                              )
                            )
                              return;
                            try {
                              const response = await fetch(
                                `${getApiUrl()}/marketplace/unlimited/subscribe`,
                                {
                                  method: "POST",
                                  headers: {
                                    Authorization: `Bearer ${tokenManager.getAccessToken()}`,
                                    "Content-Type": "application/json",
                                  },
                                },
                              );
                              const res = await response.json();
                              if (res.success) {
                                toast.success(res.message);
                                // Refresh user/page
                                window.location.reload();
                              } else {
                                toast.error(res.message);
                              }
                            } catch (err) {
                              toast.error("حدث خطأ أثناء معالجة الطلب");
                            }
                          }}
                          className="px-8 py-4 rounded-xl bg-white text-blue-900 font-bold hover:bg-blue-50 transition-all shadow-lg hover:shadow-xl hover:-translate-y-0.5 flex items-center justify-center gap-2"
                        >
                          <Crown size={20} className="text-blue-600" />
                          اشترك الآن في الوصول الشامل
                        </button>
                        <div className="text-right">
                          <div className="text-2xl font-bold">
                            999 ج{" "}
                            <span className="text-sm font-normal opacity-70">
                              /شهرياً
                            </span>
                          </div>
                          <div className="text-xs text-blue-300/80 line-through">
                            بدلاً من 4500 ج
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="hidden lg:block w-72 h-72 relative">
                      <div className="absolute inset-0 bg-blue-400 opacity-20 blur-[100px] animate-pulse"></div>
                      <div className="relative z-10 w-full h-full bg-white/5 backdrop-blur-sm border border-white/10 rounded-3xl p-6 rotate-3 transform hover:rotate-0 transition-transform duration-500 shadow-2xl overflow-hidden">
                        <div className="mb-4 flex items-center justify-between">
                          <div className="flex gap-2">
                            <div className="w-3 h-3 rounded-full bg-red-400"></div>
                            <div className="w-3 h-3 rounded-full bg-yellow-400"></div>
                            <div className="w-3 h-3 rounded-full bg-green-400"></div>
                          </div>
                          <Crown
                            size={24}
                            className="text-yellow-400 opacity-50"
                          />
                        </div>
                        <div className="space-y-4">
                          {[1, 2, 3, 4].map((i) => (
                            <div
                              key={i}
                              className="h-6 w-full rounded-lg bg-white/10 animate-pulse"
                              style={{ width: `${Math.random() * 50 + 50}%` }}
                            ></div>
                          ))}
                        </div>
                        <div className="absolute inset-x-0 bottom-0 p-8 bg-gradient-to-t from-blue-900/80">
                          <div className="w-full py-3 rounded-xl bg-blue-500 text-center font-bold text-sm shadow-lg shadow-blue-500/40">
                            Premium Active
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}

            <div className="mb-6 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-700 dark:bg-slate-800">
              <div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
                <div className="text-right">
                  <div className="text-xs font-black uppercase tracking-[0.22em] text-slate-500 dark:text-slate-400">
                    Growth Tools
                  </div>
                  <h1 className="mt-2 text-2xl font-black text-slate-900 dark:text-white">
                    أدوات النمو
                  </h1>
                  <p className="mt-2 max-w-3xl text-sm leading-7 text-slate-600 dark:text-slate-300">
                    كل أداة تعرض الآن ماذا تقدم، لمن تناسب، أين تظهر، وهل
                    المزايا مجانية أو مدفوعة أو حسب الاستخدام قبل التفعيل.
                  </p>
                </div>
                <div className="rounded-2xl bg-slate-50 px-4 py-3 text-right text-xs leading-6 text-slate-600 dark:bg-slate-900/50 dark:text-slate-300">
                  بدل ما تكون المزايا مخفية داخل النظام، صارت مرئية من أول
                  بطاقة وحتى صفحة التفاصيل.
                </div>
              </div>
            </div>

            {/* Header / Sort */}
            <div className="flex flex-wrap items-center justify-between gap-4 mb-6 bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
              <h2 className="text-lg font-bold text-gray-900 dark:text-white">
                {activeTab === "BUNDLES"
                  ? "باقات التوفير المميزة"
                  : selectedCategoryMeta
                    ? `${selectedCollectionMeta.label} • ${selectedCategoryMeta.name}`
                    : selectedCollectionMeta.label}
              </h2>

              <div className="flex items-center gap-4">
                {/* Search Input */}
                <div className="relative hidden md:block">
                  <Search
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400"
                    size={16}
                  />
                  <input
                    type="text"
                    placeholder="بحث..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-64 pr-9 pl-4 py-2 text-sm rounded-lg bg-gray-50 dark:bg-gray-700 border-none focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-gray-100 placeholder-gray-400"
                  />
                </div>

                <div className="flex items-center gap-3">
                  <span className="text-sm text-gray-500 dark:text-gray-400">
                    ترتيب حسب:
                  </span>
                  <select
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value)}
                    className="bg-gray-50 dark:bg-gray-700 border-none rounded-lg text-sm text-gray-700 dark:text-gray-200 focus:ring-2 focus:ring-blue-500 py-2 pl-8 pr-4"
                  >
                    <option value="featured">الأكثر تميزاً</option>
                    <option value="popular">الأكثر شعبية</option>
                    <option value="newest">الأحدث</option>
                    <option value="price_low">السعر: الأقل</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Content Switcher */}
            {activeTab === "BUNDLES" ? (
              /* Bundles Grid */
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {bundles.map((bundle) => (
                  <div
                    key={bundle.id}
                    className="bg-white dark:bg-gray-800 border border-yellow-200 dark:border-yellow-900/50 rounded-xl p-6 hover:shadow-lg transition-all cursor-pointer relative overflow-hidden group"
                    onClick={() =>
                      navigate(`/marketplace/bundle/${bundle.slug}`)
                    }
                  >
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-yellow-400 to-orange-500"></div>
                    <div className="flex items-start justify-between mb-4">
                      <div>
                        <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2 group-hover:text-yellow-600 transition-colors">
                          {bundle.name}
                        </h3>
                        <p className="text-gray-600 dark:text-gray-300 text-sm line-clamp-2">
                          {bundle.description}
                        </p>
                      </div>
                      <div className="bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full text-xs font-bold border border-yellow-200">
                        وفر {bundle.discount}%
                      </div>
                    </div>

                    <div className="flex items-center justify-between mt-6">
                      <div>
                        <span className="text-2xl font-bold text-gray-900 dark:text-white">
                          {bundle.monthlyPrice} ج
                        </span>
                        <span className="text-xs text-gray-500 dark:text-gray-400 mr-1">
                          /شهر
                        </span>
                      </div>
                      <button className="bg-yellow-50 text-yellow-700 hover:bg-yellow-100 px-4 py-2 rounded-lg font-semibold text-sm flex items-center gap-2 transition-colors">
                        تفاصيل الباقة
                        <ArrowRight size={16} />
                      </button>
                    </div>
                  </div>
                ))}
                {bundles.length === 0 && (
                  <div className="col-span-full text-center py-12 bg-white dark:bg-gray-800 rounded-xl border border-dashed border-gray-300 dark:border-gray-700">
                    <Package size={48} className="text-gray-400 mx-auto mb-4" />
                    <p className="text-gray-500">لا توجد باقات متاحة حالياً</p>
                  </div>
                )}
              </div>
            ) : /* Apps Grid */
              loading ? (
                <div className="text-center py-20 bg-white dark:bg-gray-800 rounded-xl">
                  <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                  <p className="text-gray-600 dark:text-gray-400 mt-4">
                    جاري تحميل الأدوات...
                  </p>
                </div>
              ) : visibleApps.length === 0 ? (
                <div className="text-center py-20 bg-white dark:bg-gray-800 rounded-xl border border-dashed border-gray-300 dark:border-gray-700">
                  <Package size={48} className="text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-600 dark:text-gray-400">
                    لا توجد أدوات متاحة ضمن هذا التنظيم حالياً
                  </p>
                </div>
              ) : (
                <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
                  {visibleApps.map((app) => {
                    const Icon = categoryIcons[app.category] || Package;
                    const featureItems = getMarketplaceFeatureItems(app);
                    const previewFeatures = featureItems.slice(0, 2);
                    const accessKind = getFeatureAccessKind(app.pricingModel);
                    const positioning = getMarketplacePositioning(app);
                    const positioningRows = positioning
                      ? ([
                        {
                          key: "audience",
                          label: MARKETPLACE_POSITIONING_LABELS.audience,
                          value: positioning.audience,
                        },
                        {
                          key: "surface",
                          label: MARKETPLACE_POSITIONING_LABELS.surface,
                          value: positioning.surface,
                        },
                        {
                          key: "outcome",
                          label: MARKETPLACE_POSITIONING_LABELS.outcome,
                          value: positioning.outcome,
                        },
                      ] as const)
                      : [];
                    return (
                      <div
                        key={app.id}
                        className={`relative group bg-white dark:bg-gray-800 rounded-xl shadow-sm hover:shadow-xl transition-all duration-300 border ${app.isInstalled
                          ? "border-green-500/50 ring-1 ring-green-500/50"
                          : "border-gray-200 dark:border-gray-700"
                          } overflow-hidden cursor-pointer flex flex-col`}
                        onClick={() => handleInstallApp(app.slug)}
                      >
                        {/* Header */}
                        <div className="p-5 border-b border-gray-100 dark:border-gray-700 flex-grow">
                          <div className="flex items-start justify-between mb-4">
                            <div
                              className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl transition-colors shadow-sm ${app.isInstalled
                                ? "bg-gradient-to-br from-green-50 to-emerald-100 text-green-600 dark:from-green-900/30 dark:to-green-800/30 dark:text-green-400"
                                : "bg-gradient-to-br from-blue-50 to-indigo-100 text-blue-600 dark:from-blue-900/30 dark:to-indigo-800/30 dark:text-blue-400"
                                }`}
                            >
                              {app.icon || <Icon size={24} />}
                            </div>
                            {app.isFeatured && (
                              <div className="bg-yellow-50 text-yellow-700 border border-yellow-200 px-2 py-0.5 rounded text-[10px] font-bold shadow-sm">
                                مميز
                              </div>
                            )}
                          </div>

                          <div className="mb-1">
                            <h3 className="font-bold text-gray-900 dark:text-white text-lg leading-tight mb-1">
                              {app.name}
                            </h3>
                            <div className="flex flex-wrap gap-2 mb-2">
                              {app.isInstalled && (
                                <span className="inline-flex items-center gap-1 text-[10px] bg-green-50 text-green-700 border border-green-200 px-1.5 py-0.5 rounded-full font-medium">
                                  <Check size={10} strokeWidth={3} />
                                  مثبت ومفعل
                                </span>
                              )}
                              <span
                                className={`inline-flex items-center gap-1 text-[10px] px-1.5 py-0.5 rounded-full font-medium ${getFeatureAccessBadgeClasses(accessKind)}`}
                              >
                                {app.pricingModel === "PAY_PER_USE" ? (
                                  <Zap
                                    size={10}
                                    className="fill-current text-amber-500"
                                  />
                                ) : null}
                                {getFeatureAccessLabel(accessKind)}
                              </span>
                              <span
                                className={`inline-flex items-center gap-1 text-[10px] px-1.5 py-0.5 rounded-full font-medium ${getToolRoleBadgeClasses(app)}`}
                              >
                                {getToolRoleLabel(app)}
                              </span>
                            </div>
                          </div>

                          <p className="text-gray-500 dark:text-gray-400 text-sm line-clamp-2 h-10 leading-relaxed">
                            {app.description}
                          </p>

                          {positioningRows.length > 0 && (
                            <div className="mt-4 space-y-2 rounded-2xl border border-blue-100 bg-blue-50/60 p-3 dark:border-blue-900/40 dark:bg-blue-950/20">
                              {positioningRows.map((row) => (
                                <div
                                  key={`${app.slug}-${row.key}`}
                                  className="rounded-xl bg-white/80 px-3 py-2 text-right dark:bg-slate-900/40"
                                >
                                  <div className="text-[10px] font-bold uppercase tracking-[0.18em] text-blue-700 dark:text-blue-300">
                                    {row.label}
                                  </div>
                                  <div className="mt-1 text-xs leading-6 text-slate-600 dark:text-slate-300">
                                    {row.value}
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}

                          <div className="mt-4 space-y-2">
                            <div className="text-[11px] font-bold uppercase tracking-[0.16em] text-gray-500 dark:text-gray-400">
                              أبرز المزايا
                            </div>
                            {previewFeatures.length > 0 ? (
                              <>
                                {previewFeatures.map((feature) => (
                                  <div
                                    key={`${app.slug}-${feature.key}`}
                                    className="rounded-xl border border-gray-100 bg-gray-50/80 p-3 dark:border-gray-700 dark:bg-gray-900/40"
                                  >
                                    <div className="flex items-start justify-between gap-3">
                                      <div className="text-right">
                                        <div className="text-sm font-semibold text-gray-900 dark:text-white">
                                          {feature.name}
                                        </div>
                                        <div className="mt-1 text-xs leading-6 text-gray-500 dark:text-gray-400">
                                          {feature.description}
                                        </div>
                                      </div>
                                      <span
                                        className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-bold ${getFeatureAccessBadgeClasses(feature.access)}`}
                                      >
                                        {getFeatureAccessLabel(feature.access)}
                                      </span>
                                    </div>
                                  </div>
                                ))}
                                {featureItems.length > previewFeatures.length && (
                                  <div className="text-xs font-medium text-blue-600 dark:text-blue-300">
                                    +{featureItems.length - previewFeatures.length} مزايا إضافية
                                  </div>
                                )}
                              </>
                            ) : (
                              <div className="rounded-xl border border-dashed border-gray-200 px-3 py-4 text-xs leading-6 text-gray-500 dark:border-gray-700 dark:text-gray-400">
                                سيتم عرض تفاصيل المزايا هنا بمجرد تجهيز بيانات
                                الأداة بشكل كامل.
                              </div>
                            )}
                          </div>

                          {getRequiredAppNames(app).length > 0 && (
                            <p className="mt-3 text-xs text-amber-700 dark:text-amber-300">
                              يتطلب: {getRequiredAppNames(app).join("، ")}
                            </p>
                          )}
                        </div>

                        {/* Footer Action */}
                        <div className="p-4 bg-gray-50/50 dark:bg-gray-900/30 mt-auto border-t border-gray-100 dark:border-gray-700">
                          <div className="flex items-center justify-between gap-3">
                            <div className="font-bold text-gray-900 dark:text-white">
                              {getPriceDisplay(app)}
                            </div>

                            {app.isInstalled ? (
                              <button
                                className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-400 dark:text-gray-500 rounded-lg text-sm font-medium flex items-center gap-1 cursor-default w-fit"
                                onClick={(e) => e.stopPropagation()}
                              >
                                <Check size={14} />
                                مثبت
                              </button>
                            ) : (
                              <button
                                className="px-4 py-2 bg-white dark:bg-gray-800 hover:bg-blue-600 hover:text-white border border-gray-200 dark:border-gray-600 text-gray-700 dark:text-gray-300 rounded-lg text-sm font-semibold transition-all shadow-sm hover:shadow-md flex items-center gap-2 group/btn disabled:opacity-50 disabled:cursor-not-allowed"
                                onClick={(e) => handleQuickInstall(e, app)}
                                disabled={installingApp === app.slug}
                              >
                                {installingApp === app.slug ? (
                                  <Loader2 size={16} className="animate-spin" />
                                ) : (
                                  <Zap
                                    size={16}
                                    className="text-blue-500 group-hover/btn:text-white fill-current transition-colors"
                                  />
                                )}
                                تفعيل
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
          </div>
        </div>
      </div>
      {/* Pricing Choice Dialog */}
      {showPricingDialog && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200"
          onClick={() => setShowPricingDialog(null)}
        >
          <div
            className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl max-w-md w-full overflow-hidden animate-in zoom-in-95 duration-200"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="p-6">
              <div className="flex items-center gap-4 mb-6">
                <div className="w-12 h-12 rounded-xl bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 flex items-center justify-center text-2xl">
                  {showPricingDialog.icon || "🚀"}
                </div>
                <div>
                  <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                    {showPricingDialog.name}
                  </h2>
                  <p className="text-sm text-gray-500">
                    اختر نظام الدفع المناسب لك
                  </p>
                </div>
              </div>

              <div className="space-y-4">
                {/* Subscription Option */}
                <button
                  onClick={() => {
                    executeInstall(showPricingDialog, "SUBSCRIPTION");
                    setShowPricingDialog(null);
                  }}
                  disabled={
                    showPricingDialog.isInstalled &&
                    showPricingDialog.activePricingModel === "SUBSCRIPTION"
                  }
                  className={`w-full p-4 rounded-xl border-2 transition-all text-right group relative overflow-hidden ${showPricingDialog.isInstalled &&
                    showPricingDialog.activePricingModel === "SUBSCRIPTION"
                    ? "border-blue-500 bg-blue-50/50 dark:bg-blue-900/20 cursor-default"
                    : "border-gray-100 dark:border-gray-700 hover:border-blue-500 hover:bg-blue-50/50 dark:hover:bg-blue-900/20"
                    }`}
                >
                  {showPricingDialog.isInstalled &&
                    showPricingDialog.activePricingModel === "SUBSCRIPTION" && (
                      <div className="absolute top-0 left-0 bg-blue-500 text-white text-[10px] px-2 py-0.5 rounded-br-lg font-bold">
                        نشط حالياً
                      </div>
                    )}
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-bold text-gray-900 dark:text-white">
                      {showPricingDialog.activePricingModel === "PAY_PER_USE"
                        ? "ترقية لاشتراك شهري"
                        : "اشتراك شهري كامل"}
                    </span>
                    <span className="text-blue-600 font-bold">
                      {(showPricingDialog.monthlyPrice ?? 0) > 0
                        ? `${showPricingDialog.monthlyPrice} ج/شهر`
                        : "مجاني"}
                    </span>
                  </div>
                  <p className="text-xs text-gray-500">
                    ادفع مبلغ ثابت شهرياً واستمتع بجميع مميزات الأداة بلا حدود.
                  </p>
                </button>

                {/* Pay Per Use Option */}
                <button
                  onClick={() => {
                    executeInstall(showPricingDialog, "PAY_PER_USE");
                    setShowPricingDialog(null);
                  }}
                  disabled={
                    showPricingDialog.isInstalled &&
                    showPricingDialog.activePricingModel === "PAY_PER_USE"
                  }
                  className={`w-full p-4 rounded-xl border-2 transition-all text-right group relative overflow-hidden ${showPricingDialog.isInstalled &&
                    showPricingDialog.activePricingModel === "PAY_PER_USE"
                    ? "border-amber-500 bg-amber-50/50 dark:bg-amber-900/20 cursor-default"
                    : "border-gray-100 dark:border-gray-700 hover:border-amber-500 hover:bg-amber-50/50 dark:hover:bg-amber-900/20"
                    }`}
                >
                  {showPricingDialog.isInstalled &&
                    showPricingDialog.activePricingModel === "PAY_PER_USE" && (
                      <div className="absolute top-0 left-0 bg-amber-500 text-white text-[10px] px-2 py-0.5 rounded-br-lg font-bold">
                        نشط حالياً
                      </div>
                    )}
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-bold text-gray-900 dark:text-white flex items-center gap-1">
                      حسب الاستخدام
                      <Zap size={14} className="text-amber-500 fill-current" />
                    </span>
                    <span className="text-amber-600 font-bold">
                      {showPricingDialog.unitPrice || 0} ج /{" "}
                      {showPricingDialog.unitName || "وحدة"}
                    </span>
                  </div>
                  <p className="text-xs text-gray-500">
                    ادفع فقط مقابل ما تستهلكه فعلياً. مناسب للمشاريع المبتدئة.
                  </p>
                </button>
              </div>

              <button
                onClick={() => setShowPricingDialog(null)}
                className="w-full mt-6 py-3 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 text-sm font-medium transition-colors border border-gray-100 dark:border-gray-700 rounded-xl"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import {
  Wallet as WalletIcon,
  TrendingUp,
  TrendingDown,
  DollarSign,
  Calendar,
  Download,
  CreditCard,
  ArrowUpRight,
  ArrowDownRight,
  Package,
  Zap,
  Gift,
  FileText,
  Sparkles,
  Upload,
  CheckCircle,
  AlertCircle,
  Image as ImageIcon,
} from "lucide-react";
import { toast } from "react-hot-toast";
import { useAuth } from "../../hooks/useAuthSimple";

interface WalletData {
  id: string;
  balance: number;
  totalDeposited: number;
  totalSpent: number;
  totalRefunded: number;
  totalCashback?: number;
  currency: string;
}

interface Transaction {
  id: string;
  type: string;
  amount: number;
  balanceBefore: number;
  balanceAfter: number;
  description: string;
  createdAt: string;
  paymentMethod?: string;
}

interface BillingSummary {
  period: { start: string; end: string };
  costs: { subscriptions: number; usage: number; total: number };
  wallet: { balance: number; currency: string };
  activeApps: number;
  usageBreakdown: any[];
}

interface WalletNumber {
  id: string;
  name: string;
  number: string;
  icon?: string;
  color?: string;
}


const transactionIcons: Record<string, any> = {
  DEPOSIT: ArrowDownRight,
  DEDUCT: ArrowUpRight,
  REFUND: ArrowDownRight,
  BONUS: Gift,
  ADJUSTMENT: Zap,
  CASHBACK: Sparkles,
};

const transactionColors: Record<string, string> = {
  DEPOSIT: "text-green-600 bg-green-100 dark:bg-green-900/30",
  DEDUCT: "text-red-600 bg-red-100 dark:bg-red-900/30",
  REFUND: "text-blue-600 bg-blue-100 dark:bg-blue-900/30",
  BONUS: "text-yellow-600 bg-yellow-100 dark:bg-yellow-900/30",
  ADJUSTMENT: "text-purple-600 bg-purple-100 dark:bg-purple-900/30",
  CASHBACK: "text-pink-600 bg-pink-100 dark:bg-pink-900/30",
};

const toNumber = (value: any): number => {
  if (value === null || value === undefined) return 0;
  if (typeof value === "number") return value;
  return parseFloat(value.toString()) || 0;
};


export default function Wallet() {
  const navigate = useNavigate();
  const { user } = useAuth();

  const [wallet, setWallet] = useState<WalletData | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [billingSummary, setBillingSummary] = useState<BillingSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Receipt upload modal
  const [showRechargeModal, setShowRechargeModal] = useState(false);
  const [walletNumbers, setWalletNumbers] = useState<WalletNumber[]>([]);
  const [loadingWallets, setLoadingWallets] = useState(false);
  const [selectedWalletId, setSelectedWalletId] = useState("");
  const [rechargeAmount, setRechargeAmount] = useState("");
  const [receiptFile, setReceiptFile] = useState<File | null>(null);
  const [receiptPreview, setReceiptPreview] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const hasCompany = !!(user?.companyId && user.companyId !== "null" && user.companyId !== "undefined");

  useEffect(() => {
    if (hasCompany) {
      fetchWalletData();
    } else {
      setLoading(false);
    }
  }, [hasCompany]);

  const fetchWalletData = async () => {
    try {
      setLoading(true);
      setError(null);

      const [walletRes, transactionsRes, summaryRes] = await Promise.allSettled([
        apiClient.get("/wallet/balance"),
        apiClient.get("/wallet/transactions?limit=20"),
        apiClient.get("/wallet/billing/summary"),
      ]);

      if (walletRes.status === "fulfilled") {
        setWallet(walletRes.value.data.data);
      }
      if (transactionsRes.status === "fulfilled") {
        const td = transactionsRes.value.data.data;
        setTransactions(Array.isArray(td) ? td : td?.transactions || td?.data || []);
      }
      if (summaryRes.status === "fulfilled") {
        setBillingSummary(summaryRes.value.data.data);
      }
    } catch (error: any) {
      console.error("Error fetching wallet data:", error);
      setError("خطأ في جلب بيانات المحفظة");
    } finally {
      setLoading(false);
    }
  };

  const openRechargeModal = async () => {
    setShowRechargeModal(true);
    if (walletNumbers.length === 0) {
      try {
        setLoadingWallets(true);
        const res = await apiClient.get("/wallet-payment/wallet-numbers");
        if (res.data.success) setWalletNumbers(res.data.data || []);
      } catch {
        toast.error("تعذر تحميل أرقام المحافظ");
      } finally {
        setLoadingWallets(false);
      }
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      toast.error("يجب أن يكون الملف صورة");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error("حجم الصورة يجب ألا يتجاوز 5 ميغابايت");
      return;
    }
    setReceiptFile(file);
    const reader = new FileReader();
    reader.onload = () => setReceiptPreview(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleSubmitReceipt = async () => {
    if (!selectedWalletId) { toast.error("اختر رقم المحفظة"); return; }
    if (!rechargeAmount || parseFloat(rechargeAmount) <= 0) { toast.error("أدخل مبلغاً صحيحاً"); return; }
    if (!receiptFile) { toast.error("ارفع صورة الإيصال"); return; }

    try {
      setSubmitting(true);

      // Find or create an invoice first (using subscriptionId 'none' as a general deposit purpose)
      const formData = new FormData();
      formData.append("walletNumberId", selectedWalletId);
      formData.append("amount", rechargeAmount);
      formData.append("purpose", "wallet_recharge");
      formData.append("receipt", receiptFile);

      // Submit using the subscription renewal flow — we create a general recharge invoice
      const res = await apiClient.post("/wallet-payment/submit-receipt", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      if (res.data.success) {
        toast.success("تم إرسال إيصال الشحن بنجاح! سيتم مراجعته قريباً 📋");
        setShowRechargeModal(false);
        setReceiptFile(null);
        setReceiptPreview(null);
        setRechargeAmount("");
        setSelectedWalletId("");
        fetchWalletData();
      } else {
        toast.error(res.data.message || "حدث خطأ أثناء إرسال الإيصال");
      }
    } catch (err: any) {
      toast.error(err.response?.data?.message || "حدث خطأ أثناء إرسال الإيصال");
    } finally {
      setSubmitting(false);
    }
  };

  const getBonusInfo = (amount: number) => {
    if (amount >= 5000) return { percentage: 30, bonus: amount * 0.3 };
    if (amount >= 1000) return { percentage: 20, bonus: amount * 0.2 };
    if (amount >= 500) return { percentage: 15, bonus: amount * 0.15 };
    if (amount >= 100) return { percentage: 10, bonus: amount * 0.1 };
    return { percentage: 0, bonus: 0 };
  };

  // ─────────────── Guard: no companyId ───────────────
  if (!hasCompany && !loading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center p-4">
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-10 max-w-md text-center">
          <WalletIcon size={48} className="mx-auto text-gray-400 mb-4" />
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">المحفظة غير متاحة</h2>
          <p className="text-gray-500 dark:text-gray-400">
            هذه الصفحة مخصصة للشركات المشتركة. حسابك لا يملك محفظة مرتبطة.
          </p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto" />
          <p className="text-gray-600 dark:text-gray-400 mt-4">جاري التحميل...</p>
        </div>
      </div>
    );
  }

  const currentAmount = parseFloat(rechargeAmount) || 0;
  const bonusInfo = getBonusInfo(currentAmount);

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="bg-gradient-to-r from-green-600 to-blue-600 text-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
          <div className="text-center">
            <h1 className="text-4xl font-bold mb-4 flex items-center justify-center gap-3">
              <WalletIcon size={40} />
              المحفظة والفواتير
            </h1>
            <p className="text-xl text-green-100">إدارة رصيدك ومتابعة مصروفاتك</p>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Error Banner */}
        {error && (
          <div className="mb-6 flex items-center gap-3 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-700 dark:text-red-400">
            <AlertCircle size={20} />
            <span>{error}</span>
            <button onClick={fetchWalletData} className="ml-auto text-sm underline">إعادة المحاولة</button>
          </div>
        )}

        {/* Balance Card */}
        <div className="bg-gradient-to-br from-blue-600 to-purple-600 text-white rounded-2xl p-8 mb-8 shadow-xl">
          <div className="flex items-center justify-between mb-6">
            <div>
              <p className="text-blue-100 mb-2">رصيد المحفظة</p>
              <div className="text-5xl font-bold">
                {toNumber(wallet?.balance).toFixed(2)} {wallet?.currency || "ج.م"}
              </div>
            </div>
            <button
              onClick={openRechargeModal}
              className="bg-white text-blue-600 hover:bg-blue-50 px-6 py-3 rounded-xl font-semibold transition-colors flex items-center gap-2 shadow"
            >
              <CreditCard size={20} />
              شحن المحفظة
            </button>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {[
              { label: "إجمالي الشحن", icon: TrendingDown, value: toNumber(wallet?.totalDeposited).toFixed(2) },
              { label: "إجمالي المصروفات", icon: TrendingUp, value: toNumber(wallet?.totalSpent).toFixed(2) },
              { label: "المسترجع", icon: Gift, value: toNumber(wallet?.totalRefunded).toFixed(2) },
              { label: "مكافآت الكاش باك", icon: Sparkles, value: toNumber(wallet?.totalCashback).toFixed(2), highlight: true },
            ].map((stat) => (
              <div key={stat.label} className="bg-white/10 backdrop-blur-sm rounded-xl p-4">
                <div className={`flex items-center gap-2 mb-2 ${stat.highlight ? "text-pink-200" : "text-blue-100"}`}>
                  <stat.icon size={16} />
                  <span className="text-sm">{stat.label}</span>
                </div>
                <div className={`text-2xl font-bold ${stat.highlight ? "text-pink-200" : ""}`}>{stat.value}</div>
              </div>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Billing Summary */}
            {billingSummary && (
              <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
                  <Calendar size={24} />
                  ملخص هذا الشهر
                </h2>
                <div className="grid grid-cols-3 gap-4 mb-6">
                  {[
                    { label: "الاشتراكات", value: billingSummary.costs.subscriptions, color: "blue" },
                    { label: "الاستخدام", value: toNumber(billingSummary.costs.usage).toFixed(2), color: "purple" },
                    { label: "الإجمالي", value: toNumber(billingSummary.costs.total).toFixed(2), color: "green", bold: true },
                  ].map((item) => (
                    <div key={item.label} className={`bg-${item.color}-50 dark:bg-${item.color}-900/20 rounded-lg p-4`}>
                      <div className="text-sm text-gray-600 dark:text-gray-400 mb-1">{item.label}</div>
                      <div className={`text-2xl font-bold ${item.bold ? `text-${item.color}-600` : "text-gray-900 dark:text-white"}`}>
                        {item.value} ج
                      </div>
                    </div>
                  ))}
                </div>

                {billingSummary.usageBreakdown.length > 0 && (
                  <div>
                    <h3 className="font-semibold text-gray-900 dark:text-white mb-3">تفاصيل الاستخدام:</h3>
                    <div className="space-y-2">
                      {billingSummary.usageBreakdown.map((item: any, idx: number) => (
                        <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-900 rounded-lg">
                          <div>
                            <div className="font-medium text-gray-900 dark:text-white">{item.feature}</div>
                            <div className="text-sm text-gray-600 dark:text-gray-400">{item._sum?.quantity} عملية</div>
                          </div>
                          <div className="text-lg font-bold text-gray-900 dark:text-white">
                            {toNumber(item._sum?.totalCost).toFixed(2)} ج
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Transactions */}
            <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                  <FileText size={24} />
                  آخر الحركات
                </h2>
                <span className="text-sm text-gray-500 bg-gray-100 dark:bg-gray-700 px-3 py-1 rounded-full">
                  {transactions.length} حركة
                </span>
              </div>

              {transactions.length === 0 ? (
                <div className="text-center py-10 text-gray-500 dark:text-gray-400">
                  <DollarSign size={40} className="mx-auto mb-3 opacity-40" />
                  <p>لا توجد حركات في المحفظة بعد</p>
                  <p className="text-sm mt-1">قم بشحن المحفظة لتظهر هنا معاملاتك</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {transactions.map((tx) => {
                    const Icon = transactionIcons[tx.type] || DollarSign;
                    const colorClass = transactionColors[tx.type] || "text-gray-600 bg-gray-100";
                    const isPositive = ["DEPOSIT", "REFUND", "BONUS", "CASHBACK", "ADJUSTMENT"].includes(tx.type);
                    return (
                      <div key={tx.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-900 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                        <div className="flex items-center gap-4">
                          <div className={`w-10 h-10 rounded-full ${colorClass} flex items-center justify-center`}>
                            <Icon size={20} />
                          </div>
                          <div>
                            <div className="font-medium text-gray-900 dark:text-white">{tx.description}</div>
                            <div className="text-sm text-gray-600 dark:text-gray-400">
                              {new Date(tx.createdAt).toLocaleString("ar-EG")}
                            </div>
                          </div>
                        </div>
                        <div className="text-right">
                          <div className={`text-lg font-bold ${isPositive ? "text-green-600" : "text-red-600"}`}>
                            {isPositive ? "+" : "-"}{toNumber(tx.amount).toFixed(2)} ج
                          </div>
                          <div className="text-sm text-gray-600 dark:text-gray-400">
                            الرصيد: {toNumber(tx.balanceAfter).toFixed(2)} ج
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Quick Actions */}
            <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
              <h3 className="font-bold text-gray-900 dark:text-white mb-4">إجراءات سريعة</h3>
              <div className="space-y-3">
                <button onClick={() => navigate("/my-apps")} className="w-full bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/30 text-blue-600 dark:text-blue-400 px-4 py-3 rounded-lg font-medium transition-colors flex items-center gap-2">
                  <Package size={18} /> أدواتي المفعلة
                </button>
                <button onClick={() => navigate("/marketplace")} className="w-full bg-purple-50 dark:bg-purple-900/20 hover:bg-purple-100 dark:hover:bg-purple-900/30 text-purple-600 dark:text-purple-400 px-4 py-3 rounded-lg font-medium transition-colors flex items-center gap-2">
                  <Zap size={18} /> تصفح Marketplace
                </button>
                <button className="w-full bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-300 px-4 py-3 rounded-lg font-medium transition-colors flex items-center gap-2">
                  <Download size={18} /> تحميل الفواتير
                </button>
              </div>
            </div>

            {/* Bonus Packages */}
            <div className="bg-gradient-to-br from-yellow-50 to-orange-50 dark:from-yellow-900/20 dark:to-orange-900/20 border-2 border-yellow-400 rounded-xl p-6">
              <h3 className="font-bold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                <Gift size={20} className="text-yellow-600" /> باقات الشحن
              </h3>
              <div className="space-y-2 text-sm">
                {[
                  { range: "100 - 499 ج", bonus: "بونص 10%" },
                  { range: "500 - 999 ج", bonus: "بونص 15%" },
                  { range: "1000 - 4999 ج", bonus: "بونص 20%" },
                  { range: "5000+ ج", bonus: "بونص 30%" },
                ].map((p) => (
                  <div key={p.range} className="flex items-center justify-between">
                    <span className="text-gray-700 dark:text-gray-300">{p.range}</span>
                    <span className="font-bold text-yellow-600">{p.bonus}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Wallet Balance indicator */}
            {wallet && (
              <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
                <h3 className="font-bold text-gray-900 dark:text-white mb-2">حالة الرصيد</h3>
                <div className={`text-2xl font-bold mb-1 ${toNumber(wallet.balance) > 0 ? "text-green-600" : "text-red-600"}`}>
                  {toNumber(wallet.balance).toFixed(2)} ج
                </div>
                {toNumber(wallet.balance) <= 0 && (
                  <div className="flex items-center gap-2 text-sm text-red-600 mt-2">
                    <AlertCircle size={16} /> الرصيد منخفض — قم بالشحن لتجنب توقف الخدمات
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ─── Recharge Receipt Modal ─── */}
      {showRechargeModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl max-w-lg w-full p-6 max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                <Upload size={24} /> شحن المحفظة
              </h2>
              <button onClick={() => { setShowRechargeModal(false); setReceiptFile(null); setReceiptPreview(null); }} className="text-gray-400 hover:text-gray-600 text-2xl leading-none">×</button>
            </div>

            {/* Steps explanation */}
            <div className="mb-6 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl text-sm text-blue-800 dark:text-blue-200">
              <p className="font-semibold mb-2">📋 كيفية الشحن:</p>
              <ol className="list-decimal list-inside space-y-1">
                <li>حوّل المبلغ على أحد أرقام المحافظ أدناه</li>
                <li>التقط صورة للإيصال وارفعها هنا</li>
                <li>سيتم مراجعة الطلب وإضافة الرصيد خلال ساعات</li>
              </ol>
            </div>

            {/* Wallet Number Selection */}
            <div className="mb-5">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                اختر رقم المحفظة *
              </label>
              {loadingWallets ? (
                <div className="flex items-center gap-2 text-gray-500 text-sm py-3">
                  <div className="w-4 h-4 border-2 border-gray-300 border-t-blue-500 rounded-full animate-spin" />
                  جاري تحميل أرقام المحافظ...
                </div>
              ) : walletNumbers.length === 0 ? (
                <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg text-sm text-yellow-800 dark:text-yellow-300">
                  ⚠️ لا توجد أرقام محافظ مضافة بعد. يرجى التواصل مع الإدارة.
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-2">
                  {walletNumbers.map((wn) => (
                    <button
                      key={wn.id}
                      type="button"
                      onClick={() => setSelectedWalletId(wn.id)}
                      className={`flex items-center gap-3 p-3 rounded-lg border-2 transition-all text-left ${selectedWalletId === wn.id ? "border-blue-500 bg-blue-50 dark:bg-blue-900/20" : "border-gray-200 dark:border-gray-600 hover:border-gray-400"}`}
                    >
                      <span className="text-2xl">{wn.icon || "💳"}</span>
                      <div>
                        <div className="font-semibold text-gray-900 dark:text-white">{wn.name}</div>
                        <div className="text-sm text-gray-500 font-mono">{wn.number}</div>
                      </div>
                      {selectedWalletId === wn.id && <CheckCircle size={20} className="text-blue-500 ml-auto" />}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Amount */}
            <div className="mb-5">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                المبلغ المحوَّل (جنيه مصري) *
              </label>
              <input
                type="number"
                value={rechargeAmount}
                onChange={(e) => setRechargeAmount(e.target.value)}
                placeholder="مثلاً: 500"
                min="1"
                className="w-full px-4 py-3 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              {bonusInfo.bonus > 0 && (
                <div className="mt-2 p-3 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 rounded-lg text-sm">
                  <span className="text-yellow-700 dark:text-yellow-400 font-medium">🎁 ستحصل على بونص {bonusInfo.percentage}% = </span>
                  <span className="font-bold text-yellow-600">{bonusInfo.bonus.toFixed(2)} ج إضافية!</span>
                </div>
              )}
            </div>

            {/* Receipt Image Upload */}
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                صورة إيصال التحويل *
              </label>
              <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileChange} />
              {receiptPreview ? (
                <div className="relative">
                  <img src={receiptPreview} alt="إيصال التحويل" className="w-full h-48 object-cover rounded-lg border-2 border-dashed border-blue-400" />
                  <button
                    onClick={() => { setReceiptFile(null); setReceiptPreview(null); }}
                    className="absolute top-2 right-2 bg-red-500 text-white rounded-full w-7 h-7 flex items-center justify-center text-lg leading-none hover:bg-red-600"
                  >×</button>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full h-32 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg flex flex-col items-center justify-center gap-2 text-gray-500 hover:border-blue-400 hover:text-blue-500 transition-colors"
                >
                  <ImageIcon size={32} />
                  <span className="text-sm">انقر لرفع صورة الإيصال</span>
                  <span className="text-xs text-gray-400">PNG، JPG، JPEG · حد أقصى 5 ميغابايت</span>
                </button>
              )}
            </div>

            {/* Actions */}
            <div className="flex gap-3">
              <button
                onClick={() => { setShowRechargeModal(false); setReceiptFile(null); setReceiptPreview(null); setRechargeAmount(""); setSelectedWalletId(""); }}
                className="flex-1 bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 text-gray-900 dark:text-white px-4 py-3 rounded-lg font-semibold transition-colors"
              >
                إلغاء
              </button>
              <button
                onClick={handleSubmitReceipt}
                disabled={submitting || !selectedWalletId || !rechargeAmount || !receiptFile}
                className="flex-1 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white px-4 py-3 rounded-lg font-semibold transition-colors flex items-center justify-center gap-2"
              >
                {submitting ? (
                  <><div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> جاري الإرسال...</>
                ) : (
                  <><Upload size={18} /> إرسال الإيصال</>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { apiClient } from "../../services/apiClient";
import { useTheme } from "../../hooks/useTheme";
import toast from "react-hot-toast";

const MerchantRegister: React.FC = () => {
  const navigate = useNavigate();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    address: "",
    commissionRate: 10.0,
    autoFulfill: false,
    webhookUrl: "",
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      const response = await apiClient.post("/merchants", formData);

      if (response.data.success) {
        toast.success("تم تسجيل التاجر بنجاح!");
        navigate("/merchants");
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "حدث خطأ أثناء التسجيل");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div
        className={`max-w-2xl mx-auto ${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow-lg p-8`}
      >
        <h1
          className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"} mb-2`}
        >
          تسجيل تاجر جديد
        </h1>
        <p className={`${isDark ? "text-gray-300" : "text-gray-600"} mb-6`}>
          انضم كتاجر للدروب شيبنج وابدأ في بيع منتجاتك
        </p>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Name */}
          <div>
            <label
              className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
            >
              اسم التاجر
            </label>
            <input
              type="text"
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
              placeholder="اسم التاجر أو الشركة"
              required
            />
          </div>

          {/* Email */}
          <div>
            <label
              className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
            >
              البريد الإلكتروني
            </label>
            <input
              type="email"
              value={formData.email}
              onChange={(e) =>
                setFormData({ ...formData, email: e.target.value })
              }
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
              placeholder="email@example.com"
              required
            />
          </div>

          {/* Phone */}
          <div>
            <label
              className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
            >
              الهاتف
            </label>
            <input
              type="tel"
              value={formData.phone}
              onChange={(e) =>
                setFormData({ ...formData, phone: e.target.value })
              }
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
              placeholder="01xxxxxxxxx"
            />
          </div>

          {/* Address */}
          <div>
            <label
              className={`block text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-700"} mb-2`}
            >
              العنوان
            </label>
            <textarea
              value={formData.address}
