            </button>
            <button
              type="button"
              onClick={() => navigate(-1)}
              className={`px-6 py-3 border rounded-lg transition ${
                isDark
                  ? "border-gray-600 text-gray-300 hover:bg-gray-700"
                  : "border-gray-300 text-gray-700 hover:bg-gray-50"
              }`}
            >
              إلغاء
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

