                <ExclamationTriangleIcon className="w-12 h-12 text-white/30" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Search and Filters */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="mb-6"
        >
          <Card>
            <CardContent className="p-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Search */}
                <div className="relative">
                  <MagnifyingGlassIcon className="w-5 h-5 absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                  <input
                    type="text"
                    placeholder="ابحث عن أصل..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pr-10 pl-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                  />
                </div>

                {/* Category Filter */}
                <div className="relative">
                  <FunnelIcon className="w-5 h-5 absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                  <select
                    value={filterCategory}
                    onChange={(e) => setFilterCategory(e.target.value)}
                    className="w-full pr-10 pl-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white appearance-none"
                  >
                    <option value="all">جميع الفئات</option>
                    {categories.map((cat) => (
                      <option key={cat} value={cat}>
                        {cat}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Condition Filter */}
                <div className="relative">
                  <TagIcon className="w-5 h-5 absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                  <select
                    value={filterCondition}
                    onChange={(e) => setFilterCondition(e.target.value)}
                    className="w-full pr-10 pl-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white appearance-none"
                  >
                    <option value="all">جميع الحالات</option>
                    <option value="NEW">جديد</option>
                    <option value="GOOD">جيد</option>
                    <option value="FAIR">مقبول</option>
                    <option value="NEEDS_REPAIR">يحتاج صيانة</option>
                  </select>
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Assets Grid */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          {filteredAssets.length === 0 ? (
            <Card className="border-2 border-dashed border-gray-300 dark:border-gray-700">
              <CardContent className="p-12">
                <div className="text-center">
                  <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-blue-100 to-purple-100 dark:from-blue-900/20 dark:to-purple-900/20 rounded-full mb-4">
                    <ComputerDesktopIcon className="w-10 h-10 text-blue-600 dark:text-blue-400" />
                  </div>
                  <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
                    {searchQuery ||
                    filterCategory !== "all" ||
                    filterCondition !== "all"
                      ? "لا توجد نتائج"
                      : "لا توجد عهدة مسلمة لك"}
                  </h3>
                  <p className="text-gray-500 dark:text-gray-400 max-w-md mx-auto">
                    {searchQuery ||
                    filterCategory !== "all" ||
                    filterCondition !== "all"
                      ? "جرب تغيير معايير البحث أو الفلاتر"
                      : "لم يتم تسليمك أي أصول أو معدات من الشركة حتى الآن"}
                  </p>
                </div>
              </CardContent>
            </Card>
          ) : (
            <>
              <div className="flex items-center justify-between mb-4">
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  عرض {filteredAssets.length} من {myCustody.length} أصل
                </p>
              </div>
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredAssets.map((asset: any, index: number) => (
                  <motion.div
                    key={asset.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                    className="group"
                  >
                    <Card className="h-full hover:shadow-2xl transition-all duration-300 border-2 border-transparent hover:border-blue-200 dark:hover:border-blue-800 overflow-hidden">
                      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500" />
                      <CardContent className="p-6">
                        <div className="flex items-start justify-between mb-4">
                          <div className="p-3 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl shadow-lg group-hover:scale-110 transition-transform">
                            <ComputerDesktopIcon className="w-7 h-7 text-white" />
                          </div>
                          <Badge className="bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300 border-0">
                            مُسلّم
                          </Badge>
                        </div>

                        <h4 className="font-bold text-xl mb-4 text-gray-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                          {asset.name}
                        </h4>

                        <div className="space-y-3">
                          <div className="flex items-center justify-between p-2 bg-gray-50 dark:bg-gray-800/50 rounded-lg">
                            <span className="text-sm text-gray-600 dark:text-gray-400 flex items-center gap-2">
                              <TagIcon className="w-4 h-4" />
                              الكود
                            </span>
                            <span className="font-semibold text-gray-900 dark:text-white">
                              {asset.code}
                            </span>
                          </div>

                          <div className="flex items-center justify-between p-2 bg-gray-50 dark:bg-gray-800/50 rounded-lg">
                            <span className="text-sm text-gray-600 dark:text-gray-400 flex items-center gap-2">
                              <CubeIcon className="w-4 h-4" />
                              التصنيف
                            </span>
                            <span className="font-semibold text-gray-900 dark:text-white">
                              {asset.category?.name || "-"}
                            </span>
                          </div>

                          <div className="flex items-center justify-between p-2 bg-gray-50 dark:bg-gray-800/50 rounded-lg">
                            <span className="text-sm text-gray-600 dark:text-gray-400">
                              الرقم التسلسلي
                            </span>
                            <span className="font-mono text-xs font-semibold text-gray-900 dark:text-white">
                              {asset.serialNumber || "-"}
                            </span>
                          </div>

                          <div className="flex items-center justify-between p-2 bg-gray-50 dark:bg-gray-800/50 rounded-lg">
                            <span className="text-sm text-gray-600 dark:text-gray-400">
                              الحالة
                            </span>
                            <Badge
                              className={`${
                                asset.condition === "NEW"
                                  ? "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300"
                                  : asset.condition === "GOOD"
                                    ? "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300"
                                    : asset.condition === "FAIR"
                                      ? "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300"
                                      : "bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300"
                              } border-0 font-semibold`}
                            >
                              {asset.condition === "NEW"
                                ? "✨ جديد"
                                : asset.condition === "GOOD"
                                  ? "✓ جيد"
                                  : asset.condition === "FAIR"
                                    ? "⚠ مقبول"
                                    : "🔧 يحتاج صيانة"}
                            </Badge>
                          </div>

                          {asset.assignedDate && (
                            <div className="flex items-center justify-between pt-3 mt-3 border-t-2 border-gray-200 dark:border-gray-700">
                              <span className="text-sm text-gray-600 dark:text-gray-400 flex items-center gap-2">
                                <CalendarIcon className="w-4 h-4" />
                                تاريخ الاستلام
                              </span>
                              <span className="font-semibold text-blue-600 dark:text-blue-400">
                                {formatDate(asset.assignedDate)}
                              </span>
                            </div>
                          )}
                        </div>
                      </CardContent>
                    </Card>
                  </motion.div>
                ))}
              </div>
            </>
          )}
        </motion.div>

        {/* My Requests Section */}
        <motion.div
           initial={{ opacity: 0, y: 20 }}
           animate={{ opacity: 1, y: 0 }}
           transition={{ delay: 0.4 }}
           className="mt-12 mb-8"
        >
          <div className="flex items-center gap-3 mb-6">
             <div className="p-2 bg-gradient-to-br from-indigo-500 to-indigo-600 rounded-xl shadow-lg">
               <ClipboardDocumentListIcon className="w-6 h-6 text-white" />
             </div>
             <h2 className="text-2xl font-bold text-gray-900 dark:text-white">طلبات العهدة السابقة</h2>
          </div>

          <Card className="border-0 shadow-lg dark:bg-gray-800">
             <CardContent className="p-0 overflow-x-auto">
               <table className="w-full text-right min-w-[700px]">
                 <thead>
                   <tr className="bg-gray-50 dark:bg-gray-900/50 text-gray-500 dark:text-gray-400 text-sm font-semibold border-b border-gray-100 dark:border-gray-700">
                     <th className="px-6 py-4">تاريخ الطلب</th>
                     <th className="px-6 py-4">النوع</th>
                     <th className="px-6 py-4">الحالة</th>
                     <th className="px-6 py-4">سبب الطلب</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                   {myRequests.length === 0 ? (
                     <tr>
                       <td colSpan={4} className="px-6 py-8 text-center text-gray-500 dark:text-gray-400">
                         لم تقم بتقديم أي طلبات عهدة بعد.
                       </td>
                     </tr>
                   ) : (
                     myRequests.map((req: any) => (
                       <tr key={req.id} className="hover:bg-gray-50/50 dark:hover:bg-gray-700/50 transition-colors">
                         <td className="px-6 py-4 text-sm font-medium text-gray-900 dark:text-gray-300">
                           {formatDate(req.createdAt)}
                         </td>
                         <td className="px-6 py-4">
                           <div className="flex items-center gap-2">
                             <ComputerDesktopIcon className="w-4 h-4 text-blue-500" />
                             <span className="font-semibold text-gray-900 dark:text-white">{req.assetType}</span>
                           </div>
                         </td>
                         <td className="px-6 py-4">
                            {req.status === 'PENDING' && (
                              <Badge className="bg-amber-100 text-amber-700 hover:bg-amber-200 border-0 flex w-max items-center gap-1.5 px-3 py-1">
                                <ClockIcon className="w-4 h-4" />
                                قيد الانتظار
                              </Badge>
                            )}
                            {req.status === 'APPROVED' && (
                              <Badge className="bg-blue-100 text-blue-700 hover:bg-blue-200 border-0 flex w-max items-center gap-1.5 px-3 py-1">
                                <CheckCircleIcon className="w-4 h-4" />
                                تمت الموافقة
                              </Badge>
                            )}
                            {req.status === 'FULFILLED' && (
                              <Badge className="bg-green-100 text-green-700 hover:bg-green-200 border-0 flex w-max items-center gap-1.5 px-3 py-1">
                                <CheckCircleIcon className="w-4 h-4" />
                                تم التسليم
                              </Badge>
                            )}
                            {req.status === 'REJECTED' && (
                              <Badge className="bg-red-100 text-red-700 hover:bg-red-200 border-0 flex w-max items-center gap-1.5 px-3 py-1">
                                <XCircleIcon className="w-4 h-4" />
                                مرفوض
                              </Badge>
                            )}
                            {req.status === 'CANCELLED' && (
                              <Badge className="bg-gray-100 text-gray-700 hover:bg-gray-200 border-0 flex w-max items-center gap-1.5 px-3 py-1">
                                <XCircleIcon className="w-4 h-4" />
                                ملغى
                              </Badge>
                            )}
                         </td>
                         <td className="px-6 py-4 text-sm text-gray-600 dark:text-gray-400">
                           <p className="truncate max-w-xs" title={req.reason}>{req.reason}</p>
                           {req.rejectionReason && (
                             <p className="text-xs text-red-500 mt-1">سبب الرفض: {req.rejectionReason}</p>
                           )}
                         </td>
                       </tr>
                     ))
                   )}
                 </tbody>
               </table>
             </CardContent>
          </Card>
        </motion.div>

        {/* Request Modal */}
        {showRequestModal && (
          <div
            className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
            onClick={() => setShowRequestModal(false)}
          >
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto"
            >
              <div className="sticky top-0 bg-gradient-to-r from-blue-600 to-purple-600 p-6 rounded-t-2xl">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-white/20 rounded-lg">
                      <ClipboardDocumentListIcon className="w-6 h-6 text-white" />
                    </div>
                    <h2 className="text-2xl font-bold text-white">
                      طلب عهدة جديدة
                    </h2>
                  </div>
                  <button
                    onClick={() => setShowRequestModal(false)}
                    className="p-2 hover:bg-white/20 rounded-lg transition-colors"
                  >
                    <svg
                      className="w-6 h-6 text-white"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M6 18L18 6M6 6l12 12"
                      />
                    </svg>
                  </button>
                </div>
              </div>

              <div className="p-6 space-y-6">
                {/* Asset Type */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                    نوع العهدة المطلوبة <span className="text-red-500">*</span>
                  </label>
                  <select
                    value={requestForm.assetType}
                    onChange={(e) =>
                      setRequestForm({
                        ...requestForm,
                        assetType: e.target.value,
                      })
                    }
                    className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  >
                    <option value="">اختر نوع العهدة</option>
                    <option value="laptop">جهاز حاسوب محمول (Laptop)</option>
                    <option value="desktop">جهاز حاسوب مكتبي (Desktop)</option>
                    <option value="phone">هاتف محمول</option>
                    <option value="tablet">جهاز لوحي (Tablet)</option>
                    <option value="monitor">شاشة عرض</option>
                    <option value="keyboard">لوحة مفاتيح</option>
                    <option value="mouse">فأرة</option>
                    <option value="headset">سماعة رأس</option>
                    <option value="printer">طابعة</option>
                    <option value="other">أخرى</option>
                  </select>
                </div>

                {/* Category */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                    الفئة
                  </label>
                  <input
                    type="text"
                    value={requestForm.category}
                    onChange={(e) =>
                      setRequestForm({
                        ...requestForm,
                        category: e.target.value,
                      })
                    }
                    placeholder="مثال: أجهزة تقنية، أثاث مكتبي، إلخ"
                    className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>

                {/* Reason */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                    سبب الطلب <span className="text-red-500">*</span>
                  </label>
                  <textarea
                    value={requestForm.reason}
                    onChange={(e) =>
                      setRequestForm({ ...requestForm, reason: e.target.value })
                    }
                    placeholder="اشرح سبب حاجتك لهذه العهدة..."
                    rows={4}
                    className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-900 dark:text-white resize-none"
                  />
                </div>

                {/* Urgency */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                    مستوى الأولوية
                  </label>
                  <div className="grid grid-cols-3 gap-3">
                    <button
                      type="button"
                      onClick={() =>
                        setRequestForm({ ...requestForm, urgency: "low" })
                      }
                      className={`px-4 py-3 rounded-lg font-medium transition-all ${
                        requestForm.urgency === "low"
                          ? "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300 ring-2 ring-green-500"
                          : "bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600"
                      }`}
                    >
                      🟢 عادي
                    </button>
                    <button
                      type="button"
                      onClick={() =>
                        setRequestForm({ ...requestForm, urgency: "normal" })
                      }
                      className={`px-4 py-3 rounded-lg font-medium transition-all ${
                        requestForm.urgency === "normal"
                          ? "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300 ring-2 ring-yellow-500"
                          : "bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600"
                      }`}
                    >
                      🟡 متوسط
                    </button>
                    <button
                      type="button"
                      onClick={() =>
                        setRequestForm({ ...requestForm, urgency: "high" })
                      }
                      className={`px-4 py-3 rounded-lg font-medium transition-all ${
                        requestForm.urgency === "high"
                          ? "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300 ring-2 ring-red-500"
                          : "bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600"
                      }`}
                    >
                      🔴 عاجل
                    </button>
                  </div>
                </div>

                {/* Notes */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                    ملاحظات إضافية
                  </label>
                  <textarea
                    value={requestForm.notes}
                    onChange={(e) =>
                      setRequestForm({ ...requestForm, notes: e.target.value })
                    }
                    placeholder="أي ملاحظات أو متطلبات خاصة..."
                    rows={3}
                    className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-900 dark:text-white resize-none"
                  />
                </div>

                {/* Info Box */}
                <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                  <div className="flex items-start gap-3">
                    <svg
                      className="w-5 h-5 text-blue-600 dark:text-blue-400 mt-0.5"
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path
                        fillRule="evenodd"
                        d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                        clipRule="evenodd"
                      />
                    </svg>
                    <div className="text-sm text-blue-700 dark:text-blue-300">
                      <p className="font-semibold mb-1">📝 ملاحظة</p>
                      <p>
                        سيتم إرسال طلبك إلى قسم الموارد البشرية للمراجعة. ستتلقى
                        إشعاراً عند الموافقة أو الرفض.
                      </p>
                    </div>
                  </div>
                </div>

                {/* Action Buttons */}
                <div className="flex gap-3 pt-4">
                  <button
                    onClick={handleSubmitRequest}
                    className="flex-1 px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:from-blue-700 hover:to-purple-700 transition-all shadow-lg hover:shadow-xl font-semibold"
                  >
                    إرسال الطلب
                  </button>
                  <button
                    onClick={() => setShowRequestModal(false)}
                    className="px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-xl hover:bg-gray-300 dark:hover:bg-gray-600 transition-all font-semibold"
                  >
                    إلغاء
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </div>
    </div>
  );
};

export default MyCustody;

import React, { useState, useEffect } from "react";
import { useCurrency } from "../../hooks/useCurrency";
import { useDateFormat } from "../../hooks/useDateFormat";
import { buildApiUrl } from "../../utils/urlHelper";
import {
  ChartBarIcon,
  PlusIcon,
  EyeIcon,
  PencilIcon,
  TrashIcon,
  FunnelIcon,
  CurrencyDollarIcon,
} from "@heroicons/react/24/outline";

interface Opportunity {
  id: string;
  title: string;
  customerId: string;
  customerName: string;
  value: number;
  currency: string;
  stage: string;
  probability: number;
  expectedCloseDate: string;
  source: string;
  assignedTo: string;
  assignedToName: string;
  description: string;
  products: Array<{
    id: string;
    name: string;
    quantity: number;
    price: number;
  }>;
  activities: Array<{
    id: string;
    type: string;
    description: string;
    date: string;
    userId: string;
  }>;
  tags: string[];
  createdAt: string;
  updatedAt: string;
}

interface PipelineStats {
  stages: Record<
    string,
    {
      count: number;
      value: number;
      opportunities: Opportunity[];
    }
  >;
  totals: {
    count: number;
    value: number;
    weightedValue: number;
    averageValue: number;
  };
}

const Opportunities: React.FC = () => {
  const [opportunities, setOpportunities] = useState<Opportunity[]>([]);
  const { formatPrice } = useCurrency();
  const { formatDate } = useDateFormat();
  const [pipelineStats, setPipelineStats] = useState<PipelineStats | null>(
    null,
  );
  const [loading, setLoading] = useState(true);
  const [selectedOpportunity, setSelectedOpportunity] =
    useState<Opportunity | null>(null);
  const [showOpportunityModal, setShowOpportunityModal] = useState(false);
  const [filters, setFilters] = useState({
    stage: "",
    source: "",
    assignedTo: "",
  });

  const stages = {
    LEAD: { name: "عميل محتمل", color: "bg-gray-100 text-gray-800" },
    QUALIFIED: { name: "مؤهل", color: "bg-blue-100 text-blue-800" },
    PROPOSAL: { name: "عرض سعر", color: "bg-yellow-100 text-yellow-800" },
    NEGOTIATION: { name: "تفاوض", color: "bg-orange-100 text-orange-800" },
    CLOSED_WON: { name: "مغلق - فوز", color: "bg-green-100 text-green-800" },
    CLOSED_LOST: { name: "مغلق - خسارة", color: "bg-red-100 text-red-800" },
  };

  useEffect(() => {
    fetchOpportunities();
    fetchPipelineStats();
  }, [filters]);

  const fetchOpportunities = async () => {
    try {
      setLoading(true);
      const queryParams = new URLSearchParams();

      if (filters.stage) queryParams.append("stage", filters.stage);
      if (filters.source) queryParams.append("source", filters.source);
      if (filters.assignedTo)
        queryParams.append("assignedTo", filters.assignedTo);

      const response = await fetch(buildApiUrl(`opportunities?${queryParams}`));
      const data = await response.json();

      if (data.success) {
        setOpportunities(data.data);
      }
    } catch (error) {
      console.error("Error fetching opportunities:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchPipelineStats = async () => {
    try {
      const response = await fetch(buildApiUrl("opportunities/stats/pipeline"));
      const data = await response.json();

      if (data.success) {
        setPipelineStats(data.data);
      }
    } catch (error) {
      console.error("Error fetching pipeline stats:", error);
    }
  };

  const updateOpportunityStage = async (
    opportunityId: string,
    newStage: string,
  ) => {
    try {
      const response = await fetch(
        buildApiUrl(`opportunities/${opportunityId}`),
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ stage: newStage }),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchOpportunities();
        fetchPipelineStats();
        alert("تم تحديث مرحلة الفرصة بنجاح");
      }
    } catch (error) {
      console.error("Error updating opportunity stage:", error);
      alert("فشل في تحديث مرحلة الفرصة");
    }
  };

  const getSourceIcon = (source: string) => {
    switch (source) {
      case "facebook":
        return "📘";
      case "whatsapp":
        return "💬";
      case "website":
        return "🌐";
      case "referral":
