                  <div>
                    <h4 className="font-medium text-gray-900 mb-2">الأنشطة</h4>
                    <div className="bg-gray-50 p-3 rounded max-h-40 overflow-y-auto">
                      {selectedOpportunity.activities.map((activity, index) => (
                        <div
                          key={index}
