                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Opportunities;

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { apiClient } from '../../services/apiClient';
import { useCurrency } from '../../hooks/useCurrency';
import { summarizeOrderDocumentItems } from '../../utils/orderDocumentQuantityOffers';
import {
  PhoneIcon,
  CalendarIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  ExclamationTriangleIcon,
  ChevronRightIcon,
  UserIcon,
  MapPinIcon,
  CurrencyDollarIcon,
  ArrowPathIcon,
  FunnelIcon,
} from '@heroicons/react/24/outline';
import toast from 'react-hot-toast';
import EnhancedOrderModal from '../../components/orders/EnhancedOrderModal';

type OrderType = 'GUEST' | 'REGULAR';
type FilterTab = 'all' | 'pending' | 'confirmed' | 'followup';
type OrderAction = 'log-call' | 'confirm' | 'cancel' | 'details';

interface Order {
  id: string;
  orderNumber: string;
  customerName: string;
  customerPhone: string;
  city: string;
  governorate: string;
  total: number;
  status: string;
  callAttempts: number;
  lastCallAt: string | null;
  followUpDate: string | null;
  createdAt: string;
  items: any[];
  type?: OrderType;
}

interface ApiErrorShape {
  response?: {
    data?: {
      message?: string;
      error?: string | { message?: string };
    };
  };
  message?: string;
}

const STATUS_COLORS: Record<string, string> = {
  PENDING: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400',
  CONFIRMED: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400',
  PROCESSING: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400',
  CANCELLED: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400',
  SHIPPED: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400',
  DELIVERED: 'bg-teal-100 text-teal-800 dark:bg-teal-900/30 dark:text-teal-400',
};

function getNormalizedStatus(status: string | null | undefined): string {
  return String(status || 'PENDING').toUpperCase();
}

function extractApiErrorMessage(error: unknown): string | null {
  const apiError = error as ApiErrorShape;
  const responseError = apiError.response?.data?.error;

  if (typeof responseError === 'string' && responseError.trim()) {
    return responseError;
  }

  if (
    typeof responseError === 'object' &&
    responseError !== null &&
    typeof responseError.message === 'string' &&
    responseError.message.trim()
  ) {
    return responseError.message;
  }

  if (
    typeof apiError.response?.data?.message === 'string' &&
    apiError.response.data.message.trim()
  ) {
    return apiError.response.data.message;
  }

  if (typeof apiError.message === 'string' && apiError.message.trim()) {
    return apiError.message;
  }

  return null;
}

function getHoursSince(dateStr: string | null): number {
  if (!dateStr) return Infinity;
  return (Date.now() - new Date(dateStr).getTime()) / (1000 * 60 * 60);
}

function isOverdue(order: Order): boolean {
  const normalizedStatus = getNormalizedStatus(order.status);

  if (normalizedStatus !== 'PENDING') {
    return false;
  }

  // Alert if no call made and order is older than 24h
  if (order.callAttempts === 0 && getHoursSince(order.createdAt) > 24) return true;
  // Alert if last call was more than 12h ago and order is still pending
  if (getHoursSince(order.lastCallAt) > 12) return true;
  return false;
}

const AgentWorkspace: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { formatPrice } = useCurrency();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [selectedOrder, setSelectedOrder] = useState<any>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<FilterTab>('all');
  const [busyOrders, setBusyOrders] = useState<Record<string, OrderAction>>({});
  const activeTabHydratedRef = useRef(false);

  const isArabic = i18n.language.toLowerCase().startsWith('ar');
  const locale = isArabic ? 'ar-EG' : 'en-US';

  const resolveCopy = (key: string, fallbackAr: string, fallbackEn: string) => {
    const translated = t(key);
    if (translated !== key) {
      return translated;
    }

    return isArabic ? fallbackAr : fallbackEn;
  };

  const formatDate = (dateStr: string) =>
    new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }).format(
      new Date(dateStr),
    );

  const formatTime = (dateStr: string) =>
    new Intl.DateTimeFormat(locale, {
      hour: '2-digit',
      minute: '2-digit',
    }).format(new Date(dateStr));

  const setOrderBusyState = (orderId: string, action: OrderAction | null) => {
    setBusyOrders((current) => {
      const next = { ...current };
      if (action) {
        next[orderId] = action;
      } else {
        delete next[orderId];
      }
      return next;
    });
  };

  const fetchOrders = async (silent = false) => {
    try {
      if (!silent) {
        setLoading(true);
      } else {
        setRefreshing(true);
      }

      const params: Record<string, string | number | boolean> = {};

      if (activeTab === 'pending') {
        params.status = 'PENDING';
      } else if (activeTab === 'confirmed') {
        params.status = 'CONFIRMED';
      } else if (activeTab === 'followup') {
        params.followUpOnly = true;
      }

      const response = await apiClient.get('/agent-workspace/my-orders', { params });
      if (!response.data?.success) {
        throw new Error(
          (typeof response.data?.error === 'string' && response.data.error) ||
            response.data?.message ||
            resolveCopy(
              'orders.loadingFailed',
              'تعذر تحميل الطلبات الآن. حاول مرة أخرى.',
              'Could not load orders right now. Please try again.',
            ),
        );
      }

      const nextOrders = Array.isArray(response.data?.data)
        ? response.data.data
        : [];

      setOrders(nextOrders);
      setFetchError(null);
    } catch (error) {
      console.error('Failed to fetch orders:', error);
      const message =
        extractApiErrorMessage(error) ||
        resolveCopy(
          'orders.loadingFailed',
          'تعذر تحميل الطلبات الآن. حاول مرة أخرى.',
          'Could not load orders right now. Please try again.',
        );

      if (!silent) {
        setFetchError(message);
        toast.error(message);
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    void fetchOrders();
    // Auto-refresh every 60 seconds
    const interval = setInterval(() => {
      void fetchOrders(true);
    }, 60000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!activeTabHydratedRef.current) {
      activeTabHydratedRef.current = true;
      return;
    }

    void fetchOrders(true);
  }, [activeTab]);

  const handleLogCall = async (order: Order) => {
    setOrderBusyState(order.id, 'log-call');

    try {
      const response = await apiClient.post(
        `/agent-workspace/orders/${order.id}/log-call`,
        {
          result: 'unreached',
          notes: resolveCopy(
            'orders.callAttemptNote',
            'محاولة اتصال من مساحة العمل',
            'Call attempt from workspace',
          ),
          type: order.type || 'REGULAR',
        },
      );

      if (response.data?.success) {
        toast.success(
          resolveCopy(
            'orders.callLogged',
            'تم تسجيل المكالمة بنجاح',
            'Call logged successfully',
          ),
        );
        await fetchOrders(true);
      }
    } catch (error) {
      toast.error(
        extractApiErrorMessage(error) ||
          resolveCopy(
            'orders.logCallFailed',
            'فشل تسجيل المكالمة',
            'Failed to log the call',
          ),
      );
    } finally {
      setOrderBusyState(order.id, null);
    }
  };

  const handleQuickAction = async (
    order: Order,
    action: Extract<OrderAction, 'confirm' | 'cancel'>,
  ) => {
    setOrderBusyState(order.id, action);

    try {
      const response = await apiClient.post(
        `/agent-workspace/orders/${order.id}/quick-action`,
        {
          action,
          type: order.type || 'REGULAR',
          notes:
            action === 'confirm'
              ? resolveCopy(
                  'orders.confirmNote',
                  'تم التأكيد من مساحة العمل',
                  'Confirmed from workspace',
                )
              : resolveCopy(
                  'orders.cancelNote',
                  'تم الإلغاء من مساحة العمل',
                  'Cancelled from workspace',
                ),
        },
      );

      if (response.data?.success) {
        const messages: Record<string, string> = {
          confirm: resolveCopy(
            'orders.orderConfirmed',
            'تم تأكيد الطلب بنجاح',
            'Order confirmed successfully',
          ),
          cancel: resolveCopy(
            'orders.orderCancelled',
            'تم إلغاء الطلب',
            'Order cancelled successfully',
          ),
        };
        toast.success(
          messages[action] ||
            resolveCopy(
              'orders.actionSuccess',
              'تم تنفيذ الإجراء بنجاح',
              'Action completed successfully',
            ),
        );
        await fetchOrders(true);
      }
    } catch (error) {
      toast.error(
        extractApiErrorMessage(error) ||
          resolveCopy(
            'orders.actionFailed',
            'فشل تنفيذ الإجراء',
            'Failed to complete the action',
          ),
      );
    } finally {
      setOrderBusyState(order.id, null);
    }
  };

  const normalizeItems = (rawItems: any): any[] => {
    if (!rawItems) return [];
    let items = rawItems;
    if (typeof items === "string") {
      try {
        items = JSON.parse(items);
      } catch {
        return [];
      }
    }
    if (!Array.isArray(items)) return [];

    return items.map((item: any) => {
      const price = parseFloat(item.price ?? item.unitPrice ?? 0);
      const quantity = parseInt(item.quantity ?? 1);
      const safePrice = Number.isFinite(price) ? price : 0;
      const safeQuantity =
        Number.isFinite(quantity) && quantity > 0 ? quantity : 1;
      return {
        ...item,
        productName:
          item.productName ||
          item.name ||
          item.product?.name ||
          "منتج غير محدد",
        name:
          item.name ||
          item.productName ||
          item.product?.name ||
          "منتج غير محدد",
        price: safePrice,
        quantity: safeQuantity,
        total:
          Number.isFinite(parseFloat(item.total))
            ? parseFloat(item.total)
            : safePrice * safeQuantity,
        productColor:
          item.productColor ||
          item.color ||
          item.metadata?.color ||
          item.metadata?.productColor,
        productSize:
          item.productSize ||
          item.size ||
          item.metadata?.size ||
          item.metadata?.productSize,
      };
    });
  };

  const openOrderDetails = async (order: Order) => {
    const orderKey = order.orderNumber || (order as any)?.id;
    const encodedKey = orderKey ? encodeURIComponent(String(orderKey)) : "";

    setOrderBusyState(order.id, 'details');

    try {
      // Fetch the full order so the modal gets items + subtotal + shipping
      const response = await apiClient.get(`/orders-new/simple/${encodedKey}`, {
        _skipErrorToast: true,
      });
      if (response.data.success && response.data.data) {
        const fetched = response.data.data;
        const fetchedItems = normalizeItems(fetched.items);
        const workspaceItems = normalizeItems(order.items);
        let merged = {
          ...order,
          ...fetched,
          items: fetchedItems.length > 0 ? fetchedItems : workspaceItems,
        };

        // If still no items, try enhanced endpoint as a fallback
        if (!merged.items || merged.items.length === 0) {
          try {
            const enhanced = await apiClient.get(
              `/orders-enhanced/${encodedKey}`,
              { _skipErrorToast: true },
            );
            if (enhanced.data?.success && enhanced.data?.data) {
              const enhancedData = enhanced.data.data;
              const enhancedItems = normalizeItems(
                enhancedData.items || enhancedData.orderItems,
              );
              merged = {
                ...merged,
                ...enhancedData,
                items: enhancedItems.length > 0 ? enhancedItems : merged.items,
              };
            }
          } catch {
            // ignore enhanced fallback errors
          }
        }

        setOrders((current) =>
          current.map((existingOrder) => {
            if (existingOrder.id !== order.id) {
              return existingOrder;
            }

            return {
              ...existingOrder,
              customerName: merged.customerName || existingOrder.customerName,
              customerPhone:
                merged.customerPhone || existingOrder.customerPhone,
              governorate:
                merged.governorate ||
                (typeof merged.shippingAddress === 'object'
                  ? merged.shippingAddress?.governorate
                  : '') ||
                existingOrder.governorate,
              city:
                merged.city ||
                (typeof merged.shippingAddress === 'object'
                  ? merged.shippingAddress?.city
                  : '') ||
                existingOrder.city,
              total:
                Number.isFinite(parseFloat(merged.total))
                  ? parseFloat(merged.total)
                  : existingOrder.total,
              status: merged.status || existingOrder.status,
              items:
                Array.isArray(merged.items) && merged.items.length > 0
                  ? merged.items
                  : existingOrder.items,
            };
          }),
        );

        setSelectedOrder(merged);
      } else {
        // Fallback: use workspace data with what we have
        setSelectedOrder({ ...order, items: normalizeItems(order.items) });
      }
    } catch {
      // Fallback if endpoint errors
      setSelectedOrder({ ...order, items: normalizeItems(order.items) });
    } finally {
      setOrderBusyState(order.id, null);
    }
    setIsModalOpen(true);
  };

  // ─── Computed Stats ──────────────────────────────────────────────────────
  const stats = useMemo(() => ({
    total: orders.length,
    pending: orders.filter(o => getNormalizedStatus(o.status) === 'PENDING').length,
    confirmed: orders.filter(o => getNormalizedStatus(o.status) === 'CONFIRMED').length,
    followup: orders.filter(o => !!o.followUpDate).length,
  }), [orders]);

  // ─── Filtered + Sorted Orders ────────────────────────────────────────────
  const filteredOrders = useMemo(() => {
    let list = [...orders];
    if (activeTab === 'pending') list = list.filter(o => getNormalizedStatus(o.status) === 'PENDING');
    else if (activeTab === 'confirmed') list = list.filter(o => getNormalizedStatus(o.status) === 'CONFIRMED');
    else if (activeTab === 'followup') list = list.filter(o => !!o.followUpDate);

    // Sort: overdue first → most call attempts → oldest
    list.sort((a, b) => {
      if (isOverdue(a) && !isOverdue(b)) return -1;
      if (!isOverdue(a) && isOverdue(b)) return 1;
      if (b.callAttempts !== a.callAttempts) return b.callAttempts - a.callAttempts;
      return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
    });
    return list;
  }, [orders, activeTab]);

  const tabs: { key: FilterTab; label: string; count: number }[] = [
    { key: 'all', label: 'الكل', count: stats.total },
    { key: 'pending', label: 'قيد الانتظار', count: stats.pending },
    { key: 'confirmed', label: 'مؤكدة', count: stats.confirmed },
    { key: 'followup', label: 'متابعة لاحقة', count: stats.followup },
  ];

  if (loading && orders.length === 0) {
    return (
      <div
        className="flex min-h-[400px] flex-col items-center justify-center gap-4"
        role="status"
        aria-live="polite"
      >
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          {resolveCopy(
            'orders.loadingWorkspace',
            'جارٍ تحميل مساحة العمل…',
            'Loading workspace…',
          )}
        </p>
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 max-w-7xl mx-auto">

      {/* ─── Header ─────────────────────────────────────────────────────── */}
      <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-1">
            {t('orders.workspaceTitle')}
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            {t('orders.workspaceSubtitle')}
          </p>
        </div>
        <button
          type="button"
          onClick={() => void fetchOrders(true)}
          disabled={refreshing}
          aria-busy={refreshing}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-gray-600 dark:text-gray-300 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors disabled:opacity-50"
        >
          <ArrowPathIcon className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
          {refreshing
            ? resolveCopy('orders.refreshing', 'جارٍ التحديث…', 'Refreshing…')
            : resolveCopy('common.refresh', 'تحديث', 'Refresh')}
        </button>
      </div>

      {fetchError && orders.length > 0 && (
        <div
          className="mb-6 flex flex-col gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-100 sm:flex-row sm:items-center sm:justify-between"
          role="alert"
        >
          <span>{fetchError}</span>
          <button
            type="button"
            onClick={() => void fetchOrders()}
            className="w-fit rounded-lg border border-amber-300 px-3 py-1.5 font-semibold text-amber-900 transition-colors hover:bg-amber-100 dark:border-amber-800 dark:text-amber-100 dark:hover:bg-amber-900/30"
          >
            {resolveCopy(
              'orders.retryLoading',
              'إعادة المحاولة',
              'Try again',
            )}
          </button>
        </div>
      )}

      {/* ─── Summary Stats Bar ───────────────────────────────────────────── */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-100 dark:border-gray-700 flex items-center gap-3">
          <div className="w-9 h-9 rounded-full bg-gray-100 dark:bg-gray-700 flex items-center justify-center">
            <FunnelIcon className="w-5 h-5 text-gray-500" />
          </div>
          <div>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.total}</p>
            <p className="text-xs text-gray-500">إجمالي الطلبات</p>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-yellow-100 dark:border-yellow-900/30 flex items-center gap-3">
          <div className="w-9 h-9 rounded-full bg-yellow-50 dark:bg-yellow-900/20 flex items-center justify-center">
            <ClockIcon className="w-5 h-5 text-yellow-600" />
          </div>
          <div>
            <p className="text-2xl font-bold text-yellow-700 dark:text-yellow-400">{stats.pending}</p>
            <p className="text-xs text-gray-500">قيد الانتظار</p>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-green-100 dark:border-green-900/30 flex items-center gap-3">
          <div className="w-9 h-9 rounded-full bg-green-50 dark:bg-green-900/20 flex items-center justify-center">
            <CheckCircleIcon className="w-5 h-5 text-green-600" />
          </div>
          <div>
            <p className="text-2xl font-bold text-green-700 dark:text-green-400">{stats.confirmed}</p>
            <p className="text-xs text-gray-500">مؤكدة</p>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-blue-100 dark:border-blue-900/30 flex items-center gap-3">
          <div className="w-9 h-9 rounded-full bg-blue-50 dark:bg-blue-900/20 flex items-center justify-center">
            <CalendarIcon className="w-5 h-5 text-blue-600" />
          </div>
          <div>
            <p className="text-2xl font-bold text-blue-700 dark:text-blue-400">{stats.followup}</p>
            <p className="text-xs text-gray-500">متابعة لاحقة</p>
          </div>
        </div>
      </div>

      {/* ─── Filter Tabs ─────────────────────────────────────────────────── */}
      <div
        className="mb-6 flex w-full items-center gap-1 overflow-x-auto rounded-xl bg-gray-100 p-1 dark:bg-gray-800 sm:w-fit"
        role="tablist"
        aria-label={resolveCopy(
          'orders.workspaceFilters',
          'فلاتر مساحة العمل',
          'Workspace filters',
        )}
      >
        {tabs.map(tab => (
          <button
            key={tab.key}
            type="button"
            onClick={() => setActiveTab(tab.key)}
            role="tab"
            aria-selected={activeTab === tab.key}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              activeTab === tab.key
                ? 'bg-white dark:bg-gray-700 shadow-sm text-gray-900 dark:text-white'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
            } whitespace-nowrap`}
          >
            {tab.label}
            <span className={`text-xs px-1.5 py-0.5 rounded-full font-bold ${
              activeTab === tab.key ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' : 'bg-gray-200 dark:bg-gray-600 text-gray-600 dark:text-gray-300'
            }`}>
              {tab.count}
            </span>
          </button>
        ))}
      </div>

      {/* ─── Orders Grid ─────────────────────────────────────────────────── */}
      {filteredOrders.length === 0 ? (
        <div
          className="bg-white dark:bg-gray-800 rounded-xl p-8 sm:p-12 text-center shadow-sm border border-gray-100 dark:border-gray-700"
          role={fetchError ? 'alert' : undefined}
        >
          <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 ${
            fetchError
              ? 'bg-red-50 dark:bg-red-900/20'
              : 'bg-gray-50 dark:bg-gray-700'
          }`}>
            {fetchError ? (
              <ExclamationTriangleIcon className="w-8 h-8 text-red-500 dark:text-red-300" />
            ) : (
              <CheckCircleIcon className="w-8 h-8 text-gray-400" />
            )}
          </div>
          <p className="text-gray-700 dark:text-gray-200 text-lg font-medium">
            {fetchError
              ? fetchError
              : activeTab === 'all'
                ? t('orders.noAssignedOrders')
                : resolveCopy(
                    'orders.noOrdersInFilter',
                    'لا توجد طلبات في هذه الفئة',
                    'No orders in this category',
                  )}
          </p>
          {fetchError && (
            <button
              type="button"
              onClick={() => void fetchOrders()}
              className="mt-5 inline-flex items-center justify-center rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-blue-700"
            >
              {resolveCopy(
                'orders.retryLoading',
                'إعادة المحاولة',
                'Try again',
              )}
            </button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredOrders.map((order) => {
            const overdue = isOverdue(order);
            const isHighAttempts = order.callAttempts >= 3;
            const currentAction = busyOrders[order.id];
            const isOrderBusy = Boolean(currentAction);
            const statusKey = getNormalizedStatus(order.status);
            const statusTranslationKey = `orders.${statusKey.toLowerCase()}`;
            const translatedStatus = t(statusTranslationKey);
            const statusLabel =
              translatedStatus === statusTranslationKey ? statusKey : translatedStatus;
            const location = [order.governorate, order.city].filter(Boolean).join('، ') || '—';
            const orderItemsSummary = summarizeOrderDocumentItems(order.items);

            return (
              <div
                key={order.id}
                className={`bg-white dark:bg-gray-800 rounded-xl shadow-sm border overflow-hidden hover:shadow-md transition-all ${
                  overdue
                    ? 'border-red-300 dark:border-red-700 ring-1 ring-red-200 dark:ring-red-800'
                    : 'border-gray-100 dark:border-gray-700'
                }`}
              >
                {/* Overdue Alert Banner */}
                {overdue && (
                  <div className="bg-red-50 dark:bg-red-900/20 border-b border-red-200 dark:border-red-800 px-4 py-2 flex items-center gap-2">
                    <ExclamationTriangleIcon className="w-4 h-4 text-red-600 dark:text-red-400 flex-shrink-0" />
                    <span className="text-xs font-bold text-red-700 dark:text-red-400">
                      يحتاج تواصل عاجل
                    </span>
                  </div>
                )}

                {/* Order Header */}
                <div className="p-4 border-b border-gray-50 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-800/50">
                  <span className="font-mono text-sm font-bold text-blue-600 dark:text-blue-400">
                    #{order.orderNumber}
                  </span>
                  <span className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${STATUS_COLORS[statusKey] || STATUS_COLORS.PENDING}`}>
                    {statusLabel}
                  </span>
                </div>

                {/* Order Content */}
                <div className="p-4 space-y-3">
                  {/* Customer */}
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-indigo-50 dark:bg-indigo-900/30 flex items-center justify-center flex-shrink-0">
                      <UserIcon className="w-4 h-4 text-indigo-500" />
                    </div>
                    <div className="min-w-0">
                      <p className="font-semibold text-gray-900 dark:text-white text-sm break-words">
                        {order.customerName || '—'}
                      </p>
                      <p className="text-sm text-gray-500 font-mono truncate" dir="ltr">
                        {order.customerPhone || '—'}
                      </p>
                    </div>
                  </div>

                  {/* Location */}
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-700 flex items-center justify-center flex-shrink-0">
                      <MapPinIcon className="w-4 h-4 text-gray-400" />
                    </div>
                    <p className="min-w-0 break-words text-sm text-gray-600 dark:text-gray-300">
                      {location}
                    </p>
                  </div>

                  {/* Price */}
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-green-50 dark:bg-green-900/20 flex items-center justify-center flex-shrink-0">
                      <CurrencyDollarIcon className="w-4 h-4 text-green-500" />
                    </div>
                    <p className="text-base font-bold text-green-700 dark:text-green-400">
                      {formatPrice(order.total)}
                    </p>
                  </div>

                  {orderItemsSummary.hasQuantityOffers ? (
                    <div className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 dark:border-amber-900/40 dark:bg-amber-900/20">
                      <div className="text-xs font-bold text-amber-800 dark:text-amber-200">
                        عرض كميات
                      </div>
                      <div className="mt-1 text-sm font-semibold text-amber-900 dark:text-amber-100">
                        {orderItemsSummary.primaryLabel}
                      </div>
                      <div className="mt-1 text-xs text-amber-700 dark:text-amber-300">
                        {orderItemsSummary.secondaryLabel}
                      </div>
                    </div>
                  ) : null}

                  {/* Call Stats */}
                  <div className="grid grid-cols-2 gap-3 pt-2 border-t border-gray-50 dark:border-gray-700">
                    <div className="flex flex-col">
                      <span className="text-[10px] uppercase tracking-wider text-gray-400 font-bold">{t('orders.attempts')}</span>
                      <div className="flex items-center gap-1.5 mt-1">
                        <PhoneIcon className="w-4 h-4 text-gray-400" />
                        <span className={`text-sm font-bold ${isHighAttempts ? 'text-red-500' : 'text-gray-700 dark:text-gray-200'}`}>
                          {order.callAttempts} / 5
                        </span>
                      </div>
                    </div>
                    <div className="flex flex-col">
                      <span className="text-[10px] uppercase tracking-wider text-gray-400 font-bold">{t('orders.lastCall')}</span>
                      <div className="flex items-center gap-1.5 mt-1">
                        <ClockIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-xs text-gray-600 dark:text-gray-300">
                          {order.lastCallAt
                            ? formatTime(order.lastCallAt)
                            : resolveCopy(
                                'orders.noCallsYet',
                                'لا يوجد',
                                'No calls yet',
                              )}
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Follow-up Badge */}
                  {order.followUpDate && (
                    <div className="bg-blue-50 dark:bg-blue-900/20 px-3 py-2 rounded-lg flex items-center gap-2 border border-blue-100 dark:border-blue-800">
                      <CalendarIcon className="w-4 h-4 text-blue-600 dark:text-blue-400 flex-shrink-0" />
                      <span className="text-xs font-semibold text-blue-800 dark:text-blue-200">
                        {t('orders.followUp')}: {formatDate(order.followUpDate)}
                      </span>
                    </div>
                  )}
                </div>

                {/* Order Actions */}
                <div className="p-3 bg-gray-50 dark:bg-gray-800/80 border-t border-gray-100 dark:border-gray-700 space-y-2">
                  {/* Row 1: Log Call + Confirm */}
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      type="button"
                      onClick={() => void handleLogCall(order)}
                      disabled={isOrderBusy}
                      className="flex items-center justify-center gap-1.5 py-2 px-3 bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm font-semibold text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors disabled:cursor-not-allowed disabled:opacity-60"
                    >
                      <PhoneIcon className={`w-4 h-4 ${currentAction === 'log-call' ? 'animate-pulse' : ''}`} />
                      {currentAction === 'log-call'
                        ? resolveCopy(
                            'orders.loggingCall',
                            'جارٍ التسجيل…',
                            'Logging…',
                          )
                        : t('orders.logCall')}
                    </button>
                    <button
                      type="button"
                      onClick={() => void handleQuickAction(order, 'confirm')}
                      disabled={statusKey === 'CONFIRMED' || isOrderBusy}
                      className="flex items-center justify-center gap-1.5 py-2 px-3 bg-green-600 hover:bg-green-700 disabled:bg-green-200 dark:disabled:bg-green-900/30 disabled:cursor-not-allowed rounded-lg text-sm font-bold text-white transition-colors"
                    >
                      <CheckCircleIcon className={`w-4 h-4 ${currentAction === 'confirm' ? 'animate-pulse' : ''}`} />
                      {currentAction === 'confirm'
                        ? resolveCopy(
                            'orders.confirmingOrder',
                            'جارٍ التأكيد…',
                            'Confirming…',
                          )
                        : t('orders.confirmOrder')}
                    </button>
                  </div>

                  {/* Row 2: Cancel */}
                  <button
                    type="button"
                    onClick={() => void handleQuickAction(order, 'cancel')}
                    disabled={statusKey === 'CANCELLED' || isOrderBusy}
                    className="w-full flex items-center justify-center gap-1.5 py-1.5 px-3 border border-red-200 dark:border-red-800 rounded-lg text-xs font-semibold text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  >
                    <XCircleIcon className={`w-3.5 h-3.5 ${currentAction === 'cancel' ? 'animate-pulse' : ''}`} />
                    {currentAction === 'cancel'
                      ? resolveCopy(
                          'orders.cancellingOrder',
                          'جارٍ الإلغاء…',
                          'Cancelling…',
                        )
                      : t('orders.cancelOrder')}
                  </button>

                  {/* View Details Link */}
                  <button
                    type="button"
                    onClick={() => void openOrderDetails(order)}
                    disabled={isOrderBusy}
                    className="w-full flex items-center justify-center gap-1 text-xs text-blue-600 dark:text-blue-400 hover:underline font-medium pt-1"
                  >
                    {currentAction === 'details'
                      ? resolveCopy(
                          'orders.loadingDetails',
                          'جارٍ تحميل التفاصيل…',
                          'Loading details…',
                        )
                      : t('orders.viewDetails')}
                    <ChevronRightIcon className={`w-3 h-3 ${currentAction === 'details' ? 'animate-pulse' : ''}`} />
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {selectedOrder && (
        <EnhancedOrderModal
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          order={selectedOrder}
          onOrderUpdate={() => void fetchOrders(true)}
        />
      )}
    </div>
  );
};

