import React, { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  MagnifyingGlassIcon,
  ClipboardDocumentIcon,
  ArrowTopRightOnSquareIcon,
} from "@heroicons/react/24/outline";
import { Link } from "react-router-dom";
import toast from "react-hot-toast";
import { useCurrency } from "../../hooks/useCurrency";
import { useDateFormat } from "../../hooks/useDateFormat";
import { apiClient } from "../../services/apiClient";

interface IncompleteOrder {
  cartId: string;
  itemsCount: number;
  total: number;
  checkoutData?: Record<string, any>;
  checkoutStartedAt?: string;
  checkoutUpdatedAt?: string;
  updatedAt?: string;
  expiresAt?: string;
  status?: "lost" | "incomplete";
}

const IncompleteOrders: React.FC = () => {
  const { t } = useTranslation();
  const { formatPrice } = useCurrency();
  const { formatDate } = useDateFormat();

  const [orders, setOrders] = useState<IncompleteOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [limit] = useState(20);
  const [totalOrders, setTotalOrders] = useState(0);
  const [totalPages, setTotalPages] = useState(1);
  const [searchInput, setSearchInput] = useState("");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    const timeout = setTimeout(() => {
      setSearch(searchInput.trim());
      setPage(1);
    }, 400);

    return () => clearTimeout(timeout);
  }, [searchInput]);

  useEffect(() => {
    const fetchIncompleteOrders = async () => {
      try {
        setLoading(true);
        setError(null);

        const params: Record<string, string | number> = {
          page,
          limit,
        };

        if (search) params.search = search;
        if (statusFilter && statusFilter !== "all") params.status = statusFilter;

        const response = await apiClient.get("/orders-new/incomplete", { params });
        const data = response.data;

        if (data?.success) {
          setOrders(Array.isArray(data.data) ? data.data : []);
          setTotalOrders(data.pagination?.total || 0);
          setTotalPages(data.pagination?.pages || 1);
        } else {
          setOrders([]);
          setTotalOrders(0);
          setTotalPages(1);
        }
      } catch (err: any) {
        setError(err.response?.data?.message || t("orders.loadingOrders"));
      } finally {
        setLoading(false);
      }
    };

    fetchIncompleteOrders();
  }, [page, limit, search, statusFilter, t, refreshKey]);

  const getCustomerName = (order: IncompleteOrder) => {
    const data = order.checkoutData || {};
    return (
      data.guestName ||
      data.fullName ||
      data.customerName ||
      data.customerFullName ||
      data.name ||
      t("orders.notSpecified")
    );
  };

  const getCustomerContact = (order: IncompleteOrder) => {
    const data = order.checkoutData || {};
    const phone =
      data.guestPhone ||
      data.customerPhone ||
      data.phoneNumber ||
      data.mobileNumber ||
      data.phone ||
      data.mobile ||
      "";
    const email =
      data.guestEmail ||
      data.customerEmail ||
      data.emailAddress ||
      data.email ||
      "";
    return { phone, email };
  };

  const getLastUpdated = (order: IncompleteOrder) => {
    return order.checkoutUpdatedAt || order.updatedAt || order.checkoutStartedAt || "";
  };

  const getStatusLabel = (order: IncompleteOrder) => {
    return order.status === "lost"
      ? t("orders.incompleteStatusLost")
      : t("orders.incompleteStatusActive");
  };

  const getStatusClasses = (order: IncompleteOrder) => {
    return order.status === "lost"
      ? "bg-red-100 text-red-700"
      : "bg-amber-100 text-amber-700";
  };

  const handleCopyCartId = async (cartId: string) => {
    if (!cartId) return;
    try {
      if (navigator?.clipboard?.writeText) {
        await navigator.clipboard.writeText(cartId);
      } else {
        const tempInput = document.createElement("input");
        tempInput.value = cartId;
        document.body.appendChild(tempInput);
        tempInput.select();
        document.execCommand("copy");
        document.body.removeChild(tempInput);
      }
      toast.success(t("orders.incompleteCopied"));
    } catch (copyError) {
      toast.error(t("orders.incompleteCopyFailed"));
    }
  };

  const handleRetry = () => {
    setRefreshKey((prev) => prev + 1);
  };

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {t("orders.incompleteTitle")}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("orders.incompleteSubtitle")}
          </p>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <label htmlFor="incomplete-orders-search" className="sr-only">
              {t("orders.incompleteSearchLabel")}
            </label>
            <MagnifyingGlassIcon className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 -translate-y-1/2" />
            <input
              id="incomplete-orders-search"
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder={t("orders.incompleteSearchPlaceholder")}
              className="w-full pr-10 pl-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-sm"
            />
          </div>
          <label htmlFor="incomplete-orders-status" className="sr-only">
            {t("orders.incompleteStatusLabel")}
          </label>
          <select
            id="incomplete-orders-status"
            value={statusFilter}
            onChange={(e) => {
              setStatusFilter(e.target.value);
              setPage(1);
            }}
            className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-sm"
          >
            <option value="all">{t("orders.incompleteStatusAll")}</option>
            <option value="active">{t("orders.incompleteStatusActive")}</option>
            <option value="lost">{t("orders.incompleteStatusLost")}</option>
          </select>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[920px]">
            <thead className="bg-gray-50 dark:bg-gray-700/50">
              <tr>
                <th className="px-4 py-3 text-xs font-medium text-gray-500 dark:text-gray-300">
                  {t("orders.customer")}
                </th>
                <th className="px-4 py-3 text-xs font-medium text-gray-500 dark:text-gray-300">
                  {t("orders.contact")}
                </th>
                <th className="px-4 py-3 text-xs font-medium text-gray-500 dark:text-gray-300">
                  {t("orders.itemsCount")}
                </th>
                <th className="px-4 py-3 text-xs font-medium text-gray-500 dark:text-gray-300">
                  {t("orders.amount")}
                </th>
                <th className="px-4 py-3 text-xs font-medium text-gray-500 dark:text-gray-300">
                  {t("orders.lastUpdated")}
                </th>
                <th className="px-4 py-3 text-xs font-medium text-gray-500 dark:text-gray-300">
                  {t("orders.status")}
                </th>
                <th className="px-4 py-3 text-xs font-medium text-gray-500 dark:text-gray-300">
                  {t("orders.incompleteActions")}
                </th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 6 }).map((_, idx) => (
                  <tr key={`skeleton-${idx}`} className="border-t border-gray-100 dark:border-gray-700">
                    {Array.from({ length: 7 }).map((__, cellIdx) => (
                      <td key={`skeleton-${idx}-${cellIdx}`} className="px-4 py-4">
                        <div className="h-4 w-full rounded bg-gray-100 dark:bg-gray-700 animate-pulse" />
                      </td>
                    ))}
                  </tr>
                ))
              ) : error ? (
                <tr>
                  <td colSpan={7} className="px-4 py-10 text-center text-red-500 space-y-3">
                    <div>{error}</div>
                    <button
                      type="button"
                      onClick={handleRetry}
                      className="inline-flex items-center justify-center rounded-lg border border-red-200 px-3 py-1 text-sm text-red-600 hover:bg-red-50 dark:border-red-700/40 dark:text-red-300"
                    >
                      {t("orders.incompleteRetry")}
                    </button>
                  </td>
                </tr>
              ) : orders.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-10 text-center text-gray-500">
                    <p className="font-medium">{t("orders.incompleteNoOrders")}</p>
                    <p className="text-sm mt-1">{t("orders.incompleteNoOrdersDesc")}</p>
                  </td>
                </tr>
              ) : (
                orders.map((order) => {
                  const contact = getCustomerContact(order);
                  const lastUpdated = getLastUpdated(order);
                  return (
                    <tr
                      key={order.cartId}
                      className="border-t border-gray-100 dark:border-gray-700"
                    >
                      <td className="px-4 py-3">
                        <div className="text-sm font-medium text-gray-900 dark:text-white">
                          {getCustomerName(order)}
                        </div>
                        <div className="text-xs text-gray-500">
                          {t("orders.cartId")}:{" "}
                          <span className="font-mono" title={order.cartId}>
                            {order.cartId}
                          </span>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="text-sm text-gray-900 dark:text-white">
                          {contact.phone || t("orders.notSpecified")}
                        </div>
                        <div className="text-xs text-gray-500">
                          {contact.email || "-"}
                        </div>
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-900 dark:text-white">
                        {order.itemsCount || 0}
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-900 dark:text-white">
                        {formatPrice(order.total || 0)}
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-500 dark:text-gray-300">
                        {lastUpdated ? formatDate(lastUpdated) : t("orders.notSpecified")}
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusClasses(order)}`}
                        >
                          {getStatusLabel(order)}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          <Link
                            to={`/orders/incomplete/${encodeURIComponent(order.cartId)}`}
                            className="inline-flex items-center gap-1 rounded-md border border-gray-200 px-2.5 py-1 text-xs font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-700 dark:text-gray-200"
                          >
                            <ArrowTopRightOnSquareIcon className="h-4 w-4" />
                            {t("orders.incompleteViewDetails")}
                          </Link>
                          <button
                            type="button"
                            onClick={() => handleCopyCartId(order.cartId)}
                            className="inline-flex items-center gap-1 rounded-md border border-gray-200 px-2.5 py-1 text-xs font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-700 dark:text-gray-200"
                          >
                            <ClipboardDocumentIcon className="h-4 w-4" />
                            {t("orders.incompleteCopyId")}
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {!loading && orders.length > 0 && (
        <div className="flex items-center justify-between text-sm text-gray-600 dark:text-gray-400">
          <div>
            {t("orders.showing")} {(page - 1) * limit + 1} {t("orders.to")} {Math.min(page * limit, totalOrders)} {t("orders.of")} {totalOrders} {t("orders.orders2")}
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setPage((prev) => Math.max(prev - 1, 1))}
              disabled={page === 1}
              className="px-3 py-1 rounded border border-gray-200 dark:border-gray-700 disabled:opacity-50"
            >
              {t("orders.previous")}
            </button>
            <button
              onClick={() => setPage((prev) => Math.min(prev + 1, totalPages))}
              disabled={page >= totalPages}
              className="px-3 py-1 rounded border border-gray-200 dark:border-gray-700 disabled:opacity-50"
            >
              {t("orders.next")}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default IncompleteOrders;

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import { MagnifyingGlassIcon, CheckCircleIcon, FunnelIcon } from '@heroicons/react/24/outline';
import toast from 'react-hot-toast';
import { useVirtualizer } from '@tanstack/react-virtual';
import { useCurrency } from '../../hooks/useCurrency';
import { useDateFormat } from '../../hooks/useDateFormat';
import orderConfirmationService, {
  OrderConfirmationSettings,
  OrderConfirmationUser
} from '../../services/orderConfirmationService';

interface ConfirmationOrder {
  id: string;
  orderNumber: string;
  customerName: string;
  customerPhone?: string;
  customerEmail?: string;
  total: number;
  status: string;
  sourceType: string;
  createdAt: string;
  governorate?: string;
  assignedTo?: string | null;
  assignedAt?: string | null;
  confirmedAt?: string | null;
  isGuestOrder?: boolean;
  assignedToName?: string | null;
  assignmentStrategy?: string | null;
}

interface ConfirmationStats {
  range: { startDate: string; endDate: string };
  totals: {
    confirmedRegular: number;
    confirmedGuest: number;
    totalConfirmed: number;
    totalAssigned: number;
  };
  assignmentsByUser: Array<{
    userId: string;
    name: string;
    email?: string | null;
    count: number;
  }>;
}

interface OrderRowProps {
  order: ConfirmationOrder;
  assignValue: string;
  eligibleUsers: OrderConfirmationUser[];
  assigningId: string | null;
  settingsEnabled: boolean;
  selectionEnabled: boolean;
  isSelected: boolean;
  formatDate: (value: string) => string;
  formatPrice: (value: number) => string;
  strategyLabelMap: Record<string, string>;
  onAssignChange: (orderId: string, value: string) => void;
  onAssign: (orderId: string, userId: string) => void;
  onConfirm: (orderId: string) => void;
  onToggleSelect: (orderId: string) => void;
}

const OrderRow = React.memo(({
  order,
  assignValue,
  eligibleUsers,
  assigningId,
  settingsEnabled,
  selectionEnabled,
  isSelected,
  formatDate,
  formatPrice,
  strategyLabelMap,
  onAssignChange,
  onAssign,
  onConfirm,
  onToggleSelect
}: OrderRowProps) => {
  return (
    <div className="p-4 flex flex-col lg:flex-row lg:items-center gap-4">
      <div className="flex-1 flex items-start gap-3">
        {selectionEnabled && (
          <input
            type="checkbox"
            className="mt-1 h-4 w-4 rounded border-gray-300 text-indigo-600"
            checked={isSelected}
            onChange={() => onToggleSelect(order.id)}
          />
        )}
        <div className="flex-1">
        <div className="flex items-center gap-2">
          <Link
            to={`/orders/${encodeURIComponent(order.orderNumber)}`}
            className="font-bold text-gray-900 dark:text-white hover:text-indigo-600"
          >
            {order.orderNumber}
          </Link>
          {order.isGuestOrder && (
            <span className="text-xs px-2 py-0.5 rounded-full bg-slate-100 text-slate-600">
              ضيف
            </span>
          )}
        </div>
        <div className="text-sm text-gray-500 mt-1">
          {order.customerName} • {order.customerPhone || 'بدون هاتف'}
        </div>
        <div className="text-xs text-gray-400 mt-1">
          {formatDate(order.createdAt)} • {order.sourceType}
        </div>
        <div className="text-xs text-gray-400 mt-1">
          موزع على: {order.assignedToName || order.assignedTo || 'غير موزع'}
          {order.assignmentStrategy
            ? ` • ${strategyLabelMap[order.assignmentStrategy] || order.assignmentStrategy}`
            : ''}
        </div>
        </div>
      </div>
      <div className="text-sm font-semibold text-gray-800 dark:text-gray-200">
        {formatPrice(Number(order.total) || 0)}
      </div>
      <div className="text-xs px-2 py-1 rounded-full bg-amber-100 text-amber-700">
        {order.status}
      </div>
      <div className="flex items-center gap-2 flex-wrap">
        {settingsEnabled && (
          <>
            <select
              value={assignValue}
              onChange={(e) => onAssignChange(order.id, e.target.value)}
              className="px-2 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-xs min-w-[160px]"
              disabled={eligibleUsers.length === 0}
            >
              <option value="">اختر موظف للتوزيع</option>
              {eligibleUsers.map((user) => (
                <option key={user.id} value={user.id}>
                  {`${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || user.id}
                </option>
              ))}
            </select>
            <button
              onClick={() => onAssign(order.id, assignValue)}
              disabled={assigningId === order.id || !assignValue}
              className="inline-flex items-center gap-1 px-3 py-2 bg-indigo-600 text-white rounded-lg text-xs disabled:opacity-60"
            >
              توزيع
            </button>
          </>
        )}
        <button
          onClick={() => onConfirm(order.id)}
          className="inline-flex items-center gap-1 px-3 py-2 bg-green-600 text-white rounded-lg text-sm"
        >
          <CheckCircleIcon className="w-4 h-4" />
          تأكيد
        </button>
      </div>
    </div>
  );
});

const OrderConfirmationQueue: React.FC = () => {
  const { t } = useTranslation();
  const { formatPrice } = useCurrency();
  const { formatDate } = useDateFormat();

  const [settings, setSettings] = useState<OrderConfirmationSettings | null>(null);
  const [orders, setOrders] = useState<ConfirmationOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [limit] = useState(20);
  const [totalPages, setTotalPages] = useState(1);
  const [totalOrders, setTotalOrders] = useState(0);
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [sourceFilter, setSourceFilter] = useState('');
  const [onlyUnassigned, setOnlyUnassigned] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const [stats, setStats] = useState<ConfirmationStats | null>(null);
  const [statsLoading, setStatsLoading] = useState(false);
  const [statsStartDate, setStatsStartDate] = useState('');
  const [statsEndDate, setStatsEndDate] = useState('');
  const [statsRefreshKey, setStatsRefreshKey] = useState(0);
  const [statsStrategy, setStatsStrategy] = useState('');
  const [eligibleUsers, setEligibleUsers] = useState<OrderConfirmationUser[]>([]);
  const [assignSelections, setAssignSelections] = useState<Record<string, string>>({});
  const [assigningId, setAssigningId] = useState<string | null>(null);
  const [selectedOrderIds, setSelectedOrderIds] = useState<string[]>([]);
  const [bulkUserId, setBulkUserId] = useState('');
  const [bulkProcessing, setBulkProcessing] = useState(false);
  const listParentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const timeout = setTimeout(() => {
      setSearch(searchInput.trim());
      setPage(1);
    }, 400);
    return () => clearTimeout(timeout);
  }, [searchInput]);

  const sourceOptions = useMemo(
    () => [
      { value: '', label: 'كل المصادر' },
      { value: 'ai_conversation', label: 'محادثة AI' },
      { value: 'manual', label: 'يدوي' },
      { value: 'storefront', label: 'المتجر' },
      { value: 'woocommerce', label: 'WooCommerce' },
      { value: 'pos', label: 'POS' },
      { value: 'api', label: 'API' },
      { value: 'import', label: 'استيراد' },
      { value: 'unknown', label: 'غير معروف' }
    ],
    []
  );

  const statusOptions = useMemo(
    () => [
      { value: '', label: 'كل الحالات' },
      { value: 'pending', label: 'جديد / قيد الانتظار' },
      { value: 'confirmed', label: 'مؤكد' },
      { value: 'processing', label: 'قيد المعالجة' },
      { value: 'shipped', label: 'تم الشحن' },
      { value: 'delivered', label: 'تم التسليم' },
      { value: 'cancelled', label: 'ملغي' }
    ],
    []
  );

  const strategyOptions = useMemo(
    () => [
      { value: '', label: 'كل الاستراتيجيات' },
      { value: 'round_robin', label: 'توزيع متساوي' },
      { value: 'by_region', label: 'حسب المنطقة' },
      { value: 'by_specialty', label: 'حسب التخصص' },
      { value: 'by_workload', label: 'حسب العبء الحالي' },
      { value: 'manual', label: 'توزيع يدوي' }
    ],
    []
  );

  const strategyLabelMap = useMemo(() => {
    return strategyOptions.reduce<Record<string, string>>((acc, opt) => {
      if (opt.value) acc[opt.value] = opt.label;
      return acc;
    }, {});
  }, [strategyOptions]);

  const fetchSettings = async () => {
    try {
      const res = await orderConfirmationService.getSettings();
      setSettings(res.data);
    } catch (error: any) {
      toast.error(error?.message || 'تعذر تحميل الإعدادات');
    }
  };

  const fetchEligibleUsers = async () => {
    try {
      const res = await orderConfirmationService.getEligibleUsers();
      setEligibleUsers(Array.isArray(res.data) ? res.data : []);
    } catch (error: any) {
      toast.error(error?.message || 'تعذر تحميل فريق التوزيع');
    }
  };

  const fetchQueue = async () => {
    try {
      setLoading(true);
      const params: Record<string, any> = {
        page,
        limit
      };
      if (search) params.search = search;
      if (statusFilter) params.status = statusFilter;
      if (sourceFilter) params.sourceType = sourceFilter;
      if (onlyUnassigned) params.onlyUnassigned = true;

      const res = await orderConfirmationService.getQueue(params);
      setOrders(Array.isArray(res.data) ? res.data : []);
      setTotalOrders(res.pagination?.total || 0);
      setTotalPages(res.pagination?.pages || 1);
    } catch (error: any) {
      toast.error(error?.message || 'تعذر تحميل الطلبات');
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      setStatsLoading(true);
      const params: Record<string, any> = {};
      if (statsStartDate) params.startDate = statsStartDate;
      if (statsEndDate) params.endDate = statsEndDate;
      if (statsStrategy) params.strategy = statsStrategy;
      const res = await orderConfirmationService.getStats(params);
      setStats(res.data || null);
    } catch (error: any) {
      toast.error(error?.message || 'تعذر تحميل تقرير الفريق');
    } finally {
      setStatsLoading(false);
    }
  };

  useEffect(() => {
    fetchSettings();
  }, []);

  useEffect(() => {
    if (settings?.enabled) {
      fetchEligibleUsers();
    }
  }, [settings?.enabled]);

  useEffect(() => {
    fetchQueue();
  }, [page, limit, search, statusFilter, sourceFilter, onlyUnassigned, refreshKey]);

  useEffect(() => {
    if (settings?.enabled) {
      fetchStats();
    }
  }, [settings?.enabled, refreshKey, statsStartDate, statsEndDate, statsRefreshKey]);

  useEffect(() => {
    if (settings?.enabled) {
      fetchStats();
    }
  }, [statsStrategy]);

  const strategyLabel = useMemo(() => {
    const match = strategyOptions.find((opt) => opt.value === statsStrategy);
    return match?.label || '';
  }, [statsStrategy, strategyOptions]);

  const statsSummaryLabel = useMemo(() => {
    if (statsStartDate || statsEndDate) {
      const fromLabel = statsStartDate ? formatDate(statsStartDate) : '—';
      const toLabel = statsEndDate ? formatDate(statsEndDate) : '—';
      const base = `ملخص الفترة من ${fromLabel} إلى ${toLabel}.`;
      return statsStrategy ? `${base} الاستراتيجية: ${strategyLabel}.` : base;
    }
    if (statsStrategy) {
      return `ملخص آخر 30 يوم بناءً على عمليات التأكيد والتوزيع. الاستراتيجية: ${strategyLabel}.`;
    }
    return 'ملخص آخر 30 يوم بناءً على عمليات التأكيد والتوزيع.';
  }, [statsStartDate, statsEndDate, formatDate, statsStrategy, strategyLabel]);

  const handleConfirm = useCallback(async (orderId: string) => {
    try {
      const res = await orderConfirmationService.confirmOrder(orderId);
      if (res?.data?.status === 'pending') {
        toast('تم إرسال الطلب للموافقة');
      } else {
        toast.success('تم تأكيد الطلب');
      }
      setRefreshKey((prev) => prev + 1);
    } catch (error: any) {
      toast.error(error?.message || 'فشل تأكيد الطلب');
    }
  }, []);

  const handleAssign = useCallback(async (orderId: string, userId: string) => {
    if (!userId) {
      toast.error('اختر موظفاً للتوزيع أولاً');
      return;
    }
    try {
      setAssigningId(orderId);
      await orderConfirmationService.assignOrder(orderId, userId, null, 'manual');
      toast.success('تم توزيع الطلب');
      setRefreshKey((prev) => prev + 1);
    } catch (error: any) {
      toast.error(error?.message || 'فشل توزيع الطلب');
    } finally {
      setAssigningId(null);
    }
  }, []);

  const handleAssignChange = useCallback((orderId: string, value: string) => {
    setAssignSelections((prev) => ({
      ...prev,
      [orderId]: value
    }));
  }, []);

  const handleToggleSelect = useCallback((orderId: string) => {
    setSelectedOrderIds((prev) =>
      prev.includes(orderId) ? prev.filter((id) => id !== orderId) : [...prev, orderId]
    );
  }, []);

  const handleToggleSelectAll = useCallback(() => {
    setSelectedOrderIds((prev) => (prev.length === orders.length ? [] : orders.map((order) => order.id)));
  }, [orders]);

  const handleBulkConfirm = useCallback(async () => {
    if (!selectedOrderIds.length) {
      toast.error('اختر طلبات أولاً');
      return;
    }
    try {
      setBulkProcessing(true);
      const res = await orderConfirmationService.confirmOrders(selectedOrderIds);
      const summary = res?.data?.summary;
      if (summary) {
        const parts = [`تم تأكيد ${summary.confirmed} طلب`];
        if (summary.pending) parts.push(`${summary.pending} في انتظار الموافقة`);
        if (summary.failed) parts.push(`${summary.failed} فشل`);
        toast.success(parts.join('، '));
      } else {
        toast.success('تم تأكيد الطلبات');
      }
      setSelectedOrderIds([]);
      setRefreshKey((prev) => prev + 1);
    } catch (error: any) {
      toast.error(error?.message || 'فشل تأكيد الطلبات');
    } finally {
      setBulkProcessing(false);
    }
  }, [selectedOrderIds]);

  const handleBulkAssign = useCallback(async () => {
    if (!selectedOrderIds.length) {
      toast.error('اختر طلبات أولاً');
      return;
    }
    if (!bulkUserId) {
      toast.error('اختر موظفاً للتوزيع أولاً');
      return;
    }
    try {
      setBulkProcessing(true);
      const res = await orderConfirmationService.assignOrders(selectedOrderIds, bulkUserId, null, 'manual');
      const summary = res?.data?.summary;
      if (summary) {
        const parts = [`تم توزيع ${summary.assigned} طلب`];
        if (summary.failed) parts.push(`${summary.failed} فشل`);
        toast.success(parts.join('، '));
      } else {
        toast.success('تم توزيع الطلبات');
      }
      setSelectedOrderIds([]);
      setBulkUserId('');
      setRefreshKey((prev) => prev + 1);
    } catch (error: any) {
      toast.error(error?.message || 'فشل توزيع الطلبات');
    } finally {
      setBulkProcessing(false);
    }
  }, [selectedOrderIds, bulkUserId]);

  useEffect(() => {
    setSelectedOrderIds([]);
    setBulkUserId('');
  }, [orders]);

  const selectedCount = selectedOrderIds.length;
  const allSelected = orders.length > 0 && selectedCount === orders.length;

  const rowVirtualizer = useVirtualizer({
    count: orders.length,
    getScrollElement: () => listParentRef.current,
    estimateSize: () => 170,
    overscan: 6
  });


  if (settings && !settings.enabled) {
    return (
      <div className="space-y-6" dir="rtl">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">طلبات تحتاج تأكيد</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">
              هذه الصفحة تعرض الطلبات التي تتطلب تأكيداً قبل التنفيذ.
            </p>
          </div>
        </div>
        <div className="bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700 rounded-2xl p-6">
          <h2 className="text-lg font-bold text-amber-800 dark:text-amber-300">ميزة التأكيد غير مفعّلة</h2>
          <p className="text-sm text-amber-700 dark:text-amber-400 mt-2">
            يرجى تفعيل قواعد التأكيد والتوزيع من إعدادات الطلبات.
          </p>
          <Link
            to="/settings/orders?tab=confirmation"
            className="inline-flex mt-4 px-4 py-2 bg-amber-600 text-white rounded-xl text-sm font-semibold"
          >
            فتح الإعدادات
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex flex-col gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">طلبات تحتاج تأكيد</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            فلترة وإدارة الطلبات التي تحتاج إلى تأكيد قبل التنفيذ.
          </p>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="flex flex-col lg:flex-row gap-3">
          <div className="relative flex-1">
