                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <ChartBarIcon className="h-5 w-5 text-indigo-500" />
              توزيع الحالات
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {stats &&
                Object.entries(stats.statusDistribution).map(
                  ([status, count]) => (
                    <div
                      key={status}
                      className="flex justify-between items-center"
                    >
                      <span className="text-sm font-medium dark:text-gray-300">
                        {status}
                      </span>
                      <div className="flex items-center gap-3 flex-1 px-4">
                        <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full flex-1 overflow-hidden">
                          <div
                            className="h-full bg-indigo-500"
                            style={{
                              width: `${(count / stats.totalOrders) * 100}%`,
                            }}
                          />
                        </div>
                        <span className="text-xs text-gray-500 font-bold w-8 text-left">
                          {count}
                        </span>
                      </div>
                    </div>
                  ),
                )}
              {!stats && (
                <p className="text-center text-gray-500">لا توجد بيانات</p>
              )}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <MapPinIcon className="h-5 w-5 text-red-500" />
              توزيع المحافظات
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {stats &&
                Object.entries(stats.governorateStats)
                  .sort((a, b) => b[1] - a[1])
                  .slice(0, 5)
                  .map(([gov, count]) => (
                    <div
                      key={gov}
                      className="flex justify-between items-center"
                    >
                      <span className="text-sm font-medium dark:text-gray-300">
                        {gov}
                      </span>
                      <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">
                        {count} طلب
                      </span>
                    </div>
                  ))}
              {!stats && (
                <p className="text-center text-gray-500">لا توجد بيانات</p>
              )}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <CreditCardIcon className="h-5 w-5 text-green-500" />
              طرق الدفع
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {stats &&
                Object.entries(stats.paymentStats).map(([method, count]) => (
                  <div
                    key={method}
                    className="flex justify-between items-center"
                  >
                    <span className="text-sm font-medium dark:text-gray-300">
                      {method}
                    </span>
                    <span className="text-sm font-bold text-gray-900 dark:text-white">
                      {count}
                    </span>
                  </div>
                ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

