import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import toast from "react-hot-toast";
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  ClipboardDocumentListIcon,
  ExclamationTriangleIcon,
} from "@heroicons/react/24/outline";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import { useDateFormat } from "../../hooks/useDateFormat";
import { printPreparationSlip } from "../../utils/printPreparationSlip";
import {
  DEFAULT_SHORTAGE_HOLD_DETAILS,
  FALLBACK_STATUS_LABELS,
  SHORTAGE_HOLD_METADATA_KEY,
  SHORTAGE_HOLD_STATUS,
} from "./preparation/constants";
import {
  getApiErrorMessage,
  buildShortageHoldDetails,
  getEffectivePreparationStatus,
  getNextStatus,
  getQuickActionLabel,
  getShortageFollowUpState,
  getShortageFollowUpVisual,
  mergePlainObjects,
  normalizeStage,
  parseMaybeJsonObject,
  toNumber,
  toUpper,
} from "./preparation/helpers";
import type {
  InventoryProductSummary,
  ItemInsight,
  PreparationOrder,
  PreparationStatusOption,
  QcCheckKey,
  ShortageHoldDetails,
} from "./preparation/types";
import { usePreparationQueueData } from "./preparation/usePreparationQueueData";
import { usePreparationQueueUiState } from "./preparation/usePreparationQueueUiState";
import PreparationBulkActions from "./preparation/components/PreparationBulkActions";
import PreparationFilters from "./preparation/components/PreparationFilters";
import PreparationOrderCard from "./preparation/components/PreparationOrderCard";
import PreparationPageHeader from "./preparation/components/PreparationPageHeader";
import PreparationStats from "./preparation/components/PreparationStats";

type BulkStatusResult = {
  id?: string | number | null;
  success?: boolean;
};

const PreparationQueue: React.FC = () => {
  const { formatPrice } = useCurrency();
  const { formatDate } = useDateFormat();
  const { state: uiState, actions: uiActions } = usePreparationQueueUiState();

  const {
    orders,
    setOrders,
    inventory,
    warehouses,
    statusConfigs,
    preparationSettings,
    pagination,
    summary,
    shortageOwnerOptions: serverShortageOwnerOptions,
    loading,
    refreshing,
    fetchInventory,
    fetchAll,
  } = usePreparationQueueData({
    page: uiState.page,
    activeStage: uiState.activeStage,
    selectedWarehouseId: uiState.selectedWarehouseId,
    stockFilter: uiState.stockFilter,
    shortageReasonFilter: uiState.shortageReasonFilter,
    shortageFollowUpFilter: uiState.shortageFollowUpFilter,
    shortageOwnerFilter: uiState.shortageOwnerFilter,
    search: uiState.search,
  });
  const [rowUpdatingId, setRowUpdatingId] = useState<string | null>(null);
  const [bulkUpdating, setBulkUpdating] = useState(false);
  const [qcChecklistState, setQcChecklistState] = useState<
    Record<string, Partial<Record<QcCheckKey, boolean>>>
  >({});
  const [shortageHoldDrafts, setShortageHoldDrafts] = useState<
    Record<string, ShortageHoldDetails>
  >({});
  const [transferingItemKey, setTransferingItemKey] = useState<string | null>(null);
  const [printingOrderNumber, setPrintingOrderNumber] = useState<string | null>(
    null,
  );
  const [shortageSavingOrderId, setShortageSavingOrderId] = useState<
    string | null
  >(null);

  const {
    activeStage,
    selectedWarehouseId,
    stockFilter,
    shortageReasonFilter,
    shortageFollowUpFilter,
    shortageOwnerFilter,
    search,
    selectedOrders,
    statusSelections,
    bulkStatus,
  } = uiState;

  useEffect(() => {
    if (preparationSettings.defaultWarehouseId) {
      uiActions.applyDefaultWarehouse(preparationSettings.defaultWarehouseId);
    }
  }, [preparationSettings.defaultWarehouseId, uiActions]);

  useEffect(() => {
    setShortageHoldDrafts((previous) => {
      const nextDrafts = { ...previous };

      orders.forEach((order) => {
        if (!nextDrafts[order.orderNumber]) {
          nextDrafts[order.orderNumber] = buildShortageHoldDetails(order.metadata);
        }
      });

      return nextDrafts;
    });
  }, [orders]);

  const statusLabelMap = useMemo(() => {
    const map = new Map<string, string>();

    Object.entries(FALLBACK_STATUS_LABELS).forEach(([code, label]) => {
      map.set(code, label);
    });

    statusConfigs.forEach((status) => {
      map.set(toUpper(status.code), status.name);
    });

    return map;
  }, [statusConfigs]);

  const statusOptions = useMemo<PreparationStatusOption[]>(() => {
    const dynamicOptions = [
      { code: preparationSettings.startingStatus, fallbackName: "في انتظار التجهيز" },
      { code: "PREPARING", fallbackName: "قيد التجهيز" },
      { code: "QUALITY_CHECK", fallbackName: "فحص الجودة" },
      { code: "PACKAGED", fallbackName: "تم التغليف" },
      { code: SHORTAGE_HOLD_STATUS, fallbackName: "مؤجل بسبب العجز" },
      {
        code: preparationSettings.handoffStatus || "READY_TO_SHIP",
        fallbackName: "جاهز للشحن",
      },
    ];

    const deduped = new Map<string, PreparationStatusOption>();
    dynamicOptions.forEach((option) => {
      deduped.set(toUpper(option.code), {
        code: toUpper(option.code),
        fallbackName: option.fallbackName,
      });
    });

    return [...deduped.values()];
  }, [preparationSettings.handoffStatus, preparationSettings.startingStatus]);

  const enabledQcChecks = useMemo(
    () =>
      (
        Object.keys(preparationSettings.qcChecks) as QcCheckKey[]
      ).filter((key) => preparationSettings.qcChecks[key]),
    [preparationSettings.qcChecks],
  );

  const inventorySummaryByProduct = useMemo(() => {
    const map = new Map<string, InventoryProductSummary>();

    inventory.forEach((record) => {
      const productId = String(record.productId || "");
      if (!productId) return;

      if (!map.has(productId)) {
        map.set(productId, {
          productId,
          productName:
            record.products?.name || record.products?.sku || "منتج غير مسمى",
          sku: record.products?.sku || null,
          totalQuantity: 0,
          totalAvailable: 0,
          totalReserved: 0,
          warehouses: [],
        });
      }

      const entry = map.get(productId)!;
      entry.totalQuantity += toNumber(record.quantity);
      entry.totalAvailable += toNumber(record.available);
      entry.totalReserved += toNumber(record.reserved);
      entry.warehouses.push({
        warehouseId: String(record.warehouseId || ""),
        warehouseName: record.warehouses?.name || "مخزن غير محدد",
        quantity: toNumber(record.quantity),
        available: toNumber(record.available),
        reserved: toNumber(record.reserved),
      });
    });

    map.forEach((entry) => {
      entry.warehouses.sort((a, b) => b.available - a.available);
    });

    return map;
  }, [inventory]);

  const preparationOrders = useMemo(() => {
    const dedupeWarehouseName = (names: Array<string | null>) => {
      const counter = new Map<string, number>();
      names
        .filter((name): name is string => Boolean(name))
        .forEach((name) => {
          counter.set(name, (counter.get(name) || 0) + 1);
        });

      const winner = [...counter.entries()].sort((a, b) => b[1] - a[1])[0];
      return winner?.[0] || null;
    };

    return orders.reduce<PreparationOrder[]>((result, order) => {
        const normalizedStatus = getEffectivePreparationStatus(
          order.status,
          order.metadata,
        );
        const stage = normalizeStage(normalizedStatus);
        const totalValue = toNumber(order.total);
        const shortageHoldDetails = buildShortageHoldDetails(order.metadata);

        if (!stage) {
          return result;
        }

        const itemInsights: ItemInsight[] = order.items.map((item) => {
          const summary = inventorySummaryByProduct.get(String(item.productId || ""));
          const scopedWarehouses = selectedWarehouseId
            ? summary?.warehouses.filter(
                (warehouse) => warehouse.warehouseId === selectedWarehouseId,
              ) || []
            : summary?.warehouses || [];

          const availableInScope = scopedWarehouses.reduce(
            (sum, warehouse) => sum + warehouse.available,
            0,
          );
          const reservedInScope = scopedWarehouses.reduce(
            (sum, warehouse) => sum + warehouse.reserved,
            0,
          );
          const quantityNumber = Math.max(1, toNumber(item.quantity));
          const bestWarehouseName = scopedWarehouses[0]?.warehouseName || null;
          const metadataProductName =
            typeof item.metadata === "object" &&
            item.metadata &&
            !Array.isArray(item.metadata) &&
            typeof item.metadata["productName"] === "string"
              ? item.metadata["productName"]
              : "";

          return {
            ...item,
            displayName: item.productName || item.name || metadataProductName || "منتج غير محدد",
            quantityNumber,
            availableInScope,
            reservedInScope,
            shortage: Math.max(0, quantityNumber - availableInScope),
            bestWarehouseName,
            warehouseCount: scopedWarehouses.length,
          };
        });

        const missingItemsCount = itemInsights.filter(
          (item) => item.shortage > 0,
        ).length;
        const warehouseMatch = selectedWarehouseId
          ? itemInsights.some(
              (item) =>
                item.availableInScope > 0 ||
                item.reservedInScope > 0 ||
                item.warehouseCount > 0,
            )
          : true;

        result.push({
          ...order,
          normalizedStatus,
          stage,
          totalValue,
          totalUnits: itemInsights.reduce(
            (sum, item) => sum + item.quantityNumber,
            0,
          ),
          itemInsights,
          missingItemsCount,
          isReady: itemInsights.length > 0 && missingItemsCount === 0,
          warehouseMatch,
          recommendedWarehouseName: dedupeWarehouseName(
            itemInsights.map((item) => item.bestWarehouseName),
          ),
          shortageHoldDetails,
        });

        return result;
      }, []);
  }, [inventorySummaryByProduct, orders, selectedWarehouseId]);

  const shortageOwnerOptions = useMemo(() => {
    const uniqueOwners = new Set<string>();

    serverShortageOwnerOptions.forEach((owner) => {
      const normalizedOwner = owner.trim();
      if (normalizedOwner) {
        uniqueOwners.add(normalizedOwner);
      }
    });

    preparationOrders.forEach((order) => {
      const effectiveShortageDetails =
        shortageHoldDrafts[order.orderNumber] || order.shortageHoldDetails;
      const owner = effectiveShortageDetails.owner.trim();
      if (owner) {
        uniqueOwners.add(owner);
      }
    });

    return [...uniqueOwners].sort((left, right) => left.localeCompare(right, "ar"));
  }, [preparationOrders, serverShortageOwnerOptions, shortageHoldDrafts]);

  const stageCounts = summary.stageCounts;
  const totalPages = Math.max(1, pagination.pages);
  const paginatedOrders = preparationOrders;
  const visibleOrdersCount = summary.visibleTotal;
  const searchedOrdersCount = summary.filteredTotal;
  const readyCount = summary.readyCount;
  const shortageCount = summary.shortageCount;
  const shortageHoldCount = summary.shortageHoldCount;
  const overdueShortageFollowUpCount = summary.overdueShortageFollowUpCount;
  const allOverdueShortageFollowUpCount =
    summary.allOverdueShortageFollowUpCount;
  const readyToShipCount = summary.readyToShipCount;

  useEffect(() => {
    uiActions.clampPage(totalPages);
  }, [totalPages, uiActions]);

  const selectionResetKey = useMemo(
    () =>
      [
        activeStage,
        selectedWarehouseId,
        stockFilter,
        shortageReasonFilter,
        shortageFollowUpFilter,
        shortageOwnerFilter.trim().toLowerCase(),
        search.trim().toLowerCase(),
      ].join("|"),
    [
      activeStage,
      search,
      selectedWarehouseId,
      shortageFollowUpFilter,
      shortageOwnerFilter,
      shortageReasonFilter,
      stockFilter,
    ],
  );
  const didInitSelectionReset = useRef(false);

  useEffect(() => {
    if (!didInitSelectionReset.current) {
      didInitSelectionReset.current = true;
      return;
    }

    uiActions.clearBulkControls();
  }, [selectionResetKey, uiActions]);

  const selectedSet = useMemo(() => new Set(selectedOrders), [selectedOrders]);
  const allVisibleSelected =
    paginatedOrders.length > 0 &&
    paginatedOrders.every((order) => selectedSet.has(order.orderNumber));

  const updateLocalStatuses = useCallback(
    (orderNumbers: string[], nextStatus: string) => {
      const normalized = toUpper(nextStatus);
      setOrders((previous) =>
        previous.map((order) =>
          orderNumbers.includes(order.orderNumber)
            ? { ...order, status: normalized, updatedAt: new Date().toISOString() }
            : order,
        ),
      );
    },
    [],
  );

  const updateLocalMetadata = useCallback(
    (orderNumber: string, metadataPatch: Record<string, unknown>) => {
      setOrders((previous) =>
        previous.map((order) => {
          if (order.orderNumber !== orderNumber) return order;

          const currentMetadata = parseMaybeJsonObject(order.metadata);
          return {
            ...order,
            metadata: mergePlainObjects(currentMetadata, metadataPatch),
            updatedAt: new Date().toISOString(),
          };
        }),
      );
    },
    [],
  );

  const getOrderByNumber = useCallback(
    (orderNumber: string) =>
      preparationOrders.find((order) => order.orderNumber === orderNumber) || null,
    [preparationOrders],
  );

  const isQcComplete = useCallback(
    (orderNumber: string) => {
      if (!preparationSettings.enableQcChecklist || enabledQcChecks.length === 0) {
        return true;
      }

      return enabledQcChecks.every(
        (key) => qcChecklistState[orderNumber]?.[key] === true,
      );
    },
    [enabledQcChecks, preparationSettings.enableQcChecklist, qcChecklistState],
  );

  const validateTransition = useCallback(
    (order: PreparationOrder, nextStatus: string) => {
      const normalizedNextStatus = toUpper(nextStatus);

      if (!preparationSettings.enabled) {
        return {
          valid: false,
          message: "تم إيقاف مسار التجهيز من الإعدادات الحالية",
        };
      }

      if (
        preparationSettings.requireStockBeforePreparing &&
        !preparationSettings.allowPartialPreparation &&
        !order.isReady &&
        [
          "PREPARING",
          "QUALITY_CHECK",
          "PACKAGED",
          preparationSettings.handoffStatus,
        ].includes(normalizedNextStatus)
      ) {
        return {
          valid: false,
          message: preparationSettings.allowCrossWarehouseTransfer
            ? "لا يمكن متابعة الطلب مع وجود نواقص. يمكنك تحديد مخزن الوجهة ثم استخدام النقل السريع من العناصر الناقصة."
            : "لا يمكن متابعة الطلب مع وجود نواقص لأن الإعدادات تشترط اكتمال المخزون أولًا.",
        };
      }

      if (
        order.stage === "QUALITY_CHECK" &&
        ["PACKAGED", preparationSettings.handoffStatus].includes(normalizedNextStatus) &&
        !isQcComplete(order.orderNumber)
      ) {
        return {
          valid: false,
          message: "يجب استكمال checklist فحص الجودة قبل اعتماد التغليف.",
        };
      }

      return { valid: true, message: "" };
    },
    [
      isQcComplete,
      preparationSettings.allowCrossWarehouseTransfer,
      preparationSettings.allowPartialPreparation,
      preparationSettings.enabled,
      preparationSettings.handoffStatus,
      preparationSettings.requireStockBeforePreparing,
    ],
  );

  const handleQcCheckToggle = useCallback(
    (orderNumber: string, key: QcCheckKey, checked: boolean) => {
      setQcChecklistState((previous) => ({
        ...previous,
        [orderNumber]: {
          ...previous[orderNumber],
          [key]: checked,
        },
      }));
    },
    [],
  );

  const handleShortageFieldChange = useCallback(
    (
      orderNumber: string,
      field: keyof ShortageHoldDetails,
      value: string | boolean,
    ) => {
      setShortageHoldDrafts((previous) => ({
        ...previous,
        [orderNumber]: {
          ...DEFAULT_SHORTAGE_HOLD_DETAILS,
          ...(previous[orderNumber] || {}),
          [field]: value,
        },
      }));
    },
    [],
  );

  const handlePrintPreparationSlip = useCallback(async (orderNumber: string) => {
    try {
      setPrintingOrderNumber(orderNumber);
      await printPreparationSlip(orderNumber);
      toast.success("تم فتح ورقة التجهيز للطباعة");
    } catch (error: unknown) {
      console.error("Failed to print preparation slip:", error);
      toast.error(getApiErrorMessage(error) || "فشل في فتح ورقة التجهيز");
    } finally {
      setPrintingOrderNumber(null);
    }
  }, []);

  const saveShortageHoldDetails = useCallback(
    async (
      orderNumber: string,
      overrides: Partial<ShortageHoldDetails> = {},
      options?: { successMessage?: string | null },
    ) => {
      const order = orders.find((item) => item.orderNumber === orderNumber);
      if (!order) {
        toast.error("تعذر العثور على الطلب المحدد");
        return false;
      }

      const currentDraft =
        shortageHoldDrafts[orderNumber] || buildShortageHoldDetails(order.metadata);
      const nextDraft: ShortageHoldDetails = {
        ...DEFAULT_SHORTAGE_HOLD_DETAILS,
        ...currentDraft,
        ...overrides,
      };
      const metadataPatch = {
        [SHORTAGE_HOLD_METADATA_KEY]: nextDraft,
      };

      try {
        setShortageSavingOrderId(orderNumber);
        await apiClient.put(`/orders-new/simple/${encodeURIComponent(orderNumber)}`, {
          metadataPatch,
        });
        updateLocalMetadata(orderNumber, metadataPatch);
        setShortageHoldDrafts((previous) => ({
          ...previous,
          [orderNumber]: nextDraft,
        }));

        if (options?.successMessage !== null) {
          toast.success(options?.successMessage || "تم حفظ بيانات تعليق العجز");
        }

        void fetchAll();
        return true;
      } catch (error: unknown) {
        console.error("Failed to save shortage hold details:", error);
        toast.error(
          getApiErrorMessage(error) || "تعذر حفظ بيانات تعليق العجز",
        );
        return false;
      } finally {
        setShortageSavingOrderId(null);
      }
    },
    [fetchAll, orders, shortageHoldDrafts, updateLocalMetadata],
  );

  const handleSingleStatusUpdate = useCallback(
    async (orderNumber: string, nextStatus: string) => {
      const order = getOrderByNumber(orderNumber);
      if (!order) {
        toast.error("تعذر العثور على الطلب المحدد");
        return;
      }

      const validation = validateTransition(order, nextStatus);
      if (!validation.valid) {
        toast.error(validation.message);
        return;
      }

      try {
        setRowUpdatingId(orderNumber);
        await apiClient.post(
          `/orders-new/simple/${encodeURIComponent(orderNumber)}/status`,
          {
            status: nextStatus,
            notes:
              order.stage === "QUALITY_CHECK" &&
              ["PACKAGED", preparationSettings.handoffStatus].includes(
                toUpper(nextStatus),
              )
                ? "QC completed from preparation queue"
                : "Updated from preparation queue",
          },
        );

        updateLocalStatuses([orderNumber], nextStatus);
        toast.success(
          `تم تحديث ${orderNumber} إلى ${statusLabelMap.get(nextStatus) || nextStatus}`,
        );
        void fetchAll();
      } catch (error: unknown) {
        console.error("Failed to update order status:", error);
        toast.error(
          getApiErrorMessage(error) || "تعذر تحديث مرحلة التجهيز",
        );
      } finally {
        setRowUpdatingId(null);
      }
    },
    [
      getOrderByNumber,
      fetchAll,
      preparationSettings.handoffStatus,
      statusLabelMap,
      updateLocalStatuses,
      validateTransition,
    ],
  );

  const handleBulkUpdate = useCallback(async () => {
    if (!bulkStatus || selectedOrders.length === 0) return;

    const selectedOrderObjects = selectedOrders
      .map((orderNumber) => getOrderByNumber(orderNumber))
      .filter((order): order is PreparationOrder => Boolean(order));
    const validOrders: PreparationOrder[] = [];
    const invalidOrders: PreparationOrder[] = [];

    selectedOrderObjects.forEach((order) => {
      const validation = validateTransition(order, bulkStatus);
      if (validation.valid) {
        validOrders.push(order);
      } else {
        invalidOrders.push(order);
      }
    });

    if (validOrders.length === 0) {
      toast.error("كل الطلبات المحددة مخالفة لقواعد التجهيز الحالية");
      return;
    }

    const confirmed = window.confirm(
      `تحديث ${validOrders.length} طلب إلى مرحلة ${
        statusLabelMap.get(bulkStatus) || bulkStatus
      }${invalidOrders.length > 0 ? ` مع استبعاد ${invalidOrders.length} طلب غير مطابق` : ""}؟`,
    );

    if (!confirmed) return;

    try {
      setBulkUpdating(true);
      const response = await apiClient.post("/orders-new/bulk/status", {
        orderIds: validOrders.map((order) => order.orderNumber),
        status: bulkStatus,
      });

      const results: BulkStatusResult[] = Array.isArray(response.data?.data?.results)
        ? response.data.data.results
        : [];
      const successIds = results
        .filter((result) => result.success)
        .map((result) => String(result.id));

      if (successIds.length > 0) {
        updateLocalStatuses(successIds, bulkStatus);
      }

      const failedCount = results.filter((result) => !result.success).length;
      toast.success(
        failedCount > 0
          ? `تم تحديث ${successIds.length} طلب وفشل ${failedCount} طلب`
          : `تم تحديث ${successIds.length} طلب بنجاح`,
      );

      uiActions.clearBulkControls();
      void fetchAll();
    } catch (error: unknown) {
      console.error("Failed bulk status update:", error);
      toast.error(
        getApiErrorMessage(error) || "تعذر تحديث الطلبات المحددة",
      );
    } finally {
      setBulkUpdating(false);
    }
  }, [
    bulkStatus,
    fetchAll,
    getOrderByNumber,
    selectedOrders,
    statusLabelMap,
    updateLocalStatuses,
    validateTransition,
  ]);

  const handleQuickTransfer = useCallback(
    async (orderNumber: string, item: ItemInsight) => {
      if (!selectedWarehouseId) {
        toast.error("حدد مخزن الوجهة أولًا لتفعيل النقل السريع");
        return;
      }

      if (!item.productId || item.shortage <= 0) {
        toast.error("لا يوجد عجز صالح للنقل في هذا العنصر");
        return;
      }

      const productSummary = inventorySummaryByProduct.get(String(item.productId));
      const sourceWarehouse = productSummary?.warehouses.find(
        (warehouse) =>
          warehouse.warehouseId !== selectedWarehouseId &&
          warehouse.available >= item.shortage,
      );

      if (!sourceWarehouse) {
        toast.error("لم يتم العثور على مخزن مصدر يملك كمية كافية للنقل");
        return;
      }

      const transferKey = `${orderNumber}-${item.productId}`;

      try {
        setTransferingItemKey(transferKey);
        await apiClient.post("/inventory/transfer", {
          productId: item.productId,
          fromWarehouseId: sourceWarehouse.warehouseId,
          toWarehouseId: selectedWarehouseId,
          quantity: item.shortage,
          notes: `Preparation transfer for order ${orderNumber}`,
        });

        toast.success(
          `تم نقل ${item.shortage} قطعة من ${sourceWarehouse.warehouseName} إلى المخزن المحدد`,
        );
        await fetchInventory();
      } catch (error: unknown) {
        console.error("Failed quick transfer:", error);
        toast.error(
          getApiErrorMessage(error) || "تعذر تنفيذ النقل السريع",
        );
      } finally {
        setTransferingItemKey(null);
      }
    },
    [fetchInventory, inventorySummaryByProduct, selectedWarehouseId],
  );

  const handleMarkAsShortageHold = useCallback(
    async (orderNumber: string) => {
      const order = orders.find((item) => item.orderNumber === orderNumber);
      const currentDraft =
        shortageHoldDrafts[orderNumber] || buildShortageHoldDetails(order?.metadata);
      const saved = await saveShortageHoldDetails(
        orderNumber,
        {
          ...currentDraft,
          heldAt: currentDraft.heldAt || new Date().toISOString(),
          releasedAt: "",
          state: "held",
        },
        { successMessage: null },
      );
      if (!saved) return;

      await handleSingleStatusUpdate(orderNumber, SHORTAGE_HOLD_STATUS);
    },
    [handleSingleStatusUpdate, orders, saveShortageHoldDetails, shortageHoldDrafts],
  );

  const handleReleaseShortageHold = useCallback(
    async (orderNumber: string) => {
      const order = orders.find((item) => item.orderNumber === orderNumber);
      const currentDraft =
        shortageHoldDrafts[orderNumber] || buildShortageHoldDetails(order?.metadata);
      const saved = await saveShortageHoldDetails(
        orderNumber,
        {
          ...currentDraft,
          releasedAt: new Date().toISOString(),
          state: "released",
        },
        { successMessage: null },
      );
      if (!saved) return;

      await handleSingleStatusUpdate(
        orderNumber,
        preparationSettings.startingStatus,
      );
    },
    [
      handleSingleStatusUpdate,
      orders,
      preparationSettings.startingStatus,
      saveShortageHoldDetails,
      shortageHoldDrafts,
    ],
  );

  const toggleOrderSelection = (orderNumber: string) => {
    uiActions.toggleOrderSelection(orderNumber);
  };

  const toggleSelectAllVisible = () => {
    if (allVisibleSelected) {
      uiActions.clearVisibleSelection(
        paginatedOrders.map((order) => order.orderNumber),
      );
      return;
    }

    const visibleIds = paginatedOrders.map((order) => order.orderNumber);
    uiActions.selectVisibleOrders(visibleIds);
  };

  if (loading) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center">
        <div className="text-center">
          <div className="mx-auto h-14 w-14 rounded-full border-4 border-amber-200 border-t-amber-500 animate-spin" />
          <p className="mt-4 text-sm text-gray-500">
            جاري تحميل قائمة تجهيز الطلبات...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PreparationPageHeader
        refreshing={refreshing}
        onRefresh={() => void fetchAll(true)}
      />

      <PreparationStats
        searchedOrdersCount={searchedOrdersCount}
        readyCount={readyCount}
        shortageCount={shortageCount}
        readyToShipCount={readyToShipCount}
        shortageHoldCount={shortageHoldCount}
        overdueShortageFollowUpCount={overdueShortageFollowUpCount}
      />

      {!preparationSettings.enabled ? (
        <section className="rounded-3xl border border-amber-200 bg-amber-50 px-5 py-4 shadow-sm">
          <div className="flex items-start gap-3">
            <ExclamationTriangleIcon className="mt-0.5 h-5 w-5 shrink-0 text-amber-700" />
            <div>
              <h2 className="font-semibold text-amber-900">
                صفحة التجهيز معطلة من الإعدادات
              </h2>
              <p className="mt-1 text-sm text-amber-800">
                التبويب ما زال ظاهرًا للإدارة، لكن الإعدادات الحالية تشير إلى أن
                workflow التجهيز متوقف. يمكنك إعادة تفعيله من إعدادات الطلبات ثم
                تبويب تجهيز الطلبات.
              </p>
            </div>
          </div>
        </section>
      ) : null}

      {allOverdueShortageFollowUpCount > 0 ? (
        <section className="rounded-3xl border border-orange-200 bg-orange-50 px-5 py-4 shadow-sm">
          <div className="flex items-start gap-3">
            <ExclamationTriangleIcon className="mt-0.5 h-5 w-5 shrink-0 text-orange-700" />
            <div>
              <h2 className="font-semibold text-orange-900">
                توجد طلبات مؤجلة تجاوزت موعد المتابعة
              </h2>
              <p className="mt-1 text-sm text-orange-800">
                يوجد حاليًا {allOverdueShortageFollowUpCount} طلب في `مؤجل للعجز`
                مرّ عليه تاريخ المتابعة. استخدم فلتر السبب أو المسؤول للوصول
                السريع لها ومراجعتها.
              </p>
            </div>
          </div>
        </section>
      ) : null}

      <PreparationFilters
        activeStage={activeStage}
        stageCounts={stageCounts}
        visibleOrdersCount={visibleOrdersCount}
        search={search}
        selectedWarehouseId={selectedWarehouseId}
        stockFilter={stockFilter}
        shortageReasonFilter={shortageReasonFilter}
        shortageOwnerFilter={shortageOwnerFilter}
        shortageOwnerOptions={shortageOwnerOptions}
        shortageFollowUpFilter={shortageFollowUpFilter}
        warehouses={warehouses}
        onActiveStageChange={uiActions.setActiveStage}
        onSearchChange={uiActions.setSearch}
        onSelectedWarehouseChange={uiActions.setSelectedWarehouse}
        onStockFilterChange={uiActions.setStockFilter}
        onShortageReasonFilterChange={uiActions.setShortageReasonFilter}
        onShortageOwnerFilterChange={uiActions.setShortageOwnerFilter}
        onShortageFollowUpFilterChange={uiActions.setShortageFollowUpFilter}
      />

      <PreparationBulkActions
        selectedOrdersCount={selectedOrders.length}
        bulkStatus={bulkStatus}
        statusOptions={statusOptions}
        statusLabelMap={statusLabelMap}
        bulkUpdating={bulkUpdating}
        preparationEnabled={preparationSettings.enabled}
        bulkStatusUpdateEnabled={preparationSettings.enableBulkStatusUpdate}
        onBulkStatusChange={uiActions.setBulkStatus}
        onApply={() => void handleBulkUpdate()}
        onClear={uiActions.clearBulkControls}
      />

      <section className="rounded-3xl border border-gray-200 bg-white p-5 shadow-sm">
        <div className="flex flex-col gap-3 border-b border-gray-100 pb-4 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h2 className="text-lg font-semibold text-gray-900">
              قائمة التنفيذ اليومي
            </h2>
            <p className="mt-1 text-sm text-gray-500">
              الطلبات المعروضة هنا مرتبة بحسب الفلاتر الحالية، ويمكن فتح الطلب
              أو تحريك مرحلته مباشرة من البطاقة.
            </p>
          </div>

          <label className="inline-flex items-center gap-3 rounded-2xl border border-gray-200 bg-gray-50 px-4 py-3 text-sm text-gray-700">
            <input
              type="checkbox"
              checked={allVisibleSelected}
              onChange={toggleSelectAllVisible}
              className="h-4 w-4 rounded border-gray-300 text-amber-600 focus:ring-amber-500"
            />
            تحديد كل الطلبات في الصفحة الحالية
          </label>
        </div>

        {paginatedOrders.length === 0 ? (
          <div className="flex min-h-[280px] flex-col items-center justify-center rounded-3xl border border-dashed border-gray-200 bg-gray-50 px-6 py-10 text-center">
            <ClipboardDocumentListIcon className="h-12 w-12 text-gray-300" />
            <h3 className="mt-4 text-lg font-semibold text-gray-900">
              لا توجد طلبات مطابقة الآن
            </h3>
            <p className="mt-2 max-w-xl text-sm leading-6 text-gray-500">
              جرّب تغيير الفلاتر أو إزالة فلتر المخزن، أو حدّث الصفحة إذا كنت
              تتوقع وجود طلبات جديدة في مسار التجهيز.
            </p>
          </div>
        ) : (
          <div className="mt-5 grid grid-cols-1 gap-5 2xl:grid-cols-2">
            {paginatedOrders.map((order) => {
              const shortageHoldDetails =
                shortageHoldDrafts[order.orderNumber] ||
                buildShortageHoldDetails(order.metadata);
              const shortageFollowUpVisual =
                getShortageFollowUpVisual(
                  getShortageFollowUpState(
                    shortageHoldDetails.followUpDate,
                    order.stage,
                  ),
                );
              const nextStatus = getNextStatus(
                order.stage,
                preparationSettings.handoffStatus,
                preparationSettings.startingStatus,
              );
              const currentSelection =
                statusSelections[order.orderNumber] ||
                (order.stage === "WAITING"
                  ? preparationSettings.startingStatus
                  : order.stage === "PREPARING"
                    ? "PREPARING"
                    : order.stage === "QUALITY_CHECK"
                      ? "QUALITY_CHECK"
                      : order.stage === "PACKAGED"
                        ? "PACKAGED"
                        : order.stage === "STOCK_SHORTAGE"
                          ? preparationSettings.startingStatus
                          : preparationSettings.handoffStatus);
              const actionLabel =
                statusSelections[order.orderNumber] &&
                statusSelections[order.orderNumber] !== nextStatus
                  ? "تطبيق المرحلة المختارة"
                  : getQuickActionLabel(order.stage);
              const qcCompleted = isQcComplete(order.orderNumber);
              const rowBusy =
                rowUpdatingId === order.orderNumber ||
                shortageSavingOrderId === order.orderNumber;
              const hasShortageContext =
                order.missingItemsCount > 0 || order.stage === "STOCK_SHORTAGE";

              return (
                <PreparationOrderCard
                  key={order.orderNumber}
                  order={order}
                  selected={selectedSet.has(order.orderNumber)}
                  statusOptions={statusOptions}
                  statusLabelMap={statusLabelMap}
                  currentSelection={currentSelection}
                  actionLabel={actionLabel}
                  qcCompleted={qcCompleted}
                  rowBusy={rowBusy}
                  hasShortageContext={hasShortageContext}
                  selectedWarehouseId={selectedWarehouseId}
                  enabledQcChecks={enabledQcChecks}
                  qcChecklist={qcChecklistState[order.orderNumber]}
                  shortageHoldDetails={shortageHoldDetails}
                  shortageFollowUpVisual={shortageFollowUpVisual}
                  transferingItemKey={transferingItemKey}
                  printingOrderNumber={printingOrderNumber}
                  preparationSettings={preparationSettings}
                  formatPrice={formatPrice}
                  formatDate={formatDate}
                  onToggleSelection={toggleOrderSelection}
                  onQuickTransfer={(orderNumber, item) =>
                    void handleQuickTransfer(orderNumber, item)
                  }
                  onShortageFieldChange={handleShortageFieldChange}
                  onSaveShortageHoldDetails={saveShortageHoldDetails}
                  onQcCheckToggle={handleQcCheckToggle}
                  onStatusSelectionChange={uiActions.setStatusSelection}
                  onSingleStatusUpdate={(orderNumber, nextStatus) =>
                    void handleSingleStatusUpdate(orderNumber, nextStatus)
                  }
                  onMarkAsShortageHold={(orderNumber) =>
                    void handleMarkAsShortageHold(orderNumber)
                  }
                  onReleaseShortageHold={(orderNumber) =>
                    void handleReleaseShortageHold(orderNumber)
                  }
                  onPrintPreparationSlip={(orderNumber) =>
                    void handlePrintPreparationSlip(orderNumber)
                  }
                />
              );
            })}
          </div>
        )}

        <div className="mt-6 flex flex-col gap-3 border-t border-gray-100 pt-4 lg:flex-row lg:items-center lg:justify-between">
          <p className="text-sm text-gray-500">
            صفحة {pagination.page} من {totalPages} • إجمالي {visibleOrdersCount} طلب
          </p>

          <div className="flex items-center gap-3">
            <button
              onClick={uiActions.goToPreviousPage}
              disabled={pagination.page === 1}
              className="inline-flex items-center gap-2 rounded-2xl border border-gray-200 px-4 py-2 text-sm font-medium text-gray-700 transition hover:border-gray-300 disabled:cursor-not-allowed disabled:opacity-50"
            >
              <ChevronRightIcon className="h-4 w-4" />
              السابق
            </button>

            <button
              onClick={() => uiActions.goToNextPage(totalPages)}
              disabled={pagination.page === totalPages}
              className="inline-flex items-center gap-2 rounded-2xl border border-gray-200 px-4 py-2 text-sm font-medium text-gray-700 transition hover:border-gray-300 disabled:cursor-not-allowed disabled:opacity-50"
            >
              التالي
              <ChevronLeftIcon className="h-4 w-4" />
            </button>
          </div>
        </div>
      </section>
    </div>
  );
};

export default PreparationQueue;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import { Link, useSearchParams } from "react-router-dom";
import { format } from "date-fns";
import toast from "react-hot-toast";
import {
    MagnifyingGlassIcon,
    ArrowPathIcon,
    TruckIcon,
    InformationCircleIcon,
} from "@heroicons/react/24/outline";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import { useDateFormat } from "../../hooks/useDateFormat";

interface TurboOrder {
    id: string;
    orderNumber: string;
    customerName: string;
    customerPhone: string;
    total: number;
    status: string;
    shippingAddress?: {
        governorate?: string;
        city?: string;
    };
    trackingNumber?: string;
    createdAt: string;
}

const TurboRecords: React.FC = () => {
    const { t } = useTranslation();
    const { formatPrice } = useCurrency();
    const { formatDate } = useDateFormat();

    const [searchParams, setSearchParams] = useSearchParams();
    const [orders, setOrders] = useState<TurboOrder[]>([]);
    const [loading, setLoading] = useState(true);
    const [refreshingStatuses, setRefreshingStatuses] = useState(false);
    const [creatingShipments, setCreatingShipments] = useState(false);

    const [page, setPage] = useState(parseInt(searchParams.get("page") || "1"));
    const [limit, setLimit] = useState(parseInt(searchParams.get("limit") || "20"));
    const [searchQuery, setSearchQuery] = useState(searchParams.get("search") || "");
    const [filterType, setFilterType] = useState<"all" | "unshipped" | "shipped">(
        (searchParams.get("filterType") as any) || "all"
    );

    const [totalPages, setTotalPages] = useState(1);
    const [totalOrders, setTotalOrders] = useState(0);
    const [selectedOrders, setSelectedOrders] = useState<string[]>([]);

    useEffect(() => {
        fetchOrders();
    }, [page, limit, filterType]);

    // Update URL params when search state changes (handling debounce/button click manually below)
    const updateUrlParams = (newParams: Record<string, string>) => {
        const params = Object.fromEntries(searchParams.entries());
        Object.assign(params, newParams);

        // Clean up empty params
        Object.keys(params).forEach(key => {
            if (!params[key]) delete params[key];
        });

        setSearchParams(params, { replace: true });
    };

    const fetchOrders = async (currentSearch = searchQuery) => {
        setLoading(true);
        try {
            const params: any = {
                page: page.toString(),
                limit: limit.toString(),
                search: currentSearch,
            };

            // To filter unshipped orders (orders without Turbo tracking code or specific status)
            // Custom implementation: assuming backend supports these or we might need to filter.
            // Based on typical behavior, let's use the simple endpoint and filter here or pass a specific status if backend supports it.
            // We'll pass 'shippingProvider=turbo' if backend supported it, else we fetch orders and show.

            const response = await apiClient.get("/orders-new/simple", { params });

            if (response.data.success) {
                let fetchedOrders = response.data.data || [];

                // Filter locally if backend doesn't support specific 'unshipped turbo' flags directly
                // For Turbo: looking for orders that either have trackingNumber from Turbo, OR user wants to send them to Turbo
                if (filterType === "unshipped") {
                    fetchedOrders = fetchedOrders.filter((o: any) => !o.trackingNumber);
                } else if (filterType === "shipped") {
                    fetchedOrders = fetchedOrders.filter((o: any) => !!o.trackingNumber); // Basic check for tracking
                }

                setOrders(fetchedOrders);
                if (response.data.pagination) {
                    // If we filtered locally, pagination might be slightly off visually, but acceptable for MVP
                    setTotalPages(response.data.pagination.pages || 1);
                    setTotalOrders(response.data.pagination.total || fetchedOrders.length);
                }
            }
        } catch (error) {
            console.error("Error fetching Turbo records:", error);
            toast.error(t("orders.fetchError", "Failed to load orders"));
        } finally {
            setLoading(false);
        }
    };

    const handleSearchClick = () => {
        setPage(1);
        updateUrlParams({ search: searchQuery, page: "1", filterType });
        fetchOrders(searchQuery);
    };

    const handleFilterChange = (newFilter: "all" | "unshipped" | "shipped") => {
        setFilterType(newFilter);
        setPage(1);
        updateUrlParams({ filterType: newFilter, page: "1", search: searchQuery });
    };

    const toggleOrderSelection = (id: string) => {
        setSelectedOrders(prev =>
            prev.includes(id) ? prev.filter(orderId => orderId !== id) : [...prev, id]
        );
    };

    const toggleAllSelection = () => {
        if (orders.length === 0) return;
        if (selectedOrders.length === orders.length) {
            setSelectedOrders([]);
        } else {
            setSelectedOrders(orders.map(o => o.id)); // assuming 'id' is used for these actions
        }
    };

    // Turbo Actions
    const handleBulkCreateShipments = async () => {
        if (selectedOrders.length === 0) return toast.error("Select orders first");

        // Ensure we are sending the correct identifier (orderNumber vs id) based on backend. 
        // The previous implementation used selectedOrders containing orderNumbers or IDs. 
        // Assuming apiClient.post("/turbo/bulk/create-shipments", { orderIds: selectedOrders }) expects IDs based on standard.

        if (!window.confirm(`Are you sure you want to send ${selectedOrders.length} orders to Turbo?`)) return;

        setCreatingShipments(true);
        try {
            const response = await apiClient.post("/turbo/bulk/create-shipments", { orderIds: selectedOrders });
            if (response.data.success) {
                toast.success(`Success: ${response.data.data?.success || 0}, Failed: ${response.data.data?.failed || 0}`);
                fetchOrders(); // Refresh
                setSelectedOrders([]);
            } else {
                toast.error(response.data.message || "Failed to create shipments");
            }
        } catch (error: any) {
            console.error(error);
            toast.error(error.response?.data?.message || "An error occurred");
        } finally {
            setCreatingShipments(false);
        }
    };

    const handleRefreshStatuses = async () => {
        // This could loop through selected orders to track them, or call a backend bulk track if exists.
        // For single orders: GET /api/turbo/orders/:orderId/track
        if (selectedOrders.length === 0) return toast.error("Select orders first");

        setRefreshingStatuses(true);
        let successCount = 0;
        let failCount = 0;

        for (const orderId of selectedOrders) {
            try {
                await apiClient.get(`/turbo/orders/${orderId}/track`);
                successCount++;
            } catch (err) {
                failCount++;
            }
        }

        toast.success(`Refresh complete. Success: ${successCount}, Fail: ${failCount}`);
        fetchOrders(); // Refresh table
        setSelectedOrders([]);
        setRefreshingStatuses(false);
    };

    // Get status color (using standard order status map)
    const getStatusColor = (status: string) => {
        const s = status.toLowerCase();
        if (s === 'delivered') return 'bg-green-100 text-green-800';
        if (s === 'shipped') return 'bg-blue-100 text-blue-800';
        if (s === 'cancelled') return 'bg-red-100 text-red-800';
        return 'bg-gray-100 text-gray-800';
    };

    return (
        <div className="p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                        <TruckIcon className="h-6 w-6 text-blue-600" />
                        سجلات تربو (Turbo Records)
                    </h1>
                    <p className="text-sm text-gray-500 mt-1">
                        إدارة الشحنات، متابعة الحالات، وإرسال الطلبات إلى تربو
                    </p>
                </div>

                <div className="flex gap-2 mt-4 md:mt-0">
                    <button
                        onClick={handleRefreshStatuses}
                        disabled={refreshingStatuses || selectedOrders.length === 0}
                        className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50"
                    >
                        <ArrowPathIcon className={`h-4 w-4 ${refreshingStatuses ? 'animate-spin' : ''}`} />
                        تحديث الحالة
                    </button>

                    <button
                        onClick={handleBulkCreateShipments}
                        disabled={creatingShipments || selectedOrders.length === 0}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 border border-transparent rounded-lg text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
                    >
                        <TruckIcon className="h-4 w-4" />
                        إرسال إلى تربو
                    </button>
                </div>
            </div>

            {/* Filters & Search */}
            <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm mb-6 flex flex-col md:flex-row gap-4 justify-between">
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => handleFilterChange("all")}
                        className={`px-3 py-1.5 rounded-md text-sm font-medium ${filterType === 'all' ? 'bg-blue-100 text-blue-700' : 'text-gray-600 hover:bg-gray-100'}`}
                    >
                        الكل
                    </button>
                    <button
                        onClick={() => handleFilterChange("unshipped")}
                        className={`px-3 py-1.5 rounded-md text-sm font-medium ${filterType === 'unshipped' ? 'bg-orange-100 text-orange-700' : 'text-gray-600 hover:bg-gray-100'}`}
                    >
                        لم يتم الشحن
                    </button>
                    <button
                        onClick={() => handleFilterChange("shipped")}
                        className={`px-3 py-1.5 rounded-md text-sm font-medium ${filterType === 'shipped' ? 'bg-green-100 text-green-700' : 'text-gray-600 hover:bg-gray-100'}`}
                    >
                        مُشحنة
                    </button>
                </div>

                <div className="flex items-center gap-2 w-full md:w-96">
                    <div className="relative flex-1">
                        <MagnifyingGlassIcon className="absolute right-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                        <input
                            type="text"
                            placeholder="بحث برقم الطلب، العميل، التتبع..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSearchClick()}
                            className="w-full pl-3 pr-10 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                        />
                    </div>
                    <button
                        onClick={handleSearchClick}
                        className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 font-medium text-sm"
                    >
                        بحث
                    </button>
                </div>
            </div>

            {/* Table */}
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200 text-right" dir="rtl">
                        <thead className="bg-gray-50">
                            <tr>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider w-10">
                                    <input
                                        type="checkbox"
                                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                                        checked={orders.length > 0 && selectedOrders.length === orders.length}
                                        onChange={toggleAllSelection}
                                    />
                                </th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">الطلب</th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">العميل</th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">الإجمالي</th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">رقم التتبع</th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">الحالة</th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">التاريخ</th>
                                <th scope="col" className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">إجراءات</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {loading ? (
                                <tr>
                                    <td colSpan={8} className="px-6 py-12 text-center text-gray-500">
                                        <div className="flex justify-center mb-4">
                                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                                        </div>
                                        جاري تحميل الطلبات...
                                    </td>
                                </tr>
                            ) : orders.length === 0 ? (
                                <tr>
                                    <td colSpan={8} className="px-6 py-12 text-center text-gray-500">
                                        لا توجد طلبات مطابقة للبحث
                                    </td>
                                </tr>
                            ) : (
                                orders.map((order) => (
                                    <tr key={order.id} className="hover:bg-gray-50">
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <input
                                                type="checkbox"
                                                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                                                checked={selectedOrders.includes(order.id)}
                                                onChange={() => toggleOrderSelection(order.id)}
                                            />
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <Link to={`/orders/${encodeURIComponent(String(order.id))}`} className="text-blue-600 hover:text-blue-900 font-medium">
                                                #{order.orderNumber || order.id.substring(0, 8)}
                                            </Link>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="text-sm font-medium text-gray-900">{order.customerName}</div>
                                            <div className="text-sm text-gray-500">{order.customerPhone}</div>
                                            <div className="text-xs text-gray-400 mt-1">
                                                {order.shippingAddress?.governorate} - {order.shippingAddress?.city}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                            {formatPrice(order.total)}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            {order.trackingNumber ? (
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-800 font-mono border border-gray-200">
                                                    {order.trackingNumber}
                                                </span>
                                            ) : (
                                                <span className="text-gray-400 text-xs">-</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${getStatusColor(order.status)}`}>
                                                {t(`orders.status.${order.status.toLowerCase()}`, order.status)}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                            {formatDate(order.createdAt)}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-center text-sm font-medium">
                                            <Link to={`/orders/${encodeURIComponent(String(order.id))}`} className="text-blue-600 hover:text-blue-900 ml-3">
                                                عرض
                                            </Link>
                                            {/* Can add single-track button here if needed */}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination placeholder, would normally use standard pagination component */}
                <div className="px-6 py-4 border-t border-gray-200 flex items-center justify-between">
                    <div className="text-sm text-gray-700">
                        إجمالي الطلبات: <span className="font-medium">{totalOrders}</span>
                    </div>
                    <div className="flex gap-2">
                        <button
                            disabled={page <= 1}
                            onClick={() => { setPage(p => p - 1); updateUrlParams({ page: String(page - 1) }) }}
                            className="px-3 py-1 border rounded disabled:opacity-50"
                        >
                            السابق
                        </button>
                        <span className="px-3 py-1">صفحة {page} من {totalPages}</span>
                        <button
                            disabled={page >= totalPages}
                            onClick={() => { setPage(p => p + 1); updateUrlParams({ page: String(page + 1) }) }}
                            className="px-3 py-1 border rounded disabled:opacity-50"
                        >
                            التالي
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TurboRecords;

import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import {
  UserIcon,
  PhoneIcon,
  MapPinIcon,
  ArrowPathIcon,
  SparklesIcon,
  ExclamationCircleIcon,
} from "@heroicons/react/24/outline";
import { OrderDetailsType, Government, Area } from "../types";
import { validateEgyptianPhone } from "../../../utils/validation";

interface CustomerInfoCardProps {
  order: OrderDetailsType;
  isEditing: boolean;
  editForm: any;
  setEditForm: (form: any) => void;
  governments: Government[];
  areas: Area[];
  loadingGovernments: boolean;
  loadingAreas: boolean;
  selectedGovernmentId: number | null;
  setSelectedGovernmentId: (id: number | null) => void;
  handleGovernmentChange: (id: number, name: string) => void;
  handleParseAddress: () => void;
  parsingAddress: boolean;
  parsedAddress: any;
}

const CustomerInfoCard: React.FC<CustomerInfoCardProps> = ({
  order,
  isEditing,
  editForm,
  setEditForm,
  governments,
  areas,
  loadingGovernments,
  loadingAreas,
  selectedGovernmentId,
  setSelectedGovernmentId,
  handleGovernmentChange,
  handleParseAddress,
  parsingAddress,
  parsedAddress,
}) => {
  const { t } = useTranslation();
  const [phoneErrors, setPhoneErrors] = useState<{
    main?: string;
    alternative?: string;
  }>({});

  const handlePhoneChange = (
    field: "customerPhone" | "alternativePhone",
    value: string,
  ) => {
    setEditForm({ ...editForm, [field]: value });

    if (value.trim() !== "") {
      const validation = validateEgyptianPhone(value);
      if (!validation.isValid) {
        setPhoneErrors((prev) => ({
          ...prev,
          [field === "customerPhone" ? "main" : "alternative"]:
            validation.error,
        }));
      } else {
        setPhoneErrors((prev) => {
          const newErrors = { ...prev };
          delete newErrors[field === "customerPhone" ? "main" : "alternative"];
          return newErrors;
        });
      }
    } else {
      setPhoneErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[field === "customerPhone" ? "main" : "alternative"];
        return newErrors;
      });
    }
  };

  return (
    <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6">
      <h3 className="text-lg font-medium text-gray-900 dark:text-gray-100 mb-4 flex items-center">
        <UserIcon className="h-5 w-5 text-gray-400 dark:text-gray-500 ml-2" />{" "}
        {t("orderDetails.customerInfo")}
        {order.customerRating && (
          <span
            className={`mr-2 px-2 py-0.5 rounded-full text-xs ${
              order.customerRating === "EXCELLENT"
                ? "bg-purple-100 dark:bg-purple-900/20 text-purple-800 dark:text-purple-400"
                : order.customerRating === "GOOD"
                  ? "bg-blue-100 dark:bg-blue-900/20 text-blue-800 dark:text-blue-400"
                  : order.customerRating === "BAD"
                    ? "bg-red-100 dark:bg-red-900/20 text-red-800 dark:text-red-400"
                    : "bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-300"
            }`}
          >
            {order.customerRating}
          </span>
        )}
      </h3>
      <div className="space-y-3">
        <div>
          <label className="text-sm font-medium text-gray-500 dark:text-gray-400 block mb-1">
            {t("orderDetails.nameLabel")}
          </label>
          {isEditing ? (
            <input
              type="text"
              value={editForm.customerName}
              onChange={(e) =>
                setEditForm({ ...editForm, customerName: e.target.value })
              }
              className="w-full border-gray-300 dark:border-gray-600 rounded-md text-sm dark:bg-gray-700 dark:text-gray-100"
            />
          ) : (
            <p className="text-gray-900 dark:text-gray-100">
              {order.customerName || t("orders.notSpecified")}
            </p>
          )}
        </div>
        <div>
          <label className="text-sm font-medium text-gray-500 dark:text-gray-400 block mb-1">
            {t("orderDetails.phoneLabel")}
          </label>
          {isEditing ? (
            <div>
              <input
                type="text"
                value={editForm.customerPhone}
                onChange={(e) =>
                  handlePhoneChange("customerPhone", e.target.value)
                }
                className={`w-full rounded-md text-sm dark:bg-gray-700 dark:text-gray-100 ${
                  phoneErrors.main
                    ? "border-red-500 dark:border-red-500 focus:ring-red-500 focus:border-red-500"
                    : "border-gray-300 dark:border-gray-600 focus:ring-blue-500 focus:border-blue-500"
                }`}
                dir="ltr"
                placeholder="01xxxxxxxxx"
              />
              {phoneErrors.main && (
                <div className="flex items-center gap-1 text-red-500 dark:text-red-400 text-xs mt-1">
                  <ExclamationCircleIcon className="w-3 h-3" />
                  <span>{phoneErrors.main}</span>
                </div>
              )}
            </div>
          ) : (
            <div
              className="flex items-center text-gray-900 dark:text-gray-100"
              dir="ltr"
            >
              <PhoneIcon className="w-4 h-4 text-gray-400 dark:text-gray-500 mr-2" />{" "}
              {order.customerPhone || t("orders.notSpecified")}
            </div>
          )}
        </div>
        <div>
          <label className="text-sm font-medium text-gray-500 dark:text-gray-400 block mb-1">
            {t("orderDetails.alternativePhone")}
          </label>
          {isEditing ? (
            <div>
              <input
                type="text"
                value={editForm.alternativePhone}
                onChange={(e) =>
                  handlePhoneChange("alternativePhone", e.target.value)
                }
                className={`w-full rounded-md text-sm dark:bg-gray-700 dark:text-gray-100 dark:placeholder-gray-400 ${
                  phoneErrors.alternative
                    ? "border-red-500 dark:border-red-500 focus:ring-red-500 focus:border-red-500"
                    : "border-gray-300 dark:border-gray-600 focus:ring-blue-500 focus:border-blue-500"
                }`}
                dir="ltr"
                placeholder={t("orderDetails.additionalPhone").toString()}
              />
              {phoneErrors.alternative && (
                <div className="flex items-center gap-1 text-red-500 dark:text-red-400 text-xs mt-1">
                  <ExclamationCircleIcon className="w-3 h-3" />
                  <span>{phoneErrors.alternative}</span>
                </div>
              )}
            </div>
          ) : order.alternativePhone ? (
            <div
              className="flex items-center text-gray-900 dark:text-gray-100"
              dir="ltr"
            >
              <PhoneIcon className="w-4 h-4 text-gray-400 dark:text-gray-500 mr-2" />{" "}
              {order.alternativePhone}
            </div>
          ) : (
            <p className="text-gray-400 dark:text-gray-500 text-sm">
              {t("orders.notSpecified")}
            </p>
          )}
        </div>
        <div>
          <label className="text-sm font-medium text-gray-500 dark:text-gray-400 block mb-1">
            {t("orderDetails.governorate")}
          </label>
          {isEditing ? (
            <select
              value={editForm.governorate}
              onChange={(e) => {
                const selectedGov = governments.find(
                  (g) => g.name === e.target.value,
                );
                if (selectedGov) {
                  handleGovernmentChange(selectedGov.id, selectedGov.name);
                } else {
                  setEditForm({ ...editForm, governorate: e.target.value });
                  setSelectedGovernmentId(null);
                }
              }}
              className="w-full border-gray-300 dark:border-gray-600 rounded-md text-sm dark:bg-gray-700 dark:text-gray-100"
              disabled={loadingGovernments}
            >
              <option value="">{t("orderDetails.selectGovernorate")}</option>
              {governments.map((gov) => (
                <option key={gov.id} value={gov.name}>
                  {gov.name}
                </option>
              ))}
            </select>
          ) : (
            <p className="text-gray-900 dark:text-gray-100">
              {(() => {
                const val =
                  order.governorate ||
                  (order.shippingAddress as any)?.governorate;
                if (!val) return t("orders.notSpecified");

                // Check if it's a numeric ID
                const govId = parseInt(String(val));
                if (!isNaN(govId) && governments) {
                  const found = governments.find((g) => g.id === govId);
                  if (found) return found.name;
                }

                // Clean numeric prefix if exists
                return String(val).replace(/^\d+:/, "").trim();
              })()}
            </p>
          )}
        </div>
        <div>
          <label className="text-sm font-medium text-gray-500 dark:text-gray-400 block mb-1">
            {t("orderDetails.areaCity")}
          </label>
          {isEditing ? (
            <select
              value={editForm.city}
              onChange={(e) =>
                setEditForm({ ...editForm, city: e.target.value })
              }
              className="w-full border-gray-300 dark:border-gray-600 rounded-md text-sm dark:bg-gray-700 dark:text-gray-100"
              disabled={
                loadingAreas || !selectedGovernmentId || areas.length === 0
              }
            >
              <option value="">
                {loadingAreas
                  ? t("orderDetails.loading")
                  : !selectedGovernmentId
                    ? t("orderDetails.selectGovernorateFirst")
                    : areas.length === 0
                      ? t("orderDetails.noAreasAvailable")
                      : t("orderDetails.selectArea")}
              </option>
              {areas.map((area) => (
                <option key={area.id} value={area.name}>
                  {area.name}
                </option>
              ))}
            </select>
          ) : (
            <p className="text-gray-900 dark:text-gray-100">
              {order.city
                ? String(order.city).replace(/^\d+:/, "").trim()
                : t("orders.notSpecified")}
            </p>
          )}
        </div>
        <div>
          <label className="text-sm font-medium text-gray-500 dark:text-gray-400 block mb-1">
            {t("orderDetails.detailedAddress")}
          </label>
          {isEditing ? (
            <div className="space-y-2">
              <textarea
                value={editForm.customerAddress}
                onChange={(e) =>
                  setEditForm({ ...editForm, customerAddress: e.target.value })
                }
                className="w-full border-gray-300 dark:border-gray-600 rounded-md text-sm dark:bg-gray-700 dark:text-gray-100 dark:placeholder-gray-400"
                rows={3}
                placeholder={t("orderDetails.addressPlaceholder").toString()}
              />
              <button
                onClick={handleParseAddress}
                disabled={parsingAddress || !editForm.customerAddress}
                className="flex items-center px-3 py-1.5 bg-purple-600 dark:bg-purple-500 text-white rounded-lg hover:bg-purple-700 dark:hover:bg-purple-600 disabled:opacity-50 text-xs"
              >
                {parsingAddress ? (
                  <>
                    <ArrowPathIcon className="w-3 h-3 ml-1 animate-spin" />
                    {t("orderDetails.parsing")}
                  </>
                ) : (
                  <>
                    <SparklesIcon className="w-3 h-3 ml-1" />
                    {t("orderDetails.parseAddressAI")}
                  </>
                )}
              </button>
              {parsedAddress && (
                <div className="text-xs text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/20 p-2 rounded">
                  {t("orderDetails.parsedSuccess", {
                    government: parsedAddress.government_name,
                    area: parsedAddress.area_name || t("orders.notSpecified"),
                  })}
                </div>
              )}
            </div>
          ) : (
            <div className="flex items-start text-gray-900 dark:text-gray-100">
              <MapPinIcon className="w-4 h-4 text-gray-400 dark:text-gray-500 ml-2 mt-1" />
              <span>
                {(() => {
                  if (!order.customerAddress) return t("orders.notSpecified");
                  if (
                    typeof order.customerAddress === "string" &&
                    order.customerAddress.trim().startsWith("{")
                  ) {
                    try {
                      const parsed = JSON.parse(order.customerAddress);
                      const parts = [];
                      if (parsed.street) parts.push(parsed.street);
                      if (parsed.building)
                        parts.push(`${t("orderDetails.building")}: ${parsed.building}`);
                      if (parsed.floor)
                        parts.push(`${t("orderDetails.floor")}: ${parsed.floor}`);
                      if (parsed.apartment)
                        parts.push(`${t("orderDetails.apartment")}: ${parsed.apartment}`);
                      if (parsed.city && parsed.city !== parsed.governorate)
                        parts.push(parsed.city);
                      if (parsed.governorate) parts.push(parsed.governorate);
                      return parts.length > 0
                        ? parts.join(", ")
                        : order.customerAddress;
                    } catch (e) {
                      return order.customerAddress;
                    }
                  }
                  return order.customerAddress;
                })()}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CustomerInfoCard;

import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import {
  CheckCircleIcon,
  ChatBubbleLeftIcon,
  CalendarIcon,
} from "@heroicons/react/24/outline";
import { useDateFormat } from "../../../hooks/useDateFormat";
import { OrderDetailsType } from "../types";

interface OrderActivityLogProps {
  order: OrderDetailsType;
  onAddNote: (note: string) => void;
  addingNote: boolean;
}

const OrderActivityLog: React.FC<OrderActivityLogProps> = ({
  order,
  onAddNote,
  addingNote,
}) => {
  const { t } = useTranslation();
  const { formatDateTime } = useDateFormat();
  const [note, setNote] = useState("");

  const handleAddNote = () => {
    if (!note.trim()) return;
    onAddNote(note);
    setNote("");
  };

  // Merge status history, notes, and scheduled info for timeline
  const activities = [
    ...(order.statusHistory || []).map((h: any) => ({
      type: "status",
      content: t("orderDetails.statusChangeTo", { status: h.status }),
      date: h.createdAt,
      author: h.updatedBy || t("orderDetails.system"),
      icon: CheckCircleIcon,
      color: "bg-blue-500",
    })),
    ...(order.orderNotes || []).map((n: any) => ({
      type: "note",
      content: n.content,
      date: n.createdAt,
      author:
        n.authorName ||
        (n.author
          ? `${n.author.firstName} ${n.author.lastName}`
          : t("orderDetails.user")),
      icon: ChatBubbleLeftIcon,
      color: "bg-gray-500",
    })),
    // Add scheduled order entry
    ...(order.isScheduled && order.scheduledDeliveryDate
      ? [
          {
            type: "scheduled",
            content: `تم جدولة الطلب للتسليم في ${new Date(
              order.scheduledDeliveryDate,
            ).toLocaleDateString("ar-EG", {
              year: "numeric",
              month: "long",
              day: "numeric",
            })} الساعة ${new Date(
              order.scheduledDeliveryDate,
            ).toLocaleTimeString("ar-EG", {
              hour: "2-digit",
              minute: "2-digit",
              hour12: true,
            })}${order.scheduledNotes ? `\n📝 ${order.scheduledNotes}` : ""}`,
            date: order.createdAt,
            author: "النظام",
            icon: CalendarIcon,
            color: "bg-orange-500",
          },
        ]
      : []),
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6">
      <h3 className="text-lg font-medium text-gray-900 dark:text-gray-100 mb-4">
        {t("orderDetails.activityLog")}
      </h3>

      {/* Add Note */}
      <div className="mb-6">
        <label htmlFor="comment" className="sr-only">
          {t("orderDetails.addNote")}
        </label>
        <div className="flex gap-2">
          <input
            type="text"
            name="comment"
            id="comment"
            className="shadow-sm focus:ring-blue-500 focus:border-blue-500 block w-full sm:text-sm border-gray-300 dark:border-gray-600 rounded-md dark:bg-gray-700 dark:text-white"
            placeholder={t("orderDetails.addNotePlaceholder")}
            value={note}
            onChange={(e) => setNote(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleAddNote()}
          />
          <button
            type="button"
            onClick={handleAddNote}
            disabled={addingNote || !note.trim()}
            className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50"
          >
            {addingNote ? t("orderDetails.adding") : t("orderDetails.add")}
          </button>
        </div>
      </div>

      <div className="flow-root">
        <ul className="-mb-8">
          {activities.map((activity, activityIdx) => (
            <li key={activityIdx}>
              <div className="relative pb-8">
                {activityIdx !== activities.length - 1 ? (
                  <span
                    className="absolute top-4 left-4 -ml-px h-full w-0.5 bg-gray-200 dark:bg-gray-700"
                    aria-hidden="true"
                  ></span>
                ) : null}
                <div className="relative flex space-x-3 space-x-reverse">
                  <div>
                    <span
                      className={`h-8 w-8 rounded-full flex items-center justify-center ring-8 ring-white dark:ring-gray-800 ${
                        activity.type === "status"
                          ? "bg-blue-500"
                          : activity.type === "scheduled"
                            ? "bg-orange-500"
                            : "bg-gray-500"
                      }`}
                    >
                      <activity.icon
                        className="h-5 w-5 text-white"
                        aria-hidden="true"
                      />
                    </span>
                  </div>
                  <div className="min-w-0 flex-1 pt-1.5 flex justify-between space-x-4 space-x-reverse">
                    <div>
                      <p className="text-sm text-gray-500 dark:text-gray-400 whitespace-pre-line">
                        {activity.content}{" "}
                        <span className="font-medium text-gray-900 dark:text-gray-100">
                          {activity.author}
                        </span>
                      </p>
                    </div>
                    <div className="text-right text-sm whitespace-nowrap text-gray-500 dark:text-gray-400">
                      <time dateTime={activity.date}>
                        {formatDateTime(activity.date)}
                      </time>
                    </div>
                  </div>
                </div>
              </div>
            </li>
          ))}
          {activities.length === 0 && (
            <li className="text-center text-gray-500 dark:text-gray-400 text-sm py-4">
              لا يوجد نشاط مسجل
            </li>
          )}
        </ul>
      </div>
    </div>
  );
};

export default OrderActivityLog;

import React from "react";
import { Link } from "react-router-dom";
import {
  UserIcon,
  ChatBubbleLeftRightIcon,
  GlobeAltIcon,
  UserGroupIcon,
  SparklesIcon,
  ClockIcon,
} from "@heroicons/react/24/outline";
import { useDateFormat } from "../../../hooks/useDateFormat";

interface OrderSourceCardProps {
  order: {
    conversationId?: string;
    conversation?: {
      id: string;
      channel: string;
    };
    orderSource?: string;
    sourceType?: string;
    extractionMethod?: string;
    affiliateId?: string;
    affiliate?: {
      id: string;
      affiliateCode?: string;
      status?: string;
      user?: {
        firstName: string;
        lastName: string;
        email: string;
      };
    };
    createdBy?: string;
    createdByName?: string;
    createdByUser?: {
      id: string;
      firstName: string;
      lastName: string;
      email: string;
    };
    createdAt: string;
    metadata?: any;
  };
}

const OrderSourceCard: React.FC<OrderSourceCardProps> = ({ order }) => {
  const { formatDateTime } = useDateFormat();

  const getChannelInfo = () => {
    if (!order.conversation && !order.conversationId) return null;

    const channel = order.conversation?.channel || "UNKNOWN";
    const channelMap: Record<
      string,
      { name: string; color: string; icon: string }
    > = {
      WHATSAPP: {
        name: "واتساب",
        color:
          "bg-green-100 text-green-800 dark:bg-green-900/20 dark:text-green-400",
        icon: "💬",
      },
      FACEBOOK: {
        name: "فيسبوك",
        color:
          "bg-blue-100 text-blue-800 dark:bg-blue-900/20 dark:text-blue-400",
        icon: "📘",
      },
      INSTAGRAM: {
        name: "انستجرام",
        color:
          "bg-pink-100 text-pink-800 dark:bg-pink-900/20 dark:text-pink-400",
        icon: "📷",
      },
      TELEGRAM: {
        name: "تيليجرام",
        color: "bg-sky-100 text-sky-800 dark:bg-sky-900/20 dark:text-sky-400",
        icon: "✈️",
      },
      WEBCHAT: {
        name: "الدردشة المباشرة",
        color:
          "bg-purple-100 text-purple-800 dark:bg-purple-900/20 dark:text-purple-400",
        icon: "💻",
      },
    };

    return (
      channelMap[channel] || {
        name: channel,
        color:
          "bg-gray-100 text-gray-800 dark:bg-gray-900/20 dark:text-gray-400",
        icon: "📱",
      }
    );
  };

  const getSourceTypeInfo = () => {
    // محاولة تحديد المصدر من البيانات المتاحة
    let sourceType = order.sourceType;

    // التحقق من extractionMethod أولاً
    if (
      order.extractionMethod === "manual" ||
      order.extractionMethod === "manual_order_modal"
    ) {
      sourceType = "manual";
    }
    // إذا لم يكن هناك sourceType أو كان unknown، نحاول التخمين
    else if (
      !sourceType ||
      sourceType === "unknown" ||
      (sourceType === "ai_conversation" && !order.conversationId)
    ) {
      if (order.conversationId) {
        sourceType = "ai_conversation";
      } else if (order.createdBy || order.createdByName) {
        sourceType = "manual";
      } else if (
        order.metadata?.source === "storefront" ||
        order.metadata?.isGuestOrder
      ) {
        sourceType = "storefront";
      } else {
        sourceType = "unknown";
      }
    }

    const sourceMap: Record<string, { name: string; icon: string }> = {
      ai_conversation: { name: "محادثة AI", icon: "🤖" },
      manual: { name: "طلب يدوي", icon: "✍️" },
      manual_order_modal: { name: "طلب يدوي", icon: "✍️" },
      storefront: { name: "المتجر الإلكتروني", icon: "🛒" },
      woocommerce: { name: "WooCommerce", icon: "🛍️" },
      api: { name: "API", icon: "🔌" },
      import: { name: "استيراد", icon: "📥" },
      unknown: { name: "غير محدد", icon: "❓" },
    };

    return sourceMap[sourceType] || { name: "غير محدد", icon: "📋" };
  };

  const channelInfo = getChannelInfo();
  const sourceTypeInfo = getSourceTypeInfo();

  return (
    <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6">
      <div className="flex items-center gap-3 mb-4">
        <div className="h-10 w-10 rounded-full bg-indigo-100 dark:bg-indigo-900/20 flex items-center justify-center">
          <SparklesIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
        </div>
        <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
          مصدر الطلب
        </h3>
      </div>

      <div className="space-y-4">
        {/* Created By User */}
        {(order.createdBy || order.createdByName || order.createdByUser) && (
          <div className="flex items-start gap-3 p-3 bg-indigo-50 dark:bg-indigo-900/10 rounded-lg border border-indigo-200 dark:border-indigo-800">
            <UserIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 mt-0.5 flex-shrink-0" />
            <div className="flex-1 min-w-0">
              <div className="text-xs text-gray-600 dark:text-gray-400 mb-1">
                أنشئ بواسطة
              </div>
              <div className="font-medium text-gray-900 dark:text-gray-100">
                {order.createdByUser
                  ? `${order.createdByUser.firstName} ${order.createdByUser.lastName}`
                  : order.createdByName || "موظف"}
              </div>
              {order.createdByUser?.email && (
                <div className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                  {order.createdByUser.email}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Channel Info */}
        {channelInfo && (
          <div className="flex items-start gap-3 p-3 bg-gray-50 dark:bg-gray-900/10 rounded-lg border border-gray-200 dark:border-gray-700">
            <ChatBubbleLeftRightIcon className="h-5 w-5 text-gray-600 dark:text-gray-400 mt-0.5 flex-shrink-0" />
            <div className="flex-1 min-w-0">
              <div className="text-xs text-gray-600 dark:text-gray-400 mb-1">
                القناة
              </div>
              <div className="flex items-center gap-2">
                <span
                  className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-sm font-medium ${channelInfo.color}`}
                >
                  <span>{channelInfo.icon}</span>
                  <span>{channelInfo.name}</span>
                </span>
                {order.conversationId && (
                  <Link
                    to={`/whatsapp?conversationId=${order.conversationId}`}
                    className="text-xs text-blue-600 dark:text-blue-400 hover:underline"
                  >
                    عرض المحادثة
                  </Link>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Source Type */}
        <div className="flex items-start gap-3 p-3 bg-gray-50 dark:bg-gray-900/10 rounded-lg border border-gray-200 dark:border-gray-700">
          <GlobeAltIcon className="h-5 w-5 text-gray-600 dark:text-gray-400 mt-0.5 flex-shrink-0" />
          <div className="flex-1 min-w-0">
            <div className="text-xs text-gray-600 dark:text-gray-400 mb-1">
              نوع المصدر
            </div>
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium text-gray-900 dark:text-gray-100">
                {sourceTypeInfo.icon} {sourceTypeInfo.name}
              </span>
              {order.extractionMethod &&
                order.extractionMethod !== "manual" && (
                  <span className="text-xs text-gray-500 dark:text-gray-400">
                    (
                    {order.extractionMethod === "ai_enhanced"
                      ? "AI محسّن"
                      : order.extractionMethod}
                    )
                  </span>
                )}
            </div>
          </div>
        </div>

        {/* Affiliate Info */}
        {order.affiliateId && order.affiliate && (
          <div className="flex items-start gap-3 p-3 bg-purple-50 dark:bg-purple-900/10 rounded-lg border border-purple-200 dark:border-purple-800">
            <UserGroupIcon className="h-5 w-5 text-purple-600 dark:text-purple-400 mt-0.5 flex-shrink-0" />
            <div className="flex-1 min-w-0">
              <div className="text-xs text-gray-600 dark:text-gray-400 mb-1">
                مسوق بالعمولة
              </div>
              <div className="font-medium text-gray-900 dark:text-gray-100">
                {order.affiliate.user
                  ? `${order.affiliate.user.firstName} ${order.affiliate.user.lastName}`
                  : "مسوق"}
              </div>
              {order.affiliate.affiliateCode && (
                <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                  كود: {order.affiliate.affiliateCode}
                </div>
              )}
              {order.affiliate.user?.email && (
                <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                  {order.affiliate.user.email}
                </div>
              )}
              <Link
                to={`/affiliates/${order.affiliateId}`}
                className="text-xs text-purple-600 dark:text-purple-400 hover:underline mt-1 inline-block"
              >
                عرض التفاصيل
              </Link>
            </div>
          </div>
        )}

        {/* Order Source Badge */}
        {order.orderSource && order.orderSource !== "REGULAR" && (
          <div className="flex items-start gap-3 p-3 bg-amber-50 dark:bg-amber-900/10 rounded-lg border border-amber-200 dark:border-amber-800">
            <SparklesIcon className="h-5 w-5 text-amber-600 dark:text-amber-400 mt-0.5 flex-shrink-0" />
            <div className="flex-1 min-w-0">
              <div className="text-xs text-gray-600 dark:text-gray-400 mb-1">
                نوع الطلب
              </div>
              <div className="text-sm font-medium text-gray-900 dark:text-gray-100">
                {order.orderSource === "AFFILIATE_REFERRAL" && "🔗 إحالة مسوق"}
                {order.orderSource === "AFFILIATE_DIRECT" &&
                  "👤 طلب مباشر من مسوق"}
              </div>
            </div>
          </div>
        )}

        {/* Creation Time */}
        <div className="flex items-start gap-3 p-3 bg-gray-50 dark:bg-gray-900/10 rounded-lg border border-gray-200 dark:border-gray-700">
          <ClockIcon className="h-5 w-5 text-gray-600 dark:text-gray-400 mt-0.5 flex-shrink-0" />
          <div className="flex-1 min-w-0">
            <div className="text-xs text-gray-600 dark:text-gray-400 mb-1">
              تاريخ الإنشاء
            </div>
            <div className="text-sm font-medium text-gray-900 dark:text-gray-100">
              {formatDateTime(order.createdAt)}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default OrderSourceCard;

import React, { useState, useEffect, useCallback, useMemo } from "react";
import {
  MagnifyingGlassIcon,
  XMarkIcon,
  PlusIcon,
  ArchiveBoxIcon,
} from "@heroicons/react/24/outline";
import { authService } from "../../../services/authService";
import { config } from "../../../config";
import { toast } from "react-hot-toast";
import { getPrimaryImageUrl } from "../../../utils/imageUrl";

interface ProductVariant {
  id: string;
  sku: string;
  price: number | string;
  stock: number;
  name: string;
  type?: string;
  color?: string;
  size?: string;
  image?: string;
  metadata?: string;
  attributeValues?: Record<string, string>;
}

interface Product {
  id: string;
  name: string;
  price: number;
  image: string;
  stock: number;
  sku: string;
  variants: ProductVariant[];
}

interface SimplifiedProductSelectionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onProductSelected: (product: Product, variant?: ProductVariant) => void;
}

// Helper function to parse variant metadata and extract attributeValues
const parseVariantAttributes = (
  variant: ProductVariant,
): Record<string, string> => {
  if (
    variant.attributeValues &&
    Object.keys(variant.attributeValues).length > 0
  ) {
    return variant.attributeValues;
  }

  if (variant.metadata) {
    try {
      const metadata =
        typeof variant.metadata === "string"
          ? JSON.parse(variant.metadata)
          : variant.metadata;

      // ✅ استخراج من attributes المستوردة من WooCommerce
      if (metadata.attributes && Array.isArray(metadata.attributes)) {
        const attrs: Record<string, string> = {};
        metadata.attributes.forEach((attr: any) => {
          if (attr.type === "color") {
            attrs["اللون"] = attr.option;
          } else if (attr.type === "size") {
            attrs["المقاس"] = attr.option;
          } else if (attr.type === "material") {
            attrs["المادة"] = attr.option;
          } else if (attr.type === "style") {
            attrs["النمط"] = attr.option;
          } else if (attr.option) {
            const attrName = attr.name || "خاصية";
            attrs[attrName] = attr.option;
          }
        });

        if (Object.keys(attrs).length > 0) {
          return attrs;
        }
      }

      if (
        metadata.attributeValues &&
        Object.keys(metadata.attributeValues).length > 0
      ) {
        return metadata.attributeValues;
      }
    } catch {}
  }

  if (variant.color || variant.size) {
    const attrs: Record<string, string> = {};
    if (variant.color) attrs["اللون"] = variant.color;
    if (variant.size) attrs["المقاس"] = variant.size;
    return attrs;
  }

  if (variant.name) {
    // محاولة استخراج من اسم المتغير بصيغة "اللون: أحمر | المقاس: 38"
    const pipePattern = /([^:]+):\s*([^|]+)/g;
    const attrs: Record<string, string> = {};
    let match;

    while ((match = pipePattern.exec(variant.name)) !== null) {
      if (match[1] && match[2]) {
        const key = match[1].trim();
        const value = match[2].trim();
        attrs[key] = value;
      }
    }

    if (Object.keys(attrs).length > 0) {
      return attrs;
    }

    const parts = variant.name.split(/\s*[-–]\s*/);
    if (parts.length >= 2 && parts[0] && parts[1]) {
      return {
        اللون: parts[0].trim(),
        المقاس: parts[1].trim(),
      };
    } else if (parts.length === 1 && parts[0] && variant.type) {
      const typeName =
        variant.type === "color"
          ? "اللون"
          : variant.type === "size"
            ? "المقاس"
            : variant.type;
      return { [typeName]: parts[0].trim() };
    }
  }

  return {};
};

// Helper function to extract unique attributes from variants
const extractAttributes = (
  variants: ProductVariant[],
): { name: string; values: string[] }[] => {
  const attributeMap: Record<string, Set<string>> = {};

  variants.forEach((variant) => {
    const attrs = parseVariantAttributes(variant);
    Object.entries(attrs).forEach(([key, value]) => {
      if (!attributeMap[key]) attributeMap[key] = new Set();
      if (value) attributeMap[key].add(value);
    });
  });

  return Object.entries(attributeMap)
    .filter(([_, values]) => values.size > 0)
    .map(([name, values]) => ({
      name,
      values: Array.from(values).sort(),
    }));
};

const SimplifiedProductSelectionModal: React.FC<
  SimplifiedProductSelectionModalProps
> = ({ isOpen, onClose, onProductSelected }) => {
  const [searchQuery, setSearchQuery] = useState("");
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedAttributes, setSelectedAttributes] = useState<
    Record<string, string>
  >({});

  const fetchProducts = useCallback(async (query: string = "") => {
    try {
      setLoading(true);
      const token = authService.getAccessToken();
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...(token && { Authorization: `Bearer ${token}` }),
      };

      const params = new URLSearchParams({
        page: "1",
        limit: "30",
      });

      const response = await fetch(
        `${config.apiUrl}/products?${params.toString()}`,
        { headers },
      );
      const data = await response.json();

      if (data.success && data.data) {
        const mappedProducts: Product[] = data.data.map((p: any) => {
          return {
            id: p.id,
            name: p.name,
            price: p.price,
            stock: p.stock,
            sku: p.sku,
            image: getPrimaryImageUrl(p.mainImage, p.image, p.images),
            variants: (p.variants || p.productVariants || []).map((v: any) => ({
              ...v,
              image: getPrimaryImageUrl(v.image, v.images),
            })),
          };
        });

        const filtered = query
          ? mappedProducts.filter(
              (p) =>
                String(p.name || "")
                  .toLowerCase()
                  .includes(query.toLowerCase()) ||
                String(p.sku || "")
                  .toLowerCase()
                  .includes(query.toLowerCase()),
            )
          : mappedProducts;

        setProducts(filtered);
      }
    } catch (error) {
      console.error("Error fetching products:", error);
      toast.error("فشل في جلب المنتجات");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (isOpen) {
      fetchProducts();
      setSearchQuery("");
      setSelectedProduct(null);
      setSelectedAttributes({});
    }
  }, [isOpen, fetchProducts]);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (searchQuery) fetchProducts(searchQuery);
    }, 300);
    return () => clearTimeout(timeoutId);
  }, [searchQuery, fetchProducts]);

  const handleProductClick = (product: Product) => {
    if (product.variants && product.variants.length > 0) {
      setSelectedProduct(product);
      setSelectedAttributes({});
    } else {
      // ✅ Check stock for products without variants
      if (product.stock !== undefined && product.stock <= 0) {
        toast.error("هذا المنتج غير متوفر في المخزون");
        return;
      }
      onProductSelected(product);
    }
  };

  const handleVariantSelect = (variant: ProductVariant) => {
    if (selectedProduct) {
      // ✅ Check stock
      if (variant.stock !== undefined && variant.stock <= 0) {
        toast.error("هذا المنتج غير متوفر في المخزون");
        return;
      }

      onProductSelected(selectedProduct, variant);
      setSelectedProduct(null);
      setSelectedAttributes({});
    }
  };

  const productAttributes = useMemo(() => {
    if (!selectedProduct) return [];
    return extractAttributes(selectedProduct.variants);
  }, [selectedProduct]);

  const filteredVariants = useMemo(() => {
    if (!selectedProduct) return [];
    return selectedProduct.variants.filter((variant) => {
      const variantAttrs = parseVariantAttributes(variant);
      return Object.entries(selectedAttributes).every(
        ([key, value]) => variantAttrs[key] === value,
      );
    });
  }, [selectedProduct, selectedAttributes]);

  const getAvailableValues = (attrName: string): string[] => {
    if (!selectedProduct) return [];
    const otherSelections = { ...selectedAttributes };
    delete otherSelections[attrName];

    const availableVariants = selectedProduct.variants.filter((variant) => {
      const variantAttrs = parseVariantAttributes(variant);
      return Object.entries(otherSelections).every(
        ([key, value]) => variantAttrs[key] === value,
      );
    });

    const values = new Set<string>();
    availableVariants.forEach((variant) => {
      const variantAttrs = parseVariantAttributes(variant);
      if (variantAttrs[attrName]) values.add(variantAttrs[attrName]);
    });

    return Array.from(values);
  };

  const allAttributesSelected =
    productAttributes.length > 0 &&
    productAttributes.every((attr) => selectedAttributes[attr.name]);

  const matchedVariant = useMemo(() => {
    if (!allAttributesSelected || filteredVariants.length !== 1) return null;
    return filteredVariants[0];
  }, [allAttributesSelected, filteredVariants]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="bg-white dark:bg-gray-800 w-full max-w-4xl rounded-2xl shadow-2xl flex flex-col overflow-hidden max-h-[90vh] animate-in zoom-in-95 duration-200 border border-gray-100 dark:border-gray-700">
        {/* Header */}
        <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-900/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-100 dark:bg-blue-900/40 rounded-lg text-blue-600 dark:text-blue-400">
              <PlusIcon className="w-5 h-5" />
            </div>
            <h2 className="font-bold text-lg text-gray-900 dark:text-gray-100">
              إضافة منتج للطلب
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full text-gray-400 dark:text-gray-500 transition-colors"
          >
            <XMarkIcon className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 flex overflow-hidden">
          {/* Left Side: Product List & Search */}
          <div className="flex-1 flex flex-col bg-white dark:bg-gray-800 border-l border-gray-100 dark:border-gray-700">
            <div className="p-4 bg-white dark:bg-gray-800 border-b border-gray-100 dark:border-gray-700">
              <div className="relative">
                <input
                  type="text"
                  autoFocus
                  placeholder="بحث باسم المنتج أو SKU..."
                  className="w-full pl-4 pr-11 py-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 dark:text-gray-100 outline-none transition-all"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
                <MagnifyingGlassIcon className="w-6 h-6 text-gray-400 absolute right-3.5 top-3" />
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
              {loading ? (
                <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
                  {[...Array(6)].map((_, i) => (
                    <div
                      key={i}
                      className="animate-pulse bg-gray-50 dark:bg-gray-900/50 rounded-xl h-48 border border-gray-100 dark:border-gray-800"
                    />
                  ))}
                </div>
              ) : products.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-gray-400 py-12">
                  <ArchiveBoxIcon className="w-16 h-16 mb-4 opacity-20" />
                  <p className="text-lg">لا توجد منتجات مطابقة</p>
                </div>
              ) : (
                <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
                  {products.map((product) => (
                    <div
                      key={product.id}
                      onClick={() => handleProductClick(product)}
                      className={`group relative flex flex-col bg-white dark:bg-gray-800 border-2 rounded-xl overflow-hidden transition-all cursor-pointer h-full ${
                        selectedProduct?.id === product.id
                          ? "border-blue-600 dark:border-blue-500 ring-2 ring-blue-50 dark:ring-blue-900/20"
                          : "border-gray-100 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-700 hover:shadow-md"
                      }`}
                    >
                      <div className="aspect-square bg-gray-50 dark:bg-gray-900 relative overflow-hidden">
                        {product.image ? (
                          <img
                            src={product.image}
                            alt={product.name}
                            className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-gray-200 dark:text-gray-700">
                            <ArchiveBoxIcon className="w-12 h-12" />
                          </div>
                        )}
                        {product.variants.length > 0 && (
                          <div className="absolute top-2 right-2 px-2 py-1 bg-blue-600/90 backdrop-blur-sm text-white text-[10px] font-bold rounded-lg shadow-sm">
                            خيارات
                          </div>
                        )}
                      </div>
                      <div className="p-3 bg-white dark:bg-gray-800">
                        <h3 className="text-sm font-semibold text-gray-900 dark:text-gray-100 line-clamp-1 mb-1">
                          {product.name}
                        </h3>
                        <div className="flex justify-between items-center">
                          <span className="text-blue-600 dark:text-blue-400 font-bold">
                            {product.price} ج.م
                          </span>
                          <div className="text-[10px] text-gray-400 truncate max-w-[60px]">
                            SKU: {product.sku || "N/A"}
                          </div>
                        </div>
                        {/* Stock indicator */}
                        {product.stock !== undefined && (
                          <div className="mt-1">
                            {product.stock <= 0 ? (
                              <span className="text-[10px] text-red-500 font-semibold">
                                نفذ من المخزون
                              </span>
                            ) : product.stock < 5 ? (
                              <span className="text-[10px] text-orange-500 font-semibold">
                                متبقي {product.stock}
                              </span>
                            ) : (
                              <span className="text-[10px] text-green-500 font-semibold">
                                متوفر
                              </span>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Right Side: Variant Selection (Dynamic) */}
          <div
            className={`w-80 flex flex-col bg-gray-50/50 dark:bg-gray-900/30 transition-all ${selectedProduct ? "translate-x-0" : "translate-x-full md:translate-x-0"}`}
          >
            {selectedProduct ? (
              <div className="flex-1 flex flex-col overflow-hidden">
                <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800">
                  <h3 className="font-bold text-gray-900 dark:text-gray-100 line-clamp-2 leading-snug">
                    {selectedProduct.name}
                  </h3>
                  <p className="text-blue-600 dark:text-blue-400 font-bold mt-1 text-lg">
                    {selectedProduct.price} ج.م
                  </p>
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
                  {productAttributes.length > 0 ? (
                    productAttributes.map((attr) => {
                      const availableValues = getAvailableValues(attr.name);
                      const isSelected = selectedAttributes[attr.name];

                      return (
                        <div key={attr.name} className="space-y-3">
                          <label className="text-sm font-bold text-gray-700 dark:text-gray-300 flex items-center justify-between">
                            {attr.name}
                            {isSelected && (
                              <span className="text-blue-600 dark:text-blue-400 text-xs px-2 py-0.5 bg-blue-50 dark:bg-blue-900/30 rounded-full">
                                {isSelected}
                              </span>
                            )}
                          </label>
                          <div className="flex flex-wrap gap-2">
                            {attr.values.map((value) => {
                              const isAvailable =
                                availableValues.includes(value);
                              const isActive =
                                selectedAttributes[attr.name] === value;

                              return (
                                <button
                                  key={value}
                                  onClick={() =>
                                    setSelectedAttributes((prev) => ({
                                      ...prev,
                                      [attr.name]: value,
                                    }))
                                  }
                                  disabled={!isAvailable}
                                  className={`px-3 py-2.5 min-w-[3rem] rounded-xl text-sm font-semibold transition-all border-2
                                                                        ${
                                                                          isActive
                                                                            ? "bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-200 dark:shadow-none"
                                                                            : isAvailable
                                                                              ? "bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-200 hover:border-blue-400 dark:hover:border-blue-500 hover:shadow-sm"
                                                                              : "bg-gray-100 dark:bg-gray-800 border-gray-100 dark:border-gray-800 text-gray-300 dark:text-gray-600 cursor-not-allowed line-through"
                                                                        }
                                                                    `}
                                >
                                  {value}
                                </button>
                              );
                            })}
                          </div>
                        </div>
                      );
                    })
                  ) : (
                    /* Fallback for simple variant list */
                    <div className="space-y-2">
                      {selectedProduct.variants.map((variant) => (
                        <button
                          key={variant.id}
                          onClick={() => handleVariantSelect(variant)}
                          disabled={
                            variant.stock !== undefined && variant.stock <= 0
                          }
                          className={`w-full text-right p-3 rounded-xl border-2 transition-all ${
                            variant.stock !== undefined && variant.stock <= 0
                              ? "border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 opacity-50 cursor-not-allowed"
                              : "border-gray-100 dark:border-gray-700 hover:border-blue-500 bg-white dark:bg-gray-800"
                          }`}
                        >
                          <div className="font-bold text-gray-900 dark:text-gray-100">
                            {variant.name}
                          </div>
                          <div className="flex justify-between items-center mt-1">
                            <span className="text-blue-600 dark:text-blue-400 text-sm font-semibold">
                              {variant.price &&
                              parseFloat(variant.price as any) > 0
                                ? `${variant.price} ج.م`
                                : `${product.price} ج.م`}
                            </span>
                            {variant.stock !== undefined &&
                              (variant.stock <= 0 ? (
                                <span className="text-[10px] text-red-500 font-semibold">
                                  نفذ
                                </span>
                              ) : variant.stock < 5 ? (
                                <span className="text-[10px] text-orange-500 font-semibold">
                                  متبقي {variant.stock}
                                </span>
                              ) : (
                                <span className="text-[10px] text-green-500 font-semibold">
                                  متوفر
                                </span>
                              ))}
                          </div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-700">
                  {matchedVariant ? (
                    <button
                      onClick={() => handleVariantSelect(matchedVariant)}
                      className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition-all shadow-lg shadow-blue-100 dark:shadow-none flex items-center justify-center gap-2"
                    >
                      <PlusIcon className="w-5 h-5" />
                      تأكيد الإضافة
                    </button>
                  ) : (
                    <div className="py-4 px-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl text-center border-2 border-dashed border-gray-200 dark:border-gray-700">
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {!allAttributesSelected
                          ? `يرجى اختيار ${productAttributes
                              .filter((a) => !selectedAttributes[a.name])
                              .map((a) => a.name)
                              .join(" و ")}`
                          : "المزيج المختار غير متوفر"}
                      </p>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-center p-8 grayscale opacity-50">
                <ArchiveBoxIcon className="w-16 h-16 mb-4 text-gray-300" />
                <h4 className="font-bold text-gray-400">اختر منتجاً</h4>
                <p className="text-sm text-gray-400 mt-2">
                  اختر منتجاً من القائمة الجانبية لتخصيص الخيارات
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SimplifiedProductSelectionModal;

