                  <span className="text-sm font-bold text-gray-900 dark:text-gray-100">
                    {formatPrice(order.shipping, order.currency)}
                  </span>
                </div>
                {shippingComparison && (
                  <div
                    className={`flex justify-between items-center pt-2 border-t ${
                      shippingComparison.difference > 0
