const resolveOrderImageSrc = (value: any): string => {
  if (!value) return "";

  if (typeof value === "string") {
    const trimmed = value.trim();

    if (
      (trimmed.startsWith("{") && trimmed.endsWith("}")) ||
      (trimmed.startsWith("[") && trimmed.endsWith("]"))
    ) {
      try {
        return resolveOrderImageSrc(JSON.parse(trimmed));
      } catch {
        return trimmed;
      }
    }

    return trimmed;
  }

  if (Array.isArray(value)) {
    return resolveOrderImageSrc(value[0]);
  }

  if (typeof value === "object") {
    if (typeof value.url === "string") return value.url;
    if (typeof value.src === "string") return value.src;
  }

  return "";
};

const looksLikeSizeValue = (value: unknown): boolean => {
  if (typeof value !== "string") return false;

  return /^(?:xxs|xs|s|m|l|xl|xxl|xxxl|2xl|3xl|4xl|5xl|free|one size|onesize|universal|small|medium|large|extra large|\d{1,3}(?:\.\d+)?)$/i.test(
    value.trim(),
  );
};

const normalizeVariantDisplayValues = (color: unknown, size: unknown) => {
  const normalizedColor = typeof color === "string" ? color.trim() : "";
  let normalizedSize = typeof size === "string" ? size.trim() : "";

  if (
    normalizedColor &&
    normalizedSize &&
    normalizedColor.toLowerCase() === normalizedSize.toLowerCase()
  ) {
    normalizedSize = "";
  }

  if (normalizedSize && !looksLikeSizeValue(normalizedSize)) {
    if (
      normalizedColor &&
      (normalizedColor.includes(normalizedSize) ||
        normalizedSize.includes(normalizedColor))
    ) {
      normalizedSize = "";
    }
  }

  return {
    color: normalizedColor,
    size: normalizedSize,
  };
};

export const useOrderDetails = (orderNumber: string | undefined) => {
  const { isLoading: authLoading, isAuthenticated } = useAuth();
  const encodedOrderNumber = orderNumber
    ? encodeURIComponent(String(orderNumber))
    : "";

  // Data State
  const [order, setOrder] = useState<OrderDetailsType | null>(null);
  const [loading, setLoading] = useState(true);
  const [updating, setUpdating] = useState(false);
  const [addingNote, setAddingNote] = useState(false);

  // Lookups State
  const [orderStatuses, setOrderStatuses] = useState<
    Array<{ code: string; name: string; nameEn?: string }>
  >([]);
  const [paymentStatuses, setPaymentStatuses] = useState<
    Array<{ code: string; name: string; nameEn?: string }>
  >([]);
  const [governments, setGovernments] = useState<Government[]>([]);
  const [areas, setAreas] = useState<Area[]>([]);
  const [loadingGovernments, setLoadingGovernments] = useState(false);
  const [loadingAreas, setLoadingAreas] = useState(false);

  // Edit Form State
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState({
    customerName: "",
    customerPhone: "",
    alternativePhone: "",
    customerAddress: "",
    city: "",
    governorate: "",
    notes: "",
    items: [] as any[],
    shipping: 0,
    tax: 0,
  });
  const [selectedGovernmentId, setSelectedGovernmentId] = useState<
    number | null
  >(null);
  const [orderNotes, setOrderNotes] = useState<any[]>([]);

  // --- Fetching Logic ---

  const fetchOrderStatuses = async () => {
    const fallbackStatuses = [
      { code: "PENDING", name: "قيد الانتظار", color: "#F59E0B" },
      { code: "DRAFT", name: "مسودة", color: "#9CA3AF" },
      { code: "CONFIRMED", name: "مؤكد", color: "#3B82F6" },
      { code: "ON_HOLD", name: "معلق", color: "#F97316" },
      { code: "PROCESSING", name: "قيد التجهيز", color: "#8B5CF6" },
      { code: "SHIPPED", name: "تم الشحن", color: "#06B6D4" },
      { code: "DELIVERED", name: "تم التسليم", color: "#10B981" },
      { code: "CANCELLED", name: "ملغي", color: "#EF4444" },
      { code: "DUPLICATE_ORDER", name: "طلب مكرر", color: "#F59E0B" },
      { code: "REFUNDED", name: "مسترد", color: "#6B7280" },
      { code: "PARTIALLY_REFUNDED", name: "مسترد جزئياً", color: "#9CA3AF" },
    ];

    try {
      const response = await apiClient.get("/order-status?statusType=order");
      console.log("📊 Order Statuses API Response:", response.data);
      if (response.data.success) {
        const apiStatuses = response.data.data || [];
        console.log("📊 Loaded statuses from API:", apiStatuses);

        // دمج الحالات من API مع الحالات الافتراضية
        // الحالات من API لها الأولوية
        const statusMap = new Map();

        // أضف الحالات الافتراضية أولاً
        fallbackStatuses.forEach((status: any) => {
          statusMap.set(status.code, status);
        });

        // اكتب فوقها بالحالات من API (تشمل الحالات المخصصة)
        apiStatuses.forEach((status) => {
          statusMap.set(status.code, status);
        });

        const mergedStatuses = Array.from(statusMap.values());
        console.log("📊 Merged statuses:", mergedStatuses.length, "statuses");
        setOrderStatuses(mergedStatuses);
      }
    } catch (error) {
      console.error("Error fetching order statuses:", error);
      setOrderStatuses(fallbackStatuses);
    }
  };

  const fetchPaymentStatuses = async () => {
    try {
      const response = await apiClient.get("/order-status?statusType=payment");
      if (response.data.success) {
        setPaymentStatuses(response.data.data || []);
      }
    } catch (error) {
      console.error("Error fetching payment statuses:", error);
      setPaymentStatuses([
        { code: "PENDING", name: "في انتظار الدفع" },
        { code: "COMPLETED", name: "مدفوع" },
        { code: "FAILED", name: "فشل الدفع" },
      ]);
    }
  };

  const fetchGovernments = async () => {
    try {
      setLoadingGovernments(true);
      const response = await apiClient.get("/turbo/governments");
      if (response.data.success && response.data.data?.governments) {
        setGovernments(response.data.data.governments);
      }
    } catch (error) {
      console.error("Failed to fetch governments:", error);
    } finally {
      setLoadingGovernments(false);
    }
  };

  const fetchAreas = async (governmentId: number) => {
    if (!governmentId) {
      setAreas([]);
      return;
    }
    try {
      setLoadingAreas(true);
      const response = await apiClient.get(`/turbo/areas/${governmentId}`);
      if (response.data.success && response.data.data.areas) {
        setAreas(response.data.data.areas);
      } else {
        setAreas([]);
      }
    } catch (error) {
      console.error("Failed to fetch areas:", error);
      setAreas([]);
    } finally {
      setLoadingAreas(false);
    }
  };

  const fetchOrderDetails = useCallback(async () => {
    if (!orderNumber) return;
    try {
      setLoading(true);
      let response;
      let data;

      console.log("🔍 [FRONTEND] Fetching order:", orderNumber);

      try {
        response = await apiClient.get(
          `/orders-new/simple/${encodedOrderNumber}`,
        );
        data = response.data;
        console.log("✅ [FRONTEND] Got response from /orders-new/simple");
      } catch (error: any) {
        console.log(
          "❌ [FRONTEND] Failed to fetch from /orders-new/simple:",
          error.response?.status,
        );
        if (error.response?.status === 404) {
          try {
            console.log("🔄 [FRONTEND] Trying /orders-enhanced endpoint...");
            response = await apiClient.get(
              `/orders-enhanced/${encodedOrderNumber}`,
            );
            data = response.data;
            console.log("✅ [FRONTEND] Got response from /orders-enhanced");
          } catch (error2) {
            console.log("❌ [FRONTEND] Failed to fetch from /orders-enhanced");
            // Error from enhanced endpoint, let it fall through to the outer catch
            throw error;
          }
        } else {
          // Other error from simple endpoint, let it fall through to the outer catch
          throw error;
        }
      }

      console.log("📦 [FRONTEND] API Response data:", data);

      if (data.success) {
        const simpleOrder = data.data;
        const wasViewed = Boolean(simpleOrder.isViewed);
        console.log("🔍 [FRONTEND] Order data received:", {
          orderNumber: simpleOrder.orderNumber,
          turboShipmentId: simpleOrder.turboShipmentId,
          turboTrackingNumber: simpleOrder.turboTrackingNumber,
          turboShipmentStatus: simpleOrder.turboShipmentStatus,
          turboLabelUrl: simpleOrder.turboLabelUrl,
          turboMetadata: simpleOrder.turboMetadata ? "exists" : "null",
        });

        if (!wasViewed) {
          try {
            await apiClient.post(`/orders-new/simple/${encodedOrderNumber}/viewed`);
          } catch (e) {
            console.error("Failed to mark order as viewed:", e);
          }
        }
        const shippingAddr =
          typeof simpleOrder.shippingAddress === "string"
            ? (() => {
                try {
                  return JSON.parse(simpleOrder.shippingAddress);
                } catch {
                  return {};
                }
              })()
            : simpleOrder.shippingAddress || {};

        const parsedSubtotal =
          parseFloat(simpleOrder.subtotal ?? simpleOrder.baseTotal ?? simpleOrder.total) || 0;
        const parsedTax = parseFloat(simpleOrder.tax) || 0;
        const parsedFinalTotal =
          parseFloat(simpleOrder.finalTotal ?? simpleOrder.total) || 0;
        const directShipping =
          parseFloat(simpleOrder.shipping ?? simpleOrder.shippingCost) || 0;
        const resolvedShipping =
          directShipping > 0
            ? directShipping
            : Math.max(0, parsedFinalTotal - parsedSubtotal - parsedTax);
        const resolvedTotal =
          parsedFinalTotal > parsedSubtotal || resolvedShipping > 0
            ? Math.max(parsedFinalTotal, parsedSubtotal + resolvedShipping + parsedTax)
            : parsedSubtotal + parsedTax;

        const enhancedOrder: OrderDetailsType = {
          ...simpleOrder,
          status: (simpleOrder.status || "").toUpperCase(),
          paymentStatus: (
            simpleOrder.paymentStatus ||
            (simpleOrder.metadata?.isGuestOrder ? "UNAVAILABLE" : "PENDING")
          ).toUpperCase() as any,
          items: (Array.isArray(simpleOrder.items)
            ? simpleOrder.items
            : []
          ).map((item: any) => {
            const price = parseFloat(item.price);
            const quantity = parseInt(item.quantity);
            const validPrice = !isNaN(price) && price >= 0 ? price : 0;
            const validQuantity =
              !isNaN(quantity) && quantity > 0 ? quantity : 1;

            // Parse Item Metadata
            let itemMetadata: any = {};
            try {
              itemMetadata =
                typeof item.metadata === "string"
                  ? JSON.parse(item.metadata)
                  : item.metadata || {};
            } catch (e) {
              console.warn("Failed to parse item metadata", e);
              itemMetadata = {};
            }

            // Parse Variant Metadata
            let variantMetadata: any = {};
            if (item.variant && item.variant.metadata) {
              try {
                variantMetadata =
                  typeof item.variant.metadata === "string"
                    ? JSON.parse(item.variant.metadata)
                    : item.variant.metadata;
              } catch (e) {
                variantMetadata = {};
              }
            }

            const extractedProductColor = (() => {
              // 1. Direct fields
              if (item.productColor) return item.productColor;
              if (item.color) return item.color;

              // 2. Metadata
              if (itemMetadata.color) return itemMetadata.color;
              if (itemMetadata.attributeValues?.["اللون"])
                return itemMetadata.attributeValues["اللون"];
              if (itemMetadata.attributeValues?.["color"])
                return itemMetadata.attributeValues["color"];

              // 3. Variant Relation
              if (item.variant) {
                if (variantMetadata.attributeValues?.["اللون"])
                  return variantMetadata.attributeValues["اللون"];
                if (variantMetadata.attributeValues?.["color"])
                  return variantMetadata.attributeValues["color"];

                if (item.variant.name) {
                  const name = item.variant.name;
                  if (item.variant.type === "color" && !name.includes("-"))
                    return name;
                }
              }

              return "";
            })();

            const extractedProductSize = (() => {
              // 1. Direct fields
              if (item.productSize) return item.productSize;
              if (item.size) return item.size;

              // 2. Metadata
              if (itemMetadata.size) return itemMetadata.size;
              if (itemMetadata.attributeValues?.["المقاس"])
                return itemMetadata.attributeValues["المقاس"];
              if (itemMetadata.attributeValues?.["size"])
                return itemMetadata.attributeValues["size"];

              // 3. Variant Relation
              if (item.variant) {
                if (variantMetadata.attributeValues?.["المقاس"])
                  return variantMetadata.attributeValues["المقاس"];
                if (variantMetadata.attributeValues?.["size"])
                  return variantMetadata.attributeValues["size"];

                if (item.variant.name) {
                  const parts = item.variant.name
                    .split(/[-/|xX]/)
                    .map((s: any) => s.trim());
                  const sizePart = parts.find((part: string) =>
                    looksLikeSizeValue(part),
                  );
                  if (sizePart) return sizePart;
                }
              }

              return "";
            })();

            const normalizedVariantValues = normalizeVariantDisplayValues(
              extractedProductColor,
              extractedProductSize,
            );

            return {
              id: item.id || Math.random().toString(),
              productId: item.productId || "",
              productName:
                item.name ||
                item.productName ||
                (item as any).local_product_id ||
                "منتج غير محدد",
              productColor: normalizedVariantValues.color,
              productSize: normalizedVariantValues.size,
              productImage:
                resolveOrderImageSrc(item.productImage) ||
                resolveOrderImageSrc(item.image) ||
                resolveOrderImageSrc(itemMetadata.image) ||
                resolveOrderImageSrc(itemMetadata.images) ||
                resolveOrderImageSrc(item.product?.images) ||
                "",
              price: validPrice,
              quantity: validQuantity,
              total: parseFloat(item.total) || validPrice * validQuantity,
              metadata: itemMetadata,
            };
          }),
          subtotal: parsedSubtotal,
          tax: parsedTax,
          shipping: resolvedShipping,
          total: resolvedTotal,
          currency: "EGP",
          isViewed: true,
        };

        setOrder(enhancedOrder);
        setOrderNotes(enhancedOrder.orderNotes || []);

        console.log("✅ [FRONTEND] Order set in state:", {
          orderNumber: enhancedOrder.orderNumber,
          turboShipmentId: enhancedOrder.turboShipmentId,
          turboTrackingNumber: enhancedOrder.turboTrackingNumber,
          turboShipmentStatus: enhancedOrder.turboShipmentStatus,
          turboLabelUrl: enhancedOrder.turboLabelUrl,
          turboMetadata: enhancedOrder.turboMetadata ? "exists" : "null",
        });

        // Initialize Edit Form
        setEditForm({
          customerName: enhancedOrder.customerName,
          customerPhone: enhancedOrder.customerPhone || "",
          alternativePhone: enhancedOrder.alternativePhone || "",
          customerAddress: enhancedOrder.customerAddress || "",
          city: enhancedOrder.city || "",
          governorate:
            enhancedOrder.governorate || shippingAddr.governorate || "",
          notes: enhancedOrder.notes || "",
          items: JSON.parse(JSON.stringify(enhancedOrder.items)),
          shipping: enhancedOrder.shipping || 0,
          tax: enhancedOrder.tax || 0,
        });

        // Logic to set selectedGovernmentId moved to separate useEffect
      }
    } catch (error) {
      console.error("Error fetching order:", error);
      toast.error("فشل تحميل تفاصيل الطلب");
    } finally {
      setLoading(false);
    }
  }, [orderNumber, encodedOrderNumber]);

  useEffect(() => {
    if (!orderNumber || authLoading || !isAuthenticated) return;
    fetchOrderDetails();
    fetchOrderStatuses();
    fetchPaymentStatuses();
  }, [orderNumber, authLoading, isAuthenticated, fetchOrderDetails]);

  useEffect(() => {
    if (
      !isEditing ||
      authLoading ||
      !isAuthenticated ||
      loadingGovernments ||
      governments.length > 0
    ) {
      return;
    }

    fetchGovernments();
  }, [
    isEditing,
    authLoading,
    isAuthenticated,
    loadingGovernments,
    governments.length,
  ]);

  // Re-run gov check when governments load if order is already loaded
  useEffect(() => {
    if (order && governments.length > 0 && !selectedGovernmentId) {
      const shippingAddr =
        typeof order.shippingAddress === "string"
          ? (() => {
              try {
                return JSON.parse(order.shippingAddress);
              } catch {
                return {};
              }
            })()
          : order.shippingAddress || {};
      const initialGovernorate =
        order.governorate || shippingAddr.governorate || order.city || ""; // Prioritize top-level governorate
      const foundGov = governments.find(
        (g) =>
          g.name === initialGovernorate ||
          g.id === parseInt(initialGovernorate) ||
          g.name === String(initialGovernorate).replace(/^\d+:/, "").trim(),
      );
      if (foundGov) {
        setSelectedGovernmentId(foundGov.id);
        fetchAreas(foundGov.id);
      }
    }
  }, [governments, order, selectedGovernmentId]);

  // --- Actions ---

  const handleGovernmentChange = (
    governmentId: number,
    governmentName: string,
  ) => {
    setSelectedGovernmentId(governmentId);
    setEditForm({ ...editForm, governorate: governmentName, city: "" });
    fetchAreas(governmentId);
  };

  const updateStatus = async (newStatus: string, notes: string) => {
    try {
      setUpdating(true);
      const response = await apiClient.post(
        `/orders-new/simple/${encodedOrderNumber}/status`,
        {
          status: newStatus,
          notes: notes,
        },
      );
      if (response.data.success) {
        setOrder((prev) =>
          prev ? { ...prev, status: newStatus.toUpperCase() as any } : null,
        );
        toast.success("تم تحديث حالة الطلب بنجاح");
        return true;
      }
      return false;
    } catch (error: any) {
      toast.error(error.response?.data?.message || "فشل تحديث الحالة");
      return false;
    } finally {
      setUpdating(false);
    }
  };

  const updatePaymentStatus = async (
    newPaymentStatus: string,
    notes: string,
  ) => {
    if (order?.metadata?.isGuestOrder) {
      toast.error("حالة الدفع غير متاحة حالياً لطلبات الضيوف");
      return false;
    }

    try {
      setUpdating(true);
      const response = await apiClient.post(
        `/orders-new/simple/${encodedOrderNumber}/payment-status`,
        {
          paymentStatus: newPaymentStatus.toUpperCase(),
          notes: notes,
        },
      );
      if (response.data.success) {
        setOrder((prev) =>
          prev
            ? { ...prev, paymentStatus: newPaymentStatus.toUpperCase() as any }
            : null,
        );
        toast.success("تم تحديث حالة الدفع بنجاح");
        return true;
      }
      return false;
    } catch (error: any) {
      toast.error(error.response?.data?.message || "فشل تحديث حالة الدفع");
      return false;
    } finally {
      setUpdating(false);
    }
  };

  const addNote = async (content: string) => {
    if (!content.trim()) return false;
    try {
      setAddingNote(true);
      const response = await apiClient.post(
        `/orders-new/simple/${encodedOrderNumber}/notes`,
        {
          content,
        },
      );
      if (response.data.success) {
        setOrderNotes((prev) => [response.data.data, ...prev]);
        toast.success("تم إضافة الملاحظة بنجاح");
        return true;
      }
      return false;
    } catch (error: any) {
      toast.error(error.response?.data?.message || "فشل إضافة الملاحظة");
      return false;
    } finally {
      setAddingNote(false);
    }
  };

  const saveChanges = async () => {
    if (!order) return false;

    // ✅ Validation: Check customer name
    const nameValidation = validateCustomerName(editForm.customerName);
    if (!nameValidation.isValid) {
      toast.error(nameValidation.error || "اسم العميل غير صحيح");
      return false;
    }

    // ✅ Validation: Check phone number
    if (editForm.customerPhone) {
      const phoneValidation = validateEgyptianPhone(editForm.customerPhone);
      if (!phoneValidation.isValid) {
        toast.error(phoneValidation.error || "رقم الهاتف غير صحيح");
        return false;
      }
    }

    // ✅ Validation: Check alternative phone if provided
    if (editForm.alternativePhone && editForm.alternativePhone.trim() !== "") {
      const altPhoneValidation = validateEgyptianPhone(
        editForm.alternativePhone,
      );
      if (!altPhoneValidation.isValid) {
        toast.error(`الرقم البديل: ${altPhoneValidation.error}`);
        return false;
      }
    }

    // ✅ Validation: Check items
    const itemsValidation = validateOrderItems(editForm.items);
    if (!itemsValidation.isValid) {
      toast.error(itemsValidation.error || "يوجد خطأ في المنتجات");
      return false;
    }

    setUpdating(true);
    try {
      // 1. Update Details
      const detailsBody = {
        customerName: editForm.customerName,
        customerPhone: editForm.customerPhone,
        alternativePhone: editForm.alternativePhone,
        shippingAddress: {
          address: editForm.customerAddress,
          city: editForm.city,
          governorate: editForm.governorate,
          country: "Egypt",
        },
        city: editForm.city,
        governorate: editForm.governorate,
        notes: editForm.notes,
      };

      await apiClient.put(
        `/orders-new/simple/${encodedOrderNumber}`,
        detailsBody,
      );

      // 2. Update Items
      const itemsToUpdate =
        editForm.items && editForm.items.length > 0
          ? editForm.items
          : order.items && order.items.length > 0
            ? order.items
            : [];

      if (itemsToUpdate && itemsToUpdate.length > 0) {
        const newItems = itemsToUpdate.map((item: any) => {
          const price =
            typeof item.price === "number" && !isNaN(item.price)
              ? item.price
              : parseFloat(item.price) || 0;
          const quantity =
            typeof item.quantity === "number" &&
            !isNaN(item.quantity) &&
            item.quantity > 0
              ? item.quantity
              : 1;
          return {
            productId: item.productId || item.id || "",
            productName: item.productName || item.name || "",
            productColor: item.productColor || null,
            productSize: item.productSize || null,
            price,
            quantity,
            total: price * quantity,
            metadata: item.metadata || {},
          };
        });

        const newSubtotal = newItems.reduce(
          (sum: number, item: any) => sum + (item.total || 0),
          0,
        );
        const currentShipping =
          typeof editForm.shipping === "number"
            ? editForm.shipping
            : parseFloat(editForm.shipping) || 0;
        const currentTax =
          typeof editForm.tax === "number"
            ? editForm.tax
            : parseFloat(editForm.tax) || 0;
        const newTotal = newSubtotal + currentShipping + currentTax;

        await apiClient.put(`/orders-new/simple/${encodedOrderNumber}/items`, {
          items: newItems,
          subtotal: newSubtotal,
          total: newTotal,
          tax: currentTax,
          shipping: currentShipping,
        });
      }

      await fetchOrderDetails();
      setIsEditing(false);
      toast.success("تم حفظ التغييرات بنجاح");
      return true;
    } catch (e: any) {
      console.error("Save error:", e);
      toast.error(e.response?.data?.message || "فشل حفظ التغييرات");
      return false;
    } finally {
      setUpdating(false);
    }
  };

  return {
    order,
    setOrder, // Exposed for real-time updates
    loading,
    updating,
    addingNote,
    // Lookups
    orderStatuses,
    paymentStatuses,
    governments,
    areas,
    loadingGovernments,
    loadingAreas,
    // Forms
    isEditing,
    setIsEditing,
    editForm,
    setEditForm,
    selectedGovernmentId,
    setSelectedGovernmentId,
    orderNotes,
    // Actions
    fetchOrderDetails,
    handleGovernmentChange,
    updateStatus,
    updatePaymentStatus,
    addNote,
    saveChanges,
  };
};

import { useState, useEffect } from "react";
import { apiClient } from "../../../services/apiClient";
import { socketService } from "../../../services/socketService";
import { useAuth } from "../../../hooks/useAuthSimple";
import { toast } from "react-hot-toast";
import { config } from "../../../config";
import tokenManager from "../../../utils/tokenManager";

export const useTurboShipping = (
  order: any,
  setOrder: (order: any) => void,
) => {
  const { user } = useAuth();

  const [turboLoading, setTurboLoading] = useState(false);
  const [turboTrackingData, setTurboTrackingData] = useState<any>(null);
  const [shippingComparison, setShippingComparison] = useState<{
    actualCost: number;
    customerCost: number;
    difference: number;
  } | null>(null);

  // Socket Listener for Real-time Updates
  useEffect(() => {
    if (!order?.id || !user?.companyId) return;

    if (!socketService.isConnected()) {
      socketService.connect();
    }

    const socket = socketService.getSocket();
    if (!socket) return;

    if (!socket.connected) {
      socket.once("connect", () => {
        if (user.companyId) {
          socket.emit("join_company_room", { companyId: user.companyId });
        }
      });
    }

    const handleTurboUpdate = (data: any) => {
      if (data.orderNumber === order.orderNumber || data.orderId === order.id) {
        // Update order state via the passed setter from useOrderDetails
        setOrder((prev: any) =>
          prev
            ? {
                ...prev,
                turboShipmentStatus: data.status,
                turboTrackingNumber:
                  data.trackingNumber || prev.turboTrackingNumber,
                updatedAt: new Date().toISOString(),
              }
            : null,
        );

        if (data.data) {
          setTurboTrackingData({
            status: data.status,
            currentLocation: data.data.currentLocation || data.data.location,
            estimatedDelivery:
              data.data.estimatedDelivery || data.data.expected_delivery,
            deliveredAt: data.data.deliveredAt || data.data.delivery_date,
            branch: data.data.branch || data.data.expected_branch,
            history: data.data.history || [],
          });
        }

        // Show notification
        if (data.status === "delivered") {
          toast.success("✅ تم تسليم الشحنة بنجاح!");
        } else if (data.status === "cancelled") {
          toast.error("❌ تم إلغاء الشحنة");
        } else if (data.status === "returned") {
          toast.error("🔄 تم إرجاع الشحنة");
        } else {
          toast("📦 تحديث حالة الشحنة: " + data.status, {
            icon: "🚚",
          });
        }
      }
    };

    socket.on("turbo_shipment_update", handleTurboUpdate);

    // Rejoin on reconnect
    const handleReconnect = () => {
      if (user?.companyId) {
        socket.emit("join_company_room", { companyId: user.companyId });
      }
    };
    socket.on("connect", handleReconnect);

    return () => {
      socket.off("turbo_shipment_update", handleTurboUpdate);
      socket.off("connect", handleReconnect);
    };
  }, [order?.id, order?.orderNumber, user?.companyId, setOrder]);

  // Actions

  const openPrintWindow = (htmlContent: string, title: string) => {
    const printWindow = window.open("", "_blank");

    if (!printWindow) {
      throw new Error("تعذر فتح نافذة جديدة للطباعة");
    }

    printWindow.document.write(htmlContent);
    printWindow.document.title = title;
    printWindow.document.close();
    printWindow.focus();

    setTimeout(() => {
      printWindow.print();
    }, 500);
  };

  const createShipment = async () => {
    if (!order?.id) return;
    setTurboLoading(true);
    try {
      const response = await apiClient.post(
        `/turbo/orders/${order.id}/shipment`,
      );
      if (response.data.success) {
        setOrder((prev: any) =>
          prev
            ? {
                ...prev,
                turboShipmentId: response.data.data.shipmentId,
                turboTrackingNumber: response.data.data.trackingNumber,
                turboShipmentStatus: response.data.data.status,
                turboLabelUrl: response.data.data.labelUrl,
              }
            : null,
        );
        toast.success(
          "تم إنشاء الشحنة بنجاح! رقم التتبع: " +
            response.data.data.trackingNumber,
        );
        return {
          success: true,
          trackingNumber: response.data.data.trackingNumber,
        };
      }
      return { success: false };
    } catch (error: any) {
      toast.error(error.response?.data?.error || "فشل إنشاء الشحنة");
      return { success: false, error: error.message };
    } finally {
      setTurboLoading(false);
    }
  };

  const getWaybill = async (useLocalGeneration = false) => {
    if (!order?.id) return null;
    setTurboLoading(true);
    try {
      const orderIdentifier = order.orderNumber || order.id;
      const baseWaybillUrl = `${config.apiUrl}/turbo/orders/${orderIdentifier}/waybill`;
      const authToken = tokenManager.getAccessToken();
      const headers: Record<string, string> = {};

      if (authToken) {
        headers.Authorization = `Bearer ${authToken}`;
      }

      toast.info("جاري تجهيز بوليصة Turbo...");

      if (!useLocalGeneration) {
        const pdfResponse = await fetch(baseWaybillUrl, {
          method: "GET",
          headers: {
            ...headers,
            Accept: "application/pdf",
          },
        });

        const contentType = pdfResponse.headers.get("content-type") || "";

        if (pdfResponse.ok && contentType.includes("application/pdf")) {
          const pdfBlob = await pdfResponse.blob();

          if (pdfBlob.size === 0) {
            throw new Error("ملف البوليصة فارغ");
          }

          const pdfUrl = window.URL.createObjectURL(pdfBlob);
          const pdfWindow = window.open(pdfUrl, "_blank");

          if (!pdfWindow) {
            const link = document.createElement("a");
            link.href = pdfUrl;
            link.download = `waybill-${orderIdentifier}.pdf`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
          }

          setTimeout(() => {
            window.URL.revokeObjectURL(pdfUrl);
          }, 60_000);

          toast.success("تم فتح بوليصة Turbo في نافذة جديدة");
          return true;
        }
      }

      const htmlResponse = await fetch(`${baseWaybillUrl}?format=html`, {
        method: "GET",
        headers: {
          ...headers,
          Accept: "text/html",
        },
      });

      if (!htmlResponse.ok) {
        const errorText = await htmlResponse.text();

        try {
          const errorData = JSON.parse(errorText);
          throw new Error(
            errorData.error || errorData.message || "فشل في تحميل بوليصة Turbo",
          );
        } catch (_parseError) {
          throw new Error(errorText || "فشل في تحميل بوليصة Turbo");
        }
      }

      const htmlContent = await htmlResponse.text();
      openPrintWindow(htmlContent, `Turbo Waybill - ${orderIdentifier}`);
      toast.success("تم فتح بوليصة Turbo للطباعة");
      return true;
    } catch (error: any) {
      console.error("❌ [WAYBILL] Error loading waybill:", error);
      toast.error(error.message || "فشل تحميل بوليصة Turbo");
      return null;
    } finally {
      setTurboLoading(false);
    }
  };

  const cancelShipment = async () => {
    if (!order?.id || !order?.turboShipmentId) return;

    // In a real UX, we'd use a custom modal. For now, we will rely on a browser confirm
    // or assume the UI button handles the "Are you sure?" step before calling this.
    // Given the task 'Replace window.alert/confirm', we should ideally assume the UI handles confirmation.
    // However, as a safeguard, we can revert to a safe check or just execute if the button is clicked.

    setTurboLoading(true);
    try {
      const response = await apiClient.post(`/turbo/orders/${order.id}/cancel`);
      if (response.data.success) {
        setOrder((prev: any) =>
          prev
            ? {
                ...prev,
                turboShipmentStatus: "cancelled",
              }
            : null,
        );
        toast.success("تم إلغاء الشحنة بنجاح");
        return true;
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || "فشل إلغاء الشحنة");
    } finally {
      setTurboLoading(false);
    }
    return false;
  };

  const calculateShipping = async (governorate: string, city: string) => {
    if (!governorate) {
      toast.error("يرجى تحديد المحافظة لحساب تكلفة الشحن");
      return;
    }
    setTurboLoading(true); // Reuse loading state or create specific one
    try {
      // Assuming endpoint accepts these params.
      // If the backend expects IDs, we might need to look them up.
      // Based on previous code, it likely takes IDs or Names.
      const response = await apiClient.post("/turbo/shipping/calculate", {
        weight: 1, // Default weight 1kg
        governorate: governorate,
        city: city,
        cod: order.total, // Cash on Delivery amount
      });

      if (response.data.success) {
        const cost = response.data.data.price || response.data.data.cost;
        if (cost) {
          setShippingComparison({
            actualCost: cost,
            customerCost: order.shipping,
            difference: cost - order.shipping,
          });
          toast.success(`تم حساب تكلفة الشحن: ${cost} ج.م`);
        }
      }
    } catch (error: any) {
      console.error("Shipping calc error:", error);
      toast.error("فشل حساب تكلفة الشحن");
    } finally {
      setTurboLoading(false);
    }
  };

  const fetchShippingComparison = async () => {
    // Logic to fetch comparison if needed
  };

  return {
    turboLoading,
    turboTrackingData,
    shippingComparison,
    createShipment,
    getWaybill,
    cancelShipment,
    calculateShipping,
    setTurboTrackingData,
  };
};

export interface OrderItem {
  id: string;
  productId?: string;
  productName: string;
  productColor?: string;
  productSize?: string;
  productDetails?: string;
  productImage?: string;
  price: number;
  quantity: number;
  total: number;
  metadata?: any;
}

export interface OrderNote {
  id: string;
  content: string;
  authorName: string;
  createdAt: string;
  author?: {
    firstName: string;
    lastName: string;
    avatar?: string;
  };
}

export interface OrderStatusHistory {
  status: string;
  notes?: string;
  createdAt: string;
  updatedBy?: string;
}

export interface OrderAttributionData {
  platform?: string;
  source?: string;
  medium?: string;
  campaignName?: string;
  campaignId?: string;
  adSetId?: string;
  adId?: string;
  content?: string;
  term?: string;
  landingPath?: string;
  referrer?: string;
  fbclid?: string;
  gclid?: string;
  ttclid?: string;
  fbc?: string;
  fbp?: string;
  capturedAt?: string;
  rawParams?: Record<string, string>;
}

export interface OrderDetailsType {
  id: string;
  orderNumber: string;
  customerName: string;
  customerEmail?: string;
  customerPhone?: string;
  alternativePhone?: string;
  customerAddress?: string;
  governorate?: string | number;
  city?: string;
  country?: string;
  shippingAddress?: string | object | any; // JSON string or parsed object
  status:
    | "PENDING"
    | "CONFIRMED"
    | "PROCESSING"
    | "SHIPPED"
    | "DELIVERED"
    | "CANCELLED"
    | "DUPLICATE_ORDER";
  paymentStatus: "PENDING" | "COMPLETED" | "FAILED" | "UNAVAILABLE";
  paymentMethod: string;
  items: OrderItem[];
  subtotal: number;
  tax: number;
  shipping: number;
  total: number;
  currency: string;
  confidence?: number;
  extractionMethod?: string;
  conversationId?: string;
  notes?: string;
  createdAt: string;
  updatedAt: string;
  isViewed?: boolean;
  statusHistory?: OrderStatusHistory[];
  customerRating?: string;
  customerSuccessScore?: number;

  // Order Source Fields
  sourceType?: string;
  orderSource?: string;
  createdBy?: string;
  createdByName?: string;
  createdByUser?: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
    avatar?: string;
  };
  conversation?: {
    id: string;
    channel: string;
  };
  affiliateId?: string;
  affiliate?: {
    id: string;
    affiliateCode?: string;
    status?: string;
    user?: {
      firstName: string;
      lastName: string;
      email: string;
    };
  };
  metadata?: any;

  // Turbo Shipping Fields
  turboShipmentId?: string;
  turboTrackingNumber?: string;
  turboShipmentStatus?: string;
  turboLabelUrl?: string;
  turboBranchId?: string;

  // Scheduled Order Fields
  isScheduled?: boolean;
  scheduledDeliveryDate?: string;
  scheduledNotes?: string;
  autoTransitionEnabled?: boolean;
  scheduledTransitionedAt?: string;

  orderNotes?: OrderNote[];

  // Confirmation & Assignment Fields
  confirmedAt?: string | null;
  confirmedBy?: string | null;
  confirmedByUser?: {
    id: string;
    firstName: string;
    lastName: string;
    email?: string;
    avatar?: string;
  } | null;
  confirmationNotes?: string | null;
  assignedTo?: string | null;
  assignedBy?: string | null;
  assignedAt?: string | null;
  assignmentStrategy?: string | null;
  assignedToUser?: {
    id: string;
    firstName: string;
    lastName: string;
    email?: string;
    avatar?: string;
  } | null;
  assignedByUser?: {
    id: string;
    firstName: string;
    lastName: string;
    email?: string;
    avatar?: string;
  } | null;
}

export interface Government {
  id: number;
  name: string;
}

export interface Area {
  id: number;
  name: string;
}

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowRightIcon,
  BuildingOffice2Icon,
  ShoppingCartIcon,
  CurrencyDollarIcon,
  CalendarDaysIcon,
  ClockIcon,
  CheckCircleIcon,
  XCircleIcon,
  TruckIcon,
  CubeIcon,
  UserIcon,
  PhoneIcon,
  MapPinIcon,
  EyeIcon,
  ArrowDownTrayIcon,
  FunnelIcon,
} from "@heroicons/react/24/outline";
import { toast } from "react-hot-toast";
import { apiClient } from "../../services/apiClient";

interface OrderItem {
  id: string;
  productName: string;
  productImage: string | null;
  quantity: number;
  price: number;
  total: number;
  sku: string | null;
}

interface Order {
  id: string;
  orderNumber: string;
  status: string;
  total: number;
  subtotal: number;
  shippingCost: number;
  discount: number;
  createdAt: string;
  customer: {
    name: string;
    phone: string;
    address: string;
    city: string;
  };
  items: OrderItem[];
  itemsCount: number;
}

interface CompanyDetails {
  id: string;
  name: string;
  logo: string | null;
}

interface OrdersResponse {
  success: boolean;
  data: {
    company: CompanyDetails;
    orders: Order[];
    stats: {
      totalOrders: number;
      totalRevenue: number;
      completedOrders: number;
      pendingOrders: number;
      cancelledOrders: number;
    };
    pagination: {
      page: number;
      limit: number;
      total: number;
      totalPages: number;
    };
  };
}

const statusColors: Record<
  string,
  { bg: string; text: string; label: string }
> = {
  PENDING: {
    bg: "bg-yellow-100 dark:bg-yellow-900/30",
    text: "text-yellow-800 dark:text-yellow-400",
    label: "قيد الانتظار",
  },
  CONFIRMED: {
    bg: "bg-blue-100 dark:bg-blue-900/30",
    text: "text-blue-800 dark:text-blue-400",
    label: "مؤكد",
  },
  PROCESSING: {
    bg: "bg-purple-100 dark:bg-purple-900/30",
    text: "text-purple-800 dark:text-purple-400",
    label: "جاري التجهيز",
  },
  SHIPPED: {
    bg: "bg-indigo-100 dark:bg-indigo-900/30",
    text: "text-indigo-800 dark:text-indigo-400",
    label: "تم الشحن",
  },
  DELIVERED: {
    bg: "bg-green-100 dark:bg-green-900/30",
    text: "text-green-800 dark:text-green-400",
    label: "تم التوصيل",
  },
  CANCELLED: {
    bg: "bg-red-100 dark:bg-red-900/30",
    text: "text-red-800 dark:text-red-400",
    label: "ملغي",
  },
  RETURNED: {
    bg: "bg-gray-100 dark:bg-gray-900/30",
    text: "text-gray-800 dark:text-gray-400",
    label: "مرتجع",
  },
};

const CompanyOrdersDetails: React.FC = () => {
  const { companyId } = useParams<{ companyId: string }>();
  const navigate = useNavigate();

  const [isLoading, setIsLoading] = useState(true);
  const [company, setCompany] = useState<CompanyDetails | null>(null);
  const [orders, setOrders] = useState<Order[]>([]);
  const [stats, setStats] = useState<OrdersResponse["data"]["stats"] | null>(
    null,
  );
  const [expandedOrder, setExpandedOrder] = useState<string | null>(null);

  // Filters
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [startDate, setStartDate] = useState(() => {
    const d = new Date();
    d.setFullYear(d.getFullYear() - 1); // Last year to get all orders
    return d.toISOString().split("T")[0];
  });
  const [endDate, setEndDate] = useState(
    () => new Date().toISOString().split("T")[0],
  );

  // Pagination
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);

  const getImageUrl = (path: string | null) => {
    if (!path) return null;
    if (path.startsWith("http")) return path;
    const backendUrl =
      import.meta.env["VITE_API_URL"]?.replace("/api/v1", "") ||
      "http://localhost:3007";
    return `${backendUrl}/${path.replace(/^\/+/, "")}`;
  };

  useEffect(() => {
    if (companyId) {
      fetchOrders();
    }
  }, [companyId, statusFilter, startDate, endDate, page]);

  const fetchOrders = async () => {
    try {
      setIsLoading(true);
      const response = await apiClient.get<OrdersResponse>(
        `owner/companies/${companyId}/orders`,
        {
          params: {
            startDate,
            endDate,
            status: statusFilter !== "all" ? statusFilter : undefined,
            page,
            limit: 20,
          },
        },
      );

      if (response.data.success) {
        setCompany(response.data.data.company);
        setOrders(response.data.data.orders);
        setStats(response.data.data.stats);
        setTotalPages(response.data.data.pagination.totalPages);
        setTotal(response.data.data.pagination.total);
      } else {
        toast.error("فشل تحميل البيانات");
      }
    } catch (error) {
      console.error("Failed to fetch orders:", error);
      toast.error("فشل تحميل الطلبات");
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = () => {
    if (orders.length === 0) {
      toast.error("لا توجد طلبات للتصدير");
      return;
    }

    const headers = [
      "رقم الطلب",
      "التاريخ",
      "العميل",
      "الهاتف",
      "المدينة",
      "الإجمالي",
      "الحالة",
      "المنتجات",
    ];
    const rows = orders.map((order) => [
      order.orderNumber,
      new Date(order.createdAt).toLocaleDateString("ar-EG"),
      order.customer.name,
      order.customer.phone,
      order.customer.city,
      order.total,
      statusColors[order.status]?.label || order.status,
      order.items.map((i) => `${i.productName} (${i.quantity})`).join(" | "),
    ]);

    const csvContent = [
      headers.join(","),
      ...rows.map((r) => r.map((cell) => `"${cell}"`).join(",")),
    ].join("\n");

    const blob = new Blob(["\ufeff" + csvContent], {
      type: "text/csv;charset=utf-8;",
    });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `orders-${company?.name}-${startDate}-to-${endDate}.csv`;
    link.click();

    toast.success("تم تصدير التقرير");
  };

  const toggleOrderExpand = (orderId: string) => {
    setExpandedOrder(expandedOrder === orderId ? null : orderId);
  };

  if (isLoading && !company) {
    return (
      <div
        className="p-6 min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center"
        dir="rtl"
      >
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-lg font-medium text-gray-600 dark:text-gray-400">
            جاري تحميل البيانات...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div
      className="p-6 space-y-6 bg-gray-50 dark:bg-gray-900 min-h-screen"
      dir="rtl"
    >
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate("/my-companies/reports")}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
            >
              <ArrowRightIcon className="w-5 h-5 text-gray-600 dark:text-gray-400" />
            </button>
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-gray-100 dark:bg-gray-700 rounded-lg flex items-center justify-center overflow-hidden">
                {company?.logo ? (
                  <img
                    src={getImageUrl(company.logo) || ""}
                    alt={company.name}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <BuildingOffice2Icon className="w-6 h-6 text-gray-400" />
                )}
              </div>
              <div>
                <h1 className="text-xl font-bold text-gray-800 dark:text-white">
                  {company?.name}
                </h1>
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  تفاصيل الطلبات والمنتجات
                </p>
              </div>
            </div>
          </div>
          <button
            onClick={handleExport}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition-colors"
          >
            <ArrowDownTrayIcon className="w-5 h-5" />
            تصدير
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
            <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm mb-1">
              <ShoppingCartIcon className="w-4 h-4" />
              إجمالي الطلبات
            </div>
            <p className="text-2xl font-bold text-gray-800 dark:text-white">
              {stats.totalOrders}
            </p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
            <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm mb-1">
              <CurrencyDollarIcon className="w-4 h-4" />
              الإيرادات
            </div>
            <p className="text-2xl font-bold text-green-600">
              {stats.totalRevenue.toLocaleString()} ج.م
            </p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
            <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm mb-1">
              <CheckCircleIcon className="w-4 h-4 text-green-500" />
              مكتمل
            </div>
            <p className="text-2xl font-bold text-gray-800 dark:text-white">
              {stats.completedOrders}
            </p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
            <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm mb-1">
              <ClockIcon className="w-4 h-4 text-yellow-500" />
              قيد الانتظار
            </div>
            <p className="text-2xl font-bold text-gray-800 dark:text-white">
              {stats.pendingOrders}
            </p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
            <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm mb-1">
              <XCircleIcon className="w-4 h-4 text-red-500" />
              ملغي
            </div>
            <p className="text-2xl font-bold text-gray-800 dark:text-white">
              {stats.cancelledOrders}
            </p>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2">
            <FunnelIcon className="w-5 h-5 text-gray-400" />
            <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
              فلترة:
            </span>
          </div>

          <div className="flex items-center gap-2">
            <label className="text-sm text-gray-600 dark:text-gray-400">
              من:
            </label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm dark:bg-gray-700 dark:text-white"
            />
          </div>

          <div className="flex items-center gap-2">
            <label className="text-sm text-gray-600 dark:text-gray-400">
              إلى:
            </label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm dark:bg-gray-700 dark:text-white"
            />
          </div>

          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm dark:bg-gray-700 dark:text-white"
          >
            <option value="all">كل الحالات</option>
            <option value="PENDING">قيد الانتظار</option>
            <option value="CONFIRMED">مؤكد</option>
            <option value="PROCESSING">جاري التجهيز</option>
            <option value="SHIPPED">تم الشحن</option>
            <option value="DELIVERED">تم التوصيل</option>
            <option value="CANCELLED">ملغي</option>
          </select>
        </div>
      </div>

      {/* Orders List */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700">
          <h2 className="text-lg font-bold text-gray-800 dark:text-white flex items-center gap-2">
            <ShoppingCartIcon className="w-5 h-5 text-blue-600" />
            الطلبات ({total})
          </h2>
        </div>

        {isLoading ? (
          <div className="p-8 text-center">
            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
          </div>
        ) : orders.length === 0 ? (
          <div className="p-8 text-center text-gray-500 dark:text-gray-400">
            <ShoppingCartIcon className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <p className="text-lg font-medium">لا توجد طلبات</p>
            <p className="text-sm">جرب تغيير الفلاتر</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-100 dark:divide-gray-700">
            {orders.map((order) => (
              <div
                key={order.id}
                className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
              >
                {/* Order Header */}
                <div
                  className="p-4 cursor-pointer"
                  onClick={() => toggleOrderExpand(order.id)}
                >
                  <div className="flex flex-wrap items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                      <div>
                        <p className="font-bold text-gray-800 dark:text-white">
                          #{order.orderNumber}
                        </p>
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          {new Date(order.createdAt).toLocaleDateString(
                            "ar-EG",
                            {
                              year: "numeric",
                              month: "short",
                              day: "numeric",
                              hour: "2-digit",
                              minute: "2-digit",
                            },
                          )}
                        </p>
                      </div>
                      <span
                        className={`px-2.5 py-1 rounded-full text-xs font-medium ${statusColors[order.status]?.bg} ${statusColors[order.status]?.text}`}
                      >
                        {statusColors[order.status]?.label || order.status}
                      </span>
                    </div>

                    <div className="flex items-center gap-6">
                      <div className="text-center">
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          المنتجات
                        </p>
                        <p className="font-bold text-gray-800 dark:text-white">
                          {order.itemsCount}
                        </p>
                      </div>
                      <div className="text-center">
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          الإجمالي
                        </p>
                        <p className="font-bold text-green-600">
                          {order.total.toLocaleString()} ج.م
                        </p>
                      </div>
                      <EyeIcon
                        className={`w-5 h-5 text-gray-400 transition-transform ${expandedOrder === order.id ? "rotate-180" : ""}`}
                      />
                    </div>
                  </div>
                </div>

                {/* Order Details (Expanded) */}
                {expandedOrder === order.id && (
                  <div className="px-4 pb-4 animate-fadeIn">
                    <div className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4 space-y-4">
                      {/* Customer Info */}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="flex items-center gap-2">
                          <UserIcon className="w-4 h-4 text-gray-400" />
                          <span className="text-sm text-gray-600 dark:text-gray-400">
                            العميل:
                          </span>
                          <span className="text-sm font-medium text-gray-800 dark:text-white">
                            {order.customer.name}
                          </span>
                        </div>
                        <div className="flex items-center gap-2">
                          <PhoneIcon className="w-4 h-4 text-gray-400" />
                          <span className="text-sm text-gray-600 dark:text-gray-400">
                            الهاتف:
                          </span>
                          <span
                            className="text-sm font-medium text-gray-800 dark:text-white"
                            dir="ltr"
                          >
                            {order.customer.phone}
                          </span>
                        </div>
                        <div className="flex items-center gap-2">
                          <MapPinIcon className="w-4 h-4 text-gray-400" />
                          <span className="text-sm text-gray-600 dark:text-gray-400">
                            المدينة:
                          </span>
                          <span className="text-sm font-medium text-gray-800 dark:text-white">
                            {order.customer.city}
                          </span>
                        </div>
                      </div>

                      {/* Products */}
                      <div>
                        <h4 className="text-sm font-bold text-gray-700 dark:text-gray-300 mb-2 flex items-center gap-2">
                          <CubeIcon className="w-4 h-4" />
                          المنتجات
                        </h4>
                        <div className="space-y-2">
                          {order.items.map((item) => (
                            <div
                              key={item.id}
                              className="flex items-center justify-between bg-white dark:bg-gray-800 p-3 rounded-lg"
                            >
                              <div className="flex items-center gap-3">
                                <div className="w-12 h-12 bg-gray-100 dark:bg-gray-700 rounded-lg overflow-hidden flex-shrink-0">
                                  {item.productImage ? (
                                    <img
                                      src={getImageUrl(item.productImage) || ""}
                                      alt={item.productName}
                                      className="w-full h-full object-cover"
                                    />
                                  ) : (
                                    <CubeIcon className="w-6 h-6 m-3 text-gray-400" />
                                  )}
                                </div>
                                <div>
                                  <p className="font-medium text-gray-800 dark:text-white">
                                    {item.productName}
                                  </p>
                                  {item.sku && (
                                    <p className="text-xs text-gray-500 dark:text-gray-400">
                                      SKU: {item.sku}
                                    </p>
                                  )}
                                </div>
                              </div>
                              <div className="text-left">
                                <p className="text-sm text-gray-600 dark:text-gray-400">
                                  {item.quantity} ×{" "}
                                  {item.price.toLocaleString()} ج.م
                                </p>
                                <p className="font-bold text-gray-800 dark:text-white">
                                  {item.total.toLocaleString()} ج.م
                                </p>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* Order Summary */}
                      <div className="border-t border-gray-200 dark:border-gray-700 pt-3">
                        <div className="flex justify-between text-sm mb-1">
                          <span className="text-gray-600 dark:text-gray-400">
                            المجموع الفرعي
                          </span>
                          <span className="text-gray-800 dark:text-white">
                            {order.subtotal.toLocaleString()} ج.م
                          </span>
                        </div>
                        {order.discount > 0 && (
                          <div className="flex justify-between text-sm mb-1">
                            <span className="text-gray-600 dark:text-gray-400">
                              الخصم
                            </span>
                            <span className="text-red-600">
                              -{order.discount.toLocaleString()} ج.م
                            </span>
                          </div>
                        )}
                        <div className="flex justify-between text-sm mb-1">
                          <span className="text-gray-600 dark:text-gray-400">
                            الشحن
                          </span>
                          <span className="text-gray-800 dark:text-white">
                            {order.shippingCost.toLocaleString()} ج.م
                          </span>
                        </div>
                        <div className="flex justify-between font-bold text-lg mt-2 pt-2 border-t border-gray-200 dark:border-gray-700">
                          <span className="text-gray-800 dark:text-white">
                            الإجمالي
                          </span>
                          <span className="text-green-600">
                            {order.total.toLocaleString()} ج.م
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="p-4 border-t border-gray-100 dark:border-gray-700 flex items-center justify-between">
            <p className="text-sm text-gray-600 dark:text-gray-400">
              صفحة {page} من {totalPages}
            </p>
            <div className="flex gap-2">
              <button
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
                className="px-3 py-1 bg-gray-100 dark:bg-gray-700 rounded-lg text-sm disabled:opacity-50"
              >
                السابق
              </button>
              <button
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page === totalPages}
                className="px-3 py-1 bg-gray-100 dark:bg-gray-700 rounded-lg text-sm disabled:opacity-50"
              >
                التالي
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default CompanyOrdersDetails;

