export default OwnerReports;

import React, { useState, useEffect, useCallback } from "react";
import {
  UsersIcon,
  BuildingOffice2Icon,
  MagnifyingGlassIcon,
  ArrowsRightLeftIcon,
  PlusIcon,
  EnvelopeIcon,
  PhoneIcon,
  TrashIcon,
} from "@heroicons/react/24/outline";
import { toast } from "react-hot-toast";
import { apiClient } from "../../services/apiClient";

interface UserCompanyRelation {
  company: {
    id: string;
    name: string;
    logo: string | null;
  };
  role: string;
  isActive: boolean;
}

interface UserData {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  phone: string | null;
  avatar: string | null;
  isActive: boolean;
  lastLoginAt: string | null;
  companies: UserCompanyRelation[];
}

const OwnerUsersManagement: React.FC = () => {
  const [isLoading, setIsLoading] = useState(true);
  const [users, setUsers] = useState<UserData[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCompanyFilter, setSelectedCompanyFilter] =
    useState<string>("all");
  const [deleteLoading, setDeleteLoading] = useState<string | null>(null);

  const getImageUrl = (path: string | null) => {
    if (!path) return null;
    if (path.startsWith("http")) return path;
    const backendUrl =
      import.meta.env["VITE_API_URL"]?.replace("/api/v1", "") ||
      "http://localhost:3007";
    return `${backendUrl}/${path.replace(/^\/+/, "")}`;
  };

  const fetchUsers = useCallback(async () => {
    try {
      setIsLoading(true);
      const response = await apiClient.get("owner/users");
      if (response.data.success) {
        setUsers(response.data.data.users);
      } else {
        toast.error(response.data.message || "فشل تحميل المستخدمين");
      }
    } catch (error: any) {
      console.error("Failed to fetch users", error);
      toast.error(error.response?.data?.message || "فشل تحميل المستخدمين");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  // تحديث تلقائي عند عودة التركيز للنافذة
  useEffect(() => {
    const onFocus = () => fetchUsers();
    window.addEventListener("focus", onFocus);
    return () => window.removeEventListener("focus", onFocus);
  }, [fetchUsers]);

  // Get unique companies for filter
  const allCompanies = React.useMemo(() => {
    const companiesMap = new Map<string, { id: string; name: string }>();
    users.forEach((user) => {
      user.companies.forEach((uc) => {
        if (!companiesMap.has(uc.company.id)) {
          companiesMap.set(uc.company.id, {
            id: uc.company.id,
            name: uc.company.name,
          });
        }
      });
    });
    return Array.from(companiesMap.values());
  }, [users]);

  // Filter users
  const filteredUsers = React.useMemo(() => {
    return users.filter((user) => {
      // Search filter
      const matchesSearch =
        searchQuery === "" ||
        user.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
        `${user.firstName} ${user.lastName}`
          .toLowerCase()
          .includes(searchQuery.toLowerCase());

      // Company filter
      const matchesCompany =
        selectedCompanyFilter === "all" ||
        user.companies.some((uc) => uc.company.id === selectedCompanyFilter);

      return matchesSearch && matchesCompany;
    });
  }, [users, searchQuery, selectedCompanyFilter]);

  const handleDeleteUser = async (user: UserData) => {
    const targetCompanies =
      selectedCompanyFilter !== "all"
        ? [selectedCompanyFilter]
        : user.companies.map((uc) => uc.company.id).filter(Boolean);
    if (!targetCompanies.length) {
      toast.error("لا يمكن تحديد الشركة لهذا المستخدم");
      return;
    }
    if (!window.confirm(`هل أنت متأكد من حذف ${user.firstName}؟`)) return;
    try {
      setDeleteLoading(user.id);
      let success = false;
      let lastMessage = "";
      let notFoundCount = 0;
      for (const companyId of targetCompanies) {
        try {
          const res = await apiClient.delete(`/company/${companyId}/users/${user.id}`);
          if (res.data?.status === "success" || res.data?.success) {
            success = true;
            break;
          }
          lastMessage = res.data?.message || lastMessage;
        } catch (err: any) {
          const status = err.response?.status;
          const msg = err.response?.data?.message || "خطأ في حذف المستخدم";
          lastMessage = msg;
          if (status === 404) {
            // محذوف مسبقاً في هذه الشركة
            notFoundCount += 1;
            continue;
          }
        }
      }

      if (success) {
        setUsers((prev) => prev.filter((u) => u.id !== user.id));
        toast.success("تم حذف المستخدم");
      } else if (notFoundCount === targetCompanies.length) {
        // كله 404 -> اعتبره محذوف وحدث القائمة
        setUsers((prev) => prev.filter((u) => u.id !== user.id));
        toast.success("المستخدم محذوف مسبقاً وتم تحديث القائمة");
      } else {
        toast.error(lastMessage || "فشل حذف المستخدم");
      }
      // تأكيد التزامن مع الخادم
      fetchUsers();
    } catch (err: any) {
      toast.error(err.response?.data?.message || "فشل حذف المستخدم");
    } finally {
      setDeleteLoading(null);
    }
  };

  const getRoleBadgeColor = (role: string) => {
    switch (role) {
      case "OWNER":
        return "bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400";
      case "COMPANY_ADMIN":
        return "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400";
      case "MANAGER":
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400";
      case "AGENT":
        return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300";
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300";
    }
  };

  const getRoleLabel = (role: string) => {
    switch (role) {
      case "OWNER":
        return "مالك";
      case "SUPER_ADMIN":
        return "مدير عام";
      case "COMPANY_ADMIN":
        return "مدير شركة";
      case "MANAGER":
        return "مدير";
      case "AGENT":
        return "موظف";
      default:
        return role;
    }
  };

  if (isLoading) {
    return (
      <div className="p-6 space-y-6 min-h-screen bg-gray-50 dark:bg-gray-900">
        <div className="h-20 bg-gray-200 dark:bg-gray-800 rounded-xl animate-pulse"></div>
        <div className="h-96 bg-gray-200 dark:bg-gray-800 rounded-xl animate-pulse"></div>
      </div>
    );
  }

  return (
    <div
      className="p-6 space-y-6 bg-gray-50 dark:bg-gray-900 min-h-screen"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-center bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
            <UsersIcon className="w-7 h-7 text-blue-600" />
            إدارة المستخدمين
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            إدارة مركزية لموظفي جميع شركاتك
          </p>
        </div>
        <div className="mt-4 md:mt-0 flex gap-3 items-center">
          {/* Search */}
          <div className="relative">
            <MagnifyingGlassIcon className="w-5 h-5 absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              placeholder="بحث..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="form-input pr-10 rounded-lg border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white"
            />
          </div>
          {/* Company Filter */}
          <select
            value={selectedCompanyFilter}
            onChange={(e) => setSelectedCompanyFilter(e.target.value)}
            className="form-select rounded-lg border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white"
          >
            <option value="all">كل الشركات</option>
            {allCompanies.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">
            إجمالي المستخدمين
          </p>
          <p className="text-2xl font-bold text-gray-800 dark:text-white mt-1">
            {users.length}
          </p>
        </div>
        <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">نشط</p>
          <p className="text-2xl font-bold text-green-600 mt-1">
            {users.filter((u) => u.isActive).length}
          </p>
        </div>
        <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">
            في أكثر من شركة
          </p>
          <p className="text-2xl font-bold text-blue-600 mt-1">
            {users.filter((u) => u.companies.length > 1).length}
          </p>
        </div>
      </div>

      {/* Users Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
            <thead className="bg-gray-50 dark:bg-gray-900">
              <tr>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                  المستخدم
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                  التواصل
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                  الشركات والأدوار
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                  الحالة
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                  إجراءات
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                  إجراءات
                </th>
              </tr>
            </thead>
            <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
              {filteredUsers.map((user) => (
                <tr
                  key={user.id}
                  className="hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900/30 rounded-full flex items-center justify-center">
                        {user.avatar ? (
                          <img
                            src={getImageUrl(user.avatar) || ""}
                            alt=""
                            className="w-full h-full object-cover rounded-full"
                          />
                        ) : (
                          <span className="text-blue-600 font-bold">
                            {user.firstName?.charAt(0)}
                            {user.lastName?.charAt(0)}
                          </span>
                        )}
                      </div>
                      <div>
                        <p className="font-medium text-gray-900 dark:text-white">
                          {user.firstName} {user.lastName}
                        </p>
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          {user.lastLoginAt
                            ? `آخر ظهور: ${new Date(user.lastLoginAt).toLocaleDateString("ar-EG")}`
                            : "لم يسجل دخول بعد"}
                        </p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="space-y-1">
                      <div className="flex items-center gap-1 text-sm text-gray-600 dark:text-gray-300">
                        <EnvelopeIcon className="w-4 h-4" />
                        <span>{user.email}</span>
                      </div>
                      {user.phone && (
                        <div className="flex items-center gap-1 text-sm text-gray-600 dark:text-gray-300">
                          <PhoneIcon className="w-4 h-4" />
                          <span>{user.phone}</span>
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-wrap gap-2">
                      {user.companies.map((uc, idx) => (
                        <div
                          key={idx}
                          className="flex items-center gap-1 bg-gray-50 dark:bg-gray-700 px-2 py-1 rounded-lg"
                        >
                          <div className="w-5 h-5 bg-gray-100 dark:bg-gray-600 rounded flex items-center justify-center overflow-hidden">
                            {uc.company.logo ? (
                              <img
                                src={getImageUrl(uc.company.logo) || ""}
                                alt=""
                                className="w-full h-full object-cover"
                              />
                            ) : (
                              <BuildingOffice2Icon className="w-3 h-3 text-gray-400" />
                            )}
                          </div>
                          <span className="text-xs text-gray-600 dark:text-gray-300">
                            {uc.company.name}
                          </span>
                          <span
                            className={`text-xs px-1.5 py-0.5 rounded ${getRoleBadgeColor(uc.role)}`}
                          >
                            {getRoleLabel(uc.role)}
                          </span>
                        </div>
                      ))}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className={`px-2 py-1 rounded-full text-xs font-medium ${
                        user.isActive
                          ? "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400"
                          : "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400"
                      }`}
                    >
                      {user.isActive ? "نشط" : "غير نشط"}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex gap-2">
                      <button
                        className="p-2 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg"
                        title="إضافة لشركة أخرى"
                      >
                        <PlusIcon className="w-4 h-4" />
                      </button>
                      <button
                        className="p-2 text-purple-600 hover:bg-purple-50 dark:hover:bg-purple-900/20 rounded-lg"
                        title="نقل بين الشركات"
                      >
                        <ArrowsRightLeftIcon className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleDeleteUser(user)}
                        disabled={deleteLoading === user.id}
                        className="p-2 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg disabled:opacity-60"
                        title="حذف المستخدم"
                      >
                        {deleteLoading === user.id ? (
                          <span className="text-xs">...</span>
                        ) : (
                          <TrashIcon className="w-4 h-4" />
                        )}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {filteredUsers.length === 0 && (
          <div className="p-8 text-center text-gray-500 dark:text-gray-400">
            لا يوجد مستخدمين مطابقين للبحث
          </div>
        )}
      </div>
    </div>
  );
};

export default OwnerUsersManagement;

import React, { useEffect, useState } from "react";
import {
  TableCellsIcon,
  ArrowDownTrayIcon,
  ArrowUpTrayIcon,
  ArrowPathIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import tokenManager from "../../utils/tokenManager";

interface PreviewRow {
  [key: string]: any;
}

const GoogleSheetsIntegration: React.FC = () => {
  const [sheetUrl, setSheetUrl] = useState("");
  const [columns, setColumns] = useState<string[]>([]);
  const [previewRows, setPreviewRows] = useState<PreviewRow[]>([]);
  const [totalRows, setTotalRows] = useState<number | null>(null);
  const [loadingPreview, setLoadingPreview] = useState(false);
  const [importing, setImporting] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [importResult, setImportResult] = useState<any>(null);
  const [importType, setImportType] = useState<"products" | "orders">("products");
  const [webhookUrl, setWebhookUrl] = useState("");
  const [webhookEnabled, setWebhookEnabled] = useState(false);
  const [loadingWebhook, setLoadingWebhook] = useState(false);
  const [savingWebhook, setSavingWebhook] = useState(false);

  const token = tokenManager.getAccessToken();
  const importTypeLabel = importType === "products" ? "المنتجات" : "الطلبات";
  const importUnitLabel = importType === "products" ? "منتج" : "طلب";
  const requirementsText =
    importType === "products"
      ? "الأعمدة المطلوبة: name, price, stock, sku, category, description, images."
      : "الأعمدة المطلوبة: customer_name أو customer_phone، مع items أو (product_name + product_price + quantity). صيغة items: اسم|سعر|كمية|SKU مفصولة بـ ;";

  const loadWebhookSettings = async () => {
    if (!token) return;
    setLoadingWebhook(true);
    try {
      const response = await fetch("/api/v1/settings/company", {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      const data = await response.json();
      if (data.success) {
        const settings = data.data?.settings || {};
        const savedUrl = settings.googleSheetsWebhookUrl || "";
        setWebhookUrl(savedUrl);
        setWebhookEnabled(settings.googleSheetsWebhookEnabled ?? !!savedUrl);
      }
    } catch (error: any) {
      toast.error(error.message || "فشل تحميل إعدادات الـ Webhook");
    } finally {
      setLoadingWebhook(false);
    }
  };

  const saveWebhookSettings = async () => {
    if (!token) return;
    setSavingWebhook(true);
    try {
      const response = await fetch("/api/v1/settings/company", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          settings: {
            googleSheetsWebhookUrl: webhookUrl.trim(),
            googleSheetsWebhookEnabled: webhookEnabled && !!webhookUrl.trim()
          }
        })
      });

      const data = await response.json();
      if (!data.success) {
        throw new Error(data.error || "تعذر حفظ الإعدادات");
      }

      toast.success("تم حفظ إعدادات الـ Webhook");
    } catch (error: any) {
      toast.error(error.message || "فشل حفظ إعدادات الـ Webhook");
    } finally {
      setSavingWebhook(false);
    }
  };

  useEffect(() => {
    loadWebhookSettings();
  }, [token]);

  const fetchPreview = async () => {
    if (!sheetUrl.trim()) {
      toast.error("أدخل رابط Google Sheets أولاً");
      return;
    }

    setLoadingPreview(true);
    setImportResult(null);
    try {
      const response = await fetch("/api/v1/google-sheets/preview", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({ sheetUrl: sheetUrl.trim() })
      });

      const data = await response.json();
      if (!data.success) {
        throw new Error(data.message || "فشل جلب البيانات");
      }

      setColumns(data.data.columns || []);
      setPreviewRows(data.data.sample || []);
      setTotalRows(data.data.totalRows || 0);
      toast.success("تم جلب المعاينة بنجاح");
    } catch (error: any) {
      toast.error(error.message || "حدث خطأ أثناء جلب البيانات");
      setColumns([]);
      setPreviewRows([]);
      setTotalRows(null);
    } finally {
      setLoadingPreview(false);
    }
  };

  const importSheet = async () => {
    if (!sheetUrl.trim()) {
      toast.error("أدخل رابط Google Sheets أولاً");
      return;
    }

    setImporting(true);
    try {
      const endpoint =
        importType === "products"
          ? "/api/v1/google-sheets/import/products"
          : "/api/v1/google-sheets/import/orders";
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({ sheetUrl: sheetUrl.trim() })
      });

      const data = await response.json();
      if (!data.success) {
        throw new Error(data.message || "فشل الاستيراد");
      }

      setImportResult(data.data);
      toast.success(`تم استيراد ${importTypeLabel} بنجاح`);
    } catch (error: any) {
      toast.error(error.message || "حدث خطأ أثناء الاستيراد");
    } finally {
      setImporting(false);
    }
  };

  const downloadFile = async (url: string, fallbackName: string) => {
    setExporting(true);
    try {
      const response = await fetch(url, {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });

      if (!response.ok) {
        throw new Error("تعذر تنزيل الملف");
      }

      const blob = await response.blob();
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = fallbackName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(link.href);
    } catch (error: any) {
      toast.error(error.message || "حدث خطأ أثناء التنزيل");
    } finally {
      setExporting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6">
        <div className="flex items-center gap-3 mb-4">
          <div className="p-2 bg-emerald-50 dark:bg-emerald-900/30 rounded-lg">
            <TableCellsIcon className="w-6 h-6 text-emerald-600 dark:text-emerald-400" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-gray-900 dark:text-white">
              الربط مع Google Sheets
            </h2>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              استيراد المنتجات أو الطلبات مباشرة من Google Sheets
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2 mb-4">
          <span className="text-sm text-gray-600 dark:text-gray-300">
            نوع الاستيراد:
          </span>
          <button
            onClick={() => setImportType("products")}
            className={`px-3 py-1.5 rounded-full text-sm border transition-colors ${
              importType === "products"
                ? "bg-emerald-600 text-white border-emerald-600"
                : "border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800"
            }`}
          >
            منتجات
          </button>
          <button
            onClick={() => setImportType("orders")}
            className={`px-3 py-1.5 rounded-full text-sm border transition-colors ${
              importType === "orders"
                ? "bg-blue-600 text-white border-blue-600"
                : "border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800"
            }`}
          >
            طلبات
          </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          <div className="lg:col-span-2">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              رابط Google Sheets
            </label>
            <input
              type="text"
              value={sheetUrl}
              onChange={(e) => setSheetUrl(e.target.value)}
              placeholder="https://docs.google.com/spreadsheets/d/..."
              className="w-full px-4 py-3 border border-gray-200 dark:border-gray-700 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-emerald-500"
              dir="ltr"
            />
          </div>
          <div className="flex flex-col gap-2 justify-end">
            <button
              onClick={fetchPreview}
              disabled={loadingPreview}
              className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 transition-colors"
            >
              {loadingPreview ? (
                <ArrowPathIcon className="w-5 h-5 animate-spin" />
              ) : (
                <ArrowDownTrayIcon className="w-5 h-5" />
              )}
              جلب المعاينة
            </button>
            <button
              onClick={importSheet}
              disabled={importing}
              className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
            >
              {importing ? (
                <ArrowPathIcon className="w-5 h-5 animate-spin" />
              ) : (
                <ArrowUpTrayIcon className="w-5 h-5" />
              )}
              استيراد {importTypeLabel}
            </button>
          </div>
        </div>

        <div className="mt-4 p-4 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-800 rounded-lg text-sm text-emerald-700 dark:text-emerald-300">
          شارك الملف كـ "Anyone with link" ثم ألصق الرابط هنا. {requirementsText}
        </div>

        {totalRows !== null && (
          <div className="mt-4 text-xs text-gray-500 dark:text-gray-400">
            إجمالي الصفوف في الملف: {totalRows}
          </div>
        )}

        {previewRows.length > 0 && (
          <div className="mt-6">
            <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
              معاينة البيانات
            </h3>
            <div className="overflow-x-auto border border-gray-200 dark:border-gray-700 rounded-lg">
              <table className="min-w-full text-sm text-right">
                <thead className="bg-gray-50 dark:bg-gray-900/50">
                  <tr>
                    {columns.map((col) => (
                      <th key={col} className="px-4 py-2 font-medium text-gray-600 dark:text-gray-300">
                        {col}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {previewRows.slice(0, 5).map((row, idx) => (
                    <tr key={idx} className="hover:bg-gray-50 dark:hover:bg-gray-800">
                      {columns.map((col) => (
                        <td key={col} className="px-4 py-2 text-gray-700 dark:text-gray-200">
                          {String(row[col] ?? "-")}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {importResult && (
          <div className="mt-6 p-4 rounded-lg border border-green-100 dark:border-green-800 bg-green-50 dark:bg-green-900/20">
            <div className="flex items-center gap-2 text-green-700 dark:text-green-300">
              <CheckCircleIcon className="w-5 h-5" />
              <span className="font-medium">نتيجة الاستيراد</span>
            </div>
            <div className="mt-2 text-sm text-gray-700 dark:text-gray-200">
              تم استيراد {importResult.imported} {importUnitLabel}، تخطي {importResult.skipped}، فشل {importResult.failed}.
            </div>
          </div>
        )}

        <div className="mt-6 p-4 border border-gray-200 dark:border-gray-700 rounded-lg">
          <div className="flex items-center justify-between gap-3 flex-wrap">
            <div>
              <h3 className="font-semibold text-gray-800 dark:text-gray-200">Webhook تلقائي للطلبات</h3>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                عند تفعيل الـ Webhook سيتم إرسال كل طلب جديد مباشرة إلى Google Sheets.
              </p>
            </div>
            <button
              onClick={saveWebhookSettings}
              disabled={savingWebhook || loadingWebhook}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
            >
              {savingWebhook ? "جارٍ الحفظ..." : "حفظ الإعدادات"}
            </button>
          </div>

          <div className="mt-4 grid grid-cols-1 lg:grid-cols-3 gap-4">
            <div className="lg:col-span-2">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                رابط Webhook (Google Apps Script)
              </label>
              <input
                type="text"
                value={webhookUrl}
                onChange={(e) => setWebhookUrl(e.target.value)}
                placeholder="https://script.google.com/macros/s/..."
                className="w-full px-4 py-3 border border-gray-200 dark:border-gray-700 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                dir="ltr"
              />
            </div>
            <div className="flex items-center gap-2">
              <input
                id="googleSheetsWebhookEnabled"
                type="checkbox"
                checked={webhookEnabled}
                onChange={(e) => setWebhookEnabled(e.target.checked)}
                className="h-4 w-4 text-blue-600 border-gray-300 rounded"
              />
              <label
                htmlFor="googleSheetsWebhookEnabled"
                className="text-sm text-gray-700 dark:text-gray-300"
              >
                تفعيل الإرسال التلقائي
              </label>
            </div>
          </div>

          <div className="mt-3 text-xs text-gray-500 dark:text-gray-400">
            سيتم إرسال بيانات الطلب بصيغة JSON وتشمل الحقول الأساسية وعناصر الطلب داخل `itemsText`.
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6">
        <div className="flex items-center gap-3 mb-4">
          <div className="p-2 bg-blue-50 dark:bg-blue-900/30 rounded-lg">
            <ArrowUpTrayIcon className="w-6 h-6 text-blue-600 dark:text-blue-400" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-gray-900 dark:text-white">
              التصدير إلى Google Sheets
            </h2>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              نزّل ملف CSV أو Excel وافتحه داخل Google Sheets
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="p-4 border border-gray-200 dark:border-gray-700 rounded-lg">
            <h3 className="font-semibold text-gray-800 dark:text-gray-200 mb-2">تصدير المنتجات</h3>
            <p className="text-xs text-gray-500 dark:text-gray-400 mb-3">
              ملف CSV جاهز يمكن فتحه مباشرة في Google Sheets.
            </p>
            <div className="flex flex-col gap-2">
              <button
                onClick={() => downloadFile("/api/v1/google-sheets/export/products", "products.csv")}
                disabled={exporting}
                className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50"
              >
                <ArrowDownTrayIcon className="w-4 h-4" />
                تنزيل CSV
              </button>
              <button
                onClick={() => downloadFile("/api/v1/google-sheets/template/products", "products-template.csv")}
                disabled={exporting}
                className="w-full flex items-center justify-center gap-2 px-4 py-2 border border-emerald-200 text-emerald-700 dark:text-emerald-300 rounded-lg hover:bg-emerald-50 dark:hover:bg-emerald-900/30"
              >
                <TableCellsIcon className="w-4 h-4" />
                تنزيل قالب جاهز
              </button>
            </div>
          </div>

          <div className="p-4 border border-gray-200 dark:border-gray-700 rounded-lg">
            <h3 className="font-semibold text-gray-800 dark:text-gray-200 mb-2">تصدير الطلبات</h3>
            <p className="text-xs text-gray-500 dark:text-gray-400 mb-3">
              يمكنك تنزيل CSV مباشرة أو Excel من النظام.
            </p>
            <div className="flex flex-col gap-2">
              <button
                onClick={() => downloadFile("/api/v1/google-sheets/export/orders", "orders.csv")}
                disabled={exporting}
                className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
              >
                <ArrowDownTrayIcon className="w-4 h-4" />
                تنزيل CSV
              </button>
              <button
                onClick={() => downloadFile("/api/v1/google-sheets/template/orders", "orders-template.csv")}
                disabled={exporting}
                className="w-full flex items-center justify-center gap-2 px-4 py-2 border border-blue-200 text-blue-700 dark:text-blue-300 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/30"
              >
                <TableCellsIcon className="w-4 h-4" />
                تنزيل قالب جاهز
              </button>
              <button
                onClick={() => downloadFile("/api/v1/orders/export", "orders.xlsx")}
                disabled={exporting}
                className="w-full flex items-center justify-center gap-2 px-4 py-2 border border-blue-200 text-blue-700 dark:text-blue-300 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/30"
              >
                <ArrowDownTrayIcon className="w-4 h-4" />
                تنزيل Excel
              </button>
            </div>
          </div>
        </div>

        {exporting && (
          <div className="mt-4 flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
            <ArrowPathIcon className="w-4 h-4 animate-spin" />
            جاري تجهيز الملف...
          </div>
        )}

        <div className="mt-4 flex items-center gap-2 text-xs text-amber-700 dark:text-amber-400">
          <ExclamationTriangleIcon className="w-4 h-4" />
          بعد التنزيل: افتح Google Sheets واختر "File → Import" ثم ارفع الملف.
        </div>
      </div>
    </div>
  );
};

export default GoogleSheetsIntegration;

import React, { useState, useEffect } from "react";
import {
    LinkIcon,
    MagnifyingGlassIcon,
    CheckCircleIcon,
    XCircleIcon,
    ArrowPathIcon,
    ShoppingCartIcon,
    ArrowDownTrayIcon,
    ArrowLeftIcon,
    ExclamationTriangleIcon,
    UsersIcon as UserGroupIcon,
    TrashIcon
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import tokenManager from "../../utils/tokenManager";

interface Connection {
    id: string;
    providerId: string;
    consumerId: string;
    allowProductPull: boolean;
    allowOrderPull: boolean;
    status: string;
    provider: {
        id: string;
        name: string;
        logo: string;
        email: string;
    };
}

interface Request {
    id: string;
    requesterId: string;
    message: string;
    createdAt: string;
    requester: {
        name: string;
        logo: string;
        email: string;
    };
}

interface InternalProduct {
    name: string;
    description: string;
    price: number;
    comparePrice: number | null;
    sku: string | null;
    stock: number;
    images: string[];
    category: string | null;
    internalId: string;
    source: string;
}

interface InternalOrder {
    id: string;
    orderNumber: string;
    total: number;
    status: string;
    createdAt: string;
    customer: {
        firstName: string;
        lastName: string;
        phone: string;
        email: string;
    };
    orderItems: Array<{
        product: {
            name: string;
            sku: string;
        };
        quantity: number;
        price: number;
    }>;
}

const InternalIntegrations: React.FC = () => {
    const [view, setView] = useState<"main" | "pull-products" | "pull-orders">("main");
    const [activeTab, setActiveTab] = useState<"connections" | "requests" | "find" | "consumers">("connections");
    const [connections, setConnections] = useState<Connection[]>([]);
    const [requests, setRequests] = useState<Request[]>([]);
    const [consumers, setConsumers] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [searchId, setSearchId] = useState("");
    const [searching, setSearching] = useState(false);

    // Pull Products State
    const [selectedProvider, setSelectedProvider] = useState<Connection | null>(null);
    const [providerProducts, setProviderProducts] = useState<InternalProduct[]>([]);
    const [selectedProductIndexes, setSelectedProductIndexes] = useState<Set<number>>(new Set());
    const [fetchingProducts, setFetchingProducts] = useState(false);
    const [importing, setImporting] = useState(false);

    // Response Loading State
    const [respondingIds, setRespondingIds] = useState<Set<string>>(new Set());

    // Pull Orders State
    const [availableOrders, setAvailableOrders] = useState<InternalOrder[]>([]);
    const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(new Set());
    const [fetchingOrders, setFetchingOrders] = useState(false);
    const [importingOrders, setImportingOrders] = useState(false);
    const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
        tokenManager.createAuthHeaders(additionalHeaders);

    const fetchActiveConnections = async () => {
        try {
            const resp = await fetch("/api/v1/company-connections/active", {
                headers: getAuthHeaders()
            });
            const data = await resp.json();
            if (data.success) setConnections(data.data);
        } catch (error) {
            toast.error("فشل جلب الشركات المتصلة");
        }
    };

    const fetchConsumers = async () => {
        try {
            const resp = await fetch("/api/v1/company-connections/consumers", {
                headers: getAuthHeaders()
            });
            const data = await resp.json();
            if (data.success) setConsumers(data.data);
        } catch (error) {
            toast.error("فشل جلب المشتركين");
        }
    };

    const fetchReceivedRequests = async () => {
        try {
            const resp = await fetch("/api/v1/company-connections/requests/received", {
                headers: getAuthHeaders()
            });
            const data = await resp.json();
            if (data.success) setRequests(data.data);
        } catch (error) {
            toast.error("فشل جلب طلبات الربط");
        }
    };

    const updatePermission = async (connectionId: string, permissions: any) => {
        try {
            const resp = await fetch(`/api/v1/company-connections/${connectionId}/permissions`, {
                method: "PUT",
                headers: getAuthHeaders({
                    "Content-Type": "application/json",
                }),
                body: JSON.stringify(permissions)
            });
            const data = await resp.json();
            if (data.success) {
                toast.success(data.message || "تم تحديث الصلاحيات");
                fetchConsumers();
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            toast.error("حدث خطأ أثناء تحديث الصلاحيات");
        }
    };

    useEffect(() => {
        fetchActiveConnections();
        fetchReceivedRequests();
        fetchConsumers();
    }, []);

    const handleRespond = async (id: string, status: "APPROVED" | "REJECTED") => {
        if (respondingIds.has(id)) return;
        setRespondingIds(prev => new Set(prev).add(id));
        try {
            const resp = await fetch(`/api/v1/company-connections/requests/${id}/respond`, {
                method: "PUT",
                headers: getAuthHeaders({
                    "Content-Type": "application/json",
                }),
                body: JSON.stringify({ status })
            });
            const data = await resp.json();
            if (data.success) {
                toast.success(data.message);
                fetchReceivedRequests();
                fetchActiveConnections();
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            toast.error("حدث خطأ أثناء معالجة الطلب");
        } finally {
            setRespondingIds(prev => {
                const next = new Set(prev);
                next.delete(id);
                return next;
            });
        }
    };

    const sendRequest = async () => {
        if (!searchId.trim()) return;
        setSearching(true);
        try {
            const resp = await fetch("/api/v1/company-connections/requests", {
                method: "POST",
                headers: getAuthHeaders({
                    "Content-Type": "application/json",
                }),
                body: JSON.stringify({ receiverId: searchId.trim(), message: "طلب ربط لسحب المنتجات" })
            });
            const data = await resp.json();
            if (data.success) {
                toast.success(data.message);
                setSearchId("");
                setActiveTab("connections");
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            toast.error("فشل إرسال طلب الربط");
        } finally {
            setSearching(false);
        }
    };

    const startPulling = async (conn: Connection) => {
        setSelectedProvider(conn);
        setFetchingProducts(true);
        setView("pull-products");
        try {
            const resp = await fetch(`/api/v1/company-connections/${conn.providerId}/products`, {
                headers: getAuthHeaders()
            });
            const data = await resp.json();
            if (data.success) {
                setProviderProducts(data.data.products);
                // Select all by default
                setSelectedProductIndexes(new Set(data.data.products.map((_: any, i: number) => i)));
            } else {
                toast.error(data.message);
                setView("main");
            }
        } catch (error) {
            toast.error("فشل جلب منتجات الشركة");
            setView("main");
        } finally {
            setFetchingProducts(false);
        }
    };

    const startPullingOrders = async (conn: Connection) => {
        setSelectedProvider(conn);
        setFetchingOrders(true);
        setView("pull-orders");
        try {
            const resp = await fetch(`/api/v1/affiliates/import/available-orders/${conn.providerId}`, {
                headers: getAuthHeaders()
            });
            const data = await resp.json();
            if (data.success) {
                setAvailableOrders(data.data);
                // Select all by default
                setSelectedOrderIds(new Set(data.data.map((o: any) => o.id)));
            } else {
                toast.error(data.message);
                setView("main");
            }
        } catch (error) {
            toast.error("فشل جلب طلبات الشركة");
            setView("main");
        } finally {
            setFetchingOrders(false);
        }
    };

    const deleteConnection = async (connectionId: string) => {
        if (!window.confirm("هل أنت متأكد من رغبتك في قطع الاتصال والارتباط بين الشركتين؟ ستتوقف جميع عمليات مزامنة البيانات.")) {
            return;
        }
        try {
            const resp = await fetch(`/api/v1/company-connections/${connectionId}`, {
                method: "DELETE",
                headers: getAuthHeaders()
            });
            const data = await resp.json();
            if (data.success) {
                toast.success(data.message || "تم قطع الاتصال بنجاح");
                fetchActiveConnections();
                fetchConsumers();
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            toast.error("فشل في قطع الاتصال");
        }
    };

    const toggleProduct = (index: number) => {
        const newSelected = new Set(selectedProductIndexes);
        if (newSelected.has(index)) newSelected.delete(index);
        else newSelected.add(index);
        setSelectedProductIndexes(newSelected);
    };

    const toggleOrder = (orderId: string) => {
        const newSelected = new Set(selectedOrderIds);
        if (newSelected.has(orderId)) newSelected.delete(orderId);
        else newSelected.add(orderId);
        setSelectedOrderIds(newSelected);
    };

    const handleImport = async () => {
        if (selectedProductIndexes.size === 0 || !selectedProvider) return;
        setImporting(true);
        try {
            const productsToImport = Array.from(selectedProductIndexes).map(idx => providerProducts[idx]);
            const resp = await fetch(`/api/v1/company-connections/${selectedProvider.providerId}/import`, {
                method: "POST",
                headers: getAuthHeaders({
                    "Content-Type": "application/json",
                }),
                body: JSON.stringify({ products: productsToImport })
            });
            const data = await resp.json();
            if (data.success) {
                toast.success(data.message);
                setView("main");
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            toast.error("فشل عملية الاستيراد");
        } finally {
            setImporting(false);
        }
    };

    const handleImportOrders = async () => {
        if (selectedOrderIds.size === 0 || !selectedProvider) return;
        setImportingOrders(true);
        try {
            const ordersToImport = availableOrders.filter(o => selectedOrderIds.has(o.id));
            const resp = await fetch(`/api/v1/affiliates/import/orders/${selectedProvider.providerId}`, {
                method: "POST",
                headers: getAuthHeaders({
                    "Content-Type": "application/json",
                }),
                body: JSON.stringify({ orders: ordersToImport })
            });
            const data = await resp.json();
            if (data.success) {
                toast.success(data.message);
                setView("main");
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            toast.error("فشل عملية استيراد الطلبات");
        } finally {
            setImportingOrders(false);
        }
    };

    if (view === "pull-products" && selectedProvider) {
        return (
            <div className="p-6 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setView("main")} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors">
                            <ArrowLeftIcon className="w-5 h-5 text-gray-500" />
                        </button>
                        <div>
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white">سحب المنتجات من {selectedProvider.provider.name}</h2>
                            <p className="text-sm text-gray-500">اختر المنتجات التي ترغب في استيرادها إلى متجرك</p>
                        </div>
                    </div>
                    <button
                        onClick={handleImport}
                        disabled={importing || selectedProductIndexes.size === 0}
                        className="flex items-center gap-2 px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 transition-colors"
                    >
                        {importing ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <ArrowDownTrayIcon className="w-5 h-5" />}
                        استيراد المحدد ({selectedProductIndexes.size})
                    </button>
                </div>

                {fetchingProducts ? (
                    <div className="py-20 text-center">
                        <ArrowPathIcon className="w-10 h-10 animate-spin text-blue-600 mx-auto mb-4" />
                        <p className="text-gray-500">جاري جلب المنتجات...</p>
                    </div>
                ) : providerProducts.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {providerProducts.map((product, idx) => {
                            const isSelected = selectedProductIndexes.has(idx);
                            return (
                                <div
                                    key={product.internalId}
                                    onClick={() => toggleProduct(idx)}
                                    className={`p-4 border-2 rounded-xl cursor-pointer transition-all ${isSelected ? "border-blue-500 bg-blue-50 dark:bg-blue-900/10" : "border-gray-100 dark:border-gray-700 hover:border-gray-200"
                                        }`}
                                >
                                    <div className="relative aspect-square rounded-lg overflow-hidden mb-3 bg-gray-50">
                                        <img
                                            src={product.images[0] || "https://placehold.co/200x200/png?text=No+Image"}
                                            alt={product.name}
                                            className="w-full h-full object-cover"
                                        />
                                        {isSelected && (
                                            <div className="absolute top-2 right-2 bg-blue-600 rounded-full p-1 shadow-lg">
                                                <CheckCircleIcon className="w-5 h-5 text-white" />
                                            </div>
                                        )}
                                    </div>
                                    <h4 className="font-semibold text-gray-900 dark:text-white mb-1 truncate">{product.name}</h4>
                                    <div className="flex justify-between items-center text-sm">
                                        <span className="text-blue-600 font-bold">{product.price} ج.م</span>
                                        <span className="text-gray-500">المخزون: {product.stock}</span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    <div className="py-20 text-center">
                        <ExclamationTriangleIcon className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                        <h3 className="text-lg font-medium text-gray-900 dark:text-white">لا توجد منتجات متاحة</h3>
                        <p className="text-gray-500">هذه الشركة ليس لديها منتجات نشطة حالياً.</p>
                    </div>
                )}
            </div>
        );
    }

    if (view === "pull-orders" && selectedProvider) {
        return (
            <div className="p-6 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setView("main")} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors">
                            <ArrowLeftIcon className="w-5 h-5 text-gray-500" />
                        </button>
                        <div>
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white">سحب الطلبات من {selectedProvider.provider.name}</h2>
                            <p className="text-sm text-gray-500">اختر الطلبات التي ترغب في استيرادها إلى نظامك</p>
                        </div>
                    </div>
                    <button
                        onClick={handleImportOrders}
                        disabled={importingOrders || selectedOrderIds.size === 0}
                        className="flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 transition-colors"
                    >
                        {importingOrders ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <ArrowDownTrayIcon className="w-5 h-5" />}
                        استيراد المحددة ({selectedOrderIds.size})
                    </button>
                </div>

                {fetchingOrders ? (
                    <div className="py-20 text-center">
                        <ArrowPathIcon className="w-10 h-10 animate-spin text-blue-600 mx-auto mb-4" />
                        <p className="text-gray-500">جاري جلب الطلبات...</p>
                    </div>
                ) : availableOrders.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {availableOrders.map((order: InternalOrder) => {
                            const isSelected = selectedOrderIds.has(order.id);
                            return (
                                <div
                                    key={order.id}
                                    onClick={() => toggleOrder(order.id)}
                                    className={`p-4 border-2 rounded-xl cursor-pointer transition-all ${isSelected ? "border-indigo-500 bg-indigo-50 dark:bg-indigo-900/10" : "border-gray-100 dark:border-gray-700 hover:border-gray-200"
                                        }`}
                                >
                                    <div className="flex justify-between items-start mb-3">
                                        <div>
                                            <h4 className="font-bold text-gray-900 dark:text-white">طلب #{order.orderNumber}</h4>
                                            <p className="text-xs text-gray-500">{new Date(order.createdAt).toLocaleString("ar-EG")}</p>
                                        </div>
                                        {isSelected && <CheckCircleIcon className="w-6 h-6 text-indigo-600" />}
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">العميل:</span>
                                            <span className="font-medium text-gray-900 dark:text-white">{order.customer.firstName} {order.customer.lastName}</span>
                                        </div>
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">الهاتف:</span>
                                            <span className="font-medium text-gray-900 dark:text-white">{order.customer.phone}</span>
                                        </div>
                                        <div className="flex justify-between text-sm pt-2 border-t border-gray-100 dark:border-gray-700">
                                            <span className="text-gray-500 font-bold">الإجمالي:</span>
