    );
};

export default InternalIntegrations;

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";

import {
  Users,
  Wallet,
  TrendingUp,
  Link as LinkIcon,
  Copy,
  Clock,
  DollarSign,
  AlertCircle,
} from "lucide-react";

import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import toast from "react-hot-toast";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { useAuth } from "../../hooks/useAuthSimple";
import {
  createStorageKey,
  getWithExpiry,
  setWithExpiry,
} from "../../utils/storage";

interface PartnerDashboardData {
  partner: {
    id: string;
    partnerCode: string;
    title: string;
    totalEarnings: number;
    pendingEarnings: number;
    totalPaid: number;
    status: string;
  };
  stats: {
    directReferralsCount: number;
    totalNetworkCount: number;
    activeCompaniesCount: number;
  };
  trends?: {
    earningsChange?: number;
    referralsChange?: number;
  };
  pagination?: {
    commissions: { page: number; pageSize: number; total: number };
    payouts: { page: number; pageSize: number; total: number };
    referrals: { page: number; pageSize: number; total: number };
  };
  recentCommissions: any[];
  recentPayouts: any[];
  referredCompanies: {
    name: string;
    status: string;
    createdAt: string;
  }[];
}

// Pure helpers (hoisted) to avoid TDZ issues inside hooks
const calcHasMore = (
  info?: { page: number; pageSize: number; total?: number },
  pageDataLength = 0,
) => {
  if (!info) return false;
  if (typeof info.total === "number" && info.total > 0) {
    return info.page * info.pageSize < info.total;
  }
  return pageDataLength === info.pageSize;
};

const calcTrendPercent = (current?: number, previous?: number) => {
  if (previous === undefined || previous === null) return undefined;
  if (previous === 0) return current && current > 0 ? 100 : 0;
  return Math.round(
    ((Number(current || 0) - Number(previous)) / Number(previous)) * 100,
  );
};

const PartnerDashboard: React.FC = () => {
  const { t } = useTranslation();
  const { user } = useAuth();
  const { formatPrice } = useCurrency();

  const [data, setData] = useState<PartnerDashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [payoutAmount, setPayoutAmount] = useState("");
  const [payoutMethod, setPayoutMethod] = useState("VODAFONE_CASH");
  const [payoutLoading, setPayoutLoading] = useState(false);
  const [commPage, setCommPage] = useState(1);
  const [payoutPage, setPayoutPage] = useState(1);
  const [refPage, setRefPage] = useState(1);
  const [pagination, setPagination] = useState({
    commissions: { page: 1, pageSize: 10, total: 0 },
    payouts: { page: 1, pageSize: 5, total: 0 },
    referrals: { page: 1, pageSize: 10, total: 0 },
  });
  const [hasMore, setHasMore] = useState({
    commissions: true,
    payouts: true,
    referrals: true,
  });
  const CACHE_TTL_MS = 60_000;

  const cacheKey = useMemo(() => {
    const companyId = user?.companyId || user?.company?.id || "unknown";
    return createStorageKey("partner-dashboard", companyId);
  }, [user?.company?.id, user?.companyId]);

  const fetchDashboardData = useCallback(
    async ({
      signal,
      background = false,
      appendSection,
      overridePages,
    }: {
      signal?: AbortSignal;
      background?: boolean;
      appendSection?: "commissions" | "payouts" | "referrals";
      overridePages?: {
        commPage?: number;
        payoutPage?: number;
        refPage?: number;
      };
    } = {}) => {
      let success = false;
      try {
        if (!background) {
          setLoading(true);
          setError(null);
        }

        const response = await apiClient.get("/platform-partners/dashboard", {
          signal,
          params: {
            commPage: overridePages?.commPage ?? commPage,
            commLimit: pagination.commissions.pageSize,
            payoutPage: overridePages?.payoutPage ?? payoutPage,
            payoutLimit: pagination.payouts.pageSize,
            refPage: overridePages?.refPage ?? refPage,
            refLimit: pagination.referrals.pageSize,
          },
        });
        if (response.data.status === "success") {
          const dash = response.data.data.dashboard;
          const nextPagination = dash.pagination || pagination;
          setPagination(nextPagination);
          setData((prev) => {
            const prevData = appendSection ? prev || dash : dash;
            const computedTrends = {
              earningsChange:
                dash.trends?.earningsChange ??
                calcTrendPercent(
                  dash.partner?.totalEarnings,
                  prev?.partner?.totalEarnings,
                ),
              referralsChange:
                dash.trends?.referralsChange ??
                calcTrendPercent(
                  dash.stats?.totalNetworkCount,
                  prev?.stats?.totalNetworkCount,
                ),
            };
            return {
              ...dash,
              trends: computedTrends,
              recentCommissions:
                appendSection === "commissions"
                  ? [
                      ...(prevData?.recentCommissions || []),
                      ...(dash.recentCommissions || []),
                    ]
                  : dash.recentCommissions,
              recentPayouts:
                appendSection === "payouts"
                  ? [
                      ...(prevData?.recentPayouts || []),
                      ...(dash.recentPayouts || []),
                    ]
                  : dash.recentPayouts,
              referredCompanies:
                appendSection === "referrals"
                  ? [
                      ...(prevData?.referredCompanies || []),
                      ...(dash.referredCompanies || []),
                    ]
                  : dash.referredCompanies,
            };
          });
          setHasMore({
            commissions: calcHasMore(
              nextPagination.commissions,
              dash.recentCommissions?.length || 0,
            ),
            payouts: calcHasMore(
              nextPagination.payouts,
              dash.recentPayouts?.length || 0,
            ),
            referrals: calcHasMore(
              nextPagination.referrals,
              dash.referredCompanies?.length || 0,
            ),
          });
          setWithExpiry(cacheKey, dash, CACHE_TTL_MS);
          setError(null);
          success = true;
        } else {
          const message =
            response.data.message ||
            t("platformPartner.dashboard.errors.fetchDashboard");
          setError(message);
          toast.error(message);
        }
      } catch (error: any) {
        const message =
          error.response?.data?.message ||
          t("platformPartner.dashboard.errors.fetchDashboard");
        setError(message);
        toast.error(message);
      } finally {
        if (!background) {
          setLoading(false);
        }
      }
      return success;
    },
    [cacheKey, t, commPage, payoutPage, refPage, pagination],
  );

  useEffect(() => {
    const controller = new AbortController();
    const initialPages = {
      commPage: 1,
      payoutPage: 1,
      refPage: 1,
    };
    setData(null);
    setCommPage(1);
    setPayoutPage(1);
    setRefPage(1);
    setPagination({
      commissions: { page: 1, pageSize: 10, total: 0 },
      payouts: { page: 1, pageSize: 5, total: 0 },
      referrals: { page: 1, pageSize: 10, total: 0 },
    });
    setHasMore({
      commissions: true,
      payouts: true,
      referrals: true,
    });
    setError(null);
    const cached = getWithExpiry<PartnerDashboardData>(cacheKey);

    if (cached) {
      setData(cached);
      setLoading(false);
      fetchDashboardData({
        signal: controller.signal,
        background: true,
        overridePages: initialPages,
      });
    } else {
      fetchDashboardData({
        signal: controller.signal,
        overridePages: initialPages,
      });
    }

    return () => controller.abort();
  }, [cacheKey]); // eslint-disable-line react-hooks/exhaustive-deps

  const copyToClipboard = (text: string, message: string) => {
    navigator.clipboard.writeText(text);
    toast.success(message);
  };

  const loadMoreCommissions = () => {
    if (!hasMore.commissions) return;
    const nextPage = commPage + 1;
    fetchDashboardData({
      background: true,
      appendSection: "commissions",
      overridePages: { commPage: nextPage },
    }).then((ok) => {
      if (ok) setCommPage(nextPage);
    });
  };

  const loadMorePayouts = () => {
    if (!hasMore.payouts) return;
    const nextPage = payoutPage + 1;
    fetchDashboardData({
      background: true,
      appendSection: "payouts",
      overridePages: { payoutPage: nextPage },
    }).then((ok) => {
      if (ok) setPayoutPage(nextPage);
    });
  };

  const loadMoreReferrals = () => {
    if (!hasMore.referrals) return;
    const nextPage = refPage + 1;
    fetchDashboardData({
      background: true,
      appendSection: "referrals",
      overridePages: { refPage: nextPage },
    }).then((ok) => {
      if (ok) setRefPage(nextPage);
    });
  };

  const statusLabel = (status: string) => {
    const map: Record<string, string> = {
      PAID: t("platformPartner.dashboard.status.paid") || "مدفوعة",
      CONFIRMED: t("platformPartner.dashboard.status.confirmed") || "مؤكدة",
      PENDING: t("platformPartner.dashboard.status.pending") || "معلّقة",
      PROCESSED: t("platformPartner.dashboard.status.processed") || "مُعالَجة",
      FAILED: t("platformPartner.dashboard.status.failed") || "فشلت",
      CANCELLED: t("platformPartner.dashboard.status.cancelled") || "مُلغاة",
      ACTIVE: t("platformPartner.dashboard.status.active") || "نشط",
      INACTIVE: t("platformPartner.dashboard.status.inactive") || "غير نشط",
    };
    return map[status] || status || "—";
  };

  const statusTone = (status: string) => {
    const key = status?.toUpperCase();
    if (["PAID", "CONFIRMED", "PROCESSED", "ACTIVE"].includes(key)) {
      return "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-200 border border-emerald-200/60 dark:border-emerald-800/60";
    }
    if (["PENDING"].includes(key)) {
      return "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-200 border border-amber-200/60 dark:border-amber-800/60";
    }
    return "bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-200 border border-red-200/60 dark:border-red-800/60";
  };

  const trendTone = (value?: number | null) => {
    if (value === null || value === undefined)
      return "bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300";
    if (value > 0)
      return "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-200";
    if (value < 0)
      return "bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-200";
    return "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-200";
  };

  const methodLabel = (method: string) => {
    const map: Record<string, string> = {
      VODAFONE_CASH:
        t("platformPartner.dashboard.payout.methods.vodafoneCash") ||
        "فودافون كاش",
      INSTAPAY:
        t("platformPartner.dashboard.payout.methods.instapay") || "إنستاباي",
      BANK_TRANSFER:
        t("platformPartner.dashboard.payout.methods.bankTransfer") ||
        "حوالة بنكية",
      CASH: t("platformPartner.dashboard.payout.methods.cash") || "نقدي",
      WALLET: t("platformPartner.dashboard.payout.methods.wallet") || "محفظة",
    };
    return map[method] || method || "—";
  };

  const handlePayoutRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!payoutAmount || Number(payoutAmount) <= 0) {
      toast.error(t("platformPartner.dashboard.payout.validAmountError"));
      return;
    }

    try {
      setPayoutLoading(true);
      const response = await apiClient.post(
        "/platform-partners/payout-request",
        {
          amount: Number(payoutAmount),
          method: payoutMethod,
          details: {}, // Can be expanded for bank details etc.
        },
      );

      if (response.data.status === "success") {
        toast.success(t("platformPartner.dashboard.payout.success"));
        setPayoutAmount("");
        fetchDashboardData({ background: true });
      }
    } catch (error: any) {
      toast.error(
        error.response?.data?.message ||
          t("platformPartner.dashboard.payout.error"),
      );
    } finally {
      setPayoutLoading(false);
    }
  };

  if (loading && !data) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="relative">
          <div className="h-16 w-16 rounded-full border-t-4 border-blue-500 animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center text-xs font-bold text-blue-500">
            {t("common.loading")}
          </div>
        </div>
      </div>
    );
  }

  if (error && !data) {
    return (
      <div className="p-8 text-center max-w-2xl mx-auto text-gray-500">
        {error}
      </div>
    );
  }

  if (!data?.partner && !loading) {
    return (
      <div className="p-8 text-center max-w-2xl mx-auto">
        <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-800 p-8 rounded-2xl shadow-sm">
          <AlertCircle className="w-16 h-16 text-blue-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold mb-2">
            {t("platformPartner.dashboard.accountRequired")}
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mb-6">
            {t("platformPartner.dashboard.accountRequiredDesc")}
          </p>
        </div>
      </div>
    );
  }

  if (!data || !data.partner) return null;

  const referralLink = `${window.location.origin}/auth/register?partner=${data.partner.partnerCode}`;
  const rankOrder = [
    "PARTNER",
    "SENIOR_PARTNER",
    "MASTER_PARTNER",
    "EXECUTIVE_PARTNER",
  ];
  const currentRankIndex = Math.max(0, rankOrder.indexOf(data.partner.title));
  const progressToTop = Math.min(
    100,
    Math.round(((currentRankIndex + 1) / rankOrder.length) * 100),
  );
  const nextRankKey = rankOrder[currentRankIndex + 1];
  const nextRankLabel = nextRankKey
    ? t(`platformPartner.dashboard.ranks.${nextRankKey}`) || nextRankKey
    : t("platformPartner.dashboard.rankings.maxRank") || "";

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500">
      {error && (
        <div className="p-4 border border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/30 rounded-xl text-red-700 dark:text-red-200 flex items-center justify-between">
          <span>{error}</span>
          <Button
            size="sm"
            variant="outline"
            onClick={() => fetchDashboardData()}
          >
            {t("common.retry") || "إعادة المحاولة"}
          </Button>
        </div>
      )}
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white dark:bg-gray-900 p-6 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-sm backdrop-blur-xl bg-opacity-80">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            {t("platformPartner.dashboard.hello")}{" "}
            <span className="text-blue-600">{data.partner.partnerCode}</span>
            <Badge className="bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300 border-none">
              {t(`platformPartner.dashboard.ranks.${data.partner.title}`)}
            </Badge>
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            {t("platformPartner.dashboard.subtitle")}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            onClick={() =>
              copyToClipboard(
                data.partner.partnerCode,
                t("platformPartner.dashboard.partnerCodeCopied"),
              )
            }
            className="gap-2"
          >
            <Copy className="w-4 h-4" /> {data.partner.partnerCode}
          </Button>
          <Button
            className="bg-blue-600 hover:bg-blue-700 gap-2"
            onClick={() =>
              copyToClipboard(
                referralLink,
                t("platformPartner.dashboard.referralLinkCopied"),
              )
            }
          >
            <LinkIcon className="w-4 h-4" />{" "}
            {t("platformPartner.dashboard.copyLink")}
          </Button>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          {
            label: t("platformPartner.dashboard.stats.totalEarnings"),
            value: formatPrice(data.partner.totalEarnings),
            icon: <Wallet className="text-emerald-500" />,
            trendValue: data.trends?.earningsChange,
          },
          {
            label: t("platformPartner.dashboard.stats.availablePayout"),
            value: formatPrice(data.partner.pendingEarnings),
            icon: <DollarSign className="text-blue-500" />,
            trendValue: null,
          },
          {
            label: t("platformPartner.dashboard.stats.directReferrals"),
            value: data.stats.directReferralsCount,
            icon: <Users className="text-purple-500" />,
            trendValue: data.trends?.referralsChange,
          },
          {
            label: t("platformPartner.dashboard.stats.totalNetwork"),
            value: data.stats.totalNetworkCount,
            icon: <TrendingUp className="text-orange-500" />,
            trendValue: data.trends?.referralsChange,
          },
        ].map((stat, i) => (
          <motion.div
            key={i}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.1 }}
          >
            <Card className="border-none shadow-md bg-white dark:bg-gray-900 hover:shadow-xl transition-shadow duration-300">
              <CardContent className="p-6">
                <div className="flex justify-between items-start">
                  <div className="p-3 bg-gray-50 dark:bg-gray-800 rounded-xl">
                    {stat.icon}
                  </div>
                  <Badge
                    variant="secondary"
                    className={trendTone(stat.trendValue)}
                  >
                    {stat.trendValue === null || stat.trendValue === undefined
                      ? "—"
                      : `${stat.trendValue > 0 ? "+" : ""}${stat.trendValue}%`}
                  </Badge>
                </div>
                <div className="mt-4">
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    {stat.label}
                  </p>
                  <h3 className="text-2xl font-bold mt-1">{stat.value}</h3>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Recent Activity Table */}
        <div className="lg:col-span-2 space-y-6">
          <Card className="border-none shadow-sm bg-white dark:bg-gray-900 overflow-hidden">
            <CardHeader className="border-b dark:border-gray-800">
              <CardTitle className="text-lg flex items-center gap-2">
                <Clock className="w-5 h-5 text-gray-400" />{" "}
                {t("platformPartner.dashboard.commissions.title")}
              </CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-400 font-medium">
                    <tr className="text-left border-b dark:border-gray-800">
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.commissions.source")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.commissions.amount")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.commissions.level")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.commissions.status")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.commissions.date")}
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y dark:divide-gray-800">
                    {data.recentCommissions.length > 0 ? (
                      data.recentCommissions.map((comm, idx) => (
                        <tr
                          key={idx}
                          className="hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                        >
                          <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">
                            {comm.fromCompany?.name ||
                              t("platformPartner.dashboard.commissions.system")}
                          </td>
                          <td className="px-6 py-4 text-emerald-600 dark:text-emerald-300 font-bold">
                            {formatPrice(comm.amount)}
                          </td>
                          <td className="px-6 py-4">
                            <Badge
                              variant="outline"
                              className="dark:border-gray-700 dark:text-gray-200"
                            >
                              {t("platformPartner.dashboard.commissions.level")}{" "}
                              {comm.level}
                            </Badge>
                          </td>
                          <td className="px-6 py-4">
                            <Badge className={statusTone(comm.status)}>
                              {statusLabel(comm.status)}
                            </Badge>
                          </td>
                          <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                            {new Date(comm.createdAt).toLocaleDateString()}
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td
                          colSpan={5}
                          className="px-6 py-12 text-center text-gray-400"
                        >
                          {t(
                            "platformPartner.dashboard.commissions.noCommissions",
                          )}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
              {hasMore.commissions && (
                <div className="px-6 py-4 text-center">
                  <Button variant="outline" onClick={loadMoreCommissions}>
                    {t("common.loadMore") || "تحميل المزيد"}
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Recent Payouts Table - Added New Section */}
          <Card className="border-none shadow-sm bg-white dark:bg-gray-900 overflow-hidden">
            <CardHeader className="border-b dark:border-gray-800">
              <CardTitle className="text-lg flex items-center gap-2">
                <DollarSign className="w-5 h-5 text-gray-400" />{" "}
                {t("platformPartner.dashboard.payout.recentPayouts")}
              </CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-400 font-medium">
                    <tr className="text-left border-b dark:border-gray-800">
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.payout.amount")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.payout.method")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.payout.status")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.payout.date")}
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y dark:divide-gray-800">
                    {data.recentPayouts?.length > 0 ? (
                      data.recentPayouts.map((payout, idx) => (
                        <tr
                          key={idx}
                          className="hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                        >
                          <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">
                            {formatPrice(payout.amount)}
                          </td>
                          <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                            {methodLabel(payout.paymentMethod)}
                          </td>
                          <td className="px-6 py-4">
                            <Badge
                              className={`${statusTone(payout.status)} ${payout.status === "PENDING" ? "animate-pulse" : ""}`}
                            >
                              {statusLabel(payout.status)}
                            </Badge>
                          </td>
                          <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                            {new Date(payout.createdAt).toLocaleDateString()}
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td
                          colSpan={4}
                          className="px-6 py-12 text-center text-gray-400"
                        >
                          {t("platformPartner.dashboard.payout.noPayouts")}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
              {hasMore.payouts && (
                <div className="px-6 py-4 text-center">
                  <Button variant="outline" onClick={loadMorePayouts}>
                    {t("common.loadMore") || "تحميل المزيد"}
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Referral History Table - Added New Section */}
          <Card className="border-none shadow-sm bg-white dark:bg-gray-900 overflow-hidden">
            <CardHeader className="border-b dark:border-gray-800">
              <CardTitle className="text-lg flex items-center gap-2">
                <Users className="w-5 h-5 text-gray-400" />{" "}
                {t("platformPartner.dashboard.referrals.historyTitle")}
              </CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-400 font-medium">
                    <tr className="text-left border-b dark:border-gray-800">
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.referrals.companyName")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.referrals.status")}
                      </th>
                      <th className="px-6 py-4">
                        {t("platformPartner.dashboard.referrals.date")}
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y dark:divide-gray-800">
                    {data.referredCompanies?.length > 0 ? (
                      data.referredCompanies.map((ref, idx) => (
                        <tr
                          key={idx}
                          className="hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                        >
                          <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">
                            {ref.name}
                          </td>
                          <td className="px-6 py-4">
                            <Badge className={statusTone(ref.status)}>
                              {statusLabel(ref.status)}
                            </Badge>
                          </td>
                          <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                            {new Date(ref.createdAt).toLocaleDateString()}
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td
                          colSpan={3}
                          className="px-6 py-12 text-center text-gray-400"
                        >
                          {t("platformPartner.dashboard.referrals.noReferrals")}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
              {hasMore.referrals && (
                <div className="px-6 py-4 text-center">
                  <Button variant="outline" onClick={loadMoreReferrals}>
                    {t("common.loadMore") || "تحميل المزيد"}
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Payout Section */}
        <div className="space-y-6">
          <Card className="border-none shadow-lg bg-gradient-to-br from-blue-700 to-indigo-900 text-white">
            <CardContent className="p-8">
              <div className="flex justify-between items-center mb-6">
                <div className="p-3 bg-white/10 rounded-2xl backdrop-blur-xl">
                  <Wallet className="w-8 h-8" />
                </div>
                <div className="text-right">
                  <p className="text-sm text-blue-100">
                    {t("platformPartner.dashboard.payout.readyForWithdrawal")}
                  </p>
                  <h2 className="text-3xl font-bold">
                    {formatPrice(data.partner.pendingEarnings)}
                  </h2>
                </div>
              </div>

              <form onSubmit={handlePayoutRequest} className="space-y-4">
                <div className="space-y-2">
                  <label
                    htmlFor="partner-payout-amount"
                    className="text-sm font-medium text-blue-100"
                  >
                    {t("platformPartner.dashboard.payout.amountToWithdraw")}
                  </label>
                  <input
                    id="partner-payout-amount"
                    name="payoutAmount"
                    type="number"
                    inputMode="numeric"
                    autoComplete="off"
                    value={payoutAmount}
                    onChange={(e) => setPayoutAmount(e.target.value)}
                    placeholder="EGP"
                    className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 placeholder-white/60 text-white focus:outline-none focus:ring-2 focus:ring-white/30 transition-all"
                  />
                </div>
                <div className="space-y-2">
                  <label
                    htmlFor="partner-payout-method"
                    className="text-sm font-medium text-blue-100"
                  >
                    {t("platformPartner.dashboard.payout.method")}
                  </label>
                  <select
                    id="partner-payout-method"
                    name="payoutMethod"
                    autoComplete="off"
                    value={payoutMethod}
                    onChange={(e) => setPayoutMethod(e.target.value)}
                    className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all appearance-none text-white"
                  >
                    <option value="VODAFONE_CASH" className="text-gray-900">
                      {t(
                        "platformPartner.dashboard.payout.methods.vodafoneCash",
                      )}
                    </option>
                    <option value="INSTAPAY" className="text-gray-900">
                      {t("platformPartner.dashboard.payout.methods.instapay")}
                    </option>
                    <option value="BANK_TRANSFER" className="text-gray-900">
                      {t(
                        "platformPartner.dashboard.payout.methods.bankTransfer",
                      )}
                    </option>
                    <option value="CASH" className="text-gray-900">
                      {t("platformPartner.dashboard.payout.methods.cash")}
                    </option>
                    <option value="WALLET" className="text-gray-900">
                      {t("platformPartner.dashboard.payout.methods.wallet")}
                    </option>
                  </select>
                </div>
                <Button
                  type="submit"
                  disabled={payoutLoading || !payoutAmount}
                  className="w-full bg-white text-blue-900 hover:bg-blue-50 py-6 text-lg font-bold rounded-xl shadow-lg transition-transform active:scale-[0.98]"
                >
                  {payoutLoading
                    ? t("platformPartner.dashboard.payout.processing")
                    : t("platformPartner.dashboard.payout.withdrawFunds")}
                </Button>
              </form>

              <p className="mt-4 text-xs text-center text-blue-200 opacity-80">
                {t("platformPartner.dashboard.payout.minimumAmount")}
              </p>
            </CardContent>
          </Card>

          <Card className="border-none shadow-sm bg-white dark:bg-gray-900">
            <CardHeader>
              <CardTitle className="text-sm font-medium text-gray-500">
                {t("platformPartner.dashboard.rankings.title")}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-4">
                <div className="h-2 w-full bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-blue-600 rounded-full"
                    style={{ width: `${progressToTop}%` }}
                  ></div>
                </div>
                <span className="text-xs font-bold text-blue-600">
                  {progressToTop}%
                </span>
              </div>
              <p className="text-xs text-gray-400 mt-2">
                {t("platformPartner.dashboard.rankings.nextRank")}{" "}
                <span className="text-gray-600 dark:text-gray-300">
                  {nextRankLabel ||
                    t("platformPartner.dashboard.rankings.maxRank")}
                </span>
              </p>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default PartnerDashboard;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import { useTheme } from "../../hooks/useTheme";
import {
  CurrencyDollarIcon,
  FunnelIcon,
  CheckCircleIcon,
  XCircleIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";

interface Commission {
  id: string;
  orderId: string;
  type: string;
  amount: number;
  status: string;
  createdAt: string;
  order: {
    orderNumber: string;
    total: number;
  };
  affiliate: {
    affiliateCode: string;
    user: {
      firstName: string;
      lastName: string;
    };
  };
  merchant: {
    name: string;
  };
}

const CommissionsManagement: React.FC = () => {
  const { formatPrice } = useCurrency();
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const [commissions, setCommissions] = useState<Commission[]>([]);
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    status: "",
    type: "",
  });

  useEffect(() => {
    loadCommissions();
  }, [filters]);

  const loadCommissions = async () => {
    try {
      setLoading(true);
      const params: any = {};
      if (filters.status) params.status = filters.status;
      if (filters.type) params.type = filters.type;

      const response = await apiClient.get("/commissions", { params });
      if (response.data.success) {
        setCommissions(response.data.data.commissions || []);
        setStats(response.data.data.stats);
      }
    } catch (error: any) {
      toast.error("حدث خطأ أثناء جلب العمولات");
    } finally {
      setLoading(false);
    }
  };

  const updateCommissionStatus = async (
    commissionId: string,
    status: string,
  ) => {
    try {
      const response = await apiClient.put(
        `/commissions/${commissionId}/status`,
        { status },
      );
      if (response.data.success) {
        toast.success("تم تحديث الحالة بنجاح");
        loadCommissions();
      }
    } catch (error: any) {
      toast.error("حدث خطأ أثناء التحديث");
    }
  };

  if (loading) {
    return (
      <div
        className={`flex items-center justify-center min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"}`}
      >
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div
      className={`min-h-screen ${isDark ? "bg-gray-900" : "bg-gray-50"} p-6`}
    >
      <div className="w-full">
        <div className="mb-6">
          <h1
            className={`text-3xl font-bold ${isDark ? "text-white" : "text-gray-900"}`}
          >
            إدارة العمولات
          </h1>
          <p className={`${isDark ? "text-gray-300" : "text-gray-600"} mt-2`}>
            عرض وإدارة جميع العمولات
          </p>
        </div>

        {/* Stats */}
        {stats && (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
            <div
              className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow p-6`}
            >
              <div className="flex items-center justify-between">
                <div>
                  <p
                    className={`text-sm ${isDark ? "text-gray-400" : "text-gray-600"}`}
                  >
                    إجمالي العمولات
                  </p>
                  <p
                    className={`text-2xl font-bold mt-1 ${isDark ? "text-white" : "text-gray-900"}`}
                  >
                    {formatPrice(stats.totalAmount || 0)}
                  </p>
                </div>
                <CurrencyDollarIcon className="h-8 w-8 text-blue-600" />
              </div>
            </div>

            <div
              className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow p-6`}
            >
              <div className="flex items-center justify-between">
                <div>
                  <p
                    className={`text-sm ${isDark ? "text-gray-400" : "text-gray-600"}`}
                  >
                    عمولات المسوقين
                  </p>
                  <p
                    className={`text-2xl font-bold mt-1 ${isDark ? "text-white" : "text-gray-900"}`}
                  >
                    {formatPrice(stats.byType?.AFFILIATE || 0)}
                  </p>
                </div>
                <CurrencyDollarIcon className="h-8 w-8 text-green-600" />
              </div>
            </div>

            <div
              className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow p-6`}
            >
              <div className="flex items-center justify-between">
                <div>
                  <p
                    className={`text-sm ${isDark ? "text-gray-400" : "text-gray-600"}`}
                  >
                    عمولات التجار
                  </p>
                  <p
                    className={`text-2xl font-bold mt-1 ${isDark ? "text-white" : "text-gray-900"}`}
                  >
                    {formatPrice(stats.byType?.MERCHANT || 0)}
                  </p>
                </div>
                <CurrencyDollarIcon className="h-8 w-8 text-purple-600" />
              </div>
            </div>

            <div
              className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow p-6`}
            >
              <div className="flex items-center justify-between">
                <div>
                  <p
                    className={`text-sm ${isDark ? "text-gray-400" : "text-gray-600"}`}
                  >
                    عمولات المنصة
                  </p>
                  <p
                    className={`text-2xl font-bold mt-1 ${isDark ? "text-white" : "text-gray-900"}`}
                  >
                    {formatPrice(stats.byType?.PLATFORM || 0)}
                  </p>
                </div>
                <CurrencyDollarIcon className="h-8 w-8 text-orange-600" />
              </div>
            </div>
          </div>
        )}

        {/* Filters */}
        <div
          className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow p-4 mb-6`}
        >
          <div className="flex items-center gap-4">
            <FunnelIcon
              className={`h-5 w-5 ${isDark ? "text-gray-400" : "text-gray-500"}`}
            />
            <select
              value={filters.status}
              onChange={(e) =>
                setFilters({ ...filters, status: e.target.value })
              }
              className={`px-4 py-2 border rounded-lg ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
            >
              <option value="">جميع الحالات</option>
              <option value="PENDING">معلق</option>
              <option value="CONFIRMED">مؤكد</option>
              <option value="PAID">مدفوع</option>
              <option value="CANCELLED">ملغي</option>
            </select>

            <select
              value={filters.type}
              onChange={(e) => setFilters({ ...filters, type: e.target.value })}
              className={`px-4 py-2 border rounded-lg ${
                isDark
                  ? "bg-gray-700 border-gray-600 text-white"
                  : "bg-white border-gray-300 text-gray-900"
              }`}
            >
              <option value="">جميع الأنواع</option>
              <option value="AFFILIATE">مسوق</option>
              <option value="MERCHANT">تاجر</option>
              <option value="PLATFORM">منصة</option>
            </select>
          </div>
        </div>

        {/* Commissions Table */}
        <div
          className={`${isDark ? "bg-gray-800" : "bg-white"} rounded-lg shadow overflow-hidden`}
        >
          {commissions.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className={isDark ? "bg-gray-700" : "bg-gray-50"}>
                  <tr>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      رقم الطلب
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      النوع
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      المستفيد
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      المبلغ
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      الحالة
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      التاريخ
                    </th>
                    <th
                      className={`px-6 py-3 text-right text-xs font-medium uppercase ${
                        isDark ? "text-gray-300" : "text-gray-500"
                      }`}
                    >
                      إجراءات
                    </th>
                  </tr>
                </thead>
                <tbody
                  className={`${isDark ? "bg-gray-800 divide-gray-700" : "bg-white divide-gray-200"} divide-y`}
                >
                  {commissions.map((commission) => (
                    <tr
                      key={commission.id}
                      className={
                        isDark ? "hover:bg-gray-700" : "hover:bg-gray-50"
                      }
                    >
                      <td
                        className={`px-6 py-4 whitespace-nowrap text-sm font-medium ${isDark ? "text-gray-300" : "text-gray-900"}`}
                      >
                        {commission.order?.orderNumber || "-"}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-2 py-1 text-xs rounded-full ${
                            commission.type === "AFFILIATE"
                              ? isDark
                                ? "bg-green-900/50 text-green-300"
                                : "bg-green-100 text-green-800"
                              : commission.type === "MERCHANT"
                                ? isDark
                                  ? "bg-purple-900/50 text-purple-300"
                                  : "bg-purple-100 text-purple-800"
                                : isDark
                                  ? "bg-orange-900/50 text-orange-300"
                                  : "bg-orange-100 text-orange-800"
                          }`}
                        >
                          {commission.type === "AFFILIATE"
                            ? "مسوق"
                            : commission.type === "MERCHANT"
                              ? "تاجر"
                              : "منصة"}
                        </span>
                      </td>
                      <td
                        className={`px-6 py-4 whitespace-nowrap text-sm ${isDark ? "text-gray-300" : "text-gray-900"}`}
                      >
                        {commission.affiliate
                          ? `${commission.affiliate.user.firstName} ${commission.affiliate.user.lastName} (${commission.affiliate.affiliateCode})`
                          : commission.merchant
                            ? commission.merchant.name
                            : "المنصة"}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-green-600">
                        {formatPrice(commission.amount)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-2 py-1 text-xs rounded-full ${
                            commission.status === "PAID"
                              ? isDark
                                ? "bg-green-900/50 text-green-300"
                                : "bg-green-100 text-green-800"
                              : commission.status === "CONFIRMED"
                                ? isDark
                                  ? "bg-blue-900/50 text-blue-300"
                                  : "bg-blue-100 text-blue-800"
                                : commission.status === "CANCELLED"
                                  ? isDark
                                    ? "bg-red-900/50 text-red-300"
                                    : "bg-red-100 text-red-800"
                                  : isDark
                                    ? "bg-yellow-900/50 text-yellow-300"
                                    : "bg-yellow-100 text-yellow-800"
                          }`}
                        >
                          {commission.status === "PAID"
                            ? "مدفوع"
                            : commission.status === "CONFIRMED"
                              ? "مؤكد"
                              : commission.status === "CANCELLED"
                                ? "ملغي"
                                : "معلق"}
                        </span>
                      </td>
                      <td
                        className={`px-6 py-4 whitespace-nowrap text-sm ${isDark ? "text-gray-400" : "text-gray-500"}`}
                      >
                        {new Date(commission.createdAt).toLocaleDateString(
                          "ar-EG",
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        {commission.status === "CONFIRMED" && (
                          <button
                            onClick={() =>
                              updateCommissionStatus(commission.id, "PAID")
                            }
                            className="text-green-600 hover:text-green-800 flex items-center gap-1 transition"
                          >
                            <CheckCircleIcon className="h-4 w-4" />
                            تأكيد الدفع
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="text-center py-12">
              <CurrencyDollarIcon
                className={`h-12 w-12 mx-auto mb-4 ${isDark ? "text-gray-600" : "text-gray-400"}`}
              />
              <p className={isDark ? "text-gray-400" : "text-gray-500"}>
                لا توجد عمولات
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CommissionsManagement;

import React, { useState, useEffect } from "react";
import {
  Search,
  ShoppingCart,
  User,
  Trash2,
  Plus,
  Minus,
  CreditCard,
  PauseCircle,
  RotateCcw,
  Maximize,
  Minimize,
  Grid,
  List as ListIcon,
  Barcode,
} from "lucide-react";

// Types
interface Product {
  id: string;
  name: string;
  price: number;
  image?: string;
  category: string;
  stock: number;
  sku: string;
}

interface CartItem extends Product {
  qty: number;
}

interface Customer {
  id: string;
  name: string;
  phone: string;
}

// Mock Data
const MOCK_PRODUCTS: Product[] = [
  {
    id: "1",
    name: "تي شيرت قطن أساسي",
    price: 150,
    category: "ملابس رجالي",
    stock: 50,
    sku: "TSH-001",
  },
  {
    id: "2",
    name: "بنطلون جينز سليم",
    price: 350,
    category: "ملابس رجالي",
    stock: 30,
    sku: "JNS-002",
  },
  {
    id: "3",
    name: "فستان صيفي مشجر",
    price: 450,
    category: "ملابس حريمي",
    stock: 15,
    sku: "DRS-003",
  },
  {
    id: "4",
    name: "حذاء رياضي أبيض",
    price: 600,
    category: "أحذية",
    stock: 10,
    sku: "SHS-004",
  },
  {
    id: "5",
    name: "حقيبة جلد طبيعي",
    price: 800,
    category: "إكسسوارات",
    stock: 5,
    sku: "BAG-005",
  },
  {
    id: "6",
    name: "جاكيت شتوي مبطن",
    price: 1200,
    category: "ملابس رجالي",
    stock: 8,
    sku: "JKT-006",
  },
];

const CATEGORIES = ["الكل", "ملابس رجالي", "ملابس حريمي", "أحذية", "إكسسوارات"];

const POS = () => {
  // State
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("الكل");
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  // Computed
  const subtotal = cart.reduce((acc, item) => acc + item.price * item.qty, 0);
  const tax = subtotal * 0.14; // 14% VAT example
  const total = subtotal + tax;

  const filteredProducts = MOCK_PRODUCTS.filter((p) => {
    const matchesSearch =
      p.name.includes(searchQuery) || p.sku.includes(searchQuery);
    const matchesCategory =
      selectedCategory === "الكل" || p.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  // Handlers
  const addToCart = (product: Product) => {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, qty: item.qty + 1 } : item,
        );
      }
      return [...prev, { ...product, qty: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart((prev) => prev.filter((item) => item.id !== productId));
  };

  const updateQty = (productId: string, delta: number) => {
    setCart((prev) =>
      prev.map((item) => {
        if (item.id === productId) {
          const newQty = Math.max(1, item.qty + delta);
          return { ...item, qty: newQty };
        }
        return item;
      }),
    );
  };

  const clearCart = () => {
    if (window.confirm("هل أنت متأكد من مسح السلة؟")) {
      setCart([]);
    }
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullscreen(false);
      }
    }
  };

  return (
    <div
      className="h-[calc(100vh-64px)] bg-gray-50 flex flex-col md:flex-row overflow-hidden"
      dir="rtl"
    >
      {/* LEFT SIDE: PRODUCTS */}
      <div className="w-full md:w-2/3 flex flex-col border-l border-gray-200 h-full">
        {/* Top Bar */}
        <div className="p-4 bg-white border-b border-gray-200 flex justify-between items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-5 w-5" />
            <input
              type="text"
              placeholder="بحث باسم المنتج أو الباركود..."
              className="w-full pr-10 pl-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              autoFocus
            />
            <Barcode className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-5 w-5 cursor-pointer hover:text-blue-600" />
          </div>

          <button
            onClick={toggleFullscreen}
            className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg"
            title="ملء الشاشة"
          >
            {isFullscreen ? (
              <Minimize className="h-6 w-6" />
            ) : (
              <Maximize className="h-6 w-6" />
            )}
          </button>
        </div>

        {/* Categories */}
        <div className="px-4 py-2 bg-white border-b border-gray-200 overflow-x-auto flex gap-2 scrollbar-hide">
          {CATEGORIES.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors
                ${
                  selectedCategory === cat
                    ? "bg-blue-600 text-white shadow-md"
                    : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Products Grid */}
        <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
            {filteredProducts.map((product) => (
              <div
                key={product.id}
                onClick={() => addToCart(product)}
                className="bg-white rounded-xl shadow-sm border border-gray-200 cursor-pointer hover:shadow-md transition-all hover:border-blue-300 flex flex-col overflow-hidden group"
              >
                <div className="h-32 bg-gray-100 flex items-center justify-center relative">
                  {/* Placeholder Image */}
                  <div className="text-4xl">📦</div>
                  <div className="absolute top-2 right-2 bg-black/50 text-white text-xs px-2 py-1 rounded-full backdrop-blur-sm">
                    {product.stock} قطعة
                  </div>
                </div>
                <div className="p-3 flex flex-col flex-1">
                  <h3 className="font-semibold text-gray-800 text-sm line-clamp-2 mb-1">
                    {product.name}
                  </h3>
                  <div className="mt-auto flex justify-between items-center">
                    <span className="font-bold text-blue-600">
                      {product.price} ج.م
                    </span>
                    <div className="h-8 w-8 rounded-full bg-gray-50 text-blue-600 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <Plus className="h-5 w-5" />
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
          {filteredProducts.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-gray-400">
              <Search className="h-16 w-16 mb-4 opacity-20" />
              <p>لا توجد منتجات مطابقة</p>
            </div>
          )}
        </div>
      </div>

      {/* RIGHT SIDE: CART */}
      <div className="w-full md:w-1/3 bg-white flex flex-col h-full shadow-xl z-10">
        {/* Customer Info */}
        <div className="p-4 border-b border-gray-100 bg-gray-50">
          <div className="flex items-center justify-between mb-2">
            <h2 className="font-bold text-gray-800 flex items-center gap-2">
              <ShoppingCart className="h-5 w-5" />
              السلة الحالية
            </h2>
            <span className="bg-blue-100 text-blue-700 text-xs px-2 py-1 rounded-full font-mono">
              #{Math.floor(Math.random() * 10000)}
            </span>
          </div>

          <div
            className="flex items-center gap-2 bg-white p-2 rounded-lg border border-dashed border-gray-300 cursor-pointer hover:border-blue-400 transition-colors"
            onClick={() =>
              setCustomer({ id: "new", name: "عميل جديد", phone: "" })
            }
          >
            <div className="h-8 w-8 rounded-full bg-blue-50 flex items-center justify-center text-blue-600">
              <User className="h-4 w-4" />
            </div>
            {customer ? (
              <div className="flex-1">
                <p className="text-sm font-bold text-gray-800">
                  {customer.name}
                </p>
                <p className="text-xs text-gray-500">اضغط للتغيير</p>
              </div>
            ) : (
              <div className="flex-1 text-gray-500 text-sm">
                اضافة عميل (اختياري)
              </div>
            )}
            <Plus className="h-4 w-4 text-gray-400" />
          </div>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-2 space-y-2">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-60">
              <ShoppingCart className="h-16 w-16 mb-4" />
              <p>السلة فارغة</p>
              <p className="text-xs mt-2">اضغط على المنتجات لإضافتها</p>
            </div>
          ) : (
            cart.map((item) => (
              <div
                key={item.id}
                className="flex items-center gap-3 p-3 bg-white rounded-lg border border-gray-100 hover:border-blue-100 shadow-sm transition-all"
              >
                <div className="h-12 w-12 bg-gray-100 rounded-md flex items-center justify-center flex-shrink-0">
                  📦
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="font-medium text-gray-800 text-sm truncate">
                    {item.name}
                  </h4>
                  <p className="text-xs text-gray-500">
                    {item.price} ج.م / قطعة
                  </p>
                </div>
                <div className="flex items-center gap-2 bg-gray-50 rounded-lg p-1">
                  <button
                    onClick={() => updateQty(item.id, -1)}
                    className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-gray-600 disabled:opacity-50"
                    disabled={item.qty <= 1}
                  >
                    <Minus className="h-3 w-3" />
                  </button>
                  <span className="text-sm font-bold w-6 text-center">
                    {item.qty}
                  </span>
                  <button
                    onClick={() => updateQty(item.id, 1)}
                    className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-blue-600"
                  >
                    <Plus className="h-3 w-3" />
                  </button>
                </div>
                <div className="text-right min-w-[60px]">
                  <p className="font-bold text-gray-800 text-sm">
                    {(item.price * item.qty).toLocaleString()}
                  </p>
                </div>
                <button
                  onClick={() => removeFromCart(item.id)}
                  className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            ))
          )}
        </div>

        {/* Totals & Actions */}
        <div className="p-4 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
          <div className="space-y-2 mb-4">
            <div className="flex justify-between text-sm text-gray-600">
              <span>المجموع الفرعي</span>
              <span>{subtotal.toLocaleString()} ج.م</span>
            </div>
            <div className="flex justify-between text-sm text-gray-600">
              <span>الضريبة (14%)</span>
              <span>{tax.toLocaleString()} ج.م</span>
            </div>
            <div className="flex justify-between text-xl font-bold text-gray-900 pt-2 border-t border-gray-100">
              <span>الإجمالي</span>
              <span>{total.toLocaleString()} ج.م</span>
            </div>
          </div>

          <div className="grid grid-cols-4 gap-2">
            <button
              onClick={clearCart}
              disabled={cart.length === 0}
              className="col-span-1 flex flex-col items-center justify-center p-2 rounded-lg bg-red-50 text-red-600 hover:bg-red-100 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Trash2 className="h-5 w-5 mb-1" />
              <span className="text-xs font-medium">إلغاء</span>
            </button>

            <button
              disabled={cart.length === 0}
              className="col-span-1 flex flex-col items-center justify-center p-2 rounded-lg bg-orange-50 text-orange-600 hover:bg-orange-100 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <PauseCircle className="h-5 w-5 mb-1" />
              <span className="text-xs font-medium">تعليق</span>
            </button>

            <button
              disabled={cart.length === 0}
              className="col-span-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:shadow-none"
            >
              <CreditCard className="h-6 w-6" />
              <div className="text-right">
                <div className="text-xs opacity-80 font-normal">دفع وإتمام</div>
                <div className="font-bold leading-none">
                  {total.toLocaleString()} ج.م
                </div>
              </div>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default POS;

import React, { useState, useEffect } from "react";
import {
  MagnifyingGlassIcon,
  ArrowPathIcon,
  PhotoIcon,
  LinkIcon,
  XMarkIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  BuildingOfficeIcon,
  BarsArrowDownIcon,
  BarsArrowUpIcon,
  ClipboardDocumentIcon,
} from "@heroicons/react/24/outline";
import Select from "react-select";
import { toast } from "react-hot-toast";
import { useVirtualizer } from "@tanstack/react-virtual";
import clsx from "clsx";
import {
  postAITrackingService,
  PostAITrackingData,
  PostDetails,
} from "../../services/postAITrackingService";
import { companyAwareApi } from "../../services/companyAwareApi";

type SortKey = "lastVisitAt" | "firstVisitAt" | "visitCount";
type SortDir = "asc" | "desc";

const PostAITracking: React.FC = () => {
  const [posts, setPosts] = useState<PostAITrackingData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [pageIdFilter, setPageIdFilter] = useState("");
  const [pageNameFilter, setPageNameFilter] = useState("");
  const [productFilter, setProductFilter] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [total, setTotal] = useState(0);
  const [isSuperAdmin, setIsSuperAdmin] = useState(false);
  const [companyId, setCompanyId] = useState<string | null>(null);
  const [companies, setCompanies] = useState<Array<{ id: string; name: string }>>([]);
  const [products, setProducts] = useState<
    Array<{ id: string; name: string; price: number }>
  >([]);
  const [updatingProducts, setUpdatingProducts] = useState<Set<string>>(
    new Set(),
  );
  const [postDetails, setPostDetails] = useState<Map<string, PostDetails>>(
    new Map(),
  );
  const [loadingDetails, setLoadingDetails] = useState<Set<string>>(new Set());
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [sortKey, setSortKey] = useState<SortKey>("lastVisitAt");
  const [sortDir, setSortDir] = useState<SortDir>("desc");
  const parentRef = React.useRef<HTMLDivElement | null>(null);
  const productOptions = products.map((p) => ({
    value: p.id,
    label: `${p.name} - ${p.price} ر.س`,
  }));
  const [isDarkMode, setIsDarkMode] = useState<boolean>(() => {
    if (typeof document === "undefined") return false;
    return document.documentElement.classList.contains("dark");
  });

  useEffect(() => {
    if (typeof document === "undefined") return;
    const root = document.documentElement;
    const update = () => setIsDarkMode(root.classList.contains("dark"));
    const observer = new MutationObserver(update);
    observer.observe(root, { attributes: true, attributeFilter: ["class"] });
    update();
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const init = async () => {
      const superAdmin = companyAwareApi.isCurrentUserSuperAdmin();
      setIsSuperAdmin(superAdmin);

      const userCompanyId = companyAwareApi.getCurrentCompanyId();
      setCompanyId(userCompanyId);

      if (superAdmin) {
        await fetchCompanies();
      }

      if (!superAdmin || userCompanyId) {
        await fetchData();
        await fetchProducts();
      }
    };
    void init();
  }, []);

  useEffect(() => {
    // Refetch when company or pagination changes
    if (isSuperAdmin && !companyId) return;
    void fetchData();
    void fetchProducts();
  }, [page, pageSize, companyId, isSuperAdmin]);

  // Ensure we have page names when filtering by pageName
  useEffect(() => {
    if (pageNameFilter.trim() === "") return;
    // Prefetch details for currently loaded posts (up to 50 to avoid overload)
    const slice = posts.slice(0, 50);
    slice.forEach((p) => {
      if (!postDetails.has(p.postId)) {
        void fetchPostDetails(p);
      }
    });
  }, [pageNameFilter, posts, postDetails]);

  const fetchCompanies = async () => {
    try {
      const response = await companyAwareApi.getAllCompanies();
      const data = response.data?.data || response.data || [];
      const mapped =
        Array.isArray(data) && data.length > 0
          ? data.map((c: any) => ({
              id: c.id || c.companyId || c.uuid,
              name: c.name || c.companyName || "بدون اسم",
            }))
          : [];
      setCompanies(mapped);
      if (!companyId && mapped.length > 0) {
        setCompanyId(mapped[0].id);
      }
    } catch (err) {
      console.error("Error fetching companies:", err);
      toast.error("تعذر تحميل قائمة الشركات");
    }
  };

  const fetchProducts = async () => {
    try {
      const response = await companyAwareApi.get("/products", {
        params: {
          isActive: true,
          limit: 1000,
          companyId: companyId || undefined,
        },
      });
      if (response.data && response.data.data) {
        setProducts(
          response.data.data.map((p: any) => ({
            id: p.id,
            name: p.name,
            price: p.price,
          })),
        );
      }
    } catch (err) {
      console.error("Error fetching products:", err);
      toast.error("تعذر تحميل المنتجات");
    }
  };

  const handleFeaturedProductChange = async (
    postId: string,
    productId: string | null,
  ) => {
    setUpdatingProducts((prev) => new Set(prev).add(postId));
    try {
      await postAITrackingService.updateFeaturedProduct(
        postId,
        productId,
        companyId,
      );
      // Update local state
      setPosts((prevPosts) =>
        prevPosts.map((post) =>
          post.postId === postId
            ? {
                ...post,
                featuredProductId: productId,
                featuredProduct: productId
                  ? products.find((p) => p.id === productId) || null
                  : null,
              }
            : post,
        ),
      );
      toast.success("تم تحديث المنتج المميز بنجاح");
    } catch (err: any) {
      console.error("Error updating featured product:", err);
      toast.error(err.message || "فشل في تحديث المنتج المميز");
    } finally {
      setUpdatingProducts((prev) => {
        const newSet = new Set(prev);
        newSet.delete(postId);
        return newSet;
      });
    }
  };

  const fetchPostDetails = async (post: PostAITrackingData) => {
    if (postDetails.has(post.postId) || loadingDetails.has(post.postId)) {
      return; // Already loaded or loading
    }

    setLoadingDetails((prev) => new Set(prev).add(post.postId));
    try {
      const response = await postAITrackingService.getPostDetails(
        post.postId,
        post.pageId || null,
        companyId,
      );
      if (response.success && response.data) {
        setPostDetails((prev) => {
          const newMap = new Map(prev);
          newMap.set(post.postId, response.data);
          return newMap;
        });
      }
    } catch (err: any) {
      console.error("Error fetching post details:", err);
      // Don't show error to user - just log it
    } finally {
      setLoadingDetails((prev) => {
        const newSet = new Set(prev);
        newSet.delete(post.postId);
        return newSet;
      });
    }
  };

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await postAITrackingService.getPostsAITracking({
        page,
        limit: pageSize,
        companyId,
      });
      if (response.success && response.data) {
        const postsData = response.data.posts || [];
        setPosts(postsData);
        setTotal(response.data.total || postsData.length);
        setPage(response.data.page ? Number(response.data.page) : page);
        setPageSize(response.data.limit ? Number(response.data.limit) : pageSize);
        setLastUpdated(new Date());
      }
    } catch (err: any) {
      setError(err.message || "فشل في جلب البيانات");
      console.error("Error fetching posts AI tracking:", err);
      toast.error(err.message || "فشل في جلب البيانات");
    } finally {
      setLoading(false);
    }
  };

  const toggleDetails = (post: PostAITrackingData) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(post.postId)) {
        next.delete(post.postId);
      } else {
        next.add(post.postId);
        void fetchPostDetails(post);
      }
      return next;
    });
  };

  const filteredPosts = posts.filter((post) => {
    const matchesSearch =
      searchQuery === "" ||
      post.postId.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesPage =
      pageIdFilter === "" ||
      (post.pageId || "").toLowerCase().includes(pageIdFilter.toLowerCase());
    const details = postDetails.get(post.postId);
    const matchesPageName =
      pageNameFilter === "" ||
      (details?.pageName || "")
        .toLowerCase()
        .includes(pageNameFilter.toLowerCase());
    const matchesProduct =
      !productFilter ||
      post.featuredProductId === productFilter ||
      post.featuredProduct?.id === productFilter;

    return matchesSearch && matchesPage && matchesPageName && matchesProduct;
  });

  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const missingFeatured = posts.filter((p) => !p.featuredProductId).length;
  const postsWithImages = posts.filter(
    (p) => (postDetails.get(p.postId)?.hasImages) || false,
  ).length;

  const sortedPosts = [...filteredPosts].sort((a, b) => {
    const dir = sortDir === "asc" ? 1 : -1;
    if (sortKey === "visitCount") {
      return dir * ((a.visitCount || 0) - (b.visitCount || 0));
    }
    const aDate =
      sortKey === "lastVisitAt"
        ? new Date(a.lastVisitAt || 0).getTime()
        : new Date(a.firstVisitAt || 0).getTime();
    const bDate =
      sortKey === "lastVisitAt"
        ? new Date(b.lastVisitAt || 0).getTime()
        : new Date(b.firstVisitAt || 0).getTime();
    return dir * (aDate - bDate);
  });

  const formatDate = (dateString?: string) => {
    if (!dateString) return "غير محدد";
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString("ar-SA", {
        year: "numeric",
        month: "long",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return "غير محدد";
    }
  };

  // Virtualizer setup
  const rowVirtualizer = useVirtualizer({
    count: sortedPosts.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 360,
    overscan: 6,
  });

  if (loading) {
    return (
      <div className="min-h-screen bg-[#f8fafc] dark:bg-[#020617] flex items-center justify-center p-8">
        <div className="relative group">
          <div className="absolute -inset-4 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-[3rem] blur-2xl opacity-20 animate-pulse"></div>
          <div className="relative bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border border-white dark:border-slate-800 p-12 rounded-[2.5rem] shadow-2xl text-center space-y-6">
            <div className="relative">
              <div className="w-20 h-20 border-4 border-blue-600/20 border-t-blue-600 rounded-full animate-spin mx-auto"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-10 h-10 bg-blue-600/10 rounded-full animate-ping"></div>
              </div>
            </div>
            <div className="space-y-2">
              <p className="text-2xl font-black text-slate-900 dark:text-white">جاري تحميل البيانات</p>
              <p className="text-slate-500 dark:text-slate-400 font-medium">نحضّر لك تجربة استثنائية...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-[#f8fafc] dark:bg-[#020617] flex items-center justify-center p-8">
        <div className="relative group max-w-md w-full">
          <div className="absolute -inset-4 bg-gradient-to-r from-red-600 to-orange-600 rounded-[3rem] blur-2xl opacity-20"></div>
          <div className="relative bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border border-white dark:border-slate-800 p-12 rounded-[2.5rem] shadow-2xl text-center space-y-8">
            <div className="w-20 h-20 bg-red-100 dark:bg-red-900/30 rounded-3xl flex items-center justify-center mx-auto rotate-12 group-hover:rotate-0 transition-transform duration-500">
              <XMarkIcon className="w-12 h-12 text-red-600 dark:text-red-400" />
            </div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 dark:text-white">عذراً، حدث خطأ</h2>
              <p className="text-slate-500 dark:text-slate-400 font-medium leading-relaxed">
                {error}
              </p>
            </div>
            <button
              onClick={fetchData}
              className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-bold shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all"
            >
              إعادة المحاولة
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] dark:bg-[#020617] p-4 md:p-8 transition-colors duration-500">
      <div className="max-w-7xl mx-auto space-y-8">

        {/* Header Section */}
        <div className="relative group">
          <div className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-[2rem] blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200"></div>
          <div className="relative flex flex-col gap-6 md:flex-row md:items-center md:justify-between bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border border-white dark:border-slate-800 p-8 rounded-[2rem] shadow-2xl shadow-blue-500/10 dark:shadow-none">
            <div className="space-y-2 text-right">
              <h1 className="text-4xl md:text-5xl font-black tracking-tight text-slate-900 dark:text-white">
                إدارة <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-indigo-500">البوستات</span>
              </h1>
              <p className="text-lg text-slate-500 dark:text-slate-400 font-medium">
                تتبع الزيارات، جلب تفاصيل فيسبوك، وربط منتج مميز لكل بوست.
              </p>
              {lastUpdated && (
                <div className="flex items-center gap-2 text-sm text-slate-400 dark:text-slate-500 font-mono mt-4 justify-end">
                  <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                  آخر تحديث: {lastUpdated.toLocaleTimeString("ar-EG")}
                </div>
              )}
            </div>
            
            <div className="flex flex-wrap items-center gap-4 justify-end">
              {isSuperAdmin && (
                <div className="group/select relative">
                  <div className="absolute -inset-0.5 bg-gradient-to-r from-blue-500 to-indigo-500 rounded-2xl blur opacity-20 group-hover/select:opacity-100 transition duration-300"></div>
                  <div className="relative flex items-center gap-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl px-4 py-3 min-w-[200px]">
                    <BuildingOfficeIcon className="w-5 h-5 text-blue-500" />
                    <select
                      className="bg-transparent text-sm font-bold text-slate-700 dark:text-slate-200 focus:outline-none w-full appearance-none cursor-pointer"
                      value={companyId || ""}
                      onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                        setPage(1);
                        setCompanyId(e.target.value || null);
                      }}
                    >
                      {companies.map((c) => (
                        <option key={c.id} value={c.id}>
                          {c.name}
                        </option>
                      ))}
                    </select>
                    <ChevronDownIcon className="w-4 h-4 text-slate-400" />
                  </div>
                </div>
              )}
              
              <button
                onClick={fetchData}
                className="group/btn relative inline-flex items-center justify-center px-8 py-4 font-bold text-white transition-all duration-200 bg-blue-600 font-pj rounded-2xl focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-600 active:scale-95 shadow-[0_10px_20px_-10px_rgba(37,99,235,0.4)]"
              >
                <div className="absolute inset-0 w-full h-full transition duration-300 transform -translate-x-1 -translate-y-1 bg-indigo-500 ease opacity-80 group-hover/btn:translate-x-0 group-hover/btn:translate-y-0 rounded-2xl"></div>
                <div className="absolute inset-0 w-full h-full transition duration-300 transform translate-x-1 translate-y-1 bg-blue-700 ease opacity-80 group-hover/btn:translate-x-0 group-hover/btn:translate-y-0 mix-blend-screen rounded-2xl"></div>
                <span className="relative flex items-center gap-2">
                  <ArrowPathIcon className={clsx("w-5 h-5", loading && "animate-spin")} />
                  تحديث البيانات
                </span>
              </button>
            </div>
          </div>
        </div>

        {/* Stats Grid */}
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4 pt-4">
          <div className="relative group overflow-hidden bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-xl shadow-slate-200/50 dark:shadow-none hover:border-blue-500/50 transition-all duration-300">
            <div className="absolute top-0 right-0 w-24 h-24 bg-blue-500/10 rounded-bl-full -mr-12 -mt-12 group-hover:scale-150 transition-transform duration-500"></div>
            <div className="relative space-y-2">
              <div className="flex items-center justify-between">
                <p className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider text-right">إجمالي البوستات</p>
                <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-xl">
                  <ClipboardDocumentIcon className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                </div>
              </div>
              <p className="text-4xl font-black text-slate-900 dark:text-white text-right">{total.toLocaleString()}</p>
              <div className="h-1 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                <div className="h-full bg-blue-500 rounded-full w-[100%]" />
              </div>
            </div>
          </div>

          <div className="relative group overflow-hidden bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-xl shadow-slate-200/50 dark:shadow-none hover:border-orange-500/50 transition-all duration-300">
            <div className="absolute top-0 right-0 w-24 h-24 bg-orange-500/10 rounded-bl-full -mr-12 -mt-12 group-hover:scale-150 transition-transform duration-500"></div>
            <div className="relative space-y-2 text-right">
              <div className="flex items-center justify-between">
                <p className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">بدون منتج</p>
                <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-xl">
                  <XMarkIcon className="w-5 h-5 text-orange-600 dark:text-orange-400" />
                </div>
              </div>
              <p className="text-4xl font-black text-slate-900 dark:text-white">{missingFeatured.toLocaleString()}</p>
              <div className="h-1 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                <div className="h-full bg-orange-500 rounded-full" style={{ width: `${(missingFeatured / (total || 1)) * 100}%` }} />
              </div>
            </div>
          </div>

          <div className="relative group overflow-hidden bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-xl shadow-slate-200/50 dark:shadow-none hover:border-emerald-500/50 transition-all duration-300">
            <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-500/10 rounded-bl-full -mr-12 -mt-12 group-hover:scale-150 transition-transform duration-500"></div>
            <div className="relative space-y-2 text-right">
              <div className="flex items-center justify-between">
                <p className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">متوسط الزيارات</p>
                <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 rounded-xl">
                  <BarsArrowUpIcon className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
                </div>
              </div>
              <p className="text-4xl font-black text-slate-900 dark:text-white">
                {posts.length
                  ? Math.round(
                      posts.reduce((sum, p) => sum + (p.visitCount || 0), 0) /
                        posts.length,
                    ).toLocaleString()
                  : 0}
              </p>
              <div className="h-1 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                <div className="h-full bg-emerald-500 rounded-full w-[70%]" />
              </div>
            </div>
          </div>

          <div className="relative group overflow-hidden bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-xl shadow-slate-200/50 dark:shadow-none hover:border-indigo-500/50 transition-all duration-300">
            <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-500/10 rounded-bl-full -mr-12 -mt-12 group-hover:scale-150 transition-transform duration-500"></div>
            <div className="relative space-y-2 text-right">
              <div className="flex items-center justify-between">
                <p className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider text-right">عرض الصفحة</p>
                <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 rounded-xl">
                  <BarsArrowDownIcon className="w-5 h-5 text-indigo-600 dark:text-indigo-400" />
                </div>
              </div>
              <select
                className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl px-3 py-3 text-lg font-black text-slate-900 dark:text-white text-center focus:outline-none appearance-none cursor-pointer"
                value={pageSize}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                  setPage(1);
                  setPageSize(Number(e.target.value));
                }}
              >
                {[10, 25, 50, 100].map((size) => (
                  <option key={size} value={size}>
                    {size} سجل
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Filters Section */}
        <div className="bg-white/70 dark:bg-slate-900/70 backdrop-blur-3xl border border-white dark:border-slate-800 rounded-[2rem] p-8 shadow-[0_20px_50px_-20px_rgba(30,41,59,0.1)] dark:shadow-none space-y-6">
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
            <div className="relative group/field">
              <div className="absolute inset-0 bg-blue-500/5 rounded-2xl opacity-0 group-hover/field:opacity-100 transition-opacity duration-300"></div>
              <MagnifyingGlassIcon className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 dark:text-slate-500" />
              <input
                type="text"
                className="w-full pr-12 pl-4 py-4 bg-slate-50/50 dark:bg-slate-950/50 border border-slate-200 dark:border-slate-800 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 dark:focus:border-blue-400 transition-all text-right font-medium dark:text-white"
                placeholder="ابحث عن معرف البوست..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            <div className="relative group/field text-right">
              <input
                type="text"
                className="w-full px-6 py-4 bg-slate-50/50 dark:bg-slate-950/50 border border-slate-200 dark:border-slate-800 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-right font-medium dark:text-white"
                placeholder="فلترة بالـ Page ID"
                value={pageIdFilter}
                onChange={(e) => setPageIdFilter(e.target.value)}
              />
            </div>

            <div className="relative group/field text-right">
              <input
                type="text"
                className="w-full px-6 py-4 bg-slate-50/50 dark:bg-slate-950/50 border border-slate-200 dark:border-slate-800 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-right font-medium dark:text-white"
                placeholder="فلترة باسم الصفحة"
                value={pageNameFilter}
                onChange={(e) => setPageNameFilter(e.target.value)}
              />
            </div>

            <div className="relative group/field rtl">
              <Select
                classNamePrefix="premium-select"
                isClearable
                isSearchable
                value={productFilter ? productOptions.find((opt) => opt.value === productFilter) || null : null}
                onChange={(opt) => setProductFilter(opt ? opt.value : null)}
                options={productOptions}
                placeholder="فلترة بالمنتج المميز..."
                styles={{
                  control: (base, state) => ({
                    ...base,
                    minHeight: 56,
                    borderRadius: '1rem',
                    backgroundColor: isDarkMode ? 'rgba(2, 6, 23, 0.5)' : 'rgba(248, 250, 252, 0.5)',
                    borderColor: state.isFocused ? '#3b82f6' : isDarkMode ? '#1e293b' : '#e2e8f0',
                    borderWidth: '1px',
                    boxShadow: state.isFocused ? '0 0 0 4px rgba(59, 130, 246, 0.1)' : 'none',
                    '&:hover': { borderColor: '#3b82f6' },
                    cursor: 'pointer'
                  }),
                  placeholder: (base) => ({ ...base, color: '#94a3b8', textAlign: 'right', width: '100%', fontWeight: '500' }),
                  input: (base) => ({ ...base, color: isDarkMode ? '#f8fafc' : '#0f172a', textAlign: 'right' }),
                  singleValue: (base) => ({ ...base, color: isDarkMode ? '#f8fafc' : '#0f172a', textAlign: 'right', width: '100%', fontWeight: '600' }),
                  menu: (base) => ({
                    ...base,
                    borderRadius: '1rem',
                    overflow: 'hidden',
                    border: isDarkMode ? '1px solid #1e293b' : '1px solid #e2e8f0',
                    boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)',
                    backgroundColor: isDarkMode ? '#0f172a' : '#ffffff',
                    zIndex: 50
                  }),
                  option: (base, state) => ({
                    ...base,
                    textAlign: 'right',
                    backgroundColor: state.isFocused ? (isDarkMode ? '#1e293b' : '#f1f5f9') : 'transparent',
                    color: isDarkMode ? '#f8fafc' : '#0f172a',
                    fontWeight: state.isSelected ? '700' : '500',
                    padding: '12px 16px',
                    cursor: 'pointer'
                  })
                }}
              />
            </div>
          </div>

          <div className="flex flex-wrap items-center justify-between gap-6 pt-6 border-t border-slate-100 dark:border-slate-800">
            <div className="flex flex-wrap items-center gap-4">
              <span className="text-sm font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">الترتيب</span>
              <div className="flex p-1 bg-slate-100 dark:bg-slate-950 rounded-2xl gap-1">
                {["lastVisitAt", "firstVisitAt", "visitCount"].map((key) => (
                  <button
                    key={key}
                    onClick={() => setSortKey(key as SortKey)}
                    className={clsx(
                      "px-4 py-2 text-sm font-bold rounded-xl transition-all duration-200",
                      sortKey === key 
                        ? "bg-white dark:bg-slate-800 text-blue-600 dark:text-blue-400 shadow-sm" 
                        : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                    )}
                  >
                    {key === "lastVisitAt" ? "آخر زيارة" : key === "firstVisitAt" ? "أول زيارة" : "الزيارات"}
                  </button>
                ))}
              </div>
              <button
                onClick={() => setSortDir((d) => (d === "asc" ? "desc" : "asc"))}
                className="p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-600 dark:text-slate-300 hover:border-blue-500 hover:text-blue-500 transition-colors"
              >
                {sortDir === "asc" ? <BarsArrowUpIcon className="w-5 h-5" /> : <BarsArrowDownIcon className="w-5 h-5" />}
              </button>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex bg-slate-100 dark:bg-slate-950 p-1 rounded-2xl gap-1">
                <button
                  disabled={page <= 1}
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  className="px-4 py-2 text-sm font-bold text-slate-500 hover:text-slate-900 disabled:opacity-30 disabled:pointer-events-none transition-colors"
                >
                  السابق
                </button>
                <div className="px-4 py-2 bg-white dark:bg-slate-800 text-blue-600 dark:text-blue-400 rounded-xl font-black text-sm shadow-sm">
                  {page} / {totalPages}
                </div>
                <button
                  disabled={page >= totalPages}
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  className="px-4 py-2 text-sm font-bold text-slate-500 hover:text-slate-900 disabled:opacity-30 disabled:pointer-events-none transition-colors"
                >
                  التالي
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Posts Cards with optional virtualization */}
        {sortedPosts.length === 0 ? (
          <div className="bg-white/80 backdrop-blur-xl rounded-2xl shadow-xl p-12 text-center">
            <PhotoIcon className="w-16 h-16 text-slate-300 mx-auto mb-4" />
            <p className="text-slate-500 text-lg font-medium">
              لا توجد بوستات
            </p>
          </div>
        ) : sortedPosts.length > 50 ? (
          <div
            ref={parentRef}
            className="bg-transparent rounded-2xl border border-transparent max-h-[70vh] overflow-auto"
          >
            <div
              style={{
                height: `${rowVirtualizer.getTotalSize()}px`,
                position: "relative",
              }}
            >
              {rowVirtualizer.getVirtualItems().map((virtualRow) => {
                const post = sortedPosts[virtualRow.index];
                const details = postDetails.get(post.postId);
                const isLoadingDetails = loadingDetails.has(post.postId);
                const isExpanded = expanded.has(post.postId);

                return (
                  <div
                    key={post.postId}
                    ref={rowVirtualizer.measureElement}
                    className="absolute left-0 right-0 p-2"
                    style={{ top: virtualRow.start }}
                  >
                <PostCard
                  post={post}
                  details={details}
                  isLoadingDetails={isLoadingDetails}
                  isExpanded={isExpanded}
                  onToggle={() => toggleDetails(post)}
                  onSelectProduct={(id) =>
                    handleFeaturedProductChange(post.postId, id)
                  }
                  products={products}
                  productOptions={productOptions}
                  updating={updatingProducts.has(post.postId)}
                  isDarkMode={isDarkMode}
                />
                  </div>
                );
              })}
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {sortedPosts.map((post: PostAITrackingData) => {
              const details = postDetails.get(post.postId);
              const isLoadingDetails = loadingDetails.has(post.postId);
              const isExpanded = expanded.has(post.postId);

              return (
                <PostCard
                  key={post.postId}
                  post={post}
                  details={details}
                  isLoadingDetails={isLoadingDetails}
                  isExpanded={isExpanded}
                  onToggle={() => toggleDetails(post)}
                  onSelectProduct={(id) =>
                    handleFeaturedProductChange(post.postId, id)
                  }
                  products={products}
                  productOptions={productOptions}
                  updating={updatingProducts.has(post.postId)}
                  isDarkMode={isDarkMode}
                />
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default PostAITracking;

type PostCardProps = {
  post: PostAITrackingData;
  details?: PostDetails;
  isLoadingDetails: boolean;
  isExpanded: boolean;
  onToggle: () => void;
  onSelectProduct: (id: string | null) => void;
  products: Array<{ id: string; name: string; price: number }>;
  productOptions: Array<{ value: string; label: string }>;
  updating: boolean;
  isDarkMode: boolean;
};

const PostCard: React.FC<PostCardProps> = ({
  post,
  details,
  isLoadingDetails,
  isExpanded,
  onToggle,
  onSelectProduct,
  products,
  productOptions,
  updating,
  isDarkMode,
}) => {
  const formatDate = (dateString?: string) => {
    if (!dateString) return "غير محدد";
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString("ar-SA", {
        year: "numeric",
        month: "long",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return "غير محدد";
    }
  };

  const selectedProductOption = post.featuredProductId
    ? productOptions.find((opt) => opt.value === post.featuredProductId) || null
    : null;

  return (
    <div className="group relative">
      <div className="absolute -inset-0.5 bg-gradient-to-r from-blue-500/20 to-indigo-500/20 rounded-3xl blur opacity-0 group-hover:opacity-100 transition duration-500"></div>
      <div className="relative overflow-hidden rounded-3xl transition-all duration-300 bg-white dark:bg-slate-900/80 backdrop-blur-xl border border-slate-200 dark:border-slate-800 shadow-xl shadow-slate-200/40 dark:shadow-none hover:shadow-2xl hover:shadow-blue-500/10">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-sky-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>
        <div className="p-8 flex flex-col gap-6">
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div className="space-y-4 flex-1">
              <div className="flex flex-wrap items-center gap-3">
                <span className="px-3 py-1 text-[10px] font-black uppercase tracking-[0.2em] rounded-full bg-blue-600/10 text-blue-600 dark:bg-blue-400/10 dark:text-blue-400 border border-blue-600/20">
                  AI Tracking
                </span>
                <h3 className="text-2xl font-black text-slate-900 dark:text-white font-mono tracking-tight">
                  {post.postId}
                </h3>
                <button
                  title="نسخ Post ID"
                  onClick={() => {
                    navigator.clipboard
                      .writeText(post.postId)
                      .then(() => toast.success("تم نسخ Post ID"))
                      .catch(() => toast.error("تعذر النسخ"));
                  }}
                  className="p-2 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-white dark:hover:bg-slate-700 transition-all shadow-inner"
                >
                  <ClipboardDocumentIcon className="w-5 h-5" />
                </button>
              </div>

              <div className="flex flex-wrap items-center gap-4">
              <div className="flex items-center gap-3 px-4 py-2 bg-slate-50 dark:bg-slate-950/50 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="p-1.5 bg-blue-500 rounded-lg">
                  <BarsArrowUpIcon className="w-3.5 h-3.5 text-white" />
                </div>
                <div className="text-right">
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">عدد الزيارات</p>
                  <p className="text-lg font-black text-slate-900 dark:text-white leading-tight">{post.visitCount || 0}</p>
                </div>
              </div>

              <div className="flex flex-col text-right">
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mb-1">تاريخ أول زيارة</p>
                <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{formatDate(post.firstVisitAt)}</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
              <div className="flex flex-col items-end">
                <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-1 leading-none">آخر نشاط</span>
                <span className="text-xs font-black text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/30 px-3 py-1.5 rounded-lg border border-blue-100 dark:border-blue-800/50">
                    {formatDate(post.lastVisitAt)}
                </span>
              </div>
          </div>
        </div>

        <div className="grid md:grid-cols-2 gap-6 pt-6 border-t border-slate-100 dark:border-slate-800">
            <div className="space-y-4">
               {post.pageId && (
                <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-950/50 rounded-2xl border border-slate-100 dark:border-slate-800">
                  <LinkIcon className="w-5 h-5 text-slate-400" />
                  <div className="text-right">
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Page ID</p>
                    <p className="text-sm font-mono font-bold text-slate-900 dark:text-white">{post.pageId}</p>
                  </div>
                </div>
              )}
              {details?.pageName && (
                <div className="flex items-center justify-between p-4 bg-indigo-50/50 dark:bg-indigo-900/20 rounded-2xl border border-indigo-100/50 dark:border-indigo-800/30">
                  <BuildingOfficeIcon className="w-5 h-5 text-indigo-500" />
                  <div className="text-right">
                    <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-wider">اسم الصفحة</p>
                    <p className="text-sm font-bold text-indigo-900 dark:text-indigo-200">{details.pageName}</p>
                  </div>
                </div>
              )}
            </div>

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block text-right">المنتج المميز</label>
              <Select
                classNamePrefix="premium-select"
                isClearable
                isSearchable
                options={productOptions}
                value={selectedProductOption}
                onChange={(opt) => onSelectProduct(opt ? opt.value : null)}
                placeholder="اختر منتجاً لهذا البوست..."
                isLoading={updating}
                styles={{
                  control: (base) => ({
                    ...base,
                    borderRadius: '1.25rem',
                    backgroundColor: isDarkMode ? 'rgba(2, 6, 23, 0.4)' : '#f8fafc',
                    borderColor: isDarkMode ? '#1e293b' : '#e2e8f0',
                    borderWidth: '1px',
                    minHeight: '52px',
                    '&:hover': { borderColor: '#3b82f6' }
                  }),
                  singleValue: (base) => ({ ...base, color: isDarkMode ? '#f8fafc' : '#0f172a', textAlign: 'right', fontWeight: '700' }),
                  placeholder: (base) => ({ ...base, color: '#94a3b8', textAlign: 'right', width: '100%', fontWeight: '500' }),
                  menu: (base) => ({ ...base, backgroundColor: isDarkMode ? '#0f172a' : '#fff', borderRadius: '1rem', overflow: 'hidden' }),
                  option: (base, state) => ({
                    ...base,
                    textAlign: 'right',
                    backgroundColor: state.isFocused ? (isDarkMode ? '#1e293b' : '#f1f5f9') : 'transparent',
                    color: isDarkMode ? '#f8fafc' : '#0f172a',
                    fontWeight: state.isSelected ? '700' : '500'
                  })
                }}
              />
            </div>
        </div>

        <button
          onClick={onToggle}
          disabled={isLoadingDetails}
          className={clsx(
            "w-full flex items-center justify-center gap-2 py-4 rounded-2xl font-black text-sm transition-all duration-300",
            isExpanded 
              ? "bg-slate-900 text-white dark:bg-white dark:text-slate-900 shadow-xl" 
              : "bg-slate-100 text-slate-600 hover:bg-blue-600 hover:text-white dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-blue-600 transition-all border border-transparent hover:border-blue-400 shadow-inner"
          )}
        >
          {isLoadingDetails ? (
            <ArrowPathIcon className="w-5 h-5 animate-spin" />
          ) : isExpanded ? (
            <>
              <ChevronUpIcon className="w-5 h-5" /> إغلاق التفاصيل
            </>
          ) : (
            <>
              <ChevronDownIcon className="w-5 h-5" /> عرض تفاصيل فيسبوك
            </>
          )}
        </button>

        {isExpanded && details && (
          <div className="space-y-6 animate-in slide-in-from-top duration-500 overflow-hidden bg-slate-50 dark:bg-slate-950/80 rounded-[2rem] p-8 border border-slate-100 dark:border-slate-800 shadow-inner">
             {details.message && (
                <div className="space-y-3">
                    <p className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest text-right">محتوى البوست</p>
                    <div className="p-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm">
                        <p className="text-slate-700 dark:text-slate-200 text-right leading-relaxed whitespace-pre-wrap font-medium">
                            {details.message}
                        </p>
                    </div>
                </div>
              )}

              {details.attachments && details.attachments.length > 0 && (
                <div className="space-y-4">
                  <p className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest text-right">المرفقات ({details.attachments.length})</p>
                  <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                    {details.attachments.map((att, idx) => (
                      <div key={idx} className="group/img relative aspect-square rounded-2xl overflow-hidden bg-slate-200 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-lg">
                        <img
                          src={att.src}
                          alt="Post attachment"
                          className="w-full h-full object-cover transition duration-500 group-hover/img:scale-110"
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover/img:opacity-100 transition-opacity flex items-end justify-center p-3">
                            <a href={att.src} target="_blank" rel="noreferrer" className="bg-white/20 backdrop-blur-md p-2 rounded-full hover:bg-white/40 transition-colors">
                                <LinkIcon className="w-4 h-4 text-white" />
                            </a>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
          </div>
        )}
      </div>
    </div>
  </div>
);
};

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  ShoppingBagIcon,
  ArrowDownTrayIcon,
  CheckCircleIcon,
  XCircleIcon,
  ExclamationTriangleIcon,
  MagnifyingGlassIcon,
  Cog6ToothIcon,
  ArrowPathIcon,
  DocumentTextIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import tokenManager from "../../utils/tokenManager";

interface Product {
  name: string;
  description: string;
  price: number;
  comparePrice?: number;
  cost?: number;
  sku?: string;
  barcode?: string;
  stock: number;
  trackInventory: boolean;
  images: string[];
  category?: string;
  tags: string[];
  weight?: number;
  dimensions?: any;
  easyOrdersId?: string;
  easyOrdersUrl?: string;
}

interface SyncLog {
  id: string;
  syncType: string;
  status: string;
  startedAt: string;
  completedAt?: string;
  totalItems: number;
  successCount: number;
  failedCount: number;
  skippedCount: number;
  errorMessage?: string;
}

const EasyOrdersImport: React.FC = () => {
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState<"products" | "orders">("products");
  const [apiKey, setApiKey] = useState("");
  const [products, setProducts] = useState<Product[]>([]);
  const [selectedProducts, setSelectedProducts] = useState<Set<number>>(
    new Set(),
  );
  const [loading, setLoading] = useState(false);
  const [importing, setImporting] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [syncLogs, setSyncLogs] = useState<SyncLog[]>([]);
  const [settings, setSettings] = useState<any>(null);
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);

  // Load settings on mount
  useEffect(() => {
    loadSettings();
    loadSyncLogs();
  }, []);

  const loadSettings = async () => {
    try {
      const response = await fetch("/api/v1/easy-orders/settings", {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success && data.data) {
        setSettings(data.data);
        if (data.data.hasApiKey) {
          setApiKey("********"); // Placeholder
        }
      }
    } catch (error) {
      console.error("Error loading settings:", error);
    }
  };

  const loadSyncLogs = async () => {
    try {
      const response = await fetch("/api/v1/easy-orders/sync-logs", {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setSyncLogs(data.data);
      }
    } catch (error) {
      console.error("Error loading sync logs:", error);
    }
  };

  const saveSettings = async () => {
    if (!apiKey.trim()) {
      toast.error(t("easyOrdersImport.errorApiKey"));
      return;
    }

    setLoading(true);
    try {
      const response = await fetch("/api/v1/easy-orders/settings", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          apiKey: apiKey === "********" ? undefined : apiKey,
          syncEnabled: true,
        }),
      });

      const data = await response.json();
      if (data.success) {
        toast.success(t("common.savedSuccessfully"));
        loadSettings();
      } else {
        toast.error(data.message);
      }
    } catch (error) {
      toast.error(t("common.error"));
    } finally {
      setLoading(false);
    }
  };

  // جلب المنتجات من Easy Orders
  const fetchProducts = async () => {
    if (!apiKey.trim()) {
      toast.error(t("easyOrdersImport.errorApiKey"));
      return;
    }

    setLoading(true);
    try {
      const response = await fetch("/api/v1/easy-orders/fetch-products", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          apiKey: apiKey === "********" ? undefined : apiKey.trim(),
        }),
      });

      const data = await response.json();

      if (data.success) {
        setProducts(data.data.products);
        toast.success(data.message);

        const allIndexes = new Set<number>(
          data.data.products.map((_: any, i: number) => i),
        );
        setSelectedProducts(allIndexes);
      } else {
        toast.error(data.message || t("easyOrdersImport.errorFetch"));
      }
    } catch (error: any) {
      console.error("Error fetching products:", error);
      toast.error(t("easyOrdersImport.errorConnection"));
    } finally {
      setLoading(false);
    }
  };

  const syncOrders = async () => {
    setSyncing(true);
    try {
      const response = await fetch("/api/v1/easy-orders/sync-orders", {
        method: "POST",
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        toast.success(t("easyOrdersImport.successSync") || "تمت المزامنة بنجاح");
        loadSyncLogs();
        loadSettings();
      } else {
        toast.error(data.message);
      }
    } catch (error) {
      toast.error(t("common.error"));
    } finally {
      setSyncing(false);
    }
  };

  // مسح البيانات
  const clearData = () => {
    setProducts([]);
    setSelectedProducts(new Set());
    setSearchTerm("");
  };

  // استيراد المنتجات المحددة
  const importProducts = async () => {
    if (selectedProducts.size === 0) {
      toast.error(t("easyOrdersImport.errorSelectOne"));
      return;
    }

    setImporting(true);
    try {
      const selectedProductsList = Array.from(selectedProducts).map(
        (index) => products[index],
      );

      const response = await fetch("/api/v1/easy-orders/import-selected", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          products: selectedProductsList,
        }),
      });

      const data = await response.json();

      if (data.success) {
        const { imported, failed, skipped } = data.data;

        let message = t("easyOrdersImport.successImport", { imported });
        if (skipped > 0)
          message += " | " + t("easyOrdersImport.skipped", { count: skipped });
        if (failed > 0)
          message += " | " + t("easyOrdersImport.failed", { count: failed });

        toast.success(message);
        clearData();
      } else {
        toast.error(data.message || t("easyOrdersImport.errorImport"));
      }
    } catch (error: any) {
      console.error("Error importing products:", error);
      toast.error(t("easyOrdersImport.errorImportConnection"));
    } finally {
      setImporting(false);
    }
  };

  // تحديد/إلغاء تحديد منتج
  const toggleProduct = (index: number) => {
    const newSelected = new Set(selectedProducts);
    if (newSelected.has(index)) {
      newSelected.delete(index);
    } else {
      newSelected.add(index);
    }
    setSelectedProducts(newSelected);
  };

  // تحديد/إلغاء تحديد الكل
  const toggleAll = () => {
    if (selectedProducts.size === filteredProducts.length) {
      setSelectedProducts(new Set());
    } else {
      const allIndexes = new Set(
        filteredProducts.map((p) => products.indexOf(p)),
      );
      setSelectedProducts(allIndexes);
    }
  };

  // فلترة المنتجات حسب البحث
  const filteredProducts = products.filter(
    (product) =>
      product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.description?.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 p-6" dir="rtl">
      <div className="w-full">
        {/* Navigation Tabs */}
        <div className="flex border-b border-gray-200 dark:border-gray-700 mb-6">
          <button
            onClick={() => setActiveTab("products")}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 ${activeTab === "products"
                ? "border-b-2 border-blue-600 text-blue-600"
                : "text-gray-500 hover:text-gray-700"
              }`}
          >
            <ShoppingBagIcon className="h-5 w-5" />
            استيراد المنتجات
          </button>
          <button
            onClick={() => setActiveTab("orders")}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 ${activeTab === "orders"
                ? "border-b-2 border-blue-600 text-blue-600"
                : "text-gray-500 hover:text-gray-700"
              }`}
          >
            <ArrowPathIcon className="h-5 w-5" />
            مزامنة الطلبات والإعدادات
          </button>
        </div>

        {activeTab === "products" ? (
          <>
            {/* Form */}
            {products.length === 0 && (
              <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 mb-6">
                <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4">
                  استيراد المنتجات من Easy Orders
                </h2>

                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      مفتاح الـ API الخاص بـ Easy Orders *
                    </label>
                    <input
                      type="password"
                      value={apiKey}
                      onChange={(e) => setApiKey(e.target.value)}
                      placeholder="أدخل مفتاح الـ API هنا..."
                      className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
                    />
                  </div>

                  <button
                    onClick={fetchProducts}
                    disabled={loading || !apiKey.trim()}
                    className="w-full px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-colors flex items-center justify-center gap-2"
                  >
                    {loading ? (
                      <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                    ) : (
                      <MagnifyingGlassIcon className="h-5 w-5" />
                    )}
                    جلب المنتجات
                  </button>
                </div>
              </div>
            )}

            {/* List */}
            {products.length > 0 && (
              <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6">
                <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6">
                  <div>
                    <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
                      المنتجات المتاحة ({filteredProducts.length})
                    </h2>
                    <p className="text-sm text-gray-600">تم تحديد {selectedProducts.size} منتج</p>
                  </div>
                  <div className="flex gap-3">
                    <button onClick={toggleAll} className="px-4 py-2 border rounded-lg">
                      {selectedProducts.size === filteredProducts.length ? "إلغاء تحديد الكل" : "تحديد الكل"}
                    </button>
                    <button
                      onClick={importProducts}
                      className="px-6 py-2 bg-green-600 text-white rounded-lg flex items-center gap-2"
                      disabled={importing}
                    >
                      {importing && <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>}
                      استيراد المحدد
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {filteredProducts.map((product, index) => {
                    const originalIndex = products.indexOf(product);
                    const isSelected = selectedProducts.has(originalIndex);
                    return (
                      <div
                        key={originalIndex}
                        onClick={() => toggleProduct(originalIndex)}
                        className={`border-2 rounded-xl p-4 cursor-pointer transition-all ${isSelected ? "border-blue-500 bg-blue-50 dark:bg-blue-900/10" : "border-gray-200 dark:border-gray-700"}`}
                      >
                        {product.images?.[0] && (
                          <img
                            src={`/api/proxy-image?url=${encodeURIComponent(product.images[0])}`}
                            className="w-full h-40 object-cover rounded-lg mb-3"
                            alt=""
                          />
                        )}
                        <h3 className="font-bold mb-1">{product.name}</h3>
                        <p className="text-blue-600 font-bold">{product.price} ج.م</p>
                        <p className="text-xs text-gray-500 mt-1">الكمية: {product.stock}</p>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </>
        ) : (
          <div className="space-y-6">
            {/* Settings Card */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 border border-gray-200 dark:border-gray-700">
              <div className="flex items-center gap-3 mb-6">
                <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                  <Cog6ToothIcon className="h-6 w-6 text-blue-600" />
                </div>
                <h2 className="text-xl font-bold">إعدادات الربط</h2>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium mb-1">مفتاح الـ API</label>
                    <input
                      type="password"
                      value={apiKey}
                      onChange={(e) => setApiKey(e.target.value)}
                      className="w-full px-4 py-2 border rounded-lg bg-gray-50 dark:bg-gray-700"
                    />
                  </div>
                  <button
                    onClick={saveSettings}
                    disabled={loading}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                  >
                    {loading ? "جاري الحفظ..." : "حفظ الإعدادات"}
                  </button>
                </div>

                <div className="bg-gray-50 dark:bg-gray-700/50 rounded-xl p-4">
                  <h3 className="font-semibold mb-3 flex items-center gap-2">
                    <CheckCircleIcon className="h-5 w-5 text-green-500" />
                    حالة المزامنة التلقائية
                  </h3>
                  {settings ? (
                    <div className="space-y-2 text-sm">
                      <div className="flex justify-between">
                        <span className="text-gray-500">آخر مزامنة ناجحة:</span>
                        <span className="font-medium">
                          {settings.lastSyncAt ? new Date(settings.lastSyncAt).toLocaleString("ar-EG") : "لم تتم بعد"}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-500">حالة آخر عملية:</span>
                        <span className={`font-medium ${settings.lastSyncStatus === 'success' ? 'text-green-600' : 'text-red-500'}`}>
                          {settings.lastSyncStatus === 'success' ? 'ناجحة' : 'فاشلة'}
                        </span>
                      </div>
                    </div>
                  ) : (
                    <p className="text-sm text-gray-500">لم يتم إعداد الربط بعد</p>
                  )}
                  <button
                    onClick={syncOrders}
                    disabled={syncing || !settings?.hasApiKey}
                    className="w-full mt-4 px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center justify-center gap-2 transition-all shadow-md shadow-indigo-200 dark:shadow-none disabled:opacity-50"
                  >
                    {syncing ? (
                      <ArrowPathIcon className="h-5 w-5 animate-spin" />
                    ) : (
                      <ArrowPathIcon className="h-5 w-5" />
                    )}
                    مزامنة الطلبات الآن
                  </button>
                </div>
              </div>
            </div>

            {/* Logs Card */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-200 dark:border-gray-700">
              <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-orange-50 dark:bg-orange-900/20 rounded-lg">
                    <DocumentTextIcon className="h-6 w-6 text-orange-600" />
                  </div>
                  <h2 className="text-xl font-bold">سجلات المزامنة</h2>
                </div>
                <button
                  onClick={loadSyncLogs}
                  className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors"
                >
                  <ArrowPathIcon className="h-5 w-5 text-gray-400" />
                </button>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-right text-sm">
                  <thead className="bg-gray-50 dark:bg-gray-700/50 text-gray-500 border-b border-gray-100 dark:border-gray-700">
                    <tr>
                      <th className="px-6 py-4 font-semibold">التوقيت</th>
                      <th className="px-6 py-4 font-semibold">الحالة</th>
                      <th className="px-6 py-4 font-semibold">العناصر</th>
                      <th className="px-6 py-4 font-semibold">المدة</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50 dark:divide-gray-700">
                    {syncLogs.length > 0 ? (
                      syncLogs.map((log) => (
                        <tr key={log.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors">
                          <td className="px-6 py-4 whitespace-nowrap">
                            {new Date(log.startedAt).toLocaleString("ar-EG")}
                          </td>
                          <td className="px-6 py-4">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${log.status === 'SUCCESS' ? 'bg-green-100 text-green-700' :
                                log.status === 'RUNNING' ? 'bg-blue-100 text-blue-700' : 'bg-red-100 text-red-700'
                              }`}>
                              {log.status === 'SUCCESS' ? 'ناجحة' : log.status === 'RUNNING' ? 'جاري العمل' : 'فاشلة'}
                            </span>
                          </td>
                          <td className="px-6 py-4">
                            {log.successCount} نجاح | {log.failedCount} فشل
                          </td>
                          <td className="px-6 py-4 text-gray-500">
                            {log.completedAt ? `${Math.floor((new Date(log.completedAt).getTime() - new Date(log.startedAt).getTime()) / 1000)} ثانية` : "-"}
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan={4} className="px-6 py-8 text-center text-gray-400">لا توجد سجلات حتى الآن</td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default EasyOrdersImport;

import React, { useState, useEffect } from "react";
import { apiClient } from "../../services/apiClient";
import { toast } from "react-hot-toast";
import { useAuth } from "../../hooks/useAuthSimple";
import { buildStoreUrl } from "../../utils/storeUrl";
import {
  MagnifyingGlassIcon,
  CheckCircleIcon,
  XCircleIcon,
  TrashIcon,
  StarIcon,
} from "@heroicons/react/24/solid";
import { StarIcon as StarOutlineIcon } from "@heroicons/react/24/outline";

interface Review {
  id: string;
  customerName: string;
  customerEmail?: string;
  customerPhone?: string;
  rating: number;
  title?: string;
  comment?: string;
  isApproved: boolean;
  helpfulCount: number;
  createdAt: string;
  product: {
    id: string;
    name: string;
    images?: string | string[];
  };
}

interface Pagination {
  page: number;
  limit: number;
  total: number;
  pages: number;
}

const ProductReviews: React.FC = () => {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();
  const [pagination, setPagination] = useState<Pagination>({
    page: 1,
    limit: 20,
    total: 0,
    pages: 0,
  });
  const [filters, setFilters] = useState({
    isApproved: "all" as "all" | "true" | "false",
    rating: "" as string,
    productId: "" as string,
  });
  const [search, setSearch] = useState("");

  useEffect(() => {
    fetchReviews();
  }, [pagination.page, filters]);

  const fetchReviews = async () => {
    try {
      setLoading(true);
      const params: any = {
        page: pagination.page,
        limit: pagination.limit,
      };

      if (filters.isApproved !== "all") {
        params.isApproved = filters.isApproved;
      }

      if (filters.rating) {
        params.rating = filters.rating;
      }

      if (filters.productId) {
        params.productId = filters.productId;
      }

      const response = await apiClient.get("/reviews", { params });

      if (response.data.success) {
        setReviews(response.data.data.reviews || []);
        setPagination(response.data.data.pagination || pagination);
      }
    } catch (error: any) {
      console.error("Error fetching reviews:", error);
      toast.error("حدث خطأ في جلب التقييمات");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (reviewId: string) => {
    try {
      const response = await apiClient.put(`/reviews/${reviewId}/approve`, {});
      if (response.data.success) {
        toast.success("تم الموافقة على التقييم بنجاح");
        fetchReviews();
      }
    } catch (error: any) {
      console.error("Error approving review:", error);
      toast.error("حدث خطأ في الموافقة على التقييم");
    }
  };

  const handleReject = async (reviewId: string) => {
    try {
      const response = await apiClient.put(`/reviews/${reviewId}/reject`, {});
      if (response.data.success) {
        toast.success("تم رفض التقييم بنجاح");
        fetchReviews();
      }
    } catch (error: any) {
      console.error("Error rejecting review:", error);
      toast.error("حدث خطأ في رفض التقييم");
    }
  };

  const handleDelete = async (reviewId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا التقييم؟")) {
      return;
    }

    try {
      const response = await apiClient.delete(`/reviews/${reviewId}`);
      if (response.data.success) {
        toast.success("تم حذف التقييم بنجاح");
        fetchReviews();
      }
    } catch (error: any) {
      console.error("Error deleting review:", error);
      toast.error("حدث خطأ في حذف التقييم");
    }
  };

  const parseImages = (images: string | string[] | undefined): string[] => {
    if (!images) return [];
    if (Array.isArray(images)) return images;
    if (typeof images === "string") {
      try {
        const parsed = JSON.parse(images);
        return Array.isArray(parsed) ? parsed : [images];
      } catch {
        return [images];
      }
    }
    return [];
  };

  const renderStars = (rating: number) => {
    return (
      <div className="flex items-center gap-1">
        {[1, 2, 3, 4, 5].map((star) =>
          star <= rating ? (
            <StarIcon key={star} className="h-4 w-4 text-yellow-400" />
          ) : (
            <StarOutlineIcon key={star} className="h-4 w-4 text-gray-300" />
          ),
        )}
      </div>
    );
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const prepareStorefrontContext = () => {
    const slug = user?.company?.slug;
    if (slug && slug.trim().length > 0) return;

    const companyId =
      user?.companyId ||
      localStorage.getItem("companyId") ||
      new URLSearchParams(window.location.search).get("companyId");

    if (companyId) {
      localStorage.setItem("storefront_companyId", companyId);
    }
  };

  const getProductUrl = (productId: string) => {
    const base = `/shop/products/${productId}`;
    const slug = user?.company?.slug;
    const companyId = user?.companyId || user?.company?.id || null;
    const customDomain = user?.company?.customDomain;

    if (slug && slug.trim().length > 0) {
      return buildStoreUrl(slug, base, customDomain || undefined, companyId);
    }

    return base;
  };

  const filteredReviews = reviews.filter((review) => {
    if (!search) return true;
    const searchLower = search.toLowerCase();
    return (
      review.customerName.toLowerCase().includes(searchLower) ||
      review.product.name.toLowerCase().includes(searchLower) ||
      (review.comment && review.comment.toLowerCase().includes(searchLower)) ||
      (review.title && review.title.toLowerCase().includes(searchLower))
    );
  });

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">
          إدارة التقييمات والمراجعات
        </h1>
        <p className="text-gray-600">إدارة ومراجعة تقييمات المنتجات</p>
      </div>

      {/* Filters */}
      <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {/* Search */}
          <div className="md:col-span-2">
            <div className="relative">
              <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
              <input
                type="text"
                placeholder="ابحث عن تقييم..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pr-10 pl-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
          </div>

          {/* Status Filter */}
          <div>
            <select
              value={filters.isApproved}
              onChange={(e) =>
                setFilters({
                  ...filters,
                  isApproved: e.target.value as "all" | "true" | "false",
                })
              }
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
            >
              <option value="all">جميع الحالات</option>
              <option value="true">موافق عليها</option>
              <option value="false">في انتظار الموافقة</option>
            </select>
          </div>

          {/* Rating Filter */}
          <div>
            <select
              value={filters.rating}
              onChange={(e) =>
                setFilters({ ...filters, rating: e.target.value })
              }
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
            >
              <option value="">جميع التقييمات</option>
              <option value="5">5 نجوم</option>
              <option value="4">4 نجوم</option>
              <option value="3">3 نجوم</option>
              <option value="2">2 نجوم</option>
              <option value="1">1 نجم</option>
            </select>
          </div>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="bg-white rounded-lg shadow-sm p-4">
          <div className="text-sm text-gray-600 mb-1">إجمالي التقييمات</div>
          <div className="text-2xl font-bold text-gray-900">
            {pagination.total}
          </div>
        </div>
        <div className="bg-white rounded-lg shadow-sm p-4">
          <div className="text-sm text-gray-600 mb-1">موافق عليها</div>
          <div className="text-2xl font-bold text-green-600">
            {reviews.filter((r) => r.isApproved).length}
          </div>
        </div>
        <div className="bg-white rounded-lg shadow-sm p-4">
          <div className="text-sm text-gray-600 mb-1">في انتظار الموافقة</div>
          <div className="text-2xl font-bold text-yellow-600">
            {reviews.filter((r) => !r.isApproved).length}
          </div>
        </div>
      </div>

      {/* Reviews List */}
      <div className="bg-white rounded-lg shadow-sm">
        {loading ? (
          <div className="flex justify-center items-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
          </div>
        ) : filteredReviews.length === 0 ? (
          <div className="text-center py-12 text-gray-500">لا توجد تقييمات</div>
        ) : (
          <div className="divide-y divide-gray-200">
            {filteredReviews.map((review) => {
              const productImages = parseImages(review.product.images);
              const productImage =
                productImages.length > 0
                  ? productImages[0]
                  : "/placeholder.png";

              return (
                <div
                  key={review.id}
                  className="p-6 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex items-start gap-4">
                    {/* Product Image */}
                    <div className="w-20 h-20 bg-gray-100 rounded-lg overflow-hidden flex-shrink-0">
                      <img
                        src={productImage}
                        alt={review.product.name}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          const target = e.target as HTMLImageElement;
                          target.src = "/placeholder.png";
                        }}
                      />
                    </div>

                    {/* Review Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between mb-2">
                        <div className="flex-1">
                          <div className="flex items-center gap-3 mb-1">
                            <h3 className="font-semibold text-gray-900">
                              {review.customerName}
                            </h3>
                            {renderStars(review.rating)}
                            <span
                              className={`px-2 py-1 rounded-full text-xs font-medium ${
                                review.isApproved
                                  ? "bg-green-100 text-green-800"
                                  : "bg-yellow-100 text-yellow-800"
                              }`}
                            >
                              {review.isApproved
                                ? "موافق عليها"
                                : "في انتظار الموافقة"}
                            </span>
                          </div>
                          <a
                            href={getProductUrl(review.product.id)}
                            onClick={prepareStorefrontContext}
                            className="text-sm text-indigo-600 hover:text-indigo-800 mb-2 block"
                          >
                            {review.product.name}
                          </a>
                          {review.title && (
                            <h4 className="font-medium text-gray-900 mb-1">
                              {review.title}
                            </h4>
                          )}
                          {review.comment && (
                            <p className="text-gray-700 text-sm mb-2">
                              {review.comment}
                            </p>
                          )}
                          <div className="flex items-center gap-4 text-xs text-gray-500">
                            <span>{formatDate(review.createdAt)}</span>
                            {review.customerEmail && (
                              <span>{review.customerEmail}</span>
                            )}
                            {review.customerPhone && (
                              <span>{review.customerPhone}</span>
                            )}
                            <span>مفيد ({review.helpfulCount})</span>
                          </div>
                        </div>
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-2 mt-3">
                        {!review.isApproved && (
                          <button
                            onClick={() => handleApprove(review.id)}
                            className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors text-sm"
                          >
                            <CheckCircleIcon className="h-4 w-4" />
                            موافقة
                          </button>
                        )}
                        {review.isApproved && (
                          <button
                            onClick={() => handleReject(review.id)}
                            className="flex items-center gap-2 px-4 py-2 bg-yellow-600 text-white rounded-lg hover:bg-yellow-700 transition-colors text-sm"
                          >
                            <XCircleIcon className="h-4 w-4" />
                            إلغاء الموافقة
                          </button>
                        )}
                        <button
                          onClick={() => handleDelete(review.id)}
                          className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors text-sm"
                        >
                          <TrashIcon className="h-4 w-4" />
                          حذف
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Pagination */}
        {pagination.pages > 1 && (
          <div className="flex items-center justify-between px-6 py-4 border-t border-gray-200">
            <div className="text-sm text-gray-600">
              صفحة {pagination.page} من {pagination.pages}
            </div>
            <div className="flex gap-2">
              <button
                onClick={() =>
                  setPagination({ ...pagination, page: pagination.page - 1 })
                }
                disabled={pagination.page === 1}
                className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                السابق
              </button>
              <button
                onClick={() =>
                  setPagination({ ...pagination, page: pagination.page + 1 })
                }
                disabled={pagination.page === pagination.pages}
                className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                التالي
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductReviews;

import React, { useState, useEffect, useCallback } from "react";
import { apiClient } from "../../services/apiClient";
import { toast } from "react-hot-toast";
import { useAuth } from "../../hooks/useAuthSimple";
import { buildStoreUrl } from "../../utils/storeUrl";
import {
  CheckCircleIcon,
  XCircleIcon,
  TrashIcon,
  StarIcon,
  MagnifyingGlassIcon,
} from "@heroicons/react/24/outline";
import { StarIcon as StarSolidIcon } from "@heroicons/react/24/solid";

interface Review {
  id: string;
  productId: string;
  productName?: string;
  customerName: string;
  customerEmail?: string;
  customerPhone?: string;
  rating: number;
  title?: string;
  comment?: string;
  isApproved: boolean;
  helpfulCount: number;
  createdAt: string;
  media?: Array<{
    id?: string;
    type: "image" | "video";
    url: string;
    poster?: string;
    alt?: string;
  }>;
}

interface Pagination {
  page: number;
  limit: number;
  total: number;
  pages: number;
}

const ProductReviewsSimple: React.FC = () => {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();
  const [pagination, setPagination] = useState<Pagination>({
    page: 1,
    limit: 20,
    total: 0,
    pages: 0,
  });
  const [filters, setFilters] = useState({
    isApproved: "all" as "all" | "true" | "false",
    rating: "",
  });
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [selectedReviews, setSelectedReviews] = useState<string[]>([]);

  const fetchReviews = useCallback(async () => {
    try {
      setLoading(true);
      const params: any = {
        page: pagination.page,
        limit: pagination.limit,
        search: debouncedSearch,
      };

      if (filters.isApproved !== "all") {
        params.isApproved = filters.isApproved;
      }

      if (filters.rating) {
        params.rating = filters.rating;
      }

      // استخدام apiClient بدلاً من axios مباشرة
      const response = await apiClient.get("/reviews", { params });

      if (response.data.success) {
        setReviews(response.data.data.reviews || []);
        setPagination((prev) => response.data.data.pagination || prev);
      } else {
        toast.error("حدث خطأ في جلب التقييمات");
      }
    } catch (error: any) {
      console.error("Error fetching reviews:", error);
      toast.error(error.response?.data?.error || "حدث خطأ في جلب التقييمات");
    } finally {
      setLoading(false);
    }
  }, [
    debouncedSearch,
    filters.isApproved,
    filters.rating,
    pagination.limit,
    pagination.page,
  ]);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search);
      setPagination((prev) => ({ ...prev, page: 1 }));
    }, 500);
    return () => clearTimeout(timer);
  }, [search]);

  // Fetch on page/filter/search change
  useEffect(() => {
    void fetchReviews();
  }, [fetchReviews]);

  const handleApprove = async (reviewId: string) => {
    try {
      const response = await apiClient.put(`/reviews/${reviewId}/approve`);
      if (response.data.success) {
        toast.success("تم الموافقة على التقييم بنجاح");
        fetchReviews();
      }
    } catch (error: any) {
      console.error("Error approving review:", error);
      toast.error(
        error.response?.data?.error || "حدث خطأ في الموافقة على التقييم",
      );
    }
  };

  const handleReject = async (reviewId: string) => {
    try {
      const response = await apiClient.put(`/reviews/${reviewId}/reject`);
      if (response.data.success) {
        toast.success("تم رفض التقييم بنجاح");
        fetchReviews();
      }
    } catch (error: any) {
      console.error("Error rejecting review:", error);
      toast.error(error.response?.data?.error || "حدث خطأ في رفض التقييم");
    }
  };

  const handleDelete = async (reviewId: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا التقييم؟")) {
      return;
    }

    try {
      const response = await apiClient.delete(`/reviews/${reviewId}`);
      if (response.data.success) {
        toast.success("تم حذف التقييم بنجاح");
        fetchReviews();
      }
    } catch (error: any) {
      console.error("Error deleting review:", error);
      toast.error(error.response?.data?.error || "حدث خطأ في حذف التقييم");
    }
  };

  const renderStars = (rating: number) => {
    return (
      <div className="flex items-center gap-1">
        {[1, 2, 3, 4, 5].map((star) =>
          star <= rating ? (
            <StarSolidIcon key={star} className="h-4 w-4 text-yellow-400" />
          ) : (
            <StarIcon key={star} className="h-4 w-4 text-gray-300" />
          ),
        )}
      </div>
    );
  };

  // Bulk Actions Handlers
  const toggleSelectAll = () => {
    if (selectedReviews.length === reviews.length) {
      setSelectedReviews([]);
    } else {
      setSelectedReviews(reviews.map((r) => r.id));
    }
  };

  const toggleReview = (id: string) => {
    if (selectedReviews.includes(id)) {
      setSelectedReviews((prev) => prev.filter((item) => item !== id));
    } else {
      setSelectedReviews((prev) => [...prev, id]);
    }
  };

  const handleBulkAction = async (action: "approve" | "reject" | "delete") => {
    if (!selectedReviews.length) return;

    if (
      action === "delete" &&
      !window.confirm(`هل أنت متأكد من حذف ${selectedReviews.length} تقييم؟`)
    ) {
      return;
    }

    try {
      const response = await apiClient.post("/reviews/bulk-action", {
        action,
        ids: selectedReviews,
      });

      if (response.data.success) {
        toast.success(response.data.message);
        setSelectedReviews([]);
        fetchReviews();
      }
    } catch (error: any) {
      console.error("Error executing bulk action:", error);
      toast.error(error.response?.data?.error || "حدث خطأ في تنفيذ العملية");
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const prepareStorefrontContext = () => {
    const slug = user?.company?.slug;
    if (slug && slug.trim().length > 0) return;

    const companyId =
      user?.companyId ||
      localStorage.getItem("companyId") ||
      new URLSearchParams(window.location.search).get("companyId");

    if (companyId) {
      localStorage.setItem("storefront_companyId", companyId);
    }
  };

  const getProductUrl = (productId: string) => {
    const base = `/shop/products/${productId}`;
    const slug = user?.company?.slug;
    const companyId = user?.companyId || user?.company?.id || null;
    const customDomain = user?.company?.customDomain;

    if (slug && slug.trim().length > 0) {
      return buildStoreUrl(slug, base, customDomain || undefined, companyId);
    }

    return base;
  };

  // Removed client-side filtering: filteredReviews
  // Stats now reflect current page only
  const approvedCount = reviews.filter((r) => r.isApproved).length;
  const pendingCount = reviews.filter((r) => !r.isApproved).length;

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
            إدارة التقييمات
          </h1>
          <p className="text-gray-600 dark:text-gray-300">
            إدارة ومراجعة تقييمات المنتجات
          </p>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              إجمالي التقييمات
            </div>
            <div className="text-2xl font-bold text-gray-900 dark:text-white">
              {pagination.total}
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              موافق عليها
            </div>
            <div className="text-2xl font-bold text-green-600 dark:text-green-400">
              {approvedCount}
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
            <div className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              في انتظار الموافقة
            </div>
            <div className="text-2xl font-bold text-yellow-600 dark:text-yellow-400">
              {pendingCount}
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Search */}
            <div className="md:col-span-2">
              <div className="relative">
                <MagnifyingGlassIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                <input
                  type="text"
                  placeholder="ابحث عن تقييم..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full pr-10 pl-4 py-2 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                />
              </div>
            </div>

            {/* Status Filter */}
            <div>
              <select
                value={filters.isApproved}
                onChange={(e) =>
                  setFilters({
                    ...filters,
                    isApproved: e.target.value as "all" | "true" | "false",
                  })
                }
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
              >
                <option value="all">جميع الحالات</option>
                <option value="true">موافق عليها</option>
                <option value="false">في انتظار الموافقة</option>
              </select>
            </div>

            {/* Rating Filter */}
            <div>
              <select
                value={filters.rating}
                onChange={(e) =>
                  setFilters({ ...filters, rating: e.target.value })
                }
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
              >
                <option value="">جميع التقييمات</option>
                <option value="5">5 نجوم</option>
                <option value="4">4 نجوم</option>
                <option value="3">3 نجوم</option>
                <option value="2">2 نجوم</option>
                <option value="1">1 نجم</option>
              </select>
            </div>
          </div>
        </div>
      </div>

      {/* Bulk Actions & Selection Toolbar */}
      <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <input
            type="checkbox"
            className="w-5 h-5 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
            checked={
              reviews.length > 0 && selectedReviews.length === reviews.length
            }
            onChange={toggleSelectAll}
            disabled={reviews.length === 0}
          />
          <span className="text-gray-700 dark:text-gray-300 font-medium">
            تحديد الكل ({selectedReviews.length})
          </span>
        </div>

        {selectedReviews.length > 0 && (
          <div className="flex items-center gap-2">
            <button
              onClick={() => handleBulkAction("approve")}
              className="flex items-center gap-2 px-3 py-1.5 bg-green-100 text-green-700 rounded-lg hover:bg-green-200 transition-colors text-sm font-medium"
            >
              <CheckCircleIcon className="h-4 w-4" />
              موافقة
            </button>
            <button
              onClick={() => handleBulkAction("reject")}
              className="flex items-center gap-2 px-3 py-1.5 bg-yellow-100 text-yellow-700 rounded-lg hover:bg-yellow-200 transition-colors text-sm font-medium"
            >
              <XCircleIcon className="h-4 w-4" />
              رفض
            </button>
            <button
              onClick={() => handleBulkAction("delete")}
              className="flex items-center gap-2 px-3 py-1.5 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 transition-colors text-sm font-medium"
            >
              <TrashIcon className="h-4 w-4" />
              حذف
            </button>
          </div>
        )}
      </div>

      {/* Reviews List */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow">
        {loading ? (
          <div className="flex justify-center items-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
          </div>
        ) : reviews.length === 0 ? (
          <div className="text-center py-12 text-gray-500 dark:text-gray-400">
            لا توجد تقييمات
          </div>
        ) : (
          <div className="divide-y divide-gray-200 dark:divide-gray-700">
            {reviews.map((review) => (
              <div
                key={review.id}
                className={`p-6 transition-colors ${
                  selectedReviews.includes(review.id)
                    ? "bg-indigo-50 dark:bg-indigo-900/20"
                    : "hover:bg-gray-50 dark:hover:bg-gray-700/50"
                }`}
              >
                <div className="flex items-start gap-4">
                  <div className="pt-1">
                    <input
                      type="checkbox"
                      className="w-5 h-5 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                      checked={selectedReviews.includes(review.id)}
                      onChange={() => toggleReview(review.id)}
                    />
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <h3 className="font-semibold text-gray-900 dark:text-white">
                        {review.customerName}
                      </h3>
                      {renderStars(review.rating)}
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-medium ${
                          review.isApproved
                            ? "bg-green-100 text-green-800"
                            : "bg-yellow-100 text-yellow-800"
                        }`}
                      >
                        {review.isApproved
                          ? "موافق عليها"
                          : "في انتظار الموافقة"}
                      </span>
                    </div>

                    {review.productName && (
                      <a
                        href={getProductUrl(review.productId)}
                        onClick={prepareStorefrontContext}
                        className="text-sm text-indigo-600 hover:text-indigo-800 mb-2 block"
                      >
                        {review.productName}
                      </a>
                    )}

                    {review.title && (
                      <h4 className="font-medium text-gray-900 dark:text-white mb-1">
                        {review.title}
                      </h4>
                    )}

                    {review.comment && (
                      <p className="text-gray-700 dark:text-gray-300 text-sm mb-2">
                        {review.comment}
                      </p>
                    )}

                    {Array.isArray(review.media) && review.media.length > 0 && (
                      <div className="mb-3 grid grid-cols-2 gap-3 sm:grid-cols-3">
                        {review.media.map((mediaItem, index) => (
                          <div
                            key={mediaItem.id || `${review.id}-media-${index}`}
                            className="overflow-hidden rounded-xl border border-gray-200 bg-gray-50 dark:border-gray-700 dark:bg-gray-900"
                          >
                            {mediaItem.type === "video" ? (
                              <video
                                src={mediaItem.url}
                                poster={mediaItem.poster}
                                controls
                                playsInline
                                className="h-36 w-full bg-black object-cover"
                              />
                            ) : (
                              <img
                                src={mediaItem.url}
                                alt={mediaItem.alt || review.title || review.customerName}
                                className="h-36 w-full object-cover"
                              />
                            )}
                          </div>
                        ))}
                      </div>
                    )}

                    <div className="flex items-center gap-4 text-xs text-gray-500 dark:text-gray-400 mt-2">
                      <span>{formatDate(review.createdAt)}</span>
                      {review.customerEmail && (
                        <span>{review.customerEmail}</span>
                      )}
                      {review.customerPhone && (
                        <span>{review.customerPhone}</span>
                      )}
                      <span>مفيد ({review.helpfulCount})</span>
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-2 ml-4">
                    {!review.isApproved && (
                      <button
                        onClick={() => handleApprove(review.id)}
                        className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors text-sm"
                      >
                        <CheckCircleIcon className="h-4 w-4" />
                        موافقة
                      </button>
                    )}
                    {review.isApproved && (
                      <button
                        onClick={() => handleReject(review.id)}
                        className="flex items-center gap-2 px-4 py-2 bg-yellow-600 text-white rounded-lg hover:bg-yellow-700 transition-colors text-sm"
                      >
                        <XCircleIcon className="h-4 w-4" />
                        إلغاء الموافقة
                      </button>
                    )}
                    <button
                      onClick={() => handleDelete(review.id)}
                      className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors text-sm"
                    >
                      <TrashIcon className="h-4 w-4" />
                      حذف
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Pagination */}
        {pagination.pages > 1 && (
          <div className="flex items-center justify-between px-6 py-4 border-t border-gray-200">
            <div className="text-sm text-gray-600">
              صفحة {pagination.page} من {pagination.pages}
            </div>
            <div className="flex gap-2">
              <button
                onClick={() =>
                  setPagination({ ...pagination, page: pagination.page - 1 })
                }
                disabled={pagination.page === 1}
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                السابق
              </button>
              <button
                onClick={() =>
                  setPagination({ ...pagination, page: pagination.page + 1 })
                }
                disabled={pagination.page === pagination.pages}
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                التالي
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductReviewsSimple;

import React, { useState, useRef } from "react";
import { useCurrency } from "../../hooks/useCurrency";
import { useDateFormat } from "../../hooks/useDateFormat";
import {
  PhotoIcon,
  XMarkIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import { getImageUrl } from "../../utils/imageUrl";

// Sub-components
import ProductsHeader from "./components/ProductsHeader";
import ProductsStats from "./components/ProductsStats";
import ProductsBulkBar from "./components/ProductsBulkBar";
import ProductsFilters from "./components/ProductsFilters";
import ProductsPagination from "./components/ProductsPagination";
import ProductsTable from "./components/ProductsTable";
import ProductsEmptyState from "./components/ProductsEmptyState";

// Hooks & Types
import { useProducts } from "./hooks/useProducts";
import { getStockStatusColor, getStockStatusText, getStockStatus } from "./components/ProductsTypes";
import {
  getWorkflowStatusColor,
  getWorkflowStatusLabel,
  isPublishedWorkflow,
} from "./utils/workflow";

// ================================================
// Products Page - Main container
// ================================================

const Products: React.FC = () => {
  const {
    products,
    isLoading,
    error,
    isDeletingAll,
    duplicatingProductId,
    isAdmin,
    currentPage,
    itemsPerPage,
    totalItems,
    sortField,
    sortDirection,
    selectedProducts,
    selectAll,
    editingProduct,
    editPrice,
    editStock,
    filters,
    hasActiveFilters,
    categories,
    allTags,
    sortedProducts,
    totalPages,
    startIndex,
    paginatedProducts,
    setCurrentPage,
    setItemsPerPage,
    handleFilterChange,
    handleSort,
    handleSelectAll,
    handleSelectProduct,
    handleBulkDelete,
    clearSelection,
    resetFilters,
    startQuickEdit,
    cancelQuickEdit,
    setEditPrice,
    setEditStock,
    saveQuickEdit,
    handleDuplicate,
    workflowLoadingId,
    handleWorkflowAction,
    handleDelete,
    handleDeleteAll,
    loadProducts,
    prepareStorefrontContext,
    getStorefrontUrl
  } = useProducts();

  const { formatPrice } = useCurrency();
  const { formatDate } = useDateFormat();

  // View mode
  const [viewMode, setViewMode] = useState<"table" | "grid">("table");
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const onBulkDelete = async () => {
    try {
      const count = await handleBulkDelete();
      if (count) toast.success(`تم حذف ${count} منتج بنجاح`);
    } catch (err) {
      toast.error("حدث خطأ أثناء الحذف");
    }
  };

  const onWorkflowAction = async (
    product: any,
    action: "save_draft" | "submit_review" | "approve" | "reject" | "publish" | "unpublish",
  ) => {
    try {
      let rejectionReason: string | null = null;
      if (action === "reject") {
        rejectionReason = prompt("سبب الرفض (اختياري):")?.trim() || null;
      }

      await handleWorkflowAction(product.id, action, rejectionReason);

      const messages: Record<string, string> = {
        save_draft: "تم حفظ المنتج كمسودة",
        submit_review: "تم إرسال المنتج للمراجعة",
        approve: "تم اعتماد المنتج",
        reject: "تم رفض المنتج",
        publish: "تم نشر المنتج",
        unpublish: "تم إلغاء نشر المنتج",
      };
      toast.success(messages[action] || "تم تحديث حالة المنتج");
    } catch (err: any) {
      toast.error(err?.response?.data?.message || err?.message || "حدث خطأ أثناء تحديث الحالة");
    }
  };

  const onSaveQuickEdit = async (id: string) => {
    try {
      const success = await saveQuickEdit(id);
      if (success) toast.success("تم تحديث المنتج بنجاح");
      else toast.error("فشل في تحديث المنتج");
    } catch (err) {
      toast.error("حدث خطأ أثناء التحديث");
    }
  };

  const onDuplicate = async (product: any) => {
    try {
      const success = await handleDuplicate(product);
      if (success) toast.success(`✅ تم نسخ المنتج "${product.name}" بنجاح`);
      else toast.error("فشل في نسخ المنتج");
    } catch (err: any) {
      toast.error(`❌ ${err?.response?.data?.error || err?.response?.data?.message || "حدث خطأ غير متوقع"}`);
    }
  };

  const onDeleteAll = async () => {
    try {
      const result = await handleDeleteAll();
      if (result) {
        toast.success(`تم حذف ${result.deletedProductsCount || 0} منتج و ${result.deletedVariantsCount || 0} متغير بنجاح`);
      }
    } catch (err: any) {
      toast.error(err.message || "حدث خطأ أثناء حذف المنتجات");
    }
  };

  const handleExport = async () => {
    // This logic is mostly API-bound, kept here for UI orchestration
    try {
      const { apiClient } = await import("../../services/apiClient");
      const r = await apiClient.get("products/export", { params: { format: "csv" }, responseType: "blob" });
      if (r.status === 200) {
        const blob = new Blob([r.data], { type: "text/csv" });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `products-${new Date().toISOString().split("T")[0]}.csv`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
        toast.success("تم تصدير المنتجات بنجاح!");
      }
    } catch {
      toast.error("فشل التصدير");
    }
  };

  const handleImportCSV = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const { apiClient } = await import("../../services/apiClient");
      const text = await file.text();
      const lines = text.split("\n").filter((l) => l.trim());
      const dataLines = lines.slice(1);
      const toImport = dataLines
        .map((line) => {
          const values = line.split(",");
          return {
            name: values[0]?.trim() || "",
            sku: values[1]?.trim() || `SKU-${Date.now()}`,
            price: parseFloat(values[2] || "0") || 0,
            stock: parseInt(values[4] || "0", 10) || 0,
            isActive: true,
          };
        })
        .filter((p) => p.name);
      let count = 0;
      for (const p of toImport) {
        const r = await apiClient.post("products", p);
        if (r.status === 200 || r.status === 201) count++;
      }
      loadProducts();
      setShowImportModal(false);
      toast.success(`تم استيراد ${count} منتج بنجاح`);
    } catch (err) {
      toast.error("حدث خطأ أثناء استيراد الملف");
    }
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  return (
    <div className="space-y-6">
      <ProductsHeader
        viewMode={viewMode}
        setViewMode={setViewMode}
        isAdmin={isAdmin}
        isDeletingAll={isDeletingAll}
        productsCount={products.length}
        isLoading={isLoading}
        onDeleteAll={onDeleteAll}
        onImportClick={() => setShowImportModal(true)}
        onExport={handleExport}
      />

      <ProductsStats
        products={products}
        totalItems={totalItems}
      />

      <ProductsBulkBar
        selectedCount={selectedProducts.size}
        onDelete={onBulkDelete}
        onClear={clearSelection}
      />

      <ProductsFilters
        filters={filters}
        categories={categories}
        allTags={allTags}
        showAdvancedFilters={showAdvancedFilters}
        onFilterChange={handleFilterChange}
        onToggleAdvancedFilters={() => setShowAdvancedFilters((v) => !v)}
        onResetAdvancedFilters={resetFilters}
      />

      {isLoading && (
        <div className="bg-white/80 dark:bg-gray-800/80 backdrop-blur-sm rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50 p-12 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
          <p className="text-gray-600 dark:text-gray-400 font-medium">جاري تحميل المنتجات...</p>
        </div>
      )}

      {error && (
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-700 rounded-xl p-6">
          <p className="text-sm text-red-800 dark:text-red-300">{error}</p>
        </div>
      )}

      {!isLoading && !error && products.length === 0 && <ProductsEmptyState />}

      {!isLoading && !error && products.length > 0 && viewMode === "table" && (
        <ProductsTable
          products={paginatedProducts}
          selectedProducts={selectedProducts}
          selectAll={selectAll}
          onSelectAll={handleSelectAll}
          onSelectProduct={handleSelectProduct}
          sortField={sortField}
          sortDirection={sortDirection}
          onSort={handleSort}
          formatPrice={formatPrice}
          formatDate={formatDate}
          getStorefrontUrl={getStorefrontUrl}
          prepareStorefrontContext={prepareStorefrontContext}
          editingProductId={editingProduct}
          editPrice={editPrice}
          editStock={editStock}
          onEditPriceChange={setEditPrice}
          onEditStockChange={setEditStock}
          onSaveQuickEdit={onSaveQuickEdit}
          onCancelQuickEdit={cancelQuickEdit}
          onStartQuickEdit={startQuickEdit}
          onDuplicate={onDuplicate}
          duplicatingProductId={duplicatingProductId}
          workflowLoadingId={workflowLoadingId}
          onWorkflowAction={onWorkflowAction}
          onDelete={handleDelete}
        />
      )}

      {!isLoading && !error && products.length > 0 && viewMode === "grid" && (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {paginatedProducts.map((product) => {
            const stockStatus = getStockStatus(product);
            return (
              <div
                key={product.id}
                className={`bg-white/80 dark:bg-gray-800/80 backdrop-blur-sm rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50 overflow-hidden hover:shadow-lg transition-all hover:-translate-y-0.5 ${selectedProducts.has(product.id) ? "ring-2 ring-indigo-500" : ""}`}
              >
                <div className="relative">
                  <input
                    type="checkbox"
                    checked={selectedProducts.has(product.id)}
                    onChange={() => handleSelectProduct(product.id)}
                    className="absolute top-2 right-2 h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded z-10"
                  />
                  <a
                    href={getStorefrontUrl(product)}
                    onClick={prepareStorefrontContext}
                    className="block"
                    target="_blank"
                    rel="noreferrer"
                  >
                    {product.mainImage || (product.images && product.images.length > 0) ? (
                      <img
                        src={getImageUrl(product.mainImage || product.images[0]) || ""}
                        alt={product.name}
                        className="w-full h-48 object-cover"
                        onError={(e) => { e.currentTarget.style.display = "none"; }}
                      />
                    ) : (
                      <div className="w-full h-48 bg-gray-200 dark:bg-gray-700 flex items-center justify-center">
                        <PhotoIcon className="h-12 w-12 text-gray-400" />
                      </div>
                    )}
                  </a>
                  <div className="absolute inset-x-3 top-3 flex items-center justify-between gap-2">
                    <span
                      className={`inline-flex px-2 py-1 text-[11px] font-semibold rounded-full ${getWorkflowStatusColor(
                        product.workflow.status,
                      )}`}
                    >
                      {getWorkflowStatusLabel(product.workflow.status)}
                    </span>
                    {!isPublishedWorkflow(product.workflow) && (
                      <span className="rounded-full bg-black/70 px-2 py-1 text-[11px] font-semibold text-white">
                        Preview
                      </span>
                    )}
                  </div>
                </div>
                <div className="p-4">
                  <h3 className="text-sm font-semibold text-gray-900 dark:text-white truncate">{product.name}</h3>
                  <div className="flex items-center justify-between mt-2">
                    <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{formatPrice(product.price)}</span>
                    <span className={`text-xs px-2 py-0.5 rounded-full ${getStockStatusColor(stockStatus)}`}>
                      {getStockStatusText(stockStatus)}
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {!isLoading && !error && sortedProducts.length > 0 && (
        <ProductsPagination
          currentPage={currentPage}
          totalPages={totalPages}
          totalItems={totalItems}
          itemsPerPage={itemsPerPage}
          startIndex={startIndex}
          hasActiveFilters={hasActiveFilters}
          sortedProductsLength={sortedProducts.length}
          onPageChange={setCurrentPage}
          onItemsPerPageChange={(count) => { setItemsPerPage(count); setCurrentPage(1); }}
        />
      )}

      {showImportModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl p-6 w-full max-w-md">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">استيراد منتجات من CSV</h3>
              <button onClick={() => setShowImportModal(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                <XMarkIcon className="h-6 w-6" />
              </button>
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept=".csv"
              onChange={handleImportCSV}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg text-sm"
            />
            <div className="mt-4 flex justify-end">
              <button onClick={() => setShowImportModal(false)} className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 rounded-lg hover:bg-gray-200">
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Products;

import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
    TrashIcon,
    ArrowPathIcon,
    ExclamationTriangleIcon,
    XMarkIcon,
    CheckIcon,
    PhotoIcon,
    ChevronLeftIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import { useCurrency } from "../../hooks/useCurrency";
import { useDateFormat } from "../../hooks/useDateFormat";

interface DeletedProduct {
    id: string;
    name: string;
    price: number;
    sku: string;
    barcode: string;
    stock: number;
    images: any[];
    category?: {
        id: string;
        name: string;
    };
    deletedAt: string;
    createdAt: string;
}

const ProductsTrash: React.FC = () => {
    const navigate = useNavigate();
    const { formatPrice } = useCurrency();
    const { formatDate } = useDateFormat();

    const [products, setProducts] = useState<DeletedProduct[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedProducts, setSelectedProducts] = useState<Set<string>>(new Set());
    const [restoring, setRestoring] = useState<string | null>(null);
    const [deleting, setDeleting] = useState<string | null>(null);

    // جلب المنتجات المحذوفة
    const fetchDeletedProducts = async () => {
        setLoading(true);
        try {
            const { apiClient } = await import("../../services/apiClient");
            const response = await apiClient.get("/products/trash/all");
            if (response.data.success) {
                setProducts(response.data.data || []);
            }
        } catch (error) {
            console.error("Error fetching deleted products:", error);
            toast.error("فشل في جلب المنتجات المحذوفة");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchDeletedProducts();
    }, []);

    // استعادة منتج واحد
    const handleRestore = async (productId: string) => {
        setRestoring(productId);
        try {
            const { apiClient } = await import("../../services/apiClient");
            const response = await apiClient.post(`/products/${productId}/restore`);
            if (response.data.success) {
                toast.success("تم استعادة المنتج بنجاح");
                setProducts((prev) => prev.filter((p) => p.id !== productId));
                setSelectedProducts((prev) => {
                    const newSet = new Set(prev);
                    newSet.delete(productId);
                    return newSet;
                });
            }
        } catch (error) {
            console.error("Error restoring product:", error);
            toast.error("فشل في استعادة المنتج");
        } finally {
            setRestoring(null);
        }
    };

    // حذف نهائي لمنتج واحد
    const handlePermanentDelete = async (productId: string) => {
        if (!window.confirm("هل أنت متأكد من حذف هذا المنتج نهائياً؟ لا يمكن التراجع عن هذا الإجراء.")) {
            return;
        }

        setDeleting(productId);
        try {
            const { apiClient } = await import("../../services/apiClient");
            const response = await apiClient.delete(`/products/${productId}/permanent`);
            if (response.data.success) {
                toast.success("تم حذف المنتج نهائياً");
                setProducts((prev) => prev.filter((p) => p.id !== productId));
                setSelectedProducts((prev) => {
                    const newSet = new Set(prev);
                    newSet.delete(productId);
                    return newSet;
                });
            }
        } catch (error) {
            console.error("Error permanently deleting product:", error);
            toast.error("فشل في حذف المنتج نهائياً");
        } finally {
            setDeleting(null);
        }
    };

    // استعادة الكل
    const handleRestoreAll = async () => {
        if (selectedProducts.size === 0) {
            toast.error("يرجى اختيار منتجات للاستعادة");
            return;
        }

        setLoading(true);
        try {
            const { apiClient } = await import("../../services/apiClient");
            let successCount = 0;
            for (const productId of selectedProducts) {
                try {
                    const response = await apiClient.post(`/products/${productId}/restore`);
                    if (response.data.success) {
                        successCount++;
                    }
                } catch (e) {
                    console.error(`Error restoring product ${productId}:`, e);
                }
            }

            if (successCount > 0) {
                toast.success(`تم استعادة ${successCount} منتج بنجاح`);
                fetchDeletedProducts();
                setSelectedProducts(new Set());
            }
        } catch (error) {
            console.error("Error restoring all products:", error);
            toast.error("فشل في استعادة المنتجات");
        } finally {
            setLoading(false);
        }
    };

    // حذف نهائي للكل
    const handlePermanentDeleteAll = async () => {
        if (selectedProducts.size === 0) {
            toast.error("يرجى اختيار منتجات للحذف");
            return;
        }

        if (!window.confirm(`هل أنت متأكد من حذف ${selectedProducts.size} منتج نهائياً؟ لا يمكن التراجع عن هذا الإجراء.`)) {
            return;
        }

        setLoading(true);
        try {
            const { apiClient } = await import("../../services/apiClient");
            let successCount = 0;
            for (const productId of selectedProducts) {
                try {
                    const response = await apiClient.delete(`/products/${productId}/permanent`);
                    if (response.data.success) {
                        successCount++;
                    }
                } catch (e) {
                    console.error(`Error permanently deleting product ${productId}:`, e);
                }
            }

            if (successCount > 0) {
                toast.success(`تم حذف ${successCount} منتج نهائياً`);
                fetchDeletedProducts();
                setSelectedProducts(new Set());
            }
        } catch (error) {
            console.error("Error deleting all products:", error);
            toast.error("فشل في حذف المنتجات");
        } finally {
            setLoading(false);
        }
    };

    // تحديد/إلغاء تحديد منتج
    const toggleSelect = (productId: string) => {
        setSelectedProducts((prev) => {
            const newSet = new Set(prev);
            if (newSet.has(productId)) {
                newSet.delete(productId);
            } else {
                newSet.add(productId);
            }
            return newSet;
        });
    };

    // تحديد/إلغاء تحديد الكل
    const toggleSelectAll = () => {
        if (selectedProducts.size === products.length) {
            setSelectedProducts(new Set());
        } else {
            setSelectedProducts(new Set(products.map((p) => p.id)));
        }
    };

    // الحصول على صورة المنتج
    const getProductImage = (images: string[]) => {
        if (!images || images.length === 0) return null;
        const firstImage = images[0];
        if (typeof firstImage === "string") {
            return firstImage;
        }
        return firstImage?.url || firstImage?.src || null;
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
            {/* Header */}
            <div className="bg-white dark:bg-gray-800 shadow-sm border-b border-gray-200 dark:border-gray-700">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <Link
                                to="/products"
                                className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                            >
                                <ChevronLeftIcon className="h-5 w-5 text-gray-600 dark:text-gray-400" />
                            </Link>
                            <div>
                                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                                    سلة المحذوفات
                                </h1>
                                <p className="text-sm text-gray-500 dark:text-gray-400">
                                    {products.length} منتج محذوف
                                </p>
                            </div>
                        </div>

                        <div className="flex items-center gap-3">
                            {selectedProducts.size > 0 && (
                                <>
                                    <button
                                        onClick={handleRestoreAll}
                                        disabled={loading}
                                        className="inline-flex items-center px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50"
                                    >
                                        <ArrowPathIcon className="h-5 w-5 mr-2" />
                                        استعادة ({selectedProducts.size})
                                    </button>
                                    <button
                                        onClick={handlePermanentDeleteAll}
                                        disabled={loading}
                                        className="inline-flex items-center px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50"
                                    >
                                        <TrashIcon className="h-5 w-5 mr-2" />
                                        حذف نهائي ({selectedProducts.size})
                                    </button>
                                </>
                            )}

                            <button
                                onClick={fetchDeletedProducts}
                                disabled={loading}
                                className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                                title="تحديث"
                            >
                                <ArrowPathIcon className={`h-5 w-5 text-gray-600 dark:text-gray-400 ${loading ? "animate-spin" : ""}`} />
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
                {loading && products.length === 0 ? (
                    <div className="flex items-center justify-center py-20">
                        <ArrowPathIcon className="h-8 w-8 text-gray-400 animate-spin" />
                    </div>
                ) : products.length === 0 ? (
                    <div className="text-center py-20">
                        <TrashIcon className="h-16 w-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" />
                        <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                            سلة المحذوفات فارغة
                        </h3>
                        <p className="text-gray-500 dark:text-gray-400 mb-6">
                            المنتجات المحذوفة ستظهر هنا
                        </p>
                        <Link
                            to="/products"
                            className="inline-flex items-center px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors"
                        >
                            العودة للمنتجات
                        </Link>
                    </div>
                ) : (
                    <>
                        {/* Bulk Actions Bar */}
                        <div className="mb-4 flex items-center justify-between">
                            <label className="flex items-center gap-2 cursor-pointer">
                                <input
                                    type="checkbox"
                                    checked={selectedProducts.size === products.length}
                                    onChange={toggleSelectAll}
                                    className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                                />
                                <span className="text-sm text-gray-700 dark:text-gray-300">
                                    تحديد الكل ({products.length})
                                </span>
                            </label>

                            <span className="text-sm text-gray-500 dark:text-gray-400">
                                {selectedProducts.size} محدد
                            </span>
                        </div>

                        {/* Products Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {products.map((product) => {
                                const image = getProductImage(product.images);
                                const isSelected = selectedProducts.has(product.id);
                                const isRestoring = restoring === product.id;
                                const isDeleting = deleting === product.id;

                                return (
                                    <div
                                        key={product.id}
                                        className={`bg-white dark:bg-gray-800 rounded-xl shadow-sm border transition-all ${isSelected
                                            ? "border-blue-500 ring-2 ring-blue-500/20"
                                            : "border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600"
                                            }`}
                                    >
                                        <div className="p-4">
                                            {/* Header with checkbox */}
                                            <div className="flex items-start gap-3 mb-3">
                                                <input
                                                    type="checkbox"
                                                    checked={isSelected}
                                                    onChange={() => toggleSelect(product.id)}
                                                    className="mt-1 w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                                                />

                                                {/* Image */}
                                                <div className="flex-shrink-0">
                                                    {image ? (
                                                        <img
                                                            src={image}
                                                            alt={product.name}
                                                            className="w-20 h-20 object-cover rounded-lg"
                                                        />
                                                    ) : (
                                                        <div className="w-20 h-20 bg-gray-100 dark:bg-gray-700 rounded-lg flex items-center justify-center">
                                                            <PhotoIcon className="h-8 w-8 text-gray-400" />
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Info */}
                                                <div className="flex-1 min-w-0">
                                                    <h3 className="font-semibold text-gray-900 dark:text-white truncate">
                                                        {product.name}
                                                    </h3>
                                                    {product.sku && (
                                                        <p className="text-xs text-gray-500 dark:text-gray-400">
                                                            SKU: {product.sku}
                                                        </p>
                                                    )}
                                                    <p className="text-sm font-bold text-blue-600 dark:text-blue-400 mt-1">
                                                        {formatPrice(product.price)}
                                                    </p>
                                                </div>
                                            </div>

                                            {/* Meta */}
                                            <div className="text-xs text-gray-500 dark:text-gray-400 space-y-1 mb-4">
                                                {product.category && (
                                                    <p>
                                                        <span className="font-medium">الفئة:</span>{" "}
                                                        {product.category.name}
                                                    </p>
                                                )}
                                                <p>
                                                    <span className="font-medium">تاريخ الحذف:</span>{" "}
                                                    {formatDate(product.deletedAt)}
                                                </p>
                                                {product.stock !== undefined && (
                                                    <p>
                                                        <span className="font-medium">المخزون:</span>{" "}
                                                        {product.stock}
                                                    </p>
                                                )}
                                            </div>

                                            {/* Actions */}
                                            <div className="flex gap-2">
                                                <button
                                                    onClick={() => handleRestore(product.id)}
                                                    disabled={isRestoring || isDeleting}
                                                    className="flex-1 inline-flex items-center justify-center px-3 py-2 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 rounded-lg text-sm font-medium hover:bg-green-200 dark:hover:bg-green-900/50 transition-colors disabled:opacity-50"
                                                >
                                                    {isRestoring ? (
                                                        <ArrowPathIcon className="h-4 w-4 animate-spin" />
                                                    ) : (
                                                        <>
                                                            <ArrowPathIcon className="h-4 w-4 mr-1" />
                                                            استعادة
                                                        </>
                                                    )}
                                                </button>
                                                <button
                                                    onClick={() => handlePermanentDelete(product.id)}
                                                    disabled={isRestoring || isDeleting}
                                                    className="flex-1 inline-flex items-center justify-center px-3 py-2 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400 rounded-lg text-sm font-medium hover:bg-red-200 dark:hover:bg-red-900/50 transition-colors disabled:opacity-50"
                                                >
                                                    {isDeleting ? (
                                                        <ArrowPathIcon className="h-4 w-4 animate-spin" />
                                                    ) : (
                                                        <>
                                                            <TrashIcon className="h-4 w-4 mr-1" />
                                                            حذف نهائي
                                                        </>
                                                    )}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

export default ProductsTrash;

// ================================================
// Shared Types for Products List Page
// ================================================

import type { ProductWorkflow } from "../utils/workflow";

export interface Product {
  id: string;
  slug?: string;
  name: string;
  description: string;
  price: number;
  comparePrice?: number;
  cost?: number;
  sku: string;
  category: string;
  categoryId?: string;
  images: string[];
  mainImage?: string;
  stock: number;
  lowStockThreshold: number;
  isActive: boolean;
  isHidden?: boolean;
  createdAt: Date;
  updatedAt: Date;
  tags: string[];
  weight?: number;
  dimensions?: { length: number; width: number; height: number };
  workflow: ProductWorkflow;
  productType: "simple" | "variable";
  variantsCount: number;
}

export type SortField = "name" | "price" | "stock" | "createdAt" | "updatedAt";
export type SortDirection = "asc" | "desc";
export type ViewMode = "table" | "grid";
export type StockStatus = "in-stock" | "low-stock" | "out-of-stock";

// ================================================
// Shared Utility Functions
// ================================================

export const getStockStatus = (product: Product): StockStatus => {
  if (product.stock === 0) return "out-of-stock";
  if (product.stock <= product.lowStockThreshold) return "low-stock";
  return "in-stock";
};

export const getStockStatusColor = (status: StockStatus): string => {
  switch (status) {
    case "in-stock":
      return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300";
    case "low-stock":
      return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300";
    case "out-of-stock":
      return "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300";
    default:
      return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300";
  }
};

export const getStockStatusText = (status: StockStatus): string => {
  switch (status) {
    case "in-stock":
      return "متوفر";
    case "low-stock":
      return "مخزون منخفض";
    case "out-of-stock":
      return "نفد المخزون";
    default:
      return "غير محدد";
  }
};

export const safeJsonParse = (jsonString: string | null, defaultValue: any = null) => {
  if (!jsonString || jsonString === "null") return defaultValue;
  try {
    return JSON.parse(jsonString);
  } catch (error) {
    console.warn("Failed to parse JSON:", jsonString, error);
    if (typeof jsonString === "string" && Array.isArray(defaultValue)) {
      return jsonString.split(",").map((t) => t.trim()).filter((t) => t.length > 0);
    }
    return defaultValue;
  }
};

import React from "react";
import { ProductAttribute } from "../../types";
import { XMarkIcon, PlusIcon, SwatchIcon } from "@heroicons/react/24/outline";

interface AttributesTabProps {
  attributeMode: "templates" | "custom";
  setAttributeMode: React.Dispatch<React.SetStateAction<"templates" | "custom">>;
  attributes: ProductAttribute[];
  setAttributes: React.Dispatch<React.SetStateAction<ProductAttribute[]>>;
  newAttributeName: string;
  setNewAttributeName: React.Dispatch<React.SetStateAction<string>>;
  newAttributeValuesList: string[];
  updateValueField: (index: number, value: string) => void;
  removeValueField: (index: number) => void;
  addValueField: () => void;
  addAttribute: () => void;
  removeAttribute: (id: string) => void;
  generateVariations: () => void;
  setActiveTab: (tab: string) => void;
  t: any;
}

export const AttributesTab: React.FC<AttributesTabProps> = ({
  attributeMode,
  setAttributeMode,
  attributes,
  setAttributes,
  newAttributeName,
  setNewAttributeName,
  newAttributeValuesList,
  updateValueField,
  removeValueField,
  addValueField,
  addAttribute,
  removeAttribute,
  generateVariations,
  setActiveTab,
  t,
}) => {
  const [editingAttrId, setEditingAttrId] = React.useState<string | null>(null);
  const [editName, setEditName] = React.useState("");
  const [editValues, setEditValues] = React.useState<string[]>([]);

  const handleValueKeyPress = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === "Enter") {
      e.preventDefault();
      addValueField();
      // Use setTimeout to focus the next input after it renders
      setTimeout(() => {
        const inputs = document.querySelectorAll(".attribute-value-input");
        const nextInput = inputs[index + 1] as HTMLInputElement;
        if (nextInput) nextInput.focus();
      }, 0);
    }
  };

  const beginEdit = (attr: ProductAttribute) => {
    setEditingAttrId(attr.id);
    setEditName(attr.name);
    setEditValues(attr.values);
  };

  const cancelEdit = () => {
    setEditingAttrId(null);
    setEditName("");
    setEditValues([]);
  };

  const saveEdit = () => {
    const cleanedValues = editValues.map((v) => v.trim()).filter(Boolean);
    if (!editName.trim() || cleanedValues.length === 0) {
      return;
    }
    setAttributes((prev) =>
      prev.map((a) =>
        a.id === editingAttrId ? { ...a, name: editName.trim(), values: cleanedValues } : a
      )
    );
    cancelEdit();
  };

  const updateEditValue = (idx: number, value: string) => {
    setEditValues((prev) => prev.map((v, i) => (i === idx ? value : v)));
  };

  const addEditValue = () => setEditValues((prev) => [...prev, ""]);

  const removeEditValue = (idx: number) =>
    setEditValues((prev) => prev.filter((_, i) => i !== idx));

  return (
    <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 animate-fade-in">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-medium text-gray-900 dark:text-white">
            {t("products.attributes.title")}
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            {t("products.attributes.description")}
          </p>
        </div>
      </div>

      {/* Mode Selector */}
      <div className="flex gap-4 mb-6">
        <button
          type="button"
          onClick={() => setAttributeMode("templates")}
          className={`flex-1 p-4 rounded-lg border-2 transition-all ${
            attributeMode === "templates"
              ? "border-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 dark:border-indigo-400"
              : "border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600"
          }`}
        >
          <div className="text-2xl mb-2">📦</div>
          <h4 className="font-medium text-gray-900 dark:text-white">
            {t("products.attributes.templates")}
          </h4>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            {t("products.attributes.templatesDesc")}
          </p>
        </button>
        <button
          type="button"
          onClick={() => setAttributeMode("custom")}
          className={`flex-1 p-4 rounded-lg border-2 transition-all ${
            attributeMode === "custom"
              ? "border-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 dark:border-indigo-400"
              : "border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600"
          }`}
        >
          <div className="text-2xl mb-2">✏️</div>
          <h4 className="font-medium text-gray-900 dark:text-white">
            {t("products.attributes.custom")}
          </h4>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            {t("products.attributes.customDesc")}
          </p>
        </button>
      </div>

      {/* Templates Mode */}
      {attributeMode === "templates" && (
        <div className="space-y-4">
          <h4 className="font-medium text-gray-700 dark:text-gray-300">
            {t("products.attributes.selectFromTemplates")}
          </h4>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {[
              {
                icon: "🎨",
                name: t("products.attributes.templateColor"),
                slug: "color",
                values: ["أسود", "أبيض", "أحمر", "أزرق", "أخضر"],
              },
              {
                icon: "📏",
                name: t("products.attributes.templateSize"),
                slug: "size",
                values: ["S", "M", "L", "XL", "XXL"],
              },
              {
                icon: "👟",
                name: t("products.attributes.templateShoeSize"),
                slug: "shoe_size",
                values: ["38", "39", "40", "41", "42", "43", "44"],
              },
              {
                icon: "🧵",
                name: t("products.attributes.templateMaterial"),
                slug: "material",
                values: ["قطن", "بوليستر", "جلد", "كتان"],
              },
              {
                icon: "💍",
                name: t("products.attributes.templateMetalColor"),
                slug: "metal_color",
                values: ["ذهبي", "فضي", "روز جولد", "أسود"],
              },
              {
                icon: "💾",
                name: t("products.attributes.templateCapacity"),
                slug: "capacity",
                values: ["64GB", "128GB", "256GB", "512GB"],
              },
              {
                icon: "⚖️",
                name: t("products.attributes.templateWeight"),
                slug: "weight",
                values: ["250g", "500g", "1kg", "2kg"],
              },
              {
                icon: "📦",
                name: t("products.attributes.templatePack"),
                slug: "pack",
                values: ["قطعة", "3 قطع", "6 قطع", "12 قطعة"],
              },
            ].map((template) => {
              const isAdded = attributes.some((a) => a.slug === template.slug);
              return (
                <button
                  key={template.slug}
                  type="button"
                  onClick={() => {
                    if (!isAdded) {
                      const newAttr: ProductAttribute = {
                        id: `attr_${template.slug}_${Date.now()}`,
                        name: template.name,
                        slug: template.slug,
                        values: template.values,
                        visible: true,
                        forVariations: true,
                      };
                      setAttributes((prev) => [...prev, newAttr]);
                    }
                  }}
                  disabled={isAdded}
                  className={`p-3 rounded-lg border-2 transition-all text-center ${
                    isAdded
                      ? "border-green-300 bg-green-50 dark:bg-green-900/30 dark:border-green-700 cursor-default"
                      : "border-dashed border-gray-300 dark:border-gray-600 hover:border-indigo-400 dark:hover:border-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/20"
                  }`}
                >
                  <span className="text-2xl">{template.icon}</span>
                  <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mt-1">
                    {template.name}
                  </p>
                  <p className="text-xs text-gray-500 dark:text-gray-400">
                    {template.values.slice(0, 3).join("، ")}...
                  </p>
                  {isAdded && (
                    <span className="text-xs text-green-600 dark:text-green-400 mt-1 block">
                      ✓ مضاف
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Custom Mode */}
      {attributeMode === "custom" && (
        <div className="bg-gray-50 dark:bg-gray-700/50 rounded-lg p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                {t("products.attributes.attributeName")}
              </label>
              <input
                type="text"
                value={newAttributeName}
                onChange={(e) => setNewAttributeName(e.target.value)}
                placeholder="مثل: اللون، الحجم، النكهة"
                className="block w-full border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 text-sm"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                {t("products.attributes.values")}{" "}
                <span className="text-gray-400 dark:text-gray-500 font-normal">
                  {t("products.attributes.valuesHint")}
                </span>
              </label>
              <div className="space-y-2">
                {newAttributeValuesList.map((value, index) => (
                  <div key={index} className="flex gap-2">
                    <input
                      type="text"
                      value={value}
                      onChange={(e) => updateValueField(index, e.target.value)}
                      onKeyDown={(e) => handleValueKeyPress(e, index)}
                      placeholder={index === 0 ? "القيمة الأولى" : "قيمة أخرى..."}
                      className="attribute-value-input flex-1 border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 text-sm"
                    />
                    {newAttributeValuesList.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeValueField(index)}
                        className="px-2 text-red-500 dark:text-red-400 hover:text-red-700 dark:hover:text-red-300"
                      >
                        <XMarkIcon className="h-5 w-5" />
                      </button>
                    )}
                  </div>
                ))}
                <button
                  type="button"
                  onClick={addValueField}
                  className="text-sm text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 flex items-center gap-1"
                >
                  <PlusIcon className="h-4 w-4" /> {t("products.attributes.addValue")}
                </button>
              </div>
            </div>
          </div>
          <div className="mt-4 flex justify-end">
            <button
              type="button"
              onClick={addAttribute}
              disabled={
                !newAttributeName.trim() ||
                !newAttributeValuesList.some((v) => v.trim())
              }
              className="px-4 py-2 bg-indigo-600 dark:bg-indigo-600 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-700 text-sm disabled:opacity-50 disabled:dark:opacity-50"
            >
              <PlusIcon className="h-4 w-4 inline ml-1" />{" "}
              {t("products.attributes.addAttribute")}
            </button>
          </div>
        </div>
      )}

      {/* Added Attributes List */}
      {attributes.length > 0 && (
        <div className="mt-6">
          <h4 className="font-medium text-gray-700 dark:text-gray-300 mb-3">
            {t("products.attributes.addedAttributes")} ({attributes.length}):
          </h4>
          <div className="space-y-2">
            {attributes.map((attr) => (
              <div
                key={attr.id}
                className="flex items-center justify-between bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg p-3"
              >
                {editingAttrId === attr.id ? (
                  <div className="w-full space-y-2">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                      <input
                        type="text"
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        className="border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 text-sm"
                        placeholder={t("products.attributes.attributeName")}
                      />
                      <div className="md:col-span-2 space-y-2">
                        {editValues.map((val, i) => (
                          <div key={i} className="flex gap-2">
                            <input
                              value={val}
                              onChange={(e) => updateEditValue(i, e.target.value)}
                              className="flex-1 border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 text-sm"
                              placeholder={t("products.attributes.values")}
                            />
                            {editValues.length > 1 && (
                              <button
                                type="button"
                                onClick={() => removeEditValue(i)}
                                className="text-red-500 dark:text-red-400 hover:text-red-700 dark:hover:text-red-300 px-2"
                              >
                                <XMarkIcon className="h-4 w-4" />
                              </button>
                            )}
                          </div>
                        ))}
                        <button
                          type="button"
                          onClick={addEditValue}
                          className="text-xs text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300"
                        >
                          + {t("products.attributes.addValue")}
                        </button>
                      </div>
                    </div>
                    <div className="flex items-center justify-between">
                      <label className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400">
                        <input
                          type="checkbox"
                          checked={attr.forVariations}
                          onChange={(e) =>
                            setAttributes((prev) =>
                              prev.map((a) =>
                                a.id === attr.id
                                  ? { ...a, forVariations: e.target.checked }
                                  : a
                              )
                            )
                          }
                          className="h-4 w-4 text-indigo-600 dark:text-indigo-500 rounded"
                        />
                        {t("products.attributes.forVariations")}
                      </label>
                      <div className="flex gap-2">
                        <button
                          type="button"
                          onClick={saveEdit}
                          disabled={!editName.trim() || !editValues.some((v) => v.trim())}
                          className="px-3 py-1 bg-indigo-600 text-white rounded-md text-sm disabled:opacity-50"
                        >
                          {t("common.save") ?? "حفظ"}
                        </button>
                        <button
                          type="button"
                          onClick={cancelEdit}
                          className="px-3 py-1 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-100 rounded-md text-sm"
                        >
                          {t("common.cancel") ?? "إلغاء"}
                        </button>
                      </div>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="flex-1">
                      <span className="font-medium text-gray-800 dark:text-gray-200">
                        {attr.name}
                      </span>
                      <div className="flex flex-wrap gap-1 mt-1">
                        {attr.values.map((val, i) => (
                          <span
                            key={i}
                            className="px-2 py-0.5 bg-indigo-100 dark:bg-indigo-900/40 text-indigo-700 dark:text-indigo-300 rounded text-xs"
                          >
                            {val}
                          </span>
                        ))}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <label className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400">
                        <input
                          type="checkbox"
                          checked={attr.forVariations}
                          onChange={(e) =>
                            setAttributes((prev) =>
                              prev.map((a) =>
                                a.id === attr.id
                                  ? { ...a, forVariations: e.target.checked }
                                  : a
                              )
                            )
                          }
                          className="h-4 w-4 text-indigo-600 dark:text-indigo-500 rounded"
                        />
                        {t("products.attributes.forVariations")}
                      </label>
                      <button
                        type="button"
                        onClick={() => beginEdit(attr)}
                        className="text-indigo-600 dark:text-indigo-300 hover:text-indigo-800 dark:hover:text-indigo-200 text-sm"
                      >
                        {t("common.edit") ?? "تعديل"}
                      </button>
                      <button
                        type="button"
                        onClick={() => removeAttribute(attr.id)}
                        className="text-red-500 dark:text-red-400 hover:text-red-700 dark:hover:text-red-300 p-1"
                      >
                        <XMarkIcon className="h-4 w-4" />
                      </button>
                    </div>
                  </>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Generate Variations Button */}
      {attributes.filter((a) => a.forVariations).length > 0 && (
        <div className="mt-6 flex items-center justify-between bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-700 rounded-lg p-4">
          <div>
            <p className="text-green-800 dark:text-green-300 font-medium">
              🔄 {t("products.attributes.generateVariants")}{" "}
              {attributes
                .filter((a) => a.forVariations)
                .reduce((acc, attr) => acc * attr.values.length, 1)}
            </p>
            <p className="text-green-600 dark:text-green-400 text-sm">
              من{" "}
              {attributes
                .filter((a) => a.forVariations)
                .map((a) => a.name)
                .join(" × ")}
            </p>
          </div>
          <button
            type="button"
            onClick={() => {
              generateVariations();
              setActiveTab("variants");
            }}
            className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 flex items-center gap-2"
          >
            {t("products.attributes.generateVariants")}
            <span className="transform rotate-180">→</span>
          </button>
        </div>
      )}

      {attributes.length === 0 && (
        <div className="mt-6 text-center py-8 text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
          <SwatchIcon className="h-12 w-12 mx-auto text-gray-400 dark:text-gray-500 mb-2" />
          <p>لم تضف أي صفات بعد</p>
          <p className="text-sm">اختر من القوالب الجاهزة أو أنشئ صفات مخصصة</p>
        </div>
      )}
    </div>
  );
};

import React from "react";
import { ProductFormData, Category, FieldErrors } from "../../types";
import { TagsInput } from "../shared/TagsInput";
import { InfoTooltip } from "../shared/InfoTooltip";
import RichTextEditor from "../../../../components/RichTextEditor";

interface BasicTabProps {
  formData: ProductFormData;
  categories: Category[];
  categoriesLoading: boolean;
  categoriesError: string | null;
  fieldErrors: FieldErrors;
  handleInputChange: (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => void;
  setFormData: React.Dispatch<React.SetStateAction<ProductFormData>>;
  getInputClassName: (fieldName: keyof FieldErrors) => string;
  workflowLabel: string;
  t: any;
}

export const BasicTab: React.FC<BasicTabProps> = ({
  formData,
  categories,
  categoriesLoading,
  categoriesError,
  fieldErrors,
  handleInputChange,
  setFormData,
  getInputClassName,
  workflowLabel,
  t,
}) => {
  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
        {/* Product Name */}
        <div className="col-span-2">
          <label
            htmlFor="name"
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
          >
            {t("products.productName")}
            <span className="text-red-500 mr-1">*</span>
          </label>
          <input
            type="text"
            name="name"
            id="name"
            required
            value={formData.name}
            onChange={handleInputChange}
            className={`mt-1 bg-white dark:bg-gray-700 block w-full shadow-sm sm:text-lg border-gray-300 dark:border-gray-600 rounded-md focus:ring-indigo-500 focus:border-indigo-500 py-3 ${getInputClassName(
              "name"
            )}`}
            placeholder={t("products.placeholders.productNamePlaceholder") as string}
          />
          {fieldErrors.name && (
            <p className="mt-2 text-sm text-red-600 dark:text-red-500 flex items-center">
              <span className="mx-1">⚠️</span> {fieldErrors.name}
            </p>
          )}
        </div>

        {/* Product Description */}
        <div className="col-span-2">
          <label
            htmlFor="description"
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
          >
            {t("products.description")}
          </label>
          <div className="mt-1">
            <RichTextEditor
              value={formData.description}
              onChange={(value) =>
                setFormData((prev) => ({
                  ...prev,
                  description: value,
                }))
              }
              placeholder={
                (t("products.placeholders.descriptionPlaceholder") as string) ||
                "اكتب وصف المنتج هنا..."
              }
              minHeight="220px"
            />
          </div>
        </div>

        {/* Category */}
        <div>
          <label
            htmlFor="category"
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
          >
            {t("products.category")}
            <span className="text-red-500 mr-1">*</span>
          </label>
          <div className="mt-1 flex rounded-md shadow-sm">
            <select
              id="category"
              name="category"
              required
              value={formData.category}
              onChange={handleInputChange}
              className={`flex-1 min-w-0 block w-full rounded-md bg-white dark:bg-gray-700 sm:text-sm border-gray-300 dark:border-gray-600 focus:ring-indigo-500 focus:border-indigo-500 ${getInputClassName(
                "category"
              )}`}
              disabled={categoriesLoading}
            >
              <option value="">
                {categoriesLoading
                  ? (t("products.messages.loadingCategories") as string)
                  : (t("products.placeholders.selectCategory") as string)}
              </option>
              {categories.map((category) => (
                <option key={category.id} value={category.id}>
                  {category.name}
                </option>
              ))}
            </select>
          </div>
          {categoriesError && (
            <p className="mt-2 text-sm text-red-600">{categoriesError}</p>
          )}
          {fieldErrors.category && (
            <p className="mt-2 text-sm text-red-600 flex items-center">
              <span className="mx-1">⚠️</span> {fieldErrors.category}
            </p>
          )}
        </div>

        {/* Slug */}
        <div>
          <label
            htmlFor="slug"
            className="flex items-center text-sm font-medium text-gray-700 dark:text-gray-300"
          >
            {t("products.slug")}
            <InfoTooltip text={t("products.tooltips.slugTooltip") as string} />
          </label>
          <div className="mt-1 flex rounded-md shadow-sm">
            <span className="inline-flex items-center px-3 rounded-r-md border border-l-0 border-gray-300 bg-gray-50 text-gray-500 sm:text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-gray-400">
              /product/
            </span>
            <input
              type="text"
              name="slug"
              id="slug"
              value={formData.slug}
              onChange={handleInputChange}
              className={`flex-1 min-w-0 bg-white dark:bg-gray-800 block w-full px-3 py-2 rounded-none rounded-l-md sm:text-sm border-gray-300 dark:border-gray-600 focus:ring-indigo-500 focus:border-indigo-500 ${getInputClassName(
                "slug"
              )}`}
              placeholder="مثال: custom-tshirt"
              dir="ltr"
            />
          </div>
          <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
            {t("products.slugHelp")}
          </p>
        </div>

        {/* Tags */}
        <div className="col-span-2">
          <TagsInput
            tags={formData.tags}
            onAddTag={(tag) => setFormData((prev) => ({ ...prev, tags: [...prev.tags, tag] }))}
            onRemoveTag={(tag) =>
              setFormData((prev) => ({
                ...prev,
                tags: prev.tags.filter((t) => t !== tag),
              }))
            }
            label={t("products.tags")}
            placeholder={t("products.placeholders.tagsPlaceholder")}
          />
        </div>

        {/* Workflow Note */}
        <div className="col-span-2 rounded-lg border border-indigo-100 bg-indigo-50/80 p-4 dark:border-indigo-900/40 dark:bg-indigo-900/20">
          <div className="space-y-1 text-sm">
            <p className="font-semibold text-indigo-900 dark:text-indigo-200">
              حالة المنتج الحالية: {workflowLabel}
            </p>
            <p className="text-indigo-700 dark:text-indigo-300">
              الحفظ كمسودة، الإرسال للمراجعة، الاعتماد، النشر وإلغاء النشر تتم من الشريط العلوي في الصفحة.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from "react";
import {
  ProductAttribute,
  ProductVariant,
  ProductVariantSettings,
} from "../../types";
import {
  EyeIcon,
  SwatchIcon,
  PhotoIcon,
  ExclamationTriangleIcon,
} from "@heroicons/react/24/outline";
import { normalizeImagePath } from "../../../../utils/imageUrl";
import {
  getVariantDisplaySupport,
  getVariantSettingImages,
  getVariantSettingKey,
  getVariantSettingStyle,
} from "../../utils/variantSettings";

interface DisplayTabProps {
  attributes: ProductAttribute[];
  variants: ProductVariant[];
  variantSettings: ProductVariantSettings;
  setVariantSettings: React.Dispatch<React.SetStateAction<ProductVariantSettings>>;
  setActiveTab: (tab: string) => void;
  uploadFiles: (files: File[]) => Promise<{ success: boolean; data: any[] }>;
  t: any;
}

export const DisplayTab: React.FC<DisplayTabProps> = ({
  attributes,
  variants,
  variantSettings,
  setVariantSettings,
  setActiveTab,
  uploadFiles,
  t,
}) => {
  return (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 rounded-lg text-indigo-600 dark:text-indigo-400">
            <EyeIcon className="h-6 w-6" />
          </div>
          <div>
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              {t("products.display.title")}
            </h3>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {t("products.display.description")}
            </p>
          </div>
        </div>

        {attributes.filter((a) => a.forVariations).length === 0 ? (
          <div className="text-center py-12 bg-gray-50 dark:bg-gray-700/50 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-600">
            <SwatchIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-500" />
            <h3 className="mt-2 text-sm font-medium text-gray-900 dark:text-gray-200">
              {t("products.display.noVariationAttributes")}
            </h3>
            <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
              {t("products.display.noVariationAttributesDesc")}
            </p>
            <button
              type="button"
              onClick={() => setActiveTab("attributes")}
              className="mt-6 inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 dark:bg-indigo-700 hover:bg-indigo-700 dark:hover:bg-indigo-800"
            >
              {t("products.display.goToAttributes")}
            </button>
          </div>
        ) : (
          <div className="space-y-8">
            {attributes
              .filter((a) => a.forVariations)
              .map((attr) => {
                const currentStyle = getVariantSettingStyle(variantSettings, attr);

                return (
                  <div
                    key={attr.id}
                    className="border border-gray-200 dark:border-gray-600 rounded-lg overflow-hidden"
                  >
                    <div className="bg-gray-50 dark:bg-gray-700 px-4 py-3 border-b border-gray-200 dark:border-gray-600 flex items-center justify-between">
                      <h4 className="font-medium text-gray-900 dark:text-gray-200 flex items-center gap-2">
                        <span className="bg-white dark:bg-gray-600 px-2 py-1 rounded border border-gray-200 dark:border-gray-500 text-xs text-gray-500 dark:text-gray-400 uppercase">
                          {attr.name}
                        </span>
                      </h4>
                      <select
                        value={currentStyle || ""}
                        onChange={(e) => {
                          const val = e.target.value as any;
                          setVariantSettings((prev: ProductVariantSettings) => {
                            const styleKey =
                              getVariantSettingKey(prev?.styles, attr) || attr.name;
                            const attributeImagesKey =
                              getVariantSettingKey(prev?.attributeImages, attr) || null;

                            const nextAttributeImages = { ...(prev?.attributeImages || {}) };
                            if (val !== "thumbnails" && attributeImagesKey) {
                              delete nextAttributeImages[attributeImagesKey];
                            }

                            return {
                              ...prev,
                              styles: {
                                ...(prev?.styles || {}),
                                [styleKey]: val,
                              },
                              attributeImages: nextAttributeImages,
                            };
                          });
                        }}
                        className="block w-48 rounded-md border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                      >
                        <option value="">{t("products.display.default")}</option>
                        <option value="buttons">{t("products.display.buttons")}</option>
                        <option value="circles">{t("products.display.circles")}</option>
                        <option value="dropdown">{t("products.display.dropdown")}</option>
                        <option value="thumbnails">
                          {t("products.display.thumbnails")}
                        </option>
                        <option value="radio">{t("products.display.radio")}</option>
                      </select>
                    </div>

                    <div className="p-4 bg-white dark:bg-gray-800">
                      {currentStyle === "thumbnails" && (
                        <>
                          <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                            {t("products.display.customizeImageLabel")}
                          </p>

                          {(() => {
                            const support = getVariantDisplaySupport(
                              attr,
                              variantSettings,
                              variants,
                            );

                            if (support.coveredValueCount === 0) {
                              const fallbackLabel = support.isColorAttribute
                                ? "دوائر الألوان"
                                : "الأزرار";

                              return (
                                <div className="mb-4 flex items-start gap-3 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-amber-900 dark:border-amber-500/30 dark:bg-amber-500/10 dark:text-amber-100">
                                  <ExclamationTriangleIcon className="h-5 w-5 shrink-0" />
                                  <div className="space-y-1">
                                    <p className="text-sm font-semibold">
                                      النمط المصغر يحتاج صورًا فعلية
                                    </p>
                                    <p className="text-xs leading-5 text-amber-800 dark:text-amber-100/80">
                                      لا توجد صور مرتبطة بقيم "{attr.name}" الآن، لذلك
                                      سيعود المتجر تلقائيًا إلى {fallbackLabel} عند الحفظ
                                      حتى لا يظهر العرض بشكل مكسور.
                                    </p>
                                  </div>
                                </div>
                              );
                            }

                            if (support.coveredValueCount < support.totalValues) {
                              return (
                                <div className="mb-4 rounded-lg border border-sky-200 bg-sky-50 px-4 py-3 text-sky-900 dark:border-sky-500/30 dark:bg-sky-500/10 dark:text-sky-100">
                                  <p className="text-sm font-semibold">
                                    التغطية الحالية غير مكتملة
                                  </p>
                                  <p className="text-xs leading-5 text-sky-800 dark:text-sky-100/80">
                                    يوجد صور لـ {support.coveredValueCount} من أصل{" "}
                                    {support.totalValues} قيمة. القيم غير المرتبطة بصورة
                                    ستظهر ببديل نصي داخل النمط المصغر.
                                  </p>
                                </div>
                              );
                            }

                            return null;
                          })()}

                          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                            {attr.values.map((value) => {
                              const attributeImagesKey =
                                getVariantSettingKey(
                                  variantSettings?.attributeImages,
                                  attr,
                                ) || attr.name;
                              const currentAttributeImages = getVariantSettingImages(
                                variantSettings,
                                attr,
                              );
                              const currentImage = currentAttributeImages[value];

                              return (
                                <div
                                  key={value}
                                  className="relative group border border-gray-200 dark:border-gray-600 rounded-lg p-2 hover:border-indigo-300 dark:hover:border-indigo-600 transition-colors"
                                >
                                  <p
                                    className="text-xs font-medium text-center mb-2 text-gray-700 dark:text-gray-300 truncate"
                                    title={value}
                                  >
                                    {value}
                                  </p>

                                  <div className="aspect-square bg-gray-50 dark:bg-gray-700 rounded-md overflow-hidden relative">
                                    {currentImage ? (
                                      <>
                                        <img
                                          src={currentImage}
                                          alt={value}
                                          className="w-full h-full object-cover"
                                        />
                                        <button
                                          type="button"
                                          onClick={() => {
                                            const newImages = { ...currentAttributeImages };
                                            delete newImages[value];
                                            setVariantSettings(
                                              (prev: ProductVariantSettings) => ({
                                                ...prev,
                                                styles: {
                                                  ...(prev?.styles || {}),
                                                },
                                                attributeImages: {
                                                  ...(prev?.attributeImages || {}),
                                                  [attributeImagesKey]: newImages,
                                                },
                                              }),
                                            );
                                          }}
                                          className="absolute top-1 right-1 bg-red-500 dark:bg-red-600 text-white rounded-full w-5 h-5 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity text-xs hover:bg-red-600 dark:hover:bg-red-700"
                                        >
                                          ×
                                        </button>
                                      </>
                                    ) : (
                                      <label className="flex flex-col items-center justify-center w-full h-full cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors">
                                        <PhotoIcon className="w-6 h-6 text-gray-400 dark:text-gray-500" />
                                        <span className="text-[10px] text-gray-500 dark:text-gray-400 mt-1">
                                          رفع صورة
                                        </span>
                                        <input
                                          type="file"
                                          className="hidden"
                                          accept="image/*"
                                          onChange={async (e) => {
                                            if (e.target.files?.[0]) {
                                              const file = e.target.files[0];
                                              try {
                                                const data = await uploadFiles([file]);
                                                if (data.success && data.data[0]) {
                                                  const rawUrl =
                                                    data.data[0].fullUrl || data.data[0].url;
                                                  const url =
                                                    normalizeImagePath(rawUrl) || rawUrl;
                                                  setVariantSettings(
                                                    (prev: ProductVariantSettings) => ({
                                                      ...prev,
                                                      styles: {
                                                        ...(prev?.styles || {}),
                                                      },
                                                      attributeImages: {
                                                        ...(prev?.attributeImages || {}),
                                                        [attributeImagesKey]: {
                                                          ...(getVariantSettingImages(
                                                            prev,
                                                            attr,
                                                          ) || {}),
                                                          [value]: url,
                                                        },
                                                      },
                                                    }),
                                                  );
                                                }
                                              } catch (err) {
                                                console.error(
                                                  "Error uploading attribute image",
                                                  err,
                                                );
                                              }
                                            }
                                          }}
                                        />
                                      </label>
                                    )}
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
          </div>
        )}
      </div>
    </div>
  );
};

import React from "react";
import { PhotoIcon, StarIcon, Bars4Icon, XMarkIcon } from "@heroicons/react/24/outline";
import {
  DndContext,
  closestCenter,
  useSensor,
  useSensors,
  PointerSensor,
  KeyboardSensor,
  DragEndEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  horizontalListSortingStrategy,
  useSortable,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { ProductFormData } from "../../types";
import { getImageUrl } from "../../../../utils/imageUrl";

const SortableImageItem = ({
  url,
  isMain,
  onSetMain,
  onRemove,
}: {
  url: string;
  isMain: boolean;
  onSetMain: () => void;
  onRemove: () => void;
}) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: url });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 2 : 1,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`relative group p-1 rounded-xl border-2 transition-all ${
        isMain ? "border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20" : "border-transparent"
      } ${isDragging ? "opacity-50" : ""}`}
    >
      <img
        src={getImageUrl(url) || url}
        alt=""
        className="h-24 w-full object-cover rounded-lg border border-gray-200 dark:border-gray-600 pointer-events-none"
      />

      {/* Main Image Badge */}
      {isMain && (
        <div className="absolute top-2 left-2 bg-yellow-500 text-white text-[10px] px-1.5 py-0.5 rounded shadow-sm font-bold flex items-center gap-0.5 pointer-events-none">
          <StarIcon className="w-3 h-3 fill-current" />
          الرئيسية
        </div>
      )}

      {/* Actions Overlay */}
      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity rounded-lg flex flex-col items-center justify-center gap-2">
        {/* Drag Handle */}
        <div
          {...attributes}
          {...listeners}
          className="p-1 cursor-grab active:cursor-grabbing text-white opacity-80 hover:opacity-100"
          title="سحب لإعادة الترتيب"
        >
          <Bars4Icon className="w-8 h-8 drop-shadow-md" />
        </div>

        <div className="flex items-center gap-2">
          {!isMain && (
            <button
              type="button"
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onSetMain();
              }}
              className="text-white hover:text-yellow-400 bg-black/50 p-1.5 rounded-full backdrop-blur-sm transition-colors"
              title="تعيين كصورة رئيسية"
            >
              <StarIcon className="w-4 h-4" />
            </button>
          )}

          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onRemove();
            }}
            className="text-white hover:text-red-400 bg-black/50 p-1.5 rounded-full backdrop-blur-sm transition-colors"
            title="حذف الصورة"
          >
            <XMarkIcon className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

interface MediaTabProps {
  formData: ProductFormData;
  setFormData: React.Dispatch<React.SetStateAction<ProductFormData>>;
  uploadedImages: string[];
  uploading: boolean;
  handleImageChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  handleDragEnd: (e: DragEndEvent) => void;
  removeUploadedImage: (url: string) => void;
  t: any;
}

export const MediaTab: React.FC<MediaTabProps> = ({
  formData,
  setFormData,
  uploadedImages,
  uploading,
  handleImageChange,
  handleDragEnd,
  removeUploadedImage,
  t,
}) => {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor)
  );

  const handleRemoveImage = (urlToRemove: string) => {
    setFormData((prev) => {
      if (prev.mainImage !== urlToRemove) {
        return prev;
      }

      const nextMainImage = uploadedImages.find((url) => url !== urlToRemove) || "";
      return {
        ...prev,
        mainImage: nextMainImage,
      };
    });

    void removeUploadedImage(urlToRemove);
  };

  return (
    <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 space-y-6 animate-fade-in">
      <h3 className="text-lg font-medium text-gray-900 dark:text-white">
        {t("products.media.title")}
      </h3>
      <div className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-6 text-center">
        <input
          type="file"
          multiple
          onChange={handleImageChange}
          className="hidden"
          id="images"
          accept="image/png, image/jpeg, image/gif, image/webp"
        />
        <label
          htmlFor="images"
          className="cursor-pointer text-indigo-600 dark:text-indigo-400 hover:text-indigo-500 dark:hover:text-indigo-300 block"
        >
          <PhotoIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-300" />
          <span className="mt-2 block text-sm font-medium text-gray-900 dark:text-white">
            {t("products.media.selectImages")}
          </span>
          <span className="mt-1 block text-xs text-gray-500 dark:text-gray-400">
            {t("products.media.imageFormats")}
          </span>
        </label>
      </div>
      
      {uploading && (
        <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-700 rounded-md p-4 flex items-center gap-3 animate-pulse">
           <div className="w-5 h-5 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-sm text-blue-700 dark:text-blue-300">
            {t("products.media.uploading")}
          </p>
        </div>
      )}

      {uploadedImages.length > 0 && (
        <div>
          <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-3">
            {t("products.media.uploadedImages")} ({uploadedImages.length})
          </p>
          <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
            <DndContext
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragEnd={handleDragEnd}
            >
              <SortableContext
                items={uploadedImages}
                strategy={horizontalListSortingStrategy}
              >
                {uploadedImages.map((url, idx) => (
                  <SortableImageItem
                    key={url}
                    url={url}
                    isMain={
                      formData.mainImage === url ||
                      (!formData.mainImage && idx === 0)
                    }
                    onSetMain={() =>
                      setFormData((prev) => ({ ...prev, mainImage: url }))
                    }
                    onRemove={() => handleRemoveImage(url)}
                  />
                ))}
              </SortableContext>
            </DndContext>
          </div>
        </div>
      )}
    </div>
  );
};

