                  {/* Variant Content */}
                  {isExpanded && (
                    <div className="border-t border-indigo-100 dark:border-indigo-900/30 bg-white dark:bg-gray-800 p-6 space-y-8 animate-slide-down">
                      {/* Section 1: Basic Info */}
