            <div className="space-y-4">
              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300">رسالة ترويجية (اختياري)</label>
              <textarea
                value={whatsappNotify.customMessage}
                onChange={(e) => setWhatsappNotify({ ...whatsappNotify, customMessage: e.target.value })}
                placeholder="اكتب رسالة مخصصة تظهر مع صورة المنتج وسعره..."
                className="w-full h-32 p-3 border-2 border-gray-100 dark:border-gray-700 dark:bg-gray-800 rounded-xl focus:border-indigo-500 outline-none transition-all resize-none text-sm text-gray-900 dark:text-white"
              />
              <p className="text-xs text-gray-500 dark:text-gray-400 italic">
                * سيتم إدراج اسم العميل، اسم المنتج، والسعر تلقائياً في الرسالة.
              </p>
            </div>
          </div>
        )}

        <div className="p-4 bg-amber-50 dark:bg-amber-900/20 rounded-xl border border-amber-100 dark:border-amber-800 flex gap-3">
          <div className="text-xl">💡</div>
          <p className="text-xs text-amber-800 dark:text-amber-300 leading-relaxed">
            نصيحة: تأكد من أن جلسة الواتساب متصلة في صفحة الإشعارات قبل الحفظ لضمان بدء الحملة فوراً.
          </p>
        </div>
      </div>
    </div>
  );
};

import { useState } from "react";
import { apiClient } from "../../../services/apiClient";
import { productApi } from "../../../utils/apiHelpers";
import { ProductFormData, ProductAttribute, ProductVariant } from "../types";
import { PRODUCT_PAGE_CHECKOUT_OVERRIDE_KEY } from "../../../utils/productPageCheckout";

interface UseProductApiProps {
  formData: ProductFormData;
  attributes: ProductAttribute[];
  variants: ProductVariant[];
  deletedVariantIds: string[];
  uploadedImages: string[];
  productMetadata: Record<string, any>;
  variantSettings: any;
  whatsappNotify: any;
  isEditMode: boolean;
  id?: string;
  t: any;
}

export const useProductApi = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const cleanVariantData = (variant: ProductVariant): any => {
    let imagesStr = null;
    if (variant.images && Array.isArray(variant.images) && variant.images.length > 0) {
      imagesStr = JSON.stringify(variant.images);
    } else if (typeof variant.images === "string") {
      imagesStr = variant.images;
    }

    const variantData: any = {
      name: variant.name,
      type: variant.type || "color",
      sku: variant.sku || null,
      price: variant.price !== undefined ? variant.price : null,
      comparePrice: variant.comparePrice !== undefined ? variant.comparePrice : null,
      cost: variant.cost !== undefined ? variant.cost : null,
      images: imagesStr,
      stock: variant.stock !== undefined ? variant.stock : 0,
      trackInventory: variant.trackInventory !== undefined ? variant.trackInventory : true,
      isActive: variant.isActive !== undefined ? variant.isActive : true,
      sortOrder: variant.sortOrder !== undefined ? variant.sortOrder : 0,
    };

    variantData.metadata = JSON.stringify({
      attributeValues: variant.attributeValues || null,
      description: variant.description || null,
      dimensions: variant.dimensions || null,
      weight: variant.weight || null,
      shippingClass: variant.shippingClass || null,
      allowBackorders: variant.allowBackorders || null,
      lowStockThreshold: variant.lowStockThreshold || null,
      image: variant.image || null,
    });

    return variantData;
  };

  const saveProduct = async (
    props: UseProductApiProps,
    onSuccess?: (product: any) => void,
  ) => {
    const {
      formData,
      attributes,
      variants,
      deletedVariantIds,
      uploadedImages,
      productMetadata,
      variantSettings,
      whatsappNotify,
      isEditMode,
      id,
      t
    } = props;

    setError(null);
    setLoading(true);

    try {
      // 1. Process base64 images in description (moved to component logic or simplified here)
      // For simplicity in the hook, we assume the description is already processed
      // Or we can keep the base64 processing here if it doesn't need external state

      // 2. Prepare Payload
      const productData = {
        name: formData.name,
        description: formData.description,
        slug: formData.slug || null,
        price: formData.price,
        comparePrice: formData.comparePrice || null,
        cost: formData.cost || null,
        sku: formData.sku || null,
        category: formData.category,
        stock: formData.trackInventory ? formData.stock : 0,
        trackInventory: formData.trackInventory,
        lowStockThreshold: formData.lowStockThreshold || 5,
        isActive: formData.isActive,
        isFeatured: formData.isFeatured || false,
        isHidden: formData.isHidden || false,
        showFakeStock: formData.showFakeStock || false,
        featuredPriority: formData.featuredPriority || 0,
        enableCheckoutForm: formData.enableCheckoutForm,
        showAddToCartButton: formData.showAddToCartButton,
        saleStartDate: formData.saleStartDate ? new Date(formData.saleStartDate).toISOString() : null,
        saleEndDate: formData.saleEndDate ? new Date(formData.saleEndDate).toISOString() : null,
        sizeGuide: formData.sizeGuide?.trim() || null,
        tags: formData.tags,
        weight: formData.weight || null,
        dimensions: formData.dimensions || null,
        images: uploadedImages,
        mainImage: formData.mainImage || (uploadedImages.length > 0 ? uploadedImages[0] : null),
        affiliateCommission: formData.affiliateCommission || 0,
        commissionType: formData.commissionType,
        allowAffiliateMarkup: formData.allowAffiliateMarkup,
        // SEO fields
        metaTitle: formData.metaTitle || null,
        metaDescription: formData.metaDescription || null,
        canonicalUrl: formData.canonicalUrl || null,
        variantSettings,
        metadata: JSON.stringify({
          ...productMetadata,
          variantSettings,
          [PRODUCT_PAGE_CHECKOUT_OVERRIDE_KEY]: Boolean(
            formData.enableCheckoutForm,
          ),
          attributes: attributes,
          shippingClass: formData.shippingClass || "standard",
          excludeFromFreeShipping: formData.excludeFromFreeShipping || false,
          // Inventory extras stored in metadata
          barcode: formData.barcode || null,
          isPreOrder: formData.isPreOrder || false,
          preOrderDate: formData.preOrderDate || null,
          preOrderMessage: formData.preOrderMessage || null,
          externalUrl: formData.externalUrl?.trim() || null,
          affiliateUrl: formData.externalUrl?.trim() || null,
          externalButtonLabel: formData.externalButtonLabel?.trim() || null,
          affiliateButtonLabel: formData.externalButtonLabel?.trim() || null,
          externalVendor: formData.externalVendor?.trim() || null,
          partnerName: formData.externalVendor?.trim() || null,
          externalDescription: formData.externalDescription?.trim() || null,
          affiliateDescription: formData.externalDescription?.trim() || null,
          externalOnly: Boolean(formData.externalOnly),
          externalAffiliateOnly: Boolean(formData.externalOnly),
          isExternalProduct: Boolean(formData.externalOnly),
        }),
      };

      if (isEditMode && id) {
        // UPDATE PRODUCT
        const response = await apiClient.patch(`/products/${id}`, productData, { timeout: 120000 });
        const result = response.data;

        if (result.success) {
          const savedProduct = result.data || null;

          // Delete removed variants
          for (const variantId of deletedVariantIds) {
            try {
              await apiClient.delete(`/products/${id}/variants/${variantId}`);
            } catch (err) {
              console.error(`Error deleting variant ${variantId}:`, err);
            }
          }

          // Update/Create variants
          for (const variant of variants) {
            const cleanedVariant = cleanVariantData(variant);
            try {
              if (variant.id) {
                await apiClient.put(`/products/${id}/variants/${variant.id}`, cleanedVariant);
              } else {
                await productApi.createVariant(id, cleanedVariant);
              }
            } catch (err) {
              console.error(`Error processing variant:`, err);
            }
          }

          setSuccessMessage(t("products.messages.productUpdated"));
          setTimeout(() => setSuccessMessage(null), 3000);
          setSuccess(false);

          // WhatsApp Trigger
          if (whatsappNotify.enabled) {
            try {
              await apiClient.post('/customers/whatsapp-notify/smart-send', {
                audience: whatsappNotify.audience,
                templateName: whatsappNotify.templateName,
                customMessage: whatsappNotify.customMessage,
                productId: id
              });
            } catch (err) {
              console.error('Error triggering whatsapp:', err);
            }
          }

          if (onSuccess) onSuccess(savedProduct);
          return savedProduct;
        } else {
          setError(result.message || t("products.messages.productError"));
          return null;
        }
      } else {
        // CREATE PRODUCT (using apiClient for consistency)
        const response = await apiClient.post('/products', productData, { timeout: 120000 });
        const result = response.data;

        if (result.success) {
          const productId = result.data?.id;
          const savedProduct = result.data || null;
          if (variants.length > 0 && productId) {
            for (const variant of variants) {
              try {
                const variantData = cleanVariantData(variant);
                await productApi.createVariant(productId, variantData);
              } catch (err) {
                console.error(`Error creating variant:`, err);
              }
            }
          }

          // WhatsApp Trigger
          if (whatsappNotify.enabled && productId) {
            try {
              await apiClient.post('/customers/whatsapp-notify/smart-send', {
                audience: whatsappNotify.audience,
                templateName: whatsappNotify.templateName,
                customMessage: whatsappNotify.customMessage,
                productId: productId
              });
            } catch (err) {
              console.error('Error triggering whatsapp:', err);
            }
          }

          setSuccess(true);
          setTimeout(() => setSuccess(false), 3000);
          if (onSuccess) onSuccess(savedProduct);
          return savedProduct;
        } else {
          setError(result.message || t("products.messages.productCreationError"));
          return null;
        }
      }
    } catch (err: any) {
      console.error("❌ [ProductSave-Hook] Error saving product:", err);
      
      // Capture more details for debugging
      const errorMessage = err.response?.data?.message || err.message || "Unknown error";
      const errorStatus = err.response?.status;
      const errorData = err.response?.data;
      
      console.error("❌ [ProductSave-Details]:", {
        message: errorMessage,
        status: errorStatus,
        data: errorData,
        isEditMode,
        productId: id
      });

      setError(
        errorMessage + (errorStatus ? ` (Status: ${errorStatus})` : "")
      );
      return null;
    } finally {
      setLoading(false);
    }
  };

  return {
    loading, setLoading,
    error, setError,
    success, setSuccess,
    successMessage, setSuccessMessage,
    saveProduct
  };
};

import { useState, useCallback } from "react";
import { ProductFormData, FieldErrors } from "../types";

const initialFormData: ProductFormData = {
  name: "",
  description: "",
  slug: "",
  price: 0,
  comparePrice: undefined,
  cost: undefined,
  sku: "",
  category: "",
  stock: 0,
  trackInventory: true,
  lowStockThreshold: 5,
  isActive: false,
  enableCheckoutForm: false,
  showAddToCartButton: true,
  saleStartDate: "",
  saleEndDate: "",
  sizeGuide: "",
  tags: [],
  weight: undefined,
  dimensions: undefined,
  isFeatured: false,
  isHidden: false,
  showFakeStock: false,
  featuredPriority: 0,
  shippingClass: "standard",
  excludeFromFreeShipping: false,
  affiliateCommission: 0,
  commissionType: "PERCENTAGE",
  allowAffiliateMarkup: false,
  mainImage: "",
  barcode: "",
  isPreOrder: false,
  preOrderDate: "",
  preOrderMessage: "",
  externalUrl: "",
  externalButtonLabel: "",
  externalVendor: "",
  externalDescription: "",
  externalOnly: false,
  metaTitle: "",
  metaDescription: "",
  canonicalUrl: "",
};

export const useProductForm = () => {
  const [formData, setFormData] = useState<ProductFormData>(initialFormData);
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});

  const handleInputChange = useCallback(
    (
      e: React.ChangeEvent<
        HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
      >
    ) => {
      const { name, value, type } = e.target;
      let parsedValue: any = value;

      if (type === "checkbox") {
        parsedValue = (e.target as HTMLInputElement).checked;
      } else if (type === "number") {
        parsedValue = value === "" ? "" : parseFloat(value);
      }

      setFormData((prev) => ({
        ...prev,
        [name]: parsedValue,
      }));

      // Clear error for the field being edited
      if (fieldErrors[name as keyof FieldErrors]) {
        setFieldErrors((prev) => {
          const newErrors = { ...prev };
          delete newErrors[name as keyof FieldErrors];
          return newErrors;
        });
      }
    },
    [fieldErrors]
  );

  const resetForm = useCallback(() => {
    setFormData(initialFormData);
    setFieldErrors({});
  }, []);

  return {
    formData,
    setFormData,
    fieldErrors,
    setFieldErrors,
    handleInputChange,
    resetForm,
    initialFormData,
  };
};

import { useState, useEffect } from "react";
import { uploadFiles } from "../../../utils/apiHelpers";
import { normalizeImagePath } from "../../../utils/imageUrl";
import { arrayMove } from "@dnd-kit/sortable";
import { DragEndEvent } from "@dnd-kit/core";

export const useProductMedia = (
  initialImages: string[] = []
) => {
  const [uploadedImages, setUploadedImages] = useState<string[]>(initialImages);
  const [uploading, setUploading] = useState(false);

  // Sync state if initialImages prop changes from DB
  useEffect(() => {
    if (initialImages.length > 0 && uploadedImages.length === 0) {
      setUploadedImages(initialImages);
    }
  }, [initialImages, uploadedImages.length]);


  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files?.length) return;
    setUploading(true);
    try {
      const selectedFiles = Array.from(e.target.files);

      const fileUrls = await uploadFiles(
        selectedFiles,
        "upload/multiple"
      );

      // Assuming API returns array of strings or objects with fullUrl
      const urls = Array.isArray(fileUrls) ? fileUrls : (fileUrls.data || []);
      const urlList = urls
        .map((u: any) => {
          if (typeof u === "string") return u;
          if (u && typeof u === "object") return u.fullUrl || u.url || u.path;
          return null;
        })
        .filter((u: any): u is string => typeof u === "string" && u.length > 0)
        .map((u: string) => normalizeImagePath(u) || u)
        .filter(Boolean) as string[];

      if (urlList.length > 0) {
        setUploadedImages((prev) => [...prev, ...urlList]);
      }
    } catch (err) {
      console.error("تعذر رفع الصور:", err);
    } finally {
      setUploading(false);
      if (e.target) {
        e.target.value = ""; // Reset input
      }
    }
  };

  const removeUploadedImage = async (urlToRemove: string) => {
    // Keep file deletion out of the editor flow. Duplicated products can
    // legitimately reference the same uploaded asset, so we only remove the
    // image from the current draft and let save persist that detached state.
    setUploadedImages((prev) => prev.filter((url) => url !== urlToRemove));
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      setUploadedImages((items) => {
        const oldIndex = items.indexOf(active.id as string);
        const newIndex = items.indexOf(over.id as string);
        return arrayMove(items, oldIndex, newIndex);
      });
    }
  };

  return {
    uploadedImages,
    setUploadedImages,
    uploading,
    handleImageChange,
    removeUploadedImage,
    handleDragEnd,
  };
};

import { useState } from "react";
import { ProductVariant, ProductAttribute } from "../types";
import { uploadFiles } from "../../../utils/apiHelpers";
import { normalizeImagePath } from "../../../utils/imageUrl";

export const useProductVariants = (initialTrackInventory: boolean = true) => {
  const [variants, setVariants] = useState<ProductVariant[]>([]);
  const [deletedVariantIds, setDeletedVariantIds] = useState<string[]>([]);
  
  const [attributes, setAttributes] = useState<ProductAttribute[]>([]);
  const [newAttributeName, setNewAttributeName] = useState("");
  const [newAttributeValuesList, setNewAttributeValuesList] = useState<string[]>([""]);
  
  const [bulkAction, setBulkAction] = useState("");
  const [bulkValue, setBulkValue] = useState<string | number>("");
  const [showBulkInput, setShowBulkInput] = useState(false);
  const [attributeMode, setAttributeMode] = useState<"templates" | "custom">("templates");
  
  const [variantSettings, setVariantSettings] = useState<{
    styles: {
      [key: string]: "buttons" | "circles" | "dropdown" | "thumbnails" | "radio";
    };
    attributeImages: { [key: string]: { [value: string]: string } };
  }>({ styles: {}, attributeImages: {} });

  // Single variant operations
  const addVariant = () => {
    const baseVariant: ProductVariant = {
      name: "",
      type: "color",
      sku: "",
      images: [],
      stock: 0,
      trackInventory: initialTrackInventory,
      isActive: true,
      sortOrder: variants.length,
      image: undefined,
      description: "",
      weight: undefined,
      dimensions: {},
      shippingClass: "standard",
      allowBackorders: false,
      lowStockThreshold: 5,
      attributeValues: {},
    };
    setVariants((prev) => [...prev, baseVariant]);
  };

  const updateVariant = (index: number, field: keyof ProductVariant, value: any) => {
    setVariants((prev) =>
      prev.map((variant, i) => (i === index ? { ...variant, [field]: value } : variant))
    );
  };

  const removeVariant = (index: number) => {
    const variantToRemove = variants[index];
    if (variantToRemove?.id) {
      setDeletedVariantIds((prev) => [...prev, variantToRemove.id!]);
    }
    setVariants((prev) => prev.filter((_, i) => i !== index));
  };

  const uploadVariantImage = async (variantIndex: number, file: File) => {
    try {
      const data = await uploadFiles([file]);
      if (data.success && data.data.length > 0) {
        const rawUrl = data.data[0].fullUrl || data.data[0].url;
        const imageUrl = normalizeImagePath(rawUrl) || rawUrl;
        updateVariant(variantIndex, "image", imageUrl);
      }
    } catch (error) {
      console.error("Variant image upload error:", error);
    }
  };

  // Attribute operations
  const addAttribute = () => {
    if (!newAttributeName.trim()) return;

    const values = newAttributeValuesList.map((v) => v.trim()).filter((v) => v);
    if (values.length === 0) return;

    const newAttr: ProductAttribute = {
      id: `attr_${Date.now()}`,
      name: newAttributeName.trim(),
      slug: newAttributeName.trim().toLowerCase().replace(/\s+/g, "_"),
      values: values,
      visible: true,
      forVariations: true,
    };

    setAttributes((prev) => [...prev, newAttr]);
    setNewAttributeName("");
    setNewAttributeValuesList([""]);
  };

  const addValueField = () => setNewAttributeValuesList((prev) => [...prev, ""]);
  const updateValueField = (index: number, value: string) =>
    setNewAttributeValuesList((prev) => prev.map((v, i) => (i === index ? value : v)));
  const removeValueField = (index: number) => {
    if (newAttributeValuesList.length > 1) {
      setNewAttributeValuesList((prev) => prev.filter((_, i) => i !== index));
    }
  };
  const removeAttribute = (id: string) => setAttributes((prev) => prev.filter((attr) => attr.id !== id));

  const generateVariations = (baseSku: string) => {
    const variationAttributes = attributes.filter((attr) => attr.forVariations && attr.values.length > 0);
    if (variationAttributes.length === 0) return;

    const combinations: { [key: string]: string }[][] = variationAttributes.map((attr) =>
      attr.values.map((value) => ({ [attr.slug]: value }))
    );

    const allCombinations = combinations.reduce(
      (acc, curr) => {
        if (acc.length === 0) return curr.map((item) => [item]);
        return acc.flatMap((combo) => curr.map((item) => [...combo, item]));
      },
      [] as { [key: string]: string }[][]
    );

    const newVariants: ProductVariant[] = allCombinations.map((combo, idx) => {
      const attributeValues = combo.reduce((acc, curr) => ({ ...acc, ...curr }), {});
      const name = Object.values(attributeValues).join(" - ");
      const timestamp = Date.now();
      const uniqueSku = baseSku && baseSku !== "-" ? `${baseSku}-${idx + 1}-${timestamp}` : `VAR-${timestamp}-${idx + 1}`;

      return {
        name,
        type: "combination",
        sku: uniqueSku,
        images: [],
        stock: 0,
        trackInventory: initialTrackInventory,
        isActive: true,
        sortOrder: idx,
        description: "",
        dimensions: {},
        shippingClass: "standard",
        allowBackorders: false,
        lowStockThreshold: 5,
        attributeValues,
      };
    });

    setVariants(newVariants);
  };

  // Bulk actions
  const bulkActionsNeedingInput = [
    "set_price", "increase_price", "decrease_price", "increase_price_percent", "decrease_price_percent",
    "set_compare_price", "set_cost", "set_stock", "set_low_stock",
    "set_weight", "set_length", "set_width", "set_height", "set_shipping_class",
  ];

  const handleBulkActionChange = (action: string) => {
    setBulkAction(action);
    setShowBulkInput(bulkActionsNeedingInput.includes(action));
    setBulkValue("");
  };

  const applyBulkAction = () => {
    if (!bulkAction || variants.length === 0) return;
    const numValue = Number(bulkValue) || 0;

    setVariants((prev) => {
      return prev.map((v) => {
        let updated = { ...v };
        switch (bulkAction) {
          case "activate": updated.isActive = true; break;
          case "deactivate": updated.isActive = false; break;
          case "set_price": updated.price = numValue; break;
          case "increase_price": updated.price = (updated.price || 0) + numValue; break;
          case "decrease_price": updated.price = Math.max(0, (updated.price || 0) - numValue); break;
          case "increase_price_percent": updated.price = (updated.price || 0) * (1 + numValue / 100); break;
          case "decrease_price_percent": updated.price = Math.max(0, (updated.price || 0) * (1 - numValue / 100)); break;
          case "set_compare_price": updated.comparePrice = numValue; break;
          case "set_cost": updated.cost = numValue; break;
          case "track_inventory": updated.trackInventory = true; break;
          case "untrack_inventory": updated.trackInventory = false; break;
          case "set_stock": updated.stock = Math.floor(numValue); updated.trackInventory = true; break;
          case "set_low_stock": updated.lowStockThreshold = Math.floor(numValue); break;
          case "in_stock": updated.stock = updated.stock || 10; updated.trackInventory = true; break;
          case "out_of_stock": updated.stock = 0; updated.trackInventory = true; break;
          case "allow_backorders": updated.allowBackorders = true; break;
          case "disallow_backorders": updated.allowBackorders = false; break;
          case "set_weight": updated.weight = numValue; break;
          case "set_length": updated.dimensions = { ...updated.dimensions, length: numValue }; break;
          case "set_width": updated.dimensions = { ...updated.dimensions, width: numValue }; break;
          case "set_height": updated.dimensions = { ...updated.dimensions, height: numValue }; break;
          case "set_shipping_class": updated.shippingClass = bulkValue as string; break;
        }
        return updated;
      });
    });

    if (bulkAction === "delete") {
      if (!window.confirm(`هل أنت متأكد من حذف كل المتغيرات (${variants.length})؟`)) {
        setBulkAction("");
        setBulkValue("");
        setShowBulkInput(false);
        return;
      }
      setDeletedVariantIds((prev) => [...prev, ...variants.map(v => v.id).filter(id => id) as string[]]);
      setVariants([]);
    }

    setBulkAction("");
    setBulkValue("");
    setShowBulkInput(false);
  };

  return {
    variants, setVariants, deletedVariantIds, setDeletedVariantIds,
    attributes, setAttributes, newAttributeName, setNewAttributeName,
    newAttributeValuesList, setNewAttributeValuesList,
    bulkAction, setBulkAction, bulkValue, setBulkValue,
    showBulkInput, setShowBulkInput,
    attributeMode, setAttributeMode,
    variantSettings, setVariantSettings,
    addVariant, updateVariant, removeVariant, uploadVariantImage,
    addAttribute, addValueField, updateValueField, removeValueField, removeAttribute, generateVariations,
    handleBulkActionChange, applyBulkAction
  };
};

import { useState, useEffect, useCallback } from "react";
import { apiClient } from "../../../services/apiClient";
import {
  Product,
  SortField,
  SortDirection,
  getStockStatus,
  safeJsonParse,
} from "../components/ProductsTypes";
import { FiltersState } from "../components/ProductsFilters";
import { useAuth } from "../../../hooks/useAuthSimple";
import { buildStoreUrl } from "../../../utils/storeUrl";
import {
  isPublishedWorkflow,
  matchesWorkflowFilter,
  normalizeProductWorkflow,
} from "../utils/workflow";

type WorkflowAction =
  | "save_draft"
  | "submit_review"
  | "approve"
  | "reject"
  | "publish"
  | "unpublish";

const initialFilters: FiltersState = {
  searchQuery: "",
  categoryFilter: "all",
  statusFilter: "all",
  stockFilter: "all",
  priceMin: "",
  priceMax: "",
  dateFrom: "",
  dateTo: "",
  tagsFilter: "",
};

const parseArray = <T>(value: any, fallback: T[] = []): T[] => {
  if (!value) return fallback;
  if (typeof value === "string") return safeJsonParse(value, fallback);
  return Array.isArray(value) ? value : fallback;
};

const resolveStoredCompanyId = (): string | null => {
  if (typeof window === "undefined") return null;

  return (
    localStorage.getItem("storefront_companyId") ||
    localStorage.getItem("companyId") ||
    new URLSearchParams(window.location.search).get("companyId")
  );
};

const buildPreviewPath = (productId: string, companyId?: string | null): string => {
  const params = new URLSearchParams();
  if (companyId) {
    params.set("companyId", companyId);
  }
  params.set("productPreview", "1");
  params.set("previewSource", "admin");
  params.set("previewProductId", productId);

  const query = params.toString();
  return `/store/shop/products/${encodeURIComponent(productId)}${query ? `?${query}` : ""}`;
};

export const useProducts = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isDeletingAll, setIsDeletingAll] = useState(false);
  const [duplicatingProductId, setDuplicatingProductId] = useState<string | null>(null);
  const [workflowLoadingId, setWorkflowLoadingId] = useState<string | null>(null);

  const { user } = useAuth();
  const isAdmin = ["OWNER", "COMPANY_ADMIN", "SUPER_ADMIN", "MANAGER"].includes(
    user?.role || "",
  );

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);
  const [totalItems, setTotalItems] = useState(0);

  // Sorting
  const [sortField, setSortField] = useState<SortField>("createdAt");
  const [sortDirection, setSortDirection] = useState<SortDirection>("desc");

  // Selection (bulk actions)
  const [selectedProducts, setSelectedProducts] = useState<Set<string>>(new Set());
  const [selectAll, setSelectAll] = useState(false);

  // Quick edit
  const [editingProduct, setEditingProduct] = useState<string | null>(null);
  const [editPrice, setEditPrice] = useState<string>("");
  const [editStock, setEditStock] = useState<string>("");

  // Filters
  const [filters, setFilters] = useState<FiltersState>(initialFilters);

  const transformProduct = useCallback(
    (p: any, fallback?: Product): Product => {
      const variants = Array.isArray(p.productVariants)
        ? p.productVariants
        : Array.isArray(p.variants)
          ? p.variants
          : [];
      const resolvedVariantsCount =
        variants.length > 0 ? variants.length : fallback?.variantsCount || 0;

      return {
        id: p.id,
        slug: p.slug || fallback?.slug || undefined,
        name: p.name || fallback?.name || "",
        description: p.description || fallback?.description || "",
        price: Number(p.price ?? fallback?.price ?? 0),
        comparePrice:
          p.comparePrice !== undefined && p.comparePrice !== null
            ? Number(p.comparePrice)
            : fallback?.comparePrice,
        cost:
          p.cost !== undefined && p.cost !== null
            ? Number(p.cost)
            : fallback?.cost,
        sku: p.sku || fallback?.sku || "",
        category: p.category?.name || fallback?.category || "غير محدد",
        categoryId: p.categoryId || fallback?.categoryId,
        images:
          p.images !== undefined
            ? parseArray<string>(p.images, [])
            : fallback?.images || [],
        mainImage: p.mainImage || fallback?.mainImage,
        stock: Number(p.stock ?? fallback?.stock ?? 0),
        lowStockThreshold: Number(p.lowStockThreshold ?? fallback?.lowStockThreshold ?? 5),
        isActive: p.isActive !== undefined ? Boolean(p.isActive) : Boolean(fallback?.isActive),
        isHidden: p.isHidden !== undefined ? Boolean(p.isHidden) : Boolean(fallback?.isHidden),
        createdAt: p.createdAt ? new Date(p.createdAt) : fallback?.createdAt || new Date(),
        updatedAt: p.updatedAt ? new Date(p.updatedAt) : fallback?.updatedAt || new Date(),
        tags:
          p.tags !== undefined
            ? parseArray<string>(p.tags, [])
            : fallback?.tags || [],
        weight:
          p.weight !== undefined && p.weight !== null
            ? Number(p.weight)
            : fallback?.weight,
        dimensions:
          p.dimensions !== undefined && p.dimensions !== null
            ? safeJsonParse(
                typeof p.dimensions === "string"
                  ? p.dimensions
                  : JSON.stringify(p.dimensions),
                undefined,
              )
            : fallback?.dimensions,
        workflow: normalizeProductWorkflow(
          p.workflow,
          p.isActive !== undefined ? Boolean(p.isActive) : fallback?.isActive,
        ),
        productType: resolvedVariantsCount > 0 ? "variable" : "simple",
        variantsCount: resolvedVariantsCount,
      };
    },
    [],
  );

  const companyIdForPreview = user?.companyId || resolveStoredCompanyId();

  const handleFilterChange = useCallback((key: keyof FiltersState, value: string) => {
    setCurrentPage(1);
    setFilters((prev) => {
      if (prev[key] === value) {
        return prev;
      }

      return { ...prev, [key]: value };
    });
  }, []);

  const resetFilters = useCallback(() => {
    setCurrentPage(1);
    setFilters(initialFilters);
  }, []);

  const clearSelection = useCallback(() => {
    setSelectedProducts(new Set());
    setSelectAll(false);
  }, []);

  const hasActiveFilters = !!(
    filters.searchQuery ||
    filters.categoryFilter !== "all" ||
    filters.statusFilter !== "all" ||
    filters.stockFilter !== "all" ||
    filters.priceMin ||
    filters.priceMax ||
    filters.dateFrom ||
    filters.dateTo ||
    filters.tagsFilter
  );

  const loadProducts = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);
      const limit = hasActiveFilters ? 500 : itemsPerPage;
      const page = hasActiveFilters ? 1 : currentPage;

      const response = await apiClient.get("products", {
        params: { page, limit, sortBy: sortField, sortOrder: sortDirection },
        _skipTransientRetry: true,
      });

      const data = response.data;
      if (data.success && data.data) {
        const transformed = data.data.map((p: any) => transformProduct(p));
        setProducts(transformed);
        setTotalItems(data.pagination?.total || transformed.length);
      } else {
        setError("فشل في تحميل المنتجات");
      }
    } catch (err: any) {
      console.error("Error loading products:", err);
      setError("حدث خطأ أثناء تحميل المنتجات");
    } finally {
      setIsLoading(false);
    }
  }, [
    currentPage,
    itemsPerPage,
    sortField,
    sortDirection,
    hasActiveFilters,
    transformProduct,
  ]);

  useEffect(() => {
    loadProducts();
  }, [loadProducts]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const categories = Array.from(new Set(products.map((p) => p.category)));
  const allTags = Array.from(new Set(products.flatMap((p) => p.tags || [])));

  const filteredProducts = hasActiveFilters
    ? products.filter((p) => {
        const matchesSearch =
          (p.name || "").toLowerCase().includes(filters.searchQuery.toLowerCase()) ||
          (p.sku || "").toLowerCase().includes(filters.searchQuery.toLowerCase()) ||
          (p.tags || []).some((t) =>
            (t || "").toLowerCase().includes(filters.searchQuery.toLowerCase()),
          );
        const matchesCategory =
          filters.categoryFilter === "all" || p.category === filters.categoryFilter;
        const matchesStatus = matchesWorkflowFilter(p.workflow, filters.statusFilter);
        const stockStatus = getStockStatus(p);
        const matchesStock = filters.stockFilter === "all" || stockStatus === filters.stockFilter;
        const matchesPriceMin =
          !filters.priceMin || (p.price != null && p.price >= parseFloat(filters.priceMin));
        const matchesPriceMax =
          !filters.priceMax || (p.price != null && p.price <= parseFloat(filters.priceMax));
        const matchesDateFrom =
          !filters.dateFrom || (p.createdAt && new Date(p.createdAt) >= new Date(filters.dateFrom));
        const matchesDateTo =
          !filters.dateTo || (p.createdAt && new Date(p.createdAt) <= new Date(filters.dateTo));
        const matchesTags =
          !filters.tagsFilter ||
          (p.tags || []).some((t) =>
            (t || "").toLowerCase().includes(filters.tagsFilter.toLowerCase()),
          );
        return (
          matchesSearch &&
          matchesCategory &&
          matchesStatus &&
          matchesStock &&
          matchesPriceMin &&
          matchesPriceMax &&
          matchesDateFrom &&
          matchesDateTo &&
          matchesTags
        );
      })
    : products;

  const sortedProducts = hasActiveFilters
    ? [...filteredProducts].sort((a, b) => {
        let cmp = 0;
        switch (sortField) {
          case "name":
            cmp = a.name.localeCompare(b.name, "ar");
            break;
          case "price":
            cmp = a.price - b.price;
            break;
          case "stock":
            cmp = a.stock - b.stock;
            break;
          case "createdAt":
            cmp = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
            break;
          case "updatedAt":
            cmp = new Date(a.updatedAt).getTime() - new Date(b.updatedAt).getTime();
            break;
        }
        return sortDirection === "asc" ? cmp : -cmp;
      })
    : filteredProducts;

  const totalPages = hasActiveFilters
    ? Math.ceil(sortedProducts.length / itemsPerPage)
    : Math.ceil(totalItems / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = hasActiveFilters
    ? sortedProducts.slice(startIndex, startIndex + itemsPerPage)
    : sortedProducts;

  const handleSelectAll = useCallback(() => {
    if (selectAll) {
      clearSelection();
    } else {
      setSelectedProducts(new Set(paginatedProducts.map((p) => p.id)));
      setSelectAll(true);
    }
  }, [clearSelection, selectAll, paginatedProducts]);

  const handleSelectProduct = (productId: string) => {
    const next = new Set(selectedProducts);
    if (next.has(productId)) next.delete(productId);
    else next.add(productId);
    setSelectedProducts(next);
    setSelectAll(paginatedProducts.length > 0 && next.size === paginatedProducts.length);
  };

  const handleBulkDelete = async () => {
    if (selectedProducts.size === 0) return;
    if (!confirm(`هل أنت متأكد من حذف ${selectedProducts.size} منتج؟`)) return;
    try {
      let count = 0;
      for (const id of selectedProducts) {
        const r = await apiClient.delete(`products/${id}`);
        if (r.status === 200 || r.status === 204) count++;
      }
      setProducts((prev) => prev.filter((p) => !selectedProducts.has(p.id)));
      clearSelection();
      return count;
    } catch (err) {
      console.error("Bulk delete error:", err);
      throw err;
    }
  };

  const startQuickEdit = (product: Product) => {
    setEditingProduct(product.id);
    setEditPrice(product.price.toString());
    setEditStock(product.stock.toString());
  };

  const cancelQuickEdit = () => {
    setEditingProduct(null);
    setEditPrice("");
    setEditStock("");
  };

  const saveQuickEdit = async (productId: string) => {
    try {
      const r = await apiClient.patch(`products/${productId}`, {
        price: parseFloat(editPrice),
        stock: parseInt(editStock, 10),
      });
      if (r.status === 200) {
        const updatedProduct = r.data?.data;
        setProducts((prev) =>
          prev.map((p) =>
            p.id === productId
              ? transformProduct(updatedProduct || { ...p, price: parseFloat(editPrice), stock: parseInt(editStock, 10) }, p)
              : p,
          ),
        );
        cancelQuickEdit();
        return true;
      }
      return false;
    } catch (err) {
      console.error("Quick edit error:", err);
      throw err;
    }
  };

  const handleDuplicate = async (product: Product) => {
    if (duplicatingProductId) return;
    setDuplicatingProductId(product.id);
    try {
      const r = await apiClient.post(`products/${product.id}/duplicate`);
      if (r.status === 200 || r.status === 201) {
        await loadProducts();
        return true;
      }
      return false;
    } catch (err: any) {
      console.error("Duplicate error:", err);
      throw err;
    } finally {
      setDuplicatingProductId(null);
    }
  };

  const handleWorkflowAction = async (
    productId: string,
    action: WorkflowAction,
    rejectionReason?: string | null,
  ) => {
    try {
      setWorkflowLoadingId(productId);
      const response = await apiClient.post(`products/${productId}/workflow`, {
        action,
        rejectionReason: rejectionReason || undefined,
      });
      const updatedProduct = response.data?.data;
      if (response.data?.success && updatedProduct) {
        setProducts((prev) =>
          prev.map((p) =>
            p.id === productId ? transformProduct(updatedProduct, p) : p,
          ),
        );
        return updatedProduct;
      }
      throw new Error(response.data?.message || "فشل في تحديث حالة المنتج");
    } catch (err) {
      console.error("Workflow action error:", err);
      throw err;
    } finally {
      setWorkflowLoadingId(null);
    }
  };

  const handleDelete = async (productId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا المنتج؟")) return;
    try {
      const r = await apiClient.delete(`products/${productId}`);
      if (r.status === 200 || r.status === 204) {
        setProducts((prev) => prev.filter((p) => p.id !== productId));
        return true;
      }
      return false;
    } catch (err) {
      console.error("Delete error:", err);
      throw err;
    }
  };

  const handleDeleteAll = async () => {
    if (products.length === 0) return;
    const confirmMsg = `هل أنت متأكد من حذف جميع المنتجات؟\n\nسيتم حذف ${products.length} منتج نهائياً.\n\nهذا الإجراء لا يمكن التراجع عنه!`;
    if (!confirm(confirmMsg)) return;
    const secondConfirm = prompt('للتأكيد، اكتب "حذف الكل" في المربع أدناه:');
    if (secondConfirm !== "حذف الكل") return;

    try {
      setIsDeletingAll(true);
      const r = await apiClient.delete("products/bulk/delete");
      if (r.status === 200 && r.data.success) {
        setProducts([]);
        clearSelection();
        return r.data.data;
      }
      throw new Error(r.data.message || "فشل في حذف المنتجات");
    } catch (err) {
      console.error("Delete all error:", err);
      throw err;
    } finally {
      setIsDeletingAll(false);
    }
  };

  const prepareStorefrontContext = useCallback(() => {
    const slug = user?.company?.slug;
    if (slug && slug.trim().length > 0) return;
    const companyId =
      user?.companyId ||
      localStorage.getItem("companyId") ||
      new URLSearchParams(window.location.search).get("companyId");
    if (companyId) localStorage.setItem("storefront_companyId", companyId);
  }, [user?.company?.slug, user?.companyId]);

  const getProductPreviewUrl = useCallback(
    (product: Pick<Product, "id"> | string) => {
      const productId = typeof product === "string" ? product : product.id;
      return buildPreviewPath(productId, companyIdForPreview);
    },
    [companyIdForPreview],
  );

  const getPublicStorefrontUrl = useCallback(
    (product: Pick<Product, "id" | "slug"> | string) => {
      const productKey =
        typeof product === "string" ? product : product.slug || product.id;
      const base = `/product/${encodeURIComponent(productKey)}`;
      const slug = user?.company?.slug;
      const customDomain = user?.company?.customDomain;
      if (slug && slug.trim().length > 0) {
        return buildStoreUrl(
          slug,
          base,
          customDomain || undefined,
          companyIdForPreview,
        );
      }
      const params = new URLSearchParams();
      if (companyIdForPreview) {
        params.set("companyId", companyIdForPreview);
      }
      const query = params.toString();
      return `/store${base}${query ? `?${query}` : ""}`;
    },
    [companyIdForPreview, user?.company?.slug, user?.company?.customDomain],
  );

  const getStorefrontUrl = useCallback(
    (product: Pick<Product, "id" | "slug" | "workflow"> | string) => {
      if (typeof product !== "string" && !isPublishedWorkflow(product.workflow)) {
        return getProductPreviewUrl(product);
      }
      return getPublicStorefrontUrl(product);
    },
    [getProductPreviewUrl, getPublicStorefrontUrl],
  );

  return {
    products,
    isLoading,
    error,
    isDeletingAll,
    duplicatingProductId,
    workflowLoadingId,
    isAdmin,
    currentPage,
    itemsPerPage,
    totalItems,
    sortField,
    sortDirection,
    selectedProducts,
    selectAll,
    editingProduct,
    editPrice,
    editStock,
    filters,
    hasActiveFilters,
    categories,
    allTags,
    sortedProducts,
    totalPages,
    startIndex,
    paginatedProducts,
    setCurrentPage,
    setItemsPerPage,
    handleFilterChange,
    handleSort,
    handleSelectAll,
    handleSelectProduct,
    handleBulkDelete,
    clearSelection,
    resetFilters,
    startQuickEdit,
    cancelQuickEdit,
    setEditPrice,
    setEditStock,
    saveQuickEdit,
    handleDuplicate,
    handleWorkflowAction,
    handleDelete,
    handleDeleteAll,
    loadProducts,
    prepareStorefrontContext,
    getStorefrontUrl,
    getProductPreviewUrl,
    getPublicStorefrontUrl,
    setFilters,
  };
};

