import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../../hooks/useAuthSimple";
import { useCurrency } from "../../hooks/useCurrency";
import { useDateFormat } from "../../hooks/useDateFormat";
import { apiClient } from "../../services/apiClient";
import {
  ArrowDownTrayIcon,
  CalendarIcon,
  ChartBarIcon,
} from "@heroicons/react/24/outline";

interface ShippingReportData {
  orderId: string;
  orderNumber: string;
  actualCost: number;
  customerCost: number;
  difference: number;
  status: string;
  trackingNumber: string;
  createdAt: string;
}

interface ShippingStatistics {
  totalOrders: number;
  ordersWithCost: number;
  totalActual: number;
  totalCustomer: number;
  totalDifference: number;
  avgActual: number;
  avgCustomer: number;
}

const ShippingReport: React.FC = () => {
  const navigate = useNavigate();
  const { formatPrice } = useCurrency();
  const { formatDate } = useDateFormat();
  const { isAuthenticated } = useAuth();
  const [loading, setLoading] = useState(true);
  const [reportData, setReportData] = useState<ShippingReportData[]>([]);
  const [statistics, setStatistics] = useState<ShippingStatistics | null>(null);
  const [filters, setFilters] = useState({
    startDate: "",
    endDate: "",
    status: "",
  });

  useEffect(() => {
    if (!isAuthenticated) {
      navigate("/auth/login");
      return;
    }
    fetchReport();
  }, [isAuthenticated, filters]);

  const fetchReport = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (filters.startDate) params.append("startDate", filters.startDate);
      if (filters.endDate) params.append("endDate", filters.endDate);
      if (filters.status) params.append("status", filters.status);

      const response = await apiClient.get(
        `/turbo/reports/shipping?${params.toString()}`,
      );
      if (response.data.success) {
        setReportData(response.data.data.orders);
        setStatistics(response.data.data.statistics);
      }
    } catch (error: any) {
      console.error("Error fetching shipping report:", error);
      alert(error.response?.data?.error || "فشل جلب التقرير");
    } finally {
      setLoading(false);
    }
  };

  const handleExportCSV = async () => {
    try {
      const params = new URLSearchParams();
      if (filters.startDate) params.append("startDate", filters.startDate);
      if (filters.endDate) params.append("endDate", filters.endDate);
      if (filters.status) params.append("status", filters.status);
      params.append("export", "csv");

      const response = await apiClient.get(
        `/turbo/reports/shipping?${params.toString()}`,
        {
          responseType: "blob",
        },
      );

      const blob = new Blob([response.data], {
        type: "text/csv;charset=utf-8;",
      });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `turbo-shipping-report-${new Date().toISOString().split("T")[0]}.csv`;
      link.click();
      window.URL.revokeObjectURL(url);
    } catch (error: any) {
      console.error("Error exporting CSV:", error);
      alert("فشل تصدير التقرير");
    }
  };

  const getStatusColor = (status?: string) => {
    if (!status)
      return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200";
    const statusLower = status.toLowerCase();
    if (statusLower === "delivered")
      return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300";
    if (statusLower === "cancelled" || statusLower === "returned")
      return "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300";
    if (statusLower === "in_transit" || statusLower === "out_for_delivery")
      return "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300";
    return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200";
  };

  const getStatusText = (status?: string) => {
    if (!status) return "غير محدد";
    const statusMap: { [key: string]: string } = {
      created: "تم الإنشاء",
      picked_up: "تم الاستلام",
      in_transit: "قيد النقل",
      out_for_delivery: "في الطريق للتسليم",
      delivered: "تم التسليم",
      cancelled: "ملغاة",
      returned: "مرتجعة",
    };
    return statusMap[status.toLowerCase()] || status;
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6 text-gray-900 dark:bg-gray-950 dark:text-gray-100">
      <div className="w-full">
        <div className="rounded-lg bg-white p-6 shadow dark:bg-gray-900 dark:shadow-black/20">
          <div className="flex justify-between items-center mb-6">
            <h1 className="flex items-center text-2xl font-bold text-gray-900 dark:text-white">
              <ChartBarIcon className="h-6 w-6 text-blue-500 ml-2" />
              تقرير الشحن - مقارنة الأسعار
            </h1>
            <button
              onClick={handleExportCSV}
              className="flex items-center px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
            >
              <ArrowDownTrayIcon className="w-5 h-5 ml-2" />
              تصدير إلى Excel (CSV)
            </button>
          </div>

          {/* Filters */}
          <div className="mb-6 grid grid-cols-1 gap-4 rounded-lg bg-gray-50 p-4 dark:bg-gray-800/80 md:grid-cols-3">
            <div>
              <label
                htmlFor="shipping-report-start-date"
                className="mb-1 block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                من تاريخ
              </label>
              <input
                id="shipping-report-start-date"
                name="startDate"
                type="date"
                autoComplete="off"
                value={filters.startDate}
                onChange={(e) =>
                  setFilters({ ...filters, startDate: e.target.value })
                }
                className="w-full rounded-lg border border-gray-300 px-3 py-2 dark:border-gray-700 dark:bg-gray-900 dark:text-gray-100"
              />
            </div>
            <div>
              <label
                htmlFor="shipping-report-end-date"
                className="mb-1 block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                إلى تاريخ
              </label>
              <input
                id="shipping-report-end-date"
                name="endDate"
                type="date"
                autoComplete="off"
                value={filters.endDate}
                onChange={(e) =>
                  setFilters({ ...filters, endDate: e.target.value })
                }
                className="w-full rounded-lg border border-gray-300 px-3 py-2 dark:border-gray-700 dark:bg-gray-900 dark:text-gray-100"
              />
            </div>
            <div>
              <label
                htmlFor="shipping-report-status"
                className="mb-1 block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                الحالة
              </label>
              <select
                id="shipping-report-status"
                name="status"
                autoComplete="off"
                value={filters.status}
                onChange={(e) =>
                  setFilters({ ...filters, status: e.target.value })
                }
                className="w-full rounded-lg border border-gray-300 px-3 py-2 dark:border-gray-700 dark:bg-gray-900 dark:text-gray-100"
              >
                <option value="">جميع الحالات</option>
                <option value="created">تم الإنشاء</option>
                <option value="picked_up">تم الاستلام</option>
                <option value="in_transit">قيد النقل</option>
                <option value="out_for_delivery">في الطريق للتسليم</option>
                <option value="delivered">تم التسليم</option>
                <option value="cancelled">ملغاة</option>
                <option value="returned">مرتجعة</option>
              </select>
            </div>
          </div>

          {/* Statistics */}
          {statistics && (
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
              <div className="rounded-lg border-l-4 border-blue-500 bg-blue-50 p-4 dark:bg-blue-950/30">
                <div className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  إجمالي الطلبات
                </div>
                <div className="text-2xl font-bold text-blue-600 mt-1">
                  {statistics.totalOrders}
                </div>
              </div>
              <div className="rounded-lg border-l-4 border-green-500 bg-green-50 p-4 dark:bg-green-950/30">
                <div className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  إجمالي السعر الفعلي
                </div>
                <div className="text-2xl font-bold text-green-600 mt-1">
                  {formatPrice(statistics.totalActual)} EGP
                </div>
              </div>
              <div className="rounded-lg border-l-4 border-gray-500 bg-gray-50 p-4 dark:bg-gray-800">
                <div className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  إجمالي سعر العميل
                </div>
                <div className="mt-1 text-2xl font-bold text-gray-600 dark:text-gray-200">
                  {formatPrice(statistics.totalCustomer)} EGP
                </div>
              </div>
              <div
                className={`p-4 rounded-lg border-l-4 ${
                  statistics.totalDifference > 0
                    ? "bg-red-50 border-red-500 dark:bg-red-950/30"
                    : statistics.totalDifference < 0
                      ? "bg-green-50 border-green-500 dark:bg-green-950/30"
                      : "bg-gray-50 border-gray-500 dark:bg-gray-800"
                }`}
              >
                <div className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  إجمالي الفرق
                </div>
                <div
                  className={`text-2xl font-bold mt-1 ${
                    statistics.totalDifference > 0
                      ? "text-red-600"
                      : statistics.totalDifference < 0
                        ? "text-green-600"
                        : "text-gray-600 dark:text-gray-200"
                  }`}
                >
                  {statistics.totalDifference > 0 ? "+" : ""}
                  {formatPrice(statistics.totalDifference)} EGP
                </div>
              </div>
            </div>
          )}

          {/* Report Table */}
          {loading ? (
            <div className="text-center py-12">
              <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
              <p className="mt-2 text-gray-600">جاري تحميل التقرير...</p>
            </div>
          ) : reportData.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-gray-600">لا توجد طلبات مع كود Turbo.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                <thead className="bg-gray-50 dark:bg-gray-800">
                  <tr>
                    <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-300">
                      رقم الطلب
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-300">
                      كود Turbo
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-300">
                      السعر الفعلي
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-300">
                      سعر العميل
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-300">
                      الفرق
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-300">
                      الحالة
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-300">
                      التاريخ
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 bg-white dark:divide-gray-700 dark:bg-gray-900">
                  {reportData.map((row) => (
                    <tr
                      key={row.orderId}
                      className="hover:bg-gray-50 dark:hover:bg-gray-800"
                    >
                      <td className="px-6 py-4 whitespace-nowrap">
                        <button
                          onClick={() =>
                            navigate(`/orders/details/${row.orderNumber}`)
                          }
                          className="text-blue-600 hover:text-blue-800 font-medium"
                        >
                          #{row.orderNumber}
                        </button>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100">
                        {row.trackingNumber || "--"}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        {row.actualCost > 0 ? (
                          <span className="font-bold text-blue-600">
                            {formatPrice(row.actualCost)} EGP
                          </span>
                        ) : (
                          <span className="text-gray-500 dark:text-gray-400">
                            غير متوفر
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900 dark:text-gray-100">
                        {formatPrice(row.customerCost)} EGP
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        {row.actualCost > 0 ? (
                          <span
                            className={`font-bold ${
                              row.difference > 0
                                ? "text-red-600"
                                : row.difference < 0
                                  ? "text-green-600"
                                  : "text-gray-600 dark:text-gray-200"
                            }`}
                          >
                            {row.difference > 0 ? "+" : ""}
                            {formatPrice(row.difference)} EGP
                          </span>
                        ) : (
                          <span className="text-gray-400 dark:text-gray-500">
                            --
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(row.status)}`}
                        >
                          {getStatusText(row.status)}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                        {formatDate(row.createdAt)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ShippingReport;

import React, { useState, useEffect } from "react";
import {
  ReturnRequest,
  returnService,
  ContactAttempt,
  ActivityLog,
} from "../../services/returnService";
import {
  X,
  Phone,
  MessageCircle,
  Clock,
  CheckCircle,
  XCircle,
  Shield,
  Calendar,
} from "lucide-react";
import toast from "react-hot-toast";

interface ReturnDetailsModalProps {
  request: ReturnRequest;
  onClose: () => void;
  onUpdate: () => void;
}

const ReturnDetailsModal: React.FC<ReturnDetailsModalProps> = ({
  request,
  onClose,
  onUpdate,
}) => {
  const [activeTab, setActiveTab] = useState<
    "details" | "contact" | "activity"
  >("details");
  const [contactHistory, setContactHistory] = useState<ContactAttempt[]>([]);
  const [activityLog, setActivityLog] = useState<ActivityLog[]>([]);
  const [loadingLogs, setLoadingLogs] = useState(false);

  // Contact Form
  const [contactMethod, setContactMethod] = useState("PHONE");
  const [contactResult, setContactResult] = useState("NO_ANSWER");
  const [contactNotes, setContactNotes] = useState("");

  // Review Form
  const [status, setStatus] = useState(request.status);
  const [responsibleParty, setResponsibleParty] = useState(
    request.responsibleParty,
  );
  const [adminNotes, setAdminNotes] = useState(request.adminNotes || "");
  const [rejectionReason, setRejectionReason] = useState(
    request.rejectionReason || "",
  );
  const [isReviewed, setIsReviewed] = useState(request.isReviewed);
  const [submittingReview, setSubmittingReview] = useState(false);

  useEffect(() => {
    if (activeTab !== "details") {
      fetchLogs();
    }
  }, [activeTab]);

  const fetchLogs = async () => {
    setLoadingLogs(true);
    try {
      if (activeTab === "contact") {
        const res = await returnService.getContactHistory(request.id);
        setContactHistory(res.data);
      } else if (activeTab === "activity") {
        const res = await returnService.getActivityLog(request.id);
        setActivityLog(res.data);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingLogs(false);
    }
  };

  const handleSaveReview = async () => {
    setSubmittingReview(true);
    try {
      await returnService.updateRequest(request.id, {
        status,
        responsibleParty,
        adminNotes,
        rejectionReason,
        isReviewed,
      });
      toast.success("تم حفظ المراجعة وتحديث تقييم العميل إذا لزم الأمر");
      onUpdate();
    } catch (error) {
      toast.error("فشل في حفظ المراجعة");
    } finally {
      setSubmittingReview(false);
    }
  };

  const handleAddContact = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await returnService.addContactAttempt(request.id, {
        method: contactMethod,
        result: contactResult,
        notes: contactNotes,
      });
      toast.success("تم تسجيل المحاوله بنجاح");
      setContactNotes("");
      fetchLogs();
    } catch (error) {
      toast.error("فشل في تسجيل المحاوله");
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "APPROVED":
        return (
          <span className="bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300 px-2 py-1 rounded-full text-xs flex items-center gap-1">
            <CheckCircle size={12} /> تم الموافقة
          </span>
        );
      case "REJECTED":
        return (
          <span className="bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300 px-2 py-1 rounded-full text-xs flex items-center gap-1">
            <XCircle size={12} /> مرفوض
          </span>
        );
      case "COMPLETED":
        return (
          <span className="bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-300 px-2 py-1 rounded-full text-xs flex items-center gap-1">
            <CheckCircle size={12} /> مكتمل
          </span>
        );
      default:
        return (
          <span className="bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300 px-2 py-1 rounded-full text-xs flex items-center gap-1">
            <Clock size={12} /> قيد الانتظار
          </span>
        );
    }
  };

  return (
    <div
      className="fixed inset-0 bg-black bg-opacity-50 dark:bg-black dark:bg-opacity-70 flex items-center justify-center z-50 p-4"
      dir="rtl"
    >
      <div className="bg-white dark:bg-gray-800 rounded-lg w-full max-w-2xl h-[80vh] flex flex-col shadow-xl">
        {/* Header */}
        <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900 rounded-t-lg">
          <div>
            <h2 className="text-lg font-bold text-gray-800 dark:text-white flex items-center gap-2">
              طلب إرجاع #{request.order?.orderNumber}
              {getStatusBadge(request.status)}
            </h2>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {new Date(request.createdAt).toLocaleString("ar-EG")}
            </p>
          </div>
          <button
            onClick={onClose}
            className="text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
          >
            <X size={24} />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-100 dark:border-gray-700">
          <button
            onClick={() => setActiveTab("details")}
            className={`flex-1 py-3 text-sm font-medium transition-colors border-b-2 ${activeTab === "details" ? "border-blue-600 dark:border-blue-400 text-blue-600 dark:text-blue-400" : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300"}`}
          >
            تفاصيل الطلب
          </button>
          <button
            onClick={() => setActiveTab("contact")}
            className={`flex-1 py-3 text-sm font-medium transition-colors border-b-2 ${activeTab === "contact" ? "border-blue-600 dark:border-blue-400 text-blue-600 dark:text-blue-400" : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300"}`}
          >
            سجل التواصل
          </button>
          <button
            onClick={() => setActiveTab("activity")}
            className={`flex-1 py-3 text-sm font-medium transition-colors border-b-2 ${activeTab === "activity" ? "border-blue-600 dark:border-blue-400 text-blue-600 dark:text-blue-400" : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300"}`}
          >
            سجل النشاط
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white dark:bg-gray-800">
          {activeTab === "details" && (
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="bg-gray-50 dark:bg-gray-900/50 p-4 rounded-lg">
                  <h3 className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-3">
                    بيانات العميل
                  </h3>
                  <div className="space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-500 dark:text-gray-400">
                        الاسم:
                      </span>
                      <span className="font-medium text-gray-900 dark:text-white">
                        {request.customer?.firstName}{" "}
                        {request.customer?.lastName}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-500 dark:text-gray-400">
                        الهاتف:
                      </span>
                      <span
                        className="font-medium text-gray-900 dark:text-white"
                        dir="ltr"
                      >
                        {request.customer?.phone}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-500 dark:text-gray-400">
                        التقييم:
                      </span>
                      <span className="font-medium text-blue-600 dark:text-blue-400">
                        {request.customer?.customerRating} (
                        {request.customer?.successScore?.toFixed(1)}%)
                      </span>
                    </div>
                  </div>
                </div>
                <div className="bg-gray-50 dark:bg-gray-900/50 p-4 rounded-lg">
                  <h3 className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-3">
                    تفاصيل الإرجاع
                  </h3>
                  <div className="space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-500 dark:text-gray-400">
                        السبب:
                      </span>
                      <span className="font-medium text-red-600 dark:text-red-400 font-bold">
                        {request.reason?.reason}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-500 dark:text-gray-400">
                        المبلغ المسترد:
                      </span>
                      <span className="font-medium text-gray-900 dark:text-white">
                        {request.refundAmount || "-"}
                      </span>
                    </div>
                    {request.isReviewed && (
                      <div className="flex justify-between">
                        <span className="text-gray-500 dark:text-gray-400">
                          تمت المراجعة في:
                        </span>
                        <span className="font-medium text-xs text-gray-900 dark:text-white">
                          {request.reviewedAt
                            ? new Date(request.reviewedAt).toLocaleDateString()
                            : "-"}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              <div className="bg-yellow-50 dark:bg-yellow-900/20 p-4 rounded-lg border border-yellow-100 dark:border-yellow-800/30">
                <h3 className="text-sm font-bold text-yellow-800 dark:text-yellow-300 mb-2">
                  ملاحظات العميل
                </h3>
                <p className="text-sm text-gray-700 dark:text-gray-300">
                  {request.customerNotes || "لا توجد ملاحظات"}
                </p>
              </div>

              {/* Enhanced Review Form */}
              <div className="bg-white dark:bg-gray-900/50 border-2 border-blue-100 dark:border-blue-900/30 p-4 rounded-lg space-y-4">
                <h3 className="text-sm font-bold text-blue-800 dark:text-blue-300 flex items-center gap-2">
                  <Shield size={16} /> مراجعة الطلب وتحديد المسؤولية
                </h3>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">
                      الجهة المسؤولة
                    </label>
                    <select
                      value={responsibleParty}
                      onChange={(e) =>
                        setResponsibleParty(e.target.value as any)
                      }
                      className="w-full text-sm border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-md"
                    >
                      <option value="CUSTOMER">
                        العميل (خطأ في القياس/تغيير رأي)
                      </option>
                      <option value="STORE">
                        المتجر (خطأ في التجهيز/عيب فني)
                      </option>
                      <option value="SHIPPING">شركة الشحن (تلف/تأخير)</option>
                      <option value="OTHER">أخرى</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">
                      قرار الحالة
                    </label>
                    <select
                      value={status}
                      onChange={(e) => setStatus(e.target.value as any)}
                      className="w-full text-sm border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-md"
                    >
                      <option value="PENDING">قيد الانتظار</option>
                      <option value="APPROVED">موافقة</option>
                      <option value="REJECTED">رفض</option>
                      <option value="COMPLETED">مكتمل</option>
                    </select>
                  </div>
                </div>
                {status === "REJECTED" && (
                  <div>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">
                      سبب الرفض
                    </label>
                    <input
                      type="text"
                      value={rejectionReason}
                      onChange={(e) => setRejectionReason(e.target.value)}
                      placeholder="اكتب سبب الرفض للعميل..."
                      className="w-full text-sm border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-md"
                    />
                  </div>
                )}
                <div>
                  <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">
                    ملاحظات إدارية (داخلية)
                  </label>
                  <textarea
                    value={adminNotes}
                    onChange={(e) => setAdminNotes(e.target.value)}
                    rows={2}
                    className="w-full text-sm border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-md"
                  />
                </div>
                <div className="flex items-center gap-2 pt-2">
                  <input
                    type="checkbox"
                    id="isReviewed"
                    checked={isReviewed}
                    onChange={(e) => setIsReviewed(e.target.checked)}
                    className="rounded text-blue-600 dark:text-blue-400"
                  />
                  <label
                    htmlFor="isReviewed"
                    className="text-xs font-bold text-gray-700 dark:text-gray-300"
                  >
                    تأكيد إتمام المراجعة (سيتم تحديث تقييم العميل بناءً على
                    المسؤولية)
                  </label>
                </div>
              </div>
            </div>
          )}

          {activeTab === "contact" && (
            <div className="space-y-6">
              {/* Add Attempt Form */}
              <form
                onSubmit={handleAddContact}
                className="bg-gray-50 dark:bg-gray-900/50 p-4 rounded-lg border border-gray-200 dark:border-gray-700"
              >
                <h3 className="text-sm font-bold text-gray-800 dark:text-white mb-4 flex items-center gap-2">
                  <Phone size={16} /> تسجيل محاولة تواصل
                </h3>
                <div className="grid grid-cols-2 gap-4 mb-4">
                  <div>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">
                      طريقة التواصل
                    </label>
                    <select
                      value={contactMethod}
                      onChange={(e) => setContactMethod(e.target.value)}
                      className="w-full text-sm border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-md shadow-sm focus:border-blue-500 dark:focus:border-blue-400 focus:ring-blue-500"
                    >
                      <option value="PHONE">📞 مكالمة هاتفية</option>
                      <option value="WHATSAPP">💬 واتساب</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">
                      النتيجة
                    </label>
                    <select
                      value={contactResult}
                      onChange={(e) => setContactResult(e.target.value)}
                      className="w-full text-sm border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-md shadow-sm focus:border-blue-500 dark:focus:border-blue-400 focus:ring-blue-500"
                    >
                      <option value="NO_ANSWER">لم يرد</option>
                      <option value="ANSWERED">تم الرد</option>
                      <option value="BUSY">مشغول</option>
                      <option value="WRONG_NUMBER">رقم خاطئ</option>
                      <option value="CALL_BACK_LATER">
                        طلب معاودة الاتصال
                      </option>
                    </select>
                  </div>
                </div>
                <div className="mb-4">
                  <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">
                    ملاحظات
                  </label>
                  <textarea
                    value={contactNotes}
                    onChange={(e) => setContactNotes(e.target.value)}
                    className="w-full text-sm border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-md shadow-sm focus:border-blue-500 dark:focus:border-blue-400 focus:ring-blue-500"
                    rows={2}
                    placeholder="تفاصيل المكالمة..."
                  />
                </div>
                <button
                  type="submit"
                  className="w-full bg-blue-600 dark:bg-blue-500 text-white py-2 px-4 rounded-md text-sm font-medium hover:bg-blue-700 dark:hover:bg-blue-600 transition-colors"
                >
                  تسجيل المحاولة
                </button>
              </form>

              {/* History List */}
              <div className="space-y-4">
                <h3 className="text-sm font-bold text-gray-700 dark:text-gray-300">
                  السجل السابق
                </h3>
                {loadingLogs ? (
                  <p className="text-center text-gray-500 dark:text-gray-400 text-sm">
                    جاري التحميل...
                  </p>
                ) : contactHistory.length === 0 ? (
                  <div className="text-center py-8 bg-gray-50 dark:bg-gray-900/50 rounded-lg text-gray-400 dark:text-gray-500 text-sm">
                    لا توجد محاولات تواصل مسجلة
                  </div>
                ) : (
                  contactHistory.map((attempt) => (
                    <div
                      key={attempt.id}
                      className="bg-white dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 p-4 rounded-lg flex items-start gap-3"
                    >
                      <div
                        className={`p-2 rounded-full ${attempt.method === "WHATSAPP" ? "bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400" : "bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400"}`}
                      >
                        {attempt.method === "WHATSAPP" ? (
                          <MessageCircle size={16} />
                        ) : (
                          <Phone size={16} />
                        )}
                      </div>
                      <div className="flex-1">
                        <div className="flex justify-between items-start">
                          <div>
                            <span className="font-bold text-sm text-gray-900 dark:text-white block mb-1">
                              {attempt.user?.firstName} {attempt.user?.lastName}
                            </span>
                            <span className="text-xs px-2 py-0.5 rounded-full bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-600">
                              {attempt.result}
                            </span>
                          </div>
                          <span className="text-xs text-gray-400 dark:text-gray-500 flex items-center gap-1">
                            <Calendar size={12} />
                            {new Date(attempt.createdAt).toLocaleString(
                              "ar-EG",
                            )}
                          </span>
                        </div>
                        {attempt.notes && (
                          <p className="mt-2 text-sm text-gray-600 dark:text-gray-300 bg-gray-50 dark:bg-gray-800 p-2 rounded">
                            "{attempt.notes}"
                          </p>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}

          {activeTab === "activity" && (
            <div className="space-y-4">
              {loadingLogs ? (
                <p className="text-center text-gray-500 dark:text-gray-400">
                  جاري التحميل...
                </p>
              ) : activityLog.length === 0 ? (
                <p className="text-center text-gray-500 dark:text-gray-400 py-8">
                  لا يوجد نشاط مسجل
                </p>
              ) : (
                <div className="relative border-r-2 border-gray-200 dark:border-gray-700 mr-4 space-y-8">
                  {activityLog.map((log) => (
                    <div
                      key={log.id}
                      className="relative flex items-start gap-4 mr-[-9px]"
                    >
                      <div className="bg-white dark:bg-gray-800 p-1 rounded-full border-2 border-blue-500 dark:border-blue-400">
                        <div className="w-2 h-2 bg-blue-500 dark:bg-blue-400 rounded-full"></div>
                      </div>
                      <div className="flex-1 bg-gray-50 dark:bg-gray-900/50 p-4 rounded-lg border border-gray-100 dark:border-gray-700">
                        <div className="flex justify-between items-center mb-2">
                          <span className="font-bold text-sm text-gray-900 dark:text-white">
                            {log.action}
                          </span>
                          <span className="text-xs text-gray-400 dark:text-gray-500">
                            {new Date(log.createdAt).toLocaleString("ar-EG")}
                          </span>
                        </div>
                        <p className="text-sm text-gray-600 dark:text-gray-300 mb-2">
                          قام <strong>{log.user?.firstName || "سيستم"}</strong>{" "}
                          بهذا الإجراء.
                        </p>
                        {log.details && (
                          <div className="text-xs bg-white dark:bg-gray-800 p-2 rounded border border-gray-200 dark:border-gray-700 font-mono text-gray-500 dark:text-gray-400 overflow-x-auto">
                            {typeof log.details === "string"
                              ? log.details
                              : JSON.stringify(log.details, null, 2)}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 rounded-b-lg flex justify-end gap-2">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-md text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
          >
            إغلاق
          </button>
          {activeTab === "details" && (
            <button
              onClick={handleSaveReview}
              disabled={submittingReview}
              className="px-6 py-2 bg-blue-600 dark:bg-blue-500 text-white rounded-md text-sm font-bold hover:bg-blue-700 dark:hover:bg-blue-600 transition-colors disabled:opacity-50"
            >
              {submittingReview ? "جاري الحفظ..." : "حفظ قرار المراجعة"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ReturnDetailsModal;

import React, { useState, useEffect } from "react";
import { returnService, ReturnRequest } from "../../services/returnService";
import toast from "react-hot-toast";
import {
  Plus,
  Filter,
  RefreshCw,
  CheckCircle,
  XCircle,
  Clock,
  Sparkles,
  Eye,
  Edit,
} from "lucide-react";
import ReturnDetailsModal from "./ReturnDetailsModal";

const ReturnManagementPage: React.FC = () => {
  const [requests, setRequests] = useState<ReturnRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedRequest, setSelectedRequest] = useState<ReturnRequest | null>(
    null,
  );

  // Analysis State
  const [analyzing, setAnalyzing] = useState<string | null>(null);

  // Filters
  const [statusFilter, setStatusFilter] = useState<string>("");

  // Create Modal State
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [categories, setCategories] = useState<any[]>([]);
  const [reasons, setReasons] = useState<any[]>([]);
  const [creating, setCreating] = useState(false);
  const [newReturn, setNewReturn] = useState({
    orderNumber: "",
    reasonId: "",
    customerNotes: "",
    adminNotes: "",
    responsibleParty: "OTHER" as "CUSTOMER" | "STORE" | "SHIPPING" | "OTHER",
  });

  // Edit Reason Modal State
  const [showEditReasonModal, setShowEditReasonModal] = useState(false);
  const [editingRequest, setEditingRequest] = useState<ReturnRequest | null>(
    null,
  );
  const [editForm, setEditForm] = useState({
    reasonId: "",
    responsibleParty: "OTHER" as "CUSTOMER" | "STORE" | "SHIPPING" | "OTHER",
    customerNotes: "",
    adminNotes: "",
  });

  const fetchData = async () => {
    setLoading(true);
    try {
      const [reqRes] = await Promise.all([
        returnService.getRequests(
          statusFilter ? { status: statusFilter } : undefined,
        ),
      ]);
      setRequests(reqRes.data);
    } catch (error) {
      toast.error("Failed to load data");
    } finally {
      setLoading(false);
    }
  };

  const fetchCategoriesAndReasons = async () => {
    try {
      const [catRes, reasonRes] = await Promise.all([
        returnService.getCategories(),
        returnService.getReasons(),
      ]);
      console.log("📦 Categories:", catRes.data);
      console.log("📋 Reasons:", reasonRes.data);
      setCategories(catRes.data);
      setReasons(reasonRes.data);
    } catch (error) {
      console.error("Failed to load categories/reasons:", error);
    }
  };

  useEffect(() => {
    fetchData();
    fetchCategoriesAndReasons();
  }, [statusFilter]);

  const handleUpdateStatus = async (id: string, newStatus: string) => {
    try {
      await returnService.updateRequest(id, { status: newStatus });
      toast.success("Status updated");
      fetchData();
    } catch (error) {
      toast.error("Failed to update status");
    }
  };

  const handleAnalyze = async (request: ReturnRequest) => {
    try {
      setAnalyzing(request.id);
      const result = await returnService.analyzeReturn(request.id);

      // In a real app, show a nice modal. For now, using alert/confirm is safe fallback or we could use toast
      // But let's log it and maybe show a simple alert
      const message = `
🤖 AI Recommendation: ${result.data?.recommendation || "N/A"}
📊 Confidence: ${((result.data?.confidence || 0) * 100).toFixed(1)}%

📝 Reasoning:
${result.data?.reasoning || "No reasoning provided"}

💬 Suggested Reply:
${result.data?.suggestedReply || "N/A"}
            `;
      alert(message);
    } catch (e: any) {
      console.error(e);
      toast.error(e.message || "Analysis failed");
    } finally {
      setAnalyzing(null);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "APPROVED":
        return (
          <span className="px-2 py-1 text-xs rounded-full bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300 flex items-center gap-1">
            <CheckCircle size={12} /> تم الموافقة
          </span>
        );
      case "REJECTED":
        return (
          <span className="px-2 py-1 text-xs rounded-full bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300 flex items-center gap-1">
            <XCircle size={12} /> مرفوض
          </span>
        );
      case "COMPLETED":
        return (
          <span className="px-2 py-1 text-xs rounded-full bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-300 flex items-center gap-1">
            <CheckCircle size={12} /> مكتمل
          </span>
        );
      default:
        return (
          <span className="px-2 py-1 text-xs rounded-full bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300 flex items-center gap-1">
            <Clock size={12} /> قيد الانتظار
          </span>
        );
    }
  };

  const getRatingBadge = (rating: string | undefined) => {
    if (!rating) return null;
    switch (rating) {
      case "EXCELLENT":
        return (
          <span className="mr-2 text-xs bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300 px-2 py-0.5 rounded-full">
            💎 ممتاز
          </span>
        );
      case "GOOD":
        return (
          <span className="mr-2 text-xs bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-2 py-0.5 rounded-full">
            ✅ جيد
          </span>
        );
      case "AVERAGE":
        return (
          <span className="mr-2 text-xs bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 px-2 py-0.5 rounded-full">
            متوسط
          </span>
        );
      case "BAD":
        return (
          <span className="mr-2 text-xs bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 px-2 py-0.5 rounded-full">
            ⛔ سيء
          </span>
        );
      default:
        return null;
    }
  };

  return (
    <div className="p-6 dark:bg-gray-900 min-h-screen" dir="rtl">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 dark:text-white">
            إدارة المرتجعات
          </h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm">
            إدارة طلبات الإرجاع وتقييمات العملاء
          </p>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          className="bg-primary hover:bg-primary-dark text-white px-4 py-2 rounded-lg flex items-center gap-2 dark:bg-blue-600 dark:hover:bg-blue-700"
        >
          <Plus size={18} /> طلب جديد
        </button>
      </div>

      {/* Filters */}
      <div className="flex gap-4 mb-6 bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400">
          <Filter size={18} />
          <span className="text-sm font-medium">Filter by Status:</span>
        </div>
        <div className="flex gap-2">
          {["", "PENDING", "APPROVED", "REJECTED", "COMPLETED"].map(
            (status) => (
              <button
                key={status}
                onClick={() => setStatusFilter(status)}
                className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${
                  statusFilter === status
                    ? "bg-blue-600 dark:bg-blue-500 text-white"
                    : "bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600"
                }`}
              >
                {status || "All"}
              </button>
            ),
          )}
        </div>
        <button
          onClick={fetchData}
          className="ml-auto text-gray-500 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400"
        >
          <RefreshCw size={18} />
        </button>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-lg shadow overflow-hidden border border-gray-200 dark:border-gray-700">
        <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
          <thead className="bg-gray-50 dark:bg-gray-900">
            <tr>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                الطلب
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                العميل
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                السبب
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                المسؤول
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                الحالة
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                المراجعة
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                التاريخ
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider pl-6">
                الإجراءات
              </th>
            </tr>
          </thead>
          <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
            {loading ? (
              <tr>
                <td
                  colSpan={8}
                  className="text-center py-8 text-gray-500 dark:text-gray-400"
                >
                  جاري التحميل...
                </td>
              </tr>
            ) : requests.length === 0 ? (
              <tr>
                <td
                  colSpan={8}
                  className="text-center py-8 text-gray-500 dark:text-gray-400"
                >
                  لا توجد طلبات إرجاع
                </td>
              </tr>
            ) : (
              requests.map((request) => (
                <tr
                  key={request.id}
                  className="hover:bg-gray-50 dark:hover:bg-gray-700/50"
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-gray-900 dark:text-white">
                      {request.order?.orderNumber || "غير متوفر"}
                    </div>
                    <div className="text-xs text-gray-500 dark:text-gray-400">
                      {request.refundAmount
                        ? `${request.refundAmount} ${request.order?.currency || "ج.م"}`
                        : "-"}
                    </div>
                  </td>
                  <td className="px-6 py-4 w-1/3">
                    <div className="flex items-center">
                      <div>
                        <div className="text-sm font-medium text-gray-900 dark:text-white flex items-center">
                          {request.customer?.firstName}{" "}
                          {request.customer?.lastName}
                          {getRatingBadge(request.customer?.customerRating)}
                        </div>
                        <div className="text-xs text-gray-500 dark:text-gray-400">
                          {request.customer?.phone}
                        </div>
                        <div className="text-xs text-gray-400 dark:text-gray-500">
                          معدل النجاح:{" "}
                          {request.customer?.successScore?.toFixed(1)}%
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm text-gray-900 dark:text-white">
                      {request.reason?.reason || "أخرى"}
                    </div>
                    <div className="text-xs text-gray-400 dark:text-gray-500">
                      {request.reason?.category?.name}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span
                      className={`text-xs px-2 py-0.5 rounded-full ${
                        request.responsibleParty === "CUSTOMER"
                          ? "bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400"
                          : request.responsibleParty === "STORE"
                            ? "bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400"
                            : "bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300"
                      }`}
                    >
                      {request.responsibleParty}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {getStatusBadge(request.status)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {request.isReviewed ? (
                      <span className="text-green-600 dark:text-green-400 text-xs flex items-center gap-1">
                        <CheckCircle size={14} /> تمت المراجعة
                      </span>
                    ) : (
                      <span className="text-orange-500 dark:text-orange-400 text-xs flex items-center gap-1">
                        <Clock size={14} /> لم تراجع
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                    {new Date(request.createdAt).toLocaleDateString()}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium pl-6">
                    <div className="flex justify-end gap-2">
                      {/* AI Analysis Button */}
                      <button
                        onClick={() => handleAnalyze(request)}
                        disabled={analyzing === request.id}
                        className="text-purple-600 dark:text-purple-400 hover:text-purple-900 dark:hover:text-purple-300 disabled:opacity-50"
                        title="تحليل الذكاء الاصطناعي"
                      >
                        {analyzing === request.id ? (
                          "..."
                        ) : (
                          <Sparkles size={18} />
                        )}
                      </button>

                      <button
                        onClick={() => {
                          setEditingRequest(request);
                          setEditForm({
                            reasonId: request.reasonId || "",
                            responsibleParty:
                              request.responsibleParty || "OTHER",
                            customerNotes: request.customerNotes || "",
                            adminNotes: request.adminNotes || "",
                          });
                          setShowEditReasonModal(true);
                        }}
                        className="text-orange-600 dark:text-orange-400 hover:text-orange-900 dark:hover:text-orange-300"
                        title="تعديل السبب"
                      >
                        <Edit size={18} />
                      </button>

                      <button
                        onClick={() => setSelectedRequest(request)}
                        className="text-blue-600 dark:text-blue-400 hover:text-blue-900 dark:hover:text-blue-300"
                        title="عرض التفاصيل"
                      >
                        <Eye size={18} />
                      </button>

                      {request.status === "PENDING" && (
                        <>
                          <button
                            onClick={() =>
                              handleUpdateStatus(request.id, "APPROVED")
                            }
                            className="text-green-600 dark:text-green-400 hover:text-green-900 dark:hover:text-green-300"
                            title="موافقة"
                          >
                            <CheckCircle size={18} />
                          </button>
                          <button
                            onClick={() =>
                              handleUpdateStatus(request.id, "REJECTED")
                            }
                            className="text-red-600 dark:text-red-400 hover:text-red-900 dark:hover:text-red-300"
                            title="رفض"
                          >
                            <XCircle size={18} />
                          </button>
                        </>
                      )}
                      {request.status === "APPROVED" && (
                        <button
                          onClick={() =>
                            handleUpdateStatus(request.id, "COMPLETED")
                          }
                          className="text-blue-600 dark:text-blue-400 hover:text-blue-900 dark:hover:text-blue-300"
                          title="تحديد كمكتمل"
                        >
                          <CheckCircle size={18} />
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Create Return Modal */}
      {showCreateModal && (
        <div
          className="fixed inset-0 bg-black/50 dark:bg-black/70 flex items-center justify-center z-50"
          onClick={() => setShowCreateModal(false)}
        >
          <div
            className="bg-white dark:bg-gray-800 rounded-2xl p-6 w-full max-w-2xl mx-4 max-h-[90vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                إنشاء طلب إرجاع جديد
              </h2>
              <button
                onClick={() => setShowCreateModal(false)}
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
              >
                <XCircle className="w-5 h-5 text-gray-500 dark:text-gray-400" />
              </button>
            </div>

            <div className="space-y-4">
              {/* Order Number */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  رقم الطلب *
                </label>
                <input
                  type="text"
                  value={newReturn.orderNumber}
                  onChange={(e) =>
                    setNewReturn({ ...newReturn, orderNumber: e.target.value })
                  }
                  placeholder="ORD-20260117-233349-05"
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                />
              </div>

              {/* Return Reason */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  سبب الإرجاع *
                </label>
                <select
                  value={newReturn.reasonId}
                  onChange={(e) => {
                    const selectedReason = reasons.find(
                      (r) => r.id === e.target.value,
                    );
                    setNewReturn({
                      ...newReturn,
                      reasonId: e.target.value,
                      responsibleParty:
                        selectedReason?.category?.defaultRole || "OTHER",
                    });
                  }}
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                >
                  <option value="">-- اختر السبب --</option>
                  {categories.map((cat) => (
                    <optgroup key={cat.id} label={cat.name}>
                      {reasons
                        .filter((r) => r.categoryId === cat.id)
                        .map((reason) => (
                          <option key={reason.id} value={reason.id}>
                            {reason.reason}{" "}
                            {reason.description && `- ${reason.description}`}
                          </option>
                        ))}
                    </optgroup>
                  ))}
                  {/* Reasons without category */}
                  {reasons.filter((r) => !r.categoryId).length > 0 && (
                    <optgroup label="أخرى">
                      {reasons
                        .filter((r) => !r.categoryId)
                        .map((reason) => (
                          <option key={reason.id} value={reason.id}>
                            {reason.reason}{" "}
                            {reason.description && `- ${reason.description}`}
                          </option>
                        ))}
                    </optgroup>
                  )}
                </select>
              </div>

              {/* Responsible Party */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  المسؤول
                </label>
                <div className="grid grid-cols-4 gap-2">
                  {["CUSTOMER", "STORE", "SHIPPING", "OTHER"].map((party) => (
                    <button
                      key={party}
                      type="button"
                      onClick={() =>
                        setNewReturn({
                          ...newReturn,
                          responsibleParty: party as any,
                        })
                      }
                      className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                        newReturn.responsibleParty === party
                          ? "bg-blue-600 text-white"
                          : "bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600"
                      }`}
                    >
                      {party === "CUSTOMER"
                        ? "عميل"
                        : party === "STORE"
                          ? "متجر"
                          : party === "SHIPPING"
                            ? "شحن"
                            : "أخرى"}
                    </button>
                  ))}
                </div>
              </div>

              {/* Customer Notes */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  ملاحظات العميل
                </label>
                <textarea
                  value={newReturn.customerNotes}
                  onChange={(e) =>
                    setNewReturn({
                      ...newReturn,
                      customerNotes: e.target.value,
                    })
                  }
                  rows={3}
                  placeholder="أي ملاحظات من العميل..."
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                />
              </div>

              {/* Admin Notes */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  ملاحظات الإدارة
                </label>
                <textarea
                  value={newReturn.adminNotes}
                  onChange={(e) =>
                    setNewReturn({ ...newReturn, adminNotes: e.target.value })
                  }
                  rows={3}
                  placeholder="ملاحظات داخلية للإدارة..."
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                />
              </div>

              {/* Actions */}
              <div className="flex justify-end gap-3 pt-4 border-t dark:border-gray-700">
                <button
                  onClick={() => setShowCreateModal(false)}
                  className="px-4 py-2 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
                >
                  إلغاء
                </button>
                <button
                  onClick={async () => {
                    if (!newReturn.orderNumber || !newReturn.reasonId) {
                      toast.error("رقم الطلب وسبب الإرجاع مطلوبان");
                      return;
                    }
                    setCreating(true);
                    try {
                      await returnService.createRequest({
                        orderNumber: newReturn.orderNumber,
                        reasonId: newReturn.reasonId,
                        customerNotes: newReturn.customerNotes,
                        adminNotes: newReturn.adminNotes,
                        responsibleParty: newReturn.responsibleParty,
                      });
                      toast.success("تم إنشاء طلب الإرجاع بنجاح");
                      setShowCreateModal(false);
                      setNewReturn({
                        orderNumber: "",
                        reasonId: "",
                        customerNotes: "",
                        adminNotes: "",
                        responsibleParty: "OTHER",
                      });
                      fetchData();
                    } catch (error: any) {
                      console.error(error);
                      toast.error(
                        error.response?.data?.error ||
                          "فشل في إنشاء طلب الإرجاع",
                      );
                    } finally {
                      setCreating(false);
                    }
                  }}
                  disabled={creating}
                  className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                >
                  {creating ? "جاري الإنشاء..." : "إنشاء الطلب"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Edit Reason Modal */}
      {showEditReasonModal && editingRequest && (
        <div
          className="fixed inset-0 bg-black/50 dark:bg-black/70 flex items-center justify-center z-50"
          onClick={() => setShowEditReasonModal(false)}
        >
          <div
            className="bg-white dark:bg-gray-800 rounded-2xl p-6 w-full max-w-2xl mx-4 max-h-[90vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                تعديل سبب الإرجاع
              </h2>
              <button
                onClick={() => setShowEditReasonModal(false)}
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
              >
                <XCircle className="w-5 h-5 text-gray-500 dark:text-gray-400" />
              </button>
            </div>

            <div className="space-y-4">
              {/* Return Reason */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  سبب الإرجاع *
                </label>
                <select
                  value={editForm.reasonId}
                  onChange={(e) => {
                    const selectedReason = reasons.find(
                      (r) => r.id === e.target.value,
                    );
                    setEditForm({
                      ...editForm,
                      reasonId: e.target.value,
                      responsibleParty:
                        selectedReason?.category?.defaultRole ||
                        editForm.responsibleParty,
                    });
                  }}
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                >
                  <option value="">-- اختر السبب --</option>
                  {categories.map((cat) => (
                    <optgroup key={cat.id} label={cat.name}>
                      {reasons
                        .filter((r) => r.categoryId === cat.id)
                        .map((reason) => (
                          <option key={reason.id} value={reason.id}>
                            {reason.reason}{" "}
                            {reason.description && `- ${reason.description}`}
                          </option>
                        ))}
                    </optgroup>
                  ))}
                  {/* Reasons without category */}
                  {reasons.filter((r) => !r.categoryId).length > 0 && (
                    <optgroup label="أخرى">
                      {reasons
                        .filter((r) => !r.categoryId)
                        .map((reason) => (
                          <option key={reason.id} value={reason.id}>
                            {reason.reason}{" "}
                            {reason.description && `- ${reason.description}`}
                          </option>
                        ))}
                    </optgroup>
                  )}
                </select>
              </div>

              {/* Responsible Party */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  المسؤول
                </label>
                <div className="grid grid-cols-4 gap-2">
                  {["CUSTOMER", "STORE", "SHIPPING", "OTHER"].map((party) => (
                    <button
                      key={party}
                      type="button"
                      onClick={() =>
                        setEditForm({
                          ...editForm,
                          responsibleParty: party as any,
                        })
                      }
                      className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                        editForm.responsibleParty === party
                          ? "bg-blue-600 text-white"
                          : "bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600"
                      }`}
                    >
                      {party === "CUSTOMER"
                        ? "عميل"
                        : party === "STORE"
                          ? "متجر"
                          : party === "SHIPPING"
                            ? "شحن"
                            : "أخرى"}
                    </button>
                  ))}
                </div>
              </div>

              {/* Customer Notes */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  ملاحظات العميل
                </label>
                <textarea
                  value={editForm.customerNotes}
                  onChange={(e) =>
                    setEditForm({ ...editForm, customerNotes: e.target.value })
                  }
                  rows={3}
                  placeholder="أي ملاحظات من العميل..."
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                />
              </div>

              {/* Admin Notes */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  ملاحظات الإدارة
                </label>
                <textarea
                  value={editForm.adminNotes}
                  onChange={(e) =>
                    setEditForm({ ...editForm, adminNotes: e.target.value })
                  }
                  rows={3}
                  placeholder="ملاحظات داخلية للإدارة..."
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                />
              </div>

              {/* Actions */}
              <div className="flex justify-end gap-3 pt-4 border-t dark:border-gray-700">
                <button
                  onClick={() => setShowEditReasonModal(false)}
                  className="px-4 py-2 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
                >
                  إلغاء
                </button>
                <button
                  onClick={async () => {
                    if (!editForm.reasonId) {
                      toast.error("سبب الإرجاع مطلوب");
                      return;
                    }
                    setCreating(true);
                    try {
                      await returnService.updateRequest(editingRequest.id, {
                        reasonId: editForm.reasonId,
                        responsibleParty: editForm.responsibleParty,
                        customerNotes: editForm.customerNotes,
                        adminNotes: editForm.adminNotes,
                      });
                      toast.success("تم تحديث السبب بنجاح");
                      setShowEditReasonModal(false);
                      setEditingRequest(null);
                      fetchData();
                    } catch (error: any) {
                      console.error(error);
                      toast.error(
                        error.response?.data?.error || "فشل في تحديث السبب",
                      );
                    } finally {
                      setCreating(false);
                    }
                  }}
                  disabled={creating}
                  className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                >
                  {creating ? "جاري التحديث..." : "حفظ التعديلات"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal Integration */}
      {selectedRequest && (
        <ReturnDetailsModal
          request={selectedRequest}
          onClose={() => setSelectedRequest(null)}
          onUpdate={fetchData}
        />
      )}
    </div>
  );
};

export default ReturnManagementPage;

