const ReturnSettingsPage: React.FC = () => {
  const [categories, setCategories] = useState<ReturnReasonCategory[]>([]);
  const [reasons, setReasons] = useState<ReturnReason[]>([]);
  const [loading, setLoading] = useState(true);

  // Form States
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [isReasonModalOpen, setIsReasonModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] =
    useState<ReturnReasonCategory | null>(null);
  const [editingReason, setEditingReason] = useState<ReturnReason | null>(null);

  const [categoryName, setCategoryName] = useState("");
  const [defaultRole, setDefaultRole] = useState<
    "CUSTOMER" | "STORE" | "SHIPPING" | "OTHER"
  >("OTHER");

  const [reasonText, setReasonText] = useState("");
  const [reasonDesc, setReasonDesc] = useState("");
  const [selectedCategoryId, setSelectedCategoryId] = useState("");

  const fetchData = async () => {
    setLoading(true);
    try {
      const [catRes, resRes] = await Promise.all([
        returnService.getCategories(),
        returnService.getReasons(),
      ]);
      setCategories(catRes.data);
      setReasons(resRes.data);
    } catch (error) {
      toast.error("Failed to load data");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const addDefaults = async () => {
    if (!confirm("سيتم إضافة بيانات افتراضية. هل أنت متأكد؟")) return;
    setLoading(true);
    try {
      for (const catData of DEFAULT_DATA) {
        // Create Category
        const catRes = await returnService.createCategory({
          name: catData.name,
          defaultRole: catData.defaultRole as any,
        });
        const catId = catRes.data.id;

        // Create Reasons for this category
        for (const reasonData of catData.reasons) {
          await returnService.createReason({
            reason: reasonData.reason,
            description: reasonData.description,
            categoryId: catId,
          });
        }
      }
      toast.success("تم إضافة البيانات الافتراضية بنجاح");
      fetchData();
    } catch (error) {
      console.error(error);
      toast.error("فشل في إضافة البيانات الافتراضية");
      setLoading(false);
    }
  };

  const handleSaveCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingCategory) {
        await returnService.updateCategory(editingCategory.id, {
          name: categoryName,
          defaultRole,
        });
        toast.success("تم تحديث التصنيف");
      } else {
        await returnService.createCategory({ name: categoryName, defaultRole });
        toast.success("تم إنشاء التصنيف");
      }
      setIsCategoryModalOpen(false);
      setEditingCategory(null);
      setCategoryName("");
      fetchData();
    } catch (error) {
      toast.error("فشل في الحفظ");
    }
  };

  const handleSaveReason = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingReason) {
        await returnService.updateReason(editingReason.id, {
          reason: reasonText,
          description: reasonDesc,
          categoryId: selectedCategoryId,
        });
        toast.success("تم تحديث السبب");
      } else {
        await returnService.createReason({
          reason: reasonText,
          description: reasonDesc,
          categoryId: selectedCategoryId,
        });
        toast.success("تم إنشاء السبب");
      }
      setIsReasonModalOpen(false);
      setEditingReason(null);
      setReasonText("");
      setReasonDesc("");
      setSelectedCategoryId("");
      fetchData();
    } catch (error) {
      toast.error("فشل في الحفظ");
    }
  };

  const deleteReason = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا السبب؟")) return;
    try {
      await returnService.deleteReason(id);
      toast.success("تم الحذف");
      fetchData();
    } catch (error) {
      toast.error("فشل في الحذف");
    }
  };

  return (
    <div
      className="p-6 bg-gray-50 dark:bg-gray-900 min-h-screen text-gray-900 dark:text-white"
      dir="rtl"
    >
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 dark:text-white">
            إعدادات المرتجعات
          </h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm">
            إدارة تصنيفات وأسباب الإرجاع والمسؤوليات
          </p>
        </div>
        <div className="flex gap-2">
          {categories.length === 0 && (
            <button
              onClick={addDefaults}
              className="bg-purple-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-purple-700 transition-colors"
            >
              <Sparkles size={18} /> اقتراحات ذكية
            </button>
          )}
          <button
            onClick={() => {
              setEditingCategory(null);
              setCategoryName("");
              setDefaultRole("OTHER");
              setIsCategoryModalOpen(true);
            }}
            className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-200 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
          >
            <FolderPlus size={18} /> تصنيف جديد
          </button>
          <button
            onClick={() => {
              setEditingReason(null);
              setReasonText("");
              setReasonDesc("");
              setSelectedCategoryId(categories[0]?.id || "");
              setIsReasonModalOpen(true);
            }}
            className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors"
          >
            <Plus size={18} /> سبب جديد
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Categories List */}
        <div className="lg:col-span-1">
          <h2 className="text-lg font-bold text-gray-700 dark:text-gray-200 mb-4 flex items-center gap-2">
            <FolderPlus size={20} className="text-blue-500" /> التصنيفات (الجهات
            المسؤولة)
          </h2>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow border border-gray-100 dark:border-gray-700 divide-y divide-gray-100 dark:divide-gray-700">
            {loading ? (
              <div className="p-4 text-center text-gray-500 dark:text-gray-400">
                جاري التحميل...
              </div>
            ) : categories.length === 0 ? (
              <div className="p-4 text-center text-gray-400">
                لا توجد تصنيفات
              </div>
            ) : (
              categories.map((cat) => (
                <div
                  key={cat.id}
                  className="p-4 flex justify-between items-center hover:bg-gray-50 dark:hover:bg-gray-700/50 group transition-colors"
                >
                  <div>
                    <div className="font-medium text-gray-900 dark:text-white">
                      {cat.name}
                    </div>
                    <div className="text-xs text-gray-500 dark:text-gray-400 flex items-center gap-1 mt-1">
                      <Shield size={12} /> المسؤول الافتراضي: {cat.defaultRole}
                    </div>
                  </div>
                  <button
                    onClick={() => {
                      setEditingCategory(cat);
                      setCategoryName(cat.name);
                      setDefaultRole(cat.defaultRole);
                      setIsCategoryModalOpen(true);
                    }}
                    className="text-gray-400 hover:text-blue-600 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Edit2 size={16} />
                  </button>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Reasons List */}
        <div className="lg:col-span-2">
          <h2 className="text-lg font-bold text-gray-700 dark:text-gray-200 mb-4 flex items-center gap-2">
            <Tag size={20} className="text-green-500" /> أسباب الإرجاع المتاحة
          </h2>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow border border-gray-100 dark:border-gray-700 overflow-hidden">
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-50 dark:bg-gray-900/50">
                <tr>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    السبب
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    التصنيف
                  </th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                    الحالة
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase pl-6">
                    الإجراءات
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                {loading ? (
                  <tr>
                    <td
                      colSpan={4}
                      className="p-4 text-center text-gray-500 dark:text-gray-400"
                    >
                      جاري التحميل...
                    </td>
                  </tr>
                ) : reasons.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="p-4 text-center text-gray-400">
                      لا توجد أسباب
                    </td>
                  </tr>
                ) : (
                  reasons.map((reason) => (
                    <tr
                      key={reason.id}
                      className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                    >
                      <td className="px-6 py-4">
                        <div className="text-sm font-medium text-gray-900 dark:text-white">
                          {reason.reason}
                        </div>
                        <div className="text-xs text-gray-500 dark:text-gray-400 truncate max-w-xs">
                          {reason.description}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-xs bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 px-2 py-1 rounded-md border border-blue-100 dark:border-blue-900/30">
                          {reason.category?.name || "غير مصنف"}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {reason.isActive ? (
                          <span className="text-green-600 dark:text-green-400 flex items-center gap-1 text-xs">
                            <CheckCircle size={14} /> نشط
                          </span>
                        ) : (
                          <span className="text-gray-400 dark:text-gray-500 flex items-center gap-1 text-xs">
                            <XCircle size={14} /> معطل
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 text-left pl-6">
                        <div className="flex gap-3">
                          <button
                            onClick={() => {
                              setEditingReason(reason);
                              setReasonText(reason.reason);
                              setReasonDesc(reason.description || "");
                              setSelectedCategoryId(reason.categoryId || "");
                              setIsReasonModalOpen(true);
                            }}
                            className="text-blue-600 hover:text-blue-500 dark:text-blue-400 dark:hover:text-blue-300"
                          >
                            <Edit2 size={16} />
                          </button>
                          <button
                            onClick={() => deleteReason(reason.id)}
                            className="text-red-400 hover:text-red-600"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Category Modal */}
      {isCategoryModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 dark:bg-opacity-70 flex items-center justify-center z-[60] p-4">
          <div className="bg-white dark:bg-gray-800 rounded-lg w-full max-w-md p-6 border border-gray-200 dark:border-gray-700 shadow-xl">
            <h3 className="text-lg font-bold mb-4 text-gray-900 dark:text-white">
              {editingCategory ? "تعديل تصنيف" : "تصنيف جديد"}
            </h3>
            <form onSubmit={handleSaveCategory}>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    اسم التصنيف (مثال: عيب صناعة)
                  </label>
                  <input
                    type="text"
                    required
                    value={categoryName}
                    onChange={(e) => setCategoryName(e.target.value)}
                    className="w-full border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg shadow-sm focus:border-blue-500 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    المسؤول الافتراضي عن هذا التصنيف
                  </label>
                  <select
                    value={defaultRole}
                    onChange={(e) => setDefaultRole(e.target.value as any)}
                    className="w-full border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg shadow-sm focus:border-blue-500 focus:ring-blue-500"
                  >
                    <option value="CUSTOMER">العميل (يؤثر على تقييمه)</option>
                    <option value="STORE">المتجر (عيب فني/تغليف)</option>
                    <option value="SHIPPING">
                      شركة الشحن (تلف أثناء النقل)
                    </option>
                    <option value="OTHER">أخرى (بدون تأثير)</option>
                  </select>
                </div>
              </div>
              <div className="flex justify-end gap-2 mt-6">
                <button
                  type="button"
                  onClick={() => setIsCategoryModalOpen(false)}
                  className="px-4 py-2 text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200"
                >
                  إلغاء
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                >
                  حفظ
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Reason Modal */}
      {isReasonModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 dark:bg-opacity-70 flex items-center justify-center z-[60] p-4">
          <div className="bg-white dark:bg-gray-800 rounded-lg w-full max-w-md p-6 border border-gray-200 dark:border-gray-700 shadow-xl">
            <h3 className="text-lg font-bold mb-4 text-gray-900 dark:text-white">
              {editingReason ? "تعديل سبب" : "سبب جديد"}
            </h3>
            <form onSubmit={handleSaveReason}>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    السبب (مثال: القياس غير مناسب)
                  </label>
                  <input
                    type="text"
                    required
                    value={reasonText}
                    onChange={(e) => setReasonText(e.target.value)}
                    className="w-full border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg shadow-sm focus:border-blue-500 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    التصنيف
                  </label>
                  <select
                    required
                    value={selectedCategoryId}
                    onChange={(e) => setSelectedCategoryId(e.target.value)}
                    className="w-full border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg shadow-sm focus:border-blue-500 focus:ring-blue-500"
                  >
                    <option value="">اختر تصنيفاً...</option>
                    {categories.map((cat) => (
                      <option key={cat.id} value={cat.id}>
                        {cat.name}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    وصف إضافي
                  </label>
                  <textarea
                    value={reasonDesc}
                    onChange={(e) => setReasonDesc(e.target.value)}
                    className="w-full border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg shadow-sm focus:border-blue-500 focus:ring-blue-500"
                    rows={3}
                  />
                </div>
              </div>
              <div className="flex justify-end gap-2 mt-6">
                <button
                  type="button"
                  onClick={() => setIsReasonModalOpen(false)}
                  className="px-4 py-2 text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200"
                >
                  إلغاء
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                >
                  حفظ
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ReturnSettingsPage;

import React, { useState, useEffect } from "react";
import { useAuth } from "../../hooks/useAuthSimple";
import {
  BuildingOfficeIcon,
  CreditCardIcon,
  ChartBarIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon,
  ArrowUpIcon,
  CurrencyDollarIcon,
  ShieldCheckIcon,
  GlobeAltIcon,
  SparklesIcon,
} from "@heroicons/react/24/outline";
import {
  SUPPORTED_CURRENCIES,
  DEFAULT_CURRENCY,
  formatCurrency,
  getCurrencyByCode,
} from "../../utils/currency";
import { tokenManager } from "../../utils/tokenManager";
import { getApiUrl, envConfig } from "../../config/environment";

import { useDateFormat } from "../../hooks/useDateFormat";
import {
  DateFormatType,
  DATE_FORMAT_LABELS,
  formatTimeWithZone,
} from "../../utils/dateFormat";

interface SubscriptionPlan {
  name: string;
  price: number;
  currency: string;
  limits: Record<string, number>;
  features: Record<string, boolean>;
}

interface UsageStat {
  usage: number;
  limit: number;
  percentage: number;
  unlimited: boolean;
  warning: boolean;
  exceeded: boolean;
}

const getAccessToken = (): string | null => tokenManager.getAccessToken();

const parseCompanySettings = (value: unknown): Record<string, any> => {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, any>;
  }

  if (typeof value !== "string" || !value.trim()) {
    return {};
  }

  try {
    const parsed = JSON.parse(value);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as Record<string, any>;
    }
  } catch (error) {
    console.warn("Failed to parse company settings:", error);
  }

  return {};
};

const CompanySettings: React.FC = () => {
  const { user } = useAuth();
  const [company, setCompany] = useState<any>(null);
  const [plans, setPlans] = useState<Record<string, SubscriptionPlan>>({});
  const [usage, setUsage] = useState<Record<string, UsageStat>>({});
  const [loading, setLoading] = useState(true);

  const [selectedCurrency, setSelectedCurrency] =
    useState<string>(DEFAULT_CURRENCY);
  const [savingCurrency, setSavingCurrency] = useState(false);

  // Time Preview
  const [currentTime, setCurrentTime] = useState<Date>(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  // Sidebar Layout
  const [sidebarLayout, setSidebarLayout] = useState<string>("three-tier");
  const [savingLayout, setSavingLayout] = useState(false);

  // Logo upload states
  const [uploadingLogo, setUploadingLogo] = useState(false);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);

  // Date format hook
  const {
    dateFormat,
    setDateFormat,
    isLoading: dateFormatLoading,
    error: dateFormatError,
    formatDate,
  } = useDateFormat();

  // Company name editing states
  const [editingName, setEditingName] = useState(false);
  const [companyName, setCompanyName] = useState("");
  const [savingName, setSavingName] = useState(false);
  const [editingDescription, setEditingDescription] = useState(false);
  const [companyDescription, setCompanyDescription] = useState("");
  const [savingDescription, setSavingDescription] = useState(false);

  // Slug states
  const [slug, setSlug] = useState("");
  const [editingSlug, setEditingSlug] = useState(false);
  const [savingSlug, setSavingSlug] = useState(false);

  // Custom domain states
  const [customDomain, setCustomDomain] = useState("");
  const [editingDomain, setEditingDomain] = useState(false);
  const [savingDomain, setSavingDomain] = useState(false);
  const [verifyingDNS, setVerifyingDNS] = useState(false);
  const [dnsStatus, setDnsStatus] = useState<{
    success: boolean;
    message: string;
  } | null>(null);

  // Tabs state
  const [activeTab, setActiveTab] = useState<
    "general" | "appearance" | "plan" | "usage" | "ownership"
  >("general");

  const customerRegisterUrl = user?.companyId
    ? `${window.location.origin}/auth/customer-register?companyId=${encodeURIComponent(user.companyId)}`
    : null;

  // Ownership Transfer State
  const [users, setUsers] = useState<any[]>([]);
  const [selectedNewOwner, setSelectedNewOwner] = useState("");
  const [transferring, setTransferring] = useState(false);
  const [showTransferConfirm, setShowTransferConfirm] = useState(false);

  useEffect(() => {
    fetchCompanyData();
    fetchPlans();
    fetchUsage();
    if (user?.role === "OWNER") {
      fetchCompanyUsers();
    }
  }, [user]);

  const fetchCompanyData = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );
      const data = await response.json();
      if (data.success) {
        const parsedCompanySettings = parseCompanySettings(data.data?.settings);
        setCompany({ ...data.data, settings: parsedCompanySettings });
        // Set currency from company data or use default
        setSelectedCurrency(data.data?.currency || DEFAULT_CURRENCY);
        // Set company name for editing
        setCompanyName(data.data?.name || "");
        // Set company description for SEO fallback editing
        setCompanyDescription(
          typeof parsedCompanySettings.description === "string"
            ? parsedCompanySettings.description
            : "",
        );
        // Set slug
        setSlug(data.data?.slug || "");
        // Set sidebar layout
        setSidebarLayout(data.data?.sidebarLayout || "three-tier");
        // Set custom domain
        setCustomDomain(data.data?.customDomain || "");
        // Set logo preview if exists
        if (data.data?.logo) {
          const logoUrl = data.data.logo.startsWith("http")
            ? data.data.logo
            : `${envConfig.backendUrl}${data.data.logo}`;
          setLogoPreview(logoUrl);
        }
      }
    } catch (error) {
      console.error("Error fetching company data:", error);
    }
  };

  const fetchPlans = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(`${getApiUrl()}/companies/plans`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const data = await response.json();
      if (data.success) {
        setPlans(data.data);
      }
    } catch (error) {
      console.error("Error fetching plans:", error);
    }
  };

  const fetchUsage = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/usage`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );
      const data = await response.json();
      if (data.success) {
        setUsage(data.data);
      }
    } catch (error) {
      console.error("Error fetching usage:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchCompanyUsers = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/users`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );
      const data = await response.json();
      if (data.success) {
        // Filter out current user (cannot transfer to self)
        setUsers(data.data.users.filter((u: any) => u.id !== user?.id));
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  const handleTransferOwnership = async () => {
    if (!selectedNewOwner) return;

    try {
      setTransferring(true);
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/transfer-ownership`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ targetUserId: selectedNewOwner }),
        },
      );

      const data = await response.json();

      if (data.success) {
        alert(
          "تم نقل الملكية بنجاح! سيتم إعادة تحميل الصفحة لتحديث الصلاحيات.",
        );
        window.location.reload();
      } else {
        alert(data.message || "فشل نقل الملكية");
      }
    } catch (error) {
      console.error("Error transferring ownership:", error);
      alert("حدث خطأ أثناء نقل الملكية");
    } finally {
      setTransferring(false);
      setShowTransferConfirm(false);
    }
  };

  const handleUpgrade = async (planName: string) => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/subscription`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ plan: planName }),
        },
      );

      const data = await response.json();
      if (data.success) {
        alert("تم تحديث الاشتراك بنجاح!");
        fetchCompanyData();
        fetchUsage();
      } else {
        alert(data.error || "فشل في تحديث الاشتراك");
      }
    } catch (error) {
      console.error("Error upgrading plan:", error);
      alert("حدث خطأ أثناء تحديث الاشتراك");
    }
  };

  const handleCompanyNameSave = async () => {
    if (!companyName.trim()) {
      alert("اسم الشركة مطلوب");
      return;
    }

    try {
      setSavingName(true);
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ name: companyName.trim() }),
        },
      );

      const data = await response.json();
      if (data.success) {
        setCompany((prev: any) => ({ ...prev, name: companyName.trim() }));
        setEditingName(false);
        alert("تم تحديث اسم الشركة بنجاح!");
      } else {
        alert(data.error || "فشل في تحديث اسم الشركة");
      }
    } catch (error) {
      console.error("Error updating company name:", error);
      alert("حدث خطأ أثناء تحديث اسم الشركة");
    } finally {
      setSavingName(false);
    }
  };

  const handleCompanyDescriptionSave = async () => {
    try {
      setSavingDescription(true);
      const token = getAccessToken();
      const normalizedDescription = companyDescription.trim();
      const response = await fetch(`${getApiUrl()}/settings/company`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          settings: {
            description: normalizedDescription,
          },
        }),
      });

      const data = await response.json();
      if (data.success) {
        setCompany((prev: any) => ({
          ...prev,
          settings: {
            ...(parseCompanySettings(prev?.settings) || {}),
            description: normalizedDescription,
          },
        }));
        setCompanyDescription(normalizedDescription);
        setEditingDescription(false);
        alert("تم تحديث وصف الشركة بنجاح!");
      } else {
        alert(data.error || data.message || "فشل في تحديث وصف الشركة");
      }
    } catch (error) {
      console.error("Error updating company description:", error);
      alert("حدث خطأ أثناء تحديث وصف الشركة");
    } finally {
      setSavingDescription(false);
    }
  };

  const handleSlugSave = async () => {
    if (!slug.trim()) {
      alert("الرابط مطلوب");
      return;
    }

    // Basic validation
    if (!/^[a-z0-9-]+$/.test(slug)) {
      alert("الرابط يجب أن يحتوي فقط على حروف إنجليزية صغيرة وأرقام وشرطة (-)");
      return;
    }

    try {
      setSavingSlug(true);
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/slug`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ slug: slug.trim() }),
        },
      );

      const data = await response.json();
      if (data.success) {
        setCompany((prev: any) => ({ ...prev, slug: slug.trim() }));
        setEditingSlug(false);
        alert("تم تحديث رابط الشركة بنجاح!");
        // Update user in local storage/context might be needed if slug is critical
        window.location.reload(); // Reload to ensure all links update
      } else {
        alert(
          data.error ||
            data.message ||
            "فشل في تحديث الرابط. قد يكون مستخدماً بالفعل.",
        );
      }
    } catch (error) {
      console.error("Error updating company slug:", error);
      alert("حدث خطأ أثناء تحديث رابط الشركة");
    } finally {
      setSavingSlug(false);
    }
  };

  const handleCurrencyChange = async (currencyCode: string) => {
    try {
      setSavingCurrency(true);
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/currency`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ currency: currencyCode }),
        },
      );

      const data = await response.json();
      if (data.success) {
        setSelectedCurrency(currencyCode);
        setCompany((prev: any) => ({ ...prev, currency: currencyCode }));
        alert("تم تحديث العملة بنجاح!");
      } else {
        alert(data.error || "فشل في تحديث العملة");
      }
    } catch (error) {
      console.error("Error updating currency:", error);
      alert("حدث خطأ أثناء تحديث العملة");
    } finally {
      setSavingCurrency(false);
    }
  };

  const handleLayoutChange = async (layout: string) => {
    try {
      setSavingLayout(true);
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ sidebarLayout: layout }),
        },
      );

      const data = await response.json();
      if (data.success) {
        setSidebarLayout(layout);
        setCompany((prev: any) => ({ ...prev, sidebarLayout: layout }));
        // Reload page to apply changes everywhere (simple way) or rely on Context
        if (
          window.confirm(
            "تم تحديث نظام القائمة بنجاح! هل تريد إعادة تحميل الصفحة لتطبيق التغييرات؟",
          )
        ) {
          window.location.reload();
        }
      } else {
        alert(data.error || "فشل في تحديث نظام القائمة");
      }
    } catch (error) {
      console.error("Error updating layout:", error);
      alert("حدث خطأ أثناء تحديث نظام القائمة");
    } finally {
      setSavingLayout(false);
    }
  };

  const handleCustomDomainSave = async () => {
    if (
      customDomain &&
      !/^[a-zA-Z0-9][a-zA-Z0-9-]{0,61}[a-zA-Z0-9]?\.[a-zA-Z]{2,}$/.test(
        customDomain,
      )
    ) {
      alert("صيغة الدومين غير صحيحة. يجب أن يكون مثل: example.com (بدون www)");
      return;
    }

    try {
      setSavingDomain(true);
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ customDomain: customDomain || null }),
        },
      );

      const data = await response.json();
      if (data.success) {
        setCompany((prev: any) => ({
          ...prev,
          customDomain: customDomain || null,
        }));
        setEditingDomain(false);
        alert("تم تحديث الدومين المخصص بنجاح!");
      } else {
        alert(data.message || data.error || "فشل في تحديث الدومين");
      }
    } catch (error) {
      console.error("Error updating custom domain:", error);
      alert("حدث خطأ أثناء تحديث الدومين");
    } finally {
      setSavingDomain(false);
    }
  };

  const handleTimezoneChange = async (newTimezone: string) => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ timezone: newTimezone }),
        },
      );

      const data = await response.json();
      if (data.success) {
        setCompany((prev: any) => ({ ...prev, timezone: newTimezone }));
        alert("تم تحديث المنطقة الزمنية بنجاح!");
      } else {
        alert(data.error || "فشل في تحديث المنطقة الزمنية");
      }
    } catch (error) {
      console.error("Error updating timezone:", error);
      alert("حدث خطأ أثناء تحديث المنطقة الزمنية");
    }
  };

  const handleVerifyDNS = async () => {
    if (!company?.id) return;

    try {
      setVerifyingDNS(true);
      setDnsStatus(null);
      const token = getAccessToken();
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/verify-dns`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      const data = await response.json();
      setDnsStatus({
        success: data.success,
        message: data.message,
      });
    } catch (error) {
      console.error("Error verifying DNS:", error);
      setDnsStatus({
        success: false,
        message: "حدث خطأ أثناء الاتصال بالسيرفر للتحقق من DNS",
      });
    } finally {
      setVerifyingDNS(false);
    }
  };

  const handleLogoUpload = async (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith("image/")) {
      alert("يُسمح فقط بملفات الصور");
      return;
    }

    // Validate file size (5MB)
    if (file.size > 5 * 1024 * 1024) {
      alert("حجم الملف يجب أن يكون أقل من 5 ميجابايت");
      return;
    }

    try {
      setUploadingLogo(true);

      // Create FormData
      const formData = new FormData();
      formData.append("logo", file);

      // Get token from localStorage
      const token = getAccessToken();

      // Upload logo
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/logo`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
          },
          body: formData,
        },
      );

      const data = await response.json();

      if (data.success) {
        const logoUrl = data.data.logo.startsWith("http")
          ? data.data.logo
          : `${envConfig.backendUrl}${data.data.logo}`;
        setLogoPreview(logoUrl);
        setCompany((prev: any) => ({ ...prev, logo: data.data.logo }));
        alert("تم رفع اللوجو بنجاح!");
      } else {
        alert(data.error || "فشل في رفع اللوجو");
      }
    } catch (error) {
      console.error("Error uploading logo:", error);
      alert("حدث خطأ أثناء رفع اللوجو");
    } finally {
      setUploadingLogo(false);
    }
  };

  const getUsageColor = (stat: UsageStat) => {
    if (stat.exceeded) return "text-red-600 bg-red-100";
    if (stat.warning) return "text-yellow-600 bg-yellow-100";
    return "text-green-600 bg-green-100";
  };

  const getUsageBarColor = (stat: UsageStat) => {
    if (stat.exceeded) return "bg-red-500";
    if (stat.warning) return "bg-yellow-500";
    return "bg-green-500";
  };

  const formatLimit = (limit: number) => {
    if (limit === -1) return "غير محدود";
    if (limit >= 1000000) return `${(limit / 1000000).toFixed(1)}م`;
    if (limit >= 1000) return `${(limit / 1000).toFixed(1)}ك`;
    return limit.toString();
  };

  const resourceNames: Record<string, string> = {
    users: "المستخدمين",
    customers: "العملاء",
    conversations: "المحادثات",
    products: "المنتجات",
    orders: "الطلبات",
    storage: "التخزين (MB)",
    aiRequests: "طلبات الذكاء الاصطناعي",
    emailNotifications: "إشعارات البريد الإلكتروني",
    smsNotifications: "الرسائل النصية",
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  const tabs = [
    { id: "general", label: "عام", icon: BuildingOfficeIcon },
    { id: "appearance", label: "المظهر", icon: ChartBarIcon },
    { id: "plan", label: "الاشتراك", icon: CreditCardIcon },
    { id: "usage", label: "الاستخدام", icon: ChartBarIcon },
  ];

  if (user?.role === "OWNER") {
    tabs.push({ id: "ownership", label: "الملكية", icon: ShieldCheckIcon });
  }

  return (
    <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          إعدادات الشركة
        </h1>
        <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
          إدارة إعدادات الشركة والاشتراكات
        </p>
      </div>

      {/* Tabs Header */}
      <div className="border-b border-gray-200 dark:border-gray-700 mb-8">
        <nav
          className="-mb-px flex space-x-8 space-x-reverse"
          aria-label="Tabs"
        >
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`${
                activeTab === tab.id
                  ? "border-indigo-500 text-indigo-600 dark:text-indigo-400"
                  : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400 dark:hover:text-gray-300"
              } group inline-flex items-center py-4 px-1 border-b-2 font-medium text-sm transition-colors duration-200`}
            >
              <tab.icon
                className={`${
                  activeTab === tab.id
                    ? "text-indigo-500 dark:text-indigo-400"
                    : "text-gray-400 group-hover:text-gray-500 dark:text-gray-500"
                } -ml-0.5 mr-2 h-5 w-5`}
                aria-hidden="true"
              />
              <span className="mr-2">{tab.label}</span>
            </button>
          ))}
        </nav>
      </div>

      {activeTab === "general" && (
        <div className="space-y-6">
          {/* Company Info */}
          <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-8">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4">
              معلومات الشركة
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                {editingName ? (
                  <label
                    htmlFor="company-name-input"
                    className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                  >
                    اسم الشركة
                  </label>
                ) : (
                  <span className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    اسم الشركة
                  </span>
                )}
                {editingName ? (
                  <div className="mt-1 flex items-center space-x-2 space-x-reverse">
                    <input
                      id="company-name-input"
                      name="companyName"
                      type="text"
                      autoComplete="organization"
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      placeholder="اسم الشركة (يفضل بالإنجليزية)"
                      disabled={savingName}
                    />
                    <p className="mt-1 text-xs text-gray-500">
                      اسم الشركة بالإنجليزية يسهل توليد رابط المتجر تلقائياً
                    </p>
                    <button
                      onClick={handleCompanyNameSave}
                      disabled={savingName || !companyName.trim()}
                      className="px-3 py-2 bg-indigo-600 text-white text-sm font-medium rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:bg-gray-400 disabled:cursor-not-allowed"
                    >
                      {savingName ? "حفظ..." : "حفظ"}
                    </button>
                    <button
                      onClick={() => {
                        setEditingName(false);
                        setCompanyName(company?.name || "");
                      }}
                      disabled={savingName}
                      className="px-3 py-2 bg-gray-300 dark:bg-gray-600 text-gray-700 dark:text-gray-300 text-sm font-medium rounded-md hover:bg-gray-400 dark:hover:bg-gray-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 disabled:cursor-not-allowed"
                    >
                      إلغاء
                    </button>
                  </div>
                ) : (
                  <div className="mt-1 flex items-center justify-between">
                    <p className="text-lg text-gray-900 dark:text-white">
                      {company?.name}
                    </p>
                    <button
                      onClick={() => setEditingName(true)}
                      className="text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 text-sm font-medium"
                    >
                      تعديل
                    </button>
