                    aria-readonly="true"
                    autoComplete="off"
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-gray-50 dark:bg-gray-900/50 text-gray-800 dark:text-gray-200 text-sm"
                  />
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => window.open(customerRegisterUrl, "_blank")}
                      className="px-3 py-2 bg-indigo-600 text-white text-sm font-medium rounded-md hover:bg-indigo-700"
                    >
                      فتح
                    </button>
                    <button
                      type="button"
                      onClick={async () => {
                        try {
                          await navigator.clipboard.writeText(
                            customerRegisterUrl,
                          );
                          alert("تم نسخ الرابط");
                        } catch (e) {
                          alert("تعذر نسخ الرابط");
                        }
                      }}
                      className="px-3 py-2 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 text-sm font-medium rounded-md hover:bg-gray-300 dark:hover:bg-gray-600"
                    >
                      نسخ
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Logo Upload Section */}
          <div className="mt-6 pt-6 border-t border-gray-200 dark:border-gray-600">
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">
              لوجو الشركة
            </h3>
            <div className="flex items-start space-x-4 space-x-reverse">
              {/* Logo Preview */}
              <div className="flex-shrink-0">
                {logoPreview ? (
                  <img
                    src={logoPreview}
                    alt="Company Logo"
                    className="h-24 w-24 rounded-lg object-cover border-2 border-gray-200"
                  />
                ) : (
                  <div className="h-24 w-24 rounded-lg bg-gray-100 flex items-center justify-center border-2 border-dashed border-gray-300">
                    <BuildingOfficeIcon className="h-12 w-12 text-gray-400" />
                  </div>
                )}
              </div>

              {/* Upload Button */}
              <div className="flex-1">
                <label
                  htmlFor="company-logo-upload"
                  className="block text-sm font-medium text-gray-700 mb-2"
                >
                  رفع لوجو جديد
                </label>
                <div className="flex items-center">
                  <label
                    htmlFor="company-logo-upload"
                    className="relative cursor-pointer bg-white rounded-md font-medium text-indigo-600 hover:text-indigo-500 focus-within:outline-none"
                  >
                    <span className="inline-flex items-center px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500">
                      {uploadingLogo ? (
                        <>
                          <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-indigo-600 ml-2"></div>
                          جاري الرفع...
                        </>
                      ) : (
                        <>
                          <svg
                            className="ml-2 h-5 w-5 text-gray-400"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"
                            />
                          </svg>
                          اختر صورة
                        </>
                      )}
                    </span>
                    <input
                      id="company-logo-upload"
                      name="companyLogo"
                      type="file"
                      className="sr-only"
                      accept="image/*"
                      onChange={handleLogoUpload}
                      disabled={uploadingLogo}
                    />
                  </label>
                </div>
              </div>
              <p className="mt-2 text-xs text-gray-500">
                PNG, JPG, GIF حتى 5MB
              </p>
            </div>
          </div>

          {/* Custom Domain Redirect Section */}
          <div className="mt-6 pt-6 border-t border-gray-200 dark:border-gray-600">
            <div className="bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800 rounded-xl p-6">
              <div className="flex items-start gap-4">
                <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 rounded-lg shrink-0">
                  <GlobeAltIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
                </div>
                <div>
                  <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-1">
                    إعدادات الدومين المخصص انتقلت لمكان جديد!
                  </h3>
                  <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
                    لقد قمنا بتحسين تجربة ربط الدومينات المخصصة وتوفير شرح مفصل
                    في صفحة مستقلة لضمان ربط متجرك بأمان وسهولة.
                  </p>
                  <div className="flex items-center gap-3">
                    <p className="text-xs text-gray-500 dark:text-gray-500 font-medium whitespace-nowrap">
                      تجدها الآن في القائمة الجانبية تحت مسمى "الدومين المخصص".
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar Layout Settings */}
      {activeTab === "appearance" && (
        <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-8">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
            <ChartBarIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400 mr-2" />
            نظام القائمة الجانبية
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {[
              {
                id: "classic",
                name: "الكلاسيكي (Classic)",
                description: "القائمة التقليدية",
              },
              {
                id: "three-tier",
                name: "الحديث (Three-Tier)",
                description: "قائمة رفيعة + فرعية",
              },
              {
                id: "horizontal",
                name: "الأفقي (Horizontal)",
                description: "شريط تنقل علوي",
              },
              {
                id: "floating",
                name: "العائم (Floating)",
                description: "قائمة عائمة بتصميم كارت",
              },
              {
                id: "minimal",
                name: "المينيمال (Focus)",
                description: "أيقونات مع قوائم منبثقة",
              },
            ].map((option) => (
              <button
                key={option.id}
                onClick={() => handleLayoutChange(option.id)}
                disabled={savingLayout}
                className={`relative p-4 rounded-xl border-2 text-right transition-all duration-200 ${
                  sidebarLayout === option.id
                    ? "border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20"
                    : "border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600"
                }`}
              >
                <h3
                  className={`font-semibold ${sidebarLayout === option.id ? "text-indigo-700 dark:text-indigo-300" : "text-gray-900 dark:text-white"}`}
                >
                  {option.name}
                </h3>
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                  {option.description}
                </p>
                {sidebarLayout === option.id && (
                  <div className="absolute top-4 left-4 h-5 w-5 bg-indigo-500 rounded-full flex items-center justify-center">
                    <CheckCircleIcon className="h-3 w-3 text-white" />
                  </div>
                )}
              </button>
            ))}
          </div>
        </div>
      )}

      {activeTab === "general" && (
        <div className="space-y-6">
          {/* Currency Settings */}
          <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-8">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
              <CurrencyDollarIcon className="h-6 w-6 text-green-600 dark:text-green-400 mr-2" />
              إعدادات العملة
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label
                  htmlFor="company-currency"
                  className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
                >
                  العملة الافتراضية للموقع
                </label>
                <select
                  id="company-currency"
                  name="currency"
                  autoComplete="off"
                  value={selectedCurrency}
                  onChange={(e) => handleCurrencyChange(e.target.value)}
                  disabled={savingCurrency}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-gray-100 disabled:cursor-not-allowed bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                >
                  {SUPPORTED_CURRENCIES.map((currency) => (
                    <option key={currency.code} value={currency.code}>
                      {currency.nameAr} ({currency.symbol}) - {currency.code}
                    </option>
                  ))}
                </select>
                {savingCurrency && (
                  <p className="mt-2 text-sm text-blue-600 flex items-center">
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600 mr-2"></div>
                    جاري حفظ التغييرات...
                  </p>
                )}
              </div>
              <div>
                <span className="block text-sm font-medium text-gray-700 mb-2">
                  معاينة العملة
                </span>
                <div className="bg-gray-50 border border-gray-200 rounded-md p-3">
                  <p className="text-sm text-gray-600 mb-1">
                    مثال على عرض السعر:
                  </p>
                  <p className="text-lg font-semibold text-gray-900">
                    {formatCurrency(1250, selectedCurrency)}
                  </p>
                  <p className="text-xs text-gray-500 mt-1">
                    العملة المختارة:{" "}
                    {getCurrencyByCode(selectedCurrency)?.nameAr}
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Date Format Settings */}
          <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-8">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
              <CurrencyDollarIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400 mr-2" />
              إعدادات الوقت والتاريخ
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label
                  htmlFor="company-timezone"
                  className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
                >
                  المنطقة الزمنية للشركة
                </label>
                <select
                  id="company-timezone"
                  name="timezone"
                  autoComplete="off"
                  value={company?.timezone || "Asia/Riyadh"}
                  onChange={(e) => handleTimezoneChange(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                >
                  <optgroup label="الخليج العربي">
                    <option value="Asia/Riyadh">
                      الرياض - السعودية (GMT+3)
                    </option>
                    <option value="Asia/Kuwait">الكويت (GMT+3)</option>
                    <option value="Asia/Bahrain">البحرين (GMT+3)</option>
                    <option value="Asia/Qatar">قطر (GMT+3)</option>
                    <option value="Asia/Dubai">دبي - الإمارات (GMT+4)</option>
                    <option value="Asia/Muscat">مسقط - عمان (GMT+4)</option>
                  </optgroup>
                  <optgroup label="الشام والعراق">
                    <option value="Asia/Amman">عمّان - الأردن (GMT+3)</option>
                    <option value="Asia/Beirut">بيروت - لبنان (GMT+2)</option>
                    <option value="Asia/Damascus">دمشق - سوريا (GMT+3)</option>
                    <option value="Asia/Baghdad">بغداد - العراق (GMT+3)</option>
                    <option value="Asia/Jerusalem">
                      القدس - فلسطين (GMT+2)
                    </option>
                  </optgroup>
                  <optgroup label="شمال أفريقيا">
                    <option value="Africa/Cairo">القاهرة - مصر (GMT+2)</option>
                    <option value="Africa/Tripoli">
                      طرابلس - ليبيا (GMT+2)
                    </option>
                    <option value="Africa/Tunis">تونس (GMT+1)</option>
                    <option value="Africa/Algiers">الجزائر (GMT+1)</option>
                    <option value="Africa/Casablanca">
                      الدار البيضاء - المغرب (GMT+1)
                    </option>
                    <option value="Africa/Khartoum">
                      الخرطوم - السودان (GMT+2)
                    </option>
                  </optgroup>
                  <optgroup label="أخرى">
                    <option value="UTC">توقيت عالمي (UTC)</option>
                  </optgroup>
                </select>
                <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                  سيتم استخدام هذا التوقيت في التقارير والحسابات اليومية
                </p>
              </div>
              <div>
                <span className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  توقيت الشركة الحالي
                </span>
                <div className="bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-md p-3 flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
                      الساعة الآن:
                    </p>
                    <p className="text-2xl font-mono font-bold text-indigo-600 dark:text-indigo-400">
                      {formatTimeWithZone(
                        currentTime,
                        company?.timezone || "Asia/Riyadh",
                      )}
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      {company?.timezone || "Asia/Riyadh"}
                    </p>
                    <p className="text-xs font-medium text-gray-700 dark:text-gray-300 mt-1">
                      {new Intl.DateTimeFormat("ar-EG", {
                        weekday: "long",
                        year: "numeric",
                        month: "long",
                        day: "numeric",
                        timeZone: company?.timezone || "Asia/Riyadh",
                      }).format(currentTime)}
                    </p>
                  </div>
                </div>
              </div>
              <div>
                <span className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  تنسيق التاريخ
                </span>
                <div className="space-y-2">
                  {Object.entries(DATE_FORMAT_LABELS).map(([format, label]) => (
                    <label key={format} className="flex items-center">
                      <input
                        id={`company-date-format-${format}`}
                        type="radio"
                        name="dateFormat"
                        value={format}
                        checked={dateFormat === format}
                        onChange={(e) =>
                          setDateFormat(e.target.value as DateFormatType)
                        }
                        disabled={dateFormatLoading}
                        className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 dark:border-gray-600"
                      />
                      <span className="mr-2 text-sm text-gray-700 dark:text-gray-300">
                        {label}
                      </span>
                    </label>
                  ))}
                </div>
                {dateFormatError && (
                  <p className="text-xs text-red-600 mt-1">{dateFormatError}</p>
                )}
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-2">
                  التنسيق المختار: {DATE_FORMAT_LABELS[dateFormat]}
                </p>
              </div>
              <div>
                <span className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  معاينة التاريخ
                </span>
                <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-4">
                  <div className="text-sm text-gray-600 dark:text-gray-300 mb-2">
                    التاريخ الحالي:
                  </div>
                  <div className="text-lg font-semibold text-gray-900 dark:text-white">
                    {formatDate(new Date())}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === "usage" && (
        <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-8">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-6 flex items-center">
            <ChartBarIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400 mr-2" />
            إحصائيات الاستخدام
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {Object.entries(usage).map(([resource, stat]) => (
              <div
                key={resource}
                className="border border-gray-200 dark:border-gray-600 rounded-lg p-4"
              >
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300">
                    {resourceNames[resource] || resource}
                  </h3>
                  <span
                    className={`px-2 py-1 rounded-full text-xs font-medium ${getUsageColor(stat)}`}
                  >
                    {stat.unlimited ? "غير محدود" : `${stat.percentage}%`}
                  </span>
                </div>

                <div className="mb-2">
                  <div className="flex justify-between text-sm text-gray-600 dark:text-gray-400">
                    <span>{stat.usage.toLocaleString()}</span>
                    <span>{formatLimit(stat.limit)}</span>
                  </div>
                  {!stat.unlimited && (
                    <div className="w-full bg-gray-200 dark:bg-gray-600 rounded-full h-2 mt-1">
                      <div
                        className={`h-2 rounded-full ${getUsageBarColor(stat)}`}
                        style={{ width: `${Math.min(stat.percentage, 100)}%` }}
                      ></div>
                    </div>
                  )}
                </div>

                {stat.exceeded && (
                  <div className="flex items-center text-red-600 text-xs">
                    <ExclamationTriangleIcon className="h-4 w-4 mr-1" />
                    تم تجاوز الحد المسموح
                  </div>
                )}
                {stat.warning && !stat.exceeded && (
                  <div className="flex items-center text-yellow-600 text-xs">
                    <ExclamationTriangleIcon className="h-4 w-4 mr-1" />
                    قريب من الحد المسموح
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === "plan" && (
        <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-6 flex items-center">
            <CreditCardIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400 mr-2" />
            باقات الاشتراك
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {Object.entries(plans).map(([planKey, plan]) => {
              const isCurrentPlan = company?.subscription?.plan === planKey;
              const isUpgrade =
                ["BASIC", "PREMIUM", "ENTERPRISE"].indexOf(planKey) >
                ["FREE", "BASIC", "PREMIUM", "ENTERPRISE"].indexOf(
                  company?.subscription?.plan,
                );

              return (
                <div
                  key={planKey}
                  className={`border rounded-lg p-6 ${
                    isCurrentPlan
                      ? "border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20 dark:border-indigo-400"
                      : "border-gray-200 dark:border-gray-600"
                  }`}
                >
                  <div className="text-center mb-4">
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                      {plan.name}
                    </h3>
                    <div className="mt-2">
                      <span className="text-3xl font-bold text-gray-900 dark:text-white">
                        {plan.price}
                      </span>
                      <span className="text-gray-600 dark:text-gray-400 mr-1">
                        {plan.currency}/شهر
                      </span>
                    </div>
                  </div>

                  <div className="space-y-2 mb-6">
                    <h4 className="font-medium text-gray-900 dark:text-white">
                      الحدود:
                    </h4>
                    {Object.entries(plan.limits)
                      .slice(0, 4)
                      .map(([resource, limit]) => (
                        <div
                          key={resource}
                          className="flex justify-between text-sm"
                        >
                          <span className="text-gray-600 dark:text-gray-400">
                            {resourceNames[resource]}
                          </span>
                          <span className="font-medium text-gray-900 dark:text-white">
                            {formatLimit(limit)}
                          </span>
                        </div>
                      ))}
                  </div>

                  <div className="space-y-2 mb-6">
                    <h4 className="font-medium text-gray-900 dark:text-white">
                      الميزات:
                    </h4>
                    {Object.entries(plan.features)
                      .slice(0, 3)
                      .map(([feature, enabled]) => (
                        <div
                          key={feature}
                          className="flex items-center text-sm"
                        >
                          <CheckCircleIcon
                            className={`h-4 w-4 mr-2 ${enabled ? "text-green-500" : "text-gray-300 dark:text-gray-600"}`}
                          />
                          <span
                            className={
                              enabled
                                ? "text-gray-900 dark:text-white"
                                : "text-gray-400 dark:text-gray-500"
                            }
                          >
                            {feature}
                          </span>
                        </div>
                      ))}
                  </div>

                  {isCurrentPlan ? (
                    <div className="text-center">
                      <span className="inline-flex items-center px-4 py-2 border border-indigo-300 dark:border-indigo-500 rounded-md text-sm font-medium text-indigo-700 dark:text-indigo-300 bg-indigo-100 dark:bg-indigo-900/30">
                        <CheckCircleIcon className="h-4 w-4 mr-2" />
                        الباقة الحالية
                      </span>
                    </div>
                  ) : (
                    <button
                      onClick={() => handleUpgrade(planKey)}
                      className={`w-full flex items-center justify-center px-4 py-2 border border-transparent rounded-md text-sm font-medium ${
                        isUpgrade
                          ? "text-white bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600"
                          : "text-indigo-600 dark:text-indigo-400 bg-indigo-100 dark:bg-indigo-900/30 hover:bg-indigo-200 dark:hover:bg-indigo-900/50"
                      }`}
                    >
                      {isUpgrade && <ArrowUpIcon className="h-4 w-4 mr-2" />}
                      {isUpgrade ? "ترقية" : "تغيير"}
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {activeTab === "ownership" && user?.role === "OWNER" && (
        <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 border-2 border-red-100 dark:border-red-900/30">
          <h2 className="text-xl font-semibold text-red-600 dark:text-red-400 mb-6 flex items-center">
            <ShieldCheckIcon className="h-6 w-6 mr-2" />
            نقل ملكية الشركة
          </h2>

          <div className="bg-red-50 dark:bg-red-900/20 p-4 rounded-lg mb-6">
            <h3 className="text-red-800 dark:text-red-200 font-medium mb-2">
              ⚠️ منطقة خطر!
            </h3>
            <div className="text-sm text-red-700 dark:text-red-300">
              نقل الملكية إجراء نهائي لا يمكن التراجع عنه. عند نقل الملكية لموظف
              آخر:
              <ul className="list-disc list-inside mt-2 space-y-1">
                <li>ستفقد صلاحيات المالك وتصبح مديراً (Admin) فقط.</li>
                <li>
                  سيحصل المالك الجديد على كامل الصلاحيات بما في ذلك حذفك من
                  النظام.
                </li>
                <li>سيطالبك النظام بتسجيل الدخول مجدداً لتحديث الصلاحيات.</li>
              </ul>
            </div>
          </div>

          <div className="max-w-xl">
            <label
              htmlFor="company-transfer-owner"
              className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
            >
              اختر المالك الجديد
            </label>
            <select
              id="company-transfer-owner"
              name="newOwnerId"
              autoComplete="off"
              value={selectedNewOwner}
              onChange={(e) => setSelectedNewOwner(e.target.value)}
              className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-red-500 focus:border-red-500 sm:text-sm rounded-md dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            >
              <option value="">اختر مستخدم...</option>
              {users.map((u) => (
                <option key={u.id} value={u.id}>
                  {u.firstName} {u.lastName} ({u.email}) - {u.role}
                </option>
              ))}
            </select>

            <div className="mt-6">
              {!showTransferConfirm ? (
                <button
                  onClick={() => setShowTransferConfirm(true)}
                  disabled={!selectedNewOwner}
                  className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 disabled:bg-gray-300 dark:disabled:bg-gray-600 disabled:cursor-not-allowed"
                >
                  نقل الملكية
                </button>
              ) : (
                <div className="flex items-center space-x-4 space-x-reverse">
                  <button
                    onClick={handleTransferOwnership}
                    disabled={transferring}
                    className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 disabled:opacity-50"
                  >
                    {transferring ? "جاري النقل..." : "تأكيد النقل النهائي"}
                  </button>
                  <button
                    onClick={() => setShowTransferConfirm(false)}
                    disabled={transferring}
                    className="inline-flex justify-center py-2 px-4 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                  >
                    إلغاء
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanySettings;

import React, { useState, useEffect } from "react";
import {
  GlobeAltIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon,
  InformationCircleIcon,
  ArrowTopRightOnSquareIcon,
  ClipboardDocumentCheckIcon,
  ClipboardIcon,
  ArrowsRightLeftIcon,
  ShieldCheckIcon,
} from "@heroicons/react/24/outline";
import { useAuth } from "../../hooks/useAuthSimple";
import { getApiUrl } from "../../config/environment";
import tokenManager from "../../utils/tokenManager";

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const CustomDomainPage: React.FC = () => {
  const { user } = useAuth();
  const [company, setCompany] = useState<any>(null);
  const [customDomain, setCustomDomain] = useState("");
  const [editingDomain, setEditingDomain] = useState(false);
  const [savingDomain, setSavingDomain] = useState(false);
  const [verifyingDNS, setVerifyingDNS] = useState(false);
  const [dnsStatus, setDnsStatus] = useState<{
    success: boolean;
    message: string;
  } | null>(null);
  const [copied, setCopied] = useState<string | null>(null);

  useEffect(() => {
    fetchCompanyData();
  }, []);

  const fetchCompanyData = async () => {
    try {
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}`,
        {
          headers: getAuthHeaders(),
        },
      );
      const data = await response.json();
      if (data.success) {
        setCompany(data.data);
        setCustomDomain(data.data.customDomain || "");
      }
    } catch (error) {
      console.error("Error fetching company:", error);
    }
  };

  const handleCustomDomainSave = async () => {
    const domainRegex =
      /^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/;
    if (customDomain && !domainRegex.test(customDomain)) {
      alert(
        "صيغة الدومين غير صحيحة. يجب أن يكون مثل: example.com أو www.example.com",
      );
      return;
    }

    try {
      setSavingDomain(true);
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}`,
        {
          method: "PUT",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ customDomain: customDomain || null }),
        },
      );

      const data = await response.json();
      if (data.success) {
        setCompany((prev: any) => ({
          ...prev,
          customDomain: customDomain || null,
        }));
        setEditingDomain(false);
        setDnsStatus(null);
        alert("تم تحديث الدومين المخصص بنجاح!");
      } else {
        alert(data.message || data.error || "فشل في تحديث الدومين");
      }
    } catch (error) {
      console.error("Error updating custom domain:", error);
      alert("حدث خطأ أثناء تحديث الدومين");
    } finally {
      setSavingDomain(false);
    }
  };

  const handleVerifyDNS = async () => {
    if (!user?.companyId) return;

    try {
      setVerifyingDNS(true);
      setDnsStatus(null);
      const response = await fetch(
        `${getApiUrl()}/companies/${user?.companyId}/verify-dns`,
        {
          headers: getAuthHeaders(),
        },
      );

      const data = await response.json();
      setDnsStatus({
        success: data.success,
        message: data.message,
      });
    } catch (error) {
      console.error("Error verifying DNS:", error);
      setDnsStatus({
        success: false,
        message: "حدث خطأ أثناء الاتصال بالسيرفر للتحقق من DNS",
      });
    } finally {
      setVerifyingDNS(false);
    }
  };

  const copyToClipboard = (text: string, key: string) => {
    navigator.clipboard.writeText(text);
    setCopied(key);
    setTimeout(() => setCopied(null), 2000);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8" dir="rtl">
      {/* Header Section */}
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-2">
          <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 rounded-lg">
            <GlobeAltIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
          </div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            الدومين المخصص (Custom Domain)
          </h1>
        </div>
        <p className="text-gray-600 dark:text-gray-400">
          اربط متجرك بدومين خاص بك (مثل store.com) لتعزيز علامتك التجارية
          واكتساب ثقة عملائك.
        </p>
      </div>

      <div className="space-y-6">
        {/* Step 1: Explanation & Requirements */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
          <div className="p-6">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
              <span className="flex items-center justify-center w-6 h-6 rounded-full bg-indigo-600 text-white text-xs">
                1
              </span>
              ماذا تحتاج للبدء؟
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="flex items-start gap-3 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg">
                <ShieldCheckIcon className="h-5 w-5 text-green-500 shrink-0" />
                <div>
                  <p className="text-sm font-medium text-gray-900 dark:text-white">
                    دومين مسجل باسمك
                  </p>
                  <p className="text-xs text-gray-500 mt-1">
                    يجب أن تكون اشتريت الدومين من مزود مثل GoDaddy أو Namecheap.
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-3 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg">
                <ArrowsRightLeftIcon className="h-5 w-5 text-blue-500 shrink-0" />
                <div>
                  <p className="text-sm font-medium text-gray-900 dark:text-white">
                    الوصول لإعدادات DNS
                  </p>
                  <p className="text-xs text-gray-500 mt-1">
                    يجب أن تتوفر لديك صلاحية تعديل سجلات DNS الخاصة بالدومين.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Step 2: DNS Configuration */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
          <div className="p-6">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
              <span className="flex items-center justify-center w-6 h-6 rounded-full bg-indigo-600 text-white text-xs">
                2
              </span>
              إعدادات الـ DNS
            </h2>
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-6">
              اذهب إلى لوحة تحكم الدومين الخاص بك وأضف السجل التالي ليتم توجيه
              الزوار إلى متجرك:
            </p>

            <div className="overflow-x-auto border border-gray-100 dark:border-gray-700 rounded-lg">
              <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                <thead className="bg-gray-50 dark:bg-gray-900/50">
                  <tr>
                    <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      النوع (Type)
                    </th>
                    <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      الاسم (Host)
                    </th>
                    <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      القيمة (Value)
                    </th>
                    <th className="px-4 py-3"></th>
                  </tr>
                </thead>
                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                  <tr>
                    <td className="px-4 py-4 whitespace-nowrap text-sm font-bold text-indigo-600 dark:text-indigo-400">
                      CNAME
                    </td>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-white">
                      www أو @
                    </td>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-white">
                      mokhtarelhenawy.online
                    </td>
                    <td className="px-4 py-4 whitespace-nowrap text-left text-sm font-medium">
                      <button
                        type="button"
                        aria-label={
                          copied === "cname"
                            ? "تم نسخ قيمة سجل CNAME"
                            : "نسخ قيمة سجل CNAME"
                        }
                        onClick={() =>
                          copyToClipboard("mokhtarelhenawy.online", "cname")
                        }
                        className="text-gray-400 hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors"
                      >
                        {copied === "cname" ? (
                          <ClipboardDocumentCheckIcon className="h-5 w-5" />
                        ) : (
                          <ClipboardIcon className="h-5 w-5" />
                        )}
                      </button>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

            <div className="mt-4 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-800 rounded-lg flex gap-3">
              <InformationCircleIcon className="h-5 w-5 text-blue-600 dark:text-blue-400 shrink-0 mt-0.5" />
              <p className="text-xs text-blue-700 dark:text-blue-300 leading-relaxed">
                ملاحظة: قد تستغرق تغييرات الـ DNS من 5 دقائق وحتى 24 ساعة لتظهر
                في جميع أنحاء العالم. ننصح باستخدام **Cloudflare** لإدارة الـ
                DNS لسرعة التحديث وأمان أعلى.
              </p>
            </div>
          </div>
        </div>

        {/* Step 3: Domain Addition & Verification */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
          <div className="p-6">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
              <span className="flex items-center justify-center w-6 h-6 rounded-full bg-indigo-600 text-white text-xs">
                3
              </span>
              إضافة الدومين والتحقق
            </h2>

            <div className="space-y-4">
              <div>
                {editingDomain ? (
                  <label
                    htmlFor="custom-domain-input"
                    className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
                  >
                    الدومين المخصص
                  </label>
                ) : (
                  <span className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    الدومين المخصص
                  </span>
                )}
                {editingDomain ? (
                  <div className="flex gap-2">
                    <input
                      id="custom-domain-input"
                      name="customDomain"
                      type="text"
                      autoComplete="url"
                      value={customDomain}
                      onChange={(e) => setCustomDomain(e.target.value)}
                      placeholder="example.com"
                      className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:text-white outline-none"
                    />
                    <button
                      onClick={handleCustomDomainSave}
                      disabled={savingDomain}
                      className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg disabled:opacity-50 transition-colors"
                    >
                      {savingDomain ? "جاري الحفظ..." : "حفظ"}
                    </button>
                    <button
                      onClick={() => {
                        setEditingDomain(false);
                        setCustomDomain(company?.customDomain || "");
                      }}
                      className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                    >
                      إلغاء
                    </button>
                  </div>
                ) : (
                  <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-100 dark:border-gray-700">
                    <div>
                      <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">
                        الدومين الحالي
                      </p>
                      <p className="text-lg font-bold text-gray-900 dark:text-white">
                        {company?.customDomain || "لم يتم ربط دومين بعد"}
                      </p>
                    </div>
                    <button
                      onClick={() => setEditingDomain(true)}
                      className="px-4 py-2 text-indigo-600 dark:text-indigo-400 font-medium hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors"
                    >
                      {company?.customDomain ? "تغيير الدومين" : "إضافة دومين"}
                    </button>
                  </div>
                )}
              </div>

              {company?.customDomain && !editingDomain && (
                <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                  <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                    <button
                      onClick={handleVerifyDNS}
                      disabled={verifyingDNS}
                      className="flex items-center justify-center gap-2 px-6 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-white font-medium rounded-lg hover:bg-gray-50 dark:hover:bg-gray-600 disabled:opacity-50 transition-colors"
                    >
                      {verifyingDNS && (
                        <div className="animate-spin h-4 w-4 border-2 border-indigo-600 border-t-transparent rounded-full" />
                      )}
                      {verifyingDNS
                        ? "جاري الفحص..."
                        : "افحص إعدادات الـ DNS الآن"}
                    </button>

                    {dnsStatus && (
                      <div
                        className={`flex items-center gap-2 text-sm font-medium ${dnsStatus.success ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"}`}
                      >
                        {dnsStatus.success ? (
                          <CheckCircleIcon className="h-5 w-5" />
                        ) : (
                          <ExclamationTriangleIcon className="h-5 w-5" />
                        )}
                        {dnsStatus.message}
                      </div>
                    )}
                  </div>

                  {dnsStatus?.success && (
                    <div className="mt-4 p-4 bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-800 rounded-lg">
                      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                        <div className="flex gap-3">
                          <CheckCircleIcon className="h-5 w-5 text-green-600 dark:text-green-400 shrink-0 mt-0.5" />
                          <div>
                            <p className="text-sm font-bold text-green-800 dark:text-green-300">
                              تم التحقق من الدومين بنجاح!
                            </p>
                            <p className="text-xs text-green-700 dark:text-green-400 mt-1">
                              تم ربط {company?.customDomain} بمتجرك بنجاح. قد
                              يحتاج النظام لبعض الوقت لتفعيل شهادة الـ SSL.
                            </p>
                          </div>
                        </div>
                        <a
                          href={`https://${company?.customDomain}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-2 px-4 py-2 bg-green-600 text-white text-sm font-bold rounded-lg hover:bg-green-700 transition-colors shadow-sm whitespace-nowrap"
                        >
                          <ArrowTopRightOnSquareIcon className="h-4 w-4" />
                          زيارة الموقع الآن
                        </a>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Helpful Tips */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="p-6 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl text-white shadow-lg">
            <h3 className="font-bold flex items-center gap-2 mb-3">
              <InformationCircleIcon className="h-5 w-5" />
              لماذا الدومين المخصص؟
            </h3>
            <ul className="text-xs space-y-2 opacity-90">
              <li>• يزيد من احترافية متجرك أمام العملاء.</li>
              <li>• يسهل على العملاء تذكر رابط متجرك.</li>
              <li>• يحسن من ظهور متجرك في محركات البحث (SEO).</li>
