export default CustomDomainPage;

import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Alert,
  CircularProgress,
  Switch,
  FormControlLabel,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  DeliveryDining as DeliveryIcon,
  Star as StarIcon,
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";

interface DeliveryOption {
  id: string;
  name: string;
  description: string | null;
  deliveryTime: string;
  price: number;
  isDefault: boolean;
  isActive: boolean;
  icon: string | null;
  sortOrder: number;
}

const DeliveryOptions: React.FC = () => {
  const [options, setOptions] = useState<DeliveryOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [openDialog, setOpenDialog] = useState(false);
  const [editingOption, setEditingOption] = useState<DeliveryOption | null>(
    null,
  );
  const [message, setMessage] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  const [formData, setFormData] = useState({
    name: "",
    description: "",
    deliveryTime: "",
    price: 0,
    isDefault: false,
    isActive: true,
    sortOrder: 0,
  });

  useEffect(() => {
    fetchOptions();
  }, []);

  const fetchOptions = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/delivery-options");

      if (response.data.success) {
        setOptions(response.data.data);
      }
    } catch (error: any) {
      console.error("Error fetching delivery options:", error);
      setMessage({
        type: "error",
        text: "فشل في جلب خيارات التوصيل",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (option?: DeliveryOption) => {
    if (option) {
      setEditingOption(option);
      setFormData({
        name: option.name,
        description: option.description || "",
        deliveryTime: option.deliveryTime,
        price: option.price,
        isDefault: option.isDefault,
        isActive: option.isActive,
        sortOrder: option.sortOrder,
      });
    } else {
      setEditingOption(null);
      setFormData({
        name: "",
        description: "",
        deliveryTime: "",
        price: 0,
        isDefault: false,
        isActive: true,
        sortOrder: options.length,
      });
    }
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setEditingOption(null);
  };

  const handleSave = async () => {
    try {
      if (editingOption) {
        // Update
        await apiClient.put(`/delivery-options/${editingOption.id}`, formData);
        setMessage({ type: "success", text: "تم تحديث خيار التوصيل بنجاح" });
      } else {
        // Create
        await apiClient.post("/delivery-options", formData);
        setMessage({ type: "success", text: "تم إضافة خيار التوصيل بنجاح" });
      }

      handleCloseDialog();
      fetchOptions();
    } catch (error: any) {
      console.error("Error saving delivery option:", error);
      setMessage({
        type: "error",
        text: error.response?.data?.message || "فشل في حفظ خيار التوصيل",
      });
    }
  };

  const handleToggle = async (id: string) => {
    try {
      await apiClient.patch(`/delivery-options/${id}/toggle`, {});
      fetchOptions();
    } catch (error: any) {
      console.error("Error toggling delivery option:", error);
      setMessage({
        type: "error",
        text: "فشل في تغيير حالة خيار التوصيل",
      });
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف خيار التوصيل هذا؟")) {
      return;
    }

    try {
      await apiClient.delete(`/delivery-options/${id}`);
      setMessage({ type: "success", text: "تم حذف خيار التوصيل بنجاح" });
      fetchOptions();
    } catch (error: any) {
      console.error("Error deleting delivery option:", error);
      setMessage({
        type: "error",
        text: "فشل في حذف خيار التوصيل",
      });
    }
  };

  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="400px"
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Box>
          <Typography variant="h4" gutterBottom sx={{ fontWeight: "bold" }}>
            🚚 خيارات التوصيل
          </Typography>
          <Typography variant="body2" color="text.secondary">
            قم بإدارة خيارات التوصيل المتاحة للعملاء
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => handleOpenDialog()}
        >
          إضافة خيار جديد
        </Button>
      </Box>

      {message && (
        <Alert
          severity={message.type}
          sx={{ mb: 3 }}
          onClose={() => setMessage(null)}
        >
          {message.text}
        </Alert>
      )}

      <Card>
        <CardContent>
          <TableContainer component={Paper} variant="outlined">
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>الاسم</TableCell>
                  <TableCell>الوصف</TableCell>
                  <TableCell>وقت التوصيل</TableCell>
                  <TableCell>السعر</TableCell>
                  <TableCell>الحالة</TableCell>
                  <TableCell align="center">الإجراءات</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {options.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">
                      <Box py={3}>
                        <DeliveryIcon
                          sx={{ fontSize: 48, color: "text.secondary", mb: 1 }}
                        />
                        <Typography variant="body2" color="text.secondary">
                          لا توجد خيارات توصيل. قم بإضافة خيار جديد
                        </Typography>
                      </Box>
                    </TableCell>
                  </TableRow>
                ) : (
                  options.map((option) => (
                    <TableRow key={option.id}>
                      <TableCell>
                        <Box display="flex" alignItems="center" gap={1}>
                          {option.name}
                          {option.isDefault && (
                            <StarIcon
                              sx={{ fontSize: 16, color: "warning.main" }}
                            />
                          )}
                        </Box>
                      </TableCell>
                      <TableCell>{option.description || "-"}</TableCell>
                      <TableCell>{option.deliveryTime}</TableCell>
                      <TableCell>{option.price} جنيه</TableCell>
                      <TableCell>
                        <Chip
                          label={option.isActive ? "نشط" : "معطل"}
                          color={option.isActive ? "success" : "default"}
                          size="small"
                        />
                      </TableCell>
                      <TableCell align="center">
                        <IconButton
                          size="small"
                          onClick={() => handleOpenDialog(option)}
                          color="primary"
                        >
                          <EditIcon />
                        </IconButton>
                        <IconButton
                          size="small"
                          onClick={() => handleToggle(option.id)}
                          color="info"
                        >
                          <Switch checked={option.isActive} size="small" />
                        </IconButton>
                        <IconButton
                          size="small"
                          onClick={() => handleDelete(option.id)}
                          color="error"
                        >
                          <DeleteIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Add/Edit Dialog */}
      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          {editingOption ? "تعديل خيار التوصيل" : "إضافة خيار توصيل جديد"}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 2 }}>
            <TextField
              label="اسم الخيار"
              fullWidth
              required
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
              placeholder="مثال: توصيل عادي، توصيل سريع، توصيل فوري"
            />

            <TextField
              label="الوصف"
              fullWidth
              multiline
              rows={2}
              value={formData.description}
              onChange={(e) =>
                setFormData({ ...formData, description: e.target.value })
              }
              placeholder="وصف مختصر لخيار التوصيل"
            />

            <TextField
              label="وقت التوصيل"
              fullWidth
              required
              value={formData.deliveryTime}
              onChange={(e) =>
                setFormData({ ...formData, deliveryTime: e.target.value })
              }
              placeholder="مثال: 3-5 أيام، 1-2 يوم، نفس اليوم"
            />

            <TextField
              label="السعر (جنيه)"
              type="number"
              fullWidth
              required
              value={formData.price}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  price: parseFloat(e.target.value) || 0,
                })
              }
              InputProps={{ inputProps: { min: 0, step: 5 } }}
            />

            <TextField
              label="ترتيب العرض"
              type="number"
              fullWidth
              value={formData.sortOrder}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  sortOrder: parseInt(e.target.value) || 0,
                })
              }
              helperText="الترتيب الذي سيظهر به الخيار (الأقل أولاً)"
              InputProps={{ inputProps: { min: 0 } }}
            />

            <FormControlLabel
              control={
                <Switch
                  checked={formData.isDefault}
                  onChange={(e) =>
                    setFormData({ ...formData, isDefault: e.target.checked })
                  }
                />
              }
              label="جعله الخيار الافتراضي"
            />

            <FormControlLabel
              control={
                <Switch
                  checked={formData.isActive}
                  onChange={(e) =>
                    setFormData({ ...formData, isActive: e.target.checked })
                  }
                />
              }
              label="تفعيل الخيار"
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>إلغاء</Button>
          <Button onClick={handleSave} variant="contained">
            {editingOption ? "تحديث" : "إضافة"}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default DeliveryOptions;

import React, { useState, useEffect } from "react";
import {
  CheckCircleIcon,
  ExclamationTriangleIcon,
  LinkIcon,
  TrashIcon,
  PlusIcon,
  ArrowTopRightOnSquareIcon,
  ShieldCheckIcon,
  UserGroupIcon,
} from "@heroicons/react/24/outline";
import { useAuth } from "../../hooks/useAuthSimple";
import { companyAwareApi } from "../../services/companyAwareApi";
import { buildApiUrl } from "../../utils/urlHelper";
import { envConfig } from "../../config/environment";
import tokenManager from "../../utils/tokenManager";

interface FacebookPage {
  id: string;
  pageId: string;
  pageName: string;
  status: string;
  connectedAt: string;
  lastActivity: string;
}

interface OAuthStatus {
  connected: boolean;
  pagesCount: number;
  pages: FacebookPage[];
}

interface SkippedPage {
  pageId: string;
  pageName: string;
  reason: string;
}

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const FacebookOAuth: React.FC = () => {
  const { user, isAuthenticated } = useAuth();
  const [loading, setLoading] = useState(false);
  const [oauthStatus, setOauthStatus] = useState<OAuthStatus | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [skippedPages, setSkippedPages] = useState<SkippedPage[]>([]);

  useEffect(() => {
    if (isAuthenticated && user?.companyId) {
      loadOAuthStatus();
      loadSkippedPages(); // 🆕 جلب الصفحات المتخطاة
    }
  }, [isAuthenticated, user]);

  useEffect(() => {
    // Check for URL parameters (success/error from OAuth callback)
    const urlParams = new URLSearchParams(window.location.search);
    const successParam = urlParams.get("success");
    const errorParam = urlParams.get("error");
    const pagesParam = urlParams.get("pages");
    const skippedParam = urlParams.get("skipped");
    const skippedDataParam = urlParams.get("skippedData");
    const companyParam = urlParams.get("companyId");

    console.log("📋 URL Parameters from OAuth callback:", {
      successParam,
      errorParam,
      pagesParam,
      skippedParam,
      skippedDataParam: skippedDataParam ? "present" : "absent",
      companyParam,
      currentPath: window.location.pathname,
    });

    if (successParam === "true") {
      const pagesCount = pagesParam || "0";
      const skippedCount = skippedParam || "0";

      let successMessage = `تم ربط ${pagesCount} صفحة بنجاح!`;

      // ⚠️ إضافة تحذير مفصل إذا كانت هناك صفحات تم تخطيها
      if (parseInt(skippedCount) > 0) {
        successMessage += ` (تم تخطي ${skippedCount} صفحة)`;

        // فك تشفير تفاصيل الصفحات المتخطاة
        if (skippedDataParam) {
          try {
            const decodedData = atob(decodeURIComponent(skippedDataParam));
            const parsedSkippedPages = JSON.parse(decodedData);

            if (
              parsedSkippedPages &&
              Array.isArray(parsedSkippedPages) &&
              parsedSkippedPages.length > 0
            ) {
              setSkippedPages(parsedSkippedPages);
            }
          } catch (e) {
            console.error("❌ Error parsing skipped pages data:", e);
          }
        }
      }

      setSuccess(successMessage);

      // Clear URL parameters without reload
      const newUrl = window.location.pathname;
      window.history.replaceState({}, document.title, newUrl);

      // Reload status after a short delay to ensure database is updated
      setTimeout(() => {
        loadOAuthStatus();
        loadSkippedPages(); // 🆕 جلب الصفحات المتخطاة
      }, 2000);
    }

    if (errorParam) {
      let errorMessage = `خطأ في الربط: ${decodeURIComponent(errorParam)}`;

      // ترجمة أخطاء معروفة
      const errorTranslations: { [key: string]: string } = {
        missing_code_or_state: "بيانات الربط ناقصة",
        invalid_state: "رابط الربط غير صالح",
        no_company_id: "معرف الشركة مفقود",
        no_pages_found: "لم يتم العثور على صفحات Facebook",
        facebook_oauth_access_denied: "تم رفض الإذن من قبل المستخدم",
      };

      if (errorTranslations[errorParam]) {
        errorMessage = errorTranslations[errorParam];
      }

      setError(errorMessage);
      // Clear URL parameters
      const newUrl = window.location.pathname;
      window.history.replaceState({}, document.title, newUrl);
    }
  }, []);

  const loadOAuthStatus = async () => {
    if (!user?.companyId) {
      console.error("No company ID available");
      setError("معرف الشركة غير متوفر");
      return;
    }

    try {
      setLoading(true);
      setError(null);

      console.log("🔄 Loading OAuth status for company:", user.companyId);

      // استخدام await صريح مع زيادة timeout
      // Make direct API call with companyId in URL since companyAwareApi isn't working
      const response = await fetch(
        `${envConfig.apiUrl}/facebook-oauth/status?companyId=${user.companyId}`,
        {
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
        },
      );

      const data = await response.json();

      console.log("✅ OAuth Status Response:", data);

      if (data.success) {
        setOauthStatus(data);
        console.log(
          `📊 Found ${data.pagesCount} pages, connected: ${data.connected}`,
        );
      } else {
        setError(data.message || "فشل في تحميل حالة الربط");
      }
    } catch (error: any) {
      console.error("❌ Error loading OAuth status:", error);
      console.error("Error details:", error.response?.data || error.message);
      setError(
        "خطأ في تحميل حالة الربط: " +
          (error.response?.data?.message || error.message),
      );
    } finally {
      setLoading(false);
    }
  };

  const loadSkippedPages = async () => {
    if (!user?.companyId) {
      return;
    }

    try {
      console.log("🔄 Loading skipped pages for company:", user.companyId);

      const response = await fetch(
        `${envConfig.apiUrl}/facebook-oauth/skipped-pages?companyId=${user.companyId}`,
        {
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
        },
      );

      const data = await response.json();

      console.log("✅ Skipped Pages Response:", data);

      if (data.success && data.skippedPages) {
        setSkippedPages(data.skippedPages);
        console.log(`📊 Found ${data.count} skipped pages`);
      }
    } catch (error: any) {
      console.error("❌ Error loading skipped pages:", error);
    }
  };

  const resolveSkippedPages = async () => {
    if (!user?.companyId) {
      return;
    }

    try {
      console.log("🔄 Resolving skipped pages for company:", user.companyId);

      const response = await fetch(
        `${envConfig.apiUrl}/facebook-oauth/resolve-skipped?companyId=${user.companyId}`,
        {
          method: "POST",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({}), // Empty body to resolve all
        },
      );

      const data = await response.json();

      console.log("✅ Resolve Response:", data);

      if (data.success) {
        setSkippedPages([]);
        setSuccess(`تم وضع علامة على ${data.resolvedCount} صفحة كمحلولة`);
      }
    } catch (error: any) {
      console.error("❌ Error resolving skipped pages:", error);
      setError("خطأ في وضع علامة على الصفحات المتخطاة");
    }
  };

  const handleConnectFacebook = async () => {
    if (!user?.companyId) {
      setError("معرف الشركة غير متوفر");
      return;
    }

    try {
      setLoading(true);
      setError(null);

      console.log("Connecting Facebook with company ID:", user.companyId);

      // Get authorization URL from backend with companyId in URL directly
      const response = await fetch(
        `${envConfig.apiUrl}/facebook-oauth/authorize?companyId=${user.companyId}&userId=${user.id}&returnOrigin=${encodeURIComponent(window.location.origin)}`,
        {
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
        },
      );

      const data = await response.json();

      console.log("Authorization Response:", data);

      if (data.success) {
        // Redirect to Facebook OAuth
        console.log("Redirecting to:", data.authUrl);
        window.location.href = data.authUrl;
      } else {
        setError(data.message || "فشل في إنشاء رابط الربط");
      }
    } catch (error) {
      console.error("Error initiating OAuth:", error);
      setError("خطأ في بدء عملية الربط");
    } finally {
      setLoading(false);
    }
  };

  const handleDisconnectPage = async (pageId: string) => {
    if (!confirm("هل أنت متأكد من قطع الاتصال مع هذه الصفحة؟")) {
      return;
    }

    if (!user?.companyId) {
      setError("معرف الشركة غير متوفر");
      return;
    }

    try {
      setLoading(true);

      const response = await fetch(
        `${envConfig.apiUrl}/facebook-oauth/disconnect?companyId=${user.companyId}`,
        {
          method: "DELETE",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({
            pageIds: [pageId], // Array في الـ body
          }),
        },
      );

      const data = await response.json();

      if (data.success) {
        setSuccess("تم قطع الاتصال بنجاح");
        loadOAuthStatus();
      } else {
        setError(data.message || "فشل في قطع الاتصال");
      }
    } catch (error) {
      console.error("Error disconnecting page:", error);
      setError("خطأ في قطع الاتصال");
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const handleDebug = async () => {
    if (!user?.companyId) return;

    try {
      // Make direct API call with companyId in URL
      const response = await fetch(
        `${envConfig.apiUrl}/facebook-oauth/debug?companyId=${user.companyId}`,
        {
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
        },
      );

      const data = await response.json();
      console.log("🐛 Debug Response:", data);

      // عرض معلومات مفصلة
      alert(`معلومات التصحيح:
الشركة: ${data.companyId}
إجمالي الصفحات: ${data.totalPages}
الصفحات المتصلة: ${data.connectedPages}
الصفحات المقطوعة: ${data.disconnectedPages}

تفاصيل الصفحات:
${data.pages
  .map((page: any) => `- ${page.pageName} (${page.pageId}): ${page.status}`)
  .join("\n")}`);
    } catch (error) {
      console.error("Debug error:", error);
    }
  };

  if (!isAuthenticated) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <ExclamationTriangleIcon className="h-12 w-12 text-yellow-500 mx-auto mb-4" />
          <p className="text-gray-600">يجب تسجيل الدخول أولاً</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full p-6">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
          ربط Facebook
        </h1>
        <p className="text-gray-600 dark:text-gray-300">
          ربط صفحات Facebook الخاصة بك بسهولة وأمان
        </p>
      </div>

      {/* Debug Info (remove in production) */}
      {import.meta.env.DEV && (
        <div className="mb-4 p-3 bg-gray-100 dark:bg-gray-800 rounded text-sm dark:text-gray-300">
          <p>Company ID: {user?.companyId || "غير متوفر"}</p>
          <p>User ID: {user?.id || "غير متوفر"}</p>
          <button
            onClick={handleDebug}
            className="mt-2 px-3 py-1 bg-blue-500 text-white rounded-md hover:bg-blue-700 text-sm"
          >
            Debug Info
          </button>
        </div>
      )}

      {/* Success/Error Messages */}
      {success && (
        <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg">
          <div className="flex items-center">
            <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2" />
            <p className="text-green-800 whitespace-pre-line">{success}</p>
            <button
              onClick={() => {
                setSuccess(null);
                setSkippedPages([]);
              }}
              className="ml-auto text-green-600 hover:text-green-800"
            >
              ×
            </button>
          </div>
        </div>
      )}

      {/* Skipped Pages Warning */}
      {skippedPages.length > 0 && (
        <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
          <div className="flex items-start">
            <ExclamationTriangleIcon className="h-6 w-6 text-yellow-500 mr-3 mt-0.5 flex-shrink-0" />
            <div className="flex-1">
              <h3 className="text-lg font-semibold text-yellow-900 mb-2">
                صفحات لم يتم ربطها ({skippedPages.length})
              </h3>
              <p className="text-sm text-yellow-800 mb-3">
                الصفحات التالية مربوطة بالفعل بشركة أخرى ولا يمكن ربطها:
              </p>
              <div className="space-y-2">
                {skippedPages.map((page) => (
                  <div
                    key={page.pageId}
                    className="flex items-center p-3 bg-white rounded-md border border-yellow-300"
                  >
                    <div className="w-8 h-8 bg-yellow-100 rounded-lg flex items-center justify-center mr-3">
                      <span className="text-yellow-600 text-sm">📘</span>
                    </div>
                    <div className="flex-1">
                      <h4 className="font-medium text-gray-900">
                        {page.pageName}
                      </h4>
                      <p className="text-xs text-gray-500">
                        Page ID: {page.pageId}
                      </p>
                    </div>
                    <span className="px-3 py-1 bg-yellow-100 text-yellow-800 text-xs rounded-full">
                      مربوطة بحساب آخر
                    </span>
                  </div>
                ))}
              </div>
              <div className="mt-4 p-3 bg-yellow-100 rounded-md">
                <p className="text-sm text-yellow-900 mb-3">
                  <strong>💡 ملاحظة:</strong> لربط هذه الصفحات، يجب أولاً فك
                  ربطها من الشركة الأخرى التي تستخدمها حالياً.
                </p>
                <button
                  onClick={resolveSkippedPages}
                  className="px-4 py-2 bg-yellow-600 text-white rounded-md hover:bg-yellow-700 text-sm"
                >
                  ✓ تم الاطلاع - إخفاء هذا التنبيه
                </button>
              </div>
            </div>
            <button
              onClick={resolveSkippedPages}
              className="ml-2 text-yellow-600 hover:text-yellow-800 text-xl"
            >
              ×
            </button>
          </div>
        </div>
      )}

      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg">
          <div className="flex items-center">
            <ExclamationTriangleIcon className="h-5 w-5 text-red-500 mr-2" />
            <p className="text-red-800">{error}</p>
            <button
              onClick={() => setError(null)}
              className="ml-auto text-red-600 hover:text-red-800"
            >
              ×
            </button>
          </div>
        </div>
      )}

      {/* OAuth Connection Card */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6 mb-6">
        <div className="flex items-center mb-4">
          <div className="w-12 h-12 bg-blue-600 rounded-lg flex items-center justify-center mr-4">
            <span className="text-white text-xl">📘</span>
          </div>
          <div>
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
              Facebook OAuth
            </h2>
            <p className="text-gray-600 dark:text-gray-300">
              ربط آمن وسهل مع Facebook
            </p>
          </div>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-4">
            <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600"></div>
            <span className="ml-2">جاري التحميل...</span>
          </div>
        ) : oauthStatus?.connected ? (
          <div className="space-y-4">
            <div className="flex items-center text-green-600">
              <CheckCircleIcon className="h-5 w-5 mr-2" />
              <span className="font-medium">
                متصل - {oauthStatus.pagesCount} صفحة
              </span>
            </div>

            <button
              onClick={handleConnectFacebook}
              disabled={loading}
              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed flex items-center"
            >
              <PlusIcon className="h-4 w-4 mr-2" />
              {loading ? "جاري التحميل..." : "إضافة صفحات أخرى"}
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center text-gray-500">
              <ExclamationTriangleIcon className="h-5 w-5 mr-2" />
              <span>غير متصل</span>
            </div>

            <button
              onClick={handleConnectFacebook}
              disabled={loading || !user?.companyId}
              className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed flex items-center text-lg"
            >
              <ArrowTopRightOnSquareIcon className="h-5 w-5 mr-2" />
              {loading ? "جاري التحميل..." : "رابط مع Facebook"}
            </button>

            {!user?.companyId && (
              <p className="text-sm text-red-600">معرف الشركة غير متوفر</p>
            )}
          </div>
        )}
      </div>

      {/* Connected Pages */}
      {oauthStatus?.connected && oauthStatus.pages.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
            <UserGroupIcon className="h-5 w-5 mr-2" />
            الصفحات المتصلة ({oauthStatus.pages.length})
          </h3>

          <div className="space-y-3">
            {oauthStatus.pages.map((page) => (
              <div
                key={page.id}
                className="flex items-center justify-between p-4 border border-gray-200 dark:border-gray-700 rounded-lg"
              >
                <div className="flex items-center">
                  <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center mr-3">
                    <span className="text-blue-600 text-sm">📘</span>
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-900 dark:text-white">
                      {page.pageName}
                    </h4>
                    <p className="text-sm text-gray-500 dark:text-gray-400">
                      Page ID: {page.pageId}
                    </p>
                    <p className="text-sm text-gray-500">
                      متصل منذ: {formatDate(page.connectedAt)}
                    </p>
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <span className="px-2 py-1 bg-green-100 text-green-800 text-xs rounded-full">
                    متصل
                  </span>
                  <button
                    onClick={() => handleDisconnectPage(page.id)}
                    disabled={loading}
                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg disabled:opacity-50"
                    title="قطع الاتصال"
                  >
                    <TrashIcon className="h-4 w-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Benefits Card */}
      <div className="bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-gray-800 dark:to-gray-700 rounded-lg p-6 mt-6">
        <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
          <ShieldCheckIcon className="h-5 w-5 mr-2" />
          مميزات الربط الآمن
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex items-start">
            <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2 mt-0.5" />
            <div>
              <h4 className="font-medium text-gray-900 dark:text-white">
                آمان عالي
              </h4>
              <p className="text-sm text-gray-600 dark:text-gray-300">
                لا نحفظ كلمات مرور أو بيانات حساسة
              </p>
            </div>
          </div>

          <div className="flex items-start">
            <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2 mt-0.5" />
            <div>
              <h4 className="font-medium text-gray-900 dark:text-white">
                سهولة الاستخدام
              </h4>
              <p className="text-sm text-gray-600 dark:text-gray-300">
                ربط بنقرة واحدة بدون إدخال بيانات يدوياً
              </p>
            </div>
          </div>

          <div className="flex items-start">
            <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2 mt-0.5" />
            <div>
              <h4 className="font-medium text-gray-900 dark:text-white">
                إدارة متقدمة
              </h4>
              <p className="text-sm text-gray-600 dark:text-gray-300">
                إضافة أو إزالة صفحات بسهولة
              </p>
            </div>
          </div>

          <div className="flex items-start">
            <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2 mt-0.5" />
            <div>
              <h4 className="font-medium text-gray-900 dark:text-white">
                صلاحيات محدودة
              </h4>
              <p className="text-sm text-gray-600 dark:text-gray-300">
                نطلب فقط الصلاحيات الضرورية
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FacebookOAuth;

import React, { useState, useEffect } from "react";
import {
  CheckCircleIcon,
  ExclamationTriangleIcon,
  LinkIcon,
  TrashIcon,
  PlusIcon,
  QuestionMarkCircleIcon,
  WrenchScrewdriverIcon,
  NoSymbolIcon,
  UserIcon,
} from "@heroicons/react/24/outline";

import { useDateFormat } from "../../hooks/useDateFormat";
import { useAuth } from "../../hooks/useAuthSimple";
import { companyAwareApi } from "../../services/companyAwareApi";
import { apiService } from "../../services/apiService";
import { tokenManager } from "../../utils/tokenManager";
import FacebookSetupGuide from "../../components/guides/FacebookSetupGuide";
import FacebookDiagnostics from "../../components/FacebookDiagnostics";

interface FacebookPage {
  id: string;
  pageId: string;
  pageName: string;
  pageAccessToken: string;
  status: string;
  connectedAt: string;
  lastActivity: string;
  messageCount: number;
}

interface FacebookConfig {
  appId: string;
  webhookUrl: string;
  verifyToken: string;
  requiredPermissions: string[];
  webhookFields: string[];
}

interface SkippedPage {
  pageId: string;
  pageName: string;
  reason: string;
}

const FacebookSettings: React.FC = () => {
  const { formatDate } = useDateFormat();
  const { user, isAuthenticated, isLoading: authLoading } = useAuth();
  const [loading, setLoading] = useState(true);
  const [pages, setPages] = useState<FacebookPage[]>([]);
  const [isConnecting, setIsConnecting] = useState(false);
  const [showConnectModal, setShowConnectModal] = useState(false);
  const [showSetupGuide, setShowSetupGuide] = useState(false);
  const [showDiagnostics, setShowDiagnostics] = useState(false);
  const [newPageData, setNewPageData] = useState({
    pageAccessToken: "",
  });
  const [pageInfo, setPageInfo] = useState<any>(null);
  const [isValidating, setIsValidating] = useState(false);
  const [skippedPages, setSkippedPages] = useState<SkippedPage[]>([]);
  const [success, setSuccess] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selectedPageForBlocked, setSelectedPageForBlocked] = useState<
    string | null
  >(null);
  const [blockedCustomers, setBlockedCustomers] = useState<any[]>([]);
  const [loadingBlocked, setLoadingBlocked] = useState(false);
  const [authError, setAuthError] = useState(false);
  const [retryCount, setRetryCount] = useState(0);
  const MAX_RETRIES = 3;

  useEffect(() => {
    // انتظار انتهاء تحميل Authentication
    if (authLoading) {
      console.log("⏳ [FacebookSettings] Waiting for auth to load...");
      return;
    }

    // ✅ FIX: Check authentication before loading data
    if (!isAuthenticated) {
      console.error(
        "❌ [FacebookSettings] User not authenticated, stopping auto-refresh",
      );
      setAuthError(true);
      setLoading(false);
      return;
    }

    console.log("🚀 [FacebookSettings] Auth loaded, loading initial data...", {
      isAuthenticated,
      user: user?.email,
    });
    setAuthError(false);
    loadFacebookData();
    loadSkippedPages();

    // ✅ FIX: Only set up auto-refresh if authenticated
    const interval = setInterval(() => {
      if (isAuthenticated && retryCount < MAX_RETRIES) {
        console.log("🔄 [FacebookSettings] Auto-refreshing data...");
        loadFacebookData();
      } else {
        console.log(
          "🛑 [FacebookSettings] Stopping auto-refresh (not authenticated or max retries reached)",
        );
      }
    }, 30000);

    return () => {
      console.log(
        "🛑 [FacebookSettings] Component unmounted, clearing interval",
      );
      clearInterval(interval);
    };
  }, [authLoading, isAuthenticated, retryCount]);

  const loadFacebookData = async () => {
    try {
      console.log("🔄 [FacebookSettings] Starting to load Facebook data...");
      console.log("🔍 [FacebookSettings] Auth state:", {
        authLoading,
        isAuthenticated,
        user: user?.email,
        hasToken: !!tokenManager.getAccessToken(),
        retryCount,
      });
      console.log("🔍 [FacebookSettings] User object:", user);
      setLoading(true);

      // ✅ FIX: Check authentication and retry limit
      if (!isAuthenticated) {
        console.error("❌ [FacebookSettings] User not authenticated");
        setAuthError(true);
        setLoading(false);
        return; // Stop execution instead of throwing
      }

      // ✅ FIX: Check retry limit
      if (retryCount >= MAX_RETRIES) {
        console.error("❌ [FacebookSettings] Max retries reached, stopping");
        setError("تم تجاوز الحد الأقصى لمحاولات الاتصال. يرجى تحديث الصفحة.");
        setLoading(false);
        return;
      }

      // Load connected pages
      console.log("📡 [FacebookSettings] Fetching connected pages...");
      console.log(
        "📡 [FacebookSettings] Making request to:",
        "/integrations/facebook/connected",
      );
      console.log("📡 [FacebookSettings] With headers:", {
        Authorization: `${tokenManager.getAuthorizationHeaderValue()?.substring(0, 27) || "missing"}...`,
        "Content-Type": "application/json",
      });
      const pagesResponse = await companyAwareApi.get(
        "/integrations/facebook/connected",
      );
      console.log(
        "📊 [FacebookSettings] Pages response status:",
        pagesResponse.status,
      );
      console.log(
        "📊 [FacebookSettings] Pages response headers:",
        pagesResponse.headers,
      );

      const pagesData = pagesResponse.data;
      console.log("📊 [FacebookSettings] Pages response data:", pagesData);
      console.log("📊 [FacebookSettings] Pages response data structure:", {
        success: pagesData.success,
        pages: pagesData.pages,
        pagesLength: pagesData.pages?.length,
        companyId: pagesData.companyId,
      });

      if (pagesData.success) {
        setPages(pagesData.pages || []);
        console.log(
          "✅ [FacebookSettings] Pages loaded successfully:",
          pagesData.pages?.length || 0,
          "pages",
        );
      } else {
        console.error(
          "❌ [FacebookSettings] Pages API returned error:",
          pagesData.error,
        );
      }
    } catch (error: any) {
      console.error(
        "❌ [FacebookSettings] Error loading Facebook data:",
        error,
      );

      // ✅ FIX: Increment retry count and handle auth errors
      setRetryCount((prev) => prev + 1);

      // Check if it's an authentication error (401)
      if (
        error.response?.status === 401 ||
        error.message?.includes("authentication") ||
        error.message?.includes("token")
      ) {
        console.error("❌ [FacebookSettings] Authentication error detected");
        setAuthError(true);
        setError("انتهت جلسة المصادقة. يرجى تسجيل الدخول مرة أخرى.");
      } else {
        setError(`خطأ في تحميل بيانات Facebook: ${error.message}`);
      }
    } finally {
      setLoading(false);
      console.log("🏁 [FacebookSettings] Finished loading Facebook data");
    }
  };

  const loadSkippedPages = async () => {
    if (!user?.companyId) {
      return;
    }

    try {
      console.log(
        "🔄 [FacebookSettings] Loading skipped pages for company:",
        user.companyId,
      );

      const response = await companyAwareApi.get(
        "/facebook-oauth/skipped-pages",
      );

      console.log(
        "✅ [FacebookSettings] Skipped Pages Response:",
        response.data,
      );

      if (response.data.success && response.data.skippedPages) {
        setSkippedPages(response.data.skippedPages);
        console.log(
          `📊 [FacebookSettings] Found ${response.data.count} skipped pages`,
        );
      }
    } catch (error: any) {
      console.error(
        "❌ [FacebookSettings] Error loading skipped pages:",
        error,
      );
    }
  };

  const resolveSkippedPages = async () => {
    if (!user?.companyId) {
      return;
    }

    try {
      console.log(
        "🔄 [FacebookSettings] Resolving skipped pages for company:",
        user.companyId,
      );

      const response = await companyAwareApi.post(
        "/facebook-oauth/resolve-skipped",
        {},
      );

      console.log("✅ [FacebookSettings] Resolve Response:", response.data);

      if (response.data.success) {
        setSkippedPages([]);
        setSuccess(
          `تم وضع علامة على ${response.data.resolvedCount} صفحة كمحلولة`,
        );
        setTimeout(() => setSuccess(null), 5000);
      }
    } catch (error: any) {
      console.error(
        "❌ [FacebookSettings] Error resolving skipped pages:",
        error,
      );
      setError("خطأ في وضع علامة على الصفحات المتخطاة");
      setTimeout(() => setError(null), 5000);
    }
  };

  const validateAccessToken = async (accessToken: string) => {
    if (!accessToken.trim()) {
      console.log(
        "🔍 [FacebookSettings] Empty access token, clearing page info",
      );
      setPageInfo(null);
      return;
    }

    try {
      console.log("🔍 [FacebookSettings] Starting access token validation...");
      console.log("🔑 [FacebookSettings] Token length:", accessToken.length);
      console.log(
        "🔑 [FacebookSettings] Token preview:",
        accessToken.substring(0, 20) + "...",
      );
      setIsValidating(true);

      const requestBody = {
        pageAccessToken: accessToken,
      };
      console.log(
        "📤 [FacebookSettings] Sending validation request:",
        requestBody,
      );

      const response = await companyAwareApi.post(
        "/integrations/facebook/test",
        requestBody,
      );

      console.log(
        "📥 [FacebookSettings] Validation response status:",
        response.status,
      );

      const data = response.data;
      console.log("📥 [FacebookSettings] Validation response data:", data);

      if (data.success && data.data) {
        setPageInfo(data.data);
        console.log(
          "✅ [FacebookSettings] Token validation successful, page info:",
          data.data,
        );
        alert(`✅ تم التحقق من الصفحة بنجاح: ${data.data.name}`);
      } else {
        setPageInfo(null);
        console.error("❌ [FacebookSettings] Token validation failed:", data);
        if (accessToken.trim()) {
          alert(
            `❌ فشل التحقق من Access Token: ${data.error || "غير صحيح أو منتهي الصلاحية"}`,
          );
        }
      }
    } catch (error: any) {
      console.error("❌ [FacebookSettings] Error validating token:", error);
      setPageInfo(null);
      if (accessToken.trim()) {
        alert(`❌ حدث خطأ أثناء التحقق من Access Token: ${error.message}`);
      }
    } finally {
      setIsValidating(false);
      console.log("🏁 [FacebookSettings] Token validation completed");
    }
  };

  const handleConnectPage = async () => {
    if (!newPageData.pageAccessToken || !pageInfo) {
      console.error(
        "❌ [FacebookSettings] Missing required data for connection",
      );
      alert("يرجى إدخال Access Token صحيح والتأكد من صحة بيانات الصفحة");
      return;
    }

    try {
      console.log("🔗 [FacebookSettings] Starting page connection...");
      console.log("📄 [FacebookSettings] Page info:", pageInfo);
      setIsConnecting(true);

      const requestBody = {
        pageId: pageInfo.id,
        pageAccessToken: newPageData.pageAccessToken,
        pageName: pageInfo.name,
      };
      console.log("📤 [FacebookSettings] Sending connection request:", {
        ...requestBody,
        pageAccessToken: requestBody.pageAccessToken.substring(0, 20) + "...",
      });

      const response = await companyAwareApi.post(
        "/integrations/facebook/connect",
        requestBody,
      );

      console.log(
        "📥 [FacebookSettings] Connection response status:",
        response.status,
      );

      const data = response.data;
      console.log("📥 [FacebookSettings] Connection response data:", data);

      if (data.success) {
        console.log("✅ [FacebookSettings] Page connected successfully");
        alert(`✅ تم ربط الصفحة بنجاح!

اسم الصفحة: ${pageInfo.name}
معرف الصفحة: ${pageInfo.id}
الحالة: متصل

سيتم تحديث قائمة الصفحات الآن...`);
        setShowConnectModal(false);
        setNewPageData({ pageAccessToken: "" });
        setPageInfo(null);
        // تحديث البيانات بعد ثانية واحدة للتأكد من حفظ البيانات
        setTimeout(() => {
          loadFacebookData();
          loadSkippedPages();
        }, 1000);
      } else {
        console.error("❌ [FacebookSettings] Page connection failed:", data);
        alert(`❌ فشل في ربط الصفحة: ${data.message || data.error}`);
      }
    } catch (error: any) {
      console.error("❌ [FacebookSettings] Error connecting page:", error);
      alert(`❌ حدث خطأ أثناء ربط الصفحة: ${error.message}`);
    } finally {
      setIsConnecting(false);
      console.log("🏁 [FacebookSettings] Page connection process completed");
    }
  };

  const handleDisconnectPage = async (pageId: string) => {
    console.log("🗑️ [FacebookSettings] Attempting to disconnect page:", pageId);

    if (!confirm("هل أنت متأكد من إلغاء ربط هذه الصفحة؟")) {
      console.log("🚫 [FacebookSettings] User cancelled page disconnection");
      return;
    }

    try {
      console.log(
        "📤 [FacebookSettings] Sending disconnect request for page:",
        pageId,
      );

      const response = await companyAwareApi.delete(
        `/integrations/facebook/${pageId}`,
      );

      console.log(
        "📥 [FacebookSettings] Disconnect response status:",
        response.status,
      );

      const data = response.data;
      console.log("📥 [FacebookSettings] Disconnect response data:", data);

      if (data.success) {
        console.log("✅ [FacebookSettings] Page disconnected successfully");
        alert(`✅ تم إلغاء ربط الصفحة بنجاح!

معرف الصفحة: ${pageId}
الحالة: غير متصل
تاريخ الإلغاء: ${new Date().toLocaleString("ar-SA")}

سيتم تحديث قائمة الصفحات الآن...`);
        // تحديث البيانات بعد ثانية واحدة للتأكد من حذف البيانات
        setTimeout(() => {
          loadFacebookData();
          loadSkippedPages();
        }, 1000);
      } else {
        console.error("❌ [FacebookSettings] Page disconnection failed:", data);
        alert(`❌ فشل في إلغاء ربط الصفحة: ${data.message || data.error}`);
      }
    } catch (error: any) {
      console.error("❌ [FacebookSettings] Error disconnecting page:", error);
      alert(`❌ حدث خطأ أثناء إلغاء ربط الصفحة: ${error.message}`);
    }
  };

  const testPageConnection = async (pageId: string) => {
    console.log("🧪 [FacebookSettings] Testing page connection:", pageId);

    try {
      const response = await companyAwareApi.get(
        `/integrations/facebook/page/${pageId}`,
      );

      const data = response.data;
      console.log("✅ [FacebookSettings] Page test result:", data);

      if (data.success) {
        alert(
          `✅ اختبار الصفحة نجح!\nاسم الصفحة: ${data.data.pageName}\nالحالة: ${data.data.status}`,
        );
      } else {
        alert(`❌ فشل اختبار الصفحة: ${data.error}`);
      }
    } catch (error: any) {
      console.error("❌ [FacebookSettings] Error testing page:", error);
      alert(`❌ خطأ في اختبار الصفحة: ${error.message}`);
    }
  };

  // 🚫 جلب العملاء المحظورين على صفحة معينة
  const loadBlockedCustomers = async (pageId: string) => {
    try {
      setLoadingBlocked(true);
      const blocked = await apiService.getBlockedCustomersOnPage(pageId);
      setBlockedCustomers(blocked);
    } catch (error: any) {
      console.error("Error loading blocked customers:", error);
      setError("فشل جلب العملاء المحظورين");
    } finally {
      setLoadingBlocked(false);
    }
  };

  // ✅ إلغاء حظر عميل
  const handleUnblockCustomer = async (customerId: string, pageId: string) => {
    if (!confirm("هل أنت متأكد من إلغاء حظر هذا العميل؟")) {
      return;
    }

    try {
      await apiService.unblockCustomerOnPage(customerId, pageId);
      setSuccess("تم إلغاء حظر العميل بنجاح");
      // تحديث القائمة
      loadBlockedCustomers(pageId);
    } catch (error: any) {
      setError(error.message || "فشل إلغاء حظر العميل");
    }
  };

  // ✅ FIX: Show authentication error with redirect to login
  if (authError || (!authLoading && !isAuthenticated)) {
    return (
      <div className="flex flex-col justify-center items-center h-64 space-y-4">
        <ExclamationTriangleIcon className="h-16 w-16 text-red-500" />
        <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
          يجب تسجيل الدخول
        </h2>
        <p className="text-gray-600 dark:text-gray-300 text-center max-w-md">
          للوصول إلى إعدادات Facebook، يرجى تسجيل الدخول إلى حسابك أولاً.
        </p>
        <button
          onClick={() => (window.location.href = "/auth/login")}
          className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 flex items-center"
        >
          <svg
            className="h-5 w-5 ml-2"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1"
            />
          </svg>
          تسجيل الدخول
        </button>
      </div>
    );
  }

  // عرض Loading أثناء انتظار Authentication
  if (authLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
        <div className="mr-4 text-gray-600">جاري التحقق من المصادقة...</div>
      </div>
    );
  }

  // عرض Loading أثناء تحميل البيانات
  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
        <div className="mr-4 text-gray-600">جاري تحميل إعدادات Facebook...</div>
      </div>
    );
  }

  return (
    <div className="w-full p-6 space-y-6">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center">
              <svg
                className="h-8 w-8 text-blue-600 ml-3"
                fill="currentColor"
                viewBox="0 0 24 24"
              >
                <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
              </svg>
              إعدادات Facebook Messenger
            </h1>
            <p className="text-gray-600 dark:text-gray-300 mt-1">
              إدارة ربط صفحات Facebook وإعدادات Messenger
            </p>
          </div>
          <div className="flex space-x-2">
            <button
              onClick={loadFacebookData}
              disabled={loading}
              className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center disabled:opacity-50"
            >
              <svg
                className="h-5 w-5 ml-2"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                />
              </svg>
              {loading ? "جاري التحديث..." : "تحديث البيانات"}
            </button>
            <button
              onClick={() => setShowDiagnostics(true)}
              className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 flex items-center"
            >
              <WrenchScrewdriverIcon className="h-5 w-5 ml-2" />
              تشخيص المشاكل
            </button>
            <button
              onClick={() => setShowSetupGuide(true)}
              className="bg-gray-600 text-white px-4 py-2 rounded-lg hover:bg-gray-700 flex items-center"
            >
              <QuestionMarkCircleIcon className="h-5 w-5 ml-2" />
              دليل الإعداد
            </button>
            <button
              onClick={() => setShowConnectModal(true)}
              className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center"
            >
              <PlusIcon className="h-5 w-5 ml-2" />
              ربط صفحة جديدة
            </button>
          </div>
        </div>
      </div>

      {/* Success/Error Messages */}
      {success && (
        <div className="bg-green-50 border border-green-200 rounded-lg p-4">
          <div className="flex items-center">
            <CheckCircleIcon className="h-5 w-5 text-green-500 ml-2" />
            <p className="text-green-800 whitespace-pre-line">{success}</p>
            <button
              onClick={() => setSuccess(null)}
              className="mr-auto text-green-600 hover:text-green-800"
            >
              ×
            </button>
          </div>
        </div>
      )}

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <div className="flex items-center">
            <ExclamationTriangleIcon className="h-5 w-5 text-red-500 ml-2" />
            <p className="text-red-800">{error}</p>
            <button
              onClick={() => setError(null)}
              className="mr-auto text-red-600 hover:text-red-800"
            >
              ×
            </button>
          </div>
        </div>
      )}

      {/* Skipped Pages Warning */}
      {skippedPages.length > 0 && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <div className="flex items-start">
            <ExclamationTriangleIcon className="h-6 w-6 text-yellow-500 ml-3 mt-0.5 flex-shrink-0" />
            <div className="flex-1">
              <h3 className="text-lg font-semibold text-yellow-900 mb-2">
                صفحات لم يتم ربطها ({skippedPages.length})
              </h3>
              <p className="text-sm text-yellow-800 mb-3">
                الصفحات التالية مربوطة بالفعل بشركة أخرى ولا يمكن ربطها:
              </p>
              <div className="space-y-2">
                {skippedPages.map((page) => (
                  <div
                    key={page.pageId}
                    className="flex items-center p-3 bg-white rounded-md border border-yellow-300"
                  >
                    <div className="w-8 h-8 bg-yellow-100 rounded-lg flex items-center justify-center ml-3">
                      <span className="text-yellow-600 text-sm">📘</span>
                    </div>
                    <div className="flex-1">
                      <h4 className="font-medium text-gray-900">
                        {page.pageName}
                      </h4>
                      <p className="text-xs text-gray-500">
                        Page ID: {page.pageId}
                      </p>
                    </div>
                    <span className="px-3 py-1 bg-yellow-100 text-yellow-800 text-xs rounded-full">
                      مربوطة بحساب آخر
                    </span>
                  </div>
                ))}
              </div>
              <div className="mt-4 p-3 bg-yellow-100 rounded-md">
                <p className="text-sm text-yellow-900 mb-3">
                  <strong>💡 ملاحظة:</strong> لربط هذه الصفحات، يجب أولاً فك
                  ربطها من الشركة الأخرى التي تستخدمها حالياً.
                </p>
                <button
                  onClick={resolveSkippedPages}
                  className="px-4 py-2 bg-yellow-600 text-white rounded-md hover:bg-yellow-700 text-sm"
                >
                  ✓ تم الاطلاع - إخفاء هذا التنبيه
                </button>
              </div>
            </div>
            <button
              onClick={resolveSkippedPages}
              className="mr-2 text-yellow-600 hover:text-yellow-800 text-xl"
            >
              ×
            </button>
          </div>
        </div>
      )}

      {/* Connected Pages */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow">
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                الصفحات المربوطة
              </h2>
              <p className="text-sm text-gray-600 dark:text-gray-300">
                إدارة صفحات Facebook المربوطة بحسابك ({pages?.length || 0} صفحة)
              </p>
            </div>
            <div className="text-sm text-gray-500 flex items-center">
              <svg
                className="h-4 w-4 ml-1 text-green-500"
                fill="currentColor"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                  clipRule="evenodd"
                />
              </svg>
              آخر تحديث: {new Date().toLocaleTimeString("ar-SA")}
              <span className="text-xs text-gray-400 mr-2">
                (تحديث تلقائي كل 30 ثانية)
              </span>
            </div>
          </div>
        </div>

        <div className="p-6">
          {!pages || pages.length === 0 ? (
            <div className="text-center py-12">
              <LinkIcon className="mx-auto h-12 w-12 text-gray-400" />
              <h3 className="mt-2 text-sm font-medium text-gray-900 dark:text-white">
                لا توجد صفحات مربوطة
              </h3>
              <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                ابدأ بربط صفحة Facebook لاستقبال الرسائل
              </p>
              <div className="mt-6">
                <button
                  onClick={() => setShowConnectModal(true)}
                  className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
                >
                  ربط صفحة Facebook
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              {pages &&
                pages.map((page) => (
                  <div
                    key={page.id}
                    className="border border-gray-200 dark:border-gray-700 rounded-lg p-4"
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center">
                        <div className="flex-shrink-0">
                          {page.status === "connected" ? (
                            <CheckCircleIcon className="h-8 w-8 text-green-500" />
                          ) : (
                            <ExclamationTriangleIcon className="h-8 w-8 text-yellow-500" />
                          )}
                        </div>
                        <div className="mr-4">
                          <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                            {page.pageName}
                          </h3>
                          <p className="text-sm text-gray-500 dark:text-gray-400">
                            الحالة:{" "}
                            {page.status === "connected" ? "نشط" : "غير نشط"}
                          </p>
                          <p className="text-xs text-gray-400">
                            معرف الصفحة: {page.pageId}
                          </p>
                          {page.connectedAt && (
                            <p className="text-xs text-gray-400">
                              تم الربط: {formatDate(page.connectedAt)}
                            </p>
                          )}
                          {page.lastActivity && (
                            <p className="text-xs text-gray-400">
                              آخر نشاط: {formatDate(page.lastActivity)}
                            </p>
                          )}
                          {page.messageCount !== undefined && (
                            <p className="text-xs text-gray-400">
                              عدد الرسائل: {page.messageCount}
                            </p>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center space-x-2">
                        <span
                          className={`px-2 py-1 text-xs font-medium rounded-full ${
                            page.status === "connected"
                              ? "bg-green-100 text-green-800"
                              : "bg-yellow-100 text-yellow-800"
                          }`}
                        >
                          {page.status === "connected" ? "متصل" : "غير متصل"}
                        </span>
                        {page.status === "connected" && (
                          <button
                            onClick={() => testPageConnection(page.pageId)}
                            className="text-blue-600 hover:text-blue-800 p-1"
                            title="اختبار الاتصال"
                          >
                            <svg
                              className="h-5 w-5"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                              />
                            </svg>
                          </button>
                        )}
                        <button
                          onClick={() => handleDisconnectPage(page.pageId)}
                          className="text-red-600 hover:text-red-800 p-1"
                          title="إلغاء الربط"
                        >
                          <TrashIcon className="h-5 w-5" />
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
            </div>
          )}
        </div>
      </div>

      {/* 🚫 قسم العملاء المحظورين */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow">
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center">
                <NoSymbolIcon className="h-6 w-6 text-red-600 ml-2" />
                العملاء المحظورين
              </h2>
              <p className="text-sm text-gray-600">
                عرض وإدارة العملاء المحظورين على صفحات Facebook
              </p>
            </div>
          </div>
        </div>

        <div className="p-6">
          {pages && pages.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              لا توجد صفحات مربوطة لعرض العملاء المحظورين
            </div>
          ) : (
            <div className="space-y-4">
              {/* اختيار الصفحة */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  اختر صفحة لعرض العملاء المحظورين عليها
                </label>
                <select
                  value={selectedPageForBlocked || ""}
                  onChange={(e) => {
                    const pageId = e.target.value;
                    setSelectedPageForBlocked(pageId);
                    if (pageId) {
                      loadBlockedCustomers(pageId);
                    } else {
                      setBlockedCustomers([]);
                    }
                  }}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">-- اختر صفحة --</option>
                  {pages?.map((page) => (
                    <option key={page.id} value={page.pageId}>
                      {page.pageName} ({page.pageId})
                    </option>
                  ))}
                </select>
              </div>

              {/* قائمة العملاء المحظورين */}
              {selectedPageForBlocked && (
                <div>
                  {loadingBlocked ? (
                    <div className="flex justify-center py-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                    </div>
                  ) : blockedCustomers.length === 0 ? (
                    <div className="text-center py-8 text-gray-500">
                      <NoSymbolIcon className="h-12 w-12 mx-auto text-gray-400 mb-2" />
                      <p>لا يوجد عملاء محظورين على هذه الصفحة</p>
                    </div>
                  ) : (
                    <div className="space-y-3">
                      <div className="text-sm text-gray-600 mb-2">
                        عدد العملاء المحظورين: {blockedCustomers.length}
                      </div>
                      {blockedCustomers.map((blocked) => (
                        <div
                          key={blocked.id}
                          className="border border-red-200 dark:border-red-800 rounded-lg p-4 bg-red-50 dark:bg-red-900/20"
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex items-center space-x-3">
                              <UserIcon className="h-8 w-8 text-red-600" />
                              <div>
                                <h4 className="font-medium text-gray-900 dark:text-white">
                                  {blocked.customer?.firstName}{" "}
                                  {blocked.customer?.lastName}
                                </h4>
                                <p className="text-sm text-gray-600 dark:text-gray-300">
                                  Facebook ID:{" "}
                                  {blocked.facebookId || "غير متوفر"}
                                </p>
                                {blocked.reason && (
                                  <p className="text-sm text-gray-500 mt-1">
                                    السبب: {blocked.reason}
                                  </p>
                                )}
                                <p className="text-xs text-gray-400 mt-1">
                                  تم الحظر في:{" "}
                                  {new Date(blocked.blockedAt).toLocaleString(
                                    "ar-EG",
                                  )}
                                </p>
                              </div>
                            </div>
                            <button
                              onClick={() =>
                                handleUnblockCustomer(
                                  blocked.customerId,
                                  selectedPageForBlocked,
                                )
                              }
                              className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center space-x-2"
                            >
                              <CheckCircleIcon className="h-5 w-5" />
                              <span>إلغاء الحظر</span>
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Connect Page Modal */}
      {showConnectModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">
              ربط صفحة Facebook
            </h3>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Page Access Token
                </label>
                <textarea
                  value={newPageData.pageAccessToken}
                  onChange={(e) => {
                    const token = e.target.value;
                    setNewPageData({ pageAccessToken: token });
                    validateAccessToken(token);
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  rows={3}
                  placeholder="أدخل Page Access Token من Facebook Developer"
                />
                <p className="text-xs text-gray-500 mt-1">
                  سيتم جلب معلومات الصفحة تلقائياً عند إدخال Access Token صحيح
                </p>
              </div>

              {isValidating && (
                <div className="flex items-center justify-center py-4">
                  <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600"></div>
                  <span className="mr-2 text-sm text-gray-600">
                    جاري التحقق من Access Token...
                  </span>
                </div>
              )}

              {pageInfo && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                  <div className="flex items-center">
                    <CheckCircleIcon className="h-5 w-5 text-green-600 ml-2" />
                    <h4 className="font-medium text-green-900">
                      تم العثور على الصفحة
                    </h4>
                  </div>
                  <div className="mt-2 text-sm text-green-700">
