              regionRules.map((rule, index) => (
                <div
                  key={`${rule.key}-${index}`}
                  className="border border-gray-200 dark:border-gray-700 rounded-lg p-3 space-y-2"
                >
                  <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <input
                      value={rule.key}
                      onChange={(e) => updateRegionRule(index, { key: e.target.value })}
                      placeholder="مثال: القاهرة"
                      className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-sm"
                    />
                    <button
                      onClick={() => removeRegionRule(index)}
                      className="text-xs text-red-600 hover:underline"
                    >
                      حذف
                    </button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {eligibleUsers.length === 0 && (
                      <span className="text-xs text-gray-400">لا يوجد مستخدمون متاحون</span>
                    )}
                    {eligibleUsers.map((user) => (
                      <label key={user.id} className="flex items-center gap-2 text-xs">
                        <input
                          type="checkbox"
                          checked={rule.userIds.includes(user.id)}
                          onChange={() => toggleRegionUser(index, user.id)}
                        />
                        {formatUserLabel(user)}
                      </label>
                    ))}
                  </div>
                </div>
              ))
            )}
            <button
              onClick={() => setRegionRules((prev) => [...prev, { key: '', userIds: [] }])}
              className="text-xs text-indigo-600 hover:underline"
            >
              إضافة قاعدة منطقة
            </button>
          </div>
          <div className="space-y-3">
            <div>
              <label className="block text-sm font-medium mb-1">قواعد التخصص</label>
              <p className="text-xs text-gray-500">أضف اسم التخصص وحدد الموظفين المختصين به.</p>
            </div>
            {specialtyRules.length === 0 ? (
              <div className="text-xs text-gray-500">لا توجد قواعد تخصص بعد.</div>
            ) : (
              specialtyRules.map((rule, index) => (
                <div
                  key={`${rule.key}-${index}`}
                  className="border border-gray-200 dark:border-gray-700 rounded-lg p-3 space-y-2"
                >
                  <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <input
                      value={rule.key}
                      onChange={(e) => updateSpecialtyRule(index, { key: e.target.value })}
                      placeholder="مثال: منتجات العناية"
                      className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-sm"
                    />
                    <button
                      onClick={() => removeSpecialtyRule(index)}
                      className="text-xs text-red-600 hover:underline"
                    >
                      حذف
                    </button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {eligibleUsers.length === 0 && (
                      <span className="text-xs text-gray-400">لا يوجد مستخدمون متاحون</span>
                    )}
                    {eligibleUsers.map((user) => (
                      <label key={user.id} className="flex items-center gap-2 text-xs">
                        <input
                          type="checkbox"
                          checked={rule.userIds.includes(user.id)}
                          onChange={() => toggleSpecialtyUser(index, user.id)}
                        />
                        {formatUserLabel(user)}
                      </label>
                    ))}
                  </div>
                </div>
              ))
            )}
            <button
              onClick={() => setSpecialtyRules((prev) => [...prev, { key: '', userIds: [] }])}
              className="text-xs text-indigo-600 hover:underline"
            >
              إضافة قاعدة تخصص
            </button>
          </div>
        </div>
      </div>

      <div className="flex justify-end">
        <button
          onClick={handleSave}
          disabled={saving}
          className="px-5 py-2 bg-indigo-600 text-white rounded-lg text-sm font-semibold disabled:opacity-60"
        >
          {saving ? 'جاري الحفظ...' : 'حفظ الإعدادات'}
        </button>
      </div>
    </div>
  );
};

export default OrderConfirmationSettings;

import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import { apiClient } from "../../services/api";
import toast from "react-hot-toast";
import {
  Cog6ToothIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowPathIcon,
} from "@heroicons/react/24/outline";

interface OrderSettings {
  enableSequentialOrders: boolean;
  orderPrefix: string;
  nextOrderNumber: number;
  orderNumberFormat: string;
}

const OrderNumberingSettings: React.FC = () => {
  const { t } = useTranslation();
  const [settings, setSettings] = useState<OrderSettings>({
    enableSequentialOrders: false,
    orderPrefix: "ORD",
    nextOrderNumber: 1,
    orderNumberFormat: "PREFIX-XXXXXX",
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [resetNumber, setResetNumber] = useState("");
  const [previewNumber, setPreviewNumber] = useState("ORD-000001");
  const [applyToPastOrders, setApplyToPastOrders] = useState(false);

  // Fetch settings on mount
  useEffect(() => {
    fetchSettings();
  }, []);

  // Update preview when settings change
  useEffect(() => {
    updatePreview();
  }, [settings.orderPrefix, settings.nextOrderNumber]);

  const fetchSettings = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/order-settings");
      if (response.data.success) {
        const data = response.data.data || {};
        setSettings({
          enableSequentialOrders: data.enableSequentialOrders ?? false,
          orderPrefix: data.orderPrefix || "ORD",
          nextOrderNumber: data.nextOrderNumber || 1,
          orderNumberFormat: data.orderNumberFormat || "PREFIX-XXXXXX",
        });
      }
    } catch (error) {
      console.error("Error fetching settings:", error);
      // Error toast is handled by apiClient
    } finally {
      setLoading(false);
    }
  };

  const updatePreview = () => {
    const paddedNumber = settings.nextOrderNumber.toString();
    setPreviewNumber(`${settings.orderPrefix}-${paddedNumber}`);
  };

  const handleSave = async () => {
    try {
      setSaving(true);
      const response = await apiClient.put("/order-settings", {
        ...settings,
        applyToPastOrders,
      });
      if (response.data.success) {
        toast.success(
          t("orderNumbering.saveSuccess") || "تم حفظ الإعدادات بنجاح ✅",
        );
        fetchSettings(); // Refresh to get latest state
      }
    } catch (error: any) {
      console.error("Error saving settings:", error);
      // Error toast is handled by apiClient
    } finally {
      setSaving(false);
    }
  };

  const handleResetCounter = async () => {
    const newNumber = parseInt(resetNumber);

    if (!resetNumber || newNumber < 1) {
      toast.error(
        t("orderNumbering.invalidNumber") ||
          "الرجاء إدخال رقم صحيح (1 أو أكثر)",
      );
      return;
    }

    if (
      !window.confirm(
        `هل أنت متأكد من إعادة تعيين العداد إلى ${newNumber}؟\nسيبدأ الرقم التالي من ${newNumber}`,
      )
    ) {
      return;
    }

    try {
      setSaving(true);
      const response = await apiClient.post("/order-settings/reset-counter", {
        newStartNumber: newNumber,
      });

      if (response.data.success) {
        toast.success(
          t("orderNumbering.resetSuccess") ||
            `تم إعادة تعيين العداد بنجاح ✅\nالرقم التالي: ${newNumber}`,
        );
        setResetNumber("");
        fetchSettings();
      }
    } catch (error: any) {
      console.error("Error resetting counter:", error);
      // Error toast is handled by apiClient
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Main Settings Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6 mb-6">
        <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
          الإعدادات الأساسية
        </h2>

        {/* Enable Sequential Numbering */}
        <div className="mb-6">
          <label className="flex items-center cursor-pointer">
            <input
              id="order-numbering-enable-sequential"
              name="enableSequentialOrders"
              type="checkbox"
              checked={settings.enableSequentialOrders}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  enableSequentialOrders: e.target.checked,
                })
              }
              className="w-5 h-5 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
            />
            <span className="mr-3 text-gray-900 dark:text-gray-100 font-medium">
              تفعيل الترقيم التسلسلي
            </span>
          </label>
          <p className="text-sm text-gray-500 dark:text-gray-400 mr-8 mt-1">
            عند التفعيل، ستبدأ أرقام الطلبات من 1 وتزيد تلقائياً (ORD-1, ORD-2,
            ...)
          </p>
        </div>

        {/* Order Prefix */}
        <div className="mb-6">
          <label
            htmlFor="order-numbering-prefix"
            className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
          >
            البادئة (Prefix)
          </label>
          <input
            id="order-numbering-prefix"
            name="orderPrefix"
            type="text"
            autoComplete="off"
            value={settings.orderPrefix}
            onChange={(e) =>
              setSettings({
                ...settings,
                orderPrefix: e.target.value.toUpperCase(),
              })
            }
            maxLength={10}
            className="w-full max-w-xs px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:text-gray-100"
            placeholder="ORD"
            disabled={!settings.enableSequentialOrders}
          />
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            الأحرف أو الكلمة التي تظهر قبل الرقم (حد أقصى 10 أحرف)
          </p>
        </div>

        {/* Next Order Number */}
        <div className="mb-6">
          <label
            htmlFor="order-numbering-next-number"
            className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
          >
            الرقم التالي
          </label>
          <input
            id="order-numbering-next-number"
            name="nextOrderNumber"
            type="number"
            autoComplete="off"
            value={settings.nextOrderNumber}
            onChange={(e) =>
              setSettings({
                ...settings,
                nextOrderNumber: parseInt(e.target.value) || 1,
              })
            }
            min="1"
            className="w-full max-w-xs px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:text-gray-100"
            disabled={!settings.enableSequentialOrders}
          />
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            الرقم الذي سيتم استخدامه للطلب القادم
          </p>
        </div>

        {/* Preview */}
        <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4 mb-6">
          <div className="flex items-center gap-2 mb-2">
            <span className="text-sm font-medium text-blue-900 dark:text-blue-100">
              معاينة رقم الطلب القادم:
            </span>
          </div>
          <div className="text-2xl font-bold text-blue-600 dark:text-blue-400 font-mono">
            {settings.enableSequentialOrders
              ? previewNumber
              : "ORD-173719-456 (عشوائي)"}
          </div>
        </div>

        {/* Apply To Option */}
        <div className="mb-6 p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg border border-gray-200 dark:border-gray-600">
          <span className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-3">
            نطاق تطبيق التعديلات:
          </span>
          <div className="flex flex-col gap-3">
            <label className="flex items-center cursor-pointer group">
              <input
                id="order-numbering-apply-new-only"
                type="radio"
                name="applyScope"
                checked={!applyToPastOrders}
                onChange={() => setApplyToPastOrders(false)}
                className="w-4 h-4 text-blue-600 border-gray-300 focus:ring-blue-500"
              />
              <div className="mr-3">
                <span className="block text-sm font-medium text-gray-900 dark:text-gray-100">
                  تطبيق على الطلبات الجديدة فقط (من الآن)
                </span>
                <span className="block text-xs text-gray-500 dark:text-gray-400">
                  الطلبات السابقة ستحتفظ بأرقامها القديمة دون تغيير
                </span>
              </div>
            </label>

            <label className="flex items-center cursor-pointer group">
              <input
                id="order-numbering-apply-all"
                type="radio"
                name="applyScope"
                checked={applyToPastOrders}
                onChange={() => setApplyToPastOrders(true)}
                className="w-4 h-4 text-blue-600 border-gray-300 focus:ring-blue-500"
              />
              <div className="mr-3">
                <span className="block text-sm font-medium text-gray-900 dark:text-gray-100">
                  تطبيق على كافة الطلبات (الكل)
                </span>
                <span className="block text-xs text-amber-600 dark:text-amber-400">
                  ⚠️ سيتم تحديث أرقام كافة الطلبات السابقة لتتوافق مع البادئة
                  والترقيم الجديد
                </span>
              </div>
            </label>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex gap-3">
          <button
            onClick={handleSave}
            disabled={saving}
            className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50"
          >
            {saving ? (
              <>
                <ArrowPathIcon className="w-5 h-5 animate-spin" />
                جاري الحفظ...
              </>
            ) : (
              <>
                <CheckCircleIcon className="w-5 h-5" />
                حفظ الإعدادات
              </>
            )}
          </button>
        </div>

        {/* Reset Counter Card */}
        {settings.enableSequentialOrders && (
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4 flex items-center gap-2">
              <ArrowPathIcon className="w-5 h-5" />
              إعادة تعيين العداد
            </h2>
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
              يمكنك إعادة تعيين العداد لبدء الترقيم من رقم معين. استخدم هذه
              الميزة بحذر.
            </p>

            <div className="flex items-end gap-3">
              <div className="flex-1 max-w-xs">
                <label
                  htmlFor="order-numbering-reset-counter"
                  className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2"
                >
                  الرقم الجديد
                </label>
                <input
                  id="order-numbering-reset-counter"
                  name="resetNumber"
                  type="number"
                  autoComplete="off"
                  value={resetNumber}
                  onChange={(e) => setResetNumber(e.target.value)}
                  min="1"
                  placeholder="مثال: 100"
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-red-500 dark:bg-gray-700 dark:text-gray-100"
                />
              </div>
              <button
                onClick={handleResetCounter}
                disabled={saving || !resetNumber}
                className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <ArrowPathIcon className="w-5 h-5 inline ml-2" />
                إعادة تعيين
              </button>
            </div>

            <div className="mt-4 p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
              <p className="text-sm text-yellow-800 dark:text-yellow-200">
                ⚠️ <strong>تحذير:</strong> إعادة تعيين العداد قد يؤدي إلى تكرار
                أرقام الطلبات إذا كانت موجودة بالفعل في النظام. تأكد من اختيار
                رقم أكبر من آخر رقم طلب حالي.
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default OrderNumberingSettings;

import React, { useState, useEffect } from "react";
import { Settings, Tag, ChevronLeft, Calendar, Hash, LayoutGrid, Star, FileText, LayoutDashboard, Clock, Copy, Package } from "lucide-react";
import { useNavigate, useSearchParams } from "react-router-dom";
import OrderStatusManager from "./OrderStatusManager";
import ScheduledOrderSettings from "./ScheduledOrderSettings";
import OrderNumberingSettings from "./OrderNumberingSettings";
import DuplicateOrderSettings from "./DuplicateOrderSettings";
import OrderInvoiceSettings from "./OrderInvoiceSettings";
import RatingSettingsManager from "./RatingSettingsManager";
import OrderColumnsSettings from "./OrderColumnsSettings";
import IncompleteOrdersSettings from "./IncompleteOrdersSettings";
import OrderWorkflow from "../admin/OrderWorkflow";
import OrderConfirmationSettings from "./OrderConfirmationSettings";
import OrderPreparationSettings from "./OrderPreparationSettings";

// ═══════════════════════════════════════════════════════════════
// 📦 Order Settings Page with Sidebar Tabs
// ═══════════════════════════════════════════════════════════════

type TabId =
  | "status"
  | "ratings"
  | "scheduled"
  | "numbering"
  | "duplicates"
  | "invoices"
  | "workflow"
  | "columns"
  | "incomplete"
  | "confirmation"
  | "preparation";

interface Tab {
  id: TabId;
  label: string;
  icon: React.ElementType;
  description: string;
}

const OrderSettings: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const [activeTab, setActiveTab] = useState<TabId>(
    (searchParams.get("tab") as TabId) || "status",
  );

  // Update URL when tab changes
  useEffect(() => {
    const tab = searchParams.get("tab") as TabId;
    if (tab && tab !== activeTab) {
      setActiveTab(tab);
    }
  }, [searchParams]);

  const handleTabChange = (tabId: TabId) => {
    setActiveTab(tabId);
    setSearchParams({ tab: tabId });
  };

  const tabs: Tab[] = [
    {
      id: "status",
      label: "حالات الطلبات",
      icon: Tag,
      description: "إدارة حالات الطلبات والدفع",
    },
    {
      id: "scheduled",
      label: "الطلبات المجدولة",
      icon: Calendar,
      description: "إعدادات الطلبات المجدولة",
    },
    {
      id: "columns",
      label: "أعمدة صفحة الطلبات",
      icon: LayoutGrid,
      description: "تحديد الأعمدة الظاهرة في جدول الطلبات",
    },
    {
      id: "incomplete",
      label: "الطلبات غير المكتملة",
      icon: Clock,
      description: "تحديد مدة تحويل الطلبات إلى مفقود",
    },
    {
      id: "numbering",
      label: "ترقيم الطلبات",
      icon: Hash,
      description: "تخصيص تسلسل أرقام الطلبات",
    },
    {
      id: "duplicates",
      label: "الطلبات المكررة",
      icon: Copy,
      description: "إعدادات فلترة أو تجاهل الطلبات المكررة",
    },
    {
      id: "invoices",
      label: "إعدادات الفواتير",
      icon: FileText,
      description: "تخصيص وتوليد فواتير الطلبات",
    },
    {
      id: "ratings",
      label: "تقييم العملاء",
      icon: Star,
      description: "تصنيف العملاء ومعدل النجاح",
    },
    {
      id: "workflow",
      label: "مسار الطلبات والصلاحيات",
      icon: LayoutDashboard,
      description: "إدارة مسار الحالات والاعتمادات والرقابة",
    },
    {
      id: "confirmation",
      label: "تأكيد وتوزيع الطلبات",
      icon: LayoutDashboard,
      description: "قواعد التأكيد والتوزيع التلقائي",
    },
    {
      id: "preparation",
      label: "تجهيز الطلبات",
      icon: Package,
      description: "إعدادات المخزن، الجودة، والإجراءات الجماعية",
    },
  ];

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900" dir="rtl">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="w-full px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate(-1)}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
            >
              <ChevronLeft className="w-5 h-5 text-gray-600 dark:text-gray-400 rotate-180" />
            </button>
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl flex items-center justify-center">
                <Settings className="w-5 h-5 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-gray-900 dark:text-white">
                  إعدادات الطلبات
                </h1>
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  إدارة إعدادات الطلبات
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="w-full px-4 sm:px-6 lg:px-8 py-6">
        <div className="flex gap-6">
          {/* Sidebar Tabs */}
          <div className="w-64 flex-shrink-0">
            <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden sticky top-6">
              <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                <h2 className="font-semibold text-gray-900 dark:text-white">
                  الإعدادات
                </h2>
              </div>
              <nav className="p-2">
                {tabs.map((tab) => (
                  <button
                    key={tab.id}
                    onClick={() => handleTabChange(tab.id)}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-right transition-colors ${activeTab === tab.id
                      ? "bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400"
                      : "text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                      }`}
                  >
                    <tab.icon
                      className={`w-5 h-5 ${activeTab === tab.id
                        ? "text-blue-600 dark:text-blue-400"
                        : "text-gray-400"
                        }`}
                    />
                    <div className="flex-1">
                      <div className="font-medium">{tab.label}</div>
                      <div className="text-xs text-gray-500 dark:text-gray-400">
                        {tab.description}
                      </div>
                    </div>
                  </button>
                ))}
              </nav>
            </div>
          </div>

          {/* Content Area */}
          <div className="flex-1 min-w-0">
            {activeTab === "status" && <OrderStatusManager />}
            {activeTab === "scheduled" && <ScheduledOrderSettings />}
            {activeTab === "columns" && <OrderColumnsSettings />}
            {activeTab === "incomplete" && <IncompleteOrdersSettings />}
            {activeTab === "numbering" && <OrderNumberingSettings />}
            {activeTab === "duplicates" && <DuplicateOrderSettings />}
            {activeTab === "invoices" && <OrderInvoiceSettings />}
            {activeTab === "ratings" && <RatingSettingsManager />}
            {activeTab === "workflow" && <OrderWorkflow isEmbedded={true} />}
            {activeTab === "confirmation" && <OrderConfirmationSettings />}
            {activeTab === "preparation" && <OrderPreparationSettings />}
          </div>
        </div>
      </div>
    </div>
  );
};

