const SETUP_STEPS = [
  {
    step: '1',
    title: 'أنشئ حساب مجاني على Clarity',
    desc: 'سجل بحسابك على Microsoft أو GitHub أو البريد الإلكتروني.',
    link: 'https://clarity.microsoft.com',
    linkText: 'افتح Microsoft Clarity',
    color: 'bg-blue-600',
  },
  {
