    linkText: null,
    color: 'bg-green-600',
  },
];

const StorefrontClaritySettings: React.FC = () => {
  const { t } = useTranslation();
  const [settings, setSettings] = useState<StorefrontSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [copied, setCopied] = useState(false);

  const clarityProjectId = settings?.clarityProjectId || '';
  const isConnected = Boolean(clarityProjectId.trim());
  const clarityDashboardUrl = clarityProjectId
    ? `https://clarity.microsoft.com/projects/view/${clarityProjectId}/dashboard`
    : 'https://clarity.microsoft.com';

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const response = await storefrontSettingsService.getSettings();
        const settingsData = (response as any).data?.data || (response as any).data;
        setSettings(settingsData);
      } catch (error) {
        console.error('Failed to fetch storefront settings:', error);
        toast.error(t('settings.fetchError', 'فشل تحميل الإعدادات'));
      } finally {
        setLoading(false);
      }
    };

    void fetchSettings();
  }, [t]);

  const handleSave = async () => {
    if (!settings) return;

    setSaving(true);
    try {
      await storefrontSettingsService.updateSettings({
        clarityProjectId: settings.clarityProjectId,
      });
      toast.success('تم حفظ إعدادات Clarity');
    } catch (error) {
      console.error('Failed to update clarity settings:', error);
      toast.error(t('settings.saveError', 'فشل الحفظ، حاول مرة أخرى'));
    } finally {
      setSaving(false);
    }
  };

  const handleCopyId = async () => {
    if (!clarityProjectId) return;

    try {
      await navigator.clipboard.writeText(clarityProjectId);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
      toast.success('تم نسخ الـ ID');
    } catch {
      toast.error('تعذر نسخ الـ ID');
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <div className="h-8 w-8 animate-spin rounded-full border-b-2 border-blue-600" />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-5xl space-y-8 px-4 py-8 sm:px-6 lg:px-8">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-4">
          <ClarityLogo />
          <div>
            <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
              Microsoft Clarity
            </h2>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              افهم زبائنك من خلال خرائط الحرارة وتسجيلات الجلسات مجانًا.
            </p>
          </div>
        </div>

        <div
          className={`inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-medium transition-all ${
            isConnected
              ? 'border-green-200 bg-green-50 text-green-700 dark:border-green-800/40 dark:bg-green-900/20 dark:text-green-400'
              : 'border-gray-200 bg-gray-100 text-gray-500 dark:border-slate-600 dark:bg-slate-700 dark:text-gray-400'
          }`}
        >
          {isConnected ? (
            <>
              <span className="relative flex h-2.5 w-2.5">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-green-400 opacity-75" />
                <span className="relative inline-flex h-2.5 w-2.5 rounded-full bg-green-500" />
              </span>
              متصل والتتبع نشط
            </>
          ) : (
            <>
              <XCircleIcon className="h-4 w-4" />
              غير متصل
            </>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {FEATURES.map((feature) => (
          <div
            key={feature.title}
            className={`flex flex-col gap-2 rounded-xl border p-4 ${feature.color}`}
          >
            <div className="flex items-center gap-2">
              {feature.icon}
              <div>
                <p className="text-sm font-semibold text-gray-800 dark:text-gray-100">
                  {feature.title}
                </p>
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  {feature.subtitle}
                </p>
              </div>
            </div>
            <p className="text-xs leading-relaxed text-gray-600 dark:text-gray-300">
              {feature.desc}
            </p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 gap-8 lg:grid-cols-5">
        <div className="space-y-4 lg:col-span-2">
          <h3 className="flex items-center gap-2 text-base font-semibold text-gray-800 dark:text-gray-200">
            <InformationCircleIcon className="h-5 w-5 text-blue-500" />
            خطوات الربط
          </h3>

          <div className="space-y-3">
            {SETUP_STEPS.map((step) => (
              <div
                key={step.step}
                className="flex gap-3 rounded-xl border border-gray-100 bg-white p-4 shadow-sm dark:border-slate-700 dark:bg-slate-800"
              >
                <div
                  className={`${step.color} flex h-7 w-7 flex-shrink-0 items-center justify-center rounded-full text-sm font-bold text-white`}
                >
                  {step.step}
                </div>
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-gray-800 dark:text-gray-200">
                    {step.title}
                  </p>
                  <p className="mt-1 text-xs leading-relaxed text-gray-500 dark:text-gray-400">
                    {step.desc}
                  </p>
                  {step.link ? (
                    <a
                      href={step.link}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="mt-2 inline-flex items-center gap-1 text-xs text-blue-600 hover:underline dark:text-blue-400"
                    >
                      {step.linkText}
                      <ArrowTopRightOnSquareIcon className="h-3 w-3" />
                    </a>
                  ) : null}
                </div>
              </div>
            ))}
          </div>

          <div className="rounded-xl border border-gray-100 bg-gray-50 p-4 dark:border-slate-700 dark:bg-slate-800/60">
            <p className="mb-3 text-xs font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400">
              روابط مفيدة
            </p>
            <div className="space-y-2">
              {[
                {
                  label: 'التسجيل المجاني على Clarity',
                  url: 'https://clarity.microsoft.com',
                },
                {
                  label: 'شرح Heatmaps بالتفصيل',
                  url: 'https://learn.microsoft.com/en-us/clarity/setup-and-installation/clarity-heatmap',
                },
                {
                  label: 'شرح Session Recordings',
                  url: 'https://learn.microsoft.com/en-us/clarity/setup-and-installation/session-recordings',
                },
                {
                  label: 'كيفية إيجاد الـ Project ID',
                  url: 'https://learn.microsoft.com/en-us/clarity/setup-and-installation/clarity-overview',
                },
              ].map((link) => (
                <a
                  key={link.url}
                  href={link.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center gap-2 text-xs text-blue-600 hover:text-blue-800 hover:underline dark:text-blue-400 dark:hover:text-blue-300"
                >
                  <ArrowTopRightOnSquareIcon className="h-3.5 w-3.5 flex-shrink-0" />
                  {link.label}
                </a>
              ))}
            </div>
          </div>
        </div>

        <div className="space-y-4 lg:col-span-3">
          <div className="overflow-hidden rounded-xl border border-gray-100 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-800">
            <div className="space-y-6 p-6">
              <div>
                <label
                  htmlFor="clarityProjectId"
                  className="mb-1 block text-sm font-medium text-gray-700 dark:text-gray-300"
                >
                  Clarity Project ID
                </label>
                <div className="flex overflow-hidden rounded-lg border border-gray-300 shadow-sm transition-all focus-within:border-blue-500 focus-within:ring-2 focus-within:ring-blue-500 dark:border-slate-600">
                  <span className="inline-flex items-center border-r border-gray-300 bg-gray-50 px-3 text-sm text-gray-500 dark:border-slate-600 dark:bg-slate-700 dark:text-gray-400">
                    ID
                  </span>
                  <input
                    type="text"
                    id="clarityProjectId"
                    value={clarityProjectId}
                    onChange={(event) =>
                      setSettings((current) =>
                        current
                          ? { ...current, clarityProjectId: event.target.value }
                          : null,
                      )
                    }
                    className="flex-1 bg-white px-4 py-2.5 text-sm text-gray-900 outline-none placeholder-gray-400 dark:bg-slate-900 dark:text-white"
                    placeholder="مثال: k3a9mz1b"
                    dir="ltr"
                  />
                  {clarityProjectId ? (
                    <button
                      type="button"
                      onClick={handleCopyId}
                      title="نسخ الـ ID"
                      className="border-l border-gray-300 bg-gray-50 px-3 text-gray-400 transition-colors hover:text-gray-600 dark:border-slate-600 dark:bg-slate-700 dark:hover:text-gray-300"
                    >
                      {copied ? (
                        <CheckCircleIconSolid className="h-4 w-4 text-green-500" />
                      ) : (
                        <ClipboardDocumentIcon className="h-4 w-4" />
                      )}
                    </button>
                  ) : null}
                </div>
                <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                  ستجد هذا الـ ID في لوحة Clarity ثم Settings ثم Overview. انسخ الكود القصير فقط
                  وليس السكريبت الكامل.
                </p>
              </div>

              <div
                className={`flex items-start gap-3 rounded-lg border p-4 ${
                  isConnected
                    ? 'border-green-100 bg-green-50 dark:border-green-800/30 dark:bg-green-900/20'
                    : 'border-yellow-100 bg-yellow-50 dark:border-yellow-800/30 dark:bg-yellow-900/20'
                }`}
              >
                {isConnected ? (
                  <>
                    <CheckCircleIcon className="mt-0.5 h-5 w-5 flex-shrink-0 text-green-600 dark:text-green-400" />
                    <div>
                      <p className="text-sm font-medium text-green-800 dark:text-green-300">
                        Clarity نشط على متجرك
                      </p>
                      <p className="mt-0.5 text-xs text-green-600 dark:text-green-400">
                        يتم الآن تسجيل جلسات الزوار وخرائط الحرارة. قد تظهر البيانات خلال 24 إلى
                        48 ساعة.
                      </p>
                    </div>
                  </>
                ) : (
                  <>
                    <InformationCircleIcon className="mt-0.5 h-5 w-5 flex-shrink-0 text-yellow-600 dark:text-yellow-400" />
                    <div>
                      <p className="text-sm font-medium text-yellow-800 dark:text-yellow-300">
                        Clarity غير مفعّل بعد
                      </p>
                      <p className="mt-0.5 text-xs text-yellow-600 dark:text-yellow-400">
                        اتبع الخطوات الموجودة على اليسار للحصول على Project ID ثم فعّل الخدمة.
                      </p>
                    </div>
                  </>
                )}
              </div>

              {isConnected ? (
                <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                  <a
                    href={clarityDashboardUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-blue-50 px-4 py-2.5 text-sm font-medium text-blue-700 transition-colors hover:bg-blue-100 dark:border-blue-800/40 dark:bg-blue-900/20 dark:text-blue-300 dark:hover:bg-blue-900/40"
                  >
                    <ChartBarIcon className="h-4 w-4" />
                    فتح لوحة Clarity
                    <ArrowTopRightOnSquareIcon className="h-3.5 w-3.5" />
                  </a>
                  <a
                    href={`https://clarity.microsoft.com/projects/view/${clarityProjectId}/heatmaps`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2 rounded-lg border border-orange-200 bg-orange-50 px-4 py-2.5 text-sm font-medium text-orange-700 transition-colors hover:bg-orange-100 dark:border-orange-800/40 dark:bg-orange-900/20 dark:text-orange-300 dark:hover:bg-orange-900/40"
                  >
                    <FireIcon className="h-4 w-4" />
                    خرائط الحرارة
                    <ArrowTopRightOnSquareIcon className="h-3.5 w-3.5" />
                  </a>
                  <a
                    href={`https://clarity.microsoft.com/projects/view/${clarityProjectId}/recordings`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2 rounded-lg border border-violet-200 bg-violet-50 px-4 py-2.5 text-sm font-medium text-violet-700 transition-colors hover:bg-violet-100 dark:border-violet-800/40 dark:bg-violet-900/20 dark:text-violet-300 dark:hover:bg-violet-900/40"
                  >
                    <PlayCircleIcon className="h-4 w-4" />
                    تسجيلات الزوار
                    <ArrowTopRightOnSquareIcon className="h-3.5 w-3.5" />
                  </a>
                  <a
                    href={`https://clarity.microsoft.com/projects/view/${clarityProjectId}/funnels`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2 rounded-lg border border-teal-200 bg-teal-50 px-4 py-2.5 text-sm font-medium text-teal-700 transition-colors hover:bg-teal-100 dark:border-teal-800/40 dark:bg-teal-900/20 dark:text-teal-300 dark:hover:bg-teal-900/40"
                  >
                    <FunnelIcon className="h-4 w-4" />
                    تحليل المبيعات
                    <ArrowTopRightOnSquareIcon className="h-3.5 w-3.5" />
                  </a>
                </div>
              ) : null}
            </div>

            <div className="flex items-center justify-between border-t border-gray-100 bg-gray-50/50 px-6 py-4 dark:border-slate-700 dark:bg-slate-800/50">
              <a
                href="https://clarity.microsoft.com"
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1 text-xs text-blue-600 hover:underline dark:text-blue-400"
              >
                الخدمة مجانية تمامًا من Microsoft
                <ArrowTopRightOnSquareIcon className="h-3 w-3" />
              </a>

              <button
                type="button"
                onClick={handleSave}
                disabled={saving}
                className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-5 py-2 text-sm font-medium text-white shadow-sm transition-colors hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50"
              >
                {saving ? (
                  <>
                    <span className="h-4 w-4 animate-spin rounded-full border-b-2 border-white" />
                    جاري الحفظ...
                  </>
                ) : (
                  <>
                    <CheckCircleIconSolid className="h-4 w-4" />
                    حفظ الإعدادات
                  </>
                )}
              </button>
            </div>
          </div>

          <div className="rounded-xl bg-gradient-to-r from-blue-600 to-indigo-600 p-5 text-white">
            <p className="mb-3 text-sm font-semibold">نصائح للاستفادة القصوى</p>
            <ul className="space-y-2 text-xs leading-relaxed text-blue-100">
              <li>انتظر 24 إلى 48 ساعة بعد التفعيل لتظهر أول بيانات في اللوحة.</li>
              <li>ركز على صفحة المنتج والـ checkout لأنهما الأهم في رحلة الشراء.</li>
              <li>راجع تقارير Rage Clicks أسبوعيًا لاكتشاف المشاكل المؤثرة على التحويل.</li>
              <li>يمكنك ربط Clarity مع Google Analytics للحصول على رؤية أكمل.</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StorefrontClaritySettings;

import React, { useState, useEffect } from "react";
import { useAuth } from "../../hooks/useAuthSimple";
import { telegramService } from "../../services/telegramService";
import { toast } from "react-hot-toast";
import { apiClient } from "../../services/apiClient";
import {
  PaperAirplaneIcon,
  CpuChipIcon,
  CheckCircleIcon,
  XCircleIcon,
  UserIcon,
  KeyIcon,
  EyeIcon,
  EyeSlashIcon,
} from "@heroicons/react/24/outline";
import { useTheme } from "../../hooks/useTheme";

const TelegramSettings = () => {
  const { user } = useAuth();
  const { derivedTheme } = useTheme();
  const [activeTab, setActiveTab] = useState<"bots" | "userbots">("bots");

  // Bots State
  const [bots, setBots] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isChecking, setIsChecking] = useState(true);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newBotToken, setNewBotToken] = useState("");
  const [newBotLabel, setNewBotLabel] = useState("");

  // Userbots State
  const [userbots, setUserbots] = useState<any[]>([]);
  const [showAddUserbotForm, setShowAddUserbotForm] = useState(false);

  // Connection Wizard State
  const [connectionStep, setConnectionStep] = useState<
    "INIT" | "OTP" | "2FA" | "RECONNECT_PHONE"
  >("INIT");
  const [currentConfigId, setCurrentConfigId] = useState<string | null>(null);
  const [phoneCodeHash, setPhoneCodeHash] = useState<string | null>(null);

  // Form Fields
  const [newUserbotLabel, setNewUserbotLabel] = useState("");
  const [newUserbotApiId, setNewUserbotApiId] = useState("");
  const [newUserbotApiHash, setNewUserbotApiHash] = useState("");
  const [newUserbotPhone, setNewUserbotPhone] = useState("");
  const [verificationCode, setVerificationCode] = useState("");
  const [password, setPassword] = useState("");

  const [showApiHash, setShowApiHash] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  useEffect(() => {
    if (user?.companyId) {
      checkStatus();
      loadUserbots();
    }
  }, [user?.companyId]);

  const checkStatus = async () => {
    if (!user?.companyId) return;
    try {
      setIsChecking(true);
      const data = await telegramService.getStatus(user.companyId);
      setBots(data.bots || []);
    } catch (error) {
      console.error("Failed to fetch status:", error);
      toast.error("Failed to load bots");
    } finally {
      setIsChecking(false);
    }
  };

  const loadUserbots = async () => {
    if (!user?.companyId) return;
    try {
      const response = await apiClient.get("/telegram/userbots");
      setUserbots(response.data.data || []);
    } catch (error: any) {
      console.error("Failed to load userbots:", error);
      if (error.response?.status !== 404) {
        toast.error("Failed to load userbots");
      }
    }
  };

  const resetForm = () => {
    setNewUserbotLabel("");
    setNewUserbotApiId("");
    setNewUserbotApiHash("");
    setNewUserbotPhone("");
    setVerificationCode("");
    setPassword("");
    setConnectionStep("INIT");
    setCurrentConfigId(null);
    setShowAddUserbotForm(false);
  };

  const handleStartConnection = async () => {
    if (!user?.companyId) return;

    // Validation based on mode
    if (connectionStep === "INIT") {
      if (!newUserbotApiId || !newUserbotApiHash || !newUserbotPhone) {
        toast.error("Please fill in all required fields");
        return;
      }
    } else if (connectionStep === "RECONNECT_PHONE") {
      if (!newUserbotPhone) {
        toast.error("Please enter phone number");
        return;
      }
    }

    try {
      setIsLoading(true);
      let configId = currentConfigId;

      // 1. Create Userbot Config (Only if INIT)
      if (connectionStep === "INIT") {
        const createResponse = await apiClient.post("/telegram/userbots", {
          label: newUserbotLabel || "Telegram Userbot",
          apiId: newUserbotApiId,
          apiHash: newUserbotApiHash,
        });
        configId = createResponse.data.data.id;
        setCurrentConfigId(configId);
      }

      if (!configId) {
        throw new Error("Configuration ID missing");
      }

      // 2. Request Login Code - Use send-code endpoint to send phone number
      const loginResponse = await apiClient.post(
        "/telegram/userbot/send-code",
        {
          userbotConfigId: configId,
          phoneNumber: newUserbotPhone,
        },
      );

      if (loginResponse.data.success) {
        toast.success("Code sent to your Telegram account!");
        setPhoneCodeHash(loginResponse.data.phoneCodeHash);
        setConnectionStep("OTP");
      } else {
        toast.error("Failed to send code: " + loginResponse.data.error);
      }
    } catch (error: any) {
      toast.error(
        "Connection failed: " + (error.response?.data?.error || error.message),
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleAskReconnect = (userbot: any) => {
    setCurrentConfigId(userbot.id);
    setNewUserbotPhone(userbot.clientPhone || "");
    setNewUserbotLabel(userbot.label || "");
    setConnectionStep("RECONNECT_PHONE");
    setShowAddUserbotForm(true);
  };

  const handleVerifyCode = async () => {
    if (!verificationCode || !currentConfigId) return;

    try {
      setIsLoading(true);

      const verifyResponse = await apiClient.post("/telegram/userbot/login", {
        userbotConfigId: currentConfigId,
        code: verificationCode,
        password: password, // Sent only if set
      });

      if (verifyResponse.data.success) {
        toast.success("Userbot Connected Successfully!");
        loadUserbots();
        resetForm();
      } else {
        if (verifyResponse.data.requiresPassword) {
          toast.error("Two-Step Verification Required");
          setConnectionStep("2FA");
        } else {
          toast.error("Verification failed: " + verifyResponse.data.error);
        }
      }
    } catch (error: any) {
      // Handle 401 specifically for generic auth failure, but check if it's password required
      const errorData = error.response?.data;
      if (
        errorData?.requiresPassword ||
        errorData?.error?.includes("PASSWORD_REQUIRED")
      ) {
        toast.error("Two-Step Verification Required");
        setConnectionStep("2FA");
      } else {
        toast.error(
          "Verification failed: " + (errorData?.error || error.message),
        );
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteUserbot = async (userbotId: string) => {
    if (!window.confirm("Are you sure you want to delete this userbot?"))
      return;
    if (!user?.companyId) return;

    try {
      setIsLoading(true);
      await apiClient.delete(`/telegram/userbots/${userbotId}`);
      toast.success("Userbot deleted");
      loadUserbots();
    } catch (error: any) {
      toast.error(
        "Failed to delete userbot: " +
          (error.response?.data?.error || error.message),
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleConnect = async () => {
    if (!newBotToken) {
      toast.error("Please enter a Bot Token");
      return;
    }

    if (!user?.companyId) return;

    try {
      setIsLoading(true);
      await telegramService.connectBot(
        user.companyId,
        newBotToken,
        newBotLabel,
      );
      toast.success("Telegram Bot Connected Successfully!");
      setNewBotToken("");
      setNewBotLabel("");
      setShowAddForm(false);
      checkStatus();
    } catch (error: any) {
      toast.error(
        "Connection Failed: " +
          (error.response?.data?.message || error.message),
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleDisconnect = async (configId: string) => {
    if (!window.confirm("Are you sure you want to disconnect this bot?"))
      return;
    if (!user?.companyId) return;

    try {
      setIsLoading(true);
      await telegramService.disconnectBot(user.companyId, configId);
      toast.success("Bot Disconnected");
      checkStatus();
    } catch (error: any) {
      toast.error(
        "Disconnect Failed: " +
          (error.response?.data?.message || error.message),
      );
    } finally {
      setIsLoading(false);
    }
  };

  if (isChecking) {
    return <div className="p-8 text-center">Loading Telegram Status...</div>;
  }

  return (
    <div
      className={`p-6 w-full ${derivedTheme === "dark" ? "bg-gray-900 text-white" : "bg-white text-gray-900"}`}
    >
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <PaperAirplaneIcon className="w-10 h-10 text-sky-500 transform -rotate-45" />
          <h1
            className={`text-3xl font-bold ${derivedTheme === "dark" ? "text-white" : "text-gray-800"}`}
          >
            Telegram Integration
          </h1>
        </div>
      </div>

      {/* Tabs */}
      <div
        className={`flex gap-2 mb-6 ${derivedTheme === "dark" ? "border-gray-700" : "border-gray-200"}`}
      >
        <button
          onClick={() => setActiveTab("bots")}
          className={`px-4 py-2 font-medium transition-colors ${
            activeTab === "bots"
              ? "text-blue-600 border-b-2 border-blue-600"
              : derivedTheme === "dark"
                ? "text-gray-400 hover:text-gray-200"
                : "text-gray-500 hover:text-gray-700"
          }`}
        >
          Telegram Bots
        </button>
        <button
          onClick={() => setActiveTab("userbots")}
          className={`px-4 py-2 font-medium transition-colors ${
            activeTab === "userbots"
              ? "text-blue-600 border-b-2 border-blue-600"
              : derivedTheme === "dark"
                ? "text-gray-400 hover:text-gray-200"
                : "text-gray-500 hover:text-gray-700"
          }`}
        >
          Telegram Userbots
        </button>
      </div>

      {/* Bots Tab */}
      {activeTab === "bots" && (
        <>
          {!showAddForm && (
            <div className="mb-4 flex justify-end">
              <button
                onClick={() => setShowAddForm(true)}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors shadow-sm flex items-center gap-2"
              >
                <span>+ Add New Bot</span>
              </button>
            </div>
          )}

          {/* Helper Text */}
          <div
            className={`${derivedTheme === "dark" ? "bg-blue-900 border-blue-800 text-white" : "bg-blue-50 border-blue-100 text-blue-800"} rounded-xl p-4 mb-6`}
          >
            <p
              className={`text-sm ${derivedTheme === "dark" ? "text-white" : "text-blue-800"}`}
            >
              Connect your Telegram Bots to manage support, sales, or other
              channels. Create bots via{" "}
              <a
                href="https://t.me/BotFather"
                target="_blank"
                rel="noopener noreferrer"
                className="font-semibold underline"
              >
                @BotFather
              </a>
              .
            </p>
          </div>

          {/* List of Bots */}
          <div className="space-y-4 mb-8">
            {bots.length === 0 && !showAddForm && (
              <div
