                          {showPassword ? (
                            <EyeSlashIcon className="w-5 h-5" />
                          ) : (
                            <EyeIcon className="w-5 h-5" />
                          )}
                        </button>
                      </div>
                    </div>
                    <div className="flex gap-3 pt-2">
                      <button
                        onClick={handleVerifyCode}
                        disabled={isLoading || !password}
                        className={`flex-1 py-3 rounded-lg font-medium text-white transition-all ${
                          isLoading || !password
                            ? "bg-green-300 cursor-not-allowed"
                            : "bg-green-600 hover:bg-green-700 shadow-md"
                        }`}
                      >
                        {isLoading ? "Verifying..." : "Complete Login"}
                      </button>
                      <button
                        onClick={resetForm}
                        disabled={isLoading}
                        className="px-6 py-3 border border-gray-300 rounded-lg font-medium text-gray-700 hover:bg-gray-50"
                      >
                        Cancel
                      </button>
                    </div>
                  </>
                )}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default TelegramSettings;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  ChatBubbleLeftRightIcon,
  ClockIcon,
  UserIcon,
  ExclamationCircleIcon,
  PaperAirplaneIcon,
  PhotoIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import { apiClient } from "../../services/apiClient";

interface Message {
  id: number;
  ticket_id: number;
  message: string;
  content: string; // Turbo API uses content
  sender_name: string;
  created_at: string;
  is_client_message: number;
  is_comment: number;
  sender: {
    id: number;
    first_name: string;
    last_name: string;
    role_name: string;
  };
  user?: {
    // Turbo API uses user
    id: number;
    name: string;
    first_name: string;
    last_name: string;
    role: {
      name: string;
    };
  };
}

interface TicketDetails {
  id: number;
  description: string;
  content: string; // Turbo API uses content
  status: number;
  created_at: string;
  messages: Message[];
  logs?: any[];
}

const TicketDetails: React.FC = () => {
  const { ticketId } = useParams<{ ticketId: string }>();
  const navigate = useNavigate();
  const [ticket, setTicket] = useState<TicketDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [replyMessage, setReplyMessage] = useState("");
  const [replyImage, setReplyImage] = useState<File | null>(null);
  const [sendingReply, setSendingReply] = useState(false);

  useEffect(() => {
    if (ticketId) {
      loadTicketDetails();
    }
  }, [ticketId]);

  const loadTicketDetails = async () => {
    try {
      setLoading(true);
      setError(null);

      console.log(`🎫 Loading ticket details from Backend for ID: ${ticketId}`);

      // Call both backend endpoints parallel
      const [ticketResponse, logResponse] = await Promise.all([
        apiClient.get(`/turbo/tickets/${ticketId}`),
        apiClient.get(`/turbo/tickets/${ticketId}/log`),
      ]);

      console.log("📋 Backend ticket response:", ticketResponse.data);
      console.log("📋 Backend log response:", logResponse.data);

      if (!ticketResponse.data.success) {
        throw new Error(
          ticketResponse.data.message || "فشل تحميل تفاصيل التذكرة",
        );
      }

      // Backend structure: { success: true, data: { success: true, ticket: {...}, ... } }
      const ticketResult = ticketResponse.data.data;
      const logResult = logResponse.data.data;

      // Extract ticket data - ticketResult.ticket contains the actual ticket from Turbo API
      const ticketData = ticketResult.ticket || {};
      // Extract logs - logResult.logs contains the log array
      const logsData = logResult.logs || [];

      // Turbo API returns messages in replies field, not messages
      // Convert replies to messages for consistency
      const messages = ticketData.messages || ticketData.replies || [];

      // Sort messages by created_at ascending (oldest first) for display from top to bottom
      const sortedMessages = [...messages].sort((a, b) => {
        const dateA = new Date(a.created_at || 0).getTime();
        const dateB = new Date(b.created_at || 0).getTime();
        return dateA - dateB;
      });

      // Combine ticket data with logs
      const combinedTicket = {
        id: ticketData.id || parseInt(ticketId || "0"),
        description:
          ticketData.content || ticketData.description || "تذكرة Turbo",
        content: ticketData.content || ticketData.description || "",
        status: ticketData.status !== undefined ? ticketData.status : 1,
        created_at: ticketData.created_at || new Date().toISOString(),
        messages: sortedMessages,
        logs: logsData,
      };

      console.log("✅ Combined ticket data:", combinedTicket);
      console.log(
        "📋 Ticket messages count:",
        combinedTicket.messages?.length || 0,
      );
      console.log("📋 Ticket logs count:", combinedTicket.logs?.length || 0);
      console.log("📋 Sample message:", combinedTicket.messages?.[0]);
      console.log("📋 Sample log:", combinedTicket.logs?.[0]);
      setTicket(combinedTicket);
    } catch (error: any) {
      console.error("❌ Error loading ticket from Backend:", error);
      setError(
        error.response?.data?.message ||
          error.message ||
          "فشل تحميل تفاصيل التذكرة",
      );
      toast.error("فشل تحميل تفاصيل التذكرة");
    } finally {
      setLoading(false);
    }
  };

  const getStatusText = (status: number) => {
    switch (status) {
      case 0:
        return "جديد";
      case 1:
        return "قيد المعالجة";
      case 2:
        return "مغلق";
      default:
        return "غير معروف";
    }
  };

  const getStatusColor = (status: number) => {
    switch (status) {
      case 0:
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300";
      case 1:
        return "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300";
      case 2:
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300";
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200";
    }
  };

  const formatDate = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleString("ar-EG", {
        year: "numeric",
        month: "long",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return dateString;
    }
  };

  const handleReply = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!replyMessage.trim() && !replyImage) {
      toast.error("يرجى إدخال رسالة أو رفع صورة");
      return;
    }

    if (!ticketId) {
      toast.error("معرف التذكرة غير موجود");
      return;
    }

    try {
      setSendingReply(true);

      // إنشاء FormData
      const formData = new FormData();
      formData.append("message", replyMessage);

      // إضافة الصورة إذا كانت موجودة
      if (replyImage) {
        formData.append("image", replyImage);
      }

      const response = await apiClient.post(
        `/turbo/tickets/${ticketId}/reply`,
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        },
      );

      if (response.data.success) {
        toast.success("تم إرسال الرد بنجاح");
        setReplyMessage("");
        setReplyImage(null);
        // إعادة تحميل تفاصيل التذكرة لتحديث الرسائل
        loadTicketDetails();
      } else {
        throw new Error(response.data.message || "فشل إرسال الرد");
      }
    } catch (error: any) {
      console.error("❌ Error sending reply:", error);
      toast.error(
        error.response?.data?.error || error.message || "فشل إرسال الرد",
      );
    } finally {
      setSendingReply(false);
    }
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // التحقق من نوع الملف
      if (!file.type.startsWith("image/")) {
        toast.error("يرجى رفع ملف صورة فقط");
        return;
      }
      // التحقق من حجم الملف (10MB)
      if (file.size > 10 * 1024 * 1024) {
        toast.error("حجم الصورة يجب أن يكون أقل من 10MB");
        return;
      }
      setReplyImage(file);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 p-6 dark:bg-gray-950">
        <div className="w-full">
          <div className="rounded-lg bg-white p-8 text-center shadow dark:bg-gray-900 dark:shadow-black/20">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
            <p className="text-gray-600 dark:text-gray-300">
              جاري تحميل تفاصيل التذكرة...
            </p>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 p-6 dark:bg-gray-950">
        <div className="w-full">
          <button
            onClick={() => navigate("/settings/turbo")}
            className="mb-6 flex items-center gap-2 text-gray-600 hover:text-gray-800 dark:text-gray-300 dark:hover:text-white"
          >
            <ArrowLeftIcon className="w-4 h-4" />
            العودة لإعدادات Turbo
          </button>

          <div className="rounded-lg bg-white p-8 text-center shadow dark:bg-gray-900 dark:shadow-black/20">
            <ExclamationCircleIcon className="w-12 h-12 text-red-500 mx-auto mb-4" />
            <h2 className="mb-2 text-xl font-semibold text-gray-900 dark:text-white">
              خطأ في تحميل التذكرة
            </h2>
            <p className="mb-4 text-gray-600 dark:text-gray-300">{error}</p>
            <button
              onClick={loadTicketDetails}
              className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700"
            >
              إعادة المحاولة
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!ticket) {
    return (
      <div className="min-h-screen bg-gray-50 p-6 dark:bg-gray-950">
        <div className="w-full">
          <button
            onClick={() => navigate("/settings/turbo")}
            className="mb-6 flex items-center gap-2 text-gray-600 hover:text-gray-800 dark:text-gray-300 dark:hover:text-white"
          >
            <ArrowLeftIcon className="w-4 h-4" />
            العودة لإعدادات Turbo
          </button>

          <div className="rounded-lg bg-white p-8 text-center shadow dark:bg-gray-900 dark:shadow-black/20">
            <p className="text-gray-600 dark:text-gray-300">
              لم يتم العثور على التذكرة
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6 text-gray-900 dark:bg-gray-950 dark:text-gray-100">
      <div className="w-full">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <button
            onClick={() => navigate("/settings/turbo")}
            className="flex items-center gap-2 text-gray-600 hover:text-gray-800 dark:text-gray-300 dark:hover:text-white"
          >
            <ArrowLeftIcon className="w-4 h-4" />
            العودة لإعدادات Turbo
          </button>

          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            تذكرة #{ticket.id}
          </h1>
        </div>

        {/* Ticket Info */}
        <div className="mb-6 rounded-lg bg-white p-6 shadow dark:bg-gray-900 dark:shadow-black/20">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <ChatBubbleLeftRightIcon className="w-6 h-6 text-indigo-600" />
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                معلومات التذكرة
              </h2>
            </div>

            <span
              className={`px-3 py-1 text-sm rounded-full ${getStatusColor(ticket.status)}`}
            >
              {getStatusText(ticket.status)}
            </span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
            <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
              <ClockIcon className="w-4 h-4" />
              تاريخ الإنشاء: {formatDate(ticket.created_at)}
            </div>
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300">
              وصف المشكلة
            </label>
            <p className="rounded-lg bg-gray-50 p-4 text-gray-900 dark:bg-gray-800 dark:text-gray-100">
              {ticket.description}
            </p>
          </div>
        </div>

        {/* Messages/Conversation */}
        <div className="rounded-lg bg-white p-6 shadow dark:bg-gray-900 dark:shadow-black/20">
          <div className="flex items-center gap-3 mb-6">
            <ChatBubbleLeftRightIcon className="w-6 h-6 text-indigo-600" />
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
              المحادثة
            </h2>
            <span className="text-sm text-gray-500 dark:text-gray-400">
              ({ticket.messages?.length || 0} رسالة)
            </span>
          </div>

          {ticket.messages && ticket.messages.length > 0 ? (
            <div className="space-y-4">
              {ticket.messages.map((message, index) => (
                <div
                  key={message.id || index}
                  className={`flex ${Number(message.is_client_message) === 1 ? "justify-start" : "justify-end"}`}
                >
                  <div
                    className={`max-w-[70%] ${
                      Number(message.is_client_message) === 1
                        ? "bg-gray-100 text-gray-900 dark:bg-gray-800 dark:text-gray-100"
                        : "bg-indigo-600 text-white"
                    } rounded-lg p-4`}
                  >
                    {/* Sender info */}
                    <div className="flex items-center gap-2 mb-2">
                      <UserIcon className="w-4 h-4" />
                      <span className="text-sm font-medium">
                        {message.user?.name ||
                          message.sender_name ||
                          (message.user?.first_name
                            ? `${message.user.first_name} ${message.user.last_name}`
                            : null) ||
                          (message.sender?.first_name
                            ? `${message.sender.first_name} ${message.sender.last_name}`
                            : "مستخدم")}
                      </span>
                      {Number(message.is_client_message) === 1 ? (
                        (message.user?.role?.name ||
                          message.sender?.role_name) && (
                          <span className="rounded bg-gray-200 px-2 py-1 text-xs text-gray-600 dark:bg-gray-700 dark:text-gray-200">
                            {message.user?.role?.name ||
                              message.sender?.role_name}
                          </span>
                        )
                      ) : (
                        <span className="text-xs px-2 py-1 rounded bg-indigo-500 text-indigo-100">
                          خدمة العملاء
                        </span>
                      )}
                    </div>

                    {/* Message content */}
                    <p className="text-sm whitespace-pre-wrap">
                      {message.content || message.message}
                    </p>

                    {/* Timestamp */}
                    <p
                      className={`text-xs mt-2 ${
                        Number(message.is_client_message) === 1
                          ? "text-gray-500 dark:text-gray-400"
                          : "text-indigo-200"
                      }`}
                    >
                      {formatDate(message.created_at)}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="py-8 text-center text-gray-500 dark:text-gray-400">
              <ChatBubbleLeftRightIcon className="mx-auto mb-4 h-12 w-12 text-gray-300 dark:text-gray-600" />
              <p>لا توجد رسائل في هذه التذكرة</p>
            </div>
          )}
        </div>

        {/* Reply Form */}
        <div className="mt-6 rounded-lg bg-white p-6 shadow dark:bg-gray-900 dark:shadow-black/20">
          <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-white">
            إرسال رد
          </h2>
          <form onSubmit={handleReply} className="space-y-4">
            <div>
              <label
                htmlFor="replyMessage"
                className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                الرسالة
              </label>
              <textarea
                id="replyMessage"
                value={replyMessage}
                onChange={(e) => setReplyMessage(e.target.value)}
                rows={4}
                className="w-full rounded-lg border border-gray-300 px-3 py-2 focus:border-indigo-500 focus:ring-indigo-500 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-100"
                placeholder="اكتب رسالتك هنا..."
                disabled={sendingReply}
              />
            </div>

            <div>
              <label
                htmlFor="replyImage"
                className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                صورة (اختياري)
              </label>
              <div className="flex items-center gap-4">
                <label
                  htmlFor="replyImage"
                  className="flex cursor-pointer items-center gap-2 rounded-lg border border-gray-300 px-4 py-2 hover:bg-gray-50 dark:border-gray-700 dark:hover:bg-gray-800"
                >
                  <PhotoIcon className="h-5 w-5 text-gray-600 dark:text-gray-300" />
                  <span className="text-sm text-gray-700 dark:text-gray-200">
                    {replyImage ? replyImage.name : "اختر صورة"}
                  </span>
                </label>
                <input
                  id="replyImage"
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="hidden"
                  disabled={sendingReply}
                />
                {replyImage && (
                  <button
                    type="button"
                    onClick={() => setReplyImage(null)}
                    className="text-sm text-red-600 hover:text-red-700 dark:text-red-400 dark:hover:text-red-300"
                    disabled={sendingReply}
                  >
                    إزالة
                  </button>
                )}
              </div>
            </div>

            <button
              type="submit"
              disabled={sendingReply || (!replyMessage.trim() && !replyImage)}
              className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              <PaperAirplaneIcon className="w-5 h-5" />
              {sendingReply ? "جاري الإرسال..." : "إرسال الرد"}
            </button>
          </form>
        </div>

        {/* Logs Section */}
        {ticket.logs && ticket.logs.length > 0 && (
          <div className="mt-6 rounded-lg bg-white p-6 shadow dark:bg-gray-900 dark:shadow-black/20">
            <div className="flex items-center gap-3 mb-6">
              <ClockIcon className="w-6 h-6 text-indigo-600" />
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                سجل التذكرة
              </h2>
              <span className="text-sm text-gray-500 dark:text-gray-400">
                ({ticket.logs.length} سجل)
              </span>
            </div>

            <div className="space-y-3">
              {ticket.logs.map((log: any, index: number) => (
                <div
                  key={log.id || index}
                  className="rounded-lg border-r-4 border-indigo-500 bg-gray-50 p-4 dark:bg-gray-800"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <p className="mb-2 text-sm text-gray-900 dark:text-gray-100">
                        {log.description?.ar ||
                          log.description ||
                          "لا يوجد وصف"}
                      </p>
                      <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
                        <UserIcon className="w-3 h-3" />
                        <span>{log.user?.full_name || "مستخدم"}</span>
                        <span>•</span>
                        <span>{formatDate(log.created_at)}</span>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default TicketDetails;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  RocketLaunchIcon,
  CheckCircleIcon,
  XCircleIcon,
  InformationCircleIcon,
  KeyIcon,
  LinkIcon,
  ArrowLeftIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import { apiClient } from "../../services/apiClient";

interface TurboSettings {
  turboEnabled: boolean;
  turboAutoCreate: boolean;
  turboApiKey: string;
  turboMainClientCode: number | null;
  turboSenderNumber: string;
  turboWebhookUrl: string;
  turboWebhookToken: string;
  hasApiKey: boolean;
  maskedApiKey: string;
}

const TurboSettings: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [showApiKey, setShowApiKey] = useState(false);
  const [settings, setSettings] = useState<TurboSettings>({
    turboEnabled: false,
    turboAutoCreate: false,
    turboApiKey: "",
    turboMainClientCode: null,
    turboSenderNumber: "",
    turboWebhookUrl: "",
    turboWebhookToken: "",
    hasApiKey: false,
    maskedApiKey: "",
  });
  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get("/store-settings/turbo");
      if (response.data.success) {
        setSettings({
          turboEnabled: response.data.data.turboEnabled || false,
          turboAutoCreate: response.data.data.turboAutoCreate || false,
          turboApiKey: "",
          turboMainClientCode: response.data.data.turboMainClientCode || null,
          turboSenderNumber: response.data.data.turboSenderNumber || "",
          turboWebhookUrl: response.data.data.turboWebhookUrl || "",
          turboWebhookToken: response.data.data.turboWebhookToken || "",
          hasApiKey: response.data.data.hasApiKey || false,
          maskedApiKey: response.data.data.maskedApiKey || "",
        });
      }
    } catch (error: any) {
      console.error("Error loading Turbo settings:", error);
      toast.error("فشل تحميل إعدادات Turbo");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!settings.turboApiKey && !settings.hasApiKey) {
      toast.error("يرجى إدخال Turbo API Key");
      return;
    }

    if (settings.turboEnabled && !settings.turboApiKey && !settings.hasApiKey) {
      toast.error("يرجى إدخال Turbo API Key لتفعيل Turbo");
      return;
    }

    try {
      setSaving(true);
      const response = await apiClient.put("/store-settings/turbo", {
        turboApiKey: settings.turboApiKey || undefined,
        turboMainClientCode: settings.turboMainClientCode || undefined,
        turboSenderNumber: settings.turboSenderNumber || undefined,
        turboEnabled: settings.turboEnabled,
        turboAutoCreate: settings.turboAutoCreate,
        turboWebhookUrl: settings.turboWebhookUrl || undefined,
        turboWebhookToken: settings.turboWebhookToken || undefined,
      });

      if (response.data.success) {
        toast.success("تم حفظ إعدادات Turbo بنجاح");
        loadSettings(); // Reload to get updated masked key
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "فشل حفظ الإعدادات");
      console.error("Error saving Turbo settings:", error);
    } finally {
      setSaving(false);
    }
  };

  const handleTestConnection = async () => {
    if (!settings.turboApiKey && !settings.hasApiKey) {
      toast.error("يرجى إدخال Turbo API Key أولاً");
      return;
    }

    try {
      setSaving(true);
      // Test by trying to calculate shipping cost (simple test)
      const response = await apiClient.post("/turbo/calculate", {
        city: "القاهرة",
        address: "test",
        items: [
          { weight: 1, dimensions: { length: 10, width: 10, height: 10 } },
        ],
      });
      if (response.data.success) {
        toast.success("✅ الاتصال بـ Turbo يعمل بشكل صحيح!");
      }
    } catch (error: any) {
      toast.error(
        error.response?.data?.error || "فشل الاتصال بـ Turbo. تحقق من API Key",
      );
      console.error("Error testing Turbo connection:", error);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96 dark:bg-gray-900">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 dark:border-indigo-400 mx-auto"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">
            جاري التحميل...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full px-4 sm:px-6 lg:px-8 py-8 dark:bg-gray-900 min-h-screen">
      {/* Header */}
      <div className="mb-8">
        <button
          onClick={() => navigate("/store-settings")}
          className="flex items-center text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200 mb-4"
        >
          <ArrowLeftIcon className="h-5 w-5 ml-2" />
          العودة لإعدادات المتجر
        </button>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center">
          <RocketLaunchIcon className="h-8 w-8 text-indigo-600 dark:text-indigo-400 ml-3" />
          إعدادات Turbo للشحن
        </h1>
        <p className="mt-2 text-gray-600 dark:text-gray-400">
          تكامل مع شركة Turbo للشحن - إدارة API Key والإعدادات
        </p>
      </div>

      {/* Main Content */}
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 space-y-6 border border-gray-200 dark:border-gray-700">
        {/* Status Card */}
        <div
          className={`p-4 rounded-lg border-2 ${settings.turboEnabled
            ? "bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800"
            : "bg-gray-50 dark:bg-gray-900/50 border-gray-200 dark:border-gray-700"
            }`}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center">
              {settings.turboEnabled ? (
                <CheckCircleIcon className="h-6 w-6 text-green-600 dark:text-green-400 ml-2" />
              ) : (
                <XCircleIcon className="h-6 w-6 text-gray-400 dark:text-gray-500 ml-2" />
              )}
              <div>
                <h3 className="font-medium text-gray-900 dark:text-white">
                  {settings.turboEnabled ? "Turbo مفعّل" : "Turbo معطّل"}
                </h3>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {settings.turboEnabled
                    ? "خدمة Turbo للشحن نشطة وجاهزة للاستخدام"
                    : "قم بتفعيل Turbo وإدخال API Key للبدء"}
                </p>
              </div>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                checked={settings.turboEnabled}
                onChange={(e) =>
                  setSettings({ ...settings, turboEnabled: e.target.checked })
                }
                className="sr-only peer"
              />
              <div className="w-14 h-7 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:right-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-indigo-600"></div>
            </label>
          </div>
        </div>

        {/* API Key Section */}
        <div className="border-t dark:border-gray-700 pt-6">
          <div className="flex items-center mb-4">
            <KeyIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              Turbo API Key
            </h3>
          </div>

          <div className="space-y-4">
            {settings.hasApiKey && settings.maskedApiKey && (
              <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
                <p className="text-sm text-gray-700 dark:text-gray-300 mb-2">
                  API Key الحالي:
                </p>
                <div className="flex items-center justify-between">
                  <code className="text-sm font-mono text-blue-700 dark:text-blue-300 bg-blue-100 dark:bg-blue-900/30 px-3 py-1 rounded">
                    {settings.maskedApiKey}
                  </code>
                  <button
                    onClick={() => setShowApiKey(!showApiKey)}
                    className="text-sm text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300"
                  >
                    {showApiKey ? "إخفاء" : "تحديث API Key"}
                  </button>
                </div>
              </div>
            )}

            {(showApiKey || !settings.hasApiKey) && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  {settings.hasApiKey ? "API Key جديد" : "Turbo API Key"}
                </label>
                <input
                  type="password"
                  value={settings.turboApiKey}
                  onChange={(e) =>
                    setSettings({ ...settings, turboApiKey: e.target.value })
                  }
                  placeholder="أدخل Turbo API Key"
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400"
                />
                <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                  يمكنك الحصول على API Key من{" "}
                  <a
                    href="https://portal.turbo-eg.com"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-indigo-600 dark:text-indigo-400 hover:underline"
                  >
                    بوابة Turbo
                  </a>
                </p>
              </div>
            )}

            <button
              onClick={handleTestConnection}
              disabled={
                saving || (!settings.turboApiKey && !settings.hasApiKey)
              }
              className="inline-flex items-center px-4 py-2 bg-gray-600 dark:bg-gray-700 text-white rounded-lg hover:bg-gray-700 dark:hover:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed text-sm"
            >
              <InformationCircleIcon className="h-4 w-4 ml-1" />
              اختبار الاتصال
            </button>
          </div>
        </div>

        {/* Main Client Code Section */}
        <div className="border-t dark:border-gray-700 pt-6">
          <div className="flex items-center mb-4">
            <KeyIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              Main Client Code
            </h3>
          </div>

          <div className="space-y-2">
            <input
              type="number"
              value={settings.turboMainClientCode || ""}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  turboMainClientCode: e.target.value
                    ? parseInt(e.target.value)
                    : null,
                })
              }
              placeholder="37321"
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400"
            />
            <p className="text-xs text-gray-500 dark:text-gray-400">
              Main Client Code الخاص بك من Turbo (مثال: 37321)
            </p>
          </div>
        </div>

        {/* Sender Number Section */}
        <div className="border-t dark:border-gray-700 pt-6">
          <div className="flex items-center mb-4">
            <KeyIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              رقم الراسل
            </h3>
          </div>

          <div className="space-y-2">
            <input
              type="text"
              value={settings.turboSenderNumber || ""}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  turboSenderNumber: e.target.value,
                })
              }
              placeholder="01000000000"
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400"
            />
            <p className="text-xs text-gray-500 dark:text-gray-400">
              رقم هاتف الراسل الذي سيتم إرساله مع كل شحنة Turbo (مثال:
              01000000000)
            </p>
          </div>
        </div>

        {/* Auto Create Section */}
        <div className="border-t dark:border-gray-700 pt-6">
          <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg">
            <div className="flex-1">
              <h3 className="text-sm font-medium text-gray-900 dark:text-white mb-1">
                الشحن التلقائي
              </h3>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                إنشاء شحنة Turbo تلقائياً لأي طلب يتم تأكيده. إذا كان معطلاً،
                يجب إنشاء الشحنة يدوياً من صفحة تفاصيل الطلب.
              </p>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                checked={settings.turboAutoCreate}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    turboAutoCreate: e.target.checked,
                  })
                }
                disabled={!settings.turboEnabled}
                className="sr-only peer"
              />
              <div
                className={`w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:right-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600 ${!settings.turboEnabled ? "opacity-50 cursor-not-allowed" : ""}`}
              ></div>
            </label>
          </div>
        </div>

        {/* Webhook URL Section */}
        <div className="border-t dark:border-gray-700 pt-6">
          <div className="flex items-center mb-4">
            <LinkIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              Webhook URL (اختياري)
            </h3>
          </div>

          <div className="space-y-2">
            <input
              type="url"
              value={settings.turboWebhookUrl}
              onChange={(e) =>
                setSettings({ ...settings, turboWebhookUrl: e.target.value })
              }
              placeholder="https://yourdomain.com/api/v1/turbo/webhook"
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400"
            />
            <p className="text-xs text-gray-500 dark:text-gray-400">
              رابط لاستقبال تحديثات حالة الشحنات من Turbo تلقائياً
            </p>
            <p className="text-xs text-gray-400 dark:text-gray-500">
              مثال: {window.location.origin}/api/v1/turbo/webhook
            </p>
          </div>
        </div>

        {/* Webhook Token Section */}
        <div className="border-t dark:border-gray-700 pt-6">
          <div className="flex items-center mb-4">
            <KeyIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              Webhook Token (اختياري)
            </h3>
          </div>

          <div className="space-y-2">
            <input
              type="password"
              value={settings.turboWebhookToken}
              onChange={(e) =>
                setSettings({
                  ...settings,
                  turboWebhookToken: e.target.value,
                })
              }
              placeholder="Bearer Token"
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400"
            />
            <p className="text-xs text-gray-500 dark:text-gray-400">
              Token اختياري للتحقق من صحة webhook requests من Turbo
            </p>
            <p className="text-xs text-gray-400 dark:text-gray-500">
              سيتم استخدام هذا الـ Token للبحث عن الشركة عند استقبال webhook
            </p>
          </div>
        </div>

        {/* Info Section */}
        <div className="border-t dark:border-gray-700 pt-6">
          <div className="bg-indigo-50 dark:bg-indigo-900/20 p-4 rounded-lg border border-indigo-200 dark:border-indigo-800">
            <div className="flex items-start">
              <InformationCircleIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2 mt-0.5 flex-shrink-0" />
              <div className="text-sm text-indigo-800 dark:text-indigo-300">
                <h4 className="font-medium mb-2">معلومات مهمة:</h4>
                <ul className="list-disc list-inside space-y-1 text-indigo-700 dark:text-indigo-400">
                  <li>يجب الحصول على Turbo API Key من بوابة Turbo أولاً</li>
                  <li>
                    رقم الراسل سيتم إرساله كـ api_followup_phone مع كل شحنة
                    Turbo
                  </li>
                  <li>
                    عند تفعيل "الشحن التلقائي"، سيتم إنشاء شحنة تلقائياً عند
                    تأكيد أي طلب
                  </li>
                  <li>
                    إذا كان الشحن التلقائي معطلاً، يجب إنشاء الشحنات يدوياً من
                    صفحة تفاصيل الطلب
                  </li>
                  <li>
                    Webhook URL اختياري - يستخدم لتلقي تحديثات حالة الشحنات
                    تلقائياً
                  </li>
                </ul>
              </div>
            </div>
          </div>
        </div>

        {/* Save Button */}
        <div className="flex justify-end pt-6 border-t dark:border-gray-700">
          <button
            onClick={handleSave}
            disabled={
              saving ||
              (settings.turboEnabled &&
                !settings.turboApiKey &&
                !settings.hasApiKey)
            }
            className="px-6 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {saving ? "جاري الحفظ..." : "حفظ الإعدادات"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default TurboSettings;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import {
    TicketIcon,
    PlusCircleIcon,
    ChevronRightIcon,
    ArrowPathIcon,
    PaperAirplaneIcon,
    XMarkIcon,
} from "@heroicons/react/24/outline";
import { apiClient } from "../../services/apiClient";

const TurboTickets: React.FC = () => {
    const navigate = useNavigate();

    // --- List state ---
    const [tickets, setTickets] = useState<any[]>([]);
    const [loadingTickets, setLoadingTickets] = useState(false);
    const [ticketsPage, setTicketsPage] = useState(1);
    const ticketsPerPage = 10;
    const [ticketsTotal, setTicketsTotal] = useState(0);

    // --- New ticket form state ---
    const [showForm, setShowForm] = useState(false);
    const [ticketDescription, setTicketDescription] = useState("");
    const [inquiryTypeId, setInquiryTypeId] = useState<number | "">("");
    const [sendingTicket, setSendingTicket] = useState(false);
    const [inquiriesTypes, setInquiriesTypes] = useState<any[]>([]);
    const [loadingTypes, setLoadingTypes] = useState(false);

    const loadTickets = async () => {
        try {
            setLoadingTickets(true);
            const response = await apiClient.get(
                `/turbo/tickets?page=${ticketsPage}&per_page=${ticketsPerPage}`
            );
            if (response.data.success) {
                const ticketsData = response.data.data?.tickets || response.data.data || [];
                const paginationData = response.data.data?.pagination || {};
                setTickets(Array.isArray(ticketsData) ? ticketsData : []);
                setTicketsTotal(paginationData.total || 0);
            } else {
                setTickets([]);
                setTicketsTotal(0);
            }
        } catch (error) {
            console.error("Error loading tickets:", error);
            toast.error("فشل تحميل التذاكر");
            setTickets([]);
        } finally {
            setLoadingTickets(false);
        }
    };

    const loadInquiriesTypes = async () => {
        try {
            setLoadingTypes(true);
            const response = await apiClient.get("/turbo/inquiries-types");
            if (response.data.success) {
                const types =
                    response.data.data?.types ||
                    response.data.data?.inquiriesTypes ||
                    [];
                setInquiriesTypes(Array.isArray(types) ? types : []);
            }
        } catch (error) {
            console.error("Error loading inquiry types:", error);
            // Silently fail — form still works with manual input
        } finally {
            setLoadingTypes(false);
        }
    };

    useEffect(() => {
        loadTickets();
    }, [ticketsPage]);

    useEffect(() => {
        if (showForm && inquiriesTypes.length === 0) {
            loadInquiriesTypes();
        }
    }, [showForm]);

    const handleViewTicket = (ticketId: number) => {
        navigate(`/settings/turbo/ticket/${ticketId}`);
    };

    const handleSendTicket = async () => {
        if (!ticketDescription.trim()) {
            toast.error("يرجى كتابة وصف للتذكرة");
            return;
        }
        if (!inquiryTypeId) {
            toast.error("يرجى اختيار نوع الاستفسار");
            return;
        }
        try {
            setSendingTicket(true);
            const response = await apiClient.post("/turbo/tickets", {
                description: ticketDescription.trim(),
                content: ticketDescription.trim(),
                type: Number(inquiryTypeId),
                inquiryTypeId: Number(inquiryTypeId),
                categoryId: Number(inquiryTypeId),
            });
            if (response.data.success) {
                toast.success("✅ تم إرسال التذكرة بنجاح");
                setTicketDescription("");
                setInquiryTypeId("");
                setShowForm(false);
                loadTickets(); // refresh the list
            } else {
                toast.error(response.data.message || "فشل إرسال التذكرة");
            }
        } catch (error: any) {
            toast.error(error.response?.data?.error || "حدث خطأ أثناء إرسال التذكرة");
            console.error("Error sending ticket:", error);
        } finally {
            setSendingTicket(false);
        }
    };

    const getStatusLabel = (status: number) => {
        switch (status) {
            case 0: return { label: "جديد", className: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400" };
            case 1: return { label: "قيد المعالجة", className: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400" };
            case 2: return { label: "مغلق", className: "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400" };
            default: return { label: "غير محدد", className: "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-400" };
        }
    };

    return (
        <div className="w-full px-4 sm:px-6 lg:px-8 py-8 dark:bg-gray-900 min-h-screen">
            {/* Header */}
            <div className="mb-6 flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                        <TicketIcon className="h-8 w-8 text-indigo-600 dark:text-indigo-400" />
                        تذاكر دعم تربو
                    </h1>
                    <p className="mt-1 text-gray-600 dark:text-gray-400">
                        إنشاء وتتبع تذاكر الدعم الخاصة بشحنات Turbo
                    </p>
                </div>
                <button
                    onClick={() => setShowForm(true)}
                    className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm font-medium transition-colors"
                >
                    <PlusCircleIcon className="h-5 w-5" />
                    تذكرة جديدة
                </button>
            </div>

            {/* New Ticket Form */}
            {showForm && (
                <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-6 border border-indigo-200 dark:border-indigo-700">
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                            <PaperAirplaneIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400" />
                            إرسال تذكرة دعم جديدة
                        </h3>
                        <button
                            onClick={() => { setShowForm(false); setTicketDescription(""); setInquiryTypeId(""); }}
                            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
                        >
                            <XMarkIcon className="h-5 w-5" />
                        </button>
                    </div>

                    <div className="space-y-4">
                        {/* Inquiry Type Selector */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                                نوع الاستفسار / الشكوى <span className="text-red-500">*</span>
                            </label>
                            {loadingTypes ? (
                                <div className="w-full px-3 py-2 text-sm text-gray-500 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700">
                                    جاري تحميل الأنواع...
                                </div>
                            ) : inquiriesTypes.length > 0 ? (
                                <select
                                    value={inquiryTypeId}
                                    onChange={(e) => setInquiryTypeId(Number(e.target.value) as any)}
                                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-indigo-500 text-sm"
                                >
                                    <option value="">-- اختر النوع --</option>
                                    {inquiriesTypes.map((type: any) => (
                                        <option key={type.id} value={type.id}>
                                            {type.name_ar || type.name || type.title || `نوع ${type.id}`}
                                        </option>
                                    ))}
                                </select>
                            ) : (
                                <select
                                    value={inquiryTypeId}
                                    onChange={(e) => setInquiryTypeId(Number(e.target.value) as any)}
                                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-indigo-500 text-sm"
                                >
                                    <option value="">-- اختر النوع --</option>
                                    <option value={1}>استفسار عام</option>
                                    <option value={2}>شكوى</option>
                                    <option value={3}>طلب متابعة شحنة</option>
                                </select>
                            )}
                        </div>

                        {/* Description */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                                تفاصيل التذكرة <span className="text-red-500">*</span>
                            </label>
                            <textarea
                                value={ticketDescription}
                                onChange={(e) => setTicketDescription(e.target.value)}
                                rows={4}
                                placeholder="اكتب تفاصيل المشكلة أو الاستفسار..."
                                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-indigo-500 text-sm resize-none"
                            />
                            <p className="text-xs text-gray-400 mt-1">{ticketDescription.length} / 500 حرف</p>
                        </div>

                        <div className="flex gap-3 justify-end">
                            <button
                                onClick={() => { setShowForm(false); setTicketDescription(""); setInquiryTypeId(""); }}
                                className="px-4 py-2 text-sm text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg transition-colors"
                            >
                                إلغاء
                            </button>
                            <button
                                onClick={handleSendTicket}
                                disabled={sendingTicket || !ticketDescription.trim() || !inquiryTypeId}
                                className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm font-medium disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                            >
                                <PaperAirplaneIcon className="h-4 w-4" />
                                {sendingTicket ? "جاري الإرسال..." : "إرسال التذكرة"}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Tickets List */}
            <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 border border-gray-200 dark:border-gray-700">
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                        قائمة التذاكر
                        {ticketsTotal > 0 && (
                            <span className="mr-2 text-sm text-gray-500 dark:text-gray-400">({ticketsTotal} تذكرة)</span>
                        )}
                    </h3>
                    <button
                        onClick={loadTickets}
                        disabled={loadingTickets}
                        className="inline-flex items-center gap-1 text-sm text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 disabled:opacity-50 transition-colors"
                    >
                        <ArrowPathIcon className={`h-4 w-4 ${loadingTickets ? "animate-spin" : ""}`} />
                        {loadingTickets ? "جاري التحديث..." : "تحديث"}
                    </button>
                </div>

                {loadingTickets ? (
                    <div className="text-center py-12 text-gray-500 dark:text-gray-400">
                        <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 dark:border-indigo-400 mx-auto mb-4"></div>
                        جاري تحميل التذاكر...
                    </div>
                ) : tickets.length === 0 ? (
                    <div className="text-center py-14 bg-gray-50 dark:bg-gray-900/50 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-700">
                        <TicketIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-500" />
                        <h3 className="mt-3 text-sm font-medium text-gray-900 dark:text-white">لا توجد تذاكر حتى الآن</h3>
                        <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">اضغط على "تذكرة جديدة" لإرسال أول تذكرة</p>
                    </div>
                ) : (
                    <div className="divide-y divide-gray-200 dark:divide-gray-700">
                        {tickets.map((ticket: any) => {
                            const statusInfo = getStatusLabel(ticket.status);
                            return (
                                <div
                                    key={ticket.id}
                                    className="py-4 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-gray-700/40 cursor-pointer transition-colors px-2 rounded"
                                    onClick={() => handleViewTicket(ticket.id)}
                                >
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="font-medium text-indigo-600 dark:text-indigo-400 text-sm">
                                                تذكرة #{ticket.id}
                                            </span>
                                            {ticket.trackingNumber && (
                                                <span className="text-xs text-gray-500 dark:text-gray-400">
                                                    — شحنة {ticket.trackingNumber}
                                                </span>
                                            )}
                                            <span className={`px-2 py-0.5 text-xs rounded-full font-medium ${statusInfo.className}`}>
                                                {statusInfo.label}
                                            </span>
                                        </div>
                                        <p className="text-sm text-gray-700 dark:text-gray-300 truncate max-w-xl">
                                            {ticket.description || ticket.content || "لا يوجد وصف"}
                                        </p>
                                        <p className="text-xs text-gray-400 mt-1">
                                            {new Date(ticket.created_at || ticket.createdAt).toLocaleDateString("ar-EG", {
                                                year: "numeric", month: "long", day: "numeric",
                                            })}
                                        </p>
                                    </div>
                                    <ChevronRightIcon className="h-5 w-5 text-gray-400 dark:text-gray-500 mr-2 flex-shrink-0" />
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Pagination */}
                {ticketsTotal > ticketsPerPage && (
                    <div className="flex justify-center items-center gap-4 pt-4 border-t border-gray-200 dark:border-gray-700 mt-4">
                        <button
                            onClick={() => setTicketsPage((p) => Math.max(1, p - 1))}
                            disabled={ticketsPage === 1}
                            className="px-4 py-2 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg text-sm disabled:opacity-50 transition-colors"
                        >
                            السابق
                        </button>
                        <span className="text-sm text-gray-600 dark:text-gray-400">
                            صفحة {ticketsPage} من {Math.ceil(ticketsTotal / ticketsPerPage)}
                        </span>
                        <button
                            onClick={() => setTicketsPage((p) => p + 1)}
                            disabled={ticketsPage >= Math.ceil(ticketsTotal / ticketsPerPage)}
                            className="px-4 py-2 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg text-sm disabled:opacity-50 transition-colors"
                        >
                            التالي
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

