import React, { useState } from "react";
import { uploadService } from "../../../services/uploadService";
import { Upload, Trash2, ChevronUp, ChevronDown, GripVertical, Image as ImageIcon } from "lucide-react";

export interface FieldDef {
    key: string;
    label: string;
    type: "text" | "textarea" | "image" | "number" | "icon";
    placeholder?: string;
}

interface ListItemsEditorProps {
    items: any[];
    onChange: (newItems: any[]) => void;
    fields: FieldDef[];
    newItemTemplate: any;
    itemTitleField: string; // The field to show as title (e.g. 'title' or 'customerName')
    maxItems?: number;
}

const ListItemsEditor: React.FC<ListItemsEditorProps> = ({
    items = [],
    onChange,
    fields,
    newItemTemplate,
    itemTitleField,
    maxItems = 10,
}) => {
    const [expandedIndex, setExpandedIndex] = useState<number | null>(null);
    const [uploadingIndex, setUploadingIndex] = useState<number | null>(null);

    const handleUpdateItem = (index: number, key: string, value: any) => {
        const newItems = [...items];
        newItems[index] = { ...newItems[index], [key]: value };
        onChange(newItems);
    };

    const handleAddItem = () => {
        if (items.length >= maxItems) return;
        onChange([...items, { ...newItemTemplate }]);
        setExpandedIndex(items.length);
    };

    const handleRemoveItem = (index: number, e: React.MouseEvent) => {
        e.stopPropagation();
        const newItems = [...items];
        newItems.splice(index, 1);
        onChange(newItems);
        if (expandedIndex === index) setExpandedIndex(null);
    };

    const moveItem = (index: number, direction: "up" | "down", e: React.MouseEvent) => {
        e.stopPropagation();
        if (direction === "up" && index === 0) return;
        if (direction === "down" && index === items.length - 1) return;

        const newItems = [...items];
        const targetIndex = direction === "up" ? index - 1 : index + 1;
        [newItems[index], newItems[targetIndex]] = [newItems[targetIndex], newItems[index]];
        onChange(newItems);

        if (expandedIndex === index) setExpandedIndex(targetIndex);
        else if (expandedIndex === targetIndex) setExpandedIndex(index);
    };

    const handleImageUpload = async (index: number, key: string, e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        try {
            setUploadingIndex(index);
            const url = await uploadService.uploadImage(file, "homepage");
            handleUpdateItem(index, key, url);
        } catch (error) {
            console.error("Upload error:", error);
            alert("حدث خطأ أثناء رفع الصورة");
        } finally {
            setUploadingIndex(null);
            // Reset input
            if (e.target) e.target.value = '';
        }
    };

    return (
        <div className="space-y-3">
            {items.map((item, index) => (
                <div
                    key={index}
                    className={`border rounded-md overflow-hidden transition-all duration-200 ${expandedIndex === index ? 'border-indigo-400 shadow-md ring-1 ring-indigo-200' : 'border-gray-200'}`}
                >
                    {/* Item Header */}
                    <div
                        className="flex items-center justify-between p-3 bg-gray-50 cursor-pointer hover:bg-gray-100"
                        onClick={() => setExpandedIndex(expandedIndex === index ? null : index)}
                    >
                        <div className="flex items-center gap-3">
                            <GripVertical className="w-4 h-4 text-gray-400 cursor-move" />
                            <span className="text-sm font-medium text-gray-700">
                                {item[itemTitleField] || `عنصر ${index + 1}`}
                            </span>
                        </div>

                        <div className="flex items-center gap-1">
                            <button
                                onClick={(e) => moveItem(index, "up", e)}
                                disabled={index === 0}
                                className="p-1 text-gray-400 hover:text-indigo-600 disabled:opacity-30 disabled:hover:text-gray-400"
                                title="تحريك لأعلى"
                            >
                                <ChevronUp className="w-4 h-4" />
                            </button>
                            <button
                                onClick={(e) => moveItem(index, "down", e)}
                                disabled={index === items.length - 1}
                                className="p-1 text-gray-400 hover:text-indigo-600 disabled:opacity-30 disabled:hover:text-gray-400"
                                title="تحريك لأسفل"
                            >
                                <ChevronDown className="w-4 h-4" />
                            </button>
                            <button
                                onClick={(e) => handleRemoveItem(index, e)}
                                className="p-1 text-gray-400 hover:text-red-500 ml-2"
                                title="حذف العنصر"
                            >
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                    </div>

                    {/* Item Content (Expanded) */}
                    {expandedIndex === index && (
                        <div className="p-4 bg-white space-y-4 border-t border-gray-100">
                            {fields.map((field) => (
                                <div key={field.key}>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">
                                        {field.label}
                                    </label>

                                    {field.type === "text" && (
                                        <input
                                            type="text"
                                            value={item[field.key] || ""}
                                            onChange={(e) => handleUpdateItem(index, field.key, e.target.value)}
                                            placeholder={field.placeholder}
                                            className="w-full px-3 py-2 text-sm border border-gray-300 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
                                        />
                                    )}

                                    {field.type === "textarea" && (
                                        <textarea
                                            value={item[field.key] || ""}
                                            onChange={(e) => handleUpdateItem(index, field.key, e.target.value)}
                                            placeholder={field.placeholder}
                                            rows={3}
                                            className="w-full px-3 py-2 text-sm border border-gray-300 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
                                        />
                                    )}

                                    {field.type === "number" && (
                                        <input
                                            type="number"
                                            value={item[field.key] || 0}
                                            onChange={(e) => handleUpdateItem(index, field.key, parseFloat(e.target.value))}
                                            placeholder={field.placeholder}
                                            className="w-full px-3 py-2 text-sm border border-gray-300 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
                                        />
                                    )}

                                    {field.type === "image" && (
                                        <div>
                                            {item[field.key] && (
                                                <div className="relative mb-2 w-32 h-32 border rounded overflow-hidden">
                                                    <img src={item[field.key]} alt="Preview" className="w-full h-full object-cover" />
                                                </div>
                                            )}
                                            <div className="flex items-center gap-2">
                                                <label className="cursor-pointer bg-white px-3 py-1.5 text-xs border border-gray-300 rounded shadow-sm hover:bg-gray-50 flex items-center gap-2">
                                                    {uploadingIndex === index ? (
                                                        <span className="text-gray-500">جاري الرفع...</span>
                                                    ) : (
                                                        <>
                                                            <Upload className="w-3 h-3 text-gray-500" />
                                                            <span className="font-medium text-gray-700">تغيير الصورة</span>
                                                        </>
                                                    )}
                                                    <input
                                                        type="file"
                                                        className="hidden"
                                                        accept="image/*"
                                                        onChange={(e) => handleImageUpload(index, field.key, e)}
                                                        disabled={uploadingIndex === index}
                                                    />
                                                </label>
                                            </div>
                                        </div>
                                    )}

                                    {field.type === "icon" && (
                                        <input
                                            type="text"
                                            value={item[field.key] || ""}
                                            onChange={(e) => handleUpdateItem(index, field.key, e.target.value)}
                                            placeholder="e.g. ⭐, 🚀, or icon class"
                                            className="w-full px-3 py-2 text-sm border border-gray-300 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 font-sans"
                                        />
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            ))}

            {/* Add New Item Button */}
            {items.length < maxItems && (
                <button
                    onClick={handleAddItem}
                    className="w-full py-2 flex items-center justify-center gap-2 text-sm font-medium text-indigo-600 bg-indigo-50 border border-indigo-100 rounded-md hover:bg-indigo-100 transition-colors"
                >
                    <span>إضافة عنصر جديد</span>
                </button>
            )}

            {items.length >= maxItems && (
                <div className="text-center text-xs text-orange-500 p-2 bg-orange-50 rounded border border-orange-100">
                    تم الوصول للحد الأقصى من العناصر ({maxItems})
                </div>
            )}
        </div>
    );
};

export default ListItemsEditor;

import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { TruckIcon, ArrowRightIcon, PencilIcon, TrashIcon, GlobeAltIcon, PhoneIcon, EnvelopeIcon, KeyIcon, LinkIcon } from '@heroicons/react/24/outline';
import { useAuth } from '../../hooks/useAuthSimple';
import { envConfig } from '../../config/environment';

interface ShippingCompany {
  id: string;
  name: string;
  phone?: string;
  email?: string;
  website?: string;
  apiKey?: string;
  apiUrl?: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

const ShippingCompanyDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [company, setCompany] = useState<ShippingCompany | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCompany();
  }, [id]);

  const fetchCompany = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`${envConfig.backendUrl}/api/v1/shipping-companies/${id}`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      const data = await response.json();
      if (data.success) {
        setCompany(data.data);
      } else {
        setError(data.error || 'لم يتم العثور على الشركة');
      }
    } catch (error) {
      console.error('Error fetching shipping company:', error);
      setError('حدث خطأ أثناء تحميل البيانات');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (confirm('هل أنت متأكد من حذف شركة الشحن؟')) {
      try {
        const token = localStorage.getItem('accessToken');
        const response = await fetch(`${envConfig.backendUrl}/api/v1/shipping-companies/${id}`, {
          method: 'DELETE',
          headers: {
            'Authorization': `Bearer ${token}`
          }
        });
        const data = await response.json();
        if (data.success) {
          navigate('/shipping-companies');
        } else {
          alert(data.error || 'حدث خطأ أثناء الحذف');
        }
      } catch (error) {
        console.error('Error deleting shipping company:', error);
        alert('حدث خطأ أثناء الحذف');
      }
    }
  };

  if (loading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="p-8 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-500">جاري التحميل...</p>
        </div>
      </div>
    );
  }

  if (error || !company) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="bg-white rounded-lg shadow p-8 text-center">
          <TruckIcon className="h-16 w-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">{error || 'لم يتم العثور على الشركة'}</h3>
          <Link to="/shipping-companies" className="text-blue-600 hover:underline">
            العودة لقائمة الشركات
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Header */}
      <div className="flex items-center mb-6">
        <Link to="/shipping-companies" className="flex items-center text-gray-600 hover:text-gray-900 ml-4">
          <ArrowRightIcon className="h-5 w-5 ml-1" />
          العودة للقائمة
        </Link>
      </div>

      {/* Company Card */}
      <div className="bg-white rounded-lg shadow-lg overflow-hidden">
        {/* Header Section */}
        <div className="bg-gradient-to-r from-blue-600 to-blue-800 px-6 py-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <div className="p-3 bg-white bg-opacity-20 rounded-full">
                <TruckIcon className="h-10 w-10 text-white" />
              </div>
              <div className="mr-4">
                <h1 className="text-2xl font-bold text-white">{company.name}</h1>
                <span className={`inline-block px-3 py-1 text-sm rounded-full mt-2 ${
                  company.isActive 
                    ? 'bg-green-400 text-green-900' 
                    : 'bg-red-400 text-red-900'
                }`}>
                  {company.isActive ? 'نشطة' : 'غير نشطة'}
                </span>
              </div>
            </div>
            <div className="flex space-x-3">
              <Link
                to={`/shipping-companies/${company.id}/edit`}
                className="flex items-center px-4 py-2 bg-white text-blue-600 rounded-lg hover:bg-gray-100 transition-colors"
              >
                <PencilIcon className="h-5 w-5 ml-2" />
                تعديل
              </Link>
              <button
                onClick={handleDelete}
                className="flex items-center px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors"
              >
                <TrashIcon className="h-5 w-5 ml-2" />
                حذف
              </button>
            </div>
          </div>
        </div>

        {/* Details Section */}
        <div className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Contact Info */}
            <div className="space-y-4">
              <h3 className="text-lg font-semibold text-gray-900 border-b pb-2">معلومات الاتصال</h3>
              
              {company.phone && (
                <div className="flex items-center">
                  <PhoneIcon className="h-5 w-5 text-gray-400 ml-3" />
                  <div>
                    <p className="text-sm text-gray-500">رقم الهاتف</p>
                    <a href={`tel:${company.phone}`} className="text-blue-600 hover:underline">
                      {company.phone}
                    </a>
                  </div>
                </div>
              )}

              {company.email && (
                <div className="flex items-center">
                  <EnvelopeIcon className="h-5 w-5 text-gray-400 ml-3" />
                  <div>
                    <p className="text-sm text-gray-500">البريد الإلكتروني</p>
                    <a href={`mailto:${company.email}`} className="text-blue-600 hover:underline">
                      {company.email}
                    </a>
                  </div>
                </div>
              )}

              {company.website && (
                <div className="flex items-center">
                  <GlobeAltIcon className="h-5 w-5 text-gray-400 ml-3" />
                  <div>
                    <p className="text-sm text-gray-500">الموقع الإلكتروني</p>
                    <a 
                      href={company.website} 
                      target="_blank" 
                      rel="noopener noreferrer" 
                      className="text-blue-600 hover:underline flex items-center"
                    >
                      {company.website}
                      <LinkIcon className="h-4 w-4 mr-1" />
                    </a>
                  </div>
                </div>
              )}
            </div>

            {/* API Info */}
            <div className="space-y-4">
              <h3 className="text-lg font-semibold text-gray-900 border-b pb-2">إعدادات الربط (API)</h3>
              
              {company.apiKey ? (
                <div className="flex items-center">
                  <KeyIcon className="h-5 w-5 text-gray-400 ml-3" />
                  <div>
                    <p className="text-sm text-gray-500">API Key</p>
                    <p className="font-mono text-sm bg-gray-100 px-2 py-1 rounded">
                      {company.apiKey.substring(0, 20)}...
                    </p>
                  </div>
                </div>
              ) : (
                <p className="text-gray-400 italic">لم يتم إضافة API Key</p>
              )}

              {company.apiUrl && (
                <div className="flex items-center">
                  <LinkIcon className="h-5 w-5 text-gray-400 ml-3" />
                  <div>
                    <p className="text-sm text-gray-500">API URL</p>
                    <code className="text-sm bg-gray-100 px-2 py-1 rounded block mt-1">
                      {company.apiUrl}
                    </code>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Metadata */}
          <div className="mt-8 pt-4 border-t border-gray-200">
            <div className="flex items-center text-sm text-gray-500 space-x-6">
              <span>تم الإنشاء: {new Date(company.createdAt).toLocaleDateString('ar-EG')}</span>
              <span>آخر تحديث: {new Date(company.updatedAt).toLocaleDateString('ar-EG')}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ShippingCompanyDetail;

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { tokenManager } from "../../utils/tokenManager";
import {
  Calendar,
  CreditCard,
  AlertCircle,
  CheckCircle,
  XCircle,
  TrendingUp,
  Clock,
  DollarSign,
  Package,
} from "lucide-react";
import axios from "axios";
import { toast } from "react-hot-toast";
import { buildApiUrl } from "../../utils/urlHelper";

interface PlatformSubscription {
  id: string;
  plan: string;
  monthlyFee: number;
  status: string;
  billingDay: number;
  nextBillingDate: string;
  lastBillingDate?: string;
  failedAttempts: number;
  createdAt: string;
  company: {
    name: string;
    plan: string;
  };
}

interface BillingHistoryItem {
  id: string;
  type: string;
  amount: number;
  description: string;
  status: string;
  createdAt: string;
}

export default function MySubscription() {
  const navigate = useNavigate();
  const [subscription, setSubscription] = useState<PlatformSubscription | null>(
    null,
  );
  const [billingHistory, setBillingHistory] = useState<BillingHistoryItem[]>(
    [],
  );
  const [loading, setLoading] = useState(true);
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [cancelling, setCancelling] = useState(false);

  useEffect(() => {
    fetchSubscription();
    fetchBillingHistory();
  }, []);

  const fetchSubscription = async () => {
    try {
      const token = tokenManager.getAccessToken();
      if (!token) {
        navigate("/auth/login");
        return;
      }

      const response = await axios.get(buildApiUrl("platform-subscription"), {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (response.data.success) {
        setSubscription(response.data.data);
      }
    } catch (error: any) {
      if (error.response?.status === 404) {
        toast.error("لا يوجد اشتراك نشط");
      } else {
        toast.error("خطأ في جلب بيانات الاشتراك");
      }
    } finally {
      setLoading(false);
    }
  };

  const fetchBillingHistory = async () => {
    try {
      const token = tokenManager.getAccessToken();
      if (!token) return;

      const response = await axios.get(
        buildApiUrl(
          "platform-subscription/billing-history?type=PLATFORM_FEE&limit=10",
        ),
        { headers: { Authorization: `Bearer ${token}` } },
      );

      if (response.data.success) {
        setBillingHistory(response.data.data);
      }
    } catch {}
  };

  const handleCancelSubscription = async () => {
    const token = tokenManager.getAccessToken();
    if (!token) return;

    try {
      setCancelling(true);
      const response = await axios.post(
        buildApiUrl("platform-subscription/cancel"),
        {},
        { headers: { Authorization: `Bearer ${token}` } },
      );

      if (response.data.success) {
        toast.success("تم إلغاء الاشتراك بنجاح");
        setShowCancelModal(false);
        fetchSubscription();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "خطأ في إلغاء الاشتراك");
    } finally {
      setCancelling(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const badges: Record<string, { color: string; icon: any; text: string }> = {
      ACTIVE: {
        color:
          "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400",
        icon: CheckCircle,
        text: "نشط",
      },
      SUSPENDED: {
        color:
          "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400",
        icon: AlertCircle,
        text: "معلق",
      },
      CANCELLED: {
        color: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400",
        icon: XCircle,
        text: "ملغي",
      },
      PAST_DUE: {
        color:
          "bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400",
        icon: AlertCircle,
        text: "متأخر",
      },
    };

    const defaultBadge = {
      color: "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400",
      icon: AlertCircle,
      text: "غير معروف",
    };
    const badge = badges[status] || defaultBadge;
    const Icon = badge.icon;

    return (
      <span
        className={`${badge.color} px-3 py-1 rounded-full text-sm font-semibold flex items-center gap-1 w-fit`}
      >
        <Icon size={16} />
        {badge.text}
      </span>
    );
  };

  const getPlanName = (plan: string) => {
    const names: Record<string, string> = {
      BASIC: "الخطة الأساسية",
      PRO: "الخطة الاحترافية",
      ENTERPRISE: "خطة المؤسسات",
    };
    return names[plan] || plan;
  };

  const getTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      PLATFORM_FEE: "رسوم المنصة",
      APP_SUBSCRIPTION: "اشتراك أداة",
      APP_USAGE: "استخدام أداة",
      WALLET_RECHARGE: "شحن المحفظة",
      REFUND: "استرداد",
      ADJUSTMENT: "تعديل",
    };
    return labels[type] || type;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (!subscription) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-8 max-w-md text-center">
          <Package className="mx-auto mb-4 text-gray-400" size={64} />
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
            لا يوجد اشتراك نشط
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mb-6">
            اختر خطة مناسبة لبدء استخدام المنصة
          </p>
          <button
            onClick={() => navigate("/subscription/plans")}
            className="bg-blue-600 text-white px-6 py-3 rounded-xl font-semibold hover:bg-blue-700 transition-colors"
          >
            عرض الخطط المتاحة
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            اشتراكي في المنصة
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-2">
            إدارة اشتراكك وعرض سجل الفواتير
          </p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Subscription Card */}
        <div className="bg-gradient-to-br from-blue-600 to-purple-600 text-white rounded-2xl p-8 mb-8 shadow-xl">
          <div className="flex items-start justify-between mb-6">
            <div>
              <h2 className="text-2xl font-bold mb-2">
                {getPlanName(subscription.plan)}
              </h2>
              {getStatusBadge(subscription.status)}
            </div>
            <div className="text-right">
              <div className="text-4xl font-bold">
                {subscription.monthlyFee} ج
              </div>
              <div className="text-blue-100">شهرياً</div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-white/10 backdrop-blur-sm rounded-xl p-4">
              <div className="flex items-center gap-2 text-blue-100 mb-2">
                <Calendar size={20} />
                <span className="text-sm">الفاتورة القادمة</span>
              </div>
              <div className="text-xl font-bold">
                {new Date(subscription.nextBillingDate).toLocaleDateString(
                  "ar-EG",
                )}
              </div>
            </div>

            <div className="bg-white/10 backdrop-blur-sm rounded-xl p-4">
              <div className="flex items-center gap-2 text-blue-100 mb-2">
                <Clock size={20} />
                <span className="text-sm">يوم الخصم</span>
              </div>
              <div className="text-xl font-bold">
                اليوم {subscription.billingDay} من كل شهر
              </div>
            </div>

            <div className="bg-white/10 backdrop-blur-sm rounded-xl p-4">
              <div className="flex items-center gap-2 text-blue-100 mb-2">
                <CreditCard size={20} />
                <span className="text-sm">آخر فاتورة</span>
              </div>
              <div className="text-xl font-bold">
                {subscription.lastBillingDate
                  ? new Date(subscription.lastBillingDate).toLocaleDateString(
                      "ar-EG",
                    )
                  : "لا توجد"}
              </div>
            </div>
          </div>

          <div className="mt-6 flex gap-4">
            <button
              onClick={() => navigate("/subscription/plans")}
              className="bg-white text-blue-600 px-6 py-3 rounded-xl font-semibold hover:bg-blue-50 transition-colors flex items-center gap-2"
            >
              <TrendingUp size={20} />
              ترقية الخطة
            </button>
            <button
              onClick={() => navigate("/subscription/usage")}
              className="bg-white/20 backdrop-blur-sm text-white px-6 py-3 rounded-xl font-semibold hover:bg-white/30 transition-colors"
            >
              عرض الاستخدام
            </button>
            {subscription.status === "ACTIVE" && (
              <button
                onClick={() => setShowCancelModal(true)}
                className="bg-red-500/20 backdrop-blur-sm text-white px-6 py-3 rounded-xl font-semibold hover:bg-red-500/30 transition-colors"
              >
                إلغاء الاشتراك
              </button>
            )}
          </div>
        </div>

        {/* Billing History */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
          <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
            <DollarSign size={24} />
            سجل الفواتير
          </h2>

          {billingHistory.length === 0 ? (
            <div className="text-center py-8 text-gray-500 dark:text-gray-400">
              لا توجد فواتير بعد
            </div>
          ) : (
            <div className="space-y-4">
              {billingHistory.map((item) => (
                <div
                  key={item.id}
                  className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-lg"
                >
                  <div className="flex items-center gap-4">
                    <div
                      className={`p-2 rounded-lg ${
                        item.status === "SUCCESS"
                          ? "bg-green-100 dark:bg-green-900/30 text-green-600"
                          : "bg-red-100 dark:bg-red-900/30 text-red-600"
                      }`}
                    >
                      {item.status === "SUCCESS" ? (
                        <CheckCircle size={20} />
                      ) : (
                        <XCircle size={20} />
                      )}
                    </div>
                    <div>
                      <div className="font-semibold text-gray-900 dark:text-white">
                        {item.description}
                      </div>
                      <div className="text-sm text-gray-600 dark:text-gray-400">
                        {getTypeLabel(item.type)} •{" "}
                        {new Date(item.createdAt).toLocaleDateString("ar-EG")}
                      </div>
                    </div>
                  </div>
                  <div
                    className={`text-lg font-bold ${
                      item.status === "SUCCESS"
                        ? "text-green-600"
                        : "text-red-600"
                    }`}
                  >
                    {item.amount} ج
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Cancel Modal */}
      {showCancelModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 max-w-md w-full">
            <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
              تأكيد إلغاء الاشتراك
            </h3>
            <p className="text-gray-700 dark:text-gray-300 mb-6">
              هل أنت متأكد من إلغاء اشتراكك؟ سيتم إيقاف الخدمة في نهاية الفترة
              المدفوعة.
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setShowCancelModal(false)}
                className="flex-1 bg-gray-200 dark:bg-gray-700 text-gray-900 dark:text-white px-4 py-2 rounded-lg font-semibold hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors"
              >
                إلغاء
              </button>
              <button
                onClick={handleCancelSubscription}
                disabled={cancelling}
                className="flex-1 bg-red-600 text-white px-4 py-2 rounded-lg font-semibold hover:bg-red-700 transition-colors disabled:bg-red-400"
              >
                {cancelling ? "جاري الإلغاء..." : "تأكيد الإلغاء"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { tokenManager } from "../../utils/tokenManager";
import {
  Check,
  Crown,
  Zap,
  Users,
  Package,
  ShoppingCart,
  MessageSquare,
  Brain,
  TrendingUp,
  Shield,
} from "lucide-react";
import axios from "axios";
import { toast } from "react-hot-toast";
import { buildApiUrl } from "../../utils/urlHelper";

interface PlanLimit {
  id: string;
  plan: string;
  maxEmployees: number;
  maxProducts: number;
  maxOrdersPerMonth: number;
  maxCustomers: number;
  maxStorageGB: number;
  maxMessagesPerMonth: number;
  maxAIChatsPerMonth: number;
  hasAdvancedReports: boolean;
  hasAPIAccess: boolean;
  hasPrioritySupport: boolean;
  hasWhiteLabel: boolean;
  hasCustomDomain: boolean;
  monthlyFee: number;
  features: string[];
}

const DEFAULT_PLAN_LIMITS: Omit<
  PlanLimit,
  "id" | "plan" | "monthlyFee" | "features"
> = {
  maxEmployees: -1,
  maxProducts: -1,
  maxOrdersPerMonth: -1,
  maxCustomers: -1,
  maxStorageGB: -1,
  maxMessagesPerMonth: -1,
  maxAIChatsPerMonth: -1,
  hasAdvancedReports: false,
  hasAPIAccess: false,
  hasPrioritySupport: false,
  hasWhiteLabel: false,
  hasCustomDomain: false,
};

const normalizePlan = (
  plan: Partial<PlanLimit> & { id: string; plan: string },
) => ({
  ...DEFAULT_PLAN_LIMITS,
  ...plan,
  monthlyFee: Number(plan.monthlyFee ?? 0),
  features: Array.isArray(plan.features) ? plan.features : [],
});

export default function PlatformPlans() {
  const navigate = useNavigate();
  const [plans, setPlans] = useState<PlanLimit[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentPlan, setCurrentPlan] = useState<string>("BASIC");
  const [upgrading, setUpgrading] = useState<string | null>(null);

  useEffect(() => {
    fetchPlans();
    fetchCurrentSubscription();
  }, []);

  const fetchPlans = async () => {
    try {
      const token = tokenManager.getAccessToken();
      const response = await axios.get(
        buildApiUrl("platform-subscription/plans"),
        {
          headers: token ? { Authorization: `Bearer ${token}` } : {},
        },
      );

      const normalizedPlans = Array.isArray(response.data.data)
        ? response.data.data.map(normalizePlan)
        : [];

      setPlans(normalizedPlans);
    } catch (error) {
      toast.error("خطأ في جلب الخطط");
    } finally {
      setLoading(false);
    }
  };

  const fetchCurrentSubscription = async () => {
    try {
      const token = tokenManager.getAccessToken();
      if (!token) return;

      const response = await axios.get(buildApiUrl("platform-subscription"), {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (response.data.success) {
        setCurrentPlan(response.data.data.plan);
      }
    } catch {}
  };

  const handleUpgrade = async (planName: string) => {
    const token = tokenManager.getAccessToken();
    if (!token) {
      toast.error("يرجى تسجيل الدخول أولاً");
      navigate("/auth/login");
      return;
    }

    if (planName === currentPlan) {
      toast.error("أنت مشترك بالفعل في هذه الخطة");
      return;
    }

    try {
      setUpgrading(planName);
      const response = await axios.post(
        buildApiUrl("platform-subscription/upgrade"),
        { newPlan: planName },
        { headers: { Authorization: `Bearer ${token}` } },
      );

      if (response.data.success) {
        toast.success("تم ترقية الخطة بنجاح!");
        setCurrentPlan(planName);
        fetchCurrentSubscription();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "خطأ في ترقية الخطة");
    } finally {
      setUpgrading(null);
    }
  };

  const getPlanIcon = (plan: string) => {
    if (plan === "BASIC") return <Package className="w-8 h-8" />;
    if (plan === "PRO") return <Zap className="w-8 h-8" />;
    return <Crown className="w-8 h-8" />;
  };

  const getPlanColor = (plan: string) => {
    if (plan === "BASIC") return "from-blue-500 to-blue-600";
    if (plan === "PRO") return "from-purple-500 to-purple-600";
    return "from-yellow-500 to-yellow-600";
  };

  const formatLimit = (value?: number | null) => {
    if (value === undefined || value === null || Number.isNaN(Number(value))) {
      return "غير متاح";
    }

    return Number(value) === -1
      ? "غير محدود"
      : Number(value).toLocaleString("ar-EG");
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <h1 className="text-4xl font-bold mb-4">اختر الخطة المناسبة لك</h1>
          <p className="text-xl text-blue-100">
            خطط مرنة تناسب جميع أحجام الأعمال
          </p>
        </div>
      </div>

      {/* Plans Grid */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {plans.map((plan) => {
            const isCurrentPlan = plan.plan === currentPlan;
            const isUpgrading = upgrading === plan.plan;

            return (
              <div
                key={plan.id}
                className={`relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl overflow-hidden transition-transform hover:scale-105 ${
                  isCurrentPlan ? "ring-4 ring-green-500" : ""
                }`}
              >
                {/* Plan Header */}
                <div
                  className={`bg-gradient-to-r ${getPlanColor(plan.plan)} text-white p-6`}
                >
                  <div className="flex items-center justify-between mb-4">
                    {getPlanIcon(plan.plan)}
                    {isCurrentPlan && (
