                    {plan.plan === "ENTERPRISE" && "خطة المؤسسات"}
                  </h3>
                  <div className="flex items-baseline gap-2">
                    <span className="text-4xl font-bold">
                      {plan.monthlyFee}
                    </span>
                    <span className="text-xl">ج / شهر</span>
                  </div>
