              <h3 className="font-bold text-gray-900 dark:text-white mb-2">
                هل يوجد دعم فني؟
              </h3>
              <p className="text-gray-700 dark:text-gray-300">
                نعم، جميع الخطط تشمل دعم فني. خطة PRO و ENTERPRISE تحصل على دعم
                أولوية.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { tokenManager } from "../../utils/tokenManager";
import {
  Users,
  Package,
  ShoppingCart,
  MessageSquare,
  Brain,
  HardDrive,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
} from "lucide-react";
import axios from "axios";
import { toast } from "react-hot-toast";
import { buildApiUrl } from "../../utils/urlHelper";

interface UsageData {
  current: number;
  limit: number;
  percentage: number;
}

interface UsageStats {
  plan: string;
  subscription: any;
  limits: any;
  usage: {
    employees: UsageData;
    products: UsageData;
    ordersThisMonth: UsageData;
    customers: UsageData;
  };
}

const DEFAULT_LIMITS = {
  maxEmployees: -1,
  maxProducts: -1,
  maxOrdersPerMonth: -1,
  maxCustomers: -1,
  maxStorageGB: -1,
  maxMessagesPerMonth: -1,
  maxAIChatsPerMonth: -1,
  hasAdvancedReports: false,
  hasAPIAccess: false,
  hasPrioritySupport: false,
  hasWhiteLabel: false,
  hasCustomDomain: false,
};

export default function UsageStats() {
  const navigate = useNavigate();
  const [stats, setStats] = useState<UsageStats | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchUsageStats();
  }, []);

  const fetchUsageStats = async () => {
    try {
      const token = tokenManager.getAccessToken();
      if (!token) {
        navigate("/auth/login");
        return;
      }

      const response = await axios.get(
        buildApiUrl("platform-subscription/usage-stats"),
        {
          headers: { Authorization: `Bearer ${token}` },
        },
      );

      if (response.data.success) {
        setStats(response.data.data);
      }
    } catch (error) {
      toast.error("خطأ في جلب إحصائيات الاستخدام");
    } finally {
      setLoading(false);
    }
  };

  const getUsageColor = (percentage: number) => {
    if (percentage >= 90) return "text-red-600 bg-red-100 dark:bg-red-900/30";
    if (percentage >= 75)
      return "text-yellow-600 bg-yellow-100 dark:bg-yellow-900/30";
    return "text-green-600 bg-green-100 dark:bg-green-900/30";
  };

  const getProgressColor = (percentage: number) => {
    if (percentage >= 90) return "bg-red-600";
    if (percentage >= 75) return "bg-yellow-600";
    return "bg-green-600";
  };

  const formatLimit = (value?: number | null) => {
    if (value === undefined || value === null || Number.isNaN(Number(value))) {
      return "غير متاح";
    }

    return Number(value) === -1
      ? "غير محدود"
      : Number(value).toLocaleString("ar-EG");
  };

  const UsageCard = ({
    title,
    icon: Icon,
    usage,
    iconColor,
  }: {
    title: string;
    icon: any;
    usage: UsageData;
    iconColor: string;
  }) => {
    const isUnlimited = usage.limit === -1;
    const percentage = isUnlimited ? 0 : usage.percentage;
    const isNearLimit = percentage >= 75 && !isUnlimited;

    return (
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className={`p-3 rounded-lg ${iconColor}`}>
              <Icon size={24} />
            </div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              {title}
            </h3>
          </div>
          {isNearLimit && (
            <AlertTriangle className="text-yellow-600" size={24} />
          )}
        </div>

        <div className="space-y-3">
          <div className="flex items-baseline justify-between">
            <span className="text-3xl font-bold text-gray-900 dark:text-white">
              {usage.current.toLocaleString("ar-EG")}
            </span>
            <span className="text-gray-600 dark:text-gray-400">
              من {formatLimit(usage.limit)}
            </span>
          </div>

          {!isUnlimited && (
            <>
              <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-3 overflow-hidden">
                <div
                  className={`h-full ${getProgressColor(percentage)} transition-all duration-500`}
                  style={{ width: `${Math.min(percentage, 100)}%` }}
                />
              </div>

              <div className="flex items-center justify-between text-sm">
                <span
                  className={`font-semibold px-2 py-1 rounded ${getUsageColor(percentage)}`}
                >
                  {percentage.toFixed(1)}% مستخدم
                </span>
                {isNearLimit && (
                  <span className="text-yellow-600 font-semibold">
                    قريب من الحد الأقصى
                  </span>
                )}
              </div>
            </>
          )}

          {isUnlimited && (
            <div className="flex items-center gap-2 text-green-600">
              <CheckCircle size={20} />
              <span className="font-semibold">استخدام غير محدود</span>
            </div>
          )}
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (!stats) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-8 max-w-md text-center">
          <AlertTriangle className="mx-auto mb-4 text-yellow-600" size={64} />
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
            لا توجد بيانات استخدام
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mb-6">
            تأكد من وجود اشتراك نشط
          </p>
          <button
            onClick={() => navigate("/subscription/plans")}
            className="bg-blue-600 text-white px-6 py-3 rounded-xl font-semibold hover:bg-blue-700 transition-colors"
          >
            عرض الخطط
          </button>
        </div>
      </div>
    );
  }

  const getPlanName = (plan: string) => {
    const names: Record<string, string> = {
      BASIC: "الخطة الأساسية",
      PRO: "الخطة الاحترافية",
      ENTERPRISE: "خطة المؤسسات",
    };
    return names[plan] || plan;
  };

  const limits = stats?.limits
    ? { ...DEFAULT_LIMITS, ...stats.limits }
    : DEFAULT_LIMITS;

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
                إحصائيات الاستخدام
              </h1>
              <p className="text-gray-600 dark:text-gray-400 mt-2">
                {getPlanName(stats.plan)} • تتبع استخدامك مقابل حدود الخطة
              </p>
            </div>
            <button
              onClick={() => navigate("/subscription/plans")}
              className="bg-blue-600 text-white px-6 py-3 rounded-xl font-semibold hover:bg-blue-700 transition-colors flex items-center gap-2"
            >
              <TrendingUp size={20} />
              ترقية الخطة
            </button>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Usage Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
          <UsageCard
            title="الموظفين"
            icon={Users}
            usage={stats.usage.employees}
            iconColor="bg-blue-100 dark:bg-blue-900/30 text-blue-600"
          />
          <UsageCard
            title="المنتجات"
            icon={Package}
            usage={stats.usage.products}
            iconColor="bg-purple-100 dark:bg-purple-900/30 text-purple-600"
          />
          <UsageCard
            title="الطلبات هذا الشهر"
            icon={ShoppingCart}
            usage={stats.usage.ordersThisMonth}
            iconColor="bg-green-100 dark:bg-green-900/30 text-green-600"
          />
          <UsageCard
            title="العملاء"
            icon={Users}
            usage={stats.usage.customers}
            iconColor="bg-yellow-100 dark:bg-yellow-900/30 text-yellow-600"
          />
        </div>

        {/* Plan Limits Info */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
          <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6">
            حدود الخطة الحالية
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                <div className="flex items-center gap-3">
                  <MessageSquare className="text-blue-600" size={20} />
                  <span className="text-gray-900 dark:text-white">
                    الرسائل الشهرية
                  </span>
                </div>
                <span className="font-bold text-gray-900 dark:text-white">
                  {formatLimit(limits.maxMessagesPerMonth)}
                </span>
              </div>

              <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                <div className="flex items-center gap-3">
                  <Brain className="text-purple-600" size={20} />
                  <span className="text-gray-900 dark:text-white">
                    محادثات AI الشهرية
                  </span>
                </div>
                <span className="font-bold text-gray-900 dark:text-white">
                  {formatLimit(limits.maxAIChatsPerMonth)}
                </span>
              </div>

              <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                <div className="flex items-center gap-3">
                  <HardDrive className="text-green-600" size={20} />
                  <span className="text-gray-900 dark:text-white">
                    مساحة التخزين
                  </span>
                </div>
                <span className="font-bold text-gray-900 dark:text-white">
                  {formatLimit(limits.maxStorageGB)} GB
                </span>
              </div>
            </div>

            <div className="space-y-4">
              <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                <h3 className="font-semibold text-gray-900 dark:text-white mb-2">
                  الميزات المتاحة
                </h3>
                <div className="space-y-2">
                  {limits.hasAdvancedReports && (
                    <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                      <CheckCircle size={16} className="text-green-600" />
                      <span>تقارير متقدمة</span>
                    </div>
                  )}
                  {limits.hasAPIAccess && (
                    <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                      <CheckCircle size={16} className="text-green-600" />
                      <span>API Access</span>
                    </div>
                  )}
                  {limits.hasPrioritySupport && (
                    <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                      <CheckCircle size={16} className="text-green-600" />
                      <span>دعم أولوية</span>
                    </div>
                  )}
                  {limits.hasWhiteLabel && (
                    <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                      <CheckCircle size={16} className="text-green-600" />
                      <span>White Label</span>
                    </div>
                  )}
                  {limits.hasCustomDomain && (
                    <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                      <CheckCircle size={16} className="text-green-600" />
                      <span>نطاق مخصص</span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Upgrade CTA */}
        {stats.plan !== "ENTERPRISE" && (
          <div className="mt-8 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl p-8 text-center">
            <h2 className="text-2xl font-bold mb-2">هل تحتاج المزيد؟</h2>
            <p className="text-blue-100 mb-6">
              قم بترقية خطتك للحصول على حدود أعلى وميزات إضافية
            </p>
            <button
              onClick={() => navigate("/subscription/plans")}
              className="bg-white text-blue-600 px-8 py-3 rounded-xl font-semibold hover:bg-blue-50 transition-colors inline-flex items-center gap-2"
            >
              <TrendingUp size={20} />
              عرض خطط الترقية
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import {
  DollarSign,
  TrendingUp,
  Users,
  AlertTriangle,
  Calendar,
  PieChart,
  BarChart3,
  RefreshCw,
  ArrowUpRight,
  ShieldCheck,
} from "lucide-react";
import { apiClient } from "../../services/apiClient";
import { toast } from "react-hot-toast";

interface BillingData {
  totalRevenue: number;
  mrr: number;
  activeSubscriptions: number;
  revenueByType: any[];
  revenueByPlan: any[];
  failedPayments: any[];
}

export default function BillingOverview() {
  const [data, setData] = useState<BillingData | null>(null);
  const [loading, setLoading] = useState(true);
  const [dateRange, setDateRange] = useState("30");
  const [retryingIds, setRetryingIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchBillingData();
  }, [dateRange]);

  const fetchBillingData = async () => {
    try {
      setLoading(true);
      const endDate = new Date();
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - parseInt(dateRange));

      const response = await apiClient.get(
        "/super-admin/platform/billing-overview",
        {
          params: {
            startDate: startDate.toISOString(),
            endDate: endDate.toISOString(),
          },
        },
      );

      if (response.data.success) {
        setData(response.data.data);
      }
    } catch (error) {
      console.error("Error fetching billing data:", error);
      toast.error("خطأ في جلب بيانات الفواتير");
    } finally {
      setLoading(false);
    }
  };

  const handleRetryPayment = async (paymentId: string) => {
    try {
      setRetryingIds((prev) => new Set(prev).add(paymentId));
      const response = await apiClient.post(
        `/super-admin/platform/retry-failed-payment/${paymentId}`,
      );

      if (response.data.success) {
        toast.success(response.data.message || "تمت إعادة محاولة الدفع بنجاح");
        fetchBillingData();
      }
    } catch (error: any) {
      console.error("Error retrying payment:", error);
      toast.error(
        error.response?.data?.message || "خطأ في إعادة محاولة الدفع",
      );
    } finally {
      setRetryingIds((prev) => {
        const next = new Set(prev);
        next.delete(paymentId);
        return next;
      });
    }
  };

  const toNumber = (value: any): number => {
    if (value === null || value === undefined) return 0;
    if (typeof value === "number") return value;
    return parseFloat(value.toString());
  };

  const getTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      PLATFORM_FEE: "رسوم المنصة",
      APP_SUBSCRIPTION: "اشتراكات الأدوات",
      APP_USAGE: "استخدام الأدوات",
      WALLET_RECHARGE: "شحن المحفظة",
      REFUND: "استرداد",
      ADJUSTMENT: "تعديل",
    };
    return labels[type] || type;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <div className="text-center">
          <AlertTriangle className="mx-auto mb-4 text-yellow-600" size={64} />
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
            لا توجد بيانات
          </h2>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
                نظرة عامة على الفواتير
              </h1>
              <p className="text-gray-600 dark:text-gray-400 mt-2">
                تحليلات الإيرادات والفواتير
              </p>
            </div>
            <div>
              <select
                value={dateRange}
                onChange={(e) => setDateRange(e.target.value)}
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
              >
                <option value="7">آخر 7 أيام</option>
                <option value="30">آخر 30 يوم</option>
                <option value="90">آخر 90 يوم</option>
                <option value="365">آخر سنة</option>
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Key Metrics */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="relative overflow-hidden bg-gradient-to-br from-blue-600 via-blue-700 to-indigo-800 text-white rounded-2xl p-6 shadow-xl transition-all duration-300 hover:scale-[1.02] group">
            <div className="absolute top-0 right-0 -mr-8 -mt-8 w-32 h-32 bg-white opacity-10 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-500"></div>
            <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="p-3 bg-white/20 rounded-xl backdrop-blur-md">
                <DollarSign size={24} />
              </div>
              <div className="flex items-center gap-1 text-xs font-semibold bg-white/20 px-2 py-1 rounded-full">
                <TrendingUp size={12} />
                <span>+12%</span>
              </div>
            </div>
            <p className="text-blue-100 text-sm font-medium mb-1 relative z-10">
              إجمالي الإيرادات
            </p>
            <p className="text-3xl font-extrabold relative z-10">
              {toNumber(data.totalRevenue).toLocaleString("ar-EG")} ج
            </p>
          </div>

          <div className="relative overflow-hidden bg-gradient-to-br from-purple-600 via-purple-700 to-fuchsia-800 text-white rounded-2xl p-6 shadow-xl transition-all duration-300 hover:scale-[1.02] group">
            <div className="absolute top-0 right-0 -mr-8 -mt-8 w-32 h-32 bg-white opacity-10 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-500"></div>
            <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="p-3 bg-white/20 rounded-xl backdrop-blur-md">
                <Calendar size={24} />
              </div>
              <div className="flex items-center gap-1 text-xs font-semibold bg-white/20 px-2 py-1 rounded-full">
                <ArrowUpRight size={12} />
                <span>MRR</span>
              </div>
            </div>
            <p className="text-purple-100 text-sm font-medium mb-1 relative z-10">
              الإيرادات الشهرية المكررة
            </p>
            <p className="text-3xl font-extrabold relative z-10">
              {toNumber(data.mrr).toLocaleString("ar-EG")} ج
            </p>
          </div>

          <div className="relative overflow-hidden bg-gradient-to-br from-emerald-500 via-emerald-600 to-teal-700 text-white rounded-2xl p-6 shadow-xl transition-all duration-300 hover:scale-[1.02] group">
            <div className="absolute top-0 right-0 -mr-8 -mt-8 w-32 h-32 bg-white opacity-10 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-500"></div>
            <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="p-3 bg-white/20 rounded-xl backdrop-blur-md">
                <Users size={24} />
              </div>
              <div className="flex items-center gap-1 text-xs font-semibold bg-white/20 px-2 py-1 rounded-full">
                <ShieldCheck size={12} />
                <span>Active</span>
              </div>
            </div>
            <p className="text-emerald-100 text-sm font-medium mb-1 relative z-10">
              الاشتراكات النشطة
            </p>
            <p className="text-3xl font-extrabold relative z-10">
              {data.activeSubscriptions}
            </p>
          </div>

          <div className="relative overflow-hidden bg-gradient-to-br from-rose-500 via-rose-600 to-red-700 text-white rounded-2xl p-6 shadow-xl transition-all duration-300 hover:scale-[1.02] group">
            <div className="absolute top-0 right-0 -mr-8 -mt-8 w-32 h-32 bg-white opacity-10 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-500"></div>
            <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="p-3 bg-white/20 rounded-xl backdrop-blur-md">
                <AlertTriangle size={24} />
              </div>
              <div className="flex items-center gap-1 text-xs font-semibold bg-white/20 px-2 py-1 rounded-full">
                <RefreshCw size={12} className={data.failedPayments.length > 0 ? "animate-spin-slow" : ""} />
                <span>Needs Redo</span>
              </div>
            </div>
            <p className="text-rose-100 text-sm font-medium mb-1 relative z-10">
              الدفعات الفاشلة
            </p>
            <p className="text-3xl font-extrabold relative z-10">
              {data.failedPayments.length}
            </p>
          </div>
        </div>

        {/* Revenue by Type */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
              <PieChart size={24} />
              الإيرادات حسب النوع
            </h2>
            <div className="space-y-4">
              {data.revenueByType.map((item, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-lg"
                >
                  <div>
                    <div className="font-semibold text-gray-900 dark:text-white">
                      {getTypeLabel(item.type)}
                    </div>
                    <div className="text-sm text-gray-600 dark:text-gray-400">
                      {item._count} عملية
                    </div>
                  </div>
                  <div className="text-lg font-bold text-green-600">
                    {toNumber(item._sum.amount).toLocaleString("ar-EG")} ج
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
              <BarChart3 size={24} />
              الإيرادات حسب الخطة
            </h2>
            <div className="space-y-4">
              {data.revenueByPlan.map((item, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-lg"
                >
                  <div>
                    <div className="font-semibold text-gray-900 dark:text-white">
                      {item.plan}
                    </div>
                    <div className="text-sm text-gray-600 dark:text-gray-400">
                      {item._count} اشتراك
                    </div>
                  </div>
                  <div className="text-lg font-bold text-purple-600">
                    {toNumber(item._sum.monthlyFee).toLocaleString("ar-EG")}{" "}
                    ج/شهر
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Failed Payments */}
        {data.failedPayments.length > 0 && (
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
              <AlertTriangle size={24} className="text-red-600" />
              الدفعات الفاشلة
            </h2>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 dark:bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                      الشركة
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                      النوع
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                      المبلغ
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                      التاريخ
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                      الوصف
                    </th>
                    <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">
                      إجراءات
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                  {data.failedPayments.map((payment) => (
                    <tr
                      key={payment.id}
                      className="hover:bg-gray-50/80 dark:hover:bg-gray-700/50 transition-colors"
                    >
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center text-red-600 font-bold shrink-0">
                            {payment.company.name.charAt(0)}
                          </div>
                          <div>
                            <div className="font-bold text-gray-900 dark:text-white">
                              {payment.company.name}
                            </div>
                            <div className="text-xs text-gray-500 dark:text-gray-400">
                              {payment.company.email}
                            </div>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="px-2 py-1 rounded-md bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 text-xs font-medium border border-gray-200 dark:border-gray-600">
                          {getTypeLabel(payment.type)}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-red-600 font-bold text-lg">
                          {toNumber(payment.amount).toLocaleString("ar-EG")} ج
                        </span>
                      </td>
                      <td className="px-6 py-4 text-gray-700 dark:text-gray-300 text-sm">
                        {new Date(payment.createdAt).toLocaleDateString(
                          "ar-EG",
                        )}
                      </td>
                      <td className="px-6 py-4 text-gray-500 dark:text-gray-400 text-sm max-w-xs truncate">
                        {payment.description}
                      </td>
                      <td className="px-6 py-4 text-center">
                        <button
                          onClick={() => handleRetryPayment(payment.id)}
                          disabled={retryingIds.has(payment.id)}
                          className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed group font-medium"
                        >
                          {retryingIds.has(payment.id) ? (
                            <RefreshCw className="w-4 h-4 animate-spin" />
                          ) : (
                            <RefreshCw className="w-4 h-4 group-hover:rotate-180 transition-transform duration-500" />
                          )}
                          <span>إعادة المحاولة</span>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { buildApiUrl } from "../../utils/urlHelper";
import tokenManager from "../../utils/tokenManager";
import {
  ServerIcon,
  PlayIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowPathIcon,
  CommandLineIcon,
  ArrowDownTrayIcon,
  InformationCircleIcon,
} from "@heroicons/react/24/outline";

interface MigrationProgress {
  step: string;
  message: string;
  users: { total: number; imported: number; skipped: number };
  teamMembers: { total: number; imported: number; skipped: number };
  projects: { total: number; imported: number; skipped: number };
  releases: { total: number; imported: number; skipped: number };
  tasks: { total: number; imported: number; skipped: number };
  percentage: number;
}

interface LogEntry {
  timestamp: string;
  message: string;
  level: "info" | "warn" | "error";
}

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const DatabaseMigration: React.FC = () => {
  const [sourceUrl, setSourceUrl] = useState(
    "mysql://u339372869_test2:0165676135Aa%40A@92.113.22.70:3306/u339372869_test2?charset=utf8mb4&collation=utf8mb4_unicode_ci",
  );
  const [testing, setTesting] = useState(false);
  const [migrating, setMigrating] = useState(false);
  const [jobId, setJobId] = useState<string | null>(null);
  const [progress, setProgress] = useState<MigrationProgress | null>(null);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const logEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    logEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [logs]);

  // Polling for status if a job is active
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (migrating && jobId) {
      interval = setInterval(fetchJobStatus, 2000);
    }
    return () => clearInterval(interval);
  }, [migrating, jobId]);

  const fetchJobStatus = async () => {
    if (!jobId) return;
    try {
      const response = await fetch(
        buildApiUrl(`super-admin/db-migration/status/${jobId}`),
        {
          headers: getAuthHeaders(),
        },
      );
      const data = await response.json();
      if (data.success) {
        setProgress(data.data.progress);
        setLogs(data.data.logs);
        if (data.data.status === "completed") {
          setMigrating(false);
          setSuccess("تم الانتهاء من عملية الاستيراد بنجاح!");
        } else if (data.data.status === "failed") {
          setMigrating(false);
          setError(`فشلت العملية: ${data.data.error}`);
        }
      }
    } catch (err) {
      console.error("Failed to fetch status", err);
    }
  };

  const testConnection = async () => {
    setTesting(true);
    setError(null);
    setSuccess(null);
    try {
      const response = await fetch(
        buildApiUrl("super-admin/db-migration/test-connection"),
        {
          method: "POST",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ url: sourceUrl }),
        },
      );
      const data = await response.json();
      if (data.success) {
        setSuccess("تم الاتصال بقاعدة البيانات بنجاح!");
      } else {
        setError(data.message || "فشل الاتصال");
      }
    } catch (err) {
      setError("خطأ في الاتصال بالخادم");
    } finally {
      setTesting(false);
    }
  };

  const startMigration = async () => {
    if (
      !window.confirm(
        "هل أنت متأكد من بدء عملية الاستيراد؟ قد يستغرق ذلك بعض الوقت.",
      )
    )
      return;

    setMigrating(true);
    setError(null);
    setSuccess(null);
    setLogs([]);
    try {
      const response = await fetch(
        buildApiUrl("super-admin/db-migration/start"),
        {
          method: "POST",
          headers: getAuthHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ url: sourceUrl }),
        },
      );
      const data = await response.json();
      if (data.success) {
        setJobId(data.data.jobId);
      } else {
        setError(data.message || "فشل بدء العملية");
        setMigrating(false);
      }
    } catch (err) {
      setError("خطأ في الاتصال بالخادم");
      setMigrating(false);
    }
  };

  return (
    <div className="space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 flex items-center gap-2">
            <ServerIcon className="h-8 w-8 text-indigo-500" />
            استيراد بيانات التطوير
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            نقل المهام والمشاريع من قاعدة بيانات خارجية
          </p>
        </div>
      </div>

      {/* Configuration Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4 flex items-center gap-2">
          <CommandLineIcon className="h-5 w-5 text-indigo-500" />
          إعدادات المصدر
        </h3>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              رابط الاتصال (Connection URL)
            </label>
            <input
              type="text"
              value={sourceUrl}
              onChange={(e) => setSourceUrl(e.target.value)}
              disabled={migrating}
              placeholder="mysql://user:pass@host:port/db"
              className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-gray-100 font-mono text-sm"
            />
          </div>

          <div className="flex gap-3">
            <button
              onClick={testConnection}
              disabled={testing || migrating}
              className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 transition-colors disabled:opacity-50"
            >
              {testing ? (
                <ArrowPathIcon className="h-5 w-5 animate-spin" />
              ) : (
                <CheckCircleIcon className="h-5 w-5" />
              )}
              فحص الاتصال
            </button>
            <button
              onClick={startMigration}
              disabled={testing || migrating}
              className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg transition-colors disabled:opacity-50 shadow-md shadow-indigo-200 dark:shadow-none"
            >
              {migrating ? (
                <ArrowPathIcon className="h-5 w-5 animate-spin" />
              ) : (
                <PlayIcon className="h-5 w-5" />
              )}
              بدء الاستيراد
            </button>
          </div>
        </div>

        {error && (
          <div className="mt-4 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg flex items-center gap-3 text-red-700 dark:text-red-400">
            <XCircleIcon className="h-6 w-6 flex-shrink-0" />
            <p className="text-sm">{error}</p>
          </div>
        )}

        {success && (
          <div className="mt-4 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg flex items-center gap-3 text-green-700 dark:text-green-400">
            <CheckCircleIcon className="h-6 w-6 flex-shrink-0" />
            <p className="text-sm">{success}</p>
          </div>
        )}
      </div>

      {/* Progress Section */}
      {(migrating || progress) && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Progress Stats */}
          <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-6 flex items-center gap-2">
              <ArrowDownTrayIcon className="h-5 w-5 text-indigo-500" />
              حالة النقل الحالية
            </h3>

            <div className="space-y-6">
              {/* Progress Bar */}
              <div>
                <div className="flex justify-between items-end mb-2">
                  <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                    الإنجاز الكلي
                  </span>
                  <span className="text-2xl font-bold text-indigo-600 dark:text-indigo-400">
                    {progress?.percentage || 0}%
                  </span>
                </div>
                <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-3">
                  <div
                    className="bg-indigo-600 h-3 rounded-full transition-all duration-500 shadow-inner"
                    style={{ width: `${progress?.percentage || 0}%` }}
                  ></div>
                </div>
                <p className="mt-2 text-sm text-gray-500 dark:text-gray-400 animate-pulse">
                  الخطوة الحالية:{" "}
                  <span className="text-indigo-600 dark:text-indigo-400 font-semibold">
                    {progress?.message || "جاري المعالجة..."}
                  </span>
                </p>
              </div>

              {/* Detailed Stats */}
              <div className="grid grid-cols-2 gap-4">
                <StatBox
                  label="المستخدمين"
                  stats={progress?.users}
                  icon={<UserGroupIcon className="h-5 w-5" />}
                />
                <StatBox
                  label="فريق العمل"
                  stats={progress?.teamMembers}
                  icon={<UserGroupIcon className="h-5 w-5" />}
                />
                <StatBox
                  label="المشاريع"
                  stats={progress?.projects}
                  icon={<FolderIcon className="h-5 w-5" />}
                />
                <StatBox
                  label="الإصدارات"
                  stats={progress?.releases}
                  icon={<TagIcon className="h-5 w-5" />}
                />
                <div className="col-span-2">
                  <StatBox
                    label="المهام"
                    stats={progress?.tasks}
                    icon={<ClipboardDocumentListIcon className="h-5 w-5" />}
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Terminal Logs */}
          <div className="bg-gray-900 rounded-xl border border-gray-800 p-4 shadow-xl flex flex-col h-[400px]">
            <div className="flex items-center justify-between mb-3 border-b border-gray-800 pb-2">
              <div className="flex items-center gap-2 text-gray-400">
                <CommandLineIcon className="h-4 w-4" />
                <span className="text-xs font-mono uppercase tracking-wider font-bold">
                  Migration Terminal
                </span>
              </div>
              <div className="flex gap-1.5">
                <div className="w-3 h-3 rounded-full bg-red-500/30"></div>
                <div className="w-3 h-3 rounded-full bg-yellow-500/30"></div>
                <div className="w-3 h-3 rounded-full bg-green-500/30"></div>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto font-mono text-sm space-y-1.5 custom-scrollbar pr-2">
              {logs.map((log, i) => (
                <div
                  key={i}
                  className={`flex gap-2 ${
                    log.level === "error"
                      ? "text-red-400"
                      : log.level === "warn"
                        ? "text-yellow-400"
                        : "text-green-400/80"
                  }`}
                >
                  <span className="text-gray-600">
                    [{new Date(log.timestamp).toLocaleTimeString()}]
                  </span>
                  <span>{log.message}</span>
                </div>
              ))}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      )}

      {/* Info Box */}
      <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl p-6 flex gap-4">
        <InformationCircleIcon className="h-10 w-10 text-blue-500 flex-shrink-0" />
        <div>
          <h4 className="font-bold text-blue-900 dark:text-blue-200 mb-1 leading-tight">
            معلومات هامة
          </h4>
          <ul className="text-sm text-blue-700 dark:text-blue-300 space-y-1 list-disc list-inside">
            <li>
              يتم تجاهل البيانات الموجودة مسبقاً (Skipped) لتفادي التكرار.
            </li>
            <li>
              يفضل فحص الاتصال (Test Connection) قبل البدء في الاستيراد الفعلي.
            </li>
            <li>
              تأكد من وجود صلاحيات كافية للقراءة من قاعدة البيانات المصدر.
            </li>
            <li>
              العملية تتم في الخلفية، يمكنك مغادرة الصفحة والعودة لمتابعة
              التقدم.
            </li>
          </ul>
        </div>
      </div>
    </div>
  );
};

