                      newAssigneeId: e.target.value,
                    })
                  }
                  className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-purple-500 dark:text-white transition-all text-sm"
                >
                  <option value="">
                    -- نفس المسؤول الحالي ({task?.assigneeName || "غير محدد"})
                    --
                  </option>
                  {teamMembers.map((member) => (
                    <option
                      key={member.userId || member.id}
                      value={member.userId || member.id}
                    >
                      {member.name}{" "}
                      {member.availability !== "available" ? "(مشغول)" : ""}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                  اترك فارغاً للاحتفاظ بنفس المسؤول
                </p>
              </div>

              <div className="space-y-3">
                <label className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-900/30 rounded-lg cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-900/50 transition-colors">
                  <input
                    type="checkbox"
                    checked={duplicateForm.includeChecklists}
                    onChange={(e) =>
                      setDuplicateForm({
                        ...duplicateForm,
                        includeChecklists: e.target.checked,
                      })
                    }
                    className="h-4 w-4 text-purple-600 rounded border-gray-300 cursor-pointer"
                  />
                  <div className="flex-1">
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      تضمين القوائم المرجعية
                    </span>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      نسخ جميع القوائم والعناصر (سيتم إعادة تعيين حالة الإكمال)
                    </p>
                  </div>
                </label>

                <label className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-900/30 rounded-lg cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-900/50 transition-colors">
                  <input
                    type="checkbox"
                    checked={duplicateForm.includeAttachments}
                    onChange={(e) =>
                      setDuplicateForm({
                        ...duplicateForm,
                        includeAttachments: e.target.checked,
                      })
                    }
                    className="h-4 w-4 text-purple-600 rounded border-gray-300 cursor-pointer"
                  />
                  <div className="flex-1">
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      تضمين المرفقات
                    </span>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      نسخ جميع الملفات المرفقة (قريباً)
                    </p>
                  </div>
                </label>
              </div>

              <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-900/30 rounded-lg p-4">
                <div className="flex gap-3">
                  <LightBulbIcon className="h-5 w-5 text-blue-600 dark:text-blue-400 flex-shrink-0 mt-0.5" />
                  <div className="text-sm text-blue-800 dark:text-blue-300">
                    <p className="font-medium mb-1">ملاحظة:</p>
                    <ul className="list-disc list-inside space-y-1 text-xs">
                      <li>سيتم إنشاء المهمة بحالة "Backlog"</li>
                      <li>سيتم إعادة تعيين التقدم والساعات الفعلية</li>
                      <li>سيتم نسخ جميع التفاصيل الأخرى</li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex gap-3 justify-end p-6 border-t border-gray-100 dark:border-gray-700">
              <button
                type="button"
                onClick={() => setShowDuplicateModal(false)}
                disabled={isDuplicating}
                className="px-5 py-2.5 border border-gray-300 dark:border-gray-600 rounded-xl text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 font-medium transition-all disabled:opacity-50"
              >
                إلغاء
              </button>
              <button
                onClick={handleDuplicateTask}
                disabled={isDuplicating}
                className="px-5 py-2.5 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-bold shadow-lg shadow-purple-200 dark:shadow-none transition-all flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isDuplicating ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                    جاري التكرار...
                  </>
                ) : (
                  <>
                    <DocumentDuplicateIcon className="h-5 w-5" />
                    تكرار المهمة
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Enhanced Subtask Modal */}
      {showSubtaskModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center overflow-y-auto p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl w-full max-w-lg shadow-2xl transform transition-all">
            <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-700">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg">
                  <ClipboardDocumentListIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                    إنشاء مهمة فرعية جديدة
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    أضف تفاصيل المهمة والمسؤول عنها
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowSubtaskModal(false)}
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full"
              >
                <XMarkIcon className="h-6 w-6 text-gray-400" />
              </button>
            </div>

            <form onSubmit={handleCreateSubtask} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5 flex items-center gap-2">
                  <SparklesIcon className="h-4 w-4" /> عنوان المهمة
                </label>
                <input
                  type="text"
                  required
                  value={subtaskForm.title}
                  onChange={(e) =>
                    setSubtaskForm({ ...subtaskForm, title: e.target.value })
                  }
                  placeholder="مثال: إصلاح خطأ في واجهة المستخدم"
                  className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 dark:text-white transition-all text-sm"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5 flex items-center gap-2">
                  <DocumentDuplicateIcon className="h-4 w-4" /> الوصف
                </label>
                <textarea
                  value={subtaskForm.description}
                  onChange={(e) =>
                    setSubtaskForm({
                      ...subtaskForm,
                      description: e.target.value,
                    })
                  }
                  placeholder="اشرح تفاصيل المهمة هنا..."
                  rows={3}
                  className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 dark:text-white transition-all text-sm resize-none"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5 flex items-center gap-2">
                    <BriefcaseIcon className="h-4 w-4" /> القسم المعني
                  </label>
                  <select
                    value={subtaskForm.department}
                    onChange={(e) => handleDepartmentChange(e.target.value)}
                    className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:border-indigo-500 dark:text-white transition-all text-sm"
                  >
                    <option value="">-- اختر القسم --</option>
                    {Array.from(
                      new Set(
                        teamMembers
                          .filter((m) => m.department)
                          .map((m) => m.department),
                      ),
                    ).map((dept) => (
                      <option key={dept} value={dept}>
                        {dept}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5 flex items-center gap-2">
                    <UserGroupIcon className="h-4 w-4" /> المسؤول
                  </label>
                  <select
                    value={subtaskForm.assigneeId}
                    onChange={(e) =>
                      setSubtaskForm({
                        ...subtaskForm,
                        assigneeId: e.target.value,
                      })
                    }
                    className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:border-indigo-500 dark:text-white transition-all text-sm"
                  >
                    <option value="">-- اختر المسؤول --</option>
                    {teamMembers
                      .filter(
                        (m) =>
                          !subtaskForm.department ||
                          m.department === subtaskForm.department,
                      )
                      .map((member) => (
                        <option
                          key={member.userId || member.id}
                          value={member.userId || member.id}
                        >
                          {member.name}{" "}
                          {member.availability !== "available" ? "(مشغول)" : ""}
                        </option>
                      ))}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5">
                    النوع
                  </label>
                  <select
                    value={subtaskForm.type}
                    onChange={(e) =>
                      setSubtaskForm({ ...subtaskForm, type: e.target.value })
                    }
                    className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:border-indigo-500 dark:text-white transition-all text-sm"
                  >
                    <option value="FEATURE">✨ ميزة</option>
                    <option value="BUG">🐛 خطأ</option>
                    <option value="ENHANCEMENT">🔧 تحسين</option>
                    <option value="REFACTOR">♻️ إعادة هيكلة</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5">
                    الأولوية
                  </label>
                  <select
                    value={subtaskForm.priority}
                    onChange={(e) =>
                      setSubtaskForm({
                        ...subtaskForm,
                        priority: e.target.value,
                      })
                    }
                    className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:border-indigo-500 dark:text-white transition-all text-sm"
                  >
                    <option value="LOW">منخفضة</option>
                    <option value="MEDIUM">متوسطة</option>
                    <option value="HIGH">عالية</option>
                    <option value="CRITICAL">حرجة 🔥</option>
                  </select>
                </div>
              </div>

              <div className="flex gap-3 justify-end mt-6 pt-4 border-t border-gray-50 dark:border-gray-700">
                <button
                  type="button"
                  onClick={() => setShowSubtaskModal(false)}
                  className="px-5 py-2.5 border border-gray-300 dark:border-gray-600 rounded-xl text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 font-medium transition-all"
                >
                  إلغاء
                </button>
                <button
                  type="submit"
                  className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold shadow-lg shadow-indigo-200 dark:shadow-none transition-all flex items-center gap-2"
                >
                  إنشاء المهمة <CheckIcon className="h-5 w-5" />
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
      {/* Request Testing Modal */}
      {showTestingModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center overflow-y-auto p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl w-full max-w-md shadow-2xl transform transition-all">
            <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-700">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-cyan-50 dark:bg-cyan-900/30 rounded-lg">
                  <CheckCircleIcon className="h-6 w-6 text-cyan-600 dark:text-cyan-400" />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                    طلب اختبار
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    اختر المسؤول عن اختبار هذه المهمة
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowTestingModal(false)}
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full"
              >
                <XMarkIcon className="h-6 w-6 text-gray-400" />
              </button>
            </div>

            <form
              onSubmit={handleCreateTestingSubtask}
              className="p-6 space-y-4"
            >
              <div>
                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5 flex items-center gap-2">
                  <UserIcon className="h-4 w-4" /> اختر المختبر
                </label>
                <select
                  required
                  value={selectedTesterId}
                  onChange={(e) => setSelectedTesterId(e.target.value)}
                  className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-cyan-500 focus:border-cyan-500 dark:text-white transition-all text-sm"
                >
                  <option value="">-- اختر المختبر --</option>
                  {teamMembers.map((member) => (
                    <option
                      key={member.userId || member.id}
                      value={member.userId || member.id}
                    >
                      {member.name}{" "}
                      {member.availability !== "available" ? "(مشغول)" : ""}
                    </option>
                  ))}
                </select>
              </div>

              <div className="bg-cyan-50 dark:bg-cyan-900/20 border border-cyan-100 dark:border-cyan-900/30 rounded-lg p-4">
                <div className="flex gap-3">
                  <LightBulbIcon className="h-5 w-5 text-cyan-600 dark:text-cyan-400 flex-shrink-0 mt-0.5" />
                  <div className="text-sm text-cyan-800 dark:text-cyan-300">
                    <p className="font-medium mb-1">تفاصيل الاختبار:</p>
                    <ul className="list-disc list-inside space-y-1 text-xs">
                      <li>
                        سيتم إنشاء مهمة فرعية جديدة بعنوان "Testing:{" "}
                        {task?.title?.substring(0, 30)}..."
                      </li>
                      <li>ستحتفظ بنفس الأولوية والقسم</li>
                    </ul>
                  </div>
                </div>
              </div>

              <div className="flex gap-3 justify-end mt-6 pt-4 border-t border-gray-50 dark:border-gray-700">
                <button
                  type="button"
                  onClick={() => setShowTestingModal(false)}
                  className="px-5 py-2.5 border border-gray-300 dark:border-gray-600 rounded-xl text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 font-medium transition-all"
                >
                  إلغاء
                </button>
                <button
                  type="submit"
                  className="px-5 py-2.5 bg-cyan-600 hover:bg-cyan-700 text-white rounded-xl font-bold shadow-lg shadow-cyan-200 dark:shadow-none transition-all flex items-center gap-2"
                >
                  إرسال الطلب <CheckIcon className="h-5 w-5" />
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );

  const renderMainContent = () => (
    <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden shadow-sm min-h-[600px]">
      {/* Tabs Header */}
      <div className="border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50 overflow-x-auto">
        <div className="flex">
          <button
            onClick={() => setActiveTab("details")}
            className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 flex items-center gap-2 ${
              activeTab === "details"
                ? "text-indigo-600 dark:text-indigo-400 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-gray-800"
                : "text-gray-500 dark:text-gray-400 border-transparent hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            <DocumentDuplicateIcon className="h-5 w-5" />
            نظرة عامة
          </button>
          <button
            onClick={() => setActiveTab("subtasks")}
            className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 flex items-center gap-2 ${
              activeTab === "subtasks"
                ? "text-indigo-600 dark:text-indigo-400 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-gray-800"
                : "text-gray-500 dark:text-gray-400 border-transparent hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            <ClipboardDocumentListIcon className="h-5 w-5" />
            المهام الفرعية ({task.subtasks?.length || 0})
          </button>
          <button
            onClick={() => setActiveTab("checklists")}
            className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 flex items-center gap-2 ${
              activeTab === "checklists"
                ? "text-indigo-600 dark:text-indigo-400 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-gray-800"
                : "text-gray-500 dark:text-gray-400 border-transparent hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            <CheckCircleIcon className="h-5 w-5" />
            القوائم ({task.checklists?.length || 0})
          </button>
          <button
            onClick={() => setActiveTab("comments")}
            className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 flex items-center gap-2 ${
              activeTab === "comments"
                ? "text-indigo-600 dark:text-indigo-400 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-gray-800"
                : "text-gray-500 dark:text-gray-400 border-transparent hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            <ChatBubbleLeftIcon className="h-5 w-5" />
            التعليقات ({task.comments?.length || 0})
          </button>
          <button
            onClick={() => setActiveTab("attachments")}
            className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 flex items-center gap-2 ${
              activeTab === "attachments"
                ? "text-indigo-600 dark:text-indigo-400 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-gray-800"
                : "text-gray-500 dark:text-gray-400 border-transparent hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            <PaperClipIcon className="h-5 w-5" />
            المرفقات ({task.attachments?.length || 0})
          </button>
          <button
            onClick={() => setActiveTab("time")}
            className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 flex items-center gap-2 ${
              activeTab === "time"
                ? "text-indigo-600 dark:text-indigo-400 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-gray-800"
                : "text-gray-500 dark:text-gray-400 border-transparent hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            <ClockIcon className="h-5 w-5" />
            تتبع الوقت
          </button>
          <button
            onClick={() => setActiveTab("activities")}
            className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 flex items-center gap-2 ${
              activeTab === "activities"
                ? "text-indigo-600 dark:text-indigo-400 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-gray-800"
                : "text-gray-500 dark:text-gray-400 border-transparent hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            يوميات النظام
          </button>
        </div>
      </div>

      <div className="p-6">
        {activeTab === "details" && (
          <TaskOverview
            task={task}
            handleToggleItem={handleToggleItem}
            handleAddItem={handleAddItem}
            newItemInputs={newItemInputs}
            setNewItemInputs={setNewItemInputs}
            settings={settings}
          />
        )}

        {activeTab === "subtasks" && (
          <TaskSubtasks
            task={task}
            onAddSubtask={() => setShowSubtaskModal(true)}
            onRequestTesting={() => setShowTestingModal(true)}
            settings={settings}
          />
        )}

        {activeTab === "checklists" && (
          <div className="space-y-6">
            <div className="flex gap-2 justify-between items-center mb-4">
              <div className="flex gap-2 flex-1">
                <input
                  type="text"
                  value={newChecklistTitle}
                  onChange={(e) => setNewChecklistTitle(e.target.value)}
                  placeholder="عنوان القائمة الجديدة..."
                  className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-gray-100"
                />
                <button
                  onClick={handleCreateChecklist}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  <PlusIcon className="h-5 w-5" />
                </button>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={handleExportChecklists}
                  title="تصدير القوائم"
                  className="p-2 text-gray-600 bg-gray-100 hover:bg-gray-200 dark:text-gray-300 dark:bg-gray-700 dark:hover:bg-gray-600 rounded-lg transition-colors"
                >
                  <ArrowDownTrayIcon className="h-5 w-5" />
                </button>
                <button
                  onClick={() => fileInputRef.current?.click()}
                  title="استيراد قوائم"
                  className="p-2 text-gray-600 bg-gray-100 hover:bg-gray-200 dark:text-gray-300 dark:bg-gray-700 dark:hover:bg-gray-600 rounded-lg transition-colors"
                >
                  <ArrowUpTrayIcon className="h-5 w-5" />
                </button>
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={handleImportChecklists}
                  accept=".txt"
                  className="hidden"
                />
              </div>
            </div>

            {task.checklists?.map((checklist) => (
              <div
                key={checklist.id}
                className="bg-gray-50 dark:bg-gray-700/30 rounded-lg p-4 border border-gray-200 dark:border-gray-700"
              >
                <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-3 flex items-center gap-2">
                  <CheckCircleIcon className="h-5 w-5 text-indigo-500" />
                  {checklist.title}
                </h4>
                <div className="space-y-2 mb-3">
                  {checklist.items?.map((item) => (
                    <div
                      key={item.id}
                      className="flex items-center gap-3 group"
                    >
                      <input
                        type="checkbox"
                        checked={item.isCompleted}
                        onChange={() =>
                          handleToggleItem(item.id, item.isCompleted)
                        }
                        className="h-4 w-4 text-indigo-600 rounded border-gray-300 cursor-pointer dark:bg-gray-700 dark:border-gray-600 focus:ring-indigo-500"
                      />
                      <span
                        className={`flex-1 transition-all ${item.isCompleted ? "line-through text-gray-400" : "text-gray-700 dark:text-gray-300"}`}
                      >
                        {item.content}
                      </span>
                      <button
                        onClick={() =>
                          setConfirmModal({
                            open: true,
                            message: "هل أنت متأكد من حذف هذا العنصر؟",
                            onConfirm: () => handleDeleteChecklistItem(item.id),
                          })
                        }
                        className="opacity-0 group-hover:opacity-100 p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 rounded transition-opacity"
                      >
                        <TrashIcon className="h-4 w-4" />
                      </button>
                    </div>
                  ))}
                </div>
                <div className="flex gap-2 mt-2">
                  <input
                    type="text"
                    value={newItemInputs[checklist.id] || ""}
                    onChange={(e) =>
                      setNewItemInputs({
                        ...newItemInputs,
                        [checklist.id]: e.target.value,
                      })
                    }
                    placeholder="إضافة عنصر..."
                    className="flex-1 px-3 py-1.5 text-sm border border-gray-200 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-gray-200 focus:ring-1 focus:ring-indigo-500"
                    onKeyPress={(e) =>
                      e.key === "Enter" && handleAddItem(checklist.id)
                    }
                  />
                  <button
                    onClick={() => handleAddItem(checklist.id)}
                    className="p-1.5 text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors"
                  >
                    <PlusIcon className="h-5 w-5" />
                  </button>
                </div>
              </div>
            ))}
            {(!task.checklists || task.checklists.length === 0) &&
              !newChecklistTitle && (
                <div className="text-center py-12 text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-dashed border-gray-200 dark:border-gray-700">
                  <CheckCircleIcon className="h-12 w-12 mx-auto mb-3 text-gray-300 dark:text-gray-600" />
                  <p>لا توجد قوائم مرجعية</p>
                </div>
              )}
          </div>
        )}

        {activeTab === "comments" && (
          <div className="space-y-6">
            <div className="border-b border-gray-200 dark:border-gray-700 pb-6">
              <textarea
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder="اكتب تعليقاً..."
                rows={3}
                className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 mb-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 transition-shadow shadow-sm"
              />
              <div className="flex justify-end">
                <button
                  onClick={handleAddComment}
                  disabled={!newComment.trim()}
                  className="px-6 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-md transition-all active:scale-95"
                >
                  إضافة تعليق
                </button>
              </div>
            </div>

            <div className="space-y-6">
              {task.comments?.map((comment) => (
                <div
                  key={comment.id}
                  className="border-b border-gray-100 dark:border-gray-700 pb-6 last:border-0"
                >
                  <div className="flex items-start gap-4">
                    {comment.authorAvatar ? (
                      <img
                        src={comment.authorAvatar}
                        alt=""
                        className="w-10 h-10 rounded-full ring-2 ring-gray-100 dark:ring-gray-700"
                      />
                    ) : (
                      <div className="w-10 h-10 rounded-full bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm">
                        {comment.authorName.charAt(0)}
                      </div>
                    )}
                    <div className="flex-1 bg-gray-50 dark:bg-gray-700/30 p-4 rounded-xl rounded-tr-none">
                      <div className="flex items-center justify-between mb-2">
                        <span className="font-bold text-gray-900 dark:text-gray-100">
                          {comment.authorName}
                        </span>
                        <span className="text-xs text-gray-500 dark:text-gray-400">
                          {new Date(comment.createdAt).toLocaleString("ar-EG")}
                          {comment.isEdited && (
                            <span className="mr-1">(معدل)</span>
                          )}
                        </span>
                      </div>
                      <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap leading-relaxed">
                        {comment.content}
                      </p>
                    </div>
                  </div>
                </div>
              ))}
              {(!task.comments || task.comments.length === 0) && (
                <div className="text-center py-12 text-gray-500 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-dashed border-gray-200 dark:border-gray-700">
                  <ChatBubbleLeftIcon className="h-12 w-12 mx-auto mb-3 text-gray-300" />
                  <p>لا توجد تعليقات بعد</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === "attachments" && (
          <div>
            <div className="mb-6">
              <label className="block w-full cursor-pointer bg-gradient-to-br from-indigo-50 to-purple-50 dark:from-indigo-900/20 dark:to-purple-900/20 border-2 border-dashed border-indigo-300 dark:border-indigo-600 rounded-xl p-8 text-center hover:from-indigo-100 hover:to-purple-100 dark:hover:from-indigo-900/30 dark:hover:to-purple-900/30 transition-all group">
                <input
                  type="file"
                  className="hidden"
                  onChange={handleFileUpload}
                  disabled={isUploading}
                  multiple
                  accept="image/*,application/pdf,.doc,.docx,.xls,.xlsx,.txt"
                />
                <div className="w-16 h-16 bg-white dark:bg-gray-800 rounded-full shadow-lg flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                  <CloudArrowDownIcon className="h-8 w-8 text-indigo-600 dark:text-indigo-400" />
                </div>
                <span className="text-gray-700 dark:text-gray-200 font-bold block text-lg mb-1">
                  {isUploading
                    ? "⏳ جاري الرفع..."
                    : "📎 اضغط لرفع ملفات متعددة"}
                </span>
                <span className="text-sm text-gray-500 dark:text-gray-400 block mb-2">
                  يمكنك اختيار أكثر من ملف في نفس الوقت (حتى 10 ملفات)
                </span>
                <span className="text-xs text-gray-400 dark:text-gray-500 block">
                  الحد الأقصى: 20 ميجابايت لكل ملف • الصور، PDF، Word، Excel
                </span>
              </label>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {task.attachments?.map((file) => {
                const isImage = file.fileType?.startsWith("image/");
                return (
                  <div
                    key={file.id}
                    className="border border-gray-200 dark:border-gray-700 rounded-xl bg-white dark:bg-gray-800 hover:shadow-md transition-shadow group relative overflow-hidden"
                  >
                    {isImage ? (
                      <div className="relative">
                        <img
                          src={
                            file.fileUrl ||
                            `/uploads/dev-tasks/${file.fileName}`
                          }
                          alt={file.originalName || file.fileName}
                          className="w-full h-48 object-cover"
                        />
                        <div className="absolute top-2 left-2 flex gap-1">
                          <a
                            href={
                              file.fileUrl ||
                              `/uploads/dev-tasks/${file.fileName}`
                            }
                            target="_blank"
                            rel="noopener noreferrer"
                            className="p-2 bg-white/90 dark:bg-gray-800/90 hover:bg-white dark:hover:bg-gray-800 rounded-lg text-gray-700 dark:text-gray-300 shadow-sm"
                          >
                            <CloudArrowDownIcon className="h-5 w-5" />
                          </a>
                          <button
                            onClick={() =>
                              setConfirmModal({
                                open: true,
                                message: "هل أنت متأكد من حذف هذا المرفق؟",
                                onConfirm: () =>
                                  handleDeleteAttachment(file.id),
                              })
                            }
                            className="p-2 bg-white/90 dark:bg-gray-800/90 hover:bg-red-50 dark:hover:bg-red-900/50 rounded-lg text-gray-700 dark:text-gray-300 hover:text-red-600 shadow-sm opacity-0 group-hover:opacity-100 transition-opacity"
                          >
                            <TrashIcon className="h-5 w-5" />
                          </button>
                        </div>
                        <div className="p-3 bg-gradient-to-t from-black/50 to-transparent absolute bottom-0 left-0 right-0">
                          <p
                            className="text-sm font-semibold text-white truncate"
                            title={file.originalName || file.fileName}
                          >
                            {file.originalName || file.fileName}
                          </p>
                          <p className="text-xs text-gray-200 mt-0.5">
                            {(file.fileSize / 1024).toFixed(1)} KB
                          </p>
                        </div>
                      </div>
                    ) : (
                      <div className="flex items-center gap-3 p-4">
                        <div className="w-12 h-12 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg flex items-center justify-center text-indigo-600 dark:text-indigo-400">
                          <PaperClipIcon className="h-6 w-6" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <p
                            className="text-sm font-semibold text-gray-900 dark:text-gray-100 truncate"
                            title={file.originalName || file.fileName}
                          >
                            {file.originalName || file.fileName}
                          </p>
                          <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                            {(file.fileSize / 1024).toFixed(1)} KB •{" "}
                            {new Date(file.createdAt).toLocaleDateString(
                              "ar-EG",
                            )}
                          </p>
                        </div>
                        <div className="flex gap-1">
                          <a
                            href={
                              file.fileUrl ||
                              `/uploads/dev-tasks/${file.fileName}`
                            }
                            target="_blank"
                            rel="noopener noreferrer"
                            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-500"
                          >
                            <CloudArrowDownIcon className="h-5 w-5" />
                          </a>
                          <button
                            onClick={() =>
                              setConfirmModal({
                                open: true,
                                message: "هل أنت متأكد من حذف هذا المرفق؟",
                                onConfirm: () =>
                                  handleDeleteAttachment(file.id),
                              })
                            }
                            className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity"
                          >
                            <TrashIcon className="h-5 w-5" />
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
            {(!task.attachments || task.attachments.length === 0) && (
              <div className="text-center py-12 text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-dashed border-gray-200 dark:border-gray-700 mt-6">
                <PaperClipIcon className="h-12 w-12 mx-auto mb-3 text-gray-300 dark:text-gray-600" />
                <p>لا توجد مرفقات</p>
              </div>
            )}
          </div>
        )}

        {activeTab === "time" && (
          <div className="space-y-8">
            {/* Live Timer Section */}
            <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-8 rounded-2xl text-white shadow-xl relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-3xl -mr-32 -mt-32"></div>
              <div className="relative z-10 text-center">
                <p className="text-indigo-100 font-medium mb-3 tracking-wide uppercase text-sm">
                  {activeTimer.taskId === id && activeTimer.isRunning
                    ? "جلسة نشطة"
                    : "العداد متوقف"}
                </p>
                <p className="text-6xl font-mono font-bold mb-8 drop-shadow-md">
                  {formatTime(activeTimer.taskId === id ? elapsedSeconds : 0)}
                </p>

                <div className="flex justify-center">
                  {activeTimer.taskId === id && activeTimer.isRunning ? (
                    <button
                      onClick={handleStopTimer}
                      className="flex items-center gap-3 px-8 py-4 bg-red-500 hover:bg-red-600 text-white rounded-full font-bold shadow-lg transition-all transform hover:scale-105"
                    >
                      <StopIcon className="h-6 w-6" />
                      إيقاف العداد
                    </button>
                  ) : (
                    <button
                      onClick={handleStartTimer}
                      className="flex items-center gap-3 px-8 py-4 bg-white text-indigo-700 hover:bg-indigo-50 rounded-full font-bold shadow-lg transition-all transform hover:scale-105"
                    >
                      <PlayIcon className="h-6 w-6" />
                      ابدأ التسجيل
                    </button>
                  )}
                </div>
              </div>
            </div>

            {/* Time Logs History */}
            <div>
              <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-4 flex items-center gap-2">
                <ClockIcon className="h-5 w-5 text-gray-500" />
                سجل الأوقات السابقة
              </h4>
              <div className="space-y-3">
                {task.timeLogs
                  ?.filter((log) => !log.isRunning)
                  .map((log) => (
                    <div
                      key={log.id}
                      className="flex items-center justify-between p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl hover:shadow-md transition-all group"
                    >
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full bg-indigo-50 dark:bg-indigo-900/30 flex items-center justify-center font-bold text-indigo-600 dark:text-indigo-400">
                          {log.memberName.charAt(0)}
                        </div>
                        <div>
                          <p className="font-bold text-gray-900 dark:text-gray-100">
                            {log.memberName}
                          </p>
                          <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400 mt-0.5">
                            <span>
                              {new Date(log.startTime).toLocaleDateString(
                                "ar-EG",
                              )}
                            </span>
                            <span>•</span>
                            <span>{log.description || "بدون وصف"}</span>
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-6">
                        <div className="text-left">
                          <p className="text-lg font-bold text-gray-900 dark:text-gray-100 font-mono">
                            {Math.round((log.duration / 60) * 100) / 100}h
                          </p>
                          <p className="text-xs text-gray-500 dark:text-gray-400 text-right">
                            {log.duration}m
                          </p>
                        </div>
                        <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                          <button
                            onClick={() =>
                              setEditingTimeLog({
                                id: log.id,
                                duration: log.duration,
                                description: log.description || "",
                              })
                            }
                            className="p-2 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg"
                          >
                            <PencilIcon className="h-4 w-4" />
                          </button>
                          <button
                            onClick={() =>
                              setConfirmModal({
                                open: true,
                                message: "هل أنت متأكد من حذف سجل الوقت هذا؟",
                                onConfirm: () => handleDeleteTimeLog(log.id),
                              })
                            }
                            className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg"
                          >
                            <TrashIcon className="h-4 w-4" />
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}

                {(!task.timeLogs ||
                  task.timeLogs.filter((l) => !l.isRunning).length === 0) && (
                  <div className="text-center py-12 text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-dashed border-gray-200 dark:border-gray-700">
                    <ClockIcon className="h-12 w-12 mx-auto mb-3 text-gray-300 dark:text-gray-600" />
                    <p>لا توجد سجلات وقت</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === "activities" && (
          <TaskActivities activities={task.activities} />
        )}
      </div>
    </div>
  );

  return (
    <div className="w-full pb-10" dir="rtl">
      {renderModals()}

      <TaskHeader
        task={task}
        isTimerRunning={activeTimer.taskId === id && activeTimer.isRunning}
        isTimerPaused={activeTimer.taskId === id && activeTimer.isPaused}
        elapsedSeconds={activeTimer.taskId === id ? elapsedSeconds : 0}
        handleStartTimer={handleStartTimer}
        handleStopTimer={handleStopTimer}
        handlePauseTimer={handlePauseTimer}
        handleResumeTimer={handleResumeTimer}
        onEdit={() => navigate(`/super-admin/dev-tasks/${id}/edit`)}
        onDelete={() =>
          setConfirmModal({
            open: true,
            message: "هل أنت متأكد من حذف هذه المهمة؟",
            onConfirm: handleDeleteTask,
          })
        }
        onDuplicate={() => setShowDuplicateModal(true)}
        isSmartTimeTrackingEnabled={settings?.smartTimeTracking ?? true}
        canEdit={userPermissions?.canEdit}
        canDelete={userPermissions?.canDelete}
        settings={settings}
      />

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-8 space-y-6">{renderMainContent()}</div>
        <div className="lg:col-span-4 space-y-6 lg:order-last">
          <TaskSidebar
            task={task}
            settings={settings}
            userPermissions={userPermissions}
            statusDropdownOpen={statusDropdownOpen}
            setStatusDropdownOpen={setStatusDropdownOpen}
            handleUpdateStatus={handleUpdateStatus}
            teamMembers={teamMembers}
            handleUpdateAssignee={handleUpdateAssignee}
          />
        </div>
      </div>
    </div>
  );
};

export default DevTaskDetails;

import React, { useState, useEffect } from "react";
import { useNavigate, useParams, useSearchParams } from "react-router-dom";
import { buildApiUrl } from "../../utils/urlHelper";
import tokenManager from "../../utils/tokenManager";
import {
  ArrowRightIcon,
  LightBulbIcon,
  CheckBadgeIcon,
  SparklesIcon,
  XMarkIcon,
  PencilIcon,
  PhotoIcon,
  CheckCircleIcon,
} from "@heroicons/react/24/outline";

interface Project {
  id: string;
  name: string;
  color: string;
}

interface TeamMember {
  id: string;
  name: string;
  email: string;
  avatar: string | null;
}

interface Release {
  id: string;
  version: string;
  name: string;
}

import {
  TYPE_OPTIONS,
  STATUS_OPTIONS,
  PRIORITY_OPTIONS,
} from "../../constants/taskConstants";

// Default component options
const componentOptions = [
  { value: "frontend", label: "Frontend" },
  { value: "backend", label: "Backend" },
  { value: "database", label: "Database" },
  { value: "api", label: "API" },
  { value: "ui", label: "UI/UX" },
  { value: "mobile", label: "Mobile" },
  { value: "devops", label: "DevOps" },
  { value: "testing", label: "Testing" },
  { value: "documentation", label: "Documentation" },
  { value: "general", label: "General" },
];

const getAccessToken = (): string | null => tokenManager.getAccessToken();

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const DevTaskForm: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [searchParams] = useSearchParams();
  const isEdit = !!id;

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [projects, setProjects] = useState<Project[]>([]);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [releases, setReleases] = useState<Release[]>([]);

  const [formData, setFormData] = useState({
    title: "",
    description: "",
    businessValue: "",
    acceptanceCriteria: "",
    type: "FEATURE",
    priority: "MEDIUM",
    status: "BACKLOG",
    component: "",
    assigneeId: "",
    projectId: "",
    releaseId: "",
    dueDate: (() => {
      const d = new Date();
      d.setDate(d.getDate() + 3);
      return d.toISOString().split("T")[0];
    })(),
    startDate: new Date().toISOString().split("T")[0], // Default to today
    estimatedHours: "1",
    tags: "",
    gitBranch: "",
    companyId: "",
    ticketId: "",
    campaignId: "",
    targetAudience: "",
    budgetAllocation: "",
    expectedROI: "",
    relatedLinks: [] as { title: string; url: string }[],
  });

  const [checklistItems, setChecklistItems] = useState<string[]>([]);
  const [selectedImages, setSelectedImages] = useState<File[]>([]);
  const [imagePreviews, setImagePreviews] = useState<string[]>([]);
  const checklistInputRef = React.useRef<HTMLInputElement>(null);

  // AI Assistant State
  const [aiModalOpen, setAiModalOpen] = useState(false);
  const [aiMode, setAiMode] = useState<"description" | "error">("description");
  const [aiPrompt, setAiPrompt] = useState("");
  const [aiGenerating, setAiGenerating] = useState(false);

  // New Features State
  const [settings, setSettings] = useState<any>(null);
  const [watchers, setWatchers] = useState<string[]>([]);
  const [newLinkTitle, setNewLinkTitle] = useState("");
  const [newLinkUrl, setNewLinkUrl] = useState("");

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;

    try {
      setAiGenerating(true);
      setError(null);
      const token = getAccessToken();

      const endpoint =
        aiMode === "description"
          ? "super-admin/dev-tasks/ai-create"
          : "super-admin/dev-tasks/ai-analyze";

      const body =
        aiMode === "description"
          ? { description: aiPrompt }
          : { errorLog: aiPrompt };

      const response = await fetch(buildApiUrl(endpoint), {
        method: "POST",
        headers: getAuthHeaders({ "Content-Type": "application/json" }),
        body: JSON.stringify(body),
      });

      const data = await response.json();

      if (data.success) {
        setFormData((prev) => ({
          ...prev,
          title: data.data.title || prev.title,
          description: data.data.description || prev.description,
          type: data.data.type || prev.type,
          priority: data.data.priority || prev.priority,
          estimatedHours:
            data.data.estimatedHours?.toString() || prev.estimatedHours,
          tags: data.data.tags ? data.data.tags.join(", ") : prev.tags,
          // Only update status if it's new
          status: "TODO",
        }));
        setAiModalOpen(false);
        if (data.data.checklist && Array.isArray(data.data.checklist)) {
          setChecklistItems(data.data.checklist);
        }
      } else {
        setError(data.message || "فشل في توليد المهمة");
      }
    } catch (err) {
      console.error("AI Generation Error:", err);
      setError("فشل في الاتصال بخدمة الذكاء الاصطناعي");
    } finally {
      setAiGenerating(false);
    }
  };

  useEffect(() => {
    fetchInitialData();
    fetchSettings();

    // Set initial status from query params
    const status = searchParams.get("status");
    if (status) {
      setFormData((prev) => ({ ...prev, status }));
    }
  }, []);

  // Merge default components with settings-defined ones
  const derivedComponentOptions = React.useMemo(() => {
    const defaultValues = new Set(componentOptions.map((o) => o.value));
    const customOptions = settings?.componentMappings
      ? Object.keys(settings.componentMappings)
          .filter((k) => !defaultValues.has(k))
          .map((k) => ({ value: k, label: k }))
      : [];
    return [...componentOptions, ...customOptions];
  }, [settings]);

  // Auto-Assignment Logic
  useEffect(() => {
    if (settings && settings.componentMappings && formData.component) {
      // Case-insensitive lookup
      const componentKey = Object.keys(settings.componentMappings).find(
        (k) => k.toLowerCase() === formData.component.toLowerCase(),
      );

      const autoAssignee = componentKey
        ? settings.componentMappings[componentKey]
        : null;

      if (autoAssignee && !formData.assigneeId) {
        // Only auto-assign if empty
        // Verify member exists
        const memberExists = teamMembers.find((m) => m.id === autoAssignee);
        if (memberExists) {
          setFormData((prev) => ({ ...prev, assigneeId: autoAssignee }));
        }
      }
    }
  }, [formData.component, settings, teamMembers]);

  useEffect(() => {
    if (isEdit) {
      fetchTask();
    }
  }, [id]);

  const fetchInitialData = async () => {
    try {
      const headers = getAuthHeaders({ "Content-Type": "application/json" });

      const [projectsRes, teamRes, releasesRes] = await Promise.all([
        fetch(buildApiUrl("super-admin/dev/projects"), { headers }),
        fetch(buildApiUrl("super-admin/dev/team"), { headers }),
        fetch(buildApiUrl("super-admin/dev/releases"), { headers }),
      ]);

      const [projectsData, teamData, releasesData] = await Promise.all([
        projectsRes.json(),
        teamRes.json(),
        releasesRes.json(),
      ]);

      if (projectsData.success) setProjects(projectsData.data);
      if (teamData.success) setTeamMembers(teamData.data);
      if (releasesData.success) setReleases(releasesData.data);
    } catch (err) {
      console.error("Error fetching initial data:", err);
    }
  };

  const fetchSettings = async () => {
    try {
      const res = await fetch(buildApiUrl("super-admin/dev/settings"), {
        headers: getAuthHeaders(),
      });
      const data = await res.json();
      if (data.success) setSettings(data.data);
    } catch (e) {
      console.error("Failed to fetch settings", e);
    }
  };

  const fetchTask = async () => {
    try {
      setLoading(true);
      const response = await fetch(buildApiUrl(`super-admin/dev/tasks/${id}`), {
        headers: getAuthHeaders({ "Content-Type": "application/json" }),
      });

      const data = await response.json();
      if (data.success) {
        const task = data.data;
        // Normalize component value to lowercase to match componentOptions
        const normalizedComponent = task.component
          ? task.component.toLowerCase()
          : "";
        setFormData({
          title: task.title || "",
          description: task.description || "",
          businessValue: task.businessValue || "",
          acceptanceCriteria: task.acceptanceCriteria || "",
          type: task.type || "FEATURE",
          priority: task.priority || "MEDIUM",
          status: task.status || "BACKLOG",
          component: normalizedComponent,
          assigneeId: task.assigneeId || "",
          projectId: task.projectId || "",
          releaseId: task.releaseId || "",
          dueDate: task.dueDate ? task.dueDate.split("T")[0] : "",
          startDate: task.startDate ? task.startDate.split("T")[0] : "",
          estimatedHours: task.estimatedHours?.toString() || "",
          tags: task.tags?.join(", ") || "",
          gitBranch: task.gitBranch || "",
          companyId: task.companyId || "",
          ticketId: task.ticketId || "",
          campaignId: task.campaignId || "",
          targetAudience: task.targetAudience || "",
          budgetAllocation: task.budgetAllocation?.toString() || "",
          expectedROI: task.expectedROI?.toString() || "",
        });

        // Set Watchers
        if (task.watchers && Array.isArray(task.watchers)) {
          // Check if watchers is array of objects { memberId } or just IDs.
          // Based on Prisma relation, it returns DevTaskWatcher objects which have memberId.
          // But API might return simplified list if I updated controller.
          // Let's assume standard include: { watchers: { memberId: '...' }[] }
          const watcherIds = task.watchers.map((w: any) => w.memberId || w);
          setWatchers(watcherIds);
        }

        // Set Related Links
        if (task.relatedLinks) {
          setFormData((prev) => ({
            ...prev,
            relatedLinks: Array.isArray(task.relatedLinks)
              ? task.relatedLinks
              : [],
          }));
        }
      } else {
        setError(data.error || "فشل في جلب المهمة");
      }
    } catch (err) {
      setError("فشل في الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title.trim()) {
      setError("العنوان مطلوب");
      return;
    }
    if (!formData.description.trim()) {
      setError("الوصف مطلوب");
      return;
    }
    if (!formData.assigneeId) {
      setError("المسؤول مطلوب");
      return;
    }
    if (!formData.dueDate) {
      setError("تاريخ الاستحقاق مطلوب");
      return;
    }

    try {
      setSaving(true);
      setError(null);
      const token = getAccessToken();

      const payload = {
        ...formData,
        estimatedHours: formData.estimatedHours
          ? parseFloat(formData.estimatedHours)
          : 0,
        tags: formData.tags
          ? formData.tags
              .split(",")
              .map((t) => t.trim())
              .filter(Boolean)
          : [],
        assigneeId: formData.assigneeId || null,
        projectId: formData.projectId || null,
        releaseId: formData.releaseId || null,
        dueDate: formData.dueDate || null,
        startDate: formData.startDate || null,
        component: formData.component || null,
        gitBranch: formData.gitBranch || null,
        companyId: formData.companyId || null,
        ticketId: formData.ticketId || null,
        campaignId: formData.campaignId || null,
        targetAudience: formData.targetAudience || null,
        budgetAllocation: formData.budgetAllocation
          ? parseFloat(formData.budgetAllocation)
          : null,
        expectedROI: formData.expectedROI
          ? parseFloat(formData.expectedROI)
          : null,
        checklistItems: checklistItems.length > 0 ? checklistItems : undefined,
        watchers: watchers,
        relatedLinks: formData.relatedLinks,
      };

      const url = isEdit
        ? buildApiUrl(`super-admin/dev/tasks/${id}`)
        : buildApiUrl("super-admin/dev/tasks");

      const method = isEdit ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: getAuthHeaders({ "Content-Type": "application/json" }),
        body: JSON.stringify(payload),
      });

      const data = await response.json();
      if (data.success) {
        const taskId = data.data.id;

        // Upload images if selected
        if (selectedImages.length > 0 && taskId) {
          const formData = new FormData();
          selectedImages.forEach((image) => {
            formData.append("files", image);
          });

          await fetch(
            buildApiUrl(`super-admin/dev/tasks/${taskId}/attachments`),
            {
              method: "POST",
              headers: {
                Authorization: `Bearer ${token}`,
              },
              body: formData,
            },
          );
        }

        navigate("/super-admin/dev-tasks");
      } else {
        setError(data.error || "فشل في حفظ المهمة");
      }
    } catch (err) {
      setError("فشل في الاتصال بالخادم");
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (field: string, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    setError(null);
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const fileArray = Array.from(files);
    const validFiles: File[] = [];

    // Validate each file
    for (const file of fileArray) {
      if (file.size > 20 * 1024 * 1024) {
        setError(`حجم الملف ${file.name} يجب أن يكون أقل من 20 ميجابايت`);
        continue;
      }
      if (!file.type.startsWith("image/")) {
        setError(`الملف ${file.name} يجب أن يكون صورة`);
        continue;
      }
      validFiles.push(file);
    }

    // Check total count
    if (selectedImages.length + validFiles.length > 10) {
      setError("الحد الأقصى 10 صور");
      return;
    }

    // Create previews
    validFiles.forEach((file) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreviews((prev) => [...prev, reader.result as string]);
      };
      reader.readAsDataURL(file);
    });

    setSelectedImages((prev) => [...prev, ...validFiles]);
    setError(null);
  };

  const removeImage = (index: number) => {
    setSelectedImages((prev) => prev.filter((_, i) => i !== index));
    setImagePreviews((prev) => prev.filter((_, i) => i !== index));
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 dark:border-indigo-400"></div>
      </div>
    );
  }

  const renderMainForm = () => (
    <div className="space-y-6">
      {error && (
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4 rounded-xl flex items-center gap-2">
          <XMarkIcon className="h-5 w-5 text-red-500" />
          <p className="text-red-700 dark:text-red-400 font-medium">{error}</p>
        </div>
      )}
      {/* Basic Info Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm">
        <h3 className="text-lg font-bold text-gray-900 dark:text-gray-100 mb-6 flex items-center gap-2">
          <SparklesIcon className="h-5 w-5 text-indigo-500" />
          تفاصيل المهمة
        </h3>

        <div className="space-y-6">
          <div>
            <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
              العنوان <span className="text-red-500 dark:text-red-400">*</span>
            </label>
            <input
              type="text"
              value={formData.title}
              onChange={(e) => handleChange("title", e.target.value)}
              placeholder="مثال: إضافة خاصية الدفع الإلكتروني..."
              className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-gray-50 dark:bg-gray-900/50 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 text-lg font-medium transition-all"
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
              الوصف <span className="text-red-500 dark:text-red-400">*</span>
            </label>
            <textarea
              value={formData.description}
              onChange={(e) => handleChange("description", e.target.value)}
              placeholder="وصف تفصيلي للمهمة..."
              rows={8}
              className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-gray-50 dark:bg-gray-900/50 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 resize-none transition-all"
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
              <PhotoIcon className="h-5 w-5 inline-block ml-2" />
              إضافة صور ({selectedImages.length}/10)
            </label>
            <div className="space-y-3">
              {/* Image Previews Grid */}
              {imagePreviews.length > 0 && (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3 mb-3">
                  {imagePreviews.map((preview, index) => (
                    <div key={index} className="relative group">
                      <img
                        src={preview}
                        alt={`Preview ${index + 1}`}
                        className="w-full h-32 object-cover rounded-lg border-2 border-gray-300 dark:border-gray-600"
                      />
                      <button
                        type="button"
                        onClick={() => removeImage(index)}
                        className="absolute top-1 left-1 p-1.5 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors opacity-0 group-hover:opacity-100"
                      >
                        <XMarkIcon className="h-4 w-4" />
                      </button>
                      <div className="absolute bottom-1 right-1 bg-black/60 text-white text-xs px-2 py-0.5 rounded">
                        {selectedImages[index]
                          ? (selectedImages[index].size / 1024 / 1024).toFixed(
                              1,
                            )
                          : "0"}
                        MB
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* Upload Area */}
              {selectedImages.length < 10 && (
                <label className="flex flex-col items-center justify-center w-full h-40 border-2 border-dashed border-indigo-300 dark:border-indigo-600 rounded-xl cursor-pointer bg-gradient-to-br from-indigo-50 to-purple-50 dark:from-indigo-900/20 dark:to-purple-900/20 hover:from-indigo-100 hover:to-purple-100 dark:hover:from-indigo-900/30 dark:hover:to-purple-900/30 transition-all">
                  <div className="flex flex-col items-center justify-center pt-5 pb-6">
                    <PhotoIcon className="h-10 w-10 text-indigo-600 dark:text-indigo-400 mb-2" />
                    <p className="mb-1 text-sm text-gray-700 dark:text-gray-300">
                      <span className="font-bold">📎 اضغط لرفع صور متعددة</span>
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      يمكنك اختيار حتى 10 صور (20MB لكل صورة)
                    </p>
                  </div>
                  <input
                    type="file"
                    className="hidden"
                    accept="image/*"
                    multiple
                    onChange={handleImageChange}
                  />
                </label>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Business & Acceptance */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-blue-50/50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-900/20 p-6">
          <label className="block text-base font-bold text-gray-900 dark:text-gray-100 mb-3 flex items-center gap-2">
            <LightBulbIcon className="h-5 w-5 text-yellow-500" />
            القيمة التجارية (Business Value)
          </label>
          <textarea
            value={formData.businessValue}
            onChange={(e) => handleChange("businessValue", e.target.value)}
            placeholder="لماذا نقوم بهذا العمل؟ ما الفائدة المتوقعة؟"
            rows={5}
            className="w-full px-4 py-3 border border-blue-200 dark:border-blue-800/50 rounded-xl focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 transition-all"
          />
        </div>

        <div className="bg-green-50/50 dark:bg-green-900/10 rounded-xl border border-green-100 dark:border-green-900/20 p-6">
          <label className="block text-base font-bold text-gray-900 dark:text-gray-100 mb-3 flex items-center gap-2">
            <CheckBadgeIcon className="h-5 w-5 text-green-500" />
            معايير القبول (Acceptance Criteria)
          </label>
          <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800/50 rounded-lg p-3 mb-3">
            <p className="text-xs text-yellow-800 dark:text-yellow-300">
              💡 <strong>نصيحة:</strong> اكتب كل معيار في سطر منفصل، سيتم عرضها
              كقائمة تحقق تلقائياً
            </p>
          </div>
          <textarea
            value={formData.acceptanceCriteria}
            onChange={(e) => handleChange("acceptanceCriteria", e.target.value)}
            placeholder="- يجب أن يعمل X عند الضغط على Y&#10;- يجب أن تظهر رسالة نجاح&#10;- يجب حفظ البيانات في قاعدة البيانات"
            rows={5}
            className="w-full px-4 py-3 border border-green-200 dark:border-green-800/50 rounded-xl focus:ring-2 focus:ring-green-500 dark:focus:ring-green-400 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 transition-all"
          />
        </div>
      </div>

      {/* Checklists */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm">
        <h3 className="text-lg font-bold text-gray-900 dark:text-gray-100 mb-4 flex items-center gap-2">
          <CheckBadgeIcon className="h-5 w-5 text-indigo-500" />
          قوائم التحقق المبدئية
        </h3>
        <div className="space-y-3">
          <div className="flex gap-2">
            <input
              ref={checklistInputRef}
              type="text"
              placeholder="أضف عنصر للقائمة..."
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  const val = e.currentTarget.value.trim();
                  if (val) {
                    setChecklistItems([...checklistItems, val]);
                    e.currentTarget.value = "";
                  }
                }
              }}
              className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            />
            <button
              type="button"
              onClick={() => {
                const val = checklistInputRef.current?.value.trim();
                if (val) {
                  setChecklistItems([...checklistItems, val]);
                  if (checklistInputRef.current) {
                    checklistInputRef.current.value = "";
                  }
                }
              }}
              className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 rounded-lg text-white font-medium transition-colors"
            >
              إضافة
            </button>
          </div>
          <ul className="space-y-2">
            {checklistItems.map((item, idx) => (
              <li
                key={idx}
                className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-700/50 rounded-lg group"
              >
                <div className="flex items-center gap-3 flex-1">
                  <CheckCircleIcon className="h-5 w-5 text-green-500 flex-shrink-0" />
                  <span className="text-gray-700 dark:text-gray-300">
                    {item}
                  </span>
                </div>
                <button
                  type="button"
                  onClick={() =>
                    setChecklistItems(
                      checklistItems.filter((_, i) => i !== idx),
                    )
                  }
                  className="text-red-500 opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0"
                >
                  <XMarkIcon className="h-4 w-4" />
                </button>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Related Links */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 shadow-sm mt-6">
        <h3 className="text-lg font-bold text-gray-900 dark:text-gray-100 mb-4 flex items-center gap-2">
          <ArrowRightIcon className="h-5 w-5 text-indigo-500 rotate-45" />
          الروابط المرتبطة (Related Links)
        </h3>
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <input
              type="text"
              placeholder="عنوان الرابط (مثال: صفحة المشكلة)"
              value={newLinkTitle}
              onChange={(e) => setNewLinkTitle(e.target.value)}
              className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            />
            <div className="flex gap-2">
              <input
                type="text"
                placeholder="الرابط (URL)"
                value={newLinkUrl}
                onChange={(e) => setNewLinkUrl(e.target.value)}
                className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
              />
              <button
                type="button"
                onClick={() => {
                  if (newLinkTitle.trim() && newLinkUrl.trim()) {
                    setFormData((prev) => ({
                      ...prev,
                      relatedLinks: [
                        ...prev.relatedLinks,
                        { title: newLinkTitle.trim(), url: newLinkUrl.trim() },
                      ],
                    }));
                    setNewLinkTitle("");
                    setNewLinkUrl("");
                  }
                }}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 rounded-lg text-white font-medium transition-colors"
              >
                إضافة
              </button>
            </div>
          </div>

          <ul className="space-y-2">
            {formData.relatedLinks.map((link, idx) => (
              <li
                key={idx}
                className="flex items-center justify-between p-3 bg-indigo-50/30 dark:bg-indigo-900/10 rounded-lg border border-indigo-100 dark:border-indigo-900/20 group"
              >
                <div className="flex items-center gap-3 overflow-hidden">
                  <ArrowRightIcon className="h-4 w-4 text-indigo-500 flex-shrink-0 rotate-45" />
                  <div className="flex flex-col min-w-0">
                    <span className="font-bold text-gray-900 dark:text-gray-100 text-sm truncate">
                      {link.title}
                    </span>
                    <span className="text-gray-500 dark:text-gray-400 text-xs truncate dir-ltr text-right">
                      {link.url}
                    </span>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() =>
                    setFormData((prev) => ({
                      ...prev,
                      relatedLinks: prev.relatedLinks.filter(
                        (_, i) => i !== idx,
                      ),
                    }))
                  }
                  className="text-red-500 opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0"
                >
                  <XMarkIcon className="h-4 w-4" />
                </button>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );

  const renderSidebarForm = () => (
    <div className="space-y-6">
      {/* Primary Actions Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-5 shadow-sm">
        <div className="mb-5">
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
            الحالة
          </label>
          <select
            value={formData.status}
            onChange={(e) => handleChange("status", e.target.value)}
            className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:border-indigo-500 dark:text-white font-medium"
          >
            {(settings?.taskStatuses || STATUS_OPTIONS).map((option: any) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </div>

        <div className="mb-5">
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
            الأولوية
          </label>
          <div className="grid grid-cols-3 gap-2">
            {(settings?.taskPriorities || PRIORITY_OPTIONS).map(
              (option: any) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => handleChange("priority", option.value)}
                  className={`px-2 py-2 text-xs font-bold rounded-lg border transition-all ${
                    formData.priority === option.value
                      ? "border-indigo-500 bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400"
                      : "border-gray-200 text-gray-600 hover:bg-gray-50 dark:border-gray-700 dark:text-gray-400 dark:hover:bg-gray-700"
                  }`}
                >
                  {option.label}
                </button>
              ),
            )}
          </div>
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
            النوع
          </label>
          <select
            value={formData.type}
            onChange={(e) => handleChange("type", e.target.value)}
            className="w-full px-4 py-2.5 bg-gray-50 dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-indigo-500 dark:border-indigo-500 dark:text-white"
          >
            {TYPE_OPTIONS.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Assignment Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-5 shadow-sm">
        <h4 className="font-semibold text-gray-900 dark:text-gray-100 mb-4 border-b border-gray-100 dark:border-gray-700 pb-2">
          التعيين
        </h4>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              المسؤول
            </label>
            <select
              value={formData.assigneeId}
              onChange={(e) => handleChange("assigneeId", e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            >
              <option value="">اختر المسؤول...</option>
              {teamMembers.map((m) => (
                <option key={m.id} value={m.id}>
                  {m.name}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              المراقبون
            </label>
            <select
              multiple
              value={watchers}
              onChange={(e) =>
                setWatchers(
                  Array.from(e.target.selectedOptions, (o) => o.value),
                )
              }
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white h-24 text-sm"
            >
              {teamMembers.map((m) => (
                <option key={m.id} value={m.id}>
                  {m.name}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Context Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-5 shadow-sm">
        <h4 className="font-semibold text-gray-900 dark:text-gray-100 mb-4 border-b border-gray-100 dark:border-gray-700 pb-2">
          السياق
        </h4>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              المشروع
            </label>
            <select
              value={formData.projectId}
              onChange={(e) => handleChange("projectId", e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            >
              <option value="">بدون ملف مشروع</option>
              {projects.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.name}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              الإصدار (Release)
            </label>
            <select
              value={formData.releaseId}
              onChange={(e) => handleChange("releaseId", e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            >
              <option value="">بدون إصدار</option>
              {releases.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.name} (v{r.version})
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              Component
            </label>
            <select
              value={formData.component}
              onChange={(e) => handleChange("component", e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            >
              <option value="">General</option>
              {derivedComponentOptions.map((c) => (
                <option key={c.value} value={c.value}>
                  {c.label}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Dates & Time Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-5 shadow-sm">
        <h4 className="font-semibold text-gray-900 dark:text-gray-100 mb-4 border-b border-gray-100 dark:border-gray-700 pb-2">
          التوقيت
        </h4>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              تاريخ البدء
            </label>
            <input
              type="date"
              value={formData.startDate}
              onChange={(e) => handleChange("startDate", e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              تاريخ الاستحقاق{" "}
              <span className="text-red-500 dark:text-red-400">*</span>
            </label>
            <input
              type="date"
              value={formData.dueDate}
              onChange={(e) => handleChange("dueDate", e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
              ساعات تقديرية
            </label>
            <input
              type="number"
              placeholder="0.0"
              step="0.5"
              value={formData.estimatedHours}
              onChange={(e) => handleChange("estimatedHours", e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
            />
          </div>
        </div>
      </div>

      {/* Tags Card */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-5 shadow-sm">
        <label className="block text-sm font-medium text-gray-600 dark:text-gray-400 mb-2">
          الوسوم (مفصول بفاصلة)
        </label>
        <input
          type="text"
          value={formData.tags}
          onChange={(e) => handleChange("tags", e.target.value)}
          placeholder="react, api, ui..."
          className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-700 dark:text-white"
        />
      </div>
    </div>
  );

  return (
    <div className="max-w-[1600px] mx-auto p-6" dir="rtl">
      {/* Page Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate(-1)}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-xl transition-colors"
          >
            <ArrowRightIcon className="h-6 w-6 text-gray-600 dark:text-gray-400" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
              {isEdit ? (
                <PencilIcon className="h-8 w-8 text-indigo-500" />
              ) : (
                <SparklesIcon className="h-8 w-8 text-indigo-500" />
              )}
              {isEdit ? "تعديل المهمة" : "إنشاء مهمة جديدة"}
            </h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">
              {isEdit
                ? `تحديث بيانات المهمة #${id?.slice(0, 8)}`
                : "أضف مهمة جديدة إلى خطة التطوير"}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={() => setAiModalOpen(true)}
            className="px-5 py-2.5 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-purple-500/30 hover:shadow-purple-500/50 hover:scale-105 transition-all flex items-center gap-2"
          >
            <SparklesIcon className="w-5 h-5" />
            مساعد AI
          </button>
        </div>
      </div>

      {/* AI Modal (Preserved) */}
      {aiModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 rounded-2xl w-full max-w-2xl shadow-2xl border border-gray-200 dark:border-gray-700 overflow-hidden transform transition-all">
            <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-800/50">
              <div className="flex items-center gap-2">
                <div className="p-2 bg-purple-100 dark:bg-purple-900/30 rounded-lg">
                  <SparklesIcon className="w-6 h-6 text-purple-600 dark:text-purple-400" />
                </div>
                <div>
                  <h3 className="text-lg font-bold text-gray-900 dark:text-gray-100">
                    مساعد المهام الذكي
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    سأقوم بملء التفاصيل نيابة عنك
                  </p>
                </div>
              </div>
              <button
                onClick={() => setAiModalOpen(false)}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
              >
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6">
              <div className="flex bg-gray-100 dark:bg-gray-700/50 rounded-lg p-1 mb-6">
                <button
                  onClick={() => setAiMode("description")}
                  className={`flex-1 py-2 px-4 rounded-md text-sm font-medium transition-all ${
                    aiMode === "description"
                      ? "bg-white dark:bg-gray-600 text-gray-900 dark:text-white shadow-sm"
                      : "text-gray-500 dark:text-gray-400 hover:text-gray-700"
                  }`}
                >
                  📝 وصف الفكرة
                </button>
                <button
                  onClick={() => setAiMode("error")}
                  className={`flex-1 py-2 px-4 rounded-md text-sm font-medium transition-all ${
                    aiMode === "error"
                      ? "bg-white dark:bg-gray-600 text-gray-900 dark:text-white shadow-sm"
                      : "text-gray-500 dark:text-gray-400 hover:text-gray-700"
                  }`}
                >
                  🐛 تحليل خطأ (Log)
                </button>
              </div>

              <div className="mb-6">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  {aiMode === "description"
                    ? "اوصف المهمة التي تريد إنشاءها:"
                    : "الصق سجل الخطأ (Error Log) هنا:"}
                </label>
                <textarea
                  value={aiPrompt}
                  onChange={(e) => setAiPrompt(e.target.value)}
                  placeholder={
                    aiMode === "description"
                      ? "مثال: أريد إضافة زر لتصدير التقارير بصيغة PDF في صفحة المبيعات..."
                      : "TypeError: Cannot read property of undefined..."
                  }
                  className="w-full h-40 px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-purple-500 bg-gray-50 dark:bg-gray-900/50 text-gray-900 dark:text-gray-100 resize-none font-mono text-sm"
                />
              </div>

              <div className="flex gap-3 justify-end">
                <button
                  onClick={() => setAiModalOpen(false)}
                  className="px-5 py-2.5 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-xl font-medium"
                >
                  إلغاء
                </button>
                <button
                  onClick={handleAiGenerate}
                  disabled={aiGenerating || !aiPrompt.trim()}
                  className="px-6 py-2.5 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white rounded-xl font-medium shadow-lg shadow-purple-500/20 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                >
                  {aiGenerating ? (
                    <>
                      <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                      جاري التحليل...
                    </>
                  ) : (
                    <>
                      <SparklesIcon className="w-5 h-5" />
                      توليد المهمة
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="mt-8">
        <div className="grid grid-cols-12 gap-8">
          {/* Main Content (8 cols) */}
          <div className="col-span-12 lg:col-span-8">
            {renderMainForm()}

            {/* Form Actions */}
            <div className="mt-8 flex items-center justify-end gap-4">
              <button
                type="button"
                onClick={() => navigate(-1)}
                className="px-6 py-3 border border-gray-300 dark:border-gray-600 rounded-xl text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 bg-white dark:bg-gray-800 font-medium transition-colors"
              >
                إلغاء
              </button>
              <button
                type="submit"
                disabled={saving}
                className="px-8 py-3 bg-indigo-600 dark:bg-indigo-500 text-white rounded-xl hover:bg-indigo-700 dark:hover:bg-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 font-bold shadow-lg shadow-indigo-500/20"
              >
                {saving ? (
                  <>
                    <div className="animate-spin rounded-full h-5 w-5 border-2 border-white/30 border-t-white"></div>
                    جاري الحفظ...
                  </>
                ) : isEdit ? (
                  "حفظ التعديلات"
                ) : (
                  "إنشاء المهمة"
                )}
              </button>
            </div>
          </div>

          {/* Sidebar (4 cols) */}
          <div className="col-span-12 lg:col-span-4">{renderSidebarForm()}</div>
        </div>
      </form>
    </div>
  );
};

export default DevTaskForm;

import React, { useState, useEffect, useRef } from "react";
import { buildApiUrl } from "../../utils/urlHelper";
import tokenManager from "../../utils/tokenManager";
import {
  Cog6ToothIcon,
  SwatchIcon,
  ShieldCheckIcon,
  BoltIcon,
  PlusIcon,
  TrashIcon,
  CheckCircleIcon,
  TrophyIcon,
  ClockIcon,
} from "@heroicons/react/24/outline";

interface StatusItem {
  value: string;
  label: string;
  color: string;
}

interface PermissionRule {
  // Task Permissions
  canCreate: boolean;
  canEdit: boolean;
  canDelete: boolean;
  canComment: boolean;
  canAssign: boolean;
  canChangeStatus: boolean;
  canArchive: boolean;
  // Project & Reports
  canViewReports: boolean;
  canManageProjects: boolean;
  canExport: boolean;
  // Settings Access
  canAccessSettings: boolean;
  canManageTaskSettings: boolean;
  // Users & Admin
  canViewAll: boolean; // 🔐 NEW: View all users in admin panel
  // View Scope
  viewScope: "all" | "project" | "assigned_only";
}

interface ComponentMapping {
  [componentName: string]: string; // memberId
}

interface LeaderboardSettings {
  baseXP: number;
  taskTypeScores: {
    [key: string]: number;
  };
  priorityScores: {
    [key: string]: number;
  };
  timeBasedScoring?: {
    enabled: boolean;
    earlyCompletionBonus: number;
    onTimeBonus: number;
    lateCompletionPenalty: number;
    maxBonusPercent: number;
    maxPenaltyPercent: number;
  };
}

interface TaskDetailsVisibility {
  showDescription: boolean;
  showRelatedLinks: boolean;
  showChecklists: boolean;
  showBusinessValue: boolean;
  showAcceptanceCriteria: boolean;
  showAttachments: boolean;
  showCreatedAt: boolean;
}

interface AutomationRule {
  threshold: number;
  unit: "hours" | "days";
  scope: "all" | string;
  action: "assign";
  targetId: string;
}

interface AutomationSettings {
  rules: AutomationRule[];
}

interface SettingsData {
  taskStatuses: StatusItem[];
  taskPriorities: StatusItem[];
  permissions: Record<string, PermissionRule>;
  componentMappings: ComponentMapping;
  autoTestingSubtask?: boolean;
  autoTestingAssigneeId?: string | null;
  leaderboardSettings?: LeaderboardSettings;
  taskDetailsVisibility?: TaskDetailsVisibility;
  automationSettings?: AutomationSettings;
  timezone?: string;
}

interface DevTeamMember {
  id: string;
  name: string;
  role: string;
}

const DEFAULT_STATUS_COLOR = "#cbd5e1";

const isValidHexColor = (value?: string | null): value is string =>
  typeof value === "string" && /^#[0-9a-f]{6}$/i.test(value);

const getSafeHexColor = (value?: string | null) =>
  isValidHexColor(value) ? value : DEFAULT_STATUS_COLOR;

const sanitizeStatusItems = (items?: StatusItem[]) =>
  Array.isArray(items)
    ? items.map((item) => ({
        ...item,
        color: getSafeHexColor(item.color),
      }))
    : [];

const DevTaskSettings = () => {
  const [activeTab, setActiveTab] = useState<
    "general" | "permissions" | "automation" | "leaderboard" | "visibility"
  >("general");
  const [settings, setSettings] = useState<SettingsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [teamMembers, setTeamMembers] = useState<DevTeamMember[]>([]);

  const newComponentNameRef = useRef<HTMLInputElement>(null);
  const newComponentOwnerRef = useRef<HTMLSelectElement>(null);
  const ruleThresholdRef = useRef<HTMLInputElement>(null);
  const ruleUnitRef = useRef<HTMLSelectElement>(null);
  const ruleScopeRef = useRef<HTMLSelectElement>(null);
  const ruleTargetRef = useRef<HTMLSelectElement>(null);
  useEffect(() => {
    fetchSettings();
    fetchTeam();
  }, []);

  const fetchSettings = async () => {
    try {
      const res = await fetch(buildApiUrl("super-admin/dev/settings"), {
        headers: tokenManager.createAuthHeaders(),
      });
      const data = await res.json();
      if (data.success) {
        setSettings({
          ...data.data,
          taskStatuses: sanitizeStatusItems(data.data.taskStatuses),
          taskPriorities: sanitizeStatusItems(data.data.taskPriorities),
        });
      }
    } catch (error) {
      console.error("Failed to fetch settings", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchTeam = async () => {
    try {
      const res = await fetch(buildApiUrl("super-admin/dev/team"), {
        headers: tokenManager.createAuthHeaders(),
      });
      const data = await res.json();
      if (data.success) {
        setTeamMembers(data.data);
      }
    } catch (error) {
      console.error("Failed to fetch team", error);
    }
  };

  const handleSave = async () => {
    if (!settings) return;
    setSaving(true);
    try {
      // Ensure leaderboardSettings is complete before saving
      const settingsToSave = {
        ...settings,
        leaderboardSettings: settings.leaderboardSettings
          ? {
              baseXP: settings.leaderboardSettings.baseXP || 10,
              taskTypeScores: settings.leaderboardSettings.taskTypeScores || {},
              priorityScores: settings.leaderboardSettings.priorityScores || {},
              timeBasedScoring: settings.leaderboardSettings
                .timeBasedScoring || {
                enabled: true,
                earlyCompletionBonus: 20,
                onTimeBonus: 10,
                lateCompletionPenalty: 15,
                maxBonusPercent: 50,
                maxPenaltyPercent: 30,
              },
            }
          : undefined,
        automationSettings: settings.automationSettings
          ? {
              rules: settings.automationSettings.rules || [],
            }
          : undefined,
      };

      const res = await fetch(buildApiUrl("super-admin/dev/settings"), {
        method: "PUT",
        headers: tokenManager.createAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(settingsToSave),
      });
      const data = await res.json();
      if (data.success) {
        alert("تم حفظ الإعدادات بنجاح");
        // Refresh settings to confirm save
        await fetchSettings();
      } else {
        alert("فشل الحفظ: " + (data.message || "خطأ غير معروف"));
      }
    } catch (error) {
      console.error("❌ Save error:", error);
      alert("حدث خطأ أثناء الحفظ");
    } finally {
      setSaving(false);
    }
  };

  const updateStatus = (
    index: number,
    field: keyof StatusItem,
    value: string,
  ) => {
    if (!settings) return;
    const newStatuses = [...settings.taskStatuses];
    newStatuses[index] = {
      ...newStatuses[index],
      [field]: value,
    } as StatusItem;
    setSettings({ ...settings, taskStatuses: newStatuses });
  };

  const addStatus = () => {
    if (!settings) return;
    setSettings({
      ...settings,
      taskStatuses: [
        ...settings.taskStatuses,
        { value: "NEW_STATUS", label: "New Status", color: "#cbd5e1" },
      ],
    });
  };

  const removeStatus = (index: number) => {
    if (!settings) return;
    const newStatuses = settings.taskStatuses.filter((_, i) => i !== index);
    setSettings({ ...settings, taskStatuses: newStatuses });
  };

  if (loading) return <div className="p-10 text-center">جاري التحميل...</div>;
  if (!settings)
    return (
      <div className="p-10 text-center text-red-500">فشل تحميل الإعدادات</div>
    );

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 flex items-center gap-2">
            <Cog6ToothIcon className="h-8 w-8 text-indigo-500" />
            إعدادات نظام المهام
          </h1>
          <p className="text-gray-500 text-sm mt-1">
            تخصيص الحالات، الصلاحيات، والتشغيل الآلي
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={saving}
          className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2"
        >
          {saving ? (
            "جاري الحفظ..."
          ) : (
            <>
              <CheckCircleIcon className="h-5 w-5" />
              حفظ التغييرات
            </>
          )}
        </button>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-gray-200 dark:border-gray-700">
        <button
          onClick={() => setActiveTab("general")}
          className={`px-6 py-3 font-medium text-sm flex items-center gap-2 ${activeTab === "general" ? "border-b-2 border-indigo-500 text-indigo-600" : "text-gray-500 hover:text-gray-700"}`}
        >
          <SwatchIcon className="h-4 w-4" />
          الحالات والأولويات
        </button>
        <button
          onClick={() => setActiveTab("permissions")}
          className={`px-6 py-3 font-medium text-sm flex items-center gap-2 ${activeTab === "permissions" ? "border-b-2 border-indigo-500 text-indigo-600" : "text-gray-500 hover:text-gray-700"}`}
        >
          <ShieldCheckIcon className="h-4 w-4" />
          الصلاحيات والأدوار
        </button>
        <button
          onClick={() => setActiveTab("automation")}
          className={`px-6 py-3 font-medium text-sm flex items-center gap-2 ${activeTab === "automation" ? "border-b-2 border-indigo-500 text-indigo-600" : "text-gray-500 hover:text-gray-700"}`}
        >
          <BoltIcon className="h-4 w-4" />
          الأقسام والتعيين التلقائي
        </button>
        <button
          onClick={() => setActiveTab("leaderboard")}
          className={`px-6 py-3 font-medium text-sm flex items-center gap-2 ${activeTab === "leaderboard" ? "border-b-2 border-indigo-500 text-indigo-600" : "text-gray-500 hover:text-gray-700"}`}
        >
          <TrophyIcon className="h-4 w-4" />
          لوحة الأبطال
        </button>
        <button
          onClick={() => setActiveTab("visibility")}
          className={`px-6 py-3 font-medium text-sm flex items-center gap-2 ${activeTab === "visibility" ? "border-b-2 border-indigo-500 text-indigo-600" : "text-gray-500 hover:text-gray-700"}`}
        >
          <Cog6ToothIcon className="h-4 w-4" />
          عرض تفاصيل المهمة
        </button>
      </div>

      {/* Content */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6">
        {activeTab === "general" && (
          <div className="space-y-8">
            {/* Timezone Settings */}
            <div className="bg-indigo-50 dark:bg-indigo-900/10 p-4 rounded-lg border border-indigo-100 dark:border-indigo-900/30">
              <div className="flex items-center gap-3 mb-4">
                <ClockIcon className="h-5 w-5 text-indigo-600" />
                <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                  إعدادات المنطقة الزمنية
                </h3>
              </div>
              <div className="max-w-md">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  المنطقة الزمنية للنظام
                </label>
                <select
                  id="system-timezone"
                  name="systemTimezone"
                  aria-label="المنطقة الزمنية للنظام"
                  value={settings.timezone || "UTC"}
                  onChange={(e) =>
                    setSettings({ ...settings, timezone: e.target.value })
                  }
                  className="w-full border rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 dark:border-gray-600 focus:ring-2 focus:ring-indigo-500"
                >
                  <option value="UTC">UTC (Universal Time)</option>
                  <option value="Africa/Cairo">القاهرة (EET - UTC+2/3)</option>
                  <option value="Asia/Riyadh">الرياض (AST - UTC+3)</option>
                  <option value="Asia/Dubai">دبي (GST - UTC+4)</option>
                  <option value="Europe/London">لندن (GMT - UTC+0/1)</option>
                  <option value="America/New_York">
                    نيويورك (EST - UTC-5/4)
                  </option>
                </select>
                <p className="text-xs text-gray-500 mt-2">
                  تستخدم هذه المنطقة الزمنية في حسابات الـ "Dashboard" والتقارير
                  اليومية لضمان دقة البيانات حسب توقيت شركتك.
                </p>
              </div>
            </div>

            {/* Task Statuses */}
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                  حالات المهام (Statuses)
                </h3>
                <button
                  onClick={addStatus}
                  className="text-sm text-indigo-600 hover:text-indigo-700 flex items-center gap-1"
                >
                  <PlusIcon className="h-4 w-4" /> إضافة حالة
                </button>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-right">
                  <thead className="text-gray-500 bg-gray-50 dark:bg-gray-700/50 uppercase">
                    <tr>
                      <th className="px-4 py-3">الكود (Value)</th>
                      <th className="px-4 py-3">الاسم الظاهر (Label)</th>
                      <th className="px-4 py-3">اللون</th>
                      <th className="px-4 py-3">إجراءات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                    {settings.taskStatuses.map((status, idx) => (
                      <tr key={idx}>
                        <td className="px-4 py-2">
                          <input
                            id={`status-value-${idx}`}
                            name={`statusValue-${idx}`}
                            aria-label={`كود الحالة ${idx + 1}`}
                            value={status.value}
                            onChange={(e) =>
                              updateStatus(idx, "value", e.target.value)
                            }
                            className="w-full bg-transparent border-none focus:ring-0"
                          />
                        </td>
                        <td className="px-4 py-2">
                          <input
                            id={`status-label-${idx}`}
                            name={`statusLabel-${idx}`}
                            aria-label={`اسم الحالة ${idx + 1}`}
                            value={status.label}
                            onChange={(e) =>
                              updateStatus(idx, "label", e.target.value)
                            }
                            className="w-full border rounded px-2 py-1 dark:bg-gray-700 dark:border-gray-600"
                          />
                        </td>
                        <td className="px-4 py-2 flex items-center gap-2">
                          <input
                            id={`status-color-${idx}`}
                            name={`statusColor-${idx}`}
                            aria-label={`لون الحالة ${idx + 1}`}
                            type="color"
                            value={getSafeHexColor(status.color)}
                            onChange={(e) =>
                              updateStatus(idx, "color", e.target.value)
                            }
                            className="h-8 w-8 rounded cursor-pointer"
                          />
                          <span className="text-xs text-gray-400">
                            {getSafeHexColor(status.color)}
                          </span>
                        </td>
                        <td className="px-4 py-2">
                          <button
                            onClick={() => removeStatus(idx)}
                            className="text-red-500 hover:text-red-700"
                          >
                            <TrashIcon className="h-4 w-4" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === "permissions" && (
          <div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
              صلاحيات الأدوار
            </h3>
            <p className="text-sm text-gray-500 mb-6">
              حدد ما يمكن لكل دور القيام به في نظام المهام.
            </p>

            <div className="space-y-6">
              {(() => {
                // Get roles from settings permissions (the source of truth)
                const rolesFromSettings = settings?.permissions
                  ? Object.keys(settings.permissions)
                  : [];
                // Also include any roles from current team members that aren't in settings
                const teamRoles = teamMembers
                  .map((m) => m.role)
                  .filter(Boolean);

                // 🔐 SECURITY: Filter out tenant roles (OWNER, AGENT, COMPANY_ADMIN)
                // These roles belong to companies, not the system administration/dev team.
                const tenantRoles = [
                  "OWNER",
                  "AGENT",
                  "Agent",
                  "COMPANY_ADMIN",
                ];

                const allRoles = Array.from(
                  new Set([...rolesFromSettings, ...teamRoles]),
                )
                  .filter((role) => !tenantRoles.includes(role))
                  .sort();

                return allRoles.map((role) => {
                  const perm = settings.permissions[role] || {
                    canCreate: false,
                    canEdit: false,
                    canDelete: false,
                    canChangeStatus: false,
                    canComment: true,
                    canAssign: false,
                    canArchive: false,
                    canViewReports: false,
                    canManageProjects: false,
                    canExport: false,
                    canAccessSettings: false,
                    canManageTaskSettings: false,
                    canViewAll: false, // 🔐 NEW
                    viewScope: "assigned_only",
                  };

                  return (
                    <div
                      key={role}
                      className="border rounded-lg p-4 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/30"
                    >
                      <h4 className="font-bold text-indigo-600 mb-3 capitalize text-lg">
                        {role}
                      </h4>

                      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        {/* Task Actions */}
                        <div className="space-y-3">
                          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            صلاحيات المهام
                          </p>
                          <div className="grid grid-cols-2 gap-2">
                            {[
                              { key: "canCreate", label: "إنشاء مهام" },
                              { key: "canEdit", label: "تعديل مهام" },
                              { key: "canDelete", label: "حذف مهام" },
                              { key: "canChangeStatus", label: "تغيير الحالة" },
                              { key: "canComment", label: "إضافة تعليق" },
                              { key: "canAssign", label: "تعيين مسؤولين" },
                              { key: "canArchive", label: "أرشفة المهام" },
                            ].map(({ key, label }) => (
                              <label
                                key={key}
                                className="flex items-center gap-2 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 p-1 rounded"
                              >
                                <input
                                  type="checkbox"
                                  checked={(perm as any)[key]}
                                  onChange={(e) => {
                                    const newPerms = {
                                      ...settings.permissions,
                                    };
                                    newPerms[role] = {
                                      ...perm,
                                      [key]: e.target.checked,
                                    };
                                    setSettings({
                                      ...settings,
                                      permissions: newPerms,
                                    });
                                  }}
                                  className="rounded text-indigo-600 focus:ring-indigo-500 cursor-pointer h-4 w-4 border-gray-300"
                                />
                                <span className="text-sm text-gray-700 dark:text-gray-300">
                                  {label}
                                </span>
                              </label>
                            ))}
                          </div>
                        </div>

                        {/* Project & Reports */}
                        <div className="space-y-3">
                          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            المشاريع والتقارير
                          </p>
                          <div className="grid grid-cols-2 gap-2">
                            {[
                              { key: "canViewReports", label: "عرض التقارير" },
                              {
                                key: "canManageProjects",
                                label: "إدارة المشاريع",
                              },
                              { key: "canExport", label: "تصدير البيانات" },
                            ].map(({ key, label }) => (
                              <label
                                key={key}
                                className="flex items-center gap-2 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 p-1 rounded"
                              >
                                <input
                                  type="checkbox"
                                  checked={(perm as any)[key]}
                                  onChange={(e) => {
                                    const newPerms = {
                                      ...settings.permissions,
                                    };
                                    newPerms[role] = {
                                      ...perm,
                                      [key]: e.target.checked,
                                    };
                                    setSettings({
                                      ...settings,
                                      permissions: newPerms,
                                    });
                                  }}
                                  className="rounded text-indigo-600 focus:ring-indigo-500 cursor-pointer h-4 w-4 border-gray-300"
                                />
                                <span className="text-sm text-gray-700 dark:text-gray-300">
                                  {label}
                                </span>
                              </label>
                            ))}
                          </div>
                        </div>

                        {/* Settings Access */}
                        <div className="space-y-3">
                          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            الوصول للإعدادات والمستخدمين
                          </p>
                          <div className="grid grid-cols-2 gap-2">
                            {[
                              {
                                key: "canAccessSettings",
                                label: "الوصول للإعدادات",
                              },
                              {
                                key: "canManageTaskSettings",
                                label: "إدارة إعدادات المهام",
                              },
                              {
                                key: "canViewAll",
                                label: "عرض جميع المستخدمين",
                              },
                            ].map(({ key, label }) => (
                              <label
                                key={key}
                                className="flex items-center gap-2 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 p-1 rounded"
                              >
                                <input
                                  type="checkbox"
                                  checked={(perm as any)[key]}
                                  onChange={(e) => {
                                    const newPerms = {
                                      ...settings.permissions,
                                    };
                                    newPerms[role] = {
                                      ...perm,
                                      [key]: e.target.checked,
                                    };
                                    setSettings({
                                      ...settings,
                                      permissions: newPerms,
                                    });
                                  }}
                                  className="rounded text-indigo-600 focus:ring-indigo-500 cursor-pointer h-4 w-4 border-gray-300"
                                />
                                <span className="text-sm text-gray-700 dark:text-gray-300">
                                  {label}
                                </span>
                              </label>
                            ))}
                          </div>
                        </div>

                        {/* Scope */}
                        <div>
                          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                            نطاق الرؤية
                          </p>
                          <select
                            id={`permission-view-scope-${role}`}
                            name={`permissionViewScope-${role}`}
                            aria-label={`نطاق الرؤية للدور ${role}`}
                            value={perm.viewScope}
                            onChange={(e) => {
                              const newPerms = { ...settings.permissions };
                              newPerms[role] = {
                                ...perm,
                                viewScope: e.target.value as any,
                              };
                              setSettings({
                                ...settings,
                                permissions: newPerms,
                              });
                            }}
                            className="w-full border rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 dark:border-gray-600 focus:ring-2 focus:ring-indigo-500"
                          >
                            <option value="all">
                              الكل (جميع المشاريع والمهام)
                            </option>
                            <option value="project">نفس المشروع فقط</option>
                            <option value="assigned_only">
                              مهامي فقط (المسندة لي)
                            </option>
                          </select>
                          <p className="text-xs text-gray-400 mt-2">
                            يحدد هذا الخيار المهام التي يمكن للمستخدم رؤيتها في
                            القائمة.
                          </p>
                        </div>
                      </div>
                    </div>
                  );
                });
              })()}
            </div>
          </div>
        )}

        {activeTab === "automation" && (
          <div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
              أقسام العمل والمسؤولين
            </h3>
            <p className="text-sm text-gray-500 mb-6">
              قم بتعريف الأقسام (مثل: Frontend, Mobile) وتعيين مسؤول لكل قسم.{" "}
              <br /> عند اختيار القسم في المهمة، سيتم تعيين المسؤول تلقائياً.
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
              <input
                id="new-component-name"
                name="newComponentName"
                aria-label="اسم القسم الجديد"
                ref={newComponentNameRef}
                placeholder="اسم القسم (مثال: Mobile App)"
                className="border rounded px-3 py-2 dark:bg-gray-700 dark:border-gray-600"
              />
              <div className="flex gap-2">
                <select
                  id="new-component-owner"
                  name="newComponentOwner"
                  aria-label="المسؤول عن القسم الجديد"
                  ref={newComponentOwnerRef}
                  className="border rounded px-3 py-2 flex-1 dark:bg-gray-700 dark:border-gray-600"
                >
                  <option value="">اختر المسؤول...</option>
                  {teamMembers.map((m) => (
                    <option key={m.id} value={m.id}>
                      {m.name}
                    </option>
                  ))}
                </select>
                <button
                  onClick={() => {
                    const nameEl = newComponentNameRef.current;
                    const ownerEl = newComponentOwnerRef.current;
                    if (nameEl?.value && ownerEl?.value) {
                      setSettings({
                        ...settings,
                        componentMappings: {
                          ...settings.componentMappings,
                          [nameEl.value]: ownerEl.value,
                        },
                      });
                      nameEl.value = "";
                      ownerEl.value = "";
                    }
                  }}
                  className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
                >
                  إضافة
                </button>
              </div>
            </div>

            <ul className="space-y-2">
              {Object.entries(settings.componentMappings).map(
                ([comp, memberId]) => {
                  const member = teamMembers.find((m) => m.id === memberId);
                  return (
                    <li
                      key={comp}
                      className="flex items-center justify-between bg-gray-50 dark:bg-gray-700/50 p-3 rounded border border-gray-100 dark:border-gray-600"
                    >
                      <div className="flex items-center gap-3">
                        <span className="font-medium text-gray-800 dark:text-gray-200">
                          {comp}
                        </span>
                        <span className="text-gray-400">→</span>
                        <span className="text-indigo-600 dark:text-indigo-400 text-sm">
                          {member ? member.name : "Unknown Member"}
                        </span>
                      </div>
                      <button
                        onClick={() => {
                          const newMap = { ...settings.componentMappings };
                          delete newMap[comp];
                          setSettings({
                            ...settings,
                            componentMappings: newMap,
                          });
                        }}
                        className="text-red-500 hover:text-red-700"
                      >
                        <TrashIcon className="h-4 w-4" />
                      </button>
                    </li>
                  );
                },
              )}
            </ul>
          </div>
        )}
        {/* Auto-Creation Setting */}
        {activeTab === "automation" && (
          <div className="mt-8 pt-8 border-t border-gray-100 dark:border-gray-700">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
              التشغيل الآلي للمهام
            </h3>

            <div className="bg-gray-50 dark:bg-gray-700/30 p-4 rounded-lg border border-gray-100 dark:border-gray-600">
              <label className="flex items-start gap-3 cursor-pointer">
                <div className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    className="sr-only peer"
                    checked={settings.autoTestingSubtask || false}
                    onChange={(e) =>
                      setSettings({
                        ...settings,
                        autoTestingSubtask: e.target.checked,
                      })
                    }
                  />
                  <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 dark:peer-focus:ring-indigo-800 rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-indigo-600"></div>
                </div>
                <div>
                  <span className="block font-medium text-gray-900 dark:text-gray-100">
                    إنشاء مهمة اختبار تلقائياً عند الاكتمال
                  </span>
                  <span className="block text-sm text-gray-500 mt-1">
                    عند تحويل حالة أي مهمة إلى "DONE" (مكتمل)، سيقوم النظام
                    تلقائياً بإنشاء مهمة فرعية جديدة من نوع "TESTING" للمراجعة.
                  </span>
                </div>
              </label>

              {/* Assignee Selector */}
              {settings.autoTestingSubtask && (
                <div className="mt-4 mr-14">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    تعيين تلقائي إلى:
                  </label>
                  <select
                    id="auto-testing-assignee"
                    name="autoTestingAssignee"
                    aria-label="تعيين مهمة الاختبار التلقائي"
                    value={settings.autoTestingAssigneeId || ""}
                    onChange={(e) =>
                      setSettings({
                        ...settings,
                        autoTestingAssigneeId: e.target.value || null,
                      })
                    }
                    className="border rounded px-3 py-2 text-sm w-full max-w-sm dark:bg-gray-700 dark:border-gray-600"
                  >
                    <option value="">(بدون تعيين محدد)</option>
                    {teamMembers.map((m) => (
                      <option key={m.id} value={m.id}>
                        {m.name} ({m.role})
                      </option>
                    ))}
                  </select>
                  <p className="text-xs text-gray-400 mt-1">
                    سيتم إسناد المهمة الفرعية لهذا الشخص تلقائياً.
                  </p>
                </div>
              )}
            </div>

            {/* Overdue Escalation Rules */}
            <div className="mt-8 pt-8 border-t border-gray-100 dark:border-gray-700">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                  تصعيد المهام المتأخرة (Escalation Rules)
                </h3>
                <a
                  href="/super-admin/dev/escalations"
                  className="text-sm text-indigo-600 hover:text-indigo-700 flex items-center gap-1 font-medium"
                >
                  <ClockIcon className="h-4 w-4" /> سجل التصعيدات
                </a>
              </div>
              <p className="text-sm text-gray-500 mb-6">
                حدد قواعد لنقل المهام تلقائياً إلى موظف آخر في حال تأخر إنجازها.
              </p>

              {/* Add Rule Form */}
              <div className="bg-gray-50 dark:bg-gray-700/30 p-4 rounded-lg border border-gray-100 dark:border-gray-600 mb-6">
                <h4 className="text-sm font-medium text-gray-900 dark:text-gray-100 mb-3">
                  إضافة قاعدة جديدة
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3 items-end">
                  <div className="lg:col-span-1">
                    <label className="text-xs text-gray-500 mb-1 block">
                      تأخير لمدة
                    </label>
                    <div className="flex">
                      <input
                        id="escalation-threshold"
                        name="escalationThreshold"
                        aria-label="مدة التأخير قبل التصعيد"
                        ref={ruleThresholdRef}
                        type="number"
                        min="1"
                        defaultValue="24"
                        className="w-full rounded-r border-l-0 border-gray-300 dark:bg-gray-700 dark:border-gray-600 px-2 py-2 text-sm"
                      />
                      <select
                        id="escalation-unit"
                        name="escalationUnit"
                        aria-label="وحدة مدة التأخير"
                        ref={ruleUnitRef}
                        className="rounded-l border-gray-300 dark:bg-gray-700 dark:border-gray-600 px-2 py-2 text-sm bg-gray-100 dark:bg-gray-800"
                      >
                        <option value="hours">ساعة</option>
                        <option value="days">يوم</option>
                      </select>
                    </div>
                  </div>

                  <div className="lg:col-span-1">
                    <label className="text-xs text-gray-500 mb-1 block">
                      النطاق (لمن؟)
                    </label>
                    <select
                      id="escalation-scope"
                      name="escalationScope"
                      aria-label="نطاق التصعيد"
                      ref={ruleScopeRef}
                      className="w-full rounded border-gray-300 dark:bg-gray-700 dark:border-gray-600 px-2 py-2 text-sm"
                    >
                      <option value="all">جميع الموظفين</option>
                      {teamMembers.map((m) => (
                        <option key={`scope-${m.id}`} value={m.id}>
                          {m.name}
                        </option>
                      ))}
                    </select>
                  </div>

