                  label: "إظهار تاريخ الإنشاء",
                  icon: Cog6ToothIcon,
                },
              ].map(({ key, label, icon: Icon }) => (
                <div
                  key={key}
                  className="bg-gray-50 dark:bg-gray-700/30 p-4 rounded-lg border border-gray-100 dark:border-gray-600 flex items-center justify-between"
                >
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-white dark:bg-gray-800 rounded-lg border border-gray-100 dark:border-gray-700">
                      <Icon className="h-5 w-5 text-indigo-500" />
                    </div>
                    <div>
                      <span className="block font-medium text-gray-900 dark:text-gray-100">
                        {label}
                      </span>
                    </div>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      className="sr-only peer"
                      checked={
                        settings.taskDetailsVisibility?.[
                          key as keyof TaskDetailsVisibility
                        ] ?? true
                      }
                      onChange={(e) => {
                        setSettings({
                          ...settings,
                          taskDetailsVisibility: {
                            ...(settings.taskDetailsVisibility || {
                              showDescription: true,
                              showRelatedLinks: true,
                              showChecklists: true,
                              showBusinessValue: true,
                              showAcceptanceCriteria: true,
                              showAttachments: true,
                              showCreatedAt: true,
                            }),
                            [key]: e.target.checked,
                          },
                        });
                      }}
                    />
                    <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 dark:peer-focus:ring-indigo-800 rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-indigo-600"></div>
                  </label>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DevTaskSettings;

import React, { useState, useEffect, useCallback } from "react";
import { useNavigate, useSearchParams, Link } from "react-router-dom";
import tokenManager from "../../utils/tokenManager";
import { buildApiUrl } from "../../utils/urlHelper";
import {
  PlusIcon,
  FunnelIcon,
  MagnifyingGlassIcon,
  ViewColumnsIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  ClipboardDocumentListIcon,
  ExclamationTriangleIcon,
  CalendarDaysIcon,
  ChatBubbleLeftIcon,
  PaperClipIcon,
  EyeIcon,
  PencilIcon,
  TrashIcon,
  XMarkIcon,
  ArrowDownTrayIcon,
  CheckCircleIcon,
  ChevronUpIcon,
  ChevronDownIcon,
  TagIcon,
  ClockIcon,
} from "@heroicons/react/24/outline";

interface Task {
  id: string;
  title: string;
  description: string;
  type: string;
  status: string;
  priority: string;
  component: string | null;
  assigneeId: string | null;
  assigneeName: string | null;
  assigneeAvatar: string | null;
  reporterName: string;
  projectId: string | null;
  projectName: string | null;
  projectColor: string | null;
  releaseId: string | null;
  releaseVersion: string | null;
  dueDate: string | null;
  estimatedHours: number;
  actualHours: number;
  progress: number;
  tags: string[];
  commentsCount: number;
  attachmentsCount: number;
  subtasksCount: number;
  createdAt: string;
  updatedAt: string;
}

interface Pagination {
  total: number;
  page: number;
  limit: number;
  totalPages: number;
}

import {
  TASK_TYPES,
  TASK_STATUSES,
  PRIORITY_CONFIG,
} from "../../constants/taskConstants";

const getAccessToken = (): string | null => tokenManager.getAccessToken();

const DevTasksList: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  const [tasks, setTasks] = useState<Task[]>([]);
  const [settings, setSettings] = useState<any>(null);
  const [userPermissions, setUserPermissions] = useState<any>(null);
  const [pagination, setPagination] = useState<Pagination>({
    total: 0,
    page: 1,
    limit: 20,
    totalPages: 1,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showFiltersSidebar, setShowFiltersSidebar] = useState(false);
  const [selectedTasks, setSelectedTasks] = useState<string[]>([]);
  const [projects, setProjects] = useState<any[]>([]);
  const [teamMembers, setTeamMembers] = useState<any[]>([]);
  const [releases, setReleases] = useState<any[]>([]);
  const [sortBy, setSortBy] = useState<string>("updatedAt");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");
  const [bulkAction, setBulkAction] = useState<string>("");
  const [stats, setStats] = useState<any>(null);
  const [confirmModal, setConfirmModal] = useState<{
    show: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({ show: false, title: "", message: "", onConfirm: () => {} });

  const [filters, setFilters] = useState({
    search: searchParams.get("search") || "",
    status: searchParams.get("status") || "",
    priority: searchParams.get("priority") || "",
    type: searchParams.get("type") || "",
    projectId: searchParams.get("projectId") || "",
    assigneeId: searchParams.get("assigneeId") || "",
    component: searchParams.get("component") || "",
    releaseId: searchParams.get("releaseId") || "",
    dueDateFrom: searchParams.get("dueDateFrom") || "",
    dueDateTo: searchParams.get("dueDateTo") || "",
    tags: searchParams.get("tags") || "",
    dateType: "dueDate", // dueDate, createdAt, updatedAt
  });

  // Pending filters for the sidebar (performance optimization)
  const [pendingFilters, setPendingFilters] = useState(filters);

  const [hideCompleted, setHideCompleted] = useState(true);
  const [showMyTasksOnly, setShowMyTasksOnly] = useState(() => {
    const saved = localStorage.getItem("devTasks_showMyTasksOnly");
    return saved !== null ? saved === "true" : true;
  });

  useEffect(() => {
    localStorage.setItem("devTasks_showMyTasksOnly", String(showMyTasksOnly));
  }, [showMyTasksOnly]);

  const [currentMemberId, setCurrentMemberId] = useState<string | null>(null);

  // Sync pending filters when sidebar opens
  useEffect(() => {
    if (showFiltersSidebar) {
      setPendingFilters(filters);
    }
  }, [showFiltersSidebar]);

  useEffect(() => {
    fetchSettings();
    fetchUserPermissions();
    fetchProjects();
    fetchTeamMembers();
    fetchReleases();
    fetchStats();
  }, []);

  useEffect(() => {
    fetchTasks();
  }, [
    pagination.page,
    pagination.limit,
    filters,
    sortBy,
    sortOrder,
    hideCompleted,
    showMyTasksOnly,
    currentMemberId,
  ]);

  const fetchUserPermissions = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        buildApiUrl("super-admin/user/permissions"),
        {
          headers: { Authorization: `Bearer ${token}` },
        },
      );
      const data = await response.json();
      if (data.success) {
        setUserPermissions(data.data.permissions);
        if (data.data.memberId) {
          setCurrentMemberId(data.data.memberId);
        }
      }
    } catch (err) {
      console.error("Error fetching user permissions:", err);
    }
  };

  const fetchSettings = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("super-admin/dev/settings"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setSettings(data.data);
      }
    } catch (err) {
      console.error("Error fetching settings:", err);
    }
  };

  const fetchProjects = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("super-admin/dev/projects"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setProjects(data.data);
      }
    } catch (err) {
      console.error("Error fetching projects:", err);
    }
  };

  const fetchTeamMembers = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("super-admin/dev/team"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setTeamMembers(data.data);
      }
    } catch (err) {
      console.error("Error fetching team members:", err);
    }
  };

  const fetchReleases = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("super-admin/dev/releases"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setReleases(data.data);
      }
    } catch (err) {
      console.error("Error fetching releases:", err);
    }
  };

  const fetchStats = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("super-admin/dev/dashboard"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setStats(data.data);
      }
    } catch (err) {
      console.error("Error fetching stats:", err);
    }
  };

  const fetchTasks = async () => {
    try {
      setLoading(true);
      setError(null);
      const token = getAccessToken();

      const params = new URLSearchParams();

      params.append("page", pagination.page.toString());
      params.append("limit", pagination.limit.toString());
      params.append("sortBy", sortBy);
      params.append("sortOrder", sortOrder);
      if (filters.search) params.append("search", filters.search);
      if (filters.status) params.append("status", filters.status);
      if (filters.priority) params.append("priority", filters.priority);
      if (filters.type) params.append("type", filters.type);
      if (filters.projectId) params.append("projectId", filters.projectId);
      if (showMyTasksOnly) {
        params.append("assigneeId", "me");
      } else if (filters.assigneeId) {
        params.append("assigneeId", filters.assigneeId);
      }
      if (filters.component) params.append("component", filters.component);
      if (filters.releaseId) params.append("releaseId", filters.releaseId);
      if (filters.dateType) params.append("dateType", filters.dateType);
      if (filters.dueDateFrom)
        params.append("dueDateFrom", filters.dueDateFrom);
      if (filters.dueDateTo) params.append("dueDateTo", filters.dueDateTo);
      if (filters.tags) params.append("tags", filters.tags);
      if (hideCompleted) params.append("excludeStatus", "DONE");

      const response = await fetch(
        buildApiUrl(`super-admin/dev/tasks?${params.toString()}`),
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        },
      );

      if (!response.ok) {
        throw new Error(`فشل تحميل المهام (${response.status})`);
      }

      const data = await response.json();
      if (data.success) {
        setTasks(data.data);
        setPagination(data.pagination);
      } else {
        setError(data.message || "حدث خطأ أثناء تحميل المهام");
      }
    } catch (err: any) {
      console.error("Error fetching tasks:", err);
      setError(
        err.message || "حدث خطأ في الاتصال بالخادم. يرجى المحاولة مرة أخرى.",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setFilters((prev) => ({ ...prev }));
    setPagination((prev) => ({ ...prev, page: 1 }));
  };

  const handleFilterChange = (key: string, value: string) => {
    setFilters((prev) => ({ ...prev, [key]: value }));
    setPagination((prev) => ({ ...prev, page: 1 }));
  };

  const handlePendingFilterChange = (key: string, value: string) => {
    setPendingFilters((prev) => ({ ...prev, [key]: value }));
  };

  const applyPendingFilters = () => {
    setFilters(pendingFilters);
    setPagination((prev) => ({ ...prev, page: 1 }));
    setShowFiltersSidebar(false);
  };

  const addTag = (tag: string) => {
    if (!tag.trim()) return;
    const currentTags = pendingFilters.tags
      ? pendingFilters.tags.split(",")
      : [];
    if (!currentTags.includes(tag.trim())) {
      const newTags = [...currentTags, tag.trim()].join(",");
      handlePendingFilterChange("tags", newTags);
    }
  };

  const removeTag = (tagToRemove: string) => {
    const currentTags = pendingFilters.tags
      ? pendingFilters.tags.split(",")
      : [];
    const newTags = currentTags.filter((tag) => tag !== tagToRemove).join(",");
    handlePendingFilterChange("tags", newTags);
  };

  const clearFilters = () => {
    const clearedFilters = {
      search: "",
      status: "",
      priority: "",
      type: "",
      projectId: "",
      assigneeId: "",
      component: "",
      releaseId: "",
      dueDateFrom: "",
      dueDateTo: "",
      tags: "",
      dateType: "dueDate",
    };
    setFilters(clearedFilters);
    setPendingFilters(clearedFilters);
    setPagination((prev) => ({ ...prev, page: 1 }));
  };

  const handleSort = (field: string) => {
    if (sortBy === field) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortBy(field);
      setSortOrder("desc");
    }
  };

  const executeBulkAction = async () => {
    try {
      const token = getAccessToken();

      if (bulkAction === "delete") {
        for (let i = 0; i < selectedTasks.length; i += 5) {
          const batch = selectedTasks.slice(i, i + 5);
          await Promise.all(
            batch.map((id) =>
              fetch(buildApiUrl(`super-admin/dev/tasks/${id}`), {
                method: "DELETE",
                headers: { Authorization: `Bearer ${token}` },
              }),
            ),
          );
        }
      } else if (bulkAction.startsWith("status:")) {
        const status = bulkAction.split(":")[1];
        for (let i = 0; i < selectedTasks.length; i += 5) {
          const batch = selectedTasks.slice(i, i + 5);
          await Promise.all(
            batch.map((id) =>
              fetch(buildApiUrl(`super-admin/dev/tasks/${id}`), {
                method: "PUT",
                headers: {
                  Authorization: `Bearer ${token}`,
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({ status }),
              }),
            ),
          );
        }
      } else if (bulkAction.startsWith("assignee:")) {
        const assigneeId = bulkAction.split(":")[1];
        for (let i = 0; i < selectedTasks.length; i += 5) {
          const batch = selectedTasks.slice(i, i + 5);
          await Promise.all(
            batch.map((id) =>
              fetch(buildApiUrl(`super-admin/dev/tasks/${id}`), {
                method: "PUT",
                headers: {
                  Authorization: `Bearer ${token}`,
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({ assigneeId }),
              }),
            ),
          );
        }
      }

      setSelectedTasks([]);
      setBulkAction("");
      fetchTasks();
    } catch (err) {
      console.error("Error performing bulk action:", err);
      setError("حدث خطأ أثناء تنفيذ العملية الجماعية");
    }
  };

  const handleBulkAction = () => {
    if (selectedTasks.length === 0 || !bulkAction) return;

    if (bulkAction === "delete") {
      setConfirmModal({
        show: true,
        title: "حذف مهام",
        message: `هل أنت متأكد من حذف ${selectedTasks.length} مهمة؟ لا يمكن التراجع عن هذا الإجراء.`,
        onConfirm: () => {
          setConfirmModal((prev) => ({ ...prev, show: false }));
          executeBulkAction();
        },
      });
    } else {
      executeBulkAction();
    }
  };

  const handleExport = async (format: "csv" | "json") => {
    try {
      const token = getAccessToken();
      const params = new URLSearchParams();
      Object.entries(filters).forEach(([key, value]) => {
        if (value) params.append(key, value);
      });

      const response = await fetch(
        buildApiUrl(
          `super-admin/dev/tasks/export?format=${format}&${params.toString()}`,
        ),
        {
          headers: { Authorization: `Bearer ${token}` },
        },
      );

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `tasks-${new Date().toISOString().split("T")[0]}.${format}`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      console.error("Error exporting tasks:", err);
    }
  };

  const toggleSelectAll = () => {
    if (selectedTasks.length === tasks.length) {
      setSelectedTasks([]);
    } else {
      setSelectedTasks(tasks.map((t) => t.id));
    }
  };

  const toggleSelectTask = (taskId: string) => {
    setSelectedTasks((prev) =>
      prev.includes(taskId)
        ? prev.filter((id) => id !== taskId)
        : [...prev, taskId],
    );
  };

  const executeDeleteTask = async (taskId: string) => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        buildApiUrl(`super-admin/dev/tasks/${taskId}`),
        {
          method: "DELETE",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchTasks();
      } else {
        setError(data.message || "فشل حذف المهمة");
      }
    } catch (err) {
      console.error("Error deleting task:", err);
      setError("حدث خطأ أثناء حذف المهمة");
    }
  };

  const handleDeleteTask = (taskId: string) => {
    setConfirmModal({
      show: true,
      title: "حذف مهمة",
      message:
        "هل أنت متأكد من حذف هذه المهمة؟ لا يمكن التراجع عن هذا الإجراء.",
      onConfirm: () => {
        setConfirmModal((prev) => ({ ...prev, show: false }));
        executeDeleteTask(taskId);
      },
    });
  };

  return (
    <div className="space-y-4" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
            📋 قائمة المهام
          </h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">
            {pagination.total} مهمة
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => handleExport("csv")}
            className="flex items-center gap-2 px-4 py-2 border border-gray-300 dark:border-gray-700 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
          >
            <ArrowDownTrayIcon className="h-5 w-5" />
            تصدير CSV
          </button>
          <button
            onClick={() => navigate("/super-admin/dev-kanban")}
            className="flex items-center gap-2 px-4 py-2 border border-gray-300 dark:border-gray-700 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
          >
            <ViewColumnsIcon className="h-5 w-5" />
            Kanban
          </button>
          <button
            onClick={() => navigate("/super-admin/dev-tasks/new")}
            className="flex items-center gap-2 px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
          >
            <PlusIcon className="h-5 w-5" />
            مهمة جديدة
          </button>
        </div>
      </div>

      {/* Quick Stats */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <div className="bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl p-4 text-white">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-blue-100 text-xs">المهام النشطة</p>
                <p className="text-2xl font-bold mt-1">
                  {stats.overview?.totalTasks || 0}
                </p>
                <p className="text-blue-200 text-[10px] mt-0.5">غير المكتملة</p>
              </div>
              <ClipboardDocumentListIcon className="h-10 w-10 text-blue-200" />
            </div>
          </div>
          <div className="bg-gradient-to-br from-yellow-500 to-yellow-600 rounded-xl p-4 text-white">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-yellow-100 text-xs">قيد العمل</p>
                <p className="text-2xl font-bold mt-1">
                  {stats.tasksByStatus?.IN_PROGRESS || 0}
                </p>
              </div>
              <ClockIcon className="h-10 w-10 text-yellow-200" />
            </div>
          </div>
          <div className="bg-gradient-to-br from-green-500 to-green-600 rounded-xl p-4 text-white">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-green-100 text-xs">مكتملة</p>
                <p className="text-2xl font-bold mt-1">
                  {stats.tasksByStatus?.DONE || 0}
                </p>
              </div>
              <CheckCircleIcon className="h-10 w-10 text-green-200" />
            </div>
          </div>
          <div className="bg-gradient-to-br from-red-500 to-red-600 rounded-xl p-4 text-white">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-red-100 text-xs">متأخرة</p>
                <p className="text-2xl font-bold mt-1">
                  {stats.overview?.overdueTasks || 0}
                </p>
              </div>
              <ExclamationTriangleIcon className="h-10 w-10 text-red-200" />
            </div>
          </div>
          <div className="bg-gradient-to-br from-purple-500 to-purple-600 rounded-xl p-4 text-white">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-purple-100 text-xs">مشاريع نشطة</p>
                <p className="text-2xl font-bold mt-1">
                  {stats.overview?.activeProjects || 0}
                </p>
              </div>
              <TagIcon className="h-10 w-10 text-purple-200" />
            </div>
          </div>
        </div>
      )}

      {/* Search & Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4">
        <div className="flex items-center gap-4">
          {/* Search */}
          <form onSubmit={handleSearch} className="flex-1">
            <div className="relative">
              <MagnifyingGlassIcon className="h-5 w-5 absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                placeholder="بحث في المهام..."
                value={filters.search}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, search: e.target.value }))
                }
                className="w-full pl-4 pr-10 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500"
              />
            </div>
          </form>

          {/* Quick Filters */}
          <select
            value={filters.status}
            onChange={(e) => handleFilterChange("status", e.target.value)}
            className="border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
          >
            <option value="">كل الحالات</option>
            {(
              settings?.taskStatuses ||
              Object.entries(TASK_STATUSES).map(([key, value]) => ({
                value: key,
                ...value,
              }))
            ).map((opt: any) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>

          <select
            value={filters.priority}
            onChange={(e) => handleFilterChange("priority", e.target.value)}
            className="border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
          >
            <option value="">كل الأولويات</option>
            {(
              settings?.taskPriorities ||
              Object.entries(PRIORITY_CONFIG).map(([key, value]) => ({
                value: key,
                ...value,
              }))
            ).map((opt: any) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>

          <select
            value={filters.type}
            onChange={(e) => handleFilterChange("type", e.target.value)}
            className="border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
          >
            <option value="">كل الأنواع</option>
            {Object.entries(TASK_TYPES).map(([key, { label }]) => (
              <option key={key} value={key}>
                {label}
              </option>
            ))}
          </select>

          <label className="flex items-center gap-2 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 cursor-pointer">
            <input
              type="checkbox"
              checked={hideCompleted}
              onChange={(e) => setHideCompleted(e.target.checked)}
              className="rounded border-gray-300 dark:border-gray-600 text-indigo-600 focus:ring-indigo-500"
            />
            <span className="text-sm">إخفاء المكتملة</span>
          </label>

          <label className="flex items-center gap-2 px-4 py-2 border border-blue-300 dark:border-blue-600 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/10 bg-blue-50/50 dark:bg-blue-900/5 text-blue-700 dark:text-blue-300 cursor-pointer transition-colors">
            <input
              type="checkbox"
              checked={showMyTasksOnly}
              onChange={(e) => setShowMyTasksOnly(e.target.checked)}
              className="rounded border-blue-300 dark:border-blue-600 text-blue-600 focus:ring-blue-500"
            />
            <span className="text-sm font-medium">مهامي فقط</span>
          </label>

          <button
            onClick={() => setShowFiltersSidebar(true)}
            className="flex items-center gap-2 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
          >
            <FunnelIcon className="h-5 w-5" />
            فلاتر متقدمة
          </button>

          {(filters.status ||
            filters.priority ||
            filters.type ||
            filters.search) && (
            <button
              onClick={clearFilters}
              className="text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 text-sm"
            >
              مسح الفلاتر
            </button>
          )}
        </div>
      </div>

      {/* Bulk Actions Toolbar */}
      {selectedTasks.length > 0 && (
        <div className="bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-700 rounded-xl p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <span className="text-indigo-700 dark:text-indigo-300 font-medium">
                {selectedTasks.length} مهمة محددة
              </span>
              <button
                onClick={() => setSelectedTasks([])}
                className="text-sm text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300"
              >
                إلغاء التحديد
              </button>
            </div>
            <div className="flex items-center gap-2">
              <select
                value={bulkAction}
                onChange={(e) => setBulkAction(e.target.value)}
                className="border border-indigo-300 dark:border-indigo-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 text-sm"
              >
                <option value="">اختر إجراء...</option>
                <option value="delete">حذف المحدد</option>
                <optgroup label="تغيير الحالة">
                  <option value="status:TODO">للتنفيذ</option>
                  <option value="status:IN_PROGRESS">قيد العمل</option>
                  <option value="status:IN_REVIEW">مراجعة</option>
                  <option value="status:DONE">مكتمل</option>
                </optgroup>
                <optgroup label="تعيين مسؤول">
                  {teamMembers.map((member) => (
                    <option key={member.id} value={`assignee:${member.userId}`}>
                      {member.name}
                    </option>
                  ))}
                </optgroup>
              </select>
              <button
                onClick={handleBulkAction}
                disabled={!bulkAction}
                className="px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed text-sm font-medium"
              >
                تنفيذ
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Tasks Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 dark:bg-gray-700/50 border-b border-gray-200 dark:border-gray-700">
              <tr>
                <th className="px-4 py-3 text-right">
                  <input
                    type="checkbox"
                    checked={
                      selectedTasks.length === tasks.length && tasks.length > 0
                    }
                    onChange={toggleSelectAll}
                    className="rounded border-gray-300 dark:border-gray-600"
                  />
                </th>
                <th className="px-4 py-3 text-right">
                  <button
                    onClick={() => handleSort("title")}
                    className="flex items-center gap-1 text-sm font-medium text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-100"
                  >
                    المهمة
                    {sortBy === "title" &&
                      (sortOrder === "asc" ? (
                        <ChevronUpIcon className="h-4 w-4" />
                      ) : (
                        <ChevronDownIcon className="h-4 w-4" />
                      ))}
                  </button>
                </th>
                <th className="px-4 py-3 text-right text-sm font-medium text-gray-600 dark:text-gray-400">
                  النوع
                </th>
                <th className="px-4 py-3 text-right">
                  <button
                    onClick={() => handleSort("status")}
                    className="flex items-center gap-1 text-sm font-medium text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-100"
                  >
                    الحالة
                    {sortBy === "status" &&
                      (sortOrder === "asc" ? (
                        <ChevronUpIcon className="h-4 w-4" />
                      ) : (
                        <ChevronDownIcon className="h-4 w-4" />
                      ))}
                  </button>
                </th>
                <th className="px-4 py-3 text-right">
                  <button
                    onClick={() => handleSort("priority")}
                    className="flex items-center gap-1 text-sm font-medium text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-100"
                  >
                    الأولوية
                    {sortBy === "priority" &&
                      (sortOrder === "asc" ? (
                        <ChevronUpIcon className="h-4 w-4" />
                      ) : (
                        <ChevronDownIcon className="h-4 w-4" />
                      ))}
                  </button>
                </th>
                <th className="px-4 py-3 text-right text-sm font-medium text-gray-600 dark:text-gray-400">
                  التقدم
                </th>
                <th className="px-4 py-3 text-right text-sm font-medium text-gray-600 dark:text-gray-400">
                  المسؤول
                </th>
                <th className="px-4 py-3 text-right text-sm font-medium text-gray-600 dark:text-gray-400">
                  المشروع
                </th>
                <th className="px-4 py-3 text-right">
                  <button
                    onClick={() => handleSort("dueDate")}
                    className="flex items-center gap-1 text-sm font-medium text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-100"
                  >
                    الاستحقاق
                    {sortBy === "dueDate" &&
                      (sortOrder === "asc" ? (
                        <ChevronUpIcon className="h-4 w-4" />
                      ) : (
                        <ChevronDownIcon className="h-4 w-4" />
                      ))}
                  </button>
                </th>
                <th className="px-4 py-3 text-right text-sm font-medium text-gray-600 dark:text-gray-400">
                  إجراءات
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {loading ? (
                <tr>
                  <td colSpan={10} className="px-4 py-12 text-center">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 dark:border-indigo-400 mx-auto"></div>
                  </td>
                </tr>
              ) : error ? (
                <tr>
                  <td colSpan={10} className="px-4 py-12 text-center">
                    <div className="flex flex-col items-center justify-center">
                      <ExclamationTriangleIcon className="h-12 w-12 text-red-400 mb-3" />
                      <p className="text-red-600 dark:text-red-400 font-medium mb-2">
                        {error}
                      </p>
                      <button
                        onClick={() => fetchTasks()}
                        className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                      >
                        إعادة المحاولة
                      </button>
                    </div>
                  </td>
                </tr>
              ) : tasks.length === 0 ? (
                <tr>
                  <td colSpan={10} className="px-4 py-16 text-center">
                    <div className="flex flex-col items-center justify-center">
                      <ClipboardDocumentListIcon className="h-16 w-16 text-gray-300 dark:text-gray-600 mb-4" />
                      <h3 className="text-lg font-medium text-gray-900 dark:text-gray-100 mb-2">
                        لا توجد مهام
                      </h3>
                      <p className="text-gray-500 dark:text-gray-400 mb-4">
                        ابدأ بإنشاء مهمة جديدة لتتبع عمل فريقك
                      </p>
                      <button
                        onClick={() => navigate("/super-admin/dev-tasks/new")}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
                      >
                        <PlusIcon className="h-5 w-5" />
                        إنشاء مهمة جديدة
                      </button>
                    </div>
                  </td>
                </tr>
              ) : (
                tasks.map((task) => {
                  const typeInfo =
                    TASK_TYPES[task.type] || TASK_TYPES["FEATURE"];

                  // Get status info from settings or default
                  const statusInfo =
                    settings?.taskStatuses?.find(
                      (s: any) => s.value === task.status,
                    ) ||
                    TASK_STATUSES[task.status] ||
                    TASK_STATUSES["BACKLOG"];

                  // Get priority info from settings or default
                  const priorityInfo =
                    settings?.taskPriorities?.find(
                      (p: any) => p.value === task.priority,
                    ) ||
                    PRIORITY_CONFIG[task.priority] ||
                    PRIORITY_CONFIG["MEDIUM"];

                  const isOverdue =
                    task.dueDate &&
                    new Date(task.dueDate) < new Date() &&
                    task.status !== "DONE";

                  return (
                    <tr
                      key={task.id}
                      className="hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer"
                      onClick={() =>
                        navigate(`/super-admin/dev-tasks/${task.id}`)
                      }
                    >
                      <td
                        className="px-4 py-3"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <input
                          type="checkbox"
                          checked={selectedTasks.includes(task.id)}
                          onChange={() => toggleSelectTask(task.id)}
                          className="rounded border-gray-300 dark:border-gray-600"
                        />
                      </td>
                      <td className="px-4 py-3">
                        <div className="max-w-md">
                          <Link
                            to={`/super-admin/dev-tasks/${task.id}`}
                            onClick={(e) => e.stopPropagation()}
                            className="font-medium text-gray-900 dark:text-gray-100 truncate hover:text-indigo-600 dark:hover:text-indigo-400 block"
                          >
                            {task.title}
                          </Link>
                          <div className="flex items-center gap-2 mt-1 text-gray-400 dark:text-gray-500 text-xs">
                            {task.commentsCount > 0 && (
                              <span className="flex items-center gap-0.5">
                                <ChatBubbleLeftIcon className="h-3 w-3" />
                                {task.commentsCount}
                              </span>
                            )}
                            {task.attachmentsCount > 0 && (
                              <span className="flex items-center gap-0.5">
                                <PaperClipIcon className="h-3 w-3" />
                                {task.attachmentsCount}
                              </span>
                            )}
                            {task.subtasksCount > 0 && (
                              <span className="flex items-center gap-0.5">
                                <ClipboardDocumentListIcon className="h-3 w-3" />
                                {task.subtasksCount}
                              </span>
                            )}
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${typeInfo?.bg || ""} ${typeInfo?.text || ""}`}
                        >
                          {typeInfo?.icon}
                          {typeInfo?.label}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={`px-2 py-1 rounded-full text-xs font-medium ${statusInfo?.bg || ""} ${statusInfo?.text || ""}`}
                        >
                          {statusInfo?.label}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          <span
                            className={`w-2 h-2 rounded-full ${priorityInfo?.color || ""}`}
                          ></span>
                          <span className="text-sm text-gray-600 dark:text-gray-400">
                            {priorityInfo?.label}
                          </span>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="space-y-1">
                          <div className="flex items-center justify-between text-xs">
                            <span className="text-gray-600 dark:text-gray-400">
                              {task.progress}%
                            </span>
                            {task.estimatedHours > 0 && (
                              <span className="text-gray-500 dark:text-gray-500">
                                {task.actualHours}/{task.estimatedHours}h
                              </span>
                            )}
                          </div>
                          <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-1.5">
                            <div
                              className="bg-indigo-600 dark:bg-indigo-500 h-1.5 rounded-full transition-all"
                              style={{ width: `${task.progress}%` }}
                            ></div>
                          </div>
                          {task.tags && task.tags.length > 0 && (
                            <div className="flex flex-wrap gap-1 mt-1">
                              {task.tags.slice(0, 2).map((tag, idx) => (
                                <span
                                  key={idx}
                                  className="inline-flex items-center px-1.5 py-0.5 rounded text-xs bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400"
                                >
                                  {tag}
                                </span>
                              ))}
                              {task.tags.length > 2 && (
                                <span className="text-xs text-gray-400">
                                  +{task.tags.length - 2}
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        {task.assigneeName ? (
                          <div className="flex items-center gap-2">
                            {task.assigneeAvatar ? (
                              <img
                                src={task.assigneeAvatar}
                                alt=""
                                className="w-6 h-6 rounded-full"
                              />
                            ) : (
                              <div className="w-6 h-6 rounded-full bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 flex items-center justify-center text-xs font-medium">
                                {task.assigneeName.charAt(0)}
                              </div>
                            )}
                            <span className="text-sm text-gray-700 dark:text-gray-300">
                              {task.assigneeName}
                            </span>
                          </div>
                        ) : (
                          <span className="text-sm text-gray-400 dark:text-gray-500">
                            غير محدد
                          </span>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        {task.projectName ? (
                          <div className="flex items-center gap-2">
                            <span
                              className="w-2 h-2 rounded-full"
                              style={{
                                backgroundColor: task.projectColor || "#6366f1",
                              }}
                            ></span>
                            <span className="text-sm text-gray-700 dark:text-gray-300">
                              {task.projectName}
                            </span>
                          </div>
                        ) : (
                          <span className="text-sm text-gray-400 dark:text-gray-500">
                            -
                          </span>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        {task.dueDate ? (
                          <span
                            className={`flex items-center gap-1 text-sm ${isOverdue ? "text-red-600 dark:text-red-400" : "text-gray-600 dark:text-gray-400"}`}
                          >
                            <CalendarDaysIcon className="h-4 w-4" />
                            {new Date(task.dueDate).toLocaleDateString("ar-EG")}
                          </span>
                        ) : (
                          <span className="text-sm text-gray-400 dark:text-gray-500">
                            -
                          </span>
                        )}
                      </td>
                      <td
                        className="px-4 py-3"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <div className="flex items-center gap-1">
                          <Link
                            to={`/super-admin/dev-tasks/${task.id}`}
                            onClick={(e) => e.stopPropagation()}
                            className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 block"
                            title="عرض"
                          >
                            <EyeIcon className="h-4 w-4" />
                          </Link>
                          {/* 🔐 Show edit button only if user has canEdit permission */}
                          {userPermissions?.canEdit && (
                            <Link
                              to={`/super-admin/dev-tasks/${task.id}/edit`}
                              onClick={(e) => e.stopPropagation()}
                              className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 block"
                              title="تعديل"
                            >
                              <PencilIcon className="h-4 w-4" />
                            </Link>
                          )}
                          {/* 🔐 Show delete button only if user has canDelete permission */}
                          {userPermissions?.canDelete && (
                            <button
                              onClick={() => handleDeleteTask(task.id)}
                              className="p-1.5 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg text-gray-500 dark:text-gray-400 hover:text-red-600 dark:hover:text-red-400"
                              title="حذف"
                            >
                              <TrashIcon className="h-4 w-4" />
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="px-4 py-3 border-t border-gray-200 dark:border-gray-700 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="text-sm text-gray-600 dark:text-gray-400">
              عرض {(pagination.page - 1) * pagination.limit + 1} -{" "}
              {Math.min(pagination.page * pagination.limit, pagination.total)}{" "}
              من {pagination.total}
            </div>
            <select
              value={pagination.limit}
              onChange={(e) =>
                setPagination((prev) => ({
                  ...prev,
                  limit: parseInt(e.target.value),
                  page: 1,
                }))
              }
              className="border border-gray-300 dark:border-gray-600 rounded-lg px-2 py-1 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 text-sm"
            >
              <option value="10">10 / صفحة</option>
              <option value="20">20 / صفحة</option>
              <option value="50">50 / صفحة</option>
              <option value="100">100 / صفحة</option>
            </select>
          </div>
          {pagination.totalPages > 1 && (
            <div className="flex items-center gap-2">
              <button
                onClick={() =>
                  setPagination((prev) => ({ ...prev, page: prev.page - 1 }))
                }
                disabled={pagination.page === 1}
                className="p-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
              >
                <ChevronRightIcon className="h-5 w-5" />
              </button>
              <span className="px-3 py-2 text-sm text-gray-600 dark:text-gray-400">
                صفحة {pagination.page} من {pagination.totalPages}
              </span>
              <button
                onClick={() =>
                  setPagination((prev) => ({ ...prev, page: prev.page + 1 }))
                }
                disabled={pagination.page === pagination.totalPages}
                className="p-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
              >
                <ChevronLeftIcon className="h-5 w-5" />
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Filters Sidebar */}
      {showFiltersSidebar && (
        <div className="fixed inset-0 z-50 overflow-hidden" dir="rtl">
          <div
            className="absolute inset-0 bg-black bg-opacity-50"
            onClick={() => setShowFiltersSidebar(false)}
          ></div>
          <div className="absolute left-0 top-0 bottom-0 w-96 bg-white dark:bg-gray-800 shadow-xl overflow-y-auto">
            <div className="sticky top-0 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 px-6 py-4 flex items-center justify-between">
              <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                فلاتر متقدمة
              </h2>
              <button
                onClick={() => setShowFiltersSidebar(false)}
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
              >
                <XMarkIcon className="h-5 w-5 text-gray-500 dark:text-gray-400" />
              </button>
            </div>

            <div className="p-6 space-y-6">
              {/* Status Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الحالة
                </label>
                <select
                  value={pendingFilters.status}
                  onChange={(e) =>
                    handlePendingFilterChange("status", e.target.value)
                  }
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">كل الحالات</option>
                  {(
                    settings?.taskStatuses ||
                    Object.entries(TASK_STATUSES).map(([key, value]) => ({
                      value: key,
                      ...value,
                    }))
                  ).map((opt: any) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Priority Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الأولوية
                </label>
                <select
                  value={pendingFilters.priority}
                  onChange={(e) =>
                    handlePendingFilterChange("priority", e.target.value)
                  }
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">كل الأولويات</option>
                  {(
                    settings?.taskPriorities ||
                    Object.entries(PRIORITY_CONFIG).map(([key, value]) => ({
                      value: key,
                      ...value,
                    }))
                  ).map((opt: any) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Type Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  النوع
                </label>
                <select
                  value={pendingFilters.type}
                  onChange={(e) =>
                    handlePendingFilterChange("type", e.target.value)
                  }
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">كل الأنواع</option>
                  {Object.entries(TASK_TYPES).map(([key, { label }]) => (
                    <option key={key} value={key}>
                      {label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Project Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  المشروع
                </label>
                <select
                  value={pendingFilters.projectId}
                  onChange={(e) =>
                    handlePendingFilterChange("projectId", e.target.value)
                  }
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">كل المشاريع</option>
                  {projects.map((project) => (
                    <option key={project.id} value={project.id}>
                      {project.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* Assignee Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  المسؤول
                </label>
                <select
                  value={pendingFilters.assigneeId}
                  onChange={(e) =>
                    handlePendingFilterChange("assigneeId", e.target.value)
                  }
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">الكل</option>
                  {teamMembers.map((member) => (
                    <option key={member.id} value={member.id}>
                      {member.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* Release Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الإصدار
                </label>
                <select
                  value={pendingFilters.releaseId}
                  onChange={(e) =>
                    handlePendingFilterChange("releaseId", e.target.value)
                  }
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">كل الإصدارات</option>
                  {releases.map((release) => (
                    <option key={release.id} value={release.id}>
                      v{release.version} - {release.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* Component Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  المكون
                </label>
                <select
                  value={pendingFilters.component}
                  onChange={(e) =>
                    handlePendingFilterChange("component", e.target.value)
                  }
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">الكل</option>
                  {/* Common Components List */}
                  {[
                    "Frontend",
                    "Backend",
                    "Database",
                    "API",
                    "AI System",
                    "WhatsApp",
                    "Facebook",
                    "Mobile App",
                    "Design",
                    "DevOps",
                    "QA",
                  ].map((comp) => (
                    <option key={comp.toLowerCase()} value={comp.toLowerCase()}>
                      {comp}
                    </option>
                  ))}
                  {/* Dynamic Components from Settings if available */}
                  {settings?.components?.map((comp: string) => (
                    <option key={comp} value={comp}>
                      {comp}
                    </option>
                  ))}
                </select>
              </div>

              {/* Date Range Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  التاريخ
                </label>
                <div className="mb-2">
                  <select
                    value={pendingFilters.dateType}
                    onChange={(e) =>
                      handlePendingFilterChange("dateType", e.target.value)
                    }
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 text-sm mb-2"
                  >
                    <option value="dueDate">تاريخ الاستحقاق</option>
                    <option value="createdAt">تاريخ الإنشاء</option>
                    <option value="updatedAt">تاريخ التحديث</option>
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">
                      من
                    </label>
                    <input
                      type="date"
                      value={pendingFilters.dueDateFrom}
                      onChange={(e) =>
                        handlePendingFilterChange("dueDateFrom", e.target.value)
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">
                      إلى
                    </label>
                    <input
                      type="date"
                      value={pendingFilters.dueDateTo}
                      onChange={(e) =>
                        handlePendingFilterChange("dueDateTo", e.target.value)
                      }
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 text-sm"
                    />
                  </div>
                </div>
              </div>

              {/* Tags Filter (Pills UI) */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  الوسوم
                </label>
                <div className="border border-gray-300 dark:border-gray-600 rounded-lg p-2 bg-white dark:bg-gray-700 focus-within:ring-2 focus-within:ring-indigo-500">
                  <div className="flex flex-wrap gap-2 mb-2">
                    {pendingFilters.tags &&
                      pendingFilters.tags.split(",").map(
                        (tag: string, idx: number) =>
                          tag.trim() && (
                            <span
                              key={idx}
                              className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-indigo-100 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300"
                            >
                              {tag}
                              <button
                                onClick={() => removeTag(tag)}
                                className="hover:text-indigo-900 dark:hover:text-indigo-100"
                              >
                                <XMarkIcon className="h-3 w-3" />
                              </button>
                            </span>
                          ),
                      )}
                  </div>
                  <input
                    type="text"
                    placeholder="أضف وسماً واضغط Enter..."
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        addTag(e.currentTarget.value);
                        e.currentTarget.value = "";
                      }
                    }}
                    className="w-full bg-transparent border-none focus:ring-0 text-sm p-0 text-gray-900 dark:text-gray-100 placeholder-gray-400"
                  />
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  اضغط Enter لإضافة الوسم
                </p>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
                <button
                  onClick={() => {
                    clearFilters();
                    setShowFiltersSidebar(false);
                  }}
                  className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300"
                >
                  مسح الكل
                </button>
                <button
                  onClick={applyPendingFilters}
                  className="flex-1 px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
                >
                  تطبيق الفلاتر
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Confirm Modal */}
      {confirmModal.show && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center"
          dir="rtl"
        >
          <div
            className="absolute inset-0 bg-black bg-opacity-50"
            onClick={() =>
              setConfirmModal((prev) => ({ ...prev, show: false }))
            }
          ></div>
          <div className="relative bg-white dark:bg-gray-800 rounded-xl shadow-2xl p-6 max-w-md w-full mx-4">
            <div className="flex items-center gap-3 mb-4">
              <div className="flex-shrink-0 w-10 h-10 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center">
                <ExclamationTriangleIcon className="h-6 w-6 text-red-600 dark:text-red-400" />
              </div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                {confirmModal.title}
              </h3>
            </div>
            <p className="text-gray-600 dark:text-gray-400 mb-6">
              {confirmModal.message}
            </p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() =>
                  setConfirmModal((prev) => ({ ...prev, show: false }))
                }
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300"
              >
                إلغاء
              </button>
              <button
                onClick={confirmModal.onConfirm}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
              >
                تأكيد الحذف
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DevTasksList;

import React, { useState, useEffect } from "react";
import { buildApiUrl } from "../../utils/urlHelper";
import tokenManager from "../../utils/tokenManager";
import { useTheme } from "../../hooks/useTheme";
import {
  UserGroupIcon,
  PlusIcon,
  PencilIcon,
  TrashIcon,
  XMarkIcon,
  UserIcon,
  BriefcaseIcon,
  CheckCircleIcon,
  ClockIcon,
  XCircleIcon,
  FunnelIcon,
  ClipboardDocumentListIcon,
} from "@heroicons/react/24/outline";

interface TeamMember {
  id: string;
  userId: string;
  name: string;
  email: string;
  avatar: string | null;
  phone: string | null;
  role: string;
  department: string | null;
  skills: string[];
  availability: string;
  isActive: boolean;
  tasksCount: number;
  projectsCount: number;
  createdAt: string;
  updatedAt: string;
}

interface User {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  role: string;
}

const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const roleLabels: Record<string, string> = {
  developer: "مطور",
  designer: "مصمم",
  project_manager: "مدير مشروع",
  qa: "مختبر",
  devops: "DevOps",
  tech_lead: "قائد تقني",
  product_manager: "مدير منتج",
};

const availabilityConfig: Record<
  string,
  { label: string; color: string; icon: React.ReactNode }
> = {
  available: {
    label: "متاح",
    color:
      "bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400",
    icon: <CheckCircleIcon className="h-4 w-4" />,
  },
  busy: {
    label: "مشغول",
    color:
      "bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-400",
    icon: <ClockIcon className="h-4 w-4" />,
  },
  away: {
    label: "بعيد",
    color:
      "bg-yellow-100 dark:bg-yellow-900/30 text-yellow-700 dark:text-yellow-400",
    icon: <ClockIcon className="h-4 w-4" />,
  },
  offline: {
    label: "غير متصل",
    color: "bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-400",
    icon: <XCircleIcon className="h-4 w-4" />,
  },
};

const DevTeam = () => {
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingMember, setEditingMember] = useState<TeamMember | null>(null);
  const [filterRole, setFilterRole] = useState("");
  const [filterAvailability, setFilterAvailability] = useState("");
  const [availableUsers, setAvailableUsers] = useState<User[]>([]);
  const [loadingUsers, setLoadingUsers] = useState(false);

  useEffect(() => {
    fetchTeamMembers();
  }, []);

  useEffect(() => {
    if (showForm && !editingMember) {
      fetchAvailableUsers();
    }
  }, [showForm, editingMember]);

  const fetchTeamMembers = async () => {
    try {
      setLoading(true);
      const response = await fetch(buildApiUrl("super-admin/dev/team"), {
        headers: getAuthHeaders({ "Content-Type": "application/json" }),
      });

      const data = await response.json();
      if (data.success) {
        setTeamMembers(data.data);
      } else {
        console.error("Failed to fetch team members:", data.error);
      }
    } catch (err) {
      console.error("Error fetching team members:", err);
    } finally {
      setLoading(false);
    }
  };

  const fetchAvailableUsers = async () => {
    try {
      setLoadingUsers(true);
      const response = await fetch(buildApiUrl("super-admin/users?limit=100"), {
        headers: getAuthHeaders({ "Content-Type": "application/json" }),
      });

      const data = await response.json();
      if (data.success && data.data) {
        // Filter out users who are already team members
        const existingUserIds = teamMembers.map((m) => m.userId);
        // data.data is an array of users
        const usersArray = Array.isArray(data.data) ? data.data : [];
        const available = usersArray.filter(
          (u: User) => !existingUserIds.includes(u.id),
        );
        setAvailableUsers(available);
      }
    } catch (err) {
      console.error("Error fetching users:", err);
    } finally {
      setLoadingUsers(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا العضو من الفريق؟")) return;

    try {
      const response = await fetch(buildApiUrl(`super-admin/dev/team/${id}`), {
        method: "DELETE",
        headers: getAuthHeaders(),
      });

      const data = await response.json();
      if (data.success) {
        fetchTeamMembers();
      } else {
        alert(data.error || "فشل في حذف العضو");
      }
    } catch (err) {
      alert("فشل في الاتصال بالخادم");
    }
  };

  const handleEdit = (member: TeamMember) => {
    setEditingMember(member);
    setShowForm(true);
  };

  const handleCloseForm = () => {
    setShowForm(false);
    setEditingMember(null);
  };

  const filteredMembers = teamMembers.filter((member) => {
    if (filterRole && member.role !== filterRole) return false;
    if (filterAvailability && member.availability !== filterAvailability)
      return false;
    return true;
  });

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 dark:border-indigo-400"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
            👥 فريق التطوير
          </h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">
            إدارة أعضاء فريق التطوير
          </p>
        </div>
        <button
          onClick={() => setShowForm(true)}
          className="flex items-center gap-2 px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
        >
          <PlusIcon className="h-5 w-5" />
          إضافة عضو
        </button>
      </div>

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4">
        <div className="flex items-center gap-4">
          <FunnelIcon className="h-5 w-5 text-gray-400 dark:text-gray-500" />
          <select
            value={filterRole}
            onChange={(e) => setFilterRole(e.target.value)}
            className="border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
          >
            <option value="">كل الأدوار</option>
            {Object.entries(roleLabels).map(([key, label]) => (
              <option key={key} value={key}>
                {label}
              </option>
            ))}
          </select>
          <select
            value={filterAvailability}
            onChange={(e) => setFilterAvailability(e.target.value)}
            className="border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
          >
            <option value="">كل الحالات</option>
            {Object.entries(availabilityConfig).map(([key, { label }]) => (
              <option key={key} value={key}>
                {label}
              </option>
            ))}
          </select>
          {(filterRole || filterAvailability) && (
            <button
              onClick={() => {
                setFilterRole("");
                setFilterAvailability("");
              }}
              className="text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 text-sm"
            >
              مسح الفلاتر
            </button>
          )}
        </div>
      </div>

      {/* Team Members Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMembers.map((member) => {
          const availabilityInfo =
            availabilityConfig[member.availability] ||
            availabilityConfig.offline;

          return (
            <div
              key={member.id}
              className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden hover:shadow-lg dark:hover:shadow-xl transition-shadow"
            >
              <div className="p-6">
                {/* Header */}
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    {member.avatar ? (
                      <img
                        src={member.avatar}
                        alt={member.name}
                        className="h-12 w-12 rounded-full object-cover"
                      />
                    ) : (
                      <div className="h-12 w-12 rounded-full bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center">
                        <UserIcon className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
                      </div>
                    )}
                    <div>
                      <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                        {member.name}
                      </h3>
                      <p className="text-sm text-gray-500 dark:text-gray-400">
                        {member.email}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => handleEdit(member)}
                      className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300"
                      title="تعديل"
                    >
                      <PencilIcon className="h-4 w-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(member.id)}
                      className="p-1.5 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg text-gray-500 dark:text-gray-400 hover:text-red-600 dark:hover:text-red-400"
                      title="حذف"
                    >
                      <TrashIcon className="h-4 w-4" />
                    </button>
                  </div>
                </div>

                {/* Role & Department */}
                <div className="mb-4">
                  <div className="flex items-center gap-2 mb-2">
                    <BriefcaseIcon className="h-4 w-4 text-gray-400 dark:text-gray-500" />
                    <span className="text-sm font-medium text-gray-900 dark:text-gray-100">
                      {roleLabels[member.role] || member.role}
                    </span>
                  </div>
                  {member.department && (
                    <p className="text-sm text-gray-600 dark:text-gray-400 mr-6">
                      {member.department}
                    </p>
                  )}
                </div>

                {/* Availability */}
                <div className="mb-4">
                  <div
                    className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-medium ${availabilityInfo.color}`}
                  >
                    {availabilityInfo.icon}
                    {availabilityInfo.label}
                  </div>
                  {!member.isActive && (
                    <span className="ml-2 inline-block px-2 py-1 rounded text-xs font-medium bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400">
                      غير نشط
                    </span>
                  )}
                </div>

                {/* Skills */}
                {member.skills && member.skills.length > 0 && (
                  <div className="mb-4">
                    <p className="text-xs text-gray-500 dark:text-gray-400 mb-2">
                      المهارات:
                    </p>
                    <div className="flex flex-wrap gap-1">
                      {member.skills.slice(0, 3).map((skill, idx) => (
                        <span
                          key={idx}
                          className="px-2 py-0.5 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400 rounded-full text-xs"
                        >
                          {skill}
                        </span>
                      ))}
                      {member.skills.length > 3 && (
                        <span className="px-2 py-0.5 text-gray-500 dark:text-gray-500 text-xs">
                          +{member.skills.length - 3}
                        </span>
                      )}
                    </div>
                  </div>
                )}

                {/* Stats */}
                <div className="grid grid-cols-2 gap-4 pt-4 border-t border-gray-100 dark:border-gray-700">
                  <div className="text-center">
                    <p className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                      {member.tasksCount}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      مهمة
                    </p>
                  </div>
                  <div className="text-center">
                    <p className="text-lg font-semibold text-indigo-600 dark:text-indigo-400">
                      {member.projectsCount}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      مشروع
                    </p>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Empty State */}
      {filteredMembers.length === 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-12 text-center">
          <UserGroupIcon className="h-16 w-16 mx-auto mb-4 text-gray-300 dark:text-gray-600" />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-2">
            لا يوجد أعضاء في الفريق
          </h3>
          <p className="text-gray-500 dark:text-gray-400 mb-6">
            ابدأ بإضافة أعضاء جدد للفريق
          </p>
          <button
            onClick={() => setShowForm(true)}
            className="px-6 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600"
          >
            <PlusIcon className="h-5 w-5 inline ml-2" />
            إضافة عضو
          </button>
        </div>
      )}

      {/* Form Modal */}
      {showForm && (
        <TeamMemberFormModal
          member={editingMember}
          availableUsers={availableUsers}
          loadingUsers={loadingUsers}
          onClose={handleCloseForm}
          onSuccess={() => {
            handleCloseForm();
            fetchTeamMembers();
          }}
        />
      )}
    </div>
  );
};

// Team Member Form Modal Component
const TeamMemberFormModal: React.FC<{
  member: TeamMember | null;
  availableUsers: User[];
  loadingUsers: boolean;
  onClose: () => void;
  onSuccess: () => void;
}> = ({ member, availableUsers, loadingUsers, onClose, onSuccess }) => {
  const { actualTheme } = useTheme();
  const isDark = actualTheme === "dark";
  const [formData, setFormData] = useState({
    userId: member?.userId || "",
    role: member?.role || "developer",
    department: member?.department || "",
    skills: member?.skills?.join(", ") || "",
    availability: member?.availability || "available",
    isActive: member?.isActive !== undefined ? member.isActive : true,
  });
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!member && !formData.userId) {
      alert("يرجى اختيار مستخدم");
      return;
    }

    try {
      setSaving(true);
      const url = member
        ? buildApiUrl(`super-admin/dev/team/${member.id}`)
        : buildApiUrl("super-admin/dev/team");

      const payload = {
        ...formData,
        skills: formData.skills
          ? formData.skills
              .split(",")
              .map((s) => s.trim())
              .filter(Boolean)
          : [],
      };

      if (!member) {
        payload.userId = formData.userId;
      } else {
        // Remove userId when editing
        delete payload.userId;
      }

      const response = await fetch(url, {
        method: member ? "PUT" : "POST",
        headers: getAuthHeaders({ "Content-Type": "application/json" }),
        body: JSON.stringify(payload),
      });

      const data = await response.json();
      if (data.success) {
        onSuccess();
      } else {
        alert(data.error || `فشل في ${member ? "تحديث" : "إنشاء"} العضو`);
      }
    } catch (err) {
      alert("فشل في الاتصال بالخادم");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 dark:bg-opacity-70 flex items-center justify-center z-50 p-4">
      <div className="bg-white dark:bg-gray-800 rounded-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between">
          <h2 className="text-xl font-bold text-gray-900 dark:text-gray-100">
            {member ? "تعديل عضو الفريق" : "إضافة عضو جديد"}
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-500 dark:text-gray-400"
          >
            <XMarkIcon className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          {!member && (
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                المستخدم{" "}
                <span className="text-red-500 dark:text-red-400">*</span>
              </label>
              {loadingUsers ? (
                <div className="text-center py-4">
                  <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-indigo-600 dark:border-indigo-400 mx-auto"></div>
                </div>
              ) : (
                <select
                  value={formData.userId}
                  onChange={(e) =>
                    setFormData({ ...formData, userId: e.target.value })
                  }
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                  required
                >
                  <option value="">اختر مستخدم...</option>
                  {availableUsers.map((user) => (
                    <option key={user.id} value={user.id}>
                      {user.firstName} {user.lastName} ({user.email})
                    </option>
                  ))}
                </select>
              )}
              {!loadingUsers && availableUsers.length === 0 && (
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                  لا يوجد مستخدمين متاحين
                </p>
              )}
            </div>
          )}

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              الدور <span className="text-red-500 dark:text-red-400">*</span>
            </label>
            <select
              value={formData.role}
              onChange={(e) =>
                setFormData({ ...formData, role: e.target.value })
              }
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
              required
            >
              {Object.entries(roleLabels).map(([key, label]) => (
                <option key={key} value={key}>
                  {label}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              القسم
            </label>
            <input
              type="text"
              value={formData.department}
              onChange={(e) =>
                setFormData({ ...formData, department: e.target.value })
              }
              placeholder="مثل: Frontend, Backend, Mobile..."
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              المهارات
            </label>
            <input
              type="text"
              value={formData.skills}
              onChange={(e) =>
                setFormData({ ...formData, skills: e.target.value })
              }
              placeholder="مفصولة بفاصلة: React, Node.js, TypeScript..."
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              الحالة
            </label>
            <select
              value={formData.availability}
              onChange={(e) =>
                setFormData({ ...formData, availability: e.target.value })
              }
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
            >
              {Object.entries(availabilityConfig).map(([key, { label }]) => (
                <option key={key} value={key}>
                  {label}
                </option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="isActive"
              checked={formData.isActive}
              onChange={(e) =>
                setFormData({ ...formData, isActive: e.target.checked })
              }
              className="w-4 h-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500 dark:focus:ring-indigo-400 dark:ring-offset-gray-800 focus:ring-2 dark:bg-gray-700 dark:border-gray-600"
            />
            <label
              htmlFor="isActive"
              className="text-sm font-medium text-gray-700 dark:text-gray-300"
            >
              نشط
            </label>
          </div>

          <div className="flex items-center justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
            <button
              type="button"
              onClick={onClose}
              className="px-6 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 bg-white dark:bg-gray-800"
            >
              إلغاء
            </button>
            <button
              type="submit"
              disabled={saving}
              className="px-6 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600 disabled:opacity-50"
            >
              {saving ? "جاري الحفظ..." : member ? "تحديث" : "إضافة"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default DevTeam;

import React, { useState, useEffect } from "react";
import { buildApiUrl } from "../../utils/urlHelper";
import tokenManager from "../../utils/tokenManager";
import { ArrowUturnLeftIcon, ClockIcon } from "@heroicons/react/24/outline";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface EscalationLog {
  id: string;
  taskId: string;
  task: {
    id: string;
    title: string;
  };
  memberId: string;
  member: {
    user: {
      firstName: string;
      lastName: string;
      avatar: string | null;
    };
  };
  description: string;
  createdAt: string;
  fromUser: string;
  toUser: string;
}

const EscalationHistory = () => {
  const [logs, setLogs] = useState<EscalationLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  useEffect(() => {
    fetchHistory();
  }, [page]);

  const fetchHistory = async () => {
    setLoading(true);
    try {
      const res = await fetch(
        buildApiUrl(`super-admin/dev/escalations?page=${page}&limit=20`),
        {
          headers: tokenManager.createAuthHeaders(),
        },
      );
      const data = await res.json();
      if (data.success) {
        setLogs(data.data);
        setTotalPages(data.pagination.pages);
      }
    } catch (error) {
      console.error("Failed to fetch history", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 flex items-center gap-2">
            <ClockIcon className="h-8 w-8 text-indigo-500" />
            سجل تصعيد المهام
          </h1>
          <p className="text-gray-500 text-sm mt-1">
            تتبع المهام التي تم نقلها تلقائياً بسبب التأخير.
          </p>
        </div>
        <button
          onClick={() => window.history.back()}
          className="px-4 py-2 text-gray-600 hover:text-gray-800 flex items-center gap-2"
        >
          <ArrowUturnLeftIcon className="h-5 w-5" />
          عودة
        </button>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead className="bg-gray-50 dark:bg-gray-700/50 text-gray-500 dark:text-gray-400 text-sm uppercase">
              <tr>
                <th className="px-6 py-4 font-medium">المهمة</th>
                <th className="px-6 py-4 font-medium">نقل من</th>
                <th className="px-6 py-4 font-medium">نقل إلى</th>
                <th className="px-6 py-4 font-medium">السبب / الوصف</th>
                <th className="px-6 py-4 font-medium">التاريخ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {loading ? (
                <tr>
                  <td
                    colSpan={5}
                    className="px-6 py-8 text-center text-gray-500"
                  >
                    جاري التحميل...
                  </td>
                </tr>
              ) : logs.length === 0 ? (
                <tr>
                  <td
                    colSpan={5}
                    className="px-6 py-8 text-center text-gray-500"
                  >
                    لا توجد سجلات تصعيد حتى الآن.
                  </td>
                </tr>
              ) : (
                logs.map((log) => (
                  <tr
                    key={log.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors"
                  >
                    <td className="px-6 py-4">
                      <a
                        href={`/super-admin/dev-tasks/${log.task.id}`}
                        className="font-medium text-indigo-600 hover:text-indigo-800 dark:text-indigo-400 block truncate max-w-xs"
                        title={log.task.title}
                      >
                        {log.task.title}
                      </a>
                      <span className="text-xs text-gray-400 font-mono">
                        {log.task.id.slice(0, 8)}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                        <div className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center text-xs font-bold text-gray-500">
                          {log.fromUser.charAt(0)}
                        </div>
                        <span>{log.fromUser}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 text-gray-900 dark:text-white font-medium">
                        <div className="w-8 h-8 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs font-bold">
                          {log.toUser.charAt(0)}
                        </div>
                        <span>{log.toUser}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-600 dark:text-gray-400">
                      {log.description}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500 whitespace-nowrap">
                      {format(new Date(log.createdAt), "PPP p", { locale: ar })}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="p-4 border-t border-gray-100 dark:border-gray-700 flex justify-center gap-2">
            <button
              disabled={page === 1}
              onClick={() => setPage((p) => p - 1)}
              className="px-3 py-1 rounded border disabled:opacity-50 hover:bg-gray-50 dark:hover:bg-gray-700"
            >
              السابق
            </button>
            <span className="px-3 py-1 text-gray-600 dark:text-gray-400">
              صفحة {page} من {totalPages}
            </span>
            <button
              disabled={page === totalPages}
              onClick={() => setPage((p) => p + 1)}
              className="px-3 py-1 rounded border disabled:opacity-50 hover:bg-gray-50 dark:hover:bg-gray-700"
            >
              التالي
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default EscalationHistory;

import React, { useState, useEffect } from 'react';
import {
    Box,
    Typography,
    Paper,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Button,
    Chip,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    CircularProgress,
    IconButton
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import { toast } from 'react-hot-toast';
import { apiClient } from '../../services/apiClient';
import { Eye, CheckCircle, XCircle } from 'lucide-react';

interface Receipt {
    id: string;
    amount: number;
    currency: string;
    status: string;
    receiptImage: string;
    createdAt: string;
    walletNumber?: {
        walletNumber: string;
        provider: string;
    };
    invoice?: {
        companyId: string;
        totalAmount: number;
        currency: string;
        company?: {
            name: string;
            email: string;
        };
    };
}

const getFullImageUrl = (path: string) => {
    if (!path) return '';
    // Normalize backslashes to forward slashes for URL compatibility
    const normalizedPath = path.replace(/\\/g, '/');
    // Convert standard backend upload paths to full URL
    if (normalizedPath.startsWith('uploads/')) {
        return `http://localhost:3000/${normalizedPath}`; // Ensure full URL for local dev
    }
    return normalizedPath;
};

const PendingReceipts: React.FC = () => {
    const { t } = useTranslation();
    const [receipts, setReceipts] = useState<Receipt[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedImage, setSelectedImage] = useState<string | null>(null);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    const fetchReceipts = async () => {
        try {
            setLoading(true);
            const response = await apiClient.get('/wallet-payment/admin/pending-receipts');
            if (response.data.success) {
                setReceipts(response.data.data || []);
            }
        } catch (error) {
            console.error('Error fetching receipts:', error);
            toast.error(t('فشل في جلب الإيصالات المعلقة'));
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchReceipts();
    }, []);

    const handleReview = async (id: string, status: 'APPROVED' | 'REJECTED') => {
        try {
            setActionLoading(id);
            const response = await apiClient.post(`/wallet-payment/admin/review-receipt/${id}`, { status });
            if (response.data.success) {
                toast.success(status === 'APPROVED' ? t('تم قبول الإيصال وإيداع الرصيد بنجاح') : t('تم رفض الإيصال'));
                // Remove from list
                setReceipts(prev => prev.filter(r => r.id !== id));
            } else {
                throw new Error(response.data.message || 'Unknown error');
            }
        } catch (error: any) {
            console.error('Error reviewing receipt:', error);
            toast.error(error.message || t('حدث خطأ أثناء المراجعة'));
        } finally {
            setActionLoading(null);
        }
    };

    return (
        <Box>
            <Typography variant="h4" fontWeight="bold" mb={3}>
                {t('مراجعة إيصالات الشحن')}
            </Typography>

            <Paper elevation={0} sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 2, overflow: 'hidden' }}>
                <TableContainer>
                    <Table>
                        <TableHead sx={{ bgcolor: 'background.default' }}>
                            <TableRow>
                                <TableCell>{t('الرقم المرجعي')}</TableCell>
                                <TableCell>{t('الشركة / العميل')}</TableCell>
                                <TableCell>{t('المبلغ المعروض')}</TableCell>
                                <TableCell>{t('المحفظة المحول إليها')}</TableCell>
                                <TableCell>{t('التاريخ')}</TableCell>
                                <TableCell align="center">{t('الإيصال')}</TableCell>
                                <TableCell align="center">{t('الإجراءات')}</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {loading ? (
                                <TableRow>
                                    <TableCell colSpan={7} align="center" sx={{ py: 6 }}>
                                        <CircularProgress />
                                    </TableCell>
                                </TableRow>
                            ) : receipts.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={7} align="center" sx={{ py: 6 }}>
                                        <Typography color="text.secondary">{t('لا توجد إيصالات معلقة حالياً')}</Typography>
                                    </TableCell>
                                </TableRow>
                            ) : (
                                receipts.map((receipt) => (
                                    <TableRow key={receipt.id}>
                                        <TableCell>
                                            <Typography variant="caption" sx={{ fontFamily: 'monospace' }}>
                                                {receipt.id.substring(0, 8)}...
                                            </Typography>
                                        </TableCell>
                                        <TableCell>
                                            {receipt.invoice?.company ? (
                                                <Box>
                                                    <Typography variant="body2">{receipt.invoice.company.name}</Typography>
                                                    <Typography variant="caption" color="text.secondary">{receipt.invoice.company.email}</Typography>
                                                </Box>
                                            ) : (
                                                <Chip label={receipt.invoice?.companyId || 'N/A'} size="small" variant="outlined" />
                                            )}
                                        </TableCell>
                                        <TableCell>
                                            <Typography fontWeight="bold" color="primary">
                                                {receipt.invoice?.totalAmount} {receipt.invoice?.currency || 'EGP'}
                                            </Typography>
                                        </TableCell>
                                        <TableCell>
                                            {receipt.walletNumber ? (
                                                <Box>
                                                    <Typography variant="body2">{receipt.walletNumber.number}</Typography>
                                                    <Typography variant="caption" color="text.secondary">{receipt.walletNumber.name}</Typography>
                                                </Box>
                                            ) : '-'}
                                        </TableCell>
                                        <TableCell>
                                            {new Date(receipt.createdAt).toLocaleString('ar-EG')}
                                        </TableCell>
                                        <TableCell align="center">
                                            <IconButton color="primary" onClick={() => setSelectedImage(getFullImageUrl(receipt.receiptImage))}>
                                                <Eye size={20} />
                                            </IconButton>
                                        </TableCell>
                                        <TableCell align="center">
                                            <Box display="flex" gap={1} justifyContent="center">
                                                <Button
                                                    variant="contained"
                                                    color="success"
                                                    size="small"
                                                    startIcon={actionLoading === receipt.id ? <CircularProgress size={16} color="inherit" /> : <CheckCircle size={16} />}
                                                    onClick={() => handleReview(receipt.id, 'APPROVED')}
                                                    disabled={actionLoading !== null}
                                                >
                                                    {t('قبول')}
                                                </Button>
                                                <Button
                                                    variant="outlined"
                                                    color="error"
                                                    size="small"
                                                    startIcon={<XCircle size={16} />}
                                                    onClick={() => handleReview(receipt.id, 'REJECTED')}
                                                    disabled={actionLoading !== null}
                                                >
                                                    {t('رفض')}
                                                </Button>
                                            </Box>
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                </TableContainer>
            </Paper>

            <Dialog open={!!selectedImage} onClose={() => setSelectedImage(null)} maxWidth="md" fullWidth>
                <DialogTitle>{t('استعراض صورة الإيصال')}</DialogTitle>
                <DialogContent sx={{ display: 'flex', justifyContent: 'center', p: 3, bgcolor: '#f5f5f5' }}>
                    {selectedImage && (
                        <img
                            src={selectedImage}
                            alt="Receipt"
                            style={{ maxWidth: '100%', maxHeight: '70vh', objectFit: 'contain', borderRadius: 8, boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                        />
                    )}
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setSelectedImage(null)}>{t('إغلاق')}</Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default PendingReceipts;

import React, { useState, useEffect } from "react";
import {
    Box,
    Card,
    CardContent,
    Typography,
    Button,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    Chip,
    IconButton,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField,
    Grid,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    CircularProgress,
    Tabs,
    Tab,
    Alert,
    Avatar,
    Stack,
    alpha,
    Tooltip,
    Divider,
    InputAdornment
} from "@mui/material";
import {
    Edit as EditIcon,
    TrendingUp as TrendingIcon,
    People as PeopleIcon,
    Wallet as WalletIcon,
    History as HistoryIcon,
    AccountBalance as BankIcon,
    Settings as SettingsIcon,
    Save as SaveIcon
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";
import { useCurrency } from "../../hooks/useCurrency";
import toast from "react-hot-toast";
import { useTheme } from "../../hooks/useTheme";

const PlatformPartnerManagement = () => {
    const { formatPrice } = useCurrency();
    const { actualTheme } = useTheme();
    const isDark = actualTheme === "dark";

    const [activeTab, setActiveTab] = useState(0);
    const [stats, setStats] = useState<any>(null);
    const [partners, setPartners] = useState<any[]>([]);
    const [payouts, setPayouts] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [savingSettings, setSavingSettings] = useState(false);

    // Settings State
    const [settings, setSettings] = useState<any>(null);
    const [settingsForm, setSettingsForm] = useState({
        level1Rate: 20,
        level2Rate: 5,
        level3Rate: 3,
        level4Rate: 1,
        minimumPayoutAmount: 100,
        termsAndConditions: ""
    });

    // Dialog States
    const [rankDialogOpen, setRankDialogOpen] = useState(false);
    const [selectedPartner, setSelectedPartner] = useState<any>(null);
    const [newTitle, setNewTitle] = useState("");

    const [payoutDialogOpen, setPayoutDialogOpen] = useState(false);
    const [selectedPayout, setSelectedPayout] = useState<any>(null);
    const [payoutStatus, setPayoutStatus] = useState("COMPLETED");

    useEffect(() => {
        fetchData();
    }, [activeTab]);

    const fetchData = async () => {
        try {
            setLoading(true);
            const [statsRes, partnersRes, payoutsRes, settingsRes] = await Promise.all([
                apiClient.get("/platform-partners/admin/stats"),
                apiClient.get("/platform-partners/admin/partners"),
                apiClient.get("/platform-partners/admin/payouts"),
                apiClient.get("/platform-partners/admin/settings")
            ]);

            if (statsRes.data.status === "success") setStats(statsRes.data.data.stats);
            if (partnersRes.data.status === "success") setPartners(partnersRes.data.data.partners);
            if (payoutsRes.data.status === "success") setPayouts(payoutsRes.data.data.payouts);
            if (settingsRes.data.status === "success") {
                const s = settingsRes.data.data.settings;
                setSettings(s);
                setSettingsForm({
                    level1Rate: s.level1Rate,
                    level2Rate: s.level2Rate,
                    level3Rate: s.level3Rate,
                    level4Rate: s.level4Rate,
                    minimumPayoutAmount: Number(s.minimumPayoutAmount),
                    termsAndConditions: s.termsAndConditions || ""
                });
            }
        } catch (error: any) {
            toast.error("خطأ في تحميل البيانات");
        } finally {
            setLoading(false);
        }
    };

    const handleUpdateRank = async () => {
        if (!selectedPartner || !newTitle) return;
        try {
            const response = await apiClient.put(`/platform-partners/admin/partners/${selectedPartner.id}/title`, {
                title: newTitle
            });
            if (response.data.status === "success") {
                toast.success("Partner rank updated");
                setRankDialogOpen(false);
                fetchData();
            }
        } catch (error: any) {
            toast.error(error.response?.data?.message || "Failed to update rank");
        }
    };

    const handleProcessPayout = async () => {
        if (!selectedPayout) return;
        try {
            const response = await apiClient.put(`/platform-partners/admin/payouts/${selectedPayout.id}`, {
                status: payoutStatus
            });
            if (response.data.status === "success") {
                toast.success(`Payout ${payoutStatus.toLowerCase()}`);
                setPayoutDialogOpen(false);
                fetchData();
            }
        } catch (error: any) {
            toast.error(error.response?.data?.message || "Failed to process payout");
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case "ACTIVE": return "success";
            case "PENDING": return "warning";
            case "COMPLETED": return "success";
            case "REJECTED": return "error";
            default: return "default";
        }
    };

    if (loading && !stats) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
                <CircularProgress />
            </Box>
        );
    }

    return (
        <Box sx={{ p: 1 }}>
            <Typography variant="h4" sx={{ mb: 4, fontWeight: 800, color: isDark ? "#f8fafc" : "#1e293b" }}>
                إدارة برنامج الشركاء
            </Typography>

            {/* Stats Grid */}
            <Grid container spacing={3} sx={{ mb: 4 }}>
                {[
                    { label: "إجمالي العمولات", value: formatPrice(stats?.totalCommissionsDistributed || 0), icon: <WalletIcon />, color: "#10b981" },
                    { label: "إجمالي الشركاء", value: stats?.totalPartners || 0, icon: <PeopleIcon />, color: "#3b82f6" },
                    { label: "مدفوعات معلقة", value: formatPrice(stats?.totalPendingPayouts || 0), icon: <HistoryIcon />, color: "#f59e0b" },
                    { label: "نمو الشبكة", value: stats?.activeCompaniesCount || 0, icon: <TrendingIcon />, color: "#8b5cf6" }
                ].map((stat, i) => (
                    <Grid key={i} size={{ xs: 12, sm: 6, md: 3 }}>
                        <Card sx={{
                            borderRadius: 4,
                            boxShadow: isDark ? "0 10px 15px -3px rgba(0,0,0,0.5)" : "0 4px 6px -1px rgba(0,0,0,0.1)",
                            bgcolor: isDark ? "#1e293b" : "#fff",
                            border: "1px solid",
                            borderColor: isDark ? alpha("#fff", 0.05) : alpha("#000", 0.05)
                        }}>
                            <CardContent sx={{ p: 3 }}>
                                <Box display="flex" justifyContent="space-between" alignItems="center">
                                    <Box>
                                        <Typography variant="body2" sx={{ color: isDark ? "#94a3b8" : "#64748b", mb: 1 }}>{stat.label}</Typography>
                                        <Typography variant="h5" sx={{ fontWeight: 800 }}>{stat.value}</Typography>
                                    </Box>
                                    <Avatar sx={{ bgcolor: alpha(stat.color, 0.1), color: stat.color, width: 56, height: 56 }}>
                                        {stat.icon}
                                    </Avatar>
                                </Box>
                            </CardContent>
                        </Card>
                    </Grid>
                ))}
            </Grid>

            <Paper sx={{
                width: "100%",
                borderRadius: 4,
                overflow: "hidden",
                bgcolor: isDark ? "#1e293b" : "#fff",
                boxShadow: "0 20px 25px -5px rgba(0,0,0,0.1)"
            }}>
                <Tabs
                    value={activeTab}
                    onChange={(_, v) => setActiveTab(v)}
                    sx={{
                        borderBottom: 1,
                        borderColor: "divider",
                        px: 2,
                        pt: 2,
                        "& .MuiTab-root": { fontWeight: 600, px: 4 }
                    }}
                >
                    <Tab label="الشركاء (PARTNERS)" />
                    <Tab label="طلبات السحب (PAYOUTS)" />
                    <Tab label="⚙️ الإعدادات (SETTINGS)" />
                </Tabs>

                <Box sx={{ p: 0 }}>
                    {activeTab === 0 ? (
                        <TableContainer>
                            <Table>
                                <TableHead sx={{ bgcolor: isDark ? alpha("#fff", 0.02) : "#f8fafc" }}>
                                    <TableRow>
                                        <TableCell sx={{ fontWeight: 700 }}>الشريك</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>اللقب (Rank)</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>إجمالي الأرباح</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>الرصيد المتاح</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>الحالة</TableCell>
                                        <TableCell align="center" sx={{ fontWeight: 700 }}>الإجراءات</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {partners.map((partner) => (
                                        <TableRow key={partner.id} hover>
                                            <TableCell>
                                                <Stack direction="row" spacing={2} alignItems="center">
                                                    <Avatar sx={{ bgcolor: "#3b82f6" }}>{partner.user?.firstName?.charAt(0)}</Avatar>
                                                    <Box>
                                                        <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>{partner.user?.firstName} {partner.user?.lastName}</Typography>
                                                        <Typography variant="caption" color="textSecondary">{partner.partnerCode}</Typography>
                                                    </Box>
                                                </Stack>
                                            </TableCell>
                                            <TableCell>
                                                <Chip label={partner.title} size="small" sx={{ fontWeight: 700, borderRadius: 1 }} />
                                            </TableCell>
                                            <TableCell>{formatPrice(partner.totalEarnings)}</TableCell>
                                            <TableCell sx={{ color: "#3b82f6", fontWeight: 700 }}>{formatPrice(partner.pendingEarnings)}</TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={partner.status}
                                                    color={getStatusColor(partner.status)}
                                                    size="small"
                                                    variant="outlined"
                                                />
                                            </TableCell>
                                            <TableCell align="center">
                                                <Tooltip title="تعديل الرتبة">
                                                    <IconButton onClick={() => { setSelectedPartner(partner); setNewTitle(partner.title); setRankDialogOpen(true); }}>
                                                        <EditIcon />
                                                    </IconButton>
                                                </Tooltip>
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    ) : activeTab === 1 ? (
                        <TableContainer>
                            <Table>
                                <TableHead sx={{ bgcolor: isDark ? alpha("#fff", 0.02) : "#f8fafc" }}>
                                    <TableRow>
                                        <TableCell sx={{ fontWeight: 700 }}>الشريك</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>المبلغ</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>الطريقة</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>التاريخ</TableCell>
                                        <TableCell sx={{ fontWeight: 700 }}>الحالة</TableCell>
                                        <TableCell align="center" sx={{ fontWeight: 700 }}>الإجراءات</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {payouts.map((payout) => (
                                        <TableRow key={payout.id} hover>
                                            <TableCell>
                                                <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>{payout.partner?.user?.firstName} {payout.partner?.user?.lastName}</Typography>
                                                <Typography variant="caption" color="textSecondary">{payout.partner?.partnerCode}</Typography>
                                            </TableCell>
                                            <TableCell sx={{ fontWeight: 800, color: "#ef4444" }}>{formatPrice(payout.amount)}</TableCell>
                                            <TableCell>
                                                <Stack direction="row" spacing={1} alignItems="center">
                                                    <BankIcon fontSize="small" sx={{ color: "#64748b" }} />
                                                    <Typography variant="body2">{payout.method}</Typography>
                                                </Stack>
                                            </TableCell>
                                            <TableCell>{new Date(payout.createdAt).toLocaleDateString()}</TableCell>
                                            <TableCell>
                                                <Chip label={payout.status} color={getStatusColor(payout.status)} size="small" />
                                            </TableCell>
                                            <TableCell align="center">
                                                {payout.status === "PENDING" && (
                                                    <IconButton onClick={() => { setSelectedPayout(payout); setPayoutDialogOpen(true); }}>
                                                        <EditIcon />
                                                    </IconButton>
                                                )}
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    ) : (
                        /* Settings Tab */
                        <Box sx={{ p: 4 }}>
                            <Stack direction="row" spacing={2} alignItems="center" sx={{ mb: 3 }}>
                                <SettingsIcon sx={{ color: "#8b5cf6" }} />
                                <Typography variant="h6" sx={{ fontWeight: 700 }}>إعدادات برنامج الشركاء</Typography>
                            </Stack>

                            <Alert severity="info" sx={{ mb: 4, borderRadius: 2 }}>
                                تحديد نِسَب العمولات يؤثر على جميع المدفوعات الجديدة فور الحفظ. المدفوعات السابقة لن تتأثر.
                            </Alert>

                            <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 2, color: isDark ? "#94a3b8" : "#475569" }}>
                                نِسَب العمولات لكل مستوى إحالة
                            </Typography>

                            <Grid container spacing={3} sx={{ mb: 4 }}>
                                {[
                                    { key: "level1Rate", label: "المستوى الأول", desc: "الشريك المباشر - PARTNER", color: "#3b82f6" },
                                    { key: "level2Rate", label: "المستوى الثاني", desc: "يتطلب رتبة SENIOR_PARTNER", color: "#8b5cf6" },
                                    { key: "level3Rate", label: "المستوى الثالث", desc: "يتطلب رتبة MASTER_PARTNER", color: "#f59e0b" },
                                    { key: "level4Rate", label: "المستوى الرابع", desc: "يتطلب رتبة EXECUTIVE_PARTNER", color: "#10b981" },
                                ].map((level) => (
                                    <Grid key={level.key} size={{ xs: 12, sm: 6, md: 3 }}>
                                        <Card sx={{
                                            borderRadius: 3,
                                            border: `2px solid ${alpha(level.color, 0.3)}`,
                                            bgcolor: isDark ? alpha(level.color, 0.05) : alpha(level.color, 0.04)
                                        }}>
                                            <CardContent sx={{ p: 2 }}>
                                                <Typography variant="caption" sx={{ fontWeight: 700, color: level.color }}>{level.label}</Typography>
                                                <Typography variant="caption" display="block" color="textSecondary" sx={{ mb: 1.5 }}>{level.desc}</Typography>
                                                <TextField
                                                    type="number"
                                                    size="small"
                                                    fullWidth
                                                    value={settingsForm[level.key as keyof typeof settingsForm]}
                                                    onChange={(e) => setSettingsForm(prev => ({ ...prev, [level.key]: Number(e.target.value) }))}
                                                    InputProps={{
                                                        endAdornment: <InputAdornment position="end">%</InputAdornment>
                                                    }}
                                                    inputProps={{ min: 0, max: 100, step: 0.5 }}
                                                />
                                            </CardContent>
                                        </Card>
                                    </Grid>
                                ))}
                            </Grid>

                            <Divider sx={{ my: 3 }} />

                            <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 2, color: isDark ? "#94a3b8" : "#475569" }}>
                                إعدادات المدفوعات
                            </Typography>

                            <Grid container spacing={3} sx={{ mb: 4 }}>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <TextField
                                        label="الحد الأدنى لطلب السحب"
                                        type="number"
                                        fullWidth
                                        value={settingsForm.minimumPayoutAmount}
                                        onChange={(e) => setSettingsForm(prev => ({ ...prev, minimumPayoutAmount: Number(e.target.value) }))}
                                        InputProps={{
                                            endAdornment: <InputAdornment position="end">ج.م</InputAdornment>
                                        }}
                                        inputProps={{ min: 0, step: 10 }}
                                    />
                                </Grid>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <TextField
                                        label="الشروط والأحكام (اختياري)"
                                        fullWidth
                                        multiline
                                        minRows={3}
                                        value={settingsForm.termsAndConditions}
                                        onChange={(e) => setSettingsForm(prev => ({ ...prev, termsAndConditions: e.target.value }))}
                                        placeholder="أدخل شروط وأحكام برنامج الشركاء هنا..."
                                    />
                                </Grid>
                            </Grid>

                            <Button
                                variant="contained"
                                size="large"
                                startIcon={savingSettings ? <CircularProgress size={16} color="inherit" /> : <SaveIcon />}
                                disabled={savingSettings}
                                onClick={async () => {
                                    try {
                                        setSavingSettings(true);
                                        const res = await apiClient.put("/platform-partners/admin/settings", settingsForm);
                                        if (res.data.status === "success") {
                                            toast.success("تم حفظ الإعدادات بنجاح ✅");
                                            fetchData();
                                        }
                                    } catch (err: any) {
                                        toast.error(err.response?.data?.message || "فشل حفظ الإعدادات");
                                    } finally {
                                        setSavingSettings(false);
                                    }
                                }}
                                sx={{ bgcolor: "#8b5cf6", "&:hover": { bgcolor: "#7c3aed" }, px: 4 }}
                            >
                                حفظ الإعدادات
                            </Button>
                        </Box>
                    )}
                </Box>
            </Paper>

            {/* Rank Dialog */}
            <Dialog open={rankDialogOpen} onClose={() => setRankDialogOpen(false)} maxWidth="xs" fullWidth>
                <DialogTitle sx={{ fontWeight: 700 }}>تعديل لقب الشريك</DialogTitle>
                <DialogContent>
                    <Box sx={{ py: 2 }}>
                        <FormControl fullWidth>
                            <InputLabel>اللقب الجديد</InputLabel>
                            <Select value={newTitle} label="اللقب الجديد" onChange={(e) => setNewTitle(e.target.value)}>
                                <MenuItem value="PARTNER">Partner</MenuItem>
                                <MenuItem value="SENIOR_PARTNER">Senior Partner</MenuItem>
                                <MenuItem value="EXECUTIVE_PARTNER">Executive Partner</MenuItem>
                                <MenuItem value="REGIONAL_DIRECTOR">Regional Director</MenuItem>
                            </Select>
                        </FormControl>
                        <Alert severity="info" sx={{ mt: 3 }}>
                            اللقب يحدد عمق العمولات (مستوى 1 إلى 4).
                        </Alert>
                    </Box>
                </DialogContent>
                <DialogActions sx={{ px: 3, pb: 2 }}>
                    <Button onClick={() => setRankDialogOpen(false)}>إلغاء</Button>
                    <Button variant="contained" onClick={handleUpdateRank}>حفظ التغييرات</Button>
                </DialogActions>
            </Dialog>

            {/* Payout Dialog */}
            <Dialog open={payoutDialogOpen} onClose={() => setPayoutDialogOpen(false)} maxWidth="xs" fullWidth>
                <DialogTitle sx={{ fontWeight: 700 }}>معالجة طلب السحب</DialogTitle>
                <DialogContent>
                    <Box sx={{ py: 2 }}>
                        <Typography variant="subtitle2" gutterBottom>بيانات الشريك:</Typography>
                        <Typography variant="body2" color="textSecondary">
                            {selectedPayout?.partner?.user?.firstName} ({selectedPayout?.partner?.partnerCode})
                        </Typography>
                        <Typography variant="h6" sx={{ my: 2, color: "#ef4444", fontWeight: 800 }}>
                            {formatPrice(selectedPayout?.amount || 0)}
                        </Typography>

                        <FormControl fullWidth sx={{ mt: 2 }}>
                            <InputLabel>تحديث الحالة</InputLabel>
                            <Select value={payoutStatus} label="تحديث الحالة" onChange={(e) => setPayoutStatus(e.target.value)}>
                                <MenuItem value="COMPLETED">مكتمل (تم التحويل)</MenuItem>
                                <MenuItem value="REJECTED">مرفوض</MenuItem>
                            </Select>
                        </FormControl>
                    </Box>
                </DialogContent>
                <DialogActions sx={{ px: 3, pb: 2 }}>
                    <Button onClick={() => setPayoutDialogOpen(false)}>إلغاء</Button>
                    <Button variant="contained" color={payoutStatus === "COMPLETED" ? "success" : "error"} onClick={handleProcessPayout}>
                        تأكيد العملية
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default PlatformPartnerManagement;

import React, { useEffect, useMemo, useState } from "react";
import {
  CalendarRange,
  Gift,
  Plus,
  RefreshCw,
  Search,
  Sparkles,
  Ticket,
  Trash2,
  Users,
} from "lucide-react";
import toast from "react-hot-toast";

import {
  BusinessFilterSheet,
  BusinessMobileSearchPanel,
} from "../../components/business/BusinessFilters";
import {
  BusinessPageHero,
  BusinessPageShell,
  BusinessSectionPanel,
} from "../../components/business/BusinessSurface";
import { BusinessMetricsStrip } from "../../components/business/BusinessMetrics";
import { Badge } from "../../components/ui/badge";
import { Button } from "../../components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { Switch } from "../../components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import { Textarea } from "../../components/ui/textarea";
import {
  platformSignupCouponService,
  type PlatformSignupCoupon,
  type PlatformSignupCouponBenefits,
  type PlatformSignupCouponFormPayload,
  type PlatformSignupCouponSummary,
} from "../../services/platformSignupCouponService";

type CouponStateFilter =
  | "all"
  | "live"
  | "scheduled"
  | "expired"
  | "inactive"
  | "depleted";

const stateOptions: Array<{
  value: CouponStateFilter;
  label: string;
}> = [
  { value: "all", label: "كل الحالات" },
  { value: "live", label: "فعّال الآن" },
  { value: "scheduled", label: "مجدول" },
  { value: "expired", label: "منتهي" },
  { value: "inactive", label: "موقوف" },
  { value: "depleted", label: "مستهلك" },
];

const createDefaultFormState = (): PlatformSignupCouponFormPayload => {
  const now = new Date();
  const validTo = new Date(now);
  validTo.setDate(validTo.getDate() + 30);

  return {
    name: "",
    code: "",
    description: "",
    usageLimit: null,
    isActive: true,
    validFrom: now.toISOString().slice(0, 16),
    validTo: validTo.toISOString().slice(0, 16),
    ...platformSignupCouponService.zeroBenefits,
  };
};

const toDateTimeInputValue = (value?: string | null) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  const offset = date.getTimezoneOffset();
  const localDate = new Date(date.getTime() - offset * 60_000);
  return localDate.toISOString().slice(0, 16);
};

const mapCouponToForm = (
  coupon: PlatformSignupCoupon,
): PlatformSignupCouponFormPayload => ({
  name: coupon.name,
  code: coupon.code,
  description: coupon.description || "",
  trialDays: coupon.trialDays,
  bonusUsers: coupon.bonusUsers,
  bonusProducts: coupon.bonusProducts,
  bonusOrdersPerMonth: coupon.bonusOrdersPerMonth,
  bonusCustomers: coupon.bonusCustomers,
  usageLimit: coupon.usageLimit,
  isActive: coupon.isActive,
  validFrom: toDateTimeInputValue(coupon.validFrom),
  validTo: toDateTimeInputValue(coupon.validTo),
});

const formatDate = (value?: string | null) => {
  if (!value) return "غير محدد";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "غير محدد";
  return date.toLocaleDateString("ar-EG", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
};

const buildBenefitList = (coupon: PlatformSignupCoupon) =>
  [
    coupon.trialDays > 0 ? `${coupon.trialDays} يوم مجاني` : null,
    coupon.bonusUsers > 0 ? `${coupon.bonusUsers} مستخدم إضافي` : null,
    coupon.bonusProducts > 0 ? `${coupon.bonusProducts} منتج إضافي` : null,
    coupon.bonusOrdersPerMonth > 0
      ? `${coupon.bonusOrdersPerMonth} طلب إضافي شهريًا`
      : null,
    coupon.bonusCustomers > 0
      ? `${coupon.bonusCustomers} عميل إضافي`
      : null,
  ].filter(Boolean) as string[];

const stateBadgeClassName = (state: PlatformSignupCoupon["state"]) => {
  if (state === "live") {
    return "border-emerald-200 bg-emerald-50 text-emerald-700";
  }
  if (state === "scheduled") {
    return "border-blue-200 bg-blue-50 text-blue-700";
  }
  if (state === "expired") {
    return "border-slate-200 bg-slate-100 text-slate-600";
  }
  if (state === "depleted") {
    return "border-amber-200 bg-amber-50 text-amber-700";
  }
  return "border-rose-200 bg-rose-50 text-rose-700";
};

const stateLabel = (state: PlatformSignupCoupon["state"]) => {
  if (state === "live") return "فعّال الآن";
  if (state === "scheduled") return "مجدول";
  if (state === "expired") return "منتهي";
  if (state === "depleted") return "مستهلك";
  return "موقوف";
};

const summaryFallback: PlatformSignupCouponSummary = {
  totalCoupons: 0,
  liveCoupons: 0,
  scheduledCoupons: 0,
  expiredCoupons: 0,
  inactiveCoupons: 0,
  depletedCoupons: 0,
  totalRedemptions: 0,
};

const numericBenefitFields: Array<{
  key: keyof PlatformSignupCouponBenefits;
  label: string;
  placeholder: string;
}> = [
  { key: "trialDays", label: "أيام التجربة المجانية", placeholder: "7" },
  { key: "bonusUsers", label: "مستخدمون إضافيون", placeholder: "5" },
  { key: "bonusProducts", label: "منتجات إضافية", placeholder: "100" },
  {
    key: "bonusOrdersPerMonth",
    label: "طلبات إضافية شهريًا",
    placeholder: "200",
  },
  { key: "bonusCustomers", label: "عملاء إضافيون", placeholder: "500" },
];

const PlatformSignupCoupons: React.FC = () => {
  const [coupons, setCoupons] = useState<PlatformSignupCoupon[]>([]);
  const [summary, setSummary] =
    useState<PlatformSignupCouponSummary>(summaryFallback);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [stateFilter, setStateFilter] = useState<CouponStateFilter>("all");
  const [filterSheetOpen, setFilterSheetOpen] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingCoupon, setEditingCoupon] = useState<PlatformSignupCoupon | null>(
    null,
  );
  const [couponPendingRemoval, setCouponPendingRemoval] =
    useState<PlatformSignupCoupon | null>(null);
  const [removing, setRemoving] = useState(false);
  const [formState, setFormState] =
    useState<PlatformSignupCouponFormPayload>(createDefaultFormState);

  const activeFilterLabels = useMemo(() => {
    if (stateFilter === "all") return [];
    const option = stateOptions.find((item) => item.value === stateFilter);
    return option ? [option.label] : [];
  }, [stateFilter]);

  const metricItems = useMemo(
    () => [
      {
        title: "إجمالي الكوبونات",
        value: summary.totalCoupons.toLocaleString("ar-EG"),
        subtitle: "عدد كل كوبونات onboarding المتاحة للإدارة.",
        tone: "primary" as const,
        icon: Ticket,
      },
      {
        title: "الكوبونات الحية",
        value: summary.liveCoupons.toLocaleString("ar-EG"),
        subtitle: "الصالحة الآن للاستخدام في شاشة التسجيل.",
        tone: "success" as const,
        icon: Sparkles,
      },
      {
        title: "إجمالي الاسترداد",
        value: summary.totalRedemptions.toLocaleString("ar-EG"),
        subtitle: "عدد الشركات التي استخدمت كوبونًا عند التسجيل.",
        tone: "secondary" as const,
        icon: Gift,
      },
      {
        title: "المستهلك والمنتهي",
        value: (
          summary.depletedCoupons + summary.expiredCoupons
        ).toLocaleString("ar-EG"),
        subtitle: "كوبونات تحتاج مراجعة أو إعادة تفعيل بخطة جديدة.",
        tone: "warning" as const,
        icon: CalendarRange,
      },
    ],
    [summary],
  );

  const loadCoupons = async (nextSearch = search, nextState = stateFilter) => {
    try {
      setLoading(true);
      const response = await platformSignupCouponService.listCoupons(
        nextSearch,
        nextState,
      );
      setCoupons(response.items);
      setSummary(response.summary);
    } catch (error) {
      console.error("Failed to load platform signup coupons", error);
      toast.error("فشل تحميل كوبونات التسجيل");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadCoupons();
  }, [search, stateFilter]);

  const openCreateDialog = () => {
    setEditingCoupon(null);
    setFormState(createDefaultFormState());
    setDialogOpen(true);
  };

  const openEditDialog = (coupon: PlatformSignupCoupon) => {
    setEditingCoupon(coupon);
    setFormState(mapCouponToForm(coupon));
    setDialogOpen(true);
  };

  const openRemoveDialog = (coupon: PlatformSignupCoupon) => {
    setCouponPendingRemoval(coupon);
  };

  const updateBenefitField = (
    key: keyof PlatformSignupCouponBenefits,
    value: string,
  ) => {
    setFormState((previous) => ({
      ...previous,
      [key]: Math.max(0, Number.parseInt(value || "0", 10) || 0),
    }));
  };

  const handleSaveCoupon = async () => {
    try {
      setSaving(true);
      const payload: PlatformSignupCouponFormPayload = {
        ...formState,
        code: formState.code.trim().toUpperCase(),
        name: formState.name.trim(),
        description: formState.description.trim(),
      };

      const savedCoupon = editingCoupon
        ? await platformSignupCouponService.updateCoupon(editingCoupon.id, payload)
        : await platformSignupCouponService.createCoupon(payload);

      setDialogOpen(false);
      setEditingCoupon(null);
      setFormState(createDefaultFormState());
      toast.success(
        editingCoupon
          ? "تم تحديث كوبون التسجيل"
          : "تم إنشاء كوبون التسجيل",
      );

      setCoupons((previous) => {
        if (editingCoupon) {
          return previous.map((coupon) =>
            coupon.id === savedCoupon.id ? savedCoupon : coupon,
          );
        }

        return [savedCoupon, ...previous];
      });

      await loadCoupons();
    } catch (error: any) {
      console.error("Failed to save platform signup coupon", error);
      toast.error(
        error?.response?.data?.message ||
          error?.message ||
          "فشل حفظ كوبون التسجيل",
      );
    } finally {
      setSaving(false);
    }
  };

  const handleRemoveCoupon = async () => {
    if (!couponPendingRemoval) return;

    try {
      setRemoving(true);
      const result = await platformSignupCouponService.removeCoupon(
        couponPendingRemoval.id,
      );

      if (result.action === "deleted") {
        setCoupons((previous) =>
          previous.filter((coupon) => coupon.id !== couponPendingRemoval.id),
        );
        toast.success("تم حذف كوبون التسجيل");
      } else {
        setCoupons((previous) =>
          previous.map((coupon) =>
            coupon.id === couponPendingRemoval.id && result.coupon
              ? result.coupon
              : coupon,
          ),
        );
        toast.success("تم إيقاف الكوبون مع الاحتفاظ بسجل الاستخدام");
      }

      setCouponPendingRemoval(null);
      await loadCoupons();
    } catch (error: any) {
      console.error("Failed to remove platform signup coupon", error);
      toast.error(
        error?.response?.data?.message ||
          error?.message ||
          "فشل حذف كوبون التسجيل",
      );
    } finally {
      setRemoving(false);
    }
  };

  return (
    <BusinessPageShell className="space-y-6">
      <BusinessPageHero
        eyebrow="Growth Controls"
        title="كوبونات التسجيل للمنصة"
        description="إدارة كوبونات onboarding التي تمنح trial إضافي أو limits استخدام أعلى للعملاء الجدد من شاشة التسجيل مباشرة."
        actions={
          <div className="flex flex-wrap items-center gap-3">
            <Button
              type="button"
              variant="outline"
              className="rounded-2xl"
              onClick={() => void loadCoupons()}
              disabled={loading}
            >
              <RefreshCw className={loading ? "animate-spin" : ""} />
              تحديث
            </Button>
            <Button type="button" className="rounded-2xl" onClick={openCreateDialog}>
              <Plus />
              إنشاء كوبون
            </Button>
          </div>
        }
      />

      <BusinessMetricsStrip items={metricItems} />

      <BusinessMobileSearchPanel
        searchId="signup-coupon-search-mobile"
        searchLabel="ابحث عن كوبون"
        searchPlaceholder="ابحث بالاسم أو الكود"
        searchValue={search}
        searchAriaLabel="ابحث عن كوبون تسجيل"
        onSearchChange={setSearch}
        onSearchSubmit={() => {
          void loadCoupons(search, stateFilter);
        }}
        onOpenFilters={() => setFilterSheetOpen(true)}
        filterCount={activeFilterLabels.length}
        summaryIcon={<Sparkles className="size-4" />}
        summary={`تعرض ${coupons.length.toLocaleString("ar-EG")} كوبون`}
        activeFilters={activeFilterLabels}
      />

      <BusinessFilterSheet
        open={filterSheetOpen}
        onOpenChange={setFilterSheetOpen}
        title="فلاتر كوبونات التسجيل"
        description="اختر الحالة التي تريد عرضها في شاشة الإدارة."
        onClear={() => {
          setStateFilter("all");
        }}
        onApply={() => {
          setFilterSheetOpen(false);
          void loadCoupons(search, stateFilter);
        }}
      >
        <div className="space-y-2">
          <Label>حالة الكوبون</Label>
          <Select
            value={stateFilter}
            onValueChange={(value) =>
              setStateFilter(value as CouponStateFilter)
            }
          >
            <SelectTrigger>
              <SelectValue placeholder="اختر الحالة" />
            </SelectTrigger>
            <SelectContent>
              {stateOptions.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </BusinessFilterSheet>

      <BusinessSectionPanel
        title="لوحة الكوبونات"
        description="بحث سريع، فلترة، ومراجعة آخر استرداد لكل كوبون قبل التعديل."
        headerAside={
          <div className="hidden flex-wrap items-center gap-3 md:flex">
            <div className="relative w-[18rem]">
              <Search className="pointer-events-none absolute right-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="ابحث بالاسم أو الكود"
                className="pr-10 text-right"
              />
            </div>

            <Select
              value={stateFilter}
              onValueChange={(value) =>
                setStateFilter(value as CouponStateFilter)
              }
            >
              <SelectTrigger className="w-[13rem]">
                <SelectValue placeholder="كل الحالات" />
              </SelectTrigger>
              <SelectContent>
                {stateOptions.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        }
        contentClassName="space-y-4 p-4 sm:p-6"
      >
        {loading ? (
          <div className="rounded-3xl border border-dashed border-border/70 bg-background/70 px-6 py-12 text-center text-sm text-muted-foreground">
            جاري تحميل كوبونات التسجيل...
          </div>
        ) : coupons.length === 0 ? (
          <div className="rounded-3xl border border-dashed border-border/70 bg-background/70 px-6 py-12 text-center">
            <div className="mx-auto flex max-w-xl flex-col items-center gap-3">
              <Badge variant="outline" className="rounded-full px-3 py-1">
                Empty State
              </Badge>
              <h3 className="text-xl font-semibold text-foreground">
                لا توجد كوبونات مطابقة الآن
              </h3>
              <p className="text-sm leading-7 text-muted-foreground">
                أنشئ أول كوبون onboarding ليحصل العميل الجديد على فترة مجانية
                إضافية أو limits استخدام أعلى منذ أول يوم.
              </p>
              <Button type="button" className="rounded-2xl" onClick={openCreateDialog}>
                <Plus />
                إنشاء أول كوبون
              </Button>
            </div>
          </div>
        ) : (
          <>
            <div className="grid gap-4 md:hidden">
              {coupons.map((coupon) => {
                const benefits = buildBenefitList(coupon);

                return (
                  <article
                    key={coupon.id}
                    className="rounded-[28px] border border-border/70 bg-card p-5 shadow-sm"
                  >
                    <div className="flex items-start justify-between gap-3">
                      <div className="space-y-2">
                        <div className="flex flex-wrap items-center gap-2">
                          <Badge
                            variant="outline"
                            className={`rounded-full px-3 py-1 ${stateBadgeClassName(coupon.state)}`}
                          >
                            {stateLabel(coupon.state)}
                          </Badge>
                          <Badge variant="secondary" className="rounded-full px-3 py-1">
                            {coupon.code}
                          </Badge>
                        </div>
                        <h3 className="text-lg font-semibold text-foreground">
                          {coupon.name}
                        </h3>
                        <p className="text-sm leading-7 text-muted-foreground">
                          {coupon.description || "بدون وصف إضافي."}
                        </p>
                      </div>

                      <div className="flex flex-col gap-2">
                        <Button
                          type="button"
                          variant="outline"
                          className="rounded-2xl"
                          aria-label={`تعديل الكوبون ${coupon.code}`}
                          onClick={() => openEditDialog(coupon)}
                        >
                          تعديل
                        </Button>
                        <Button
                          type="button"
                          variant="outline"
                          className="rounded-2xl border-rose-200 text-rose-700 hover:bg-rose-50 hover:text-rose-800"
                          aria-label={`حذف الكوبون ${coupon.code}`}
                          onClick={() => openRemoveDialog(coupon)}
                        >
                          <Trash2 className="size-4" />
                          حذف
                        </Button>
                      </div>
                    </div>

                    <div className="mt-4 flex flex-wrap gap-2">
                      {benefits.map((benefit) => (
                        <Badge key={benefit} variant="outline" className="rounded-full px-3 py-1">
                          {benefit}
                        </Badge>
                      ))}
                    </div>

                    <div className="mt-4 grid gap-3 rounded-3xl bg-background/80 p-4 text-sm">
                      <div className="flex items-center justify-between gap-3">
                        <span className="text-muted-foreground">الفترة</span>
                        <span className="font-medium text-foreground">
                          {formatDate(coupon.validFrom)} - {formatDate(coupon.validTo)}
                        </span>
                      </div>
                      <div className="flex items-center justify-between gap-3">
                        <span className="text-muted-foreground">الاستخدام</span>
                        <span className="font-medium text-foreground">
                          {coupon.usageCount.toLocaleString("ar-EG")}
                          {coupon.usageLimit
                            ? ` / ${coupon.usageLimit.toLocaleString("ar-EG")}`
                            : " / غير محدود"}
                        </span>
                      </div>
                      <div className="flex items-center justify-between gap-3">
                        <span className="text-muted-foreground">آخر استرداد</span>
                        <span className="font-medium text-foreground">
                          {coupon.lastRedemption?.companyName || "لا يوجد بعد"}
                        </span>
                      </div>
                    </div>
                  </article>
                );
              })}
            </div>

            <div className="hidden md:block">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="text-right">الكوبون</TableHead>
                    <TableHead className="text-right">المزايا</TableHead>
                    <TableHead className="text-right">الفترة</TableHead>
                    <TableHead className="text-right">الاستخدام</TableHead>
                    <TableHead className="text-right">آخر استرداد</TableHead>
                    <TableHead className="text-right">إجراء</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {coupons.map((coupon) => {
                    const benefits = buildBenefitList(coupon);

                    return (
                      <TableRow key={coupon.id}>
                        <TableCell className="align-top">
                          <div className="space-y-2">
                            <div className="flex flex-wrap items-center gap-2">
                              <span className="font-semibold text-foreground">
                                {coupon.name}
                              </span>
                              <Badge
                                variant="outline"
                                className={`rounded-full px-3 py-1 ${stateBadgeClassName(coupon.state)}`}
                              >
                                {stateLabel(coupon.state)}
                              </Badge>
                            </div>
                            <div className="text-sm text-muted-foreground">
                              <span dir="ltr">{coupon.code}</span>
                              {coupon.description ? ` • ${coupon.description}` : ""}
                            </div>
                          </div>
                        </TableCell>
                        <TableCell className="align-top">
                          <div className="flex flex-wrap gap-2">
                            {benefits.map((benefit) => (
                              <Badge
                                key={benefit}
                                variant="outline"
                                className="rounded-full px-3 py-1"
                              >
                                {benefit}
                              </Badge>
                            ))}
                          </div>
                        </TableCell>
                        <TableCell className="align-top text-sm text-muted-foreground">
                          <div>{formatDate(coupon.validFrom)}</div>
                          <div>{formatDate(coupon.validTo)}</div>
                        </TableCell>
                        <TableCell className="align-top text-sm text-foreground">
                          <div>
                            {coupon.usageCount.toLocaleString("ar-EG")}
                            {coupon.usageLimit
                              ? ` / ${coupon.usageLimit.toLocaleString("ar-EG")}`
                              : " / غير محدود"}
                          </div>
                          <div className="mt-1 text-muted-foreground">
                            {coupon.redemptionsCount.toLocaleString("ar-EG")} شركة
                          </div>
                        </TableCell>
                        <TableCell className="align-top text-sm text-muted-foreground">
                          {coupon.lastRedemption ? (
                            <>
                              <div className="text-foreground">
                                {coupon.lastRedemption.companyName || "شركة غير معروفة"}
                              </div>
                              <div>{formatDate(coupon.lastRedemption.redeemedAt)}</div>
                            </>
                          ) : (
                            "لا يوجد بعد"
                          )}
                        </TableCell>
                        <TableCell className="align-top">
                          <div className="flex flex-wrap items-center gap-2">
                            <Button
                              type="button"
                              variant="outline"
                              className="rounded-2xl"
                              aria-label={`تعديل الكوبون ${coupon.code}`}
                              onClick={() => openEditDialog(coupon)}
                            >
                              تعديل
                            </Button>
                            <Button
                              type="button"
                              variant="outline"
                              className="rounded-2xl border-rose-200 text-rose-700 hover:bg-rose-50 hover:text-rose-800"
                              aria-label={`حذف الكوبون ${coupon.code}`}
                              onClick={() => openRemoveDialog(coupon)}
                            >
                              <Trash2 className="size-4" />
                              حذف
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          </>
        )}
      </BusinessSectionPanel>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-3xl p-0">
          <DialogHeader className="border-b px-6 pt-6">
            <DialogTitle>
              {editingCoupon ? "تعديل كوبون التسجيل" : "إنشاء كوبون تسجيل جديد"}
            </DialogTitle>
            <DialogDescription>
              حدّد مزايا onboarding التي ستظهر مباشرة للعميل عند إدخال الكود في
              شاشة التسجيل.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-6 px-6 py-5">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="coupon-name">اسم الكوبون</Label>
                <Input
                  id="coupon-name"
                  value={formState.name}
                  onChange={(event) =>
                    setFormState((previous) => ({
                      ...previous,
                      name: event.target.value,
                    }))
                  }
                  placeholder="Welcome PRO Launch"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="coupon-code">كود الكوبون</Label>
                <Input
                  id="coupon-code"
                  dir="ltr"
                  value={formState.code}
                  onChange={(event) =>
                    setFormState((previous) => ({
                      ...previous,
                      code: event.target.value.toUpperCase(),
                    }))
                  }
                  placeholder="WELCOME14"
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="coupon-description">وصف مختصر</Label>
              <Textarea
                id="coupon-description"
                value={formState.description}
                onChange={(event) =>
                  setFormState((previous) => ({
                    ...previous,
                    description: event.target.value,
                  }))
                }
                placeholder="الكوبون يمنح 14 يومًا إضافية و200 طلب شهريًا."
              />
            </div>

            <div className="grid gap-4 md:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="coupon-valid-from">بداية الصلاحية</Label>
                <Input
                  id="coupon-valid-from"
                  type="datetime-local"
                  value={formState.validFrom}
                  onChange={(event) =>
                    setFormState((previous) => ({
                      ...previous,
                      validFrom: event.target.value,
                    }))
                  }
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="coupon-valid-to">نهاية الصلاحية</Label>
                <Input
                  id="coupon-valid-to"
                  type="datetime-local"
                  value={formState.validTo}
                  onChange={(event) =>
                    setFormState((previous) => ({
                      ...previous,
                      validTo: event.target.value,
                    }))
                  }
                />
              </div>
            </div>

            <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
              {numericBenefitFields.map((field) => (
                <div key={field.key} className="space-y-2">
                  <Label htmlFor={`benefit-${field.key}`}>{field.label}</Label>
                  <Input
                    id={`benefit-${field.key}`}
                    type="number"
                    min={0}
                    value={formState[field.key]}
                    onChange={(event) =>
                      updateBenefitField(field.key, event.target.value)
                    }
                    placeholder={field.placeholder}
                  />
                </div>
              ))}

              <div className="space-y-2">
                <Label htmlFor="coupon-usage-limit">حد الاستخدام</Label>
                <Input
                  id="coupon-usage-limit"
                  type="number"
                  min={1}
                  value={formState.usageLimit ?? ""}
                  onChange={(event) =>
                    setFormState((previous) => ({
                      ...previous,
                      usageLimit: event.target.value
                        ? Math.max(1, Number.parseInt(event.target.value, 10) || 1)
                        : null,
                    }))
                  }
                  placeholder="اتركه فارغًا لغير المحدود"
                />
              </div>
            </div>

            <div className="flex items-center justify-between rounded-3xl border border-border/70 bg-background/70 px-4 py-4">
              <div>
                <p className="font-medium text-foreground">تفعيل الكوبون</p>
                <p className="text-sm text-muted-foreground">
                  عند الإيقاف سيظل ظاهرًا في السوبر أدمن لكن لن يقبل في التسجيل.
                </p>
              </div>
              <Switch
                checked={formState.isActive}
                onCheckedChange={(checked) =>
                  setFormState((previous) => ({
                    ...previous,
                    isActive: Boolean(checked),
                  }))
                }
              />
            </div>
          </div>

          <DialogFooter className="px-6">
            <Button
              type="button"
              variant="outline"
              className="rounded-2xl"
              onClick={() => setDialogOpen(false)}
              disabled={saving}
            >
              إلغاء
            </Button>
            <Button
              type="button"
              className="rounded-2xl"
              onClick={() => void handleSaveCoupon()}
              disabled={saving}
            >
              {saving ? (
                <>
                  <RefreshCw className="animate-spin" />
                  جاري الحفظ...
                </>
              ) : editingCoupon ? (
                "حفظ التعديلات"
              ) : (
                "إنشاء الكوبون"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={Boolean(couponPendingRemoval)}
        onOpenChange={(open) => {
          if (!open && !removing) {
            setCouponPendingRemoval(null);
          }
        }}
      >
        <DialogContent className="max-w-md text-right sm:text-right">
          <DialogHeader className="text-right">
            <DialogTitle>
              حذف كوبون التسجيل؟
            </DialogTitle>
            <DialogDescription>
              {couponPendingRemoval?.redemptionsCount
                ? `الكوبون ${couponPendingRemoval.code} تم استخدامه من قبل، لذلك سيتم إيقافه بدلًا من حذف السجل بالكامل.`
                : `سيتم حذف الكوبون ${couponPendingRemoval?.code || ""} نهائيًا لأنه غير مستخدم بعد.`}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="sm:flex-row-reverse">
            <Button
              type="button"
              variant="outline"
              className="rounded-2xl"
              disabled={removing}
              onClick={() => setCouponPendingRemoval(null)}
            >
              إلغاء
            </Button>
            <Button
              type="button"
              className="rounded-2xl bg-rose-600 text-white hover:bg-rose-700"
              disabled={removing}
              onClick={() => void handleRemoveCoupon()}
            >
              {removing ? "جارٍ التنفيذ..." : "تأكيد الحذف"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </BusinessPageShell>
  );
};

