interface QueueMetric {
  id: string;
  completed: number;
  failed: number;
  timestamp: string;
}

interface MonitorData {
  success: boolean;
  stats: {
    webhookProcessing: QueueStats;
  };
  recentJobs: RecentJob[];
  timestamp: string;
}

export default function QueueMonitor() {
  const [filter, setFilter] = useState<
    "all" | "message" | "read" | "comment" | "failed"
  >("all");
  const [data, setData] = useState<MonitorData | null>(null);
  const [history, setHistory] = useState<QueueMetric[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [selectedJob, setSelectedJob] = useState<RecentJob | null>(null);
  const [timeRange, setTimeRange] = useState<"1" | "7">("1");

  const fetchData = async () => {
    try {
      setLoading(true);
      const [statsRes, historyRes] = await Promise.all([
        apiClient.get("/monitor-admin/queues", { params: { type: filter } }),
        apiClient.get("/monitor-admin/history", {
          params: { days: timeRange },
        }),
      ]);

      setData(statsRes.data);
      setHistory(historyRes.data.history || []);
      setError(null);
    } catch (err: any) {
      console.error("Fetch error:", err);
      setError(err.response?.data?.error || "فشل تحميل البيانات من الخادم");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [filter, timeRange]);

  useEffect(() => {
    if (!autoRefresh) return;
    const interval = setInterval(fetchData, 10000); // 10 seconds for real-time feel
    return () => clearInterval(interval);
  }, [autoRefresh, filter, timeRange]);

  const stats = data?.stats.webhookProcessing;
  const recentJobs = data?.recentJobs || [];

  const handleExport = () => {
    if (!recentJobs.length) return;
    exportToExcel(
      recentJobs,
      [
        { key: "id", label: "المعرف (ID)" },
        { key: "name", label: "النوع" },
        { key: "status", label: "الحالة" },
        { key: "finishedOn", label: "الوقت" },
        { key: "data", label: "البيانات" },
      ],
      `queue-jobs-${new Date().toISOString().split("T")[0]}.xlsx`,
    );
  };

  const formatChartData = (items: QueueMetric[]) => {
    return items.map((item) => ({
      ...item,
      time: new Date(item.timestamp).toLocaleTimeString("ar-EG", {
        hour: "2-digit",
        minute: "2-digit",
      }),
      date: new Date(item.timestamp).toLocaleDateString("ar-EG", {
        day: "2-digit",
        month: "2-digit",
      }),
    }));
  };

  return (
    <div className="p-6 space-y-6 bg-slate-50/50 min-h-screen" dir="rtl">
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col md:flex-row md:items-center justify-between gap-4"
      >
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight text-slate-900">
            مراقبة النظام
          </h1>
          <p className="text-slate-500 mt-1 flex items-center gap-2">
            <Activity className="w-4 h-4 text-primary animate-pulse" />
            إحصائيات الأداء في الوقت الفعلي والعمليات التاريخية
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex bg-white border rounded-lg p-1 shadow-sm">
            <Button
              variant={autoRefresh ? "default" : "ghost"}
              size="sm"
              onClick={() => setAutoRefresh(!autoRefresh)}
              className="text-xs h-8"
            >
              <Activity
                className={`w-3.5 h-3.5 ml-1.5 ${autoRefresh ? "animate-pulse" : ""}`}
              />
              {autoRefresh ? "تحديث تلقائي" : "تحديث يدوي"}
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={fetchData}
              disabled={loading}
              className="text-xs h-8"
            >
              <RefreshCw
                className={`w-3.5 h-3.5 ml-1.5 ${loading ? "animate-spin" : ""}`}
              />
              تحديث
            </Button>
            <div className="w-px h-4 bg-slate-200 self-center mx-1" />
            <Button
              variant="ghost"
              size="sm"
              onClick={handleExport}
              disabled={recentJobs.length === 0}
              className="text-xs h-8 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50"
            >
              <Download className="w-3.5 h-3.5 ml-1.5" />
              تصدير Excel
            </Button>
          </div>
        </div>
      </motion.div>

      {error && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
          <Card className="border-red-200 bg-red-50/50 backdrop-blur-sm">
            <CardContent className="pt-6 flex items-center gap-3 text-red-600">
              <XCircle className="w-5 h-5" />
              <p className="font-medium text-sm">{error}</p>
            </CardContent>
          </Card>
        </motion.div>
      )}

      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
          {[
            {
              label: "قيد المعالجة",
              value: stats.active,
              icon: Activity,
              color: "text-blue-500",
              bg: "bg-blue-50",
            },
            {
              label: "في الانتظار",
              value: stats.waiting,
              icon: Clock,
              color: "text-yellow-500",
              bg: "bg-yellow-50",
            },
            {
              label: "مكتملة",
              value: stats.completed,
              icon: CheckCircle2,
              color: "text-emerald-500",
              bg: "bg-emerald-50",
            },
            {
              label: "فاشلة",
              value: stats.failed,
              icon: XCircle,
              color: "text-rose-500",
              bg: "bg-rose-50",
            },
            {
              label: "مؤجلة",
              value: stats.delayed,
              icon: Clock,
              color: "text-orange-500",
              bg: "bg-orange-50",
            },
            {
              label: "متوقفة",
              value: stats.paused,
              icon: Pause,
              color: "text-slate-500",
              bg: "bg-slate-50",
            },
          ].map((item, idx) => (
            <motion.div
              key={item.label}
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ delay: idx * 0.05 }}
            >
              <Card className="overflow-hidden border-none shadow-sm hover:shadow-md transition-shadow">
                <CardHeader className="p-4 pb-2 space-y-0">
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-xs font-semibold text-slate-500">
                      {item.label}
                    </CardTitle>
                    <div className={`p-1.5 rounded-lg ${item.bg}`}>
                      <item.icon className={`w-4 h-4 ${item.color}`} />
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="p-4 pt-0">
                  <div className="text-2xl font-bold text-slate-900 tracking-tight">
                    {item.value.toLocaleString()}
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Historical Analytics Chart */}
        <Card className="lg:col-span-8 border-none shadow-sm overflow-hidden bg-white">
          <CardHeader className="flex flex-row items-center justify-between border-b bg-slate-50/50 px-6 py-4">
            <div className="flex items-center gap-2">
              <History className="w-5 h-5 text-primary" />
              <CardTitle className="text-lg font-bold">
                تحليلات الأداء
              </CardTitle>
            </div>
            <div className="flex bg-slate-200/50 p-1 rounded-lg">
              <Button
                variant={timeRange === "1" ? "secondary" : "ghost"}
                size="sm"
                onClick={() => setTimeRange("1")}
                className={`text-xs h-7 px-3 ${timeRange === "1" ? "bg-white shadow-sm" : ""}`}
              >
                ٢٤ ساعة
              </Button>
              <Button
                variant={timeRange === "7" ? "secondary" : "ghost"}
                size="sm"
                onClick={() => setTimeRange("7")}
                className={`text-xs h-7 px-3 ${timeRange === "7" ? "bg-white shadow-sm" : ""}`}
              >
                ٧ أيام
              </Button>
            </div>
          </CardHeader>
          <CardContent className="p-6">
            <div className="h-[350px] w-full">
              {history.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={formatChartData(history)}>
                    <defs>
                      <linearGradient
                        id="colorCompleted"
                        x1="0"
                        y1="0"
                        x2="0"
                        y2="1"
                      >
                        <stop
                          offset="5%"
                          stopColor="#10b981"
                          stopOpacity={0.2}
                        />
                        <stop
                          offset="95%"
                          stopColor="#10b981"
                          stopOpacity={0}
                        />
                      </linearGradient>
                      <linearGradient
                        id="colorFailed"
                        x1="0"
                        y1="0"
                        x2="0"
                        y2="1"
                      >
                        <stop
                          offset="5%"
                          stopColor="#ef4444"
                          stopOpacity={0.2}
                        />
                        <stop
                          offset="95%"
                          stopColor="#ef4444"
                          stopOpacity={0}
                        />
                      </linearGradient>
                    </defs>
                    <CartesianGrid
                      strokeDasharray="3 3"
                      vertical={false}
                      stroke="#f1f5f9"
                    />
                    <XAxis
                      dataKey={timeRange === "1" ? "time" : "date"}
                      axisLine={false}
                      tickLine={false}
                      tick={{ fontSize: 11, fill: "#64748b" }}
                      minTickGap={40}
                    />
                    <YAxis
                      axisLine={false}
                      tickLine={false}
                      tick={{ fontSize: 11, fill: "#64748b" }}
                    />
                    <Tooltip
                      contentStyle={{
                        backgroundColor: "rgba(255, 255, 255, 0.95)",
                        border: "1px solid #e2e8f0",
                        borderRadius: "12px",
                        boxShadow: "0 10px 15px -3px rgb(0 0 0 / 0.1)",
                        padding: "12px",
                      }}
                      labelStyle={{
                        fontWeight: "bold",
                        marginBottom: "8px",
                        color: "#1e293b",
                      }}
                    />
                    <Legend
                      align="right"
                      verticalAlign="top"
                      height={40}
                      iconType="circle"
                    />
                    <Area
                      type="monotone"
                      name="الناجحة"
                      dataKey="completed"
                      stroke="#10b981"
                      strokeWidth={3}
                      fillOpacity={1}
                      fill="url(#colorCompleted)"
                      animationDuration={1500}
                    />
                    <Area
                      type="monotone"
                      name="الفاشلة"
                      dataKey="failed"
                      stroke="#ef4444"
                      strokeWidth={3}
                      fillOpacity={1}
                      fill="url(#colorFailed)"
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-400 bg-slate-50/50 rounded-xl border-2 border-dashed border-slate-200">
                  <BarChart3 className="w-12 h-12 mb-4 opacity-10" />
                  <div className="text-center">
                    <p className="font-semibold text-slate-600">
                      جاري جمع البيانات التاريخية...
                    </p>
                    <p className="text-xs mt-1 text-slate-400">
                      ستظهر البيانات فور اكتمال أول عملية تسجيل آلي
                    </p>
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Recent Jobs List */}
        <Card className="lg:col-span-4 border-none shadow-sm overflow-hidden flex flex-col bg-white">
          <CardHeader className="border-b bg-slate-50/50 px-6 py-4">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg font-bold">
                العمليات الأخيرة
              </CardTitle>
              <span className="text-[10px] bg-primary/10 text-primary px-2 py-0.5 rounded-full font-bold uppercase tracking-wider">
                Live
              </span>
            </div>
            <div className="flex gap-1.5 mt-4 overflow-x-auto pb-1 no-scrollbar">
              {[
                { id: "all", label: "الكل" },
                { id: "message", label: "رسائل" },
                { id: "read", label: "قراءة" },
                { id: "comment", label: "تعليقات" },
                { id: "failed", label: "فاشلة" },
              ].map((item) => (
                <button
                  key={item.id}
                  onClick={() => setFilter(item.id as any)}
                  className={`px-3 py-1 rounded-full text-xs font-semibold whitespace-nowrap transition-all ${
                    filter === item.id
                      ? "bg-slate-900 text-white shadow-sm"
                      : "bg-white border text-slate-600 hover:border-slate-400"
                  }`}
                >
                  {item.label}
                </button>
              ))}
            </div>
          </CardHeader>
          <CardContent className="p-4 flex-1 overflow-auto max-h-[450px]">
            <AnimatePresence mode="popLayout">
              {recentJobs.length === 0 ? (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="flex flex-col items-center justify-center h-48 text-slate-400"
                >
                  <Info className="w-8 h-8 mb-2 opacity-10" />
                  <p className="text-sm">لا توجد عمليات حالياً</p>
                </motion.div>
              ) : (
                <div className="space-y-1.5">
                  {recentJobs.map((job) => (
                    <motion.div
                      key={job.id}
                      layout
                      initial={{ opacity: 0, x: 20 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, scale: 0.95 }}
                      onClick={() => setSelectedJob(job)}
                      className="group flex items-center justify-between p-3 rounded-xl border border-slate-100 hover:border-slate-200 hover:bg-slate-50/80 transition-all cursor-pointer"
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <div className="shrink-0 p-2.5 bg-slate-50 border border-slate-100 rounded-xl group-hover:bg-white transition-colors">
                          {job.name === "facebook-message" && (
                            <MessageSquare className="w-4 h-4 text-blue-500" />
                          )}
                          {job.name === "facebook-read-receipt" && (
                            <CheckCheck className="w-4 h-4 text-emerald-500" />
                          )}
                          {job.name === "facebook-comment" && (
                            <MessageCircle className="w-4 h-4 text-purple-500" />
                          )}
                          {![
                            "facebook-message",
                            "facebook-read-receipt",
                            "facebook-comment",
                          ].includes(job.name) && (
                            <Activity className="w-4 h-4 text-slate-400" />
                          )}
                        </div>

                        <div className="flex flex-col min-w-0">
                          <span className="text-sm font-bold text-slate-700 leading-tight">
                            {job.name.replace("facebook-", "")}
                          </span>
                          <span
                            className="text-[10px] text-slate-400 font-mono truncate max-w-[120px]"
                            title={job.data}
                          >
                            {job.data}
                          </span>
                        </div>
                      </div>

                      <div className="flex items-center gap-2.5">
                        <div className="flex flex-col items-end">
                          {job.finishedOn && (
                            <span className="text-[10px] text-slate-400 font-medium">
                              {new Date(job.finishedOn).toLocaleTimeString(
                                "ar-EG",
                                { hour: "2-digit", minute: "2-digit" },
                              )}
                            </span>
                          )}
                          <div
                            className={`mt-0.5 h-1.5 w-1.5 rounded-full ${
                              job.status === "completed"
                                ? "bg-emerald-500"
                                : job.status === "active"
                                  ? "bg-blue-500 animate-pulse"
                                  : job.status === "waiting"
                                    ? "bg-amber-500 animate-bounce"
                                    : "bg-rose-500"
                            }`}
                          />
                        </div>
                        <ChevronRight className="w-4 h-4 text-slate-300 group-hover:text-slate-400 transition-colors" />
                      </div>
                    </motion.div>
                  ))}
                </div>
              )}
            </AnimatePresence>
          </CardContent>
        </Card>
      </div>

      {data?.timestamp && (
        <div className="flex items-center justify-center gap-2 py-4">
          <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
          <p className="text-xs text-slate-400 font-medium tracking-wide">
            آخر تحديث للبيانات:{" "}
            {new Date(data.timestamp).toLocaleString("ar-EG")}
          </p>
        </div>
      )}

      {/* Job Details Modal */}
      <AnimatePresence>
        {selectedJob && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm"
              onClick={() => setSelectedJob(null)}
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="relative bg-white border rounded-2xl max-w-lg w-full overflow-hidden shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="border-b bg-slate-50/50 p-6">
                <div className="flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-white rounded-lg border shadow-sm">
                      <Info className="w-5 h-5 text-primary" />
                    </div>
                    <h3 className="text-xl font-bold text-slate-800">
                      تفاصيل المهمة
                    </h3>
                  </div>
                  <button
                    onClick={() => setSelectedJob(null)}
                    className="p-2 hover:bg-slate-200 rounded-full transition-colors"
                  >
                    <XCircle className="w-6 h-6 text-slate-400" />
                  </button>
                </div>
              </div>

              <div className="p-6 space-y-6 overflow-y-auto max-h-[70vh]">
                <div className="grid grid-cols-2 gap-6 bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">
                      المعرف (Job ID)
                    </p>
                    <p className="text-sm font-mono text-slate-700 bg-white p-2 rounded border">
                      {selectedJob.id}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">
                      النوع
                    </p>
                    <p className="text-sm font-bold text-slate-700 bg-white p-2 rounded border">
                      {selectedJob.name}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">
                      الحالة
                    </p>
                    <span
                      className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold leading-5 ${
                        selectedJob.status === "completed"
                          ? "bg-emerald-100 text-emerald-800"
                          : selectedJob.status === "active"
                            ? "bg-blue-100 text-blue-800"
                            : selectedJob.status === "waiting"
                              ? "bg-amber-100 text-amber-800"
                              : "bg-rose-100 text-rose-800"
                      }`}
                    >
                      {selectedJob.status === "completed"
                        ? "ناجحة"
                        : selectedJob.status === "active"
                          ? "قيد التنفيذ"
                          : selectedJob.status === "waiting"
                            ? "في الانتظار"
                            : "فاشلة"}
                    </span>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">
                      الوقت
                    </p>
                    <p className="text-sm font-medium text-slate-600">
                      {selectedJob.finishedOn
                        ? new Date(selectedJob.finishedOn).toLocaleString(
                            "ar-EG",
                          )
                        : "N/A"}
                    </p>
                  </div>
                </div>

                <div className="space-y-2">
                  <p className="text-sm font-bold text-slate-800">
                    حزمة البيانات (Payload):
                  </p>
                  <div
                    className="bg-slate-900 text-blue-100 p-4 rounded-xl text-[11px] font-mono overflow-auto max-h-[200px]"
                    dir="ltr"
                  >
                    <pre>
                      {JSON.stringify(selectedJob.rawPayload || {}, null, 2)}
                    </pre>
                  </div>
                </div>

                {selectedJob.failedReason && (
                  <div className="space-y-2">
                    <p className="text-sm font-bold text-rose-600">
                      سبب الفشل:
                    </p>
                    <div className="bg-rose-50 text-rose-700 p-4 rounded-xl text-xs font-medium border border-rose-100">
                      {selectedJob.failedReason}
                    </div>
                  </div>
                )}
              </div>

              <div className="p-6 pt-0">
                <Button
                  className="w-full h-11 rounded-xl font-bold"
                  onClick={() => setSelectedJob(null)}
                >
                  إغلاق النافذة
                </Button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  Button,
  Tabs,
  Tab,
  CircularProgress,
  Alert,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import {
  Refresh,
  Delete,
  Speed,
  Storage,
  Analytics,
  Security,
  CheckCircle,
  Error as ErrorIcon,
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";

interface CacheStats {
  faqs: { size: number; hits: number; misses: number };
  policies: { size: number; hits: number; misses: number };
  products: { size: number; hits: number; misses: number };
  search: { size: number; hits: number; misses: number };
}

interface SystemHealth {
  status: string;
  cache: { enabled: boolean; stats: CacheStats };
  analytics: { enabled: boolean; recordsCount: number };
  rateLimiter: { enabled: boolean; activeCompanies: number };
  dataLoader: { enabled: boolean; lastReload: string };
}

const RAGManagement: React.FC = () => {
  const [tabValue, setTabValue] = useState(0);
  const [loading, setLoading] = useState(false);
  const [cacheStats, setCacheStats] = useState<CacheStats | null>(null);
  const [systemHealth, setSystemHealth] = useState<SystemHealth | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean;
    action: string;
    title: string;
  }>({ open: false, action: "", title: "" });
  const [settings, setSettings] = useState<any>(null);
  const [analyticsData, setAnalyticsData] = useState<any>(null);
  const [performanceData, setPerformanceData] = useState<any>(null);

  useEffect(() => {
    loadData();
  }, [tabValue]);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      if (tabValue === 0) {
        const [healthRes, cacheRes] = await Promise.all([
          apiClient.get("/rag-admin/health"),
          apiClient.get("/rag-admin/cache/stats"),
        ]);
        setSystemHealth(healthRes.data);
        setCacheStats(cacheRes.data);
      } else if (tabValue === 1) {
        const analyticsRes = await apiClient.get("/rag-admin/analytics/search");
        setAnalyticsData(analyticsRes.data.data);
      } else if (tabValue === 2) {
        const performanceRes = await apiClient.get(
          "/rag-admin/analytics/performance",
        );
        setPerformanceData(performanceRes.data.data);
      } else if (tabValue === 3) {
        const settingsRes = await apiClient.get("/rag-admin/settings");
        setSettings(settingsRes.data.data);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحميل البيانات");
    } finally {
      setLoading(false);
    }
  };

  const handleInvalidateCache = async (type?: string) => {
    try {
      await apiClient.post("/rag-admin/cache/invalidate", { type });
      setSuccess(
        `تم إلغاء الذاكرة المؤقتة ${type ? `(${type})` : "بالكامل"} بنجاح`,
      );
      loadData();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل إلغاء الذاكرة المؤقتة");
    }
    setConfirmDialog({ open: false, action: "", title: "" });
  };

  const handleReloadData = async (type: "faqs" | "policies") => {
    try {
      await apiClient.post(`/rag-admin/reload/${type}`);
      setSuccess(
        `تم إعادة تحميل ${type === "faqs" ? "الأسئلة الشائعة" : "السياسات"} بنجاح`,
      );
      loadData();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل إعادة التحميل");
    }
    setConfirmDialog({ open: false, action: "", title: "" });
  };

  const handleUpdateSettings = async (newSettings: any) => {
    try {
      await apiClient.post("/rag-admin/settings/update", newSettings);
      setSuccess("تم تحديث الإعدادات بنجاح");
      loadData();
    } catch (err: any) {
      setError(err.response?.data?.error || "فشل تحديث الإعدادات");
    }
  };

  const renderCacheCard = (title: string, stats: any, type: string) => {
    if (!stats) stats = { size: 0, hits: 0, misses: 0 };
    const hits = stats.hits || 0;
    const misses = stats.misses || 0;
    const size = stats.size || 0;
    const hitRate =
      hits + misses > 0 ? ((hits / (hits + misses)) * 100).toFixed(1) : "0";

    return (
      <Card sx={{ height: "100%" }}>
        <CardContent>
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            mb={2}
          >
            <Typography variant="h6">{title}</Typography>
            <IconButton
              size="small"
              onClick={() =>
                setConfirmDialog({
                  open: true,
                  action: `invalidate-${type}`,
                  title: `إلغاء ذاكرة ${title}`,
                })
              }
            >
              <Delete />
            </IconButton>
          </Box>
          <Grid container spacing={2}>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                الحجم
              </Typography>
              <Typography variant="h6">{size}</Typography>
            </Grid>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                معدل النجاح
              </Typography>
              <Typography variant="h6" color="primary">
                {hitRate}%
              </Typography>
            </Grid>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                Hits
              </Typography>
              <Typography variant="body1">{hits}</Typography>
            </Grid>
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary">
                Misses
              </Typography>
              <Typography variant="body1">{misses}</Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    );
  };

  const limits = settings?.limits || {};
  const cacheConfig = settings?.cache || {};

  const renderSettingsTab = () => (
    <Box>
      <Typography variant="h5" mb={3}>
        إعدادات النظام
      </Typography>
      {settings && (
        <Grid container spacing={3}>
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  حدود الطلبات (Rate Limits)
                </Typography>
                <Box mb={3}>
                  <Typography variant="subtitle2" color="text.secondary">
                    لكل شركة (في الدقيقة)
                  </Typography>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={8}>
                      <Typography variant="body1">
                        الحد الأقصى: {limits.perCompany?.maxRequests}
                      </Typography>
                    </Grid>
                    <Grid item xs={4}>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => {
                          const val = prompt(
                            "أدخل الحد الجديد لكل شركة:",
                            limits.perCompany?.maxRequests?.toString(),
                          );
                          if (val)
                            handleUpdateSettings({
                              limits: {
                                ...limits,
                                perCompany: {
                                  ...limits.perCompany,
                                  maxRequests: parseInt(val),
                                },
                              },
                            });
                        }}
                      >
                        تعديل
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
                <Box>
                  <Typography variant="subtitle2" color="text.secondary">
                    لكل عنوان IP (في الدقيقة)
                  </Typography>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={8}>
                      <Typography variant="body1">
                        الحد الأقصى: {limits.perIP?.maxRequests}
                      </Typography>
                    </Grid>
                    <Grid item xs={4}>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => {
                          const val = prompt(
                            "أدخل الحد الجديد لكل IP:",
                            limits.perIP?.maxRequests?.toString(),
                          );
                          if (val)
                            handleUpdateSettings({
                              limits: {
                                ...limits,
                                perIP: {
                                  ...limits.perIP,
                                  maxRequests: parseInt(val),
                                },
                              },
                            });
                        }}
                      >
                        تعديل
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  ميزانية الـ Tokens اليومية
                </Typography>
                <Box mb={3}>
                  <Typography variant="subtitle2" color="text.secondary">
                    الحد الأقصى للشركة يومياً
                  </Typography>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={8}>
                      <Typography variant="body1">
                        {limits.dailyTokens?.maxTokens?.toLocaleString()} Token
                      </Typography>
                    </Grid>
                    <Grid item xs={4}>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => {
                          const val = prompt(
                            "أدخل حد الـ Tokens الجديد:",
                            limits.dailyTokens?.maxTokens?.toString(),
                          );
                          if (val)
                            handleUpdateSettings({
                              limits: {
                                ...limits,
                                dailyTokens: { maxTokens: parseInt(val) },
                              },
                            });
                        }}
                      >
                        تعديل
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  إعدادات الذاكرة المؤقتة (Smart Cache)
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  التحكم في مدة بقاء البيانات في الذاكرة (بالدقائق). زيادة المدة
                  تحسن الأداء ولكن قد تؤخر التحديثات.
                </Typography>
                <Grid container spacing={3}>
                  <Grid item xs={12} md={4}>
                    <Box mb={1}>
                      <Typography variant="subtitle2">
                        ذاكرة البحث (Search TTL)
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        المقترحات والنتائج المكررة
                      </Typography>
                    </Box>
                    <Grid container spacing={2} alignItems="center">
                      <Grid item xs={6}>
                        <Typography variant="h6">
                          {(cacheConfig.ttl?.search / 60000).toFixed(0)} دقيقة
                        </Typography>
                      </Grid>
                      <Grid item xs={6}>
                        <Button
                          size="small"
                          variant="outlined"
                          fullWidth
                          onClick={() => {
                            const val = prompt(
                              "أدخل مدة الحفظ بالدقائق:",
                              (cacheConfig.ttl?.search / 60000).toString(),
                            );
                            if (val)
                              handleUpdateSettings({
                                cache: {
                                  ...cacheConfig,
                                  ttl: {
                                    ...cacheConfig.ttl,
                                    search: parseInt(val) * 60000,
                                  },
                                },
                              });
                          }}
                        >
                          تعديل
                        </Button>
                      </Grid>
                    </Grid>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <Box mb={1}>
                      <Typography variant="subtitle2">
                        ذاكرة المنتجات (Product TTL)
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        تفاصيل المنتجات والأسعار
                      </Typography>
                    </Box>
                    <Grid container spacing={2} alignItems="center">
                      <Grid item xs={6}>
                        <Typography variant="h6">
                          {(cacheConfig.ttl?.product / 60000).toFixed(0)} دقيقة
                        </Typography>
                      </Grid>
                      <Grid item xs={6}>
                        <Button
                          size="small"
                          variant="outlined"
                          fullWidth
                          onClick={() => {
                            const val = prompt(
                              "أدخل مدة الحفظ بالدقائق:",
                              (cacheConfig.ttl?.product / 60000).toString(),
                            );
                            if (val)
                              handleUpdateSettings({
                                cache: {
                                  ...cacheConfig,
                                  ttl: {
                                    ...cacheConfig.ttl,
                                    product: parseInt(val) * 60000,
                                  },
                                },
                              });
                          }}
                        >
                          تعديل
                        </Button>
                      </Grid>
                    </Grid>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <Box mb={1}>
                      <Typography variant="subtitle2">
                        الأسئلة والسياسات
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        المعلومات الثابتة
                      </Typography>
                    </Box>
                    <Grid container spacing={2} alignItems="center">
                      <Grid item xs={6}>
                        <Typography variant="h6">
                          {(cacheConfig.ttl?.faq / 60000).toFixed(0)} دقيقة
                        </Typography>
                      </Grid>
                      <Grid item xs={6}>
                        <Button
                          size="small"
                          variant="outlined"
                          fullWidth
                          onClick={() => {
                            const val = prompt(
                              "أدخل مدة الحفظ بالدقائق:",
                              (cacheConfig.ttl?.faq / 60000).toString(),
                            );
                            if (val)
                              handleUpdateSettings({
                                cache: {
                                  ...cacheConfig,
                                  ttl: {
                                    ...cacheConfig.ttl,
                                    faq: parseInt(val) * 60000,
                                    policy: parseInt(val) * 60000,
                                  },
                                },
                              });
                          }}
                        >
                          تعديل
                        </Button>
                      </Grid>
                    </Grid>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}
    </Box>
  );

  const renderAnalyticsTab = () => (
    <Box>
      <Typography variant="h5" mb={3}>
        تحليلات البحث
      </Typography>
      {analyticsData && (
        <Grid container spacing={3}>
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  إحصائيات النتائج
                </Typography>
                <TableContainer>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell align="right">النية (Intent)</TableCell>
                        <TableCell align="center">العدد</TableCell>
                        <TableCell align="center">الحالة</TableCell>
                        <TableCell align="center">متوسط السرعة</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {analyticsData.stats.map((stat: any, idx: number) => (
                        <TableRow key={idx}>
                          <TableCell align="right">{stat.intent}</TableCell>
                          <TableCell align="center">{stat._count}</TableCell>
                          <TableCell align="center">
                            {stat.wasSuccessful ? "✅" : "❌"}
                          </TableCell>
                          <TableCell align="center">
                            {stat._avg.responseTime.toFixed(0)} ms
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2} color="error">
                  أبحاث فاشلة حديثاً
                </Typography>
                {analyticsData.failedSearches.map((item: any, idx: number) => (
                  <Box
                    key={idx}
                    mb={1}
                    p={1}
                    bgcolor="error.light"
                    borderRadius={1}
                  >
                    <Typography variant="body2" color="white">
                      {item.query}
                    </Typography>
                    <Typography
                      variant="caption"
                      color="white"
                      sx={{ opacity: 0.8 }}
                    >
                      {new Date(item.createdAt).toLocaleTimeString()}
                    </Typography>
                  </Box>
                ))}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}
    </Box>
  );

  const renderPerformanceTab = () => (
    <Box>
      <Typography variant="h5" mb={3}>
        أداء النظام وتكاليف الـ AI
      </Typography>
      {performanceData && (
        <Grid container spacing={3}>
          {performanceData.stats.map((op: any, idx: number) => (
            <Grid item xs={12} md={4} key={idx}>
              <Card>
                <CardContent>
                  <Typography variant="h6" color="primary">
                    {op.operation}
                  </Typography>
                  <Box mt={2}>
                    <Typography variant="body2" color="text.secondary">
                      عدد العمليات: {op._count}
                    </Typography>
                    <Typography variant="body1">
                      متوسط الـ Tokens: {op._avg.tokensUsed?.toFixed(0) || 0}
                    </Typography>
                    <Typography variant="body1">
                      إجمالي الـ Tokens:{" "}
                      {op._sum.tokensUsed?.toLocaleString() || 0}
                    </Typography>
                    <Typography variant="body2" mt={1}>
                      متوسط الاستجابة: {op._avg.responseTime.toFixed(0)} ms
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}
    </Box>
  );

  const renderOverviewTab = () => (
    <Box>
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}
      {success && (
        <Alert
          severity="success"
          sx={{ mb: 2 }}
          onClose={() => setSuccess(null)}
        >
          {success}
        </Alert>
      )}
      {systemHealth && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Box display="flex" alignItems="center" mb={2}>
              <Typography variant="h5" sx={{ flexGrow: 1 }}>
                حالة النظام
              </Typography>
              <Chip
                icon={
                  systemHealth.status === "healthy" ? (
                    <CheckCircle />
                  ) : (
                    <ErrorIcon />
                  )
                }
                label={
                  systemHealth.status === "healthy"
                    ? "يعمل بشكل جيد"
                    : "يوجد مشاكل"
                }
                color={systemHealth.status === "healthy" ? "success" : "error"}
              />
            </Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Storage sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Cache
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.cache?.enabled ? "مفعّل" : "معطّل"}
                    </Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Analytics sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Analytics
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.analytics?.recordsCount || 0} سجل
                    </Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Security sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Rate Limiter
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.rateLimiter?.activeCompanies || 0} شركة
                    </Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} md={3}>
                <Box display="flex" alignItems="center">
                  <Speed sx={{ mr: 1, color: "primary.main" }} />
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      آخر تحديث
                    </Typography>
                    <Typography variant="body1">
                      {systemHealth.dataLoader?.lastReload
                        ? new Date(
                            systemHealth.dataLoader.lastReload,
                          ).toLocaleTimeString("ar-EG")
                        : "N/A"}
                    </Typography>
                  </Box>
                </Box>
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      )}

      {cacheStats && (
        <>
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            mb={2}
          >
            <Typography variant="h5">إحصائيات الذاكرة المؤقتة</Typography>
            <Box>
              <Button
                variant="outlined"
                startIcon={<Refresh />}
                onClick={loadData}
                sx={{ mr: 1 }}
              >
                تحديث
              </Button>
              <Button
                variant="contained"
                color="error"
                startIcon={<Delete />}
                onClick={() =>
                  setConfirmDialog({
                    open: true,
                    action: "invalidate-all",
                    title: "إلغاء جميع الذاكرة المؤقتة",
                  })
                }
              >
                إلغاء الكل
              </Button>
            </Box>
          </Box>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("الأسئلة الشائعة", cacheStats.faqs, "faqs")}
            </Grid>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("السياسات", cacheStats.policies, "policies")}
            </Grid>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("المنتجات", cacheStats.products, "products")}
            </Grid>
            <Grid item xs={12} md={6} lg={3}>
              {renderCacheCard("البحث", cacheStats.search, "search")}
            </Grid>
          </Grid>

          <Box mt={4}>
            <Typography variant="h5" mb={2}>
              إعادة تحميل البيانات
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" mb={2}>
                      الأسئلة الشائعة
                    </Typography>
                    <Button
                      variant="contained"
                      startIcon={<Refresh />}
                      onClick={() =>
                        setConfirmDialog({
                          open: true,
                          action: "reload-faqs",
                          title: "إعادة تحميل الأسئلة الشائعة",
                        })
                      }
                      fullWidth
                    >
                      إعادة تحميل من قاعدة البيانات
                    </Button>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" mb={2}>
                      السياسات
                    </Typography>
                    <Button
                      variant="contained"
                      startIcon={<Refresh />}
                      onClick={() =>
                        setConfirmDialog({
                          open: true,
                          action: "reload-policies",
                          title: "إعادة تحميل السياسات",
                        })
                      }
                      fullWidth
                    >
                      إعادة تحميل من قاعدة البيانات
                    </Button>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          </Box>
        </>
      )}
    </Box>
  );

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" mb={3}>
        إدارة نظام RAG
      </Typography>
      <Tabs value={tabValue} onChange={(_, v) => setTabValue(v)} sx={{ mb: 3 }}>
        <Tab label="نظرة عامة" />
        <Tab label="التحليلات" />
        <Tab label="الأداء" />
        <Tab label="الإعدادات" />
      </Tabs>
      {loading ? (
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          {tabValue === 0 && renderOverviewTab()}
          {tabValue === 1 && renderAnalyticsTab()}
          {tabValue === 2 && renderPerformanceTab()}
          {tabValue === 3 && renderSettingsTab()}
        </>
      )}
      <Dialog
        open={confirmDialog.open}
        onClose={() => setConfirmDialog({ open: false, action: "", title: "" })}
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>
        <DialogContent>
          <Typography>هل أنت متأكد من هذا الإجراء؟</Typography>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() =>
              setConfirmDialog({ open: false, action: "", title: "" })
            }
          >
            إلغاء
          </Button>
          <Button
            variant="contained"
            color="primary"
            onClick={() => {
              if (confirmDialog.action === "invalidate-all")
                handleInvalidateCache();
              else if (confirmDialog.action.startsWith("invalidate-"))
                handleInvalidateCache(
                  confirmDialog.action.replace("invalidate-", ""),
                );
              else if (confirmDialog.action === "reload-faqs")
                handleReloadData("faqs");
              else if (confirmDialog.action === "reload-policies")
                handleReloadData("policies");
            }}
          >
            تأكيد
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default RAGManagement;

import React, { useState, useEffect, useMemo } from "react";
import {
  Box,
  Typography,
  Tabs,
  Tab,
  Paper,
  CircularProgress,
  Alert,
  Grid,
  Card,
  CardContent,
  Button,
  Chip,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Switch,
  FormControlLabel,
  List,
  ListItem,
  ListItemText,
  Divider,
  Tooltip,
  Collapse,
} from "@mui/material";
import {
  Star as StarIcon,
  ShoppingBag as MarketplaceIcon,
  Storefront as StorefrontIcon,
  Inventory as BundleIcon,
  CorporateFare as EnterpriseIcon,
  Add as AddIcon,
  Edit as EditIcon,
  TrendingUp as TrendingUpIcon,
  Check as CheckIcon,
  Close as CloseIcon,
  Delete as DeleteIcon,
  Save as SaveIcon,
  FileDownload as DownloadIcon,
  FileUpload as UploadIcon,
  Refresh as RefreshIcon,
} from "@mui/icons-material";
import { buildApiUrl } from "../../utils/urlHelper";
import axios from "axios";
import { toast } from "react-hot-toast";
import type { StorefrontThemeCatalogItem } from "../../services/storefrontThemeCatalogService";
import tokenManager from "../../utils/tokenManager";

type SubscriptionCenterProps = {
  initialTab?: number;
  storefrontThemesOnly?: boolean;
  pageTitle?: string;
  pageDescription?: string;
};

const getAccessToken = (): string | null => tokenManager.getAccessToken();
const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
  tokenManager.createAuthHeaders(additionalHeaders);

const SubscriptionCenter: React.FC<SubscriptionCenterProps> = ({
  initialTab = 0,
  storefrontThemesOnly = false,
  pageTitle = "مركز إدارة الاشتراكات والفوترة",
  pageDescription = "إدارة الخطط الأساسية، تطبيقات المتجر، والعروض المخصصة للمؤسسات",
}) => {
  const [activeTab, setActiveTab] = useState(initialTab);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Platform Plans State
  const [plans, setPlans] = useState([]);
  const [planDialog, setPlanDialog] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<any>(null);

  // Marketplace State
  const [apps, setApps] = useState([]);
  const [pricingRules, setPricingRules] = useState([]);
  const [bundles, setBundles] = useState([]);
  const [enterprisePlans, setEnterprisePlans] = useState([]);
  const [storefrontThemes, setStorefrontThemes] = useState<
    StorefrontThemeCatalogItem[]
  >([]);
  const [catalogDiff, setCatalogDiff] = useState<any>(null);
  const [catalogDiffLoading, setCatalogDiffLoading] = useState(false);
  const [catalogDiffError, setCatalogDiffError] = useState<string | null>(null);
  const [marketplaceDialog, setMarketplaceDialog] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);

  const fetchCatalogDiff = async ({ showToast = false } = {}) => {
    setCatalogDiffLoading(true);
    try {
      const headers = getAuthHeaders();
      const response = await axios.get(
        buildApiUrl("super-admin/marketplace-management/catalog/diff"),
        { headers },
      );

      if (response.data?.success) {
        setCatalogDiff(response.data.data);
        setCatalogDiffError(null);
        if (showToast) {
          toast.success("تم تحديث تقرير الفرق بين الملفات وقاعدة البيانات");
        }
      } else {
        setCatalogDiff(null);
        setCatalogDiffError("فشل في جلب تقرير الفرق");
        if (showToast) {
          toast.error("فشل في جلب تقرير الفرق");
        }
      }
    } catch (err: any) {
      console.error("Catalog diff fetch error:", err);
      setCatalogDiff(null);
      setCatalogDiffError(
        err?.response?.data?.message || "تعذر جلب تقرير الفرق",
      );
      if (showToast) {
        toast.error("تعذر جلب تقرير الفرق");
      }
    } finally {
      setCatalogDiffLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا العنصر؟")) return;
    try {
      const headers = getAuthHeaders();
      const typePath =
        activeTab === 1
          ? "apps"
          : editingItem?.feature
            ? "pricing-rules"
            : "bundles";

      await axios.delete(
        buildApiUrl(`super-admin/marketplace-management/${typePath}/${id}`),
        { headers },
      );
      toast.success("تم الحذف بنجاح");
      fetchAllData();
    } catch (err) {
      console.error("Delete error:", err);
      toast.error("خطأ في الحذف");
    }
  };

  useEffect(() => {
    fetchAllData();
  }, []);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab]);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const headers = getAuthHeaders();

      if (storefrontThemesOnly) {
        const themesRes = await axios.get(
          buildApiUrl("super-admin/storefront-theme-catalog"),
          { headers },
        );

        if (themesRes.data?.success) {
          setStorefrontThemes(themesRes.data.data);
          setError(null);
        } else {
          setStorefrontThemes([]);
          setError("فشل في جلب كتالوج قوالب المتجر");
        }

        return;
      }

      const [
        plansRes,
        appsRes,
        pricingRes,
        bundlesRes,
        enterpriseRes,
        themesRes,
      ] = await Promise.allSettled([
        axios.get(buildApiUrl("admin/plans/plans"), { headers }),
        axios.get(buildApiUrl("super-admin/marketplace-management/apps"), {
          headers,
        }),
        axios.get(
          buildApiUrl("super-admin/marketplace-management/pricing-rules"),
          { headers },
        ),
        axios.get(buildApiUrl("super-admin/marketplace-management/bundles"), {
          headers,
        }),
        axios.get(
          buildApiUrl("super-admin/marketplace-management/enterprise-plans"),
          { headers },
        ),
        axios.get(buildApiUrl("super-admin/storefront-theme-catalog"), {
          headers,
        }),
      ]);

      if (plansRes.status === "fulfilled" && plansRes.value.data.success) {
        setPlans(plansRes.value.data.data);
      }
      if (appsRes.status === "fulfilled" && appsRes.value.data.success) {
        setApps(appsRes.value.data.data);
      }
      if (pricingRes.status === "fulfilled" && pricingRes.value.data.success) {
        setPricingRules(pricingRes.value.data.data);
      }
      if (bundlesRes.status === "fulfilled" && bundlesRes.value.data.success) {
        setBundles(bundlesRes.value.data.data);
      }
      if (
        enterpriseRes.status === "fulfilled" &&
        enterpriseRes.value.data.success
      ) {
        setEnterprisePlans(enterpriseRes.value.data.data);
      }
      if (themesRes.status === "fulfilled" && themesRes.value.data.success) {
        setStorefrontThemes(themesRes.value.data.data);
      }

      const allFailed = [
        plansRes,
        appsRes,
        pricingRes,
        bundlesRes,
        enterpriseRes,
        themesRes,
      ].every((result) => result.status === "rejected");

      setError(allFailed ? "فشل في جلب البيانات الموحدة للاشتراكات" : null);

      // Catalog diff is operational telemetry; keep it separate from base data.
      fetchCatalogDiff();
    } catch (err) {
      console.error("Error fetching data:", err);
      setError(
        storefrontThemesOnly
          ? "فشل في جلب كتالوج قوالب المتجر"
          : "فشل في جلب البيانات الموحدة للاشتراكات",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  if (loading)
    return (
      <Box display="flex" justifyContent="center" p={10}>
        <CircularProgress />
      </Box>
    );

  return (
    <Box p={3}>
      <Box mb={4}>
        <Typography variant="h4" fontWeight="bold" gutterBottom>
          {pageTitle}
        </Typography>
        <Typography variant="body1" color="text.secondary">
          {pageDescription}
        </Typography>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      )}

      {!storefrontThemesOnly ? (
        <Paper sx={{ mb: 3 }}>
          <Tabs
            value={activeTab}
            onChange={handleTabChange}
            indicatorColor="primary"
            textColor="primary"
            variant="scrollable"
            scrollButtons="auto"
          >
            <Tab icon={<StarIcon />} iconPosition="start" label="خطط المنصة" />
            <Tab
              icon={<MarketplaceIcon />}
              iconPosition="start"
              label="تطبيقات المتجر"
            />
            <Tab
              icon={<BundleIcon />}
              iconPosition="start"
              label="الباقات والأسعار"
            />
            <Tab
              icon={<EnterpriseIcon />}
              iconPosition="start"
              label="تعاقدات المؤسسات"
            />
            <Tab
              icon={<StorefrontIcon />}
              iconPosition="start"
              label="قوالب المتجر"
            />
          </Tabs>
        </Paper>
      ) : null}

      {!storefrontThemesOnly && activeTab === 0 && (
        <PlatformPlansTab
          plans={plans}
          onEdit={(p) => {
            setSelectedPlan(p);
            setPlanDialog(true);
          }}
          onRefresh={fetchAllData}
        />
      )}
      {!storefrontThemesOnly && activeTab === 1 && (
        <MarketplaceAppsTab
          apps={apps}
          catalogDiff={catalogDiff}
          catalogDiffLoading={catalogDiffLoading}
          catalogDiffError={catalogDiffError}
          onEdit={(app: any) => {
            setEditingItem(app);
            setMarketplaceDialog(true);
          }}
          onDelete={handleDelete}
          onRefresh={fetchAllData}
          onRefreshCatalogDiff={() => fetchCatalogDiff({ showToast: true })}
        />
      )}
      {!storefrontThemesOnly && activeTab === 2 && (
        <BundlesAndPricingTab
          pricingRules={pricingRules}
          bundles={bundles}
          onEdit={(item: any) => {
            setEditingItem(item);
            setMarketplaceDialog(true);
          }}
          onDelete={handleDelete}
          onRefresh={fetchAllData}
        />
      )}
      {!storefrontThemesOnly && activeTab === 3 && (
        <EnterprisePlansTab
          enterprisePlans={enterprisePlans}
          onEdit={(plan: any) => {
            setEditingItem(plan);
            setMarketplaceDialog(true);
          }}
          onRefresh={fetchAllData}
        />
      )}
      {(storefrontThemesOnly || activeTab === 4) && (
        <StorefrontThemesTab
          themes={storefrontThemes}
          onRefresh={fetchAllData}
        />
      )}

      {/* Marketplace Item Dialog */}
      {marketplaceDialog && (
        <MarketplaceItemDialog
          open={marketplaceDialog}
          onClose={() => {
            setMarketplaceDialog(false);
            setEditingItem(null);
          }}
          item={editingItem}
          type={
            activeTab === 1
              ? "app"
              : activeTab === 3
                ? "enterprise"
                : editingItem?.feature
                  ? "pricing"
                  : "bundle"
          }
          onSave={async (itemData: any) => {
            try {
              const headers = getAuthHeaders();
              let typePath = "apps";
              if (activeTab === 1) typePath = "apps";
              else if (activeTab === 2)
                typePath = editingItem?.feature ? "pricing-rules" : "bundles";
              else if (activeTab === 3) typePath = "enterprise-plans";

              if (editingItem?.id) {
                await axios.put(
                  buildApiUrl(
                    `super-admin/marketplace-management/${typePath}/${editingItem.id}`,
                  ),
                  itemData,
                  { headers },
                );
              } else {
                await axios.post(
                  buildApiUrl(`super-admin/marketplace-management/${typePath}`),
                  itemData,
                  { headers },
                );
              }

              toast.success("تم الحفظ بنجاح");
              setMarketplaceDialog(false);
              setEditingItem(null);
              fetchAllData();
            } catch (err) {
              console.error("Marketplace save error:", err);
              toast.error("خطأ في الحفظ");
            }
          }}
        />
      )}

      {/* Plan Edit Dialog */}
      <EditPlanDialog
        open={planDialog}
        onClose={() => {
          setPlanDialog(false);
          setSelectedPlan(null);
        }}
        plan={selectedPlan}
        onSave={async (planData: any) => {
          try {
            const planType = planData.planType || selectedPlan?.planType;
            await axios.put(
              buildApiUrl(`admin/plans/plans/${planType}`),
              planData,
              { headers: getAuthHeaders() },
            );
            toast.success("تم حفظ الخطة بنجاح");
            setPlanDialog(false);
            fetchAllData();
          } catch (err) {
            console.error("Save error:", err);
            toast.error("خطأ في حفظ الخطة");
          }
        }}
      />
    </Box>
  );
};

// Sub-components for Tabs

const PlatformPlansTab = ({ plans, onEdit, onRefresh }) => {
  const [expandedPlan, setExpandedPlan] = useState<string | null>(null);

  const getPlanColor = (planType: string) => {
    const colors: { [key: string]: string } = {
      BASIC: "#3b82f6",
      PRO: "#8b5cf6",
      ENTERPRISE: "#f59e0b",
      CUSTOM: "#10b981",
    };
    return colors[planType] || "#6b7280";
  };

  const formatFeatureValue = (value: any) => {
    if (value === -1) return "غير محدود";
    if (value === true) return "✓";
    if (value === false || value === undefined || value === null) return "✗";
    return value;
  };

  const calculateTotalRevenue = (plan: any) => {
    return (plan.stats?.activeCompanies || 0) * (plan.price || 0);
  };

  const toggleExpand = (planType: string) => {
    setExpandedPlan(expandedPlan === planType ? null : planType);
  };

  return (
    <Box>
      {/* Summary Stats */}
      <Paper
        sx={{
          p: 3,
          mb: 3,
          bgcolor: "primary.light",
          color: "primary.contrastText",
        }}
      >
        <Grid container spacing={3}>
          <Grid size={{ xs: 12, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {plans.reduce(
                (sum, p) => sum + (p.stats?.activeCompanies || 0),
                0,
              )}
            </Typography>
            <Typography variant="body2">إجمالي الشركات المشتركة</Typography>
          </Grid>
          <Grid size={{ xs: 12, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {plans
                .reduce((sum, p) => sum + calculateTotalRevenue(p), 0)
                .toLocaleString()}{" "}
              ج.م
            </Typography>
            <Typography variant="body2">إجمالي الإيرادات الشهرية</Typography>
          </Grid>
          <Grid size={{ xs: 12, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {plans.length}
            </Typography>
            <Typography variant="body2">عدد الخطط المتاحة</Typography>
          </Grid>
          <Grid size={{ xs: 12, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {plans.filter((p) => p.isCustom).length}
            </Typography>
            <Typography variant="body2">خطط مخصصة</Typography>
          </Grid>
        </Grid>
      </Paper>

      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h6">خطط المنصة الأساسية</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => onEdit(null)}
        >
          إنشاء خطة جديدة
        </Button>
      </Box>

      <Grid container spacing={3}>
        {plans.map((plan) => {
          const features =
            typeof plan.features === "string"
              ? JSON.parse(plan.features)
              : plan.features || {};
          const isExpanded = expandedPlan === plan.planType;
          const monthlyRevenue = calculateTotalRevenue(plan);

          return (
            <Grid key={plan.planType} size={{ xs: 12, md: 6, lg: 4 }}>
              <Card
                sx={{
                  height: "100%",
                  borderTop: 4,
                  borderColor: getPlanColor(plan.planType),
                  transition: "all 0.3s ease",
                  "&:hover": { boxShadow: 4 },
                }}
              >
                <CardContent>
                  {/* Plan Header */}
                  <Box textAlign="center" mb={2}>
                    <Typography variant="h5" fontWeight="bold">
                      {plan.name}
                    </Typography>
                    <Chip
                      label={plan.planType}
                      size="small"
                      sx={{
                        mt: 0.5,
                        bgcolor: getPlanColor(plan.planType),
                        color: "white",
                      }}
                    />
                    <Typography variant="h4" color="primary" sx={{ my: 1 }}>
                      {plan.price?.toLocaleString()} {plan.currency || "ج.م"}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      /{" "}
                      {plan.billingCycle === "monthly"
                        ? "شهرياً"
                        : plan.billingCycle === "yearly"
                          ? "سنوياً"
                          : "ربع سنوي"}
                    </Typography>
                  </Box>

                  {/* Stats Row */}
                  <Paper
                    variant="outlined"
                    sx={{ p: 2, mb: 2, bgcolor: "action.hover" }}
                  >
                    <Grid container spacing={1} textAlign="center">
                      <Grid size={{ xs: 6 }}>
                        <Typography
                          variant="h6"
                          fontWeight="bold"
                          color="success.main"
                        >
                          {plan.stats?.activeCompanies || 0}
                        </Typography>
                        <Typography variant="caption" display="block">
                          الشركات
                        </Typography>
                      </Grid>
                      <Grid size={{ xs: 6 }}>
                        <Typography
                          variant="h6"
                          fontWeight="bold"
                          color="primary.main"
                        >
                          {monthlyRevenue.toLocaleString()}
                        </Typography>
                        <Typography variant="caption" display="block">
                          ج.م/شهر
                        </Typography>
                      </Grid>
                    </Grid>
                  </Paper>

                  {/* Quick Features Preview */}
                  <Box mb={2}>
                    <Typography
                      variant="subtitle2"
                      gutterBottom
                      fontWeight="bold"
                    >
                      أبرز المميزات:
                    </Typography>
                    <Box display="flex" flexWrap="wrap" gap={0.5}>
                      <Chip
                        icon={<CheckIcon fontSize="small" />}
                        label={`${formatFeatureValue(features.maxUsers)} مستخدم`}
                        size="small"
                        variant="outlined"
                      />
                      <Chip
                        icon={<CheckIcon fontSize="small" />}
                        label={`${formatFeatureValue(features.maxCustomers)} عميل`}
                        size="small"
                        variant="outlined"
                      />
                      <Chip
                        icon={<CheckIcon fontSize="small" />}
                        label={`${formatFeatureValue(features.storageLimit)} GB تخزين`}
                        size="small"
                        variant="outlined"
                      />
                      {features.apiAccess && (
                        <Chip
                          icon={<CheckIcon fontSize="small" />}
                          label="API"
                          size="small"
                          color="success"
                        />
                      )}
                      {features.prioritySupport && (
                        <Chip
                          icon={<CheckIcon fontSize="small" />}
                          label="دعم مميز"
                          size="small"
                          color="primary"
                        />
                      )}
                    </Box>
                  </Box>

                  {/* Description */}
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{ mb: 2, minHeight: 40 }}
                  >
                    {plan.description || "لا يوجد وصف"}
                  </Typography>

                  {/* Expandable Features List */}
                  <Collapse in={isExpanded}>
                    <Divider sx={{ my: 2 }} />
                    <Typography variant="subtitle2" gutterBottom>
                      تفاصيل المميزات:
                    </Typography>
                    <List dense sx={{ mb: 2 }}>
                      <ListItem>
                        <ListItemText
                          primary={`المستخدمين: ${formatFeatureValue(features.maxUsers)}`}
                          secondary={`العملاء: ${formatFeatureValue(features.maxCustomers)}`}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemText
                          primary={`المحادثات: ${formatFeatureValue(features.maxConversations)}`}
                          secondary={`الرسائل: ${formatFeatureValue(features.maxMessages)}`}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemText
                          primary={`ردود AI: ${formatFeatureValue(features.aiResponses)}`}
                          secondary={`التخزين: ${formatFeatureValue(features.storageLimit)} GB`}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemText
                          primary={`سير العمل: ${formatFeatureValue(features.automatedWorkflows)}`}
                          secondary={`الحقول المخصصة: ${formatFeatureValue(features.customFields)}`}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemText
                          primary={`الاحتفاظ بالبيانات: ${formatFeatureValue(features.dataRetention)} يوم`}
                          secondary={`SLA: ${features.sla || "غير محدد"}`}
                        />
                      </ListItem>
                    </List>
                    <Box display="flex" flexWrap="wrap" gap={1}>
                      {features.customBranding && (
                        <Chip label="علامة تجارية" size="small" />
                      )}
                      {features.advancedReports && (
                        <Chip label="تقارير متقدمة" size="small" />
                      )}
                      {features.apiAccess && (
                        <Chip label="API" size="small" color="primary" />
                      )}
                      {features.prioritySupport && (
                        <Chip label="دعم أولوية" size="small" color="primary" />
                      )}
                      {features.customIntegrations && (
                        <Chip label="تكاملات" size="small" />
                      )}
                      {features.whatsappBusiness && (
                        <Chip label="واتساب" size="small" />
                      )}
                      {features.facebookMessenger && (
                        <Chip label="ماسنجر" size="small" />
                      )}
                      {features.webChat && <Chip label="دردشة" size="small" />}
                      {features.mobileApp && (
                        <Chip label="تطبيق" size="small" color="success" />
                      )}
                      {features.multiLanguage && (
                        <Chip label="متعدد اللغات" size="small" />
                      )}
                      {features.exportData && (
                        <Chip label="تصدير" size="small" />
                      )}
                      {features.dedicatedSupport && (
                        <Chip label="دعم مخصص" size="small" color="success" />
                      )}
                    </Box>
                  </Collapse>

                  {/* Actions */}
                  <Box
                    display="flex"
                    justifyContent="space-between"
                    alignItems="center"
                    mt={2}
                  >
                    <Tooltip
                      title={isExpanded ? "إخفاء التفاصيل" : "عرض التفاصيل"}
                    >
                      <Button
                        size="small"
                        onClick={() => toggleExpand(plan.planType)}
                        variant="text"
                      >
                        {isExpanded ? "إخفاء" : "المزيد"}
                      </Button>
                    </Tooltip>
                    <Button
                      variant="outlined"
                      size="small"
                      startIcon={<EditIcon />}
                      onClick={() => onEdit(plan)}
                    >
                      تعديل
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          );
        })}
      </Grid>
    </Box>
  );
};

type CatalogDiffFieldChange = {
  field: string;
  catalog: any;
  db: any;
};

type CatalogDiffEntityDetails = {
  slug: string;
  changes: CatalogDiffFieldChange[];
};

type CatalogDiffSection = {
  missingInDb: string[];
  extraInDb: string[];
  changed: CatalogDiffEntityDetails[];
};

type CatalogDiffPayload = {
  comparedAt: string;
  catalogMeta?: any;
  totals?: {
    catalogApps: number;
    dbApps: number;
    catalogBundles: number;
    dbBundles: number;
    diffEntries: number;
  };
  apps?: CatalogDiffSection;
  bundles?: CatalogDiffSection;
};

const MarketplaceAppsTab = ({
  apps,
  catalogDiff,
  catalogDiffLoading,
  catalogDiffError,
  onEdit,
  onDelete,
  onRefresh,
  onRefreshCatalogDiff,
}: {
  apps: any[];
  catalogDiff: CatalogDiffPayload | null;
  catalogDiffLoading: boolean;
  catalogDiffError: string | null;
  onEdit: (app: any) => void;
  onDelete: (id: string) => void;
  onRefresh: () => void;
  onRefreshCatalogDiff: () => void;
}) => {
  const [searchQuery, setSearchQuery] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("ALL");
  const [sortBy, setSortBy] = useState("installations");
  const [expandedApp, setExpandedApp] = useState<string | null>(null);
  const [showCatalogDiffDetails, setShowCatalogDiffDetails] = useState(false);

  const formatDiffValue = (value: any) => {
    if (Array.isArray(value)) {
      return value.length > 0 ? value.join(", ") : "[]";
    }
    if (value === null) return "null";
    if (value === undefined) return "undefined";
    if (typeof value === "object") return JSON.stringify(value);
    return String(value);
  };

  // Get unique categories
  const categories = [
    "ALL",
    ...new Set(apps.map((app) => app.category).filter(Boolean)),
  ];

  // Filter and sort apps
  const filteredApps = apps
    .filter((app) => {
      const matchesSearch =
        app.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        app.description?.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesCategory =
        categoryFilter === "ALL" || app.category === categoryFilter;
      return matchesSearch && matchesCategory;
    })
    .sort((a, b) => {
      switch (sortBy) {
        case "price":
          return (b.monthlyPrice || 0) - (a.monthlyPrice || 0);
        case "rating":
          return (b.rating || 0) - (a.rating || 0);
        case "installations":
          return (
            (b._count?.installations || b.installCount || 0) -
            (a._count?.installations || a.installCount || 0)
          );
        case "name":
          return (a.name || "").localeCompare(b.name || "");
        default:
          return 0;
      }
    });

  // Calculate statistics
  const totalInstallations = apps.reduce(
    (sum, app) => sum + (app._count?.installations || app.installCount || 0),
    0,
  );
  const totalMonthlyRevenue = apps.reduce((sum, app) => {
    const installs = app._count?.installations || app.installCount || 0;
    return sum + installs * (app.monthlyPrice || 0);
  }, 0);
  const activeApps = apps.filter((app) => app.isActive).length;
  const featuredApps = apps.filter((app) => app.isFeatured).length;
  const appDiffEntries =
    (catalogDiff?.apps?.missingInDb?.length || 0) +
    (catalogDiff?.apps?.extraInDb?.length || 0) +
    (catalogDiff?.apps?.changed?.length || 0);
  const bundleDiffEntries =
    (catalogDiff?.bundles?.missingInDb?.length || 0) +
    (catalogDiff?.bundles?.extraInDb?.length || 0) +
    (catalogDiff?.bundles?.changed?.length || 0);
  const hasDiffData = Boolean(catalogDiff?.totals);
  const comparedAtLabel = catalogDiff?.comparedAt
    ? new Date(catalogDiff.comparedAt).toLocaleString("ar-EG")
    : "غير متاح";

  const categoryLabels: { [key: string]: string } = {
    ALL: "جميع الفئات",
    ECOMMERCE: "التجارة الإلكترونية",
    AI: "الذكاء الاصطناعي",
    CRM: "إدارة العملاء",
    COMMUNICATION: "التواصل",
    ANALYTICS: "التحليلات",
    MARKETING: "التسويق",
    HR: "الموارد البشرية",
    FINANCE: "المالية",
    INTEGRATION: "التكاملات",
    PRODUCTIVITY: "الإنتاجية",
    GAMIFICATION: "التحفيز",
  };

  const getCategoryColor = (category: string) => {
    const colors: { [key: string]: string } = {
      ECOMMERCE: "#3b82f6",
      AI: "#8b5cf6",
      CRM: "#10b981",
      COMMUNICATION: "#f59e0b",
      ANALYTICS: "#ef4444",
      MARKETING: "#ec4899",
      HR: "#06b6d4",
      FINANCE: "#84cc16",
      INTEGRATION: "#6366f1",
      PRODUCTIVITY: "#14b8a6",
      GAMIFICATION: "#f97316",
    };
    return colors[category] || "#6b7280";
  };

  const calculateAppRevenue = (app: any) => {
    const installs = app._count?.installations || app.installCount || 0;
    return installs * (app.monthlyPrice || 0);
  };

  const handleQuickToggle = async (app: any, field: string, value: boolean) => {
    try {
      await axios.patch(
        buildApiUrl(`super-admin/marketplace-management/apps/${app.id}`),
        { [field]: value },
        { headers: getAuthHeaders() },
      );
      toast.success(
        `تم ${value ? "تفعيل" : "تعطيل"} ${field === "isActive" ? "التطبيق" : "الميزة"} بنجاح`,
      );
      onRefresh();
    } catch (err) {
      toast.error("خطأ في التحديث");
    }
  };

  const handleExport = async () => {
    try {
      const response = await axios.get(
        buildApiUrl("super-admin/marketplace-management/export"),
        {
          headers: getAuthHeaders(),
          responseType: "blob",
        },
      );

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `marketplace-config-${new Date().toISOString().split("T")[0]}.json`,
      );
      document.body.appendChild(link);
      link.click();
      link.remove();
      toast.success("تم تصدير الإعدادات بنجاح");
    } catch (err) {
      console.error("Export error:", err);
      toast.error("فشل في تصدير الإعدادات");
    }
  };

  const handleImport = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);

    try {
      await axios.post(
        buildApiUrl("super-admin/marketplace-management/import"),
        formData,
        {
          headers: getAuthHeaders({
            "Content-Type": "multipart/form-data",
          }),
        },
      );
      toast.success("تم استيراد الإعدادات بنجاح");
      onRefresh();
    } catch (err) {
      console.error("Import error:", err);
      toast.error("فشل في استيراد الإعدادات");
    }
  };

  return (
    <Box>
      {/* Statistics Dashboard */}
      <Paper
        sx={{
          p: 3,
          mb: 3,
          bgcolor: "secondary.light",
          color: "secondary.contrastText",
        }}
      >
        <Grid container spacing={3}>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {apps.length}
            </Typography>
            <Typography variant="body2">إجمالي التطبيقات</Typography>
          </Grid>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {totalInstallations.toLocaleString()}
            </Typography>
            <Typography variant="body2">إجمالي التثبيتات</Typography>
          </Grid>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {totalMonthlyRevenue.toLocaleString()} ج.م
            </Typography>
            <Typography variant="body2">إيرادات شهرية</Typography>
          </Grid>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {activeApps}
            </Typography>
            <Typography variant="body2">نشط | {featuredApps} مميز</Typography>
          </Grid>
        </Grid>
      </Paper>

      {/* Catalog Diff (Files vs DB) */}
      <Paper
        sx={{
          p: 2,
          mb: 3,
          border: 1,
          borderColor:
            (catalogDiff?.totals?.diffEntries || 0) > 0
              ? "warning.light"
              : "success.light",
        }}
      >
        <Box
          display="flex"
          justifyContent="space-between"
          alignItems={{ xs: "flex-start", md: "center" }}
          flexDirection={{ xs: "column", md: "row" }}
          gap={1}
          mb={1.5}
        >
          <Box>
            <Typography variant="h6" fontWeight="bold">
              فرق الكاتالوج (Files vs DB)
            </Typography>
            <Typography variant="caption" color="text.secondary">
              آخر مقارنة: {comparedAtLabel}
            </Typography>
          </Box>
          <Box display="flex" gap={1}>
            <Button
              variant="outlined"
              size="small"
              startIcon={<RefreshIcon />}
              onClick={onRefreshCatalogDiff}
              disabled={catalogDiffLoading}
            >
              {catalogDiffLoading ? "جارٍ التحديث..." : "تحديث"}
            </Button>
            <Button
              variant="text"
              size="small"
              onClick={() => setShowCatalogDiffDetails((prev) => !prev)}
              disabled={!hasDiffData}
            >
              {showCatalogDiffDetails ? "إخفاء التفاصيل" : "عرض التفاصيل"}
            </Button>
          </Box>
        </Box>

        {catalogDiffError && (
          <Alert severity="warning" sx={{ mb: 1.5 }}>
            {catalogDiffError}
          </Alert>
        )}

        {hasDiffData ? (
          <Grid container spacing={1}>
            <Grid size={{ xs: 6, md: 4 }}>
              <Paper variant="outlined" sx={{ p: 1.5 }}>
                <Typography variant="caption" color="text.secondary">
                  إجمالي الفرق
                </Typography>
                <Typography variant="h6" fontWeight="bold">
                  {catalogDiff?.totals?.diffEntries || 0}
                </Typography>
              </Paper>
            </Grid>
            <Grid size={{ xs: 6, md: 4 }}>
              <Paper variant="outlined" sx={{ p: 1.5 }}>
                <Typography variant="caption" color="text.secondary">
                  Apps (Catalog/DB)
                </Typography>
                <Typography variant="h6" fontWeight="bold">
                  {catalogDiff?.totals?.catalogApps || 0}/
                  {catalogDiff?.totals?.dbApps || 0}
                </Typography>
              </Paper>
            </Grid>
            <Grid size={{ xs: 6, md: 4 }}>
              <Paper variant="outlined" sx={{ p: 1.5 }}>
                <Typography variant="caption" color="text.secondary">
                  Bundles (Catalog/DB)
                </Typography>
                <Typography variant="h6" fontWeight="bold">
                  {catalogDiff?.totals?.catalogBundles || 0}/
                  {catalogDiff?.totals?.dbBundles || 0}
                </Typography>
              </Paper>
            </Grid>
            <Grid size={{ xs: 6, md: 4 }}>
              <Paper variant="outlined" sx={{ p: 1.5 }}>
                <Typography variant="caption" color="text.secondary">
                  فروقات التطبيقات
                </Typography>
                <Typography variant="h6" fontWeight="bold">
                  {appDiffEntries}
                </Typography>
              </Paper>
            </Grid>
            <Grid size={{ xs: 6, md: 4 }}>
              <Paper variant="outlined" sx={{ p: 1.5 }}>
                <Typography variant="caption" color="text.secondary">
                  فروقات الباقات
                </Typography>
                <Typography variant="h6" fontWeight="bold">
                  {bundleDiffEntries}
                </Typography>
              </Paper>
            </Grid>
          </Grid>
        ) : (
          <Typography variant="body2" color="text.secondary">
            لا توجد بيانات فرق متاحة حالياً.
          </Typography>
        )}

        <Collapse in={showCatalogDiffDetails && hasDiffData}>
          <Divider sx={{ my: 2 }} />
          <Grid container spacing={2}>
            <Grid size={{ xs: 12, md: 6 }}>
              <Typography variant="subtitle2" fontWeight="bold" gutterBottom>
                تطبيقات
              </Typography>
              <Box mb={1}>
                <Typography variant="caption" color="text.secondary">
                  موجود بالملفات وغير موجود في DB (
                  {catalogDiff?.apps?.missingInDb?.length || 0})
                </Typography>
                <Box display="flex" flexWrap="wrap" gap={0.5} mt={0.5}>
                  {(catalogDiff?.apps?.missingInDb || []).map((slug) => (
                    <Chip
                      key={`app-miss-${slug}`}
                      size="small"
                      label={slug}
                      color="warning"
                    />
                  ))}
                </Box>
              </Box>
              <Box mb={1}>
                <Typography variant="caption" color="text.secondary">
                  موجود في DB وغير موجود بالملفات (
                  {catalogDiff?.apps?.extraInDb?.length || 0})
                </Typography>
                <Box display="flex" flexWrap="wrap" gap={0.5} mt={0.5}>
                  {(catalogDiff?.apps?.extraInDb || []).map((slug) => (
                    <Chip
                      key={`app-extra-${slug}`}
                      size="small"
                      label={slug}
                      color="info"
                    />
                  ))}
                </Box>
              </Box>
              <Box>
                <Typography variant="caption" color="text.secondary">
                  عناصر مختلفة ({catalogDiff?.apps?.changed?.length || 0})
                </Typography>
                <List dense sx={{ maxHeight: 220, overflow: "auto", mt: 0.5 }}>
                  {(catalogDiff?.apps?.changed || []).map((entry) => (
                    <ListItem
                      key={`app-changed-${entry.slug}`}
                      sx={{ display: "block", py: 0.5 }}
                    >
                      <Typography variant="body2" fontWeight="bold">
                        {entry.slug}
                      </Typography>
                      {(entry.changes || []).slice(0, 3).map((change) => (
                        <Typography
                          key={`${entry.slug}-${change.field}`}
                          variant="caption"
                          color="text.secondary"
                          display="block"
                        >
                          {change.field}: [{formatDiffValue(change.catalog)}]{" "}
                          {"->"} [{formatDiffValue(change.db)}]
                        </Typography>
                      ))}
                      {(entry.changes || []).length > 3 && (
                        <Typography
                          variant="caption"
                          color="text.secondary"
                          display="block"
                        >
                          +{entry.changes.length - 3} تغييرات إضافية
                        </Typography>
                      )}
                    </ListItem>
                  ))}
                </List>
              </Box>
            </Grid>

            <Grid size={{ xs: 12, md: 6 }}>
              <Typography variant="subtitle2" fontWeight="bold" gutterBottom>
                باقات
              </Typography>
              <Box mb={1}>
                <Typography variant="caption" color="text.secondary">
                  موجود بالملفات وغير موجود في DB (
                  {catalogDiff?.bundles?.missingInDb?.length || 0})
                </Typography>
                <Box display="flex" flexWrap="wrap" gap={0.5} mt={0.5}>
                  {(catalogDiff?.bundles?.missingInDb || []).map((slug) => (
                    <Chip
                      key={`bundle-miss-${slug}`}
                      size="small"
                      label={slug}
                      color="warning"
                    />
                  ))}
                </Box>
              </Box>
              <Box mb={1}>
                <Typography variant="caption" color="text.secondary">
                  موجود في DB وغير موجود بالملفات (
                  {catalogDiff?.bundles?.extraInDb?.length || 0})
                </Typography>
                <Box display="flex" flexWrap="wrap" gap={0.5} mt={0.5}>
                  {(catalogDiff?.bundles?.extraInDb || []).map((slug) => (
                    <Chip
                      key={`bundle-extra-${slug}`}
                      size="small"
                      label={slug}
                      color="info"
                    />
                  ))}
                </Box>
              </Box>
              <Box>
                <Typography variant="caption" color="text.secondary">
                  عناصر مختلفة ({catalogDiff?.bundles?.changed?.length || 0})
                </Typography>
                <List dense sx={{ maxHeight: 220, overflow: "auto", mt: 0.5 }}>
                  {(catalogDiff?.bundles?.changed || []).map((entry) => (
                    <ListItem
                      key={`bundle-changed-${entry.slug}`}
                      sx={{ display: "block", py: 0.5 }}
                    >
                      <Typography variant="body2" fontWeight="bold">
                        {entry.slug}
                      </Typography>
                      {(entry.changes || []).slice(0, 3).map((change) => (
                        <Typography
                          key={`${entry.slug}-${change.field}`}
                          variant="caption"
                          color="text.secondary"
                          display="block"
                        >
                          {change.field}: [{formatDiffValue(change.catalog)}]{" "}
                          {"->"} [{formatDiffValue(change.db)}]
                        </Typography>
                      ))}
                      {(entry.changes || []).length > 3 && (
                        <Typography
                          variant="caption"
                          color="text.secondary"
                          display="block"
                        >
                          +{entry.changes.length - 3} تغييرات إضافية
                        </Typography>
                      )}
                    </ListItem>
                  ))}
                </List>
              </Box>
            </Grid>
          </Grid>
        </Collapse>
      </Paper>

      {/* Filters and Search */}
      <Paper sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid size={{ xs: 12, md: 4 }}>
            <TextField
              fullWidth
              placeholder="البحث في التطبيقات..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              size="small"
              InputProps={{
                startAdornment: (
                  <Box component="span" sx={{ mr: 1 }}>
                    🔍
                  </Box>
                ),
              }}
            />
          </Grid>
          <Grid size={{ xs: 12, md: 3 }}>
            <FormControl fullWidth size="small">
              <InputLabel>الترتيب</InputLabel>
              <Select
                value={sortBy}
                label="الترتيب"
                onChange={(e) => setSortBy(e.target.value)}
              >
                <MenuItem value="installations">الأكثر تثبيتاً</MenuItem>
                <MenuItem value="price">الأعلى سعراً</MenuItem>
                <MenuItem value="rating">الأعلى تقييماً</MenuItem>
                <MenuItem value="name">الاسم</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid size={{ xs: 12, md: 5 }}>
            <Box display="flex" gap={1}>
              <Button
                fullWidth
                variant="contained"
                startIcon={<AddIcon />}
                onClick={() => onEdit(null)}
              >
                إضافة
              </Button>
              <Button
                variant="outlined"
                startIcon={<DownloadIcon />}
                onClick={handleExport}
                sx={{ minWidth: 100 }}
              >
                تصدير
              </Button>
              <Button
                variant="outlined"
                component="label"
                startIcon={<UploadIcon />}
                sx={{ minWidth: 100 }}
              >
                استيراد
                <input
                  type="file"
                  hidden
                  accept=".json"
                  onChange={handleImport}
                />
              </Button>
            </Box>
          </Grid>
        </Grid>
        {filteredApps.length !== apps.length && (
          <Typography
            variant="caption"
            color="text.secondary"
            sx={{ mt: 1, display: "block" }}
          >
            عرض {filteredApps.length} من {apps.length} تطبيق
          </Typography>
        )}
      </Paper>

      {/* Category Tabs + Apps Grid Layout */}
      <Grid container spacing={2}>
        {/* Side Category Tabs */}
        <Grid size={{ xs: 12, md: 2 }}>
          <Paper sx={{ height: "100%", minHeight: 400 }}>
            <Tabs
              orientation="vertical"
              variant="scrollable"
              value={categoryFilter}
              onChange={(_, newValue) => setCategoryFilter(newValue)}
              sx={{
                borderLeft: 1,
                borderColor: "divider",
                "& .MuiTabs-flexContainer": { alignItems: "stretch" },
              }}
            >
              {categories.map((cat) => (
                <Tab
                  key={cat}
                  value={cat}
                  label={
                    <Box
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        gap: 1,
                        width: "100%",
                      }}
                    >
                      <Box
                        sx={{
                          width: 12,
                          height: 12,
                          borderRadius: "50%",
                          bgcolor:
                            cat === "ALL" ? "#6b7280" : getCategoryColor(cat),
                          flexShrink: 0,
                        }}
                      />
                      <Typography
                        variant="body2"
                        sx={{ flex: 1, textAlign: "right" }}
                      >
                        {categoryLabels[cat] || cat}
                      </Typography>
                      <Chip
                        label={
                          cat === "ALL"
                            ? apps.length
                            : apps.filter((a) => a.category === cat).length
                        }
                        size="small"
                        sx={{
                          height: 20,
                          fontSize: "0.7rem",
                          bgcolor:
                            categoryFilter === cat
                              ? "primary.main"
                              : "action.hover",
                          color:
                            categoryFilter === cat
                              ? "primary.contrastText"
                              : "text.secondary",
                        }}
                      />
                    </Box>
                  }
                  sx={{
                    alignItems: "flex-start",
                    textAlign: "right",
                    minHeight: 48,
                    px: 1,
                    "&.Mui-selected": {
                      bgcolor: "action.selected",
                      borderLeft: 3,
                      borderColor:
                        cat === "ALL" ? "#6b7280" : getCategoryColor(cat),
                    },
                  }}
                />
              ))}
            </Tabs>
          </Paper>
        </Grid>

        {/* Apps Grid */}
        <Grid size={{ xs: 12, md: 10 }}>
          <Grid container spacing={3}>
            {filteredApps.map((app) => {
              const monthlyRevenue = calculateAppRevenue(app);
              const isExpanded = expandedApp === app.id;

              return (
                <Grid key={app.id} size={{ xs: 12, sm: 6, md: 4 }}>
                  <Card
                    sx={{
                      height: "100%",
                      display: "flex",
                      flexDirection: "column",
                      borderTop: 3,
                      borderColor: getCategoryColor(app.category),
                      transition: "all 0.2s ease",
                      "&:hover": {
                        boxShadow: 4,
                        transform: "translateY(-2px)",
                      },
                    }}
                  >
                    <CardContent sx={{ flexGrow: 1, pb: 1 }}>
                      {/* Header */}
                      <Box
                        display="flex"
                        justifyContent="space-between"
                        alignItems="flex-start"
                        mb={1}
                      >
                        <Box flex={1}>
                          <Typography variant="h6" fontWeight="bold" noWrap>
                            {app.name}
                          </Typography>
                          <Chip
                            label={app.category}
                            size="small"
                            sx={{
                              mt: 0.5,
                              bgcolor: getCategoryColor(app.category),
                              color: "white",
                              fontSize: "0.7rem",
                            }}
                          />
                        </Box>
                        <Box
                          display="flex"
                          flexDirection="column"
                          alignItems="flex-end"
                          gap={0.5}
                        >
                          {app.isFeatured && (
                            <Chip
                              label="مميز"
                              color="warning"
                              size="small"
                              icon={<StarIcon fontSize="small" />}
                            />
                          )}
                          {app.isPopular && (
                            <Chip label="شائع" color="info" size="small" />
                          )}
                        </Box>
                      </Box>

                      {/* Description */}
                      <Typography
                        variant="body2"
                        color="text.secondary"
                        sx={{
                          mb: 2,
                          height: 36,
                          overflow: "hidden",
                          display: "-webkit-box",
                          WebkitLineClamp: 2,
                          WebkitBoxOrient: "vertical",
                          fontSize: "0.8rem",
                        }}
                      >
                        {app.description || "لا يوجد وصف"}
                      </Typography>

                      {/* Stats Row */}
                      <Paper
                        variant="outlined"
                        sx={{ p: 1.5, mb: 2, bgcolor: "action.hover" }}
                      >
                        <Grid container spacing={1} textAlign="center">
                          <Grid size={{ xs: 4 }}>
                            <Typography
                              variant="h6"
                              fontWeight="bold"
                              color="primary.main"
                              fontSize="1rem"
                            >
                              {app._count?.installations ||
                                app.installCount ||
                                0}
                            </Typography>
                            <Typography
                              variant="caption"
                              display="block"
                              fontSize="0.65rem"
                            >
                              تثبيت
                            </Typography>
                          </Grid>
                          <Grid size={{ xs: 4 }}>
                            <Typography
                              variant="h6"
                              fontWeight="bold"
                              color="success.main"
                              fontSize="1rem"
                            >
                              ⭐ {app.rating?.toFixed(1) || "0.0"}
                            </Typography>
                            <Typography
                              variant="caption"
                              display="block"
                              fontSize="0.65rem"
                            >
                              ({app.reviewCount || 0})
                            </Typography>
                          </Grid>
                          <Grid size={{ xs: 4 }}>
                            <Typography
                              variant="h6"
                              fontWeight="bold"
                              color="warning.main"
                              fontSize="1rem"
                            >
                              {monthlyRevenue.toLocaleString()}
                            </Typography>
                            <Typography
                              variant="caption"
                              display="block"
                              fontSize="0.65rem"
                            >
                              ج.م/شهر
                            </Typography>
                          </Grid>
                        </Grid>
                      </Paper>

                      {/* Price */}
                      <Box display="flex" alignItems="center" gap={1} mb={1}>
                        <Typography
                          variant="h5"
                          color="primary"
                          fontWeight="bold"
                        >
                          {app.monthlyPrice?.toLocaleString() || 0} ج
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          / شهر
                        </Typography>
                        {app.yearlyPrice > 0 && (
                          <Chip
                            label={`${Math.round((1 - app.yearlyPrice / (app.monthlyPrice * 12)) * 100)}% توفير سنوي`}
                            size="small"
                            color="success"
                            variant="outlined"
                          />
                        )}
                      </Box>

                      {/* Expanded Details */}
                      <Collapse in={isExpanded}>
                        <Divider sx={{ my: 1.5 }} />
                        <Box mb={1.5}>
                          <Typography
                            variant="caption"
                            color="text.secondary"
                            display="block"
                          >
                            أيام التجربة: {app.trialDays || 14} يوم
                          </Typography>
                          <Typography
                            variant="caption"
                            color="text.secondary"
                            display="block"
                          >
                            الإيرادات المتوقعة:{" "}
                            {(
                              app.monthlyPrice *
                              (app._count?.installations || 0) *
                              12
                            ).toLocaleString()}{" "}
                            ج.م/سنة
                          </Typography>
                          {app.mainRoute && (
                            <Typography
                              variant="caption"
                              color="text.secondary"
                              display="block"
                            >
                              المسار: {app.mainRoute}
                            </Typography>
                          )}
                        </Box>
                      </Collapse>

                      {/* Toggle Switches */}
                      <Box display="flex" gap={2} mb={1} flexWrap="wrap">
                        <Box display="flex" alignItems="center" gap={0.5}>
                          <input
                            type="checkbox"
                            checked={!!app.isActive}
                            onChange={(e) =>
                              handleQuickToggle(
                                app,
                                "isActive",
                                e.target.checked,
                              )
                            }
                            style={{ cursor: "pointer" }}
                          />
                          <Typography variant="caption">نشط</Typography>
                        </Box>
                        <Box display="flex" alignItems="center" gap={0.5}>
                          <input
                            type="checkbox"
                            checked={!!app.isPublic}
                            onChange={(e) =>
                              handleQuickToggle(
                                app,
                                "isPublic",
                                e.target.checked,
                              )
                            }
                            style={{ cursor: "pointer" }}
                          />
                          <Typography variant="caption">عام</Typography>
                        </Box>
                        <Box display="flex" alignItems="center" gap={0.5}>
                          <input
                            type="checkbox"
                            checked={!!app.isFeatured}
                            onChange={(e) =>
                              handleQuickToggle(
                                app,
                                "isFeatured",
                                e.target.checked,
                              )
                            }
                            style={{ cursor: "pointer" }}
                          />
                          <Typography variant="caption">مميز</Typography>
                        </Box>
                      </Box>

                      {/* Actions */}
                      <Box
                        display="flex"
                        justifyContent="space-between"
                        alignItems="center"
                      >
                        <Button
                          size="small"
                          onClick={() =>
                            setExpandedApp(isExpanded ? null : app.id)
                          }
                          variant="text"
                        >
                          {isExpanded ? "أقل" : "المزيد"}
                        </Button>
                        <Box>
                          <Tooltip title="تعديل">
                            <IconButton
                              size="small"
                              onClick={() => onEdit(app)}
                              color="primary"
                            >
                              <EditIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="حذف">
                            <IconButton
                              size="small"
                              color="error"
                              onClick={() => onDelete(app.id)}
                            >
                              <DeleteIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>

          {filteredApps.length === 0 && (
            <Paper sx={{ p: 4, textAlign: "center" }}>
              <Typography variant="h6" color="text.secondary">
                لا توجد تطبيقات مطابقة للبحث
              </Typography>
            </Paper>
          )}
        </Grid>
      </Grid>
    </Box>
  );
};

const BundlesAndPricingTab = ({
  pricingRules,
  bundles,
  onEdit,
  onDelete,
  onRefresh,
}: {
  pricingRules: any[];
  bundles: any[];
  onEdit: (item: any) => void;
  onDelete: (id: string) => void;
  onRefresh: () => void;
}) => {
  const [expandedBundle, setExpandedBundle] = useState<string | null>(null);

  const calculateBundleSavings = (bundle: any) => {
    if (!bundle.apps || bundle.apps.length === 0) return bundle.discount || 0;
    return bundle.discount || 0;
  };

  const handleQuickToggle = async (
    bundle: any,
    field: string,
    value: boolean,
  ) => {
    try {
      await axios.patch(
        buildApiUrl(`super-admin/marketplace-management/bundles/${bundle.id}`),
        { [field]: value },
        { headers: getAuthHeaders() },
      );
      toast.success(`تم ${value ? "تفعيل" : "تعطيل"} الباقة بنجاح`);
      onRefresh();
    } catch (err) {
      toast.error("خطأ في التحديث");
    }
  };

  return (
    <Box>
      {/* Pricing Rules Section */}
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={2}
      >
        <Typography variant="h6">قواعد التسعير الإضافية</Typography>
        <Button
          variant="outlined"
          startIcon={<AddIcon />}
          size="small"
          onClick={() => onEdit({ feature: "", price: 0, unit: "" })}
        >
          إضافة قاعدة
        </Button>
      </Box>
      <TableContainer component={Paper} sx={{ mb: 4 }}>
        <Table size="small">
          <TableHead sx={{ bgcolor: "action.hover" }}>
            <TableRow>
              <TableCell>الميزة</TableCell>
              <TableCell>السعر</TableCell>
              <TableCell>الوحدة</TableCell>
              <TableCell>الحالة</TableCell>
              <TableCell>إجراءات</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {pricingRules.map((rule) => (
              <TableRow key={rule.id}>
                <TableCell>
                  <Typography fontWeight="bold">{rule.feature}</Typography>
                  {rule.description && (
                    <Typography
                      variant="caption"
                      color="text.secondary"
                      display="block"
                    >
                      {rule.description}
                    </Typography>
                  )}
                </TableCell>
                <TableCell>{rule.price} ج</TableCell>
                <TableCell>{rule.unit}</TableCell>
                <TableCell>
                  <Chip
                    label={rule.isActive ? "نشط" : "معطل"}
                    color={rule.isActive ? "success" : "default"}
                    size="small"
                  />
                </TableCell>
                <TableCell>
                  <IconButton size="small" onClick={() => onEdit(rule)}>
                    <EditIcon />
                  </IconButton>
                  <IconButton
                    size="small"
                    color="error"
                    onClick={() => onDelete(rule.id)}
                  >
                    <DeleteIcon />
                  </IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Bundles Section */}
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={2}
      >
        <Box>
          <Typography variant="h6">باقات العروض (Bundles)</Typography>
          <Typography variant="caption" color="text.secondary">
            {bundles.length} باقة | {bundles.filter((b) => b.isActive).length}{" "}
            نشطة
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          size="small"
          onClick={() => onEdit({ name: "", price: 0, apps: [] })}
        >
          إضافة باقة
        </Button>
      </Box>

      <Grid container spacing={3}>
        {bundles.map((bundle) => {
          const isExpanded = expandedBundle === bundle.id;
          const appsCount = bundle.apps?.length || 0;
          const savings = calculateBundleSavings(bundle);

          return (
            <Grid key={bundle.id} size={{ xs: 12, md: 6 }}>
              <Card
                sx={{
                  bgcolor: bundle.isActive
                    ? "background.paper"
                    : "action.disabledBackground",
                  border: 2,
                  borderColor: bundle.isFeatured ? "warning.main" : "divider",
                  transition: "all 0.2s ease",
                  "&:hover": { boxShadow: 3 },
                }}
              >
                <CardContent>
                  {/* Header */}
                  <Box
                    display="flex"
                    justifyContent="space-between"
                    alignItems="flex-start"
                    mb={2}
                  >
                    <Box flex={1}>
                      <Box display="flex" alignItems="center" gap={1}>
                        <Typography variant="h6" fontWeight="bold">
                          {bundle.name}
                        </Typography>
