                    <Grid container spacing={2} alignItems="center">
                      <Grid size={{ xs: 6 }}>
                        <Typography
                          variant="caption"
                          color="text.secondary"
                          display="block"
                        >
                          السعر الحالي
                        </Typography>
                        <Typography
                          variant="h4"
                          fontWeight="bold"
                          color="success.dark"
