                      </Typography>
                    </Box>
                    <Box display="flex" flexWrap="wrap" gap={0.5}>
                      {appsCount > 0 ? (
                        bundle.apps.map((app: any, idx: number) => (
                          <Tooltip key={idx} title={app.name || app}>
                            <Chip
                              label={app.name || app}
                              size="small"
                              variant="outlined"
                              sx={{ maxWidth: 120 }}
                            />
                          </Tooltip>
                        ))
                      ) : (
                        <Typography variant="caption" color="text.secondary">
                          لا توجد تطبيقات مضمنة
                        </Typography>
                      )}
                    </Box>
                  </Box>

                  {/* Expanded Details */}
                  <Collapse in={isExpanded}>
                    <Divider sx={{ my: 1.5 }} />
                    {appsCount > 0 && (
                      <List dense sx={{ mb: 1 }}>
                        <Typography
                          variant="caption"
                          color="text.secondary"
                          gutterBottom
                          display="block"
                        >
                          تفاصيل التطبيقات:
                        </Typography>
                        {bundle.apps.map((app: any, idx: number) => (
                          <ListItem key={idx} sx={{ py: 0.5 }}>
                            <ListItemText
                              primary={app.name || app}
                              secondary={
                                typeof app === "object" ? app.category : ""
                              }
                            />
                          </ListItem>
                        ))}
                      </List>
                    )}
                  </Collapse>

                  {/* Toggle Switches */}
                  <Box display="flex" gap={2} mb={1} flexWrap="wrap">
                    <Box display="flex" alignItems="center" gap={0.5}>
                      <input
                        type="checkbox"
                        checked={!!bundle.isActive}
                        onChange={(e) =>
                          handleQuickToggle(
                            bundle,
                            "isActive",
                            e.target.checked,
                          )
                        }
                        style={{ cursor: "pointer" }}
                      />
                      <Typography variant="caption">نشطة</Typography>
                    </Box>
                    <Box display="flex" alignItems="center" gap={0.5}>
                      <input
                        type="checkbox"
                        checked={!!bundle.isFeatured}
                        onChange={(e) =>
                          handleQuickToggle(
                            bundle,
                            "isFeatured",
                            e.target.checked,
                          )
                        }
                        style={{ cursor: "pointer" }}
                      />
                      <Typography variant="caption">مميزة</Typography>
                    </Box>
                  </Box>

                  {/* Actions */}
                  <Box
                    display="flex"
                    justifyContent="space-between"
                    alignItems="center"
                  >
                    <Button
                      size="small"
                      onClick={() =>
                        setExpandedBundle(isExpanded ? null : bundle.id)
