                      {isExpanded ? "أقل" : "عرض التفاصيل"}
                    </Button>
                    <Box>
                      <Tooltip title="تعديل">
                        <IconButton
                          size="small"
                          onClick={() => onEdit(bundle)}
                          color="primary"
                        >
                          <EditIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="حذف">
                        <IconButton
                          size="small"
                          color="error"
                          onClick={() => onDelete(bundle.id)}
