const StorefrontThemesTab = ({
  themes,
  onRefresh,
}: {
  themes: StorefrontThemeCatalogItem[];
  onRefresh: () => void;
}) => {
  const [drafts, setDrafts] = useState<
    Record<string, StorefrontThemeCatalogItem>
  >({});
  const [savingThemeId, setSavingThemeId] = useState<string | null>(null);
  const [bulkSaving, setBulkSaving] = useState(false);
  const uniqueThemes = useMemo(
    () =>
      Array.from(
        themes
          .reduce((map, theme) => {
            if (!map.has(theme.themeId)) {
              map.set(theme.themeId, theme);
            }
            return map;
          }, new Map<string, StorefrontThemeCatalogItem>())
          .values(),
      ),
    [themes],
  );

  useEffect(() => {
    const nextDrafts = uniqueThemes.reduce<
      Record<string, StorefrontThemeCatalogItem>
    >((accumulator, theme) => {
      accumulator[theme.themeId] = theme;
      return accumulator;
    }, {});
    setDrafts(nextDrafts);
  }, [uniqueThemes]);

  const handleDraftChange = (
    themeId: string,
    patch: Partial<StorefrontThemeCatalogItem>,
  ) => {
    setDrafts((current) => ({
      ...current,
      [themeId]: {
        ...(current[themeId] ||
          uniqueThemes.find((theme) => theme.themeId === themeId)!),
        ...patch,
      },
      }));
  };

  const persistThemeDraft = async (
    themeId: string,
    draft: StorefrontThemeCatalogItem,
  ) => {
    await axios.put(
      buildApiUrl(`super-admin/storefront-theme-catalog/${themeId}`),
      {
        description: draft.description,
        pricingModel: draft.pricingModel,
        monthlyPrice: draft.monthlyPrice,
        yearlyPrice: draft.yearlyPrice,
        isActive: draft.isActive,
        isPublic: draft.isPublic,
        isFeatured: draft.isFeatured,
        imageUrl: draft.preview?.imageUrl,
      },
      {
        headers: getAuthHeaders(),
      },
    );
  };

  const handleSave = async (themeId: string) => {
    const draft = drafts[themeId];
    if (!draft || bulkSaving) return;

    try {
      setSavingThemeId(themeId);
      await persistThemeDraft(themeId, draft);
      toast.success("تم تحديث القالب بنجاح");
      onRefresh();
    } catch (error) {
      console.error("Theme catalog save error:", error);
      toast.error("فشل تحديث القالب");
    } finally {
      setSavingThemeId(null);
    }
  };

  const hiddenOrInactiveThemesCount = useMemo(
    () =>
      uniqueThemes.filter((theme) => {
        const draft = drafts[theme.themeId] || theme;
        return !draft.isActive || !draft.isPublic;
      }).length,
    [drafts, uniqueThemes],
  );

  const handleEnableAndShowAllThemes = async () => {
    if (uniqueThemes.length === 0 || bulkSaving) return;

    const nextDrafts = uniqueThemes.reduce<
      Record<string, StorefrontThemeCatalogItem>
    >((accumulator, theme) => {
      accumulator[theme.themeId] = {
        ...(drafts[theme.themeId] || theme),
        isActive: true,
        isPublic: true,
      };
      return accumulator;
    }, {});

    setDrafts(nextDrafts);
    setBulkSaving(true);

    try {
      const results = await Promise.allSettled(
        uniqueThemes.map((theme) =>
          persistThemeDraft(theme.themeId, nextDrafts[theme.themeId]),
        ),
      );
      const failedCount = results.filter(
        (result) => result.status === "rejected",
      ).length;

      if (failedCount > 0) {
        toast.error(`تعذر تحديث ${failedCount} قالب. راجع الشبكة ثم أعد المحاولة.`);
      } else {
        toast.success("تم إظهار وتفعيل كل القوالب");
      }

      onRefresh();
    } catch (error) {
      console.error("Bulk theme activation error:", error);
      toast.error("فشل إظهار وتفعيل القوالب");
    } finally {
      setBulkSaving(false);
    }
  };

  const totalPaidThemes = uniqueThemes.filter(
    (theme) => theme.pricingModel === "ONE_TIME" && theme.monthlyPrice > 0,
  ).length;

  return (
    <Box>
      <Paper
        sx={{
          p: 3,
          mb: 3,
          bgcolor: "info.light",
          color: "info.contrastText",
        }}
      >
        <Grid container spacing={3}>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {uniqueThemes.length}
            </Typography>
            <Typography variant="body2">إجمالي القوالب</Typography>
          </Grid>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {uniqueThemes.filter((theme) => theme.isActive).length}
            </Typography>
            <Typography variant="body2">قوالب متاحة للتفعيل</Typography>
          </Grid>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {uniqueThemes.filter((theme) => theme.isPublic).length}
            </Typography>
            <Typography variant="body2">ظاهرة للشركات</Typography>
          </Grid>
          <Grid size={{ xs: 6, md: 3 }}>
            <Typography variant="h4" fontWeight="bold">
              {totalPaidThemes}
            </Typography>
            <Typography variant="body2">قوالب مسعّرة</Typography>
          </Grid>
        </Grid>
      </Paper>

      <Box
        display="flex"
        justifyContent="space-between"
        alignItems={{ xs: "flex-start", md: "center" }}
        flexDirection={{ xs: "column", md: "row" }}
        gap={2}
        mb={3}
      >
        <Box>
          <Typography variant="h6">كتالوج قوالب المتجر</Typography>
          <Typography variant="body2" color="text.secondary">
            من هنا يتحكم السوبر أدمن في إتاحة القوالب وتسعيرها للشركات، بينما
            الشراء والتطبيق يتمان من صفحة القوالب داخل متجر التطبيقات.
          </Typography>
        </Box>
        <Button
          variant="outlined"
          startIcon={<RefreshIcon />}
          onClick={onRefresh}
          disabled={bulkSaving}
        >
          تحديث البيانات
        </Button>
        <Button
          variant="contained"
          color="success"
          startIcon={<CheckIcon />}
          onClick={handleEnableAndShowAllThemes}
          disabled={bulkSaving || uniqueThemes.length === 0}
        >
          {bulkSaving ? "جارٍ الإظهار والتفعيل..." : "إظهار وتفعيل كل القوالب"}
        </Button>
      </Box>

      {hiddenOrInactiveThemesCount > 0 ? (
        <Alert severity="warning" sx={{ mb: 3 }}>
          يوجد {hiddenOrInactiveThemesCount} قالب غير ظاهر للشركات أو غير متاح
          للتفعيل حاليًا. الزر الجماعي بالأعلى يعيدها كلها إلى حالة
          <strong> ظاهر + متاح للتفعيل </strong>
          دفعة واحدة.
        </Alert>
      ) : (
        <Alert severity="success" sx={{ mb: 3 }}>
          جميع القوالب الحالية ظاهرة للشركات ومتاحة للتفعيل.
        </Alert>
      )}

      <Grid container spacing={3}>
        {uniqueThemes.map((theme) => {
          const draft = drafts[theme.themeId] || theme;
          const isSaving = savingThemeId === theme.themeId || bulkSaving;
          const previewColors =
            draft.preview?.colors?.length > 0 ? draft.preview.colors : [];

          return (
            <Grid key={theme.themeId} size={{ xs: 12, lg: 6 }}>
              <Card sx={{ height: "100%", overflow: "hidden" }}>
                {draft.preview?.imageUrl && (
                  <Box
                    sx={{
                      height: 200,
                      width: "100%",
                      overflow: "hidden",
                      position: "relative",
                      borderBottom: "1px solid",
                      borderColor: "divider",
                      bgcolor: "action.hover",
                    }}
                  >
                    <img
                      src={draft.preview.imageUrl}
                      alt={draft.name}
                      style={{
                        width: "100%",
                        height: "100%",
                        objectFit: "cover",
                        objectPosition: "top center",
                      }}
                    />
                  </Box>
                )}
                <CardContent>
                  <Box
                    display="flex"
                    justifyContent="space-between"
                    alignItems="flex-start"
                    gap={2}
                    mb={2}
                  >
                    <Box>
                      <Typography variant="h6" fontWeight="bold">
                        {draft.name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {draft.themeId}
                      </Typography>
                    </Box>
                    <Box display="flex" gap={1} flexWrap="wrap">
                      {draft.isFeatured ? (
                        <Chip label="مميز" color="warning" size="small" />
                      ) : null}
                      <Chip
                        label={draft.isActive ? "نشط" : "موقوف"}
                        color={draft.isActive ? "success" : "default"}
                        size="small"
                      />
                    </Box>
                  </Box>

                  <Box display="flex" gap={1} mb={2}>
                    {previewColors.map((colorValue, colorIndex) => (
                      <Box
                        key={`${draft.themeId}-${colorValue}-${colorIndex}`}
                        sx={{
                          width: 28,
                          height: 28,
                          borderRadius: "999px",
                          border: "1px solid",
                          borderColor: "divider",
                          backgroundColor: `hsl(${colorValue})`,
                        }}
                      />
                    ))}
                  </Box>

                  <Grid container spacing={2} sx={{ mb: 2 }}>
                    <Grid size={{ xs: 12 }}>
                      <TextField
                        fullWidth
                        size="small"
                        label="رابط الصورة المعاينة (imageUrl)"
                        value={draft.preview?.imageUrl || ""}
                        onChange={(event) =>
                          handleDraftChange(theme.themeId, {
                            preview: {
                              ...draft.preview,
                              imageUrl: event.target.value,
                            },
                          })
                        }
                        sx={{ mb: 2 }}
                        helperText="يفضل استخدام مسار يبدأ بـ /assets/themes/..."
                      />
                    </Grid>
                    <Grid size={{ xs: 12 }}>
                      <TextField
                        fullWidth
                        size="small"
                        label="وصف القالب"
                        multiline
                        minRows={2}
                        value={draft.description}
                        onChange={(event) =>
                          handleDraftChange(theme.themeId, {
                            description: event.target.value,
                          })
                        }
                      />
                    </Grid>
                    <Grid size={{ xs: 12, md: 4 }}>
                      <FormControl fullWidth size="small">
                        <InputLabel id={`${theme.themeId}-pricing-model-label`}>
                          نموذج التسعير
                        </InputLabel>
                        <Select
                          labelId={`${theme.themeId}-pricing-model-label`}
                          label="نموذج التسعير"
                          value={draft.pricingModel}
                          onChange={(event) =>
                            handleDraftChange(theme.themeId, {
                              pricingModel:
                                event.target.value === "ONE_TIME"
                                  ? "ONE_TIME"
                                  : "FREE",
                              yearlyPrice:
                                event.target.value === "ONE_TIME"
                                  ? Number(draft.yearlyPrice) || 0
                                  : 0,
                            })
                          }
                        >
                          <MenuItem value="FREE">مجاني</MenuItem>
                          <MenuItem value="ONE_TIME">شراء مرة واحدة</MenuItem>
                        </Select>
                      </FormControl>
                    </Grid>
                    <Grid size={{ xs: 12, md: 4 }}>
                      <TextField
                        fullWidth
                        size="small"
                        type="number"
                        label="سعر الشراء"
                        value={draft.monthlyPrice}
                        onChange={(event) =>
                          handleDraftChange(theme.themeId, {
                            monthlyPrice: Number(event.target.value) || 0,
                          })
                        }
                        disabled={draft.pricingModel !== "ONE_TIME"}
                      />
                    </Grid>
                    <Grid size={{ xs: 12, md: 4 }}>
                      <TextField
                        fullWidth
                        size="small"
                        type="number"
                        label="السعر السنوي"
                        value={draft.yearlyPrice}
                        onChange={(event) =>
                          handleDraftChange(theme.themeId, {
                            yearlyPrice: Number(event.target.value) || 0,
                          })
                        }
                        disabled
                        helperText="غير مستخدم في شراء القوالب"
                      />
                    </Grid>
                  </Grid>

                  <Grid container spacing={1} sx={{ mb: 2 }}>
                    <Grid size={{ xs: 12, md: 4 }}>
                      <FormControlLabel
                        control={
                          <Switch
                            checked={draft.isActive}
                            onChange={(event) =>
                              handleDraftChange(theme.themeId, {
                                isActive: event.target.checked,
                              })
                            }
                          />
                        }
                        label="متاح للتفعيل"
                      />
                    </Grid>
                    <Grid size={{ xs: 12, md: 4 }}>
                      <FormControlLabel
                        control={
                          <Switch
                            checked={draft.isPublic}
                            onChange={(event) =>
                              handleDraftChange(theme.themeId, {
                                isPublic: event.target.checked,
                              })
                            }
                          />
                        }
                        label="ظاهر للشركات"
                      />
                    </Grid>
                    <Grid size={{ xs: 12, md: 4 }}>
                      <FormControlLabel
                        control={
                          <Switch
                            checked={draft.isFeatured}
                            onChange={(event) =>
                              handleDraftChange(theme.themeId, {
                                isFeatured: event.target.checked,
                              })
                            }
                          />
                        }
                        label="شارة مميز"
                      />
                    </Grid>
                  </Grid>

                  <Paper variant="outlined" sx={{ p: 2, mb: 2 }}>
                    <Grid container spacing={1}>
                      <Grid size={{ xs: 6 }}>
                        <Typography variant="caption" color="text.secondary">
                          الرئيسية
                        </Typography>
                        <Typography variant="subtitle2">
                          {draft.pageStats.homeSections} sections
                        </Typography>
                      </Grid>
                      <Grid size={{ xs: 6 }}>
                        <Typography variant="caption" color="text.secondary">
                          المتجر
                        </Typography>
                        <Typography variant="subtitle2">
                          {draft.pageStats.shopSections} sections
                        </Typography>
                      </Grid>
                      <Grid size={{ xs: 6 }}>
                        <Typography variant="caption" color="text.secondary">
                          المنتج
                        </Typography>
                        <Typography variant="subtitle2">
                          {draft.pageStats.pdpSections} sections
                        </Typography>
                      </Grid>
                      <Grid size={{ xs: 6 }}>
                        <Typography variant="caption" color="text.secondary">
                          السلة/الدفع
                        </Typography>
                        <Typography variant="subtitle2">
                          {draft.pageStats.cartSections +
                            draft.pageStats.checkoutSections}{" "}
                          sections
                        </Typography>
                      </Grid>
                    </Grid>
                  </Paper>

                  <Box display="flex" justifyContent="flex-end">
                    <Button
                      variant="contained"
                      startIcon={<SaveIcon />}
                      onClick={() => handleSave(theme.themeId)}
                      disabled={isSaving}
                    >
                      {isSaving ? "جاري الحفظ..." : "حفظ القالب"}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          );
        })}
      </Grid>
    </Box>
  );
};

const MarketplaceItemDialog = ({
  open,
  onClose,
  item,
  type,
  onSave,
}: {
  open: boolean;
  onClose: () => void;
  item: any;
  type: string;
  onSave: (data: any) => void;
}) => {
  const [formData, setFormData] = useState<any>({});

  const categoryMap = [
    { id: "ECOMMERCE", name: "التجارة الإلكترونية" },
    { id: "HR", name: "الموارد البشرية" },
    { id: "AI", name: "الذكاء الاصطناعي" },
    { id: "COMMUNICATION", name: "التواصل" },
    { id: "CRM", name: "إدارة العملاء" },
    { id: "ANALYTICS", name: "التحليلات" },
    { id: "INTEGRATION", name: "التكاملات" },
    { id: "PRODUCTIVITY", name: "الإنتاجية" },
    { id: "FINANCE", name: "المالية" },
    { id: "MARKETING", name: "التسويق" },
  ];

  useEffect(() => {
    if (item) {
      setFormData({ ...item });
    } else {
      setFormData({
        name: "",
        slug: "",
        description: "",
        monthlyPrice: 0,
        yearlyPrice: 0,
        trialDays: 14,
        category: "ECOMMERCE",
        isActive: true,
        isPublic: true,
        isFeatured: false,
        isPopular: false,
        logo: "",
        icon: "",
        mainRoute: "",
        adminRoute: "",
        pricingModel: "SUBSCRIPTION",
        unitPrice: 0,
        unitName: "",
        ...(type === "pricing" ? { feature: "", price: 0, unit: "" } : {}),
        ...(type === "bundle" ? { discount: 0, apps: [] } : {}),
      });
    }
  }, [item, open, type]);

  const handleChange = (e: any) => {
    const { name, value, type: inputType, checked } = e.target;
    setFormData((prev: any) => ({
      ...prev,
      [name]:
        inputType === "checkbox"
          ? checked
          : inputType === "number"
            ? parseFloat(value)
            : value,
    }));
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>
        {item ? "تعديل" : "إضافة"}{" "}
        {type === "app" ? "تطبيق" : type === "pricing" ? "قاعدة تسعير" : "باقة"}
      </DialogTitle>
      <DialogContent dividers>
        <Grid container spacing={2} sx={{ mt: 1 }}>
          {type === "pricing" ? (
            <>
              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="الميزة"
                  name="feature"
                  value={formData.feature || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 6 }}>
                <TextField
                  fullWidth
                  label="السعر"
                  name="price"
                  type="number"
                  value={formData.price || 0}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 6 }}>
                <TextField
                  fullWidth
                  label="الوحدة"
                  name="unit"
                  value={formData.unit || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <Box display="flex" gap={3}>
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      نشط:
                    </Typography>
                    <input
                      type="checkbox"
                      name="isActive"
                      checked={!!formData.isActive}
                      onChange={handleChange}
                    />
                  </Box>
                </Box>
              </Grid>
            </>
          ) : type === "enterprise" ? (
            <>
              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="معرف الشركة (Company ID)"
                  name="companyId"
                  value={formData.companyId || ""}
                  onChange={handleChange}
                  disabled={!!item}
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="اسم الخطة"
                  name="name"
                  value={formData.name || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="السعر"
                  name="price"
                  type="number"
                  value={formData.price || 0}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="الوصف"
                  name="description"
                  multiline
                  rows={3}
                  value={formData.description || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <Box display="flex" gap={3}>
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      نشط:
                    </Typography>
                    <input
                      type="checkbox"
                      name="isActive"
                      checked={!!formData.isActive}
                      onChange={handleChange}
                    />
                  </Box>
                </Box>
              </Grid>
            </>
          ) : type === "bundle" ? (
            <>
              <Grid size={{ xs: 12, md: 6 }}>
                <TextField
                  fullWidth
                  label="الاسم"
                  name="name"
                  value={formData.name || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12, md: 6 }}>
                <TextField
                  fullWidth
                  label="Slug"
                  name="slug"
                  value={formData.slug || ""}
                  onChange={handleChange}
                  placeholder="اتركه فارغاً للتوليد التلقائي"
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="الوصف"
                  name="description"
                  multiline
                  rows={3}
                  value={formData.description || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 6, md: 4 }}>
                <TextField
                  fullWidth
                  label="السعر الشهري"
                  name="monthlyPrice"
                  type="number"
                  value={formData.monthlyPrice || 0}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 6, md: 4 }}>
                <TextField
                  fullWidth
                  label="الخصم %"
                  name="discount"
                  type="number"
                  value={formData.discount || 0}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12, md: 4 }}>
                <Box
                  display="flex"
                  gap={2}
                  sx={{ height: "100%", alignItems: "center" }}
                >
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      نشط:
                    </Typography>
                    <input
                      type="checkbox"
                      name="isActive"
                      checked={!!formData.isActive}
                      onChange={handleChange}
                    />
                  </Box>
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      مميز:
                    </Typography>
                    <input
                      type="checkbox"
                      name="isFeatured"
                      checked={!!formData.isFeatured}
                      onChange={handleChange}
                    />
                  </Box>
                </Box>
              </Grid>
            </>
          ) : (
            <>
              <Grid size={{ xs: 12, md: 6 }}>
                <TextField
                  fullWidth
                  label="الاسم"
                  name="name"
                  value={formData.name || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12, md: 6 }}>
                <TextField
                  fullWidth
                  label="Slug"
                  name="slug"
                  value={formData.slug || ""}
                  onChange={handleChange}
                  placeholder="اتركه فارغاً للتوليد التلقائي"
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="الوصف"
                  name="description"
                  multiline
                  rows={2}
                  value={formData.description || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12, md: 6 }}>
                <FormControl fullWidth>
                  <InputLabel id="category-label">الفئة</InputLabel>
                  <Select
                    labelId="category-label"
                    label="الفئة"
                    name="category"
                    value={formData.category || "ECOMMERCE"}
                    onChange={handleChange}
                  >
                    {categoryMap.map((cat) => (
                      <MenuItem key={cat.id} value={cat.id}>
                        {cat.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 6, md: 3 }}>
                <TextField
                  fullWidth
                  label="السعر الشهري"
                  name="monthlyPrice"
                  type="number"
                  value={formData.monthlyPrice || 0}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 6, md: 3 }}>
                <TextField
                  fullWidth
                  label="أيام التجربة"
                  name="trialDays"
                  type="number"
                  value={formData.trialDays || 14}
                  onChange={handleChange}
                />
              </Grid>

              <Grid size={{ xs: 12, md: 4 }}>
                <TextField
                  fullWidth
                  label="الأيقونة (Emoji or Icon Name)"
                  name="icon"
                  value={formData.icon || ""}
                  onChange={handleChange}
                />
              </Grid>
              <Grid size={{ xs: 12, md: 2 }}>
                <Box display="flex" alignItems="center" sx={{ height: "100%" }}>
                  <Typography variant="body2" sx={{ mr: 1 }}>
                    تثبيت تلقائي:
                  </Typography>
                  <input
                    type="checkbox"
                    name="isAutoInstall"
                    checked={!!formData.isAutoInstall}
                    onChange={handleChange}
                  />
                </Box>
              </Grid>
              <Grid size={{ xs: 12, md: 6 }}>
                <TextField
                  fullWidth
                  label="رابط اللوجو (URL)"
                  name="logo"
                  value={formData.logo || ""}
                  onChange={handleChange}
                />
              </Grid>

              <Grid size={{ xs: 12, md: 4 }}>
                <FormControl fullWidth>
                  <InputLabel id="pricing-model-label">نظام التسعير</InputLabel>
                  <Select
                    labelId="pricing-model-label"
                    label="نظام التسعير"
                    name="pricingModel"
                    value={formData.pricingModel || "SUBSCRIPTION"}
                    onChange={handleChange}
                  >
                    <MenuItem value="FREE">مجاني</MenuItem>
                    <MenuItem value="SUBSCRIPTION">اشتراك شهري/سنوي</MenuItem>
                    <MenuItem value="PAY_PER_USE">حسب الاستخدام (PPU)</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 6, md: 4 }}>
                <TextField
                  fullWidth
                  label="سعر الوحدة (لـ PPU)"
                  name="unitPrice"
                  type="number"
                  value={formData.unitPrice || 0}
                  onChange={handleChange}
                  disabled={formData.pricingModel !== "PAY_PER_USE"}
                />
              </Grid>
              <Grid size={{ xs: 6, md: 4 }}>
                <TextField
                  fullWidth
                  label="اسم الوحدة (لـ PPU)"
                  name="unitName"
                  value={formData.unitName || ""}
                  onChange={handleChange}
                  disabled={formData.pricingModel !== "PAY_PER_USE"}
                  placeholder="مثال: رسالة، موظف"
                />
              </Grid>

              <Grid size={{ xs: 12, md: 6 }}>
                <TextField
                  fullWidth
                  label="المسار الرئيسي (Main Route)"
                  name="mainRoute"
                  value={formData.mainRoute || ""}
                  onChange={handleChange}
                  placeholder="/my-apps/something"
                />
              </Grid>
              <Grid size={{ xs: 12, md: 6 }}>
                <TextField
                  fullWidth
                  label="مسار الإدارة (Admin Route)"
                  name="adminRoute"
                  value={formData.adminRoute || ""}
                  onChange={handleChange}
                  placeholder="/settings/something"
                />
              </Grid>

              <Grid size={{ xs: 12 }}>
                <TextField
                  fullWidth
                  label="الأدوات والمميزات (Tools Included)"
                  name="features"
                  multiline
                  rows={3}
                  value={
                    Array.isArray(formData.features)
                      ? formData.features.join(", ")
                      : formData.features || ""
                  }
                  onChange={(e) => {
                    const val = e.target.value;
                    setFormData((prev: any) => ({
                      ...prev,
                      features: val
                        .split(",")
                        .map((s) => s.trim())
                        .filter(Boolean),
                    }));
                  }}
                  placeholder="افصل بين كل ميزة بفاصلة (،) .. مثال: نظام تقارير، ربط واتساب، دعم فني"
                  helperText="افصل بين الأدوات بفاصلة لكي تظهر كنقاط منفصلة للمستخدم"
                />
              </Grid>

              <Grid size={{ xs: 12 }}>
                <Box display="flex" gap={3} flexWrap="wrap">
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      نشط:
                    </Typography>
                    <input
                      type="checkbox"
                      name="isActive"
                      checked={!!formData.isActive}
                      onChange={handleChange}
                    />
                  </Box>
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      عام (Public):
                    </Typography>
                    <input
                      type="checkbox"
                      name="isPublic"
                      checked={!!formData.isPublic}
                      onChange={handleChange}
                    />
                  </Box>
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      مميز (Featured):
                    </Typography>
                    <input
                      type="checkbox"
                      name="isFeatured"
                      checked={!!formData.isFeatured}
                      onChange={handleChange}
                    />
                  </Box>
                  <Box display="flex" alignItems="center">
                    <Typography variant="body2" sx={{ mr: 1 }}>
                      شائع (Popular):
                    </Typography>
                    <input
                      type="checkbox"
                      name="isPopular"
                      checked={!!formData.isPopular}
                      onChange={handleChange}
                    />
                  </Box>
                </Box>
              </Grid>
            </>
          )}
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>إلغاء</Button>
        <Button variant="contained" onClick={() => onSave(formData)}>
          حفظ
        </Button>
      </DialogActions>
    </Dialog>
  );
};

const EditPlanDialog = ({
  open,
  onClose,
  plan,
  onSave,
}: {
  open: boolean;
  onClose: () => void;
  plan: any;
  onSave: (data: any) => void;
}) => {
  const [formData, setFormData] = useState({
    planType: "",
    name: "",
    nameEn: "",
    price: 0,
    currency: "EGP",
    billingCycle: "monthly",
    description: "",
    descriptionEn: "",
    features: {
      maxUsers: 5,
      maxCustomers: 1000,
      maxConversations: 5000,
      maxMessages: 50000,
      aiResponses: 1000,
      customBranding: false,
      advancedReports: false,
      apiAccess: false,
      prioritySupport: false,
      customIntegrations: false,
      whatsappBusiness: true,
      facebookMessenger: true,
      webChat: true,
      mobileApp: false,
      multiLanguage: false,
      customFields: 10,
      automatedWorkflows: 5,
      dataRetention: 90,
      storageLimit: 1,
      exportData: false,
      dedicatedSupport: false,
      customDevelopment: false,
      onPremiseDeployment: false,
      sla: "",
    },
  });
  const [activeTab, setActiveTab] = useState(0);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  const billingCycles = [
    { value: "monthly", label: "شهري" },
    { value: "quarterly", label: "ربع سنوي" },
    { value: "yearly", label: "سنوي" },
  ];

  const currencies = [
    { value: "EGP", label: "جنيه مصري (EGP)" },
    { value: "USD", label: "دولار أمريكي (USD)" },
    { value: "SAR", label: "ريال سعودي (SAR)" },
    { value: "AED", label: "درهم إماراتي (AED)" },
  ];

  useEffect(() => {
    if (plan) {
      const features =
        typeof plan.features === "string"
          ? JSON.parse(plan.features)
          : plan.features || {};

      setFormData({
        planType: plan.planType || "",
        name: plan.name || "",
        nameEn: plan.nameEn || "",
        price: plan.price || 0,
        currency: plan.currency || "EGP",
        billingCycle: plan.billingCycle || "monthly",
        description: plan.description || "",
        descriptionEn: plan.descriptionEn || "",
        features: {
          ...formData.features,
          ...features,
        },
      });
    } else {
      // Reset for new plan
      setFormData({
        planType: "",
        name: "",
        nameEn: "",
        price: 0,
        currency: "EGP",
        billingCycle: "monthly",
        description: "",
        descriptionEn: "",
        features: {
          maxUsers: 5,
          maxCustomers: 1000,
          maxConversations: 5000,
          maxMessages: 50000,
          aiResponses: 1000,
          customBranding: false,
          advancedReports: false,
          apiAccess: false,
          prioritySupport: false,
          customIntegrations: false,
          whatsappBusiness: true,
          facebookMessenger: true,
          webChat: true,
          mobileApp: false,
          multiLanguage: false,
          customFields: 10,
          automatedWorkflows: 5,
          dataRetention: 90,
          storageLimit: 1,
          exportData: false,
          dedicatedSupport: false,
          customDevelopment: false,
          onPremiseDeployment: false,
          sla: "99.9%",
        },
      });
    }
    setActiveTab(0);
    setErrors({});
  }, [plan, open]);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    // Clear error when field is edited
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: "" }));
    }
  };

  const handleFeatureChange = (featureKey: string, value: any) => {
    setFormData((prev) => ({
      ...prev,
      features: {
        ...prev.features,
        [featureKey]: value,
      },
    }));
  };

  const validate = () => {
    const newErrors: { [key: string]: string } = {};

    if (!formData.planType.trim()) {
      newErrors.planType = "نوع الخطة مطلوب";
    }
    if (!formData.name.trim()) {
      newErrors.name = "اسم الخطة مطلوب";
    }
    if (formData.price < 0) {
      newErrors.price = "السعر يجب أن يكون 0 أو أكثر";
    }
    if (formData.features.maxUsers < -1) {
      newErrors.maxUsers = "الحد الأقصى للمستخدمين غير صالح (-1 للغير محدود)";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = () => {
    if (!validate()) return;

    const dataToSave = {
      ...formData,
      features: JSON.stringify(formData.features),
    };
    onSave(dataToSave);
  };

  const formatFeatureValue = (value: any) => {
    if (value === -1 || value === true) return "✓";
    if (
      value === false ||
      value === undefined ||
      value === null ||
      value === ""
    )
      return "✗";
    return value;
  };

  const numericFeatures = [
    {
      key: "maxUsers",
      label: "الحد الأقصى للمستخدمين",
      helper: "-1 للغير محدود",
    },
    {
      key: "maxCustomers",
      label: "الحد الأقصى للعملاء",
      helper: "-1 للغير محدود",
    },
    {
      key: "maxConversations",
      label: "الحد الأقصى للمحادثات",
      helper: "-1 للغير محدود",
    },
    {
      key: "maxMessages",
      label: "الحد الأقصى للرسائل",
      helper: "-1 للغير محدود",
    },
    {
      key: "aiResponses",
      label: "ردود الذكاء الاصطناعي",
      helper: "-1 للغير محدود",
    },
    { key: "customFields", label: "الحقول المخصصة", helper: "-1 للغير محدود" },
    {
      key: "automatedWorkflows",
      label: "سير العمل التلقائي",
      helper: "-1 للغير محدود",
    },
    {
      key: "dataRetention",
      label: "الاحتفاظ بالبيانات (أيام)",
      helper: "-1 للغير محدود",
    },
    { key: "storageLimit", label: "حد التخزين (GB)", helper: "-1 للغير محدود" },
  ];

  const booleanFeatures = [
    { key: "customBranding", label: "العلامة التجارية المخصصة" },
    { key: "advancedReports", label: "التقارير المتقدمة" },
    { key: "apiAccess", label: "الوصول للـ API" },
    { key: "prioritySupport", label: "الدعم ذو الأولوية" },
    { key: "customIntegrations", label: "التكاملات المخصصة" },
    { key: "whatsappBusiness", label: "واتساب بزنس" },
    { key: "facebookMessenger", label: "فيسبوك ماسنجر" },
    { key: "webChat", label: "الدردشة على الموقع" },
    { key: "mobileApp", label: "تطبيق الجوال" },
    { key: "multiLanguage", label: "متعدد اللغات" },
    { key: "exportData", label: "تصدير البيانات" },
    { key: "dedicatedSupport", label: "دعم مخصص" },
    { key: "customDevelopment", label: "تطوير مخصص" },
    { key: "onPremiseDeployment", label: "النشر المحلي" },
  ];

  return (
    <Dialog open={open} onClose={onClose} maxWidth="lg" fullWidth>
      <DialogTitle sx={{ pb: 1 }}>
        <Box display="flex" alignItems="center" gap={2}>
          {plan ? <EditIcon color="primary" /> : <AddIcon color="success" />}
          <Typography variant="h6">
            {plan ? `تعديل خطة ${plan.name}` : "إنشاء خطة جديدة"}
          </Typography>
        </Box>
      </DialogTitle>

      <Tabs
        value={activeTab}
        onChange={(e, v) => setActiveTab(v)}
        sx={{ px: 3, borderBottom: 1, borderColor: "divider" }}
      >
        <Tab label="المعلومات الأساسية" />
        <Tab label="الحدود والأرقام" />
        <Tab label="المميزات المتقدمة" />
        <Tab label="معاينة" />
      </Tabs>

      <DialogContent sx={{ pt: 3 }}>
        {/* Tab 1: Basic Info */}
        {activeTab === 0 && (
          <Grid container spacing={3}>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="نوع الخطة (Plan Type) *"
                name="planType"
                value={formData.planType}
                onChange={handleChange}
                disabled={!!plan}
                error={!!errors.planType}
                helperText={
                  errors.planType ||
                  (plan
                    ? "لا يمكن تغيير نوع الخطة"
                    : "مثال: BASIC, PRO, ENTERPRISE أو CUSTOM1")
                }
                placeholder="مثال: PRO"
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="الاسم (العربية) *"
                name="name"
                value={formData.name}
                onChange={handleChange}
                error={!!errors.name}
                helperText={errors.name}
                placeholder="الخطة الاحترافية"
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="الاسم (English)"
                name="nameEn"
                value={formData.nameEn}
                onChange={handleChange}
                placeholder="Professional Plan"
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <TextField
                fullWidth
                label="السعر *"
                name="price"
                type="number"
                value={formData.price}
                onChange={handleChange}
                error={!!errors.price}
                helperText={errors.price}
                InputProps={{
                  startAdornment: (
                    <Typography sx={{ mr: 1, color: "text.secondary" }}>
                      {formData.currency}
                    </Typography>
                  ),
                }}
              />
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl fullWidth>
                <InputLabel>العملة</InputLabel>
                <Select
                  name="currency"
                  value={formData.currency}
                  label="العملة"
                  onChange={(e) =>
                    handleChange({
                      target: { name: "currency", value: e.target.value },
                    } as any)
                  }
                >
                  {currencies.map((c) => (
                    <MenuItem key={c.value} value={c.value}>
                      {c.label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, md: 6 }}>
              <FormControl fullWidth>
                <InputLabel>دورة الفوترة</InputLabel>
                <Select
                  name="billingCycle"
                  value={formData.billingCycle}
                  label="دورة الفوترة"
                  onChange={(e) =>
                    handleChange({
                      target: { name: "billingCycle", value: e.target.value },
                    } as any)
                  }
                >
                  {billingCycles.map((b) => (
                    <MenuItem key={b.value} value={b.value}>
                      {b.label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12 }}>
              <TextField
                fullWidth
                label="وصف الخطة (عربي)"
                name="description"
                multiline
                rows={2}
                value={formData.description}
                onChange={handleChange}
                placeholder="وصف مختصر للخطة ومميزاتها الرئيسية"
              />
            </Grid>
            <Grid size={{ xs: 12 }}>
              <TextField
                fullWidth
                label="الوصف (English)"
                name="descriptionEn"
                multiline
                rows={2}
                value={formData.descriptionEn}
                onChange={handleChange}
                placeholder="Brief description of the plan"
              />
            </Grid>
          </Grid>
        )}

        {/* Tab 2: Numeric Limits */}
        {activeTab === 1 && (
          <Grid container spacing={2}>
            <Grid size={{ xs: 12 }}>
              <Alert severity="info" sx={{ mb: 2 }}>
                أدخل -1 للقيم غير المحدودة. القيم تُحسب بالشهر ما عدا
                dataRetention (أيام).
              </Alert>
            </Grid>
            {numericFeatures.map((feature) => (
              <Grid key={feature.key} size={{ xs: 12, sm: 6, md: 4 }}>
                <TextField
                  fullWidth
                  type="number"
                  label={feature.label}
                  value={formData.features[feature.key]}
                  onChange={(e) =>
                    handleFeatureChange(
                      feature.key,
                      parseInt(e.target.value) || 0,
                    )
                  }
                  helperText={feature.helper}
                  size="small"
                />
              </Grid>
            ))}
          </Grid>
        )}

        {/* Tab 3: Boolean Features */}
        {activeTab === 2 && (
          <Grid container spacing={2}>
            <Grid size={{ xs: 12 }}>
              <Alert severity="info" sx={{ mb: 2 }}>
                مميزات إضافية متوفرة في هذه الخطة.
              </Alert>
            </Grid>
            {booleanFeatures.map((feature) => (
              <Grid key={feature.key} size={{ xs: 12, sm: 6, md: 4 }}>
                <Paper
                  sx={{
                    p: 2,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    bgcolor: formData.features[feature.key]
                      ? "success.light"
                      : "background.paper",
                    border: 1,
                    borderColor: formData.features[feature.key]
                      ? "success.main"
                      : "divider",
                  }}
                >
                  <Typography
                    variant="body2"
                    fontWeight={formData.features[feature.key] ? 600 : 400}
                  >
                    {feature.label}
                  </Typography>
                  <input
                    type="checkbox"
                    checked={!!formData.features[feature.key]}
                    onChange={(e) =>
                      handleFeatureChange(feature.key, e.target.checked)
                    }
                    style={{ width: 20, height: 20, cursor: "pointer" }}
                  />
                </Paper>
              </Grid>
            ))}
            <Grid size={{ xs: 12, md: 4 }}>
              <TextField
                fullWidth
                label="اتفاقية مستوى الخدمة (SLA)"
                value={formData.features.sla || ""}
                onChange={(e) => handleFeatureChange("sla", e.target.value)}
                placeholder="99.9%"
                helperText="مثال: 99.9%"
                size="small"
              />
            </Grid>
          </Grid>
        )}

        {/* Tab 4: Preview */}
        {activeTab === 3 && (
          <Box>
            <Paper
              sx={{
                p: 3,
                mb: 3,
                bgcolor: "primary.light",
                color: "primary.contrastText",
              }}
            >
              <Typography variant="h4" fontWeight="bold">
                {formData.name || "اسم الخطة"}
              </Typography>
              <Typography variant="h5" sx={{ mt: 1 }}>
                {formData.price} {formData.currency} /
                {
                  billingCycles.find((b) => b.value === formData.billingCycle)
                    ?.label
                }
              </Typography>
              <Typography variant="body1" sx={{ mt: 1, opacity: 0.9 }}>
                {formData.description || "لا يوجد وصف"}
              </Typography>
            </Paper>

            <Typography variant="h6" gutterBottom>
              ملخص المميزات:
            </Typography>
            <Grid container spacing={1}>
              {numericFeatures.map((f) => (
                <Grid key={f.key} size={{ xs: 12, sm: 6 }}>
                  <Chip
                    label={`${f.label}: ${formatFeatureValue(formData.features[f.key])}`}
                    color={
                      formData.features[f.key] === -1 ? "success" : "default"
                    }
                    size="small"
                    sx={{ width: "100%", justifyContent: "flex-start" }}
                  />
                </Grid>
              ))}
              {booleanFeatures.map((f) => (
                <Grid key={f.key} size={{ xs: 12, sm: 6 }}>
                  <Chip
                    icon={
                      formData.features[f.key] ? <CheckIcon /> : <CloseIcon />
                    }
                    label={f.label}
                    color={formData.features[f.key] ? "success" : "default"}
                    variant={formData.features[f.key] ? "filled" : "outlined"}
                    size="small"
                    sx={{ width: "100%", justifyContent: "flex-start" }}
                  />
                </Grid>
              ))}
            </Grid>
          </Box>
        )}
      </DialogContent>

      <DialogActions sx={{ px: 3, py: 2 }}>
        <Button onClick={onClose} variant="outlined">
          إلغاء
        </Button>
        <Button
          variant="contained"
          onClick={handleSave}
          startIcon={plan ? <SaveIcon /> : <AddIcon />}
          disabled={Object.keys(errors).length > 0 && activeTab === 0}
        >
          {plan ? "حفظ التغييرات" : "إنشاء الخطة"}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default SubscriptionCenter;

import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  CircularProgress,
  Alert,
  Stack,
  alpha,
  useTheme as useMuiTheme,
  IconButton,
  LinearProgress,
  Paper,
  Divider,
  Tooltip,
} from "@mui/material";
import {
  Storage as StorageIcon,
  Refresh as RefreshIcon,
  PieChart as PieChartIcon,
  InfoOutlined as InfoIcon,
  Dns as DnsIcon,
  CloudQueue as CloudIcon,
  Memory as MemoryIcon,
  Speed as SpeedIcon,
  SettingsSuggest as SystemIcon,
  BarChart as BarChartIcon,
  Image as ImageIcon,
  Videocam as VideoIcon,
  Audiotrack as AudioIcon,
  Description as DocIcon,
  MoreHoriz as OtherIcon,
} from "@mui/icons-material";
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  Tooltip as RechartsTooltip,
  Legend,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
} from "recharts";
import { motion, AnimatePresence } from "framer-motion";
import { apiClient } from "../../services/apiClient";

const formatSize = (bytes: number) => {
  if (bytes === 0 || !bytes) return "0 Bytes";
  const k = 1024;
  const sizes = ["Bytes", "KB", "MB", "GB", "TB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
};

interface DiskStats {
  total: number;
  used: number;
  free: number;
  usagePercent: number;
  breakdown: {
    images: number;
    videos: number;
    audio: number;
    documents: number;
    other: number;
  };
  platform: string;
  timestamp: string;
}

const SuperAdminServerUsage = () => {
  const muiTheme = useMuiTheme();
  const isDark = muiTheme.palette.mode === "dark";

  const [stats, setStats] = useState<DiskStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await apiClient.get("/super-admin/server-usage");

      if (response.status === 200 && response.data.success) {
        setStats(response.data.data);
      } else {
        setError(response.data.message || "فشل في جلب إحصائيات السيرفر");
      }
    } catch (err: any) {
      console.error("Error fetching server usage:", err);
      setError("حدث خطأ أثناء الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (percent: number) => {
    if (percent < 60) return muiTheme.palette.success.main;
    if (percent < 80) return muiTheme.palette.warning.main;
    if (percent < 90) return "#f97316"; // Orange
    return muiTheme.palette.error.main;
  };

  if (loading && !stats) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="60vh"
      >
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ repeat: Infinity, duration: 1, ease: "linear" }}
        >
          <CircularProgress size={60} thickness={4} />
        </motion.div>
      </Box>
    );
  }

  const chartData = stats
    ? [
        {
          name: "المساحة المستخدمة",
          value: stats.used,
          color: getStatusColor(stats.usagePercent),
        },
        {
          name: "المساحة الفارغة",
          value: stats.free,
          color: isDark ? alpha("#fff", 0.1) : "#f1f5f9",
        },
      ]
    : [];

  const breakdownData = stats?.breakdown
    ? [
        {
          name: "الصور",
          value: stats.breakdown.images,
          color: "#3b82f6",
          icon: <ImageIcon />,
        },
        {
          name: "الفيديوهات",
          value: stats.breakdown.videos,
          color: "#ef4444",
          icon: <VideoIcon />,
        },
        {
          name: "الصوتيات",
          value: stats.breakdown.audio,
          color: "#8b5cf6",
          icon: <AudioIcon />,
        },
        {
          name: "المستندات",
          value: stats.breakdown.documents,
          color: "#fbbf24",
          icon: <DocIcon />,
        },
        {
          name: "أخرى / النظام",
          value: stats.breakdown.other,
          color: "#94a3b8",
          icon: <OtherIcon />,
        },
      ]
    : [];

  const cardVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: (i: number) => ({
      opacity: 1,
      y: 0,
      transition: { delay: i * 0.1, duration: 0.5, ease: "easeOut" },
    }),
  };

  return (
    <Box
      sx={{
        p: { xs: 2, md: 4 },
        direction: "rtl",
        minHeight: "100%",
        background: isDark
          ? "radial-gradient(circle at top right, rgba(30, 41, 59, 0.5), transparent), radial-gradient(circle at bottom left, rgba(15, 23, 42, 0.5), transparent)"
          : "radial-gradient(circle at top right, rgba(59, 130, 246, 0.05), transparent)",
      }}
    >
      {/* Header */}
      <Stack
        direction="row"
        justifyContent="space-between"
        alignItems="center"
        mb={4}
      >
        <Box>
          <Typography
            variant="h3"
            sx={{
              fontWeight: 900,
              letterSpacing: "-0.02em",
              background: "linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              mb: 0.5,
            }}
          >
            تحليل استهلاك القرص
          </Typography>
          <Typography
            variant="body1"
            sx={{ color: isDark ? "#94a3b8" : "#64748b", fontWeight: 500 }}
          >
            مراقبة حية وتفصيلية لموارد التخزين
          </Typography>
        </Box>
        <Tooltip title="تحديث البيانات">
          <IconButton
            onClick={fetchStats}
            sx={{
              p: 2,
              bgcolor: isDark ? alpha("#3b82f6", 0.1) : alpha("#3b82f6", 0.05),
              color: "#3b82f6",
              border: "1px solid",
              borderColor: alpha("#3b82f6", 0.2),
              "&:hover": {
                bgcolor: "#3b82f6",
                color: "#fff",
                transform: "rotate(180deg)",
                transition: "all 0.5s cubic-bezier(0.4, 0, 0.2, 1)",
              },
            }}
          >
            <RefreshIcon />
          </IconButton>
        </Tooltip>
      </Stack>

      {error && (
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
        >
          <Alert
            severity="error"
            variant="filled"
            sx={{
              mb: 4,
              borderRadius: 3,
              boxShadow: "0 4px 12px rgba(239, 68, 68, 0.2)",
            }}
          >
            {error}
          </Alert>
        </motion.div>
      )}

      {stats && (
        <Grid container spacing={3}>
          {/* Main Overwiew Component */}
          <Grid size={{ xs: 12, lg: 4 }}>
            <motion.div
              custom={0}
              initial="hidden"
              animate="visible"
              variants={cardVariants}
            >
              <Card
                sx={{
                  height: "100%",
                  borderRadius: 5,
                  border: "1px solid",
                  borderColor: isDark
                    ? alpha("#fff", 0.08)
                    : alpha("#000", 0.05),
                  bgcolor: isDark ? alpha("#1e293b", 0.6) : "#fff",
                  backdropFilter: "blur(20px)",
                  boxShadow: isDark
                    ? "0 10px 30px -10px rgba(0,0,0,0.5)"
                    : "0 10px 30px -10px rgba(0,0,0,0.05)",
                  overflow: "hidden",
                }}
              >
                <CardContent sx={{ p: 4 }}>
                  <Stack
                    direction="row"
                    justifyContent="space-between"
                    alignItems="center"
                    mb={3}
                  >
                    <Typography
                      variant="h6"
                      sx={{
                        fontWeight: 800,
                        display: "flex",
                        alignItems: "center",
                        gap: 1.5,
                      }}
                    >
                      <PieChartIcon sx={{ color: "#3b82f6" }} /> نظرة عامة
                    </Typography>
                  </Stack>

                  <Box
                    sx={{ minHeight: 280, width: "100%", position: "relative" }}
                  >
                    <ResponsiveContainer
                      width="100%"
                      height={280}
                      minWidth={0}
                      minHeight={280}
                    >
                      <PieChart>
                        <Pie
                          data={chartData}
                          cx="50%"
                          cy="50%"
                          innerRadius={80}
                          outerRadius={100}
                          stroke="none"
                          paddingAngle={8}
                          dataKey="value"
                          startAngle={90}
                          endAngle={-270}
                        >
                          {chartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={entry.color} />
                          ))}
                        </Pie>
                      </PieChart>
                    </ResponsiveContainer>

                    {/* Center Content */}
                    <Box
                      sx={{
                        position: "absolute",
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%, -50%)",
                        textAlign: "center",
                        width: "100%",
                      }}
                    >
                      <motion.div
                        initial={{ opacity: 0, scale: 0.5 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ delay: 0.5 }}
                      >
                        <Typography
                          variant="h3"
                          sx={{
                            fontWeight: 900,
                            color: getStatusColor(stats.usagePercent),
                            lineHeight: 1,
                          }}
                        >
                          {stats.usagePercent}%
                        </Typography>
                        <Typography
                          variant="caption"
                          sx={{
                            color: isDark ? "#64748b" : "#94a3b8",
                            fontWeight: 600,
                            display: "block",
                            mt: 0.5,
                          }}
                        >
                          نسبة الاستهلاك
                        </Typography>
                      </motion.div>
                    </Box>
                  </Box>

                  <Stack
                    direction="row"
                    spacing={3}
                    justifyContent="center"
                    mt={3}
                  >
                    <Box sx={{ textAlign: "center" }}>
                      <Typography variant="h6" sx={{ fontWeight: 800 }}>
                        {formatSize(stats.used)}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        المستخدم
                      </Typography>
                    </Box>
                    <Divider
                      orientation="vertical"
                      flexItem
                      sx={{ height: 40 }}
                    />
                    <Box sx={{ textAlign: "center" }}>
                      <Typography
                        variant="h6"
                        sx={{ fontWeight: 800, color: "#10b981" }}
                      >
                        {formatSize(stats.free)}
                      </Typography>
                      <Typography
                        variant="caption"
                        color="text.secondary"
                        sx={{ color: "#10b981" }}
                      >
                        المتاح
                      </Typography>
                    </Box>
                  </Stack>
                </CardContent>
              </Card>
            </motion.div>
          </Grid>

          {/* Detailed Breakdown Component */}
          <Grid size={{ xs: 12, lg: 8 }}>
            <motion.div
              custom={1}
              initial="hidden"
              animate="visible"
              variants={cardVariants}
            >
              <Card
                sx={{
                  height: "100%",
                  borderRadius: 5,
                  border: "1px solid",
                  borderColor: isDark
                    ? alpha("#fff", 0.08)
                    : alpha("#000", 0.05),
                  bgcolor: isDark ? alpha("#1e293b", 0.6) : "#fff",
                  backdropFilter: "blur(20px)",
                  boxShadow: isDark
                    ? "0 10px 30px -10px rgba(0,0,0,0.5)"
                    : "0 10px 30px -10px rgba(0,0,0,0.05)",
                }}
              >
                <CardContent sx={{ p: 4 }}>
                  <Typography
                    variant="h6"
                    sx={{
                      fontWeight: 800,
                      display: "flex",
                      alignItems: "center",
                      gap: 1.5,
                      mb: 4,
                    }}
                  >
                    <BarChartIcon sx={{ color: "#3b82f6" }} /> توزيع مساحة
                    الملفات
                  </Typography>

                  <Grid container spacing={4}>
                    <Grid size={{ xs: 12, md: 7 }}>
                      <Stack spacing={2.5}>
                        {breakdownData.map((item, index) => (
                          <Box key={index}>
                            <Stack
                              direction="row"
                              justifyContent="space-between"
                              alignItems="center"
                              mb={1}
                            >
                              <Stack
                                direction="row"
                                spacing={1.5}
                                alignItems="center"
                              >
                                <Box
                                  sx={{ color: item.color, display: "flex" }}
                                >
                                  {item.icon}
                                </Box>
                                <Typography
                                  variant="body2"
                                  sx={{ fontWeight: 700 }}
                                >
                                  {item.name}
                                </Typography>
                              </Stack>
                              <Typography
                                variant="body2"
                                sx={{ fontWeight: 800 }}
                              >
                                {formatSize(item.value)}
                              </Typography>
                            </Stack>
                            <LinearProgress
                              variant="determinate"
                              value={(item.value / stats.used) * 100}
                              sx={{
                                height: 8,
                                borderRadius: 4,
                                bgcolor: isDark
                                  ? alpha("#000", 0.2)
                                  : alpha("#e2e8f0", 0.5),
                                "& .MuiLinearProgress-bar": {
                                  bgcolor: item.color,
                                  borderRadius: 4,
                                },
                              }}
                            />
                          </Box>
                        ))}
                      </Stack>
                    </Grid>
                    <Grid size={{ xs: 12, md: 5 }}>
                      <Box sx={{ width: "100%" }}>
                        <ResponsiveContainer
                          width="100%"
                          height={250}
                          minWidth={0}
                          minHeight={250}
                        >
                          <BarChart
                            data={breakdownData}
                            layout="vertical"
                            margin={{ left: -20 }}
                          >
                            <XAxis type="number" hide />
                            <YAxis
                              dataKey="name"
                              type="category"
                              width={80}
                              tick={{ fontSize: 12, fontWeight: 700 }}
                            />
                            <RechartsTooltip
                              formatter={(value: number) => formatSize(value)}
                              contentStyle={{
                                borderRadius: 8,
                                border: "none",
                                boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
                              }}
                            />
                            <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                              {breakdownData.map((entry, index) => (
                                <Cell
                                  key={`cell-${index}`}
                                  fill={entry.color}
                                />
                              ))}
                            </Bar>
                          </BarChart>
                        </ResponsiveContainer>
                      </Box>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            </motion.div>
          </Grid>

          {/* System Summary Cards */}
          <Grid size={{ xs: 12, sm: 4 }}>
            <motion.div
              custom={2}
              initial="hidden"
              animate="visible"
              variants={cardVariants}
            >
              <Card
                sx={{
                  borderRadius: 4,
                  height: "100%",
                  border: "1px solid",
                  borderColor: "divider",
                }}
              >
                <CardContent>
                  <Stack direction="row" spacing={2} alignItems="center">
                    <Box
                      sx={{
                        p: 1.5,
                        borderRadius: 3,
                        bgcolor: alpha("#3b82f6", 0.1),
                        color: "#3b82f6",
                      }}
                    >
                      <StorageIcon />
                    </Box>
                    <Box>
                      <Typography
                        variant="caption"
                        color="text.secondary"
                        sx={{ fontWeight: 600 }}
                      >
                        نظام التشغيل
                      </Typography>
                      <Typography
                        variant="h6"
                        sx={{ fontWeight: 800, textTransform: "uppercase" }}
                      >
                        {stats.platform}
                      </Typography>
                    </Box>
                  </Stack>
                </CardContent>
              </Card>
            </motion.div>
          </Grid>
          <Grid size={{ xs: 12, sm: 4 }}>
            <motion.div
              custom={3}
              initial="hidden"
              animate="visible"
              variants={cardVariants}
            >
              <Card
                sx={{
                  borderRadius: 4,
                  height: "100%",
                  border: "1px solid",
                  borderColor: "divider",
                }}
              >
                <CardContent>
                  <Stack direction="row" spacing={2} alignItems="center">
                    <Box
                      sx={{
                        p: 1.5,
                        borderRadius: 3,
                        bgcolor: alpha("#10b981", 0.1),
                        color: "#10b981",
                      }}
                    >
                      <SystemIcon />
                    </Box>
                    <Box>
                      <Typography
                        variant="caption"
                        color="text.secondary"
                        sx={{ fontWeight: 600 }}
                      >
                        اسم القرص
                      </Typography>
                      <Typography variant="h6" sx={{ fontWeight: 800 }}>
                        القرص المحلي (Root)
                      </Typography>
                    </Box>
                  </Stack>
                </CardContent>
              </Card>
            </motion.div>
          </Grid>
          <Grid size={{ xs: 12, sm: 4 }}>
            <motion.div
              custom={4}
              initial="hidden"
              animate="visible"
              variants={cardVariants}
            >
              <Card
                sx={{
                  borderRadius: 4,
                  height: "100%",
                  border: "1px solid",
                  borderColor: "divider",
                }}
              >
                <CardContent>
                  <Stack direction="row" spacing={2} alignItems="center">
                    <Box
                      sx={{
                        p: 1.5,
                        borderRadius: 3,
                        bgcolor: alpha("#fbbf24", 0.1),
                        color: "#fbbf24",
                      }}
                    >
                      <RefreshIcon />
                    </Box>
                    <Box>
                      <Typography
                        variant="caption"
                        color="text.secondary"
                        sx={{ fontWeight: 600 }}
                      >
                        آخر تحديث
                      </Typography>
                      <Typography variant="h6" sx={{ fontWeight: 800 }}>
                        {new Date(stats.timestamp).toLocaleTimeString("ar-EG", {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </Typography>
                    </Box>
                  </Stack>
                </CardContent>
              </Card>
            </motion.div>
          </Grid>
        </Grid>
      )}

      {/* Warning Sections */}
      <AnimatePresence>
        {stats && stats.usagePercent > 80 && (
          <motion.div
            initial={{ opacity: 0, height: 0, marginTop: 0 }}
            animate={{ opacity: 1, height: "auto", marginTop: 32 }}
            exit={{ opacity: 0, height: 0 }}
          >
            <Paper
              sx={{
                p: 3,
                borderRadius: 4,
                background: `linear-gradient(to right, ${alpha(muiTheme.palette.error.main, 0.1)}, transparent)`,
                border: "1px solid",
                borderColor: alpha(muiTheme.palette.error.main, 0.2),
              }}
            >
              <Stack direction="row" spacing={2} alignItems="center">
                <Box
                  sx={{
                    p: 1.5,
                    borderRadius: "50%",
                    bgcolor: muiTheme.palette.error.main,
                    color: "#fff",
                    animation: "pulse 2s infinite",
                  }}
                >
                  <InfoIcon />
                </Box>
                <Box>
                  <Typography
                    variant="h6"
                    sx={{ fontWeight: 900, color: muiTheme.palette.error.main }}
                  >
                    تنبيه: مساحة التخزين حرجة ({stats.usagePercent}%)
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      fontWeight: 500,
                      color: isDark ? "#94a3b8" : "#64748b",
                    }}
                  >
                    نوصي بحذف الفيديوهات القديمة أو الصور المؤرشفة لتوفير مساحة
                    إضافية.
                  </Typography>
                </Box>
              </Stack>
            </Paper>
          </motion.div>
        )}
      </AnimatePresence>
    </Box>
  );
};

export default SuperAdminServerUsage;

import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  Button,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  CircularProgress,
  Paper,
  Divider,
  Tooltip,
} from "@mui/material";
import {
  PlayArrow as PlayIcon,
  Stop as StopIcon,
  Refresh as RefreshIcon,
  Settings as SettingsIcon,
  Schedule as ScheduleIcon,
  CheckCircle as CheckCircleIcon,
  Error as ErrorIcon,
  Info as InfoIcon,
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";

interface SchedulerStats {
  totalChecked?: number;
  totalUpdated?: number;
  totalErrors?: number;
  totalChecks?: number;
  campaignsSent?: number;
  errors?: number;
}

interface Scheduler {
  id: string;
  name: string;
  description: string;
  isRunning: boolean;
  intervalMinutes?: number;
  activeCompanies?: number;
  lastRun?: string;
  lastCheck?: string;
  type: string;
  schedule?: string;
  icon: string;
  stats: SchedulerStats | null;
}

interface SchedulersSummary {
  total: number;
  running: number;
  stopped: number;
}

const SystemMonitoring: React.FC = () => {
  const [schedulers, setSchedulers] = useState<Scheduler[]>([]);
  const [summary, setSummary] = useState<SchedulersSummary>({
    total: 0,
    running: 0,
    stopped: 0,
  });
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [intervalDialog, setIntervalDialog] = useState(false);
  const [newInterval, setNewInterval] = useState(5);

  const fetchSchedulersStatus = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await apiClient.get("/admin/schedulers");

      if (response.data.success) {
        setSchedulers(response.data.data.schedulers);
        setSummary(response.data.data.summary);
      }
    } catch (err: any) {
      console.error("Error fetching schedulers:", err);
      setError(err.response?.data?.message || "فشل في جلب حالة الموقتات");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSchedulersStatus();
    const interval = setInterval(fetchSchedulersStatus, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleStartScheduler = async (schedulerId: string) => {
    try {
      setActionLoading(schedulerId);
      setError(null);
      setSuccess(null);
      const response = await apiClient.post(
        `/admin/schedulers/${schedulerId}/start`,
      );

      if (response.data.success) {
        setSuccess(response.data.message);
        await fetchSchedulersStatus();
      }
    } catch (err: any) {
      console.error("Error starting scheduler:", err);
      setError(err.response?.data?.message || "فشل في تشغيل الموقت");
    } finally {
      setActionLoading(null);
    }
  };

  const handleStopScheduler = async (schedulerId: string) => {
    try {
      setActionLoading(schedulerId);
      setError(null);
      setSuccess(null);
      const response = await apiClient.post(
        `/admin/schedulers/${schedulerId}/stop`,
      );

      if (response.data.success) {
        setSuccess(response.data.message);
        await fetchSchedulersStatus();
      }
    } catch (err: any) {
      console.error("Error stopping scheduler:", err);
      setError(err.response?.data?.message || "فشل في إيقاف الموقت");
    } finally {
      setActionLoading(null);
    }
  };

  const handleUpdateInterval = async () => {
    try {
      setActionLoading("interval");
      setError(null);
      setSuccess(null);
      const response = await apiClient.put(
        "/admin/schedulers/woocommerce/interval",
        { intervalMinutes: newInterval },
      );

      if (response.data.success) {
        setSuccess(response.data.message);
        setIntervalDialog(false);
        await fetchSchedulersStatus();
      }
    } catch (err: any) {
      console.error("Error updating interval:", err);
      setError(err.response?.data?.message || "فشل في تحديث الفترة");
    } finally {
      setActionLoading(null);
    }
  };

  const handleManualSync = async (type: "woocommerce" | "turbo") => {
    try {
      setActionLoading(`manual-${type}`);
      setError(null);
      setSuccess(null);
      const endpoint =
        type === "woocommerce"
          ? "/admin/schedulers/woocommerce/sync"
          : "/admin/schedulers/turbo/update";

      const response = await apiClient.post(endpoint);

      if (response.data.success) {
        setSuccess(response.data.message);
      }
    } catch (err: any) {
      console.error("Error triggering manual action:", err);
      setError(err.response?.data?.message || "فشل في تنفيذ العملية");
    } finally {
      setActionLoading(null);
    }
  };

  const formatDate = (dateString?: string) => {
    if (!dateString) return "لم يتم التشغيل بعد";
    const date = new Date(dateString);
    return date.toLocaleString("ar-EG");
  };

  if (loading && schedulers.length === 0) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="400px"
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h4" fontWeight="bold">
          ⚙️ مراقبة الموقتات
        </Typography>
        <Button
          variant="outlined"
          startIcon={<RefreshIcon />}
          onClick={fetchSchedulersStatus}
          disabled={loading}
        >
          تحديث
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert
          severity="success"
          sx={{ mb: 3 }}
          onClose={() => setSuccess(null)}
        >
          {success}
        </Alert>
      )}

      <Grid container spacing={3} mb={3}>
        <Grid size={{ xs: 12, md: 4 }}>
          <Paper
            sx={{
              p: 3,
              textAlign: "center",
              bgcolor: "primary.main",
              color: "white",
            }}
          >
            <Typography variant="h3" fontWeight="bold">
              {summary.total}
            </Typography>
            <Typography variant="body1">إجمالي الموقتات</Typography>
          </Paper>
        </Grid>
        <Grid size={{ xs: 12, md: 4 }}>
          <Paper
            sx={{
              p: 3,
              textAlign: "center",
              bgcolor: "success.main",
              color: "white",
            }}
          >
            <Typography variant="h3" fontWeight="bold">
              {summary.running}
            </Typography>
            <Typography variant="body1">موقتات نشطة</Typography>
          </Paper>
        </Grid>
        <Grid size={{ xs: 12, md: 4 }}>
          <Paper
            sx={{
              p: 3,
              textAlign: "center",
              bgcolor: "error.main",
              color: "white",
            }}
          >
            <Typography variant="h3" fontWeight="bold">
              {summary.stopped}
            </Typography>
            <Typography variant="body1">موقتات متوقفة</Typography>
          </Paper>
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        {schedulers.map((scheduler) => (
          <Grid size={{ xs: 12, md: 6, lg: 4 }} key={scheduler.id}>
            <Card
              sx={{ height: "100%", display: "flex", flexDirection: "column" }}
            >
              <CardContent sx={{ flexGrow: 1 }}>
                <Box
                  display="flex"
                  justifyContent="space-between"
                  alignItems="start"
                  mb={2}
                >
                  <Box display="flex" alignItems="center" gap={1}>
                    <Typography variant="h4">{scheduler.icon}</Typography>
                    <Box>
                      <Typography variant="h6" fontWeight="bold">
                        {scheduler.name}
                      </Typography>
                      <Chip
                        label={scheduler.isRunning ? "نشط" : "متوقف"}
                        color={scheduler.isRunning ? "success" : "error"}
                        size="small"
                        icon={
                          scheduler.isRunning ? (
                            <CheckCircleIcon />
                          ) : (
                            <ErrorIcon />
                          )
                        }
                      />
                    </Box>
                  </Box>
                  {scheduler.id === "woocommerce_sync" && (
                    <Tooltip title="تعديل الفترة">
                      <IconButton
                        size="small"
                        onClick={() => {
                          setNewInterval(scheduler.intervalMinutes || 5);
                          setIntervalDialog(true);
                        }}
                      >
                        <SettingsIcon />
                      </IconButton>
                    </Tooltip>
                  )}
                </Box>

                <Typography variant="body2" color="text.secondary" mb={2}>
                  {scheduler.description}
                </Typography>

                <Divider sx={{ my: 2 }} />

                <Box display="flex" flexDirection="column" gap={1}>
                  {scheduler.type === "cron" && scheduler.schedule && (
                    <Box display="flex" alignItems="center" gap={1}>
                      <ScheduleIcon fontSize="small" color="action" />
                      <Typography variant="body2">
                        الجدولة: {scheduler.schedule}
                      </Typography>
                    </Box>
                  )}

                  {scheduler.type === "polling" &&
                    scheduler.intervalMinutes && (
                      <Box display="flex" alignItems="center" gap={1}>
                        <ScheduleIcon fontSize="small" color="action" />
                        <Typography variant="body2">
                          كل {scheduler.intervalMinutes} دقيقة
                        </Typography>
                      </Box>
                    )}

                  {scheduler.activeCompanies !== undefined && (
                    <Box display="flex" alignItems="center" gap={1}>
                      <InfoIcon fontSize="small" color="action" />
                      <Typography variant="body2">
                        شركات نشطة: {scheduler.activeCompanies}
                      </Typography>
                    </Box>
                  )}

                  {scheduler.lastRun && (
                    <Typography variant="caption" color="text.secondary">
                      آخر تشغيل: {formatDate(scheduler.lastRun)}
                    </Typography>
                  )}

                  {scheduler.lastCheck && (
                    <Typography variant="caption" color="text.secondary">
                      آخر فحص: {formatDate(scheduler.lastCheck)}
                    </Typography>
                  )}
                </Box>

                {scheduler.stats && (
                  <>
                    <Divider sx={{ my: 2 }} />
                    <Typography variant="subtitle2" fontWeight="bold" mb={1}>
                      الإحصائيات:
                    </Typography>
                    <Box display="flex" flexDirection="column" gap={0.5}>
                      {scheduler.stats.totalChecked !== undefined && (
                        <Typography variant="body2">
                          تم الفحص: {scheduler.stats.totalChecked}
                        </Typography>
                      )}
                      {scheduler.stats.totalUpdated !== undefined && (
                        <Typography variant="body2" color="success.main">
                          تم التحديث: {scheduler.stats.totalUpdated}
                        </Typography>
                      )}
                      {scheduler.stats.totalChecks !== undefined && (
                        <Typography variant="body2">
                          إجمالي الفحوصات: {scheduler.stats.totalChecks}
                        </Typography>
                      )}
                      {scheduler.stats.campaignsSent !== undefined && (
                        <Typography variant="body2" color="success.main">
                          حملات مرسلة: {scheduler.stats.campaignsSent}
                        </Typography>
                      )}
                      {(scheduler.stats.totalErrors !== undefined ||
                        scheduler.stats.errors !== undefined) && (
                        <Typography variant="body2" color="error.main">
                          أخطاء:{" "}
                          {scheduler.stats.totalErrors ||
                            scheduler.stats.errors}
                        </Typography>
                      )}
                    </Box>
                  </>
                )}
              </CardContent>

              <Box sx={{ p: 2, pt: 0, display: "flex", gap: 1 }}>
                {scheduler.isRunning ? (
                  <Button
                    variant="contained"
                    color="error"
                    startIcon={<StopIcon />}
                    fullWidth
                    onClick={() => handleStopScheduler(scheduler.id)}
                    disabled={actionLoading === scheduler.id}
                  >
                    {actionLoading === scheduler.id ? (
                      <CircularProgress size={24} />
                    ) : (
                      "إيقاف"
                    )}
                  </Button>
                ) : (
                  <Button
                    variant="contained"
                    color="success"
                    startIcon={<PlayIcon />}
                    fullWidth
                    onClick={() => handleStartScheduler(scheduler.id)}
                    disabled={actionLoading === scheduler.id}
                  >
                    {actionLoading === scheduler.id ? (
                      <CircularProgress size={24} />
                    ) : (
                      "تشغيل"
                    )}
                  </Button>
                )}

                {(scheduler.id === "woocommerce_sync" ||
                  scheduler.id === "turbo_tracking") && (
                  <Button
                    variant="outlined"
                    startIcon={<RefreshIcon />}
                    onClick={() =>
                      handleManualSync(
                        scheduler.id === "woocommerce_sync"
                          ? "woocommerce"
                          : "turbo",
                      )
                    }
                    disabled={
                      actionLoading ===
                      `manual-${scheduler.id === "woocommerce_sync" ? "woocommerce" : "turbo"}`
                    }
                  >
                    {actionLoading ===
                    `manual-${scheduler.id === "woocommerce_sync" ? "woocommerce" : "turbo"}` ? (
                      <CircularProgress size={24} />
                    ) : (
                      "تشغيل يدوي"
                    )}
                  </Button>
                )}
              </Box>
            </Card>
          </Grid>
        ))}
      </Grid>

      <Dialog open={intervalDialog} onClose={() => setIntervalDialog(false)}>
        <DialogTitle>تعديل فترة المزامنة</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="الفترة بالدقائق"
            type="number"
            fullWidth
            value={newInterval}
            onChange={(e) => setNewInterval(parseInt(e.target.value))}
            inputProps={{ min: 1, max: 60 }}
            helperText="أدخل قيمة بين 1 و 60 دقيقة"
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setIntervalDialog(false)}>إلغاء</Button>
          <Button
            onClick={handleUpdateInterval}
            variant="contained"
            disabled={
              actionLoading === "interval" ||
              newInterval < 1 ||
              newInterval > 60
            }
          >
            {actionLoading === "interval" ? (
              <CircularProgress size={24} />
            ) : (
              "حفظ"
            )}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default SystemMonitoring;

import React, { useEffect, useState, useRef } from "react";
import {
