              >
                <Download className="w-4 h-4" />
                تصدير
              </button>
              <div
                id="export-menu"
                className={`hidden absolute left-0 mt-2 w-48 rounded-lg shadow-lg border z-10 ${
                  isDark
                    ? "bg-gray-800 border-gray-700"
                    : "bg-white border-gray-200"
                }`}
              >
                <button
                  onClick={() => handleExport("csv")}
