import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import {
  ArrowLeft,
  Search,
  ChevronDown,
  ChevronUp,
  ThumbsUp,
  ThumbsDown,
  BookOpen,
  HelpCircle,
  MessageSquare,
  Plus,
} from "lucide-react";
import supportService, { FAQ as FAQType } from "../../services/supportService";
import ThemeToggle from "../../components/ui/theme-toggle";

interface FAQCategory {
  category: string;
  count: number;
}

const FAQ: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const initialCategory = searchParams.get("category") || "";

  const [faqs, setFaqs] = useState<{ [key: string]: FAQType[] }>({});
  const [categories, setCategories] = useState<FAQCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedCategory, setSelectedCategory] = useState(initialCategory);
  const [expandedFAQ, setExpandedFAQ] = useState<string | null>(null);

  const categoryLabels: { [key: string]: string } = {
    general: "عام",
    technical: "تقني",
    billing: "فواتير",
    woocommerce: "WooCommerce",
    whatsapp: "WhatsApp",
    facebook_ads: "إعلانات فيسبوك",
  };

  useEffect(() => {
    fetchFAQs();
    fetchCategories();
  }, []);

  useEffect(() => {
    if (selectedCategory) {
      fetchFAQs();
    }
  }, [selectedCategory]);

  const fetchFAQs = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();

      if (selectedCategory) {
        params.append("category", selectedCategory);
      }

      if (searchTerm) {
        params.append("search", searchTerm);
      }

      const data = await supportService.getFAQs(params);

      if (data.success) {
        setFaqs(data.faqs || {});
      }
    } catch (error) {
      console.error("Error fetching FAQs:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchCategories = async () => {
    try {
      const data = await supportService.getFAQCategories();

      if (data.success) {
        setCategories(data.categories || []);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const handleSearch = () => {
    fetchFAQs();
  };

  const rateFAQ = async (faqId: string, helpful: boolean) => {
    try {
      await supportService.rateFAQ(faqId, helpful);
      // Refresh FAQs to show updated ratings
      fetchFAQs();
    } catch (error) {
      console.error("Error rating FAQ:", error);
    }
  };

  const toggleFAQ = (faqId: string) => {
    setExpandedFAQ(expandedFAQ === faqId ? null : faqId);
  };

  const clearFilters = () => {
    setSelectedCategory("");
    setSearchTerm("");
    fetchFAQs();
  };

  if (loading && Object.keys(faqs).length === 0) {
