            </button>
            <ThemeToggle />
          </div>
          <div className="text-center">
            <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-4 flex items-center justify-center">
              <BookOpen className="w-8 h-8 ml-3 text-blue-600 dark:text-blue-400" />
