import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import supportService, { Ticket } from "../../services/supportService";
import TicketsSidebar from "./components/TicketsSidebar";
import ChatArea from "./components/ChatArea";
import DetailsPanel from "./components/DetailsPanel";
import { useAuth } from "../../hooks/useAuthSimple";

const MyTickets: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [activeTicket, setActiveTicket] = useState<Ticket | null>(null);
  const [loading, setLoading] = useState(true);
  const [ticketLoading, setTicketLoading] = useState(false);
  const [userHistory, setUserHistory] = useState<any[]>([]);
  const [showDetailsPanel, setShowDetailsPanel] = useState(true);

  // Get ticket ID from URL
  const ticketIdFromUrl = searchParams.get("ticket");

  useEffect(() => {
    fetchTickets();
  }, []);

  useEffect(() => {
    if (ticketIdFromUrl && tickets.length > 0) {
      const ticket = tickets.find((t) => t.ticketId === ticketIdFromUrl);
      if (ticket) {
        handleTicketSelect(ticketIdFromUrl);
      }
    } else if (tickets.length > 0 && !activeTicket) {
      // Auto-select first ticket
      handleTicketSelect(tickets[0].ticketId);
    }
  }, [ticketIdFromUrl, tickets]);

  const fetchTickets = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        limit: "100", // Get all tickets for sidebar
      });

      const data = await supportService.getUserTickets(params);

      if (data.success) {
        setTickets(data.tickets || []);
      }
    } catch (error) {
      console.error("Error fetching tickets:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleTicketSelect = async (ticketId: string) => {
    try {
      setTicketLoading(true);
      setSearchParams({ ticket: ticketId });

      const data = await supportService.getTicketDetails(ticketId);

      if (data.success) {
        setActiveTicket(data.ticket);

        // Fetch user history if admin
        if (user?.role === "SUPER_ADMIN" && data.ticket.userId) {
          fetchUserHistory(data.ticket.userId.id, ticketId);
        }
      }
    } catch (error) {
      console.error("Error fetching ticket details:", error);
    } finally {
      setTicketLoading(false);
    }
  };

  const fetchUserHistory = async (userId: string, currentTicketId: string) => {
    try {
      const data = await supportService.getUserTicketHistory(
        userId,
        currentTicketId,
      );
      if (data.success) {
        setUserHistory(data.tickets || []);
      }
    } catch (error) {
      console.error("Error fetching user history:", error);
    }
  };

  const handleSendMessage = async (content: string, attachments: File[]) => {
    if (!activeTicket) return;

    try {
      const formData = new FormData();
      formData.append("content", content);
      attachments.forEach((file) => formData.append("attachments", file));

      const data = await supportService.addMessage(
        activeTicket.ticketId,
        formData,
      );

      if (data.success) {
        // Refresh ticket details
        const updatedData = await supportService.getTicketDetails(
          activeTicket.ticketId,
        );
        if (updatedData.success) {
          setActiveTicket(updatedData.ticket);
          // Update ticket in list
          setTickets((prev) =>
            prev.map((t) =>
              t.ticketId === activeTicket.ticketId ? updatedData.ticket : t,
            ),
          );
        }
      }
    } catch (error) {
      console.error("Error sending message:", error);
      throw error;
    }
  };

  const handleStatusChange = async (status: string) => {
    if (!activeTicket) return;

    try {
      const data = await supportService.updateTicketStatus(
        activeTicket.ticketId,
        status,
      );

      if (data.success) {
        setActiveTicket((prev) => (prev ? { ...prev, status } : null));
        setTickets((prev) =>
          prev.map((t) =>
            t.ticketId === activeTicket.ticketId ? { ...t, status } : t,
          ),
        );
      }
    } catch (error) {
      console.error("Error updating status:", error);
    }
  };

  const handlePriorityChange = async (priority: string) => {
    if (!activeTicket) return;

    try {
      const data = await supportService.updateTicketPriority(
        activeTicket.ticketId,
        priority,
      );

      if (data.success) {
        setActiveTicket((prev) => (prev ? { ...prev, priority } : null));
        setTickets((prev) =>
          prev.map((t) =>
            t.ticketId === activeTicket.ticketId ? { ...t, priority } : t,
          ),
        );
      }
    } catch (error) {
      console.error("Error updating priority:", error);
    }
  };

  const handleNewTicket = () => {
    navigate("/support/tickets/new");
  };

  return (
    <div className="h-screen flex flex-col bg-gray-50 dark:bg-gray-900">
      {/* 3-Column Layout */}
      <div className="flex-1 flex overflow-hidden">
        {/* Column 1: Tickets Sidebar */}
        <div className="w-80 flex-shrink-0 hidden lg:block">
          <TicketsSidebar
            tickets={tickets}
            activeTicketId={activeTicket?.ticketId || null}
            onTicketSelect={handleTicketSelect}
            onNewTicket={handleNewTicket}
            loading={loading}
          />
        </div>

        {/* Column 2: Chat Area */}
        <div className="flex-1 min-w-0">
          <ChatArea
            ticket={activeTicket}
            onSendMessage={handleSendMessage}
            onStatusChange={handleStatusChange}
            onPriorityChange={handlePriorityChange}
            loading={ticketLoading}
          />
        </div>

        {/* Column 3: Details Panel */}
        <div
          className={`w-80 flex-shrink-0 hidden xl:block ${!showDetailsPanel ? "hidden" : ""}`}
        >
          <DetailsPanel ticket={activeTicket} userHistory={userHistory} />
        </div>
      </div>

      {/* Mobile: Show sidebar as overlay */}
      <div className="lg:hidden">
        {/* Mobile implementation can be added later */}
      </div>
    </div>
  );
};

export default MyTickets;

import React, { useState, useEffect, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeft,
  ArrowRight,
  Send,
  Paperclip,
  X,
  Download,
  Clock,
  CheckCircle,
  AlertCircle,
  Star,
  MessageSquare,
  User,
  Shield,
  Briefcase,
  Building,
  Mail,
  Phone,
  Calendar,
  MoreVertical,
  Flag,
  Trash2,
  Lock,
  Search,
  Filter,
} from "lucide-react";
import supportService, {
  Ticket,
  AttachmentFile,
} from "../../services/supportService";
import { useAuth } from "../../hooks/useAuthSimple";

const TicketDetails: React.FC = () => {
  const { ticketId } = useParams<{ ticketId: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const [ticket, setTicket] = useState<Ticket | null>(null);
  const [loading, setLoading] = useState(true);
  const [messageContent, setMessageContent] = useState("");
  const [attachments, setAttachments] = useState<AttachmentFile[]>([]);
  const [sendingMessage, setSendingMessage] = useState(false);
  const [error, setError] = useState("");
  const [showRating, setShowRating] = useState(false);
  const [rating, setRating] = useState(0);
  const [feedback, setFeedback] = useState("");
  const [submittingRating, setSubmittingRating] = useState(false);

  // Admin specific state
  const [adminTab, setAdminTab] = useState<"reply" | "note">("reply");
  const [updatingStatus, setUpdatingStatus] = useState(false);
  const [userHistory, setUserHistory] = useState<any[]>([]);
  const [staffList, setStaffList] = useState<any[]>([]);
  const [notification, setNotification] = useState<string | null>(null);

  // NEW: All tickets for sidebar
  const [allTickets, setAllTickets] = useState<Ticket[]>([]);
  const [ticketsSearchQuery, setTicketsSearchQuery] = useState("");

  const isAdmin = user?.role === "SUPER_ADMIN" || user?.role === "superadmin";

  useEffect(() => {
    if (ticketId) {
      fetchTicketDetails();
    }
  }, [ticketId]);

  useEffect(() => {
    scrollToBottom();
  }, [ticket?.messages]);

  useEffect(() => {
    if (isAdmin && ticket?.userId) {
      fetchUserHistory();
      fetchStaffList();
    }
  }, [ticket?.userId, isAdmin]);

  // NEW: Fetch all tickets for sidebar
  useEffect(() => {
    if (isAdmin) {
      fetchAllTickets();
    }
  }, [isAdmin]);

  const fetchAllTickets = async () => {
    try {
      const data = await supportService.getAllTickets();
      if (data.success) setAllTickets(data.tickets || []);
    } catch (err) {
      console.error("Error fetching all tickets", err);
    }
  };

  const fetchUserHistory = async () => {
    if (!ticket?.userId) return;
    try {
      // @ts-ignore
      const userId = ticket.userId.id;
      const data = await supportService.getUserTicketHistory(
        userId,
        ticket.ticketId,
      );
      if (data.success) setUserHistory(data.tickets);
    } catch (err) {
      console.error("Error fetching history", err);
    }
  };

  const fetchStaffList = async () => {
    try {
      const data = await supportService.getSupportStaff();
      if (data.success) setStaffList(data.staff);
    } catch (err) {
      console.error("Error fetching staff", err);
    }
  };

  const showNotification = (msg: string) => {
    setNotification(msg);
    setTimeout(() => setNotification(null), 3000);
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const fetchTicketDetails = async () => {
    try {
      setLoading(true);
      const data = await supportService.getTicketDetails(ticketId!);

      if (data.success) {
        setTicket(data.ticket);
        // Show rating form if ticket is closed and not rated yet (ONLY for users)
        if (
          !isAdmin &&
          data.ticket.status === "closed" &&
          !data.ticket.rating
        ) {
          setShowRating(true);
        }
      } else {
        setError("التذكرة غير موجودة");
      }
    } catch (error: any) {
      setError(
        error.response?.data?.message || "حدث خطأ في جلب تفاصيل التذكرة",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (newStatus: string) => {
    if (!ticket) return;
    try {
      setUpdatingStatus(true);
      const data = await supportService.updateTicket(ticket.ticketId, {
        status: newStatus,
      });
      if (data.success) {
        await fetchTicketDetails();
        showNotification("تم تحديث الحالة بنجاح");
      }
    } catch (error) {
      console.error("Failed to update status", error);
    } finally {
      setUpdatingStatus(false);
    }
  };

  const handleUpdatePriority = async (newPriority: string) => {
    if (!ticket) return;
    try {
      const data = await supportService.updateTicket(ticket.ticketId, {
        priority: newPriority,
      });
      if (data.success) {
        await fetchTicketDetails();
        showNotification("تم تحديث الأولوية بنجاح");
      }
    } catch (error) {
      console.error("Failed to update priority", error);
    }
  };

  const handleAssignToMe = async () => {
    if (!ticket || !user) return;
    try {
      const data = await supportService.updateTicket(ticket.ticketId, {
        assignedUserId: user.id,
      });
      if (data.success) {
        await fetchTicketDetails();
        showNotification("تم تعيين التذكرة لك بنجاح");
      }
    } catch (error) {
      console.error("Failed to assign ticket", error);
    }
  };

  const handleAssignUser = async (userId: string) => {
    if (!ticket) return;
    try {
      const data = await supportService.updateTicket(ticket.ticketId, {
        assignedUserId: userId,
      });
      if (data.success) {
        await fetchTicketDetails();
        showNotification("تم تعيين التذكرة للموظف بنجاح");
      }
    } catch (error) {
      console.error("Failed to assign ticket", error);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    const maxFiles = 5;
    const maxSize = 10 * 1024 * 1024; // 10MB

    if (attachments.length + files.length > maxFiles) {
      setError(`يمكنك رفع ${maxFiles} ملفات كحد أقصى`);
      return;
    }

    const validFiles: AttachmentFile[] = [];

    files.forEach((file) => {
      if (file.size > maxSize) {
        setError(`حجم الملف ${file.name} كبير جداً (الحد الأقصى 10 ميجابايت)`);
        return;
      }

      const allowedTypes = [
        "image/jpeg",
        "image/jpg",
        "image/png",
        "image/gif",
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "text/plain",
      ];

      if (!allowedTypes.includes(file.type)) {
        setError(`نوع الملف ${file.name} غير مسموح`);
        return;
      }

      const attachmentFile: AttachmentFile = { file };

      // Create preview for images
      if (file.type.startsWith("image/")) {
        const reader = new FileReader();
        reader.onload = (e) => {
          attachmentFile.preview = e.target?.result as string;
          setAttachments((prev) => [...prev, attachmentFile]);
        };
        reader.readAsDataURL(file);
      } else {
        validFiles.push(attachmentFile);
      }
    });

    if (validFiles.length > 0) {
      setAttachments((prev) => [...prev, ...validFiles]);
    }

    // Clear the input
    e.target.value = "";
  };

  const removeAttachment = (index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!messageContent.trim() && attachments.length === 0) {
      setError("يجب كتابة رسالة أو إرفاق ملف");
      return;
    }

    setSendingMessage(true);
    setError("");

    try {
      const formData = new FormData();
      // If admin is sending a note, we might prefix it or handle it differently.
      // Current backend might not support "Internal Notes" natively visible only to admins.
      // For now, we strictly send as "content" but if it's a note, we might style it differently in the future
      // or assume the backend handles it. Since backend audit said no implementation yet,
      // we will treat "Internal Note" as a visual distinct message for now or simply as a normal message
      // but warn the admin it's public if the backend doesn't support it.
      // Re-reading usage: Admin wants "Internal Notes".
      // If I send it as normal message, USER WILL SEE IT.
      // Safest: ONLY "Reply" works for now. "Internal Note" should be disabled or marked (Coming Soon).

      const contentToSend = messageContent;

      formData.append("content", contentToSend);
      if (adminTab === "note") {
        formData.append("isInternal", "true");
      }

      // Add attachments
      attachments.forEach((attachment) => {
        formData.append("attachments", attachment.file);
      });

      const data = await supportService.addMessage(ticketId!, formData);

      if (data.success) {
        setTicket(data.ticket);
        setMessageContent("");
        setAttachments([]);
      } else {
        setError(data.message || "حدث خطأ في إرسال الرسالة");
      }
    } catch (error: any) {
      setError(error.response?.data?.message || "حدث خطأ في إرسال الرسالة");
    } finally {
      setSendingMessage(false);
    }
  };

  const handleRatingSubmit = async () => {
    if (rating === 0) {
      setError("يرجى اختيار تقييم");
      return;
    }

    setSubmittingRating(true);
    setError("");

    try {
      const data = await supportService.rateTicket(ticketId!, {
        rating,
        feedback,
      });

      if (data.success) {
        setTicket(data.ticket);
        setShowRating(false);
      } else {
        setError(data.message || "حدث خطأ في تقييم الخدمة");
      }
    } catch (error: any) {
      setError(error.response?.data?.message || "حدث خطأ في تقييم الخدمة");
    } finally {
      setSubmittingRating(false);
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "open":
        return <Clock className="w-5 h-5 text-orange-500" />;
      case "in_progress":
        return <AlertCircle className="w-5 h-5 text-blue-500" />;
      case "closed":
        return <CheckCircle className="w-5 h-5 text-green-500" />;
      default:
        return <Clock className="w-5 h-5 text-gray-500" />;
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case "open":
        return "مفتوح";
      case "in_progress":
        return "قيد المعالجة";
      case "closed":
        return "مغلق";
      default:
        return status;
    }
  };

  const getCategoryText = (category: string) => {
    const categories: { [key: string]: string } = {
      technical: "تقني",
      billing: "فواتير",
      inquiry: "استفسار",
      suggestion: "اقتراح",
      complaint: "شكوى",
    };
    return categories[category] || category;
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return "0 Bytes";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
  };

  if (loading) {
    return (
      <div className="support-ticket-theme min-h-screen bg-gray-50 flex items-center justify-center dark:bg-gray-950">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error && !ticket) {
    return (
      <div className="support-ticket-theme min-h-screen bg-gray-50 flex items-center justify-center dark:bg-gray-950">
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg shadow-md dark:shadow-black/40 p-8 text-center max-w-md">
          <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-gray-900 dark:text-slate-100 mb-2">
            خطأ
          </h2>
          <p className="text-gray-600 dark:text-slate-400 mb-4">{error}</p>
          <button
            onClick={() =>
              navigate(isAdmin ? "/admin/support" : "/support/tickets")
            }
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            العودة إلى التذاكر
          </button>
        </div>
      </div>
    );
  }

  if (!ticket) return null;

  // =========================================================================
