                              {staff.name}
                            </button>
                          ))}
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Previous Tickets */}
              <div className="bg-white rounded-2xl p-5 border border-slate-100 shadow-sm">
                <h3 className="text-sm font-bold text-slate-400 uppercase mb-4 tracking-wider">
                  تذاكر سابقة للعميل
                </h3>
                <div className="space-y-2 max-h-60 overflow-y-auto">
                  {userHistory.length > 0 ? (
                    userHistory.map((hTicket) => (
                      <div
                        key={hTicket.id}
                        onClick={() =>
                          navigate(`/support/tickets/${hTicket.ticketId}`)
                        }
                        className="cursor-pointer group flex items-start gap-3 p-3 rounded-xl hover:bg-slate-50 transition-colors border border-transparent hover:border-slate-200"
                      >
                        <div
                          className={`mt-1 w-2.5 h-2.5 rounded-full flex-shrink-0 ${
                            hTicket.status === "open"
                              ? "bg-emerald-500"
                              : hTicket.status === "closed"
                                ? "bg-slate-300"
                                : "bg-indigo-500"
                          }`}
                        />
                        <div className="flex-1 min-w-0">
                          <div className="text-base font-medium text-slate-700 truncate group-hover:text-indigo-600 transition-colors mb-1">
                            {hTicket.subject}
                          </div>
                          <div className="flex items-center gap-2 text-sm text-slate-400">
                            <span className="font-mono">
                              {hTicket.ticketId}
                            </span>
                            <span>•</span>
                            <span>
                              {new Date(hTicket.createdAt).toLocaleDateString(
                                "ar-EG",
                              )}
                            </span>
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-base text-slate-400 italic text-center py-4 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                      لا توجد تذاكر سابقة
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // =========================================================================
  // USER VIEW (Original Layout)
  // =========================================================================
  return (
    <div className="support-ticket-theme h-screen bg-gray-50 flex flex-col dark:bg-gray-950">
      <div className="flex-1 w-full px-4 sm:px-6 lg:px-8 py-4 flex flex-col overflow-hidden">
        {/* Header */}
        <div className="mb-6">
          <button
            onClick={() => navigate("/support/tickets")}
            className="flex items-center text-blue-600 hover:text-blue-700 mb-4"
          >
            <ArrowLeft className="w-4 h-4 ml-2" />
            العودة إلى التذاكر
          </button>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-start justify-between mb-4">
              <div>
                <h1 className="text-2xl font-bold text-gray-900 mb-2">
                  {ticket.subject}
                </h1>
                <div className="flex items-center space-x-4 space-x-reverse text-sm text-gray-600">
                  <span>#{ticket.ticketId}</span>
                  <span>•</span>
                  <span>{getCategoryText(ticket.category)}</span>
                  <span>•</span>
                  <span>
                    {new Date(ticket.createdAt).toLocaleDateString("ar-EG")}
                  </span>
                </div>
              </div>
              <div className="flex items-center">
                {getStatusIcon(ticket.status)}
                <span className="mr-2 font-medium">
                  {getStatusText(ticket.status)}
                </span>
              </div>
            </div>

            {ticket.status === "closed" && ticket.resolvedAt && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-4">
                <div className="flex items-center">
                  <CheckCircle className="w-5 h-5 text-green-500 ml-2" />
                  <span className="text-green-800">
                    تم حل التذكرة في{" "}
                    {new Date(ticket.resolvedAt).toLocaleDateString("ar-EG")}
                  </span>
                </div>
                {ticket.rating && (
                  <div className="mt-2 flex items-center">
                    <span className="text-green-700 ml-2">التقييم:</span>
                    <div className="flex">
                      {[1, 2, 3, 4, 5].map((star) => (
                        <Star
                          key={star}
                          className={`w-4 h-4 ${
                            star <= ticket.rating!
                              ? "text-yellow-400 fill-current"
                              : "text-gray-300"
                          }`}
                        />
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Messages */}
        <div className="bg-white rounded-lg shadow-md mb-4 flex-1 flex flex-col min-h-0">
          <div className="p-4 border-b border-gray-200 flex-shrink-0">
            <h2 className="text-lg font-semibold text-gray-900 flex items-center">
              <MessageSquare className="w-5 h-5 ml-2" />
              المحادثة ({ticket.messages.length})
            </h2>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 min-h-0">
            {ticket.messages.map((message, index) => (
              <div
                key={message._id}
                className={`flex ${
                  message.senderType === "user"
                    ? "justify-end"
                    : "justify-start"
                }`}
              >
                <div
                  className={`max-w-xs lg:max-w-md px-4 py-3 rounded-lg ${
                    message.senderType === "user"
                      ? "bg-blue-600 text-white"
                      : "bg-gray-100 text-gray-900"
                  }`}
                >
                  <div className="flex items-center mb-2">
                    {message.senderType === "admin" ? (
                      <Shield className="w-4 h-4 ml-1 text-blue-600" />
                    ) : (
                      <User className="w-4 h-4 ml-1" />
                    )}
                    <span className="text-xs font-medium">
                      {message.senderType === "admin"
                        ? "فريق الدعم"
                        : message.sender.name}
                    </span>
                  </div>

                  <p className="text-sm leading-relaxed mb-2">
                    {message.content}
                  </p>

                  {message.attachments.length > 0 && (
                    <div className="space-y-2 mb-2">
                      {message.attachments.map((attachment, attachIndex) => (
                        <div key={attachIndex} className="flex items-center">
                          {attachment.mimetype.startsWith("image/") ? (
                            <img
                              src={attachment.url}
                              alt={attachment.originalName}
                              className="max-w-full h-32 object-cover rounded cursor-pointer"
                              onClick={() =>
                                window.open(attachment.url, "_blank")
                              }
                            />
                          ) : (
                            <a
                              href={attachment.url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center text-xs hover:underline"
                            >
                              <Download className="w-3 h-3 ml-1" />
                              {attachment.originalName} (
                              {formatFileSize(attachment.size)})
                            </a>
                          )}
                        </div>
                      ))}
                    </div>
                  )}

                  <div className="text-xs opacity-75">
                    {new Date(message.createdAt).toLocaleString("ar-EG")}
                  </div>
                </div>
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Reply Form (User) */}
        {ticket.status !== "closed" && (
          <div className="bg-white rounded-lg shadow-md p-4 flex-shrink-0">
            <h3 className="text-lg font-semibold text-gray-900 mb-3">
              إضافة رد
            </h3>

            {error && (
              <div className="bg-red-50 border border-red-200 rounded-lg p-3 mb-3 flex items-center">
                <AlertCircle className="w-5 h-5 text-red-500 ml-3" />
                <span className="text-red-700">{error}</span>
              </div>
            )}

            <form onSubmit={handleSendMessage} className="space-y-3">
              <textarea
                value={messageContent}
                onChange={(e) => setMessageContent(e.target.value)}
                placeholder="اكتب ردك هنا..."
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
              />

              {/* File Upload */}
              <div>
                <input
                  type="file"
                  multiple
                  accept="image/*,.pdf,.doc,.docx,.txt"
                  onChange={handleFileUpload}
                  className="hidden"
                  id="message-file-upload"
                />
                <label
                  htmlFor="message-file-upload"
                  className="inline-flex items-center px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 cursor-pointer transition-colors"
                >
                  <Paperclip className="w-4 h-4 ml-2" />
                  إرفاق ملفات
                </label>
              </div>

              {/* Attachments Preview */}
              {attachments.length > 0 && (
                <div className="space-y-2">
                  {attachments.map((attachment, index) => (
                    <div
                      key={index}
                      className="flex items-center justify-between bg-gray-50 rounded-lg p-3"
                    >
                      <div className="flex items-center gap-3">
                        {attachment.preview ? (
                          <img
                            src={attachment.preview}
                            alt="Preview"
                            className="w-8 h-8 object-cover rounded"
                          />
                        ) : (
                          <div className="w-8 h-8 bg-gray-200 rounded flex items-center justify-center">
                            <Paperclip className="w-3 h-3 text-gray-500" />
                          </div>
                        )}
                        <span className="text-sm text-gray-900">
                          {attachment.file.name}
                        </span>
                      </div>
                      <button
                        type="button"
                        onClick={() => removeAttachment(index)}
                        className="text-red-500 hover:text-red-700 p-1"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <div className="flex justify-end">
                <button
                  type="submit"
                  disabled={
                    sendingMessage ||
                    (!messageContent.trim() && attachments.length === 0)
                  }
                  className="inline-flex items-center px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {sendingMessage ? (
                    <>
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white ml-2"></div>
                      جاري الإرسال...
                    </>
                  ) : (
                    <>
                      <Send className="w-4 h-4 ml-2" />
                      إرسال
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>
        )}

        {/* Rating Form */}
        {showRating && (
          <div className="bg-white rounded-lg shadow-md p-4 flex-shrink-0">
            <h3 className="text-lg font-semibold text-gray-900 mb-3">
              تقييم الخدمة
            </h3>
            <p className="text-gray-600 mb-3">
              نرجو منك تقييم جودة الدعم المقدم لك
            </p>

            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  التقييم *
                </label>
                <div className="flex space-x-1 space-x-reverse">
                  {[1, 2, 3, 4, 5].map((star) => (
                    <button
                      key={star}
                      type="button"
                      onClick={() => setRating(star)}
                      className={`p-1 ${
                        star <= rating
                          ? "text-yellow-400"
                          : "text-gray-300 hover:text-yellow-400"
                      }`}
                    >
                      <Star className="w-5 h-5 fill-current" />
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label
                  htmlFor="feedback"
                  className="block text-sm font-medium text-gray-700 mb-2"
                >
                  ملاحظات إضافية (اختياري)
                </label>
                <textarea
                  id="feedback"
                  value={feedback}
                  onChange={(e) => setFeedback(e.target.value)}
                  placeholder="شاركنا رأيك حول الخدمة المقدمة..."
                  rows={2}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
                />
              </div>

              <div className="flex justify-end space-x-3 space-x-reverse">
                <button
                  onClick={() => setShowRating(false)}
                  className="px-3 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  تخطي
                </button>
                <button
                  onClick={handleRatingSubmit}
                  disabled={submittingRating || rating === 0}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {submittingRating ? "جاري الحفظ..." : "إرسال التقييم"}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default TicketDetails;

import React from "react";
import {
  Calendar,
  Tag,
  User,
  Mail,
  Clock,
  Star,
  TrendingUp,
} from "lucide-react";
import { Ticket } from "../../../services/supportService";

interface DetailsPanelProps {
  ticket: Ticket | null;
  userHistory?: any[];
}

const DetailsPanel: React.FC<DetailsPanelProps> = ({ ticket, userHistory }) => {
  if (!ticket) {
    return (
      <div className="h-full flex items-center justify-center bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700">
        <div className="text-center text-gray-500 dark:text-gray-400">
          <Tag className="w-12 h-12 mx-auto mb-2 opacity-50" />
          <p className="text-sm">لا توجد تفاصيل</p>
        </div>
      </div>
    );
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case "open":
        return "bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300";
      case "in_progress":
        return "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300";
      case "closed":
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300";
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-300";
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "critical":
        return "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300";
      case "high":
        return "bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300";
      case "medium":
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300";
      case "low":
        return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-300";
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-300";
    }
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case "technical":
        return "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300";
      case "billing":
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300";
      case "inquiry":
        return "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300";
      case "suggestion":
        return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300";
      case "complaint":
        return "bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300";
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-300";
    }
  };

  const getStatusText = (status: string) => {
    const statusMap: { [key: string]: string } = {
      open: "مفتوح",
      in_progress: "قيد المعالجة",
      closed: "مغلق",
    };
    return statusMap[status] || status;
  };

  const getPriorityText = (priority: string) => {
    const priorityMap: { [key: string]: string } = {
      critical: "حرجة",
      high: "عالية",
      medium: "متوسطة",
      low: "منخفضة",
    };
    return priorityMap[priority] || priority;
  };

  const getCategoryText = (category: string) => {
    const categoryMap: { [key: string]: string } = {
      technical: "تقني",
      billing: "فواتير",
      inquiry: "استفسار",
      suggestion: "اقتراح",
      complaint: "شكوى",
    };
    return categoryMap[category] || category;
  };

  return (
    <div className="h-full overflow-y-auto bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700">
      <div className="p-4 space-y-6">
        {/* Ticket Info */}
        <div className="bg-white dark:bg-gray-800 rounded-lg p-4 shadow-sm">
          <h3 className="text-sm font-bold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
            <Tag className="w-4 h-4" />
            معلومات التذكرة
          </h3>

          <div className="space-y-3">
