import React from 'react';
import {
  ChartBarIcon,
  ClipboardDocumentListIcon,
  FolderIcon,
  ExclamationTriangleIcon,
  CheckCircleIcon,
  ClockIcon,
  ArrowTrendingUpIcon,
  CurrencyDollarIcon
} from '@heroicons/react/24/outline';
import { buildApiUrl } from '../../utils/urlHelper';
import { createStorageKey, getWithExpiry, setWithExpiry } from '../../utils/storage';

interface DashboardStats {
  tasks: {
    totalTasks: number;
    myTasks: number;
    tasksByStatus: {
      pending: number;
      inProgress: number;
      completed: number;
      cancelled: number;
    };
    myTasksByStatus: {
      pending: number;
      inProgress: number;
      completed: number;
      cancelled: number;
    };
    tasksByPriority: {
      urgent: number;
      high: number;
      medium: number;
      low: number;
    };
    overdueTasks: number;
    myOverdueTasks: number;
    completionRate: number;
    myCompletionRate: number;
  };
  projects: {
    totalProjects: number;
    activeProjects: number;
    completedProjects: number;
    planningProjects: number;
    onHoldProjects: number;
    averageProgress: number;
    totalBudget: number;
    totalSpent: number;
  };
  recentTasks: Array<{
    id: string;
    title: string;
    status: string;
    priority: string;
    projectName: string;
    assignedToName: string;
    createdAt: string;
  }>;
}

const formatPrice = (price: number) => {
  return new Intl.NumberFormat('ar-EG', {
    style: 'currency',
    currency: 'EGP'
  }).format(price);
};

const getStatusColor = (status: string) => {
  switch (status.toUpperCase()) {
    case 'PENDING': return 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300';
    case 'IN_PROGRESS': return 'bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-300';
    case 'COMPLETED': return 'bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300';
    case 'CANCELLED': return 'bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300';
    default: return 'bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-300';
  }
};

const getPriorityColor = (priority: string) => {
  switch (priority.toUpperCase()) {
    case 'URGENT': return 'bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300';
    case 'HIGH': return 'bg-orange-100 dark:bg-orange-900/30 text-orange-800 dark:text-orange-300';
    case 'MEDIUM': return 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300';
    case 'LOW': return 'bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300';
    default: return 'bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-300';
  }
};

const Dashboard: React.FC = () => {
  const [stats, setStats] = React.useState<DashboardStats | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  const CACHE_TTL_MS = 60_000;

  const cacheKey = React.useMemo(() => {
    try {
      const rawUser = localStorage.getItem('user');
      const parsedUser = rawUser ? JSON.parse(rawUser) : null;
      const userId = parsedUser?.id || parsedUser?.userId || 'unknown';
      const companyId = parsedUser?.companyId || parsedUser?.company?.id || 'unknown';
      return createStorageKey('tasks-dashboard', `${companyId}:${userId}`);
    } catch {
      return createStorageKey('tasks-dashboard', 'unknown');
    }
  }, []);

  const fetchDashboardStats = React.useCallback(async ({
    signal,
    background = false,
  }: {
    signal?: AbortSignal;
    background?: boolean;
  } = {}) => {
    try {
      if (!background) {
        setLoading(true);
        setError(null);
      }

      const token = localStorage.getItem('accessToken');
      const response = await fetch(buildApiUrl('tasks/dashboard-stats'), {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        signal
      });

      if (!response.ok) {
        throw new Error('فشل في تحميل الإحصائيات');
      }

      const data = await response.json();
      if (data.success) {
        setStats(data.data);
        setWithExpiry(cacheKey, data.data, CACHE_TTL_MS);
      } else if (!background) {
        setError(data.message || 'فشل في تحميل الإحصائيات');
      }
    } catch (error) {
      console.error('Error fetching dashboard stats:', error);
      if (!background) {
        setError('فشل في تحميل الإحصائيات');
      }
    } finally {
      if (!background) {
        setLoading(false);
      }
    }
  }, [cacheKey]);

  React.useEffect(() => {
    const controller = new AbortController();
    const cached = getWithExpiry<DashboardStats>(cacheKey);

    if (cached) {
      setStats(cached);
      setLoading(false);
      fetchDashboardStats({ signal: controller.signal, background: true });
    } else {
      fetchDashboardStats({ signal: controller.signal });
    }

    return () => controller.abort();
  }, [cacheKey, fetchDashboardStats]);

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 dark:border-indigo-400"></div>
      </div>
    );
  }

  if (error && !stats) {
    return <div className="text-center py-12">{error}</div>;
  }

  if (!stats) {
    return <div className="text-center py-12">فشل في تحميل الإحصائيات</div>;
  }

  return (
    <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
