import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import tokenManager from "../../utils/tokenManager";
import { buildApiUrl } from "../../utils/urlHelper";
import {
  ViewColumnsIcon,
  PlusIcon,
  ClockIcon,
  ChatBubbleLeftIcon,
  PaperClipIcon,
  UserCircleIcon,
  CalendarIcon,
  ArrowLeftIcon,
  FunnelIcon,
  PlayIcon,
  StopIcon,
} from "@heroicons/react/24/outline";

interface Task {
  id: string;
  title: string;
  description: string;
  status: string;
  priority: string;
  assignedUser: {
    firstName: string;
    lastName: string;
    avatar?: string;
  };
  dueDate: string | null;
  subtasksCount: number;
  completedSubtasks: number;
  commentsCount: number;
  attachmentsCount: number;
  color?: string;
  projectId?: string;
}

interface KanbanData {
  PENDING: Task[];
  IN_PROGRESS: Task[];
  COMPLETED: Task[];
  CANCELLED: Task[];
}

interface Project {
  id: string;
  name: string;
}

const KanbanBoard: React.FC = () => {
  const [kanbanData, setKanbanData] = useState<KanbanData>({
    PENDING: [],
    IN_PROGRESS: [],
    COMPLETED: [],
    CANCELLED: [],
  });
  const [loading, setLoading] = useState(true);
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProject, setSelectedProject] = useState<string>("");
  const [draggedTask, setDraggedTask] = useState<Task | null>(null);
  const [runningTimer, setRunningTimer] = useState<any>(null);
  const getAccessToken = (): string | null => tokenManager.getAccessToken();

  const columns = [
    {
      id: "PENDING",
      title: "في الانتظار",
      color: "bg-yellow-500",
      bgColor: "bg-yellow-50 dark:bg-yellow-900/20",
    },
    {
      id: "IN_PROGRESS",
      title: "قيد التنفيذ",
      color: "bg-blue-500",
      bgColor: "bg-blue-50 dark:bg-blue-900/20",
    },
    {
      id: "COMPLETED",
      title: "مكتمل",
      color: "bg-green-500",
      bgColor: "bg-green-50 dark:bg-green-900/20",
    },
    {
      id: "CANCELLED",
      title: "ملغي",
      color: "bg-red-500",
      bgColor: "bg-red-50 dark:bg-red-900/20",
    },
  ];

  useEffect(() => {
    fetchKanbanTasks();
    fetchProjects();
    fetchRunningTimer();
  }, [selectedProject]);

  const fetchKanbanTasks = async () => {
    try {
      setLoading(true);
      const token = getAccessToken();
      let url = "tasks/kanban";
      if (selectedProject) {
        url += `?projectId=${selectedProject}`;
      }

      const response = await fetch(buildApiUrl(url), {
        headers: { Authorization: `Bearer ${token}` },
      });

      const data = await response.json();
      if (data.success) {
        setKanbanData(data.data);
      }
    } catch (error) {
      console.error("Error fetching kanban tasks:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchProjects = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("projects"), {
        headers: { Authorization: `Bearer ${token}` },
      });

      const data = await response.json();
      if (data.success) {
        setProjects(data.data);
      }
    } catch (error) {
      console.error("Error fetching projects:", error);
    }
  };

  const fetchRunningTimer = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("tasks/running-timer"), {
        headers: { Authorization: `Bearer ${token}` },
      });

      const data = await response.json();
      if (data.success && data.data) {
        setRunningTimer(data.data);
      }
    } catch (error) {
      console.error("Error fetching running timer:", error);
    }
  };

  const handleDragStart = (e: React.DragEvent, task: Task) => {
    setDraggedTask(task);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = async (e: React.DragEvent, newStatus: string) => {
    e.preventDefault();
    if (!draggedTask || draggedTask.status === newStatus) {
      setDraggedTask(null);
      return;
    }

    try {
      const token = getAccessToken();
      const response = await fetch(
        buildApiUrl(`tasks/${draggedTask.id}/order`),
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            newStatus,
            newOrder: kanbanData[newStatus as keyof KanbanData].length,
          }),
        },
      );

      const data = await response.json();
      if (data.success) {
        // Update local state
        setKanbanData((prev) => {
          const oldStatus = draggedTask.status as keyof KanbanData;
          const newKanban = { ...prev };

          // Remove from old column
          newKanban[oldStatus] = prev[oldStatus].filter(
            (t) => t.id !== draggedTask.id,
          );

          // Add to new column
          const updatedTask = { ...draggedTask, status: newStatus };
          newKanban[newStatus as keyof KanbanData] = [
            ...prev[newStatus as keyof KanbanData],
            updatedTask,
          ];

          return newKanban;
        });
      }
    } catch (error) {
      console.error("Error updating task status:", error);
    }

    setDraggedTask(null);
  };

  const startTimer = async (taskId: string) => {
    try {
      const token = getAccessToken();
      const response = await fetch(
        buildApiUrl(`tasks/${taskId}/time-tracking/start`),
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({}),
        },
      );

      const data = await response.json();
      if (data.success) {
        setRunningTimer(data.data);
      } else {
        alert(data.error || "فشل في بدء المؤقت");
      }
    } catch (error) {
      console.error("Error starting timer:", error);
    }
  };

  const stopTimer = async () => {
    if (!runningTimer) return;

    try {
      const token = getAccessToken();
      const response = await fetch(
        buildApiUrl(`tasks/time-tracking/${runningTimer.id}/stop`),
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
        },
      );

      const data = await response.json();
      if (data.success) {
        setRunningTimer(null);
        alert(data.message);
      }
    } catch (error) {
      console.error("Error stopping timer:", error);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "URGENT":
        return "border-l-red-500";
      case "HIGH":
        return "border-l-orange-500";
      case "MEDIUM":
        return "border-l-yellow-500";
      case "LOW":
        return "border-l-green-500";
      default:
        return "border-l-gray-500";
    }
  };

  const getPriorityBadge = (priority: string) => {
    const colors: Record<string, string> = {
      URGENT: "bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300",
      HIGH: "bg-orange-100 dark:bg-orange-900/30 text-orange-800 dark:text-orange-300",
      MEDIUM:
        "bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300",
      LOW: "bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300",
    };
    const labels: Record<string, string> = {
      URGENT: "عاجل",
      HIGH: "عالي",
      MEDIUM: "متوسط",
      LOW: "منخفض",
    };
    return (
      <span
        className={`text-xs px-2 py-0.5 rounded-full ${colors[priority] || "bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-300"}`}
      >
        {labels[priority] || priority}
      </span>
    );
  };

  const isOverdue = (dueDate: string | null) => {
    if (!dueDate) return false;
    return new Date(dueDate) < new Date();
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 dark:border-indigo-400"></div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 px-6 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4 space-x-reverse">
            <Link
              to="/tasks"
              className="flex items-center text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200"
            >
              <ArrowLeftIcon className="h-5 w-5 ml-2" />
              العودة للقائمة
            </Link>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 flex items-center">
              <ViewColumnsIcon className="h-7 w-7 text-indigo-600 dark:text-indigo-400 ml-2" />
              لوحة Kanban
            </h1>
          </div>

          <div className="flex items-center space-x-4 space-x-reverse">
            {/* Running Timer */}
            {runningTimer && (
              <div className="flex items-center bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300 px-4 py-2 rounded-lg">
                <ClockIcon className="h-5 w-5 ml-2 animate-pulse" />
                <span className="text-sm font-medium ml-2">
                  {runningTimer.task?.title}
                </span>
                <button
                  onClick={stopTimer}
                  className="mr-2 p-1 hover:bg-green-200 dark:hover:bg-green-900/50 rounded"
                >
                  <StopIcon className="h-4 w-4" />
                </button>
              </div>
            )}

            {/* Project Filter */}
            <div className="flex items-center">
              <FunnelIcon className="h-5 w-5 text-gray-400 dark:text-gray-500 ml-2" />
              <select
                value={selectedProject}
                onChange={(e) => setSelectedProject(e.target.value)}
                className="border border-gray-300 dark:border-gray-700 rounded-md px-3 py-2 text-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              >
                <option value="">جميع المشاريع</option>
                {projects.map((project) => (
                  <option key={project.id} value={project.id}>
                    {project.name}
                  </option>
                ))}
              </select>
            </div>

            <Link
              to="/tasks"
              className="inline-flex items-center px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-600"
            >
              <PlusIcon className="h-5 w-5 ml-2" />
              مهمة جديدة
            </Link>
          </div>
        </div>
      </div>

      {/* Kanban Board */}
      <div className="flex-1 overflow-x-auto p-6 bg-gray-100 dark:bg-gray-900">
        <div className="flex space-x-4 space-x-reverse h-full min-w-max">
          {columns.map((column) => (
            <div
              key={column.id}
              className="w-80 flex flex-col bg-gray-50 dark:bg-gray-800 rounded-lg"
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, column.id)}
            >
              {/* Column Header */}
              <div className={`p-4 rounded-t-lg ${column.bgColor}`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center">
                    <div
                      className={`w-3 h-3 rounded-full ${column.color} ml-2`}
                    ></div>
                    <h3 className="font-semibold text-gray-800 dark:text-gray-200">
                      {column.title}
                    </h3>
                  </div>
                  <span className="bg-white dark:bg-gray-700 px-2 py-1 rounded-full text-sm font-medium text-gray-600 dark:text-gray-300">
                    {kanbanData[column.id as keyof KanbanData].length}
                  </span>
                </div>
              </div>

              {/* Tasks */}
              <div className="flex-1 p-2 space-y-2 overflow-y-auto max-h-[calc(100vh-280px)]">
                {kanbanData[column.id as keyof KanbanData].map((task) => (
                  <div
                    key={task.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, task)}
                    className={`bg-white dark:bg-gray-800 rounded-lg shadow-sm border-l-4 ${getPriorityColor(task.priority)} p-4 cursor-move hover:shadow-md transition-shadow ${
                      draggedTask?.id === task.id ? "opacity-50" : ""
                    }`}
                  >
                    {/* Task Title */}
                    <Link
                      to={`/tasks/${task.id}`}
                      className="font-medium text-gray-900 dark:text-gray-100 hover:text-indigo-600 dark:hover:text-indigo-400 block mb-2"
                    >
                      {task.title}
                    </Link>

                    {/* Task Description */}
                    {task.description && (
                      <p className="text-sm text-gray-500 dark:text-gray-400 mb-3 line-clamp-2">
                        {task.description}
                      </p>
                    )}

                    {/* Priority & Due Date */}
                    <div className="flex items-center justify-between mb-3">
                      {getPriorityBadge(task.priority)}
                      {task.dueDate && (
                        <span
                          className={`text-xs flex items-center ${isOverdue(task.dueDate) ? "text-red-600 dark:text-red-400" : "text-gray-500 dark:text-gray-400"}`}
                        >
                          <CalendarIcon className="h-3 w-3 ml-1" />
                          {new Date(task.dueDate).toLocaleDateString("ar-EG")}
                        </span>
                      )}
                    </div>

                    {/* Subtasks Progress */}
                    {task.subtasksCount > 0 && (
                      <div className="mb-3">
                        <div className="flex items-center justify-between text-xs text-gray-500 dark:text-gray-400 mb-1">
                          <span>المهام الفرعية</span>
                          <span>
                            {task.completedSubtasks}/{task.subtasksCount}
                          </span>
                        </div>
                        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-1.5">
                          <div
                            className="bg-indigo-600 dark:bg-indigo-500 h-1.5 rounded-full"
                            style={{
                              width: `${(task.completedSubtasks / task.subtasksCount) * 100}%`,
                            }}
                          ></div>
                        </div>
                      </div>
                    )}

                    {/* Footer */}
                    <div className="flex items-center justify-between pt-2 border-t border-gray-100 dark:border-gray-700">
                      {/* Assigned User */}
                      <div className="flex items-center">
                        {task.assignedUser?.avatar ? (
                          <img
                            src={task.assignedUser.avatar}
                            alt=""
                            className="h-6 w-6 rounded-full"
                          />
                        ) : (
                          <UserCircleIcon className="h-6 w-6 text-gray-400 dark:text-gray-500" />
                        )}
                        <span className="text-xs text-gray-500 dark:text-gray-400 mr-1">
                          {task.assignedUser?.firstName}
                        </span>
                      </div>

                      {/* Meta Info */}
                      <div className="flex items-center space-x-2 space-x-reverse">
                        {task.commentsCount > 0 && (
                          <span className="flex items-center text-xs text-gray-400 dark:text-gray-500">
                            <ChatBubbleLeftIcon className="h-4 w-4 ml-1" />
                            {task.commentsCount}
                          </span>
                        )}
                        {task.attachmentsCount > 0 && (
                          <span className="flex items-center text-xs text-gray-400 dark:text-gray-500">
                            <PaperClipIcon className="h-4 w-4 ml-1" />
                            {task.attachmentsCount}
                          </span>
                        )}
                        {/* Timer Button */}
                        {column.id !== "COMPLETED" &&
                          column.id !== "CANCELLED" && (
                            <button
                              onClick={(e) => {
                                e.preventDefault();
                                if (runningTimer?.taskId === task.id) {
                                  stopTimer();
                                } else if (!runningTimer) {
                                  startTimer(task.id);
                                }
                              }}
                              className={`p-1 rounded ${
                                runningTimer?.taskId === task.id
                                  ? "bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400"
                                  : "hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-400 dark:text-gray-500"
                              }`}
                              title={
                                runningTimer?.taskId === task.id
                                  ? "إيقاف المؤقت"
                                  : "بدء المؤقت"
                              }
                            >
                              {runningTimer?.taskId === task.id ? (
                                <StopIcon className="h-4 w-4" />
                              ) : (
                                <PlayIcon className="h-4 w-4" />
                              )}
                            </button>
                          )}
                      </div>
                    </div>
                  </div>
                ))}

                {/* Empty State */}
                {kanbanData[column.id as keyof KanbanData].length === 0 && (
                  <div className="text-center py-8 text-gray-400 dark:text-gray-500">
                    <p className="text-sm">لا توجد مهام</p>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default KanbanBoard;

import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import tokenManager from "../../utils/tokenManager";
import { buildApiUrl } from "../../utils/urlHelper";
import {
  BellIcon,
  CheckIcon,
  ClockIcon,
  ChatBubbleLeftIcon,
  UserPlusIcon,
  ExclamationTriangleIcon,
  CheckCircleIcon,
} from "@heroicons/react/24/outline";

interface Notification {
  id: string;
  type: string;
  title: string;
  message: string;
  taskId: string | null;
  projectId: string | null;
  link: string | null;
  isRead: boolean;
  readAt: string | null;
  createdAt: string;
}

const TaskNotifications: React.FC = () => {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<"all" | "unread">("all");
  const getAccessToken = (): string | null => tokenManager.getAccessToken();

  useEffect(() => {
    fetchNotifications();
  }, [filter]);

  const fetchNotifications = async () => {
    try {
      setLoading(true);
      const token = getAccessToken();
      const url =
        filter === "unread"
          ? "tasks/notifications?unreadOnly=true"
          : "tasks/notifications";

      const response = await fetch(buildApiUrl(url), {
        headers: { Authorization: `Bearer ${token}` },
      });

      const data = await response.json();
      if (data.success) {
        setNotifications(data.data.notifications);
        setUnreadCount(data.data.unreadCount);
      }
    } catch (error) {
      console.error("Error fetching notifications:", error);
    } finally {
      setLoading(false);
    }
  };

  const markAsRead = async (notificationId: string) => {
    try {
      const token = getAccessToken();
      await fetch(buildApiUrl(`tasks/notifications/${notificationId}/read`), {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}` },
      });
      fetchNotifications();
    } catch (error) {
      console.error("Error marking notification as read:", error);
    }
  };

  const markAllAsRead = async () => {
    try {
      const token = getAccessToken();
      await fetch(buildApiUrl("tasks/notifications/read-all"), {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}` },
      });
      fetchNotifications();
    } catch (error) {
      console.error("Error marking all notifications as read:", error);
    }
  };

  const getNotificationIcon = (type: string) => {
    switch (type) {
      case "task_assigned":
        return <UserPlusIcon className="h-5 w-5 text-blue-500" />;
      case "due_soon":
        return <ClockIcon className="h-5 w-5 text-yellow-500" />;
      case "overdue":
        return <ExclamationTriangleIcon className="h-5 w-5 text-red-500" />;
      case "comment":
      case "mention":
        return <ChatBubbleLeftIcon className="h-5 w-5 text-indigo-500" />;
      case "status_changed":
        return <CheckCircleIcon className="h-5 w-5 text-green-500" />;
      default:
        return <BellIcon className="h-5 w-5 text-gray-500" />;
    }
  };

  const formatTime = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return "الآن";
    if (diffMins < 60) return `منذ ${diffMins} دقيقة`;
    if (diffHours < 24) return `منذ ${diffHours} ساعة`;
    if (diffDays < 7) return `منذ ${diffDays} يوم`;
    return date.toLocaleDateString("ar-EG");
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 dark:border-indigo-400"></div>
      </div>
    );
  }

  return (
    <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center">
            <BellIcon className="h-8 w-8 text-indigo-600 dark:text-indigo-400 ml-3" />
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
                الإشعارات
              </h1>
              {unreadCount > 0 && (
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  {unreadCount} إشعار غير مقروء
                </p>
              )}
            </div>
          </div>
          {unreadCount > 0 && (
            <button
              onClick={markAllAsRead}
              className="text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-300 text-sm flex items-center"
            >
              <CheckIcon className="h-4 w-4 ml-1" />
              تحديد الكل كمقروء
            </button>
          )}
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow mb-6">
        <div className="border-b border-gray-200 dark:border-gray-700">
          <nav className="flex -mb-px">
            <button
              onClick={() => setFilter("all")}
              className={`py-3 px-6 text-sm font-medium border-b-2 ${
                filter === "all"
                  ? "border-indigo-500 dark:border-indigo-400 text-indigo-600 dark:text-indigo-400"
                  : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300"
              }`}
            >
              الكل
            </button>
            <button
              onClick={() => setFilter("unread")}
              className={`py-3 px-6 text-sm font-medium border-b-2 ${
                filter === "unread"
                  ? "border-indigo-500 dark:border-indigo-400 text-indigo-600 dark:text-indigo-400"
                  : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300"
              }`}
            >
              غير مقروء
              {unreadCount > 0 && (
                <span className="mr-2 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 px-2 py-0.5 rounded-full text-xs">
                  {unreadCount}
                </span>
              )}
            </button>
          </nav>
        </div>
      </div>

      {/* Notifications List */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow divide-y divide-gray-100 dark:divide-gray-700">
        {notifications.length === 0 ? (
          <div className="text-center py-12">
            <BellIcon className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-4" />
            <p className="text-gray-500 dark:text-gray-400">لا توجد إشعارات</p>
          </div>
        ) : (
          notifications.map((notification) => (
            <div
              key={notification.id}
              className={`p-4 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors ${
                !notification.isRead ? "bg-indigo-50 dark:bg-indigo-900/20" : ""
              }`}
            >
              <div className="flex items-start">
                <div className="flex-shrink-0 mt-1">
                  {getNotificationIcon(notification.type)}
                </div>
                <div className="mr-3 flex-1">
                  <div className="flex items-center justify-between">
                    <p
                      className={`text-sm font-medium ${!notification.isRead ? "text-gray-900 dark:text-gray-100" : "text-gray-700 dark:text-gray-300"}`}
                    >
                      {notification.title}
                    </p>
                    <div className="flex items-center space-x-2 space-x-reverse">
                      <span className="text-xs text-gray-500 dark:text-gray-400">
                        {formatTime(notification.createdAt)}
                      </span>
                      {!notification.isRead && (
                        <button
                          onClick={() => markAsRead(notification.id)}
                          className="p-1 text-gray-400 dark:text-gray-500 hover:text-indigo-600 dark:hover:text-indigo-400"
                          title="تحديد كمقروء"
                        >
                          <CheckIcon className="h-4 w-4" />
                        </button>
                      )}
                    </div>
                  </div>
                  <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                    {notification.message}
                  </p>
                  {notification.link && (
                    <Link
                      to={notification.link}
                      className="text-sm text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-300 mt-2 inline-block"
                    >
                      عرض التفاصيل ←
                    </Link>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default TaskNotifications;

import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import tokenManager from "../../utils/tokenManager";
import { buildApiUrl } from "../../utils/urlHelper";
import {
  DocumentDuplicateIcon,
  PlusIcon,
  ArrowLeftIcon,
  PencilIcon,
  TrashIcon,
  XMarkIcon,
  ClipboardDocumentIcon,
  TagIcon,
  ClockIcon,
  FolderIcon,
} from "@heroicons/react/24/outline";

interface TaskTemplate {
  id: string;
  name: string;
  description: string;
  taskTitle: string;
  taskDescription: string;
  priority: string;
  type: string;
  estimatedHours: number;
  tags: string[];
  projectId: string | null;
  projectName: string | null;
  categoryId: string | null;
  categoryName: string | null;
  createdAt: string;
  usageCount: number;
}

interface Project {
  id: string;
  name: string;
}

interface Category {
  id: string;
  name: string;
}

const TaskTemplates: React.FC = () => {
  const navigate = useNavigate();
  const [templates, setTemplates] = useState<TaskTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<TaskTemplate | null>(
    null,
  );
  const [projects, setProjects] = useState<Project[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);

  const [newTemplate, setNewTemplate] = useState({
    name: "",
    description: "",
    taskTitle: "",
    taskDescription: "",
    priority: "medium",
    type: "general",
    estimatedHours: 0,
    tags: [] as string[],
    projectId: "",
    categoryId: "",
  });

  const [tagInput, setTagInput] = useState("");
  const getAccessToken = (): string | null => tokenManager.getAccessToken();

  useEffect(() => {
    fetchTemplates();
    fetchProjects();
    fetchCategories();
  }, []);

  const fetchTemplates = async () => {
    try {
      setLoading(true);
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("tasks/templates"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setTemplates(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching templates:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchProjects = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("projects"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setProjects(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching projects:", error);
    }
  };

  const fetchCategories = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("tasks/categories/list"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setCategories(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const createTemplate = async () => {
    if (!newTemplate.name.trim() || !newTemplate.taskTitle.trim()) {
      alert("اسم القالب وعنوان المهمة مطلوبان");
      return;
    }

    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("tasks/templates"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(newTemplate),
      });

      const data = await response.json();
      if (data.success) {
        fetchTemplates();
        setShowCreateModal(false);
        resetForm();
        alert("تم إنشاء القالب بنجاح");
      } else {
        alert(data.error || "فشل في إنشاء القالب");
      }
    } catch (error) {
      console.error("Error creating template:", error);
      alert("فشل في إنشاء القالب");
    }
  };

  const updateTemplate = async () => {
    if (!editingTemplate) return;

    try {
      const token = getAccessToken();
      const response = await fetch(
        buildApiUrl(`tasks/templates/${editingTemplate.id}`),
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(editingTemplate),
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchTemplates();
        setShowEditModal(false);
        setEditingTemplate(null);
        alert("تم تحديث القالب بنجاح");
      } else {
        alert(data.error || "فشل في تحديث القالب");
      }
    } catch (error) {
      console.error("Error updating template:", error);
      alert("فشل في تحديث القالب");
    }
  };

  const deleteTemplate = async (templateId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا القالب؟")) return;

    try {
      const token = getAccessToken();
      const response = await fetch(
        buildApiUrl(`tasks/templates/${templateId}`),
        {
          method: "DELETE",
          headers: { Authorization: `Bearer ${token}` },
        },
      );

      const data = await response.json();
      if (data.success) {
        fetchTemplates();
        alert("تم حذف القالب بنجاح");
      } else {
        alert(data.error || "فشل في حذف القالب");
      }
    } catch (error) {
      console.error("Error deleting template:", error);
      alert("فشل في حذف القالب");
    }
  };

  const useTemplate = async (template: TaskTemplate) => {
    // Navigate to tasks page with template data pre-filled
    navigate("/tasks", {
      state: {
        openCreateModal: true,
        templateData: {
          title: template.taskTitle,
          description: template.taskDescription,
          priority: template.priority,
          type: template.type,
          estimatedHours: template.estimatedHours,
          tags: template.tags,
          projectId: template.projectId,
          categoryId: template.categoryId,
        },
      },
    });
  };

  const resetForm = () => {
    setNewTemplate({
      name: "",
      description: "",
      taskTitle: "",
      taskDescription: "",
      priority: "medium",
      type: "general",
      estimatedHours: 0,
      tags: [],
      projectId: "",
      categoryId: "",
    });
    setTagInput("");
  };

  const addTag = (tagsArray: string[], setTags: (tags: string[]) => void) => {
    if (tagInput.trim() && !tagsArray.includes(tagInput.trim())) {
      setTags([...tagsArray, tagInput.trim()]);
      setTagInput("");
    }
  };

  const removeTag = (
    tag: string,
    tagsArray: string[],
    setTags: (tags: string[]) => void,
  ) => {
    setTags(tagsArray.filter((t) => t !== tag));
  };

  const getPriorityColor = (priority: string) => {
    switch (priority?.toLowerCase()) {
      case "urgent":
        return "bg-red-100 dark:bg-red-900/50 text-red-800 dark:text-red-300";
      case "high":
        return "bg-orange-100 dark:bg-orange-900/50 text-orange-800 dark:text-orange-300";
      case "medium":
        return "bg-yellow-100 dark:bg-yellow-900/50 text-yellow-800 dark:text-yellow-300";
      case "low":
        return "bg-green-100 dark:bg-green-900/50 text-green-800 dark:text-green-300";
      default:
        return "bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-300";
    }
  };

  const getPriorityText = (priority: string) => {
    switch (priority?.toLowerCase()) {
      case "urgent":
        return "عاجل";
      case "high":
        return "عالي";
      case "medium":
        return "متوسط";
      case "low":
        return "منخفض";
      default:
        return priority;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 bg-white dark:bg-gray-900">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 dark:border-indigo-400"></div>
      </div>
    );
  }

  return (
    <div className="w-full px-4 sm:px-6 lg:px-8 py-8 bg-white dark:bg-gray-900 min-h-screen">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4 space-x-reverse">
            <Link
              to="/tasks"
              className="flex items-center text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200 dark:text-gray-100"
            >
              <ArrowLeftIcon className="h-5 w-5 ml-2" />
              العودة
            </Link>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 flex items-center">
              <DocumentDuplicateIcon className="h-7 w-7 text-indigo-600 ml-2" />
              قوالب المهام
            </h1>
          </div>

          <button
            onClick={() => setShowCreateModal(true)}
            className="inline-flex items-center px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-600 transition-colors"
          >
            <PlusIcon className="h-5 w-5 ml-2" />
            قالب جديد
          </button>
        </div>
        <p className="mt-2 text-gray-600 dark:text-gray-400">
          أنشئ قوالب للمهام المتكررة لتوفير الوقت
        </p>
      </div>

      {/* Templates Grid */}
      {templates.length === 0 ? (
        <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-lg shadow border border-gray-200 dark:border-gray-700">
          <DocumentDuplicateIcon className="h-12 w-12 mx-auto mb-4 text-gray-300 dark:text-gray-600" />
          <p className="text-gray-500 dark:text-gray-400 mb-4">
            لا توجد قوالب بعد
          </p>
          <button
            onClick={() => setShowCreateModal(true)}
            className="inline-flex items-center px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
          >
            <PlusIcon className="h-5 w-5 ml-2" />
            إنشاء أول قالب
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {templates.map((template) => (
            <div
              key={template.id}
              className="bg-white dark:bg-gray-800 rounded-lg shadow hover:shadow-md transition-shadow border border-gray-200 dark:border-gray-700"
            >
              <div className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h3 className="text-lg font-medium text-gray-900 dark:text-gray-100">
                      {template.name}
                    </h3>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                      {template.description}
                    </p>
                  </div>
                  <span
                    className={`px-2 py-1 text-xs rounded-full ${getPriorityColor(template.priority)}`}
                  >
                    {getPriorityText(template.priority)}
                  </span>
                </div>

                <div className="bg-gray-50 dark:bg-gray-700/50 rounded-lg p-3 mb-4">
                  <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    عنوان المهمة:
                  </p>
                  <p className="text-sm text-gray-900 dark:text-gray-100">
                    {template.taskTitle}
                  </p>
                  {template.taskDescription && (
                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 line-clamp-2">
                      {template.taskDescription}
                    </p>
                  )}
                </div>

                <div className="flex flex-wrap gap-2 mb-4">
                  {template.estimatedHours > 0 && (
                    <span className="inline-flex items-center text-xs text-gray-500 dark:text-gray-400">
                      <ClockIcon className="h-3 w-3 ml-1" />
                      {template.estimatedHours} ساعة
                    </span>
                  )}
                  {template.projectName && (
                    <span className="inline-flex items-center text-xs text-gray-500 dark:text-gray-400">
                      <FolderIcon className="h-3 w-3 ml-1" />
                      {template.projectName}
                    </span>
                  )}
                  {template.categoryName && (
                    <span className="inline-flex items-center text-xs text-gray-500 dark:text-gray-400">
                      <TagIcon className="h-3 w-3 ml-1" />
                      {template.categoryName}
                    </span>
                  )}
                </div>

                {template.tags &&
                  Array.isArray(template.tags) &&
                  template.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1 mb-4">
                      {template.tags.map((tag, index) => (
                        <span
                          key={index}
                          className="px-2 py-0.5 text-xs bg-indigo-100 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300 rounded"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                  )}

                <div className="flex items-center justify-between pt-4 border-t border-gray-200 dark:border-gray-700">
                  <span className="text-xs text-gray-400 dark:text-gray-500">
                    استُخدم {template.usageCount || 0} مرة
                  </span>
                  <div className="flex items-center space-x-2 space-x-reverse">
                    <button
                      onClick={() => useTemplate(template)}
                      className="inline-flex items-center px-3 py-1.5 text-sm bg-indigo-600 dark:bg-indigo-500 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-600 transition-colors"
                    >
                      <ClipboardDocumentIcon className="h-4 w-4 ml-1" />
                      استخدام
                    </button>
                    <button
                      onClick={() => {
                        setEditingTemplate(template);
                        setShowEditModal(true);
                      }}
                      className="p-1.5 text-gray-400 dark:text-gray-500 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded transition-colors"
                    >
                      <PencilIcon className="h-4 w-4" />
                    </button>
                    <button
                      onClick={() => deleteTemplate(template.id)}
                      className="p-1.5 text-gray-400 dark:text-gray-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30 rounded transition-colors"
                    >
                      <TrashIcon className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Template Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 dark:bg-black dark:bg-opacity-70 overflow-y-auto h-full w-full z-50">
          <div className="relative top-10 mx-auto p-5 border border-gray-200 dark:border-gray-700 w-full max-w-2xl shadow-lg rounded-md bg-white dark:bg-gray-800">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-medium text-gray-900 dark:text-gray-100">
                إنشاء قالب جديد
              </h3>
              <button
                onClick={() => {
                  setShowCreateModal(false);
                  resetForm();
                }}
                className="text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300 dark:text-gray-400"
              >
                <XMarkIcon className="h-6 w-6" />
              </button>
            </div>

            <div className="space-y-4 max-h-[70vh] overflow-y-auto">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    اسم القالب *
                  </label>
                  <input
                    type="text"
                    value={newTemplate.name}
                    onChange={(e) =>
                      setNewTemplate({ ...newTemplate, name: e.target.value })
                    }
                    placeholder="مثال: مهمة مراجعة أسبوعية"
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 placeholder-gray-400 dark:placeholder-gray-500"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    وصف القالب
                  </label>
                  <input
                    type="text"
                    value={newTemplate.description}
                    onChange={(e) =>
                      setNewTemplate({
                        ...newTemplate,
                        description: e.target.value,
                      })
                    }
                    placeholder="وصف مختصر للقالب"
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 placeholder-gray-400 dark:placeholder-gray-500"
                  />
                </div>

                <div className="col-span-2 border-t border-gray-200 dark:border-gray-700 pt-4">
                  <h4 className="font-medium text-gray-900 dark:text-gray-100 mb-3">
                    تفاصيل المهمة
                  </h4>
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    عنوان المهمة *
                  </label>
                  <input
                    type="text"
                    value={newTemplate.taskTitle}
                    onChange={(e) =>
                      setNewTemplate({
                        ...newTemplate,
                        taskTitle: e.target.value,
                      })
                    }
                    placeholder="عنوان المهمة التي ستُنشأ"
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 placeholder-gray-400 dark:placeholder-gray-500"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    وصف المهمة
                  </label>
                  <textarea
                    value={newTemplate.taskDescription}
                    onChange={(e) =>
                      setNewTemplate({
                        ...newTemplate,
                        taskDescription: e.target.value,
                      })
                    }
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 resize-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    الأولوية
                  </label>
                  <select
                    value={newTemplate.priority}
                    onChange={(e) =>
                      setNewTemplate({
                        ...newTemplate,
                        priority: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400"
                    style={{ colorScheme: "dark" }}
                  >
                    <option
                      value="low"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      منخفض
                    </option>
                    <option
                      value="medium"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      متوسط
                    </option>
                    <option
                      value="high"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      عالي
                    </option>
                    <option
                      value="urgent"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      عاجل
                    </option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    الساعات المقدرة
                  </label>
                  <input
                    type="number"
                    min="0"
                    value={newTemplate.estimatedHours}
                    onChange={(e) =>
                      setNewTemplate({
                        ...newTemplate,
                        estimatedHours: parseInt(e.target.value) || 0,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    المشروع
                  </label>
                  <select
                    value={newTemplate.projectId}
                    onChange={(e) =>
                      setNewTemplate({
                        ...newTemplate,
                        projectId: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400"
                    style={{ colorScheme: "dark" }}
                  >
                    <option
                      value=""
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      بدون مشروع
                    </option>
                    {projects.map((project) => (
                      <option
                        key={project.id}
                        value={project.id}
                        className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                      >
                        {project.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    القسم
                  </label>
                  <select
                    value={newTemplate.categoryId}
                    onChange={(e) =>
                      setNewTemplate({
                        ...newTemplate,
                        categoryId: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400"
                    style={{ colorScheme: "dark" }}
                  >
                    <option
                      value=""
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      بدون قسم
                    </option>
                    {categories.map((category) => (
                      <option
                        key={category.id}
                        value={category.id}
                        className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                      >
                        {category.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    الوسوم
                  </label>
                  <div className="flex items-center space-x-2 space-x-reverse">
                    <input
                      type="text"
                      value={tagInput}
                      onChange={(e) => setTagInput(e.target.value)}
                      onKeyPress={(e) =>
                        e.key === "Enter" &&
                        (e.preventDefault(),
                        addTag(newTemplate.tags, (tags) =>
                          setNewTemplate({ ...newTemplate, tags }),
                        ))
                      }
                      placeholder="أضف وسم واضغط Enter"
                      className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 placeholder-gray-400 dark:placeholder-gray-500"
                    />
                    <button
                      type="button"
                      onClick={() =>
                        addTag(newTemplate.tags, (tags) =>
                          setNewTemplate({ ...newTemplate, tags }),
                        )
                      }
                      className="px-3 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                    >
                      إضافة
                    </button>
                  </div>
                  {newTemplate.tags &&
                    Array.isArray(newTemplate.tags) &&
                    newTemplate.tags.length > 0 && (
                      <div className="flex flex-wrap gap-2 mt-2">
                        {newTemplate.tags.map((tag, index) => (
                          <span
                            key={index}
                            className="inline-flex items-center px-2 py-1 bg-indigo-100 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300 rounded text-sm"
                          >
                            {tag}
                            <button
                              type="button"
                              onClick={() =>
                                removeTag(tag, newTemplate.tags, (tags) =>
                                  setNewTemplate({ ...newTemplate, tags }),
                                )
                              }
                              className="mr-1 text-indigo-500 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-200"
                            >
                              ×
                            </button>
                          </span>
                        ))}
                      </div>
                    )}
                </div>
              </div>
            </div>

            <div className="mt-6 flex justify-end space-x-2 space-x-reverse">
              <button
                onClick={() => {
                  setShowCreateModal(false);
                  resetForm();
                }}
                className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
              >
                إلغاء
              </button>
              <button
                onClick={createTemplate}
                className="px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-600 transition-colors"
              >
                إنشاء القالب
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Template Modal */}
      {showEditModal && editingTemplate && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 dark:bg-black dark:bg-opacity-70 overflow-y-auto h-full w-full z-50">
          <div className="relative top-10 mx-auto p-5 border border-gray-200 dark:border-gray-700 w-full max-w-2xl shadow-lg rounded-md bg-white dark:bg-gray-800">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-medium text-gray-900 dark:text-gray-100">
                تعديل القالب
              </h3>
              <button
                onClick={() => {
                  setShowEditModal(false);
                  setEditingTemplate(null);
                }}
                className="text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300 dark:text-gray-400"
              >
                <XMarkIcon className="h-6 w-6" />
              </button>
            </div>

            <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-gray-300 dark:scrollbar-thumb-gray-600 scrollbar-track-transparent">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    اسم القالب *
                  </label>
                  <input
                    type="text"
                    value={editingTemplate.name}
                    onChange={(e) =>
                      setEditingTemplate({
                        ...editingTemplate,
                        name: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 placeholder-gray-400 dark:placeholder-gray-500"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    وصف القالب
                  </label>
                  <input
                    type="text"
                    value={editingTemplate.description}
                    onChange={(e) =>
                      setEditingTemplate({
                        ...editingTemplate,
                        description: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 placeholder-gray-400 dark:placeholder-gray-500"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    عنوان المهمة *
                  </label>
                  <input
                    type="text"
                    value={editingTemplate.taskTitle}
                    onChange={(e) =>
                      setEditingTemplate({
                        ...editingTemplate,
                        taskTitle: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 placeholder-gray-400 dark:placeholder-gray-500"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    وصف المهمة
                  </label>
                  <textarea
                    value={editingTemplate.taskDescription}
                    onChange={(e) =>
                      setEditingTemplate({
                        ...editingTemplate,
                        taskDescription: e.target.value,
                      })
                    }
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 resize-none placeholder-gray-400 dark:placeholder-gray-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    الأولوية
                  </label>
                  <select
                    value={editingTemplate.priority}
                    onChange={(e) =>
                      setEditingTemplate({
                        ...editingTemplate,
                        priority: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400"
                    style={{ colorScheme: "dark" }}
                  >
                    <option
                      value="low"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      منخفض
                    </option>
                    <option
                      value="medium"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      متوسط
                    </option>
                    <option
                      value="high"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      عالي
                    </option>
                    <option
                      value="urgent"
                      className="bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                    >
                      عاجل
                    </option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    الساعات المقدرة
                  </label>
                  <input
                    type="number"
                    min="0"
                    value={editingTemplate.estimatedHours}
                    onChange={(e) =>
                      setEditingTemplate({
                        ...editingTemplate,
                        estimatedHours: parseInt(e.target.value) || 0,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400"
                  />
                </div>
              </div>
            </div>

            <div className="mt-6 flex justify-end space-x-2 space-x-reverse">
              <button
                onClick={() => {
                  setShowEditModal(false);
                  setEditingTemplate(null);
                }}
                className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
              >
                إلغاء
              </button>
              <button
                onClick={updateTemplate}
                className="px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-600 transition-colors"
              >
                حفظ التغييرات
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskTemplates;

import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import tokenManager from "../../utils/tokenManager";
import { buildApiUrl } from "../../utils/urlHelper";
import {
  ClockIcon,
  ArrowLeftIcon,
  ChartBarIcon,
  UserGroupIcon,
  FolderIcon,
  CalendarIcon,
  ArrowDownTrayIcon,
  FunnelIcon,
} from "@heroicons/react/24/outline";

interface TimeEntry {
  id: string;
  taskId: string;
  taskTitle: string;
  projectName: string;
  userId: string;
  userName: string;
  startTime: string;
  endTime: string | null;
  duration: number;
  description: string;
  createdAt: string;
}

interface UserTimeStats {
  userId: string;
  userName: string;
  totalMinutes: number;
  tasksCount: number;
}

interface ProjectTimeStats {
  projectId: string;
  projectName: string;
  totalMinutes: number;
  tasksCount: number;
}

interface DailyStats {
  date: string;
  totalMinutes: number;
  entriesCount: number;
}

const TimeReports: React.FC = () => {
  const [timeEntries, setTimeEntries] = useState<TimeEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<
    "entries" | "users" | "projects" | "daily"
  >("entries");
  const [dateRange, setDateRange] = useState({
    startDate: new Date(new Date().setDate(new Date().getDate() - 30))
      .toISOString()
      .split("T")[0],
    endDate: new Date().toISOString().split("T")[0],
  });
  const [selectedUser, setSelectedUser] = useState("");
  const [selectedProject, setSelectedProject] = useState("");
  const [users, setUsers] = useState<
    { id: string; firstName: string; lastName: string }[]
  >([]);
  const [projects, setProjects] = useState<{ id: string; name: string }[]>([]);
  const getAccessToken = (): string | null => tokenManager.getAccessToken();

  useEffect(() => {
    fetchTimeEntries();
    fetchUsers();
    fetchProjects();
  }, [dateRange, selectedUser, selectedProject]);

  const fetchTimeEntries = async () => {
    try {
      setLoading(true);
      const token = getAccessToken();

      let url = `tasks/time-entries?startDate=${dateRange.startDate}&endDate=${dateRange.endDate}`;
      if (selectedUser) url += `&userId=${selectedUser}`;
      if (selectedProject) url += `&projectId=${selectedProject}`;

      const response = await fetch(buildApiUrl(url), {
        headers: { Authorization: `Bearer ${token}` },
      });

      const data = await response.json();
      if (data.success) {
        setTimeEntries(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching time entries:", error);
      setTimeEntries([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchUsers = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("tasks/company-users"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setUsers(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  const fetchProjects = async () => {
    try {
      const token = getAccessToken();
      const response = await fetch(buildApiUrl("projects"), {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (data.success) {
        setProjects(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching projects:", error);
    }
  };

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}س ${mins}د`;
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const formatTime = (dateString: string) => {
    return new Date(dateString).toLocaleTimeString("ar-EG", {
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  // Calculate stats
  const totalMinutes = timeEntries.reduce(
    (sum, entry) => sum + (entry.duration || 0),
    0,
  );

  const userStats: UserTimeStats[] = Object.values(
    timeEntries.reduce(
      (acc, entry) => {
        if (!acc[entry.userId]) {
          acc[entry.userId] = {
            userId: entry.userId,
            userName: entry.userName,
            totalMinutes: 0,
            tasksCount: 0,
          };
        }
        acc[entry.userId]!.totalMinutes += entry.duration || 0;
        acc[entry.userId]!.tasksCount += 1;
        return acc;
      },
      {} as Record<string, UserTimeStats>,
    ),
  ).sort((a, b) => b.totalMinutes - a.totalMinutes);

  const projectStats: ProjectTimeStats[] = Object.values(
    timeEntries.reduce(
      (acc, entry) => {
        const projectId = entry.projectName || "no-project";
        if (!acc[projectId]) {
          acc[projectId] = {
            projectId,
            projectName: entry.projectName || "بدون مشروع",
            totalMinutes: 0,
            tasksCount: 0,
          };
        }
        const projectStatsEntry = acc[projectId]!;
        projectStatsEntry.totalMinutes += entry.duration || 0;
        projectStatsEntry.tasksCount += 1;
        return acc;
      },
      {} as Record<string, ProjectTimeStats>,
    ),
  ).sort((a, b) => b.totalMinutes - a.totalMinutes);

  const dailyStats: DailyStats[] = Object.values(
    timeEntries.reduce(
      (acc, entry) => {
        const date = entry.startTime?.split("T")[0] || "";
        if (!date) return acc;
        if (!acc[date]) {
          acc[date] = {
            date,
            totalMinutes: 0,
            entriesCount: 0,
          };
        }
        const dailyStatsEntry = acc[date]!;
        dailyStatsEntry.totalMinutes += entry.duration || 0;
        dailyStatsEntry.entriesCount += 1;
        return acc;
      },
      {} as Record<string, DailyStats>,
    ),
  ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const exportToCSV = () => {
    const headers = [
      "المهمة",
      "المشروع",
      "المستخدم",
      "تاريخ البدء",
      "وقت البدء",
      "المدة (دقائق)",
      "الوصف",
    ];
    const rows = timeEntries.map((entry) => [
      entry.taskTitle,
      entry.projectName || "غير محدد",
      entry.userName,
      formatDate(entry.startTime),
      formatTime(entry.startTime),
      entry.duration?.toString() || "0",
      entry.description || "",
    ]);

    const csvContent =
      "\uFEFF" + [headers, ...rows].map((row) => row.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `time_report_${dateRange.startDate}_${dateRange.endDate}.csv`;
    link.click();
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="w-full px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4 space-x-reverse">
            <Link
              to="/tasks"
              className="flex items-center text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200 dark:text-gray-100"
            >
              <ArrowLeftIcon className="h-5 w-5 ml-2" />
              العودة
            </Link>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 flex items-center">
              <ClockIcon className="h-7 w-7 text-indigo-600 ml-2" />
              تقارير الوقت
            </h1>
          </div>

          <button
            onClick={exportToCSV}
            className="inline-flex items-center px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700"
          >
            <ArrowDownTrayIcon className="h-5 w-5 ml-2" />
            تصدير CSV
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4 mb-6">
        <div className="flex items-center mb-4">
          <FunnelIcon className="h-5 w-5 text-gray-400 ml-2" />
          <span className="font-medium text-gray-700 dark:text-gray-300">
            الفلاتر
          </span>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              من تاريخ
            </label>
            <input
              type="date"
              value={dateRange.startDate}
              onChange={(e) =>
                setDateRange({ ...dateRange, startDate: e.target.value })
              }
              className="w-full px-3 py-2 border border-gray-200 dark:border-gray-700-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              إلى تاريخ
            </label>
            <input
              type="date"
              value={dateRange.endDate}
              onChange={(e) =>
                setDateRange({ ...dateRange, endDate: e.target.value })
              }
              className="w-full px-3 py-2 border border-gray-200 dark:border-gray-700-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              المستخدم
            </label>
            <select
              value={selectedUser}
              onChange={(e) => setSelectedUser(e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 dark:border-gray-700-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">جميع المستخدمين</option>
              {users.map((user) => (
                <option key={user.id} value={user.id}>
                  {user.firstName} {user.lastName}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              المشروع
            </label>
            <select
              value={selectedProject}
              onChange={(e) => setSelectedProject(e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 dark:border-gray-700-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">جميع المشاريع</option>
              {projects.map((project) => (
                <option key={project.id} value={project.id}>
                  {project.name}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                إجمالي الوقت
              </p>
              <p className="text-2xl font-bold text-indigo-600">
                {formatDuration(totalMinutes)}
              </p>
            </div>
            <ClockIcon className="h-10 w-10 text-indigo-400" />
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                عدد السجلات
              </p>
              <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">
                {timeEntries.length}
              </p>
            </div>
            <ChartBarIcon className="h-10 w-10 text-gray-400" />
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                المستخدمين النشطين
              </p>
              <p className="text-2xl font-bold text-green-600">
                {userStats.length}
              </p>
            </div>
            <UserGroupIcon className="h-10 w-10 text-green-400" />
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                المشاريع النشطة
              </p>
              <p className="text-2xl font-bold text-blue-600">
                {projectStats.length}
              </p>
            </div>
            <FolderIcon className="h-10 w-10 text-blue-400" />
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow">
        <div className="border-b border-gray-200 dark:border-gray-700-200">
          <nav className="flex -mb-px">
            {[
              { id: "entries", label: "سجلات الوقت", icon: ClockIcon },
              { id: "users", label: "حسب المستخدم", icon: UserGroupIcon },
              { id: "projects", label: "حسب المشروع", icon: FolderIcon },
              { id: "daily", label: "حسب اليوم", icon: CalendarIcon },
            ].map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex items-center py-4 px-6 text-sm font-medium border-b-2 ${
                  activeTab === tab.id
                    ? "border-indigo-500 text-indigo-600"
                    : "border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:text-gray-300 hover:border-gray-200 dark:border-gray-700-300"
                }`}
              >
                <tab.icon className="h-5 w-5 ml-2" />
                {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="p-6">
          {/* Entries Tab */}
          {activeTab === "entries" && (
            <div className="overflow-x-auto">
              {timeEntries.length === 0 ? (
                <div className="text-center py-12 text-gray-500 dark:text-gray-400">
                  <ClockIcon className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                  <p>لا توجد سجلات وقت في هذه الفترة</p>
                </div>
              ) : (
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                        المهمة
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                        المشروع
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                        المستخدم
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                        التاريخ
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                        الوقت
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                        المدة
                      </th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-400 uppercase">
                        الوصف
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200">
                    {timeEntries.map((entry) => (
                      <tr key={entry.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <Link
                            to={`/tasks/${entry.taskId}`}
                            className="text-indigo-600 hover:text-indigo-900 font-medium"
                          >
                            {entry.taskTitle}
                          </Link>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                          {entry.projectName || "غير محدد"}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100">
                          {entry.userName}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                          {formatDate(entry.startTime)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                          {formatTime(entry.startTime)}
                          {entry.endTime && ` - ${formatTime(entry.endTime)}`}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="px-2 py-1 text-sm font-medium bg-indigo-100 text-indigo-800 rounded">
                            {formatDuration(entry.duration || 0)}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-500 dark:text-gray-400 max-w-xs truncate">
                          {entry.description || "-"}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          )}

          {/* Users Tab */}
          {activeTab === "users" && (
            <div className="space-y-4">
              {userStats.length === 0 ? (
                <div className="text-center py-12 text-gray-500 dark:text-gray-400">
                  <UserGroupIcon className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                  <p>لا توجد بيانات</p>
                </div>
              ) : (
                userStats.map((stat, index) => (
                  <div key={stat.userId} className="bg-gray-50 rounded-lg p-4">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center">
                        <span className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center font-bold ml-3">
                          {index + 1}
                        </span>
                        <span className="font-medium text-gray-900 dark:text-gray-100">
                          {stat.userName}
                        </span>
                      </div>
                      <div className="text-left">
                        <span className="text-lg font-bold text-indigo-600">
                          {formatDuration(stat.totalMinutes)}
                        </span>
                        <span className="text-sm text-gray-500 dark:text-gray-400 mr-2">
                          ({stat.tasksCount} سجل)
                        </span>
                      </div>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-indigo-600 h-2 rounded-full"
                        style={{
                          width: `${(stat.totalMinutes / totalMinutes) * 100}%`,
                        }}
                      ></div>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {/* Projects Tab */}
          {activeTab === "projects" && (
            <div className="space-y-4">
              {projectStats.length === 0 ? (
                <div className="text-center py-12 text-gray-500 dark:text-gray-400">
                  <FolderIcon className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                  <p>لا توجد بيانات</p>
                </div>
              ) : (
                projectStats.map((stat, index) => (
                  <div
                    key={stat.projectId}
                    className="bg-gray-50 rounded-lg p-4"
                  >
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center">
                        <span className="w-8 h-8 bg-green-100 text-green-600 rounded-full flex items-center justify-center font-bold ml-3">
                          {index + 1}
                        </span>
                        <span className="font-medium text-gray-900 dark:text-gray-100">
                          {stat.projectName}
                        </span>
                      </div>
                      <div className="text-left">
                        <span className="text-lg font-bold text-green-600">
                          {formatDuration(stat.totalMinutes)}
                        </span>
                        <span className="text-sm text-gray-500 dark:text-gray-400 mr-2">
                          ({stat.tasksCount} سجل)
                        </span>
                      </div>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-green-600 h-2 rounded-full"
                        style={{
                          width: `${(stat.totalMinutes / totalMinutes) * 100}%`,
                        }}
                      ></div>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {/* Daily Tab */}
          {activeTab === "daily" && (
            <div className="space-y-4">
              {dailyStats.length === 0 ? (
                <div className="text-center py-12 text-gray-500 dark:text-gray-400">
                  <CalendarIcon className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                  <p>لا توجد بيانات</p>
                </div>
              ) : (
                dailyStats.map((stat) => (
                  <div key={stat.date} className="bg-gray-50 rounded-lg p-4">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center">
                        <CalendarIcon className="h-5 w-5 text-gray-400 ml-2" />
                        <span className="font-medium text-gray-900 dark:text-gray-100">
                          {formatDate(stat.date)}
                        </span>
                      </div>
                      <div className="text-left">
                        <span className="text-lg font-bold text-blue-600">
                          {formatDuration(stat.totalMinutes)}
                        </span>
                        <span className="text-sm text-gray-500 dark:text-gray-400 mr-2">
                          ({stat.entriesCount} سجل)
                        </span>
                      </div>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-blue-600 h-2 rounded-full"
                        style={{
                          width: `${Math.min((stat.totalMinutes / 480) * 100, 100)}%`,
                        }}
                      ></div>
                    </div>
                    <div className="text-xs text-gray-500 dark:text-gray-400 mt-1 text-left">
                      {stat.totalMinutes >= 480
                        ? "8+ ساعات"
                        : `${((stat.totalMinutes / 480) * 100).toFixed(0)}% من يوم العمل`}
                    </div>
                  </div>
                ))
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TimeReports;

import React from "react";

export interface ActiveFiltersDisplayProps {
  filters: any;
  setFilters: (filters: any) => void;
  projects: any[];
  categories: any[];
  users: any[];
  formatDate: (date: string) => string;
}

export const ActiveFiltersDisplay: React.FC<ActiveFiltersDisplayProps> = ({
  filters,
  setFilters,
  projects,
  categories,
  users,
  formatDate,
}) => {
  if (!Object.values(filters).some((v) => v)) return null;

  return (
    <div className="bg-indigo-50 dark:bg-indigo-900/30 border border-indigo-200 dark:border-indigo-800 rounded-lg p-3 mb-4">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-sm text-indigo-700 dark:text-indigo-300 font-medium">
            الفلاتر النشطة:
          </span>
          {filters.projectId && (
            <span className="inline-flex items-center px-2 py-1 bg-white dark:bg-gray-800 border border-indigo-300 dark:border-indigo-700 rounded-full text-xs text-indigo-700 dark:text-indigo-300">
              المشروع:{" "}
              {projects.find((p) => p.id === filters.projectId)?.name}
              <button
                onClick={() => setFilters({ ...filters, projectId: "" })}
                className="mr-1 hover:text-indigo-900 dark:hover:text-indigo-200"
              >
                ×
              </button>
            </span>
          )}
          {filters.categoryId && (
            <span className="inline-flex items-center px-2 py-1 bg-white dark:bg-gray-800 border border-indigo-300 dark:border-indigo-700 rounded-full text-xs text-indigo-700 dark:text-indigo-300">
              القسم:{" "}
              {categories.find((c) => c.id === filters.categoryId)?.name}
              <button
                onClick={() => setFilters({ ...filters, categoryId: "" })}
                className="mr-1 hover:text-indigo-900"
              >
                ×
              </button>
            </span>
          )}
          {filters.status && (
            <span className="inline-flex items-center px-2 py-1 bg-white dark:bg-gray-800 border border-indigo-300 dark:border-indigo-700 rounded-full text-xs text-indigo-700 dark:text-indigo-300">
              الحالة:{" "}
              {filters.status === "pending"
                ? "في الانتظار"
                : filters.status === "in_progress"
                  ? "قيد التنفيذ"
                  : filters.status === "completed"
                    ? "مكتمل"
                    : "ملغي"}
              <button
                onClick={() => setFilters({ ...filters, status: "" })}
                className="mr-1 hover:text-indigo-900"
              >
                ×
              </button>
            </span>
          )}
          {filters.priority && (
            <span className="inline-flex items-center px-2 py-1 bg-white dark:bg-gray-800 border border-indigo-300 dark:border-indigo-700 rounded-full text-xs text-indigo-700 dark:text-indigo-300">
              الأولوية:{" "}
              {filters.priority === "urgent"
                ? "عاجل"
                : filters.priority === "high"
                  ? "عالي"
                  : filters.priority === "medium"
                    ? "متوسط"
                    : "منخفض"}
              <button
                onClick={() => setFilters({ ...filters, priority: "" })}
                className="mr-1 hover:text-indigo-900"
              >
                ×
              </button>
            </span>
          )}
          {filters.assignedTo && (
            <span className="inline-flex items-center px-2 py-1 bg-white dark:bg-gray-800 border border-indigo-300 dark:border-indigo-700 rounded-full text-xs text-indigo-700 dark:text-indigo-300">
              المسؤول:{" "}
              {users.find((u) => u.id === filters.assignedTo)?.firstName}
              <button
                onClick={() => setFilters({ ...filters, assignedTo: "" })}
                className="mr-1 hover:text-indigo-900"
              >
                ×
              </button>
            </span>
          )}
          {(filters.dueDateFrom || filters.dueDateTo) && (
            <span className="inline-flex items-center px-2 py-1 bg-white dark:bg-gray-800 border border-indigo-300 dark:border-indigo-700 rounded-full text-xs text-indigo-700 dark:text-indigo-300">
              التاريخ: {filters.dueDateFrom || "..."} -{" "}
              {filters.dueDateTo || "..."}
              <button
                onClick={() =>
                  setFilters({
                    ...filters,
                    dueDateFrom: "",
                    dueDateTo: "",
                  })
                }
                className="mr-1 hover:text-indigo-900"
              >
                ×
              </button>
            </span>
          )}
        </div>
        <button
          onClick={() => {
            setFilters({
              projectId: "",
              categoryId: "",
              status: "",
              priority: "",
              assignedTo: "",
              dueDateFrom: "",
              dueDateTo: "",
            });
          }}
          className="text-xs text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 font-medium"
        >
          مسح الكل
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Switch,
  FormControlLabel,
  Chip,
  IconButton,
  Alert,
} from "@mui/material";
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  PlayArrow as PlayIcon,
  Stop as StopIcon,
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";
import { useTranslation } from "react-i18next";

const TelegramAutoReply = () => {
  const [rules, setRules] = useState([]);
  const [userbots, setUserbots] = useState([]);
  const [selectedUserbot, setSelectedUserbot] = useState("");
  const [openDialog, setOpenDialog] = useState(false);
  const [editingRule, setEditingRule] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const { t, i18n } = useTranslation();
  const isRtl = i18n.dir() === "rtl";

  const [formData, setFormData] = useState({
    name: "",
    triggerType: "KEYWORD",
    triggerValue: "",
    response: "",
    workingHoursOnly: false,
    startTime: "09:00",
    endTime: "17:00",
    daysOfWeek: [],
    priority: 0,
  });

  useEffect(() => {
    fetchUserbots();
  }, []);

  useEffect(() => {
    if (selectedUserbot) {
      fetchRules();
    }
  }, [selectedUserbot]);

  const fetchUserbots = async () => {
    try {
      const response = await apiClient.get("/api/v1/telegram/userbots");
      setUserbots(response.data.data || []);
      if (response.data.data?.length > 0) {
        setSelectedUserbot(response.data.data[0].id);
      }
    } catch (error) {
      console.error("Error fetching userbots:", error);
      setError(t("telegramAutoReply.failedLoadUserbots"));
    }
  };

  const fetchRules = async () => {
    if (!selectedUserbot) return;
    setLoading(true);
    try {
      const response = await apiClient.get(
        `/api/v1/telegram-advanced/auto-reply/${selectedUserbot}`,
      );
      setRules(response.data.data || []);
    } catch (error) {
      console.error("Error fetching rules:", error);
      setError(t("telegramAutoReply.failedLoadRules"));
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (rule = null) => {
    if (rule) {
      setEditingRule(rule);
      setFormData({
        name: rule.name,
        triggerType: rule.triggerType,
        triggerValue: rule.triggerValue,
        response: rule.response,
        workingHoursOnly: rule.workingHoursOnly,
        startTime: rule.startTime || "09:00",
        endTime: rule.endTime || "17:00",
        daysOfWeek: rule.daysOfWeek || [],
        priority: rule.priority || 0,
      });
    } else {
      setEditingRule(null);
      setFormData({
        name: "",
        triggerType: "KEYWORD",
        triggerValue: "",
        response: "",
        workingHoursOnly: false,
        startTime: "09:00",
        endTime: "17:00",
        daysOfWeek: [],
        priority: 0,
      });
    }
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setEditingRule(null);
  };

  const handleSave = async () => {
    if (!selectedUserbot) {
      setError(t("telegramAutoReply.selectUserbotFirst"));
      return;
    }

    setLoading(true);
    try {
      if (editingRule) {
        await apiClient.put(
          `/api/v1/telegram-advanced/auto-reply/${editingRule.id}`,
          formData,
        );
      } else {
        await apiClient.post(
          `/api/v1/telegram-advanced/auto-reply/${selectedUserbot}`,
          formData,
        );
      }
      fetchRules();
      handleCloseDialog();
    } catch (error) {
      console.error("Error saving rule:", error);
      setError(t("telegramAutoReply.failedSaveRule"));
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (ruleId) => {
    if (!window.confirm(t("telegramAutoReply.confirmDelete"))) return;

    setLoading(true);
    try {
      await apiClient.delete(`/api/v1/telegram-advanced/auto-reply/${ruleId}`);
      fetchRules();
    } catch (error) {
      console.error("Error deleting rule:", error);
      setError(t("telegramAutoReply.failedDeleteRule"));
    } finally {
      setLoading(false);
    }
  };

  const handleToggleActive = async (rule) => {
    setLoading(true);
    try {
      await apiClient.put(`/api/v1/telegram-advanced/auto-reply/${rule.id}`, {
        isActive: !rule.isActive,
      });
      fetchRules();
    } catch (error) {
      console.error("Error toggling rule:", error);
      setError(t("telegramAutoReply.failedToggleRule"));
    } finally {
      setLoading(false);
    }
  };

  const daysOfWeek = [
    { value: 0, label: t("telegramAutoReply.days.sun") },
    { value: 1, label: t("telegramAutoReply.days.mon") },
    { value: 2, label: t("telegramAutoReply.days.tue") },
    { value: 3, label: t("telegramAutoReply.days.wed") },
    { value: 4, label: t("telegramAutoReply.days.thu") },
    { value: 5, label: t("telegramAutoReply.days.fri") },
    { value: 6, label: t("telegramAutoReply.days.sat") },
  ];

  return (
    <Box sx={{ p: 3, direction: isRtl ? "rtl" : "ltr" }}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Typography variant="h4">{t("telegramAutoReply.title")}</Typography>
        <Box sx={{ display: "flex", gap: 2 }}>
          <FormControl sx={{ minWidth: 200 }}>
            <InputLabel>{t("telegramAutoReply.selectBot")}</InputLabel>
            <Select
              value={selectedUserbot}
              onChange={(e) => setSelectedUserbot(e.target.value)}
              label={t("telegramAutoReply.selectBot")}
            >
              {userbots.map((bot) => (
                <MenuItem key={bot.id} value={bot.id}>
                  {bot.label} ({bot.clientPhone || t("telegramAutoReply.offline")})
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => handleOpenDialog()}
            disabled={!selectedUserbot}
          >
            {t("telegramAutoReply.addRule")}
          </Button>
        </Box>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError("")}>
          {error}
        </Alert>
      )}

      <Box sx={{ display: "grid", gap: 2 }}>
        {rules.map((rule) => (
          <Card key={rule.id}>
            <CardContent>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "start",
                }}
              >
                <Box sx={{ flex: 1 }}>
                  <Box
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 1,
                      mb: 1,
                    }}
                  >
                    <Typography variant="h6">{rule.name}</Typography>
                    <Chip
                      label={rule.isActive ? t("telegramAutoReply.active") : t("telegramAutoReply.stopped")}
                      color={rule.isActive ? "success" : "default"}
                      size="small"
                    />
                    <Chip label={`${t("telegramAutoReply.priority")}: ${rule.priority}`} size="small" />
                  </Box>
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{ mb: 1 }}
                  >
                    <strong>{t("telegramAutoReply.trigger")}:</strong>{" "}
                    {rule.triggerType === "KEYWORD"
                      ? t("telegramAutoReply.keyword")
                      : rule.triggerType === "REGEX"
                        ? t("telegramAutoReply.regex")
                        : t("telegramAutoReply.all")}{" "}
                    - {rule.triggerValue}
                  </Typography>
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{ mb: 1 }}
                  >
                    <strong>{t("telegramAutoReply.response")}:</strong> {rule.response}
                  </Typography>
                  {rule.workingHoursOnly && (
                    <Typography variant="body2" color="text.secondary">
                      ⏰ {t("telegramAutoReply.workingHoursOnly")}: {rule.startTime} - {rule.endTime}
                    </Typography>
                  )}
                </Box>
                <Box sx={{ display: "flex", gap: 1 }}>
                  <IconButton
                    color={rule.isActive ? "error" : "success"}
                    onClick={() => handleToggleActive(rule)}
                    disabled={loading}
                  >
                    {rule.isActive ? <StopIcon /> : <PlayIcon />}
                  </IconButton>
                  <IconButton
                    color="primary"
                    onClick={() => handleOpenDialog(rule)}
                    disabled={loading}
                  >
                    <EditIcon />
                  </IconButton>
                  <IconButton
                    color="error"
                    onClick={() => handleDelete(rule.id)}
                    disabled={loading}
                  >
                    <DeleteIcon />
                  </IconButton>
                </Box>
              </Box>
            </CardContent>
          </Card>
        ))}

        {rules.length === 0 && !loading && (
          <Card>
            <CardContent>
              <Typography
                variant="body1"
                color="text.secondary"
                textAlign="center"
              >
                {t("telegramAutoReply.noRules")}
              </Typography>
            </CardContent>
          </Card>
        )}
      </Box>

      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="md"
        fullWidth
        dir={isRtl ? "rtl" : "ltr"}
      >
        <DialogTitle>
          {editingRule ? t("telegramAutoReply.editRule") : t("telegramAutoReply.addNewRule")}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 2 }}>
            <TextField
              label={t("telegramAutoReply.ruleName")}
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
              fullWidth
              required
            />

            <FormControl fullWidth>
              <InputLabel>{t("telegramAutoReply.triggerType")}</InputLabel>
              <Select
                value={formData.triggerType}
                onChange={(e) =>
                  setFormData({ ...formData, triggerType: e.target.value })
                }
                label={t("telegramAutoReply.triggerType")}
              >
                <MenuItem value="KEYWORD">{t("telegramAutoReply.keyword")}</MenuItem>
                <MenuItem value="REGEX">{t("telegramAutoReply.regexFull")}</MenuItem>
                <MenuItem value="ALL">{t("telegramAutoReply.allMessages")}</MenuItem>
              </Select>
            </FormControl>

            {formData.triggerType !== "ALL" && (
              <TextField
                label={t("telegramAutoReply.triggerValue")}
                value={formData.triggerValue}
                onChange={(e) =>
                  setFormData({ ...formData, triggerValue: e.target.value })
                }
                fullWidth
                required
                helperText={
                  formData.triggerType === "KEYWORD"
                    ? t("telegramAutoReply.keywordExample")
                    : t("telegramAutoReply.regexExample")
                }
              />
            )}

            <TextField
              label={t("telegramAutoReply.response")}
              value={formData.response}
              onChange={(e) =>
                setFormData({ ...formData, response: e.target.value })
              }
              fullWidth
              required
              multiline
              rows={4}
            />

            <TextField
              label={t("telegramAutoReply.priority")}
              type="number"
              value={formData.priority}
              onChange={(e) =>
                setFormData({ ...formData, priority: parseInt(e.target.value) })
              }
              fullWidth
              helperText={t("telegramAutoReply.priorityHelper")}
            />

            <FormControlLabel
              control={
                <Switch
                  checked={formData.workingHoursOnly}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      workingHoursOnly: e.target.checked,
                    })
                  }
                />
              }
              label={t("telegramAutoReply.workingHoursOnly")}
            />

            {formData.workingHoursOnly && (
              <Box sx={{ display: "flex", gap: 2 }}>
                <TextField
                  label={t("telegramAutoReply.from")}
                  type="time"
                  value={formData.startTime}
                  onChange={(e) =>
                    setFormData({ ...formData, startTime: e.target.value })
                  }
                  fullWidth
                />
                <TextField
                  label={t("telegramAutoReply.to")}
                  type="time"
                  value={formData.endTime}
                  onChange={(e) =>
                    setFormData({ ...formData, endTime: e.target.value })
                  }
                  fullWidth
                />
              </Box>
            )}

            <FormControl fullWidth>
              <InputLabel>{t("telegramAutoReply.workingDays")}</InputLabel>
              <Select
                multiple
                value={formData.daysOfWeek}
                onChange={(e) =>
                  setFormData({ ...formData, daysOfWeek: e.target.value as number[] })
                }
                label={t("telegramAutoReply.workingDays")}
                renderValue={(selected) => (
                  <Box sx={{ display: "flex", flexWrap: "wrap", gap: 0.5 }}>
                    {(selected as number[]).map((value) => (
                      <Chip
                        key={value}
                        label={daysOfWeek.find((d) => d.value === value)?.label}
                        size="small"
                      />
                    ))}
                  </Box>
                )}
              >
                {daysOfWeek.map((day) => (
                  <MenuItem key={day.value} value={day.value}>
                    {day.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>{t("telegramAutoReply.cancel")}</Button>
          <Button onClick={handleSave} variant="contained" disabled={loading}>
            {loading ? t("telegramAutoReply.saving") : t("telegramAutoReply.save")}
          </Button>
        </DialogActions>
      </Dialog>
    </Box >
  );
};

export default TelegramAutoReply;

import React, { useState, useEffect, useCallback } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Chip,
  LinearProgress,
  Alert,
  List,
  ListItem,
  ListItemText,
  Skeleton,
  IconButton,
  Tooltip,
} from "@mui/material";
import {
  Add as AddIcon,
  Send as SendIcon,
  Cancel as CancelIcon,
  Visibility as VisibilityIcon,
  Refresh as RefreshIcon,
  Close as CloseIcon,
} from "@mui/icons-material";
import { apiClient } from "../../services/apiClient";

// ===== TypeScript Interfaces =====

interface Userbot {
  id: string;
  label: string;
  clientPhone?: string;
  isConnected?: boolean;
}

interface Contact {
  id: string;
  telegramId: string;
  firstName: string;
  lastName?: string;
  username?: string;
}

interface BulkMessage {
  id: string;
  name: string;
  message: string;
  status: "PENDING" | "IN_PROGRESS" | "COMPLETED" | "FAILED" | "CANCELLED";
  sentCount: number;
  failedCount: number;
  totalRecipients: number;
  createdAt: string;
}

interface BulkMessageLog {
  id: string;
  recipient: string;
  status: "SENT" | "FAILED";
  sentAt?: string;
  error?: string;
}

interface BulkMessageDetails {
  bulkMessage: BulkMessage;
  logs: BulkMessageLog[];
}

interface FormData {
  userbotConfigId: string;
  name: string;
  message: string;
  recipients: string[];
  delayBetweenMessages: number;
}

// ===== Helper Functions =====

// دالة لتعقيم المدخلات لمنع XSS
const sanitizeInput = (input: string): string => {
  if (typeof input !== "string") return "";
  const div = document.createElement("div");
  div.textContent = input;
  return div.innerHTML;
};

// دالة للحصول على لون الحالة
const getStatusColor = (
  status: string,
): "success" | "info" | "error" | "default" | "warning" => {
  switch (status) {
    case "COMPLETED":
      return "success";
    case "IN_PROGRESS":
      return "info";
    case "FAILED":
      return "error";
    case "CANCELLED":
      return "default";
    default:
      return "warning";
  }
};

// دالة للحصول على نص الحالة بالعربية
const getStatusLabel = (status: string): string => {
  switch (status) {
    case "PENDING":
      return "قيد الانتظار";
    case "IN_PROGRESS":
      return "جاري الإرسال";
    case "COMPLETED":
      return "مكتمل";
    case "FAILED":
      return "فشل";
    case "CANCELLED":
      return "ملغي";
    default:
      return status;
  }
};

// ===== Main Component =====

const TelegramBulkMessages: React.FC = () => {
  // State
  const [bulkMessages, setBulkMessages] = useState<BulkMessage[]>([]);
  const [userbots, setUserbots] = useState<Userbot[]>([]);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [openDetailsDialog, setOpenDetailsDialog] = useState(false);
  const [selectedBulkMessage, setSelectedBulkMessage] =
    useState<BulkMessageDetails | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [autoRefresh, setAutoRefresh] = useState(true);

  const [formData, setFormData] = useState<FormData>({
    userbotConfigId: "",
    name: "",
    message: "",
    recipients: [],
    delayBetweenMessages: 2000,
  });

  // Effects
  useEffect(() => {
    fetchUserbots();
    fetchBulkMessages();
    fetchContacts();

    // تحديث تلقائي كل 10 ثوانٍ للصفحة
    const refreshInterval = setInterval(() => {
      if (autoRefresh && !openDialog && !openDetailsDialog) {
        fetchBulkMessages();
      }
    }, 10000);

    return () => clearInterval(refreshInterval);
  }, [autoRefresh, openDialog, openDetailsDialog]);

  // API Functions
  const fetchUserbots = async (): Promise<void> => {
    try {
      const response = await apiClient.get<{ data: Userbot[] }>(
        "/api/v1/telegram/userbots",
      );
      setUserbots(response.data.data || []);
    } catch (error) {
      console.error("Error fetching userbots:", error);
    }
  };

  const fetchBulkMessages = async (): Promise<void> => {
    setLoading(true);
    try {
      const response = await apiClient.get<{ data: BulkMessage[] }>(
        "/api/v1/telegram-advanced/bulk-messages",
      );
      setBulkMessages(response.data.data || []);
    } catch (error) {
      console.error("Error fetching bulk messages:", error);
      setError("فشل تحميل الرسائل الجماعية");
    } finally {
      setLoading(false);
    }
  };

  const fetchContacts = async (): Promise<void> => {
    try {
      const response = await apiClient.get<{ data: Contact[] }>(
        "/api/v1/telegram-advanced/contacts",
      );
      setContacts(response.data.data || []);
    } catch (error) {
      console.error("Error fetching contacts:", error);
    }
  };

  // Event Handlers
  const handleOpenDialog = (): void => {
    setFormData({
      userbotConfigId: userbots[0]?.id || "",
      name: "",
      message: "",
      recipients: [],
      delayBetweenMessages: 2000,
    });
    setOpenDialog(true);
  };

  const handleCloseDialog = (): void => {
    setOpenDialog(false);
  };

  const handleSend = async (): Promise<void> => {
    if (
      !formData.userbotConfigId ||
      !formData.message ||
      formData.recipients.length === 0
    ) {
      setError("يرجى ملء جميع الحقول المطلوبة");
      return;
    }

    // التحقق من أن المستخدم المحدد متصل
    const selectedUserbot = userbots.find(
      (bot: Userbot) => bot.id === formData.userbotConfigId,
    );
    if (!selectedUserbot || !selectedUserbot.clientPhone) {
      setError("يرجى اختيار حساب تيليجرام متصل");
      return;
    }

    setLoading(true);
    try {
      await apiClient.post("/api/v1/telegram-advanced/bulk-messages", formData);
      setSuccess("تم إرسال الحملة بنجاح");
      fetchBulkMessages();
      handleCloseDialog();
    } catch (error: unknown) {
      console.error("Error sending bulk message:", error);
      const axiosError = error as { response?: { data?: { error?: string } } };
      setError(
        axiosError.response?.data?.error || "فشل إرسال الرسالة الجماعية",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleViewDetails = async (bulkMessage: BulkMessage): Promise<void> => {
    setLoading(true);
    try {
      const response = await apiClient.get<{ data: BulkMessageDetails }>(
        `/api/v1/telegram-advanced/bulk-messages/${bulkMessage.id}`,
      );
      setSelectedBulkMessage(response.data.data);
      setOpenDetailsDialog(true);
    } catch (error) {
      console.error("Error fetching details:", error);
      setError("فشل تحميل التفاصيل");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (bulkMessageId: string): Promise<void> => {
    if (!window.confirm("هل أنت متأكد من إلغاء هذه الحملة؟")) return;

    setLoading(true);
    try {
      await apiClient.post(
        `/api/v1/telegram-advanced/bulk-messages/${bulkMessageId}/cancel`,
      );
      fetchBulkMessages();
    } catch (error) {
      console.error("Error cancelling bulk message:", error);
      setError("فشل إلغاء الحملة");
    } finally {
      setLoading(false);
    }
  };

  // Render
  return (
    <Box sx={{ p: 3, direction: "rtl" }}>
      {/* Header */}
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <Typography variant="h4">📨 الرسائل الجماعية</Typography>
          <Tooltip title="تحديث">
            <IconButton onClick={fetchBulkMessages} disabled={loading}>
              <RefreshIcon />
            </IconButton>
          </Tooltip>
        </Box>
        <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
          <FormControl size="small" sx={{ minWidth: 120 }}>
            <Select
              value={autoRefresh ? "on" : "off"}
              onChange={(e) => setAutoRefresh(e.target.value === "on")}
              size="small"
            >
              <MenuItem value="on">تحديث تلقائي</MenuItem>
              <MenuItem value="off">تحديث يدوي</MenuItem>
            </Select>
          </FormControl>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={handleOpenDialog}
            disabled={
              userbots.length === 0 ||
              !userbots.some((bot: Userbot) => bot.clientPhone)
            }
          >
            حملة جديدة
          </Button>
        </Box>
      </Box>

      {/* Alerts */}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError("")}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess("")}>
          {success}
        </Alert>
      )}

      {/* Bulk Messages List */}
      <Box sx={{ display: "grid", gap: 2 }}>
        {loading && bulkMessages.length === 0
          ? [...Array(3)].map((_, index) => (
              <Card key={index}>
                <CardContent>
                  <Skeleton variant="rectangular" height={100} />
                </CardContent>
              </Card>
            ))
          : bulkMessages.map((bulk) => (
              <Card key={bulk.id}>
                <CardContent>
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "start",
                      mb: 2,
                    }}
                  >
                    <Box sx={{ flex: 1 }}>
                      <Box
                        sx={{
                          display: "flex",
                          alignItems: "center",
                          gap: 1,
                          mb: 1,
                        }}
                      >
                        <Typography variant="h6">
                          {sanitizeInput(bulk.name)}
                        </Typography>
                        <Chip
                          label={getStatusLabel(bulk.status)}
                          color={getStatusColor(bulk.status)}
                          size="small"
                        />
                      </Box>
                      <Typography
                        variant="body2"
                        color="text.secondary"
                        sx={{ mb: 1 }}
                      >
                        {sanitizeInput(bulk.message.substring(0, 100))}
                        {bulk.message.length > 100 ? "..." : ""}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        📊 {bulk.sentCount} / {bulk.totalRecipients} تم الإرسال
                        {bulk.failedCount > 0 &&
                          ` • ❌ ${bulk.failedCount} فشل`}
                      </Typography>
                    </Box>
                    <Box sx={{ display: "flex", gap: 1 }}>
                      <Button
                        size="small"
                        startIcon={<VisibilityIcon />}
                        onClick={() => handleViewDetails(bulk)}
                      >
                        التفاصيل
                      </Button>
                      {bulk.status === "IN_PROGRESS" && (
                        <Button
                          size="small"
                          color="error"
                          startIcon={<CancelIcon />}
                          onClick={() => handleCancel(bulk.id)}
                        >
                          إلغاء
                        </Button>
                      )}
                    </Box>
                  </Box>
                  {bulk.status === "IN_PROGRESS" && (
                    <LinearProgress
                      variant="determinate"
                      value={Math.min(
                        (bulk.sentCount / bulk.totalRecipients) * 100,
                        100,
                      )}
                    />
                  )}
                </CardContent>
              </Card>
            ))}

        {bulkMessages.length === 0 && !loading && (
          <Card>
            <CardContent>
              <Typography
                variant="body1"
                color="text.secondary"
                textAlign="center"
              >
                لا توجد حملات رسائل جماعية. انقر على "حملة جديدة" للبدء.
              </Typography>
            </CardContent>
          </Card>
        )}
      </Box>

      {/* Create Dialog */}
      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="md"
        fullWidth
        dir="rtl"
      >
        <DialogTitle>📨 حملة رسائل جماعية جديدة</DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 2 }}>
            <FormControl
              fullWidth
              error={!formData.userbotConfigId && error.includes("حساب")}
            >
              <InputLabel>اختر Userbot</InputLabel>
              <Select
                value={formData.userbotConfigId}
                onChange={(e) =>
                  setFormData({ ...formData, userbotConfigId: e.target.value })
                }
                label="اختر Userbot"
              >
                {userbots.map((bot: Userbot) => (
                  <MenuItem
                    key={bot.id}
                    value={bot.id}
                    disabled={!bot.clientPhone}
                  >
                    {bot.label} ({bot.clientPhone || "غير متصل"})
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <TextField
              label="اسم الحملة"
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
              fullWidth
              required
              error={!formData.name && error.includes("الحقول")}
            />

            <TextField
              label="الرسالة"
              value={formData.message}
              onChange={(e) =>
                setFormData({ ...formData, message: e.target.value })
              }
              fullWidth
              required
              multiline
              rows={6}
              helperText={`${formData.message.length} حرف`}
              error={!formData.message && error.includes("الحقول")}
            />

            <FormControl
              fullWidth
              error={
                formData.recipients.length === 0 && error.includes("الحقول")
              }
            >
              <InputLabel>المستلمون</InputLabel>
              <Select
                multiple
                value={formData.recipients}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    recipients: e.target.value as string[],
                  })
                }
                label="المستلمون"
                renderValue={(selected: string[]) => `${selected.length} مستلم`}
              >
                {contacts.map((contact: Contact) => (
                  <MenuItem key={contact.id} value={contact.telegramId}>
                    {sanitizeInput(contact.firstName)}{" "}
                    {sanitizeInput(contact.lastName || "")}{" "}
                    {contact.username
                      ? `(@${sanitizeInput(contact.username)})`
                      : ""}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <TextField
              label="التأخير بين الرسائل (ميلي ثانية)"
              type="number"
              value={formData.delayBetweenMessages}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  delayBetweenMessages: Math.max(
                    2000,
                    parseInt(e.target.value) || 2000,
                  ),
                })
              }
              fullWidth
              inputProps={{ min: 2000 }}
              helperText="الحد الأدنى: 2000 (ثانيتين) لتجنب الحظر"
            />

            <Alert severity="warning">
              ⚠️ تأكد من عدم إرسال رسائل سبام. قد يؤدي الإرسال المفرط إلى حظر
              حسابك.
            </Alert>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>إلغاء</Button>
          <Button
            onClick={handleSend}
            variant="contained"
            startIcon={<SendIcon />}
            disabled={loading || formData.recipients.length === 0}
          >
            {loading
              ? "جاري الإرسال..."
              : `إرسال (${formData.recipients.length})`}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Details Dialog */}
      <Dialog
        open={openDetailsDialog}
        onClose={() => setOpenDetailsDialog(false)}
        maxWidth="md"
        fullWidth
        dir="rtl"
      >
        <DialogTitle>
          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            تفاصيل الحملة
            <IconButton
              onClick={() => setOpenDetailsDialog(false)}
              size="small"
            >
              <CloseIcon />
            </IconButton>
          </Box>
        </DialogTitle>
        <DialogContent>
          {loading ? (
            <Box sx={{ display: "flex", justifyContent: "center", p: 3 }}>
              <LinearProgress />
            </Box>
          ) : (
            selectedBulkMessage && (
              <Box sx={{ mt: 2 }}>
                <Typography variant="h6" gutterBottom>
                  {sanitizeInput(selectedBulkMessage.bulkMessage?.name || "")}
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  {sanitizeInput(
                    selectedBulkMessage.bulkMessage?.message || "",
                  )}
                </Typography>
                <Box
                  sx={{
                    mb: 2,
                    p: 2,
                    bgcolor: "background.default",
                    borderRadius: 1,
                  }}
                >
                  <Typography variant="subtitle2" gutterBottom>
                    الإحصائيات:
                  </Typography>
                  <Typography variant="body2">
                    ✅ تم الإرسال: {selectedBulkMessage.bulkMessage?.sentCount}
                  </Typography>
                  <Typography variant="body2">
                    ❌ فشل: {selectedBulkMessage.bulkMessage?.failedCount}
                  </Typography>
                  <Typography variant="body2">
                    📊 الإجمالي:{" "}
                    {selectedBulkMessage.bulkMessage?.totalRecipients}
                  </Typography>
                  <Typography variant="body2">
                    📈 النسبة:{" "}
                    {selectedBulkMessage.bulkMessage?.totalRecipients
                      ? Math.round(
                          (selectedBulkMessage.bulkMessage.sentCount /
                            selectedBulkMessage.bulkMessage.totalRecipients) *
                            100,
                        )
                      : 0}
                    %
                  </Typography>
                </Box>
                <Typography variant="subtitle2" gutterBottom>
                  سجل الإرسال:
                </Typography>
                <List dense sx={{ maxHeight: 300, overflow: "auto" }}>
                  {selectedBulkMessage.logs
                    ?.slice(0, 20)
                    .map((log: BulkMessageLog) => (
                      <ListItem key={log.id}>
                        <ListItemText
                          primary={sanitizeInput(log.recipient)}
                          secondary={
                            log.status === "SENT"
                              ? `✅ تم الإرسال في ${log.sentAt ? new Date(log.sentAt).toLocaleString("ar-EG") : ""}`
                              : `❌ فشل: ${sanitizeInput(log.error || "خطأ غير معروف")}`
                          }
                        />
                      </ListItem>
                    ))}
                </List>
                {selectedBulkMessage.logs &&
                  selectedBulkMessage.logs.length > 20 && (
                    <Typography
                      variant="body2"
                      color="text.secondary"
                      textAlign="center"
                    >
                      ... و {selectedBulkMessage.logs.length - 20} آخرين
                    </Typography>
                  )}
              </Box>
            )
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDetailsDialog(false)}>إغلاق</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default TelegramBulkMessages;

import React, { useState, useEffect, useCallback } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Chip,
  IconButton,
  Autocomplete,
  Alert,
  LinearProgress,
  Tooltip,
  Collapse,
  Divider,
  FormControlLabel,
  Switch,
  Badge,
} from "@mui/material";
import {
  Add as AddIcon,
  Cancel as CancelIcon,
  Delete as DeleteIcon,
  Campaign as CampaignIcon,
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
  Refresh as RefreshIcon,
  CheckCircle as SentIcon,
  Error as FailedIcon,
  HourglassEmpty as PendingIcon,
} from "@mui/icons-material";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { LocalizationProvider, DateTimePicker } from "@mui/x-date-pickers";
import { ar } from "date-fns/locale";
import { apiClient } from "../../services/apiClient";
import { format } from "date-fns";

// ── Types ──────────────────────────────────────────────────────────────────
interface Campaign {
  id: string;
  name: string;
  description?: string;
  message: string;
  scheduledTime: string;
  status: "PENDING" | "RUNNING" | "COMPLETED" | "FAILED" | "CANCELLED";
  totalCount: number;
  sentCount: number;
  failedCount: number;
  pendingCount: number;
  cancelledCount: number;
  createdAt: string;
}

interface CampaignMessage {
  id: string;
  chatId: string;
  status: string;
  error?: string;
}

interface UserbotConfig {
  id: string;
  label: string;
  clientPhone?: string;
}

interface TelegramDialog {
  id: string;
  name: string;
}

const STATUS_COLORS: Record<string, "default" | "warning" | "success" | "error" | "info"> = {
  PENDING: "warning",
  RUNNING: "info",
  COMPLETED: "success",
  FAILED: "error",
  CANCELLED: "default",
};

const STATUS_LABELS: Record<string, string> = {
  PENDING: "⏳ قيد الانتظار",
  RUNNING: "🔄 جاري الإرسال",
  COMPLETED: "✅ مكتملة",
  FAILED: "❌ فاشلة",
  CANCELLED: "🚫 ملغاة",
};

// ── Component ──────────────────────────────────────────────────────────────
const TelegramCampaigns: React.FC = () => {
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [userbots, setUserbots] = useState<UserbotConfig[]>([]);
  const [dialogs, setDialogs] = useState<TelegramDialog[]>([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [campaignMessages, setCampaignMessages] = useState<Record<string, CampaignMessage[]>>({});

  const [formData, setFormData] = useState({
    userbotConfigId: "",
    name: "",
    description: "",
    message: "",
    chatIds: [] as string[],
    scheduledTime: new Date(Date.now() + 3600000),
    recurring: false,
    recurringPattern: "DAILY",
  });

  // ── Data Fetching ─────────────────────────────────────────────────────
  const fetchCampaigns = useCallback(async () => {
    try {
      const res = await apiClient.get("/api/v1/telegram-advanced/campaigns");
      const body = (res as { data?: { data?: Campaign[] } }).data;
      setCampaigns(Array.isArray(body?.data) ? body!.data! : []);
    } catch {
      // silent
    }
  }, []);

  const fetchUserbots = useCallback(async () => {
    try {
      const res = await apiClient.get("/api/v1/telegram/userbots");
      const body = (res as { data?: { data?: UserbotConfig[] } }).data;
      setUserbots(Array.isArray(body?.data) ? body!.data! : []);
    } catch {
      // silent
    }
  }, []);

  const fetchDialogs = useCallback(async (userbotConfigId: string) => {
    if (!userbotConfigId) return;
    try {
      const res = await apiClient.get(
        `/api/v1/userbot/dialogs?userbotConfigId=${userbotConfigId}`
      );
      const body = (res as { data?: { data?: TelegramDialog[] } }).data;
      setDialogs(Array.isArray(body?.data) ? body!.data! : []);
    } catch {
      setDialogs([]);
    }
  }, []);

  const fetchCampaignMessages = useCallback(async (campaignId: string) => {
    try {
      const res = await apiClient.get(
        `/api/v1/telegram-advanced/campaigns/${campaignId}`
      );
      const body = (res as { data?: { data?: { messages: CampaignMessage[] } } }).data;
      const msgs = body?.data?.messages;
      if (Array.isArray(msgs)) {
        setCampaignMessages((prev) => ({ ...prev, [campaignId]: msgs }));
      }
    } catch {
      // silent
    }
  }, []);

  useEffect(() => {
    fetchUserbots();
    fetchCampaigns();
    const timer = setInterval(fetchCampaigns, 10000);
    return () => clearInterval(timer);
  }, [fetchUserbots, fetchCampaigns]);

  // ── Actions ────────────────────────────────────────────────────────────
  const handleUserbotChange = (id: string) => {
    setFormData({ ...formData, userbotConfigId: id, chatIds: [] });
    fetchDialogs(id);
  };

  const handleCreateCampaign = async () => {
    setError("");
    if (!formData.name.trim() || formData.name.trim().length < 2) {
      setError("اسم الحملة يجب أن يكون حرفين على الأقل");
      return;
    }
    if (!formData.userbotConfigId) {
      setError("يرجى اختيار الـ Userbot");
      return;
    }
    if (formData.chatIds.length === 0) {
      setError("يرجى اختيار محادثة واحدة على الأقل");
      return;
    }
    if (!formData.message.trim()) {
      setError("يرجى كتابة نص الرسالة");
      return;
    }
    if (formData.scheduledTime < new Date()) {
      setError("لا يمكن جدولة رسالة في وقت ماضٍ");
      return;
    }
    setLoading(true);
    try {
      await apiClient.post("/api/v1/telegram-advanced/campaigns", {
        ...formData,
        chatIds: formData.chatIds.filter((id) => id && id !== "unknown"),
      });
      setOpenDialog(false);
      resetForm();
      fetchCampaigns();
    } catch (e: unknown) {
      const errMsg = (e as { response?: { data?: { error?: string } } })?.response?.data?.error;
      setError(errMsg || "فشل إنشاء الحملة");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (campaignId: string) => {
    if (!confirm("هل تريد إلغاء هذه الحملة؟")) return;
    try {
      await apiClient.post(`/api/v1/telegram-advanced/campaigns/${campaignId}/cancel`);
      fetchCampaigns();
    } catch {
      // silent
    }
  };

  const handleDelete = async (campaignId: string) => {
    if (!confirm("هل تريد حذف هذه الحملة نهائياً؟")) return;
    try {
      await apiClient.delete(`/api/v1/telegram-advanced/campaigns/${campaignId}`);
      fetchCampaigns();
    } catch {
      // silent
    }
  };

  const handleExpand = (campaignId: string) => {
    if (expandedId === campaignId) {
      setExpandedId(null);
    } else {
      setExpandedId(campaignId);
      if (!campaignMessages[campaignId]) {
        fetchCampaignMessages(campaignId);
      }
    }
  };

  const resetForm = () => {
    const firstUserbotId = userbots[0]?.id || "";
    setFormData({
      userbotConfigId: firstUserbotId,
      name: "",
      description: "",
      message: "",
      chatIds: [],
      scheduledTime: new Date(Date.now() + 3600000),
      recurring: false,
      recurringPattern: "DAILY",
    });
    if (firstUserbotId) fetchDialogs(firstUserbotId);
    setError("");
  };

  // ── Stats bar ──────────────────────────────────────────────────────────
  const StatBar = ({ campaign }: { campaign: Campaign }) => {
    const total = campaign.totalCount || 1;
    const sentPct = Math.round((campaign.sentCount / total) * 100);
    const failedPct = Math.round((campaign.failedCount / total) * 100);
    return (
      <Box sx={{ mt: 1.5 }}>
        <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 0.5 }}>
          <SentIcon sx={{ color: "success.main", fontSize: 16 }} />
          <Typography variant="caption">أُرسلت: {campaign.sentCount}</Typography>
          <FailedIcon sx={{ color: "error.main", fontSize: 16, ml: 1 }} />
          <Typography variant="caption">فشل: {campaign.failedCount}</Typography>
          <PendingIcon sx={{ color: "warning.main", fontSize: 16, ml: 1 }} />
          <Typography variant="caption">انتظار: {campaign.pendingCount}</Typography>
        </Box>
        {/* Stacked progress bar */}
        <Box sx={{ display: "flex", borderRadius: 1, overflow: "hidden", height: 8, bgcolor: "grey.200" }}>
          {sentPct > 0 && (
            <Box sx={{ width: `${sentPct}%`, bgcolor: "success.main", transition: "width 0.4s" }} />
          )}
          {failedPct > 0 && (
            <Box sx={{ width: `${failedPct}%`, bgcolor: "error.main", transition: "width 0.4s" }} />
          )}
        </Box>
        <Typography variant="caption" color="text.secondary">
          {campaign.totalCount} محادثة إجمالاً • {sentPct}% مرسلة
        </Typography>
      </Box>
    );
  };

  // ── JSX ────────────────────────────────────────────────────────────────
  return (
    <Box sx={{ p: 3, direction: "rtl" }}>
      {/* Header */}
      <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 3 }}>
        <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
          <CampaignIcon sx={{ color: "primary.main", fontSize: 32 }} />
          <Box>
            <Typography variant="h5" fontWeight="bold">
              حملات تيليجرام
            </Typography>
            <Typography variant="caption" color="text.secondary">
              أرسل رسائل مجدولة لعدة محادثات دفعةً واحدة وتابع تقرير الأداء
            </Typography>
          </Box>
        </Box>
        <Box sx={{ display: "flex", gap: 1 }}>
          <Tooltip title="تحديث">
            <IconButton onClick={fetchCampaigns}>
              <RefreshIcon />
            </IconButton>
          </Tooltip>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => { resetForm(); setOpenDialog(true); }}
          >
            حملة جديدة
          </Button>
        </Box>
      </Box>

      {/* Campaign Cards */}
      {campaigns.length === 0 && !loading && (
        <Card>
          <CardContent>
            <Typography color="text.secondary" textAlign="center">
              لا توجد حملات بعد. انقر على "حملة جديدة" للبدء!
            </Typography>
          </CardContent>
        </Card>
      )}

      {campaigns.map((c) => (
        <Card key={c.id} sx={{ mb: 2, border: 1, borderColor: "divider" }}>
          <CardContent>
            {/* Row 1: name + status + actions */}
            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <Box>
                <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                  <Typography variant="h6" fontWeight="bold">{c.name}</Typography>
                  <Chip
                    label={STATUS_LABELS[c.status] || c.status}
                    color={STATUS_COLORS[c.status] || "default"}
                    size="small"
                  />
                </Box>
                {c.description && (
                  <Typography variant="body2" color="text.secondary">{c.description}</Typography>
                )}
                <Typography variant="caption" color="text.secondary">
                  🕒 {format(new Date(c.scheduledTime), "yyyy/MM/dd HH:mm")}
                </Typography>
              </Box>

              {/* Actions */}
              <Box sx={{ display: "flex", gap: 0.5, alignItems: "center" }}>
                {c.status === "PENDING" && (
                  <Tooltip title="إلغاء الحملة">
                    <IconButton size="small" color="warning" onClick={() => handleCancel(c.id)}>
                      <CancelIcon />
                    </IconButton>
                  </Tooltip>
                )}
                {(c.status === "CANCELLED" || c.status === "COMPLETED" || c.status === "FAILED") && (
                  <Tooltip title="حذف الحملة">
                    <IconButton size="small" color="error" onClick={() => handleDelete(c.id)}>
                      <DeleteIcon />
                    </IconButton>
                  </Tooltip>
                )}
                <Tooltip title="تفاصيل الحملة">
                  <IconButton size="small" onClick={() => handleExpand(c.id)}>
                    {expandedId === c.id ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                  </IconButton>
                </Tooltip>
              </Box>
            </Box>

            {/* Stats bar */}
            <StatBar campaign={c} />

            {/* Expanded message list */}
            <Collapse in={expandedId === c.id}>
              <Divider sx={{ my: 2 }} />
              <Typography variant="subtitle2" fontWeight="bold" sx={{ mb: 1 }}>
                📋 تفاصيل المستقبلين ({campaignMessages[c.id]?.length ?? "..."})
              </Typography>
              {!campaignMessages[c.id] && <LinearProgress />}
              {campaignMessages[c.id]?.map((msg) => (
                <Box
                  key={msg.id}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1,
                    py: 0.5,
                    px: 1,
                    mb: 0.5,
                    borderRadius: 1,
                    bgcolor: msg.status === "SENT"
                      ? "success.50"
                      : msg.status === "FAILED"
                      ? "error.50"
                      : "grey.50",
                  }}
                >
                  <Chip
                    label={msg.status}
                    color={
                      msg.status === "SENT"
                        ? "success"
                        : msg.status === "FAILED"
                        ? "error"
                        : "warning"
                    }
                    size="small"
                    sx={{ minWidth: 80 }}
                  />
                  <Typography variant="body2" sx={{ flex: 1 }}>
                    {msg.chatId}
                  </Typography>
                  {msg.error && (
                    <Tooltip title={msg.error}>
                      <FailedIcon sx={{ color: "error.main", fontSize: 16 }} />
                    </Tooltip>
                  )}
                </Box>
              ))}
            </Collapse>
          </CardContent>
        </Card>
      ))}

      {/* ── Create Campaign Dialog ─────────────────────────────────────── */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="md" fullWidth dir="rtl">
        <DialogTitle>🚀 إنشاء حملة جديدة</DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 1 }}>
            {error && <Alert severity="error">{error}</Alert>}

            {/* Campaign name + description */}
            <TextField
              label="اسم الحملة *"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              fullWidth
              placeholder="مثال: حملة عروض رمضان"
            />
            <TextField
              label="وصف الحملة (اختياري)"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              fullWidth
              multiline
              rows={2}
            />

            {/* Userbot */}
            <FormControl fullWidth>
              <InputLabel>اختر Userbot *</InputLabel>
              <Select
                value={formData.userbotConfigId}
                onChange={(e) => handleUserbotChange(e.target.value)}
                label="اختر Userbot *"
              >
                {userbots.map((b) => (
                  <MenuItem key={b.id} value={b.id}>
                    {b.label} ({b.clientPhone || "غير متصل"})
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            {/* Chat multi-select */}
            <Autocomplete
              multiple
              fullWidth
              disabled={!formData.userbotConfigId}
              options={dialogs}
              getOptionLabel={(o) => o.name || ""}
              isOptionEqualToValue={(o, v) => o.id === v.id}
              renderOption={(props, option) => (
                <li {...props} key={option.id}>{option.name}</li>
              )}
              value={dialogs.filter((d) => formData.chatIds.includes(d.id))}
              onChange={(_e, newVal) =>
                setFormData({ ...formData, chatIds: newVal.map((v) => v.id) })
              }
              renderInput={(params) => (
                <TextField
                  {...params}
                  label={`اختر المحادثات * ${formData.chatIds.length > 0 ? `(${formData.chatIds.length} مختارة)` : ""}`}
                />
              )}
              renderTags={(value, getTagProps) =>
                value.map((option, index) => (
                  <Chip
                    variant="outlined"
                    label={option.name}
                    size="small"
                    {...getTagProps({ index })}
                    key={option.id}
                  />
                ))
              }
            />

            {formData.chatIds.length > 0 && (
              <Alert severity="info" icon={<CampaignIcon />}>
                ستُرسل هذه الرسالة إلى <strong>{formData.chatIds.length}</strong> محادثة في وقت واحد.
              </Alert>
            )}

            {/* Message */}
            <TextField
              label="نص الرسالة *"
              value={formData.message}
              onChange={(e) => setFormData({ ...formData, message: e.target.value })}
              fullWidth
              multiline
              rows={5}
              placeholder="اكتب رسالة الحملة هنا..."
            />

            {/* Scheduled time */}
            <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={ar}>
              <DateTimePicker
                label="وقت الإرسال *"
                value={formData.scheduledTime}
                onChange={(v) => v && setFormData({ ...formData, scheduledTime: v })}
                minDateTime={new Date()}
                slotProps={{ textField: { fullWidth: true, required: true } }}
              />
            </LocalizationProvider>

            {/* Recurring */}
            <FormControlLabel
              control={
                <Switch
                  checked={formData.recurring}
                  onChange={(e) => setFormData({ ...formData, recurring: e.target.checked })}
                />
              }
              label="رسالة متكررة"
            />
            {formData.recurring && (
              <FormControl fullWidth>
                <InputLabel>نمط التكرار</InputLabel>
                <Select
                  value={formData.recurringPattern}
                  label="نمط التكرار"
                  onChange={(e) => setFormData({ ...formData, recurringPattern: e.target.value })}
                >
                  <MenuItem value="DAILY">يومياً</MenuItem>
                  <MenuItem value="WEEKLY">أسبوعياً</MenuItem>
                  <MenuItem value="MONTHLY">شهرياً</MenuItem>
                </Select>
              </FormControl>
            )}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)} disabled={loading}>إلغاء</Button>
          <Button
            variant="contained"
            onClick={handleCreateCampaign}
            disabled={loading}
            startIcon={<CampaignIcon />}
          >
            {loading ? "جاري الإنشاء..." : "إنشاء الحملة"}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default TelegramCampaigns;

import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Chip,
  IconButton,
  Switch,
  FormControlLabel,
  Autocomplete,
  Tabs,
  Tab,
  Tooltip,
  Alert
} from "@mui/material";
import {
  Add as AddIcon,
  Cancel as CancelIcon,
  Schedule as ScheduleIcon,
  Replay as RescheduleIcon
} from "@mui/icons-material";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { LocalizationProvider, DateTimePicker } from "@mui/x-date-pickers";
import { apiClient } from "../../services/apiClient";
import { ar } from "date-fns/locale";

interface SchedulerFormData {
  userbotConfigId: string;
  chatIds: string[];
  message: string;
  scheduledTime: Date;
  recurring: boolean;
  recurringPattern: string;
}

interface UserbotConfig {
  id: string;
  label: string;
  clientPhone?: string;
}

interface TelegramDialog {
  id: string;
  name: string;
}

interface ScheduledMessage {
  id: string;
  userbotConfigId: string;
  chatId: string;
  message: string;
  scheduledTime: string | Date;
  status: string;
  recurring: boolean;
  recurringPattern?: string;
  error?: string;
}

const TelegramScheduler = () => {
  const [scheduledMessages, setScheduledMessages] = useState<ScheduledMessage[]>([]);
  const [userbots, setUserbots] = useState<UserbotConfig[]>([]);
  const [dialogs, setDialogs] = useState<TelegramDialog[]>([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [formData, setFormData] = useState<SchedulerFormData>({
    userbotConfigId: "",
    chatIds: [],
    message: "",
    scheduledTime: new Date(Date.now() + 3600000),
    recurring: false,
    recurringPattern: "DAILY",
  });
  const [currentTab, setCurrentTab] = useState("ALL");

  useEffect(() => {
    fetchUserbots();
    fetchScheduledMessages();

    const interval = setInterval(() => {
      fetchScheduledMessages(false);
    }, 30000);

    return () => clearInterval(interval);
  }, []);

  const fetchUserbots = async () => {
    try {
      const response = await apiClient.get("/api/v1/telegram/userbots");
      setUserbots(response.data.data || []);
    } catch (error) {
      console.error("Error fetching userbots:", error);
    }
  };

  const fetchScheduledMessages = async (showLoading = true) => {
    if (showLoading) setLoading(true);
    try {
      const response = await apiClient.get(
        "/api/v1/telegram-advanced/scheduled-messages",
      );
      setScheduledMessages(response.data.data || []);
    } catch (error) {
      console.error("Error fetching scheduled messages:", error);
      if (showLoading) setError("فشل تحميل الرسائل المجدولة");
    } finally {
      if (showLoading) setLoading(false);
    }
  };

  const fetchDialogs = async (userbotConfigId) => {
    if (!userbotConfigId) return;
    try {
      const response = await apiClient.get(
        `/api/v1/userbot/dialogs?userbotConfigId=${userbotConfigId}`,
      );
      setDialogs(response.data.data || []);
    } catch (error) {
      console.error("Error fetching dialogs:", error);
    }
  };

  const handleOpenDialog = () => {
    setFormData({
      userbotConfigId: userbots[0]?.id || "",
      chatIds: [],
      message: "",
      scheduledTime: new Date(Date.now() + 3600000),
      recurring: false,
      recurringPattern: "DAILY",
    });
    if (userbots[0]?.id) {
      fetchDialogs(userbots[0].id);
    }
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
  };

  const handleUserbotChange = (userbotConfigId) => {
    setFormData({ ...formData, userbotConfigId, chatIds: [] });
    fetchDialogs(userbotConfigId);
  };

  const handleSchedule = async () => {
    // Clean chatIds to remove any duplicates or nulls
    const cleanChatIds = formData.chatIds.filter(id => id && id !== 'unknown');
    
    if (!formData.userbotConfigId || cleanChatIds.length === 0 || !formData.message) {
      setError("يرجى ملء جميع الحقول المطلوبة (محادثة واحدة على الأقل صالحة)");
      return;
    }

    if (formData.scheduledTime < new Date()) {
      setError("لا يمكن جدولة رسالة في وقت ماضٍ");
      return;
    }

    setLoading(true);
    try {
      await apiClient.post(
        "/api/v1/telegram-advanced/scheduled-messages",
        { ...formData, chatIds: cleanChatIds },
      );
      fetchScheduledMessages();
      handleCloseDialog();
    } catch (error) {
      console.error("Error scheduling message:", error);
      setError("فشل جدولة الرسالة");
    } finally {
      setLoading(false);
    }
  };

  const handleReschedule = (msg) => {
    setFormData({
      userbotConfigId: msg.userbotConfigId || userbots[0]?.id || "",
      chatIds: [msg.chatId],
      message: msg.message || "",
      scheduledTime: new Date(Date.now() + 3600000),
      recurring: msg.recurring || false,
      recurringPattern: msg.recurringPattern || "DAILY",
    });
    if (msg.userbotConfigId) fetchDialogs(msg.userbotConfigId);
    setOpenDialog(true);
  };

  const handleCancel = async (messageId) => {
    if (!window.confirm("هل أنت متأكد من إلغاء هذه الرسالة المجدولة؟")) return;

    setLoading(true);
    try {
      await apiClient.post(
        `/api/v1/telegram-advanced/scheduled-messages/${messageId}/cancel`,
      );
      fetchScheduledMessages();
    } catch (error) {
      console.error("Error cancelling message:", error);
      setError("فشل إلغاء الرسالة");
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "SENT":
        return "success";
      case "PENDING":
        return "warning";
      case "FAILED":
        return "error";
      case "CANCELLED":
        return "default";
      default:
        return "info";
    }
  };

  const getStatusLabel = (status) => {
    switch (status) {
      case "PENDING":
        return "قيد الانتظار";
      case "SENT":
        return "تم الإرسال";
      case "FAILED":
        return "فشل";
      case "CANCELLED":
        return "ملغي";
      default:
        return status;
    }
  };

  const getRecurringLabel = (pattern) => {
    switch (pattern) {
      case "DAILY":
        return "يومي";
      case "WEEKLY":
        return "أسبوعي";
      case "MONTHLY":
        return "شهري";
      default:
        return pattern;
    }
  };

  return (
    <Box sx={{ p: 3, direction: "rtl" }}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Typography variant="h4">⏰ جدولة الرسائل</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={handleOpenDialog}
          disabled={userbots.length === 0}
        >
          جدولة رسالة
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError("")}>
          {error}
        </Alert>
      )}

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={currentTab} onChange={(e, val) => setCurrentTab(val)} aria-label="message status tabs">
          <Tab label="الكل" value="ALL" />
          <Tab label="قيد الانتظار" value="PENDING" />
          <Tab label="تم الإرسال" value="SENT" />
          <Tab label="فشل" value="FAILED" />
          <Tab label="ملغاة" value="CANCELLED" />
        </Tabs>
      </Box>

      <Box sx={{ display: "grid", gap: 2 }}>
        {scheduledMessages.filter(msg => currentTab === "ALL" || msg.status === currentTab).map((msg) => (
          <Card key={msg.id}>
            <CardContent>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "start",
                }}
              >
                <Box sx={{ flex: 1 }}>
                  <Box
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 1,
                      mb: 1,
                    }}
                  >
                    <ScheduleIcon color="action" />
                    <Typography variant="h6">
                      {new Date(msg.scheduledTime).toLocaleString("ar-EG")}
                    </Typography>
                    <Chip
                      label={getStatusLabel(msg.status)}
                      color={getStatusColor(msg.status)}
                      size="small"
                    />
                    {msg.recurring && (
                      <Chip
                        label={`🔄 ${getRecurringLabel(msg.recurringPattern)}`}
                        size="small"
                        color="info"
                      />
                    )}
                  </Box>
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{ mb: 1 }}
                  >
                    <strong>المحادثة:</strong> {msg.chatId}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {msg.message.substring(0, 150)}
                    {msg.message.length > 150 ? "..." : ""}
                  </Typography>
                  {msg.status === "FAILED" && msg.error && (
                    <Alert severity="error" sx={{ mt: 1 }}>
                      {msg.error}
                    </Alert>
                  )}
                </Box>
                <Box sx={{ display: "flex", gap: 1 }}>
                  {(msg.status === "FAILED" || msg.status === "CANCELLED") && (
                    <Tooltip title="إعادة الجدولة">
                      <IconButton
                        color="primary"
                        onClick={() => handleReschedule(msg)}
                        disabled={loading}
                      >
                        <RescheduleIcon />
                      </IconButton>
                    </Tooltip>
                  )}
                  {msg.status === "PENDING" && (
                    <Tooltip title="إلغاء الجدولة">
                      <IconButton
                        color="error"
                        onClick={() => handleCancel(msg.id)}
                        disabled={loading}
                      >
                        <CancelIcon />
                      </IconButton>
                    </Tooltip>
                  )}
                </Box>
              </Box>
            </CardContent>
          </Card>
        ))}

        {scheduledMessages.filter(msg => currentTab === "ALL" || msg.status === currentTab).length === 0 && !loading && (
          <Card>
            <CardContent>
              <Typography
                variant="body1"
                color="text.secondary"
                textAlign="center"
              >
                لا توجد رسائل مجدولة. انقر على "جدولة رسالة" للبدء.
              </Typography>
            </CardContent>
          </Card>
        )}
      </Box>

      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="md"
        fullWidth
        dir="rtl"
      >
        <DialogTitle>⏰ جدولة رسالة جديدة</DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 2 }}>
            <FormControl fullWidth>
              <InputLabel>اختر Userbot</InputLabel>
              <Select
                value={formData.userbotConfigId}
                onChange={(e) => handleUserbotChange(e.target.value)}
                label="اختر Userbot"
              >
                {userbots.map((bot) => (
                  <MenuItem key={bot.id} value={bot.id}>
                    {bot.label} ({bot.clientPhone || "غير متصل"})
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <Autocomplete
              multiple
              fullWidth
              disabled={!formData.userbotConfigId}
              options={dialogs}
              getOptionLabel={(option) => option.name || ""}
              isOptionEqualToValue={(option, value) => option.id === value.id}
              renderOption={(props, option) => (
                <li {...props} key={option.id}>
                  {option.name}
                </li>
              )}
              value={dialogs.filter(d => formData.chatIds.includes(d.id))}
              onChange={(event, newValue) => {
                setFormData({ ...formData, chatIds: newValue.map(v => v.id) });
              }}
              renderInput={(params) => (
                <TextField {...params} label="اختر المحادثات" required={formData.chatIds.length === 0} />
              )}
            />

            <TextField
              label="الرسالة"
              value={formData.message}
              onChange={(e) =>
                setFormData({ ...formData, message: e.target.value })
              }
              fullWidth
              required
              multiline
              rows={6}
            />

            <LocalizationProvider
              dateAdapter={AdapterDateFns}
              adapterLocale={ar}
            >
              <DateTimePicker
                label="وقت الإرسال"
                value={formData.scheduledTime}
                onChange={(newValue) =>
                  setFormData({ ...formData, scheduledTime: newValue })
                }
                minDateTime={new Date()}
                slotProps={{
                  textField: {
                    fullWidth: true,
                    required: true,
                  },
                }}
              />
            </LocalizationProvider>

            <FormControlLabel
              control={
                <Switch
                  checked={formData.recurring}
                  onChange={(e) =>
                    setFormData({ ...formData, recurring: e.target.checked })
                  }
                />
              }
              label="رسالة متكررة"
            />

            {formData.recurring && (
              <FormControl fullWidth>
                <InputLabel>نمط التكرار</InputLabel>
                <Select
                  value={formData.recurringPattern}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      recurringPattern: e.target.value,
                    })
                  }
                  label="نمط التكرار"
                >
                  <MenuItem value="DAILY">يومي</MenuItem>
                  <MenuItem value="WEEKLY">أسبوعي</MenuItem>
                  <MenuItem value="MONTHLY">شهري</MenuItem>
                </Select>
              </FormControl>
            )}

            <Alert severity="info">
              💡 سيتم إرسال الرسالة تلقائياً في الوقت المحدد
            </Alert>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>إلغاء</Button>
          <Button
            onClick={handleSchedule}
            variant="contained"
            startIcon={<ScheduleIcon />}
            disabled={loading}
          >
            {loading ? "جاري الجدولة..." : "جدولة"}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default TelegramScheduler;

import React, {
  useState,
  useEffect,
  useRef,
  useMemo,
  useCallback,
} from "react";
import { useAuth } from "../../hooks/useAuthSimple";
import { apiClient } from "../../services/apiClient";

// Alias for easier usage
const api = apiClient;

// Media cache to avoid re-downloading the same media
const mediaCache = new Map<
  string,
  { blobUrl: string; mimeType: string; timestamp: number }
>();
const CACHE_MAX_AGE = 30 * 60 * 1000; // 30 minutes

// Cleanup old cache entries periodically
setInterval(
  () => {
    const now = Date.now();
    for (const [key, value] of mediaCache.entries()) {
      if (now - value.timestamp > CACHE_MAX_AGE) {
        URL.revokeObjectURL(value.blobUrl);
        mediaCache.delete(key);
      }
    }
  },
  5 * 60 * 1000,
); // Check every 5 minutes
import {
  PaperAirplaneIcon,
  ChatBubbleLeftRightIcon,
  ArrowPathIcon,
  MagnifyingGlassIcon,
  PhotoIcon,
} from "@heroicons/react/24/outline";

interface Chat {
  id: string;
  name: string;
  unreadCount: number;
  lastMessage: string;
  date: number;
  isGroup: boolean;
  isUser: boolean;
  isChannel: boolean;
}

interface Message {
  id: number | string;
  text: string;
  date: number;
  senderId: string | null;
  senderName?: string;
  isOut: boolean;
  media: { type: string } | null | boolean; // Can be object with type, null, or boolean (for backwards compat)
}

// Internal Media Component - Extracted to prevent re-remounting
const MediaMessage = ({
  msg,
  userbotId,
  chatId,
}: {
  msg: Message;
  userbotId: string;
  chatId?: string;
}) => {
  // Create cache key
  const cacheKey = useMemo(
    () => `${userbotId}-${chatId}-${msg.id}`,
    [userbotId, chatId, msg.id],
  );

  // Check cache first
  const cachedMedia = useMemo(() => {
    const cached = mediaCache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp < CACHE_MAX_AGE) {
      return cached;
    }
    return null;
  }, [cacheKey]);

  const [mediaUrl, setMediaUrl] = useState<string | null>(
    cachedMedia?.blobUrl || null,
  );
  const [loading, setLoading] = useState(!cachedMedia);
  const [error, setError] = useState(false);
  const [mimeType, setMimeType] = useState<string | null>(
    cachedMedia?.mimeType || null,
  );

  // Determine media type from the media object
  const getMediaType = () => {
    if (!msg.media || typeof msg.media !== "object") return "unknown";
    const type = (msg.media as any).type || "";
    if (type.includes("Photo") || type === "MessageMediaPhoto") return "image";
    if (type.includes("Video") || type === "MessageMediaVideo") return "video";
    if (type.includes("Document") || type === "MessageMediaDocument")
      return "document";
    if (type.includes("Audio") || type === "MessageMediaAudio") return "audio";
    if (type.includes("WebPage")) return "webpage";
    return "unknown";
  };

  const mediaType = getMediaType();

  // Check if media is WebPage (link preview) - often not downloadable
  const isWebPage = mediaType === "webpage";

  const loadMedia = useCallback(async () => {
    // Check cache first
    const cached = mediaCache.get(cacheKey);
    const hasValidCache =
      cached && Date.now() - cached.timestamp < CACHE_MAX_AGE;

    // Don't auto-load WebPage previews
    if (isWebPage) {
      setLoading(false);
      return;
    }

    // Use cached media if available
    if (hasValidCache) {
      setMediaUrl(cached.blobUrl);
      setMimeType(cached.mimeType);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(false);
    try {
      const response = await api.get("/userbot/message/media", {
        params: {
          userbotConfigId: userbotId,
          chatId: chatId,
          messageId: msg.id,
        },
        responseType: "blob",
      });

      const url = URL.createObjectURL(response.data);
      const detectedMimeType =
        response.data.type ||
        response.headers["content-type"] ||
        "application/octet-stream";

      // Cache the media
      mediaCache.set(cacheKey, {
        blobUrl: url,
        mimeType: detectedMimeType,
        timestamp: Date.now(),
      });

      setMediaUrl(url);
      setMimeType(detectedMimeType);
      setLoading(false);
    } catch (err: any) {
      console.error("Failed to load media", err);
      setError(true);
      setLoading(false);
    }
  }, [cacheKey, isWebPage, msg.id, userbotId, chatId, mediaType]);

  useEffect(() => {
    // Check cache directly (not through cachedMedia which might be stale)
    const cached = mediaCache.get(cacheKey);
    const hasValidCache =
      cached && Date.now() - cached.timestamp < CACHE_MAX_AGE;

    if (isWebPage) {
      setLoading(false);
    } else if (hasValidCache) {
      // Use cached media immediately
      // Check if mediaUrl needs to be updated (may differ if cache was populated after component mount)
      setMediaUrl(cached.blobUrl);
      setMimeType(cached.mimeType);
      setLoading(false);
    } else {
      // No valid cache - need to load media (even if mediaUrl exists, it might be stale/invalid)
      // loadMedia will check cache again and load from API if needed
      loadMedia();
    }

    // Don't revoke blob URLs here - they're cached and will be cleaned up by the cache cleanup interval
    return () => {
      // Note: We don't revoke blob URLs here because they're cached
      // The cache cleanup will handle revoking old URLs
    };
  }, [msg.id, userbotId, chatId, isWebPage, cacheKey, loadMedia]);

  // Determine if mime type indicates image, video, or document
  // Priority: MIME type (from API) > Telegram media type
  const isImage = mimeType
    ? mimeType.startsWith("image/")
    : mediaType === "image";
  const isVideo = mimeType
    ? mimeType.startsWith("video/")
    : mediaType === "video";
  const isAudio = mimeType
    ? mimeType.startsWith("audio/")
    : mediaType === "audio";

  // For documents, check if MIME type indicates it's actually an image/video/audio
  const isDocumentAsImage =
    mediaType === "document" && mimeType?.startsWith("image/");
  const isDocumentAsVideo =
    mediaType === "document" && mimeType?.startsWith("video/");
  const isDocumentAsAudio =
    mediaType === "document" && mimeType?.startsWith("audio/");

  const finalIsImage = isImage || isDocumentAsImage;
  const finalIsVideo = isVideo || isDocumentAsVideo;
  const finalIsAudio = isAudio || isDocumentAsAudio;

  if (isWebPage) return null; // Hide WebPage media for now

  if (loading) {
    return (
      <div className="h-40 w-40 bg-gray-200 dark:bg-gray-700 animate-pulse rounded flex items-center justify-center">
        <PhotoIcon className="w-8 h-8 text-gray-400 dark:text-gray-500" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center p-2 border border-red-200 dark:border-red-800 rounded bg-red-50 dark:bg-red-900/20 mb-2">
        <div className="text-xs text-red-500 dark:text-red-400 mb-1">
          Failed to load media
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation();
            loadMedia();
          }}
          className="text-[10px] bg-white dark:bg-gray-800 border border-red-300 dark:border-red-700 px-2 py-1 rounded hover:bg-red-50 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400 font-medium"
        >
          Retry
        </button>
      </div>
    );
  }

  if (!mediaUrl) return null;

  // Render based on media type
  if (finalIsImage) {
    return (
      <div className="mb-2 -mx-3 -mt-3 first:mt-0">
        <img
          src={mediaUrl}
          alt="Media"
          className="w-full rounded-t-lg max-h-96 object-contain cursor-pointer"
          style={{ maxWidth: "400px", display: "block" }}
          onClick={() => window.open(mediaUrl, "_blank")}
          onError={() => {
            setError(true);
          }}
        />
      </div>
    );
  }

  if (finalIsVideo) {
    return (
      <div className="mb-2 -mx-3 -mt-3 first:mt-0">
        <video
          src={mediaUrl}
          controls
          className="w-full rounded-t-lg max-h-96 cursor-pointer"
          style={{ maxWidth: "400px", display: "block" }}
          onClick={(e) => e.stopPropagation()}
        >
          Your browser does not support the video tag.
        </video>
      </div>
    );
  }

  if (finalIsAudio) {
    return (
      <div className="mb-2 p-2 bg-gray-100 dark:bg-gray-700 rounded-lg">
        <audio src={mediaUrl} controls className="w-full">
          Your browser does not support the audio tag.
        </audio>
      </div>
    );
  }

  // For documents or unknown types, show download link
  return (
    <div className="mb-2 p-3 border border-gray-300 dark:border-gray-600 rounded-lg bg-gray-50 dark:bg-gray-700">
      <div className="flex items-center gap-2">
        <PhotoIcon className="w-5 h-5 text-gray-500 dark:text-gray-400" />
        <span className="text-sm text-gray-700 dark:text-gray-200">
          Media file
        </span>
        <a
          href={mediaUrl}
          download
          className="ml-auto text-xs bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600 transition"
          onClick={(e) => e.stopPropagation()}
        >
          Download
        </a>
      </div>
      {mimeType && (
        <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
          {mimeType}
        </div>
      )}
    </div>
  );
};

const TelegramUserbot: React.FC = () => {
  const { user } = useAuth();
  const [step, setStep] = useState<"SELECT" | "LOGIN" | "VERIFY" | "CHATS">(
    "SELECT",
  );

  // Userbot Selection
  const [userbots, setUserbots] = useState<any[]>([]);
  const [selectedUserbot, setSelectedUserbot] = useState<string | null>(null);

  // Chats & Messages

  const [chats, setChats] = useState<Chat[]>([]);
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [messageText, setMessageText] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  // Filtered chats
  const filteredChats = chats.filter(
    (chat) =>
      chat.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (chat.lastMessage &&
        chat.lastMessage.toLowerCase().includes(searchTerm.toLowerCase())),
  );

  // Auto-scroll ref
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // ... removed internal MediaMessage ...

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Load userbots on mount
  useEffect(() => {
    if (user?.companyId) {
      loadUserbots();
    }
  }, [user?.companyId]);

  // Auto-fetch chats when userbot is selected and step is CHATS (for auto-login)
  useEffect(() => {
    if (selectedUserbot && step === "CHATS" && chats.length === 0) {
      console.log(
        "🔄 Auto-fetching chats for logged in userbot:",
        selectedUserbot,
      );
      fetchChats();
    }
  }, [selectedUserbot, step]);

  const loadUserbots = async () => {
    if (!user?.companyId) return;

    try {
      const response = await api.get("/v1/telegram/userbots");

      const userbotsList = response.data?.data || response.data || [];
      setUserbots(Array.isArray(userbotsList) ? userbotsList : []);

      // Check if any userbot is already logged in (has active session)
      const loggedInUserbot = userbotsList.find((ub: any) => ub.sessionString);

      if (loggedInUserbot) {
        // Userbot is already logged in, go directly to chats
        console.log("✅ Found logged in userbot:", loggedInUserbot.id);
        setSelectedUserbot(loggedInUserbot.id);
        setStep("CHATS");
      } else {
        // No connected userbot found, show selection (which will show "not connected" state if bots exist but aren't connected)
        setStep("SELECT");
      }
    } catch (error: any) {
      console.error("Failed to load userbots:", error);
      if (error.response?.status === 404) {
        // No userbots configured yet - this is OK
        setUserbots([]);
        setStep("SELECT");
      } else {
        // (error.response?.data?.error || 'Failed to load userbots. Please add a userbot in Settings first.'); // Removed setError
      }
    }
  };

  // 3. Fetch Chats
  const fetchChats = async () => {
    if (!selectedUserbot) {
      console.warn("⚠️ Cannot fetch chats: no userbot selected");
      return;
    }

    try {
      console.log("📥 Fetching chats for userbot:", selectedUserbot);
      const res = await api.get("/userbot/dialogs", {
        params: {
          userbotConfigId: selectedUserbot,
        },
      });

      if (res.data.success) {
        console.log("✅ Chats fetched:", res.data.data?.length || 0);
        setChats(res.data.data || []);
        setStep("CHATS");
      } else {
        console.error("❌ Failed to fetch chats:", res.data.error);

        // Check if session expired
        if (
          res.data.error === "AUTH_KEY_UNREGISTERED" ||
          res.data.requiresReauth
        ) {
          // Session expired.
          setStep("SELECT");
          // Clear any cached userbot selection
          setSelectedUserbot(null);
        } else {
          // (res.data.error || res.data.message || 'Failed to fetch chats');
        }
      }
    } catch (err: any) {
      console.error("❌ Failed to fetch chats:", err);
      const errorMessage =
        err.response?.data?.error ||
        err.response?.data?.message ||
        err.message ||
        "Failed to fetch chats";

      // Check if it's an auth error
      if (
        errorMessage.includes("AUTH_KEY_UNREGISTERED") ||
        err.response?.data?.requiresReauth
      ) {
        // Session expired.
        setStep("SELECT");
        setSelectedUserbot(null);
      } else {
        if (step === "CHATS") {
          // If we're already on CHATS step, maybe session expired
          console.warn("⚠️ Session might be expired, redirecting to select");
          setStep("SELECT");
        }
      }
    }
  };

  // 4. Fetch Messages
  useEffect(() => {
    if (!selectedChat || !user?.companyId) return;

    const fetchMessages = async () => {
      if (!selectedUserbot) return;

      try {
        const res = await api.get("/userbot/messages", {
          params: {
            userbotConfigId: selectedUserbot,
            chatId: selectedChat.id,
          },
        });
        // Sort messages by date (oldest first) before setting
        const sortedMessages = (res.data.data || []).sort(
          (a: Message, b: Message) => a.date - b.date,
        );
        setMessages(sortedMessages);
      } catch (err) {
        console.error("Failed to fetch messages", err);
      }
    };

    fetchMessages();
    const interval = setInterval(fetchMessages, 3000); // Polling every 3s
    return () => clearInterval(interval);
  }, [selectedChat, user?.companyId]);

  // Check session on mount

  // 5. Send Message
  const handleSendMessage = async () => {
    if (!selectedChat || !messageText.trim() || !selectedUserbot) return;

    try {
      await api.post("/userbot/message", {
        userbotConfigId: selectedUserbot,
        chatId: selectedChat.id,
        message: messageText,
      });

      // Optimistic update
      const newMessage: Message = {
        id: Date.now(),
        text: messageText,
        date: Math.floor(Date.now() / 1000),
        senderId: "me",
        isOut: true,
        media: false,
      };
      setMessages((prev) => [...prev, newMessage]);
      setMessageText("");
    } catch (error) {
      console.error("Error sending message:", error);
    }
  };

  // 6. Logout

  // 7. Send File
  const handleSendFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!selectedChat || !e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);
    formData.append("userbotConfigId", selectedUserbot || "");
    formData.append("chatId", selectedChat.id);

    try {
      await api.post("/userbot/message/file", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      // Optimistic Update (Text only placeholder)
      const newMessage: Message = {
        id: Date.now(),
        text: `[File: ${file.name}]`,
        date: Math.floor(Date.now() / 1000),
        senderId: "me",
        isOut: true,
        media: true,
      };
      setMessages((prev) => [...prev, newMessage]);
    } catch (err: any) {
      alert("Failed to upload: " + err.message);
    }
  };

  return (
    <div className="p-6 w-full h-[calc(100vh-100px)] flex flex-col">
      <div className="mb-6 flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2 dark:text-white">
            <PaperAirplaneIcon className="h-8 w-8 text-blue-500" />
            Telegram Userbot
          </h1>
          <p className="text-gray-500 dark:text-gray-400">
            Connect your personal Telegram account
          </p>
        </div>
      </div>

      {step === "SELECT" && (
        <div className="flex-1 flex justify-center items-center">
          <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-lg w-full max-w-md text-center">
            <h2 className="text-xl font-bold mb-4 dark:text-white">
              Select Userbot
            </h2>
            {!userbots || userbots.length === 0 ? (
              <div className="py-4">
                <PaperAirplaneIcon className="h-16 w-16 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500 mb-6">
                  No Telegram Userbots connected yet.
                </p>
                <a
                  href="/settings/telegram"
                  className="inline-flex items-center justify-center px-6 py-3 border border-transparent text-base font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700"
                >
                  Go to Settings to Connect
                </a>
              </div>
            ) : (
              <div className="space-y-3">
                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                  Select an account to start chatting:
                </p>
                {Array.isArray(userbots) &&
                  userbots.map((userbot: any) => {
                    if (!userbot || !userbot.id) return null;
                    const isConnected = userbot.sessionString;

                    if (!isConnected) return null; // Only show connected bots

                    return (
                      <button
                        key={userbot.id}
                        onClick={() => {
                          setSelectedUserbot(userbot.id);
                          // Check if it's already connected
                          if (userbot.sessionString) {
                            setStep("CHATS");
                          } else {
                            setStep("SELECT");
                          }
                        }}
                        className="w-full p-4 border-2 border-gray-200 dark:border-gray-700 rounded-lg hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-left"
                      >
                        <div className="font-semibold flex items-center justify-between dark:text-white">
                          <span>{userbot.label || "Unnamed Userbot"}</span>
                          <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded">
                            Connected
                          </span>
                        </div>
                        <div className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                          {userbot.clientPhone}
                        </div>
                      </button>
                    );
                  })}

                {userbots.filter((u) => u.sessionString).length === 0 && (
                  <div className="py-4">
                    <p className="text-amber-600 mb-4">
                      You have added Userbots but none are connected.
                    </p>
                    <a
                      href="/settings/telegram"
                      className="text-blue-600 font-medium hover:underline"
                    >
                      Go to Settings to Complete Setup
                    </a>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}

      {step === "CHATS" && (
        <div className="flex-1 flex bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border dark:border-gray-700">
          {/* Sidebar */}
          <div className="w-80 border-r dark:border-r-gray-700 flex flex-col bg-gray-50 dark:bg-gray-800">
            <div className="p-4 border-b dark:border-b-gray-700 flex justify-between items-center">
              <h3 className="font-bold dark:text-white">Chats</h3>
              <button
                onClick={fetchChats}
                className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded dark:text-gray-300"
              >
                <ArrowPathIcon className="h-5 w-5" />
              </button>
            </div>

            {/* Search Bar */}
            <div className="p-3 border-b dark:border-b-gray-700 bg-white dark:bg-gray-800">
              <div className="relative">
                <MagnifyingGlassIcon className="h-5 w-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  placeholder="Search chats..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 bg-gray-100 dark:bg-gray-700 border-none rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm dark:text-white"
                />
              </div>
            </div>

            {/* Logout should be handled in settings mostly, but let's keep a disconnect or redirect */}
            <div className="px-4 pb-2">
              <a
                href="/settings/telegram"
                className="text-xs text-gray-500 hover:underline block pt-2"
              >
                Manage Connections in Settings
              </a>
            </div>
            <div className="flex-1 overflow-y-auto">
              {filteredChats.map((chat) => (
                <div
                  key={chat.id}
                  onClick={() => setSelectedChat(chat)}
                  className={`p-3 border-b dark:border-b-gray-700 cursor-pointer hover:bg-white dark:hover:bg-gray-750 transition-colors ${selectedChat?.id === chat.id ? "bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800" : ""}`}
                >
                  <div className="flex justify-between mb-1">
                    <span className="font-semibold truncate dark:text-white">
                      {chat.name}
                    </span>
                    <span className="text-xs text-gray-400">
                      {new Date(chat.date * 1000).toLocaleDateString()}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <div className="text-sm text-gray-500 dark:text-gray-400 truncate w-4/5">
                      {chat.lastMessage}
                    </div>
                    {chat.unreadCount > 0 && (
                      <span className="bg-green-500 text-white text-xs px-2 py-0.5 rounded-full">
                        {chat.unreadCount}
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Chat Area */}
          <div className="flex-1 flex flex-col bg-slate-50 dark:bg-gray-900">
            {selectedChat ? (
              <>
                <div className="p-4 bg-white dark:bg-gray-800 border-b dark:border-b-gray-700 shadow-sm flex-none">
                  <h3 className="font-bold text-lg dark:text-white">
                    {selectedChat.name}
                  </h3>
                </div>

                <div className="flex-1 p-4 overflow-y-auto space-y-4">
                  {messages
                    .sort((a, b) => a.date - b.date) // Sort by date (oldest first)
                    .map((msg, index) => (
                      <div
                        key={`${msg.id}-${index}`}
                        className={`flex ${msg.isOut ? "justify-end" : "justify-start"}`}
                      >
                        <div
                          className={`max-w-[70%] rounded-lg shadow-sm overflow-hidden ${
                            msg.isOut
                              ? "bg-blue-600 text-white rounded-br-none"
                              : "bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 rounded-bl-none"
                          } ${msg.media ? "p-0" : "p-3"}`}
                        >
                          {/* Sender name for incoming messages */}
                          {!msg.isOut && msg.senderName && (
                            <div
                              className={`text-xs font-semibold mb-1 px-3 pt-3 ${msg.isOut ? "text-blue-200" : "text-gray-600 dark:text-gray-400"}`}
                            >
                              {msg.senderName}
                            </div>
                          )}
                          {msg.media && selectedUserbot && selectedChat && (
                            <MediaMessage
                              msg={msg}
                              userbotId={selectedUserbot}
                              chatId={selectedChat.id}
                            />
                          )}
                          {!msg.media && (
                            <div className="break-words">{msg.text}</div>
                          )}
                          {msg.media && msg.text && (
                            <div className="break-words mt-2 px-3">
                              {msg.text}
                            </div>
                          )}
                          <div
                            className={`text-[10px] mt-1 flex justify-between items-center px-3 pb-2 ${msg.isOut ? "text-blue-200" : "text-gray-400"}`}
                          >
                            <span>
                              {new Date(msg.date * 1000).toLocaleTimeString(
                                [],
                                { hour: "2-digit", minute: "2-digit" },
                              )}
                            </span>
                            {msg.isOut && <span className="ml-2">✓</span>}
                          </div>
                        </div>
                      </div>
                    ))}
                  <div ref={messagesEndRef} />
                </div>

                <div className="p-4 bg-white dark:bg-gray-800 border-t dark:border-t-gray-700 flex gap-2 flex-none items-center">
                  <label className="cursor-pointer p-2 hover:bg-gray-100 rounded-full text-gray-500">
                    <input
                      type="file"
                      className="hidden"
                      onChange={handleSendFile}
                    />
                    <span className="text-xl">📎</span>
                  </label>
                  <input
                    type="text"
                    className="flex-1 border dark:border-gray-600 rounded-lg p-3 outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-700 dark:text-white"
                    placeholder="Type a message..."
                    value={messageText}
                    onChange={(e) => setMessageText(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && handleSendMessage()}
                  />
                  <button
                    onClick={handleSendMessage}
                    className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition"
                  >
                    <PaperAirplaneIcon className="h-6 w-6" />
                  </button>
                </div>
              </>
            ) : (
              <div className="flex-1 flex flex-col justify-center items-center text-gray-400">
                <ChatBubbleLeftRightIcon className="h-20 w-20 mb-4 opacity-20" />
                <p>Select a chat to view conversation</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default TelegramUserbot;

import React, { useState, useEffect, useRef } from "react";
import {
  PaperAirplaneIcon,
  MagnifyingGlassIcon,
  TrashIcon,
  CpuChipIcon,
  UserIcon,
  ChatBubbleLeftRightIcon,
  ExclamationTriangleIcon,
  SparklesIcon,
  XMarkIcon,
  Squares2X2Icon,
  ArrowPathIcon,
  QueueListIcon,
  PhotoIcon, // ✅ NEW: للصور
  XCircleIcon, // ✅ NEW: لحذف الصور
} from "@heroicons/react/24/outline";
import {
  testChatService,
  TestConversation,
  TestMessage,
  AITestResponse,
} from "../../services/testChatService";
import CompanyProtectedRoute from "../../components/protection/CompanyProtectedRoute";
import useSocket from "../../hooks/useSocket";

// إضافة معلومات الرد إلى TestMessage
interface ExtendedTestMessage extends TestMessage {
  aiResponseInfo?: AITestResponse | null;
}

// واجهة للدردشة المفتوحة
interface OpenChat {
  conversation: TestConversation;
  messages: ExtendedTestMessage[];
  newMessage: string;
  sending: boolean;
  isAiTyping: boolean;
  error: string | null;
}

const AITestChatContent: React.FC = () => {
  const [conversations, setConversations] = useState<TestConversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<TestConversation | null>(null);
  const [messages, setMessages] = useState<ExtendedTestMessage[]>([]);
  const [newMessage, setNewMessage] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [selectedImages, setSelectedImages] = useState<File[]>([]); // ✅ NEW: الصور المختارة
  const fileInputRef = useRef<HTMLInputElement>(null); // ✅ NEW: مرجع لـ input الملفات
  const [searchQuery, setSearchQuery] = useState("");
  const [isAiTyping, setIsAiTyping] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [conversationToDelete, setConversationToDelete] =
    useState<TestConversation | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [testResults, setTestResults] = useState<any>(null); // ✅ Restored
  const [runningTest, setRunningTest] = useState(false);
  const [selectedPlatform, setSelectedPlatform] = useState<string>("test-chat"); // ✅ NEW
  const [simulatedPostId, setSimulatedPostId] = useState<string>(""); // ✅ NEW
  const [simulatedAdId, setSimulatedAdId] = useState<string>(""); // ✅ NEW

  // ✅ NEW: حالة الدردشات المتعددة
  const [openChats, setOpenChats] = useState<Map<string, OpenChat>>(new Map());
  const [multiChatMode, setMultiChatMode] = useState(false);
  const [sendingToAll, setSendingToAll] = useState(false);
  const [selectedMessageForDetails, setSelectedMessageForDetails] =
    useState<ExtendedTestMessage | null>(null); // ✅ NEW: لتفاصيل الرسالة في العمود الجانبي
  const [smartSuggestions, setSmartSuggestions] = useState<string[]>([]); // ✅ NEW: للاقتراحات
  const [lastExtractedDetails, setLastExtractedDetails] = useState<any>(null); // ✅ NEW: للبيانات المستخرجة
  const [replyingTo, setReplyingTo] = useState<ExtendedTestMessage | null>(
    null,
  ); // ✅ NEW: للرد على رسالة

  const { socket, isConnected } = useSocket();
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);

  // ✅ Socket.IO Integration for Real-time Updates
  useEffect(() => {
    if (!socket || !isConnected) return;

    // Handle new message
    const handleNewMessage = (data: any) => {
      console.log("📨 [SOCKET] New message received:", data);

      // Update conversations list (last message)
      setConversations((prev) =>
        prev.map((conv) => {
          if (conv.id === data.conversationId) {
            return {
              ...conv,
              lastMessage: data.content || conv.lastMessage,
              lastMessageTime: new Date(),
            };
          }
          return conv;
        }),
      );

      // Map socket data to ExtendedTestMessage
      const newMessage: ExtendedTestMessage = {
        id: data.id,
        content: data.content,
        senderId: data.senderId,
        senderName: data.senderName, // Might need adjustment based on payload
        createdAt: new Date(data.createdAt),
        type: data.type || "text",
        isFromCustomer: data.isFromCustomer,
        status: "sent",
        conversationId: data.conversationId,
        aiResponseInfo:
          data.metadata?.aiResponseInfo ||
          (data.metadata
            ? JSON.parse(JSON.stringify(data.metadata))
            : undefined),
        // ✅ FIX: Map socket 'images' to 'attachments'
        attachments: data.images
          ? data.images.map((imgUrl: string) => ({
              type: "image",
              url: imgUrl,
              filename: "product-image.jpg",
            }))
          : undefined,
      };

      // 1. Update Selected Conversation
      if (
        selectedConversation &&
        data.conversationId === selectedConversation.id
      ) {
        setMessages((prev) => {
          // Avoid duplicates
          if (prev.some((m) => m.id === newMessage.id)) return prev;

          // Remove temp message if it matches (by content/type/time approx?)
          // Usually we rely on API response to replace temp, but socket might arrive too.
          // For now just append.
          return [...prev, newMessage];
        });

        // Stop typing indicator
        if (!newMessage.isFromCustomer) {
          setIsAiTyping(false);
          if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
        }

        // Scroll
        setTimeout(() => {
          messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
        }, 100);
      }

      // 2. Update Open Chats (Multi-mode)
      if (openChats.has(data.conversationId)) {
        setOpenChats((prev) => {
          const newMap = new Map(prev);
          const chat = newMap.get(data.conversationId);
          if (chat) {
            // Avoid duplicates check
            if (chat.messages.some((m) => m.id === newMessage.id)) return prev;

            newMap.set(data.conversationId, {
              ...chat,
              messages: [...chat.messages, newMessage],
              isAiTyping: !newMessage.isFromCustomer ? false : chat.isAiTyping,
            });
          }
          return newMap;
        });
      }
    };

    // Handle typing status
    const handleTyping = (data: {
      conversationId: string;
      isTyping: boolean;
    }) => {
      if (
        selectedConversation &&
        data.conversationId === selectedConversation.id
      ) {
        setIsAiTyping(data.isTyping);

        if (data.isTyping) {
          if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
          typingTimeoutRef.current = setTimeout(
            () => setIsAiTyping(false),
            15000,
          );
        }
      }

      if (openChats.has(data.conversationId)) {
        setOpenChats((prev) => {
          const newMap = new Map(prev);
          const chat = newMap.get(data.conversationId);
          if (chat) {
            newMap.set(data.conversationId, {
              ...chat,
              isAiTyping: data.isTyping,
            });
          }
          return newMap;
        });
      }
    };

    socket.on("new_message", handleNewMessage);
    socket.on("ai_typing", handleTyping);

    return () => {
      socket.off("new_message", handleNewMessage);
      socket.off("ai_typing", handleTyping);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    };
  }, [socket, isConnected, selectedConversation, openChats]);

  // تحميل المحادثات
  const loadConversations = async () => {
    try {
      setLoading(true);
      setError(null);
      console.log("🔄 Loading test conversations...");
      const result = await testChatService.getConversations();
      console.log("✅ Test conversations loaded:", result.data.length);
      setConversations(result.data);
    } catch (error: any) {
      console.error("❌ Error loading conversations:", error);
      setError(error.message || "فشل في تحميل المحادثات");
    } finally {
      setLoading(false);
    }
  };

  // تحميل الرسائل
  const loadMessages = async (conversationId: string) => {
    try {
      console.log("🔄 Loading messages for conversation:", conversationId);
      const messagesData = await testChatService.getMessages(conversationId);
      console.log("✅ Messages loaded:", messagesData.length);
      console.log(
        "🔍 [FRONTEND] Messages with aiResponseInfo:",
        messagesData.filter((msg) => msg.aiResponseInfo),
      );
      setMessages(
        messagesData.map((msg) => {
          const mappedMsg = {
            ...msg,
            createdAt: new Date(msg.createdAt),
          };
          if (msg.aiResponseInfo) {
            console.log(
              "✅ [FRONTEND] Message has aiResponseInfo:",
              msg.id,
              msg.aiResponseInfo,
            );
          }
          return mappedMsg;
        }),
      );

      // التمرير للأسفل
      setTimeout(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 100);
    } catch (error: any) {
      console.error("❌ Error loading messages:", error);
    }
  };

  // ✅ NEW: معالجة اختيار الصور
  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    const imageFiles = files.filter((file) => file.type.startsWith("image/"));

    if (imageFiles.length > 0) {
      setSelectedImages((prev) => [...prev, ...imageFiles].slice(0, 5)); // حد أقصى 5 صور
    }
  };

  // ✅ NEW: حذف صورة
  const removeImage = (index: number) => {
    setSelectedImages((prev) => prev.filter((_, i) => i !== index));
  };

  // إرسال رسالة
  const sendMessage = async () => {
    if (
      (!newMessage.trim() && selectedImages.length === 0) ||
      !selectedConversation ||
      sending
    )
      return;

    const images = [...selectedImages];
    const replyToId = replyingTo?.id; // ✅ NEW: حفظ معرف الرسالة المردود عليها

    const messageContent = newMessage.trim();
    setNewMessage("");
    setSelectedImages([]); // ✅ مسح الصور بعد الإرسال
    setReplyingTo(null); // ✅ إخفاء شريط الرد
    setSmartSuggestions([]); // ✅ مسح الاقتراحات
    setSending(true);
    setIsAiTyping(true);

    // إضافة رسالة المستخدم مؤقتاً
    const tempUserMessage: ExtendedTestMessage = {
      id: `temp_user_${Date.now()}`,
      content: messageContent,
      senderId: "user",
      senderName: "أنت",
      createdAt: new Date(),
      type: "text",
      isFromCustomer: true,
      status: "sending",
      conversationId: selectedConversation.id,
      metadata: replyToId ? { replyToMessageId: replyToId } : undefined, // ✅ NEW
    };

    setMessages((prev) => [...prev, tempUserMessage]);

    // التمرير للأسفل
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, 100);

    try {
      console.log("📤 Sending message to test chat:", messageContent);
      console.log("📸 Images:", images.length);

      // ✅ إرسال مع الصور
      const result = await testChatService.sendMessage(
        selectedConversation.id,
        messageContent,
        images, // ✅ تمرير الصور
        {
          // ✅ NEW: الميتا داتا الإضافية
          platform: selectedPlatform,
          ...(simulatedPostId ? { postId: simulatedPostId } : {}),
          ...(simulatedAdId ? { adId: simulatedAdId } : {}),
          replyToMessageId: replyToId, // ✅ NEW: تمرير معرف الرد
        },
      );
      console.log(
        "✅ Message sent, full result:",
        JSON.stringify(result, null, 2),
      );
      console.log("🔍 aiMessage:", result.aiMessage);
      console.log("🔍 aiResponse:", result.aiResponse);

      // تحديث رسالة المستخدم
      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === tempUserMessage.id
            ? {
                ...result.userMessage,
                createdAt: new Date(result.userMessage.createdAt),
              }
            : msg,
        ),
      );

      // إضافة رد AI إذا كان موجوداً
      console.log(
        "🔍 Checking aiMessage:",
        result.aiMessage,
        "aiResponse:",
        result.aiResponse,
      );

      if (result.aiMessage && result.aiMessage.content) {
        // ✅ FIX: استخدام aiResponseInfo من aiMessage أولاً، ثم من aiResponse
        const aiMessageWithInfo: ExtendedTestMessage = {
          id: result.aiMessage.id,
          content: result.aiMessage.content,
          senderId: "ai",
          senderName: "AI",
          createdAt: new Date(result.aiMessage.createdAt),
          type: "text",
          isFromCustomer: false,
          status: "sent",
          conversationId: selectedConversation.id,
          isAiGenerated: true,
          aiResponseInfo:
            result.aiMessage.aiResponseInfo || result.aiResponse || null,
          // ✅ FIX: Map backend 'images' (string[]) to frontend 'attachments' structure
          attachments: result.aiMessage.images
            ? result.aiMessage.images.map((imgUrl: string) => ({
                type: "image",
                url: imgUrl,
                filename: "product-image.jpg",
              }))
            : undefined,
        };
        console.log("✅ [FRONTEND] Adding AI message:", aiMessageWithInfo);

        // ✅ FIX: استخدام functional update مع spread جديد لضمان re-render + منع التكرار
        setMessages((currentMessages) => {
          // Check for duplicates
          if (currentMessages.some((m) => m.id === aiMessageWithInfo.id)) {
            console.log(
              "⚠️ [FRONTEND] Duplicate message detected in sendMessage, skipping add:",
              aiMessageWithInfo.id,
            );
            return currentMessages;
          }
          const updatedMessages = [...currentMessages, aiMessageWithInfo];
          console.log("📝 New messages count:", updatedMessages.length);
          return updatedMessages;
        });

        // تحديث آخر رسالة في المحادثة
        setConversations((prev) =>
          prev.map((conv) =>
            conv.id === selectedConversation.id
              ? {
                  ...conv,
                  lastMessage: result.aiMessage?.content || messageContent,
                  lastMessageTime: new Date(),
                }
              : conv,
          ),
        );
      } else {
        // ✅ عرض معلومات النظام الصامت أو الخطأ (دائماً إذا لم يكن هناك aiMessage)
        const silentReason =
          result.aiResponse?.silentReason ||
          result.aiResponse?.error ||
          "لم يتم توليد رد من الذكاء الصناعي";
        const silentMessage: ExtendedTestMessage = {
          id: `silent_${Date.now()}`,
          content: `🤐 النظام صامت\n\n📋 السبب: ${silentReason}${result.aiResponse?.model ? `\n🤖 النموذج: ${result.aiResponse.model}` : ""}${result.aiResponse?.processingTime ? `\n⏱️ الوقت: ${result.aiResponse.processingTime}ms` : ""}`,
          senderId: "system",
          senderName: "النظام",
          createdAt: new Date(),
          type: "text",
          isFromCustomer: false,
          status: "sent",
          conversationId: selectedConversation.id,
          aiResponseInfo: result.aiResponse || null,
        };
        console.log("🤐 [FRONTEND] Adding silent message:", silentMessage);
        setMessages((prev) => {
          const newMessages = [...prev, silentMessage];
          console.log("📝 New messages count (silent):", newMessages.length);
          return newMessages;
        });
      }

      // ✅ NEW: تحديث الاقتراحات والبيانات المستخرجة
      if (result.suggestions) setSmartSuggestions(result.suggestions);
      if (result.extractedDetails)
        setLastExtractedDetails(result.extractedDetails);

      // ✅ FIX: إيقاف حالة الإرسال والكتابة هنا بدلاً من finally
      setTimeout(() => {
        setSending(false);
        setIsAiTyping(false);
      }, 100);

      // التمرير للأسفل بعد إضافة الرد
      setTimeout(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 150);
    } catch (error: any) {
      console.error("❌ Error sending message:", error);

      // تحديث حالة الرسالة إلى خطأ
