                    <button onClick={(e) => handleAddToCart(p, e)} className="w-full bg-white/90 backdrop-blur-md text-teal-700 py-3 rounded-xl font-bold text-xs uppercase tracking-widest shadow-lg border border-white hover:bg-teal-600 hover:text-white hover:border-teal-600 transition-colors">
                      Quick Add
                    </button>
                  </div>
                </div>

                <div className="px-2 flex-1 flex flex-col">
                  <span className="text-[10px] font-black text-teal-600/60 uppercase tracking-[0.2em] mb-2 block">{p.category?.name || 'Healthcare'}</span>
                  <h4 className="font-bold text-slate-800 text-lg mb-2 leading-tight group-hover:text-teal-600 transition-colors line-clamp-2" title={p.name}>
                    {p.name}
                  </h4>
                  <div className="flex items-center gap-3 mt-auto pt-4">
                    <span className="text-2xl font-black text-slate-900">${p.price}</span>
                    {p.comparePrice && p.comparePrice > p.price && (
                      <span className="text-sm font-bold text-slate-300 line-through decoration-slate-300">${p.comparePrice}</span>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {!products || products.length === 0 && (
              <div className="col-span-full flex flex-col items-center justify-center py-20 text-center">
                <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center text-slate-300 mb-6 font-black text-3xl">!</div>
                <p className="text-slate-500 font-medium">No medical stock currently available in this category.</p>
              </div>
            )}
          </div>
        )}
      </section>

      {/* Advanced Cart Slide-over */}
      {isOpen && (
        <div className="fixed inset-0 z-[200] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-sm transition-opacity" onClick={() => setIsOpen(false)}></div>
          <div className="relative w-full max-w-md bg-white/95 backdrop-blur-2xl h-full shadow-[0_0_60px_rgba(0,0,0,0.1)] p-8 flex flex-col animate-in slide-in-from-right duration-500 border-l border-white">
            <div className="flex items-center justify-between mb-10 pb-6 border-b border-slate-100">
              <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">Your Cart</h3>
                <p className="text-xs font-bold text-teal-600 uppercase tracking-widest mt-1">Ready for fulfillment</p>
              </div>
              <button onClick={() => setIsOpen(false)} className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            
            <div className="flex-1 overflow-y-auto space-y-4 pr-2 custom-scrollbar">
              {cartStoreItems.map(item => (
                <div key={item.id} className="flex gap-4 p-4 bg-white rounded-2xl border border-slate-100 shadow-sm group hover:border-teal-200 transition-colors">
                  <div className="w-20 h-20 bg-slate-50 rounded-xl flex items-center justify-center p-2">
                    <img src={item.imageUrl} className="max-w-full max-h-full object-contain mix-blend-multiply" alt={item.name} />
                  </div>
                  <div className="flex-1 flex flex-col justify-center">
                    <h5 className="font-bold text-sm text-slate-800 line-clamp-2 leading-tight mb-1">{item.name}</h5>
                    <p className="text-xs font-medium text-slate-400 mb-2">Quantity: {item.quantity}</p>
                    <div className="flex items-center justify-between mt-auto">
                      <span className="font-black text-teal-600">${(item.price * item.quantity).toFixed(2)}</span>
                      <button onClick={() => removeItem(item.id)} className="text-[10px] uppercase font-bold tracking-widest text-red-400 hover:text-red-600">Remove</button>
                    </div>
                  </div>
                </div>
              ))}
              {cartStoreItems.length === 0 && (
                <div className="flex flex-col items-center justify-center h-full opacity-50 space-y-4">
                  <svg className="w-16 h-16 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>
                  <p className="text-sm font-bold tracking-widest uppercase">Cart is empty</p>
                </div>
              )}
            </div>

            {cartStoreItems.length > 0 && (
              <div className="pt-8 mt-auto border-t border-slate-100">
                <div className="flex justify-between items-end mb-6">
                  <span className="text-sm font-bold text-slate-400 uppercase tracking-widest">Total Amount</span>
                  <span className="text-3xl font-black text-slate-900">
                    ${cartStoreItems.reduce((acc, item) => acc + (item.price * item.quantity), 0).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                  </span>
                </div>
                <button onClick={handleCheckout} className="w-full bg-slate-900 text-white hover:bg-teal-600 py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-slate-900/20 hover:shadow-teal-600/30 transition-all duration-300 flex justify-center items-center gap-3">
                  Proceed to Checkout <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg>
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Global generic animations string for Tailwind JIT */}
      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-20px); }
        }
        .animate-float {
          animation: float 6s ease-in-out infinite;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  TicketIcon,
  PaperAirplaneIcon,
  ArrowLeftIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import { apiClient } from "../../services/apiClient";

const TurboTickets: React.FC = () => {
  const navigate = useNavigate();
  const [ticketDescription, setTicketDescription] = useState("");
  const [ticketType, setTicketType] = useState(1); // Default to inquiry type
  const [inquiryTypeId, setInquiryTypeId] = useState<number | null>(null);
  const [sendingTicket, setSendingTicket] = useState(false);
  const [inquiriesTypes, setInquiriesTypes] = useState<
    Array<{ id: number; name: string; nameEn?: string }>
  >([]);
  const [loadingTypes, setLoadingTypes] = useState(false);
  const [tickets, setTickets] = useState<any[]>([]);
  const [loadingTickets, setLoadingTickets] = useState(false);
  const [ticketsPage, setTicketsPage] = useState(1);
  const [ticketsPerPage] = useState(10);
  const [ticketsTotal, setTicketsTotal] = useState(0);
  const [unreadCount, setUnreadCount] = useState({
    tickets: 0,
    missions: 0,
    orders: 0,
  });
  const [turboEnabled, setTurboEnabled] = useState(false);

  useEffect(() => {
    const initializeTurbo = async () => {
      const enabled = await checkTurboEnabled();
      if (enabled) {
        loadUnreadCount();
      }
    };

    initializeTurbo();
  }, []);

  useEffect(() => {
    if (turboEnabled) {
      loadTickets();
    }
  }, [ticketsPage, turboEnabled]);

  useEffect(() => {
    if (turboEnabled && ticketType === 1 && inquiriesTypes.length === 0) {
      loadInquiriesTypes();
    }
  }, [turboEnabled, ticketType]);

  const checkTurboEnabled = async () => {
    try {
      const response = await apiClient.get("/store-settings/turbo");
      if (response.data.success) {
        const enabled = response.data.data.turboEnabled || false;
        setTurboEnabled(enabled);
        return enabled;
      }
    } catch (error) {
      console.error("Error checking Turbo status:", error);
    }

    setTurboEnabled(false);
    return false;
  };

  const loadInquiriesTypes = async () => {
    try {
      setLoadingTypes(true);
      const response = await apiClient.get("/turbo/inquiries-types");
      if (response.data.success && response.data.data?.types) {
        const typesData = response.data.data.types;
        const typesArray = Array.isArray(typesData) ? typesData : [];
        setInquiriesTypes(typesArray);
        // Set default inquiry_type_id to first type if available
        if (typesArray.length > 0) {
          setInquiryTypeId(typesArray[0].id || typesArray[0].type || null);
        }
      } else {
        // Fallback to default types
        const defaultTypes = [
          { id: 1, name: "شكوى" },
          { id: 2, name: "استفسار" },
          { id: 3, name: "شكر" },
        ];
        setInquiriesTypes(defaultTypes);
        setInquiryTypeId(defaultTypes[0].id || null);
      }
    } catch (error: any) {
      console.error("Error loading inquiries types:", error);
      // Fallback to default types
      const defaultTypes = [
        { id: 1, name: "شكوى" },
        { id: 2, name: "استفسار" },
        { id: 3, name: "شكر" },
      ];
      setInquiriesTypes(defaultTypes);
      setInquiryTypeId(defaultTypes[0].id || null);
    } finally {
      setLoadingTypes(false);
    }
  };

  const loadTickets = async () => {
    if (!turboEnabled) return;

    try {
      setLoadingTickets(true);
      const response = await apiClient.get(
        `/turbo/tickets?page=${ticketsPage}&per_page=${ticketsPerPage}`,
      );

      if (response.data.success) {
        const ticketsData = response.data.data?.tickets || [];
        const paginationData = response.data.data?.pagination || {};

        setTickets(Array.isArray(ticketsData) ? ticketsData : []);
        setTicketsTotal(paginationData.total || 0);
      } else {
        setTickets([]);
        setTicketsTotal(0);
      }
    } catch (error: any) {
      console.error("Error loading tickets:", error);
      toast.error("فشل تحميل التذاكر");
      setTickets([]);
      setTicketsTotal(0);
    } finally {
      setLoadingTickets(false);
    }
  };

  const loadUnreadCount = async () => {
    if (!turboEnabled) return;

    try {
      const response = await apiClient.get("/turbo/tickets/unread-count");
      if (response.data.success) {
        setUnreadCount(
          response.data.data.counts || { tickets: 0, missions: 0, orders: 0 },
        );
      }
    } catch (error: any) {
      console.error("Error loading unread count:", error);
    }
  };

  const handleViewTicket = (ticketId: number) => {
    navigate(`/settings/turbo/ticket/${ticketId}`);
  };

  const handleSendTicket = async () => {
    if (!ticketDescription.trim()) {
      toast.error("يرجى إدخال وصف التذكرة");
      return;
    }

    if (ticketType === 1 && !inquiryTypeId) {
      toast.error("يرجى اختيار نوع الاستفسار");
      return;
    }

    const requestData: any = {
      description: ticketDescription.trim(),
      type: ticketType,
    };

    if (ticketType === 1 && inquiryTypeId) {
      requestData.inquiryTypeId = inquiryTypeId;
    }

    try {
      setSendingTicket(true);

      const response = await apiClient.post("/turbo/tickets", requestData);

      if (response.data.success) {
        toast.success("تم إرسال التذكرة بنجاح");
        setTicketDescription("");
        setTicketType(1);
        setInquiryTypeId(null);
        loadTickets();
        loadUnreadCount();
      } else {
        toast.error(response.data.message || "فشل إرسال التذكرة");
      }
    } catch (error: any) {
      console.error("Error sending ticket:", error);
      const errorMessage =
        error.response?.data?.error ||
        error.response?.data?.message ||
        "فشل إرسال التذكرة";
      console.error("Ticket request data:", requestData);
      console.error("Error response:", error.response?.data);
      toast.error(errorMessage);
    } finally {
      setSendingTicket(false);
    }
  };

  return (
    <div
      className="w-full px-4 sm:px-6 lg:px-8 py-8 dark:bg-gray-900 min-h-screen"
      dir="rtl"
    >
      {/* Header */}
      <div className="mb-8">
        <button
          onClick={() => navigate("/orders")}
          className="flex items-center text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200 mb-4"
        >
          <ArrowLeftIcon className="h-5 w-5 ml-2" />
          العودة للطلبات
        </button>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center">
          <TicketIcon className="h-8 w-8 text-indigo-600 dark:text-indigo-400 ml-3" />
          تذاكر Turbo
        </h1>
        <p className="mt-2 text-gray-600 dark:text-gray-400">
          إدارة تذاكر Turbo للشحن - إرسال ومتابعة التذاكر
        </p>
      </div>

      {/* Send Ticket Section */}
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mb-6 border border-gray-200 dark:border-gray-700">
        <div className="flex items-center mb-4">
          <TicketIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2" />
          <h3 className="text-lg font-medium text-gray-900 dark:text-white">
            إرسال تذكرة جديدة
          </h3>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              نوع التذكرة
            </label>
            <select
              value={ticketType}
              onChange={(e) => {
                setTicketType(parseInt(e.target.value));
                if (parseInt(e.target.value) !== 1) {
                  setInquiryTypeId(null);
                }
              }}
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400"
            >
              <option value={1}>استفسار (Inquiry)</option>
              <option value={2}>شكوى (Complain)</option>
              <option value={3}>شكر (Gratitude)</option>
              <option value={4}>اقتراح (Suggestion)</option>
            </select>
          </div>

          {ticketType === 1 && (
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                نوع الاستفسار{" "}
                <span className="text-red-500 dark:text-red-400">*</span>
              </label>
              {loadingTypes ? (
                <div className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-gray-50 dark:bg-gray-700 text-gray-500 dark:text-gray-400 text-sm">
                  جاري تحميل الأنواع...
                </div>
              ) : (
                <select
                  value={inquiryTypeId || ""}
                  onChange={(e) => setInquiryTypeId(parseInt(e.target.value))}
                  disabled={
                    !Array.isArray(inquiriesTypes) ||
                    inquiriesTypes.length === 0
                  }
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400 disabled:bg-gray-100 dark:disabled:bg-gray-800 disabled:cursor-not-allowed"
                >
                  <option value="">اختر نوع الاستفسار</option>
                  {Array.isArray(inquiriesTypes) &&
                  inquiriesTypes.length > 0 ? (
                    inquiriesTypes.map((type) => (
                      <option
                        key={type.id || type.type}
                        value={type.id || type.type}
                      >
                        {type.name ||
                          type.nameEn ||
                          `نوع ${type.id || type.type}`}
                      </option>
                    ))
                  ) : (
                    <>
                      <option value={1}>نوع 1</option>
                      <option value={2}>نوع 2</option>
                      <option value={3}>نوع 3</option>
                    </>
                  )}
                </select>
              )}
            </div>
          )}

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              وصف التذكرة
            </label>
            <textarea
              value={ticketDescription}
              onChange={(e) => setTicketDescription(e.target.value)}
              rows={5}
              placeholder="اكتب وصف التذكرة هنا..."
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-lg focus:ring-2 focus:ring-indigo-500 dark:focus:ring-indigo-400 focus:border-indigo-500 dark:focus:border-indigo-400 resize-none"
            />
            <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
              {ticketDescription.length} حرف
            </p>
          </div>

          <button
            onClick={handleSendTicket}
            disabled={
              sendingTicket || !ticketDescription.trim() || !turboEnabled
            }
            className="inline-flex items-center px-4 py-2 bg-indigo-600 dark:bg-indigo-500 text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed text-sm"
          >
            <PaperAirplaneIcon className="h-4 w-4 ml-1" />
            {sendingTicket ? "جاري الإرسال..." : "إرسال التذكرة"}
          </button>

          {!turboEnabled && (
            <p className="text-xs text-red-500 dark:text-red-400">
              يجب تفعيل Turbo أولاً لإرسال التذاكر. يرجى الذهاب إلى{" "}
              <button
                onClick={() => navigate("/settings/turbo")}
                className="underline hover:text-red-700 dark:hover:text-red-300"
              >
                إعدادات Turbo
              </button>
            </p>
          )}
        </div>
      </div>

      {/* Tickets List Section */}
      <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 border border-gray-200 dark:border-gray-700">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center">
            <TicketIcon className="h-5 w-5 text-indigo-600 dark:text-indigo-400 ml-2" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              قائمة التذاكر
            </h3>
            {unreadCount.tickets > 0 && (
              <span className="mr-2 px-2 py-1 bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300 text-xs font-medium rounded-full">
                {unreadCount.tickets} غير مقروء
              </span>
            )}
          </div>
          <button
            onClick={loadTickets}
            disabled={loadingTickets}
            className="text-sm text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300"
          >
            {loadingTickets ? "جاري التحديث..." : "تحديث"}
          </button>
        </div>

        {!turboEnabled ? (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            يجب تفعيل Turbo أولاً لعرض التذاكر. يرجى الذهاب إلى{" "}
            <button
              onClick={() => navigate("/settings/turbo")}
              className="text-indigo-600 dark:text-indigo-400 underline hover:text-indigo-800 dark:hover:text-indigo-300"
            >
              إعدادات Turbo
            </button>
          </div>
        ) : loadingTickets ? (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            جاري تحميل التذاكر...
          </div>
        ) : tickets.length === 0 ? (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            لا توجد تذاكر
          </div>
        ) : (
          <div className="space-y-3">
            {Array.isArray(tickets) &&
              tickets.map((ticket: any) => (
                <div
                  key={ticket.id}
                  className="border border-gray-200 dark:border-gray-700 rounded-lg p-4 hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer transition-colors"
                  onClick={() => handleViewTicket(ticket.id)}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="font-medium text-gray-900 dark:text-white">
                          #{ticket.id}
                        </span>
                        <span
                          className={`px-2 py-1 text-xs rounded-full ${
                            ticket.status === 0
                              ? "bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300"
                              : ticket.status === 1
                                ? "bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-300"
                                : "bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300"
                          }`}
                        >
                          {ticket.status === 0
                            ? "جديد"
                            : ticket.status === 1
                              ? "قيد المعالجة"
                              : "مغلق"}
                        </span>
                      </div>
                      <p className="text-sm text-gray-600 dark:text-gray-300 line-clamp-2">
                        {ticket.description || "لا يوجد وصف"}
                      </p>
                      <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">
                        {new Date(
                          ticket.created_at || ticket.createdAt,
                        ).toLocaleDateString("ar-EG")}
                      </p>
                    </div>
                  </div>
                </div>
              ))}

            {/* Pagination */}
            {ticketsTotal > ticketsPerPage && (
              <div className="flex justify-center items-center gap-2 pt-4">
                <button
                  onClick={() => setTicketsPage((p) => Math.max(1, p - 1))}
                  disabled={ticketsPage === 1 || loadingTickets}
                  className="px-3 py-1 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded text-sm disabled:opacity-50"
                >
                  السابق
                </button>
                <span className="text-sm text-gray-600 dark:text-gray-400">
                  صفحة {ticketsPage} من{" "}
                  {Math.ceil(ticketsTotal / ticketsPerPage)}
                </span>
                <button
                  onClick={() => setTicketsPage((p) => p + 1)}
                  disabled={
                    ticketsPage >= Math.ceil(ticketsTotal / ticketsPerPage) ||
                    loadingTickets
                  }
                  className="px-3 py-1 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded text-sm disabled:opacity-50"
                >
                  التالي
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default TurboTickets;

import React, { useState, useEffect, useRef, useCallback } from "react";
import {
  MagnifyingGlassIcon,
  PaperAirplaneIcon,
  ChatBubbleLeftRightIcon,
  UserCircleIcon,
  XMarkIcon,
  ArrowPathIcon,
  EllipsisVerticalIcon,
  PaperClipIcon,
  FaceSmileIcon,
  ClockIcon,
  PhoneIcon,
  EnvelopeIcon,
  SparklesIcon,
  BoltIcon,
} from "@heroicons/react/24/outline";
import { StarIcon as StarSolidIcon } from "@heroicons/react/24/solid";
import { apiClient } from "../../services/apiClient";
import { socketService } from "../../services/socketService";
import { useTranslation } from "react-i18next";

// ═══════════════════════════════════════════════════════════════════════════════
// 📋 Types
// ═══════════════════════════════════════════════════════════════════════════════

interface UnifiedConversation {
  id: string;
  platform: "facebook" | "whatsapp" | "telegram";
  platformIcon: string;
  contactName: string;
  contactAvatar: string | null;
  contactId: string;
  contactEmail: string | null;
  contactPhone: string | null;
  lastMessage: string;
  lastMessageType: string;
  lastMessageTime: string;
  lastMessageIsFromCustomer: boolean;
  unreadCount: number;
  status: string;
  assignedTo: { id: string; name: string; avatar: string | null } | null;
  isPinned: boolean;
  isMuted: boolean;
  tags: string[];
  metadata: Record<string, any>;
}

interface UnifiedMessage {
  id: string;
  platform: string;
  messageId?: string;
  content: string;
  type: string;
  isFromCustomer: boolean;
  timestamp: string;
  status: string;
  mediaUrl: string | null;
  mediaType: string | null;
  mediaFileName: string | null;
  quotedMessage: { id: string; content: string } | null;
  isAIResponse: boolean;
  sender: string;
  senderAvatar?: string | null;
  interactiveData: any;
}

interface CustomerProfile {
  id: string;
  name: string;
  firstName: string;
  lastName: string;
  email: string | null;
  phone: string | null;
  avatar: string | null;
  status: string;
  createdAt: string;
  totalOrders: number;
  totalConversations: number;
  recentOrders: any[];
  recentConversations: any[];
  tags: string[];
  notes: string;
}

interface PlatformCounts {
  all: number;
  facebook: number;
  whatsapp: number;
  telegram: number;
  unreplied: number;
}

// ═══════════════════════════════════════════════════════════════════════════════
// 🎨 Platform styling
// ═══════════════════════════════════════════════════════════════════════════════

const platformStyles: Record<string, { label: string; icon: string }> = {
  facebook: { label: "Messenger", icon: "💬" },
  whatsapp: { label: "WhatsApp", icon: "📱" },
  telegram: { label: "Telegram", icon: "✈️" },
};

// ═══════════════════════════════════════════════════════════════════════════════
// 🏗️ Main Component
// ═══════════════════════════════════════════════════════════════════════════════

const UnifiedInbox: React.FC = () => {
  const { t, i18n } = useTranslation();
  const isRtl = i18n.dir() === "rtl";

  // State
  const [conversations, setConversations] = useState<UnifiedConversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<UnifiedConversation | null>(null);
  const [messages, setMessages] = useState<UnifiedMessage[]>([]);
  const [customerProfile, setCustomerProfile] =
    useState<CustomerProfile | null>(null);
  const [counts, setCounts] = useState<PlatformCounts>({
    all: 0,
    facebook: 0,
    whatsapp: 0,
    telegram: 0,
    unreplied: 0,
  });

  const [loading, setLoading] = useState(true);
  const [loadingMessages, setLoadingMessages] = useState(false);
  const [loadingProfile, setLoadingProfile] = useState(false);
  const [sending, setSending] = useState(false);

  const [searchQuery, setSearchQuery] = useState("");
  const [platformFilter, setPlatformFilter] = useState<string>("all");
  const [statusFilter] = useState<string>("");
  const [newMessage, setNewMessage] = useState("");
  const [showProfilePanel, setShowProfilePanel] = useState(true);
  const [showQuickReplies, setShowQuickReplies] = useState(false);
  const [quickReplies, setQuickReplies] = useState<any[]>([]);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // ──────────────────────────────────────────────────────────
  // 📡 Data Fetching
  // ──────────────────────────────────────────────────────────

  const loadConversations = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      params.set("platform", platformFilter);
      if (searchQuery) params.set("search", searchQuery);
      if (statusFilter) params.set("status", statusFilter);
      params.set("limit", "50");

      const response = await apiClient.get(
        `/api/v1/unified-inbox/conversations?${params.toString()}`,
      );

      if (response.data?.success) {
        setConversations(response.data.data || []);
        if (response.data.counts) {
          setCounts(response.data.counts);
        }
      }
    } catch (error) {
      console.error("❌ Error loading conversations:", error);
    } finally {
      setLoading(false);
    }
  }, [platformFilter, searchQuery, statusFilter]);

  const loadMessages = useCallback(async (conv: UnifiedConversation) => {
    try {
      setLoadingMessages(true);
      const params = new URLSearchParams();
      params.set("platform", conv.platform);
      if (conv.metadata?.["sessionId"])
        params.set("sessionId", conv.metadata["sessionId"]);
      if (conv.metadata?.["jid"]) params.set("jid", conv.metadata["jid"]);

      const realId = conv.id.startsWith("wa_") ? conv.id : conv.id;
      const response = await apiClient.get(
        `/api/v1/unified-inbox/conversations/${realId}/messages?${params.toString()}`,
      );

      if (response.data?.success) {
        setMessages(response.data.data || []);
        setTimeout(() => scrollToBottom(), 100);
      }
    } catch (error) {
      console.error("❌ Error loading messages:", error);
    } finally {
      setLoadingMessages(false);
    }
  }, []);

  const loadCustomerProfile = useCallback(async (customerId: string) => {
    try {
      setLoadingProfile(true);
      const response = await apiClient.get(
        `/api/v1/unified-inbox/customer/${customerId}`,
      );
      if (response.data?.success) {
        setCustomerProfile(response.data.data);
      }
    } catch (error) {
      console.error("❌ Error loading customer:", error);
      setCustomerProfile(null);
    } finally {
      setLoadingProfile(false);
    }
  }, []);

  const loadQuickReplies = useCallback(async () => {
    try {
      const response = await apiClient.get(
        "/api/v1/unified-inbox/quick-replies",
      );
      if (response.data?.success) {
        setQuickReplies(response.data.data || []);
      }
    } catch (error) {
      console.error("Error loading quick replies:", error);
    }
  }, []);

  // ──────────────────────────────────────────────────────────
  // 🎯 Actions
  // ──────────────────────────────────────────────────────────

  const selectConversation = useCallback(
    (conv: UnifiedConversation) => {
      setSelectedConversation(conv);
      loadMessages(conv);
      if (conv.contactId && !conv.id.startsWith("wa_")) {
        loadCustomerProfile(conv.contactId);
      } else {
        setCustomerProfile(null);
      }
    },
    [loadMessages, loadCustomerProfile],
  );

  const handleSendMessage = async () => {
    if (!selectedConversation || !newMessage.trim()) return;

    setSending(true);
    try {
      const body: any = {
        content: newMessage.trim(),
        platform: selectedConversation.platform,
      };

      if (selectedConversation.metadata?.["sessionId"]) {
        body.sessionId = selectedConversation.metadata["sessionId"];
      }
      if (selectedConversation.metadata?.["jid"]) {
        body.jid = selectedConversation.metadata["jid"];
      }

      const realId = selectedConversation.id;
      const response = await apiClient.post(
        `/api/v1/unified-inbox/conversations/${realId}/messages`,
        body,
      );

      if (response.data?.success) {
        setMessages((prev) => [...prev, response.data.data]);
        setNewMessage("");
        setTimeout(() => scrollToBottom(), 100);

        // Update conversation preview
        setConversations((prev) =>
          prev.map((c) =>
            c.id === selectedConversation.id
              ? {
                  ...c,
                  lastMessage: newMessage.trim(),
                  lastMessageTime: new Date().toISOString(),
                  lastMessageIsFromCustomer: false,
                }
              : c,
          ),
        );
      }
    } catch (error) {
      console.error("❌ Error sending message:", error);
    } finally {
      setSending(false);
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const handleSearchChange = (value: string) => {
    setSearchQuery(value);
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
    searchTimeoutRef.current = setTimeout(() => {
      loadConversations();
    }, 400);
  };

  const useQuickReply = (reply: any) => {
    setNewMessage(reply.content);
    setShowQuickReplies(false);
  };

  // ──────────────────────────────────────────────────────────
  // 🔄 Effects
  // ──────────────────────────────────────────────────────────

  useEffect(() => {
    loadConversations();
    loadQuickReplies();
  }, [platformFilter, statusFilter]);

  useEffect(() => {
    // Real-time updates
    socketService.connect();

    socketService.onMessage?.((message: any) => {
      if (
        selectedConversation &&
        message.conversationId === selectedConversation.id
      ) {
        setMessages((prev) => [...prev, message]);
        scrollToBottom();
      }
      // Update conversation list
      setConversations((prev) =>
        prev.map((c) =>
          c.id === message.conversationId
            ? {
                ...c,
                lastMessage: message.content,
                lastMessageTime: new Date().toISOString(),
                unreadCount: c.unreadCount + 1,
              }
            : c,
        ),
      );
    });

    return () => {
      // Cleanup if needed
    };
  }, [selectedConversation]);

  // ──────────────────────────────────────────────────────────
  // 🎨 Helpers
  // ──────────────────────────────────────────────────────────

  const formatTime = (dateStr: string) => {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));

    const locale = i18n.language === "ar" ? "ar-EG" : "en-US";

    if (days === 0) {
      return date.toLocaleTimeString(locale, {
        hour: "2-digit",
        minute: "2-digit",
      });
    }
    if (days === 1) return t("unifiedInbox.yesterday");
    if (days < 7) return date.toLocaleDateString(locale, { weekday: "short" });
    return date.toLocaleDateString(locale, { month: "short", day: "numeric" });
  };

  const getPlatformBadge = (platform: string) => {
    const style =
      (platformStyles as any)[platform] || platformStyles["facebook"];
    return (
      <span className="business-platform-indicator" data-platform={platform}>
        <span className={isRtl ? "ml-1" : "mr-1"}>{style.icon}</span>
        {style.label}
      </span>
    );
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // 🖼️ RENDER
  // ═══════════════════════════════════════════════════════════════════════════

  return (
    <div className="business-inbox-shell" dir={isRtl ? "rtl" : "ltr"}>
      <div className="business-inbox-stage">
        {/* ═══════════════════════════════════════════════════════════════════ */}
        {/* COLUMN 1 — Conversation List */}
        {/* ═══════════════════════════════════════════════════════════════════ */}
        <div className="business-inbox-column business-inbox-column--list">
          {/* Header */}
          <div className="business-inbox-header">
            <div className="business-inbox-header-row mb-3">
              <h1 className="business-inbox-title">
                <ChatBubbleLeftRightIcon className="w-6 h-6" />
                {t("unifiedInbox.title")}
              </h1>
              <button
                onClick={() => loadConversations()}
                className="business-chip-button"
                title={t("unifiedInbox.refresh")}
              >
                <ArrowPathIcon
                  className={`w-5 h-5 ${loading ? "animate-spin" : ""}`}
                />
              </button>
            </div>

            {/* Search */}
            <div className="business-inbox-search-wrap mb-3">
              <MagnifyingGlassIcon
                className={`business-inbox-search-icon ${isRtl ? "right-0 left-auto" : ""}`}
              />
              <input
                type="text"
                placeholder={t("unifiedInbox.searchPlaceholder")}
                value={searchQuery}
                onChange={(e) => handleSearchChange(e.target.value)}
                className={`business-inbox-search ${isRtl ? "pr-10 pl-4" : "pl-10 pr-4 text-left"}`}
              />
            </div>

            {/* Platform Filter Tabs */}
            <div className="business-inbox-tabs">
              {[
                {
                  key: "all",
                  label: t("unifiedInbox.tabs.all"),
                  count: counts.all,
                },
                { key: "facebook", label: "💬", count: counts.facebook },
                { key: "whatsapp", label: "📱", count: counts.whatsapp },
                { key: "telegram", label: "✈️", count: counts.telegram },
              ].map((tab) => (
                <button
                  key={tab.key}
                  onClick={() => setPlatformFilter(tab.key)}
                  className="business-inbox-tab"
                  data-active={platformFilter === tab.key ? "true" : "false"}
                >
                  {tab.label}
                  {tab.count > 0 && (
                    <span className="business-inbox-tab-count">
                      {tab.count}
                    </span>
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Conversation List */}
          <div className="flex-1 overflow-y-auto">
            {loading ? (
              <div className="business-inbox-empty h-40">
                <div className="flex flex-col items-center gap-3">
                  <div
                    className="animate-spin rounded-full h-8 w-8 border-2 border-t-transparent"
                    style={{
                      borderColor:
                        "color-mix(in srgb, var(--color-primary) 24%, transparent)",
                      borderTopColor: "transparent",
                    }}
                  />
                  <span className="text-sm">{t("unifiedInbox.loading")}</span>
                </div>
              </div>
            ) : conversations.length === 0 ? (
              <div className="business-inbox-empty h-40">
                <ChatBubbleLeftRightIcon
                  className="w-12 h-12"
                  style={{
                    color:
                      "color-mix(in srgb, var(--color-primary) 24%, var(--color-muted-foreground))",
                  }}
                />
                <p className="text-sm">{t("unifiedInbox.noConversations")}</p>
              </div>
            ) : (
              conversations.map((conv) => (
                <div
                  key={conv.id}
                  onClick={() => selectConversation(conv)}
                  className="business-conversation-card"
                  data-state={
                    selectedConversation?.id === conv.id
                      ? "selected"
                      : conv.unreadCount > 0
                        ? "attention"
                        : "idle"
                  }
                >
                  <div className="flex items-start gap-3">
                    {/* Avatar */}
                    <div className="relative flex-shrink-0">
                      {conv.contactAvatar ? (
                        <img
                          src={conv.contactAvatar}
                          alt={conv.contactName}
                          className="business-conversation-avatar"
                        />
                      ) : (
                        <div className="business-conversation-fallback">
                          {conv.contactName?.charAt(0) || "?"}
                        </div>
                      )}
                      {/* Platform indicator */}
                      <span
                        className={`absolute -bottom-0.5 text-xs ${isRtl ? "-left-0.5" : "-right-0.5"}`}
                      >
                        {platformStyles[conv.platform]?.icon || "💬"}
                      </span>
                    </div>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between mb-0.5">
                        <h3
                          className={`font-semibold text-sm truncate ${isRtl ? "" : "text-left"}`}
                          style={{ color: "var(--color-foreground)" }}
                        >
                          {conv.contactName || t("unifiedInbox.unknown")}
                        </h3>
                        <span
                          className={`text-[11px] flex-shrink-0 ${isRtl ? "mr-2" : "ml-2"}`}
                          style={{ color: "var(--color-muted-foreground)" }}
                        >
                          {formatTime(conv.lastMessageTime)}
                        </span>
                      </div>

                      <p
                        className={`text-xs truncate leading-5 ${isRtl ? "" : "text-left"}`}
                        style={{ color: "var(--color-muted-foreground)" }}
                      >
                        {conv.lastMessageIsFromCustomer
                          ? ""
                          : t("unifiedInbox.you")}
                        {conv.lastMessage || t("unifiedInbox.noMessages")}
                      </p>

                      <div className="flex items-center justify-between mt-1">
                        {getPlatformBadge(conv.platform)}
                        <div className="flex items-center gap-1.5">
                          {conv.isPinned && (
                            <StarSolidIcon
                              className="w-3.5 h-3.5"
                              style={{ color: "var(--business-warning)" }}
                            />
                          )}
                          {conv.unreadCount > 0 && (
                            <span
                              className="text-[10px] font-bold rounded-full min-w-[18px] h-[18px] flex items-center justify-center px-1 text-white"
                              style={{ background: "var(--business-danger)" }}
                            >
                              {conv.unreadCount > 99 ? "99+" : conv.unreadCount}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* ═══════════════════════════════════════════════════════════════════ */}
        {/* COLUMN 2 — Chat Area */}
        {/* ═══════════════════════════════════════════════════════════════════ */}
        <div className="business-inbox-column flex-1">
          {selectedConversation ? (
            <>
              {/* Chat Header */}
              <div className="business-inbox-header">
                <div className="business-inbox-header-row">
                  <div className="flex items-center gap-3">
                    <div className="relative">
                      {selectedConversation.contactAvatar ? (
                        <img
                          src={selectedConversation.contactAvatar}
                          alt=""
                          className="business-conversation-avatar !w-10 !h-10"
                        />
                      ) : (
                        <div className="business-conversation-fallback !w-10 !h-10">
                          {selectedConversation.contactName?.charAt(0) || "?"}
                        </div>
                      )}
                    </div>
                    <div>
                      <h3
                        className="font-semibold text-sm"
                        style={{ color: "var(--color-foreground)" }}
                      >
                        {selectedConversation.contactName}
                      </h3>
                      <div className="flex items-center gap-2">
                        {getPlatformBadge(selectedConversation.platform)}
                        <span
                          className="text-xs"
                          style={{ color: "var(--color-muted-foreground)" }}
                        >
                          {selectedConversation.status === "active"
                            ? t("unifiedInbox.status.active")
                            : selectedConversation.status}
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => setShowProfilePanel(!showProfilePanel)}
                      className="business-chip-button"
                      data-active={showProfilePanel ? "true" : "false"}
                      title={t("unifiedInbox.profile")}
                    >
                      <UserCircleIcon className="w-5 h-5" />
                    </button>
                    <button className="business-chip-button">
                      <EllipsisVerticalIcon className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>

              {/* Messages Area */}
              <div
                ref={messagesContainerRef}
                className="business-chat-stage flex-1 overflow-y-auto p-5"
                style={{
                  backgroundImage:
                    "radial-gradient(circle at 25px 25px, color-mix(in srgb, var(--color-primary) 4%, transparent) 2%, transparent 0%)",
                  backgroundSize: "50px 50px",
                }}
              >
                {loadingMessages ? (
                  <div className="business-inbox-empty h-full">
                    <div
                      className="animate-spin rounded-full h-8 w-8 border-2 border-t-transparent"
                      style={{
                        borderColor:
                          "color-mix(in srgb, var(--color-primary) 24%, transparent)",
                        borderTopColor: "transparent",
                      }}
                    />
                  </div>
                ) : messages.length === 0 ? (
                  <div className="business-inbox-empty h-full">
                    <ChatBubbleLeftRightIcon
                      className="w-16 h-16 mb-3"
                      style={{
                        color:
                          "color-mix(in srgb, var(--color-primary) 18%, var(--color-muted-foreground))",
                      }}
                    />
                    <p className="text-sm">{t("unifiedInbox.noMessagesYet")}</p>
                  </div>
                ) : (
                  <div className="space-y-3 max-w-3xl mx-auto">
                    {messages.map((msg, index) => {
                      const showTimeSeparator =
                        index === 0 ||
                        (() => {
                          const prevMsg = messages[index - 1];
                          if (!prevMsg) return false;
                          const prev = new Date(prevMsg.timestamp);
                          const curr = new Date(msg.timestamp);
                          return (
                            curr.getTime() - prev.getTime() > 30 * 60 * 1000
                          );
                        })();

                      return (
                        <React.Fragment key={msg.id}>
                          {showTimeSeparator && (
                            <div className="flex items-center justify-center my-4">
                              <div
                                className="text-[11px] px-3 py-1 rounded-full"
                                style={{
                                  background:
                                    "color-mix(in srgb, var(--color-border) 40%, white)",
                                  color: "var(--color-muted-foreground)",
                                }}
                              >
                                {new Date(msg.timestamp).toLocaleDateString(
                                  i18n.language === "ar" ? "ar-EG" : "en-US",
                                  {
                                    weekday: "short",
                                    hour: "2-digit",
                                    minute: "2-digit",
                                  },
                                )}
                              </div>
                            </div>
                          )}

                          <div
                            className={`flex ${msg.isFromCustomer ? "justify-start" : "justify-end"}`}
                          >
                            <div
                              className="max-w-[75%] rounded-2xl px-4 py-2.5 shadow-sm"
                              style={
                                msg.isFromCustomer
                                  ? {
                                      background:
                                        "linear-gradient(180deg, color-mix(in srgb, white 90%, var(--color-background) 10%) 0%, color-mix(in srgb, white 78%, var(--color-background) 22%) 100%)",
                                      border:
                                        "1px solid var(--business-card-border)",
                                      borderTopRightRadius: "0.5rem",
                                    }
                                  : {
                                      background:
                                        "linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%)",
                                      color: "white",
                                      borderTopLeftRadius: "0.5rem",
                                    }
                              }
                            >
                              {/* AI Badge */}
                              {msg.isAIResponse && (
                                <div className="flex items-center gap-1 mb-1.5">
                                  <SparklesIcon
                                    className="w-3.5 h-3.5"
                                    style={{
                                      color: "rgba(255, 220, 136, 0.95)",
                                    }}
                                  />
                                  <span
                                    className="text-[10px] font-medium"
                                    style={{
                                      color: "rgba(255, 236, 182, 0.9)",
                                    }}
                                  >
                                    {t("unifiedInbox.aiResponse")}
                                  </span>
                                </div>
                              )}

                              {/* Quoted message */}
                              {msg.quotedMessage && (
                                <div
                                  className="border-r-2 pr-2 mb-1.5 text-xs opacity-70"
                                  style={{
                                    borderColor: msg.isFromCustomer
                                      ? "color-mix(in srgb, var(--color-muted-foreground) 40%, transparent)"
                                      : "rgba(232, 243, 255, 0.45)",
                                  }}
                                >
                                  {msg.quotedMessage.content?.substring(0, 80)}
                                </div>
                              )}

                              {/* Media */}
                              {msg.mediaUrl &&
                                (msg.type === "image" ||
                                  msg.mediaType?.includes("image")) && (
                                  <img
                                    src={msg.mediaUrl}
                                    alt=""
                                    className="rounded-lg max-w-full mb-1.5 cursor-pointer hover:opacity-90"
                                  />
                                )}

                              {/* Text content */}
                              {msg.content && (
                                <p
                                  className="text-sm leading-relaxed whitespace-pre-wrap"
                                  style={{
                                    color: msg.isFromCustomer
                                      ? "var(--color-foreground)"
                                      : "white",
                                  }}
                                >
                                  {msg.content}
                                </p>
                              )}

                              {/* Timestamp + status */}
                              <div
                                className="flex items-center gap-1.5 mt-1"
                                style={{
                                  color: msg.isFromCustomer
                                    ? "var(--color-muted-foreground)"
                                    : "rgba(225, 238, 250, 0.82)",
                                }}
                              >
                                <span className="text-[10px]">
                                  {new Date(msg.timestamp).toLocaleTimeString(
                                    i18n.language === "ar" ? "ar-EG" : "en-US",
                                    {
                                      hour: "2-digit",
                                      minute: "2-digit",
                                    },
                                  )}
                                </span>
                                {!msg.isFromCustomer && (
                                  <span className="text-[10px]">
                                    {msg.status === "read"
                                      ? "✓✓"
                                      : msg.status === "delivered"
                                        ? "✓✓"
                                        : "✓"}
                                  </span>
                                )}
                              </div>
                            </div>
                          </div>
                        </React.Fragment>
                      );
                    })}
                    <div ref={messagesEndRef} />
                  </div>
                )}
              </div>

              {/* Quick Replies Panel */}
              {showQuickReplies && quickReplies.length > 0 && (
                <div className="business-chat-composer max-h-40 overflow-y-auto">
                  <div className="p-3 space-y-1">
                    <div className="flex items-center justify-between mb-2">
                      <span
                        className="text-xs font-semibold"
                        style={{ color: "var(--color-muted-foreground)" }}
                      >
                        {t("unifiedInbox.quickReplies")}
                      </span>
                      <button
                        onClick={() => setShowQuickReplies(false)}
                        className="business-chip-button"
                      >
                        <XMarkIcon className="w-4 h-4" />
                      </button>
                    </div>
                    {quickReplies.map((reply) => (
                      <button
                        key={reply.id}
                        onClick={() => useQuickReply(reply)}
                        className="w-full rounded-2xl border px-3 py-2 text-right text-sm transition-colors truncate"
                        style={{
                          borderColor: "var(--business-card-border)",
                          background:
                            "color-mix(in srgb, white 74%, var(--color-background) 26%)",
                        }}
                      >
                        <span
                          className="font-medium"
                          style={{ color: "var(--color-foreground)" }}
                        >
                          {reply.title}
                        </span>
                        <span
                          className="mr-2"
                          style={{ color: "var(--color-muted-foreground)" }}
                        >
                          — {reply.content.substring(0, 50)}
                        </span>
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {/* Message Input */}
              <div className="business-chat-composer px-5 py-3">
                <div className="flex items-center gap-2">
                  {/* Actions */}
                  <div className="flex items-center gap-0.5">
                    <button
                      onClick={() => setShowQuickReplies(!showQuickReplies)}
                      className="business-chip-button"
                      title={t("unifiedInbox.quickReplies")}
                    >
                      <BoltIcon className="w-5 h-5" />
                    </button>
                    <button
                      className="business-chip-button"
                      title={t("unifiedInbox.attachFile")}
                    >
                      <PaperClipIcon className="w-5 h-5" />
                    </button>
                    <button
                      className="business-chip-button"
                      title={t("unifiedInbox.emoji")}
                    >
                      <FaceSmileIcon className="w-5 h-5" />
                    </button>
                  </div>

                  {/* Input */}
                  <div className="flex-1">
                    <input
                      type="text"
                      value={newMessage}
                      onChange={(e) => setNewMessage(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" && !e.shiftKey) {
                          e.preventDefault();
                          handleSendMessage();
                        }
                      }}
                      placeholder={t("unifiedInbox.inputPlaceholder", {
                        platform:
                          platformStyles[selectedConversation.platform]
                            ?.label || t("common.platform"),
                      })}
                      className="business-chat-input"
                      disabled={sending}
                    />
                  </div>

                  {/* Send */}
                  <button
                    onClick={handleSendMessage}
                    disabled={!newMessage.trim() || sending}
                    className="business-icon-button text-white p-2.5 rounded-xl disabled:opacity-40 disabled:cursor-not-allowed transition-colors shadow-sm"
                    style={{
                      background:
                        "linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%)",
                    }}
                  >
                    {sending ? (
                      <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    ) : (
                      <PaperAirplaneIcon className="w-5 h-5 rotate-180" />
                    )}
                  </button>
                </div>
              </div>
            </>
          ) : (
            /* Empty State */
            <div className="business-chat-stage flex-1 flex items-center justify-center">
              <div className="text-center max-w-md">
                <div
                  className="mx-auto mb-6 flex h-24 w-24 items-center justify-center rounded-3xl"
                  style={{
                    background:
                      "linear-gradient(135deg, color-mix(in srgb, var(--color-primary) 10%, white) 0%, color-mix(in srgb, var(--color-secondary) 12%, white) 100%)",
                  }}
                >
                  <ChatBubbleLeftRightIcon
                    className="w-12 h-12"
                    style={{ color: "var(--color-primary)" }}
                  />
                </div>
                <h2
                  className="text-xl font-bold mb-2"
                  style={{ color: "var(--color-foreground)" }}
                >
                  {t("unifiedInbox.empty.header")}
                </h2>
                <p
                  className="text-sm leading-relaxed mb-6"
                  style={{ color: "var(--color-muted-foreground)" }}
                >
                  {t("unifiedInbox.empty.subheader")}
                  <br />
                  {t("unifiedInbox.empty.description")}
                </p>
                <div
                  className="flex items-center justify-center gap-6"
                  style={{ color: "var(--color-muted-foreground)" }}
                >
                  <div className="flex flex-col items-center gap-1">
                    <span className="text-2xl">💬</span>
                    <span className="text-xs">Messenger</span>
                  </div>
                  <div className="flex flex-col items-center gap-1">
                    <span className="text-2xl">📱</span>
                    <span className="text-xs">WhatsApp</span>
                  </div>
                  <div className="flex flex-col items-center gap-1">
                    <span className="text-2xl">✈️</span>
                    <span className="text-xs">Telegram</span>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* ═══════════════════════════════════════════════════════════════════ */}
        {/* COLUMN 3 — Customer Profile Panel */}
        {/* ═══════════════════════════════════════════════════════════════════ */}
        {showProfilePanel && selectedConversation && (
          <div className="business-inbox-column business-inbox-column--profile overflow-y-auto">
            {/* Profile Header */}
            <div className="business-inbox-header text-center relative">
              <button
                onClick={() => setShowProfilePanel(false)}
                className={`absolute top-3 p-1 rounded business-chip-button ${isRtl ? "left-3" : "right-3"}`}
              >
                <XMarkIcon className="w-4 h-4" />
              </button>

              <div className="relative inline-block mb-3">
                {selectedConversation.contactAvatar ? (
                  <img
                    src={selectedConversation.contactAvatar}
