} from "lucide-react";

import { apiClient } from "../../services/apiClient";
import { useAuth } from "../../hooks/useAuthSimple";

type CustomerWalletData = {
  id: string;
  balance: number;
  totalEarned?: number;
  totalSpent?: number;
  totalCashback?: number;
  currency?: string;
};

type CustomerWalletTransaction = {
