              {transactions.length} حركة
            </div>
            <div className="text-right">
              <h2 className="text-2xl font-black text-gray-900 dark:text-white">آخر الحركات</h2>
              <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                راجع عمليات الكاش باك، الاسترجاع، واستخدام الرصيد داخل الطلبات.
              </p>
            </div>
          </div>

          {transactions.length === 0 ? (
            <div className="mt-6 rounded-3xl border border-dashed border-gray-200 bg-gray-50 px-6 py-12 text-center text-sm text-gray-500 dark:border-gray-700 dark:bg-gray-900/60 dark:text-gray-400">
              لا توجد حركات على المحفظة بعد.
            </div>
          ) : (
            <div className="mt-6 space-y-3">
              {transactions.map((transaction) => {
                const Icon = transactionIcons[transaction.type] || Clock3;
                const style =
                  transactionStyles[transaction.type] ||
                  "bg-gray-100 text-gray-700 dark:bg-gray-900 dark:text-gray-200";
                const isPositive = positiveTypes.has(transaction.type);

                return (
                  <div
                    key={transaction.id}
                    className="rounded-3xl border border-gray-200 bg-gray-50 p-4 dark:border-gray-700 dark:bg-gray-900/60"
                  >
                    <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                      <div className="flex items-start justify-end gap-3 text-right">
                        <div>
                          <div className="font-bold text-gray-900 dark:text-white">
                            {transaction.description || "حركة على المحفظة"}
                          </div>
                          <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                            {new Intl.DateTimeFormat("ar-EG", {
                              year: "numeric",
                              month: "short",
                              day: "numeric",
                              hour: "numeric",
                              minute: "2-digit",
                            }).format(new Date(transaction.createdAt))}
                          </div>
                          {transaction.orderId ? (
                            <div className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                              مرجع الطلب: {transaction.orderId}
                            </div>
                          ) : null}
                        </div>
                        <div className={`flex h-11 w-11 items-center justify-center rounded-2xl ${style}`}>
                          <Icon size={18} />
                        </div>
                      </div>

                      <div className="text-right">
                        <div className={`text-xl font-black ${isPositive ? "text-green-600" : "text-red-600"}`}>
                          {isPositive ? "+" : "-"}
                          {formatMoney(toNumber(transaction.amount), currency)}
                        </div>
                        <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                          الرصيد بعد الحركة: {formatMoney(toNumber(transaction.balanceAfter), currency)}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  ArrowLeftIcon,
  CloudArrowDownIcon,
  CloudArrowUpIcon,
  Cog6ToothIcon,
  MapIcon,
  ClipboardDocumentListIcon,
  ShoppingBagIcon,
} from "@heroicons/react/24/outline";
import toast from "react-hot-toast";
import tokenManager from "../../utils/tokenManager";

// Types
import { SyncLog } from "./types";

// Hooks
import { useWooCommerceSettings } from "./hooks/useWooCommerceSettings";

// Components
import { ConnectionStatus } from "./components/ConnectionStatus";
import { SettingsTab } from "./components/SettingsTab";
import { ImportTab } from "./components/ImportTab";
import { ExportTab } from "./components/ExportTab";
import { ProductsTab } from "./components/ProductsTab";
import { StatusMappingTab } from "./components/StatusMappingTab";
import { LogsTab } from "./components/LogsTab";

export default function WooCommerceSync() {
  const navigate = useNavigate();
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);

  // State
  const [activeTab, setActiveTab] = useState<
    "import" | "export" | "settings" | "logs" | "status_mapping" | "products"
  >("import");
  const [logs, setLogs] = useState<SyncLog[]>([]);

  // Use Settings Hook (Central Logic)
  const {
    loading,
    testingConnection,
    settingsList,
    selectedSettingsId,
    setSelectedSettingsId,
    settingsForm,
    setSettingsForm,
    ngrokUrl,
    setNgrokUrl,
    loadSettings,
    saveSettings,
    testConnection,
    setupWebhooks,
    disconnectSettings,
    resetWooCommerceData,
  } = useWooCommerceSettings();

  const currentSettings =
    settingsList.find((s) => s.id === selectedSettingsId) || null;

  // Use Effects
  useEffect(() => {
    loadSettings();
    loadSyncLogs();
  }, [loadSettings]);

  // ضمان التحويل لتبويب الإعدادات عند اختيار "إضافة موقع جديد"
  useEffect(() => {
    if (selectedSettingsId === "new") {
      setActiveTab("settings");
      // السكرول لأعلى الصفحة لضمان رؤية النموذج
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  }, [selectedSettingsId]);

  // Load logs (Kept simple here as it's read-only)
  const loadSyncLogs = async () => {
    try {
      const response = await fetch("/api/v1/woocommerce/sync-logs", {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setLogs(data.data);
      }
    } catch (error) {
      console.error("Error loading logs", error);
    }
  };

  const syncNow = async () => {
    if (!currentSettings?.syncEnabled) {
      toast.error("يرجى تفعيل المزامنة أولاً من الإعدادات");
      return;
    }

    try {
      const response = await fetch("/api/v1/woocommerce/auto-sync", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({ id: currentSettings.id }),
      });
      const data = await response.json();
      if (data.success) {
        toast.success("تم بدء المزامنة بنجاح");
        loadSyncLogs();
      } else {
        toast.error(data.message);
      }
    } catch (error) {
      toast.error("فشل بدء المزامنة");
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pt-20 pb-12 px-4 sm:px-6 lg:px-8 dir-rtl">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate("/admin/dashboard")}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
            >
              <ArrowLeftIcon className="h-6 w-6 text-gray-600 dark:text-gray-400" />
            </button>
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                <span className="text-purple-600">WooCommerce</span>
                <span>ربط وانتقال بيانات</span>
              </h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1">
                إدارة المزامنة بين المتجر والنظام المحلي
              </p>
            </div>
          </div>
        </div>

        {/* Connection Status Banner */}
        <ConnectionStatus
          settingsList={settingsList}
          selectedId={selectedSettingsId}
          onSelect={(id) => {
            setSelectedSettingsId(id);
            if (id === "new") {
              setActiveTab("settings");
            }
          }}
          onDisconnect={disconnectSettings}
          loading={loading}
          onSync={syncNow}
        />

        {/* Tabs Navigation */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-x-auto">
          <div className="flex p-1 gap-1 min-w-max">
            <button
              onClick={() => setActiveTab("import")}
              className={`flex items-center gap-2 px-6 py-3 rounded-lg text-sm font-medium transition-all ${activeTab === "import"
                ? "bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 shadow-sm"
                : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700"
                }`}
            >
              <CloudArrowDownIcon className="h-5 w-5" />
              استيراد طلبات
            </button>

            <button
              onClick={() => setActiveTab("products")}
              className={`flex items-center gap-2 px-6 py-3 rounded-lg text-sm font-medium transition-all ${activeTab === "products"
                ? "bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 shadow-sm"
                : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700"
                }`}
            >
              <ShoppingBagIcon className="h-5 w-5" />
              منتجات
            </button>

            <button
              onClick={() => setActiveTab("export")}
              className={`flex items-center gap-2 px-6 py-3 rounded-lg text-sm font-medium transition-all ${activeTab === "export"
                ? "bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 shadow-sm"
                : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700"
                }`}
            >
              <CloudArrowUpIcon className="h-5 w-5" />
              تصدير طلبات
            </button>

            <button
              onClick={() => setActiveTab("status_mapping")}
              className={`flex items-center gap-2 px-6 py-3 rounded-lg text-sm font-medium transition-all ${activeTab === "status_mapping"
                ? "bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 shadow-sm"
                : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700"
                }`}
            >
              <MapIcon className="h-5 w-5" />
              خريطة الحالات
            </button>

            <button
              onClick={() => setActiveTab("settings")}
              className={`flex items-center gap-2 px-6 py-3 rounded-lg text-sm font-medium transition-all ${activeTab === "settings"
                ? "bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 shadow-sm"
                : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700"
                }`}
            >
              <Cog6ToothIcon className="h-5 w-5" />
              الإعدادات
            </button>

            <button
              onClick={() => setActiveTab("logs")}
              className={`flex items-center gap-2 px-6 py-3 rounded-lg text-sm font-medium transition-all ${activeTab === "logs"
                ? "bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 shadow-sm"
                : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700"
                }`}
            >
              <ClipboardDocumentListIcon className="h-5 w-5" />
              السجلات
            </button>
          </div>
        </div>

        {/* Tab Content */}
        <div className="space-y-6 animate-fadeIn">
          {activeTab === "import" && <ImportTab settings={currentSettings} />}

          {activeTab === "products" && (
            <ProductsTab settings={currentSettings} />
          )}

          {activeTab === "export" && <ExportTab settings={currentSettings} />}

          {activeTab === "status_mapping" && (
            <StatusMappingTab
              settings={currentSettings}
              settingsForm={settingsForm}
              setSettingsForm={setSettingsForm}
              saveSettings={saveSettings}
            />
          )}

          {activeTab === "settings" && (
            <SettingsTab
              settings={currentSettings}
              settingsForm={settingsForm}
              setSettingsForm={setSettingsForm}
              saveSettings={saveSettings}
              testConnection={testConnection}
              setupWebhooks={setupWebhooks}
              testingConnection={testingConnection}
              ngrokUrl={ngrokUrl}
              setNgrokUrl={setNgrokUrl}
              loading={loading}
              resetWooCommerceData={resetWooCommerceData}
            />
          )}

          {activeTab === "logs" && <LogsTab logs={logs} />}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect } from "react";
import {
  ArrowPathIcon,
  CloudArrowUpIcon,
  ShoppingCartIcon,
  CheckCircleIcon,
} from "@heroicons/react/24/outline";
import { StatusBadge } from "./shared/StatusBadge";
import { useWooCommerceExport } from "../hooks/useWooCommerceExport";
import { Settings } from "../types";

interface ExportTabProps {
  settings: Settings | null;
}

export const ExportTab: React.FC<ExportTabProps> = ({ settings }) => {
  const {
    localOrders,
    selectedLocalOrders,
    setSelectedLocalOrders,
    exporting,
    loading,
    fetchLocalOrders,
    exportSelectedOrders,
  } = useWooCommerceExport(settings);

  // Initial fetch
  useEffect(() => {
    fetchLocalOrders();
  }, []);

  return (
    <div>
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
            تصدير الطلبات إلى WooCommerce
          </h2>
          <p className="text-gray-600 dark:text-gray-400 text-sm">
            إرسال الطلبات المحلية إلى متجر WooCommerce
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap justify-end">
          <button
            onClick={fetchLocalOrders}
            disabled={loading}
            className="flex-1 sm:flex-none px-4 py-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-300 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {loading ? (
              <ArrowPathIcon className="h-5 w-5 animate-spin" />
            ) : (
              <ArrowPathIcon className="h-5 w-5" />
            )}
            تحديث القائمة
          </button>
        </div>
      </div>

      {(localOrders?.length || 0) > 0 && (
        <>
          <div className="flex items-center justify-between mb-4">
            {selectedLocalOrders.size} من {localOrders?.length || 0} طلب محدد
            <button
              onClick={exportSelectedOrders}
              disabled={exporting || selectedLocalOrders.size === 0}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg flex items-center gap-2 disabled:opacity-50"
            >
              {exporting ? (
                <ArrowPathIcon className="h-5 w-5 animate-spin" />
              ) : (
                <CloudArrowUpIcon className="h-5 w-5" />
              )}
              تصدير المحدد ({selectedLocalOrders.size})
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 dark:bg-gray-700">
                <tr>
                  <th className="px-4 py-3 text-right">
                    <input
                      type="checkbox"
                      checked={
                        selectedLocalOrders.size === (localOrders?.length || 0)
                      }
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedLocalOrders(
                            new Set(localOrders.map((o) => o.id)),
                          );
                        } else {
                          setSelectedLocalOrders(new Set());
                        }
                      }}
                      className="rounded"
                    />
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium text-gray-700 dark:text-gray-300">
                    رقم الطلب
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium text-gray-700 dark:text-gray-300">
                    العميل
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium text-gray-700 dark:text-gray-300">
                    الحالة
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium text-gray-700 dark:text-gray-300">
                    حالة المزامنة
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium text-gray-700 dark:text-gray-300">
                    الإجمالي
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium text-gray-700 dark:text-gray-300">
                    التاريخ
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                {localOrders.map((order) => (
                  <tr
                    key={order.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-700"
                  >
                    <td className="px-4 py-3">
                      <input
                        type="checkbox"
                        checked={selectedLocalOrders.has(order.id)}
                        onChange={(e) => {
                          const newSet = new Set(selectedLocalOrders);
                          if (e.target.checked) {
                            newSet.add(order.id);
                          } else {
                            newSet.delete(order.id);
                          }
                          setSelectedLocalOrders(newSet);
                        }}
                        className="rounded"
                      />
                    </td>
                    <td className="px-4 py-3 text-sm font-medium text-gray-900 dark:text-white">
                      #{order.orderNumber}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-900 dark:text-white">
                      {order.customerName}
                    </td>
                    <td className="px-4 py-3">
                      <StatusBadge status={order.status} />
                    </td>
                    <td className="px-4 py-3 text-sm">
                      {order.syncedToWoo ? (
                        <span className="flex items-center gap-1 text-green-600 dark:text-green-400">
                          <CheckCircleIcon className="h-4 w-4" />
                          متزامن
                        </span>
                      ) : (
                        <span className="text-gray-500">غير متزامن</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-sm font-medium text-gray-900 dark:text-white">
                      {order.total}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-500">
                      {new Date(order.createdAt).toLocaleDateString("ar-EG")}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {(localOrders?.length || 0) === 0 && !loading && (
        <div className="text-center py-12">
          <ShoppingCartIcon className="h-16 w-16 text-gray-300 mx-auto mb-4" />
          <p className="text-gray-500 dark:text-gray-400">
            اضغط على "تحديث القائمة" لعرض الطلبات المحلية
          </p>
        </div>
      )}
    </div>
  );
};

import React, { useEffect } from "react";
import {
  ArrowDownTrayIcon,
  ArrowPathIcon,
  PauseIcon,
  PlayIcon,
  StopIcon,
  XCircleIcon,
  CheckCircleIcon,
} from "@heroicons/react/24/outline";
import { StatusBadge } from "./shared/StatusBadge";
import { useCurrency } from "../../../hooks/useCurrency";
import { useWooCommerceImport } from "../hooks/useWooCommerceImport";
import { Settings } from "../types";

interface ImportTabProps {
  settings: Settings | null;
}

export const ImportTab: React.FC<ImportTabProps> = ({ settings }) => {
  const { formatPrice } = useCurrency();
  const {
    loading,
    importing,
    wooOrders,
    activeJob,
    totalOrdersCount,
    countingOrders,
    selectedWooOrders,
    setSelectedWooOrders,
    loadActiveJobs,
    fetchOrdersCount,
    fetchWooOrders,
    startBackendImport,
    pauseBackendImport,
    resumeBackendImport,
    cancelBackendImport,
    importSelectedOrders,
    showImportOptions,
    setShowImportOptions,
    importOptions,
    setImportOptions,
  } = useWooCommerceImport(settings);

  // Load active jobs on mount
  useEffect(() => {
    loadActiveJobs();
  }, []);

  return (
    <div>
      {/* Active Import Status Banner */}
      {activeJob && (
        <div className="mb-8 p-6 bg-white dark:bg-gray-800 rounded-xl border border-blue-200 dark:border-blue-800 shadow-lg shadow-blue-500/5">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              {activeJob.status === "running" && (
                <ArrowPathIcon className="h-5 w-5 text-blue-600 animate-spin" />
              )}
              {activeJob.status === "paused" && (
                <PauseIcon className="h-5 w-5 text-yellow-600" />
              )}
              {activeJob.status === "failed" && (
                <XCircleIcon className="h-5 w-5 text-red-600" />
              )}
              {activeJob.status === "completed" && (
                <CheckCircleIcon className="h-5 w-5 text-green-600" />
              )}
              <span className="font-bold text-gray-900 dark:text-white">
                {activeJob.status === "running" &&
                  "🚀 جاري الاستيراد في الخلفية..."}
                {activeJob.status === "paused" && "⏸️ الاستيراد متوقف مؤقتاً"}
                {activeJob.status === "failed" && "❌ فشل الاستيراد"}
                {activeJob.status === "completed" && "✅ تم اكتمال الاستيراد"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              {activeJob.status === "running" && (
                <button
                  onClick={pauseBackendImport}
                  className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-yellow-600"
                  title="إيقاف مؤقت"
                >
                  <PauseIcon className="h-5 w-5" />
                </button>
              )}
              {activeJob.status === "paused" && (
                <button
                  onClick={resumeBackendImport}
                  className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-green-600"
                  title="استئناف"
                >
                  <PlayIcon className="h-5 w-5" />
                </button>
              )}
              {(activeJob.status === "running" ||
                activeJob.status === "paused") && (
                <button
                  onClick={cancelBackendImport}
                  className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-red-600"
                  title="إلغاء الأمر"
                >
                  <StopIcon className="h-5 w-5" />
                </button>
              )}
            </div>
          </div>

          {/* Progress Bar */}
          <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
            <div
              className={`h-4 rounded-full transition-all duration-500 ${
                activeJob.status === "failed"
                  ? "bg-red-500"
                  : activeJob.status === "completed"
                    ? "bg-green-500"
                    : activeJob.status === "paused"
                      ? "bg-yellow-500"
                      : "bg-blue-600"
              }`}
              style={{
                width: `${Math.max(5, activeJob.progress.percentage)}%`,
              }}
            ></div>
          </div>

          <div className="flex justify-between text-sm text-gray-600 dark:text-gray-400 font-medium">
            <span>
              تم معالجة {activeJob.progress.processedOrders} من{" "}
              {activeJob.progress.grandTotal} طلب (
              {Math.round(activeJob.progress.percentage)}%)
            </span>
            <div className="flex gap-4">
              {activeJob.progress.imported > 0 && (
                <span className="text-green-600">
                  تم استيراد: {activeJob.progress.imported}
                </span>
              )}
              {activeJob.progress.updated > 0 && (
                <span className="text-blue-600">
                  تم تحديث: {activeJob.progress.updated}
                </span>
              )}
              {activeJob.progress.failed > 0 && (
                <span className="text-red-600">
                  فشل: {activeJob.progress.failed}
                </span>
              )}
              {activeJob.progress.skipped > 0 && (
                <span className="text-gray-500">
                  تم تخطي: {activeJob.progress.skipped}
                </span>
              )}
            </div>
          </div>

          {activeJob.progress.error && (
            <div className="mt-4 p-3 bg-red-50 text-red-700 rounded-lg text-sm border border-red-200">
              <strong>خطأ:</strong> {activeJob.progress.error}
            </div>
          )}
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-6 mb-8">
        <div className="flex-1">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
            استيراد الطلبات
          </h2>
          <p className="text-gray-600 dark:text-gray-400 text-sm">
            جلب الطلبات من WooCommerce إلى النظام المحلي
          </p>
        </div>

        <div className="flex flex-wrap gap-3 items-end">
          <button
            onClick={() => setShowImportOptions(!showImportOptions)}
            className="px-4 py-2.5 border border-gray-200 dark:border-gray-700 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300 transition-colors text-sm font-medium"
          >
            ⚙️ خيارات متقدمة
          </button>
          <button
            onClick={fetchOrdersCount}
            disabled={countingOrders}
            className="px-4 py-2.5 bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-300 border border-blue-100 dark:border-blue-900/30 rounded-xl hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-colors text-sm font-medium flex items-center gap-2"
          >
            {countingOrders ? (
              <ArrowPathIcon className="h-4 w-4 animate-spin" />
            ) : (
              "📊"
            )}
            {totalOrdersCount !== null
              ? `الإجمالي: ${totalOrdersCount}`
              : "فحص العدد"}
          </button>
        </div>
      </div>

      {/* Import Options Panel */}
      {showImportOptions && (
        <div className="mb-6 p-5 bg-gray-50 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 grid grid-cols-1 md:grid-cols-4 gap-4 animate-fadeIn">
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">
              العدد
            </label>
            <select
              value={importOptions.limit}
              onChange={(e) =>
                setImportOptions((prev) => ({
                  ...prev,
                  limit: e.target.value as any,
                }))
              }
              className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm"
            >
              <option value="10">آخر 10 طلبات</option>
              <option value="50">آخر 50 طلب</option>
              <option value="100">آخر 100 طلب</option>
              <option value="all">كل الطلبات (استيراد كامل)</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">
              الحالة
            </label>
            <select
              value={importOptions.status}
              onChange={(e) =>
                setImportOptions((prev) => ({
                  ...prev,
                  status: e.target.value,
                }))
              }
              className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm"
            >
              <option value="any">أي حالة</option>
              <option value="processing">Processing</option>
              <option value="completed">Completed</option>
              <option value="pending">Pending</option>
              <option value="on-hold">On Hold</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">
              عند التكرار
            </label>
            <select
              value={importOptions.duplicateAction}
              onChange={(e) =>
                setImportOptions((prev) => ({
                  ...prev,
                  duplicateAction: e.target.value as any,
                }))
              }
              className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm"
            >
              <option value="skip">تجاهل (Skip)</option>
              <option value="update">تحديث (Update)</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">
              الإجراء
            </label>
            <div className="flex gap-2">
              <button
                onClick={fetchWooOrders}
                disabled={loading}
                className="flex-1 px-3 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 hover:bg-gray-50 rounded-lg text-sm text-gray-700 dark:text-gray-200"
                title="معاينة الطلبات قبل الاستيراد"
              >
                👁️ معاينة
              </button>
              <button
                onClick={startBackendImport}
                disabled={importing || !!activeJob}
                className="flex-1 px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm flex items-center justify-center gap-1 shadow-sm"
                title="بدء عملية الاستيراد في الخلفية مباشرة"
              >
                {importing ? (
                  <ArrowPathIcon className="h-4 w-4 animate-spin" />
                ) : (
                  <PlayIcon className="h-4 w-4" />
                )}
                بدء
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Review Table */}
      {wooOrders.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden shadow-sm">
          <div className="p-4 bg-gray-50 dark:bg-gray-900/50 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center">
            <div className="font-semibold text-gray-700 dark:text-gray-300 flex items-center gap-2">
              <span>نتائج المعاينة</span>
              <span className="bg-blue-100 text-blue-800 text-xs px-2 py-0.5 rounded-full">
                {wooOrders.length}
              </span>
            </div>
            {selectedWooOrders.size > 0 && (
              <button
                onClick={importSelectedOrders}
                disabled={importing}
                className="px-4 py-1.5 bg-green-600 hover:bg-green-700 text-white rounded-lg text-sm font-medium flex items-center gap-2 shadow-sm transition-all active:scale-95"
              >
                <ArrowDownTrayIcon className="h-4 w-4" />
                استيراد المحدد ({selectedWooOrders.size})
              </button>
            )}
          </div>

          <div className="overflow-x-auto max-h-[500px]">
            <table className="w-full text-right">
              <thead className="bg-gray-50 dark:bg-gray-700 sticky top-0 z-10 shadow-sm">
                <tr>
                  <th className="px-4 py-3 w-12 text-center">
                    <input
                      type="checkbox"
                      checked={selectedWooOrders.size === wooOrders.length}
                      onChange={(e) => {
                        if (e.target.checked)
                          setSelectedWooOrders(
                            new Set(wooOrders.map((o) => o.wooCommerceId)),
                          );
                        else setSelectedWooOrders(new Set());
                      }}
                      className="rounded border-gray-300 text-blue-600 focus:ring-offset-0 focus:ring-1"
                    />
                  </th>
                  <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase">
                    الطلب
                  </th>
                  <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase">
                    العميل
                  </th>
                  <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase">
                    الحالة
                  </th>
                  <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase">
                    الإجمالي
                  </th>
                  <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase">
                    التاريخ
                  </th>
                  <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase">
                    في النظام؟
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
                {wooOrders.map((order) => (
                  <tr
                    key={order.wooCommerceId}
                    className="hover:bg-blue-50/50 dark:hover:bg-blue-900/10 transition-colors"
                  >
                    <td className="px-4 py-3 text-center">
                      <input
                        type="checkbox"
                        checked={selectedWooOrders.has(order.wooCommerceId)}
                        onChange={(e) => {
                          const newSet = new Set(selectedWooOrders);
                          if (e.target.checked) newSet.add(order.wooCommerceId);
                          else newSet.delete(order.wooCommerceId);
                          setSelectedWooOrders(newSet);
                        }}
                        className="rounded border-gray-300 text-blue-600 focus:ring-offset-0 focus:ring-1"
                      />
                    </td>
                    <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">
                      #{order.orderNumber}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-600 dark:text-gray-300">
                      <div>{order.customerName}</div>
                      <div className="text-xs text-gray-400">
                        {order.customerEmail}
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      <StatusBadge status={order.wooCommerceStatus} />
                    </td>
                    <td className="px-4 py-3 font-mono text-sm">
                      {formatPrice(order.total, order.currency)}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-500" dir="ltr">
                      {new Date(
                        order.wooCommerceDateCreated,
                      ).toLocaleDateString()}
                    </td>
                    <td className="px-4 py-3">
                      {order.localStatus ? (
                        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400">
                          موجود ({order.localStatus})
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300">
                          جديد
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

import React from "react";
import {
  ArrowPathIcon,
  ArrowDownTrayIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  FunnelIcon,
  ShoppingBagIcon,
} from "@heroicons/react/24/outline";
import { useCurrency } from "../../../hooks/useCurrency";
import { useWooCommerceProducts } from "../hooks/useWooCommerceProducts";
import { Settings } from "../types";
import { getImageUrl } from "../../../utils/imageUrl";

interface ProductsTabProps {
  settings: Settings | null;
}

export const ProductsTab: React.FC<ProductsTabProps> = ({ settings }) => {
  const { formatPrice } = useCurrency();
  const {
    wooProducts,
    fetchingProducts,
    importingProducts,
    selectedWooProducts,
    setSelectedWooProducts,
    selectedVariants,
    expandedProduct,
    setExpandedProduct,
    variantFilter,
    setVariantFilter,
    fetchWooProducts,
    importSelectedProducts,
    toggleVariantSelection,
    selectAllVariantsForProduct,
    deselectAllVariantsForProduct,
    groupVariantsByType,
    selectVariantsByType,
  } = useWooCommerceProducts(settings);

  return (
    <div>
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
            استيراد المنتجات
          </h2>
          <p className="text-gray-600 dark:text-gray-400 text-sm">
            جلب المنتجات وتحديث المخزون من WooCommerce
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap justify-end">
          <button
            onClick={fetchWooProducts}
            disabled={fetchingProducts}
            className="flex-1 sm:flex-none px-4 py-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-300 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-colors"
          >
            {fetchingProducts ? (
              <ArrowPathIcon className="h-5 w-5 animate-spin" />
            ) : (
              <ArrowPathIcon className="h-5 w-5" />
            )}
            تحديث القائمة
          </button>
        </div>
      </div>

      {(wooProducts?.length || 0) > 0 && (
        <>
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 p-4 bg-gray-50 dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-700">
            <div className="flex items-center gap-4">
              <span className="font-medium text-gray-700 dark:text-gray-300">
                تصفية المتغيرات:
              </span>
              <div className="flex gap-2">
                <button
                  onClick={() => setVariantFilter("all")}
                  className={`px-3 py-1.5 rounded-lg text-sm transition-colors ${
                    variantFilter === "all"
                      ? "bg-blue-600 text-white shadow-sm"
                      : "bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700"
                  }`}
                >
                  الكل
                </button>
                <button
                  onClick={() => setVariantFilter("color")}
                  className={`px-3 py-1.5 rounded-lg text-sm transition-colors flex items-center gap-1 ${
                    variantFilter === "color"
                      ? "bg-blue-600 text-white shadow-sm"
                      : "bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 "
                  }`}
                >
                  <span className="w-2 h-2 rounded-full bg-gradient-to-r from-pink-500 to-purple-500"></span>
                  ألوان
                </button>
                <button
                  onClick={() => setVariantFilter("size")}
                  className={`px-3 py-1.5 rounded-lg text-sm transition-colors flex items-center gap-1 ${
                    variantFilter === "size"
                      ? "bg-blue-600 text-white shadow-sm"
                      : "bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700"
                  }`}
                >
                  <FunnelIcon className="w-3 h-3" />
                  مقاسات
                </button>
              </div>
            </div>

            <button
              onClick={importSelectedProducts}
              disabled={importingProducts || selectedWooProducts.size === 0}
              className="px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg shadow-blue-500/20 active:scale-95 transition-all font-bold"
            >
              {importingProducts ? (
                <ArrowPathIcon className="h-5 w-5 animate-spin" />
              ) : (
                <ArrowDownTrayIcon className="h-5 w-5" />
              )}
              استيراد المحدد ({selectedWooProducts.size})
            </button>
          </div>

          <div className="space-y-4">
            {wooProducts.map((product) => {
              const isExpanded = expandedProduct === product.wooCommerceId;
              const hasVariations =
                product.isVariable &&
                product.variations &&
                product.variations.length > 0;
              const productSelected = selectedWooProducts.has(
                product.wooCommerceId,
              );
              const selectedCount =
                selectedVariants.get(product.wooCommerceId)?.size || 0;
              const totalVariations = product.variations?.length || 0;
              const variantTypes = hasVariations
                ? groupVariantsByType(product.variations!)
                : {};

              // Apply Filters
              if (variantFilter !== "all") {
                if (!hasVariations) return null;
                const matchesFilter = product.variations!.some((v) =>
                  v.attributes.some((a: any) => a.type === variantFilter),
                );
                if (!matchesFilter) return null;
              }

              return (
                <div
                  key={product.wooCommerceId}
                  className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden text-right"
                >
                  <div className="p-4 flex items-center gap-4 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                    <input
                      type="checkbox"
                      checked={productSelected}
                      onChange={(e) => {
                        if (e.target.checked)
                          selectAllVariantsForProduct(product.wooCommerceId);
                        else
                          deselectAllVariantsForProduct(product.wooCommerceId);
                      }}
                      className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-offset-0 focus:ring-1"
                    />
                    {product.images?.[0] ? (
                      <img
                        src={getImageUrl(product.images[0]) || ""}
                        alt={product.name}
                        className="w-12 h-12 object-cover rounded-lg border border-gray-200 dark:border-gray-700"
                      />
                    ) : (
                      <div className="w-12 h-12 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center">
                        <ShoppingBagIcon className="w-6 h-6 text-gray-400" />
                      </div>
                    )}
                    <div className="flex-1">
                      <h3 className="font-semibold text-gray-900 dark:text-white">
                        {product.name}
                      </h3>
                      <div className="flex items-center gap-4 text-sm text-gray-500 mt-1">
                        <span>#{product.sku || "N/A"}</span>
                        <span>•</span>
                        <span>{formatPrice(product.price)}</span>
                        {hasVariations && (
                          <>
                            <span>•</span>
                            <span className="text-blue-600 bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded text-xs font-medium">
                              {totalVariations} متغيرات
                              {selectedCount > 0 && ` (${selectedCount} محدد)`}
                            </span>
                          </>
                        )}
                      </div>

                      {/* Quick Variation Filters for this product */}
                      {hasVariations && isExpanded && (
                        <div className="flex gap-2 mt-2">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              selectAllVariantsForProduct(
                                product.wooCommerceId,
                              );
                            }}
                            className="text-xs text-blue-600 hover:underline"
                          >
                            تحديد الكل
                          </button>
                          {variantTypes.color && (
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                selectVariantsByType(
                                  product.wooCommerceId,
                                  "color",
                                );
                              }}
                              className="text-xs text-gray-500 hover:text-gray-900 dark:hover:text-gray-300"
                            >
                              تحديد الألوان
                            </button>
                          )}
                          {variantTypes.size && (
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                selectVariantsByType(
                                  product.wooCommerceId,
                                  "size",
                                );
                              }}
                              className="text-xs text-gray-500 hover:text-gray-900 dark:hover:text-gray-300"
                            >
                              تحديد المقاسات
                            </button>
                          )}
                        </div>
                      )}
                    </div>

                    {hasVariations && (
                      <button
                        onClick={() =>
                          setExpandedProduct(
                            isExpanded ? null : product.wooCommerceId,
                          )
                        }
                        className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-500"
                      >
                        {isExpanded ? (
                          <ChevronDownIcon className="w-5 h-5" />
                        ) : (
                          <ChevronRightIcon className="w-5 h-5" />
                        )}
                      </button>
                    )}
                  </div>

                  {/* Variations List */}
                  {isExpanded && hasVariations && (
                    <div className="border-t border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-black/20 p-4 grid grid-cols-1 md:grid-cols-2 gap-3 animate-fadeIn">
                      {product.variations!.map((variant) => {
                        // Check Filters
                        if (variantFilter !== "all") {
                          const hasAttr = variant.attributes.some(
                            (a: any) => a.type === variantFilter,
                          );
                          if (!hasAttr) return null;
                        }

                        const isSelected = selectedVariants
                          .get(product.wooCommerceId)
                          ?.has(variant.wooCommerceVariationId);

                        return (
                          <div
                            key={variant.wooCommerceVariationId}
                            onClick={() =>
                              toggleVariantSelection(
                                product.wooCommerceId,
                                variant.wooCommerceVariationId,
                              )
                            }
                            className={`
                                                flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-all
                                                ${
                                                  isSelected
                                                    ? "bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800"
                                                    : "bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600"
                                                }
                                            `}
                          >
                            <input
                              type="checkbox"
                              checked={!!isSelected}
                              readOnly
                              className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-offset-0 focus:ring-1 pointer-events-none"
                            />
                            {variant.images?.[0] && (
                              <img
                                src={getImageUrl(variant.images[0]) || ""}
                                alt=""
                                className="w-10 h-10 object-cover rounded border border-gray-100 dark:border-gray-700"
                              />
                            )}
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2 flex-wrap">
                                {variant.attributes.map(
                                  (attr: any, idx: number) => (
                                    <span
                                      key={idx}
                                      className={`text-xs px-2 py-0.5 rounded border ${
                                        attr.type === "color"
                                          ? "bg-gray-100 dark:bg-gray-700 border-gray-200 dark:border-gray-600"
                                          : "bg-gray-100 dark:bg-gray-700 border-gray-200 dark:border-gray-600 text-gray-600 dark:text-gray-300"
                                      }`}
                                    >
                                      {attr.type === "color" &&
                                        attr.colorHex && (
                                          <span
                                            className="w-2 h-2 rounded-full inline-block ml-1"
                                            style={{
                                              backgroundColor: attr.colorHex,
                                            }}
                                          ></span>
                                        )}
                                      {attr.option}
                                    </span>
                                  ),
                                )}
                              </div>
                              <div className="text-xs text-gray-500 mt-1 flex justify-between">
                                <span>{variant.sku || "No SKU"}</span>
                                <span className="font-semibold text-gray-700 dark:text-gray-300">
                                  {formatPrice(variant.price)}
                                </span>
                              </div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </>
      )}

      {(wooProducts?.length || 0) === 0 && !fetchingProducts && (
        <div className="text-center py-12">
          <ShoppingBagIcon className="h-16 w-16 text-gray-300 mx-auto mb-4" />
          <p className="text-gray-500 dark:text-gray-400">
            اضغط على "تحديث القائمة" لعرض المنتجات
          </p>
        </div>
      )}
    </div>
  );
};

import React, { useRef, useEffect } from "react";
import toast from "react-hot-toast";
import {
  ArrowPathIcon,
  CloudArrowDownIcon,
  CheckCircleIcon,
  PlusIcon,
} from "@heroicons/react/24/outline";
import { StatusBadge } from "./shared/StatusBadge";
import { useWooCommerceStatus } from "../hooks/useWooCommerceStatus";
import { Settings } from "../types";

interface StatusMappingTabProps {
  settings: Settings | null;
  settingsForm: any;
  setSettingsForm: React.Dispatch<React.SetStateAction<any>>;
  saveSettings: () => Promise<void>;
}

export const StatusMappingTab: React.FC<StatusMappingTabProps> = ({
  settings,
  settingsForm,
  setSettingsForm,
  saveSettings,
}) => {
  const {
    wooStatuses,
    fetchingStatuses,
    localStatuses,
    statusSearch,
    setStatusSearch,
    fetchLocalStatuses,
    fetchWooStatuses,
    autoMapStatuses,
    defaultStatusMapping,
  } = useWooCommerceStatus(settings, settingsForm, setSettingsForm);

  const customStatusRef = useRef<HTMLInputElement>(null);

  // Fetch local statuses on mount
  useEffect(() => {
    fetchLocalStatuses();
  }, [fetchLocalStatuses]);

  // Fetch woo statuses on mount/settings change
  useEffect(() => {
    if (settings?.hasCredentials) {
      fetchWooStatuses();
    }
  }, [settings?.hasCredentials]);

  const filteredStatuses = wooStatuses.filter(
    (s) =>
      s.name.toLowerCase().includes(statusSearch.toLowerCase()) ||
      s.slug.toLowerCase().includes(statusSearch.toLowerCase()),
  );

  const handleStatusChange = (wooSlug: string, localStatus: string) => {
    setSettingsForm((prev: any) => ({
      ...prev,
      statusMapping: {
        ...prev.statusMapping,
        [wooSlug]: localStatus,
      },
    }));
  };

  const handleAddCustomStatus = () => {
    const val = customStatusRef.current?.value?.trim();
    if (val && !settingsForm.statusMapping?.[val]) {
      const newMapping = { ...settingsForm.statusMapping };
      newMapping[val] = "PROCESSING"; // Default
      setSettingsForm((prev: any) => ({ ...prev, statusMapping: newMapping }));
      toast.success(`تم إضافة الحالة "${val}"`);
      if (customStatusRef.current) customStatusRef.current.value = "";
    } else if (settingsForm.statusMapping?.[val]) {
      toast.error("هذه الحالة موجودة بالفعل");
    }
  };

  return (
    <div>
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6 mb-6">
        <div>
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
            ربط حالات الطلبات (Status Mapping)
          </h2>
          <p className="text-gray-600 dark:text-gray-400 text-sm">
            تحديد الحالة المقابلة في النظام لكل حالة من حالات WooCommerce
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2 justify-end">
          <button
            onClick={fetchWooStatuses}
            disabled={fetchingStatuses}
            className="flex-1 sm:flex-none px-4 py-2.5 border border-gray-200 dark:border-gray-700 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300 flex items-center justify-center gap-2 disabled:opacity-50 transition-all font-semibold shadow-sm active:scale-95"
          >
            {fetchingStatuses ? (
              <ArrowPathIcon className="h-5 w-5 animate-spin text-blue-500" />
            ) : (
              <CloudArrowDownIcon className="h-5 w-5 text-blue-500" />
            )}
            جلب الحالات
          </button>
          <button
            onClick={() =>
              setSettingsForm((prev: any) => ({
                ...prev,
                statusMapping: defaultStatusMapping,
              }))
            }
            className="flex-1 sm:flex-none px-4 py-2.5 border border-gray-200 dark:border-gray-700 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300 flex items-center justify-center gap-2 transition-all font-semibold shadow-sm active:scale-95"
          >
            <ArrowPathIcon className="h-5 w-5 text-orange-500" />
            الافتراضي
          </button>
          <button
            onClick={autoMapStatuses}
            className="flex-1 sm:flex-none px-4 py-2.5 bg-blue-50 hover:bg-blue-100 border border-blue-200 dark:bg-blue-500/10 dark:hover:bg-blue-500/20 dark:border-blue-500/30 rounded-xl text-blue-600 dark:text-blue-400 flex items-center justify-center gap-2 transition-all font-bold shadow-sm active:scale-95"
            title="اقتراح الربط تلقائياً بناءً على أسماء الحالات"
          >
            <span>🤖</span>
            ربط تلقائي
          </button>
          <button
            onClick={saveSettings}
            className="w-full sm:flex-1 xl:flex-none px-6 py-2.5 bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 text-white rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-blue-500/20 transition-all active:scale-95 font-bold"
          >
            <CheckCircleIcon className="h-5 w-5" />
            حفظ الخريطة
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-6">
        {/* شرح التلوين */}
        <div className="flex flex-wrap gap-4 mb-6 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg text-sm text-gray-600 dark:text-gray-400">
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-green-500"></span>
            <span>حالة مكتملة/ناجحة</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-blue-500"></span>
            <span>قيد التجهيز</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-yellow-500"></span>
            <span>معلق/انتظار</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-red-500"></span>
            <span>ملغي/فشل</span>
          </div>
        </div>

        {/* البحث */}
        <div className="mb-6 relative">
          <input
            type="text"
            placeholder="🔍 ابحث عن حالة..."
            value={statusSearch}
            onChange={(e) => setStatusSearch(e.target.value)}
            className="w-full px-4 py-3 border border-gray-200 dark:border-gray-700 rounded-xl bg-gray-50 dark:bg-gray-900/50 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
          />
        </div>

        <div className="space-y-4">
          <div className="grid grid-cols-12 gap-4 px-4 py-2 bg-gray-50 dark:bg-gray-700/50 rounded-lg text-sm font-bold text-gray-500 dark:text-gray-400">
