              </button>
            </div>
          </div>

          {/* Mappings View */}
          <div className="mt-8">
            <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              الخريطة الحالية:
            </h3>
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4 font-mono text-xs overflow-x-auto border border-gray-200 dark:border-gray-700 max-h-40 overflow-y-auto">
              <div className="flex flex-wrap gap-2">
                {Object.entries(settingsForm.statusMapping || {}).map(
                  ([key, val]) => (
                    <span
                      key={key}
                      className="px-2 py-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-600 rounded flex items-center gap-1"
                    >
                      <span className="text-gray-500">{key}</span>
                      <span className="text-gray-300">→</span>
                      <StatusBadge status={val as string} />
                    </span>
                  ),
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import { useState } from "react";
import toast from "react-hot-toast";
import { LocalOrder, Settings } from "../types";
import tokenManager from "../../../utils/tokenManager";

export const useWooCommerceExport = (settings: Settings | null) => {
  const [localOrders, setLocalOrders] = useState<LocalOrder[]>([]);
  const [selectedLocalOrders, setSelectedLocalOrders] = useState<Set<string>>(
    new Set(),
  );
  const [exporting, setExporting] = useState(false);
  const [loading, setLoading] = useState(false);
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);

  const fetchLocalOrders = async () => {
    setLoading(true);
    setLocalOrders([]);
    try {
      const response = await fetch("/api/v1/woocommerce/orders/local", {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setLocalOrders(data.data.orders || []);
      }
    } catch (error) {
      toast.error("خطأ في جلب الطلبات المحلية");
    } finally {
      setLoading(false);
    }
  };

  const exportSelectedOrders = async () => {
    if (selectedLocalOrders.size === 0) return;
    if (!settings?.id) {
      toast.error("يرجى اختيار متجر WooCommerce أولاً");
      return;
    }
    setExporting(true);

    try {
      const response = await fetch("/api/v1/woocommerce/orders/export", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settings.id,
          orderIds: Array.from(selectedLocalOrders),
        }),
      });

      const data = await response.json();

      if (data.success) {
        const exported = data.data?.exported || 0;
        const failed = data.data?.failed || 0;

        if (failed > 0) {
          toast(
            `تم تصدير ${exported} طلب بنجاح، وفشل ${failed} طلب. راجع سجلات المزامنة للتفاصيل.`,
            {
              duration: 5000,
              icon: "⚠️",
            },
          );
        } else {
          toast.success(`تم تصدير ${exported} طلب بنجاح`);
        }

        setSelectedLocalOrders(new Set());
        fetchLocalOrders();
      } else {
        const errorDetails = data.data?.errors;
        const errorMsg = data.message || "فشل التصدير الجزئي";

        toast.error(
          errorDetails
            ? `${errorMsg}\n${typeof errorDetails === "string" ? errorDetails : JSON.stringify(errorDetails)}`
            : errorMsg,
          { duration: 7000 },
        );
      }
    } catch (error: any) {
      toast.error(`خطأ في تصدير الطلبات: ${error.message || "خطأ غير معروف"}`);
    } finally {
      setExporting(false);
    }
  };

  return {
    localOrders,
    selectedLocalOrders,
    setSelectedLocalOrders,
    exporting,
    loading,
    fetchLocalOrders,
    exportSelectedOrders,
  };
};

import { useState, useRef, useEffect } from "react";
import toast from "react-hot-toast";
import io, { Socket } from "socket.io-client";
import { WooOrder, ImportJob, Settings } from "../types";
import tokenManager from "../../../utils/tokenManager";

export const useWooCommerceImport = (settings: Settings | null) => {
  const [loading, setLoading] = useState(false);
  const [wooOrders, setWooOrders] = useState<WooOrder[]>([]);
  const [activeJob, setActiveJob] = useState<ImportJob | null>(null);
  const [importing, setImporting] = useState(false);
  const [totalOrdersCount, setTotalOrdersCount] = useState<number | null>(null);
  const [countingOrders, setCountingOrders] = useState(false);
  const [selectedWooOrders, setSelectedWooOrders] = useState<Set<string>>(
    new Set(),
  );

  // Resume state if any
  const [resumeState, setResumeState] = useState<{
    currentPage: number;
    currentBatch: number;
    processedOrders: number;
    grandTotal: number;
    totalBatches: number;
    timestamp: string;
  } | null>(null);

  const socketRef = useRef<Socket | null>(null);
  const [showImportOptions, setShowImportOptions] = useState(false);
  const [importOptions, setImportOptions] = useState({
    limit: "10" as "10" | "50" | "100" | "all",
    status: "any",
    dateFrom: "",
    dateTo: "",
    batchSize: "50" as "50" | "100",
    duplicateAction: "skip" as "skip" | "update",
  });
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);

  // Socket.io initialization for real-time progress
  useEffect(() => {
    socketRef.current = io("/", {
      path: "/socket.io",
      transports: ["websocket"],
      upgrade: false,
      auth: {
        token: tokenManager.getAccessToken(),
      },
    });

    socketRef.current.on("connect", () => {
      console.log("🔌 Socket connected:", socketRef.current?.id);
    });

    socketRef.current.on("import:progress", (data: any) => {
      if (data.jobId && (!activeJob || activeJob.jobId === data.jobId)) {
        setActiveJob((prev) => ({
          ...prev!,
          jobId: data.jobId,
          type: "import",
          status: "running",
          progress: data,
        }));
      }
    });

    socketRef.current.on("import:completed", (data: any) => {
      setActiveJob((prev) => ({
        ...prev!,
        status: "completed",
        progress: { ...prev!.progress, ...data.result, percentage: 100 },
      }));
      toast.success("تم اكتمال الاستيراد بنجاح!");
      setTimeout(() => setActiveJob(null), 5000);
    });

    socketRef.current.on("import:failed", (data: any) => {
      setActiveJob((prev) => ({
        ...prev!,
        status: "failed",
        progress: { ...prev!.progress, error: data.error },
      }));
      toast.error(`فشل الاستيراد: ${data.error}`);
    });

    return () => {
      socketRef.current?.disconnect();
    };
  }, []); // Logic simplified for hook context

  const loadActiveJobs = async () => {
    try {
      const response = await fetch("/api/v1/import-jobs/list", {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success && data.data) {
        // Find running job or most recent one
        const runningJob = data.data.find(
          (j: any) => j.status === "running" || j.status === "pending",
        );
        if (runningJob) {
          setActiveJob(runningJob);
        } else if (data.data.length > 0) {
          // Optionally show last completed job? For now just null if no running job
          // setActiveJob(data.data[0]);
        }
      }
    } catch (error) {
      console.error("Error loading active jobs", error);
    }
  };

  const fetchOrdersCount = async () => {
    if (!settings?.hasCredentials) {
      toast.error("يرجى إعداد بيانات الاتصال أولاً");
      return;
    }

    setCountingOrders(true);
    try {
      const response = await fetch("/api/v1/woocommerce/orders/count", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settings.id,
          status:
            importOptions.status !== "any" ? importOptions.status : undefined,
          after: importOptions.dateFrom || undefined,
          before: importOptions.dateTo || undefined,
        }),
      });

      const data = await response.json();
      if (data.success) {
        setTotalOrdersCount(data.data.count);
        toast.success(`إجمالي الطلبات: ${data.data.count}`);
      }
    } catch (error) {
      console.error("Error counting orders:", error);
      toast.error("فشل في جلب عدد الطلبات");
    } finally {
      setCountingOrders(false);
    }
  };

  const fetchWooOrders = async () => {
    if (!settings?.hasCredentials) return;

    setLoading(true);
    setWooOrders([]);
    try {
      const response = await fetch("/api/v1/woocommerce/orders/fetch", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settings.id,
          limit:
            importOptions.limit === "all" ? 20 : parseInt(importOptions.limit),
          status:
            importOptions.status !== "any" ? importOptions.status : undefined,
          after: importOptions.dateFrom || undefined,
          before: importOptions.dateTo || undefined,
        }),
      });

      const data = await response.json();
      if (data.success) {
        setWooOrders(data.data.orders);
        toast.success(`تم جلب ${data.data.orders.length} طلب للمراجعة`);
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("خطأ في جلب الطلبات");
    } finally {
      setLoading(false);
    }
  };

  const startBackendImport = async () => {
    setImporting(true);
    try {
      const response = await fetch("/api/v1/import-jobs/start", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settings?.id,
          type: "orders",
          limit:
            importOptions.limit === "all" ? 0 : parseInt(importOptions.limit),
          batchSize: parseInt(importOptions.batchSize),
          status: importOptions.status,
          dateFrom: importOptions.dateFrom,
          dateTo: importOptions.dateTo,
          duplicateAction: importOptions.duplicateAction,
        }),
      });
      const data = await response.json();
      if (data.success) {
        setActiveJob(data.data);
        toast.success("🚀 تم بدء الاستيراد في الخلفية");
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("فشل بدء الاستيراد");
    } finally {
      setImporting(false);
    }
  };

  const pauseBackendImport = async () => {
    if (!activeJob) return;
    try {
      await fetch(`/api/v1/import-jobs/pause/${activeJob.jobId}`, {
        method: "POST",
        headers: getAuthHeaders(),
      });
      toast.success("تم إرسال طلب الإيقاف المؤقت");
    } catch (e) {
      toast.error("فشل الإيقاف");
    }
  };

  const resumeBackendImport = async () => {
    if (!activeJob) return;
    try {
      await fetch(`/api/v1/import-jobs/resume/${activeJob.jobId}`, {
        method: "POST",
        headers: getAuthHeaders(),
      });
      toast.success("تم استئناف الاستيراد");
    } catch (e) {
      toast.error("فشل الاستئناف");
    }
  };

  const cancelBackendImport = async () => {
    if (!activeJob) return;
    try {
      await fetch(`/api/v1/import-jobs/cancel/${activeJob.jobId}`, {
        method: "POST",
        headers: getAuthHeaders(),
      });
      toast.success("تم إلغاء المهمة");
      setActiveJob(null);
    } catch (e) {
      toast.error("فشل الإلغاء");
    }
  };

  const importSelectedOrders = async () => {
    if (selectedWooOrders.size === 0) return;

    setImporting(true);
    try {
      const ordersToImport = wooOrders.filter((o) =>
        selectedWooOrders.has(o.wooCommerceId),
      );

      const response = await fetch("/api/v1/woocommerce/orders/import", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settings?.id,
          orders: ordersToImport,
          duplicateAction: importOptions.duplicateAction,
        }),
      });

      const data = await response.json();
      if (data.success) {
        toast.success(`تم استيراد ${data.data.imported} طلب بنجاح`);
        setSelectedWooOrders(new Set());
        // Remove imported orders from review list
        setWooOrders((prev) =>
          prev.filter((o) => !selectedWooOrders.has(o.wooCommerceId)),
        );
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("خطأ في استيراد الطلبات");
    } finally {
      setImporting(false);
    }
  };

  return {
    loading,
    importing,
    wooOrders,
    setWooOrders,
    activeJob,
    setActiveJob,
    totalOrdersCount,
    countingOrders,
    selectedWooOrders,
    setSelectedWooOrders,
    resumeState,
    loadActiveJobs,
    fetchOrdersCount,
    fetchWooOrders,
    startBackendImport,
    pauseBackendImport,
    resumeBackendImport,
    cancelBackendImport,
    importSelectedOrders,
    showImportOptions,
    setShowImportOptions,
    importOptions,
    setImportOptions,
  };
};

import { useState } from "react";
import toast from "react-hot-toast";
import { WooProduct, Settings } from "../types";
import tokenManager from "../../../utils/tokenManager";

export const useWooCommerceProducts = (settings: Settings | null) => {
  const [wooProducts, setWooProducts] = useState<WooProduct[]>([]);
  const [selectedWooProducts, setSelectedWooProducts] = useState<Set<string>>(
    new Set(),
  );
  const [importingProducts, setImportingProducts] = useState(false);
  const [fetchingProducts, setFetchingProducts] = useState(false);

  // Variants State
  const [selectedVariants, setSelectedVariants] = useState<
    Map<string, Set<string>>
  >(new Map());
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);
  const [variantFilter, setVariantFilter] = useState<
    "all" | "color" | "size" | "composite"
  >("all");
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);

  const fetchWooProducts = async () => {
    if (!settings?.hasCredentials) {
      toast.error("يرجى إعداد بيانات الاتصال أولاً");
      return;
    }

    setFetchingProducts(true);
    setWooProducts([]);
    try {
      const response = await fetch("/api/v1/woocommerce/fetch-products", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settings.id,
          storeUrl: settings.storeUrl,
          // Note: consumerKey/Secret are handled by backend controller if cached
        }),
      });

      const data = await response.json();
      if (data.success) {
        setWooProducts(data.data.products);
        toast.success(`تم جلب ${data.data.products.length} منتج`);
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("خطأ في جلب المنتجات");
    } finally {
      setFetchingProducts(false);
    }
  };

  const importSelectedProducts = async () => {
    if (selectedWooProducts.size === 0) return;

    setImportingProducts(true);
    try {
      const productsToImport = wooProducts
        .filter((p) => selectedWooProducts.has(p.wooCommerceId))
        .map((p) => {
          // Include selected variants only
          const selectedVars = selectedVariants.get(p.wooCommerceId);
          if (p.variations && selectedVars && selectedVars.size > 0) {
            return {
              ...p,
              variations: p.variations.filter((v) =>
                selectedVars.has(v.wooCommerceVariationId),
              ),
            };
          }
          return p;
        });

      const response = await fetch("/api/v1/woocommerce/import-selected", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({ products: productsToImport }),
      });

      const data = await response.json();
      if (data.success) {
        toast.success(
          `تم استيراد ${data.data.imported} منتج، وتحديث ${data.data.updated}`,
        );
        setSelectedWooProducts(new Set());
        setSelectedVariants(new Map());
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("خطأ في استيراد المنتجات");
    } finally {
      setImportingProducts(false);
    }
  };

  // Helper functions for variants (same logic as before)
  const toggleVariantSelection = (productId: string, variationId: string) => {
    const newSelected = new Map(selectedVariants);
    const productVariants = newSelected.get(productId) || new Set();

    if (productVariants.has(variationId)) {
      productVariants.delete(variationId);
    } else {
      productVariants.add(variationId);
    }

    if (productVariants.size === 0) {
      newSelected.delete(productId);

      // Also uncheck the main product if no variants are selected
      const newSelectedProducts = new Set(selectedWooProducts);
      newSelectedProducts.delete(productId);
      setSelectedWooProducts(newSelectedProducts);
    } else {
      newSelected.set(productId, productVariants);

      // Auto check main product
      const newSelectedProducts = new Set(selectedWooProducts);
      newSelectedProducts.add(productId);
      setSelectedWooProducts(newSelectedProducts);
    }

    setSelectedVariants(newSelected);
  };

  const selectAllVariantsForProduct = (productId: string) => {
    const product = wooProducts.find((p) => p.wooCommerceId === productId);
    if (!product || !product.variations) return;

    const newSelected = new Map(selectedVariants);
    const variantIds = new Set(
      product.variations.map((v) => v.wooCommerceVariationId),
    );
    newSelected.set(productId, variantIds);
    setSelectedVariants(newSelected);

    const newSelectedProducts = new Set(selectedWooProducts);
    newSelectedProducts.add(productId);
    setSelectedWooProducts(newSelectedProducts);
  };

  const deselectAllVariantsForProduct = (productId: string) => {
    const newSelected = new Map(selectedVariants);
    newSelected.delete(productId);
    setSelectedVariants(newSelected);
  };

  const groupVariantsByType = (variations: any[]) => {
    const types: Record<string, boolean> = {
      color: false,
      size: false,
      other: false,
    };
    variations.forEach((v) => {
      v.attributes.forEach((attr: any) => {
        if (attr.type === "color") types["color"] = true;
        else if (attr.type === "size") types["size"] = true;
        else types["other"] = true;
      });
    });
    return types;
  };

  const selectVariantsByType = (productId: string, type: "color" | "size") => {
    const product = wooProducts.find((p) => p.wooCommerceId === productId);
    if (!product || !product.variations) return;

    const newSelected = new Map(selectedVariants);
    const productVariants = newSelected.get(productId) || new Set();

    product.variations.forEach((v) => {
      const hasType = v.attributes.some((attr: any) => attr.type === type);
      if (hasType) productVariants.add(v.wooCommerceVariationId);
    });

    newSelected.set(productId, productVariants);
    setSelectedVariants(newSelected);

    const newSelectedProducts = new Set(selectedWooProducts);
    newSelectedProducts.add(productId);
    setSelectedWooProducts(newSelectedProducts);
  };

  return {
    wooProducts,
    fetchingProducts,
    importingProducts,
    selectedWooProducts,
    setSelectedWooProducts,
    selectedVariants,
    setSelectedVariants,
    expandedProduct,
    setExpandedProduct,
    variantFilter,
    setVariantFilter,
    fetchWooProducts,
    importSelectedProducts,
    toggleVariantSelection,
    selectAllVariantsForProduct,
    deselectAllVariantsForProduct,
    groupVariantsByType,
    selectVariantsByType,
  };
};

import { useState, useCallback } from "react";
import toast from "react-hot-toast";
import { Settings } from "../types";
import tokenManager from "../../../utils/tokenManager";

export const useWooCommerceSettings = () => {
  const [loading, setLoading] = useState(false);
  const [testingConnection, setTestingConnection] = useState(false);
  const [settingsList, setSettingsList] = useState<Settings[]>([]);
  const [selectedSettingsId, setSelectedSettingsId] = useState<string | null>(
    null,
  );
  const [settingsForm, setSettingsForm] = useState({
    id: "",
    storeUrl: "",
    consumerKey: "",
    consumerSecret: "",
    syncEnabled: false,
    syncDirection: "both",
    syncInterval: 15,
    autoImport: false,
    autoExport: false,
    webhookEnabled: false,
    webhookSecret: "",
    statusMapping: {} as Record<string, string>,
  });

  // Ngrok URL state (for local development webhooks)
  const [ngrokUrl, setNgrokUrl] = useState(() => {
    return localStorage.getItem("woocommerce_ngrok_url") || "";
  });
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);

  const loadSettings = useCallback(async () => {
    try {
      const response = await fetch("/api/v1/woocommerce/settings", {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success && data.data) {
        const list = Array.isArray(data.data) ? data.data : [data.data];
        setSettingsList(list);

        // If we have items and none selected, select first
        if (list.length > 0 && !selectedSettingsId) {
          const first = list[0];
          setSelectedSettingsId(first.id);
          setSettingsForm({
            id: first.id,
            storeUrl: first.storeUrl,
            consumerKey: "",
            consumerSecret: "",
            syncEnabled: first.syncEnabled,
            syncDirection: first.syncDirection,
            syncInterval: first.syncInterval,
            autoImport:
              first.syncDirection === "import_only" ||
              first.syncDirection === "both",
            autoExport:
              first.syncDirection === "export_only" ||
              first.syncDirection === "both",
            webhookEnabled: first.webhookEnabled,
            webhookSecret: first.webhookSecret || "",
            statusMapping: first.statusMapping || {},
          });
        }
      } else {
        setSettingsList([]);
      }
    } catch (error) {
      console.error("Error fetching settings:", error);
      toast.error("فشل جلب الإعدادات");
    }
  }, []);

  const handleSelectSite = useCallback(
    (id: string | null) => {
      setSelectedSettingsId(id);
      if (id === "new") {
        setSettingsForm({
          id: "",
          storeUrl: "",
          consumerKey: "",
          consumerSecret: "",
          syncEnabled: false,
          syncDirection: "both",
          syncInterval: 15,
          autoImport: false,
          autoExport: false,
          webhookEnabled: false,
          webhookSecret: "",
          statusMapping: {},
        });
      } else if (id) {
        const s = settingsList.find((item) => item.id === id);
        if (s) {
          setSettingsForm({
            id: s.id,
            storeUrl: s.storeUrl,
            consumerKey: "",
            consumerSecret: "",
            syncEnabled: s.syncEnabled,
            syncDirection: s.syncDirection,
            syncInterval: s.syncInterval,
            autoImport:
              s.syncDirection === "import_only" || s.syncDirection === "both",
            autoExport:
              s.syncDirection === "export_only" || s.syncDirection === "both",
            webhookEnabled: s.webhookEnabled,
            webhookSecret: s.webhookSecret || "",
            statusMapping: s.statusMapping || {},
          });
        }
      }
    },
    [settingsList],
  );

  const saveSettings = async () => {
    // Check required fields (allow empty keys if present in system)
    const currentSite = settingsList.find((s) => s.id === settingsForm.id);
    const hasKeys =
      currentSite?.hasCredentials ||
      (settingsForm.consumerKey && settingsForm.consumerSecret);

    if (!settingsForm.storeUrl || !hasKeys) {
      toast.error("جميع بيانات الاتصال مطلوبة");
      return;
    }

    setLoading(true);
    try {
      const response = await fetch("/api/v1/woocommerce/settings", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(settingsForm),
      });

      const data = await response.json();
      if (data.success) {
        toast.success("تم حفظ الإعدادات بنجاح");
        loadSettings();
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("خطأ في حفظ الإعدادات");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const testConnection = async () => {
    const currentSite = settingsList.find((s) => s.id === settingsForm.id);
    const useStoredCredentials =
      !!settingsForm.id &&
      !!currentSite?.hasCredentials &&
      !settingsForm.consumerKey &&
      !settingsForm.consumerSecret;

    if (
      !settingsForm.storeUrl ||
      (!useStoredCredentials &&
        (!settingsForm.consumerKey || !settingsForm.consumerSecret))
    ) {
      toast.error("يرجى ملء جميع الحقول أولاً");
      return;
    }

    setTestingConnection(true);
    try {
      const response = await fetch("/api/v1/woocommerce/fetch-products", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settingsForm.id || undefined,
          storeUrl: settingsForm.storeUrl,
          consumerKey: useStoredCredentials
            ? "from_settings"
            : settingsForm.consumerKey,
          consumerSecret: useStoredCredentials
            ? "from_settings"
            : settingsForm.consumerSecret,
        }),
      });

      const data = await response.json();
      if (data.success) {
        toast.success(`✅ الاتصال ناجح! تم العثور على ${data.data.count} منتج`);
      } else {
        toast.error(`❌ فشل الاتصال: ${data.message}`);
      }
    } catch (error: any) {
      toast.error("❌ خطأ في اختبار الاتصال");
    } finally {
      setTestingConnection(false);
    }
  };

  const setupWebhooks = async (customNgrokUrl?: string) => {
    const urlToUse = customNgrokUrl || ngrokUrl;

    if (!settingsForm.id) {
      toast.error("احفظ إعدادات المتجر أولاً قبل تثبيت Webhooks");
      return;
    }

    // Check for ngrok on localhost
    if (window.location.hostname === "localhost" && !urlToUse) {
      toast.error("يرجى إدخال ngrok URL للاختبار على localhost");
      return;
    }

    if (urlToUse) {
      localStorage.setItem("woocommerce_ngrok_url", urlToUse);
      setNgrokUrl(urlToUse);
    }

    setLoading(true);
    try {
      const response = await fetch("/api/v1/woocommerce/webhooks/setup", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settingsForm.id,
          ngrokUrl: urlToUse || undefined,
        }),
      });

      const data = await response.json();
      if (data.success) {
        toast.success(data.message);
        if (data.data?.webhookUrl) {
          toast.success(`Webhook URL: ${data.data.webhookUrl}`, {
            duration: 5000,
          });
        }
        loadSettings();
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("خطأ في إعداد Webhooks");
    } finally {
      setLoading(false);
    }
  };

  const disconnectSettings = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من رغبتك في الغاء الربط لهذا الموقع؟"))
      return;

    setLoading(true);
    try {
      const response = await fetch(`/api/v1/woocommerce/settings/${id}`, {
        method: "DELETE",
        headers: getAuthHeaders(),
      });

      const data = await response.json();
      if (data.success) {
        toast.success("تم الغاء الربط بنجاح");
        if (selectedSettingsId === id) setSelectedSettingsId(null);
        loadSettings();
      } else {
        toast.error(data.message);
      }
    } catch (error: any) {
      toast.error("خطأ في الغاء الربط");
    } finally {
      setLoading(false);
    }
  };

  const resetWooCommerceData = async (options: {
    resetOrders: boolean;
    resetProducts: boolean;
    resetLogs: boolean;
    resetSettings: boolean;
  }) => {
    setLoading(true);
    try {
      const response = await fetch("/api/v1/woocommerce/reset", {
        method: "POST",
        headers: getAuthHeaders({
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: settingsForm.id || undefined,
          ...options,
        }),
      });

      const data = await response.json();
      if (data.success) {
        toast.success(data.message);
        loadSettings();
      } else {
        toast.error(data.message);
      }
      return data;
    } catch (error) {
      console.error("Reset error:", error);
      toast.error("فشل عملية إعادة الضبط");
      return { success: false };
    } finally {
      setLoading(false);
    }
  };

  return {
    loading,
    testingConnection,
    settingsList,
    selectedSettingsId,
    setSelectedSettingsId: handleSelectSite,
    settingsForm,
    setSettingsForm,
    ngrokUrl,
    setNgrokUrl,
    loadSettings,
    saveSettings,
    testConnection,
    setupWebhooks,
    disconnectSettings,
    resetWooCommerceData,
  };
};

import { useState, useCallback } from "react";
import toast from "react-hot-toast";
import { FetchedStatus, Settings } from "../types";
import tokenManager from "../../../utils/tokenManager";

export const useWooCommerceStatus = (
  settings: Settings | null,
  settingsForm: any,
  setSettingsForm: React.Dispatch<React.SetStateAction<any>>,
) => {
  const [wooStatuses, setWooStatuses] = useState<FetchedStatus[]>([]);
  const [fetchingStatuses, setFetchingStatuses] = useState(false);
  const [statusSearch, setStatusSearch] = useState("");

  // Hardcoded fallback statuses while loading from API
  const [localStatuses, setLocalStatuses] = useState<
    { value: string; label: string }[]
  >([
    { value: "PENDING", label: "معلق (Pending)" },
    { value: "CONFIRMED", label: "مؤكد (Confirmed)" },
    { value: "PROCESSING", label: "قيد التجهيز (Processing)" },
    { value: "SHIPPED", label: "تم الشحن (Shipped)" },
    { value: "DELIVERED", label: "تم التوصيل (Delivered)" },
    { value: "CANCELLED", label: "ملغي (Cancelled)" },
    { value: "REFUNDED", label: "مسترجع (Refunded)" },
  ]);
  const getAuthHeaders = (additionalHeaders: Record<string, string> = {}) =>
    tokenManager.createAuthHeaders(additionalHeaders);

  const defaultStatusMapping = {
    pending: "PENDING",
    processing: "PROCESSING",
    "on-hold": "PENDING",
    completed: "DELIVERED",
    cancelled: "CANCELLED",
    refunded: "CANCELLED",
    failed: "CANCELLED",
    trash: "CANCELLED",
  };

  const fetchLocalStatuses = useCallback(async () => {
    try {
      const types = ["order", "payment", "shipping", "preparation"];
      const responses = await Promise.all(
        types.map((type) =>
          fetch(`/api/v1/order-status?type=${type}`, {
            headers: getAuthHeaders(),
          }).then((res) => res.json()),
        ),
      );

      let allLocalStatuses: { value: string; label: string }[] = [];
      const typeLabels: Record<string, string> = {
        order: "طلب",
        payment: "دفع",
        shipping: "شحن",
        preparation: "تجهيز",
      };

      responses.forEach((res, index) => {
        if (res.success && res.data) {
          const type = types[index];
          const typeLabel = typeLabels[type] || type;

          const mapped = res.data.map((s: any) => ({
            value: s.code,
            label: `[${typeLabel}] ${s.name} (${s.nameEn || s.code})`,
          }));
          allLocalStatuses = [...allLocalStatuses, ...mapped];
        }
      });

      if (allLocalStatuses.length > 0) {
        // Remove duplicates if any status code exists in multiple types
        const uniqueStatuses = Array.from(
          new Map(allLocalStatuses.map((s) => [s.value, s])).values(),
        );
        setLocalStatuses(uniqueStatuses);
      }
    } catch (error) {
      console.error("Error fetching local statuses:", error);
    }
  }, []);

  const fetchWooStatuses = async () => {
    if (!settings?.hasCredentials) {
      toast.error("يرجى إعداد بيانات الاتصال أولاً");
      return;
    }

    setFetchingStatuses(true);
    try {
      const query = settings?.id
        ? `?id=${encodeURIComponent(settings.id)}`
        : "";
      const response = await fetch(`/api/v1/woocommerce/orders/statuses${query}`, {
        headers: getAuthHeaders(),
      });
      const data = await response.json();
      if (data.success) {
        setWooStatuses(data.data);
        toast.success(`تم جلب ${data.data.length} حالة من المتجر`);
      } else {
        toast.error("فشل جلب الحالات");
      }
    } catch (error) {
      toast.error("خطأ في الاتصال");
    } finally {
      setFetchingStatuses(false);
    }
  };

  const autoMapStatuses = () => {
    const newMapping = { ...settingsForm.statusMapping };

    wooStatuses.forEach((status) => {
      if (!newMapping[status.slug]) {
        const lowerName = (status.name || "").toLowerCase();
        const lowerSlug = status.slug.toLowerCase();

        if (
          lowerName.includes("complet") ||
          lowerName.includes("deliver") ||
          lowerName.includes("success") ||
          lowerSlug.includes("complet") ||
          lowerSlug.includes("deliver") ||
          lowerSlug.includes("success")
        ) {
          newMapping[status.slug] = "DELIVERED";
        } else if (
          lowerName.includes("process") ||
          lowerName.includes("confirm") ||
          lowerName.includes("prepar") ||
          lowerSlug.includes("process") ||
          lowerSlug.includes("confirm") ||
          lowerSlug.includes("prepar")
        ) {
          newMapping[status.slug] = "PROCESSING";
        } else if (
          lowerName.includes("cancel") ||
          lowerName.includes("refund") ||
          lowerName.includes("reject") ||
          lowerSlug.includes("cancel") ||
          lowerSlug.includes("refund") ||
          lowerSlug.includes("reject")
        ) {
          newMapping[status.slug] = "CANCELLED";
        } else if (
          lowerName.includes("hold") ||
          lowerName.includes("wait") ||
          lowerName.includes("pend") ||
          lowerSlug.includes("hold") ||
          lowerSlug.includes("wait") ||
          lowerSlug.includes("pend")
        ) {
          newMapping[status.slug] = "PENDING";
        } else if (
          lowerName.includes("ship") ||
          lowerName.includes("dispatch") ||
          lowerName.includes("rout") ||
          lowerSlug.includes("ship") ||
          lowerSlug.includes("dispatch") ||
          lowerSlug.includes("rout")
        ) {
          newMapping[status.slug] = "SHIPPED";
        }
      }
    });

    setSettingsForm((prev: any) => ({ ...prev, statusMapping: newMapping }));
    toast.success("🤖 تمت محاولة الربط التلقائي بنجاح");
  };

  return {
    wooStatuses,
    fetchingStatuses,
    localStatuses,
    statusSearch,
    setStatusSearch,
    fetchLocalStatuses,
    fetchWooStatuses,
    autoMapStatuses,
    defaultStatusMapping,
  };
};

