import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import {
  storefrontSettingsService,
  type StorefrontSettings,
} from "../services/storefrontSettingsService";

type StorefrontSettingsContextValue = {
  settings: StorefrontSettings | null;
  loading: boolean;
  saving: boolean;
  updateSetting: (key: keyof StorefrontSettings | string, value: any) => void;
  handleSave: () => Promise<void>;
  handleReset: () => Promise<void>;
  reload: () => Promise<void>;
};

const StorefrontSettingsContext =
  createContext<StorefrontSettingsContextValue | null>(null);

const useStorefrontSettingsController = (): StorefrontSettingsContextValue => {
  const [settings, setSettings] = useState<StorefrontSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const reload = async () => {
    try {
      setLoading(true);
      const response = await storefrontSettingsService.getSettings();
      setSettings(response?.data || null);
    } catch {
      setSettings(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void reload();
  }, []);

  const updateSetting = (key: keyof StorefrontSettings | string, value: any) => {
    setSettings((current) => ({
      ...(current || ({} as StorefrontSettings)),
      [key]: value,
    }));
  };

  const handleSave = async () => {
    if (!settings) return;
    try {
      setSaving(true);
      const response = await storefrontSettingsService.updateSettings(settings);
      setSettings(response?.data || settings);
    } finally {
      setSaving(false);
    }
  };

  const handleReset = async () => {
    try {
      setSaving(true);
      const response = await storefrontSettingsService.resetSettings();
      setSettings(response?.data || null);
    } finally {
      setSaving(false);
    }
  };

  return useMemo(
    () => ({
      settings,
      loading,
      saving,
      updateSetting,
      handleSave,
      handleReset,
      reload,
    }),
    [loading, saving, settings],
  );
};

export const StorefrontSettingsProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const value = useStorefrontSettingsController();
  return (
    <StorefrontSettingsContext.Provider value={value}>
      {children}
    </StorefrontSettingsContext.Provider>
  );
};

export const useStorefrontSettings = (): StorefrontSettingsContextValue => {
  const context = useContext(StorefrontSettingsContext);
  const fallback = useStorefrontSettingsController();
  return context || fallback;
};

export default StorefrontSettingsProvider;

import { apiClient } from "./apiClient";
import { tokenManager } from "../utils/tokenManager";

/**
 * Analytics Service
 * Handles store visit tracking, conversion events, and analytics reporting
 * Uses standardized apiClient for all requests
 */

class AnalyticsService {
  private sessionId: string;
  private readonly publicRequestConfig = {
    _skipAuthHeader: true,
    _skipAuthRefresh: true,
    _skipErrorToast: true,
  } as const;

  constructor() {
    this.sessionId = this.getOrCreateSessionId();
  }

  private getSessionId(): string {
    this.sessionId = this.getOrCreateSessionId();
    return this.sessionId;
  }

  private readStorage(
    storage: "localStorage" | "sessionStorage",
    key: string,
  ): string | null {
    try {
      return window[storage].getItem(key);
    } catch {
      return null;
    }
  }

  private writeStorage(
    storage: "localStorage" | "sessionStorage",
    key: string,
    value: string,
  ) {
    try {
      window[storage].setItem(key, value);
    } catch {
      // Ignore storage failures in restricted browser contexts.
    }
  }

  private hasTrackedKey(
    storage: "localStorage" | "sessionStorage",
    key: string,
  ): boolean {
    return this.readStorage(storage, key) === "1";
  }

  private markTracked(
    storage: "localStorage" | "sessionStorage",
    key: string,
  ) {
    this.writeStorage(storage, key, "1");
  }

  private buildDedupeKey(...parts: Array<string | number | null | undefined>) {
    return parts
      .map((part) => String(part ?? "").trim())
      .filter(Boolean)
      .join(":");
  }

  private getOrCreateSessionId(): string {
    const SESSION_DURATION = 30 * 60 * 1000; // 30 minutes
    const now = Date.now();

    // Try to get existing session from localStorage
    const storedSession = localStorage.getItem("analytics_session");

    if (storedSession) {
      try {
        const { sessionId, expiresAt } = JSON.parse(storedSession);

        // Check if session is still valid
        if (expiresAt > now) {
          // Extend session on activity
          localStorage.setItem(
            "analytics_session",
            JSON.stringify({
              sessionId,
              expiresAt: now + SESSION_DURATION,
            }),
          );
          return sessionId;
        }
      } catch (e) {
        console.error("Error parsing stored session:", e);
      }
    }

    // Create new session
    const sessionId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    localStorage.setItem(
      "analytics_session",
      JSON.stringify({
        sessionId,
        expiresAt: now + SESSION_DURATION,
      }),
    );

    return sessionId;
  }

  private getCompanyId(): string | null {
    const companyIdFromQuery = new URLSearchParams(window.location.search).get(
      "companyId",
    );
    if (companyIdFromQuery) {
      return companyIdFromQuery;
    }

    // أولاً: جرب storefront_companyId (للـ Storefront - نفس المفتاح المستخدم في storefrontApi)
    const storefrontCompanyId = localStorage.getItem("storefront_companyId");

    if (storefrontCompanyId) {
      return storefrontCompanyId;
    }

    const sessionCompanyId = sessionStorage.getItem("currentCompanyId");
    if (sessionCompanyId) {
      return sessionCompanyId;
    }

    const directCompanyId =
      localStorage.getItem("currentCompanyId") ||
      localStorage.getItem("companyId");
    if (directCompanyId) {
      return directCompanyId;
    }

    // ثانياً: جرب company object (للـ Admin Dashboard)
    const storedCompany = localStorage.getItem("company");
    if (storedCompany) {
      try {
        const company = JSON.parse(storedCompany);
        if (company?.id) {
          return company.id;
        }
      } catch (e) {
        console.error("Error parsing company from localStorage:", e);
      }
    }

    // ثالثاً: جرب user object لأن معظم الشاشات الإدارية تحفظ companyId بداخله
    const storedUser = localStorage.getItem("user");
    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        const nestedCompanyId =
          user?.companyId ||
          user?.company?.id ||
          user?.currentCompanyId ||
          user?.effectiveCompanyId ||
          null;

        if (nestedCompanyId) {
          return nestedCompanyId;
        }
      } catch (e) {
        console.error("Error parsing user from localStorage:", e);
      }
    }

    console.warn("⚠️ [Analytics] No companyId found in localStorage");
    return null;
  }

  async trackStoreVisit(landingPage?: string) {
    try {
      const companyId = this.getCompanyId();
      if (!companyId) {
        console.warn(
          "📊 [Analytics] No companyId found, skipping store visit tracking",
        );
        return;
      }

      const sessionId = this.getSessionId();
      const dedupeKey = this.buildDedupeKey(
        "analytics_store_visit",
        companyId,
        sessionId,
      );
      if (this.hasTrackedKey("sessionStorage", dedupeKey)) {
        return dedupeKey;
      }

      console.log("📊 [Analytics] Tracking store visit...", {
        companyId,
        landingPage,
      });

      await apiClient.post(
        "/analytics/track/store-visit",
        {
          sessionId,
          ipAddress: null, // يمكن إضافة IP من الـ backend
          userAgent: navigator.userAgent,
          referrer: document.referrer || null,
