class BroadcastService {
  private async makeRequest(endpoint: string, options: RequestInit = {}) {
    const token = authService.getAccessToken();

    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
        ...options.headers,
      },
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(
        errorData.message || `HTTP error! status: ${response.status}`,
      );
    }

    return response.json();
  }

  // Campaign methods
  async createCampaign(campaignData: FormData): Promise<Campaign> {
    const token = authService.getAccessToken();

    // 🚀 Create AbortController with 60 second timeout for campaign creation
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 60000); // 60 seconds

    try {
      const response = await fetch(`${API_BASE_URL}/broadcast/campaigns`, {
        method: "POST",
        body: campaignData,
        headers: {
          Authorization: `Bearer ${token}`,
          // لا تضع Content-Type هنا، المتصفح يحددها تلقائياً مع FormData
        },
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          errorData.message || `HTTP error! status: ${response.status}`,
        );
      }

      return response.json();
    } catch (error: any) {
      clearTimeout(timeoutId);
      if (error.name === "AbortError") {
        throw new Error(
          "انتهت مهلة الطلب. قد تكون الحملة قيد الإرسال في الخلفية.",
        );
      }
      throw error;
    }
  }

  async getCampaigns(
    filters?: any,
    pagination?: any,
  ): Promise<{
    campaigns: Campaign[];
    pagination: {
      page: number;
      limit: number;
      total: number;
      totalPages: number;
    };
  }> {
    const params = new URLSearchParams();

    if (filters) {
      Object.keys(filters).forEach((key) => {
        if (filters[key] !== undefined && filters[key] !== null) {
          params.append(key, filters[key]);
        }
      });
    }

    if (pagination) {
      if (pagination.page) params.append("page", pagination.page.toString());
      if (pagination.limit) params.append("limit", pagination.limit.toString());
    }

    const queryString = params.toString();
    const endpoint = `/broadcast/campaigns${queryString ? `?${queryString}` : ""}`;

    return this.makeRequest(endpoint);
  }

  async getCampaign(campaignId: string): Promise<Campaign> {
    return this.makeRequest(`/broadcast/campaigns/${campaignId}`);
  }

  async updateCampaign(
    campaignId: string,
    updateData: Partial<CampaignData>,
  ): Promise<Campaign> {
    return this.makeRequest(`/broadcast/campaigns/${campaignId}`, {
      method: "PUT",
      body: JSON.stringify(updateData),
    });
  }

