      if (options?.metadata)
        formData.append("metadata", JSON.stringify(options.metadata));

      // إضافة الصور
      images.forEach((image) => {
        formData.append("images", image);
      });

      const token = this.getAuthToken();
      const headers: HeadersInit = {};
      if (token) {
        headers["Authorization"] = `Bearer ${token}`;
