const MARKETPLACE_PREVIEW_CART_SEED_PREFIX =
  "sf-marketplace-preview-cart-seeded";

const serializeMarketplacePreviewCartItems = (
  items: ReturnType<typeof getMarketplacePreviewCartItems>,
) =>
  items
    .map((item) =>
      [
        item.id,
        item.productId,
        item.variantId || "",
        item.imageUrl || "",
        item.price,
        item.basePrice ?? item.price,
        item.quantity,
        JSON.stringify(item.attributes || {}),
      ].join("::"),
    )
    .join("||");

const MarketplacePreviewCartBootstrap: React.FC = () => {
  const previewThemeId = resolveMarketplacePreviewThemeId();

  useEffect(() => {
    const persistApi = useCartStore.persist;
    if (!persistApi) {
      return;
    }

    const targetStorageName = previewThemeId
      ? getStorefrontPreviewCartStorageName(previewThemeId)
      : DEFAULT_STOREFRONT_CART_STORAGE_NAME;

    if (persistApi.getOptions().name === targetStorageName) {
      return;
    }

    useCartStore.setState({ items: [], isOpen: false });
    persistApi.setOptions({ name: targetStorageName });
    void persistApi.rehydrate();
  }, [previewThemeId]);

  useEffect(() => {
    if (!previewThemeId) {
      return;
    }

    const previewItems = getMarketplacePreviewCartItems(previewThemeId);
    if (previewItems.length === 0) {
      return;
    }

    const seedKey = `${MARKETPLACE_PREVIEW_CART_SEED_PREFIX}:${previewThemeId}`;
    const seedSignature = serializeMarketplacePreviewCartItems(previewItems);
    if (
      typeof window !== "undefined" &&
      window.sessionStorage.getItem(seedKey) === seedSignature
    ) {
      return;
    }

    useCartStore.setState({ items: previewItems, isOpen: false });
    if (typeof window !== "undefined") {
      window.sessionStorage.setItem(seedKey, seedSignature);
    }
  }, [previewThemeId]);

  return null;
};

