import React from "react";
import toast from "react-hot-toast";
import { storefrontFetch } from "../../utils/storefrontApi";
import { cn as cx } from "../../lib/utils";
import { useStorefrontTheme } from "../engine/ThemeProvider";

interface BackInStockSignupCardProps {
  productId: string;
  productName?: string;
  title?: string;
  description?: string;
  successMessage?: string;
  buttonLabel?: string;
  variant?: "panel" | "inline" | "accent";
  className?: string;
}

const inputClassName =
  "w-full rounded-xl border border-border/60 bg-background/50 px-3.5 py-2.5 text-sm text-foreground outline-none transition duration-300 placeholder:text-muted-foreground/50 focus:border-primary/40 focus:bg-background focus:ring-4 focus:ring-primary/5";

const BackInStockSignupCard: React.FC<BackInStockSignupCardProps> = ({
  productId,
  productName,
  title,
  description,
  successMessage,
  buttonLabel,
  variant = "panel",
  className = "",
}) => {
  const { theme } = useStorefrontTheme();
  const isRTL = theme.direction === "rtl";
  const resolvedTitle =
    title || (isRTL ? "نبّهيني عند عودة المقاس" : "Notify me when it's back");
  const resolvedDescription =
    description ||
    (isRTL
      ? "اكتبي اسمك مع البريد أو رقم الهاتف، وسنرسل لك تنبيهًا بمجرد عودة هذا الموديل أو المقاس."
      : "Leave your name plus email or phone and we'll let you know once this item returns.");
  const resolvedSuccessMessage =
    successMessage ||
    (isRTL
      ? "تم تسجيل طلب التنبيه. سنخبرك فور عودة هذا الموديل للمخزون."
      : "You're on the waitlist. We'll let you know when this product is back in stock.");
  const resolvedButtonLabel =
    buttonLabel || (isRTL ? "سجّليني في التنبيه" : "Join waitlist");
  const [form, setForm] = React.useState({
    customerName: "",
    customerEmail: "",
    customerPhone: "",
  });
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [isSubmitted, setIsSubmitted] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const updateField = (
    field: "customerName" | "customerEmail" | "customerPhone",
    value: string,
  ) => {
    setForm((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const customerName = form.customerName.trim();
    const customerEmail = form.customerEmail.trim();
    const customerPhone = form.customerPhone.trim();

    if (!customerName) {
      const message = isRTL
        ? "اكتبي اسمك حتى نقدر نحفظ طلب التنبيه."
        : "Add your name so we can save this alert.";
      setError(message);
      toast.error(message);
      return;
    }

    if (!customerEmail && !customerPhone) {
      const message = isRTL
        ? "أضيفي بريدًا إلكترونيًا أو رقم هاتف حتى يصلك التنبيه."
        : "Add an email or phone number to receive the alert.";
      setError(message);
      toast.error(message);
      return;
    }

    try {
      setIsSubmitting(true);
      setError(null);

      const response = await storefrontFetch(
        `/products/${encodeURIComponent(productId)}/back-in-stock`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            customerName,
            customerEmail: customerEmail || undefined,
            customerPhone: customerPhone || undefined,
            notifyEmail: Boolean(customerEmail),
            notifySMS: Boolean(customerPhone),
          }),
        },
      );

      setIsSubmitted(true);
      setForm({
        customerName: "",
        customerEmail: "",
        customerPhone: "",
      });

      toast.success(
        String(
          response?.message ||
            resolvedSuccessMessage ||
            `${productName || (isRTL ? "هذا المنتج" : "This product")} is now on your alert list.`,
        ),
      );
    } catch (submissionError: any) {
      const message =
        submissionError?.response?.data?.error ||
        submissionError?.message ||
        (isRTL
          ? "تعذر حفظ طلب التنبيه الآن. حاولي مرة أخرى بعد قليل."
          : "Unable to save your back in stock request right now.");
      setError(String(message));
      toast.error(String(message));
    } finally {
      setIsSubmitting(false);
    }
  };

  const containerBase =
    "group relative overflow-hidden rounded-[1.5rem] border transition-all duration-500 hover:shadow-[0_20px_50px_-20px_hsl(var(--primary)/0.1)]";
  const surfaceStyle = isSubmitted
    ? "border-emerald-500/20 bg-[linear-gradient(180deg,hsl(var(--background)),hsl(var(--emerald-500)/0.04))] p-5"
    : variant === "accent"
      ? "border-primary/20 bg-[linear-gradient(180deg,hsl(var(--background)),hsl(var(--primary)/0.06))] p-5 shadow-[0_30px_60px_-45px_hsl(var(--primary)/0.35)]"
      : "border-border/40 bg-secondary/5 p-4 sm:p-5";

  if (isSubmitted) {
    return (
      <div className={cx(containerBase, surfaceStyle, className)}>
        <div className="flex items-center gap-2 rounded-full bg-emerald-500/10 px-3 py-1 text-[10px] font-black uppercase tracking-[0.1em] text-emerald-600">
          <span className="h-1 w-1 rounded-full bg-emerald-500" />
          {isRTL ? "تم تسجيل التنبيه" : "Waitlist Joined"}
        </div>
        <h3 className="mt-4 text-lg font-black text-foreground">{resolvedTitle}</h3>
        <p className="mt-2 text-sm font-medium text-muted-foreground">{resolvedSuccessMessage}</p>
      </div>
    );
  }

  return (
    <div className={cx(containerBase, surfaceStyle, className)}>
      <div className="flex items-center gap-2 rounded-full bg-primary/10 px-3 py-1 text-[10px] font-black uppercase tracking-[0.1em] text-primary">
        <span className="h-1 w-1 rounded-full bg-primary" />
        {isRTL ? "تنبيه عودة المخزون" : "Back In Stock"}
      </div>
      <h3 className="mt-4 text-lg font-black text-foreground sm:text-xl">{resolvedTitle}</h3>
      <p className="mt-2 text-sm font-medium text-muted-foreground/80">{resolvedDescription}</p>

      <form className="mt-5 space-y-4" onSubmit={handleSubmit}>
        <div className="relative">
          <input
            className={inputClassName}
            value={form.customerName}
            onChange={(event) => updateField("customerName", event.target.value)}
            placeholder={isRTL ? "اسمك" : "Your name"}
            autoComplete="name"
          />
        </div>
        <div className="flex flex-col gap-3 sm:flex-row">
          <div className="relative flex-1">
            <input
              className={inputClassName}
              value={form.customerEmail}
              onChange={(event) => updateField("customerEmail", event.target.value)}
              placeholder={isRTL ? "البريد الإلكتروني" : "Email address"}
              autoComplete="email"
              inputMode="email"
            />
          </div>
          <div className="relative flex-1">
            <input
              className={inputClassName}
              value={form.customerPhone}
              onChange={(event) => updateField("customerPhone", event.target.value)}
              placeholder={isRTL ? "رقم الهاتف" : "Phone number"}
              autoComplete="tel"
              inputMode="tel"
            />
          </div>
        </div>

        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between pt-1">
          <p className="text-[11px] leading-relaxed text-muted-foreground/60 max-w-[200px]">
            {isRTL
              ? "سنرسل لك التنبيه على الوسيلة المتاحة فور عودة الموديل أو المقاس."
              : "We'll notify you across all saved channels as soon as inventory returns."}
          </p>
          <button
            type="submit"
            disabled={isSubmitting}
            className="inline-flex h-11 items-center justify-center rounded-xl bg-primary px-6 text-sm font-bold text-primary-foreground shadow-[0_8px_20px_-8px_hsl(var(--primary)/0.6)] transition-all duration-300 hover:scale-102 hover:shadow-[0_12px_25px_-8px_hsl(var(--primary)/0.7)] active:scale-98 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isSubmitting ? (isRTL ? "جارٍ الحفظ..." : "Syncing...") : resolvedButtonLabel}
          </button>
        </div>

        {error ? <p className="text-xs font-semibold text-destructive/80 text-center">{error}</p> : null}
      </form>
    </div>
  );
};

export default BackInStockSignupCard;

import React, { useEffect, useMemo, useState } from "react";
import { Link, useLocation } from "react-router-dom";
import { storefrontFetch } from "../../utils/storefrontApi";
import type { Product } from "../hooks/useProducts";
import { useCartStore } from "../store/useCartStore";
import { useStorefrontSettings } from "../hooks/useStorefrontSettings";
import {
  getStorefrontMarketplaceAppSettings,
  isStorefrontMarketplaceAppEnabled,
} from "../utils/marketplaceApps";
import { buildStorefrontPath } from "../utils/paths";
import { formatStorefrontCurrency } from "../utils/currency";
import StorefrontProductImage from "./StorefrontProductImage";
import { getProductImageCandidates, getPrimaryProductImage } from "../utils/productImages";
import { trackStorefrontAppUsage } from "../utils/appUsageTracking";
import { getProductVolumeDiscounts } from "../utils/volumeDiscounts";
import { useStorefrontTheme } from "../engine/ThemeProvider";
import { getMarketplacePreviewRecommendations } from "../preview/marketplaceSampleData";

interface CartUpsellHostProps {
  open: boolean;
  layout?: "drawer" | "inline";
}

const dedupeProducts = (products: Product[]): Product[] => {
  const seen = new Set<string>();
  return products.filter((product) => {
    if (!product?.id || seen.has(product.id)) {
      return false;
    }

    seen.add(product.id);
    return true;
  });
};

const excludeDuplicateProducts = (
  primary: Product[],
  secondary: Product[],
): Product[] => {
  if (primary.length === 0 || secondary.length === 0) {
    return secondary;
  }

  const primaryIds = new Set(primary.map((product) => product.id));
  return secondary.filter((product) => !primaryIds.has(product.id));
};

const resolveDirectionalCopy = ({
  value,
  englishFallback,
  arabicFallback,
  prefersArabicCopy,
}: {
  value: unknown;
  englishFallback: string;
  arabicFallback: string;
  prefersArabicCopy: boolean;
}) => {
  if (typeof value === "string" && value.trim()) {
    const trimmedValue = value.trim();
    if (prefersArabicCopy && trimmedValue === englishFallback) {
      return arabicFallback;
    }

    return trimmedValue;
  }

  return prefersArabicCopy ? arabicFallback : englishFallback;
};

const CartUpsellHost: React.FC<CartUpsellHostProps> = ({
  open,
  layout = "drawer",
}) => {
  const location = useLocation();
  const { theme } = useStorefrontTheme();
  const { settings } = useStorefrontSettings();
  const items = useCartStore((state) => state.items);
  const addItem = useCartStore((state) => state.addItem);
  const setIsOpen = useCartStore((state) => state.setIsOpen);
  const [relatedProducts, setRelatedProducts] = useState<Product[]>([]);
  const [bundleProducts, setBundleProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);

  const conversionEnabled = isStorefrontMarketplaceAppEnabled(
    settings,
    "conversion-suite",
  );
  const conversionSettings = getStorefrontMarketplaceAppSettings(
    settings,
    "conversion-suite",
  );
  const modules = (conversionSettings["modules"] as Record<string, any> | undefined) || {};
  const conversionUi =
    (conversionSettings["ui"] as Record<string, any> | undefined) || {};
  const conversionCopy =
    (conversionSettings["copy"] as Record<string, any> | undefined) || {};
  const sourceProductId = items[0]?.productId || null;
  const currency =
    settings?.storefront?.settings?.currency || settings?.company?.currency || "EGP";
  const prefersArabicCopy = theme.direction === "rtl";
  const isBiteRush = theme.id === "restaurant-demo";
  const isInline = layout === "inline";
  const conversionActive = conversionEnabled || isBiteRush;
  const crossSellEnabled = Boolean(modules["crossSell"]) || isBiteRush;
  const boughtTogetherEnabled = Boolean(modules["boughtTogether"]) || isBiteRush;
  const upsellStyle = String(conversionUi["cartUpsellStyle"] || "stacked");
  const upsellBadge = resolveDirectionalCopy({
    value: conversionCopy["cartUpsellBadge"],
    englishFallback: "Upsell",
    arabicFallback: "ترشيحات ذكية",
    prefersArabicCopy,
  });
  const upsellTitle = resolveDirectionalCopy({
    value: conversionCopy["cartUpsellTitle"],
    englishFallback: "Continue building your order",
    arabicFallback: "كمّل طلبك باقتراحات مناسبة",
    prefersArabicCopy,
  });
  const upsellDescription = resolveDirectionalCopy({
    value: conversionCopy["cartUpsellDescription"],
    englishFallback:
      "These storefront suggestions are powered by the conversion app inside the cart drawer.",
    arabicFallback:
      "اقتراحات سريعة داخل السلة تساعدك على زيادة قيمة الطلب قبل الإتمام.",
    prefersArabicCopy,
  });
  const crossSellTitle = resolveDirectionalCopy({
    value: conversionCopy["crossSellTitle"],
    englishFallback: "Cross Sell",
    arabicFallback: "منتجات مكملة",
    prefersArabicCopy,
  });
  const crossSellDescription = resolveDirectionalCopy({
    value: conversionCopy["crossSellDescription"],
    englishFallback: "Add complementary picks",
    arabicFallback: "أضف اقتراحات تكمل المنتج الحالي",
    prefersArabicCopy,
  });
  const boughtTogetherTitle = resolveDirectionalCopy({
    value: conversionCopy["boughtTogetherTitle"],
    englishFallback: "Bought Together",
    arabicFallback: "يُشترى معه كثيرًا",
    prefersArabicCopy,
  });
  const boughtTogetherDescription = resolveDirectionalCopy({
    value: conversionCopy["boughtTogetherDescription"],
    englishFallback: "Popular pairings for this product",
    arabicFallback: "ترشيحات شائعة مع هذا المنتج",
    prefersArabicCopy,
  });
  const quickAddLabel = resolveDirectionalCopy({
    value: conversionCopy["quickAddLabel"],
    englishFallback: "Quick add",
    arabicFallback: "إضافة سريعة",
    prefersArabicCopy,
  });
  const chooseOptionsLabel = resolveDirectionalCopy({
    value: conversionCopy["chooseOptionsLabel"],
    englishFallback: "Choose options",
    arabicFallback: "اختر الخيارات",
    prefersArabicCopy,
  });
  const crossSellCardLabel = prefersArabicCopy ? "يكمل الطلب" : "Cross sell";
  const bundleCardLabel = prefersArabicCopy ? "الأكثر طلبًا معه" : "Bundle";
  const cartProductIds = useMemo(
    () => new Set(items.map((item) => item.productId)),
    [items],
  );

  useEffect(() => {
    if (!open || !conversionActive || !sourceProductId || (!crossSellEnabled && !boughtTogetherEnabled)) {
      setRelatedProducts([]);
      setBundleProducts([]);
      return;
    }

    let cancelled = false;

    const loadSuggestions = async () => {
      try {
        setLoading(true);

        const previewRelated = getMarketplacePreviewRecommendations(sourceProductId, "related");
        const previewBundles = getMarketplacePreviewRecommendations(sourceProductId, "boughtTogether");

        if (previewRelated || previewBundles) {
          if (cancelled) {
            return;
          }

          const nextRelatedProducts = dedupeProducts(
            (previewRelated || []).filter(
              (product) => product?.id && !cartProductIds.has(product.id),
            ),
          );
          const nextBundleProducts = excludeDuplicateProducts(
            nextRelatedProducts,
            dedupeProducts(
              (previewBundles || []).filter(
                (product) => product?.id && !cartProductIds.has(product.id),
              ),
            ),
          );

          setRelatedProducts(nextRelatedProducts);
          setBundleProducts(nextBundleProducts);
          return;
        }

        const [relatedResponse, bundleResponse] = await Promise.all([
          crossSellEnabled
            ? storefrontFetch(`/products/${encodeURIComponent(sourceProductId)}/related`, {
                query: { limit: 4 },
              })
            : Promise.resolve({ data: [] }),
          boughtTogetherEnabled
            ? storefrontFetch(
                `/products/${encodeURIComponent(sourceProductId)}/frequently-bought-together`,
                { query: { limit: 4 } },
              )
            : Promise.resolve({ data: [] }),
        ]);

        if (cancelled) {
          return;
        }

        const filterAvailable = (products: Product[]) =>
          dedupeProducts(products).filter(
            (product) => product?.id && !cartProductIds.has(product.id),
          );

        const nextRelatedProducts = filterAvailable(
          Array.isArray(relatedResponse?.data) ? relatedResponse.data : [],
        );
        const nextBundleProducts = excludeDuplicateProducts(
          nextRelatedProducts,
          filterAvailable(
            Array.isArray(bundleResponse?.data) ? bundleResponse.data : [],
          ),
        );

        setRelatedProducts(nextRelatedProducts);
        setBundleProducts(nextBundleProducts);
      } catch (error) {
        if (!cancelled) {
          console.error("Failed to load cart upsell suggestions:", error);
          setRelatedProducts([]);
          setBundleProducts([]);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    void loadSuggestions();

    return () => {
      cancelled = true;
    };
  }, [
    boughtTogetherEnabled,
    cartProductIds,
    conversionActive,
    crossSellEnabled,
    open,
    sourceProductId,
  ]);

  useEffect(() => {
    if (!open || loading || !sourceProductId) {
      return;
    }

    const totalSuggestions = relatedProducts.length + bundleProducts.length;
    if (totalSuggestions === 0) {
      return;
    }

    void trackStorefrontAppUsage({
      slug: "conversion-suite",
      feature: "cart_upsell_view",
        dedupeKey: `cart-upsell:${layout}:${sourceProductId}:${upsellStyle}`,
        metadata: {
          sourceProductId,
          relatedCount: relatedProducts.length,
          bundleCount: bundleProducts.length,
          layout,
          style: upsellStyle,
        },
    });
  }, [
    bundleProducts.length,
    loading,
    open,
    relatedProducts.length,
    sourceProductId,
    layout,
    upsellStyle,
  ]);

  const handleQuickAdd = (product: Product) => {
    void trackStorefrontAppUsage({
      slug: "conversion-suite",
      feature: "cart_upsell_quick_add",
      metadata: {
        sourceProductId: sourceProductId || undefined,
        productId: product.id,
      },
    });

    addItem(
      {
        productId: product.id,
        variantId: null,
        name: product.name,
        price: Number(product.price) || 0,
        basePrice: Number(product.price) || 0,
        quantity: 1,
        imageUrl: getPrimaryProductImage(product),
        volumeDiscounts: getProductVolumeDiscounts(product),
      },
      { openCart: !isInline },
    );

    if (!isInline) {
      setIsOpen(true);
    }
  };

  const renderProductCard = (product: Product, label: string) => {
    const hasVariants = Boolean(product.productVariants?.length || product.variants?.length);
    const variantSource = product.productVariants?.length
      ? product.productVariants
      : product.variants || [];
    const variantAxes = new Set(
      variantSource.flatMap((variant) =>
        Object.keys(variant?.attributes || variant?.attributeValues || {}),
      ),
    );
    const hasColorAxis = variantAxes.has("اللون");
    const hasSizeAxis = variantAxes.has("المقاس");
    const variantSelectionHint = hasColorAxis && hasSizeAxis
      ? "اختاري اللون والمقاس من صفحة المنتج"
      : hasColorAxis
        ? "اختاري اللون من صفحة المنتج"
        : hasSizeAxis
          ? "اختاري المقاس من صفحة المنتج"
          : "اختيارات متاحة من صفحة المنتج";
    const chooseOptionsCtaLabel = hasColorAxis && hasSizeAxis
      ? (prefersArabicCopy ? "اختاري اللون والمقاس" : "Choose color & size")
      : hasColorAxis
        ? (prefersArabicCopy ? "اختاري اللون" : "Choose color")
        : hasSizeAxis
          ? (prefersArabicCopy ? "اختاري المقاس" : "Choose size")
          : chooseOptionsLabel;
    const productPath = buildStorefrontPath(
      location.pathname,
      `/product/${product.slug || product.id}`,
      location.search,
    );
    const cardClassName = isBiteRush
      ? "rounded-[1.5rem] border border-[#f8c08c] bg-white/90 p-3 shadow-[0_18px_40px_-34px_rgba(247,115,22,0.3)]"
      : isInline
        ? "rounded-[1.4rem] border border-border/70 bg-background/95 p-4 shadow-[0_22px_48px_-38px_rgba(15,23,42,0.35)]"
        : upsellStyle === "editorial"
          ? "rounded-[1.4rem] border border-border bg-[linear-gradient(180deg,hsl(var(--background)),hsl(var(--secondary)/0.28))] p-3 shadow-sm"
          : upsellStyle === "compact"
            ? "rounded-xl border border-border bg-background p-2.5"
            : "rounded-2xl border border-border bg-background p-3";
    const imageClassName =
      isBiteRush
        ? "h-16 w-16 overflow-hidden rounded-[1rem] bg-[#fff1e2]"
        : isInline
          ? "h-20 w-20 overflow-hidden rounded-[1rem] border border-border/70 bg-muted"
          : upsellStyle === "compact"
            ? "h-14 w-14 overflow-hidden rounded-lg bg-muted"
            : "h-16 w-16 overflow-hidden rounded-xl bg-muted";
    const badgeClassName =
      isBiteRush
        ? "inline-flex rounded-full bg-[#111111] px-2.5 py-1 text-[10px] font-black uppercase tracking-[0.16em] text-white"
        : upsellStyle === "editorial"
        ? "inline-flex rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-[0.16em] text-primary"
        : "inline-flex rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-black uppercase tracking-wide text-primary";

    return (
      <div
        key={`${label}-${product.id}`}
        className={cardClassName}
      >
        <div className="flex items-start gap-3">
          <div className={imageClassName}>
            <StorefrontProductImage
              candidates={getProductImageCandidates(product)}
              alt={product.name}
              width="64"
              height="64"
              className="h-full w-full object-cover"
              fallback={
                <div className="flex h-full w-full items-center justify-center text-xs text-muted-foreground">
                  IMG
                </div>
              }
            />
          </div>

          <div className="min-w-0 flex-1">
            <span className={badgeClassName}>
              {label}
            </span>
            <h4 className={`mt-2 truncate text-sm font-bold ${isBiteRush ? "text-[#171717]" : "text-foreground"}`}>
              {product.name}
            </h4>
            <p
              className={`mt-1 text-xs ${
                isBiteRush ? "text-[#8a4b1f]" : "text-muted-foreground"
              }`}
            >
              {formatStorefrontCurrency(Number(product.price) || 0, currency)}
            </p>
            {isInline ? (
              <p className="mt-1 text-[11px] text-muted-foreground">
                {hasVariants
                  ? variantSelectionHint
                  : "إضافة مباشرة إلى السلة"}
              </p>
            ) : null}
          </div>
        </div>

        <div className="mt-3">
          {hasVariants ? (
            <Link
              to={productPath}
              onClick={() => {
                if (!isInline) {
                  setIsOpen(false);
                }
              }}
            className={`inline-flex w-full items-center justify-center rounded-xl px-3 py-2 text-sm font-semibold ${
                isBiteRush
                  ? "border border-[#171717] bg-white text-[#171717] hover:border-[#f97316] hover:text-[#f97316]"
                  : "border border-border text-foreground hover:bg-muted"
              }`}
            >
              {chooseOptionsCtaLabel}
            </Link>
          ) : (
            <button
              type="button"
              onClick={() => handleQuickAdd(product)}
              className={`inline-flex w-full items-center justify-center rounded-xl px-3 py-2 text-sm font-bold hover:opacity-90 ${
                isBiteRush
                  ? "bg-[linear-gradient(135deg,#f97316_0%,#ef4444_100%)] text-white"
                  : "bg-primary text-primary-foreground"
              }`}
            >
              {quickAddLabel}
            </button>
          )}
        </div>
      </div>
    );
  };

  if (
    !open ||
    !conversionActive ||
    (!crossSellEnabled && !boughtTogetherEnabled) ||
    !sourceProductId
  ) {
    return null;
  }

  const hasSuggestions = relatedProducts.length > 0 || bundleProducts.length > 0;

  if (!loading && !hasSuggestions) {
    return null;
  }

  return (
    <section
      className={`space-y-5 ${
        isInline
          ? "mt-6 rounded-[1.85rem] border border-border/70 bg-[linear-gradient(180deg,hsl(var(--background)),hsl(var(--secondary)/0.18))] p-5 shadow-[0_30px_80px_-62px_rgba(15,23,42,0.38)]"
          : `border-t px-5 py-5 ${
              isBiteRush
                ? "border-[#f8c08c] bg-[linear-gradient(180deg,rgba(255,247,238,0.98),rgba(255,255,255,0.96))]"
                : upsellStyle === "editorial"
                  ? "border-border bg-[linear-gradient(180deg,hsl(var(--background)),hsl(var(--secondary)/0.22))]"
                  : "border-border"
            }`
      }`}
    >
      <div>
        <span
          className={`inline-flex rounded-full px-3 py-1 text-[10px] font-black uppercase tracking-[0.22em] ${
            isBiteRush
              ? "bg-[#111111] text-white"
              : upsellStyle === "editorial"
                ? "bg-primary/10 text-primary"
                : "bg-secondary text-primary"
          }`}
        >
          {upsellBadge}
        </span>
        <h3 className={`mt-2 text-base font-black ${isBiteRush ? "text-[#171717]" : "text-foreground"}`}>
          {upsellTitle}
        </h3>
        <p className={`mt-1 text-sm ${isBiteRush ? "text-[#7c5a3b]" : "text-muted-foreground"}`}>
          {upsellDescription}
        </p>
      </div>

      {loading ? (
        <div className="grid gap-3">
          {[1, 2].map((item) => (
            <div
              key={item}
              className={`h-24 animate-pulse rounded-2xl border ${
                isBiteRush ? "border-[#f8c08c] bg-[#fff1e2]" : "border-border bg-muted/40"
              }`}
            />
          ))}
        </div>
      ) : null}

      {!loading && relatedProducts.length > 0 ? (
        <div className="space-y-3">
          <div
            className={`${
              isInline
                ? "flex flex-col gap-1.5 md:flex-row md:items-center md:justify-between"
                : "flex items-center justify-between"
            }`}
          >
            <h4 className={`text-sm font-black uppercase tracking-wide ${isBiteRush ? "text-[#171717]" : "text-foreground"}`}>
              {crossSellTitle}
            </h4>
            <span className={`text-xs ${isBiteRush ? "text-[#8a4b1f]" : "text-muted-foreground"}`}>
              {crossSellDescription}
            </span>
          </div>
          <div
            className={
              isInline
                ? "grid gap-3 md:grid-cols-2"
                : upsellStyle === "compact"
                  ? "grid gap-2 sm:grid-cols-2"
                  : "grid gap-3"
            }
          >
            {relatedProducts
              .slice(0, isInline ? 2 : 3)
              .map((product) => renderProductCard(product, crossSellCardLabel))}
          </div>
        </div>
      ) : null}

      {!loading && bundleProducts.length > 0 ? (
        <div className="space-y-3">
          <div
            className={`${
              isInline
                ? "flex flex-col gap-1.5 md:flex-row md:items-center md:justify-between"
                : "flex items-center justify-between"
            }`}
          >
            <h4 className={`text-sm font-black uppercase tracking-wide ${isBiteRush ? "text-[#171717]" : "text-foreground"}`}>
              {boughtTogetherTitle}
            </h4>
            <span className={`text-xs ${isBiteRush ? "text-[#8a4b1f]" : "text-muted-foreground"}`}>
              {boughtTogetherDescription}
            </span>
          </div>
          <div
            className={
              isInline
                ? "grid gap-3 md:grid-cols-2"
                : upsellStyle === "compact"
                  ? "grid gap-2 sm:grid-cols-2"
                  : "grid gap-3"
            }
          >
            {bundleProducts
              .slice(0, isInline ? 2 : 3)
              .map((product) => renderProductCard(product, bundleCardLabel))}
          </div>
        </div>
      ) : null}
    </section>
  );
};

export default CartUpsellHost;

import React, { useEffect, useMemo, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { ArrowUpRight, ShoppingCart, Sparkles } from 'lucide-react';
import { storefrontFetch } from '../../utils/storefrontApi';
import { useProducts, type Product } from '../hooks/useProducts';
import { getMarketplacePreviewRecommendations } from '../preview/marketplaceSampleData';
import { useStorefrontSettings } from '../hooks/useStorefrontSettings';
import { useStorefrontFacebookTracking } from '../hooks/useStorefrontFacebookTracking';
import { useCartStore } from '../store/useCartStore';
import { trackConversionSuiteUsage } from '../utils/conversionSuiteTracking';
import { buildStorefrontPath } from '../utils/paths';
import { formatStorefrontCurrency } from '../utils/currency';
import {
  getStorefrontMarketplaceAppSettings,
  isStorefrontMarketplaceAppEnabled,
} from '../utils/marketplaceApps';
import { useStorefrontTheme } from '../engine/ThemeProvider';
import StorefrontProductImage from './StorefrontProductImage';
import {
  buildStorefrontImageCandidates,
  getPrimaryProductImage,
  normalizeStorefrontImageValue,
} from '../utils/productImages';
import { getProductVolumeDiscounts } from '../utils/volumeDiscounts';

interface PurchaseTrackingItem {
  id: string;
  quantity: number;
  price: number;
}

interface PostPurchaseUpsellBlockProps {
  orderReference?: string;
  purchaseItems?: PurchaseTrackingItem[] | null;
  settings?: {
    variant?: string;
    title?: string;
    subtitle?: string;
    badge?: string;
    limit?: number | string;
    ctaLabel?: string;
    chooseOptionsLabel?: string;
    variantChoicesLabel?: string;
    emptyStateTitle?: string;
    [key: string]: unknown;
  };
}

const normalizePostPurchaseUpsellVariant = (
  value: unknown,
): 'standard' | 'boutique-afterglow' => {
  if (typeof value !== 'string') {
    return 'standard';
  }

  const normalizedValue = value.trim().toLowerCase();
  if (normalizedValue === 'boutique-afterglow') {
    return 'boutique-afterglow';
  }

  return 'standard';
};

type StorefrontProductPayload = Product & {
  images?: unknown;
  mainImage?: unknown;
  image?: unknown;
};

const parsePositiveNumber = (value: unknown, fallback: number) => {
  const parsedValue =
    typeof value === 'number' ? value : typeof value === 'string' ? Number(value) : Number.NaN;

  if (!Number.isFinite(parsedValue) || parsedValue <= 0) {
    return fallback;
  }

  return Math.round(parsedValue);
};

const normalizeRecommendation = (product: StorefrontProductPayload): Product => ({
  ...product,
  mainImage: normalizeStorefrontImageValue(product.mainImage as any),
  images: buildStorefrontImageCandidates(
    product.images,
    product.mainImage,
    (product as Record<string, unknown>)['image'],
  ),
});

const dedupeRecommendations = (products: Product[]) => {
  const seenIds = new Set<string>();

  return products.filter((product) => {
    if (!product?.id || seenIds.has(product.id)) {
      return false;
    }

    seenIds.add(product.id);
    return true;
  });
};

const getPcHubRecommendationGridClassName = (itemCount: number) => {
  if (itemCount <= 1) {
    return 'mx-auto grid max-w-xl grid-cols-1 gap-4';
  }

  if (itemCount === 2) {
    return 'mx-auto grid max-w-4xl grid-cols-1 gap-4 md:grid-cols-2';
  }

  if (itemCount === 3) {
    return 'mx-auto grid max-w-6xl grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3';
  }

  return 'grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4';
};

const PostPurchaseUpsellBlock: React.FC<PostPurchaseUpsellBlockProps> = ({
  orderReference,
  purchaseItems,
  settings,
}) => {
  const { settings: storefrontSettings } = useStorefrontSettings();
  const { theme } = useStorefrontTheme();
  const { addItem } = useCartStore();
  const { trackAddToCartEvent } = useStorefrontFacebookTracking();
  const location = useLocation();
  const navigate = useNavigate();
  const [recommendedProducts, setRecommendedProducts] = useState<Product[]>([]);
  const [recommendationsLoading, setRecommendationsLoading] = useState(false);
  const conversionEnabled = isStorefrontMarketplaceAppEnabled(
    storefrontSettings,
    'conversion-suite',
  );
  const conversionSettings = getStorefrontMarketplaceAppSettings(
    storefrontSettings,
    'conversion-suite',
  );
  const modules = (conversionSettings['modules'] as Record<string, any> | undefined) || {};
  const copy = (conversionSettings['copy'] as Record<string, any> | undefined) || {};
  const postPurchaseUpsellEnabled =
    !conversionEnabled || modules['postPurchaseUpsell'] !== false;
  const prefersArabicCopy = theme.direction === 'rtl';
  const isPcHub = theme.id === 'pc-hub-eg';
  const variant = normalizePostPurchaseUpsellVariant(settings?.variant);
  const isBoutiqueAfterglow =
    variant === 'boutique-afterglow' || theme.id === 'rose-boutique-eg';

  const currency =
    storefrontSettings?.storefront?.settings?.currency ||
    storefrontSettings?.company?.currency ||
    'EGP';
  const limit = parsePositiveNumber(settings?.limit, 4);
  const purchasedProductIds = useMemo(
    () =>
      Array.from(
        new Set(
          (purchaseItems || [])
            .map((item) => String(item?.id || '').trim())
            .filter(Boolean),
        ),
      ),
    [purchaseItems],
  );
  const { products: fallbackProducts, isLoading: fallbackLoading, error } = useProducts({
    limit: Math.max(limit + 2, 6),
  });

  useEffect(() => {
    if (!postPurchaseUpsellEnabled || purchasedProductIds.length === 0) {
      setRecommendedProducts([]);
      setRecommendationsLoading(false);
      return;
    }

    let cancelled = false;

    const loadRecommendations = async () => {
      try {
        setRecommendationsLoading(true);

        const previewRecommendations = dedupeRecommendations(
          purchasedProductIds
            .slice(0, 3)
            .flatMap((productId) => [
              ...(getMarketplacePreviewRecommendations(productId, 'boughtTogether') || []),
              ...(getMarketplacePreviewRecommendations(productId, 'related') || []),
            ])
            .filter((product) => product?.id && !purchasedProductIds.includes(product.id)),
        ).slice(0, limit);

        if (previewRecommendations.length > 0) {
          if (!cancelled) {
            setRecommendedProducts(previewRecommendations);
          }
          return;
        }

        const responses = await Promise.all(
          purchasedProductIds.slice(0, 3).map((productId) =>
            storefrontFetch(`/products/${encodeURIComponent(productId)}/upsell`, {
              query: { limit },
            }).catch(() => null),
          ),
        );

        if (cancelled) {
          return;
        }

        const recommendationMap = new Map<string, Product>();

        responses.forEach((response) => {
          const items = Array.isArray(response?.data) ? response.data : [];

          items.forEach((item: StorefrontProductPayload) => {
            const normalized = normalizeRecommendation(item);
            if (!normalized.id || purchasedProductIds.includes(normalized.id)) {
              return;
            }

            if (!recommendationMap.has(normalized.id)) {
              recommendationMap.set(normalized.id, normalized);
            }
          });
        });

        setRecommendedProducts(Array.from(recommendationMap.values()).slice(0, limit));
      } catch (fetchError) {
        if (!cancelled) {
          console.error('Failed to load post-purchase upsell recommendations:', fetchError);
          setRecommendedProducts([]);
        }
      } finally {
        if (!cancelled) {
          setRecommendationsLoading(false);
        }
      }
    };

    void loadRecommendations();

    return () => {
      cancelled = true;
    };
  }, [limit, postPurchaseUpsellEnabled, purchasedProductIds]);

  const fallbackRecommendations = useMemo(
    () =>
      fallbackProducts
        .filter((product) => !purchasedProductIds.includes(product.id))
        .slice(0, limit),
    [fallbackProducts, limit, purchasedProductIds],
  );

  const displayProducts = recommendedProducts.length > 0 ? recommendedProducts : fallbackRecommendations;
  const recommendationSource = recommendedProducts.length > 0 ? 'upsell' : 'fallback';
  const shouldShowLoading =
    recommendationsLoading || (displayProducts.length === 0 && fallbackLoading);

  const heading =
    settings?.title ||
