import React, { useEffect, useMemo, useState } from "react";
import {
  buildOptimizedStorefrontImageUrl,
  buildResponsiveStorefrontImage,
  canOptimizeStorefrontImage,
} from "../utils/productImages";

interface StorefrontProductImageProps extends Omit<
  React.ImgHTMLAttributes<HTMLImageElement>,
  "src"
> {
  candidates?: Array<string | null | undefined>;
  fallback?: React.ReactNode;
  requestedWidth?: number;
  responsiveWidths?: number[];
  responsiveSizes?: string;
  imageQuality?: number;
  fetchpriority?: "high" | "low" | "auto";
}

const StorefrontProductImage: React.FC<StorefrontProductImageProps> = ({
  candidates = [],
  fallback = null,
  decoding = "async",
  loading = "lazy",
  alt = "", // Default to empty string for accessibility (decorative) if not provided
  onError,
  requestedWidth = 720,
  responsiveWidths,
  responsiveSizes,
  imageQuality = 76,
  fetchpriority,
  ...imgProps
}) => {
  const normalizedCandidates = useMemo(
    () =>
      candidates
        .map((candidate) => String(candidate || "").trim())
        .filter(Boolean),
    [candidates],
  );
  const candidatesKey = normalizedCandidates.join("|");
  const [candidateIndex, setCandidateIndex] = useState(0);
  const [useOriginalCandidate, setUseOriginalCandidate] = useState(false);

  useEffect(() => {
    setCandidateIndex(0);
  }, [candidatesKey]);

  useEffect(() => {
    setUseOriginalCandidate(false);
  }, [candidateIndex, candidatesKey]);

  const activeCandidate = normalizedCandidates[candidateIndex];
  const optimizedCandidate = useMemo(() => {
    if (!activeCandidate || useOriginalCandidate) {
      return {
        src: activeCandidate || "",
        srcSet: undefined,
        sizes: undefined,
      };
    }

    if (responsiveWidths?.length && responsiveSizes) {
      return buildResponsiveStorefrontImage(activeCandidate, {
        widths: responsiveWidths,
        fallbackWidth: requestedWidth,
        sizes: responsiveSizes,
        quality: imageQuality,
      });
    }

    if (!canOptimizeStorefrontImage(activeCandidate)) {
      return {
        src: activeCandidate,
        srcSet: undefined,
        sizes: undefined,
      };
    }

    return {
      src: buildOptimizedStorefrontImageUrl(activeCandidate, {
        width: requestedWidth,
        quality: imageQuality,
      }),
      srcSet: undefined,
      sizes: undefined,
    };
  }, [
    activeCandidate,
    imageQuality,
    requestedWidth,
    responsiveSizes,
    responsiveWidths,
    useOriginalCandidate,
  ]);

  if (!activeCandidate) {
    return <>{fallback}</>;
  }

    return (
      <img
        {...imgProps}
        alt={alt}
        decoding={decoding}
        loading={loading}
        fetchpriority={fetchpriority}
        src={optimizedCandidate.src}
        srcSet={optimizedCandidate.srcSet}
        sizes={optimizedCandidate.sizes}
        onError={(event) => {
          onError?.(event);
          if (
            !useOriginalCandidate &&
            optimizedCandidate.src !== activeCandidate
          ) {
            setUseOriginalCandidate(true);
            return;
          }

          setUseOriginalCandidate(false);
          setCandidateIndex((currentIndex) => currentIndex + 1);
        }}
      />
    );
};

export default StorefrontProductImage;

import React from 'react';
import type { ProductVariant } from '../hooks/useProducts';
import { getVariantAttributeLabel, getVariantAttributes } from '../utils/variants';
import {
  buildStorefrontImageCandidates,
  normalizeStorefrontImageValue,
} from '../utils/productImages';
import { useStorefrontTheme } from '../engine/ThemeProvider';

interface VariantSelectorProps {
  variants: ProductVariant[];
  selectedAttributes: Record<string, string>;
  onChange: (attributes: Record<string, string>) => void;
  density?: 'default' | 'compact';
  layout?: 'default' | 'inline-compact';
  variantSettings?: {
    styles?: Record<string, unknown> | null;
    attributeImages?: Record<string, unknown> | null;
  } | null;
}

interface RgbColor {
  r: number;
  g: number;
  b: number;
}

type VariantDisplayStyle =
  | 'buttons'
  | 'circles'
  | 'dropdown'
  | 'thumbnails'
  | 'radio';

const FALLBACK_LIGHT: RgbColor = { r: 255, g: 255, b: 255 };
const FALLBACK_DARK: RgbColor = { r: 17, g: 24, b: 39 };
const CANONICAL_ATTRIBUTE_LABELS: Record<string, string> = {
  color: 'Color',
  colour: 'Color',
  اللون: 'Color',
  size: 'Size',
  المقاس: 'Size',
  material: 'Material',
  الخامة: 'Material',
  style: 'Style',
  الطراز: 'Style',
};

const COLOR_PRESETS: Record<string, string> = {
  black: '#000000',
  'أسود': '#000000',
  'اسود': '#000000',
  'أسود كلاسيك': '#18181b',
  'اسود كلاسيك': '#18181b',
  white: '#ffffff',
  'أبيض': '#ffffff',
  'ابيض': '#ffffff',
  'أبيض لؤلؤي': '#f7f1ea',
  'ابيض لؤلؤي': '#f7f1ea',
  'أوف وايت': '#f5efe6',
  'اوف وايت': '#f5efe6',
  red: '#dc2626',
  'أحمر': '#dc2626',
  'احمر': '#dc2626',
  blue: '#1d4ed8',
  'أزرق': '#1d4ed8',
  'ازرق': '#1d4ed8',
  green: '#16a34a',
  'أخضر': '#16a34a',
  'اخضر': '#16a34a',
  brown: '#8b4513',
  'بني': '#8b4513',
  beige: '#d0b089',
  'بيج': '#d0b089',
  gray: '#6b7280',
  grey: '#6b7280',
  'رمادي': '#6b7280',
  'رصاصي': '#6b7280',
  pink: '#ec4899',
  'وردي': '#ec4899',
  'زهري': '#ec4899',
  gold: '#d4af37',
  'ذهبي': '#d4af37',
  silver: '#c0c0c0',
  'فضي': '#c0c0c0',
  orange: '#f97316',
  'برتقالي': '#f97316',
  purple: '#8b5cf6',
  'بنفسجي': '#8b5cf6',
  yellow: '#facc15',
  'أصفر': '#facc15',
  'اصفر': '#facc15',
  navy: '#0f172a',
  'كحلي': '#0f172a',
  khaki: '#b59c67',
  'خاكي': '#b59c67',
  mauve: '#a855f7',
  'موف': '#a855f7',
  'موف توتي': '#8f5576',
  'عنابي': '#6f1d3a',
  'خمري': '#6f1d3a',
  'بيج لوزي': '#c9a27a',
  'بيج رملي': '#d6b089',
  'وردي هادئ': '#dea1b1',
  'وردي غباري': '#c58f95',
  'كريمي': '#efe2d2',
  'كريمي وردي': 'linear-gradient(135deg, #f1e3d8 0%, #e9b8c2 100%)',
  'سيج هادئ': '#95a895',
};

const clampChannel = (value: number) => Math.max(0, Math.min(255, Math.round(value)));

const toRgbString = ({ r, g, b }: RgbColor) => `rgb(${r}, ${g}, ${b})`;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const canonicalizeAttributeKey = (key: string): string => {
  const trimmedKey = String(key || '').trim();
  if (!trimmedKey) {
    return '';
  }

  return CANONICAL_ATTRIBUTE_LABELS[trimmedKey.toLowerCase()] || trimmedKey;
};

const parseHslToken = (rawValue: string): RgbColor | null => {
  const normalized = String(rawValue || '')
    .trim()
    .replace(/^hsl\(/i, '')
    .replace(/\)$/g, '')
    .split('/')[0]
    .trim();

  const match = normalized.match(
    /^(-?\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)%\s+(\d+(?:\.\d+)?)%$/,
  );
  if (!match) {
    return null;
  }

  const hue = Number(match[1]);
  const saturation = Number(match[2]) / 100;
  const lightness = Number(match[3]) / 100;

  const chroma = (1 - Math.abs(2 * lightness - 1)) * saturation;
  const huePrime = ((hue % 360) + 360) % 360 / 60;
  const x = chroma * (1 - Math.abs((huePrime % 2) - 1));

  let red = 0;
  let green = 0;
  let blue = 0;

  if (huePrime >= 0 && huePrime < 1) {
    red = chroma;
    green = x;
  } else if (huePrime < 2) {
    red = x;
    green = chroma;
  } else if (huePrime < 3) {
    green = chroma;
    blue = x;
  } else if (huePrime < 4) {
    green = x;
    blue = chroma;
  } else if (huePrime < 5) {
    red = x;
    blue = chroma;
  } else {
    red = chroma;
    blue = x;
  }

  const matchLightness = lightness - chroma / 2;
  return {
    r: clampChannel((red + matchLightness) * 255),
    g: clampChannel((green + matchLightness) * 255),
    b: clampChannel((blue + matchLightness) * 255),
  };
};

const toRelativeLuminance = ({ r, g, b }: RgbColor) => {
  const normalizeChannel = (channel: number) => {
    const value = channel / 255;
    return value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  };

  return (
    0.2126 * normalizeChannel(r) +
    0.7152 * normalizeChannel(g) +
    0.0722 * normalizeChannel(b)
  );
};

const getContrastRatio = (left: RgbColor, right: RgbColor) => {
  const leftLuminance = toRelativeLuminance(left);
  const rightLuminance = toRelativeLuminance(right);
  const [lightest, darkest] =
    leftLuminance >= rightLuminance
      ? [leftLuminance, rightLuminance]
      : [rightLuminance, leftLuminance];
  return (lightest + 0.05) / (darkest + 0.05);
};

const resolveReadableSelectedTextColor = (): string | null => {
  if (typeof window === 'undefined') {
    return null;
  }

  const target =
    document.getElementById('storefront-engine-root') || document.documentElement;
  const styles = window.getComputedStyle(target);
  const primary = parseHslToken(styles.getPropertyValue('--primary'));

  if (!primary) {
    return null;
  }

  const preferredForeground = parseHslToken(
    styles.getPropertyValue('--primary-foreground'),
  );
  if (preferredForeground && getContrastRatio(primary, preferredForeground) >= 4.5) {
    return toRgbString(preferredForeground);
  }

  const themeForeground = parseHslToken(styles.getPropertyValue('--foreground'));
  if (themeForeground && getContrastRatio(primary, themeForeground) >= 4.5) {
    return toRgbString(themeForeground);
  }

  return getContrastRatio(primary, FALLBACK_LIGHT) >= getContrastRatio(primary, FALLBACK_DARK)
    ? toRgbString(FALLBACK_LIGHT)
    : toRgbString(FALLBACK_DARK);
};

const normalizeVariantDisplayStyle = (
  value: unknown,
  isColor: boolean,
): VariantDisplayStyle => {
  const normalizedValue = String(value || '').trim().toLowerCase();

  if (
    normalizedValue === 'buttons' ||
    normalizedValue === 'circles' ||
    normalizedValue === 'dropdown' ||
    normalizedValue === 'thumbnails' ||
    normalizedValue === 'radio'
  ) {
    return normalizedValue;
  }

  return isColor ? 'circles' : 'buttons';
};

const parseVariantMetadata = (value: unknown): Record<string, unknown> => {
  if (isRecord(value)) {
    return value;
  }

  if (typeof value !== 'string' || !value.trim()) {
    return {};
  }

  try {
    const parsed = JSON.parse(value);
    return isRecord(parsed) ? parsed : {};
  } catch {
    return {};
  }
};

const parseVariantImages = (value: unknown): unknown[] => {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) {
      return [];
    }

    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) {
        return parsed;
      }
      return [parsed];
    } catch {
      return [trimmed];
    }
  }

  if (value) {
    return [value];
  }

  return [];
};

const normalizeColorToken = (raw: string) =>
  raw
    .trim()
    .toLowerCase()
    .replace(/أ|إ|آ/g, 'ا')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/ى/g, 'ي')
    .replace(/\s+/g, ' '); // normalize Arabic/spacing variants

const NORMALIZED_COLOR_PRESETS = Object.entries(COLOR_PRESETS).reduce<
  Record<string, string>
>((acc, [key, value]) => {
  acc[normalizeColorToken(key)] = value;
  return acc;
}, {});

const resolveColorValue = (option: string): string | null => {
  const normalized = normalizeColorToken(option);
  if (!normalized) {
    return null;
  }

  const exactMatch = NORMALIZED_COLOR_PRESETS[normalized];
  if (exactMatch) {
    return exactMatch;
  }

  const normalizedParts = normalized.split(/[\s/-]+/).filter(Boolean);
  const partialMatch = Object.entries(NORMALIZED_COLOR_PRESETS)
    .sort((left, right) => right[0].length - left[0].length)
    .find(([token]) => {
      if (!token) {
        return false;
      }

      if (normalized.includes(token) || token.includes(normalized)) {
        return true;
      }

      const tokenParts = token.split(/[\s/-]+/).filter(Boolean);
      return tokenParts.every((part) =>
        normalizedParts.some(
          (candidate) =>
            candidate === part ||
            candidate.includes(part) ||
            part.includes(candidate),
        ),
      );
    });

  return partialMatch?.[1] || null;
};

const getOptionMatch = <T,>(
  source: Record<string, T> | undefined,
  option: string,
): T | undefined => {
  if (!source) {
    return undefined;
  }

  if (source[option] !== undefined) {
    return source[option];
  }

  const normalizedOption = option.trim().toLowerCase();
  const matchedEntry = Object.entries(source).find(
    ([candidate]) => candidate.trim().toLowerCase() === normalizedOption,
  );

  return matchedEntry?.[1];
};

const VariantSelector: React.FC<VariantSelectorProps> = ({
  variants = [],
  selectedAttributes = {},
  onChange,
  density = 'default',
  layout = 'default',
  variantSettings,
}) => {
  const { theme } = useStorefrontTheme();
  const isZenOrganic = theme.id === 'zen-organic';
  const prefersArabicCopy = theme.direction === 'rtl';
  const isCompact = density === 'compact';
  const isInlineCompact = isCompact && layout === 'inline-compact';

  const [selectedTextColor, setSelectedTextColor] = React.useState<string | null>(
    () => resolveReadableSelectedTextColor(),
  );

  const normalizedStyles = React.useMemo(() => {
    if (!isRecord(variantSettings?.styles)) {
      return {} as Record<string, string>;
    }

    return Object.entries(variantSettings.styles).reduce<Record<string, string>>(
      (acc, [key, value]) => {
        const normalizedKey = canonicalizeAttributeKey(key);
        const normalizedValue = String(value || '').trim();

        if (normalizedKey && normalizedValue) {
          acc[normalizedKey] = normalizedValue;
        }

        return acc;
      },
      {},
    );
  }, [variantSettings?.styles]);

  const normalizedAttributeImages = React.useMemo(() => {
    if (!isRecord(variantSettings?.attributeImages)) {
      return {} as Record<string, Record<string, string>>;
    }

    return Object.entries(variantSettings.attributeImages).reduce<
      Record<string, Record<string, string>>
    >((acc, [key, value]) => {
      const normalizedKey = canonicalizeAttributeKey(key);
      if (!normalizedKey || !isRecord(value)) {
        return acc;
      }

      const valueMap = Object.entries(value).reduce<Record<string, string>>(
        (valueAcc, [option, imageValue]) => {
          const normalizedValue = normalizeStorefrontImageValue(imageValue as any);
          if (normalizedValue) {
            valueAcc[String(option)] = normalizedValue;
          }
          return valueAcc;
        },
        {},
      );

      if (Object.keys(valueMap).length > 0) {
        acc[normalizedKey] = valueMap;
      }

      return acc;
    }, {});
  }, [variantSettings?.attributeImages]);

  const variantOptionImages = React.useMemo(() => {
    return variants.reduce<Record<string, Record<string, string>>>((acc, variant) => {
      const attributes = getVariantAttributes(variant);
      const variantMetadata = parseVariantMetadata(variant.metadata);
      const primaryVariantImage =
        buildStorefrontImageCandidates(
          variantMetadata.image,
          variant.image,
          parseVariantImages(variant.images),
        )[0] || '';

      if (!primaryVariantImage) {
        return acc;
      }

      Object.entries(attributes).forEach(([key, value]) => {
        const normalizedKey = canonicalizeAttributeKey(key);
        if (!normalizedKey || !value) {
          return;
        }

        if (!acc[normalizedKey]) {
          acc[normalizedKey] = {};
        }

        if (!acc[normalizedKey][value]) {
          acc[normalizedKey][value] = primaryVariantImage;
        }
      });

      return acc;
    }, {});
  }, [variants]);

  const attributeKeys = React.useMemo(() => {
    const keys = new Set<string>();
    variants.forEach((variant) => {
      Object.keys(getVariantAttributes(variant)).forEach((key) => {
        const normalizedKey = canonicalizeAttributeKey(key);
        if (normalizedKey) {
          keys.add(normalizedKey);
        }
      });
    });
    return Array.from(keys);
  }, [variants]);

  React.useEffect(() => {
    if (typeof window === 'undefined') {
      return undefined;
    }

    const frame = window.requestAnimationFrame(() => {
      setSelectedTextColor(resolveReadableSelectedTextColor());
    });

    return () => window.cancelAnimationFrame(frame);
  }, [attributeKeys.length, variants.length]);

  const getOptionsForKey = (key: string) => {
    const values = new Set<string>();
    variants.forEach((variant) => {
      const option = getVariantAttributes(variant)[key];
      if (typeof option === 'string' && option.length > 0) {
        values.add(option);
      }
    });
    return Array.from(values);
  };

  const getOptionImage = (key: string, option: string) => {
    const configuredImage = getOptionMatch(normalizedAttributeImages[key], option);
    if (configuredImage) {
      return configuredImage;
    }

    return getOptionMatch(variantOptionImages[key], option) || '';
  };

  const handleSelect = (key: string, value: string) => {
    onChange({
      ...selectedAttributes,
      [key]: value,
    });
  };

  if (variants.length === 0) return null;

  const rootClassName = isInlineCompact ? 'space-y-2.5' : isCompact ? 'space-y-3.5' : 'space-y-6';
  const groupMarginClassName = isInlineCompact ? 'mb-0' : isCompact ? 'mb-2' : 'mb-3';
  const selectedValueClassName = isInlineCompact ? 'hidden' : isCompact ? 'text-[11px] font-bold' : '';

  return (
    <div className={rootClassName}>
      {attributeKeys.map((key) => {
        const options = getOptionsForKey(key);
        const isColor = key.toLowerCase() === 'color';
        const displayKey = getVariantAttributeLabel(key, prefersArabicCopy);
        const requestedDisplayStyle = normalizeVariantDisplayStyle(
          normalizedStyles[key],
          isColor,
        );
        const optionImages = options.reduce<Record<string, string>>((acc, option) => {
          acc[option] = getOptionImage(key, option);
          return acc;
        }, {});
        const hasAnyOptionImages = Object.values(optionImages).some(Boolean);
        const displayStyle =
          requestedDisplayStyle === 'thumbnails' && !hasAnyOptionImages
            ? isColor
              ? 'circles'
              : 'buttons'
            : requestedDisplayStyle;
        const inlineCompactOptionGridClass =
          options.length <= 2
            ? 'grid-cols-2'
            : options.length === 3
              ? 'grid-cols-3'
              : 'grid-cols-4';

        return (
          <div
            key={key}
            className={
              isInlineCompact && displayStyle !== 'thumbnails'
                ? 'flex w-full flex-col gap-y-1.5'
                : ''
            }
          >
            <label
              className={`block ${
                isInlineCompact
                  ? 'text-[10px] tracking-[0.12em]'
                  : isCompact
                    ? 'text-[9px] tracking-[0.16em]'
                    : 'text-[10px] tracking-widest'
              } font-black uppercase ${groupMarginClassName} ${
                isZenOrganic ? 'text-[#1a3328]' : 'text-foreground'
              } ${isInlineCompact ? 'w-full text-right' : ''}`}
            >
              {displayKey}:{' '}
              <span
                className={`${
                  isZenOrganic
                    ? 'text-[#1a3328]/40 ml-1'
                    : 'text-muted-foreground ml-1'
                } ${selectedValueClassName}`}
              >
                {selectedAttributes[key] || (prefersArabicCopy ? 'اختر' : 'Select')}
              </span>
            </label>

            {displayStyle === 'dropdown' ? (
              <select
                aria-label={
                  prefersArabicCopy ? `اختر ${displayKey}` : `Select ${displayKey}`
                }
                value={selectedAttributes[key] || ''}
                onChange={(event) => handleSelect(key, event.target.value)}
                className={`w-full rounded-[var(--radius)] border border-border bg-background text-foreground shadow-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/20 ${
                  isInlineCompact
                    ? 'px-3 py-2 text-[11px]'
                    : isCompact
                      ? 'px-3 py-2.5 text-xs'
                      : 'px-4 py-3 text-sm'
                }`}
              >
                <option value="" disabled>
                  {prefersArabicCopy ? `اختر ${displayKey}` : `Select ${displayKey}`}
                </option>
                {options.map((option) => (
                  <option key={option} value={option}>
                    {option}
                  </option>
                ))}
              </select>
            ) : displayStyle === 'radio' ? (
              <div
                className={`grid ${
                  isInlineCompact ? 'w-full justify-items-end gap-1' : isCompact ? 'gap-1.5' : 'gap-2'
                }`}
              >
                {options.map((option) => {
                  const isSelected = selectedAttributes[key] === option;
                  return (
                    <label
                      key={option}
                      className={`flex cursor-pointer items-center rounded-[var(--radius)] border transition-all duration-200 ${
                        isSelected
                          ? 'border-primary bg-primary/10 shadow-sm'
                          : 'border-border bg-background hover:border-primary/40'
                      } ${
                        isInlineCompact
                          ? 'gap-2 px-2.5 py-2'
                          : isCompact
                            ? 'gap-2.5 px-3 py-2.5'
                            : 'gap-3 px-4 py-3'
                      }`}
                      style={
                        isSelected && selectedTextColor && !isZenOrganic
                          ? { color: selectedTextColor }
                          : undefined
                      }
                    >
                      <input
                        type="radio"
                        name={`variant-${key}`}
                        value={option}
                        checked={isSelected}
                        onChange={() => handleSelect(key, option)}
                        aria-label={
                          prefersArabicCopy
                            ? `اختر ${displayKey} ${option}`
                            : `Select ${displayKey} ${option}`
                        }
                        className={`${isCompact ? 'h-3.5 w-3.5' : 'h-4 w-4'} border-border text-primary focus:ring-primary`}
                      />
                      <span
                        className={
                          isInlineCompact
                            ? 'text-[11px] font-semibold'
                            : isCompact
                              ? 'text-xs font-semibold'
                              : 'text-sm font-medium'
                        }
                      >
                        {option}
                      </span>
                    </label>
                  );
                })}
              </div>
            ) : (
              <div
                className={
                  isInlineCompact && displayStyle === 'buttons'
                    ? `grid w-full ${inlineCompactOptionGridClass} gap-2`
                    : `flex flex-wrap ${
                        isInlineCompact
                          ? 'w-full justify-end gap-1.5'
                          : isCompact
                            ? 'gap-1.5'
                            : 'gap-2'
                      }`
                }
                style={
                  isInlineCompact && displayStyle !== 'buttons'
                    ? { direction: 'ltr' }
                    : undefined
                }
              >
                {options.map((option) => {
                  const isSelected = selectedAttributes[key] === option;
                  const thumbnailImage =
                    displayStyle === 'thumbnails' ? optionImages[option] || '' : '';

                  if (displayStyle === 'thumbnails') {
                    return (
                      <button
                        key={option}
                        onClick={() => handleSelect(key, option)}
                        className={`flex flex-col items-center rounded-2xl border transition-all duration-200 ${
                          isSelected
                            ? 'border-primary bg-primary/5 ring-2 ring-primary/20'
                            : 'border-border bg-background hover:border-primary/40'
                        } ${
                          isInlineCompact
                            ? 'min-w-[4rem] gap-1 p-1.5'
                            : isCompact
                              ? 'min-w-[4.5rem] gap-1.5 p-1.5'
                              : 'min-w-[5.5rem] gap-2 p-2'
                        }`}
                        aria-label={
                          prefersArabicCopy
                            ? `اختر ${displayKey} ${option}`
                            : `Select ${displayKey} ${option}`
                        }
                      >
                        <div
                          className={`${
                            isInlineCompact
                              ? 'h-10 w-10 rounded-lg'
                              : isCompact
                                ? 'h-12 w-12 rounded-lg'
                                : 'h-16 w-16 rounded-xl'
                          } overflow-hidden bg-muted`}
                        >
                          {thumbnailImage ? (
                            <img
                              src={thumbnailImage}
                              alt={`${displayKey} ${option}`}
                              className="h-full w-full object-cover"
                            />
                          ) : (
                            <div className="flex h-full w-full items-center justify-center px-2 text-center text-[11px] font-bold text-muted-foreground">
                              {option}
                            </div>
                          )}
                        </div>
                        <span
                          className={`${
                            isInlineCompact
                              ? 'max-w-[3.5rem] text-[10px]'
                              : isCompact
                                ? 'max-w-[4rem] text-[11px]'
                                : 'max-w-[5rem] text-xs'
                          } truncate font-semibold text-foreground`}
                        >
                          {option}
                        </span>
                      </button>
                    );
                  }

                  if (displayStyle === 'circles') {
                    return (
                      <button
                        key={option}
                        onClick={() => handleSelect(key, option)}
                        className={`relative flex items-center justify-center overflow-hidden rounded-full border-2 font-bold transition-all duration-200 ${
                          isSelected
                            ? 'border-ring ring-2 ring-ring ring-offset-2 ring-offset-background scale-110'
                            : 'border-white/10 hover:border-primary/50 hover:scale-105'
                        } ${
                          isInlineCompact
                            ? 'h-10 w-10 text-[9px]'
                            : isCompact
                              ? 'h-8 w-8 text-[9px]'
                              : 'h-10 w-10 text-[10px]'
                        }`}
                        style={
                          isColor
                            ? {
                                background: resolveColorValue(option) || option.toLowerCase(),
                              }
                            : undefined
                        }
                        aria-label={
                          prefersArabicCopy
                            ? `اختر ${displayKey} ${option}`
                            : `Select ${displayKey} ${option}`
                        }
                        title={option}
                      >
                        {!isColor ? (
                          <span className="text-foreground">
                            {option.slice(0, 2).toUpperCase()}
                          </span>
                        ) : null}
                      </button>
                    );
                  }

                  return (
                    <button
                      key={option}
                      onClick={() => handleSelect(key, option)}
                        className={
                          isZenOrganic
                            ? `px-6 py-2 text-[13px] font-bold rounded-full transition-all duration-300 border ${
                                isSelected
                                  ? 'bg-[#1a3328] border-[#1a3328] text-white'
                                  : 'bg-transparent border-[#e9ebe5] text-[#1a3328]/40 hover:border-[#1a3328]/30'
                              }`
                          : `rounded-[var(--radius)] border transition-all duration-200 ${
                              isInlineCompact
                                ? 'min-h-[2.65rem] w-full px-0 py-2 text-[12px] font-black'
                                : isCompact
                                  ? 'min-w-[2.6rem] px-3 py-1.5 text-xs font-semibold'
                                : 'min-w-[3rem] px-4 py-2 text-sm font-medium'
                            } ${
                              isSelected
                                ? 'bg-primary border-primary shadow-sm'
                                : 'bg-background text-foreground border-border hover:border-muted-foreground'
                            }`
                      }
                      style={
                        isSelected && selectedTextColor && !isZenOrganic
                          ? { color: selectedTextColor }
                          : undefined
                      }
                      aria-label={
                        prefersArabicCopy
                          ? `اختر ${displayKey} ${option}`
                          : `Select ${displayKey} ${option}`
                      }
                    >
                      {option}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default VariantSelector;

import React from "react";
import * as Dialog from "@radix-ui/react-dialog";
import toast from "react-hot-toast";
import { storefrontFetch } from "../../utils/storefrontApi";
import { useStorefrontTheme } from "../engine/ThemeProvider";

interface WriteReviewDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  productId?: string;
  onSubmitted?: () => void;
}

type SelectedReviewMedia = {
  id: string;
  file: File;
  previewUrl: string;
  type: "image" | "video";
};

const MAX_REVIEW_MEDIA = 6;
const MAX_REVIEW_MEDIA_SIZE = 40 * 1024 * 1024;

const fieldClassName =
  "w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm text-foreground outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15";

const mediaPreviewCardClassName =
  "group relative overflow-hidden rounded-2xl border border-border bg-background";

const WriteReviewDialog: React.FC<WriteReviewDialogProps> = ({
  open,
  onOpenChange,
  productId,
  onSubmitted,
}) => {
  const { theme } = useStorefrontTheme();
  const prefersArabicCopy = theme.direction === "rtl";
  const [customerName, setCustomerName] = React.useState("");
  const [customerEmail, setCustomerEmail] = React.useState("");
  const [customerPhone, setCustomerPhone] = React.useState("");
  const [title, setTitle] = React.useState("");
  const [comment, setComment] = React.useState("");
  const [rating, setRating] = React.useState(5);
  const [selectedMedia, setSelectedMedia] = React.useState<SelectedReviewMedia[]>([]);
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const fileInputRef = React.useRef<HTMLInputElement | null>(null);
  const selectedMediaRef = React.useRef<SelectedReviewMedia[]>([]);
  const dialogBadge = prefersArabicCopy ? "مراجعة" : "Review";
  const dialogTitle = prefersArabicCopy ? "اكتب مراجعتك" : "Write a review";
  const dialogDescription = prefersArabicCopy
    ? "شارك تجربتك مع المنتج، ويمكنك إضافة صور أو فيديو لتكون المراجعة أوضح وأكثر إقناعًا."
    : "Share your experience, and add photos or video if you want your review to stand out on the product page.";
  const dialogDescriptionMobile = prefersArabicCopy
    ? "\u0623\u0636\u0641 \u062a\u0642\u064a\u064a\u0645\u0643 \u0648\u0645\u0644\u0627\u062d\u0638\u0627\u062a\u0643 \u0628\u0633\u0631\u0639\u0629\u060c \u0648\u0627\u0644\u0635\u0648\u0631 \u0623\u0648 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0627\u062e\u062a\u064a\u0627\u0631\u064a\u0629."
    : "Share a quick rating and optional media.";
  const closeLabel = prefersArabicCopy ? "إغلاق" : "Close";
  const ratingLabel = prefersArabicCopy ? "تقييمك" : "Your rating";
  const customerNameLabel = prefersArabicCopy ? "الاسم" : "Your name";
  const emailLabel = prefersArabicCopy ? "البريد الإلكتروني" : "Email";
  const phoneLabel = prefersArabicCopy ? "رقم الهاتف" : "Phone";
  const headlineLabel = prefersArabicCopy ? "عنوان المراجعة" : "Headline";
  const reviewLabel = prefersArabicCopy ? "محتوى المراجعة" : "Your review";
  const namePlaceholder = prefersArabicCopy ? "اكتب اسمك" : "Jane Doe";
  const emailPlaceholder = prefersArabicCopy ? "name@example.com" : "name@example.com";
  const phonePlaceholder = prefersArabicCopy ? "+20..." : "+20...";
  const headlinePlaceholder = prefersArabicCopy ? "ما أكثر شيء أعجبك؟" : "What stood out most?";
  const reviewPlaceholder = prefersArabicCopy
    ? "احكِ للمتسوقين الآخرين عن المقاس أو الجودة أو الشحن أو أي تفاصيل تستحق الذكر."
    : "Tell other shoppers what you liked, how it fit, delivery quality, and anything worth knowing.";
  const mediaTitle = prefersArabicCopy ? "صور أو فيديو" : "Photos or video";
  const mediaDescription = prefersArabicCopy
    ? "اختياري. يمكنك رفع حتى 6 صور أو فيديوهات، بحجم 40MB لكل ملف."
    : "Optional. Upload up to 6 images or videos, 40MB each.";
  const addMediaLabel = prefersArabicCopy ? "إضافة وسائط" : "Add media";
  const removeMediaLabel = prefersArabicCopy ? "إزالة" : "Remove";
  const emptyMediaText = prefersArabicCopy
    ? "أضف صور المنتج أو فيديو فتح الصندوق أو مقطع قصير يساعد العملاء على اتخاذ القرار."
    : "Add product photos, unboxing clips, or short fit videos to increase trust.";
  const moderationText = prefersArabicCopy
    ? "قد تظهر المراجعات مباشرة أو بعد المراجعة حسب إعدادات المتجر."
    : "Reviews may appear instantly or after moderation depending on store settings.";
  const submittingText = prefersArabicCopy ? "جارٍ الإرسال..." : "Submitting...";
  const submitLabel = prefersArabicCopy ? "إرسال المراجعة" : "Submit review";

  const revokeSelectedMedia = React.useCallback((items: SelectedReviewMedia[]) => {
    items.forEach((item) => {
      try {
        URL.revokeObjectURL(item.previewUrl);
      } catch {
        // Ignore object URL cleanup issues.
      }
    });
  }, []);

  const resetForm = React.useCallback(() => {
    setCustomerName("");
    setCustomerEmail("");
    setCustomerPhone("");
    setTitle("");
    setComment("");
    setRating(5);
    setSelectedMedia((current) => {
      revokeSelectedMedia(current);
      return [];
    });

    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  }, [revokeSelectedMedia]);

  React.useEffect(() => {
    selectedMediaRef.current = selectedMedia;
  }, [selectedMedia]);

  React.useEffect(() => {
    if (!open) {
      resetForm();
      return;
    }

    resetForm();
  }, [open, resetForm]);

  React.useEffect(
    () => () => {
      revokeSelectedMedia(selectedMediaRef.current);
    },
    [revokeSelectedMedia],
  );

  const handleMediaSelection = (event: React.ChangeEvent<HTMLInputElement>) => {
    const incomingFiles = Array.from(event.target.files || []);
    if (incomingFiles.length === 0) {
      return;
    }

    const remainingSlots = MAX_REVIEW_MEDIA - selectedMedia.length;
    if (remainingSlots <= 0) {
      toast.error(
        prefersArabicCopy
          ? `يمكنك رفع حتى ${MAX_REVIEW_MEDIA} صور أو فيديوهات فقط.`
          : `You can upload up to ${MAX_REVIEW_MEDIA} images or videos.`,
      );
      event.target.value = "";
      return;
    }

    const nextMedia: SelectedReviewMedia[] = [];

    incomingFiles.slice(0, remainingSlots).forEach((file) => {
      const isImage = file.type.startsWith("image/");
      const isVideo = file.type.startsWith("video/");

      if (!isImage && !isVideo) {
        toast.error(
          prefersArabicCopy
            ? `"${file.name}" ليس ملف صورة أو فيديو مدعومًا.`
            : `"${file.name}" is not a supported image or video file.`,
        );
        return;
      }

      if (file.size > MAX_REVIEW_MEDIA_SIZE) {
        toast.error(
          prefersArabicCopy
            ? `"${file.name}" يتجاوز حد الرفع المسموح وهو 40MB.`
            : `"${file.name}" exceeds the 40MB upload limit.`,
        );
        return;
      }

      nextMedia.push({
        id: `${file.name}-${file.lastModified}-${Math.random().toString(36).slice(2, 8)}`,
        file,
        previewUrl: URL.createObjectURL(file),
        type: isVideo ? "video" : "image",
      });
    });

    if (incomingFiles.length > remainingSlots) {
      toast.error(
        prefersArabicCopy
          ? `تمت إضافة أول ${remainingSlots} ملفات إضافية فقط.`
          : `Only the first ${remainingSlots} additional files were added.`,
      );
    }

    if (nextMedia.length > 0) {
      setSelectedMedia((current) => [...current, ...nextMedia].slice(0, MAX_REVIEW_MEDIA));
    }

    event.target.value = "";
  };

  const handleRemoveMedia = (mediaId: string) => {
    setSelectedMedia((current) => {
      const target = current.find((item) => item.id === mediaId);
      if (target) {
        revokeSelectedMedia([target]);
      }

      return current.filter((item) => item.id !== mediaId);
    });
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (!productId) {
      toast.error(
        prefersArabicCopy
          ? "هذا المنتج غير جاهز لاستقبال المراجعات الآن."
          : "This product is not ready for review submission yet.",
      );
      return;
    }

    if (!customerName.trim()) {
      toast.error(
        prefersArabicCopy
          ? "أضف اسمك قبل إرسال المراجعة."
          : "Add your name before submitting the review.",
      );
      return;
    }

    if (rating < 1 || rating > 5) {
      toast.error(
        prefersArabicCopy
          ? "اختر تقييمًا من 1 إلى 5 نجوم."
          : "Choose a rating from 1 to 5 stars.",
      );
      return;
    }

    try {
      setIsSubmitting(true);

      let response;
      if (selectedMedia.length > 0) {
        const formData = new FormData();
        formData.append("customerName", customerName.trim());
        if (customerEmail.trim()) {
          formData.append("customerEmail", customerEmail.trim());
        }
        if (customerPhone.trim()) {
          formData.append("customerPhone", customerPhone.trim());
        }
        formData.append("rating", String(rating));
        if (title.trim()) {
          formData.append("title", title.trim());
        }
        if (comment.trim()) {
          formData.append("comment", comment.trim());
        }
        selectedMedia.forEach((item) => {
          formData.append("media", item.file);
        });

        response = await storefrontFetch(
          `/products/${encodeURIComponent(productId)}/reviews`,
          {
            method: "POST",
            body: formData,
          },
        );
      } else {
        response = await storefrontFetch(
          `/products/${encodeURIComponent(productId)}/reviews`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              customerName: customerName.trim(),
              customerEmail: customerEmail.trim() || undefined,
              customerPhone: customerPhone.trim() || undefined,
              rating,
              title: title.trim() || undefined,
              comment: comment.trim() || undefined,
            }),
          },
        );
      }

      toast.success(
        String(
          response?.message ||
            (prefersArabicCopy
              ? "تم إرسال مراجعتك بنجاح."
              : "Your review has been submitted successfully."),
        ),
      );

      onOpenChange(false);
      onSubmitted?.();
    } catch (error: any) {
      const message =
        error?.response?.data?.error ||
        error?.message ||
        (prefersArabicCopy
          ? "تعذر إرسال مراجعتك الآن."
          : "Unable to submit your review right now.");
      toast.error(String(message));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-[90] bg-background/80 backdrop-blur-sm animate-in fade-in duration-200" />
        <Dialog.Content
          className="fixed inset-x-0 bottom-0 z-[91] flex max-h-[82dvh] flex-col overflow-hidden rounded-t-[1.75rem] border border-border bg-card shadow-2xl animate-in slide-in-from-bottom duration-200 sm:left-[50%] sm:top-[50%] sm:w-[calc(100vw-2rem)] sm:max-h-[calc(100vh-2rem)] sm:max-w-xl sm:translate-x-[-50%] sm:translate-y-[-50%] sm:rounded-[1.5rem] sm:zoom-in-95"
        >
          <div className="mx-auto mt-2 h-1.5 w-14 rounded-full bg-border/80 sm:hidden" aria-hidden="true" />
          <div className="flex items-start justify-between gap-3 border-b border-border px-4 pb-3 pt-3 sm:gap-4 sm:px-6 sm:pb-5 sm:pt-6">
            <div className="min-w-0">
              <span className="inline-flex rounded-full bg-primary/10 px-3 py-1 text-[11px] font-bold uppercase tracking-[0.18em] text-primary">
                {dialogBadge}
              </span>
              <Dialog.Title className="mt-2.5 text-lg font-black text-foreground sm:mt-3 sm:text-2xl">
                {dialogTitle}
              </Dialog.Title>
              <p className="mt-1.5 text-sm leading-5 text-muted-foreground sm:hidden">
                {dialogDescriptionMobile}
              </p>
              <p className="mt-2 hidden text-sm leading-6 text-muted-foreground sm:block">
                {dialogDescription}
              </p>
            </div>
            <Dialog.Close className="inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-border text-sm font-semibold text-muted-foreground transition hover:text-foreground sm:h-auto sm:w-auto sm:px-3 sm:py-2">
              <span aria-hidden="true" className="sm:hidden">X</span>
              <span className="hidden sm:inline">{closeLabel}</span>
              <span className="sr-only sm:hidden">{closeLabel}</span>
            </Dialog.Close>
          </div>

          <form className="flex min-h-0 flex-1 flex-col" onSubmit={handleSubmit}>
            <div className="min-h-0 flex-1 overflow-y-auto px-4 pb-5 pt-4 sm:px-6 sm:pb-6">
              <div className="space-y-4 sm:space-y-5">
                <div className="space-y-2">
              <label className="text-sm font-semibold text-foreground">{ratingLabel}</label>
              <div className="flex flex-wrap items-center gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => setRating(star)}
                    className={`min-w-[2.625rem] rounded-full px-3 py-2 text-sm font-bold leading-none transition sm:min-w-[3rem] ${
                      star <= rating
                        ? "bg-amber-100 text-amber-700"
                        : "bg-secondary text-muted-foreground"
                    }`}
                  >
                    {star}★
                  </button>
                ))}
              </div>
            </div>

                <div className="grid gap-3 sm:grid-cols-2 sm:gap-4">
              <label className="block space-y-2">
                <span className="text-sm font-semibold text-foreground">{customerNameLabel}</span>
                <input
                  className={fieldClassName}
                  value={customerName}
                  onChange={(event) => setCustomerName(event.target.value)}
                  autoComplete="name"
                  placeholder={namePlaceholder}
                />
              </label>

              <label className="block space-y-2">
                <span className="text-sm font-semibold text-foreground">{emailLabel}</span>
                <input
                  className={fieldClassName}
                  value={customerEmail}
                  onChange={(event) => setCustomerEmail(event.target.value)}
                  autoComplete="email"
                  inputMode="email"
                  placeholder={emailPlaceholder}
                />
              </label>
            </div>

                <div className="grid gap-3 sm:grid-cols-2 sm:gap-4">
              <label className="block space-y-2">
                <span className="text-sm font-semibold text-foreground">{phoneLabel}</span>
                <input
                  className={fieldClassName}
                  value={customerPhone}
                  onChange={(event) => setCustomerPhone(event.target.value)}
                  autoComplete="tel"
                  inputMode="tel"
                  placeholder={phonePlaceholder}
                />
              </label>

              <label className="block space-y-2">
                <span className="text-sm font-semibold text-foreground">{headlineLabel}</span>
                <input
                  className={fieldClassName}
                  value={title}
                  onChange={(event) => setTitle(event.target.value)}
                  placeholder={headlinePlaceholder}
                />
              </label>
            </div>

            <label className="block space-y-2">
              <span className="text-sm font-semibold text-foreground">{reviewLabel}</span>
              <textarea
                className={`${fieldClassName} min-h-[7.5rem] resize-y sm:min-h-32`}
                value={comment}
                onChange={(event) => setComment(event.target.value)}
                placeholder={reviewPlaceholder}
              />
            </label>

                <div className="space-y-3 rounded-[1.25rem] border border-dashed border-border bg-background/60 p-3.5 sm:p-4">
              <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <h3 className="text-sm font-semibold text-foreground">{mediaTitle}</h3>
                  <p className="text-xs text-muted-foreground">
                    {mediaDescription}
                  </p>
                </div>
                <label className="inline-flex w-full cursor-pointer items-center justify-center rounded-xl border border-border bg-card px-4 py-2 text-sm font-semibold text-foreground transition hover:border-primary hover:text-primary sm:w-auto">
                  {addMediaLabel}
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*,video/*"
                    multiple
                    className="sr-only"
                    onChange={handleMediaSelection}
                  />
                </label>
              </div>

              {selectedMedia.length > 0 ? (
                <div className="grid grid-cols-2 gap-2.5 sm:grid-cols-3 sm:gap-3">
                  {selectedMedia.map((item) => (
                    <div key={item.id} className={mediaPreviewCardClassName}>
                      {item.type === "video" ? (
                        <video
                          src={item.previewUrl}
                          poster={undefined}
                          muted
                          playsInline
                          controls
                          className="h-24 w-full bg-black object-cover sm:h-28"
                        />
                      ) : (
                        <img
                          src={item.previewUrl}
                          alt={item.file.name}
                          className="h-24 w-full object-cover sm:h-28"
                        />
                      )}
                      <button
                        type="button"
                        onClick={() => handleRemoveMedia(item.id)}
                        className="absolute right-1.5 top-1.5 rounded-full bg-black/70 px-2 py-1 text-[11px] font-bold text-white transition hover:bg-black sm:right-2 sm:top-2"
                      >
                        {removeMediaLabel}
                      </button>
                      <div className="space-y-1 p-2.5 sm:p-3">
                        <p className="line-clamp-1 text-xs font-semibold text-foreground">
                          {item.file.name}
                        </p>
                        <p className="text-[11px] text-muted-foreground">
                          {item.type === "video"
                            ? prefersArabicCopy
                              ? "فيديو"
                              : "Video"
                            : prefersArabicCopy
                              ? "صورة"
                              : "Image"}{" "}
                          •{" "}
                          {(item.file.size / (1024 * 1024)).toFixed(1)} MB
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="rounded-2xl border border-border/70 bg-card/70 px-4 py-4 text-center text-xs text-muted-foreground sm:py-5">
                  {emptyMediaText}
                </div>
              )}
                </div>
              </div>
            </div>

            <div className="border-t border-border bg-card px-4 pb-[calc(env(safe-area-inset-bottom,0px)+0.875rem)] pt-3 sm:px-6 sm:pb-6 sm:pt-4">
              <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <p className="text-xs text-muted-foreground">
                {moderationText}
              </p>
              <button
                type="submit"
                disabled={isSubmitting}
                className="inline-flex w-full items-center justify-center rounded-2xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground transition hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-60 sm:w-auto"
              >
                {isSubmitting ? submittingText : submitLabel}
              </button>
              </div>
            </div>
          </form>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
};

export default WriteReviewDialog;

import React from 'react';
import { STOREFRONT_SECTION_MANIFEST } from '../sections/manifest';

// ALL sections are now lazy-loaded for optimal code splitting.
// Previously HeroBanner (99KB), PromoStrip, ShopCommandBar were eager — this
// caused them to ship in every storefront route even when unused (e.g. PDP).
const HeroBanner = React.lazy(() => import('../sections/HeroBanner'));
const PromoStrip = React.lazy(() => import('../sections/PromoStrip'));
const ShopCommandBar = React.lazy(() => import('../sections/ShopCommandBar'));
const ProductGrid = React.lazy(() => import('../sections/ProductGrid'));
const Newsletter = React.lazy(() => import('../sections/Newsletter'));
const LookbookShowcase = React.lazy(() => import('../sections/LookbookShowcase'));
const FeaturedCollections = React.lazy(() => import('../sections/FeaturedCollections'));
const FiltersSidebar = React.lazy(() => import('../sections/FiltersSidebar'));
const ShopPromoRail = React.lazy(() => import('../sections/ShopPromoRail'));
const ProductGallery = React.lazy(() => import('../sections/ProductGallery'));
const ProductInfo = React.lazy(() => import('../sections/ProductInfo'));
const QuantityOffersSection = React.lazy(() => import('../sections/QuantityOffersSection'));
const ConversionStack = React.lazy(() => import('../sections/ConversionStack'));
const SizeGuide = React.lazy(() => import('../sections/SizeGuide'));
const BoughtTogetherSection = React.lazy(() => import('../sections/BoughtTogetherSection'));
const RelatedProducts = React.lazy(() => import('../sections/RelatedProducts'));
const ReviewsSection = React.lazy(() => import('../sections/ReviewsSection'));
const CartItems = React.lazy(() => import('../sections/CartItems'));
const OrderSummary = React.lazy(() => import('../sections/OrderSummary'));
const CheckoutForm = React.lazy(() => import('../sections/CheckoutForm'));
const PaymentSection = React.lazy(() => import('../sections/PaymentSection'));
