/**
 * Central registry mapping JSON section IDs to React components.
 * The PageComposer reads `theme.pages.<pageType>.sections` array and
 * resolves each string key through this map.
 */
export const ComponentRegistry: Record<
  string,
  React.ComponentType<any>
> = Object.entries(STOREFRONT_SECTION_MANIFEST).reduce(
  (registry, [sectionId, sectionConfig]) => {
    const sectionComponent = baseComponentRegistry[sectionConfig.component];
    if (sectionComponent) {
      registry[sectionId] = sectionComponent;
    }
    return registry;
  },
  { ...baseComponentRegistry },
);

import React, { createContext, useContext, useEffect, useState } from 'react';
import { StorefrontTheme } from '../types/theme.types';
import { resolveStorefrontTheme, StorefrontThemeInput } from './themeResolver';

interface ThemeContextType {
  theme: StorefrontTheme;
  setTheme: (theme: StorefrontTheme) => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const StorefrontThemeProvider: React.FC<{ 
  children: React.ReactNode, 
  initialTheme?: StorefrontThemeInput,
  scoped?: boolean 
}> = ({ children, initialTheme, scoped = true }) => {
  const [theme, setTheme] = useState<StorefrontTheme>(() =>
    resolveStorefrontTheme(initialTheme),
  );

  useEffect(() => {
    setTheme(resolveStorefrontTheme(initialTheme));
  }, [initialTheme]);

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      // In a real production app we'd verify origin, but for this preview modal we allow it
      if (event.data?.type === 'UPDATE_PREVIEW_TOKENS' && event.data?.payload) {
        setTheme((currentTheme) => ({
          ...currentTheme,
          tokens: {
            ...currentTheme.tokens,
            ...event.data.payload,
          },
          pages: {
            ...currentTheme.pages,
            home: event.data.payload.home || currentTheme.pages.home,
          }
        }));
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  useEffect(() => {
    const targetElement = scoped ? document.getElementById('storefront-engine-root') : document.documentElement;
    
    if (!targetElement) return;

    const setVar = (key: string, value: string) => {
      targetElement.style.setProperty(key, value);
    };

    // 1. Apply Colors
    if (theme.tokens?.colors) {
      Object.entries(theme.tokens.colors).forEach(([key, value]) => {
        // Handle kebab-case conversion (e.g. primaryForeground -> --primary-foreground)
        const kebabKey = key.replace(/([a-z0-9]|(?=[A-Z]))([A-Z])/g, '$1-$2').toLowerCase();
        setVar(`--${kebabKey}`, value as string);
        
        // Ensure standard tailwind-style names are also available
        if (key === 'primary') setVar('--primary', value as string);
        if (key === 'foreground') setVar('--foreground', value as string);
        if (key === 'background') setVar('--background', value as string);
      });
    }

    // 2. Apply Typography
    if (theme.tokens?.typography) {
      if (theme.tokens.typography.bodyFont) setVar('--font-sans', theme.tokens.typography.bodyFont);
      if (theme.tokens.typography.headingFont) setVar('--font-heading', theme.tokens.typography.headingFont);
      if (theme.tokens.typography.baseSize) setVar('--base-font-size', theme.tokens.typography.baseSize);
    }

    // 3. Apply Shape
    if (theme.tokens?.shape) {
      if (theme.tokens.shape.borderRadius) setVar('--radius', theme.tokens.shape.borderRadius);
      if (theme.tokens.shape.buttonRadius) setVar('--button-radius', theme.tokens.shape.buttonRadius);
    }

    // 4. Apply Product Card tokens
    if (theme.tokens?.productCard) {
      if (theme.tokens.productCard.borderRadius) setVar('--product-card-radius', theme.tokens.productCard.borderRadius);
      if (theme.tokens.productCard.boxShadow) setVar('--product-card-shadow', theme.tokens.productCard.boxShadow);
      if (theme.tokens.productCard.hoverShadow) setVar('--product-card-hover-shadow', theme.tokens.productCard.hoverShadow);
      if (theme.tokens.productCard.badgeRadius) setVar('--product-card-badge-radius', theme.tokens.productCard.badgeRadius);
      if (theme.tokens.productCard.buttonRadius) setVar('--product-card-button-radius', theme.tokens.productCard.buttonRadius);
      if (theme.tokens.productCard.surfaceOpacity) setVar('--product-card-surface-opacity', theme.tokens.productCard.surfaceOpacity);
    }

  }, [theme, scoped]);

  // Dynamically load only the Google Fonts required by the active theme
  useEffect(() => {
    if (!theme?.tokens?.typography) return;

    const { headingFont, bodyFont } = theme.tokens.typography;
    const fontsToLoad = new Set<string>();

    // Skip system/generic fonts and fonts already bundled (Inter, IBM Plex)
    const BUNDLED_FONTS = new Set([
      'inter', 'ibm plex sans arabic', 'system-ui', 'sans-serif',
      'serif', 'monospace', 'geist variable', 'dejavu sans',
      'dejavu sans bold',
    ]);

    const extractFontFamily = (fontStack: string): string | null => {
      // Get the first font from a CSS font stack like "'Outfit', sans-serif"
      const first = fontStack.split(',')[0]?.trim().replace(/['"]/g, '');
      if (!first || BUNDLED_FONTS.has(first.toLowerCase())) return null;
      return first;
    };

    if (headingFont) {
      const font = extractFontFamily(headingFont);
      if (font) fontsToLoad.add(font);
    }
    if (bodyFont) {
      const font = extractFontFamily(bodyFont);
      if (font) fontsToLoad.add(font);
    }

    if (fontsToLoad.size === 0) return;

    // Build Google Fonts URL for only the needed fonts
    const families = Array.from(fontsToLoad)
      .map((f) => `family=${f.replace(/ /g, '+')}:wght@400;500;600;700`)
      .join('&');
    const href = `https://fonts.googleapis.com/css2?${families}&display=swap`;

    const LINK_ID = 'storefront-theme-fonts';
    let linkEl = document.getElementById(LINK_ID) as HTMLLinkElement | null;

    if (linkEl) {
      if (linkEl.href === href) return; // same fonts, skip
      linkEl.href = href;
    } else {
      linkEl = document.createElement('link');
      linkEl.id = LINK_ID;
      linkEl.rel = 'stylesheet';
      linkEl.href = href;
      document.head.appendChild(linkEl);
    }
  }, [theme?.tokens?.typography?.headingFont, theme?.tokens?.typography?.bodyFont]);

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      <div 
        id="storefront-engine-root" 
        className="storefront-container isolation-auto min-h-screen bg-background text-foreground"
        style={{ fontFamily: 'var(--font-sans)' }}
      >
        {children}
      </div>
    </ThemeContext.Provider>
  );
};

export const useStorefrontTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useStorefrontTheme must be used within a StorefrontThemeProvider');
  }
  return context;
};

import { useQuery } from '@tanstack/react-query';
import { getStorefrontScope, storefrontFetch } from '../../utils/storefrontApi';
import {
  getMarketplacePreviewProducts,
  resolveMarketplacePreviewThemeId,
} from '../preview/marketplaceSampleData';
import {
  filterThemePreviewProducts,
  resolveActiveThemePreviewDataset,
  resolveThemeCatalogPreviewKey,
} from '../preview/themePreviewData';
import {
  getProductImageCandidates,
  normalizeStorefrontImageValue,
} from '../utils/productImages';

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  comparePrice?: number;
  images: string[];
  slug: string;
  categoryId?: string;
  category?: {
    id: string;
    name: string;
  };
  productVariants?: ProductVariant[];
  variants?: ProductVariant[];
  [key: string]: any;
}

export interface ProductVariant {
  id: string;
  name: string;
  price?: number | null;
  comparePrice?: number | null;
  sku?: string;
  attributes?: Record<string, string> | null;
  attributeValues?: Record<string, string> | string | null;
  [key: string]: any;
}

export interface ProductsParams {
  [key: string]: string | number | boolean | undefined;
  page?: number;
  limit?: number;
  category?: string;
  search?: string;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
  minPrice?: number;
  maxPrice?: number;
}

interface UseProductsOptions {
  enabled?: boolean;
}

interface ProductsResponse {
  data: Product[];
  pagination: {
    total: number;
    page: number;
    limit: number;
    pages: number;
  };
}

type StorefrontProductPayload = Product & {
  images?: unknown;
  mainImage?: unknown;
  image?: unknown;
};

type StorefrontProductVariantPayload = ProductVariant & {
  price?: unknown;
  comparePrice?: unknown;
  image?: unknown;
};

const toFiniteNumber = (value: unknown, fallback = 0) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const toOptionalFiniteNumber = (value: unknown) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
};

export const normalizeStorefrontProductVariant = (
  variant: StorefrontProductVariantPayload,
): ProductVariant => ({
  ...variant,
  price: toOptionalFiniteNumber(variant.price),
  comparePrice: toOptionalFiniteNumber(variant.comparePrice),
  image: normalizeStorefrontImageValue(variant.image),
});

export const normalizeStorefrontProduct = (
  product: StorefrontProductPayload,
): Product => {
  const normalizedVariants = Array.isArray(product.productVariants)
    ? product.productVariants.map((variant) =>
        normalizeStorefrontProductVariant(variant),
      )
    : undefined;
  const normalizedLegacyVariants = Array.isArray(product.variants)
    ? product.variants.map((variant) =>
        normalizeStorefrontProductVariant(variant),
      )
    : normalizedVariants;

  return {
    ...product,
    price: toFiniteNumber(product.price, 0),
    comparePrice: toOptionalFiniteNumber(product.comparePrice),
    mainImage: normalizeStorefrontImageValue(product.mainImage),
    images: getProductImageCandidates(product),
    productVariants: normalizedVariants,
    variants: normalizedLegacyVariants,
  };
};

const resolveStorefrontProductsPreviewKey = (): string => {
  const themePreviewKey = resolveThemeCatalogPreviewKey();
  if (themePreviewKey) {
    return themePreviewKey;
  }

  const marketplacePreviewThemeId = resolveMarketplacePreviewThemeId();
  return marketplacePreviewThemeId ? `marketplace:${marketplacePreviewThemeId}` : '';
};

export const useProducts = (
  params: ProductsParams = {},
  companyIdOverride?: string | null,
  options: UseProductsOptions = {},
) => {
  const storefrontScope = getStorefrontScope(companyIdOverride);
  const enabled = options.enabled ?? true;
  const previewKey = resolveStorefrontProductsPreviewKey();

  const { data, isLoading, error } = useQuery<ProductsResponse>({
    queryKey: ['storefront', 'products', storefrontScope, previewKey, params],
    queryFn: async () => {
      const previewDataset = resolveActiveThemePreviewDataset();
      if (previewDataset) {
        return filterThemePreviewProducts(previewDataset, params);
      }

      const marketplacePreviewThemeId = resolveMarketplacePreviewThemeId();
      const previewData = getMarketplacePreviewProducts(params, marketplacePreviewThemeId);
      if (previewData) {
        return previewData;
      }

      const response = await storefrontFetch('/products', {
        companyId: companyIdOverride,
        query: params,
      });
      if (response.success) {
        const normalizedData = (response.data || []).map(
          (p: StorefrontProductPayload) => normalizeStorefrontProduct(p),
        );

        return {
          data: normalizedData,
          pagination: response.pagination,
        };
      }
      throw new Error(response.message || 'Failed to fetch products');
    },
    staleTime: 60 * 1000,
    enabled,
  });

  return {
    products: data?.data || [],
    pagination: data?.pagination || { total: 0, page: 1, limit: 12, pages: 1 },
    isLoading,
    error: error as Error | null,
  };
};

