    <section
      className={`w-full ${compactCatalogPills ? "py-5 md:py-6" : "py-10 md:py-14"} ${
        isSoleaFemme
          ? "bg-[linear-gradient(180deg,hsl(var(--background))_0%,hsl(var(--secondary)/0.72)_42%,hsl(var(--background))_100%)]"
          : isBiteRush
