const useSwipe = (
  imagesLength: number,
  setActiveIndex: React.Dispatch<React.SetStateAction<number>>,
) => {
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);

  const minSwipeDistance = 50;

  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0]?.clientX ?? null);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0]?.clientX ?? null);
  };

  const onTouchEndHandler = () => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) {
      setActiveIndex((p: number) => (p === imagesLength - 1 ? 0 : p + 1));
    }
    if (isRightSwipe) {
      setActiveIndex((p: number) => (p === 0 ? imagesLength - 1 : p - 1));
    }
  };

  return { onTouchStart, onTouchMove, onTouchEnd: onTouchEndHandler };
};

interface OptimizedGalleryImageProps extends Omit<
  React.ImgHTMLAttributes<HTMLImageElement>,
  "src"
> {
  source?: string | null;
  mode?: "hero" | "detail" | "thumb";
  responsiveSizes?: string;
  fetchpriority?: "high" | "low" | "auto";
  productName?: string;
  categoryLabel?: string;
  fallbackVariant?: "default" | "cyber";
  prefersArabicCopy?: boolean;
}

const OptimizedGalleryImage: React.FC<OptimizedGalleryImageProps> = ({
  source,
  mode = "detail",
  responsiveSizes,
  productName,
  categoryLabel,
  fallbackVariant = "default",
  prefersArabicCopy,
  ...imgProps
}) => {
  return (
    <StorefrontProductImage
      candidates={[source]}
      requestedWidth={mode === "thumb" ? 160 : mode === "hero" ? 1200 : 800}
      responsiveWidths={
        mode === "thumb"
          ? undefined
          : mode === "hero"
            ? [480, 800, 1200, 1600]
            : [320, 480, 640, 800, 1200]
      }
      responsiveSizes={
        mode === "thumb" ? undefined : responsiveSizes || "100vw"
      }
      imageQuality={mode === "thumb" ? 68 : mode === "hero" ? 80 : 76}
      fallback={
        fallbackVariant === "cyber" ? (
          <CyberGalleryImageFallback
            productName={productName}
            categoryLabel={categoryLabel}
            prefersArabicCopy={prefersArabicCopy}
          />
        ) : (
          <GalleryImageFallback
            productName={productName}
            prefersArabicCopy={prefersArabicCopy}
          />
        )
      }
      {...imgProps}
    />
  );
};

