                  loading="lazy"
                  fetchpriority="low"
                  decoding="async"
                  mode="thumb"
                  className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.03]"
                  productName={product?.name}
                />
              </button>
            ))}
          </div>
        ) : null}
      </div>
    </div>
  );
};

