        <motion.button
          whileTap={{ scale: 0.95 }}
          animate={{
            boxShadow: [
              "0 0 0 0px hsl(var(--primary)/0.4)",
              "0 0 0 10px hsl(var(--primary)/0)",
              "0 0 0 0px hsl(var(--primary)/0)"
