        y: [0, -10, 0],
        rotate: [0, 5, 0],
      }}
      transition={{
        duration: 4,
        repeat: Infinity,
        ease: "easeInOut",
      }}
      className="absolute -right-8 -top-8 h-20 w-20 opacity-20 drop-shadow-xl"
    >
      <svg viewBox="0 0 100 100" className="h-full w-full fill-primary">
