      </svg>
    ))}
  </div>
);

interface ReviewsSectionProps {
  section?: {
    variant?: string;
    [key: string]: unknown;
  };
  settings?: {
    title?: string;
    writeReviewText?: string;
    emptyText?: string;
    verifiedLabel?: string;
    outOfText?: string;
