  const [isReviewDialogOpen, setIsReviewDialogOpen] = React.useState(false);

  const rawMockReviews = (Array.isArray(settings?.['reviews']) ? settings?.['reviews'] : []) as unknown[];
  const mockReviews = React.useMemo(
