// Date formatting utilities with Gregorian calendar support

export type DateFormatType = "gregorian";

export interface DateFormatOptions {
  format: DateFormatType;
  locale?: string;
  options?: Intl.DateTimeFormatOptions;
}

// Default date format options
export const DEFAULT_DATE_FORMAT: DateFormatType = "gregorian";

// Date format configurations
export const DATE_FORMAT_CONFIGS = {
  gregorian: {
    locale: "ar-EG", // Arabic locale with Gregorian calendar
    options: {
      year: "numeric" as const,
      month: "long" as const,
      day: "numeric" as const,
      calendar: "gregory" as const,
    },
  },
};

// Format date based on the specified format type
export const formatDate = (
  date: Date | string | number,
  formatType: DateFormatType = DEFAULT_DATE_FORMAT,
  customOptions?: Intl.DateTimeFormatOptions,
): string => {
  try {
    const dateObj = new Date(date);

    if (isNaN(dateObj.getTime())) {
      return "تاريخ غير صحيح";
    }

    const config = DATE_FORMAT_CONFIGS[formatType];
    const options =
      customOptions || (config.options as Intl.DateTimeFormatOptions);

    // Apply timezone if provided
    const finalOptions: Intl.DateTimeFormatOptions = { ...options };
    if (customOptions?.timeZone) {
      finalOptions.timeZone = customOptions.timeZone;
    }

    return dateObj.toLocaleDateString(config.locale, finalOptions);
  } catch (error) {
    console.error("Error formatting date:", error);
    return "تاريخ غير صحيح";
  }
};

// Format time
export const formatTime = (
  date: Date | string | number,
  locale: string = "ar-EG",
): string => {
  try {
    const dateObj = new Date(date);

    if (isNaN(dateObj.getTime())) {
      return "وقت غير صحيح";
    }

    return dateObj.toLocaleTimeString(locale, {
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
      timeZone:
        typeof date === "string" ||
        typeof date === "number" ||
        date instanceof Date
          ? undefined
          : (date as any).timeZone,
    });
  } catch (error) {
    console.error("Error formatting time:", error);
    return "وقت غير صحيح";
  }
};

// Format time with explicit timezone support
export const formatTimeWithZone = (
  date: Date | string | number,
  timezone?: string,
  locale: string = "ar-EG",
): string => {
  try {
    const dateObj = new Date(date);

    if (isNaN(dateObj.getTime())) {
      return "وقت غير صحيح";
    }

    const options: Intl.DateTimeFormatOptions = {
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    };

    if (timezone) {
      options.timeZone = timezone;
    }

    return dateObj.toLocaleTimeString(locale, options);
  } catch (error) {
    console.error("Error formatting time:", error);
    return "وقت غير صحيح";
  }
};

// Format date and time together
export const formatDateTime = (
  date: Date | string | number,
  formatType: DateFormatType = DEFAULT_DATE_FORMAT,
): string => {
  const formattedDate = formatDate(date, formatType);
  const formattedTime = formatTime(date);

  return `${formattedDate} - ${formattedTime}`;
};

// Get relative time (time ago)
export const getTimeAgo = (date: Date | string | number): string => {
  try {
    const dateObj = new Date(date);
    const now = new Date();
    const diffMs = now.getTime() - dateObj.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);
    const diffWeeks = Math.floor(diffDays / 7);
    const diffMonths = Math.floor(diffDays / 30);

    if (diffMins < 1) return "الآن";
    if (diffMins < 60) return `منذ ${diffMins} دقيقة`;
    if (diffHours < 24) return `منذ ${diffHours} ساعة`;
    if (diffDays < 7) return `منذ ${diffDays} يوم`;
    if (diffWeeks < 4) return `منذ ${diffWeeks} أسبوع`;
    if (diffMonths < 12) return `منذ ${diffMonths} شهر`;

    const diffYears = Math.floor(diffMonths / 12);
    return `منذ ${diffYears} سنة`;
  } catch (error) {
    console.error("Error calculating time ago:", error);
    return "منذ وقت غير محدد";
  }
};

// Date format display names for UI
export const DATE_FORMAT_LABELS = {
  gregorian: "ميلادي (Gregorian)",
};

// Validate date format type
export const isValidDateFormat = (format: string): format is DateFormatType => {
  return format === "gregorian";
};

// Get current date in specified format
export const getCurrentDate = (
  formatType: DateFormatType = DEFAULT_DATE_FORMAT,
): string => {
  return formatDate(new Date(), formatType);
};

// Parse date format from company settings
export const parseDateFormatFromSettings = (settings: any): DateFormatType => {
  if (settings?.dateFormat && isValidDateFormat(settings.dateFormat)) {
    return settings.dateFormat;
  }
  return DEFAULT_DATE_FORMAT;
};

import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

export interface ExportColumn {
  key: string;
  label: string;
}

export const exportToCSV = (
  data: any[],
  columns: ExportColumn[],
  filename: string = 'export.csv'
) => {
  // Create CSV content
  const headers = columns.map((col) => col.label).join(',');
  const rows = data.map((row) =>
    columns.map((col) => {
      const value = row[col.key];
      // Escape commas and quotes
      if (typeof value === 'string' && (value.includes(',') || value.includes('"'))) {
        return `"${value.replace(/"/g, '""')}"`;
      }
      return value ?? '';
    }).join(',')
  );

  const csvContent = [headers, ...rows].join('\\n');

  // Download
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
};

export const exportToExcel = (
  data: any[],
  columns: ExportColumn[],
  filename: string = 'export.xlsx',
  sheetName: string = 'Sheet1'
) => {
  // Prepare data for Excel
  const excelData = data.map((row) => {
    const excelRow: any = {};
    columns.forEach((col) => {
      excelRow[col.label] = row[col.key];
    });
    return excelRow;
  });

  // Create workbook and worksheet
  const worksheet = XLSX.utils.json_to_sheet(excelData);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);

  // Auto-size columns
  const maxWidth = 50;
  const colWidths = columns.map((col) => {
    const maxLength = Math.max(
      col.label.length,
      ...data.map((row) => String(row[col.key] ?? '').length)
    );
    return { wch: Math.min(maxLength + 2, maxWidth) };
  });
  worksheet['!cols'] = colWidths;

  // Download
  XLSX.writeFile(workbook, filename);
};

export const exportToPDF = (
  data: any[],
  columns: ExportColumn[],
  title: string = 'تقرير',
  filename: string = 'export.pdf'
) => {
  const doc = new jsPDF({
    orientation: 'landscape',
  });

  // Add title
  doc.setFontSize(18);
  doc.text(title, 14, 20);

  // Add date
  doc.setFontSize(10);
  doc.text(`تاريخ التصدير: ${new Date().toLocaleDateString('ar-EG')}`, 14, 28);

  // Prepare table data
  const headers = columns.map((col) => col.label);
  const rows = data.map((row) =>
    columns.map((col) => String(row[col.key] ?? ''))
  );

  // Add table
  autoTable(doc, {
    head: [headers],
    body: rows,
    startY: 35,
    styles: {
      font: 'helvetica',
      fontSize: 10,
    },
    headStyles: {
      fillColor: [59, 130, 246], // Blue
      textColor: 255,
      fontStyle: 'bold',
    },
    alternateRowStyles: {
      fillColor: [245, 247, 250],
    },
  });

  // Download
  doc.save(filename);
};

export const printTable = (
  data: any[],
  columns: ExportColumn[],
  title: string = 'تقرير'
) => {
  // Verify we are in a browser environment
  if (typeof window === 'undefined') return;

  // Helper to escape HTML to prevent XSS
  const escapeHtml = (unsafe: any): string => {
    if (unsafe === null || unsafe === undefined) return '';
    return String(unsafe)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  };

  // Create a new window for printing
  const printWindow = window.open('', '_blank');
  if (!printWindow) return;

  // Build HTML content
  const headers = columns.map((col) => `<th>${escapeHtml(col.label)}</th>`).join('');
  const rows = data
    .map(
      (row) =>
        `<tr>${columns
          .map((col) => `<td>${escapeHtml(row[col.key])}</td>`)
          .join('')}</tr>`
    )
    .join('');

  const htmlContent = `
    <!DOCTYPE html>
    <html>
      <head>
        <title>${title}</title>
        <style>
          body {
            font-family: Arial, sans-serif;
            direction: rtl;
            padding: 20px;
          }
          h1 {
            text-align: center;
            color: #333;
          }
          .date {
            text-align: center;
            color: #666;
            margin-bottom: 20px;
          }
          table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 20px;
          }
          th, td {
            border: 1px solid #ddd;
            padding: 12px;
            text-align: right;
          }
          th {
            background-color: #3b82f6;
            color: white;
            font-weight: bold;
          }
          tr:nth-child(even) {
            background-color: #f5f7fa;
          }
          @media print {
            body {
              padding: 0;
            }
          }
        </style>
      </head>
      <body>
        <h1>${title}</h1>
        <div class="date">تاريخ الطباعة: ${new Date().toLocaleDateString('ar-EG')}</div>
        <table>
          <thead>
            <tr>${headers}</tr>
          </thead>
          <tbody>
            ${rows}
          </tbody>
        </table>
      </body>
    </html>
  `;

  printWindow.document.write(htmlContent);
  printWindow.document.close();
  printWindow.focus();
  printWindow.print();
  printWindow.close();
};

type DataLayerEvent = Record<string, unknown>;

export type GtmEcommerceItem = {
  item_id: string;
  item_name?: string;
  item_category?: string;
  price?: number;
  quantity?: number;
};

const DEFAULT_DATA_LAYER = "dataLayer";
const SCRIPT_ATTR = "data-gtm-id";
const NOSCRIPT_ATTR = "data-gtm-noscript";

const ensureDataLayer = (name: string = DEFAULT_DATA_LAYER): DataLayerEvent[] => {
  if (typeof window === "undefined") return [];
  const win = window as any;
  if (!win[name]) {
    win[name] = [];
  }
  return win[name];
};

const buildGtmScriptSrc = (containerId: string, dataLayerName: string) => {
  const dl = dataLayerName !== DEFAULT_DATA_LAYER ? `&l=${dataLayerName}` : "";
  return `https://www.googletagmanager.com/gtm.js?id=${encodeURIComponent(containerId)}${dl}`;
};

export const createGtmEventId = (): string => {
  return `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
};

export const loadGtm = (containerId: string, dataLayerName: string = DEFAULT_DATA_LAYER): void => {
  if (typeof document === "undefined" || !containerId) return;

  const existingScript = document.querySelector(
    `script[${SCRIPT_ATTR}="${containerId}"]`,
  );
  if (existingScript) {
    return;
  }

  const dataLayer = ensureDataLayer(dataLayerName);
  dataLayer.push({ "gtm.start": Date.now(), event: "gtm.js" });

  const script = document.createElement("script");
  script.async = true;
  script.src = buildGtmScriptSrc(containerId, dataLayerName);
  script.setAttribute(SCRIPT_ATTR, containerId);
  const firstScript = document.getElementsByTagName("script")[0];
  if (firstScript?.parentNode) {
    firstScript.parentNode.insertBefore(script, firstScript);
  } else {
    document.head.appendChild(script);
  }

  const existingNoScript = document.querySelector(
    `noscript[${NOSCRIPT_ATTR}="${containerId}"]`,
  );
  if (!existingNoScript && document.body) {
    const noScript = document.createElement("noscript");
    noScript.setAttribute(NOSCRIPT_ATTR, containerId);
    const iframe = document.createElement("iframe");
    iframe.src = `https://www.googletagmanager.com/ns.html?id=${encodeURIComponent(containerId)}`;
    iframe.height = "0";
    iframe.width = "0";
    iframe.style.display = "none";
    iframe.style.visibility = "hidden";
    noScript.appendChild(iframe);
    document.body.prepend(noScript);
  }
};

export const pushGtmEvent = (
  eventName: string,
  payload: Record<string, unknown> = {},
  dataLayerName: string = DEFAULT_DATA_LAYER,
): void => {
  if (typeof window === "undefined" || !eventName) return;
  const dataLayer = ensureDataLayer(dataLayerName);
  dataLayer.push({ event: eventName, ...payload });
};

export const pushGtmEcommerceEvent = (
  eventName: string,
  params: {
    items: GtmEcommerceItem[];
    value?: number;
    currency?: string;
    transaction_id?: string;
    event_id?: string;
  },
  dataLayerName: string = DEFAULT_DATA_LAYER,
): void => {
  const payload: Record<string, unknown> = {
    event_id: params.event_id,
    ecommerce: {
      items: params.items,
    },
  };

  if (params.currency) {
    (payload.ecommerce as Record<string, unknown>).currency = params.currency;
  }
  if (typeof params.value === "number") {
    (payload.ecommerce as Record<string, unknown>).value = params.value;
  }
  if (params.transaction_id) {
    (payload.ecommerce as Record<string, unknown>).transaction_id = params.transaction_id;
  }

  pushGtmEvent(eventName, payload, dataLayerName);
};

/**
 * 🔍 HR Frontend Validation Utilities
 * مكتبة التحقق من صحة البيانات في واجهة نظام الموارد البشرية
 */

export interface ValidationError {
  field: string;
  message: string;
}

export interface ValidationResult {
  isValid: boolean;
  errors: ValidationError[];
}

/**
 * التحقق من البريد الإلكتروني
 */
export const validateEmail = (email: string): boolean => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

/**
 * التحقق من رقم الهاتف المصري
 */
export const validateEgyptianPhone = (phone: string): boolean => {
  const phoneRegex = /^(01)[0-9]{9}$/;
  return phoneRegex.test(phone.replace(/[\s-]/g, ""));
};

/**
 * التحقق من رقم الهوية المصري
 */
export const validateNationalId = (nationalId: string): boolean => {
  const nationalIdRegex = /^[0-9]{14}$/;
  return nationalIdRegex.test(nationalId);
};

/**
 * التحقق من صحة بيانات الموظف
 */
export const validateEmployeeData = (data: any): ValidationResult => {
  const errors: ValidationError[] = [];

  // الاسم الأول
  if (!data.firstName || data.firstName.trim().length < 2) {
    errors.push({
      field: "firstName",
      message: "الاسم الأول يجب أن يكون على الأقل حرفين",
    });
  }
  if (data.firstName && data.firstName.length > 50) {
    errors.push({
      field: "firstName",
      message: "الاسم الأول يجب ألا يزيد عن 50 حرف",
    });
  }

  // الاسم الأخير
  if (!data.lastName || data.lastName.trim().length < 2) {
    errors.push({
      field: "lastName",
      message: "الاسم الأخير يجب أن يكون على الأقل حرفين",
    });
  }
  if (data.lastName && data.lastName.length > 50) {
    errors.push({
      field: "lastName",
      message: "الاسم الأخير يجب ألا يزيد عن 50 حرف",
    });
  }

  // البريد الإلكتروني
  if (data.email && !validateEmail(data.email)) {
    errors.push({
      field: "email",
      message: "البريد الإلكتروني غير صحيح",
    });
  }

  // رقم الهاتف
  if (data.phone && !validateEgyptianPhone(data.phone)) {
    errors.push({
      field: "phone",
      message: "رقم الهاتف غير صحيح (يجب أن يبدأ بـ 01 ويتكون من 11 رقم)",
    });
  }

  // تاريخ الميلاد
  if (data.dateOfBirth) {
    const birthDate = new Date(data.dateOfBirth);
    const today = new Date();
    const age = today.getFullYear() - birthDate.getFullYear();

    if (birthDate > today) {
      errors.push({
        field: "dateOfBirth",
        message: "تاريخ الميلاد لا يمكن أن يكون في المستقبل",
      });
    }
    if (age < 16) {
      errors.push({
        field: "dateOfBirth",
        message: "عمر الموظف يجب أن يكون 16 سنة على الأقل",
      });
    }
    if (age > 70) {
      errors.push({
        field: "dateOfBirth",
        message: "عمر الموظف يجب ألا يزيد عن 70 سنة",
      });
    }
  }

  // تاريخ التعيين
  if (data.hireDate) {
    const hireDate = new Date(data.hireDate);
    const today = new Date();

    if (hireDate > today) {
      errors.push({
        field: "hireDate",
        message: "تاريخ التعيين لا يمكن أن يكون في المستقبل",
      });
    }
  }

  // الراتب الأساسي
  if (data.baseSalary !== undefined && data.baseSalary !== "") {
    const salary = parseFloat(data.baseSalary);
    if (isNaN(salary) || salary < 0) {
      errors.push({
        field: "baseSalary",
        message: "الراتب الأساسي يجب أن يكون رقماً موجباً",
      });
    }
    if (salary > 1000000) {
      errors.push({
        field: "baseSalary",
        message: "الراتب الأساسي يبدو غير منطقي (أكثر من مليون)",
      });
    }
  }

  // رقم الهوية
  if (data.nationalId && !validateNationalId(data.nationalId)) {
    errors.push({
      field: "nationalId",
      message: "رقم الهوية يجب أن يتكون من 14 رقم",
    });
  }

  // كلمة المرور (مطلوبة)
  if (!data.password || data.password.trim().length === 0) {
    errors.push({
      field: "password",
      message: "كلمة المرور مطلوبة",
    });
  } else if (data.password.length < 6) {
    errors.push({
      field: "password",
      message: "كلمة المرور يجب أن تكون 6 أحرف على الأقل",
    });
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * التحقق من صحة بيانات الإجازة
 */
export const validateLeaveData = (data: any): ValidationResult => {
  const errors: ValidationError[] = [];

  // نوع الإجازة
  if (!data.type) {
    errors.push({
      field: "type",
      message: "نوع الإجازة مطلوب",
    });
  }

  // تاريخ البداية
  if (!data.startDate) {
    errors.push({
      field: "startDate",
      message: "تاريخ بداية الإجازة مطلوب",
    });
  }

  // تاريخ النهاية
  if (!data.endDate) {
    errors.push({
      field: "endDate",
      message: "تاريخ نهاية الإجازة مطلوب",
    });
  }

  // التحقق من أن تاريخ النهاية بعد تاريخ البداية
  if (data.startDate && data.endDate) {
    const startDate = new Date(data.startDate);
    const endDate = new Date(data.endDate);

    if (endDate < startDate) {
      errors.push({
        field: "endDate",
        message: "تاريخ النهاية يجب أن يكون بعد تاريخ البداية",
      });
    }

    const daysDiff =
      (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24);
    if (daysDiff > 365) {
      errors.push({
        field: "endDate",
        message: "مدة الإجازة طويلة جداً (أكثر من سنة)",
      });
    }
  }

  // السبب (مطلوب لبعض أنواع الإجازات)
  if (["SICK", "EMERGENCY", "OTHER"].includes(data.type) && !data.reason) {
    errors.push({
      field: "reason",
      message: "السبب مطلوب لهذا النوع من الإجازات",
    });
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * التحقق من صحة بيانات القسم
 */
export const validateDepartmentData = (data: any): ValidationResult => {
  const errors: ValidationError[] = [];

  if (!data.name || data.name.trim().length < 2) {
    errors.push({
      field: "name",
      message: "اسم القسم يجب أن يكون على الأقل حرفين",
    });
  }

  if (data.name && data.name.length > 100) {
    errors.push({
      field: "name",
      message: "اسم القسم يجب ألا يزيد عن 100 حرف",
    });
  }

  if (data.color && !/^#[0-9A-F]{6}$/i.test(data.color)) {
    errors.push({
      field: "color",
      message: "لون القسم يجب أن يكون بصيغة HEX صحيحة (مثل #FF5733)",
    });
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * التحقق من صحة بيانات الحضور اليدوي
 */
export const validateManualAttendanceData = (data: any): ValidationResult => {
  const errors: ValidationError[] = [];

  if (!data.date) {
    errors.push({
      field: "date",
      message: "التاريخ مطلوب",
    });
  }

  if (!data.employeeId) {
    errors.push({
      field: "employeeId",
      message: "الموظف مطلوب",
    });
  }

  if (data.checkIn && data.checkOut) {
    const checkIn = new Date(data.checkIn);
    const checkOut = new Date(data.checkOut);

    if (checkOut <= checkIn) {
      errors.push({
        field: "checkOut",
        message: "وقت الانصراف يجب أن يكون بعد وقت الحضور",
      });
    }

    const workHours = (checkOut.getTime() - checkIn.getTime()) / 3600000;
    if (workHours > 24) {
      errors.push({
        field: "checkOut",
        message: "ساعات العمل غير منطقية (أكثر من 24 ساعة)",
      });
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * عرض رسائل الأخطاء
 */
export const getErrorMessage = (
  errors: ValidationError[],
  field: string,
